import { Effect, Schema } from "effect"
import type { HttpClientResponse } from "effect/http"
import type { Status } from "../generation.js"
import { Media } from "../media.js"
import { MediaProtocol } from "../route/media-protocol.js"
import { MediaRoute } from "../route/media.js"
import { mergeJsonRecords, type OpenString } from "../schema/index.js"
import { TranscriptionModel, TranscriptionResponse, type TranscriptionRequestFor } from "../transcription.js"
import { ProviderShared, optionalNull } from "./shared.js"
import { MediaInput } from "./utils/media-input.js"

const route = MediaProtocol.identity({ id: "assemblyai-transcription", name: "AssemblyAI", provider: "assemblyai" })
export const DEFAULT_BASE_URL = "https://api.assemblyai.com"
export const PATH = "/v2/transcript"
export const UPLOAD_PATH = "/v2/upload"

// ---------------------------------------------------------------------------
// 1. Public model input
// ---------------------------------------------------------------------------

export type AssemblyAITranscriptionOptions = {
  readonly keyterms_prompt?: ReadonlyArray<string>
  readonly punctuate?: boolean
  readonly format_text?: boolean
  readonly disfluencies?: boolean
  readonly filter_profanity?: boolean
  readonly temperature?: number
  readonly speaker_options?: { readonly min_speakers_expected?: number; readonly max_speakers_expected?: number }
  readonly language_detection_options?: {
    readonly expected_languages?: ReadonlyArray<string>
    readonly fallback_language?: string
    readonly code_switching?: boolean
  }
  readonly speech_models?: ReadonlyArray<OpenString<"universal-3-5-pro" | "universal-2">>
} & Record<string, unknown>

export type Request = TranscriptionRequestFor<AssemblyAITranscriptionOptions>

// ---------------------------------------------------------------------------
// 2. Token and response schemas
// ---------------------------------------------------------------------------

export const Token = Schema.Struct({ transcriptID: Schema.String })
export type Token = Schema.Schema.Type<typeof Token>

const Upload = Schema.Struct({ upload_url: Schema.String })

/** Word and utterance times are milliseconds. */
const Transcript = Schema.Struct({
  id: Schema.String,
  status: Schema.String,
  text: optionalNull(Schema.String),
  words: optionalNull(
    Schema.Array(
      Schema.Struct({
        text: Schema.String,
        start: Schema.Number,
        end: Schema.Number,
        confidence: optionalNull(Schema.Number),
        speaker: optionalNull(Schema.String),
      }),
    ),
  ),
  utterances: optionalNull(
    Schema.Array(
      Schema.Struct({
        text: Schema.String,
        start: Schema.Number,
        end: Schema.Number,
        speaker: optionalNull(Schema.String),
      }),
    ),
  ),
  language_code: optionalNull(Schema.String),
  audio_duration: optionalNull(Schema.Number),
  speech_model_used: optionalNull(Schema.String),
  error: optionalNull(Schema.String),
})

const STATUS = {
  queued: "queued",
  processing: "running",
  completed: "completed",
  error: "failed",
} as const satisfies Record<string, Status>

// ---------------------------------------------------------------------------
// 5. Request body construction
// ---------------------------------------------------------------------------

const decodeUpload = route.decodeJson(Upload)

/** `/v2/transcript` only takes a URL, so inline audio is uploaded to `/v2/upload` first. */
const prepare = Effect.fn("AssemblyAITranscription.prepare")(function* (request: Request, send: MediaProtocol.Send) {
  if (request.audio.source.type !== "bytes" && request.audio.source.type !== "base64") return request
  const audio = yield* MediaInput.inlineBytes(route.id, request.audio)
  const uploaded = yield* send(UPLOAD_PATH, MediaProtocol.binary(audio, "application/octet-stream")).pipe(
    Effect.flatMap(decodeUpload),
  )
  return { ...request, audio: Media.url(uploaded.value.upload_url, { mediaType: request.audio.mediaType }) }
})

const fromRequest = Effect.fn("AssemblyAITranscription.fromRequest")(function* (request: Request) {
  const audio = yield* ProviderShared.mediaReference(request.audio, route.provider, route.name)
  return MediaProtocol.json(
    mergeJsonRecords(
      {
        audio_url: audio.value,
        speech_models: [request.model.id],
        language_code: request.language,
        language_detection: request.language === undefined ? true : undefined,
        prompt: request.prompt,
        // Turn-level `utterances`, the only segments AssemblyAI returns, and `speakers_expected` require speaker labels.
        speaker_labels:
          request.diarize === true || request.timestamps === "segment" || request.speakers !== undefined
            ? true
            : undefined,
        speakers_expected: request.speakers,
      },
      request.providerOptions,
      request.http?.body,
    ) ?? {},
  )
})

// ---------------------------------------------------------------------------
// 6. Response decoding
// ---------------------------------------------------------------------------

const decodeTranscript = route.decodeJson(Transcript)

const decodeStart = Effect.fn("AssemblyAITranscription.decodeStart")(function* (
  response: HttpClientResponse.HttpClientResponse,
) {
  const output = yield* decodeTranscript(response)
  const status = yield* MediaProtocol.status(STATUS, output.value.status, output)
  return { token: { transcriptID: output.value.id }, snapshot: { id: output.value.id, status } }
})

const decodeStatus = Effect.fn("AssemblyAITranscription.decodeStatus")(function* (
  response: HttpClientResponse.HttpClientResponse,
  context: MediaProtocol.PollContext<Token>,
) {
  const output = yield* decodeTranscript(response)
  const status = yield* MediaProtocol.status(STATUS, output.value.status, output)
  return { id: context.token.transcriptID, status }
})

const seconds = (milliseconds: number) => milliseconds / 1000

const decodeResult = Effect.fn("AssemblyAITranscription.decodeResult")(function* (
  response: HttpClientResponse.HttpClientResponse,
  context: MediaProtocol.PollContext<Token>,
) {
  const output = yield* decodeTranscript(response)
  const transcript = output.value
  const status = yield* MediaProtocol.status(STATUS, transcript.status, output)
  const error = transcript.error ?? undefined
  if (status === "failed")
    return yield* output.ended("failed", `${route.name} transcription failed${error === undefined ? "" : `: ${error}`}`)
  if (status !== "completed") return yield* output.pending(context.token.transcriptID)
  const duration = transcript.audio_duration ?? undefined
  return new TranscriptionResponse({
    text: transcript.text ?? "",
    segments: transcript.utterances?.map((utterance) => ({
      text: utterance.text,
      startSeconds: seconds(utterance.start),
      endSeconds: seconds(utterance.end),
      speaker: utterance.speaker ?? undefined,
    })),
    words: transcript.words?.map((word) => ({
      text: word.text,
      startSeconds: seconds(word.start),
      endSeconds: seconds(word.end),
      speaker: word.speaker ?? undefined,
      confidence: word.confidence ?? undefined,
    })),
    language: transcript.language_code?.toLowerCase(),
    durationSeconds: duration,
    usage: duration === undefined ? undefined : { type: "seconds", seconds: duration },
    providerMetadata: {
      assemblyai: { transcriptId: transcript.id, speechModel: transcript.speech_model_used ?? undefined },
    },
  })
})

// ---------------------------------------------------------------------------
// 7. Protocol and route
// ---------------------------------------------------------------------------

const transcriptPath = (token: Token) => `${PATH}/${token.transcriptID}`

export const protocol = MediaProtocol.queued<Request, TranscriptionResponse, Token>(route, {
  token: Token,
  start: { prepare, body: { from: fromRequest }, decode: decodeStart },
  status: { path: transcriptPath, decode: decodeStatus },
  result: { path: transcriptPath, decode: decodeResult },
})

export const model = (input: MediaRoute.ModelInput) =>
  TranscriptionModel.fromRoute<AssemblyAITranscriptionOptions, Token>(
    { protocol, baseURL: DEFAULT_BASE_URL, path: PATH },
    input,
  )

export const AssemblyAITranscription = {
  protocol,
  model,
} as const

import { Effect, Schema } from "effect"
import { Base64 } from "effect/encoding"
import { Route } from "../route/client.js"
import { Endpoint } from "../route/endpoint.js"
import { Protocol } from "../route/protocol.js"
import {
  AIError,
  LLMEvent,
  Usage,
  type CacheHint,
  type FinishReason,
  type FinishReasonDetails,
  type LLMRequest,
  type LanguageModel,
  type ProviderMetadata,
  type ReasoningPart,
  type ToolCallPart,
  type ToolDefinition,
  type ToolResultPart,
} from "../schema/index.js"
import { BedrockEventStream } from "./bedrock-event-stream.js"
import { classifyProviderFailure } from "../provider-error.js"
import { JsonObject, optionalArray, ProviderShared } from "./shared.js"
import { BedrockAuth } from "./utils/bedrock-auth.js"
import { BedrockCache } from "./utils/bedrock-cache.js"
import { BedrockMedia } from "./utils/bedrock-media.js"
import { supportsThinkingBlockBinding, THINKING_BINDING_BETA } from "./utils/claude-model.js"
import { Lifecycle } from "./utils/lifecycle.js"
import { MistralToolID } from "./utils/mistral-tool-id.js"
import { ToolStream } from "./utils/tool-stream.js"
import { concatBytes } from "../utils/bytes.js"

const ADAPTER = "bedrock-converse"

export type { Credentials as BedrockCredentials } from "./utils/bedrock-auth.js"

// =============================================================================
// Request Body Schema
// =============================================================================
const BedrockTextBlock = Schema.Struct({
  text: Schema.String,
})
type BedrockTextBlock = Schema.Schema.Type<typeof BedrockTextBlock>

const BedrockToolUseBlock = Schema.Struct({
  toolUse: Schema.Struct({
    toolUseId: Schema.String,
    name: Schema.String,
    input: Schema.Unknown,
  }),
})
type BedrockToolUseBlock = Schema.Schema.Type<typeof BedrockToolUseBlock>

const BedrockToolResultContentItem = Schema.Union([
  Schema.Struct({ text: Schema.String }),
  Schema.Struct({ json: Schema.Unknown }),
  BedrockMedia.ImageBlock,
  BedrockMedia.DocumentBlock,
])

const BedrockToolResultBlock = Schema.Struct({
  toolResult: Schema.Struct({
    toolUseId: Schema.String,
    content: Schema.Array(BedrockToolResultContentItem),
    status: Schema.optional(Schema.Literals(["success", "error"])),
  }),
})
type BedrockToolResultBlock = Schema.Schema.Type<typeof BedrockToolResultBlock>

const BedrockReasoningBlock = Schema.Struct({
  reasoningContent: Schema.Union([
    Schema.Struct({
      reasoningText: Schema.Struct({
        text: Schema.String,
        signature: Schema.optional(Schema.String),
      }),
    }),
    Schema.Struct({ redactedContent: Schema.String }),
  ]),
})

const BedrockUserBlock = Schema.Union([
  BedrockTextBlock,
  BedrockMedia.ImageBlock,
  BedrockMedia.DocumentBlock,
  BedrockToolResultBlock,
  BedrockCache.CachePointBlock,
])
type BedrockUserBlock = Schema.Schema.Type<typeof BedrockUserBlock>

const BedrockAssistantBlock = Schema.Union([
  BedrockTextBlock,
  BedrockReasoningBlock,
  BedrockToolUseBlock,
  BedrockCache.CachePointBlock,
])
type BedrockAssistantBlock = Schema.Schema.Type<typeof BedrockAssistantBlock>

const BedrockMessage = Schema.Union([
  Schema.Struct({ role: Schema.Literal("user"), content: Schema.Array(BedrockUserBlock) }),
  Schema.Struct({ role: Schema.Literal("assistant"), content: Schema.Array(BedrockAssistantBlock) }),
]).pipe(Schema.toTaggedUnion("role"))
type BedrockMessage = Schema.Schema.Type<typeof BedrockMessage>

const BedrockSystemBlock = Schema.Union([BedrockTextBlock, BedrockCache.CachePointBlock])
type BedrockSystemBlock = Schema.Schema.Type<typeof BedrockSystemBlock>

const BedrockToolSpec = Schema.Struct({
  toolSpec: Schema.Struct({
    name: Schema.String,
    description: Schema.optional(Schema.String),
    inputSchema: Schema.Struct({
      json: JsonObject,
    }),
  }),
})
type BedrockToolSpec = Schema.Schema.Type<typeof BedrockToolSpec>

const BedrockTool = Schema.Union([BedrockToolSpec, BedrockCache.CachePointBlock])
type BedrockTool = Schema.Schema.Type<typeof BedrockTool>

const BedrockToolChoice = Schema.Union([
  Schema.Struct({ auto: Schema.Struct({}) }),
  Schema.Struct({ any: Schema.Struct({}) }),
  Schema.Struct({ tool: Schema.Struct({ name: Schema.String }) }),
])

const BedrockBodyFields = {
  modelId: Schema.String,
  messages: Schema.Array(BedrockMessage),
  system: optionalArray(BedrockSystemBlock),
  inferenceConfig: Schema.optional(
    Schema.Struct({
      maxTokens: Schema.optional(Schema.Number),
      temperature: Schema.optional(Schema.Number),
      topP: Schema.optional(Schema.Number),
      stopSequences: optionalArray(Schema.String),
    }),
  ),
  toolConfig: Schema.optional(
    Schema.Struct({
      tools: Schema.Array(BedrockTool),
      toolChoice: Schema.optional(BedrockToolChoice),
    }),
  ),
  additionalModelRequestFields: Schema.optional(JsonObject),
}
const BedrockConverseBody = Schema.Struct(BedrockBodyFields)
export type BedrockConverseBody = Schema.Schema.Type<typeof BedrockConverseBody>

const BedrockUsageSchema = Schema.Struct({
  inputTokens: Schema.optional(Schema.Number),
  outputTokens: Schema.optional(Schema.Number),
  totalTokens: Schema.optional(Schema.Number),
  cacheReadInputTokens: Schema.optional(Schema.Number),
  cacheWriteInputTokens: Schema.optional(Schema.Number),
})
type BedrockUsageSchema = Schema.Schema.Type<typeof BedrockUsageSchema>

const BedrockStreamException = Schema.Struct({
  message: Schema.optional(Schema.String),
  originalMessage: Schema.optional(Schema.String),
  originalStatusCode: Schema.optional(Schema.Number),
})

// Streaming event shape — the AWS event stream wraps each JSON payload by its
// `:event-type` header (e.g. `messageStart`, `contentBlockDelta`). We
// reconstruct that wrapping in `decodeFrames` below so the event schema can
// stay a plain discriminated record.
const BedrockEvent = Schema.Struct({
  messageStart: Schema.optional(Schema.Struct({ role: Schema.String })),
  contentBlockStart: Schema.optional(
    Schema.Struct({
      contentBlockIndex: Schema.Number,
      start: Schema.optional(
        Schema.Struct({
          toolUse: Schema.optional(Schema.Struct({ toolUseId: Schema.String, name: Schema.String })),
        }),
      ),
    }),
  ),
  contentBlockDelta: Schema.optional(
    Schema.Struct({
      contentBlockIndex: Schema.Number,
      delta: Schema.optional(
        Schema.Struct({
          text: Schema.optional(Schema.String),
          toolUse: Schema.optional(Schema.Struct({ input: Schema.String })),
          reasoningContent: Schema.optional(
            Schema.Struct({
              text: Schema.optional(Schema.String),
              signature: Schema.optional(Schema.String),
              // Blob fields in Bedrock's JSON event stream are base64 strings.
              redactedContent: Schema.optional(Schema.String),
              // Vercel's Bedrock provider exposes the same delta under
              // Anthropic's shorter `data` spelling.
              data: Schema.optional(Schema.String),
            }),
          ),
        }),
      ),
    }),
  ),
  contentBlockStop: Schema.optional(Schema.Struct({ contentBlockIndex: Schema.Number })),
  messageStop: Schema.optional(
    Schema.Struct({
      stopReason: Schema.String,
      additionalModelResponseFields: Schema.optional(Schema.Unknown),
    }),
  ),
  metadata: Schema.optional(
    Schema.Struct({
      usage: Schema.optional(BedrockUsageSchema),
      metrics: Schema.optional(Schema.Unknown),
    }),
  ),
  exception: Schema.optional(Schema.Struct({ type: Schema.String, details: BedrockStreamException })),
})
type BedrockEvent = Schema.Schema.Type<typeof BedrockEvent>

// =============================================================================
// Request Lowering
// =============================================================================
const lowerToolSpec = (tool: ToolDefinition): BedrockToolSpec => ({
  toolSpec: {
    name: tool.name,
    ...(tool.description.trim().length > 0 ? { description: tool.description } : {}),
    inputSchema: { json: tool.inputSchema },
  },
})

const lowerTools = (breakpoints: BedrockCache.Breakpoints, tools: ReadonlyArray<ToolDefinition>): BedrockTool[] => {
  const result: BedrockTool[] = []
  for (const tool of tools) {
    result.push(lowerToolSpec(tool))
    const cachePoint = BedrockCache.block(breakpoints, tool.cache)
    if (cachePoint) result.push(cachePoint)
  }
  return result
}

const textWithCache = (
  breakpoints: BedrockCache.Breakpoints,
  text: string,
  cache: CacheHint | undefined,
): Array<BedrockTextBlock | BedrockCache.CachePointBlock> => {
  const cachePoint = BedrockCache.block(breakpoints, cache)
  return cachePoint ? [{ text }, cachePoint] : [{ text }]
}

const lowerToolChoice = (toolChoice: NonNullable<LLMRequest["toolChoice"]>) =>
  ProviderShared.matchToolChoice("Bedrock Converse", toolChoice, {
    auto: () => ({ auto: {} }) as const,
    none: () => undefined,
    required: () => ({ any: {} }) as const,
    tool: (name) => ({ tool: { name } }) as const,
  })

const providerMetadata = (key: string, metadata: Record<string, unknown>): ProviderMetadata => ({ [key]: metadata })

const reasoningSignature = (part: ReasoningPart, providerMetadataKey: string) => {
  const metadata = part.providerMetadata?.[providerMetadataKey]
  if (part.encrypted !== undefined) return part.encrypted
  if (ProviderShared.isRecord(metadata) && typeof metadata.signature === "string") return metadata.signature
}

const reasoningRedactedData = (part: ReasoningPart, providerMetadataKey: string) => {
  const metadata = part.providerMetadata?.[providerMetadataKey]
  if (ProviderShared.isRecord(metadata) && typeof metadata.redactedData === "string") return metadata.redactedData
}

const removeEmptyToolInputKeys = (input: unknown): unknown => {
  if (Array.isArray(input)) return input.map(removeEmptyToolInputKeys)
  if (!ProviderShared.isRecord(input)) return input
  return Object.fromEntries(
    Object.entries(input).flatMap(([key, value]) => (key === "" ? [] : [[key, removeEmptyToolInputKeys(value)]])),
  )
}

const lowerToolCall = (part: ToolCallPart, normalizeID: (id: string) => string): BedrockToolUseBlock => ({
  toolUse: {
    toolUseId: normalizeID(part.id),
    // Models can emit names that Converse rejects when replayed in history.
    name: part.name.replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 64) || "_",
    input: removeEmptyToolInputKeys(part.input),
  },
})

const lowerToolResultContent = Effect.fnUntraced(function* (
  part: ToolResultPart,
  documentNames: Set<string>,
) {
  if (part.result.type === "text" || part.result.type === "error")
    return [{ text: ProviderShared.toolResultText(part) }]
  if (part.result.type === "json") return [{ json: part.result.value }]

  const content: Array<Schema.Schema.Type<typeof BedrockToolResultContentItem>> = []
  for (const item of part.result.value) {
    if (item.type === "text") {
      content.push({ text: item.text })
      continue
    }
    const media = yield* BedrockMedia.lower(ProviderShared.toolFileMedia(item), documentNames)
    content.push(...media)
  }
  return content
})

const lowerToolResult = Effect.fnUntraced(function* (
  part: ToolResultPart,
  documentNames: Set<string>,
  normalizeID: (id: string) => string,
) {
  return {
    toolResult: {
      toolUseId: normalizeID(part.id),
      content: yield* lowerToolResultContent(part, documentNames),
      status: part.result.type === "error" ? "error" : "success",
    },
  } satisfies BedrockToolResultBlock
})

// Keep Claude and Nova tool-result images inline; put other models' images beside the result.
const keepToolImagesInline = (id: string) => id.includes("anthropic.claude-") || id.includes("amazon.nova-")

const lowerMessages = Effect.fnUntraced(function* (
  request: LLMRequest,
  breakpoints: BedrockCache.Breakpoints,
) {
  const messages: BedrockMessage[] = []
  const documentNames = new Set<string>()
  // Mistral can reject replay IDs even when they satisfy Converse's broader ID syntax.
  const normalizeID = request.model.id.includes("mistral.") ? MistralToolID.normalizer(request) : (id: string) => id
  const providerMetadataKey = request.model.route.providerMetadataKey ?? String(request.model.provider)
  const hoistImages = !keepToolImagesInline(request.model.id)
  // Bedrock expects parallel tool results before any images hoisted beside them.
  const pendingImages: BedrockMedia.ImageBlock[] = []
  const flushImages = () => {
    if (pendingImages.length === 0) return
    const previous = messages.at(-1)
    if (previous?.role === "user")
      messages[messages.length - 1] = { role: "user", content: [...previous.content, ...pendingImages] }
    pendingImages.length = 0
  }

  for (const message of request.messages) {
    if (message.role !== "tool") flushImages()
    if (message.role === "system") {
      const part = yield* ProviderShared.wrappedSystemUpdate("Bedrock Converse", message)
      const content = textWithCache(breakpoints, part.text, part.cache)
      const previous = messages.at(-1)
      if (previous?.role === "user")
        messages[messages.length - 1] = { role: "user", content: [...previous.content, ...content] }
      else messages.push({ role: "user", content })
      continue
    }

    if (message.role === "user") {
      const content: BedrockUserBlock[] = []
      for (const part of message.content) {
        if (!ProviderShared.supportsContent(part, ["text", "media"]))
          return yield* ProviderShared.unsupportedContent("Bedrock Converse", "user", ["text", "media"])
        if (part.type === "text") {
          content.push(...textWithCache(breakpoints, part.text, part.cache))
          continue
        }
        if (part.type === "media") {
          content.push(...(yield* BedrockMedia.lower(part, documentNames)))
          continue
        }
      }
      const previous = messages.at(-1)
      if (previous?.role === "user")
        messages[messages.length - 1] = { role: "user", content: [...previous.content, ...content] }
      else messages.push({ role: "user", content })
      continue
    }

    if (message.role === "assistant") {
      const content: BedrockAssistantBlock[] = []
      for (const part of message.content) {
        if (!ProviderShared.supportsContent(part, ["text", "reasoning", "tool-call"]))
          return yield* ProviderShared.unsupportedContent("Bedrock Converse", "assistant", [
            "text",
            "reasoning",
            "tool-call",
          ])
        if (part.type === "text") {
          content.push(...textWithCache(breakpoints, part.text, part.cache))
          continue
        }
        if (part.type === "reasoning") {
          const signature = reasoningSignature(part, providerMetadataKey)
          const redactedData = reasoningRedactedData(part, providerMetadataKey)
          if (signature === undefined && redactedData !== undefined) {
            content.push({ reasoningContent: { redactedContent: redactedData } })
            continue
          }
          if (signature === undefined || signature.trim().length === 0) {
            // Interrupted streams and model switches can leave unsigned reasoning.
            // Preserve readable history as text rather than replay invalid reasoningContent.
            if (part.text.trim().length > 0) content.push(...textWithCache(breakpoints, part.text, part.cache))
            continue
          }
          content.push({ reasoningContent: { reasoningText: { text: part.text, signature } } })
          continue
        }
        if (part.type === "tool-call") {
          content.push(lowerToolCall(part, normalizeID))
          continue
        }
      }
      if (content.length > 0) messages.push({ role: "assistant", content })
      continue
    }

    const content: BedrockUserBlock[] = []
    for (const part of message.content) {
      if (!ProviderShared.supportsContent(part, ["tool-result"]))
        return yield* ProviderShared.unsupportedContent("Bedrock Converse", "tool", ["tool-result"])
      const result = yield* lowerToolResult(part, documentNames, normalizeID)
      const images: BedrockMedia.ImageBlock[] = hoistImages
        ? result.toolResult.content.filter((item) => "image" in item)
        : []
      const nonImageContent = result.toolResult.content.filter((item) => !("image" in item))
      content.push(
        images.length === 0
          ? result
          : {
              toolResult: {
                ...result.toolResult,
                content: nonImageContent.length > 0 ? nonImageContent : [{ text: "See attached image." }],
              },
            },
      )
      pendingImages.push(...images)
      const cachePoint = BedrockCache.block(breakpoints, part.cache)
      if (cachePoint) content.push(cachePoint)
    }
    const previous = messages.at(-1)
    if (previous?.role === "user")
      messages[messages.length - 1] = { role: "user", content: [...previous.content, ...content] }
    else messages.push({ role: "user", content })
  }

  flushImages()
  return messages
})

// System prompts share the cache-point convention: emit the text block, then
// optionally a positional `cachePoint` marker.
const lowerSystem = (breakpoints: BedrockCache.Breakpoints, system: ReadonlyArray<LLMRequest["system"][number]>) => {
  const content = system
    .filter((part) => part.text.length > 0)
    .flatMap((part) => textWithCache(breakpoints, part.text, part.cache))
  return content.length === 0 ? undefined : content
}

// Nova 2 rejects `maxTokens` at high reasoning effort, where its output can exceed the field's maximum. Other models
// that take `reasoningConfig`, such as Grok on Bedrock, accept it.
const isNova2 = (model: LanguageModel) => /\bamazon\.nova-2-/.test(model.id)
const isHighReasoningEffort = Schema.is(
  Schema.Struct({
    additionalModelRequestFields: Schema.Struct({
      reasoningConfig: Schema.Struct({ maxReasoningEffort: Schema.Literal("high") }),
    }),
  }),
)

const Options = Schema.Struct({
  thinking: Schema.optional(Schema.Struct({ type: Schema.Literal("enabled"), budgetTokens: Schema.Number })),
})
export type OptionsInput = typeof Options.Type
const decodeOptions = ProviderShared.validateWith(Schema.decodeUnknownEffect(Options))
// Claude on Bedrock requires the thinking budget below `maxTokens`, with a minimum of 1,024.
const MIN_THINKING_BUDGET = 1_024

const isThinkingDisabled = Schema.is(
  Schema.Struct({
    additionalModelRequestFields: Schema.Struct({
      thinking: Schema.Struct({ type: Schema.Literals(["disabled", "between_tools"]) }),
    }),
  }),
)

// Claude 5.1+ binds each thinking signature to the prefix above it. Ask Bedrock to drop the affected blocks instead of
// failing when that prefix changes. `http.body` overlays this field by field, so callers can still override it.
const applyThinkingBindingDefault = (request: LLMRequest, thinking: Readonly<Record<string, unknown>> | undefined) => {
  if (isThinkingDisabled(request.http?.body)) return thinking
  if (!supportsThinkingBlockBinding(request.model)) return thinking
  return {
    ...(thinking ?? { type: "adaptive" as const }),
    block_binding: { prefix_mismatch_behavior: "drop_block" },
  }
}

const fromRequest = Effect.fn("BedrockConverse.fromRequest")(function* (request: LLMRequest) {
  const toolChoice = request.toolChoice ? yield* lowerToolChoice(request.toolChoice) : undefined
  const flattened = ProviderShared.flattenToolRequest(request)
  const generation = request.generation
  const options = yield* decodeOptions(request.providerOptions ?? {})
  const maxTokens =
    isNova2(request.model) && isHighReasoningEffort(request.http?.body) ? undefined : generation?.maxTokens
  const thinking = applyThinkingBindingDefault(
    request,
    options.thinking === undefined
      ? undefined
      : {
          type: "enabled",
          budget_tokens: ProviderShared.fitThinkingBudget(
            options.thinking.budgetTokens,
            maxTokens,
            MIN_THINKING_BUDGET,
          ),
        },
  )
  // Bedrock-Claude shares Anthropic's 4-breakpoint cap. Spend the budget in
  // tools → system → messages order to favour the highest-impact prefixes.
  const breakpoints = BedrockCache.breakpoints(request.model)
  const toolConfig = (() => {
    if (flattened.tools.length === 0) return undefined
    return {
      tools: lowerTools(breakpoints, flattened.tools),
      // Converse has no native "none". Keep definitions stable for prompt
      // caching and omit only the unsupported choice.
      toolChoice,
    }
  })()
  const system = lowerSystem(breakpoints, request.system)
  const messages = yield* lowerMessages(flattened.request, breakpoints)
  if (breakpoints.dropped > 0) {
    yield* Effect.logWarning(
      `Bedrock Converse: dropped ${breakpoints.dropped} cache breakpoint(s); the API allows at most ${BedrockCache.BEDROCK_BREAKPOINT_CAP} per request.`,
    )
  }
  const inferenceConfig = (() => {
    if (
      maxTokens === undefined &&
      generation?.temperature === undefined &&
      generation?.topP === undefined &&
      (generation?.stop === undefined || generation.stop.length === 0)
    )
      return undefined
    return {
      maxTokens,
      temperature: generation?.temperature,
      topP: generation?.topP,
      stopSequences: generation?.stop,
    }
  })()
  return {
    modelId: request.model.id,
    messages,
    system,
    inferenceConfig,
    toolConfig,
    // Converse's base inferenceConfig has no topK or thinking; Anthropic/Nova accept them
    // as model-specific fields, so they go through additionalModelRequestFields.
    additionalModelRequestFields:
      generation?.topK === undefined && thinking === undefined
        ? undefined
        : {
            ...(generation?.topK === undefined ? {} : { top_k: generation.topK }),
            ...(thinking === undefined ? {} : { thinking }),
            // Converse takes Anthropic betas in the body, and Bedrock rejects `block_binding` without this one.
            ...(thinking?.block_binding === undefined ? {} : { anthropic_beta: [THINKING_BINDING_BETA] }),
          },
  }
})

// =============================================================================
// Stream Parsing
// =============================================================================
const mapFinishReason = (reason: string): FinishReason => {
  if (reason === "end_turn" || reason === "stop_sequence") return "stop"
  if (reason === "max_tokens" || reason === "model_context_window_exceeded") return "length"
  if (reason === "tool_use") return "tool-calls"
  if (reason === "content_filtered" || reason === "guardrail_intervened") return "content-filter"
  return "unknown"
}

// AWS reports inputTokens separately from cache reads and writes.
// Bedrock does not break reasoning out of outputTokens for current models.
const mapUsage = (usage: BedrockUsageSchema | undefined, providerMetadataKey: string): Usage | undefined => {
  if (!usage) return undefined
  const inputTokens = ProviderShared.sumTokens(
    usage.inputTokens,
    usage.cacheReadInputTokens,
    usage.cacheWriteInputTokens,
  )
  return new Usage({
    inputTokens,
    outputTokens: usage.outputTokens,
    nonCachedInputTokens: usage.inputTokens,
    cacheReadInputTokens: usage.cacheReadInputTokens,
    cacheWriteInputTokens: usage.cacheWriteInputTokens,
    totalTokens: ProviderShared.totalTokens(inputTokens, usage.outputTokens, usage.totalTokens),
    providerMetadata: { [providerMetadataKey]: usage },
  })
}

interface ParserState {
  readonly providerMetadataKey: string
  readonly tools: ToolStream.State<number>
  // Bedrock splits the finish into `messageStop` (carries `stopReason`) and
  // `metadata` (carries usage). Hold both in state so `onHalt` can emit exactly
  // one finish after both chunks have had a chance to arrive.
  readonly finishReason: FinishReasonDetails | undefined
  readonly usage: Usage | undefined
  readonly hasToolCalls: boolean
  readonly lifecycle: Lifecycle.State
  readonly reasoningSignatures: Readonly<Record<number, string>>
  readonly reasoningRedactedContent: Readonly<Record<number, Uint8Array[]>>
}

const encodeRedactedContent = (chunks: ReadonlyArray<Uint8Array>) => Base64.encode(concatBytes(chunks))

const step = (state: ParserState, event: BedrockEvent) =>
  Effect.gen(function* () {
    if (event.contentBlockStart?.start?.toolUse) {
      const index = event.contentBlockStart.contentBlockIndex
      const events: LLMEvent[] = []
      const lifecycle = Lifecycle.stepStart(state.lifecycle, events)
      return [
        {
          ...state,
          lifecycle,
          tools: ToolStream.start(state.tools, index, {
            id: event.contentBlockStart.start.toolUse.toolUseId,
            name: event.contentBlockStart.start.toolUse.name,
          }),
        },
        [
          ...events,
          LLMEvent.toolInputStart({
            id: event.contentBlockStart.start.toolUse.toolUseId,
            name: event.contentBlockStart.start.toolUse.name,
          }),
        ],
      ] as const
    }

    if (event.contentBlockDelta?.delta?.text) {
      const events: LLMEvent[] = []
      return [
        {
          ...state,
          lifecycle: Lifecycle.textDelta(
            state.lifecycle,
            events,
            `text-${event.contentBlockDelta.contentBlockIndex}`,
            event.contentBlockDelta.delta.text,
          ),
        },
        events,
      ] as const
    }

    if (event.contentBlockDelta?.delta?.reasoningContent) {
      const index = event.contentBlockDelta.contentBlockIndex
      const reasoning = event.contentBlockDelta.delta.reasoningContent
      const events: LLMEvent[] = []
      const redactedChunk = yield* (() => {
        if (reasoning.redactedContent === undefined) return Effect.succeed(undefined)
        return Effect.fromResult(Base64.decode(reasoning.redactedContent)).pipe(
          Effect.mapError((cause) =>
            ProviderShared.eventError(
              ADAPTER,
              "Bedrock Converse reasoningContent.redactedContent contains invalid base64 data",
              undefined,
              cause,
            ),
          ),
        )
      })()
      const redactedChunks = state.reasoningRedactedContent[index] ?? []
      if (redactedChunk !== undefined) redactedChunks.push(redactedChunk)
      const metadata = (() => {
        if (reasoning.signature) return providerMetadata(state.providerMetadataKey, { signature: reasoning.signature })
        if (redactedChunk === undefined && reasoning.data !== undefined)
          return providerMetadata(state.providerMetadataKey, { redactedData: reasoning.data })
      })()
      const lifecycle = (() => {
        if (reasoning.text !== undefined || metadata !== undefined)
          return Lifecycle.reasoningDelta(state.lifecycle, events, `reasoning-${index}`, reasoning.text ?? "", metadata)
        if (redactedChunk !== undefined) return Lifecycle.reasoningStart(state.lifecycle, events, `reasoning-${index}`)
        return state.lifecycle
      })()
      const reasoningRedactedContent = (() => {
        if (redactedChunk !== undefined) return { ...state.reasoningRedactedContent, [index]: redactedChunks }
        if (reasoning.data === undefined) return state.reasoningRedactedContent
        return Object.fromEntries(
          Object.entries(state.reasoningRedactedContent).filter(([key]) => key !== String(index)),
        )
      })()
      const reasoningSignatures = (() => {
        if (!reasoning.signature) return state.reasoningSignatures
        return { ...state.reasoningSignatures, [index]: reasoning.signature }
      })()
      return [
        {
          ...state,
          lifecycle,
          reasoningSignatures,
          reasoningRedactedContent,
        },
        events,
      ] as const
    }

    if (event.contentBlockDelta?.delta?.toolUse) {
      // A delta for a block that is not open, whether it already stopped or never
      // started, has nothing to attach to and is dropped.
      const result = ToolStream.append(
        state.tools,
        event.contentBlockDelta.contentBlockIndex,
        event.contentBlockDelta.delta.toolUse.input,
      )
      if (!result) return [state, []] as const
      const events: LLMEvent[] = []
      const lifecycle = result.events.length ? Lifecycle.stepStart(state.lifecycle, events) : state.lifecycle
      events.push(...result.events)
      return [{ ...state, lifecycle, tools: result.tools }, events] as const
    }

    if (event.contentBlockStop) {
      const index = event.contentBlockStop.contentBlockIndex
      const result = yield* ToolStream.finish(ADAPTER, state.tools, index)
      const events: LLMEvent[] = []
      const resultEvents = result.events ?? []
      const lifecycle = (() => {
        if (resultEvents.length) return Lifecycle.stepStart(state.lifecycle, events)
        const metadata = (() => {
          const signature = state.reasoningSignatures[index]
          if (signature) return providerMetadata(state.providerMetadataKey, { signature })
          const redactedContent = state.reasoningRedactedContent[index]
          if (redactedContent)
            return providerMetadata(state.providerMetadataKey, {
              redactedData: encodeRedactedContent(redactedContent),
            })
        })()
        return Lifecycle.reasoningEnd(
          Lifecycle.textEnd(state.lifecycle, events, `text-${index}`),
          events,
          `reasoning-${index}`,
          metadata,
        )
      })()
      events.push(...resultEvents)
      return [
        {
          ...state,
          hasToolCalls:
            resultEvents.some((event) => LLMEvent.is.toolCall(event) || LLMEvent.is.toolInputError(event)) ||
            state.hasToolCalls,
          lifecycle,
          tools: result.tools,
          reasoningSignatures: Object.fromEntries(
            Object.entries(state.reasoningSignatures).filter(([key]) => key !== String(index)),
          ),
          reasoningRedactedContent: Object.fromEntries(
            Object.entries(state.reasoningRedactedContent).filter(([key]) => key !== String(index)),
          ),
        },
        events,
      ] as const
    }

    if (event.messageStop) {
      if (
        event.messageStop.stopReason === "malformed_model_output" ||
        event.messageStop.stopReason === "malformed_tool_use"
      )
        return yield* ProviderShared.eventError(
          ADAPTER,
          `Bedrock Converse stopped with ${event.messageStop.stopReason}`,
          ProviderShared.encodeJson(event),
        )
      return [
        {
          ...state,
          finishReason: {
            normalized: mapFinishReason(event.messageStop.stopReason),
            raw: event.messageStop.stopReason,
          },
        },
        [],
      ] as const
    }

    if (event.metadata) {
      const usage = mapUsage(event.metadata.usage, state.providerMetadataKey) ?? state.usage
      return [
        {
          ...state,
          usage,
        },
        [],
      ] as const
    }

    if (event.exception) {
      const message =
        event.exception.details.message ?? event.exception.details.originalMessage ?? "Bedrock Converse stream error"
      const body = ProviderShared.encodeJson(event)
      return yield* new AIError({
        reason: classifyProviderFailure({
          message,
          rawBody: body,
        }),
      })
    }

    return [state, []] as const
  })

const framing = BedrockEventStream.framing(ADAPTER)

const onHalt = (state: ParserState): ReadonlyArray<LLMEvent> => {
  if (!state.finishReason) return []
  const normalized = (() => {
    if (state.finishReason.normalized === "stop" && state.hasToolCalls) return "tool-calls"
    return state.finishReason.normalized
  })()
  const events: LLMEvent[] = []
  const lifecycle = Object.entries(state.reasoningRedactedContent).reduce((current, [index, chunks]) => {
    const signature = state.reasoningSignatures[Number(index)]
    return Lifecycle.reasoningEnd(
      current,
      events,
      `reasoning-${index}`,
      providerMetadata(
        state.providerMetadataKey,
        signature ? { signature } : { redactedData: encodeRedactedContent(chunks) },
      ),
    )
  }, state.lifecycle)
  Lifecycle.finish(lifecycle, events, {
    reason: {
      ...state.finishReason,
      normalized,
    },
    usage: state.usage,
  })
  return events
}

// =============================================================================
// Protocol And Bedrock Route
// =============================================================================
/**
 * The Bedrock Converse protocol — request body construction, body schema, and
 * the streaming-event state machine.
 */
export const protocol = Protocol.make({
  id: ADAPTER,
  body: {
    schema: BedrockConverseBody,
    from: fromRequest,
  },
  stream: {
    event: BedrockEvent,
    initial: (request) => ({
      providerMetadataKey: request.model.route.providerMetadataKey ?? String(request.model.provider),
      tools: ToolStream.empty<number>(),
      finishReason: undefined,
      usage: undefined,
      hasToolCalls: false,
      lifecycle: Lifecycle.initial(),
      reasoningSignatures: {},
      reasoningRedactedContent: {},
    }),
    step,
    onHalt: (state) => Effect.succeed(onHalt(state)),
  },
})

export const route = Route.make({
  id: ADAPTER,
  provider: "bedrock",
  providerMetadataKey: "bedrock",
  protocol,
  // Bedrock's URL embeds the region in the route endpoint host and the
  // validated modelId in the path. We read the validated body so the URL
  // matches the body that gets signed.
  endpoint: Endpoint.path<BedrockConverseBody>(
    ({ body }) => `/model/${encodeURIComponent(body.modelId)}/converse-stream`,
  ),
  auth: BedrockAuth.auth,
  framing,
})

export const sigV4Auth = BedrockAuth.sigV4

export * as BedrockConverse from "./bedrock-converse.js"

import { EventStreamCodec } from "@smithy/eventstream-codec"
import { fromUtf8, toUtf8 } from "@smithy/util-utf8"
import { Effect, Stream } from "effect"
import { Base64 } from "effect/encoding"
import { AIError, AIErrorReason, InvalidProviderOutputError } from "../schema/index.js"
import { Framing } from "../route/framing.js"
import { ProviderShared } from "./shared.js"

// Bedrock streams responses using the AWS event stream binary protocol — each
// frame is `[length:4][headers-length:4][prelude-crc:4][headers][payload][crc:4]`.
// We use `@smithy/eventstream-codec` to validate framing and CRCs, then
// reconstruct the JSON wrapping by `:event-type` so the chunk schema can match.
const eventCodec = new EventStreamCodec(toUtf8, fromUtf8)
const utf8 = new TextDecoder()

// Cursor-tracking buffer state. Bytes accumulate in `buffer`; `offset` is the
// read position. Reading by `subarray` is zero-copy. We only allocate a fresh
// buffer when a new network chunk arrives and we need to append.
interface FrameBufferState {
  readonly buffer: Uint8Array
  readonly offset: number
}

const initialFrameBuffer: FrameBufferState = { buffer: new Uint8Array(0), offset: 0 }

type FrameInput = { readonly _tag: "Chunk"; readonly bytes: Uint8Array } | { readonly _tag: "End" }

const endOfStream: FrameInput = { _tag: "End" }

const appendChunk = (state: FrameBufferState, chunk: Uint8Array): FrameBufferState => {
  const remaining = state.buffer.length - state.offset
  // Compact: drop the consumed prefix and append the new chunk in one alloc.
  // This bounds buffer growth to at most one network chunk past the live
  // window, regardless of stream length.
  const next = new Uint8Array(remaining + chunk.length)
  next.set(state.buffer.subarray(state.offset), 0)
  next.set(chunk, remaining)
  return { buffer: next, offset: 0 }
}

const consumeFrames = (route: string) => (state: FrameBufferState, input: FrameInput) =>
  Effect.gen(function* () {
    if (input._tag === "End") {
      const remaining = state.buffer.subarray(state.offset)
      if (remaining.length > 0)
        return yield* new AIError({
          reason: new InvalidProviderOutputError({
            route,
            classification: "incomplete-stream",
            message: `Incomplete Bedrock Converse event-stream frame: ${remaining.length} buffered bytes remain at end of stream`,
            body: Base64.encode(remaining),
          }),
        })
      return [state, []] as const
    }

    let cursor = appendChunk(state, input.bytes)
    const out: object[] = []
    while (cursor.buffer.length - cursor.offset >= 4) {
      const view = cursor.buffer.subarray(cursor.offset)
      const totalLength = new DataView(view.buffer, view.byteOffset, view.byteLength).getUint32(0, false)
      if (view.length < totalLength) break

      const decoded = yield* Effect.try({
        try: () => eventCodec.decode(view.subarray(0, totalLength)),
        catch: (error) =>
          ProviderShared.eventError(
            route,
            `Failed to decode Bedrock Converse event-stream frame: ${
              error instanceof Error ? error.message : String(error)
            }`,
            Base64.encode(view.subarray(0, totalLength)),
            error,
          ),
      })
      cursor = { buffer: cursor.buffer, offset: cursor.offset + totalLength }

      const payload = utf8.decode(decoded.body)
      const body = ProviderShared.encodeJson({ headers: decoded.headers, body: payload })
      const messageType = decoded.headers[":message-type"]?.value
      if (messageType === "error") {
        const code = decoded.headers[":error-code"]?.value
        const message = decoded.headers[":error-message"]?.value
        return yield* ProviderShared.eventError(
          route,
          [code, message].filter((value): value is string => typeof value === "string").join(": ") ||
            "Bedrock Converse event-stream error",
          body,
        )
      }
      const eventType =
        messageType === "event"
          ? decoded.headers[":event-type"]?.value
          : messageType === "exception"
            ? decoded.headers[":exception-type"]?.value
            : undefined
      if (typeof eventType !== "string") continue
      if (!payload) continue
      // The AWS event stream pads short payloads with a `p` field. Drop it
      // before handing the object to the chunk schema. JSON decode goes
      // through the shared Schema-driven codec to satisfy the package rule
      // against ad-hoc `JSON.parse` calls.
      const parsed = (yield* ProviderShared.parseJson(
        route,
        payload,
        "Failed to parse Bedrock Converse event-stream payload",
      ).pipe(
        Effect.mapError(
          (error) =>
            new AIError({
              reason: AIErrorReason.make({ ...error.reason, message: error.message, cause: error.reason.cause, body }),
            }),
        ),
      )) as Record<string, unknown>
      delete parsed.p
      out.push({
        ...(messageType === "exception"
          ? { exception: { type: eventType, details: parsed } }
          : { [eventType]: parsed }),
        rawBody: body,
      })
    }
    return [cursor, out] as const
  })

/**
 * AWS event-stream framing for Bedrock Converse. Each frame is decoded by
 * `@smithy/eventstream-codec` (length + header + payload + CRC) and rewrapped
 * under its `:event-type` header so the chunk schema can match the JSON
 * payload directly.
 */
export const framing = (route: string): Framing.Definition<object> => ({
  id: "aws-event-stream",
  body: (frame) => ("rawBody" in frame && typeof frame.rawBody === "string" ? frame.rawBody : undefined),
  frame: (bytes) =>
    bytes.pipe(
      Stream.map((bytes): FrameInput => ({ _tag: "Chunk", bytes })),
      Stream.concat(Stream.succeed(endOfStream)),
      Stream.mapAccumEffect(() => initialFrameBuffer, consumeFrames(route)),
    ),
})

export * as BedrockEventStream from "./bedrock-event-stream.js"

import { Effect, Schema } from "effect"
import type { HttpClientResponse } from "effect/http"
import type { Status } from "../generation.js"
import { ImageModel, ImageResponse, type ImageRequestFor } from "../image.js"
import { Media } from "../media.js"
import { MediaProtocol } from "../route/media-protocol.js"
import { MediaRoute } from "../route/media.js"
import { mergeJsonRecords } from "../schema/index.js"
import { ProviderShared, optionalNull } from "./shared.js"
import { MediaInput } from "./utils/media-input.js"

const route = MediaProtocol.identity({ id: "bfl-images", name: "Black Forest Labs", provider: "black-forest-labs" })
export const DEFAULT_BASE_URL = "https://api.bfl.ai"

// ---------------------------------------------------------------------------
// 1. Public model input
// ---------------------------------------------------------------------------

export type BlackForestLabsImageOptions = {
  readonly safety_tolerance?: number
  readonly prompt_upsampling?: boolean
  readonly disable_pup?: boolean
  readonly raw?: boolean
  readonly guidance?: number
  readonly steps?: number
} & Record<string, unknown>

export type Request = ImageRequestFor<BlackForestLabsImageOptions>

// ---------------------------------------------------------------------------
// 2. Token and response schemas
// ---------------------------------------------------------------------------

/**
 * Regional clusters answer on different hosts, so the returned `polling_url` is followed verbatim. BFL reports the
 * credit cost on submit, so it rides on the token; it is optional so tokens persisted before it existed still decode.
 */
export const Token = Schema.Struct({
  id: Schema.String,
  pollingURL: Schema.String,
  cost: Schema.optionalKey(Schema.Number),
})
export type Token = Schema.Schema.Type<typeof Token>

const StartResponse = Schema.Struct({
  id: Schema.String,
  polling_url: Schema.String,
  cost: optionalNull(Schema.Number),
})

const Result = Schema.Struct({
  id: Schema.String,
  status: Schema.String,
  result: optionalNull(
    Schema.StructWithRest(
      Schema.Struct({ sample: Schema.String, seed: optionalNull(Schema.Number), prompt: optionalNull(Schema.String) }),
      [Schema.Record(Schema.String, Schema.Unknown)],
    ),
  ),
  cost: optionalNull(Schema.Number),
})

const STATUS = {
  Pending: "running",
  Reasoning: "running",
  Generating: "running",
  Ready: "completed",
  Error: "failed",
  // Moderation is terminal; `decodeResult` reports it as a content-policy failure.
  "Content Moderated": "failed",
  "Request Moderated": "failed",
  "Task not found": "expired",
} as const satisfies Record<string, Status>

const isModerated = (status: string) => status === "Content Moderated" || status === "Request Moderated"

// ---------------------------------------------------------------------------
// 5. Request body construction
// ---------------------------------------------------------------------------

interface Capabilities {
  readonly sizing: "dimensions" | "aspectRatio" | "none"
  /** `input_image` numbers extra references `input_image_2`…; the other fields take one image. */
  readonly imageField: "input_image" | "image_prompt" | "image"
  readonly maxImages: number
  readonly mask: boolean
}

const capabilities = (model: string): Capabilities => {
  if (model.startsWith("flux-pro-1.0-fill")) return { sizing: "none", imageField: "image", maxImages: 1, mask: true }
  if (model.startsWith("flux-pro-1.0-expand")) return { sizing: "none", imageField: "image", maxImages: 1, mask: false }
  if (model.startsWith("flux-kontext"))
    return { sizing: "aspectRatio", imageField: "input_image", maxImages: 4, mask: false }
  if (model.startsWith("flux-pro-1.1-ultra"))
    return { sizing: "aspectRatio", imageField: "image_prompt", maxImages: 1, mask: false }
  if (model.startsWith("flux-pro-1.1") || model.startsWith("flux-dev"))
    return { sizing: "dimensions", imageField: "image_prompt", maxImages: 1, mask: false }
  if (model.startsWith("flux-2-klein"))
    return { sizing: "dimensions", imageField: "input_image", maxImages: 4, mask: false }
  return { sizing: "dimensions", imageField: "input_image", maxImages: 8, mask: false }
}

const validate = (request: Request, model: Capabilities) => {
  const id = request.model.id
  const images = request.images?.length ?? 0
  if (request.n !== undefined && request.n > 1)
    return Effect.fail(route.unsupported("media.n", `${id} generates one image per request; call it once per image`))
  if (request.size !== undefined && model.sizing !== "dimensions")
    return Effect.fail(route.unsupported("media.size", `${id} does not take size (width and height)`))
  if (request.aspectRatio !== undefined && model.sizing !== "aspectRatio")
    return Effect.fail(route.unsupported("media.aspectRatio", `${id} does not take aspectRatio`))
  if (images > model.maxImages)
    return Effect.fail(route.unsupported("media.images", `${id} takes at most ${model.maxImages} images`))
  if (request.mask !== undefined && !model.mask)
    return Effect.fail(route.unsupported("media.mask", `${id} does not inpaint; use flux-pro-1.0-fill`))
  return Effect.void
}

const imageInput = (asset: Media.Asset) => {
  const value = asset.inline()?.base64 ?? ProviderShared.mediaUrl(asset)
  if (value === undefined)
    return Effect.fail(ProviderShared.invalidRequest(`${route.name} accepts inline images or https URLs`))
  return Effect.succeed(value)
}

const fromRequest = Effect.fn("BlackForestLabsImages.fromRequest")(function* (request: Request) {
  const model = capabilities(request.model.id)
  yield* validate(request, model)
  const images = yield* Effect.forEach(request.images ?? [], imageInput)
  const fields = images.map((image, index) => [
    index === 0 ? model.imageField : `${model.imageField}_${index + 1}`,
    image,
  ])
  return MediaProtocol.json(
    mergeJsonRecords(
      {
        prompt: request.prompt,
        ...(request.size === undefined ? {} : MediaInput.dimensions(request.size)),
        aspect_ratio: request.aspectRatio,
        seed: request.seed,
        output_format: request.format,
        mask: request.mask === undefined ? undefined : yield* imageInput(request.mask),
        ...Object.fromEntries(fields),
      },
      request.providerOptions,
      request.http?.body,
    ) ?? {},
  )
})

// ---------------------------------------------------------------------------
// 6. Response decoding
// ---------------------------------------------------------------------------

const decodeStart = route.decodeStarted(StartResponse, (value) => ({
  token: {
    id: value.id,
    pollingURL: value.polling_url,
    ...(value.cost === undefined || value.cost === null ? {} : { cost: value.cost }),
  },
  snapshot: { id: value.id, status: "queued" },
}))

const decodeDocument = route.decodeJson(Result)

const decodeStatus = Effect.fn("BlackForestLabsImages.decodeStatus")(function* (
  response: HttpClientResponse.HttpClientResponse,
  context: MediaProtocol.PollContext<Token>,
) {
  const output = yield* decodeDocument(response)
  return { id: context.token.id, status: yield* MediaProtocol.status(STATUS, output.value.status, output) }
})

const decodeResult = Effect.fn("BlackForestLabsImages.decodeResult")(function* (
  response: HttpClientResponse.HttpClientResponse,
  context: MediaProtocol.PollContext<Token>,
) {
  const output = yield* decodeDocument(response)
  const document = output.value
  const status = yield* MediaProtocol.status(STATUS, document.status, output)
  if (isModerated(document.status)) return yield* output.contentPolicy(`${route.name} moderated the generation`)
  if (status === "failed" || status === "expired")
    return yield* output.ended(status, `${route.name} generation ${context.token.id} ended with ${document.status}`)
  if (status !== "completed") return yield* output.pending(context.token.id)
  if (document.result === undefined || document.result === null)
    return yield* output.invalid(`${route.name} generation ${context.token.id} has no result`)
  const { sample, seed, prompt, ...rest } = document.result
  // A settled `cost` on the result supersedes the submit-time cost carried on the token.
  const cost = document.cost ?? context.token.cost
  return new ImageResponse({
    // `sample` is a signed URL that expires 10 minutes after the result is ready, so it is downloaded now.
    images: [yield* context.materialize(Media.url(sample))],
    usage: cost === undefined ? undefined : { type: "credits", credits: cost },
    providerMetadata: {
      bfl: { id: context.token.id, seed: seed ?? undefined, prompt: prompt ?? undefined, ...rest },
    },
  })
})

// ---------------------------------------------------------------------------
// 7. Protocol and route
// ---------------------------------------------------------------------------

export const protocol = MediaProtocol.queued<Request, ImageResponse, Token>(route, {
  token: Token,
  start: { body: { from: fromRequest }, decode: decodeStart },
  status: { path: (token) => token.pollingURL, decode: decodeStatus },
  result: { path: (token) => token.pollingURL, decode: decodeResult },
})

export const model = (input: MediaRoute.ModelInput) =>
  ImageModel.fromRoute<BlackForestLabsImageOptions, Token>(
    { protocol, baseURL: DEFAULT_BASE_URL, path: ({ request }) => `/v1/${request.model.id}` },
    input,
  )

export const BlackForestLabsImages = {
  protocol,
  model,
} as const

import { Effect, Schema } from "effect"
import { classifyProviderFailure } from "../provider-error.js"
import { Framing } from "../route/framing.js"
import { MediaProtocol } from "../route/media-protocol.js"
import { MediaRoute } from "../route/media.js"
import { AIError, mergeJsonRecords, type OpenString } from "../schema/index.js"
import { SpeechModel, type SpeechEvent, type SpeechRequestFor } from "../speech.js"
import { ProviderShared, optionalNull } from "./shared.js"
import { SpeechStream } from "./utils/speech-stream.js"

const route = MediaProtocol.identity({ id: "cartesia-speech", name: "Cartesia", provider: "cartesia" })
export const DEFAULT_BASE_URL = "https://api.cartesia.ai"
export const API_VERSION = "2026-08-14"
export const BYTES_PATH = "/tts/bytes"
export const SSE_PATH = "/tts/sse"
const DEFAULT_SAMPLE_RATE = 44100
const DEFAULT_BIT_RATE = 128000

// ---------------------------------------------------------------------------
// 1. Public model input
// ---------------------------------------------------------------------------

export type CartesiaEncoding = SpeechStream.PcmEncoding

export type CartesiaSpeechOptions = {
  readonly sampleRate?: 8000 | 16000 | 22050 | 24000 | 44100 | 48000
  readonly bitRate?: 32000 | 64000 | 96000 | 128000 | 192000
  readonly encoding?: CartesiaEncoding
  readonly generation_config?: {
    readonly volume?: number
    readonly emotion?: OpenString<"neutral" | "calm" | "angry" | "content" | "sad" | "scared">
  }
  readonly pronunciation_dict_id?: string
} & Record<string, unknown>

export type Request = SpeechRequestFor<CartesiaSpeechOptions>

// ---------------------------------------------------------------------------
// 3. Streaming event schema
// ---------------------------------------------------------------------------

/** `phoneme_timestamps` and future record types are ignored. */
const SseEvent = Schema.Struct({
  type: Schema.String,
  data: Schema.optional(Schema.Uint8ArrayFromBase64),
  word_timestamps: Schema.optional(
    Schema.Struct({
      words: Schema.Array(Schema.String),
      start: Schema.Array(Schema.Number),
      end: Schema.Array(Schema.Number),
    }),
  ),
  status_code: Schema.optional(Schema.Number),
  title: Schema.optional(Schema.String),
  message: Schema.optional(Schema.String),
  error_code: optionalNull(Schema.String),
})

const decodeEvent = route.decodeFrame(SseEvent)

// ---------------------------------------------------------------------------
// 4. Parser state
// ---------------------------------------------------------------------------

interface State extends SpeechStream.Audio {
  readonly done: boolean
}

// ---------------------------------------------------------------------------
// 5. Request body construction
// ---------------------------------------------------------------------------

/** Timestamps exist only on the SSE endpoint, so a `generate` that asks for them collects an SSE stream. */
const usesSse = (request: MediaProtocol.Addressed<Request>) => request.mode === "stream" || request.timestamps === true

const CONTAINERS: Readonly<Record<string, "raw" | "wav" | "mp3">> = { pcm: "raw", wav: "wav", mp3: "mp3" }

const outputFormat = Effect.fnUntraced(function* (request: MediaProtocol.Addressed<Request>) {
  const sse = usesSse(request)
  const format = request.format ?? (sse ? "pcm" : "mp3")
  const container = CONTAINERS[format]
  if (container === undefined)
    return yield* route.unsupported(
      "media.format",
      `${route.name} supports the pcm, wav, and mp3 formats, not "${format}"`,
    )
  if (sse && container !== "raw")
    return yield* route.unsupported(
      "media.format",
      `${route.name} streams and timestamps only raw PCM; request format "pcm" instead of "${format}"`,
    )
  const sampleRate = request.providerOptions?.sampleRate ?? DEFAULT_SAMPLE_RATE
  if (container === "mp3")
    return { container, sample_rate: sampleRate, bit_rate: request.providerOptions?.bitRate ?? DEFAULT_BIT_RATE }
  return { container, encoding: request.providerOptions?.encoding ?? "pcm_s16le", sample_rate: sampleRate }
})

const fromRequest = Effect.fn("CartesiaSpeech.fromRequest")(function* (request: MediaProtocol.Addressed<Request>) {
  const voice = SpeechStream.voiceID(request.voice)
  if (voice === undefined)
    return yield* ProviderShared.invalidRequest(`${route.name} requires a voice id; pass it as \`voice\``)
  const { sampleRate: _sampleRate, bitRate: _bitRate, encoding: _encoding, ...native } = request.providerOptions ?? {}
  return MediaProtocol.json(
    mergeJsonRecords(
      {
        model_id: request.model.id,
        transcript: request.text,
        voice,
        output_format: yield* outputFormat(request),
        language: request.language,
        generation_config: request.speed === undefined ? undefined : { speed: request.speed },
        add_timestamps: request.timestamps === true ? true : undefined,
      },
      native,
      request.http?.body,
    ) ?? {},
  )
})

// ---------------------------------------------------------------------------
// 6. Stream parsing
// ---------------------------------------------------------------------------

const onEvent = Effect.fnUntraced(function* (state: State, frame: string) {
  const event = yield* decodeEvent(frame)
  if (event.type === "chunk" && event.data !== undefined) return SpeechStream.delta(state, event.data)
  if (event.type === "timestamps" && event.word_timestamps !== undefined) {
    const words = event.word_timestamps
    return [state, SpeechStream.timestamps(words.words, words.start, words.end)] as const
  }
  if (event.type === "done") return [{ ...state, done: true }, []] as const
  if (event.type === "error")
    return yield* new AIError({
      reason: classifyProviderFailure({
        message: `${route.name} stream failed${event.title === undefined ? "" : ` (${event.title})`}: ${event.message ?? "unknown error"}`,
        status: event.status_code,
        rawBody: frame,
      }),
    })
  return [state, []] as const
})

const finish = Effect.fnUntraced(function* (
  state: State,
  context: MediaProtocol.ResponseContext<Request>,
) {
  if (usesSse(context.request) && !state.done) return yield* route.incomplete()
  const format = yield* outputFormat(context.request)
  return yield* SpeechStream.finish(
    route,
    state,
    format.container === "raw"
      ? SpeechStream.pcm(format.encoding, format.sample_rate)
      : SpeechStream.container(format.container, format.sample_rate),
  )
})

// ---------------------------------------------------------------------------
// 7. Protocol and route
// ---------------------------------------------------------------------------

export const protocol = MediaProtocol.stream<Request, SpeechEvent, string | Uint8Array, State>(route, {
  unsupported: ["instructions"],
  body: { from: fromRequest },
  frames: (bytes, context) => (usesSse(context.request) ? Framing.sse.frame(bytes) : bytes),
  initial: () => ({ chunks: [], done: false }),
  step: SpeechStream.step(onEvent),
  finish,
})

export const model = (input: MediaRoute.ModelInput) =>
  SpeechModel.fromRoute<CartesiaSpeechOptions, string | Uint8Array, State>(
    {
      protocol,
      baseURL: DEFAULT_BASE_URL,
      headers: { "Cartesia-Version": API_VERSION },
      path: ({ request }) => (usesSse(request) ? SSE_PATH : BYTES_PATH),
    },
    input,
  )

export const CartesiaSpeech = {
  protocol,
  model,
} as const

import { Effect, Schema } from "effect"
import { Route } from "../route/client.js"
import { Endpoint } from "../route/endpoint.js"
import { Framing } from "../route/framing.js"
import { Protocol } from "../route/protocol.js"
import { LLMEvent, Usage, type FinishReasonDetails, type LLMRequest } from "../schema/index.js"
import { ProviderShared } from "./shared.js"
import { Lifecycle } from "./utils/lifecycle.js"
import { ToolStream } from "./utils/tool-stream.js"

const ADAPTER = "cohere-chat"
export const DEFAULT_BASE_URL = "https://api.cohere.com/v2"

const Options = Schema.Struct({
  thinking: Schema.optional(
    Schema.Struct({
      type: Schema.optional(Schema.Literals(["enabled", "disabled"])),
      tokenBudget: Schema.optional(Schema.Int.check(Schema.isGreaterThan(0))),
    }),
  ),
})
export type ProviderOptionsInput = Schema.Schema.Type<typeof Options>

const Content = Schema.Union([
  Schema.Struct({ type: Schema.Literal("text"), text: Schema.String }),
  Schema.Struct({ type: Schema.Literal("thinking"), thinking: Schema.String }),
  Schema.Struct({ type: Schema.Literal("image_url"), image_url: Schema.Struct({ url: Schema.String }) }),
])
const ToolCall = Schema.Struct({
  id: Schema.String,
  type: Schema.Literal("function"),
  function: Schema.Struct({ name: Schema.String, arguments: Schema.String }),
})
const Message = Schema.Struct({
  role: Schema.Literals(["system", "user", "assistant", "tool"]),
  content: Schema.optional(Schema.Union([Schema.String, Schema.Array(Content)])),
  tool_calls: Schema.optional(Schema.Array(ToolCall)),
  tool_call_id: Schema.optional(Schema.String),
  tool_plan: Schema.optional(Schema.String),
})
const Body = Schema.Struct({
  model: Schema.String,
  messages: Schema.Array(Message),
  stream: Schema.Literal(true),
  tools: Schema.optional(
    Schema.Array(
      Schema.Struct({
        type: Schema.Literal("function"),
        function: Schema.Struct({
          name: Schema.String,
          description: Schema.optional(Schema.String),
          parameters: Schema.Unknown,
        }),
      }),
    ),
  ),
  tool_choice: Schema.optional(Schema.Literals(["NONE", "REQUIRED"])),
  thinking: Schema.optional(Schema.Struct({ type: Schema.String, token_budget: Schema.optional(Schema.Number) })),
  max_tokens: Schema.optional(Schema.Number),
  temperature: Schema.optional(Schema.Number),
  p: Schema.optional(Schema.Number),
  k: Schema.optional(Schema.Number),
  seed: Schema.optional(Schema.Number),
  stop_sequences: Schema.optional(Schema.Array(Schema.String)),
  frequency_penalty: Schema.optional(Schema.Number),
  presence_penalty: Schema.optional(Schema.Number),
})
const TokenCounts = Schema.Struct({
  input_tokens: Schema.optional(Schema.Number),
  output_tokens: Schema.optional(Schema.Number),
  reasoning_tokens: Schema.optional(Schema.Number),
})
const NativeUsage = Schema.Struct({
  tokens: Schema.optional(TokenCounts),
  billed_units: Schema.optional(TokenCounts),
  cached_tokens: Schema.optional(Schema.Number),
})
const Event = Schema.Union([
  Schema.Struct({ type: Schema.Literal("message-start") }),
  Schema.Struct({
    type: Schema.Literals(["content-start", "content-delta"]),
    index: Schema.Number,
    delta: Schema.Struct({
      message: Schema.Struct({
        content: Schema.Struct({ text: Schema.optional(Schema.String), thinking: Schema.optional(Schema.String) }),
      }),
    }),
  }),
  Schema.Struct({ type: Schema.Literal("content-end"), index: Schema.Number }),
  Schema.Struct({
    type: Schema.Literal("tool-plan-delta"),
    delta: Schema.Struct({ message: Schema.Struct({ tool_plan: Schema.String }) }),
  }),
  Schema.Struct({
    type: Schema.Literals(["tool-call-start", "tool-call-delta"]),
    index: Schema.Number,
    delta: Schema.Struct({
      message: Schema.Struct({
        tool_calls: Schema.Struct({
          id: Schema.optional(Schema.String),
          function: Schema.Struct({ name: Schema.optional(Schema.String), arguments: Schema.optional(Schema.String) }),
        }),
      }),
    }),
  }),
  Schema.Struct({ type: Schema.Literal("tool-call-end"), index: Schema.Number }),
  Schema.Struct({
    type: Schema.Literal("message-end"),
    delta: Schema.Struct({ finish_reason: Schema.String, usage: Schema.optional(NativeUsage) }),
  }),
  // Citation output is outside this basic chat surface.
  Schema.Struct({ type: Schema.Literals(["citation-start", "citation-end"]) }),
])
type Event = typeof Event.Type
type State = {
  readonly lifecycle: Lifecycle.State
  readonly tools: ToolStream.State<number>
  readonly finished: boolean
}

const TOOL_CHOICE = { auto: undefined, none: "NONE", required: "REQUIRED", tool: "REQUIRED" } as const

const fromRequest = Effect.fn("CohereChat.fromRequest")(function* (request: LLMRequest) {
  const options = yield* ProviderShared.validateWith(Schema.decodeUnknownEffect(Options))(request.providerOptions ?? {})
  const flattened = ProviderShared.flattenToolRequest(request)
  const messages: (typeof Message.Type)[] = request.system.length
    ? [
        {
          role: "system",
          content:
            request.system.length === 1
              ? request.system[0].text
              : request.system.map((part) => ({ type: "text", text: part.text })),
        },
      ]
    : []
  for (const message of flattened.request.messages) {
    if (message.role === "system") {
      messages.push({ role: "user", content: (yield* ProviderShared.wrappedSystemUpdate("Cohere Chat", message)).text })
      continue
    }
    if (message.role === "tool") {
      for (const part of message.content) {
        if (part.type !== "tool-result")
          return yield* ProviderShared.unsupportedContent("Cohere Chat", "tool", ["tool-result"])
        if (part.result.type === "content" && part.result.value.some((item) => item.type === "file"))
          return yield* ProviderShared.invalidRequest("Cohere Chat does not support file content in tool results")
        messages.push({ role: "tool", tool_call_id: part.id, content: ProviderShared.toolResultText(part) })
      }
      continue
    }
    const content: (typeof Content.Type)[] = []
    const calls: (typeof ToolCall.Type)[] = []
    const plans: string[] = []
    for (const part of message.content) {
      if (part.type === "text") {
        content.push({ type: "text", text: part.text })
        continue
      }
      if (message.role === "assistant" && part.type === "reasoning") {
        if (part.providerMetadata?.cohere?.toolPlan === true) plans.push(part.text)
        else content.push({ type: "thinking", thinking: part.text })
        continue
      }
      if (message.role === "assistant" && part.type === "tool-call") {
        const args = ProviderShared.encodeJson(part.input)
        calls.push({ id: part.id, type: "function", function: { name: part.name, arguments: args } })
        continue
      }
      if (message.role === "user" && part.type === "media" && part.media.mediaType.startsWith("image/")) {
        const url =
          ProviderShared.mediaUrl(part.media) ??
          (yield* ProviderShared.requireInlineMedia("Cohere Chat", part.media)).dataUrl
        content.push({ type: "image_url", image_url: { url } })
        continue
      }
      return yield* ProviderShared.unsupportedContent(
        "Cohere Chat",
        message.role,
        message.role === "user" ? ["text", "media"] : ["text", "reasoning", "tool-call"],
      )
    }
    messages.push({
      role: message.role,
      content: content.length ? content : undefined,
      tool_calls: calls.length ? calls : undefined,
      tool_plan: plans.length ? plans.join("") : undefined,
    })
  }
  const selected = request.toolChoice?.type === "tool" ? request.toolChoice.name : undefined
  const tools = selected === undefined ? flattened.tools : flattened.tools.filter((tool) => tool.name === selected)
  if (selected !== undefined && tools.length === 0)
    return yield* ProviderShared.invalidRequest("Cohere Chat tool choice must name an available tool")
  if (tools.some((tool) => tool.native !== undefined))
    return yield* ProviderShared.invalidRequest("Cohere Chat does not support provider-defined tools")
  return {
    model: request.model.id,
    messages,
    stream: true as const,
    tools: tools.length
      ? tools.map((tool) => ({
          type: "function" as const,
          function: { name: tool.name, description: tool.description, parameters: tool.inputSchema },
        }))
      : undefined,
    tool_choice: TOOL_CHOICE[request.toolChoice?.type ?? "auto"],
    thinking: options.thinking && {
      type: options.thinking.type ?? "enabled",
      // Cohere rejects budgets above max_tokens; fitting also leaves room for the answer.
      token_budget:
        options.thinking.tokenBudget === undefined
          ? undefined
          : ProviderShared.fitThinkingBudget(options.thinking.tokenBudget, request.generation?.maxTokens),
    },
    max_tokens: request.generation?.maxTokens,
    temperature: request.generation?.temperature,
    p: request.generation?.topP,
    k: request.generation?.topK,
    seed: request.generation?.seed,
    stop_sequences: request.generation?.stop,
    frequency_penalty: request.generation?.frequencyPenalty,
    presence_penalty: request.generation?.presencePenalty,
  }
})

const finishReason = (raw: string): FinishReasonDetails => {
  switch (raw) {
    case "COMPLETE":
    case "STOP_SEQUENCE":
      return { normalized: "stop", raw }
    case "MAX_TOKENS":
      return { normalized: "length", raw }
    case "TOOL_CALL":
      return { normalized: "tool-calls", raw }
    case "ERROR":
    case "TIMEOUT":
      return { normalized: "error", raw }
    default:
      return { normalized: "unknown", raw }
  }
}

const mapUsage = (usage: typeof NativeUsage.Type) =>
  new Usage({
    inputTokens: usage.tokens?.input_tokens,
    outputTokens: usage.tokens?.output_tokens,
    nonCachedInputTokens: ProviderShared.subtractTokens(usage.tokens?.input_tokens, usage.cached_tokens),
    cacheReadInputTokens: usage.cached_tokens,
    reasoningTokens: usage.tokens?.reasoning_tokens,
    totalTokens: ProviderShared.totalTokens(usage.tokens?.input_tokens, usage.tokens?.output_tokens, undefined),
    providerMetadata: { cohere: usage },
  })

// Lifecycle deltas open blocks on demand and ends are no-ops for closed blocks, so content-start needs no handling.
const step = Effect.fnUntraced(function* (state: State, event: Event) {
  const events: LLMEvent[] = []
  switch (event.type) {
    case "message-start":
      return [{ ...state, lifecycle: Lifecycle.stepStart(state.lifecycle, events) }, events] as const
    case "content-delta": {
      const id = String(event.index)
      const content = event.delta.message.content
      const lifecycle =
        content.thinking !== undefined
          ? Lifecycle.reasoningDelta(state.lifecycle, events, id, content.thinking)
          : Lifecycle.textDelta(state.lifecycle, events, id, content.text ?? "")
      return [{ ...state, lifecycle }, events] as const
    }
    case "content-end": {
      const id = String(event.index)
      const lifecycle = Lifecycle.textEnd(Lifecycle.reasoningEnd(state.lifecycle, events, id), events, id)
      return [{ ...state, lifecycle }, events] as const
    }
    case "tool-plan-delta": {
      const plan = event.delta.message.tool_plan
      const lifecycle = Lifecycle.reasoningDelta(state.lifecycle, events, "tool-plan", plan, {
        cohere: { toolPlan: true },
      })
      return [{ ...state, lifecycle }, events] as const
    }
    case "tool-call-start":
    case "tool-call-delta": {
      const call = event.delta.message.tool_calls
      const result = ToolStream.appendOrStart(
        ADAPTER,
        state.tools,
        event.index,
        { id: call.id, name: call.function.name, text: call.function.arguments ?? "" },
        "Cohere tool call is missing id or name",
      )
      if (ToolStream.isError(result)) return yield* result
      return [{ ...state, tools: result.tools }, result.events] as const
    }
    case "tool-call-end": {
      const result = yield* ToolStream.finish(ADAPTER, state.tools, event.index)
      return [{ ...state, tools: result.tools }, result.events ?? []] as const
    }
    case "message-end": {
      const pending = yield* ToolStream.finishAll(ADAPTER, state.tools)
      events.push(...pending.events)
      const lifecycle = Lifecycle.finish(state.lifecycle, events, {
        reason: finishReason(event.delta.finish_reason),
        usage: event.delta.usage && mapUsage(event.delta.usage),
      })
      return [{ tools: pending.tools, lifecycle, finished: true }, events] as const
    }
    default:
      return [state, events] as const
  }
})

export const protocol = Protocol.make({
  id: ADAPTER,
  body: { schema: Body, from: fromRequest },
  stream: {
    event: Protocol.jsonEvent(Event),
    initial: (): State => ({ lifecycle: Lifecycle.initial(), tools: ToolStream.empty(), finished: false }),
    step,
    terminal: (event) => event.type === "message-end",
