const lowerMedia = Effect.fnUntraced(function* (part: MediaPart) {
  const mime = part.media.mediaType.toLowerCase()
  const url =
    ProviderShared.mediaUrl(part.media) ??
    (yield* ProviderShared.requireInlineMedia("Mistral Chat", part.media)).dataUrl
  if (mime.startsWith("image/")) return { type: "image_url" as const, image_url: url }
  if (mime === "application/pdf") return { type: "document_url" as const, document_url: url }
  return yield* ProviderShared.invalidRequest(`Mistral Chat does not support media type ${part.media.mediaType}`)
})

const lowerUser = Effect.fnUntraced(function* (message: LLMRequest["messages"][number]) {
  const content: MistralUserContent[] = []
  for (const part of message.content) {
    if (part.type === "text") {
      content.push({ type: "text", text: part.text })
      continue
    }
    if (part.type === "media") {
      content.push(yield* lowerMedia(part))
      continue
    }
    return yield* ProviderShared.unsupportedContent("Mistral Chat", "user", ["text", "media"])
  }
  if (content.every((part) => part.type === "text"))
    return { role: "user" as const, content: content.map((part) => part.text).join("") }
  return { role: "user" as const, content }
})

const lowerToolCall = (part: ToolCallPart, normalizeID: (id: string) => string): MistralAssistantToolCall => ({
  id: normalizeID(part.id),
  type: "function",
  function: { name: part.name, arguments: ProviderShared.encodeJson(part.input) },
})

const lowerAssistant = Effect.fnUntraced(function* (
  message: LLMRequest["messages"][number],
  normalizeID: (id: string) => string,
  prefix: boolean,
) {
  const structured = message.content.some(
    (part) => part.type === "reasoning" && isMistralThinkingContent(part.providerMetadata?.mistral?.thinking),
  )
  const content: Array<Schema.Schema.Type<typeof MistralTextContent> | MistralThinkingContent> = []
  const text: string[] = []
  const toolCalls: MistralAssistantToolCall[] = []
  for (const part of message.content) {
    if (part.type === "text") {
      if (structured) content.push({ type: "text", text: part.text })
      else text.push(part.text)
      continue
    }
    if (part.type === "reasoning") {
      const native = part.providerMetadata?.mistral?.thinking
      if (structured && isMistralThinkingContent(native)) content.push(native)
      else if (structured) content.push({ type: "text", text: part.text })
      else text.push(part.text)
      continue
    }
    if (part.type === "tool-call") {
      toolCalls.push(lowerToolCall(part, normalizeID))
      continue
    }
    return yield* ProviderShared.unsupportedContent("Mistral Chat", "assistant", ["text", "reasoning", "tool-call"])
  }
  return {
    role: "assistant" as const,
    content: structured ? content : text.join(""),
    ...(toolCalls.length > 0 ? { tool_calls: toolCalls } : {}),
    ...(prefix ? { prefix: true as const } : {}),
  }
})

const lowerToolResults = Effect.fnUntraced(function* (
  message: LLMRequest["messages"][number],
  normalizeID: (id: string) => string,
) {
  const output: MistralMessage[] = []
  for (const part of message.content) {
    if (part.type !== "tool-result")
      return yield* ProviderShared.unsupportedContent("Mistral Chat", "tool", ["tool-result"])
    if (part.result.type !== "content") {
      output.push({
        role: "tool",
        tool_call_id: normalizeID(part.id),
        name: part.name,
        content: ProviderShared.toolResultText(part),
      })
      continue
    }
    const content: MistralUserContent[] = []
    for (const item of part.result.value) {
      if (item.type === "text") {
        content.push({ type: "text", text: item.text })
        continue
      }
      content.push(yield* lowerMedia(ProviderShared.toolFileMedia(item)))
    }
    output.push({
      role: "tool",
      tool_call_id: normalizeID(part.id),
      name: part.name,
      content: content.some((item) => item.type !== "text")
        ? content
        : content.map((item) => (item.type === "text" ? item.text : "")).join(""),
    })
  }
  return output
})

const lowerMessages = Effect.fnUntraced(function* (request: LLMRequest) {
  const normalizeID = MistralToolID.normalizer(request)
  const messages: MistralMessage[] =
    request.system.length === 0
      ? []
      : [
          {
            role: "system",
            content:
              request.system.length === 1
                ? request.system[0].text
                : request.system.map((part) => ({ type: "text", text: part.text })),
          },
        ]
  for (const message of request.messages) {
    if (message.role === "system") {
      const update = yield* ProviderShared.wrappedSystemUpdate("Mistral Chat", message)
      messages.push({
        role: "user",
        content: update.text,
      })
      continue
    }
    if (message.role === "user") {
      messages.push(yield* lowerUser(message))
      continue
    }
    if (message.role === "assistant") {
      const hasToolCalls = message.content.some((part) => part.type === "tool-call")
      const hasNativeThinking = message.content.some(
        (part) => part.type === "reasoning" && isMistralThinkingContent(part.providerMetadata?.mistral?.thinking),
      )
      const text = message.content
        .flatMap((part) => (part.type === "text" || part.type === "reasoning" ? [part.text] : []))
        .join("")
      if (!hasToolCalls && !hasNativeThinking && text.trim() === "") continue
      messages.push(yield* lowerAssistant(message, normalizeID, !hasToolCalls && message === request.messages.at(-1)))
      continue
    }
    messages.push(...(yield* lowerToolResults(message, normalizeID)))
  }
  return messages
})

const lowerTool = (tool: ToolDefinition): MistralTool => ({
  type: "function",
  function: { name: tool.name, description: tool.description, parameters: tool.inputSchema, strict: false },
})

export const fromRequest = Effect.fn("MistralChat.fromRequest")(function* (request: LLMRequest) {
  const options = yield* ProviderShared.validateWith(Schema.decodeUnknownEffect(MistralOptions))(
    request.providerOptions ?? {},
  )
  const selected = request.toolChoice?.type === "tool" ? request.toolChoice.name : undefined
  if (request.toolChoice?.type === "tool" && !selected)
    return yield* ProviderShared.invalidRequest("Mistral Chat tool choice requires a tool name")
  if (options.reasoningEffort !== undefined && options.promptMode !== undefined)
    return yield* ProviderShared.invalidRequest(
      "Mistral Chat reasoningEffort and promptMode provider options are mutually exclusive",
    )
  const toolChoice = request.toolChoice
    ? yield* ProviderShared.matchToolChoice("Mistral Chat", request.toolChoice, {
        auto: () => "auto" as const,
        none: () => "none" as const,
        required: () => "any" as const,
        tool: (name) => ({ type: "function" as const, function: { name } }),
      })
    : undefined
  const flattened = ProviderShared.flattenToolRequest(request)
  return {
    model: request.model.id,
    messages: yield* lowerMessages(flattened.request),
    tools: flattened.tools.length > 0 ? flattened.tools.map(lowerTool) : undefined,
    tool_choice: toolChoice,
    stream: true as const,
    max_tokens: request.generation?.maxTokens,
    random_seed: request.generation?.seed,
    temperature: request.generation?.temperature,
    top_p: request.generation?.topP,
    frequency_penalty: request.generation?.frequencyPenalty,
    presence_penalty: request.generation?.presencePenalty,
    stop: request.generation?.stop,
    prompt_cache_key: ProviderShared.sendsPromptCacheKey(request)
      ? (options.promptCacheKey ?? request.promptCacheKey)
      : undefined,
    safe_prompt: options.safePrompt,
    document_image_limit: options.documentImageLimit,
    document_page_limit: options.documentPageLimit,
    parallel_tool_calls:
      options.parallelToolCalls ?? (request.toolChoice?.disableParallelToolUse === true ? false : undefined),
    reasoning_effort: options.reasoningEffort,
    prompt_mode: options.promptMode,
  }
})

type ToolKey = string | number
interface PendingTool {
  readonly id: string
  readonly name?: string
  readonly input: string
}

interface ActiveContent {
  readonly type: "text" | "reasoning"
  readonly id: string
  readonly thinking?: MistralThinkingContent
  readonly thinkingUnits?: MistralThinkingUnit[]
}

export interface ParserState {
  readonly tools: ToolStream.State<ToolKey>
  readonly pendingTools: Partial<Record<ToolKey, PendingTool>>
  readonly toolIDs: ReadonlyMap<string, string>
  readonly usedToolIDs: ReadonlySet<string>
  readonly completedTools: ReadonlyArray<LLMEvent>
  readonly latestToolKey?: ToolKey
  readonly generatedTools: number
  readonly lifecycle: Lifecycle.State
  readonly active?: ActiveContent
  readonly nextContent: number
  readonly usage?: Usage
  readonly finishReason?: FinishReasonDetails
}

const mapUsage = (usage: MistralEvent["usage"]): Usage | undefined => {
  if (!usage) return undefined
  const input = usage.prompt_tokens ?? undefined
  const reported =
    usage.num_cached_tokens ??
    usage.prompt_tokens_details?.cached_tokens ??
    usage.prompt_token_details?.cached_tokens ??
    undefined
  const cached = input === undefined || reported === undefined ? undefined : Math.max(0, Math.min(input, reported))
  const output = usage.completion_tokens ?? undefined
  return new Usage({
    inputTokens: input,
    outputTokens: output,
    nonCachedInputTokens: ProviderShared.subtractTokens(input, cached),
    cacheReadInputTokens: cached,
    totalTokens: ProviderShared.totalTokens(input, output, usage.total_tokens ?? undefined),
    providerMetadata: { mistral: usage },
  })
}

const mapFinishReason = (reason: string) => {
  switch (reason) {
    case "stop":
      return "stop" as const
    case "length":
    case "model_length":
      return "length" as const
    case "tool_calls":
      return "tool-calls" as const
    case "content_filter":
      return "content-filter" as const
    case "error":
    case "network_error":
      return "error" as const
    default:
      return "unknown" as const
  }
}

const thinkingUnits = (value: unknown): ReadonlyArray<MistralThinkingUnit> => {
  if (typeof value === "string") return [{ type: "text", text: value }]
  if (!Array.isArray(value)) return []
  return value.filter(Schema.is(MistralThinkingUnit))
}

const thinkingText = (thinking: ReadonlyArray<MistralThinkingUnit>) =>
  thinking.flatMap((unit) => (typeof unit.text === "string" ? [unit.text] : [])).join("")

const thinkingMetadata = (thinking: MistralThinkingContent) => ({ mistral: { thinking } })

const closeActive = (state: ParserState, events: LLMEvent[]) => {
  if (!state.active) return state
  const lifecycle =
    state.active.type === "text"
      ? Lifecycle.textEnd(state.lifecycle, events, state.active.id)
      : Lifecycle.reasoningEnd(
          state.lifecycle,
          events,
          state.active.id,
          thinkingMetadata({ ...state.active.thinking, type: "thinking", thinking: state.active.thinkingUnits ?? [] }),
          thinkingText(state.active.thinkingUnits ?? []),
        )
  return { ...state, lifecycle, active: undefined }
}

const appendText = (state: ParserState, events: LLMEvent[], text: string) => {
  if (text.length === 0) return state
  const current = state.active?.type === "text" ? state : closeActive(state, events)
  const active = current.active ?? { type: "text" as const, id: `text-${current.nextContent}` }
  return {
    ...current,
    lifecycle: Lifecycle.textDelta(current.lifecycle, events, active.id, text),
    active,
    nextContent: current.active ? current.nextContent : current.nextContent + 1,
  }
}

const appendThinking = (state: ParserState, events: LLMEvent[], part: MistralOutputContent) => {
  const current = state.active?.type === "reasoning" ? state : closeActive(state, events)
  const units = thinkingUnits(part.thinking)
  const active = current.active ?? { type: "reasoning" as const, id: `reasoning-${current.nextContent}` }
  // Keep native units out of streamed events until the block is complete.
  const accumulated = active.thinkingUnits ?? []
  accumulated.push(...units)
  const thinking = {
    ...active.thinking,
    ...part,
    type: "thinking" as const,
    thinking: [],
  }
  const text = thinkingText(units)
  return {
    ...current,
    lifecycle:
      text.length > 0
        ? Lifecycle.reasoningDelta(current.lifecycle, events, active.id, text)
        : Lifecycle.reasoningStart(current.lifecycle, events, active.id),
    active: { ...active, thinking, thinkingUnits: accumulated },
    nextContent: current.active ? current.nextContent : current.nextContent + 1,
  }
}

const appendContent = (
  state: ParserState,
  events: LLMEvent[],
  content: string | ReadonlyArray<MistralOutputContent>,
) => {
  if (typeof content === "string") return appendText(state, events, content)
  return content.reduce((current, part) => {
    if (part.type === "text") return appendText(current, events, part.text ?? "")
    if (part.type === "thinking") return appendThinking(current, events, part)
    return closeActive(current, events)
  }, state)
}

const normalizeStreamToolID = (state: ParserState, source: string) => {
  if (MistralToolID.valid.test(source))
    return { id: source, state: { ...state, usedToolIDs: new Set([...state.usedToolIDs, source]) } }
  const previous = state.toolIDs.get(source)
  if (previous) return { id: previous, state }
  let attempt = 0
  let id = MistralToolID.hash(source)
  while (state.usedToolIDs.has(id)) id = MistralToolID.hash(`${source}:${++attempt}`)
  return {
    id,
    state: {
      ...state,
      toolIDs: new Map([...state.toolIDs, [source, id]]),
      usedToolIDs: new Set([...state.usedToolIDs, id]),
    },
  }
}

const toolText = (tool: MistralToolDelta) => {
  const value = tool.function?.arguments
  if (typeof value === "string") return value
  return value === null || value === undefined ? "" : ProviderShared.encodeJson(value)
}

const appendTools = Effect.fnUntraced(function* (
  initial: ParserState,
  events: LLMEvent[],
  deltas: ReadonlyArray<MistralToolDelta>,
) {
  if (deltas.length === 0) return initial
  let state = closeActive(initial, events)
  for (const [position, delta] of deltas.entries()) {
    const wireID = delta.id?.trim() || undefined
    const providedID = wireID === "null" ? undefined : wireID
    const key =
      delta.index ??
      (providedID
        ? `id:${providedID}`
        : deltas.length > 1
          ? `position:${position}`
          : (state.latestToolKey ?? `missing:${state.generatedTools}`))
    const existing = state.tools[key]
    const pending = state.pendingTools[key]
    const source = providedID ?? `generated:${String(key)}`
    const normalized =
      existing || pending ? { id: existing?.id ?? pending?.id ?? "", state } : normalizeStreamToolID(state, source)
    state = normalized.state
    const name = existing?.name ?? pending?.name ?? (delta.function?.name?.trim() || undefined)
    const text = `${pending?.input ?? ""}${toolText(delta)}`
    if (!name) {
      state = {
        ...state,
        pendingTools: { ...state.pendingTools, [key]: { id: normalized.id, input: text } },
        latestToolKey: key,
        generatedTools: state.generatedTools + (!providedID && !pending ? 1 : 0),
      }
      continue
    }
    const result = ToolStream.appendOrStart(
      ADAPTER,
      state.tools,
      key,
      { id: normalized.id, name, text },
      "Mistral Chat tool call delta is missing a name",
    )
    if (ToolStream.isError(result)) return yield* result
    if (result.events.length > 0) state = { ...state, lifecycle: Lifecycle.stepStart(state.lifecycle, events) }
    events.push(...result.events)
    const pendingTools = { ...state.pendingTools }
    delete pendingTools[key]
    state = {
      ...state,
      tools: result.tools,
      pendingTools,
      latestToolKey: key,
      generatedTools: state.generatedTools + (!providedID && !existing && !pending ? 1 : 0),
    }
  }
  return state
})

const hasLateContent = (event: MistralEvent) => {
  const delta = event.choices?.[0]?.delta
  if (typeof delta?.content === "string" && delta.content.length > 0) return true
  if (Array.isArray(delta?.content) && delta.content.length > 0) return true
  return (delta?.tool_calls ?? []).some(
    (tool) => Boolean(tool.id) || Boolean(tool.function?.name) || tool.function?.arguments !== undefined,
  )
}

const step = Effect.fnUntraced(function* (state: ParserState, event: MistralEvent) {
  if (event.error) {
    const body = ProviderShared.encodeJson(event)
    return yield* new AIError({
      reason: classifyProviderFailure({
        message: event.error.message,
        status: typeof event.error.code === "number" ? event.error.code : undefined,
        rawBody: body,
      }),
    })
  }
  const events: LLMEvent[] = []
  const usage = mapUsage(event.usage) ?? state.usage
  if (state.finishReason) {
    if (hasLateContent(event))
      return yield* ProviderShared.eventError(
        ADAPTER,
        "Mistral Chat received content after the finish reason",
        ProviderShared.encodeJson(event),
      )
    return [{ ...state, usage }, events] as const
  }
  const choice = event.choices?.[0]
  const withContent = choice?.delta?.content == null ? state : appendContent(state, events, choice.delta.content)
  const withTools = yield* appendTools(withContent, events, choice?.delta?.tool_calls ?? [])
  if (!choice?.finish_reason) return [{ ...withTools, usage }, events] as const

  const finishReason = {
    normalized: mapFinishReason(choice.finish_reason),
    raw: choice.finish_reason,
  }
  if (finishReason.normalized === "error") {
    const details = {
      message: `Mistral Chat stopped with ${finishReason.raw}`,
      body: ProviderShared.encodeJson(event),
    }
    return yield* new AIError({
      reason:
        finishReason.raw === "network_error" ? new ProviderInternalError(details) : new UnknownProviderError(details),
    })
  }
  const incomplete = finishReason.normalized === "length" || finishReason.normalized === "content-filter"
  if (!incomplete && Object.keys(withTools.pendingTools).length > 0)
    return yield* ProviderShared.eventError(
      ADAPTER,
      "Mistral Chat tool call delta is missing a name",
      ProviderShared.encodeJson(event),
    )
  const finished =
    !incomplete && Object.keys(withTools.tools).length > 0
      ? yield* ToolStream.finishAll(ADAPTER, withTools.tools)
      : undefined
  return [
    {
      ...withTools,
      tools: finished?.tools ?? withTools.tools,
      completedTools: finished?.events ?? withTools.completedTools,
      usage,
      finishReason,
    },
    events,
  ] as const
})

const finishEvents = Effect.fnUntraced(function* (state: ParserState) {
  if (!state.finishReason)
    return yield* new AIError({
      reason: new InvalidProviderOutputError({
        message: "Mistral Chat stream ended without finish_reason",
        classification: "incomplete-stream",
        route: ADAPTER,
      }),
    })
  const events: LLMEvent[] = []
  const closed = closeActive(state, events)
  const lifecycle = closed.completedTools.length > 0 ? Lifecycle.stepStart(closed.lifecycle, events) : closed.lifecycle
  events.push(...closed.completedTools)
  const reason =
    state.finishReason.normalized === "stop" && closed.completedTools.some(LLMEvent.is.toolCall)
      ? { ...state.finishReason, normalized: "tool-calls" as const }
      : state.finishReason
  Lifecycle.finish(lifecycle, events, { reason, usage: closed.usage })
  return events
})

export const protocol = Protocol.make({
  id: ADAPTER,
  body: { schema: MistralBody, from: fromRequest },
  stream: {
    event: MistralStreamEvent,
    initial: (): ParserState => ({
      tools: ToolStream.empty<ToolKey>(),
      pendingTools: {},
      toolIDs: new Map(),
      usedToolIDs: new Set(),
      completedTools: [],
      generatedTools: 0,
      lifecycle: Lifecycle.initial(),
      nextContent: 0,
    }),
    step: (state: ParserState, event) => (event === DONE ? Effect.succeed([state, []] as const) : step(state, event)),
    terminal: (event) => event === DONE,
    onHalt: finishEvents,
  },
})

export const framing = Framing.sseWithDone
export const httpTransport = HttpTransport.sseJson.with<MistralBody>().with({ framing })

export const route = Route.make({
  id: ADAPTER,
  provider: "mistral",
  providerMetadataKey: "mistral",
  protocol,
  endpoint: Endpoint.path(PATH, { baseURL: DEFAULT_BASE_URL }),
  auth: Auth.none,
  transport: httpTransport,
})

export * as MistralChat from "./mistral-chat.js"

import { Effect, Schema, Stream } from "effect"
import { Headers } from "effect/http"
import { Framing } from "../route/framing.js"
import type { HttpContext } from "../schema/index.js"
import {
  HttpTransport,
  WebSocketTransport,
  type Transport,
  type WebSocketChannelDriver,
  type WebSocketChannelExchange,
} from "../route/transport/index.js"
import * as ProviderShared from "./shared.js"
import { OpenResponses } from "./open-responses.js"
import { OpenResponsesContinuation } from "./open-responses-continuation.js"

const WebSocketResponseCreate = Schema.StructWithRest(Schema.Struct({ type: Schema.tag("response.create") }), [
  Schema.Record(Schema.String, Schema.Unknown),
])
const decodeMessage = ProviderShared.validateWith(Schema.decodeUnknownEffect(WebSocketResponseCreate))
const encodeMessage = Schema.encodeSync(Schema.fromJsonString(WebSocketResponseCreate))

export interface Options {
  readonly id: string
  readonly name: string
  readonly rotateAfterMs?: number
  readonly enabled?: (url: string) => boolean
  readonly url?: (url: string) => string
  readonly headers?: (headers: Headers.Headers) => Headers.Headers
  readonly continuation?: OpenResponsesContinuation.Shape
}

export interface Prepared {
  readonly http: HttpTransport.HttpPrepared<string>
  readonly channel?: {
    readonly url: string
    readonly headers: Headers.Headers
    readonly rotateAfterMs?: number
    readonly driver: WebSocketChannelDriver
  }
}

const message = (body: unknown) =>
  Effect.gen(function* () {
    if (!ProviderShared.isRecord(body))
      return yield* ProviderShared.invalidRequest("Open Responses WebSocket body must be a JSON object")
    const { stream: _stream, stream_options: _streamOptions, background: _background, ...request } = body
    const decoded = yield* decodeMessage({ ...request, type: "response.create" })
    return { request: decoded, message: encodeMessage(decoded) }
  })

const driver = (options: Options, body: string): WebSocketChannelDriver => {
  let responseID: string | undefined
  let terminal = false
  return {
    create: () =>
      Effect.sync(() => {
        responseID = undefined
        terminal = false
        return { message: body, mode: "full" }
      }),
    observe: (_create, frame) =>
      Effect.gen(function* () {
        const event = yield* OpenResponses.decodeChannelEvent(frame).pipe(
          Effect.mapError((cause) =>
            ProviderShared.eventError(options.id, `Invalid ${options.name} WebSocket event`, frame, cause),
          ),
        )
        if (terminal)
          return yield* ProviderShared.eventError(
            options.id,
            `${options.name} emitted ${event.type} after a terminal event`,
            frame,
          )
        if (event.type === "error") {
          terminal = true
          return {
            type: "provider-failure",
            error: OpenResponses.providerFailure(event, `${options.name} stream error`, frame),
          }
        }
        if (event.type === "response.failed") {
          terminal = true
          if (responseID && event.response?.id && event.response.id !== responseID)
            return yield* ProviderShared.eventError(
              options.id,
              `${options.name} response ID changed during execution`,
              frame,
            )
          return {
            type: "provider-failure",
            error: OpenResponses.providerFailure(event, `${options.name} response failed`, frame),
          }
        }
        if (event.type === "response.created") {
          const created = event.response?.id
          if (responseID)
            return yield* ProviderShared.eventError(
              options.id,
              `${options.name} emitted duplicate response.created`,
              frame,
            )
          if (!created)
            return yield* ProviderShared.eventError(
              options.id,
              `${options.name} response.created is missing response.id`,
              frame,
            )
          responseID = created
          return { type: "frame", frame }
        }
        // Keepalives and provider notifications carry no response state and may precede response.created.
        if (!event.type.startsWith("response.")) return { type: "frame", frame }
        if (!responseID)
          return yield* ProviderShared.eventError(
            options.id,
            `${options.name} emitted ${event.type} before response.created`,
            frame,
          )
        if (event.response?.id && event.response.id !== responseID)
          return yield* ProviderShared.eventError(
            options.id,
            `${options.name} response ID changed during execution`,
            frame,
          )
        if (event.type === "response.completed") {
          terminal = true
          return { type: "completed", frame }
        }
        if (event.type === "response.incomplete") {
          terminal = true
          return { type: "incomplete", frame }
        }
        return { type: "frame", frame }
      }),
  }
}

export const transport = <Body>(options: Options): Transport<Body, Prepared, string> => {
  const http = HttpTransport.sseJson.with<Body>()
  return {
    id: http.id,
    prepare: (input) =>
      Effect.gen(function* () {
        const parts = yield* HttpTransport.jsonRequestParts(input)
        const headers = Headers.remove(options.headers?.(parts.headers) ?? parts.headers, "content-length")
        const channel =
          input.webSocket && (options.enabled?.(parts.url) ?? true)
            ? yield* Effect.gen(function* () {
                const create = yield* message(parts.jsonBody)
                const base = driver(options, create.message)
                return {
                  url: yield* WebSocketTransport.toWebSocketUrl(options.url?.(parts.url) ?? parts.url),
                  headers,
                  rotateAfterMs: options.rotateAfterMs,
                  driver: OpenResponsesContinuation.driver({
                    id: options.id,
                    name: options.name,
                    request: create.request,
                    message: create.message,
                    base,
                    continuation: options.continuation,
                  }),
                }
              })
            : undefined
        if (input.webSocket && !channel)
          yield* Effect.logWarning(`${options.name} does not offer WebSocket for this endpoint; using HTTP`, {
            url: parts.url,
          })
        return {
          http: {
            request: ProviderShared.jsonPost({
              url: parts.url,
              body: parts.bodyText,
              headers: parts.headers,
              encoding: input.request.http?.encoding,
            }),
            framing: Framing.sse,
            middleware: input.middleware,
          },
          channel,
        }
      }),
    execute: (prepared, request, runtime, executeOptions) =>
      Effect.gen(function* () {
        if (!executeOptions?.webSocket || !prepared.channel) return yield* http.execute(prepared.http, request, runtime)
        let fallbackHttp: HttpContext | undefined
        const exchange: WebSocketChannelExchange = {
          id: request.id ?? "request",
          connect: {
            url: prepared.channel.url,
            headers: prepared.channel.headers,
            rotateAfterMs: prepared.channel.rotateAfterMs,
          },
          fallback: () =>
            Stream.unwrap(
              http.execute(prepared.http, request, runtime).pipe(
                Effect.map((execution) => {
                  fallbackHttp = execution.http
                  return execution.frames
                }),
              ),
            ),
          driver: prepared.channel.driver,
        }
        const execution = yield* executeOptions.webSocket.execute(exchange)
        return {
          frames: execution.frames,
          complete: execution.complete,
          get http() {
            return fallbackHttp ?? execution.http
          },
        }
      }),
  }
}

export const OpenResponsesChannel = { transport } as const

import { AIError, TransportError } from "../schema/index.js"
import type { ChannelCheckpoint, ChannelObservation, WebSocketChannelDriver } from "../route/transport/index.js"
import { Effect, Option, Schema } from "effect"
import * as ProviderShared from "./shared.js"
import { OpenResponses } from "./open-responses.js"

const PROTOCOL = "open-responses.websocket.v1"
const VERSION = 1

interface CheckpointValue {
  readonly version: typeof VERSION
  readonly responseID: string
  readonly request: Readonly<Record<string, unknown>>
  readonly output: ReadonlyArray<unknown>
}

/**
 * Fields to send next to `previous_response_id` on an incremental step, or undefined to send the step in full.
 * Whether omitted fields carry over from the continued response is provider behavior the route must know.
 */
export type Shape = (request: Readonly<Record<string, unknown>>) => Readonly<Record<string, unknown>> | undefined

export interface DriverInput {
  readonly id: string
  readonly name: string
  readonly request: Readonly<Record<string, unknown>>
  readonly message: string
  readonly base: WebSocketChannelDriver
  readonly continuation?: Shape
}

const checkpointValue = (checkpoint: ChannelCheckpoint | undefined): CheckpointValue | undefined => {
  if (checkpoint?.protocol !== PROTOCOL || !ProviderShared.isRecord(checkpoint.value)) return undefined
  if (checkpoint.value.version !== VERSION) return undefined
  if (typeof checkpoint.value.responseID !== "string" || checkpoint.value.responseID.trim().length === 0)
    return undefined
  if (!ProviderShared.isRecord(checkpoint.value.request) || !Array.isArray(checkpoint.value.output)) return undefined
  return {
    version: VERSION,
    responseID: checkpoint.value.responseID,
    request: checkpoint.value.request,
    output: checkpoint.value.output,
  }
}

const canonical = (value: unknown): string => {
  if (value === undefined) return "undefined"
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`
  if (!ProviderShared.isRecord(value)) return ProviderShared.encodeJson(value)
  return `{${Object.keys(value)
    .filter((key) => value[key] !== undefined)
    .sort()
    .map((key) => `${ProviderShared.encodeJson(key)}:${canonical(value[key])}`)
    .join(",")}}`
}

const json = (value: unknown) => {
  if (typeof value !== "string") return value
  return Option.getOrElse(Schema.decodeUnknownOption(ProviderShared.Json)(value), () => value)
}

const comparable = (value: unknown) => {
  if (!ProviderShared.isRecord(value)) return value
  if (value.type === "message" && value.role === "assistant")
    return {
      role: "assistant",
      // Annotations and logprobs describe the response, not the text replayed in model input.
      content: Array.isArray(value.content)
        ? value.content.map((part) =>
            ProviderShared.isRecord(part) && part.type === "output_text" ? { type: part.type, text: part.text } : part,
          )
        : value.content,
      ...(value.phase === undefined ? {} : { phase: value.phase }),
    }
  if (value.type === "function_call")
    return {
      type: value.type,
      call_id: value.call_id,
      name: value.name,
      arguments: json(value.arguments),
    }
  if (value.type === "reasoning")
    return {
      type: value.type,
      summary: value.summary,
      encrypted_content: value.encrypted_content,
    }
  return value
}

const invariant = (request: Readonly<Record<string, unknown>>) => {
  const { type: _type, input: _input, previous_response_id: _previousResponseID, ...rest } = request
  return rest
}

const incremental = (
  request: Readonly<Record<string, unknown>>,
  checkpoint: CheckpointValue,
): ReadonlyArray<unknown> | undefined => {
  const input = request.input
  const previousInput = checkpoint.request.input
  if (!Array.isArray(input) || !Array.isArray(previousInput)) return undefined
  if (canonical(invariant(request)) !== canonical(invariant(checkpoint.request))) return undefined
  const baseline = [...previousInput, ...checkpoint.output]
  if (input.length <= baseline.length) return undefined
  if (!baseline.every((item, index) => canonical(comparable(item)) === canonical(comparable(input[index]))))
    return undefined
  return input.slice(baseline.length)
}

const code = (event: OpenResponses.Event) => OpenResponses.errorDetail(event).code

const rejected = (
  observation: Extract<ChannelObservation, { readonly type: "provider-failure" }>,
  recovery: "retry-full" | "rotate-and-retry-full",
): ChannelObservation => ({
  type: "rejected",
  recovery,
  error: new AIError({
    reason: new TransportError({
      message: observation.error.message,
      body: observation.error.reason.body,
      http: observation.error.reason.http,
      cause: observation.error.reason.cause,
      transport: "websocket",
      operation: "read",
      phase: "receive",
      delivery: "rejected",
      recovery,
    }),
  }),
})

export const driver = (input: DriverInput): WebSocketChannelDriver => {
  const { previous_response_id: _previousResponseID, ...request } = input.request
  const shape = input.continuation ?? ((fields: Readonly<Record<string, unknown>>) => fields)
  let output: OpenResponses.StreamItem[] = []
  return {
    create: (checkpoint) =>
      Effect.sync(() => {
        output = []
        const previous = checkpointValue(checkpoint)
        // Ask the route first: diffing the whole history is wasted when it declines the continuation.
        const fields = previous ? shape(request) : undefined
        const delta = previous && fields ? incremental(request, previous) : undefined
        if (!previous || !fields || !delta)
          return { message: ProviderShared.encodeJson(request), mode: "full" as const }
        return {
          message: ProviderShared.encodeJson({ ...fields, input: delta, previous_response_id: previous.responseID }),
          mode: "incremental" as const,
        }
      }),
    observe: (create, frame) =>
      Effect.gen(function* () {
        const event = yield* OpenResponses.decodeChannelEvent(frame).pipe(
          Effect.mapError((cause) =>
            ProviderShared.eventError(input.id, `Invalid ${input.name} WebSocket event`, frame, cause),
          ),
        )
        const observation = yield* input.base.observe(create, frame)
        if (event.type === "response.output_item.done" && event.item) output.push(event.item)
        if (observation.type === "provider-failure") {
          const rejection = code(event)
          if (rejection === "previous_response_not_found") return rejected(observation, "retry-full")
          if (rejection === "websocket_connection_limit_reached") return rejected(observation, "rotate-and-retry-full")
          // Only the continuation distinguishes an incremental send from a full one, so an unclassified
          // invalid request there is retried full; Codex reports a stale previous_response_id that way, with
          // no code. Classified failures such as context overflow keep their runner-owned recovery.
          if (
            create.mode === "incremental" &&
            observation.error.reason._tag === "InvalidRequest" &&
            observation.error.reason.classification === undefined
          )
            return rejected(observation, "retry-full")
        }
        if (observation.type !== "completed") return observation
        // A trigger installs a different context window. Clear the append baseline, retaining the socket.
        if (
          Array.isArray(request.input) &&
          request.input.some((item) => ProviderShared.isRecord(item) && item.type === "compaction_trigger")
        )
          return observation
        const responseID = event.response?.id
        if (!responseID || responseID.trim().length === 0) return observation
        return {
          ...observation,
          checkpoint: {
            protocol: PROTOCOL,
            value: {
              version: VERSION,
              responseID,
              request,
              // Completion can re-encrypt reasoning. Callers replay the item already emitted by output_item.done.
              output: event.response?.output?.length
                ? event.response.output.map((item) =>
                    item.type === "reasoning" && item.id !== undefined
                      ? (output.find((done) => done.type === item.type && done.id === item.id) ?? item)
                      : item,
                  )
                : output.slice(),
            } satisfies CheckpointValue,
          },
        }
      }),
  }
}

export * as OpenResponsesContinuation from "./open-responses-continuation.js"

import { Effect, Option, Schema } from "effect"
import type { Content } from "@opencode/schema/tool"
