import { Schema } from "effect"
import { Allow } from "./partial-json-options.js"
export * from "./partial-json-options.js"

export class PartialJSON extends Error {}
export class MalformedJSON extends Error {}

const decodeJson = Schema.decodeUnknownSync(Schema.fromJsonString(Schema.Unknown))

/** Parse complete or incomplete JSON, restricted by the supplied partial-value flags. */
export function parseJSON(jsonString: string, allowPartial = Allow.ALL): unknown {
  if (typeof jsonString !== "string") throw new TypeError(`expecting str, got ${typeof jsonString}`)
  const input = jsonString.trim()
  if (!input) throw new Error(`${jsonString} is empty`)
  try {
    return decodeJson(input)
  } catch {}

  const repaired = repairJSON(input)
  if (repaired !== input) {
    try {
      return decodeJson(repaired)
    } catch {}
  }

  try {
    return _parseJSON(input, allowPartial)
  } catch (error) {
    if (repaired !== input) return _parseJSON(repaired, allowPartial)
    throw error
  }
}

const repairJSON = (input: string) => {
  let repaired = ""
  let quoted = false

  for (let index = 0; index < input.length; index++) {
    const character = input[index]
    if (!quoted) {
      repaired += character
      if (character === '"') quoted = true
      continue
    }

    if (character === '"') {
      repaired += character
      quoted = false
      continue
    }

    if (character === "\\") {
      const next = input[index + 1]
      if (next === "u" && /^[0-9a-fA-F]{4}$/.test(input.slice(index + 2, index + 6))) {
        repaired += input.slice(index, index + 6)
        index += 5
        continue
      }
      if (next !== undefined && '"\\/bfnrtu'.includes(next)) {
        repaired += `\\${next}`
        index++
        continue
      }
      repaired += "\\\\"
      continue
    }

    const code = character.charCodeAt(0)
    repaired += code <= 0x1f ? `\\u${code.toString(16).padStart(4, "0")}` : character
  }

  return repaired
}

const _parseJSON = (jsonString: string, allow: number) => {
  const length = jsonString.length
  let index = 0

  const markPartialJSON = (message: string): never => {
    throw new PartialJSON(`${message} at position ${index}`)
  }

  const throwMalformedError = (message: string): never => {
    throw new MalformedJSON(`${message} at position ${index}`)
  }

  const parseAny = (): unknown => {
    skipBlank()
    if (index >= length) markPartialJSON("Unexpected end of input")
    if (jsonString[index] === '"') return parseStr()
    if (jsonString[index] === "{") return parseObj()
    if (jsonString[index] === "[") return parseArr()
    if (
      jsonString.substring(index, index + 4) === "null" ||
      (Allow.NULL & allow && length - index < 4 && "null".startsWith(jsonString.substring(index)))
    ) {
      index += 4
      return null
    }
    if (
      jsonString.substring(index, index + 4) === "true" ||
      (Allow.BOOL & allow && length - index < 4 && "true".startsWith(jsonString.substring(index)))
    ) {
      index += 4
      return true
    }
    if (
      jsonString.substring(index, index + 5) === "false" ||
      (Allow.BOOL & allow && length - index < 5 && "false".startsWith(jsonString.substring(index)))
    ) {
      index += 5
      return false
    }
    if (
      jsonString.substring(index, index + 8) === "Infinity" ||
      (Allow.INFINITY & allow && length - index < 8 && "Infinity".startsWith(jsonString.substring(index)))
    ) {
      index += 8
      return Infinity
    }
    if (
      jsonString.substring(index, index + 9) === "-Infinity" ||
      (Allow._INFINITY & allow &&
        1 < length - index &&
        length - index < 9 &&
        "-Infinity".startsWith(jsonString.substring(index)))
    ) {
      index += 9
      return -Infinity
    }
    if (
      jsonString.substring(index, index + 3) === "NaN" ||
      (Allow.NAN & allow && length - index < 3 && "NaN".startsWith(jsonString.substring(index)))
    ) {
      index += 3
      return NaN
    }
    return parseNum()
  }

  const parseStr = (): string => {
    const start = index
    let escape = false
    index++
    while (index < length && (jsonString[index] !== '"' || (escape && jsonString[index - 1] === "\\"))) {
      escape = jsonString[index] === "\\" ? !escape : false
      index++
    }
    if (jsonString.charAt(index) === '"') {
      try {
        return decodeJson(jsonString.substring(start, ++index - Number(escape))) as string
      } catch (error) {
        throwMalformedError(String(error))
      }
    }
    if (Allow.STR & allow) {
      try {
        return decodeJson(`${jsonString.substring(start, index - Number(escape))}"`) as string
      } catch {
        return decodeJson(`${jsonString.substring(start, jsonString.lastIndexOf("\\"))}"`) as string
      }
    }
    return markPartialJSON("Unterminated string literal")
  }

  const parseObj = (): Record<string, unknown> => {
    index++
    skipBlank()
    const object: Record<string, unknown> = {}
    try {
      while (jsonString[index] !== "}") {
        skipBlank()
        if (index >= length && Allow.OBJ & allow) return object
        const key = parseStr()
        skipBlank()
        index++
        try {
          Object.defineProperty(object, key, {
            value: parseAny(),
            enumerable: true,
            configurable: true,
            writable: true,
          })
        } catch (error) {
          if (Allow.OBJ & allow) return object
          throw error
        }
        skipBlank()
        if (jsonString[index] === ",") index++
      }
    } catch {
      if (Allow.OBJ & allow) return object
      return markPartialJSON("Expected '}' at end of object")
    }
    index++
    return object
  }

  const parseArr = (): unknown[] => {
    index++
    const array: unknown[] = []
    try {
      while (jsonString[index] !== "]") {
        array.push(parseAny())
        skipBlank()
        if (jsonString[index] === ",") index++
      }
    } catch {
      if (Allow.ARR & allow) return array
      return markPartialJSON("Expected ']' at end of array")
    }
    index++
    return array
  }

  const parseNum = (): unknown => {
    if (index === 0) {
      if (jsonString === "-") throwMalformedError("Not sure what '-' is")
      try {
        return decodeJson(jsonString)
      } catch (error) {
        if (Allow.NUM & allow) {
          try {
            return decodeJson(jsonString.substring(0, jsonString.lastIndexOf("e")))
          } catch {}
        }
        throwMalformedError(String(error))
      }
    }

    const start = index
    if (jsonString[index] === "-") index++
    while (jsonString[index] && !",]}".includes(jsonString[index])) index++
    if (index === length && !(Allow.NUM & allow)) markPartialJSON("Unterminated number literal")

    try {
      return decodeJson(jsonString.substring(start, index))
    } catch (error) {
      if (jsonString.substring(start, index) === "-") markPartialJSON("Not sure what '-' is")
      try {
        return decodeJson(jsonString.substring(start, jsonString.lastIndexOf("e")))
      } catch {
        throwMalformedError(String(error))
      }
    }
  }

  const skipBlank = () => {
    while (index < length && " \n\r\t".includes(jsonString[index])) index++
  }

  return parseAny()
}

export const parse = parseJSON

import { Effect, Schema, Stream } from "effect"
import { Route, type RouteBody, type TriggerCompactOperation } from "../../route/client.js"
import { Protocol } from "../../route/protocol.js"
import { CompactionCheckpointResponse, LLMEvent, LLMRequest } from "../../schema/index.js"
import { OpenResponses } from "../open-responses.js"
import { ProviderShared } from "../shared.js"

interface State {
  readonly parser: Pick<OpenResponses.ParserState, "id" | "provider" | "outputItems">
  readonly checkpoints: Readonly<Record<string, CompactionCheckpointResponse["checkpoint"]>>
  readonly responseID?: string
}

const onOutputItem = Effect.fnUntraced(function* (
  state: State,
  input: OpenResponses.Event,
) {
  const event = OpenResponses.normalize(state.parser, input)
  const item = event.item
  if (!item) return state
  const parser =
    event.output_index === undefined || state.parser.outputItems[event.output_index] === item.id
      ? state.parser
      : { ...state.parser, outputItems: { ...state.parser.outputItems, [event.output_index]: item.id } }
  const next = parser === state.parser ? state : { ...state, parser }
  if (event.type === "response.output_item.added" || item.type !== "compaction") return next
  if (
    event.output_index !== undefined &&
    Object.entries(state.parser.outputItems).some(
      ([index, id]) => id === item.id && Number(index) !== event.output_index,
    )
  )
    return yield* ProviderShared.eventError(parser.id, "Compaction checkpoint appeared in multiple output slots")
  if (!item.encrypted_content)
    return yield* ProviderShared.eventError(parser.id, "Compaction output is missing its encrypted content")
  const previous = state.checkpoints[item.id]
  if (previous && previous.encrypted !== item.encrypted_content)
    return yield* ProviderShared.eventError(parser.id, "Compaction output changed after completion")
  if (previous) return next
  return {
    ...next,
    checkpoints: {
      ...state.checkpoints,
      [item.id]: { type: "compaction", provider: parser.provider, id: item.id, encrypted: item.encrypted_content },
    },
  } satisfies State
})

/** Collect a trigger response before acknowledging transport completion. No generation output escapes. */
export const make = <Body>(body: RouteBody<Body>): TriggerCompactOperation =>
  Effect.fn("ResponsesCheckpoint.execute")(function* (request, executor, options) {
    const source = request.model.route
    let result: CompactionCheckpointResponse | undefined
    // Route registries erase the frame type. The codec validates that boundary before parsing.
    const event: Schema.Codec<OpenResponses.Event, unknown> = OpenResponses.protocol.stream.event
    const protocol = Protocol.make({
      id: source.protocol,
      body,
      stream: {
        event,
        initial: (request: LLMRequest): State => ({
          parser: { id: source.id, provider: request.model.provider, outputItems: {} },
          checkpoints: {},
        }),
        terminal: OpenResponses.terminal,
        step: Effect.fnUntraced(function* (state: State, event: OpenResponses.Event) {
          if (event.response?.id && state.responseID && event.response.id !== state.responseID)
            return yield* ProviderShared.eventError(source.id, "Compaction response ID changed during execution")
          if (event.type === "response.created") return [{ ...state, responseID: event.response?.id }, []] as const
          if (event.type === "error" || event.type === "response.failed")
            return yield* OpenResponses.providerFailure(event, "Compaction request failed")
          if (event.type === "response.incomplete")
            return yield* ProviderShared.eventError(source.id, "Compaction response was incomplete")
          if (event.type === "response.output_item.added" || event.type === "response.output_item.done")
            return [yield* onOutputItem(state, event), []] as const
          if (event.type !== "response.completed") return [state, []] as const
          const responseID = event.response?.id
          if (!responseID?.trim())
            return yield* ProviderShared.eventError(source.id, "Compaction response is missing its response ID")
          if (event.response?.status !== undefined && event.response.status !== "completed")
            return yield* ProviderShared.eventError(source.id, "Compaction response did not complete successfully")
          let next = state
          for (const [index, item] of (event.response?.output ?? []).entries()) {
            next = yield* onOutputItem(next, { type: "response.output_item.done", output_index: index, item })
          }
          const checkpoints = Object.values(next.checkpoints)
          const checkpoint = checkpoints[0]
          if (checkpoints.length !== 1 || !checkpoint)
            return yield* ProviderShared.eventError(
              source.id,
              "Compaction response must contain exactly one checkpoint",
            )
          result = new CompactionCheckpointResponse({
            checkpoint,
            responseID,
            usage: OpenResponses.mapUsage(event.response?.usage, OpenResponses.metadataKey(request.model)),
          })
          return [next, [LLMEvent.finish({ reason: { normalized: "stop" } })]] as const
        }),
      },
    })
    const route = Route.make({
      id: source.id,
      provider: source.provider,
      providerMetadataKey: source.providerMetadataKey,
      protocol,
      endpoint: source.endpoint,
      auth: source.auth,
      transport: source.transport,
    })
    const native = yield* body.from(request)
    const prepared = yield* route.prepareTransport(native, request, options)
    yield* route.streamPrepared(prepared, request, { http: executor }, options).pipe(Stream.runDrain)
    if (!result) return yield* ProviderShared.eventError(source.id, "Compaction response ended without a checkpoint")
    return result
  })

