        nullable: "route",
        primitive: "route",
      },
      {
        include: ["model"],
        metadata: { model: true, shared: "model" },
        nullable: null,
        primitive: "model",
      },
      { metadata: { request: true }, primitive: false },
    )

    expect(merged).toEqual({
      include: ["model"],
