      Effect.provide(
        dynamicResponse((input) =>
          Effect.gen(function* () {
            const web = yield* HttpClientRequest.toWeb(input.request).pipe(Effect.orDie)
            expect(web.url).toBe("https://proxy.test/v1/chat/completions")
            expect(web.method).toBe("PUT")
            expect(web.headers.get("x-plugin")).toBe("transformed")
            expect(web.headers.get("content-type")).toBe("application/custom+json")
            expect(decodeJson(input.text)).toEqual({ transformed: true })
            return input.respond(sseEvents(deltaChunk({}, "stop")), {
              headers: { "content-type": "text/event-stream" },
            })
          }),
        ),
      ),
    ),
  )

  it.effect("transforms the HTTP response before protocol decoding", () =>
    Effect.gen(function* () {
      const response = yield* LLMClient.generate(
        LLM.request({
          model: OpenAIChat.route
            .with({ endpoint: { baseURL: "https://api.openai.test/v1/" }, auth: Auth.bearer("test") })
            .model({ id: "gpt-4o-mini" }),
          prompt: "Say hello.",
        }),
        {
          http: (request, handler) =>
            Effect.gen(function* () {
              const response = yield* handler(request)
              return HttpClientResponse.fromWeb(
                response.request,
                new Response((yield* response.text).replace("network", "hooked"), {
                  status: response.status,
                  headers: response.headers,
                }),
              )
            }),
        },
      ).pipe(
        Effect.provide(
          dynamicResponse((input) =>
            Effect.succeed(
              input.respond(sseEvents(deltaChunk({ content: "network" }, "stop")), {
                headers: { "content-type": "text/event-stream" },
              }),
            ),
          ),
        ),
      )

      expect(response.text).toBe("hooked")
    }),
  )

  it.effect("can inspect an error response and retry the native request", () =>
    Effect.gen(function* () {
      const attempts = yield* Ref.make(0)
      const response = yield* LLMClient.generate(
        LLM.request({
          model: OpenAIChat.route
            .with({ endpoint: { baseURL: "https://api.openai.test/v1/" }, auth: Auth.bearer("stale") })
            .model({ id: "gpt-4o-mini" }),
          prompt: "Say hello.",
        }),
        {
          http: (request, handler) =>
            Effect.gen(function* () {
              const response = yield* handler(request)
              expect(response.status).toBe(401)
              return yield* handler(HttpClientRequest.setHeader(request, "authorization", "Bearer refreshed"))
            }),
        },
      ).pipe(
        Effect.provide(
          dynamicResponse((input) =>
            Effect.gen(function* () {
              yield* Ref.update(attempts, (value) => value + 1)
              if (input.request.headers.authorization !== "Bearer refreshed")
                return input.respond("unauthorized", { status: 401 })
              return input.respond(sseEvents(deltaChunk({ content: "retried" }, "stop")), {
                headers: { "content-type": "text/event-stream" },
              })
            }),
          ),
        ),
      )

      expect(response.text).toBe("retried")
      expect(yield* Ref.get(attempts)).toBe(2)
    }),
  )

  it.effect("sanitizes outbound JSON without an HTTP overlay", () =>
    LLMClient.generate(
      LLM.request({
        model: OpenAIChat.route
          .with({ endpoint: { baseURL: "https://api.openai.test/v1/" }, auth: Auth.bearer("test") })
          .model({ id: "gpt-4o-mini" }),
        prompt: "hello \uD800 \u{1F600}",
      }),
    ).pipe(
      Effect.provide(
        dynamicResponse((input) =>
          Effect.gen(function* () {
            expect(decodeJson(input.text)).toMatchObject({
              messages: [{ role: "user", content: "hello \uFFFD \u{1F600}" }],
            })
            return input.respond(sseEvents(deltaChunk({}, "stop")), {
              headers: { "content-type": "text/event-stream" },
            })
          }),
        ),
      ),
    ),
  )

  it.effect("sanitizes unpaired surrogates throughout outbound JSON", () =>
    LLMClient.generate(
      LLM.request({
        model: OpenAIChat.route
          .with({ endpoint: { baseURL: "https://api.openai.test/v1/" }, auth: Auth.bearer("test") })
          .model({ id: "gpt-4o-mini" }),
        system: "system \uD800 \u{1F600}",
        messages: [
          Message.user("user \uDC00"),
          Message.assistant([
            Message.text("assistant \uD800"),
            ToolCallPart.make({ id: "call_1", name: "lookup", input: { query: "input \uDC00" } }),
          ]),
          Message.tool({ id: "call_1", name: "lookup", result: { output: "result \uD800" } }),
        ],
        http: { body: { metadata: { "key\uD800": ["overlay \uDC00", "valid \u{1F600}"] } } },
      }),
    ).pipe(
      Effect.provide(
        dynamicResponse((input) =>
          Effect.gen(function* () {
            expect(decodeJson(input.text)).toMatchObject({
              messages: [
                { role: "system", content: "system \uFFFD \u{1F600}" },
                { role: "user", content: "user \uFFFD" },
                {
                  role: "assistant",
                  content: "assistant \uFFFD",
                  tool_calls: [{ function: { arguments: '{"query":"input \uFFFD"}' } }],
                },
                { role: "tool", content: '{"output":"result \uFFFD"}' },
              ],
              metadata: { "key\uFFFD": ["overlay \uFFFD", "valid \u{1F600}"] },
            })
            return input.respond(sseEvents(deltaChunk({}, "stop")), {
              headers: { "content-type": "text/event-stream" },
            })
          }),
        ),
      ),
    ),
  )

  it.effect("applies raw body overlays after protocol lowering", () =>
    LLMClient.generate(
      LLM.request({
        model: OpenAIChat.route
          .with({ endpoint: { baseURL: "https://api.openai.test/v1/" }, auth: Auth.bearer("test") })
          .model({ id: "gpt-4o-mini" }),
        prompt: "Say hello.",
        http: { body: { model: "gpt-5", messages: [], tools: [] } },
      }),
    ).pipe(
      Effect.provide(
        dynamicResponse((input) =>
          Effect.gen(function* () {
            expect(decodeJson(input.text)).toMatchObject({ model: "gpt-5", messages: [], tools: [] })
            return input.respond(sseEvents(deltaChunk({}, "stop")), {
              headers: { "content-type": "text/event-stream" },
            })
          }),
        ),
      ),
    ),
  )

  it.effect("uses the Anthropic default before call maxTokens", () =>
    Effect.gen(function* () {
      const route = AnthropicMessages.route.with({
        endpoint: { baseURL: "https://api.anthropic.test/v1/" },
        auth: Auth.header("x-api-key", "test"),
      })
      const model = route.model({ id: "claude-sonnet-4-5" })
      const withoutMaxTokens = yield* compileRequest(LLM.request({ model, prompt: "Say hello.", cache: "none" }))
      const withMaxTokens = yield* compileRequest(
        LLM.request({ model, prompt: "Say hello.", cache: "none", generation: { maxTokens: 8_000 } }),
      )

      expect(withoutMaxTokens.body.max_tokens).toBe(32_000)
      expect(withMaxTokens.body.max_tokens).toBe(8_000)
    }),
  )
})

import {
  LLM,
  Media,
  Message,
  ToolCallPart,
  ToolDefinition,
  ToolResultPart,
  type ContentPart,
  type LanguageModel,
} from "../src/index.js"

export const basicContinuation = ["system", "user-text", "assistant-text", "user-follow-up"] as const
export const toolContinuation = ["tool-call", "tool-result"] as const
export const reasoningContinuation = ["assistant-reasoning", "encrypted-reasoning"] as const
export const mediaContinuation = ["user-image"] as const
export const maximalContinuation = [
  ...basicContinuation,
  ...toolContinuation,
  ...reasoningContinuation,
  ...mediaContinuation,
] as const

export type ContinuationFeature = (typeof maximalContinuation)[number]

export const nativeOpenAIResponsesContinuation = [
  ...basicContinuation,
  ...toolContinuation,
  "encrypted-reasoning",
  ...mediaContinuation,
] as const satisfies ReadonlyArray<ContinuationFeature>

export const nativeAnthropicMessagesContinuation = [
  ...basicContinuation,
  ...toolContinuation,
  "assistant-reasoning",
  ...mediaContinuation,
] as const satisfies ReadonlyArray<ContinuationFeature>

export const continuationTool = ToolDefinition.make({
  name: "get_weather",
  description: "Get current weather for a city.",
  inputSchema: {
    type: "object",
    properties: { city: { type: "string" } },
    required: ["city"],
    additionalProperties: false,
  },
})

export function continuationRequest(input: {
  readonly id: string
  readonly model: LanguageModel
  readonly features: ReadonlyArray<ContinuationFeature>
  readonly image?: string
}) {
  const features = new Set(input.features)
  const messages = []
  const firstUser: ContentPart[] = []
  const firstAssistant: ContentPart[] = []

  if (features.has("user-text")) firstUser.push({ type: "text", text: "What is shown here?" })
  if (features.has("user-image"))
    firstUser.push({ type: "media", media: Media.base64(input.image ?? "AAECAw==", "image/png") })
  if (firstUser.length > 0) messages.push(Message.user(firstUser))

  if (features.has("assistant-reasoning"))
    firstAssistant.push({
      type: "reasoning",
      text: "I inspected the previous turn.",
      providerMetadata: { anthropic: { signature: "sig_continuation_1" } },
    })
  if (features.has("encrypted-reasoning"))
    firstAssistant.push({
      type: "reasoning",
      text: "I inspected the previous turn.",
      providerMetadata: {
        openai: {
          itemId: "rs_continuation_1",
          reasoningEncryptedContent: "encrypted-continuation-state",
        },
      },
    })
  if (features.has("assistant-text")) firstAssistant.push({ type: "text", text: "It shows a small test image." })
  if (firstAssistant.length > 0) messages.push(Message.assistant(firstAssistant))

  if (features.has("tool-call")) {
    messages.push(Message.user("Check the weather in Paris before continuing."))
    messages.push(
      Message.assistant([ToolCallPart.make({ id: "call_weather_1", name: "get_weather", input: { city: "Paris" } })]),
    )
  }
  if (features.has("tool-result")) {
    messages.push(
      Message.tool(ToolResultPart.make({ id: "call_weather_1", name: "get_weather", result: { temperature: 22 } })),
    )
    if (features.has("assistant-text")) messages.push(Message.assistant("Paris is 22 degrees."))
  }
  if (features.has("user-follow-up"))
    messages.push(Message.user("Continue from this conversation in one short sentence."))

  return LLM.request({
    id: input.id,
    model: input.model,
    system: features.has("system") ? "You are concise. Continue from the provided history." : undefined,
    messages,
    tools: features.has("tool-call") ? [continuationTool] : [],
    cache: "none",
    providerOptions: features.has("encrypted-reasoning")
      ? { store: false, include: ["reasoning.encrypted_content"], reasoningSummary: "auto" }
      : undefined,
    generation: { maxTokens: 80, temperature: 0 },
  })
}

import { describe, expect, test } from "bun:test"
import { Effect } from "effect"
import { LLM, Message, ToolCallPart } from "../src/index.js"
import { Auth, LLMClient } from "../src/route.js"
import { compileRequest } from "../src/route/client.js"
import { AnthropicMessages } from "../src/protocols/anthropic-messages.js"
import { OpenAIResponses } from "../src/protocols/openai-responses.js"
import { Gemini } from "../src/protocols/gemini.js"
import { AmazonBedrockMantle, GoogleVertexMessages, OpenAI } from "../src/providers.js"
import { applyEffortUpdates } from "../src/effort-updates.js"
import { it, testEffect } from "./lib/effect.js"
import { dynamicResponse } from "./lib/http.js"
import { sseEvents } from "./lib/sse.js"

const anthropic = (id: string, compatibility?: { readonly supportsEffortUpdates?: boolean }) =>
  AnthropicMessages.route
    .with({ endpoint: { baseURL: "https://api.anthropic.test/v1/" }, auth: Auth.header("x-api-key", "test") })
    .model({ id, compatibility })

const openai = (id: string, compatibility?: { readonly supportsEffortUpdates?: boolean }) =>
  OpenAIResponses.route
    .with({ endpoint: { baseURL: "https://api.openai.test/v1/" }, auth: Auth.bearer("test") })
    .model({ id, compatibility })

const opus5 = anthropic("claude-opus-5")
const astra = openai("gpt-6-astra")

const lowFromHigh = Message.effort({ effort: "low", previous: "high" })
const conversation = [Message.user("Before."), lowFromHigh, Message.user("After.")]

const systemMessages = (body: AnthropicMessages.AnthropicMessagesBody) =>
  body.messages.filter((message) => message.role === "system")

const updates = (body: OpenAIResponses.OpenAIResponsesBody) =>
  body.input.filter((item) => "type" in item && item.type === "configuration_update")

describe("applyEffortUpdates", () => {
  test("keeps the request identity without markers and for protocols that lower them", () => {
    const plain = LLM.request({ model: opus5, prompt: "hi" })
    expect(applyEffortUpdates(plain)).toBe(plain)

    const supported = LLM.request({ model: opus5, messages: conversation, providerOptions: { effort: "low" } })
    expect(applyEffortUpdates(supported)).toBe(supported)
  })

  it.effect("compiles markers away for protocols without per-message effort", () =>
    Effect.gen(function* () {
      const model = Gemini.route
        .with({
          endpoint: { baseURL: "https://generativelanguage.test/v1beta/" },
          auth: Auth.header("x-goog-api-key", "test"),
        })
        .model({ id: "gemini-3.5-flash" })
      const withMarkers = yield* compileRequest(LLM.request({ model, messages: conversation }))
      const withoutMarkers = yield* compileRequest(
        LLM.request({ model, messages: [Message.user("Before."), Message.user("After.")] }),
      )

      expect(withMarkers.body).toEqual(withoutMarkers.body)
    }),
  )
})

describe("cache policy", () => {
  it.effect("walks the tail breakpoint back past a trailing effort marker", () =>
    Effect.gen(function* () {
      const prepared = yield* compileRequest(
        LLM.request({
          model: opus5,
          messages: [Message.user("first"), Message.assistant("reply"), Message.user("latest"), lowFromHigh],
          providerOptions: { effort: "low" },
          cache: "auto",
        }),
      )

      expect(prepared.body.messages).toEqual([
        { role: "user", content: [{ type: "text", text: "first" }] },
        { role: "assistant", content: [{ type: "text", text: "reply" }] },
        { role: "user", content: [{ type: "text", text: "latest", cache_control: { type: "ephemeral" } }] },
        { role: "system", content: [], output_config: { effort: "low" } },
      ])
    }),
  )
})

