    Effect.gen(function* () {
      const error = yield* Evaluation.run({
        model: TypeSafeAI.experimental.evaluation("jev-latest"),
        state: "hello",
        questions: { score: { type: "score", instructions: "How much?", criteria: ["only"] } },
