import { test, type TestOptions } from "bun:test"
import { Cause, Effect, Exit, Layer } from "effect"
import type * as Scope from "effect/Scope"
import * as TestClock from "effect/testing/TestClock"
import * as TestConsole from "effect/testing/TestConsole"

type Body<A, E, R> = Effect.Effect<A, E, R> | (() => Effect.Effect<A, E, R>)

const body = <A, E, R>(value: Body<A, E, R>) => Effect.suspend(() => (typeof value === "function" ? value() : value))

const run = <A, E, R, E2>(value: Body<A, E, R | Scope.Scope>, layer: Layer.Layer<R, E2>) =>
  Effect.gen(function* () {
    const exit = yield* body(value).pipe(Effect.scoped, Effect.provide(layer), Effect.exit)
    if (Exit.isFailure(exit)) {
      for (const err of Cause.prettyErrors(exit.cause)) {
        yield* Effect.logError(err)
      }
    }
    return yield* exit
  }).pipe(Effect.runPromise)

const make = <R, E>(testLayer: Layer.Layer<R, E>, liveLayer: Layer.Layer<R, E>) => {
  const effect = <A, E2>(name: string, value: Body<A, E2, R | Scope.Scope>, opts?: number | TestOptions) =>
    test(name, () => run(value, testLayer), opts)

  effect.only = <A, E2>(name: string, value: Body<A, E2, R | Scope.Scope>, opts?: number | TestOptions) =>
    test.only(name, () => run(value, testLayer), opts)

  effect.skip = <A, E2>(name: string, value: Body<A, E2, R | Scope.Scope>, opts?: number | TestOptions) =>
    test.skip(name, () => run(value, testLayer), opts)

  const live = <A, E2>(name: string, value: Body<A, E2, R | Scope.Scope>, opts?: number | TestOptions) =>
    test(name, () => run(value, liveLayer), opts)

  live.only = <A, E2>(name: string, value: Body<A, E2, R | Scope.Scope>, opts?: number | TestOptions) =>
    test.only(name, () => run(value, liveLayer), opts)

  live.skip = <A, E2>(name: string, value: Body<A, E2, R | Scope.Scope>, opts?: number | TestOptions) =>
    test.skip(name, () => run(value, liveLayer), opts)

  return { effect, live }
}

const testEnv = Layer.mergeAll(TestConsole.layer, TestClock.layer())
const liveEnv = TestConsole.layer

export const it = make(testEnv, liveEnv)

export const testEffect = <R, E>(layer: Layer.Layer<R, E>) =>
  make(Layer.provideMerge(layer, testEnv), Layer.provideMerge(layer, liveEnv))

import { Effect } from "effect"

/**
 * Run an effect with `process.env` overrides, restoring the previous values
 * afterwards. Use for code that reads `process.env` directly, such as AWS SDK
 * credential providers, where Effect `ConfigProvider` layers do not apply.
 * `undefined` removes a variable for the duration of the effect.
 */
export const withProcessEnv =
  (env: Record<string, string | undefined>) =>
  <A, E, R>(effect: Effect.Effect<A, E, R>) =>
    Effect.acquireUseRelease(
      Effect.sync(() => {
        const previous = Object.fromEntries(Object.keys(env).map((name) => [name, process.env[name]]))
        apply(env)
        return previous
      }),
      () => effect,
      (previous) => Effect.sync(() => apply(previous)),
    )

const apply = (env: Record<string, string | undefined>) => {
  for (const [name, value] of Object.entries(env)) {
    if (value === undefined) {
      delete process.env[name]
      continue
    }
    process.env[name] = value
  }
}

import { Effect, Fiber, Layer, Ref } from "effect"
import * as TestClock from "effect/testing/TestClock"
import { HttpClient, HttpClientError, HttpClientRequest, HttpClientResponse } from "effect/http"
import { LLMClient, RequestExecutor } from "../../src/route.js"
import type { Service as LLMClientService } from "../../src/route/client.js"
import type { Service as RequestExecutorService } from "../../src/route/executor.js"

export type HandlerInput = {
  readonly request: HttpClientRequest.HttpClientRequest
  readonly text: string
  readonly respond: (
    body: ConstructorParameters<typeof Response>[0],
    init?: ResponseInit,
  ) => HttpClientResponse.HttpClientResponse
}

export type Handler = (
  input: HandlerInput,
) => Effect.Effect<HttpClientResponse.HttpClientResponse, HttpClientError.HttpClientError>

export interface Call {
  readonly method: string
  readonly url: string
  readonly headers: Headers
  readonly body: string
}

/** Record every request and tell the handler how many times this exact method+URL has been seen (1-based). */
export const observe = (calls: Array<Call>, input: HandlerInput) =>
  Effect.gen(function* () {
    const web = yield* HttpClientRequest.toWeb(input.request).pipe(Effect.orDie)
    const call = { method: web.method, url: web.url, headers: web.headers, body: input.text }
    calls.push(call)
    return { call, nth: calls.filter((seen) => seen.method === call.method && seen.url === call.url).length }
  })

export const json = (input: HandlerInput, value: unknown, init?: ResponseInit) =>
  input.respond(JSON.stringify(value), { ...init, headers: { "content-type": "application/json", ...init?.headers } })

/** Fork the polling program, let the test clock cover `seconds` of polling, and join. */
export const settle = <A, E, R>(program: Effect.Effect<A, E, R>, seconds: number) =>
  Effect.gen(function* () {
    const fiber = yield* Effect.forkChild(program)
    yield* TestClock.adjust(`${seconds} seconds`)
    return yield* Fiber.join(fiber)
  })

export const handlerLayer = (handler: Handler): Layer.Layer<HttpClient.HttpClient> =>
  Layer.succeed(
    HttpClient.HttpClient,
    HttpClient.make((request) =>
      Effect.gen(function* () {
        const web = yield* HttpClientRequest.toWeb(request).pipe(Effect.orDie)
        const text = yield* Effect.promise(() => web.text())
        return yield* handler({
          request,
          text,
          respond: (body, init) => HttpClientResponse.fromWeb(request, new Response(body, init)),
        })
      }),
    ),
  )

export type RuntimeEnv = RequestExecutorService | LLMClientService

export interface SystemError extends Error {
  readonly code: string
}

export const systemError = (code: string, message: string): SystemError => Object.assign(new Error(message), { code })

export const runtimeLayer = (layer: Layer.Layer<HttpClient.HttpClient>): Layer.Layer<RuntimeEnv> => {
  const requestExecutorLayer = RequestExecutor.layer.pipe(Layer.provide(layer))
  const llmClientLayer = LLMClient.layer.pipe(Layer.provide(requestExecutorLayer))
  return Layer.mergeAll(requestExecutorLayer, llmClientLayer)
}

const SSE_HEADERS = { "content-type": "text/event-stream" } as const

/**
 * Layer that returns a single fixed response body. Use for stream-parser
 * fixture tests where the request shape is irrelevant. The body type widens
 * to whatever `Response` accepts so binary fixtures (`Uint8Array`,
 * `ReadableStream`, etc.) flow through without casts.
 */
export const fixedResponse = (
  body: ConstructorParameters<typeof Response>[0],
  init: ResponseInit = { headers: SSE_HEADERS },
) => runtimeLayer(handlerLayer((input) => Effect.succeed(input.respond(body, init))))

/**
 * Layer that builds a response per request. Useful for echo servers.
 */
export const dynamicResponse = (handler: Handler) => runtimeLayer(handlerLayer(handler))

/**
 * Layer that emits the supplied SSE chunks and then aborts mid-stream. Used to
 * exercise transport errors that surface during parsing.
 */
export const truncatedStream = (chunks: ReadonlyArray<string>, error: Error = new Error("connection reset")) =>
  dynamicResponse((input) =>
    Effect.sync(() => {
      const encoder = new TextEncoder()
      let index = 0
      const stream = new ReadableStream({
        pull(controller) {
          const chunk = chunks[index]
          if (chunk !== undefined) {
            index++
            controller.enqueue(encoder.encode(chunk))
            return
          }
          controller.error(error)
        },
      })
      return input.respond(stream, { headers: SSE_HEADERS })
    }),
  )

/**
 * Layer that returns successive bodies on each request. Useful for scripting
 * multi-step model exchanges (e.g. tool-call loops). The last body in the
 * array is reused if the test makes more requests than scripted.
 */
export const scriptedResponses = (bodies: ReadonlyArray<string>, init: ResponseInit = { headers: SSE_HEADERS }) => {
  if (bodies.length === 0) throw new Error("scriptedResponses requires at least one body")
  return Layer.unwrap(
    Effect.gen(function* () {
      const cursor = yield* Ref.make(0)
      return dynamicResponse((input) =>
        Effect.gen(function* () {
          const index = yield* Ref.getAndUpdate(cursor, (n) => n + 1)
          return input.respond(bodies[index] ?? bodies[bodies.length - 1], init)
        }),
      )
    }),
  )
}

export const dimensions = (data: Uint8Array) => {
  if (data[0] === 0x89 && data[1] === 0x50 && data[2] === 0x4e && data[3] === 0x47)
    return {
      width: readUint32(data, 16),
      height: readUint32(data, 20),
    }
  if (data[0] === 0xff && data[1] === 0xd8) {
    for (let offset = 2; offset + 8 < data.length; ) {
      if (data[offset] !== 0xff) {
        offset++
        continue
      }
      const marker = data[offset + 1]
      if (
        marker !== undefined &&
        [0xc0, 0xc1, 0xc2, 0xc3, 0xc5, 0xc6, 0xc7, 0xc9, 0xca, 0xcb, 0xcd, 0xce, 0xcf].includes(marker)
      )
        return {
          width: (data[offset + 7] << 8) | data[offset + 8],
          height: (data[offset + 5] << 8) | data[offset + 6],
        }
      offset += 2 + ((data[offset + 2] << 8) | data[offset + 3])
    }
  }
  throw new Error("Unsupported image fixture format")
}

const readUint32 = (data: Uint8Array, offset: number) =>
  ((data[offset] << 24) | (data[offset + 1] << 16) | (data[offset + 2] << 8) | data[offset + 3]) >>> 0

/**
 * Shared chunk shapes for OpenAI Chat / OpenAI-compatible Chat fixture tests.
 * Multiple test files build the same `{ id, choices: [{ delta, finish_reason }], usage }`
 * envelope; consolidating here keeps tool-call event shapes consistent.
 */

const FIXTURE_ID = "chatcmpl_fixture"

export const deltaChunk = (delta: object, finishReason: string | null = null) => ({
  id: FIXTURE_ID,
  choices: [{ delta, finish_reason: finishReason }],
  usage: null,
})

export const usageChunk = (usage: object) => ({
  id: FIXTURE_ID,
  choices: [],
  usage,
})

export const finishChunk = (reason: string) => deltaChunk({}, reason)

export const toolCallChunk = (id: string, name: string, args: string, index = 0) =>
  deltaChunk({
    role: "assistant",
    tool_calls: [{ index, id, function: { name, arguments: args } }],
  })

import { Effect, Stream } from "effect"
import { LLMClient } from "../../src/route.js"
import {
  LLMEvent,
  LLMRequest,
  Message,
  type ContentPart,
  type ProviderMetadata,
  type ToolCallPart,
  ToolResultPart,
  type Usage,
} from "../../src/schema/index.js"
import { type Tools, toDefinitions } from "../../src/tool.js"
import { ToolRuntime } from "../../src/tool-runtime.js"

interface RunOptions<T extends Tools> {
  readonly request: LLMRequest
  readonly tools: T
  readonly maxSteps?: number
}

/** Test-owned continuation loop. Production callers must own durable history. */
export const runTools = <T extends Tools>(options: RunOptions<T>) =>
  Stream.unwrap(
    Effect.gen(function* () {
      const names = new Set(Object.keys(options.tools))
      let request = LLMRequest.update(options.request, {
        tools: [...options.request.tools.filter((tool) => !names.has(tool.name)), ...toDefinitions(options.tools)],
      })
      let usage: Usage | undefined
      const events: LLMEvent[] = []

      for (let step = 0; step < (options.maxSteps ?? 10); step++) {
        const streamed = Array.from(yield* LLMClient.stream(request).pipe(Stream.runCollect))
        const state = stepState(streamed)
        usage = addUsage(usage, state.usage)
        events.push(...streamed.filter((event) => event.type !== "finish").map((event) => indexStep(event, step)))

        if (state.toolCalls.length === 0) {
          events.push(LLMEvent.finish({ reason: state.reason, usage, providerMetadata: state.providerMetadata }))
          return Stream.fromIterable(events)
        }

        const dispatched = yield* Effect.forEach(
          state.toolCalls,
          (call) => ToolRuntime.dispatch(options.tools, call).pipe(Effect.map((result) => [call, result] as const)),
          { concurrency: 10 },
        )
        events.push(...dispatched.flatMap(([, result]) => result.events))

        if (step + 1 >= (options.maxSteps ?? 10)) {
          events.push(LLMEvent.finish({ reason: state.reason, usage, providerMetadata: state.providerMetadata }))
          return Stream.fromIterable(events)
        }

        request = LLMRequest.update(request, {
          messages: [
            ...request.messages,
            Message.assistant(state.assistantContent),
            ...dispatched.map(([call, dispatched]) =>
              Message.tool({
                id: call.id,
                name: call.name,
                result: dispatched.result,
                providerMetadata: call.providerMetadata,
              }),
            ),
          ],
        })
      }

      return Stream.fromIterable(events)
    }),
  )

const indexStep = (event: LLMEvent, index: number): LLMEvent => {
  if (event.type === "step-start") return LLMEvent.stepStart({ index })
  if (event.type === "step-finish") return LLMEvent.stepFinish({ ...event, index })
  return event
}

const stepState = (events: ReadonlyArray<LLMEvent>) => {
  const assistantContent: ContentPart[] = []
  const toolCalls: ToolCallPart[] = []
  let reason: Extract<LLMEvent, { type: "finish" }>["reason"] = { normalized: "unknown" }
  let usage: Usage | undefined
  let providerMetadata: ProviderMetadata | undefined

  for (const event of events) {
    if (event.type === "text-delta" || event.type === "reasoning-delta") {
      appendText(assistantContent, event.type === "text-delta" ? "text" : "reasoning", event.text)
    } else if (event.type === "text-end" || event.type === "reasoning-end") {
      appendText(assistantContent, event.type === "text-end" ? "text" : "reasoning", "", event.providerMetadata)
    } else if (event.type === "tool-call") {
      assistantContent.push(event)
      if (!event.providerExecuted) toolCalls.push(event)
    } else if (event.type === "tool-result" && event.providerExecuted && event.result !== undefined) {
      assistantContent.push(
        ToolResultPart.make({
          id: event.id,
          name: event.name,
          result: event.result,
          providerExecuted: true,
          providerMetadata: event.providerMetadata,
        }),
      )
    } else if (event.type === "finish") {
      reason = event.reason
      usage = event.usage
      providerMetadata = event.providerMetadata
    }
  }
  return { assistantContent, toolCalls, reason, usage, providerMetadata }
}

const appendText = (
  content: ContentPart[],
  type: "text" | "reasoning",
  text: string,
  providerMetadata?: ProviderMetadata,
) => {
  const last = content.at(-1)
  if (last?.type === type) {
    content[content.length - 1] = {
      ...last,
      text: `${last.text}${text}`,
      providerMetadata: providerMetadata ?? last.providerMetadata,
    }
    return
  }
  content.push({ type, text, providerMetadata })
}

const addUsage = (left: Usage | undefined, right: Usage | undefined): Usage | undefined => {
  if (!left) return right
  if (!right) return left
  const sum = (key: keyof Usage) =>
    typeof left[key] !== "number" && typeof right[key] !== "number"
      ? undefined
      : ((left[key] as number | undefined) ?? 0) + ((right[key] as number | undefined) ?? 0)
  return {
    inputTokens: sum("inputTokens"),
    outputTokens: sum("outputTokens"),
    nonCachedInputTokens: sum("nonCachedInputTokens"),
    cacheReadInputTokens: sum("cacheReadInputTokens"),
    cacheWriteInputTokens: sum("cacheWriteInputTokens"),
    reasoningTokens: sum("reasoningTokens"),
    totalTokens: sum("totalTokens"),
  } as Usage
}

import { describe, expect, test } from "bun:test"
import { Effect, Schema, Stream } from "effect"
import { CacheHint, LLM, LLMEvent, LLMResponse, ToolEntry, ToolNamespace } from "../src/index.js"
import { OpenAI } from "../src/providers.js"
import * as OpenAIChat from "../src/protocols/openai-chat.js"
import * as OpenAIResponses from "../src/protocols/openai-responses.js"
import {
  GenerationOptions,
  LLMRequest,
  Message,
  LanguageModel,
  ToolCallPart,
  ToolChoice,
  ToolDefinition,
  ToolResultPart,
} from "../src/schema/index.js"
import { fixedResponse } from "./lib/http.js"
import { sseEvents } from "./lib/sse.js"

const chatRoute = OpenAIChat.route
const responsesRoute = OpenAIResponses.route

describe("llm constructors", () => {
  test("normalizes recursive tool namespaces", () => {
    const request = LLM.request({
      model: LanguageModel.make({ id: "fake-model", provider: "fake", route: responsesRoute }),
      tools: [
        {
          type: "namespace",
          name: "crm",
          description: "Customer management",
          tools: [
            { name: "lookup", description: "Look up a customer", inputSchema: { type: "object" } },
            {
              type: "namespace",
              name: "orders",
              tools: [{ name: "list", description: "List orders", inputSchema: { type: "object" } }],
            },
          ],
        },
      ],
    })

    expect(request.tools[0]).toEqual({
      type: "namespace",
      name: "crm",
      description: "Customer management",
      tools: [
        expect.objectContaining({ type: "tool", name: "lookup" }),
        {
          type: "namespace",
          name: "orders",
          description: undefined,
          tools: [expect.objectContaining({ type: "tool", name: "list" })],
        },
      ],
    })
    expect(request.tools[0]).toEqual(
      ToolNamespace.make({
        name: "crm",
        description: "Customer management",
        tools: request.tools[0]!.type === "namespace" ? request.tools[0].tools : [],
      }),
    )
    expect(Schema.decodeUnknownSync(ToolEntry)(Schema.encodeUnknownSync(ToolEntry)(request.tools[0]))).toEqual(
      request.tools[0],
    )
  })

  test("builds canonical schema classes from ergonomic input", () => {
    const request = LLM.request({
      id: "req_1",
      model: LanguageModel.make({ id: "fake-model", provider: "fake", route: chatRoute }),
      system: "You are concise.",
      prompt: "Say hello.",
    })

    expect(request).toBeInstanceOf(LLMRequest)
    expect(request.model).toBeInstanceOf(LanguageModel)
    expect(request.messages[0]).toBeInstanceOf(Message)
    expect(request.system).toEqual([{ type: "text", text: "You are concise." }])
    expect(request.messages[0]?.content).toEqual([{ type: "text", text: "Say hello." }])
    expect(request.generation).toBeUndefined()
    expect(request.tools).toEqual([])
  })

  test("updates requests without spreading schema class instances", () => {
    const base = LLM.request({
      id: "req_1",
      model: LanguageModel.make({ id: "fake-model", provider: "fake", route: chatRoute }),
      prompt: "Say hello.",
    })
    const updated = LLMRequest.update(base, {
      generation: GenerationOptions.make({ maxTokens: 20 }),
      messages: [...base.messages, Message.assistant("Hi.")],
    })

    expect(updated).toBeInstanceOf(LLMRequest)
    expect(updated.id).toBe("req_1")
    expect(updated.model).toEqual(base.model)
    expect(updated.generation).toEqual({ maxTokens: 20 })
    expect(updated.messages.map((message) => message.role)).toEqual(["user", "assistant"])
  })

  test("keeps request options separate from route defaults", () => {
    const request = LLM.request({
      model: LanguageModel.make({
        id: "fake-model",
        provider: "fake",
        route: chatRoute.with({
          generation: { maxTokens: 100, temperature: 1 },
          providerOptions: { store: false, metadata: { model: true } },
          http: { body: { metadata: { model: true } }, headers: { "x-shared": "model" }, query: { model: "1" } },
        }),
      }),
      prompt: "Say hello.",
      generation: { temperature: 0 },
      providerOptions: { store: true, metadata: { request: true } },
      http: { body: { metadata: { request: true } }, headers: { "x-shared": "request" }, query: { request: "1" } },
    })

    expect(request.generation).toEqual({ temperature: 0 })
    expect(request.providerOptions).toEqual({ store: true, metadata: { request: true } })
    expect(request.http).toEqual({
      body: { metadata: { request: true } },
      headers: { "x-shared": "request" },
      query: { request: "1" },
    })
  })

  test("updates canonical requests from the request datatype", () => {
    const base = LLM.request({
      id: "req_1",
      model: LanguageModel.make({ id: "fake-model", provider: "fake", route: chatRoute }),
      prompt: "Say hello.",
    })
    const updated = LLMRequest.update(base, { messages: [...base.messages, Message.assistant("Hi.")] })

    expect(updated).toBeInstanceOf(LLMRequest)
    expect(updated.id).toBe("req_1")
    expect(LLMRequest.input(updated).id).toBe("req_1")
    expect(updated.messages.map((message) => message.role)).toEqual(["user", "assistant"])
    expect(LLMRequest.update(updated, {})).toBe(updated)
  })

  test("updates canonical models from the model datatype", () => {
    const base = LanguageModel.make({
      id: "fake-model",
      provider: "fake",
      route: chatRoute,
    })
    const updated = LanguageModel.update(base, {
      route: responsesRoute,
      defaults: { generation: { maxTokens: 20 } },
      compatibility: { sanitizer: "gemini", requireFinishReason: false },
    })
    const updatedInput = LanguageModel.input(updated)

    expect(updated).toBeInstanceOf(LanguageModel)
    expect(String(updated.id)).toBe("fake-model")
    expect(updated.route).toBe(responsesRoute)
    expect(updated.defaults?.generation).toEqual({ maxTokens: 20 })
    expect(updated.compatibility).toEqual({ sanitizer: "gemini", requireFinishReason: false })
    expect(updatedInput.defaults).toBe(updated.defaults)
    expect(updatedInput.compatibility).toBe(updated.compatibility)
    expect(String(updatedInput.provider)).toBe("fake")
    expect(LanguageModel.update(updated, {})).toBe(updated)
  })

  test("carries model defaults and compatibility through route model selection", () => {
    const model = chatRoute.model({
      id: "kimi-k2",
      defaults: {
        generation: { maxTokens: 1_024, stop: ["END"] },
        providerOptions: { parallelToolCalls: false },
        http: { body: { extra_body: true } },
      },
      compatibility: { sanitizer: "moonshot" },
    })
    const request = LLM.request({ model, prompt: "Say hello." })

    expect(request.model.defaults?.generation).toEqual({ maxTokens: 1_024, stop: ["END"] })
    expect(request.model.defaults?.providerOptions).toEqual({ parallelToolCalls: false })
    expect(request.model.defaults?.http).toEqual({ body: { extra_body: true } })
    expect(request.model.compatibility).toEqual({ sanitizer: "moonshot" })
    expect(request.generation).toBeUndefined()
    expect(request.providerOptions).toBeUndefined()
    expect(request.http).toBeUndefined()
  })

  test("builds tool choices from names and tools", () => {
    const tool = ToolDefinition.make({ name: "lookup", description: "Lookup data", inputSchema: { type: "object" } })

    expect(tool).toBeInstanceOf(ToolDefinition)
    expect(ToolChoice.make("lookup")).toEqual(new ToolChoice({ type: "tool", name: "lookup" }))
    expect(ToolChoice.named("required")).toEqual(new ToolChoice({ type: "tool", name: "required" }))
    expect(ToolChoice.make(tool)).toEqual(new ToolChoice({ type: "tool", name: "lookup" }))
  })

  test("builds tool choice modes from reserved strings", () => {
    expect(ToolChoice.make("auto")).toEqual(new ToolChoice({ type: "auto" }))
    expect(ToolChoice.make("none")).toEqual(new ToolChoice({ type: "none" }))
    expect(ToolChoice.make("required")).toEqual(new ToolChoice({ type: "required" }))
    expect(
      LLM.request({
        model: LanguageModel.make({
          id: "fake-model",
          provider: "fake",
          route: chatRoute,
        }),
        prompt: "Use tools if needed.",
        toolChoice: "required",
      }).toolChoice,
    ).toEqual(new ToolChoice({ type: "required" }))
  })

  test("builds assistant tool calls and tool result messages", () => {
    const call = ToolCallPart.make({ id: "call_1", name: "lookup", input: { query: "weather" } })
    const result = ToolResultPart.make({ id: "call_1", name: "lookup", result: { temperature: 72 } })

    expect(Message.assistant([call]).content).toEqual([call])
    expect(Message.tool(result).content).toEqual([
      { type: "tool-result", id: "call_1", name: "lookup", result: { type: "json", value: { temperature: 72 } } },
    ])
  })

  test("builds chronological text-only system updates separately from the initial system prompt", () => {
    const update = Message.system([
      { type: "text", text: "Use parameterized SQL.", cache: new CacheHint({ type: "ephemeral" }) },
    ])
    const request = LLM.request({
      model: LanguageModel.make({ id: "fake-model", provider: "fake", route: chatRoute }),
      system: "Initial operator prompt.",
      messages: [Message.user("Review this."), update],
    })

    expect(update).toBeInstanceOf(Message)
    expect(update).toEqual({
      role: "system",
      content: [{ type: "text", text: "Use parameterized SQL.", cache: { type: "ephemeral" } }],
    })
    expect(request.system).toEqual([{ type: "text", text: "Initial operator prompt." }])
    expect(request.messages.map((message) => message.role)).toEqual(["user", "system"])
  })

  test("generates and streams from input or a prebuilt request", async () => {
    const model = OpenAI.configure({ apiKey: "test", baseURL: "https://openai.test/v1" }).chat("gpt-4o-mini")
    const layer = fixedResponse(
      sseEvents({ choices: [{ delta: { content: "Hello" } }] }, { choices: [{ delta: {}, finish_reason: "stop" }] }),
    )
    const input = { model, prompt: "Say hello." }
    const request = LLM.request(input)
    const generated = await Effect.runPromise(LLM.generate(input).pipe(Effect.provide(layer)))
    const generatedFromRequest = await Effect.runPromise(LLM.generate(request).pipe(Effect.provide(layer)))
    expect(generated.text).toBe("Hello")
    expect(generatedFromRequest.text).toBe(generated.text)

    const streamed = await Effect.runPromise(LLM.stream(input).pipe(Stream.runCollect, Effect.provide(layer)))
    const streamedFromRequest = await Effect.runPromise(
      LLM.stream(request).pipe(Stream.runCollect, Effect.provide(layer)),
    )
    expect(Array.from(streamed).some(LLMEvent.is.textDelta)).toBe(true)
    expect(streamedFromRequest).toEqual(streamed)
  })

  test("extracts output text from response events", () => {
    expect(
      LLMResponse.text({
        events: [
          { type: "text-delta", id: "text-0", text: "hi" },
          { type: "finish", reason: { normalized: "stop" } },
        ],
      }),
    ).toBe("hi")
  })
})

import { describe, expect } from "bun:test"
import { NodeFileSystem } from "@effect/platform-node"
import { Effect, Ref, Schema } from "effect"
import { FileSystem } from "effect"
import { HttpClientRequest } from "effect/http"
import { AIError, Media, Message } from "../src/index.js"
import { it } from "./lib/effect.js"
import { dynamicResponse, scriptedResponses } from "./lib/http.js"

const PNG = Uint8Array.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0, 0, 0, 0])
const JPEG = Uint8Array.from([0xff, 0xd8, 0xff, 0xe0, 0, 0])
const GIF = Uint8Array.from([0x47, 0x49, 0x46, 0x38, 0x39, 0x61])
const WEBP = Uint8Array.from([0x52, 0x49, 0x46, 0x46, 0, 0, 0, 0, 0x57, 0x45, 0x42, 0x50])
const PDF = Uint8Array.from([0x25, 0x50, 0x44, 0x46, 0x2d, 0x31])

describe("Media", () => {
  it.effect("round-trips every source through Media.from(asset.source)", () =>
    Effect.sync(() => {
      const assets = [
        Media.bytes(PNG),
        Media.base64("AQID", "image/png"),
        Media.url("https://example.test/a.png", { mediaType: "image/png", expiresAt: 123, headers: { a: "b" } }),
        Media.ref("openai", "file_123", "image/webp"),
      ]
      for (const asset of assets) {
        const copy = Media.from(asset.source)
        expect(copy.source).toEqual(asset.source)
        expect(copy.mediaType).toBe(asset.mediaType)
        expect(copy.kind).toBe(asset.kind)
        expect(copy.expiresAt).toBe(asset.expiresAt)
      }
      expect(assets.map((asset) => asset.kind)).toEqual(["image", "image", "image", "image"])
      expect(Media.url("https://example.test/unknown").mediaType).toBe("application/octet-stream")
      expect(Media.url("https://example.test/unknown").kind).toBe("other")
      expect(Media.base64("AQID", "application/pdf").kind).toBe("document")
      expect(Media.base64("AQID", "video/mp4").kind).toBe("video")
      expect(Media.base64("AQID", "audio/wav").kind).toBe("audio")
    }),
  )

  it.effect("parses data URLs and rejects malformed ones", () =>
    Effect.sync(() => {
      const asset = Media.fromDataUrl("data:image/jpeg;base64,/9j/")
      expect(asset.source).toEqual({ type: "base64", data: "/9j/", mediaType: "image/jpeg" })
      expect(asset.mediaType).toBe("image/jpeg")
      expect(Media.fromDataUrl("data:text/plain;charset=utf-8;base64,aGk=").source).toEqual({
        type: "base64",
        data: "aGk=",
        mediaType: "text/plain",
      })
      expect(() => Media.fromDataUrl("https://example.test/a.png")).toThrow(
        "Media data URLs must contain a MIME type and base64 data",
      )
      expect(() => Media.fromDataUrl("data:image/png,rawtext")).toThrow()
    }),
  )

  it.effect("detects media types from magic bytes", () =>
    Effect.sync(() => {
      expect(Media.detectMediaType(PNG)).toBe("image/png")
      expect(Media.detectMediaType(JPEG)).toBe("image/jpeg")
      expect(Media.detectMediaType(GIF)).toBe("image/gif")
      expect(Media.detectMediaType(WEBP)).toBe("image/webp")
      expect(Media.detectMediaType(PDF)).toBe("application/pdf")
      expect(Media.detectMediaType(Uint8Array.from([1, 2, 3]))).toBeUndefined()
      expect(Media.detectMediaType(new TextEncoder().encode("ID3\x04"))).toBe("audio/mpeg")
      expect(Media.detectMediaType(Uint8Array.from([0xff, 0xfb, 0x90, 0x64]))).toBe("audio/mpeg")
      expect(Media.detectMediaType(Uint8Array.from([0xff, 0xf3, 0x90, 0x64]))).toBe("audio/mpeg")
      expect(Media.detectMediaType(Uint8Array.from([0xff, 0xf1, 0x50, 0x80]))).toBe("audio/aac")
      expect(Media.detectMediaType(new TextEncoder().encode("RIFF\0\0\0\0WAVEfmt "))).toBe("audio/wav")
      expect(Media.detectMediaType(new TextEncoder().encode("OggS\0\x02"))).toBe("audio/ogg")
      expect(Media.detectMediaType(new TextEncoder().encode("fLaC\0\0\0\x22"))).toBe("audio/flac")
      expect(Media.bytes(PNG).mediaType).toBe("image/png")
      expect(Media.bytes(Uint8Array.from([1, 2, 3])).mediaType).toBe("application/octet-stream")
      expect(Media.bytes(Uint8Array.from([1, 2, 3]), "image/x-custom").mediaType).toBe("image/x-custom")
    }),
  )

  it.effect("materializes url assets through the request executor once", () =>
    Effect.gen(function* () {
      const requests = yield* Ref.make<Array<HttpClientRequest.HttpClientRequest>>([])
      const asset = Media.url("https://cdn.example.test/generated", {
        expiresAt: 42,
        headers: { authorization: "Bearer media" },
        providerMetadata: { example: { id: "gen_1" } },
      })
      const program = Effect.gen(function* () {
        const first = yield* asset.bytes()
        const second = yield* asset.bytes()
        expect(second).toBe(first)
        expect(first).toEqual(PNG)
        expect(yield* asset.base64()).toBe(Buffer.from(PNG).toString("base64"))
        expect(yield* asset.dataUrl()).toBe(
          `data:application/octet-stream;base64,${Buffer.from(PNG).toString("base64")}`,
        )

        const owned = yield* asset.materialize()
        expect(owned.source).toEqual({ type: "bytes", data: PNG, mediaType: "image/png" })
        expect(owned.mediaType).toBe("image/png")
        expect(owned.kind).toBe("image")
        expect(owned.expiresAt).toBeUndefined()
        expect(owned.providerMetadata).toEqual({ example: { id: "gen_1" } })
        expect(yield* owned.materialize()).toBe(owned)

        const seen = yield* Ref.get(requests)
        expect(seen).toHaveLength(1)
        expect(seen[0].url).toBe("https://cdn.example.test/generated")
        expect(seen[0].headers.authorization).toBe("Bearer media")
      })
      yield* program.pipe(
        Effect.provide(
          dynamicResponse((input) =>
            Ref.update(requests, (all) => [...all, input.request]).pipe(
              Effect.map(() => input.respond(PNG, { headers: { "content-type": "image/png" } })),
            ),
          ),
        ),
      )
    }),
  )

  it.effect("caches decoded base64 bytes and encodes owned bytes lazily", () =>
    Effect.gen(function* () {
      const fromBase64 = Media.base64("AQID", "image/png")
      const decoded = yield* fromBase64.bytes()
      expect(decoded).toEqual(Uint8Array.from([1, 2, 3]))
      expect(yield* fromBase64.bytes()).toBe(decoded)
      expect(yield* fromBase64.base64()).toBe("AQID")

      const fromBytes = Media.bytes(Uint8Array.from([1, 2, 3]), "image/png")
      const encoded = yield* fromBytes.base64()
      expect(encoded).toBe("AQID")
      expect(yield* fromBytes.base64()).toBe(encoded)
      expect(yield* fromBytes.dataUrl()).toBe("data:image/png;base64,AQID")

      const invalid = yield* Media.base64("not base64!", "image/png").bytes().pipe(Effect.flip)
      expect(invalid.reason._tag).toBe("InvalidRequest")
      const ref = yield* Media.ref("openai", "file_1").bytes().pipe(Effect.flip)
      expect(ref.reason._tag).toBe("InvalidRequest")
    }).pipe(Effect.provide(scriptedResponses(["unused"]))),
  )

  it.effect("serializes assets inside messages and restores them as Media.Asset", () =>
    Effect.sync(() => {
      const codec = Schema.fromJsonString(Message)
      const message = Message.user([
        Message.media(Media.base64("AQID", "image/png", { info: { width: 1, height: 1 } }), { filename: "a.png" }),
        Message.media(Media.url("https://example.test/b.pdf", { mediaType: "application/pdf", expiresAt: 7 })),
      ])
      const json = Schema.encodeSync(codec)(message)
      expect(json).not.toContain("null")
      const restored = Schema.decodeSync(codec)(json)
      const parts = restored.content.filter((part) => part.type === "media")
      expect(parts).toHaveLength(2)
      expect(parts[0].media).toBeInstanceOf(Media.Asset)
      expect(parts[0].media.source).toEqual({ type: "base64", data: "AQID", mediaType: "image/png" })
      expect(parts[0].media.info).toEqual({ width: 1, height: 1 })
      expect(parts[0].filename).toBe("a.png")
      expect(parts[1].media.kind).toBe("document")
      expect(parts[1].media.expiresAt).toBe(7)
    }),
  )

  it.effect("keeps transient url download headers out of toJSON and AssetSchema encoding", () =>
    Effect.sync(() => {
      const asset = Media.url("https://cdn.example.test/video.mp4", {
        mediaType: "video/mp4",
        expiresAt: 42,
        headers: { "x-goog-api-key": "secret" },
      })
      expect(asset.headers).toEqual({ "x-goog-api-key": "secret" })
      const source = { type: "url", url: "https://cdn.example.test/video.mp4", mediaType: "video/mp4", expiresAt: 42 }

      expect(asset.toJSON()).not.toHaveProperty("headers")
      expect(JSON.stringify(asset)).not.toContain("secret")
      expect(asset.toJSON().source).toEqual(source)

      const encoded = Schema.encodeSync(Media.AssetSchema)(asset)
      expect(encoded).not.toHaveProperty("headers")
      expect(encoded.source).toEqual(source)

      const codec = Schema.fromJsonString(Media.AssetSchema)
      const json = Schema.encodeSync(codec)(asset)
      expect(json).not.toContain("secret")
      const restored = Schema.decodeSync(codec)(json)
      expect(restored).toBeInstanceOf(Media.Asset)
      expect(restored.source).toEqual(source)
      expect(restored.expiresAt).toBe(42)
      expect(restored.headers).toBeUndefined()
    }),
  )

  it.effect("fails url downloads with non-2xx status as a typed AIError keeping http and body", () =>
    Effect.gen(function* () {
      const body = JSON.stringify({ error: { message: "file expired" } })
      const error = yield* Media.url("https://cdn.example.test/expired.png")
        .bytes()
        .pipe(
          Effect.flip,
          Effect.provide(
            dynamicResponse((input) =>
              Effect.succeed(input.respond(body, { status: 404, headers: { "content-type": "application/json" } })),
            ),
          ),
        )
      expect(error).toBeInstanceOf(AIError)
      expect(error.message).toContain("file expired")
      expect(error.reason.http?.status).toBe(404)
      expect(error.reason.http?.url).toBe("https://cdn.example.test/expired.png")
      expect(error.reason.body).toBe(body)
    }),
  )

  it.effect("reads files with sniffed media types and writes materialized assets", () =>
    Effect.gen(function* () {
      const fs = yield* FileSystem.FileSystem
      const dir = yield* fs.makeTempDirectoryScoped()
      const source = `${dir}/source.bin`
      yield* fs.writeFile(source, PNG)

      const asset = yield* Media.file(source)
      expect(asset.mediaType).toBe("image/png")
      expect(asset.source).toEqual({ type: "bytes", data: PNG, mediaType: "image/png" })

      const plain = `${dir}/notes.md`
      yield* fs.writeFile(plain, new TextEncoder().encode("# hi"))
      expect((yield* Media.file(plain)).mediaType).toBe("text/markdown")

      const target = `${dir}/copy.png`
      yield* Media.write(Media.base64("AQID", "image/png"), target)
      expect(yield* fs.readFile(target)).toEqual(Uint8Array.from([1, 2, 3]))

      const missing = yield* Media.file(`${dir}/missing.png`).pipe(Effect.flip)
      expect(missing.reason._tag).toBe("InvalidRequest")
    }).pipe(Effect.provide(NodeFileSystem.layer), Effect.provide(scriptedResponses(["unused"]))),
  )
})

import { describe, expect, test } from "bun:test"
import { Allow, MalformedJSON, PartialJSON, parse } from "../src/protocols/utils/partial-json.js"

describe("partial JSON", () => {
  test("parses complete JSON", () => {
    expect(parse('{"key":"value","items":[1,true,null]}')).toEqual({
      key: "value",
      items: [1, true, null],
    })

    const object = parse('{"__proto__":{"safe":true}}') as Record<string, unknown>
    expect(Object.hasOwn(object, "__proto__")).toBe(true)
  })

  test("parses partial strings", () => {
    expect(parse('"hello')).toBe("hello")
    expect(parse('"hello \\u12')).toBe("hello ")
    expect(() => parse('"hello', ~Allow.STR)).toThrow(PartialJSON)
  })

  test("repairs invalid escapes and raw control characters", () => {
    expect(parse('{"path":"A\\H","text":"first\tsecond"}')).toEqual({
      path: "A\\H",
      text: "first\tsecond",
    })
  })

  test("preserves prototype keys in partial objects", () => {
    const object = parse('{"__proto__":{"safe":true}') as Record<string, unknown>

    expect(Object.hasOwn(object, "__proto__")).toBe(true)
    expect(Object.getPrototypeOf(object)).toBe(Object.prototype)
    expect(object.__proto__).toEqual({ safe: true })
  })

  test("controls partial collection values independently", () => {
    expect(parse('["', Allow.ARR)).toEqual([])
    expect(parse('["', Allow.ARR | Allow.STR)).toEqual([""])
    expect(parse('{"key":"', Allow.OBJ)).toEqual({})
    expect(parse('{"key":"', Allow.OBJ | Allow.STR)).toEqual({ key: "" })
  })

  test("parses partial literals and numbers", () => {
    expect(parse("nu", Allow.NULL)).toBeNull()
    expect(parse("tr", Allow.BOOL)).toBe(true)
    expect(parse("fa", Allow.BOOL)).toBe(false)
    expect(parse("1e", Allow.NUM)).toBe(1)
  })

  test("distinguishes disallowed partial values from malformed values", () => {
    expect(() => parse("[", Allow.STR)).toThrow(PartialJSON)
    expect(() => parse("n", ~Allow.NULL)).toThrow(MalformedJSON)
  })

  test("rejects empty input", () => {
    expect(() => parse("  ")).toThrow("is empty")
  })
})

import { describe, expect, test } from "bun:test"
import { mkdtemp, rm } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { Effect, Layer } from "effect"
import { HttpClientRequest } from "effect/http"
import { AIError, LLMEvent, Media, SpeechEvent, TranscriptionEvent } from "../src/index.js"
import { RequestExecutor } from "../src/route.js"
import { AI } from "../src/promise.js"
import { AssemblyAI, OpenAI, Replicate, Runway } from "../src/providers.js"
import { handlerLayer, json } from "./lib/http.js"
import { sseEvents } from "./lib/sse.js"

const openai = OpenAI.configure({ apiKey: "test", baseURL: "https://openai.test/v1" })

const chatBody = sseEvents(
  { choices: [{ delta: { content: "Hello" } }] },
  { choices: [{ delta: { content: " world" } }] },
  { choices: [{ delta: {}, finish_reason: "stop" }] },
)

/**
 * Executor layer that answers chat completions with SSE text, image generations with one base64 PNG, Runway video
 * tasks with a queued submission that succeeds on the second poll, speech with raw audio or SSE audio deltas, OpenAI
 * transcription with JSON or SSE text deltas, AssemblyAI transcripts that complete on the first poll, and `slow.test`
 * chat completions that send one text delta and never finish.
 */
const executor = (seen: Array<string>) =>
  RequestExecutor.layer.pipe(
    Layer.provide(
      handlerLayer((input) =>
        Effect.gen(function* () {
          const web = yield* HttpClientRequest.toWeb(input.request).pipe(Effect.orDie)
          seen.push(web.url)
          if (web.url.endsWith("/images/generations"))
            return JSON.parse(input.text).stream === true
              ? input.respond(
                  sseEvents(
                    {
                      type: "image_generation.partial_image",
                      b64_json: "AQ==",
                      partial_image_index: 0,
                      output_format: "png",
                    },
                    { type: "image_generation.completed", b64_json: "AQID", output_format: "png" },
                  ),
                  { headers: { "content-type": "text/event-stream" } },
                )
              : input.respond(JSON.stringify({ data: [{ b64_json: "AQID" }], output_format: "png" }), {
                  headers: { "content-type": "application/json" },
                })
          if (web.url.startsWith("https://replicate.test"))
            return json(input, {
              id: "p_1",
              status: "succeeded",
              output: "https://replicate.test/a.webp",
              urls: { get: "https://replicate.test/p_1", cancel: "https://replicate.test/p_1/cancel" },
            })
          if (web.url.startsWith("https://slow.test"))
            return input.respond(
              new ReadableStream({
                start: (controller) =>
                  controller.enqueue(
                    new TextEncoder().encode(
                      `data: ${JSON.stringify({ choices: [{ delta: { content: "Hello" } }] })}\n\n`,
                    ),
                  ),
              }),
              { headers: { "content-type": "text/event-stream" } },
            )
          if (web.url.endsWith("/chat/completions"))
            return input.respond(chatBody, { headers: { "content-type": "text/event-stream" } })
          if (web.url.endsWith("/audio/speech"))
            return JSON.parse(input.text).stream_format === "sse"
              ? input.respond(
                  sseEvents(
                    { type: "speech.audio.delta", audio: "AQI=" },
                    { type: "speech.audio.delta", audio: "Aw==" },
                    { type: "speech.audio.done", usage: { input_tokens: 4, output_tokens: 8, total_tokens: 12 } },
                  ),
                  { headers: { "content-type": "text/event-stream" } },
                )
              : input.respond(Uint8Array.from([1, 2, 3]), { headers: { "content-type": "audio/pcm" } })
          if (web.url.endsWith("/audio/transcriptions"))
            return input.text.includes('name="stream"')
              ? input.respond(
                  sseEvents(
                    { type: "transcript.text.delta", delta: "Hello" },
                    { type: "transcript.text.delta", delta: " there." },
                    { type: "transcript.text.done", text: "Hello there." },
                  ),
                  { headers: { "content-type": "text/event-stream" } },
                )
              : input.respond(JSON.stringify({ text: "Hello there." }), {
                  headers: { "content-type": "application/json" },
                })
          if (web.url.endsWith("/v2/transcript"))
            return input.respond(JSON.stringify({ id: "tr_1", status: "queued" }), {
              headers: { "content-type": "application/json" },
            })
          if (web.url.endsWith("/v2/transcript/tr_1"))
            return input.respond(JSON.stringify({ id: "tr_1", status: "completed", text: "Hello there." }), {
              headers: { "content-type": "application/json" },
            })
          if (web.url.endsWith("/text_to_video"))
            return input.respond(JSON.stringify({ id: "task_1" }), { headers: { "content-type": "application/json" } })
          if (web.url.endsWith("/tasks/task_1")) {
            const polls = seen.filter((url) => url.endsWith("/tasks/task_1")).length
            return input.respond(
              JSON.stringify(
                polls === 1
                  ? { status: "RUNNING", progress: 0.5 }
                  : { status: "SUCCEEDED", output: ["https://runway.test/out.mp4"], cost: { credits: 5 } },
              ),
              { headers: { "content-type": "application/json" } },
            )
          }
          return input.respond(JSON.stringify({ error: { message: "not found" } }), {
            status: 404,
            headers: { "content-type": "application/json" },
          })
        }),
      ),
    ),
  )

describe("AI promise client", () => {
  test("generates text, images, and streams over one managed runtime, and queues images", async () => {
    const seen: Array<string> = []
    const ai = AI.make({ layer: executor(seen) })

    const request = ai.llm.request({ model: openai.chat("gpt-4o-mini"), prompt: "Say hello." })
    const text = await ai.llm.generate(request)
    expect(text.text).toBe("Hello world")
    expect((await ai.llm.generate({ model: openai.chat("gpt-4o-mini"), prompt: "Say hello." })).text).toBe(
      "Hello world",
    )

    const image = await ai.image.generate({ model: openai.image("gpt-image-2"), prompt: "A lighthouse" })
    expect(image.image).toBeInstanceOf(Media.Asset)
    expect(image.image.mediaType).toBe("image/png")
    expect(await ai.run(image.image.bytes())).toEqual(Uint8Array.from([1, 2, 3]))
    const requested = await ai.image.generate(
      ai.image.request({ model: openai.image("gpt-image-2"), prompt: "A lighthouse" }),
    )
    expect(requested.image.mediaType).toBe("image/png")

    const deltas: Array<string> = []
    for await (const event of ai.llm.stream(request)) {
      if (LLMEvent.is.textDelta(event)) deltas.push(event.text)
    }
    expect(deltas).toEqual(["Hello", " world"])
    const directDeltas: Array<string> = []
    for await (const event of ai.llm.stream({ model: openai.chat("gpt-4o-mini"), prompt: "Say hello." })) {
      if (LLMEvent.is.textDelta(event)) directDeltas.push(event.text)
    }
    expect(directDeltas).toEqual(deltas)

    const imageEvents: Array<string> = []
    for await (const event of ai.image.stream({ model: openai.image("gpt-image-2"), prompt: "A lighthouse" })) {
      imageEvents.push(event.type)
    }
    expect(imageEvents).toEqual(["image-partial", "image", "finish"])

    expect(seen).toEqual([
      "https://openai.test/v1/chat/completions",
      "https://openai.test/v1/chat/completions",
      "https://openai.test/v1/images/generations",
      "https://openai.test/v1/images/generations",
      "https://openai.test/v1/chat/completions",
      "https://openai.test/v1/chat/completions",
      "https://openai.test/v1/images/generations",
    ])

    const generation = await ai.image.start({
      model: Replicate.configure({ apiKey: "test", baseURL: "https://replicate.test" }).image("owner/model"),
      prompt: "A lighthouse",
    })
    expect((await generation.await()).image.source).toMatchObject({ url: "https://replicate.test/a.webp" })
    await ai.dispose()
  })

  test("starts, awaits, and resumes video generations over the same runtime", async () => {
    const seen: Array<string> = []
    const ai = AI.make({ layer: executor(seen) })
    const model = Runway.configure({ apiKey: "test", baseURL: "https://runway.test/v1" }).video("gen4.5")

    const generation = await ai.video.start({ model, prompt: "A kite" })
    expect(generation.id).toBe("task_1")
    expect(generation.status).toBe("queued")
    expect(generation.token).toEqual({ taskID: "task_1" })

    const refreshed = await generation.refresh()
    expect(refreshed.status).toBe("running")
    expect(refreshed.progress).toBe(0.5)

    const response = await refreshed.await({ poll: { interval: 10 } })
    expect(response.video).toBeInstanceOf(Media.Asset)
    expect(response.video.source).toMatchObject({ type: "url", url: "https://runway.test/out.mp4" })
    expect(response.usage).toEqual({ type: "credits", credits: 5 })

    const resumed = await ai.video.resume(model, JSON.parse(JSON.stringify(generation.token)))
    expect(resumed.status).toBe("completed")
    expect((await resumed.await()).videos).toHaveLength(1)

    const events: Array<string> = []
    for await (const event of ai.video.stream({ model, prompt: "A kite" }, { poll: { interval: 10 } })) {
      events.push(event.type)
    }
    expect(events).toEqual(["video", "finish"])

    expect(seen[0]).toBe("https://runway.test/v1/text_to_video")
    expect(seen.filter((url) => url.endsWith("/tasks/task_1")).length).toBeGreaterThanOrEqual(5)
    await ai.dispose()
  })

  test("observes a started generation's events and fetches its result", async () => {
    const ai = AI.make({ layer: executor([]) })
    const model = Runway.configure({ apiKey: "test", baseURL: "https://runway.test/v1" }).video("gen4.5")
    const generation = await ai.video.start({ model, prompt: "A kite" })

    const events: Array<string> = []
    for await (const event of generation.events({ poll: { interval: 10 } })) events.push(event.type)
    expect(events).toEqual(["generation-progress", "generation-finished"])
    expect(generation.status).toBe("queued")
    expect((await generation.result()).video.source).toMatchObject({ url: "https://runway.test/out.mp4" })
    await ai.dispose()
  })

  test("reads, writes, and decodes assets without leaving promises", async () => {
    const ai = AI.make({ layer: executor([]) })
    const dir = await mkdtemp(join(tmpdir(), "ai-promise-"))
    try {
      const png = Uint8Array.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 1, 2, 3])
      await Bun.write(join(dir, "source.bin"), png)

      const asset = await ai.file(join(dir, "source.bin"))
      expect(asset.mediaType).toBe("image/png")
      await ai.write(asset, join(dir, "copy.png"))
      expect(await ai.bytes(await ai.file(join(dir, "copy.png")))).toEqual(png)
    } finally {
      await rm(dir, { recursive: true })
      await ai.dispose()
    }
  })

  test("generates, streams, and starts transcriptions over the same runtime", async () => {
    const ai = AI.make({ layer: executor([]) })
    const audio = Media.url("https://audio.test/hello.mp3")
    const bytes = Media.bytes(Uint8Array.from([0x49, 0x44, 0x33]), "audio/mpeg")

    expect(
      (await ai.transcription.generate({ model: openai.transcription("gpt-4o-mini-transcribe"), audio: bytes })).text,
    ).toBe("Hello there.")

    const deltas: Array<string> = []
    for await (const event of ai.transcription.stream({
      model: openai.transcription("gpt-4o-mini-transcribe"),
      audio: bytes,
    }))
      if (TranscriptionEvent.is.textDelta(event)) deltas.push(event.delta)
    expect(deltas).toEqual(["Hello", " there."])

    const model = AssemblyAI.configure({ apiKey: "test", baseURL: "https://assemblyai.test" }).transcription(
      "universal-2",
    )
    const generation = await ai.transcription.start({ model, audio })
    expect(generation.token).toEqual({ transcriptID: "tr_1" })
    expect((await generation.await({ poll: { interval: 10 } })).text).toBe("Hello there.")
    await ai.dispose()
  })

  test("generates and streams speech over the same runtime", async () => {
    const ai = AI.make({ layer: executor([]) })
    const model = openai.speech("gpt-4o-mini-tts")

    const response = await ai.speech.generate({ model, text: "Hello", voice: "coral", format: "pcm" })
    expect(await ai.run(response.audio.bytes())).toEqual(Uint8Array.from([1, 2, 3]))

    const events: Array<SpeechEvent> = []
    for await (const event of ai.speech.stream({ model, text: "Hello", voice: "coral" })) events.push(event)
    expect(events.map((event) => event.type)).toEqual(["audio-delta", "audio-delta", "finish"])
    const finish = events.find(SpeechEvent.is.finish)
    expect(await ai.run(finish!.audio.bytes())).toEqual(Uint8Array.from([1, 2, 3]))
    await ai.dispose()
  })

  test("rethrows AIError unchanged and honors abort signals", async () => {
    const ai = AI.make({ layer: executor([]) })

    const failure = await ai.llm
      .generate(ai.llm.request({ model: openai.responses("gpt-5"), prompt: "Hello" }))
      .then(() => undefined)
      .catch((error: unknown) => error)
    expect(failure).toBeInstanceOf(AIError)
    expect(failure instanceof AIError && failure.reason.http?.status).toBe(404)

    const invalidLLM = await ai.llm
      // @ts-expect-error Invalid input must reject with AIError instead of throwing synchronously.
      .generate({ model: openai.responses("gpt-5"), messages: [{ role: "bogus" }] })
      .catch((error: unknown) => error)
    expect(invalidLLM instanceof AIError && invalidLLM.reason._tag).toBe("InvalidRequest")

    const invalid = await ai.image
      .generate({ model: openai.image("gpt-image-2"), prompt: "A lighthouse", n: 1.5 })
      .catch((error: unknown) => error)
    expect(invalid instanceof AIError && invalid.reason._tag).toBe("InvalidRequest")

    const controller = new AbortController()
    controller.abort()
    const aborted = await ai.llm
      .generate(ai.llm.request({ model: openai.chat("gpt-4o-mini"), prompt: "Hello" }), { signal: controller.signal })
      .then(() => "completed")
      .catch(() => "aborted")
    expect(aborted).toBe("aborted")

    await ai.dispose()
  })

  test("aborted calls reject and aborted streams throw with the signal's reason", async () => {
    const ai = AI.make({ layer: executor([]) })
    const slow = OpenAI.configure({ apiKey: "test", baseURL: "https://slow.test/v1" }).chat("gpt-4o-mini")
    const aborted = new AbortController()
    aborted.abort()
    const reason = new Error("mine")

    const rejected = await ai.run(Effect.never, { signal: aborted.signal }).catch((error: unknown) => error)
    expect(rejected).toBe(aborted.signal.reason)
    expect(rejected).toMatchObject({ name: "AbortError" })

    const inFlight = new AbortController()
    setTimeout(() => inFlight.abort(reason), 10)
    expect(
      await ai.llm
        .generate({ model: slow, prompt: "Hello" }, { signal: inFlight.signal })
        .catch((error: unknown) => error),
    ).toBe(reason)

    const preAborted = await Array.fromAsync(
      ai.speech.stream({ model: openai.speech("gpt-4o-mini-tts"), text: "Hello" }, { signal: aborted.signal }),
    ).catch((error: unknown) => error)
    expect(preAborted).toBe(aborted.signal.reason)
    expect(preAborted).toMatchObject({ name: "AbortError" })

    const midStream = new AbortController()
    const deltas: Array<string> = []
    const midStreamFailure = await Array.fromAsync(
      ai.llm.stream({ model: slow, prompt: "Hello" }, { signal: midStream.signal }),
      (event) => {
        if (!LLMEvent.is.textDelta(event)) return
        deltas.push(event.text)
        midStream.abort()
      },
    ).catch((error: unknown) => error)
    expect(deltas).toEqual(["Hello"])
    expect(midStreamFailure).toBe(midStream.signal.reason)
    expect(midStreamFailure).toMatchObject({ name: "AbortError" })

    const model = Runway.configure({ apiKey: "test", baseURL: "https://runway.test/v1" }).video("gen4.5")
    const generation = await ai.video.start({ model, prompt: "A kite" })
    const polling = new AbortController()
    const events: Array<string> = []
    const eventsFailure = await Array.fromAsync(
      generation.events({ poll: { interval: 60_000 }, signal: polling.signal }),
      (event) => {
        events.push(event.type)
        polling.abort(reason)
      },
    ).catch((error: unknown) => error)
    expect(events).toEqual(["generation-progress"])
    expect(eventsFailure).toBe(reason)

    await ai.dispose()
  })

  test("breaking out of an abortable stream cleans up without throwing", async () => {
    const ai = AI.make({ layer: executor([]) })
    const slow = OpenAI.configure({ apiKey: "test", baseURL: "https://slow.test/v1" }).chat("gpt-4o-mini")
    const controller = new AbortController()
    const deltas: Array<string> = []
    for await (const event of ai.llm.stream({ model: slow, prompt: "Hello" }, { signal: controller.signal })) {
      if (!LLMEvent.is.textDelta(event)) continue
      deltas.push(event.text)
      break
    }
    controller.abort()
    expect(deltas).toEqual(["Hello"])
    await ai.dispose()
  })

  test("the default client is created lazily and can be disposed", async () => {
    expect(typeof AI.ai.llm.generate).toBe("function")
    expect(typeof AI.ai.image.generate).toBe("function")
    expect(typeof AI.ai.video.start).toBe("function")
    expect(typeof AI.ai.speech.generate).toBe("function")
    await AI.ai.dispose()
  })
})

import { describe, expect, test } from "bun:test"
import { isContextOverflow } from "../src/index.js"
import { classifyProviderFailure, providerErrorMessage } from "../src/provider-error.js"

describe("provider error classification", () => {
  test("classifies provider token limit messages as context overflow", () => {
    const messages = [
      "tokens in request more than max tokens allowed",
      "Requested token count exceeds the model's maximum context length of 131072 tokens.",
      "Requested input length 600010 exceeds maximum input length 131071",
      "Input length (265330) exceeds model's maximum context length (262144).",
      "Input length 131393 exceeds the maximum allowed input length of 131040 tokens.",
      "The input (516368 tokens) is longer than the model's context length (262144 tokens).",
      "The input is longer than the model's context length trace_id: 39d8c3a5c6c91dbc8dd9055f0b37e084",
      "Prompt has 5,958,968 tokens, but the configured context size is 256,000 tokens",
      "Range of input length should be [1, 129024]",
      "Too many tokens",
      "Input validation error: `inputs` tokens + `max_new_tokens` must be <= 131073. Given: 600035 `inputs` tokens and 16 `max_new_tokens`",
      "Token limit exceeded",
    ]

    expect(messages.every(isContextOverflow)).toBe(true)
  })

  test("classifies Anthropic request_too_large as recoverable overflow", () => {
    expect(
      classifyProviderFailure({
        message: '{"error":{"type":"request_too_large","message":"Request exceeds the maximum size"}}',
        status: 400,
      }),
    ).toMatchObject({ _tag: "InvalidRequest", classification: "context-overflow" })
    expect(isContextOverflow("413 status code (no body)")).toBe(true)
  })

  test("classifies generic request size failures separately from context overflow", () => {
    const failures = [
      classifyProviderFailure({ message: "request too large", status: 413 }),
      classifyProviderFailure({ message: "upstream request entity too large", status: 502 }),
    ]

    expect(failures).toEqual(
      failures.map(() => expect.objectContaining({ _tag: "InvalidRequest", classification: "payload-too-large" })),
    )
  })

  test("does not classify rate limits as context overflow", () => {
    const messages = [
      "Throttling error: Too many tokens, please wait before trying again.",
      "Rate limit exceeded, please retry after 30 seconds.",
      "Too many requests. Please slow down.",
    ]

    expect(messages.some(isContextOverflow)).toBe(false)
  })

  test("classifies V1 plain-text rate limit fallbacks", () => {
    expect(
      [
        "Request rate increased too quickly",
        "Rate limit exceeded, please try again later",
        "Too many requests, please slow down",
      ].map((message) => classifyProviderFailure({ message })._tag),
    ).toEqual(["RateLimit", "RateLimit", "RateLimit"])
  })

  test("classifies V1 JSON rate limit fallbacks", () => {
    expect(
      [
        '{"type":"error","error":{"type":"too_many_requests"}}',
        '{"type":"error","error":{"code":"rate_limit_exceeded"}}',
        '{"code":"bad_request","error":{"code":"rate_limit_exceeded"}}',
        '{"type":"error","error":{"code":"unknown","type":"too_many_requests"}}',
      ].map((message) => classifyProviderFailure({ message })._tag),
    ).toEqual(["RateLimit", "RateLimit", "RateLimit", "RateLimit"])
  })

  test("classifies V1 overloaded provider codes", () => {
    expect(
      ['{"code":"resource_exhausted"}', '{"code":"service_unavailable"}', '{"code":"slow_down"}'].map(
        (message) => classifyProviderFailure({ message })._tag,
      ),
    ).toEqual(["ProviderInternal", "ProviderInternal", "ProviderInternal"])
  })

  test("classifies retryable server messages as provider internal", () => {
    const message =
      "The model is currently at capacity due to high demand. Please try again in a few minutes, or use a higher service tier for priority processing."

    expect(
      [
        message,
        "Try again",
        "Please retry your request shortly.",
        "You can retry the request.",
        "Try your request again.",
        "The service is temporarily at capacity.",
        "The model is overloaded.",
        "Service unavailable",
        "Internal server error",
        "The server is busy.",
        "Provider returned error",
        "Provider returned an error",
        "ResourceExhausted",
        "Upstream connection failed",
        "Exceeded request buffer limit while retrying upstream",
      ].map((message) => classifyProviderFailure({ message })._tag),
    ).toEqual(Array(15).fill("ProviderInternal"))
    expect(
      classifyProviderFailure({ message: "Provider request failed", rawBody: "Please try again later." })._tag,
    ).toBe("ProviderInternal")
  })

  test("prioritizes specific failures over retryable server text", () => {
    expect(
      [
        classifyProviderFailure({ message: "Invalid credentials, try again", status: 401 }),
        classifyProviderFailure({ message: "Quota exceeded, try again", status: 429 }),
        classifyProviderFailure({ message: "Rate limit exceeded, try again" }),
        classifyProviderFailure({ message: "Upstream request failed: validation failed", status: 400 }),
        classifyProviderFailure({ message: "Try again", status: 200 }),
      ].map((failure) => failure._tag),
    ).toEqual(["Authentication", "QuotaExceeded", "RateLimit", "InvalidRequest", "ProviderInternal"])
  })

  test("classifies Azure content filter rejections by their structured codes", () => {
    const message = "The response was filtered"
    const azure = {
      error: {
        message,
        type: null,
        param: "prompt",
        code: "content_filter",
        status: 400,
        innererror: { code: "ResponsibleAIPolicyViolation", content_filter_result: {} },
      },
    }
    const innerOnly = { error: { message, code: null, innererror: { code: "ResponsibleAIPolicyViolation" } } }

    expect(classifyProviderFailure({ message, status: 400, rawBody: JSON.stringify(azure) })._tag).toBe("ContentPolicy")
    expect(classifyProviderFailure({ message, status: 400, rawBody: JSON.stringify(innerOnly) })._tag).toBe(
      "ContentPolicy",
    )
  })

  test("classifies policy rejections that reuse generic request codes by the provider explanation", () => {
    const openai = {
      error: {
        message:
          "Invalid prompt: your prompt was flagged as potentially violating our usage policy. Please try again with a different prompt.",
        type: "invalid_request_error",
        param: null,
        code: "invalid_prompt",
      },
    }
    const anthropic = {
      type: "error",
      error: { type: "invalid_request_error", message: "Output blocked by content filtering policy" },
    }

    expect(
      [openai, anthropic].map(
        (body) =>
          classifyProviderFailure({ message: body.error.message, status: 400, rawBody: JSON.stringify(body) })._tag,
      ),
    ).toEqual(["ContentPolicy", "ContentPolicy"])
  })

  test("classifies OpenRouter typed policy errors across its API skins", () => {
    const chat = {
      id: "gen-abc123",
      object: "chat.completion.chunk",
      error: {
        code: 403,
        message: "Your input was flagged",
        metadata: { error_type: "content_policy_violation", reasons: ["violence"], flagged_input: "..." },
      },
      choices: [{ index: 0, delta: { content: "" }, finish_reason: "error" }],
    }
    const responses = {
      type: "response.failed",
      response: {
        id: "resp_abc123",
        status: "failed",
        error: { code: "image_content_policy_violation", message: "Your input was flagged" },
        error_type: "content_policy_violation",
      },
    }
    const messages = {
      type: "error",
      error: { type: "invalid_request_error", message: "Claude refused to respond", error_type: "refusal" },
    }

    expect(
      [
        classifyProviderFailure({ message: chat.error.message, status: 403, rawBody: JSON.stringify(chat) }),
        classifyProviderFailure({ message: responses.response.error.message, rawBody: JSON.stringify(responses) }),
        classifyProviderFailure({ message: messages.error.message, rawBody: JSON.stringify(messages) }),
      ].map((failure) => failure._tag),
    ).toEqual(["ContentPolicy", "ContentPolicy", "ContentPolicy"])
    const stability = { id: "a1b2", name: "content_moderation", errors: ["Your request was flagged"] }
    expect(
      classifyProviderFailure({ message: "Forbidden", status: 403, rawBody: JSON.stringify(stability) })._tag,
    ).toBe("ContentPolicy")
  })

  test("recovers policy codes that OpenCode Zen preserves only in its message label", () => {
    // Zen drops upstream codes outside its allow-list and replaces the type, but
    // `Protocol.errorMessage` keeps the original code as a `[code]` prefix.
    const zen = {
      error: {
        type: "server_error",
        message: "Upstream request failed: [content_filter] The response was filtered",
      },
    }

    expect(
      classifyProviderFailure({ message: zen.error.message, status: 400, rawBody: JSON.stringify(zen) })._tag,
    ).toBe("ContentPolicy")
  })

  test("keeps invalid_prompt schema validation failures as invalid requests", () => {
    // Bedrock Mantle reports request validation failures under `invalid_prompt`
    // with a pydantic dump that lists every input union member's fields.
    const message = [
      "SubmitRequestFailure: code=-32602, msg=219 validation errors for ResponsesRequest",
      "input.list[union[EasyInputMessageParam,ResponseComputerToolCallParam]].2.ResponseComputerToolCallParam.pending_safety_checks",
      "  Field required [type=missing, input_value={'content': [...], 'role': 'assistant', 'type': 'message'}, input_type=dict]",
    ].join("\n")
    const failure = classifyProviderFailure({
      message,
      status: 200,
      rawBody: JSON.stringify({ response: { status: "failed", error: { code: "invalid_prompt", message } } }),
    })

    expect(failure._tag).toBe("InvalidRequest")
  })

  test("does not infer content policy from policy phrases outside the provider explanation", () => {
    const failure = classifyProviderFailure({
      message: "Provider request failed with HTTP 400",
      status: 400,
      rawBody: JSON.stringify({ error: { message: "Unknown parameter: content_policy_id" } }),
    })

    expect(failure._tag).toBe("InvalidRequest")
  })

  test("classifies transient client statuses as provider internal", () => {
    expect([408, 409].map((status) => classifyProviderFailure({ message: `HTTP ${status}`, status })._tag)).toEqual([
      "ProviderInternal",
      "ProviderInternal",
    ])
  })

  test("classifies any remaining 4xx status as an invalid request", () => {
    expect(
      [400, 404, 418, 422, 451].map((status) => classifyProviderFailure({ message: `HTTP ${status}`, status })._tag),
    ).toEqual(Array(5).fill("InvalidRequest"))
  })

  test("classifies 402 as exhausted quota", () => {
    expect(classifyProviderFailure({ message: "Payment Required", status: 402 })._tag).toBe("QuotaExceeded")
  })

  test("classifies OpenCode Zen account limits as quota rather than throttling", () => {
    const typed = (type: string, message: string) => ({ type: "error", error: { type, message } })
    const substituted = (message: string) => ({
      error: { type: "server_error", message: `Upstream request failed: ${message}` },
    })
    const cases: ReadonlyArray<[number, { error: { message: string } }]> = [
      [429, typed("GoUsageLimitError", "Go usage limit exceeded")],
      [429, typed("FreeUsageLimitError", "Rate limit exceeded. Please try again later.")],
      [402, typed("CreditLimitExceeded", "Credit limit exceeded.")],
      [402, substituted("Insufficient account funds")],
      [402, substituted("Account invoice is overdue")],
      [429, substituted("Account budget exceeded")],
    ]
    expect(
      cases.map(
        ([status, body]) =>
          classifyProviderFailure({ message: body.error.message, status, rawBody: JSON.stringify(body) })._tag,
      ),
    ).toEqual(Array(6).fill("QuotaExceeded"))
  })

  test("classifies Z.ai plan and balance limits as quota rather than throttling", () => {
    const zai = (code: string, message: string) => ({ error: { code, message } })
    const cases = [
      zai("1113", "Insufficient balance or no resource package. Please recharge."),
      zai("1308", "Usage limit reached for 5 hours. Your limit will reset at 2026-10-01 00:00:00"),
      zai(
        "1309",
        "Your GLM Coding Plan package has expired and is temporarily unavailable. You can resume using it after renewing the subscription on the official website.",
      ),
      zai("1310", "Weekly/Monthly Limit Exhausted. Your limit will reset at 2026-10-01 00:00:00"),
      zai("1311", "Your current subscription plan does not yet include access to glm-5"),
      zai("1314", "Your enterprise package has expired. Please contact your enterprise administrator."),
      // Z.ai's Anthropic-compatible endpoint wraps the code and request ID into the message.
      {
        type: "error",
        error: {
          type: "rate_limit_error",
          code: "1309",
          message:
            "[1309][Your GLM Coding Plan package has expired and is temporarily unavailable. You can resume using it after renewing the subscription on the official website.][20260929132151e73af01340d54b58]",
        },
      },
    ]
    expect(
      cases.map(
        (body) =>
          classifyProviderFailure({ message: body.error.message, status: 429, rawBody: JSON.stringify(body) })._tag,
      ),
    ).toEqual(Array(cases.length).fill("QuotaExceeded"))
  })

  test("classifies Z.ai prompt length rejections as context overflow", () => {
    const cases = [
      { error: { code: "1261", message: "Prompt 超长" } },
      { error: { code: "1261", message: "Prompt too long" } },
      {
        type: "error",
        error: { type: "invalid_request_error", code: "1261", message: "[1261][Prompt too long][2026092913]" },
      },
    ]
    expect(
      cases.map((body) => {
        const reason = classifyProviderFailure({
          message: body.error.message,
          status: 400,
          rawBody: JSON.stringify(body),
        })
        return reason._tag === "InvalidRequest" ? reason.classification : reason._tag
      }),
    ).toEqual(["context-overflow", "context-overflow", "context-overflow"])
  })

  test("classifies Z.ai sensitive content rejections as content policy", () => {
    const message =
      "System detected potentially unsafe or sensitive content in input or generation. Please avoid using prompts that may generate sensitive content. Thank you for your cooperation."
    expect(
      classifyProviderFailure({
        message,
        status: 400,
        rawBody: JSON.stringify({ error: { code: "1301", message } }),
      })._tag,
    ).toBe("ContentPolicy")
  })

  test("keeps Z.ai throttling and overload retryable", () => {
    expect(
      [
        { error: { code: "1302", message: "Rate limit reached for requests" } },
        { error: { code: "1305", message: "The service may be temporarily overloaded, please try again later" } },
      ].map(
        (body) =>
          classifyProviderFailure({ message: body.error.message, status: 429, rawBody: JSON.stringify(body) })._tag,
      ),
    ).toEqual(["RateLimit", "RateLimit"])
  })

  test("does not let substituted server codes make a 4xx retryable", () => {
    const openai = { error: { type: "server_error", message: "Upstream request failed: Model is unavailable." } }
    const anthropic = {
      type: "error",
      error: { type: "api_error", message: "Upstream request failed: Model is unavailable." },
    }
    expect(
      [openai, anthropic].map(
        (body) =>
          classifyProviderFailure({ message: body.error.message, status: 400, rawBody: JSON.stringify(body) })._tag,
      ),
    ).toEqual(["InvalidRequest", "InvalidRequest"])
    // Without a contradicting status the same codes still mark provider trouble.
    expect(classifyProviderFailure({ message: openai.error.message, rawBody: JSON.stringify(openai) })._tag).toBe(
      "ProviderInternal",
    )
    expect(
      classifyProviderFailure({ message: openai.error.message, status: 200, rawBody: JSON.stringify(openai) })._tag,
    ).toBe("ProviderInternal")
  })

  test("classifies nested provider codes when a top-level code is also present", () => {
    expect(
      [
        '{"code":"bad_request","error":{"code":"usage_not_included"}}',
        '{"code":"bad_request","error":{"code":"server_error"}}',
        '{"code":"bad_request","error":{"type":"invalid_request_error"}}',
      ].map((message) => classifyProviderFailure({ message })._tag),
    ).toEqual(["QuotaExceeded", "ProviderInternal", "InvalidRequest"])
  })

  test("leaves unrecognized failures unclassified for the retry default", () => {
    expect(classifyProviderFailure({ message: '{"error":{"message":"no_kv_space"}}' })._tag).toBe("UnknownProvider")
    expect(classifyProviderFailure({ message: '{"type":"error","error":{"code":123}}' })._tag).toBe("UnknownProvider")
    expect(classifyProviderFailure({ message: "not-json" })._tag).toBe("UnknownProvider")
    expect(classifyProviderFailure({ message: "network error" })._tag).toBe("UnknownProvider")
  })
})

describe("provider error rawBody classification", () => {
  test("classifies provider envelopes without separate code inputs", () => {
    const cases = [
      ['{"type":"error","error":{"type":"overloaded_error","message":"Try again"}}', "ProviderInternal"],
      ['{"error":{"code":"insufficient_quota","message":"Request failed"}}', "QuotaExceeded"],
      [
        '{"type":"response.failed","response":{"error":{"code":"authentication_error","message":"Denied"}}}',
        "Authentication",
      ],
      ['{"error":{"code":429,"status":"RESOURCE_EXHAUSTED","message":"Try again"}}', "ProviderInternal"],
      ['{"exception":{"type":"throttlingException","details":{"message":"Try again"}}}', "RateLimit"],
    ] as const
    for (const [rawBody, expected] of cases) {
      const reason = classifyProviderFailure({ message: "Request failed", rawBody })
      expect(reason._tag).toBe(expected)
      expect(reason.body).toBe(rawBody)
      expect(reason).not.toHaveProperty("code")
    }
  })

  test("classifies separately supplied SDK data without replacing the response body", () => {
    const data = { error: { code: "authentication_error" } }
    for (const value of [data, JSON.stringify(data)]) {
      const reason = classifyProviderFailure({
        message: "Request failed",
        status: 400,
        rawBody: '{"message":"Request failed"}',
        data: value,
      })
      expect(reason._tag).toBe("Authentication")
      expect(reason.body).toBe('{"message":"Request failed"}')
    }
  })

  test("classifies Workers AI context window rejections as context overflow despite HTTP 413", () => {
    const message =
      "AiError: Ai: The estimated number of input and maximum output tokens (900047) exceeded this model context window limit (32000). (17851589-f2e6-405d-b67c-5550e52ee1c1)"
    const reason = classifyProviderFailure({
      message,
      status: 413,
      rawBody: JSON.stringify({ errors: [{ message, code: 5021 }], success: false, result: {}, messages: [] }),
    })
    expect(reason._tag === "InvalidRequest" ? reason.classification : reason._tag).toBe("context-overflow")
  })

  test("classifies Amazon Nova input token rejections as context overflow", () => {
    const message =
      "The model returned the following errors: Input Tokens Exceeded: Number of input tokens exceeds maximum length. Please update the input to try again."
    const reason = classifyProviderFailure({
      message,
      rawBody: JSON.stringify({
        headers: {
          ":exception-type": { type: "string", value: "validationException" },
          ":content-type": { type: "string", value: "application/json" },
          ":message-type": { type: "string", value: "exception" },
        },
        body: JSON.stringify({ message }),
      }),
    })
    expect(reason._tag === "InvalidRequest" ? reason.classification : reason._tag).toBe("context-overflow")
  })

  test("separates Cohere prompt overflow from output limit rejections", () => {
    const classify = (message: string) => {
      const reason = classifyProviderFailure({
        message,
        status: 400,
        rawBody: JSON.stringify({ error_type: "TOO_MANY_TOKENS", message }),
      })
      return reason._tag === "InvalidRequest" ? reason.classification : reason._tag
    }
    expect(
      classify(
        "too many tokens: size limit exceeded by 168512 tokens. Try using shorter or fewer inputs. The limit for this model is 132000 tokens.",
      ),
    ).toBe("context-overflow")
    expect(
      classify(
        "too many tokens: max tokens must be less than or equal to 4096, the maximum output length for this model - received 1000000.",
      ),
    ).toBeUndefined()
  })

  test("classifies invalid API keys reported as HTTP 400 as authentication failures", () => {
    const rawBody = JSON.stringify({
      error: {
        code: 400,
        message: "API key not valid. Please pass a valid API key.",
        status: "INVALID_ARGUMENT",
        details: [
          {
            "@type": "type.googleapis.com/google.rpc.ErrorInfo",
            reason: "API_KEY_INVALID",
            domain: "googleapis.com",
          },
          {
            "@type": "type.googleapis.com/google.rpc.LocalizedMessage",
            locale: "en-US",
            message: "API key not valid. Please pass a valid API key.",
          },
        ],
      },
    })
    expect(
      classifyProviderFailure({ message: "API key not valid. Please pass a valid API key.", status: 400, rawBody })
        ._tag,
    ).toBe("Authentication")
    // xAI
    expect(
      classifyProviderFailure({
        message: "Incorrect API key provided. You can obtain an API key from https://console.x.ai.",
        status: 400,
        rawBody: '{"code":"invalid-argument","error":"Incorrect API key provided."}',
      })._tag,
    ).toBe("Authentication")
  })

  test("classifies overflow signals buried in the raw payload when the summary is vague", () => {
    const reason = classifyProviderFailure({
      message: "Request failed",
      rawBody: '{"error":{"message":"This model\'s maximum context length is 40960 tokens"}}',
    })
    expect(reason._tag).toBe("InvalidRequest")
    expect(reason).toMatchObject({ classification: "context-overflow" })
  })

  test("extracts nested codes from the raw payload", () => {
    expect(
      classifyProviderFailure({ message: "Request failed", rawBody: '{"error":{"code":"insufficient_quota"}}' })._tag,
    ).toBe("QuotaExceeded")
    // Z.ai Responses stream rejections
    expect(
      classifyProviderFailure({
        message: "Unknown Model, please check the model code.",
        rawBody: '{"type":"response.failed","response":{"error":{"code":"model_not_found"}}}',
      })._tag,
    ).toBe("InvalidRequest")
    expect(
      classifyProviderFailure({
        message: "Your GLM Coding Plan package has expired and is temporarily unavailable.",
        rawBody: '{"type":"response.failed","response":{"error":{"code":"permission_denied"}}}',
      })._tag,
    ).toBe("Authentication")
  })
})

describe("provider error messages", () => {
  test("reads messages from common error body layouts", () => {
    expect(
      [
        '{"error":{"message":"Invalid API Key","type":"invalid_request_error"}}',
        '{"code":"invalid-argument","error":"Incorrect API key provided."}',
        '{"message":"1 validation error detected"}',
        '{"Message":"Invalid API Key format: Must start with pre-defined prefix"}',
        '{"type":"about:blank","title":"Gone","status":410,"detail":"The model has reached its end of life"}',
        '{"result":null,"success":false,"errors":[{"code":10000,"message":"Authentication error"}]}',
      ].map(providerErrorMessage),
    ).toEqual([
      "Invalid API Key",
      "Incorrect API key provided.",
      "1 validation error detected",
      "Invalid API Key format: Must start with pre-defined prefix",
      "The model has reached its end of life",
      "Authentication error",
    ])
  })

  test("prefers the nested error message over a top-level message", () => {
    expect(providerErrorMessage('{"message":"Bad Request","error":{"message":"model not found"}}')).toBe(
      "model not found",
    )
  })

  test("ignores blank, non-string, and non-JSON messages", () => {
    expect(
      [
        '{"error":{"message":"  "}}',
        '{"message":{"detail":[{"msg":"too high"}]}}',
        '{"errors":[]}',
        "invalid parameter",
      ].map(providerErrorMessage),
    ).toEqual([undefined, undefined, undefined, undefined])
  })
})

