import { expect } from "bun:test"
import { Effect } from "effect"
import { LLM } from "../../src/index.js"
import { AnthropicMessages } from "../../src/protocols/anthropic-messages.js"
import { compileRequest } from "../../src/route/client.js"
import { it } from "../lib/effect.js"

for (const [id, enabled] of [
  ["claude-fable-5-1", true],
  ["claude-mythos-5-1", true],
  ["claude-fable-5.1", true],
  ["anthropic/claude-fable-5.1", true],
  ["claude-fable-5-1@default", true],
  ["claude-fable-5-1@20260901", true],
  ["claude-sonnet-6", true],
  ["claude-opus-5-20260901", false],
  ["claude-opus-4-8", false],
  ["anthropic/claude-opus-4.8", false],
  ["claude-fable-5@default", false],
  ["kimi-k2.5", false],
] as const) {
  it.effect(`thinking-binding defaults for ${id}`, () =>
    Effect.gen(function* () {
      const request = LLM.request({
        model: AnthropicMessages.route.model({ id }),
        prompt: "Hello",
        http: { headers: { "anthropic-beta": "existing-beta" } },
      })
      const compiled = yield* compileRequest(request)
      const prepared = yield* AnthropicMessages.route.prepareTransport(compiled.body, request)
      expect(compiled.body.thinking).toEqual(
        enabled ? { type: "adaptive", block_binding: { prefix_mismatch_behavior: "drop_block" } } : undefined,
      )
      expect(prepared.request.headers["anthropic-beta"]).toBe(
        enabled
          ? "existing-beta,interleaved-thinking-2025-05-14,thinking-binding-controls-2026-08-01"
          : "existing-beta,interleaved-thinking-2025-05-14",
      )
    }),
  )
}

it.effect("preserves explicit thinking settings and combines required beta headers", () =>
  Effect.gen(function* () {
    for (const thinking of [
      { type: "disabled" },
      { type: "between_tools" },
      { type: "adaptive", block_binding: { prefix_mismatch_behavior: "error" } },
    ] as const) {
      const request = LLM.request({
        model: AnthropicMessages.route.model({ id: "claude-fable-5-1" }),
        prompt: "Hello",
        providerOptions: { thinking, contextManagement: { edits: [{ type: "compact_20260112" }] } },
      })
      const compiled = yield* compileRequest(request)
      const prepared = yield* AnthropicMessages.route.prepareTransport(compiled.body, request)
      expect(compiled.body.thinking).toEqual(thinking)
      expect(prepared.request.headers["anthropic-beta"]).toBe(
        thinking.type === "disabled" || thinking.type === "between_tools"
          ? "interleaved-thinking-2025-05-14,compact-2026-01-12"
          : "interleaved-thinking-2025-05-14,compact-2026-01-12,thinking-binding-controls-2026-08-01",
      )
    }
  }),
)

import { describe, expect } from "bun:test"
import { Effect } from "effect"
import { Transcription } from "../../src/index.js"
import { AssemblyAI } from "../../src/providers.js"
import { recordedTests } from "../recorded-test.js"
import { TRANSCRIPT, audio, audioRecording } from "./transcription-recording.js"
import { queuedPoll } from "./queued-recording.js"

// Recorded against the EU region: the US endpoint was unreachable from the recording network. Same API and shapes.
const model = AssemblyAI.configure({
  apiKey: process.env.ASSEMBLYAI_API_KEY ?? "fixture",
  baseURL: "https://api.eu.assemblyai.com",
}).transcription("universal-3-5-pro")

const recorded = recordedTests({
  prefix: "assemblyai-transcription",
  provider: "assemblyai",
  protocol: "assemblyai-transcription",
  requires: ["ASSEMBLYAI_API_KEY"],
  options: audioRecording,
})

describe("AssemblyAI Transcription recorded", () => {
  recorded.effect(
    "uploads, submits, and polls a transcript",
    () =>
      Effect.gen(function* () {
        const generation = yield* Transcription.start({ model, audio: yield* audio, diarize: true })
        const response = yield* generation.await({ poll: queuedPoll })

        expect(response.text).toMatch(TRANSCRIPT)
        expect(response.words?.[0]).toMatchObject({ text: "Hello", speaker: "A" })
        expect(response.words?.every((word) => word.startSeconds < 5 && word.endSeconds < 5)).toBe(true)
        expect(response.segments?.[0]?.speaker).toBe("A")
        expect(response.usage).toEqual({ type: "seconds", seconds: expect.any(Number) })
      }),
    { timeout: 15 * 60 * 1000 },
  )
})

