import { describe, expect } from "bun:test"
import { Effect } from "effect"
import { Speech } from "../../src/index.js"
import { Deepgram } from "../../src/providers.js"
import { recordedTests } from "../recorded-test.js"
import { TEXT, collectSpeech } from "./speech-recording.js"

const model = Deepgram.configure({
  apiKey: process.env.DEEPGRAM_API_KEY ?? "fixture",
}).speech("aura-2-thalia-en")

const recorded = recordedTests({
  prefix: "deepgram-speech",
  provider: "deepgram",
  protocol: "deepgram-speech",
  requires: ["DEEPGRAM_API_KEY"],
  // Usage and the request id arrive only as response headers.
  options: { redact: { allowResponseHeaders: ["dg-char-count", "dg-request-id", "dg-model-name"] } },
})

describe("Deepgram Speech recorded", () => {
  recorded.effect("generates speech", () =>
    Effect.gen(function* () {
      const response = yield* Speech.generate({ model, text: TEXT })

      expect(response.audio.mediaType).toBe("audio/mpeg")
      expect(response.audio.info).toEqual({ format: "mp3" })
      expect((yield* response.audio.bytes()).length).toBeGreaterThan(0)
      expect(response.usage).toEqual({ type: "characters", characters: expect.any(Number) })
    }),
  )

  recorded.effect("streams speech", () =>
    Effect.gen(function* () {
      const { finish } = yield* collectSpeech(Speech.stream({ model, text: TEXT, format: "pcm" }))

      expect(finish.audio.info).toMatchObject({ format: "pcm", encoding: "pcm_s16le", channels: 1 })
      expect(finish.usage).toEqual({ type: "characters", characters: expect.any(Number) })
    }),
  )
})

import { describe, expect } from "bun:test"
import { Effect, Stream } from "effect"
import { Transcription } from "../../src/index.js"
import { Deepgram } from "../../src/providers.js"
import { recordedTests } from "../recorded-test.js"
import { TRANSCRIPT, audio, audioRecording, dialog } from "./transcription-recording.js"

const model = Deepgram.configure({ apiKey: process.env.DEEPGRAM_API_KEY ?? "fixture" }).transcription("nova-3")

const recorded = recordedTests({
  prefix: "deepgram-transcription",
  provider: "deepgram",
  protocol: "deepgram-transcription",
  requires: ["DEEPGRAM_API_KEY"],
  options: audioRecording,
})

describe("Deepgram Transcription recorded", () => {
  recorded.effect("transcribes raw audio with speakers and word timestamps", () =>
    Effect.gen(function* () {
      const request = Transcription.request({ model, audio: yield* audio, diarize: true, timestamps: "word" })
      const response = yield* Transcription.generate(request)

      expect(response.text).toMatch(TRANSCRIPT)
      expect(response.words?.map((word) => word.text)).toEqual(["Hello", "from", "OpenCode."])
      expect(response.words?.every((word) => word.speaker === "0" && word.confidence !== undefined)).toBe(true)
      expect(response.segments).toEqual([
        { text: response.text, startSeconds: expect.any(Number), endSeconds: expect.any(Number), speaker: "0" },
      ])
      expect(response.language).toBe("en")
      expect(response.usage).toEqual({ type: "seconds", seconds: response.durationSeconds })

      const events = Array.from(yield* Stream.runCollect(Transcription.stream(request)))
      expect(events.map((event) => event.type)).toEqual(["finish"])
    }),
  )

  recorded.effect("splits utterances at speaker changes", () =>
    Effect.gen(function* () {
      const response = yield* Transcription.generate({ model, audio: yield* dialog, diarize: true })

      expect(response.segments?.map((segment) => segment.speaker)).toEqual(["0", "1"])
      expect(response.segments?.[0].text).toMatch(/release ship\?$/)
      expect(response.segments?.[1].text).toMatch(/shipped this morning\.$/)
    }),
  )
})

import { describe, expect } from "bun:test"
import { Effect } from "effect"
import { LLM, LLMRequest } from "../../src/index.js"
import { DigitalOcean } from "../../src/providers/digitalocean.js"
import { LLMClient } from "../../src/route.js"
import {
  LARGE_CACHEABLE_SYSTEM,
  expectWeatherToolLoop,
  goldenWeatherToolLoopRequest,
  runWeatherToolLoop,
} from "../recorded-scenarios.js"
import { recordedTests } from "../recorded-test.js"

const recorded = recordedTests({
  prefix: "digitalocean-chat",
  provider: "digitalocean",
  protocol: "digitalocean-chat",
  requires: ["DIGITAL_OCEAN_OFFICIAL_API_KEY"],
})

for (const item of [
  { id: "anthropic-claude-haiku-4.5", name: "Haiku", maxTokens: 128, providerOptions: undefined },
  { id: "openai-gpt-5-nano", name: "GPT Nano", maxTokens: 1024, providerOptions: { reasoningEffort: "minimal" } },
] as const) {
  const model = DigitalOcean.configure({
    apiKey: process.env.DIGITAL_OCEAN_OFFICIAL_API_KEY ?? "fixture",
    providerOptions: item.providerOptions,
  }).model(item.id)

  describe(`DigitalOcean ${item.name} recorded`, () => {
    recorded.effect.with(
      `${item.name} reuses a cached prompt`,
      { tags: ["cache", "usage"], metadata: { model: item.id } },
      () =>
        Effect.gen(function* () {
          const request = LLM.request({
            model,
            system: LARGE_CACHEABLE_SYSTEM,
            prompt: "Reply exactly: OK",
            promptCacheKey: `digitalocean-recorded-${item.id}`,
            generation: { maxTokens: item.maxTokens },
          })
          const first = yield* LLMClient.generate(request)
          const second = yield* LLMClient.generate(request)

          expect(first.text.trim()).toMatch(/^OK\.?$/)
          expect(second.text.trim()).toMatch(/^OK\.?$/)
          expect(second.usage.cacheReadInputTokens).toBeGreaterThan(0)
          for (const response of [first, second]) {
            expect(response.usage.inputTokens).toBeGreaterThan(4096)
            expect(response.usage.inputTokens).toBe(
              (response.usage.nonCachedInputTokens ?? 0) +
                (response.usage.cacheReadInputTokens ?? 0) +
                (response.usage.cacheWriteInputTokens ?? 0),
            )
          }
        }),
      60_000,
    )

    recorded.effect.with(
      `${item.name} continues a tool call with cache markers`,
      { tags: ["cache", "tool", "tool-loop"], metadata: { model: item.id } },
      () =>
        Effect.gen(function* () {
          const request = goldenWeatherToolLoopRequest({
            id: `digitalocean-${item.id}-tool-loop`,
            model,
            maxTokens: item.maxTokens,
            temperature: false,
          })
          const events = yield* runWeatherToolLoop(LLMRequest.update(request, { cache: "auto" }))
          expectWeatherToolLoop(events)
        }),
      60_000,
    )
  })
}

import { describe, expect, test } from "bun:test"
import { Effect } from "effect"
import { CacheHint, LLM } from "../../src/index.js"
import { compileRequest } from "../../src/route/client.js"
import { DigitalOcean } from "../../src/providers/digitalocean.js"
import { it } from "../lib/effect.js"
import { fixedResponse } from "../lib/http.js"
import { sseEvents } from "../lib/sse.js"
import { LLMClient } from "../../src/route.js"

describe("DigitalOcean", () => {
  test("preserves package entrypoint headers and body overrides", () => {
    const model = DigitalOcean.model("anthropic-claude-fable-5.1", {
      apiKey: "test-key",
      headers: { "X-Test": "fixture" },
      body: { temperature: 0 },
    })
    expect(model.route.defaults?.http).toMatchObject({
      headers: { "X-Test": "fixture" },
      body: { temperature: 0 },
    })
  })

  it.effect("prepares DigitalOcean models with default endpoint and auth", () =>
    Effect.gen(function* () {
      const model = DigitalOcean.configure({ apiKey: "test-key" }).model("anthropic-claude-fable-5.1")

      expect(model).toMatchObject({
        id: "anthropic-claude-fable-5.1",
        provider: "digitalocean",
        route: { id: "digitalocean" },
      })
      expect(model.route.endpoint.baseURL).toBe("https://inference.do-ai.run/v1")

      const prepared = yield* compileRequest(LLM.request({ model, prompt: "Say hello.", cache: "none" }))

      expect(prepared.route).toBe("digitalocean")
      expect(prepared.body).toMatchObject({
        model: "anthropic-claude-fable-5.1",
        messages: [{ role: "user", content: "Say hello." }],
        stream: true,
      })
    }),
  )

  it.effect("lowers the native cache policy to DigitalOcean cache_control markers", () =>
    Effect.gen(function* () {
      const prepared = yield* compileRequest(
        LLM.request({
          model: DigitalOcean.configure({ apiKey: "test-key" }).model("anthropic-claude-fable-5.1"),
          system: [
            { type: "text", text: "Base agent", cache: new CacheHint({ type: "ephemeral", ttlSeconds: 3_600 }) },
            { type: "text", text: "Project instructions" },
          ],
          tools: [{ name: "lookup", description: "Lookup", inputSchema: { type: "object", properties: {} } }],
          prompt: "Hello",
          cache: { tools: true, system: true, messages: { tail: 1 } },
        }),
      )

      expect(prepared.body).toMatchObject({
        tools: [{ cache_control: { type: "ephemeral" } }],
        messages: [
          {
            role: "system",
            content: [
              { text: "Base agent", cache_control: { type: "ephemeral", ttl: "1h" } },
              { text: "Project instructions", cache_control: { type: "ephemeral" } },
            ],
          },
          {
            role: "user",
            content: [{ text: "Hello", cache_control: { type: "ephemeral" } }],
          },
        ],
      })
    }),
  )

  it.effect("parses DigitalOcean cache usage fields into AI.Usage", () =>
    Effect.gen(function* () {
      const model = DigitalOcean.configure({ apiKey: "test-key" }).model("anthropic-claude-fable-5.1")
      const response = yield* LLMClient.generate(LLM.request({ model, prompt: "Say OK" })).pipe(
        Effect.provide(
          fixedResponse(
            sseEvents(
              {
                id: "chatcmpl-1",
                object: "chat.completion.chunk",
                created: 1,
                model: "anthropic-claude-fable-5.1",
                choices: [{ index: 0, delta: { content: "OK" }, finish_reason: null }],
              },
              {
                id: "chatcmpl-1",
                object: "chat.completion.chunk",
                created: 1,
                model: "anthropic-claude-fable-5.1",
                choices: [{ index: 0, delta: {}, finish_reason: "stop" }],
                usage: {
                  prompt_tokens: 4491,
                  completion_tokens: 8,
                  total_tokens: 4499,
                  cache_read_input_tokens: 4483,
                  cache_created_input_tokens: 0,
                },
              },
              "[DONE]",
            ),
          ),
        ),
      )

      expect(response.usage).toMatchObject({
        inputTokens: 4491,
        outputTokens: 8,
        nonCachedInputTokens: 8,
        cacheReadInputTokens: 4483,
        totalTokens: 4499,
      })
    }),
  )
})

import { describe, expect } from "bun:test"
import { Effect } from "effect"
import { Speech, SpeechEvent } from "../../src/index.js"
import { ElevenLabs } from "../../src/providers.js"
import { recordedTests } from "../recorded-test.js"
import { TEXT, collectSpeech } from "./speech-recording.js"

const model = ElevenLabs.configure({
  apiKey: process.env.ELEVENLABS_API_KEY ?? "fixture",
}).speech("eleven_flash_v2_5")

// "George", an ElevenLabs premade voice.
const voice = "JBFqnCBsd6RMkjVDRZzb"

const recorded = recordedTests({
  prefix: "elevenlabs-speech",
  provider: "elevenlabs",
  protocol: "elevenlabs-speech",
  requires: ["ELEVENLABS_API_KEY"],
  // Usage and the request id arrive only as response headers.
  options: { redact: { allowResponseHeaders: ["character-cost", "request-id"] } },
})

describe("ElevenLabs Speech recorded", () => {
  recorded.effect("generates speech", () =>
    Effect.gen(function* () {
      const response = yield* Speech.generate({ model, text: TEXT, voice })

      expect(response.audio.mediaType).toBe("audio/mpeg")
      expect(response.audio.info).toMatchObject({ format: "mp3", sampleRate: 44100 })
      expect((yield* response.audio.bytes()).length).toBeGreaterThan(0)
      expect(response.usage).toEqual({ type: "credits", credits: 3 })
    }),
  )

  recorded.effect("streams speech with timestamps", () =>
    Effect.gen(function* () {
      const { events, finish } = yield* collectSpeech(
        Speech.stream({ model, text: TEXT, voice, format: "pcm", timestamps: true }),
      )
      const timestamps = events.filter(SpeechEvent.is.timestamps).flatMap((event) => event.items)

      expect(finish.audio.mediaType).toBe("audio/pcm")
      expect(finish.audio.info).toMatchObject({ encoding: "pcm_s16le", sampleRate: 24000, channels: 1 })
      expect(
        timestamps
          .map((item) => item.text)
          .join("")
          .trim(),
      ).toBe(TEXT)
      expect(timestamps.every((item) => item.endSeconds >= item.startSeconds)).toBe(true)
    }),
  )
})

import { describe, expect } from "bun:test"
import { Effect, Stream } from "effect"
import { Transcription } from "../../src/index.js"
import { ElevenLabs } from "../../src/providers.js"
