describe("MiniMax provider", () => {
  test("composes the baseline Messages and Responses protocols", () => {
    const minimax = MiniMax.configure()
    expect(minimax.model).toBe(minimax.messages)
    expect(minimax.model("MiniMax-M3").route.body).toBe(AnthropicMessages.protocol.body)
    expect(minimax.responses("MiniMax-M3").route.body).toBe(OpenResponses.protocol.body)
  })

  it.effect("owns API endpoints, provider identity and environment bearer authentication", () =>
    Effect.gen(function* () {
      const minimax = MiniMax.configure()
      for (const item of [
        { model: minimax.model("MiniMax-M3"), path: "/anthropic/v1/messages" },
        { model: minimax.chat("MiniMax-M3"), path: "/v1/chat/completions" },
        { model: minimax.responses("MiniMax-M3"), path: "/v1/responses" },
      ]) {
        const request = LLM.request({ model: item.model, prompt: "Hello" })
        const compiled = yield* compileRequest(request)
        expect(item.model.provider).toBe("minimax")
        expect(item.model.route.providerMetadataKey).toBe("minimax")
        const url = Endpoint.render(item.model.route.endpoint, { request, body: compiled.body }).toString()
        expect(url).toBe(`https://api.minimax.io${item.path}`)
        const headers = yield* item.model.route.auth.apply({
          request,
          method: "POST",
          url,
          body: "{}",
          headers: Headers.empty,
        })
        expect(headers.authorization).toBe("Bearer fixture-key")
        expect(headers["x-api-key"]).toBeUndefined()
      }
    }).pipe(Effect.provide(ConfigProvider.layer(ConfigProvider.fromEnv({ env: { MINIMAX_API_KEY: "fixture-key" } })))),
  )

  it.effect("honors explicit auth and custom API bases", () =>
    Effect.gen(function* () {
      const model = MiniMax.configure({
        baseURL: "https://gateway.example/anthropic/v1",
        auth: Auth.header("x-api-key", "gateway-key"),
      }).model("custom-model")
      const request = LLM.request({ model, prompt: "Hello" })
      const compiled = yield* compileRequest(request)
      expect(Endpoint.render(model.route.endpoint, { request, body: compiled.body }).toString()).toBe(
        "https://gateway.example/anthropic/v1/messages",
      )
      expect(model.route.headers?.({ request })).toEqual({ "anthropic-version": "2023-06-01" })
      const headers = yield* model.route.auth.apply({
        request,
        method: "POST",
        url: "https://gateway.example/anthropic/v1/messages",
        body: "{}",
        headers: Headers.empty,
      })
      expect(headers["x-api-key"]).toBe("gateway-key")
      expect(headers.authorization).toBeUndefined()
    }),
  )

  it.effect("keeps thinking controls native to the selected API", () =>
    Effect.gen(function* () {
      const minimax = MiniMax.configure({ apiKey: "fixture" })
      const messages = yield* compileRequest(
        LLM.request({ model: minimax.model("MiniMax-M3"), providerOptions: { thinking: { type: "adaptive" } } }),
      )
      expect(messages.body.thinking).toEqual({ type: "adaptive" })
      expect(messages.body.output_config).toBeUndefined()
      const chat = yield* compileRequest(
        LLM.request({
          model: minimax.chat("MiniMax-M3"),
          generation: { maxTokens: 128 },
          providerOptions: { thinking: { type: "disabled" }, reasoningSplit: false },
        }),
      )
      expect(chat.body).toMatchObject({
        thinking: { type: "disabled" },
        reasoning_split: false,
        max_completion_tokens: 128,
        stream_options: { include_usage: true },
      })
      expect(chat.body.store).toBeUndefined()
      const responses = yield* compileRequest(
        LLM.request({ model: minimax.responses("MiniMax-M3"), providerOptions: { reasoningEffort: "minimal" } }),
      )
      expect(responses.body.reasoning).toEqual({ effort: "minimal" })
      expect(responses.body.include).toBeUndefined()
    }),
  )
})

import { expect } from "bun:test"
import { Effect, Schema } from "effect"
import { LLM, Message, ToolCallPart } from "../../src/index.js"
import { OpenAIChat } from "../../src/protocols/openai-chat.js"
import { OpenAIResponses } from "../../src/protocols/openai-responses.js"
import { Auth } from "../../src/route/auth.js"
import { compileRequest } from "../../src/route/client.js"
import { it } from "../lib/effect.js"

for (const route of [OpenAIChat.route, OpenAIResponses.route]) {
  const model = route
    .with({ endpoint: { baseURL: "https://api.openai.test/v1" }, auth: Auth.bearer("test") })
    .model({ id: "gpt-4.1-mini" })
  const chat = route.id === "openai-chat"

  it.effect(`${route.id} serializes schema-valid undefined historical tool input as an empty object`, () =>
    Effect.gen(function* () {
      const message = Schema.decodeUnknownSync(Message)({
        role: "assistant",
        content: [{ type: "tool-call", id: "call_1", name: "lookup", input: undefined }],
      })
      expect(Schema.is(Message)(message)).toBe(true)
      const prepared = yield* compileRequest(
        LLM.request({
          model,
          messages: [
            Message.user("Look up the value."),
            message,
            Message.tool({ id: "call_1", name: "lookup", result: "Missing input", resultType: "error" }),
          ],
        }),
      )
      if (chat)
        expect(prepared.body.messages).toContainEqual({
          role: "assistant",
          content: null,
          tool_calls: [{ id: "call_1", type: "function", function: { name: "lookup", arguments: "{}" } }],
        })
      if (!chat)
        expect(prepared.body.input).toContainEqual({
          type: "function_call",
          call_id: "call_1",
          name: "lookup",
          arguments: "{}",
        })
      expect(message.content[0]).toEqual({ type: "tool-call", id: "call_1", name: "lookup", input: undefined })
    }),
  )

  it.effect(`${route.id} preserves defined historical tool inputs`, () =>
    Effect.gen(function* () {
      for (const [input, encoded] of [
        [null, "null"],
        [[], "[]"],
        [42, "42"],
        ["invalid", '"invalid"'],
        [{ value: "original" }, '{"value":"original"}'],
      ] as const) {
        const prepared = yield* compileRequest(
          LLM.request({
            model,
            messages: [
              Message.assistant([ToolCallPart.make({ id: "call_1", name: "lookup", input })]),
              Message.tool({ id: "call_1", name: "lookup", result: "Invalid input", resultType: "error" }),
            ],
          }),
        )
        if (chat) expect(prepared.body.messages[0].tool_calls[0].function.arguments).toBe(encoded)
        if (!chat) expect(prepared.body.input[0].arguments).toBe(encoded)
      }
    }),
  )
}

import { describe, expect, test } from "bun:test"
import { ConfigProvider, Effect } from "effect"
import { HttpClientRequest } from "effect/http"
import { LanguageModel, LLM, LLMEvent, Message, SystemPart, ToolDefinition, Media } from "../../src/index.js"
import { Mistral } from "../../src/providers/index.js"
import { MistralChat } from "../../src/protocols/index.js"
import { LLMClient } from "../../src/route.js"
import { compileRequest } from "../../src/route/client.js"
import { it } from "../lib/effect.js"
import { dynamicResponse, fixedResponse } from "../lib/http.js"
import { sseEvents } from "../lib/sse.js"

const model = Mistral.configure({ apiKey: "fixture" }).model("mistral-large-latest")
const request = LLM.request({ model, prompt: "Hello" })
const chunk = (delta: object, finishReason: string | null = null, usage?: object) => ({
  choices: [{ delta, finish_reason: finishReason }],
  usage,
})

describe("Mistral Chat", () => {
  test("exposes native provider and protocol identities", async () => {
    const entrypoint = await import("@opencode/ai/providers/mistral")

    expect(Mistral.id).toBe("mistral")
    expect(MistralChat.protocol.id).toBe("mistral-chat")
    expect(Mistral.route).toMatchObject({
      id: "mistral-chat",
      provider: "mistral",
      providerMetadataKey: "mistral",
      protocol: "mistral-chat",
    })
    expect(Mistral.route.endpoint).toMatchObject({
      baseURL: "https://api.mistral.ai/v1",
      path: "/chat/completions",
    })
    expect(entrypoint.model).toBeFunction()
  })

  it.effect("lowers native messages, media, tool choice, options, and replay IDs", () =>
    Effect.gen(function* () {
      const prepared = yield* compileRequest(
        LLM.request({
          model,
          system: [SystemPart.make("Initial\nKeep this newline."), SystemPart.make("Second instructions.")],
          messages: [
            Message.system("Updated"),
            Message.user([
              { type: "text", text: "Inspect" },
              { type: "media", media: Media.base64("aW1hZ2U=", "image/png") },
              { type: "media", media: Media.base64("cGRm", "application/pdf") },
            ]),
            Message.assistant([
              { type: "reasoning", text: "Think" },
              { type: "text", text: "Calling" },
              { type: "tool-call", id: "call.same-prefix-1", name: "lookup", input: { city: "Paris" } },
              { type: "tool-call", id: "call.same-prefix-2", name: "other", input: {} },
            ]),
            Message.tool({ id: "call.same-prefix-1", name: "lookup", result: { ok: true } }),
          ],
          tools: [
            ToolDefinition.make({ name: "lookup", description: "Look up a city", inputSchema: { type: "object" } }),
            ToolDefinition.make({ name: "other", description: "Other operation", inputSchema: {} }),
          ],
          toolChoice: "lookup",
          promptCacheKey: "session-1",
          generation: {
            maxTokens: 64,
            seed: 7,
            temperature: 0.2,
            topP: 0.8,
            frequencyPenalty: 0.1,
            presencePenalty: 0.3,
            stop: ["done"],
          },
          providerOptions: {
            safePrompt: true,
            documentImageLimit: 3,
            documentPageLimit: 8,
            parallelToolCalls: false,
            reasoningEffort: "high",
          },
        }),
      )

      expect(prepared.body).toMatchObject({
        model: "mistral-large-latest",
        tools: [
          { function: { name: "lookup", strict: false } },
          { function: { name: "other", strict: false, parameters: { type: "object" } } },
        ],
        tool_choice: { type: "function", function: { name: "lookup" } },
        stream: true,
        max_tokens: 64,
        random_seed: 7,
        temperature: 0.2,
        top_p: 0.8,
        frequency_penalty: 0.1,
        presence_penalty: 0.3,
        stop: ["done"],
        prompt_cache_key: "session-1",
        safe_prompt: true,
        document_image_limit: 3,
        document_page_limit: 8,
        parallel_tool_calls: false,
        reasoning_effort: "high",
      })
      expect(prepared.body.messages.slice(0, 4)).toMatchObject([
        {
          role: "system",
          content: [
            { type: "text", text: "Initial\nKeep this newline." },
            { type: "text", text: "Second instructions." },
          ],
        },
        { role: "user", content: "<system-update>\nUpdated\n</system-update>" },
        {
          role: "user",
          content: [
            { type: "text", text: "Inspect" },
            { type: "image_url", image_url: "data:image/png;base64,aW1hZ2U=" },
            { type: "document_url", document_url: "data:application/pdf;base64,cGRm" },
          ],
        },
        {
          role: "assistant",
          content: "ThinkCalling",
        },
      ])
      const assistant = prepared.body.messages[3]
      const toolResult = prepared.body.messages[4]
      expect(assistant?.role).toBe("assistant")
      expect(toolResult?.role).toBe("tool")
      if (assistant?.role !== "assistant" || toolResult?.role !== "tool") return
      const ids = assistant.tool_calls?.map((tool) => tool.id) ?? []
      expect(ids).toHaveLength(2)
      expect(ids[0]).toMatch(/^[A-Za-z0-9]{9}$/)
      expect(ids[1]).toMatch(/^[A-Za-z0-9]{9}$/)
      expect(ids[0]).not.toBe(ids[1])
      expect(toolResult.tool_call_id).toBe(ids[0])
      expect(toolResult.name).toBe("lookup")
    }),
  )

  it.effect("preserves valid replay IDs", () =>
    Effect.gen(function* () {
      const prepared = yield* compileRequest(
        LLM.request({
          model,
          messages: [
            Message.assistant({ type: "tool-call", id: "Ab12Cd34E", name: "lookup", input: {} }),
            Message.tool({ id: "Ab12Cd34E", name: "lookup", result: "ok" }),
          ],
        }),
      )
      expect(prepared.body.messages).toMatchObject([
        { tool_calls: [{ id: "Ab12Cd34E" }] },
        { tool_call_id: "Ab12Cd34E" },
      ])
    }),
  )

  it.effect("applies trailing prefix, cache, and reasoning options without changing earlier assistants", () =>
    Effect.gen(function* () {
      const prepared = yield* compileRequest(
        LLM.request({
          model,
          promptCacheKey: "common-key",
          messages: [Message.assistant("Earlier"), Message.user("Continue"), Message.assistant("Prefix")],
          providerOptions: { promptCacheKey: "native-key", promptMode: "reasoning" },
        }),
      )
      expect(prepared.body.prompt_cache_key).toBe("native-key")
      expect(prepared.body.prompt_mode).toBe("reasoning")
      expect(prepared.body.messages).toEqual([
        { role: "assistant", content: "Earlier" },
        { role: "user", content: "Continue" },
        { role: "assistant", content: "Prefix", prefix: true },
      ])

      const uncached = yield* compileRequest(
        LLM.request({
          model,
          prompt: "Hello",
          promptCacheKey: "common-key",
          cache: "none",
          providerOptions: { promptCacheKey: "native-key" },
        }),
      )
      expect(uncached.body.prompt_cache_key).toBeUndefined()

      const unsupported = yield* compileRequest(
        LLM.request({
          model: LanguageModel.update(model, { compatibility: { supportsPromptCacheKey: false } }),
          prompt: "Hello",
          promptCacheKey: "common-key",
          providerOptions: { promptCacheKey: "native-key" },
        }),
      )
      expect(unsupported.body.prompt_cache_key).toBeUndefined()

      const longKey = "cache-key-".repeat(10)
      const unbounded = yield* compileRequest(
        LLM.request({
          model,
          prompt: "Hello",
          promptCacheKey: longKey,
        }),
      )
      expect(unbounded.body.prompt_cache_key).toBe(longKey)

      const conflict = yield* compileRequest(
        LLM.request({
          model,
          prompt: "Hello",
          providerOptions: { reasoningEffort: "high", promptMode: "reasoning" },
        }),
      ).pipe(Effect.flip)
      expect(conflict.message).toContain("mutually exclusive")
    }),
  )

  it.effect("omits empty assistant history unless it carries a tool call", () =>
    Effect.gen(function* () {
      const prepared = yield* compileRequest(
        LLM.request({
          model,
          messages: [
            Message.assistant(" \n "),
            Message.assistant({ type: "reasoning", text: "\t" }),
            Message.assistant({ type: "tool-call", id: "Ab12Cd34E", name: "lookup", input: {} }),
          ],
        }),
      )
      expect(prepared.body.messages[0]).toEqual({
        role: "assistant",
        content: "",
        tool_calls: [{ id: "Ab12Cd34E", type: "function", function: { name: "lookup", arguments: "{}" } }],
      })
    }),
  )

  it.effect("preserves remote media URLs and structured tool-result media", () =>
    Effect.gen(function* () {
      const prepared = yield* compileRequest(
        LLM.request({
          model,
          messages: [
            Message.user({
              type: "media",
              media: Media.url("https://assets.example.test/input.png", { mediaType: "image/png" }),
            }),
            Message.tool({
              id: "Ab12Cd34E",
              name: "inspect",
              resultType: "content",
              result: [
                { type: "text", text: "Result" },
                { type: "file", mime: "image/jpeg", uri: "https://assets.example.test/output.jpg" },
                { type: "file", mime: "application/pdf", uri: "cGRm" },
              ],
            }),
          ],
        }),
      )
      expect(prepared.body.messages).toEqual([
        {
          role: "user",
          content: [{ type: "image_url", image_url: "https://assets.example.test/input.png" }],
        },
        {
          role: "tool",
          tool_call_id: "Ab12Cd34E",
          name: "inspect",
          content: [
            { type: "text", text: "Result" },
            { type: "image_url", image_url: "https://assets.example.test/output.jpg" },
            { type: "document_url", document_url: "data:application/pdf;base64,cGRm" },
          ],
        },
      ])
    }),
