      ).toEqual([
        ["Con", undefined],
        ["sider", undefined],
      ])
      expect(response.message.content).toEqual([
        {
          type: "reasoning",
          text: "Consider",
          providerMetadata: {
            mistral: {
              thinking: {
                type: "thinking",
                thinking: [
                  { type: "text", text: "Con" },
                  { type: "text", text: "sider" },
                ],
                marker: "empty",
                closed: true,
              },
