        {
          type: "text-end",
          id: "msg_1",
          providerMetadata: { "openai-compatible": { itemId: "msg_1", phase: "commentary" } },
        },
        {
          type: "text-start",
          id: "msg_2",
          providerMetadata: { "openai-compatible": { itemId: "msg_2", phase: null } },
        },
        { type: "text-delta", id: "msg_2", text: "Cannot help." },
        {
