        },
        { type: "text-delta", id: "msg_3", text: "Done-only refusal." },
        { type: "text-end", id: "msg_3", providerMetadata: { "openai-compatible": { itemId: "msg_3", phase: null } } },
      ])
    }),
  )

  it.effect("preserves non-empty done-only message content", () =>
    Effect.gen(function* () {
      const text = {
        type: "message",
