      }
      const events = yield* collect(
        { type: "response.output_item.done", item: text },
        {
          type: "response.output_item.done",
          item: { type: "message", id: "msg_empty", content: [{ type: "output_text", text: "" }] },
        },
        { type: "response.output_item.done", item: refusal },
        completed,
      )

      expect(events.filter((event) => event.type.startsWith("text-"))).toEqual([
        {
          type: "text-start",
          id: "msg_text",
          providerMetadata: { "openai-compatible": { itemId: "msg_text" } },
        },
        {
          type: "text-end",
          id: "msg_text",
          text: "Done-only text.",
          providerMetadata: { "openai-compatible": { itemId: "msg_text" } },
        },
        {
          type: "text-start",
          id: "msg_refusal",
          providerMetadata: { "openai-compatible": { itemId: "msg_refusal" } },
        },
        {
          type: "text-end",
          id: "msg_refusal",
          text: "Done-only refusal.",
          providerMetadata: { "openai-compatible": { itemId: "msg_refusal" } },
        },
      ])
    }),
  )

  // Captured from Bedrock Mantle (openai.gpt-oss-120b): the terminal function_call
  // items rename `id` to `item_id` and carry a stray `output_index`.
  it.effect("recovers a terminal function_call id from its output slot", () =>
    Effect.gen(function* () {
      const terminal = {
        type: "function_call",
        item_id: "fc_828bee50dee1d029",
        call_id: "call_bc1eb4b42e70ee53",
        name: "get_weather",
        arguments: '{\n  "city": "Paris"\n}',
        output_index: 1,
        status: "completed",
      }
      const events = yield* collect(
        {
          type: "response.output_item.added",
          output_index: 0,
          item: { type: "reasoning", id: "msg_879a68b589198b4c" },
        },
        { type: "response.output_item.done", output_index: 0, item: { type: "reasoning", id: "msg_879a68b589198b4c" } },
        {
          type: "response.output_item.added",
          output_index: 1,
          item: {
            type: "function_call",
            id: "fc_828bee50dee1d029",
            call_id: "call_bc1eb4b42e70ee53",
            name: "get_weather",
            arguments: "",
            status: "in_progress",
          },
        },
        {
          type: "response.function_call_arguments.delta",
          output_index: 1,
          item_id: "fc_828bee50dee1d029",
          delta: '{\n  "city": "Paris"\n}',
        },
        {
          type: "response.function_call_arguments.done",
          output_index: 1,
          item_id: "fc_828bee50dee1d029",
          arguments: '{\n  "city": "Paris"\n}',
        },
        { type: "response.output_item.done", output_index: 1, item: terminal },
        {
          type: "response.completed",
          response: { id: "resp_1", output: [{ type: "reasoning", id: "msg_879a68b589198b4c" }, terminal] },
        },
      )
      const providerMetadata = { "openai-compatible": { itemId: "fc_828bee50dee1d029" } }
      expect(events.filter((event) => event.type.startsWith("tool-"))).toEqual([
        { type: "tool-input-start", id: "call_bc1eb4b42e70ee53", name: "get_weather", providerMetadata },
        {
          type: "tool-input-delta",
          id: "call_bc1eb4b42e70ee53",
          name: "get_weather",
          text: '{\n  "city": "Paris"\n}',
          input: { city: "Paris" },
        },
        { type: "tool-input-end", id: "call_bc1eb4b42e70ee53", name: "get_weather", providerMetadata },
        {
          type: "tool-call",
          id: "call_bc1eb4b42e70ee53",
          name: "get_weather",
          input: { city: "Paris" },
          providerMetadata,
        },
      ])
    }),
  )
  it.effect("mints an id for a done-only tool that never had one", () =>
    Effect.gen(function* () {
      const events = yield* collect(
        {
          type: "response.output_item.done",
          output_index: 0,
          item: { type: "function_call", call_id: "call_1", name: "lookup", arguments: '{"query":"weather"}' },
        },
        completed,
      )
      const call = events.find(LLMEvent.is.toolCall)
      expect(call).toMatchObject({ id: "call_1", name: "lookup", input: { query: "weather" } })
      expect(call?.providerMetadata?.["openai-compatible"]).toMatchObject({
        itemId: expect.stringMatching(/^fc_[0-9a-f]{32}$/),
      })
    }),
  )

  it.effect("opens and closes a done-only tool", () =>
    Effect.gen(function* () {
      const item = {
        type: "function_call",
        id: "fc_1",
        call_id: "call_1",
        name: "lookup",
        arguments: '{"query":"weather"}',
      }
      const events = yield* collect({ type: "response.output_item.done", item }, completed)
      const providerMetadata = { "openai-compatible": { itemId: "fc_1" } }
      expect(events.filter((event) => event.type.startsWith("tool-"))).toEqual([
        { type: "tool-input-start", id: "call_1", name: "lookup", namespace: undefined, providerMetadata },
        { type: "tool-input-end", id: "call_1", name: "lookup", namespace: undefined, providerMetadata },
        {
          type: "tool-call",
          id: "call_1",
          name: "lookup",
          namespace: undefined,
          input: { query: "weather" },
          providerMetadata,
        },
      ])
      expect(events.filter(LLMEvent.is.finish)).toEqual([
        {
          type: "finish",
          reason: { normalized: "tool-calls", raw: undefined },
          providerMetadata: { "openai-compatible": { responseId: "resp_1", serviceTier: undefined } },
        },
      ])
    }),
  )

  it.effect("recovers pending calls without reconciling terminal reasoning", () =>
    Effect.gen(function* () {
      const events = yield* collect(
        {
          type: "response.output_item.added",
          item: { type: "function_call", id: "fc_1", call_id: "call_1", name: "lookup" },
        },
        { type: "response.function_call_arguments.delta", item_id: "fc_1", delta: '{"query":"draft"}' },
        { type: "response.output_item.added", item: { type: "reasoning", id: "rs_1", encrypted_content: null } },
        { type: "response.reasoning_summary_text.delta", item_id: "rs_1", delta: "Thinking" },
        { type: "response.reasoning_summary_part.done", item_id: "rs_1", summary_index: 0 },
        {
          type: "response.completed",
          response: {
            id: "resp_1",
            output: [
              { type: "reasoning", id: "rs_1", encrypted_content: "terminal-state" },
              { type: "function_call", id: "fc_1", call_id: "call_1", name: "lookup", arguments: '{"query":"final"}' },
              { type: "function_call", id: "fc_unseen", call_id: "call_unseen", name: "lookup", arguments: "{}" },
            ],
          },
        },
      )
      expect(events.slice(5, -2)).toEqual([
        {
          type: "tool-input-end",
          id: "call_1",
          name: "lookup",
          providerMetadata: { "openai-compatible": { itemId: "fc_1" } },
        },
        {
          type: "tool-call",
          id: "call_1",
          name: "lookup",
          input: { query: "final" },
          providerExecuted: undefined,
          providerMetadata: { "openai-compatible": { itemId: "fc_1" } },
        },
        { type: "reasoning-end", id: "rs_1:0" },
      ])
    }),
  )

  it.effect("keeps text and reasoning identities separate even with empty item ids", () =>
    Effect.gen(function* () {
      const events = yield* collect(
        { type: "response.output_item.added", item: { type: "reasoning", id: "" } },
        { type: "response.output_item.added", item: { type: "message", id: "" } },
        { type: "response.output_item.added", item: { type: "reasoning", id: "" } },
        { type: "response.reasoning_summary_text.delta", item_id: "", delta: "Thinking" },
        { type: "response.output_text.delta", item_id: "", delta: "Answer" },
        { type: "response.output_item.done", item: { type: "reasoning", id: "", encrypted_content: "state" } },
        { type: "response.output_item.done", item: { type: "message", id: "" } },
        completed,
      )
      expect(events.filter(LLMEvent.is.reasoningDelta).map((event) => event.text)).toEqual(["Thinking"])
      expect(events.filter(LLMEvent.is.textDelta).map((event) => event.text)).toEqual(["Answer"])
      expect(events.filter(LLMEvent.is.reasoningEnd)).toEqual([
        {
          type: "reasoning-end",
          id: ":0",
          providerMetadata: { "openai-compatible": { itemId: "", reasoningEncryptedContent: "state" } },
        },
      ])
    }),
  )

  it.effect("does not recover a completed tool from a tracked message with the same id", () =>
    Effect.gen(function* () {
      const events = yield* collect(
        { type: "response.output_item.added", item: { type: "message", id: "item_1" } },
        { type: "response.output_text.delta", item_id: "item_1", delta: "Answer" },
        {
          type: "response.completed",
          response: {
            id: "resp_1",
            output: [{ type: "function_call", id: "item_1", call_id: "call_1", name: "lookup", arguments: "{}" }],
          },
        },
      )
      expect(events.filter(LLMEvent.is.toolCall)).toEqual([])
      expect(events.filter(LLMEvent.is.finish).map((event) => event.reason.normalized)).toEqual(["stop"])
    }),
  )

  it.effect("flushes pending calls and open text when completed output is absent", () =>
    Effect.gen(function* () {
      const events = yield* collect(
        { type: "response.output_item.added", item: { type: "message", id: "msg_1", phase: "final_answer" } },
        { type: "response.output_text.delta", item_id: "msg_1", delta: "Answer" },
        {
          type: "response.output_item.added",
          item: { type: "function_call", id: "fc_1", call_id: "call_1", name: "lookup", arguments: "{}" },
        },
        completed,
      )
      // Generic terminal closure does not repeat the message's phase metadata.
      const providerMetadata = { "openai-compatible": { itemId: "fc_1" } }
      expect(events.slice(4, -2)).toEqual([
        { type: "tool-input-end", id: "call_1", name: "lookup", providerMetadata },
        { type: "tool-call", id: "call_1", name: "lookup", input: {}, providerMetadata },
        { type: "text-end", id: "msg_1" },
      ])
    }),
  )

  it.effect("does not reconcile pending calls or terminal reasoning metadata on incomplete responses", () =>
    Effect.gen(function* () {
      const events = yield* collect(
        { type: "response.output_item.added", item: { type: "reasoning", id: "rs_1", encrypted_content: null } },
        { type: "response.reasoning_summary_text.delta", item_id: "rs_1", delta: "Partial" },
        {
          type: "response.output_item.added",
          item: { type: "function_call", id: "fc_1", call_id: "call_1", name: "lookup" },
        },
        { type: "response.function_call_arguments.delta", item_id: "fc_1", delta: '{"query":' },
        {
          type: "response.incomplete",
          response: {
            id: "resp_1",
            incomplete_details: { reason: "max_output_tokens" },
            output: [
              { type: "reasoning", id: "rs_1", encrypted_content: "not-reconciled" },
              {
                type: "function_call",
                id: "fc_1",
                call_id: "call_1",
                name: "lookup",
                arguments: '{"query":"not-reconciled"}',
              },
            ],
          },
        },
      )
      expect(events.filter(LLMEvent.is.toolInputEnd)).toEqual([])
      expect(events.filter(LLMEvent.is.toolCall)).toEqual([])
      expect(events.filter(LLMEvent.is.reasoningEnd)).toEqual([{ type: "reasoning-end", id: "rs_1:0" }])
      expect(events.filter(LLMEvent.is.finish)).toEqual([
        {
          type: "finish",
          reason: { normalized: "length", raw: "max_output_tokens" },
          providerMetadata: { "openai-compatible": { responseId: "resp_1", serviceTier: undefined } },
        },
      ])
    }),
  )
})

import { describe, expect } from "bun:test"
import { Effect } from "effect"
import { LLM, LLMEvent, Message } from "../../src/index.js"
import { OpenAI } from "../../src/providers.js"
import { configure } from "../../src/providers/openai-compatible-responses.js"
import { compileRequest, LLMClient } from "../../src/route/client.js"
import { it } from "../lib/effect.js"
import { fixedResponse } from "../lib/http.js"
import { sseEvents } from "../lib/sse.js"

for (const model of [
  OpenAI.configure({ apiKey: "test-key" }).responses("example-model"),
  configure({ apiKey: "test-key", baseURL: "https://responses.example.test/v1" }).model("example-model"),
]) {
  describe(`${model.route.protocol} message replay`, () => {
    const key = model.route.providerMetadataKey ?? "openresponses"

    it.effect("marks assistant text completed regardless of stored status", () =>
      Effect.gen(function* () {
        const prepared = yield* compileRequest(
          LLM.request({
            model,
            messages: [
              ...[undefined, "in_progress", "incomplete", "completed"].map((status, index) =>
                Message.make({
                  role: "assistant",
                  providerMetadata: { [key]: { status } },
                  content: [
                    {
                      type: "text",
                      text: `Saved ${index}`,
                      providerMetadata: { [key]: { itemId: `msg_${index}`, phase: "commentary", status } },
                    },
                    {
                      type: "text",
                      text: `Final ${index}`,
                      providerMetadata: { [key]: { itemId: `msg_final_${index}`, phase: "final_answer", status } },
                    },
                  ],
                }),
              ),
              Message.make({
                role: "user",
                content: [{ type: "text", text: "Continue" }],
                providerMetadata: { [key]: { status: "incomplete" } },
              }),
            ],
          }),
        )
        expect(prepared.body.input).toEqual([
          ...[0, 1, 2, 3].flatMap((index) => [
            {
              type: "message",
              role: "assistant",
              id: `msg_${index}`,
              phase: "commentary",
              status: "completed",
              content: [{ type: "output_text", text: `Saved ${index}` }],
            },
            {
              type: "message",
              role: "assistant",
              id: `msg_final_${index}`,
              phase: "final_answer",
              status: "completed",
              content: [{ type: "output_text", text: `Final ${index}` }],
            },
          ]),
          { type: "message", role: "user", status: "incomplete", content: [{ type: "input_text", text: "Continue" }] },
        ])
      }),
    )

    it.effect("replays truncated text as completed while retaining the response finish reason", () =>
      Effect.gen(function* () {
        const response = yield* LLMClient.generate(LLM.request({ model, prompt: "Respond" })).pipe(
          Effect.provide(
            fixedResponse(
              sseEvents(
                {
                  type: "response.output_item.added",
                  item: { type: "message", id: "msg_partial", status: "in_progress" },
                },
                { type: "response.output_text.delta", item_id: "msg_partial", delta: "The next step is" },
                {
                  type: "response.output_item.done",
                  item: {
                    type: "message",
                    id: "msg_partial",
                    status: "incomplete",
                    content: [{ type: "output_text", text: "The next step is" }],
                  },
                },
                {
                  type: "response.incomplete",
                  response: { status: "incomplete", incomplete_details: { reason: "max_output_tokens" } },
                },
              ),
            ),
          ),
        )
        expect(response.finishReason.normalized).toBe("length")
        expect(response.events.filter(LLMEvent.is.textEnd)).toHaveLength(1)
        const prepared = yield* compileRequest(
          LLM.request({ model, messages: [response.message, Message.user("Continue")] }),
        )
        expect(prepared.body.input).toEqual([
          {
            type: "message",
            role: "assistant",
            id: "msg_partial",
            status: "completed",
            content: [{ type: "output_text", text: "The next step is" }],
          },
          { type: "message", role: "user", content: [{ type: "input_text", text: "Continue" }] },
        ])
      }),
    )
  })
}

import { describe, expect } from "bun:test"
import { Effect } from "effect"
import { LLM, LLMEvent, LLMResponse, LanguageModel } from "../../src/index.js"
import * as OpenAICompatible from "../../src/providers/openai-compatible.js"
import * as OpenRouter from "../../src/providers/openrouter.js"
import { LLMClient } from "../../src/route.js"
import { compileRequest } from "../../src/route/client.js"
import { recordedTests } from "../recorded-test.js"
import { expectWeatherToolLoop, goldenWeatherToolLoopRequest, runWeatherToolLoop } from "../recorded-scenarios.js"

const cases = [
  {
    name: "OpenRouter",
    model: LanguageModel.update(
      OpenRouter.configure({
        apiKey: process.env.OPENROUTER_API_KEY ?? "fixture",
        providerOptions: { reasoning: { max_tokens: 1024 } },
      }).model("anthropic/claude-sonnet-4.6"),
      { compatibility: { reasoningField: "reasoning" } },
    ),
    requires: ["OPENROUTER_API_KEY"],
    cassette: "openrouter-reasoning",
    structured: true,
  },
  {
    name: "Vercel AI Gateway",
    model: LanguageModel.update(
      OpenAICompatible.configure({
        provider: "vercel-ai-gateway",
        baseURL: "https://ai-gateway.vercel.sh/v1",
        apiKey: process.env.AI_GATEWAY_API_KEY ?? "fixture",
        http: { body: { reasoning: { enabled: true, max_tokens: 1024 } } },
      }).model("anthropic/claude-sonnet-4.6"),
      { compatibility: { reasoningField: "reasoning" } },
    ),
    requires: ["AI_GATEWAY_API_KEY"],
    cassette: "vercel-ai-gateway-reasoning",
    structured: true,
  },
] as const

for (const item of cases) {
  const recorded = recordedTests({
    prefix: "openai-compatible-chat",
    provider: item.model.provider,
    protocol: "openai-chat",
    requires: item.requires,
    tags: ["reasoning"],
    metadata: { model: item.model.id },
  })

  describe(`${item.name} reasoning recorded`, () => {
    recorded.effect.with(
      "streams scalar reasoning",
      { cassette: item.cassette },
      () =>
        Effect.gen(function* () {
          const response = yield* LLMClient.generate(
            LLM.request({
              model: item.model,
              system: "Think through the arithmetic, then reply with only the final integer.",
              prompt: "What is 173 multiplied by 219?",
              generation: { maxTokens: 1536, temperature: 0 },
            }),
          )

          expect(response.text.replaceAll(",", "").trim()).toBe("37887")
          expect(response.reasoning.length).toBeGreaterThan(0)
          expect(response.events.some(LLMEvent.is.reasoningDelta)).toBe(true)
          const metadata = response.message.content.find((part) => part.type === "reasoning")?.providerMetadata?.[
            item.model.route.providerMetadataKey ?? String(item.model.provider)
          ]
          expect(metadata?.reasoningField).toBe(item.structured ? "reasoning" : "reasoning_content")
          expect(Array.isArray(metadata?.reasoningDetails)).toBe(item.structured)
          if (!item.structured) return
          const details = metadata?.reasoningDetails
          if (!Array.isArray(details)) return
          expect(
            details.some(
              (detail) =>
                typeof detail === "object" &&
                detail !== null &&
                "signature" in detail &&
                typeof detail.signature === "string" &&
                detail.signature.length > 0,
            ),
          ).toBe(true)

          const replay = yield* compileRequest(LLM.request({ model: item.model, messages: [response.message] }))
          expect(replay.body.messages).toMatchObject([
            {
              role: "assistant",
              content:
                item.model.route.id === "openrouter"
                  ? [{ type: "text", text: response.text, cache_control: { type: "ephemeral" } }]
                  : response.text,
              reasoning: response.reasoning,
            },
          ])
          const replayDetails =
            replay.body.messages[0]?.role === "assistant" ? replay.body.messages[0].reasoning_details : undefined
          expect(Array.isArray(replayDetails)).toBe(true)
          if (!Array.isArray(replayDetails)) return
          expect(replayDetails).toEqual(details)
          expect(replayDetails).toHaveLength(1)
          expect(replayDetails[0]).toMatchObject({
            type: "reasoning.text",
            text: response.reasoning,
            signature: expect.any(String),
          })
        }),
      30_000,
    )

    recorded.effect.with(
      "continues signed reasoning through a tool loop",
      { cassette: `${item.cassette}-tool-loop`, tags: ["continuation", "tool", "tool-loop"] },
      () =>
        Effect.gen(function* () {
          const events = yield* runWeatherToolLoop(
            goldenWeatherToolLoopRequest({
              id: `${item.cassette}-tool-loop`,
              model: item.model,
              maxTokens: 1536,
              temperature: false,
            }),
          )

          expectWeatherToolLoop(events)
          expect(
            LLMResponse.text({
              events: events.slice(events.findIndex(LLMEvent.is.stepFinish) + 1),
            }).trim(),
          ).toMatch(/^Paris is sunny\.?$/)
          const details = events
            .filter(LLMEvent.is.reasoningEnd)
            .map(
              (event) =>
                event.providerMetadata?.[item.model.route.providerMetadataKey ?? String(item.model.provider)]
                  ?.reasoningDetails,
            )
            .find(Array.isArray)
          expect(Array.isArray(details)).toBe(item.structured)
          if (!item.structured || !Array.isArray(details)) return
          expect(
            details.some(
              (detail) =>
                typeof detail === "object" &&
                detail !== null &&
                "signature" in detail &&
                typeof detail.signature === "string" &&
                detail.signature.length > 0,
            ),
          ).toBe(true)
        }),
      60_000,
    )
  })
}

