                    {
                      type: "file",
                      uri: `data:application/pdf;base64,${PDF}`,
                      mime: "application/pdf",
                      name: target.filename,
                    },
                  ],
                }),
              ],
              tools: [readPdf],
            }),
          ),
        )
      }),
    )
