                .flatMap((part) => part.providerMetadata?.venice?.reasoningDetails ?? []),
            ),
          ).toEqual(
            expect.arrayContaining([
              expect.objectContaining({ type: "reasoning.encrypted", data: expect.any(String) }),
            ]),
          )
        }
      }),
