import { dynamicResponse, fixedResponse } from "../lib/http.js"

describe("Z.ai Images", () => {
  it.effect("generates through the Z.ai Images API", () =>
    Effect.gen(function* () {
      const response = yield* Image.generate({
        model: ZAI.configure({
          apiKey: "test",
          baseURL: "https://api.z.ai.test/api/paas/v4",
          headers: { "x-default": "yes" },
          http: { body: { configured: true, quality: "configured" }, query: { trace: "default" } },
        }).image("glm-image"),
        prompt: "A red circle on a white background",
        providerOptions: {
          quality: "hd",
          userID: "alias-user",
          user_id: "raw-user",
          future_option: true,
        },
        http: {
          headers: { "x-request": "yes" },
          query: { trace: "request" },
          body: { quality: "final", user_id: "final-user" },
        },
      })

      expect(response.images).toHaveLength(1)
      expect(response.image.mediaType).toBe("application/octet-stream")
      // Z.ai documents that output URLs expire 30 days after generation; the test clock starts at 0.
      expect(response.image.source).toEqual({
        type: "url",
        url: "https://cdn.z.ai/generated.png",
        expiresAt: 30 * 24 * 60 * 60 * 1000,
      })
      expect(response.notices).toEqual([
        {
          type: "moderated",
          message: "Z.ai Images applied a content filter for future-role at level 4.5",
          providerMetadata: { zai: { role: "future-role", level: 4.5 } },
        },
      ])
      expect(response.providerMetadata).toEqual({
        zai: {
          created: 1_760_335_349,
          id: "generation-1",
          requestID: "request-1",
          contentFilter: [{ role: "future-role", level: 4.5 }],
        },
      })
    }).pipe(
      Effect.provide(
        ImageClient.layer.pipe(
          Layer.provide(
            dynamicResponse((input) =>
              Effect.gen(function* () {
                const request = yield* HttpClientRequest.toWeb(input.request).pipe(Effect.orDie)
                expect(request.url).toBe("https://api.z.ai.test/api/paas/v4/images/generations?trace=request")
                expect(request.headers.get("authorization")).toBe("Bearer test")
                expect(request.headers.get("x-default")).toBe("yes")
                expect(request.headers.get("x-request")).toBe("yes")
                expect(JSON.parse(input.text)).toEqual({
                  model: "glm-image",
                  prompt: "A red circle on a white background",
                  quality: "final",
                  user_id: "final-user",
                  future_option: true,
                  configured: true,
                })
                return input.respond(
                  JSON.stringify({
                    created: 1_760_335_349,
                    id: "generation-1",
                    request_id: "request-1",
                    data: [{ url: "https://cdn.z.ai/generated.png" }],
                    content_filter: [{ role: "future-role", level: 4.5 }],
                  }),
                  { headers: { "content-type": "application/json" } },
                )
              }),
            ),
          ),
        ),
      ),
    ),
  )

  it.effect("sanitizes unpaired surrogates in outbound image requests", () =>
    Image.generate({
      model: ZAI.configure({ apiKey: "test", http: { body: { metadata: { source: "default\uDC00" } } } }).image(
        "model",
      ),
      prompt: "A red circle \uD800 on a white background \u{1F600}",
    }).pipe(
      Effect.provide(
        ImageClient.layer.pipe(
          Layer.provide(
            dynamicResponse((input) => {
              expect(JSON.parse(input.text)).toMatchObject({
                prompt: "A red circle \uFFFD on a white background \u{1F600}",
                metadata: { source: "default\uFFFD" },
              })
              return Effect.succeed(
                input.respond(JSON.stringify({ data: [{ url: "https://example.test/image.jpg" }] }), {
                  headers: { "content-type": "application/json" },
                }),
              )
            }),
          ),
        ),
      ),
    ),
  )

  it.effect("lets raw native options override aliases", () =>
    Image.generate({
      model: ZAI.configure({ apiKey: "test" }).image("model"),
      prompt: "test",
      providerOptions: { quality: "future-quality", userID: "x", user_id: "raw-user" },
    }).pipe(
      Effect.provide(
        ImageClient.layer.pipe(
          Layer.provide(
            dynamicResponse((input) => {
              expect(JSON.parse(input.text)).toMatchObject({ quality: "future-quality", user_id: "raw-user" })
              return Effect.succeed(
                input.respond(JSON.stringify({ data: [{ url: "https://example.test/image.jpg" }] }), {
                  headers: { "content-type": "application/json" },
                }),
              )
            }),
          ),
        ),
      ),
    ),
  )

  it.effect("rejects invalid response structures", () =>
    Effect.gen(function* () {
      const model = ZAI.configure({ apiKey: "test" }).image("model")
      const payloads = [
        {},
        { data: [] },
        { data: [{ b64_json: "image" }] },
        { data: [{ url: 1 }] },
        { data: [{ url: "https://example.test/image.jpg" }], content_filter: [{ role: 1, level: "high" }] },
      ]

      yield* Effect.forEach(payloads, (payload) =>
        Image.generate({ model, prompt: "test" }).pipe(
          Effect.provide(
            ImageClient.layer.pipe(
              Layer.provide(
                fixedResponse(JSON.stringify(payload), { headers: { "content-type": "application/json" } }),
              ),
            ),
          ),
          Effect.flip,
          Effect.tap((error) => Effect.sync(() => expect(error.reason._tag).toBe("InvalidProviderOutput"))),
        ),
      )
    }),
  )
})

import { expect } from "bun:test"
import { Effect } from "effect"
import { LLM, LLMEvent, LLMRequest, Message, ToolDefinition, type LLMResponse } from "../../src/index.js"
import { ZAI } from "../../src/providers.js"
import { LLMClient } from "../../src/route.js"
import { compileRequest } from "../../src/route/client.js"
import { recordedTests } from "../recorded-test.js"

const apiKey = process.env.ZAI_API_KEY ?? "fixture"
const recorded = recordedTests({ prefix: "zai-chat", provider: "zai", protocol: "zai-chat", requires: ["ZAI_API_KEY"] })
const weather = ToolDefinition.make({
  name: "get_weather",
  description: "Get the current weather in a city",
  inputSchema: {
    type: "object",
    properties: { city: { type: "string", enum: ["Paris"] } },
    required: ["city"],
    additionalProperties: false,
  },
})

for (const effort of [undefined, "low", "high", "max"] as const) {
  recorded.effect.with(
    `GLM 5.3 streams ${effort ?? "default"} effort`,
    { tags: ["text", "reasoning", "usage"] },
    () =>
      Effect.gen(function* () {
        const request = LLM.request({
          model: ZAI.configure({ apiKey, providerOptions: { reasoningEffort: effort } }).model("glm-5.3"),
          prompt: "What is 173 multiplied by 219? Reply with only the final integer.",
          generation: { maxTokens: 4096 },
        })
        const compiled = yield* compileRequest(request)
        expect(compiled.body.thinking).toBeUndefined()
        expect(compiled.body.reasoning_effort).toBe(effort)
        const response = yield* LLMClient.generate(request)
        expect(response.text.replaceAll(",", "")).toContain("37887")
        expect(response.reasoning.length).toBeGreaterThan(0)
        expect(response.finishReason.normalized).toBe("stop")
        expectUsage(response)
      }),
    120_000,
  )
}

recorded.effect.with(
  "GLM 5.3 preserves reasoning through a tool loop and follow-up",
  { tags: ["tool", "tool-loop", "reasoning", "continuation"] },
  () =>
    Effect.gen(function* () {
      const request = LLM.request({
        model: ZAI.configure({
          apiKey,
          providerOptions: { reasoningEffort: "high", thinking: { type: "enabled", clear_thinking: false } },
        }).chat("glm-5.3"),
        prompt:
          "We have a budget of 38000 dollars for 219 trips costing 173 dollars each. Calculate whether that is affordable. If it is, use get_weather to look up the current weather in Paris. After receiving the result, report the weather in one short sentence.",
        tools: [weather],
        generation: { maxTokens: 4096 },
      })
      const first = yield* LLMClient.generate(request)
      expect(first.toolCalls).toMatchObject([{ name: "get_weather", input: { city: "Paris" } }])
      expect(first.finishReason.normalized).toBe("tool-calls")
      expect(first.reasoning.length).toBeGreaterThan(0)
      expect(first.events.some(LLMEvent.is.toolInputDelta)).toBe(true)
      expectUsage(first)
      const continuation = LLMRequest.update(request, {
        messages: [
          ...request.messages,
          first.message,
          ...first.toolCalls.map((call) =>
            Message.tool({ id: call.id, name: call.name, result: { condition: "sunny", temperature: "18C" } }),
          ),
        ],
      })
      const compiled = yield* compileRequest(continuation)
      expect(compiled.body.messages).toEqual(
        expect.arrayContaining([expect.objectContaining({ role: "assistant", reasoning_content: first.reasoning })]),
      )
      const second = yield* LLMClient.generate(continuation)
      expect(second.text.toLowerCase()).toContain("sunny")
      expect(second.toolCalls).toHaveLength(0)
      expect(second.finishReason.normalized).toBe("stop")
      expectUsage(second)
      const followUp = LLMRequest.update(continuation, {
        messages: [
          ...continuation.messages,
          second.message,
          Message.user("What temperature did the tool report? Reply with only the temperature."),
        ],
      })
      const replay = yield* compileRequest(followUp)
      expect(replay.body.messages).toEqual(
        expect.arrayContaining(
          [first, second].map((response) =>
            expect.objectContaining({ role: "assistant", reasoning_content: response.reasoning }),
          ),
        ),
      )
      const third = yield* LLMClient.generate(followUp)
      expect(third.text).toContain("18")
      expect(third.toolCalls).toHaveLength(0)
      expect(third.finishReason.normalized).toBe("stop")
      expectUsage(third)
    }),
  180_000,
)

function expectUsage(response: LLMResponse) {
  expect(response.usage?.inputTokens).toBeGreaterThan(0)
  expect(response.usage?.outputTokens).toBeGreaterThan(0)
  expect(response.events.filter(LLMEvent.is.finish)).toHaveLength(1)
}

