import { describe, expect } from "bun:test"
import { Effect, Layer, Stream } from "effect"
import { Base64 } from "effect/encoding"
import { Speech, SpeechClient, SpeechEvent } from "../src/index.js"
import { Cartesia, Deepgram, ElevenLabs, Google, OpenAI } from "../src/providers.js"
import { it } from "./lib/effect.js"
import { dynamicResponse } from "./lib/http.js"
import { sseEvents } from "./lib/sse.js"

// Recorded tests in test/provider cover lowering and decoding; these cover what recordings cannot.

const layer = (handler: Parameters<typeof dynamicResponse>[0]) =>
  SpeechClient.layer.pipe(Layer.provideMerge(dynamicResponse(handler)))

const respond = (body: string | ReadableStream<Uint8Array>, contentType: string) =>
  layer((input) => Effect.succeed(input.respond(body, { headers: { "content-type": contentType } })))

const collect = <E, R>(stream: Stream.Stream<SpeechEvent, E, R>) =>
  stream.pipe(
    Stream.runCollect,
    Effect.map((events) => Array.from(events)),
  )

const openai = OpenAI.configure({ apiKey: "test", baseURL: "https://openai.test/v1" }).speech("gpt-4o-mini-tts")
const elevenlabs = ElevenLabs.configure({ apiKey: "test", baseURL: "https://elevenlabs.test" }).speech(
  "eleven_flash_v2_5",
)
const cartesia = Cartesia.configure({ apiKey: "test", baseURL: "https://cartesia.test" }).speech("sonic-3")
const google = Google.configure({ apiKey: "test", baseURL: "https://google.test/v1beta" }).speech(
  "gemini-2.5-flash-preview-tts",
)
const google38 = Google.configure({ apiKey: "test", baseURL: "https://google.test/v1beta" }).speech(
  "gemini-3.8-flash-tts",
)
const google38Lite = Google.configure({ apiKey: "test", baseURL: "https://google.test/v1beta" }).speech(
  "gemini-3.8-flash-lite-tts",
)
const deepgram = Deepgram.configure({ apiKey: "test", baseURL: "https://deepgram.test" }).speech("aura-2-thalia-en")
const voice = "JBFqnCBsd6RMkjVDRZzb"

describe("Speech", () => {
  it.effect("preserves Google's WAV output instead of describing it as raw PCM", () =>
    Effect.gen(function* () {
      const bytes = new TextEncoder().encode("RIFF....WAVEfmt ")
      const response = yield* Speech.generate({ model: google38, text: "Hi" }).pipe(
        Effect.provide(
          respond(
            JSON.stringify({
              candidates: [
                {
                  content: { parts: [{ inlineData: { mimeType: "audio/wav", data: Base64.encode(bytes) } }] },
                  finishReason: "STOP",
                },
              ],
            }),
            "application/json",
          ),
        ),
      )
      expect(response.audio.mediaType).toBe("audio/wav")
      expect(response.audio.info?.format).toBe("wav")
      expect(response.audio.info?.encoding).toBeUndefined()
      expect(yield* response.audio.bytes()).toEqual(bytes)
    }),
  )

  it.effect("describes OpenAI audio in the format the request body actually asked for", () =>
    Effect.gen(function* () {
      const [pcm, wav] = yield* Effect.all([
        Speech.generate({ model: openai, text: "Hi", format: "mp3", providerOptions: { response_format: "pcm" } }),
        Speech.generate({ model: openai, text: "Hi", http: { body: { response_format: "wav" } } }),
      ]).pipe(Effect.provide(respond("\u0001\u0002", "application/octet-stream")))
      expect(pcm.audio.mediaType).toBe("audio/pcm")
      expect(pcm.audio.info).toEqual({ format: "pcm", encoding: "pcm_s16le", sampleRate: 24000, channels: 1 })
      expect(wav.audio.mediaType).toBe("audio/wav")
      expect(wav.audio.info?.format).toBe("wav")
    }),
  )

  it.effect("describes Deepgram raw encodings in their default WAV container", () =>
    Effect.gen(function* () {
      const response = yield* Speech.generate({ model: deepgram, text: "Hi", providerOptions: { encoding: "mulaw" } })
      expect(response.audio.mediaType).toBe("audio/wav")
      expect(response.audio.info?.format).toBe("wav")
    }).pipe(Effect.provide(respond("RIFF....WAVEfmt ", "audio/wav"))),
  )

  it.effect("always gives headerless Deepgram PCM a sample rate", () =>
    Effect.gen(function* () {
      const [requested, defaulted] = yield* Effect.all([
        Speech.generate({
          model: deepgram,
          text: "Hi",
          providerOptions: { encoding: "mulaw", container: "none", sampleRate: 16000 },
        }),
        Speech.generate({ model: deepgram, text: "Hi", providerOptions: { encoding: "alaw", container: "none" } }),
      ]).pipe(Effect.provide(respond("\u0001\u0002", "audio/basic")))
      expect(requested.audio.info).toEqual({ format: "pcm", encoding: "pcm_mulaw", sampleRate: 16000, channels: 1 })
      expect(defaulted.audio.info).toEqual({ format: "pcm", encoding: "pcm_alaw", sampleRate: 8000, channels: 1 })
    }),
  )

  it.effect("rejects raw PCM for Gemini 3.8 unary requests before sending", () =>
    Effect.gen(function* () {
      const errors = yield* Effect.all(
        [google38, google38Lite].map((model) =>
          Speech.generate({ model, text: "Hi", format: "pcm" }).pipe(Effect.flip),
        ),
      ).pipe(Effect.provide(layer(() => Effect.die("An unsupported request reached the network"))))
      expect(errors.map((error) => error.reason._tag)).toEqual(["UnsupportedOperation", "UnsupportedOperation"])
    }),
  )

  it.effect("rejects what a provider cannot produce before sending anything", () =>
    Effect.gen(function* () {
      const errors = yield* Effect.all(
        [
          Speech.generate({ model: openai, text: "Hi", timestamps: true }),
          Speech.generate({ model: openai, text: "Hi", format: "ogg" }),
          Speech.generate({ model: google, text: "Hi", format: "mp3" }),
          Speech.generate({ model: google, text: "Hi", instructions: "Warm." }),
          collect(Speech.stream({ model: elevenlabs, text: "Hi", voice, format: "wav" })),
          collect(Speech.stream({ model: cartesia, text: "Hi", voice, format: "mp3" })),
          Speech.generate({ model: deepgram, text: "Hi", voice: "thalia" }),
        ].map((effect) => Effect.flip(effect)),
      )
      expect(errors.map((error) => [error.reason._tag, "operation" in error.reason && error.reason.operation])).toEqual(
        [
          ["UnsupportedOperation", "media.timestamps"],
          ["UnsupportedOperation", "media.format"],
          ["UnsupportedOperation", "media.format"],
          ["UnsupportedOperation", "media.instructions"],
          ["UnsupportedOperation", "media.format"],
          ["UnsupportedOperation", "media.format"],
          ["UnsupportedOperation", "media.voice"],
        ],
      )
      expect(errors[1].reason).toMatchObject({ provider: "openai", route: "openai-speech" })
      expect(errors[2].reason).toMatchObject({ provider: "google", route: "google-speech" })
    }).pipe(Effect.provide(layer(() => Effect.die("an unsupported request reached the network")))),
  )

  it.effect("treats timestamps: false as not asking for timestamps on routes that cannot return them", () =>
    Effect.gen(function* () {
      const bytes = Uint8Array.from([1, 2, 3])
      const gemini = JSON.stringify({
        candidates: [
          {
            content: { parts: [{ inlineData: { mimeType: "audio/L16;codec=pcm;rate=24000", data: "AQID" } }] },
            finishReason: "STOP",
          },
        ],
      })
      const responses = yield* Effect.all([
        Speech.generate({ model: openai, text: "Hi", timestamps: false }).pipe(
          Effect.provide(respond(new Blob([bytes]).stream(), "audio/mpeg")),
        ),
        Speech.generate({ model: google, text: "Hi", timestamps: false }).pipe(
          Effect.provide(respond(gemini, "application/json")),
        ),
        Speech.generate({ model: deepgram, text: "Hi", timestamps: false }).pipe(
          Effect.provide(respond(new Blob([bytes]).stream(), "audio/mpeg")),
        ),
      ])
      for (const response of responses) expect(yield* response.audio.bytes()).toEqual(bytes)

      const errors = yield* Effect.all(
        [openai, google, deepgram].map((model) =>
          Speech.generate({ model, text: "Hi", timestamps: true }).pipe(Effect.flip),
        ),
      ).pipe(Effect.provide(layer(() => Effect.die("an unsupported request reached the network"))))
      expect(errors.map((error) => [error.reason._tag, "operation" in error.reason && error.reason.operation])).toEqual(
        [
          ["UnsupportedOperation", "media.timestamps"],
          ["UnsupportedOperation", "media.timestamps"],
          ["UnsupportedOperation", "media.timestamps"],
        ],
      )
    }),
  )

  it.effect("classifies stream failures and keeps the provider payload and HTTP context", () =>
    Effect.gen(function* () {
      const badFrame = JSON.stringify({ type: "speech.audio.delta", audio: "not base64!" })
      const cartesiaError = { type: "error", done: true, status_code: 400, title: "Invalid model", message: "Nope" }
      const blocked = JSON.stringify({ promptFeedback: { blockReason: "PROHIBITED_CONTENT" } })
      const [truncated, invalid, provider, policy] = yield* Effect.all(
        [
          collect(Speech.stream({ model: openai, text: "Hi" })).pipe(
            Effect.provide(respond(sseEvents({ type: "speech.audio.delta", audio: "AQI=" }), "text/event-stream")),
          ),
          collect(Speech.stream({ model: openai, text: "Hi" })).pipe(
            Effect.provide(respond(sseEvents(badFrame), "text/event-stream")),
          ),
          collect(Speech.stream({ model: cartesia, text: "Hi", voice })).pipe(
            Effect.provide(respond(sseEvents(cartesiaError), "text/event-stream")),
          ),
          Speech.generate({ model: google, text: "Hi" }).pipe(Effect.provide(respond(blocked, "application/json"))),
        ].map((effect) => Effect.flip(effect)),
      )

      expect(truncated.reason).toMatchObject({ _tag: "InvalidProviderOutput", classification: "incomplete-stream" })
      expect(truncated.reason.http?.status).toBe(200)
      expect(invalid.reason).toMatchObject({ _tag: "InvalidProviderOutput", body: badFrame })
      expect(invalid.reason.http?.status).toBe(200)
      expect(provider.reason).toMatchObject({ _tag: "InvalidRequest", body: JSON.stringify(cartesiaError) })
      expect(provider.message).toBe("Cartesia stream failed (Invalid model): Nope")
      expect(policy.reason).toMatchObject({ _tag: "ContentPolicy", body: blocked })
    }),
  )

  it.effect("surfaces Gemini speech that ended without STOP instead of returning it as complete", () =>
    Effect.gen(function* () {
      const document = (finishReason?: string) =>
        JSON.stringify({
          candidates: [
            {
              content: { parts: [{ inlineData: { mimeType: "audio/L16;codec=pcm;rate=24000", data: "AQI=" } }] },
              finishReason,
            },
          ],
        })
      const withheld = JSON.stringify({ candidates: [{ finishReason: "SAFETY" }] })
      const generate = (body: string) =>
        Speech.generate({ model: google, text: "Hi" }).pipe(Effect.provide(respond(body, "application/json")))

      const truncated = yield* generate(document()).pipe(Effect.flip)
      const partial = yield* generate(document("MAX_TOKENS"))
      const policy = yield* generate(withheld).pipe(Effect.flip)

      expect(truncated.reason).toMatchObject({ _tag: "InvalidProviderOutput", classification: "incomplete-stream" })
      expect(yield* partial.audio.bytes()).toEqual(Uint8Array.from([1, 2]))
      expect(partial.notices).toEqual([
        {
          type: "other",
          message: "Google Speech finished with MAX_TOKENS",
          providerMetadata: { google: { finishReason: "MAX_TOKENS" } },
        },
      ])
      expect(policy.reason).toMatchObject({ _tag: "ContentPolicy", body: withheld })
    }),
  )

  it.effect("parses ElevenLabs timestamped records split across network chunks", () =>
    Effect.gen(function* () {
      const record = (bytes: ReadonlyArray<number>, character: string, start: number) =>
        JSON.stringify({
          audio_base64: Base64.encode(Uint8Array.from(bytes)),
          alignment: {
            characters: [character],
            character_start_times_seconds: [start],
            character_end_times_seconds: [start + 0.1],
          },
        })
      const first = record([1, 2], "H", 0)
      const second = record([3], "i", 0.1)
      const encoder = new TextEncoder()
      const body = new ReadableStream<Uint8Array>({
        start(controller) {
          controller.enqueue(encoder.encode(`${first}\n${second.slice(0, 10)}`))
          controller.enqueue(encoder.encode(`${second.slice(10)}\n`))
          controller.close()
        },
      })

      const events = yield* collect(Speech.stream({ model: elevenlabs, text: "Hi", voice, timestamps: true })).pipe(
        Effect.provide(respond(body, "application/json")),
      )

      expect(events.map((event) => event.type)).toEqual([
        "audio-delta",
        "timestamps",
        "audio-delta",
        "timestamps",
        "finish",
      ])
      expect(events.filter(SpeechEvent.is.timestamps).flatMap((event) => event.items)).toEqual([
        { text: "H", startSeconds: 0, endSeconds: 0.1 },
        { text: "i", startSeconds: 0.1, endSeconds: 0.2 },
      ])
      const finish = events.find(SpeechEvent.is.finish)
      expect(yield* finish!.audio.bytes()).toEqual(Uint8Array.from([1, 2, 3]))
    }),
  )
})

import { describe, expect } from "bun:test"
import {
  AIError,
  CompactionPart,
  CompactionResponse,
  CompactionCheckpointResponse,
  LanguageModel,
  LLM,
  LLMClient,
  LLMEvent,
  LLMRequest,
  Message,
  ProviderID,
  RateLimitError,
} from "../src/index.js"
import { OpenAI } from "../src/providers.js"
import { OpenAIChat } from "../src/protocols/openai-chat.js"
import { TestLLM } from "../src/testing.js"
import { Effect, Fiber, Latch, Stream } from "effect"
import { testEffect } from "./lib/effect.js"

const request = LLM.request({
  model: LanguageModel.make({ id: "fictional-model", provider: "fixture", route: OpenAIChat.route }),
  prompt: "Say hello",
})
const legacy = testEffect(TestLLM.layer())
const it = testEffect(TestLLM.testLayer())

describe("TestLLM legacy client", () => {
  legacy.effect("does not observe requests or consume responses until execution", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Service
      yield* llm.push(TestLLM.text("first", "first"), TestLLM.text("second", "second"))

      llm.client.stream(request)
      llm.client.generate(request)
      expect(llm.requests).toEqual([])

      expect((yield* llm.client.generate(request)).text).toBe("first")
      expect((yield* llm.client.generate(request)).text).toBe("second")
      expect(llm.requests).toEqual([request, request])
    }),
  )

  legacy.effect("assigns and records a fresh response for each execution", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Service
      yield* llm.push(
        TestLLM.text("first", "first"),
        TestLLM.text("second", "second"),
        TestLLM.text("third", "third"),
        TestLLM.text("fourth", "fourth"),
      )
      const stream = llm.client.stream(request)
      const generate = llm.client.generate(request)

      expect(yield* Stream.runCollect(stream)).toEqual(TestLLM.text("first", "first"))
      expect(yield* Stream.runCollect(stream)).toEqual(TestLLM.text("second", "second"))
      expect((yield* generate).text).toBe("third")
      expect((yield* generate).text).toBe("fourth")
      expect(llm.requests).toEqual([request, request, request, request])
    }),
  )

  legacy.effect("keeps module-level controls and clientLayer on the same backing state", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Service
      const requests = llm.requests
      yield* TestLLM.push(TestLLM.text("queued", "queued"))
      yield* TestLLM.always(TestLLM.text("fallback", "fallback"))
      expect((yield* LLMClient.generate(request).pipe(Effect.provide(TestLLM.clientLayer))).text).toBe("queued")
      yield* TestLLM.wait(1)
      expect(requests).toEqual([request])
      requests.length = 0
      expect((yield* llm.client.generate(request)).text).toBe("fallback")
      expect(llm.requests).toBe(requests)
      expect(requests).toEqual([request])
    }),
  )
})

describe("TestLLM first-class client", () => {
  it.effect("returns scripted checkpoints only for trigger compaction", () =>
    Effect.gen(function* () {
      const client = yield* TestLLM.Test
      const request = LLM.request({ model: OpenAI.configure().responses("fixture"), prompt: "hello" })
      const checkpoint = new CompactionCheckpointResponse({
        checkpoint: { type: "compaction", provider: ProviderID.make("openai"), encrypted: "opaque" },
        responseID: "resp_fixture",
      })
      const endpoint = new CompactionResponse({ replacement: [] })
      yield* client.push(checkpoint, endpoint, checkpoint, checkpoint)
      const operation = LLMClient.compact(request, { mechanism: "trigger" })
      expect(yield* client.requests()).toEqual([])
      expect(yield* operation).toBe(checkpoint)
      expect(yield* client.compact(request, { mechanism: "trigger" }).pipe(Effect.catchDefect(Effect.succeed))).toBe(
        "TestLLM trigger compaction requires a CompactionCheckpointResponse",
      )
      expect(yield* client.compact(request).pipe(Effect.catchDefect(Effect.succeed))).toBe(
        "TestLLM compaction requires a CompactionResponse",
      )
      expect(yield* client.generate(request).pipe(Effect.catchDefect(Effect.succeed))).toBe(
        "TestLLM generation requires an event response",
      )
    }),
  )

  it.effect("rejects response fixtures for the wrong operation", () =>
    Effect.gen(function* () {
      const client = yield* TestLLM.Test
      const request = LLM.request({ model: OpenAI.configure({ apiKey: "test" }).responses("fixture"), prompt: "hello" })
      yield* client.push(TestLLM.stop(), new CompactionResponse({ replacement: [] }))
      expect(yield* client.compact(request).pipe(Effect.catchDefect(Effect.succeed))).toBe(
        "TestLLM compaction requires a CompactionResponse",
      )
      expect(yield* client.generate(request).pipe(Effect.catchDefect(Effect.succeed))).toBe(
        "TestLLM generation requires an event response",
      )
    }),
  )

  it.effect("scripts replacement windows with the same lazy recording, gates, and fallback controls", () =>
    Effect.gen(function* () {
      const client = yield* TestLLM.Test
      const request = LLM.request({ model: OpenAI.configure({ apiKey: "test" }).responses("fixture"), prompt: "hello" })
      const compacted = new CompactionResponse({
        replacement: [
          Message.user("retained input"),
          Message.assistant(CompactionPart.make({ provider: ProviderID.make("openai"), encrypted: "checkpoint" })),
          Message.user("retained tail"),
        ],
      })
      yield* client.push(compacted, TestLLM.text("continued", "answer"))
      const operation = LLMClient.compact(request)
      expect(yield* client.requests()).toEqual([])
      const gate = yield* client.gate()
      const fiber = yield* operation.pipe(Effect.forkChild({ startImmediately: true }))
      yield* gate.started
      yield* client.wait(1)
      expect(fiber.pollUnsafe()).toBeUndefined()
      yield* gate.release
      expect(yield* Fiber.join(fiber)).toBe(compacted)
      const next = LLMRequest.update(request, { messages: compacted.replacement })
      expect((yield* LLMClient.generate(next)).text).toBe("continued")
      yield* client.serve((observed) => {
        expect(observed).toBe(next)
        return compacted
      })
      expect(yield* LLMClient.compact(next)).toBe(compacted)
      yield* client.always(compacted)
      expect(yield* LLMClient.compact(next)).toBe(compacted)
      expect(yield* client.requests()).toEqual([request, next, next, next])
    }),
  )

  it.effect("provides the same object under normal and test tags with snapshot observations", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      const client = yield* LLMClient.Service
      expect(client).toBe(llm)
      const before = yield* llm.requests()
      yield* llm.push(TestLLM.text("hello", "answer"))
      const generate = client.generate(request)
      client.stream(request)
      expect(yield* llm.requests()).toEqual([])

      expect((yield* generate).text).toBe("hello")
      expect(before).toEqual([])
      expect(yield* llm.requests()).toEqual([request])
      expect(yield* llm.requests()).not.toBe(yield* llm.requests())
    }),
  )

  it.effect("prioritizes queued replies over request-dependent and constant fallbacks", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      const served: LLMRequest[] = []
      yield* llm.always(TestLLM.text("old fallback", "old"))
      yield* llm.push(TestLLM.text("first", "first"), TestLLM.text("second", "second"))
      yield* llm.serve((request) => {
        served.push(request)
        return TestLLM.text(request.promptCacheKey ?? "default", "served")
      })

      expect((yield* LLMClient.generate(request)).text).toBe("first")
      expect((yield* LLMClient.generate(request)).text).toBe("second")
      expect(served).toEqual([])
      const selected = LLMRequest.update(request, { promptCacheKey: "selected" })
      expect((yield* LLMClient.generate(selected)).text).toBe("selected")
      expect((yield* LLMClient.generate(request)).text).toBe("default")
      expect(served).toEqual([selected, request])

      yield* llm.push(TestLLM.text("queued again", "queued"))
      yield* llm.always(TestLLM.text("constant", "constant"))
      expect((yield* LLMClient.generate(request)).text).toBe("queued again")
      expect((yield* LLMClient.generate(request)).text).toBe("constant")
      expect((yield* LLMClient.generate(request)).text).toBe("constant")
      expect(served).toEqual([selected, request])
    }),
  )

  testEffect(
    TestLLM.testLayer({
      transformRequest: (request) => LLMRequest.update(request, { promptCacheKey: "observation" }),
    }),
  ).effect("transforms observations without changing the request passed to the responder", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      yield* llm.serve((input) => {
        expect(input).toBe(request)
        return TestLLM.text("original", "answer")
      })
      const generate = llm.generate(request)
      expect(yield* llm.requests()).toEqual([])
      expect((yield* generate).text).toBe("original")
      expect(yield* llm.requests()).toEqual([LLMRequest.update(request, { promptCacheKey: "observation" })])
    }),
  )

  it.effect("broadcasts request-arrival waits and satisfies waits registered afterward", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      yield* llm.always(TestLLM.stop())
      const first = yield* llm.wait(2).pipe(Effect.forkChild({ startImmediately: true }))
      const second = yield* llm.wait(2).pipe(Effect.forkChild({ startImmediately: true }))
      yield* llm.generate(request)
      expect(first.pollUnsafe()).toBeUndefined()
      expect(second.pollUnsafe()).toBeUndefined()
      yield* llm.generate(request)
      yield* Fiber.join(first)
      yield* Fiber.join(second)
      yield* llm.wait(2)
      expect(yield* llm.requests()).toHaveLength(2)
    }),
  )
  ;(["queued", "served"] as const).forEach((mode) => {
    it.effect(`assigns ${mode} replies before resuming request-arrival continuations`, () =>
      Effect.gen(function* () {
        const llm = yield* TestLLM.Test
        const responses = [TestLLM.text("first", "first"), TestLLM.text("second", "second")]
        yield* mode === "queued" ? llm.push(...responses) : llm.serve(() => responses.shift() ?? [])
        const later = yield* llm
          .wait(1)
          .pipe(Effect.andThen(llm.generate(request)), Effect.forkChild({ startImmediately: true }))

        expect((yield* llm.generate(request)).text).toBe("first")
        expect((yield* Fiber.join(later)).text).toBe("second")
        expect(yield* llm.requests()).toEqual([request, request])
      }),
    )
  })

  it.effect("notifies arrival waiters even when the responder defects", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      const defect = new Error("Broken fixture responder")
      yield* llm.serve(() => {
        throw defect
      })
      const waiter = yield* llm.wait(1).pipe(Effect.forkChild({ startImmediately: true }))
      expect(yield* llm.generate(request).pipe(Effect.catchDefect(Effect.succeed))).toBe(defect)
      yield* Fiber.join(waiter)
    }),
  )

  it.effect("builds independent state even when the same layer is provided concurrently", () => {
    const layer = TestLLM.testLayer()
    const run = Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      expect(yield* llm.requests()).toEqual([])
      yield* llm.push(TestLLM.text("one", "answer"))
      expect((yield* LLMClient.generate(request)).text).toBe("one")
      return yield* llm.requests()
    }).pipe(Effect.provide(layer))
    return Effect.gen(function* () {
      expect(yield* Effect.all([run, run], { concurrency: "unbounded" })).toEqual([[request], [request]])
    })
  })

  it.effect("counts concurrent starts on one gate without serializing their response assignment", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      yield* llm.push(TestLLM.text("first", "first"), TestLLM.text("second", "second"))
      const generate = llm.generate(request)
      const gate = yield* llm.gate()
      const first = yield* generate.pipe(Effect.forkChild({ startImmediately: true }))
      yield* gate.started
      const second = yield* generate.pipe(Effect.forkChild({ startImmediately: true }))
      yield* gate.started
      yield* llm.wait(2)
      expect(first.pollUnsafe()).toBeUndefined()
      expect(second.pollUnsafe()).toBeUndefined()
      yield* gate.release
      expect((yield* Fiber.join(first)).text).toBe("first")
      expect((yield* Fiber.join(second)).text).toBe("second")
    }),
  )

  it.effect("does not clear a replacement gate when the previous gate is released", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      yield* llm.always(TestLLM.stop())
      const previous = yield* llm.gate()
      const first = yield* llm.generate(request).pipe(Effect.forkChild({ startImmediately: true }))
      yield* previous.started
      const next = yield* llm.gate()
      yield* previous.release
      yield* Fiber.join(first)

      const second = yield* llm.generate(request).pipe(Effect.forkChild({ startImmediately: true }))
      yield* next.started
      expect(second.pollUnsafe()).toBeUndefined()
      yield* next.release
      yield* Fiber.join(second)
    }),
  )

  it.effect("releases a gate when its deliberately narrower scope closes", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      yield* llm.always(TestLLM.stop())
      // Only the gate is scoped here; its release must happen before the test ends.
      const run = yield* Effect.scoped(
        Effect.gen(function* () {
          const gate = yield* llm.gate()
          const run = yield* llm.generate(request).pipe(Effect.forkChild({ startImmediately: true }))
          yield* gate.started
          return run
        }),
      )
      yield* Fiber.join(run)
      yield* llm.generate(request)
      expect(yield* llm.requests()).toHaveLength(2)
    }),
  )

  it.effect("keeps an executed response consumed after interruption and permits later requests", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      yield* llm.push(TestLLM.text("interrupted", "first"), TestLLM.text("next", "second"))
      const gate = yield* llm.gate()
      const run = yield* llm.generate(request).pipe(Effect.forkChild({ startImmediately: true }))
      yield* gate.started
      yield* Fiber.interrupt(run)
      yield* gate.release
      expect((yield* llm.generate(request)).text).toBe("next")
      expect(yield* llm.requests()).toHaveLength(2)
    }),
  )

  it.effect("consumes a supplied stream's post-finish tail and runs its finalizer", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      const tail = yield* Latch.make()
      const release = yield* Latch.make()
      const finalized = yield* Latch.make()
      yield* llm.push(
        Stream.unwrap(
          Effect.gen(function* () {
            yield* Effect.addFinalizer(() => finalized.open)
            return Stream.fromIterable(TestLLM.text("complete", "answer")).pipe(
              Stream.concat(Stream.fromEffect(tail.open.pipe(Effect.andThen(release.await))).pipe(Stream.drain)),
            )
          }),
        ),
      )
      const run = yield* llm.generate(request).pipe(Effect.forkChild({ startImmediately: true }))
      yield* tail.await
      expect(run.pollUnsafe()).toBeUndefined()
      yield* release.open
      expect((yield* Fiber.join(run)).text).toBe("complete")
      yield* finalized.await
    }),
  )

  it.effect("preserves irregular events, ordinary EOF, typed failures, and responder defects", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      const events = [LLMEvent.textDelta({ id: "without-start", text: "partial" })]
      yield* llm.push(events, [])
      expect(yield* Stream.runCollect(llm.stream(request))).toEqual(events)
      expect(yield* Stream.runCollect(llm.stream(request))).toEqual([])

      const failure = new AIError({ reason: new RateLimitError({ message: "Try later" }) })
      const observed: LLMEvent[] = []
      yield* llm.serve(() => TestLLM.failAfter(failure, ...events))
      expect(
        yield* llm.stream(request).pipe(
          Stream.runForEach((event) => Effect.sync(() => observed.push(event))),
          Effect.flip,
        ),
      ).toBe(failure)
      expect(observed).toEqual(events)
      expect(yield* llm.generate(request).pipe(Effect.flip)).toBe(failure)

      const defect = new Error("Broken fixture responder")
      yield* llm.serve(() => {
        throw defect
      })
      expect(yield* llm.generate(request).pipe(Effect.catchDefect(Effect.succeed))).toBe(defect)
      yield* llm.push(TestLLM.text("recovered", "answer"))
      expect((yield* llm.generate(request)).text).toBe("recovered")
    }),
  )

  it.effect("defects on unexpected requests instead of waiting for a late script", () =>
    Effect.gen(function* () {
      const llm = yield* TestLLM.Test
      const defect = yield* llm.generate(request).pipe(Effect.catchDefect(Effect.succeed))
      expect(defect).toBeInstanceOf(Error)
      if (!(defect instanceof Error)) return
      expect(defect.message).toBe("TestLLM has no response for request 1")
      expect(yield* llm.requests()).toEqual([request])
      yield* llm.push(TestLLM.stop())
      yield* llm.generate(request)
    }),
  )
})

import { describe, expect, test } from "bun:test"
import { Message, ToolCallPart, ToolResultPart } from "../src/schema/messages.js"
import { normalizeToolHistory } from "../src/tool-history.js"

const toolCall = (id: string, name = id) => ToolCallPart.make({ id, name, input: {} })
const toolResult = (id: string, value: unknown, name = id, resultType?: "text" | "content" | "error") =>
  Message.tool(ToolResultPart.make({ id, name, result: value, resultType }))

describe("tool history normalization", () => {
  test("fills missing local results before the next step", () => {
    const normalized = normalizeToolHistory([
      Message.assistant([toolCall("first"), toolCall("second")]),
      toolResult("first", "done", "wrong", "text"),
      Message.user("Continue."),
      Message.assistant(toolCall("trailing")),
    ])

    expect(normalized.map((message) => message.role)).toEqual([
      "assistant",
      "tool",
      "tool",
      "user",
      "assistant",
      "tool",
    ])
    expect(normalized[1]?.content[0]).toMatchObject({ type: "tool-result", id: "first", name: "first" })
    expect(normalized[2]?.content).toEqual([
      { type: "tool-result", id: "second", name: "second", result: { type: "error", value: "Tool result missing" } },
    ])
    expect(normalized[4]?.content).toEqual([toolCall("trailing")])
    expect(normalized[5]?.content).toEqual([
      {
        type: "tool-result",
        id: "trailing",
        name: "trailing",
        result: { type: "error", value: "Tool result missing" },
      },
    ])
  })

  test("fills missing results for trailing calls without replacing available results", () => {
    const calls = Message.assistant([toolCall("answered"), toolCall("unanswered")])
    const answered = toolResult("answered", "done", "answered", "text")
    const hosted = ToolCallPart.make({ id: "hosted", name: "web_search", input: {}, providerExecuted: true })

    expect(normalizeToolHistory([calls, answered])).toEqual([
      calls,
      answered,
      Message.tool(
        ToolResultPart.make({
          id: "unanswered",
          name: "unanswered",
          result: "Tool result missing",
          resultType: "error",
        }),
      ),
    ])
    expect(normalizeToolHistory([Message.assistant(hosted)])).toEqual([Message.assistant(hosted)])
  })

  test("normalizes empty results without changing whitespace or media", () => {
    const media = { type: "file" as const, uri: "data:image/png;base64,AQID", mime: "image/png" }
    const normalized = normalizeToolHistory([
      Message.assistant([
        toolCall("text"),
        toolCall("content"),
        toolCall("error"),
        toolCall("mixed"),
        toolCall("whitespace"),
      ]),
      toolResult("text", "", "text", "text"),
      toolResult("content", [], "content", "content"),
      toolResult("error", "", "error", "error"),
      toolResult("mixed", [{ type: "text", text: "" }, media], "mixed", "content"),
      toolResult("whitespace", "   ", "whitespace", "text"),
    ])

    expect(normalized.slice(1).map((message) => message.content[0])).toEqual([
      { type: "tool-result", id: "text", name: "text", result: { type: "text", value: "(no tool output)" } },
      { type: "tool-result", id: "content", name: "content", result: { type: "text", value: "(no tool output)" } },
      { type: "tool-result", id: "error", name: "error", result: { type: "error", value: "(no tool output)" } },
      { type: "tool-result", id: "mixed", name: "mixed", result: { type: "content", value: [media] } },
      { type: "tool-result", id: "whitespace", name: "whitespace", result: { type: "text", value: "   " } },
    ])
  })

  test("leaves unmatched and provider-executed history unchanged", () => {
    const hostedCall = ToolCallPart.make({
      id: "hosted",
      name: "web_search",
      input: {},
      providerExecuted: true,
    })
    const hostedResult = ToolResultPart.make({
      id: "hosted",
      name: "web_search",
      result: "",
      resultType: "text",
      providerExecuted: true,
    })
    const hosted = Message.assistant([hostedCall, hostedResult])
    const orphan = toolResult("orphan", "ignored", "orphan", "text")

    expect(normalizeToolHistory([orphan, hosted])).toEqual([orphan, hosted])
  })

  test("uses a matching call as the complete tool identity", () => {
    const normalized = normalizeToolHistory([
      Message.assistant(ToolCallPart.make({ id: "call_1", name: "lookup", input: {} })),
      Message.tool(ToolResultPart.make({ id: "call_1", name: "wrong", namespace: "stale", result: "done" })),
    ])

    expect(normalized[1]?.content[0]).toMatchObject({ name: "lookup", namespace: undefined })
  })

  test("moves system updates after the results of pending calls", () => {
    const calls = Message.assistant([toolCall("first"), toolCall("second")])
    const first = toolResult("first", "one", "first", "text")
    const second = toolResult("second", "two", "second", "text")
    const update = Message.system("First update.")
    const later = Message.system("Second update.")
    const user = Message.user("Continue.")
    const missing = (id: string) =>
      Message.tool(ToolResultPart.make({ id, name: id, result: "Tool result missing", resultType: "error" }))

    expect(normalizeToolHistory([calls, first, update, later, second, user])).toEqual([
      calls,
      first,
      second,
      update,
      later,
      user,
    ])
    expect(normalizeToolHistory([Message.assistant(toolCall("first")), update, user])).toEqual([
      Message.assistant(toolCall("first")),
      missing("first"),
      update,
      user,
    ])
    expect(normalizeToolHistory([Message.assistant(toolCall("first")), update])).toEqual([
      Message.assistant(toolCall("first")),
      missing("first"),
      update,
    ])
  })

  test("moves effort updates after the results of pending calls", () => {
    const call = Message.assistant(toolCall("first"))
    const result = toolResult("first", "one", "first", "text")
    const effort = Message.effort({ effort: "low", previous: "high" })

    expect(normalizeToolHistory([call, effort, result])).toEqual([call, result, effort])
  })

  test("keeps system updates in place when no call is pending", () => {
    const history = [Message.assistant(toolCall("first")), toolResult("first", "one", "first", "text")]
    const update = Message.system("Update.")
    const input = [Message.user("Start."), update, ...history, update, Message.user("Continue.")]

    expect(normalizeToolHistory(input)).toBe(input)
  })
})

import { describe, expect, test } from "bun:test"
import { Content } from "@opencode/schema/tool"
import { Effect, Schema, Stream } from "effect"
import {
  GenerationOptions,
  LLM,
  LLMEvent,
  LLMRequest,
  LLMResponse,
  ToolCallPart,
  ToolChoice,
  ToolOutput,
  toDefinitions,
} from "../src/index.js"
import { Auth, LLMClient } from "../src/route.js"
import * as AnthropicMessages from "../src/protocols/anthropic-messages.js"
import * as OpenAIChat from "../src/protocols/openai-chat.js"
import * as OpenAIResponses from "../src/protocols/openai-responses.js"
import { Tool, ToolFailure, type ToolExecuteContext } from "../src/tool.js"
import { ToolRuntime } from "../src/tool-runtime.js"
import { it } from "./lib/effect.js"
import * as TestToolRuntime from "./lib/tool-runtime.js"
import { dynamicResponse, scriptedResponses } from "./lib/http.js"
import { deltaChunk, finishChunk, toolCallChunk } from "./lib/openai-chunks.js"
import { sseEvents } from "./lib/sse.js"

const model = OpenAIChat.route
  .with({ endpoint: { baseURL: "https://api.openai.test/v1/" }, auth: Auth.bearer("test") })
  .model({ id: "gpt-4o-mini" })
const Json = Schema.fromJsonString(Schema.Unknown)
const decodeJson = Schema.decodeUnknownSync(Json)

const baseRequest = LLM.request({
  id: "req_1",
  model,
  prompt: "Use the tool.",
})
const weatherFailureCause = new Error("weather lookup denied")

test("dispatches namespaced calls by qualified identity", async () => {
  let context: ToolExecuteContext | undefined
  const lookup = Tool.make({
    description: "Look up a customer.",
    parameters: Schema.Struct({}),
    success: Schema.String,
    execute: (_, value) => {
      context = value
      return Effect.succeed("customer")
    },
  })
  const call = ToolCallPart.make({ id: "call_1", namespace: "crm", name: "lookup", input: {} })
  const result = await Effect.runPromise(
    ToolRuntime.dispatch({ "crm.lookup": lookup, lookup: schema_only_weather }, call),
  )

  expect(result.result).toEqual({ type: "text", value: "customer" })
  expect(context).toEqual({ id: "call_1", namespace: "crm", name: "lookup" })
  expect(result.events).toEqual([expect.objectContaining({ type: "tool-result", namespace: "crm", name: "lookup" })])
})

const get_weather = Tool.make({
  description: "Get current weather for a city.",
  parameters: Schema.Struct({ city: Schema.String }),
  success: Schema.Struct({ temperature: Schema.Number, condition: Schema.String }),
  execute: ({ city }) =>
    Effect.gen(function* () {
      if (city === "FAIL")
        return yield* new ToolFailure({ message: `Weather lookup failed for ${city}`, error: weatherFailureCause })
      return { temperature: 22, condition: "sunny" }
    }),
})

const schema_only_weather = Tool.make({
  description: "Get current weather for a city.",
  parameters: Schema.Struct({ city: Schema.String }),
  success: Schema.Struct({ temperature: Schema.Number, condition: Schema.String }),
})

describe("LLMClient tools", () => {
  it.effect("uses the selected model route when adding runtime tools", () =>
    Effect.gen(function* () {
      const layer = scriptedResponses([
        sseEvents(deltaChunk({ role: "assistant", content: "Done." }), finishChunk("stop")),
      ])

      const events = Array.from(
        yield* TestToolRuntime.runTools({ request: baseRequest, tools: { get_weather } }).pipe(
          Stream.runCollect,
          Effect.provide(layer),
        ),
      )

      expect(LLMResponse.text({ events })).toBe("Done.")
    }),
  )

  it.effect("sends tool-call history and request options on the follow-up request", () =>
    Effect.gen(function* () {
      const bodies: unknown[] = []
      const responses = [
        sseEvents(toolCallChunk("call_1", "get_weather", '{"city":"Paris"}'), finishChunk("tool_calls")),
        sseEvents(deltaChunk({ role: "assistant", content: "It's sunny in Paris." }), finishChunk("stop")),
      ]
      const layer = dynamicResponse((input) =>
        Effect.sync(() => {
          bodies.push(decodeJson(input.text))
          return input.respond(responses[bodies.length - 1] ?? responses[responses.length - 1], {
            headers: { "content-type": "text/event-stream" },
          })
        }),
      )

      yield* TestToolRuntime.runTools({
        request: LLMRequest.update(baseRequest, {
          generation: GenerationOptions.make({ maxTokens: 50 }),
          toolChoice: ToolChoice.make("auto"),
        }),
        tools: { get_weather },
      }).pipe(Stream.runCollect, Effect.provide(layer))

      const second = bodies[1]
      if (!second || typeof second !== "object") throw new Error("Expected second request body")
      const messages = "messages" in second ? second.messages : undefined
      const tools = "tools" in second ? second.tools : undefined

      expect("max_completion_tokens" in second ? second.max_completion_tokens : undefined).toBe(50)
      expect("tool_choice" in second ? second.tool_choice : undefined).toBe("auto")
      expect(tools).toHaveLength(1)
      expect(
        Array.isArray(messages)
          ? messages.map((message) =>
              message && typeof message === "object" && "role" in message ? message.role : undefined,
            )
          : undefined,
      ).toEqual(["user", "assistant", "tool"])
      expect(Array.isArray(messages) ? messages[1] : undefined).toMatchObject({
        role: "assistant",
        content: null,
        tool_calls: [{ id: "call_1", type: "function", function: { name: "get_weather" } }],
      })
      expect(Array.isArray(messages) ? messages[2] : undefined).toMatchObject({
        role: "tool",
        tool_call_id: "call_1",
        content: '{"temperature":22,"condition":"sunny"}',
      })
    }),
  )

  it.effect("dispatches a tool call, appends results, and resumes streaming", () =>
    Effect.gen(function* () {
      const layer = scriptedResponses([
        sseEvents(toolCallChunk("call_1", "get_weather", '{"city":"Paris"}'), finishChunk("tool_calls")),
        sseEvents(deltaChunk({ role: "assistant", content: "It's sunny in Paris." }), finishChunk("stop")),
      ])

      const events = Array.from(
        yield* TestToolRuntime.runTools({ request: baseRequest, tools: { get_weather } }).pipe(
          Stream.runCollect,
          Effect.provide(layer),
        ),
      )

      const result = events.find(LLMEvent.is.toolResult)
      expect(result).toMatchObject({
        type: "tool-result",
        id: "call_1",
        name: "get_weather",
        result: { type: "json", value: { temperature: 22, condition: "sunny" } },
      })
      expect(events.at(-1)?.type).toBe("finish")
      expect(LLMResponse.text({ events })).toBe("It's sunny in Paris.")
    }),
  )

  it.effect("projects encoded typed tool success into canonical model content", () =>
    Effect.gen(function* () {
      const calls: unknown[] = []
      const projected = Tool.make({
        description: "Project an encoded success.",
        parameters: Schema.Struct({ prefix: Schema.String }),
        success: Schema.Struct({ count: Schema.NumberFromString }),
        execute: () => Effect.succeed({ count: 2 }),
        toModelOutput: (input) => {
          calls.push(input)
          return [{ type: "text", text: `${input.parameters.prefix}:${input.output.count}` }]
        },
      })

      const dispatched = yield* ToolRuntime.dispatch(
        { projected },
        LLMEvent.toolCall({ id: "call_projected", name: "projected", input: { prefix: "count" } }),
      )

      expect(calls).toEqual([{ id: "call_projected", parameters: { prefix: "count" }, output: { count: "2" } }])
      expect(dispatched.result).toEqual({ type: "text", value: "count:2" })
      expect(dispatched.output).toEqual({ structured: { count: "2" }, content: [{ type: "text", text: "count:2" }] })
      expect(dispatched.events).toEqual([
        LLMEvent.toolResult({
          id: "call_projected",
          name: "projected",
          result: { type: "text", value: "count:2" },
          output: { structured: { count: "2" }, content: [{ type: "text", text: "count:2" }] },
        }),
      ])
    }),
  )

  it.effect("preserves provider metadata on dispatched tool results", () =>
    Effect.gen(function* () {
      const tool = Tool.make({
        description: "Return text.",
        parameters: Schema.Struct({}),
        success: Schema.String,
        execute: () => Effect.succeed("hello"),
      })
      const providerMetadata = { google: { thoughtSignature: "provider_sig" } }
      const dispatched = yield* ToolRuntime.dispatch(
        { tool },
        LLMEvent.toolCall({ id: "call_1", name: "tool", input: {}, providerMetadata }),
      )

      expect(dispatched.events).toEqual([
        LLMEvent.toolResult({
          id: "call_1",
          name: "tool",
          result: { type: "text", value: "hello" },
          output: { structured: "hello", content: [{ type: "text", text: "hello" }] },
          providerMetadata,
        }),
      ])

      const failed = yield* ToolRuntime.dispatch(
        {},
        LLMEvent.toolCall({ id: "call_2", name: "missing", input: {}, providerMetadata }),
      )
      expect(failed.events).toEqual([
        LLMEvent.toolError({
          id: "call_2",
          name: "missing",
          message: 'No tool named "missing" is currently available. Please use a tool from the available tool list.',
          providerMetadata,
        }),
        LLMEvent.toolResult({
          id: "call_2",
          name: "missing",
          result: {
            type: "error",
            value: 'No tool named "missing" is currently available. Please use a tool from the available tool list.',
          },
          providerMetadata,
        }),
      ])
    }),
  )

  it.effect("uses the narrow default projection for encoded typed success", () =>
    Effect.gen(function* () {
      const text = Tool.make({
        description: "Return text.",
        parameters: Schema.Struct({}),
        success: Schema.String,
        execute: () => Effect.succeed("hello"),
      })
      const json = Tool.make({
        description: "Return JSON.",
        parameters: Schema.Struct({}),
        success: Schema.Struct({ ok: Schema.Boolean }),
        execute: () => Effect.succeed({ ok: true }),
      })

      expect(
        (yield* ToolRuntime.dispatch({ text }, LLMEvent.toolCall({ id: "call_text", name: "text", input: {} }))).output,
      ).toEqual({ structured: "hello", content: [{ type: "text", text: "hello" }] })
      expect(
        (yield* ToolRuntime.dispatch({ json }, LLMEvent.toolCall({ id: "call_json", name: "json", input: {} }))).output,
      ).toEqual({ structured: { ok: true }, content: [] })
    }),
  )

  it.effect("can retain model media while redacting duplicated structured payloads", () =>
    Effect.gen(function* () {
      const image = Tool.make({
        description: "Return an image.",
        parameters: Schema.Struct({}),
        success: Schema.Struct({ mime: Schema.String, data: Schema.String }),
        execute: () => Effect.succeed({ mime: "image/png", data: "AAECAw==" }),
        toStructuredOutput: (output) => ({ mime: output.mime }),
        toModelOutput: ({ output }) => [
          { type: "file", uri: `data:${output.mime};base64,${output.data}`, mime: output.mime },
        ],
      })

      const dispatched = yield* ToolRuntime.dispatch(
        { image },
        LLMEvent.toolCall({ id: "call_image", name: "image", input: {} }),
      )

      expect(dispatched.output).toEqual({
        structured: { mime: "image/png" },
        content: [{ type: "file", uri: "data:image/png;base64,AAECAw==", mime: "image/png" }],
      })
    }),
  )

  test("models canonical tool files with URIs", () => {
    const decode = Schema.decodeUnknownSync(Content)

    expect(decode({ type: "file", uri: "data:image/png;base64,AAAA", mime: "image/png" })).toEqual({
      type: "file",
      uri: "data:image/png;base64,AAAA",
      mime: "image/png",
    })
    expect(decode({ type: "file", uri: "https://example.test/image.png", mime: "image/png" })).toEqual({
      type: "file",
      uri: "https://example.test/image.png",
      mime: "image/png",
    })
    expect(decode({ type: "file", uri: "file:///tmp/image.png", mime: "image/png" })).toEqual({
      type: "file",
      uri: "file:///tmp/image.png",
      mime: "image/png",
    })
  })

  test("preserves canonical tool file URIs", () => {
    expect(
      ToolOutput.toResultValue(
        ToolOutput.make({}, [{ type: "file", uri: "data:image/png;base64,AAAA", mime: "image/png" }]),
      ),
    ).toEqual({
      type: "content",
      value: [{ type: "file", uri: "data:image/png;base64,AAAA", mime: "image/png" }],
    })
    expect(
      ToolOutput.toResultValue(
