            ...Object.fromEntries(
              Array.from({ length: count - 1 }, (_, index) => {
                const id = `catalog-model-${index}`

                return [
                  id,
                  {
                    id,
                    name: `Catalog model ${index}`,
                    cost: { input: 1, output: 2 },
