import type { Page } from "@playwright/test"

type CachedRepaintTrace = {
  timeOriginEpochMs: number
  startedAtPerformanceMs: number
  samples: {
    observedAtMs: number
    root: number | undefined
    scrollTop: number
    scrollHeight: number
    bottomErrorPx: number | undefined
    last: boolean
    rows: { key: string | undefined; node: number; top: number; bottom: number }[]
    mounted: number
    center: string | undefined
    destination: string[]
    source: string[]
  }[]
  mutations: { observedAtMs: number; changed: { type: string; node: number }[] }[]
  shifts: { occurredAtMs: number; value: number }[]
  windowMs: number
  running: boolean
  stop: () => void
}

export async function installCachedRepaintProbe(
  page: Page,
  input: { targetHref: string; destination: string[]; source: string[]; last: string; windowMs: number },
) {
  await page.evaluate(({ targetHref, destination, source, last, windowMs }) => {
    const destinationIDs = new Set(destination)
    const sourceIDs = new Set(source)
    const nodeIDs = new WeakMap<Node, number>()
    let nextNodeID = 1

    const id = (node: Node) => {
      const current = nodeIDs.get(node)

      if (current) return current
      nodeIDs.set(node, nextNodeID)

      return nextNodeID++
    }

    const state: CachedRepaintTrace = {
      timeOriginEpochMs: performance.timeOrigin,
      startedAtPerformanceMs: 0,
      samples: [],
      mutations: [],
      shifts: [],
      windowMs,
      running: false,
      stop: () => {},
    }

    const recordShifts = (entries: PerformanceEntry[]) => {
      if (!state.running) return
      state.shifts.push(
        ...entries
          .map((entry) => {
            if (
              entry.startTime < state.startedAtPerformanceMs ||
              entry.startTime > state.startedAtPerformanceMs + state.windowMs
            )
              return

            return {
              occurredAtMs: entry.startTime - state.startedAtPerformanceMs,
              value: (entry as PerformanceEntry & { value: number }).value,
            }
          })
          .filter((entry): entry is { occurredAtMs: number; value: number } => entry !== undefined),
      )
    }

    const shiftObserver = new PerformanceObserver((entries) => recordShifts(entries.getEntries()))
    shiftObserver.observe({ type: "layout-shift" })

    const recordMutations = (entries: MutationRecord[]) => {
      if (!state.running) return
      const observedAtMs = performance.now() - state.startedAtPerformanceMs

      if (observedAtMs > state.windowMs) return

      const changed = entries.flatMap((entry) => [
        ...[...entry.addedNodes].map((node) => ({ type: "add", node: id(node) })),
        ...[...entry.removedNodes].map((node) => ({ type: "remove", node: id(node) })),
      ])

      if (changed.length) state.mutations.push({ observedAtMs, changed })
    }

    const mutationObserver = new MutationObserver(recordMutations)
    mutationObserver.observe(document.documentElement, { childList: true, subtree: true })
    state.stop = () => {
      recordShifts(shiftObserver.takeRecords())
      recordMutations(mutationObserver.takeRecords())
      state.running = false
      shiftObserver.disconnect()
      mutationObserver.disconnect()
    }

    const sample = () => {
      if (!state.running) return
      setTimeout(() => {
        if (!state.running) return
        const observedAtMs = performance.now() - state.startedAtPerformanceMs

        if (observedAtMs > state.windowMs) return

        const root = [...document.querySelectorAll<HTMLElement>(".scroll-view__viewport")].find((element) =>
          element.querySelector("[data-timeline-row]"),
        )

        if (root) {
          const view = root.getBoundingClientRect()

          const rows = [...root.querySelectorAll<HTMLElement>("[data-timeline-key]")]
            .map((element) => ({
              key: element.dataset.timelineKey,
              node: id(element),
              rect: element.getBoundingClientRect(),
            }))
            .filter((item) => item.rect.bottom > view.top && item.rect.top < view.bottom)
            .map((item) => ({
              key: item.key,
              node: item.node,
              top: item.rect.top - view.top,
              bottom: item.rect.bottom - view.top,
            }))

          const messages = [...root.querySelectorAll<HTMLElement>("[data-message-id]")]
            .filter((element) => {
              const rect = element.getBoundingClientRect()

              return rect.bottom > view.top && rect.top < view.bottom
            })
            .map((element) => element.dataset.messageId!)

          const spacer = root.querySelector<HTMLElement>('[data-timeline-row="bottom-spacer"]')?.getBoundingClientRect()
          state.samples.push({
            observedAtMs,
            root: id(root),
            scrollTop: root.scrollTop,
            scrollHeight: root.scrollHeight,
            bottomErrorPx: spacer ? spacer.bottom - view.bottom : undefined,
            last: messages.includes(last),
            rows,
            mounted: root.querySelectorAll("[data-timeline-key]").length,
            center: document
              .elementFromPoint(view.left + view.width / 2, view.top + view.height / 2)
              ?.textContent?.slice(0, 80),
            destination: messages.filter((messageID) => destinationIDs.has(messageID)),
            source: messages.filter((messageID) => sourceIDs.has(messageID)),
          })
        } else {
          state.samples.push({
            observedAtMs,
            root: undefined,
            scrollTop: 0,
            scrollHeight: 0,
            bottomErrorPx: undefined,
            last: false,
            rows: [],
            mounted: 0,
            center: document.elementFromPoint(innerWidth / 2, innerHeight / 2)?.textContent?.slice(0, 80),
            destination: [],
            source: [],
          })
        }

        requestAnimationFrame(sample)
      }, 0)
    }

    document.addEventListener(
      "click",
      (event) => {
        const link = event.target instanceof Element ? event.target.closest("a") : undefined

        if (link?.getAttribute("href") !== targetHref) return
        state.startedAtPerformanceMs = performance.now()
        state.running = true
        requestAnimationFrame(sample)
      },
      { capture: true, once: true },
    )
    ;(window as Window & { __cachedFlash?: CachedRepaintTrace }).__cachedFlash = state
  }, input)
}

export function layoutShiftSample(entry: Pick<PerformanceEntry, "startTime"> & { value: number }, started: number) {
  if (entry.startTime < started) return

  return { occurredAtMs: entry.startTime - started, value: entry.value }
}

export async function waitForCachedRepaintWindow(page: Page, durationMs: number) {
  await page.waitForFunction((durationMs) => {
    const state = (window as Window & { __cachedFlash?: CachedRepaintTrace }).__cachedFlash

    return !!state?.running && performance.now() - state.startedAtPerformanceMs >= durationMs
  }, durationMs)
}

export async function collectCachedRepaintTrace(page: Page) {
  return page.evaluate(() => {
    const state = (window as Window & { __cachedFlash?: CachedRepaintTrace }).__cachedFlash!
    state.stop()

    return state
  })
}

export function summarizeCachedRepaintTrace(trace: CachedRepaintTrace) {
  const roots = trace.samples.map((sample) => sample.root)

  const bottomErrors = trace.samples.flatMap((sample) =>
    sample.bottomErrorPx === undefined ? [] : [Math.abs(sample.bottomErrorPx)],
  )

  const category = (sample: CachedRepaintTrace["samples"][number]) => {
    if (sample.source.length) return "source"

    if (sample.root === undefined || sample.rows.length === 0) return "blank"

    if (!sample.destination.length) return "unknown"

    if (sample.last && Math.abs(sample.bottomErrorPx ?? Infinity) <= 1) return "correct"

    return "wrongDestination"
  }

  return {
    samples: trace.samples.length,
    durationMs: trace.samples.at(-1)?.observedAtMs ?? 0,
    firstSampleObservedMs: trace.samples[0]?.observedAtMs,
    firstSampleCorrect: trace.samples[0] ? category(trace.samples[0]) === "correct" : false,
    blankSamples: trace.samples.filter((sample) => category(sample) === "blank").length,
    sourceSamples: trace.samples.filter((sample) => category(sample) === "source").length,
    wrongDestinationSamples: trace.samples.filter((sample) => category(sample) === "wrongDestination").length,
    unknownSamples: trace.samples.filter((sample) => category(sample) === "unknown").length,
    rootChanges: roots.slice(1).filter((root, index) => root !== roots[index]).length,
    mountedMin: trace.samples.length ? Math.min(...trace.samples.map((sample) => sample.mounted)) : 0,
    mountedMax: Math.max(...trace.samples.map((sample) => sample.mounted)),
    maxBottomErrorPx: Math.max(0, ...bottomErrors),
    mutationBatches: trace.mutations.length,
    addedNodes: trace.mutations.reduce(
      (sum, batch) => sum + batch.changed.filter((change) => change.type === "add").length,
      0,
    ),
    removedNodes: trace.mutations.reduce(
      (sum, batch) => sum + batch.changed.filter((change) => change.type === "remove").length,
      0,
    ),
    layoutShiftValueSum: trace.shifts.reduce((sum, shift) => sum + shift.value, 0),
    maxLayoutShiftValue: Math.max(0, ...trace.shifts.map((shift) => shift.value)),
  }
}

export function compressCachedRepaintTrace(trace: CachedRepaintTrace) {
  const samples: {
    observedAtMs: number[]
    state: Omit<CachedRepaintTrace["samples"][number], "observedAtMs">
  }[] = []

  for (const sample of trace.samples) {
    const { observedAtMs, ...state } = sample
    const previous = samples.at(-1)

    if (previous && JSON.stringify(previous.state) === JSON.stringify(state)) {
      previous.observedAtMs.push(observedAtMs)
      continue
    }

    samples.push({ observedAtMs: [observedAtMs], state })
  }

  return {
    timeOriginEpochMs: trace.timeOriginEpochMs,
    startedAtPerformanceMs: trace.startedAtPerformanceMs,
    windowMs: trace.windowMs,
    summary: summarizeCachedRepaintTrace(trace),
    samples,
    mutations: trace.mutations,
    shifts: trace.shifts,
  }
}

import type { Page } from "@playwright/test"
import { mockOpenCodeServer } from "../../utils/mock-server"
import { expectSessionTitle } from "../../utils/waits"
import { benchmark, benchmarkDiagnostics, expect } from "../benchmark"
import { fixture, installStressSessionTabs, installTimelineSettings } from "../../utils/session-fixture"
import { sessionHref } from "../../utils/app"
import { expected, messages } from "../../utils/markdown-sessions"
import { workload } from "./session-tab-switch.fixture"
import { createReviewDiffs } from "./timeline-test-helpers"
import { measureSessionSwitch, waitForStableTimeline } from "./session-tab-switch-probe"

const scenarios = [
  { cache: "cold", review: "closed" },
  { cache: "cold", review: "open" },
  { cache: "warm", review: "closed" },
  { cache: "warm", review: "open" },
  { cache: "warm", review: "resized" },
] as const

const viewport = { width: 1440, height: 900 }

const reviewDiffs = createReviewDiffs()

benchmark.use({ viewport, video: "off", trace: "off", serviceWorkers: "block", traceScope: "interaction" })

scenarios.forEach((scenario) => {
  benchmark(`tab switch: ${scenario.cache}, review ${scenario.review}`, async ({ page, report }, testInfo) => {
    const requests = await prepareSessionTabs(page)

    if (scenario.review === "open") await openReviewPane(page)

    if (scenario.cache === "warm") {
      await switchSession(page, fixture.targetID, fixture.expected.targetTitle)
      await expectReadyTimeline(page, fixture.targetID)
      await switchSession(page, fixture.sourceID, fixture.expected.sourceTitle)
    }

    if (scenario.review === "resized") await openReviewPane(page)
    await expectReadyTimeline(page, fixture.sourceID)
    await benchmarkDiagnostics(page).startTrace()
    const requestsBefore = requests.length

    const result = await measureSessionSwitch(page, {
      destinationIDs: messages[fixture.targetID].map((message) => message.id),
      sourceIDs: messages[fixture.sourceID].map((message) => message.id),
      lastID: expected[fixture.targetID].lastID,
      requiredPartID: expected[fixture.targetID].answerID,
      href: sessionHref(fixture.targetID),
      switch: () => switchSession(page, fixture.targetID, fixture.expected.targetTitle),
    })

    expect(result.firstCorrectObservedMs).not.toBeNull()
    expect(result.stableObservedMs).not.toBeNull()
    expect(requests).toHaveLength(requestsBefore + (scenario.cache === "cold" ? 1 : 0))
    await expectReadyTimeline(page, fixture.targetID)
    report(
      {
        ...result,
        messageRequestsDuringSwitch: requests.length - requestsBefore,
        rendererMemory:
          process.env.OPENCODE_PERFORMANCE_MEMORY === "1" ? await retainedRendererMemory(page) : undefined,
      },
      {
        ...scenario,
        ...workload,
        viewport,
        browserVersion: page.context().browser()!.version(),
        serviceWorkers: "blocked",
        reviewFiles: scenario.review === "closed" ? 0 : reviewDiffs.length,
        data: scenario.cache === "cold" ? "on-demand" : "cached",
        transport: process.env.OPENCODE_PERFORMANCE_HTTP_FIXTURE === "1" ? "http" : "playwright-route",
        inputEvent: "mousedown",
        requireReadyAnswer: true,
      },
    )

    if (testInfo.repeatEachIndex === 0) {
      await page.screenshot({ path: testInfo.outputPath("destination.png") })
      await testInfo.attach("destination", { path: testInfo.outputPath("destination.png"), contentType: "image/png" })
    }
  })
})

async function prepareSessionTabs(page: Page) {
  const requests: string[] = []
  page.on("request", (request) => {
    if (request.method() !== "GET") return
    const match = new URL(request.url()).pathname.match(/^\/api\/session\/([^/]+)\/message$/)

    if (match) requests.push(decodeURIComponent(match[1]))
  })

  if (process.env.OPENCODE_PERFORMANCE_HTTP_FIXTURE !== "1")
    await mockOpenCodeServer(page, {
      sessions: fixture.sessions,
      provider: fixture.provider,
      directory: fixture.directory,
      project: fixture.project,
      // Return the full history so every scenario exercises a long loaded timeline.
      pageMessages: (sessionID) => ({ items: messages[sessionID] ?? [] }),
      vcsDiff: reviewDiffs,
    })
  await installTimelineSettings(page)
  await installStressSessionTabs(page)
  await page.goto(sessionHref(fixture.sourceID))
  await expectSessionTitle(page, fixture.expected.sourceTitle)
  await expectReadyTimeline(page, fixture.sourceID)
  await expect(page.locator(`[data-timeline-part-id="${expected[fixture.targetID].answerID}"]`)).toHaveCount(0)
  expect(requests).toEqual([fixture.sourceID])

  return requests
}

async function expectReadyTimeline(page: Page, sessionID: string) {
  const answer = page.locator(`[data-timeline-part-id="${expected[sessionID].answerID}"]`)
  await expect(answer.locator('[data-component="markdown"]')).toHaveAttribute("data-markdown-ready", "")
  await expect(answer.getByRole("table")).toHaveCount(1)
  await expect(answer.locator("pre")).toHaveCount(4)
  await expect
    .poll(() => answer.evaluate((element) => element.checkVisibility({ checkOpacity: true, checkVisibilityCSS: true })))
    .toBe(true)
  await waitForStableTimeline(page, expected[sessionID].lastID)
  await expect(page.locator('[data-timeline-key] [data-component="markdown"]:not([data-markdown-ready])')).toHaveCount(
    0,
  )
}

async function switchSession(page: Page, sessionID: string, title: string) {
  const tab = page.locator(`[data-slot="titlebar-tabs"] a[href="${sessionHref(sessionID)}"]`)
  await expect(tab).toHaveCount(1)
  await tab.click()
  await expectSessionTitle(page, title)
}

async function openReviewPane(page: Page) {
  await page.getByRole("button", { name: "Toggle review" }).click()
  await expect(page.locator("#review-panel")).toBeVisible()
  await page.waitForFunction(() => {
    const text = document.querySelector("#review-panel")?.textContent ?? ""

    return text.includes("generated-000.ts") && text.includes("+3")
  })
  await page.locator('[data-slot="session-chat-panel"]').evaluate(async (panel) => {
    await Promise.all(panel.getAnimations().map((animation) => animation.finished))
  })
}

async function retainedRendererMemory(page: Page) {
  const cdp = await page.context().newCDPSession(page)

  try {
    await cdp.send("HeapProfiler.collectGarbage")

    return {
      heap: await cdp.send("Runtime.getHeapUsage"),
      dom: await cdp.send("Memory.getDOMCounters"),
    }
  } finally {
    await cdp.detach()
  }
}

export type SessionSwitchSample = {
  observedAtMs: number
  destination: string[]
  source: string[]
  hasVisibleRows: boolean
  last: boolean
  requiredPartVisible?: boolean
  bottomAnchorRequired?: boolean
  bottomErrorPx?: number
  review?: {
    fileHost: boolean
    fileHostReplaced: boolean
    header: string
    replacedLevels: string[]
  }
}

export function classifySessionSwitch(samples: SessionSwitchSample[]) {
  const firstDestination = samples.findIndex((sample) => sample.destination.length > 0)
  const firstCorrect = samples.findIndex(isCorrectDestination)
  const stable = samples.findIndex((_, index) => isStableSessionSwitch(samples.slice(index, index + 3)))

  return {
    samples,
    firstDestinationObservedMs: samples[firstDestination]?.observedAtMs ?? null,
    firstCorrectObservedMs: samples[firstCorrect]?.observedAtMs ?? null,
    stableObservedMs: stable < 0 ? null : samples[stable + 2].observedAtMs,
    wrongDestinationSamples: samples
      .slice(firstDestination)
      .filter((sample) => sample.destination.length > 0 && !sample.last).length,
    blankSamples: samples.filter((sample) => !sample.hasVisibleRows).length,
    unknownSamples: samples.filter(
      (sample) => sample.hasVisibleRows && sample.destination.length === 0 && sample.source.length === 0,
    ).length,
    sourceSamples: samples.filter((sample) => sample.source.length > 0).length,
    reviewFileHostMissingSamples: samples.filter((sample) => sample.review && !sample.review.fileHost).length,
    reviewFileHostReplacedSamples: samples.filter((sample) => sample.review?.fileHostReplaced).length,
    reviewHeaders: [...new Set(samples.flatMap((sample) => (sample.review ? [sample.review.header] : [])))],
    reviewReplacedLevels: [...new Set(samples.flatMap((sample) => sample.review?.replacedLevels ?? []))],
  }
}

export function isCorrectDestination(sample: SessionSwitchSample) {
  return (
    sample.destination.length > 0 &&
    sample.source.length === 0 &&
    sample.last &&
    sample.requiredPartVisible !== false &&
    (sample.bottomAnchorRequired === false || Math.abs(sample.bottomErrorPx ?? Infinity) <= 1)
  )
}

export function isStableSessionSwitch(samples: SessionSwitchSample[]) {
  return samples.length === 3 && samples.every(isCorrectDestination)
}

export function isStableDestination(samples: Pick<SessionSwitchSample, "last" | "bottomErrorPx">[]) {
  return (
    samples.length === 3 && samples.every((sample) => sample.last && Math.abs(sample.bottomErrorPx ?? Infinity) <= 1)
  )
}

import { benchmark, expect } from "../benchmark"
import { measureSessionSwitch } from "./session-tab-switch-probe"
import type { SessionSwitchSample } from "./session-tab-switch-metrics"

for (const tag of ["a", "button"] as const) {
  benchmark(
    `starts at ${tag} mousedown and excludes hidden or unfinished destination content`,
    async ({ page, report }) => {
      await page.setContent(`
    <${tag} id="destination" ${tag === "a" ? 'href="/session/destination"' : 'type="button"'}>Destination</${tag}>
    <div class="scroll-view__viewport" style="height:200px;overflow:auto">
      <div data-timeline-row="message" data-timeline-key="row" data-message-id="source">
        <div data-timeline-part-id="answer"><div data-component="markdown">Destination answer</div></div>
      </div>
    </div>
  `)
      await page.evaluate(() => {
        document.querySelector("#destination")!.addEventListener("mousedown", () => {
          const row = document.querySelector<HTMLElement>("[data-message-id]")!
          row.dataset.messageId = "destination"
          row.style.visibility = "hidden"
        })
      })

      const result = await measureSessionSwitch(page, {
        destinationIDs: ["destination"],
        sourceIDs: ["source"],
        lastID: "destination",
        requiredPartID: "answer",
        requireBottomAnchor: false,
        href: "/session/destination",
        triggerSelector: tag === "button" ? "#destination" : undefined,
        switch: async () => {
          // No click is dispatched: the probe must observe the event that activates tabs.
          await page
            .getByRole(tag === "a" ? "link" : "button", { name: "Destination", exact: true })
            .dispatchEvent("mousedown", { button: 0 })
          await page.waitForFunction(() => {
            const host = window as Window & { __sessionSwitchProbe?: { samples: SessionSwitchSample[] } }

            return host.__sessionSwitchProbe?.samples.some((sample) => !sample.hasVisibleRows)
          })
          await page.locator("[data-message-id]").evaluate((row) => row.style.removeProperty("visibility"))
          await page.waitForFunction(() => {
            const host = window as Window & { __sessionSwitchProbe?: { samples: SessionSwitchSample[] } }

            return host.__sessionSwitchProbe?.samples.some(
              (sample) => sample.destination.length > 0 && sample.requiredPartVisible === false,
            )
          })

          const beforeClip = await page.evaluate(() => {
            const row = document.querySelector<HTMLElement>("[data-timeline-key]")!
            row.style.cssText = "height:10px;position:relative;overflow:clip"
            const answer = row.querySelector<HTMLElement>("[data-timeline-part-id]")!
            answer.style.cssText = "position:absolute;top:30px;width:150px"
            answer.querySelector('[data-component="markdown"]')!.setAttribute("data-markdown-ready", "")

            return (
              (window as Window & { __sessionSwitchProbe?: { samples: SessionSwitchSample[] } }).__sessionSwitchProbe
                ?.samples.length ?? 0
            )
          })

          await page.waitForFunction((count) => {
            const host = window as Window & { __sessionSwitchProbe?: { samples: SessionSwitchSample[] } }

            return host.__sessionSwitchProbe?.samples
              .slice(count)
              .some((sample) => sample.requiredPartVisible === false)
          }, beforeClip)
          await page.locator("[data-timeline-key]").evaluate((row) => {
            row.style.height = "100px"
          })
        },
      })

      expect(result.blankSamples).toBeGreaterThan(0)
      expect(result.firstCorrectObservedMs).not.toBeNull()
      expect(result.stableObservedMs).not.toBeNull()
      expect(result.firstCorrectObservedMs).toBeGreaterThan(result.firstDestinationObservedMs!)
      expect(await page.evaluate(() => "__sessionSwitchProbe" in window)).toBe(false)
      report(result)
    },
  )
}

import { expect, type Page } from "@playwright/test"
import { classifySessionSwitch, isStableDestination, type SessionSwitchSample } from "./session-tab-switch-metrics"

type SessionSwitchProbe = {
  samples: SessionSwitchSample[]
  stop: () => void
}

async function installSessionSwitchProbe(
  page: Page,
  input: {
    destinationIDs: string[]
    sourceIDs: string[]
    lastID: string
    requiredPartID?: string
    requireBottomAnchor?: boolean
    triggerSelector?: string
    href: string
  },
) {
  await page.evaluate(
    ({ destinationIDs, sourceIDs, lastID, requiredPartID, requireBottomAnchor, triggerSelector, href }) => {
      const destination = new Set(destinationIDs)
      const source = new Set(sourceIDs)
      const samples: SessionSwitchSample[] = []
      let started: number | undefined
      let running = true

      const reviewLevels: Record<string, string> = {
        panel: "#review-panel",
        tabs: '#review-panel [data-component="tabs"]',
        body: '#review-panel [data-slot="session-review-v2-body"]',
        review: '#review-panel [data-component="session-review-v2"]',
        preview: '#review-panel [data-slot="session-review-v2-preview"]',
        scroll: '#review-panel [data-slot="session-review-v2-diff-scroll"]',
        file: '#review-panel [data-component="file"][data-mode="diff"]',
      }

      const initialReviewNodes: Record<string, Element | null> = {}

      const sample = () => {
        if (!running || started === undefined) return
        setTimeout(() => {
          if (!running || started === undefined) return
          const reviewPanel = document.querySelector<HTMLElement>("#review-panel")
          const reviewFile = reviewPanel?.querySelector('[data-component="file"][data-mode="diff"]')
          const initialReviewFile = initialReviewNodes.file

          const replacedLevels = Object.entries(reviewLevels).flatMap(([name, selector]) => {
            const initial = initialReviewNodes[name]

            if (!initial) return []
            const current = document.querySelector(selector)

            return current && current !== initial ? [name] : []
          })

          const review = reviewPanel
            ? {
                fileHost: !!reviewFile,
                fileHostReplaced: !!initialReviewFile && !!reviewFile && reviewFile !== initialReviewFile,
                header:
                  reviewPanel
                    .querySelector<HTMLElement>('[data-slot="session-review-v2-file-header"]')
                    ?.textContent?.trim() ?? "",
                replacedLevels,
              }
            : undefined

          const root = [...document.querySelectorAll<HTMLElement>(".scroll-view__viewport")].find((element) =>
            element.querySelector("[data-timeline-row]"),
          )

          if (root) {
            const view = root.getBoundingClientRect()

            const inViewport = (element: HTMLElement) => {
              if (!element.checkVisibility({ checkOpacity: true, checkVisibilityCSS: true })) return false
              const rect = element.getBoundingClientRect()
              const clip = element.closest<HTMLElement>("[data-timeline-key]")?.getBoundingClientRect() ?? view

              return (
                Math.min(rect.bottom, clip.bottom, view.bottom) > Math.max(rect.top, clip.top, view.top) &&
                Math.min(rect.right, clip.right, view.right) > Math.max(rect.left, clip.left, view.left)
              )
            }

            const visible = [...root.querySelectorAll<HTMLElement>("[data-message-id]")]
              .filter(inViewport)
              .map((element) => element.dataset.messageId!)

            const hasVisibleRows = [...root.querySelectorAll<HTMLElement>("[data-timeline-key]")].some(inViewport)

            const requiredPartVisible = requiredPartID
              ? [...root.querySelectorAll<HTMLElement>("[data-timeline-part-id]")].some((element) => {
                  if (element.dataset.timelinePartId !== requiredPartID) return false

                  if (!element.textContent?.trim()) return false

                  if (element.querySelector('[data-component="markdown"]:not([data-markdown-ready])')) return false

                  return inViewport(element)
                })
              : undefined

            const spacer = root
              .querySelector<HTMLElement>('[data-timeline-row="bottom-spacer"]')
              ?.getBoundingClientRect()

            samples.push({
              observedAtMs: performance.now() - started,
              destination: visible.filter((id) => destination.has(id)),
              source: visible.filter((id) => source.has(id)),
              hasVisibleRows,
              last: visible.includes(lastID),
              requiredPartVisible,
              bottomAnchorRequired: requireBottomAnchor !== false,
              bottomErrorPx: spacer ? spacer.bottom - view.bottom : undefined,
              review,
            })
          } else {
            samples.push({
              observedAtMs: performance.now() - started,
              destination: [],
              source: [],
              hasVisibleRows: false,
              last: false,
              requiredPartVisible: requiredPartID ? false : undefined,
              bottomAnchorRequired: requireBottomAnchor !== false,
              review,
            })
          }

          requestAnimationFrame(sample)
        }, 0)
      }

      const start = (event: MouseEvent) => {
        if (started !== undefined || event.button !== 0) return
        const trigger = event.target instanceof Element ? event.target.closest(triggerSelector ?? "a") : undefined

        if (!trigger || (!triggerSelector && trigger.getAttribute("href") !== href)) return
        started = performance.now()
        performance.mark("session-switch:start", { startTime: started })

        for (const [name, selector] of Object.entries(reviewLevels)) {
          initialReviewNodes[name] = document.querySelector(selector)
        }

        requestAnimationFrame(sample)
      }

      // Tabs activate on mousedown; click alone misses the synchronous navigation work.
      document.addEventListener("mousedown", start, true)
      document.addEventListener("click", start, true)
      ;(window as Window & { __sessionSwitchProbe?: SessionSwitchProbe }).__sessionSwitchProbe = {
        samples,
        stop: () => {
          running = false
          document.removeEventListener("mousedown", start, true)
          document.removeEventListener("click", start, true)
          Object.keys(initialReviewNodes).forEach((key) => (initialReviewNodes[key] = null))
        },
      }
    },
    input,
  )
}

async function waitForStableSessionSwitch(page: Page) {
  await page.waitForFunction(() => {
    const samples = (window as Window & { __sessionSwitchProbe?: SessionSwitchProbe }).__sessionSwitchProbe?.samples

    if (!samples) return false

    return samples.some((_, index) => {
      const stable = samples.slice(index, index + 3)

      return (
        stable.length === 3 &&
        stable.every(
          (sample) =>
            sample.destination.length > 0 &&
            sample.source.length === 0 &&
            sample.last &&
            sample.requiredPartVisible !== false &&
            (sample.bottomAnchorRequired === false || Math.abs(sample.bottomErrorPx ?? Infinity) <= 1),
        )
      )
    })
  })
}

async function collectSessionSwitchResult(page: Page) {
  const samples = await page.evaluate(() => {
    const probe = (window as Window & { __sessionSwitchProbe?: SessionSwitchProbe }).__sessionSwitchProbe!
    probe.stop()
    delete (window as Window & { __sessionSwitchProbe?: SessionSwitchProbe }).__sessionSwitchProbe

    return probe.samples
  })

  const result = classifySessionSwitch(samples)
  await page.evaluate(({ firstCorrectObservedMs, stableObservedMs }) => {
    const start = performance.getEntriesByName("session-switch:start").at(-1)!.startTime

    if (firstCorrectObservedMs !== null)
      performance.mark("session-switch:ready", { startTime: start + firstCorrectObservedMs })

    if (stableObservedMs !== null) performance.mark("session-switch:stable", { startTime: start + stableObservedMs })
  }, result)

  return result
}

export async function measureSessionSwitch(
  page: Page,
  input: {
    destinationIDs: string[]
    sourceIDs: string[]
    lastID: string
    requiredPartID?: string
    requireBottomAnchor?: boolean
    triggerSelector?: string
    href: string
    switch: () => Promise<void>
  },
) {
  const { switch: run, ...probe } = input
  await installSessionSwitchProbe(page, probe)

  try {
    await run()
    await waitForStableSessionSwitch(page)

    return await collectSessionSwitchResult(page)
  } finally {
    await page.evaluate(() => {
      ;(window as Window & { __sessionSwitchProbe?: SessionSwitchProbe }).__sessionSwitchProbe?.stop()
      delete (window as Window & { __sessionSwitchProbe?: SessionSwitchProbe }).__sessionSwitchProbe
    })
  }
}

export async function waitForStableTimeline(page: Page, lastID: string) {
  const samples: Pick<SessionSwitchSample, "last" | "bottomErrorPx">[] = []
  await expect
    .poll(
      async () => {
        samples.push(
          await page.evaluate(
            (lastID) =>
              new Promise<Pick<SessionSwitchSample, "last" | "bottomErrorPx">>((resolve) => {
                requestAnimationFrame(() =>
                  setTimeout(() => {
                    const root = [...document.querySelectorAll<HTMLElement>(".scroll-view__viewport")].find((element) =>
                      element.querySelector("[data-timeline-row]"),
                    )

                    if (!root) {
                      resolve({ last: false })

                      return
                    }

                    const view = root.getBoundingClientRect()

                    const last = [...root.querySelectorAll<HTMLElement>("[data-message-id]")].some((element) => {
                      if (element.dataset.messageId !== lastID) return false
                      const rect = element.getBoundingClientRect()

                      return rect.bottom > view.top && rect.top < view.bottom
                    })

                    const spacer = root
                      .querySelector<HTMLElement>('[data-timeline-row="bottom-spacer"]')
                      ?.getBoundingClientRect()

                    resolve({ last, bottomErrorPx: spacer ? spacer.bottom - view.bottom : undefined })
                  }, 0),
                )
              }),
            lastID,
          ),
        )

        return isStableDestination(samples.slice(-3))
      },
      { timeout: 30_000, intervals: [0] },
    )
    .toBe(true)
}

