async function runTimelineStreamBenchmark(page: Page, options: TimelineStreamOptions) {
  const completionTimeoutMs = Number(process.env.TIMELINE_COMPLETION_TIMEOUT_MS ?? 420_000)
  const cpuThrottle = Number(process.env.TIMELINE_CPU_THROTTLE ?? 30)
  const deltaCount = Number(process.env.TIMELINE_DELTA_COUNT ?? 160)
  const historyTurns = Number(process.env.TIMELINE_HISTORY_TURNS ?? 320)
  const eventBatch = Number(process.env.TIMELINE_EVENT_BATCH ?? 1)
  const minimal = process.env.TIMELINE_MINIMAL === "1"
  const profileCPU = process.env.TIMELINE_CPU_PROFILE === "1"
  const profileVisual = !minimal && profileCPU && process.env.TIMELINE_VISUAL_PROFILE !== "0"
  const diffs = options.reviewDiffs || options.reviewPane ? createReviewDiffs() : undefined

  const fixture = await setupTimelineBenchmark(page, {
    historyTurns,
    eventBatch,
    // Turn diffs exercise timeline data cost; the pane-open scenario serves the same
    // diffs through the default git mode so it works across review implementations.
    turnDiffs: options.reviewDiffs ? diffs : undefined,
    vcsDiff: options.reviewPane ? diffs : undefined,
  })

  fixture.transport.enqueue(buildInitialStreamEvent(deltaCount))
  const contentStart = performance.now()
  await expect(fixture.text).toBeVisible()
  await expect(fixture.text).toContainText("Implementation plan")
  const initialContentObservedMs = performance.now() - contentStart
  await fixture.scrollToBottom()
  await fixture.waitForStableGeometry()

  const reviewPane = options.reviewPane && diffs ? await measureReviewPaneLoad(page, diffs[0]!.file) : undefined

  if (reviewPane) await fixture.waitForStableGeometry()

  const profile = await startTimelineProfile(page, { cpuThrottle, profileCPU })
  await installTimelineStreamProbe(page, { textPartID, finalIndex: deltaCount, profileVisual, minimal })
  const deltas = buildStreamDeltaEvents(deltaCount)
  await startTimelineStreamProbe(page)
  fixture.transport.enqueue(deltas)

  await page.waitForFunction(
    (finalIndex) =>
      (
        window as Window & {
          __timelineStreamBenchmark?: { applied: { index: number }[] }
        }
      ).__timelineStreamBenchmark?.applied.some((value) => value.index === finalIndex),
    deltaCount,
    { timeout: completionTimeoutMs },
  )
  await expect(fixture.text).toContainText("benchmark-complete")
  await expect(fixture.text).toContainText("Streaming")
  await fixture.waitForStableGeometry()

  const metrics = await collectTimelineStreamMetrics(page, {
    textPartID,
    finalIndex: deltaCount,
    navigations: benchmarkDiagnostics(page).navigations,
  })

  const delivered = deltas.length - fixture.transport.pendingCount()
  await profile.stop()

  const result = {
    metrics: {
      endToEndInitialContentObservedMs: initialContentObservedMs,
      ...metrics,
      deliveredDeltas: delivered,
      pendingDeltas: fixture.transport.pendingCount(),
      reviewPane: reviewPane ?? null,
    },
    context: {
      cpuThrottle,
      profileCPU,
      profileVisual,
      minimal,
      queuedDeltas: deltas.length,
      historyTurns,
      eventBatch,
      reviewPane: options.reviewPane === true ? "open" : "closed",
      reviewDiffs: diffs?.length ?? 0,
    },
  }

  await profile.reset()

  return result
}

async function measureReviewPaneLoad(page: Page, file: string) {
  // Default git mode reads the mocked /vcs/diff data, so opening the pane is enough
  // and the flow works across review pane implementations.
  await installReviewPaneProbe(page, { file })
  await startReviewPaneProbe(page)
  await page.getByRole("button", { name: "Toggle review" }).click()
  await expect(page.locator("#review-panel")).toBeVisible()

  return collectReviewPaneProbe(page)
}

async function measureReviewNextFile(page: Page, file: string) {
  await installReviewPaneProbe(page, { file })
  await startReviewPaneProbe(page)
  await page.getByRole("button", { name: "Next file" }).click()

  return collectReviewPaneProbe(page)
}

async function installReviewPaneProbe(page: Page, input: { file: string }) {
  await page.evaluate((input) => {
    const samples: ReviewPaneSample[] = []
    const basename = input.file.split(/[\\/]/).at(-1) ?? input.file
    let started: number | undefined
    let running = true

    const paneState = () => {
      const panel = document.querySelector<HTMLElement>("#review-panel")
      const review = panel?.querySelector<HTMLElement>('[data-component="session-review-v2"]')
      const rect = (review ?? panel)?.getBoundingClientRect()
      const text = panel?.textContent ?? ""

      const previewHeader = panel?.querySelector<HTMLElement>(
        '[data-slot="session-review-v2-file-header"]',
      )?.textContent

      const header = previewHeader ?? text
      const viewers = panel ? [...panel.querySelectorAll<HTMLElement>('[data-component="file"][data-mode="diff"]')] : []
      const codeBlocks = panel?.querySelectorAll("code").length ?? 0

      const diffLines = viewers.reduce(
        (sum, viewer) =>
          sum +
          (viewer.shadowRoot?.querySelectorAll("[data-line]").length ?? viewer.querySelectorAll("[data-line]").length),
        0,
      )

      const panelVisible =
        !!panel && panel.getAttribute("aria-hidden") !== "true" && !!rect && rect.width > 0 && rect.height > 0

      return {
        panelVisible,
        header: header.slice(0, 500),
        diffViewers: viewers.length,
        diffLines,
        codeBlocks,
        ready:
          panelVisible &&
          header.includes(basename) &&
          (viewers.length > 0 || text.includes("+3") || diffLines > 0 || codeBlocks > 0),
      }
    }

    const sample = () => {
      if (!running || started === undefined) return
      requestAnimationFrame(() => {
        setTimeout(() => {
          if (!running || started === undefined) return
          samples.push({ observedAtMs: performance.now() - started, ...paneState() })

          if (performance.now() - started < 10_000) sample()
        }, 0)
      })
    }

    ;(window as Window & { __reviewPaneProbe?: ReviewPaneProbe }).__reviewPaneProbe = {
      samples,
      start: () => {
        started = performance.now()
        performance.mark("opencode.review-pane.click")
        sample()
      },
      stop: () => {
        running = false
      },
    }
  }, input)
}

async function startReviewPaneProbe(page: Page) {
  await page.evaluate(() => {
    ;(window as Window & { __reviewPaneProbe?: ReviewPaneProbe }).__reviewPaneProbe!.start()
  })
}

async function collectReviewPaneProbe(page: Page) {
  await page.waitForFunction((streak) => {
    const samples = (window as Window & { __reviewPaneProbe?: ReviewPaneProbe }).__reviewPaneProbe?.samples

    if (!samples) return false

    return samples.some((_, index) => {
      const stable = samples.slice(index, index + streak)

      return stable.length === streak && stable.every((sample) => sample.ready)
    })
  }, reviewReadyStreak)

  const samples = await page.evaluate(() => {
    const probe = (window as Window & { __reviewPaneProbe?: ReviewPaneProbe }).__reviewPaneProbe!
    probe.stop()

    return probe.samples
  })

  return { summary: summarizeReviewPaneSamples(samples), samples }
}

function summarizeReviewPaneSamples(samples: ReviewPaneSample[]) {
  const firstReady = samples.find((sample) => sample.ready)

  const stableIndex = samples.findIndex((_, index) => {
    const stable = samples.slice(index, index + reviewReadyStreak)

    return stable.length === reviewReadyStreak && stable.every((sample) => sample.ready)
  })

  return {
    samples: samples.length,
    firstReadyObservedMs: firstReady?.observedAtMs ?? null,
    stableReadyObservedMs: stableIndex === -1 ? null : samples[stableIndex + reviewReadyStreak - 1]!.observedAtMs,
    notReadySamples: samples.filter((sample) => !sample.ready).length,
    maxDiffViewers: Math.max(0, ...samples.map((sample) => sample.diffViewers)),
    maxDiffLines: Math.max(0, ...samples.map((sample) => sample.diffLines)),
    maxCodeBlocks: Math.max(0, ...samples.map((sample) => sample.codeBlocks)),
  }
}

import type { Page } from "@playwright/test"
import path from "node:path"
import { mkdir, writeFile } from "node:fs/promises"

export async function startTimelineProfile(page: Page, options: { cpuThrottle: number; profileCPU: boolean }) {
  const cdp = await page.context().newCDPSession(page)

  if (options.cpuThrottle > 1) await cdp.send("Emulation.setCPUThrottlingRate", { rate: options.cpuThrottle })

  if (options.profileCPU) {
    await cdp.send("Profiler.enable")
    await cdp.send("Profiler.setSamplingInterval", { interval: 100 })
    await cdp.send("Profiler.start")
  }

  return {
    async stop() {
      if (!options.profileCPU) return
      const result = await cdp.send("Profiler.stop")
      const directory = process.env.TIMELINE_CPU_PROFILE_DIR

      if (directory) {
        await mkdir(directory, { recursive: true })
        const file = path.join(directory, `${process.env.OPENCODE_PERFORMANCE_RUN_ID ?? "manual"}-timeline.cpuprofile`)
        await writeFile(file, JSON.stringify(result.profile))
        console.log("timeline cpu profile file", file)
      }

      const self = new Map<number, number>()
      result.profile.samples?.forEach((id, index) => {
        const duration = (result.profile.timeDeltas?.[index] ?? 0) / 1_000
        self.set(id, (self.get(id) ?? 0) + duration)
      })
      console.log(
        "timeline cpu profile",
        JSON.stringify(
          result.profile.nodes
            .map((node) => ({
              function: node.callFrame.functionName || "(anonymous)",
              url: node.callFrame.url,
              line: node.callFrame.lineNumber + 1,
              selfMs: self.get(node.id) ?? 0,
            }))
            .filter((node) => node.selfMs > 1)
            .sort((a, b) => b.selfMs - a.selfMs)
            .slice(0, 40),
        ),
      )
    },
    async reset() {
      if (options.cpuThrottle > 1) await cdp.send("Emulation.setCPUThrottlingRate", { rate: 1 })
    },
  }
}

import type { Page } from "@playwright/test"

export type TimelineSearchSample = {
  observedAtMs: number
  counter: string
  targetMounted: boolean
  targetVisible: boolean
  targetTopPx?: number
  activeRanges: number
  activePartID?: string
  activeVisible: boolean
  scrollTopPx: number
}

type TimelineSearchProbe = {
  samples: TimelineSearchSample[]
  handlerDurationMs?: number
  initialScrollTopPx: number
  stop: () => void
}

export async function installTimelineSearchProbe(page: Page, input: { targetPartID: string }) {
  await page.evaluate(({ targetPartID }) => {
    const search = document.querySelector<HTMLElement>('[data-component="timeline-search-bar"]')
    const field = search?.querySelector<HTMLInputElement>('[data-slot="text-input-v2-input"]')

    const root = [...document.querySelectorAll<HTMLElement>(".scroll-view__viewport")].find((element) =>
      element.querySelector("[data-timeline-row]"),
    )

    if (!search || !field || !root) throw new Error("missing timeline search benchmark nodes")

    const samples: TimelineSearchSample[] = []
    const initialScrollTopPx = root.scrollTop
    let startedAt: number | undefined
    let handlerDurationMs: number | undefined
    let frame: number | undefined
    let running = true

    const visibleInRoot = (rect: DOMRect) => {
      const viewport = root.getBoundingClientRect()

      return rect.width > 0 && rect.height > 0 && rect.bottom > viewport.top && rect.top < viewport.bottom
    }

    const sample = () => {
      if (!running || startedAt === undefined) return
      frame = requestAnimationFrame(() => {
        frame = undefined
        setTimeout(() => {
          if (!running || startedAt === undefined) return
          const target = root.querySelector<HTMLElement>(`[data-timeline-part-id="${targetPartID}"]`)
          const targetRect = target?.getBoundingClientRect()
          const highlight = CSS.highlights.get("timeline-search-hit-active")
          const ranges = highlight ? [...highlight] : []
          const active = ranges.find((range): range is Range => range instanceof Range)
          const activeRect = active?.getBoundingClientRect()

          const activeElement =
            active?.startContainer instanceof Element ? active.startContainer : active?.startContainer.parentElement

          samples.push({
            observedAtMs: performance.now() - startedAt,
            counter:
              search.querySelector<HTMLElement>('[data-slot="timeline-search-count"]')?.textContent?.trim() ?? "",
            targetMounted: !!target,
            targetVisible: !!targetRect && visibleInRoot(targetRect),
            targetTopPx: targetRect?.top,
            activeRanges: ranges.length,
            activePartID: activeElement?.closest<HTMLElement>("[data-timeline-part-id]")?.dataset.timelinePartId,
            activeVisible: !!activeRect && visibleInRoot(activeRect),
            scrollTopPx: root.scrollTop,
          })
          sample()
        }, 0)
      })
    }

    const onInputCapture = (event: Event) => {
      if (event.target !== field || startedAt !== undefined) return
      startedAt = performance.now()
      sample()
    }

    const onInput = (event: Event) => {
      if (event.target !== field || startedAt === undefined || handlerDurationMs !== undefined) return
      handlerDurationMs = performance.now() - startedAt
    }

    document.addEventListener("input", onInputCapture, { capture: true })
    document.addEventListener("input", onInput)
    ;(window as Window & { __timelineSearchBenchmark?: TimelineSearchProbe }).__timelineSearchBenchmark = {
      samples,
      initialScrollTopPx,
      get handlerDurationMs() {
        return handlerDurationMs
      },
      stop: () => {
        running = false
        document.removeEventListener("input", onInputCapture, { capture: true })
        document.removeEventListener("input", onInput)

        if (frame !== undefined) cancelAnimationFrame(frame)
      },
    }
  }, input)
}

export async function waitForStableTimelineSearch(
  page: Page,
  input: { counter: string; targetPartID: string; timeout: number },
) {
  await page.waitForFunction(
    ({ counter, targetPartID }) => {
      const samples = (window as Window & { __timelineSearchBenchmark?: TimelineSearchProbe }).__timelineSearchBenchmark
        ?.samples

      if (!samples) return false

      return samples.some((_, index) => {
        const stable = samples.slice(index, index + 3)

        if (stable.length !== 3) return false

        return stable.every(
          (sample, sampleIndex) =>
            sample.counter === counter &&
            sample.targetVisible &&
            sample.activeRanges === 1 &&
            sample.activePartID === targetPartID &&
            sample.activeVisible &&
            (sampleIndex === 0 ||
              (Math.abs(sample.scrollTopPx - stable[sampleIndex - 1]!.scrollTopPx) <= 1 &&
                Math.abs((sample.targetTopPx ?? Infinity) - (stable[sampleIndex - 1]!.targetTopPx ?? -Infinity)) <= 1)),
        )
      })
    },
    { counter: input.counter, targetPartID: input.targetPartID },
    { timeout: input.timeout },
  )
}

export async function collectTimelineSearchMetrics(page: Page, input: { counter: string; targetPartID: string }) {
  const result = await page.evaluate(() => {
    const probe = (window as Window & { __timelineSearchBenchmark?: TimelineSearchProbe }).__timelineSearchBenchmark

    if (!probe) throw new Error("missing timeline search benchmark probe")
    probe.stop()

    return {
      samples: probe.samples,
      handlerDurationMs: probe.handlerDurationMs,
      initialScrollTopPx: probe.initialScrollTopPx,
    }
  })

  const first = (predicate: (sample: TimelineSearchSample) => boolean) => result.samples.find(predicate)?.observedAtMs

  const stable = result.samples.findIndex((_, index) => {
    const samples = result.samples.slice(index, index + 3)

    if (samples.length !== 3) return false

    return samples.every(
      (sample, sampleIndex) =>
        sample.counter === input.counter &&
        sample.targetVisible &&
        sample.activeRanges === 1 &&
        sample.activePartID === input.targetPartID &&
        sample.activeVisible &&
        (sampleIndex === 0 ||
          (Math.abs(sample.scrollTopPx - samples[sampleIndex - 1]!.scrollTopPx) <= 1 &&
            Math.abs((sample.targetTopPx ?? Infinity) - (samples[sampleIndex - 1]!.targetTopPx ?? -Infinity)) <= 1)),
    )
  })

  const final = result.samples.at(-1)

  return {
    summary: {
      handlerDurationMs: result.handlerDurationMs,
      firstCountObservedMs: first((sample) => sample.counter === input.counter),
      firstTargetMountedMs: first((sample) => sample.targetMounted),
      firstTargetVisibleMs: first((sample) => sample.targetVisible),
      firstActiveHighlightObservedMs: first(
        (sample) => sample.activeRanges === 1 && sample.activePartID === input.targetPartID && sample.activeVisible,
      ),
      stableResultObservedMs: stable >= 0 ? result.samples[stable + 2]?.observedAtMs : undefined,
      initialScrollTopPx: result.initialScrollTopPx,
      finalScrollTopPx: final?.scrollTopPx,
      scrollDistancePx: final === undefined ? undefined : Math.abs(result.initialScrollTopPx - final.scrollTopPx),
      activeHighlightRanges: final?.activeRanges,
    },
    samples: result.samples,
  }
}

import type { Page } from "@playwright/test"

const STREAM_MARKER_PATTERN = "stream-(\\d+)"

const STREAM_FRAGMENT_COUNT = 18

type TimelineProbeState = {
  started: number
  ended: number
  profileVisual: boolean
  minimal: boolean
  frames: number[]
  frameAt: number[]
  applied: { at: number; index: number }[]
  geometry: {
    scrollTop: number
    scrollHeight: number
    clientHeight: number
    distance: number
    virtualHeight: number
    headerHeight: number
  }[]
  blanks: number
  longTasks: number[]
  layoutShifts: number[]
  visibleMounts: number
  visibleUnmounts: number
  visibleRows: Set<Element>
  visibleSubtreeMounts: string[]
  visibleSubtreeUnmounts: string[]
  visibleSubtreeReplacements: number
  visibleSubtreeDropouts: string[]
  visibleSubtrees: Map<string, Element>
  subtreeKeys: WeakMap<Element, string>
  maxOverlap: number
  maxGap: number
  maxPartTopMovement: number
  previousPartTop: number
  slowFrames: {
    duration: number
    index: number
    phase: "stream" | "boundary" | "complete" | "unknown"
    tokenSpans: number
    blocks: number
    codeBlocks: number
    height: number
    distance: number
  }[]
  scroll: {
    calls: number
    callNoops: number
    sameFrameCalls: number
    assignments: number
    assignmentNoops: number
    lastCallFrame: number
    frame: number
  }
  row: HTMLElement
  markdown: HTMLElement
  running: boolean
  previous: number
  cleanup: () => void
  start: () => void
}

export async function installTimelineStreamProbe(
  page: Page,
  options: { textPartID: string; finalIndex: number; profileVisual: boolean; minimal: boolean },
) {
  await page.evaluate(
    ({ textPartID, finalIndex, profileVisual, minimal, markerPattern, fragmentCount }) => {
      const part = document.querySelector<HTMLElement>(`[data-timeline-part-id="${textPartID}"]`)
      const row = part?.closest<HTMLElement>("[data-timeline-row]")
      const markdown = part?.querySelector<HTMLElement>('[data-component="markdown"]')
      const root = part?.closest<HTMLElement>(".scroll-view__viewport")

      if (!part || !row || !markdown || !root) throw new Error("missing streaming benchmark nodes")
      const viewport = root.getBoundingClientRect()

      const state: TimelineProbeState = {
        started: 0,
        ended: Infinity,
        profileVisual,
        minimal,
        frames: [],
        frameAt: [],
        applied: [],
        geometry: [],
        blanks: 0,
        longTasks: [],
        layoutShifts: [],
        visibleMounts: 0,
        visibleUnmounts: 0,
        visibleRows: new Set(
          [...root.querySelectorAll("[data-timeline-key]")].filter((element) => {
            const rect = element.getBoundingClientRect()

            return rect.bottom > viewport.top && rect.top < viewport.bottom
          }),
        ),
        visibleSubtreeMounts: [],
        visibleSubtreeUnmounts: [],
        visibleSubtreeReplacements: 0,
        visibleSubtreeDropouts: [],
        visibleSubtrees: new Map<string, Element>(),
        subtreeKeys: new WeakMap<Element, string>(),
        maxOverlap: 0,
        maxGap: 0,
        maxPartTopMovement: 0,
        previousPartTop: part.getBoundingClientRect().top,
        slowFrames: [],
        scroll: {
          calls: 0,
          callNoops: 0,
          sameFrameCalls: 0,
          assignments: 0,
          assignmentNoops: 0,
          lastCallFrame: -1,
          frame: 0,
        },
        row,
        markdown,
        running: false,
        previous: 0,
        cleanup: () => {},
        start: () => {},
      }

      ;(window as Window & { __timelineStreamBenchmark?: TimelineProbeState }).__timelineStreamBenchmark = state
      const scrollTo = Element.prototype.scrollTo
      const scrollTop = Object.getOwnPropertyDescriptor(Element.prototype, "scrollTop")!

      if (profileVisual) {
        function measuredScrollTo(this: Element, options?: ScrollToOptions): void
        function measuredScrollTo(this: Element, x: number, y: number): void
        function measuredScrollTo(this: Element, first?: number | ScrollToOptions, second?: number) {
          state.scroll.calls += 1
          const top = typeof first === "object" ? first?.top : second

          if (typeof top === "number") {
            const target = Math.min(top, this.scrollHeight - this.clientHeight)

            if (Math.abs(this.scrollTop - target) < 1) state.scroll.callNoops += 1
          }

          if (state.scroll.lastCallFrame === state.scroll.frame) state.scroll.sameFrameCalls += 1
          state.scroll.lastCallFrame = state.scroll.frame
          scrollTo.apply(this, typeof first === "number" ? [first, second] : [first])
        }

        Element.prototype.scrollTo = measuredScrollTo
        Object.defineProperty(Element.prototype, "scrollTop", {
          configurable: true,
          get: scrollTop.get,
          set(value) {
            state.scroll.assignments += 1

            if (Math.abs(this.scrollTop - value) < 1) state.scroll.assignmentNoops += 1
            scrollTop.set!.call(this, value)
          },
        })
      }

      const recordLongTasks = (entries: PerformanceEntry[]) => {
        if (!state.running) return
        state.longTasks.push(
          ...entries
            .filter((entry) => entry.startTime >= state.started && entry.startTime <= state.ended)
            .map((entry) => entry.duration),
        )
      }

      const longTaskObserver = new PerformanceObserver((list) => recordLongTasks(list.getEntries()))
      longTaskObserver.observe({ type: "longtask" })

      const recordLayoutShifts = (entries: PerformanceEntry[]) => {
        if (!state.running) return
        state.layoutShifts.push(
          ...entries
            .map((entry) => {
              const shift = entry as LayoutShiftEntry

              if (shift.startTime < state.started || shift.hadRecentInput) return

              return shift.value
            })
            .filter((value): value is number => value !== undefined),
        )
      }

      const layoutShiftObserver = profileVisual
        ? new PerformanceObserver((list) => recordLayoutShifts(list.getEntries()))
        : undefined

      layoutShiftObserver?.observe({ type: "layout-shift", buffered: true })

      const visible = (element: Element) => {
        const rect = element.getBoundingClientRect()
        const viewport = root.getBoundingClientRect()
        const style = getComputedStyle(element)

        return (
          element.isConnected &&
          rect.width > 0 &&
          rect.height > 0 &&
          rect.bottom > viewport.top &&
          rect.top < viewport.bottom &&
          style.display !== "none" &&
          style.visibility !== "hidden" &&
          Number(style.opacity) > 0
        )
      }

      const critical = [
        "[data-timeline-part-id]",
        '[data-component="edit-content"]',
        '[data-component="apply-patch-file-diff"]',
        '[data-component="file"]',
        '[data-component="markdown-code"]',
        "[data-markdown-block]",
      ].join(",")

      const describe = (element: Element) => {
        const cached = state.subtreeKeys.get(element)

        if (!element.isConnected && cached) return cached
        const part = element.closest<HTMLElement>("[data-timeline-part-id]")?.dataset.timelinePartId ?? "unknown"

        const block = element
          .closest<HTMLElement>("[data-markdown-key]")
          ?.dataset.markdownKey?.replace(/:(?:code|full|live)$/, "")

        const component =
          element.getAttribute("data-component") ?? element.getAttribute("data-markdown-block") ?? element.tagName

        const key = `${part}:${block ?? "root"}:${component}`
        state.subtreeKeys.set(element, key)

        return key
      }

      const recordMutations = (records: MutationRecord[]) => {
        if (!state.running) return
        records.forEach((record) => {
          record.addedNodes.forEach((node) => {
            if (node instanceof HTMLElement && node.matches("[data-timeline-key]") && visible(node)) {
              state.visibleMounts += 1
              state.visibleRows.add(node)
            }

            if (!(node instanceof Element)) return
            const added = [node, ...node.querySelectorAll(critical)].filter((element) => element.matches(critical))
            added.forEach((element) => {
              if (visible(element)) state.visibleSubtreeMounts.push(describe(element))
            })
          })
          record.removedNodes.forEach((node) => {
            if (node instanceof HTMLElement && node.matches("[data-timeline-key]") && state.visibleRows.delete(node))
              state.visibleUnmounts += 1

            if (!(node instanceof Element)) return
            const removed = [node, ...node.querySelectorAll(critical)].filter((element) => element.matches(critical))
            removed.forEach((element) => {
              const key = describe(element)

              if (state.visibleSubtrees.get(key) === element) state.visibleSubtreeUnmounts.push(key)
            })
          })
        })
      }

      const mutationObserver = profileVisual ? new MutationObserver(recordMutations) : undefined
      mutationObserver?.observe(root, { childList: true, subtree: true })
      const currentPart = () => root.querySelector<HTMLElement>(`[data-timeline-part-id="${textPartID}"]`)

      const observeProgress = (at: number) => {
        if (!state.running) return
        const content = currentPart()?.textContent ?? ""

        const index = content.includes("benchmark-complete")
          ? finalIndex
          : Number(content.match(new RegExp(markerPattern, "g"))?.at(-1)?.match(/\d+/)?.[0] ?? -1)

        if (index >= 0 && index !== state.applied.at(-1)?.index) state.applied.push({ at, index })
      }

      const progressObserver = new MutationObserver(() => observeProgress(performance.now()))
      progressObserver.observe(root, { characterData: true, childList: true, subtree: true })
      state.cleanup = () => {
        recordLongTasks(longTaskObserver.takeRecords())
        recordLayoutShifts(layoutShiftObserver?.takeRecords() ?? [])
        recordMutations(mutationObserver?.takeRecords() ?? [])

        if (progressObserver.takeRecords().length) observeProgress(performance.now())
        longTaskObserver.disconnect()
        layoutShiftObserver?.disconnect()
        mutationObserver?.disconnect()
        progressObserver.disconnect()

        if (!profileVisual) return
        Element.prototype.scrollTo = scrollTo
        Object.defineProperty(Element.prototype, "scrollTop", scrollTop)
      }

      const sample = (now: number) => {
        if (!state.running) return
        state.frameAt.push(now)
        observeProgress(now)

        if (minimal) {
          state.frames.push(now - state.previous)
          state.previous = now
          requestAnimationFrame(sample)

          return
        }

        setTimeout(() => {
          if (!state.running) return
          state.scroll.frame += 1
          const duration = now - state.previous
          state.frames.push(duration)
          state.previous = now
          const virtualRoot = root.querySelector<HTMLElement>("[data-timeline-virtual-content]")
          const header = root.querySelector<HTMLElement>("[data-session-title]")
          state.geometry.push({
            scrollTop: root.scrollTop,
            scrollHeight: root.scrollHeight,
            clientHeight: root.clientHeight,
            distance: root.scrollHeight - root.clientHeight - root.scrollTop,
            virtualHeight: virtualRoot?.getBoundingClientRect().height ?? 0,
            headerHeight: header?.getBoundingClientRect().height ?? 0,
          })
          const viewport = root.getBoundingClientRect()

          if (profileVisual) {
            const visibleRows = [...root.querySelectorAll<HTMLElement>("[data-timeline-key]")]
              .map((element) => ({ element, rect: element.getBoundingClientRect() }))
              .filter((item) => item.rect.bottom > viewport.top && item.rect.top < viewport.bottom)
              .sort((a, b) => a.rect.top - b.rect.top)

            state.visibleRows = new Set(visibleRows.map((item) => item.element))
            const rows = visibleRows.map((item) => item.rect)
            rows.slice(1).forEach((rect, index) => {
              const previous = rows[index]!
              state.maxOverlap = Math.max(state.maxOverlap, previous.bottom - rect.top)
              state.maxGap = Math.max(state.maxGap, rect.top - previous.bottom)
            })
            const partTop = part.getBoundingClientRect().top
            state.maxPartTopMovement = Math.max(state.maxPartTopMovement, Math.abs(partTop - state.previousPartTop))
            state.previousPartTop = partTop
          }

          const visibleRow = [...root.querySelectorAll<HTMLElement>("[data-timeline-row]")].some((element) => {
            const rect = element.getBoundingClientRect()

            return rect.bottom > viewport.top && rect.top < viewport.bottom
          })

          if (!visibleRow) state.blanks += 1

          if (profileVisual) {
            const subtrees = new Map<string, { element: Element; rendered: boolean }>()
            const visibleSubtrees = new Map<string, Element>()
            root.querySelectorAll(critical).forEach((element) => {
              const key = describe(element)
              const rect = element.getBoundingClientRect()
              const style = getComputedStyle(element)

              const rendered =
                element.isConnected &&
                rect.width > 0 &&
                rect.height > 0 &&
                style.display !== "none" &&
                style.visibility !== "hidden" &&
                Number(style.opacity) > 0

              subtrees.set(key, { element, rendered })

              if (rendered && rect.bottom > viewport.top && rect.top < viewport.bottom) {
                const previous = state.visibleSubtrees.get(key)

                if (previous && previous !== element && key.startsWith(`${textPartID}:`))
                  state.visibleSubtreeReplacements += 1
                visibleSubtrees.set(key, element)
              }
            })
            state.visibleSubtrees.forEach((element, key) => {
              const current = subtrees.get(key)

              if (key.startsWith(`${textPartID}:`) && !current?.rendered) {
                const markdown = part.querySelector<HTMLElement>('[data-component="markdown"]')
                state.visibleSubtreeDropouts.push(
                  `${key}:projection=${markdown?.dataset.markdownProjectionLength}/${markdown?.dataset.markdownProjectionBlocks}:result=${markdown?.dataset.markdownResultLength}/${markdown?.dataset.markdownResultBlocks}:applied=${markdown?.dataset.markdownAppliedBlocks}:dom=${markdown?.children.length}`,
                )
              }

              if (element.matches('[data-component="file"]')) {
                const hadLines = element.hasAttribute("data-profiler-had-lines")
                const hasLines = element.shadowRoot?.querySelector("[data-line]") != null

                if (hasLines) element.setAttribute("data-profiler-had-lines", "")

                if (hadLines && !hasLines) state.visibleSubtreeDropouts.push(`${key}:shadow-lines`)
              }
            })
            state.visibleSubtrees = visibleSubtrees
          }

          if (profileVisual && duration > 33.34) {
            const livePart = currentPart()
            const content = livePart?.textContent ?? ""
            const complete = content.includes("benchmark-complete")

            const index = complete
              ? finalIndex
              : Number(content.match(new RegExp(markerPattern, "g"))?.at(-1)?.match(/\d+/)?.[0] ?? -1)

            state.slowFrames.push({
              duration,
              index,
              phase: complete
                ? "complete"
                : index >= 0 && index % fragmentCount === 0
                  ? "boundary"
                  : index >= 0
                    ? "stream"
                    : "unknown",
              tokenSpans: livePart?.querySelectorAll(".shiki span").length ?? 0,
              blocks: livePart?.querySelectorAll("[data-markdown-block]").length ?? 0,
              codeBlocks: livePart?.querySelectorAll('[data-component="markdown-code"]').length ?? 0,
              height: livePart?.getBoundingClientRect().height ?? 0,
              distance: root.scrollHeight - root.clientHeight - root.scrollTop,
            })
          }

          requestAnimationFrame(sample)
        }, 0)
      }

      state.start = () => {
        state.started = performance.now()
        state.previous = state.started
        state.running = true
        requestAnimationFrame(sample)
      }
    },
    { ...options, markerPattern: STREAM_MARKER_PATTERN, fragmentCount: STREAM_FRAGMENT_COUNT },
  )
}

export function startTimelineStreamProbe(page: Page) {
  return page.evaluate(() => {
    const state = (window as Window & { __timelineStreamBenchmark?: TimelineProbeState }).__timelineStreamBenchmark

    if (!state) throw new Error("missing streaming benchmark state")
    state.start()
  })
}

type LayoutShiftEntry = PerformanceEntry & { value: number; hadRecentInput?: boolean }

export function layoutShiftValue(
  entry: Pick<LayoutShiftEntry, "startTime" | "value" | "hadRecentInput">,
  start: number,
) {
  if (entry.startTime < start || entry.hadRecentInput) return

  return entry.value
}

export function removeVisibleRow<T>(visible: Set<T>, row: T) {
  return visible.delete(row)
}

export function streamProgress(content: string) {
  const index = Number(content.match(new RegExp(STREAM_MARKER_PATTERN, "g"))?.at(-1)?.match(/\d+/)?.[0] ?? -1)

  return {
    index,
    phase: content.includes("benchmark-complete")
      ? ("complete" as const)
      : index >= 0 && index % STREAM_FRAGMENT_COUNT === 0
        ? ("boundary" as const)
        : index >= 0
          ? ("stream" as const)
          : ("unknown" as const),
  }
}

export async function collectTimelineStreamMetrics(
  page: Page,
  options: { textPartID: string; finalIndex: number; navigations: string[] },
) {
  return page.evaluate(({ textPartID, finalIndex, navigations }) => {
    const state = (window as Window & { __timelineStreamBenchmark?: TimelineProbeState }).__timelineStreamBenchmark

    if (!state) throw new Error(`missing streaming benchmark state after navigation: ${JSON.stringify(navigations)}`)
    state.ended = performance.now()
    state.cleanup()
    state.running = false
    const part = document.querySelector<HTMLElement>(`[data-timeline-part-id="${textPartID}"]`)
    const row = part?.closest<HTMLElement>("[data-timeline-row]")
    const markdown = part?.querySelector<HTMLElement>('[data-component="markdown"]')
    const sorted = state.frames.slice().sort((a, b) => a - b)
    const duration = state.frames.reduce((sum, value) => sum + value, 0)

    const longestSlowStreak = state.frames.reduce(
      (result, value) => {
        const current = value > 33.34 ? result.current + 1 : 0

        return { current, longest: Math.max(result.longest, current) }
      },
      { current: 0, longest: 0 },
    ).longest

    const busyStart = state.applied.at(0)?.at
    const completion = state.applied.find((value) => value.index === finalIndex)
    const busyEnd = completion?.at

    const busyFrames =
      busyStart === undefined || busyEnd === undefined
        ? []
        : state.frames.filter((_, index) => state.frameAt[index]! >= busyStart && state.frameAt[index]! <= busyEnd)

    const busySorted = busyFrames.slice().sort((a, b) => a - b)
    const busyDuration = busyFrames.reduce((sum, value) => sum + value, 0)
    const completionObservedMs = (completion?.at ?? NaN) - state.started

    const visual = state.profileVisual
      ? {
          layoutShiftValueSum: state.layoutShifts.reduce((sum, value) => sum + value, 0),
          maxLayoutShiftValue: Math.max(0, ...state.layoutShifts),
          visibleMounts: state.visibleMounts,
          visibleUnmounts: state.visibleUnmounts,
          visibleSubtreeMounts: state.visibleSubtreeMounts,
          visibleSubtreeUnmounts: [...new Set(state.visibleSubtreeUnmounts)],
          visibleSubtreeReplacements: state.visibleSubtreeReplacements,
          visibleSubtreeDropouts: [...new Set(state.visibleSubtreeDropouts)],
          maxOverlapPx: state.maxOverlap,
          maxGapPx: state.maxGap,
          maxPartTopMovementPx: state.maxPartTopMovement,
          slowestRafGaps: state.slowFrames
            .sort((a, b) => b.duration - a.duration)
            .slice(0, 20)
            .map((frame) => ({
              durationMs: frame.duration,
              index: frame.index,
              phase: frame.phase,
              tokenSpans: frame.tokenSpans,
              blocks: frame.blocks,
              codeBlocks: frame.codeBlocks,
              heightPx: frame.height,
              distancePx: frame.distance,
            })),
          slowRafGapPhases: Object.fromEntries(
            ["stream", "boundary", "complete", "unknown"].map((phase) => {
              const frames = state.slowFrames.filter((frame) => frame.phase === phase)

              return [
                phase,
                {
                  count: frames.length,
                  totalMs: frames.reduce((sum, frame) => sum + frame.duration, 0),
                  maxMs: Math.max(0, ...frames.map((frame) => frame.duration)),
                },
              ]
            }),
          ),
          scroll: state.scroll,
        }
      : null

    const geometry = state.minimal
      ? null
      : {
          maxDistancePx: Math.max(0, ...state.geometry.map((sample) => sample.distance)),
          finalDistancePx: state.geometry.at(-1)?.distance ?? 0,
          final: state.geometry.at(-1),
          distanceTransitionsPx: state.geometry
            .map((sample) => Math.round(sample.distance))
            .filter((value, index, values) => index === 0 || value !== values[index - 1]),
          bottomDriftTransitions: state.geometry.slice(1).filter((value, index) => {
            const previous = state.geometry[index]?.distance ?? 0

            return previous <= 1 && value.distance > 1
          }).length,
          blankSamples: state.blanks,
        }

    return {
      capabilities: { visual: state.profileVisual, geometry: !state.minimal },
      completionObservedMs,
      deltasPerSecond: Number.isFinite(completionObservedMs) ? finalIndex / (completionObservedMs / 1_000) : null,
      rafGapSamples: state.frames.length,
      rafCallbackRate: duration ? (state.frames.length * 1000) / duration : 0,
      observedProgressWindowRafCallbackRate: busyDuration ? (busyFrames.length * 1000) / busyDuration : null,
      observedProgressWindowRafGapP95Ms: busySorted[Math.floor(busySorted.length * 0.95)] ?? null,
      observedProgressWindowRafGaps: busyFrames.length,
      maxObservedProgressIndex: Math.max(-1, ...state.applied.map((value) => value.index)),
      observedProgressTransitions: state.applied.length,
      rafGapP50Ms: sorted[Math.floor(sorted.length * 0.5)] ?? 0,
      rafGapP95Ms: sorted[Math.floor(sorted.length * 0.95)] ?? 0,
      rafGapP99Ms: sorted[Math.floor(sorted.length * 0.99)] ?? 0,
      maxRafGapMs: sorted.at(-1) ?? 0,
      rafGapsOver33Ms: state.frames.filter((value) => value > 33.34).length,
      rafGapsOver50Ms: state.frames.filter((value) => value > 50).length,
      missedFrameBudgetEquivalents: state.frames.reduce(
        (sum, value) => sum + Math.max(0, Math.round(value / 16.67) - 1),
        0,
      ),
      longestRafGapOver33MsStreak: longestSlowStreak,
      longTaskCount: state.longTasks.length,
      longTaskTimeMs: state.longTasks.reduce((sum, value) => sum + value, 0),
      visual,
      geometry,
      rowReplaced: row !== state.row,
      markdownReplaced: markdown !== state.markdown,
      domTextCharacters: part?.textContent?.length ?? 0,
    }
  }, options)
}

import { createServer, type ServerResponse } from "node:http"
import type { OpenCodeEvent } from "@opencode/client/promise"
import { benchmark, benchmarkDiagnostics, expect } from "../benchmark"
import {
  buildInitialStreamEvent,
  buildStreamDeltaEvents,
  setupTimelineBenchmark,
  textPartID,
} from "./session-timeline-benchmark.fixture"

type Probe = { calls: number; entries: number; ms: number }

type Measurement = { frames: number[]; started: number; ready: number; rowReplacements: number; stop: () => void }

declare global {
  interface Window {
    __timelineProjectionProbe?: Probe
    __projectionMeasurement: Measurement
  }
}

benchmark.use({ traceScope: "interaction" })

for (const scenario of [
  { historyTurns: 40, historyShape: "mixed" },
  { historyTurns: 320, historyShape: "mixed" },
  { historyTurns: 320, historyShape: "tool-heavy" },
] as const) {
  benchmark(`text projection ${scenario.historyTurns} ${scenario.historyShape}`, async ({ page, report }) => {
    benchmark.setTimeout(120_000)
    const responses = new Set<ServerResponse>()

    const source = createServer((request, response) => {
      response.writeHead(200, {
        "content-type": "text/event-stream",
        "access-control-allow-origin": "*",
        "cache-control": "no-cache",
      })
      response.write(
        `data: ${JSON.stringify({ id: "evt_projection_connected", type: "server.connected", data: {} })}\n\n`,
      )
      responses.add(response)
      request.on("close", () => responses.delete(response))
    })

    await new Promise<void>((resolve) => source.listen(0, "127.0.0.1", resolve))
    const address = source.address()

    if (!address || typeof address === "string") throw new Error("Missing fixture SSE address")
    let timer: ReturnType<typeof setInterval> | undefined

    const send = (events: OpenCodeEvent[]) =>
      responses.forEach((response) => events.forEach((event) => response.write(`data: ${JSON.stringify(event)}\n\n`)))

    try {
      await page.addInitScript(
        ({ url, counters }) => {
          Object.assign(window, { __testSseTransport: true })

          if (counters) window.__timelineProjectionProbe = { calls: 0, entries: 0, ms: 0 }
          const fetch = window.fetch.bind(window)

          const intercept = (input: RequestInfo | URL, init?: RequestInit) => {
            const request = new Request(input, init)

            return fetch(
              new URL(request.url).pathname === "/api/event" ? new Request(url, { signal: request.signal }) : request,
            )
          }

          Object.defineProperty(window, "fetch", { configurable: true, writable: true, value: intercept })
        },
        { url: `http://127.0.0.1:${address.port}`, counters: process.env.PROJECTION_COUNTERS === "1" },
      )
      const initialStarted = performance.now()
      const fixture = await setupTimelineBenchmark(page, { ...scenario, busy: true, eventBatch: 1 })
      await expect.poll(() => responses.size).toBe(1)
      const deltas = buildStreamDeltaEvents(160)
      send(buildInitialStreamEvent(160))
      await expect(fixture.text).toContainText("Implementation plan")
      await expect(fixture.text.locator('[data-component="markdown"]')).toHaveAttribute("data-markdown-ready", "")
      const initialReadyMs = performance.now() - initialStarted
      await fixture.scrollToBottom()
      await expect(page.getByRole("button", { name: "Stop", exact: true })).toBeVisible()
      await benchmarkDiagnostics(page).startTrace()
      await page.evaluate(
        ({ partID, counters }) => {
          const part = document.querySelector(`[data-timeline-part-id="${partID}"]`)
          const row = part?.closest("[data-timeline-key]")

          if (!row) throw new Error("Missing active row")

          if (counters) {
            if (!window.__timelineProjectionProbe?.calls)
              throw new Error("Projection instrumentation did not observe initial construction")
            window.__timelineProjectionProbe = { calls: 0, entries: 0, ms: 0 }
          }

          const measurement: Measurement = {
            frames: [],
            started: performance.now(),
            ready: 0,
            rowReplacements: 0,
            stop: () => {},
          }

          window.__projectionMeasurement = measurement
          let previous: number | undefined
          let frame = 0
          let current = row

          const sample = (now: number) => {
            if (previous !== undefined) measurement.frames.push(now - previous)
            previous = now
            const next = document.querySelector(`[data-timeline-part-id="${partID}"]`)?.closest("[data-timeline-key]")

            if (next && next !== current) {
              measurement.rowReplacements++
              current = next
            }

            const markdown = next?.querySelector('[data-component="markdown"][data-markdown-ready]')

            if (markdown?.textContent?.includes("benchmark-complete")) {
              measurement.ready = performance.now() - measurement.started

              return
            }

            frame = requestAnimationFrame(sample)
          }

          measurement.stop = () => cancelAnimationFrame(frame)
          frame = requestAnimationFrame(sample)
        },
        { partID: textPartID, counters: process.env.PROJECTION_COUNTERS === "1" },
      )
      const emitted: number[] = []
      const started = performance.now()
      // The source clock runs in Node, never waiting for a renderer acknowledgement.
      await new Promise<void>((resolve) => {
        timer = setInterval(() => {
          const event = deltas[emitted.length]

          if (!event) throw new Error("Unexpected source overrun")
          send([event])
          emitted.push(performance.now() - started)

          if (emitted.length !== deltas.length) return
          clearInterval(timer)
          resolve()
        }, 25)
      })
      await expect(fixture.text).toContainText("benchmark-complete")
      await expect(fixture.text.locator('[data-component="markdown"]')).toHaveAttribute("data-markdown-ready", "")
      await page.waitForFunction(() => window.__projectionMeasurement.ready > 0)

      const metrics = await page.evaluate(() => {
        const data = window.__projectionMeasurement
        data.stop()

        return {
          frames: data.frames,
          readyMs: data.ready,
          rowReplacements: data.rowReplacements,
          projection: window.__timelineProjectionProbe ?? null,
        }
      })

      expect(emitted).toHaveLength(160)
      expect(metrics.frames.length).toBeGreaterThan(0)
      await benchmarkDiagnostics(page).stop()
      report(
        { ...metrics, initialReadyMs, emitted },
        {
          ...scenario,
          ...fixture.workload,
          deltaBytes: Buffer.byteLength(JSON.stringify(deltas)),
          counters: process.env.PROJECTION_COUNTERS === "1",
          intervalMs: 25,
          deltas: 160,
          viewport: "1366x768",
          revision: process.env.PROJECTION_REVISION,
        },
      )

      if (process.env.PROJECTION_SCREENSHOT)
        await page.screenshot({
          path: `${process.env.PROJECTION_SCREENSHOT}-${scenario.historyTurns}-${scenario.historyShape}.png`,
        })
    } finally {
      clearInterval(timer)
      source.closeAllConnections()
      await new Promise<void>((resolve, reject) => source.close((error) => (error ? reject(error) : resolve())))
    }
  })
}

export function createReviewDiffs() {
  return Array.from({ length: Number(process.env.REVIEW_PANE_DIFF_COUNT ?? 72) }, (_, index) => {
    const lines = index % 3 === 0 ? 300 : index % 3 === 1 ? 120 : 38
    const file = `src/review/generated-${String(index).padStart(3, "0")}.ts`
    const before = reviewSource(index, lines)

    const after = before
      .replace(`value_${index}_4`, `updated_${index}_4`)
      .replace(
        `value_${index}_${Math.max(8, Math.floor(lines / 2))}`,
        `updated_${index}_${Math.max(8, Math.floor(lines / 2))}`,
      )
      .replace(`value_${index}_${lines - 4}`, `updated_${index}_${lines - 4}`)

    return {
      file,
      patch: reviewPatch(file, before, after),
      additions: 3,
      deletions: 3,
      status: "modified" as const,
    }
  })
}

function reviewSource(seed: number, lines: number) {
  return Array.from(
    { length: lines },
    (_, index) => `export const value_${seed}_${index} = "${reviewWords(seed + index, index % 5 === 0 ? 180 : 42)}"`,
  ).join("\n")
}

function reviewPatch(file: string, before: string, after: string) {
  const beforeLines = before.split("\n")
  const afterLines = after.split("\n")

  return [
    `diff --git a/${file} b/${file}`,
    `--- a/${file}`,
    `+++ b/${file}`,
    `@@ -1,${beforeLines.length} +1,${afterLines.length} @@`,
    ...beforeLines.flatMap((line, index) => {
      const next = afterLines[index]!

      if (line === next) return [` ${line}`]

      return [`-${line}`, `+${next}`]
    }),
  ].join("\n")
}

function reviewWords(seed: number, length: number) {
  const words = ["alpha", "bravo", "charlie", "delta", "echo", "foxtrot", "golf", "hotel", "india", "juliet"]

  return Array.from({ length: Math.ceil(length / 7) }, (_, index) => words[(seed + index * 3) % words.length]).join(" ")
}

