}

function currentModels(catalog: MockProviderCatalog) {
  return (catalog.all ?? [])
    .flatMap((item) => Option.toArray(decodeModelProvider(item)))
    .flatMap((provider) =>
      Object.values(provider.models)
        .flatMap((item) => Option.toArray(decodeModel(item)))
        .map((model) => ({
