import { MemoryRouter, createMemoryHistory } from "@solidjs/router"
import { createMemo, Show } from "solid-js"
import { createStore, unwrap } from "solid-js/store"
import { render } from "solid-js/web"
import type { Bridge, BridgeMessage } from "@opencode/gui-extensions/sdk/bridge"
import type { SshItem, SshState } from "../../../gui-extensions/src/ssh/contract"
import type { WslServerRuntime, WslServersState } from "../../../gui-extensions/src/wsl/contract"
import { AppBaseProviders, AppInterface } from "../../src/app"
import { PlatformProvider, type Platform } from "../../src/runtime/platform/platform"
import { ServerConnection } from "../../src/runtime/server/registry"
import { useExtensionServers } from "../../src/runtime/extension/servers"

/** The input of a WSL or SSH method this fixture answers. */
type FixtureInput = { id?: string; name?: string }

/** A main-side method: SSH `start` answers with the state revision, the others with nothing. */
type FixtureMethod = (input: FixtureInput) => number | void

// A desktop window. `wsl` is the Ubuntu server's endpoint (default `server`); updating OpenCode restarts it on `restart`
// (default `wsl`). `ssh` adds a saved SSH server `box`, ready on that endpoint with password `ssh-1`; each connect
// brings up a new remote server with the next password (`ssh-2`, ...). `storage=async` stores in localStorage behind
// asynchronous reads like the desktop app's; reads of keys containing `hold` wait for "Load held storage".
export function mount(input: {
  server: string
  mode: "failed" | "stopped" | "ready"
  wsl?: string | null
  restart?: string | null
  path?: string | null
  ssh?: string | null
  storage?: string | null
  hold?: string | null
  /** Enables the updater Ipc; check and install reject with this message, which may be empty. */
  updater?: string | null
}) {
  const root = document.getElementById("root")

  if (!root) throw new Error("Missing fixture root")
  const history = createMemoryHistory()
  history.set({ value: input.path ?? "/settings", replace: true, scroll: false })
  const endpoint = { url: input.wsl ?? input.server }
  const ready = () => ({ kind: "ready" as const, url: endpoint.url, password: null })
  const held = Promise.withResolvers<void>()

  const storage = (name?: string) => {
    const item = (key: string) => (name ? `${name}:${key}` : key)

    return {
      getItem: async (key: string) => {
        if (input.hold && key.includes(input.hold)) await held.promise

        return localStorage.getItem(item(key))
      },
      setItem: async (key: string, value: string) => localStorage.setItem(item(key), value),
      removeItem: async (key: string) => localStorage.removeItem(item(key)),
    }
  }

  render(() => {
    const [store, setStore] = createStore<{
      calls: string[]
      connects: number
      available: boolean
      state: WslServersState
      ssh: SshState
    }>({
      calls: [],
      connects: 0,
      available: true,
      ssh: {
        revision: 0,
        servers: input.ssh
          ? [
              {
                config: { id: "box", target: "box", name: "box" },
                saved: true,
                stage: "ready",
                http: { url: input.ssh, password: "ssh-1" },
                detail: "",
              },
            ]
          : [],
      },
      state: {
        runtime: { available: true, version: "2", error: null },
        installed: [],
        online: [],
        distroProbes: {},
        pendingRestart: false,
        job: null,
        servers: [
          {
            config: { id: "wsl:Ubuntu", distro: "Ubuntu" },
            runtime: (
              {
                ready: ready(),
                failed: { kind: "failed", message: "WSL failed to start" },
                stopped: { kind: "stopped" },
              } satisfies Record<typeof input.mode, WslServerRuntime>
            )[input.mode],
          },
        ],
        opencodeChecks: {
          Ubuntu: {
            distro: "Ubuntu",
            resolvedPath: "/usr/bin/opencode",
            version: "old",
            expectedVersion: "current",
            matchesDesktop: false,
            error: null,
          },
        },
      },
    })

    // The main-process WSL and SSH extensions, as the extension bridge sees them.
    const listeners = new Set<(message: BridgeMessage) => void>()
    const snapshot = (ipc: string) => structuredClone(unwrap(ipc === "ssh" ? store.ssh : store.state))

    const publish = (ipc: string) =>
      listeners.forEach((listener) => listener({ type: "state", ipc, state: snapshot(ipc) }))

    // The contract state is deeply readonly, so each action replaces the changed branch.
    const setRuntime = (id: string | undefined, runtime: WslServerRuntime) =>
      setStore("state", (state) => ({
        servers: state.servers.map((server) => (server.config.id === id ? { ...server, runtime } : server)),
      }))

    const setSsh = (item: Partial<SshItem>) =>
      setStore("ssh", (state) => ({
        revision: state.revision + 1,
        servers: state.servers.map((server) => ({ ...server, ...item })),
      }))

    const wsl = {
      // Like main: stops the distro's server, updates OpenCode, then starts the server again on a new endpoint.
      installOpencode(value) {
        const name = value.name ?? ""
        const id = store.state.servers.find((server) => server.config.distro === name)?.config.id
        setStore("calls", (calls) => [...calls, `update:${value.name}`])
        setRuntime(id, { kind: "stopped" })
        publish("wsl")
        setStore("state", (state) => ({
          opencodeChecks: {
            ...state.opencodeChecks,
            [name]: { ...state.opencodeChecks[name]!, version: "current", matchesDesktop: true },
          },
        }))
        endpoint.url = input.restart ?? endpoint.url
        setRuntime(id, ready())
      },
      startServer(value) {
        setStore("calls", (calls) => [...calls, `start:${value.id}`])
        setRuntime(value.id, ready())
      },
      removeServer(value) {
        setStore("calls", (calls) => [...calls, `remove:${value.id}`])
        setStore("state", (state) => ({ servers: state.servers.filter((server) => server.config.id !== value.id) }))
      },
    } satisfies Readonly<Record<string, FixtureMethod>>

    const ssh = {
      // Like main: a connect opens a new tunnel to a remote server with a new password.
      start() {
        setStore("connects", (count) => count + 1)
        setSsh({ stage: "ready", http: { url: input.ssh ?? "", password: `ssh-${store.connects + 1}` } })

        return store.ssh.revision
      },
    } satisfies Readonly<Record<string, FixtureMethod>>

    const methods = new Map<string, Readonly<Record<string, FixtureMethod>>>([
      ["wsl", wsl],
      ["ssh", ssh],
    ])

    const bridge: Bridge = {
      packaged: false,
      async call(request) {
        if (request.ipc === "updater" && input.updater != null) throw new Error(input.updater)
        const method = methods.get(request.ipc)?.[request.method]

        if (!method) throw new Error("Unexpected fixture action")
        // SAFETY: every WSL and SSH method the fixture answers takes a struct of these optional string fields.
        const result = method(request.input as FixtureInput)
        publish(request.ipc)

        return result ?? null
      },
      async subscribe(ipc) {
        if (ipc === "updater" && input.updater != null) return { available: true, state: { status: "idle" } }

        if (ipc === "wsl" || ipc === "ssh") return { available: true, state: snapshot(ipc) }

        return { available: false }
      },
      on(listener) {
        listeners.add(listener)

        return () => listeners.delete(listener)
      },
      embed: () => undefined,
      capture: async () => undefined,
      runMenubarItem: () => undefined,
      configure: () => undefined,
      manager: {
        list: async () => [],
        enable: async () => undefined,
        disable: async () => undefined,
        reload: async () => undefined,
        install: async () => undefined,
        remove: async () => undefined,
        source: async () => "",
        asset: () => "",
      },
    }

    const unused = async () => {
      throw new Error("Unexpected fixture action")
    }

    const platform: Platform = {
      platform: "desktop",
      os: "windows",
      windowID: "settings-wsl-test",
      openExternal: () => undefined,
      openDirectoryPickerDialog: async () => null,
      notify: async () => undefined,
      restart: unused,
      extensions: bridge,
    }

    if (input.storage === "async") platform.storage = storage

    function Interface() {
      const extensions = useExtensionServers()

      const servers = createMemo<ServerConnection.Any[]>(() => [
        { type: "sidecar", variant: "base", displayName: "Local Server", http: { url: input.server } },
        ...extensions.list(),
      ])

      return (
        <Show when={extensions.ready()}>
          <AppInterface servers={servers()} router={(props) => <MemoryRouter {...props} history={history} />} />
        </Show>
      )
    }

    return (
      <PlatformProvider value={platform}>
        <AppBaseProviders locale="en">
          <output aria-label="WSL actions">{store.calls.join(",")}</output>
          {/* The WSL extension's main side going away, as on a reload or failure, and coming back. */}
          <label>
            <input
              type="checkbox"
              checked={store.available}
              onChange={(event) => {
                const available = event.currentTarget.checked
                setStore("available", available)
                listeners.forEach((listener) => listener({ type: "available", ipc: "wsl", available }))

                if (available) publish("wsl")
              }}
            />
            WSL extension
          </label>
          {/* The SSH extension's main side going away and coming back. */}
          <label>
            <input
              type="checkbox"
              checked
              onChange={(event) => {
                const available = event.currentTarget.checked
                listeners.forEach((listener) => listener({ type: "available", ipc: "ssh", available }))

                if (available) publish("ssh")
              }}
            />
            SSH extension
          </label>
          {/* The SSH tunnel dropping, which only main notices. */}
          <Show when={input.ssh}>
            <button
              type="button"
              onClick={() => {
                setSsh({ stage: "disconnected" })
                publish("ssh")
              }}
            >
              Drop SSH tunnel
            </button>
            {/* A background reconnect that needs a password, as main reports it to every window. */}
            <button
              type="button"
              onClick={() => {
                setSsh({ stage: "authentication" })
                publish("ssh")
              }}
            >
              Require SSH sign-in
            </button>
            <output aria-label="SSH connects">{store.connects}</output>
          </Show>
          <Show when={input.hold}>
            <button type="button" onClick={() => held.resolve()}>
              Load held storage
            </button>
          </Show>
          <Interface />
        </AppBaseProviders>
      </PlatformProvider>
    )
  }, root)
}

import type { Page } from "@playwright/test"
import type { OpenCodeEvent } from "@opencode/client/promise"

export type SseConnectionRecord = {
  id: number
  url: string
  path: "/api/event"
  headers: Record<string, string>
  openedAt: number
  endedAt?: number
  endedBy?: "close" | "disconnect" | "error" | "abort"
  error?: string
}

export type SseDeliveryAcknowledgement = {
  deliveryID: number
  connectionID: number
  bytes: number
  chunkCount: number
  deliveredAt: number
  eventID?: string
}

export type SseEventOptions = {
  id?: string
  event?: string
  retry?: number
  marker?: string
}

export type SseTransport<T extends OpenCodeEvent> = {
  server: string
  waitForConnection(options?: { after?: number; timeout?: number }): Promise<SseConnectionRecord>
  send(payload: T, options?: SseEventOptions): Promise<SseDeliveryAcknowledgement>
  burst(payloads: readonly T[], options?: readonly SseEventOptions[]): Promise<SseDeliveryAcknowledgement[]>
  split(payload: T, cuts: readonly number[], options?: SseEventOptions): Promise<SseDeliveryAcknowledgement>
  heartbeat(options?: SseEventOptions): Promise<SseDeliveryAcknowledgement>
  writeRaw(value: string | Uint8Array, cuts?: readonly number[], marker?: string): Promise<SseDeliveryAcknowledgement>
  close(): Promise<void>
  disconnect(message?: string): Promise<void>
  error(message?: string): Promise<void>
  connections(): Promise<SseConnectionRecord[]>
  acknowledgements(): Promise<SseDeliveryAcknowledgement[]>
}

type BrowserCommand<T> =
  | { type: "send"; deliveries: { payload: T; options?: SseEventOptions }[]; burst: boolean; cuts?: number[] }
  | { type: "raw"; bytes: number[]; cuts?: number[]; marker?: string }
  | { type: "end"; mode: "close" | "disconnect" | "error"; message?: string }
  | { type: "connections" }
  | { type: "acknowledgements" }

// Keyed by server origin so every installed server keeps its own connections and commands.
type BrowserTransport = Window & {
  __testSseTransports?: Record<string, { command: (command: BrowserCommand<unknown>) => unknown }>
}

// `keepalive` (default true) writes an SSE comment every 15 s like the real server, so long scenarios do not trip the
// client's stall watchdog. Set it to false only to test that watchdog.
export async function installSseTransport<T extends OpenCodeEvent = OpenCodeEvent>(
  page: Page,
  options: { server: string; retry?: number; keepalive?: boolean },
): Promise<SseTransport<T>> {
  const server = new URL(options.server).origin
  await page.addInitScript(
    ({ server, retry, keepalive }) => {
      type Connection = SseConnectionRecord & { controller: ReadableStreamDefaultController<Uint8Array> }

      type ProbeWindow = Window & {
        __visualStabilityProbe?: { startedAt: number; markers: { at: number; label: string }[] }
      }

      const originalFetch = window.fetch.bind(window)
      const connections: Connection[] = []
      const acknowledgements: SseDeliveryAcknowledgement[] = []
      const encoder = new TextEncoder()
      const keepalives = new Map<number, ReturnType<typeof setInterval>>()

      const stopKeepalive = (id: number) => {
        clearInterval(keepalives.get(id))
        keepalives.delete(id)
      }

      let nextConnectionID = 0
      let nextDeliveryID = 0

      const current = () => connections.findLast((connection) => connection.endedAt === undefined)

      const chunks = (bytes: Uint8Array, cuts?: readonly number[]) => {
        const boundaries = [...new Set(cuts ?? [])]
          .filter((cut) => Number.isInteger(cut) && cut > 0 && cut < bytes.byteLength)
          .sort((a, b) => a - b)

        return [0, ...boundaries].map((start, index) => bytes.slice(start, boundaries[index] ?? bytes.byteLength))
      }

      const marker = (label?: string) => {
        if (!label) return
        const probe = (window as ProbeWindow).__visualStabilityProbe

        if (!probe) return
        probe.markers.push({ at: performance.now() - probe.startedAt, label })
      }

      const frame = (payload: unknown, eventOptions: SseEventOptions = {}) =>
        [
          eventOptions.event === undefined ? "" : `event: ${eventOptions.event}\n`,
          eventOptions.id === undefined ? "" : `id: ${eventOptions.id}\n`,
          eventOptions.retry === undefined ? "" : `retry: ${eventOptions.retry}\n`,
          `data: ${JSON.stringify(payload)}\n\n`,
        ].join("")

      const acknowledge = (
        connection: Connection,
        bytes: number,
        chunkCount: number,
        eventID?: string,
      ): SseDeliveryAcknowledgement => {
        const acknowledgement = {
          deliveryID: ++nextDeliveryID,
          connectionID: connection.id,
          bytes,
          chunkCount,
          deliveredAt: performance.now(),
          ...(eventID === undefined ? {} : { eventID }),
        }

        acknowledgements.push(acknowledgement)

        return acknowledgement
      }

      const end = (mode: "close" | "disconnect" | "error", message?: string) => {
        const connection = current()

        if (!connection) throw new Error("SSE transport has no active connection")
        stopKeepalive(connection.id)
        connection.endedAt = performance.now()
        connection.endedBy = mode

        if (message) connection.error = message

        if (mode === "close") {
          connection.controller.close()

          return
        }

        const error = new DOMException(
          message ?? "SSE connection disconnected",
          mode === "error" ? "Error" : "NetworkError",
        )

        connection.controller.error(error)
      }

      const command = (input: BrowserCommand<unknown>) => {
        if (input.type === "connections")
          return connections.map(({ controller: _controller, ...connection }) => connection)

        if (input.type === "acknowledgements") return acknowledgements

        if (input.type === "end") return end(input.mode, input.message)
        const connection = current()

        if (!connection) throw new Error("SSE transport has no active connection")

        if (input.type === "raw") {
          marker(input.marker)
          const output = chunks(new Uint8Array(input.bytes), input.cuts)
          output.forEach((chunk) => connection.controller.enqueue(chunk))

          return acknowledge(connection, input.bytes.length, output.length)
        }

        const encoded = input.deliveries.map((delivery) => ({
          delivery,
          payload: delivery.payload,
          bytes: encoder.encode(frame(delivery.payload, delivery.options)),
        }))

        encoded.forEach((item) => marker(item.delivery.options?.marker))

        if (input.burst) {
          const bytes = encoder.encode(encoded.map((item) => new TextDecoder().decode(item.bytes)).join(""))
          connection.controller.enqueue(bytes)

          return encoded.map((item) => acknowledge(connection, item.bytes.byteLength, 1, item.delivery.options?.id))
        }

        const output = chunks(encoded[0]!.bytes, input.cuts)
        output.forEach((chunk) => connection.controller.enqueue(chunk))

        return acknowledge(connection, encoded[0]!.bytes.byteLength, output.length, encoded[0]!.delivery.options?.id)
      }

      const host = window as BrowserTransport
      host.__testSseTransports = { ...host.__testSseTransports, [server]: { command } }

      const fetch = (input: RequestInfo | URL, init?: RequestInit) => {
        const request = new Request(input, init)
        const url = new URL(request.url)

        if (url.origin !== server || url.pathname !== "/api/event") return originalFetch(request)

        const id = ++nextConnectionID

        const record = {
          id,
          url: url.href,
          path: url.pathname,
          headers: Object.fromEntries(request.headers.entries()),
          openedAt: performance.now(),
        } as Connection

        const stream = new ReadableStream<Uint8Array>({
          start(controller) {
            record.controller = controller
            connections.push(record)

            if (retry !== undefined) controller.enqueue(encoder.encode(`retry: ${retry}\n\n`))
            controller.enqueue(
              encoder.encode(frame({ id: `evt_mock_connected_${id}`, type: "server.connected", data: {} })),
            )

            if (keepalive)
              keepalives.set(
                id,
                setInterval(() => controller.enqueue(encoder.encode(": keepalive\n\n")), 15_000),
              )
            request.signal.addEventListener(
              "abort",
              () => {
                if (record.endedAt !== undefined) return
                stopKeepalive(id)
                record.endedAt = performance.now()
                record.endedBy = "abort"
                controller.error(request.signal.reason ?? new DOMException("The operation was aborted", "AbortError"))
              },
              { once: true },
            )
          },
          cancel() {
            stopKeepalive(id)

            if (record.endedAt !== undefined) return
            record.endedAt = performance.now()
            record.endedBy = "disconnect"
          },
        })

        return Promise.resolve(
          new Response(stream, {
            status: 200,
            headers: {
              "cache-control": "no-cache",
              "content-type": "text/event-stream",
            },
          }),
        )
      }

      Object.defineProperty(window, "fetch", { configurable: true, writable: true, value: fetch })
    },
    { server, retry: options.retry, keepalive: options.keepalive !== false },
  )

  const command = <Result>(input: BrowserCommand<T>) =>
    page.evaluate(
      ({ server, input }) => {
        const transport = (window as BrowserTransport).__testSseTransports?.[server]

        if (!transport) throw new Error(`SSE transport for ${server} was not installed before page load`)

        return transport.command(input as BrowserCommand<unknown>)
      },
      { server, input },
    ) as Promise<Result>

  return {
    server,
    async waitForConnection(input = {}) {
      const connection = await page.waitForFunction(
        ({ server, after }) => {
          const transport = (window as BrowserTransport).__testSseTransports?.[server]
          const connections = transport?.command({ type: "connections" }) as SseConnectionRecord[] | undefined

          return connections?.findLast((connection) => connection.id > after && connection.endedAt === undefined)
        },
        { server, after: input.after ?? 0 },
        { timeout: input.timeout },
      )

      let result: SseConnectionRecord | undefined

      try {
        result = await connection.jsonValue()
      } finally {
        await connection.dispose()
      }

      if (!result) throw new Error("SSE transport connection disappeared while waiting")

      return result
    },
    send(payload, eventOptions) {
      return command({ type: "send", deliveries: [{ payload, options: eventOptions }], burst: false })
    },
    burst(payloads, eventOptions = []) {
      return command({
        type: "send",
        deliveries: payloads.map((payload, index) => ({ payload, options: eventOptions[index] })),
        burst: true,
      })
    },
    split(payload, cuts, eventOptions) {
      return command({ type: "send", deliveries: [{ payload, options: eventOptions }], burst: false, cuts: [...cuts] })
    },
    heartbeat(eventOptions) {
      const bytes = new TextEncoder().encode(": heartbeat\n\n")

      return command({
        type: "raw",
        bytes: Array.from(bytes),
        marker: eventOptions?.marker,
      })
    },
    writeRaw(value, cuts, marker) {
      return command({
        type: "raw",
        bytes: Array.from(typeof value === "string" ? new TextEncoder().encode(value) : value),
        cuts: cuts ? [...cuts] : undefined,
        marker,
      })
    },
    close() {
      return command({ type: "end", mode: "close" })
    },
    disconnect(message) {
      return command({ type: "end", mode: "disconnect", message })
    },
    error(message) {
      return command({ type: "end", mode: "error", message })
    },
    connections() {
      return command({ type: "connections" })
    },
    acknowledgements() {
      return command({ type: "acknowledgements" })
    },
  }
}

import type {
  JsonValue,
  OpenCodeEvent,
  SessionInfo,
  SessionMessageAssistant,
  SessionMessageInfo,
  SessionMessageUser,
  SessionStatus,
  SessionStructuredError,
} from "@opencode/client/promise"
import { EventManifest } from "@opencode/schema/event-manifest"
import { SessionMessage } from "@opencode/schema/session-message"
import type { TimelineDetail } from "@opencode/session-ui/timeline/detail"
import { expect, test, type Page, type TestInfo } from "@playwright/test"
import { Schema } from "effect"
import { SERVER, seed, sessionHref } from "./app"
import { mockOpenCodeServer, type MockServerConfig } from "./mock-server"
import { installSseTransport } from "./sse-transport"
import { expectSessionReady } from "./waits"

export const directory = "C:/OpenCode/TimelineStability"

export const projectID = "proj_timeline_stability"

export const sessionID = "ses_timeline_stability"

export const userID = "msg_1000_timeline_user"

export const assistantID = "msg_1001_timeline_assistant"

export const title = "Timeline visual stability"

export const model = { providerID: "opencode", modelID: "claude-opus-4-6", variant: "max" }

const tokens = { input: 100, output: 200, reasoning: 0, cache: { read: 0, write: 0 } }

type Session = SessionInfo

type TextSeed = {
  id: string
  type: "text"
  text: string
  messageID?: string
}

type FileSeed = {
  id: string
  type: "file"
  mime: string
  filename?: string
  url: string
  source?: { type: string; path?: string; text?: { value: string; start: number; end: number } }
}

type AgentSeed = {
  id: string
  type: "agent"
  name: string
  source?: { value: string; start: number; end: number }
}

type ReasoningSeed = {
  id: string
  type: "reasoning"
  text: string
  time?: { start: number; end?: number }
  metadata?: Record<string, unknown>
  messageID?: string
}

type ToolSeed = {
  id: string
  type: "tool"
  name: string
  messageID?: string
  executed?: boolean
  providerState?: Record<string, unknown>
  providerResultState?: Record<string, unknown>
  state:
    | { status: "streaming"; input: Record<string, unknown>; raw: string }
    | {
        status: "running"
        input: Record<string, unknown>
        output?: string
        title?: string
        metadata: Record<string, unknown>
        time: { start: number }
      }
    | {
        status: "completed"
        input: Record<string, unknown>
        output: string
        title: string
        metadata: Record<string, unknown>
        time: { start: number; end: number }
      }
    | {
        status: "error"
        input: Record<string, unknown>
        error: string
        metadata: Record<string, unknown>
        time: { start: number; end: number }
      }
}

// Mock server hooks a timeline scenario may add; the fixture owns directory, project, provider, and history.
type TimelineServerInput = Partial<
  Pick<
    MockServerConfig,
    | "inbox"
    | "forms"
    | "permissions"
    | "sessionPermissions"
    | "onPrompt"
    | "onInboxChange"
    | "beforeMessagesResponse"
    | "onMessages"
    | "onMessage"
    | "message"
    | "pageMessages"
    | "onRevertStage"
    | "vcsDiff"
    | "fileList"
    | "fileContent"
    | "findFiles"
    | "pty"
    | "keepalive"
    | "onPermissionReply"
    | "shellCommands"
    | "shellOutput"
  >
>

export type TimelineMessage = SessionMessageUser | SessionMessageAssistant

export type TimelineEvent = OpenCodeEvent | readonly OpenCodeEvent[]

export type EventPayload = OpenCodeEvent

export type ToolStatus = ToolSeed["state"]["status"]

export type PartSeed<Owner extends "user" | "assistant"> = Owner extends "user"
  ? TextSeed | FileSeed | AgentSeed
  : TextSeed | ReasoningSeed | ToolSeed

type ToolOptions<State extends ToolStatus> = State extends "streaming"
  ? { output?: never; title?: never; metadata?: never; error?: never }
  : State extends "running"
    ? { title?: string; metadata?: Record<string, unknown>; output?: string; error?: never }
    : State extends "error"
      ? { error?: string; metadata?: Record<string, unknown>; output?: never; title?: never }
      : { output?: string; title?: string; metadata?: Record<string, unknown>; error?: never }

type PartRef = { messageID: string; type: "text" | "reasoning" | "tool"; ordinal?: number }

type TimelineState = {
  partRefs: Map<string, PartRef>
  nextOrdinals: Map<string, { text: number; reasoning: number }>
  startedParts: Set<string>
  toolStates: Map<string, ToolStatus>
  eventSequence: number
  durableSequence: number
}

// Builder state is owned by the running test attempt. Builders called outside a test (module scope, bun unit tests)
// share the module state, and each test attempt starts from a copy of it.
const moduleState: TimelineState = {
  partRefs: new Map(),
  nextOrdinals: new Map(),
  startedParts: new Set(),
  toolStates: new Map(),
  eventSequence: 0,
  durableSequence: -1,
}

const testStates = new WeakMap<TestInfo, TimelineState>()

function scenario() {
  const info = runningTest()

  if (!info) return moduleState
  const existing = testStates.get(info)

  if (existing) return existing

  const created: TimelineState = {
    partRefs: new Map(moduleState.partRefs),
    nextOrdinals: new Map([...moduleState.nextOrdinals].map(([id, next]) => [id, { ...next }])),
    startedParts: new Set(moduleState.startedParts),
    toolStates: new Map(moduleState.toolStates),
    eventSequence: moduleState.eventSequence,
    durableSequence: moduleState.durableSequence,
  }

  testStates.set(info, created)

  return created
}

function runningTest() {
  // Playwright offers no non-throwing check for a running test.
  try {
    return test.info()
  } catch {
    return undefined
  }
}

export async function setupTimeline(
  page: Page,
  input: {
    messages?: TimelineMessage[]
    sessionMessages?: SessionMessageInfo[]
    sessionStatus?: Record<string, SessionStatus>
    settings?: Record<string, boolean | TimelineDetail>
    sessions?: Session[]
    cpuRate?: number
    viewport?: { width: number; height: number }
    eventRetry?: number
    reducedMotion?: boolean
    locale?: string
    deviceScaleFactor?: number
    seedHistory?: boolean
    // Session IDs to open as titlebar tabs.
    tabs?: string[]
  } & TimelineServerInput = {},
) {
  const state = scenario()
  state.eventSequence = 0
  state.durableSequence = -1
  const sessions = input.sessions ?? [session()]

  const messages =
    input.sessionMessages ??
    validateTimelineMessages([
      ...(input.seedHistory ? historyMessages(18) : []),
      ...(input.messages ?? [userMessage(), assistantMessage()]),
    ])

  const active = messages.findLast((message) => message.type === "assistant")

  const initialStatus: SessionStatus =
    active?.type === "assistant" && active.time.completed === undefined ? { type: "busy" } : { type: "idle" }

  const transport = await installSseTransport(page, {
    server: SERVER,
    retry: input.eventRetry ?? 20,
    keepalive: input.keepalive,
  })

  const mock = await mockOpenCodeServer(page, {
    ...input,
    directory,
    project: project(),
    provider: provider(),
    sessions,
    sessionStatus: input.sessionStatus ?? { [sessionID]: initialStatus },
    pageMessages: input.pageMessages ?? (() => ({ items: messages })),
  })

  if (input.tabs) await seed(page, { tabs: input.tabs })
  await page.addInitScript((settings) => {
    localStorage.setItem(
      "settings.v3",
      JSON.stringify({
        general: {
          editToolPartsExpanded: false,
          shellToolPartsExpanded: false,
          showReasoningSummaries: false,
          showSessionProgressBar: true,
          ...settings,
        },
      }),
    )
  }, input.settings ?? {})

  if (input.locale) {
    await page.addInitScript((locale) => {
      localStorage.setItem("opencode.global.dat:language", JSON.stringify({ locale }))
    }, input.locale)
  }

  if (input.reducedMotion) await page.emulateMedia({ reducedMotion: "reduce" })
  await page.setViewportSize(input.viewport ?? { width: 1400, height: 900 })

  if (input.deviceScaleFactor) {
    const devtools = await page.context().newCDPSession(page)
    const viewport = input.viewport ?? { width: 1400, height: 900 }
    await devtools.send("Emulation.setDeviceMetricsOverride", {
      width: viewport.width,
      height: viewport.height,
      deviceScaleFactor: input.deviceScaleFactor,
      mobile: false,
    })
  }

  await page.goto(sessionHref(sessionID))
  await expectSessionReady(page, { server: SERVER, sessionID, title })
  await transport.waitForConnection()

  if (input.cpuRate && input.cpuRate > 1) {
    const devtools = await page.context().newCDPSession(page)
    await devtools.send("Emulation.setCPUThrottlingRate", { rate: input.cpuRate })
  }

  // `delay` and `sendAll` pace benchmark workloads only; tests wait for the resulting UI state instead.
  const send = async (input: TimelineEvent, delay = 0) => {
    const events = timelineEvents(input)

    if (events.length === 1) await transport.send(events[0]!, { marker: describeEvent(events[0]!) })

    if (events.length > 1)
      await transport.burst(
        events,
        events.map((item) => ({ marker: describeEvent(item) })),
      )

    if (delay) await page.waitForTimeout(delay)
  }

  return {
    transport,
    pty: mock.pty,
    send,
    async sendAll(sequence: { event: TimelineEvent; delay: number }[]) {
      for (const item of sequence) await send(item.event, item.delay)
    },
    async waitForPart(partID: string) {
      const part = page.locator(`[data-timeline-part-id="${renderedPartID(partID)}"]`)
      await expect(part).toHaveCount(1)
      await expect(part).toBeVisible()
    },
  }
}

function timelineEvents(input: TimelineEvent) {
  return (Array.isArray(input) ? input : [input]).map(validateTimelineEvent)
}

function describeEvent(event: OpenCodeEvent) {
  if (event.type.startsWith("session.tool.")) {
    const data = event.data as { id?: string }

    return [event.type, data.id].filter(Boolean).join(":")
  }

  return event.type
}

export function event(
  type: "session.status",
  data: Extract<OpenCodeEvent, { type: "session.status" }>["data"],
): OpenCodeEvent {
  return makeEvent(type, data)
}

export function compactionStarted(data: Extract<OpenCodeEvent, { type: "session.compaction.started" }>["data"]) {
  return makeEvent("session.compaction.started", data)
}

export function compactionDelta(data: Extract<OpenCodeEvent, { type: "session.compaction.delta" }>["data"]) {
  return makeEvent("session.compaction.delta", data)
}

export function compactionEnded(data: Extract<OpenCodeEvent, { type: "session.compaction.ended" }>["data"]) {
  return makeEvent("session.compaction.ended", data)
}

export function compactionFailed(data: Extract<OpenCodeEvent, { type: "session.compaction.failed" }>["data"]) {
  return makeEvent("session.compaction.failed", data)
}

export function toolInputStarted(data: Extract<OpenCodeEvent, { type: "session.tool.input.started" }>["data"]) {
  return makeEvent("session.tool.input.started", data)
}

export function toolInputEnded(data: Extract<OpenCodeEvent, { type: "session.tool.input.ended" }>["data"]) {
  return makeEvent("session.tool.input.ended", data)
}

export function toolCalled(data: Extract<OpenCodeEvent, { type: "session.tool.called" }>["data"]) {
