import type { SessionMessageUser } from "@opencode/client/promise"
import { Option, Schema } from "effect"
import { Persistence } from "@/runtime/persistence/schema"
import { uuid } from "@/runtime/persistence/uuid"
import { FileSelection } from "@/workspaces/files/types"
import { durableNote, LegacyBrowserNote, NoteComment, type ContextItem } from "./schema"

export const PromptFileComment = Persistence.struct({
  type: Schema.optional(Schema.Literal("file")),
  path: Schema.String,
  selection: Persistence.optional(FileSelection),
  comment: Schema.String,
  preview: Persistence.optional(Schema.String),
  origin: Persistence.optional(Schema.Literals(["review", "file"])),
})

export type PromptFileComment = typeof PromptFileComment.Type

export type PromptComment = PromptFileComment | NoteComment

/** An attachment the model receives as a path on the server rather than inline bytes. */
export const PromptAttachmentReference = Persistence.struct({
  name: Schema.String,
  mime: Schema.String,
  path: Schema.String,
})

export type PromptAttachmentReference = typeof PromptAttachmentReference.Type

// Presentation metadata needs a comments list, which prompts from other clients lack; a malformed comment or
// attachment is skipped rather than discarding the rest.
const decodePromptPresentation = Schema.decodeUnknownOption(
  Schema.Struct({
    displayText: Schema.String,
    comments: Schema.Array(Schema.Unknown),
    attachments: Persistence.array(PromptAttachmentReference),
  }),
)

const decodePromptComment = Schema.decodeUnknownOption(Schema.Union([NoteComment, LegacyBrowserNote, PromptFileComment]))

export function readPromptPresentation(metadata: SessionMessageUser["metadata"]) {
  return Option.getOrUndefined(
    Option.map(decodePromptPresentation(metadata), (presentation) => ({
      displayText: presentation.displayText,
      attachments: presentation.attachments,
      comments: presentation.comments.flatMap((item): PromptComment[] => Option.toArray(decodePromptComment(item))),
    })),
  )
}

export function formatAttachmentReference(input: PromptAttachmentReference) {
  return `Attached file: \`${input.path}\``
}

/** A note reads with its live subject while it stays in the app process that attached it. */
export function formatNoteComment(input: NoteComment) {
  return `The user made the following comment regarding ${input.live?.subject ?? input.subject}: ${input.comment}`
}

/** Restores a sent comment to the composer, for example after a revert or fork. */
export function commentContextItem(comment: PromptComment): ContextItem {
  // The message may predate this app process, so a note's live references can no longer be trusted.
  if (comment.type === "note") return { ...durableNote(comment), commentID: uuid() }

  return {
    type: "file",
    path: comment.path,
    selection: comment.selection,
    comment: comment.comment,
    preview: comment.preview,
    commentOrigin: comment.origin,
  }
}

export function formatCommentNote(input: { path: string; selection?: FileSelection; comment: string }) {
  const start = input.selection ? Math.min(input.selection.startLine, input.selection.endLine) : undefined
  const end = input.selection ? Math.max(input.selection.startLine, input.selection.endLine) : undefined

  const range =
    start === undefined || end === undefined
      ? "this file"
      : start === end
        ? `line ${start}`
        : `lines ${start} through ${end}`

  return `The user made the following comment regarding ${range} of ${input.path}: ${input.comment}`
}

export function parseCommentNote(text: string) {
  const match = text.match(
    /^The user made the following comment regarding (this file|line (\d+)|lines (\d+) through (\d+)) of (.+?): ([\s\S]+)$/,
  )

  if (!match) return
  const start = match[2] ? Number(match[2]) : match[3] ? Number(match[3]) : undefined
  const end = match[2] ? Number(match[2]) : match[4] ? Number(match[4]) : undefined

  return {
    path: match[5],
    selection:
      start !== undefined && end !== undefined
        ? {
            startLine: start,
            startChar: 0,
            endLine: end,
            endChar: 0,
          }
        : undefined,
    comment: match[6],
  } satisfies PromptComment
}

import { describe, expect, test } from "bun:test"
import { createRoot } from "solid-js"
import { createCommentSessionForTest, type LineComment } from "./comments"

function line(file: string, id: string, time: number): LineComment {
  return {
    id,
    file,
    comment: id,
    time,
    selection: { start: 1, end: 1 },
  }
}

describe("comments session indexing", () => {
  test("keeps file list behavior and aggregate chronological order", () => {
    createRoot((dispose) => {
      const comments = createCommentSessionForTest({
        "a.ts": [line("a.ts", "a-late", 30), line("a.ts", "a-early", 10)],
        "b.ts": [line("b.ts", "b-mid", 20)],
      })

      expect(comments.list("a.ts").map((item) => item.id)).toEqual(["a-late", "a-early"])
      expect(comments.all().map((item) => item.id)).toEqual(["a-early", "b-mid", "a-late"])

      const next = comments.add({
        file: "b.ts",
        comment: "next",
        selection: { start: 2, end: 2 },
      })

      expect(comments.list("b.ts").map((item) => item.id)).toEqual(["b-mid", next.id])
      expect(comments.all().map((item) => item.id)).toEqual(["a-early", "b-mid", "a-late", next.id])

      comments.update("a.ts", "a-early", "edited")
      expect(comments.list("a.ts").map((item) => item.comment)).toEqual(["a-late", "edited"])

      dispose()
    })
  })

  test("remove updates file and aggregate indexes and clears focus only for the same file", () => {
    createRoot((dispose) => {
      const comments = createCommentSessionForTest({
        "a.ts": [line("a.ts", "a1", 10), line("a.ts", "shared", 20)],
        "b.ts": [line("b.ts", "shared", 30)],
      })

      comments.setFocus({ file: "b.ts", id: "shared" })
      comments.remove("a.ts", "shared")
      expect(comments.focus()).toEqual({ file: "b.ts", id: "shared" })

      comments.setFocus({ file: "a.ts", id: "a1" })
      comments.setActive({ file: "a.ts", id: "a1" })
      comments.remove("a.ts", "a1")

      expect(comments.list("a.ts")).toEqual([])
      expect(comments.all().map((item) => `${item.file}:${item.id}`)).toEqual(["b.ts:shared"])
      expect(comments.focus()).toBeNull()
      expect(comments.active()).toEqual({ file: "a.ts", id: "a1" })

      dispose()
    })
  })

  test.each(["replace", "clear"] as const)("%s resets comment state and focus", (action) => {
    createRoot((dispose) => {
      const comments = createCommentSessionForTest({
        "a.ts": [line("a.ts", "a1", 10)],
      })

      comments.setFocus({ file: "a.ts", id: "a1" })
      comments.setActive({ file: "a.ts", id: "a1" })

      if (action === "replace") comments.replace([line("b.ts", "b1", 30)])

      if (action === "clear") comments.clear()

      expect(comments.list("a.ts")).toEqual([])
      expect(comments.all().map((item) => item.id)).toEqual(action === "replace" ? ["b1"] : [])
      expect(comments.focus()).toBeNull()
      expect(comments.active()).toBeNull()

      dispose()
    })
  })
})

import { batch, createMemo, createRoot, onCleanup } from "solid-js"
import { createStore, reconcile, type SetStoreFunction, type Store } from "solid-js/store"
import { createSimpleContext } from "@opencode/ui/context"
import { useParams } from "@solidjs/router"
import { base64Encode } from "@opencode/util/encode"
import { Persist, persisted } from "@/runtime/persistence/storage"
import { useServerSDK } from "@/runtime/server/client"
import type { ServerScope } from "@/runtime/server/scope"
import { createScopedCache } from "@/runtime/server/scoped-cache"
import { uuid } from "@/runtime/persistence/uuid"
import type { SelectedLineRange } from "@/workspaces/files/model"
import { useWorkspaceLocation } from "@/workspaces/location"
import { CommentStore, type LineComment } from "./schema"

export type { LineComment } from "./schema"

type CommentFocus = { file: string; id: string }

const WORKSPACE_KEY = "__workspace__"

const MAX_COMMENT_SESSIONS = 20

function sessionKey(dir: string, id: string | undefined) {
  return `${dir}\n${id ?? WORKSPACE_KEY}`
}

function decodeSessionKey(key: string) {
  const split = key.lastIndexOf("\n")

  if (split < 0) return { dir: key, id: WORKSPACE_KEY }

  return {
    dir: key.slice(0, split),
    id: key.slice(split + 1),
  }
}

function aggregate(comments: Record<string, LineComment[]>) {
  return Object.keys(comments)
    .flatMap((file) => comments[file] ?? [])
    .slice()
    .sort((a, b) => a.time - b.time)
}

function cloneSelection(selection: SelectedLineRange): SelectedLineRange {
  const next: SelectedLineRange = {
    start: selection.start,
    end: selection.end,
  }

  if (selection.side) next.side = selection.side

  if (selection.endSide) next.endSide = selection.endSide

  return next
}

function cloneComment(comment: LineComment): LineComment {
  return {
    ...comment,
    selection: cloneSelection(comment.selection),
  }
}

function group(comments: LineComment[]) {
  return comments.reduce<Record<string, LineComment[]>>((acc, comment) => {
    const list = acc[comment.file]
    const next = cloneComment(comment)

    if (list) {
      list.push(next)

      return acc
    }

    acc[comment.file] = [next]

    return acc
  }, {})
}

function createCommentSessionState(store: Store<CommentStore>, setStore: SetStoreFunction<CommentStore>) {
  const [state, setState] = createStore({
    focus: null as CommentFocus | null,
    active: null as CommentFocus | null,
  })

  // Reuse the previous array when contents are unchanged so consumers keep a stable
  // identity; a fresh array per call cascaded into diff annotation re-renders.
  let lastAll: LineComment[] = []

  const all = () => {
    const next = aggregate(store.comments)

    if (next.length === lastAll.length && next.every((item, index) => item === lastAll[index])) return lastAll
    lastAll = next

    return next
  }

  const setRef = (
    key: "focus" | "active",
    value: CommentFocus | null | ((value: CommentFocus | null) => CommentFocus | null),
  ) => setState(key, value)

  const setFocus = (value: CommentFocus | null | ((value: CommentFocus | null) => CommentFocus | null)) =>
    setRef("focus", value)

  const setActive = (value: CommentFocus | null | ((value: CommentFocus | null) => CommentFocus | null)) =>
    setRef("active", value)

  const list = (file: string) => store.comments[file] ?? []

  const add = (input: Omit<LineComment, "id" | "time">) => {
    const next: LineComment = {
      id: uuid(),
      time: Date.now(),
      ...input,
      selection: cloneSelection(input.selection),
    }

    batch(() => {
      setStore("comments", input.file, (items) => [...(items ?? []), next])
      setFocus({ file: input.file, id: next.id })
    })

    return next
  }

  const remove = (file: string, id: string) => {
    batch(() => {
      setStore("comments", file, (items) => (items ?? []).filter((item) => item.id !== id))
      setFocus((current) => (current?.file === file && current.id === id ? null : current))
    })
  }

  const update = (file: string, id: string, comment: string) => {
    setStore("comments", file, (items) =>
      (items ?? []).map((item) => {
        if (item.id !== id) return item

        return { ...item, comment }
      }),
    )
  }

  const replace = (comments: LineComment[]) => {
    batch(() => {
      setStore("comments", reconcile(group(comments)))
      setFocus(null)
      setActive(null)
    })
  }

  const clear = () => {
    batch(() => {
      setStore("comments", reconcile({}))
      setFocus(null)
      setActive(null)
    })
  }

  return {
    list,
    all,
    add,
    remove,
    update,
    replace,
    clear,
    focus: () => state.focus,
    setFocus,
    clearFocus: () => setRef("focus", null),
    active: () => state.active,
    setActive,
    clearActive: () => setRef("active", null),
  }
}

export function createCommentSessionForTest(comments: Record<string, LineComment[]> = {}) {
  const [store, setStore] = createStore<CommentStore>({ comments })

  return createCommentSessionState(store, setStore)
}

function createCommentSession(scope: ServerScope, dir: string, id: string | undefined) {
  const [store, setStore, _, ready] = persisted(Persist.serverScoped(scope, dir, id, "comments"), CommentStore, {
    comments: {},
  })

  const session = createCommentSessionState(store, setStore)

  return {
    ready,
    list: session.list,
    all: session.all,
    add: session.add,
    remove: session.remove,
    update: session.update,
    replace: session.replace,
    clear: session.clear,
    focus: session.focus,
    setFocus: session.setFocus,
    clearFocus: session.clearFocus,
    active: session.active,
    setActive: session.setActive,
    clearActive: session.clearActive,
  }
}

export const { use: useComments, provider: CommentsProvider } = createSimpleContext({
  name: "Comments",
  gate: false,
  init: () => {
    const params = useParams()
    const sdk = useWorkspaceLocation()
    const serverSDK = useServerSDK()

    const cache = createScopedCache(
      (key) => {
        const decoded = decodeSessionKey(key)

        return createRoot((dispose) => ({
          value: createCommentSession(
            serverSDK.scope,
            decoded.dir,
            decoded.id === WORKSPACE_KEY ? undefined : decoded.id,
          ),
          dispose,
        }))
      },
      {
        maxEntries: MAX_COMMENT_SESSIONS,
        dispose: (entry) => entry.dispose(),
      },
    )

    onCleanup(() => cache.clear())

    const load = (dir: string, id: string | undefined) => {
      const key = sessionKey(dir, id)

      return cache.get(key).value
    }

    const session = createMemo(() => load(base64Encode(sdk().directory), params.id))

    return {
      ready: () => session().ready(),
      list: (file: string) => session().list(file),
      all: () => session().all(),
      add: (input: Omit<LineComment, "id" | "time">) => session().add(input),
      remove: (file: string, id: string) => session().remove(file, id),
      update: (file: string, id: string, comment: string) => session().update(file, id, comment),
      replace: (comments: LineComment[]) => session().replace(comments),
      clear: () => session().clear(),
      focus: () => session().focus(),
      setFocus: (focus: CommentFocus | null) => session().setFocus(focus),
      clearFocus: () => session().clearFocus(),
      active: () => session().active(),
      setActive: (active: CommentFocus | null) => session().setActive(active),
      clearActive: () => session().clearActive(),
    }
  },
})

import { Show, createMemo, onMount, type JSX } from "solid-js"
