function ComposerEditorConfiguredSelect(props: {
  mobileDrawer?: boolean
  title: string
  keybind?: string[]
  control: ComposerSelectControl
  model?: boolean
  class?: string
}) {
  const current = () => props.control.current()
  const providerID = () => props.control.options().find((option) => option.id === current())?.providerID

  return (
    <ComposerEditorSelect
      mobileDrawer={props.mobileDrawer}
      title={props.title}
      class={props.class}
      keybind={props.control.keybind?.() ?? props.keybind}
      options={props.control.options()}
      current={current()}
      currentIcon={
        <Show when={props.model && providerID()}>
          {(id) => <ProviderModelIcon provider={{ id: id(), name: id() }} class="shrink-0 opacity-60" />}
        </Show>
      }
      onSelect={props.control.onSelect}
    />
  )
}

export function ComposerEditorSelect(props: {
  mobileDrawer?: boolean
  title: string
  keybind?: string[]
  options: ComposerOption[]
  current: string
  currentIcon?: JSX.Element
  class?: string
  onOpenChange?: (open: boolean) => void
  onSelect: (id: string) => void
}) {
  const mobile = createMediaQuery("(max-width: 767px)")
  const [store, setStore] = createStore({ open: false, loaded: false })
  let trigger: HTMLButtonElement | undefined

  const setOpen = (open: boolean) => {
    setStore("open", open)

    if (open) setStore("loaded", true)
    props.onOpenChange?.(open)
  }

  createEffect(() => {
    if (!mobile() && store.open) setOpen(false)
  })

  const content = () => (
    <>
      {props.currentIcon}
      <span class="truncate capitalize leading-5">
        {props.options.find((option) => option.id === props.current)?.label ?? props.current}
      </span>
      <span class="-ms-0.5 -me-1 flex shrink-0">
        <Icon name="chevron-down" />
      </span>
    </>
  )

  return (
    <Tooltip
      inactive={props.mobileDrawer && mobile()}
      placement="top"
      value={
        <>
          {props.title}
          <Keybind keys={props.keybind ?? []} variant="neutral" />
        </>
      }
    >
      <Show
        when={props.mobileDrawer && mobile()}
        fallback={
          <Menu gutter={6} modal={false} placement="top-start" onOpenChange={props.onOpenChange}>
            <Menu.Trigger
              as={Button}
              variant="ghost-muted"
              size="normal"
              class={`max-w-[220px] justify-start ![font-weight:440] ${props.class ?? ""}`}
              aria-label={props.title}
            >
              {content()}
            </Menu.Trigger>
            <Menu.Portal>
              <Menu.Content>
                <Menu.RadioGroup value={props.current} onChange={props.onSelect}>
                  <For each={props.options}>
                    {(option) => (
                      <Menu.RadioItem value={option.id} class="capitalize" closeOnSelect>
                        {option.label}
                      </Menu.RadioItem>
                    )}
                  </For>
                </Menu.RadioGroup>
              </Menu.Content>
            </Menu.Portal>
          </Menu>
        }
      >
        <Button
          ref={(element: HTMLButtonElement) => {
            trigger = element
          }}
          variant="ghost-muted"
          size="normal"
          class={`max-w-[220px] justify-start ![font-weight:440] ${props.class ?? ""}`}
          aria-label={props.title}
          aria-haspopup="dialog"
          aria-expanded={store.open}
          onClick={() => setOpen(true)}
        >
          {content()}
        </Button>
        <Show when={store.loaded}>
          <Suspense>
            <MobilePanelDrawer
              hideHeader
              title={props.title}
              open={store.open}
              onOpenChange={setOpen}
              returnFocus={() => trigger}
            >
              <div class="flex flex-col overflow-hidden rounded-lg border border-v2-border-border-base bg-v2-background-bg-layer-02 divide-y divide-v2-border-border-base">
                <For each={props.options}>
                  {(option) => (
                    <Button
                      variant="ghost"
                      class="w-full !h-10 !justify-start !rounded-none !px-3 !font-[440] capitalize focus-visible:!outline-offset-[-2px]"
                      aria-pressed={props.current === option.id}
                      data-state={props.current === option.id ? "pressed" : undefined}
                      onClick={() => {
                        props.onSelect(option.id)
                        setOpen(false)
                      }}
                    >
                      {option.label}
                      <Show when={props.current === option.id}>
                        <Icon name="check" class="ms-auto" />
                      </Show>
                    </Button>
                  )}
                </For>
              </div>
            </MobilePanelDrawer>
          </Suspense>
        </Show>
      </Show>
    </Tooltip>
  )
}

export function ComposerEditorPopover(props: {
  emptyLabel: string
  items: ComposerSuggestion[]
  activeID?: string
  search?: {
    value: string
    label: string
    placeholder: string
    onValueChange: (value: string) => void
    onKeyDown: (event: KeyboardEvent) => void
  }
  boundary?: () => HTMLElement | undefined
  onActiveChange: (item: ComposerSuggestion) => void
  onSelect: (item: ComposerSuggestion) => void
}) {
  const [store, setStore] = createStore({ maxHeight: COMPOSER_SUGGESTION_MAX_HEIGHT })

  const resize = (height: number) =>
    setStore("maxHeight", composerSuggestionMaxHeight(height, props.search !== undefined))

  // A detached boundary (e.g. the previous session's timeline while the next one loads) measures 0px.
  const boundary = () => {
    const element = props.boundary?.()

    return element?.isConnected ? element : undefined
  }

  createEffect(() => resize(boundary()?.clientHeight ?? COMPOSER_SUGGESTION_MAX_HEIGHT * 2))
  createResizeObserver(boundary, (rect) => resize(rect.height))

  return (
    <div
      data-component="composer-suggestions"
      class="absolute inset-x-0 -top-2 z-40 flex -translate-y-full scroll-pb-[18px] flex-col overflow-auto rounded-xl bg-v2-background-bg-base p-2 shadow-[var(--v2-elevation-raised)] no-scrollbar"
      style={{ "max-height": `${store.maxHeight}px` }}
      onMouseDown={(event) => event.preventDefault()}
    >
      <Show when={props.search}>
        {(search) => (
          <div class="shrink-0 px-2 py-1">
            <input
              ref={(element) => requestAnimationFrame(() => element.focus())}
              value={search().value}
              aria-label={search().label}
              placeholder={search().placeholder}
              class="w-full bg-transparent text-[13px] leading-5 text-v2-text-text-base outline-none placeholder:text-v2-text-text-faint"
              onInput={(event) => search().onValueChange(event.currentTarget.value)}
              onKeyDown={(event) => search().onKeyDown(event)}
              onMouseDown={(event) => event.stopPropagation()}
            />
          </div>
        )}
      </Show>
      <Show
        when={props.items.length > 0}
        fallback={<div class="px-2 py-1 text-v2-text-text-muted">{props.emptyLabel}</div>}
      >
        <For each={props.items}>
          {(item) => (
            <button
              type="button"
              data-suggestion-id={item.id}
              data-active={props.activeID === item.id ? "" : undefined}
              class="flex h-7 w-full shrink-0 items-center gap-2 rounded-md px-2 py-1 text-start hover:bg-v2-overlay-simple-overlay-hover"
              classList={{ "bg-v2-overlay-simple-overlay-hover": props.activeID === item.id }}
              onPointerMove={() => props.onActiveChange(item)}
              onClick={() => props.onSelect(item)}
            >
              <div class="flex min-w-0 flex-1 items-center gap-2">
                <ComposerSuggestionIcon item={item} />
                <bdi dir="auto" class="shrink-0 text-v2-text-text-base">
                  {item.label}
                </bdi>
                <Show when={item.description}>
                  <span class="min-w-0 truncate text-v2-text-text-muted">{item.description}</span>
                </Show>
              </div>
              <Show when={item.keybind?.length}>
                <span class="shrink-0 text-v2-text-text-muted">{item.keybind?.join("+")}</span>
              </Show>
            </button>
          )}
        </For>
      </Show>
    </div>
  )
}

function composerSuggestionMaxHeight(boundaryHeight: number, search: boolean) {
  const reserve = Math.min(COMPOSER_SUGGESTION_CONTEXT_RESERVE, boundaryHeight / 4)
  const limit = Math.min(COMPOSER_SUGGESTION_MAX_HEIGHT, boundaryHeight - reserve)
  const chrome = COMPOSER_SUGGESTION_TOP_PADDING + (search ? COMPOSER_SUGGESTION_SEARCH_HEIGHT : 0)

  if (limit < chrome + COMPOSER_SUGGESTION_ROW_HEIGHT + COMPOSER_SUGGESTION_ROW_PEEK) return limit

  return (
    chrome +
    Math.floor((limit - chrome - COMPOSER_SUGGESTION_ROW_PEEK) / COMPOSER_SUGGESTION_ROW_HEIGHT) *
      COMPOSER_SUGGESTION_ROW_HEIGHT +
    COMPOSER_SUGGESTION_ROW_PEEK
  )
}

// "Steer ⌘⏎" / "Queue ⌘⏎" hint next to the submit button: submits with the
// delivery opposite to what plain Enter does. Visible only while the queue
// exposes an alternate (turn running and composer holding a value), so it
// disappears on its own when the current turn ends.
function ComposerEditorAlternateDelivery(props: { controller: ComposerEditorModel; keybind: string[] }) {
  const i18n = useI18n()
  const view = props.controller.view

  const action = createMemo(() => {
    const queue = view.submit.queue

    if (!queue || !props.controller.canSubmit()) return undefined

    if (queue.editing()) return "steer" as const

    return queue.alternate()
  })

  const [button, setButton] = createSignal<HTMLButtonElement>()
  const presence = createAnimatedPresence(action, () => button() ?? null)

  return (
    <Show when={presence.present() && presence.value()} keyed>
      {(delivery) => (
        <Tooltip placement="top" inactive={delivery !== "steer"} value={i18n.t("ui.promptInput.steerHint")}>
          <Button
            ref={setButton}
            data-action="composer-alternate-delivery"
            type="button"
            variant="ghost-faint"
            size="small"
            class="me-3 gap-1.5 px-1.5 ![font-weight:530] duration-150 motion-reduce:animate-none"
            classList={{
              "animate-in fade-in": presence.animate() && presence.show(),
              "animate-out fade-out fill-mode-forwards": presence.animate() && !presence.show(),
            }}
            onClick={() => props.controller.submit({ alternate: true })}
          >
            {delivery === "steer" ? i18n.t("ui.promptInput.steer") : i18n.t("ui.promptInput.queue")}
            <span class="hidden sm:block">
              <Keybind keys={props.keybind} variant="neutral" />
            </span>
          </Button>
        </Tooltip>
      )}
    </Show>
  )
}

export function ComposerEditorSubmitButton(props: {
  mode: ComposerMode
  stopping: boolean
  disabled: boolean
  sendLabel: string
  stopLabel: string
  onSubmit: () => void
  onStop: () => void
}) {
  return (
    <Tooltip
      placement="top"
      inactive={!props.stopping && props.disabled}
      value={props.stopping ? props.stopLabel : props.sendLabel}
    >
      <IconButton
        data-action="composer-submit"
        type="button"
        disabled={!props.stopping && props.disabled}
        tabIndex={props.mode === "normal" ? undefined : -1}
        icon={<Icon name={props.stopping ? "stop" : props.mode === "shell" ? "arrow-undo-down" : "arrow-up"} />}
        variant="submit"
        class="size-7 rounded-md p-[6px]"
        aria-label={props.stopping ? props.stopLabel : props.sendLabel}
        onClick={(event) => {
          event.preventDefault()
          event.stopPropagation()

          if (props.stopping) {
            props.onStop()

            return
          }

          props.onSubmit()
        }}
      />
    </Tooltip>
  )
}

function ComposerSuggestionIcon(props: { item: ComposerSuggestion }) {
  if (props.item.kind === "agent") return <Icon name="brain" size="small" class="shrink-0 text-icon-info-active" />

  if (props.item.kind === "skill") return <Icon name="post-skill" size="small" class="shrink-0" />

  if (props.item.kind === "command") return null

  return (
    <FileIcon
      node={{ path: props.item.path ?? props.item.label, type: props.item.kind === "reference" ? "directory" : "file" }}
      class="size-4 shrink-0"
    />
  )
}

import { expect, test } from "bun:test"
import { shouldHandlePasteAsAttachment } from "./interaction"

test("handles clipboard files, and native images only when the clipboard has no text", () => {
  expect(shouldHandlePasteAsAttachment(clipboard(), false)).toBe(false)
  expect(shouldHandlePasteAsAttachment(clipboard(), true)).toBe(true)
  expect(shouldHandlePasteAsAttachment(clipboard(["text/plain"]), true)).toBe(false)
  expect(shouldHandlePasteAsAttachment(clipboard([], [{ kind: "file" }]), false)).toBe(true)
})

function clipboard(types: string[] = [], items: Array<{ kind: string }> = []) {
  return { types, items } as unknown as DataTransfer
}

import { Predicate } from "effect"
import { createEffect, type Accessor } from "solid-js"
import { createStore, reconcile } from "solid-js/store"
import { useFilteredList } from "@opencode/ui/hooks"
import { createComposerAttachments, type ComposerAttachmentConfig } from "../attachments/attachments"
import type { Upload } from "../attachments/uploads"
import { createComposerEditorActions, type ComposerStateStoreInput } from "./actions"
import type {
  ComposerAttachment,
  ComposerComment,
  ComposerHistory,
  ComposerHistoryEntry,
  ComposerOption,
  ComposerPersistedState,
  ComposerSuggestion,
} from "../types"
import {
  createComposerInteractionState,
  transitionComposer,
  type ComposerInteractionCommand,
  type ComposerInteractionEvent,
} from "../suggestions/machine"
import { clonePrompt, isAttachment, promptLength } from "../prompt-parts"
import type { ComposerQueue } from "../adapter"

export type ComposerSelectControl = {
  options: Accessor<ComposerOption[]>
  current: Accessor<string>
  onSelect: (id: string) => void
  keybind?: Accessor<string[]>
}

export type ComposerEditorView = {
  draftOnly?: boolean
  placeholder?: Accessor<string>
  add?: {
    onAttach: () => void
  }
  agent?: ComposerSelectControl
  variant?: ComposerSelectControl
  submit: {
    available?: Accessor<boolean>
    stopping: Accessor<boolean>
    working?: Accessor<boolean>
    queue?: ComposerQueue
    onSubmit: (options?: { alternate?: boolean }) => void
    onStop: () => void
  }
  shell?: {
    onOpen: () => void
    onClose: () => void
  }
}

export function createComposerEditorState(mode: "normal" | "shell" = "normal") {
  return createStore({ ...createComposerInteractionState(), mode })
}

export function createComposerEditor(input: {
  store: ComposerStateStoreInput
  state?: ReturnType<typeof createComposerEditorState>
  history?: ComposerHistory
  commands: Accessor<ComposerSuggestion[]>
  context: Accessor<ComposerSuggestion[]>
  searchContextFiles: (query: string) => ComposerSuggestion[] | Promise<ComposerSuggestion[]>
  openAttachment?: (attachment: ComposerAttachment) => void
  openContext?: (key: string) => void
  onContextRemove?: (item: ComposerComment) => void
  onEditor?: (element: HTMLElement) => void
  onSuggestionSelect?: (item: ComposerSuggestion) => (() => void) | void
  view: ComposerEditorView
  attachments?: ComposerAttachmentConfig
}) {
  let editor: HTMLElement | undefined
  let fileInput: HTMLInputElement | undefined
  const draft = createComposerEditorActions(input.store)
  const [state, setState] = input.state ?? createComposerEditorState(draft.state.mode)

  function addPart(part: ComposerPersistedState["prompt"][number]) {
    if (isAttachment(part)) return false

    if (part.type === "file" || part.type === "agent") {
      draft.addMention(part)

      return true
    }

    draft.addText(part.content)

    return true
  }

  const attachments = input.attachments
    ? createComposerAttachments({
        ...input.attachments,
        capture: () => ({
          current: () => draft.state.prompt,
          cursor: () => draft.state.cursor,
          set: (prompt, cursor) => draft.setPrompt(prompt, cursor),
        }),
        editor: () => editor,
        focusEditor: () => editor?.focus(),
        addPart,
        setDraggingType: (type) => dispatch({ type: type ? "drag.enter" : "drag.leave" }),
      })
    : undefined

  const attach = () => {
    if (!attachments) {
      input.view.add?.onAttach()

      return
    }

    // The add menu leaves focus on its trigger, so return it to the editor once files are picked.
    attachments.pick(
      () => fileInput?.click(),
      () => restoreFocus(),
    )
  }

  const contextList = useFilteredList<ComposerSuggestion>({
    items: async (query) => {
      const fixed = input.context().filter((item) => item.kind !== "file")
      const recent = input.context().filter((item) => item.kind === "file" && item.recent)

      if (!query.trim()) return [...fixed, ...recent]
      const seen = new Set(recent.map((item) => item.id))
      const files = (await input.searchContextFiles(query)).filter((item) => !seen.has(item.id))

      return [...fixed, ...recent, ...files]
    },
    key: (item) => item.id,
    filterKeys: ["label"],
    skipFilter: (item) => item.kind === "file" && !item.recent,
    groupBy: (item) => {
      if (item.kind === "reference") return "reference"

      if (item.kind === "skill") return "skill"

      if (item.kind === "agent") return "agent"

      if (item.kind === "resource") return "resource"

      if (item.recent) return "recent"

      return "file"
    },
    sortGroupsBy: (a, b) => {
      const order = ["reference", "skill", "agent", "resource", "recent", "file"]

      return order.indexOf(a.category) - order.indexOf(b.category)
    },
  })

  const commandList = useFilteredList<ComposerSuggestion>({
    items: () => input.commands(),
    key: (item) => item.id,
    filterKeys: ["trigger", "title"],
  })

  const list = () => (state.popover.type === "context" ? contextList : commandList)
  const suggestions = () => list().flat()

  const execute = (command: ComposerInteractionCommand) => {
    if (command.type === "draft.setText") {
      draft.setText(command.value)

      return
    }

    if (command.type === "draft.addText") {
      draft.addText(command.value)

      return
    }

    if (command.type === "mention.add") {
      if (command.item.mention) draft.addMention(command.item.mention, command.range)

      return
    }

    if (command.type === "popover.filter") {
      ;(command.popover === "command" ? commandList : contextList).onInput(command.query)

      return
    }

    if (command.type === "suggestion.select") {
      const item = suggestions().find((entry) => entry.id === command.id)

      if (item) dispatch({ type: "popover.select", item })

      return
    }

    if (command.type === "focus.editor") requestAnimationFrame(() => editor?.focus())
  }

  function dispatch(event: ComposerInteractionEvent) {
    const mode = state.mode
    const result = transitionComposer(state, event, draft.state)
    const action = event.type === "popover.select" ? input.onSuggestionSelect?.(event.item) : undefined

    if (event.type === "popover.select") {
      if (!action) result.commands.forEach(execute)

      if (action && event.item.kind === "command" && state.popover.type !== "command-menu") {
        draft.setPrompt(draft.state.prompt.filter(isAttachment), 0)
      }
    }

    setState(reconcile(result.state))

    if (mode !== result.state.mode) draft.setMode(result.state.mode)

    if (event.type !== "popover.select") result.commands.forEach(execute)

    if (mode !== result.state.mode) {
      if (result.state.mode === "shell") input.view.shell?.onOpen()

      if (result.state.mode === "normal") input.view.shell?.onClose()
    }

    if (event.type === "popover.select") {
      if (!action) return result.handled
      action()
    }

    return result.handled
  }

  const onKeyDown = (event: KeyboardEvent) => {
    if (
      state.mode === "normal" &&
      (event.metaKey || event.ctrlKey) &&
      !event.altKey &&
      !event.shiftKey &&
      event.key.toLowerCase() === "u"
    ) {
      event.preventDefault()
      attach()

      return true
    }

    const handled = dispatch({
      type: "key.down",
      key: event.key,
      ctrl: event.ctrlKey && !event.metaKey && !event.altKey && !event.shiftKey,
      composing: event.isComposing,
      ids: suggestions().map((item) => item.id),
      empty: draft.state.prompt.every((part) => !("content" in part) || part.content.length === 0),
    })

    if (handled) event.preventDefault()

    if (handled && event.key !== "Enter" && event.key !== "Tab" && state.popover.type !== "closed") {
      const activeID = state.popover.activeID ?? ""
      requestAnimationFrame(() =>
        document.querySelector(`[data-suggestion-id="${CSS.escape(activeID)}"]`)?.scrollIntoView({ block: "nearest" }),
      )
    }

    if (handled) return true

    if (event.key === "Escape" && input.view.submit.queue?.editing()) {
      event.preventDefault()
      input.view.submit.queue.cancelEdit()

      return true
    }

    const stop =
      input.view.submit.working?.() &&
      ((event.ctrlKey && !event.metaKey && !event.altKey && !event.shiftKey && event.key.toLowerCase() === "g") ||
        event.key === "Escape")

    if (stop) {
      event.preventDefault()
      input.view.submit.onStop()

      return true
    }

    if (
      !event.altKey &&
      !event.ctrlKey &&
      !event.metaKey &&
      (event.key === "ArrowUp" || event.key === "ArrowDown") &&
      navigateHistory(event.key === "ArrowUp" ? "up" : "down")
    ) {
      event.preventDefault()

      return true
    }

    return event.defaultPrevented
  }

  createEffect(() => {
    if (state.popover.type === "closed") return
    const ids = suggestions().map((item) => item.id)

    if (state.popover.activeID ? ids.includes(state.popover.activeID) : ids.length === 0) return
    dispatch({ type: "popover.results", ids })
  })

  const restoreFocus = (cursor = draft.state.cursor ?? promptLength(draft.state.prompt)) => {
    requestAnimationFrame(() => {
      editor?.focus()
      setEditorCursor(editor, cursor)
    })
  }

  const applyHistory = (entry: ComposerHistoryEntry, position: "start" | "end") => {
    input.history?.restore?.(entry.metadata)
    const cursor = position === "start" ? 0 : promptLength(entry.prompt)
    draft.setPrompt(clonePrompt(entry.prompt), cursor)
    restoreFocus(cursor)
  }

  const navigateHistory = (direction: "up" | "down") => {
    if (!input.history || !editor) return false
    const selection = window.getSelection()

    if (!selection?.isCollapsed || !editor.contains(selection.anchorNode)) return false
    const text = draft.state.prompt.map((part) => ("content" in part ? part.content : "")).join("")

    if (!canNavigateHistory(direction, text, editorCursor(editor), state.historyIndex >= 0)) return false
    const entries = input.history.entries(state.mode)

    if (direction === "up") {
      if (entries.length === 0 || state.historyIndex >= entries.length - 1) return false

      if (state.historyIndex === -1) {
        setState("savedHistory", {
          prompt: clonePrompt(draft.state.prompt),
          metadata: input.history.capture?.(),
        })
      }

      const index = state.historyIndex + 1
      setState("historyIndex", index)
      applyHistory(entries[index]!, "start")

      return true
    }

    if (state.historyIndex < 0) return false

    if (state.historyIndex > 0) {
      const index = state.historyIndex - 1
      setState("historyIndex", index)
      applyHistory(entries[index]!, "end")

      return true
    }

    const saved = state.savedHistory ?? { prompt: [{ type: "text", content: "", start: 0, end: 0 }] }
    setState({ historyIndex: -1, savedHistory: undefined })
    applyHistory(saved, "end")

    return true
  }

  return {
    state,
    view: input.view,
    suggestions,
    dispatch,
    onKeyDown,
    value() {
      return draft.state.prompt.map((part) => ("content" in part ? part.content : "")).join("")
    },
    parts() {
      return draft.state.prompt
    },
    contextItem(id: string) {
      return draft.state.context.items.find((item) => item.key === id)
    },
    comments() {
      return draft.state.context.items.filter((item) => !!item.comment?.trim())
    },
    files() {
      return draft.state.context.items.flatMap((item) => (item.type === "file" && !item.comment?.trim() ? [item] : []))
    },
    attachments(): ComposerAttachment[] {
      return draft.state.prompt.filter(isAttachment)
    },
    uploads(): Upload[] {
      return attachments?.pending() ?? []
    },
    cancelUpload(id: string) {
      attachments?.cancel(id)
    },
    toggleContext(id: string) {
      dispatch({ type: "context.active", id })
      input.openContext?.(id)
    },
    removeContext(id: string) {
      const item = draft.state.context.items.find((entry) => entry.key === id)

      if (item) input.onContextRemove?.(item)
      draft.removeContext(id)

      if (state.activeContextID === id) dispatch({ type: "context.active", id })
    },
    openAttachment(attachment: ComposerAttachment) {
      input.openAttachment?.(attachment)
    },
    removeAttachment(id: string) {
      draft.removeAttachment(id)
    },
    canSubmit() {
      if (input.view.submit.available?.() === false) return false

      if (input.view.draftOnly) return false

      if (attachments?.pending().length) return false
      const persisted = draft.state

      if (state.mode === "shell") {
        return persisted.prompt.some((part) => "content" in part && !!part.content.trim())
      }

      if (persisted.prompt.some(isAttachment)) return true

      if (persisted.context.items.some((item) => !!item.comment?.trim())) return true

      return persisted.prompt.some((part) => "content" in part && !!part.content.trim())
    },
    setEditor(element: HTMLElement) {
      editor = element
      input.onEditor?.(element)
    },
    restoreFocus,
    onInput(value: string, prompt?: ComposerPersistedState["prompt"], cursor?: number) {
      if (prompt) draft.setPrompt(prompt, cursor)

      if (input.view.draftOnly) return
      dispatch({ type: "input.changed", value, persist: !prompt })
    },
    onCursor(cursor: number) {
      draft.setCursor(cursor)
    },
    openCommands() {
      dispatch({ type: "commands.open" })
    },
    openContext() {
      dispatch({ type: "context.open" })
    },
    openShell() {
      dispatch({ type: "mode.shell" })
    },
    submit(options?: { alternate?: boolean }) {
      if (input.view.submit.available?.() === false) return

      if (input.view.draftOnly) return

      if (attachments?.pending().length) return
      input.view.submit.onSubmit(options)
      dispatch({ type: "popover.close" })
    },
    stop() {
      input.view.submit.onStop()
    },
    addHistory(prompt: ComposerPersistedState["prompt"], mode: "normal" | "shell") {
      input.history?.add(prompt, mode)
      setState({ historyIndex: -1, savedHistory: undefined })
    },
    resetHistory() {
      setState({ historyIndex: -1, savedHistory: undefined })
    },
    onPaste(event: ClipboardEvent) {
      const clipboard = event.clipboardData
      const text = clipboard?.getData("text/plain")

      if (attachments && shouldHandlePasteAsAttachment(clipboard, !!input.attachments?.readClipboardImage)) {
        void attachments.handlePaste(event)

        return
      }

      if (!text) return
      event.preventDefault()
      // insertText emits input events per line, repeatedly parsing and saving the draft.
      // Escaped HTML inserts multiline text once and preserves native selection and undo.
      const normalized = text.replace(/\r\n?/g, "\n")
      const multiline = normalized.includes("\n")

      const value = multiline
        ? normalized.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;")
        : normalized

      if (
        Predicate.isFunction(document.execCommand) &&
        document.execCommand(multiline ? "insertHTML" : "insertText", false, value)
      )
        return
      const target = event.currentTarget
      const selection = window.getSelection()

      if (!(target instanceof HTMLElement) || !selection?.rangeCount || !target.contains(selection.anchorNode)) return
      const range = selection.getRangeAt(0)
      range.deleteContents()
      const node = document.createTextNode(normalized)
      range.insertNode(node)
      range.setStartAfter(node)
      range.collapse(true)
      selection.removeAllRanges()
      selection.addRange(range)
      target.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertFromPaste", data: normalized }))
    },
    onDragEnter(event: DragEvent) {
      event.preventDefault()
      dispatch({ type: "drag.enter" })
    },
    onDragOver(event: DragEvent) {
      event.preventDefault()
    },
    onDragLeave() {
      dispatch({ type: "drag.leave" })
    },
    onDrop(event: DragEvent) {
      event.preventDefault()
      dispatch({ type: "drag.leave" })

      if (attachments) {
        event.stopPropagation()
        void attachments.handleDrop(event)

        return
      }
    },
    attach,
    setFileInput(element: HTMLInputElement) {
      fileInput = element
    },
    addAttachments(files: File[]) {
      if (!attachments) return
      void attachments.addAttachments(files)
      restoreFocus()
    },
    setQuery(value: string) {
      dispatch({ type: "popover.query", value })
    },
  }
}

export type ComposerEditorModel = ReturnType<typeof createComposerEditor>

export function shouldHandlePasteAsAttachment(clipboard: DataTransfer | null, readClipboardImage: boolean) {
  if (Array.from(clipboard?.items ?? []).some((item) => item.kind === "file")) return true

  if (Array.from(clipboard?.types ?? []).some((type) => type.startsWith("text/"))) return false

  return readClipboardImage
}

function canNavigateHistory(direction: "up" | "down", text: string, cursor: number, inHistory: boolean) {
  const position = Math.max(0, Math.min(cursor, text.length))

  if (inHistory) return position === 0 || position === text.length

  if (direction === "up") return position === 0 && text.length === 0

  return position === text.length
}

function editorCursor(editor: HTMLElement) {
  const selection = window.getSelection()

  if (!selection?.rangeCount || !editor.contains(selection.anchorNode)) return editor.textContent?.length ?? 0
  const range = selection.getRangeAt(0).cloneRange()
  range.selectNodeContents(editor)
  range.setEnd(selection.anchorNode!, selection.anchorOffset)

  return range.toString().length
}

function setEditorCursor(editor: HTMLElement | undefined, cursor: number) {
  if (!editor) return
  const walker = document.createTreeWalker(editor, NodeFilter.SHOW_TEXT)
  let remaining = cursor
  let node = walker.nextNode()

  while (node) {
    const length = node.textContent?.length ?? 0

    if (remaining <= length) {
      const range = document.createRange()
      range.setStart(node, remaining)
      range.collapse(true)
      const selection = window.getSelection()
      selection?.removeAllRanges()
      selection?.addRange(range)

      return
    }

    remaining -= length
    node = walker.nextNode()
  }
}

import { describe, expect, test } from "bun:test"
import type { Prompt } from "@/composer/state"
import { prependHistoryEntry, removeHistoryEntry, type PromptHistoryComment } from "./entry"

const DEFAULT_PROMPT: Prompt = [{ type: "text", content: "", start: 0, end: 0 }]

const text = (value: string): Prompt => [{ type: "text", content: value, start: 0, end: value.length }]

const comment = (id: string, value = "note"): PromptHistoryComment => ({
  id,
  path: "src/a.ts",
  selection: { start: 2, end: 4 },
  comment: value,
  time: 1,
  origin: "review",
  preview: "const a = 1",
})

describe("Composer history", () => {
  test("prependHistoryEntry skips empty prompt and deduplicates consecutive entries", () => {
    const first = prependHistoryEntry([], DEFAULT_PROMPT)
    expect(first).toEqual([])

    const commentsOnly = prependHistoryEntry([], DEFAULT_PROMPT, [comment("c1")])
    expect(commentsOnly).toHaveLength(1)

    const withOne = prependHistoryEntry([], text("hello"))
    expect(withOne).toHaveLength(1)

    const deduped = prependHistoryEntry(withOne, text("hello"))
    expect(deduped).toBe(withOne)

    const dedupedComments = prependHistoryEntry(commentsOnly, DEFAULT_PROMPT, [comment("c1")])
    expect(dedupedComments).toBe(commentsOnly)
  })

  test("removeHistoryEntry drops the entry recorded for a prompt and leaves others alone", () => {
    const image: Prompt = [
      { type: "text", content: "look", start: 0, end: 4 },
      { type: "image", id: "img", filename: "big.png", mime: "image/png", blob: { id: "hash", url: "" } },
    ]

    const entries = prependHistoryEntry(prependHistoryEntry([], text("earlier")), image, [comment("c1")])
    expect(entries).toHaveLength(2)

    const untouched = removeHistoryEntry(entries, text("never sent"))
    expect(untouched).toBe(entries)

    const withoutComments = removeHistoryEntry(entries, image)
    expect(withoutComments).toBe(entries)

    const removed = removeHistoryEntry(entries, image, [comment("c1")])
    expect(removed).toEqual(prependHistoryEntry([], text("earlier")))
  })

  test("insertion isolates canonical entries from source mutations", () => {
    const prompt: Prompt = [
      {
        type: "file",
        path: "src/a.ts",
        content: "@src/a.ts",
        start: 0,
        end: 9,
        selection: { startLine: 1, startChar: 0, endLine: 2, endChar: 0 },
      },
    ]

    const comments = [comment("c1")]
    const entries = prependHistoryEntry([], prompt, comments)
    const stored = entries[0]

    if (prompt[0]?.type !== "file" || stored?.prompt[0]?.type !== "file") throw new Error("expected file")
    prompt[0].selection!.startLine = 9
    comments[0].selection.start = 9

    expect(stored.prompt[0].selection?.startLine).toBe(1)
    expect(stored.comments[0]?.selection.start).toBe(2)
  })
})

import type { Prompt } from "@/composer/state"
import type { SelectedLineRange } from "@/workspaces/files/model"
import { clonePrompt, isAttachment } from "../prompt-parts"
import type { PromptHistoryComment, PromptHistoryEntry } from "../schema"

export type { PromptHistoryComment, PromptHistoryEntry } from "../schema"

export const MAX_HISTORY = 100

export type PromptHistoryStoredEntry = PromptHistoryEntry

function cloneSelection(selection: SelectedLineRange): SelectedLineRange {
  return {
    start: selection.start,
    end: selection.end,
    ...(selection.side ? { side: selection.side } : {}),
    ...(selection.endSide ? { endSide: selection.endSide } : {}),
  }
}

export function clonePromptHistoryComments(comments: PromptHistoryComment[]) {
  return comments.map((comment) => ({
    ...comment,
    selection: cloneSelection(comment.selection),
  }))
}

export function prependHistoryEntry(
  entries: PromptHistoryStoredEntry[],
  prompt: Prompt,
  comments: PromptHistoryComment[] = [],
  max = MAX_HISTORY,
) {
  const text = prompt
    .map((part) => ("content" in part ? part.content : ""))
    .join("")
    .trim()

  const hasAttachments = prompt.some(isAttachment)
  const hasComments = comments.some((comment) => !!comment.comment.trim())

  if (!text && !hasAttachments && !hasComments) return entries

  const entry = {
    prompt: clonePrompt(prompt),
    comments: clonePromptHistoryComments(comments),
  } satisfies PromptHistoryEntry

  const last = entries[0]

  if (last && isPromptEqual(last, entry)) return entries

  return [entry, ...entries].slice(0, max)
}

// A send that failed puts its prompt back in the composer, so the entry recorded for it would
// only duplicate the draft and keep its attachments referenced for as long as history holds it.
export function removeHistoryEntry(
  entries: PromptHistoryStoredEntry[],
  prompt: Prompt,
  comments: PromptHistoryComment[] = [],
) {
  const entry = { prompt, comments } satisfies PromptHistoryEntry
  const next = entries.filter((item) => !isPromptEqual(item, entry))

  return next.length === entries.length ? entries : next
}

function isCommentEqual(commentA: PromptHistoryComment, commentB: PromptHistoryComment) {
  return (
    commentA.path === commentB.path &&
    commentA.comment === commentB.comment &&
    commentA.origin === commentB.origin &&
    commentA.preview === commentB.preview &&
    commentA.selection.start === commentB.selection.start &&
    commentA.selection.end === commentB.selection.end &&
    commentA.selection.side === commentB.selection.side &&
    commentA.selection.endSide === commentB.selection.endSide
  )
}

function isPromptEqual(entryA: PromptHistoryStoredEntry, entryB: PromptHistoryStoredEntry) {
  if (entryA.prompt.length !== entryB.prompt.length) return false

  for (let i = 0; i < entryA.prompt.length; i++) {
    const partA = entryA.prompt[i]
    const partB = entryB.prompt[i]

    if (partA.type !== partB.type) return false

    if (partA.type === "text" && partA.content !== (partB.type === "text" ? partB.content : "")) return false

    if (partA.type === "file") {
      if (partA.path !== (partB.type === "file" ? partB.path : "")) return false
      const a = partA.selection
      const b = partB.type === "file" ? partB.selection : undefined

      const sameSelection =
        (!a && !b) ||
        (!!a &&
          !!b &&
          a.startLine === b.startLine &&
          a.startChar === b.startChar &&
          a.endLine === b.endLine &&
          a.endChar === b.endChar)

      if (!sameSelection) return false
    }

    if (partA.type === "agent" && partA.name !== (partB.type === "agent" ? partB.name : "")) return false

    if (partA.type === "skill") {
      if (partB.type !== "skill" || partA.id !== partB.id || partA.name !== partB.name) return false
    }

    if (isAttachment(partA) && partA.id !== (isAttachment(partB) ? partB.id : "")) return false
  }

  if (entryA.comments.length !== entryB.comments.length) return false

  for (let i = 0; i < entryA.comments.length; i++) {
    const commentA = entryA.comments[i]
    const commentB = entryB.comments[i]

    if (!commentA || !commentB || !isCommentEqual(commentA, commentB)) return false
  }

  return true
}

import { type SetStoreFunction, type Store } from "solid-js/store"
import type { Prompt } from "@/composer/state"
import { Persist, persisted } from "@/runtime/persistence/storage"
import {
  clonePromptHistoryComments,
  prependHistoryEntry,
  removeHistoryEntry,
  type PromptHistoryComment,
  type PromptHistoryStoredEntry,
} from "./entry"
import { clonePrompt } from "../prompt-parts"
import { PromptHistoryState } from "../schema"

export type ComposerHistoryStore = {
  entries: (mode: "normal" | "shell") => PromptHistoryStoredEntry[]
  add: (prompt: Prompt, mode: "normal" | "shell", comments: PromptHistoryComment[]) => void
  remove: (prompt: Prompt, mode: "normal" | "shell", comments: PromptHistoryComment[]) => void
}

type PromptHistoryState = typeof PromptHistoryState.Type

function createComposerHistoryStore(
  normal: Store<PromptHistoryState>,
  setNormal: SetStoreFunction<PromptHistoryState>,
  shell: Store<PromptHistoryState>,
  setShell: SetStoreFunction<PromptHistoryState>,
): ComposerHistoryStore {
  return {
    entries: (mode) => (mode === "shell" ? shell.entries : normal.entries),
    add(prompt, mode, comments) {
      const current = mode === "shell" ? shell : normal
      const setCurrent = mode === "shell" ? setShell : setNormal
      const next = prependHistoryEntry(current.entries, prompt, comments)

      if (next === current.entries) return
      setCurrent("entries", next)
    },
    remove(prompt, mode, comments) {
      const current = mode === "shell" ? shell : normal
      const setCurrent = mode === "shell" ? setShell : setNormal
      const next = removeHistoryEntry(current.entries, prompt, comments)

      if (next === current.entries) return
      setCurrent("entries", next)
    },
  }
}

export function createComposerHistory() {
  const [normal, setNormal, normalInit] = persisted(
    Persist.prompt(Persist.global("prompt-history")),
    PromptHistoryState,
    { entries: [] },
  )

  const [shell, setShell, shellInit] = persisted(
    Persist.prompt(Persist.global("prompt-history-shell")),
    PromptHistoryState,
    { entries: [] },
  )

  const history = createComposerHistoryStore(normal, setNormal, shell, setShell)

  return {
    ...history,
    add(prompt: Prompt, mode: "normal" | "shell", comments: PromptHistoryComment[]) {
      const ready = mode === "shell" ? shellInit : normalInit

      if (!(ready instanceof Promise)) return history.add(prompt, mode, comments)
      const saved = clonePrompt(prompt)
      const metadata = clonePromptHistoryComments(comments)
      void ready.then(() => history.add(saved, mode, metadata))
    },
    remove(prompt: Prompt, mode: "normal" | "shell", comments: PromptHistoryComment[]) {
      const ready = mode === "shell" ? shellInit : normalInit

      if (!(ready instanceof Promise)) return history.remove(prompt, mode, comments)
      const saved = clonePrompt(prompt)
      const metadata = clonePromptHistoryComments(comments)
      void ready.then(() => history.remove(saved, mode, metadata))
    },
  }
}

import { ImagePreview } from "@opencode/ui/image-preview"
import { useDialog } from "@opencode/ui/context/dialog"
import type { ReferenceInfo } from "@opencode/client/promise"
import type { Links, MountedSession } from "@opencode/gui-extensions/sdk"
import { createComponent, createEffect, createMemo, on } from "solid-js"
import { Predicate } from "effect"
import type { ComposerSuggestion } from "./types"
import { createComposerEditor, createComposerEditorState, type ComposerEditorModel } from "./editor/interaction"
import { selectionFromLines, type SelectedLineRange, useFile } from "@/workspaces/files/model"
import { useComments } from "@/composer/comments"
import { useCommand } from "@/shell/commands/command"
import { useLanguage } from "@/runtime/i18n/language"
import { useExtensionHost } from "@/runtime/extension/host"
import { useExtensionAttachment } from "@/runtime/extension/host-apis"
import { usePlatform } from "@/runtime/platform/platform"
import { useWorkspaceLocation } from "@/workspaces/location"
import { resolveBlobUrl } from "@/runtime/persistence/drafts"
import { useData, useServer } from "@/runtime/server/current"
import { showToast } from "@/shell/notifications/toast"
import { formatServerError } from "@/runtime/server/errors"
import { Skill } from "@opencode/schema/skill"
import type { ComposerAdapter, ComposerControls, ComposerQueue } from "./adapter"
import { isAttachment } from "./prompt-parts"
import type { PromptHistoryComment } from "./history/entry"
import { createComposerHistory } from "./history/store"
import { createComposerSubmit } from "./submit"
import { useAttachmentDestination } from "./attachments/destination"
import { parseClientSlashCommand } from "./client-slash-command"

export type ComposerModel = ComposerEditorModel & {
  readonly model: ComposerControls["model"]
}

const sendFailedTitle = {
  shell: "prompt.toast.shellSendFailed.title",
  command: "prompt.toast.commandSendFailed.title",
  prompt: "prompt.toast.promptSendFailed.title",
} as const

export function createComposerModel(adapter: ComposerAdapter, options?: { queue?: ComposerQueue }): ComposerModel {
  const sdk = useWorkspaceLocation()
  const data = useData()
  const server = useServer()

  const available = () =>
    server.conn.type !== "extension" || !server.conn.managed || server.ctx.sdk.connection.status() === "connected"

  const files = useFile()
  const links = useExtensionHost().links
  const extensions = useExtensionAttachment()
  const comments = useComments()
  const dialog = useDialog()
  const command = useCommand()
  const language = useLanguage()
  const platform = usePlatform()
  const prompt = adapter.state
  let editor: HTMLDivElement | undefined

  const interaction = createComposerEditorState(prompt.mode.current())
  createEffect(
    on(
      () => (adapter.ready() ? prompt.mode.current() : undefined),
      (mode) => {
        if (!mode) return
        // Project external draft changes without another mode write clearing restored retry metadata.
        interaction[1](mode === "shell" ? { mode, popover: { type: "closed" } } : { mode })
      },
    ),
  )
  const mode = () => interaction[0].mode
  const history = createComposerHistory()

  const recent = createMemo(() => {
    const all = extensions.files.opened()
    const active = extensions.files.active()

    return active ? [active, ...all.filter((path) => path !== active)] : all
  })

  const attachments = createMemo(() => prompt.current().filter(isAttachment))

  const commentCount = createMemo(() => {
    if (mode() === "shell") return 0

    return prompt.context.items().filter((item) => !!item.comment?.trim()).length
  })

  const blank = createMemo(() => {
    const text = prompt
      .current()
      .map((part) => ("content" in part ? part.content : ""))
      .join("")

    return text.trim().length === 0 && attachments().length === 0 && commentCount() === 0
  })

  const stopping = createMemo(() => adapter.working() && blank())

  const placeholder = () => {
    if (mode() === "shell") return language.t("prompt.placeholder.shell", { example: "git status" })

    if (adapter.working() || (options?.queue?.count() ?? 0) > 0)
      return language.t("ui.promptInput.placeholder.followUp", { slash: "/", at: "@" })

    return language.t("ui.promptInput.placeholder.normal", { slash: "/", at: "@" })
  }

  const historyComments = () => {
    const byID = new Map(comments.all().map((item) => [`${item.file}\n${item.id}`, item] as const))

    return prompt.context.items().flatMap((item) => {
      const comment = item.comment?.trim()

      if (!comment || item.type !== "file") return []
      const selection = item.commentID ? byID.get(`${item.path}\n${item.commentID}`)?.selection : undefined

      const nextSelection =
        selection ??
        (item.selection
          ? ({ start: item.selection.startLine, end: item.selection.endLine } satisfies SelectedLineRange)
          : undefined)

      if (!nextSelection) return []

      return [
        {
          id: item.commentID ?? item.key,
          path: item.path,
          selection: { ...nextSelection },
          comment,
          time: item.commentID ? (byID.get(`${item.path}\n${item.commentID}`)?.time ?? Date.now()) : Date.now(),
          origin: item.commentOrigin,
          preview: item.preview,
        } satisfies PromptHistoryComment,
      ]
    })
  }

  const restoreHistoryComments = (items: PromptHistoryComment[]) => {
    comments.replace(
      items.map((item) => ({
        id: item.id,
        file: item.path,
        selection: { ...item.selection },
        comment: item.comment,
        time: item.time,
      })),
    )
    // History records file comments only; notes stay with the draft while it is browsed.
    prompt.context.replaceComments([
      ...prompt.context.items().filter((item) => item.type === "note"),
      ...items.map((item) => ({
        type: "file" as const,
        path: item.path,
        selection: selectionFromLines(item.selection),
        comment: item.comment,
        commentID: item.id,
        commentOrigin: item.origin,
        preview: item.preview,
      })),
    ])
  }

  const referenceDescription = (reference: ReferenceInfo) =>
    reference.source.type === "git" ? reference.source.repository : reference.source.path

  const references = createMemo(() =>
    (data.location.reference.list({ directory: sdk().directory }) ?? [])
      .filter((reference) => !reference.hidden)
      .map((reference) => ({
        id: `reference:${reference.name}`,
        kind: "reference" as const,
        label: `@${reference.name}`,
        path: reference.path,
        description: reference.description ?? referenceDescription(reference),
        mention: {
          type: "file" as const,
          path: reference.path,
          content: `@${reference.name}`,
          start: 0,
          end: 0,
          mime: "application/x-directory",
          filename: reference.name,
        },
      })),
  )

  const skills = createMemo(() => data.location.skill.list({ directory: sdk().directory }) ?? [])

  const context = createMemo<ComposerSuggestion[]>(() => [
    ...references(),
    ...skills().map((skill) => ({
      id: `skill:${skill.id}`,
      kind: "skill" as const,
      label: `@${skill.id}`,
      description: skill.description,
      mention: {
        type: "skill" as const,
        id: Skill.ID.make(skill.id),
        name: Skill.Name.make(skill.name),
        content: `@${skill.id}`,
        start: 0,
        end: 0,
      },
    })),
    ...adapter
      .controls()
      .agents.available.filter((agent) => !agent.hidden && agent.mode !== "primary")
      .map((agent) => ({
        id: `agent:${agent.name}`,
        kind: "agent" as const,
        label: `@${agent.name}`,
        mention: { type: "agent" as const, name: agent.name, content: `@${agent.name}`, start: 0, end: 0 },
      })),
    ...recent().map((path) => ({
      id: `file:${path}`,
      kind: "file" as const,
      label: path,
      path,
      recent: true,
      mention: { type: "file" as const, path, content: `@${path}`, start: 0, end: 0 },
    })),
  ])

  const slashCommands = createMemo(() => [
    ...(data.location.command.list({ directory: sdk().directory }) ?? []).map((item) => ({
      id: `custom.${item.name}`,
      trigger: item.name,
      title: item.name,
      description: item.description,
      type: "custom" as const,
    })),
    ...command.options
      .filter((item) => !item.disabled && !item.id.startsWith("suggested.") && item.slash)
      .map((item) => ({
        id: item.id,
        trigger: item.slash!,
        title: item.title,
        description: item.description,
        arguments: item.slashArguments,
        type: "builtin" as const,
      })),
  ])

  const commands = createMemo<ComposerSuggestion[]>(() => [
    ...slashCommands().map((item) => ({
      id: item.id,
      kind: "command" as const,
      label: `/${item.trigger}`,
      trigger: item.trigger,
      title: item.title,
      description: item.description,
      keybind: command.keybindParts(item.id),
    })),
  ])

  const variants = createMemo(() => ["default", ...adapter.controls().model.selection.variant.list()])

  const submission = createComposerSubmit({
    adapter,
    mode,
    commands: () => data.location.command.list({ directory: sdk().directory }),
    editor: () => editor,
    queueScroll: () => requestAnimationFrame(() => editor?.scrollIntoView({ block: "nearest" })),
    addToHistory: (value, mode) => controller.addHistory(value, mode),
    removeFromHistory: (value, mode, comments) => history.remove(value, mode, mode === "shell" ? [] : comments),
    resetHistory: () => controller.resetHistory(),
    setMode: (next) => controller.dispatch({ type: next === "shell" ? "mode.shell" : "mode.normal" }),
    closePopover: () => controller.dispatch({ type: "popover.close" }),
    delivery: (alternate) => {
      const queue = options?.queue

      if (!queue) return "steer"

      return (alternate ? queue.alternate() : queue.delivery()) ?? "steer"
    },
    notify: {
      missingSelection: () =>
        showToast({
          title: language.t("prompt.toast.modelAgentRequired.title"),
          description: language.t("prompt.toast.modelAgentRequired.description"),
        }),
      unqueueable: () => showToast({ title: language.t("prompt.toast.unqueueable.title") }),
      failed: (kind, error) =>
        showToast({
          title: language.t(sendFailedTitle[kind]),
          description:
            kind === "command"
              ? formatServerError(error, language.t, language.t("common.requestFailed"))
              : composerErrorMessage(language, error),
        }),
    },
    comments: {
      capture: historyComments,
      clear: comments.clear,
      restore: restoreHistoryComments,
    },
    clientCommand: (text) => {
      const selected = parseClientSlashCommand(slashCommands(), text)

      if (!selected) return

      return () => command.trigger(selected.id, "slash", selected.input)
    },
  })

  const controller = createComposerEditor({
    store: prompt.store,
    state: interaction,
    history: {
      entries: (mode) => history.entries(mode).map((entry) => ({ prompt: entry.prompt, metadata: entry.comments })),
      add: (value, mode) => history.add(value, mode, mode === "shell" ? [] : historyComments()),
      capture: historyComments,
      // SAFETY: `entries` stores each entry's comments as its metadata, and the editor restores only metadata it read there.
      restore: (metadata) => restoreHistoryComments(metadata as PromptHistoryComment[]),
    },
    commands,
    context,
    searchContextFiles: async (query) =>
      (await files.searchFilesAndDirectories(query)).map((path) => ({
        id: `file:${path}`,
        kind: "file",
        label: path,
        path,
        mention: { type: "file", path, content: `@${path}`, start: 0, end: 0 },
      })),
    onContextRemove(item) {
      if (item.type === "file" && item.commentID) comments.remove(item.path, item.commentID)
    },
    openAttachment: (attachment) => {
      if (attachment.type !== "image") return
      void resolveBlobUrl(attachment.blob).then((src) => {
        if (src) dialog.show(() => createComponent(ImagePreview, { src, alt: attachment.filename }))
      })
    },
    openContext(key) {
      const item = controller.contextItem(key)

      if (item?.type === "note") {
        // The extension that attached the note reveals its subject.
        const href = item.live?.href ?? item.href

        if (href) links.open({ href, origin: item.origin, session: extensions.current() })

        return
      }

      if (item) openComment(item, links, extensions.current(), files, comments)
    },
    onEditor(element) {
      // SAFETY: the editor's only `setEditor` call passes its editable root, a `<div>` (`editor/editor.tsx`).
      editor = element as HTMLDivElement

      if (adapter.kind === "active-session") adapter.setEditor(editor)
    },
    onSuggestionSelect(item) {
      if (item.kind !== "command") return
      const selected = slashCommands().find((entry) => entry.id === item.id)

      if (!selected || selected.type === "custom") return

      if (selected.arguments) return

      return () => command.trigger(selected.id, "slash")
    },
    attachments: {
      picker: platform.openAttachmentPickerDialog,
      directory: () => sdk().directory,
      destination: useAttachmentDestination(adapter.controls),
      isDialogActive: () => !!dialog.active,
      duplicate: () => showToast({ title: language.t("prompt.toast.attachmentDuplicate.title") }),
      onUploadError: (error) =>
        showToast({
          variant: "error",
          title: language.t("prompt.toast.uploadFailed.title"),
          description: composerErrorMessage(language, error),
        }),
      onError: (error) =>
        showToast({
          variant: "error",
          title: language.t("common.requestFailed"),
          description: error instanceof Error ? error.message : String(error),
        }),
      readClipboardImage: platform.readClipboardImage,
      getPathForFile: platform.getPathForFile,
      onDragCancel: platform.onDragCancel,
      store: platform.draftStore?.putBlob,
    },
    view: {
      placeholder,
      get agent() {
        const agents = adapter.controls().agents

        return agents.visible && agents.options.length > 0
          ? {
              options: () => adapter.controls().agents.options.map((name) => ({ id: name, label: name })),
              current: () => adapter.controls().agents.current,
              onSelect: (value: string) => adapter.controls().agents.select(value),
              keybind: () => command.keybindParts("agent.cycle"),
            }
          : undefined
      },
      variant: {
        options: () => variants().map((value) => ({ id: value, label: value })),
        current: () => adapter.controls().model.selection.variant.current() ?? "default",
        onSelect: (value) => adapter.controls().model.selection.variant.set(value === "default" ? undefined : value),
        keybind: () => command.keybindParts("model.variant.cycle"),
      },
      submit: {
        available,
        stopping,
        working: adapter.working,
        queue: options?.queue,
        onSubmit: (submitOptions) => {
          if (!available()) return
          const queue = options?.queue

          if (queue?.undoing()) return

          // Confirming an edit re-admits the queued prompt instead of sending
          // the composer value as a new prompt. Enter keeps it queued in
          // place; the alternate action sends it as a steer.
          if (queue?.editing()) {
            queue.confirmEdit(submitOptions?.alternate ? "steer" : "queue")

            return
          }

          void submission.submit(new Event("submit"), submitOptions)
        },
        onStop: () => void submission.stop(),
      },
    },
  })

  Object.defineProperty(controller, "model", { get: () => adapter.controls().model })

  command.register("composer-editor", () => [
    {
      id: "file.attach",
      title: language.t("prompt.action.attachFile"),
      category: language.t("command.category.file"),
      keybind: "mod+u",
      editable: true,
      disabled: controller.state.mode !== "normal",
      onSelect: () => controller.attach(),
    },
    {
      id: "prompt.mode.shell",
      title: language.t("command.prompt.mode.shell"),
      category: language.t("command.category.session"),
      keybind: "mod+shift+x",
      disabled: controller.state.mode === "shell",
      onSelect: () => void controller.dispatch({ type: "mode.shell" }),
    },
    {
      id: "prompt.mode.normal",
      title: language.t("command.prompt.mode.normal"),
      category: language.t("command.category.session"),
      keybind: "mod+shift+e",
      disabled: controller.state.mode === "normal",
      onSelect: () => void controller.dispatch({ type: "mode.normal" }),
    },
  ])

  // SAFETY: the `model` getter defined on the controller above completes `ComposerModel`.
  return controller as ComposerModel
}

function composerErrorMessage(language: ReturnType<typeof useLanguage>, cause: unknown) {
  if (Predicate.hasProperty(cause, "message") && Predicate.isString(cause.message)) return cause.message

  if (
    Predicate.hasProperty(cause, "data") &&
    Predicate.hasProperty(cause.data, "message") &&
    Predicate.isString(cause.data.message) &&
    cause.data.message
  )
    return cause.data.message

  return language.t("common.requestFailed")
}

function openComment(
  item: { path: string; commentID?: string; commentOrigin?: "review" | "file" },
  links: Links,
  session: MountedSession | undefined,
  files: ReturnType<typeof useFile>,
  comments: ReturnType<typeof useComments>,
) {
  if (!item.commentID) return
  const focus = { file: item.path, id: item.commentID }
  comments.setActive(focus)

  const queueFocus = (attempts = 6) => {
    requestAnimationFrame(() => {
      comments.setFocus({ ...focus })

      if (attempts <= 0) return
      requestAnimationFrame(() => {
        const current = comments.focus()

        if (current?.file === focus.file && current.id === focus.id) queueFocus(attempts - 1)
      })
    })
  }

  // The extension that owns the comment's origin reveals it (the review diff or a file tab), keeping the conversation.
  links.open({ href: item.path, origin: item.commentOrigin, exact: true, background: true, session })

  if (item.commentOrigin === "review") return queueFocus()
  void Promise.resolve(files.load(item.path)).finally(() => queueFocus())
}

import { base64Encode } from "@opencode/util/encode"
import { createSimpleContext } from "@opencode/ui/context"
import { useParams, useSearchParams } from "@solidjs/router"
import { createMemo, createResource, createRoot, getOwner, onCleanup } from "solid-js"
import { requireServerKey } from "@/shell/routes/session"
import { ServerConnection } from "@/runtime/server/registry"
import { useServerSDK } from "@/runtime/server/client"
import { useWorkspaceLocation } from "@/workspaces/location"
import { useTabs, type Tab } from "@/shell/tabs/tabs"
import type { ServerScope } from "@/runtime/server/scope"
import {
  createComposerReady,
  createComposerState,
  type ContextItem,
  type Prompt,
  type PromptModel,
  type PromptScope,
  type ComposerState,
} from "./state"

export {
  createComposerReady,
  createComposerState,
  createMemoryComposerState,
  DEFAULT_PROMPT,
  isCommentItem,
} from "./state"

export type {
  AgentPart,
  ContentPart,
  ContextItem,
  FileAttachmentPart,
  FileContextItem,
  ImageAttachmentPart,
  Prompt,
  PromptModel,
  ComposerStore,
  PromptScope,
  ComposerState,
  TextPart,
} from "./state"

const WORKSPACE_KEY = "__workspace__"

const MAX_PROMPT_SESSIONS = 20

export function selectPromptTab(tabs: Tab[], scope: PromptScope, server: ServerConnection.Key) {
  if ("draftID" in scope) return tabs.find((tab) => tab.type === "draft" && tab.draftID === scope.draftID)

  if (!scope.id) return

  return (
    tabs.find((tab) => tab.type === "session" && tab.server === server && tab.sessionId === scope.id) ??
    ({ type: "session", server, sessionId: scope.id } satisfies Tab)
  )
}

function scopeKey(scope: PromptScope) {
  if ("draftID" in scope) return `draft:${scope.draftID}`

  return `${scope.dir}:${scope.id ?? WORKSPACE_KEY}`
}

type ComposerCacheEntry = {
  value: ComposerState
  dispose: VoidFunction
}

export const createTabComposerState = (
  tabs: ReturnType<typeof useTabs>,
  tab: Tab,
  ...args: Parameters<typeof createComposerState>
) => tabs.state(tab, "prompt", () => createComposerState(...args))

export const { use: useComposerState, provider: ComposerPersistenceProvider } = createSimpleContext({
  name: "ComposerState",
  gate: false,
  init: () => {
    const params = useParams<{ serverKey?: string; id?: string }>()
    const sdk = useWorkspaceLocation()
    const [search] = useSearchParams<{ draftId?: string }>()
    const serverSDK = useServerSDK()
    const tabs = useTabs()
    const cache = new Map<string, ComposerCacheEntry>()

    const disposeAll = () => {
      for (const entry of cache.values()) entry.dispose()
      cache.clear()
    }

    onCleanup(disposeAll)

    const prune = () => {
      while (cache.size > MAX_PROMPT_SESSIONS) {
        const first = cache.keys().next().value

        if (!first) return
        const entry = cache.get(first)
        entry?.dispose()
        cache.delete(first)
      }
    }

    const owner = getOwner()

    const serverKey = () =>
      params.serverKey ? requireServerKey(params.serverKey) : ServerConnection.key(serverSDK.server)

    const scope = (): PromptScope =>
      search.draftId ? { draftID: search.draftId } : { dir: base64Encode(sdk().directory), id: params.id }

    const load = (scope: PromptScope, target?: { server?: ServerConnection.Key; scope: ServerScope }) => {
      const current = selectPromptTab(tabs.store, scope, target?.server ?? serverKey())

      if (current) return createTabComposerState(tabs, current, target?.scope ?? serverSDK.scope, scope)

      const key = target ? `${target.scope}:${scopeKey(scope)}` : scopeKey(scope)
      const existing = cache.get(key)

      if (existing) {
        cache.delete(key)
        cache.set(key, existing)

        return existing.value
      }

      const entry = createRoot(
        (dispose) => ({
          value: createComposerState(target?.scope ?? serverSDK.scope, scope),
          dispose,
        }),
        owner,
      )

      cache.set(key, entry)
      prune()

      return entry.value
    }

    const session = createMemo(() => load(scope()))

    const pick = (scope?: PromptScope, target?: { server?: ServerConnection.Key; scope: ServerScope }) =>
      scope ? load(scope, target) : session()

    const ready = createComposerReady(session)

    const withSuspense = <T,>(cb: () => T): (() => T) =>
      createResource(
        async () => {
          const value = cb()
          await session().ready.promise

          return value
        },
        cb,
        { initialValue: cb() },
      )[0]

    return {
      ready,
      capture: (scope?: PromptScope, target?: { server?: ServerConnection.Key; scope: ServerScope }) =>
        pick(scope, target).capture(),
      current: withSuspense(() => session().current()),
      cursor: withSuspense(() => session().cursor()),
      model: {
        current: withSuspense(() => session().model.current()),
        set: (model: PromptModel | undefined) => session().model.set(model),
      },
      context: {
        items: withSuspense(() => session().context.items()),
        add: (item: ContextItem) => session().context.add(item),
        remove: (key: string) => session().context.remove(key),
        removeComment: (commentID: string) => session().context.removeComment(commentID),
        updateComment: (commentID: string, next: { readonly comment?: string; readonly preview?: string }) =>
          session().context.updateComment(commentID, next),
        replaceComments: (items: ContextItem[]) => session().context.replaceComments(items),
      },
      set: (prompt: Prompt, cursorPosition?: number, scope?: PromptScope) => pick(scope).set(prompt, cursorPosition),
      reset: (scope?: PromptScope) => pick(scope).reset(),
    }
  },
})

import type { ContentPart, ImageAttachmentPart, PathAttachmentPart, Prompt } from "./state"

/** Parts that sit beside the text rather than inside it. */
export function isAttachment(part: ContentPart): part is ImageAttachmentPart | PathAttachmentPart {
  return part.type === "image" || part.type === "path"
}

export function clonePrompt(prompt: Prompt): Prompt {
  return prompt.map((part) =>
    part.type === "file" ? { ...part, selection: part.selection ? { ...part.selection } : undefined } : { ...part },
  )
}

export function promptLength(prompt: Prompt) {
  return prompt.reduce((length, part) => length + ("content" in part ? part.content.length : 0), 0)
}

export function appendPrompt(prompt: Prompt, following: Prompt): Prompt {
  const start = promptLength(prompt)
  const offset = start + 2

  return [
    ...clonePrompt(prompt),
    { type: "text", content: "\n\n", start, end: offset },
    ...clonePrompt(following).map((part) =>
      isAttachment(part) ? part : { ...part, start: part.start + offset, end: part.end + offset },
    ),
  ]
}

