    { dir: "C:\\current\\project", path: "D:\\other\\project\\file.ts", uri: "file:///D:/other/project/file.ts" },
    {
      dir: "C:\\project",
      path: "src\\App.tsx",
      selection: { startLine: 10, startChar: 0, endLine: 20, endChar: 5 },
