    },
    // `..` stays for the backend to normalize.
    {
      dir: "C:\\projects\\myapp\\src",
      path: "..\\..\\shared\\util.ts",
      uri: "file:///C:/projects/myapp/src/../../shared/util.ts",
    },
    {
      dir: "D:\\workspace\\app",
      path: "src\\utils\\helper.ts",
