      images: [],
      text: row.context ? "" : `@${row.path}`,
      sessionDirectory: row.dir,
    })

    expect(result.files.map((file) => file.uri)).toEqual([row.uri])
  })
})

import { encodeFilePath, getFilename } from "@opencode/util/path"
import type { FileSelection } from "@/workspaces/files/model"
import type {
  AgentPart,
  ContextItem,
  FileAttachmentPart,
  ImageAttachmentPart,
  NoteComment,
  NoteContextItem,
  PathAttachmentPart,
  Prompt,
  SkillPart,
} from "@/composer/state"
import {
  formatAttachmentReference,
  formatCommentNote,
  formatNoteComment,
  type PromptAttachmentReference,
  type PromptComment,
} from "@/composer/comment-note"

// Network fields feed both boundaries; display fields keep desktop-only rendering details in the local echo.
type PromptRequest = {
  text: string
  displayText: string
  files: {
    uri: string
    mime: string
    name?: string
    description?: string
    mention?: { start: number; end: number; text: string }
  }[]
  agents: { name: string; mention?: { start: number; end: number; text: string } }[]
  skills: { id: string; name: string; mention?: { start: number; end: number; text: string } }[]
  comments: PromptComment[]
  attachments: PromptAttachmentReference[]
}

type BuildPromptRequestInput = {
  prompt: Prompt
  context: (ContextItem & { key: string })[]
  images: (Omit<ImageAttachmentPart, "blob"> & { dataUrl: string })[]
  text: string
  sessionDirectory: string
}

const absolute = (directory: string, path: string) => {
  if (path.startsWith("/")) return path

  if (/^[A-Za-z]:[\\/]/.test(path) || /^[A-Za-z]:$/.test(path)) return path

  if (path.startsWith("\\\\") || path.startsWith("//")) return path

  return `${directory.replace(/[\\/]+$/, "")}/${path}`
}

const fileQuery = (selection: FileSelection | undefined) =>
  selection ? `?start=${selection.startLine}&end=${selection.endLine}` : ""

const mention = /(^|[\s([{"'])@(\S+)/g

const parseCommentMentions = (comment: string) => {
  return Array.from(comment.matchAll(mention)).flatMap((match) => {
    const path = (match[2] ?? "").replace(/[.,!?;:)}\]"']+$/, "")

    if (!path) return []

    return [path]
  })
}

const isFileAttachment = (part: Prompt[number]): part is FileAttachmentPart => part.type === "file"

const isAgentAttachment = (part: Prompt[number]): part is AgentPart => part.type === "agent"

const isSkillAttachment = (part: Prompt[number]): part is SkillPart => part.type === "skill"

const isPathAttachment = (part: Prompt[number]): part is PathAttachmentPart => part.type === "path"

/** The sent form of a note: its optional link and live subject travel only when present. */
export function noteComment(item: NoteContextItem, comment: string) {
  const note: NoteComment = {
    type: "note",
    origin: item.origin,
    label: item.label,
    icon: item.icon,
    subject: item.subject,
    comment,
  }

  if (item.href) note.href = item.href

  if (item.live) note.live = { ...item.live }

  return note
}

export function buildPromptRequest(input: BuildPromptRequestInput): PromptRequest {
  const skills = input.prompt.filter(isSkillAttachment).map((attachment) => ({
    id: attachment.id,
    name: attachment.name,
    mention: { start: attachment.start, end: attachment.end, text: attachment.content },
  }))

  const files = input.prompt.filter(isFileAttachment).map((attachment) => {
    const path = absolute(input.sessionDirectory, attachment.path)

    return {
      uri: attachment.url ?? `file://${encodeFilePath(path)}${fileQuery(attachment.selection)}`,
      mime: attachment.mime ?? "text/plain",
      name: attachment.filename ?? getFilename(attachment.path),
      description: attachment.description,
      mention: { start: attachment.start, end: attachment.end, text: attachment.content },
    }
  })

  const agents = input.prompt.filter(isAgentAttachment).map((attachment) => ({
    name: attachment.name,
    mention: { start: attachment.start, end: attachment.end, text: attachment.content },
  }))

  const used = new Set(files.map((file) => file.uri))
  const comments: PromptComment[] = []

  const mentioned = (comment: string) =>
    parseCommentMentions(comment).flatMap((path) => {
      const uri = `file://${encodeFilePath(absolute(input.sessionDirectory, path))}`

      if (used.has(uri)) return []
      used.add(uri)

      return [{ uri, mime: "text/plain", name: getFilename(path) }]
    })

  const context = input.context.flatMap((item) => {
    if (item.type === "note") {
      const comment = item.comment.trim()

      if (!comment) return []
      comments.push(noteComment(item, comment))

      return mentioned(comment)
    }

    const path = absolute(input.sessionDirectory, item.path)
    const uri = `file://${encodeFilePath(path)}${fileQuery(item.selection)}`
    const comment = item.comment?.trim()

    if (!comment && used.has(uri)) return []
    used.add(uri)

    const file = { uri, mime: "text/plain", name: item.name ?? getFilename(item.path), description: item.description }

    if (!comment) return [file]

    comments.push({
      path: item.path,
      selection: item.selection,
      comment,
      preview: item.preview,
      origin: item.commentOrigin,
    })

    return [file, ...mentioned(comment)]
  })

  const inline = input.images.map((attachment) => ({
    uri: attachment.dataUrl,
    mime: attachment.mime,
    name: attachment.sourcePath ?? attachment.filename,
  }))

  // Like comments, path references reach the model as text and the message UI through metadata.
  const attachments = input.prompt
    .filter(isPathAttachment)
    .map((part) => ({ name: part.filename, mime: part.mime, path: part.path }))

  return {
    text: [
      ...(input.text.trim() ? [input.text] : []),
      ...attachments.map(formatAttachmentReference),
      ...comments.map((comment) => (comment.type === "note" ? formatNoteComment(comment) : formatCommentNote(comment))),
    ].join("\n"),
    displayText: input.text,
    files: [...files, ...context, ...inline],
    agents,
    skills,
    comments,
    attachments,
  }
}

import { describe, expect, test } from "bun:test"
import { Schema } from "effect"
import { Persistence } from "@/runtime/persistence/schema"
import { SessionMessage } from "@opencode/schema/session-message"
import {
  CommentStore,
  ComposerStore,
  DEFAULT_PROMPT,
  PromptHistoryState,
  type TextPart,
  type ImageAttachmentPart,
  type FileAttachmentPart,
  type LineComment,
} from "./schema"

const text: TextPart = { type: "text", content: "hello", start: 0, end: 5 }

const image: Omit<ImageAttachmentPart, "blob"> = {
  type: "image",
  id: "image",
  filename: "image.png",
  mime: "image/png",
}

const comment = { id: "comment", path: "src/app.ts", selection: { start: 1, end: 2 }, comment: "note", time: 1 }

const decode = Schema.decodeUnknownSync(
  Persistence.withInitial(ComposerStore, { prompt: DEFAULT_PROMPT, context: { items: [] } }),
)

describe("composer persistence schemas", () => {
  test("defaults missing or invalid fields independently and normalizes the cursor", () => {
    expect(decode({})).toEqual({ prompt: DEFAULT_PROMPT, context: { items: [] } })
    const selection = { startLine: 1, startChar: 0, endLine: 2, endChar: 3 }

    const value = decode({
      prompt: [null, { type: "unknown" }],
      cursor: -1,
      mode: "unknown",
      model: { providerID: 42, modelID: "model" },
      retry: { id: "bad", agent: "build", providerID: "provider", modelID: "model" },
      context: {
        items: [
          { type: "file", path: "src/app.ts", commentID: "note", key: "stale" },
          null,
          { type: "file", path: "src/app.ts", selection, comment: "Check this", key: "untrusted" },
          { type: "file", path: 42 },
        ],
      },
    })

    expect(value.prompt).toEqual(DEFAULT_PROMPT)
    expect(value.cursor).toBe(0)
    expect(value.mode).toBeUndefined()
    expect(value.model).toBeUndefined()
    expect(value.retry).toBeUndefined()
    expect(value.context.items).toEqual([
      { type: "file", path: "src/app.ts", commentID: "note", key: "file:src/app.ts:undefined:undefined:c=note" },
      // A comment without an ID is keyed by a digest of its text.
      {
        type: "file",
        path: "src/app.ts",
        selection,
        comment: "Check this",
        key: expect.stringMatching(/^file:src\/app\.ts:1:2:c=/),
      },
    ])
    expect(decode({ prompt: false, cursor: Infinity, context: null })).toEqual({
      prompt: DEFAULT_PROMPT,
      context: { items: [] },
    })
    const first = decode({})
    first.prompt[0] = { type: "text", content: "changed", start: 0, end: 7 }
    expect(decode({}).prompt).toEqual(DEFAULT_PROMPT)
  })

  test("restores extension notes and legacy browser comments without their process-bound refs", () => {
    const durable = {
      type: "note" as const,
      origin: "example",
      label: "button#save",
      icon: "select-element",
      subject: 'the "button#save" element',
      href: "tab_00000000-0000-4000-8000-000000000000",
      comment: "Rename this",
      commentID: "note",
    }

    const note = {
      ...durable,
      live: { subject: 'the "button#save" element (browser ref @e42)', href: `${durable.href}#e42` },
    }

    // A draft stored by a build before extension notes, as its composer schema encoded it.
    const browser = {
      type: "browser" as const,
      tabID: "tab_00000000-0000-4000-8000-000000000000",
      url: "http://localhost:5173/",
      element: { ref: "e42", selector: "#save", label: "button#save", role: 42 },
      comment: "Rename this",
      commentID: "picked",
      key: "browser:tab_00000000-0000-4000-8000-000000000000:c=picked",
    }

    const value = decode({ context: { items: [note, { ...note, subject: null }, browser, { ...browser, url: null }] } })
    expect(value.context.items).toEqual([
      { ...durable, key: "note:example:c=note" },
      {
        type: "note",
        origin: "browser",
        label: "button#save",
        icon: "select-element",
        subject:
          'the "button#save" element in browser tab tab_00000000-0000-4000-8000-000000000000 at http://localhost:5173/ (selector "#save")',
        href: "tab_00000000-0000-4000-8000-000000000000",
        comment: "Rename this",
        commentID: "picked",
        key: "note:browser:c=picked",
      },
    ])
  })

  test("drops invalid parts without losing valid mentions or optional field recovery", () => {
    const value = decode({
      prompt: [
        text,
        { type: "agent", content: "@build", start: 5, end: 11, name: "build" },
        { type: "skill", content: "@effect", start: 11, end: 18, id: "effect", name: "Effect" },
        { type: "agent", content: "@broken", start: 18, end: 25, name: 42 },
        {
          type: "file",
          path: "src/app.ts",
          content: "@src/app.ts",
          start: 18,
          end: 29,
          selection: { startLine: "broken" },
          mime: 42,
          filename: "app.ts",
          source: { type: "invalid" },
        },
      ],
      model: { providerID: "provider", modelID: "model", variant: null },
      retry: { id: "msg_retry", agent: "build", providerID: "provider", modelID: "model", variant: false },
    })

    expect(value.prompt.map((part) => part.type)).toEqual(["text", "agent", "skill", "file"])
    expect(value.prompt[3]).toEqual({
      type: "file",
      path: "src/app.ts",
      content: "@src/app.ts",
      start: 18,
      end: 29,
      filename: "app.ts",
    })
    expect(value.model?.variant).toBeNull()
    expect(value.retry).toEqual({
      id: SessionMessage.ID.make("msg_retry"),
      agent: "build",
      providerID: "provider",
      modelID: "model",
    })
    expect(decode(Schema.encodeSync(ComposerStore)(value))).toEqual(value)
  })

  test("preserves file source variants through canonical round trips", () => {
    const sourceText = { value: "@source", start: 0, end: 7 }

    const sources: NonNullable<FileAttachmentPart["source"]>[] = [
      { type: "file", path: "src/app.ts", text: sourceText },
      { type: "resource", clientName: "docs", uri: "docs://example", text: sourceText },
      {
        type: "symbol",
        path: "src/app.ts",
        name: "App",
        kind: 1,
        range: { start: { line: 1, character: 0 }, end: { line: 2, character: 1 } },
        text: sourceText,
      },
    ]

    const value = decode({
      prompt: sources.map((source) => ({
        type: "file",
        path: "src/app.ts",
        content: "@source",
        start: 0,
        end: 7,
        source,
        selection: { startLine: 1, startChar: 0, endLine: 2, endChar: 1 },
      })),
    })

    expect(value.prompt).toHaveLength(3)
    expect(value.prompt.map((part) => part.type === "file" && part.source)).toEqual(sources)
    expect(decode(Schema.encodeSync(ComposerStore)(value))).toEqual(value)
  })

  test("migrates inline images, keeps store references without a URL, and never encodes dataUrl", () => {
    const value = decode({
      prompt: [
        { ...image, dataUrl: "data:image/png;base64,YQ==", sourcePath: "/image.png" },
        { ...image, blob: { id: "data:image/png;base64,Yg==" } },
        { ...image, blob: { id: "hash", url: "blob:hydrated" } },
        { ...image, blob: { id: "missing" } },
        { ...image, blob: { id: "bad", url: "https://example.com/image.png" } },
        { ...image, blob: { id: "missing" }, dataUrl: "data:image/png;base64,YQ==" },
        { ...image, blob: { id: 42 } },
      ],
    })

    expect(value.prompt).toHaveLength(6)
    expect(value.prompt[0]).toEqual({
      ...image,
      sourcePath: "/image.png",
      blob: { id: "data:image/png;base64,YQ==", url: "data:image/png;base64,YQ==" },
    })
    // Bytes still in the draft store resolve on use; a non-blob URL is discarded in favour of the id.
    expect(value.prompt[3]).toEqual({ ...image, blob: { id: "missing", url: "" } })
    expect(value.prompt[4]).toEqual({ ...image, blob: { id: "bad", url: "" } })
    expect(value.prompt[5]).toEqual({ ...image, blob: { id: "missing", url: "" } })
    const encoded = Schema.encodeSync(ComposerStore)(value)
    expect(JSON.stringify(encoded)).not.toContain("dataUrl")
    expect(decode(encoded)).toEqual(value)
  })

  test("migrates legacy history arrays and recovers entries, parts, and comments independently", () => {
    const value = Schema.decodeUnknownSync(Persistence.withInitial(PromptHistoryState, { entries: [] }))({
      entries: [
        [text, null, { ...image, dataUrl: "data:image/png;base64,YQ==" }],
        null,
        {},
        { prompt: false, comments: [] },
        { prompt: [text, { type: "invalid" }], comments: [comment, { ...comment, selection: null }, false] },
        { prompt: [text], comments: false },
      ],
    })

    expect(value.entries).toHaveLength(3)
    expect(value.entries[0].prompt).toHaveLength(2)
    expect(value.entries[0].comments).toEqual([])
    expect(value.entries[1]).toEqual({ prompt: [text], comments: [comment] })
    expect(value.entries[2]).toEqual({ prompt: [text], comments: [] })
    const encoded = Schema.encodeSync(PromptHistoryState)(value)
    expect(encoded.entries?.every((entry) => !Array.isArray(entry))).toBe(true)
    expect(JSON.stringify(encoded)).not.toContain("dataUrl")
    expect(Schema.decodeUnknownSync(Persistence.withInitial(PromptHistoryState, { entries: [] }))(encoded)).toEqual(
      value,
    )
    expect(
      Schema.decodeUnknownSync(Persistence.withInitial(PromptHistoryState, { entries: [] }))({ entries: "invalid" }),
    ).toEqual({ entries: [] })
  })

  test("recovers comments per file and entry without discarding healthy siblings", () => {
    const line: LineComment = {
      id: "comment",
      file: "src/app.ts",
      selection: { start: 1, end: 2, side: "additions", endSide: "deletions" },
      comment: "note",
      time: 1,
    }

    const value = Schema.decodeUnknownSync(Persistence.withInitial(CommentStore, { comments: {} }))({
      comments: {
        "src/app.ts": [line, null, { ...line, time: "bad" }, { ...line, selection: { start: 2, end: 4, side: "bad" } }],
        "broken.ts": { invalid: true },
        "healthy.ts": [{ ...line, file: "healthy.ts" }],
      },
    })

    expect(value.comments["src/app.ts"]).toEqual([line, { ...line, selection: { start: 2, end: 4 } }])
    expect(value.comments["broken.ts"]).toEqual([])
    expect(value.comments["healthy.ts"]).toEqual([{ ...line, file: "healthy.ts" }])
    expect(
      Schema.decodeUnknownSync(Persistence.withInitial(CommentStore, { comments: {} }))(
        Schema.encodeSync(CommentStore)(value),
      ),
    ).toEqual(value)
    expect(Schema.decodeUnknownSync(Persistence.withInitial(CommentStore, { comments: {} }))({})).toEqual({
      comments: {},
    })
    expect(Schema.decodeUnknownSync(Persistence.withInitial(CommentStore, { comments: {} }))({ comments: [] })).toEqual(
      { comments: {} },
    )
  })
})

import { Schema, SchemaGetter, Struct } from "effect"
import { checksum } from "@opencode/util/encode"
import { SessionMessage } from "@opencode/schema/session-message"
import { Skill } from "@opencode/schema/skill"
import { Persistence } from "@/runtime/persistence/schema"
import { FileSelection, SelectedLineRange } from "@/workspaces/files/types"

const PartBase = {
  content: Schema.String,
  start: Schema.Number,
  end: Schema.Number,
}

const SourceText = Schema.Struct({ value: Schema.String, start: Schema.Number, end: Schema.Number })

const Position = Schema.Struct({ line: Schema.Number, character: Schema.Number })

const FilePartSource = Schema.Union([
  Schema.Struct({ type: Schema.Literal("file"), text: SourceText, path: Schema.String }),
  Schema.Struct({
    type: Schema.Literal("symbol"),
    text: SourceText,
    path: Schema.String,
    range: Schema.Struct({ start: Position, end: Position }),
    name: Schema.String,
    kind: Schema.Number,
  }),
  Schema.Struct({ type: Schema.Literal("resource"), text: SourceText, clientName: Schema.String, uri: Schema.String }),
])

export const TextPart = Persistence.struct({ type: Schema.Literal("text"), ...PartBase })

export type TextPart = typeof TextPart.Type

export const FileAttachmentPart = Persistence.struct({
  type: Schema.Literal("file"),
  ...PartBase,
  path: Schema.String,
  selection: Persistence.optional(FileSelection),
  mime: Persistence.optional(Schema.String),
  filename: Persistence.optional(Schema.String),
  description: Persistence.optional(Schema.String),
  url: Persistence.optional(Schema.String),
  source: Persistence.optional(FilePartSource),
})

export type FileAttachmentPart = typeof FileAttachmentPart.Type

export const AgentPart = Persistence.struct({ type: Schema.Literal("agent"), ...PartBase, name: Schema.String })

export type AgentPart = typeof AgentPart.Type

export const SkillPart = Persistence.struct({
  type: Schema.Literal("skill"),
  ...PartBase,
  id: Skill.ID,
  name: Skill.Name,
})

export type SkillPart = typeof SkillPart.Type

const ImageFields = {
  type: Schema.Literal("image"),
  id: Schema.String,
  filename: Schema.String,
  sourcePath: Persistence.optional(Schema.String),
  mime: Schema.String,
}

const Image = Persistence.struct({
  ...ImageFields,
  // An empty URL is an image whose bytes are still in the draft store; see `resolveBlobUrl`.
  blob: Schema.Struct({ id: Schema.NonEmptyString, url: Schema.String.check(Schema.isPattern(/^(blob:|data:|$)/)) }),
})

// Draft storage keeps content-addressed blobs in the store until an image is shown or sent; a
// reference without a URL resolves through `resolveBlobUrl`. Legacy inline data remains usable.
export const ImageAttachmentPart = Schema.Struct({
  ...ImageFields,
  blob: Persistence.optional(
    Schema.Struct({ id: Persistence.optional(Schema.String), url: Persistence.optional(Schema.String) }),
  ),
  dataUrl: Persistence.optional(Schema.String),
}).pipe(
  Schema.decodeTo(Schema.toType(Image), {
    decode: SchemaGetter.transform((value) => {
      const id = value.blob?.id ?? value.dataUrl ?? ""
      const url = value.blob?.url

      return {
        type: value.type,
        id: value.id,
        filename: value.filename,
        sourcePath: value.sourcePath,
        mime: value.mime,
        blob: {
          id,
          url: url?.startsWith("blob:") || url?.startsWith("data:") ? url : id.startsWith("data:") ? id : "",
        },
      }
    }),
    encode: SchemaGetter.transform((value) => value),
  }),
)

export type ImageAttachmentPart = typeof ImageAttachmentPart.Type

// A file the model receives as a path on the server: its bytes never enter the draft store.
export const PathAttachmentPart = Persistence.struct({
  type: Schema.Literal("path"),
  id: Schema.String,
  filename: Schema.String,
  mime: Schema.String,
  path: Schema.String,
})

export type PathAttachmentPart = typeof PathAttachmentPart.Type

export const ContentPart = Schema.Union([
  TextPart,
  FileAttachmentPart,
  AgentPart,
  SkillPart,
  ImageAttachmentPart,
  PathAttachmentPart,
])

export type ContentPart = typeof ContentPart.Type

export const Prompt = Persistence.array(ContentPart)

export type Prompt = typeof Prompt.Type

export const PromptModel = Persistence.struct({
  providerID: Schema.String,
  modelID: Schema.String,
  variant: Persistence.optional(Schema.NullOr(Schema.String)),
})

export type PromptModel = typeof PromptModel.Type

export const FileContextItem = Persistence.struct({
  type: Schema.Literal("file"),
  path: Schema.String,
  selection: Persistence.optional(FileSelection),
  comment: Persistence.optional(Schema.String),
  commentID: Persistence.optional(Schema.String),
  commentOrigin: Persistence.optional(Schema.Literals(["review", "file"])),
  preview: Persistence.optional(Schema.String),
  // A file restored from a sent prompt keeps the name and description it was sent with.
  name: Persistence.optional(Schema.String),
  description: Persistence.optional(Schema.String),
})

export type FileContextItem = typeof FileContextItem.Type

const NoteFields = {
  type: Schema.Literal("note"),
  origin: Schema.String,
  label: Schema.String,
  icon: Schema.String,
  subject: Schema.String,
  href: Persistence.optional(Schema.String),
  live: Persistence.optional(Persistence.struct({ subject: Schema.String, href: Persistence.optional(Schema.String) })),
  comment: Schema.String,
}

/** An extension's comment on something other than workspace lines, as sent in message metadata. */
export const NoteComment = Persistence.struct(NoteFields)

export type NoteComment = typeof NoteComment.Type

export const NoteContextItem = Persistence.struct({ ...NoteFields, commentID: Schema.String })

export type NoteContextItem = typeof NoteContextItem.Type

export type ContextItem = FileContextItem | NoteContextItem

/** A note's live part names state inside the app process that attached it; anything that may outlive it drops it. */
export function durableNote<Note extends NoteComment>(note: Note) {
  return Struct.omit(note, ["live"])
}

// Legacy data: desktop builds before extension notes stored browser element comments as their own type, in drafts
// and in message metadata. They read as the browser extension's note, without the element ref of their process.
const LegacyBrowserComment = Persistence.struct({
  type: Schema.Literal("browser"),
  tabID: Schema.String,
  url: Schema.String,
  title: Persistence.optional(Schema.String),
  element: Persistence.struct({
    ref: Persistence.optional(Schema.String),
    selector: Schema.String,
    label: Schema.String,
    role: Persistence.optional(Schema.String),
    name: Persistence.optional(Schema.String),
    text: Persistence.optional(Schema.String),
  }),
  comment: Schema.String,
})

export const LegacyBrowserNote = LegacyBrowserComment.pipe(
  Schema.decodeTo(Schema.toType(NoteComment), {
    decode: SchemaGetter.transform(legacyBrowserNote),
    encode: SchemaGetter.forbidden(() => "Legacy browser comments are read-only"),
  }),
)

// The subject those builds sent for an element whose ref no longer applies.
function legacyBrowserNote(item: typeof LegacyBrowserComment.Type): NoteComment {
  const element = item.element

  const details = [
    element.role ? `role ${element.role}` : undefined,
    element.name ? `accessible name ${JSON.stringify(element.name)}` : undefined,
    element.text && element.text !== element.name ? `text ${JSON.stringify(element.text.slice(0, 80))}` : undefined,
    element.selector
      ? `selector ${JSON.stringify(element.selector)}${element.selector.includes(" >>> ") ? ' (">>>" enters a shadow root)' : ""}`
      : undefined,
  ].filter((detail) => detail !== undefined)

  return {
    type: "note",
    origin: "browser",
    label: element.label,
    icon: "select-element",
    subject: `the ${JSON.stringify(element.label)} element in browser tab ${item.tabID} at ${item.url}${details.length ? ` (${details.join("; ")})` : ""}`,
    href: item.tabID,
    comment: item.comment,
  }
}

export function contextItemKey(item: ContextItem) {
  if (item.type === "note") return `note:${item.origin}:c=${item.commentID}`
  const key = `${item.type}:${item.path}:${item.selection?.startLine}:${item.selection?.endLine}`

  if (item.commentID) return `${key}:c=${item.commentID}`
  const comment = item.comment?.trim()

  if (!comment) return key
  const digest = checksum(comment) ?? comment

  return `${key}:c=${digest.slice(0, 8)}`
}

const FileContextEntry = Schema.Struct({ ...FileContextItem.fields, key: Persistence.optional(Schema.String) }).pipe(
  Schema.decodeTo(Persistence.struct({ ...FileContextItem.fields, key: Schema.String }).pipe(Schema.toType), {
    decode: SchemaGetter.transform((item) => ({ ...item, key: contextItemKey(item) })),
    encode: SchemaGetter.transform((item) => item),
  }),
)

const NoteContextEntry = Schema.Struct({
  ...NoteContextItem.fields,
  key: Persistence.optional(Schema.String),
}).pipe(
  Schema.decodeTo(Persistence.struct({ ...NoteContextItem.fields, key: Schema.String }).pipe(Schema.toType), {
    // A stored draft can outlive the app process that attached the note.
    decode: SchemaGetter.transform((item) => ({ ...durableNote(item), key: contextItemKey(item) })),
    encode: SchemaGetter.transform((item) => item),
  }),
)

const LegacyBrowserContextEntry = Schema.Struct({
  ...LegacyBrowserComment.fields,
  commentID: Schema.String,
  key: Persistence.optional(Schema.String),
}).pipe(
  Schema.decodeTo(Persistence.struct({ ...NoteContextItem.fields, key: Schema.String }).pipe(Schema.toType), {
    decode: SchemaGetter.transform((item) => {
      const note = { ...legacyBrowserNote(item), commentID: item.commentID }

      return { ...note, key: contextItemKey(note) }
    }),
    encode: SchemaGetter.forbidden(() => "Legacy browser comments are read-only"),
  }),
)

const ContextEntry = Schema.Union([FileContextEntry, NoteContextEntry, LegacyBrowserContextEntry])

export const DEFAULT_PROMPT: Prompt = [{ type: "text", content: "", start: 0, end: 0 }]

export const ComposerStore = Persistence.struct({
  prompt: Prompt.pipe(
    Schema.decode({
      decode: SchemaGetter.transform((prompt) =>
        prompt.length ? prompt : DEFAULT_PROMPT.map((part) => ({ ...part })),
      ),
      encode: SchemaGetter.transform((prompt) => prompt),
    }),
  ),
  cursor: Persistence.optional(
    Schema.Finite.pipe(
      Schema.decode({
        decode: SchemaGetter.transform((cursor) => Math.max(0, cursor)),
        encode: SchemaGetter.transform((cursor) => cursor),
      }),
    ),
  ),
  model: Persistence.optional(PromptModel),
  mode: Persistence.optional(Schema.Literals(["normal", "shell"])),
  retry: Persistence.optional(
    Schema.Struct({
      id: SessionMessage.ID,
      agent: Schema.String,
      providerID: Schema.String,
      modelID: Schema.String,
      variant: Persistence.optional(Schema.String),
    }),
  ),
  context: Persistence.struct({ items: Persistence.array(ContextEntry) }),
})

export type ComposerStore = typeof ComposerStore.Type

export const LineComment = Persistence.struct({
  id: Schema.String,
  file: Schema.String,
  selection: SelectedLineRange,
  comment: Schema.String,
  time: Schema.Number,
})

export type LineComment = typeof LineComment.Type

export const CommentStore = Persistence.struct({
  comments: Schema.Record(Schema.String, Schema.mutableKey(Persistence.array(LineComment))),
})

export type CommentStore = typeof CommentStore.Type

export const PromptHistoryComment = Persistence.struct({
  id: Schema.String,
  path: Schema.String,
  selection: SelectedLineRange,
  comment: Schema.String,
  time: Schema.Number,
  origin: Persistence.optional(Schema.Literals(["review", "file"])),
  preview: Persistence.optional(Schema.String),
})

export type PromptHistoryComment = typeof PromptHistoryComment.Type

// History entries require a prompt array; only its individual parts recover.
const HistoryPrompt = Schema.Array(Persistence.fallback(Schema.UndefinedOr(ContentPart), () => undefined)).pipe(
  Schema.decodeTo(Schema.toType(Prompt), {
    decode: SchemaGetter.transform((parts) => parts.filter((part) => part !== undefined)),
    encode: SchemaGetter.transform((parts) => parts),
  }),
)

const HistoryEntry = Schema.Struct({ prompt: HistoryPrompt, comments: Persistence.array(PromptHistoryComment) })

export const PromptHistoryEntry = Schema.Union([HistoryEntry, HistoryPrompt]).pipe(
  Schema.decodeTo(Schema.toType(HistoryEntry), {
    decode: SchemaGetter.transform((entry) => ("prompt" in entry ? entry : { prompt: entry, comments: [] })),
    encode: SchemaGetter.transform((entry) => entry),
  }),
)

export type PromptHistoryEntry = typeof PromptHistoryEntry.Type

export const PromptHistoryState = Persistence.struct({ entries: Persistence.array(PromptHistoryEntry) })

import { batch, createEffect, createMemo, on } from "solid-js"
import { createStore } from "solid-js/store"
import type { ComposerControls } from "./adapter"
import { useLocal, type ModelKey, type ModelSelection } from "@/providers/models/selection"
import { useWorkspaceLocation } from "@/workspaces/location"
import { useProviders } from "@/providers/catalog/providers"
import { useData } from "@/runtime/server/current"
import { normalizeAgentList } from "@/runtime/server/global-sync/utils"
import { useModels } from "@/providers/models/models"
import { cycleModelVariant, getConfiguredAgentVariant, resolveModelVariant } from "@/providers/models/variant"
import { useComposerState } from "./persistence"
import { useConfiguredModel } from "@/providers/models/configured"

export function createComposerControls(input: { model?: ModelSelection } = {}) {
  const local = useLocal()
  const sdk = useWorkspaceLocation()
  const data = useData()
  const providers = useProviders(() => sdk().directory)

  return createMemo<ComposerControls>(() => {
    return {
      agents: {
        available: normalizeAgentList(data.location.agent.list({ directory: sdk().directory }) ?? []),
        options: local.agent.list().map((agent) => agent.name),
        current: local.agent.current()?.name ?? "",
        visible: local.agent.visible(),
        select: local.agent.set,
      },
      model: {
        selection: input.model ?? local.model,
        paid: providers.paid().length > 0,
        loading:
          !(input.model ?? local.model).ready() ||
          (local.agent.visible() && data.location.agent.list({ directory: sdk().directory }) === undefined) ||
          !providers.ready(),
      },
    }
  })
}

export function createComposerModelSelection(input: {
  agent: () => { name: string; model?: ModelKey; variant?: string } | undefined
}) {
  const sdk = useWorkspaceLocation()
  const models = useModels()
  const local = useLocal()
  const prompt = useComposerState()
  const configuredModel = useConfiguredModel()
  const [remembered, setRemembered] = createStore<Record<string, ModelKey | undefined>>({})
  createEffect(
    on(
      () => input.agent()?.name,
      (name, previous) => {
        if (!name || !previous || name === previous) return
        batch(() => {
          const model = prompt.model.current()
          setRemembered(previous, model ? { providerID: model.providerID, modelID: model.modelID } : undefined)
          prompt.model.set(remembered[name] ? { ...remembered[name] } : undefined)
        })
      },
    ),
  )
  const providers = useProviders(() => sdk().directory)
  const connected = createMemo(() => new Set(providers.connected().map((item) => item.id)))

  const valid = (model: Pick<ModelKey, "providerID" | "modelID">) => {
    const provider = providers.all().get(model.providerID)

    return !!provider?.models[model.modelID] && connected().has(model.providerID)
  }

  const recent = () => models.recent.list().find(valid)

  const fallback = () =>
    providers.connected().flatMap((provider) => {
      const modelID = Object.values(provider.models)[0]?.id

      return modelID ? [{ providerID: provider.id, modelID }] : []
    })[0]

  const current = () => {
    if (!configuredModel.ready()) return

    const key = [prompt.model.current(), input.agent()?.model, configuredModel(), recent(), fallback()].find(
      (item): item is ModelKey => !!item && valid(item),
    )

    return key ? models.find(key) : undefined
  }

  const recentModels = createMemo(() =>
    models.recent
      .list()
      .map(models.find)
      .filter((item): item is NonNullable<typeof item> => !!item),
  )

  const selection = {
    trackSessionCommit: local.model.trackSessionCommit,
    remembered: () => Object.fromEntries(Object.entries(remembered).map(([name, model]) => [name, { model }])),
    ready: Object.assign(() => models.ready() && configuredModel.ready(), { promise: models.ready.promise }),
    current,
    recent: recentModels,
    list: models.list,
    cycle(direction: 1 | -1) {
      const items = recentModels()
      const item = current()

      if (!item) return
      const index = items.findIndex((entry) => entry.provider.id === item.provider.id && entry.id === item.id)

      const next =
        items[
          index === -1 ? (direction === 1 ? 0 : items.length - 1) : (index + direction + items.length) % items.length
        ]

      if (next) selection.set({ providerID: next.provider.id, modelID: next.id })
    },
    set(item: ModelKey | undefined, options?: { recent?: boolean }) {
      batch(() => {
        if (item && !valid(item)) return
        const previous = current()
        const same = item && previous?.provider.id === item.providerID && previous.id === item.modelID
        prompt.model.set(
          item ? { ...item, variant: same ? (selection.variant.current() ?? null) : undefined } : undefined,
        )

        if (!item) return
        models.setVisibility(item, true)

        if (options?.recent) models.recent.push(item)
      })
    },
    visible: models.visible,
    setVisibility: models.setVisibility,
    variant: {
      configured() {
        const item = input.agent()
        const model = current()

        if (!item || !model) return
        const global = configuredModel()

        return (
          getConfiguredAgentVariant({
            agent: { model: item.model, variant: item.variant },
            model: { providerID: model.provider.id, modelID: model.id, variants: model.variants },
          }) ??
          getConfiguredAgentVariant({
            agent: { model: global, variant: global?.variant },
            model: { providerID: model.provider.id, modelID: model.id, variants: model.variants },
          })
        )
      },
      selected() {
        const model = prompt.model.current()

        return model && valid(model) ? model.variant : undefined
      },
      current() {
        const model = current()

        return resolveModelVariant({
          variants: this.list(),
          selected: this.selected(),
          configured: this.configured(),
          preferred: model ? models.variant.get({ providerID: model.provider.id, modelID: model.id }) : undefined,
        })
      },
      list() {
        return Object.keys(current()?.variants ?? {})
      },
      set(value: string | undefined) {
        batch(() => {
          const model = current()

          if (!model) return
          prompt.model.set({ providerID: model.provider.id, modelID: model.id, variant: value ?? null })
          models.variant.set({ providerID: model.provider.id, modelID: model.id }, value)
        })
      },
      cycle() {
        const variants = this.list()

        if (variants.length === 0) return
        this.set(
          cycleModelVariant({
            variants,
            selected: this.current() ?? null,
            configured: undefined,
          }),
        )
      },
    },
  }

  return selection satisfies ModelSelection
}

import { batch, untrack, type Accessor } from "solid-js"
import { createStore, type SetStoreFunction } from "solid-js/store"
import { Persist, persisted } from "@/runtime/persistence/storage"
import { ServerScope } from "@/runtime/server/scope"
import type { Platform } from "@/runtime/platform/platform"
import { clonePrompt } from "./prompt-parts"
import {
  ComposerStore,
  DEFAULT_PROMPT,
  contextItemKey,
  type ContextItem,
  type Prompt,
  type PromptModel,
} from "./schema"

export { DEFAULT_PROMPT } from "./schema"

export type {
  AgentPart,
  ComposerStore,
  ContentPart,
  ContextItem,
  FileAttachmentPart,
  FileContextItem,
  ImageAttachmentPart,
  NoteComment,
  NoteContextItem,
  PathAttachmentPart,
  Prompt,
  PromptModel,
  SkillPart,
  TextPart,
} from "./schema"

export type PromptScope = { draftID: string } | { dir: string; id?: string }

type InitialPrompt = {
  prompt?: string
  model?: PromptModel
}

export function isCommentItem(item: ContextItem | (ContextItem & { key: string })) {
  return !!item.comment?.trim()
}

function createComposerActions(setStore: SetStoreFunction<ComposerStore>) {
  return {
    set(prompt: Prompt, cursorPosition?: number) {
      batch(() => {
        setStore({ prompt: clonePrompt(prompt), retry: undefined })

        // An omitted cursor keeps the current one.
        if (cursorPosition !== undefined) setStore("cursor", cursorPosition)
      })
    },
    reset() {
      batch(() => setStore({ prompt: clonePrompt(DEFAULT_PROMPT), cursor: 0, retry: undefined }))
    },
  }
}

function composerTarget(serverScope: ServerScope, scope: PromptScope) {
  return "draftID" in scope
    ? Persist.prompt(Persist.draft(scope.draftID, "prompt"))
    : Persist.prompt({
        ...Persist.serverScoped(serverScope, scope.dir, scope.id, "prompt"),
        previousKey:
          serverScope === ServerScope.local ? `${scope.dir}/prompt${scope.id ? "/" + scope.id : ""}.v2` : undefined,
      })
}

function initialComposerStore(initial?: InitialPrompt): ComposerStore {
  const text = initial?.prompt

  return {
    prompt:
      text === undefined ? clonePrompt(DEFAULT_PROMPT) : [{ type: "text", content: text, start: 0, end: text.length }],
    cursor: text === undefined ? undefined : text.length,
    model: initial?.model ? { ...initial.model } : undefined,
    context: {
      items: [],
    },
  }
}

function createComposerStateValue(store: ComposerStore, setStore: SetStoreFunction<ComposerStore>) {
  const actions = createComposerActions(setStore)

  const clearRetry = () => {
    if (untrack(() => store.retry) !== undefined) setStore("retry", undefined)
  }

  const value = {
    store: [() => store, setStore] satisfies [Accessor<ComposerStore>, SetStoreFunction<ComposerStore>],
    current: () => store.prompt,
    cursor: () => store.cursor,
    model: {
      current: () => store.model,
      set: (model: PromptModel | undefined) => {
        setStore("model", model)
        clearRetry()
      },
    },
    mode: {
      current: () => store.mode ?? "normal",
      set: (mode: "normal" | "shell") => {
        if (untrack(() => store.mode === mode && store.retry === undefined)) return
        setStore({ mode, retry: undefined })
      },
    },
    retry: {
      current: () => store.retry,
      set: (retry: NonNullable<ComposerStore["retry"]>) => setStore("retry", retry),
    },
    context: {
      items: () => store.context.items,
      add(item: ContextItem) {
        const key = contextItemKey(item)

        if (store.context.items.find((x) => x.key === key)) return
        setStore("context", "items", (items) => [...items, { key, ...item }])
        clearRetry()
      },
      remove(key: string) {
        setStore("context", "items", (items) => items.filter((x) => x.key !== key))
        clearRetry()
      },
      /** Removes the file comment or note with this commentID. */
      removeComment(commentID: string) {
        setStore("context", "items", (items) => items.filter((item) => item.commentID !== commentID))
        clearRetry()
      },
      /** Edits the file comment or note with this commentID; only file comments carry a preview. */
      updateComment(commentID: string, next: { readonly comment?: string; readonly preview?: string }) {
        setStore("context", "items", (items) =>
          items.map((item) => {
            if (item.commentID !== commentID) return item

            const value =
              item.type === "file" ? { ...item, ...next } : { ...item, comment: next.comment ?? item.comment }

            return { ...value, key: contextItemKey(value) }
          }),
        )
        clearRetry()
      },
      /** Replaces every item, as restoring a sent prompt replaces the whole draft. */
      replace(items: ContextItem[]) {
        setStore(
          "context",
          "items",
          [...new Map(items.map((item) => [contextItemKey(item), item] as const)).entries()].map(([key, item]) => ({
            ...item,
            key,
          })),
        )
        clearRetry()
      },
      replaceComments(items: ContextItem[]) {
        setStore("context", "items", (current) => [
          ...current.filter((item) => !isCommentItem(item)),
          ...items.map((item) => ({ ...item, key: contextItemKey(item) })),
        ])
        clearRetry()
      },
    },
    set: (prompt: Prompt, cursorPosition?: number) => actions.set(prompt, cursorPosition),
    reset: () => actions.reset(),
    capture: () => value,
  }

  return value
}

function createPersistedComposer(
  target: ReturnType<typeof composerTarget>,
  initial?: InitialPrompt,
  platform?: Platform,
) {
  const [store, setStore, _, ready] = persisted(target, ComposerStore, initialComposerStore(initial), platform)

  return { ready, ...createComposerStateValue(store, setStore) }
}

export function createComposerState(
  serverScope: ServerScope,
  scope: PromptScope,
  initial?: InitialPrompt,
  platform?: Platform,
) {
  return createPersistedComposer(composerTarget(serverScope, scope), initial, platform)
}

export function createDraftComposerState(draftID: string, initial?: InitialPrompt) {
  return createPersistedComposer(Persist.prompt(Persist.draft(draftID, "prompt")), initial)
}

export type ComposerState = ReturnType<typeof createComposerState>

export function createComposerReady(session: Accessor<ComposerState>) {
  // SAFETY: defineProperty returns the same function, now carrying the promise getter defined here.
  return Object.defineProperty(() => session().ready(), "promise", {
    get: () => session().ready.promise,
  }) as (() => boolean) & { readonly promise: Promise<unknown> | undefined }
}

export function createMemoryComposerState(initial?: InitialPrompt) {
  const [store, setStore] = createStore<ComposerStore>(initialComposerStore(initial))
  const ready = Object.assign(() => true, { promise: Promise.resolve(true) })

  return {
    ready,
    ...createComposerStateValue(store, setStore),
  }
}

import type { ComposerState, ContextItem, Prompt } from "./state"
import { appendPrompt, clonePrompt, isAttachment } from "./prompt-parts"

export type ComposerStateTarget = ReturnType<ComposerState["capture"]>

export function createComposerSubmission(input: {
  target: ComposerStateTarget
  prompt: Prompt
  context: (ContextItem & { key: string })[]
}) {
  const initial = input.target
  let target = input.target
  let cleared: Prompt | undefined
  let following: Prompt | undefined
  let preserveDraft = false

  return {
    prompt: input.prompt,
    context: input.context,
    target: () => target,
    clear() {
      if (initial !== target) {
        initial.reset()

        // A preparing session may already have an unsent follow-up in its promoted composer.
        if (preserveDraft && target.current().some((part) => isAttachment(part) || part.content.length > 0))
          following = clonePrompt(target.current())
      }

      if (!following) target.reset()
      cleared = target.current()
    },
    retarget(next: ComposerStateTarget, options?: { preserveDraft?: boolean }) {
      input.context.forEach((item) => next.context.add(item))
      target = next
      preserveDraft = options?.preserveDraft ?? false
    },
    current: (value: ComposerStateTarget) => target === value,
    restore() {
      if (cleared !== undefined && target.current() !== cleared) return

      return {
        target,
        prompt: following ? appendPrompt(input.prompt, following) : input.prompt,
        context: input.context,
      }
    },
  }
}

import { describe, expect, test } from "bun:test"
import type { ModelSelection } from "@/providers/models/selection"
import type { SessionMessageHandoff } from "@/session/handoff"
import { Skill } from "@opencode/schema/skill"
import type {
  ActiveComposerAdapter,
  ComposerControls,
  ComposerDelivery,
  ComposerSession,
  NewSessionComposerAdapter,
} from "./adapter"
import { createMemoryComposerState, type Prompt } from "./state"
import { createComposerSubmit } from "./submit"
import type { ComposerStateTarget } from "./submission-state"

