function active(state: ComposerStateTarget, target: ComposerSession, ctl = controls): ActiveComposerAdapter {
  return {
    kind: "active-session",
    state,
    ready: () => true,
    controls: ctl,
    working: () => false,
    session: () => target,
    interrupt: async () => undefined,
    submitted() {},
    setEditor() {},
  }
