import { SessionMessage } from "@opencode/schema/session-message"
import type { SessionMessageUser } from "@opencode/client/promise"
import type { Accessor } from "solid-js"
import type { PromptComment } from "./comment-note"
import type { PromptHistoryComment } from "./history/entry"
import type { ImageAttachmentPart, Prompt } from "./state"
import { clonePrompt, promptLength } from "./prompt-parts"
import type { ComposerAdapter, ComposerDelivery, ComposerSelection, ComposerSession } from "./adapter"
import { createComposerSubmission } from "./submission-state"
import { buildPromptRequest, noteComment } from "./request"
import { setCursorPosition } from "./editor/dom"
import { blobDataUrl, resolveBlobUrl } from "@/runtime/persistence/drafts"
import { isAttachment } from "./prompt-parts"
import type { ModelSelection } from "@/providers/models/selection"
import { parseSlashCommand } from "./client-slash-command"

const submitting = new WeakSet<object>()

type ComposerSubmission = {
  id: SessionMessage.ID
  mode: "normal" | "shell"
  prompt: Prompt
  context: ReturnType<ComposerAdapter["state"]["context"]["items"]>
  text: string
  images: ImageAttachmentPart[]
  selection: ComposerSelection
  delivery: ComposerDelivery
}

type ComposerSubmitInput = {
  adapter: ComposerAdapter
  mode: Accessor<"normal" | "shell">
  commands: Accessor<readonly { name: string }[] | undefined>
  editor: () => HTMLDivElement | undefined
  queueScroll: () => void
  addToHistory: (prompt: Prompt, mode: "normal" | "shell") => void
  removeFromHistory: (prompt: Prompt, mode: "normal" | "shell", comments: PromptHistoryComment[]) => void
  resetHistory: () => void
  setMode: (mode: "normal" | "shell") => void
  closePopover: () => void
  delivery?: (alternate: boolean) => ComposerDelivery
  clientCommand?: (text: string) => (() => void | Promise<void>) | undefined
  notify: {
    missingSelection: () => void
    unqueueable: () => void
    // oxlint-disable-next-line anti-slop/no-unknown-parameters -- a rejected send is opaque; the notifier formats it
    failed: (kind: "shell" | "command" | "prompt", error: unknown) => void
  }
  comments: {
    capture: () => PromptHistoryComment[]
    clear: () => void
    restore: (comments: PromptHistoryComment[]) => void
  }
}

export function createComposerSubmit(input: ComposerSubmitInput) {
  const submit = async (event: globalThis.Event, options?: { alternate?: boolean }) => {
    event.preventDefault()

    const prompt = clonePrompt(input.adapter.state.current())
    const text = submissionText(prompt)
    const clientCommand = input.mode() === "normal" ? input.clientCommand?.(text) : undefined

    if (clientCommand) {
      if (submitting.has(input.adapter.state)) return
      submitting.add(input.adapter.state)

      try {
        // Client commands such as /btw answer with the session's model, so apply the composer's selection first,
        // following the same steer rule as server commands.
        const selection = currentSelection(input)

        if (input.adapter.kind === "active-session" && selection && (input.delivery?.(false) ?? "steer") === "steer")
          await applySelection(
            input.adapter.session(),
            selection,
            input.adapter.controls().model.selection.trackSessionCommit,
          )
        clearClientCommand(input, prompt)
        await clientCommand()
      } catch (error) {
        input.notify.failed("command", error)
      } finally {
        submitting.delete(input.adapter.state)
      }

      return
    }

    const submission = createComposerSubmission({
      target: input.adapter.state,
      prompt,
      context: input.adapter.state.context
        .items()
        .map((item) =>
          item.type === "note"
            ? { ...item, live: item.live ? { ...item.live } : undefined }
            : { ...item, selection: item.selection ? { ...item.selection } : undefined },
        ),
    })

    const read = readSubmission(input, submission.prompt, submission.context, text, options?.alternate ?? false)

    if (!read) {
      if (input.adapter.working() && input.adapter.kind === "active-session") void input.adapter.interrupt()

      return
    }

    // Like the TUI, a shell command runs now or not at all; it cannot wait in the queue.
    if (read.mode === "shell" && read.delivery === "queue") {
      input.notify.unqueueable()

      return
    }

    if (submitting.has(input.adapter.state)) return

    // Images restored from a draft or history carry ids only; the optimistic message shows their URLs.
    const value = {
      ...read,
      images: await Promise.all(
        read.images.map(async (image) => ({
          ...image,
          blob: { ...image.blob, url: (await resolveBlobUrl(image.blob)) ?? image.blob.url },
        })),
      ),
    }

    submitting.add(input.adapter.state)
    const comments = input.comments.capture()
    // Capture command intent before starting a session in a worktree whose catalog has not loaded.
    const command = value.mode === "normal" ? findCommand(input.commands(), value.text) : undefined

    try {
      const started =
        input.adapter.kind === "active-session"
          ? { session: input.adapter.session(), cleanupReady: Promise.resolve() }
          : await input.adapter.start(value.selection, submission, handoffMessage(value))

      if (!started) return
      const session = started.session

      input.addToHistory(value.prompt, value.mode)
      input.resetHistory()
      const restore = () => restoreSubmission(input, submission, value, comments)

      if (value.mode === "normal" && !command) {
        // The timeline shows a steer, and any switches it makes, as the composer clears; a queued prompt shows in
        // the queue once admitted.
        if (value.delivery === "steer")
          session.handoff.set({
            message: handoffMessage(value),
            selection: {
              agent: value.selection.agent,
              model: {
                id: value.selection.model.modelID,
                providerID: value.selection.model.providerID,
                variant: value.selection.variant,
              },
            },
          })
        const optimisticBusy = !input.adapter.working()

        if (optimisticBusy) session.data.session.setStatus(session.id, "running")

        const sending = sendPrompt(session, value, input.adapter.controls().model.selection.trackSessionCommit).then(
          () => ({ ok: true as const }),
          (error) => ({ ok: false as const, error }),
        )

        await started.cleanupReady
        await started.complete?.()
        input.adapter.submitted()
        // Like the TUI, sent context goes with the prompt rather than riding along on the next one.
        submission.context.forEach((item) => submission.target().context.remove(item.key))
        input.comments.clear()
        clearSubmission(input, submission)
        void sending.then((result) => {
          if (!result.ok)
            failSubmission(input, session, "prompt", result.error, restore, value.id, () => {
              if (optimisticBusy) session.data.session.setStatus(session.id, "idle")
            })
        })

        return
      }

      await started.cleanupReady
      await started.complete?.()
      input.adapter.submitted()

      if (value.mode === "shell") {
        clearSubmission(input, submission)
        void sendShell(session, value).catch((error) => failSubmission(input, session, "shell", error, restore))

        return
      }

      if (command) {
        clearSubmission(input, submission)
        void sendCommand(session, value, command, input.adapter.controls().model.selection.trackSessionCommit).catch(
          (error) => failSubmission(input, session, "command", error, restore, value.id),
        )

        return
      }
    } finally {
      submitting.delete(input.adapter.state)
    }
  }

  return {
    submit,
    stop: () => (input.adapter.kind === "active-session" ? input.adapter.interrupt() : Promise.resolve()),
  }
}

function clearClientCommand(input: ComposerSubmitInput, prompt: Prompt) {
  input.adapter.state.set([{ type: "text", content: "", start: 0, end: 0 }, ...prompt.filter(isAttachment)], 0)
  input.adapter.state.mode.set("normal")
  input.setMode("normal")
  input.closePopover()
}

function selectionModel(selection: ComposerSelection) {
  const model: ComposerSelection["model"] & { variant?: string } = { ...selection.model }

  if (selection.variant) model.variant = selection.variant

  return model
}

function submissionText(prompt: Prompt) {
  return prompt.map((part) => ("content" in part ? part.content : "")).join("")
}

function handoffMessage(value: ComposerSubmission): SessionMessageUser {
  return {
    id: value.id,
    type: "user",
    text: value.text,
    files: value.images.map((image) => ({
      data: "",
      mime: image.mime,
      source: { type: "uri", uri: image.blob.url },
      name: image.sourcePath ?? image.filename,
    })),
    metadata: {
      displayText: value.text,
      attachments: value.prompt.flatMap((part) =>
        part.type === "path" ? [{ name: part.filename, mime: part.mime, path: part.path }] : [],
      ),
      comments: value.context.flatMap((item): PromptComment[] => {
        const comment = item.comment?.trim()

        if (!comment) return []

        if (item.type === "note") return [noteComment(item, comment)]

        return [
          {
            path: item.path,
            comment,
            selection: item.selection && { ...item.selection },
            preview: item.preview,
            origin: item.commentOrigin,
          },
        ]
      }),
      agent: value.selection.agent,
      model: selectionModel(value.selection),
    },
    time: { created: Date.now() },
  }
}

function readSubmission(
  input: ComposerSubmitInput,
  prompt: Prompt,
  context: ComposerSubmission["context"],
  text: string,
  alternate: boolean,
): ComposerSubmission | undefined {
  const mode = input.mode()

  if (mode === "shell" && !text.trim()) return
  const images = prompt.filter((part): part is ImageAttachmentPart => part.type === "image")
  // Like the TUI's blank Enter, file chips alone send nothing; they wait for text.
  const comments = context.filter((item) => !!item.comment?.trim()).length

  if (!text.trim() && !prompt.some(isAttachment) && comments === 0) return

  const selection = currentSelection(input)

  if (!selection) {
    input.notify.missingSelection()

    return
  }

  const retry = input.adapter.state.retry.current()

  const retryID =
    retry &&
    retry.agent === selection.agent &&
    retry.providerID === selection.model.providerID &&
    retry.modelID === selection.model.modelID &&
    (retry.variant ?? "default") === (selection.variant ?? "default")
      ? retry.id
      : undefined

  return {
    id: retryID ?? SessionMessage.ID.create(),
    mode,
    prompt,
    context,
    text,
    images,
    selection,
    delivery: input.delivery?.(alternate) ?? "steer",
  }
}

function currentSelection(input: ComposerSubmitInput): ComposerSelection | undefined {
  const controls = input.adapter.controls()
  const model = controls.model.selection.current()
  const agent = controls.agents.current

  if (!model || !agent) return

  return {
    agent,
    model: { modelID: model.id, providerID: model.provider.id },
    variant: controls.model.selection.variant.current(),
  }
}

function clearSubmission(input: ComposerSubmitInput, submission: ReturnType<typeof createComposerSubmission>) {
  submission.clear()
  submission.target().mode.set("normal")
  input.setMode("normal")
  input.closePopover()

  if (window.matchMedia("(max-width: 767px)").matches) input.editor()?.blur()
}

function restoreSubmission(
  input: ComposerSubmitInput,
  submission: ReturnType<typeof createComposerSubmission>,
  value: ComposerSubmission,
  comments: PromptHistoryComment[],
) {
  const restored = submission.restore()

  if (!restored) return false
  // The prompt is back in the composer; its history entry would only keep attachments referenced.
  input.removeFromHistory(value.prompt, value.mode, comments)
  restored.target.set(restored.prompt, promptLength(restored.prompt))
  restored.target.mode.set(value.mode)
  restored.target.context.replaceComments(
    restored.context
      .filter((item) => !!item.comment?.trim())
      .map((item) =>
        item.type === "note"
          ? {
              type: "note",
              origin: item.origin,
              label: item.label,
              icon: item.icon,
              subject: item.subject,
              href: item.href,
              live: item.live,
              comment: item.comment,
              commentID: item.commentID,
            }
          : {
              type: "file",
              path: item.path,
              selection: item.selection,
              comment: item.comment,
              commentID: item.commentID,
              commentOrigin: item.commentOrigin,
              preview: item.preview,
            },
      ),
  )
  restored.context.forEach((item) => {
    if (item.type === "file" && !item.comment?.trim())
      restored.target.context.add({
        type: "file",
        path: item.path,
        selection: item.selection,
        name: item.name,
        description: item.description,
      })
  })

  // A recovered follow-up changes the payload, so it must use a new admission ID.
  if (value.mode === "normal" && restored.prompt === submission.prompt) {
    restored.target.retry.set({
      id: value.id,
      agent: value.selection.agent,
      providerID: value.selection.model.providerID,
      modelID: value.selection.model.modelID,
      variant: value.selection.variant,
    })
  }

  if (!submission.current(input.adapter.state)) return true

  input.comments.restore(comments)
  input.setMode(value.mode)
  input.closePopover()
  requestAnimationFrame(() => {
    const editor = input.editor()

    if (!editor) return
    editor.focus()
    setCursorPosition(editor, promptLength(value.prompt))
    input.queueScroll()
  })

  return true
}

async function sendShell(session: ComposerSession, value: ComposerSubmission) {
  await session.api.shell({ sessionID: session.id, id: value.id, command: value.text })
}

function findCommand(commands: ReturnType<ComposerSubmitInput["commands"]>, text: string) {
  const parsed = parseSlashCommand(text)

  if (!parsed || !commands?.some((item) => item.name === parsed.name)) return

  return { command: parsed.name, arguments: parsed.input }
}

async function sendCommand(
  session: ComposerSession,
  value: ComposerSubmission,
  command: { command: string; arguments: string },
  track?: ModelSelection["trackSessionCommit"],
) {
  const request = await buildSubmissionRequest(session, value)

  // Like queued prompts, queued commands must not apply the composer's selection to active work.
  if (value.delivery === "steer") await applySelection(session, value.selection, track)
  await session.api.command({
    sessionID: session.id,
    name: command.command,
    text: command.arguments,
    files: request.files.map((file) => ({
      uri: file.uri,
      name: file.name,
      description: file.description,
      mention: file.mention,
    })),
    agents: request.agents,
    skills: request.skills,
    delivery: value.delivery,
  })
}

async function applySelection(
  session: ComposerSession,
  selection: ComposerSelection,
  track?: ModelSelection["trackSessionCommit"],
  beforeModel?: () => Promise<void>,
) {
  const cancel = track?.(session.id, selection)

  try {
    const current = session.current()

    if (current?.agent !== selection.agent) {
      await session.api.switchAgent({ sessionID: session.id, agent: selection.agent })
    }

    await beforeModel?.()

    // The server deduplicates unchanged selections; cached SSE state may still be behind an earlier switch.
    await session.api.switchModel({
      sessionID: session.id,
      model: { id: selection.model.modelID, providerID: selection.model.providerID, variant: selection.variant },
    })
  } catch (error) {
    cancel?.()
    throw error
  }
}

async function sendPrompt(
  session: ComposerSession,
  value: ComposerSubmission,
  track: ModelSelection["trackSessionCommit"] | undefined,
) {
  const request = await buildSubmissionRequest(session, value)

  // Switching agent or model reconfigures the session immediately, and with it
  // the remainder of a running turn. A steer targets that turn, so its
  // selection applies now; a queued follow-up must not reconfigure the turn it
  // waits behind, so it runs with the session selection at delivery time (the
  // intended selection stays recorded in its metadata).
  // Like the TUI, a staged revert settles after the agent switch and before the model switch and admission. The
  // server would otherwise commit it on admission and delete every row from its boundary on, the model switch too.
  const settle = async () => {
    if (session.current()?.revert) await session.api.revert.commit({ sessionID: session.id })
  }

  const commit = () => (value.delivery === "steer" ? applySelection(session, value.selection, track, settle) : settle())
  // The data layer admits the prompt locally before it commits the selection, so a steer shows as pending while the
  // selection commits. A staged revert settles before admission instead: its committed echo removes every local row
  // from its boundary on. Only an idle session stages one, and a prompt into it starts work rather than showing as
  // pending.
  const staged = !!session.current()?.revert

  if (staged) await commit()
  // A retried admission reuses the first commit rather than switching again.
  let committed: Promise<void> | undefined

  const admission = {
    id: value.id,
    sessionID: session.id,
    delivery: value.delivery,
    text: request.text,
    files: request.files.map((file) => ({
      uri: file.uri,
      name: file.name,
      description: file.description,
      mention: file.mention,
    })),
    agents: request.agents,
    skills: request.skills,
    metadata: {
      displayText: request.displayText,
      comments: request.comments,
      attachments: request.attachments,
      agent: value.selection.agent,
      model: selectionModel(value.selection),
    },
    prepare: staged ? undefined : () => (committed ??= commit()),
  }

  await session.data.session.prompt(admission).catch(() => session.data.session.prompt(admission))
}

async function buildSubmissionRequest(session: ComposerSession, value: ComposerSubmission) {
  const images = await Promise.all(
    value.images.map(async (attachment) => ({
      ...attachment,
      dataUrl: await blobDataUrl(attachment.blob, attachment.mime),
    })),
  )

  return buildPromptRequest({
    prompt: value.prompt,
    context: value.context,
    images,
    text: value.text,
    sessionDirectory: session.directory,
  })
}

function failSubmission(
  input: ComposerSubmitInput,
  session: ComposerSession,
  kind: "shell" | "command" | "prompt",
  // oxlint-disable-next-line anti-slop/no-unknown-parameters -- a rejected send is opaque; the notifier formats it
  error: unknown,
  restore: () => boolean,
  messageID?: string,
  rollback?: () => void,
) {
  if (messageID && session.admitted(messageID)) return

  if (messageID) session.handoff.clear(messageID)
  rollback?.()
  restore()
  input.notify.failed(kind, error)
}

import { expect, test } from "bun:test"
import type { ComposerPersistedState, ComposerSuggestion } from "../types"
import {
  createComposerInteractionState,
  transitionComposer,
  type ComposerInteractionCommand,
  type ComposerInteractionEvent,
  type ComposerInteractionState,
} from "./machine"

const command: ComposerSuggestion = { id: "review", kind: "command", label: "/review" }

const file: ComposerSuggestion = { id: "src/index.ts", kind: "file", label: "index.ts", path: "src/index.ts" }

function persisted(value = "", cursor = value.length): ComposerPersistedState {
  return {
    prompt: [{ type: "text", content: value, start: 0, end: value.length }],
    cursor,
    context: { items: [] },
  }
}

function key(key: string, input: { ctrl?: boolean; ids?: string[]; empty?: boolean } = {}): ComposerInteractionEvent {
  return {
    type: "key.down",
    key,
    ctrl: input.ctrl ?? false,
    composing: false,
    ids: input.ids ?? [],
    empty: input.empty,
  }
}

const menu = { popover: { type: "command-menu", query: "" }, focus: "command-search" } as const

test.each<{
  name: string
  from?: Partial<ComposerInteractionState>
  event: ComposerInteractionEvent
  draft?: ComposerPersistedState
  popover?: ComposerInteractionState["popover"]
  focus?: ComposerInteractionState["focus"]
  mode?: ComposerInteractionState["mode"]
  command?: ComposerInteractionCommand
  handled?: true
}>([
  {
    name: "opens the searchable command menu for a populated draft",
    event: { type: "commands.open" },
    draft: persisted("existing text"),
    ...menu,
    command: { type: "focus.command-search" },
  },
  {
    name: "opens inline commands when slash is the entire prompt",
    event: { type: "input.changed", value: "/re" },
    popover: { type: "command-inline", query: "re" },
  },
  {
    name: "keeps inline commands closed when slash is not the entire prompt",
    event: { type: "input.changed", value: "explain /re" },
    popover: { type: "closed" },
  },
  {
    name: "opens nested slash command names",
    event: { type: "input.changed", value: "/review/" },
    popover: { type: "command-inline", query: "review/" },
  },
  {
    name: "completes nested slash command names",
    from: { popover: { type: "command-inline", query: "review/" } },
    event: { type: "popover.select", item: { ...command, label: "/review/nested" } },
    draft: persisted("/review/"),
    command: { type: "draft.setText", value: "/review/nested " },
  },
  {
    name: "opens context completion at the cursor",
    event: { type: "input.changed", value: "alpha @sr omega", persist: false },
    draft: persisted("alpha @sr omega", 9),
    popover: { type: "context", query: "sr" },
  },
  {
    name: "enters shell mode from an initial exclamation mark",
    event: { type: "input.changed", value: "!", persist: false },
    draft: persisted("!"),
    mode: "shell",
    command: { type: "draft.setText", value: "" },
  },
  {
    name: "leaves shell mode with escape",
    from: { mode: "shell" },
    event: key("Escape"),
    mode: "normal",
    handled: true,
  },
  {
    name: "leaves shell mode with backspace when empty",
    from: { mode: "shell" },
    event: key("Backspace", { empty: true }),
    mode: "normal",
    handled: true,
  },
  {
    name: "closes a popover with ctrl-g before stopping a run",
    from: { popover: { type: "context", query: "", activeID: "first" } },
    event: key("g", { ctrl: true, ids: ["first"] }),
    popover: { type: "closed" },
    handled: true,
  },
  {
    name: "prepends a menu command and preserves existing text as arguments",
    from: menu,
    event: { type: "popover.select", item: command },
    draft: persisted("existing text"),
    popover: { type: "closed" },
    command: { type: "draft.setText", value: "/review existing text" },
  },
  {
    name: "stores selected context files as prompt file parts",
    from: { popover: { type: "context", query: "index" } },
    event: { type: "popover.select", item: file },
    draft: persisted("@index"),
    command: { type: "mention.add", item: file },
  },
  {
    name: "loops active popover items with arrow keys",
    from: { popover: { type: "context", query: "", activeID: "second" } },
    event: key("ArrowDown", { ids: ["first", "second"] }),
    popover: { type: "context", query: "", activeID: "first" },
    handled: true,
  },
])("$name", (row) => {
  const result = transitionComposer(
    { ...createComposerInteractionState(), ...row.from },
    row.event,
    row.draft ?? persisted(),
  )

  if (row.popover) expect(result.state.popover).toEqual(row.popover)

  if (row.focus) expect(result.state.focus).toBe(row.focus)

  if (row.mode) expect(result.state.mode).toBe(row.mode)

  if (row.command) expect(result.commands).toContainEqual(row.command)
  expect(result.handled).toBe(row.handled ?? false)
})

import type { ComposerHistoryEntry, ComposerPersistedState, ComposerSuggestion } from "../types"
import { isAttachment } from "../prompt-parts"

export type ComposerInteractionState = {
  mode: "normal" | "shell"
  popover:
    | { type: "closed" }
    | { type: "context"; query: string; activeID?: string }
    | { type: "command-inline"; query: string; activeID?: string }
    | { type: "command-menu"; query: string; activeID?: string }
  drag: "idle" | "active"
  focus: "editor" | "command-search" | "external"
  activeContextID?: string
  historyIndex: number
  savedHistory?: ComposerHistoryEntry
}

export type ComposerInteractionEvent =
  | { type: "input.changed"; value: string; persist?: boolean }
  | { type: "commands.open" }
  | { type: "context.open" }
  | { type: "popover.query"; value: string }
  | { type: "popover.results"; ids: string[] }
  | { type: "popover.active"; id: string }
  | { type: "popover.close" }
  | { type: "popover.select"; item: ComposerSuggestion }
  | { type: "key.down"; key: string; ctrl: boolean; composing: boolean; ids: string[]; empty?: boolean }
  | { type: "mode.shell" }
  | { type: "mode.normal" }
  | { type: "drag.enter" }
  | { type: "drag.leave" }
  | { type: "focus.editor" }
  | { type: "focus.external" }
  | { type: "context.active"; id: string }

export type ComposerInteractionCommand =
  | { type: "draft.setText"; value: string }
  | { type: "draft.addText"; value: string }
  | { type: "mention.add"; item: ComposerSuggestion; range?: { start: number; end: number } }
  | { type: "popover.filter"; popover: "command" | "context"; query: string }
  | { type: "suggestion.select"; id: string }
  | { type: "focus.editor" }
  | { type: "focus.command-search" }

export type ComposerEditorTransition = {
  state: ComposerInteractionState
  commands: ComposerInteractionCommand[]
  handled: boolean
}

export function createComposerInteractionState(): ComposerInteractionState {
  return {
    mode: "normal",
    popover: { type: "closed" },
    drag: "idle",
    focus: "external",
    historyIndex: -1,
  }
}

export function transitionComposer(
  state: ComposerInteractionState,
  event: ComposerInteractionEvent,
  persisted: ComposerPersistedState,
): ComposerEditorTransition {
  if (event.type === "input.changed") return inputChanged(state, event.value, event.persist !== false, persisted.cursor)

  if (event.type === "commands.open") return openCommands(state, persisted)

  if (event.type === "context.open") return openContext(state)

  if (event.type === "popover.query") return queryChanged(state, event.value)

  if (event.type === "popover.results") return resultsChanged(state, event.ids)

  if (event.type === "popover.active") return activeChanged(state, event.id)

  if (event.type === "popover.close") return changed({ ...state, popover: { type: "closed" } })

  if (event.type === "popover.select") return suggestionSelected(state, event.item, persisted)

  if (event.type === "key.down") return keyDown(state, event)

  if (event.type === "mode.shell") return changed({ ...state, mode: "shell", popover: { type: "closed" } })

  if (event.type === "mode.normal") return changed({ ...state, mode: "normal" })

  if (event.type === "drag.enter") return changed({ ...state, drag: "active" })

  if (event.type === "drag.leave") return changed({ ...state, drag: "idle" })

  if (event.type === "focus.editor") return changed({ ...state, focus: "editor" })

  if (event.type === "context.active") {
    return changed({ ...state, activeContextID: state.activeContextID === event.id ? undefined : event.id })
  }

  return changed({ ...state, focus: "external" })
}

function inputChanged(
  state: ComposerInteractionState,
  value: string,
  persist: boolean,
  cursor: number | undefined,
): ComposerEditorTransition {
  const setText: ComposerInteractionCommand[] = persist ? [{ type: "draft.setText", value }] : []

  if (state.mode === "normal" && value === "!") {
    return changed({ ...state, mode: "shell", popover: { type: "closed" }, focus: "editor" }, [
      { type: "draft.setText", value: "" },
    ])
  }

  const context = value.slice(0, cursor ?? value.length).match(/(?:^|\s)@([^\s@]*)$/)

  if (context) {
    const query = context[1] ?? ""

    return changed({ ...state, popover: { type: "context", query }, focus: "editor" }, [
      ...setText,
      { type: "popover.filter", popover: "context", query },
    ])
  }

  const command = value.match(/^\/(\S*)$/)

  if (command) {
    const query = command[1] ?? ""

    return changed({ ...state, popover: { type: "command-inline", query }, focus: "editor" }, [
      ...setText,
      { type: "popover.filter", popover: "command", query },
    ])
  }

  return changed(
    { ...state, popover: state.popover.type === "command-menu" ? state.popover : { type: "closed" }, focus: "editor" },
    setText,
  )
}

function openCommands(state: ComposerInteractionState, persisted: ComposerPersistedState): ComposerEditorTransition {
  if (!populated(persisted)) {
    return changed({ ...state, popover: { type: "command-inline", query: "" }, focus: "editor" }, [
      { type: "draft.addText", value: "/" },
      { type: "popover.filter", popover: "command", query: "" },
      { type: "focus.editor" },
    ])
  }

  return changed({ ...state, popover: { type: "command-menu", query: "" }, focus: "command-search" }, [
    { type: "popover.filter", popover: "command", query: "" },
    { type: "focus.command-search" },
  ])
}

function openContext(state: ComposerInteractionState): ComposerEditorTransition {
  return changed({ ...state, popover: { type: "context", query: "" }, focus: "editor" }, [
    { type: "draft.addText", value: "@" },
    { type: "popover.filter", popover: "context", query: "" },
    { type: "focus.editor" },
  ])
}

function queryChanged(state: ComposerInteractionState, query: string): ComposerEditorTransition {
  if (state.popover.type === "closed") return unchanged(state)
  const popover = state.popover.type === "context" ? "context" : "command"

  return changed({ ...state, popover: { ...state.popover, query, activeID: undefined } }, [
    { type: "popover.filter", popover, query },
  ])
}

function resultsChanged(state: ComposerInteractionState, ids: string[]): ComposerEditorTransition {
  if (state.popover.type === "closed") return unchanged(state)
  const activeID = state.popover.activeID && ids.includes(state.popover.activeID) ? state.popover.activeID : ids[0]

  if (activeID === state.popover.activeID) return unchanged(state)

  return changed({ ...state, popover: { ...state.popover, activeID } })
}

function activeChanged(state: ComposerInteractionState, id: string): ComposerEditorTransition {
  if (state.popover.type === "closed" || state.popover.activeID === id) return unchanged(state)

  return changed({ ...state, popover: { ...state.popover, activeID: id } })
}

function suggestionSelected(
  state: ComposerInteractionState,
  item: ComposerSuggestion,
  persisted: ComposerPersistedState,
): ComposerEditorTransition {
  const current = promptText(persisted)
  const commands: ComposerInteractionCommand[] = []

  if (item.kind === "command") {
    commands.push({
      type: "draft.setText",
      value:
        state.popover.type === "command-menu"
          ? current.trim()
            ? `${item.label} ${current.trim()}`
            : `${item.label} `
          : replaceTrigger(current, "/", `${item.label} `),
    })
  } else {
    commands.push({
      type: "mention.add",
      item,
      ...(item.kind === "skill" && item.label.startsWith("/")
        ? { range: { start: 0, end: state.popover.type === "command-menu" ? 0 : current.length } }
        : {}),
    })
  }

  commands.push({ type: "focus.editor" })

  return changed({ ...state, popover: { type: "closed" }, focus: "editor" }, commands)
}

function keyDown(
  state: ComposerInteractionState,
  event: Extract<ComposerInteractionEvent, { type: "key.down" }>,
): ComposerEditorTransition {
  if (event.ctrl && event.key.toLowerCase() === "g") {
    if (state.popover.type === "closed") return unchanged(state)

    return changed({ ...state, popover: { type: "closed" }, focus: "editor" }, [{ type: "focus.editor" }], true)
  }

  if (state.popover.type === "closed") {
    if (state.mode === "shell" && (event.key === "Escape" || (event.key === "Backspace" && event.empty))) {
      return changed({ ...state, mode: "normal" }, [], true)
    }

    return unchanged(state)
  }

  if (event.key === "Escape") {
    return changed({ ...state, popover: { type: "closed" }, focus: "editor" }, [{ type: "focus.editor" }], true)
  }

  if (event.key === "Tab" || (event.key === "Enter" && !event.composing)) {
    if (!state.popover.activeID) return unchanged(state, true)

    return unchanged(state, true, [{ type: "suggestion.select", id: state.popover.activeID }])
  }

  const direction =
    event.key === "ArrowDown" || (event.ctrl && event.key === "n")
      ? 1
      : event.key === "ArrowUp" || (event.ctrl && event.key === "p")
        ? -1
        : 0

  if (!direction || event.ids.length === 0) return unchanged(state)
  const current = state.popover.activeID ? event.ids.indexOf(state.popover.activeID) : -1

  const index =
    current < 0
      ? direction === 1
        ? 0
        : event.ids.length - 1
      : (current + direction + event.ids.length) % event.ids.length

  return changed({ ...state, popover: { ...state.popover, activeID: event.ids[index] } }, [], true)
}

function promptText(persisted: ComposerPersistedState) {
  return persisted.prompt.map((part) => (part.type === "text" ? part.content : "")).join("")
}

function populated(persisted: ComposerPersistedState) {
  return (
    !!promptText(persisted).trim() ||
    persisted.context.items.length > 0 ||
    persisted.prompt.some((part) => part.type === "file" || isAttachment(part))
  )
}

function replaceTrigger(value: string, trigger: "@" | "/", replacement: string) {
  const index = trigger === "/" ? value.indexOf(trigger) : value.lastIndexOf(trigger)

  return index < 0 ? replacement : value.slice(0, index) + replacement
}

function changed(
  state: ComposerInteractionState,
  commands: ComposerInteractionCommand[] = [],
  handled = false,
): ComposerEditorTransition {
  return { state, commands, handled }
}

function unchanged(
  state: ComposerInteractionState,
  handled = false,
  commands: ComposerInteractionCommand[] = [],
): ComposerEditorTransition {
  return { state, commands, handled }
}

