import { Predicate } from "effect"
import { base64Encode } from "@opencode/util/encode"
import { Session } from "@opencode/schema/session"
import { startTransition } from "solid-js"
import type { NewSessionComposerAdapter } from "@/composer/adapter"
import { useComposerState } from "@/composer/persistence"
import { createComposerControls, createComposerModelSelection } from "@/composer/selection"
import { createComposerProjectControls } from "./project/controller"
import { useLanguage } from "@/runtime/i18n/language"
import { useLocal } from "@/providers/models/selection"
import { useData, useServer } from "@/runtime/server/current"
import { useServerSDK } from "@/runtime/server/client"
import { useTabs } from "@/shell/tabs/tabs"
import { useWorkspaceLocation } from "@/workspaces/location"
import { createWorktree } from "@/workspaces/create"
import { showToast } from "@/shell/notifications/toast"
import { SessionRouteKey, SessionStateKey } from "@/runtime/server/scope"
import { createSessionMessageHandoff } from "@/session/handoff"
import type { DraftMcpControls } from "./mcp"

export function createNewSessionComposerAdapter(props: {
  draftID: string
  worktree: () => string
  branch: () => string | undefined
  submitted: () => void
  mcp: DraftMcpControls
}) {
  const prompt = useComposerState()
  const state = prompt.capture()
  const local = useLocal()
  const data = useData()
  const server = useServer()
  const serverSDK = useServerSDK()
  const tabs = useTabs()
  const location = useWorkspaceLocation()
  const language = useLanguage()
  const model = createComposerModelSelection({ agent: () => local.agent.current() })
  const controls = createComposerControls({ model })

  const adapter: NewSessionComposerAdapter = {
    kind: "new-session",
    state,
    ready: prompt.ready,
    controls,
    working: () => false,
    submitted: props.submitted,
    async start(selection, submission, message) {
      const draftID = props.draftID
      const currentDirectory = location().directory

      const projectDirectory =
        data.location.info({ directory: currentDirectory })?.project.canonical ?? currentDirectory

      const worktree = props.worktree()
      const branch = props.branch()
      const mcp = props.mcp.capture()
      const id = Session.ID.create()

      const pending =
        worktree === "create"
          ? tabs.prepareSession(draftID, { server: server.key, sessionId: id }, { message, selection })
          : undefined

      await pending?.ready

      const sessionDirectory = await resolveSessionDirectory({
        projectDirectory,
        worktree,
        branch,
        data,
        serverSDK,
        language,
      })

      if (!sessionDirectory) {
        await pending?.rollback()

        return
      }

      const rollback = async () => {
        if (!pending) return
        data.project.invalidate()
        await data.project.sync().catch(() => undefined)
        await pending.rollback(sessionDirectory)
      }

      if (!(await props.mcp.prepare(sessionDirectory, mcp))) {
        await rollback()

        if (pending) props.mcp.remember(sessionDirectory, mcp)

        return
      }

      const created = data.session.create({
        id,
        agent: selection.agent,
        model: {
          id: selection.model.modelID,
          providerID: selection.model.providerID,
          variant: selection.variant,
        },
        location: { directory: sessionDirectory },
      })

      const creation = created.request.then(
        () => ({ ok: true as const }),
        (error) => {
          showToast({
            title: language.t("prompt.toast.sessionCreateFailed.title"),
            description: errorMessage(language, error),
          })

          return { ok: false as const, error }
        },
      )

      if (pending && !(await creation).ok) {
        await rollback()

        return
      }

      const afterCreation = async <T>(run: () => Promise<T>) => {
        const result = await creation

        if (!result.ok) throw result.error

        return run()
      }

      const sessionKey = SessionStateKey.from(
        serverSDK.scope,
        SessionRouteKey.fromRoute(base64Encode(sessionDirectory), created.id),
      )

      const cleanupReady = startTransition(() => {
        if (!pending) tabs.updateDraft(draftID, { worktree: undefined, branch: undefined })
        local.session.promote(sessionDirectory, created.id, {
          agent: selection.agent,
          model: selection.model,
          variant: selection.variant ?? null,
          choices: model.remembered(),
        })

        if (!pending) tabs.promoteDraft(draftID, { server: server.key, sessionId: created.id })
        submission.retarget(
          prompt.capture(
            { dir: base64Encode(sessionDirectory), id: created.id },
            { server: server.key, scope: serverSDK.scope },
          ),
          { preserveDraft: !!pending },
        )
      })

      return {
        cleanupReady,
        complete: pending ? () => pending.complete(submission.target()) : undefined,
        session: {
          id: created.id,
          directory: sessionDirectory,
          handoff: createSessionMessageHandoff(sessionKey, created.id, serverSDK.event),
          api: {
            command: (input) => afterCreation(() => serverSDK.api.session.command(input)),
            shell: (input) => afterCreation(() => serverSDK.api.session.shell(input)),
            switchAgent: (input) => afterCreation(() => serverSDK.api.session.switchAgent(input)),
            switchModel: (input) => afterCreation(() => serverSDK.api.session.switchModel(input)),
            revert: { commit: (input) => afterCreation(() => serverSDK.api.session.revert.commit(input)) },
          },
          data: {
            location: data.location,
            session: {
              setStatus: data.session.setStatus,
              prompt: (input) =>
                data.session.prompt({
                  ...input,
                  gate: Promise.all([input.gate, afterCreation(async () => undefined)]),
                }),
            },
          },
          current: () => data.session.get(created.id),
          admitted: (messageID) =>
            data.session.input.has(created.id, messageID) || !!data.session.message.get(created.id, messageID),
        },
      }
    },
  }

  return {
    adapter,
    project: createComposerProjectControls({ draftId: props.draftID, worktree: props.worktree }),
    model,
    ready: prompt.ready,
  }
}

async function resolveSessionDirectory(input: {
  projectDirectory: string
  worktree: string
  branch?: string
  data: ReturnType<typeof useData>
  serverSDK: ReturnType<typeof useServerSDK>
  language: ReturnType<typeof useLanguage>
}) {
  if (input.worktree === "main") return input.projectDirectory

  if (input.worktree !== "create") return input.worktree

  return createWorktree({
    api: input.serverSDK.api,
    data: input.data,
    directory: input.projectDirectory,
    project: input.data.location.info({ directory: input.projectDirectory })?.project,
    branch: input.branch,
  }).catch((error) => {
    showToast({
      title: input.language.t("prompt.toast.worktreeCreateFailed.title"),
      description: errorMessage(input.language, error),
    })
  })
}

function errorMessage(language: ReturnType<typeof useLanguage>, cause: unknown) {
  if (Predicate.hasProperty(cause, "message") && Predicate.isString(cause.message)) return cause.message

  if (
    Predicate.hasProperty(cause, "data") &&
    Predicate.hasProperty(cause.data, "message") &&
    Predicate.isString(cause.data.message) &&
    cause.data.message
  )
    return cause.data.message

  return language.t("common.requestFailed")
}

import { createMemo } from "solid-js"
import { createStore } from "solid-js/store"
import { useMcpToggle, type McpControls } from "@/providers/connect/mcp"
import { useLanguage } from "@/runtime/i18n/language"
import { useServerSDK } from "@/runtime/server/client"
import { useServer } from "@/runtime/server/current"
import { useTabs } from "@/shell/tabs/tabs"
import { showToast } from "@/shell/notifications/toast"
import { useWorkspaceLocation } from "@/workspaces/location"

export function createDraftMcpControls(input: { draftID: string; worktree: () => string }) {
  const tabs = useTabs()
  const location = useWorkspaceLocation()
  const server = useServer()
  const sdk = useServerSDK()
  const language = useLanguage()

  const [store, setStore] = createStore<{
    preparing: boolean
    pending: Record<string, Promise<boolean> | undefined>
  }>({ preparing: false, pending: {} })

  const key = (worktree: string) => JSON.stringify([server.key, location().directory, worktree])
  const target = createMemo(() => key(input.worktree()))
  const preview = () => input.worktree() === "create"

  const directory = createMemo(() => {
    const selected = input.worktree()

    return selected === "main" || selected === "create" ? location().directory : selected
  })

  const states = createMemo(() => {
    const draft = tabs.store.find((tab) => tab.type === "draft" && tab.draftID === input.draftID)

    return draft?.type === "draft" && draft.mcp?.target === target() ? draft.mcp.states : {}
  })

  const toggle = useMcpToggle(directory)

  const controls: McpControls = {
    get preview() {
      return preview()
    },
    get states() {
      return states()
    },
    get pending() {
      return store.preparing || (!preview() && store.pending[directory()] !== undefined)
    },
    change(name, enabled) {
      if (controls.pending) return
      tabs.updateDraft(input.draftID, { mcp: { target: target(), states: { ...states(), [name]: enabled } } })

      if (preview()) return
      const current = directory()

      const request = toggle.mutateAsync({ name, enabled, directory: current }).then(
        () => true,
        () => false,
      )

      setStore("pending", current, request)
      void request.finally(() => setStore("pending", current, undefined))
    },
  }

  const apply = async (directory: string, states: Readonly<Record<string, boolean>>) => {
    const pending = store.pending[directory]

    if (pending && !(await pending)) return false
    const entries = Object.entries(states)

    if (entries.length === 0) return true
    const catalog = await sdk.api.mcp.list({ location: { directory } })
    const missing = entries.find(([name, enabled]) => enabled && !catalog.data.some((server) => server.name === name))

    if (missing) throw new Error(language.t("session.summary.mcp.unavailable", { name: missing[0] }))

    const results = await Promise.all(
      entries
        .filter(([name, enabled]) => {
          const server = catalog.data.find((server) => server.name === name)

          return server && (enabled ? server.status.status !== "connected" : server.status.status !== "disabled")
        })
        .map(([name, enabled]) =>
          toggle.mutateAsync({ name, enabled, directory }).then(
            () => true,
            () => false,
          ),
        ),
    )

    if (results.some((success) => !success)) return false
    const current = await sdk.api.mcp.list({ location: { directory } })

    const unresolved = entries.find(([name, enabled]) => {
      const status = current.data.find((server) => server.name === name)?.status.status

      return enabled ? status !== "connected" : status !== undefined && status !== "disabled"
    })

    if (!unresolved) return true
    const status = current.data.find((server) => server.name === unresolved[0])?.status.status
    throw new Error(
      language.t(status === "needs_auth" ? "session.summary.mcp.signInBeforeSend" : "session.summary.mcp.notReady", {
        name: unresolved[0],
      }),
    )
  }

  return {
    controls,
    directory,
    capture: () => ({ ...states() }),
    remember(directory: string, states: Readonly<Record<string, boolean>>) {
      tabs.updateDraft(input.draftID, { mcp: { target: key(directory), states: { ...states } } })
    },
    async prepare(directory: string, states: Readonly<Record<string, boolean>>) {
      if (!store.pending[directory] && !Object.keys(states).length) return true
      setStore("preparing", true)

      return apply(directory, states)
        .catch((error) => {
          showToast({
            variant: "error",
            title: language.t("session.summary.mcp.prepareFailed"),
            description: error instanceof Error ? error.message : String(error),
          })

          return false
        })
        .finally(() => setStore("preparing", false))
    },
  }
}

