import { describe, expect, test } from "bun:test"
import {
  cycleNewSessionWorktree,
  resolveNewSessionBranch,
  resolveNewSessionGit,
  resolveNewSessionWorktree,
} from "./controller"

describe("new session workspace selection", () => {
  test.each([
    {
      name: "main when the workspace bar is unavailable",
      input: { enabled: false, selected: "/project/feature" },
      expected: "main",
    },
    {
      name: "the saved new-workspace destination",
      input: { enabled: true, fallback: "create" as const },
      expected: "create",
    },
    { name: "the saved local destination", input: { enabled: true, fallback: "main" as const }, expected: "main" },
    {
      name: "local when the cached project path is stale",
      input: { enabled: true, directory: "C:/Projects/repo", projectWorktree: "D:/Projects/repo" },
      expected: "main",
    },
    {
      name: "the selection when the cached project path is stale",
      input: {
        enabled: true,
        directory: "C:/Projects/repo",
        projectWorktree: "D:/Projects/repo",
        selected: "/worktree",
      },
      expected: "/worktree",
    },
  ])("resolves $name", ({ input, expected }) => {
    expect(resolveNewSessionWorktree(input)).toBe(expected)
  })

  const branch = (worktree: string) => (worktree === "/project/feature" ? "feature" : undefined)

  test.each([
    { worktree: "main", directory: "/project/feature", createBranch: undefined, expected: "feature" },
    { worktree: "create", directory: "/project/feature", createBranch: undefined, expected: "feature" },
    { worktree: "/project/feature", directory: "/project", createBranch: undefined, expected: "feature" },
    { worktree: "/missing", directory: "/project/feature", createBranch: undefined, expected: undefined },
    { worktree: "create", directory: "/project/feature", createBranch: "release", expected: "release" },
  ])("resolves the branch for $worktree in $directory (new branch: $createBranch)", (row) => {
    expect(
      resolveNewSessionBranch({
        worktree: row.worktree,
        directory: row.directory,
        createBranch: row.createBranch,
        worktreeBranch: branch,
      }),
    ).toBe(row.expected)
  })

  test("uses location VCS state when the project inventory is stale", () => {
    expect(resolveNewSessionGit({ branch: "dev" })).toBe(true)
    expect(resolveNewSessionGit({ projectVcs: "git" })).toBe(true)
    expect(resolveNewSessionGit({})).toBe(false)
  })

  const existing = "/project/feature"

  test.each([
    { current: "main", existing: undefined, expected: "create" },
    { current: "create", existing: undefined, expected: "main" },
    { current: existing, existing, expected: "main" },
    { current: "main", existing, expected: "create" },
    { current: "create", existing, expected: existing },
  ])("cycles from $current (existing: $existing) to $expected", ({ current, existing, expected }) => {
    expect(cycleNewSessionWorktree({ current, existing })).toBe(expected)
  })
})

import { debounce } from "@solid-primitives/scheduled"
import { createEffect, createMemo, createResource, onCleanup } from "solid-js"
import { createStore } from "solid-js/store"
import { useWorkspaceLocation } from "@/workspaces/location"
import { useServerSDK } from "@/runtime/server/client"
import { useData } from "@/runtime/server/current"
import { useSettings } from "@/settings/model"
import { useTabs } from "@/shell/tabs/tabs"
import { ServerConnection } from "@/runtime/server/registry"
import { normalizeProjectInfo } from "@/runtime/server/global-sync/utils"
import { sameDirectory } from "@opencode/util/path"
import {
  isWorkspaceDirectory,
  isWorkspaceSelection,
  workspaceDefaultSelection,
  workspaceSelectionDestination,
} from "@/workspaces/paths"

export function resolveNewSessionWorktree(input: { enabled: boolean; selected?: string; fallback?: string }) {
  if (!input.enabled) return "main"

  if (input.selected) return input.selected

  return input.fallback ?? "main"
}

export function resolveNewSessionBranch(input: {
  worktree: string
  directory: string
  createBranch?: string
  worktreeBranch: (worktree: string) => string | undefined
}) {
  if (input.worktree === "create" && input.createBranch) return input.createBranch
  const directory = input.worktree === "main" || input.worktree === "create" ? input.directory : input.worktree

  return input.worktreeBranch(directory)
}

export function resolveNewSessionGit(input: { projectVcs?: string; branch?: string }) {
  return input.projectVcs === "git" || input.branch !== undefined
}

export function cycleNewSessionWorktree(input: { current: string; existing?: string }) {
  if (input.current === "main") return "create"

  if (input.current === "create") return input.existing ?? "main"

  return "main"
}

export function createNewSessionWorkspaceController(input: {
  selectedWorktree: () => string | undefined
  selectedBranch: () => string | undefined
  setSelectedWorktree: (worktree: string | undefined) => void
  setSelectedBranch: (branch: string | undefined) => void
  onViewAll: () => void
}) {
  const sdk = useWorkspaceLocation()
  const serverSDK = useServerSDK()
  const data = useData()
  const settings = useSettings()
  const tabs = useTabs()

  const [state, setState] = createStore({
    search: "",
    existing: undefined as { projectID: string; directory: string } | undefined,
  })

  const searchBranches = debounce((search: string) => setState("search", search.trim()), 100)

  const currentProject = createMemo(() => {
    const projectID = data.location.info({ directory: sdk().directory })?.project.id
    const current = projectID ? data.project.get(projectID) : undefined

    return current ? normalizeProjectInfo(current) : undefined
  })

  const worktreeSource = createMemo(
    () => {
      const project = currentProject()

      return project ? { projectID: project.id, directory: project.worktree } : undefined
    },
    undefined,
    { equals: (a, b) => a?.projectID === b?.projectID && a?.directory === b?.directory },
  )

  const [worktrees, worktreeActions] = createResource(worktreeSource, async (source) => ({
    projectID: source.projectID,
    items: await serverSDK.api.worktree
      .list({ projectID: source.projectID })
      .catch(() => (currentProject()?.id === source.projectID ? currentProject()?.worktrees : undefined) ?? []),
  }))

  onCleanup(
    serverSDK.event.listen((event) => {
      if (event.type === "worktree.updated" && event.data.projectID === currentProject()?.id)
        void worktreeActions.refetch()
    }),
  )
  // `latest` only skips Suspense once the resource has resolved at least once. Before that it
  // behaves like a plain read, which holds the transition that opens the New Session tab until
  // the worktree list returns.
  const worktreesLoaded = () => worktrees.state === "ready" || worktrees.state === "refreshing"

  const worktreeItems = createMemo(() => {
    const project = currentProject()

    if (!project) return []

    if (!worktreesLoaded()) return project.worktrees
    const loaded = worktrees.latest

    return loaded?.projectID === project.id ? loaded.items : project.worktrees
  })

  const worktreeDirectories = createMemo(() => {
    const project = currentProject()

    if (!project) return []

    const directories = [
      ...worktreeItems().map((item) => item.directory),
      ...project.worktrees.map((item) => item.directory),
      ...(project.sandboxes ?? []),
    ]

    return directories
      .filter((directory) => !sameDirectory(project.worktree, directory))
      .filter((directory, index, items) => items.findIndex((item) => sameDirectory(item, directory)) === index)
  })

  const managedWorktrees = createMemo(() => {
    const project = currentProject()

    if (!project) return 0

    return worktreeItems().filter(
      (item) => item.strategy !== undefined && !sameDirectory(project.worktree, item.directory),
    ).length
  })

  const visible = createMemo(() =>
    resolveNewSessionGit({
      projectVcs: currentProject()?.vcs,
      branch: data.location.vcs.info({ directory: sdk().directory })?.branch.current,
    }),
  )

  const selected = createMemo(() => {
    const project = currentProject()
    const worktree = input.selectedWorktree()

    if (!project || !worktree) return

    if (isWorkspaceSelection(project, worktree)) return worktree

    // A saved choice may only exist in the server inventory. Keep it until the list can confirm it,
    // otherwise the selector falls back to Local while loading and a submit would target the wrong directory.
    if (!worktreesLoaded()) return worktree

    return worktreeDirectories().some((item) => sameDirectory(item, worktree)) ? worktree : undefined
  })

  const fallback = createMemo(() => {
    const project = currentProject()

    if (!project) return "main"

    return workspaceDefaultSelection(
      settings.workspaces.defaultDestination(),
      settings.workspaces.lastUsed(serverSDK.scope, project.id),
    )
  })

  const value = createMemo(() =>
    resolveNewSessionWorktree({
      enabled: visible(),
      selected: selected(),
      fallback: fallback(),
    }),
  )

  const projectRoot = createMemo(() => currentProject()?.worktree ?? sdk().directory)

  const [branches] = createResource(
    () => (visible() ? { directory: projectRoot(), search: state.search } : undefined),
    ({ directory, search }) =>
      serverSDK.api.vcs
        .branch.list({ location: { directory }, search, limit: 50 })
        .then((response) => ({ directory, search, data: response.data }))
        .catch(() => ({ directory, search, data: [] })),
  )

  createEffect(() => {
    void Promise.all([
      data.location.syncInfo({ directory: sdk().directory }),
      data.project.sync(),
      data.location.vcs.sync({ directory: sdk().directory }),
    ]).catch(() => undefined)
  })
  // Only the selected worktree feeds the branch label. Syncing every worktree in the inventory boots
  // each one on the server, which then emits `agent.updated` and makes the client run the full
  // catalog fan-out for every directory.
  createEffect(() => {
    const selection = value()

    if (selection === "main" || selection === "create") return
    const project = currentProject()

    if (project) setState("existing", { projectID: project.id, directory: selection })
    void data.location.vcs.sync({ directory: selection }).catch(() => undefined)
  })

  const branch = createMemo(() =>
    resolveNewSessionBranch({
      worktree: value(),
      directory: sdk().directory,
      createBranch: input.selectedBranch(),
      worktreeBranch: (worktree) => data.location.vcs.info({ directory: worktree })?.branch.current,
    }),
  )

  const remember = (worktree = value()) => {
    const project = currentProject()

    if (!project) return
    tabs.initializeDraftWorktrees(ServerConnection.key(serverSDK.server), sdk().directory, fallback())
    const local = workspaceSelectionDestination(worktree, project.worktree) === "main"
    settings.workspaces.setLastUsed(serverSDK.scope, project.id, local ? "local" : "workspace")
  }

  const select = (worktree: string) => {
    input.setSelectedBranch(undefined)
    input.setSelectedWorktree(worktree)
    remember(worktree)
  }

  // The remembered worktree may have been removed since it was selected. Cycling to a directory the
  // inventory no longer contains would resolve back to the fallback and leave the cycle stuck.
  const existing = () => {
    const project = currentProject()
    const previous = state.existing

    if (!project || previous?.projectID !== project.id) return

    if (!worktreeDirectories().some((item) => sameDirectory(item, previous.directory))) return

    return previous.directory
  }

  return {
    selection: {
      value,
      workspace: createMemo(() => {
        const project = currentProject()
        const current = value()

        if (current === "create") return true

        if (current === "main" || !project) return false

        if (isWorkspaceDirectory(project, current) || !worktreesLoaded()) return true

        return worktreeDirectories().some((item) => sameDirectory(item, current))
      }),
      reset: () => {
        input.setSelectedWorktree(undefined)
        input.setSelectedBranch(undefined)
      },
      remember,
      set: select,
      cycle: () => select(cycleNewSessionWorktree({ current: value(), existing: existing() })),
      create: (branch: string) => {
        input.setSelectedBranch(branch)
        input.setSelectedWorktree("create")
        remember("create")
      },
    },
    project: {
      root: projectRoot,
      workspaces: worktreeDirectories,
      managed: managedWorktrees,
      git: visible,
      branches: () => {
        const current = data.location.vcs.info({ directory: sdk().directory })?.branch.current
        const loaded = branches.latest
        const list = loaded?.directory === projectRoot() ? loaded.data : []

        return [
          ...new Set([
            ...list,
            ...(current && current.toLowerCase().includes(state.search.toLowerCase()) ? [current] : []),
          ]),
        ].slice(0, 50)
      },
      searchBranches,
      openAll: input.onViewAll,
    },
    bar: {
      visible,
      branch,
    },
  }
}

export type NewSessionWorkspaceController = ReturnType<typeof createNewSessionWorkspaceController>

import { createMemo, createSignal, For, Show } from "solid-js"
import { createStore } from "solid-js/store"
import { createResizeObserver } from "@solid-primitives/resize-observer"
import { Menu } from "@opencode/ui/menu"
import { Tooltip } from "@opencode/ui/tooltip"
import { Icon } from "@opencode/ui/icon"
import { getFilename, sameDirectory } from "@opencode/util/path"
import { useLanguage } from "@/runtime/i18n/language"

export function PromptWorkspaceSelector(props: {
  value: string
  projectRoot: string
  workspaces: string[]
  branches: string[]
  branch?: string
  onboarding?: boolean
  variant?: "inline" | "summary"
  onChange: (value: string) => void
  onCreate: (branch: string) => void
  onSearch: (search: string) => void
  onDone?: () => void
  onViewAll: () => void
}) {
  const language = useLanguage()
  const summary = () => props.variant === "summary"

  const placement = createMemo(() =>
    summary() ? (language.direction() === "rtl" ? "right-start" : "left-start") : "bottom",
  )

  const [search, setSearch] = createStore({ workspaces: "", branches: "" })
  let searchInput: HTMLInputElement | undefined
  let branchSearchInput: HTMLInputElement | undefined
  let focusSearch = false
  const branchTruncation = createTruncatedText()

  const focusWorktreeSearch = () =>
    requestAnimationFrame(() => requestAnimationFrame(() => searchInput?.focus({ preventScroll: true })))

  let pending: { type: "select"; value: string } | { type: "create"; branch: string } | { type: "viewAll" } | undefined
  const selected = () => (sameDirectory(props.value, props.projectRoot) ? "main" : props.value)

  const workspaces = createMemo(() => {
    const query = search.workspaces.trim().toLowerCase()

    if (!query) return props.workspaces

    return props.workspaces.filter((workspace) => getFilename(workspace).toLowerCase().includes(query))
  })

  const icon = () => {
    if (selected() === "main") return "monitor"

    if (selected() === "create") return "plus"

    return "outline-worktree"
  }

  const select = (value: string) => {
    pending = { type: "select", value }
  }

  const onOpenChange = (open: boolean) => {
    if (open) {
      setSearch({ workspaces: "", branches: "" })
      props.onSearch("")

      return
    }

    const action = pending
    pending = undefined

    if (action?.type === "select") props.onChange(action.value)

    if (action?.type === "create") props.onCreate(action.branch)

    if (action?.type === "viewAll") {
      props.onViewAll()

      return
    }

    props.onDone?.()
  }

  const label = () => {
    if (selected() === "main")
      return language.t(summary() ? "session.new.workspace.local" : "session.new.workspace.triggerLocal")

    if (props.value === "create") return language.t("workspace.new")

    return getFilename(props.value)
  }

  return (
    <>
      <Show when={!summary()}>
        <span class="hidden select-none opacity-50 sm:inline mx-1">/</span>
      </Show>
      <Tooltip
        appearance={props.onboarding ? "large" : undefined}
        placement="top"
        openDelay={800}
        value={
          props.onboarding ? (
            <div class="flex flex-col gap-1 text-start">
              <div class="flex items-center gap-1.5 font-[530] text-v2-text-text-base">
                <Icon name="outline-worktree" size="small" class="shrink-0 text-v2-text-text-accent" />
                <span>{language.t("workspace.onboarding.title")}</span>
              </div>
              <span class="font-[440] text-v2-text-text-muted">{language.t("workspace.onboarding.description")}</span>
            </div>
          ) : (
            language.t("session.new.workspace.trigger.tooltip")
          )
        }
        contentClass={props.onboarding ? "max-w-[280px]" : undefined}
        class={summary() ? "min-w-0 w-full" : "min-w-0"}
      >
        <Menu
          placement={placement()}
          gutter={4}
          overflowPadding={24}
          modal={summary() ? false : undefined}
          onOpenChange={onOpenChange}
        >
          <Menu.Trigger
            aria-description={language.t("session.new.workspace.trigger.tooltip")}
            class={
              summary()
                ? "session-summary-row"
                : "flex h-6 min-w-0 max-w-[203px] items-center gap-1.5 rounded-sm px-1.5 hover:bg-v2-overlay-simple-overlay-hover focus-visible:bg-v2-overlay-simple-overlay-hover focus-visible:outline-none data-[expanded]:bg-v2-overlay-simple-overlay-pressed data-[expanded]:text-v2-text-text-muted"
            }
          >
            <Icon
              name={icon()}
              class={`shrink-0 ${summary() || selected() === "main" || selected() === "create" ? "text-v2-icon-icon-muted" : "text-v2-icon-icon-accent"}`}
            />
            <span class={summary() ? "session-summary-label" : "min-w-0 truncate"}>{label()}</span>
            <Show when={props.onboarding}>
              <span
                data-slot="workspace-onboarding-dot"
                aria-hidden="true"
                class="size-1.5 shrink-0 rounded-full bg-v2-text-text-accent"
              />
            </Show>
            <Icon
              name={summary() ? "fill-triangle-down" : "chevron-down"}
              size={summary() ? "normal" : "small"}
              class="session-summary-menu-indicator shrink-0 text-v2-icon-icon-muted"
            />
          </Menu.Trigger>
          <Menu.Portal>
            <Menu.Content class="w-[200px]">
              <Menu.Group>
                <Menu.GroupLabel>{language.t("session.new.workspace.runIn")}</Menu.GroupLabel>
                <Menu.Item onSelect={() => select("main")}>
                  <Icon name="monitor" />
                  <Tooltip
                    placement="right"
                    openDelay={800}
                    value={language.t("session.new.workspace.local.tooltip")}
                    contentClass="max-w-[140px]"
                    class="min-w-0 flex-1"
                  >
                    <span class="min-w-0 truncate">{language.t("session.new.workspace.local")}</span>
                  </Tooltip>
                  <Show when={selected() === "main"}>
                    <Icon name="check" size="small" class="shrink-0" />
                  </Show>
                </Menu.Item>
                <Menu.Item onSelect={() => select("create")}>
                  <Icon name="plus" />
                  <Tooltip
                    placement="right"
                    openDelay={800}
                    value={language.t("session.new.workspace.new.tooltip")}
                    contentClass="max-w-[140px]"
                    class="min-w-0 flex-1"
                  >
                    <span class="min-w-0 truncate">{language.t("workspace.new")}</span>
                  </Tooltip>
                  <Show when={selected() === "create"}>
                    <Icon name="check" size="small" class="shrink-0" />
                  </Show>
                </Menu.Item>
              </Menu.Group>
              <Show when={props.workspaces.length > 0}>
                <Menu.Separator class="h-[0.5px]" />
                <Menu.Sub
                  gutter={0}
                  overlap
                  overflowPadding={24}
                  onOpenChange={(open) => {
                    if (!open) {
                      focusSearch = false

                      return
                    }

                    if (!focusSearch || props.workspaces.length < 10) return
                    focusSearch = false
                    focusWorktreeSearch()
                  }}
                >
                  <Menu.SubTrigger
                    onClick={focusWorktreeSearch}
                    onKeyDown={(event) => {
                      if (
                        event.key === "ArrowRight" ||
                        event.key === "ArrowLeft" ||
                        event.key === "Enter" ||
                        event.key === " "
                      )
                        focusSearch = true
                    }}
                  >
                    <Icon name="outline-worktree" />
                    <span class="min-w-0 flex-1 truncate">{language.t("session.new.workspace.existingLabel")}</span>
                  </Menu.SubTrigger>
                  <Menu.Portal>
                    <Menu.SubContent class="max-h-[66.667dvh] w-[200px] overflow-y-auto !pb-0 [&>[data-component=menu-v2-item]:last-child]:mb-0.5 [@media(max-height:600px)]:max-h-[calc(100dvh-48px)]">
                      <Show when={props.workspaces.length >= 10}>
                        <div class="flex h-7 items-center gap-2 rounded-sm ps-3 pe-2 text-v2-icon-icon-muted">
                          <Icon name="magnifying-glass" size="small" class="shrink-0" />
                          <input
                            ref={(element) => {
                              searchInput = element
                            }}
                            value={search.workspaces}
                            placeholder={language.t("session.new.workspace.search.placeholder")}
                            aria-label={language.t("session.new.workspace.search.placeholder")}
                            class="h-7 min-w-0 flex-1 border-0 bg-transparent text-[13px] font-[440] leading-5 tracking-[-0.04px] text-v2-text-text-base outline-none placeholder:text-v2-text-text-faint"
                            onInput={(event) => setSearch("workspaces", event.currentTarget.value)}
                            onKeyDown={(event) => {
                              if (
                                event.key === "Escape" ||
                                event.key === "ArrowDown" ||
                                event.key === "ArrowUp" ||
                                event.key === "Enter"
                              )
                                return
                              event.stopPropagation()
                            }}
                          />
                        </div>
                      </Show>
                      <For each={workspaces()}>
                        {(workspace) => (
                          <Menu.Item onSelect={() => select(workspace)}>
                            <Icon name="outline-worktree" />
                            <span class="min-w-0 flex-1 truncate">{getFilename(workspace)}</span>
                            <Show when={selected() === workspace}>
                              <Icon name="check" size="small" class="shrink-0" />
                            </Show>
                          </Menu.Item>
                        )}
                      </For>
                      <Show when={search.workspaces.trim() && workspaces().length === 0}>
                        <div class="px-3 py-4 text-center text-[13px] font-[440] leading-5 text-v2-text-text-muted">
                          {language.t("session.new.workspace.search.empty")}
                        </div>
                      </Show>
                      <Menu.Separator class="h-[0.5px]" />
                      <Menu.Item onSelect={() => (pending = { type: "viewAll" })}>
                        <span class="min-w-0 flex-1 truncate">{language.t("common.viewAll")}</span>
                      </Menu.Item>
                    </Menu.SubContent>
                  </Menu.Portal>
                </Menu.Sub>
              </Show>
            </Menu.Content>
          </Menu.Portal>
        </Menu>
      </Tooltip>
      <Show
        when={selected() === "create" && props.branch}
        fallback={
          summary() ? (
            <Show when={props.branch}>
              <div class="session-summary-row">
                <Icon name="branch" class="shrink-0 text-v2-icon-icon-muted" />
                <span dir="auto" class="session-summary-label">
                  {props.branch}
                </span>
              </div>
            </Show>
          ) : (
            <PromptGitStatus branch={props.branch} from={selected() === "create"} class="ms-1" />
          )
        }
      >
        <Tooltip
          placement="top"
          value={language.t("session.new.workspace.fromBranch", { branch: props.branch! })}
          disabled={!branchTruncation.truncated()}
          class={summary() ? "min-w-0 w-full" : "ms-1 min-w-0 max-w-[220px]"}
          contentClass="max-w-[calc(100vw-32px)] break-all"
        >
          <Menu placement={placement()} gutter={4} modal={summary() ? false : undefined} onOpenChange={onOpenChange}>
            <Menu.Trigger
              class={
                summary()
                  ? "session-summary-row"
                  : "flex h-6 min-w-0 max-w-[220px] items-center gap-1.5 rounded-full bg-v2-background-bg-layer-02 px-2.5 text-[13px] font-[440] leading-5 tracking-[-0.04px] text-v2-text-text-faint transition-colors hover:bg-v2-background-bg-layer-03 hover:text-v2-text-text-muted focus-visible:bg-v2-background-bg-layer-03 focus-visible:text-v2-text-text-muted focus-visible:outline-none data-[expanded]:bg-v2-background-bg-layer-03 data-[expanded]:text-v2-text-text-muted"
              }
            >
              <Icon name="branch-out" size={summary() ? "normal" : "small"} class="shrink-0 text-v2-icon-icon-muted" />
              <span ref={branchTruncation.observe} class={summary() ? "session-summary-label" : "min-w-0 truncate"}>
                {language.t(summary() ? "session.summary.basedOn" : "session.new.workspace.fromBranch", {
                  branch: props.branch!,
                })}
              </span>
              <Icon
                name={summary() ? "fill-triangle-down" : "chevron-down"}
                size={summary() ? "normal" : "small"}
                class="session-summary-menu-indicator shrink-0 text-v2-icon-icon-muted"
              />
            </Menu.Trigger>
            <Menu.Portal>
              <Menu.Content
                class="w-[243px] overflow-hidden rounded-md border-0 bg-v2-background-bg-layer-01 shadow-[var(--v2-elevation-floating)] focus:outline-none"
                onOpenAutoFocus={(event) => {
                  event.preventDefault()
                  // Kobalte defers its list autofocus until after the focus scope opens.
                  setTimeout(() => requestAnimationFrame(() => branchSearchInput?.focus({ preventScroll: true })))
                }}
              >
                <div class="flex h-7 shrink-0 items-center gap-2 rounded-sm pl-3 pr-1 text-v2-icon-icon-muted">
                  <Icon name="magnifying-glass" size="small" class="shrink-0" />
                  <input
                    ref={(element) => {
                      branchSearchInput = element
                    }}
                    value={search.branches}
                    placeholder={language.t("session.new.workspace.branch.search.placeholder")}
                    aria-label={language.t("session.new.workspace.branch.search.placeholder")}
                    class="h-7 min-w-0 flex-1 border-0 bg-transparent text-[13px] font-[440] leading-5 tracking-[-0.04px] text-v2-text-text-base outline-none placeholder:text-v2-text-text-faint"
                    onInput={(event) => {
                      setSearch("branches", event.currentTarget.value)
                      props.onSearch(event.currentTarget.value)
                    }}
                    onKeyDown={(event) => {
                      if (
                        event.key === "Escape" ||
                        event.key === "ArrowDown" ||
                        event.key === "ArrowUp" ||
                        event.key === "Enter"
                      )
                        return
                      event.stopPropagation()
                    }}
                  />
                  <Show when={search.branches.trim()}>
                    <button
                      type="button"
                      class="flex size-5 items-center justify-center rounded-sm bg-transparent text-v2-icon-icon-faint transition-colors hover:text-v2-icon-icon-base focus-visible:text-v2-icon-icon-base active:text-v2-icon-icon-base"
                      onPointerDown={(event) => event.preventDefault()}
                      onClick={() => {
                        setSearch("branches", "")
                        props.onSearch("")
                      }}
                      aria-label={language.t("common.clear")}
                    >
                      <Icon name="circle-xmark" />
                    </button>
                  </Show>
                </div>
                <div class="max-h-[224px] overflow-y-auto">
                  <Menu.RadioGroup value={props.branch}>
                    <For each={props.branches}>
                      {(branch) => (
                        <Menu.RadioItem
                          value={branch}
                          class="h-7 gap-2 rounded-sm px-3 text-[13px] font-[440] leading-5 tracking-[-0.04px] text-v2-text-text-base [font-family:var(--v2-font-family-sans)] data-[highlighted]:!bg-v2-overlay-simple-overlay-hover"
                          closeOnSelect
                          onSelect={() => (pending = { type: "create", branch })}
                        >
                          <span class="min-w-0 truncate leading-5">{branch}</span>
                        </Menu.RadioItem>
                      )}
                    </For>
                  </Menu.RadioGroup>
                </div>
              </Menu.Content>
            </Menu.Portal>
          </Menu>
        </Tooltip>
      </Show>
    </>
  )
}

export function PromptGitStatus(props: { branch?: string; noGit?: boolean; from?: boolean; class?: string }) {
  const language = useLanguage()
  const truncation = createTruncatedText()

  const label = () => {
    if (props.noGit) return language.t("session.new.git.none")

    if (!props.branch) return undefined

    if (props.from) return language.t("session.new.workspace.fromBranch", { branch: props.branch })

    return props.branch
  }

  const icon = () => {
    if (props.noGit) return "monitor"

    if (props.from) return "branch-out"

    return "branch"
  }

  return (
    <Show when={label()}>
      {(value) => (
        <Tooltip
          placement="top"
          value={value()}
          disabled={!truncation.truncated()}
          class={`min-w-0 max-w-[220px] ${props.class ?? ""}`}
          contentClass="max-w-[calc(100vw-32px)] break-all"
        >
          <div class="flex h-6 min-w-0 max-w-[220px] items-center gap-1.5 rounded-full bg-v2-background-bg-layer-02 px-2.5 text-[13px] font-[440] leading-5 tracking-[-0.04px] text-v2-text-text-faint">
            <Icon name={icon()} size="small" class="shrink-0 text-v2-icon-icon-muted" />
            <span ref={truncation.observe} class="min-w-0 truncate">
              {value()}
            </span>
          </div>
        </Tooltip>
      )}
    </Show>
  )
}

function createTruncatedText() {
  const [truncated, setTruncated] = createSignal(false)

  return {
    truncated,
    observe: (element: HTMLSpanElement) =>
      createResizeObserver(element, () => setTruncated(element.scrollWidth > element.clientWidth)),
  }
}

type Provider = {
  id: string
  integrationID?: string
  name: string
}

export function consoleProviderGroup<T extends Provider>(providers: readonly T[]) {
  const root = providers.find((provider) => provider.id === "opencode" && provider.integrationID === "opencode")
  const suffix = " / OpenCode"

  if (!root?.name.endsWith(suffix)) return
  const workspace = root.name.slice(0, -suffix.length).trim()

  if (!workspace) return
  const prefix = `${workspace} / `

  return {
    root,
    workspace,
    prefix,
    providers: providers.filter(
      (provider) => provider.integrationID === "opencode" && provider.name.startsWith(prefix),
    ),
  }
}

export function consoleProviderName(group: { prefix: string }, name: string) {
  return name.startsWith(group.prefix) ? name.slice(group.prefix.length) : name
}

import { useServerSDK } from "@/runtime/server/client"
import { useData } from "@/runtime/server/current"
import { createEffect, type Accessor } from "solid-js"

export function useIntegrations(directory: Accessor<string | undefined>) {
  const serverSDK = useServerSDK()
  const data = useData()

  createEffect(() => {
    if (serverSDK.connection.status() !== "connected") return
    const value = directory()
    void (async () => {
      const ref = value ? { directory: value } : undefined

      if (!ref) await data.location.syncInfo()
      await data.location.integration.sync(ref ?? data.location.default())
    })().catch(() => undefined)
  })

  const location = () => {
    const value = directory()

    return value ? { directory: value } : undefined
  }

  return {
    ready: () => data.location.integration.list(location()) !== undefined,
    list: () => data.location.integration.list(location()) ?? [],
  }
}

import type { PluginInfo } from "@opencode/client"

export function pluginLabel(plugin: PluginInfo) {
  if (plugin.id) return plugin.id

  if (plugin.source.type === "package") return plugin.source.target

  if (plugin.source.type === "local") return plugin.source.path

  return plugin.source.type
}

export function pluginLabels(plugins: readonly PluginInfo[]) {
  return plugins.filter((plugin) => plugin.source.type !== "builtin").map(pluginLabel)
}

import { useData } from "@/runtime/server/current"
import { useServerSDK } from "@/runtime/server/client"
import { normalizeProviderList } from "@/runtime/server/global-sync/utils"
import { Iterable, pipe } from "effect"
import { createEffect, createMemo, type Accessor } from "solid-js"
import type { ProviderListResponse } from "@/runtime/server/types"
import { useIntegrations } from "./integrations"
import { popularProviders } from "./order"

export { popularProviders } from "./order"

const emptyProviderCatalog: ProviderListResponse = { all: new Map(), connected: [], default: {} }

const popularProviderSet = new Set(popularProviders)

export function useProviders(directory: Accessor<string | undefined>) {
  const data = useData()
  const sdk = useServerSDK()

  const location = () => {
    const dir = directory()

    return dir ? { directory: dir } : undefined
  }

  createEffect(() => {
    if (sdk.connection.status() !== "connected") return
    const ref = location()
    void (async () => {
      if (!ref) await data.location.syncInfo()
      const resolved = ref ?? data.location.default()
      await Promise.all([data.location.provider.sync(resolved), data.location.model.sync(resolved)])
    })().catch(() => undefined)
  })
  const integrations = useIntegrations(directory)

  const providers = createMemo(() => {
    const ref = location()
    const provider = data.location.provider.list(ref)
    const model = data.location.model.list(ref)

    if (!provider || !model) return emptyProviderCatalog

    return normalizeProviderList(provider, model)
  })

  const ready = () => {
    const ref = location()

    return data.location.provider.list(ref) !== undefined && data.location.model.list(ref) !== undefined
  }

  return {
    ready,
    all: () => providers().all,
    default: () => providers().default,
    // V2 servers list only available providers, so the connectable catalog
    // comes from the integration list, with the provider catalog as fallback.
    popular: () => {
      const catalog = integrations
        .list()
        .filter((integration) => popularProviderSet.has(integration.id))
        .map((integration) => ({ id: integration.id, name: integration.name }))

      const seen = new Set(catalog.map((integration) => integration.id))

      return pipe(
        providers().all,
        Iterable.map(([, p]) => p),
        Iterable.filter((p) => popularProviderSet.has(p.id) && !seen.has(p.id)),
        Iterable.map((p) => ({ id: p.id, name: p.name })),
        (v) => [...catalog, ...v],
      )
    },
    connected: () => {
      const connected = new Set(providers().connected)

      return pipe(
        providers().all,
        Iterable.map(([, p]) => p),
        Iterable.filter((p) => connected.has(p.id)),
        (v) => Array.from(v),
      )
    },
    // Any stored or detected connection, or a provider with models beyond the keyless OpenCode catalog.
    // Undefined until both catalogs load, so callers never mistake loading for a first run.
    anyConnection: () => {
      if (!integrations.ready() || !ready()) return undefined

      if (integrations.list().some((integration) => integration.connections.length > 0)) return true

      return providers().connected.some(
        (id) => id !== "opencode" && Object.keys(providers().all.get(id)?.models ?? {}).length > 0,
      )
    },
    paid: () => {
      const connected = new Set(providers().connected)

      const paid = [
        ...Iterable.filter(
          providers().all,
          ([id]) =>
            connected.has(id) &&
            (id !== "opencode" || Object.values(providers().all.get(id)?.models ?? {}).some((m) => m.cost?.input)),
        ),
      ]

      return paid
    },
  }
}

