                            >
                              <span class="settings-models-group-chevron">
                                <Icon name="chevron-down" size="small" classList={{ collapsed: !expanded() }} />
                              </span>
                              <span class="settings-models-group-label">
                                <ProviderModelIcon provider={group.provider} class="shrink-0" />
                                <span class="settings-section-title">{group.provider.name}</span>
                              </span>
                            </button>
                          </h3>
                          <Show when={expanded()}>
                            <ConnectionModelList items={group.models} />
                          </Show>
                        </section>
                      )
                    }}
                  </For>
                </Show>
              }
            >
              <div class="provider-model-groups provider-model-groups--dialog">
                <For each={connectionGroups()}>
                  {(group) => (
                    <ProviderModelGroup
                      provider={group.provider}
                      name={connectionGroupName(group.provider.name)}
                      expanded={!state.collapsed[group.provider.id]}
                      onExpandedChange={(value) => setState("collapsed", group.provider.id, !value)}
                    >
                      <ConnectionModelList items={group.models} />
                    </ProviderModelGroup>
                  )}
                </For>
              </div>
            </Show>
          </div>
        </div>
        <div
          data-component="first-provider-model-footer"
          class="-mx-5 flex h-15 shrink-0 items-center justify-end border-t border-v2-border-border-muted px-4"
        >
          <Button variant="contrast" disabled={!selectedModel()} onClick={() => void startWithModel()}>
            {language.t("common.continue")}
          </Button>
        </div>
      </div>
    )
  }

  return (
    <Show when={!state.models} fallback={<FirstConnectionModels />}>
      <div class="flex min-h-0 flex-1 flex-col">
        <div
          class={isConsole ? "flex shrink-0 items-center gap-2 px-3 pb-6" : "flex h-10 shrink-0 items-start gap-2 px-3"}
        >
          <ProviderModelIcon
            provider={provider()}
            class={isConsole ? "shrink-0 text-v2-icon-icon-base" : "mt-0.5 shrink-0 text-v2-icon-icon-base"}
          />
          <div class="text-[15px] font-[530] leading-5 tracking-[-0.13px] text-v2-text-text-base">
            <DialogTitle>
              <Switch>
                <Match when={showAccounts()}>{provider().name}</Match>
                <Match when={isConsole && controller.auth.state() === "error"}>
                  {language.t("provider.connect.opencode.errorTitle")}
                </Match>
                <Match when={consoleSignIn()}>
                  {language.t(
                    props.provider === "opencode-go"
                      ? "provider.connect.console.titleGo"
                      : "provider.connect.console.title",
                  )}
                </Match>
                <Match
                  when={
                    props.provider === "anthropic" && controller.currentMethod()?.label?.toLowerCase().includes("max")
                  }
                >
                  {language.t("provider.connect.title.anthropicProMax")}
                </Match>
                <Match when={props.provider === "opencode"}>
                  {language.t("provider.connect.title", { provider: language.t("provider.connect.opencode.name") })}
                </Match>
                <Match when={true}>{language.t("provider.connect.title", { provider: provider().name })}</Match>
              </Switch>
            </DialogTitle>
          </div>
        </div>
        <div
          data-component="provider-connect-content"
          class={isConsole ? "flex min-h-0 flex-1 flex-col overflow-y-auto pb-4" : "flex min-h-0 flex-1 flex-col"}
        >
          <Show when={remote}>
            <div class="mb-5 px-3">
              <RemoteAuthNotice server={sdk.server} />
            </div>
          </Show>
          <Switch>
            <Match when={state.noModels && controller.auth.state() !== "error"}>
              <ConsoleNoModels />
            </Match>
            <Match when={consoleSignIn()}>
              <div class="px-3">
                <ConsoleAuthorization
                  code={code()}
                  browserFailed={controller.browserFailed()}
                  copied={state.copied}
                  copyFailed={state.copyFailed}
                  onCopy={() => void copyLink()}
                  onOpen={() => void controller.auth.open()}
                />
              </div>
            </Match>
            <Match when={showAccounts() && controller.methodIndex() === undefined}>
              <AccountsView />
            </Match>
            <Match when={consoleIntro()}>
              <ConsoleIntro />
            </Match>
            <Match when={controller.busy()}>
              <div class="px-3">
                <StatusRow>{language.t("provider.connect.status.inProgress")}</StatusRow>
              </div>
            </Match>
            <Match when={controller.methodIndex() === undefined}>
              <MethodSelection />
            </Match>
            <Match when={controller.auth.state() === "form"}>
              <AuthFormView />
            </Match>
            <Match when={controller.auth.state() === "error"}>
              <div class="px-3">
                <ErrorRow />
              </div>
            </Match>
            <Match when={controller.currentMethod()?.type === "key"}>
              <ApiAuthView />
            </Match>
            <Match when={controller.authorization()?.mode === "code"}>
              <OAuthCodeView />
            </Match>
            <Match when={controller.authorization()?.mode === "auto"}>
              <OAuthAutoView />
            </Match>
          </Switch>
        </div>
      </div>
    </Show>
  )
}

import { Component, createMemo, Show } from "solid-js"
import { useData } from "@/runtime/server/current"
import { useWorkspaceLocation } from "@/workspaces/location"
import { Dialog, DialogBody, DialogHeader, DialogTitleGroup } from "@opencode/ui/dialog"
import { List } from "@opencode/ui/list"
import { Switch } from "@opencode/ui/switch"
import { useLanguage } from "@/runtime/i18n/language"
import { useMcpToggle } from "@/providers/connect/mcp"

const statusLabels = {
  connected: "mcp.status.connected",
  failed: "mcp.status.failed",
  needs_auth: "mcp.status.needs_auth",
  disabled: "mcp.status.disabled",
} as const

export const DialogSelectMcp: Component = () => {
  const data = useData()
  const sdk = useWorkspaceLocation()
  const language = useLanguage()

  const items = createMemo(() =>
    (data.location.mcp.server.list({ directory: sdk().directory }) ?? [])
      .map((server) => ({ name: server.name, status: server.status.status }))
      .sort((a, b) => a.name.localeCompare(b.name)),
  )

  const toggle = useMcpToggle(() => sdk().directory)

  const enabledCount = createMemo(() => items().filter((i) => i.status === "connected").length)
  const totalCount = createMemo(() => items().length)

  return (
    <Dialog>
      <DialogHeader>
        <DialogTitleGroup
          title={language.t("dialog.mcp.title")}
          description={language.t("dialog.mcp.description", { enabled: enabledCount(), total: totalCount() })}
        />
      </DialogHeader>
      <DialogBody>
        <List
          class="px-3"
          search={{ placeholder: language.t("common.search.placeholder"), autofocus: true }}
          emptyMessage={language.t("dialog.mcp.empty")}
          key={(x) => x?.name ?? ""}
          items={items}
          filterKeys={["name", "status"]}
          sortBy={(a, b) => a.name.localeCompare(b.name)}
          onSelect={(x) => {
            if (!x || x.status === "pending" || toggle.isPending) return
            toggle.mutate(x.name)
          }}
        >
          {(i) => {
            const mcpStatus = () =>
              data.location.mcp.server.list({ directory: sdk().directory })?.find((server) => server.name === i.name)
                ?.status

            const status = () => mcpStatus()?.status

            const statusLabel = () => {
              const key = status() ? statusLabels[status() as keyof typeof statusLabels] : undefined

              if (!key) return

              return language.t(key)
            }

            const error = () => {
              const s = mcpStatus()

              if (s?.status === "failed") return s.error
            }

            const enabled = () => status() === "connected"

            return (
              <div class="w-full flex items-center justify-between gap-x-3">
                <div class="flex flex-col gap-0.5 min-w-0">
                  <div class="flex items-center gap-2">
                    <span class="truncate">{i.name}</span>
                    <Show when={statusLabel()}>
                      <span class="text-11-regular text-text-weaker">{statusLabel()}</span>
                    </Show>
                  </div>
                  <Show when={error()}>
                    <span class="text-11-regular text-text-weaker truncate">{error()}</span>
                  </Show>
                </div>
                <div onClick={(e) => e.stopPropagation()}>
                  <Switch
                    appearance="standard"
                    checked={enabled()}
                    disabled={status() === "pending" || (toggle.isPending && toggle.variables === i.name)}
                    onChange={() => {
                      if (toggle.isPending) return
                      toggle.mutate(i.name)
                    }}
                  />
                </div>
              </div>
            )
          }}
        </List>
      </DialogBody>
    </Dialog>
  )
}

import { useMutation } from "@tanstack/solid-query"
import type { Accessor } from "solid-js"
import { useLanguage } from "@/runtime/i18n/language"
import { useData } from "@/runtime/server/current"
import { useServerSDK } from "@/runtime/server/client"
import { usePlatform } from "@/runtime/platform/platform"
import { showToast } from "@/shell/notifications/toast"

export type McpControls = {
  readonly preview: boolean
  readonly states: Readonly<Record<string, boolean>>
  readonly pending: boolean
  change: (name: string, enabled: boolean) => void
}

export function useMcpToggle(directory?: Accessor<string | undefined>, onSuccess?: () => unknown) {
  const data = useData()
  const serverSDK = useServerSDK()
  const platform = usePlatform()
  const language = useLanguage()

  const location = () => {
    const value = directory ? directory() : data.location.default().directory

    return value ? { directory: value } : undefined
  }

  return useMutation(() => ({
    mutationFn: async (input: string | { name: string; enabled: boolean; directory?: string }) => {
      const name = typeof input === "string" ? input : input.name
      const ref = typeof input !== "string" && input.directory ? { directory: input.directory } : location()
      const server = (await serverSDK.api.mcp.list({ location: ref })).data.find((item) => item.name === name)

      if (!server || (server.status.status === "pending" && typeof input === "string")) return
      const enabled = typeof input === "string" ? server.status.status !== "connected" : input.enabled

      if (!enabled) {
        await serverSDK.api.mcp.disconnect({ server: name, location: ref })
      }

      if (enabled && server.status.status !== "needs_auth") {
        await serverSDK.api.mcp.connect({ server: name, location: ref })
      }

      data.location.mcp.server.invalidate(ref)
      await data.location.mcp.server.sync(ref)
      const current = data.location.mcp.server.list(ref)?.find((item) => item.name === name)

      if (enabled && current?.status.status === "needs_auth" && current.integrationID) {
        const integration = await serverSDK.api.integration.get({ integrationID: current.integrationID, location: ref })
        const method = integration.data?.methods.find((item) => item.type === "oauth" && !item.form?.length)

        if (!method || method.type !== "oauth") throw new Error(language.t("mcp.auth.interactiveForm", { name }))

        const attempt = await serverSDK.api.integration.oauth.connect({
          integrationID: current.integrationID,
          methodID: method.id,
          location: ref,
        })

        platform.openExternal(attempt.data.url)
      }

      data.location.mcp.resource.invalidate(ref)
      await Promise.all([data.location.mcp.resource.sync(ref), onSuccess?.()])
      // A successful HTTP response can still leave the MCP connection in a failed state.
      const status = current?.status

      if (status?.status === "failed") throw new Error(`${name}: ${status.error}`)
    },
    onError: (error) =>
      showToast({
        variant: "error",
        title: language.t("common.requestFailed"),
        description: error instanceof Error ? error.message : String(error),
      }),
  }))
}

import { expect, test } from "bun:test"
import { authServerName } from "./remote"

const contributed = {
  type: "extension",
  key: "ssh:production",
  extension: "ssh",
  state: "ready",
  connecting: false,
  authenticationRequired: false,
  managed: true,
  http: { url: "http://127.0.0.1:4096" },
} as const

test("SSH disclosure uses the remote identity even with a loopback proxy", () => {
  expect(authServerName({ ...contributed, displayName: "Production server" })).toBe("Production server")
})

test.each([
  {
    name: "local Desktop",
    server: { type: "sidecar", variant: "base", http: { url: "http://127.0.0.1:4096" } } as const,
    expected: undefined,
  },
  {
    name: "localhost HTTP",
    server: { type: "http", http: { url: "http://localhost:4096" } } as const,
    expected: undefined,
  },
  {
    name: "IPv4 loopback HTTP",
    server: { type: "http", http: { url: "http://127.0.0.1:4096" } } as const,
    expected: undefined,
  },
  {
    name: "IPv6 loopback HTTP",
    server: { type: "http", http: { url: "http://[::1]:4096" } } as const,
    expected: undefined,
  },
  {
    name: "WSL",
    server: { ...contributed, key: "wsl:Ubuntu", extension: "wsl", displayName: "Ubuntu" } as const,
    expected: "Ubuntu",
  },
  {
    name: "remote HTTP",
    server: { type: "http", http: { url: "https://production.example" } } as const,
    expected: "production.example",
  },
])("remote disclosure for a $name connection names $expected", ({ server, expected }) => {
  expect(authServerName(server)).toBe(expected)
})

import { Show } from "solid-js"
import { useLanguage } from "@/runtime/i18n/language"
import { ServerConnection, serverName } from "@/runtime/server/registry"

export function authServerName(server: ServerConnection.Any) {
  if (ServerConnection.builtin(server)) return undefined

  if (server.type === "http" && ["localhost", "127.0.0.1", "[::1]"].includes(new URL(server.http.url).hostname))
    return undefined

  return serverName(server)
}

export function RemoteAuthNotice(props: { server: ServerConnection.Any }) {
  const language = useLanguage()

  return (
    <Show when={authServerName(props.server)}>
      {(name) => (
        <div
          class="rounded-md border border-v2-border-border-base bg-v2-background-bg-layer-02 p-3 text-[13px] leading-5"
          role="note"
        >
          <p class="font-medium text-v2-text-text-base">
            {language.t("provider.connect.remote.title", { server: name() })}
          </p>
          <p class="text-v2-text-text-muted">{language.t("provider.connect.remote.description")}</p>
        </div>
      )}
    </Show>
  )
}

import { usePlatform } from "@/runtime/platform/platform"
import { useLanguage } from "@/runtime/i18n/language"
import { Button } from "@opencode/ui/button"
import { useDialog } from "@opencode/ui/context/dialog"
import { Dialog, DialogBody, DialogHeader, DialogTitleGroup } from "@opencode/ui/dialog"
import { JSX } from "solid-js"

export type DialogGoUpsellProps = {
  title: string
  description: JSX.Element
  link?: string
  actionLabel: string
  onClose?: (dontShowAgain?: boolean) => void
}

export function DialogUsageExceeded(props: DialogGoUpsellProps) {
  const dialog = useDialog()
  const language = useLanguage()
  const platform = usePlatform()

  const runAction = () => {
    if (props.link) platform.openExternal(props.link)
    props.onClose?.()
    dialog.close()
  }

  const dismiss = () => {
    props.onClose?.(true)
    dialog.close()
  }

  return (
    <Dialog fit>
      <DialogHeader>
        <DialogTitleGroup title={props.title} description={props.description} />
      </DialogHeader>
      <DialogBody>
        <div class="flex flex-col gap-4 pl-6 pr-2.5 pb-3">
          <div class="flex justify-end gap-2">
            <Button variant="ghost" size="large" onClick={dismiss}>
              {language.t("dialog.usageExceeded.dontShowAgain")}
            </Button>
            <Button variant="contrast" size="large" onClick={runAction}>
              {props.actionLabel}
            </Button>
          </div>
        </div>
      </DialogBody>
    </Dialog>
  )
}

import { Button } from "@opencode/ui/button"
import { useDialog } from "@opencode/ui/context/dialog"
import { Icon } from "@opencode/ui/icon"
import { IconButton } from "@opencode/ui/icon-button"
import { useMutation } from "@tanstack/solid-query"
import { TextField } from "@opencode/ui/text-field"
import { showToast } from "@/shell/notifications/toast"
import { batch, For } from "solid-js"
import { createStore, produce } from "solid-js/store"
import { ExternalLink } from "@/runtime/platform/external-link"
import { useData } from "@/runtime/server/current"
import { useLanguage } from "@/runtime/i18n/language"
import { type FormState, headerRow, modelRow, validateCustomProvider } from "./form"
import { CustomManagedProviderIcon } from "@/providers/models/provider-group"

export function CustomProviderForm(props: { autofocus?: boolean } = {}) {
  const dialog = useDialog()
  const data = useData()
  const language = useLanguage()

  const [form, setForm] = createStore<FormState>({
    providerID: "",
    name: "",
    baseURL: "",
    apiKey: "",
    models: [modelRow()],
    headers: [headerRow()],
    err: {},
  })

  const addModel = () => {
    setForm(
      "models",
      produce((rows) => {
        rows.push(modelRow())
      }),
    )
  }

  const removeModel = (index: number) => {
    if (form.models.length <= 1) return
    setForm(
      "models",
      produce((rows) => {
        rows.splice(index, 1)
      }),
    )
  }

  const addHeader = () => {
    setForm(
      "headers",
      produce((rows) => {
        rows.push(headerRow())
      }),
    )
  }

  const removeHeader = (index: number) => {
    if (form.headers.length <= 1) return
    setForm(
      "headers",
      produce((rows) => {
        rows.splice(index, 1)
      }),
    )
  }

  const setField = (key: "providerID" | "name" | "baseURL" | "apiKey", value: string) => {
    setForm(key, value)

    if (key === "apiKey") return
    setForm("err", key, undefined)
  }

  const setModel = (index: number, key: "id" | "name", value: string) => {
    batch(() => {
      setForm("models", index, key, value)
      setForm("models", index, "err", key, undefined)
    })
  }

  const setHeader = (index: number, key: "key" | "value", value: string) => {
    batch(() => {
      setForm("headers", index, key, value)
      setForm("headers", index, "err", key, undefined)
    })
  }

  const validate = () => {
    const output = validateCustomProvider({
      form,
      t: language.t,
      // TODO: Restore disabled-provider validation when V2 exposes config reads.
      disabledProviders: [],
      existingProviderIDs: new Set((data.location.provider.list() ?? []).map((provider) => provider.id)),
    })

    batch(() => {
      setForm("err", output.err)
      output.models.forEach((err, index) => setForm("models", index, "err", err))
      output.headers.forEach((err, index) => setForm("headers", index, "err", err))
    })

    return output.result
  }

  const saveMutation = useMutation(() => ({
    mutationFn: async (result: NonNullable<ReturnType<typeof validate>>): Promise<typeof result> => {
      // TODO: Restore custom providers when V2 exposes config and arbitrary credential APIs.
      throw new Error(language.t("provider.custom.unavailable"))
    },
    onSuccess: (result) => {
      dialog.close()
      showToast({
        variant: "success",
        icon: "circle-check",
        title: language.t("provider.connect.toast.connected.title", { provider: result.name }),
        description: language.t("provider.connect.toast.connected.description", { provider: result.name }),
      })
    },
    onError: (err) => {
      const message = err instanceof Error ? err.message : String(err)
      showToast({ title: language.t("common.requestFailed"), description: message })
    },
  }))

  const save = (e: SubmitEvent) => {
    e.preventDefault()

    if (saveMutation.isPending) return

    const result = validate()

    if (!result) return
    saveMutation.mutate(result)
  }

  return (
    <div class="flex flex-col gap-6 px-2.5 pb-3 overflow-y-auto max-h-[60vh]">
      <div class="px-2.5 flex gap-4 items-center">
        <CustomManagedProviderIcon class="size-5 shrink-0" />
        <div class="text-16-medium text-text-strong">{language.t("provider.custom.title")}</div>
      </div>

      <form onSubmit={save} class="px-2.5 pb-6 flex flex-col gap-6">
        <p class="text-14-regular text-text-base">
          {language.t("provider.custom.description.prefix")}
          <ExternalLink href="https://opencode.ai/docs/providers/#custom-provider" tabIndex={-1}>
            {language.t("provider.custom.description.link")}
          </ExternalLink>
          {language.t("provider.custom.description.suffix")}
        </p>

        <div class="flex flex-col gap-4">
          <TextField
            autofocus={props.autofocus ?? true}
            label={language.t("provider.custom.field.providerID.label")}
            placeholder={language.t("provider.custom.field.providerID.placeholder")}
            description={language.t("provider.custom.field.providerID.description")}
            value={form.providerID}
            onChange={(v) => setField("providerID", v)}
            validationState={form.err.providerID ? "invalid" : undefined}
            error={form.err.providerID}
          />
          <TextField
            label={language.t("provider.custom.field.name.label")}
            placeholder={language.t("provider.custom.field.name.placeholder")}
            value={form.name}
            onChange={(v) => setField("name", v)}
            validationState={form.err.name ? "invalid" : undefined}
            error={form.err.name}
          />
          <TextField
            label={language.t("provider.custom.field.baseURL.label")}
            placeholder={language.t("provider.custom.field.baseURL.placeholder")}
            value={form.baseURL}
            onChange={(v) => setField("baseURL", v)}
            validationState={form.err.baseURL ? "invalid" : undefined}
            error={form.err.baseURL}
          />
          <TextField
            label={language.t("provider.custom.field.apiKey.label")}
            placeholder={language.t("provider.custom.field.apiKey.placeholder")}
            description={language.t("provider.custom.field.apiKey.description")}
            value={form.apiKey}
            onChange={(v) => setField("apiKey", v)}
          />
        </div>

        <div class="flex flex-col gap-3">
          <label class="text-12-medium text-text-weak">{language.t("provider.custom.models.label")}</label>
          <For each={form.models}>
            {(m, i) => (
              <div class="flex gap-2 items-start" data-row={m.row}>
                <div class="flex-1">
                  <TextField
                    label={language.t("provider.custom.models.id.label")}
                    hideLabel
                    placeholder={language.t("provider.custom.models.id.placeholder")}
                    value={m.id}
                    onChange={(v) => setModel(i(), "id", v)}
                    validationState={m.err.id ? "invalid" : undefined}
                    error={m.err.id}
                  />
                </div>
                <div class="flex-1">
                  <TextField
                    label={language.t("provider.custom.models.name.label")}
                    hideLabel
                    placeholder={language.t("provider.custom.models.name.placeholder")}
                    value={m.name}
                    onChange={(v) => setModel(i(), "name", v)}
                    validationState={m.err.name ? "invalid" : undefined}
                    error={m.err.name}
                  />
                </div>
                <IconButton
                  type="button"
                  icon={<Icon name="trash" />}
                  variant="ghost"
                  class="mt-1.5"
                  onClick={() => removeModel(i())}
                  disabled={form.models.length <= 1}
                  aria-label={language.t("provider.custom.models.remove")}
                />
              </div>
            )}
          </For>
          <Button type="button" size="small" variant="ghost" icon="plus-small" onClick={addModel} class="self-start">
            {language.t("provider.custom.models.add")}
          </Button>
        </div>

        <div class="flex flex-col gap-3">
          <label class="text-12-medium text-text-weak">{language.t("provider.custom.headers.label")}</label>
          <For each={form.headers}>
            {(h, i) => (
              <div class="flex gap-2 items-start" data-row={h.row}>
                <div class="flex-1">
                  <TextField
                    label={language.t("provider.custom.headers.key.label")}
                    hideLabel
                    placeholder={language.t("provider.custom.headers.key.placeholder")}
                    value={h.key}
                    onChange={(v) => setHeader(i(), "key", v)}
                    validationState={h.err.key ? "invalid" : undefined}
                    error={h.err.key}
                  />
                </div>
                <div class="flex-1">
                  <TextField
                    label={language.t("provider.custom.headers.value.label")}
                    hideLabel
                    placeholder={language.t("provider.custom.headers.value.placeholder")}
                    value={h.value}
                    onChange={(v) => setHeader(i(), "value", v)}
                    validationState={h.err.value ? "invalid" : undefined}
                    error={h.err.value}
                  />
                </div>
                <IconButton
                  type="button"
                  icon={<Icon name="trash" />}
                  variant="ghost"
                  class="mt-1.5"
                  onClick={() => removeHeader(i())}
                  disabled={form.headers.length <= 1}
                  aria-label={language.t("provider.custom.headers.remove")}
                />
              </div>
            )}
          </For>
          <Button type="button" size="small" variant="ghost" icon="plus-small" onClick={addHeader} class="self-start">
            {language.t("provider.custom.headers.add")}
          </Button>
        </div>

        <Button
          class="w-auto self-start"
          type="submit"
          size="large"
          variant="contrast"
          disabled={saveMutation.isPending}
        >
          {saveMutation.isPending ? language.t("common.saving") : language.t("common.submit")}
        </Button>
      </form>
    </div>
  )
}

