                </button>
              </div>
            </div>
          </div>
        </div>
      </DialogBody>
    </Dialog>
  )
}

import { describe, expect, test } from "bun:test"
import { cycleModelVariant, getConfiguredAgentVariant, resolveModelVariant } from "./variant"

const variants = ["low", "high", "xhigh"]

describe("model variant", () => {
  test.each([
    { name: "applies when the model matches", providerID: "openai", modelID: "gpt-5.2", expected: "xhigh" },
    { name: "is ignored for another model", providerID: "anthropic", modelID: "claude-sonnet-4", expected: undefined },
  ])("the configured agent variant $name", ({ providerID, modelID, expected }) => {
    const value = getConfiguredAgentVariant({
      agent: { model: { providerID: "openai", modelID: "gpt-5.2" }, variant: "xhigh" },
      model: { providerID, modelID, variants: { low: {}, high: {}, xhigh: {} } },
    })

    expect(value).toBe(expected)
  })

  test.each([
    { name: "prefers the selected variant over configuration", selected: "high", expected: "high" },
    { name: "lets an explicit default override configuration", selected: null, expected: undefined },
  ])("resolve $name", ({ selected, expected }) => {
    expect(resolveModelVariant({ variants, selected, configured: "xhigh" })).toBe(expected)
  })

  test.each([
    { name: "a configured variant to the next", selected: undefined, configured: "high", expected: "xhigh" },
    { name: "the configured last variant to default", selected: undefined, configured: "xhigh", expected: undefined },
    { name: "an explicit default to the first variant", selected: null, configured: "xhigh", expected: "low" },
  ])("cycles from $name", ({ selected, configured, expected }) => {
    expect<string | undefined>(cycleModelVariant({ variants, selected, configured })).toBe(expected)
  })

  test("prefers a saved variant to configuration, including explicit Default", () => {
    const input = { variants: ["low", "high"], selected: undefined, configured: "high" }
    expect(resolveModelVariant({ ...input, preferred: "low" })).toBe("low")
    expect(resolveModelVariant({ ...input, preferred: "default" })).toBeUndefined()
    expect(resolveModelVariant({ ...input, preferred: "low", selected: null })).toBeUndefined()
    expect(resolveModelVariant({ ...input, preferred: "low", selected: "high" })).toBe("high")
    expect(cycleModelVariant({ ...input, preferred: "high" })).toBeUndefined()
    expect(cycleModelVariant({ ...input, preferred: "default" })).toBe("low")
  })

  test("normalizes unavailable selections instead of silently applying another variant", () => {
    expect(resolveModelVariant({ variants: ["low"], selected: "high", configured: "low" })).toBeUndefined()
    expect(
      resolveModelVariant({ variants: ["low"], selected: undefined, preferred: "high", configured: "low" }),
    ).toBeUndefined()
    expect(cycleModelVariant({ variants: [], selected: undefined, configured: undefined })).toBeUndefined()
  })
})

type AgentModel = {
  providerID: string
  modelID: string
}

type Agent = {
  model?: AgentModel
  variant?: string
}

type Model = AgentModel & {
  variants?: Record<string, unknown>
}

type VariantInput = {
  variants: string[]
  selected: string | null | undefined
  configured: string | undefined
  preferred?: string
}

export function getConfiguredAgentVariant(input: { agent: Agent | undefined; model: Model | undefined }) {
  if (!input.agent?.variant) return undefined

  if (!input.agent.model) return undefined

  if (!input.model?.variants) return undefined

  if (input.agent.model.providerID !== input.model.providerID) return undefined

  if (input.agent.model.modelID !== input.model.modelID) return undefined

  return input.agent.variant
}

export function resolveModelVariant(input: VariantInput) {
  if (input.selected === null) return undefined
  const value = input.selected ?? input.preferred ?? input.configured

  return value && value !== "default" && input.variants.includes(value) ? value : undefined
}

export function cycleModelVariant(input: VariantInput) {
  const current = resolveModelVariant(input)

  return input.variants[current ? input.variants.indexOf(current) + 1 : 0]
}

import { createMemo, createSignal, onCleanup, type Accessor } from "solid-js"
import createPresence from "solid-presence"

export function createAnimatedPresence<T>(
  value: Accessor<T | undefined>,
  element: Accessor<HTMLElement | null>,
  identity?: Accessor<unknown>,
  minimumDuration = 0,
) {
  const [tick, setTick] = createSignal(0)

  const animation = createMemo<{
    identity?: unknown
    show: boolean
    animate: boolean
    value: T | undefined
    started: number
  }>((previous) => {
    tick()
    const currentIdentity = identity?.()
    const current = value()
    const same = !identity || previous?.identity === currentIdentity
    const started = same && previous?.show ? previous.started : performance.now()

    const remaining =
      current === undefined && same && previous?.show ? minimumDuration - (performance.now() - started) : 0

    const show = current !== undefined || remaining > 0

    if (remaining > 0) {
      const timer = setTimeout(() => setTick((value) => value + 1), remaining)
      onCleanup(() => clearTimeout(timer))
    }

    return {
      identity: currentIdentity,
      show,
      started,
      animate: previous !== undefined && same && (previous.animate || previous.show !== show),
      value: current ?? (same ? previous?.value : undefined),
    }
  })

  const presence = createPresence({ show: () => animation().show, element })

  return {
    ...presence,
    show: () => animation().show,
    animate: () => animation().animate,
    value: () => animation().value,
  }
}

import { createContext, useContext } from "solid-js"
import type { createExtensionAttachment } from "./host-apis"

// Apart from `host-apis.tsx`, so session code such as the side panels reads the attachment without loading the HostApis.
const AttachmentContext = createContext<ReturnType<typeof createExtensionAttachment>>()

export function useExtensionAttachment() {
  const value = useContext(AttachmentContext)

  if (!value) throw new Error("Extension attachment is unavailable")

  return value
}

export const ExtensionAttachmentProvider = AttachmentContext.Provider

import type { Definition } from "@opencode/gui-extensions/sdk"
import { builtins } from "@opencode/gui-extensions/renderer"

export { builtins }

/** Dispatched in development with the re-evaluated built-in list after an extension's files change. */
export const BUILTINS_UPDATED = "opencode:gui-extensions-updated"

// Accepting the list here keeps an extension edit from reloading the window; hmr.tsx reloads that extension.
if (import.meta.hot)
  import.meta.hot.accept("@opencode/gui-extensions/renderer", (module) => {
    const next: readonly Definition[] | undefined = module?.builtins

    if (next) window.dispatchEvent(new CustomEvent(BUILTINS_UPDATED, { detail: next }))
  })

import { createEffect, on, onCleanup, Show } from "solid-js"
import { createStore } from "solid-js/store"
import { createEventListener } from "@solid-primitives/event-listener"
import { createResizeObserver } from "@solid-primitives/resize-observer"
import type { EmbedProps, Embeds } from "@opencode/gui-extensions/sdk"
import type { Bridge } from "@opencode/gui-extensions/sdk/bridge"

const geometry =
  /^(inset|left|right|top|bottom|translate|transform|scale|rotate|margin|padding|flex|grid|gap|row-gap|column-gap)|(^|-)(width|height)$/

type Input = {
  readonly bridge: Bridge | undefined
  readonly zoom: () => number
  readonly dialog: () => boolean
}

/** Main-process embeds laid out over the DOM box an extension renders for them. */
export function createEmbeds(input: Input): Embeds {
  return {
    View: (props) => {
      const bridge = input.bridge

      // Without the desktop bridge there is no embed; the box still renders its children.
      if (!bridge) return <div class={props.class}>{props.children}</div>

      return <EmbedView {...props} input={input} bridge={bridge} />
    },
    capture: (id) => input.bridge?.capture(id) ?? Promise.resolve(undefined),
  }
}

function EmbedView(props: EmbedProps & { input: Input; bridge: Bridge }) {
  const [store, setStore] = createStore<{
    visible: boolean
    snapshot: { id: string; url: string; presented: boolean } | undefined
  }>({
    visible: typeof document === "undefined" || document.visibilityState === "visible",
    // A still of the embed shown in the DOM while floating content covers the hidden native view.
    snapshot: undefined,
  })

  let element: HTMLDivElement | undefined
  let frame: number | undefined
  let layout: string | undefined
  let until = 0
  let capturing: string | undefined
  let release: ReturnType<typeof setTimeout> | undefined
  // The embed the last layout went to; it hides when another one takes the box.
  let placed: string | undefined
  const canvas = document.createElement("canvas")
  canvas.width = canvas.height = 1
  const paint = canvas.getContext("2d", { willReadFrequently: true })

  // Let the browser resolve colors, including custom themes using color formats
  // that Electron's color parser cannot read.
  const resolve = (color: string) => {
    if (!paint) return undefined
    paint.clearRect(0, 0, 1, 1)
    paint.fillStyle = color
    paint.fillRect(0, 0, 1, 1)
    const data = paint.getImageData(0, 0, 1, 1).data

    return [data[0], data[1], data[2], data[3]] as const
  }

  const hide = () => {
    if (placed) props.bridge.embed(placed)
    placed = undefined
  }

  // The native embed always paints above the DOM, so hide it while a floating
  // menu, select, or popover overlaps it. Tooltips are excluded.
  const covered = (rect: DOMRect) =>
    Array.from(document.querySelectorAll('[data-popper-positioner]:not(:has([role="tooltip"]))')).some((el) => {
      const r = el.getBoundingClientRect()

      return r.width > 0 && r.left < rect.right && r.right > rect.left && r.top < rect.bottom && r.bottom > rect.top
    })

  const replaceSnapshot = (next?: { id: string; url: string; presented: boolean }) => {
    if (store.snapshot?.url) URL.revokeObjectURL(store.snapshot.url)
    setStore("snapshot", next)
  }

  // Keep the embed on screen as a still under the floating content. The native view
  // stays visible until the still is on screen, so the box never flashes blank.
  const freeze = (id: string) => {
    clearTimeout(release)
    release = undefined

    if (store.snapshot?.id === id || capturing === id) return
    capturing = id
    void props.bridge
      .capture(id)
      .catch(() => undefined)
      .then(async (data) => {
        const url = data ? URL.createObjectURL(new Blob([new Uint8Array(data)], { type: "image/jpeg" })) : ""
        const image = new Image()

        if (url) image.src = url

        const decoded =
          !!url &&
          (await image
            .decode()
            .then(() => true)
            .catch(() => false))

        if (capturing !== id) {
          if (url) URL.revokeObjectURL(url)

          return
        }

        capturing = undefined
        // A failed capture still hides the embed; the box shows its background as before. A still that
        // cannot decode never paints, so Element Timing would never report it.
        replaceSnapshot({ id, url, presented: !decoded })
        schedule()
      })
  }

  // Main hides the native view at once, but a still reaches the screen only a few frames after it
  // enters the DOM, so wait for Element Timing to report the frame that presents it.
  const presentation = new PerformanceObserver((list) => {
    const snapshot = store.snapshot

    if (!snapshot || snapshot.presented) return

    if (!list.getEntries().some((entry) => "url" in entry && entry.url === snapshot.url)) return
    setStore("snapshot", "presented", true)
    schedule()
  })

  presentation.observe({ type: "element" })
  onCleanup(() => presentation.disconnect())

  const thaw = () => {
    capturing = undefined

    if (!store.snapshot || release !== undefined) return
    // Keep the still under the native view until the view has painted again.
    release = setTimeout(() => {
      release = undefined
      replaceSnapshot()
    }, 150)
  }

  const measure = () => {
    if (!element) return
    const id = props.id

    if (!id) return hide()
    const rect = element.getBoundingClientRect()
    const zoom = props.input.zoom()
    const left = Math.round(rect.left * zoom)
    const top = Math.round(rect.top * zoom)
    const right = Math.round(rect.right * zoom)
    const bottom = Math.round(rect.bottom * zoom)
    const shown = props.visible && store.visible && !props.input.dialog()
    const cover = !!props.frozen || covered(rect)

    if (shown && cover) freeze(id)

    if (!cover) thaw()
    const visible = shown && !(cover && store.snapshot?.id === id && store.snapshot.presented)

    // The cutout exposes the app backdrop outside the rounded card, not the embed inside it.
    const color =
      props.background ??
      getComputedStyle(element.closest(".bg-v2-background-bg-deep") ?? document.documentElement).backgroundColor

    const ring = props.radius ? cardRing(element) : undefined
    const viewport = { width: Math.round(window.innerWidth * zoom), height: Math.round(window.innerHeight * zoom) }

    const next = `${id}:${visible}:${left}:${top}:${right}:${bottom}:${viewport.width}:${viewport.height}:${color}:${ring?.color}:${ring?.width}:${window.devicePixelRatio}`

    if (next === layout) return
    layout = next

    const background = resolve(color)
    const border = ring && resolve(ring.color)

    if (placed !== id) hide()
    placed = id

    const box = {
      visible,
      bounds: { x: left, y: top, width: Math.max(0, right - left), height: Math.max(0, bottom - top) },
      viewport,
      radius: Math.round((props.radius ?? 0) * zoom),
    }

    const backed = background ? { ...box, background } : box

    props.bridge.embed(
      id,
      ring && border && border[3] > 0 ? { ...backed, border: { color: border, width: ring.width * zoom } } : backed,
    )
  }

  const tick = () => {
    frame = undefined
    measure()

    if (performance.now() < until) frame = requestAnimationFrame(tick)
  }

  const schedule = (duration = 0) => {
    until = Math.max(until, performance.now() + duration)

    if (frame === undefined) frame = requestAnimationFrame(tick)
  }

  createEffect(
    on(
      [
        props.input.zoom,
        props.input.dialog,
        () => store.visible,
        () => props.visible,
        () => props.id,
        () => props.frozen,
      ],
      () => {
        layout = undefined

        // The native views are not clipped by the retained panel's DOM. Hide before the next
        // animation frame so closing the panel cannot leave the embed above the app.
        if (!props.visible || !store.visible || props.input.dialog() || !props.id) return hide()
        schedule(300)
      },
    ),
  )
  // ResizeObserver runs after layout in the same frame; measuring here instead of on the next
  // animation frame keeps the native view in step with a region drag.
  createResizeObserver(() => element, measure)
  createEventListener(window, "resize", () => schedule(300))
  // A layout transition elsewhere, such as the chat column's width while the side pane opens, can
  // move the box without resizing it. Track it from when it actually runs, and settle on its end.
  createEventListener(document, "transitionrun", (event) => {
    if (geometry.test(event.propertyName)) schedule(300)
  })
  createEventListener(document, ["transitionend", "transitioncancel"], (event) => {
    if (geometry.test(event.propertyName)) schedule()
  })
  // Floating content portals directly into <body>; keep measuring briefly so
  // the positioner has settled before the overlap check runs.
  const portals = new MutationObserver(() => schedule(300))
  portals.observe(document.body, { childList: true })
  onCleanup(() => portals.disconnect())
  const appearance = new MutationObserver(() => schedule(300))
  appearance.observe(document.documentElement, { attributes: true, attributeFilter: ["style", "data-theme"] })
  onCleanup(() => appearance.disconnect())
  createEventListener(window.matchMedia("(prefers-color-scheme: dark)"), "change", () => schedule(300))
  createEventListener(document, "visibilitychange", () => setStore("visible", document.visibilityState === "visible"))
  onCleanup(() => {
    if (frame !== undefined) cancelAnimationFrame(frame)
    clearTimeout(release)
    capturing = undefined
    replaceSnapshot()
    hide()
  })

  return (
    <div ref={element} class={props.class}>
      <Show when={store.snapshot?.id === props.id && props.visible && store.snapshot?.url}>
        {(url) => (
          <img
            src={url()}
            alt=""
            elementtiming="embed-snapshot"
            draggable={false}
            class="absolute inset-0 size-full pointer-events-none select-none"
          />
        )}
      </Show>
      {props.children}
    </div>
  )
}

// The hairline ring (a zero-offset, zero-blur, spread-only shadow) of the nearest card around the box.
// The corner masks sit where it curves, so they redraw it.
function cardRing(element: HTMLElement) {
  for (let node = element.parentElement; node; node = node.parentElement) {
    const shadow = getComputedStyle(node).boxShadow

    if (shadow === "none") continue

    return shadow
      .split(/,(?![^(]*\))/)
      .map((layer) => layer.trim().match(/^(.+?)\s+(-?[\d.]+)px\s+(-?[\d.]+)px\s+([\d.]+)px\s+([\d.]+)px$/))
      .flatMap((match) =>
        match && +match[2] === 0 && +match[3] === 0 && +match[4] === 0 && +match[5] > 0
          ? [{ color: match[1], width: +match[5] }]
          : [],
      )
      .at(0)
  }
}

import { makeEventListener } from "@solid-primitives/event-listener"
import type { Definition } from "@opencode/gui-extensions/sdk"
import { BUILTINS_UPDATED } from "./builtins"
import { useExtensionHost } from "./host"

/** Development only: reloads the built-in extensions whose renderer code or English copy changed. */
export default function ExtensionHotReload() {
  const host = useExtensionHost()
  makeEventListener(window, BUILTINS_UPDATED, (event) => {
    if (!(event instanceof CustomEvent)) return
    const next: readonly Definition[] = event.detail
    next.forEach((definition) => {
      const current = host.definitions().find((item) => item.id === definition.id)

      if (!current || host.state.status[definition.id] === "disabled") return
      void changed(current, definition).then((value) => {
        if (value) host.reload(definition.id, definition)
      })
    })
  })

  return null
}

// Unchanged modules keep their URL, so importing them again returns the same module.
async function changed(current: Definition, next: Definition) {
  if (current.i18n?.en !== next.i18n?.en) return true

  if (!current.renderer || !next.renderer) return current.renderer !== next.renderer
  const [before, after] = await Promise.all([current.renderer().catch(() => undefined), next.renderer()])

  return before?.default !== after.default
}

import {
  batch,
  createComputed,
  createEffect,
  createMemo,
  createSignal,
  getOwner,
  on,
  runWithOwner,
  untrack,
  type Accessor,
} from "solid-js"
import { createStore, produce, type Store } from "solid-js/store"
import type { Schema } from "effect"
import { useDialog } from "@opencode/ui/context/dialog"
import { base64Encode } from "@opencode/util/encode"
import {
  Panel,
  type Build,
  type Layout,
  type MountedSession,
  type OpenOptions,
  type PanelSidebar,
  type PanelState,
  type ServerRef,
  type SessionRef,
  type SessionScreen,
  type Storage,
  type StorageScope,
  type StoreFrom,
  type StoreOptions,
} from "@opencode/gui-extensions/sdk"
import { usePlatform } from "@/runtime/platform/platform"
import { same } from "@/runtime/persistence/equality"
import { Persist, persisted, removePersisted } from "@/runtime/persistence/storage"
import { useGlobal, type ServerCtx } from "@/runtime/server/runtime"
import { ServerConnection, serverName, useServers } from "@/runtime/server/registry"
import { useDirectoryPicker } from "@/workspaces/selection/picker"
import { SessionRouteKey, SessionStateKey, type ServerScope } from "@/runtime/server/scope"
import { findSessionTab, tabKey, useTabs } from "@/shell/tabs/tabs"
import { useCurrentRoute, useLayout } from "@/shell/state/layout"
import { terminalFontFamily, useSettings } from "@/settings/model"
import { useSettingsSurface } from "@/settings/surface"
import { formatKeybindParts, useCommand } from "@/shell/commands/command"
import { createMediaQuery } from "@solid-primitives/media"
import { useIsRouting, useLocation } from "@solidjs/router"
import { useLanguage } from "@/runtime/i18n/language"
import { createEmbeds } from "./embeds"
import { useExtensionHost, type HostApiFactories } from "./host"
import { createLocatedWrites } from "./located"
import type { Region } from "./panels"
import { deferredHandle, globalStoreTarget, persistedHandle, storeImports, storeName } from "./stores"

type Attached = {
  sessions: Accessor<readonly SessionRef[]>
  current: Accessor<MountedSession | undefined>
  screen: Accessor<SessionScreen | undefined>
  scope: (server: string) => ServerScope
  /** Records a session-scoped store so layout pruning drops it with the session. */
  scoped: (name: string) => void
  layout: Omit<Layout, "narrow" | "settings" | "project" | "stored"> & {
    stored(extension: string, session: SessionRef): readonly string[]
  }
  settings: (page?: string) => void
  project: (server: string, title: string) => void
  font: Accessor<string>
  routing: Accessor<boolean>
  path: Accessor<string>
  keybind: (command: string) => readonly string[]
  matches: (command: string, event: KeyboardEvent) => boolean
  servers: Accessor<readonly string[]>
  server: (id: string) => ServerRef | undefined
}

/**
 * HostApis the host owns. Session and layout attach once the app interface mounts; until then their reads return
 * their documented defaults and their writes wait, then apply in call order.
 */
export function createHostApis() {
  const platform = usePlatform()
  const dialog = useDialog()
  const language = useLanguage()
  // The session screen's breakpoint, negated, so no fractional width is both narrow and desktop.
  const desktop = createMediaQuery("(min-width: 768px)")
  const narrow = () => !desktop()
  const [attached, setAttached] = createSignal<Attached>()
  const removed = new Set<(value: { server: string; directory: string }) => void>()
  const memory = new Map<string, ReturnType<Storage["memory"]>>()
  const current = () => attached()
  // Writes made while the app interface is not mounted, in call order.
  const early: ((value: Attached) => void)[] = []
  // Removals of a session's store wait for its location, as layout writes do.
  const located = createLocatedWrites()

  // Runs a write now when the interface is mounted and nothing waits before it; otherwise once it mounts.
  const write = (run: (value: Attached) => void) => {
    const value = untrack(attached)

    if (value && early.length === 0) return run(value)
    early.push(run)
  }

  // Promise.try runs each write synchronously and isolates a throw, such as an unlisted server, from the later ones.
  const flush = () => {
    const value = untrack(attached)

    if (!value) return
    batch(() =>
      early
        .splice(0)
        .forEach(
          (run) => void Promise.try(() => run(value)).catch((cause: unknown) => console.error("[extension]", cause)),
        ),
    )
  }

  const embeds = createEmbeds({
    bridge: platform.extensions,
    zoom: () => platform.webviewZoom?.() ?? 1,
    dialog: () => !!dialog.active,
  })

  // A server or session store's key needs the server's scope, which the mounted interface provides.
  const target = (
    extension: string,
    key: string,
    scope: Exclude<StorageScope, "global">,
    from: StoreFrom | readonly StoreFrom[] | undefined,
    connected: Attached,
  ) => {
    const name = storeName(extension, key)

    if ("session" in scope) {
      const location = scope.session.location

      if (!location) throw new Error("Session storage requires a session location")
      connected.scoped(name)
      const server = connected.scope(scope.session.server.id)
      const directory = base64Encode(location.directory)
      const session = SessionStateKey.from(server, SessionRouteKey.fromRoute(directory, scope.session.id))

      return {
        ...Persist.serverSession(server, directory, scope.session.id, name),
        copyFrom: storeImports(from, session),
      }
    }

    const copyFrom = storeImports(from)

    if (!scope.directory) return { ...Persist.serverGlobal(connected.scope(scope.server), name), copyFrom }

    return { ...Persist.serverWorkspace(connected.scope(scope.server), base64Encode(scope.directory), name), copyFrom }
  }

  const apis: HostApiFactories = {
    storage: (extension, owner) => ({
      store<S extends Schema.ConstraintCodec<object, unknown>>(key: string, options: StoreOptions<S>) {
        const open = (at: Parameters<typeof persisted>[0]) => {
          const pair = persisted(at, options.schema, options.initial, platform)

          return persistedHandle({ store: pair[0], set: pair[1], init: pair[3].promise })
        }

        const scope = options.scope

        // Persistence owns effects and resources; code after an await in setup has no owner.
        return runWithOwner(getOwner() ?? owner, () => {
          if (!scope || scope === "global") return open(globalStoreTarget(extension, key, options.from))

          const scoped = (connected: Attached | undefined) =>
            connected && open(target(extension, key, scope, options.from, connected))

          // A server store opens once the interface mounts. A session store also waits for the session's location, and
          // opens again in a new directory; the store a run opened disposes with the next run.
          if (!("session" in scope)) return deferredHandle(createMemo(on(attached, scoped)))

          const directory = createMemo(() => scope.session.location?.directory)

          return deferredHandle(
            createMemo(
              on([attached, directory], ([connected, value]) => (value === undefined ? undefined : scoped(connected))),
            ),
          )
        })!
      },
      memory<T extends object>(key: string, options: { readonly initial: T }) {
        const name = `${extension}.${key}`
        const existing = memory.get(name)

        if (existing) {
          // SAFETY: a memory key is one extension's store, which that extension always opens with the same shape.
          return existing as readonly [Store<T>, (mutation: (draft: T) => void) => void]
        }

        const [store, setStore] = createStore(options.initial)
        const value = [store, (mutation: (draft: T) => void) => setStore(produce(mutation))] as const

        memory.set(name, value)

        return value
      },
      remove(key, options) {
        const scope = options?.scope

        if (!scope || scope === "global")
          return removePersisted(globalStoreTarget(extension, key, options?.from), platform)

        const run = (connected: Attached) =>
          removePersisted(target(extension, key, scope, options?.from, connected), platform)

        // A session's store is found through its location: the removal waits for it, as layout writes do.
        write((connected) =>
          "session" in scope && !scope.session.location
            ? located.hold(scope.session, () => write(run))
            : run(connected),
        )
      },
    }),
    system: () => ({
      copy: (text) => platform.writeClipboardText?.(text) ?? navigator.clipboard.writeText(text),
      async save(file) {
        if (platform.saveFile) return platform.saveFile({ defaultPath: file.name }, file.content)
        const url = URL.createObjectURL(new Blob([file.content], { type: "application/octet-stream" }))
        const link = document.createElement("a")
        link.href = url
        link.download = file.name
        link.click()
        URL.revokeObjectURL(url)

        return true
      },
      openExternal(url) {
        if (platform.openLocalFile && URL.canParse(url) && new URL(url).protocol === "file:")
          return platform.openLocalFile(url)
        platform.openExternal(url)
      },
    }),
    desktop: () =>
      platform.platform === "desktop"
        ? {
            os: platform.os ?? "linux",
            window: platform.windowID,
            zoom: () => platform.webviewZoom?.() ?? 1,
            launch: (path, app) => platform.openPath?.(path, app) ?? Promise.resolve(),
            reveal: (path) => platform.revealPath?.(path) ?? Promise.resolve(false),
            installed: (app) => platform.checkAppExists?.(app) ?? Promise.resolve(false),
            forceFocus: (enabled) => platform.setForceFocus?.(enabled) ?? Promise.resolve(),
          }
        : undefined,
    build: () => ({
      version: platform.version ?? "",
      // SAFETY: the build sets VITE_OPENCODE_CHANNEL to one of the release channels, or leaves it unset locally.
      channel: (import.meta.env.VITE_OPENCODE_CHANNEL ?? "local") as Build["channel"],
      platform: platform.platform,
      packaged: platform.extensions?.packaged ?? false,
    }),
    locale: () => ({
      locale: language.intl,
      direction: language.direction,
      setDirection: language.setDirection,
    }),
    // Before the interface mounts, the default mono font.
    appearance: () => ({ font: () => current()?.font() ?? terminalFontFamily(undefined) }),
    router: () => ({
      routing: () => current()?.routing() ?? false,
      path: () => current()?.path() ?? "",
    }),
    keybinds: () => ({
      keybind: (command) => current()?.keybind(command) ?? [],
      keys: (bind) => formatKeybindParts(bind, language.t),
      matches: (command, event) => current()?.matches(command, event) ?? false,
    }),
    servers: () => ({
      list: () => current()?.servers() ?? [],
      get: (id) => current()?.server(id),
    }),
    workspaces: (_extension, _owner, _context, register) => ({
      on(_event, handler) {
        removed.add(handler)

        return register(() => {
          removed.delete(handler)
        })
      },
    }),
    sessions: () => ({
      list: () => current()?.sessions() ?? [],
      current: () => current()?.current(),
    }),
    screen: () => ({
      current: () => {
        const attached = current()

        return attached?.current() ? attached.screen() : undefined
      },
    }),
    // Before the interface mounts, reads return what an empty layout holds and writes wait for it.
    layout: (extension) => ({
      narrow,
      ready: () => current()?.layout.ready() ?? false,
      open: (key, session, options) => write((value) => value.layout.open(key, session, options)),
      close: (key, session) => write((value) => value.layout.close(key, session)),
      toggle: (key, session) => write((value) => value.layout.toggle(key, session)),
      state: (key, session) => current()?.layout.state(key, session) ?? "closed",
      stored: (session) => current()?.layout.stored(extension, session) ?? [],
      side: {
        opened: (session) => current()?.layout.side.opened(session) ?? false,
        toggle: (session) => write((value) => value.layout.side.toggle(session)),
      },
      sidebar: { opened: () => current()?.layout.sidebar.opened() ?? true },
      dock: {
        opened: (session) => current()?.layout.dock.opened(session) ?? false,
        placement: () => current()?.layout.dock.placement() ?? "side",
      },
      scroll: {
        get: (session, key) => current()?.layout.scroll.get(session, key),
        set: (session, key, value) => write((connected) => connected.layout.scroll.set(session, key, value)),
      },
      settings: (page) => write((value) => value.settings(page)),
      project: (server, title) => write((value) => value.project(server, title)),
    }),
    embeds: () => embeds,
  }

  return {
    apis,
    /**
     * Runs `run` now while the app interface is mounted and no write waits; otherwise after the interface's first
     * render, behind the writes made before it. The returned function cancels a run that still waits.
     */
    whenMounted(run: () => void) {
      const state = { cancelled: false }

      write(() => {
        if (!state.cancelled) run()
      })

      return () => {
        state.cancelled = true
      }
    },
    attach(value: Attached) {
      setAttached(() => value)
      // After the interface's first render, so the waiting writes find its layout, in call order.
      queueMicrotask(flush)

      return () => {
        if (attached() === value) setAttached(undefined)
      }
    },
    workspaceRemoved(value: { server: string; directory: string }) {
      removed.forEach((handler) => handler(value))
    },
  }
}

export type HostApis = ReturnType<typeof createHostApis>

export { ExtensionAttachmentProvider, useExtensionAttachment } from "./attachment"

/** Builds the session and layout attachment before readiness; its `attach` connects HostApis as the routes render. */
export function createExtensionAttachment(apis: HostApis) {
  const global = useGlobal()
  const tabs = useTabs()
  const layout = useLayout()
  const route = useCurrentRoute()
  const settings = useSettings()
  const surface = useSettingsSurface()
  const host = useExtensionHost()
  const command = useCommand()
  const location = useLocation()
  const desktop = createMediaQuery("(min-width: 768px)")
  const narrow = () => !desktop()
  // The mounted session screen, from its first render, and its object for the session it routes once it has mounted;
  // one screen is mounted at a time.
  const [screen, setScreen] = createSignal<SessionScreen>()
  const [routedView, setRoutedView] = createSignal<Accessor<MountedSession>>()
  const refs = new Map<string, SessionRef>()

  const connection = (id: string) => global.servers.list().find((item) => ServerConnection.key(item) === id)
  const servers = useServers()

  // One ref per server id. A restarted server (e.g. an updated WSL server) gets a new controller under the same id,
  // so the ref follows the live controller instead of the one it was created with.
  const owner = getOwner()
  const serverRefs = new Map<string, ServerRef>()

  const server = (id: string): ServerRef | undefined => {
    const conn = connection(id)

    if (!conn) return
    const existing = serverRefs.get(id)

    if (existing) return existing
    const key = ServerConnection.Key.make(id)
    // The controller starts on first use, not when the ref is made: reading `builtin` to find a server must not
    // connect to every listed server, such as one the runtime holds back because it rejects its credentials.
    let started: Accessor<ServerCtx> | undefined

    const live = () => {
      started ??= runWithOwner(owner, () =>
        createMemo<ServerCtx>(
          (previous) => global.serverCtx(key) ?? previous,
          global.ensureServerCtx(connection(id) ?? conn),
        ),
      )!

      return started()
    }

    // What the app's server list already says, without a controller.
    const listed = () => connection(id) ?? live().sdk.server

    const ref: ServerRef = {
      id,
      get name() {
        return serverName(listed()) || id
      },
      get url() {
        return live().sdk.url
      },
      get password() {
        return live().sdk.server.http.password
      },
      get client() {
        return live().sdk.api
      },
      get data() {
        return live().data
      },
      get local() {
        return ServerConnection.local(listed())
      },
      get builtin() {
        return ServerConnection.builtin(listed())
      },
      get compatible() {
        return !global.servers.health[key]?.incompatible
      },
      get connected() {
        return live().sdk.connection.status() === "connected"
      },
    }

    serverRefs.set(id, ref)

    return ref
  }

  const sessions = createMemo(() => {
    const owned = new Set(tabs.store.filter((tab) => tab.type === "session").map(tabKey))
    Array.from(refs).forEach(([key, ref]) => {
      if (!owned.has(ref.tab)) refs.delete(key)
    })
    tabs.store.forEach((tab) => {
      if (tab.type !== "session") return
      const target = server(tab.server)

      if (!target) return
      Array.from(new Set([tab.sessionId, tab.routeSessionId ?? tab.sessionId])).forEach((id) => {
        const key = `${tab.server}\n${id}`

        if (refs.has(key)) return
        refs.set(key, {
          key,
          id,
          tab: tabKey(tab),
          server: target,
          get pending() {
            return target.data.session.creating(id)
          },
          get location() {
            return target.data.session.get(id)?.location
          },
        })
      })
    })

    return Array.from(refs.values())
  })

  const routed = createMemo(() => {
    const value = route()

    return value.type === "session" ? `${value.server}\n${value.sessionId}` : undefined
  })

  const current = createMemo(() => {
    const key = routed()
    const view = routedView()?.()

    return key && view?.key === key ? view : undefined
  })

  const scope = (id: string) => {
    const conn = connection(id)

    if (!conn) throw new Error(`Server ${id} is unavailable`)

    return global.ensureServerCtx(conn).sdk.scope
  }

  // The registry's scope is pure: an unlisted server's sessions (e.g. a stopped WSL server, whose tabs stay open) keep
  // their key, and no server controller starts for it.
  const stateKey = (session: SessionRef) => {
    const location = session.location

    if (!location) return

    return SessionStateKey.from(
      servers.scope(ServerConnection.Key.make(session.server.id)),
      SessionRouteKey.fromRoute(base64Encode(location.directory), session.id),
    )
  }

  // Each session's layout key, kept while its location is unknown (e.g. after the server re-authenticates).
  const stateKeys = createMemo<ReadonlyMap<string, string>>(
    (previous) =>
      new Map(
        sessions().flatMap((session) => {
          const value = stateKey(session) ?? previous.get(session.key)

          return value ? [[session.key, value] as const] : []
        }),
      ),
    new Map(),
  )

  // The strip is stored per directory, so a session that moves copies its strip to its new key: its tabs look the same
  // before and after the move. Synchronous, so no region renders the new key before the copy lands. A layout write
  // before desktop layout storage loads would stop it loading, so `lastKeys` keeps each session's first key until then.
  const lastKeys = new Map<string, string>()
  createComputed(() => {
    const next = stateKeys()
    Array.from(lastKeys.keys()).forEach((key) => {
      if (!next.has(key)) lastKeys.delete(key)
    })
    next.forEach((to, key) => {
      if (!lastKeys.has(key)) lastKeys.set(key, to)
    })

    if (!layout.ready()) return
    next.forEach((to, key) => {
      const from = lastKeys.get(key)

      if (!from || from === to) return
      layout.panel.copy(from, to)
      lastKeys.set(key, to)
    })
  })

  const shellTab = (session: SessionRef) =>
    findSessionTab(tabs.store, ServerConnection.Key.make(session.server.id), session.id)

  const sideOpened = (session: SessionRef) => !!tabs.region(shellTab(session), "side")
  const dockOpened = (session: SessionRef) => !!tabs.region(shellTab(session), "dock")
  const setDock = (session: SessionRef, opened: boolean) => tabs.setRegion(shellTab(session), "dock", opened)

  // A token per session whose side region is open, new each time the region opens.
  const sideVisits = createMemo<ReadonlyMap<string, object>>(
    (previous) =>
      new Map(
        sessions().flatMap((session) =>
          sideOpened(session) ? [[session.key, previous.get(session.key) ?? {}] as const] : [],
        ),
      ),
    new Map(),
  )

  // The panel whose toggle opened a side region, by the region's token. However the region closes, it reopens with
  // a new token, so a region reopened any other way belongs to the user.
  const openedFor = new WeakMap<object, string>()

  // Keys are `${extension}:${tab id}`; the extension's panel decides the region.
  const provider = (key: string) => {
    const extension = key.slice(0, key.indexOf(":"))
    const matches = host.items(Panel).filter((item) => item.extension === extension)

    return matches.find((item) => item.value.region === "side") ?? matches[0]
  }

  const mountedSession = (session: SessionRef) => {
    const view = current()

    return view?.key === session.key ? view : undefined
  }

  // Counts routing visits: each change of the routed session, including to none (e.g. Home), starts the next one.
  const visit = createMemo(on(routed, (_key, _previous, count: number = 0) => count + 1))

  // The narrow-screen view belongs to the routed, mounted session for one visit, and reads as the conversation once
  // another visit starts. A view selected for a session that is not routed (e.g. a file link that opens Files on
  // another session) belongs to the next visit, which the navigation that follows starts. The dock's view follows
  // the dock's own per-session state instead.
  const [mobile, setMobile] = createStore<{ session: string | undefined; view: string; visit: number }>({
    session: undefined,
    view: "session",
    visit: 0,
  })

  const mobileView = createMemo(() =>
    mobile.session === current()?.key && mobile.visit === visit() ? mobile.view : "session",
  )

  const selectMobile = (session: SessionRef, view: string) =>
    setMobile({ session: session.key, view, visit: session.key === routed() ? visit() : visit() + 1 })

  // The side tabs a mounted session lists right now, plus `adding` as if it were stored; unmounted sessions have none.
  const listed = (session: SessionRef, value: string, adding?: string) => {
    const view = mountedSession(session)
    const currentScreen = screen()

    if (!view || !currentScreen) return []
    const all = layout.panel.state(value).all
    const stored = adding && !all.includes(adding) ? [...all, adding] : all

    return untrack(() =>
      host
        .items(Panel)
        .filter((item) => item.value.region === "side")
        .flatMap((item) => {
          const prefix = `${item.extension}:`
          const open = stored.flatMap((key) => (key.startsWith(prefix) ? [key.slice(prefix.length)] : []))

          return item.value
            .list({
              get session() {
                return mountedSession(session) ?? view
              },
              screen: currentScreen,
              open,
            })
            .map((tab) => ({ key: `${prefix}${tab.id}`, tab }))
        }),
    )
  }

  // Writes made before a session's location is known wait for it rather than being dropped.
  const located = createLocatedWrites()

  const open = (key: string, session: SessionRef, options?: OpenOptions) => {
    const item = provider(key)

    if (item?.value.region === "dock") return setDock(session, true)
    const value = stateKey(session)

    if (!value) return located.hold(session, () => open(key, session, options))
    const placement = options?.tab ?? "open"

    // An append adds the tab quietly: no selection, no region change, no preview replacement.
    if (placement === "append") return layout.panel.append(value, key)

    // A select keeps the narrow-screen view and dock, as a background open does, and opens the side region too.
    if (placement === "select")
      return batch(() => {
        tabs.setRegion(shellTab(session), "side", true)
        layout.panel.append(value, key)
        layout.panel.focus(value, key)
      })
    // Lists the opened tab too, so its own fields apply before it is stored. The next preview replaces a transient tab.
    const known = listed(session, value, key)
    const transient = new Set(known.flatMap((entry) => (entry.tab.transient ? [entry.key] : [])))
    const first = known.some((entry) => entry.key === key && entry.tab.first)
    batch(() => {
      if (narrow() && !options?.background) {
        setDock(session, false)

        if (item?.value.mobile) selectMobile(session, `${item.extension}:${item.value.id}`)

        // A tab its panel does not list, or a transient one, stays unstored: the open only selects the panel's view.
        if (mountedSession(session) && !known.some((entry) => entry.key === key && !entry.tab.transient)) return
      }

      // A background open keeps the narrow-screen view, but its tab still shows once the window is wide.
      if (!narrow() || options?.background) tabs.setRegion(shellTab(session), "side", true)

      // Pinned tabs are listed without being stored; opening one only selects it.
      if (known.some((entry) => entry.key === key && entry.tab.pinned)) return layout.panel.focus(value, key)

      if (placement === "preview") return layout.panel.preview(value, key, transient)
      layout.panel.open(value, key, transient, first)
    })
  }

  const close = (key: string, session: SessionRef) => {
    const item = provider(key)

    if (item?.value.region === "dock") return setDock(session, false)
    const value = stateKey(session)

    if (!value) return located.hold(session, () => close(key, session))
    const tab = listed(session, value).find((entry) => entry.key === key)?.tab
    layout.panel.close(value, key)
    const view = mountedSession(session)
    const currentScreen = screen()

    if (view && tab && currentScreen) item?.value.close?.({ tab, session: view, screen: currentScreen })
  }

  // The routed session's side region, which knows the fallback selection the stored state lacks.
  const [region, setRegion] = createSignal<Region>()
  // The session screen's inner sidebar preference, which its side panels share.
  const [sidebar, setSidebar] = createSignal<PanelSidebar>()

  const opened = createMemo(
    () => Array.from(new Set((region()?.entries() ?? []).flatMap((entry) => entry.tab.file ?? []))),
    [],
    { equals: same },
  )

  const state = (key: string, session: SessionRef): PanelState => {
    if (provider(key)?.value.region === "dock") return dockOpened(session) ? "visible" : "closed"
    const value = stateKey(session)

    if (!value) return "closed"
    const panel = layout.panel.state(value)
    const active = mountedSession(session) ? (region()?.active() ?? panel.active) : panel.active

    if (active !== key) return panel.all.includes(key) ? "open" : "closed"

    return sideOpened(session) ? "visible" : "active"
  }

  // Open-project requests wait until their server is listed (e.g. an SSH server that just connected).
  const picker = useDirectoryPicker()
  const [projects, setProjects] = createSignal<readonly { server: string; title: string }[]>([])
  createEffect(() => {
    const pending = projects()

    const ready = pending.flatMap((request) => {
      const server = servers.list.find((conn) => ServerConnection.key(conn) === request.server)

      return server ? [{ request, server }] : []
    })

    if (ready.length === 0) return
    setProjects(pending.filter((request) => !ready.some((item) => item.request === request)))
    untrack(() =>
      ready.forEach(({ request, server }) =>
        picker({
          server,
          title: request.title,
          onSelect: (value) => {
            const directory = Array.isArray(value) ? value[0] : value

            if (!directory) return
            const key = ServerConnection.key(server)
            servers.projects.forServer(key).open(directory)
            void tabs.newDraft({ server: key, directory })
          },
        }),
      ),
    )
  })

  const toggle = (key: string, session: SessionRef) => {
    if (provider(key)?.value.region === "dock") return setDock(session, !dockOpened(session))
    const value = stateKey(session)

    if (!value) return located.hold(session, () => toggle(key, session))
    const region = sideVisits().get(session.key)

    if (state(key, session) === "visible") {
      batch(() => {
        close(key, session)

        // Closing the last panel the region was opened for also closes the region.
        if (region && openedFor.get(region) === key && layout.panel.state(value).all.length === 0)
          tabs.setRegion(shellTab(session), "side", false)
      })

      return
    }

    // A panel opened into an open region makes the region the user's.
    if (region) openedFor.delete(region)
    open(key, session)
    const opened = sideVisits().get(session.key)

    if (!region && opened) openedFor.set(opened, key)
  }

  const setScroll = (session: SessionRef, key: string, next: { readonly x: number; readonly y: number }) => {
    const value = stateKey(session)

    if (!value) return located.hold(session, () => setScroll(session, key, next))
    layout.panel.setScroll(value, key, next)
  }

  const mounted: Attached = {
    sessions,
    current,
    screen,
    scope,
    scoped: layout.sessionState.track,
    project: (server, title) => setProjects((pending) => [...pending, { server, title }]),
    font: () => terminalFontFamily(settings.appearance.terminalFont()),
    routing: useIsRouting(),
    path: () => `${location.pathname}${location.search}`,
    keybind: command.keybindParts,
    matches: command.matches,
    servers: () => global.servers.list().map(ServerConnection.key),
    server,
    // SAFETY: an extension names a page it contributed through `SettingsPage`, which settings lists as an extension tab.
    settings: (page) => surface.open(page as Parameters<typeof surface.open>[0]),
    layout: {
      ready: layout.ready,
      open,
      close,
      toggle,
      state,
      stored(extension, session) {
        const value = stateKey(session)

        if (!value) return []
        const prefix = `${extension}:`

        return layout.panel
          .state(value)
          .all.flatMap((key) => (key.startsWith(prefix) ? [key.slice(prefix.length)] : []))
      },
      side: {
        opened: sideOpened,
        toggle: (session) => tabs.setRegion(shellTab(session), "side", !sideOpened(session)),
      },
      // Open is the stored preference's default, which holds until a session screen shows the preference.
      sidebar: { opened: () => sidebar()?.opened() ?? true },
      dock: {
        opened: dockOpened,
        placement: settings.general.terminalPlacement,
      },
      scroll: {
        get(session, key) {
          const value = stateKey(session)

          return value ? layout.panel.scroll(value, key) : undefined
        },
        set: setScroll,
      },
    },
  }

  return {
    /**
     * Mounts the interface for the HostApis; returns its detach. Called as the routes first render, which waits for
     * every extension to settle, so writes and dialogs made before then apply after that render.
     */
    attach: () => apis.attach(mounted),
    /** The routed `MountedSession`. */
    current,
    region(value: Region) {
      setRegion(() => value)

      return () => {
        if (region() === value) setRegion(undefined)
      }
    },
    /** The session screen's inner sidebar preference, which `Layout.sidebar` reads. */
    sidebar(value: PanelSidebar) {
      setSidebar(() => value)

      return () => {
        if (sidebar() === value) setSidebar(undefined)
      }
    },
    /** Workspace files the routed session's side tabs show, in strip order, and the selected one. */
    files: {
      opened,
      active: () => region()?.selected()?.tab.file,
    },
    mobile: {
      current: mobileView,
      select(view: string) {
        const session = current()

        if (session) selectMobile(session, view)
      },
    },
    /** A screen started rendering: `Screen.current` returns it only while its session matches the route. */
    screen(value: SessionScreen) {
      setScreen(() => value)

      return () => {
        if (screen() === value) setScreen(undefined)
      }
    },
    /** A session screen mounted: `Sessions.current` reads its object for the routed session. */
    mount(view: Accessor<MountedSession>) {
      setRoutedView(() => view)

      return () => {
        if (routedView() === view) setRoutedView(undefined)
      }
    },
    /** Starts loading every extension's declared session stores for a session the screen routes. */
    preload(view: MountedSession) {
      untrack(() => host.preload(view))
    },
  }
}

import {
  batch,
  catchError,
  createContext,
  createMemo,
  createRenderEffect,
  createResource,
  createRoot,
  createSignal,
  ErrorBoundary,
  getOwner,
  on,
  onCleanup,
  onMount,
  runWithOwner,
  untrack,
  useContext,
  type Accessor,
  type Owner,
  type ParentProps,
} from "solid-js"
import { createStore } from "solid-js/store"
import { Predicate } from "effect"
import { resolveTemplate } from "@solid-primitives/i18n"
import { useDialog } from "@opencode/ui/context/dialog"
import { pluralCategory } from "@opencode/ui/context/i18n"
import {
  ExtensionContext,
  LifetimeContext,
  LinkHandler,
  Live,
  type BaseContext,
  type Catalog,
  type Cleanup,
  type Context,
  type Contract,
  type Definition,
  type Dialogs,
  type Link,
  type Links,
  type Messages,
  type Persisted,
  type Registry,
  type Ipc,
  type IpcClient,
  type IpcRef,
  type IpcSpec,
  type SessionRef,
  type SetupContext,
  type Token,
} from "@opencode/gui-extensions/sdk"
import { useLanguage } from "@/runtime/i18n/language"
import { createSessionStore, whenLoaded } from "./stores"

type Entry = { key: string; registry: string; extension: string; value: Accessor<unknown> }

export type Item<T> = { readonly key: string; readonly extension: string; readonly value: T }

/** The context the host builds: every `Setup<D>` of the definition receives it, and contributions read it as `Context`. */
type InstanceContext = SetupContext<Definition> & Context

type Instance = {
  definition: Definition
  context: InstanceContext
  dispose: () => void
  /** Opens the declared stores. Settles once the global stores have loaded. */
  prepare(): Promise<readonly void[]>
  /** Starts loading the declared session stores for a mounted session. */
  preload(session: SessionRef): void
}

/** The APIs a window context exposes as properties. */
type HostApis = Omit<Context, keyof BaseContext | "signal" | "provide">

/**
 * Creates one HostApi for an extension instance, on the instance's first read of it. `register` withdraws what it is
 * given with the caller's owner, else with the extension.
 */
type HostApiFactory<T> = (
  extension: string,
  owner: Owner | null,
  context: Context,
  register: (fn: Cleanup) => Cleanup,
) => T

/** The HostApis a window provides, by context property. The host itself provides `links` and `dialogs`. */
export type HostApiFactories = {
  readonly [K in Exclude<keyof HostApis, "links" | "dialogs">]: HostApiFactory<HostApis[K]>
}

export type ExtensionStatus = "loading" | "active" | "failed" | "disabled" | "blocked"

/** The last error an extension raised: in its setup or an effect, or while one of its contributions rendered. */
export type ExtensionFailure = { readonly phase: "setup" | "render"; readonly error: string }

type Absent = Exclude<Live<never>, { readonly status: "active" }>

/** A provider as the gate and `requires` see it: its generation while active, else why it is absent. */
type Provider = Absent | { readonly status: "active"; readonly generation: number }

type HostState = {
  entries: Record<string, Entry[] | undefined>
  contracts: Record<string, number | undefined>
  status: Record<string, ExtensionStatus | undefined>
  failures: Record<string, ExtensionFailure | undefined>
}

type Stores = Record<string, Persisted<object> | ((session: SessionRef) => Persisted<object>)>

const pending: Absent = { status: "pending" }

const inactive = {
  disabled: { status: "inactive", reason: "disabled" },
  failed: { status: "inactive", reason: "failed" },
  blocked: { status: "inactive", reason: "blocked" },
  restarting: { status: "inactive", reason: "restarting" },
} as const satisfies Record<string, Absent>

const HostContext = createContext<ReturnType<typeof createHost>>()

export function useExtensionHost() {
  const host = useContext(HostContext)

  if (!host) throw new Error("Extension host is unavailable")

  return host
}

type HostInput = {
  definitions: readonly Definition[]
  disabled: Accessor<ReadonlySet<string> | undefined>
  apis: HostApiFactories
  /**
   * Runs `run` once the app interface has mounted, behind the HostApis writes made before it, or now when it has.
   * Returns a cancel for a run that still waits.
   */
  whenMounted: (run: () => void) => () => void
  /** The renderer client of an Ipc while it is available; omitted where there is no main process. */
  ipc?: (token: Ipc) => IpcClient<IpcSpec> | undefined
  /** How many times an Ipc became available. Reactive. */
  generation?: (token: Ipc) => number
  /** An extension's main entry failed. Reactive. */
  failed?: (id: string) => boolean
}

export function ExtensionHostProvider(props: ParentProps<HostInput>) {
  const host = createHost(props)

  return <HostContext.Provider value={host}>{props.children}</HostContext.Provider>
}

function createHost(input: HostInput) {
  const language = useLanguage()
  const owner = getOwner()
  const provided = new Map<string, { live: Live<unknown> & { readonly status: "active" } }>()
  const generations = new Map<string, number>()

  // Entries are indexed by registry and contracts versioned by token, so a change wakes only its own readers.
  const [state, setState] = createStore<HostState>({ entries: {}, contracts: {}, status: {}, failures: {} })

  const instances = new Map<string, Instance>()
  const memos = new Map<string, Accessor<readonly Item<unknown>[]>>()
  const sequence = { value: 0 }
  // An entry that finishes loading after the host is gone must not create a root nothing disposes.
  const lifetime = { disposed: false }
  // The current load of each extension. Deactivating drops it and a reload replaces it, so an older load
  // neither sets up nor reports a failure over its replacement.
  const loads = new Map<string, object>()

  // The extension that provides a token: the one declaring it in `provides`, else the one whose id prefixes it.
  const providers = new Map<string, string | undefined>()

  const providerOf = (id: string) => {
    if (providers.has(id)) return providers.get(id)

    const found =
      input.definitions.find((definition) =>
        Object.values(definition.provides ?? {}).some((token) => token.id === id),
      ) ?? input.definitions.find((definition) => definition.id === id || id.startsWith(`${definition.id}.`))

    providers.set(id, found?.id)

    return found?.id
  }

  // Why a token has no active provider. Main-side providers report through the installed list.
  const absent = (id: string, generation: number, main: boolean): Absent => {
    const extension = providerOf(id)

    if (!extension) return inactive.disabled

    if (main ? input.disabled()?.has(extension) : state.status[extension] === "disabled") return inactive.disabled

    if (main ? input.failed?.(extension) : state.status[extension] === "failed") return inactive.failed

    // A blocked provider cannot offer its own contracts either, so hard-dependency chains settle as unavailable.
    if (!main && state.status[extension] === "blocked") return inactive.blocked

    // A renderer provider that is up but does not provide the token (e.g. on this platform) is not coming.
    if (!main && state.status[extension] === "active") return inactive.disabled

    return generation > 0 ? inactive.restarting : pending
  }

  const contractLive = (token: Contract<unknown>): Live<unknown> => {
    void state.contracts[token.id]

    return provided.get(token.id)?.live ?? absent(token.id, generations.get(token.id) ?? 0, false)
  }

  // Full Ipc tokens by id. A reference (`Ipc.ref`) carries no spec and resolves through the full token once code
  // in this window uses it; until then it is absent, as pending as its provider allows.
  const [known, setKnown] = createSignal<ReadonlyMap<string, Ipc>>(new Map())

  const learn = (token: Token) => {
    if (token.kind !== "ipc" || !token.spec || untrack(known).has(token.id)) return

    setKnown((map) => new Map(map).set(token.id, token))
  }

  const resolve = (token: Ipc | IpcRef) => (token.spec ? token : known().get(token.id))

  // One object per Ipc generation, so reading a provider allocates nothing while it is unchanged.
  const actives = new Map<string, Provider & { readonly status: "active" }>()

  const providerState = (token: Token): Provider => {
    if (token.kind === "contract") return contractLive(token)

    if (!input.ipc) return inactive.disabled

    const full = resolve(token)

    if (!full || !input.ipc(full)) return absent(token.id, full ? (input.generation?.(full) ?? 0) : 0, true)

    const generation = input.generation?.(full) ?? 1
    const cached = actives.get(token.id)

    if (cached?.generation === generation) return cached

    const active = { status: "active", generation } as const

    actives.set(token.id, active)

    return active
  }

  const satisfied = (definition: Definition) =>
    Object.values(definition.requires ?? {}).every((token) => untrack(() => providerState(token)).status === "active")

  // Reuses each item object while its value is unchanged so keyed renders do not remount.
  const createItems = (id: string) => {
    const cache = new Map<string, Item<unknown>>()

    const created = runWithOwner(owner, () =>
      createMemo(() => {
        const next = (state.entries[id] ?? []).flatMap((entry) => {
          const value = entry.value()

          if (value === undefined) return []

          const previous = cache.get(entry.key)

          if (previous?.value === value) return [previous]

          const item = { key: entry.key, extension: entry.extension, value }

          cache.set(entry.key, item)

          return [item]
        })

        if (cache.size > next.length) {
          const live = new Set(next.map((item) => item.key))

          cache.forEach((_, key) => {
            if (!live.has(key)) cache.delete(key)
          })
        }

        return next
      }),
    )

    const memo = created ?? (() => [])

    memos.set(id, memo)

    return memo
  }

  const items = <T,>(registry: Registry<T>) => {
    const memo = memos.get(registry.id) ?? createItems(registry.id)

    // SAFETY: only `add` stores entries, under the id of the typed registry it was given, so this registry's items
    // are T.
    return memo() as readonly Item<T>[]
  }

  const list = <T,>(registry: Registry<T>) => items(registry).map((item) => item.value)

  const pickLinkHandler = (link: Link) =>
    list(LinkHandler)
      .filter((item) => item.match(link))
      .reduce<LinkHandler | undefined>(
        (best, item) => (!best || (item.priority ?? 0) > (best.priority ?? 0) ? item : best),
        undefined,
      )

  const links: Links = {
    open(link) {
      const handler = untrack(() => pickLinkHandler(link))

      if (!handler) return false

      handler.open(link)

      return true
    },
    // Markdown asks from inside its render effect; untracked so a session or screen switch never reruns it.
    exists: (link) => untrack(() => pickLinkHandler(link)?.exists?.(link) ?? false),
  }

  const dialog = useDialog()

  const factories = {
    ...input.apis,
    links: () => links,
    // Bound to the instance that asked, so an older async call after a disable or reload opens and closes nothing.
    dialogs: (extension, _, context, register): Dialogs => ({
      open(render, options) {
        const id = `extension:${extension}:${sequence.value++}`
        const waiting = { cancel: () => {} }
        // This open alone: once it aborts, a deferred open neither mounts nor replaces another dialog.
        const opening = new AbortController()

        // Each handle names its own dialog, so it never closes one another extension or instance opened. Closing a
        // dialog that still waits for the app interface, or for its deferred open, cancels it.
        const close = () => {
          opening.abort()
          waiting.cancel()
          dialog.close(id)
        }

        const handle = { close }

        if (context.signal.aborted) return handle

        // Closes this dialog, not whichever is on top, when the extension or the scope that opened it goes away.
        const release = register(close)

        // A dialog opened before the app interface mounts, as during setup, shows after its first render: never behind
        // the startup screen, and never before a route that focuses itself as it mounts.
        waiting.cancel = input.whenMounted(
          () =>
            void dialog[options?.replace ? "show" : "push"](
              () => {
                // The dialog's root disposes when it closes or another dialog replaces it.
                onCleanup(() => void release())

                return (
                  <ErrorBoundary
                    fallback={(error) => {
                      onMount(() => {
                        dialog.close(id)
                        fail(extension, error, "render")
                      })

                      return null
                    }}
                  >
                    <ExtensionContext.Provider value={context}>
                      {untrack(() => render(handle))}
                    </ExtensionContext.Provider>
                  </ErrorBoundary>
                )
              },
              undefined,
              id,
              // The stack mounts in a later transition. Its handle, its owner or the extension ending before then keeps
              // it closed.
              AbortSignal.any([opening.signal, context.signal]),
            ),
        )

        return handle
      },
      active: () => !!dialog.active,
    }),
  } satisfies { readonly [K in keyof HostApis]: HostApiFactory<HostApis[K]> }

  const activate = async (definition: Definition) => {
    const load = definition.renderer

    // A disabled extension, e.g. one reloaded from settings, stays disabled: marking it loading would make the
    // enable watcher skip it later. Before the list loads nothing activates; the watcher starts each entry then.
    if (!load || input.disabled()?.has(definition.id) !== false) return

    const unavailable = Object.values(definition.requires ?? {}).some((token) => {
      const provider = untrack(() => providerState(token))

      return blocked(provider)
    })

    setState("status", definition.id, unavailable ? "blocked" : "loading")

    // Waits for its hard contracts; the requirement watcher starts it once they are active.
    if (!satisfied(definition)) return

    const attempt = {}
    const current = () => loads.get(definition.id) === attempt

    loads.set(definition.id, attempt)

    // The current language's catalog loads with the entry, so the first render is already translated.
    const [module, messages] = await Promise.all([
      load().catch((cause: unknown) => {
        if (current()) fail(definition.id, cause)

        return undefined
      }),
      loadMessages(definition.i18n, untrack(language.locale)),
    ])

    if (!current()) return

    loads.delete(definition.id)

    if (!module || lifetime.disposed) return

    // Disabling mid-load deactivates, which drops this load before it gets here.
    if (instances.has(definition.id)) return

    runWithOwner(owner, () =>
      createRoot((dispose) => {
        const root = getOwner()
        const instance = createInstance(definition, dispose, root, messages)

        instances.set(definition.id, instance)

        // Setup and every scope under it read the extension's context, e.g. `createKeyed` with a token.
        if (root) root.context = { ...root.context, [ExtensionContext.id]: instance.context }

        const crash = (cause: unknown) => {
          if (instances.get(definition.id) !== instance) return

          batch(() => {
            deactivate(definition.id)
            fail(definition.id, cause)
          })
        }

        // SAFETY: the host context implements the parameter of every `Setup<D>` of this definition.
        const setup = module.default as (ctx: InstanceContext) => void

        const start = () =>
          void Promise.try(() =>
            // Errors from the extension's own effects, at setup or later, fail the extension and nothing else.
            catchError(
              () =>
                untrack(() => {
                  const returned = setup(instance.context)

                  if (!Predicate.isPromiseLike(returned)) return

                  // Do not await invalid setup, but consume its eventual rejection after the instance is aborted.
                  void Promise.resolve(returned).catch((cause: unknown) =>
                    console.error(`[extension] ${definition.id}`, cause),
                  )
                  throw new Error(
                    "Window setup must be synchronous. Start async work with createKeyed or createLatest.",
                  )
                }),
              (cause) => queueMicrotask(() => crash(cause)),
            ),
          ).then(() => {
            if (instances.get(definition.id) !== instance) return

            setState("status", definition.id, "active")
          }, crash)

        // Setup runs synchronously inside the extension root so its effects and memos are owned.
        if (windowStores(definition).length === 0) return start()

        // Global stores load in their storage namespace's one read before setup, so setup reads them as plain values.
        Promise.try(instance.prepare).then(() => {
          if (instances.get(definition.id) === instance) runWithOwner(root, start)
        }, crash)
      }),
    )
  }

  const createInstance = (
    definition: Definition,
    dispose: () => void,
    root: Owner | null,
    initial: Messages,
  ): Instance => {
    const extension = definition.id
    const controller = new AbortController()
    const cleanups = new Set<Cleanup>()

    const [catalog] = createResource(language.locale, (locale) => loadMessages(definition.i18n, locale), {
      initialValue: initial,
    })

    const messages = () => catalog.latest

    // Promise.try runs the cleanup synchronously and isolates a throw from the others.
    const release = (fn: Cleanup) =>
      void Promise.try(fn).catch((cause: unknown) => console.error(`[extension] ${extension}`, cause))

    const own = (fn: Cleanup): Cleanup => {
      // Work that outlives the extension, e.g. a promise callback, is released as soon as it registers.
      if (controller.signal.aborted) {
        release(fn)

        return () => {}
      }

      const cleanup = () => {
        if (cleanups.delete(cleanup)) return fn()
      }

      cleanups.add(cleanup)

      return cleanup
    }

    // The extension went away, or the scope registering (e.g. through a captured owner) already ended.
    const late = () => controller.signal.aborted || !!useContext(LifetimeContext)?.ended

    // Withdrawn with the current owner, or with the extension when there is none (after an await).
    const register = (fn: Cleanup): Cleanup => {
      if (late()) {
        release(fn)

        return () => {}
      }

      const cleanup = own(fn)
      const scope = getOwner()

      if (scope && scope !== root) onCleanup(() => void cleanup())

      return cleanup
    }

    const clients = new Map<string, { client: IpcClient<IpcSpec>; live: Live<unknown> }>()

    // One accessor per token, and one Live object per transition, so readers re-run only when the provider changes.
    const ipcLive = (token: Ipc | IpcRef): Live<unknown> => {
      if (!input.ipc) return inactive.disabled

      const full = resolve(token)
      const client = full && input.ipc(full)

      if (!full || !client) return absent(token.id, full ? (input.generation?.(full) ?? 0) : 0, true)

      const generation = input.generation?.(full) ?? 1
      const cached = clients.get(token.id)

      if (cached?.client === client && cached.live.status === "active" && cached.live.generation === generation)
        return cached.live

      const value = Object.assign({}, client, {
        on: (name: string, listener: Parameters<typeof client.on>[1]) => register(client.on(name, listener)),
      })

      const live = { status: "active", value, generation } as const

      clients.set(token.id, { client, live })

      return live
    }

    const lives = new Map<string, Accessor<Live<unknown>>>()

    const liveOf = (token: Token) => {
      const existing = lives.get(token.id)

      if (existing) return existing

      const read = Live.accessor(token.kind === "contract" ? () => contractLive(token) : () => ipcLive(token))

      lives.set(token.id, read)

      return read
    }

    const value = (read: Accessor<Live<unknown>>) => {
      const current = read()

      return current.status === "active" ? current.value : undefined
    }

    // A declared reference resolves once the chunk that loads its full token passes it to `load`, here and in other
    // extensions.
    const used = (token: Token) => {
      const read = liveOf(token)

      if (token.kind !== "ipc" || token.spec) return read

      return Object.assign(read, {
        load(full: Ipc) {
          if (full.id !== token.id) throw new Error(`Ipc "${full.id}" does not resolve the reference "${token.id}"`)
          learn(full)

          return read
        },
      })
    }

    // `ctx.uses` holds the extension's own tokens too; `Extension.define` refuses a key that names two tokens.
    const usable = { ...definition.provides, ...definition.uses }

    Object.values(usable).forEach(learn)
    Object.values(definition.requires ?? {}).forEach(learn)

    const stores: Stores = {}

    const context = {
      id: extension,
      signal: controller.signal,
      add<T>(registry: Registry<T>, item: T | (() => T | undefined)) {
        if (late()) return () => {}

        // Promise callbacks may have no owner; fall back to the extension root.
        const read =
          // SAFETY: a function item is the SDK's reactive form; registries take no function values.
          // oxlint-disable-next-line anti-slop/no-runtime-typeof -- see SAFETY above
          typeof item === "function"
            ? runWithOwner(getOwner() ?? root, () => createMemo(item as () => T | undefined))
            : () => item

        const key = `${extension}/${++sequence.value}`

        setState("entries", registry.id, (entries = []) => [
          ...entries,
          { key, registry: registry.id, extension, value: read ?? (() => undefined) },
        ])

        return register(() =>
          setState("entries", registry.id, (entries = []) => entries.filter((entry) => entry.key !== key)),
        )
      },
      list,
      provide<T>(token: Contract<T> | Ipc, impl: T) {
        if (token.kind === "ipc") throw new Error("Ipcs are provided by an extension's main entry")

        if (late()) return () => {}

        const generation = (generations.get(token.id) ?? 0) + 1

        generations.set(token.id, generation)

        const entry = { live: { status: "active", value: impl, generation } as const }

        provided.set(token.id, entry)
        setState("contracts", token.id, (version = 0) => version + 1)

        return register(() => {
          if (provided.get(token.id) !== entry) return

          provided.delete(token.id)
          setState("contracts", token.id, (version = 0) => version + 1)
        })
      },
      uses: Object.fromEntries(Object.entries(usable).map(([name, token]) => [name, used(token)])),
      // The host starts the extension only while every hard contract is active, and restarts it when one changes.
      requires: Object.fromEntries(
        Object.entries(definition.requires ?? {}).map(([name, token]) => [name, untrack(() => value(liveOf(token)))]),
      ),
      stores,
      t(key: string, params?: Record<string, string | number | boolean>) {
        const template = messages()[key]

        if (template !== undefined) return resolveTemplate(template, params)

        // SAFETY: a key the extension's catalog lacks is one of the app's shared keys, such as `common.*`.
        return language.t(key as Parameters<typeof language.t>[0], params)
      },
      plural(key: string, count: number, params?: Record<string, string | number | boolean>) {
        const current = messages()
        const template = current[`${key}.${pluralCategory(language.intl(), count)}`] ?? current[`${key}.other`]

        if (template !== undefined) return resolveTemplate(template, { ...params, count })

        // SAFETY: a key the extension's catalog lacks is one of the app's shared keys, such as `common.*`.
        return language.plural(key as Parameters<typeof language.plural>[0], count, params)
      },
    }

    // Each HostApi is created on the instance's first read of it.
    const created = new Map<string, HostApis[keyof HostApis]>()

    Object.defineProperties(
      context,
      Object.fromEntries(
        Object.entries(factories).map(([name, create]) => [
          name,
          {
            enumerable: true,
            get() {
              if (!created.has(name)) created.set(name, create(extension, root, typed, register))

              return created.get(name)
            },
          },
        ]),
      ),
    )

    // SAFETY: one implementation serves `Context` and every `SetupContext`: the declarations' records are built from
    // the definition, and every HostApi is a getter defined above.
    // oxlint-disable-next-line anti-slop/no-chained-type-assertions -- see SAFETY above
    const typed = context as unknown as InstanceContext

    const sessions: ReturnType<typeof createSessionStore<object>>[] = []

    return {
      definition,
      context: typed,
      prepare() {
        const storage = typed.storage

        const loaded = windowStores(definition).flatMap(([name, declaration]) => {
          if (declaration.scope === "global") {
            const handle = storage.store(name, { ...declaration, scope: "global" })

            stores[name] = handle

            return [whenLoaded(handle)]
          }

          const store = createSessionStore({
            open: (session) => storage.store(name, { ...declaration, scope: { session } }),
            owner: root,
            sessions: typed.sessions,
          })

          stores[name] = store.get
          sessions.push(store)

          return []
        })

        if (sessions.length > 0) own(() => sessions.forEach((store) => store.dispose()))

        return Promise.all(loaded)
      },
      preload: (session) => sessions.forEach((store) => store.get(session)),
      dispose() {
        controller.abort()
        // One batch: every contribution and contract of the extension disappears in the same frame.
        batch(() => {
          Array.from(cleanups).reverse().forEach(release)
          cleanups.clear()
          Object.entries(state.entries).forEach(([registry, entries]) => {
            if (!entries?.some((entry) => entry.extension === extension)) return

            setState("entries", registry, (list = []) => list.filter((entry) => entry.extension !== extension))
          })
        })
        // A throwing onCleanup in the extension's root must not stop the host disposing the rest.
        release(dispose)
      },
    }
  }

  const deactivate = (id: string) => {
    loads.delete(id)

    const instance = instances.get(id)

    if (!instance) return

    instances.delete(id)
    instance.dispose()
  }

  const fail = (id: string, cause: unknown, phase: ExtensionFailure["phase"] = "setup") => {
    console.error(`[extension] ${id}`, cause)
    batch(() => {
      // A contribution that fails to render renders nothing; the extension and its other contributions stay.
      if (phase === "setup") setState("status", id, "failed")

      setState("failures", id, {
        phase,
        error: cause instanceof Error ? (cause.stack ?? cause.message) : String(cause),
      })
    })
  }

  const replaced = new Map<string, Definition>()
  const latest = (definition: Definition) => replaced.get(definition.id) ?? definition

  // The startup gate: once every entry settled it stays open, so enabling or reloading an extension later
  // never unmounts the app. An entry waiting on a hard contract that is disabled or failed has settled too.
  const ready = createMemo<boolean>(
    (settled) =>
      settled ||
      (!!input.disabled() &&
        input.definitions.every((definition) => {
          if (!definition.renderer) return true

          const status = state.status[definition.id]

          if (status === "active" || status === "failed" || status === "disabled" || status === "blocked") return true

          return Object.values(definition.requires ?? {}).some((token) => {
            const provider = providerState(token)

            return blocked(provider)
          })
        })),
    false,
  )

  // `requires` gating: an extension starts once every hard contract is active and restarts with a new generation of
  // any of them. Activation is never ordered by the graph; only these extensions wait, and only for their contracts.
  input.definitions.forEach((definition) => {
    const tokens = Object.values(definition.requires ?? {})

    if (tokens.length === 0) return

    const key = createMemo(() => {
      const providers = tokens.map(providerState)

      if (providers.every((provider) => provider.status === "active"))
        return providers.map((provider) => (provider.status === "active" ? provider.generation : 0)).join(",")

      return providers.some(blocked) ? "blocked" : undefined
    })

    createRenderEffect(
      on(key, (value) =>
        untrack(() =>
          batch(() => {
            const id = definition.id

            deactivate(id)

            if (input.disabled()?.has(id) !== false) return

            if (value === undefined) return setState("status", id, "loading")

            if (value === "blocked") return setState("status", id, "blocked")

            void activate(latest(definition))
          }),
        ),
      ),
    )
  })

  // Establish requirement watchers before activation, including their initial state. Publish every disabled status
  // before starting enabled entries, so declaration order cannot leave a hard-dependency chain loading forever.
  createMemo(() => {
    const disabled = input.disabled()

    if (!disabled) return

    untrack(() =>
      batch(() => {
        input.definitions
          .filter((definition) => disabled.has(definition.id))
          .forEach((definition) => {
            deactivate(definition.id)
            setState("status", definition.id, "disabled")
          })
        input.definitions
          .filter((definition) => !disabled.has(definition.id))
          .forEach((definition) => {
            if (instances.has(definition.id) || state.status[definition.id] === "loading") return

            void activate(latest(definition))
          })
      }),
    )
  })

  onCleanup(() => {
    lifetime.disposed = true
    loads.clear()
    Array.from(instances.keys()).forEach(deactivate)
  })

  return {
    state,
    ready,
    list,
    items,
    links,
    definitions: () => input.definitions.map(latest),
    context: (id: string): Context | undefined => instances.get(id)?.context,
    fail,
    /** Starts loading every active extension's declared session stores for a session that mounts. */
    preload(session: SessionRef) {
      instances.forEach((instance) => instance.preload(session))
    },
    /** `next` replaces the definition, e.g. after a development hot update. */
    reload(id: string, next?: Definition) {
      const definition = next ?? input.definitions.find((item) => item.id === id)

      if (!definition) return

      if (next) replaced.set(id, next)

      batch(() => {
        deactivate(id)
        setState("failures", id, undefined)
        void activate(latest(definition))
      })
    },
  }
}

/** The window's declared stores; a `Store.main` store belongs to the main process. */
function windowStores(definition: Definition) {
  return Object.entries(definition.stores ?? {}).flatMap(([name, declaration]) =>
    declaration.scope === "main" ? [] : [[name, declaration] as const],
  )
}

/** A hard dependency that is not coming until its provider or configuration changes. */
function blocked(provider: Provider) {
  return provider.status === "inactive" && provider.reason !== "restarting"
}

/** English merged under the locale's messages. A catalog that fails to load leaves English. */
async function loadMessages(catalog: Catalog | undefined, locale: string): Promise<Messages> {
  const english = catalog?.en ?? {}
  const source = catalog?.[locale]

  if (!source || locale === "en") return english

  const loaded =
    // SAFETY: a catalog entry is either inline messages or the loader of a locale module, as `Catalog` types it.
    // oxlint-disable-next-line anti-slop/no-runtime-typeof -- see SAFETY above
    typeof source === "function"
      ? await source().then(
          (module) => module.default,
          () => ({}),
        )
      : source

  return { ...english, ...loaded }
}

import { createMemo, createResource, onCleanup } from "solid-js"
import { createStore, reconcile } from "solid-js/store"
import type { Bridge, Installed } from "@opencode/gui-extensions/sdk/bridge"

/** Saved enable preferences and manager metadata; activation and blocked-dependency status belong to the host. */
export function createInstalled(bridge: Bridge | undefined) {
  const [state, setState] = createStore<{ list?: readonly Installed[] }>({})
  // A pushed list is newer than the initial reply, so a reply that arrives after one is dropped.
  const pushed = { count: 0 }
  const [initial] = createResource(async () => (bridge ? bridge.manager.initial?.catch(() => undefined) : []))

  // Metadata still loads for settings and failure reporting. Activation can use known preload rows before it arrives.
  createResource(async () => {
    if (!bridge) return

    const seen = pushed.count
    const list = await bridge.manager.list()

    if (pushed.count === seen) setState("list", reconcile([...list]))
  })

  if (bridge)
    onCleanup(
      bridge.on((message) => {
        if (message.type !== "extensions") return
        pushed.count++
        setState("list", reconcile([...message.list]))
      }),
    )

  return {
    enableState: createMemo(() => state.list ?? initial.latest),
    list: () => state.list ?? [],
  }
}

import { expect, test } from "bun:test"
import { Ipc } from "@opencode/gui-extensions/sdk"
import { Schema } from "effect"
import type { Bridge, BridgeMessage } from "@opencode/gui-extensions/sdk/bridge"
import { createIpcClients } from "./ipc"

const token: Ipc = { kind: "ipc", id: "fixture", spec: { id: "fixture", methods: {} } }

type Reply = { readonly available: boolean; readonly state?: unknown }

// Each row sends an event while the subscribe reply is in flight; the older reply must not undo it.
test.each<[string, BridgeMessage, Reply, { available: boolean; state: unknown }]>([
  [
    "the Ipc appearing",
    { type: "available", ipc: "fixture", available: true },
    { available: false },
    { available: true, state: undefined },
  ],
  [
    "the Ipc going away",
    { type: "available", ipc: "fixture", available: false },
    { available: true, state: { count: 1 } },
    { available: false, state: undefined },
  ],
  [
    "a state push",
    { type: "state", ipc: "fixture", state: { count: 2 } },
    { available: true, state: { count: 1 } },
    { available: true, state: { count: 2 } },
  ],
])("a subscribe reply older than %s keeps the event's data", async (_, event, reply, expected) => {
  const bridge = fakeBridge()
  const ipcs = createIpcClients(bridge.value)
  expect(ipcs.client(token)).toBeUndefined()
  bridge.emit(event)
  bridge.reply(reply)
  await Bun.sleep(0)
  const client = ipcs.client(token)
  expect({ available: !!client, state: client?.state() }).toEqual(expected)
  ipcs.dispose()
})

test("no-input methods pass their first argument's abort signal to the bridge", async () => {
  const bridge = fakeBridge()
  const controller = new AbortController()
  const calls: { method: string; input?: unknown; signal?: AbortSignal }[] = []

  const methods = Ipc.define({
    id: "fixture",
    methods: { info: { output: Schema.String }, echo: { input: Schema.String, output: Schema.String } },
  })

  const ipcs = createIpcClients({
    ...bridge.value,
    call: async (request, signal) => {
      calls.push({ method: request.method, input: request.input, signal })

      return "reply"
    },
  })

  ipcs.typed(methods)
  bridge.emit({ type: "available", ipc: "fixture", available: true })
  const client = ipcs.typed(methods)

  expect(await client?.info({ signal: controller.signal })).toBe("reply")
  expect(await client?.echo("input", { signal: controller.signal })).toBe("reply")
  expect(calls).toEqual([
    { method: "info", input: null, signal: controller.signal },
    { method: "echo", input: "input", signal: controller.signal },
  ])
  ipcs.dispose()
})

function fakeBridge() {
  const listeners = new Set<(message: BridgeMessage) => void>()
  const pending = Promise.withResolvers<Reply>()

  const value: Bridge = {
    packaged: false,
    call: () => Promise.reject(new Error("no calls in this test")),
    subscribe: () => pending.promise,
    on: (listener) => {
      listeners.add(listener)

      return () => {
        listeners.delete(listener)
      }
    },
    embed: () => {},
    capture: async () => undefined,
    runMenubarItem: () => {},
    configure: () => {},
    manager: {
      list: async () => [],
      enable: async () => {},
      disable: async () => {},
      reload: async () => {},
      install: async () => {},
      remove: async () => {},
      source: async () => "",
      asset: () => "",
    },
  }

  return {
    value,
    emit: (message: BridgeMessage) => listeners.forEach((listener) => listener(message)),
    reply: (reply: Reply) => pending.resolve(reply),
  }
}

import { batch } from "solid-js"
import { createStore, reconcile } from "solid-js/store"
import { Schema } from "effect"
import type { Ipc, IpcCallOptions, IpcClient, IpcSpec } from "@opencode/gui-extensions/sdk"
import type { Bridge } from "@opencode/gui-extensions/sdk/bridge"

type Codec = NonNullable<IpcSpec["state"]>

/** A value an Ipc's codec decodes to; each Ipc's `IpcClient` gives it that Ipc's own type. */
type Decoded = Codec["Type"]

/** A value as it crosses the bridge, encoded by an Ipc's codec. */
type Encoded = Codec["Encoded"]

type IpcState = {
  available: Record<string, boolean | undefined>
  values: Record<string, Decoded>
  // Counts each time an Ipc becomes available, so users can tell a returning provider from the one they had.
  generations: Record<string, number | undefined>
}

/** Renderer-side clients for the Ipcs that extensions provide in the main process. */
export function createIpcClients(bridge: Bridge | undefined) {
  const [state, setState] = createStore<IpcState>({ available: {}, values: {}, generations: {} })

  const setAvailable = (id: string, available: boolean) => {
    if (available && !state.available[id]) setState("generations", id, (value = 0) => value + 1)

    setState("available", id, available)
  }

  const specs = new Map<string, IpcSpec>()
  const clients = new Map<string, IpcClient<IpcSpec>>()
  const listeners = new Map<string, Set<(name: string, data: Decoded) => void>>()
  const subscribed = new Set<string>()
  // How many availability and state events reached each Ipc. Events are newer than any snapshot, so a
  // subscribe reply only fills in what no event changed while it was in flight.
  const changes = new Map<string, { available: number; state: number }>()

  const changesOf = (id: string) => {
    const existing = changes.get(id)

    if (existing) return existing

    const created = { available: 0, state: 0 }

    changes.set(id, created)

    return created
  }

  const decodeState = (id: string, value: Encoded): Decoded => {
    const schema = specs.get(id)?.state

    return schema ? Schema.decodeUnknownSync(schema)(value) : value
  }

  const stop = bridge?.on((message) => {
    if (message.type === "state") {
      if (!specs.has(message.ipc)) return

      changesOf(message.ipc).state++
      setState("values", message.ipc, reconcile(decodeState(message.ipc, message.state)))

      return
    }

    if (message.type === "available") {
      const changed = changesOf(message.ipc)

      changed.available++

      // Going away clears the state too.
      if (!message.available) changed.state++

      batch(() => {
        setAvailable(message.ipc, message.available)

        if (!message.available) setState("values", message.ipc, undefined)
      })

      return
    }

    if (message.type !== "event") return

    const schema = specs.get(message.ipc)?.events?.[message.name]
    const data = schema ? Schema.decodeUnknownSync(schema)(message.data) : message.data

    listeners.get(message.ipc)?.forEach((listener) => listener(message.name, data))
  })

  const subscribe = (connected: Bridge, token: Ipc) => {
    if (subscribed.has(token.id)) return

    subscribed.add(token.id)
    specs.set(token.id, token.spec)

    const before = { ...changesOf(token.id) }

    void connected.subscribe(token.id).then((result) => {
      const after = changesOf(token.id)

      batch(() => {
        if (after.available === before.available) setAvailable(token.id, result.available)

        if (after.state === before.state && result.state !== undefined)
          setState("values", token.id, decodeState(token.id, result.state))
      })
    })
  }

  const create = (connected: Bridge, token: Ipc): IpcClient<IpcSpec> => {
    const methods = Object.fromEntries(
      Object.entries(token.spec.methods).map(([name, method]) => {
        const call = async (input: Decoded, options?: IpcCallOptions) => {
          const encoded = method.input ? Schema.encodeUnknownSync(method.input)(input) : null
          const output = await connected.call({ ipc: token.id, method: name, input: encoded }, options?.signal)

          return method.output ? Schema.decodeUnknownSync(method.output)(output) : undefined
        }

        return [name, method.input ? call : (options?: IpcCallOptions) => call(undefined, options)]
      }),
    )

    const client = Object.assign(methods, {
      state: () => state.values[token.id],
      on(name: string, listener: (data: Decoded) => void) {
        const set = listeners.get(token.id) ?? new Set()

        const wrapped = (event: string, data: Decoded) => {
          if (event === name) listener(data)
        }

        set.add(wrapped)
        listeners.set(token.id, set)

        return () => {
          set.delete(wrapped)
        }
      },
    })

    // SAFETY: `methods` holds one codec-checked function per method of the token's spec, beside `state` and `on`.
    return client as IpcClient<IpcSpec>
  }

  const client = (token: Ipc) => {
    if (!bridge) return undefined

    subscribe(bridge, token)

    if (!state.available[token.id]) return undefined

    const existing = clients.get(token.id)

    if (existing) return existing

    const created = create(bridge, token)

    clients.set(token.id, created)

    return created
  }

  return {
    client,
    /** How many times the Ipc became available; 0 until it first is. Reactive. */
    generation: (token: Ipc) => state.generations[token.id] ?? 0,
    /** A client typed by its token, for host code that uses one Ipc directly. */
    typed: <S extends IpcSpec>(token: Ipc<S>) =>
      // SAFETY: the client was built from this token's spec, so its methods, state and events are those of `S`.
      client(token) as IpcClient<S> | undefined,
    /** Stops listening to the bridge. Call it when the owner of these clients goes away. */
    dispose() {
      stop?.()
    },
  }
}

import { batch, createEffect, createSignal, untrack } from "solid-js"
import type { SessionRef } from "@opencode/gui-extensions/sdk"

/**
 * Layout writes find a session's stored layout through its location, which is unknown until the server reports it
 * (for example after a server re-authenticates). `hold` keeps such a write and runs it, in order, once the location is
 * known, so no write is lost.
 */
export function createLocatedWrites() {
  const [pending, setPending] = createSignal<readonly { readonly session: SessionRef; readonly run: () => void }[]>([])
  // Syncs held writes with the session locations the server reports.
  createEffect(() => {
    const held = pending()

    if (held.length === 0) return
    const located = held.filter((item) => item.session.location)

    if (located.length === 0) return
    setPending(held.filter((item) => !located.includes(item)))
    untrack(() => batch(() => located.forEach((item) => item.run())))
  })

  return {
    hold(session: SessionRef, run: () => void) {
      setPending((held) => [...held, { session, run }])
    },
  }
}

import { createContext, onCleanup, useContext } from "solid-js"
import { createStore, reconcile } from "solid-js/store"
import type { Bridge, BridgeMenubarItem } from "@opencode/gui-extensions/sdk/bridge"

/** MenubarItem contributions from main extensions, for the in-app menu on Windows and Linux. */
export function createMenubarItems(bridge: Bridge | undefined) {
  const [state, setState] = createStore<{ items: BridgeMenubarItem[] }>({ items: [] })

  if (bridge)
    onCleanup(
      bridge.on((message) => {
        if (message.type === "menubarItems") setState("items", reconcile([...message.items], { key: "id" }))
      }),
    )

  return {
    items: () => state.items,
    run: (id: string) => bridge?.runMenubarItem(id),
  }
}

const MenubarItemsContext = createContext<ReturnType<typeof createMenubarItems>>()

export const MenubarItemsProvider = MenubarItemsContext.Provider

export function useMenubarItems() {
  return useContext(MenubarItemsContext)
}

import { createMemo, For, lazy, Show, Suspense, type JSX } from "solid-js"
import { createStore } from "solid-js/store"
import { Tabs } from "@opencode/ui/tabs"
import { Icon } from "@opencode/ui/icon"
import {
  Panel,
  type PanelSidebar,
  type PanelTab,
  type MountedSession,
  type SessionScreen,
} from "@opencode/gui-extensions/sdk"
import { useLanguage } from "@/runtime/i18n/language"
import { useExtensionHost } from "./host"
import { panelKey } from "./panel-keys"
import { MobilePanel, type Region, type RegionEntry } from "./panels"

const MobilePanelDrawer = lazy(async () => {
  const { MobilePanelDrawer } = await import("@/shell/mobile-panel-drawer")

  return { default: MobilePanelDrawer }
})

export type MobileEntry = RegionEntry & { readonly mobile: NonNullable<Panel["mobile"]> }

/** Panels that offer a narrow-screen view, keyed `${extension}:${panel id}`. */
export function createMobileViews() {
  const host = useExtensionHost()

  const entries = createMemo(() =>
    host.items(Panel).flatMap((item): MobileEntry[] => {
      const mobile = item.value.mobile

      if (!mobile) return []
      const tab: PanelTab = { id: item.value.id, title: mobile.title }

      return [
        { key: panelKey(item.extension, item.value.id), extension: item.extension, tab, provider: item.value, mobile },
      ]
    }),
  )

  const sorted = (kinds: readonly string[]) =>
    entries()
      .filter((entry) => kinds.includes(entry.mobile.kind))
      .toSorted((a, b) => a.mobile.order - b.mobile.order)

  return {
    entries,
    tabs: createMemo(() => sorted(["tab"])),
    menu: createMemo(() => sorted(["menu", "drawer"])),
    find: (key: string) => entries().find((entry) => entry.key === key),
  }
}

export type MobileViews = ReturnType<typeof createMobileViews>

/** The narrow-screen view switcher: the conversation, each tab view, and a More drawer with the other views. */
export function MobileViewTabs(props: {
  views: MobileViews
  region: Region
  current: string
  session: MountedSession
  screen: SessionScreen
  sidebar: PanelSidebar
  bottom?: boolean
  onSelect: (key: string) => void
}): JSX.Element {
  const language = useLanguage()

  const [store, setStore] = createStore<{
    open: boolean
    loaded: boolean
    drawer: string | undefined
  }>({
    open: false,
    loaded: false,
    drawer: undefined,
  })

  const drawer = createMemo(() => (store.drawer ? props.views.find(store.drawer) : undefined))

  const tab = createMemo(() =>
    props.current === "session" || props.views.tabs().some((entry) => entry.key === props.current)
      ? props.current
      : "more",
  )

  let trigger: HTMLButtonElement | undefined

  return (
    <div
      class="relative flex shrink-0 items-center before:pointer-events-none before:absolute before:inset-x-0 before:h-px before:bg-v2-border-border-base before:content-['']"
      classList={{ "before:top-0": props.bottom, "before:bottom-0": !props.bottom }}
      data-slot="session-mobile-view-navigation"
    >
      <Tabs value={tab()} variant="line" class="!h-auto min-w-0 flex-1" data-slot="session-mobile-view-tabs">
        <Tabs.List aria-label={language.t("session.view.select")} class="!h-9 !gap-0 !px-0 before:!hidden">
          <Tabs.Trigger
            value="session"
            class="min-w-0 flex-1"
            classes={{ button: "w-full justify-center" }}
            onClick={() => props.onSelect("session")}
          >
            {language.t("session.tab.session")}
          </Tabs.Trigger>
          <For each={props.views.tabs()}>
            {(entry) => (
              <Tabs.Trigger
                value={entry.key}
                class="min-w-0 flex-1"
                classes={{ button: "w-full justify-center" }}
                onClick={() => props.onSelect(entry.key)}
              >
                {entry.mobile.title}
              </Tabs.Trigger>
            )}
          </For>
          <Show when={props.views.menu().length}>
            <Tabs.Trigger
              value="more"
              ref={(element: HTMLButtonElement) => {
                trigger = element
              }}
              class="min-w-0 flex-1"
              classes={{ button: "w-full justify-center" }}
              aria-haspopup="dialog"
              aria-expanded={store.open}
              onClick={() => setStore({ open: true, loaded: true, drawer: undefined })}
            >
              {language.t("session.tab.more")}
            </Tabs.Trigger>
          </Show>
        </Tabs.List>
      </Tabs>
      <Show when={store.loaded}>
        <Suspense>
          <MobilePanelDrawer
            title={drawer()?.mobile.title ?? language.t("common.moreOptions")}
            hideHeader
            open={store.open}
            onOpenChange={(open) => setStore("open", open)}
            returnFocus={() => trigger}
          >
            <Show
              when={drawer()}
              keyed
              fallback={
                <div
                  data-slot="session-mobile-view-options"
                  class="flex flex-col gap-0.5 rounded-[6px] bg-v2-background-bg-base p-0.5 shadow-[var(--v2-elevation-raised)] [[data-color-scheme=dark]_&]:bg-v2-background-bg-layer-01"
                >
                  <For each={props.views.menu().filter((entry) => entry.mobile.kind === "menu")}>
                    {(entry) => (
                      <button
                        type="button"
                        class="flex min-h-11 w-full items-center gap-2 rounded-[4px] py-1 ps-3 pe-2 text-start text-[13px] font-[440] leading-[var(--line-height-base)] text-v2-text-text-base hover:bg-[var(--v2-overlay-simple-overlay-hover)] focus-visible:outline-none focus-visible:bg-[var(--v2-overlay-simple-overlay-hover)] aria-pressed:bg-[var(--v2-overlay-simple-overlay-pressed)]"
                        aria-pressed={props.current === entry.key}
                        onClick={() => {
                          props.onSelect(entry.key)
                          setStore("open", false)
                        }}
                      >
                        <Show when={entry.mobile.icon}>
                          {(icon) => <Icon name={icon()} class="shrink-0 text-v2-icon-icon-muted" />}
                        </Show>
                        <span class="min-w-0 flex-1 truncate">{entry.mobile.title}</span>
                        <Show when={props.current === entry.key}>
                          <Icon name="check" class="ms-1 shrink-0 text-v2-icon-icon-muted" />
                        </Show>
                      </button>
                    )}
                  </For>
                  <For each={props.views.menu().filter((entry) => entry.mobile.kind === "drawer")}>
                    {(entry) => (
                      <button
                        type="button"
                        class="flex min-h-11 w-full items-center gap-2 rounded-[4px] py-1 ps-3 pe-2 text-start text-[13px] font-[440] leading-[var(--line-height-base)] text-v2-text-text-base hover:bg-[var(--v2-overlay-simple-overlay-hover)] focus-visible:outline-none focus-visible:bg-[var(--v2-overlay-simple-overlay-hover)]"
                        onClick={() => setStore("drawer", entry.key)}
                      >
                        <Show when={entry.mobile.icon}>
                          {(icon) => <Icon name={icon()} class="shrink-0 text-v2-icon-icon-muted" />}
                        </Show>
                        <span class="min-w-0 flex-1 truncate">{entry.mobile.title}</span>
                        <Icon name="chevron-right" class="ms-1 shrink-0 text-v2-icon-icon-muted" />
                      </button>
                    )}
                  </For>
                </div>
              }
            >
              {(entry) => (
                <MobilePanel
                  entry={entry}
                  view={props.session}
                  screen={props.screen}
                  sidebar={props.sidebar}
                  visible={store.open}
                  open={() => props.region.openFor(entry.extension)}
                />
              )}
            </Show>
          </MobilePanelDrawer>
        </Suspense>
      </Show>
    </div>
  )
}

import {
  batch,
  createMemo,
  createEffect,
  createRenderEffect,
  createRoot,
  createSignal,
  getOwner,
  on,
  onCleanup,
  untrack,
  type Accessor,
} from "solid-js"
import type {
  BackgroundTask,
  Comments,
  Composer,
  Files,
  LineRange,
  ServerRef,
  MountedSession,
  SessionScreen,
} from "@opencode/gui-extensions/sdk"
import { useComments } from "@/composer/comments"
import { useComposerState } from "@/composer/persistence"
import { useServer } from "@/runtime/server/current"
import { ServerConnection, serverName } from "@/runtime/server/registry"
import { sessionInWorkspace, sessionProject, type SessionModel } from "@/session/model"
import { useFile } from "@/workspaces/files/model"
import { useWorkspaceLocation } from "@/workspaces/location"
import { pathKey } from "@/workspaces/path-key"
import { useExtensionAttachment } from "./host-apis"

const noTasks: readonly BackgroundTask[] = []

/** The root of the routed session's object, which ends when the screen routes another session. */
type ObjectRoot = { dispose?: () => void }

/**
 * The routed session as extensions see it: one frozen object per routed session, a new one each time the screen
 * routes another session, and the `SessionScreen` that owns the route-following files, comments and composer.
 */
export function createMountedSession(session: SessionModel) {
  const file = useFile()
  const comments = useComments()
  const composer = useComposerState()
  const server = useServer()
  const location = useWorkspaceLocation()
  const attachment = useExtensionAttachment()
  // The composer region owns background tasks and is created after the view.
  const [background, setBackground] = createSignal<Accessor<readonly BackgroundTask[]>>()

  const serverRef: ServerRef = {
    get id() {
      return server.key
    },
    get name() {
      return serverName(server.conn) || server.key
    },
    get url() {
      return server.ctx.sdk.url
    },
    get password() {
      return server.conn.http.password
    },
    get client() {
      return server.ctx.sdk.api
    },
    get data() {
      return server.ctx.data
    },
    get local() {
      return server.isLocal
    },
    get builtin() {
      return ServerConnection.builtin(server.conn)
    },
    get compatible() {
      return !server.health?.incompatible
    },
    get connected() {
      return server.ctx.sdk.connection.status() === "connected"
    },
  }

  const files: Files = {
    get root() {
      return location().directory
    },
    ready: file.ready,
    resolve: file.normalize,
    absolute: file.absolute,
    get: file.get,
    missing: file.notFound,
    sync: (path, options) => file.load(path, options),
    exists: file.exists,
    search: (query, options) =>
      options?.kind === "any" ? file.searchFilesAndDirectories(query, options) : file.searchFiles(query, options),
    selection: {
      // SAFETY: the file model returns the view cache's selection for the path, which its schema types as a line range.
      get: (path) => file.selectedLines(path) as LineRange | null | undefined,
      set: (path, range) => void file.setSelectedLines(path, range),
    },
    scroll: {
      get: (path) => ({
        // SAFETY: the file model returns the view cache's offsets for the path, which its schema types as numbers.
        top: file.scrollTop(path) as number | undefined,
        // SAFETY: as above.
        left: file.scrollLeft(path) as number | undefined,
      }),
      set(path, value) {
        if (value.top !== undefined) file.setScrollTop(path, value.top)

        if (value.left !== undefined) file.setScrollLeft(path, value.left)
      },
    },
    tree: {
      list: file.tree.children,
      state: file.tree.state,
      sync: (path, options) => (options?.force ? file.tree.refresh(path) : file.tree.list(path)),
      expand: (path, options) => void file.tree.expand(path, options),
      collapse: (path) => void file.tree.collapse(path),
    },
  }

  const commentFile = (id: string) => comments.all().find((item) => item.id === id)?.file

  const comment: Comments = {
    list: (path) => (path ? comments.list(path) : comments.all()),
    add: comments.add,
    update(id, text) {
      const path = commentFile(id)

      if (path) comments.update(path, id, text)
    },
    remove(id) {
      const path = commentFile(id)

      if (path) comments.remove(path, id)
    },
    focus: { current: comments.focus, set: (value) => void comments.setFocus(value) },
    active: { current: comments.active, set: (value) => void comments.setActive(value) },
  }

  const composerRef: Composer = {
    attach: (part) => composer.context.add(part),
    update: (id, patch) => composer.context.updateComment(id, patch),
    detach: (id) => composer.context.removeComment(id),
  }

  // Each object's memos live in its own root, which ends when the next object replaces it: a kept object stops
  // updating `project`, `listedProject` and `local`, and its other fields keep reading this session's data.
  const create = (input: { id: string; directory: string; tab: string; visit: object }): MountedSession => {
    const id = input.id
    const directory = input.directory
    const info = () => server.ctx.data.session.get(id)

    // Global sync adds the worktrees found on disk, and the user's local name and icon override the server's.
    // Raw metadata stands in until global sync lists the project.
    const project = createMemo(() => {
      const value = info()

      return (
        (value && server.ctx.projects.detailsForSession(value)) || sessionProject(server.ctx.data, value, directory)
      )
    })

    // Only a project opened at this exact directory; a session in a project subfolder has none.
    const listedProject = createMemo(() => {
      const key = pathKey(directory)

      return server.ctx.projects
        .list()
        .find((item) => pathKey(item.worktree) === key || item.sandboxes?.some((sandbox) => pathKey(sandbox) === key))
    })

    const local = createMemo(() => !sessionInWorkspace(server.ctx.sync.data.project, info(), directory))

    const view: MountedSession = Object.freeze({
      key: `${server.key}\n${id}`,
      id,
      tab: input.tab,
      visit: input.visit,
      server: serverRef,
      get pending() {
        return server.ctx.data.session.creating(id)
      },
      get location() {
        return info()?.location
      },
      get project() {
        return project()
      },
      get listedProject() {
        return listedProject()
      },
      directory,
      get local() {
        return local()
      },
      // The composer region serves the routed session only.
      get background() {
        return mounted() === view ? (background()?.() ?? noTasks) : noTasks
      },
    })

    return view
  }

  // One object while this screen is mounted, whichever session it routes: its models follow the route.
  const screen: SessionScreen = Object.freeze({
    file: files,
    comment,
    composer: composerRef,
  })

  const owner = getOwner()
  const root: ObjectRoot = {}

  onCleanup(() => root.dispose?.())

  // A new object for each routed session, and for the same session once it moves to another directory or its shell tab
  // is known: its fields never change. A moment without an id keeps the last one. A move is the same routing visit.
  const mounted = createMemo<MountedSession>((previous) => {
    const id = session.identity.sessionID() ?? ""
    const directory = session.workspace.directory()
    const tab = session.layout.tabKey() ?? ""

    if (previous && !id) return previous

    if (previous && previous.id === id && previous.directory === directory && previous.tab === tab) return previous

    const visit = previous?.id === id ? previous.visit : {}

    return untrack(() =>
      createRoot((dispose) => {
        root.dispose?.()
        root.dispose = dispose

        return create({ id, directory, tab, visit })
      }, owner),
    )
  })

  // The session's declared stores start loading now, before its regions read them.
  createRenderEffect(on(mounted, (view) => attachment.preload(view)))
  // Publish both after render, with the original session-mount timing. Renders receive their own screen directly;
  // only global observers need this attachment. One batch prevents exposing a view on another screen.
  createEffect(() =>
    batch(() => {
      onCleanup(attachment.screen(screen))
      onCleanup(attachment.mount(mounted))
    }),
  )

  return {
    screen,
    view: mounted,
    bindBackground: (tasks: Accessor<readonly BackgroundTask[]>) => setBackground(() => tasks),
  }
}

import type { Panel } from "@opencode/gui-extensions/sdk"

/** The key the host stores a panel tab under. */
export function panelKey(extension: string, id: string) {
  return `${extension}:${id}`
}

/** The stored keys the panels map with `Panel.legacy`, each to the key of the tab it is now. */
export function legacyKeys(providers: readonly { readonly extension: string; readonly value: Panel }[]) {
  return new Map(
    providers.flatMap((item) =>
      Object.entries(item.value.legacy ?? {}).map(([key, id]) => [key, panelKey(item.extension, id)] as const),
    ),
  )
}

import { createMemo, Match, Show, Switch, untrack } from "solid-js"
import type { JSX } from "solid-js"
import { useSortable } from "@dnd-kit/solid/sortable"
import { Icon } from "@opencode/ui/icon"
import { IconButton } from "@opencode/ui/icon-button"
import { Keybind } from "@opencode/ui/keybind"
import { Tooltip } from "@opencode/ui/tooltip"
import { Tabs } from "@opencode/ui/tabs"
import type { MountedSession, PanelTab } from "@opencode/gui-extensions/sdk"
import { useLanguage } from "@/runtime/i18n/language"
import { useCommand } from "@/shell/commands/command"
import { Contribution } from "./render"

/** One side panel tab trigger. The extension supplies the content; the host owns close, drag, and ids. */
export function PanelTrigger(props: {
  value: string
  extension: string
  tab: PanelTab
  session: MountedSession
  index: number
  active: boolean
  preview: boolean
  onClose: (value: string) => void
  onPromote: (value: string) => void
}): JSX.Element {
  const language = useLanguage()
  const command = useCommand()
  const closeKeybind = createMemo(() => command.keybindParts("file.close"))

  // The label renders once per label function; state is read through getters so neither selection nor a session
  // switch remounts it.
  const state = {
    get active() {
      return props.active
    },
    get preview() {
      return props.preview
    },
    get session() {
      return props.session
    },
  }

  const label = createMemo(() => props.tab.label)

  const rendered = createMemo(() => {
    const render = label()

    if (!render) return

    return <Contribution extension={props.extension}>{() => untrack(() => render(state))}</Contribution>
  })

  const content = () => rendered() ?? props.tab.title

  const tooltip = (button: JSX.Element) => (
    <Tooltip
      value={
        <>
          {language.t("common.closeTab")}
          <Show when={closeKeybind().length > 0}>
            <Keybind keys={closeKeybind()} variant="neutral" />
          </Show>
        </>
      }
      placement="bottom"
      gutter={10}
    >
      {button}
    </Tooltip>
  )

  const closeButton = (reveal: boolean) =>
    tooltip(
      <IconButton
        size="small"
        variant="ghost-muted"
        class={reveal ? "hover-reveal relative z-10 group-hover:opacity-100" : undefined}
        classList={reveal ? { "opacity-100": props.active } : undefined}
        onPointerDown={(event) => {
          event.preventDefault()
          event.stopPropagation()
        }}
        onClick={(event) => {
          event.preventDefault()
          event.stopPropagation()
          props.onClose(props.value)
        }}
        icon={<Icon name="xmark-small" />}
        aria-label={language.t("common.closeTab")}
      />,
    )

  const compactClose = () =>
    tooltip(<Tabs.CloseButton onClick={() => props.onClose(props.value)} aria-label={language.t("common.closeTab")} />)

  // The close button `closable` asks for; a plain one by default.
  const close = () => {
    const closable = props.tab.closable

    if (closable === false) return undefined

    if (closable === "compact") return compactClose()

    return closeButton(closable === "hover")
  }

  return (
    <Switch fallback={<SortableTrigger {...props} content={content()} close={close()} />}>
      <Match when={props.tab.pinned}>
        <Tabs.Trigger
          value={props.value}
          id={props.tab.dom?.tab}
          aria-controls={props.active ? props.tab.dom?.panel : undefined}
        >
          {content()}
        </Tabs.Trigger>
      </Match>
      <Match when={props.tab.draggable === false && props.tab.closable === "compact"}>
        <Tabs.Trigger
          value={props.value}
          id={props.tab.dom?.tab}
          onMiddleClick={() => props.onClose(props.value)}
          closeButton={compactClose()}
          hideCloseButton
        >
          {content()}
        </Tabs.Trigger>
      </Match>
      <Match when={props.tab.draggable === false}>
        <Tabs.Trigger
          value={props.value}
          id={props.tab.dom?.tab}
          class="group"
          onMiddleClick={props.tab.closable === false ? undefined : () => props.onClose(props.value)}
          closeButton={close()}
          hideCloseButton
        >
          {content()}
        </Tabs.Trigger>
      </Match>
    </Switch>
  )
}

function SortableTrigger(props: {
  value: string
  tab: PanelTab
  index: number
  active: boolean
  preview: boolean
  content: JSX.Element
  close: JSX.Element | undefined
  onClose: (value: string) => void
  onPromote: (value: string) => void
}): JSX.Element {
  const sortable = useSortable({
    get id() {
      return props.value
    },
    get index() {
      return props.index
    },
  })

  return (
    <div ref={sortable.ref} class="h-full flex items-center">
      <div class="relative">
        <Tabs.Trigger
          value={props.value}
          id={props.tab.dom?.tab}
          aria-controls={props.active ? props.tab.dom?.panel : undefined}
          aria-label={props.tab.missing ? props.tab.title : undefined}
          onMiddleClick={props.tab.closable === false ? undefined : () => props.onClose(props.value)}
          onDblClick={() => {
            if (props.preview) props.onPromote(props.value)
          }}
          closeButton={props.close}
          hideCloseButton
        >
          {props.content}
        </Tabs.Trigger>
      </div>
    </div>
  )
}

import {
  createEffect,
  createMemo,
  For,
  mergeProps,
  on,
  onCleanup,
  onMount,
  Show,
  type Accessor,
  type JSX,
} from "solid-js"
import { createStore } from "solid-js/store"
import { Schema } from "effect"
import { makeEventListener } from "@solid-primitives/event-listener"
import { createMediaQuery } from "@solid-primitives/media"
import { ResizeHandle } from "@opencode/ui/resize-handle"
import {
  SESSION_REVIEW_V2_SIDEBAR_WIDTH_DEFAULT,
  SESSION_REVIEW_V2_SIDEBAR_WIDTH_MAX,
  SESSION_REVIEW_V2_SIDEBAR_WIDTH_MIN,
} from "@opencode/session-ui/v2/session-review-v2"
import {
  Panel,
  PanelContext,
  type PanelFrame,
  type PanelSidebar,
  type PanelTab,
  type MountedSession,
  type SessionScreen,
} from "@opencode/gui-extensions/sdk"
import { same } from "@/runtime/persistence/equality"
import { Persist, persisted } from "@/runtime/persistence/storage"
import { Persistence } from "@/runtime/persistence/schema"
import { createSizing } from "@/session/helpers"
import { useSessionLayout } from "@/session/session-layout"
import { useExtensionHost } from "./host"
import { Contribution } from "./render"
import { useExtensionAttachment } from "./attachment"
import { legacyKeys, panelKey } from "./panel-keys"

type Tabs = Accessor<{
  all(): string[]
  active(): string | undefined
  setAll(all: string[]): void
  setActive(tab: string | undefined): void
  close(tab: string): void
  remap(rewrite: (tab: string) => string): void
}>

export type RegionEntry = {
  readonly key: string
  readonly extension: string
  readonly tab: PanelTab
  readonly provider: Panel
}

const SidebarState = Persistence.struct({
  sidebarOpened: Schema.Boolean,
  sidebarWidth: Schema.Finite.check(
    Schema.isBetween({ minimum: SESSION_REVIEW_V2_SIDEBAR_WIDTH_MIN, maximum: SESSION_REVIEW_V2_SIDEBAR_WIDTH_MAX }),
  ),
  expandMode: Schema.Literals(["expand", "collapse"]),
})

/**
 * The inner sidebar preference every side panel shares. The key predates extensions. `Layout.sidebar` reads it while
 * the session screen that created it is mounted.
 */
export function createPanelSidebar(): PanelSidebar {
  const [store, setStore, , ready] = persisted(Persist.global("review-panel-v2"), SidebarState, {
    sidebarOpened: true,
    sidebarWidth: SESSION_REVIEW_V2_SIDEBAR_WIDTH_DEFAULT,
    expandMode: "collapse",
  })

  const sidebar: PanelSidebar = {
    opened: () => store.sidebarOpened,
    width: () => store.sidebarWidth,
    transition: ready,
    resize: (width) =>
      setStore(
        "sidebarWidth",
        Math.min(SESSION_REVIEW_V2_SIDEBAR_WIDTH_MAX, Math.max(SESSION_REVIEW_V2_SIDEBAR_WIDTH_MIN, width)),
      ),
    toggle: () => setStore("sidebarOpened", (opened) => !opened),
  }

  onCleanup(useExtensionAttachment().sidebar(sidebar))

  return sidebar
}

/**
 * Every panel extensions offer in one region of the routed session, merged with the stored strip. `view` returns the
 * routed session's object, a new one per routed session.
 */
export function createRegion(input: {
  region: Panel["region"]
  view: Accessor<MountedSession>
  screen: SessionScreen
  tabs: Tabs
}) {
  const host = useExtensionHost()
  const stored = () => input.tabs().all()
  const providers = createMemo(() => host.items(Panel).filter((item) => item.value.region === input.region))

  const entries = createMemo(() =>
    providers().flatMap((item) => {
      const prefix = `${item.extension}:`
      const open = stored().flatMap((key) => (key.startsWith(prefix) ? [key.slice(prefix.length)] : []))

      return item.value.list(panelInput(input.view, input.screen, { open })).map(
        (tab): RegionEntry => ({
          key: panelKey(item.extension, tab.id),
          extension: item.extension,
          tab,
          provider: item.value,
        }),
      )
    }),
  )

  const byKey = createMemo(() => new Map(entries().map((entry) => [entry.key, entry])))

  // Rewrites stored keys once their panel is present: keys stored before extensions (e.g. "context") or under an
  // extension's earlier id, and ids a panel writes more than one way. Duplicates collapse, so one file stored two ways
  // is one tab.
  createEffect(() => {
    const legacy = legacyKeys(providers())
    const normalizers = providers().flatMap((item) => (item.value.normalize ? [item] : []))

    if (legacy.size === 0 && normalizers.length === 0) return

    const rewrite = (key: string) => {
      const moved = legacy.get(key)

      if (moved) return moved
      const item = normalizers.find((provider) => key.startsWith(`${provider.extension}:`))

      if (!item?.value.normalize) return key

      return panelKey(
        item.extension,
        item.value.normalize(
          panelInput(input.view, input.screen, {
            id: key.slice(item.extension.length + 1),
          }),
        ),
      )
    }

    // remap reads the stored tabs and writes nothing once every key is canonical, so this settles in one rerun.
    input.tabs().remap(rewrite)
  })

  // Transient panels are not restored: their stored keys leave once the panel stops listing them.
  createEffect(() => {
    const listed = new Set(entries().map((entry) => entry.key))
    const transient = providers().flatMap((item) => (item.value.transient ? [`${item.extension}:`] : []))

    if (transient.length === 0) return
    const all = stored()
    const next = all.filter((key) => listed.has(key) || !transient.some((prefix) => key.startsWith(prefix)))

    if (next.length !== all.length) input.tabs().setAll(next)
  })

  const strip = createMemo(() => {
    const listed = stored().flatMap((key) => {
      const entry = byKey().get(key)

      return entry && !entry.tab.pinned ? [entry] : []
    })

    return [
      ...entries().filter((entry) => entry.tab.pinned),
      ...listed.filter((entry) => entry.tab.first),
      ...listed.filter((entry) => !entry.tab.first),
    ]
  })

  // Narrow screens never select a transient tab: a stored one falls back like a missing tab.
  const desktop = createMediaQuery("(min-width: 768px)")

  const active = createMemo(() => {
    const value = input.tabs().active()

    if (value && strip().some((entry) => entry.key === value && (desktop() || !entry.tab.transient))) return value

    const eligible = strip().filter((entry) => entry.tab.fallback && (desktop() || !entry.tab.transient))

    return [
      ...eligible.filter((entry) => !entry.tab.pinned && !entry.tab.first),
      ...eligible.filter((entry) => !entry.tab.pinned && entry.tab.first),
      ...eligible.filter((entry) => entry.tab.pinned),
    ][0]?.key
  })

  // The effect's own value marks its first run: the selection the region mounts with, stored or fallback.
  createEffect(
    on(active, (key, _, restored: boolean = true) => {
      const entry = key ? byKey().get(key) : undefined

      if (entry)
        entry.provider.focus?.(
          panelInput(input.view, input.screen, {
            tab: entry.tab,
            restored,
          }),
        )

      return false
    }),
  )

  // Hidden tabs keep their place in the strip for selection, focus, and close, but draw no trigger.
  const drawn = createMemo(() => strip().filter((entry) => !entry.tab.hidden))

  return {
    entries,
    /** Drawn strip order by key. Renders iterate keys so a provider's fresh tab objects never remount a trigger. */
    keys: createMemo(() => drawn().map((entry) => entry.key), [], { equals: same }),
    entry: (key: string) => byKey().get(key),
    active,
    selected: createMemo(() => {
      const key = active()

      return key ? byKey().get(key) : undefined
    }),
    wide: createMemo(() => providers().some((item) => item.value.wide)),
    /** An extension's tab ids in the stored strip. */
    openFor: (extension: string) =>
      stored().flatMap((key) => (key.startsWith(`${extension}:`) ? [key.slice(extension.length + 1)] : [])),
    lead: () => !!drawn().find((entry) => !entry.tab.pinned)?.tab.first,
    select(key: string) {
      input.tabs().setActive(key)
    },
    close(key: string) {
      const entry = byKey().get(key)
      input.tabs().close(key)

      if (entry)
        entry.provider.close?.(
          panelInput(input.view, input.screen, {
            tab: entry.tab,
          }),
        )
    },
  }
}

export type Region = ReturnType<typeof createRegion>

/** Grouped content stays mounted while any member is listed; other tabs mount only while selected. */
export function RegionContent(props: {
  region: Region
  view: MountedSession
  screen: SessionScreen
  frame: Omit<PanelFrame, "visible" | "open"> & { shown: Accessor<boolean> }
}) {
  const groups = createMemo(() =>
    Array.from(new Set(props.region.entries().flatMap((entry) => (entry.tab.group ? [groupKey(entry)] : [])))),
  )

  const single = createMemo(() => {
    const entry = props.region.selected()

    return entry && !entry.tab.group ? entry.key : undefined
  })

  return (
    <>
      <For each={groups()}>
        {(group) => {
          const active = () => {
            const entry = props.region.selected()

            return !!entry && groupKey(entry) === group
          }

          // The last selected member keeps rendering while the group is hidden.
          const member = createMemo<RegionEntry | undefined>((previous) => {
            const members = props.region.entries().filter((entry) => groupKey(entry) === group)
            const selected = props.region.selected()

            if (selected && groupKey(selected) === group) return selected

            return members.find((entry) => entry.key === previous?.key) ?? members[0]
          })

          return (
            <Show when={member()?.extension} keyed>
              {(extension) => (
                <div
                  id={member()?.tab.dom?.panel}
                  role="tabpanel"
                  aria-labelledby={active() && !member()?.tab.hidden ? member()?.tab.dom?.tab : undefined}
                  data-slot="tabs-content"
                  class="h-full min-h-0 overflow-hidden"
                  classList={{ hidden: !active() }}
                  inert={!active() || undefined}
                >
                  <PanelContext.Provider
                    value={{
                      ...props.frame,
                      visible: () => props.frame.shown() && active(),
                      open: () => props.region.openFor(extension),
                    }}
                  >
                    <Contribution extension={extension}>
                      {() =>
                        member()!.provider.render(
                          panelInput(() => props.view, props.screen, {
                            get tab() {
                              return member()!.tab
                            },
                          }),
                        )
                      }
                    </Contribution>
                  </PanelContext.Provider>
                </div>
              )}
            </Show>
          )
        }}
      </For>
      <Show when={single()} keyed>
        {(key) => {
          const entry = createMemo(() => props.region.entries().find((item) => item.key === key))

          return (
            <Show when={entry()?.extension} keyed>
              {(extension) => (
                <div
                  id={entry()?.tab.dom?.panel}
                  role="tabpanel"
                  aria-labelledby={entry()?.tab.hidden ? undefined : entry()?.tab.dom?.tab}
                  tabIndex={entry()?.tab.tabbable ? 0 : undefined}
                  data-slot="tabs-content"
                  class="flex flex-col h-full overflow-hidden contain-strict"
                >
                  <PanelContext.Provider
                    value={{ ...props.frame, visible: props.frame.shown, open: () => props.region.openFor(extension) }}
                  >
                    <Contribution extension={extension}>
                      {() =>
                        entry()!.provider.render(
                          panelInput(() => props.view, props.screen, {
                            get tab() {
                              return entry()!.tab
                            },
                          }),
                        )
                      }
                    </Contribution>
                  </PanelContext.Provider>
                </div>
              )}
            </Show>
          )
        }}
      </Show>
    </>
  )
}

function groupKey(entry: RegionEntry) {
  return `${entry.extension}/${entry.tab.group ?? entry.key}`
}

/** Keeps session and tab getters live while the owning screen stays constant. Spreading would snapshot getters. */
function panelInput<T extends object>(view: Accessor<MountedSession>, screen: SessionScreen, fields: T) {
  return mergeProps(
    {
      get session() {
        return view()
      },
      screen,
    },
    fields,
  )
}

/** The dock region: host frame, sizing, and resize around the dock panel an extension renders. */
export function DockRegion(props: {
  view: MountedSession
  screen: SessionScreen
  sidebar: PanelSidebar
  stacked?: boolean
  fill?: boolean
  framed?: boolean
  present?: boolean
  contentHeight?: string
  embedded?: boolean
  animate?: boolean
  reserve?: boolean
}) {
  const host = useExtensionHost()
  const { view } = useSessionLayout()
  const isDesktop = createMediaQuery("(min-width: 768px)")
  const size = createSizing()

  const [store, setStore] = createStore({
    viewport: typeof window === "undefined" ? 1000 : (window.visualViewport?.height ?? window.innerHeight),
  })

  const entry = createMemo(() =>
    host
      .items(Panel)
      .filter((item) => item.value.region === "dock")
      .flatMap((item) =>
        item.value.list(panelInput(() => props.view, props.screen, { open: [] })).map(
          (tab): RegionEntry => ({
            key: panelKey(item.extension, tab.id),
            extension: item.extension,
            tab,
            provider: item.value,
          }),
        ),
      )
      .at(0),
  )

  const opened = createMemo(() => view().dock.opened())
  const height = createMemo(() => view().dock.height())
  const max = () => store.viewport * 0.6
  const regionHeight = () => Math.min(height(), max())
  const stacked = createMemo(() => isDesktop() && !!props.stacked)

  const panelHeight = createMemo(() => {
    if (props.fill) return "100%"

    if (!opened()) return "0px"

    if (isDesktop()) return stacked() ? `${regionHeight()}px` : "100%"

    return `${regionHeight()}px`
  })

  const contentHeight = createMemo(
    () => props.contentHeight ?? (isDesktop() ? (stacked() ? `${regionHeight()}px` : "100%") : `${regionHeight()}px`),
  )

  const present = createMemo(() => opened() || !!props.present)
  let root: HTMLElement | undefined

  onMount(() => {
    const sync = () => setStore("viewport", window.visualViewport?.height ?? window.innerHeight)
    sync()
    makeEventListener(window, "resize", sync)

    if (window.visualViewport) makeEventListener(window.visualViewport, "resize", sync)
  })

  createEffect(() => {
    if (opened()) return
    const active = document.activeElement

    if (!(active instanceof HTMLElement)) return

    if (!root?.contains(active)) return
    active.blur()
  })

  return (
    <aside
      ref={root}
      id="terminal-panel"
      data-component="terminal-panel"
      data-opened={opened()}
      data-size-animated={props.animate !== false && !props.embedded && !size.active() && (!isDesktop() || stacked())}
      role="region"
      aria-label={entry()?.tab.title}
      aria-hidden={!opened()}
      inert={!opened()}
      class="relative shrink-0 overflow-hidden bg-v2-background-bg-base"
      classList={{
        "w-full": !isDesktop() || stacked(),
        "min-w-0 h-full flex-1": isDesktop() && present() && !stacked(),
        "w-0 h-full pointer-events-none": isDesktop() && !present(),
        "rounded-[10px] shadow-[var(--v2-elevation-raised)]": isDesktop() && (props.framed ?? true),
        "will-change-[height]": !props.embedded && !size.active() && (!isDesktop() || stacked()),
      }}
      style={{ height: panelHeight(), "--terminal-panel-height": contentHeight() }}
    >
      <div classList={{ "md:hidden": !stacked(), hidden: stacked() || props.embedded }} onPointerDown={size.start}>
        <ResizeHandle
          class="-top-1"
          direction="vertical"
          size={regionHeight()}
          min={100}
          max={max()}
          collapseThreshold={50}
          onResize={(next) => {
            size.touch()
            view().dock.resize(next)
          }}
          onCollapse={() => view().dock.close()}
        />
      </div>
      <div
        data-slot="terminal-panel-content"
        class="absolute inset-x-0 top-0 flex flex-col overflow-hidden"
        classList={{
          "border-t border-border-weak-base": opened() && !isDesktop() && !props.embedded,
          "pointer-events-none": !opened(),
        }}
        style={{ height: contentHeight() }}
      >
        <Show when={entry()?.extension} keyed>
          {(extension) => (
            <PanelContext.Provider
              value={{
                visible: opened,
                present,
                placement: () => (props.embedded ? "mobile" : stacked() ? "bottom" : "side"),
                reserve: () => !!props.reserve,
                animate: () => !size.active(),
                sidebar: props.sidebar,
                open: () => [],
              }}
            >
              <Contribution extension={extension}>
                {() =>
                  entry()!.provider.render(
                    panelInput(() => props.view, props.screen, {
                      get tab() {
                        return entry()!.tab
                      },
                    }),
                  )
                }
              </Contribution>
            </PanelContext.Provider>
          )}
        </Show>
      </div>
    </aside>
  )
}

/** Renders one panel as a narrow-screen view. */
export function MobilePanel(props: {
  entry: RegionEntry
  view: MountedSession
  screen: SessionScreen
  sidebar: PanelSidebar
  visible: boolean
  open: Accessor<readonly string[]>
}): JSX.Element {
  return (
    <PanelContext.Provider
      value={{
        visible: () => props.visible,
        present: () => props.visible,
        placement: () => "mobile",
        reserve: () => false,
        animate: () => true,
        sidebar: props.sidebar,
        open: props.open,
      }}
    >
      <Contribution extension={props.entry.extension}>
        {() =>
          props.entry.provider.render(
            panelInput(() => props.view, props.screen, {
              get tab() {
                return props.entry.tab
              },
            }),
          )
        }
      </Contribution>
    </PanelContext.Provider>
  )
}

import { createMemo, ErrorBoundary, For, onMount, Show, untrack, type JSX, type ParentProps } from "solid-js"
import { Portal } from "solid-js/web"
import { MarkdownProvider, useMarkdown } from "@opencode/session-ui/context/markdown"
import { ExtensionContext, Slot, Style, type MountedSession, type SlotMap } from "@opencode/gui-extensions/sdk"
import { useExtensionHost } from "./host"

/**
 * Renders one extension contribution with its context and error isolation: a contribution that throws records the
 * error and renders nothing, and the rest of the window keeps working. Contributions never render on timeline rows;
 * the session header slot is per timeline.
 */
export function Contribution(props: { extension: string; children: () => JSX.Element }) {
  const host = useExtensionHost()

  return (
    <Show when={host.context(props.extension)} keyed>
      {(context) => (
        <ErrorBoundary
          fallback={(error) => {
            onMount(() => host.fail(props.extension, error, "render"))

            return null
          }}
        >
          {/* Untracked: a contribution renders once; its own reactivity updates it in place. */}
          <ExtensionContext.Provider value={context}>{untrack(props.children)}</ExtensionContext.Provider>
        </ErrorBoundary>
      )}
    </Show>
  )
}

export function ExtensionSlot<At extends keyof SlotMap>(props: { at: At; input: SlotMap[At] }) {
  const host = useExtensionHost()

  const items = createMemo(() =>
    host
      .items(Slot)
      .filter((item) => item.value.at === props.at)
      .toSorted((a, b) => (a.value.order ?? 0) - (b.value.order ?? 0)),
  )

  return (
    <For each={items()}>
      {(item) => (
        <Contribution extension={item.extension}>
          {() =>
            // SAFETY: items are filtered to `at === props.at`, and a slot's render takes that slot's input.
            (item.value.render as (input: SlotMap[At]) => JSX.Element)(props.input)
          }
        </Contribution>
      )}
    </For>
  )
}

export function ExtensionStyles() {
  const host = useExtensionHost()

  return (
    <Portal mount={document.head}>
      <For each={host.items(Style)}>{(item) => <style data-extension={item.extension}>{item.value}</style>}</For>
    </Portal>
  )
}

/** Routes local markdown links in the session to extension LinkHandler contributions, keeping image loading. */
export function ExtensionLinks(props: ParentProps<{ session: MountedSession }>) {
  const host = useExtensionHost()
  const markdown = useMarkdown()

  return (
    <MarkdownProvider
      readImage={markdown?.readImage}
      openLocalFile={(href) => void host.links.open({ href, session: props.session })}
      // Untracked: markdown calls this inside its render effect, which must not follow the routed session.
      localFileExists={(href) => untrack(() => host.links.exists({ href, session: props.session }))}
    >
      {props.children}
    </MarkdownProvider>
  )
}

import { createMemo, lazy, onCleanup, Show, Suspense, type ParentProps } from "solid-js"
import { extensionEnabled } from "@opencode/gui-extensions/sdk/bridge"
import type { Definition } from "@opencode/gui-extensions/sdk"
import { builtins } from "./builtins"
import { createInstalled } from "./installed"
import { createMenubarItems, MenubarItemsProvider } from "./menubar-items"
import { usePlatform } from "@/runtime/platform/platform"
import { ExtensionHostProvider, useExtensionHost } from "./host"
import { createIpcClients } from "./ipc"
import { createExtensionAttachment, createHostApis, ExtensionAttachmentProvider, type HostApis } from "./host-apis"
import { ExtensionCommands } from "./commands"
import { ExtensionStyles } from "./render"
import { ExtensionServersProvider } from "./servers"
import { ExtensionServerEndpoints } from "./server-shell"
import { createContext, useContext } from "solid-js"

const HostApisContext = createContext<HostApis>()

const ExtensionHotReload = import.meta.env.DEV ? lazy(() => import("./hmr")) : undefined

export function useHostApis() {
  const value = useContext(HostApisContext)

  if (!value) throw new Error("Host APIs are unavailable")

  return value
}

/** Mounts the extension host for the window. Lives above the app interface so extensions can contribute servers. */
export function ExtensionRoot(props: ParentProps) {
  const platform = usePlatform()
  const apis = createHostApis()
  const bridge = platform.extensions
  const menubar = createMenubarItems(bridge)
  const ipcs = createIpcClients(bridge)
  onCleanup(ipcs.dispose)
  const installed = createInstalled(bridge)

  const os = platform.platform === "desktop" ? platform.os : undefined

  // Built-ins only: installed `.ocdx` archives run their main entry until that format ships renderer bundles.
  const definitions = builtins.filter(
    (definition: Definition) => !definition.os || (!!os && definition.os.includes(os)),
  )

  // Only enable preferences cross this boundary; the host derives blocked status from live hard dependencies.
  const disabled = createMemo(() => {
    const state = installed.enableState()

    if (!state) return undefined

    return new Set(definitions.flatMap((definition) => (extensionEnabled(definition, state) ? [] : [definition.id])))
  })

  const failed = (id: string) => installed.list().some((item) => item.id === id && item.error !== undefined)

  return (
    <HostApisContext.Provider value={apis}>
      <ExtensionHostProvider
        definitions={definitions}
        disabled={disabled}
        apis={apis.apis}
        whenMounted={apis.whenMounted}
        ipc={bridge ? (token) => ipcs.client(token) : undefined}
        generation={ipcs.generation}
        failed={failed}
      >
        <ExtensionStyles />
        {ExtensionHotReload && (
          <Suspense>
            <ExtensionHotReload />
          </Suspense>
        )}
        <MenubarItemsProvider value={menubar}>
          <ExtensionServersProvider failed={failed}>{props.children}</ExtensionServersProvider>
        </MenubarItemsProvider>
      </ExtensionHostProvider>
    </HostApisContext.Provider>
  )
}

/** Attaches the session and layout HostApis and publishes extension commands. Renders once extensions are active. */
export function ExtensionAttachment(props: ParentProps) {
  const host = useExtensionHost()
  const attachment = createExtensionAttachment(useHostApis())

  return (
    <ExtensionAttachmentProvider value={attachment}>
      <ExtensionCommands />
      <ExtensionServerEndpoints />
      <Show when={host.ready()}>
        <MountedInterface attach={attachment.attach} />
        {props.children}
      </Show>
    </ExtensionAttachmentProvider>
  )
}

/**
 * The app interface as the HostApis see it, mounted as the routes first render and not before: writes and dialogs made
 * while extensions set up wait until then.
 */
function MountedInterface(props: { attach: () => () => void }) {
  onCleanup(props.attach())

  return null
}

import { createEffect, createMemo, Show, type ParentProps } from "solid-js"
import { usePlatform } from "@/runtime/platform/platform"
import { ServerConnection, useServers } from "@/runtime/server/registry"
import { useCurrentRoute } from "@/shell/state/layout"
import { useTabs } from "@/shell/tabs/tabs"
import { Contribution } from "./render"
import { useExtensionServers } from "./servers"

/**
 * Keeps the routed session or draft mounted and lets its server's extension cover it while the
 * server is not ready.
 */
export function ExtensionServerCover(props: ParentProps) {
  const servers = useExtensionServers()
  const route = useCurrentRoute()
  const tabs = useTabs()

  const covered = createMemo(() => {
    const current = route()

    const key =
      current.type === "session"
        ? current.server
        : current.type === "draft"
          ? tabs.store.find((tab) => tab.type === "draft" && tab.draftID === current.draftID)?.server
          : undefined

    if (!key) return
    const source = servers.entry(key)

    if (!source?.entry.cover || source.entry.state === "ready") return

    return source.key
  })

  const tab = () => {
    const current = route()

    if (current.type === "session") return `${current.server}:${current.sessionId}`

    if (current.type === "draft") return current.draftID

    return ""
  }

  return (
    <div class="relative flex size-full min-h-0 min-w-0 flex-col">
      {/* Keep the route mounted so reconnecting preserves its draft and local UI state. */}
      <div
        class="flex size-full min-h-0 min-w-0 flex-col"
        classList={{ invisible: !!covered() }}
        inert={!!covered()}
        aria-hidden={covered() ? true : undefined}
      >
        {props.children}
      </div>
      <Show when={covered()} keyed>
        {(key) => {
          const source = servers.entry(key)
          const cover = source?.entry.cover

          if (!source || !cover) return null

          return (
            <div class="absolute inset-0">
              <Contribution extension={source.extension}>
                {() =>
                  cover({
                    get tab() {
                      return tab()
                    },
                  })
                }
              </Contribution>
            </div>
          )
        }}
      </Show>
    </div>
  )
}

/** Tells main the server endpoints so main extensions can reach them. */
export function ExtensionServerEndpoints() {
  const servers = useServers()
  const bridge = usePlatform().extensions

  if (bridge) {
    const sent = { value: "" }
    createEffect(() => {
      const endpoints = servers.list.flatMap((conn) => {
        // Main knows the built-in server first-hand; a contributed server has no endpoint until it is ready.
        if (conn.type === "sidecar" || (conn.type === "extension" && conn.state !== "ready")) return []
        const password = conn.http.password

        return [{ id: ServerConnection.key(conn), url: conn.http.url, ...(password ? { password } : {}) }]
      })

      const value = JSON.stringify(endpoints)

      if (value === sent.value) return
      sent.value = value
      bridge.configure(endpoints)
    })
  }

  return null
}

import { createContext, createEffect, createMemo, createSignal, useContext, type ParentProps } from "solid-js"
import { reconcile } from "solid-js/store"
import { Schema } from "effect"
import { MenuItem, Server, type ServerEntry } from "@opencode/gui-extensions/sdk"
import { Persistence } from "@/runtime/persistence/schema"
import { Persist, persisted } from "@/runtime/persistence/storage"
import type { ServerConnection } from "@/runtime/server/registry"
import { useExtensionHost } from "./host"

/** A server an extension contributes. `key` is `${extension}:${entry.id}`. */
export type ExtensionServer = { readonly key: string; readonly extension: string; readonly entry: ServerEntry }

// Endpoint of a contributed server before its extension reports one.
const offline = { url: "http://127.0.0.1:0" }

// The last complete inventory of each extension that contributes servers, without endpoints or credentials.
const Inventories = Schema.Record(
  Schema.String,
  Schema.mutableKey(
    Persistence.struct({
      order: Schema.Finite,
      servers: Persistence.array(
        Persistence.struct({
          id: Schema.String,
          name: Schema.String,
          label: Persistence.optional(Schema.String),
          listed: Persistence.optional(Schema.Boolean),
        }),
      ),
    }),
  ),
)

const ServersContext = createContext<ReturnType<typeof createExtensionServers>>()

export function useExtensionServers() {
  const value = useContext(ServersContext)

  if (!value) throw new Error("Extension servers are unavailable")

  return value
}

/** Collects Server contributions. `failed` reports extensions whose main entry failed, so startup stops waiting for them. */
export function ExtensionServersProvider(props: ParentProps<{ failed: (extension: string) => boolean }>) {
  return (
    <ServersContext.Provider value={createExtensionServers(props.failed)}>{props.children}</ServersContext.Provider>
  )
}

function createExtensionServers(failed: (extension: string) => boolean) {
  const host = useExtensionHost()
  const [known, setKnown, , knownReady] = persisted(Persist.global("extension.servers"), Inventories, {})
  const sources = createMemo(() => host.items(Server).toSorted((a, b) => (a.value.order ?? 0) - (b.value.order ?? 0)))
  // Only a ready source reports its complete inventory. One that reloads, fails or has not started keeps its last
  // inventory as stopped entries, so its servers' tabs, drafts and routes outlive the outage.
  const available = createMemo(() => sources().filter((item) => item.value.ready))
  createEffect(() => {
    if (!knownReady()) return

    for (const item of available()) {
      const inventory = {
        order: item.value.order ?? 0,
        servers: item.value.entries.map((entry) => ({
          id: entry.id,
          name: entry.name,
          label: entry.label,
          listed: entry.listed,
        })),
      }

      if (JSON.stringify(known[item.extension]) !== JSON.stringify(inventory))
        setKnown(item.extension, reconcile(inventory))
    }
  })

  const entries = createMemo(() => {
    const live = available()
    const down = Object.entries(known).filter(([extension]) => !live.some((item) => item.extension === extension))

    return [
      ...live.map((item) => ({ extension: item.extension, order: item.value.order ?? 0, entries: item.value.entries })),
      ...down.map(([extension, inventory]) => ({
        extension,
        order: inventory.order,
        entries: inventory.servers.map((server): ServerEntry => ({ ...server, state: "stopped" })),
      })),
    ]
      .toSorted((a, b) => a.order - b.order)
      .flatMap((group) =>
        group.entries.map(
          (entry): ExtensionServer => ({ key: `${group.extension}:${entry.id}`, extension: group.extension, entry }),
        ),
      )
  })

  // Routes key on the connection object. Keep one per key across entry updates so reconnecting
  // never unmounts an open conversation or composer.
  const connections = new Map<
    string,
    { update: (server: ExtensionServer) => void; value: ServerConnection.Extension }
  >()

  const list = createMemo(() => {
    const listed = entries().filter((item) => item.entry.listed !== false)
    const keys = new Set(listed.map((item) => item.key))
    connections.forEach((_, key) => {
      if (!keys.has(key)) connections.delete(key)
    })

    return listed.map((item) => {
      const existing = connections.get(item.key)

      if (existing) {
        existing.update(item)

        return existing.value
      }

      const created = connection(item)
      connections.set(item.key, created)

      return created.value
    })
  })

  // Startup waits for every source once; a source that reloads later does not hide the app again.
  const ready = createMemo<boolean>(
    (previous) =>
      previous ||
      (knownReady() && host.ready() && sources().every((item) => item.value.ready || failed(item.extension))),
    false,
  )

  return {
    ready,
    /** Contributed servers the app lists, as stable connections. */
    list,
    /**
     * Every contributed server, including those settings lists before they are ready and those of an extension
     * that is down. A server leaves only when its ready extension stops reporting it.
     */
    entries,
    entry: (key: string) => entries().find((item) => item.key === key),
  }
}

function connection(initial: ExtensionServer) {
  const [current, setCurrent] = createSignal(initial)
  const entry = () => current().entry

  const value: ServerConnection.Extension = {
    type: "extension",
    key: initial.key,
    extension: initial.extension,
    get displayName() {
      return entry().name
    },
    get label() {
      return entry().label
    },
    get state() {
      return entry().state
    },
    get connecting() {
      return entry().state === "starting"
    },
    get authenticationRequired() {
      return entry().state === "auth"
    },
    get managed() {
      return !!entry().reconnect
    },
    get http() {
      return entry().http ?? offline
    },
    // Resolved per call: the connection outlives a reload of the extension that provides it.
    get reconnect() {
      if (!entry().reconnect) return undefined

      return (signal: AbortSignal) => entry().reconnect?.(signal) ?? Promise.resolve(entry().http ?? offline)
    },
    connect: () => entry().connect?.() ?? Promise.resolve(entry().state === "ready"),
  }

  return { update: (server: ExtensionServer) => setCurrent(server), value }
}

/** MenuItem "server.row" contributions that apply to a server. */
export function useServerRowItems(server: () => string) {
  const host = useExtensionHost()

  return createMemo(() =>
    host
      .list(MenuItem)
      .flatMap((item) => (item.menu === "server.row" && (item.when?.(server()) ?? true) ? [item] : []))
      .toSorted((a, b) => (a.order ?? 0) - (b.order ?? 0)),
  )
}

/** MenuItem "server.add" contributions, in order. */
export function useServerAddItems() {
  const host = useExtensionHost()

  return createMemo(() =>
    host
      .list(MenuItem)
      .flatMap((item) => (item.menu === "server.add" ? [item] : []))
      .toSorted((a, b) => (a.order ?? 0) - (b.order ?? 0)),
  )
}

import { For, onCleanup, Show } from "solid-js"
import { createStore, reconcile } from "solid-js/store"
import { Button } from "@opencode/ui/button"
import { Switch } from "@opencode/ui/switch"
import type { Installed } from "@opencode/gui-extensions/sdk/bridge"
import { useLanguage } from "@/runtime/i18n/language"
import { usePlatform } from "@/runtime/platform/platform"
import { SettingsList } from "@/settings/list"
import { SettingsRow } from "@/settings/row"
import { useExtensionHost } from "./host"

/** Development builds: every built-in GUI extension of this window, with enable and reload controls. */
export function GuiExtensionsSettings() {
  const language = useLanguage()
  const host = useExtensionHost()
  const bridge = usePlatform().extensions
  const [installed, setInstalled] = createStore<{ list: Installed[] }>({ list: [] })

  if (bridge) {
    void bridge.manager.list().then((list) => setInstalled("list", reconcile([...list])))
    onCleanup(
      bridge.on((message) => {
        if (message.type === "extensions") setInstalled("list", reconcile([...message.list]))
      }),
    )
  }

  const enabled = (id: string) => installed.list.find((item) => item.id === id)?.enabled ?? true

  const status = (id: string) => {
    const value = host.state.status[id] ?? "loading"

    if (value === "active") return language.t("settings.guiExtensions.status.active")

    if (value === "failed") return language.t("settings.guiExtensions.status.failed")

    if (value === "disabled") return language.t("settings.guiExtensions.status.disabled")

    if (value === "blocked") return language.t("settings.guiExtensions.status.blocked")

    return language.t("settings.guiExtensions.status.loading")
  }

  const toggle = (id: string, next: boolean) => void (next ? bridge?.manager.enable(id) : bridge?.manager.disable(id))

  // Main entries reload through the manager; the renderer entry reloads here.
  const reload = (id: string) => {
    host.reload(id)
    void bridge?.manager.reload(id)
  }

  return (
    <>
      <div class="settings-tab-header">
        <div class="settings-tab-header-row">
          <div class="flex flex-col gap-1">
            <h2 class="settings-tab-title">{language.t("settings.guiExtensions.title")}</h2>
            <span class="text-11-regular text-v2-text-text-muted">
              {language.t("settings.guiExtensions.description")}
            </span>
          </div>
        </div>
      </div>
      <div class="settings-tab-body settings-tab-body--sectioned">
        <section class="settings-section" aria-label={language.t("settings.guiExtensions.title")}>
          <SettingsList>
            <For each={host.definitions()}>
              {(definition) => (
                <SettingsRow
                  title={<bdi dir="ltr">{definition.id}</bdi>}
                  description={
                    <>
                      {status(definition.id)}
                      <Show when={host.state.failures[definition.id]?.error}>
                        {(error) => <pre class="mt-1 whitespace-pre-wrap text-text-danger-base">{error()}</pre>}
                      </Show>
                    </>
                  }
                >
                  <div class="flex items-center gap-3">
                    <Button size="small" variant="ghost" onClick={() => reload(definition.id)}>
                      {language.t("settings.guiExtensions.reload")}
                    </Button>
                    <Switch hideLabel checked={enabled(definition.id)} onChange={(next) => toggle(definition.id, next)}>
                      {definition.id}
                    </Switch>
                  </div>
                </SettingsRow>
              )}
            </For>
          </SettingsList>
        </section>
      </div>
    </>
  )
}

import { For } from "solid-js"
import { Tabs } from "@opencode/ui/tabs"
import { useSettingsSurface } from "@/settings/surface"
import { Contribution } from "./render"

/** One settings panel per extension page; the tab value is the SettingsPage id. */
export function ExtensionSettingsPages() {
  const surface = useSettingsSurface()

  return (
    <For each={surface.extensions.pages()}>
      {(item) => (
        <Tabs.Content value={item.value.id} class="settings-panel">
          <Contribution extension={item.extension}>
            {() =>
              item.value.render({
                get target() {
                  const view = surface.view()

                  return view.tab === item.value.id ? view.target : undefined
                },
              })
            }
          </Contribution>
        </Tabs.Content>
      )}
    </For>
  )
}

/**
 * Extension sections on a host settings page, in contribution order; with `section`, the extension rows placed in
 * that host section, rendered where the host lists them.
 */
export function ExtensionSettingsSections(props: { page: "general" | "servers"; section?: "general" }) {
  const surface = useSettingsSurface()

  return (
    <For each={surface.extensions.sections(props.page, props.section)}>
      {(item) => (
        <Contribution extension={item.extension}>
          {() =>
            item.value.render({
              get target() {
                return surface.view().target
              },
            })
          }
        </Contribution>
      )}
    </For>
  )
}

import { createMemo } from "solid-js"
import { createMediaQuery } from "@solid-primitives/media"
import { SettingsPage } from "@opencode/gui-extensions/sdk"
import { usePlatform } from "@/runtime/platform/platform"
import { useExtensionHost } from "./host"

export type SettingsPageItem = ReturnType<ReturnType<typeof createSettingsPages>["items"]>[number]

/** Extension settings pages that apply to this platform and viewport. */
export function createSettingsPages() {
  const host = useExtensionHost()
  const platform = usePlatform()
  const mobile = createMediaQuery("(max-width: 767px)")

  const items = createMemo(() =>
    host.items(SettingsPage).filter((item) => {
      if (item.value.available === "desktop") return platform.platform === "desktop"

      if (item.value.available === "mobile") return mobile()

      return true
    }),
  )

  const pages = createMemo(() => items().filter((item) => !item.value.page))
  const tabs = createMemo<ReadonlySet<string>>(() => new Set(pages().map((item) => item.value.id)))

  return {
    items,
    /** Settings pages without a host page, in contribution order. */
    pages,
    /** Their tab values. */
    tabs,
    /** Sections on a host page, or with `section`, the rows placed in that host section. */
    sections: (page: "general" | "servers", section?: "general") =>
      items().filter((item) => item.value.page === page && item.value.section === section),
  }
}

