      },
    })

    expect(state.session.good).toEqual({
      agent: "build",
      model: { providerID: "provider", modelID: "model", variant: "high" },
      variant: null,
    })
    expect(state.session.partial?.agent).toBe("plan")
    expect(state.session.partial?.model).toBeUndefined()
    expect(state.session.partial?.variant).toBeUndefined()
    expect(state.session.invalid).toBeUndefined()
  })

  test("file views validate scroll positions and line sides independently", () => {
    const decode = Schema.decodeUnknownSync(Persistence.withInitial(FileViewsSchema, { file: {} }))
    expect(decode({})).toEqual({ file: {} })

    const state = decode({
      file: {
        good: {
          scrollTop: 12,
          scrollLeft: 4,
          selectedLines: { start: 9, end: 2, side: "deletions", endSide: "additions" },
        },
        partial: { scrollTop: "12", scrollLeft: 8, selectedLines: { start: 1, end: 3, side: "invalid" } },
        cleared: { selectedLines: null },
        invalid: false,
      },
    })

    expect(state.file.good).toEqual({
      scrollTop: 12,
      scrollLeft: 4,
      selectedLines: { start: 9, end: 2, side: "deletions", endSide: "additions" },
    })
    expect(state.file.partial?.scrollTop).toBeUndefined()
    expect(state.file.partial?.scrollLeft).toBe(8)
    expect(state.file.partial?.selectedLines).toEqual({ start: 1, end: 3 })
    expect(state.file.cleared?.selectedLines).toBeNull()
    expect(state.file.invalid).toEqual({})
  })

  test("language preserves runtime defaults and normalizes unsupported locales to English", () => {
    const decode = Schema.decodeUnknownSync(Persistence.withInitial(languageSchema, { locale: "fr" }))
    expect(decode({})).toEqual({ locale: "fr" })
    expect(decode({ locale: undefined })).toEqual({ locale: "fr" })
    expect(decode({ locale: 42 })).toEqual({ locale: "fr" })
    expect(decode({ locale: "unsupported" })).toEqual({ locale: "en" })
    expect(decode({ locale: "ar" })).toEqual({ locale: "ar" })
  })
})

import { describe, expect, test } from "bun:test"
import { createDraftStore, draftTextChunk, draftTextThreshold, resolveBlobUrl } from "./drafts"

function memoryDriver() {
  const documents = new Map<string, string>()
  const blobs = new Map<string, Blob>()
  let puts = 0

  return {
    documents,
    blobs,
    puts: () => puts,
    driver: {
      get: async (key: string) => documents.get(key) ?? null,
      // Like the real stores: report referenced blobs that are not held; a strict write with any
      // missing is refused.
      set: async (key: string, value: string, strict: boolean) => {
        const ids = new Set<string>()
        JSON.parse(value, (_key, item) => {
          if (item?.blob && typeof item.blob.id === "string") ids.add(item.blob.id)

          if (item?.blob && Array.isArray(item.blob.ids)) item.blob.ids.forEach((id: unknown) => ids.add(String(id)))

          return item
        })
        const missing = [...ids].filter((id) => !blobs.has(id))

        if (!strict || missing.length === 0) documents.set(key, value)

        return missing
      },
      remove: async (key: string) => void documents.delete(key),
      putBlob: async (blob: Blob) => {
        puts++
        const id = `blob-${await blob.text().then((text) => Bun.hash(text).toString(16))}`
        blobs.set(id, blob)

        return id
      },
      getBlob: async (id: string) => blobs.get(id) ?? null,
    },
  }
}

const large = "x".repeat(draftTextThreshold)

const paste = Array.from({ length: 3 * draftTextChunk }, (_, i) => String.fromCharCode(97 + (i % 26))).join("")

describe("draft store text externalization", () => {
  test("large strings become chunk lists and small ones stay inline", async () => {
    const memory = memoryDriver()
    const store = createDraftStore(memory.driver)
    await store.setDocument("doc", {
      prompt: [
        { type: "text", content: paste },
        { type: "text", content: "hi" },
      ],
    })
    const stored = JSON.parse(memory.documents.get("doc")!)
    expect(stored.prompt[0].content.blob.kind).toBe("text")
    expect(stored.prompt[0].content.blob.ids).toHaveLength(3)
    expect(stored.prompt[1].content).toBe("hi")
    expect(memory.documents.get("doc")!.length).toBeLessThan(400)

    const chunks = await Promise.all(
      stored.prompt[0].content.blob.ids.map((id: string) => memory.blobs.get(id)!.text()),
    )

    expect(chunks.join("")).toBe(paste)
    await store.setItem("serialized", JSON.stringify({ prompt: [{ type: "text", content: large }] }))
    expect(JSON.parse(memory.documents.get("serialized")!).prompt[0].content.blob.ids).toHaveLength(1)
  })

  test("appending to a large string re-uploads only the final chunk", async () => {
    const memory = memoryDriver()
    const store = createDraftStore(memory.driver)
    await store.setDocument("doc", { prompt: [{ type: "text", content: paste }] })
    expect(memory.puts()).toBe(3)
    await store.setDocument("doc", { prompt: [{ type: "text", content: `${paste}!` }] })
    expect(memory.puts()).toBe(4)
    await store.setDocument("doc", { prompt: [{ type: "text", content: `${paste}!` }], cursor: 1 })
    expect(memory.puts()).toBe(4)
  })

  test("reads join the chunks again and reuse cached content", async () => {
    const memory = memoryDriver()
    const store = createDraftStore(memory.driver)
    await store.setDocument("doc", { prompt: [{ type: "text", content: paste }] })
    const fresh = createDraftStore(memory.driver)
    expect(JSON.parse((await fresh.getItem("doc"))!)).toEqual({ prompt: [{ type: "text", content: paste }] })
    memory.blobs.clear()
    expect(JSON.parse((await fresh.getItem("doc"))!)).toEqual({ prompt: [{ type: "text", content: paste }] })
  })

  test("a missing chunk decodes to empty text instead of failing the document", async () => {
    const memory = memoryDriver()
    memory.documents.set(
      "doc",
      JSON.stringify({ prompt: [{ type: "text", content: { blob: { kind: "text", ids: ["gone"] } } }] }),
    )
    const store = createDraftStore(memory.driver)
    expect(JSON.parse((await store.getItem("doc"))!)).toEqual({ prompt: [{ type: "text", content: "" }] })
  })

  test("a cached chunk id the store no longer holds is uploaded again on the next save", async () => {
    const memory = memoryDriver()
    const store = createDraftStore(memory.driver)
    await store.setDocument("doc", { prompt: [{ type: "text", content: large }] })
    const [id] = JSON.parse(memory.documents.get("doc")!).prompt[0].content.blob.ids
    await store.setDocument("doc", { prompt: [{ type: "text", content: `${large}!` }] })
    // Another tab collected the chunk for `large` while this tab still caches its id.
    memory.blobs.clear()
    // Undo republishes the cached id; the write reports it missing and the chunk is uploaded again.
    await store.setDocument("doc", { prompt: [{ type: "text", content: large }] })
    expect(memory.puts()).toBe(3)
    const fresh = createDraftStore(memory.driver)
    expect(JSON.parse((await fresh.getItem("doc"))!).prompt[0].content).toBe(large)
    expect(memory.blobs.has(id)).toBe(true)
  })

  test("an image reference whose blob was collected is restored from its object url", async () => {
    const memory = memoryDriver()
    const store = createDraftStore(memory.driver)
    const image = await store.putBlob(new Blob([new Uint8Array([1, 2, 3])], { type: "image/png" }))
    // The composer kept this reference (for example in its history) while the store collected the bytes.
    memory.blobs.clear()
    await store.setDocument("doc", { prompt: [{ type: "image", blob: { id: image.id, url: image.url } }] })
    expect(memory.blobs.has(image.id)).toBe(true)
    expect(new Uint8Array(await memory.blobs.get(image.id)!.arrayBuffer())).toEqual(new Uint8Array([1, 2, 3]))
  })

  test("the previous document stays visible until missing blobs are restored", async () => {
    const memory = memoryDriver()
    const store = createDraftStore(memory.driver)
    await store.setDocument("doc", { prompt: [{ type: "text", content: large }] })
    await store.setDocument("doc", { prompt: [{ type: "text", content: `${large}!` }] })
    const before = memory.documents.get("doc")
    memory.blobs.clear()
    // Hold the repair upload: while it is pending, another reader must still see the old document.
    const gate = Promise.withResolvers<void>()
    const putBlob = memory.driver.putBlob
    memory.driver.putBlob = async (blob) => {
      await gate.promise

      return putBlob(blob)
    }

    const saving = store.setDocument("doc", { prompt: [{ type: "text", content: large }] })
    await new Promise((resolve) => setTimeout(resolve, 0))
    expect(memory.documents.get("doc")).toBe(before)
    gate.resolve()
    await saving
    expect(JSON.parse(memory.documents.get("doc")!).prompt[0].content.blob.ids).toHaveLength(1)
    const fresh = createDraftStore(memory.driver)
    expect(JSON.parse((await fresh.getItem("doc"))!).prompt[0].content).toBe(large)
  })

  test("references are renamed when a restored blob comes back under a different id", async () => {
    const memory = memoryDriver()
    // A store without WebCrypto assigns a fresh id to every upload.
    let counter = 0
    memory.driver.putBlob = async (blob) => {
      const id = `random-${counter++}`
      memory.blobs.set(id, blob)

      return id
    }

    const store = createDraftStore(memory.driver)
    const image = await store.putBlob(new Blob([new Uint8Array([7])], { type: "image/png" }))
    await store.setDocument("doc", {
      prompt: [
        { type: "text", content: paste },
        { type: "image", blob: image },
      ],
    })
    const original = JSON.parse(memory.documents.get("doc")!)
    memory.blobs.clear()
    await store.setDocument("doc", {
      prompt: [
        { type: "text", content: paste },
        { type: "image", blob: image },
      ],
    })
    const restored = JSON.parse(memory.documents.get("doc")!)
    expect(restored.prompt[0].content.blob.ids).not.toEqual(original.prompt[0].content.blob.ids)
    expect(restored.prompt[1].blob.id).not.toBe(original.prompt[1].blob.id)

    for (const id of [...restored.prompt[0].content.blob.ids, restored.prompt[1].blob.id])
      expect(memory.blobs.has(id)).toBe(true)
    const fresh = createDraftStore(memory.driver)
    const read = JSON.parse((await fresh.getItem("doc"))!)
    expect(read.prompt[0].content).toBe(paste)
    expect(read.prompt[1].blob.id).toBe(restored.prompt[1].blob.id)
    // The renamed ids are what later encodes publish, so saves of the still-live references (the
    // composer keeps the original image id) upload nothing and keep one stable image id.
    const puts = counter

    for (const cursor of [1, 2, 3]) {
      await store.setDocument("doc", {
        prompt: [
          { type: "text", content: paste },
          { type: "image", blob: image },
        ],
        cursor,
      })
      expect(JSON.parse(memory.documents.get("doc")!).prompt[1].blob.id).toBe(restored.prompt[1].blob.id)
    }

    expect(counter).toBe(puts)
  })

  test("chunk boundaries never split a surrogate pair", async () => {
    const memory = memoryDriver()
    const store = createDraftStore(memory.driver)
    const text = "x".repeat(draftTextChunk - 1) + "😀tail"
    await store.setDocument("doc", { prompt: [{ type: "text", content: text }] })
    const stored = JSON.parse(memory.documents.get("doc")!)
    const bytes = await Promise.all(stored.prompt[0].content.blob.ids.map((id: string) => memory.blobs.get(id)!.text()))
    expect(bytes.join("")).toBe(text)
    expect(bytes[0]!.length).toBe(draftTextChunk + 1)
    const fresh = createDraftStore(memory.driver)
    expect(JSON.parse((await fresh.getItem("doc"))!).prompt[0].content).toBe(text)
  })

  test("a failed chunk upload is retried on the next save instead of being reused", async () => {
    const memory = memoryDriver()
    let failNext = true
    const putBlob = memory.driver.putBlob
    memory.driver.putBlob = async (blob) => {
      if (failNext) {
        failNext = false
        throw new Error("offline")
      }

      return putBlob(blob)
    }

    const store = createDraftStore(memory.driver)
    await expect(store.setDocument("doc", { prompt: [{ type: "text", content: paste }] })).rejects.toThrow("offline")
    await store.setDocument("doc", { prompt: [{ type: "text", content: `${paste}!` }] })
    const fresh = createDraftStore(memory.driver)
    expect(JSON.parse((await fresh.getItem("doc"))!).prompt[0].content).toBe(`${paste}!`)
  })
})

describe("draft store image retention", () => {
  const image = (byte: number) => new Blob([new Uint8Array(6).fill(byte)], { type: "image/png" })

  const fresh = (grace = 0) => {
    const memory = memoryDriver()

    return { memory, store: createDraftStore(memory.driver, { grace }) }
  }

  // Release timers fire on the macrotask queue; a zero grace has fired after one tick.
  const tick = () => new Promise((resolve) => setTimeout(resolve, 5))

  // An image with no object URL left gets a new one when its bytes are uploaded again.
  const released = async (store: ReturnType<typeof createDraftStore>, byte: number, url: string) =>
    (await store.putBlob(image(byte))).url !== url

  test("an uploaded image no document references is released after the grace", async () => {
    const { store } = fresh()
    const orphan = await store.putBlob(image(1))
    await tick()
    expect(await released(store, 1, orphan.url)).toBe(true)
  })

  test("an image referenced within the grace is kept", async () => {
    const { store } = fresh(50)
    const pasted = await store.putBlob(image(2))
    await store.setDocument("pinned", { prompt: [{ type: "image", blob: pasted }] })
    await new Promise((resolve) => setTimeout(resolve, 80))
    expect(await released(store, 2, pasted.url)).toBe(false)
  })

  test("saving a document without an image or removing the document releases it", async () => {
    const { store } = fresh()
    const dropped = await store.putBlob(image(3))
    const removed = await store.putBlob(image(4))
    await store.setDocument("edited", { prompt: [{ type: "image", blob: dropped }] })
    await store.setDocument("closed", { prompt: [{ type: "image", blob: removed }] })
    await tick()
    expect(await released(store, 3, dropped.url)).toBe(false)
    expect(await released(store, 4, removed.url)).toBe(false)
    await store.setDocument("edited", { prompt: [{ type: "text", content: "typed over it" }] })
    await store.removeItem("closed")
    await tick()
    expect(await released(store, 3, dropped.url)).toBe(true)
    expect(await released(store, 4, removed.url)).toBe(true)
  })

  test("an image referenced by two documents survives until both drop it", async () => {
    const { store } = fresh()
    const shared = await store.putBlob(image(5))
    await store.setDocument("composer", { prompt: [{ type: "image", blob: shared }] })
    await store.setDocument("history", { entries: [{ prompt: [{ type: "image", blob: shared }] }] })
    await store.setDocument("composer", { prompt: [] })
    await tick()
    expect(await released(store, 5, shared.url)).toBe(false)
    await store.setDocument("history", { entries: [] })
    await tick()
    expect(await released(store, 5, shared.url)).toBe(true)
  })

  test("loading a document pins the images it references without fetching their bytes", async () => {
    const { memory, store } = fresh()
    const reads: string[] = []
    const getBlob = memory.driver.getBlob
    memory.driver.getBlob = (id) => {
      reads.push(id)

      return getBlob(id)
    }

    const id = await memory.driver.putBlob(image(6))
    memory.documents.set("loaded", JSON.stringify({ prompt: [{ type: "image", blob: { id } }] }))
    const loaded = JSON.parse((await store.getItem("loaded"))!).prompt[0].blob
    expect(loaded).toEqual({ id })
    expect(reads).toEqual([])
    // The first consumer that shows or sends the image loads it; the pin from the load keeps it.
    const url = (await resolveBlobUrl(loaded))!
    expect(url.startsWith("blob:")).toBe(true)
    expect(reads).toEqual([id])
    expect(await resolveBlobUrl(loaded)).toBe(url)
    expect(reads).toEqual([id])
    await tick()
    expect(await released(store, 6, url)).toBe(false)
    await store.removeItem("loaded")
    await tick()
    expect(await released(store, 6, url)).toBe(true)
  })

  test("a reference to bytes the store no longer holds resolves to nothing", async () => {
    fresh()
    expect(await resolveBlobUrl({ id: "gone" })).toBeUndefined()
  })
})

import type { AsyncStorage } from "@solid-primitives/storage"
import { Option, Schema } from "effect"

export type BlobReference = { id: string; url: string }

type Driver = {
  get(key: string): Promise<string | null>
  /**
   * Store the document and report every blob id it references that the store does not hold. A
   * strict write is refused (nothing stored) when any are missing, so a document is never visible
   * with dangling references while its blobs are being restored.
   */
  set(key: string, value: string, strict: boolean): Promise<readonly string[]>
  remove(key: string): Promise<void>
  putBlob(blob: Blob): Promise<string>
  getBlob(id: string): Promise<Blob | null>
}

export type DraftStore = AsyncStorage & {
  putBlob(blob: Blob): Promise<BlobReference>
  /** Persist an already-encoded document without re-parsing its serialized form. */
  setDocument(key: string, document: unknown): Promise<void>
}

// Strings at least this long leave the document as fixed-size content-addressed chunks. Typing
// after a large paste changes only the final chunk, so a save uploads one chunk, not the paste.
export const draftTextThreshold = 16 * 1024

export const draftTextChunk = 64 * 1024

const textCacheLimit = 64

// Decoded image bytes the renderer pins through object URLs. Every consumer of a `blob.url` is a
// persisted draft document (composer prompt, prompt history), so an image is pinned exactly while a
// stored document references it. Once the last reference disappears (removed from a draft, sent, or
// a discarded duplicate paste) the URL is revoked after this grace, which covers the persist delay
// between a paste and the save that references it, and the submit → history handoff.
export const retainedBlobGrace = 30_000

type Retained = { blob: Blob; url: string; release: ReturnType<typeof setTimeout> | undefined }

const retained = new Map<string, Retained>()

// Document keys that reference each image id; an id with no keys is released after the grace.
const refs = new Map<string, Set<string>>()

// Image ids that were restored under a different id (a store without WebCrypto assigns fresh
// ones); live references still carry the original.
const aliases = new Map<string, string>()

// Fetches image bytes from the store created last. Documents load without their bytes; a consumer
// that renders or sends an image resolves its URL through here, so a history full of large
// attachments costs nothing at startup.
let loader: ((id: string) => Promise<string | undefined>) | undefined

/** The object URL for an image reference, loading its bytes from the draft store on first use. */
export function resolveBlobUrl(blob: { id: string; url?: string }) {
  if (blob.url) return Promise.resolve(blob.url)
  const existing = retained.get(aliases.get(blob.id) ?? blob.id)

  if (existing) return Promise.resolve(existing.url)

  return loader?.(blob.id) ?? Promise.resolve(undefined)
}

function blobUrl(id: string, blob: Blob, grace?: number) {
  const existing = retained.get(id)

  if (existing) return existing.url
  const url = URL.createObjectURL(blob)
  // Without a grace the image has no store to reference it from and stays for the page's lifetime.
  const release = grace === undefined || refs.get(id)?.size ? undefined : setTimeout(() => revoke(id), grace)
  retained.set(id, { blob, url, release })

  return url
}

// Record which image ids `key` now references; ids it dropped are released once no other document
// references them, ids it gained stay pinned.
function retain(key: string, ids: ReadonlySet<string>, grace: number) {
  for (const [id, keys] of refs) {
    if (ids.has(id) || !keys.delete(key) || keys.size) continue
    refs.delete(id)
    const entry = retained.get(id)

    if (entry) entry.release = setTimeout(() => revoke(id), grace)
  }

  for (const id of ids) {
    const keys = refs.get(id) ?? new Set<string>()
    keys.add(key)
    refs.set(id, keys)
    const entry = retained.get(id)

    if (!entry) continue
    clearTimeout(entry.release)
    entry.release = undefined
  }
}

function revoke(id: string) {
  const entry = retained.get(id)

  if (!entry) return
  URL.revokeObjectURL(entry.url)
  retained.delete(id)

  for (const [from, to] of aliases) if (to === id) aliases.delete(from)
}

// Image ids a document references: `{ blob: { id } }` parts, not text chunk lists.
function imageIDs(value: unknown, into = new Set<string>()): Set<string> {
  if (Array.isArray(value)) {
    value.forEach((entry) => imageIDs(entry, into))

    return into
  }

  if (!value || typeof value !== "object") return into
  const item = value as Record<string, unknown>
  const blob = item.blob

  if (blob && typeof blob === "object" && !("kind" in blob)) {
    const id = (blob as Record<string, unknown>).id

    if (typeof id === "string") into.add(id)

    return into
  }

  Object.values(item).forEach((entry) => imageIDs(entry, into))

  return into
}

async function blobID(blob: Blob) {
  const bytes = crypto.subtle
    ? new Uint8Array(await crypto.subtle.digest("SHA-256", await blob.arrayBuffer()))
    : crypto.getRandomValues(new Uint8Array(16))

  const id = Array.from(bytes)
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("")

  return id
}

export async function createBlobReference(blob: Blob): Promise<BlobReference> {
  const id = await blobID(blob)

  return { id, url: blobUrl(id, blob) }
}

export function createDraftStore(driver: Driver, options: { grace?: number } = {}): DraftStore {
  const grace = options.grace ?? retainedBlobGrace
  const versions = new Map<string, number>()
  const loading = new Map<string, Promise<string | undefined>>()

  const loadBlobUrl = (id: string) => {
    const existing = retained.get(id)

    if (existing) return Promise.resolve(existing.url)
    const pending = loading.get(id)

    if (pending) return pending

    const next = driver
      .getBlob(id)
      .then((blob) => (blob ? blobUrl(id, blob, grace) : undefined))
      .finally(() => loading.delete(id))

    loading.set(id, next)

    return next
  }

  loader = loadBlobUrl

  const putBlob = async (blob: Blob) => {
    const id = await driver.putBlob(blob)

    return { id, url: blobUrl(id, blob, grace) }
  }

  // Keyed by chunk content so unchanged chunks are never hashed or sent again while the draft is
  // edited. Bounded because each entry pins up to draftTextChunk characters. A hit is safe even if
  // the store has since collected the blob: the write reports it missing and it is uploaded again.
  const chunkIds = new Map<string, Promise<string>>()
  const chunks = new Map<string, string>()

  const remember = <V>(cache: Map<string, V>, key: string, value: V) => {
    cache.set(key, value)

    if (cache.size > textCacheLimit) cache.delete(cache.keys().next().value!)

    return value
  }

  const upload = (chunk: string) => {
    const id = driver.putBlob(new Blob([chunk])).then(
      (id) => {
        remember(chunks, id, chunk)

        return id
      },
      (error: unknown) => {
        // A failed upload must not be reused as the answer for this content on later saves.
        if (chunkIds.get(chunk) === id) chunkIds.delete(chunk)
        throw error
      },
    )

    return remember(chunkIds, chunk, id)
  }

  const externalize = (text: string) => Promise.all(split(text).map((chunk) => chunkIds.get(chunk) ?? upload(chunk)))

  const loadChunk = async (id: string) => {
    const cached = chunks.get(id)

    if (cached !== undefined) return cached
    const blob = await driver.getBlob(id)

    // A missing chunk loses that text but keeps the rest of the document decodable.
    return remember(chunks, id, blob ? await blob.text() : "")
  }

  // `sources` collects, for every blob id the encoded document references, a way to produce its
  // bytes again: the chunk text itself, or the image Blob (or object URL) the reference carries.
  type Sources = Map<string, { blob: () => Promise<Blob>; chunk?: string }>

  const encode = async (value: unknown, sources: Sources): Promise<unknown> => {
    if (typeof value === "string" && value.length >= draftTextThreshold) {
      const pieces = split(value)
      const ids = await externalize(value)
      ids.forEach((id, index) =>
        sources.set(id, { blob: async () => new Blob([pieces[index]!]), chunk: pieces[index] }),
      )

      return { blob: { kind: "text", ids } }
    }

    if (Array.isArray(value)) return Promise.all(value.map((entry) => encode(entry, sources)))

    if (!value || typeof value !== "object") return value
    const item = value as Record<string, unknown>

    if (item.type === "image" && typeof item.dataUrl === "string") {
      const blob = await fetch(item.dataUrl).then((response) => response.blob())
      const { dataUrl: _, ...rest } = item
      const id = await driver.putBlob(blob)
      sources.set(id, { blob: async () => blob })

      return { ...rest, blob: { id } }
    }

    if ("blob" in item && item.blob && typeof item.blob === "object") {
      const blob = item.blob as Record<string, unknown>

      if (blob.kind === "text") return item

      if (typeof blob.id === "string" && blob.id.startsWith("data:")) {
        const data = await fetch(blob.id).then((response) => response.blob())
        const id = await driver.putBlob(data)
        sources.set(id, { blob: async () => data })

        return { ...item, blob: { id } }
      }

      if (typeof blob.id === "string") {
        // A live reference keeps the id it was created with; publish the id its bytes now live under.
        const id = aliases.get(blob.id) ?? blob.id
        const kept = retained.get(id)?.blob
        const url = typeof blob.url === "string" ? blob.url : retained.get(id)?.url

        if (kept) sources.set(id, { blob: async () => kept })
        else if (url) sources.set(id, { blob: () => fetch(url).then((response) => response.blob()) })

        return { ...item, blob: { id } }
      }

      return { ...item, blob: { id: blob.id } }
    }

    return Object.fromEntries(
      await Promise.all(Object.entries(item).map(async ([key, entry]) => [key, await encode(entry, sources)])),
    )
  }

  const decode = async (value: unknown): Promise<unknown> => {
    if (Array.isArray(value)) return Promise.all(value.map(decode))

    if (!value || typeof value !== "object") return value
    const item = value as Record<string, unknown>

    if (item.blob && typeof item.blob === "object") {
      const ref = item.blob as Record<string, unknown>

      if (ref.kind === "text" && Array.isArray(ref.ids)) {
        return (await Promise.all(ref.ids.map((id) => loadChunk(String(id))))).join("")
      }

      // Bytes stay in the store until something renders or sends the image (see resolveBlobUrl);
      // only an image already pinned in this page gets its URL back immediately.
      if (typeof ref.id === "string") {
        const url = retained.get(aliases.get(ref.id) ?? ref.id)?.url

        return { ...item, blob: url ? { id: ref.id, url } : { id: ref.id } }
      }
    }

    return Object.fromEntries(
      await Promise.all(Object.entries(item).map(async ([key, entry]) => [key, await decode(entry)])),
    )
  }

  // Upload the bytes behind `ids` again and return the ids they were stored under. Ids are
  // usually content hashes and come back unchanged, but a store without WebCrypto assigns fresh
  // ones, so callers must rename references rather than assume.
  const restore = async (ids: readonly string[], sources: Sources) => {
    const renamed = new Map<string, string>()
    await Promise.all(
      ids.map(async (id) => {
        const source = sources.get(id)

        if (!source) return
        const blob = await source.blob()
        const next = await driver.putBlob(blob)
        renamed.set(id, next)

        if (source.chunk !== undefined) {
          remember(chunkIds, source.chunk, Promise.resolve(next))
          remember(chunks, next, source.chunk)

          return
        }

        blobUrl(next, blob, grace)

        if (next === id) return

        // Later encodes of the still-live reference resolve straight to the new id. Re-point any
        // earlier alias chain so lookups stay one step.
        for (const [from, to] of aliases) if (to === id) aliases.set(from, next)
        aliases.set(id, next)
      }),
    )

    return renamed
  }

  const rename = (value: unknown, renamed: Map<string, string>): unknown => {
    if (Array.isArray(value)) return value.map((entry) => rename(entry, renamed))

    if (!value || typeof value !== "object") return value
    const item = value as Record<string, unknown>

    if (item.blob && typeof item.blob === "object") {
      const ref = item.blob as Record<string, unknown>

      if (Array.isArray(ref.ids))
        return { ...item, blob: { ...ref, ids: ref.ids.map((id) => renamed.get(String(id)) ?? id) } }

      if (typeof ref.id === "string") return { ...item, blob: { ...ref, id: renamed.get(ref.id) ?? ref.id } }
    }

    return Object.fromEntries(Object.entries(item).map(([key, entry]) => [key, rename(entry, renamed)]))
  }

  const setDocument = async (key: string, document: unknown) => {
    const version = (versions.get(key) ?? 0) + 1
    versions.set(key, version)
    const sources: Sources = new Map()
    const encoded = await encode(document, sources)

    if (versions.get(key) !== version) return
    // The store refuses the write while any referenced blob is missing, so the previous document
    // stays visible until the bytes are back. Covers a blob collected while a cache, another tab,
    // or the composer's history still held its id.
    const missing = await driver.set(key, JSON.stringify(encoded), true)

    if (missing.length === 0) {
      retain(key, imageIDs(encoded), grace)

      return
    }

    const renamed = await restore(missing, sources)

    if (versions.get(key) !== version) return
    const unrestored = missing.filter((id) => !renamed.has(id))

    if (unrestored.length)
      console.error(`[persistence] draft ${key} references blobs with no bytes to restore`, unrestored)
    // Anything still missing has no bytes anywhere; the owning codec drops such references on read.
    const final = rename(encoded, renamed)
    await driver.set(key, JSON.stringify(final), false)
    retain(key, imageIDs(final), grace)
  }

  return {
    getItem: async (key) => {
      const value = await driver.get(key)

      if (value === null) return null
      const parsed = Schema.decodeUnknownOption(Schema.fromJsonString(Schema.Unknown))(value)

      // Let the owning persistence codec apply its invalid-document policy.
      if (Option.isNone(parsed)) return value
      // A loaded document is live in the composer: pin its images before decode mints their URLs.
      retain(key, imageIDs(parsed.value), grace)

      return JSON.stringify(await decode(parsed.value))
    },
    setItem: (key, value) => setDocument(key, JSON.parse(value)),
    setDocument,
    removeItem: async (key) => {
      versions.set(key, (versions.get(key) ?? 0) + 1)
      await driver.remove(key)
      retain(key, new Set(), grace)
    },
    putBlob,
  }
}

// Fixed-size pieces, except that a piece never ends between the two halves of a surrogate pair:
// each piece becomes its own Blob, and an unpaired surrogate would be encoded as U+FFFD.
function split(text: string) {
  const pieces: string[] = []

  for (let start = 0; start < text.length; ) {
    const end = Math.min(start + draftTextChunk, text.length)
    const code = text.charCodeAt(end - 1)
    const stop = end < text.length && code >= 0xd800 && code <= 0xdbff ? end + 1 : end
    pieces.push(text.slice(start, stop))
    start = stop
  }

  return pieces
}

export function createBrowserDraftStore(): DraftStore {
  const request = indexedDB.open("opencode-drafts", 1)
  request.addEventListener("upgradeneeded", () => {
    request.result.createObjectStore("documents")
    request.result.createObjectStore("blobs")
  })

  const db = new Promise<IDBDatabase>((resolve, reject) => {
    request.addEventListener("success", () => {
      const database = request.result
      const transaction = database.transaction(["documents", "blobs"], "readwrite")
      const documents = transaction.objectStore("documents").getAll()
      documents.addEventListener("success", () => {
        const used = referenced(`[${documents.result.join(",")}]`)
        const store = transaction.objectStore("blobs")
        const blobs = store.openKeyCursor()
        blobs.addEventListener("success", () => {
          const cursor = blobs.result

          if (!cursor) return

          if (!used.has(String(cursor.key))) store.delete(cursor.key)
          cursor.continue()
        })
      })
      transaction.addEventListener("complete", () => resolve(database))
      transaction.addEventListener("abort", () => resolve(database))
    })
    request.addEventListener("error", () => reject(request.error))
  })

  const get = async (store: string, key: string) => {
    const result = (await db).transaction(store).objectStore(store).get(key)

    return new Promise<unknown>((resolve, reject) => {
      result.addEventListener("success", () => resolve(result.result))
      result.addEventListener("error", () => reject(result.error))
    })
  }

  const write = async (store: string, key: string, value?: unknown) => {
    const transaction = (await db).transaction(store, "readwrite")

    if (value === undefined) transaction.objectStore(store).delete(key)
    else transaction.objectStore(store).put(value, key)

    return new Promise<void>((resolve, reject) => {
      transaction.addEventListener("complete", () => resolve())
      transaction.addEventListener("error", () => reject(transaction.error))
    })
  }

  return createDraftStore({
    get: async (key) => ((await get("documents", key)) as string | undefined) ?? null,
    set: async (key, value, strict) => {
      // One readwrite transaction over both stores: IndexedDB serialises overlapping readwrite
      // transactions in creation order, so a later save or removal cannot commit between the
      // reference check and this write. The put is issued from the last lookup's callback so the
      // transaction is never left without a pending request.
      const ids = [...referenced(value)]
      const transaction = (await db).transaction(["blobs", "documents"], "readwrite")
      const missing: string[] = []

      const publish = () => {
        if (!strict || missing.length === 0) transaction.objectStore("documents").put(value, key)
      }

      let remaining = ids.length

      if (remaining === 0) publish()

      for (const id of ids) {
        const lookup = transaction.objectStore("blobs").getKey(id)
        lookup.addEventListener("success", () => {
          if (lookup.result === undefined) missing.push(id)

          if (--remaining === 0) publish()
        })
      }

      return new Promise<string[]>((resolve, reject) => {
        transaction.addEventListener("complete", () => resolve(missing))
        transaction.addEventListener("error", () => reject(transaction.error))
        transaction.addEventListener("abort", () => reject(transaction.error))
      })
    },
    remove: (key) => write("documents", key),
    putBlob: async (blob) => {
      const id = await blobID(blob)
      await write("blobs", id, blob)

      return id
    },
    getBlob: async (id) => ((await get("blobs", id)) as Blob | undefined) ?? null,
  })
}

// Every blob id a serialized document (or array of documents) references.
function referenced(json: string) {
  const ids = new Set<string>()
  JSON.parse(json, (_key, item) => {
    if (item?.blob && typeof item.blob.id === "string") ids.add(item.blob.id)

    if (item?.blob && Array.isArray(item.blob.ids)) item.blob.ids.forEach((id: unknown) => ids.add(String(id)))

    return item
  })

  return ids
}

export async function blobDataUrl(blob: BlobReference, mime: string) {
  const kept = retained.get(aliases.get(blob.id) ?? blob.id)
  const url = kept ? undefined : await resolveBlobUrl(blob)

  if (!kept && !url) throw new Error(`Attachment ${blob.id} has no stored bytes`)
  const data = kept ? kept.blob : await fetch(url!).then((response) => response.blob())

  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader()
    reader.addEventListener("error", () => reject(reader.error))
    reader.addEventListener("load", () => {
      const value = typeof reader.result === "string" ? reader.result : ""
      resolve(`data:${mime};base64,${value.slice(value.indexOf(",") + 1)}`)
    })
    reader.readAsDataURL(data)
  })
}

export function createLegacyBlobReference(dataUrl: string): BlobReference {
  return { id: dataUrl, url: dataUrl }
}

export function same<T>(a: readonly T[] | undefined, b: readonly T[] | undefined) {
  if (a === b) return true

  if (!a || !b) return false

  if (a.length !== b.length) return false

  return a.every((x, i) => x === b[i])
}

import { describe, expect, test } from "bun:test"
import { createNamespaceStorage, type NamespaceDriver, type NamespaceStorage } from "./namespace"

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

type Call = { kind: string; name: string; insert?: Record<string, string>; remove?: string[] }

// A host with a monotonic revision. Each update is acked to its caller and recorded as an event
// that the test delivers to other windows whenever it chooses, like the real event stream.
function host(initial: Record<string, Record<string, string>> = {}) {
  const data = new Map(Object.entries(initial).map(([name, items]) => [name, new Map(Object.entries(items))]))
  const calls: Call[] = []
  const events: { name: string; insert: Record<string, string>; remove: string[]; revision: number }[] = []
  let revision = 0
  let fail: (insert: Record<string, string>) => boolean = () => false
  let gate: Promise<void> | undefined

  const driver: NamespaceDriver = {
    items: async (name) => {
      calls.push({ kind: "items", name })

      return { items: Object.fromEntries(data.get(name) ?? []), revision }
    },
    update: async (name, insert, remove) => {
      calls.push({ kind: "update", name, insert, remove })
      await gate

      if (fail(insert)) throw new Error("disk full")
      const items = data.get(name) ?? new Map()

      for (const [key, value] of Object.entries(insert)) items.set(key, value)

      for (const key of remove) items.delete(key)
      data.set(name, items)
      events.push({ name, insert, remove, revision: ++revision })

      return revision
    },
    clear: async (name) => {
      calls.push({ kind: "clear", name })
      data.delete(name)
    },
  }

  return {
    driver,
    data,
    calls,
    events,
    updates: () => calls.filter((call) => call.kind === "update"),
    setFail: (value: boolean | ((insert: Record<string, string>) => boolean)) =>
      (fail = typeof value === "boolean" ? () => value : value),
    setGate: (value: Promise<void> | undefined) => (gate = value),
    deliver: (target: NamespaceStorage, index: number) => {
      const event = events[index]!
      target.accept(event.insert, event.remove, event.revision)
    },
  }
}

describe("namespace storage", () => {
  test("loads the namespace once and serves reads from memory", async () => {
    const h = host({ w: { tabs: "[]", recent: "{}" } })
    const storage = createNamespaceStorage(h.driver, "w", { delay: 10 })
    expect(await storage.getItem("tabs")).toBe("[]")
    expect(await storage.getItem("recent")).toBe("{}")
    expect(await storage.getItem("missing")).toBeNull()
    expect(await storage.getLength()).toBe(2)
    expect(h.calls.filter((call) => call.kind === "items")).toHaveLength(1)
  })

  test("reads its own writes immediately and coalesces them into one update", async () => {
    const h = host()
    const storage = createNamespaceStorage(h.driver, "w", { delay: 10 })
    void storage.setItem("tabs", "[1]")
    void storage.setItem("recent", "{}")
    void storage.setItem("tabs", "[1,2]")
    void storage.removeItem("recent")
    expect(await storage.getItem("tabs")).toBe("[1,2]")
    expect(await storage.getItem("recent")).toBeNull()
    expect(h.updates()).toHaveLength(0)
    await wait(30)
    expect(h.updates()).toEqual([{ kind: "update", name: "w", insert: { tabs: "[1,2]" }, remove: ["recent"] }])
  })

  test("writes made while loading win over the loaded snapshot", async () => {
    const h = host({ w: { tabs: "old" } })
    const storage = createNamespaceStorage(h.driver, "w", { delay: 10 })
    const read = storage.getItem("tabs")
    void storage.setItem("tabs", "new")
    expect(await read).toBe("new")
  })

  test("flush writes now and resolves after the driver accepted the batch", async () => {
    const h = host()
    const storage = createNamespaceStorage(h.driver, "w", { delay: 10_000 })
    void storage.setItem("tabs", "[1]")
    await storage.flush()
    expect(h.data.get("w")?.get("tabs")).toBe("[1]")
    await storage.flush()
    expect(h.updates()).toHaveLength(1)
  })

  test("a failed update keeps unsuperseded changes queued for the next flush", async () => {
    const h = host()
    const storage = createNamespaceStorage(h.driver, "w", { delay: 10_000 })
    h.setFail(true)
    void storage.setItem("tabs", "[1]")
    void storage.setItem("recent", "{}")
    await storage.flush()
    expect(h.data.get("w")).toBeUndefined()
    h.setFail(false)
    void storage.setItem("tabs", "[2]")
    await storage.flush()
    expect(Object.fromEntries(h.data.get("w")!)).toEqual({ tabs: "[2]", recent: "{}" })
  })

  test("a batch is handed to the driver synchronously, not behind an earlier reply", async () => {
    const h = host()
    const first = Promise.withResolvers<void>()
    h.setGate(first.promise)
    const storage = createNamespaceStorage(h.driver, "w", { delay: 10_000 })
    void storage.setItem("tabs", "[1]")
    void storage.flush()
    void storage.setItem("tabs", "[2]")
    void storage.flush()
    // Both batches reached the driver while the first reply is still outstanding.
    expect(h.updates().map((call) => call.insert)).toEqual([{ tabs: "[1]" }, { tabs: "[2]" }])
    first.resolve()
    await storage.flush()
  })

  test("a pending load or an external change cannot overwrite a value that is in flight", async () => {
    const loaded = Promise.withResolvers<{ items: Record<string, string>; revision: number }>()
    const accepted = Promise.withResolvers<number>()

    const driver: NamespaceDriver = {
      items: () => loaded.promise,
      update: () => accepted.promise,
      clear: async () => undefined,
    }

    const storage = createNamespaceStorage(driver, "g", { delay: 10_000 })
    const read = storage.getItem("model")
    void storage.setItem("model", "local")
    void storage.flush()
    storage.accept({ model: "other-window-older" }, [], 1)
    loaded.resolve({ items: { model: "snapshot-older" }, revision: 0 })
    expect(await read).toBe("local")
    accepted.resolve(2)
    await storage.flush()
    expect(await storage.getItem("model")).toBe("local")
    storage.accept({ model: "other-window-newer" }, [], 3)
    expect(await storage.getItem("model")).toBe("other-window-newer")
  })

  test("a failed batch does not requeue a value a later batch already replaced", async () => {
    const h = host()
    const first = Promise.withResolvers<void>()
    h.setGate(first.promise)
    // The first batch (old) is held at the host and will be rejected; the second (new) succeeds.
    h.setFail((insert) => insert.tabs === "old")
    const storage = createNamespaceStorage(h.driver, "w", { delay: 10_000 })
    void storage.setItem("tabs", "old")
    void storage.flush()
    h.setGate(undefined)
    void storage.setItem("tabs", "new")
    void storage.flush()
    await wait(0)
    expect(h.data.get("w")?.get("tabs")).toBe("new")
    first.resolve()
    await storage.flush()
    await storage.flush()
    expect(h.updates().map((call) => call.insert)).toEqual([{ tabs: "old" }, { tabs: "new" }])
    expect(h.data.get("w")?.get("tabs")).toBe("new")
    expect(await storage.getItem("tabs")).toBe("new")
  })

  test("an event that reaches a window after a newer ack for the same key is ignored", async () => {
    const h = host({ g: { model: "start" } })
    const one = createNamespaceStorage(h.driver, "g", { delay: 10_000 })
    const two = createNamespaceStorage(h.driver, "g", { delay: 10_000 })
    await one.getItem("model")
    await two.getItem("model")
    void one.setItem("model", "A")
    await one.flush()
    void two.setItem("model", "B")
    await two.flush()
    // Both writes are acked. Now the event for A, which the host applied before B, reaches two.
    h.deliver(two, 0)
    expect(await two.getItem("model")).toBe("B")
    expect(h.data.get("g")?.get("model")).toBe("B")
    // One still receives B, which is newer than its own ack.
    h.deliver(one, 1)
    expect(await one.getItem("model")).toBe("B")
  })

  test("an event held back during an in-flight write wins after the ack if the host applied it later", async () => {
    const h = host()
    const gate = Promise.withResolvers<void>()
    h.setGate(gate.promise)
    const storage = createNamespaceStorage(h.driver, "g", { delay: 10_000 })
    void storage.setItem("model", "mine")
    void storage.flush()
    // Another window's write for the same key landed at the host after ours will.
    storage.accept({ model: "theirs" }, [], 2)
    expect(await storage.getItem("model")).toBe("mine")
    gate.resolve()
    await storage.flush()
    expect(await storage.getItem("model")).toBe("theirs")
  })

  test("the initial load removes a key an older event inserted while the load was in flight", async () => {
    const loaded = Promise.withResolvers<{ items: Record<string, string>; revision: number }>()
    const driver: NamespaceDriver = { items: () => loaded.promise, update: async () => 0, clear: async () => undefined }
    const storage = createNamespaceStorage(driver, "g", { delay: 10_000 })
    const read = storage.getItem("model")
    // Host history: insert at 41, delete at 42; the snapshot was taken at 42.
    storage.accept({ model: "inserted" }, [], 41)
    loaded.resolve({ items: {}, revision: 42 })
    expect(await read).toBeNull()
    // The delete event is older than the floor and must stay a no-op either way.
    storage.accept({}, ["model"], 42)
    expect(await storage.getItem("model")).toBeNull()
    // A key inserted by an event newer than the snapshot survives the load.
    const second = Promise.withResolvers<{ items: Record<string, string>; revision: number }>()
    const other = createNamespaceStorage({ ...driver, items: () => second.promise }, "g", { delay: 10_000 })
    const pending = other.getItem("model")
    other.accept({ model: "after-snapshot" }, [], 43)
    second.resolve({ items: {}, revision: 42 })
    expect(await pending).toBe("after-snapshot")
  })

  test("an event older than the initial load is ignored", async () => {
    const h = host({ g: { model: "loaded" } })
    void h.driver.update("g", { model: "loaded" }, [])
    await wait(0)
    const storage = createNamespaceStorage(h.driver, "g", { delay: 10_000 })
    await storage.getItem("model")
    storage.accept({ model: "before-load" }, [], 1)
    expect(await storage.getItem("model")).toBe("loaded")
    storage.accept({}, ["model"], 2)
    expect(await storage.getItem("model")).toBeNull()
  })

  test("clear drops the cache and queued changes and clears the driver", async () => {
    const h = host({ w: { tabs: "[]" } })
    const storage = createNamespaceStorage(h.driver, "w", { delay: 10_000 })
    await storage.getItem("tabs")
    void storage.setItem("recent", "{}")
    await storage.clear()
    expect(await storage.getItem("tabs")).toBeNull()
    expect(await storage.getItem("recent")).toBeNull()
    expect(h.calls.map((call) => call.kind)).toEqual(["items", "clear"])
  })
})

import type { AsyncStorage } from "@solid-primitives/storage"

// The host-side store for one namespace: one bulk read, one bulk write. The host stamps every
// update with a monotonic revision and reports it with reads, acks, and change events.
export type NamespaceDriver = {
  items(name: string): Promise<{ items: Record<string, string>; revision: number }>
  update(name: string, insert: Record<string, string>, remove: string[]): Promise<number>
  clear(name: string): Promise<void>
}

export type NamespaceStorage = AsyncStorage & {
  /** Write every queued change now. Resolves when the driver has accepted it. */
  flush(): Promise<void>
  /** Apply a change another window made at `revision`, unless this window already holds something newer. */
  accept(insert: Record<string, string>, remove: string[], revision: number): void
}

export const namespaceFlushDelay = 100

// In-memory truth for a namespace. Reads load the namespace once and are Map lookups from then
// on; writes update the cache immediately and are batched into one driver call per flush window,
// so a burst of setter calls costs one round trip. Mirrors VS Code's Storage class.
//
// Two orderings keep the cache correct. Every local write gets a sequence number that stays
// recorded until the host acks that exact write; while recorded, nothing external may replace
// the key. Every value the cache holds also carries the host revision it came from, so an event
// that reaches this window after a newer ack or load is recognised as stale and dropped. Batches
// are posted as soon as they are cut, never behind an earlier reply, so a flush on pagehide is
// on the wire before the page goes away.
export function createNamespaceStorage(
  driver: NamespaceDriver,
  name: string,
  options: { delay?: number } = {},
): NamespaceStorage {
  const delay = options.delay ?? namespaceFlushDelay
  const cache = new Map<string, string>()
  const local = new Map<string, { seq: number; value: string | null }>()
  const dirty = new Set<string>()
  const inflight = new Set<Promise<void>>()
  // Host revision behind each cached key, and the revision the initial load reflected for all keys.
  const applied = new Map<string, number>()
  let floor = -1
  // The newest external change for a key that arrived while a local write was still in flight.
  const deferred = new Map<string, { revision: number; value: string | null }>()
  let seq = 0
  let loading: Promise<void> | undefined
  let timer: ReturnType<typeof setTimeout> | undefined

  const place = (key: string, value: string | null, revision: number) => {
    if (value === null) cache.delete(key)
    else cache.set(key, value)
    applied.set(key, revision)
  }

  // The snapshot is the whole truth at its revision: a key it lacks was deleted by then, even if
  // an older event inserted it into the cache while the load was in flight.
  const load = () =>
    (loading ??= driver.items(name).then((loaded) => {
      floor = loaded.revision
      const stale = (key: string) => !local.has(key) && (applied.get(key) ?? -1) <= loaded.revision

      for (const key of [...cache.keys()]) {
        if (!(key in loaded.items) && stale(key)) place(key, null, loaded.revision)
      }

      for (const [key, value] of Object.entries(loaded.items)) {
        if (stale(key)) place(key, value, loaded.revision)
      }
    }))

  const write = (key: string, value: string | null) => {
    if (value === null) cache.delete(key)
    else cache.set(key, value)
    local.set(key, { seq: ++seq, value })
    dirty.add(key)
    timer ??= setTimeout(() => void flush(), delay)
  }

  // The host accepted this window's value for `key` at `revision`. A change from another window
  // that was held back meanwhile wins if the host applied it later than ours.
  const acknowledge = (key: string, revision: number) => {
    local.delete(key)
    const later = deferred.get(key)
    deferred.delete(key)

    if (later && later.revision > revision) return place(key, later.value, later.revision)
    applied.set(key, revision)
  }

  const flush = () => {
    clearTimeout(timer)
    timer = undefined

    if (dirty.size > 0) {
      const batch = [...dirty].map((key) => ({ key, ...local.get(key)! }))
      dirty.clear()
      const insert = Object.fromEntries(batch.filter((entry) => entry.value !== null).map((e) => [e.key, e.value!]))
      const remove = batch.filter((entry) => entry.value === null).map((entry) => entry.key)
      const current = (entry: { key: string; seq: number }) => local.get(entry.key)?.seq === entry.seq

      const request = driver
        .update(name, insert, remove)
        .then((revision) => batch.filter(current).forEach((entry) => acknowledge(entry.key, revision)))
        .catch((error: unknown) => {
          // Only a value nothing newer has replaced is worth retrying.
          batch.filter(current).forEach((entry) => dirty.add(entry.key))
          console.error(`[persistence] flush failed for ${name}`, error)
        })
        .finally(() => inflight.delete(request))

      inflight.add(request)
    }

    return Promise.all(inflight).then(() => undefined)
  }

  const storage: NamespaceStorage = {
    getItem: async (key) => {
      await load()

      return cache.get(key) ?? null
    },
    setItem: async (key, value) => write(key, value),
    removeItem: async (key) => write(key, null),
    clear: async () => {
      clearTimeout(timer)
      timer = undefined
      cache.clear()
      local.clear()
      dirty.clear()
      applied.clear()
      deferred.clear()
      loading = Promise.resolve()
      await driver.clear(name)
    },
    key: async (index: number) => {
      await load()

      return [...cache.keys()][index]
    },
    getLength: async () => {
      await load()

      return cache.size
    },
    get length() {
      return storage.getLength()
    },
    flush,
    accept(insert, remove, revision) {
      // The initial load already reflects everything up to `floor`.
      if (revision <= floor) return

      const changes = [
        ...Object.entries(insert).map(([key, value]) => [key, value] as const),
        ...remove.map((key) => [key, null] as const),
      ]

      for (const [key, value] of changes) {
        if (local.has(key)) {
          const held = deferred.get(key)

          if (!held || revision > held.revision) deferred.set(key, { revision, value })
          continue
        }

        if (revision <= (applied.get(key) ?? floor)) continue
        place(key, value, revision)
      }
    },
  }

  return storage
}

import { describe, expect, test } from "bun:test"
import type { PersistenceSyncAPI, PersistenceSyncCallback, SyncStorage } from "@solid-primitives/storage"
import { createRoot } from "solid-js"
import { createStore } from "solid-js/store"
import { flushPersisted, persistStore } from "./persist"

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

type State = { count: number; label: string }

function setup(input: { initial?: string | null; delay?: number; sync?: PersistenceSyncAPI }) {
  const writes: string[] = []

  return createRoot((dispose) => {
    const [store, setStore] = createStore<State>({ count: 0, label: "" })

    const persist = persistStore({
      store,
      setStore,
      name: "state",
      storage: {
        getItem: () => input.initial ?? null,
        setItem: (_key: string, value: string) => {
          writes.push(value)
        },
        removeItem: () => {},
      } satisfies SyncStorage,
      serialize: JSON.stringify,
      deserialize: JSON.parse,
      sync: input.sync,
      delay: input.delay ?? 10,
    })

    return { store, set: persist.setStore, persist, writes, dispose }
  })
}

describe("persistStore", () => {
  test("marks the store dirty on set and writes once after the delay", async () => {
    const value = setup({})
    value.set("count", 1)
    value.set("count", 2)
    value.set("label", "a")
    expect(value.store.count).toBe(2)
    expect(value.writes).toEqual([])
    await wait(30)
    expect(value.writes).toEqual([JSON.stringify({ count: 2, label: "a" })])
    value.dispose()
  })

  test("skips the write when the serialized value did not change", () => {
    const value = setup({ delay: 10_000 })
    value.set("count", 1)
    value.persist.flush()
    value.set("count", 1)
    value.persist.flush()
    expect(value.writes).toHaveLength(1)
    value.dispose()
  })

  test("hydrates synchronously from sync storage without writing back", () => {
    const value = setup({ initial: JSON.stringify({ count: 5, label: "saved" }), delay: 10_000 })
    expect(value.store).toEqual({ count: 5, label: "saved" })
    value.persist.flush()
    expect(value.writes).toEqual([])
    value.dispose()
  })

  test("applies another window's value when clean and ignores it while dirty", () => {
    const listeners: PersistenceSyncCallback[] = []
    const sent: string[] = []

    const value = setup({
      delay: 10_000,
      sync: [(subscriber) => listeners.push(subscriber), (_key, next) => sent.push(String(next))],
    })

    listeners[0]!({ key: "state", newValue: JSON.stringify({ count: 3, label: "remote" }), timeStamp: 0 })
    expect(value.store).toEqual({ count: 3, label: "remote" })
    value.set("label", "local")
    listeners[0]!({ key: "state", newValue: JSON.stringify({ count: 4, label: "remote-2" }), timeStamp: 0 })
    expect(value.store).toEqual({ count: 3, label: "local" })
    value.persist.flush()
    expect(sent).toEqual([JSON.stringify({ count: 3, label: "local" })])
    value.dispose()
  })

  test("a remote value arriving during a no-op local set is adopted when the save finds no change", () => {
    const listeners: PersistenceSyncCallback[] = []
    const sent: string[] = []

    const value = setup({
      delay: 10_000,
      sync: [(subscriber) => listeners.push(subscriber), (_key, next) => sent.push(String(next))],
    })

    value.set("count", 1)
    value.persist.flush()
    // Setting the same value again marks the store dirty without changing it.
    value.set("count", 1)
    listeners[0]!({ key: "state", newValue: JSON.stringify({ count: 1, label: "remote" }), timeStamp: 0 })
    expect(value.store.label).toBe("")
    value.persist.flush()
    expect(value.store).toEqual({ count: 1, label: "remote" })
    expect(value.writes).toHaveLength(1)
    expect(sent).toHaveLength(1)
    // A later save must not consider the adopted value a local change.
    value.set("count", 1)
    value.persist.flush()
    expect(value.writes).toHaveLength(1)
    value.dispose()
  })

  test("a remote revert to the saved value during a no-op local set clears an earlier held change", () => {
    const listeners: PersistenceSyncCallback[] = []
    const value = setup({ delay: 10_000, sync: [(subscriber) => listeners.push(subscriber), () => {}] })
    value.set("label", "saved")
    value.persist.flush()
    value.set("label", "saved")
    listeners[0]!({ key: "state", newValue: JSON.stringify({ count: 0, label: "changed" }), timeStamp: 0 })
    listeners[0]!({ key: "state", newValue: JSON.stringify({ count: 0, label: "saved" }), timeStamp: 0 })
    value.persist.flush()
    expect(value.store).toEqual({ count: 0, label: "saved" })
    expect(value.writes).toHaveLength(1)
    value.dispose()
  })

  test("a remote value arriving during a real local change is dropped in favour of the local one", () => {
    const listeners: PersistenceSyncCallback[] = []
    const value = setup({ delay: 10_000, sync: [(subscriber) => listeners.push(subscriber), () => {}] })
    value.set("count", 1)
    listeners[0]!({ key: "state", newValue: JSON.stringify({ count: 9, label: "remote" }), timeStamp: 0 })
    value.persist.flush()
    expect(value.store).toEqual({ count: 1, label: "" })
    expect(value.writes).toEqual([JSON.stringify({ count: 1, label: "" })])
    value.dispose()
  })

  test("disposing the owner and flushPersisted both save pending changes", () => {
    const first = setup({ delay: 10_000 })
    first.set("count", 1)
    first.dispose()
    expect(first.writes).toHaveLength(1)

    const second = setup({ delay: 10_000 })
    second.set("count", 2)
    flushPersisted()
    expect(second.writes).toEqual([JSON.stringify({ count: 2, label: "" })])
    second.dispose()
    expect(second.writes).toHaveLength(1)
  })
})

import type { AsyncStorage, PersistenceSyncAPI, SyncStorage } from "@solid-primitives/storage"
import { getOwner, onCleanup, untrack } from "solid-js"
import { reconcile, type SetStoreFunction, type Store } from "solid-js/store"

export const persistSaveDelay = 100

const pending = new Set<() => void>()

/** Serialize and write every store with unsaved changes now. */
export function flushPersisted() {
  for (const save of [...pending]) save()
}

// Covers synchronous web storage. Desktop registers its own pagehide handling earlier than this
// module loads, so its shutdown path calls flushPersisted() itself before flushing namespaces.
if (typeof document !== "undefined") {
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") flushPersisted()
  })
  window.addEventListener("pagehide", flushPersisted)
}

// A store whose serialized form is written to storage on a schedule instead of on every setter
// call. The setter only marks the store dirty; serialization happens once per save window, once
// per owner cleanup, and when the page hides. Mirrors VS Code's Memento.
export function persistStore<T extends object>(input: {
  store: Store<T>
  setStore: SetStoreFunction<T>
  name: string
  storage: SyncStorage | AsyncStorage
  serialize: (value: T) => string
  deserialize: (raw: string) => T
  sync?: PersistenceSyncAPI
  delay?: number
  /** Replaces `storage.setItem` for stores whose storage can take the value itself. */
  write?: (value: T, serialized: string) => void
}) {
  const delay = input.delay ?? persistSaveDelay
  let dirty = false
  let touched = false
  let last: string | undefined
  // The newest value another window wrote while this store was dirty; applied at save time if the
  // local setter calls turned out not to change anything.
  let remote: string | undefined
  let timer: ReturnType<typeof setTimeout> | undefined

  const save = () => {
    clearTimeout(timer)
    timer = undefined
    pending.delete(save)

    if (!dirty) return
    dirty = false
    const held = remote
    remote = undefined
    const next = untrack(() => input.serialize(input.store))

    if (next === last) {
      if (held !== undefined && held !== last) hydrate(held)

      return
    }

    last = next
    input.sync?.[1](input.name, next)

    if (input.write) return input.write(input.store, next)
    void input.storage.setItem(input.name, next)
  }

  // Solid's setter overloads are too deep to spread generically; the wrapper only forwards.
  const apply = input.setStore as unknown as (...values: unknown[]) => void

  const setStore = ((...values: unknown[]) => {
    apply(...values)
    dirty = true
    touched = true
    pending.add(save)
    timer ??= setTimeout(save, delay)
  }) as unknown as SetStoreFunction<T>

  const hydrate = (raw: string) => {
    last = raw
    input.setStore(reconcile(input.deserialize(raw)))
  }

  const init = input.storage.getItem(input.name)

  // A value the user already changed is newer than whatever storage held.
  if (init instanceof Promise) void init.then((raw) => raw && !touched && hydrate(raw))
  else if (init) hydrate(init)

  input.sync?.[0]((data) => {
    if (data.key !== input.name || (data.url ?? location.href) !== location.href) return

    if (!data.newValue) return

    // A real unsaved local change wins over another window's write, as in VS Code's storage
    // service; whether the change is real is only known when the store is serialized. Every
    // remote value replaces the held one, including a revert to `last`, so the save sees the
    // other window's final state rather than an intermediate one.
    if (dirty) {
      remote = data.newValue

      return
    }

    if (data.newValue === last) return
    hydrate(data.newValue)
  })

  if (getOwner()) onCleanup(save)

  return { setStore, init, flush: save }
}

import { describe, expect, test } from "bun:test"
import { Effect, Predicate, Schema, SchemaGetter } from "effect"
import { Persistence } from "./schema"

describe("persistence schemas", () => {
  test("initial state supplies nested defaults without hiding valid siblings", () => {
    const schema = Persistence.withInitial(
      Persistence.struct({
        enabled: Schema.Boolean,
        appearance: Persistence.struct({ width: Schema.Number, font: Schema.String }),
        variant: Schema.optional(Schema.NullOr(Schema.String)),
      }),
      { enabled: true, appearance: { width: 240, font: "default" }, variant: "high" },
    )

    const decode = Schema.decodeUnknownSync(schema)
    expect(decode({ appearance: { width: 300 } })).toEqual({
      enabled: true,
      appearance: { width: 300, font: "default" },
      variant: "high",
    })
    expect(decode({ enabled: "false", appearance: { width: "wide", font: "saved" }, variant: null })).toEqual({
      enabled: true,
      appearance: { width: 240, font: "saved" },
      variant: null,
    })
    expect(decode({ appearance: null })).toEqual({
      enabled: true,
      appearance: { width: 240, font: "default" },
      variant: "high",
    })
  })

  test("legacy migration observes missing fields before initial defaults are applied", () => {
    const current = Persistence.struct({ mode: Schema.Literals(["compact", "full"]), enabled: Schema.Boolean })

    const stored = Persistence.legacy({
      mode: Schema.optional(Schema.Unknown),
      expanded: Schema.optional(Schema.Boolean),
    }).pipe(
      Schema.decode({
        decode: SchemaGetter.transform((value) =>
          value.mode !== undefined || value.expanded === undefined
            ? value
            : { ...value, mode: value.expanded ? "full" : "compact" },
        ),
        encode: SchemaGetter.passthrough(),
      }),
    )

    const schema = Persistence.withInitial(Persistence.migrate(current, stored), { mode: "compact", enabled: true })
    const decode = Schema.decodeUnknownSync(schema)
    expect(decode({ expanded: true, enabled: false })).toEqual({ mode: "full", enabled: false })
    expect(decode({ expanded: true, mode: "compact" })).toEqual({ mode: "compact", enabled: true })
    expect(decode({ expanded: true, mode: "invalid" })).toEqual({ mode: "compact", enabled: true })
    expect(Schema.encodeSync(schema)(decode({ expanded: true }))).toEqual({ mode: "full", enabled: true })
  })

  test("legacy read shapes carry unknown nested fields through to the current schema", () => {
    const current = Persistence.struct({
      general: Persistence.struct({
        mode: Schema.Literals(["compact", "full"]),
        theme: Schema.String,
        nested: Persistence.struct({ keep: Schema.Boolean }),
      }),
      other: Persistence.struct({ flag: Schema.Boolean }),
    })

    const stored = Persistence.legacy({
      general: Persistence.optional(Persistence.legacy({ expanded: Persistence.optional(Schema.Boolean) })),
    }).pipe(
      Schema.decode({
        decode: SchemaGetter.transform((value) => {
          const general = value.general

          if (!general || general.expanded === undefined) return value

          return { ...value, general: { ...general, mode: general.expanded ? "full" : "compact" } }
        }),
        encode: SchemaGetter.passthrough(),
      }),
    )

    const schema = Persistence.withInitial(Persistence.migrate(current, stored), {
      general: { mode: "compact", theme: "light", nested: { keep: false } },
      other: { flag: false },
    })

    const decode = Schema.decodeUnknownSync(schema)
    expect(decode({ general: { expanded: true, theme: "dark", nested: { keep: true } }, other: { flag: true } })).toEqual({
      general: { mode: "full", theme: "dark", nested: { keep: true } },
      other: { flag: true },
    })
  })

  test("initial merging preserves field codecs and replaces arrays rather than merging indexes", () => {
    const current = Persistence.struct({
      amount: Schema.NumberFromString.check(Schema.isFinite()),
      items: Schema.mutable(Schema.Array(Schema.String)),
    })

    const schema = Persistence.withInitial(current, { amount: 7, items: ["initial"] })
    const decode = Schema.decodeUnknownSync(schema)
    expect(decode({ amount: "12", items: [] })).toEqual({ amount: 12, items: [] })
    expect(decode({ amount: "invalid", items: ["saved"] })).toEqual({ amount: 7, items: ["saved"] })
    expect(Schema.encodeSync(schema)(decode({}))).toEqual({ amount: "7", items: ["initial"] })
  })

  test("built-in defaults only recover absent values, not invalid ones", () => {
    const schema = Persistence.struct({
      enabled: Schema.Boolean.pipe(Schema.withDecodingDefault(Effect.succeed(true))),
    })

    const decode = Schema.decodeUnknownSync(schema)
    expect(decode({})).toEqual({ enabled: true })
    expect(decode({ enabled: undefined })).toEqual({ enabled: true })
    expect(() => decode({ enabled: "true" })).toThrow()
    const state: typeof schema.Type = { enabled: false }
    state.enabled = true
    expect(Schema.encodeSync(schema)(state)).toEqual({ enabled: true })
  })

  test("defaults missing and invalid fields without discarding valid siblings and keeps codecs on writes", () => {
    const schema = Schema.Struct({
      enabled: Persistence.fallback(Schema.Boolean, () => true),
      label: Persistence.fallback(Schema.String, () => "default"),
      amount: Persistence.fallback(Schema.NumberFromString.check(Schema.isFinite()), () => 7),
    })

    const decode = Schema.decodeUnknownSync(schema)
    expect(decode({})).toEqual({ enabled: true, label: "default", amount: 7 })
    expect(decode({ enabled: "false", label: "saved", amount: "invalid" })).toEqual({
      enabled: true,
      label: "saved",
      amount: 7,
    })
    expect(decode({ enabled: undefined, label: null, amount: "12" })).toEqual({
      enabled: true,
      label: "default",
      amount: 12,
    })
    expect(Schema.encodeSync(schema)(decode({}))).toEqual({ enabled: true, label: "default", amount: "7" })
  })

  test("optional recovery keeps fields optional without adding an undefined default", () => {
    const number = Schema.NumberFromString.check(Schema.isFinite())
    const schema = Persistence.struct({ value: Persistence.optional(number) })
    const decode = Schema.decodeUnknownSync(schema)
    const empty: typeof schema.Type = {}
    expect(decode({})).toEqual(empty)
    expect(decode({ value: "invalid" })).toEqual(empty)
    expect(Object.hasOwn(decode({ value: "invalid" }), "value")).toBe(false)
    expect(decode({ value: undefined })).toEqual({ value: undefined })
    expect(decode({ value: "42" })).toEqual({ value: 42 })
    expect(Schema.encodeSync(schema)({ value: 42 })).toEqual({ value: "42" })
    expect(Schema.encodeSync(schema)(empty)).toEqual({})
    expect(() =>
      Schema.decodeUnknownSync(Schema.Struct({ value: Schema.optional(number) }))({ value: "invalid" }),
    ).toThrow()
  })

  test("records default to fresh mutable objects and keep entry recovery explicit", () => {
    const strict = Persistence.record(Schema.Boolean)
    const decode = Schema.decodeUnknownSync(strict)
    expect(decode(undefined)).toEqual({})
    expect(decode([])).toEqual({})
    expect(decode({ valid: true, invalid: "true" })).toEqual({})
    const first: typeof strict.Type = decode(undefined)
    first.changed = true
    expect(decode(undefined)).toEqual({})

    const recover = Persistence.record(Persistence.optional(Schema.Boolean))
    const state = Schema.decodeUnknownSync(recover)({ valid: true, invalid: "true" })
    expect(state).toEqual({ valid: true })
    expect(Schema.encodeSync(recover)(state)).toEqual({ valid: true })
  })

  test("creates fresh default collections", () => {
    const schema = Schema.Struct({ items: Persistence.array(Schema.String) })
    const decode = Schema.decodeUnknownSync(schema)
    const first = decode({})
    first.items.push("changed")
    expect(decode({}).items).toEqual([])
  })

  test("recovers and migrates individual array entries", () => {
    const current = Schema.Struct({ name: Schema.String })

    const schema = Persistence.array(
      Schema.Union([current, Schema.String]).pipe(
        Schema.decodeTo(current, {
          decode: SchemaGetter.transform((value) => (Predicate.isString(value) ? { name: value } : value)),
          encode: SchemaGetter.passthrough(),
        }),
      ),
    )

    const decode = Schema.decodeUnknownSync(schema)
    const value = decode(["old", { name: "new" }, null, { name: false }])
    expect(value).toEqual([{ name: "old" }, { name: "new" }])
    expect(Schema.encodeSync(schema)(value)).toEqual(value)
    expect(decode(Schema.encodeSync(schema)(value))).toEqual(value)
    expect(decode(undefined)).toEqual([])
    expect(decode({})).toEqual([])
  })
})

export * as Persistence from "./schema"

import { Effect, Option, Predicate, Result, Schema, SchemaAST, SchemaGetter, SchemaParser, Struct } from "effect"

export type Migrated<S extends Schema.ConstraintCodec<object, unknown>> = {
  current: S
  read: Schema.ConstraintDecoder<unknown>
}

export function migrate<S extends Schema.ConstraintCodec<object, unknown>>(
  current: S,
  read: Schema.ConstraintDecoder<unknown>,
): Migrated<S> {
  return { current, read }
}

function isMigrated<S extends Schema.ConstraintCodec<object, unknown>>(schema: S | Migrated<S>): schema is Migrated<S> {
  return "current" in schema
}

export function withInitial<S extends Schema.ConstraintCodec<object, unknown>>(
  definition: S | Migrated<S>,
  initial: NoInfer<S["Type"]>,
) {
  const schema = isMigrated(definition) ? definition.current : definition
  const read = isMigrated(definition) ? SchemaParser.decodeUnknownResult(definition.read) : Result.succeed<unknown>
  const encode = Schema.encodeUnknownSync(schema)

  return Schema.Unknown.pipe(
    Schema.decode<Schema.Unknown>({
      decode: SchemaGetter.transformEffect((value) =>
        Effect.fromResult(Result.map(read(value), (stored) => merge(initial, recover(schema.ast, stored, initial)))),
      ),
      encode: SchemaGetter.transform((value) => encode(value)),
    }),
    Schema.decodeTo(Schema.toType(schema)),
  )
}

// A legacy read shape declares only the fields it migrates. Decoding strips unknown keys, so every
// struct level in a `migrate` read schema must stay open for the current fields it does not name.
export function legacy<const Fields extends Schema.Struct.Fields>(fields: Fields) {
  return Schema.StructWithRest(Schema.Struct(fields), [Schema.Record(Schema.String, Schema.Unknown)])
}

// Object-level codecs own their recovery. Plain structs can recover fields independently.
// SAFETY: stored values and their defaults are untyped trees walked against `ast`; `withInitial` decodes the
// recovered and merged result with the current schema before anyone reads it.
// oxlint-disable-next-line anti-slop/no-unknown-parameters, anti-slop/no-unknown-returns -- see SAFETY above
function recover(ast: SchemaAST.AST, value: unknown, initial: unknown): unknown {
  if (value === undefined) return initial

  if (SchemaAST.isObjects(ast) && !ast.encoding && ast.indexSignatures.length === 0 && Predicate.isObject(value)) {
    return Object.fromEntries(
      ast.propertySignatures.flatMap((field) => {
        const defaults = Predicate.isObject(initial) ? initial[field.name] : undefined
        const next = recover(field.type, value[field.name], defaults)

        if (next === undefined && !Object.hasOwn(value, field.name) && defaults === undefined) return []

        return [[field.name, next]]
      }),
    )
  }

  const decoded = Schema.decodeUnknownOption(Schema.make<Schema.Codec<unknown, unknown>>(ast))(value)

  return Option.isSome(decoded) ? decoded.value : initial
}

// SAFETY: like `recover`, merges untyped trees that `withInitial` decodes with the current schema afterwards.
// oxlint-disable-next-line anti-slop/no-unknown-parameters, anti-slop/no-unknown-returns -- see SAFETY above
function merge(initial: unknown, value: unknown): unknown {
  if (value === undefined) return initial

  if (!Predicate.isObject(initial) || !Predicate.isObject(value)) return value

  return Object.fromEntries(
    [...new Set([...Object.keys(initial), ...Object.keys(value)])].map((key) => [key, merge(initial[key], value[key])]),
  )
}

// Unlike a decoding default, a fallback also replaces invalid persisted values.
export function fallback<S extends Schema.ConstraintCodec<unknown, unknown>>(schema: S, value: () => S["Type"]) {
  const defaulted = Schema.withDecodingDefaultType<S>(Effect.sync(value))(schema)

  return Schema.catchDecoding<typeof defaulted>(() => Effect.sync(() => Option.some(value())))(defaulted)
}

export function optional<S extends Schema.ConstraintCodec<unknown, unknown>>(schema: S) {
  const field = Schema.optional(schema)

  return Schema.catchDecoding<typeof field>(() => Effect.succeed(Option.none()))(field)
}

export function struct<const Fields extends Schema.Struct.Fields>(fields: Fields) {
  return Schema.Struct(fields).mapFields(Struct.map(Schema.mutableKey))
}

export function record<S extends Schema.ConstraintCodec<unknown, unknown>>(schema: S) {
  const entries = Schema.Record(Schema.String, Schema.mutableKey(schema))

  return fallback(entries, () => Schema.decodeUnknownSync(entries)({}))
}

// Recover individual entries rather than discarding a whole history or collection.
export function array<S extends Schema.ConstraintCodec<unknown, unknown>>(schema: S) {
  const decode = Schema.decodeUnknownOption(schema)
  const encode = Schema.encodeSync(schema)

  return fallback(
    Schema.Array(Schema.Unknown).pipe(
      Schema.decodeTo(Schema.mutable(Schema.Array(Schema.toType(schema))), {
        decode: SchemaGetter.transform((items) => items.flatMap((item) => Option.toArray(decode(item)))),
        encode: SchemaGetter.transform((items) => items.map((item) => encode(item))),
      }),
    ),
    () => [],
  )
}

import { describe, expect, test } from "bun:test"
import { ServerScope } from "@/runtime/server/scope"
import { Persist, removePersisted } from "./storage"

describe("persist targets", () => {
  test("workspace storage names are safe file names and normalize Windows paths", () => {
    const raw = Persist.workspace("C:\\Users\\foo", "vcs")
    const normalized = Persist.workspace("C:/Users/foo", "vcs")

    expect(raw.storage).toMatch(/^opencode\.workspace\.[a-zA-Z0-9._-]+\.dat$/)
    expect(raw.storage).toBe(normalized.storage)
    expect(raw.workspaceStorageAliases).toHaveLength(1)
    expect(raw.workspaceStorageAliases![0]).toMatch(/^opencode\.workspace\.[a-zA-Z0-9._-]+\.dat$/)
    expect(raw.workspaceStorageAliases![0]).not.toBe(raw.storage)
    expect(normalized.workspaceStorageAliases).toEqual(raw.workspaceStorageAliases)
    expect(Persist.workspace("/home/luke/repo", "vcs").workspaceStorageAliases).toBeUndefined()
  })

  test("removes workspace storage aliases and draft storage when removing persisted targets", () => {
    const workspace = Persist.workspace("C:\\Users\\foo", "terminal")
    const draft = Persist.draft("draft-a", "prompt")

    const keys = [
      `${workspace.storage}:${workspace.key}`,
      `${workspace.workspaceStorageAliases![0]}:${workspace.key}`,
      `${draft.storage}:${draft.key}`,
    ]

    keys.forEach((key) => localStorage.setItem(key, '{"value":1}'))

    removePersisted(workspace)
    removePersisted(draft)

    expect(keys.map((key) => localStorage.getItem(key))).toEqual([null, null, null])
  })

  test("draft target isolates storage per draft and namespaces keys", () => {
    const a = Persist.draft("draft-a", "prompt")
    const b = Persist.draft("draft-b", "prompt")

    expect(a.key).toBe("draft:prompt")
    expect(a.storage).not.toBe(b.storage)
    expect(a.storage).not.toBe(Persist.workspace("/home/luke/repo", "prompt").storage)
  })

  test("server workspace target preserves local storage and isolates remote storage", () => {
    const local = Persist.serverWorkspace(ServerScope.local, "/home/luke/repo", "prompt")
    const windows = Persist.serverWorkspace("https://windows.example" as ServerScope, "/home/luke/repo", "prompt")
    const debian = Persist.serverWorkspace("https://debian.example" as ServerScope, "/home/luke/repo", "prompt")

    expect(local).toEqual(Persist.workspace("/home/luke/repo", "prompt"))
    expect(windows.storage).not.toBe(local.storage)
    expect(debian.storage).not.toBe(local.storage)
    expect(debian.storage).not.toBe(windows.storage)
    expect(windows.workspaceStorageAliases).toBeUndefined()
    expect(debian.workspaceStorageAliases).toBeUndefined()
  })

  test("server global target preserves local key and isolates remote keys", () => {
    expect(Persist.serverGlobal(ServerScope.local, "notification")).toEqual(Persist.global("notification"))
    expect(Persist.serverGlobal("https://debian.example" as ServerScope, "notification")).toEqual({
      storage: "opencode.global.dat",
      key: "https://debian.example\0notification",
    })
  })

  test("server global target cannot collide when scope and key contain colons", () => {
    expect(Persist.serverGlobal("a:b" as ServerScope, "c")).not.toEqual(Persist.serverGlobal("a" as ServerScope, "b:c"))
  })
})

import { Platform, usePlatform } from "@/runtime/platform/platform"
import { messageSync, type AsyncStorage, type SyncStorage } from "@solid-primitives/storage"
import { checksum } from "@opencode/util/encode"
import { createResource, onCleanup, type Accessor } from "solid-js"
import { createStore, type SetStoreFunction, type Store } from "solid-js/store"
import { Option, Predicate, Schema } from "effect"
import { pathKey } from "@/workspaces/path-key"
import { ScopedKey, ServerScope } from "@/runtime/server/scope"
import { persistStore } from "./persist"
import { Persistence } from "./schema"

type InitType = Promise<string | null> | string | null

type PersistedWithReady<T> = [
  Store<T>,
  SetStoreFunction<T>,
  InitType,
  Accessor<boolean> & { promise: undefined | Promise<unknown> },
]

type PersistTarget = {
  draft?: boolean
  sync?: boolean
  storage?: string
  scope?: "window"
  workspaceStorageAliases?: string[]
  previousKey?: string
  /**
   * Imports an older key once, from this storage (or `storage` when given) or else the default storage
   * (e.g. `settings.v3`). With pick, only that part is copied and the source stays. The first source that holds a
   * value wins.
   */
  copyFrom?: readonly CopyFrom[]
  key: string
}

// SAFETY: an older stored value is JSON with no schema of its own; the store decodes what a pick returns.
// oxlint-disable-next-line anti-slop/no-unknown-parameters, anti-slop/no-unknown-returns -- see SAFETY above
type PickPart = (value: unknown) => unknown

type CopyFrom = { key: string; storage?: string; pick?: PickPart }

const GLOBAL_STORAGE = "opencode.global.dat"

const WINDOW_STORAGE = "opencode.window"

const LOCAL_PREFIX = "opencode."

const fallback = new Map<string, boolean>()

const CACHE_MAX_ENTRIES = 500

const CACHE_MAX_BYTES = 8 * 1024 * 1024

type CacheEntry = { value: string; bytes: number }

const cache = new Map<string, CacheEntry>()

const cacheTotal = { bytes: 0 }

function cacheDelete(key: string) {
  const entry = cache.get(key)

  if (!entry) return
  cacheTotal.bytes -= entry.bytes
  cache.delete(key)
}

function cachePrune() {
  for (;;) {
    if (cache.size <= CACHE_MAX_ENTRIES && cacheTotal.bytes <= CACHE_MAX_BYTES) return
    const oldest = cache.keys().next()

    if (oldest.done || !oldest.value) return
    cacheDelete(oldest.value)
  }
}

function cacheSet(key: string, value: string) {
  const bytes = value.length * 2

  if (bytes > CACHE_MAX_BYTES) {
    cacheDelete(key)

    return
  }

  const entry = cache.get(key)

  if (entry) cacheTotal.bytes -= entry.bytes
  cache.delete(key)
  cache.set(key, { value, bytes })
  cacheTotal.bytes += bytes
  cachePrune()
}

function cacheGet(key: string) {
  const entry = cache.get(key)

  if (!entry) return
  cache.delete(key)
  cache.set(key, entry)

  return entry.value
}

function fallbackDisabled(scope: string) {
  return fallback.get(scope) === true
}

function fallbackSet(scope: string) {
  fallback.set(scope, true)
}

// SAFETY: a thrown storage error has no schema; only `name`, `code` and `message` are read, each behind a guard.
// oxlint-disable-next-line anti-slop/no-unknown-parameters -- see SAFETY above
function quota(error: unknown) {
  if (error instanceof DOMException) {
    if (error.name === "QuotaExceededError") return true

    if (error.name === "NS_ERROR_DOM_QUOTA_REACHED") return true

    if (error.name === "QUOTA_EXCEEDED_ERR") return true

    if (error.code === 22 || error.code === 1014) return true

    return false
  }

  const name = Predicate.hasProperty(error, "name") && Predicate.isString(error.name) ? error.name : undefined

  if (name === "QuotaExceededError" || name === "NS_ERROR_DOM_QUOTA_REACHED") return true

  if (name && /quota/i.test(name)) return true

  const code = Predicate.hasProperty(error, "code") ? error.code : undefined

  if (code === 22 || code === 1014) return true

  const message =
    Predicate.hasProperty(error, "message") && Predicate.isString(error.message) ? error.message : undefined

  return !!message && /quota/i.test(message)
}

type Evict = { key: string; size: number }

function evict(storage: Storage, keep: string, value: string) {
  const total = storage.length
  const indexes = Array.from({ length: total }, (_, index) => index)
  const items: Evict[] = []

  for (const index of indexes) {
    const name = storage.key(index)

    if (!name) continue

    if (!name.startsWith(LOCAL_PREFIX)) continue

    if (name === keep) continue
    const stored = storage.getItem(name)
    items.push({ key: name, size: stored?.length ?? 0 })
  }

  items.sort((a, b) => b.size - a.size)

  for (const item of items) {
    storage.removeItem(item.key)
    cacheDelete(item.key)

    try {
      storage.setItem(keep, value)
      cacheSet(keep, value)

      return true
    } catch (error) {
      if (!quota(error)) throw error
    }
  }

  return false
}

function write(storage: Storage, key: string, value: string) {
  try {
    storage.setItem(key, value)
    cacheSet(key, value)

    return true
  } catch (error) {
    if (!quota(error)) throw error
  }

  try {
    storage.removeItem(key)
    cacheDelete(key)
    storage.setItem(key, value)
    cacheSet(key, value)

    return true
  } catch (error) {
    if (!quota(error)) throw error
  }

  const ok = evict(storage, key, value)

  return ok
}

function readCurrent(input: { storage: SyncStorage; key: string; normalize: (raw: string) => string | undefined }) {
  const raw = input.storage.getItem(input.key)

  if (raw === null) return
  const next = input.normalize(raw)

  if (next === undefined) {
    input.storage.removeItem(input.key)

    return null
  }

  if (raw !== next) input.storage.setItem(input.key, next)

  return next
}

type RelocationSource<S> = { storage: S; key?: string; pick?: PickPart }

const decodeJson = Schema.decodeUnknownOption(Schema.fromJsonString(Schema.Unknown))

/** Applies a source's pick to its raw JSON; the picked part is re-encoded for the target schema. */
function pickRaw(raw: string | null, pick: PickPart | undefined) {
  if (raw === null || !pick) return raw
  const value = decodeJson(raw)

  if (Option.isNone(value)) return null
  const picked = pick(value.value)

  return picked === undefined ? null : JSON.stringify(picked)
}

function relocateStoredValue(input: {
  current: SyncStorage
  sources: RelocationSource<SyncStorage>[]
  key: string
  normalize: (raw: string) => string | undefined
}) {
  for (const source of input.sources) {
    const key = source.key ?? input.key
    const raw = pickRaw(source.storage.getItem(key), source.pick)

    if (raw === null) continue

    const next = input.normalize(raw)

    if (next === undefined) {
      if (!source.pick) source.storage.removeItem(key)
      continue
    }

    input.current.setItem(input.key, next)

    if (input.current.getItem(input.key) !== next) return null

    if (!source.pick) source.storage.removeItem(key)

    return next
  }

  return null
}

async function readCurrentAsync(input: {
  storage: AsyncStorage
  key: string
  normalize: (raw: string) => string | undefined
}) {
  const raw = await input.storage.getItem(input.key)

  if (raw === null) return
  const next = input.normalize(raw)

  if (next === undefined) {
    await input.storage.removeItem(input.key).catch(() => undefined)

    return null
  }

  if (raw !== next) await input.storage.setItem(input.key, next)

  return next
}

async function removeAsync(storage: AsyncStorage, key: string) {
  try {
    await storage.removeItem(key)
  } catch {}
}

function toAsyncStorage(storage: SyncStorage | AsyncStorage): AsyncStorage {
  return {
    getItem: async (key) => storage.getItem(key),
    setItem: async (key, value) => storage.setItem(key, value),
    removeItem: async (key) => storage.removeItem(key),
  }
}

async function relocateStoredValueAsync(input: {
  current: AsyncStorage
  sources: RelocationSource<AsyncStorage>[]
  key: string
  normalize: (raw: string) => string | undefined
}) {
  for (const source of input.sources) {
    const key = source.key ?? input.key
    const raw = pickRaw(await source.storage.getItem(key), source.pick)

    if (raw === null) continue

    const next = input.normalize(raw)

    if (next === undefined) {
      if (!source.pick) await removeAsync(source.storage, key)
      continue
    }

    await input.current.setItem(input.key, next)

    if (!source.pick) await source.storage.removeItem(key)

    return next
  }

  return null
}

function workspaceStorage(dir: string) {
  const head = (dir.slice(0, 12) || "workspace").replace(/[^a-zA-Z0-9._-]/g, "-")
  const sum = checksum(dir) ?? "0"

  return `opencode.workspace.${head}.${sum}.dat`
}

function draftStorage(draftID: string) {
  const head = (draftID.slice(0, 12) || "draft").replace(/[^a-zA-Z0-9._-]/g, "-")
  const sum = checksum(draftID) ?? "0"

  return `opencode.draft.${head}.${sum}.dat`
}

function windowStorage(windowID: string) {
  const safe = (windowID || "browser").replace(/[^a-zA-Z0-9._-]/g, "-")

  return `${WINDOW_STORAGE}.${safe}.dat`
}

function workspaceStorageAliases(dir: string) {
  const storage = workspaceStorage(pathKey(dir))
  const result = new Set<string>()
  const raw = workspaceStorage(dir)

  if (raw !== storage) result.add(raw)

  const key = pathKey(dir)
  const drive = key.length >= 3 && key[1] === ":" && key[2] === "/"

  if (drive) {
    const backslash = workspaceStorage(key.replaceAll("/", "\\"))

    if (backslash !== storage) result.add(backslash)
  }

  if (result.size === 0) return

  return [...result]
}

function serverWorkspaceTarget(scope: ServerScope, dir: string, key: string): PersistTarget {
  if (scope !== ServerScope.local) return { storage: workspaceStorage(ScopedKey.from(scope, pathKey(dir))), key }

  return { storage: workspaceStorage(pathKey(dir)), workspaceStorageAliases: workspaceStorageAliases(dir), key }
}

function localStorageWithPrefix(prefix: string): SyncStorage {
  const base = `${prefix}:`
  const scope = `prefix:${prefix}`
  const item = (key: string) => base + key

  return {
    getItem: (key) => {
      const name = item(key)
      const cached = cacheGet(name)

      if (fallbackDisabled(scope)) return cached ?? null

      const stored = (() => {
        try {
          return localStorage.getItem(name)
        } catch {
          fallbackSet(scope)

          return null
        }
      })()

      if (stored === null) return cached ?? null
      cacheSet(name, stored)

      return stored
    },
    setItem: (key, value) => {
      const name = item(key)

      if (fallbackDisabled(scope)) return

      try {
        if (write(localStorage, name, value)) return
      } catch {
        fallbackSet(scope)

        return
      }

      fallbackSet(scope)
    },
    removeItem: (key) => {
      const name = item(key)
      cacheDelete(name)

      if (fallbackDisabled(scope)) return

      try {
        localStorage.removeItem(name)
      } catch {
        fallbackSet(scope)
      }
    },
  }
}

function localStorageDirect(): SyncStorage {
  const scope = "direct"

  return {
    getItem: (key) => {
      const cached = cacheGet(key)

      if (fallbackDisabled(scope)) return cached ?? null

      const stored = (() => {
        try {
          return localStorage.getItem(key)
        } catch {
          fallbackSet(scope)

          return null
        }
      })()

      if (stored === null) return cached ?? null
      cacheSet(key, stored)

      return stored
    },
    setItem: (key, value) => {
      if (fallbackDisabled(scope)) return

      try {
        if (write(localStorage, key, value)) return
      } catch {
        fallbackSet(scope)

        return
      }

      fallbackSet(scope)
    },
    removeItem: (key) => {
      cacheDelete(key)

      if (fallbackDisabled(scope)) return

      try {
        localStorage.removeItem(key)
      } catch {
        fallbackSet(scope)
      }
    },
  }
}

const DRAFT_PERSISTED_KEYS = ["prompt", "comments", "file-view", "layout"]

export function draftPersistedKeys() {
  return DRAFT_PERSISTED_KEYS
}

export const Persist = {
  global(key: string): PersistTarget {
    return { storage: GLOBAL_STORAGE, key }
  },
  window(key: string): PersistTarget {
    return { scope: "window", key }
  },
  draft(draftID: string, key: string): PersistTarget {
    return { storage: draftStorage(draftID), key: `draft:${key}` }
  },
  serverGlobal(scope: ServerScope, key: string): PersistTarget {
    if (scope === ServerScope.local) return Persist.global(key)

    return { storage: GLOBAL_STORAGE, key: ScopedKey.from(scope, key) }
  },
  workspace(dir: string, key: string): PersistTarget {
    return serverWorkspaceTarget(ServerScope.local, dir, `workspace:${key}`)
  },
  serverWorkspace(scope: ServerScope, dir: string, key: string): PersistTarget {
    return serverWorkspaceTarget(scope, dir, `workspace:${key}`)
  },
  session(dir: string, session: string, key: string): PersistTarget {
    return serverWorkspaceTarget(ServerScope.local, dir, `session:${session}:${key}`)
  },
  serverSession(scope: ServerScope, dir: string, session: string, key: string): PersistTarget {
    return serverWorkspaceTarget(scope, dir, `session:${session}:${key}`)
  },
  scoped(dir: string, session: string | undefined, key: string): PersistTarget {
    if (session) return Persist.session(dir, session, key)

    return Persist.workspace(dir, key)
  },
  serverScoped(scope: ServerScope, dir: string, session: string | undefined, key: string) {
    if (session) return Persist.serverSession(scope, dir, session, key)

    return Persist.serverWorkspace(scope, dir, key)
  },
  prompt(target: PersistTarget): PersistTarget {
    return { ...target, draft: true }
  },
}

function resolveTarget(target: PersistTarget, platform: Platform): PersistTarget {
  if (target.scope !== "window") return target
  const windowID = platform.platform === "desktop" ? platform.windowID : "browser"

  if (!windowID) throw new Error("Desktop window ID is required for window-scoped storage")

  return {
    ...target,
    storage: windowStorage(windowID),
  }
}

/**
 * Deletes a stored value, so the next read gets the initial value. The older keys `copyFrom` names never import
 * again: a whole-value source is deleted from every storage the import reads, and a picked source, which other owners
 * share, stays while the value becomes `null`, which every store schema reads as its initial value without importing.
 */
export function removePersisted(
  target: Pick<PersistTarget, "draft" | "storage" | "workspaceStorageAliases" | "copyFrom" | "key">,
  platform?: Platform,
) {
  if (target.draft && platform?.draftStore) {
    void platform.draftStore.removeItem(`${target.storage ?? "default"}:${target.key}`)
  }

  const desktop = platform?.platform === "desktop" ? platform.storage : undefined

  const open = (name: string | undefined): SyncStorage | AsyncStorage | undefined => {
    if (desktop) return desktop(name)

    return name ? localStorageWithPrefix(name) : localStorageDirect()
  }

  const copies = target.copyFrom ?? []

  if (copies.some((copy) => copy.pick)) void open(target.storage)?.setItem(target.key, "null")
  else void open(target.storage)?.removeItem(target.key)
  target.workspaceStorageAliases?.forEach((name) => void open(name)?.removeItem(target.key))
  copies.forEach((copy) => {
    if (copy.pick) return
    void open(copy.storage ?? target.storage)?.removeItem(copy.key)

    if (target.storage) void open(undefined)?.removeItem(copy.key)
  })
}

export function persisted<S extends Schema.ConstraintCodec<object, unknown>>(
  target: string | PersistTarget,
  schema: S | Persistence.Migrated<S>,
  initial: NoInfer<S["Type"]>,
  platformOverride?: Platform,
): PersistedWithReady<S["Type"]> {
  const platform = platformOverride ?? usePlatform()
  const config = resolveTarget(Predicate.isString(target) ? { key: target } : target, platform)

  const initialized = Persistence.withInitial(schema, initial)
  const json = Schema.fromJsonString(initialized)
  const decode = Schema.decodeUnknownOption(json)
  const encode = Schema.encodeSync(initialized)
  const serialize = Schema.encodeSync(json)

  const normalize = (raw: string) => {
    const value = decode(raw)

    if (Option.isSome(value)) return serialize(value.value)
  }

  const store = createStore<S["Type"]>(Schema.decodeUnknownSync(Schema.toType(initialized))(initial))
  const isDesktop = platform.platform === "desktop" && !!platform.storage
  const draft = config.draft ? platform.draftStore : undefined
  const prefix = `${config.storage ?? "default"}:`
  // The newest serialized draft, replayed into storage if a slow load finishes after an edit.
  let draftLatest: string | undefined

  const currentStorage = (() => {
    if (draft) {
      return {
        getItem: (key: string) => draft.getItem(prefix + key),
        setItem: (key: string, value: string) => draft.setItem(prefix + key, value),
        removeItem: (key: string) => draft.removeItem(prefix + key),
      } satisfies AsyncStorage
    }

    if (isDesktop) return platform.storage?.(config.storage)

    if (!config.storage) return localStorageDirect()

    return localStorageWithPrefix(config.storage)
  })()

  const workspaceAliases = config.workspaceStorageAliases ?? []

  const storage = (() => {
    if (!isDesktop && !draft) {
      // SAFETY: without desktop storage or a draft store, `currentStorage` is one of the synchronous localStorage views.
      const current = currentStorage as SyncStorage

      const sources: RelocationSource<SyncStorage>[] = [
        ...workspaceAliases.map((storage) => ({ storage: localStorageWithPrefix(storage) })),
        ...(config.previousKey ? [{ storage: localStorageDirect(), key: config.previousKey }] : []),
        ...(config.copyFrom ?? []).flatMap((copy) => [
          { storage: copy.storage ? localStorageWithPrefix(copy.storage) : current, key: copy.key, pick: copy.pick },
          ...(config.storage ? [{ storage: localStorageDirect(), key: copy.key, pick: copy.pick }] : []),
        ]),
      ]

      const api: SyncStorage = {
        getItem: (key) => {
          const value = readCurrent({ storage: current, key, normalize })

          if (value !== undefined) return value

          return relocateStoredValue({
            current,
            sources,
            key,
            normalize,
          })
        },
        setItem: (key, value) => {
          current.setItem(key, value)
        },
        removeItem: (key) => {
          current.removeItem(key)
        },
      }

      return api
    }

    // SAFETY: with desktop storage or a draft store, `currentStorage` is that asynchronous storage.
    const current = currentStorage as AsyncStorage

    const previousDraftStorage = draft
      ? isDesktop
        ? platform.storage?.(config.storage)
        : config.storage
          ? localStorageWithPrefix(config.storage)
          : localStorageDirect()
      : undefined

    const previousStorage = config.previousKey ? (isDesktop ? platform.storage?.() : localStorageDirect()) : undefined

    const relocationSources = [
      previousDraftStorage ? { storage: previousDraftStorage } : undefined,
      ...workspaceAliases.map((name) => ({
        storage: isDesktop ? platform.storage?.(name) : localStorageWithPrefix(name),
      })),
      previousStorage && config.previousKey ? { storage: previousStorage, key: config.previousKey } : undefined,
      ...(config.copyFrom ?? []).flatMap((copy) => [
        {
          storage: copy.storage
            ? isDesktop
              ? platform.storage?.(copy.storage)
              : localStorageWithPrefix(copy.storage)
            : current,
          key: copy.key,
          pick: copy.pick,
        },
        config.storage
          ? { storage: isDesktop ? platform.storage?.() : localStorageDirect(), key: copy.key, pick: copy.pick }
          : undefined,
      ]),
    ].flatMap((source): RelocationSource<AsyncStorage>[] =>
      source?.storage ? [{ ...source, storage: toAsyncStorage(source.storage) }] : [],
    )

    const api: AsyncStorage = {
      getItem: async (key) => {
        const value = await readCurrentAsync({ storage: current, key, normalize })

        if (value !== undefined) return value

        const relocated = await relocateStoredValueAsync({
          current,
          sources: relocationSources,
          key,
          normalize,
        })

        if (draftLatest === undefined) {
          if (draft && relocated !== null) return (await current.getItem(key)) ?? relocated

          return relocated
        }

        await current.setItem(key, draftLatest)

        return draftLatest
      },
      setItem: async (key, value) => {
        if (draft) draftLatest = value
        await current.setItem(key, value)
      },
      removeItem: async (key) => {
        await current.removeItem(key)
      },
    }

    return api
  })()

  const channel =
    config.sync && typeof BroadcastChannel !== "undefined"
      ? new BroadcastChannel(`opencode.persist:${config.storage ?? "default"}:${config.key}`)
      : undefined

  if (channel) onCleanup(() => channel.close())

  const persist = persistStore({
    store: store[0],
    setStore: store[1],
    name: config.key,
    storage,
    serialize,
    deserialize: Schema.decodeUnknownSync(json),
    sync: channel ? messageSync(channel) : undefined,
    // Drafts take the encoded document itself so large text is externalized without the store
    // re-parsing the serialized form on every save.
    write: draft
      ? (value, serialized) => {
          draftLatest = serialized
          // A failed chunk upload is retried by the next save; see drafts.ts.
          void draft
            .setDocument(prefix + config.key, encode(value))
            .catch((error) => console.error(`[persistence] draft write failed for ${config.key}`, error))
        }
      : undefined,
  })

  const state = store[0]
  const setState = persist.setStore
  const init = persist.init

  const isAsync = init instanceof Promise

  const [ready] = createResource(
    () => init,
    async (initValue) => {
      if (initValue instanceof Promise) await initValue

      return true
    },
    { initialValue: !isAsync },
  )

  return [
    state,
    setState,
    init,
    Object.assign(() => (ready.loading ? false : ready.latest === true), {
      promise: init instanceof Promise ? init : undefined,
    }),
  ]
}

import { afterEach, describe, expect, test } from "bun:test"
import { uuid } from "./uuid"

const cryptoDescriptor = Object.getOwnPropertyDescriptor(globalThis, "crypto")

const secureDescriptor = Object.getOwnPropertyDescriptor(globalThis, "isSecureContext")

const randomDescriptor = Object.getOwnPropertyDescriptor(Math, "random")

const setCrypto = (value: Partial<Crypto>) => {
  Object.defineProperty(globalThis, "crypto", {
    configurable: true,
    value: value as Crypto,
  })
}

const setSecure = (value: boolean) => {
  Object.defineProperty(globalThis, "isSecureContext", {
    configurable: true,
    value,
  })
}

const setRandom = (value: () => number) => {
  Object.defineProperty(Math, "random", {
    configurable: true,
    value,
  })
}

afterEach(() => {
  if (cryptoDescriptor) {
    Object.defineProperty(globalThis, "crypto", cryptoDescriptor)
  }

  if (secureDescriptor) {
    Object.defineProperty(globalThis, "isSecureContext", secureDescriptor)
  }

  if (!secureDescriptor) {
    delete (globalThis as { isSecureContext?: boolean }).isSecureContext
  }

  if (randomDescriptor) {
    Object.defineProperty(Math, "random", randomDescriptor)
  }
})

describe("uuid", () => {
  test("uses randomUUID in secure contexts", () => {
    setCrypto({ randomUUID: () => "00000000-0000-0000-0000-000000000000" })
    setSecure(true)
    expect(uuid()).toBe("00000000-0000-0000-0000-000000000000")
  })

  const fallbacks: { name: string; secure: boolean; crypto: Partial<Crypto> }[] = [
    {
      name: "in insecure contexts",
      secure: false,
      crypto: { randomUUID: () => "00000000-0000-0000-0000-000000000000" },
    },
    {
      name: "when randomUUID throws",
      secure: true,
      crypto: {
        randomUUID: () => {
          throw new DOMException("Failed", "OperationError")
        },
      },
    },
    { name: "when randomUUID is unavailable", secure: true, crypto: {} },
  ]

  test.each(fallbacks)("falls back $name", (row) => {
    setCrypto(row.crypto)
    setSecure(row.secure)
    setRandom(() => 0.5)
    expect(uuid()).toBe("8")
  })
})

const fallback = () => Math.random().toString(16).slice(2)

export function uuid() {
  const c = globalThis.crypto

  if (!c || typeof c.randomUUID !== "function") return fallback()

  if (typeof globalThis.isSecureContext === "boolean" && !globalThis.isSecureContext) return fallback()

  try {
    return c.randomUUID()
  } catch {
    return fallback()
  }
}

