import { createSimpleContext } from "@opencode/ui/context"
import { batch, createMemo } from "solid-js"
import { type SetStoreFunction, type Store } from "solid-js/store"
import { Persist, persisted } from "@/runtime/persistence/storage"
import { pathKey } from "@/workspaces/path-key"
import { ServerScope } from "@/runtime/server/scope"
import type { ServerEntry } from "@opencode/gui-extensions/sdk"
import { ServerHttp, ServerHttpBase, ServerKey, serverState } from "./persistence"

type ServerState = ReturnType<typeof serverState>["current"]["Type"]

// Retain closed paths until reopened so settings can exclude them from the server inventory.
// The Home page independently limits the visible recently closed entries.
export const RECENTLY_CLOSED_DISPLAY_LIMIT = 5

export function normalizeServerUrl(input: string) {
  const trimmed = input.trim()

  if (!trimmed) return
  const withProtocol = /^https?:\/\//.test(trimmed) ? trimmed : `http://${trimmed}`

  return withProtocol.replace(/\/+$/, "")
}

export function serverName(conn?: ServerConnection.Any, ignoreDisplayName = false) {
  if (!conn) return ""

  if (conn.displayName && !ignoreDisplayName) return conn.displayName

  return conn.http.url.replace(/^https?:\/\//, "").replace(/\/+$/, "")
}

function isLocalHost(url: string) {
  const host = url.replace(/^https?:\/\//, "").split(":")[0]

  if (host === "localhost" || host === "127.0.0.1") return "local"
}

export function createServerProjects(input: {
  scope: () => ServerScope
  store: Store<ServerState>
  setStore: SetStoreFunction<ServerState>
}) {
  const setStore = input.setStore
  const current = () => input.store.projects[input.scope()] ?? []
  const currentClosed = () => input.store.recentlyClosed?.[input.scope()] ?? []

  const remove = (directory: string) => {
    setStore(
      "projects",
      input.scope(),
      current().filter((project) => project.worktree !== directory),
    )
  }

  return {
    list: current,
    closed: currentClosed,
    recentlyClosed: currentClosed,
    remove,
    open(directory: string) {
      const scope = input.scope()
      const key = pathKey(directory)
      const closed = currentClosed()

      if (closed.some((worktree) => pathKey(worktree) === key)) {
        setStore(
          "recentlyClosed",
          scope,
          closed.filter((worktree) => pathKey(worktree) !== key),
        )
      }

      if (current().some((project) => project.worktree === directory)) return
      setStore("projects", scope, [{ worktree: directory, expanded: true }, ...current()])
    },
    // User-initiated close: removes the project and records it in recently closed.
    // Internal, non-user removals (e.g. sandbox/worktree normalization) should use remove().
    close(directory: string) {
      remove(directory)
      const key = pathKey(directory)
      const closed = [directory, ...currentClosed().filter((worktree) => pathKey(worktree) !== key)]
      setStore("recentlyClosed", input.scope(), closed)
    },
    expand(directory: string) {
      const index = current().findIndex((project) => project.worktree === directory)

      if (index !== -1) setStore("projects", input.scope(), index, "expanded", true)
    },
    collapse(directory: string) {
      const index = current().findIndex((project) => project.worktree === directory)

      if (index !== -1) setStore("projects", input.scope(), index, "expanded", false)
    },
    move(directory: string, toIndex: number) {
      const fromIndex = current().findIndex((project) => project.worktree === directory)

      if (fromIndex === -1 || fromIndex === toIndex) return
      const next = [...current()]
      const [item] = next.splice(fromIndex, 1)
      next.splice(toIndex, 0, item)
      setStore("projects", input.scope(), next)
    },
    last() {
      return input.store.lastProject[input.scope()]
    },
    touch(directory: string) {
      setStore("lastProject", input.scope(), directory)
    },
  }
}

export function resolveServerList(input: {
  props?: Array<ServerConnection.Any>
  stored: ServerConnection.Http[]
}): Array<ServerConnection.Any> {
  const deduped = new Map<ServerConnection.Key, ServerConnection.Any>(
    input.props?.map((v) => [ServerConnection.key(v), v]) ?? [],
  )

  for (const conn of input.stored) {
    const key = ServerConnection.key(conn)

    const existing = deduped.get(key)

    if (existing)
      deduped.set(key, {
        ...existing,
        ...conn,
        http: { ...existing.http, ...conn.http },
      })
    else deduped.set(key, conn)
  }

  return [...deduped.values()]
}

export function canRemoveServer(input: {
  key: ServerConnection.Key
  provided?: Array<ServerConnection.Any>
  stored: ServerConnection.Http[]
}) {
  if (input.provided?.some((server) => ServerConnection.key(server) === input.key)) return false

  return input.stored.some((server) => server.http.url === input.key)
}

export namespace ServerConnection {
  type Base = { displayName?: string; label?: string }

  export type HttpBase = typeof ServerHttpBase.Type

  // Regular web connections
  export type Http = typeof ServerHttp.Type

  // Regular desktop server
  export type Sidecar = {
    type: "sidecar"
    variant: "base"
    http: HttpBase
    reconnect?: (signal: AbortSignal) => Promise<HttpBase>
  } & Base

  // A server a GUI extension contributes (e.g. SSH or WSL), keyed `${extension}:${id}`
  export type Extension = {
    type: "extension"
    key: string
    extension: string
    state: ServerEntry["state"]
    connecting: boolean
    authenticationRequired: boolean
    /** The extension re-resolves the endpoint (e.g. a tunnel), so the connection can drop and come back. */
    managed: boolean
    http: HttpBase
    reconnect?: (signal: AbortSignal) => Promise<HttpBase>
    /** Called before opening a server that is not ready. Resolves true once it is. */
    connect?: () => Promise<boolean>
  } & Base

  export type Any =
    | Http
    // All these are desktop-only
    | (Sidecar | Extension)

  export const key = (conn: Any): Key => {
    switch (conn.type) {
      case "http":
        return Key.make(conn.http.url)
      case "sidecar":
        return Key.make("sidecar")
      case "extension":
        return Key.make(conn.key)
    }
  }

  export const Key = ServerKey
  export type Key = typeof Key.Type

  export const builtin = (conn: Any) => conn.type === "sidecar" && conn.variant === "base"
  /** Starts sign-in for a server that asks for it; false when it does not. */
  export const authenticate = (conn: Any, onConnected?: () => void) => {
    if (conn.type !== "extension" || !conn.authenticationRequired || !conn.connect) return false
    void conn.connect().then((ready) => {
      if (ready) onConnected?.()
    })

    return true
  }

  export const local = (conn?: Any) =>
    !!conn && (builtin(conn) || (conn.type === "http" && isLocalHost(conn.http.url) === "local"))
}

export const { use: useServers, provider: ServersProvider } = createSimpleContext({
  name: "Server",
  gate: true,
  init: (props: { canonicalLocalServer?: ServerConnection.Key; servers?: Array<ServerConnection.Any> }) => {
    const [store, setStore, _, hydrated] = persisted(
      {
        ...Persist.global("server"),
        sync: true,
        previousKey: "server.v3",
      },
      serverState(() => props.canonicalLocalServer),
      { list: [], hidden: {}, projects: {}, lastProject: {}, recentlyClosed: {} },
    )

    const allServers = createMemo((): Array<ServerConnection.Any> => {
      return resolveServerList({ stored: store.list, props: props.servers })
    })

    const visibleServers = createMemo(() => allServers().filter((conn) => !store.hidden[ServerConnection.key(conn)]))

    function add(input: ServerConnection.Http) {
      const url_ = normalizeServerUrl(input.http.url)

      if (!url_) return
      const conn: ServerConnection.Http = { ...input, authToken: undefined, http: { ...input.http, url: url_ } }

      return batch(() => {
        const existing = store.list.findIndex((x) => x.http.url === url_)

        if (existing !== -1) {
          setStore("list", existing, conn)
        } else {
          setStore("list", store.list.length, conn)
        }

        return conn
      })
    }

    function remove(key: ServerConnection.Key) {
      const list = store.list.filter((x) => x.http.url !== key)
      batch(() => {
        setStore("list", list)
      })
    }

    function canRemove(key: ServerConnection.Key) {
      return canRemoveServer({ key, provided: props.servers, stored: store.list })
    }

    const scope = (key: ServerConnection.Key) => ServerScope.fromServerKey(key, props.canonicalLocalServer)
    const projectStores = new Map<ServerConnection.Key, ReturnType<typeof createServerProjects>>()

    const projectsForServer = (key: ServerConnection.Key) => {
      const existing = projectStores.get(key)

      if (existing) return existing
      const next = createServerProjects({ scope: () => scope(key), store, setStore })
      projectStores.set(key, next)

      return next
    }

    return {
      get list() {
        return allServers()
      },
      get visible() {
        return visibleServers()
      },
      // Named to avoid the context `ready` gate: consumers that derive from persisted project
      // state wait on this, but the provider must not block first render on storage.
      hydrated,
      isHidden(key: ServerConnection.Key) {
        return store.hidden[key] ?? false
      },
      setHidden(key: ServerConnection.Key, hidden: boolean) {
        setStore("hidden", key, hidden)
      },
      add,
      remove,
      canRemove,
      scope,
      projects: {
        forServer: projectsForServer,
      },
    }
  },
})

import { describe, expect, test } from "bun:test"
import { createRequestQueue } from "./request-queue"

function setup(input?: {
  limit?: number
  slowLimit?: number
  stallMs?: number
  headersTimeoutMs?: number
  setupHeadersTimeoutMs?: number
}) {
  const pending: Array<{ url: string; signal: AbortSignal; resolve: () => void }> = []
  const logs: Array<{ message: string; data: Record<string, unknown> }> = []
  let clock = 0

  const queue = createRequestQueue({
    limit: input?.limit ?? 2,
    slowLimit: input?.slowLimit,
    stallMs: input?.stallMs,
    headersTimeoutMs: input?.headersTimeoutMs,
    setupHeadersTimeoutMs: input?.setupHeadersTimeoutMs,
    now: () => clock,
    log: (message, data) => logs.push({ message, data }),
    fetch: Object.assign(
      (resource: RequestInfo | URL, init?: RequestInit) =>
        new Promise<Response>((resolve, reject) => {
          const request = new Request(resource, init)
          request.signal.addEventListener("abort", () => reject(request.signal.reason), { once: true })
          pending.push({ url: request.url, signal: request.signal, resolve: () => resolve(new Response("ok")) })
        }),
      { preconnect() {} },
    ),
  })

  const settle = () => new Promise<void>((resolve) => setTimeout(resolve, 0))

  return { queue, pending, logs, settle, tick: (ms: number) => (clock += ms) }
}

describe("createRequestQueue", () => {
  test("starts a free slot before the caller continues its synchronous work", async () => {
    const input = setup()
    const response = input.queue.fetch("http://server/api/session")
    expect(input.pending.map((item) => new URL(item.url).pathname)).toEqual(["/api/session"])
    expect(input.queue.inflight()).toBe(1)
    input.pending[0]!.resolve()
    await response
    expect(input.queue.inflight()).toBe(0)
  })

  test("releases a free slot without sending an already-aborted request", async () => {
    const input = setup()
    const controller = new AbortController()
    controller.abort()
    await expect(input.queue.fetch("http://server/api/session", { signal: controller.signal })).rejects.toBeInstanceOf(
      DOMException,
    )
    expect(input.pending).toHaveLength(0)
    expect(input.queue.inflight()).toBe(0)
  })

  test("caps concurrent requests and starts queued ones as slots free up", async () => {
    const input = setup()
    const responses = ["/api/a", "/api/b", "/api/c"].map((path) => input.queue.fetch(`http://server${path}`))
    await input.settle()
    expect(input.pending.map((item) => new URL(item.url).pathname)).toEqual(["/api/a", "/api/b"])
    expect(input.queue.queued()).toBe(1)
    input.pending[0]!.resolve()
    await input.settle()
    expect(input.pending.map((item) => new URL(item.url).pathname)).toEqual(["/api/a", "/api/b", "/api/c"])
    input.pending.forEach((item) => item.resolve())
    await Promise.all(responses)
    expect(input.queue.inflight()).toBe(0)
  })

  test("slow endpoints hold at most their share of slots so small reads go first", async () => {
    const input = setup({ limit: 4, slowLimit: 2 })

    const paths = [
      "/api/vcs?location[directory]=%2Fa",
      "/api/vcs/diff?location[directory]=%2Fa",
      "/api/worktree",
      "/api/session/ses_1",
      "/api/vcsx",
    ]

    const responses = paths.map((path) => input.queue.fetch(`http://server${path}`))
    await input.settle()
    const started = () => input.pending.map((item) => new URL(item.url).pathname)
    // Two slow requests fill the slow share; the worktree read waits while the fast reads jump ahead.
    expect(started()).toEqual(["/api/vcs", "/api/vcs/diff", "/api/session/ses_1", "/api/vcsx"])
    expect(input.queue.inflight()).toBe(4)
    expect(input.queue.queued()).toBe(1)
    // A fast request finishing does not free a slow slot.
    input.pending[2]!.resolve()
    await input.settle()
    expect(started()).toEqual(["/api/vcs", "/api/vcs/diff", "/api/session/ses_1", "/api/vcsx"])
    input.pending[0]!.resolve()
    await input.settle()
    expect(started()).toEqual(["/api/vcs", "/api/vcs/diff", "/api/session/ses_1", "/api/vcsx", "/api/worktree"])
    input.pending.forEach((item) => item.resolve())
    await Promise.all(responses)
    expect(input.queue.inflight()).toBe(0)
  })

  test("never counts the event stream against the budget", async () => {
    const input = setup({ limit: 1 })
    void input.queue.fetch("http://server/api/session")
    void input.queue.fetch("http://server/api/event")
    await input.settle()
    expect(input.pending.map((item) => new URL(item.url).pathname).toSorted()).toEqual(["/api/event", "/api/session"])
    expect(input.queue.inflight()).toBe(1)
  })

  test("aborted requests leave the queue without being sent", async () => {
    const input = setup({ limit: 1 })
    const controller = new AbortController()
    void input.queue.fetch("http://server/api/first")
    const aborted = input.queue.fetch("http://server/api/second", { signal: controller.signal })
    controller.abort()
    await input.settle()
    input.pending[0]!.resolve()
    await expect(aborted).rejects.toBeInstanceOf(DOMException)
    expect(input.pending.map((item) => new URL(item.url).pathname)).toEqual(["/api/first"])
    expect(input.queue.inflight()).toBe(0)
  })

  test("a request the server never answers times out and frees its slot", async () => {
    const input = setup({ limit: 1, headersTimeoutMs: 10 })
    const dead = input.queue.fetch("http://server/api/dead")
    const next = input.queue.fetch("http://server/api/next")
    expect(input.queue.queued()).toBe(1)
    const error = await dead.catch((cause: unknown) => cause)
    expect(error).toBeInstanceOf(DOMException)
    expect((error as DOMException).name).toBe("TimeoutError")
    expect(input.pending.map((item) => new URL(item.url).pathname)).toEqual(["/api/dead", "/api/next"])
    input.pending[1]!.resolve()
    await expect(next).resolves.toBeInstanceOf(Response)
    expect(input.queue.inflight()).toBe(0)
  })

  test("worktree creation gets the setup deadline while other worktree requests keep the normal one", async () => {
    const input = setup({ limit: 4, slowLimit: 4, headersTimeoutMs: 10, setupHeadersTimeoutMs: 200 })
    const create = input.queue.fetch("http://server/api/worktree?location[directory]=%2Fa", { method: "POST" })

    const others = [
      input.queue.fetch("http://server/api/worktree?location[directory]=%2Fa"),
      input.queue.fetch("http://server/api/worktree/refresh?location[directory]=%2Fa", { method: "POST" }),
      input.queue.fetch("http://server/api/worktree?location[directory]=%2Fa", { method: "DELETE" }),
    ]

    const errors = await Promise.all(others.map((request) => request.catch((cause: unknown) => cause)))
    expect(errors.map((error) => (error as DOMException).name)).toEqual([
      "TimeoutError",
      "TimeoutError",
      "TimeoutError",
    ])
    // Past the normal deadline, the create is still on the wire.
    expect(input.pending[0]!.signal.aborted).toBe(false)
    input.pending[0]!.resolve()
    await expect(create).resolves.toBeInstanceOf(Response)
    expect(input.queue.inflight()).toBe(0)
  })

  test("caller aborts still reach the underlying request", async () => {
    const input = setup({ limit: 1 })
    const controller = new AbortController()
    const request = input.queue.fetch("http://server/api/slow", { signal: controller.signal })
    await input.settle()
    expect(input.pending[0]!.signal.aborted).toBe(false)
    controller.abort()
    expect(input.pending[0]!.signal.aborted).toBe(true)
    await expect(request).rejects.toBeInstanceOf(DOMException)
    expect(input.queue.inflight()).toBe(0)
  })

  test("a burst that drains promptly is not thrashing", async () => {
    const input = setup({ stallMs: 5 })
    const responses = Array.from({ length: 12 }, (_, index) => input.queue.fetch(`http://server/api/${index}`))
    await input.settle()
    expect(input.queue.queued()).toBe(10)

    // Drain two at a time before the stall threshold elapses.
    for (let round = 0; round < 6; round++) {
      input.pending.splice(0).forEach((item) => item.resolve())
      await input.settle()
    }

    await Promise.all(responses)
    await new Promise((resolve) => setTimeout(resolve, 20))
    expect(input.logs).toEqual([])
  })

  test("logs what is in flight and queued once per burst after requests stall", async () => {
    const input = setup({ stallMs: 5 })
    input.queue.fetch("http://server/api/worktree?location[directory]=%2Fa").catch(() => undefined)
    input.tick(50)
    input.queue.fetch("http://server/api/worktree?location[directory]=%2Fb").catch(() => undefined)
    input.tick(50)
    input.queue.fetch("http://server/api/worktree?location[directory]=%2Fc").catch(() => undefined)
    input.tick(100)
    input.queue.fetch("http://server/api/info").catch(() => undefined)
    expect(input.logs).toEqual([])
    input.tick(2_000)
    await new Promise((resolve) => setTimeout(resolve, 20))
    expect(input.logs).toEqual([
      {
        message: "server thrashing detected",
        data: {
          limit: 2,
          inflight: [
            { method: "GET", url: "http://server/api/worktree?location[directory]=%2Fa", ms: 2_200 },
            { method: "GET", url: "http://server/api/worktree?location[directory]=%2Fb", ms: 2_150 },
          ],
          queued: [
            { method: "GET", url: "http://server/api/worktree?location[directory]=%2Fc", ms: 2_100 },
            { method: "GET", url: "http://server/api/info", ms: 2_000 },
          ],
        },
      },
    ])
    // Still stalled within the rate limit: no repeat.
    input.tick(2_000)
    await new Promise((resolve) => setTimeout(resolve, 20))
    expect(input.logs).toHaveLength(1)
    input.tick(10_000)
    await new Promise((resolve) => setTimeout(resolve, 20))
    expect(input.logs).toHaveLength(2)
  })
})

type Entry = { method: string; url: string; at: number; slow: boolean }

// Chromium allows six connections per origin. The event stream holds one for the life of the
// connection and health probes use their own fetch, so the app's API calls stay below that or
// a burst stalls probes and user actions inside the browser where nothing can observe it.
export const requestQueueLimit = 4

// Endpoints that shell out to git or walk the filesystem take seconds on a large repository. They
// may hold at most this many slots, so a session mount's small reads never queue behind them.
export const requestQueueSlowLimit = 2

export const slowRequestPaths = ["/api/vcs", "/api/worktree"]

// A mount legitimately fires a dozen requests at once; only a request that has waited this long
// for a slot indicates the server is not keeping up.
export const requestStallMs = 2_000

// A socket that dies while the device sleeps can leave fetch waiting for response headers until the
// OS gives up on TCP retransmits, which takes minutes. Bound that so a dead request frees its slot
// instead of wedging every later API call; the body may still stream for as long as it needs.
export const requestHeadersTimeoutMs = 60_000

// Creating a worktree runs the project's setup script (dependency installs, fetches) before the
// server answers, so it needs a budget measured in minutes rather than seconds. Cutting it off
// kills the script midway and leaves a registered but half-initialised worktree behind.
export const setupRequestHeadersTimeoutMs = 10 * 60_000

function isSlowRequest(pathname: string) {
  return slowRequestPaths.some((path) => pathname === path || pathname.startsWith(`${path}/`))
}

function isSetupRequest(method: string, pathname: string) {
  return method === "POST" && pathname === "/api/worktree"
}

export function createRequestQueue(input: {
  fetch: typeof globalThis.fetch
  limit?: number
  slowLimit?: number
  stallMs?: number
  headersTimeoutMs?: number
  setupHeadersTimeoutMs?: number
  log?: (message: string, data: Record<string, unknown>) => void
  now?: () => number
}) {
  const limit = input.limit ?? requestQueueLimit
  const slowLimit = input.slowLimit ?? requestQueueSlowLimit
  const stallMs = input.stallMs ?? requestStallMs
  const headersTimeoutMs = input.headersTimeoutMs ?? requestHeadersTimeoutMs
  const setupHeadersTimeoutMs = input.setupHeadersTimeoutMs ?? setupRequestHeadersTimeoutMs
  // Call the browser fetch unbound; `input.fetch(...)` would make `this` the options object.
  const base = input.fetch
  const now = input.now ?? Date.now
  const log = input.log ?? ((message, data) => console.warn(`[server-request-queue] ${message}`, data))
  const inflight = new Set<Entry>()
  const waiting: Array<{ entry: Entry; start: () => void }> = []
  let warned = -Infinity
  let watcher: ReturnType<typeof setTimeout> | undefined

  const describe = (entry: Entry) => ({ method: entry.method, url: entry.url, ms: now() - entry.at })

  // Debug exports include the console, so list what the server is busy with while requests wait.
  const watch = () => {
    watcher = undefined
    const oldest = waiting[0]?.entry

    if (!oldest) return

    if (now() - oldest.at >= stallMs && now() - warned >= 10_000) {
      warned = now()
      log("server thrashing detected", {
        limit,
        inflight: [...inflight].map(describe),
        queued: waiting.map((item) => describe(item.entry)),
      })
    }

    watcher = setTimeout(watch, stallMs)
  }

  const canStart = (entry: Entry) => {
    if (inflight.size >= limit) return false

    if (!entry.slow) return true

    return [...inflight].filter((item) => item.slow).length < slowLimit
  }

  // FIFO, except a slow request waits its turn behind faster ones while the slow slots are full.
  const release = (entry: Entry) => {
    inflight.delete(entry)
    const index = waiting.findIndex((item) => canStart(item.entry))

    if (index === -1) return
    waiting.splice(index, 1)[0]?.start()
  }

  const acquire = (entry: Entry) => {
    // A free slot must start fetch before the caller's synchronous UI work.
    // Awaiting an already-resolved promise postpones that dispatch until after it.
    if (canStart(entry)) {
      inflight.add(entry)

      return
    }

    return new Promise<void>((resolve) => {
      const start = () => {
        entry.at = now()
        inflight.add(entry)
        resolve()
      }

      waiting.push({ entry, start })
      watcher ??= setTimeout(watch, stallMs)
    })
  }

  const fetch: typeof globalThis.fetch = Object.assign(
    async (resource: RequestInfo | URL, init?: RequestInit) => {
      const request = new Request(resource, init)
      const pathname = new URL(request.url).pathname

      // The event stream is long-lived; never count it against the request budget.
      if (pathname === "/api/event") return base(request)
      const entry = { method: request.method, url: request.url, at: now(), slow: isSlowRequest(pathname) }
      const queued = acquire(entry)

      if (queued) await queued

      if (request.signal.aborted) {
        release(entry)
        throw request.signal.reason ?? new DOMException("The operation was aborted.", "AbortError")
      }

      const controller = new AbortController()
      request.signal.addEventListener("abort", () => controller.abort(request.signal.reason), { once: true })

      const timer = setTimeout(
        () => controller.abort(new DOMException("Timed out waiting for the server to respond", "TimeoutError")),
        isSetupRequest(request.method, pathname) ? setupHeadersTimeoutMs : headersTimeoutMs,
      )

      return base(new Request(request, { signal: controller.signal })).finally(() => {
        clearTimeout(timer)
        release(entry)
      })
    },
    // Bun's fetch type carries preconnect; the browser never calls it.
    { preconnect: () => {} },
  )

  return {
    fetch,
    inflight: () => inflight.size,
    queued: () => waiting.length,
  }
}

import { createSimpleContext } from "@opencode/ui/context"
import { Accessor, batch, createEffect, createMemo, createResource, createRoot, getOwner, untrack } from "solid-js"
import { createServerProjects, RECENTLY_CLOSED_DISPLAY_LIMIT, ServerConnection, useServers } from "./registry"
import { pathKey } from "@/workspaces/path-key"
import { useServerHealth } from "@/runtime/server/health"
import { createServerSdkContext } from "./client"
import { createServerSyncContext } from "./sync"
import { createData } from "@opencode/client/solid"
import type { ServerScope } from "@/runtime/server/scope"
import { createPermissionAutoApprover } from "@/session/requests/auto-approve"
import { createServerNotificationState } from "@/shell/notifications/notification"
import { createNotificationCoordinator } from "@/shell/notifications/coordinator"
import { Persist, persisted } from "@/runtime/persistence/storage"
import { createDesktopData } from "./data"
import { ModelState } from "./persistence"
import { useLanguage } from "@/runtime/i18n/language"
import { showToast } from "@/shell/notifications/toast"
import { formatServerError } from "./errors"
import { useSettings } from "@/settings/model"
import { timelinePreset } from "@opencode/session-ui/timeline/detail"
import type { SessionInfo } from "@opencode/client/promise"
import { resolveProjectForSession, resolveSessionDetailsProject } from "@/shell/layout/helpers"

export const { use: useGlobal, provider: GlobalProvider } = createSimpleContext({
  name: "Global",
  init: () => {
    const server = useServers()

    const serverHealth = useServerHealth(
      () => server.list,
      () => true,
    )

    const models = createGlobalModels()
    const notificationCoordinator = createNotificationCoordinator()

    const serverCtxs = new Map<ServerConnection.Key, ReturnType<typeof createServerController>>()
    const serverCtxDisposers = new Map<ServerConnection.Key, () => void>()
    // The credentials each controller started with, as plain values: the listed connection is a store proxy that
    // already reads the new password once the user saves it.
    const serverCtxCredentials = new Map<ServerConnection.Key, string>()

    const owner = getOwner()

    if (!owner) throw new Error("Global provider requires a Solid owner")

    const disposeServerCtx = (key: ServerConnection.Key) => {
      serverCtxDisposers.get(key)?.()
      serverCtxDisposers.delete(key)
      serverCtxCredentials.delete(key)
      serverCtxs.delete(key)
    }

    const ensureServerCtx = (input: ServerConnection.Any) => {
      const key = ServerConnection.key(input)
      // Callers can hold an older copy of the connection; the listed one has the credentials the user saved last.
      const conn = untrack(() => server.list.find((item) => ServerConnection.key(item) === key)) ?? input
      const existing = serverCtxs.get(key)

      if (existing && serverCtxCredentials.get(key) === credentials(conn)) return existing

      // A controller keeps the credentials it started with, so a server signed in again under the same address needs
      // a new one.
      if (existing) disposeServerCtx(key)

      const serverCtx = createRoot((dispose) => {
        serverCtxDisposers.set(key, dispose)

        return createServerController(conn, server.scope(key), server.projects.forServer(key), notificationCoordinator)
      }, owner)

      serverCtxs.set(key, serverCtx)
      serverCtxCredentials.set(key, credentials(conn))

      return serverCtx
    }

    // A server that rejects our credentials would retry its event stream every second with the same
    // credentials, so its controller waits until health recovers and then starts with the current ones.
    createMemo(() => {
      for (const conn of server.list) {
        if (serverHealth[ServerConnection.key(conn)]?.unauthorized) continue
        ensureServerCtx(conn)
      }
    })

    createEffect(() => {
      for (const [key] of serverCtxs) {
        if (serverHealth[key]?.unauthorized || !server.list.find((conn) => ServerConnection.key(conn) === key))
          disposeServerCtx(key)
      }
    })

    return {
      servers: {
        list: () => server.list,
        health: serverHealth,
      },
      models,
      ensureServerCtx(conn: ServerConnection.Any) {
        return ensureServerCtx(conn)
      },
      /** The live controller of a server, or undefined while it is unlisted or rejects our credentials. Reactive. */
      serverCtx(key: ServerConnection.Key) {
        const conn = server.list.find((item) => ServerConnection.key(item) === key)

        if (!conn || serverHealth[key]?.unauthorized) return

        return ensureServerCtx(conn)
      },
    }
  },
})

function createGlobalModels() {
  const [store, setStore, _, ready] = persisted(Persist.global("model"), ModelState, {
    user: [],
    recent: [],
    variant: {},
  })

  // Suspend readers only until persisted state loads. Refetching on every change would put the
  // session route into its Suspense fallback, detaching the screen and resetting the timeline scroll.
  const [loaded] = createResource(async () => {
    await ready.promise

    return true
  })

  return {
    store,
    set: setStore,
    ready,
    recent: () => {
      loaded()

      return store.recent
    },
    // Marks models visible in the picker regardless of the "latest per family" default.
    show(models: ReadonlyArray<{ providerID: string; modelID: string }>) {
      const seen = new Map(store.user.map((item, index) => [`${item.providerID}:${item.modelID}`, index]))
      batch(() => {
        for (const model of models) {
          const index = seen.get(`${model.providerID}:${model.modelID}`)

          if (index !== undefined) {
            setStore("user", index, "visibility", "show")
            continue
          }

          seen.set(`${model.providerID}:${model.modelID}`, store.user.length)
          setStore("user", store.user.length, {
            providerID: model.providerID,
            modelID: model.modelID,
            visibility: "show",
          })
        }
      })
    },
  }
}

function createServerController(
  conn: ServerConnection.Any,
  scope: ServerScope,
  projects: ReturnType<typeof createServerProjects>,
  notificationCoordinator: ReturnType<typeof createNotificationCoordinator>,
) {
  const language = useLanguage()
  const settings = useSettings()
  const connKey = ServerConnection.key(conn)
  const sdk = createServerSdkContext(conn, scope)

  const source = createData({
    api: () => sdk.api,
    initialMessageLimit: () => (timelinePreset(settings.general.timelineDetail())?.id === "compact" ? 40 : 20),
    event: {
      on: sdk.event.on,
      listen: (handler) => sdk.event.listen((event) => handler({ name: event.type, details: event })),
    },
    connection: sdk.connection,
    directory: "",
    onError(error) {
      showToast({
        variant: "error",
        title: language.t("common.requestFailed"),
        description: formatServerError(error, language.t),
      })
    },
  })

  const data = createDesktopData({
    data: source,
    remove: (sessionID) => sdk.api.session.remove({ sessionID }),
  })

  const sync = createServerSyncContext(sdk, data)
  createPermissionAutoApprover({ sdk, data })
  const notification = createServerNotificationState({ sdk, data, key: connKey, coordinator: notificationCoordinator })

  function enrich(project: { worktree: string; expanded: boolean }) {
    const [childStore] = sync.child(project.worktree, { bootstrap: false })
    const projectID = childStore.project

    const metadata = projectID
      ? sync.data.project.find((x) => x.id === projectID)
      : sync.data.project.find((x) => x.worktree === project.worktree)

    // Preserve local icon override from per-workspace localStorage cache (childStore.icon).
    // Without this, different subdirectories of the same git repo would share the same
    // icon from the database instead of using their individual overrides.
    const base = {
      ...metadata,
      ...(!metadata || metadata.id === "global" ? childStore.projectMeta : undefined),
      ...project,
    }

    if (childStore.icon) {
      return { ...base, icon: { ...base.icon, override: childStore.icon } }
    }

    return base
  }

  const projectsList = createMemo(() => projects.list().map(enrich))

  const forSession = (session: SessionInfo) => {
    const project = resolveProjectForSession(session, projectsList(), sync.data.project)

    if (!project) return

    return "expanded" in project ? project : { ...project, expanded: false }
  }

  const detailsForSession = (session: SessionInfo) =>
    resolveSessionDetailsProject(session, projectsList(), sync.data.project)

  const recentlyClosedList = createMemo(() => {
    const known = new Set(sync.data.project.map((project) => pathKey(project.worktree)))

    return projects
      .recentlyClosed()
      .filter((worktree) => known.has(pathKey(worktree)))
      .slice(0, RECENTLY_CLOSED_DISPLAY_LIMIT)
      .map((worktree) => enrich({ worktree, expanded: false }))
  })

  const isLocal =
    (conn?.type === "sidecar" && conn.variant === "base") || (conn?.type === "http" && isLocalHost(conn.http.url))

  return {
    data,
    sdk,
    sync,
    isLocal,
    projects: {
      ...projects,
      list: projectsList,
      forSession,
      detailsForSession,
      resolve: enrich,
      recentlyClosed: recentlyClosedList,
    },
    notification,
  }
}

export function useServerCtx(server: Accessor<ServerConnection.Any>): Accessor<ServerCtx>
export function useServerCtx(server: Accessor<ServerConnection.Any | undefined>): Accessor<ServerCtx | undefined>
export function useServerCtx(server: Accessor<ServerConnection.Any | undefined>) {
  const global = useGlobal()

  return () => {
    const s = server()

    if (s) return global.ensureServerCtx(s)
  }
}

export type ServerCtx = ReturnType<typeof createServerController>

function isLocalHost(url: string) {
  const host = url.replace(/^https?:\/\//, "").split(":")[0]

  if (host === "localhost" || host === "127.0.0.1") return "local"
}

/** What an HTTP server's controller authenticates with; other servers keep one controller per id. */
function credentials(conn: ServerConnection.Any) {
  return conn.type === "http" ? `${conn.http.url}\n${conn.http.password ?? ""}` : ""
}

