type FormMode = "list" | "add" | "edit"

export const DialogServer: Component<{
  mode: "add" | "edit"
  server?: ServerConnection.Http
  onSave?: (server: ServerConnection.Http) => void
}> = (props) => {
  const dialog = useDialog()
  const language = useLanguage()
  const platform = usePlatform()
  const camera = createCameraAvailability()

  const form = createFormController({
    // Close first: onSave may open the next dialog, such as the folder picker an interrupted action continues with.
    onSelect: (server) => {
      dialog.close()
      props.onSave?.(server)
    },
  })

  const [opened, setOpened] = createSignal(false)

  onMount(() => {
    if (props.mode === "add") form.start.add()

    if (props.mode === "edit" && props.server) form.start.edit(props.server)
    setOpened(true)
  })

  onCleanup(() => {
    form.reset()
  })

  createEffect(() => {
    if (!opened()) return

    if (form.state.open()) return
    dialog.close()
  })

  const keyDown = (event: KeyboardEvent) => {
    if (event.key !== "Enter" || event.isComposing) return
    event.preventDefault()
    form.submit()
  }

  const title = () =>
    props.mode === "add" ? language.t("dialog.server.add.title") : language.t("dialog.server.edit.title")

  const error = () => (
    <Show when={form.state.error()}>
      <span id="dialog-server-error" class="settings-server-dialog-error" role="alert">
        {form.state.error()}
      </span>
    </Show>
  )

  const submitLabel = () => {
    if (form.state.busy()) return language.t("dialog.server.add.checking")

    if (props.mode === "add") return language.t("dialog.server.add.button")

    return language.t("common.save")
  }

  return (
    <Dialog fit class="settings-server-dialog">
      <DialogHeader hideClose={true}>
        <DialogTitle>{title()}</DialogTitle>
      </DialogHeader>
      <Divider />
      <DialogBody class="flex w-full min-w-0 flex-1 flex-col px-4 pt-4 pb-2">
        <Show
          when={!form.state.scanning()}
          fallback={
            <Suspense fallback={<p role="status">{language.t("server.connect.camera.starting")}</p>}>
              <PairingScanner
                onCancel={() => {
                  form.scan.stop()
                  void camera.refetch()
                }}
                redeem={form.scan.redeem}
                onScan={form.scan.complete}
              />
            </Suspense>
          }
        >
          <div class="flex w-full min-w-0 flex-col gap-6">
            <Show when={form.state.signedOut()}>
              <p class="settings-server-dialog-notice" role="status">
                <Icon name="lock" size="small" />
                <span>{language.t("dialog.server.signedOut")}</span>
              </p>
            </Show>
            <Show
              when={form.state.method() === "password"}
              fallback={
                <div class="flex w-full min-w-0 flex-col gap-2">
                  <label for="dialog-server-link" class="settings-server-dialog-label">
                    {language.t("server.connect.link")}
                  </label>
                  <TextInput
                    id="dialog-server-link"
                    type="text"
                    appearance="large"
                    class="!w-full self-stretch"
                    dir="ltr"
                    spellcheck={false}
                    autocapitalize="off"
                    value={form.state.link()}
                    placeholder={language.t("server.connect.link.placeholder")}
                    invalid={!!form.state.error()}
                    disabled={form.state.busy()}
                    autofocus
                    aria-describedby={form.state.error() ? "dialog-server-error" : undefined}
                    onInput={(event) => form.change.link(event.currentTarget.value)}
                    onKeyDown={keyDown}
                  />
                  {error()}
                </div>
              }
            >
              <div class="flex w-full min-w-0 flex-col gap-2">
                <label for="dialog-server-url" class="settings-server-dialog-label">
                  {language.t("dialog.server.add.url")}
                </label>
                <TextInput
                  id="dialog-server-url"
                  type="text"
                  appearance="large"
                  class="!w-full self-stretch"
                  value={form.state.value()}
                  placeholder={language.t("dialog.server.add.placeholder")}
                  invalid={!!form.state.error()}
                  disabled={form.state.busy()}
                  autofocus
                  aria-describedby={form.state.error() ? "dialog-server-error" : undefined}
                  onInput={(event) => form.change.value(event.currentTarget.value)}
                  onKeyDown={keyDown}
                />
                {error()}
              </div>
            </Show>
            <div class="flex w-full min-w-0 flex-col gap-2">
              <label for="dialog-server-name" class="settings-server-dialog-label">
                {language.t("dialog.server.add.name")}
              </label>
              <TextInput
                id="dialog-server-name"
                type="text"
                appearance="large"
                class="!w-full self-stretch"
                value={form.state.name()}
                placeholder={language.t("dialog.server.add.namePlaceholder")}
                disabled={form.state.busy()}
                onInput={(event) => form.change.name(event.currentTarget.value)}
                onKeyDown={keyDown}
              />
            </div>
            <Show when={form.state.method() === "password"}>
              <div class="flex w-full min-w-0 flex-col gap-2">
                <label for="dialog-server-password" class="settings-server-dialog-label">
                  {language.t("dialog.server.add.password")}
                </label>
                <TextInput
                  id="dialog-server-password"
                  type="password"
                  appearance="large"
                  class="!w-full self-stretch"
                  value={form.state.password()}
                  placeholder={language.t("dialog.server.add.passwordPlaceholder")}
                  disabled={form.state.busy()}
                  aria-describedby="dialog-server-password-hint"
                  onInput={(event) => form.change.password(event.currentTarget.value)}
                  onKeyDown={keyDown}
                />
                <span id="dialog-server-password-hint" class="settings-server-dialog-hint">
                  {language.t("server.connect.password.hint")}
                </span>
              </div>
            </Show>
            <Show when={form.state.method() === "link" && platform.platform === "web"}>
              <Show
                when={camera.available.latest || camera.available.loading}
                fallback={<span class="settings-server-dialog-hint">{language.t(cameraHint())}</span>}
              >
                <Button
                  variant="neutral"
                  size="large"
                  class="!w-full self-stretch"
                  disabled={form.state.busy() || !camera.available.latest}
                  onClick={form.scan.start}
                >
                  {language.t("server.connect.scan")}
                </Button>
              </Show>
            </Show>
            <ConnectMethodSwitch
              method={form.state.method()}
              disabled={form.state.busy()}
              onChange={form.change.method}
            />
          </div>
        </Show>
      </DialogBody>
      <Show when={!form.state.scanning()}>
        <DialogFooter>
          <Button variant="neutral" disabled={form.state.busy()} onClick={() => dialog.close()}>
            {language.t("common.cancel")}
          </Button>
          <Button variant="contrast" disabled={form.state.busy()} onClick={form.submit}>
            {submitLabel()}
          </Button>
        </DialogFooter>
      </Show>
    </Dialog>
  )
}

function createFormController(options: { onSelect?: (server: ServerConnection.Http) => void } = {}) {
  const platform = usePlatform()
  const server = useServers()
  const tabs = useTabs()
  const global = useGlobal()
  const language = useLanguage()
  const checkServerHealth = useCheckServerHealth()
  const redeem = useRedeemPairing()
  const healthPreview = createServerHealthPreview(checkServerHealth)

  const [store, setStore] = createStore<{
    mode: FormMode
    method: ConnectMethod
    originalUrl: string | undefined
    link: string
    values: ServerFormValues
    scanning: boolean
    error: string
    status: boolean | undefined
  }>({
    mode: "list",
    method: "link",
    originalUrl: undefined,
    link: "",
    values: { url: "", name: "", password: "" },
    scanning: false,
    error: "",
    status: undefined,
  })

  onCleanup(healthPreview.cancel)

  const reset = () => {
    healthPreview.cancel()
    setStore({
      mode: "list",
      method: "link",
      originalUrl: undefined,
      link: "",
      values: { url: "", name: "", password: "" },
      scanning: false,
      error: "",
      status: undefined,
    })
  }

  const allServers = () => {
    return server.list
  }

  const editing = createMemo(() =>
    allServers().find((item) => item.type === "http" && item.http.url === store.originalUrl),
  )

  const add = (connection: ServerConnection.Http) => server.add(connection)

  const replace = (originalKey: ServerConnection.Key, next: ServerConnection.Http) =>
    replaceServerConnection(originalKey, next, {
      removeTabs: (key) => tabs.removeServer(key),
      add,
      remove: (key) => server.remove(key),
    })

  // A pairing token works on every address of its server. Signing in again to the edited server keeps its address
  // (e.g. localhost) even when the link names another one (e.g. 127.0.0.1 from opencode pair).
  const paired = async (pairing: Pairing) => {
    const original = store.mode === "edit" ? editing() : undefined

    if (!original || original.http.url === pairing.url) return pairing
    const http = { url: original.http.url, password: pairing.password }

    return (await checkServerHealth(http)).healthy ? http : pairing
  }

  // Where the form points: a scanned or pasted pairing link wins, else the address and password fields.
  const target = async (): Promise<ServerConnection.HttpBase | undefined> => {
    if (store.method === "link") {
      const redeemed = await redeem(store.link)

      if (redeemed && "error" in redeemed) return void setStore("error", redeemed.error)

      if (redeemed) return paired(redeemed.pairing)
      // A server address typed here belongs to the password form.
      const address = bareServerAddress(store.link)

      if (address) {
        setStore({ method: "password", link: "", values: { ...store.values, url: address } })
        preview()

        return
      }

      return void setStore("error", language.t("server.connect.link.invalid"))
    }

    // A pairing link pasted into the address field still pairs.
    const redeemed = await redeem(store.values.url)

    if (redeemed && "error" in redeemed) return void setStore("error", redeemed.error)

    if (redeemed) return paired(redeemed.pairing)
    const url = normalizeServerUrl(store.values.url)

    if (!url) return void reset()

    return { url, password: store.values.password || undefined }
  }

  const request = useMutation(() => ({
    mutationFn: async () => {
      const http = await target()

      if (!http) return
      const normalized = http.url
      const original = store.mode === "edit" ? editing() : undefined

      if (store.mode === "edit" && !original) return
      const name = store.values.name.trim() || undefined
      const password = http.password

      // Nothing changed: close, unless the server rejects these credentials, so saving checks them and the action that
      // asked for sign-in can continue.
      if (
        original?.type === "http" &&
        !global.servers.health[ServerConnection.key(original)]?.unauthorized &&
        normalized === original.http.url &&
        name === original.displayName &&
        password === original.http.password
      ) {
        reset()

        return
      }

      const connection: ServerConnection.Http = {
        type: "http",
        displayName: name,
        http: {
          url: normalized,
          password,
        },
      }

      const result = await checkServerHealth(connection.http)

      if (!result.healthy) {
        setStore(
          "error",
          language.t(
            platform.platform === "web" && isMixedContent(location.href, normalized)
              ? "server.connect.mixedContent"
              : "dialog.server.add.error",
          ),
        )

        return
      }

      if (original?.type === "http") {
        if (normalized === original.http.url) add(connection)

        if (normalized !== original.http.url) replace(ServerConnection.key(original), connection)
        reset()
        options.onSelect?.(connection)

        return
      }

      reset()
      add(connection)
      options.onSelect?.(connection)
    },
  }))

  const preview = () => {
    // A pairing link is not a server address until it is redeemed, and redeeming spends it.
    if (store.method === "link" || pairingLink(store.values.url)) {
      healthPreview.cancel()
      setStore("status", undefined)

      return
    }

    void healthPreview.preview(store.values, (status) => setStore("status", status))
  }

  const change = (field: keyof ServerFormValues, value: string) => {
    if (request.isPending) return
    setStore("values", field, value)
    setStore("error", "")

    if (field !== "name") preview()
  }

  const startAdd = () => {
    reset()
    setStore("mode", "add")
  }

  const startEdit = (connection: ServerConnection.Http) => {
    reset()
    setStore({
      mode: "edit",
      // A signed-out server needs a new pairing link; otherwise editing starts from its address.
      method: global.servers.health[ServerConnection.key(connection)]?.unauthorized ? "link" : "password",
      originalUrl: connection.http.url,
      values: {
        url: connection.http.url,
        name: connection.displayName ?? "",
        password: connection.http.password ?? "",
      },
      error: "",
      status: global.servers.health[ServerConnection.key(connection)]?.healthy,
    })
  }

  const submit = () => {
    if (store.mode === "list" || request.isPending) return
    setStore("error", "")
    request.mutate()
  }

  const pair = (link: string) => {
    healthPreview.cancel()
    setStore({ method: "link", link, scanning: false, error: "" })
    request.mutate()
  }

  createEffect(() => {
    if (store.mode !== "edit") return

    if (editing()) return
    reset()
  })

  return {
    state: {
      mode: () => store.mode,
      open: () => store.mode !== "list",
      adding: () => store.mode === "add",
      busy: () => request.isPending,
      method: () => store.method,
      link: () => store.link,
      value: () => store.values.url,
      name: () => store.values.name,
      password: () => store.values.password,
      scanning: () => store.scanning,
      error: () => store.error,
      status: () => store.status,
      signedOut: () => {
        const original = editing()

        return !!original && !!global.servers.health[ServerConnection.key(original)]?.unauthorized
      },
    },
    change: {
      method: (method: ConnectMethod) => {
        if (request.isPending) return
        setStore({ method, error: "" })
        preview()
      },
      link: (value: string) => {
        if (request.isPending) return
        setStore({ link: value, error: "" })
      },
      value: (value: string) => change("url", value),
      name: (value: string) => change("name", value),
      password: (value: string) => change("password", value),
    },
    scan: {
      start: () => setStore("scanning", true),
      stop: () => setStore("scanning", false),
      complete: pair,
      redeem,
    },
    start: { add: startAdd, edit: startEdit },
    reset,
    submit,
  }
}

import { Button } from "@opencode/ui/button"
import { useLanguage } from "@/runtime/i18n/language"

export type ConnectMethod = "link" | "password"

// Deliberately quiet, like the Console's API key switch: a pairing link is the way in, the password is the fallback.
export function ConnectMethodSwitch(props: {
  method: ConnectMethod
  disabled?: boolean
  onChange: (method: ConnectMethod) => void
}) {
  const language = useLanguage()
  const next = () => (props.method === "link" ? "password" : "link")

  return (
    <div
      data-component="server-connect-method"
      class="flex min-h-7 flex-wrap items-center justify-center gap-1 text-[13px]"
    >
      <span class="text-v2-text-text-faint">
        {language.t(props.method === "link" ? "server.connect.password.prompt" : "server.connect.link.prompt")}
      </span>
      <Button variant="ghost-muted" disabled={props.disabled} onClick={() => props.onChange(next())}>
        {language.t(props.method === "link" ? "server.connect.password.use" : "server.connect.link.use")}
      </Button>
    </div>
  )
}

import { describe, expect, test } from "bun:test"
import { bareServerAddress, legacyPairingLink, pairingLink } from "./pairing"

describe("pairing link", () => {
  test("reads the server address and code from opencode pair links", () => {
    expect(pairingLink(" http://192.168.1.2:49374/auth/connect/abc_DEF-123 ")).toEqual({
      urls: ["http://192.168.1.2:49374"],
      code: "abc_DEF-123",
    })
  })

  test("reads every server address from opencode pair QR codes", () => {
    expect(
      pairingLink(
        JSON.stringify({ code: "abc_DEF-123", urls: ["http://192.168.1.2:49374", "http://100.64.0.3:49374"] }),
      ),
    ).toEqual({
      urls: ["http://192.168.1.2:49374", "http://100.64.0.3:49374"],
      code: "abc_DEF-123",
    })
  })

  test("rejects other URLs", () => {
    expect(pairingLink("http://192.168.1.2:49374/auth/connect/")).toBeUndefined()
    expect(pairingLink("http://192.168.1.2:49374/auth/connect/abc/extra")).toBeUndefined()
    expect(pairingLink("http://192.168.1.2:49374/connect#abc")).toBeUndefined()
    expect(pairingLink("opencode-ios://auth/connect/abc")).toBeUndefined()
    expect(pairingLink("192.168.1.2:49374")).toBeUndefined()
  })

  test("rejects malformed QR payloads", () => {
    expect(pairingLink(JSON.stringify({ code: "abc", urls: [] }))).toBeUndefined()
    expect(pairingLink(JSON.stringify({ code: "a/b", urls: ["http://192.168.1.2:49374"] }))).toBeUndefined()
    expect(pairingLink(JSON.stringify({ code: "abc", urls: ["opencode-ios://host"] }))).toBeUndefined()
    expect(pairingLink(JSON.stringify({ urls: ["http://192.168.1.2:49374"] }))).toBeUndefined()
    expect(pairingLink("{not json")).toBeUndefined()
  })

  test("treats only a host without a path as a server address typed into the pairing link field", () => {
    expect(bareServerAddress("192.168.1.2:4096")).toBe("http://192.168.1.2:4096")
    expect(bareServerAddress("https://opencode.example.com/")).toBe("https://opencode.example.com")
    expect(bareServerAddress("localhost")).toBe("http://localhost")
    expect(bareServerAddress("devbox:4096")).toBe("http://devbox:4096")
    expect(bareServerAddress("[::1]:4096")).toBe("http://[::1]:4096")
    expect(bareServerAddress("abc_DEF-123")).toBeUndefined()
    expect(bareServerAddress("http://192.168.1.2:4096/auth/connect/")).toBeUndefined()
    expect(bareServerAddress("http://192.168.1.2:4096/auth/connect/…")).toBeUndefined()
    expect(bareServerAddress("http://192.168.1.2:4096/connect")).toBeUndefined()
  })

  test("recognizes the credential links that servers printed before one-time links", () => {
    expect(legacyPairingLink("http://192.168.1.2:49374/connect#eyJ1c2VybmFtZSI6Im9wZW5jb2RlIn0")).toBe(true)
    expect(legacyPairingLink("http://192.168.1.2:49374/connect?data=eyJ1c2VybmFtZSI6Im9wZW5jb2RlIn0")).toBe(true)
    expect(legacyPairingLink("http://192.168.1.2:49374/connect")).toBe(false)
    expect(legacyPairingLink("http://192.168.1.2:49374/auth/connect/abc")).toBe(false)
  })
})

import { isUnauthorizedError, OpenCode } from "@opencode/client/promise"
import { Option, Schema } from "effect"
import { checkServerHealth } from "@/runtime/server/health"
import { normalizeServerUrl } from "@/runtime/server/registry"

export function serverAddress(value: string) {
  if (value.includes("://") && !/^https?:\/\//.test(value.trim())) return
  const normalized = normalizeServerUrl(value)

  if (!normalized || !URL.canParse(normalized)) return
  const url = new URL(normalized)

  if (url.protocol !== "http:" && url.protocol !== "https:") return

  if (url.username || url.password || url.search || url.hash) return

  return normalized
}

const CODE = /^[A-Za-z0-9_-]+$/

const decodePayload = Schema.decodeUnknownOption(
  Schema.fromJsonString(Schema.Struct({ code: Schema.String, urls: Schema.Array(Schema.String) })),
)

// `opencode pair` prints links carrying a single-use code that the server exchanges for a session token.
// Its QR code carries the same code with every reachable server address as {"code","urls"} JSON.
export function pairingLink(value: string) {
  const trimmed = value.trim()

  if (trimmed.startsWith("{")) {
    const payload = Option.getOrUndefined(decodePayload(trimmed))

    if (!payload || !CODE.test(payload.code)) return
    const urls = [...new Set(payload.urls)].map(serverAddress)

    if (urls.length === 0 || urls.some((url) => url === undefined)) return

    return { urls: urls.filter((url) => url !== undefined), code: payload.code }
  }

  const url = URL.parse(trimmed)

  if (!url || (url.protocol !== "http:" && url.protocol !== "https:")) return
  const code = /^\/auth\/connect\/([^/]+)$/.exec(url.pathname)?.[1]
  const address = serverAddress(url.origin)

  if (!code || !CODE.test(code) || !address) return

  return { urls: [address], code }
}

// A server address typed where a pairing link was expected: a host with no path, so a bare code or a cut-off link
// is not mistaken for a server. Paths stay allowed in the password form, where servers behind a proxy prefix live.
export function bareServerAddress(value: string) {
  const address = serverAddress(value)

  if (!address) return
  const url = new URL(address)

  if (url.pathname !== "/") return

  if (url.hostname !== "localhost" && !url.hostname.includes(".") && !url.hostname.startsWith("[") && !url.port) return

  return address
}

// Servers before one-time links paired with `/connect#<credentials>` or `/connect?data=<credentials>`.
export function legacyPairingLink(value: string) {
  const url = URL.parse(value.trim())

  if (!url || (url.protocol !== "http:" && url.protocol !== "https:")) return false

  return url.pathname === "/connect" && (url.hash.length > 1 || url.searchParams.has("data"))
}

export type Pairing = { readonly url: string; readonly password: string }

export type Redeemed =
  | { readonly type: "paired"; readonly pairing: Pairing }
  | { readonly type: "expired" }
  | { readonly type: "unreachable" }

// Every address may reach the same server, but the code is single-use, so at most one attempt succeeds.
export function redeemPairingLink(link: { urls: ReadonlyArray<string>; code: string }) {
  const attempts = link.urls.map((url) =>
    OpenCode.make({ baseUrl: url })
      .server.connect({ code: link.code }, { signal: AbortSignal.timeout(5_000) })
      .then((session): Pairing => ({ url, password: session.token })),
  )

  // Whether the first address answered at all: a 401 there means another address spent the code first.
  const first = attempts[0]?.then(
    () => true,
    (error) => isUnauthorizedError(error),
  )

  return Promise.any(attempts)
    .then((pairing) => preferFirst(link.urls, pairing, first))
    .then(
      (pairing): Redeemed => ({ type: "paired", pairing }),
      // Only a server's answer proves the code is spent; addresses that could not be reached leave it valid.
      (error): Redeemed =>
        error instanceof AggregateError && error.errors.some(isUnauthorizedError)
          ? { type: "expired" }
          : { type: "unreachable" },
    )
}

// The token works on every address of the server, so keep the first one (the address the user chose in Pairing) when it
// answers, even if a nearer address answered sooner: a local network address stops working away from that network. An
// address that has not answered within a second, such as a local one seen from elsewhere, is not waited for.
async function preferFirst(
  urls: ReadonlyArray<string>,
  pairing: Pairing,
  answered: Promise<boolean> | undefined,
): Promise<Pairing> {
  const first = urls[0]

  if (!first || first === pairing.url || !answered) return pairing

  const reachable = await Promise.race([
    answered,
    new Promise<false>((resolve) => setTimeout(() => resolve(false), 1_000)),
  ])

  if (!reachable) return pairing
  const http = { url: first, password: pairing.password }
  const health = await checkServerHealth(http, globalThis.fetch, { signal: AbortSignal.timeout(5_000), retryCount: 0 })

  return health.healthy ? http : pairing
}

import { useLanguage } from "@/runtime/i18n/language"
import { usePlatform } from "@/runtime/platform/platform"
import { isMixedContent } from "./browser"
import { legacyPairingLink, pairingLink, redeemPairingLink, type Pairing } from "./pairing"

export type Redemption = { readonly pairing: Pairing } | { readonly error: string }

/** Redeems a pasted or scanned pairing link; resolves undefined when the value is not a pairing link at all. */
export type RedeemPairing = (value: string) => Promise<Redemption | undefined>

/** The code of the last link a form redeemed, and the token the server returned for it. */
type Redeemed = { code?: string; pairing?: Pairing }

// Pasted and scanned links share one redeem path so every surface explains a failure the same way.
// Each form keeps the last token it redeemed: the code is spent, so a retry after a failed connection check reuses it,
// whichever form the link takes (a scanned QR payload, or the link the scanner then shows).
export function useRedeemPairing(): RedeemPairing {
  const language = useLanguage()
  const platform = usePlatform()
  const last: Redeemed = {}

  return async (value) => {
    const link = pairingLink(value)

    if (!link) return legacyPairingLink(value) ? { error: language.t("server.connect.link.legacy") } : undefined

    // The same code again: reuse its token. An address the user edited since (another forwarded port, say) wins; the
    // token works on every address of the server.
    if (last.pairing && last.code === link.code) {
      const url = link.urls.includes(last.pairing.url) ? last.pairing.url : (link.urls[0] ?? last.pairing.url)

      return { pairing: { url, password: last.pairing.password } }
    }

    const result = await redeemPairingLink(link)

    if (result.type === "paired") {
      last.code = link.code
      last.pairing = result.pairing

      return { pairing: result.pairing }
    }

    if (result.type === "expired") return { error: language.t("server.connect.link.expired") }

    // A QR code can carry several addresses; the HTTPS page can reach none of them only when every one is plain HTTP.
    if (platform.platform === "web" && link.urls.every((url) => isMixedContent(location.href, url)))
      return { error: language.t("server.connect.mixedContent") }

    return { error: language.t("server.connect.link.unreachable", { url: link.urls.join(", ") }) }
  }
}

import QrScanner from "qr-scanner"
import { onCleanup, onMount, Show } from "solid-js"
import { createStore } from "solid-js/store"
import { Button } from "@opencode/ui/button"
import { useLanguage } from "@/runtime/i18n/language"
import { pairingLink } from "./pairing"
import type { RedeemPairing } from "./redeem"
import "./scanner.css"

// Redeems with the form's own redeem, so the form keeps the token and a failed connection check retries without the
// spent code; the form gets back a link it can show, and fills it in.
export function PairingScanner(props: { redeem: RedeemPairing; onScan: (link: string) => void; onCancel: () => void }) {
  const language = useLanguage()
  const [state, setState] = createStore({ error: "", ready: false, redeeming: false })
  const video = document.createElement("video")
  video.setAttribute("aria-label", language.t("server.connect.camera"))
  video.setAttribute("playsinline", "")
  video.muted = true

  onMount(() => {
    // A code that failed usually stays in view, so skip it for a few seconds instead of redeeming it on every frame.
    // It is tried again afterwards: a code the server could not be reached for still works once the network is back.
    const rejected = new Map<string, number>()
    const scan = { disposed: false }

    // QrScanner hides detached videos, so initialize only after this preview is mounted.
    const scanner = new QrScanner(
      video,
      (result) => {
        if (state.redeeming || Date.now() < (rejected.get(result.data) ?? 0)) return
        setState({ redeeming: true, error: "" })
        void props.redeem(result.data).then((redeemed) => {
          if (scan.disposed) return
          setState("redeeming", false)

          if (redeemed && "pairing" in redeemed) {
            scanner.stop()
            // A QR code carries {"code","urls"} JSON; the form shows the link for the address that paired instead.
            const code = pairingLink(result.data)?.code
            props.onScan(code ? new URL(`/auth/connect/${code}`, redeemed.pairing.url).href : result.data)

            return
          }

          rejected.set(result.data, Date.now() + 3000)
          setState("error", redeemed?.error ?? language.t("server.connect.scan.invalid"))
        })
      },
      {
        preferredCamera: "environment",
        maxScansPerSecond: 10,
        returnDetailedScanResult: true,
        // QrScanner only logs a decoder that fails (for example, a worker the page may not start), so the preview
        // would look like it is still scanning.
        onDecodeError: (error) => {
          // The native BarcodeDetector engine reports an empty frame as "Scanner error: No QR code found".
          if (String(error).includes(QrScanner.NO_QR_CODE_FOUND) || state.redeeming) return
          setState("error", language.t("server.connect.scan.failed"))
        },
      },
    )

    // Terminal QR codes can be light-on-dark depending on the terminal theme.
    scanner.setInversionMode("both")
    onCleanup(() => {
      scan.disposed = true
      scanner.destroy()
    })
    void scanner.start().then(
      () => setState("ready", true),
      () => setState("error", language.t("server.connect.camera.error")),
    )
  })

  return (
    <section class="server-connect-scanner" aria-label={language.t("server.connect.scan")}>
      <p>{language.t("server.connect.scan.description")}</p>
      <div class="server-connect-video">
        {video}
        <Show when={(!state.ready && !state.error) || state.redeeming}>
          <span role="status" data-busy={state.redeeming ? "" : undefined}>
            {language.t(state.redeeming ? "dialog.server.add.checking" : "server.connect.camera.starting")}
          </span>
        </Show>
      </div>
      <Show when={state.error}>
        <p class="server-connect-error" role="alert">
          {state.error}
        </p>
      </Show>
      <Button variant="neutral" size="large" onClick={props.onCancel}>
        {language.t("common.cancel")}
      </Button>
    </section>
  )
}

import { lazy, Show, Suspense } from "solid-js"
import { createStore } from "solid-js/store"
import { useMutation } from "@tanstack/solid-query"
import { Button } from "@opencode/ui/button"
import { TextInput } from "@opencode/ui/text-input"
import { Wordmark } from "@opencode/ui/wordmark"
import { useLanguage } from "@/runtime/i18n/language"
import { usePlatform } from "@/runtime/platform/platform"
import { useCheckServerHealth } from "@/runtime/server/health"
import { ServerConnection, useServers } from "@/runtime/server/registry"
import { bareServerAddress, serverAddress, type Pairing } from "./pairing"
import { useRedeemPairing } from "./redeem"
import { isMixedContent } from "./browser"
import { cameraHint, createCameraAvailability } from "./camera"
import { ConnectMethodSwitch, type ConnectMethod } from "./method"
import "./screen.css"

const PairingScanner = lazy(() => import("./scanner").then((module) => ({ default: module.PairingScanner })))

export function ConnectServerScreen(props: { url?: string } = {}) {
  const language = useLanguage()
  const platform = usePlatform()
  const servers = useServers()
  const check = useCheckServerHealth()
  const redeem = useRedeemPairing()
  const camera = createCameraAvailability()

  const [state, setState] = createStore<{
    method: ConnectMethod
    link: string
    url: string
    password: string
    error: string
    scanning: boolean
  }>({
    method: "link",
    link: "",
    url: props.url ?? "",
    password: "",
    error: "",
    scanning: false,
  })

  // A pairing token works on every address of its server. Signing in again to the server that signed out keeps its
  // address (e.g. localhost) even when the link names another one (e.g. 127.0.0.1 from opencode pair).
  const target = async (pairing: Pairing) => {
    if (!props.url || props.url === pairing.url) return pairing
    const http = { url: props.url, password: pairing.password }

    return (await check(http)).healthy ? http : pairing
  }

  const connect = async (http: ServerConnection.HttpBase) => {
    const result = await check(http)

    if (!result.healthy) {
      setState("error", connectionError(http.url))

      return
    }

    // Signing in again keeps the name the user gave this server.
    const existing = servers.list.find(
      (server): server is ServerConnection.Http => server.type === "http" && server.http.url === http.url,
    )

    servers.add(existing ? { ...existing, http } : { type: "http", http })
  }

  const connectionError = (url: string) =>
    language.t(
      platform.platform === "web" && isMixedContent(location.href, url)
        ? "server.connect.mixedContent"
        : "server.connect.failed",
    )

  const request = useMutation(() => ({
    mutationFn: async () => {
      if (state.method === "link") {
        const redeemed = await redeem(state.link)

        if (redeemed && "error" in redeemed) return void setState("error", redeemed.error)

        if (redeemed) return connect(await target(redeemed.pairing))
        // A server address typed here belongs to the password form.
        const address = bareServerAddress(state.link)

        if (address) return void setState({ method: "password", url: address, link: "", error: "" })

        return void setState("error", language.t("server.connect.link.invalid"))
      }

      // A pairing link pasted into the address field still pairs.
      const redeemed = await redeem(state.url)

      if (redeemed && "error" in redeemed) return void setState("error", redeemed.error)

      if (redeemed) return connect(await target(redeemed.pairing))
      const url = serverAddress(state.url)

      if (!url) return void setState("error", language.t("server.connect.address.invalid"))

      await connect({ url, password: state.password || undefined })
    },
    onError: () => setState("error", connectionError(state.method === "link" ? state.link : state.url)),
  }))

  const submit = () => {
    if (request.isPending) return
    setState("error", "")
    request.mutate()
  }

  return (
    <main data-component="connect-server" aria-labelledby="server-connect-title">
      <div class="server-connect-content">
        <div class="server-connect-brand" role="img" aria-label="OpenCode">
          <Wordmark />
        </div>
        <header>
          <h1 id="server-connect-title">{language.t("server.connect.title")}</h1>
          <p>
            {language.t(state.method === "link" ? "server.connect.description.pairing" : "server.connect.description")}
          </p>
        </header>
        <Show
          when={!state.scanning}
          fallback={
            <Suspense fallback={<p role="status">{language.t("server.connect.camera.starting")}</p>}>
              <PairingScanner
                redeem={redeem}
                onCancel={() => {
                  setState("scanning", false)
                  void camera.refetch()
                }}
                onScan={(link) => {
                  setState({ method: "link", link, error: "", scanning: false })
                  request.mutate()
                }}
              />
            </Suspense>
          }
        >
          <form
            onSubmit={(event) => {
              event.preventDefault()
              submit()
            }}
          >
            <Show
              when={state.method === "password"}
              fallback={
                <div class="server-connect-field">
                  <label for="server-connect-link">{language.t("server.connect.link")}</label>
                  <TextInput
                    id="server-connect-link"
                    name="link"
                    dir="ltr"
                    type="text"
                    inputMode="url"
                    autocapitalize="off"
                    spellcheck={false}
                    required
                    appearance="large"
                    placeholder={language.t("server.connect.link.placeholder")}
                    value={state.link}
                    disabled={request.isPending}
                    aria-describedby={state.error ? "server-connect-error" : undefined}
                    onInput={(event) => setState({ link: event.currentTarget.value, error: "" })}
                  />
                </div>
              }
            >
              <div class="server-connect-field">
                <label for="server-connect-url">{language.t("dialog.server.add.url")}</label>
                <TextInput
                  id="server-connect-url"
                  name="server"
                  dir="ltr"
                  type="text"
                  inputMode="url"
                  autocomplete="url"
                  autocapitalize="off"
                  spellcheck={false}
                  required
                  appearance="large"
                  placeholder={language.t("dialog.server.add.placeholder")}
                  value={state.url}
                  disabled={request.isPending}
                  aria-describedby={state.error ? "server-connect-error" : undefined}
                  onInput={(event) => setState({ url: event.currentTarget.value, error: "" })}
                />
              </div>
              <div class="server-connect-field">
                <label for="server-connect-password">{language.t("dialog.server.add.password")}</label>
                <TextInput
                  id="server-connect-password"
                  name="password"
                  type="password"
                  autocomplete="current-password"
                  appearance="large"
                  value={state.password}
                  disabled={request.isPending}
                  aria-describedby="server-connect-password-hint"
                  onInput={(event) => setState({ password: event.currentTarget.value, error: "" })}
                />
                <p id="server-connect-password-hint" class="server-connect-hint">
                  {language.t("server.connect.password.hint")}
                </p>
              </div>
            </Show>
            <Show when={state.error}>
              <p id="server-connect-error" class="server-connect-error" role="alert">
                {state.error}
              </p>
            </Show>
            <Button
              type="submit"
              variant="contrast"
              size="large"
              disabled={request.isPending || !(state.method === "link" ? state.link : state.url).trim()}
            >
              {language.t(request.isPending ? "dialog.server.add.checking" : "server.connect.button")}
            </Button>
          </form>
          <Show when={state.method === "link" && platform.platform === "web"}>
            <Show
              when={camera.available.latest || camera.available.loading}
              fallback={<p>{language.t(cameraHint())}</p>}
            >
              <Button
                variant="neutral"
                size="large"
                disabled={request.isPending || !camera.available.latest}
                onClick={() => setState("scanning", true)}
              >
                {language.t("server.connect.scan")}
              </Button>
            </Show>
          </Show>
          <ConnectMethodSwitch
            method={state.method}
            disabled={request.isPending}
            onChange={(method) => setState({ method, error: "" })}
          />
          <Show when={state.method === "link"}>
            <footer>
              <p>{language.t("server.connect.pair.link")}</p>
              <code dir="ltr">opencode pair</code>
            </footer>
          </Show>
        </Show>
      </div>
    </main>
  )
}

