  background: {
    blocking: () => boolean
    move: () => Promise<void>
  }
  navigateMessageByOffset: (offset: number) => void
  revert: Pick<SessionRevert, "undo" | "redo">
  focusInput: () => void
  // The composer's model, which a compaction runs with.
  model: () => { id: string; providerID: string; variant?: string } | undefined
}

const withCategory = (category: string) => {
  return (option: Omit<CommandOption, "category">): CommandOption => ({
    ...option,
    category,
  })
}

export const useSessionCommands = (actions: SessionCommandContext) => {
  const command = useCommand()
  const dialog = useDialog()
  const file = useFile()
  const language = useLanguage()
  const prompt = useComposerState()
  const serverSDK = useServerSDK()
  const data = useData()
  const settings = useSettings()
  const platform = usePlatform()
  const layout = useLayout()
  const host = useExtensionHost()

  const openDialog = async <T,>(load: () => Promise<T>, show: (value: T) => void) => {
    const owner = actions.session.ownership.capture()
    const value = await load()
    owner.run(() => show(value))
  }

  const shown = settings.visibility.fileTree

  // The file the selected side tab shows; other tabs have no line selection.
  const activeFile = () => actions.region.selected()?.tab.file

  // Pinned tabs stay open, and hidden side-panel tabs do not claim Close Tab while the region is collapsed.
  const closableTab = () => {
    if (!actions.session.layout.view().side.opened()) return

    const entry = actions.region.selected()

    return entry && !entry.tab.pinned ? entry.key : undefined
  }

  const cycleSideTabs = () => actions.session.layout.view().side.opened() && actions.region.keys().length > 1

  // Focus inside an extension command's scope belongs to that extension, which binds its own shortcuts there.
  const extensionScoped = (target: EventTarget | null) =>
    target instanceof Element &&
    host.items(Command).some((item) => !!item.value.scope && !!target.closest(item.value.scope))

  const sideFocused = (target: EventTarget | null) => {
    const element =
      target instanceof Element && target !== document.body && target !== document.documentElement
        ? target
        : document.activeElement

    return element instanceof Element && !!element.closest("#review-panel") && !extensionScoped(element)
  }

  const selectionPreview = (path: string, selection: FileSelection) => {
    const content = file.get(path)?.content?.content

    if (!content) return undefined

    return previewSelectedLines(content, { start: selection.startLine, end: selection.endLine })
  }

  const addSelectionToContext = (path: string, selection: FileSelection) => {
    const preview = selectionPreview(path, selection)
    prompt.context.add({ type: "file", path, selection, preview })
  }

  const canAddSelectionContext = () => {
    const path = activeFile()

    if (!path) return false

    return file.selectedLines(path) != null
  }

  const navigateMessageByOffset = actions.navigateMessageByOffset
  const focusInput = actions.focusInput

  const sessionCommand = withCategory(language.t("command.category.session"))
  const projectCommand = withCategory(language.t("command.category.project"))
  const fileCommand = withCategory(language.t("command.category.file"))
  const contextCommand = withCategory(language.t("command.category.context"))
  const viewCommand = withCategory(language.t("command.category.view"))
  const mcpCommand = withCategory(language.t("command.category.mcp"))
  const permissionsCommand = withCategory(language.t("command.category.permissions"))

  const exportSession = async () => {
    const sessionID = actions.session.identity.params.id

    if (!sessionID) return

    try {
      const data = await fetchSessionExport({
        sessionID,
        api: serverSDK.api,
      })

      const filename = sessionExportFilename(data.info)

      if (!(await saveSessionExport(filename, data, platform))) return
      showToast({
        variant: "success",
        icon: "circle-check",
        title: language.t("toast.session.export.success.title"),
        description: language.t("toast.session.export.success.description", { filename }),
      })
    } catch (err) {
      showToast({
        variant: "error",
        title: language.t("toast.session.export.failed.title"),
        description: err instanceof Error ? err.message : language.t("toast.session.export.failed.description"),
      })
    }
  }

  const copySessionID = async () => {
    const sessionID = actions.session.identity.params.id

    if (!sessionID) return

    try {
      await (platform.writeClipboardText?.(sessionID) ?? navigator.clipboard.writeText(sessionID))
      showToast({
        variant: "success",
        icon: "circle-check",
        title: language.t("common.copied"),
        description: sessionID,
      })
    } catch (err) {
      showToast({
        variant: "error",
        title: language.t("toast.session.copyID.failed.title"),
        description: err instanceof Error ? err.message : language.t("toast.session.copyID.failed.description"),
      })
    }
  }

  const copyProjectID = async () => {
    const projectID = actions.session.data.info()?.projectID

    if (!projectID) return

    try {
      await (platform.writeClipboardText?.(projectID) ?? navigator.clipboard.writeText(projectID))
      showToast({
        variant: "success",
        icon: "circle-check",
        title: language.t("common.copied"),
        description: projectID,
      })
    } catch (err) {
      showToast({
        variant: "error",
        title: language.t("toast.project.copyID.failed.title"),
        description: err instanceof Error ? err.message : language.t("toast.project.copyID.failed.description"),
      })
    }
  }

  const openFile = () => {
    void openDialog(
      () => import("@/shell/commands/dialog"),
      (x) => dialog.show(() => <x.DialogCommandPalette />),
    )
  }

  const closeTab = () => {
    const tab = closableTab()

    if (tab) actions.region.close(tab)
  }

  const selectAdjacentSideTab = (offset: -1 | 1) => {
    const key = adjacentTabKey(actions.region.keys(), actions.region.active(), offset)

    if (!key) return

    actions.region.select(key)

    const panel = document.getElementById("review-panel")

    if (!panel) return

    const active = document.activeElement

    if (
      active instanceof HTMLElement &&
      panel.contains(active) &&
      !active.closest('[role="tab"][aria-selected="false"], [inert], .hidden')
    )
      return
    ;(panel.querySelector<HTMLElement>('[role="tab"][aria-selected="true"]') ?? panel).focus({ preventScroll: true })
  }

  const addSelection = () => {
    const path = activeFile()

    if (!path) return

    const range = file.selectedLines(path)

    if (!range) {
      showToast({
        title: language.t("toast.context.noLineSelection.title"),
        description: language.t("toast.context.noLineSelection.description"),
      })

      return
    }

    addSelectionToContext(path, selectionFromLines(range))
  }

  const chooseMcp = () => {
    void openDialog(
      () => import("@/providers/connect/mcp-dialog"),
      (x) => dialog.show(() => <x.DialogSelectMcp />),
    )
  }

  const sessionProject = () => projectSettingsKey(serverSDK.scope, actions.session.data.info()?.projectID)

  const autoAccepting = () => settings.permissions.autoApproves(sessionProject())

  // From a session the toggle sets this project's choice, falling back to the default when they match.
  const toggleAutoAccept = () => {
    const project = sessionProject()
    const active = !autoAccepting()

    if (!project) settings.permissions.setAutoApproveDefault(active)
    else
      settings.permissions.setAutoApproveOverride(
        project,
        active === settings.permissions.autoApproveDefault() ? undefined : active,
      )

    if (!active) {
      showToast({
        title: language.t("toast.permissions.autoaccept.off.title"),
        description: language.t("toast.permissions.autoaccept.off.description"),
      })

      return
    }

    showToast({
      title: project
        ? language.t("toast.permissions.autoaccept.project.title")
        : language.t("toast.permissions.autoaccept.on.title"),
      description: project
        ? language.t("toast.permissions.autoaccept.project.description")
        : language.t("toast.permissions.autoaccept.on.description"),
    })
  }

  const undo = actions.revert.undo
  const redo = actions.revert.redo

  const compact = async () => {
    const sessionID = actions.session.identity.params.id

    if (!sessionID) return

    await data.session.compact({ sessionID, model: actions.model() }).catch((cause: unknown) => {
      showToast({ title: formatServerError(cause, language.t, language.t("common.requestFailed")) })
    })
  }

  const fork = () => {
    const sessionID = actions.session.identity.params.id

    if (!sessionID) return
    void openDialog(
      () => import("@/session/commands/fork-dialog"),
      (x) => dialog.show(() => <x.DialogFork />),
    )
  }

  const sessionCmds = () => [
    sessionCommand({
      id: "session.new",
      title: language.t("command.session.new"),
      keybind: "mod+shift+s",
      slash: "new",
      onSelect: (source) => command.trigger("tab.new", source),
    }),
    sessionCommand({
      id: "session.undo",
      title: language.t("command.session.undo"),
      description: language.t("command.session.undo.description"),
      slash: "undo",
      disabled: !actions.session.identity.params.id || actions.session.history.visibleUserMessages().length === 0,
      onSelect: undo,
    }),
    sessionCommand({
      id: "session.redo",
      title: language.t("command.session.redo"),
      description: language.t("command.session.redo.description"),
      slash: "redo",
      disabled: !actions.session.identity.params.id || !actions.session.data.revertMessageID(),
      onSelect: redo,
    }),
    sessionCommand({
      id: "session.compact",
      title: language.t("command.session.compact"),
      description: language.t("command.session.compact.description"),
      slash: "compact",
      disabled: !actions.session.identity.params.id || actions.session.history.visibleUserMessages().length === 0,
      onSelect: compact,
    }),
    sessionCommand({
      id: "session.background",
      title: language.t("command.session.background"),
      keybind: "ctrl+b",
      disabled: !actions.background.blocking(),
      onSelect: actions.background.move,
    }),
    sessionCommand({
      id: "session.fork",
      title: language.t("command.session.fork"),
      description: language.t("command.session.fork.description"),
      slash: "fork",
      disabled: !actions.session.identity.params.id || actions.session.history.visibleUserMessages().length === 0,
      onSelect: fork,
    }),
    sessionCommand({
      id: "session.export",
      title: language.t("command.session.export"),
      description: language.t("command.session.export.description"),
      slash: "export",
      disabled: !actions.session.identity.params.id,
      onSelect: exportSession,
    }),
    sessionCommand({
      id: "session.copyID",
      title: language.t("command.session.copyID"),
      disabled: !actions.session.identity.params.id,
      onSelect: copySessionID,
    }),
  ]

  const fileCmds = () => {
    const tab = closableTab()
    const cycle = cycleSideTabs()

    return [
      fileCommand({
        id: "file.open",
        title: language.t("command.file.open"),
        description: language.t("palette.search.placeholder"),
        keybind: "mod+p",
        slash: "open",
        onSelect: openFile,
      }),
      tab &&
        fileCommand({
          id: "file.close",
          title: language.t("command.tab.close"),
          keybind: settings.keybinds.get("tab.close") ?? "mod+w",
          when: (event) => !extensionScoped(event.target),
          onSelect: closeTab,
        }),
      cycle &&
        fileCommand({
          id: "file.tab.prev",
          title: "",
          keybind: settings.keybinds.get("tab.prev") ?? "mod+option+ArrowLeft,ctrl+shift+tab",
          hidden: true,
          when: (event) => sideFocused(event.target),
          onSelect: () => selectAdjacentSideTab(-1),
        }),
      cycle &&
        fileCommand({
          id: "file.tab.next",
          title: "",
          keybind: settings.keybinds.get("tab.next") ?? "mod+option+ArrowRight,ctrl+tab",
          hidden: true,
          when: (event) => sideFocused(event.target),
          onSelect: () => selectAdjacentSideTab(1),
        }),
    ].filter((v) => !!v)
  }

  const projectCmds = () => [
    projectCommand({
      id: "project.copyID",
      title: language.t("command.project.copyID"),
      disabled: !actions.session.data.info()?.projectID,
      onSelect: copyProjectID,
    }),
  ]

  const contextCmds = () => [
    contextCommand({
      id: "context.addSelection",
      title: language.t("command.context.addSelection"),
      description: language.t("command.context.addSelection.description"),
      keybind: "mod+shift+l",
      disabled: !canAddSelectionContext(),
      onSelect: addSelection,
    }),
  ]

  const viewCmds = () => [
    viewCommand({
      id: "review.toggle",
      title: language.t("command.review.toggle"),
      keybind: "mod+shift+r",
      onSelect: () => actions.session.layout.view().side.toggle(),
    }),
    ...(shown()
      ? [
          viewCommand({
            id: "fileTree.toggle",
            title: language.t("command.fileTree.toggle"),
            keybind: "mod+\\",
            onSelect: () => layout.fileTree.toggle(),
          }),
        ]
      : []),
    viewCommand({
      id: "input.focus",
      title: language.t("command.input.focus"),
      keybind: "ctrl+l",
      onSelect: focusInput,
    }),
  ]

  const messageCmds = () => [
    sessionCommand({
      id: "message.previous",
      title: language.t("command.message.previous"),
      description: language.t("command.message.previous.description"),
      keybind: "mod+alt+[",
      disabled: !actions.session.identity.params.id,
      onSelect: () => navigateMessageByOffset(-1),
    }),
    sessionCommand({
      id: "message.next",
      title: language.t("command.message.next"),
      description: language.t("command.message.next.description"),
      keybind: "mod+alt+]",
      disabled: !actions.session.identity.params.id,
      onSelect: () => navigateMessageByOffset(1),
    }),
  ]

  const mcpCmds = () => [
    mcpCommand({
      id: "mcp.toggle",
      title: language.t("command.mcp.toggle"),
      description: language.t("command.mcp.toggle.description"),
      keybind: "mod+;",
      slash: "mcp",
      onSelect: chooseMcp,
    }),
  ]

  const permissionsCmds = () => [
    permissionsCommand({
      id: "permissions.autoaccept",
      title: autoAccepting()
        ? language.t("command.permissions.autoaccept.disable")
        : sessionProject()
          ? language.t("command.permissions.autoaccept.project")
          : language.t("command.permissions.autoaccept.enable"),
      keybind: "mod+shift+a",
      disabled: false,
      onSelect: toggleAutoAccept,
    }),
  ]

  command.register("session", () => [
    ...sessionCmds(),
    ...projectCmds(),
    ...fileCmds(),
    ...contextCmds(),
    ...viewCmds(),
    ...messageCmds(),
    ...mcpCmds(),
    ...permissionsCmds(),
  ])
}

import { createEffect, createMemo, on, type Accessor } from "solid-js"
import type { ComposerControls } from "@/composer/adapter"
import { setCursorPosition } from "@/composer/editor/dom"
import { createComposerModel } from "@/composer/model"
import { useSettings } from "@/settings/model"
import { createActiveComposerAdapter } from "./adapter"
import { createSessionQueue } from "./queue"
import { createSessionComposerRegionController } from "./session-composer-region-controller"

export function createSessionComposerController(input: {
  sessionID: string
  sessionKey: Accessor<string>
  controls: Accessor<ComposerControls>
  dock: Parameters<typeof createSessionComposerRegionController>[0]
}) {
  const settings = useSettings()
  const region = createSessionComposerRegionController(input.dock)
  let editor: HTMLDivElement | undefined

  const adapter = createActiveComposerAdapter({
    sessionID: input.sessionID,
    sessionKey: input.sessionKey,
    controls: input.controls,
    submitted: region.onResponseSubmit,
    setEditor: (element) => {
      editor = element
      region.setPromptRef(element)
    },
  })

  const queue = createSessionQueue({
    sessionID: input.sessionID,
    draft: adapter.state,
    working: adapter.working,
    behavior: settings.general.followUpBehavior,
    restoreFocus: (cursor) => {
      const target = editor

      if (!target) return
      requestAnimationFrame(() => {
        target.focus()
        setCursorPosition(target, cursor)
      })
    },
  })

  const composer = createComposerModel(adapter, { queue })
  const editable = createMemo(() => region.showComposer() && !region.child())
  // Requests hide the view without disposing its draft or queue edit.
  createEffect(on(editable, () => composer.onDragLeave()))

  return {
    region,
    queue,
    composer,
    drop: {
      active: () => editable() && composer.state.drag === "active",
      input: () => composer.model.selection.current()?.capabilities.input,
    },
  }
}

export type SessionComposerController = ReturnType<typeof createSessionComposerController>

import { Button } from "@opencode/ui/button"
import { useDialog } from "@opencode/ui/context/dialog"
import { DockShell, DockTray } from "@opencode/ui/dock-surface"
import { Icon } from "@opencode/ui/icon"
import { Menu } from "@opencode/ui/menu"
import { getFilename, sameDirectory } from "@opencode/util/path"
import { useMutation } from "@tanstack/solid-query"
import { createEffect, createResource, For, Show } from "solid-js"
import { createStore } from "solid-js/store"
import { useLanguage } from "@/runtime/i18n/language"
import { useData, useServer } from "@/runtime/server/current"
import { showToast } from "@/shell/notifications/toast"
import { createWorktree } from "@/workspaces/create"
import { useDirectoryPicker } from "@/workspaces/selection/picker"

export function SessionLocationMissing(props: { sessionID: string; projectID: string; directory: string }) {
  const language = useLanguage()
  const server = useServer()
  const data = useData()
  const dialog = useDialog()
  const pickDirectory = useDirectoryPicker()
  const [state, setState] = createStore({ restoreFocus: false, worktreesOpen: false })
  const project = () => data.project.get(props.projectID)

  const [worktrees] = createResource(
    () => (state.worktreesOpen ? props.projectID : undefined),
    async (projectID) => {
      await server.ctx.sync.worktrees.refresh(projectID)
      const items = await server.ctx.sync.worktrees.list(projectID)

      if (!items) showToast({ variant: "error", title: language.t("session.location.worktreesFailed") })

      return items ?? []
    },
    // Seed latest so even the first fetch does not enter Suspense.
    { initialValue: [] },
  )

  const otherWorktrees = () =>
    worktrees.latest.filter((item) => item.strategy && !sameDirectory(item.directory, props.directory))

  let button: HTMLButtonElement | undefined

  const move = useMutation(() => ({
    mutationFn: async (input: { directory?: string }) => {
      // The missing worktree cannot resolve its own Location, so create from the project's saved checkout.
      const current = project()

      const destination =
        input.directory ??
        (current &&
          (await createWorktree({
            api: server.ctx.sdk.api,
            data,
            directory: current.canonical,
            project: { id: current.id, canonical: current.canonical, directory: current.canonical },
          })))

      if (!destination) return
      await server.ctx.sdk.api.session.move({ sessionID: props.sessionID, directory: destination })
    },
    onError: (error) => {
      setState("restoreFocus", true)
      showToast({
        variant: "error",
        title: language.t("session.location.moveFailed"),
        description: error instanceof Error ? error.message : language.t("common.requestFailed"),
      })
    },
  }))

  createEffect(() => {
    if (!state.restoreFocus || move.isPending || dialog.active) return
    setState("restoreFocus", false)
    button?.focus()
  })

  function choose() {
    if (move.isPending) return
    pickDirectory({
      server: server.conn,
      title: language.t("session.location.choose"),
      onSelect: (result) => {
        const selected = Array.isArray(result) ? result[0] : result

        if (selected) move.mutate({ directory: selected })

        if (!selected) setState("restoreFocus", true)
      },
    })
  }

  return (
    <div data-component="session-location-missing">
      <DockShell class="flex flex-col gap-2 p-3">
        <div role="status" class="flex items-start gap-2 text-13-regular leading-[var(--line-height-base)]">
          <Icon name="warning" class="shrink-0 text-icon-warning-base" />
          <div class="min-w-0 flex flex-col gap-1">
            <div class="font-medium text-text-strong">{language.t("session.location.unavailable")}</div>
            <div class="break-all font-mono text-12-regular text-text-weak">{props.directory}</div>
            <div class="text-text-base">{language.t("session.location.description")}</div>
          </div>
        </div>
      </DockShell>
      <DockTray attach="top" class="flex flex-wrap justify-end gap-2 p-2 pt-[22px]">
        <Show when={project()?.vcs === "git"}>
          <Menu placement="top-end" onOpenChange={(open) => setState("worktreesOpen", open)}>
            <Menu.Trigger as={Button} variant="neutral" disabled={move.isPending}>
              {language.t("session.location.worktree")}
            </Menu.Trigger>
            <Menu.Portal>
              <Menu.Content class="max-h-80 max-w-[calc(100vw-32px)] overflow-y-auto">
                <Menu.Item onSelect={() => move.mutate({})} disabled={move.isPending}>
                  <Icon name="workspace-new" />
                  {language.t("workspace.new")}
                </Menu.Item>
                <Show when={worktrees.loading && otherWorktrees().length === 0}>
                  <Menu.Item disabled>{language.t("common.loading")}</Menu.Item>
                </Show>
                <For each={otherWorktrees()}>
                  {(worktree) => (
                    <Menu.Item
                      title={worktree.directory}
                      onSelect={() => move.mutate({ directory: worktree.directory })}
                      disabled={move.isPending}
                    >
                      <Icon name="workspace-isolated" />
                      <span class="truncate">{getFilename(worktree.directory)}</span>
                    </Menu.Item>
                  )}
                </For>
              </Menu.Content>
            </Menu.Portal>
          </Menu>
        </Show>
        <Button ref={button} variant="contrast" onClick={choose} disabled={move.isPending}>
          {language.t(move.isPending ? "session.location.moving" : "session.location.choose")}
        </Button>
      </DockTray>
    </div>
  )
}

import { createMemo, For, Show } from "solid-js"
import { DragDropProvider, PointerSensor } from "@dnd-kit/solid"
import { isSortable, useSortable } from "@dnd-kit/solid/sortable"
import { AutoScroller, Feedback, PointerActivationConstraints } from "@dnd-kit/dom"
import { RestrictToVerticalAxis } from "@dnd-kit/abstract/modifiers"
import { RestrictToElement } from "@dnd-kit/dom/modifiers"
import { arrayMove } from "@dnd-kit/helpers"
import { Button } from "@opencode/ui/button"
import { Icon } from "@opencode/ui/icon"
import { IconButton } from "@opencode/ui/icon-button"
import { Tooltip } from "@opencode/ui/tooltip"
import { useLanguage } from "@/runtime/i18n/language"
import type { SessionQueueView } from "./queue"

// Pullout above the composer listing the prompts queued behind the current
// turn. The panel slides under the composer card (negative margin, opaque
// composer background) so the two read as one attached surface.
export function SessionQueuePanel(props: { queue: SessionQueueView }) {
  const language = useLanguage()
  const count = () => props.queue.rows().length
  let listRef!: HTMLDivElement

  return (
    <Show when={count() > 0}>
      <div
        data-component="session-queue-panel"
        class="relative z-0 -mb-3 rounded-xl bg-v2-background-bg-base px-1.5 pt-1.5 shadow-[inset_0_0_0_0.5px_var(--v2-border-border-base)]"
        // Match the composer overlap so the scroll crop meets the input edge.
        classList={{ "pb-3": count() > 4, "pb-[18px]": count() <= 4 }}
      >
        <Show when={count() > 3}>
          <div class="px-1.5 pt-1 pb-px text-[11px] font-[530] uppercase leading-[var(--line-height-tight)] tracking-[0.05px] text-v2-text-text-muted [font-variant-numeric:tabular-nums]">
            {language.plural("session.queue.count", count())}
          </div>
        </Show>
        <DragDropProvider
          sensors={(defaults) => [
            ...defaults.filter((sensor) => sensor !== PointerSensor),
            PointerSensor.configure({
              activationConstraints: [new PointerActivationConstraints.Distance({ value: 4 })],
            }),
          ]}
          modifiers={[RestrictToVerticalAxis, RestrictToElement.configure({ element: () => listRef })]}
          plugins={(defaults) => [
            ...defaults.filter((plugin) => plugin !== AutoScroller && plugin !== Feedback),
            AutoScroller.configure({ acceleration: 8, threshold: { x: 0, y: 0.05 } }),
            Feedback.configure({ dropAnimation: null }),
          ]}
          onDragEnd={(event) => {
            const source = event.operation.source

            if (event.canceled || !isSortable(source)) return

            if (source.initialIndex === source.index) return
            void props.queue.reorder(
              arrayMove(
                props.queue.rows().map((row) => row.id),
                source.initialIndex,
                source.index,
              ),
            )
          }}
        >
          {/* Keyed on row IDs so store updates move row elements instead of
              remounting them, which would kill an in-flight drag. */}
          {/* Four 32px rows, four 1px gaps, and half a row hint at more queued prompts. */}
          <div
            ref={listRef}
            class="flex flex-col gap-px"
            classList={{ "max-h-[148px] overflow-y-auto": count() > 4 }}
            style={{
              "mask-image":
                count() > 4
                  ? "linear-gradient(to bottom, transparent, black 8px, black calc(100% - 12px), transparent)"
                  : undefined,
            }}
          >
            <For each={props.queue.rows().map((row) => row.id)}>
              {(id, index) => <SessionQueueRow queue={props.queue} id={id} index={index()} />}
            </For>
          </div>
        </DragDropProvider>
      </div>
    </Show>
  )
}

function SessionQueueRow(props: { queue: SessionQueueView; id: string; index: number }) {
  const language = useLanguage()
  const row = createMemo(() => props.queue.rows().find((entry) => entry.id === props.id))
  const editing = () => props.queue.editing() === props.id
  // While the turn is stopped the queue stays parked, so the first prompt
  // shows its actions without hover and its label reads Send: that is how a
  // parked queue resumes.
  const active = () => !props.queue.working() && props.index === 0

  const sortable = useSortable({
    get id() {
      return props.id
    },
    get index() {
      return props.index
    },
    get disabled() {
      return props.queue.busy()
    },
  })

  return (
    <Show when={row()} keyed>
      {(entry) => (
        <div
          ref={sortable.ref}
          data-component="session-queue-row"
          class="group/queue-row flex h-8 shrink-0 items-center justify-between gap-2 rounded-md py-1 ps-1 pe-2"
          classList={{
            "bg-v2-overlay-simple-overlay-hover": editing(),
            "opacity-60": sortable.isDragSource(),
          }}
        >
          <div class="flex min-w-0 flex-1 items-center gap-2">
            <button
              ref={sortable.handleRef}
              type="button"
              class="grid shrink-0 cursor-grab touch-none grid-cols-2 gap-x-[2px] gap-y-[2.25px] p-1"
              aria-label={language.t("session.queue.reorder")}
            >
              <For each={Array.from({ length: 6 })}>
                {() => <span class="size-[2px] bg-v2-background-bg-layer-04" />}
              </For>
            </button>
            <div class="flex min-w-0 items-center gap-4">
              <button
                type="button"
                data-action="session-queue-edit"
                dir="auto"
                disabled={props.queue.busy()}
                class="max-w-full min-w-0 self-start truncate rounded-sm text-start text-[13px] font-[440] leading-[var(--line-height-compact)]"
                classList={{
                  "text-v2-text-text-faint": editing(),
                  "cursor-text text-v2-text-text-base hover:bg-v2-overlay-simple-overlay-hover": !editing(),
                }}
                onClick={() => props.queue.edit(props.id)}
              >
                {entry.text ||
                  (entry.attachments ? language.plural("session.queue.attachments", entry.attachments) : "")}
              </button>
              <Show when={entry.attachments && entry.text}>
                <span class="shrink-0 whitespace-nowrap text-[13px] font-[440] leading-[var(--line-height-compact)] text-v2-text-text-muted">
                  {language.plural("session.queue.attachments", entry.attachments)}
                </span>
              </Show>
            </div>
          </div>
          <div
            data-slot="session-queue-actions"
            class="flex shrink-0 items-center gap-1.5"
            classList={{
              "opacity-0 focus-within:opacity-100 group-hover/queue-row:opacity-100 [@media(hover:none)]:opacity-100":
                !active() && !editing(),
              "pointer-events-none": props.queue.busy(),
            }}
          >
            <Show when={!editing()}>
              <Tooltip
                placement="top"
                inactive={!props.queue.working()}
                value={language.t("session.queue.steerTooltip")}
              >
                <Button
                  data-action="session-queue-steer"
                  type="button"
                  size="small"
                  variant="ghost-faint"
                  icon="arrow-up"
                  disabled={props.queue.busy()}
                  class="![font-weight:530]"
                  onClick={() => void props.queue.steer(props.id)}
                >
                  {props.queue.working() ? language.t("session.queue.steer") : language.t("session.queue.send")}
                </Button>
              </Tooltip>
              <Tooltip placement="top" value={language.t("session.queue.undo")}>
                <IconButton
                  data-action="session-queue-undo"
                  type="button"
                  size="small"
                  variant="ghost-muted"
                  icon={<Icon name="outline-undo" />}
                  disabled={props.queue.busy()}
                  aria-label={language.t("session.queue.undo")}
                  onClick={() => props.queue.undo(props.id)}
                />
              </Tooltip>
            </Show>
            <Tooltip placement="top" value={language.t("session.queue.remove")}>
              <IconButton
                data-action="session-queue-remove"
                type="button"
                size="small"
                variant="ghost-muted"
                icon={<Icon name="outline-xmark" />}
                disabled={props.queue.busy()}
                aria-label={language.t("session.queue.remove")}
                onClick={() => void props.queue.remove(props.id)}
              />
            </Tooltip>
          </div>
        </div>
      )}
    </Show>
  )
}

