import { describe, expect, test } from "bun:test"
import type { SessionApi, SessionInfo, SessionListInput } from "@opencode/client/promise"
import { listAllSessions } from "./list"

describe("listAllSessions", () => {
  test("loads every page in server order and retains the query", async () => {
    const calls: SessionListInput[] = []

    const pages = new Map<string | undefined, { data: SessionInfo[]; cursor: { next?: string } }>([
      [undefined, { data: [sessionInfo("session-3"), sessionInfo("session-2")], cursor: { next: "next" } }],
      ["next", { data: [sessionInfo("session-1", true)], cursor: {} }],
    ])

    const api = {
      list: async (query = {}) => {
        calls.push(query)

        return pages.get(query.cursor) ?? { data: [], cursor: {} }
      },
    } satisfies Pick<SessionApi, "list">

    const result = await listAllSessions(api, { directory: "/repo", order: "desc" })

    expect(result.map((session) => session.id)).toEqual(["session-3", "session-2", "session-1"])
    expect(result[2]?.time.archived).toBe(2)
    expect(calls).toEqual([
      { directory: "/repo", order: "desc", limit: 100, cursor: undefined },
      { directory: "/repo", order: "desc", limit: 100, cursor: "next" },
    ])
  })

  test("requests the terminal empty page when the server returns a next cursor", async () => {
    const cursors: Array<string | undefined> = []

    const api = {
      list: async (query = {}) => {
        cursors.push(query.cursor)

        if (query.cursor) return { data: [], cursor: { next: "unused" } }

        return { data: [sessionInfo("session-1")], cursor: { next: "terminal" } }
      },
    } satisfies Pick<SessionApi, "list">

    const result = await listAllSessions(api, { directory: "/repo", limit: 25 })

    expect(result.map((session) => session.id)).toEqual(["session-1"])
    expect(cursors).toEqual([undefined, "terminal"])
  })
})

function sessionInfo(id: string, archived = false) {
  return {
    id,
    projectID: "project-1",
    agent: "build",
    model: { id: "model-1", providerID: "provider-1" },
    cost: 0,
    tokens: { input: 0, output: 0, reasoning: 0, cache: { read: 0, write: 0 } },
    time: { created: 1, updated: 1, archived: archived ? 2 : undefined },
    title: id,
    location: { directory: "/repo" },
  } as SessionInfo
}

import type { SessionApi, SessionInfo, SessionListInput } from "@opencode/client/promise"

export async function listAllSessions(api: Pick<SessionApi, "list">, input: Omit<SessionListInput, "cursor">) {
  const load = async (cursor?: string): Promise<SessionInfo[]> => {
    const result = await api.list({ ...input, limit: input.limit ?? 100, cursor })
    const sessions = result.data

    if (result.data.length === 0 || !result.cursor.next) return sessions

    return [...sessions, ...(await load(result.cursor.next))]
  }

  return load()
}

export const messageIdFromHash = (hash: string) => {
  const value = hash.startsWith("#") ? hash.slice(1) : hash
  const match = value.match(/^message-(.+)$/)

  if (!match) return

  return match[1]
}

import type { SessionInfo, SessionMessageInfo, SessionMessageUser } from "@opencode/client/promise"
import { createMediaQuery } from "@solid-primitives/media"
import { createMemo } from "solid-js"
import { useWorkspaceLocation } from "@/workspaces/location"
import { useData } from "@/runtime/server/current"
import { same } from "@/runtime/persistence/equality"
import { containsDirectory } from "@opencode/util/path"
import { isProjectDirectory, isWorkspaceDirectory } from "@/workspaces/paths"
import { projectForSession } from "@/shell/layout/helpers"
import { selectSessionUserMessages, selectVisibleSessionUserMessages } from "./session-domain"
import { useSessionLayout } from "./session-layout"
import { createSessionOwnership } from "./session-ownership"
import { useTabs } from "@/shell/tabs/tabs"
import { useServer } from "@/runtime/server/current"
import type { ServerCtx } from "@/runtime/server/runtime"

const emptyMessages: SessionMessageInfo[] = []

const emptyUserMessages: SessionMessageUser[] = []

const idle = { type: "idle" as const }

export function useSessionModel() {
  const data = useData()
  const server = useServer()
  const shellTabs = useTabs()
  const layout = useSessionLayout()
  const location = useWorkspaceLocation()
  const isDesktop = createMediaQuery("(min-width: 768px)")
  const sessionID = createMemo(() => layout.params.id)

  const info = createMemo(() => {
    const id = sessionID()

    return id ? data.session.get(id) : undefined
  })

  const parentID = createMemo(() => {
    const current = info()?.parentID

    if (current) return current
    const id = sessionID()

    if (!id) return

    const tab = shellTabs.store.find(
      (item) => item.type === "session" && item.server === server.key && item.routeSessionId === id,
    )

    return tab?.type === "session" ? (tab.routeParentId ?? tab.sessionId) : undefined
  })

  const parent = createMemo(() => {
    const id = parentID()

    return id ? data.session.get(id) : undefined
  })

  const status = createMemo(() => {
    const id = sessionID()

    return id && data.session.status(id) === "running" ? { type: "busy" as const } : idle
  })

  const messages = createMemo(() => {
    const id = sessionID()

    return id ? data.session.message.list(id) : emptyMessages
  })

  const userMessages = createMemo(() => selectSessionUserMessages(messages()), emptyUserMessages, { equals: same })
  const revertMessageID = createMemo(() => info()?.revert?.messageID)

  const visibleUserMessages = createMemo(
    () => selectVisibleSessionUserMessages(userMessages(), revertMessageID()),
    emptyUserMessages,
    { equals: same },
  )

  const project = createMemo(() => sessionProject(data, info(), location().directory))

  return {
    shared: { data },
    project,
    isDesktop,
    workspace: {
      directory: createMemo(() => info()?.location.directory ?? location().directory),
      current: createMemo(() => sessionInWorkspace(server.ctx.sync.data.project, info(), location().directory)),
    },
    identity: {
      params: layout.params,
      sessionID,
      sessionKey: layout.sessionKey,
      workspaceKey: layout.workspaceKey,
    },
    data: {
      info,
      parent,
      parentID,
      isChild: createMemo(() => !!parentID()),
      status,
      working: createMemo(() => {
        const id = sessionID()

        return id ? data.session.status(id) === "running" : false
      }),
      revertMessageID,
    },
    history: {
      messages,
      userMessages,
      visibleUserMessages,
      lastUserMessage: createMemo(() => visibleUserMessages().at(-1)),
    },
    layout: {
      tabs: layout.tabs,
      view: layout.view,
      tabKey: layout.tabKey,
      sessionKey: layout.sessionKey,
    },
    ownership: createSessionOwnership(layout.sessionKey),
  }
}

export type SessionModel = ReturnType<typeof useSessionModel>

/**
 * A session's project from raw server metadata: its project id's, else the project whose root contains `directory`.
 * Global sync's enriched project replaces it once listed.
 */
export function sessionProject(data: ServerCtx["data"], info: SessionInfo | undefined, directory: string) {
  const value = info?.projectID
    ? data.project.get(info.projectID)
    : data.project.list().find((item) => containsDirectory(item.canonical, directory))

  if (!value) return

  return { ...value, worktree: value.canonical, worktrees: [] }
}

/** The session runs in a worktree or sandbox of its project rather than the project root. */
export function sessionInWorkspace(
  projects: ServerCtx["sync"]["data"]["project"],
  info: SessionInfo | undefined,
  fallback: string,
) {
  const directory = info?.location.directory ?? fallback
  // Global sync enriches projects with discovered worktrees; raw project metadata does not.
  const value = info ? projectForSession(info, projects) : projects.find((item) => isProjectDirectory(item, directory))

  return isWorkspaceDirectory(value, directory)
}

import { createEffect, on, onCleanup } from "solid-js"
import { useLocation } from "@solidjs/router"
import { ComposerEditor } from "@/composer/editor/editor"
import { setCursorPosition } from "@/composer/editor/dom"
import { createComposerEditor } from "@/composer/editor/interaction"
import type { PendingSession } from "@/shell/tabs/tabs"

export function PreparingComposer(props: { pending: PendingSession }) {
  const location = useLocation()
  let element: HTMLElement | undefined

  const editor = createComposerEditor({
    store: () => props.pending.composer.store,
    commands: () => [],
    context: () => [],
    searchContextFiles: () => [],
    onEditor: (value) => {
      element = value
    },
    view: {
      draftOnly: true,
      submit: { stopping: () => false, onSubmit() {}, onStop() {} },
    },
  })

  createEffect(
    on(
      () => props.pending,
      (pending) => {
        const pathname = location.pathname
        editor.restoreFocus(pending.composer.cursor())
        onCleanup(() => {
          if (document.activeElement !== element) return
          const cursor = pending.composer.cursor()
          requestAnimationFrame(() => {
            if (location.pathname !== pathname) return
            const next = document.querySelector<HTMLDivElement>('[data-component="composer-editor"]')

            if (!next || next === element) return
            next.focus()
            setCursorPosition(next, cursor ?? 0)
          })
        })
      },
    ),
  )

  return (
    <div data-component="session-composer-dock" class="w-full shrink-0 bg-v2-background-bg-base pb-3">
      <div class="mx-auto w-full px-3 md:max-w-session">
        <ComposerEditor controller={editor} modelControlsVisible={false} />
      </div>
    </div>
  )
}

import { createEffect, onCleanup } from "solid-js"
import type { PermissionRequest } from "@opencode/client/promise"
import type { Data } from "@opencode/client/solid"
import type { ServerSDK } from "@/runtime/server/client"
import { projectSettingsKey, useSettings } from "@/settings/model"

const respondedLimit = 1000

const retryLimit = 2

const retryDelayMs = 1000

// Auto-approves permission requests on one server connection for the projects
// the client-local settings cover: the app-wide default, unless a project overrides it.
export function createPermissionAutoApprover(input: { sdk: ServerSDK; data: Data }) {
  const permissions = useSettings().permissions
  const enabled = () => permissions.autoApprovesOnServer(input.sdk.scope)

  const covers = (projectID: string | undefined) =>
    permissions.autoApproves(projectSettingsKey(input.sdk.scope, projectID))

  const state = { disposed: false, generation: 0, responded: new Set<string>() }

  const unsubscribe = input.sdk.event.on("permission.asked", (event) => {
    if (enabled()) consider(event.data)
  })

  onCleanup(() => {
    state.disposed = true
    unsubscribe()
  })

  // The event stream does not replay requests asked while this client was
  // disconnected, and requests may already be pending before the setting turns
  // on, so sweep on every connect while the setting is on.
  createEffect(() => {
    if (!enabled() || input.sdk.connection.status() !== "connected") return
    const generation = ++state.generation
    void sweepWithRetry(generation, 0)
  })

  // Approves pending requests that reach the local store, which is how a
  // previously unknown idle session's requests surface when its view opens
  // and syncs them. Store changes cannot re-trigger the network sweep: it
  // deliberately reads them after an await, outside Solid tracking.
  createEffect(() => {
    if (!enabled()) return

    for (const session of input.data.session.list()) {
      for (const request of input.data.session.permission.list(session.id) ?? []) approve(request)
    }
  })

  // An incomplete sweep leaves pending requests hidden with no later trigger
  // to recover them, so retry it a bounded number of times. A newer sweep
  // supersedes scheduled retries.
  async function sweepWithRetry(generation: number, attempt: number) {
    const complete = await sweep()

    if (complete || attempt >= retryLimit) return
    setTimeout(() => {
      if (state.disposed || !enabled() || generation !== state.generation) return
      void sweepWithRetry(generation, attempt + 1)
    }, retryDelayMs * (attempt + 1))
  }

  async function sweep() {
    const inventory = await sweepLocations()

    const listed = await Promise.all(
      inventory.locations.map((location) =>
        input.sdk.api.permission.request
          .list({ location: { directory: location.directory } })
          .then((pending) => {
            if (!state.disposed) pending.data.forEach((request) => consider(request))

            return true
          })
          .catch(() => false),
      ),
    )

    return inventory.complete && listed.every(Boolean)
  }

  // Active sessions are the primary inventory: session.active is server-wide,
  // so it covers sessions no tab has loaded, and a request blocking a tool
  // call always belongs to one (Permission.assert clears its entry when the
  // awaiting fiber dies). Locally known sessions are swept too because the
  // external session.permission.create API can park a request on an idle
  // session. A detached request on a session this client never loaded is the
  // one case that stays uncovered.
  async function sweepLocations() {
    const active = await input.sdk.api.session.active().catch(() => undefined)
    const ids = Object.keys(active ?? {})

    // Resync every active session rather than trusting cached info: another
    // client may have moved one while this client was disconnected, and the
    // cached location would list permissions from the old location. A failed
    // resync falls back to the cached location and marks the sweep incomplete.
    const synced = await Promise.all(
      ids.map((id) => {
        input.data.session.invalidate(id)

        return input.data.session.sync(id).then(
          () => true,
          () => false,
        )
      }),
    )

    const locations = [
      ...ids.flatMap((id) => {
        const location = input.data.session.get(id)?.location

        return location ? [location] : []
      }),
      ...input.data.session.list().map((session) => session.location),
    ]

    return {
      locations: [
        ...new Map(locations.map((item) => [item.directory, item])).values(),
      ],
      complete: active !== undefined && synced.every(Boolean),
    }
  }

  // A request from a session this client has not loaded needs that session's
  // project before a per-project choice can apply to it.
  function consider(permission: PermissionRequest) {
    if (covers(undefined) || input.data.session.get(permission.sessionID)) return approve(permission)
    void input.sdk.api.session
      .get({ sessionID: permission.sessionID })
      .then((session) => approve(permission, session.projectID))
      .catch(() => undefined)
  }

  function approve(
    permission: PermissionRequest,
    projectID = input.data.session.get(permission.sessionID)?.projectID,
    attempt = 0,
  ) {
    // covers() guards the retry timer path: the user may disable the setting
    // between a failed reply and its scheduled retry.
    if (state.disposed || !covers(projectID) || state.responded.has(permission.id)) return
    remember(permission.id)
    input.sdk.api.permission
      .reply({ sessionID: permission.sessionID, requestID: permission.id, decision: "once" })
      .catch(() => {
        // A reply failure leaves the request pending but invisible (the UI
        // hides prompts while auto-approve is on), so retry a bounded number
        // of times. Later sweeps retry it after that.
        state.responded.delete(permission.id)

        if (state.disposed || attempt >= retryLimit) return
        setTimeout(() => approve(permission, projectID, attempt + 1), retryDelayMs * (attempt + 1))
      })
  }

  function remember(id: string) {
    state.responded.add(id)

    for (const oldest of state.responded) {
      if (state.responded.size <= respondedLimit) break
      state.responded.delete(oldest)
    }
  }
}

import type { SessionInfo, SessionMessageAssistant, SessionMessageInfo, ShellInfo } from "@opencode/client/promise"
import { createMemo } from "solid-js"

type Task =
  | { id: string; type: "subagent"; label: string; agent?: string }
  | { id: string; type: "shell"; label: string }

export function createSessionBackground(input: {
  sessionID: () => string | undefined
  messages: (id: string) => SessionMessageInfo[]
  sessions: () => SessionInfo[]
  status: (id: string) => "idle" | "running"
  shells: () => ShellInfo[]
}) {
  const history = createMemo(() => {
    const completed = new Set<string>()
    const subagents: { id: string; type: "subagent"; label: string; agent: string | undefined }[] = []
    const shells: { partID: string; task: { id: string; type: "shell"; label: string } }[] = []
    const id = input.sessionID()

    const assistant = (id ? input.messages(id) : []).reduce<SessionMessageAssistant | undefined>((latest, message) => {
      if (message.type === "synthetic") {
        if (message.metadata?.source === "subagent" && typeof message.metadata.childID === "string")
          completed.add(message.metadata.childID)

        if (message.metadata?.source === "shell") {
          if (typeof message.metadata.shellID === "string") completed.add(message.metadata.shellID)

          if (typeof message.metadata.jobID === "string") completed.add(message.metadata.jobID)
        }

        return latest
      }

      if (message.type !== "assistant") return latest
      message.content.forEach((part) => {
        if (part.type !== "tool" || (part.name !== "subagent" && part.name !== "shell")) return

        if (part.state.status !== "completed" || part.state.metadata?.status !== "running") return

        if (part.name === "subagent") {
          const sessionID = part.state.metadata.sessionID

          if (typeof sessionID !== "string") return
          const description = part.state.input.description
          const agent = part.state.input.agent
          subagents.push({
            id: sessionID,
            type: "subagent",
            label: typeof description === "string" ? description : sessionID,
            agent: typeof agent === "string" ? agent : undefined,
          })

          return
        }

        const shellID = part.state.metadata.shellID
        const command = part.state.input.command
        shells.push({
          partID: part.id,
          task: {
            id: typeof shellID === "string" ? shellID : part.id,
            type: "shell",
            label: typeof command === "string" ? command : part.id,
          },
        })
      })

      return message.time.completed === undefined ? message : latest
    }, undefined)

    return {
      // Completion notices can identify the shell or its original tool call.
      subagents: subagents.filter((task) => !completed.has(task.id)),
      shells: shells
        .filter((item) => !completed.has(item.partID) && !completed.has(item.task.id))
        .map((item) => item.task),
      blocking:
        assistant?.content.flatMap((part) => {
          if (part.type !== "tool" || part.state.status !== "running") return []

          if (part.name !== "shell" && part.name !== "subagent") return []
          const value = part.name === "shell" ? part.state.metadata.shellID : part.state.metadata.sessionID
          const label = part.name === "shell" ? part.state.input.command : part.state.input.description

          return [
            {
              type: part.name as "shell" | "subagent",
              partID: part.id,
              id: typeof value === "string" ? value : undefined,
              label: typeof label === "string" ? label : undefined,
            },
          ]
        }) ?? [],
    }
  })

  const blocking = createMemo(() => history().blocking)

  const tasks = createMemo(() => {
    const id = input.sessionID()

    if (!id) return []
    const current = history()

    const active = input.sessions().flatMap((info) => {
      if (info?.parentID !== id) return []

      if (input.status(info.id) === "idle") return []

      if (
        current.blocking.some(
          (item) => item.type === "subagent" && (item.id === info.id || (!!item.label && info.title === item.label)),
        )
      )
        return []

      return [{ id: info.id, type: "subagent" as const, label: info.title ?? info.id }]
    })

    const running = input.shells().flatMap((shell) => {
      if (shell.status !== "running" || shell.metadata.sessionID !== id) return []

      if (
        current.blocking.some(
          (item) => item.type === "shell" && (item.id === shell.id || (!!item.label && shell.command === item.label)),
        )
      )
        return []

      return [{ id: shell.id, type: "shell" as const, label: shell.command }]
    })

    return [
      ...new Map<string, Task>(
        [...current.subagents, ...active, ...current.shells, ...running].map((task) => [task.id, task]),
      ).values(),
    ]
  })

  return { blocking, tasks }
}

import { createEffect, createMemo } from "solid-js"
import { createStore } from "solid-js/store"
import type { FormInfo, PermissionRequest } from "@opencode/client/promise"
import { useParams } from "@solidjs/router"
import { showToast } from "@/shell/notifications/toast"
import { useServerSDK } from "@/runtime/server/client"
import { useLanguage } from "@/runtime/i18n/language"
import { projectSettingsKey, useSettings } from "@/settings/model"
import { useWorkspaceLocation } from "@/workspaces/location"
import { sessionPermissionRequest, sessionFormRequest, sessionTreeIDs } from "@/session/requests/session-request-tree"
import { createWebSearchRequest } from "./websearch"
import { createSessionBackground } from "@/session/requests/background"
import { useData } from "@/runtime/server/current"

export function createSessionRequestModel() {
  const params = useParams()
  const sdk = useWorkspaceLocation()
  const serverSDK = useServerSDK()
  const data = useData()
  const language = useLanguage()
  const settings = useSettings()
  createEffect(() => {
    const id = params.id

    if (!id || serverSDK.connection.status() !== "connected") return
    void Promise.all([data.shell.sync({ directory: sdk().directory }), data.session.permission.sync(id)]).catch(
      () => undefined,
    )
  })
  createEffect(() => {
    const id = params.id

    if (!id || serverSDK.connection.status() !== "connected") return
    void Promise.all(
      sessionTreeIDs(data.session.list(), id).map((sessionID) => data.session.form.sync(sessionID)),
    ).catch(() => undefined)
  })

  const formRequest = createMemo((): FormInfo | undefined => {
    return sessionFormRequest(data.session.list(), data.session.form.list, params.id)
  })

  const websearch = createWebSearchRequest({
    owner: () => params.id,
    connected: () => serverSDK.connection.status() === "connected",
    request: () => {
      const form = formRequest()

      return form?.metadata?.kind === "websearch.provider" ? form : undefined
    },
    providers: async (sessionID) => {
      const session = data.session.get(sessionID) ?? (await serverSDK.api.session.get({ sessionID }))

      const result = await serverSDK.api.websearch.providers({
        location: { directory: session.location.directory },
      })

      return result.data.map((provider) => ({ value: provider.id, label: provider.name }))
    },
    reply: (input) => data.session.form.reply(input),
    events: serverSDK.event,
  })

  const questionRequest = createMemo(() => {
    if (websearch.request()) return
    const form = formRequest()

    return form?.metadata?.kind === "question" ? form : undefined
  })

  const permissionRequest = createMemo((): PermissionRequest | undefined => {
    const id = params.id

    const project = projectSettingsKey(serverSDK.scope, id ? data.session.get(id)?.projectID : undefined)

    if (settings.permissions.autoApproves(project)) return

    return sessionPermissionRequest(data.session.list(), data.session.permission.list, id)
  })

  const blocked = createMemo(() => {
    const id = params.id

    if (!id) return false

    return !!permissionRequest() || !!questionRequest() || !!websearch.request()
  })

  const primary = () => {
    const id = params.id

    return !!id && !data.session.get(id)?.parentID
  }

  // Inside a subagent, running work is the parent's, so the header lists its siblings.
  const owner = createMemo(() => {
    const id = params.id

    if (!id) return

    return data.session.get(id)?.parentID ?? id
  })

  const running = createSessionBackground({
    sessionID: owner,
    messages: data.session.message.list,
    sessions: data.session.list,
    status: data.session.status,
    shells: () => data.shell.list({ directory: sdk().directory }),
  })

  // Moving to the background and the extensions' background list stay with the primary session's own work.
  const blocking = createMemo(() => (primary() ? running.blocking() : []))
  const tasks = createMemo(() => (primary() ? running.tasks() : []))

  const moveToBackground = async () => {
    if (!primary()) return
    const sessionID = params.id

    if (!sessionID) return
    await serverSDK.api.session.background({ sessionID }).catch((error) => {
      showToast({
        title: language.t("common.requestFailed"),
        description: error instanceof Error ? error.message : String(error),
      })
    })
  }

  const [store, setStore] = createStore<{ responding: string | undefined }>({ responding: undefined })

  const permissionResponding = createMemo(() => {
    const perm = permissionRequest()

    if (!perm) return false

    return store.responding === perm.id
  })

  const decide = (response: "once" | "always" | "reject") => {
    const perm = permissionRequest()

    if (!perm) return

    if (store.responding === perm.id) return

    setStore("responding", perm.id)
    serverSDK.api.permission
      .reply({ sessionID: perm.sessionID, requestID: perm.id, decision: response })
      .catch((error) => {
        showToast({
          title: language.t("common.requestFailed"),
          description: error instanceof Error ? error.message : String(error),
        })
      })
      .finally(() => {
        setStore("responding", (id) => (id === perm.id ? undefined : id))
      })
  }

  return {
    blocked,
    questionRequest,
    websearch,
    permissionRequest,
    permissionResponding,
    background: {
      blocking,
      tasks,
      running: { sessionID: owner, blocking: running.blocking, tasks: running.tasks },
      move: moveToBackground,
    },
    decide,
  }
}

export type SessionRequestModel = ReturnType<typeof createSessionRequestModel>

import { For, Show, createEffect, createMemo, onCleanup, onMount, type Component } from "solid-js"
import { createStore } from "solid-js/store"
import { useMutation } from "@tanstack/solid-query"
import { Button } from "@opencode/ui/button"
import { IconButton } from "@opencode/ui/icon-button"
import { Tooltip } from "@opencode/ui/tooltip"
import { DockPrompt } from "@opencode/session-ui/dock-prompt"
import { Icon } from "@opencode/ui/icon"
import { TextInput } from "@opencode/ui/text-input"
import { useSpring } from "@opencode/ui/motion-spring"
import { showToast } from "@/shell/notifications/toast"
import type { FormAnswer, FormInfo, FormMultiselectField, FormStringField } from "@opencode/client/promise"
import { useLanguage } from "@/runtime/i18n/language"
import { makeEventListener } from "@solid-primitives/event-listener"
import { createResizeObserver } from "@solid-primitives/resize-observer"
import { useServerSDK } from "@/runtime/server/client"
import { ScopedKey } from "@/runtime/server/scope"
import { useCommand } from "@/shell/commands/command"

const cache = new Map<string, { tab: number; answers: string[][]; custom: string[]; customOn: boolean[] }>()

const IS_MAC = /(Mac|iPod|iPhone|iPad)/.test(navigator.platform)

type QuestionField = FormStringField | FormMultiselectField

function questionField(field: FormInfo["fields"][number]): field is QuestionField {
  return field.type === "string" || field.type === "multiselect"
}

function Mark(props: { multi: boolean; picked: boolean }) {
  return (
    <span data-slot="question-option-check" aria-hidden="true">
      <span data-slot="question-option-box" data-type={props.multi ? "checkbox" : "radio"} data-picked={props.picked}>
        <Show when={props.multi} fallback={<span data-slot="question-option-radio-dot" />}>
          <Icon name="check" size="normal" />
        </Show>
      </span>
    </span>
  )
}

function Option(props: {
  multi: boolean
  picked: boolean
  label: string
  description?: string
  shortcut?: string
  disabled: boolean
  ref?: (el: HTMLButtonElement) => void
  onFocus?: VoidFunction
  onClick: VoidFunction
}) {
  return (
    <button
      type="button"
      ref={props.ref}
      data-slot="question-option"
      data-picked={props.picked}
      role={props.multi ? "checkbox" : "radio"}
      aria-checked={props.picked}
      aria-keyshortcuts={props.shortcut}
      disabled={props.disabled}
      onFocus={props.onFocus}
      onClick={props.onClick}
    >
      <Mark multi={props.multi} picked={props.picked} />
      <span data-slot="question-option-main">
        <span data-slot="option-label">
          <bdi>{props.label}</bdi>
        </span>
        <Show when={props.description}>
          <span data-slot="option-description">
            <bdi>{props.description}</bdi>
          </span>
        </Show>
      </span>
    </button>
  )
}

export const SessionQuestionDock: Component<{ request: FormInfo; onSubmit: () => void }> = (props) => {
  const serverSDK = useServerSDK()
  const language = useLanguage()
  const command = useCommand()
  const cacheKey = ScopedKey.from(serverSDK.scope, props.request.id)

  const questions = createMemo(() =>
    props.request.fields.filter(questionField).map((field) => ({
      field,
      header: field.title ?? "",
      question: field.description ?? field.title ?? "",
      options: field.type === "string" ? (field.options ?? []) : field.options,
      multiple: field.type === "multiselect",
    })),
  )

  const total = createMemo(() => questions().length)

  const cached = cache.get(cacheKey)

  const [store, setStore] = createStore({
    tab: cached?.tab ?? 0,
    answers: cached?.answers ?? [],
    custom: cached?.custom ?? [],
    customOn: cached?.customOn ?? [],
    editing: false,
    focus: 0,
    minimized: false,
    optionsHeight: 180,
  })

  let root: HTMLDivElement | undefined
  let optionsRef: HTMLDivElement | undefined
  let customRef: HTMLButtonElement | undefined
  let customInput: HTMLInputElement | undefined
  let optsRef: HTMLButtonElement[] = []
  let replied = false
  let focusFrame: number | undefined

  const question = createMemo(() => questions()[store.tab])
  const options = createMemo(() => question()?.options ?? [])
  const input = createMemo(() => store.custom[store.tab] ?? "")
  const on = createMemo(() => store.customOn[store.tab] === true)
  const multi = createMemo(() => question()?.multiple === true)
  const count = createMemo(() => options().length + 1)

  const summary = createMemo(() => {
    if (total() === 1) return language.t("session.question.title")
    const n = Math.min(store.tab + 1, total())

    return language.t("session.question.progress", { current: n, total: total() })
  })

  const customLabel = () => language.t("ui.question.custom.answerPlaceholder")

  const last = createMemo(() => store.tab >= total() - 1)
  const collapse = useSpring(() => (store.minimized ? 1 : 0), { visualDuration: 0.3, bounce: 0 })
  const hidden = createMemo(() => Math.max(0, Math.min(1, collapse())))
  const optionsOff = createMemo(() => hidden() > 0.98)

  const customUpdate = (value: string, selected: boolean = on()) => {
    const prev = input().trim()
    const next = value.trim()

    setStore("custom", store.tab, value)

    if (!selected) return

    if (multi()) {
      setStore("answers", store.tab, (current = []) => {
        const removed = prev ? current.filter((item) => item.trim() !== prev) : current

        if (!next) return removed

        if (removed.some((item) => item.trim() === next)) return removed

        return [...removed, next]
      })

      return
    }

    setStore("answers", store.tab, next ? [next] : [])
  }

  const measure = () => {
    if (!root) return

    const scroller = document.querySelector(".scroll-view__viewport")
    const head = scroller instanceof HTMLElement ? scroller.firstElementChild : undefined

    const top =
      head instanceof HTMLElement && head.classList.contains("sticky") ? head.getBoundingClientRect().bottom : 0

    if (!top) {
      root.style.removeProperty("--question-prompt-max-height")

      return
    }

    const dock = root.closest('[data-component="session-composer-dock"]')

    if (!(dock instanceof HTMLElement)) return

    const dockBottom = dock.getBoundingClientRect().bottom
    const below = Math.max(0, dockBottom - root.getBoundingClientRect().bottom)
    const gap = 8
    const max = Math.max(240, Math.floor(dockBottom - top - gap - below))
    root.style.setProperty("--question-prompt-max-height", `${max}px`)
  }

  const clamp = (i: number) => Math.max(0, Math.min(count() - 1, i))

  const pickFocus = (tab: number = store.tab) => {
    const list = questions()[tab]?.options ?? []

    if (store.customOn[tab] === true) return list.length

    return Math.max(
      0,
      list.findIndex((item) => store.answers[tab]?.includes(item.value) ?? false),
    )
  }

  const focus = (i: number) => {
    const next = clamp(i)
    setStore("focus", next)

    if (store.editing) return

    if (focusFrame !== undefined) cancelAnimationFrame(focusFrame)
    focusFrame = requestAnimationFrame(() => {
      focusFrame = undefined
      const el = next === options().length ? customRef : optsRef[next]
      el?.focus()
    })
  }

  onMount(() => {
    let raf: number | undefined

    const update = () => {
      if (raf !== undefined) cancelAnimationFrame(raf)
      raf = requestAnimationFrame(() => {
        raf = undefined
        measure()
      })
    }

    update()

    makeEventListener(window, "resize", update)

    const dock = root?.closest('[data-component="session-composer-dock"]')
    const scroller = document.querySelector(".scroll-view__viewport")
    createResizeObserver([dock, scroller], update)

    onCleanup(() => {
      if (raf !== undefined) cancelAnimationFrame(raf)
    })

    focus(pickFocus())
  })

  createEffect(() => {
    const el = optionsRef

    if (!el) return
    const update = () => setStore("optionsHeight", (height) => Math.max(height, el.scrollHeight))
    update()
    createResizeObserver(el, update)
  })

  onCleanup(() => {
    if (focusFrame !== undefined) cancelAnimationFrame(focusFrame)

    if (replied) return
    cache.set(cacheKey, {
      tab: store.tab,
      answers: store.answers.map((a) => (a ? [...a] : [])),
      custom: store.custom.map((s) => s ?? ""),
      customOn: store.customOn.map((b) => b ?? false),
    })
  })

  const fail = (err: Error) => showToast({ title: language.t("common.requestFailed"), description: err.message })

  const replyMutation = useMutation(() => ({
    mutationFn: (answer: FormAnswer) =>
      serverSDK.api.session.form.reply({ sessionID: props.request.sessionID, formID: props.request.id, answer }),
    onMutate: () => {
      props.onSubmit()
    },
    onSuccess: () => {
      replied = true
      cache.delete(cacheKey)
    },
    onError: fail,
  }))

  const rejectMutation = useMutation(() => ({
    mutationFn: () =>
      serverSDK.api.session.form.cancel({ sessionID: props.request.sessionID, formID: props.request.id }),
    onMutate: () => {
      props.onSubmit()
    },
    onSuccess: () => {
      replied = true
      cache.delete(cacheKey)
    },
    onError: fail,
  }))

  const sending = createMemo(() => replyMutation.isPending || rejectMutation.isPending)
  const submitShortcut = () => (IS_MAC ? "⌘⏎" : `${language.t("common.key.ctrl")}+⏎`)
  const backShortcut = () => (IS_MAC ? "⌘[" : `${language.t("common.key.alt")}+←`)

  const reply = (answer: FormAnswer) => {
    if (sending()) return
    replyMutation.mutate(answer)
  }

  const reject = () => {
    if (sending()) return
    rejectMutation.mutate()
  }

  const submit = () =>
    reply(
      Object.fromEntries(
        questions().flatMap((question, index) => {
          const answers = store.answers[index] ?? []

          if (answers.length === 0) return []

          return [[question.field.key, question.multiple ? answers : answers[0]]]
        }),
      ),
    )

  const answered = (i: number) => {
    if ((store.answers[i]?.length ?? 0) > 0) return true

    return store.customOn[i] === true && (store.custom[i] ?? "").trim().length > 0
  }

  const picked = (answer: string) => store.answers[store.tab]?.includes(answer) ?? false

  const pick = (answer: string) => {
    setStore("answers", store.tab, [answer])
    setStore("customOn", store.tab, false)
    setStore("editing", false)
  }

  const toggle = (answer: string) => {
    setStore("answers", store.tab, (current = []) => {
      if (current.includes(answer)) return current.filter((item) => item !== answer)

      return [...current, answer]
    })
  }

  const customToggle = () => {
    if (sending()) return
    setStore("focus", options().length)

    if (!multi()) {
      setStore("customOn", store.tab, true)
      setStore("editing", true)
      customUpdate(input(), true)
      customInput?.focus()

      return
    }

    const next = !on()
    setStore("customOn", store.tab, next)

    if (next) {
      setStore("editing", true)
      customUpdate(input(), true)
      customInput?.focus()

      return
    }

    const value = input().trim()

    if (value) setStore("answers", store.tab, (current = []) => current.filter((item) => item.trim() !== value))
    setStore("editing", false)
    focus(options().length)
  }

  const move = (step: number) => {
    if (store.editing || sending()) return
    focus(store.focus + step)
  }

  const nav = (event: KeyboardEvent) => {
    if (event.defaultPrevented) return

    if (event.key === "Escape") {
      event.preventDefault()
      reject()

      return
    }

    const previous = IS_MAC
      ? event.metaKey && !event.ctrlKey && !event.altKey && event.key === "["
      : event.altKey && !event.ctrlKey && !event.metaKey && event.key === "ArrowLeft"

    if (previous) {
      if (event.repeat) return
      event.preventDefault()
      back()

      return
    }

    const mod = (event.metaKey || event.ctrlKey) && !event.altKey

    if (mod && event.key === "Enter") {
      if (event.repeat) return
      event.preventDefault()
      next()

      return
    }

    const target =
      event.target instanceof HTMLElement ? event.target.closest('[data-slot="question-options"]') : undefined

    if (store.editing) return

    if (event.altKey || event.ctrlKey || event.metaKey) return

    if (/^[1-9]$/.test(event.key)) {
      if (event.repeat || event.isComposing || store.minimized || sending()) return
      const index = Number(event.key) - 1

      if (index >= count()) return
      event.preventDefault()

      if (index === options().length) {
        customToggle()

        return
      }

      selectOption(index)
      focus(index)

      return
    }

    if (!(target instanceof HTMLElement)) return

    if (event.key === "ArrowDown" || event.key === "ArrowRight") {
      event.preventDefault()
      move(1)

      return
    }

    if (event.key === "ArrowUp" || event.key === "ArrowLeft") {
      event.preventDefault()
      move(-1)

      return
    }

    if (event.key === "Home") {
      event.preventDefault()
      focus(0)

      return
    }

    if (event.key !== "End") return
    event.preventDefault()
    focus(count() - 1)
  }

  const selectOption = (optIndex: number) => {
    if (sending()) return

    const opt = options()[optIndex]

    if (!opt) return

    if (multi()) {
      setStore("editing", false)
      toggle(opt.value)

      return
    }

    pick(opt.value)
  }

  const commitCustom = () => {
    setStore("editing", false)
    customUpdate(input())
    focus(options().length)
  }

  const next = () => {
    if (sending()) return

    if (store.editing) commitCustom()

    if (store.tab >= total() - 1) {
      submit()

      return
    }

    jump(store.tab + 1)
  }

  const back = () => {
    if (sending()) return

    if (store.tab <= 0) return
    jump(store.tab - 1)
  }

  const jump = (tab: number) => {
    if (sending() || tab === store.tab) return
    setStore("tab", tab)
    setStore("editing", false)

    if (optionsRef) setStore("optionsHeight", optionsRef.scrollHeight)

    if (!store.minimized) focus(pickFocus(tab))
  }

  command.register("session.question.back", () => [
    {
      id: "session.question.back",
      title: language.t("ui.common.back"),
      keybind: IS_MAC ? "mod+[" : "alt+arrowleft",
      hidden: true,
      // Stay registered while sending so the shortcut does not fall through to history navigation.
      disabled: store.tab <= 0,
      when: () => store.tab > 0,
      onSelect: back,
    },
  ])

  const minimize = () => {
    if (sending()) return
    setStore("editing", false)
    setStore("minimized", true)
  }

  const restore = () => {
    if (sending()) return
    setStore("minimized", false)
    focus(pickFocus())
  }

  return (
    <div data-component="session-question-dock">
      <DockPrompt
        kind="question"
        ref={(el) => (root = el)}
        onKeyDown={nav}
        header={
          <>
            <div data-slot="question-header-top">
              <div data-slot="question-header-title">
                <bdi>{summary()}</bdi>
              </div>
              <div data-slot="question-header-actions">
                <Show when={total() > 1}>
                  <div data-slot="question-progress">
                    <For each={questions()}>
                      {(_, i) => (
                        <button
                          type="button"
                          data-slot="question-progress-segment"
                          data-active={i() === store.tab}
                          data-answered={answered(i())}
                          disabled={sending()}
                          onClick={() => jump(i())}
                          aria-label={language.t("ui.tool.questions.numbered", { number: i() + 1 })}
                          aria-current={i() === store.tab ? "step" : undefined}
                        />
                      )}
                    </For>
                  </div>
                </Show>
                <IconButton
                  icon={<Icon name="outline-chevron-down" size="normal" />}
                  variant="ghost"
                  size="large"
                  disabled={sending()}
                  style={{ transform: `rotate(${hidden() * 180}deg)` }}
                  onClick={store.minimized ? restore : minimize}
                  aria-label={language.t(store.minimized ? "session.question.restore" : "session.question.minimize")}
                />
              </div>
            </div>
            <div data-slot="question-details">
              <div
                data-slot="question-text"
                style={{
                  display: store.minimized ? "-webkit-box" : undefined,
                  "-webkit-line-clamp": store.minimized ? "3" : undefined,
                  "-webkit-box-orient": store.minimized ? "vertical" : undefined,
                  overflow: store.minimized ? "hidden" : undefined,
                }}
              >
                <bdi>{question()?.question}</bdi>
              </div>
              <Show when={!store.minimized}>
                <div data-slot="question-hint">
                  {language.t(multi() ? "ui.question.multiHint" : "ui.question.singleHint")}
                </div>
              </Show>
            </div>
          </>
        }
        footer={
          <>
            <Button variant="ghost" size="large" disabled={sending()} onClick={reject} aria-keyshortcuts="Escape">
              {language.t("ui.common.dismiss")}
            </Button>
            <div data-slot="question-footer-actions">
              <Show when={store.tab > 0}>
                <Tooltip
                  placement="top"
                  value={
                    <>
                      {language.t("ui.common.back")}
                      <span style={{ opacity: 0.6 }}>{backShortcut()}</span>
                    </>
                  }
                >
                  <Button
                    variant="neutral"
                    size="large"
                    disabled={sending()}
                    onClick={back}
                    aria-keyshortcuts={IS_MAC ? "Meta+[" : "Alt+ArrowLeft"}
                  >
                    {language.t("ui.common.back")}
                  </Button>
                </Tooltip>
              </Show>
              <Tooltip
                placement="top"
                value={
                  <>
                    {language.t(last() ? "ui.common.submit" : "ui.common.next")}
                    <span style={{ opacity: 0.6 }}>{submitShortcut()}</span>
                  </>
                }
              >
                <Button
                  variant={last() ? "submit" : "neutral"}
                  size="large"
                  disabled={sending()}
                  onClick={next}
                  aria-keyshortcuts="Meta+Enter Control+Enter"
                >
                  {language.t(last() ? "ui.common.submit" : "ui.common.next")}
                  <span data-slot="question-submit-shortcut" aria-hidden="true">
                    {submitShortcut()}
                  </span>
                </Button>
              </Tooltip>
            </div>
          </>
        }
      >
        <div
          ref={(el) => (optionsRef = el)}
          data-slot="question-options"
          role={multi() ? "group" : "radiogroup"}
          aria-label={question()?.question}
          inert={store.minimized}
          aria-hidden={store.minimized || optionsOff() ? "true" : undefined}
          classList={{ "pointer-events-none": hidden() > 0.1 }}
          style={{
            "max-height": `${Math.max(0, store.optionsHeight * (1 - hidden()))}px`,
            opacity: `${Math.max(0, Math.min(1, 1 - hidden()))}`,
            visibility: optionsOff() ? "hidden" : "visible",
          }}
        >
          <For each={options()}>
            {(opt, i) => (
              <Option
                multi={multi()}
                picked={picked(opt.value)}
                label={opt.label}
                description={opt.description}
                shortcut={i() < 9 ? String(i() + 1) : undefined}
                disabled={sending()}
                ref={(el) => (optsRef[i()] = el)}
                onFocus={() => setStore("focus", i())}
                onClick={() => selectOption(i())}
              />
            )}
          </For>

          <div
            data-slot="question-option"
            data-custom="true"
            data-picked={on()}
            data-editing={store.editing}
            data-disabled={sending()}
            onClick={(event) => {
              if (event.target !== event.currentTarget || sending()) return
              setStore("focus", options().length)
              setStore("customOn", store.tab, true)
              setStore("editing", true)
              customUpdate(input(), true)
              customInput?.focus()
            }}
          >
            <button
              type="button"
              ref={customRef}
              data-slot="question-custom-toggle"
              role={multi() ? "checkbox" : "radio"}
              aria-checked={on()}
              aria-label={customLabel()}
              aria-keyshortcuts={count() <= 9 ? String(count()) : undefined}
              disabled={sending()}
              onFocus={() => setStore("focus", options().length)}
              onClick={customToggle}
            >
              <Mark multi={multi()} picked={on()} />
            </button>
            <TextInput
              ref={(el) => (customInput = el)}
              class="question-custom-field"
              dir="auto"
              aria-label={customLabel()}
              placeholder={customLabel()}
              value={input()}
              disabled={sending()}
              onFocus={() => {
                if (focusFrame !== undefined) cancelAnimationFrame(focusFrame)
                focusFrame = undefined
                setStore("focus", options().length)
                setStore("editing", true)
              }}
              onClick={() => {
                setStore("customOn", store.tab, true)
                customUpdate(input(), true)
              }}
              onBlur={() => setStore("editing", false)}
              onKeyDown={(e) => {
                if (e.key === "Escape") {
                  e.preventDefault()
                  setStore("editing", false)
                  focus(options().length)

                  return
                }

                if ((e.metaKey || e.ctrlKey) && !e.altKey) return

                if (e.key !== "Enter") return
                e.preventDefault()
                commitCustom()
              }}
              onInput={(e) => {
                setStore("customOn", store.tab, true)
                customUpdate(e.currentTarget.value, true)
              }}
            />
          </div>
        </div>
      </DockPrompt>
    </div>
  )
}

import { describe, expect, test } from "bun:test"
import type { FormInfo, PermissionRequest, SessionInfo } from "@opencode/client/promise"
import { sessionPermissionRequest, sessionFormRequest, sessionTreeIDs } from "@/session/requests/session-request-tree"

const session = (input: { id: string; parentID?: string }) =>
  ({
    id: input.id,
    parentID: input.parentID,
  }) as SessionInfo

const permission = (id: string, sessionID: string) =>
  ({
    id,
    sessionID,
  }) as PermissionRequest

const question = (id: string, sessionID: string) =>
  ({
    id,
    sessionID,
    title: "Questions",
    metadata: { kind: "question" },
    fields: [{ key: "q0", type: "string" }],
  }) as FormInfo

describe("sessionTreeIDs", () => {
  test("returns only the current session and its descendants", () => {
    const sessions = [
      session({ id: "root" }),
      session({ id: "child", parentID: "root" }),
      session({ id: "grand", parentID: "child" }),
      session({ id: "sibling", parentID: "root" }),
      session({ id: "other" }),
    ]

    expect(sessionTreeIDs(sessions, "child")).toEqual(["child", "grand"])
    expect(sessionTreeIDs(sessions, "root")).toEqual(["root", "child", "sibling", "grand"])
    expect(sessionTreeIDs(sessions)).toEqual([])
  })
})

const tree = [
  session({ id: "root" }),
  session({ id: "child", parentID: "root" }),
  session({ id: "grand", parentID: "child" }),
  session({ id: "other" }),
]

const search = (id: string, sessionID: string) => ({
  ...question(id, sessionID),
  metadata: { kind: "websearch.provider" },
})

describe("sessionPermissionRequest", () => {
  const both = { root: [permission("perm-root", "root")], child: [permission("perm-child", "child")] }

  test.each([
    ["prefers the current session permission", both, undefined, "perm-root"],
    [
      "returns a nested child permission",
      { grand: [permission("perm-grand", "grand")], other: [permission("perm-other", "other")] },
      undefined,
      "perm-grand",
    ],
    [
      "returns undefined without a matching tree permission",
      { other: [permission("perm-other", "other")] },
      undefined,
      undefined,
    ],
    [
      "skips filtered permissions in the current tree",
      both,
      (item: PermissionRequest) => item.id !== "perm-root",
      "perm-child",
    ],
    ["returns undefined when all tree permissions are filtered out", both, () => false, undefined],
  ])("%s", (_name, permissions, include, id) => {
    expect(sessionPermissionRequest(tree, permissions, "root", include)?.id).toBe(id)
  })
})

describe("sessionFormRequest", () => {
  test.each([
    [
      "prefers the current session question",
      { root: [question("q-root", "root")], child: [question("q-child", "child")] },
      "q-root",
    ],
    ["returns a nested child question", { grand: [question("q-grand", "grand")] }, "q-grand"],
    [
      "skips unsupported forms",
      { root: [{ ...question("form", "root"), metadata: { kind: "integration" } }] },
      undefined,
    ],
    ["finds web search consent in a nested child session", { child: [search("search", "child")] }, "search"],
    [
      "keeps web search ahead of a later question",
      { root: [search("search", "root"), question("q", "root")] },
      "search",
    ],
    ["keeps a question ahead of a later web search", { root: [question("q", "root"), search("search", "root")] }, "q"],
    [
      "keeps the current session ahead of a child question",
      { root: [search("search", "root")], child: [question("q", "child")] },
      "search",
    ],
  ])("%s", (_name, forms, id) => {
    expect(sessionFormRequest(tree, forms, "root")?.id).toBe(id)
  })
})

import type { FormInfo, PermissionRequest, SessionInfo } from "@opencode/client/promise"

function sessionTreeRequest<T>(
  session: SessionInfo[],
  request: Record<string, T[] | undefined> | ((sessionID: string) => T[] | undefined),
  sessionID?: string,
  include: (item: T) => boolean = () => true,
) {
  const ids = sessionTreeIDs(session, sessionID)

  if (!ids.length) return
  const list = (id: string) => (typeof request === "function" ? request(id) : request[id])
  const id = ids.find((id) => list(id)?.some(include))

  if (!id) return

  return list(id)?.find(include)
}

export function sessionTreeIDs(session: SessionInfo[], sessionID?: string) {
  if (!sessionID) return []

  const map = session.reduce((acc, item) => {
    if (!item.parentID) return acc
    const list = acc.get(item.parentID)

    if (list) list.push(item.id)

    if (!list) acc.set(item.parentID, [item.id])

    return acc
  }, new Map<string, string[]>())

  const seen = new Set([sessionID])
  const ids = [sessionID]

  for (const id of ids) {
    const list = map.get(id)

    if (!list) continue

    for (const child of list) {
      if (seen.has(child)) continue
      seen.add(child)
      ids.push(child)
    }
  }

  return ids
}

export function sessionPermissionRequest(
  session: SessionInfo[],
  request: Record<string, PermissionRequest[] | undefined> | ((sessionID: string) => PermissionRequest[] | undefined),
  sessionID?: string,
  include?: (item: PermissionRequest) => boolean,
) {
  return sessionTreeRequest(session, request, sessionID, include)
}

export function sessionFormRequest(
  session: SessionInfo[],
  request: Record<string, FormInfo[] | undefined> | ((sessionID: string) => FormInfo[] | undefined),
  sessionID?: string,
) {
  return sessionTreeRequest(
    session,
    request,
    sessionID,
    (item) => item.metadata?.kind === "question" || item.metadata?.kind === "websearch.provider",
  )
}

import { createMemo, Show } from "solid-js"
import { Button } from "@opencode/ui/button"
import { DockShell, DockTray } from "@opencode/ui/dock-surface"
import { Select } from "@opencode/ui/select"
import { useLanguage } from "@/runtime/i18n/language"
import { SettingsRow } from "@/settings/row"
import type { WebSearchRequestModel } from "./websearch"
import "./session-websearch-dock.css"

export function SessionWebSearchDock(props: { model: WebSearchRequestModel; onSubmit: () => void }) {
  const language = useLanguage()

  const options = createMemo(() => [
    ...(props.model.specific() ? [] : [{ value: "random", label: language.t("session.websearch.any") }]),
    ...props.model.options(),
  ])

  const current = createMemo(() => options().find((option) => option.value === props.model.selected()))
  const busy = () => props.model.sending() || !props.model.connected()

  const status = () => {
    if (props.model.loading()) return language.t("common.loading")

    if (props.model.failed()) return language.t("session.websearch.failed")

    if (!props.model.options().length) return language.t("session.websearch.empty")
  }

  const unavailable = () => props.model.loading() || props.model.loadFailed() || !props.model.options().length

  const submit = (selection: string | false) => {
    if (busy()) return
    props.onSubmit()
    void props.model.submit(selection)
  }

  return (
    <section
      data-component="session-websearch-dock"
      aria-label={language.t("session.websearch.title")}
      aria-busy={props.model.sending()}
    >
      <DockShell class="websearch-body">
        <div class="websearch-setting">
          <SettingsRow
            title={language.t("session.websearch.title")}
            description={language.t("session.websearch.description")}
          >
            <Select
              aria-label={language.t("session.websearch.provider")}
              options={options()}
              current={current()}
              value={(option) => option.value}
              label={(option) => option.label}
              onSelect={(option) => option && props.model.select(option.value)}
              disabled={busy() || unavailable()}
              placeholder={language.t("session.websearch.provider")}
              contentClass="websearch-provider-menu"
            />
          </SettingsRow>
        </div>
      </DockShell>
      <DockTray attach="top" class="websearch-footer">
        <div class="websearch-status" aria-live="polite">
          <Show when={props.model.loadFailed()} fallback={status()}>
            <span>{language.t("session.websearch.loadFailed")}</span>
            <Button variant="ghost" size="small" onClick={props.model.retry} disabled={busy()}>
              {language.t("session.websearch.retry")}
            </Button>
          </Show>
        </div>
        <div class="websearch-actions">
          <Show when={!props.model.specific()}>
            <Button variant="ghost" size="small" onClick={() => submit(false)} disabled={busy()}>
              {language.t("session.websearch.disable")}
            </Button>
          </Show>
          <Button
            variant="submit"
            size="small"
            onClick={() => {
              const selected = props.model.selected()

              if (selected) submit(selected)
            }}
            disabled={busy() || unavailable() || !current()}
          >
            {language.t("session.websearch.enable")}
          </Button>
        </div>
      </DockTray>
    </section>
  )
}

import { describe, expect, test } from "bun:test"
import type { FormAnswer, FormCreated, SessionFormReplyInput, OpenCodeEvent } from "@opencode/client/promise"
import { replyWebSearch } from "./websearch"

const consent: FormCreated["data"]["form"] = {
  id: "frm_consent",
  sessionID: "ses_child",
  title: "Web Search",
  metadata: { kind: "websearch.provider" },
  fields: [{ key: "choice", type: "string", required: true, custom: false }],
}

const provider: FormCreated["data"]["form"] = {
  ...consent,
  id: "frm_provider",
  fields: [
    {
      key: "provider",
      type: "string",
      required: true,
      custom: false,
      options: [
        { value: "exa", label: "Exa" },
        { value: "parallel", label: "Parallel" },
      ],
    },
  ],
}

function fixture() {
  const listeners = new Set<(event: OpenCodeEvent) => void>()
  const replies: SessionFormReplyInput[] = []
  const abort = new AbortController()
  const emit = (event: OpenCodeEvent) => listeners.forEach((listener) => listener(event))

  return {
    form: consent,
    signal: abort.signal,
    abort,
    listeners,
    replies,
    events: {
      listen(listener: (event: OpenCodeEvent) => void) {
        listeners.add(listener)

        return () => {
          listeners.delete(listener)
        }
      },
    },
    reply: async (input: SessionFormReplyInput) => {
      replies.push(input)
    },
    create: (form = provider) => emit({ id: "evt_create", created: 0, type: "form.created", data: { form } }),
    cancel: (id: string) =>
      emit({
        id: "evt_cancel",
        created: 0,
        type: "form.cancelled",
        data: { id, sessionID: consent.sessionID },
      }),
    answer: (id: string, answer: FormAnswer) =>
      emit({
        id: "evt_reply",
        created: 0,
        type: "form.replied",
        data: { id, sessionID: consent.sessionID, answer },
      }),
  }
}

describe("web search desktop consent", () => {
  test.each([
    ["random", "allow"],
    [false, "disable"],
  ] as const)("submits %s without a second form", async (selection, choice) => {
    const input = fixture()
    await replyWebSearch({ ...input, selection })
    expect(input.replies).toEqual([{ sessionID: consent.sessionID, formID: consent.id, answer: { choice } }])
    expect(input.listeners.size).toBe(0)
  })

  test("subscribes before the first reply and answers the owning session's provider form", async () => {
    const input = fixture()
    await replyWebSearch({
      ...input,
      selection: "parallel",
      reply: async (answer) => {
        input.replies.push(answer)

        if (answer.answer.choice === "choose") input.create()
      },
    })
    expect(input.replies).toEqual([
      { sessionID: consent.sessionID, formID: consent.id, answer: { choice: "choose" } },
      { sessionID: consent.sessionID, formID: provider.id, answer: { provider: "parallel" } },
    ])
    expect(input.listeners.size).toBe(0)
  })

  test("ignores questions, other sessions, and repeated consent forms during handoff", async () => {
    const input = fixture()
    const pending = replyWebSearch({ ...input, selection: "exa" })
    input.create({ ...provider, sessionID: "ses_other" })
    input.create({ ...provider, metadata: { kind: "question" } })
    input.create(consent)
    input.create()
    await pending
    expect(input.replies).toHaveLength(2)
    expect(input.replies[1]?.formID).toBe(provider.id)
  })

  test("leaves a changed provider list for explicit confirmation", async () => {
    const input = fixture()
    const pending = replyWebSearch({ ...input, selection: "removed" })
    input.create()
    await pending
    expect(input.replies).toHaveLength(1)
    expect(input.listeners.size).toBe(0)
  })

  test("supports direct entry into the provider form", async () => {
    const input = fixture()
    await replyWebSearch({ ...input, form: provider, selection: "exa" })
    expect(input.replies).toEqual([{ sessionID: consent.sessionID, formID: provider.id, answer: { provider: "exa" } }])
    expect(input.listeners.size).toBe(0)
  })

  test("does not misrepresent cancelling the provider form as disabling search", async () => {
    const input = fixture()
    await replyWebSearch({ ...input, form: provider, selection: false })
    expect(input.replies).toEqual([])
  })

  test.each(["cancel", "other-client", "abort"])("ends a pending handoff on %s", async (action) => {
    const input = fixture()
    const pending = replyWebSearch({ ...input, selection: "exa" })

    if (action === "cancel") input.cancel(consent.id)

    if (action === "other-client") input.answer(consent.id, { choice: "disable" })

    if (action === "abort") input.abort.abort()
    await pending
    input.create()
    expect(input.replies).toHaveLength(1)
    expect(input.listeners.size).toBe(0)
  })

  test.each([consent.id, provider.id])("propagates a failed %s submission and cleans up", async (failing) => {
    const input = fixture()
    await expect(
      replyWebSearch({
        ...input,
        selection: "exa",
        reply: async (answer) => {
          if (answer.formID === failing) throw new Error("offline")
          input.create()
        },
      }),
    ).rejects.toThrow("offline")
    expect(input.listeners.size).toBe(0)
  })
})

import type { FormInfo, FormOption, SessionFormReplyInput, FormStringField } from "@opencode/client/promise"
import { createEffect, createMemo, createResource, on, onCleanup } from "solid-js"
import { createStore } from "solid-js/store"
import type { OpenCodeEventStream } from "@/runtime/server/client"

export function webSearchProviderField(form: FormInfo) {
  return form.fields.find(
    (field): field is FormStringField => field.type === "string" && field.key === "provider" && !!field.options,
  )
}

export function createWebSearchRequest(input: {
  owner: () => string | undefined
  connected: () => boolean
  request: () => FormInfo | undefined
  providers: (sessionID: string) => Promise<FormOption[]>
  reply: (input: SessionFormReplyInput) => Promise<unknown>
  events: Pick<OpenCodeEventStream, "listen">
}) {
  const [store, setStore] = createStore({
    selected: "random",
    sending: undefined as { form: FormInfo; abort: AbortController } | undefined,
    error: false,
  })

  const [providers, resource] = createResource(input.request, async (form) => {
    const field = webSearchProviderField(form)

    if (field) return field.options ?? []

    return input.providers(form.sessionID)
  })

  const request = createMemo(() => store.sending?.form ?? input.request())

  const specific = createMemo(() => {
    const form = request()

    return !!form && !!webSearchProviderField(form)
  })

  const options = createMemo(() => (providers.error ? [] : (providers() ?? [])))

  const selected = createMemo(() => {
    if (!specific()) return store.selected

    return options().some((option) => option.value === store.selected) ? store.selected : options()[0]?.value
  })

  createEffect(
    on([input.owner, input.connected], () => {
      store.sending?.abort.abort()
      setStore({ sending: undefined, selected: "random", error: false })
    }),
  )
  createEffect(
    on(
      () => input.request()?.id,
      () => {
        const form = input.request()

        if (!form || store.sending || webSearchProviderField(form)) return
        setStore({ selected: "random", error: false })
      },
    ),
  )
  onCleanup(() => store.sending?.abort.abort())

  const submit = async (selection: string | false) => {
    const form = input.request()

    if (!form || store.sending || !input.connected()) return

    if (selection === false && webSearchProviderField(form)) return
    const sending = { form, abort: new AbortController() }
    setStore({ sending, error: false })
    await replyWebSearch({ ...input, form, selection, signal: sending.abort.signal })
      .catch(() => {
        if (!sending.abort.signal.aborted) setStore("error", true)
      })
      .finally(() => {
        if (store.sending?.abort === sending.abort) setStore("sending", undefined)
      })
  }

  return {
    request,
    options,
    selected,
    specific,
    loading: () => providers.loading,
    loadFailed: () => !!providers.error,
    failed: () => store.error,
    sending: () => !!store.sending,
    connected: input.connected,
    select: (value: string) => setStore({ selected: value, error: false }),
    retry: () => void resource.refetch(),
    submit,
  }
}

export type WebSearchRequestModel = ReturnType<typeof createWebSearchRequest>

export async function replyWebSearch(input: {
  form: FormInfo
  selection: string | false
  signal: AbortSignal
  reply: (input: SessionFormReplyInput) => Promise<unknown>
  events: Pick<OpenCodeEventStream, "listen">
}) {
  if (input.signal.aborted) return

  if (webSearchProviderField(input.form)) {
    if (input.selection === false) return

    return input.reply({
      sessionID: input.form.sessionID,
      formID: input.form.id,
      answer: { provider: input.selection },
    })
  }

  if (input.selection === false || input.selection === "random") {
    return input.reply({
      sessionID: input.form.sessionID,
      formID: input.form.id,
      answer: { choice: input.selection === false ? "disable" : "allow" },
    })
  }

  const next = Promise.withResolvers<FormInfo | undefined>()

  const stop = input.events.listen((event) => {
    if (event.type === "form.created") {
      const form = event.data.form

      if (
        form.sessionID !== input.form.sessionID ||
        form.id === input.form.id ||
        form.metadata?.kind !== "websearch.provider" ||
        !webSearchProviderField(form)
      )
        return
      next.resolve(form)
    }

    if (event.type === "form.cancelled" && event.data.id === input.form.id) next.resolve(undefined)

    if (event.type === "form.replied" && event.data.id === input.form.id && event.data.answer.choice !== "choose")
      next.resolve(undefined)
  })

  const cancel = () => next.resolve(undefined)
  input.signal.addEventListener("abort", cancel, { once: true })

  return Promise.all([
    input.reply({ sessionID: input.form.sessionID, formID: input.form.id, answer: { choice: "choose" } }),
    next.promise,
  ])
    .then(([, form]) => {
      if (!form || input.signal.aborted) return
      const field = webSearchProviderField(form)

      if (!field?.options?.some((option) => option.value === input.selection)) return

      return input.reply({
        sessionID: form.sessionID,
        formID: form.id,
        answer: { provider: input.selection },
      })
    })
    .finally(() => {
      stop()
      input.signal.removeEventListener("abort", cancel)
    })
}

import type { SessionMessageUser } from "@opencode/client/promise"
import { useComposerState } from "@/composer/persistence"
import { useData } from "@/runtime/server/current"
import { useServerSDK } from "@/runtime/server/client"
import { useWorkspaceLocation } from "@/workspaces/location"
import { useLanguage } from "@/runtime/i18n/language"

import { extractPromptContext, extractPromptFromMessage } from "@/composer/prompt"
import { promptLength } from "@/composer/prompt-parts"
import { showToast } from "@/shell/notifications/toast"
import type { SessionModel } from "./model"

export function createSessionRevert(input: {
  session: SessionModel
  setActiveMessage: (message: SessionMessageUser | undefined) => void
}) {
  const prompt = useComposerState()
  const server = useServerSDK()
  const data = useData()
  const location = useWorkspaceLocation()
  const language = useLanguage()

  const request = async <A>(action: () => Promise<A>) =>
    action()
      .then(() => true)
      .catch((error) => {
        showToast({
          title: language.t("common.requestFailed"),
          description: error instanceof Error ? error.message : String(error),
        })

        return false
      })

  const restore = (target: ReturnType<typeof prompt.capture>, message: SessionMessageUser) => {
    const restored = extractPromptFromMessage(message, {
      directory: location().directory,
      attachmentName: language.t("common.attachment"),
    })

    const context = extractPromptContext(message, { directory: location().directory })

    target.set(restored, promptLength(restored))
    // The restored prompt replaces the draft, so chips from an earlier restore do not ride along.
    target.context.replace([...context.comments, ...context.files])
  }

  const stage = async (message: SessionMessageUser, previous: SessionMessageUser | undefined) => {
    const sessionID = input.session.identity.params.id

    if (!sessionID) return
    const owner = input.session.ownership.capture()
    const target = prompt.capture()

    // An undelivered prompt has no history to rewind. Withdraw it like the TUI
    // instead of interrupting the work it is waiting behind.
    if (data.session.input.has(sessionID, message.id)) {
      if (!(await request(() => server.api.session.inbox.cancel({ sessionID, inboxID: message.id })))) return
      restore(target, message)
      owner.run(() => input.setActiveMessage(previous))

      return
    }

    // Interrupt acknowledges before the execution settles, and staging a busy Session fails. The
    // local status can lag the server either way, so always settle first; both are idle no-ops.
    // Like the TUI, stop at the first failure instead of waiting on work that was never interrupted.
    if (!(await request(() => server.api.session.interrupt({ sessionID })))) return

    if (!(await request(() => server.api.session.wait({ sessionID })))) return

    if (!(await request(() => server.api.session.revert.stage({ sessionID, messageID: message.id })))) return
    // Like the TUI, pending inputs are left alone: the revert hides them, committing it drops them,
    // and redo delivers them.
    restore(target, message)
    owner.run(() => input.setActiveMessage(previous))
  }

  const to = async (messageID: string) => {
    const messages = input.session.history.userMessages()
    const index = messages.findIndex((message) => message.id === messageID)
    const message = messages[index]

    if (!message) return
    await stage(message, messages[index - 1])
  }

  const undo = async () => {
    const messages = input.session.history.userMessages()
    const reverted = input.session.data.revertMessageID()
    const boundary = reverted ? messages.findIndex((message) => message.id === reverted) : messages.length

    if (boundary <= 0) return
    const message = messages[boundary - 1]

    if (message) await stage(message, messages[boundary - 2])
  }

  const redo = async () => {
    const sessionID = input.session.identity.params.id
    const reverted = input.session.data.revertMessageID()

    if (!sessionID || !reverted) return
    const owner = input.session.ownership.capture()

    // Like the TUI, redo restores every reverted message at once and leaves the composer alone.
    if (!(await request(() => server.api.session.revert.clear({ sessionID })))) return
    owner.run(() =>
      input.setActiveMessage(
        input.session.history
          .userMessages()
          .filter((message) => !data.session.input.has(sessionID, message.id))
          .at(-1),
      ),
    )
  }

  return { to, undo, redo }
}

export type SessionRevert = ReturnType<typeof createSessionRevert>

import { Button } from "@opencode/ui/button"
import { createMemo, Show } from "solid-js"
import { ErrorPage } from "@/shell/errors/error"
import { useLanguage } from "@/runtime/i18n/language"
import { useServer } from "@/runtime/server/current"
import { ServerConnection, serverName, useServers } from "@/runtime/server/registry"
import { useTabs } from "@/shell/tabs/tabs"
import { isLocalSessionNotFoundError, isSessionNotFoundError } from "@/runtime/server/errors"
import { IncompatibleServerPanel } from "./incompatible-server-panel"

export function SessionErrorFallback(props: { error: unknown; sessionID?: string; serverKey?: ServerConnection.Key }) {
  const language = useLanguage()
  const activeServer = useServer()
  const server = useServers()
  const tabs = useTabs()

  const displayServer = createMemo(() => {
    const conn = server.list.find((item) => ServerConnection.key(item) === props.serverKey)

    return conn ? serverName(conn) : props.serverKey
  })

  const closeSession = () => {
    if (!props.sessionID) return
    tabs.removeSessionTab({ server: activeServer.key, sessionId: props.sessionID })
  }

  return (
    <Show
      when={!activeServer.health?.incompatible}
      fallback={<IncompatibleServerPanel onClose={props.sessionID ? closeSession : undefined} />}
    >
      <Show
        when={isCurrentSessionNotFoundError(props.error, props.sessionID)}
        fallback={<ErrorPage error={props.error} />}
      >
        <div class="flex-1 min-h-0 overflow-hidden">
          <div class="h-full px-6 pb-42 -mt-4 flex flex-col items-center justify-center text-center gap-4">
            <div class="flex flex-col items-center gap-2">
              <div class="text-16-medium text-text max-w-md">{language.t("session.error.notFound")}</div>
              <div class="text-13-regular text-text-weak max-w-md">
                {language.t("session.error.notFound.description")}
              </div>
            </div>
            <Show when={props.sessionID}>
              {(sessionID) => (
                <div class="max-w-full flex flex-col items-center gap-1">
                  <div class="max-w-full text-11-regular text-text-faint break-all">{displayServer()}</div>
                  <code class="max-w-full rounded-[4px] px-1 py-0.5 font-mono text-xs font-medium leading-4 text-text-base break-all bg-[color-mix(in_oklch,var(--v2-text-text-base)_8%,transparent)]">
                    {sessionID()}
                  </code>
                </div>
              )}
            </Show>
            <Button
              variant="neutral"
              size="normal"
              icon="xmark-small"
              onClick={() => {
                if (!props.sessionID || !props.serverKey) return
                tabs.removeSessionTab({ server: props.serverKey, sessionId: props.sessionID })
              }}
            >
              {language.t("session.error.notFound.closeTab")}
            </Button>
          </div>
        </div>
      </Show>
    </Show>
  )
}

function isCurrentSessionNotFoundError(error: unknown, sessionID: string | undefined) {
  if (!sessionID) return false

  return isSessionNotFoundError(error, sessionID) || isLocalSessionNotFoundError(error, sessionID)
}

