export function TargetSessionRouteContent() {
  const params = useParams<{ serverKey: string; id: string }>()
  const data = useData()
  const server = useServer()
  const tabs = useTabs()
  const directory = createMemo(() => data.session.get(params.id)?.location.directory)

  return (
    <>
      <MarkSessionViewed sessionID={() => params.id} />
      <ModelsProvider directory={directory}>
        <TargetSessionSettingsCommand />
        <SessionRouteErrorBoundary sessionID={params.id} serverKey={requireServerKey(params.serverKey)}>
          <Show when={tabs.pendingSession(server.key, params.id)} fallback={<ResolvedTargetSessionRoute />}>
            {(pending) => <PreparingSession sessionID={params.id} pending={pending()} />}
          </Show>
        </SessionRouteErrorBoundary>
      </ModelsProvider>
    </>
  )
}

function PreparingSession(props: { sessionID: string; pending: PendingSession }) {
  const language = useLanguage()
  const providers = useProviders(() => props.pending.draft.directory)

  return (
    <SessionStatePanel>
      <DataProvider
        directory={props.pending.draft.directory}
        data={{
          session: [],
          session_status: {},
          session_diff: {},
          provider: { all: providers.all(), default: providers.default(), connected: [] },
        }}
      >
        <div data-component="session-preparing" data-workspace-session class="min-h-0 flex-1 overflow-y-auto">
          <SessionIdentityHeader sessionID={props.sessionID} />
          <div class="mx-auto w-full min-w-0 px-4 pb-5 md:max-w-session md:px-6">
            <SessionUserMessage
              sessionID={props.sessionID}
              message={props.pending.message}
              comments={readPromptPresentation(props.pending.message.metadata)?.comments}
              historicalAgent={props.pending.selection.agent}
              historicalModel={{
                id: props.pending.selection.model.modelID,
                providerID: props.pending.selection.model.providerID,
                variant: props.pending.selection.variant,
              }}
            />
            <div
              role="status"
              class="mt-3 flex min-h-6 items-center text-[13px] font-medium leading-[var(--line-height-compact)] text-v2-text-text-muted"
            >
              <TextShimmer text={language.t("session.new.worktree.creating")} active />
            </div>
          </div>
        </div>
        <PreparingComposer pending={props.pending} />
      </DataProvider>
    </SessionStatePanel>
  )
}

function TargetSessionSettingsCommand() {
  useSettingsCommand()

  return null
}

function SessionRouteErrorBoundary(props: ParentProps<{ sessionID?: string; serverKey?: ServerConnection.Key }>) {
  return (
    <ErrorBoundary
      fallback={(error) => (
        <SessionStatePanel>
          <SessionErrorFallback error={error} sessionID={props.sessionID} serverKey={props.serverKey} />
        </SessionStatePanel>
      )}
    >
      {props.children}
    </ErrorBoundary>
  )
}

function ResolvedTargetSessionRoute() {
  const params = useParams<{ id: string }>()
  const server = useServer()
  const tabs = useTabs()
  const data = useData()

  const current = createSessionResolution(
    () => params.id,
    () => data.session,
    { children: true, connected: () => server.ctx.sdk.connection.status() === "connected" },
  )

  const directory = createMemo(() => current()?.location.directory)

  return (
    <Show
      when={!server.health?.incompatible}
      fallback={
        <SessionStatePanel>
          <IncompatibleServerPanel
            onClose={() => tabs.removeSessionTab({ server: server.key, sessionId: params.id })}
          />
        </SessionStatePanel>
      }
    >
      <Show when={directory()} fallback={<PendingSessionState sessionID={params.id} />}>
        {(value) => (
          <LocationProvider directory={value()}>
            <SessionUIProvider directory={value()} server={server.key}>
              <TargetSessionPage />
            </SessionUIProvider>
          </LocationProvider>
        )}
      </Show>
    </Show>
  )
}

function PendingSessionState(props: { sessionID: string }) {
  return (
    <SessionStatePanel>
      <SessionIdentityHeader sessionID={props.sessionID} />
    </SessionStatePanel>
  )
}

function SessionStatePanel(props: ParentProps) {
  return (
    <div class="flex min-h-0 flex-1 px-[var(--shell-inline-inset,8px)] pb-[var(--shell-bottom-inset,8px)] pt-[var(--shell-top-inset,8px)]">
      <SessionPanelFrame raised>{props.children}</SessionPanelFrame>
    </div>
  )
}

function TargetSessionPage() {
  return (
    // These providers select their scoped state reactively and retain bounded caches,
    // so keep their owners alive while navigating between workspaces on this server.
    <FileProvider>
      <ComposerPersistenceProvider>
        <CommentsProvider>
          <SessionPage />
        </CommentsProvider>
      </ComposerPersistenceProvider>
    </FileProvider>
  )
}

function SessionPage() {
  const session = useSessionModel()

  return <SessionScreenView session={session} />
}

function MarkSessionViewed(props: { sessionID: () => string | undefined }) {
  const notification = useNotification()
  const [focus, setFocus] = createStore({ window: document.hasFocus() })
  const update = () => setFocus("window", document.hasFocus())
  makeEventListener(window, "focus", update)
  makeEventListener(window, "blur", update)
  makeEventListener(document, "visibilitychange", update)

  // Viewed state is shared by every client, so only a focused window reports what its user has seen.
  // markViewed reads the session's idle watermark, so a turn finishing while it stays open re-runs this.
  createEffect(() => {
    const sessionID = props.sessionID()

    if (!sessionID || !focus.window) return
    notification.session.markViewed(sessionID)
  })

  return null
}

import { createMemo, type Accessor } from "solid-js"
import { createStore } from "solid-js/store"
import { createResizeObserver } from "@solid-primitives/resize-observer"
import { useLayout } from "@/shell/state/layout"
import { useSettings } from "@/settings/model"
import { createSizing } from "./helpers"
import type { SessionModel } from "./model"
import { clampSessionPanelWidth, sessionPanelWidthMax } from "./session-panel-width"

/** wide asks for the wider session minimum; sidebar is whether any extension fills the side panel sidebar. */
export function createSessionScreenLayout(
  session: SessionModel,
  input: { wide: Accessor<boolean>; sidebar: Accessor<boolean> },
) {
  const layout = useLayout()
  const settings = useSettings()
  const size = createSizing()
  const view = session.layout.view
  const tabsOpen = createMemo(() => session.isDesktop() && view().side.opened() && !!session.identity.params.id)
  const dockOpen = createMemo(() => view().dock.opened())
  const dockSide = createMemo(() => session.isDesktop() && settings.general.terminalPlacement() === "side")
  const dockBottom = createMemo(() => session.isDesktop() && settings.general.terminalPlacement() === "bottom")
  const dockSideOpen = createMemo(() => dockOpen() && dockSide())

  const fileTreeOpen = createMemo(
    () => session.isDesktop() && input.sidebar() && settings.visibility.fileTree() && layout.fileTree.opened(),
  )

  const resizable = createMemo(() => tabsOpen() || dockSideOpen())
  const besideOpen = createMemo(() => resizable() || fileTreeOpen())
  const [rowSize, setRowSize] = createStore<{ width?: number; height?: number }>({})
  let row: HTMLDivElement | undefined
  createResizeObserver(
    () => row,
    ({ width, height }) => setRowSize({ width, height }),
  )

  const available = createMemo<number | undefined>(() => {
    const width = rowSize.width

    if (width === undefined) return undefined

    return width - 8
  })

  const splitSide = createMemo(() => tabsOpen() && input.wide())

  const resizedWidth = createMemo(() =>
    clampSessionPanelWidth({
      width: view().session.width(),
      available: available(),
      split: splitSide(),
    }),
  )

  const panelWidth = createMemo(() => {
    if (!besideOpen()) return "100%"

    if (resizable()) return `${resizedWidth()}px`

    return `calc(100% - ${layout.fileTree.width()}px)`
  })

  const panelMax = createMemo(() => {
    const width = available()

    if (width === undefined) return 1000

    return sessionPanelWidthMax({ available: width, split: splitSide() })
  })

  const panelLayout = createMemo(() => ({
    visible: tabsOpen() || dockSideOpen() || fileTreeOpen(),
    stacked: tabsOpen() && dockSideOpen(),
  }))

  const sideRegionOpen = createMemo(() => tabsOpen() || fileTreeOpen())

  const dockRegion = createMemo(() =>
    Math.min(view().dock.height(), typeof window === "undefined" ? 600 : window.innerHeight * 0.6),
  )

  const dockRegionHeight = createMemo(() => `${dockRegion()}px`)
  const sideHeight = createMemo(() => rowSize.height)
  const fullSideHeight = createMemo(() => (sideHeight() === undefined ? "100%" : `${sideHeight()}px`))

  const stackedRegionHeight = createMemo(() => {
    const height = sideHeight()

    if (height === undefined) return `calc(100% - ${dockRegionHeight()} - 8px)`

    return `${Math.max(0, height - dockRegion() - 8)}px`
  })

  const sideContentWidth = createMemo<string>((previous) => {
    const width = available()

    if (resizable() && width !== undefined) return `${Math.max(0, width - resizedWidth())}px`

    if (fileTreeOpen()) return `${layout.fileTree.width()}px`

    return previous
  }, "100%")

  return {
    centered: createMemo(() => session.isDesktop()),
    files: { open: fileTreeOpen },
    panel: {
      max: panelMax,
      ref: (element: HTMLDivElement) => {
        row = element
      },
      resizable,
      resizedWidth,
      width: panelWidth,
    },
    side: {
      contentWidth: sideContentWidth,
      gap: { height: createMemo(() => (panelLayout().stacked ? "8px" : "0px")) },
      layout: panelLayout,
      region: {
        height: createMemo(() => {
          if (!sideRegionOpen()) return "0px"

          if (dockSideOpen()) return stackedRegionHeight()

          return fullSideHeight()
        }),
        open: sideRegionOpen,
      },
      tabs: { open: tabsOpen },
      dock: {
        contentHeight: createMemo(() => (sideRegionOpen() ? dockRegionHeight() : fullSideHeight())),
        height: createMemo(() => {
          if (!dockSideOpen()) return "0px"

          if (sideRegionOpen()) return dockRegionHeight()

          return fullSideHeight()
        }),
      },
    },
    size,
    dock: {
      bottom: dockBottom,
      open: dockOpen,
      side: dockSide,
    },
  }
}

export type SessionScreenLayout = ReturnType<typeof createSessionScreenLayout>

