export function SessionAncestorTrail(props: {
  sessionID: string
  parentID: string
  parentTitle?: string
  trailing: boolean
}) {
  const server = useServer()
  const language = useLanguage()
  const open = useOpenSessionRoute()

  const ancestors = createMemo(() => {
    const path: { id: string; title: string; direct: boolean }[] = []
    const seen = new Set([props.sessionID])
    let id: string | undefined = props.parentID

    while (id && !seen.has(id)) {
      seen.add(id)
      const info = server.ctx.data.session.get(id)
      path.unshift({
        id,
        title:
          sessionTitle(info?.title ?? (id === props.parentID ? props.parentTitle : undefined)) ??
          language.t("session.tab.session"),
        direct: id === props.parentID,
      })
      id = info?.parentID
    }

    return path
  })

  return (
    <div class="flex min-w-0 max-w-full items-center">
      <div
        data-slot="session-title-ancestors"
        class="flex min-w-0 items-center overflow-x-auto whitespace-nowrap [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
      >
        <For each={ancestors()}>
          {(ancestor, index) => (
            <>
              <button
                type="button"
                data-slot={ancestor.direct ? "session-title-parent" : "session-title-ancestor"}
                data-session-id={ancestor.id}
                title={ancestor.title}
                class="max-w-[min(200px,40vw)] shrink-0 truncate text-[13px] font-[530] leading-4 tracking-[-0.04px] text-v2-text-text-faint transition-colors hover:text-v2-text-text-muted"
                classList={{ "ps-1": index() === 0, "ps-2": index() > 0 }}
                onClick={() => open(props.sessionID, ancestor.id)}
              >
                <bdi dir="auto">{ancestor.title}</bdi>
              </button>
              <Show when={index() < ancestors().length - 1}>
                <span
                  data-slot="session-title-separator"
                  class="-translate-y-[0.5px] shrink-0 ps-2 pe-1 text-[11px] font-medium text-v2-text-text-faint"
                  aria-hidden="true"
                >
                  /
                </span>
              </Show>
            </>
          )}
        </For>
      </div>
      <Show when={props.trailing}>
        <span
          data-slot="session-title-separator"
          class="-translate-y-[0.5px] shrink-0 ps-2 pe-1 text-[11px] font-medium text-v2-text-text-faint"
          aria-hidden="true"
        >
          /
        </span>
      </Show>
    </div>
  )
}

// Opens a related session in the tab showing `from`, and records its parent so the tab's route stays consistent.
// `reveal` names a tool call or shell the opened timeline scrolls to and expands.
export function useOpenSessionRoute() {
  const server = useServer()
  const tabs = useTabs()
  const navigate = useNavigate()

  return (from: string, id: string, reveal?: string) => {
    const tab = tabs.store.find(
      (item) =>
        item.type === "session" &&
        item.server === server.key &&
        (item.sessionId === from || item.routeSessionId === from),
    )

    if (tab?.type === "session") tabs.rememberSessionRoute(tab, id, server.ctx.data.session.get(id)?.parentID)
    navigate(sessionHref(server.key, id), reveal ? { state: { reveal } } : undefined)
  }
}

export function SessionIdentityHeader(props: ParentProps<{ sessionID: string; session?: SessionInfo }>) {
  const server = useServer()
  const tabs = useTabs()
  const language = useLanguage()
  const pending = createMemo(() => tabs.pendingSession(server.key, props.sessionID))

  const tab = createMemo(() =>
    tabs.store.find(
      (item) =>
        item.type === "session" &&
        item.server === server.key &&
        (item.sessionId === props.sessionID || item.routeSessionId === props.sessionID),
    ),
  )

  const info = createMemo(() => {
    const current = tab()

    return current ? tabs.info[tabKey(current)] : undefined
  })

  const parentID = createMemo(() => {
    if (props.session?.parentID) return props.session.parentID
    const current = tab()

    if (current?.type !== "session" || current.routeSessionId !== props.sessionID) return

    return current.routeParentId ?? current.sessionId
  })

  const parent = createMemo(() => {
    const id = parentID()

    return id ? server.ctx.data.session.get(id) : undefined
  })

  const parentTitle = createMemo(() => {
    const id = parentID()
    const current = tab()

    return sessionTitle(
      parent()?.title ?? (current?.type === "session" && current.sessionId === id ? info()?.title : undefined),
    )
  })

  const directory = createMemo(
    () => props.session?.location.directory ?? pending()?.draft.directory ?? info()?.directory,
  )

  const title = createMemo(() =>
    pending()
      ? language.t("session.tab.session")
      : sessionTitle(props.session?.title ?? (parentID() ? undefined : info()?.title)),
  )

  const project = createMemo(() => {
    if (props.session) return server.ctx.projects.forSession(props.session)
    const projects = server.ctx.projects.list()
    const value = directory()

    if (!value) return undefined
    const key = pathKey(value)

    return (
      projects.find(
        (item) => pathKey(item.worktree) === key || item.sandboxes?.some((sandbox) => pathKey(sandbox) === key),
      ) ?? server.ctx.sync.data.project.find((item) => isProjectDirectory(item, value))
    )
  })

  const workspaceSession = createMemo(() => !!pending() || isWorkspaceDirectory(project(), directory() ?? ""))

  return (
    <Show when={title() || parentTitle()}>
      <SessionTitleHeader>
        <div class="flex h-12 w-full items-center justify-between gap-2">
          <div class="flex min-w-0 flex-1 items-center gap-1">
            <div class="flex min-w-0 w-full flex-1 items-center gap-0.5">
              <SessionProjectMenu project={project()} directory={directory()} workspace={workspaceSession()} />
              <Show when={parentID()}>
                {(id) => (
                  <SessionAncestorTrail
                    sessionID={props.sessionID}
                    parentID={id()}
                    parentTitle={parentTitle()}
                    trailing={!!title()}
                  />
                )}
              </Show>
              <Show when={parentID() && props.children}>{props.children}</Show>
              <Show when={!parentID() || !props.children}>
                <SessionWorkingIndicator sessionID={props.sessionID} />
              </Show>
              <Show when={(!parentID() || !props.children) && title()}>
                {(value) => (
                  <h1
                    data-slot={parentID() ? "session-title-child" : undefined}
                    dir="auto"
                    class="w-fit truncate rounded-[6px] px-1 py-1 text-[13px] font-[530] leading-4 tracking-[-0.04px] text-v2-text-text-base"
                    classList={{ "max-w-[45%] shrink-0": !!parentID() }}
                  >
                    {value()}
                  </h1>
                )}
              </Show>
              <Show when={!parentID()}>{props.children}</Show>
            </div>
          </div>
        </div>
      </SessionTitleHeader>
    </Show>
  )
}

import { useParams } from "@solidjs/router"
import { createMemo } from "solid-js"
import { useLayout } from "@/shell/state/layout"
import { SessionRouteKey, SessionStateKey } from "@/runtime/server/scope"
import { useWorkspaceLocation } from "@/workspaces/location"
import { useServerSDK } from "@/runtime/server/client"
import { base64Encode } from "@opencode/util/encode"
import { ServerConnection } from "@/runtime/server/registry"
import { findSessionTab, tabKey, useTabs } from "@/shell/tabs/tabs"

export const useSessionKey = () => {
  const params = useParams()
  const sdk = useWorkspaceLocation()
  const serverSDK = useServerSDK()
  const scope = createMemo(() => serverSDK.scope)
  const directory = createMemo(() => base64Encode(sdk().directory))
  const workspaceKey = createMemo(() => SessionStateKey.from(scope(), SessionRouteKey.fromRoute(directory())))
  const sessionKey = createMemo(() => SessionStateKey.from(scope(), SessionRouteKey.fromRoute(directory(), params.id)))

  return { params, sessionKey, workspaceKey }
}

export const useSessionLayout = () => {
  const layout = useLayout()
  const tabs = useTabs()
  const { params, sessionKey, workspaceKey } = useSessionKey()
  const serverSDK = useServerSDK()

  const currentTab = createMemo(() => {
    if (!params.id) return

    return findSessionTab(tabs.store, ServerConnection.key(serverSDK.server), params.id)
  })

  const regions = {
    dockOpened: () => tabs.region(currentTab(), "dock"),
    setDockOpened: (opened: boolean) => tabs.setRegion(currentTab(), "dock", opened),
    dockHeight: () => tabs.regionSize(currentTab(), "dockHeight"),
    setDockHeight: (height: number) => tabs.setRegionSize(currentTab(), "dockHeight", height),
    sideOpened: () => tabs.region(currentTab(), "side"),
    setSideOpened: (opened: boolean) => tabs.setRegion(currentTab(), "side", opened),
    sessionWidth: () => tabs.regionSize(currentTab(), "sessionWidth"),
    setSessionWidth: (width: number) => tabs.setRegionSize(currentTab(), "sessionWidth", width),
  }

  return {
    params,
    sessionKey,
    workspaceKey,
    tabKey: createMemo(() => {
      const tab = currentTab()

      return tab && tabKey(tab)
    }),
    tabs: createMemo(() => layout.tabs(sessionKey)),
    view: createMemo(() => layout.view(sessionKey, regions)),
  }
}

import { expect, test } from "bun:test"
import { syncPromptModel } from "./session-model-helpers"

const sonnet = { providerID: "anthropic", modelID: "claude-sonnet-4", variant: "high" }

test.each([
  ["stores the effective session model in prompt state", sonnet, undefined, [sonnet]],
  ["does not rewrite an unchanged prompt model", sonnet, sonnet, []],
  [
    "replaces the submission mirror without changing the effective selection",
    { providerID: "openai", modelID: "gpt", variant: undefined },
    { providerID: "anthropic", modelID: "claude", variant: "high" },
    [{ providerID: "openai", modelID: "gpt", variant: undefined }],
  ],
])("%s", (_name, effective, mirror, writes) => {
  const calls: unknown[] = []

  syncPromptModel(
    {
      model: {
        current: () => ({ id: effective.modelID, provider: { id: effective.providerID } }),
        variant: { current: () => effective.variant },
      },
    },
    { model: { current: () => mirror, set: (model) => calls.push(model) } },
  )

  expect(calls).toEqual(writes)
})

type ModelSelection = {
  model: {
    current(): { id: string; provider: { id: string } } | undefined
    variant: {
      current(): string | undefined
    }
  }
}

type PromptState = {
  model: {
    current(): { providerID: string; modelID: string; variant?: string | null } | undefined
    set(model: { providerID: string; modelID: string; variant?: string | null }): void
  }
}

export const syncPromptModel = (local: ModelSelection, prompt: PromptState) => {
  const model = local.model.current()

  if (!model) return

  const next = {
    providerID: model.provider.id,
    modelID: model.id,
    variant: local.model.variant.current(),
  }

  const current = prompt.model.current()

  if (current?.providerID === next.providerID && current.modelID === next.modelID && current.variant === next.variant)
    return
  prompt.model.set(next)
}

import { expect, test } from "bun:test"
import { createRoot, createSignal } from "solid-js"
import { createSessionOwnership } from "./session-ownership"

test("rejects work captured by a previous session", () => {
  createRoot((dispose) => {
    const [key, setKey] = createSignal("session-a")
    const ownership = createSessionOwnership(key)
    const captured = ownership.capture()
    let ran = false

    setKey("session-b")

    expect(captured.current()).toBe(false)
    expect(captured.run(() => (ran = true))).toBeUndefined()
    expect(ran).toBe(false)
    dispose()
  })
})

import { createComputed, onCleanup } from "solid-js"

export function createSessionOwnership(sessionKey: () => string) {
  let current = sessionKey()
  let generation = 0

  const transition = () => {
    const next = sessionKey()

    if (next === current) return
    current = next
    generation++
  }

  createComputed(transition)
  onCleanup(() => generation++)

  return {
    key: () => {
      transition()

      return `${generation}:${current}`
    },
    capture() {
      transition()
      const captured = generation

      return {
        key: `${captured}:${current}`,
        current: () => {
          transition()

          return generation === captured
        },
        run<T>(action: () => T) {
          transition()

          if (generation !== captured) return

          return action()
        },
      }
    },
  }
}

// The review pane has no width of its own: it takes whatever the chat panel
// leaves behind. Instead of capping the chat panel at a fraction of the window
// (which forces the review pane to grow with the monitor), reserve a fixed
// minimum for the review pane and let the chat panel take everything else.
export const SESSION_PANEL_WIDTH_MIN = 450

const REVIEW_PANE_WIDTH_MIN = 480

const REVIEW_PANE_WIDTH_MIN_SPLIT = 800

export function sessionPanelWidthMax(input: { available: number; split: boolean }) {
  const pane = input.split ? REVIEW_PANE_WIDTH_MIN_SPLIT : REVIEW_PANE_WIDTH_MIN

  return Math.max(SESSION_PANEL_WIDTH_MIN, input.available - pane)
}

// `available` is undefined until the layout row is first measured; render the
// stored width untouched until then to avoid a first-frame snap.
export function clampSessionPanelWidth(input: { width: number; available: number | undefined; split: boolean }) {
  if (input.available === undefined) return input.width

  return Math.min(input.width, sessionPanelWidthMax({ available: input.available, split: input.split }))
}

import { createMemo, createRenderEffect, createSignal, on, onCleanup } from "solid-js"
import { sessionNotFoundError } from "@/runtime/server/errors"

type SessionStore<T> = {
  get: (id: string) => T | undefined
  sync: (id: string, options?: { children?: boolean }) => Promise<unknown>
  message: {
    sync: (id: string) => Promise<unknown>
  }
  pending: {
    sync: (id: string) => Promise<unknown>
  }
}

type Resolution<T> = { id: string; store: SessionStore<T> } & (
  | { state: "pending" }
  | { state: "settled" }
  | { state: "failed"; failure: unknown }
)

// Reactive target session for the session route, read from the data store.
// All session tabs on a server share one route instance, so the target session ID
// changes in place; the effect is only a trigger that starts resolution for the
// current target, and each run cancels the previous one through onCleanup so a
// late result from an abandoned target is dropped. Resolution is imperative rather
// than a resource on purpose: a resource created here would be created inside the
// router's navigation transition, and suspending that transition deadlocks the URL
// commit and double-mounts the session header portals from the transition's shadow
// render.
//
// The returned accessor is a pure derivation. The sync cache is authoritative, and
// status only applies while it matches the current target (store + session ID): on
// navigation or store replacement the memo re-evaluates before the trigger runs,
// so trusting a previous target's settlement would fabricate a not-found for a
// session that simply has not resolved yet. Resolve failures rethrow on read so
// the enclosing SessionRouteErrorBoundary renders the scoped session error.
export function createSessionResolution<T>(
  sessionID: () => string | undefined,
  sessions: () => SessionStore<T>,
  options?: { children?: boolean; connected?: () => boolean },
) {
  const cached = createMemo(() => {
    const id = sessionID()

    if (!id) return

    return sessions().get(id)
  })

  const [status, setStatus] = createSignal<Resolution<T>>()

  // Start independent reads before constructing the selected view, including
  // when its metadata is cached but its transcript has never been loaded.
  createRenderEffect(
    on([sessionID, sessions, () => options?.connected?.() ?? true] as const, ([id, store, connected]) => {
      if (!id || !connected) return
      let stale = false
      onCleanup(() => {
        stale = true
      })
      // The timeline owns message errors; metadata resolution stays independent. Queued inputs
      // ride along so a reconnect refreshes them with the transcript instead of leaving the
      // pre-disconnect queue on screen.
      void store.message.sync(id).catch(() => undefined)
      void store.pending.sync(id).catch(() => undefined)

      if (cached() && !options?.children && !options?.connected) {
        setStatus({ id, store, state: "settled" })

        return
      }

      setStatus({ id, store, state: "pending" })
      store
        .sync(id, options)
        .then(() => {
          if (!stale) setStatus({ id, store, state: "settled" })
        })
        .catch((failure) => {
          if (!stale) setStatus({ id, store, state: "failed", failure })
        })
    }),
  )

  return createMemo(() => {
    const id = sessionID()

    if (!id) return
    const value = cached()

    if (value) return value
    const state = status()

    if (!state || state.id !== id || state.store !== sessions()) return undefined

    if (state.state === "failed") throw state.failure

    // A session missing after settlement was deleted, possibly by another client.
    // Match the resolve error so the boundary shows the
    // session not found fallback.
    if (state.state === "settled") throw sessionNotFoundError(id)

    return undefined
  })
}

