import {
  createComputed,
  createMemo,
  createRoot,
  getOwner,
  on,
  onCleanup,
  untrack,
  type Accessor,
  type JSX,
} from "solid-js"
import { createScopedCache } from "@/runtime/server/scoped-cache"
import type { TimelineSessionSource } from "./controller"

export function createTimelineCache(
  session: TimelineSessionSource & { identity: { workspaceKey: Accessor<string> } },
  render: (source: TimelineSessionSource, active: Accessor<boolean>) => JSX.Element,
  visible: Accessor<boolean>,
) {
  const owner = getOwner()
  let workspace = untrack(session.identity.workspaceKey)

  const cache = createScopedCache(
    (key) =>
      createRoot((dispose) => {
        const id = untrack(session.identity.sessionID)
        const sessionKey = untrack(session.identity.sessionKey)
        const active = createMemo(() => visible() && session.identity.sessionKey() === key)

        // A detached view retains its own inputs until it is selected again.
        const select = <T>(read: Accessor<T>) =>
          createMemo<T>((previous) => (active() ? read() : previous), untrack(read))

        return {
          value: render(
            {
              identity: {
                params: session.identity.params,
                sessionID: () => id,
                sessionKey: () => sessionKey,
              },
              data: {
                info: select(session.data.info),
                parent: select(session.data.parent),
                parentID: select(session.data.parentID),
                status: select(session.data.status),
              },
              history: { messages: select(session.history.messages) },
            },
            active,
          ),
          dispose,
        }
      }, owner),
    { maxEntries: 16, dispose: (entry) => entry.dispose() },
  )

  onCleanup(cache.clear)

  const syncWorkspace = (key: string) => {
    if (workspace === key) return
    workspace = key
    cache.clear()
  }

  // Providers follow the selected Location even while its history is loading.
  // Dispose detached views before their effects can read the new Location.
  createComputed(on(session.identity.workspaceKey, syncWorkspace, { defer: true }))

  return () => {
    // A tab's render can run before the workspace watcher in the same batch.
    // Clear the old workspace here, and let that later watcher keep this view.
    syncWorkspace(session.identity.workspaceKey())

    return cache.get(session.identity.sessionKey()).value
  }
}

import { describe, expect, test } from "bun:test"
import type { SessionInboxInfo, SessionMessageInfo } from "@opencode/client/promise"
import { createRoot } from "solid-js"
import { applyTimelineMessageHandoff, visibleTimelineMessages } from "./controller-projection"
import { createTimelineProjection } from "./projection"
import { timelinePresets } from "@opencode/session-ui/timeline/detail"

const messages = [
  { id: "msg_1", type: "user", text: "first", time: { created: 1 } },
  {
    id: "msg_2",
    type: "assistant",
    agent: "build",
    model: { id: "model", providerID: "provider" },
    content: [],
    time: { created: 2 },
  },
  { id: "msg_3", type: "user", text: "queued", time: { created: 3 } },
  { id: "msg_4", type: "user", text: "reverted", time: { created: 4 } },
] satisfies SessionMessageInfo[]

describe("visibleTimelineMessages", () => {
  const steer = {
    id: "msg_3",
    sessionID: "ses_1",
    time: { created: 3 },
    type: "user",
    delivery: "steer",
    payload: { text: "queued" },
  } satisfies SessionInboxInfo

  const work = {
    id: "msg_5",
    type: "assistant",
    agent: "build",
    model: { id: "model", providerID: "provider" },
    content: [
      {
        type: "tool",
        id: "tool_read",
        name: "read",
        state: {
          status: "completed",
          input: { filePath: "src/example.ts" },
          content: [{ type: "text", text: "export const example = true" }],
          metadata: {},
        },
        time: { created: 5, completed: 6 },
      },
    ],
    time: { created: 5, completed: 6 },
  } satisfies SessionMessageInfo

  test("keeps work above an undelivered steer without adding a thinking row", () => {
    const source = [...messages.slice(0, 3), work]
    const visible = visibleTimelineMessages(source, [steer])
    expect(visible.map((message) => message.id)).toEqual(["msg_1", "msg_2", "msg_5", "msg_3"])
    expect(source.map((message) => message.id)).toEqual(["msg_1", "msg_2", "msg_3", "msg_5"])
    expect(visible[2]).toBe(work)

    createRoot((dispose) => {
      const projection = createTimelineProjection({
        sessionMessages: () => visible,
        status: () => ({ type: "busy" }),
        reasoningMode: () => "compact",
        shellToolDefaultOpen: () => false,
        editToolDefaultOpen: () => false,
        timelineDetail: () => timelinePresets[2].value,
        pendingInputIDs: () => new Set([steer.id]),
      })

      expect(projection.activeMessageID()).toBe("msg_1")
      expect(projection.rows().map((row) => [row._tag, row.userMessageID])).toEqual([
        ["UserMessage", "msg_1"],
        ["AssistantPart", "msg_1"],
        ["Activity", "msg_1"],
        ["TurnGap", "msg_3"],
        ["UserMessage", "msg_3"],
      ])
      expect(
        projection
          .assistantMessagesByParent()
          .get("msg_1")
          ?.map((message) => message.id),
      ).toEqual(["msg_2", "msg_5"])
      expect(projection.assistantMessagesByParent().has(steer.id)).toBe(false)
      expect([...projection.messageRowIndex()]).toEqual([
        ["msg_1", 0],
        ["msg_3", 3],
      ])
      expect([...projection.messageLastRowIndex()]).toEqual([
        ["msg_1", 2],
        ["msg_3", 4],
      ])
      expect([...projection.lastAssistantGroupKey()]).toEqual([["msg_1", "context:msg_5:tool_read"]])
      expect(projection.rowByKey().get("user-message:msg_1")).toBe(projection.rows()[0])
      expect(projection.rowByKey().size).toBe(projection.rows().length)
      dispose()
    })
  })

  test("moves a queued input after existing work when changed to steer", () => {
    const source = [...messages.slice(0, 3), work]
    expect(visibleTimelineMessages(source, [{ ...steer, delivery: "queue" }]).map((message) => message.id)).toEqual([
      "msg_1",
      "msg_2",
      "msg_5",
    ])
    expect(visibleTimelineMessages(source, [steer]).map((message) => message.id)).toEqual([
      "msg_1",
      "msg_2",
      "msg_5",
      "msg_3",
    ])
    const delivered = [messages[0], messages[1], work, messages[2]]
    expect(visibleTimelineMessages(delivered, [])).toBe(delivered)
  })

  test("preserves pending input order and excludes reverted steers", () => {
    const source = [...messages, work]
    const pending = [steer, { ...steer, id: "msg_4" }]
    expect(visibleTimelineMessages(source, pending).map((message) => message.id)).toEqual([
      "msg_1",
      "msg_2",
      "msg_5",
      "msg_3",
      "msg_4",
    ])

    // A notice admitted after the steers, before the next step, sinks with them in admission order. The
    // server delivers steers in that order and the store moves each delivered input to the end, so the
    // rendered order does not change at delivery.
    const notice = {
      id: "msg_4a",
      sessionID: "ses_1",
      time: { created: 4 },
      type: "synthetic",
      delivery: "steer",
      payload: { text: "", description: "Task finished" },
    } satisfies SessionInboxInfo

    const noticeMessage = {
      id: notice.id,
      type: "synthetic",
      ...notice.payload,
      time: notice.time,
    } satisfies SessionMessageInfo

    const pendingOrder = visibleTimelineMessages([...messages, noticeMessage, work], [...pending, notice])

    // The order the server delivers in: active work, then steers and notices by admission.
    expect(pendingOrder.map((message) => message.id)).toEqual(["msg_1", "msg_2", "msg_5", "msg_3", "msg_4", "msg_4a"])
    expect(visibleTimelineMessages(source, pending, "msg_4").map((message) => message.id)).toEqual([
      "msg_1",
      "msg_2",
      "msg_3",
    ])
  })

  test("hides queued inputs until delivery", () => {
    const pending = [
      {
        id: "msg_3",
        sessionID: "ses_1",
        time: { created: 3 },
        type: "user",
        delivery: "queue",
        payload: { text: "queued" },
      },
    ] satisfies SessionInboxInfo[]

    expect(visibleTimelineMessages(messages, pending).map((message) => message.id)).toEqual(["msg_1", "msg_2", "msg_4"])
  })

  test("hides the staged revert boundary and later messages", () => {
    expect(visibleTimelineMessages(messages, [], "msg_4").map((message) => message.id)).toEqual([
      "msg_1",
      "msg_2",
      "msg_3",
    ])
    expect(visibleTimelineMessages(messages, [], "msg_0")).toEqual([])
  })

  test("keeps a pre-promotion failed idle marker after the pending input that triggered it", () => {
    const failed = [
      { id: "msg_3", type: "user", text: "queued", time: { created: 3 } },
      {
        id: "msg_idle",
        type: "idle",
        outcome: "failed",
        error: { type: "unknown", message: 'Agent not found: "build"' },
        time: { created: 4 },
      },
    ] satisfies SessionMessageInfo[]

    expect(visibleTimelineMessages(failed, [steer]).map((message) => message.id)).toEqual(["msg_3", "msg_idle"])
  })
})

describe("applyTimelineMessageHandoff", () => {
  const message = {
    id: "msg_image",
    type: "user",
    text: "",
    files: [
      {
        data: "",
        mime: "image/png",
        source: { type: "uri", uri: "blob:image" },
        name: "image.png",
      },
    ],
    time: { created: 1 },
  } satisfies SessionMessageInfo

  const selection = { agent: "plan", model: { id: "next", providerID: "provider", variant: "high" } }
  const handoff = { message, selection }
  const switched = { agent: "plan", model: selection.model }

  test("shows a promoted image-only prompt before client admission", () => {
    expect(applyTimelineMessageHandoff([], handoff, switched)).toEqual([message])
  })

  test("adds attachments to the client's optimistic row", () => {
    const optimistic = { id: message.id, type: "user", text: "", time: { created: 2 } } satisfies SessionMessageInfo
    expect(applyTimelineMessageHandoff([optimistic], handoff, switched)).toEqual([
      { ...optimistic, files: message.files },
    ])
  })

  test("keeps the durable attachment payload", () => {
    const durable = {
      ...message,
      files: [{ data: "YQ==", mime: "image/png", source: { type: "inline" } }],
    } satisfies SessionMessageInfo

    const source = [durable]

    expect(applyTimelineMessageHandoff(source, handoff, switched)).toBe(source)
  })

  const agent = {
    id: "msg_image_agent",
    type: "agent-switched",
    agent: "plan",
    previous: "build",
    time: { created: 1 },
  } satisfies SessionMessageInfo

  const model = {
    id: "msg_image_model",
    type: "model-switched",
    model: selection.model,
    previous: { id: "old", providerID: "provider" },
    time: { created: 1 },
  } satisfies SessionMessageInfo

  // The session takes each switch from its echo, which also lands the durable notice.
  test.each([
    {
      name: "both switches pending",
      session: { agent: "build", model: { id: "old", providerID: "provider" } },
      notices: [agent, model],
    },
    {
      name: "only a variant change",
      session: { agent: "plan", model: { ...selection.model, variant: undefined } },
      notices: [{ ...model, previous: { ...selection.model, variant: undefined } }],
    },
    {
      name: "the agent echoed",
      session: { agent: "plan", model: { id: "old", providerID: "provider" } },
      notices: [model],
    },
    { name: "both echoed", session: switched, notices: [] },
  ])("projects the prompt's switches ahead of it: $name", (row) => {
    expect(applyTimelineMessageHandoff(messages.slice(0, 2), handoff, row.session)).toEqual([
      ...messages.slice(0, 2),
      ...row.notices,
      message,
    ])
  })

  test("projects a return to the default variant with its previous selection", () => {
    const toDefault = { ...handoff, selection: { ...selection, model: { ...selection.model, variant: undefined } } }
    const previous = { ...selection.model, variant: "xhigh" }

    expect(applyTimelineMessageHandoff(messages.slice(0, 2), toDefault, { agent: "plan", model: previous })).toEqual([
      ...messages.slice(0, 2),
      { ...model, model: toDefault.selection.model, previous },
      message,
    ])
  })

  test("projects pending switches ahead of the client's optimistic row", () => {
    const optimistic = { ...message, files: [] } satisfies SessionMessageInfo
    const session = { agent: "build", model: selection.model }

    expect(applyTimelineMessageHandoff([messages[0], optimistic], handoff, session)).toEqual([
      messages[0],
      agent,
      message,
    ])
  })
})

import type { ModelRef, SessionInboxInfo, SessionMessageInfo } from "@opencode/client/promise"
import type { SessionMessageHandoff } from "@/session/handoff"

// Projects a submitted prompt, and the agent and model switches it makes, until the server's echoes replace them.
// The session's live selection takes each switch's echo, so a switch projects only while the session still differs.
export function applyTimelineMessageHandoff(
  messages: SessionMessageInfo[],
  handoff: SessionMessageHandoff | undefined,
  session: { agent?: string; model?: ModelRef } | undefined,
) {
  if (!handoff) return messages
  const notices = handoffNotices(handoff, session)
  const index = messages.findIndex((message) => message.id === handoff.message.id)

  if (index < 0) return [...messages, ...notices, handoff.message]
  const message = messages[index]
  const filled = message.type === "user" && !message.files?.length

  if (!filled && notices.length === 0) return messages

  return [
    ...messages.slice(0, index),
    ...notices,
    filled ? { ...message, files: handoff.message.files } : message,
    ...messages.slice(index + 1),
  ]
}

function handoffNotices(
  handoff: SessionMessageHandoff,
  session: { agent?: string; model?: ModelRef } | undefined,
): SessionMessageInfo[] {
  const time = { created: handoff.message.time.created }
  const selection = handoff.selection

  return [
    ...(session?.agent && session.agent !== selection.agent
      ? [
          {
            id: `${handoff.message.id}_agent`,
            type: "agent-switched" as const,
            agent: selection.agent,
            previous: session.agent,
            time,
          },
        ]
      : []),
    ...(session?.model &&
    (session.model.providerID !== selection.model.providerID ||
      session.model.id !== selection.model.id ||
      (session.model.variant ?? "default") !== (selection.model.variant ?? "default"))
      ? [
          {
            id: `${handoff.message.id}_model`,
            type: "model-switched" as const,
            model: selection.model,
            previous: session.model,
            time,
          },
        ]
      : []),
  ]
}

export function visibleTimelineMessages(
  messages: SessionMessageInfo[],
  pending: SessionInboxInfo[],
  revertMessageID?: string,
) {
  const queued = new Set(
    pending.flatMap((item) => (item.type === "user" && item.delivery === "queue" ? [item.id] : [])),
  )

  const inputs = new Set(
    pending.flatMap((item) =>
      (item.type === "user" && item.delivery === "steer") || item.type === "synthetic" ? [item.id] : [],
    ),
  )

  if (queued.size === 0 && inputs.size === 0 && !revertMessageID) return messages

  const visible = messages.filter(
    (message) => !queued.has(message.id) && (!revertMessageID || message.id < revertMessageID),
  )

  if (inputs.size === 0) return visible

  // Undelivered inputs do not own assistant work, so they stay below the active work like the TUI.
  // They keep admission order: the server delivers steers in that order, so delivery moves nothing.
  // A pre-promotion failure ends in a failed idle marker with no assistant work, so keep that marker
  // after the input that triggered it.
  const tail = visible.at(-1)

  if (tail?.type === "idle" && tail.outcome === "failed") {
    const start = visible.slice(0, -1).findLastIndex((message) => message.type === "idle") + 1

    if (
      visible.slice(start, -1).some((message) => inputs.has(message.id)) &&
      !visible.slice(start, -1).some((message) => message.type === "assistant")
    ) {
      const rest = visible.slice(0, -1)

      return [
        ...rest.filter((message) => !inputs.has(message.id)),
        ...rest.filter((message) => inputs.has(message.id)),
        tail,
      ]
    }
  }

  return [
    ...visible.filter((message) => !inputs.has(message.id)),
    ...visible.filter((message) => inputs.has(message.id)),
  ]
}

export function timelineChildTitle(input: {
  parentID?: string
  taskDescription?: string
  title?: string
  fallback: string
}) {
  if (!input.parentID) return input.title ?? ""

  if (input.taskDescription) return input.taskDescription

  return input.title?.replace(/\s+\(@[^)]+ subagent\)$/, "") || input.fallback
}

import type { SessionMessageInfo } from "@opencode/client/promise"
import { DialogFooter, DialogHeader, DialogTitleGroup, Dialog } from "@opencode/ui/dialog"
import { Button } from "@opencode/ui/button"
import { useNavigate } from "@solidjs/router"
import { createEffect, createMemo, on } from "solid-js"
import { createStore } from "solid-js/store"
import { Option, Predicate, Schema } from "effect"
import { notifySessionTabsRemoved } from "@/shell/titlebar/session-events"
import { useDialog } from "@opencode/ui/context/dialog"
import { useLanguage } from "@/runtime/i18n/language"
import { useSettings } from "@/settings/model"
import { useWorkspaceLocation } from "@/workspaces/location"
import { useTabs } from "@/shell/tabs/tabs"
import type { SessionModel } from "@/session/model"
import { sessionTreeIDs } from "@/session/requests/session-request-tree"
import { useServerSDK } from "@/runtime/server/client"
import { sessionHref } from "@/shell/routes/session"
import { sessionTitle } from "@/session/title"
import { fetchSessionExport, saveSessionExport, sessionExportFilename } from "@/session/commands/export"
import { showToast } from "@/shell/notifications/toast"
import { usePlatform } from "@/runtime/platform/platform"
import { applyTimelineMessageHandoff, timelineChildTitle, visibleTimelineMessages } from "./controller-projection"
import { createTimelineProjection } from "./projection"
import { useServer } from "@/runtime/server/current"
import { getSessionMessageHandoff } from "@/session/handoff"
import type { ReasoningMode } from "@opencode/session-ui/timeline/projection"

const emptyMessages: SessionMessageInfo[] = []

const decodeErrorData = Schema.decodeUnknownOption(Schema.Struct({ data: Schema.Struct({ message: Schema.String }) }))

const taskDescription = (message: SessionMessageInfo, sessionID: string): string | undefined => {
  if (message.type !== "assistant") return

  const tool = message.content.findLast((item) => {
    if (item.type !== "tool" || (item.name !== "task" && item.name !== "subagent")) return false

    const metadata =
      item.state.status === "running" || item.state.status === "completed" ? item.state.metadata : undefined

    return metadata?.sessionId === sessionID || metadata?.sessionID === sessionID
  })

  if (tool?.type !== "tool") return
  const input = Predicate.isString(tool.state.input) ? undefined : tool.state.input
  const value = input?.description

  if (Predicate.isString(value) && value) return value

  return undefined
}

export type TimelineSessionSource = {
  identity: Pick<SessionModel["identity"], "params" | "sessionID" | "sessionKey">
  data: Pick<SessionModel["data"], "info" | "parent" | "parentID" | "status">
  history: Pick<SessionModel["history"], "messages">
}

export function createTimelineController(input: { session: TimelineSessionSource }) {
  const navigate = useNavigate()
  const sdk = useWorkspaceLocation()
  const serverSDK = useServerSDK()
  const server = useServer()
  const data = server.ctx.data
  const settings = useSettings()
  const tabs = useTabs()
  const dialog = useDialog()
  const language = useLanguage()
  const platform = usePlatform()

  const visibleMessages = createMemo(() => {
    const id = input.session.identity.sessionID()

    return visibleTimelineMessages(
      input.session.history.messages(),
      id ? data.session.pending.list(id) : [],
      input.session.data.info()?.revert?.messageID,
    )
  })

  // A handoff projects after visibility: its prompt commits any staged revert, so the boundary does not hide it.
  const projectedMessages = createMemo(() =>
    applyTimelineMessageHandoff(
      visibleMessages(),
      getSessionMessageHandoff(input.session.identity.sessionKey()),
      input.session.data.info(),
    ),
  )

  // Inputs that wait behind the active turn. A starting steer opens the next turn instead, so the turn before it
  // stays finished, as it will once the steer is delivered.
  const pendingInputIDs = createMemo(() => {
    const id = input.session.identity.sessionID()

    if (!id) return new Set<string>()

    return new Set(
      data.session.pending
        .list(id)
        .flatMap((item) =>
          (item.type === "user" &&
            item.delivery === "steer" &&
            data.session.pending.status(id, item.id) !== "starting") ||
          item.type === "synthetic"
            ? [item.id]
            : [],
        ),
    )
  })

  const queuedCompactionIDs = createMemo(() => {
    const id = input.session.identity.sessionID()

    return (id ? data.session.pending.list(id) : []).flatMap((item) => (item.type === "compaction" ? [item.id] : []))
  })

  const titleValue = createMemo(() => input.session.data.info()?.title)
  const titleLabel = createMemo(() => sessionTitle(titleValue()) ?? language.t("session.tab.session"))

  const parentMessages = createMemo(() => {
    const id = input.session.data.parentID()

    return id ? data.session.message.list(id) : emptyMessages
  })

  const parentTitle = createMemo(
    () => sessionTitle(input.session.data.parent()?.title) ?? language.t("session.tab.session"),
  )

  const childTaskDescription = createMemo(() => {
    const id = input.session.identity.sessionID()

    if (!id) return undefined

    return parentMessages()
      .map((message) => taskDescription(message, id))
      .findLast((value): value is string => !!value)
  })

  const childTitle = createMemo(() => {
    return timelineChildTitle({
      parentID: input.session.data.parentID(),
      taskDescription: childTaskDescription(),
      title: titleLabel(),
      fallback: language.t("session.tab.session"),
    })
  })

  const showHeader = createMemo(() => !!input.session.identity.sessionID())

  const timelineDetail = createMemo(() => {
    const detail = settings.general.timelineDetail()

    return {
      shell: { ...detail.shell },
      edit: { ...detail.edit },
      thinking: { ...detail.thinking },
      subagents: { ...detail.subagents },
      notices: { ...detail.notices },
      tools: { ...detail.tools },
    }
  })

  const reasoningMode = (): ReasoningMode =>
    timelineDetail().thinking.placement === "hidden"
      ? "hidden"
      : timelineDetail().thinking.details === "expanded"
        ? "full"
        : "compact"

  const shellToolPartsExpanded = () => timelineDetail().shell.details === "expanded"
  const editToolPartsExpanded = () => timelineDetail().edit.details === "expanded"

  const projection = createTimelineProjection({
    sessionMessages: projectedMessages,
    status: input.session.data.status,
    reasoningMode,
    shellToolDefaultOpen: shellToolPartsExpanded,
    editToolDefaultOpen: editToolPartsExpanded,
    timelineDetail,
    pendingInputIDs,
    queuedCompactionIDs,
    turnDiffs: settings.general.showTurnDiffs,
  })

  const [pending, setPending] = createStore({ rename: false })

  const errorMessage = (cause: unknown) =>
    Option.match(decodeErrorData(cause), {
      onSome: (error) => error.data.message,
      onNone: () => (cause instanceof Error ? cause.message : language.t("common.requestFailed")),
    })

  const rename = async (title: string) => {
    const id = input.session.identity.sessionID()

    if (!id || pending.rename) return false
    const next = title.trim()

    if (!next || next === (titleLabel() ?? "")) return true
    setPending("rename", true)

    const success = await serverSDK.api.session
      .update({ sessionID: id, title: next })
      .then(() => true)
      .catch((error) => {
        showToast({ title: language.t("common.requestFailed"), description: errorMessage(error) })

        return false
      })

    setPending("rename", false)

    if (!success) return false
    const current = data.session.get(id)

    if (current) data.session.remember({ ...current, title: next })

    return true
  }

  const href = (id: string) => sessionHref(server.key, id)

  const navigateAfterRemoval = (id: string, parent?: string, next?: string) => {
    if (input.session.identity.params.id !== id) return

    if (parent) return navigate(href(parent))

    if (next) return navigate(href(next))

    return tabs.newDraft({ server: server.key, directory: sdk().directory })
  }

  const exportSession = async (id: string) => {
    try {
      const data = await fetchSessionExport({ sessionID: id, api: serverSDK.api })
      const filename = sessionExportFilename(data.info)

      if (!(await saveSessionExport(filename, data, platform))) return
      showToast({
        variant: "success",
        icon: "circle-check",
        title: language.t("toast.session.export.success.title"),
        description: language.t("toast.session.export.success.description", { filename }),
      })
    } catch (error) {
      showToast({
        variant: "error",
        title: language.t("toast.session.export.failed.title"),
        description: error instanceof Error ? error.message : language.t("toast.session.export.failed.description"),
      })
    }
  }

  const remove = async (id: string) => {
    const session = data.session.get(id)

    if (!session) return false
    const sessions = data.session.list().filter((item) => !item.parentID && !item.time?.archived)
    const index = sessions.findIndex((item) => item.id === id)
    const next = index === -1 ? undefined : (sessions[index + 1] ?? sessions[index - 1])
    const removed = sessionTreeIDs(data.session.list(), id)

    const success = await data.session
      .remove(id)
      .then(() => true)
      .catch((error) => {
        showToast({ title: language.t("session.delete.failed.title"), description: errorMessage(error) })

        return false
      })

    if (!success) return false
    void navigateAfterRemoval(id, session.parentID, next?.id)
    notifySessionTabsRemoved({ server: server.key, directory: sdk().directory, sessionIDs: removed })

    return true
  }

  function DeleteDialog(props: { sessionID: string }) {
    const name = createMemo(
      () => sessionTitle(data.session.get(props.sessionID)?.title) ?? language.t("session.tab.session"),
    )

    const confirm = async () => {
      await remove(props.sessionID)
      dialog.close()
    }

    return (
      <Dialog fit>
        <DialogHeader hideClose>
          <DialogTitleGroup
            title={language.t("session.delete.title")}
            description={language.t("session.delete.confirm", { name: name() })}
          />
        </DialogHeader>
        <DialogFooter>
          <Button variant="ghost" onClick={() => dialog.close()}>
            {language.t("common.cancel")}
          </Button>
          <Button variant="danger" onClick={confirm}>
            {language.t("session.delete.button")}
          </Button>
        </DialogFooter>
      </Dialog>
    )
  }

  createEffect(
    on(
      () => [input.session.data.parentID(), childTaskDescription()] as const,
      ([id, description]) => {
        if (!id || description || data.session.message.list(id).length > 0) return
        void Promise.all([data.session.sync(id), data.session.message.sync(id)])
      },
      { defer: true },
    ),
  )

  return {
    data: {
      sessionKey: input.session.identity.sessionKey,
      sessionID: input.session.identity.sessionID,
      status: input.session.data.status,
      titleValue,
      titleLabel,
      parentID: input.session.data.parentID,
      parentTitle,
      childTitle,
      showHeader,
      projection,
      timelineDetail,
      reasoningMode,
      shellToolPartsExpanded,
      editToolPartsExpanded,
    },
    pending: {
      rename: () => pending.rename,
    },
    action: {
      rename,
      export: exportSession,
      showDelete: (id: string) => dialog.show(() => <DeleteDialog sessionID={id} />),
      navigateParent: () => {
        const id = input.session.data.parentID()

        if (id) navigate(href(id))
      },
    },
  }
}

export type TimelineController = ReturnType<typeof createTimelineController>

import type { SessionMessageUser } from "@opencode/client/promise"
import { createResizeObserver } from "@solid-primitives/resize-observer"
import { useLocation } from "@solidjs/router"
import { createEffect, on, onCleanup } from "solid-js"
import { createStore } from "solid-js/store"
import { useLayout } from "@/shell/state/layout"
import type { SessionModel } from "../model"
import { useSessionHashScroll } from "../use-session-hash-scroll"
import { createTimelineModel } from "./model"

export function createSessionTimelineInteraction(session: SessionModel) {
  const layout = useLayout()
  const location = useLocation<{ reveal?: string }>()
  const timeline = createTimelineModel({ session })

  const [state, setState] = createStore<{
    messageID: string | undefined
    pendingMessage: string | undefined
    scroll: { overflow: boolean; jump: boolean }
    follow: { sessionKey: string; pinned: boolean }
    refs: {
      scroller: HTMLDivElement | undefined
      content: HTMLDivElement | undefined
      dock: HTMLDivElement | undefined
    }
  }>({
    messageID: undefined,
    pendingMessage: undefined,
    scroll: {
      overflow: false,
      jump: false,
    },
    follow: {
      sessionKey: session.identity.sessionKey(),
      pinned: true,
    },
    refs: {
      scroller: undefined,
      content: undefined,
      dock: undefined,
    },
  })

  // The single source of truth for "follow the newest content". The virtualizer pins and unpins
  // it from scroll geometry; everything else only expresses explicit intent.
  const pinned = () => state.follow.sessionKey !== session.identity.sessionKey() || state.follow.pinned
  const pin = () => setState("follow", { sessionKey: session.identity.sessionKey(), pinned: true })

  const unpin = () => {
    if (!scroller || scroller.scrollHeight - scroller.clientHeight <= 1) return
    setState("follow", { sessionKey: session.identity.sessionKey(), pinned: false })
  }

  let scroller: HTMLDivElement | undefined
  let dockHeight = 0
  // The history entry whose tool call was already revealed.
  let revealed: string | undefined

  // The active timeline's navigation, registered by its virtualizer.
  let revealMessage = (_id: string, _partID?: string) => {}

  let scrollToEnd = () => {}

  let scrollMark = 0
  let messageMark = 0
  let scrollStateFrame: number | undefined
  let scrollStateTarget: HTMLDivElement | undefined
  let fillFrame: number | undefined
  let historyContinuationFrame: number | undefined
  const historyRequests = new Set<string>()
  const visibleUserMessages = timeline.visibleUserMessages
  const anchor = (id: string) => `message-${id}`

  const cursor = () => {
    if (!scroller) return state.messageID
    const box = scroller.getBoundingClientRect()
    const line = box.top + 100

    const list = [...scroller.querySelectorAll<HTMLElement>("[data-message-id]")].flatMap((element) => {
      const id = element.dataset.messageId

      if (!id) return []
      const rect = element.getBoundingClientRect()

      return [{ id, top: rect.top, bottom: rect.bottom }]
    })

    const shown = list.filter((item) => item.bottom > box.top && item.top < box.bottom)
    const hit = shown.find((item) => item.top <= line && item.bottom >= line)

    if (hit) return hit.id

    const near = [...shown].sort((a, b) => {
      const aDistance = Math.abs(a.top - line)
      const bDistance = Math.abs(b.top - line)

      if (aDistance !== bDistance) return aDistance - bDistance

      return a.top - b.top
    })[0]

    if (near) return near.id

    return list.filter((item) => item.top <= line).at(-1)?.id ?? list[0]?.id ?? state.messageID
  }

  const setActiveMessage = (message: SessionMessageUser | undefined) => {
    messageMark = scrollMark
    setState("messageID", message?.id)
  }

  const jumpThreshold = (element: HTMLDivElement) => Math.max(400, element.clientHeight)

  const updateScrollState = (element: HTMLDivElement) => {
    const max = element.scrollHeight - element.clientHeight
    const distance = max - element.scrollTop
    const overflow = max > 1
    const jump = overflow && distance > jumpThreshold(element)

    if (state.scroll.overflow === overflow && state.scroll.jump === jump) return
    setState("scroll", { overflow, jump })
  }

  const scheduleScrollState = (element: HTMLDivElement) => {
    scrollStateTarget = element

    if (scrollStateFrame !== undefined) return
    scrollStateFrame = requestAnimationFrame(() => {
      scrollStateFrame = undefined
      const target = scrollStateTarget
      scrollStateTarget = undefined

      if (target) updateScrollState(target)
    })
  }

  const { clearMessageHash, scrollToMessage } = useSessionHashScroll({
    sessionKey: session.identity.sessionKey,
    sessionID: () => session.identity.params.id,
    messagesReady: timeline.ready,
    visibleUserMessages,
    historyMore: timeline.history.more,
    historyLoading: timeline.history.loading,
    loadMore: loadOlder,
    currentMessageId: () => state.messageID,
    pendingMessage: () => state.pendingMessage,
    setPendingMessage: (value) => setState("pendingMessage", value),
    setActiveMessage,
    follow: {
      unpin,
      toBottom: () => {
        pin()
        scrollToEnd()
      },
    },
    scroller: () => scroller,
    anchor,
    revealMessage: (id) => revealMessage(id),
    scheduleScrollState,
    consumePendingMessage: (key) => layout.pendingMessage.consume(key),
  })

  const resume = () => {
    setState("messageID", undefined)
    pin()
    scrollToEnd()
    clearMessageHash()

    if (scroller) scheduleScrollState(scroller)
  }

  const navigateMessage = (offset: number) => {
    const messages = visibleUserMessages()

    if (messages.length === 0) return
    const current = state.messageID && messageMark === scrollMark ? state.messageID : cursor()
    const base = current ? messages.findIndex((message) => message.id === current) : messages.length
    const target = (base === -1 ? messages.length : base) + offset

    if (target < 0 || target > messages.length) return

    if (target === messages.length) {
      resume()

      return
    }

    unpin()
    scrollToMessage(messages[target], "auto")
  }

  // A gesture inside a nested scrollable region scrolls that region, not the timeline.
  const markUserScroll = (target?: EventTarget | null) => {
    if (!scroller) return
    const element = target instanceof Element ? target : undefined
    const nested = element?.closest("[data-scrollable]")

    if (nested && nested !== scroller) return
    scrollMark += 1
  }

  const selectionInteraction = () => {
    const selection = window.getSelection()

    if (selection && selection.toString().length > 0) unpin()
  }

  const setScrollRef = (element: HTMLDivElement | undefined) => {
    scroller = element
    setState("refs", "scroller", element)

    if (!element) return
    scheduleScrollState(element)
    fill()
  }

  async function loadOlder() {
    const owner = session.ownership.capture()

    if (timeline.history.loading() || historyRequests.has(owner.key)) return
    historyRequests.add(owner.key)
    const before = timeline.messages().length

    try {
      await timeline.history.loadOlder()
    } finally {
      historyRequests.delete(owner.key)
    }

    if (!owner.current() || timeline.messages().length <= before) return

    if (pinned() || !scroller || scroller.scrollTop >= 200 || !timeline.history.more()) return

    if (historyContinuationFrame !== undefined) cancelAnimationFrame(historyContinuationFrame)
    historyContinuationFrame = requestAnimationFrame(() => {
      historyContinuationFrame = undefined
      owner.run(onHistoryScroll)
    })
  }

  const onHistoryScroll = () => {
    if (
      historyRequests.has(session.ownership.key()) ||
      timeline.history.loading() ||
      pinned() ||
      !scroller ||
      scroller.scrollTop >= 200
    )
      return
    void loadOlder()
  }

  const fill = () => {
    if (fillFrame !== undefined) return
    fillFrame = requestAnimationFrame(() => {
      fillFrame = undefined

      if (!session.identity.params.id || !timeline.ready()) return

      if (!pinned() || timeline.history.loading() || !scroller) return

      if (scroller.scrollHeight > scroller.clientHeight + 1 || !timeline.history.more()) return
      void loadOlder()
    })
  }

  createEffect(
    on(
      () => visibleUserMessages().at(-1)?.id,
      (lastID, previousID) => {
        if (lastID && previousID && lastID > previousID) setState("messageID", undefined)
      },
      { defer: true },
    ),
  )
  createEffect(
    on(
      session.identity.sessionKey,
      () => {
        pin()
        setState("messageID", undefined)
        setState("pendingMessage", undefined)
        setState("scroll", { overflow: false, jump: false })
      },
      { defer: true },
    ),
  )
  createEffect(
    on(
      () => session.identity.params.id,
      (id, previous) => {
        if (!id || !previous || id === previous || state.messageID || state.pendingMessage || location.hash) return
        pin()
        scrollToEnd()
      },
    ),
  )
  createEffect(
    on(
      pinned,
      (value) => {
        if (!value) return
        setState("messageID", undefined)
        clearMessageHash()
      },
      { defer: true },
    ),
  )
  createEffect(
    on(
      () =>
        [
          session.identity.params.id,
          timeline.ready(),
          timeline.history.more(),
          timeline.history.loading(),
          pinned(),
          visibleUserMessages().length,
        ] as const,
      ([id, ready, more, loading, following]) => {
        if (id && ready && more && !loading && following) fill()
      },
      { defer: true },
    ),
  )
  createResizeObserver(
    () => state.refs.content,
    () => {
      if (scroller) scheduleScrollState(scroller)
      fill()
    },
  )
  createResizeObserver(
    () => state.refs.dock,
    ({ height }) => {
      const next = Math.ceil(height)

      if (next === dockHeight) return
      const delta = next - dockHeight

      const stick = scroller
        ? pinned() || scroller.scrollHeight - scroller.clientHeight - scroller.scrollTop < 10 + Math.max(0, delta)
        : false

      dockHeight = next

      if (stick) scrollToEnd()

      if (scroller) scheduleScrollState(scroller)
      fill()
    },
  )
  onCleanup(() => {
    if (historyContinuationFrame !== undefined) cancelAnimationFrame(historyContinuationFrame)

    if (scrollStateFrame !== undefined) cancelAnimationFrame(scrollStateFrame)

    if (fillFrame !== undefined) cancelAnimationFrame(fillFrame)
  })

  return {
    actions: {
      navigateMessage,
      revealMessage: (id: string, partID?: string) => revealMessage(id, partID),
      resume,
      setActiveMessage,
    },
    lastUserMessage: timeline.lastUserMessage,
    resource: timeline.resource,
    ready: timeline.ready,
    scroll: state.scroll,
    scroller: () => state.refs.scroller,
    view: {
      anchor,
      markUserScroll,
      onHistoryScroll,
      pin,
      pinned,
      selectionInteraction,
      scheduleScrollState,
      setContentRef: (element: HTMLDivElement | undefined) => {
        setState("refs", "content", element)

        if (scroller) scheduleScrollState(scroller)
      },
      setDockRef: (element: HTMLDivElement | undefined) => {
        setState("refs", "dock", element)
      },
      setRevealMessage: (reveal: (id: string, partID?: string) => void) => {
        revealMessage = reveal
      },
      // The tool call the route opened the session on, revealed once per history entry.
      reveal: {
        target: () => (revealed === location.key ? undefined : location.state?.reveal),
        done: () => {
          revealed = location.key
        },
      },
      setScrollRef,
      setScrollToEnd: (scroll: () => void) => {
        scrollToEnd = scroll
      },
      unpin,
    },
  }
}

export type SessionTimelineInteraction = ReturnType<typeof createSessionTimelineInteraction>

import { createEffect, createMemo, createSignal, on, onCleanup, Show, type Accessor, type JSX } from "solid-js"
import { createStore } from "solid-js/store"
import { Predicate } from "effect"
import { createAnimatedPresence } from "@/runtime/animated-presence"
import type { SessionUserActions } from "@opencode/session-ui/actions"
import { Button } from "@opencode/ui/button"
import { Icon } from "@opencode/ui/icon"
import { IconButton } from "@opencode/ui/icon-button"
import { InlineInput } from "@opencode/ui/inline-input"
import { Keybind } from "@opencode/ui/keybind"
import { Menu } from "@opencode/ui/menu"
import { TextShimmer } from "@opencode/ui/text-shimmer"
import type { BackgroundTask, MountedSession, SessionScreen } from "@opencode/gui-extensions/sdk"
import { ExtensionSlot } from "@/runtime/extension/render"
import { useLanguage } from "@/runtime/i18n/language"
import { useServer } from "@/runtime/server/current"
import { useWorkspaceLocation } from "@/workspaces/location"
import { Timeline } from "@opencode/session-ui/timeline/projection"
import { createSessionTimelineRowRenderer } from "@opencode/session-ui/timeline/row"
import { getReadyMarkdown, preloadMarkdown } from "@opencode/session-ui/markdown-cache"
import { createTimelineController, type TimelineController, type TimelineSessionSource } from "./controller"
import { createTimelineVirtualizer } from "./virtualizer"
import { containsDirectory } from "@opencode/util/path"
import { isWorkspaceDirectory } from "@/workspaces/paths"
import { parseCommentNote, readPromptPresentation } from "@/composer/comment-note"
import { parseVoiceDelegation } from "./voice-delegation"
import { useCommand } from "@/shell/commands/command"
import { SessionAncestorTrail, SessionProjectMenu, SessionTitleHeader } from "../session-identity-header"
import { SessionHeaderSpacer } from "@/session/header/session-header"
import { SessionRunningMenu } from "@/session/header/session-running-menu"

type BlockingTask = { type: "shell" | "subagent"; partID: string; id?: string; label?: string }

type SessionBackground = {
  blocking: Accessor<BlockingTask[]>
  tasks: Accessor<readonly BackgroundTask[]>
  running: {
    sessionID: Accessor<string | undefined>
    blocking: Accessor<BlockingTask[]>
    tasks: Accessor<readonly BackgroundTask[]>
  }
  move: () => Promise<void>
}

export function BackgroundMoveHint(props: { keybind?: string[]; onMove?: () => void }) {
  const language = useLanguage()
  const command = useCommand()
  const keys = () => props.keybind ?? command.keybindParts("session.background")
  const keybind = () => props.keybind?.join("+") ?? command.keybind("session.background")

  return (
    <Button
      data-component="session-background-hint"
      type="button"
      variant="ghost-faint"
      size="small"
      class="max-w-full"
      aria-label={language.t("session.background.moveInline", { keybind: keybind() })}
      onClick={() => props.onMove?.()}
    >
      <span class="min-w-0 truncate">{language.t("session.background.moveRunning")}</span>
      <Keybind keys={keys()} variant="neutral" />
    </Button>
  )
}

type MessageTimelineProps = {
  hideHeader?: boolean
  active?: boolean
  session: TimelineSessionSource
  view: MountedSession
  screen: SessionScreen
  background: SessionBackground
  actions?: SessionUserActions
  scroll: { overflow: boolean; jump: boolean }
  onResumeScroll: () => void
  setScrollRef: (el: HTMLDivElement | undefined) => void
  onScheduleScrollState: (el: HTMLDivElement) => void
  onPin: () => void
  onUnpin: () => void
  onUserScroll: (target?: EventTarget | null) => void
  onHistoryScroll: () => void
  onSelectionInteraction: (event: MouseEvent) => void
  pinned: boolean
  centered: boolean
  reserveReviewToggle: boolean
  setContentRef: (el: HTMLDivElement) => void
  anchor: (id: string) => string
  setRevealMessage?: (fn: (id: string, partID?: string) => void) => void
  setScrollToEnd?: (fn: () => void) => void
  reveal?: { target: () => string | undefined; done: () => void }
  search?: JSX.Element
}

export function MessageTimeline(props: MessageTimelineProps) {
  const controller = createTimelineController({ session: props.session })
  const tail = props.pinned ? controller.data.projection.rows().at(-1) : undefined

  if (tail?._tag === "AssistantPart" && tail.group.type === "part") {
    const message = controller.data.projection.messageByID().get(tail.group.ref.messageID)

    if (message?.type === "assistant" && message.time.completed !== undefined) {
      const content = Timeline.resolveContent(message, tail.group.ref.partID)

      // Start the required worker job while the rest of the selected view is constructed.
      if (content?.type === "text" && content.text.trim()) {
        const preload = new AbortController()
        onCleanup(() => preload.abort())
        void preloadMarkdown(content.text, tail.group.ref.partID, preload.signal).catch(() => undefined)
      }
    }
  }

  return (
    <MessageTimelineView {...props} data={controller.data} action={controller.action} pending={controller.pending} />
  )
}

function MessageTimelineView(
  props: MessageTimelineProps & {
    data: TimelineController["data"]
    action: TimelineController["action"]
    pending: TimelineController["pending"]
  },
) {
  const language = useLanguage()
  const server = useServer()
  const data = server.ctx.data
  const sdk = useWorkspaceLocation()
  const sessionID = props.data.sessionID
  const sessionStatus = props.data.status
  const titleLabel = props.data.titleLabel
  const parentID = props.data.parentID
  const parentTitle = props.data.parentTitle
  const childTitle = props.data.childTitle
  const projection = props.data.projection
  const sessionDirectory = createMemo(() => props.session.data.info()?.location.directory ?? sdk().directory)

  const project = createMemo(() => {
    const session = props.session.data.info()
    const projects = server.ctx.sync.data.project

    return session
      ? server.ctx.projects.detailsForSession(session)
      : projects.find((item) => containsDirectory(item.worktree, sessionDirectory()))
  })

  const workspaceSession = createMemo(() => isWorkspaceDirectory(project(), sessionDirectory()))

  const headerProject = createMemo(() => {
    const session = props.session.data.info()

    if (!session) return

    return server.ctx.projects.forSession(session)
  })

  createEffect(() => {
    const directory = project()?.worktree

    if (!directory) return
    void data.location.vcs.sync({ directory }).catch(() => undefined)
  })
  const turnPadding = () => "px-4 md:px-6"
  const showHeader = createMemo(() => !props.hideHeader && (props.data.showHeader() || workspaceSession()))
  const pinned = createMemo(() => props.pinned)
  const messageByID = projection.messageByID

  const virtualized = createTimelineVirtualizer({
    active: () => props.active !== false,
    sessionKey: () => `${server.key}/${props.data.sessionID()}`,
    presentationKey: () => JSON.stringify(props.data.timelineDetail()),
    projection,
    showHeader,
    pinned,
    scroll: () => props.scroll,
    onResumeScroll: props.onResumeScroll,
    setScrollRef: props.setScrollRef,
    setContentRef: props.setContentRef,
    onScheduleScrollState: props.onScheduleScrollState,
    onPin: props.onPin,
    onUnpin: props.onUnpin,
    onSelectionInteraction: props.onSelectionInteraction,
    onUserScroll: props.onUserScroll,
    onHistoryScroll: props.onHistoryScroll,
    canRenderImmediately: (row, disclosure) => {
      if (
        Predicate.isTagged(row, "TurnGap") ||
        Predicate.isTagged(row, "TurnDivider") ||
        Predicate.isTagged(row, "CompactionQueued") ||
        Predicate.isTagged(row, "Activity")
      )
        return true

      if (Predicate.isTagged(row, "Notice")) {
        const message = messageByID().get(row.messageID)

        return (
          (message?.type === "system" || message?.type === "synthetic") &&
          (message.description ?? message.text).length <= 1024
        )
      }

      if (Predicate.isTagged(row, "UserMessage")) {
        const message = messageByID().get(row.userMessageID)

        if (message?.type !== "user" || message.text.length > 1024 || message.files?.length || message.agents?.length)
          return false
        const presentation = readPromptPresentation(message.metadata)

        return (
          (presentation?.displayText ?? message.text).length <= 1024 &&
          !presentation?.comments?.length &&
          !presentation?.attachments.length &&
          !parseCommentNote(message.text)
        )
      }

      if (!Predicate.isTagged(row, "AssistantPart") || row.group.type !== "part") return false
      const message = messageByID().get(row.group.ref.messageID)

      if (message?.type !== "assistant" || message.time.completed === undefined) return false
      const content = Timeline.resolveContent(message, row.group.ref.partID)

      if (content?.type === "reasoning")
        return !(disclosure[row.group.ref.partID] ?? props.data.reasoningMode() === "full")

      return (
        content?.type === "text" &&
        content.text.length <= 1024 &&
        !!getReadyMarkdown({ raw: content.text, src: content.text }, `${row.group.ref.partID}:0:full`)
      )
    },
    setRevealMessage: props.setRevealMessage,
    setScrollToEnd: props.setScrollToEnd,
    reveal: props.reveal,
  })

  const VirtualizedTimeline = virtualized.View

  const [title, setTitle] = createStore({
    draft: "",
    editing: false,
    menuOpen: false,
    pendingRename: false,
  })

  let titleRef: HTMLInputElement | undefined

  createEffect(
    on(
      props.data.sessionKey,
      () =>
        setTitle({
          draft: "",
          editing: false,
          menuOpen: false,
          pendingRename: false,
        }),
      { defer: true },
    ),
  )

  const openTitleEditor = () => {
    if (!sessionID() || parentID()) return
    setTitle({ editing: true, draft: titleLabel() ?? "" })
    requestAnimationFrame(() => {
      if (!titleRef) return
      titleRef.focus()
      titleRef.select()
    })
  }

  const closeTitleEditor = () => {
    if (props.pending.rename()) return
    setTitle("editing", false)
  }

  const saveTitleEditor = async () => {
    if (!title.editing || props.pending.rename()) return

    if (await props.action.rename(title.draft)) setTitle("editing", false)
  }

  createEffect(() => {
    if (props.active !== false) return
    setTitle({ draft: "", editing: false, menuOpen: false, pendingRename: false })
  })

  const rowRenderer = createSessionTimelineRowRenderer({
    sessionID: () => sessionID()!,
    status: sessionStatus,
    projection,
    presentation: (message) => {
      const value = readPromptPresentation(message.metadata)
      const parsed = value ? undefined : parseCommentNote(message.text)
      const voice = parseVoiceDelegation(value?.displayText ?? message.text)

      return {
        displayText: voice ? (voice.framing ?? voice.instruction) : value?.displayText,
        comments: value?.comments ?? (parsed ? [parsed] : []),
        references: value?.attachments,
        voice: !!voice,
      }
    },
    actions: props.actions,
    reasoningMode: props.data.reasoningMode,
    shellToolDefaultOpen: props.data.shellToolPartsExpanded,
    editToolDefaultOpen: props.data.editToolPartsExpanded,
    timelineDetail: props.data.timelineDetail,
    disclosure: virtualized.disclosure,
    centered: () => props.centered,
    padding: turnPadding,
    anchor: props.anchor,
  })

  const backgroundHintPartID = createMemo(() => {
    const blocking = new Set(props.background.blocking().map((task) => task.partID))

    if (blocking.size === 0) return

    return projection
      .rows()
      .flatMap((row) =>
        Predicate.isTagged(row, "AssistantPart") ? (row.group.type === "part" ? [row.group.ref] : row.group.refs) : [],
      )
      .findLast((ref) => blocking.has(ref.partID))?.partID
  })

  const [backgroundHintRef, setBackgroundHintRef] = createSignal<HTMLDivElement>()

  const backgroundHintPresence = createAnimatedPresence(
    backgroundHintPartID,
    () => backgroundHintRef() ?? null,
    sessionID,
    1000,
  )

  const showWorking = createMemo(() => {
    const id = sessionID()

    if (!id || sessionStatus().type !== "busy") return false

    if (data.session.permission.list(id)?.length || data.session.form.list(id)?.length) return false
    const active = projection.activeMessageID()

    if (!active) return false
    const assistant = projection.assistantMessagesByParent().get(active)?.at(-1)

    if (assistant?.retry) return false

    // Pending steers still project under the previous response until delivery.
    // Its error must not hide feedback for a newly submitted prompt.
    if (
      assistant?.error &&
      !data.session.pending.list(id).some((item) => item.type === "user" && item.delivery === "steer")
    )
      return false
    const content = assistant?.content.at(-1)

    if (
      assistant?.time.completed === undefined &&
      assistant?.time.streamed === undefined &&
      content?.type === "text" &&
      content.text.trim()
    )
      return false
    const background = new Set(props.background.tasks().map((task) => task.id))

    return !projection.rows().some((row) => {
      if (row.userMessageID !== active) return false

      if (Predicate.isTagged(row, "Thinking")) return true

      if (Predicate.isTagged(row, "Notice")) {
        const message = messageByID().get(row.messageID)

        return message?.type === "compaction" && message.status === "running"
      }

      // Used and read groups keep the fallback, so each new read does not swap Working out for its short call.
      if (!Predicate.isTagged(row, "AssistantPart") || row.group.type === "context" || row.group.type === "read")
        return false

      return (row.group.type === "part" ? [row.group.ref] : row.group.refs).some((ref) => {
        const content = Timeline.resolveContent(messageByID().get(ref.messageID), ref.partID)

        if (content?.type !== "tool") return false

        if (content.state.status === "streaming" || content.state.status === "running") return true
        const taskID = content.state.metadata?.[content.name === "subagent" ? "sessionID" : "shellID"]

        return background.has(content.id) || (Predicate.isString(taskID) && background.has(taskID))
      })
    })
  })

  // Undelivered input waits below the work the model has seen, so live status moves into the row above it.
  const activityRow = createMemo(() => projection.rows().some((row) => Predicate.isTagged(row, "Activity")))

  const activity = () => (
    <Show when={showWorking() || backgroundHintPresence.present()}>
      <div
        classList={{
          "min-w-0 w-full max-w-full": true,
          "md:max-w-session md:mx-auto": props.centered,
        }}
      >
        <div class={`flex h-9 items-center gap-2 pt-3 text-[13px] font-[530] leading-text-compact ${turnPadding()}`}>
          <Show when={showWorking()}>
            <div data-component="session-working" role="status">
              <TextShimmer text={language.t("session.timeline.working")} active />
            </div>
          </Show>
          <Show when={backgroundHintPresence.present()}>
            <div
              ref={setBackgroundHintRef}
              data-component="session-background-hint-row"
              class="duration-150 motion-reduce:animate-none"
              classList={{
                "animate-in fade-in": backgroundHintPresence.animate() && backgroundHintPresence.show(),
                "animate-out fade-out fill-mode-forwards":
                  backgroundHintPresence.animate() && !backgroundHintPresence.show(),
              }}
            >
              <BackgroundMoveHint onMove={props.background.move} />
            </div>
          </Show>
        </div>
      </div>
    </Show>
  )

  const runningMenu = (title?: string) => (
    <SessionRunningMenu
      sessionID={sessionID()}
      owner={props.background.running.sessionID()}
      blocking={props.background.running.blocking()}
      tasks={props.background.running.tasks()}
      onReveal={virtualized.revealPart}
      title={title}
    />
  )

  return (
    <VirtualizedTimeline
      workspaceSession={workspaceSession}
      bottomSpacer={<Show when={!activityRow()}>{activity()}</Show>}
      deferred={(row) => {
        if (!Predicate.isTagged(row, "AssistantPart") || row.group.type !== "part") return false
        const content = Timeline.resolveContent(messageByID().get(row.group.ref.messageID), row.group.ref.partID)

        return content?.type === "tool" && ["edit", "write"].includes(content.name)
      }}
      renderRow={(row, onSizeChange) => (
        <Show
          when={Predicate.isTagged(row(), "Activity")}
          fallback={<rowRenderer.Row row={row} onSizeChange={onSizeChange} />}
        >
          {activity()}
        </Show>
      )}
      header={
        <Show when={!props.hideHeader}>
          <SessionTitleHeader>
            <div class="h-12 w-full flex items-center justify-between gap-2">
              <div class="flex items-center gap-1 min-w-0 flex-1">
                <div class="flex items-center gap-0.5 min-w-0 flex-1 w-full">
                  <SessionProjectMenu
                    project={headerProject()}
                    directory={sessionDirectory()}
                    workspace={workspaceSession()}
                  />
                  <Show when={parentID()}>
                    {(id) => (
                      <SessionAncestorTrail
                        sessionID={sessionID() ?? ""}
                        parentID={id()}
                        parentTitle={parentTitle()}
                        trailing={!!(childTitle() || title.editing)}
                      />
                    )}
                  </Show>
                  <Show when={parentID()}>{runningMenu(childTitle())}</Show>
                  <Show when={!parentID() && (childTitle() || title.editing)}>
                    <Show
                      when={title.editing}
                      fallback={
                        <h1
                          data-slot="session-title-child"
                          class="truncate text-[13px] font-[530] leading-4 tracking-[-0.04px] text-v2-text-text-base w-fit rounded-[6px] px-1 py-1 hover:bg-v2-overlay-simple-overlay-hover"
                          classList={{ "max-w-[45%] shrink-0": !!parentID() }}
                          onClick={openTitleEditor}
                        >
                          {childTitle()}
                        </h1>
                      }
                    >
                      <InlineInput
                        ref={(el) => {
                          titleRef = el
                        }}
                        data-slot="session-title-child"
                        dir="auto"
                        value={title.draft}
                        disabled={props.pending.rename()}
                        class="block text-[13px] font-[530] leading-4 tracking-[-0.04px] text-v2-text-text-base field-sizing-content rounded-[6px] px-1 py-1"
                        classList={{ "max-w-[45%] shrink-0": !!parentID() }}
                        style={{
                          "--inline-input-shadow": "none",
                          "text-align": "start",
                        }}
                        onInput={(event) => setTitle("draft", event.currentTarget.value)}
                        onKeyDown={(event) => {
                          event.stopPropagation()

                          if (event.isComposing || event.keyCode === 229) return

                          if (event.key === "Enter") {
                            event.preventDefault()
                            void saveTitleEditor()

                            return
                          }

                          if (event.key === "Escape") {
                            event.preventDefault()
                            closeTitleEditor()
                          }
                        }}
                        onBlur={() => void saveTitleEditor()}
                      />
                    </Show>
                  </Show>
                  <Show when={!parentID()}>{runningMenu()}</Show>
                  <Show when={!parentID() && sessionID()} keyed>
                    {(id) => (
                      <Menu
                        gutter={6}
                        placement="bottom-start"
                        open={title.menuOpen}
                        onOpenChange={(open) => setTitle("menuOpen", open)}
                      >
                        <Menu.Trigger
                          as={IconButton}
                          icon={<Icon name="outline-dots" />}
                          variant="ghost-muted"
                          size="large"
                          class="shrink-0"
                          aria-label={language.t("common.moreOptions")}
                          aria-expanded={title.menuOpen}
                        />
                        <Menu.Portal>
                          <Menu.Content
                            class="session-options-menu w-max"
                            style={{ "min-width": "0" }}
                            onCloseAutoFocus={(event) => {
                              if (!title.pendingRename) return
                              event.preventDefault()
                              setTitle("pendingRename", false)
                              openTitleEditor()
                            }}
                          >
                            <Show when={!parentID()}>
                              <Menu.Item
                                onSelect={() => {
                                  setTitle("pendingRename", true)
                                  setTitle("menuOpen", false)
                                }}
                              >
                                {language.t("common.rename")}
                              </Menu.Item>
                              <Menu.Item onSelect={() => void props.action.export(id)}>
                                {language.t("common.export")}…
                              </Menu.Item>
                            </Show>
                            <Show when={!parentID()}>
                              {/* TODO: Need a session archive API. */}
                              <Menu.Separator />
                              <Menu.Item onSelect={() => props.action.showDelete(id)}>
                                {language.t("common.delete")}…
                              </Menu.Item>
                            </Show>
                          </Menu.Content>
                        </Menu.Portal>
                      </Menu>
                    )}
                  </Show>
                </div>
              </div>
              <Show when={sessionID()} keyed>
                {(_id) => (
                  <div class="shrink-0 flex items-center gap-2">
                    {props.search}
                    <ExtensionSlot
                      at="session.header"
                      input={{
                        get session() {
                          return props.view
                        },
                        get screen() {
                          return props.screen
                        },
                        get active() {
                          return props.active !== false
                        },
                      }}
                    />
                    <SessionHeaderSpacer visible={props.reserveReviewToggle} />
                  </div>
                )}
              </Show>
            </div>
          </SessionTitleHeader>
        </Show>
      }
    />
  )
}

import { describe, expect, test } from "bun:test"
import type { SessionMessageAssistant, SessionMessageInfo, SessionMessageUser } from "@opencode/client/promise"
import { enrichLeadingTurn, loadOlderTimeline } from "./model"

const user = (id: string): SessionMessageUser => ({ id, type: "user", text: id, time: { created: 1 } })

const assistant = (id: string): SessionMessageAssistant => ({
  id,
  type: "assistant",
  agent: "build",
  model: { id: "model", providerID: "provider" },
  content: [],
  time: { created: 1 },
})

describe("timeline model", () => {
  test.each([
    ["restores the anchor after one opaque cursor page", "ok", ["before", "load", "after", true]],
    ["does not restore an anchor after the session changes", "switch", ["before", "load"]],
    ["releases the anchor when loading history fails", "fail", ["before", "load", "after", true, "history failed"]],
  ] as const)("%s", async (_name, outcome, expected) => {
    let sessionID = "ses_old"
    const calls: Array<string | boolean> = []

    await loadOlderTimeline({
      sessionID: () => sessionID,
      more: () => true,
      loading: () => false,
      loadMore: async () => {
        calls.push("load")

        if (outcome === "switch") sessionID = "ses_new"

        if (outcome === "fail") throw new Error("history failed")
      },
      before: () => calls.push("before"),
      after: (done) => calls.push("after", done),
    }).catch((error: Error) => calls.push(error.message))

    expect(calls).toEqual([...expected])
  })

  test.each([
    ["caps background pages when the parent remains outside the window", [assistant("msg_latest")], 3],
    ["does not load before a leading user turn", [user("msg_user"), assistant("msg_latest")], 0],
    ["does not load without an assistant turn", [user("msg_user")], 0],
  ])("%s", async (_name, messages: SessionMessageInfo[], expected) => {
    let loads = 0

    await enrichLeadingTurn({
      current: () => true,
      messages: () => messages,
      more: () => true,
      loading: () => false,
      loadMore: async () => {
        loads += 1
      },
      pause: async () => undefined,
      maxPages: 3,
    })

    expect(loads).toBe(expected)
  })

  test("pauses between history pages and stops once the leading turn has its parent", async () => {
    const pages: SessionMessageInfo[][] = [[assistant("msg_older")], [user("msg_parent")], [user("msg_earlier")]]
    const messages: SessionMessageInfo[] = [assistant("msg_latest"), user("msg_next")]
    const calls: string[] = []

    await enrichLeadingTurn({
      current: () => true,
      messages: () => messages,
      more: () => pages.length > 0,
      loading: () => false,
      loadMore: async () => {
        const page = pages.shift()!
        messages.unshift(...page)
        calls.push(`load:${page[0]!.id}`)
      },
      pause: async () => {
        calls.push("pause")
      },
      maxPages: 3,
    })

    expect(calls).toEqual(["pause", "load:msg_older", "pause", "load:msg_parent"])
    expect(pages).toHaveLength(1)
  })
})

import { createMemo, createResource, type Accessor } from "solid-js"
import type { SessionMessageInfo } from "@opencode/client/promise"
import { useData } from "@/runtime/server/current"
import { getSessionMessageHandoff } from "@/session/handoff"
import type { SessionModel } from "../model"

const leadingTurnPageDelay = 200

const leadingTurnPageLimit = 3

export function createTimelineModel(input: { session: Pick<SessionModel, "identity" | "history" | "ownership"> }) {
  const data = useData()

  const [resource] = createResource(
    () => input.session.identity.sessionID(),
    async (id) => {
      if (!id) return
      const owner = input.session.ownership.capture()
      await Promise.all([data.session.message.sync(id), data.session.pending.sync(id)])
      await enrichLeadingTurn({
        current: owner.current,
        messages: () => data.session.message.list(id),
        more: () => data.session.message.more(id),
        loading: () => data.session.message.loading(id),
        loadMore: () => data.session.message.loadMore(id),
        pause: () => new Promise((resolve) => setTimeout(resolve, leadingTurnPageDelay)),
        maxPages: leadingTurnPageLimit,
      }).catch(() => undefined)

      return id
    },
  )

  const ready = createMemo(() => {
    const id = input.session.identity.sessionID()

    if (!id || (!resource.loading && resource.latest === id)) return true

    // Enrich the partial leading group without withholding the already loaded tail. Undelivered inbox rows
    // load with the inbox, not the transcript, so alone they are no tail; a first prompt shows through its handoff.
    return (
      data.session.message.list(id).some((message) => !data.session.input.has(id, message.id)) ||
      !!getSessionMessageHandoff(input.session.identity.sessionKey())
    )
  })

  const more = () => {
    const id = input.session.identity.sessionID()

    return id ? data.session.message.more(id) : false
  }

  const loading = () => {
    const id = input.session.identity.sessionID()

    return id ? data.session.message.loading(id) : false
  }

  const loadOlder = async (options?: { before?: () => void; after?: (done: boolean) => void }) => {
    return loadOlderTimeline({
      sessionID: input.session.identity.sessionID,
      more,
      loading,
      loadMore: (id) => data.session.message.loadMore(id),
      before: options?.before,
      after: options?.after,
    })
  }

  return {
    history: { loadOlder, loading, more },
    lastUserMessage: input.session.history.lastUserMessage,
    messages: input.session.history.messages,
    ready,
    resource,
    visibleUserMessages: input.session.history.visibleUserMessages,
  }
}

export async function enrichLeadingTurn(input: {
  current: Accessor<boolean>
  messages: Accessor<SessionMessageInfo[]>
  more: Accessor<boolean>
  loading: Accessor<boolean>
  loadMore: () => Promise<void>
  pause: () => Promise<void>
  maxPages: number
}) {
  const load = async (pages: number): Promise<void> => {
    if (!input.current() || pages >= input.maxPages || !leadingTurnNeedsParent(input.messages()) || !input.more())
      return
    await input.pause()

    if (!input.current() || !leadingTurnNeedsParent(input.messages()) || !input.more()) return

    if (input.loading()) return load(pages)
    await input.loadMore()

    return load(pages + 1)
  }

  return load(0)
}

function leadingTurnNeedsParent(messages: SessionMessageInfo[]) {
  const assistant = messages.findIndex((message) => message.type === "assistant")

  if (assistant === -1) return false
  const boundary = messages.findIndex((message) => message.type === "user" || message.type === "shell")

  return boundary === -1 || assistant < boundary
}

export async function loadOlderTimeline(input: {
  sessionID: Accessor<string | undefined>
  more: Accessor<boolean>
  loading: Accessor<boolean>
  loadMore: (sessionID: string) => Promise<void>
  before?: () => void
  after?: (done: boolean) => void
}) {
  const id = input.sessionID()

  if (!id || !input.more() || input.loading()) return

  input.before?.()
  await input.loadMore(id).catch((error) => {
    if (input.sessionID() === id) input.after?.(true)
    throw error
  })

  if (input.sessionID() !== id) return
  input.after?.(true)
}

import { expect, test } from "bun:test"
