// A real virtualizer attached to the viewport the way its mount does (scroll element plus the window that owns it),
// without starting its own rect and offset observers, so each test drives the observer under test directly.
function attachedVirtualizer(viewport: HTMLDivElement, state: { scrollOffset: number; isScrollingResetDelay: number }) {
  const instance = new Virtualizer<HTMLDivElement, HTMLDivElement>({
    count: 0,
    getScrollElement: () => viewport,
    estimateSize: () => 0,
    scrollToFn: () => {},
    observeElementRect: () => {},
    observeElementOffset: () => {},
    isScrollingResetDelay: state.isScrollingResetDelay,
  })

  instance.scrollElement = viewport
  instance.targetWindow = viewport.ownerDocument.defaultView
  instance.scrollOffset = state.scrollOffset

  return instance
}

// A separate window whose MutationObserver and animation frames a test can replace without touching the global
// window. happy-dom loads a srcdoc frame synchronously, so its window is ready once the frame is attached.
function openFrame() {
  const frame = document.createElement("iframe")
  frame.srcdoc = ""
  document.body.append(frame)
  const targetWindow = frame.contentDocument?.defaultView

  if (!targetWindow) throw new Error("Frame window did not load")

  return { targetWindow, close: () => frame.remove() }
}

async function frames(count: number, targetWindow: Window = window) {
  for (let index = 0; index < count; index++) {
    await new Promise<void>((resolve) => targetWindow.requestAnimationFrame(() => resolve()))
  }
}

function controlledMutations(targetWindow: Window & typeof globalThis) {
  let flush: () => void = () => {
    throw new Error("Mutation observer is not active")
  }

  // Delivers each operation's records as soon as it happens instead of at the next microtask.
  class ControlledMutationObserver extends targetWindow.MutationObserver {
    constructor(callback: MutationCallback) {
      super(callback)
      flush = () => callback(this.takeRecords(), this)
    }
  }

  Object.defineProperty(targetWindow, "MutationObserver", { value: ControlledMutationObserver })

  return {
    append(parent: Node, node: Node) {
      parent.appendChild(node)
      flush()
    },
    remove(node: Node) {
      const parent = node.parentNode

      if (!parent) throw new Error("Mutation target has no parent")
      parent.removeChild(node)
      flush()
    },
  }
}

function controlledAnimationFrames(targetWindow: Window) {
  let time = 0
  let id = 0
  const callbacks = new Map<number, FrameRequestCallback>()
  Object.defineProperty(targetWindow.performance, "now", { value: () => time })
  Object.defineProperty(targetWindow, "requestAnimationFrame", {
    value: (callback: FrameRequestCallback) => {
      id += 1
      callbacks.set(id, callback)

      return id
    },
  })
  Object.defineProperty(targetWindow, "cancelAnimationFrame", {
    value: (frame: number) => callbacks.delete(frame),
  })

  return {
    run(at: number) {
      time = at
      const pending = [...callbacks.values()]
      callbacks.clear()
      pending.forEach((callback) => callback(at))
    },
    pending: () => callbacks.size,
  }
}

import { observeElementOffset, type Virtualizer } from "@tanstack/solid-virtual"

export function observeElementOffsetReconnectAware<TScrollElement extends Element, TItemElement extends Element>(
  instance: Virtualizer<TScrollElement, TItemElement>,
  callback: (offset: number, isScrolling: boolean) => void,
  onReconnect?: () => void,
) {
  let active = true
  const element = instance.scrollElement

  // TanStack resets isScrolling on a timer that reports the offset of the last scroll event. A virtualizer
  // write since then (prepend anchoring, size compensation) may not have dispatched its scroll event yet, and
  // compensating from that stale offset would undo the write, so a settled scroll reads the live scrollTop
  // (vertical only, like the reconnect check below).
  const deliver = (offset: number, isScrolling: boolean) => {
    if (!active) return
    callback(isScrolling || !element?.isConnected ? offset : element.scrollTop, isScrolling)
  }

  const cleanupOffset = observeElementOffset(instance, deliver)
  const targetWindow = instance.targetWindow
  const root = element?.closest("main") ?? element?.ownerDocument.body

  if (!element || !targetWindow || !root)
    return () => {
      active = false
      cleanupOffset?.()
    }

  // Cached views can be constructed before their first attachment to the page.
  let removed = !element.isConnected
  let frame: number | undefined

  const clearCheck = () => {
    if (frame === undefined) return
    targetWindow.cancelAnimationFrame(frame)
    frame = undefined
  }

  const startCheck = () => {
    clearCheck()
    const deadline = targetWindow.performance.now() + instance.options.isScrollingResetDelay
    let framesAfterDeadline = 0

    const check = (time: number) => {
      frame = undefined

      if (
        element.isConnected &&
        (instance.scrollOffset === null || Math.abs(element.scrollTop - instance.scrollOffset) > 1)
      )
        deliver(element.scrollTop, false)

      if (time >= deadline) framesAfterDeadline += 1

      if (framesAfterDeadline >= 2) return
      frame = targetWindow.requestAnimationFrame(check)
    }

    frame = targetWindow.requestAnimationFrame(check)
  }

  const observer = new targetWindow.MutationObserver((records) => {
    if (!active) return
    records.forEach((record) => {
      if (record.target === element || element.contains(record.target)) return

      if (mutationNodesContainElement(record.removedNodes, element)) {
        removed = true
        clearCheck()
      }

      if (!removed || !element.isConnected || !mutationNodesContainElement(record.addedNodes, element)) return
      removed = false
      onReconnect?.()
      startCheck()
    })
  })

  // Session routes are replaced below persistent main; body is the fallback for isolated hosts.
  observer.observe(root, { childList: true, subtree: true })

  return () => {
    active = false
    observer.disconnect()
    clearCheck()
    cleanupOffset?.()
  }
}

function mutationNodesContainElement(nodes: Iterable<Node>, element: Element) {
  return [...nodes].some((node) => node === element || node.contains(element))
}

