  })

  return (
    <SettingsKeybindsView
      visible={props.active}
      groups={controller.catalog.groups}
      filtered={controller.catalog.filtered}
      title={controller.catalog.title}
      keybind={controller.catalog.keybind}
      active={controller.capture.active()}
      onCapture={controller.capture.toggle}
      hasOverrides={controller.settings.hasOverrides()}
      onReset={controller.settings.reset}
    />
  )
}

function SettingsKeybindsView(props: {
  visible?: boolean
  groups: KeybindGroup[]
  filtered: (query: string) => Map<KeybindGroup, string[]>
  title: (id: string) => string
  keybind: (id: string) => string
  active: string | null
  onCapture: (id: string) => void
  hasOverrides: boolean
  onReset: () => void
}) {
  const language = useLanguage()
  const [store, setStore] = createStore({ filter: "" })
  const filtered = createMemo(() => props.filtered(store.filter))
  const hasResults = createMemo(() => props.groups.some((group) => (filtered().get(group)?.length ?? 0) > 0))

  return (
    <>
      <div class="settings-tab-header settings-tab-header--stacked">
        <div class="settings-tab-header-row">
          <div class="flex flex-col gap-1">
            <h2 class="settings-tab-title">{language.t("settings.shortcuts.title")}</h2>
            <span class="text-11-regular text-v2-text-text-muted">{language.t("settings.shortcuts.description")}</span>
          </div>
          <Button variant="ghost" onClick={props.onReset} disabled={!props.hasOverrides}>
            {language.t("settings.shortcuts.reset.button")}
          </Button>
        </div>
        <SettingsSearchField
          value={store.filter}
          active={props.visible ?? true}
          onInput={(value) => setStore("filter", value)}
          placeholder={language.t("settings.shortcuts.search.placeholder")}
        />
      </div>
      <div class="settings-tab-body">
        <div class="settings-shortcuts settings-section-stack">
          <For each={props.groups}>
            {(group) => (
              <Show when={(filtered().get(group) ?? []).length > 0}>
                <div class="settings-section">
                  <h3 class="settings-section-title">{language.t(groupKey[group])}</h3>
                  <SettingsList>
                    <For each={filtered().get(group) ?? []}>
                      {(id) => {
                        const binding = () => props.keybind(id)

                        return (
                          <div class="flex items-center justify-between gap-4 py-3 border-b border-border-weak-base last:border-none">
                            <span>{props.title(id)}</span>
                            <Button
                              type="button"
                              size="small"
                              variant={binding() ? "ghost" : "ghost-muted"}
                              data-keybind-id={id}
                              data-expanded={props.active === id ? "" : undefined}
                              onClick={() => props.onCapture(id)}
                            >
                              <Show
                                when={props.active === id}
                                fallback={binding() || language.t("settings.shortcuts.unassigned")}
                              >
                                {language.t("settings.shortcuts.pressKeys")}
                              </Show>
                            </Button>
                          </div>
                        )
                      }}
                    </For>
                  </SettingsList>
                </div>
              </Show>
            )}
          </For>
          <Show when={store.filter && !hasResults()}>
            <div class="settings-tab-search-empty">
              <SettingsSearchEmpty query={store.filter} />
            </div>
          </Show>
        </div>
      </div>
    </>
  )
}

import { batch, createEffect, untrack } from "solid-js"
import { Predicate } from "effect"
import type { useSettings } from "@/settings/model"

/**
 * Stored custom keybinds of commands that built-in GUI extensions now publish under another id. Each old id maps to
 * the current one, and a newer old id comes first, so its override wins over an older one.
 */
export const keybindRenames = {
  "app.checkForUpdates": "updater.check",
  "server.pair": "pairing.open",
  "server.ssh.add": "ssh.add",
  "debugBar.toggle": "debug.toggle",
  "session.btw": "btw.ask",
  // The details extension's earlier id, then the command before extensions.
  "summary.toggle": "details.toggle",
  "session.summary.toggle": "details.toggle",
} satisfies Readonly<Record<string, string>>

/** Moves renamed overrides once settings load. An override already stored under the new id wins. */
export function migrateKeybinds(settings: Pick<ReturnType<typeof useSettings>, "ready" | "keybinds">) {
  const state = { done: false }

  createEffect(() => {
    if (state.done || !settings.ready()) return
    state.done = true
    untrack(() =>
      batch(() =>
        Object.entries(keybindRenames).forEach(([from, to]) => {
          const value = settings.keybinds.get(from)

          if (!Predicate.isString(value)) return

          if (settings.keybinds.get(to) === undefined) settings.keybinds.set(to, value)
          settings.keybinds.reset(from)
        }),
      ),
    )
  })
}

