import { showToast } from "@/shell/notifications/toast"
import { consoleProviderGroup } from "@/providers/catalog/console"
import { useIntegrations } from "@/providers/catalog/integrations"
import { useProviders } from "@/providers/catalog/providers"
import { CONSOLE_INTEGRATION } from "@/providers/connect/controller"
import { useLanguage } from "@/runtime/i18n/language"
import { useServerSDK } from "@/runtime/server/client"
import { useData } from "@/runtime/server/current"
import { formatServerError } from "@/runtime/server/errors"
import { activeProviderAccount, type ProviderAccount } from "./accounts"

// Shared by the connect dialog and Settings so both switch, rename and remove accounts the same way.
export function useProviderAccountActions(directory: () => string | undefined) {
  const language = useLanguage()
  const sdk = useServerSDK()
  const data = useData()
  const providers = useProviders(directory)
  const integrations = useIntegrations(directory)

  const location = () => {
    const value = directory()

    return value ? { directory: value } : undefined
  }

  const refresh = async () => {
    const ref = location()
    data.location.integration.invalidate(ref)
    data.location.provider.invalidate(ref)
    data.location.model.invalidate(ref)
    await Promise.all([
      data.location.integration.sync(ref),
      data.location.provider.sync(ref),
      data.location.model.sync(ref),
    ])
  }

  // The server loads a Console workspace's providers after the credential changes, so the first
  // refresh can still show only the free catalog. Poll briefly before reporting the new account.
  // A Zen API key shares the Console integration but has no workspace to wait for.
  const settle = async (integrationID: string) => {
    const account = activeProviderAccount(integrations.list().find((integration) => integration.id === integrationID))

    if (integrationID !== CONSOLE_INTEGRATION || account?.method !== "oauth") return
    const deadline = Date.now() + 10_000

    while (!consoleProviderGroup(providers.connected()) && Date.now() < deadline) {
      await new Promise((resolve) => setTimeout(resolve, 250))
      data.location.provider.invalidate(location())
      data.location.model.invalidate(location())
      await Promise.all([data.location.provider.sync(location()), data.location.model.sync(location())])
    }
  }

  const fail = (message: string) => showToast({ title: language.t("common.requestFailed"), description: message })

  const activate = (input: { integrationID: string; provider: string; account: ProviderAccount }) =>
    sdk.api.credential
      .activate({ credentialID: input.account.id })
      .then(refresh)
      .then(() => settle(input.integrationID))
      .then(() =>
        showToast({
          variant: "success",
          icon: "circle-check",
          title: language.t("settings.providers.account.switched.title", { provider: input.provider }),
          description: language.t("settings.providers.account.switched.description", { account: input.account.label }),
        }),
      )
      .catch((error) => fail(formatServerError(error, language.t)))

  const remove = (input: { integrationID: string; provider: string; account: ProviderAccount; final: boolean }) =>
    sdk.api.credential
      .remove({ credentialID: input.account.id })
      .then(refresh)
      .then(() => (input.final ? undefined : settle(input.integrationID)))
      .then(() =>
        showToast({
          variant: "success",
          icon: "circle-check",
          title: input.final
            ? language.t("provider.disconnect.toast.disconnected.title", { provider: input.provider })
            : language.t("settings.providers.account.removed.title", { account: input.account.label }),
          description: input.final
            ? language.t("provider.disconnect.toast.disconnected.description", { provider: input.provider })
            : language.t("settings.providers.account.removed.description", { provider: input.provider }),
        }),
      )
      .catch((error) => fail(formatServerError(error, language.t)))

  const rename = (account: ProviderAccount, label: string) =>
    sdk.api.credential
      .update({ credentialID: account.id, label })
      .then(refresh)
      .then(() => true)
      .catch((error) => {
        fail(formatServerError(error, language.t))

        return false
      })

  return { refresh, activate, remove, rename }
}

import { InlineInput } from "@opencode/ui/inline-input"
import { onMount } from "solid-js"
import { createStore } from "solid-js/store"
import { useLanguage } from "@/runtime/i18n/language"

export function AccountNameInput(props: {
  value: string
  class?: string
  onSave: (label: string) => Promise<boolean>
  onClose: () => void
}) {
  const language = useLanguage()
  const [store, setStore] = createStore({ draft: props.value, saving: false, cancelled: false })
  let input: HTMLInputElement | undefined

  // Waits a frame so a closing menu's focus restore cannot pull focus back out of the field.
  onMount(() =>
    requestAnimationFrame(() => {
      input?.focus()
      input?.select()
    }),
  )

  const save = async () => {
    const label = store.draft.trim()

    if (!label || label === props.value) return props.onClose()
    setStore("saving", true)

    if (await props.onSave(label)) return props.onClose()
    setStore("saving", false)
    requestAnimationFrame(() => input?.focus())
  }

  return (
    <InlineInput
      ref={input}
      aria-label={language.t("settings.providers.account.name")}
      dir="auto"
      value={store.draft}
      disabled={store.saving}
      class={`field-sizing-content rounded-[6px] px-1 py-1 ${props.class ?? ""}`}
      style={{ "--inline-input-shadow": "none", "text-align": "start" }}
      onInput={(event) => setStore("draft", event.currentTarget.value)}
      data-owns-escape
      onKeyDown={(event) => {
        event.stopPropagation()

        if (event.isComposing || event.keyCode === 229) return

        if (event.key === "Enter") {
          event.preventDefault()
          void save()

          return
        }

        if (event.key !== "Escape") return
        event.preventDefault()
        setStore("cancelled", true)
        props.onClose()
      }}
      // Like session title editing, clicking away keeps the typed name.
      onBlur={() => {
        if (!store.saving && !store.cancelled) void save()
      }}
    />
  )
}

import type { ConnectionInfo, IntegrationInfo } from "@opencode/client/promise"

export type ProviderAccount = Extract<ConnectionInfo, { type: "credential" }>

export function providerAccounts(integration: IntegrationInfo | undefined) {
  return integration?.connections.filter((connection): connection is ProviderAccount => connection.type === "credential") ?? []
}

export function activeProviderAccount(integration: IntegrationInfo | undefined) {
  return providerAccounts(integration)[0]
}

import { Button } from "@opencode/ui/button"
import { Badge } from "@opencode/ui/badge"
import { useDialog } from "@opencode/ui/context/dialog"
import { Icon } from "@opencode/ui/icon"
import { IconButton } from "@opencode/ui/icon-button"
import { Menu } from "@opencode/ui/menu"
import { OpenCodeLogo } from "@/providers/opencode-logo"
import { showToast } from "@/shell/notifications/toast"
import { popularProviders, useProviders } from "@/providers/catalog/providers"
import { consoleProviderGroup } from "@/providers/catalog/console"
import { useIntegrations } from "@/providers/catalog/integrations"
import { createEffect, createMemo, type Component, For, Show } from "solid-js"
import { createStore, reconcile } from "solid-js/store"
import { useLanguage } from "@/runtime/i18n/language"
import { useServerSDK } from "@/runtime/server/client"
import { formatServerError } from "@/runtime/server/errors"
import { CONSOLE_INTEGRATION, CONSOLE_PROVIDERS } from "@/providers/connect/controller"
import { DialogConnectProvider, useProviderConnectController } from "@/providers/connect/dialog"
import { ProviderModelIcon } from "@/providers/models/provider-group"
import { SettingsList } from "@/settings/list"
import { activeProviderAccount, providerAccounts, type ProviderAccount } from "./accounts"
import { AccountNameInput } from "./account-name"
import { useProviderAccountActions } from "./account-actions"
import "@/settings/settings.css"

type ProviderSource = "env" | "api" | "account" | "config" | "custom"

type ProviderItem = ReturnType<ReturnType<typeof useProviders>["connected"]>[number]

const PROVIDER_NOTES = [
  { match: (id: string) => id === "opencode", key: "dialog.provider.opencode.note" },
  { match: (id: string) => id === "opencode-go", key: "dialog.provider.opencodeGo.tagline" },
  { match: (id: string) => id === "anthropic", key: "dialog.provider.anthropic.note" },
  { match: (id: string) => id.startsWith("github-copilot"), key: "dialog.provider.copilot.note" },
  { match: (id: string) => id === "openai", key: "dialog.provider.openai.note" },
  { match: (id: string) => id === "google", key: "dialog.provider.google.note" },
  { match: (id: string) => id === "openrouter", key: "dialog.provider.openrouter.note" },
  { match: (id: string) => id === "vercel", key: "dialog.provider.vercel.note" },
] as const

export const SettingsProviders: Component<{
  directory: string | undefined
  onSelectProvider?: (providerID: string) => void
}> = (props) => {
  const dialog = useDialog()
  const language = useLanguage()
  const serverSdk = useServerSDK()
  const providers = useProviders(() => props.directory)
  const integrations = useIntegrations(() => props.directory)
  const providerConnect = useProviderConnectController()
  const accountActions = useProviderAccountActions(() => props.directory)

  const [state, setState] = createStore<{
    disconnecting: Record<string, "removing" | "removed" | "absent" | undefined>
    consoleExpanded: boolean
    credentialID?: string
    renaming?: string
    held?: ProviderItem[]
  }>({
    disconnecting: {},
    consoleExpanded: false,
  })

  const updateDisconnecting = (ids: string[], status: "removing" | "removed" | "absent" | undefined) =>
    setState("disconnecting", (current) => ({
      ...current,
      ...Object.fromEntries(ids.map((id) => [id, status])),
    }))

  // Console-managed providers (`opencode-go`, `console-*`) connect through the `opencode`
  // integration, so the lookup must follow `integrationID` rather than the provider id.
  const integration = (item: ProviderItem) => {
    const id = item.integrationID ?? item.id

    return integrations.list().find((entry) => entry.id === id)
  }

  const connect = (provider?: string) => {
    // The list stays as it was while the dialog connects, so a new sign-in that briefly drops the
    // Console workspace providers from the catalog can't flash rows behind the dialog.
    setState("held", available())
    providerConnect.select(provider)
    void dialog.show(
      () => (
        <DialogConnectProvider
          directory={props.directory}
          defaultLocation={props.directory === undefined}
          controller={providerConnect}
          onConnected={(providerID) => {
            if (CONSOLE_PROVIDERS.has(providerID)) {
              setState("disconnecting", reconcile({}))

              return
            }

            setState("disconnecting", providerID, undefined)
          }}
        />
      ),
      () => void accountActions
          .refresh()
          .catch(() => undefined)
          .finally(() => setState("held", undefined)),
    )
  }

  const available = createMemo(() => {
    if (state.held) return state.held
    const connected = providers.connected()
    const managedConsole = consoleProviderGroup(connected)

    const consoleConnected = integrations
      .list()
      .find((item) => item.id === CONSOLE_INTEGRATION)
      ?.connections.some((connection) => connection.type === "credential" || connection.type === "env")

    return connected
      .filter(
        (provider) =>
          provider.id !== "opencode" ||
          managedConsole !== undefined ||
          consoleConnected ||
          Object.values(provider.models).some((model) => model.cost.input > 0),
      )
      .toSorted((a, b) => Number(b.id === "opencode-go") - Number(a.id === "opencode-go"))
  })

  createEffect(() => {
    const ids = new Set(available().map((item) => item.id))
    Object.entries(state.disconnecting).forEach(([id, status]) => {
      if ((status === "removing" || status === "removed") && !ids.has(id)) {
        setState("disconnecting", id, "absent")

        return
      }

      if (status === "absent" && ids.has(id)) setState("disconnecting", id, undefined)
    })
  })

  const connected = createMemo(() => available().filter((item) => !state.disconnecting[item.id]))

  const consoleGroup = createMemo(() => consoleProviderGroup(available()))

  const displayed = createMemo(() => {
    const group = consoleGroup()

    if (!group) return connected()
    const grouped = new Set(group.providers.filter((item) => item.id !== group.root.id).map((item) => item.id))

    return connected().filter((item) => !grouped.has(item.id))
  })

  const popular = createMemo(() => {
    const connectedIDs = new Set(connected().map((p) => p.id))
    // The Console account (integration `opencode`) shares its id with the Zen provider. A stored API
    // key, including one imported from a v1 auth.json, makes Zen "connected" without any account, so
    // the Popular list keeps the sign-in row until the active credential is an OAuth grant. Until the
    // integration list arrives the row is still the models.dev Zen provider, so dedupe it as before.
    const account = integrations.list().find((entry) => entry.id === CONSOLE_INTEGRATION)

    const items = providers
      .popular()
      .filter((p) => {
        if (p.id !== CONSOLE_INTEGRATION || !account) return !connectedIDs.has(p.id)

        return account.connections.find((connection) => connection.type === "credential")?.method !== "oauth"
      })
      .slice()

    items.sort((a, b) => popularProviders.indexOf(a.id) - popularProviders.indexOf(b.id))

    return items
  })

  // Connection state comes from the integration list like the TUI: credential
  // connections mean an API key or OAuth grant, env connections mean detected
  // environment variables, and a connectionless integration is config-provided.
  const source = (item: ProviderItem): ProviderSource | undefined => {
    const current = integration(item)
    const credential = current?.connections.find((connection) => connection.type === "credential")

    if (credential) return credential.method === "oauth" ? "account" : "api"

    if (current?.connections.some((connection) => connection.type === "env")) return "env"

    if (current) return "config"

    if (!("source" in item)) return
    const value = item.source

    if (value === "env" || value === "api" || value === "config" || value === "custom") return value

    return
  }

  const type = (item: ProviderItem) => {
    const current = source(item)

    if (current === "env") return language.t("settings.providers.tag.environment")

    if (current === "api") return language.t("provider.connect.method.apiKey")

    if (current === "account") return language.t("settings.providers.tag.account")

    if (current === "config") return language.t("settings.providers.tag.config")

    if (current === "custom") return language.t("settings.providers.tag.custom")

    return language.t("settings.providers.tag.other")
  }

  const canDisconnect = (item: ProviderItem) => {
    const current = integration(item)

    if (current) return current.connections.some((connection) => connection.type === "credential")
    const currentSource = source(item)

    return currentSource !== "env" && currentSource !== "config"
  }

  const canManageAccounts = (item: ProviderItem) => providerAccounts(integration(item)).length > 0

  const note = (id: string) => PROVIDER_NOTES.find((item) => item.match(id))?.key

  const disconnect = async (item: ProviderItem, name: string) => {
    if (state.disconnecting[item.id]) return
    const group = consoleGroup()
    const ids = group?.root.id === item.id ? group.providers.map((provider) => provider.id) : [item.id]
    updateDisconnecting(ids, "removing")
    const location = props.directory ? { directory: props.directory } : undefined
    await serverSdk.api.integration
      .get({ integrationID: item.integrationID ?? item.id, location })
      .then(async (integration) => {
        const credentials = integration.data?.connections.filter((item) => item.type === "credential") ?? []

        if (credentials.length === 0) {
          showToast({
            title: language.t("common.requestFailed"),
            description: language.t("provider.disconnect.toast.noCredentials.description", { provider: name }),
          })

          return
        }

        await Promise.all(
          credentials.map((credential) => serverSdk.api.credential.remove({ credentialID: credential.id })),
        )
        updateDisconnecting(ids, "removed")
        showToast({
          variant: "success",
          icon: "circle-check",
          title: language.t("provider.disconnect.toast.disconnected.title", { provider: name }),
          description: language.t("provider.disconnect.toast.disconnected.description", { provider: name }),
        })
      })
      .catch((err) => {
        updateDisconnecting(ids, undefined)
        const message = formatServerError(err, language.t)
        showToast({
          title: language.t("common.requestFailed"),
          description: language.tDynamic("provider.disconnect.toast.failed.description", message, { provider: name }),
        })
      })
  }

  const activate = async (provider: ProviderItem, providerName: string, account: ProviderAccount) => {
    if (activeProviderAccount(integration(provider))?.id === account.id) return
    setState({ credentialID: account.id, held: available() })
    await accountActions.activate({ integrationID: provider.integrationID ?? provider.id, provider: providerName, account })
    setState({ credentialID: undefined, held: undefined })
  }

  const remove = async (provider: ProviderItem, providerName: string, account: ProviderAccount) => {
    setState({ credentialID: account.id, held: available() })
    await accountActions.remove({
      integrationID: provider.integrationID ?? provider.id,
      provider: providerName,
      account,
      final: providerAccounts(integration(provider)).length === 1,
    })
    setState({ credentialID: undefined, held: undefined })
  }

  function AccountMenu(menuProps: { provider: ProviderItem; name?: string }) {
    const accounts = () => providerAccounts(integration(menuProps.provider))
    const active = () => activeProviderAccount(integration(menuProps.provider))
    const name = () => menuProps.name ?? menuProps.provider.name
    const renaming = () => accounts().find((account) => account.id === state.renaming)

    return (
      <Show
        when={renaming()}
        fallback={
          <AccountMenuTrigger provider={menuProps.provider} name={name()} accounts={accounts()} active={active()} />
        }
      >
        {(account) => (
          <AccountNameInput
            value={account().label}
            class="settings-provider-account-input"
            onSave={(label) => accountActions.rename(account(), label)}
            onClose={() => setState("renaming", undefined)}
          />
        )}
      </Show>
    )
  }

  function AccountMenuTrigger(menuProps: {
    provider: ProviderItem
    name: string
    accounts: ProviderAccount[]
    active: ProviderAccount | undefined
  }) {
    const accounts = () => menuProps.accounts
    const active = () => menuProps.active
    const name = () => menuProps.name

    return (
      <div class="settings-provider-account-actions">
        <Menu placement="bottom-end" gutter={6}>
          <Menu.Trigger
            as={Button}
            size="normal"
            variant="ghost-muted"
            class="settings-provider-account-trigger"
            aria-label={language.t("settings.providers.account.manage", { provider: name() })}
          >
            <span>{active()?.label}</span>
            <Icon name="chevron-down" size="small" />
          </Menu.Trigger>
          <Menu.Portal>
            <Menu.Content class="settings-provider-account-menu" onEscapeKeyDown={(event) => event.stopPropagation()}>
              <Menu.Group>
                <Menu.GroupLabel>{language.t("settings.providers.account.group")}</Menu.GroupLabel>
                <Menu.RadioGroup
                  class="settings-provider-account-list"
                  value={active()?.id}
                  onChange={(credentialID) => {
                    const account = accounts().find((item) => item.id === credentialID)

                    if (account) void activate(menuProps.provider, name(), account)
                  }}
                >
                  <For each={accounts()}>
                    {(account) => (
                      <Menu.RadioItem value={account.id} closeOnSelect disabled={state.credentialID !== undefined}>
                        <span class="settings-provider-account-label">{account.label}</span>
                      </Menu.RadioItem>
                    )}
                  </For>
                </Menu.RadioGroup>
              </Menu.Group>
              <Menu.Separator />
              <Menu.Item disabled={state.credentialID !== undefined} onSelect={() => connect(menuProps.provider.id)}>
                <Icon name="plus" size="small" class="shrink-0" />
                {language.t("settings.providers.account.add")}
              </Menu.Item>
            </Menu.Content>
          </Menu.Portal>
        </Menu>
        <Menu placement="bottom-end" gutter={6}>
          <Menu.Trigger
            as={IconButton}
            variant="ghost-muted"
            size="large"
            icon={<Icon name="outline-dots" />}
            disabled={state.credentialID !== undefined || !active()}
            aria-label={language.t("dialog.provider.accounts.options", { account: active()?.label ?? "" })}
          />
          <Menu.Portal>
            <Menu.Content onCloseAutoFocus={(event) => state.renaming && event.preventDefault()}>
              <Menu.Item onSelect={() => setState("renaming", active()?.id)}>
                {language.t("common.rename")}
              </Menu.Item>
              <Menu.Item
                onSelect={() => {
                  const account = active()

                  if (account) void remove(menuProps.provider, name(), account)
                }}
              >
                {language.t("dialog.provider.accounts.remove")}
              </Menu.Item>
            </Menu.Content>
          </Menu.Portal>
        </Menu>
      </div>
    )
  }

  return (
    <>
      <div class="settings-tab-header">
        <div class="settings-tab-header-row">
          <div class="flex flex-col gap-1">
            <h2 class="settings-tab-title">{language.t("settings.providers.title")}</h2>
            <span class="text-11-regular text-v2-text-text-muted">{language.t("settings.providers.description")}</span>
          </div>
        </div>
      </div>

      <div class="settings-tab-body settings-tab-body--sectioned settings-providers">
        <div class="settings-section" data-component="connected-providers-section">
          <h3 class="settings-section-title">{language.t("settings.providers.section.connected")}</h3>
          <SettingsList variant="catalog">
            <Show
              when={displayed().length > 0}
              fallback={<div class="settings-provider-empty">{language.t("settings.providers.connected.empty")}</div>}
            >
              <For each={displayed()}>
                {(item) => {
                  const managedGroup = () => (consoleGroup()?.root.id === item.id ? consoleGroup() : undefined)

                  return (
                    <Show
                      when={managedGroup()}
                      fallback={
                        <div class="settings-provider-row group">
                          <div class="settings-provider-lead">
                            <ProviderModelIcon provider={item} class="settings-provider-icon shrink-0" />

                            <div class="settings-provider-main">
                              <span class="settings-provider-name truncate">
                                {item.name}
                              </span>
                              <Badge>{type(item)}</Badge>
                            </div>
                          </div>
                          <Show
                            when={canManageAccounts(item)}
                            fallback={
                              <Show
                                when={canDisconnect(item)}
                                fallback={
                                  <span class="settings-provider-env-hint">
                                    {language.t("settings.providers.connected.environmentDescription")}
                                  </span>
                                }
                              >
                                <Button
                                  size="normal"
                                  variant="ghost-muted"
                                  onClick={() => void disconnect(item, item.name)}
                                >
                                  {language.t("common.disconnect")}
                                </Button>
                              </Show>
                            }
                          >
                            <AccountMenu provider={item} />
                          </Show>
                        </div>
                      }
                    >
                      {(group) => (
                        <div class="settings-provider-console group">
                          <div class="settings-provider-console-header">
                            <div class="settings-provider-lead">
                              <OpenCodeLogo class="settings-provider-icon size-4 shrink-0" />
                              <div class="settings-provider-console-summary">
                                <div class="settings-provider-main">
                                  <span class="settings-provider-name truncate">
                                    {language.t("provider.connect.opencode.name")}
                                  </span>
                                  <Badge>{group().workspace}</Badge>
                                </div>
                                <Show when={group().providers.length > 1}>
                                  <button
                                    type="button"
                                    class="settings-provider-console-toggle"
                                    aria-expanded={state.consoleExpanded}
                                    onClick={() => setState("consoleExpanded", (value) => !value)}
                                  >
                                    <span>
                                      {language.plural(
                                        "settings.providers.console.available",
                                        group().providers.length,
                                        { count: group().providers.length },
                                      )}
                                    </span>
                                    <Icon
                                      name="chevron-right"
                                      size="small"
                                      classList={{
                                        "settings-provider-console-chevron": true,
                                        open: state.consoleExpanded,
                                      }}
                                    />
                                  </button>
                                </Show>
                              </div>
                            </div>
                            <Show
                              when={canManageAccounts(item)}
                              fallback={
                                <Button
                                  size="normal"
                                  variant="ghost-muted"
                                  onClick={() => void disconnect(item, language.t("provider.connect.opencode.name"))}
                                >
                                  {language.t("common.disconnect")}
                                </Button>
                              }
                            >
                              <AccountMenu provider={item} name={language.t("provider.connect.opencode.name")} />
                            </Show>
                          </div>
                          <Show when={state.consoleExpanded}>
                            <div class="settings-provider-console-list">
                              <div class="settings-provider-console-separator" aria-hidden="true" />
                              <For each={group().providers}>
                                {(provider) => (
                                  <button
                                    type="button"
                                    class="settings-provider-console-item"
                                    onClick={() => props.onSelectProvider?.(provider.id)}
                                  >
                                    <span>{provider.name.slice(group().prefix.length)}</span>
                                    <Icon
                                      name="chevron-right"
                                      size="small"
                                      class="settings-provider-console-item-chevron"
                                    />
                                  </button>
                                )}
                              </For>
                            </div>
                          </Show>
                        </div>
                      )}
                    </Show>
                  )
                }}
              </For>
            </Show>
          </SettingsList>
        </div>

        <div class="settings-section">
          <h3 class="settings-section-title">{language.t("settings.providers.section.popular")}</h3>
          <SettingsList variant="catalog">
            <For each={popular()}>
              {(item) => (
                <div class="settings-provider-row">
                  <div class="settings-provider-lead">
                    <ProviderModelIcon provider={item} class="settings-provider-icon shrink-0" />

                    <div class="settings-provider-copy">
                      <div class="settings-provider-main">
                        <span class="settings-provider-name">
                          {item.name}
                        </span>
                        <Show when={item.id === "opencode" || item.id === "opencode-go"}>
                          <Badge>{language.t("dialog.provider.tag.recommended")}</Badge>
                        </Show>
                      </div>
                      <Show when={note(item.id)}>
                        {(key) => <p class="settings-provider-description">{language.t(key())}</p>}
                      </Show>
                    </div>
                  </div>
                  <Button size="normal" variant="neutral" icon="plus" onClick={() => connect(item.id)}>
                    {language.t("common.connect")}
                  </Button>
                </div>
              )}
            </For>
          </SettingsList>

          <button type="button" class="settings-providers-view-all" onClick={() => connect()}>
            {language.t("dialog.provider.viewAll")}
          </button>
        </div>
      </div>
    </>
  )
}

import { describe, expect, test } from "bun:test"
import { parseSettingsView, settingsViewRedirect, settingsViewUrl, type SettingsView } from "./route"

describe("settings route", () => {
  test("keeps root preferences at the canonical route", () => {
    expect(settingsViewUrl({ type: "root", tab: "general" })).toBe("/settings")
    expect(parseSettingsView("", false)).toEqual({ type: "root", tab: "general", subtab: undefined })
  })

  test("round trips root, server, and project pages", () => {
    const root: SettingsView = { type: "root", tab: "appearance" }
    const server: SettingsView = { type: "server", server: "wsl:Debian", tab: "models" }

    const project: SettingsView = {
      type: "project",
      server: "local",
      project: "C:\\work folder",
      parent: "server",
      tab: "extensions",
      subtab: "skills",
    }

    expect(parseSettingsView(new URL(settingsViewUrl(root), "http://localhost").search, false)).toEqual({
      ...root,
      subtab: undefined,
    })
    expect(parseSettingsView(new URL(settingsViewUrl(server), "http://localhost").search, true)).toEqual({
      ...server,
      subtab: undefined,
    })
    expect(parseSettingsView(new URL(settingsViewUrl(project), "http://localhost").search, true)).toEqual(project)
  })

  test("derives project ancestry and keeps search reveal state transient", () => {
    expect(
      parseSettingsView("?server=local&project=%2Fwork&tab=extensions&subtab=plugins", false, {
        target: "settings-plugin",
        searchActivation: 2,
      }),
    ).toEqual({
      type: "project",
      server: "local",
      project: "/work",
      parent: "root",
      tab: "extensions",
      subtab: "plugins",
      target: "settings-plugin",
      searchActivation: 2,
    })
  })

  test("keeps a restored server page until the server lists load", () => {
    const view: SettingsView = { type: "server", server: "wsl:Debian", tab: "models" }
    const local = { key: "local", connected: true, starting: false }
    const wsl = { key: "wsl:Debian", connected: false, starting: true }

    expect(settingsViewRedirect({ view, loaded: false, servers: [local] })).toBeUndefined()
    expect(settingsViewRedirect({ view, loaded: true, servers: [local, wsl] })).toBeUndefined()
    expect(settingsViewRedirect({ view, loaded: true, servers: [local] })).toEqual({ type: "back" })
  })

  test("keeps a project page while its server starts", () => {
    const view: SettingsView = {
      type: "project",
      server: "wsl:Debian",
      project: "/work",
      parent: "server",
      tab: "general",
    }

    const local = { key: "local", connected: true, starting: false }

    expect(
      settingsViewRedirect({
        view,
        loaded: true,
        servers: [local, { key: "wsl:Debian", connected: false, starting: true }],
      }),
    ).toBeUndefined()
    expect(
      settingsViewRedirect({
        view,
        loaded: true,
        servers: [local, { key: "wsl:Debian", connected: false, starting: false }],
      }),
    ).toEqual({ type: "server", server: "wsl:Debian" })
  })

  test("moves a single server's page to the root settings", () => {
    const local = { key: "local", connected: true, starting: false }
    expect(
      settingsViewRedirect({
        view: { type: "server", server: "local", tab: "general" },
        loaded: true,
        servers: [local],
      }),
    ).toEqual({ type: "root", tab: "servers" })
    expect(
      settingsViewRedirect({
        view: { type: "server", server: "local", tab: "models" },
        loaded: true,
        servers: [local],
      }),
    ).toEqual({ type: "root", tab: "models" })
  })

  test("falls back for invalid scope and tab combinations", () => {
    expect(parseSettingsView("?tab=unknown", false)).toEqual({ type: "root", tab: "general" })
    expect(parseSettingsView("?project=%2Fwork&tab=extensions", false)).toEqual({ type: "root", tab: "general" })
    expect(parseSettingsView("?server=local&tab=about", true)).toEqual({ type: "root", tab: "general" })
    expect(parseSettingsView("?tab=toString", false)).toEqual({ type: "root", tab: "general" })
    expect(parseSettingsView("?tab=extensions&subtab=toString", false)).toEqual({
      type: "root",
      tab: "extensions",
      subtab: undefined,
    })
    expect(parseSettingsView("?tab=extensions&subtab=lsps", false)).toEqual({
      type: "root",
      tab: "extensions",
      subtab: undefined,
    })
  })
})

export type SettingsRootTab =
  | "general"
  | "appearance"
  | "notifications"
  | "shortcuts"
  | "projects"
  | "workspaces"
  | "providers"
  | "models"
  | "extensions"
  | "servers"
  | "experimental"
  | "gui-extensions"
  | "about"

declare const extensionTab: unique symbol

/** A root page a GUI extension contributes; the value is its SettingsPage id. */
export type SettingsExtensionTab = string & { readonly [extensionTab]: true }

export type SettingsServerTab = "general" | "projects" | "workspaces" | "providers" | "models" | "extensions"

export type SettingsProjectTab = "general" | "workspaces" | "extensions"

type SettingsViewState = {
  target?: string
  subtab?: "mcps" | "plugins" | "skills" | "lsps"
  searchActivation?: number
}

type SettingsNestedView =
  | { type: "server"; server: string; tab: SettingsServerTab }
  | {
      type: "project"
      server: string
      project: string
      tab: SettingsProjectTab
      parent: "root" | "server"
    }

export type SettingsView = ({ type: "root"; tab: SettingsRootTab | SettingsExtensionTab } | SettingsNestedView) &
  SettingsViewState

/** A view of a page the host owns. */
export type SettingsHostView = ({ type: "root"; tab: SettingsRootTab } | SettingsNestedView) & SettingsViewState

export type SettingsTransientView = Pick<SettingsView, "target" | "searchActivation">

const rootTabs: Record<SettingsRootTab, true> = {
  general: true,
  appearance: true,
  notifications: true,
  shortcuts: true,
  projects: true,
  workspaces: true,
  providers: true,
  models: true,
  extensions: true,
  servers: true,
  experimental: true,
  "gui-extensions": true,
  about: true,
}

const serverTabs: Record<SettingsServerTab, true> = {
  general: true,
  projects: true,
  workspaces: true,
  providers: true,
  models: true,
  extensions: true,
}

const projectTabs: Record<SettingsProjectTab, true> = {
  general: true,
  workspaces: true,
  extensions: true,
}

const subtabs: Record<NonNullable<SettingsView["subtab"]>, true> = {
  mcps: true,
  plugins: true,
  skills: true,
  lsps: true,
}

export function parseSettingsView(
  search: string,
  multipleServers: boolean,
  transient?: SettingsTransientView,
  extensionTabs?: ReadonlySet<string>,
): SettingsView {
  const params = new URLSearchParams(search)
  const tab = params.get("tab") ?? "general"
  const server = params.get("server")
  const project = params.get("project")
  const subtab = params.get("subtab")
  const nested = subtab && isSubtab(subtab) && tab === "extensions" ? subtab : undefined

  if (project && server && isProjectTab(tab)) {
    return {
      type: "project",
      server,
      project,
      parent: multipleServers ? "server" : "root",
      tab,
      subtab: nested,
      ...transient,
    }
  }

  if (!project && server && isServerTab(tab))
    return { type: "server", server, tab, subtab: nested === "lsps" ? undefined : nested, ...transient }

  if (!project && !server && isRootTab(tab))
    return { type: "root", tab, subtab: nested === "lsps" ? undefined : nested, ...transient }

  if (!project && !server && extensionTabs && isExtensionTab(tab, extensionTabs))
    return { type: "root", tab, subtab: undefined, ...transient }

  return { type: "root", tab: "general", ...transient }
}

export function settingsViewUrl(view: SettingsView) {
  const params = new URLSearchParams()

  if (view.type !== "root") params.set("server", view.server)

  if (view.type === "project") params.set("project", view.project)

  if (view.tab !== "general") params.set("tab", view.tab)

  if (view.tab === "extensions" && view.subtab) params.set("subtab", view.subtab)
  const search = params.toString()

  return search ? `/settings?${search}` : "/settings"
}

type RedirectServer = { key: string; connected: boolean; starting: boolean }

/** Where a server or project view must go when its server is gone, unreachable, or the only one. */
export function settingsViewRedirect(input: {
  view: SettingsView
  /** False while the saved, WSL, and SSH server lists load; a restored route waits for them. */
  loaded: boolean
  servers: readonly RedirectServer[]
}): { type: "back" } | { type: "server"; server: string } | { type: "root"; tab: SettingsRootTab } | undefined {
  const view = input.view

  if (view.type === "root" || !input.loaded) return
  const server = input.servers.find((item) => item.key === view.server)

  if (!server) return { type: "back" }

  // A starting WSL or SSH server connects shortly; only an unavailable one leaves the project page.
  if (view.type === "project" && !server.connected && !server.starting) return { type: "server", server: server.key }

  if (view.type === "server" && input.servers.length === 1)
    return { type: "root", tab: view.tab === "general" ? "servers" : view.tab }
}

export function isRootTab(value: string): value is SettingsRootTab {
  return Object.hasOwn(rootTabs, value)
}

/** Host tabs win over an extension page with the same id. */
export function isExtensionTab(value: string, tabs: ReadonlySet<string>): value is SettingsExtensionTab {
  return !isRootTab(value) && tabs.has(value)
}

export function isServerTab(value: string): value is SettingsServerTab {
  return Object.hasOwn(serverTabs, value)
}

export function isProjectTab(value: string): value is SettingsProjectTab {
  return Object.hasOwn(projectTabs, value)
}

function isSubtab(value: string): value is NonNullable<SettingsView["subtab"]> {
  return Object.hasOwn(subtabs, value)
}

