import { describe, expect, test } from "bun:test"
import type { ConfigEntry } from "@opencode/client/promise"
import { configuredLanguageServers } from "./project-lsp"

const global: ConfigEntry = {
  type: "document",
  path: "/config/opencode.json",
  info: {
    lsp: {
      typescript: { command: ["typescript-language-server", "--stdio"], extensions: [".ts", ".tsx"] },
      eslint: { disabled: true },
    },
  },
}

describe("configuredLanguageServers", () => {
  test("merges inherited entries and project overrides by name", () => {
    expect(
      configuredLanguageServers([
        global,
        { type: "directory", path: "/project/.opencode" },
        {
          type: "document",
          path: "/project/opencode.jsonc",
          info: {
            lsp: {
              typescript: { disabled: true },
              eslint: { command: ["eslint-lsp"], disabled: false, extensions: [".js"] },
              rust: { command: ["rust-analyzer"], extensions: [".rs"] },
            },
          },
        },
      ]),
    ).toEqual({
      disabled: false,
      servers: [
        { name: "eslint", disabled: false, extensions: [".js"] },
        { name: "rust", disabled: false, extensions: [".rs"] },
        { name: "typescript", disabled: true, extensions: [".ts", ".tsx"] },
      ],
    })
  })

  test("does not invent servers for omitted or boolean-only configuration", () => {
    expect(configuredLanguageServers([])).toEqual({ disabled: false, servers: [] })
    expect(configuredLanguageServers([global, { type: "document", info: { lsp: false } }])).toEqual({
      disabled: true,
      servers: [],
    })
    expect(configuredLanguageServers([global, { type: "document", info: { lsp: true } }])).toEqual({
      disabled: false,
      servers: [],
    })
  })

  test("allows named configuration after a disabled parent without reviving earlier entries", () => {
    expect(
      configuredLanguageServers([
        global,
        { type: "document", info: { lsp: false } },
        { type: "document", info: { lsp: { custom: { command: ["custom-lsp"] } } } },
      ]),
    ).toEqual({ disabled: false, servers: [{ name: "custom", disabled: false, extensions: [] }] })
  })
})

import type { ConfigEntry } from "@opencode/client/promise"

type ConfiguredServer = { name: string; disabled: boolean; extensions: readonly string[] }

export function configuredLanguageServers(entries: readonly ConfigEntry[]) {
  const state = entries.reduce(
    (state, entry) => {
      if (entry.type !== "document" || entry.info.lsp === undefined) return state
      const config = entry.info.lsp

      // A boolean replaces the object form, so earlier named entries no longer apply.
      if (typeof config === "boolean") return { disabled: !config, servers: new Map<string, ConfiguredServer>() }
      Object.entries(config).forEach(([name, server]) => {
        const previous = state.servers.get(name)
        state.servers.set(name, {
          name,
          disabled: server.disabled ?? previous?.disabled ?? false,
          extensions: ("extensions" in server ? server.extensions : undefined) ?? previous?.extensions ?? [],
        })
      })

      return { disabled: false, servers: state.servers }
    },
    { disabled: false, servers: new Map<string, ConfiguredServer>() },
  )

  return {
    disabled: state.disabled,
    servers: [...state.servers.values()].sort((a, b) => a.name.localeCompare(b.name)),
  }
}

import { getFilename } from "@opencode/util/path"
import type { ProjectUpdateInput } from "@opencode/client/promise"
import { createMemo } from "solid-js"
import { createStore } from "solid-js/store"
import { useGlobal } from "@/runtime/server/runtime"
import { useLanguage } from "@/runtime/i18n/language"
import type { LocalProject } from "@/shell/state/layout"
import { ServerConnection } from "@/runtime/server/registry"
import { showToast } from "@/shell/notifications/toast"

type ProjectPatch = Pick<ProjectUpdateInput, "name" | "icon" | "commands">

export function createEditProjectModel(props: { project: LocalProject; server: ServerConnection.Any }) {
  const language = useLanguage()
  const global = useGlobal()
  const serverCtx = createMemo(() => global.ensureServerCtx(props.server))
  const folderName = createMemo(() => getFilename(props.project.worktree))
  const defaultName = createMemo(() => props.project.name || folderName())

  const [store, setStore] = createStore({
    name: defaultName(),
    color: props.project.icon?.color,
    iconOverride: props.project.icon?.override,
    startup: props.project.commands?.start ?? "",
    dragOver: false,
    iconHover: false,
    saving: 0,
  })

  const saved = {
    name: props.project.name ?? "",
    startup: store.startup.trim(),
    color: store.color,
    iconOverride: store.iconOverride,
  }

  let iconInput: HTMLInputElement | undefined
  let queue = Promise.resolve()

  const persist = (patch: ProjectPatch, complete: () => void) => {
    setStore("saving", (value) => value + 1)
    queue = queue
      .then(async () => {
        if (props.project.id && props.project.id !== "global") {
          const project = await serverCtx().sdk.api.project.update({ projectID: props.project.id, ...patch })
          serverCtx().sync.project.update(project)

          return
        }

        serverCtx().sync.project.meta(props.project.worktree, patch)
      })
      .then(complete)
      .catch((error: unknown) => {
        showToast({
          variant: "error",
          title: language.t("common.requestFailed"),
          description: error instanceof Error ? error.message : language.t("common.requestFailed"),
        })
      })
      .finally(() => setStore("saving", (value) => value - 1))
  }

  const saveName = () => {
    const value = store.name.trim() === folderName() ? "" : store.name.trim()

    // A pending write can change the saved value, so reverting to it must still be queued.
    if (!store.saving && value === saved.name) return
    persist({ name: value }, () => {
      saved.name = value
    })
  }

  const saveStartup = () => {
    const value = store.startup.trim()

    if (!store.saving && value === saved.startup) return
    persist({ commands: { start: value } }, () => {
      saved.startup = value
    })
  }

  const saveIcon = (color = store.color, override = store.iconOverride) => {
    if (!store.saving && color === saved.color && override === saved.iconOverride) return
    persist({ icon: { color: color ?? "", override: override ?? "" } }, () => {
      saved.color = color
      saved.iconOverride = override
    })
  }

  function selectFile(file: File) {
    if (!file.type.startsWith("image/")) return
    const reader = new FileReader()
    reader.onload = (event) => {
      const result = event.target?.result

      if (typeof result !== "string") return
      setStore("iconOverride", result)
      setStore("iconHover", false)
      saveIcon(store.color, result)
    }

    reader.readAsDataURL(file)
  }

  return {
    store,
    setStore,
    folderName,
    defaultName,
    saveName,
    saveStartup,
    setColor(value: string | undefined) {
      setStore("color", value)
      saveIcon(value, store.iconOverride)
    },
    drop(event: DragEvent) {
      event.preventDefault()
      setStore("dragOver", false)
      const file = event.dataTransfer?.files[0]

      if (file) selectFile(file)
    },
    dragOver(event: DragEvent) {
      event.preventDefault()
      setStore("dragOver", true)
    },
    dragLeave() {
      setStore("dragOver", false)
    },
    inputChange(input: HTMLInputElement) {
      const file = input.files?.[0]

      if (file) selectFile(file)
    },
    iconClick() {
      if (store.iconOverride && store.iconHover) {
        setStore("iconOverride", "")
        saveIcon(store.color, "")

        return
      }

      iconInput?.click()
    },
    setIconInput(input: HTMLInputElement) {
      iconInput = input
    },
  }
}

import { Show, type Component } from "solid-js"
import { Icon } from "@opencode/ui/icon"
import { IconButton } from "@opencode/ui/icon-button"
import { Menu } from "@opencode/ui/menu"
import { useLanguage } from "@/runtime/i18n/language"
import { usePlatform } from "@/runtime/platform/platform"
import { useGlobal } from "@/runtime/server/runtime"
import { ServerConnection } from "@/runtime/server/registry"
import type { LocalProject } from "@/shell/state/layout"
import { fileManagerApp } from "@/home/projects/file-manager"
import { useRevealProject } from "@/home/projects/reveal"

export const ProjectOptions: Component<{
  server: ServerConnection.Any
  project: LocalProject
  open?: boolean
  onOpenChange?: (open: boolean) => void
  onEdit?: () => void
  onRename?: () => void
  onClose?: () => void
  class?: string
  size?: "small" | "normal" | "large"
}> = (props) => {
  const language = useLanguage()
  const global = useGlobal()
  const platform = usePlatform()
  const revealProject = useRevealProject()
  const context = () => global.ensureServerCtx(props.server)

  const directories = () => [props.project.worktree, ...(props.project.sandboxes ?? [])]

  const hasUnread = () => directories().some((directory) => context().notification.project.hasUnread(directory))

  const clearNotifications = () => {
    const notification = context().notification
    directories().forEach((directory) => notification.project.markViewed(directory))
  }

  const close = () => {
    context().projects.close(props.project.worktree)
    props.onClose?.()
  }

  return (
    <Menu
      gutter={4}
      modal={false}
      placement="bottom-end"
      open={props.open}
      onOpenChange={props.onOpenChange}
    >
      <Menu.Trigger
        as={IconButton}
        variant="ghost-muted"
        size={props.size ?? "small"}
        class={props.class}
        icon={<Icon name="outline-dots" />}
        aria-label={language.t("common.moreOptions")}
      />
      <Menu.Portal>
        <Menu.Content>
          <Show when={props.onEdit} keyed>
            {(edit) => <Menu.Item onSelect={edit}>{language.t("common.edit")}</Menu.Item>}
          </Show>
          <Show when={props.onRename} keyed>
            {(rename) => <Menu.Item onSelect={rename}>{language.t("common.rename")}</Menu.Item>}
          </Show>
          <Show when={revealProject.available(props.server)}>
            <Menu.Item onSelect={() => revealProject.reveal(props.server, props.project)}>{language.t(fileManagerApp(platform.os ?? "unknown").actionLabel)}</Menu.Item>
          </Show>
          <Menu.Item disabled={!hasUnread()} onSelect={clearNotifications}>
            {language.t("sidebar.project.clearNotifications")}
          </Menu.Item>
          <Menu.Separator />
          <Menu.Item onSelect={close}>{language.t("common.close")}</Menu.Item>
        </Menu.Content>
      </Menu.Portal>
    </Menu>
  )
}

import { Show } from "solid-js"
import { createStore } from "solid-js/store"
import { InlineInput } from "@opencode/ui/inline-input"
import { getFilename } from "@opencode/util/path"
import { useLanguage } from "@/runtime/i18n/language"
import { useGlobal } from "@/runtime/server/runtime"
import { ServerConnection } from "@/runtime/server/registry"
import type { LocalProject } from "@/shell/state/layout"
import { displayName } from "@opencode/ui/project-avatar"
import { errorMessage } from "@/shell/layout/helpers"
import { ProjectIcon } from "@/shell/layout/project-icon"
import { showToast } from "@/shell/notifications/toast"
import { ProjectOptions } from "./project-options"

export function SettingsProjectRow(props: {
  project: LocalProject
  server: ServerConnection.Any
  onOpen: (project: LocalProject) => void
}) {
  const language = useLanguage()
  const global = useGlobal()

  const [store, setStore] = createStore({
    menu: false,
    editor: undefined as { draft: string; saving: boolean } | undefined,
  })

  let button: HTMLButtonElement | undefined
  let input: HTMLInputElement | undefined

  const openEditor = () => {
    setStore("editor", { draft: displayName(props.project), saving: false })
    requestAnimationFrame(() => {
      input?.focus()
      input?.select()
    })
  }

  const closeEditor = () => {
    if (store.editor?.saving) return
    setStore("editor", undefined)
  }

  const saveEditor = async () => {
    if (!store.editor || store.editor.saving) return
    const name = store.editor.draft.trim()

    if (!name || name === displayName(props.project)) {
      closeEditor()
      requestAnimationFrame(() => button?.focus())

      return
    }

    setStore("editor", "saving", true)
    const context = global.ensureServerCtx(props.server)
    const value = name === getFilename(props.project.worktree) ? "" : name

    const saved = await (props.project.id && props.project.id !== "global"
      ? context.sdk.api.project
          .update({ projectID: props.project.id, name: value })
          .then((project) => context.sync.project.update(project))
      : Promise.resolve(context.sync.project.meta(props.project.worktree, { name: value }))
    )
      .then(() => true)
      .catch((cause: unknown) => {
        showToast({
          variant: "error",
          title: language.t("common.requestFailed"),
          description: errorMessage(cause, language.t("common.requestFailed")),
        })

        return false
      })

    const restore = document.activeElement === document.body || document.activeElement === input

    if (saved) setStore("editor", undefined)

    if (!saved) setStore("editor", "saving", false)

    if (!restore) return
    requestAnimationFrame(() => (saved ? button : input)?.focus())
  }

  return (
    <div class="settings-project-row-shell">
      <div
        role="listitem"
        data-component="settings-project-card"
        data-menu={store.menu ? "true" : undefined}
        class="settings-project-card"
      >
        <Show
          when={!store.editor}
          fallback={
            <div class="flex h-full min-w-0 flex-1 items-center gap-2">
              <ProjectIcon project={props.project} class="shrink-0" />
              <InlineInput
                ref={input}
                aria-label={language.t("common.rename")}
                dir="auto"
                value={store.editor?.draft ?? ""}
                disabled={store.editor?.saving}
                class="w-full text-[13px] font-[530] leading-5 tracking-[-0.04px] text-v2-text-text-base outline-none"
                style={{ "--inline-input-shadow": "none", "border-radius": "0", "text-align": "start" }}
                onInput={(event) => setStore("editor", "draft", event.currentTarget.value)}
                onKeyDown={(event) => {
                  event.stopPropagation()

                  if (event.isComposing || event.keyCode === 229) return

                  if (event.key === "Enter") {
                    event.preventDefault()
                    void saveEditor()

                    return
                  }

                  if (event.key !== "Escape") return
                  event.preventDefault()
                  closeEditor()
                  requestAnimationFrame(() => button?.focus())
                }}
                onBlur={closeEditor}
              />
            </div>
          }
        >
          <button
            ref={button}
            type="button"
            aria-label={displayName(props.project)}
            title={props.project.worktree}
            class="flex h-full min-w-0 flex-1 items-center gap-2 rounded-[4px] bg-transparent text-start focus-visible:outline-none focus-visible:[box-shadow:inset_0_0_0_1px_var(--v2-border-border-focus)]"
            onClick={() => props.onOpen(props.project)}
          >
            <ProjectIcon project={props.project} class="shrink-0" />
            <bdi class="truncate text-[13px] font-[530] leading-5 tracking-[-0.04px] text-v2-text-text-base">
              {displayName(props.project)}
            </bdi>
          </button>
          <ProjectOptions
            server={props.server}
            project={props.project}
            open={store.menu}
            onOpenChange={(open) => setStore("menu", open)}
            onEdit={() => props.onOpen(props.project)}
            onRename={openEditor}
          />
        </Show>
      </div>
    </div>
  )
}

