export const SettingsProjects: Component<{
  server: ServerConnection.Any
  active: boolean
  onOpenProject: (project: LocalProject) => void
}> = (props) => {
  const language = useLanguage()
  const global = useGlobal()
  const pickDirectory = useDirectoryPicker()
  const [store, setStore] = createStore({ filter: "" })
  const context = createMemo(() => global.ensureServerCtx(props.server))
  const projects = createMemo(() => settingsProjects(context()))
  const searchable = createMemo(() => projects().length > 7)

  const filtered = createMemo(() => {
    const query = searchable() ? store.filter.trim().toLowerCase() : ""

    return query ? projects().filter((project) => displayName(project).toLowerCase().includes(query)) : projects()
  })

  createEffect(() => {
    if (!searchable()) setStore("filter", "")
  })

  const addProject = () =>
    pickDirectory({
      server: props.server,
      title: language.t("command.project.open"),
      multiple: true,
      onSelect: (result) => {
        const directories = homeProjectDirectories(result)
        const directory = addProjects(context(), directories)

        if (!directory) return

        if (directories.length > 1) return

        const project = context()
          .projects.list()
          .find((item) => item.worktree === directory)

        if (!project) return
        props.onOpenProject(project)
      },
    })

  return (
    <>
      <div class="settings-tab-header" classList={{ "settings-tab-header--stacked": searchable() }}>
        <div class="settings-tab-header-row">
          <div class="flex flex-col gap-1">
            <h2 class="settings-tab-title">{language.t("settings.projects.title")}</h2>
            <span class="text-11-regular text-v2-text-text-muted">{language.t("settings.projects.description")}</span>
          </div>
          <Show when={projects().length > 0}>
            <Button variant="ghost-muted" icon="plus" onClick={addProject}>
              {language.t("home.project.add")}
            </Button>
          </Show>
        </div>
        <Show when={searchable()}>
          <SettingsSearchField
            value={store.filter}
            active={props.active}
            onInput={(value) => setStore("filter", value)}
            placeholder={language.t("settings.projects.search.placeholder")}
          />
        </Show>
      </div>

      <div class="settings-tab-body">
        <Show
          when={filtered().length > 0}
          fallback={
            <Show
              when={!store.filter.trim() && projects().length === 0}
              fallback={
                <Show
                  when={store.filter.trim()}
                  fallback={
                    <div class="py-12 text-center text-v2-text-text-muted text-13-regular">
                      {language.t("settings.projects.empty")}
                    </div>
                  }
                >
                  <div class="settings-tab-search-empty">
                    <SettingsSearchEmpty query={store.filter} />
                  </div>
                </Show>
              }
            >
              <div
                data-component="settings-project-empty-card"
                class="settings-project-empty-card flex flex-col items-center gap-2 py-24 text-center"
              >
                <Icon name="folder" size="large" class="mb-2 text-v2-icon-icon-muted" />
                <div class="text-13-medium text-v2-text-text-base">
                  {language.t("settings.projects.empty.title")}
                </div>
                <div class="text-13-regular text-v2-text-text-muted">
                  {language.t("settings.projects.empty.description")}
                </div>
                <Button variant="neutral" icon="plus" class="mt-6" onClick={addProject}>
                  {language.t("home.project.add")}
                </Button>
              </div>
            </Show>
          }
        >
          <div role="list" class="settings-project-list">
            <Key each={filtered()} by="worktree">
              {(project) => (
                <SettingsProjectRow project={project()} server={props.server} onOpen={props.onOpenProject} />
              )}
            </Key>
          </div>
        </Show>
      </div>
    </>
  )
}

import { queryOptions, useQueryClient, type QueryClient } from "@tanstack/solid-query"
import type { Accessor } from "solid-js"
import type { ServerSDK } from "@/runtime/server/client"
import type { ServerConnection } from "@/runtime/server/registry"
import { useServerCtx, type ServerCtx } from "@/runtime/server/runtime"
import { normalizeProjectInfo } from "@/runtime/server/global-sync/utils"
import { worktreeInventoryViewKey } from "@/workspaces/inventory"

function workspaceProjectsQuery(sdk: ServerSDK) {
  return queryOptions({
    queryKey: [sdk.scope, "settings-workspace-project-metadata"],
    queryFn: () => sdk.api.project.list(),
    staleTime: 30_000,
  })
}

export function workspaceInventoryQuery(
  context: ServerCtx,
  client: QueryClient,
  projectID?: string,
  shouldRefresh = projectID !== undefined,
) {
  return queryOptions({
    queryKey: worktreeInventoryViewKey(context.sdk.scope, projectID),
    queryFn: async () =>
      Promise.all(
        (await client.fetchQuery(workspaceProjectsQuery(context.sdk)))
          .filter((project) => projectID === undefined || project.id === projectID)
          .map(async (project) => {
            const worktrees = (await context.sync.worktrees.list(project.id)) ?? [
              { directory: project.canonical },
              ...project.sandboxes.map((directory) => ({ directory })),
            ]

            if (shouldRefresh) void context.sync.worktrees.refresh(project.id)

            return normalizeProjectInfo({ ...project, worktrees })
          }),
      ),
    staleTime: 30_000,
  })
}

export function useWorkspacesPrefetch(
  server: Accessor<ServerConnection.Any | undefined>,
  projectID?: Accessor<string | undefined>,
) {
  const client = useQueryClient()
  const context = useServerCtx(server)

  return () => {
    const current = context()

    if (!current || current.sdk.connection.status() !== "connected") return
    const project = projectID?.()

    if (project) {
      void client.prefetchQuery(workspaceInventoryQuery(current, client, project, false))

      return
    }

    // Server-level hover warms metadata without booting every project's Location.
    void client.prefetchQuery(workspaceProjectsQuery(current.sdk))
  }
}

import type { Component } from "solid-js"
import { For, Show, createEffect, createMemo, createSignal } from "solid-js"
import { createStore } from "solid-js/store"
import { createResizeObserver } from "@solid-primitives/resize-observer"
import { Key } from "@solid-primitives/keyed"
import type { SessionInfo } from "@opencode/client/promise"
import { useQuery, useQueryClient } from "@tanstack/solid-query"
import { Button } from "@opencode/ui/button"
import { Dialog, DialogFooter, DialogHeader, DialogTitleGroup } from "@opencode/ui/dialog"
import { Icon } from "@opencode/ui/icon"
import { IconButton } from "@opencode/ui/icon-button"
import { Menu } from "@opencode/ui/menu"
import { Tooltip } from "@opencode/ui/tooltip"
import { useDialog } from "@opencode/ui/context/dialog"
import { containsDirectory, getFilename } from "@opencode/util/path"
import { useLanguage } from "@/runtime/i18n/language"
import { useServer } from "@/runtime/server/current"
import { showToast } from "@/shell/notifications/toast"
import { getRelativeTime } from "@/shell/time"
import { sessionLabel } from "@/session/title"
import { pathKey } from "@/workspaces/path-key"
import { worktreeInventoryKey } from "@/workspaces/inventory"
import { SettingsList } from "@/settings/list"
import { useTabs } from "@/shell/tabs/tabs"
import { useHostApis } from "@/runtime/extension/root"
import { ServerConnection } from "@/runtime/server/registry"
import type { Project } from "@/runtime/server/types"
import {
  filterWorkspaceInventory,
  inspectWorkspaceDeletion,
  managedWorkspaceDirectories,
  mergeWorkspaceSessionInventory,
  removeWorkspacesSequentially,
  sessionsForWorkspace,
  type WorkspaceDeleteInspection,
  workspaceInventory,
} from "@/workspaces/paths"
import { listAllSessions } from "@/session/list"
import type { ServerScope } from "@/runtime/server/scope"
import { workspaceInventoryQuery } from "./queries"
import "@/settings/settings.css"

type Workspace = {
  directory: string
  project: Project
}

export const SettingsWorkspaces: Component<{
  activeDirectory?: string
  resetProjectFilter?: () => number
  projectID?: string
}> = (props) => {
  const dialog = useDialog()
  const language = useLanguage()
  const server = useServer()
  const serverSDK = server.ctx.sdk
  const queryClient = useQueryClient()
  const data = server.ctx.data
  const tabs = useTabs()
  const extensions = useHostApis()

  const [store, setStore] = createStore<{
    project: string
    transaction: "confirm" | "running" | undefined
    deleting: string[]
    removing: string[]
  }>({
    project: "all",
    transaction: undefined,
    deleting: [],
    removing: [],
  })

  createEffect(() => {
    if (props.projectID) {
      setStore("project", props.projectID)

      return
    }

    props.resetProjectFilter?.()
    setStore("project", "all")
  })

  const projectQuery = useQuery(() => ({
    ...workspaceInventoryQuery(server.ctx, queryClient, props.projectID),
    enabled: serverSDK.connection.status() === "connected",
    refetchOnMount: true,
  }))

  const inventory = createMemo(() => (projectQuery.isPending ? [] : (projectQuery.data ?? [])))
  const workspaces = createMemo(() => workspaceInventory(inventory()))
  const projects = createMemo(() => inventory().filter((project) => managedWorkspaceDirectories(project).length > 0))
  const projectName = (project: Project) => project.name || getFilename(project.worktree)

  const projectOptions = createMemo(() => [
    { id: "all", label: language.t("settings.workspaces.filter.all") },
    ...projects().map((project) => ({ id: project.id, label: projectName(project) })),
  ])

  const selectedProject = createMemo(() =>
    props.projectID
      ? props.projectID
      : store.project === "all" || projects().some((project) => project.id === store.project)
        ? store.project
        : "all",
  )

  const filtered = createMemo(() => filterWorkspaceInventory(workspaces(), selectedProject()))

  const captureDeleteContext = () => {
    const sdk = serverSDK

    return {
      sdk,
      data,
      server: ServerConnection.key(sdk.server),
      activeDirectory: props.activeDirectory,
    }
  }

  // Fetch sessions per workspace directory instead of paging through every session on the server.
  const loadSessions = async (directories: readonly string[], context = captureDeleteContext()) => {
    const fetched = await Promise.all(
      directories.map((directory) => listAllSessions(context.sdk.api.session, { order: "desc", directory })),
    )

    const sessions = fetched.flat()

    return mergeWorkspaceSessionInventory(sessions, context.data.session.list())
  }

  const workspaceDirectories = createMemo(() => workspaces().map((workspace) => workspace.directory))

  const sessionQuery = useQuery(() => ({
    queryKey: [
      serverSDK.scope,
      null,
      "settings-workspace-sessions",
      workspaceDirectories().map((directory) => String(pathKey(directory))),
    ] as const,
    queryFn: () => loadSessions(workspaceDirectories()),
    enabled: serverSDK.connection.status() === "connected" && workspaceDirectories().length > 0,
    placeholderData: (previous) => previous,
    refetchOnMount: "always",
  }))

  const sessionsByWorkspace = createMemo(() => {
    const sessions = mergeWorkspaceSessionInventory(
      sessionQuery.isPending ? [] : (sessionQuery.data ?? []),
      data.session.list(),
    )

    return new Map(
      workspaces().map((workspace) => [
        pathKey(workspace.directory),
        sessionsForWorkspace(sessions, workspace.directory),
      ]),
    )
  })

  const workspaceSessions = (workspace: Workspace) => sessionsByWorkspace().get(pathKey(workspace.directory)) ?? []

  const workspacesWithoutSessions = createMemo(() => {
    if (sessionQuery.isPending || sessionQuery.isError || sessionQuery.isPlaceholderData) return []

    return filtered().filter((workspace) => workspaceSessions(workspace).length === 0)
  })

  const sessionCount = (workspace: Workspace) => {
    const count = workspaceSessions(workspace).length

    if (!count && sessionQuery.isPending) return language.t("session.messages.loading")

    if (!count && sessionQuery.isError) return language.t("common.requestFailed")

    if (selectedProject() !== "all") return language.plural("settings.workspaces.sessions.filtered", count, { count })
    const project = projectName(workspace.project)

    const label = language.plural("settings.workspaces.sessions", count, {
      count,
      project,
    })

    const start = label.lastIndexOf(project)

    if (start < 0) return label

    return (
      <>
        {label.slice(0, start)}
        <span class="settings-workspaces-meta-project">{project}</span>
        {label.slice(start + project.length)}
      </>
    )
  }

  const lastActive = (workspace: Workspace) => {
    const updated = workspaceSessions(workspace)[0]?.time.updated

    if (!updated) return undefined

    return getRelativeTime(new Date(updated).toISOString(), language.t)
  }

  const sessionTime = (session: SessionInfo) => {
    if (!session.time.updated) return undefined

    return getRelativeTime(new Date(session.time.updated).toISOString(), language.t)
  }

  const inspect = async (workspace: Workspace, context = captureDeleteContext()) => {
    const [working, branch, sessions] = await Promise.all([
      context.sdk.api.vcs.status({ location: { directory: workspace.directory } }),
      context.sdk.api.vcs.diff({ location: { directory: workspace.directory }, mode: "branch" }),
      loadSessions([workspace.directory], context),
    ])

    const result = inspectWorkspaceDeletion({
      workspace: workspace.directory,
      activeDirectory: context.activeDirectory,
      sessions,
      status: working.data.length > 0 || branch.data.length > 0 ? "dirty" : "clean",
    })

    return { result, sessions }
  }

  const inspectionMessages = (result: WorkspaceDeleteInspection) => {
    const messages = [
      result.linked ? language.t("settings.workspaces.delete.blocked.linked") : undefined,
      result.dirty ? language.t("workspace.status.dirty") : undefined,
    ].filter((message): message is string => message !== undefined)

    return messages
  }

  const blocked = (result: WorkspaceDeleteInspection) => {
    showToast({
      variant: "error",
      title: language.t("workspace.delete.failed.title"),
      description: result.active
        ? language.t("settings.workspaces.delete.blocked.active")
        : inspectionMessages(result)[0],
    })
  }

  const remove = async (workspace: Workspace, force = false, context = captureDeleteContext()) => {
    const key = String(pathKey(workspace.directory))
    setStore("deleting", (items) => [...items, key])

    try {
      const preflight = await inspect(workspace, context)

      if (!force && (preflight.result.active || preflight.result.linked || preflight.result.dirty)) {
        blocked(preflight.result)

        return
      }

      const removed = await context.sdk.api.worktree
        .remove({
          projectID: workspace.project.id,
          directory: workspace.directory,
          force,
        })
        .then(() => true)
        .catch((error) => {
          showToast({
            variant: "error",
            title: language.t("workspace.delete.failed.title"),
            description: error instanceof Error ? error.message : language.t("common.requestFailed"),
          })

          return false
        })

      if (!removed) return
      setStore("removing", (items) => [...items, key])
      await new Promise((resolve) => setTimeout(resolve, 150))
      tabs.store.forEach((tab) => {
        if (tab.type !== "draft" || tab.server !== context.server) return
        const directoryMatches = containsDirectory(workspace.directory, tab.directory)
        const worktreeMatches = tab.worktree && containsDirectory(workspace.directory, tab.worktree)

        if (!directoryMatches && !worktreeMatches) return
        tabs.updateDraft(tab.draftID, {
          directory: directoryMatches ? workspace.project.worktree : tab.directory,
          worktree: undefined,
        })
      })
      extensions.workspaceRemoved({ server: context.server, directory: workspace.directory })
      await queryClient.invalidateQueries({
        queryKey: worktreeInventoryKey(context.sdk.scope, workspace.project.id),
      })
      await queryClient.invalidateQueries({ queryKey: [context.sdk.scope, "settings-workspace-inventory"] })
    } finally {
      setStore("deleting", (items) => items.filter((item) => item !== key))
      setStore("removing", (items) => items.filter((item) => item !== key))
    }
  }

  let inspectionID = 0

  const releaseConfirmation = () => {
    if (store.transaction === "confirm") setStore("transaction", undefined)
  }

  const transact = async (task: () => Promise<void>) => {
    if (store.transaction !== "confirm") return
    setStore("transaction", "running")

    try {
      await task()
    } catch (error) {
      showToast({
        variant: "error",
        title: language.t("workspace.delete.failed.title"),
        description: error instanceof Error ? error.message : language.t("common.requestFailed"),
      })
    } finally {
      setStore("transaction", undefined)
    }
  }

  const confirmDelete = (workspace: Workspace) => {
    if (store.transaction) return
    const context = captureDeleteContext()
    const current = ++inspectionID
    setStore("transaction", "confirm")
    void dialog.push(
      () => (
        <DialogDeleteWorkspace
          workspace={workspace}
          scope={context.sdk.scope}
          inspectionID={current}
          inspect={() => inspect(workspace, context)}
          inspectionMessages={inspectionMessages}
          onDelete={() => transact(() => remove(workspace, true, context))}
        />
      ),
      releaseConfirmation,
    )
  }

  const removeAll = async (inventory: Workspace[], context: ReturnType<typeof captureDeleteContext>) => {
    await removeWorkspacesSequentially(inventory, (workspace) => remove(workspace, false, context))
  }

  const confirmDeleteAll = () => {
    if (store.transaction) return
    const context = captureDeleteContext()
    const inventory = [...filtered()]
    setStore("transaction", "confirm")
    void dialog.push(
      () => (
        <DialogDeleteWorkspaces
          title={language.t("settings.workspaces.deleteAll")}
          confirmation={language.plural("settings.workspaces.deleteAll.confirm", inventory.length)}
          warning={language.t("settings.workspaces.deleteAll.warning")}
          onDelete={() => transact(() => removeAll(inventory, context))}
        />
      ),
      releaseConfirmation,
    )
  }

  const confirmDeleteWithoutSessions = () => {
    if (store.transaction || workspacesWithoutSessions().length === 0) return
    const context = captureDeleteContext()
    const inventory = [...workspacesWithoutSessions()]
    setStore("transaction", "confirm")
    void dialog.push(
      () => (
        <DialogDeleteWorkspaces
          title={language.t("settings.workspaces.deleteWithoutSessions")}
          confirmation={language.plural("settings.workspaces.deleteWithoutSessions.confirm", inventory.length)}
          warning={language.t("settings.workspaces.deleteWithoutSessions.warning")}
          onDelete={() => transact(() => removeAll(inventory, context))}
        />
      ),
      releaseConfirmation,
    )
  }

  return (
    <>
      <div class="settings-tab-header settings-workspaces-header">
        <div class="settings-tab-header-row">
          <div class="flex flex-col gap-1">
            <h2 class="settings-tab-title">{language.t("settings.tab.workspaces")}</h2>
            <span class="text-11-regular text-v2-text-text-muted">{language.t("settings.workspaces.description")}</span>
          </div>
        </div>
      </div>

      <div class="settings-tab-body settings-workspaces">
        <Show when={filtered().length > 0}>
          <div class="settings-workspaces-toolbar">
            <span class="settings-section-title">
              {language.plural("settings.workspaces.count", filtered().length)}
            </span>
            <div class="settings-workspaces-toolbar-actions">
              <Show when={!props.projectID && projects().length > 1}>
                <Menu placement="bottom-end" gutter={6}>
                  <Menu.Trigger as={Button} size="small" variant="ghost-muted" class="max-w-48">
                    <span class="min-w-0 truncate">
                      {projectOptions().find((option) => option.id === selectedProject())?.label}
                    </span>
                    <Icon name="chevron-down" size="small" class="shrink-0 text-v2-icon-icon-muted" />
                  </Menu.Trigger>
                  <Menu.Portal>
                    <Menu.Content>
                      <For each={projectOptions()}>
                        {(option) => (
                          <Menu.Item onSelect={() => setStore("project", option.id)}>
                            <span class="min-w-0 flex-1 truncate">{option.label}</span>
                            <Show when={selectedProject() === option.id}>
                              <Icon name="check" size="small" class="shrink-0" />
                            </Show>
                          </Menu.Item>
                        )}
                      </For>
                    </Menu.Content>
                  </Menu.Portal>
                </Menu>
              </Show>
              <Menu placement="bottom-end" gutter={4}>
                <Menu.Trigger
                  as={IconButton}
                  type="button"
                  variant="ghost-muted"
                  size="small"
                  aria-label={language.t("common.moreOptions")}
                  disabled={!!store.transaction}
                  icon={<Icon name="outline-dots" size="small" />}
                />
                <Menu.Portal>
                  <Menu.Content>
                    <Show when={workspacesWithoutSessions().length > 0}>
                      <Menu.Item onSelect={confirmDeleteWithoutSessions}>
                        {language.t("settings.workspaces.deleteWithoutSessions")}
                      </Menu.Item>
                      <Menu.Separator />
                    </Show>
                    <Menu.Item onSelect={confirmDeleteAll}>
                      <span class="settings-workspaces-delete-all">{language.t("settings.workspaces.deleteAll")}</span>
                    </Menu.Item>
                  </Menu.Content>
                </Menu.Portal>
              </Menu>
            </div>
          </div>
        </Show>

        <div class="settings-workspaces-inventory" data-empty={filtered().length === 0}>
          <SettingsList>
            <div class="settings-workspaces-empty-motion" data-visible={filtered().length === 0}>
              <div class="settings-workspaces-empty">
                <Show
                  when={!projectQuery.isPending && !projectQuery.isError}
                  fallback={language.t(projectQuery.isPending ? "common.loading" : "common.requestFailed")}
                >
                  <span class="settings-workspaces-empty-title">{language.t("settings.workspaces.empty")}</span>
                  <span>{language.t("settings.workspaces.empty.description")}</span>
                </Show>
              </div>
            </div>
            <Key each={filtered()} by={(workspace) => `${workspace.project.id}:${pathKey(workspace.directory)}`}>
              {(workspace) => {
                const linked = () => workspaceSessions(workspace())
                const key = () => String(pathKey(workspace().directory))
                const deleting = () => store.deleting.includes(key())

                return (
                  <div class="settings-workspaces-row-motion" data-removing={store.removing.includes(key())}>
                    <div class="settings-workspaces-row">
                      <div class="settings-workspaces-row-header">
                        <div class="settings-workspaces-copy">
                          <div class="settings-workspaces-main">
                            <WorkspacePath directory={workspace().directory} />
                          </div>
                          <span class="settings-workspaces-meta">{sessionCount(workspace())}</span>
                        </div>
                        <div class="settings-workspaces-row-actions">
                          <Show
                            when={deleting()}
                            fallback={
                              <>
                                <Show when={lastActive(workspace())}>
                                  {(value) => (
                                    <Tooltip
                                      value={language.t("settings.workspaces.lastActiveSession")}
                                      placement="top-end"
                                    >
                                      <span tabIndex={0} class="settings-workspaces-active">
                                        {value()}
                                      </span>
                                    </Tooltip>
                                  )}
                                </Show>
                                <IconButton
                                  type="button"
                                  variant="ghost-muted"
                                  size="small"
                                  aria-label={language.t("workspace.delete.confirm", {
                                    name: getFilename(workspace().directory),
                                  })}
                                  disabled={!!store.transaction}
                                  icon={<Icon name="outline-trash" size="small" />}
                                  onClick={() => confirmDelete(workspace())}
                                />
                              </>
                            }
                          >
                            <span class="settings-workspaces-active">{language.t("workspace.lifecycle.deleting")}</span>
                          </Show>
                        </div>
                      </div>
                      <Show when={linked().length > 0}>
                        <div class="settings-workspaces-sessions">
                          <For each={linked()}>
                            {(session) => (
                              <div class="settings-workspaces-session">
                                <span>{sessionLabel(session)}</span>
                                <Show when={linked().length > 1 ? sessionTime(session) : undefined}>
                                  {(time) => <span class="settings-workspaces-session-time">{time()}</span>}
                                </Show>
                              </div>
                            )}
                          </For>
                        </div>
                      </Show>
                    </div>
                  </div>
                )
              }}
            </Key>
          </SettingsList>
        </div>
      </div>
    </>
  )
}

function WorkspacePath(props: { directory: string }) {
  const [truncated, setTruncated] = createSignal(false)
  const name = () => getFilename(props.directory)

  return (
    <Tooltip
      value={props.directory}
      placement="top-start"
      disabled={!truncated()}
      contentClass="max-w-[calc(100vw-32px)] break-all"
    >
      <span
        ref={(element) => createResizeObserver(element, () => setTruncated(element.scrollWidth > element.clientWidth))}
        tabIndex={truncated() ? 0 : undefined}
        dir="ltr"
        aria-label={props.directory}
        class="settings-workspaces-path"
      >
        <span>{props.directory.slice(0, -name().length)}</span>
        <span class="settings-workspaces-path-name">{name()}</span>
      </span>
    </Tooltip>
  )
}

function DialogDeleteWorkspaces(props: {
  title: string
  confirmation: string
  warning: string
  onDelete: () => Promise<void>
}) {
  const dialog = useDialog()
  const language = useLanguage()

  const remove = () => {
    const deleting = props.onDelete()
    dialog.close()
    void deleting
  }

  return (
    <Dialog fit>
      <DialogHeader>
        <DialogTitleGroup
          title={props.title}
          description={
            <div class="flex flex-col gap-2">
              <div>{props.confirmation}</div>
              <div>{props.warning}</div>
            </div>
          }
        />
      </DialogHeader>
      <DialogFooter>
        <Button type="button" variant="neutral" onClick={() => dialog.close()}>
          {language.t("common.cancel")}
        </Button>
        <Button type="button" variant="danger" onClick={remove}>
          {language.t("settings.workspaces.delete.button")}
        </Button>
      </DialogFooter>
    </Dialog>
  )
}

function DialogDeleteWorkspace(props: {
  workspace: Workspace
  scope: ServerScope
  inspectionID: number
  inspect: () => Promise<{ result: WorkspaceDeleteInspection; sessions: SessionInfo[] }>
  inspectionMessages: (result: WorkspaceDeleteInspection) => string[]
  onDelete: () => Promise<void>
}) {
  const dialog = useDialog()
  const language = useLanguage()

  const status = useQuery(() => ({
    queryKey: [props.scope, pathKey(props.workspace.directory), "workspace-delete-status", props.inspectionID] as const,
    queryFn: props.inspect,
    staleTime: 0,
  }))

  const descriptions = () => {
    if (status.isPending) return []

    if (status.isError) return [language.t("workspace.status.error")]

    if (!status.data) return []

    return props.inspectionMessages(status.data.result)
  }

  const remove = () => {
    const deleting = props.onDelete()
    dialog.close()
    void deleting
  }

  return (
    <Dialog fit>
      <DialogHeader>
        <DialogTitleGroup
          title={language.t("workspace.delete.confirm", { name: getFilename(props.workspace.directory) })}
          description={
            <div class="flex flex-col gap-2">
              <div class="flex flex-col gap-1">
                <span class="text-11-regular text-v2-text-text-faint">
                  {language.t(status.isPending ? "workspace.status.checking" : "workspace.delete.location")}
                </span>
                <code class="block w-fit max-w-full rounded-[4px] bg-[color-mix(in_oklch,var(--v2-text-text-base)_8%,transparent)] px-1 py-0.5 font-mono text-xs font-medium leading-4 text-v2-text-text-base break-all">
                  {props.workspace.directory}
                </code>
              </div>
              <div>{language.t("settings.workspaces.delete.warning")}</div>
              <For each={descriptions()}>{(description) => <div>{description}</div>}</For>
            </div>
          }
        />
      </DialogHeader>
      <DialogFooter>
        <Button type="button" variant="neutral" onClick={() => dialog.close()}>
          {language.t("common.cancel")}
        </Button>
        <Button type="button" variant="danger" disabled={status.isPending || status.isError} onClick={remove}>
          {language.t("workspace.delete.button")}
        </Button>
      </DialogFooter>
    </Dialog>
  )
}

import { describe, expect, test } from "bun:test"
import { Schema } from "effect"
import {
  activeCommandRegistrations,
  addCommandRegistration,
  commandPaletteOptions,
  CommandCatalog,
  formatKeybind,
  matchKeybind,
  parseKeybind,
  resolveKeybindOption,
  type CommandOption,
} from "./command"

test("command catalog persistence validates metadata and omits executable fields", () => {
  const decode = Schema.decodeUnknownSync(CommandCatalog)

  const catalog = decode({
    open: { title: "Open", keybind: "mod+o", hidden: false, onSelect: "invalid" },
    shell: { title: "Terminal", section: "terminal" },
    stale: { title: "Stale", section: "removed" },
  })

  expect(catalog).toEqual({
    open: { title: "Open", keybind: "mod+o", hidden: false },
    shell: { title: "Terminal", section: "terminal" },
    stale: { title: "Stale" },
  })
  expect(decode({})).toEqual({})
  expect(() => decode({ open: { title: 1 } })).toThrow()
  expect(decode(Schema.encodeSync(CommandCatalog)(catalog))).toEqual(catalog)
})

test("commandPaletteOptions keeps visible enabled commands", () => {
  const options: CommandOption[] = [
    { id: "settings.open", title: "Open settings" },
    { id: "session.undo", title: "Undo" },
    { id: "suggested.session.undo", title: "Undo" },
    { id: "file.open", title: "Open file" },
    { id: "hidden", title: "Hidden", hidden: true },
    { id: "disabled", title: "Disabled", disabled: true },
  ]

  expect(commandPaletteOptions(options).map((option) => option.id)).toEqual(["settings.open", "session.undo"])
})

test("command registrations shadow keyed owners, restore the previous owner, and keep unkeyed ones additive", () => {
  const one = () => [{ id: "one", title: "One" }]
  const two = () => [{ id: "two", title: "Two" }]

  const registrations = addCommandRegistration([{ key: "layout", options: one }], { key: "layout", options: two })
  expect(registrations).toHaveLength(2)
  expect(activeCommandRegistrations(registrations).map((entry) => entry.options)).toEqual([two])
  expect(
    activeCommandRegistrations(registrations.filter((entry) => entry.options !== two)).map((entry) => entry.options),
  ).toEqual([one])

  const unkeyed = activeCommandRegistrations(addCommandRegistration([{ options: one }], { options: two }))
  expect(unkeyed.map((entry) => entry.options)).toEqual([two, one])
})

test.each([true, false])("resolveKeybindOption prefers a contextual command only in its context: %p", (inside) => {
  const fallback = { id: "tab.close", title: "Close tab" }
  const contextual = { id: "terminal.close", title: "Close terminal", when: () => inside }

  expect(resolveKeybindOption([fallback, contextual], new KeyboardEvent("keydown"))).toBe(
    inside ? contextual : fallback,
  )
})

describe("command keybinds", () => {
  test("parseKeybind handles aliases, multiple combos, and disabled bindings", () => {
    const keybinds = parseKeybind("control+option+k, mod+shift+comma")

    expect(keybinds).toHaveLength(2)
    expect(keybinds[0]).toEqual({ key: "k", ctrl: true, meta: false, shift: false, alt: true })
    expect(keybinds[1]?.shift).toBe(true)
    expect(keybinds[1]?.key).toBe("comma")
    expect(Boolean(keybinds[1]?.ctrl || keybinds[1]?.meta)).toBe(true)
    expect(parseKeybind("none")).toEqual([])
    expect(parseKeybind("")).toEqual([])
  })

  // happy-dom never reports a Mac platform, so mod is Ctrl here.
  test.each([
    { config: "ctrl+comma", event: { key: ",", ctrlKey: true }, match: true },
    { config: "shift+plus", event: { key: "+", shiftKey: true }, match: true },
    { config: "meta+space", event: { key: " ", metaKey: true }, match: true },
    { config: "ctrl+comma", event: { key: ",", ctrlKey: true, altKey: true }, match: false },
    { config: "mod+alt+[", event: { key: "[", ctrlKey: true, altKey: true }, match: true },
    { config: "mod+alt+]", event: { key: "]", ctrlKey: true, altKey: true }, match: true },
    { config: "mod+alt+[", event: { key: "[", metaKey: true, altKey: true }, match: false },
    // macOS Option turns L into ¬; the physical key still matches.
    { config: "meta+alt+l", event: { key: "¬", code: "KeyL", metaKey: true, altKey: true }, match: true },
  ])("matchKeybind $config with $event.key is $match", (row) => {
    expect(matchKeybind(parseKeybind(row.config), new KeyboardEvent("keydown", row.event))).toBe(row.match)
  })

  // IS_MAC is fixed when the module loads, so each assertion accepts either platform's symbols.
  test("formatKeybind returns human readable output for the first combo", () => {
    const display = formatKeybind("ctrl+alt+arrowup")

    expect(display).toContain("↑")
    expect(display.includes("Ctrl") || display.includes("⌃")).toBe(true)
    expect(display.includes("Alt") || display.includes("⌥")).toBe(true)
    expect(formatKeybind("none")).toBe("")
    expect(formatKeybind("mod+k,mod+p")).toContain("K")
    expect(formatKeybind("mod+k,mod+p")).not.toContain("P")
  })
})

import { createSimpleContext } from "@opencode/ui/context"
import { useDialog } from "@opencode/ui/context/dialog"
import { type Accessor, batch, createEffect, createMemo, onCleanup, onMount, untrack } from "solid-js"
import { createStore, produce, reconcile } from "solid-js/store"
import { Schema } from "effect"
import { Persistence } from "@/runtime/persistence/schema"
import { makeEventListener } from "@solid-primitives/event-listener"
import { useLanguage } from "@/runtime/i18n/language"
import { useSettings } from "@/settings/model"
import { keybindRenames } from "@/settings/keybinds/migration"
import en from "@/runtime/i18n/en"
import { Persist, persisted } from "@/runtime/persistence/storage"

const IS_MAC = typeof navigator === "object" && /(Mac|iPod|iPhone|iPad)/.test(navigator.platform)

const PALETTE_ID = "command.palette"

export const DEFAULT_PALETTE_KEYBIND = "mod+k,mod+shift+p"

const SUGGESTED_PREFIX = "suggested."

type KeyLabel =
  | "common.key.ctrl"
  | "common.key.alt"
  | "common.key.shift"
  | "common.key.meta"
  | "common.key.space"
  | "common.key.backspace"
  | "common.key.enter"
  | "common.key.tab"
  | "common.key.delete"
  | "common.key.home"
  | "common.key.end"
  | "common.key.pageUp"
  | "common.key.pageDown"
  | "common.key.insert"
  | "common.key.esc"

function keyText(key: KeyLabel, t?: (key: KeyLabel) => string) {
  return t ? t(key) : en[key]
}

function actionId(id: string) {
  if (!id.startsWith(SUGGESTED_PREFIX)) return id

  return id.slice(SUGGESTED_PREFIX.length)
}

function normalizeKey(key: string) {
  if (key === ",") return "comma"

  if (key === "+") return "plus"

  if (key === " ") return "space"

  return key.toLowerCase()
}

export function keyFromKeyboardEvent(event: KeyboardEvent) {
  const key = normalizeKey(event.key)

  if (!event.altKey || /^[a-z0-9]$/.test(key)) return key

  if (!event.code.startsWith("Key") || event.code.length !== 4) return key

  return event.code.slice(3).toLowerCase()
}

function signature(key: string, ctrl: boolean, meta: boolean, shift: boolean, alt: boolean) {
  const mask = (ctrl ? 1 : 0) | (meta ? 2 : 0) | (shift ? 4 : 0) | (alt ? 8 : 0)

  return `${key}:${mask}`
}

function signatureFromEvent(event: KeyboardEvent) {
  return signature(keyFromKeyboardEvent(event), event.ctrlKey, event.metaKey, event.shiftKey, event.altKey)
}

export type KeybindConfig = string

export interface Keybind {
  key: string
  ctrl: boolean
  meta: boolean
  shift: boolean
  alt: boolean
}

export const CommandSection = Schema.Literals(["general", "session", "navigation", "model", "terminal", "prompt"])

export type CommandSection = typeof CommandSection.Type

export interface CommandOption {
  id: string
  title: string
  description?: string
  category?: string
  /** Section of Settings > Shortcuts. Host commands leave it unset and are placed by id prefix. */
  section?: CommandSection
  keybind?: KeybindConfig
  slash?: string
  slashArguments?: boolean
  /** Listed right after the option whose slash name this is, when one is registered. */
  slashAfter?: string
  suggested?: boolean
  /** Listed when the command palette opens without a query. Host commands are listed by id instead. */
  featured?: boolean
  disabled?: boolean
  hidden?: boolean
  /** The keybind also fires while a text field has focus. */
  editable?: boolean
  when?: (event: KeyboardEvent) => boolean
  onSelect?: (source?: "palette" | "keybind" | "slash", input?: string) => void | Promise<void>
  onHighlight?: () => (() => void) | void
}

export function commandPaletteOptions(options: CommandOption[]) {
  return options.filter(
    (option) =>
      !option.disabled && !option.hidden && !option.id.startsWith(SUGGESTED_PREFIX) && option.id !== "file.open",
  )
}

export function resolveKeybindOption(candidates: CommandOption[] | undefined, event: KeyboardEvent) {
  return candidates?.find((option) => option.when?.(event)) ?? candidates?.find((option) => !option.when)
}

type CommandSource = "palette" | "keybind" | "slash"

export const CommandCatalogItem = Persistence.struct({
  title: Schema.String,
  description: Schema.optional(Schema.String),
  category: Schema.optional(Schema.String),
  section: Persistence.optional(CommandSection),
  keybind: Schema.optional(Schema.String),
  slash: Schema.optional(Schema.String),
  hidden: Schema.optional(Schema.Boolean),
})

export type CommandCatalogItem = typeof CommandCatalogItem.Type

export const CommandCatalog = Schema.Record(Schema.String, Schema.mutableKey(CommandCatalogItem))

export type CommandCatalog = typeof CommandCatalog.Type

export type CommandRegistration = {
  key?: string
  options: Accessor<CommandOption[]>
}

export function addCommandRegistration(registrations: CommandRegistration[], entry: CommandRegistration) {
  return [entry, ...registrations]
}

export function activeCommandRegistrations(registrations: CommandRegistration[]) {
  const keys = new Set<string>()

  return registrations.filter((entry) => {
    if (entry.key === undefined) return true

    if (keys.has(entry.key)) return false
    keys.add(entry.key)

    return true
  })
}

// Each option with `slashAfter` follows the first option with that slash name, so a command from another
// registration can sit inside that registration's slash list.
function placeAfterSlash(options: CommandOption[]) {
  const anchors = new Map<string, CommandOption>()
  options.forEach((option) => {
    if (option.slash && !option.slashAfter && !anchors.has(option.slash)) anchors.set(option.slash, option)
  })
  const moved = options.filter((option) => option.slashAfter && anchors.has(option.slashAfter))

  if (moved.length === 0) return options

  return options.flatMap((option) => {
    if (moved.includes(option)) return []

    if (!option.slash || anchors.get(option.slash) !== option) return [option]

    return [option, ...moved.filter((item) => item.slashAfter === option.slash)]
  })
}

export function parseKeybind(config: string): Keybind[] {
  if (!config || config === "none") return []

  return config.split(",").map((combo) => {
    const parts = combo.trim().toLowerCase().split("+")

    const keybind: Keybind = {
      key: "",
      ctrl: false,
      meta: false,
      shift: false,
      alt: false,
    }

    for (const part of parts) {
      switch (part) {
        case "ctrl":
        case "control":
          keybind.ctrl = true
          break
        case "meta":
        case "cmd":
        case "command":
          keybind.meta = true
          break
        case "mod":
          if (IS_MAC) keybind.meta = true
          else keybind.ctrl = true
          break
        case "alt":
        case "option":
          keybind.alt = true
          break
        case "shift":
          keybind.shift = true
          break
        default:
          keybind.key = part
          break
      }
    }

    return keybind
  })
}

export function matchKeybind(keybinds: Keybind[], event: KeyboardEvent): boolean {
  const eventKey = keyFromKeyboardEvent(event)

  for (const kb of keybinds) {
    const keyMatch = kb.key === eventKey
    const ctrlMatch = kb.ctrl === (event.ctrlKey || false)
    const metaMatch = kb.meta === (event.metaKey || false)
    const shiftMatch = kb.shift === (event.shiftKey || false)
    const altMatch = kb.alt === (event.altKey || false)

    if (keyMatch && ctrlMatch && metaMatch && shiftMatch && altMatch) {
      return true
    }
  }

  return false
}

function displayKeybindParts(kb: Keybind, t?: (key: KeyLabel) => string) {
  const parts: string[] = []

  if (kb.ctrl) parts.push(IS_MAC ? "⌃" : keyText("common.key.ctrl", t))

  if (kb.alt) parts.push(IS_MAC ? "⌥" : keyText("common.key.alt", t))

  if (kb.shift) parts.push(IS_MAC ? "⇧" : keyText("common.key.shift", t))

  if (kb.meta) parts.push(IS_MAC ? "⌘" : keyText("common.key.meta", t))

  if (!kb.key) return parts

  const keys: Record<string, string> = {
    arrowup: "↑",
    arrowdown: "↓",
    arrowleft: "←",
    arrowright: "→",
    comma: ",",
    plus: "+",
  }

  const named: Record<string, KeyLabel> = {
    backspace: "common.key.backspace",
    delete: "common.key.delete",
    end: "common.key.end",
    enter: "common.key.enter",
    esc: "common.key.esc",
    escape: "common.key.esc",
    home: "common.key.home",
    insert: "common.key.insert",
    pagedown: "common.key.pageDown",
    pageup: "common.key.pageUp",
    space: "common.key.space",
    tab: "common.key.tab",
  }

  const key = kb.key.toLowerCase()

  const displayKey =
    keys[key] ??
    (named[key]
      ? keyText(named[key], t)
      : key.length === 1
        ? key.toUpperCase()
        : key.charAt(0).toUpperCase() + key.slice(1))

  parts.push(displayKey)

  return parts
}

export function formatKeybindParts(config: string, t?: (key: KeyLabel) => string): string[] {
  if (!config || config === "none") return []
  const keybind = parseKeybind(config)[0]

  return keybind ? displayKeybindParts(keybind, t) : []
}

export function formatKeybind(config: string, t?: (key: KeyLabel) => string): string {
  const parts = formatKeybindParts(config, t)

  if (parts.length === 0) return ""

  return IS_MAC ? parts.join("") : parts.join("+")
}

function isEditableTarget(target: EventTarget | null) {
  if (!(target instanceof HTMLElement)) return false

  if (target.isContentEditable) return true

  if (target.closest("[contenteditable='true']")) return true

  if (target.closest("input, textarea, select")) return true

  return false
}

export const { use: useCommand, provider: CommandProvider } = createSimpleContext({
  name: "Command",
  init: () => {
    const dialog = useDialog()
    const settings = useSettings()
    const language = useLanguage()

    const [store, setStore] = createStore({
      registrations: [] as CommandRegistration[],
      suspendCount: 0,
    })

    const warnedDuplicates = new Set<string>()

    const [catalog, setCatalog, _, catalogReady] = persisted(Persist.global("command.catalog.v1"), CommandCatalog, {})

    const bind = (id: string, def: KeybindConfig | undefined) => {
      const custom = settings.keybinds.get(actionId(id))
      const config = custom ?? def

      if (!config || config === "none") return

      return config
    }

    const registered = createMemo(() => {
      const seen = new Set<string>()
      const all: CommandOption[] = []

      for (const reg of activeCommandRegistrations(store.registrations)) {
        for (const opt of reg.options()) {
          if (seen.has(opt.id)) {
            if (import.meta.env.DEV && !warnedDuplicates.has(opt.id)) {
              warnedDuplicates.add(opt.id)
              console.warn(`[command] duplicate command id "${opt.id}" registered; keeping first entry`)
            }

            continue
          }

          seen.add(opt.id)
          all.push(opt)
        }
      }

      return placeAfterSlash(all)
    })

    createEffect(() => {
      if (!catalogReady()) return

      batch(() =>
        registered().forEach((opt) => {
          if (!opt.title) return
          setCatalog(
            actionId(opt.id),
            reconcile({
              title: opt.title,
              description: opt.description,
              category: opt.category,
              section: opt.section,
              keybind: opt.keybind,
              slash: opt.slash,
            }),
          )
        }),
      )
    })

    // Built-in GUI extensions republished these commands under new ids. Drop the old entries so
    // Settings > Shortcuts lists each command once.
    createEffect(() => {
      if (!catalogReady()) return
      const stale = untrack(() => Object.keys(keybindRenames).filter((id) => id in catalog))

      if (stale.length) setCatalog(produce((draft) => stale.forEach((id) => delete draft[id])))
    })

    const catalogOptions = createMemo(() => Object.entries(catalog).map(([id, meta]) => ({ id, ...meta })))

    const options = createMemo(() => {
      const resolved = registered().map((opt) => ({
        ...opt,
        keybind: bind(opt.id, opt.keybind),
      }))

      const suggested = resolved.filter((x) => x.suggested && !x.disabled)

      return [
        ...suggested.map((x) => ({
          ...x,
          id: SUGGESTED_PREFIX + x.id,
          category: language.t("command.category.suggested"),
        })),
        ...resolved,
      ]
    })

    const suspended = () => store.suspendCount > 0

    const palette = createMemo(() => {
      const config = settings.keybinds.get(PALETTE_ID) ?? DEFAULT_PALETTE_KEYBIND
      const keybinds = parseKeybind(config)

      return new Set(keybinds.map((kb) => signature(kb.key, kb.ctrl, kb.meta, kb.shift, kb.alt)))
    })

    const keymap = createMemo(() => {
      const map = new Map<string, CommandOption[]>()

      for (const option of options()) {
        if (option.id.startsWith(SUGGESTED_PREFIX)) continue

        if (option.disabled) continue

        if (!option.keybind) continue

        const keybinds = parseKeybind(option.keybind)

        for (const kb of keybinds) {
          if (!kb.key) continue
          const sig = signature(kb.key, kb.ctrl, kb.meta, kb.shift, kb.alt)
          const existing = map.get(sig)

          if (existing) {
            existing.push(option)
            continue
          }

          map.set(sig, [option])
        }
      }

      return map
    })

    const optionMap = createMemo(() => {
      const map = new Map<string, CommandOption>()

      for (const option of options()) {
        map.set(option.id, option)
        map.set(actionId(option.id), option)
      }

      return map
    })

    const run = (id: string, source?: CommandSource, input?: string) => {
      const option = optionMap().get(id)

      return option?.onSelect?.(source, input)
    }

    const showPalette = () => {
      run(PALETTE_ID, "palette")
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (suspended() || dialog.active) return

      const sig = signatureFromEvent(event)
      const isPalette = palette().has(sig)
      const option = resolveKeybindOption(keymap().get(sig), event)
      const modified = event.ctrlKey || event.metaKey || event.altKey
      const isTab = event.key === "Tab"

      if (isEditableTarget(event.target) && !isPalette && !option?.editable && !modified && !isTab) return

      if (isPalette) {
        event.preventDefault()
        event.stopPropagation()
        showPalette()

        return
      }

      if (!option) return
      event.preventDefault()
      event.stopPropagation()
      void option.onSelect?.("keybind")
    }

    onMount(() => {
      makeEventListener(document, "keydown", handleKeyDown, { capture: true })
    })

    function register(cb: () => CommandOption[]): void
    function register(key: string, cb: () => CommandOption[]): void
    function register(key: string | (() => CommandOption[]), cb?: () => CommandOption[]) {
      const id = typeof key === "string" ? key : undefined
      const next = typeof key === "function" ? key : cb

      if (!next) return
      const options = createMemo(next)

      const entry: CommandRegistration = {
        key: id,
        options,
      }

      // Register only committed owners. Updating the registry during a transition
      // can restore its pending snapshot after the outgoing owner's cleanup.
      onMount(() => setStore("registrations", (arr) => addCommandRegistration(arr, entry)))
      onCleanup(() => {
        setStore("registrations", (arr) => arr.filter((x) => x !== entry))
      })
    }

    const keybindConfig = (id: string) => {
      if (id === PALETTE_ID) return settings.keybinds.get(PALETTE_ID) ?? DEFAULT_PALETTE_KEYBIND
      const base = actionId(id)

      return options().find((x) => actionId(x.id) === base)?.keybind ?? bind(base, catalog[base]?.keybind)
    }

    return {
      register,
      trigger(id: string, source?: CommandSource, input?: string) {
        return run(id, source, input)
      },
      keybind(id: string) {
        const config = keybindConfig(id)

        if (!config) return ""

        return formatKeybind(config, language.t)
      },
      keybindParts(id: string) {
        const config = keybindConfig(id)

        return config ? formatKeybindParts(config, language.t) : []
      },
      /** The event matches the command's effective keybind (user override or default). */
      matches(id: string, event: KeyboardEvent) {
        const config = keybindConfig(id)

        return !!config && matchKeybind(parseKeybind(config), event)
      },
      show: showPalette,
      keybinds(enabled: boolean) {
        setStore("suspendCount", (count) => Math.max(0, count + (enabled ? -1 : 1)))
      },
      suspended,
      get catalog() {
        return catalogOptions()
      },
      get options() {
        return options()
      },
    }
  },
})

import { useLanguage } from "@/runtime/i18n/language"
import { usePlatform } from "@/runtime/platform/platform"
import { useCommand, type CommandOption } from "./command"

export function DesktopCommands() {
  const command = useCommand()
  const language = useLanguage()
  const platform = usePlatform()

  command.register("desktop", () => {
    const commands: CommandOption[] = []

    if (platform.platform !== "desktop" || !platform.exportDebugLogs) return commands
    commands.push({
      id: "logs.export",
      title: language.t("command.logs.export"),
      category: language.t("command.category.settings"),
      onSelect: () => void platform.exportDebugLogs?.(),
    })

    return commands
  })

  return null
}

