function groups(entries: CommandPaletteEntry[]) {
  const map = new Map<string, CommandPaletteEntry[]>()

  for (const entry of entries) map.set(entry.category, [...(map.get(entry.category) ?? []), entry])

  return Array.from(map.entries()).map(([category, entries]) => ({ category, entries }))
}

export function matchesCommandPaletteEntry(entry: CommandPaletteEntry, query: string) {
  const value = query.toLowerCase()

  return [entry.title, entry.description, entry.category].some((text) => text?.toLowerCase().includes(value))
}

export function DialogCommandPalette(props: { onOpenFile?: (path: string) => void }) {
  const palette = createCommandPaletteModel(props)

  const items = (q: string) => {
    if (!q) return [...palette.preferredCommandEntries(), ...palette.recentFileEntries()]

    return palette.commandEntries().filter((entry) => matchesCommandPaletteEntry(entry, q))
  }

  return (
    <CommandPaletteView
      placeholder={palette.language.t("palette.search.placeholder")}
      items={items}
      sources={[
        palette.sessions,
        async (query, signal) => {
          if (!query) return []
          const files = await palette.file.searchFiles(query, { signal })
          const category = palette.language.t("palette.group.files")

          return files.map((path) => createCommandPaletteFileEntry(path, category))
        },
      ]}
      highlight={palette.highlight}
      select={palette.select}
      close={palette.close}
    />
  )
}

export function CommandPaletteView(props: {
  placeholder: string
  items: (query: string) => CommandPaletteEntry[]
  sources: ((query: string, signal: AbortSignal) => Promise<CommandPaletteEntry[]>)[]
  highlight: (item: CommandPaletteEntry | undefined) => void
  select: (item: CommandPaletteEntry | undefined) => void
  close: () => void
}) {
  const language = useLanguage()
  const tabs = useTabs()
  const [store, setStore] = createStore<{ query: string; active?: string }>({ query: "" })

  const search = createCommandPaletteSearch({ query: () => store.query, items: props.items, sources: props.sources })
  const visibleEntries = search.items
  const groupedEntries = createMemo(() => groups(visibleEntries()))

  // Follow the first result until the user explicitly chooses a row.
  const activeEntry = createMemo(
    () => visibleEntries().find((entry) => entry.id === store.active) ?? visibleEntries()[0],
  )

  const openSessions = createMemo(
    () => new Set(tabs.store.flatMap((tab) => (tab.type === "session" ? [`${tab.server}\0${tab.sessionId}`] : []))),
  )

  createEffect(() => {
    props.highlight(activeEntry())
  })

  let resultsRef: HTMLDivElement | undefined

  createEffect(() => {
    // Incoming results can move an explicitly selected row below the viewport.
    visibleEntries()

    if (!activeEntry()) return

    const frame = requestAnimationFrame(() => {
      resultsRef?.querySelector("[data-active]")?.scrollIntoView({ block: "nearest" })
    })

    onCleanup(() => cancelAnimationFrame(frame))
  })

  const move = (delta: -1 | 1) => {
    const count = visibleEntries().length

    if (count === 0) return
    const index = visibleEntries().findIndex((entry) => entry.id === activeEntry()?.id)
    setStore("active", visibleEntries()[(index + delta + count) % count].id)
  }

  const handleKeyDown = (event: KeyboardEvent) => {
    if (event.key === "ArrowDown") {
      event.preventDefault()
      move(1)

      return
    }

    if (event.key === "ArrowUp") {
      event.preventDefault()
      move(-1)

      return
    }

    if (event.key === "Enter") {
      event.preventDefault()
      props.select(activeEntry())

      return
    }

    if (event.key === "Escape") {
      event.preventDefault()
      props.close()
    }
  }

  return (
    <Dialog class="command-palette" size="large">
      <DialogBody class="command-palette-body">
        <div class="command-palette-search">
          <TextInput
            value={store.query}
            autofocus
            autocomplete="off"
            spellcheck={false}
            appearance="large"
            placeholder={props.placeholder}
            leadingIcon={<Icon name="magnifying-glass" />}
            onInput={(event) => setStore({ query: event.currentTarget.value, active: undefined })}
            onKeyDown={handleKeyDown}
          />
        </div>
        <ScrollView class="command-palette-scroll" viewportRef={(el) => (resultsRef = el)}>
          <div class="command-palette-results" role="listbox">
            <Show
              when={visibleEntries().length > 0}
              fallback={
                <div class="command-palette-state">
                  {search.loading() ? language.t("common.loading") : language.t("palette.empty")}
                </div>
              }
            >
              <For each={groupedEntries()}>
                {(group) => (
                  <div class="command-palette-group">
                    <Show when={group.category}>
                      <div class="command-palette-group-title">{group.category}</div>
                    </Show>
                    <For each={group.entries}>
                      {(item) => (
                        <PaletteRow
                          item={item}
                          active={activeEntry()?.id === item.id}
                          language={language}
                          sessionOpen={
                            item.server && item.sessionID
                              ? openSessions().has(`${item.server}\0${item.sessionID}`)
                              : false
                          }
                          onActive={() => setStore("active", item.id)}
                          onSelect={() => props.select(item)}
                        />
                      )}
                    </For>
                  </div>
                )}
              </For>
            </Show>
          </div>
        </ScrollView>
      </DialogBody>
    </Dialog>
  )
}

function PaletteRow(props: {
  item: CommandPaletteEntry
  active: boolean
  language: ReturnType<typeof useLanguage>
  sessionOpen: boolean
  onActive: () => void
  onSelect: () => void
}) {
  const session = () =>
    props.item.server && props.item.directory && props.item.sessionID
      ? { server: props.item.server, directory: props.item.directory, sessionID: props.item.sessionID }
      : undefined

  return (
    <button
      type="button"
      class="command-palette-row group"
      role="option"
      aria-selected={props.active}
      data-active={props.active ? "" : undefined}
      onMouseMove={(event) => {
        // Ignore hover from a static cursor when keyboard scrolling moves rows underneath it.
        if (event.movementX === 0 && event.movementY === 0) return
        props.onActive()
      }}
      onMouseDown={(event) => event.preventDefault()}
      onClick={props.onSelect}
    >
      <Switch
        fallback={
          <div class="command-palette-row-main">
            <FileIcon node={{ path: props.item.path ?? "", type: "file" }} class="command-palette-row-icon size-4" />
            <div class="command-palette-file-path">
              <span class="command-palette-file-dir">{getDirectory(props.item.path ?? "")}</span>
              <span class="command-palette-file-name">{getFilename(props.item.path ?? "")}</span>
            </div>
          </div>
        }
      >
        <Match when={props.item.type === "command"}>
          <div class="command-palette-row-main">
            <div class="command-palette-row-text">
              <span class="command-palette-title">{props.item.title}</span>
              <Show when={props.item.description}>
                <span class="command-palette-description">{props.item.description}</span>
              </Show>
            </div>
          </div>
          <Show when={props.item.keybind}>
            <Keybind keys={formatKeybindParts(props.item.keybind ?? "", props.language.t)} variant="neutral" />
          </Show>
        </Match>
        <Match when={props.item.type === "session"}>
          <div class="command-palette-row-main">
            <div class="relative shrink-0">
              <Show when={props.sessionOpen}>
                <span
                  aria-hidden="true"
                  class="pointer-events-none absolute top-1/2 h-3 w-0.5 -translate-y-1/2 rounded-[2px] bg-v2-background-bg-layer-04"
                  style={{ right: "calc(100% + 4px)" }}
                />
              </Show>
              <Show when={session()}>
                {(session) => (
                  <SessionTabAvatar
                    project={props.item.project}
                    directory={session().directory}
                    sessionId={session().sessionID}
                    server={session().server}
                  />
                )}
              </Show>
            </div>
            <div class="command-palette-row-text">
              <span class="command-palette-title" classList={{ "opacity-70": !!props.item.archived }}>
                {props.item.title}
              </span>
              <Show when={props.item.description}>
                <span class="command-palette-description" classList={{ "opacity-70": !!props.item.archived }}>
                  {props.item.description}
                </span>
              </Show>
            </div>
          </div>
          <Show when={props.item.updated}>
            <span class="command-palette-meta">
              {getRelativeTime(new Date(props.item.updated!).toISOString(), props.language.t)}
            </span>
          </Show>
        </Match>
      </Switch>
    </button>
  )
}

/** Coordinates focus restoration and actions that must run after menu content unmounts. */
export function createMenuDismissController(content: () => HTMLElement | undefined) {
  let restoreTrigger = true

  return {
    /** Allows the menu primitive to restore focus to its trigger when closing. */
    allowTriggerRestore() {
      restoreTrigger = true
    },
    /** Keeps focus at its current or next destination instead of returning it to the trigger. */
    preventTriggerRestore() {
      restoreTrigger = false
    },
    /** Applies the current restoration policy during the menu primitive's close-focus event. */
    onCloseAutoFocus(event: Event) {
      if (!restoreTrigger) event.preventDefault()
    },
    /** Runs an action after the menu unmounts and its focus-close work has settled. */
    afterClose(callback: () => void) {
      const complete = () => {
        if (content()?.isConnected) {
          requestAnimationFrame(complete)

          return
        }

        requestAnimationFrame(() => requestAnimationFrame(callback))
      }

      requestAnimationFrame(complete)
    },
  }
}

import { getFilename } from "@opencode/util/path"
import type { Project } from "@/runtime/server/types"
import type { SessionInfo } from "@opencode/client/promise"
import { useDialog } from "@opencode/ui/context/dialog"
import { createMemo, onCleanup } from "solid-js"
import { commandPaletteOptions, useCommand, type CommandOption } from "@/shell/commands/command"
import { useFile } from "@/workspaces/files/model"
import { useGlobal } from "@/runtime/server/runtime"
import { useLanguage } from "@/runtime/i18n/language"
import type { LocalProject } from "@/shell/state/layout"
import { ServerConnection } from "@/runtime/server/registry"
import { useServerSDK } from "@/runtime/server/client"
import { useTabs } from "@/shell/tabs/tabs"
import { displayName } from "@opencode/ui/project-avatar"
import { resolveProjectForSession } from "@/shell/layout/helpers"
import { useExtensionHost } from "@/runtime/extension/host"
import { useExtensionAttachment } from "@/runtime/extension/host-apis"
import { looksLikeSessionID } from "@/session/search"

export type CommandPaletteEntry = {
  id: string
  type: "command" | "file" | "session"
  title: string
  description?: string
  keybind?: string
  category: string
  option?: CommandOption
  path?: string
  directory?: string
  sessionID?: string
  server?: ServerConnection.Key
  project?: LocalProject
  archived?: number
  updated?: number
}

const ENTRY_LIMIT = 5

// The palette opens with these host commands. Featured extension commands list before the view toggles.
const COMMON_COMMAND_IDS = ["session.new", "workspace.new", "session.previous", "session.next"] as const

const COMMON_VIEW_COMMAND_IDS = ["review.toggle"] as const

export function uniqueCommandPaletteEntries(items: CommandPaletteEntry[]) {
  const seen = new Set<string>()

  return items.filter((item) => {
    if (seen.has(item.id)) return false
    seen.add(item.id)

    return true
  })
}

export function createCommandPaletteFileEntry(path: string, category: string): CommandPaletteEntry {
  return {
    id: "file:" + path,
    type: "file",
    title: path,
    category,
    path,
  }
}

export function createCommandPaletteFileOpener(onOpenFile?: (path: string) => void) {
  const links = useExtensionHost().links
  const extensions = useExtensionAttachment()

  return (path: string) => {
    links.open({ href: path, exact: true, background: true, session: extensions.current() })
    onOpenFile?.(path)
  }
}

/** The highlighted option's preview cleanup, and whether the palette committed a choice. */
export type PaletteHighlight = { cleanup: (() => void) | void; committed: boolean }

export function createCommandPaletteModel(props: { filesOnly?: () => boolean; onOpenFile?: (path: string) => void }) {
  const command = useCommand()
  const global = useGlobal()
  const language = useLanguage()
  const file = useFile()
  const dialog = useDialog()
  const serverSDK = useServerSDK()
  const serverCtx = global.ensureServerCtx(serverSDK.server)
  const appTabs = useTabs()
  const extensions = useExtensionAttachment()
  const openFile = createCommandPaletteFileOpener(props.onOpenFile)
  const state: PaletteHighlight = { cleanup: undefined, committed: false }
  const filesOnly = () => props.filesOnly?.() ?? false

  const allowedCommands = createMemo(() => {
    if (filesOnly()) return []

    return commandPaletteOptions(command.options)
  })

  const commandEntries = createMemo(() => {
    const category = language.t("palette.group.commands")

    return allowedCommands().map((option) => createCommandPaletteCommandEntry(option, category))
  })

  const preferredCommandEntries = createMemo(() => {
    const all = allowedCommands()

    const ids = [
      ...COMMON_COMMAND_IDS,
      ...all.flatMap((option) => (option.featured ? [option.id] : [])),
      ...COMMON_VIEW_COMMAND_IDS,
    ]

    const order = new Map<string, number>(ids.map((id, index) => [id, index]))
    const picked = all.filter((option) => order.has(option.id))
    const base = picked.length ? picked : all.slice(0, ENTRY_LIMIT)
    const sorted = picked.length ? [...base].sort((a, b) => (order.get(a.id) ?? 0) - (order.get(b.id) ?? 0)) : base
    const category = language.t("palette.group.commands")

    return sorted.map((option) => createCommandPaletteCommandEntry(option, category))
  })

  const recentFileEntries = createMemo(() => {
    const all = extensions.files.opened()
    const active = extensions.files.active()
    const order = active ? [active, ...all.filter((path) => path !== active)] : all
    const category = language.t("palette.group.files")

    return order.slice(0, ENTRY_LIMIT).map((path) => createCommandPaletteFileEntry(path, category))
  })

  const rootFileEntries = createMemo(() => {
    const category = language.t("palette.group.files")

    return file.tree
      .children("")
      .filter((node) => node.type === "file")
      .map((node) => node.path)
      .sort((a, b) => a.localeCompare(b))
      .slice(0, ENTRY_LIMIT)
      .map((path) => createCommandPaletteFileEntry(path, category))
  })

  const sessions = createServerSessionEntries({
    server: ServerConnection.key(serverSDK.server),
    opened: serverCtx.projects.list,
    stored: () => serverCtx.sync.data.project,
    load: (search, signal) => serverSDK.api.session.list({ parentID: null, search, limit: 50 }, { signal }),
    get: (sessionID, signal) => serverSDK.api.session.get({ sessionID }, { signal }),
    untitled: () => language.t("command.session.new"),
    category: () => language.t("command.category.session"),
    recentCategory: () => language.t("palette.group.recentSessions"),
  })

  const highlight = (item: CommandPaletteEntry | undefined) => {
    state.cleanup?.()
    state.cleanup = undefined

    if (item?.type !== "command") return
    state.cleanup = item.option?.onHighlight?.()
  }

  const select = (item: CommandPaletteEntry | undefined) => {
    if (!item) return
    state.committed = true
    state.cleanup = undefined
    dialog.close()

    if (item.type === "command") {
      void item.option?.onSelect?.("palette")

      return
    }

    if (item.type === "session") {
      if (!item.sessionID || !item.server) return
      const directory = item.project?.worktree ?? item.directory

      if (directory) {
        serverCtx.projects.open(directory)
        serverCtx.projects.touch(directory)
      }

      const tab = appTabs.addSessionTab({
        server: item.server,
        sessionId: item.sessionID,
      })

      appTabs.select(tab)

      return
    }

    if (!item.path) return
    openFile(item.path)
  }

  onCleanup(() => {
    if (state.committed) return
    state.cleanup?.()
  })

  return {
    language,
    file,
    commandEntries,
    preferredCommandEntries,
    recentFileEntries,
    rootFileEntries,
    sessions,
    highlight,
    select,
    close: () => dialog.close(),
  }
}

export function createCommandPaletteCommandEntry(option: CommandOption, category: string): CommandPaletteEntry {
  return {
    id: "command:" + option.id,
    type: "command",
    title: option.title,
    description: option.description,
    keybind: option.keybind,
    category,
    option,
  }
}

export function createServerSessionEntries(props: {
  server: ServerConnection.Key
  opened: () => LocalProject[]
  stored: () => Project[]
  load: (search: string, signal: AbortSignal) => Promise<{ data: SessionInfo[] }>
  get: (sessionID: string, signal: AbortSignal) => Promise<SessionInfo>
  untitled: () => string
  category: () => string
  recentCategory: () => string
}) {
  let abort: AbortController | undefined

  onCleanup(() => abort?.abort())

  return async (text: string): Promise<CommandPaletteEntry[]> => {
    const search = text.trim()

    abort?.abort()
    const current = new AbortController()
    abort = current

    // Typed searches wait for a pause; an empty query lists recent sessions right away.
    await new Promise<void>((resolve) => {
      const timer = setTimeout(resolve, search ? 100 : 0)
      current.signal.addEventListener(
        "abort",
        () => {
          clearTimeout(timer)
          resolve()
        },
        { once: true },
      )
    })

    if (current.signal.aborted) return []
    const opened = props.opened()
    const stored = props.stored().map((project) => ({ ...project, expanded: false }))
    const category = search ? props.category() : props.recentCategory()

    const entries = await Promise.all([
      props.load(search, current.signal).then(
        (result) => result.data,
        () => [],
      ),
      looksLikeSessionID(search)
        ? props.get(search, current.signal).then(
            (result) => [result],
            () => [],
          )
        : Promise.resolve([]),
    ]).then(([listed, exact]) =>
      [...new Map([...exact, ...listed].map((session) => [session.id, session] as const)).values()].flatMap(
        (session) => {
          if (session.time.archived) return []

          const project = resolveProjectForSession(session, opened, stored)

          return [
            {
              id: `session:${props.server}:${session.id}`,
              type: "session" as const,
              title: session.title || props.untitled(),
              description: project ? displayName(project) : getFilename(session.location.directory),
              category,
              directory: session.location.directory,
              sessionID: session.id,
              server: props.server,
              project,
              updated: session.time.updated,
            },
          ]
        },
      ),
    )

    return search ? entries : entries.slice(0, ENTRY_LIMIT)
  }
}

const editableSelector = "input, textarea, select, [contenteditable=''], [contenteditable='true']"

export function handleDocumentSearchKeydown(
  input: HTMLInputElement | undefined,
  event: KeyboardEvent,
  inputValue: string,
  setInputValue: (value: string) => void,
) {
  if (!input) return false

  if (event.defaultPrevented || event.isComposing) return false

  if (event.target === input) return false

  if (event.target instanceof Element && event.target.closest(editableSelector)) return false

  const action = searchKeyAction(event)

  if (!action) return false

  event.preventDefault()
  event.stopPropagation()
  input.focus()

  const start = input.selectionStart ?? inputValue.length
  const end = input.selectionEnd ?? inputValue.length

  if (action.type === "selectAll") {
    input.setSelectionRange(0, inputValue.length)

    return true
  }

  if (action.type === "move") {
    moveSelection(input, inputValue, action.delta, event.shiftKey)

    return true
  }

  if (action.type === "home") {
    setBoundarySelection(input, start, 0, event.shiftKey)

    return true
  }

  if (action.type === "end") {
    setBoundarySelection(input, start, inputValue.length, event.shiftKey)

    return true
  }

  if (action.type === "deleteBackward") {
    if (start !== end)
      return updateValue(input, inputValue.slice(0, start) + inputValue.slice(end), start, setInputValue)

    if (start === 0) return true

    return updateValue(input, inputValue.slice(0, start - 1) + inputValue.slice(end), start - 1, setInputValue)
  }

  if (action.type === "deleteForward") {
    if (start !== end)
      return updateValue(input, inputValue.slice(0, start) + inputValue.slice(end), start, setInputValue)

    if (end === inputValue.length) return true

    return updateValue(input, inputValue.slice(0, start) + inputValue.slice(end + 1), start, setInputValue)
  }

  return updateValue(
    input,
    inputValue.slice(0, start) + action.value + inputValue.slice(end),
    start + action.value.length,
    setInputValue,
  )
}

function searchKeyAction(event: KeyboardEvent) {
  if ((event.ctrlKey || event.metaKey) && !event.altKey && event.key.toLowerCase() === "a") {
    return { type: "selectAll" } as const
  }

  if (event.ctrlKey || event.metaKey || event.altKey) return undefined

  if (event.key.length === 1) return { type: "insert", value: event.key } as const

  if (event.key === "Backspace") return { type: "deleteBackward" } as const

  if (event.key === "Delete") return { type: "deleteForward" } as const

  if (event.key === "ArrowLeft") return { type: "move", delta: -1 } as const

  if (event.key === "ArrowRight") return { type: "move", delta: 1 } as const

  if (event.key === "Home") return { type: "home" } as const

  if (event.key === "End") return { type: "end" } as const

  return undefined
}

function moveSelection(input: HTMLInputElement, inputValue: string, delta: -1 | 1, extend: boolean) {
  const start = input.selectionStart ?? inputValue.length
  const end = input.selectionEnd ?? inputValue.length

  if (!extend && start !== end) {
    const caret = delta < 0 ? start : end
    input.setSelectionRange(caret, caret)

    return
  }

  if (!extend) {
    const caret = Math.max(0, Math.min(inputValue.length, start + delta))
    input.setSelectionRange(caret, caret)

    return
  }

  const backward = input.selectionDirection === "backward"
  const anchor = backward ? end : start
  const focus = backward ? start : end
  const next = Math.max(0, Math.min(inputValue.length, focus + delta))
  input.setSelectionRange(Math.min(anchor, next), Math.max(anchor, next), next < anchor ? "backward" : "forward")
}

function setBoundarySelection(input: HTMLInputElement, anchor: number, focus: number, extend: boolean) {
  if (!extend) {
    input.setSelectionRange(focus, focus)

    return
  }

  input.setSelectionRange(Math.min(anchor, focus), Math.max(anchor, focus), focus < anchor ? "backward" : "forward")
}

function updateValue(input: HTMLInputElement, value: string, caret: number, setInputValue: (value: string) => void) {
  input.value = value
  setInputValue(value)
  input.setSelectionRange(caret, caret)

  return true
}

import { createMemo, createResource, onCleanup } from "solid-js"
import { uniqueCommandPaletteEntries, type CommandPaletteEntry } from "./palette"

export function createCommandPaletteSearch(props: {
  query: () => string
  items: (query: string) => CommandPaletteEntry[]
  sources: ((query: string, signal: AbortSignal) => Promise<CommandPaletteEntry[]>)[]
}) {
  const query = createMemo(() => props.query().trim())
  const local = createMemo(() => props.items(query()))

  const sources = props.sources.map((load) => {
    let abort: AbortController | undefined
    onCleanup(() => abort?.abort())

    const [result] = createResource(
      query,
      async (query) => {
        abort?.abort()
        const current = new AbortController()
        abort = current

        return { query, items: await load(query, current.signal).catch(() => []) }
      },
      // Remote searches must not suspend the dialog's local results on first render.
      { initialValue: { query: "", items: [] as CommandPaletteEntry[] } },
    )

    return result
  })

  return {
    items: createMemo(() =>
      uniqueCommandPaletteEntries([
        ...local(),
        ...sources.flatMap((source) => {
          // Never keep results for an older query selectable while the next one loads.
          const result = source.latest

          return result.query === query() ? result.items : []
        }),
      ]),
    ),
    loading: () => sources.some((source) => source.loading),
  }
}

import { describe, expect, test } from "bun:test"
import { errorDescriptionKey, errorStatus } from "./description"

describe("error description", () => {
  test("describes local server startup errors", () => {
    expect(errorDescriptionKey(Object.assign(new Error("migration failed"), { localServerStartup: true }))).toBe(
      "error.page.description.localServerStartup",
    )
  })

  test.each([new Error("unknown"), Object.assign(new Error("unknown"), { localServerStartup: false })])(
    "uses the generic description for other errors",
    (error) => {
      expect(errorDescriptionKey(error)).toBe("error.page.description")
    },
  )
})

describe("error status", () => {
  test.each([
    [new Error("UnexpectedStatus", { cause: { status: 502 } }), 502],
    [{ name: "APIError", data: { statusCode: 401 } }, 401],
  ])("finds status codes in an error cause or structured data", (error, status) => {
    expect(errorStatus(error)).toBe(status)
  })

  test("ignores invalid and circular status values", () => {
    const error: { status: number; cause?: unknown } = { status: 99 }
    error.cause = error
    expect(errorStatus(error)).toBeUndefined()
  })
})

export function errorDescriptionKey(error: unknown) {
  if (
    typeof error === "object" &&
    error !== null &&
    "localServerStartup" in error &&
    error.localServerStartup === true
  ) {
    return "error.page.description.localServerStartup" as const
  }

  return "error.page.description" as const
}

export function errorStatus(error: unknown) {
  const seen = new Set<object>()

  const visit = (value: unknown): number | undefined => {
    if (typeof value !== "object" || value === null || seen.has(value)) return
    seen.add(value)
    const item = value as Record<string, unknown>

    for (const key of ["status", "statusCode"] as const) {
      const status = item[key]

      if (typeof status === "number" && Number.isInteger(status) && status >= 100 && status <= 599) return status
    }

    return visit(item.cause) ?? visit(item.data)
  }

  return visit(error)
}

