export type InitError = {
  name: unknown
  data: object
}

type Translator = ReturnType<typeof useLanguage>["t"]

const CHAIN_SEPARATOR = "\n" + "─".repeat(40) + "\n"

function isIssue(value: unknown): value is { message: string; path: string[] } {
  return (
    Predicate.hasProperty(value, "message") &&
    Predicate.hasProperty(value, "path") &&
    Predicate.isString(value.message) &&
    Array.isArray(value.path) &&
    value.path.every(Predicate.isString)
  )
}

function isInitError(value: unknown): value is InitError {
  return (
    Predicate.hasProperty(value, "name") &&
    Predicate.hasProperty(value, "data") &&
    Predicate.isObjectKeyword(value.data) &&
    !Predicate.isFunction(value.data)
  )
}

/** A field of an init error's payload when `is` accepts it. */
function read<T>(error: InitError, key: string, is: (value: unknown) => value is T) {
  const value = Predicate.hasProperty(error.data, key) ? error.data[key] : undefined

  return is(value) ? value : undefined
}

function safeJson(cause: unknown, circular: string): string {
  const seen = new WeakSet<object>()

  const json = JSON.stringify(
    cause,
    (_key, val) => {
      if (Predicate.isBigInt(val)) return val.toString()

      if (Predicate.isObjectKeyword(val) && !Predicate.isFunction(val)) {
        if (seen.has(val)) return circular
        seen.add(val)
      }

      return val
    },
    2,
  )

  return json ?? String(cause)
}

function formatInitError(error: InitError, t: Translator): string {
  const json = (cause: unknown) => safeJson(cause, t("error.page.circular"))

  // The field as text: the string itself, else its JSON.
  const shown = (key: string) => read(error, key, Predicate.isString) ?? json(read(error, key, Predicate.isUnknown))

  switch (error.name) {
    case "MCPFailed": {
      const name = read(error, "name", Predicate.isString) ?? ""

      return t("error.chain.mcpFailed", { name })
    }

    case "ProviderAuthError": {
      const providerID = read(error, "providerID", Predicate.isString) ?? t("common.unknown")

      return t("error.chain.providerAuthFailed", { provider: providerID, message: shown("message") })
    }

    case "APIError": {
      const message = read(error, "message", Predicate.isString) ?? t("error.chain.apiError")
      const lines: string[] = [message]
      const statusCode = read(error, "statusCode", Predicate.isNumber)
      const retryable = read(error, "isRetryable", Predicate.isBoolean)
      const responseBody = read(error, "responseBody", Predicate.isString)

      if (statusCode !== undefined) {
        lines.push(t("error.chain.status", { status: statusCode }))
      }

      if (retryable !== undefined) {
        lines.push(t("error.chain.retryable", { retryable }))
      }

      if (responseBody) {
        lines.push(t("error.chain.responseBody", { body: responseBody }))
      }

      return lines.join("\n")
    }

    case "ProviderModelNotFoundError": {
      const suggestions = read(error, "suggestions", Array.isArray)

      const suggestionsLine = suggestions?.length
        ? [t("error.chain.didYouMean", { suggestions: suggestions.join(", ") })]
        : []

      return [
        t("error.chain.modelNotFound", {
          provider: read(error, "providerID", Predicate.isString) ?? "",
          model: read(error, "modelID", Predicate.isString) ?? "",
        }),
        ...suggestionsLine,
        t("error.chain.checkConfig"),
      ].join("\n")
    }

    case "ProviderInitError": {
      const providerID = read(error, "providerID", Predicate.isString) ?? t("common.unknown")

      return t("error.chain.providerInitFailed", { provider: providerID })
    }

    case "ConfigJsonError": {
      const path = shown("path")
      const message = read(error, "message", Predicate.isString) ?? ""

      if (message) return t("error.chain.configJsonInvalidWithMessage", { path, message })

      return t("error.chain.configJsonInvalid", { path })
    }

    case "ConfigDirectoryTypoError":
      return t("error.chain.configDirectoryTypo", {
        dir: shown("dir"),
        path: shown("path"),
        suggestion: shown("suggestion"),
      })

    case "ConfigFrontmatterError":
      return t("error.chain.configFrontmatterError", { path: shown("path"), message: shown("message") })

    case "ConfigInvalidError": {
      const issues = (read(error, "issues", Array.isArray) ?? [])
        .filter(isIssue)
        .map((issue) => "↳ " + issue.message + " " + issue.path.join("."))

      const message = read(error, "message", Predicate.isString) ?? ""
      const path = shown("path")

      const line = message
        ? t("error.chain.configInvalidWithMessage", { path, message })
        : t("error.chain.configInvalid", { path })

      return [line, ...issues].join("\n")
    }

    default:
      return read(error, "message", Predicate.isString) ?? json(error.data)
  }
}

function formatErrorChain(cause: unknown, t: Translator, depth = 0, parentMessage?: string): string {
  if (!cause) return t("error.chain.unknown")

  if (isInitError(cause)) {
    const message = formatInitError(cause, t)

    if (depth > 0 && parentMessage === message) return ""

    const indent = depth > 0 ? `\n${CHAIN_SEPARATOR}${t("error.chain.causedBy")}\n` : ""

    return indent + `${cause.name}\n${message}`
  }

  if (cause instanceof Error) {
    const isDuplicate = depth > 0 && parentMessage === cause.message
    const parts: string[] = []
    const indent = depth > 0 ? `\n${CHAIN_SEPARATOR}${t("error.chain.causedBy")}\n` : ""

    const header = `${cause.name}${cause.message ? `: ${cause.message}` : ""}`
    const stack = cause.stack?.trim()

    if (stack) {
      const startsWithHeader = stack.startsWith(header)

      if (isDuplicate && startsWithHeader) {
        const trace = stack.split("\n").slice(1).join("\n").trim()

        if (trace) {
          parts.push(indent + trace)
        }
      }

      if (isDuplicate && !startsWithHeader) {
        parts.push(indent + stack)
      }

      if (!isDuplicate && startsWithHeader) {
        parts.push(indent + stack)
      }

      if (!isDuplicate && !startsWithHeader) {
        parts.push(indent + `${header}\n${stack}`)
      }
    }

    if (!stack && !isDuplicate) {
      parts.push(indent + header)
    }

    if (cause.cause) {
      const causeResult = formatErrorChain(cause.cause, t, depth + 1, cause.message)

      if (causeResult) {
        parts.push(causeResult)
      }
    }

    return parts.join("\n\n")
  }

  if (Predicate.isString(cause)) {
    if (depth > 0 && parentMessage === cause) return ""

    const indent = depth > 0 ? `\n${CHAIN_SEPARATOR}${t("error.chain.causedBy")}\n` : ""

    return indent + cause
  }

  const indent = depth > 0 ? `\n${CHAIN_SEPARATOR}${t("error.chain.causedBy")}\n` : ""

  return indent + safeJson(cause, t("error.page.circular"))
}

function formatError(cause: unknown, t: Translator): string {
  return formatErrorChain(cause, t, 0)
}

interface ErrorPageProps {
  error: unknown
}

export const ErrorPage: Component<ErrorPageProps> = (props) => {
  const platform = usePlatform()
  const language = useLanguage()
  const formattedError = () => formatError(props.error, language.t)
  const status = () => errorStatus(props.error)
  let recordedFatalError: Promise<void> | undefined

  const [store, setStore] = createStore<{
    actionError: string | undefined
    captureException: typeof captureException | undefined
  }>({
    actionError: undefined,
    captureException: undefined,
  })

  function ensureFatalErrorRecorded() {
    recordedFatalError ??=
      platform.recordFatalRendererError?.({
        error: formattedError(),
        url: location.href,
        version: platform.version,
        platform: platform.platform,
        os: platform.os,
      }) ?? Promise.resolve()

    return recordedFatalError
  }

  onMount(() => {
    void ensureFatalErrorRecorded().catch(() => undefined)
    void import("@sentry/solid")
      .then(({ captureException, isEnabled }) => {
        if (isEnabled()) setStore("captureException", () => captureException)
      })
      .catch(() => undefined)
  })

  // A crash can take the extension root down with the app, so the page reaches the updater's
  // main-process Ipc over the bridge itself.
  const ipcs = createIpcClients(platform.extensions)
  onCleanup(ipcs.dispose)
  const updater = () => ipcs.typed(Updater)

  async function checkForUpdates() {
    const state = await updater()?.check()
    setStore("actionError", state?.status === "error" ? state.message : undefined)
  }

  async function installUpdate() {
    await updater()
      ?.install()
      .then(() => setStore("actionError", undefined))
      .catch((err) => {
        setStore("actionError", formatError(err, language.t))
      })
  }

  const updateVersion = () => {
    const state = updater()?.state()

    return state?.status === "ready" || state?.status === "download-required" ? state.version : undefined
  }

  async function exportDebugLogs() {
    const exportLogs = platform.exportDebugLogs

    if (!exportLogs) return
    await ensureFatalErrorRecorded()
      .then(() => exportLogs())
      .then(() => setStore("actionError", undefined))
      .catch((err) => {
        setStore("actionError", formatError(err, language.t))
      })
  }

  return (
    <div
      class="relative flex-1 h-full w-full min-h-0 min-w-0 overflow-y-auto flex flex-col items-center justify-start sm:justify-center p-4 sm:p-8 font-sans"
      data-tauri-drag-region
    >
      <div class="w-full max-w-3xl flex flex-col items-center justify-center gap-6 sm:gap-8 my-auto">
        <Logo class="w-48 sm:w-58.5 opacity-12 shrink-0" />
        <div class="flex flex-col items-center gap-2 text-center">
          <h1 class="text-lg font-medium text-text-strong">
            {language.t(status() ? "error.page.title.status" : "error.page.title")}
          </h1>
          <p class="text-sm text-text-weak">
            {status()
              ? language.t("error.page.description.status", { status: status()! })
              : language.t(errorDescriptionKey(props.error))}
          </p>
        </div>
        <TextField
          value={formattedError()}
          readOnly
          copyable
          multiline
          class="max-h-96 w-full font-mono text-xs no-scrollbar"
          label={language.t("error.page.details.label")}
          hideLabel
        />
        <div class="flex flex-row items-center justify-center gap-3 flex-wrap max-w-64">
          <Button size="large" onClick={platform.restart}>
            {language.t(platform.platform === "web" ? "error.page.action.reload" : "error.page.action.restart")}
          </Button>
          <Show when={platform.platform === "desktop" && platform.exportDebugLogs}>
            <Button size="large" variant="ghost" onClick={exportDebugLogs}>
              {language.t("error.page.action.exportLogs")}
            </Button>
          </Show>
          <Show when={store.captureException}>
            {(capture) => {
              const [reported, setReported] = createSignal(false)

              return (
                <Button
                  size="large"
                  disabled={reported()}
                  onClick={() => {
                    capture()(props.error)
                    setReported(true)
                  }}
                >
                  {language.t(reported() ? "error.page.action.reported" : "error.page.action.report")}
                </Button>
              )
            }}
          </Show>
          <Show when={updater()}>
            <Show
              when={updateVersion()}
              fallback={
                <Button
                  size="large"
                  variant="ghost"
                  onClick={checkForUpdates}
                  disabled={["checking", "downloading", "installing"].includes(updater()?.state()?.status ?? "")}
                >
                  {updater()?.state()?.status === "checking"
                    ? language.t("error.page.action.checking")
                    : language.t("error.page.action.checkUpdates")}
                </Button>
              }
            >
              {(version) => (
                <Button size="large" onClick={installUpdate}>
                  {language.t("error.page.action.updateTo", { version: version() })}
                </Button>
              )}
            </Show>
          </Show>
        </div>
        <Show when={store.actionError}>
          {(message) => <p class="text-xs text-text-danger-base text-center max-w-2xl">{message()}</p>}
        </Show>
        <div class="flex flex-col items-center gap-2 text-xs text-center">
          <div class="flex flex-wrap items-center justify-center gap-1">
            {language.t("error.page.report.prefix")}
            <button
              type="button"
              class="flex items-center text-text-interactive-base gap-1"
              onClick={() => platform.openExternal("https://opencode.ai/desktop-feedback")}
            >
              <div>{language.t("error.page.report.discord")}</div>
              <Icon name="discord" class="text-text-interactive-base" />
            </button>
          </div>
          <Show when={platform.version}>
            {(version) => (
              <p class="text-xs text-text-weak">{language.t("error.page.version", { version: version() })}</p>
            )}
          </Show>
        </div>
      </div>
    </div>
  )
}

import { describe, expect, test } from "bun:test"
import type { SessionInfo } from "@opencode/client/promise"
import { closeHomeProject, errorMessage, projectForSession, toggleHomeProjectSelection } from "./helpers"
import { ServerConnection } from "@/runtime/server/registry"

const serverKey = ServerConnection.Key.make

const session = (input: Partial<SessionInfo> & Pick<SessionInfo, "id"> & { directory: string }) =>
  ({
    projectID: "project",
    title: "",
    cost: 0,
    tokens: { input: 0, output: 0, reasoning: 0, cache: { read: 0, write: 0 } },
    parentID: undefined,
    time: { created: 0, updated: 0, archived: undefined },
    ...input,
    location: { directory: input.directory },
    directory: undefined,
  }) as SessionInfo

type Project = {
  id: string
  worktree: string
  sandboxes: string[]
  worktrees?: { directory: string; strategy?: string }[]
}

const enriched: { name: string; project: Project }[] = [
  {
    name: "matching project id",
    project: {
      id: "project",
      worktree: "/repo",
      sandboxes: ["/workspaces/feature"],
      worktrees: [{ directory: "/repo" }, { directory: "/workspaces/feature", strategy: "git" }],
    },
  },
  { name: "stale project id", project: { id: "updated", worktree: "/repo", sandboxes: ["/workspaces/feature"] } },
]

describe("layout workspace helpers", () => {
  test.each(enriched)("keeps the enriched project for a nested workspace session ($name)", ({ project }) => {
    expect(
      projectForSession(session({ id: "feature", directory: "/workspaces/feature/packages/app" }), [project]),
    ).toBe(project)
  })

  test("scopes home project selection by server", () => {
    expect(
      toggleHomeProjectSelection(undefined, serverKey("https://debian.example"), "/home/luke/repos/amazon"),
    ).toEqual({
      server: serverKey("https://debian.example"),
      directory: "/home/luke/repos/amazon",
    })
    expect(
      toggleHomeProjectSelection(
        { server: serverKey("https://windows.example"), directory: "/home/luke/repos/amazon" },
        serverKey("https://debian.example"),
        "/home/luke/repos/amazon",
      ),
    ).toEqual({ server: serverKey("https://debian.example"), directory: "/home/luke/repos/amazon" })
    expect(
      toggleHomeProjectSelection(
        { server: serverKey("https://debian.example"), directory: "/home/luke/repos/amazon" },
        serverKey("https://debian.example"),
        "/home/luke/repos/amazon",
      ),
    ).toEqual({ server: serverKey("https://debian.example") })
  })

  test("closes a home project through its server context", () => {
    const closed: string[] = []

    expect(
      closeHomeProject(
        { server: serverKey("https://windows.example"), directory: "/shared" },
        serverKey("https://debian.example"),
        { close: (directory) => closed.push(directory) },
        "/shared",
      ),
    ).toEqual({ server: serverKey("https://windows.example"), directory: "/shared" })
    expect(closed).toEqual(["/shared"])
    expect(
      closeHomeProject(
        { server: serverKey("https://debian.example"), directory: "/shared" },
        serverKey("https://debian.example"),
        { close: (directory) => closed.push(directory) },
        "/shared",
      ),
    ).toEqual({ server: serverKey("https://debian.example") })
  })

  test("extracts api error message and fallback", () => {
    expect(errorMessage({ data: { message: "boom" } }, "fallback")).toBe("boom")
    expect(errorMessage(new Error("broken"), "fallback")).toBe("broken")
    expect(errorMessage("unknown", "fallback")).toBe("fallback")
  })
})

import type { SessionInfo } from "@opencode/client/promise"
import { displayName } from "@opencode/ui/project-avatar"
import { pathKey } from "@/workspaces/path-key"
import { isProjectDirectory } from "@/workspaces/paths"
import type { ServerConnection } from "@/runtime/server/registry"
import type { HomeProjectSelection } from "@/shell/state/layout"

export function compareSessionTime(a: SessionInfo, b: SessionInfo) {
  const updated = (b.time.updated ?? b.time.created) - (a.time.updated ?? a.time.created)

  if (updated !== 0) return updated

  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0
}

type ProjectAppearance = {
  name?: string
  worktree: string
  icon?: { color?: string; url?: string; override?: string }
}

function withProjectAppearance<T extends ProjectAppearance>(metadata: T, appearance?: ProjectAppearance) {
  if (!appearance || appearance === metadata) return metadata

  return { ...metadata, name: displayName(appearance), icon: appearance.icon }
}

export function toggleHomeProjectSelection(
  current: HomeProjectSelection | undefined,
  server: ServerConnection.Key,
  directory: string,
): HomeProjectSelection {
  if (current?.server === server && current.directory === directory) return { server }

  return { server, directory }
}

export function closeHomeProject(
  selected: HomeProjectSelection | undefined,
  server: ServerConnection.Key,
  projects: { close: (directory: string) => void },
  directory: string,
) {
  projects.close(directory)

  if (selected?.server === server && selected.directory === directory) return { server }

  return selected
}

export function homeProjectDirectories(result: string | string[] | null) {
  if (!result) return []

  return Array.isArray(result) ? result : [result]
}

export function projectForSession<T extends { id?: string; worktree: string; sandboxes?: string[] }>(
  session: SessionInfo,
  projects: T[],
) {
  const matching = projects.filter((project) => project.id === session.projectID)

  if (matching.length === 1) return matching[0]

  if (matching.length > 1) {
    const directory = pathKey(session.location.directory)

    const exact =
      matching.find((project) => pathKey(project.worktree) === directory) ??
      matching.find((project) => project.sandboxes?.some((sandbox) => pathKey(sandbox) === directory))

    if (exact) return exact

    return (
      matching
        .filter((project) => isProjectDirectory(project, session.location.directory))
        .sort((a, b) => b.worktree.length - a.worktree.length)[0] ?? matching.at(-1)
    )
  }

  const directory = pathKey(session.location.directory)

  const exact =
    projects.find((project) => pathKey(project.worktree) === directory) ??
    projects.find((project) => project.sandboxes?.some((sandbox) => pathKey(sandbox) === directory))

  if (exact) return exact

  return projects
    .filter((project) => isProjectDirectory(project, session.location.directory))
    .sort((a, b) => b.worktree.length - a.worktree.length)[0]
}

export function resolveProjectForSession<
  T extends { id?: string; worktree: string; sandboxes?: string[] },
  U extends { id?: string; worktree: string; sandboxes?: string[] },
>(session: SessionInfo, opened: T[], stored: U[]) {
  const current = projectForSession(session, opened)

  if (current?.id === session.projectID) {
    const unresolved = opened.find(
      (project) => !project.id && pathKey(project.worktree) === pathKey(session.location.directory),
    )

    if (!unresolved) return current
    const canonical = projectForSession(session, stored)

    if (canonical?.id === session.projectID && pathKey(canonical.worktree) === pathKey(unresolved.worktree))
      return unresolved

    return current
  }

  const synced = projectForSession(session, stored)

  if (synced?.id !== session.projectID) return current ?? synced

  if (current && !current.id && pathKey(current.worktree) === pathKey(session.location.directory)) return current

  return synced
}

export function resolveSessionDetailsProject<
  T extends ProjectAppearance & { id?: string; sandboxes?: string[] },
  U extends ProjectAppearance & { id?: string; sandboxes?: string[] },
>(session: SessionInfo, opened: T[], stored: U[]) {
  const metadata = projectForSession(session, stored)

  if (!metadata) return

  return withProjectAppearance(metadata, resolveProjectForSession(session, opened, stored))
}

export const errorMessage = (err: unknown, fallback: string) => {
  if (err && typeof err === "object" && "data" in err) {
    const data = (err as { data?: { message?: string } }).data

    if (data?.message) return data.message
  }

  if (err instanceof Error) return err.message

  return fallback
}

import { createMemo, type Accessor } from "solid-js"
import type { SessionInfo } from "@opencode/client/promise"
import { useGlobal, useServerCtx } from "@/runtime/server/runtime"
import { sessionPermissionRequest, sessionFormRequest } from "@/session/requests/session-request-tree"
import { ServerConnection } from "@/runtime/server/registry"
import { projectSettingsKey, useSettings } from "@/settings/model"

export function useSessionTabAvatarState(
  server: Accessor<ServerConnection.Key>,
  sessionId: Accessor<string>,
  root?: Accessor<boolean>,
  snapshot?: Accessor<SessionInfo | undefined>,
) {
  const global = useGlobal()
  const settings = useSettings()
  const connection = createMemo(() => global.servers.list().find((item) => ServerConnection.key(item) === server()))
  const serverCtx = useServerCtx(connection)

  const sessions = createMemo(() => {
    const data = serverCtx()?.data

    if (!data) return []

    if (!root?.()) return data.session.list()
    const id = sessionId()

    return [...new Set([id, ...data.session.family(id)])].flatMap((id) => {
      const info = data.session.get(id)

      return info ? [info] : []
    })
  })

  const hasPermissions = createMemo(() => {
    const ctx = serverCtx()

    if (!ctx) return false

    const project = projectSettingsKey(ctx.sdk.scope, ctx.data.session.get(sessionId())?.projectID)

    if (settings.permissions.autoApproves(project)) return false

    return !!sessionPermissionRequest(sessions(), ctx.data.session.permission.list, sessionId())
  })

  const hasForms = createMemo(() => {
    const data = serverCtx()?.data

    if (!data) return false

    return !!sessionFormRequest(sessions(), data.session.form.list, sessionId())
  })

  const needsAttention = createMemo(() => hasPermissions() || hasForms())

  const unread = createMemo(
    () => needsAttention() || (serverCtx()?.notification.session.unread(sessionId(), snapshot?.()) ?? false),
  )

  const loading = createMemo(() => {
    const data = serverCtx()?.data

    if (!data) return false

    if (needsAttention()) return false

    // Like the TUI, work waiting in the inbox counts as busy; parked synthetic context does not.
    const busy = (id: string) =>
      data.session.status(id) === "running" || data.session.pending.list(id).some((item) => item.type !== "synthetic")

    if (root?.())
      return data.session.list().some((session) => data.session.root(session.id) === sessionId() && busy(session.id))

    return busy(sessionId())
  })

  return { unread, loading }
}

import {
  displayName,
  getProjectAvatarSource,
  getProjectAvatarVariant,
  ProjectAvatar,
  type ProjectAvatarProps,
} from "@opencode/ui/project-avatar"
import { splitProps } from "solid-js"
import type { LocalProject } from "@/shell/state/layout"

type ProjectIconProps = Omit<ProjectAvatarProps, "fallback" | "src" | "variant"> & {
  project: Pick<LocalProject, "id" | "name" | "worktree" | "icon">
  fallback?: string
  icon?: LocalProject["icon"]
}

export function ProjectIcon(props: ProjectIconProps) {
  const [local, rest] = splitProps(props, ["project", "fallback", "icon"])
  const icon = () => local.icon ?? local.project.icon

  return (
    <ProjectAvatar
      {...rest}
      fallback={local.fallback ?? displayName(local.project)}
      src={getProjectAvatarSource(local.project.id, icon())}
      variant={getProjectAvatarVariant(icon()?.color)}
    />
  )
}

import type { LocalProject } from "@/shell/state/layout"
import type { ServerConnection } from "@/runtime/server/registry"
import { useSessionTabAvatarState } from "@/shell/layout/project-avatar-state"
import {
  displayName,
  getProjectAvatarSource,
  getProjectAvatarVariant,
  ProjectAvatar,
} from "@opencode/ui/project-avatar"
import { SessionProgressIndicatorV2 } from "@opencode/session-ui/v2/session-progress-indicator-v2"
import { Show } from "solid-js"

export function SessionTabAvatar(props: {
  project?: LocalProject
  directory: string
  sessionId: string
  server: ServerConnection.Key
}) {
  const state = useSessionTabAvatarState(
    () => props.server,
    () => props.sessionId,
    () => true,
  )

  return (
    <SessionTabAvatarView
      project={props.project}
      directory={props.directory}
      unread={state.unread()}
      loading={state.loading()}
    />
  )
}

export function SessionTabAvatarView(props: {
  project?: LocalProject
  directory: string
  unread: boolean
  loading: boolean
}) {
  return (
    <Show
      when={props.loading}
      fallback={
        <ProjectAvatar
          fallback={displayName(props.project ?? { worktree: props.directory })}
          src={getProjectAvatarSource(props.project?.id, props.project?.icon)}
          variant={getProjectAvatarVariant(props.project?.icon?.color)}
          unread={props.unread}
        />
      }
    >
      <SessionProgressIndicatorV2 />
    </Show>
  )
}

import Drawer from "@corvu/drawer"
import type { ParentProps } from "solid-js"
import { useLanguage } from "@/runtime/i18n/language"
import "./mobile-drawer.css"

export function MobileDrawer(
  props: ParentProps<{
    open: boolean
    onOpenChange: (open: boolean) => void
    onContentPresentChange?: (present: boolean) => void
    initialFocus?: () => HTMLElement | undefined
    returnFocus?: () => HTMLElement | undefined
    onFinalFocus?: (event: Event) => void
    closeOnOutsideFocus?: boolean
  }>,
) {
  return (
    <Drawer
      open={props.open}
      onOpenChange={props.onOpenChange}
      onContentPresentChange={props.onContentPresentChange}
      side="bottom"
      initialFocusEl={props.initialFocus?.()}
      finalFocusEl={props.returnFocus?.()}
      onFinalFocus={props.onFinalFocus}
      closeOnOutsideFocus={props.closeOnOutsideFocus}
    >
      {props.children}
    </Drawer>
  )
}

export const MobileDrawerTrigger = Drawer.Trigger

export function MobileDrawerContent(props: ParentProps) {
  const language = useLanguage()

  return (
    <Drawer.Portal forceMount>
      <Drawer.Overlay data-slot="mobile-drawer-overlay" />
      <Drawer.Content forceMount data-slot="mobile-drawer-content" dir={language.direction()}>
        <div data-slot="mobile-drawer-handle" aria-hidden="true">
          <span />
        </div>
        {props.children}
      </Drawer.Content>
    </Drawer.Portal>
  )
}

export const MobileDrawerLabel = Drawer.Label

export const MobileDrawerClose = Drawer.Close

import { createEffect, on, Show, type JSX, type ParentProps } from "solid-js"
import { createStore } from "solid-js/store"
import { Button } from "@opencode/ui/button"
import { DrawerContext } from "@opencode/gui-extensions/sdk"
import { useLanguage } from "@/runtime/i18n/language"
import { MobileDrawer, MobileDrawerClose, MobileDrawerContent, MobileDrawerLabel } from "./mobile-drawer"
import "./mobile-panel-drawer.css"

type DrawerView = { title: string; content: JSX.Element; trigger: HTMLElement }

export function MobilePanelDrawer(
  props: ParentProps<{
    title: string
    hideHeader?: boolean
    open: boolean
    onOpenChange: (open: boolean) => void
    onContentPresentChange?: (present: boolean) => void
    initialFocus?: () => HTMLElement | undefined
    returnFocus?: () => HTMLElement | undefined
    onFinalFocus?: (event: Event) => void
  }>,
) {
  const language = useLanguage()
  const [store, setStore] = createStore<{ view?: DrawerView }>({})
  createEffect(
    on(
      () => props.open,
      (open) => {
        if (open) setStore("view", undefined)
      },
    ),
  )

  const navigation = {
    close: () => props.onOpenChange(false),
    open: (view: DrawerView) => setStore("view", view),
    back: () => {
      const trigger = store.view?.trigger
      setStore("view", undefined)
      trigger?.focus()
    },
  }

  return (
    <DrawerContext.Provider value={navigation}>
      <MobileDrawer
        open={props.open}
        onOpenChange={props.onOpenChange}
        onContentPresentChange={props.onContentPresentChange}
        initialFocus={props.initialFocus}
        returnFocus={props.returnFocus}
        onFinalFocus={props.onFinalFocus}
        // Menu focus handoff must not dismiss the drawer during its opening transition.
        closeOnOutsideFocus={false}
      >
        <MobileDrawerContent>
          <div data-slot="mobile-panel" data-corvu-no-drag>
            <Show
              when={!props.hideHeader}
              fallback={<MobileDrawerLabel class="sr-only">{store.view?.title ?? props.title}</MobileDrawerLabel>}
            >
              <div data-slot="mobile-panel-header">
                <MobileDrawerLabel>{store.view?.title ?? props.title}</MobileDrawerLabel>
                <MobileDrawerClose
                  as={Button}
                  variant="ghost"
                  data-slot="mobile-panel-close"
                  aria-label={language.t("common.close")}
                >
                  {language.t("common.close")}
                </MobileDrawerClose>
              </div>
            </Show>
            <div data-slot="mobile-panel-content">
              <div hidden={!!store.view}>{props.children}</div>
              <Show when={store.view}>
                {(view) => (
                  <>
                    <Button
                      variant="ghost"
                      icon="arrow-left"
                      class="mb-2 !justify-start"
                      aria-label={language.t("common.goBack")}
                      onClick={navigation.back}
                    >
                      {props.title}
                    </Button>
                    {view().content}
                  </>
                )}
              </Show>
            </div>
          </div>
        </MobileDrawerContent>
      </MobileDrawer>
    </DrawerContext.Provider>
  )
}

import { onCleanup } from "solid-js"

const FOCUS_LOCK = "opencode:notification-focus"

const MAX_CLAIMED = 500

export function createNotificationCoordinator() {
  const locks = typeof navigator === "undefined" ? undefined : navigator.locks
  const claimed = new Set<string>()
  const focus = { pending: false, release: undefined as (() => void) | undefined }

  const updateFocus = () => {
    if (typeof document === "undefined" || !document.hasFocus()) {
      focus.release?.()

      return
    }

    if (!locks || focus.pending || focus.release) return

    focus.pending = true
    void locks
      .request(FOCUS_LOCK, { mode: "shared" }, async () => {
        focus.pending = false

        if (!document.hasFocus()) return
        await new Promise<void>((resolve) => {
          focus.release = resolve
        })
        focus.release = undefined
      })
      .catch(() => {
        focus.pending = false
      })
  }

  if (typeof window !== "undefined") {
    window.addEventListener("focus", updateFocus)
    window.addEventListener("blur", updateFocus)
    document.addEventListener("visibilitychange", updateFocus)
    updateFocus()
    onCleanup(() => {
      window.removeEventListener("focus", updateFocus)
      window.removeEventListener("blur", updateFocus)
      document.removeEventListener("visibilitychange", updateFocus)
      focus.release?.()
    })
  }

  const once = async (kind: "sound" | "system", eventID: string, run: () => Promise<unknown> | void) => {
    const key = `${kind}:${eventID}`

    const execute = async () => {
      if (!claim(kind, key, claimed)) return
      await run()
    }

    if (!locks) return execute()
    await locks.request(`opencode:notification:${key}`, execute)
  }

  return {
    sound(eventID: string, run: () => Promise<unknown> | void) {
      return once("sound", eventID, run)
    },
    system(eventID: string, run: () => Promise<unknown> | void) {
      return once("system", eventID, async () => {
        if (typeof document !== "undefined" && document.hasFocus()) return

        if (!locks) return run()
        await locks.request(FOCUS_LOCK, { mode: "exclusive", ifAvailable: true }, async (lock) => {
          if (!lock) return
          await run()
        })
      })
    },
  }
}

function claim(kind: "sound" | "system", eventID: string, claimed: Set<string>) {
  if (claimed.has(eventID)) return false

  if (typeof localStorage !== "undefined") {
    try {
      const storageKey = `opencode:notification-${kind}`
      const value: unknown = JSON.parse(localStorage.getItem(storageKey) ?? "[]")
      const events = Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : []

      if (events.includes(eventID)) {
        claimed.add(eventID)

        return false
      }

      localStorage.setItem(storageKey, JSON.stringify([...events, eventID].slice(-MAX_CLAIMED)))
    } catch {
      // The in-memory claim still prevents duplicates in this renderer when storage is unavailable.
    }
  }

  claimed.add(eventID)

  return true
}

import { expect, test } from "bun:test"
import type { ServerConnection } from "@/runtime/server/registry"
import type { Tab } from "@/shell/tabs/tabs"
import { openNotificationSession } from "./notification"

test("opens notification sessions through the tab router", () => {
  const server = "local\nhttp://localhost:4096" as ServerConnection.Key
  const tab = { type: "session" as const, server, sessionId: "session-1" }
  const calls: string[] = []

  const tabs = {
    addSessionTab: (input: Omit<typeof tab, "type">) => {
      calls.push(`add:${input.sessionId}`)

      return tab
    },
    rememberSessionRoute: (_tab: typeof tab, sessionID: string) => {
      calls.push(`route:${sessionID}`)
    },
    select: (input: Tab) => {
      calls.push(`select:${input.type === "session" ? input.sessionId : input.draftID}`)
    },
  }

  openNotificationSession(tabs, server, "session-1")

  expect(calls).toEqual(["add:session-1", "route:session-1", "select:session-1"])
})

import { createEffect, createMemo, onCleanup, untrack } from "solid-js"
import { createStore } from "solid-js/store"
import { Schema } from "effect"
import type { SessionInfo } from "@opencode/client/promise"
import type { ServerSDK } from "@/runtime/server/client"
import type { Data } from "@opencode/client/solid"
import { usePlatform } from "@/runtime/platform/platform"
import { useLanguage } from "@/runtime/i18n/language"
import { useSettings } from "@/settings/model"
import { Persist, persisted, removePersisted } from "@/runtime/persistence/storage"
import { Persistence } from "@/runtime/persistence/schema"
import { playSoundById } from "@/shell/notifications/sound"
import type { createNotificationCoordinator } from "@/shell/notifications/coordinator"
import { ServerConnection } from "@/runtime/server/registry"
import { sessionIDHasOpenTab, useTabs } from "@/shell/tabs/tabs"
import { useServer } from "@/runtime/server/current"

type NotificationTabs = Pick<ReturnType<typeof useTabs>, "addSessionTab" | "rememberSessionRoute" | "select">

export function openNotificationSession(tabs: NotificationTabs, server: ServerConnection.Key, sessionID: string) {
  const tab = tabs.addSessionTab({ server, sessionId: sessionID })

  if (tab.type !== "session") return
  tabs.rememberSessionRoute(tab, sessionID)
  tabs.select(tab)
}

/** A session is unread when its latest terminal execution is newer than the last one any client viewed. */
function isSessionUnread(session?: Pick<SessionInfo, "time">) {
  const time = session?.time

  return time?.idle !== undefined && (time.viewed === undefined || time.idle > time.viewed)
}

// The list Desktop kept before unread state moved to the server. Until its viewed state reaches the server, unread
// state still honours it, so sessions read here don't light up while the server catches up.
const LegacyNotificationStore = Persistence.struct({
  list: Schema.optional(
    Persistence.array(Persistence.struct({ session: Schema.optional(Schema.String), viewed: Schema.Boolean })),
  ),
  // When this client first found the list. Sessions that went idle later are new, whatever the list says.
  started: Schema.optional(Schema.Finite),
})

// The carry-over waits this long after connecting so it doesn't compete with startup requests.
const LEGACY_MIGRATION_DELAY = 5_000

const LEGACY_MIGRATION_PAGE = 200

const LEGACY_MIGRATION_CONCURRENCY = 4

const VIEW_RETRY_DELAY = 250

const VIEW_RETRY_MAX_DELAY = 5_000

export function createServerNotificationState(input: {
  sdk: ServerSDK
  data: Data
  key: ServerConnection.Key
  coordinator: ReturnType<typeof createNotificationCoordinator>
}) {
  const platform = usePlatform()
  const settings = useSettings()
  const language = useLanguage()
  const tabs = useTabs()
  const disposed = { value: false }
  // Idle watermarks already reported per root session, so reactive re-runs don't re-post them.
  const acknowledged = new Map<string, number>()
  // A failed view report re-runs the tracking caller with backoff, like the TUI.
  const [state, setState] = createStore({ viewRetry: 0, legacyMigrated: false })
  let viewRetryTimer: ReturnType<typeof setTimeout> | undefined
  let viewRetryAttempt = 0
  onCleanup(() => clearTimeout(viewRetryTimer))

  const legacyTarget = Persist.serverGlobal(input.sdk.scope, "notification")
  const [legacy, setLegacy, , legacyReady] = persisted(legacyTarget, LegacyNotificationStore, {}, platform)
  const started = Date.now()
  const legacyStarted = () => legacy.started ?? started

  // Sessions the old list still had unread, while its viewed state hasn't reached the server yet.
  const legacyUnseen = createMemo(() => {
    const list = legacy.list

    if (!list || state.legacyMigrated) return

    return new Set(list.flatMap((item) => (!item.viewed && item.session ? [item.session] : [])))
  })

  // Idle watermarks the carry-over reported, so rows drawn from an older fetched copy of a session stay read.
  const legacyReported = new Map<string, number>()

  const unread = (session?: Pick<SessionInfo, "id" | "time">) => {
    const idle = session?.time.idle

    // Until the old list is read, a session it had read could flash unread.
    if (!legacyReady() || !session || idle === undefined || !isSessionUnread(session)) return false

    if (idle <= (legacyReported.get(session.id) ?? -Infinity)) return false
    const unseen = legacyUnseen()

    return !unseen || unseen.has(session.id) || idle > legacyStarted()
  }

  // Carry the old list's viewed state to the server in the background: page through every root session and report
  // the ones the server has unread but this client shows read. Then delete the list. A failure keeps it, and the
  // next connection retries; reports already made are skipped because the server then has them read.
  let legacyMigration: "idle" | "scheduled" | "running" = "idle"

  const migrateLegacy = async () => {
    legacyMigration = "running"
    let cursor: string | undefined

    for (;;) {
      const page = await input.sdk.api.session.list({
        limit: LEGACY_MIGRATION_PAGE,
        order: "desc",
        parentID: null,
        cursor,
      })

      const hidden = page.data.flatMap((session) =>
        session.time.idle !== undefined && isSessionUnread(session) && !unread(session)
          ? [{ sessionID: session.id, idle: session.time.idle }]
          : [],
      )

      for (let index = 0; index < hidden.length; index += LEGACY_MIGRATION_CONCURRENCY) {
        if (disposed.value) return

        await Promise.all(
          hidden.slice(index, index + LEGACY_MIGRATION_CONCURRENCY).map(async (report) => {
            await input.sdk.api.session.view(report)
            legacyReported.set(report.sessionID, report.idle)
          }),
        )
      }

      if (page.data.length === 0 || !page.cursor.next) break
      cursor = page.cursor.next
    }

    removePersisted(legacyTarget, platform)
    setState("legacyMigrated", true)
  }

  createEffect(() => {
    if (!legacyReady() || !legacyUnseen()) return

    if (untrack(() => legacy.started) === undefined) setLegacy("started", started)

    if (input.sdk.connection.status() !== "connected" || legacyMigration !== "idle") return
    legacyMigration = "scheduled"

    const timer = setTimeout(
      () =>
        void migrateLegacy().catch(() => {
          legacyMigration = "idle"
        }),
      LEGACY_MIGRATION_DELAY,
    )

    onCleanup(() => {
      clearTimeout(timer)

      if (legacyMigration === "scheduled") legacyMigration = "idle"
    })
  })

  const roots = (directory: string) =>
    input.data.session
      .list()
      .filter(
        (session) =>
          !session.parentID && session.time.archived === undefined && session.location.directory === directory,
      )

  const view = (sessionID: string) => {
    void state.viewRetry
    const root = input.data.session.root(sessionID)
    const session = input.data.session.get(root)
    const idle = session?.time.idle

    if (idle === undefined || !isSessionUnread(session) || acknowledged.get(root) === idle) return
    acknowledged.set(root, idle)
    void input.sdk.api.session.view({ sessionID: root, idle }).then(
      () => {
        clearTimeout(viewRetryTimer)
        viewRetryTimer = undefined
        viewRetryAttempt = 0
      },
      () => {
        if (acknowledged.get(root) !== idle) return
        acknowledged.delete(root)

        if (viewRetryTimer) return

        const delay = Math.min(VIEW_RETRY_DELAY * 2 ** viewRetryAttempt, VIEW_RETRY_MAX_DELAY)
        viewRetryAttempt++
        viewRetryTimer = setTimeout(() => {
          viewRetryTimer = undefined
          setState("viewRetry", (value) => value + 1)
        }, delay)
      },
    )
  }

  // Loading the session keeps a background completion visible in the server-derived unread state.
  const lookup = async (sessionID: string) => {
    const session = input.data.session.get(sessionID)

    if (session) return session

    return input.data.session
      .sync(sessionID)
      .then(() => input.data.session.get(sessionID))
      .catch(() => undefined)
  }

  const handleSessionIdle = (sessionID: string, eventID: string) => {
    void lookup(sessionID).then((session) => {
      if (disposed.value) return

      if (!session) return

      if (session.parentID) return

      const hasOpenTab = sessionIDHasOpenTab(tabs.store, input.key, sessionID)

      if (hasOpenTab && settings.sounds.agentEnabled()) {
        void input.coordinator.sound(`${input.key}\0${eventID}`, () => playSoundById(settings.sounds.agent()))
      }

      if (hasOpenTab && settings.notifications.agent()) {
        void input.coordinator.system(`${input.key}\0${eventID}`, () =>
          platform.notify(language.t("notification.session.responseReady.title"), session.title ?? sessionID, () =>
            openNotificationSession(tabs, input.key, sessionID),
          ),
        )
      }
    })
  }

  const handleSessionError = (sessionID: string, eventID: string) => {
    void lookup(sessionID).then((session) => {
      if (disposed.value) return

      if (session?.parentID) return

      const hasOpenTab = sessionIDHasOpenTab(tabs.store, input.key, sessionID)

      if (hasOpenTab && settings.sounds.errorsEnabled()) {
        void input.coordinator.sound(`${input.key}\0${eventID}`, () => playSoundById(settings.sounds.errors()))
      }

      const description = session?.title ?? language.t("notification.session.error.fallbackDescription")

      if (hasOpenTab && settings.notifications.errors()) {
        void input.coordinator.system(`${input.key}\0${eventID}`, () =>
          platform.notify(language.t("notification.session.error.title"), description, () =>
            openNotificationSession(tabs, input.key, sessionID),
          ),
        )
      }
    })
  }

  const unsub = input.sdk.event.listen((event) => {
    if (event.type === "session.execution.failed") {
      handleSessionError(event.data.sessionID, event.id)

      return
    }

    if (event.type === "session.execution.succeeded") handleSessionIdle(event.data.sessionID, event.id)
  })

  onCleanup(() => {
    disposed.value = true
    unsub()
  })

  return {
    session: {
      /**
       * Whether the session's root has an execution result no client has viewed yet. `snapshot` stands in for a root
       * session that isn't loaded, such as a row from the fetched home index.
       */
      unread(sessionID: string, snapshot?: SessionInfo) {
        return unread(input.data.session.get(input.data.session.root(sessionID)) ?? snapshot)
      },
      /** Reports the session's latest idle transition to the server as viewed. */
      markViewed: view,
    },
    project: {
      hasUnread(directory: string) {
        return roots(directory).some((session) => unread(session))
      },
      markViewed(directory: string) {
        roots(directory).forEach((session) => view(session.id))
      },
    },
  }
}

export const useNotification = () => {
  const server = useServer()

  return server.ctx.notification
}

import { Icon, type IconProps } from "@opencode/ui/icon"
import { Toast, showToast, toaster, type ToastOptions } from "@opencode/ui/toast"
import type { JSX } from "solid-js"

type AppToastOptions = Omit<ToastOptions, "icon"> & {
  icon?: IconProps["name"]
}

export function ToastRegion() {
  return <Toast.Region />
}

function showAppToast(options: AppToastOptions | string) {
  if (typeof options === "string") return showToast(options)

  return showToast({
    ...options,
    icon: resolveIcon(options.icon, options.variant),
    actions: options.actions?.map((action) => ({
      ...action,
      variant: action.onClick === "dismiss" ? "secondary" : "primary",
    })),
  })
}

export { showAppToast as showToast }

export function dismissToast(toastId: number) {
  return toaster.dismiss(toastId)
}

function resolveIcon(icon: IconProps["name"] | undefined, variant: ToastOptions["variant"]) {
  const name = icon ?? (variant === "success" ? "check" : undefined)

  if (!name) return undefined

  // Solid resolves JSX accessors under the toast's render owner, not this imperative call site.
  return (() => <Icon name={name} />) as unknown as JSX.Element
}

import { Route, useParams } from "@solidjs/router"
import { createMemo, lazy, Show, Suspense, type ParentProps } from "solid-js"
import { Home } from "@/home/route"
import { ServerProvider } from "@/runtime/server/current"
import { useGlobal } from "@/runtime/server/runtime"
import { ServerConnection, useServers } from "@/runtime/server/registry"
import { SessionPanelFrame, SessionRouteFrame } from "@/session/session-frame"
import { LayoutProvider } from "@/shell/state/layout"
import { SettingsSurfaceProvider } from "@/settings/surface"
import Shell from "@/shell/shell"
import { requireServerKey } from "./session"
import { ExtensionAttachment } from "@/runtime/extension/root"

export const File = lazy(() => import("@opencode/session-ui/file").then((module) => ({ default: module.File })))

const loadSessionRoute = () => Promise.all([import("@/session/route"), File.preload()]).then(([module]) => module)

const DraftRoute = lazy(() => import("@/new-session/route").then((module) => ({ default: module.DraftRoute })))

const SettingsScreen = lazy(() => import("@/settings/shell").then((module) => ({ default: module.SettingsScreen })))

const ConnectServerScreen = lazy(() =>
  import("@/servers/connect/screen").then((module) => ({ default: module.ConnectServerScreen })),
)

const TargetSessionRouteContent = lazy(() =>
  loadSessionRoute().then((module) => ({ default: module.TargetSessionRouteContent })),
)

export function preloadRoute(url: string) {
  const pathname = url.split(/[?#]/, 1)[0]

  if (pathname === "/new-session") return DraftRoute.preload().then(() => undefined)

  if (pathname === "/settings") return SettingsScreen.preload().then(() => undefined)

  if (/^\/server\/[^/]+\/session\/[^/]+$/.test(pathname))
    return TargetSessionRouteContent.preload().then(() => undefined)

  return Promise.resolve()
}

export function AppRoutes() {
  return (
    <Route component={AppLayout}>
      <Route path="/" component={Home} />
      <Route path="/settings" component={SettingsScreen} />
      <Route
        path="/server/:serverKey/session/:id"
        component={() => (
          <SessionRouteFrame>
            <Suspense
              fallback={
                <div class="flex min-h-0 flex-1 px-[var(--shell-inline-inset,8px)] pb-[var(--shell-bottom-inset,8px)] pt-[var(--shell-top-inset,8px)]">
                  <SessionPanelFrame raised />
                </div>
              }
            >
              <TargetServerRoute>
                <TargetSessionRouteContent />
              </TargetServerRoute>
            </Suspense>
          </SessionRouteFrame>
        )}
      />
      <Route path="/new-session" component={DraftRoute} />
    </Route>
  )
}

function TargetServerRoute(props: ParentProps) {
  const params = useParams<{ serverKey: string }>()
  const global = useGlobal()

  const connection = createMemo(() =>
    global.servers.list().find((item) => ServerConnection.key(item) === requireServerKey(params.serverKey)),
  )

  return (
    <Show when={connection()} keyed>
      {(connection) => <ServerProvider conn={connection}>{props.children}</ServerProvider>}
    </Show>
  )
}

function AppLayout(props: ParentProps) {
  const servers = useServers()
  const global = useGlobal()

  // A lone server that rejects our credentials (e.g. the web app before pairing) has nothing else to show.
  const signedOut = () => {
    const only = servers.list.length === 1 ? servers.list[0] : undefined

    if (only?.type !== "http") return

    return global.servers.health[ServerConnection.key(only)]?.unauthorized ? only : undefined
  }

  return (
    <Show when={servers.list.length > 0 && !signedOut()} fallback={<ConnectServerScreen url={signedOut()?.http.url} />}>
      <LayoutProvider>
        <SettingsSurfaceProvider>
          <ExtensionAttachment>
            <Shell>{props.children}</Shell>
          </ExtensionAttachment>
        </SettingsSurfaceProvider>
      </LayoutProvider>
    </Show>
  )
}

import { DataProvider } from "@opencode/session-ui/context"
import { MarkdownProvider, type ReadMarkdownImage } from "@opencode/session-ui/context/markdown"
import { useNavigate, useParams } from "@solidjs/router"
import { createMemo, type ParentProps } from "solid-js"
import { useProviders } from "@/providers/catalog/providers"
import { LocalProvider } from "@/providers/models/selection"
import type { ServerConnection } from "@/runtime/server/registry"
import { sessionHref } from "@/shell/routes/session"
import { useData } from "@/runtime/server/current"
import { useServerSDK } from "@/runtime/server/client"
import { useTabs, type Tab } from "@/shell/tabs/tabs"
import { readLocalImage } from "@/runtime/server/image"
import { useLanguage } from "@/runtime/i18n/language"
