import { createStore, produce, reconcile } from "solid-js/store"
import { Predicate, Schema, SchemaGetter } from "effect"
import { batch, createEffect, createMemo, onCleanup, onMount, untrack, type Accessor } from "solid-js"
import { useLocation } from "@solidjs/router"
import { createSimpleContext } from "@opencode/ui/context"
import { makeEventListener } from "@solid-primitives/event-listener"
import { ServerConnection, useServers } from "@/runtime/server/registry"
import { usePlatform } from "@/runtime/platform/platform"
import type { Project } from "@/runtime/server/types"
import { Persist, persisted, removePersisted } from "@/runtime/persistence/storage"
import { Persistence } from "@/runtime/persistence/schema"
import { TabStorage } from "@/shell/tabs/schema"
import { createScrollPersistence, type SessionScroll } from "./scroll"
import { SessionStateKey } from "@/runtime/server/scope"
import { createSessionKeyReader, ensureSessionKey, pruneSessionKeys } from "./helpers"
import { requireServerKey } from "@/shell/routes/session"
import { closeSessionTab, openSessionTab, previewSessionTab } from "./session-tabs"

const DEFAULT_SIDEBAR_WIDTH = 344

const DEFAULT_FILE_TREE_WIDTH = 200

const DEFAULT_SESSION_WIDTH = 600

const DEFAULT_DOCK_HEIGHT = 280

export type LocalProject = Partial<Project> & { worktree: string; expanded: boolean }

export type HomeProjectSelection = typeof layoutSchema.Type.home.selection

export type TabRegions = {
  dockOpened: Accessor<boolean>
  setDockOpened(opened: boolean): void
  dockHeight: Accessor<number | undefined>
  setDockHeight(height: number): void
  sideOpened: Accessor<boolean>
  setSideOpened(opened: boolean): void
  sessionWidth: Accessor<number | undefined>
  setSessionWidth(width: number): void
}

export type LayoutRoute =
  | { type: "home" }
  | { type: "settings" }
  | { type: "connect" }
  | { type: "draft"; draftID: string }
  | { type: "session"; sessionId: string; server: ServerConnection.Key }

export const currentRoute = (pathname: string, search: string): LayoutRoute => {
  const parts = pathname.split("/").filter(Boolean)

  if (parts.length === 0) return { type: "home" }

  if (parts[0] === "settings") return { type: "settings" }

  if (parts[0] === "connect") return { type: "connect" }

  if (parts[0] === "new-session") {
    const draftID = new URLSearchParams(search).get("draftId")

    if (!draftID) return { type: "home" }

    return { type: "draft", draftID }
  }

  if (parts[0] === "server" && parts[2] === "session" && parts[3]) {
    return {
      type: "session",
      sessionId: parts[3],
      server: requireServerKey(parts[1]),
    }
  }

  throw new Error("Unrecognised route!")
}

export const useCurrentRoute = () => {
  const location = useLocation()

  return createMemo(() => currentRoute(location.pathname, location.search))
}

const sessionTabsSchema = Persistence.struct({
  all: Persistence.array(Schema.String),
  active: Persistence.optional(Schema.String),
})

const sessionViewSchema = Persistence.struct({
  scroll: Persistence.record(Schema.Struct({ x: Schema.Finite, y: Schema.Finite })),
  // Review state from before extensions. An extension copies each session's entry out once; nothing writes these
  // any more, and they stay so layout rewrites cannot drop a session's entry before it is copied.
  reviewOpen: Schema.optional(Persistence.array(Schema.String)),
  reviewMode: Schema.optional(Schema.Literals(["git", "branch", "turn"])),
  reviewFile: Schema.optional(Schema.String),
  pendingMessage: Schema.optional(Schema.String),
  pendingMessageAt: Schema.optional(Schema.Finite),
})

export const layoutSchema = Persistence.struct({
  sidebar: Persistence.struct({
    opened: Schema.Boolean,
    width: Schema.Finite,
    workspaces: Persistence.record(Schema.Boolean),
    workspacesDefault: Schema.Boolean,
  }),
  // The dock and side region state moved to per-tab regions; these fields stay so stored layouts keep decoding.
  terminal: Persistence.struct({ height: Schema.Finite, opened: Schema.Boolean }),
  review: Persistence.struct({
    panelOpened: Schema.Boolean,
    // Owned by the review extension, which copies it out once; kept so layout rewrites cannot drop it first.
    diffStyle: Schema.optional(Schema.Literals(["unified", "split"])),
  }),
  fileTree: Persistence.struct({
    opened: Schema.Boolean,
    width: Schema.Finite,
    // The file extension owns the tree's tab now. The stored field stays so the migration below
    // keeps telling current layouts from ones saved before the tab existed.
    tab: Schema.Literals(["changes", "all"]),
  }),
  session: Persistence.struct({ width: Schema.Finite }),
  mobileSidebar: Persistence.struct({ opened: Schema.Boolean }),
  sessionTabs: Persistence.record(Persistence.fallback(sessionTabsSchema, () => ({ all: [] }))),
  sessionView: Persistence.record(Persistence.fallback(sessionViewSchema, () => ({ scroll: {} }))),
  home: Persistence.struct({
    selection: Persistence.struct({
      server: Schema.optional(TabStorage.ServerKey),
      directory: Schema.optional(Schema.String),
    }),
  }),
})

export const layoutPersistence = Persistence.migrate(
  layoutSchema,
  Persistence.legacy({
    sidebar: Persistence.optional(
      Persistence.legacy({
        workspaces: Persistence.optional(Schema.Union([Schema.Boolean, Schema.Record(Schema.String, Schema.Boolean)])),
        workspacesDefault: Persistence.optional(Schema.Boolean),
      }),
    ),
    review: Persistence.optional(Persistence.legacy({ panelOpened: Persistence.optional(Schema.Boolean) })),
    fileTree: Persistence.optional(
      Persistence.legacy({
        opened: Persistence.optional(Schema.Boolean),
        width: Persistence.optional(Schema.Finite),
        tab: Persistence.optional(Schema.Literals(["changes", "all"])),
      }),
    ),
    sessionTabs: layoutSchema.fields.sessionTabs,
    sessionView: layoutSchema.fields.sessionView,
  }).pipe(
    Schema.decode({
      decode: SchemaGetter.transform((value) => ({
        ...value,
        sidebar: Predicate.isBoolean(value.sidebar?.workspaces)
          ? { ...value.sidebar, workspaces: {}, workspacesDefault: value.sidebar.workspaces }
          : value.sidebar,
        // Only an existing review section inherits the old file-tree panel flag.
        review: value.review
          ? { ...value.review, panelOpened: value.review.panelOpened ?? value.fileTree?.opened }
          : value.review,
        fileTree:
          value.fileTree && !value.fileTree.tab
            ? {
                ...value.fileTree,
                opened: true,
                width: value.fileTree.width === 260 ? DEFAULT_FILE_TREE_WIDTH : value.fileTree.width,
                tab: "changes" as const,
              }
            : value.fileTree,
        sessionTabs: Object.fromEntries(
          Object.entries(value.sessionTabs)
            .filter(([key]) => SessionStateKey.is(key))
            .map(([key, tabs]) => [key, { all: [...new Set(tabs.all)], active: tabs.active }]),
        ),
        sessionView: Object.fromEntries(Object.entries(value.sessionView).filter(([key]) => SessionStateKey.is(key))),
      })),
      encode: SchemaGetter.transform((value) => value),
    }),
  ),
)

/** The session key the user is on, whether pruning ran, and when each session key was last used. */
type SessionKeyUsage = { active: string | undefined; pruned: boolean; used: Map<string, number> }

export function initialLayout(server?: ServerConnection.Key): typeof layoutSchema.Type {
  return {
    sidebar: { opened: false, width: DEFAULT_SIDEBAR_WIDTH, workspaces: {}, workspacesDefault: false },
    terminal: { height: DEFAULT_DOCK_HEIGHT, opened: false },
    review: { panelOpened: false },
    fileTree: { opened: false, width: DEFAULT_FILE_TREE_WIDTH, tab: "changes" },
    session: { width: DEFAULT_SESSION_WIDTH },
    mobileSidebar: { opened: false },
    sessionTabs: {},
    sessionView: {},
    home: { selection: server ? { server } : {} },
  }
}

export const { use: useLayout, provider: LayoutProvider } = createSimpleContext({
  name: "Layout",
  gate: false,
  init: () => {
    const servers = useServers()
    const platform = usePlatform()

    const [store, setStore, _, ready] = persisted(
      { ...Persist.global("layout"), previousKey: "layout.v6" },
      layoutPersistence,
      initialLayout(servers.list[0] ? ServerConnection.key(servers.list[0]) : undefined),
    )

    const [ephemeral, setEphemeral] = createStore<{ sessionTabPreview: Record<string, string | undefined> }>({
      sessionTabPreview: {},
    })

    // Opening Home with its shortcut focuses session search, so typing filters immediately.
    let homeSearchFocus = false

    // Names of other session-scoped stores, e.g. extension storage, so pruning drops them with the layout state.
    const [scoped, setScoped, , scopedReady] = persisted(
      Persist.global("layout.scoped"),
      Persistence.array(Schema.String),
      [],
    )

    const MAX_SESSION_KEYS = 50
    const PENDING_MESSAGE_TTL_MS = 2 * 60 * 1000

    const usage: SessionKeyUsage = {
      active: undefined,
      pruned: false,
      used: new Map<string, number>(),
    }

    const dropSessionState = (keys: string[]) => {
      const names = ["prompt", "file-view", ...scoped]

      for (const key of keys) {
        const scope = SessionStateKey.scope(key)
        const parts = SessionStateKey.route(key).split("/")
        const dir = parts[0]
        const session = parts[1]

        if (!dir) continue

        for (const entry of names) {
          const target = session
            ? Persist.serverSession(scope, dir, session, entry)
            : Persist.serverWorkspace(scope, dir, entry)

          void removePersisted(target, platform)
        }
      }
    }

    function prune(keep?: string) {
      if (!scopedReady()) return

      const drop = pruneSessionKeys({
        keep,
        max: MAX_SESSION_KEYS,
        used: usage.used,
        view: Object.keys(store.sessionView),
        tabs: Object.keys(store.sessionTabs),
      })

      if (drop.length === 0) return

      setStore(
        produce((draft) => {
          for (const key of drop) {
            delete draft.sessionView[key]
            delete draft.sessionTabs[key]
          }
        }),
      )

      scroll.drop(drop)
      dropSessionState(drop)
      setEphemeral(
        "sessionTabPreview",
        produce((draft) => {
          for (const key of drop) delete draft[key]
        }),
      )

      for (const key of drop) {
        usage.used.delete(key)
      }
    }

    function touch(sessionKey: string) {
      usage.active = sessionKey
      usage.used.set(sessionKey, Date.now())

      if (!ready() || !scopedReady()) return

      if (usage.pruned) return

      usage.pruned = true
      prune(sessionKey)
    }

    const scroll = createScrollPersistence({
      debounceMs: 250,
      getSnapshot: (sessionKey) => store.sessionView[sessionKey]?.scroll,
      onFlush: (sessionKey, next) => {
        const current = store.sessionView[sessionKey]
        const keep = usage.active ?? sessionKey

        if (!current) {
          setStore("sessionView", sessionKey, { scroll: next })
          prune(keep)

          return
        }

        setStore("sessionView", sessionKey, "scroll", (prev) => ({ ...prev, ...next }))
        prune(keep)
      },
    })

    const ensureKey = (key: string) => ensureSessionKey(key, touch, (sessionKey) => scroll.seed(sessionKey))

    createEffect(() => {
      if (!ready() || !scopedReady()) return

      if (usage.pruned) return
      const active = usage.active

      if (!active) return
      usage.pruned = true
      prune(active)
    })

    onMount(() => {
      const flush = () => batch(() => scroll.flushAll())

      const handleVisibility = () => {
        if (document.visibilityState !== "hidden") return
        flush()
      }

      makeEventListener(window, "pagehide", flush)
      makeEventListener(document, "visibilitychange", handleVisibility)

      onCleanup(() => {
        scroll.dispose()
      })
    })

    return {
      route: useCurrentRoute(),
      ready,
      home: {
        selection: createMemo(() => store.home.selection),
        setSelection(selection: HomeProjectSelection) {
          setStore("home", "selection", reconcile(selection))
        },
        searchFocus: {
          request() {
            homeSearchFocus = true
          },
          take() {
            const requested = homeSearchFocus
            homeSearchFocus = false

            return requested
          },
        },
      },
      sessionState: {
        /** Records a session-scoped store, so pruning a session's layout state drops it too. */
        track(name: string) {
          untrack(() => {
            const add = () => setScoped((names) => (names.includes(name) ? names : [...names, name]))

            if (scopedReady()) return add()
            void scopedReady.promise?.then(add)
          })
        },
      },
      fileTree: {
        opened: createMemo(() => store.fileTree?.opened ?? true),
        width: createMemo(() => store.fileTree?.width ?? DEFAULT_FILE_TREE_WIDTH),
        open() {
          if (!store.fileTree) {
            setStore("fileTree", { opened: true, width: DEFAULT_FILE_TREE_WIDTH, tab: "changes" })

            return
          }

          setStore("fileTree", "opened", true)
        },
        close() {
          if (!store.fileTree) {
            setStore("fileTree", { opened: false, width: DEFAULT_FILE_TREE_WIDTH, tab: "changes" })

            return
          }

          setStore("fileTree", "opened", false)
        },
        toggle() {
          if (!store.fileTree) {
            setStore("fileTree", { opened: true, width: DEFAULT_FILE_TREE_WIDTH, tab: "changes" })

            return
          }

          setStore("fileTree", "opened", (x) => !x)
        },
        resize(width: number) {
          if (!store.fileTree) {
            setStore("fileTree", { opened: true, width, tab: "changes" })

            return
          }

          setStore("fileTree", "width", width)
        },
      },
      session: {
        width: createMemo(() => store.session?.width ?? DEFAULT_SESSION_WIDTH),
        resize(width: number) {
          if (!store.session) {
            setStore("session", { width })

            return
          }

          setStore("session", "width", width)
        },
      },
      mobileSidebar: {
        opened: createMemo(() => store.mobileSidebar?.opened ?? false),
        hide() {
          setStore("mobileSidebar", "opened", false)
        },
        toggle() {
          setStore("mobileSidebar", "opened", (x) => !x)
        },
      },
      pendingMessage: {
        set(sessionKey: string, messageID: string) {
          const at = Date.now()
          touch(sessionKey)
          const current = store.sessionView[sessionKey]

          if (!current) {
            setStore("sessionView", sessionKey, {
              scroll: {},
              pendingMessage: messageID,
              pendingMessageAt: at,
            })
            prune(usage.active ?? sessionKey)

            return
          }

          setStore(
            "sessionView",
            sessionKey,
            produce((draft) => {
              draft.pendingMessage = messageID
              draft.pendingMessageAt = at
            }),
          )
        },
        consume(sessionKey: string) {
          const current = store.sessionView[sessionKey]
          const message = current?.pendingMessage
          const at = current?.pendingMessageAt

          if (!message || !at) return

          setStore(
            "sessionView",
            sessionKey,
            produce((draft) => {
              delete draft.pendingMessage
              delete draft.pendingMessageAt
            }),
          )

          if (Date.now() - at > PENDING_MESSAGE_TTL_MS) return

          return message
        },
      },
      /** The dock and side regions of a shell tab, and the session panel width beside them. */
      view(sessionKey: string | Accessor<string>, regions: TabRegions) {
        const key = createSessionKeyReader(sessionKey, ensureKey)

        return {
          scroll(tab: string) {
            return scroll.scroll(key(), tab)
          },
          setScroll(tab: string, pos: SessionScroll) {
            scroll.setScroll(key(), tab, pos)
          },
          dock: {
            opened: regions.dockOpened,
            height: createMemo(() => regions.dockHeight() ?? DEFAULT_DOCK_HEIGHT),
            resize: regions.setDockHeight,
            open() {
              regions.setDockOpened(true)
            },
            close() {
              regions.setDockOpened(false)
            },
          },
          side: {
            opened: regions.sideOpened,
            toggle() {
              regions.setSideOpened(!regions.sideOpened())
            },
          },
          session: {
            width: createMemo(() => regions.sessionWidth() ?? DEFAULT_SESSION_WIDTH),
            resize: regions.setSessionWidth,
          },
        }
      },
      /** Side panel tabs for any session key, mounted or not. Reads are reactive. */
      panel: {
        state(session: string) {
          return store.sessionTabs[session] ?? { all: [] }
        },
        open(session: string, tab: string, launchers?: ReadonlySet<string>, first?: boolean) {
          const next = openSessionTab(
            { tabs: store.sessionTabs[session] ?? { all: [] }, preview: ephemeral.sessionTabPreview[session] },
            tab,
            launchers,
            first,
          )

          batch(() => {
            setStore("sessionTabs", session, next.tabs)
            setEphemeral("sessionTabPreview", session, next.preview)
          })
        },
        preview(session: string, tab: string, launchers?: ReadonlySet<string>) {
          const next = previewSessionTab(
            { tabs: store.sessionTabs[session] ?? { all: [] }, preview: ephemeral.sessionTabPreview[session] },
            tab,
            launchers,
          )

          batch(() => {
            setStore("sessionTabs", session, next.tabs)
            setEphemeral("sessionTabPreview", session, next.preview)
          })
        },
        /** Adds a tab at the end of the strip without selecting it or touching the preview. */
        append(session: string, tab: string) {
          const current = store.sessionTabs[session]

          if (!current) return setStore("sessionTabs", session, { all: [tab] })

          if (current.all.includes(tab)) return
          setStore("sessionTabs", session, "all", current.all.length, tab)
        },
        focus(session: string, tab: string) {
          if (!store.sessionTabs[session]) {
            setStore("sessionTabs", session, { all: [], active: tab })

            return
          }

          setStore("sessionTabs", session, "active", tab)
        },
        close(session: string, tab: string) {
          const current = store.sessionTabs[session]

          if (!current) return
          const next = closeSessionTab({ tabs: current, preview: ephemeral.sessionTabPreview[session] }, tab)
          batch(() => {
            setStore("sessionTabs", session, next.tabs)
            setEphemeral("sessionTabPreview", session, next.preview)
          })
        },
        /**
         * Replaces `to`'s strip, selection, preview tab and scroll offsets with copies of `from`'s, keeping `from`; a key
         * with nothing stored copies as empty. `to` counts as just used, then pruning runs as for any new key.
         */
        copy(from: string, to: string) {
          const current = store.sessionTabs[from]
          usage.used.set(to, Date.now())
          batch(() => {
            scroll.flush(from)
            setStore("sessionTabs", to, { all: [...(current?.all ?? [])], active: current?.active })
            setEphemeral("sessionTabPreview", to, ephemeral.sessionTabPreview[from])
            scroll.drop([to])
            setStore("sessionView", to, {
              scroll: Object.fromEntries(
                Object.entries(store.sessionView[from]?.scroll ?? {}).map(([key, value]) => [
                  key,
                  { x: value.x, y: value.y },
                ]),
              ),
            })
            prune(usage.active ?? to)
          })
        },
        scroll(session: string, tab: string) {
          return scroll.scroll(session, tab)
        },
        setScroll(session: string, tab: string, pos: SessionScroll) {
          scroll.setScroll(session, tab, pos)
        },
      },
      tabs(sessionKey: string | Accessor<string>) {
        const key = createSessionKeyReader(sessionKey, ensureKey)
        const tabs = createMemo(() => store.sessionTabs[key()] ?? { all: [] })

        const apply = (session: string, next: ReturnType<typeof openSessionTab>) => {
          batch(() => {
            setStore("sessionTabs", session, next.tabs)
            setEphemeral("sessionTabPreview", session, next.preview)
          })
        }

        return {
          tabs,
          active: createMemo(() => tabs().active),
          all: createMemo(() => tabs().all),
          preview: createMemo(() => ephemeral.sessionTabPreview[key()]),
          setActive(tab: string | undefined) {
            const session = key()

            if (!store.sessionTabs[session]) {
              setStore("sessionTabs", session, { all: [], active: tab })
            } else {
              setStore("sessionTabs", session, "active", tab)
            }
          },
          setAll(all: string[]) {
            const session = key()
            batch(() => {
              if (!store.sessionTabs[session]) {
                setStore("sessionTabs", session, { all, active: undefined })
              } else {
                setStore("sessionTabs", session, "all", all)
              }

              const preview = ephemeral.sessionTabPreview[session]

              if (preview && !all.includes(preview)) setEphemeral("sessionTabPreview", session, undefined)
            })
          },
          /** Rewrites every stored key, the selected tab and the preview together; keys that collapse into one dedupe. */
          remap(rewrite: (tab: string) => string) {
            const session = key()
            const current = store.sessionTabs[session]

            if (!current) return
            const all = Array.from(new Set(current.all.map(rewrite)))
            const active = current.active === undefined ? undefined : rewrite(current.active)
            const preview = ephemeral.sessionTabPreview[session]
            // A preview that collapses into a kept tab becomes that kept tab: kept wins.
            const kept = new Set(current.all.filter((tab) => tab !== preview).map(rewrite))
            const renamed = preview === undefined ? undefined : rewrite(preview)
            const nextPreview = renamed !== undefined && kept.has(renamed) ? undefined : renamed
            const changed = all.length !== current.all.length || all.some((tab, index) => tab !== current.all[index])

            if (!changed && active === current.active && nextPreview === preview) return
            batch(() => {
              setStore("sessionTabs", session, { ...current, all, active })
              setEphemeral("sessionTabPreview", session, nextPreview)
            })
          },
          async open(tab: string) {
            const session = key()
            apply(
              session,
              openSessionTab(
                { tabs: store.sessionTabs[session] ?? { all: [] }, preview: ephemeral.sessionTabPreview[session] },
                tab,
              ),
            )
          },
          previewTab(tab: string) {
            const session = key()
            apply(
              session,
              previewSessionTab(
                { tabs: store.sessionTabs[session] ?? { all: [] }, preview: ephemeral.sessionTabPreview[session] },
                tab,
              ),
            )
          },
          close(tab: string) {
            const session = key()
            const current = store.sessionTabs[session]

            if (!current) return
            apply(session, closeSessionTab({ tabs: current, preview: ephemeral.sessionTabPreview[session] }, tab))
          },
          move(tab: string, to: number) {
            const session = key()
            const current = store.sessionTabs[session]

            if (!current) return
            const index = current.all.findIndex((f) => f === tab)

            if (index === -1) return
            setStore(
              "sessionTabs",
              session,
              "all",
              produce((opened) => {
                opened.splice(to, 0, opened.splice(index, 1)[0])
              }),
            )
          },
        }
      },
    }
  },
})

import { describe, expect, test, vi } from "bun:test"
import { createScrollPersistence } from "./scroll"

describe("createScrollPersistence", () => {
  test("debounces persisted scroll writes", () => {
    vi.useFakeTimers()

    try {
      const snapshot = {
        session: {
          review: { x: 0, y: 0 },
        },
      } as Record<string, Record<string, { x: number; y: number }>>

      const writes: Array<Record<string, { x: number; y: number }>> = []

      const scroll = createScrollPersistence({
        debounceMs: 10,
        getSnapshot: (sessionKey) => snapshot[sessionKey],
        onFlush: (sessionKey, next) => {
          snapshot[sessionKey] = next
          writes.push(next)
        },
      })

      for (const i of Array.from({ length: 30 }, (_, n) => n + 1)) {
        scroll.setScroll("session", "review", { x: 0, y: i })
      }

      vi.advanceTimersByTime(9)
      expect(writes).toHaveLength(0)

      vi.advanceTimersByTime(1)

      expect(writes).toHaveLength(1)
      expect(writes[0]?.review).toEqual({ x: 0, y: 30 })

      scroll.setScroll("session", "review", { x: 0, y: 30 })
      vi.advanceTimersByTime(20)

      expect(writes).toHaveLength(1)
      scroll.dispose()
    } finally {
      vi.useRealTimers()
    }
  })

  test("reseeds empty cache after persisted snapshot loads", () => {
    const snapshot = {
      session: {},
    } as Record<string, Record<string, { x: number; y: number }>>

    const scroll = createScrollPersistence({
      getSnapshot: (sessionKey) => snapshot[sessionKey],
      onFlush: () => {},
    })

    expect(scroll.scroll("session", "review")).toBeUndefined()

    snapshot.session = {
      review: { x: 12, y: 34 },
    }

    expect(scroll.scroll("session", "review")).toEqual({ x: 12, y: 34 })
    scroll.dispose()
  })
})

import { createStore, produce } from "solid-js/store"

export type SessionScroll = {
  x: number
  y: number
}

type ScrollMap = Record<string, SessionScroll>

type Options = {
  debounceMs?: number
  getSnapshot: (sessionKey: string) => ScrollMap | undefined
  onFlush: (sessionKey: string, scroll: ScrollMap) => void
}

export function createScrollPersistence(opts: Options) {
  const wait = opts.debounceMs ?? 200
  const [cache, setCache] = createStore<Record<string, ScrollMap>>({})
  const dirty = new Set<string>()
  const timers = new Map<string, ReturnType<typeof setTimeout>>()

  function clone(input?: ScrollMap) {
    const out: ScrollMap = {}

    if (!input) return out

    for (const key of Object.keys(input)) {
      const pos = input[key]

      if (!pos) continue
      out[key] = { x: pos.x, y: pos.y }
    }

    return out
  }

  function seed(sessionKey: string) {
    const next = clone(opts.getSnapshot(sessionKey))
    const current = cache[sessionKey]

    if (!current) {
      setCache(sessionKey, next)

      return
    }

    if (Object.keys(current).length > 0) return

    if (Object.keys(next).length === 0) return
    setCache(sessionKey, next)
  }

  function scroll(sessionKey: string, tab: string) {
    seed(sessionKey)

    return cache[sessionKey]?.[tab] ?? opts.getSnapshot(sessionKey)?.[tab]
  }

  function schedule(sessionKey: string) {
    const prev = timers.get(sessionKey)

    if (prev) clearTimeout(prev)
    timers.set(
      sessionKey,
      setTimeout(() => flush(sessionKey), wait),
    )
  }

  function setScroll(sessionKey: string, tab: string, pos: SessionScroll) {
    seed(sessionKey)

    const prev = cache[sessionKey]?.[tab]

    if (prev?.x === pos.x && prev?.y === pos.y) return

    setCache(sessionKey, tab, { x: pos.x, y: pos.y })
    dirty.add(sessionKey)
    schedule(sessionKey)
  }

  function flush(sessionKey: string) {
    const timer = timers.get(sessionKey)

    if (timer) clearTimeout(timer)
    timers.delete(sessionKey)

    if (!dirty.has(sessionKey)) return
    dirty.delete(sessionKey)

    opts.onFlush(sessionKey, clone(cache[sessionKey]))
  }

  function flushAll() {
    const keys = Array.from(dirty)

    if (keys.length === 0) return

    for (const key of keys) {
      flush(key)
    }
  }

  function drop(keys: string[]) {
    if (keys.length === 0) return

    for (const key of keys) {
      const timer = timers.get(key)

      if (timer) clearTimeout(timer)
      timers.delete(key)
      dirty.delete(key)
    }

    setCache(
      produce((draft) => {
        for (const key of keys) {
          delete draft[key]
        }
      }),
    )
  }

  function dispose() {
    drop(Array.from(timers.keys()))
  }

  return {
    cache,
    drop,
    flush,
    flushAll,
    scroll,
    seed,
    setScroll,
    dispose,
  }
}

import { expect, test } from "bun:test"
import { closeSessionTab, openSessionTab, previewSessionTab, type SessionTabState } from "./session-tabs"

const OPEN = "file:open"

const launchers = new Set([OPEN])

const state = (all: string[], active?: string, preview?: string): SessionTabState => ({
  tabs: { all, active },
  preview,
})

test.each([
  {
    name: "preview appends the Open File placeholder",
    run: () => previewSessionTab(state(["file://a.ts"], "file://a.ts"), OPEN),
    expected: state(["file://a.ts", OPEN], OPEN, OPEN),
  },
  {
    name: "preview replaces the current preview in place",
    run: () => previewSessionTab(state(["context", OPEN, "file://b.ts"], OPEN, OPEN), "file://a.ts"),
    expected: state(["context", "file://a.ts", "file://b.ts"], "file://a.ts", "file://a.ts"),
  },
  {
    name: "preview activates a durable tab without duplicating it",
    run: () => previewSessionTab(state(["file://a.ts", OPEN, "file://b.ts"], OPEN, OPEN), "file://b.ts"),
    expected: state(["file://a.ts", "file://b.ts"], "file://b.ts"),
  },
  {
    name: "preview replaces a restored Open File placeholder",
    run: () => previewSessionTab(state(["file://a.ts", OPEN], OPEN), "file://b.ts", launchers),
    expected: state(["file://a.ts", "file://b.ts"], "file://b.ts", "file://b.ts"),
  },
  {
    name: "open pins the current preview",
    run: () => openSessionTab(state(["file://a.ts"], "file://a.ts", "file://a.ts"), "file://a.ts"),
    expected: state(["file://a.ts"], "file://a.ts"),
  },
  {
    name: "open replaces a preview with a directly opened file",
    run: () => openSessionTab(state(["file://a.ts"], "file://a.ts", "file://a.ts"), "file://b.ts"),
    expected: state(["file://b.ts"], "file://b.ts"),
  },
  {
    name: "open replaces a restored Open File placeholder",
    run: () => openSessionTab(state(["file://a.ts", OPEN], OPEN), "file://b.ts", launchers),
    expected: state(["file://a.ts", "file://b.ts"], "file://b.ts"),
  },
  {
    name: "close clears preview metadata and selects the left neighbor",
    run: () =>
      closeSessionTab(
        state(["file://a.ts", "file://b.ts", "file://c.ts"], "file://b.ts", "file://b.ts"),
        "file://b.ts",
      ),
    expected: state(["file://a.ts", "file://c.ts"], "file://a.ts"),
  },
])("$name", ({ run, expected }) => {
  expect(run()).toEqual(expected)
})

export type SessionTabs = {
  active?: string
  all: string[]
}

export type SessionTabState = {
  tabs: SessionTabs
  preview?: string
}

/** A launcher tab (e.g. the file browser) stays replaceable by the next preview even after reload. */
const sessionTabPreview = (current: SessionTabState, launchers: ReadonlySet<string>) =>
  current.preview ?? current.tabs.all.find((tab) => launchers.has(tab))

export function previewSessionTab(
  current: SessionTabState,
  tab: string,
  launchers: ReadonlySet<string> = new Set(),
): SessionTabState {
  const preview = sessionTabPreview(current, launchers)
  const previewIndex = preview ? current.tabs.all.indexOf(preview) : -1
  const existingIndex = current.tabs.all.indexOf(tab)

  if (existingIndex !== -1) {
    if (previewIndex === -1 || preview === tab) {
      return { tabs: { all: current.tabs.all, active: tab }, preview: preview === tab ? tab : undefined }
    }

    return {
      tabs: { all: current.tabs.all.filter((item) => item !== preview), active: tab },
    }
  }

  if (previewIndex === -1) {
    return { tabs: { all: [...current.tabs.all, tab], active: tab }, preview: tab }
  }

  return {
    tabs: {
      all: current.tabs.all.map((item, index) => (index === previewIndex ? tab : item)),
      active: tab,
    },
    preview: tab,
  }
}

/** A `first` tab is stored first and keeps the preview tab, so closing it selects the first remaining tab. */
export function openSessionTab(
  current: SessionTabState,
  tab: string,
  launchers: ReadonlySet<string> = new Set(),
  first = false,
): SessionTabState {
  const preview = sessionTabPreview(current, launchers)

  if (first) {
    return {
      tabs: { all: [tab, ...current.tabs.all.filter((item) => item !== tab)], active: tab },
      preview,
    }
  }

  const previewIndex = preview ? current.tabs.all.indexOf(preview) : -1
  const existingIndex = current.tabs.all.indexOf(tab)

  if (existingIndex !== -1) {
    if (previewIndex === -1 || preview === tab) {
      return { tabs: { all: current.tabs.all, active: tab } }
    }

    return {
      tabs: { all: current.tabs.all.filter((item) => item !== preview), active: tab },
    }
  }

  if (previewIndex === -1) {
    return { tabs: { all: [...current.tabs.all, tab], active: tab } }
  }

  return {
    tabs: {
      all: current.tabs.all.map((item, index) => (index === previewIndex ? tab : item)),
      active: tab,
    },
  }
}

export function closeSessionTab(current: SessionTabState, tab: string): SessionTabState {
  const all = current.tabs.all.filter((item) => item !== tab)
  const preview = current.preview === tab ? undefined : current.preview

  if (current.tabs.active !== tab) return { tabs: { ...current.tabs, all }, preview }

  const index = current.tabs.all.indexOf(tab)

  return {
    tabs: {
      all,
      active: current.tabs.all[index - 1] ?? current.tabs.all[index + 1] ?? all[0],
    },
    preview,
  }
}

import type { SessionTab, Tab, TabInfo } from "./tabs"
import type { TabStorage } from "./schema"

export type ClosedTab = typeof TabStorage.ClosedTab.Type

const CLOSED_TAB_LIMIT = 25

// Only session tabs are recorded; closing a draft tab deletes its persisted
// state, so a reopened draft would come back empty anyway.
export function pushClosedTab(stack: ClosedTab[], tab: Tab, index: number, info?: TabInfo): ClosedTab[] {
  if (tab.type !== "session") return stack

  const entry: ClosedTab = { tab: { ...tab }, index }

  if (info) entry.info = { ...info }

  return [...stack.filter((item) => !sameTab(item.tab, tab)), entry].slice(-CLOSED_TAB_LIMIT)
}

export function listClosedTabs(stack: ClosedTab[], tabs: Tab[]) {
  const seen = new Set<string>()

  return stack.toReversed().filter((entry) => {
    const key = `${entry.tab.server}\n${entry.tab.sessionId}`

    if (seen.has(key)) return false
    seen.add(key)

    return !isOpen(tabs, entry.tab)
  })
}

export type TakenClosedTab = { entry?: ClosedTab; stack: ClosedTab[] }

// Pops the most recently closed tab that is not open again,
// discarding stale entries along the way.
export function takeClosedTab(stack: ClosedTab[], tabs: Tab[], target?: SessionTab): TakenClosedTab {
  if (target) {
    const index = stack.findLastIndex((entry) => sameTab(entry.tab, target))
    const entry = stack[index]

    if (!entry || isOpen(tabs, entry.tab)) return { stack }

    return { entry, stack: [...stack.slice(0, index), ...stack.slice(index + 1)] }
  }

  const remaining = [...stack]

  while (remaining.length) {
    const entry = remaining.pop()

    if (entry && !isOpen(tabs, entry.tab)) return { entry, stack: remaining }
  }

  return { stack: remaining }
}

export function removeClosedTabs(stack: ClosedTab[], server: SessionTab["server"], sessionIDs: string[]) {
  const removed = new Set(sessionIDs)

  return stack.filter((entry) => entry.tab.server !== server || !removed.has(entry.tab.sessionId))
}

export function nextTabAfterClose(tabs: Tab[], index: number, active: boolean) {
  if (!active) return undefined

  return tabs[index + 1] ?? tabs[index - 1] ?? null
}

function isOpen(tabs: Tab[], tab: SessionTab) {
  return tabs.some((item) => item.type === "session" && sameTab(item, tab))
}

function sameTab(first: SessionTab, second: SessionTab) {
  return first.server === second.server && first.sessionId === second.sessionId
}

import { createRoot, type Owner } from "solid-js"

type Entry = {
  value: unknown
  dispose: VoidFunction
}

export function createTabMemory(owner: Owner | null) {
  const entries = new Map<string, Map<string, Entry>>()

  const remove = (key: string) => {
    const state = entries.get(key)

    if (!state) return

    for (const entry of state.values()) entry.dispose()
    entries.delete(key)
  }

  return {
    get<T>(key: string, name: string) {
      return entries.get(key)?.get(name)?.value as T | undefined
    },
    ensure<T>(key: string, name: string, init: () => T) {
      const state = entries.get(key) ?? new Map<string, Entry>()

      if (!entries.has(key)) entries.set(key, state)
      const existing = state.get(name)

      if (existing) return existing.value as T
      const entry = createRoot((dispose) => ({ value: init(), dispose }), owner)
      state.set(name, entry)

      return entry.value
    },
    remove,
    dispose() {
      for (const key of entries.keys()) remove(key)
    },
  }
}

export * as TabStorage from "./schema"

import { Schema, SchemaGetter } from "effect"
import { ServerKey } from "@/runtime/server/persistence"
import { Persistence } from "@/runtime/persistence/schema"

export { ServerKey }

export const Session = Persistence.struct({
  type: Schema.Literal("session"),
  server: ServerKey,
  sessionId: Schema.String,
  routeSessionId: Persistence.optional(Schema.String),
  routeParentId: Persistence.optional(Schema.String),
})

export const Draft = Persistence.struct({
  type: Schema.Literal("draft"),
  draftID: Schema.String,
  server: ServerKey,
  directory: Schema.String,
  worktree: Persistence.optional(Schema.String),
  branch: Persistence.optional(Schema.String),
  mcp: Persistence.optional(Persistence.struct({ target: Schema.String, states: Persistence.record(Schema.Boolean) })),
})

const SessionCodec = Session.pipe(
  Schema.decodeTo(Schema.toType(Session), {
    decode: SchemaGetter.transform(withRoute),
    encode: SchemaGetter.transform((tab) => tab),
  }),
)

export const Tab = Schema.Union([Session, Draft])

export const Tabs = Persistence.array(Schema.Union([SessionCodec, Draft]))

export const Recent = Persistence.struct({
  key: Schema.optional(Schema.String),
})

export const Info = Persistence.struct({
  title: Schema.optional(Schema.String),
  directory: Schema.optional(Schema.String),
  prompted: Schema.optional(Schema.Boolean),
})

export const Infos = Schema.Record(Schema.String, Schema.mutableKey(Info))

// The dock and side regions keep the names they were stored under before extensions.
export const Regions = Schema.Record(
  Schema.String,
  Schema.mutableKey(
    Persistence.struct({
      dock: Schema.optional(Schema.Boolean),
      side: Schema.optional(Schema.Boolean),
      dockHeight: Schema.optional(Schema.Finite),
      sessionWidth: Schema.optional(Schema.Finite),
    }).pipe(Schema.encodeKeys({ dock: "terminal", side: "review", dockHeight: "terminalHeight" })),
  ),
)

export const ClosedTab = Persistence.struct({
  tab: SessionCodec,
  index: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
  info: Persistence.optional(Info),
})

export const Closed = Persistence.array(ClosedTab)

/** A tab keeps its route only when it differs from the session, and the route's parent only with the route. */
function withRoute(tab: typeof Session.Type) {
  const base = { type: tab.type, server: tab.server, sessionId: tab.sessionId }

  if (!tab.routeSessionId || tab.routeSessionId === tab.sessionId) return base

  const routed = { ...base, routeSessionId: tab.routeSessionId }

  return tab.routeParentId ? { ...routed, routeParentId: tab.routeParentId } : routed
}

import { describe, expect, test } from "bun:test"
import { createRoot, getOwner, onCleanup } from "solid-js"
import { createTabMemory } from "./memory"
import {
  listClosedTabs,
  nextTabAfterClose,
  pushClosedTab,
  removeClosedTabs,
  takeClosedTab,
  type ClosedTab,
} from "./closed"
import { findSessionTab, sessionIDHasOpenTab, tabHref, tabKey, type SessionTab, type Tab } from "./tabs"
import { Schema } from "effect"
import { TabStorage } from "./schema"
import { ServerConnection } from "@/runtime/server/registry"
import { Persistence } from "@/runtime/persistence/schema"

const server = ServerConnection.Key.make("local\nhttp://localhost:4096")

const decodeTabs = Schema.decodeUnknownSync(Persistence.withInitial(TabStorage.Tabs, []))

function sessionTab(sessionId: string): SessionTab {
  return { type: "session", server, sessionId }
}

describe("tab migration", () => {
  test("round trips draft MCP choices without changing older drafts", () => {
    const legacy: Tab = { type: "draft", draftID: "legacy-draft", server, directory: "/project" }

    const draft: Tab = {
      ...legacy,
      draftID: "mcp-draft",
      worktree: "create",
      mcp: { target: "new-worktree", states: { first: true, second: false } },
    }

    const restored = decodeTabs([legacy, draft])
    expect(restored).toEqual([legacy, draft])
    expect(decodeTabs(Schema.encodeSync(TabStorage.Tabs)(restored))).toEqual([legacy, draft])
  })

  const dropped: { name: string; stored: unknown; expected: Tab[] }[] = [
    {
      name: "null and malformed tabs",
      stored: [null, sessionTab("a"), { type: "session", server }, { type: "unknown", server }, "invalid"],
      expected: [sessionTab("a")],
    },
    { name: "tabs without a server", stored: [{ type: "session", sessionId: "a" }], expected: [] },
    { name: "null top-level data", stored: null, expected: [] },
    { name: "object top-level data", stored: {}, expected: [] },
  ]

  test.each(dropped)("drops $name", ({ stored, expected }) => {
    expect(decodeTabs(stored)).toEqual(expected)
  })

  test("preserves the active child route and drops an invalid one", () => {
    expect(decodeTabs([{ ...sessionTab("root"), routeSessionId: "child", routeParentId: "parent" }])).toEqual([
      { ...sessionTab("root"), routeSessionId: "child", routeParentId: "parent" },
    ])
    expect(decodeTabs([{ ...sessionTab("parent"), routeSessionId: 1 }])).toEqual([sessionTab("parent")])
    expect(decodeTabs([{ ...sessionTab("parent"), routeSessionId: "child", routeParentId: 1 }])).toEqual([
      { ...sessionTab("parent"), routeSessionId: "child" },
    ])
  })

  test("encodes only canonical tabs and preserves drafts", () => {
    const draft: Tab = { type: "draft", server, draftID: "draft", directory: "/project", branch: "main" }

    const tabs = decodeTabs([
      { ...sessionTab("root"), routeSessionId: "root", routeParentId: "stale", legacy: true },
      draft,
    ])

    expect(tabs).toEqual([sessionTab("root"), draft])
    expect(Schema.encodeSync(TabStorage.Tabs)(tabs)).toEqual(tabs)
    expect(decodeTabs(Schema.encodeSync(TabStorage.Tabs)(tabs))).toEqual(tabs)
  })

  test("salvages valid closed session tabs", () => {
    expect(
      Schema.decodeUnknownSync(Persistence.withInitial(TabStorage.Closed, []))([
        { tab: sessionTab("a"), index: 1 },
        { tab: sessionTab("b"), index: -1 },
        { tab: { type: "draft", server, draftID: "d", directory: "/project" }, index: 0 },
        null,
      ]),
    ).toEqual([{ tab: sessionTab("a"), index: 1 }])
  })

  test("validates auxiliary tab state", () => {
    expect(
      Schema.decodeUnknownSync(Persistence.withInitial(TabStorage.Recent, { key: undefined }))({ key: 1 }),
    ).toEqual({ key: undefined })
    expect(Schema.decodeUnknownSync(TabStorage.Infos)({})).toEqual({})
    expect(Schema.decodeUnknownSync(TabStorage.Regions)({})).toEqual({})
    expect(Schema.decodeUnknownSync(TabStorage.Infos)({ tab: { title: "Title", directory: "/project" } })).toEqual({
      tab: { title: "Title", directory: "/project" },
    })
    const regions = Schema.decodeUnknownSync(TabStorage.Regions)({ tab: { terminal: true, terminalHeight: 300 } })
    expect(regions).toEqual({ tab: { dock: true, dockHeight: 300 } })
    expect(Schema.encodeSync(TabStorage.Regions)(regions)).toEqual({ tab: { terminal: true, terminalHeight: 300 } })
    expect(() => Schema.decodeUnknownSync(TabStorage.Regions)({ tab: { terminal: "yes" } })).toThrow()
  })
})

test("session tab identity stays rooted while its href follows the child route", () => {
  const parent = sessionTab("parent")
  const child = { ...parent, routeSessionId: "child" }

  expect(tabKey(child)).toBe(tabKey(parent))
  expect(tabHref(child)).toContain("/session/child")
})

test("finds open root and routed session tabs", () => {
  const tab = { ...sessionTab("root"), routeSessionId: "child" }
  const tabs = [tab]

  expect(findSessionTab(tabs, server, "root")).toBe(tab)
  expect(findSessionTab(tabs, server, "child")).toBe(tab)
  expect(findSessionTab(tabs, server, "closed")).toBeUndefined()
  expect(sessionIDHasOpenTab(tabs, server, "root")).toBe(true)
  expect(sessionIDHasOpenTab(tabs, server, "child")).toBe(true)
  expect(sessionIDHasOpenTab(tabs, server, "closed")).toBe(false)
  expect(sessionIDHasOpenTab(tabs, ServerConnection.Key.make("other"), "root")).toBe(false)
})

describe("tab memory", () => {
  test("keeps state until its tab is removed", () => {
    createRoot((dispose) => {
      const memory = createTabMemory(getOwner())
      let disposed = 0

      const first = memory.ensure("tab", "prompt", () => {
        onCleanup(() => disposed++)

        return { value: "prompt" }
      })

      expect(memory.ensure("tab", "prompt", () => ({ value: "other" }))).toBe(first)
      expect(memory.get<typeof first>("tab", "prompt")).toBe(first)
      expect(memory.get("missing", "prompt")).toBeUndefined()
      expect(memory.ensure("other", "prompt", () => ({ value: "other" }))).not.toBe(first)

      memory.remove("tab")
      expect(disposed).toBe(1)
      expect(memory.ensure("tab", "prompt", () => ({ value: "new" }))).not.toBe(first)
      dispose()
    })
  })
})

describe("closed tab stack", () => {
  test("records session tabs with their index", () => {
    const stack = pushClosedTab([], sessionTab("a"), 2, {
      title: "Alpha",
      directory: "/project",
      prompted: true,
    })

    expect(stack).toEqual([
      { tab: sessionTab("a"), index: 2, info: { title: "Alpha", directory: "/project", prompted: true } },
    ])
  })

  test("ignores draft tabs", () => {
    const draft: Tab = { type: "draft", draftID: "d1", server, directory: "/tmp" }

    expect(pushClosedTab([], draft, 0)).toEqual([])
  })

  test("caps the stack size", () => {
    const stack = Array.from({ length: 30 }, (_, i) => i).reduce<ClosedTab[]>(
      (acc, i) => pushClosedTab(acc, sessionTab(`s${i}`), i),
      [],
    )

    expect(stack).toHaveLength(25)
    expect(stack[0]?.tab.sessionId).toBe("s5")
    expect(stack.at(-1)?.tab.sessionId).toBe("s29")
  })

  test("keeps only the newest close record for a session", () => {
    const stack = pushClosedTab(
      pushClosedTab([], sessionTab("a"), 1, { title: "Old", directory: "/old", prompted: true }),
      sessionTab("a"),
      3,
      { title: "New", directory: "/new", prompted: true },
    )

    expect(stack).toEqual([
      { tab: sessionTab("a"), index: 3, info: { title: "New", directory: "/new", prompted: true } },
    ])
  })

  test("pops the most recently closed tab", () => {
    const stack = [
      { tab: sessionTab("a"), index: 0 },
      { tab: sessionTab("b"), index: 1 },
    ]

    const result = takeClosedTab(stack, [])

    expect(result.entry?.tab.sessionId).toBe("b")
    expect(result.stack).toEqual([{ tab: sessionTab("a"), index: 0 }])
  })

  test("skips entries whose tab is already open", () => {
    const stack = [
      { tab: sessionTab("a"), index: 0 },
      { tab: sessionTab("b"), index: 1 },
    ]

    const result = takeClosedTab(stack, [sessionTab("b")])

    expect(result.entry?.tab.sessionId).toBe("a")
    expect(result.stack).toEqual([])
  })

  test("lists closed tabs from newest to oldest and excludes open tabs", () => {
    const stack = [
      { tab: sessionTab("a"), index: 0 },
      { tab: sessionTab("b"), index: 1 },
      { tab: sessionTab("c"), index: 2 },
    ]

    expect(listClosedTabs(stack, [sessionTab("b")]).map((entry) => entry.tab.sessionId)).toEqual(["c", "a"])
  })

  test("deduplicates previously stored close records", () => {
    const stack = [
      { tab: sessionTab("a"), index: 0 },
      { tab: sessionTab("b"), index: 1 },
      { tab: sessionTab("a"), index: 2 },
    ]

    expect(listClosedTabs(stack, []).map((entry) => [entry.tab.sessionId, entry.index])).toEqual([
      ["a", 2],
      ["b", 1],
    ])
  })

  test("takes a selected closed tab without removing newer entries", () => {
    const stack = [
      { tab: sessionTab("a"), index: 0 },
      { tab: sessionTab("b"), index: 1 },
      { tab: sessionTab("c"), index: 2 },
    ]

    const result = takeClosedTab(stack, [], sessionTab("a"))

    expect(result.entry?.tab.sessionId).toBe("a")
    expect(result.stack.map((entry) => entry.tab.sessionId)).toEqual(["b", "c"])
  })

  test("returns no entry when everything is open or empty", () => {
    expect(takeClosedTab([], []).entry).toBeUndefined()

    const result = takeClosedTab([{ tab: sessionTab("a"), index: 0 }], [sessionTab("a")])
    expect(result.entry).toBeUndefined()
    expect(result.stack).toEqual([])
  })

  test("purges removed sessions", () => {
    const stack = [
      { tab: sessionTab("a"), index: 0 },
      { tab: sessionTab("b"), index: 1 },
    ]

    expect(removeClosedTabs(stack, server, ["a"])).toEqual([{ tab: sessionTab("b"), index: 1 }])
  })

  test("does not navigate when a background tab closes", () => {
    const tabs = [sessionTab("a"), sessionTab("b"), sessionTab("c")]

    expect(nextTabAfterClose(tabs, 1, false)).toBeUndefined()
    expect(nextTabAfterClose(tabs, 1, true)).toEqual(sessionTab("c"))
    expect(nextTabAfterClose([sessionTab("a")], 0, true)).toBeNull()
  })
})

import type { SessionInfo, SessionMessageUser } from "@opencode/client/promise"
import type { ComposerSelection } from "@/composer/adapter"
import { createSimpleContext } from "@opencode/ui/context"
import { createStore, produce } from "solid-js/store"
import { Persist, persisted, removePersisted, draftPersistedKeys } from "@/runtime/persistence/storage"
import { ServerConnection, useServers } from "@/runtime/server/registry"
import { useExtensionServers } from "@/runtime/extension/servers"
import { createEffect, getOwner, onCleanup, startTransition } from "solid-js"
import { useLocation, useNavigate } from "@solidjs/router"
import { usePlatform } from "@/runtime/platform/platform"
import { uuid } from "@/runtime/persistence/uuid"
import { SessionTabsRemovedDetail } from "@/shell/titlebar/session-events"
import { sessionHref } from "@/shell/routes/session"
import { createTabMemory } from "./memory"
import { nextTabAfterClose, pushClosedTab, removeClosedTabs, takeClosedTab, type ClosedTab } from "./closed"
import {
  createDraftComposerState,
  createMemoryComposerState,
  type ComposerState,
  type PromptModel,
} from "@/composer/state"
import { appendPrompt, promptLength } from "@/composer/prompt-parts"
import { TabStorage } from "./schema"
import { useCurrentRoute } from "@/shell/state/layout"

export type SessionTab = typeof TabStorage.Session.Type

export type DraftTab = typeof TabStorage.Draft.Type

export type Tab = typeof TabStorage.Tab.Type

export type PendingSession = {
  draft: DraftTab
  message: SessionMessageUser
  selection: ComposerSelection
  composer: ComposerState
}

export type TabInfo = typeof TabStorage.Info.Type

export type TabRegion = "dock" | "side"

export type TabRegionSize = "dockHeight" | "sessionWidth"

export const draftHref = (draftID: string) => `/new-session?draftId=${encodeURIComponent(draftID)}`

export const tabHref = (tab: Tab) =>
  tab.type === "draft" ? draftHref(tab.draftID) : sessionHref(tab.server, tab.routeSessionId ?? tab.sessionId)

export const tabKey = (tab: Tab) =>
  tab.type === "draft" ? `draft:${tab.draftID}` : `${tab.server}\n${sessionHref(tab.server, tab.sessionId)}`

export function sessionHasOpenTab(tabs: Tab[], server: ServerConnection.Key, session: SessionInfo) {
  return sessionIDHasOpenTab(tabs, server, session.id)
}

export function findSessionTab(tabs: Tab[], server: ServerConnection.Key, sessionID: string) {
  return tabs.find(
    (tab) =>
      tab.type === "session" &&
      tab.server === server &&
      (tab.sessionId === sessionID || tab.routeSessionId === sessionID),
  )
}

export function sessionIDHasOpenTab(tabs: Tab[], server: ServerConnection.Key, sessionID: string) {
  return !!findSessionTab(tabs, server, sessionID)
}

export const { use: useTabs, provider: TabsProvider } = createSimpleContext({
  name: "Tabs",
  gate: false,
  init: () => {
    const servers = useServers()
    const extensions = useExtensionServers()
    const platform = usePlatform()
    const [store, setStore, _, ready] = persisted(Persist.window("tabs"), TabStorage.Tabs, [])

    const [recent, setRecent, , recentReady] = persisted(Persist.window("tabs.recent"), TabStorage.Recent, {
      key: undefined,
    })

    const [info, setInfo, , infoReady] = persisted(Persist.window("tabs.info"), TabStorage.Infos, {})
    const [regions, setRegions, , regionsReady] = persisted(Persist.window("tabs.panes"), TabStorage.Regions, {})
    const [closed, setClosed, , closedReady] = persisted(Persist.window("tabs.closed"), TabStorage.Closed, [])
    const [pending, setPending] = createStore<Record<string, PendingSession | undefined>>({})

    const navigate = useNavigate()
    const location = useLocation()
    const memory = createTabMemory(getOwner())
    const currentRoute = useCurrentRoute()

    const closing = new Set<string>()
    let recentWrite = 0
    let recentValue: string | undefined

    const recentKey = () => (recentWrite ? recentValue : recent.key)

    const setRecentKey = (key: string | undefined) => {
      const write = ++recentWrite
      recentValue = key

      if (recentReady()) {
        setRecent("key", key)

        return
      }

      void recentReady.promise?.then(() => {
        if (write === recentWrite) setRecent("key", key)
      })
    }

    const updateClosed = (update: (stack: ClosedTab[]) => ClosedTab[]) => {
      const apply = () => setClosed((stack) => update(stack))

      if (closedReady()) {
        apply()

        return
      }

      void closedReady.promise?.then(apply)
    }

    const removeDraftPersisted = (draftID: string) => {
      for (const key of draftPersistedKeys()) {
        const target = Persist.draft(draftID, key)
        removePersisted(key === "prompt" ? Persist.prompt(target) : target, platform)
      }
    }

    const removeInfo = (key: string) => {
      if (!info[key]) return
      setInfo(
        produce((draft) => {
          delete draft[key]
        }),
      )
    }

    const removeRegions = (key: string) => {
      if (!regions[key]) return
      setRegions(
        produce((draft) => {
          delete draft[key]
        }),
      )
    }

    onCleanup(memory.dispose)

    // A contributed server that is unlisted or whose extension is down is still known: only its removal drops its tabs.
    const known = () =>
      new Set<string>([...servers.list.map(ServerConnection.key), ...extensions.entries().map((item) => item.key)])

    createEffect(() => {
      if (!ready() || !recentReady()) return
      const serversSet = known()
      const next = store.filter((tab) => serversSet.has(tab.server))

      if (next.length !== store.length) {
        for (const tab of store) {
          if (!serversSet.has(tab.server)) {
            const key = tabKey(tab)
            memory.remove(key)
            removeInfo(key)
            removeRegions(key)
          }
        }

        setStore(() => next)
      }

      if (recent.key && !next.some((tab) => tabKey(tab) === recent.key)) setRecentKey(undefined)
      const keys = new Set(next.map(tabKey))

      for (const key of Object.keys(info)) {
        if (!keys.has(key)) removeInfo(key)
      }

      if (!regionsReady()) return

      for (const key of Object.keys(regions)) {
        if (!keys.has(key)) removeRegions(key)
      }
    })

    createEffect(() => {
      if (!closedReady()) return
      const serversSet = known()
      const next = closed.filter((entry) => serversSet.has(entry.tab.server))

      if (next.length !== closed.length) setClosed(() => next)
    })

    const navigateTab = (tab: Tab) => {
      const href = tabHref(tab)
      setRecentKey(tabKey(tab))
      navigate(href)
    }

    const removeTab = (index: number) => {
      const tab = store[index]

      if (!tab) return
      const key = tabKey(tab)
      const draftID = tab.type === "draft" ? tab.draftID : undefined
      const nextTab = nextTabAfterClose(store, index, recentKey() === key && location.pathname !== "/")
      closing.add(key)
      void startTransition(() => {
        setStore(
          produce((tabs) => {
            tabs.splice(index, 1)
          }),
        )

        if (nextTab === null) {
          setRecentKey(undefined)
          navigate("/")
        }

        if (nextTab) navigateTab(nextTab)
      }).finally(() => closing.delete(key))
      memory.remove(key)
      removeInfo(key)
      removeRegions(key)

      if (draftID) removeDraftPersisted(draftID)
    }

    const actions = {
      addSessionTab: (tab: Omit<SessionTab, "type">) => {
        const next = { type: "session" as const, ...tab }
        const existing = store.find((item) => tabKey(item) === tabKey(next))

        if (existing) return existing
        void startTransition(() => {
          setStore(
            produce((tabs) => {
              if (tabs.some((item) => tabKey(item) === tabKey(next))) return
              tabs.push(next)
            }),
          )
        })

        return next
      },
      reorder(keys: string[]) {
        setStore(
          produce((tabs) => {
            const byKey = new Map(tabs.map((tab) => [tabKey(tab), tab]))
            const next = keys.flatMap((key) => byKey.get(key) ?? [])

            if (next.length !== tabs.length) return
            tabs.splice(0, tabs.length, ...next)
          }),
        )
      },
      draft(draftID: string) {
        const tab = store.find((item) => item.type === "draft" && item.draftID === draftID)

        if (!tab || tab.type !== "draft") throw new Error(`Draft not found: ${draftID}`)

        return tab
      },
      async newDraft(draft: Omit<DraftTab, "type" | "draftID">, prompt?: string, model?: PromptModel) {
        const draftID = uuid()
        const tab = { type: "draft" as const, draftID, ...draft }
        memory.ensure(tabKey(tab), "prompt", () => createDraftComposerState(draftID, { prompt, model }))
        await startTransition(() => {
          setStore(
            produce((tabs) => {
              tabs.push(tab)
            }),
          )
          navigate(draftHref(draftID))
        })

        return tab
      },
      updateDraft(draftID: string, draft: Partial<Omit<DraftTab, "type" | "draftID">>) {
        void startTransition(() => {
          setStore(
            (tab) => tab.type === "draft" && tab.draftID === draftID,
            produce((tab) => Object.assign(tab, draft)),
          )
        })
      },
      initializeDraftWorktrees(server: ServerConnection.Key, directory: string, worktree: string) {
        setStore(
          (tab) => tab.type === "draft" && tab.server === server && tab.directory === directory && !tab.worktree,
          produce((tab) => {
            if (tab.type === "draft") tab.worktree = worktree
          }),
        )
      },
      promoteDraft(draftID: string, session: Omit<SessionTab, "type">) {
        // Keep the replacement and navigation atomic so /new-session never renders
        // after its backing draft tab has been removed from the store.
        const active = location.pathname === "/new-session" && location.query.draftId === draftID
        const next = { type: "session" as const, ...session }
        void startTransition(() => {
          setStore(
            produce((tabs) => {
              const index = tabs.findIndex((tab) => tab.type === "draft" && tab.draftID === draftID)

              if (index !== -1) tabs[index] = next
            }),
          )

          if (recent.key === `draft:${draftID}`) setRecentKey(tabKey(next))

          if (active) navigateTab(next)
        })
        memory.remove(`draft:${draftID}`)
        removeDraftPersisted(draftID)
      },
      pendingSession(server: ServerConnection.Key, sessionID: string): PendingSession | undefined {
        return pending[tabKey({ type: "session", server, sessionId: sessionID })]
      },
      prepareSession(
        draftID: string,
        session: Omit<SessionTab, "type">,
        preview: { message: SessionMessageUser; selection: ComposerSelection },
      ) {
        // Snapshot the draft before replacing its store entry; keep its composer alive for rollback.
        const draft = { ...actions.draft(draftID) }
        const next = { type: "session" as const, ...session }
        const key = tabKey(next)
        const composer = createMemoryComposerState()

        const ready = startTransition(() => {
          setPending(key, { draft, ...preview, composer })
          const index = store.findIndex((tab) => tab.type === "draft" && tab.draftID === draftID)

          if (index === -1) return
          const active = location.pathname === "/new-session" && location.query.draftId === draftID
          setStore(
            produce((tabs) => {
              tabs[index] = next
            }),
          )

          if (recentKey() === tabKey(draft)) setRecentKey(key)

          if (active) navigateTab(next)
        })

        return {
          ready,
          async complete(target: ReturnType<ComposerState["capture"]>) {
            await ready

            if (!pending[key]) return
            await memory.get<ComposerState>(key, "prompt")?.ready.promise

            if (promptLength(composer.current())) target.set(composer.current(), composer.cursor())
            await startTransition(() => setPending(key, undefined))
            memory.remove(tabKey(draft))
            removeDraftPersisted(draftID)
          },
          async rollback(worktree?: string) {
            await ready

            if (!pending[key]) return
            const original = memory.get<ComposerState>(tabKey(draft), "prompt")

            if (original && promptLength(composer.current())) {
              // Nothing was submitted: recover both inputs in the original draft.
              const restored = appendPrompt(original.current(), composer.current())
              original.set(restored, promptLength(restored))
            }

            await startTransition(() => {
              const index = store.findIndex((tab) => tabKey(tab) === key)

              if (index !== -1) {
                const restored = worktree === undefined ? draft : { ...draft, worktree, branch: undefined }
                const route = currentRoute()
                setStore(
                  produce((tabs) => {
                    tabs[index] = restored
                  }),
                )

                if (recentKey() === key) setRecentKey(tabKey(restored))

                if (
                  route.type === "session" &&
                  route.server === session.server &&
                  route.sessionId === session.sessionId
                ) {
                  navigateTab(restored)
                }
              }

              setPending(key, undefined)
            })
            updateClosed((stack) => removeClosedTabs(stack, session.server, [session.sessionId]))
            memory.remove(key)
            removeInfo(key)

            if (store.some((tab) => tab.type === "draft" && tab.draftID === draftID)) return
            memory.remove(tabKey(draft))
            removeDraftPersisted(draftID)
          },
        }
      },
      removeTab,
      // User-initiated close: records the tab so it can be reopened.
      // Cleanup paths (missing sessions, archive, server removal) go through
      // removeTab and friends directly and are not recorded.
      closeTab(index: number) {
        const tab = store[index]

        if (!tab) return

        if (tab.type === "session") updateClosed((stack) => pushClosedTab(stack, tab, index, info[tabKey(tab)]))
        removeTab(index)
      },
      reopenClosedTab(target?: SessionTab, options?: { append?: boolean }) {
        if (!closedReady()) {
          void closedReady.promise?.then(() => actions.reopenClosedTab(target, options))

          return
        }

        const result = takeClosedTab(closed, store, target)

        if (result.stack.length === closed.length) return
        setClosed(() => result.stack)
        const entry = result.entry

        if (!entry) return
        const index = options?.append ? store.length : Math.min(entry.index, store.length)

        if (entry.info) setInfo(tabKey(entry.tab), entry.info)
        void startTransition(() => {
          setStore(
            produce((tabs) => {
              if (tabs.some((item) => tabKey(item) === tabKey(entry.tab))) return
              tabs.splice(index, 0, entry.tab)
            }),
          )
          navigateTab(entry.tab)
        })
      },
      removeSessionTab(input: Omit<SessionTab, "type">) {
        updateClosed((stack) => removeClosedTabs(stack, input.server, [input.sessionId]))

        const index = store.findIndex(
          (tab) =>
            tab.type === "session" &&
            tab.server === input.server &&
            (tab.sessionId === input.sessionId || tab.routeSessionId === input.sessionId),
        )

        if (index !== -1) removeTab(index)
      },
      removeServer(key: ServerConnection.Key) {
        updateClosed((stack) => stack.filter((entry) => entry.tab.server !== key))
        const drafts = store.flatMap((tab) => (tab.type === "draft" && tab.server === key ? [tab.draftID] : []))
        const removed = store.filter((tab) => tab.server === key).map(tabKey)
        setStore((tabs) => tabs.filter((tab) => tab.server !== key))

        for (const key of removed) memory.remove(key)

        for (const key of removed) removeInfo(key)

        if (recent.key && removed.includes(recent.key)) setRecentKey(undefined)

        for (const draftID of drafts) removeDraftPersisted(draftID)
      },
      removeSessions: (input: SessionTabsRemovedDetail) => {
        const targetServer = input.server
        updateClosed((stack) => removeClosedTabs(stack, targetServer, input.sessionIDs))

        const removed = store
          .filter(
            (tab) => tab.type === "session" && tab.server === targetServer && input.sessionIDs.includes(tab.sessionId),
          )
          .map(tabKey)

        void startTransition(() => {
          setStore(
            produce((tabs) => {
              const sessionIDs = new Set(input.sessionIDs)
              const route = currentRoute()
              const sessionRoute = route.type === "session" ? route : undefined

              const currentIndex = sessionRoute
                ? tabs.findIndex(
                    (tab) =>
                      tab.type === "session" &&
                      tab.server === sessionRoute.server &&
                      tab.sessionId === sessionRoute.sessionId,
                  )
                : -1

              const currentTab = tabs[currentIndex]

              const removedCurrent =
                currentTab?.type === "session" &&
                currentTab.server === targetServer &&
                sessionIDs.has(currentTab.sessionId)

              for (let i = tabs.length - 1; i >= 0; i--) {
                const tab = tabs[i]

                if (!tab || tab.type !== "session") continue

                if (tab.server !== targetServer) continue

                if (!sessionIDs.has(tab.sessionId)) continue
                tabs.splice(i, 1)
              }

              if (!removedCurrent) return

              const nextTab =
                tabs.slice(currentIndex).find((tab) => tab.type === "session") ??
                tabs.slice(0, currentIndex).findLast((tab) => tab.type === "session")

              if (nextTab) navigateTab(nextTab)
              else navigate("/")
            }),
          )

          if (recent.key && removed.includes(recent.key)) setRecentKey(undefined)
        })

        for (const key of removed) memory.remove(key)

        for (const key of removed) removeInfo(key)
      },
      rememberSessionInfo(tab: SessionTab, session: SessionInfo, prompted: boolean) {
        const key = tabKey(tab)
        const current = info[key]

        const next = {
          title: session.title,
          directory: session.location.directory,
          prompted: current?.prompted === true || prompted,
        }

        if (
          current &&
          current.title === next.title &&
          current.directory === next.directory &&
          current.prompted === next.prompted
        )
          return
        console.debug("[tabs] update persisted session info", { key, sessionID: session.id, current, next })
        setInfo(key, next)
      },
      select: navigateTab,
      remember(tab: Tab) {
        const key = tabKey(tab)

        if (recentKey() !== key) setRecentKey(key)
      },
      rememberSessionRoute(tab: SessionTab, sessionId: string, parentId?: string) {
        const index = store.findIndex((item) => tabKey(item) === tabKey(tab))

        if (index === -1) return
        setStore(
          index,
          produce((item) => {
            if (item.type !== "session") return
            item.routeSessionId = sessionId === item.sessionId ? undefined : sessionId
            item.routeParentId = sessionId === item.sessionId ? undefined : parentId
          }),
        )
      },
      toggleHome(input: { home: boolean; current?: Tab }) {
        if (input.home) {
          const tab = store.find((tab) => tabKey(tab) === recentKey())

          if (tab) navigateTab(tab)

          return
        }

        if (input.current) {
          setRecentKey(tabKey(input.current))
          navigate("/")

          return
        }

        navigate("/")
      },
      state<T>(tab: Tab, name: string, init: () => T) {
        return memory.ensure(tabKey(tab), name, init)
      },
      stateValue<T>(tab: Tab, name: string) {
        return memory.get<T>(tabKey(tab), name)
      },
      region(tab: Tab | undefined, region: TabRegion) {
        if (!tab) return false

        return regions[tabKey(tab)]?.[region] ?? false
      },
      setRegion(tab: Tab | undefined, region: TabRegion, opened: boolean) {
        if (!tab) return
        const key = tabKey(tab)
        const current = regions[key]

        if (current?.[region] === opened) return

        if (!current) {
          setRegions(key, { [region]: opened })

          return
        }

        setRegions(key, region, opened)
      },
      regionSize(tab: Tab | undefined, size: TabRegionSize) {
        if (!tab) return

        return regions[tabKey(tab)]?.[size]
      },
      setRegionSize(tab: Tab | undefined, size: TabRegionSize, value: number) {
        if (!tab) return
        const key = tabKey(tab)
        const current = regions[key]

        if (current?.[size] === value) return

        if (!current) {
          setRegions(key, { [size]: value })

          return
        }

        setRegions(key, size, value)
      },
    }

    return { ...actions, store, info, closed, ready, infoReady, recentReady, closedReady, regionsReady }
  },
})

type TimeKey =
  | "common.time.justNow"
  | "common.time.minutesAgo.short"
  | "common.time.hoursAgo.short"
  | "common.time.daysAgo.short"

type Translate = (key: TimeKey, params?: Record<string, string | number>) => string

export function getRelativeTime(dateString: string, t: Translate): string {
  const date = new Date(dateString)
  const now = new Date()
  const diffMs = now.getTime() - date.getTime()
  const diffSeconds = Math.floor(diffMs / 1000)
  const diffMinutes = Math.floor(diffSeconds / 60)
  const diffHours = Math.floor(diffMinutes / 60)
  const diffDays = Math.floor(diffHours / 24)

  if (diffSeconds < 60) return t("common.time.justNow")

  if (diffMinutes < 60) return t("common.time.minutesAgo.short", { count: diffMinutes })

  if (diffHours < 24) return t("common.time.hoursAgo.short", { count: diffHours })

  return t("common.time.daysAgo.short", { count: diffDays })
}

import { describe, expect, test } from "bun:test"
import { applyPath, backPath, forwardPath, type TitlebarHistory } from "./history"

function history(): TitlebarHistory {
  return { stack: [], index: 0, action: undefined }
}

describe("titlebar history", () => {
  test("trims to the maximum and keeps back and forward indexes correct", () => {
    const state = ["/", "/a", "/b", "/c"].reduce((current, url) => applyPath(current, { url }, 3), history())

    expect(state.stack.map((entry) => entry.url)).toEqual(["/a", "/b", "/c"])
    expect(state.index).toBe(2)

    const back = backPath(state)
    expect(back?.to.url).toBe("/b")
    expect(back?.state.index).toBe(1)

    const afterBack = applyPath(back!.state, back!.to, 3)
    expect(afterBack.stack.map((entry) => entry.url)).toEqual(["/a", "/b", "/c"])
    expect(afterBack.index).toBe(1)

    const forward = forwardPath(afterBack)
    expect(forward?.to.url).toBe("/c")
    expect(forward?.state.index).toBe(2)

    const afterForward = applyPath(forward!.state, forward!.to, 3)
    expect(afterForward.stack.map((entry) => entry.url)).toEqual(["/a", "/b", "/c"])
    expect(afterForward.index).toBe(2)
  })

  test("action-driven navigation does not push duplicate history entries", () => {
    const state: TitlebarHistory = {
      stack: [{ url: "/" }, { url: "/a" }, { url: "/b" }],
      index: 2,
      action: undefined,
    }

    const back = backPath(state)
    expect(back?.to.url).toBe("/a")

    const next = applyPath(back!.state, back!.to, 10)
    expect(next.stack.map((entry) => entry.url)).toEqual(["/", "/a", "/b"])
    expect(next.index).toBe(1)
    expect(next.action).toBeUndefined()
  })

  test("settings visits retain their own route state", () => {
    const first = { url: "/settings", state: { settings: { type: "draft", draftID: "a" } } }
    const second = { url: "/settings", state: { settings: { type: "draft", draftID: "b" } } }
    const state = applyPath(applyPath(applyPath(history(), first), { url: "/b" }), second)
    const back = backPath(state)!
    const previous = backPath(applyPath(back.state, back.to))!
    expect(previous.to).toEqual(first)
    expect(forwardPath(applyPath(back.state, back.to))?.to).toEqual(second)
  })

  test("settings pages and settings state replace one history entry", () => {
    const initial = applyPath(history(), { url: "/settings", state: { tab: "general" } })
    const updated = applyPath(initial, { url: "/settings", state: { tab: "models" } })
    expect(updated.stack).toHaveLength(2)
    const back = backPath(updated)!
    expect(back.to.url).toBe("/")
    expect(forwardPath(applyPath(back.state, back.to))?.to.state).toEqual({ tab: "models" })

    const models = applyPath(applyPath(history(), { url: "/settings" }), { url: "/settings?tab=models" })
    const project = applyPath(models, { url: "/settings?server=local&project=%2Fwork&tab=extensions" })
    expect(project.stack.map((entry) => entry.url)).toEqual([
      "/",
      "/settings?server=local&project=%2Fwork&tab=extensions",
    ])
    expect(backPath(project)?.to.url).toBe("/")
  })
})

export const MAX_TITLEBAR_HISTORY = 100

export type TitlebarAction = "back" | "forward" | undefined

export type HistoryLocation = { url: string; state?: unknown }

export type TitlebarHistory = {
  stack: HistoryLocation[]
  index: number
  action: TitlebarAction
}

export function applyPath(
  state: TitlebarHistory,
  current: HistoryLocation,
  max = MAX_TITLEBAR_HISTORY,
): TitlebarHistory {
  if (!state.stack.length) {
    const stack = current.url === "/" ? [current] : [{ url: "/" }, current]

    return { stack, index: stack.length - 1, action: undefined }
  }

  const active = state.stack[state.index]
  const sameUrl = current.url === active.url

  if (sameUrl || (isSettingsPath(current.url) && isSettingsPath(active.url))) {
    if (sameUrl && !state.action && current.state === active.state) return state

    return {
      ...state,
      stack: state.stack.map((entry, index) => (index === state.index ? current : entry)),
      action: undefined,
    }
  }

  if (state.action) return { ...state, action: undefined }

  return pushPath(state, current, max)
}

function isSettingsPath(url: string) {
  return url.split(/[?#]/, 1)[0] === "/settings"
}

export function pushPath(state: TitlebarHistory, path: HistoryLocation, max = MAX_TITLEBAR_HISTORY): TitlebarHistory {
  const stack = state.stack.slice(0, state.index + 1).concat(path)
  const next = trimHistory(stack, stack.length - 1, max)

  return { ...state, ...next, action: undefined }
}

export function trimHistory(stack: HistoryLocation[], index: number, max = MAX_TITLEBAR_HISTORY) {
  if (stack.length <= max) return { stack, index }
  const cut = stack.length - max

  return {
    stack: stack.slice(cut),
    index: Math.max(0, index - cut),
  }
}

export function backPath(state: TitlebarHistory) {
  if (state.index <= 0) return
  const index = state.index - 1
  const to = state.stack[index]

  if (!to) return

  return { state: { ...state, index, action: "back" as const }, to }
}

export function forwardPath(state: TitlebarHistory) {
  if (state.index >= state.stack.length - 1) return
  const index = state.index + 1
  const to = state.stack[index]

  if (!to) return

  return { state: { ...state, index, action: "forward" as const }, to }
}

import { createMemo, For, Show, type JSX } from "solid-js"
import { createStore } from "solid-js/store"
import { createResizeObserver } from "@solid-primitives/resize-observer"
import { Icon } from "@opencode/ui/icon"
import { IconButton } from "@opencode/ui/icon-button"
import { Menu } from "@opencode/ui/menu"
import { Tooltip } from "@opencode/ui/tooltip"
import { useLanguage } from "@/runtime/i18n/language"
import { ServerConnection } from "@/runtime/server/registry"
import { useGlobal, useServerCtx } from "@/runtime/server/runtime"
import { SessionTabAvatarView } from "@/shell/layout/session-tab-avatar"
import { listClosedTabs, type ClosedTab } from "@/shell/tabs/closed"
