export function RecentlyClosedTabsMenu(props: {
  onNewTab: () => void
  tooltip?: JSX.Element
  vertical?: boolean
  keybind?: string
}) {
  const language = useLanguage()
  const tabs = useTabs()

  const recent = createMemo(() =>
    listClosedTabs(tabs.closed, tabs.store).filter((entry) => entry.info?.prompted === true),
  )

  return (
    <Menu.Context modal={false}>
      <Show
        when={props.vertical}
        fallback={
          <Tooltip placement="bottom" value={props.tooltip}>
            <Menu.Context.Trigger
              as={IconButton}
              type="button"
              variant="ghost-muted"
              size="large"
              class="shrink-0"
              icon={<Icon name="plus" />}
              onClick={props.onNewTab}
              aria-label={language.t("command.session.new")}
            />
          </Tooltip>
        }
      >
        <Menu.Context.Trigger
          as="button"
          type="button"
          data-titlebar-tab-action
          data-action="vertical-tabs-new-session"
          class="group flex h-7 w-full shrink-0 items-center gap-1.5 rounded-[6px] ps-1.5 pe-2 text-[13px] leading-4 text-v2-text-text-faint hover:text-v2-text-text-base"
          onClick={props.onNewTab}
          aria-label={language.t("command.session.new")}
        >
          <Icon name="edit" class="shrink-0" />
          <span class="min-w-0 truncate">{language.t("command.session.new")}</span>
          <span
            class="ms-auto hidden min-w-0 truncate text-v2-text-text-faint group-hover:block group-focus-visible:block"
            aria-hidden="true"
          >
            <bdi dir="ltr">{props.keybind}</bdi>
          </span>
        </Menu.Context.Trigger>
      </Show>
      <Menu.Context.Portal>
        <Menu.Context.Content class="max-h-[66.667dvh] w-56 max-w-56 overflow-y-auto">
          <Menu.Group>
            <Menu.GroupLabel>{language.t("home.recentlyClosed")}</Menu.GroupLabel>
            <For each={recent()}>
              {(entry) => (
                <RecentlyClosedTabItem
                  entry={entry}
                  onSelect={() => tabs.reopenClosedTab(entry.tab, { append: true })}
                />
              )}
            </For>
          </Menu.Group>
        </Menu.Context.Content>
      </Menu.Context.Portal>
    </Menu.Context>
  )
}

function RecentlyClosedTabItem(props: { entry: ClosedTab; onSelect: () => void }) {
  const global = useGlobal()
  const language = useLanguage()
  const [state, setState] = createStore({ truncated: false })
  const placement = language.direction() === "rtl" ? "left-start" : "right-start"

  const serverCtx = useServerCtx(() =>
    global.servers.list().find((item) => ServerConnection.key(item) === props.entry.tab.server),
  )

  const session = createMemo(() => serverCtx()?.data.session.get(props.entry.tab.sessionId))
  const directory = () => props.entry.info?.directory ?? session()?.location.directory ?? ""

  const project = createMemo(() => {
    const value = session()

    if (value) return serverCtx()?.projects.forSession(value)

    if (!directory()) return

    return serverCtx()?.projects.resolve({ worktree: directory(), expanded: false })
  })

  const title = () => sessionTabTitle(session()?.title ?? props.entry.info?.title, language.t("session.tab.session"))

  return (
    <Menu.Item class="max-w-56" onSelect={props.onSelect}>
      <span class="flex size-4 shrink-0 items-center justify-center">
        <SessionTabAvatarView project={project()} directory={directory()} unread={false} loading={false} />
      </span>
      <Tooltip
        placement={placement}
        value={<bdi dir="auto">{title()}</bdi>}
        disabled={!state.truncated}
        class="min-w-0 flex-1"
        contentClass="max-w-[min(480px,calc(100vw-32px))] break-words"
      >
        <span
          ref={(element) =>
            createResizeObserver(element, () => setState("truncated", element.scrollWidth > element.clientWidth))
          }
          dir="auto"
          class="block min-w-0 truncate text-start"
        >
          {title()}
        </span>
      </Tooltip>
    </Menu.Item>
  )
}

import { describe, expect, test } from "bun:test"
import { createRoot } from "solid-js"
import { createTitlebarRightSlot } from "./right-slot"

describe("titlebar right slot", () => {
  test("selects the latest owner and restores the previous owner after overlap", () => {
    createRoot((dispose) => {
      const slot = createTitlebarRightSlot()
      const committed = slot.createRegistration()
      committed.register()
      expect(committed.active()).toBe(true)

      const shadow = slot.createRegistration()
      shadow.register()
      expect(committed.active()).toBe(false)
      expect(shadow.active()).toBe(true)

      shadow.unregister()
      expect(committed.active()).toBe(true)
      expect(shadow.active()).toBe(false)

      committed.unregister()
      expect(committed.active()).toBe(false)
      dispose()
    })
  })
})

import { createContext, onCleanup, onMount, Show, useContext, type ParentProps } from "solid-js"
import { createStore } from "solid-js/store"
import { Portal } from "solid-js/web"

type Registration = {
  active: () => boolean
  register: () => void
  unregister: () => void
}

type TitlebarRightSlot = {
  createRegistration: () => Registration
  mount: () => HTMLElement | undefined
  setMount: (mount: HTMLElement) => void
}

const TitlebarRightContext = createContext<TitlebarRightSlot>()

export function TitlebarRightProvider(props: ParentProps) {
  return (
    <TitlebarRightContext.Provider value={createTitlebarRightSlot()}>{props.children}</TitlebarRightContext.Provider>
  )
}

export function createTitlebarRightSlot(): TitlebarRightSlot {
  const [store, setStore] = createStore<{ mount?: HTMLElement; registrations: symbol[] }>({ registrations: [] })

  return {
    mount: () => store.mount,
    setMount: (mount) => setStore("mount", mount),
    createRegistration() {
      const id = Symbol()

      return {
        active: () => store.registrations.at(-1) === id,
        register: () => setStore("registrations", (items) => [...items, id]),
        unregister: () => setStore("registrations", (items) => items.filter((item) => item !== id)),
      }
    },
  }
}

export function TitlebarRightMount(props: { vertical?: boolean }) {
  const slot = useTitlebarRightSlot()

  return (
    <div
      ref={slot.setMount}
      id="opencode-titlebar-right"
      class={props.vertical ? "flex w-full shrink-0 flex-col" : "flex shrink-0 items-center justify-end gap-0"}
    />
  )
}

export function TitlebarRight(props: ParentProps) {
  const slot = useTitlebarRightSlot()
  const registration = slot.createRegistration()
  onMount(() => {
    registration.register()
    onCleanup(registration.unregister)
  })

  return (
    <Show when={registration.active() && slot.mount()} keyed>
      {(mount) => <Portal mount={mount}>{props.children}</Portal>}
    </Show>
  )
}

function useTitlebarRightSlot() {
  const slot = useContext(TitlebarRightContext)

  if (!slot) throw new Error("TitlebarRight must be used within TitlebarRightProvider")

  return slot
}

