                        entry.command ? props.command.keybind(entry.command) : entry.accelerator?.windows

                      const disabled = () => (entry.command ? commandDisabled(entry.command) : false)

                      return (
                        <DesktopMenuItem
                          label={label()}
                          keybind={keybind()}
                          disabled={disabled()}
                          onSelect={() => runEntry(entry)}
                        />
                      )
                    }}
                  </For>
                </DesktopMenuSubmenu>
              )}
            </For>
          </Menu.Group>
        </Menu.Content>
      </Menu.Portal>
    </Menu>
