        "file",
        file,
        produce((draft) => {
          draft.loading = false
          draft.notFound = notFound
          draft.error = message

          if (!notFound) return
          draft.loaded = false
          draft.content = undefined
        }),
      )

      if (silent || (notFound && extensions.files.opened().includes(file))) return

      showToast({
        variant: "error",
        title: language.t("toast.file.loadFailed.title"),
        description: message,
      })
