          node: tree.node,
          isDirLoaded: tree.isLoaded,
          refreshDir: (dir) => {
            void tree.listDir(dir, { force: true })
          },
        })
      })

      onCleanup(stop)
    })

    const get = (input: string) => {
      const file = path.normalize(input)
      const state = store.file[file]
      const content = state?.content

      if (!content) return state

      if (hasFileContent(file)) {
        touchFileContent(file)

        return state
      }

      touchFileContent(file, approxBytes(content))

      return state
    }

    function withPath<T>(input: string, action: (file: string) => T) {
      return action(path.normalize(input))
    }

    const scrollTop = (input: string) => withPath(input, (file) => view().scrollTop(file))
    const scrollLeft = (input: string) => withPath(input, (file) => view().scrollLeft(file))
    const selectedLines = (input: string) => withPath(input, (file) => view().selectedLines(file))
    const setScrollTop = (input: string, top: number) => withPath(input, (file) => view().setScrollTop(file, top))
    const setScrollLeft = (input: string, left: number) => withPath(input, (file) => view().setScrollLeft(file, left))

    const setSelectedLines = (input: string, range: SelectedLineRange | null) =>
      withPath(input, (file) => view().setSelectedLines(file, range))

    onCleanup(() => {
      viewCache.clear()
    })

    return {
      ready: () => view().ready(),
      normalize: path.normalize,
      absolute: path.absolute,
      tree: {
        list: tree.listDir,
        refresh: (input: string) => tree.listDir(input, { force: true }),
        state: tree.dirState,
        children: tree.children,
        expand: tree.expandDir,
        collapse: tree.collapseDir,
      },
      get,
      notFound: (input: string) => store.file[path.normalize(input)]?.notFound ?? false,
      load,
      exists,
      scrollTop,
      scrollLeft,
      setScrollTop,
      setScrollLeft,
      selectedLines,
      setSelectedLines,
      searchFiles: (query: string, options?: { limit?: number; signal?: AbortSignal }) =>
        search(query, "false", options),
      searchFilesAndDirectories: (query: string, options?: { limit?: number; signal?: AbortSignal }) =>
        search(query, "true", options),
    }
  },
})

export function stripFileProtocol(input: string) {
  if (!input.startsWith("file://")) return input

  return input.slice("file://".length)
}

export function stripQueryAndHash(input: string) {
  const hashIndex = input.indexOf("#")
  const queryIndex = input.indexOf("?")

  if (hashIndex !== -1 && queryIndex !== -1) {
    return input.slice(0, Math.min(hashIndex, queryIndex))
  }

  if (hashIndex !== -1) return input.slice(0, hashIndex)

  if (queryIndex !== -1) return input.slice(0, queryIndex)

  return input
}

export function unquoteGitPath(input: string) {
  if (!input.startsWith('"')) return input

  if (!input.endsWith('"')) return input
  const body = input.slice(1, -1)
  const bytes: number[] = []

  for (let i = 0; i < body.length; i++) {
    const char = body[i]!

    if (char !== "\\") {
      bytes.push(char.charCodeAt(0))
      continue
    }

    const next = body[i + 1]

    if (!next) {
      bytes.push("\\".charCodeAt(0))
      continue
    }

    if (next >= "0" && next <= "7") {
      const chunk = body.slice(i + 1, i + 4)
      const match = chunk.match(/^[0-7]{1,3}/)

      if (!match) {
        bytes.push(next.charCodeAt(0))
        i++
        continue
      }

      bytes.push(parseInt(match[0], 8))
      i += match[0].length
      continue
    }

    const escaped =
      next === "n"
        ? "\n"
        : next === "r"
          ? "\r"
          : next === "t"
            ? "\t"
            : next === "b"
              ? "\b"
              : next === "f"
                ? "\f"
                : next === "v"
                  ? "\v"
                  : next === "\\" || next === '"'
                    ? next
                    : undefined

    bytes.push((escaped ?? next).charCodeAt(0))
    i++
  }

  return new TextDecoder().decode(new Uint8Array(bytes))
}

export function decodeFilePath(input: string) {
  try {
    return decodeURIComponent(input)
  } catch {
    return input
  }
}

export function createPathHelpers(scope: () => string) {
  const normalize = (input: string) => {
    const root = scope()

    // file:///C:/dir becomes /C:/dir once the protocol is gone; restore the drive form.
    let path = unquoteGitPath(decodeFilePath(stripQueryAndHash(stripFileProtocol(input)))).replace(
      /^[/\\]([A-Za-z]:)/,
      "$1",
    )

    // Separator-agnostic prefix stripping for Cygwin/native Windows compatibility
    // Only case-insensitive on Windows (drive letter or UNC paths)
    const windows = /^[A-Za-z]:/.test(root) || root.startsWith("\\\\")
    const canonRoot = windows ? root.replace(/\\/g, "/").toLowerCase() : root.replace(/\\/g, "/")
    const canonPath = windows ? path.replace(/\\/g, "/").toLowerCase() : path.replace(/\\/g, "/")

    if (
      canonPath.startsWith(canonRoot) &&
      (canonRoot.endsWith("/") || canonPath === canonRoot || canonPath[canonRoot.length] === "/")
    ) {
      // Slice from original path to preserve native separators, then drop the separator itself.
      path = path.slice(root.length).replace(/^[/\\]/, "")
    }

    if (path.startsWith("./") || path.startsWith(".\\")) {
      path = path.slice(2)
    }

    // An absolute path that is not under the root stays absolute; it is a file outside the workspace.
    return path
  }

  /** Whether a normalized path points outside the workspace root. */
  const absolute = (path: string) => /^[A-Za-z]:[/\\]/.test(path) || path.startsWith("/") || path.startsWith("\\\\")

  const normalizeDir = (input: string) => {
    const path = normalize(input)
    const root = scope()
    const windows = /^[A-Za-z]:/.test(root) || root.startsWith("\\\\")

    return (windows ? path.replace(/\\/g, "/") : path).replace(/\/+$/, "")
  }

  return {
    normalize,
    absolute,
    normalizeDir,
  }
}

import { createStore, produce, reconcile } from "solid-js/store"
import type { FileNode } from "@/runtime/server/types"

type DirectoryState = {
  expanded: boolean
  loaded?: boolean
  loading?: boolean
  error?: string
  children?: string[]
}

type TreeStoreOptions = {
  scope: () => string
  normalizeDir: (input: string) => string
  list: (input: string) => Promise<FileNode[]>
  onError: (message: string) => void
}

export function createFileTreeStore(options: TreeStoreOptions) {
  const [tree, setTree] = createStore<{
    node: Record<string, FileNode>
    dir: Record<string, DirectoryState>
  }>({
    node: {},
    dir: { "": { expanded: true } },
  })

  const inflight = new Map<string, Promise<void>>()

  const reset = () => {
    inflight.clear()
    setTree("node", reconcile({}))
    setTree("dir", reconcile({}))
    setTree("dir", "", { expanded: true })
  }

  const ensureDir = (path: string) => {
    if (tree.dir[path]) return
    setTree("dir", path, { expanded: false })
  }

  const listDir = (input: string, opts?: { force?: boolean }) => {
    const dir = options.normalizeDir(input)
    ensureDir(dir)

    const current = tree.dir[dir]

    if (!opts?.force && current?.loaded) return Promise.resolve()

    const pending = inflight.get(dir)

    if (pending) return pending

    setTree(
      "dir",
      dir,
      produce((draft) => {
        draft.loading = true
        draft.error = undefined
      }),
    )

    const directory = options.scope()

    const promise = options
      .list(dir)
      .then((nodes) => {
        if (options.scope() !== directory) return
        const prevChildren = tree.dir[dir]?.children ?? []
        const nextChildren = nodes.map((node) => node.path)
        const nextSet = new Set(nextChildren)

        setTree(
          "node",
          produce((draft) => {
            const removedDirs: string[] = []

            for (const child of prevChildren) {
              if (nextSet.has(child)) continue
              const existing = draft[child]

              if (existing?.type === "directory") removedDirs.push(child)
              delete draft[child]
            }

            if (removedDirs.length > 0) {
              const keys = Object.keys(draft)

              for (const key of keys) {
                for (const removed of removedDirs) {
                  if (!key.startsWith(removed + "/")) continue
                  delete draft[key]
                  break
                }
              }
            }

            for (const node of nodes) {
              draft[node.path] = node
            }
          }),
        )

        setTree(
          "dir",
          dir,
          produce((draft) => {
            draft.loaded = true
            draft.loading = false
            draft.children = nextChildren
          }),
        )
      })
      .catch((e) => {
        if (options.scope() !== directory) return
        setTree(
          "dir",
          dir,
          produce((draft) => {
            draft.loading = false
            draft.error = e.message
          }),
        )
        options.onError(e.message)
      })
      .finally(() => {
        inflight.delete(dir)
      })

    inflight.set(dir, promise)

    return promise
  }

  // `list: false` marks a directory expanded without fetching its children, for
  // trees whose nodes are synthesized from a filter; listing directories that
  // only exist on a diff's base branch fails and surfaces error toasts.
  const expandDir = (input: string, behavior?: { list?: boolean }) => {
    const dir = options.normalizeDir(input)
    ensureDir(dir)
    setTree("dir", dir, "expanded", true)

    if (behavior?.list === false) return
    void listDir(dir)
  }

  const collapseDir = (input: string) => {
    const dir = options.normalizeDir(input)
    ensureDir(dir)
    setTree("dir", dir, "expanded", false)
  }

  const dirState = (input: string) => {
    const dir = options.normalizeDir(input)

    return tree.dir[dir]
  }

  const children = (input: string) => {
    const dir = options.normalizeDir(input)
    const ids = tree.dir[dir]?.children

    if (!ids) return []
    const out: FileNode[] = []

    for (const id of ids) {
      const node = tree.node[id]

      if (node) out.push(node)
    }

    return out
  }

  return {
    listDir,
    expandDir,
    collapseDir,
    dirState,
    children,
    node: (path: string) => tree.node[path],
    isLoaded: (path: string) => Boolean(tree.dir[path]?.loaded),
    reset,
  }
}

import type { FileContent } from "@opencode/gui-extensions/sdk"
import { Schema } from "effect"
import { Persistence } from "@/runtime/persistence/schema"

export const FileSelection = Persistence.struct({
  startLine: Schema.Number,
  startChar: Schema.Number,
  endLine: Schema.Number,
  endChar: Schema.Number,
})

export type FileSelection = typeof FileSelection.Type

export const SelectedLineRange = Persistence.struct({
  start: Schema.Number,
  end: Schema.Number,
  side: Persistence.optional(Schema.Literals(["additions", "deletions"])),
  endSide: Persistence.optional(Schema.Literals(["additions", "deletions"])),
})

export type SelectedLineRange = typeof SelectedLineRange.Type

export type FileViewState = {
  scrollTop?: number
  scrollLeft?: number
  selectedLines?: SelectedLineRange | null
}

export type FileState = {
  path: string
  name: string
  loaded?: boolean
  loading?: boolean
  notFound?: boolean
  error?: string
  content?: FileContent
}

export function selectionFromLines(range: SelectedLineRange): FileSelection {
  const startLine = Math.min(range.start, range.end)
  const endLine = Math.max(range.start, range.end)

  return {
    startLine,
    endLine,
    startChar: 0,
    endChar: 0,
  }
}

import { createEffect, createRoot } from "solid-js"
import { produce } from "solid-js/store"
import { Schema } from "effect"
import { Persist, persisted } from "@/runtime/persistence/storage"
import { Persistence } from "@/runtime/persistence/schema"
import { createScopedCache } from "@/runtime/server/scoped-cache"
import { SelectedLineRange } from "./types"
import type { ServerScope } from "@/runtime/server/scope"

const WORKSPACE_KEY = "__workspace__"

const MAX_FILE_VIEW_SESSIONS = 20

const MAX_VIEW_FILES = 500

const FileViewSchema = Persistence.struct({
  scrollTop: Persistence.optional(Schema.Finite),
  scrollLeft: Persistence.optional(Schema.Finite),
  selectedLines: Persistence.optional(Schema.NullOr(SelectedLineRange)),
})

export const FileViewsSchema = Schema.Struct({
  file: Persistence.record(Persistence.fallback(FileViewSchema, () => ({}))),
})

function normalizeSelectedLines(range: SelectedLineRange): SelectedLineRange {
  if (range.start <= range.end) return { ...range }

  const startSide = range.side
  const endSide = range.endSide ?? startSide

  return {
    ...range,
    start: range.end,
    end: range.start,
    side: endSide,
    endSide: startSide !== endSide ? startSide : undefined,
  }
}

function equalSelectedLines(a: SelectedLineRange | null | undefined, b: SelectedLineRange | null | undefined) {
  if (!a && !b) return true

  if (!a || !b) return false
  const left = normalizeSelectedLines(a)
  const right = normalizeSelectedLines(b)

  return (
    left.start === right.start && left.end === right.end && left.side === right.side && left.endSide === right.endSide
  )
}

function createViewSession(scope: ServerScope, dir: string, id: string | undefined) {
  const [view, setView, _, ready] = persisted(Persist.serverScoped(scope, dir, id, "file-view"), FileViewsSchema, {
    file: {},
  })

  const meta = { pruned: false }

  const pruneView = (keep?: string) => {
    const keys = Object.keys(view.file)

    if (keys.length <= MAX_VIEW_FILES) return

    const drop = keys.filter((key) => key !== keep).slice(0, keys.length - MAX_VIEW_FILES)

    if (drop.length === 0) return

    setView(
      produce((draft) => {
        for (const key of drop) {
          delete draft.file[key]
        }
      }),
    )
  }

  createEffect(() => {
    if (!ready()) return

    if (meta.pruned) return
    meta.pruned = true
    pruneView()
  })

  const scrollTop = (path: string) => view.file[path]?.scrollTop
  const scrollLeft = (path: string) => view.file[path]?.scrollLeft
  const selectedLines = (path: string) => view.file[path]?.selectedLines

  const setScrollTop = (path: string, top: number) => {
    setView(
      produce((draft) => {
        const file = draft.file[path] ?? (draft.file[path] = {})

        if (file.scrollTop === top) return
        file.scrollTop = top
      }),
    )
    pruneView(path)
  }

  const setScrollLeft = (path: string, left: number) => {
    setView(
      produce((draft) => {
        const file = draft.file[path] ?? (draft.file[path] = {})

        if (file.scrollLeft === left) return
        file.scrollLeft = left
      }),
    )
    pruneView(path)
  }

  const setSelectedLines = (path: string, range: SelectedLineRange | null) => {
    const next = range ? normalizeSelectedLines(range) : null
    setView(
      produce((draft) => {
        const file = draft.file[path] ?? (draft.file[path] = {})

        if (equalSelectedLines(file.selectedLines, next)) return
        file.selectedLines = next
      }),
    )
    pruneView(path)
  }

  return {
    ready,
    scrollTop,
    scrollLeft,
    selectedLines,
    setScrollTop,
    setScrollLeft,
    setSelectedLines,
  }
}

export function createFileViewCache(scope: ServerScope) {
  const cache = createScopedCache(
    (key) => {
      const split = key.lastIndexOf("\n")
      const dir = split >= 0 ? key.slice(0, split) : key
      const id = split >= 0 ? key.slice(split + 1) : WORKSPACE_KEY

      return createRoot((dispose) => ({
        value: createViewSession(scope, dir, id === WORKSPACE_KEY ? undefined : id),
        dispose,
      }))
    },
    {
      maxEntries: MAX_FILE_VIEW_SESSIONS,
      dispose: (entry) => entry.dispose(),
    },
  )

  return {
    load: (dir: string, id: string | undefined) => {
      const key = `${dir}\n${id ?? WORKSPACE_KEY}`

      return cache.get(key).value
    },
    clear: () => cache.clear(),
  }
}

import { describe, expect, test } from "bun:test"
import type { OpenCodeEvent } from "@opencode/client/promise"
import { invalidateFromWatcher } from "./watcher"

type FilesystemEvent = Extract<OpenCodeEvent, { type: "filesystem.changed" }>

const filesystemEvent = (file: string, event: FilesystemEvent["data"]["event"]): FilesystemEvent => ({
  id: `evt_${file}`,
  created: 1,
  type: "filesystem.changed",
  data: { file, event },
})

describe("file watcher invalidation", () => {
  test("reloads open files and refreshes loaded parent on add", () => {
    const loads: string[] = []
    const refresh: string[] = []
    invalidateFromWatcher(filesystemEvent("src/new.ts", "add"), {
      normalize: (input) => input,
      hasFile: (path) => path === "src/new.ts",
      loadFile: (path) => loads.push(path),
      node: () => undefined,
      isDirLoaded: (path) => path === "src",
      refreshDir: (path) => refresh.push(path),
    })

    expect(loads).toEqual(["src/new.ts"])
    expect(refresh).toEqual(["src"])
  })

  test("reloads files that are open in tabs", () => {
    const loads: string[] = []

    invalidateFromWatcher(filesystemEvent("src/open.ts", "change"), {
      normalize: (input) => input,
      hasFile: () => false,
      isOpen: (path) => path === "src/open.ts",
      loadFile: (path) => loads.push(path),
      node: () => ({
        path: "src/open.ts",
        type: "file",
        name: "open.ts",
        absolute: "/repo/src/open.ts",
        ignored: false,
      }),
      isDirLoaded: () => false,
      refreshDir: () => {},
    })

    expect(loads).toEqual(["src/open.ts"])
  })

  test("refreshes only changed loaded directory nodes", () => {
    const refresh: string[] = []

    invalidateFromWatcher(filesystemEvent("src", "change"), {
      normalize: (input) => input,
      hasFile: () => false,
      loadFile: () => {},
      node: () => ({ path: "src", type: "directory", name: "src", absolute: "/repo/src", ignored: false }),
      isDirLoaded: (path) => path === "src",
      refreshDir: (path) => refresh.push(path),
    })

    invalidateFromWatcher(filesystemEvent("src/file.ts", "change"), {
      normalize: (input) => input,
      hasFile: () => false,
      loadFile: () => {},
      node: () => ({
        path: "src/file.ts",
        type: "file",
        name: "file.ts",
        absolute: "/repo/src/file.ts",
        ignored: false,
      }),
      isDirLoaded: () => true,
      refreshDir: (path) => refresh.push(path),
    })

    expect(refresh).toEqual(["src"])
  })

  test("ignores invalid or git watcher updates", () => {
    const refresh: string[] = []

    invalidateFromWatcher(filesystemEvent(".git/index.lock", "change"), {
      normalize: (input) => input,
      hasFile: () => true,
      loadFile: () => {
        throw new Error("should not load")
      },
      node: () => undefined,
      isDirLoaded: () => true,
      refreshDir: (path) => refresh.push(path),
    })

    expect(refresh).toEqual([])
  })
})

import type { FileNode } from "@/runtime/server/types"
import type { OpenCodeEvent } from "@opencode/client/promise"

type WatcherEvent = Extract<OpenCodeEvent, { type: "filesystem.changed" }>

type WatcherOps = {
  normalize: (input: string) => string
  hasFile: (path: string) => boolean
  isOpen?: (path: string) => boolean
  loadFile: (path: string) => void
  node: (path: string) => FileNode | undefined
  isDirLoaded: (path: string) => boolean
  refreshDir: (path: string) => void
}

export function invalidateFromWatcher(event: WatcherEvent, ops: WatcherOps) {
  const path = ops.normalize(event.data.file)

  if (!path) return

  if (path.startsWith(".git/")) return

  if (ops.hasFile(path) || ops.isOpen?.(path)) {
    ops.loadFile(path)
  }

  if (event.data.event === "change") {
    if (ops.node(path)?.type !== "directory") return

    if (!ops.isDirLoaded(path)) return
    ops.refreshDir(path)

    return
  }

  const parent = path.split("/").slice(0, -1).join("/")

  if (!ops.isDirLoaded(parent)) return

  ops.refreshDir(parent)
}

import { describe, expect, test } from "bun:test"
import { QueryClient } from "@tanstack/solid-query"
import type { WorktreeDirectory } from "@opencode/client/promise"
import { createWorktreeInventory, withWorktreeInventory, worktreeInventoryKey } from "./inventory"
import { ServerScope } from "@/runtime/server/scope"
import { normalizeProjectInfo, updateProjectInfo } from "@/runtime/server/global-sync/utils"

function setup(list: (directory: string) => Promise<WorktreeDirectory[]>) {
  const client = new QueryClient()
  const refreshed = Promise.withResolvers<void>()
  const refreshes: string[] = []
  const calls: string[] = []
  const updates: Array<[string, WorktreeDirectory[]]> = []

  const inventory = createWorktreeInventory({
    scope: ServerScope.local,
    queryClient: client,
    api: () => ({
      list: (input) => {
        const directory = input.projectID
        calls.push(directory)

        return list(directory)
      },
      refresh: (input) => {
        refreshes.push(input.projectID)

        return refreshed.promise
      },
    }),
    updated: (directory, items) => {
      updates.push([directory, items])
    },
  })

  return { client, calls, updates, inventory, refreshed, refreshes }
}

describe("createWorktreeInventory", () => {
  test("lists a project, shares in-flight work, and publishes each result", async () => {
    const gate = Promise.withResolvers<void>()

    const setupResult = setup(async (directory) => {
      await gate.promise

      return [{ directory }, { directory: `${directory}/feature`, strategy: "git" }]
    })

    const first = setupResult.inventory.list("/repo")
    const second = setupResult.inventory.list("/repo")
    expect(setupResult.calls).toEqual(["/repo"])
    gate.resolve()
    expect(await first).toHaveLength(2)
    expect(await second).toHaveLength(2)
    await setupResult.inventory.list("/repo")
    expect(setupResult.calls).toEqual(["/repo", "/repo"])
    expect(setupResult.updates).toEqual([
      ["/repo", [{ directory: "/repo" }, { directory: "/repo/feature", strategy: "git" }]],
      ["/repo", [{ directory: "/repo" }, { directory: "/repo/feature", strategy: "git" }]],
    ])
    expect(setupResult.inventory.cached("/repo")).toHaveLength(2)
    expect(setupResult.refreshes).toEqual([])
    setupResult.client.clear()
  })

  test("list reads saved inventory without discovery", async () => {
    const setupResult = setup(async (directory) => [{ directory }])
    await setupResult.inventory.list("/opened")
    expect(setupResult.calls).toEqual(["/opened"])
    expect(setupResult.refreshes).toEqual([])
    setupResult.client.clear()
  })

  test("a failed list is not cached and never rejects the caller", async () => {
    let fail = true

    const setupResult = setup(async (directory) => {
      if (fail) throw new Error("Location unavailable")

      return [{ directory }]
    })

    expect(await setupResult.inventory.list("/repo")).toBeUndefined()
    expect(setupResult.inventory.cached("/repo")).toBeUndefined()
    fail = false
    expect(await setupResult.inventory.list("/repo")).toEqual([{ directory: "/repo" }])
    expect(setupResult.calls).toEqual(["/repo", "/repo"])
    setupResult.client.clear()
  })

  test("keys are partitioned by server and use opaque project IDs", () => {
    const remote = "https://remote.example" as typeof ServerScope.local
    expect(worktreeInventoryKey(ServerScope.local, "project")).not.toEqual(
      worktreeInventoryKey(ServerScope.local, "project/"),
    )
    expect(worktreeInventoryKey(ServerScope.local, "/repo")).not.toEqual(worktreeInventoryKey(remote, "/repo"))
  })

  test("refresh discovers without changing cached inventory until the next list", async () => {
    const rows = [{ directory: "/repo" }]
    const result = setup(async () => [...rows])
    expect(await result.inventory.list("project")).toEqual(rows)
    const pending = result.inventory.refresh("project")
    rows.push({ directory: "/external" })
    expect(result.inventory.cached("project")).toEqual([{ directory: "/repo" }])
    result.refreshed.resolve()
    expect(await pending).toBeUndefined()
    expect(result.calls).toEqual(["project"])
    expect(result.refreshes).toEqual(["project"])
    expect(await result.inventory.list("project")).toEqual(rows)
    result.client.clear()
  })
})

describe("withWorktreeInventory", () => {
  const metadata = {
    id: "project",
    canonical: "/repo",
    name: "Before",
    time: { created: 1, updated: 1, active: 1 },
    sandboxes: [],
  }

  test("derives the workspace list from the inventory, excluding the project root", () => {
    const worktrees = [
      { directory: "/repo/" },
      { directory: "/repo/feature", strategy: "git" },
      { directory: "/elsewhere" },
    ]

    expect(withWorktreeInventory(normalizeProjectInfo(metadata), worktrees)).toMatchObject({
      worktree: "/repo",
      sandboxes: ["/repo/feature", "/elsewhere"],
      worktrees,
    })
  })

  test("leaves metadata untouched without an inventory and survives metadata updates", () => {
    const project = normalizeProjectInfo(metadata)
    expect(withWorktreeInventory(project, undefined)).toBe(project)
    const cached = [{ directory: "/repo" }, { directory: "/repo/feature", strategy: "git" }]

    const updated = updateProjectInfo(
      { ...withWorktreeInventory(project, cached), worktree: "/old-repo" },
      { ...metadata, name: "After" },
    )

    expect(updated).toMatchObject({ worktree: "/repo", worktrees: cached })
    expect(withWorktreeInventory(updated, cached)).toMatchObject({ name: "After", sandboxes: ["/repo/feature"] })
  })
})

