describe("isWorkspaceSelection", () => {
  const project = { worktree: "/repo", sandboxes: ["/workspaces/feature"] }

  test("accepts local, new, and managed workspace selections", () => {
    expect(isWorkspaceSelection(project, "main")).toBe(true)
    expect(isWorkspaceSelection(project, "create")).toBe(true)
    expect(isWorkspaceSelection(project, "/repo/")).toBe(true)
    expect(isWorkspaceSelection(project, "/workspaces/feature/")).toBe(true)
    expect(isWorkspaceSelection({ worktree: "C:\\repo" }, "c:\\repo\\")).toBe(true)
    expect(isWorkspaceSelection(project, "/other/workspace")).toBe(false)
  })
})

describe("workspaceSelectionDestination", () => {
  test("keeps local intent for main and the project root, otherwise creates a workspace", () => {
    expect(workspaceSelectionDestination("main", "/repo")).toBe("main")
    expect(workspaceSelectionDestination("/repo/", "/repo")).toBe("main")
    expect(workspaceSelectionDestination("c:\\repo\\", "C:\\repo")).toBe("main")
    expect(workspaceSelectionDestination("create", "/repo")).toBe("create")
    expect(workspaceSelectionDestination("/workspaces/feature", "/repo")).toBe("create")
  })
})

test("groups and filters workspace inventory by project", () => {
  const inventory = workspaceInventory([
    {
      id: "a",
      worktree: "/a",
      sandboxes: ["/a", "/a/one", "/a/two"],
      worktrees: [
        { directory: "/a" },
        { directory: "/a/one", strategy: "git" },
        { directory: "/a/two", strategy: "git" },
      ],
    },
    {
      id: "b",
      worktree: "/b",
      sandboxes: ["/b/one"],
      worktrees: [{ directory: "/b/one", strategy: "git" }],
    },
  ])

  expect(inventory.map((item) => [item.project.id, item.directory])).toEqual([
    ["a", "/a/one"],
    ["a", "/a/two"],
    ["b", "/b/one"],
  ])
  expect(filterWorkspaceInventory(inventory, "a").map((item) => item.directory)).toEqual(["/a/one", "/a/two"])
  expect(filterWorkspaceInventory(inventory, "all")).toEqual(inventory)
})

test("reports every workspace deletion condition", () => {
  const session = (directory: string) => ({ location: { directory }, time: { created: 1, updated: 1 } }) as SessionInfo
  expect(
    inspectWorkspaceDeletion({
      workspace: "/workspace",
      activeDirectory: "/workspace/app",
      sessions: [],
      status: "dirty",
    }),
  ).toEqual({ active: true, linked: false, dirty: true })
  expect(
    inspectWorkspaceDeletion({
      workspace: "/workspace",
      sessions: [session("/workspace/packages/app")],
      status: "dirty",
    }),
  ).toEqual({ active: false, linked: true, dirty: true })
  expect(inspectWorkspaceDeletion({ workspace: "/workspace", sessions: [], status: "dirty" })).toEqual({
    active: false,
    linked: false,
    dirty: true,
  })
  expect(inspectWorkspaceDeletion({ workspace: "/workspace", sessions: [], status: "clean" })).toEqual({
    active: false,
    linked: false,
    dirty: false,
  })
  expect(
    inspectWorkspaceDeletion({
      workspace: "/workspace",
      sessions: [
        { location: { directory: "/workspace" }, time: { created: 1, updated: 1, archived: 2 } } as SessionInfo,
      ],
      status: "clean",
    }),
  ).toEqual({ active: false, linked: false, dirty: false })
})

test("groups nested non-archived workspace sessions by latest activity", () => {
  const session = (id: string, directory: string, updated: number, archived?: number) =>
    ({ id, location: { directory }, time: { created: 1, updated, archived } }) as SessionInfo

  const sessions = sessionsForWorkspace(
    [
      session("old", "/workspace", 2),
      session("nested", "/workspace/packages/app", 3),
      session("archived", "/workspace", 4, 5),
      session("other", "/other", 6),
    ],
    "/workspace",
  )

  expect(sessions.map((item) => item.id)).toEqual(["nested", "old"])
})

test("merges workspace placement by freshness with authoritative server ties", () => {
  const session = (directory: string, updated: number) =>
    ({ id: "session", location: { directory }, time: { created: 1, updated } }) as SessionInfo

  expect(
    mergeWorkspaceSessionInventory([session("/destination", 3)], [session("/source", 2)])[0]?.location.directory,
  ).toBe("/destination")
  expect(
    mergeWorkspaceSessionInventory([session("/destination", 3)], [session("/source", 3)])[0]?.location.directory,
  ).toBe("/destination")
  expect(
    mergeWorkspaceSessionInventory([session("/destination", 2)], [session("/source", 3)])[0]?.location.directory,
  ).toBe("/source")
})

import { containsDirectory, sameDirectory } from "@opencode/util/path"
import type { WorkspaceDefaultDestination, WorkspaceLastUsed } from "@/settings/model"
import type { SessionInfo, WorktreeDirectory } from "@opencode/client/promise"

type WorkspaceProject = {
  worktree: string
  sandboxes?: readonly string[]
  worktrees?: readonly WorktreeDirectory[]
}

export function workspaceDirectories(project: WorkspaceProject) {
  return (project.sandboxes ?? []).filter((directory) => !sameDirectory(project.worktree, directory))
}

export function managedWorkspaceDirectories(project: WorkspaceProject) {
  return (project.worktrees ?? [])
    .filter((worktree) => worktree.strategy !== undefined)
    .map((worktree) => worktree.directory)
    .filter((directory) => !sameDirectory(project.worktree, directory))
}

export function workspaceInventory<T extends WorkspaceProject & { id: string }>(projects: readonly T[]) {
  return projects.flatMap((project) =>
    managedWorkspaceDirectories(project).map((directory) => ({ directory, project })),
  )
}

export function filterWorkspaceInventory<T extends { project: { id: string } }>(
  workspaces: readonly T[],
  project: string,
) {
  if (project === "all") return [...workspaces]

  return workspaces.filter((workspace) => workspace.project.id === project)
}

export function sessionsForWorkspace(sessions: readonly SessionInfo[], workspace: string) {
  return sessions
    .filter((session) => session.time.archived === undefined)
    .filter((session) => containsDirectory(workspace, session.location.directory))
    .toSorted((a, b) => b.time.updated - a.time.updated)
}

export function mergeWorkspaceSessionInventory(server: readonly SessionInfo[], cached: readonly SessionInfo[]) {
  const sessions = new Map(server.map((session) => [session.id, session]))
  cached.forEach((session) => {
    const current = sessions.get(session.id)

    if (!current || session.time.updated > current.time.updated) sessions.set(session.id, session)
  })

  return [...sessions.values()]
}

export function removeWorkspacesSequentially<T>(workspaces: readonly T[], remove: (workspace: T) => Promise<void>) {
  return workspaces.reduce((previous, workspace) => previous.then(() => remove(workspace)), Promise.resolve())
}

export type WorkspaceDeleteInspection = {
  active: boolean
  linked: boolean
  dirty: boolean
}

export function inspectWorkspaceDeletion(input: {
  workspace: string
  activeDirectory?: string
  sessions: readonly SessionInfo[]
  status: "clean" | "dirty"
}): WorkspaceDeleteInspection {
  return {
    active: !!input.activeDirectory && containsDirectory(input.workspace, input.activeDirectory),
    linked: input.sessions.some(
      (session) =>
        session.time.archived === undefined && containsDirectory(input.workspace, session.location.directory),
    ),
    dirty: input.status === "dirty",
  }
}

export function isWorkspaceDirectory(project: WorkspaceProject | undefined, directory: string) {
  if (!project || sameDirectory(project.worktree, directory)) return false

  return workspaceDirectories(project).some((workspace) => containsDirectory(workspace, directory))
}

export function isProjectDirectory(project: WorkspaceProject | undefined, directory: string) {
  if (!project) return false

  return [project.worktree, ...(project.sandboxes ?? [])].some((root) => containsDirectory(root, directory))
}

export function isWorkspaceSelection(project: WorkspaceProject | undefined, selection: string) {
  if (selection === "main" || selection === "create") return true

  if (!project) return false

  if (sameDirectory(project.worktree, selection)) return true

  return isWorkspaceDirectory(project, selection)
}

export function workspaceSelectionDestination(selection: string, projectWorktree: string) {
  return selection === "main" || sameDirectory(selection, projectWorktree) ? "main" : "create"
}

export function workspaceDefaultSelection(
  setting: WorkspaceDefaultDestination,
  lastUsed: WorkspaceLastUsed | undefined,
) {
  if (setting === "local") return "main"

  if (setting === "new") return "create"

  return lastUsed === "workspace" ? "create" : "main"
}

import "@pierre/trees/web-components"
import { FileTree } from "@pierre/trees"
import { Dialog, DialogBody, DialogFooter, DialogHeader, DialogTitle } from "@opencode/ui/dialog"
import { Button } from "@opencode/ui/button"
import { TextInput } from "@opencode/ui/text-input"
import { useDialog } from "@opencode/ui/context/dialog"
import { createEffect, createMemo, createResource, createSignal, For, onCleanup, onMount, Show } from "solid-js"
import { useGlobal } from "@/runtime/server/runtime"
import { useLanguage } from "@/runtime/i18n/language"
import { ServerConnection } from "@/runtime/server/registry"
import type { LocationRef } from "@opencode/client/promise"
import {
  absoluteTreePath,
  activeTreeNavigation,
  advanceTreePreload,
  nextSuggestionIndex,
  nextTreeScrollTop,
  pickerFileSearchQuery,
  pickerAbsoluteInput,
  pickerMode,
  preloadTreeDirectories,
  cleanPickerInput,
  createPriorityTaskQueue,
  createDirectorySearch,
  currentPickerSuggestions,
  displayPickerPath,
  pickerParent,
  pickerRoot,
  listPickerDirectory,
  pickerRelativePath,
  pickerAbsolutePath,
} from "./domain"
import "./dialog.css"
import { Divider } from "@opencode/ui/divider"

interface DirectoryPickerDialogProps {
  title?: string
  multiple?: boolean
  onSelect: (result: string | string[] | null) => void
  server: ServerConnection.Any
  location?: LocationRef
  mode?: "directory" | "file"
  start?: string
}

export function DirectoryPickerDialog(props: DirectoryPickerDialogProps) {
  const global = useGlobal()
  const { sync, sdk } = global.ensureServerCtx(props.server)
  const dialog = useDialog()
  const language = useLanguage()
  const policy = pickerMode(props.mode ?? "directory", props.start)

  const action = {
    file: language.t("dialog.directory.action.selectFile"),
    directory: language.t("dialog.directory.action.selectFolder"),
  }

  const [root, setRoot] = createSignal("")
  const [input, setInput] = createSignal("")
  const [selected, setSelected] = createSignal("")
  const [suggestionsOpen, setSuggestionsOpen] = createSignal(false)
  const [activeSuggestion, setActiveSuggestion] = createSignal(-1)
  const [loading, setLoading] = createSignal(false)
  const [error, setError] = createSignal(false)
  const [rootValid, setRootValid] = createSignal(false)
  const listings = new Map<string, Promise<Array<{ name: string; type: "file" | "directory" }> | undefined>>()
  const loads = createPriorityTaskQueue<Array<{ name: string; type: "file" | "directory" }> | undefined>(3)
  const advanced = new Set<string>()
  let tree: FileTree | undefined
  let container: HTMLDivElement | undefined
  let pathArea: HTMLDivElement | undefined
  let navigation = 0

  const [fallbackPath] = createResource(
    () => (props.location ? undefined : true),
    () => sdk.api.location.get().catch(() => undefined),
    { initialValue: undefined },
  )

  const home = createMemo(() => sync.data.path.home || "")

  const location = createMemo(() => {
    const current = props.location ?? fallbackPath.latest

    return current ? { directory: current.directory } : undefined
  })

  const start = createMemo(
    () =>
      props.start ||
      sync.data.path.home ||
      props.location?.directory ||
      sync.data.path.directory ||
      fallbackPath.latest?.directory,
  )

  const search = createDirectorySearch({ sdk, home, location, base: () => root() || start() })

  const [suggestions] = createResource(input, async (value) => {
    const cleaned = cleanPickerInput(value)
    const typed = cleaned.replace(/\/+$/, "")
    const current = displayPickerPath(root(), value, home()).replace(/\/+$/, "")

    if (!cleaned || (root() && typed === current)) return { query: value, items: [] }
    const directories = (await search(value)).map((absolute) => ({ absolute, type: "directory" as const }))

    if (!policy.includeFiles) return { query: value, items: directories.slice(0, 5) }
    const base = location()?.directory

    if (!base) return { query: value, items: directories.slice(0, 5) }
    const query = pickerRelativePath(base, pickerAbsoluteInput(cleaned, home(), root() || base))

    if (query === undefined) return { query: value, items: directories.slice(0, 5) }

    const files = await sdk.api.file
      .find({
        location: location(),
        query,
        type: "file",
        limit: 20,
      })
      .then((result) => result.data)
      .catch(() => [])

    const results = [
      ...directories,
      ...files.map((entry) => ({ absolute: pickerAbsolutePath(entry.path, base), type: "file" as const })),
    ]

    return {
      query: value,
      items: Array.from(new Map(results.map((result) => [result.absolute, result])).values()).slice(0, 8),
    }
  })

  const currentSuggestions = createMemo(() => currentPickerSuggestions(suggestions.latest, input()))

  async function load(path: string, generation: number, eager = false) {
    const key = path.replace(/\/+$/, "")
    setError(false)
    const absolute = absoluteTreePath(root(), key)
    const existing = listings.get(key)

    if (existing && !eager) loads.promote(`${generation}:${key}`)

    const request =
      existing ??
      loads.schedule(`${generation}:${key}`, eager ? "background" : "user", () => {
        if (!activeTreeNavigation(generation, navigation)) return Promise.resolve(undefined)
        const current = location()

        if (!current) return Promise.resolve(undefined)

        return listPickerDirectory(sdk, current, absolute).catch(() => undefined)
      })

    listings.set(key, request)
    const nodes = await request

    if (!activeTreeNavigation(generation, navigation)) return false

    if (!nodes) {
      listings.delete(key)

      if (!key) setError(true)

      return false
    }

    tree?.batch(policy.entries(key, nodes).map((item) => ({ type: "add", path: item })))

    if (!eager && advanceTreePreload(advanced, key)) {
      for (const directory of preloadTreeDirectories(key, nodes)) void load(directory, generation, true)
    }

    return true
  }

  async function navigate(path: string) {
    const value = policy.navigation(pickerAbsoluteInput(cleanPickerInput(path), home(), root() || start() || home()))

    if (!value) return
    const token = ++navigation
    setLoading(true)
    setRootValid(false)
    setSelected("")
    setSuggestionsOpen(false)
    setActiveSuggestion(-1)
    setRoot(value)
    setInput(displayPickerPath(value, value, home()))
    listings.clear()
    advanced.clear()
    tree?.resetPaths([])
    const valid = await load("", token)

    if (!activeTreeNavigation(token, navigation)) return
    setRootValid(valid)
    setLoading(false)
  }

  function complete() {
    const items = currentSuggestions()
    const match = items[activeSuggestion()] ?? items[0]

    if (!match) return
    const value = displayPickerPath(match.absolute, input(), home())
    setInput(match.type === "directory" && !value.endsWith("/") ? value + "/" : value)

    if (match.type === "file") {
      setSelected(policy.selection(root(), pickerFileSearchQuery(root(), match.absolute, home())) ?? "")
      setSuggestionsOpen(false)
      setActiveSuggestion(-1)
    }
  }

  function chooseSuggestion(suggestion: { absolute: string; type: "file" | "directory" }) {
    if (suggestion.type === "directory") {
      void navigate(suggestion.absolute)

      return
    }

    setInput(displayPickerPath(suggestion.absolute, input(), home()))
    setSelected(policy.selection(root(), pickerFileSearchQuery(root(), suggestion.absolute, home())) ?? "")
    setSuggestionsOpen(false)
    setActiveSuggestion(-1)
  }

  function moveSuggestion(delta: -1 | 1) {
    setSuggestionsOpen(true)
    setActiveSuggestion((current) => nextSuggestionIndex(current, delta, currentSuggestions().length))
  }

  function activeSuggestionValue() {
    const items = currentSuggestions()

    return items[activeSuggestion()] ?? items[0]
  }

  const keyActions = new Map([
    ["ArrowDown", () => moveSuggestion(1)],
    ["ArrowUp", () => moveSuggestion(-1)],
    [
      "Enter",
      () => {
        const suggestion = activeSuggestionValue()

        if (suggestion) chooseSuggestion(suggestion)

        if (!suggestion) void navigate(input())
      },
    ],
    ["Tab", complete],
  ])

  function handleInputKey(event: KeyboardEvent) {
    const action = keyActions.get(event.key)

    if (!action) return

    if (event.key === "Tab" && event.shiftKey) return
    event.preventDefault()
    action()
  }

  function resolve() {
    const path = policy.result(root(), selected(), rootValid())

    if (!path) return
    props.onSelect(props.multiple ? [path] : path)
    dialog.close()
  }

  onMount(() => {
    const closeSuggestions = (event: PointerEvent) => {
      if (event.target instanceof Node && pathArea?.contains(event.target)) return
      setSuggestionsOpen(false)
      setActiveSuggestion(-1)
    }

    document.addEventListener("pointerdown", closeSuggestions)
    onCleanup(() => document.removeEventListener("pointerdown", closeSuggestions))
    tree = new FileTree({
      paths: [],
      flattenEmptyDirectories: false,
      initialExpansion: "closed",
      stickyFolders: true,
      unsafeCSS: `
        button[data-type="item"] {
          background: transparent !important;
          box-shadow: none !important;
        }
        button[data-type="item"]:hover {
          background: var(--v2-overlay-simple-overlay-hover) !important;
        }
        button[data-type="item"]:focus-visible {
          outline: none !important;
          box-shadow: none !important;
        }
        [data-file-tree-virtualized-scroll] {
          overscroll-behavior: contain;
          scrollbar-width: thin;
        }
      `,
      onExpansionChange(change) {
        if (change.expanded) void load(change.path, navigation)
      },
      onSelectionChange(paths) {
        const path = paths.at(-1)
        setSelected(path ? (policy.selection(root(), path) ?? "") : "")
      },
    })

    if (!container) return
    tree.render({ containerWrapper: container })
    tree.getFileTreeContainer()?.classList.add("directory-picker-tree")
  })

  createEffect(() => {
    const path = start()

    if (!path || !location() || root()) return
    void navigate(path)
  })

  onCleanup(() => tree?.cleanUp())

  return (
    <Dialog size="large" class="directory-picker">
      <DialogHeader>
        <DialogTitle>{props.title ?? language.t("command.project.open")}</DialogTitle>
      </DialogHeader>
      <Divider />
      <DialogBody class="directory-picker-body pt-4!">
        <div class="directory-picker-path" ref={pathArea}>
          <TextInput
            value={input()}
            autofocus
            autocomplete="off"
            spellcheck={false}
            class="!w-full"
            onInput={(event) => {
              setInput(cleanPickerInput(event.currentTarget.value))
              setSelected("")
              setSuggestionsOpen(true)
              setActiveSuggestion(-1)
            }}
            role="combobox"
            aria-autocomplete="list"
            aria-expanded={suggestionsOpen()}
            aria-controls="directory-picker-suggestions"
            aria-activedescendant={
              activeSuggestion() >= 0 ? `directory-picker-suggestion-${activeSuggestion()}` : undefined
            }
            onKeyDown={handleInputKey}
          />
          <div class="directory-picker-actions">
            <Button size="small" variant="ghost" onClick={() => void navigate(home())}>
              ~
            </Button>
            <Button size="small" variant="ghost" onClick={() => void navigate(pickerRoot(root()) || root())}>
              {language.t("dialog.directory.root")}
            </Button>
            <Button size="small" variant="ghost" onClick={() => void navigate(pickerParent(root()))}>
              {language.t("dialog.directory.parent")}
            </Button>
          </div>
          <Show when={suggestionsOpen() && currentSuggestions().length > 0}>
            <div id="directory-picker-suggestions" role="listbox" class="directory-picker-suggestions">
              <For each={currentSuggestions()}>
                {(suggestion, index) => (
                  <button
                    id={`directory-picker-suggestion-${index()}`}
                    data-directory-path={suggestion.absolute}
                    role="option"
                    aria-selected={index() === activeSuggestion()}
                    data-active={index() === activeSuggestion() ? "" : undefined}
                    onPointerMove={() => setActiveSuggestion(index())}
                    onClick={() => chooseSuggestion(suggestion)}
                  >
                    {displayPickerPath(suggestion.absolute, input(), home())}
                    {suggestion.type === "directory" ? "/" : ""}
                  </button>
                )}
              </For>
            </div>
          </Show>
        </div>
        <div
          class="directory-picker-browser"
          ref={container}
          // The modal's scroll lock sees only the shadow host, not the tree's inner scroller.
          on:touchmove={(event) => event.stopPropagation()}
          onWheel={(event) => {
            const scroller = tree
              ?.getFileTreeContainer()
              ?.shadowRoot?.querySelector<HTMLElement>("[data-file-tree-virtualized-scroll]")

            if (!scroller) return

            const next = nextTreeScrollTop(
              scroller.scrollTop,
              event.deltaY,
              scroller.scrollHeight,
              scroller.clientHeight,
            )

            if (next === scroller.scrollTop) return
            event.preventDefault()
            scroller.scrollTop = next
            scroller.dispatchEvent(new Event("scroll"))
          }}
        >
          <Show when={loading()}>
            <div class="directory-picker-state">{language.t("common.loading")}</div>
          </Show>
          <Show when={!loading() && error()}>
            <div class="directory-picker-state">{language.t("dialog.directory.readError")}</div>
          </Show>
        </div>
        <div class="directory-picker-selection">{policy.result(root(), selected(), rootValid())}</div>
      </DialogBody>
      <DialogFooter>
        <Button variant="neutral" onClick={() => dialog.close()}>
          {language.t("common.cancel")}
        </Button>
        <Button variant="contrast" disabled={!policy.result(root(), selected(), rootValid())} onClick={resolve}>
          {action[policy.action]}
        </Button>
      </DialogFooter>
    </Dialog>
  )
}

