import { expect, test } from "bun:test"
import type { SessionMessageInfo } from "@opencode/client/promise"
import { batch, createMemo, createRoot, onCleanup } from "solid-js"
import { createStore } from "solid-js/store"
import { ServerScope, SessionRouteKey, SessionStateKey } from "../src/runtime/server/scope"
import { createTimelineCache } from "../src/session/timeline/cache"

function setup() {
  return createRoot((dispose) => {
    const [state, setState] = createStore({
      id: "ses_a",
      directory: "/repo",
      visible: true,
      messages: {
        ses_a: [{ id: "msg_a", type: "user", text: "First session", time: { created: 1 } }],
        ses_b: [{ id: "msg_b", type: "user", text: "Second session", time: { created: 2 } }],
      } as Record<string, SessionMessageInfo[]>,
    })

    const views = new Map<
      string,
      { active: () => boolean; messages: () => SessionMessageInfo[]; element: HTMLDivElement }
    >()

    const disposed: string[] = []

    const cache = createTimelineCache(
      {
        identity: {
          params: {
            get id() {
              return state.id
            },
            serverKey: "local",
          },
          sessionID: () => state.id,
          workspaceKey: () => SessionStateKey.from(ServerScope.local, SessionRouteKey.fromRoute(state.directory)),
          sessionKey: () =>
            SessionStateKey.from(ServerScope.local, SessionRouteKey.fromRoute(state.directory, state.id)),
        },
        data: {
          info: createMemo(() => ({
            id: state.id,
            projectID: "project",
            cost: 0,
            tokens: { input: 0, output: 0, reasoning: 0, cache: { read: 0, write: 0 } },
            time: { created: 1, updated: 1 },
            location: { directory: state.directory },
          })),
          parent: () => undefined,
          parentID: () => undefined,
          status: () => ({ type: "idle" }),
        },
        history: { messages: () => state.messages[state.id] ?? [] },
      },
      (source, active) => {
        const id = source.identity.sessionID()!
        const element = document.createElement("div")
        createMemo(() =>
          element.setAttribute(
            "data-messages",
            source.history
              .messages()
              .map((message) => message.id)
              .join(","),
          ),
        )
        views.set(id, { active, messages: source.history.messages, element })
        onCleanup(() => disposed.push(id))

        return element
      },
      () => state.visible,
    )

    return { state, setState, cache, views, disposed, dispose }
  })
}

test("reuses a session view and refreshes its own history when selected again", () => {
  const input = setup()

  try {
    const first = input.cache()
    input.setState("id", "ses_b")
    const second = input.cache()
    expect(second).not.toBe(first)
    expect(input.views.get("ses_a")!.active()).toBe(false)
    expect(input.views.get("ses_a")!.element.dataset.messages).toBe("msg_a")
    expect(input.views.get("ses_b")!.element.dataset.messages).toBe("msg_b")

    input.setState("messages", "ses_a", [
      { id: "msg_c", type: "user", text: "Updated while inactive", time: { created: 3 } },
    ])
    input.setState("id", "ses_a")
    expect(input.cache()).toBe(first)
    expect(input.views.get("ses_a")!.active()).toBe(true)
    expect(input.views.get("ses_a")!.element.dataset.messages).toBe("msg_c")
    expect(input.views.get("ses_b")!.element.dataset.messages).toBe("msg_b")
    expect(input.disposed).toEqual([])
  } finally {
    input.dispose()
  }

  expect(input.disposed.sort()).toEqual(["ses_a", "ses_b"])
})

test("suspends a detached mobile view and reuses it when the conversation returns", () => {
  const input = setup()

  try {
    const first = input.cache()
    input.setState("visible", false)
    expect(input.views.get("ses_a")!.active()).toBe(false)
    input.setState("visible", true)
    expect(input.cache()).toBe(first)
    expect(input.views.get("ses_a")!.active()).toBe(true)
  } finally {
    input.dispose()
  }
})

test("disposes views whose Location-scoped providers no longer match", () => {
  const input = setup()

  try {
    const first = input.cache()
    input.setState("directory", "/other")
    expect(input.cache()).not.toBe(first)
    expect(input.disposed).toEqual(["ses_a"])
    input.setState("directory", "/repo")
    expect(input.cache()).not.toBe(first)
    expect(input.disposed).toEqual(["ses_a", "ses_a"])
  } finally {
    input.dispose()
  }

  expect(input.disposed).toHaveLength(3)
})

test("disposes views on workspace changes while the destination is not rendered", () => {
  const input = setup()

  try {
    const first = input.cache()
    input.setState("visible", false)
    input.setState("directory", "/other")
    expect(input.disposed).toEqual(["ses_a"])
    input.setState("directory", "/repo")
    input.setState("visible", true)
    expect(input.cache()).not.toBe(first)
  } finally {
    input.dispose()
  }

  expect(input.disposed).toEqual(["ses_a", "ses_a"])
})

for (const order of ["session-first", "workspace-first"] as const) {
  test(`keeps views live across five workspaces when updates are ${order}`, () => {
    const input = setup()
    const render = createRoot((dispose) => ({ selected: createMemo(input.cache), dispose }))
    const visited = ["ses_a"]

    try {
      ;["ses_b", "ses_c", "ses_d", "ses_e", "ses_a", "ses_c", "ses_b", "ses_e", "ses_d", "ses_a"].forEach(
        (id, index) => {
          batch(() => {
            if (order === "workspace-first") input.setState("directory", `/repo/${id}`)
            input.setState("id", id)

            if (order === "session-first") input.setState("directory", `/repo/${id}`)
          })
          expect(input.disposed).toEqual(visited)
          input.setState("messages", id, [
            { id: `msg_live_${index}`, type: "user", text: "Live update", time: { created: index + 3 } },
          ])
          expect((render.selected() as HTMLDivElement).dataset.messages).toBe(`msg_live_${index}`)
          expect(input.views.get(id)!.active()).toBe(true)
          visited.push(id)
        },
      )
    } finally {
      render.dispose()
      input.dispose()
    }
  })
}

test("evicts the least recently selected view and disposes all retained owners", () => {
  const input = setup()

  try {
    const first = input.cache()
    Array.from({ length: 15 }, (_, index) => `ses_${index}`).forEach((id) => {
      input.setState("id", id)
      input.cache()
    })
    input.setState("id", "ses_a")
    expect(input.cache()).toBe(first)
    input.setState("id", "ses_last")
    input.cache()
    expect(input.disposed).toEqual(["ses_0"])
    input.setState("id", "ses_0")
    input.cache()
    expect(input.disposed).toEqual(["ses_0", "ses_1"])
  } finally {
    input.dispose()
  }

  expect(input.disposed).toHaveLength(18)
})

import { describe, expect, test } from "bun:test"
import type { SessionMessageAssistant, SessionMessageInfo, SessionStatus } from "@opencode/client/promise"
import { createRoot } from "solid-js"
import { createStore, produce } from "solid-js/store"
import {
  createReactiveTimelineProjection,
  reuseTimelineRows,
  Timeline,
  TimelineRow,
  type ReasoningMode,
} from "@opencode/session-ui/timeline/projection"
import { createTimelineProjection } from "../src/session/timeline/projection"

const assistant = (id: string, content: SessionMessageAssistant["content"]): SessionMessageAssistant => ({
  id,
  type: "assistant",
  agent: "build",
  model: { id: "model", providerID: "provider" },
  time: { created: 2 },
  content,
})

for (const factory of [createTimelineProjection, createReactiveTimelineProjection]) {
  describe(factory.name, () => {
    test("only crosses the renderable boundary on text deltas, while retaining live content", () => {
      createRoot((dispose) => {
        let visits = 0

        const [state, setState] = createStore<{ messages: SessionMessageInfo[] }>({
          messages: [
            {
              id: "old",
              type: "user",
              text: "history",
              get time() {
                visits++

                return { created: 0 }
              },
            },
            assistant("old-answer", [{ type: "text", text: "History remains visible." }]),
            { id: "user", type: "user", text: "question", time: { created: 1 } },
            assistant("answer", [{ type: "text", text: "" }]),
          ],
        })

        const projection = factory({
          sessionMessages: () => state.messages,
          status: () => ({ type: "busy" }),
          reasoningMode: () => "compact",
          shellToolDefaultOpen: () => false,
          editToolDefaultOpen: () => false,
          pendingInputIDs: () => new Set(),
        })

        const update = (text: string) =>
          setState(
            "messages",
            3,
            produce((message) => {
              if (message.type === "assistant" && message.content[0].type === "text") message.content[0].text = text
            }),
          )

        const empty = projection.rows()
        visits = 0
        update(" \n\t")
        expect(projection.rows()).toBe(empty)
        expect(visits).toBe(0)
        update("The first visible answer.")
        const visible = projection.rows()
        expect(visible.length).toBe(empty.length + 1)
        expect(visits).toBeGreaterThan(0)
        visits = 0
        update("The first visible answer. More streamed words.")
        expect(projection.rows()).toBe(visible)
        expect(visits).toBe(0)
        expect(Timeline.resolveContent(projection.messageByID().get("answer"), "answer:text:0")).toMatchObject({
          text: "The first visible answer. More streamed words.",
        })
        update("")
        expect(projection.rows()).toEqual(empty)
        expect(visits).toBeGreaterThan(0)
        dispose()
      })
    })

    test("matches full construction through grouping, notices, history and preference transitions", () => {
      createRoot((dispose) => {
        const [state, setState] = createStore<{
          messages: SessionMessageInfo[]
          status: SessionStatus
          reasoning: ReasoningMode
          shell: boolean
          edit: boolean
          pending: Set<string>
        }>({
          messages: [
            assistant("answer", [
              { type: "reasoning", text: "Inspect the source", time: { created: 1 } },
              {
                type: "tool",
                id: "read",
                name: "read",
                state: { status: "completed", input: {}, content: [{ type: "text", text: "read" }], metadata: {} },
                time: { created: 1 },
              },
              { type: "text", text: "" },
              {
                type: "tool",
                id: "shell",
                name: "shell",
                state: { status: "running", input: {}, metadata: {} },
                time: { created: 1 },
              },
              {
                type: "tool",
                id: "question",
                name: "question",
                state: { status: "running", input: {}, metadata: {} },
                time: { created: 1 },
              },
            ]),
          ],
          status: { type: "busy" },
          reasoning: "compact",
          shell: false,
          edit: false,
          pending: new Set<string>(),
        })

        const projection = factory({
          sessionMessages: () => state.messages,
          status: () => state.status,
          reasoningMode: () => state.reasoning,
          shellToolDefaultOpen: () => state.shell,
          editToolDefaultOpen: () => state.edit,
          pendingInputIDs: () => state.pending,
        })

        let previous: TimelineRow.TimelineRow[] | undefined

        const verify = () => {
          const full = Timeline.constructSessionMessageRows(
            state.messages,
            state.reasoning !== "hidden",
            state.status,
            state.pending,
            state.shell,
            state.edit,
          )

          previous = reuseTimelineRows(previous, full.rows)
          expect(projection.rows()).toEqual(previous)
          expect(projection.activeMessageID()).toBe(full.activeMessageID)
          expect([...projection.rowByKey().keys()]).toEqual(previous.map(TimelineRow.key))
          expect([...projection.messageByID().keys()]).toEqual(state.messages.map((message) => message.id))
          previous.forEach((row, index) => {
            expect(projection.messageRowIndex().get(row.userMessageID)).toBe(
              previous!.findIndex((item) => item.userMessageID === row.userMessageID),
            )
            expect(projection.messageLastRowIndex().get(row.userMessageID)).toBe(
              previous!.findLastIndex((item) => item.userMessageID === row.userMessageID),
            )
            expect(projection.rowByKey().get(TimelineRow.key(row))).toBe(projection.rows()[index])
          })
        }

        const change = (update: (message: SessionMessageAssistant) => void) => {
          setState(
            "messages",
            (message) => message.id === "answer",
            produce((message) => {
              if (message.type === "assistant") update(message)
            }),
          )
          verify()
        }

        verify()
        change((message) => {
          if (message.content[2].type === "text") message.content[2].text = "Split the context group"
        })
        change((message) => {
          if (message.content[2].type === "text") message.content[2].text = " \n"
        })
        change((message) => {
          if (message.content[0].type === "reasoning") message.content[0].text += " and its callers"
        })
        setState("reasoning", "hidden")
        verify()
        setState("reasoning", "full")
        verify()
        change((message) => {
          if (message.content[1].type === "tool" && message.content[1].state.status === "completed")
            message.content[1].state.metadata = { loaded: ["src/example.ts"] }
        })
        change((message) => {
          if (message.content[3].type === "tool")
            message.content[3].state = {
              status: "completed",
              input: {},
              metadata: {},
              content: [{ type: "text", text: "ok" }],
            }
        })
        setState("shell", true)
        verify()
        change((message) => {
          if (message.content[4].type === "tool")
            message.content[4].state = {
              status: "completed",
              input: {},
              metadata: {},
              content: [{ type: "text", text: "answered" }],
            }
        })
        change((message) => {
          message.content.push({
            type: "tool",
            id: "edit",
            name: "edit",
            state: {
              status: "completed",
              input: {},
              metadata: { files: [{ status: "deleted" }] },
              content: [{ type: "text", text: "edited" }],
            },
            time: { created: 1 },
          })
        })
        setState("edit", true)
        verify()
        change((message) => {
          const tool = message.content.at(-1)

          if (tool?.type === "tool" && tool.state.status === "completed")
            tool.state.metadata = { files: [{ status: "modified" }] }
        })
        change((message) => {
          message.content.push({ type: "reasoning", text: "Working", time: { created: 3 } })
        })
        expect(projection.rows().at(-1)?._tag).toBe("Thinking")
        change((message) => {
          const part = message.content.at(-1)

          if (part?.type === "reasoning") part.time = { created: 3, completed: 4 }
        })
        change((message) => {
          message.retry = { attempt: 1, at: 3, error: { type: "Retry", message: "retry" } }
        })
        change((message) => {
          message.retry = undefined
          message.error = { type: "Interrupted", message: "stopped" }
        })
        change((message) => {
          message.error = { type: "Error", message: "failed" }
        })
        change((message) => {
          message.error = undefined
          message.time.completed = 5
        })
        setState("status", { type: "idle" })
        verify()
        setState(
          "messages",
          produce((messages) =>
            messages.unshift({ id: "user", type: "user", text: "Earlier page", time: { created: 0 } }),
          ),
        )
        verify()
        expect(projection.assistantMessagesByParent().get("user")?.[0].id).toBe("answer")
        expect(projection.userContextByID().get("user")?.agent).toBe("build")
        setState(
          "messages",
          produce((messages) =>
            messages.push(
              { id: "notice", type: "synthetic", text: "hidden", time: { created: 6 } },
              assistant("later", [{ type: "text", text: "Later work" }]),
            ),
          ),
        )
        verify()
        setState("messages", (message) => message.id === "notice", { description: "Visible notice" })
        verify()
        setState(
          "messages",
          produce((messages) => messages.push({ id: "pending", type: "user", text: "Steer", time: { created: 8 } })),
        )
        setState("pending", new Set(["pending"]))
        verify()
        expect(projection.activeMessageID()).toBe("user")
        setState("pending", new Set())
        verify()
        expect(projection.activeMessageID()).toBe("pending")
        const all = [...state.messages]
        setState("messages", (messages) => messages.slice(0, 2))
        verify()
        setState("messages", all)
        verify()
        change((message) => {
          message.content = [{ type: "text", text: "Replacement" }]
        })
        setState("messages", [])
        verify()
        setState("messages", [assistant("new-session", [{ type: "text", text: "New session" }])])
        verify()
        dispose()
      })
    })
  })
}

import { beforeEach, describe, expect, test } from "bun:test"
import { createSignal, type JSX } from "solid-js"
import { showToast, toaster } from "@opencode/ui/toast"

describe("showToast", () => {
  // The toast registry is module state, so each test starts from an empty stack.
  beforeEach(() => {
    toaster.dismiss()
  })

  test("coalesces exact active content", () => {
    const first = showToast({ title: "Repeated error", description: "Try again" })
    const second = showToast({ title: "Repeated error", description: "Try again" })
    const different = showToast({ title: "Repeated error", description: "A different error" })

    expect(second).toBe(first)
    expect(different).not.toBe(first)

    toaster.dismiss(first)
    toaster.dismiss(different)
  })

  test("allows dismissed content to appear again", () => {
    const first = showToast("Dismiss and retry")
    toaster.dismiss(first)

    const second = showToast("Dismiss and retry")
    expect(second).not.toBe(first)

    toaster.dismiss(second)
  })

  test("recreates matching content when it is not the topmost toast", () => {
    const first = showToast("First toast")
    const topmost = showToast("Topmost toast")
    const repeated = showToast("First toast")

    expect(repeated).not.toBe(first)

    toaster.dismiss(topmost)
    toaster.dismiss(repeated)
  })

  test("creates no reactive computations at call time", () => {
    const [tick, setTick] = createSignal(0)
    let reads = 0

    const icon = (() => {
      reads++
      tick()

      return undefined
    }) as unknown as JSX.Element

    const id = showToast({ description: "test", icon })

    // Resolving the icon at call time creates an ownerless computation that is
    // never disposed and tracks its dependencies forever; it must only resolve
    // once the toast component renders.
    expect(reads).toBe(0)
    setTick(1)
    expect(reads).toBe(0)

    toaster.dismiss(id)
  })
})

import { afterEach, describe, expect, test } from "bun:test"
import type { FormCreated, FormReplyInput, OpenCodeEvent } from "@opencode/client/promise"
import { createEffect, createRoot } from "solid-js"
import { createStore } from "solid-js/store"
import { createWebSearchRequest } from "@/session/requests/websearch"

const consent: FormCreated["data"]["form"] = {
  id: "frm_consent",
  sessionID: "ses_child",
  title: "Web Search",
  metadata: { kind: "websearch.provider" },
  fields: [{ key: "choice", type: "string", required: true, custom: false }],
}

const options = [
  { value: "exa", label: "Exa" },
  { value: "parallel", label: "Parallel" },
]

const provider: FormCreated["data"]["form"] = {
  ...consent,
  id: "frm_provider",
  fields: [{ key: "provider", type: "string", options, required: true, custom: false }],
}

const cleanups: VoidFunction[] = []

afterEach(() => cleanups.splice(0).forEach((dispose) => dispose()))

function ready(condition: () => boolean) {
  return new Promise<void>((resolve) => {
    createRoot((dispose) => {
      cleanups.push(dispose)
      createEffect(() => {
        if (!condition()) return
        dispose()
        resolve()
      })
    })
  })
}

function fixture(form: FormCreated["data"]["form"] | null = consent) {
  return createRoot((dispose) => {
    cleanups.push(dispose)
    const listeners = new Set<(event: OpenCodeEvent) => void>()
    const replies: FormReplyInput[] = []
    const loads: string[] = []

    const [state, setState] = createStore({
      request: form ?? undefined,
      owner: "ses_root",
      connected: true,
      loadFails: false,
      replyFails: false,
    })

    const model = createWebSearchRequest({
      owner: () => state.owner,
      connected: () => state.connected,
      request: () => state.request,
      providers: async (sessionID) => {
        loads.push(sessionID)

        if (state.loadFails) throw new Error("offline")

        return options
      },
      reply: async (input) => {
        replies.push(input)

        if (state.replyFails) throw new Error("offline")
        setState("request", undefined)
      },
      events: {
        listen(listener) {
          listeners.add(listener)

          return () => {
            listeners.delete(listener)
          }
        },
      },
    })

    return {
      model,
      state,
      setState,
      replies,
      loads,
      dispose,
      listeners,
      create(form = provider) {
        setState("request", form)
        listeners.forEach((listener) =>
          listener({
            id: "evt_create",
            created: 0,
            type: "form.created",
            data: { form },
          }),
        )
      },
      cancel(id: string) {
        setState("request", undefined)
        listeners.forEach((listener) =>
          listener({
            id: "evt_cancel",
            created: 0,
            type: "form.cancelled",
            data: { id, sessionID: consent.sessionID },
          }),
        )
      },
    }
  })
}

describe("web search request state", () => {
  test("loads providers for the form owner, not the viewed parent, and waits for consent", async () => {
    const input = fixture()
    await ready(() => !input.model.loading())
    expect(input.loads).toEqual(["ses_child"])
    expect(input.model.selected()).toBe("random")
    input.model.select("exa")
    expect(input.replies).toEqual([])
    await input.model.submit(false)
    expect(input.replies[0]?.answer).toEqual({ choice: "disable" })
    expect(input.model.request()).toBeUndefined()
    expect(input.model.sending()).toBe(false)
  })

  test("does not load providers when there is no consent request", () => {
    const input = fixture(null)
    expect(input.model.request()).toBeUndefined()
    expect(input.loads).toEqual([])
  })

  test("holds the card across both forms and prevents duplicate submissions", async () => {
    const input = fixture()
    await ready(() => !input.model.loading())
    input.model.select("parallel")
    const pending = input.model.submit("parallel")
    await input.model.submit("parallel")
    expect(input.state.request).toBeUndefined()
    expect(input.model.request()?.id).toBe(consent.id)
    expect(input.model.sending()).toBe(true)
    input.create()
    await pending
    expect(input.replies.map((reply) => reply.answer)).toEqual([{ choice: "choose" }, { provider: "parallel" }])
    expect(input.model.request()).toBeUndefined()
    expect(input.model.sending()).toBe(false)
    expect(input.listeners.size).toBe(0)
  })

  test("direct provider requests need confirmation and do not load a different provider list", async () => {
    const input = fixture(provider)
    await ready(() => !input.model.loading())
    expect(input.loads).toEqual([])
    expect(input.model.specific()).toBe(true)
    expect(input.model.options()).toEqual(options)
    expect(input.replies).toEqual([])
    await input.model.submit("exa")
    expect(input.replies.map((reply) => reply.answer)).toEqual([{ provider: "exa" }])
  })

  test("keeps the selected provider after failure and retries only the provider form", async () => {
    const input = fixture()
    await ready(() => !input.model.loading())
    input.model.select("parallel")
    const pending = input.model.submit("parallel")
    input.setState("replyFails", true)
    input.create()
    await pending
    expect(input.model.failed()).toBe(true)
    expect(input.model.sending()).toBe(false)
    expect(input.model.request()?.id).toBe(provider.id)
    expect(input.model.selected()).toBe("parallel")
    input.setState("replyFails", false)
    await input.model.submit("parallel")
    expect(input.replies.map((reply) => reply.answer)).toEqual([
      { choice: "choose" },
      { provider: "parallel" },
      { provider: "parallel" },
    ])
    expect(input.model.request()).toBeUndefined()
  })

  test("can retry loading providers without submitting consent", async () => {
    const input = fixture()
    await ready(() => !input.model.loading())
    input.setState("loadFails", true)
    input.model.retry()
    await ready(() => input.model.loadFailed())
    expect(input.model.options()).toEqual([])
    input.setState("loadFails", false)
    input.model.retry()
    await ready(() => !input.model.loading())
    expect(input.model.options()).toEqual(options)
    expect(input.model.loadFailed()).toBe(false)
    expect(input.replies).toEqual([])
  })

  test.each(["navigate", "disconnect", "dispose", "cancel"])("stops automatic replies on %s", async (action) => {
    const input = fixture()
    await ready(() => !input.model.loading())
    const pending = input.model.submit("exa")

    if (action === "navigate") input.setState("owner", "ses_other")

    if (action === "disconnect") input.setState("connected", false)

    if (action === "dispose") input.dispose()

    if (action === "cancel") input.cancel(consent.id)
    await pending
    expect(input.model.sending()).toBe(false)
    expect(input.listeners.size).toBe(0)
    input.create()
    expect(input.replies.map((reply) => reply.answer)).toEqual([{ choice: "choose" }])
  })
})

import { expect, test } from "bun:test"
import { fetch } from "bun"
import { build, createServer } from "vite"
import { icons } from "./vite.icons"
import manifest from "./manifest.json" with { type: "json" }

test.each(["dev", "beta", "prod", "local"])("bundles %s app icons", async (channel) => {
  const result = await build({
    root: import.meta.dirname,
    configFile: false,
    logLevel: "silent",
    plugins: [
      icons(channel),
      {
        name: "icons-only-fixture",
        transformIndexHtml: {
          order: "pre",
          handler: (html) => html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/g, ""),
        },
      },
    ],
    build: { write: false, copyPublicDir: false },
  })

  if (!("output" in result)) throw new Error("Expected a single build output")

  await check(channel === "local" ? "dev" : channel, async (path) => {
    const file = result.output.find((file) => `/${file.fileName}` === path)

    if (file?.type !== "asset") throw new Error(`Missing asset: ${path}`)

    return new Uint8Array(Buffer.from(file.source))
  })
})

test.each(["dev", "beta", "prod"])("serves %s app icons", async (channel) => {
  const server = await createServer({
    root: import.meta.dirname,
    configFile: false,
    logLevel: "silent",
    plugins: [icons(channel)],
    optimizeDeps: { noDiscovery: true, include: [] },
    server: { host: "127.0.0.1", port: 0, hmr: false, preTransformRequests: false, watch: null },
  })

  try {
    await server.listen()
    const url = server.resolvedUrls?.local[0]

    if (!url) throw new Error("Expected a local URL")

    await check(channel, async (path) => {
      const response = await fetch(new URL(path, url))
      expect(response.status).toBe(200)

      if (path.endsWith(".webmanifest")) expect(response.headers.get("content-type")).toBe("application/manifest+json")

      if (path.endsWith(".png")) expect(response.headers.get("content-type")).toBe("image/png")

      return new Uint8Array(await response.arrayBuffer())
    })
  } finally {
    await server.close()
  }
})

async function check(channel: string, read: (path: string) => Promise<Uint8Array>) {
  const html = new TextDecoder().decode(await read("/index.html"))
  const actual: typeof manifest = JSON.parse(new TextDecoder().decode(await read("/site.webmanifest")))
  expect(actual.icons.some((icon) => icon.purpose === "maskable")).toBe(true)
  expect(actual).toEqual({
    ...manifest,
    icons: manifest.icons.map((icon) => ({ ...icon, src: `/icons/${channel}${icon.src}` })),
  })
  expect(html).toContain(`href="/icons/${channel}/favicon.ico"`)
  expect(html).toContain(`href="/icons/${channel}/apple-touch-icon.png"`)
  expect(html).toContain(`href="/site.webmanifest"`)
  expect(html).not.toContain("%OPENCODE_")

  await Promise.all(
    Object.entries({
      "favicon.ico": "icon.ico",
      "apple-touch-icon.png": "ios/AppIcon-60x60@3x.png",
      "web-app-manifest-192x192.png": "android/mipmap-xxxhdpi/ic_launcher.png",
      "web-app-manifest-512x512.png": "icon.png",
    }).map(async ([name, source]) => {
      const bytes = await read(`/icons/${channel}/${name}`)
      expect(bytes).toEqual(await Bun.file(new URL(`../desktop/icons/${channel}/${source}`, import.meta.url)).bytes())

      if (!name.endsWith(".png")) return
      const size = name === "apple-touch-icon.png" ? 180 : Number(name.match(/(192|512)/)?.[0])
      expect(new DataView(bytes.buffer, bytes.byteOffset).getUint32(16)).toBe(size)
      expect(new DataView(bytes.buffer, bytes.byteOffset).getUint32(20)).toBe(size)
    }),
  )
}

import { readFileSync } from "node:fs"
import type { Plugin } from "vite"
import manifest from "./manifest.json" with { type: "json" }

export function icons(channel: string): Plugin {
  const selected = channel === "beta" || channel === "prod" ? channel : "dev"
  const prefix = `icons/${selected}`

  const files = [
    ...Object.entries({
      "favicon.ico": "icon.ico",
      "apple-touch-icon.png": "ios/AppIcon-60x60@3x.png",
      "web-app-manifest-192x192.png": "android/mipmap-xxxhdpi/ic_launcher.png",
      "web-app-manifest-512x512.png": "icon.png",
    }).map(([name, source]) => ({
      fileName: `${prefix}/${name}`,
      source: readFileSync(new URL(`../desktop/icons/${selected}/${source}`, import.meta.url)),
      type: name.endsWith(".ico") ? "image/x-icon" : "image/png",
    })),
    {
      fileName: "site.webmanifest",
      source: JSON.stringify({
        ...manifest,
        icons: manifest.icons.map((icon) => ({ ...icon, src: `/${prefix}${icon.src}` })),
      }),
      type: "application/manifest+json",
    },
  ]

  return {
    name: "opencode-app:icons",
    generateBundle() {
      files.forEach((file) => this.emitFile({ type: "asset", fileName: file.fileName, source: file.source }))
    },
    configureServer(server) {
      server.middlewares.use((request, response, next) => {
        const file = files.find((file) => `/${file.fileName}` === request.url?.split("?")[0])

        if (!file) return next()
        response.setHeader("Content-Type", file.type)
        response.end(file.source)
      })
    },
    transformIndexHtml: {
      order: "pre",
      handler(html) {
        return html
          .replace("%OPENCODE_FAVICON%", `/${prefix}/favicon.ico`)
          .replace("%OPENCODE_APPLE_TOUCH_ICON%", `/${prefix}/apple-touch-icon.png`)
      },
    },
  }
}

import { createHash } from "node:crypto"
import { readFile } from "node:fs/promises"
import { resolve } from "node:path"
import { VitePWA } from "vite-plugin-pwa"

// The Office previews' engines and fonts (about 52 MB) load only when an Office file opens, so they stay out of the
// precache. The app's own fonts have no hyphenated name, such as `assets/Inter.ttf`.
const officeAsset =
  /(?:^|\/)(?:(?:docx_\w+|ooxml_opc|pptx_wasm|xlsx_wasm)_bg-[\w-]+\.wasm|residentEngineWorker-[\w-]+\.js|(?:Carlito|Caladea|LiberationSans|LiberationSerif|LiberationMono|NotoSansArabic|NotoNaskhArabic|NotoSansHebrew|Gelasio|ComicRelief|Inter|Roboto|SourceSans3|DMSans|DMSerifDisplay|OpenSans|Montserrat|Poppins|Oswald|Heebo)-[\w-]+\.ttf)$/

/** Whether a built file loads on demand instead of being precached. */
export function onDemandAsset(path: string) {
  return officeAsset.test(path)
}

export function serviceWorker(directory: string) {
  return VitePWA({
    strategies: "generateSW",
    registerType: "prompt",
    injectRegister: false,
    manifest: false,
    workbox: {
      // Workbox runs after Sentry's upload and cleanup, so do not publish an unuploaded map.
      sourcemap: false,
      globDirectory: directory,
      clientsClaim: false,
      // Keep each open tab on its complete build until all old clients close.
      skipWaiting: false,
      inlineWorkboxRuntime: true,
      navigateFallback: "/index.html",
      // Pairing links must reach the server so it can set the session cookie.
      navigateFallbackDenylist: [/^\/(?:api|auth)(?:\/|$)/, /^\/(?:_assets|assets)(?:\/|$)/],
      // Include lazy chunks and non-JS dependencies, not just the startup bundle.
      globPatterns: ["**/*"],
      globIgnores: ["**/*.map", "_headers", "_redirects"],
      maximumFileSizeToCacheInBytes: Number.MAX_SAFE_INTEGER,
      manifestTransforms: [
        async (entries) => ({
          manifest: await Promise.all(
            entries
              .filter((entry) => !onDemandAsset(entry.url))
              .map(async (entry) => ({
              ...entry,
              // A revision labels a cache entry; integrity rejects mixed deployments
              // and HTML fallback responses instead of installing a broken build.
              integrity: `sha256-${createHash("sha256")
                .update(await readFile(resolve(directory, entry.url)))
                .digest("base64")}`,
            })),
          ),
          warnings: [],
        }),
      ],
    },
  })
}

