}
const processes: Array<ReturnType<typeof Bun.spawn>> = []
const errors: Array<Promise<string>> = []
let failure: unknown
try {
  await fs.mkdir(path.join(root, ".opencode", "plugins"), { recursive: true })
  spawnService()
  spawnService()
  const registration = await waitForRegistration()
  const info = await Schema.decodeUnknownPromise(Service.Info)(await Bun.file(registration).json())
  if (info.id === undefined || info.password === undefined) throw new Error("Registration is missing service identity")
  const credential = btoa(`opencode:${info.password}`)
  const headers = { authorization: "Basic " + credential }
  const token = encodeURIComponent(credential)
  const serverInfo = await waitForReady(info.url, headers)
  if (serverInfo.pid !== info.pid) throw new Error("Server info does not match registration")
  const tokenInfo = await fetch(new URL(`/api/info?auth_token=${token}`, info.url), {
    signal: AbortSignal.timeout(5_000),
  })
  if (tokenInfo.status !== 200) throw new Error("Compiled service rejected query authentication")
  const tokenOpenApi = await fetch(new URL(`/openapi.json?auth_token=${token}`, info.url), {
    signal: AbortSignal.timeout(5_000),
  })
  if (tokenOpenApi.status !== 200) throw new Error("Compiled application rejected query authentication")
  await verifyWebUi(info.url)
  if ((await pluginIDs(info.url, headers)).includes("smoke")) throw new Error("Smoke plugin existed before creation")
  const plugin = path.join(root, ".opencode", "plugins", "smoke.ts")
  await fs.writeFile(plugin, pluginSource())
  await waitForPlugin(info.url, headers, plugin)

  const unauthorizedInfo = await fetch(new URL("/api/info", info.url), {
    signal: AbortSignal.timeout(5_000),
  })
  if (unauthorizedInfo.status !== 401) throw new Error("Compiled service exposed info without authentication")
  const unauthorizedOpenApi = await fetch(new URL("/openapi.json", info.url), {
    signal: AbortSignal.timeout(5_000),
  })
  if (unauthorizedOpenApi.status !== 401)
    throw new Error("Compiled service exposed application routes without authentication")
  const stopRoute = await fetch(new URL("/api/service/stop", info.url), {
    method: "POST",
    headers: { ...headers, "content-type": "application/json" },
    body: JSON.stringify({ instanceID: info.id }),
    signal: AbortSignal.timeout(5_000),
  })
  if (stopRoute.status !== 404) throw new Error("Compiled service exposed the removed HTTP stop route")

  const winner = processes.find((process) => process.pid === info.pid)
  const loser = processes.find((process) => process.pid !== info.pid)
  if (!winner || !loser) throw new Error("Compiled contenders did not elect one registered owner")
  if (!(await exitsWithin(loser, 10_000))) throw new Error("Losing compiled contender did not exit")

  await Effect.runPromise(Service.stop({ file: registration }).pipe(Effect.provide(NodeFileSystem.layer)))
  if (!(await exitsWithin(winner, 10_000))) throw new Error("Compiled service did not stop")
  for (let attempt = 0; attempt < 200 && (await Bun.file(registration).exists()); attempt++) await Bun.sleep(25)
  if (await Bun.file(registration).exists()) throw new Error("Compiled service registration was not removed")
} catch (cause) {
  failure = cause
} finally {
  processes.forEach((process) => process.kill())
  await Promise.all(processes.map((process) => process.exited))
  if (failure)
    errors.push(fs.readFile(path.join(root, "data", "opencode", "log", "opencode.log"), "utf8").catch(() => ""))
}

const output = await Promise.all(errors)
// Windows can retain directory handles briefly after the service processes exit.
await fs.rm(root, { recursive: true, force: true, maxRetries: 10, retryDelay: 100 }).catch((cause: unknown) => {
  console.error("Failed to remove service smoke-test directory", cause)
  failure ??= cause
})
if (failure)
  throw new Error(output.filter(Boolean).join("\n") || "Compiled service lifecycle smoke test failed", {
    cause: failure,
  })

function spawnService() {
  const process = Bun.spawn([binary, "serve", "--service"], { env, stdout: "ignore", stderr: "pipe" })
  processes.push(process)
  errors.push(new Response(process.stderr).text())
  return process
}

async function waitForRegistration() {
  const directory = path.join(root, "state", "opencode")
  for (let attempt = 0; attempt < 400; attempt++) {
    const files = await fs.readdir(directory).catch(() => [])
    const file = files.find(
      (file) => file === "service.json" || (file.startsWith("service-") && file.endsWith(".json")),
    )
    if (file) return path.join(directory, file)
    await Bun.sleep(25)
  }
  throw new Error("Compiled service did not publish registration")
}

// Reads the web UI from the binary's embedded archive: the shell, and the entry script it names.
async function verifyWebUi(url: string) {
  const shell = await fetch(url, { signal: AbortSignal.timeout(5_000) })
  const html = await shell.text()
  if (shell.status !== 200 || !html.includes("<html")) throw new Error("Compiled service did not serve the web UI")
  const script = html.match(/<script[^>]*\bsrc="(\/_assets\/[^"]+\.js)"/)?.[1]
  if (!script) throw new Error("Compiled web UI names no entry script")
  const entry = await fetch(new URL(script, url), { signal: AbortSignal.timeout(5_000) })
  if (entry.status !== 200 || (await entry.text()).length === 0)
    throw new Error(`Compiled service did not serve ${script}`)
}

async function waitForReady(url: string, headers: HeadersInit) {
  const deadline = Date.now() + 20_000
  while (Date.now() < deadline) {
    const response = await fetch(new URL("/api/info", url), {
      headers,
      signal: AbortSignal.timeout(1_000),
    }).catch(() => undefined)
    if (response?.ok) return Schema.decodeUnknownPromise(ServerInfo)(await response.json())
    await Bun.sleep(25)
  }
  throw new Error("Compiled service did not become ready")
}

function exitsWithin(process: Bun.Subprocess, milliseconds: number) {
  return new Promise<boolean>((resolve) => {
    const timeout = setTimeout(() => resolve(false), milliseconds)
    process.exited.then(() => {
      clearTimeout(timeout)
      resolve(true)
    })
  })
}

function pluginSource() {
  return 'export default { id: "smoke", setup: async () => {} }\n'
}

async function pluginIDs(url: string, headers: HeadersInit) {
  const endpoint = new URL("/api/plugin", url)
  endpoint.searchParams.set("location[directory]", root)
  const response = await fetch(endpoint, { headers, signal: AbortSignal.timeout(5_000) })
  const body: unknown = await response.json()
  if (typeof body !== "object" || body === null || !("data" in body) || !Array.isArray(body.data)) {
    throw new Error("Compiled service returned an invalid plugin list")
  }
  return body.data.flatMap((plugin) =>
    typeof plugin === "object" && plugin !== null && "id" in plugin && typeof plugin.id === "string" ? [plugin.id] : [],
  )
}

async function waitForPlugin(url: string, headers: HeadersInit, plugin: string) {
  const deadline = Date.now() + 10_000
  let attempt = 0
  while (Date.now() < deadline) {
    if ((await pluginIDs(url, headers)).includes("smoke")) return
    await Bun.sleep(25)
    // Native watchers may coalesce a single creation edge. Keep changing valid source so
    // the smoke proves that a later native event is delivered.
    if (++attempt % 10 === 0) await fs.writeFile(plugin, `${pluginSource()}// watcher retry ${attempt}\n`)
  }
  throw new Error("Compiled service did not discover the created plugin")
}

import { stat } from "node:fs/promises"
import path from "node:path"
import { collectFiles } from "./files"

const forbidden = [
  "@napi-rs/canvas",
  "@fontsource/commit-mono",
  "@fontsource/noto-sans",
  "SimulationPng",
  "frontend/png",
  "Failed to register screenshot font",
  "commit-mono-latin-400-normal",
  "noto-sans-symbols-symbols-400-normal",
  "noto-sans-math-math-400-normal",
  "CommitMono-400-Regular.otf",
  "NotoSansSymbols.ttf",
  "src/frontend/png.ts",
  "skia.darwin-",
  "skia.linux-",
  "skia.win32-",
]
const overlap = Math.max(...forbidden.map((value) => value.length)) - 1

export async function verifyArtifact(target: string) {
  const files = await artifactFiles(target)
  if (files.length === 0) throw new Error(`Artifact contains no published files: ${target}`)
  for (const file of files) await scan(file)
}

export function verifySimulationGraph(inputs: Iterable<string>) {
  const modules = Array.from(inputs, (input) => input.replaceAll("\\", "/"))
  const required = [
    "/packages/simulation/src/frontend/simulation.ts",
    "/packages/simulation/src/frontend/server.ts",
    "/packages/simulation/src/control-server.ts",
  ]
  const missing = required.filter((input) => !modules.some((module) => module.endsWith(input)))
  if (missing.length > 0) throw new Error(`Build graph is missing simulation bridge inputs: ${missing.join(", ")}`)
  const leaked = modules.find((module) => module.includes("/packages/simulation/src/frontend/png."))
  if (leaked) throw new Error(`Build graph contains Drive-only rendering input: ${leaked}`)
}

async function artifactFiles(target: string): Promise<string[]> {
  if ((await stat(target)).isFile()) return [target]
  return (await collectFiles(target)).map((file) => path.join(target, file))
}

async function scan(file: string) {
  let trailing = ""
  const reader = Bun.file(file).stream().getReader()
  while (true) {
    const chunk = await reader.read()
    if (chunk.done) return
    const text = trailing + Buffer.from(chunk.value).toString("latin1")
    const leaked = forbidden.find((marker) => text.includes(marker))
    if (leaked) throw new Error(`Artifact file ${file} contains forbidden simulation payload: ${leaked}`)
    trailing = text.slice(-overlap)
  }
}

if (import.meta.main) {
  const target = process.argv[2]
  if (!target) throw new Error("Usage: bun run script/verify-artifact.ts <file-or-directory>")
  await verifyArtifact(target)
}

import {
  agent,
  RequestError,
  type AgentHandlerContext,
  type AgentNotificationHandlersByMethod,
  type AgentNotificationMethod,
  type AgentRequestHandlersByMethod,
  type AgentRequestMethod,
  type JsonRpcId,
  type Stream,
} from "@agentclientprotocol/sdk"
import type { OpenCodeClient } from "@opencode/client/effect"
import { Cause, Deferred, Effect, Ref, type Scope } from "effect"
import { ACPCapabilities } from "./capabilities"
import { ACPCatalog } from "./catalog"
import { ACPClient } from "./client"
import { ACPConnection } from "./connection"
import { ACPError } from "./error"
import { ACPService } from "./service"
import { ACPSessions } from "./sessions"
import { ACPTurn } from "./turn"

type HandlerContext<Params> = AgentHandlerContext<Params> & { readonly requestId?: JsonRpcId }

// Untraced so request spans parent to the caller's span instead of a setup span that has already ended.
export const connect = Effect.fnUntraced(function* (client: OpenCodeClient, stream: Stream) {
  const run = Effect.runPromiseWith(yield* Effect.context<Scope.Scope>())
  const catalog = yield* ACPCatalog.make(client)
  // Requests can dispatch before the service below is built.
  const ready = yield* Deferred.make<{
    readonly service: ACPService.Interface
    readonly connection: ACPConnection.Interface
  }>()
  const handle =
    <Params, A>(
      call: (service: ACPService.Interface, ctx: AgentHandlerContext<Params>) => Effect.Effect<A, ACPError.Failure>,
    ) =>
    (name: string) => {
      const handler = Effect.fn(name)(
        function* (ctx: HandlerContext<Params>) {
          const connected = yield* Deferred.await(ready)
          if (ctx.requestId === undefined) return yield* call(connected.service, ctx)
          return yield* call(connected.service, ctx).pipe(
            Effect.provideService(ACPConnection.Responded, connected.connection.responded(ctx.requestId)),
          )
        },
        Effect.catchTags({
          ACPCatalogLoadError: (error) => ACPClient.classify(error.cause),
          ACPCatalogNotReadyError: (error) =>
            Effect.fail(new ACPError.ServiceFailureError({ safeMessage: error.message, errorName: "CatalogNotReady" })),
        }),
        Effect.mapError((error) => (error instanceof RequestError ? error : ACPError.toRequestError(error))),
        Effect.tapCauseIf(Cause.hasDies, (cause) => Effect.logError("ACP request failed", cause)),
        Effect.catchDefect((defect) => Effect.fail(ACPError.toRequestError(ACPError.fromUnknown(defect)))),
      )
      return (ctx: HandlerContext<Params>) => run(handler(ctx))
    }
  const app = agent({ name: "opencode" })
  const request = <Method extends AgentRequestMethod>(
    method: Method,
    make: (name: string) => AgentRequestHandlersByMethod[Method],
  ) => app.onRequest(method, make(spanName(method)))
  const notification = <Method extends AgentNotificationMethod>(
    method: Method,
    make: (name: string) => AgentNotificationHandlersByMethod[Method],
  ) => app.onNotification(method, make(spanName(method)))

  request(
    "initialize",
    handle((service, ctx) => service.initialize(ctx.params)),
  )
  request(
    "authenticate",
    handle((service, ctx) => service.authenticate(ctx.params)),
  )
  request(
    "session/new",
    handle((service, ctx) => service.newSession(ctx.params)),
  )
  request(
    "session/load",
    handle((service, ctx) => service.loadSession(ctx.params)),
  )
  request(
    "session/list",
    handle((service, ctx) => service.listSessions(ctx.params)),
  )
  request(
    "session/delete",
    handle((service, ctx) => service.deleteSession(ctx.params)),
  )
  request(
    "session/resume",
    handle((service, ctx) => service.resumeSession(ctx.params)),
  )
  request(
    "session/close",
    handle((service, ctx) => service.closeSession(ctx.params)),
  )
  request(
    "session/fork",
    handle((service, ctx) => service.forkSession(ctx.params)),
  )
  request(
    "session/set_config_option",
    handle((service, ctx) => service.setSessionConfigOption(ctx.params)),
  )
  request(
    "session/set_mode",
    handle((service, ctx) => service.setSessionMode(ctx.params)),
  )
  request(
    "session/prompt",
    handle((service, ctx) => service.prompt(ctx.params, ctx.signal)),
  )
  notification(
    "session/cancel",
    handle((service, ctx) => service.cancel(ctx.params)),
  )
  const acp = ACPConnection.make(app, stream)
  const connection = acp.connection
  const sessions = yield* ACPSessions.make({ client, connection, catalog })
  const capabilities = yield* Ref.make(ACPCapabilities.parse(undefined))
  const turn = yield* ACPTurn.make({ client, connection, sessions, catalog, capabilities })
  yield* Deferred.succeed(ready, {
    service: ACPService.make({ client, connection, catalog, sessions, capabilities, turn }),
    connection,
  })
  return acp.agent
})

const spanName = (method: string) => `cli.acp.${method.replaceAll("/", ".")}`

export * as ACP from "./agent"

import type { ClientCapabilities } from "@agentclientprotocol/sdk"

export const ChildSessionUpdates = "opencode/child-session-updates"

export type Capabilities = ReturnType<typeof parse>

export function parse(client: ClientCapabilities | undefined) {
  const elicitation = client?.elicitation
  const compaction = client?.session?.compaction
  return {
    childSessionUpdates: client?._meta?.[ChildSessionUpdates] === true,
    formElicitation: elicitation?.form !== undefined && elicitation.form !== null,
    compaction: compaction !== undefined && compaction !== null,
  }
}

export * as ACPCapabilities from "./capabilities"

import type { OpenCodeClient, OpenCodeEvent } from "@opencode/client/effect"
import type { Agent } from "@opencode/schema/agent"
import type { Command } from "@opencode/schema/command"
import type { Model } from "@opencode/schema/model"
import { FSUtil } from "@opencode/util/fs-util"
import { Cause, Deferred, Effect, Exit, Schedule, Semaphore, Stream, SubscriptionRef } from "effect"
import { ACPError } from "./error"

export const builtinCommands = new Map([
  ["compact", { description: "Compact the session", start: "compaction" as const }],
])

export type Catalog = {
  readonly models: ReadonlyArray<Model.Info>
  readonly defaultModel: Model.Ref
  readonly modes: ReadonlyArray<{ id: Agent.ID; name: string; description?: string }>
  readonly defaultModeID: Agent.ID
  readonly commands: ReadonlyArray<Command.Info>
}

export function findModel(models: ReadonlyArray<Model.Info>, ref: Model.Ref) {
  return models.find((model) => model.providerID === ref.providerID && model.id === ref.id)
}

export interface Interface {
  readonly get: (cwd: string) => Effect.Effect<Catalog, ACPError.CatalogError>
  readonly reload: (cwd: string) => Effect.Effect<void, ACPError.CatalogError>
  readonly changes: (cwd: string) => Stream.Stream<Catalog, ACPError.CatalogError>
}

type Entry = {
  readonly cwd: string
  readonly catalog: SubscriptionRef.SubscriptionRef<Catalog>
  readonly lock: Semaphore.Semaphore
  requestedGeneration: number
  loadedGeneration: number
}

const reloadOn = new Set<OpenCodeEvent["type"]>(["model.updated", "agent.updated", "command.updated"])

export const make = Effect.fnUntraced(function* (client: OpenCodeClient) {
  const scope = yield* Effect.scope
  const entries = new Map<string, Deferred.Deferred<Entry, ACPError.CatalogError>>()
  const connected = yield* Deferred.make<void>()

  // Requests queued behind a running load share the next one.
  const reload = (entry: Entry) =>
    Effect.suspend(() => {
      const target = ++entry.requestedGeneration
      return entry.lock.withPermit(
        Effect.suspend(() => {
          if (entry.loadedGeneration >= target) return Effect.void
          const generation = entry.requestedGeneration
          return load(client, entry.cwd).pipe(
            Effect.flatMap((next) => SubscriptionRef.set(entry.catalog, next)),
            Effect.ignore,
            Effect.andThen(
              Effect.sync(() => {
                entry.loadedGeneration = generation
              }),
            ),
          )
        }),
      )
    })

  // Subscribe before the first read so an update between the read and the subscription is not lost.
  yield* client.event.subscribe().pipe(
    Stream.runForEach((event) => {
      if (event.type === "server.connected") return Deferred.succeed(connected, undefined)
      if (!reloadOn.has(event.type)) return Effect.void
      const directory = event.location?.directory
      const targets = directory === undefined ? [...entries.values()] : [entries.get(FSUtil.resolve(directory))]
      return Effect.forEach(
        targets.filter((entry) => entry !== undefined),
        (entry) => Deferred.await(entry).pipe(Effect.flatMap(reload), Effect.ignore, Effect.forkIn(scope)),
        { discard: true },
      )
    }),
    Effect.catchCause((cause) =>
      Cause.hasInterruptsOnly(cause) ? Effect.void : Effect.logWarning("ACP catalog event stream failed", cause),
    ),
    Effect.ensuring(Deferred.succeed(connected, undefined)),
    Effect.forkScoped,
  )

  const create = Effect.fnUntraced(function* (cwd: string) {
    yield* Deferred.await(connected)
    return {
      cwd,
      catalog: yield* SubscriptionRef.make<Catalog>(yield* load(client, cwd)),
      lock: Semaphore.makeUnsafe(1),
      requestedGeneration: 0,
      loadedGeneration: 0,
    } satisfies Entry
  })

  const entry = (cwd: string) =>
    Effect.suspend(() => {
      const key = FSUtil.resolve(cwd)
      const cached = entries.get(key)
      if (cached) return Deferred.await(cached)
      const loading = Deferred.makeUnsafe<Entry, ACPError.CatalogError>()
      entries.set(key, loading)
      return create(cwd).pipe(
        Effect.onExit((exit) => {
          if (Exit.isFailure(exit)) entries.delete(key)
          return Deferred.done(loading, exit)
        }),
        Effect.forkIn(scope),
        Effect.andThen(Deferred.await(loading)),
      )
    })

  return {
    get: Effect.fnUntraced(function* (cwd) {
      const loaded = yield* entry(cwd)
      return yield* SubscriptionRef.get(loaded.catalog)
    }),
    reload: Effect.fn("cli.acp.catalog.reload")(function* (cwd) {
      yield* reload(yield* entry(cwd))
    }),
    changes: (cwd) => Stream.unwrap(entry(cwd).pipe(Effect.map((loaded) => SubscriptionRef.changes(loaded.catalog)))),
  } satisfies Interface
})

const poll = Schedule.spaced("25 millis").pipe(Schedule.upTo({ duration: "5 seconds" }))

// A cold Location lists no plugins until activation finishes, and providers may still discover models after that.
const load = Effect.fn("cli.acp.catalog.load")(function* (client: OpenCodeClient, cwd: string) {
  yield* client.plugin
    .list({ location: { directory: cwd } })
    .pipe(Effect.repeat({ until: (plugins) => plugins.data.length > 0, schedule: poll }), Effect.ignore)
  return yield* read(client, cwd).pipe(
    Effect.retry({ while: (error) => error._tag === "ACPCatalogNotReadyError", schedule: poll }),
  )
})

const read = Effect.fnUntraced(function* (client: OpenCodeClient, cwd: string) {
  const location = { directory: cwd }
  const [modelResult, defaultResult, agentResult, commandResult] = yield* Effect.all(
    [
      client.model.list({ location }),
      client.model.default({ location }),
      client.agent.list({ location }),
      client.command.list({ location }),
    ],
    { concurrency: "unbounded" },
  ).pipe(Effect.mapError((cause) => new ACPError.CatalogLoadError({ cause })))
  const models = modelResult.data.filter((model) => model.enabled)
  const preferred = defaultResult.data
  // The parallel default read can name a model missing from this list.
  const defaultModel = preferred ? findModel(models, preferred) : models[0]
  if (!defaultModel) return yield* new ACPError.CatalogNotReadyError({ reason: "models" })
  const agents = agentResult.data.filter((agent) => agent.mode !== "subagent" && !agent.hidden)
  // Core lists its resolved default agent first, the same one a new session runs.
  const defaultAgent = agents[0]
  if (!defaultAgent) return yield* new ACPError.CatalogNotReadyError({ reason: "agents" })
  return {
    models,
    defaultModel: {
      providerID: defaultModel.providerID,
      id: defaultModel.id,
      variant: defaultModel.variants.find((variant) => variant.id === "default")?.id,
    },
    modes: agents.map((agent) => ({ id: agent.id, name: agent.name, description: agent.description })),
    defaultModeID: defaultAgent.id,
    commands: commandResult.data.filter((command) => !builtinCommands.has(command.name)),
  } satisfies Catalog
})

export * as ACPCatalog from "./catalog"

import type { SessionUpdate } from "@agentclientprotocol/sdk"

export const UpdateMethod = "opencode/session/child_update"

export type Session = {
  readonly id: string
  readonly parentID: string
  readonly depth: number
  readonly title?: string
}

export type Event =
  | { readonly type: "update"; readonly update: SessionUpdate }
  | {
      readonly type: "status"
      readonly status: "created" | "running" | "completed" | "failed" | "interrupted"
      readonly error?: { readonly type: string; readonly message: string }
    }

export type Update = {
  readonly rootSessionId: string
  readonly childSessionId: string
  readonly parentSessionId: string
  readonly depth: number
  readonly title?: string
} & Event

export function update(rootSessionID: string, child: Session, event: Event): Update {
  return {
    rootSessionId: rootSessionID,
    childSessionId: child.id,
    parentSessionId: child.parentID,
    depth: child.depth,
    ...(child.title ? { title: child.title } : {}),
    ...event,
  }
}

export function project(sessionUpdate: SessionUpdate, child: Session) {
  const projected = { ...sessionUpdate }
  projected._meta = { ...projected._meta, ...meta(child) }
  if (projected.sessionUpdate === "tool_call" || projected.sessionUpdate === "tool_call_update") {
    projected.toolCallId = toolCallID(child, projected.toolCallId)
    if (projected.title) projected.title = prefixTitle(child, projected.title)
  }
  return projected
}

export function meta(child: Session) {
  return {
    "opencode/child-session": {
      id: child.id,
      parentID: child.parentID,
      depth: child.depth,
      ...(child.title ? { title: child.title } : {}),
    },
  }
}

export function toolCallID(child: Session | undefined, id: string) {
  return child ? `${child.id}:${id}` : id
}

export function prefixTitle(child: Session | undefined, value: string) {
  return child?.title ? `${child.title}: ${value}` : value
}

export * as ACPChild from "./child"

import { ClientError } from "@opencode/client/effect"
import { InvalidCursorError, InvalidRequestError, SessionNotFoundError } from "@opencode/protocol/errors"
import { Session } from "@opencode/schema/session"
import { Effect, Schema } from "effect"
import { HttpClientError } from "effect/http"
import { ACPError } from "./error"

export function classify(error: unknown): Effect.Effect<never, ACPError.Error> {
  if (
    error instanceof ClientError &&
    HttpClientError.isHttpClientError(error.cause) &&
    // The client reports a failed body read as a `DecodeError` with a cause; its other `DecodeError`s have none.
    (error.cause.reason._tag === "TransportError" ||
      (error.cause.reason._tag === "DecodeError" && error.cause.reason.cause !== undefined))
  )
    return Effect.fail(new ACPError.ServerUnavailableError())
  if (error instanceof SessionNotFoundError)
    return Effect.fail(new ACPError.SessionNotFoundError({ sessionId: error.sessionID }))
  if (error instanceof InvalidRequestError)
    return Effect.fail(new ACPError.InvalidRequestError({ message: error.message, field: error.field }))
  if (error instanceof InvalidCursorError)
    return Effect.fail(new ACPError.InvalidRequestError({ message: error.message, field: "cursor" }))
  return Effect.die(error)
}

export function decodeSessionID(value: string) {
  return Schema.decodeUnknownEffect(Session.ID)(value).pipe(
    Effect.mapError(() => new ACPError.InvalidRequestError({ message: "Invalid session ID", field: "sessionID" })),
  )
}

export * as ACPClient from "./client"

import type { SessionUpdate } from "@agentclientprotocol/sdk"
import type { OpenCodeEvent } from "@opencode/client/effect"
import type { SessionError } from "@opencode/schema/session-error"
import { SessionMessage } from "@opencode/schema/session-message"

const MarkerMeta = "opencode/compaction"

type Started = { readonly status: "started"; readonly messageId: string; readonly reason: "auto" | "manual" }

type Compaction =
  | Started
  | {
      readonly status: "completed"
      readonly messageId: string
      readonly reason: "auto" | "manual"
      readonly summary: string
    }
  | {
      readonly status: "failed"
      readonly messageId: string
      readonly reason: "auto" | "manual"
      readonly error: SessionError.Error
    }

export type Tracked = ReadonlyMap<string, Started>

type LifecycleEvent = Extract<
  OpenCodeEvent,
  { readonly type: "session.compaction.started" | "session.compaction.ended" | "session.compaction.failed" }
>
type OpeningEvent = Extract<
  LifecycleEvent,
  { readonly type: "session.compaction.started" | "session.compaction.failed" }
>

const Cancelled = new Set(["aborted", "compaction.interrupted"])

// Without child updates, a child's standard update would read as the parent's own.
export function usesStandardUpdates(
  ctx: { readonly compaction: boolean; readonly childUpdates: boolean },
  child: boolean,
) {
  return ctx.compaction && (!child || ctx.childUpdates)
}

export function apply(event: LifecycleEvent, tracked: Tracked, standardUpdates: boolean) {
  const sessionID = event.data.sessionID
  if (event.type === "session.compaction.started") {
    const started = open(event)
    return { tracked: new Map(tracked).set(sessionID, started), updates: [update(started, standardUpdates)] }
  }
  const current = tracked.get(sessionID)
  const remaining = new Map(tracked)
  remaining.delete(sessionID)
  if (event.type === "session.compaction.ended") {
    if (!current) return { tracked: remaining, updates: [] }
    const completed: Compaction = {
      ...current,
      status: "completed",
      reason: event.data.reason,
      summary: event.data.text,
    }
    return { tracked: remaining, updates: [update(completed, standardUpdates)] }
  }
  // Auto compaction can fail without a started event; open it first for standard clients.
  const started = current ?? open(event)
  const failed: Compaction = { ...started, status: "failed", reason: event.data.reason, error: event.data.error }
  return {
    tracked: remaining,
    updates: [
      ...(current || !standardUpdates ? [] : [update(started, standardUpdates)]),
      update(failed, standardUpdates),
    ],
  }
}

export function chunk(started: Started | undefined, text: string, standardUpdates: boolean): SessionUpdate | undefined {
  if (!started || !standardUpdates) return undefined
  return { sessionUpdate: "compaction_summary_chunk", compactionId: started.messageId, content: { type: "text", text } }
}

export function abandon(started: Started, standardUpdates: boolean) {
  return update(
    { ...started, status: "failed", error: { type: "aborted", message: "Compaction cancelled" } },
    standardUpdates,
  )
}

// Nothing on this connection would settle a replayed running compaction.
export function replay(message: Extract<SessionMessage.Info, { type: "compaction" }>, standardUpdates: boolean) {
  if (message.status === "running") return undefined
  const base = { messageId: message.id, reason: message.reason }
  return update(
    message.status === "failed"
      ? { ...base, status: "failed", error: message.error }
      : { ...base, status: "completed", summary: message.summary },
    standardUpdates,
  )
}

// Matches core's compaction message ID, so live and replayed compactions line up.
function open(event: OpeningEvent): Started {
  return {
    status: "started",
    messageId: event.data.inputID ?? SessionMessage.ID.fromEvent(event.id),
    reason: event.data.reason,
  }
}

function update(compaction: Compaction, standardUpdates: boolean): SessionUpdate {
  if (!standardUpdates) {
    const marker = {
      status: compaction.status,
      messageId: compaction.messageId,
      reason: compaction.reason,
      ...(compaction.status === "failed" ? { error: compaction.error } : {}),
    }
    return { sessionUpdate: "session_info_update", _meta: { [MarkerMeta]: marker } }
  }
  const compactionId = compaction.messageId
  if (compaction.status === "started")
    return { sessionUpdate: "compaction_update", compactionId, status: "in_progress" }
  if (compaction.status === "completed") {
    const summary = compaction.summary ? [{ type: "text" as const, text: compaction.summary }] : null
    return { sessionUpdate: "compaction_update", compactionId, status: "completed", summary }
  }
  if (Cancelled.has(compaction.error.type))
    return { sessionUpdate: "compaction_update", compactionId, status: "cancelled", summary: null }
  return {
    sessionUpdate: "compaction_update",
    compactionId,
    status: "failed",
    summary: null,
    error: displayError(compaction.error),
  }
}

// Core reports a defect as `compaction.failed` with a multi-line pretty-printed cause.
function displayError(error: SessionError.Error) {
  if (!error.message || (error.type === "compaction.failed" && error.message.includes("\n"))) return "Compaction failed"
  return error.message
}

export * as ACPCompaction from "./compaction"

import type { SessionConfigOption } from "@agentclientprotocol/sdk"
import type { Agent } from "@opencode/schema/agent"
import { Model } from "@opencode/schema/model"
import { Provider } from "@opencode/schema/provider"
import { Effect, Order } from "effect"
import { builtinCommands, findModel, type Catalog } from "./catalog"
import { ACPError } from "./error"

const DEFAULT_VARIANT_VALUE = "default"

export type Selection = {
  readonly model?: Model.Ref
  readonly modeID?: Agent.ID
}

export type Change = { readonly model: Model.Ref } | { readonly modeID: Agent.ID }

export function currentModel(catalog: Catalog, selection: Selection) {
  return selection.model ?? catalog.defaultModel
}

export function configOptions(catalog: Catalog, selection: Selection): SessionConfigOption[] {
  const model = currentModel(catalog, selection)
  const variants = findModel(catalog.models, model)?.variants.map((variant) => variant.id) ?? []
  return [
    {
      id: "model",
      name: "Model",
      category: "model",
      type: "select",
      currentValue: advertisedModel(model),
      options: catalog.models
        .toSorted((a, b) => Order.String(a.providerID, b.providerID) || a.name.localeCompare(b.name))
        .map((item) => ({ value: advertisedModel(item), name: `${item.providerID}/${item.name}` })),
    },
    ...(variants.length > 0
      ? [
          {
            id: "effort",
            name: "Effort",
            description: "Available effort levels for this model",
            category: "thought_level",
            type: "select",
            currentValue: selectVariant(model.variant, variants),
            options: [...new Set([...variants, DEFAULT_VARIANT_VALUE])].map((variant) => ({
              value: variant,
              name: variant
                .split(/[_-]/)
                .map((part) => (part ? part.charAt(0).toUpperCase() + part.slice(1) : part))
                .join(" "),
            })),
          } satisfies SessionConfigOption,
        ]
      : []),
    {
      id: "mode",
      name: "Session Mode",
      category: "mode",
      type: "select",
      currentValue: selection.modeID ?? catalog.defaultModeID,
      options: catalog.modes.map((mode) => ({
        value: mode.id,
        name: mode.name,
        ...(mode.description ? { description: mode.description } : {}),
      })),
    },
  ]
}

export function availableCommands(catalog: Catalog) {
  return [
    ...catalog.commands.map((command) => ({ name: command.name, description: command.description ?? "" })),
    ...Array.from(builtinCommands, ([name, command]) => ({ name, description: command.description })),
  ]
}

export const resolveChange = Effect.fnUntraced(function* (
  catalog: Catalog,
  selection: Selection,
  configId: string,
  value: string,
) {
  const current = currentModel(catalog, selection)
  switch (configId) {
    case "model":
      return { model: yield* requireModel(catalog, value, current) }
    case "effort": {
      const model = findModel(catalog.models, current)
      if (!model || (value !== DEFAULT_VARIANT_VALUE && !model.variants.some((variant) => variant.id === value)))
        return yield* new ACPError.InvalidEffortError({ effort: value })
      return { model: { ...current, variant: Model.VariantID.make(value) } }
    }
    case "mode": {
      const mode = catalog.modes.find((item) => item.id === value)
      if (!mode) return yield* new ACPError.InvalidModeError({ mode: value })
      return { modeID: mode.id }
    }
    default:
      return yield* new ACPError.InvalidConfigOptionError({ configId })
  }
})

export function parseModelSelection(value: string, models: ReadonlyArray<Model.Info>): Model.Ref {
  const exact = models.find((model) => advertisedModel(model) === value)
  if (exact) return { providerID: exact.providerID, id: exact.id }
  const separator = value.lastIndexOf("/")
  const variant = Model.VariantID.make(value.slice(separator + 1))
  const base = models.find(
    (model) =>
      advertisedModel(model) === value.slice(0, separator) && model.variants.some((item) => item.id === variant),
  )
  if (base) return { providerID: base.providerID, id: base.id, variant }
  const providerEnd = value.indexOf("/")
  if (providerEnd === -1) return { providerID: Provider.ID.make(value), id: Model.ID.make("") }
  return { providerID: Provider.ID.make(value.slice(0, providerEnd)), id: Model.ID.make(value.slice(providerEnd + 1)) }
}

const requireModel = Effect.fnUntraced(function* (catalog: Catalog, value: string, current: Model.Ref) {
  const selected = parseModelSelection(value, catalog.models)
  const model = findModel(catalog.models, selected)
  if (!model) return yield* new ACPError.InvalidModelError({ providerId: selected.providerID, modelId: value })
  const selectedVariant = model.variants.find((variant) => variant.id === selected.variant)
  if (selected.variant && !selectedVariant) return yield* new ACPError.InvalidEffortError({ effort: selected.variant })
  const variant =
    selectedVariant?.id ??
    (current.providerID === model.providerID &&
    current.id === model.id &&
    (current.variant === DEFAULT_VARIANT_VALUE || model.variants.some((variant) => variant.id === current.variant))
      ? current.variant
      : undefined)
  return { providerID: model.providerID, id: model.id, variant } satisfies Model.Ref
})

function advertisedModel(model: { readonly providerID: string; readonly id: string }) {
  return `${model.providerID}/${model.id}`
}

function selectVariant(variant: string | undefined, variants: readonly string[]) {
  if (!variant || variant === DEFAULT_VARIANT_VALUE) return DEFAULT_VARIANT_VALUE
  if (variants.includes(variant)) return variant
  if (variants.includes(DEFAULT_VARIANT_VALUE)) return DEFAULT_VARIANT_VALUE
  return variants[0] ?? DEFAULT_VARIANT_VALUE
}

import {
  methods,
  type AgentApp,
  type AnyMessage,
  type CreateElicitationRequest,
  type CreateElicitationResponse,
  type JsonRpcId,
  RequestError,
  type RequestPermissionRequest,
  type RequestPermissionResponse,
  type SessionNotification,
  type Stream,
} from "@agentclientprotocol/sdk"
import { Context, Deferred, Effect } from "effect"

export const Responded = Context.Reference<Effect.Effect<void>>("@opencode/cli/acp/Connection/Responded", {
  defaultValue: () => Effect.void,
})

export interface Interface {
  readonly sessionUpdate: (params: SessionNotification) => Effect.Effect<void, RequestError>
  readonly requestPermission: (
    params: RequestPermissionRequest,
  ) => Effect.Effect<RequestPermissionResponse, RequestError>
  readonly extNotification: (method: string, params: Record<string, unknown>) => Effect.Effect<void, RequestError>
  readonly createElicitation: (
    params: CreateElicitationRequest,
  ) => Effect.Effect<CreateElicitationResponse, RequestError>
  readonly responded: (requestId: JsonRpcId) => Effect.Effect<void>
}

export function make(app: AgentApp, stream: Stream) {
  const responses = new Map<JsonRpcId, Deferred.Deferred<void>>()
  const writer = stream.writable.getWriter()
  const agent = app.connect({
    readable: stream.readable,
    writable: new WritableStream<AnyMessage>({
      write: async (message) => {
        await writer.write(message)
        if ("method" in message) return
        const responded = responses.get(message.id)
        if (!responded) return
        responses.delete(message.id)
        Deferred.doneUnsafe(responded, "result" in message ? Effect.void : Effect.interrupt)
      },
      close: () => writer.close(),
      abort: (reason) => writer.abort(reason),
    }),
  })
  return {
    agent,
    connection: {
      sessionUpdate: (params) => promise(() => agent.client.notify(methods.client.session.update, params)),
      requestPermission: (params) =>
        promise((signal) =>
          agent.client.request(methods.client.session.requestPermission, params, { cancellationSignal: signal }),
        ),
      extNotification: (method, params) => promise(() => agent.client.notify(method, params)),
      createElicitation: (params) =>
        promise((signal) =>
          agent.client.request(methods.client.elicitation.create, params, { cancellationSignal: signal }),
        ),
      responded: (requestId) => {
        const responded = Deferred.makeUnsafe<void>()
        responses.set(requestId, responded)
        return Deferred.await(responded)
      },
    } satisfies Interface,
  }
}

function promise<A>(evaluate: (signal: AbortSignal) => Promise<A>) {
  return Effect.tryPromise({ try: evaluate, catch: (cause) => cause }).pipe(
    Effect.catch((cause) => (cause instanceof RequestError ? Effect.fail(cause) : Effect.die(cause))),
  )
}

export * as ACPConnection from "./connection"

import type { ContentBlock, ContentChunk, ResourceLink } from "@agentclientprotocol/sdk"
import path from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"
import { Result } from "effect"

export type PromptPart =
  | { readonly type: "text"; readonly text: string; readonly synthetic?: boolean; readonly ignored?: boolean }
  | { readonly type: "file"; readonly url: string; readonly filename?: string; readonly mime: string }

type ReplayPart = PromptPart | { readonly type: "reasoning"; readonly text: string }

export function promptContentToParts(content: readonly ContentBlock[]): PromptPart[] {
  return content.flatMap(contentBlockToParts)
}

function contentBlockToParts(block: ContentBlock): PromptPart[] {
  switch (block.type) {
    case "text": {
      const audience = block.annotations?.audience
      if (audience?.length === 1 && audience[0] === "assistant") {
        return [{ type: "text", text: block.text, synthetic: true }]
      }
      if (audience?.length === 1 && audience[0] === "user") {
        return [{ type: "text", text: block.text, ignored: true }]
      }
      return [{ type: "text", text: block.text }]
    }
    case "image": {
      const url = block.data ? `data:${block.mimeType};base64,${block.data}` : block.uri
      if (!url) return []
      const filename = filenameFromUri(block.uri ?? undefined) ?? "image"
      if (url.startsWith("data:")) return [{ type: "file", url, filename, mime: block.mimeType }]
      return [resourceLinkToPart({ uri: url, name: filename, mimeType: block.mimeType })]
    }
    case "resource_link":
      return [resourceLinkToPart(block)]
    case "resource":
      if ("text" in block.resource) {
        const parsed = URL.canParse(block.resource.uri) ? new URL(block.resource.uri) : undefined
        const decoded =
          parsed?.protocol === "file:"
            ? Result.try(() => fileURLToPath(parsed)).pipe(
                Result.orElse(() => Result.try(() => decodeURIComponent(parsed.pathname))),
                Result.getOrUndefined,
              )
            : undefined
        if (!parsed || decoded === undefined)
          return [{ type: "text", text: `[${block.resource.uri}]\n${block.resource.text}` }]
        const line = parsed.hash.match(/^#L(\d+)/)?.[1]
        const filepath = path.sep === "\\" ? decoded.replace(/\\/g, "/") : decoded
        return [{ type: "text", text: `[${filepath}${line ? `:${line}` : ""}]\n${block.resource.text}` }]
      }
      if (!block.resource.mimeType) return []
      return [
        {
          type: "file",
          url: block.resource.uri.startsWith("data:")
            ? block.resource.uri
            : `data:${block.resource.mimeType};base64,${block.resource.blob}`,
          filename: filenameFromUri(block.resource.uri) ?? "file",
          mime: block.resource.mimeType,
        },
      ]
    default:
      return []
  }
}

export function partsToContentChunks(parts: readonly ReplayPart[]): ContentChunk[] {
  return parts.flatMap((part): ContentChunk[] => {
    if (part.type === "text") {
      if (!part.text) return []
      return [
        {
          content: {
            type: "text",
            text: part.text,
            ...(part.synthetic ? { annotations: { audience: ["assistant" as const] } } : {}),
            ...(!part.synthetic && part.ignored ? { annotations: { audience: ["user" as const] } } : {}),
          },
        },
      ]
    }
    if (part.type === "reasoning") {
      return part.text ? [{ content: { type: "text", text: part.text } }] : []
    }
    if (part.url.startsWith("file://")) {
      return [
        {
          content: {
            type: "resource_link",
            uri: part.url,
            name: part.filename ?? "file",
            mimeType: part.mime,
          },
        },
      ]
    }
    if (!part.url.startsWith("data:")) return []
    const match = /^data:([^;]+);base64,(.*)$/.exec(part.url)
    if (!match?.[1] || match[2] === undefined) return []
    const mime = match[1]
    const data = match[2]
    if (mime.startsWith("image/")) {
      return [
        {
          content: {
            type: "image",
            mimeType: mime,
            data,
            uri: pathToFileURL(part.filename ?? "image").href,
          },
        },
      ]
    }
    return [
      {
        content: {
          type: "resource",
          resource:
            mime.startsWith("text/") || mime === "application/json"
              ? {
                  uri: pathToFileURL(part.filename ?? "file").href,
                  mimeType: mime,
                  text: Buffer.from(data, "base64").toString("utf8"),
                }
              : {
                  uri: pathToFileURL(part.filename ?? "file").href,
                  mimeType: mime,
                  blob: data,
                },
        },
      },
    ]
  })
}

function resourceLinkToPart(link: ResourceLink): PromptPart {
  if (link.uri.startsWith("file://")) {
    return {
      type: "file",
      url: link.uri,
      filename: link.name || filenameFromUri(link.uri) || "file",
      mime: link.mimeType ?? "text/plain",
    }
  }
  if (link.uri.startsWith("zed://") && URL.canParse(link.uri)) {
    const pathname = new URL(link.uri).searchParams.get("path")
    if (pathname)
      return {
        type: "file",
        url: pathToFileURL(pathname).href,
        filename: link.name || path.basename(pathname) || "file",
        mime: link.mimeType ?? "text/plain",
      }
  }
  return linkReference(link.name, link.uri)
}

export function linkReference(name: string | undefined, uri: string): PromptPart {
  return { type: "text", text: name ? `[${name}](${uri})` : uri }
}

function filenameFromUri(uri: string | undefined): string | undefined {
  if (!uri || uri.startsWith("data:")) return undefined
  if (URL.canParse(uri)) {
    const url = new URL(uri)
    return path.basename((url.protocol === "zed:" && url.searchParams.get("path")) || url.pathname) || undefined
  }
  return path.basename(uri) || undefined
}

import { isAbsolute, join, resolve } from "node:path"
import { isDeepStrictEqual } from "node:util"
import type { OpenCodeClient } from "@opencode/client/effect"
import type { Permission } from "@opencode/schema/permission"
import { AbsolutePath } from "@opencode/schema/schema"
import type { Session } from "@opencode/schema/session"
import { FSUtil } from "@opencode/util/fs-util"
import { Effect, Option, Schema } from "effect"
import { ACPClient } from "./client"
import { ACPError } from "./error"

const key = "opencode.acp.additionalDirectories"
const decodeStored = Schema.decodeUnknownOption(Schema.Array(Schema.String))

// Permission resources treat `*` and `?` as wildcards.
export const parse = Effect.fnUntraced(function* (cwd: string, directories: readonly string[] = []) {
  yield* parseCwd(cwd)
  const invalid = directories.find((directory) => !isAbsolute(directory) || /[*?]/.test(directory))
  if (invalid !== undefined) return yield* new ACPError.InvalidAdditionalDirectoryError({ directory: invalid })
  const root = FSUtil.resolve(cwd)
  return [...new Set(directories.map((directory) => resolve(FSUtil.windowsPath(directory))))].filter(
    (directory) => FSUtil.resolve(directory) !== root,
  )
})

export const parseCwd = Effect.fnUntraced(function* (cwd: string) {
  if (!isAbsolute(cwd))
    return yield* new ACPError.InvalidRequestError({ message: `cwd must be an absolute path: ${cwd}`, field: "cwd" })
  return AbsolutePath.make(cwd)
})

export function grant(directories: readonly string[]) {
  if (directories.length === 0) return {}
  return { permissions: rules(directories), metadata: { [key]: [...directories] } }
}

export function list(session: Pick<Session.Info, "metadata">) {
  return [...Option.getOrElse(decodeStored(session.metadata?.[key]), () => [])]
}

export const activate = Effect.fnUntraced(function* (
  client: OpenCodeClient,
  session: Session.Info,
  directories: readonly string[],
) {
  const previous = list(session)
  const owned = rules(previous)
  const current = session.permissions ?? []
  // ACP rules lead so the session's other rules keep precedence for the same paths.
  const permissions = [
    ...rules(directories),
    ...current.filter((rule) => !owned.some((item) => isDeepStrictEqual(item, rule))),
  ]
  const metadata: Session.Metadata = {
    ...Object.fromEntries(Object.entries(session.metadata ?? {}).filter(([name]) => name !== key)),
    ...(directories.length > 0 ? { [key]: [...directories] } : {}),
  }
  const permissionsChanged = !isDeepStrictEqual(permissions, current)
  const metadataChanged = !isDeepStrictEqual(previous, directories)
  if (!permissionsChanged && !metadataChanged) return
  yield* client.session
    .update({
      sessionID: session.id,
      ...(permissionsChanged ? { permissions } : {}),
      ...(metadataChanged ? { metadata } : {}),
    })
    .pipe(Effect.catch(ACPClient.classify))
})

// Tools compare the written path without following symlinks, so both spellings of a root are granted.
function rules(directories: readonly string[]): Permission.Rule[] {
  return [...new Set(directories.flatMap((directory) => [directory, FSUtil.resolve(directory)]))].map((directory) => ({
    action: "external_directory",
    resource: join(directory, "*"),
    effect: "allow",
  }))
}

export * as ACPDirectories from "./directories"

import type {
  CreateElicitationResponse,
  ElicitationPropertySchema,
  ElicitationSchema,
  EnumOption,
} from "@agentclientprotocol/sdk"
import type { OpenCodeClient } from "@opencode/client/effect"
import { Form } from "@opencode/schema/form"
import { Effect, Option, Schema } from "effect"
import type { Capabilities } from "./capabilities"
import { ACPChild } from "./child"
import { ACPClient } from "./client"
import type { ACPConnection } from "./connection"

export type AskedForm = Omit<Form.Info, "id"> & { readonly id: string }
type InputField = Exclude<Form.Field, Form.ExternalField>
type SelectField = Form.StringField | Form.MultiselectField

const QuestionKind = "question"
// Form mode must not collect secrets; elicit only flows known to be credential-free.
const ElicitedKind = Schema.Struct({ kind: Schema.Literals([QuestionKind, "websearch.provider"]) })
const Credential = /password|passphrase|secret|token|api[_ -]?key|credential|private[_ -]?key/i
const ToolSource = Schema.Struct({ tool: Schema.Struct({ id: Schema.String }) })

type Input = {
  readonly client: OpenCodeClient
  readonly connection: ACPConnection.Interface
  readonly form: Form.Info
  readonly requestedSchema: ElicitationSchema
  readonly clientSessionID: string
  readonly child?: ACPChild.Session
  readonly toolCallSent: boolean
}

export const UnshownQuestionMessage =
  "The question couldn't be shown to the user in this client. Continue without an answer: make reasonable assumptions and state them, or ask the user in your reply if you can't proceed."

function cancel(client: OpenCodeClient, form: Form.Info, message?: string) {
  return client.session.form.cancel({ sessionID: form.sessionID, formID: form.id, message }).pipe(
    Effect.catchTag(["FormAlreadySettledError", "FormNotFoundError"], () => Effect.void),
    Effect.catch(() =>
      ACPClient.decodeSessionID(form.sessionID).pipe(
        Effect.flatMap((sessionID) => client.session.interrupt({ sessionID })),
        Effect.ignore,
      ),
    ),
  )
}

export function requestedSchema(form: AskedForm, capabilities: Capabilities): ElicitationSchema | undefined {
  if (!capabilities.formElicitation) return undefined
  if (Option.isNone(Schema.decodeUnknownOption(ElicitedKind)(form.metadata))) return undefined
  if (form.fields.some(credentialLike)) return undefined
  const fields = form.fields.filter((field): field is InputField => field.type !== "external")
  if (fields.length !== form.fields.length || fields.some((field) => field.when?.length)) return undefined
  if (fields.some((field) => field.hidden && field.required && field.default === undefined)) return undefined
  const keys = new Set(fields.map((field) => field.key))
  const visible = fields.filter((field) => !field.hidden)
  if (!visible.every((field) => representable(field, keys))) return undefined
  return {
    type: "object",
    properties: Object.fromEntries(visible.flatMap(properties)),
    required: visible.filter((field) => field.required).map((field) => field.key),
  }
}

// The question tool returns the message to the model, so the turn continues instead of ending as interrupted.
export function cancelUnshown(client: OpenCodeClient, form: Form.Info) {
  return cancel(client, form, form.metadata?.kind === QuestionKind ? UnshownQuestionMessage : undefined).pipe(
    Effect.uninterruptible,
  )
}

function answer(form: AskedForm, response: CreateElicitationResponse): Form.Answer | undefined {
  if (response.action !== "accept") return undefined
  const content = Schema.decodeUnknownOption(Form.Answer)(response.content ?? {})
  if (Option.isNone(content)) return undefined
  return Object.fromEntries(
    form.fields.flatMap((field) => {
      const value = fieldAnswer(field, content.value)
      return value === undefined ? [] : [[field.key, value]]
    }),
  )
}

export const ask = Effect.fnUntraced(function* (input: Input) {
  const source = input.toolCallSent ? Schema.decodeUnknownOption(ToolSource)(input.form.metadata) : Option.none()
  const toolCallID = Option.getOrUndefined(Option.map(source, (metadata) => metadata.tool.id))
  const response = yield* input.connection.createElicitation({
    mode: "form",
    sessionId: input.clientSessionID,
    ...(toolCallID ? { toolCallId: ACPChild.toolCallID(input.child, toolCallID) } : {}),
    message: ACPChild.prefixTitle(input.child, input.form.title),
    requestedSchema: input.requestedSchema,
  })
  return answer(input.form, response) ?? "cancel"
})

export function respond(input: Input, outcome: Form.Answer | "cancel") {
  if (outcome === "cancel") return cancel(input.client, input.form)
  return input.client.session.form
    .reply({ sessionID: input.form.sessionID, formID: input.form.id, answer: outcome })
    .pipe(
      Effect.catchTag(["FormAlreadySettledError", "FormNotFoundError"], () => Effect.void),
      Effect.catch((cause) =>
        Effect.logWarning("ACP form reply failed", cause).pipe(Effect.andThen(cancel(input.client, input.form))),
      ),
    )
}

function credentialLike(field: Form.Field) {
  const labels =
    field.type === "string" || field.type === "multiselect" ? (field.options ?? []).map((option) => option.label) : []
  return [field.key, field.title, field.description, ...labels].some(
    (text) => text !== undefined && Credential.test(text),
  )
}

function representable(field: InputField, keys: ReadonlySet<string>) {
  if (field.type !== "string" && field.type !== "multiselect") return true
  if (!hasOptions(field)) return true
  const values = new Set(field.options?.map((option) => option.value))
  const defaults =
    field.default === undefined ? [] : typeof field.default === "string" ? [field.default] : field.default
  if (defaults.some((value) => !values.has(value))) return false
  if (!field.custom) return true
  if (field.required || keys.has(customKey(field))) return false
  return field.type === "string" || (field.minItems === undefined && field.maxItems === undefined)
}

function properties(field: InputField): Array<[string, ElicitationPropertySchema]> {
  const base = { title: field.title, description: field.description }
  switch (field.type) {
    case "string": {
      if (!hasOptions(field))
        return [[field.key, { type: "string", ...base, ...stringConstraints(field), default: field.default }]]
      const select: ElicitationPropertySchema = {
        type: "string",
        ...base,
        oneOf: options(field),
        default: field.default,
      }
      return field.custom ? [[field.key, select], other(field, "Type your own answer")] : [[field.key, select]]
    }
    case "multiselect": {
      const select: ElicitationPropertySchema = {
        type: "array",
        ...base,
        items: { anyOf: options(field) },
        minItems: field.required ? Math.max(field.minItems ?? 0, 1) : field.minItems,
        maxItems: field.maxItems,
        default: field.default,
      }
      return field.custom ? [[field.key, select], other(field, "Add your own answer")] : [[field.key, select]]
    }
    case "number":
    case "integer":
      return [
        [
          field.key,
          { type: field.type, ...base, minimum: field.minimum, maximum: field.maximum, default: field.default },
        ],
      ]
    case "boolean":
      return [[field.key, { type: "boolean", ...base, default: field.default }]]
  }
}

function other(field: SelectField, description: string): [string, ElicitationPropertySchema] {
  return [
    customKey(field),
    {
      type: "string",
      title: `${field.title ?? field.key} (other)`,
      description,
      ...(field.type === "string" ? stringConstraints(field) : {}),
    },
  ]
}

// Core rejects an empty string for a required field.
function stringConstraints(field: Form.StringField) {
  return {
    format: field.format,
    minLength: field.required ? Math.max(field.minLength ?? 0, 1) : field.minLength,
    maxLength: field.maxLength,
    pattern: field.pattern,
  }
}

function options(field: SelectField): EnumOption[] {
  return (field.options ?? []).map((option) => ({
    const: option.value,
    title: option.label,
    description: option.description,
  }))
}

function fieldAnswer(field: Form.Field, content: Form.Answer) {
  if (field.type !== "external" && field.hidden) return field.default
  const value = content[field.key]
  if ((field.type !== "string" && field.type !== "multiselect") || !field.custom || !hasOptions(field)) return value
  const custom = content[customKey(field)]
  if (typeof custom !== "string" || custom.trim() === "") return value
  if (field.type === "string") return custom
  return Array.isArray(value) ? [...value, custom] : [custom]
}

function hasOptions(field: SelectField) {
  return field.type === "multiselect" || field.options !== undefined
}

function customKey(field: SelectField) {
  return `${field.key}_custom`
}

export * as ACPElicitation from "./elicitation"

import { RequestError } from "@agentclientprotocol/sdk"
import { Schema } from "effect"

export class SessionNotFoundError extends Schema.TaggedError<SessionNotFoundError>()("ACPSessionNotFoundError", {
  sessionId: Schema.String,
}) {}

export class SessionDirectoryMismatchError extends Schema.TaggedError<SessionDirectoryMismatchError>()(
  "ACPSessionDirectoryMismatchError",
  { sessionId: Schema.String, cwd: Schema.String },
) {}

export class InvalidConfigOptionError extends Schema.TaggedError<InvalidConfigOptionError>()(
  "ACPInvalidConfigOptionError",
  { configId: Schema.String },
) {}

export class InvalidModelError extends Schema.TaggedError<InvalidModelError>()("ACPInvalidModelError", {
  modelId: Schema.String,
  providerId: Schema.optional(Schema.String),
}) {}

export class InvalidEffortError extends Schema.TaggedError<InvalidEffortError>()("ACPInvalidEffortError", {
  effort: Schema.String,
}) {}

export class InvalidModeError extends Schema.TaggedError<InvalidModeError>()("ACPInvalidModeError", {
  mode: Schema.String,
}) {}

export class InvalidAdditionalDirectoryError extends Schema.TaggedError<InvalidAdditionalDirectoryError>()(
  "ACPInvalidAdditionalDirectoryError",
  { directory: Schema.String },
) {}

export class AuthRequiredError extends Schema.TaggedError<AuthRequiredError>()("ACPAuthRequiredError", {}) {}

export class UnknownAuthMethodError extends Schema.TaggedError<UnknownAuthMethodError>()("ACPUnknownAuthMethodError", {
  methodId: Schema.String,
}) {}

export class InvalidRequestError extends Schema.TaggedError<InvalidRequestError>()("ACPInvalidRequestError", {
  message: Schema.String,
  field: Schema.optional(Schema.String),
}) {}

export class ServiceFailureError extends Schema.TaggedError<ServiceFailureError>()("ACPServiceFailureError", {
  safeMessage: Schema.String,
  service: Schema.optional(Schema.String),
  errorName: Schema.optional(Schema.String),
}) {}

export class ServerUnavailableError extends Schema.TaggedError<ServerUnavailableError>()(
  "ACPServerUnavailableError",
  {},
) {}

export class CatalogNotReadyError extends Schema.TaggedError<CatalogNotReadyError>()("ACPCatalogNotReadyError", {
  reason: Schema.Literals(["models", "agents"]),
}) {
  override get message() {
    return this.reason === "models" ? "No models are available" : "No primary agents are available"
  }
}

export class CatalogLoadError extends Schema.TaggedError<CatalogLoadError>()("ACPCatalogLoadError", {
  cause: Schema.Defect(),
}) {}

export type CatalogError = CatalogNotReadyError | CatalogLoadError

export type Error =
  | SessionNotFoundError
  | SessionDirectoryMismatchError
  | InvalidConfigOptionError
  | InvalidModelError
  | InvalidEffortError
  | InvalidModeError
  | InvalidAdditionalDirectoryError
  | AuthRequiredError
  | UnknownAuthMethodError
  | InvalidRequestError
  | ServiceFailureError
  | ServerUnavailableError

export type Failure = Error | RequestError | CatalogError

export function toRequestError(error: Error): RequestError {
  switch (error._tag) {
    case "ACPSessionNotFoundError":
      return RequestError.invalidParams({ sessionId: error.sessionId }, `session not found: ${error.sessionId}`)
    case "ACPSessionDirectoryMismatchError":
      return RequestError.invalidParams(
        { sessionId: error.sessionId, cwd: error.cwd },
        `session ${error.sessionId} does not belong to cwd: ${error.cwd}`,
      )
    case "ACPInvalidConfigOptionError":
      return RequestError.invalidParams({ configId: error.configId }, `unknown config option: ${error.configId}`)
    case "ACPInvalidModelError":
      return RequestError.invalidParams(
        { providerId: error.providerId, modelId: error.modelId },
        `model not found: ${error.modelId}`,
      )
    case "ACPInvalidEffortError":
      return RequestError.invalidParams({ effort: error.effort }, `effort not found: ${error.effort}`)
    case "ACPInvalidModeError":
      return RequestError.invalidParams({ mode: error.mode }, `mode not found: ${error.mode}`)
    case "ACPInvalidAdditionalDirectoryError":
      return RequestError.invalidParams(
        { additionalDirectory: error.directory },
        `additional directory must be an absolute path without glob characters: ${error.directory}`,
      )
    case "ACPAuthRequiredError":
      return RequestError.authRequired({}, "provider authentication required")
    case "ACPUnknownAuthMethodError":
      return RequestError.invalidParams({ methodId: error.methodId }, `unknown auth method: ${error.methodId}`)
    case "ACPInvalidRequestError":
      return RequestError.invalidParams(error.field ? { field: error.field } : {}, error.message)
    case "ACPServiceFailureError":
      return RequestError.internalError(
        {
          ...(error.service ? { service: error.service } : {}),
          ...(error.errorName ? { errorName: error.errorName } : {}),
        },
        error.safeMessage,
      )
    case "ACPServerUnavailableError":
      return RequestError.internalError({ errorName: "ServerUnavailable" }, "OpenCode server is unavailable")
  }
  const exhaustive: never = error
  return exhaustive
}

export function fromUnknown(error: unknown) {
  const errorName = error instanceof Error ? error.name : undefined
  return new ServiceFailureError({ safeMessage: "Internal service failure", errorName })
}

export * as ACPError from "./error"

import type { PermissionOption, SessionUpdate } from "@agentclientprotocol/sdk"
import type { OpenCodeClient, OpenCodeEvent } from "@opencode/client/effect"
import { FileDiff } from "@opencode/schema/file-diff"
import type { Permission } from "@opencode/schema/permission"
import type { Session } from "@opencode/schema/session"
import { Patch } from "@opencode/util/patch"
import { applyPatch, parsePatch, reversePatch, structuredPatch, type StructuredPatch } from "diff"
import { Effect, Option, Schema } from "effect"
import { ACPChild } from "./child"
import { ACPClient } from "./client"
import type { ACPConnection } from "./connection"
import {
  absolutePath,
  canonicalName,
  filePath,
  patchHunks,
  pendingToolCall,
  stringValue,
  toLocations,
  type DiffSource,
  type ToolInput,
} from "./tool"

type PermissionEvent = Extract<OpenCodeEvent, { type: "permission.asked" }>
type Tool = { readonly id: string; readonly name: string; readonly input: ToolInput }
type Preview = ReturnType<typeof diff>

type Input = {
  readonly client: OpenCodeClient
  readonly connection: ACPConnection.Interface
  readonly event: PermissionEvent
  readonly sessionID: Session.ID
  readonly clientSessionID: string
  readonly cwd: string
  readonly tool?: Tool
  readonly child?: ACPChild.Session
}

const options: PermissionOption[] = [
  { optionId: "once", kind: "allow_once", name: "Allow once" },
  { optionId: "always", kind: "allow_always", name: "Always allow" },
  { optionId: "reject", kind: "reject_once", name: "Reject" },
]

const decodeFiles = Schema.decodeUnknownOption(Schema.Array(FileDiff.Info))

export const ask = Effect.fnUntraced(function* (input: Input) {
  const toolName = input.tool?.name ?? input.event.data.action
  const toolInput = input.tool?.input ?? input.event.data.metadata ?? {}
  const previews = yield* permissionPreviews(toolName, toolInput, input.event.data.metadata, input.cwd).pipe(
    Effect.orElseSucceed((): Preview[] => []),
  )
  const title = permissionTitle(toolName, toolInput, previews)
  const toolCall = pendingToolCall({
    toolCallId: ACPChild.toolCallID(input.child, input.tool?.id ?? input.event.data.id),
    toolName,
    state: { input: toolInput, title: title ? ACPChild.prefixTitle(input.child, title) : input.child?.title },
    cwd: input.cwd,
  })
  const result = yield* input.connection.requestPermission({
    sessionId: input.clientSessionID,
    toolCall: {
      ...toolCall,
      name: input.tool?.name,
      rawInput: input.tool ? toolCall.rawInput : undefined,
      locations: permissionLocations(toolName, toolInput, input.event.data, input.cwd),
      ...(previews.length > 0 ? { content: previews } : {}),
      ...(input.child ? { _meta: ACPChild.meta(input.child) } : {}),
    },
    options,
  })
  const selected = result.outcome.outcome === "selected" ? result.outcome.optionId : undefined
  return selected === "once" || selected === "always" ? selected : "reject"
})

export function respond(input: Input, decision: Permission.Reply) {
  return input.client.permission.reply({ sessionID: input.sessionID, requestID: input.event.data.id, decision }).pipe(
    Effect.catchTag("PermissionNotFoundError", () => Effect.void),
    Effect.catch(ACPClient.classify),
  )
}

export const withCompletedDiffs = Effect.fnUntraced(function* (
  update: SessionUpdate,
  source: DiffSource | undefined,
  cwd: string,
) {
  if (!source || update.sessionUpdate !== "tool_call_update") return update
  const hunks = canonicalName(source.toolName) === "patch" ? patchHunks(source.input) : []
  const diffs = yield* Effect.forEach(
    Option.getOrElse(decodeFiles(source.metadata?.files), () => []),
    (file) =>
      Effect.gen(function* () {
        const path = absolutePath(file.file, cwd)
        const newText = file.status === "deleted" ? "" : yield* Effect.tryPromise(() => Bun.file(path).text())
        if (file.status === "added") return [diff(path, null, newText)]
        const recorded = parsePatch(file.patch)[0]
        if (!recorded) return []
        const oldText = yield* Effect.try(() => applyPatch(newText, reversePatch(recorded)))
        if (oldText !== false) return [diff(path, oldText, newText)]
        // Core trims indentation from patch-tool diffs, so rebuild those from its hunks and keep them if the ranges agree.
        const hunk = hunks.find(
          (item) => item.type === "update" && absolutePath(item.movePath ?? item.path, cwd) === path,
        )
        if (hunk?.type !== "update" || hunk.chunks.some((chunk) => !chunk.oldLines.length || !chunk.newLines.length))
          return []
        const chunks = hunk.chunks.map((chunk) => ({ ...chunk, oldLines: chunk.newLines, newLines: chunk.oldLines }))
        const rebuilt = (yield* Effect.try(() => Patch.derive(hunk.path, chunks, newText))).content
        return ranges(structuredPatch(path, path, rebuilt, newText)) === ranges(recorded)
          ? [diff(path, rebuilt, newText)]
          : []
      }).pipe(Effect.orElseSucceed((): Preview[] => [])),
    { concurrency: "unbounded" },
  ).pipe(Effect.map((items) => items.flat()))
  return diffs.length === 0 ? update : { ...update, content: [...(update.content ?? []), ...diffs] }
})

function ranges(patch: StructuredPatch) {
  return patch.hunks.map((hunk) => `${hunk.oldStart},${hunk.oldLines},${hunk.newStart},${hunk.newLines}`).join(" ")
}

// Core trims the patch tool's diffs for display, which breaks `applyPatch`, so its previews come from its own hunks.
const permissionPreviews = Effect.fnUntraced(function* (
  toolName: string,
  input: ToolInput,
  metadata: ToolInput | undefined,
  cwd: string,
) {
  if (canonicalName(toolName) === "patch") return yield* patchPreviews(input, cwd)
  const files = Option.getOrElse(decodeFiles(metadata?.files), () => [])
  const previews = yield* Effect.forEach(
    files,
    (file) =>
      Effect.gen(function* () {
        const path = absolutePath(file.file, cwd)
        const oldText = file.status === "added" ? null : yield* Effect.tryPromise(() => Bun.file(path).text())
        const newText = yield* Effect.try(() => applyPatch(oldText ?? "", file.patch))
        return newText === false ? [] : [diff(path, oldText, newText)]
      }),
    { concurrency: "unbounded" },
  )
  return previews.flat()
})

function patchPreviews(input: ToolInput, cwd: string) {
  return Effect.forEach(
    patchHunks(input),
    (hunk) =>
      Effect.gen(function* () {
        const path = absolutePath(hunk.path, cwd)
        if (hunk.type === "add") {
          const newText = hunk.contents.endsWith("\n") || hunk.contents === "" ? hunk.contents : `${hunk.contents}\n`
          return diff(path, null, newText)
        }
        const oldText = yield* Effect.tryPromise(() => Bun.file(path).text())
        if (hunk.type === "delete") return diff(path, oldText, "")
        const derived = yield* Effect.try(() => Patch.derive(hunk.path, hunk.chunks, oldText))
        return diff(hunk.movePath ? absolutePath(hunk.movePath, cwd) : path, oldText, derived.content)
      }),
    { concurrency: "unbounded" },
  )
}

function diff(path: string, oldText: string | null, newText: string) {
  return { type: "diff" as const, path, oldText, newText }
}

function permissionTitle(toolName: string, input: ToolInput, previews: ReadonlyArray<Preview>) {
  if (previews.length > 1) return `${previews.length} files`
  switch (canonicalName(toolName)) {
    case "external_directory":
      return stringValue(input.description) ?? stringValue(input.command) ?? stringValue(input.parentDir)
    case "webfetch":
      return stringValue(input.url)
    case "websearch":
      return stringValue(input.query)
    case "grep":
    case "glob":
      return stringValue(input.pattern)
    case "read":
    case "edit":
    case "write":
    case "patch":
      return filePath(input) ?? previews[0]?.path
    default:
      return undefined
  }
}

function permissionLocations(toolName: string, input: ToolInput, ask: PermissionEvent["data"], cwd: string) {
  const locations = toLocations(toolName, input, cwd)
  if (locations.length > 0 || !PathActions.has(ask.action)) return locations
  const paths = ask.resources.flatMap((resource) => {
    const path = resource.endsWith("/*") ? resource.slice(0, -2) : resource
    return path && !/[*?]/.test(path) ? [absolutePath(path, cwd)] : []
  })
  return Array.from(new Set(paths), (path) => ({ path }))
}

const PathActions = new Set(["read", "edit", "external_directory"])

export * as ACPPermission from "./permission"

import type { ContentBlock } from "@agentclientprotocol/sdk"
import type { Command } from "@opencode/schema/command"
import { SessionMessage } from "@opencode/schema/session-message"
import { Effect } from "effect"
import { access, constants } from "node:fs/promises"
import { fileURLToPath } from "node:url"
import { builtinCommands, type Catalog } from "./catalog"
import { linkReference, promptContentToParts, type PromptPart } from "./content"
import { ACPError } from "./error"
import type { ACPTranslate } from "./translate"

export type Prepared = {
  readonly start: ACPTranslate.TurnStart
  readonly text: string
  readonly files: Array<{ readonly uri: string; readonly name?: string }>
  readonly synthetic: ReadonlyArray<string>
  readonly slash?: { readonly name: string; readonly args: string }
  readonly command?: Command.Info
}

export const prepare = Effect.fnUntraced(function* (catalog: Catalog, content: readonly ContentBlock[]) {
  if (content.some((block) => block.type === "image" && !block.data && !block.uri)) {
    return yield* new ACPError.InvalidRequestError({ message: "image content has no data or uri", field: "prompt" })
  }
  const parts = yield* Effect.forEach(promptContentToParts(content), referenceUnreadableFile, {
    concurrency: "unbounded",
  })
  const visible = parts.filter((part) => part.type !== "text" || (!part.synthetic && !part.ignored))
  const text = visible.flatMap((part) => (part.type === "text" ? [part.text] : [])).join("\n")
  const slash = detectSlashCommand(text)
  const id = SessionMessage.ID.create()
  return {
    start:
      slash && builtinCommands.get(slash.name)?.start === "compaction"
        ? { type: "compaction", id }
        : { type: "input", id },
    text,
    files: visible.flatMap((part) => (part.type === "file" ? [{ uri: part.url, name: part.filename }] : [])),
    synthetic: parts.flatMap((part) => (part.type === "text" && part.synthetic ? [part.text] : [])),
    slash,
    command: slash ? catalog.commands.find((item) => item.name === slash.name) : undefined,
  } satisfies Prepared
})

function referenceUnreadableFile(part: PromptPart) {
  if (part.type !== "file" || !part.url.startsWith("file://")) return Effect.succeed(part)
  return Effect.tryPromise(() => access(fileURLToPath(part.url), constants.R_OK)).pipe(
    Effect.as(part),
    Effect.orElseSucceed(() => linkReference(part.filename, part.url)),
  )
}

function detectSlashCommand(text: string) {
  const value = text.trim()
  if (!value.startsWith("/")) return undefined
  const [name, ...rest] = value.slice(1).split(/\s+/)
  if (!name) return undefined
  return { name, args: rest.join(" ").trim() }
}

export * as ACPPrompt from "./prompt"

import type { SessionUpdate } from "@agentclientprotocol/sdk"
import type { OpenCodeClient } from "@opencode/client/effect"
import type { SessionMessage } from "@opencode/schema/session-message"
import { Effect, Option, Stream } from "effect"
import type { Capabilities } from "./capabilities"
import { ACPClient } from "./client"
import { ACPCompaction } from "./compaction"
import type { ACPConnection } from "./connection"
import { partsToContentChunks } from "./content"
import { ACPPermission } from "./permission"
import type { Attached } from "./sessions"
import { ACPTranslate } from "./translate"
import { completedToolUpdate, errorToolUpdate, pendingToolCall, runningToolUpdate } from "./tool"

export function history(
  client: OpenCodeClient,
  connection: ACPConnection.Interface,
  attached: Attached,
  capabilities: Capabilities,
) {
  return Stream.paginate(undefined, (cursor: string | undefined) =>
    (cursor
      ? client.message.list({ sessionID: attached.id, limit: 200, cursor })
      : client.message.list({ sessionID: attached.id, limit: 200, order: "asc" })
    ).pipe(
      Effect.catch(ACPClient.classify),
      Effect.map((page) => [page.data, Option.fromNullishOr(page.cursor.next)] as const),
    ),
  ).pipe(
    Stream.runForEach((message) =>
      Effect.forEach(
        updates(message, attached.cwd, capabilities),
        (update) =>
          ACPPermission.withCompletedDiffs(update, completedSource(message, update), attached.cwd).pipe(
            Effect.flatMap((enriched) => connection.sessionUpdate({ sessionId: attached.id, update: enriched })),
          ),
        { discard: true },
      ),
    ),
  )
}

export function updates(message: SessionMessage.Info, cwd: string, capabilities: Capabilities): SessionUpdate[] {
  if (message.type === "user")
    return [
      { sessionUpdate: "user_message_chunk", messageId: message.id, content: { type: "text", text: message.text } },
      ...partsToContentChunks(
        (message.files ?? []).map((file) => ({
          type: "file",
          url: file.source.type === "uri" ? file.source.uri : `data:${file.mime};base64,${file.data}`,
          filename: file.name,
          mime: file.mime,
        })),
      ).map((chunk) => ({ sessionUpdate: "user_message_chunk" as const, messageId: message.id, ...chunk })),
    ]
  if (message.type === "compaction") {
    const update = ACPCompaction.replay(message, capabilities.compaction)
    return update ? [update] : []
  }
  if (message.type !== "assistant") return []
  // Live reasoning ordinals count only reasoning parts, not the mixed content array.
  const reasoning = message.content.filter((part) => part.type === "reasoning")
  return message.content.flatMap((part): SessionUpdate[] => {
    if (part.type === "text")
      return [
        { sessionUpdate: "agent_message_chunk", messageId: message.id, content: { type: "text", text: part.text } },
      ]
    if (part.type === "reasoning")
      return [
        {
          sessionUpdate: "agent_thought_chunk",
          messageId: ACPTranslate.reasoningMessageID(message.id, reasoning.indexOf(part)),
          content: { type: "text", text: part.text },
        },
      ]
    const call: SessionUpdate = {
      sessionUpdate: "tool_call",
      ...pendingToolCall({
        toolCallId: part.id,
        toolName: part.name,
        state: { input: part.state.status === "streaming" ? {} : part.state.input },
        cwd,
      }),
    }
    switch (part.state.status) {
      case "completed":
        return [
          call,
          {
            sessionUpdate: "tool_call_update",
            ...completedToolUpdate({
              toolCallId: part.id,
              toolName: part.name,
              input: part.state.input,
              metadata: part.state.metadata,
              content: part.state.content,
              cwd,
            }),
          },
        ]
      case "running":
        return [
          call,
          {
            sessionUpdate: "tool_call_update",
            ...runningToolUpdate({ toolCallId: part.id, toolName: part.name, state: { input: part.state.input }, cwd }),
          },
        ]
      case "error":
        return [
          call,
          {
            sessionUpdate: "tool_call_update",
            ...errorToolUpdate({
              toolCallId: part.id,
              toolName: part.name,
              input: part.state.input,
              metadata: part.state.metadata,
              content: part.state.content,
              error: part.state.error.message,
              cwd,
            }),
          },
        ]
      case "streaming":
        return [call]
    }
  })
}

function completedSource(message: SessionMessage.Info, update: SessionUpdate) {
  if (message.type !== "assistant" || update.sessionUpdate !== "tool_call_update") return undefined
  const part = message.content.find((item) => item.type === "tool" && item.id === update.toolCallId)
  if (part?.type !== "tool" || part.state.status !== "completed") return undefined
  return { toolName: part.name, input: part.state.input, metadata: part.state.metadata }
}

export * as ACPReplay from "./replay"

import type { OpenCodeClient } from "@opencode/client/effect"
import { SessionsCursor } from "@opencode/protocol/groups/session"
import { AbsolutePath } from "@opencode/schema/schema"
import { FSUtil } from "@opencode/util/fs-util"
import { DateTime, Effect, Ref, Schema } from "effect"
import { withTimestampedFallback } from "@opencode/util/session-title-fallback"
import type {
  AuthenticateRequest,
  AuthenticateResponse,
  AuthMethod,
  CancelNotification,
  CloseSessionRequest,
  CloseSessionResponse,
  DeleteSessionRequest,
  DeleteSessionResponse,
  ForkSessionRequest,
  ForkSessionResponse,
  InitializeRequest,
  InitializeResponse,
  ListSessionsRequest,
  ListSessionsResponse,
  LoadSessionRequest,
  LoadSessionResponse,
  McpServer,
  NewSessionRequest,
  NewSessionResponse,
  PromptRequest,
  PromptResponse,
  ResumeSessionRequest,
  ResumeSessionResponse,
  SetSessionConfigOptionRequest,
  SetSessionConfigOptionResponse,
  SetSessionModeRequest,
  SetSessionModeResponse,
} from "@agentclientprotocol/sdk"
import { OPENCODE_VERSION } from "../version"
import { ACPCapabilities, type Capabilities } from "./capabilities"
import type { ACPCatalog } from "./catalog"
import { ACPClient } from "./client"
import { configOptions, resolveChange } from "./config-option"
import type { ACPConnection } from "./connection"
import { ACPDirectories } from "./directories"
import { ACPError } from "./error"
import { ACPReplay } from "./replay"
import type { ACPSessions, Attached, SupportedMcpServer } from "./sessions"
import type { ACPTurn } from "./turn"

const AuthMethodID = "opencode-login"

export interface Interface {
  readonly initialize: (input: InitializeRequest) => Effect.Effect<InitializeResponse>
  readonly authenticate: (input: AuthenticateRequest) => Effect.Effect<AuthenticateResponse, ACPError.Failure>
  readonly newSession: (input: NewSessionRequest) => Effect.Effect<NewSessionResponse, ACPError.Failure>
  readonly loadSession: (input: LoadSessionRequest) => Effect.Effect<LoadSessionResponse, ACPError.Failure>
  readonly listSessions: (input: ListSessionsRequest) => Effect.Effect<ListSessionsResponse, ACPError.Failure>
  readonly deleteSession: (input: DeleteSessionRequest) => Effect.Effect<DeleteSessionResponse, ACPError.Failure>
  readonly resumeSession: (input: ResumeSessionRequest) => Effect.Effect<ResumeSessionResponse, ACPError.Failure>
  readonly closeSession: (input: CloseSessionRequest) => Effect.Effect<CloseSessionResponse, ACPError.Failure>
  readonly forkSession: (input: ForkSessionRequest) => Effect.Effect<ForkSessionResponse, ACPError.Failure>
  readonly setSessionConfigOption: (
    input: SetSessionConfigOptionRequest,
  ) => Effect.Effect<SetSessionConfigOptionResponse, ACPError.Failure>
  readonly setSessionMode: (input: SetSessionModeRequest) => Effect.Effect<SetSessionModeResponse, ACPError.Failure>
  readonly prompt: (input: PromptRequest, signal: AbortSignal) => Effect.Effect<PromptResponse, ACPError.Failure>
  readonly cancel: (input: CancelNotification) => Effect.Effect<void>
}

export function make(input: {
  readonly client: OpenCodeClient
  readonly connection: ACPConnection.Interface
  readonly catalog: ACPCatalog.Interface
  readonly sessions: ACPSessions.Interface
  readonly capabilities: Ref.Ref<Capabilities>
  readonly turn: ACPTurn.Interface
}): Interface {
  const currentOptions = Effect.fnUntraced(function* (attached: Attached) {
    return configOptions(yield* input.catalog.get(attached.cwd), yield* Ref.get(attached.selection))
  })

  const withReload = <A>(attached: Attached, attempt: Effect.Effect<A, ACPError.Failure>) => {
    const retry = () => input.catalog.reload(attached.cwd).pipe(Effect.andThen(attempt))
    return attempt.pipe(
      Effect.catchTags({ ACPInvalidModelError: retry, ACPInvalidModeError: retry, ACPInvalidEffortError: retry }),
    )
  }

  const select = Effect.fnUntraced(function* (attached: Attached, configId: string, value: string) {
    const change = yield* resolveChange(
      yield* input.catalog.get(attached.cwd),
      yield* Ref.get(attached.selection),
      configId,
      value,
    )
    yield* input.sessions.select(attached, change)
  })

  const getSession = Effect.fnUntraced(function* (sessionId: string, cwd: string) {
    const sessionID = yield* ACPClient.decodeSessionID(sessionId)
    const session = yield* input.client.session.get({ sessionID }).pipe(Effect.catch(ACPClient.classify))
    if (FSUtil.resolve(cwd) !== FSUtil.resolve(session.location.directory))
      return yield* new ACPError.SessionDirectoryMismatchError({ sessionId, cwd })
    return session
  })

  return {
    initialize: Effect.fnUntraced(function* (params) {
      yield* Ref.set(input.capabilities, ACPCapabilities.parse(params.clientCapabilities))
      const authMethod: AuthMethod = {
        description: "Run `opencode auth login` in the terminal",
        name: "Login with opencode",
        id: AuthMethodID,
        ...(params.clientCapabilities?.auth?.terminal ? { type: "terminal" as const, args: ["--login"] } : {}),
      }
      if (params.clientCapabilities?._meta?.["terminal-auth"] === true) {
        authMethod._meta = {
          "terminal-auth": { command: "opencode", args: ["auth", "login"], label: "OpenCode Login" },
        }
      }
      return {
        protocolVersion: 1,
        agentCapabilities: {
          loadSession: true,
          mcpCapabilities: { http: true, sse: false },
          promptCapabilities: { embeddedContext: true, image: true },
          sessionCapabilities: { additionalDirectories: {}, close: {}, delete: {}, fork: {}, list: {}, resume: {} },
          _meta: { [ACPCapabilities.ChildSessionUpdates]: true },
        },
        authMethods: [authMethod],
        agentInfo: { name: "OpenCode", version: OPENCODE_VERSION },
      }
    }),
    authenticate: Effect.fnUntraced(function* (params) {
      if (params.methodId !== AuthMethodID)
        return yield* new ACPError.UnknownAuthMethodError({ methodId: params.methodId })
      return {}
    }),
    newSession: Effect.fnUntraced(function* (params) {
      const directories = yield* ACPDirectories.parse(params.cwd, params.additionalDirectories)
      const mcpServers = yield* supportedMcpServers(params.mcpServers)
      // Load first so a catalog failure leaves no session.
      yield* input.catalog.get(params.cwd)
      const created = yield* input.client.session
        .create({ location: { directory: AbsolutePath.make(params.cwd) }, ...ACPDirectories.grant(directories) })
        .pipe(Effect.catch(ACPClient.classify))
      const attachment = yield* input.sessions.attach(created, params.cwd, mcpServers)
      return { sessionId: attachment.attached.id, configOptions: attachment.configOptions }
    }),
    loadSession: Effect.fnUntraced(function* (params) {
      const directories = yield* ACPDirectories.parse(params.cwd, params.additionalDirectories)
      const mcpServers = yield* supportedMcpServers(params.mcpServers)
      const session = yield* getSession(params.sessionId, params.cwd)
      yield* ACPDirectories.activate(input.client, session, directories)
      const attachment = yield* input.sessions.attach(session, session.location.directory, mcpServers)
      return yield* ACPReplay.history(
        input.client,
        input.connection,
        attachment.attached,
        yield* Ref.get(input.capabilities),
      ).pipe(
        Effect.andThen(currentOptions(attachment.attached)),
        Effect.map((configOptions) => ({ configOptions })),
        Effect.onError(() => input.sessions.release(attachment.attached)),
      )
    }),
    listSessions: Effect.fnUntraced(function* (params) {
      const page = yield* input.client.session
        .list({
          ...(params.cwd !== undefined && params.cwd !== null
            ? { directory: yield* ACPDirectories.parseCwd(params.cwd) }
            : {}),
          order: "desc",
          limit: 100,
          ...(params.cursor ? { cursor: Schema.decodeSync(SessionsCursor)(params.cursor) } : {}),
        })
        .pipe(Effect.catch(ACPClient.classify))
      return {
        sessions: page.data.map((session) => {
          const additionalDirectories = ACPDirectories.list(session)
          return {
            sessionId: session.id,
            cwd: session.location.directory,
            ...(additionalDirectories.length > 0 ? { additionalDirectories } : {}),
            title: withTimestampedFallback({
              ...session,
              time: { created: DateTime.toEpochMillis(session.time.created) },
            }),
            updatedAt: DateTime.formatIso(session.time.updated),
          }
        }),
        ...(page.cursor.next ? { nextCursor: page.cursor.next } : {}),
      }
    }),
    deleteSession: Effect.fnUntraced(function* (params) {
      yield* input.turn.cancel({ sessionId: params.sessionId })
      yield* ACPClient.decodeSessionID(params.sessionId).pipe(
        Effect.flatMap((sessionID) => input.client.session.remove({ sessionID })),
        Effect.catchTag(["ACPInvalidRequestError", "SessionNotFoundError"], () => Effect.void),
        Effect.catch(ACPClient.classify),
      )
      yield* input.sessions.detach(params.sessionId)
      return {}
    }),
    resumeSession: Effect.fnUntraced(function* (params) {
      const directories = yield* ACPDirectories.parse(params.cwd, params.additionalDirectories)
      const mcpServers = yield* supportedMcpServers(params.mcpServers)
      const session = yield* getSession(params.sessionId, params.cwd)
      yield* ACPDirectories.activate(input.client, session, directories)
      const attachment = yield* input.sessions.attach(session, session.location.directory, mcpServers)
      return { configOptions: attachment.configOptions }
    }),
    closeSession: Effect.fnUntraced(function* (params) {
      yield* input.turn.close(params.sessionId)
      yield* input.sessions.detach(params.sessionId)
      return {}
    }),
    forkSession: Effect.fnUntraced(function* (params) {
      const directories = yield* ACPDirectories.parse(params.cwd, params.additionalDirectories)
      const mcpServers = yield* supportedMcpServers(params.mcpServers)
      const session = yield* getSession(params.sessionId, params.cwd)
      const forked = yield* input.client.session.fork({ sessionID: session.id }).pipe(Effect.catch(ACPClient.classify))
      // Forks inherit the source's grants; replace them with this request's.
      yield* ACPDirectories.activate(input.client, forked, directories)
      const attachment = yield* input.sessions.attach(forked, forked.location.directory, mcpServers)
      return { sessionId: attachment.attached.id, configOptions: attachment.configOptions }
    }),
    setSessionConfigOption: Effect.fnUntraced(function* (params) {
      const attached = yield* input.sessions.require(params.sessionId)
      const value = params.value
      if (typeof value !== "string") return yield* new ACPError.InvalidConfigOptionError({ configId: params.configId })
      yield* withReload(attached, select(attached, params.configId, value))
      return { configOptions: yield* currentOptions(attached) }
    }),
    setSessionMode: Effect.fnUntraced(function* (params) {
      const attached = yield* input.sessions.require(params.sessionId)
      yield* withReload(attached, select(attached, "mode", params.modeId))
      return {}
    }),
    prompt: input.turn.prompt,
    cancel: input.turn.cancel,
  }
}

const supportedMcpServers = Effect.fnUntraced(function* (servers: readonly McpServer[] = []) {
  const supported = servers.filter(
    (server): server is SupportedMcpServer => !("type" in server) || server.type === "http",
  )
  if (supported.length < servers.length)
    return yield* new ACPError.InvalidRequestError({
      message: "Only stdio and HTTP MCP servers are supported",
      field: "mcpServers",
    })
  return supported
})

export * as ACPService from "./service"

import { isDeepStrictEqual } from "node:util"
import type { McpServer, SessionConfigOption } from "@agentclientprotocol/sdk"
import type { OpenCodeClient, OpenCodeEvent } from "@opencode/client/effect"
import { Mcp } from "@opencode/schema/mcp"
import type { Session } from "@opencode/schema/session"
import { Cause, Deferred, Effect, Exit, Queue, Ref, Scope, Stream } from "effect"
import type { ACPCatalog, Catalog } from "./catalog"
import { ACPClient } from "./client"
import { availableCommands, configOptions, type Change, type Selection } from "./config-option"
import { ACPConnection } from "./connection"
import { ACPError } from "./error"

export type SupportedMcpServer = Exclude<McpServer, { readonly type: "acp" | "sse" }>

export type Attached = {
  readonly id: Session.ID
  readonly cwd: string
  readonly selection: Ref.Ref<Selection>
}

export interface Interface {
  readonly attach: (
    session: Session.Info,
    cwd: string,
    mcpServers: readonly SupportedMcpServer[],
  ) => Effect.Effect<{ readonly attached: Attached; readonly configOptions: SessionConfigOption[] }, ACPError.Failure>
  readonly detach: (sessionID: string) => Effect.Effect<void>
  readonly release: (attached: Attached) => Effect.Effect<void>
  readonly require: (sessionID: string) => Effect.Effect<Attached, ACPError.SessionNotFoundError>
  readonly fork: (attached: Attached, effect: Effect.Effect<void>) => Effect.Effect<void, ACPError.SessionNotFoundError>
  readonly select: (attached: Attached, change: Change) => Effect.Effect<void, ACPError.Error>
}

type Entry = {
  readonly attached: Attached
  readonly scope: Scope.Closeable
  readonly selected: Queue.Queue<Change>
}

type SelectedEvent = Extract<OpenCodeEvent, { type: "session.model.selected" | "session.agent.selected" }>

export const make = Effect.fnUntraced(function* (input: {
  readonly client: OpenCodeClient
  readonly connection: ACPConnection.Interface
  readonly catalog: ACPCatalog.Interface
}) {
  const scope = yield* Effect.scope
  const sessions = new Map<string, Entry>()
  // Outlives entries so re-attaching does not re-add servers.
  const registeredMcpBySession = new Map<string, Map<string, Mcp.ServerConfig>>()
  const connected = yield* Deferred.make<void>()

  // Subscribe before any attach so a switch right after `sessions.set` reaches the session.
  yield* input.client.event.subscribe().pipe(
    Stream.tap((event) => (event.type === "server.connected" ? Deferred.succeed(connected, undefined) : Effect.void)),
    Stream.filter(
      (event): event is SelectedEvent =>
        event.type === "session.model.selected" || event.type === "session.agent.selected",
    ),
    Stream.runForEach((event) => {
      const entry = sessions.get(event.data.sessionID)
      if (!entry) return Effect.void
      return Queue.offer(
        entry.selected,
        event.type === "session.model.selected" ? { model: event.data.model } : { modeID: event.data.agent },
      )
    }),
    Effect.catchCause((cause) =>
      Cause.hasInterruptsOnly(cause) ? Effect.void : Effect.logWarning("ACP selection event stream failed", cause),
    ),
    Effect.ensuring(Deferred.succeed(connected, undefined)),
    Effect.forkScoped,
  )

  const sendCommands = (sessionID: string, catalog: Catalog) =>
    input.connection.sessionUpdate({
      sessionId: sessionID,
      update: { sessionUpdate: "available_commands_update", availableCommands: availableCommands(catalog) },
    })

  const changed = Effect.fnUntraced(function* (attached: Attached, previous: Catalog, next: Catalog, patch: Selection) {
    const selection = yield* Ref.getAndUpdate(attached.selection, (current) => ({ ...current, ...patch }))
    const options = configOptions(next, { ...selection, ...patch })
    if (!isDeepStrictEqual(options, configOptions(previous, selection))) {
      yield* input.connection.sessionUpdate({
        sessionId: attached.id,
        update: { sessionUpdate: "config_option_update", configOptions: options },
      })
    }
    if (!isDeepStrictEqual(next.commands, previous.commands)) yield* sendCommands(attached.id, next)
  })

  const registerMcp = (attached: Attached, servers: readonly SupportedMcpServer[]) =>
    Effect.suspend(() => {
      const registered = registeredMcpBySession.get(attached.id) ?? new Map<string, Mcp.ServerConfig>()
      registeredMcpBySession.set(attached.id, registered)
      return Effect.forEach(
        servers,
        (server) =>
          Effect.suspend(() => {
            const config = mcpConfig(server)
            if (isDeepStrictEqual(registered.get(server.name), config)) return Effect.void
            registered.set(server.name, config)
            return input.client.mcp.add({ server: server.name, location: { directory: attached.cwd }, config }).pipe(
              Effect.catch(ACPClient.classify),
              Effect.onError(() => Effect.sync(() => registered.delete(server.name))),
              Effect.uninterruptible,
            )
          }),
        { concurrency: "unbounded", discard: true },
      )
    })

  const remove = (sessionID: string, entry: Entry) =>
    Effect.suspend(() => {
      if (sessions.get(sessionID) === entry) {
        sessions.delete(sessionID)
        registeredMcpBySession.delete(sessionID)
      }
      return Scope.close(entry.scope, Exit.void)
    })

  return {
    attach: Effect.fn("cli.acp.sessions.attach")(function* (session, cwd, mcpServers) {
      yield* Deferred.await(connected)
      const current = yield* input.catalog.get(cwd)
      const entry: Entry = {
        attached: {
          id: session.id,
          cwd,
          selection: yield* Ref.make<Selection>({ model: session.model, modeID: session.agent }),
        },
        scope: Scope.forkUnsafe(scope),
        selected: yield* Queue.unbounded<Change>(),
      }
      // Swap synchronously so concurrent attaches of one ID cannot both keep a scope.
      const replaced = sessions.get(session.id)
      sessions.set(session.id, entry)
      if (replaced) yield* Scope.close(replaced.scope, Exit.void)
      yield* registerMcp(entry.attached, mcpServers).pipe(Effect.onError(() => remove(session.id, entry)))
      const responded = yield* ACPConnection.Responded
      // `changes` replays the latest catalog, so a reload since `current` still pushes.
      // One fold keeps catalog and selection consistent.
      yield* Effect.gen(function* () {
        yield* responded
        yield* sendCommands(session.id, current)
        yield* Stream.merge(
          input.catalog.changes(cwd).pipe(Stream.map((catalog) => ({ catalog, patch: {} }))),
          Stream.fromQueue(entry.selected).pipe(Stream.map((patch) => ({ catalog: undefined, patch }))),
        ).pipe(
          Stream.runFoldEffect(
            () => current,
            (previous, step) => {
              const next = step.catalog ?? previous
              return changed(entry.attached, previous, next, step.patch).pipe(Effect.ignore, Effect.as(next))
            },
          ),
        )
      }).pipe(Effect.ignore, Effect.forkIn(entry.scope))
      return {
        attached: entry.attached,
        configOptions: configOptions(current, yield* Ref.get(entry.attached.selection)),
      }
    }),
    detach: Effect.fn("cli.acp.sessions.detach")(function* (sessionID) {
      const entry = sessions.get(sessionID)
      if (entry) yield* remove(sessionID, entry)
    }),
    release: Effect.fn("cli.acp.sessions.release")(function* (attached) {
      const entry = sessions.get(attached.id)
      if (entry?.attached === attached) yield* remove(attached.id, entry)
    }),
    require: Effect.fnUntraced(function* (sessionID) {
      const entry = sessions.get(sessionID)
      if (!entry) return yield* new ACPError.SessionNotFoundError({ sessionId: sessionID })
      return entry.attached
    }),
    fork: Effect.fn("cli.acp.sessions.fork")(function* (attached, effect) {
      const entry = sessions.get(attached.id)
      if (entry?.attached !== attached) return yield* new ACPError.SessionNotFoundError({ sessionId: attached.id })
      yield* Effect.forkIn(effect, entry.scope, { startImmediately: true })
    }),
    // Update selection before switching so the echoed event is a no-op.
    select: Effect.fnUntraced(function* (attached, change) {
      yield* Ref.update(attached.selection, (selection) => ({ ...selection, ...change }))
      yield* (
        "model" in change
          ? input.client.session.switchModel({ sessionID: attached.id, model: change.model })
          : input.client.session.switchAgent({ sessionID: attached.id, agent: change.modeID })
      ).pipe(Effect.catch(ACPClient.classify))
    }),
  } satisfies Interface
})

function mcpConfig(server: SupportedMcpServer) {
  if ("type" in server) {
    return new Mcp.RemoteConfig({
      type: "remote",
      url: server.url,
      headers: Object.fromEntries(server.headers.map((header) => [header.name, header.value])),
      oauth: false,
    })
  }
  return new Mcp.LocalConfig({
    type: "local",
    command: [server.command, ...server.args],
    environment: Object.fromEntries(server.env.map((entry) => [entry.name, entry.value])),
  })
}

export * as ACPSessions from "./sessions"

import { isAbsolute, resolve } from "node:path"
import type { ToolCall, ToolCallContent, ToolCallLocation, ToolCallUpdate, ToolKind } from "@agentclientprotocol/sdk"
import type { Tool } from "@opencode/schema/tool"
import { readDisplayText } from "@opencode/tui/mini/tool"
import { Patch } from "@opencode/util/patch"
import { Result } from "effect"

export type ToolInput = Record<string, unknown>

export type DiffSource = {
  readonly toolName: string
  readonly input: ToolInput
  readonly metadata?: Readonly<Record<string, unknown>>
}

function toToolKind(toolName: string): ToolKind {
  switch (canonicalName(toolName)) {
    case "shell":
      return "execute"
    case "webfetch":
      return "fetch"
    case "edit":
    case "patch":
    case "write":
      return "edit"
    case "grep":
    case "glob":
    case "context":
    case "context7_resolve_library_id":
    case "context7_get_library_docs":
      return "search"
    case "read":
      return "read"
    case "subagent":
      return "think"
    default:
      return "other"
  }
}

export function toLocations(toolName: string, input: ToolInput, cwd: string): ToolCallLocation[] {
  switch (canonicalName(toolName)) {
    case "shell":
      return locationFrom(cwd, stringValue(input.workdir) ?? stringValue(input.cwd) ?? cwd)
    case "read":
    case "edit":
    case "write":
      return locationFrom(cwd, filePath(input))
    case "patch":
      return locationFrom(
        cwd,
        ...patchHunks(input).flatMap((hunk) => [hunk.path, hunk.type === "update" ? hunk.movePath : undefined]),
      )
    case "external_directory":
      return locationFrom(cwd, input.filepath)
    case "grep":
    case "glob":
    case "context":
    case "context7_resolve_library_id":
    case "context7_get_library_docs":
      return locationFrom(cwd, input.path)
    default:
      return []
  }
}

export function pendingToolCall(input: {
  readonly toolCallId: string
  readonly toolName: string
  readonly state: { readonly input: ToolInput; readonly title?: string }
  readonly cwd: string
}): ToolCall {
  return {
    toolCallId: input.toolCallId,
    name: input.toolName,
    title: toolTitle(input.toolName, input.state.input, input.state.title),
    kind: toToolKind(input.toolName),
    status: "pending",
    locations: toLocations(input.toolName, input.state.input, input.cwd),
    rawInput: rawInput(input.toolName, input.state.input, input.cwd),
  }
}

export function runningToolUpdate(input: {
  readonly toolCallId: string
  readonly toolName: string
  readonly state: { readonly input: ToolInput }
  readonly cwd: string
}): ToolCallUpdate {
  return {
    toolCallId: input.toolCallId,
    status: "in_progress",
    kind: toToolKind(input.toolName),
    title: toolTitle(input.toolName, input.state.input),
    locations: toLocations(input.toolName, input.state.input, input.cwd),
    rawInput: rawInput(input.toolName, input.state.input, input.cwd),
  }
}

export function completedToolUpdate(input: {
  readonly toolCallId: string
  readonly toolName: string
  readonly input: ToolInput
  readonly content: ReadonlyArray<Tool.Content>
  readonly metadata?: Readonly<Record<string, unknown>>
  readonly cwd: string
}): ToolCallUpdate {
  const normalized = toolContent(input.content)
  const firstText = input.content.find((part) => part.type === "text")
  const read = canonicalName(input.toolName) === "read" && firstText ? readDisplayText(firstText.text) : undefined
  const images = normalized.filter((part) => part.type === "content" && part.content.type === "image")
  const primary =
    read === undefined
      ? normalized.filter((part) => !images.includes(part))
      : [{ type: "content" as const, content: { type: "text" as const, text: read } }]
  return {
    toolCallId: input.toolCallId,
    status: "completed",
    locations: toLocations(input.toolName, input.input, input.cwd),
    content: [...primary, ...images],
    rawOutput: {
      ...(input.metadata === undefined ? {} : { metadata: input.metadata }),
    },
  }
}

export function errorToolUpdate(input: {
  readonly toolCallId: string
  readonly toolName: string
  readonly input: ToolInput
  readonly content?: ReadonlyArray<Tool.Content>
  readonly metadata?: Readonly<Record<string, unknown>>
  readonly error: string
  readonly cwd: string
}): ToolCallUpdate {
  return {
    toolCallId: input.toolCallId,
    status: "failed",
    kind: toToolKind(input.toolName),
    title: toolTitle(input.toolName, input.input),
    locations: toLocations(input.toolName, input.input, input.cwd),
    rawInput: rawInput(input.toolName, input.input, input.cwd),
    content: [...toolContent(input.content ?? []), { type: "content", content: { type: "text", text: input.error } }],
    rawOutput: {
      ...(input.metadata === undefined ? {} : { metadata: input.metadata }),
      error: input.error,
    },
  }
}

function toolContent(content: ReadonlyArray<Tool.Content>): ToolCallContent[] {
  return content.flatMap((part): ToolCallContent[] => {
    if (part.type === "text") return [{ type: "content", content: { type: "text", text: part.text } }]
    const match = /^data:([^;,]+)(?:;[^,]*)*;base64,(.*)$/.exec(part.uri)
    if (!match?.[1]?.startsWith("image/") || match[2] === undefined) return []
    return [{ type: "content", content: { type: "image", mimeType: match[1], data: match[2] } }]
  })
}

function toolTitle(toolName: string, input: ToolInput, fallback?: string) {
  if (isShell(toolName)) return stringValue(input.command) ?? stringValue(input.cmd) ?? fallback ?? toolName
  return fallback || toolName
}

function rawInput(toolName: string, input: ToolInput, cwd: string): ToolInput {
  if (!isShell(toolName) || input.cwd || input.workdir) return input
  return { ...input, cwd }
}

function isShell(toolName: string) {
  return canonicalName(toolName) === "shell"
}

function locationFrom(cwd: string, ...values: unknown[]): ToolCallLocation[] {
  return Array.from(
    new Set(values.flatMap((value) => (typeof value === "string" && value ? [absolutePath(value, cwd)] : []))),
    (path) => ({ path }),
  )
}

const V1Aliases = new Map([
  ["bash", "shell"],
  ["task", "subagent"],
  ["apply_patch", "patch"],
])

export function canonicalName(toolName: string) {
  const name = toolName.toLocaleLowerCase()
  return V1Aliases.get(name) ?? name
}

// Sessions migrated from V1 keep their original `filePath` tool inputs.
export function filePath(input: ToolInput) {
  return stringValue(input.path) ?? stringValue(input.filePath)
}

export function patchHunks(input: ToolInput) {
  const patchText = stringValue(input.patchText)
  if (!patchText) return []
  const parsed = Patch.parse(patchText)
  return Result.isSuccess(parsed) ? parsed.success : []
}

export function absolutePath(path: string, cwd: string) {
  return isAbsolute(path) ? path : resolve(cwd, path)
}

export function stringValue(value: unknown) {
  return typeof value === "string" ? value : undefined
}

import type { PromptResponse, SessionUpdate } from "@agentclientprotocol/sdk"
import type { OpenCodeEvent } from "@opencode/client/effect"
import type { Session } from "@opencode/schema/session"
import type { SessionError } from "@opencode/schema/session-error"
import type { SessionMessage } from "@opencode/schema/session-message"
import { TokenUsage } from "@opencode/schema/token-usage"
import { ACPChild } from "./child"
import { ACPCompaction } from "./compaction"
import { ACPError } from "./error"
import {
  completedToolUpdate,
  errorToolUpdate,
  pendingToolCall,
  runningToolUpdate,
  type DiffSource,
  type ToolInput,
} from "./tool"

const RetryMeta = "opencode/retry"

export type TurnStart = { readonly type: "input" | "compaction"; readonly id: SessionMessage.ID }

export type Terminal = "succeeded" | "failed" | "interrupted"

export type TurnContext = {
  readonly sessionID: Session.ID
  readonly cwd: string
  readonly start: TurnStart
  readonly childUpdates: boolean
  readonly compaction: boolean
}

type Tool = {
  readonly sessionID: string
  readonly id: string
  readonly name: string
  readonly input: ToolInput
  readonly metadata: Record<string, unknown>
}

type RetryStatus = {
  readonly attempt: number
  readonly nextRetryAt: string
  readonly error: SessionError.Error
}

export type TurnState = {
  readonly started: boolean
  readonly tools: ReadonlyMap<string, Tool>
  readonly retries: ReadonlyMap<string, RetryStatus>
  readonly compactions: ACPCompaction.Tracked
  readonly children: ReadonlyMap<string, ACPChild.Session>
  readonly openChildren: ReadonlySet<string>
  readonly asks: ReadonlySet<string>
  readonly finish?: SessionMessage.Assistant["finish"]
  readonly usage?: { readonly turn: TokenUsage.Info; readonly last: TokenUsage.Info }
  readonly stepError?: SessionError.Error
  readonly executionError?: { readonly type: string; readonly message: string }
}

type PermissionEvent = Extract<OpenCodeEvent, { type: "permission.asked" }>
type FormEvent = Extract<OpenCodeEvent, { type: "form.created" }>
type CreatedEvent = Extract<OpenCodeEvent, { type: "session.created" }>

export type Output =
  | { readonly _tag: "SessionUpdate"; readonly update: SessionUpdate; readonly diff?: DiffSource }
  | { readonly _tag: "ChildUpdate"; readonly update: ACPChild.Update; readonly diff?: DiffSource }
  | {
      readonly _tag: "PermissionAsk"
      readonly event: PermissionEvent
      readonly tool?: Tool
      readonly child?: ACPChild.Session
    }
  | { readonly _tag: "FormAsk"; readonly form: FormEvent["data"]["form"]; readonly child?: ACPChild.Session }
  | { readonly _tag: "AskSettled"; readonly id: string }

export type Folded = {
  readonly state: TurnState
  readonly outputs: ReadonlyArray<Output>
  readonly terminal?: Terminal
}

export const initial: TurnState = {
  started: false,
  tools: new Map(),
  retries: new Map(),
  compactions: new Map(),
  children: new Map(),
  openChildren: new Set(),
  asks: new Set(),
}

export function fold(state: TurnState, event: OpenCodeEvent, ctx: TurnContext): Folded {
  if (event.type === "session.created") return childCreated(state, event, ctx)

  const sessionID = sessionIDFromEvent(event)
  const child = sessionID ? state.children.get(sessionID) : undefined

  if (event.type === "permission.asked" && (event.data.sessionID === ctx.sessionID || child)) {
    const tool = event.data.source?.id
      ? state.tools.get(toolKey(event.data.sessionID, event.data.source.id))
      : undefined
    return {
      state: { ...state, asks: new Set(state.asks).add(event.data.id) },
      outputs: [{ _tag: "PermissionAsk", event, tool, child }],
    }
  }
  if (event.type === "form.created" && (event.data.form.sessionID === ctx.sessionID || child)) {
    return {
      state: { ...state, asks: new Set(state.asks).add(event.data.form.id) },
      outputs: [{ _tag: "FormAsk", form: event.data.form, child }],
    }
  }
  const settledID =
    event.type === "permission.replied"
      ? event.data.requestID
      : event.type === "form.replied" || event.type === "form.cancelled"
        ? event.data.id
        : undefined
  if (settledID && state.asks.has(settledID)) {
    const asks = new Set(state.asks)
    asks.delete(settledID)
    return { state: { ...state, asks }, outputs: [{ _tag: "AskSettled", id: settledID }] }
  }
  if (!sessionID || (sessionID !== ctx.sessionID && !child)) return { state, outputs: [] }
  if (event.type === "session.inbox.delivered" && event.data.inboxID === ctx.start.id)
    return { state: { ...state, started: true }, outputs: [] }
  if (!state.started) return { state, outputs: [] }
  return child ? childEvent(state, event, ctx, child) : rootEvent(state, event, ctx)
}

export function fromTrackedChild(state: TurnState, event: OpenCodeEvent) {
  const sessionID = event.type === "session.created" ? event.data.parentID : sessionIDFromEvent(event)
  return sessionID !== undefined && state.children.has(sessionID)
}

export function failure(state: TurnState) {
  const error = state.stepError ?? state.executionError
  if (error?.type === "provider.auth") return new ACPError.AuthRequiredError()
  if (error && error.type !== "aborted" && error.type !== "provider.content-filter") {
    return new ACPError.ServiceFailureError({
      safeMessage: error.message || "OpenCode prompt failed",
      service: "session",
      errorName: error.type,
    })
  }
  return undefined
}

export function response(state: TurnState, sessionID: string, terminal: Terminal): PromptResponse {
  const tokens = state.usage?.turn
  const usage = tokens
    ? {
        inputTokens: tokens.input,
        outputTokens: tokens.output,
        totalTokens: TokenUsage.total(tokens),
        ...(tokens.reasoning > 0 ? { thoughtTokens: tokens.reasoning } : {}),
        ...(tokens.cache.read > 0 ? { cachedReadTokens: tokens.cache.read } : {}),
        ...(tokens.cache.write > 0 ? { cachedWriteTokens: tokens.cache.write } : {}),
      }
    : undefined
  const error = (state.stepError ?? state.executionError)?.type
  const stopReason = resolveStopReason({ terminal, finish: state.finish, error })
  // Interruption clears the projected retry, so a retry pending at interrupt is reported here.
  const retry = state.retries.get(sessionID)
  return { stopReason, ...(usage ? { usage } : {}), _meta: retry ? { [RetryMeta]: retry } : {} }
}

// Child compactions are left to the background consumer.
export function abandon(state: TurnState, ctx: TurnContext): Folded {
  const compaction = state.compactions.get(ctx.sessionID)
  return {
    state: { ...state, tools: new Map(), compactions: without(state.compactions, ctx.sessionID) },
    outputs: [
      ...[...state.tools.values()].flatMap((tool) =>
        route(ctx, state.children.get(tool.sessionID), {
          sessionUpdate: "tool_call_update",
          ...errorToolUpdate({
            toolCallId: tool.id,
            toolName: tool.name,
            input: tool.input,
            metadata: tool.metadata,
            content: [],
            error: "Cancelled",
            cwd: ctx.cwd,
          }),
        }),
      ),
      ...(compaction
        ? route(ctx, undefined, ACPCompaction.abandon(compaction, ACPCompaction.usesStandardUpdates(ctx, false)))
        : []),
    ],
  }
}

export function reasoningMessageID(messageID: string, ordinal: number) {
  return `${messageID}:reasoning:${ordinal}`
}

function childCreated(state: TurnState, event: CreatedEvent, ctx: TurnContext): Folded {
  const parentID = event.data.parentID
  if (!parentID) return { state, outputs: [] }
  const parent = parentID === ctx.sessionID ? undefined : state.children.get(parentID)
  if (!parent && parentID !== ctx.sessionID) return { state, outputs: [] }
  const child = { id: event.data.sessionID, parentID, depth: parent ? parent.depth + 1 : 1, title: event.data.title }
  return {
    state: {
      ...state,
      children: new Map(state.children).set(child.id, child),
      openChildren: new Set(state.openChildren).add(child.id),
    },
    outputs: childStatus(ctx, child, { type: "status", status: "created" }),
  }
}

function rootEvent(state: TurnState, event: OpenCodeEvent, ctx: TurnContext): Folded {
  switch (event.type) {
    case "session.step.started":
      return sessionEvent({ ...state, stepError: undefined }, event, ctx, undefined)
    case "session.step.ended":
      return { state: { ...recordStep(state, event.data.tokens), finish: event.data.finish }, outputs: [] }
    case "session.step.failed": {
      const recorded = event.data.tokens ? recordStep(state, event.data.tokens) : state
      return { state: { ...recorded, stepError: event.data.error }, outputs: [] }
    }
    case "session.execution.succeeded":
      return { state, outputs: [], terminal: "succeeded" }
    case "session.execution.interrupted":
      return { state, outputs: [], terminal: "interrupted" }
    case "session.execution.failed":
      return { state: { ...state, executionError: event.data.error }, outputs: [], terminal: "failed" }
    default:
      return sessionEvent(state, event, ctx, undefined)
  }
}

function childEvent(state: TurnState, event: OpenCodeEvent, ctx: TurnContext, child: ACPChild.Session): Folded {
  switch (event.type) {
    case "session.execution.started":
      return { state, outputs: childStatus(ctx, child, { type: "status", status: "running" }) }
    case "session.execution.succeeded":
      return childEnded(state, ctx, child, { type: "status", status: "completed" })
    case "session.execution.interrupted":
      return childEnded(state, ctx, child, { type: "status", status: "interrupted" })
    case "session.execution.failed":
      return childEnded(state, ctx, child, { type: "status", status: "failed", error: event.data.error })
    default:
      return sessionEvent(state, event, ctx, child)
  }
}

function sessionEvent(
  state: TurnState,
  event: OpenCodeEvent,
  ctx: TurnContext,
  child: ACPChild.Session | undefined,
): Folded {
  const sessionID = child?.id ?? ctx.sessionID
  const send = (update: SessionUpdate) => route(ctx, child, update)
  switch (event.type) {
    case "session.step.started":
      if (!state.retries.has(sessionID)) return { state, outputs: [] }
      return {
        state: { ...state, retries: without(state.retries, sessionID) },
        outputs: send({ sessionUpdate: "session_info_update", _meta: { [RetryMeta]: null } }),
      }
    case "session.retry.scheduled": {
      const retry = {
        attempt: event.data.attempt,
        nextRetryAt: new Date(event.data.at).toISOString(),
        error: event.data.error,
      }
      return {
        state: { ...state, retries: new Map(state.retries).set(sessionID, retry) },
        outputs: send({ sessionUpdate: "session_info_update", _meta: { [RetryMeta]: retry } }),
      }
    }
    case "session.compaction.started":
    case "session.compaction.ended":
    case "session.compaction.failed": {
      const applied = ACPCompaction.apply(
        event,
        state.compactions,
        ACPCompaction.usesStandardUpdates(ctx, child !== undefined),
      )
      return { state: { ...state, compactions: applied.tracked }, outputs: applied.updates.flatMap(send) }
    }
    case "session.compaction.delta": {
      const update = ACPCompaction.chunk(
        state.compactions.get(sessionID),
        event.data.text,
        ACPCompaction.usesStandardUpdates(ctx, child !== undefined),
      )
      return { state, outputs: update ? send(update) : [] }
    }
    case "session.text.delta":
      return {
        state,
        outputs: send({
          sessionUpdate: "agent_message_chunk",
          messageId: event.data.assistantMessageID,
          content: { type: "text", text: event.data.delta },
        }),
      }
    case "session.reasoning.delta":
      return {
        state,
        outputs: send({
          sessionUpdate: "agent_thought_chunk",
          messageId: reasoningMessageID(event.data.assistantMessageID, event.data.ordinal),
          content: { type: "text", text: event.data.delta },
        }),
      }
    case "session.tool.input.started":
      return {
        state: {
          ...state,
          tools: new Map(state.tools).set(
            toolKey(event.data.sessionID, event.data.id),
            newTool(event.data.sessionID, event.data.id, event.data.name),
          ),
        },
        outputs: send({
          sessionUpdate: "tool_call",
          ...pendingToolCall({
            toolCallId: event.data.id,
            toolName: event.data.name,
            state: { input: {} },
            cwd: ctx.cwd,
          }),
        }),
      }
    case "session.tool.called": {
      const key = toolKey(event.data.sessionID, event.data.id)
      const tool = {
        ...(state.tools.get(key) ?? newTool(event.data.sessionID, event.data.id)),
        input: event.data.input,
      }
      return {
        state: { ...state, tools: new Map(state.tools).set(key, tool) },
        outputs: send({
          sessionUpdate: "tool_call_update",
          ...runningToolUpdate({
            toolCallId: event.data.id,
            toolName: tool.name,
            state: { input: tool.input },
            cwd: ctx.cwd,
          }),
        }),
      }
    }
    case "session.tool.progress": {
      const key = toolKey(event.data.sessionID, event.data.id)
      const current = state.tools.get(key)
      if (!current) return { state, outputs: [] }
      return {
        state: { ...state, tools: new Map(state.tools).set(key, { ...current, metadata: event.data.metadata }) },
        outputs: send({
          sessionUpdate: "tool_call_update",
          ...runningToolUpdate({
            toolCallId: event.data.id,
            toolName: current.name,
            state: { input: current.input },
            cwd: ctx.cwd,
          }),
        }),
      }
    }
    case "session.tool.success": {
      const key = toolKey(event.data.sessionID, event.data.id)
      const tool = state.tools.get(key) ?? newTool(event.data.sessionID, event.data.id)
      return {
        state: { ...state, tools: without(state.tools, key) },
        outputs: send({
          sessionUpdate: "tool_call_update",
          ...completedToolUpdate({
            toolCallId: event.data.id,
            toolName: tool.name,
            input: tool.input,
            metadata: event.data.metadata,
            content: event.data.content,
            cwd: ctx.cwd,
          }),
        }).map((output) => ({
          ...output,
          diff: { toolName: tool.name, input: tool.input, metadata: event.data.metadata },
        })),
      }
    }
    case "session.tool.failed": {
      const key = toolKey(event.data.sessionID, event.data.id)
      const tool = state.tools.get(key) ?? newTool(event.data.sessionID, event.data.id)
      return {
        state: { ...state, tools: without(state.tools, key) },
        outputs: send({
          sessionUpdate: "tool_call_update",
          ...errorToolUpdate({
            toolCallId: event.data.id,
            toolName: tool.name,
            input: tool.input,
            metadata: event.data.metadata ?? tool.metadata,
            content: event.data.content ?? [],
            error: event.data.error.message,
            cwd: ctx.cwd,
          }),
        }),
      }
    }
    default:
      return { state, outputs: [] }
  }
}

function newTool(sessionID: string, id: string, name = "tool"): Tool {
  return { sessionID, id, name, input: {}, metadata: {} }
}

function route(ctx: TurnContext, child: ACPChild.Session | undefined, update: SessionUpdate): Output[] {
  if (!child) return [{ _tag: "SessionUpdate", update }]
  const projected = ACPChild.project(update, child)
  if (ctx.childUpdates) return childStatus(ctx, child, { type: "update", update: projected })
  return [{ _tag: "SessionUpdate", update: projected }]
}

function childStatus(ctx: TurnContext, child: ACPChild.Session, event: ACPChild.Event): Output[] {
  if (!ctx.childUpdates) return []
  return [{ _tag: "ChildUpdate", update: ACPChild.update(ctx.sessionID, child, event) }]
}

function childEnded(state: TurnState, ctx: TurnContext, child: ACPChild.Session, status: ACPChild.Event): Folded {
  const openChildren = new Set(state.openChildren)
  openChildren.delete(child.id)
  return { state: { ...state, openChildren }, outputs: childStatus(ctx, child, status) }
}

function recordStep(state: TurnState, tokens: TokenUsage.Info): TurnState {
  const turn = state.usage?.turn
  return {
    ...state,
    usage: {
      turn: turn
        ? {
            input: turn.input + tokens.input,
            output: turn.output + tokens.output,
            reasoning: turn.reasoning + tokens.reasoning,
            cache: { read: turn.cache.read + tokens.cache.read, write: turn.cache.write + tokens.cache.write },
          }
        : tokens,
      last: tokens,
    },
  }
}

function without<K, V>(map: ReadonlyMap<K, V>, key: K) {
  const next = new Map(map)
  next.delete(key)
  return next
}

function sessionIDFromEvent(event: OpenCodeEvent) {
  if ("sessionID" in event.data && typeof event.data.sessionID === "string") return event.data.sessionID
  if (event.type === "form.created") return event.data.form.sessionID
  return undefined
}

function toolKey(sessionID: string, id: string) {
  return `${sessionID}:${id}`
}

function resolveStopReason(input: {
  readonly terminal: Terminal
  readonly finish: SessionMessage.Assistant["finish"]
  readonly error?: string
}): PromptResponse["stopReason"] {
  if (input.terminal === "interrupted" || input.error === "aborted") return "cancelled"
  if (input.finish === "length") return "max_tokens"
  if (input.finish === "content-filter" || input.error === "provider.content-filter") return "refusal"
  return "end_turn"
}

export * as ACPTranslate from "./translate"

import type { CancelNotification, PromptRequest, PromptResponse, RequestError } from "@agentclientprotocol/sdk"
import type { OpenCodeClient, OpenCodeEvent } from "@opencode/client/effect"
import { TokenUsage } from "@opencode/schema/token-usage"
import {
  Cause,
  Context,
  Deferred,
  Duration,
  Effect,
  Exit,
  Fiber,
  FiberMap,
  Option,
  Queue,
  Ref,
  Scope,
  Stream,
} from "effect"
import type { Capabilities } from "./capabilities"
import { findModel, type ACPCatalog } from "./catalog"
import { ACPChild } from "./child"
import { ACPClient } from "./client"
import { currentModel } from "./config-option"
import type { ACPConnection } from "./connection"
import { ACPElicitation } from "./elicitation"
import { ACPError } from "./error"
import { ACPPermission } from "./permission"
import { ACPPrompt } from "./prompt"
import type { ACPSessions, Attached } from "./sessions"
import { ACPTranslate } from "./translate"

export interface Interface {
  readonly prompt: (input: PromptRequest, signal: AbortSignal) => Effect.Effect<PromptResponse, ACPError.Failure>
  readonly cancel: (input: CancelNotification) => Effect.Effect<void>
  /** Unlike `cancel`, interrupts an idle session too, since server work can outlive its turn. */
  readonly close: (sessionID: string) => Effect.Effect<void, ACPError.Error | RequestError>
}

/** Core acknowledges an interrupt before its cleanup settles, and its shell tool waits 3s before SIGKILL. */
export const CancelDrainTimeout = Context.Reference<Duration.Input>("@opencode/cli/acp/Turn/CancelDrainTimeout", {
  defaultValue: () => "5 seconds",
})

type Subscription = {
  readonly scope: Scope.Closeable
  readonly events: Queue.Dequeue<OpenCodeEvent, unknown>
  readonly askQueue: Queue.Queue<Effect.Effect<void, ACPError.Error | RequestError>>
  readonly settled: Map<string, Deferred.Deferred<void>>
}

type Turn = {
  readonly ctx: ACPTranslate.TurnContext
  readonly state: Ref.Ref<ACPTranslate.TurnState>
  readonly subscription: Subscription
  readonly cancelled: Deferred.Deferred<void>
  readonly background: boolean
}

export const make = Effect.fnUntraced(function* (input: {
  readonly client: OpenCodeClient
  readonly connection: ACPConnection.Interface
  readonly sessions: ACPSessions.Interface
  readonly catalog: ACPCatalog.Interface
  readonly capabilities: Ref.Ref<Capabilities>
}) {
  const scope = yield* Effect.scope
  const drainTimeout = yield* CancelDrainTimeout
  const turns = yield* FiberMap.make<string, PromptResponse, ACPError.Failure>()

  const open = Effect.fnUntraced(function* (ctx: ACPTranslate.TurnContext, state: Ref.Ref<ACPTranslate.TurnState>) {
    // Parented to the service scope; the session scope may already be closed.
    const subscriptionScope = yield* Scope.fork(scope)
    const subscription: Subscription = {
      scope: subscriptionScope,
      events: yield* input.client.event
        .subscribe()
        .pipe(Stream.toQueue({ capacity: "unbounded" }), Scope.provide(subscriptionScope)),
      askQueue: yield* Queue.unbounded<Effect.Effect<void, ACPError.Error | RequestError>>(),
      settled: new Map(),
    }
    yield* Queue.take(subscription.askQueue).pipe(
      Effect.flatten,
      Effect.catchCause((cause) =>
        Cause.hasInterruptsOnly(cause) ? Effect.void : Effect.logWarning("ACP ask reply failed", cause),
      ),
      Effect.forever,
      Effect.forkIn(subscriptionScope),
    )
    return { ctx, state, subscription, cancelled: yield* Deferred.make<void>(), background: false } satisfies Turn
  })

  const take = (subscription: Subscription) =>
    Queue.take(subscription.events).pipe(
      Effect.catch((error) =>
        Cause.isDone(error) ? Effect.fail(new ACPError.ServerUnavailableError()) : ACPClient.classify(error),
      ),
    )

  const asksSettled = Effect.fnUntraced(function* (subscription: Subscription) {
    const settled = yield* Deferred.make<void>()
    yield* Queue.offer(subscription.askQueue, Deferred.succeed(settled, undefined).pipe(Effect.asVoid))
    yield* Deferred.await(settled)
  })

  const queueAsk = <A>(
    turn: Turn,
    id: string,
    ask: Effect.Effect<A, unknown>,
    fallback: A,
    respond: (outcome: A) => Effect.Effect<void, ACPError.Error | RequestError>,
  ) =>
    Effect.gen(function* () {
      const settled = yield* Deferred.make<void>()
      turn.subscription.settled.set(id, settled)
      yield* Queue.offer(
        turn.subscription.askQueue,
        Effect.uninterruptibleMask((restore) =>
          // The race starts racers in order and stops once one is done, so an earlier cancel never starts the ask.
          restore(
            Deferred.await(turn.cancelled).pipe(
              Effect.as(fallback),
              Effect.raceFirst(Deferred.await(settled).pipe(Effect.as("settled" as const))),
              Effect.raceFirst(ask),
            ),
          ).pipe(
            Effect.tapCauseIf(Cause.hasDies, (cause) => Effect.logWarning("ACP ask failed", cause)),
            Effect.catchCause(() => Effect.succeed(fallback)),
            Effect.flatMap((outcome) => (outcome === "settled" ? Effect.void : respond(outcome))),
          ),
        ).pipe(Effect.withSpan("cli.acp.turn.ask")),
      )
    })

  const interpret = (turn: Turn, output: ACPTranslate.Output) => {
    switch (output._tag) {
      case "SessionUpdate":
        if (turn.background) return Effect.void
        return ACPPermission.withCompletedDiffs(output.update, output.diff, turn.ctx.cwd).pipe(
          Effect.flatMap((update) => input.connection.sessionUpdate({ sessionId: turn.ctx.sessionID, update })),
        )
      case "ChildUpdate":
        return Effect.gen(function* () {
          if (output.update.type !== "update")
            return yield* input.connection.extNotification(ACPChild.UpdateMethod, output.update)
          const update = yield* ACPPermission.withCompletedDiffs(output.update.update, output.diff, turn.ctx.cwd)
          return yield* input.connection.extNotification(ACPChild.UpdateMethod, { ...output.update, update })
        }).pipe(
          Effect.catchCause((cause) =>
            Cause.hasInterruptsOnly(cause)
              ? Effect.void
              : Effect.logWarning("ACP child session update failed", cause),
          ),
        )
      case "PermissionAsk": {
        const permission = {
          client: input.client,
          connection: input.connection,
          event: output.event,
          sessionID: output.event.data.sessionID,
          clientSessionID: turn.ctx.sessionID,
          cwd: turn.ctx.cwd,
          tool: output.tool,
          child: output.child,
        }
        return queueAsk(turn, output.event.data.id, ACPPermission.ask(permission), "reject", (decision) =>
          ACPPermission.respond(permission, decision),
        )
      }
      case "FormAsk":
        return Effect.gen(function* () {
          const capabilities = yield* Ref.get(input.capabilities)
          const requestedSchema = ACPElicitation.requestedSchema(output.form, capabilities)
          if (!requestedSchema) return yield* ACPElicitation.cancelUnshown(input.client, output.form)
          const elicitation = {
            client: input.client,
            connection: input.connection,
            form: output.form,
            requestedSchema,
            clientSessionID: turn.ctx.sessionID,
            child: output.child,
            toolCallSent: !turn.background && (!output.child || !turn.ctx.childUpdates),
          }
          yield* queueAsk(turn, output.form.id, ACPElicitation.ask(elicitation), "cancel", (outcome) =>
            ACPElicitation.respond(elicitation, outcome),
          )
        })
      case "AskSettled":
        return Effect.suspend(() => {
          const settled = turn.subscription.settled.get(output.id)
          turn.subscription.settled.delete(output.id)
          return settled ? Deferred.succeed(settled, undefined) : Effect.void
        })
    }
  }

  const advance = Effect.fnUntraced(function* (turn: Turn) {
    const event = yield* take(turn.subscription)
    const folded = yield* Ref.modify(turn.state, (current) => {
      const next =
        turn.background && !ACPTranslate.fromTrackedChild(current, event)
          ? { state: current, outputs: [] }
          : ACPTranslate.fold(current, event, turn.ctx)
      return [next, next.state]
    })
    yield* Effect.forEach(folded.outputs, (output) => interpret(turn, output), { discard: true })
    return folded
  })

  const consume = Effect.fnUntraced(function* (turn: Turn) {
    while (true) {
      const folded = yield* advance(turn)
      if (folded.terminal) {
        yield* asksSettled(turn.subscription)
        return folded.terminal
      }
    }
  })

  const followChildren = Effect.fnUntraced(function* (turn: Turn) {
    while (true) {
      const folded = yield* advance(turn)
      if (folded.state.openChildren.size === 0) return yield* asksSettled(turn.subscription)
    }
  })

  const submit = Effect.fnUntraced(function* (attached: Attached, prompt: ACPPrompt.Prepared) {
    const sessionID = attached.id
    if (prompt.synthetic.length > 0) {
      yield* input.client.session
        .synthetic({
          sessionID,
          text: prompt.synthetic.join("\n\n"),
          description: "ACP embedded context",
          delivery: "steer",
          resume: false,
        })
        .pipe(Effect.catch(ACPClient.classify))
    }
    if (prompt.start.type === "compaction") {
      yield* input.client.session.compact({ sessionID, id: prompt.start.id }).pipe(Effect.catch(ACPClient.classify))
      return
    }
    const command = prompt.command
    if (command) {
      yield* input.client.session
        .command({
          sessionID,
          name: command.name,
          text: prompt.slash?.args ?? "",
          files: prompt.files,
          delivery: "steer",
        })
        .pipe(Effect.catch(ACPClient.classify))
      return
    }
    yield* input.client.session
      .prompt({ sessionID, id: prompt.start.id, text: prompt.text, files: prompt.files, delivery: "steer" })
      .pipe(Effect.catch(ACPClient.classify))
  })

  const windDown = Effect.fnUntraced(function* (
    turn: Turn,
    events: Fiber.Fiber<ACPTranslate.Terminal, ACPError.Failure>,
  ) {
    yield* Deferred.succeed(turn.cancelled, undefined)
    yield* input.client.session
      .interrupt({ sessionID: turn.ctx.sessionID })
      .pipe(
        Effect.catchCause((cause) =>
          Cause.hasInterruptsOnly(cause) ? Effect.void : Effect.logWarning("ACP server interrupt failed", cause),
        ),
      )
    if (!(yield* Ref.get(turn.state)).started) return
    if (Option.exists(yield* Fiber.await(events).pipe(Effect.timeoutOption(drainTimeout)), Exit.isSuccess)) return
    yield* Fiber.interrupt(events)
    const abandoned = ACPTranslate.abandon(yield* Ref.get(turn.state), turn.ctx)
    yield* Ref.set(turn.state, abandoned.state)
    yield* Effect.forEach(abandoned.outputs, (output) => interpret(turn, output), { discard: true }).pipe(Effect.ignore)
  })

  const execute = (attached: Attached, prompt: ACPPrompt.Prepared, turn: Turn) =>
    Effect.gen(function* () {
      // The feed opens with `server.connected`, so every event the submission causes comes after it.
      const connected = yield* take(turn.subscription)
      if (connected.type !== "server.connected")
        return yield* Effect.die(new Error(`expected server.connected, got ${connected.type}`))
      const events = yield* consume(turn).pipe(Effect.forkScoped)
      return yield* Effect.gen(function* () {
        yield* submit(attached, prompt)
        if (prompt.command) return "succeeded" as const
        return yield* Fiber.join(events)
      }).pipe(Effect.onInterrupt(() => windDown(turn, events)))
    }).pipe(Effect.scoped)

  const handoff = Effect.fnUntraced(function* (
    attached: Attached,
    turn: Turn,
    exit: Exit.Exit<ACPTranslate.Terminal, ACPError.Failure>,
  ) {
    const close = Scope.close(turn.subscription.scope, Exit.void)
    if (Exit.isFailure(exit) && !Cause.hasInterruptsOnly(exit.cause)) return yield* close
    const state = yield* Ref.get(turn.state)
    if (state.openChildren.size === 0) return yield* close
    // Children outlive a cancelled turn, so their asks still reach the client.
    const background = followChildren({
      ...turn,
      state: yield* Ref.make(state),
      cancelled: yield* Deferred.make<void>(),
      background: true,
    }).pipe(Effect.ignore, Effect.ensuring(close), Effect.withSpan("cli.acp.turn.background"))
    yield* input.sessions.fork(attached, background).pipe(Effect.catchTag("ACPSessionNotFoundError", () => close))
  })

  const settle = Effect.fnUntraced(function* (
    attached: Attached,
    current: ACPTranslate.TurnState,
    exit: Exit.Exit<ACPTranslate.Terminal, ACPError.Failure>,
  ) {
    if (Exit.isFailure(exit) && !Cause.hasInterrupts(exit.cause)) return yield* Effect.failCause(exit.cause)
    const terminal = Exit.isSuccess(exit) ? exit.value : "interrupted"
    const failure = terminal === "interrupted" ? undefined : ACPTranslate.failure(current)
    if (failure) return yield* failure
    yield* sendUsageUpdate(attached, current)
    const cancelledWhileSettling = Exit.isFailure(yield* Effect.exit(Effect.interruptible(Effect.void)))
    return ACPTranslate.response(current, attached.id, cancelledWhileSettling ? "interrupted" : terminal)
  })

  const sendUsageUpdate = Effect.fn("cli.acp.turn.usage")(
    function* (attached: Attached, state: ACPTranslate.TurnState) {
      const used = state.usage ? TokenUsage.total(state.usage.last) : 0
      if (!used) return
      const catalog = yield* input.catalog.get(attached.cwd)
      const model = findModel(catalog.models, currentModel(catalog, yield* Ref.get(attached.selection)))
      if (!model?.limit.context) return
      const info = yield* input.client.session.get({ sessionID: attached.id }).pipe(Effect.catch(ACPClient.classify))
      yield* input.connection.sessionUpdate({
        sessionId: attached.id,
        update: {
          sessionUpdate: "usage_update",
          used,
          size: model.limit.context,
          cost: { amount: info.cost, currency: "USD" },
        },
      })
    },
    Effect.catchCause((cause) =>
      Cause.hasInterruptsOnly(cause) ? Effect.void : Effect.logWarning("ACP usage update failed", cause),
    ),
  )

  // Forked uninterruptible: interruption lands only in `execute` and the last check in `settle`, so a response follows.
  const run = Effect.fn("cli.acp.turn.run")(function* (params: PromptRequest) {
    const attached = yield* input.sessions.require(params.sessionId)
    const prompt = yield* ACPPrompt.prepare(yield* input.catalog.get(attached.cwd), params.prompt)
    const capabilities = yield* Ref.get(input.capabilities)
    const state = yield* Ref.make(ACPTranslate.initial)
    const exit = yield* Effect.acquireUseRelease(
      open(
        {
          sessionID: attached.id,
          cwd: attached.cwd,
          start: prompt.start,
          childUpdates: capabilities.childSessionUpdates,
          compaction: capabilities.compaction,
        },
        state,
      ),
      (turn) => execute(attached, prompt, turn),
      (turn, exit) => handoff(attached, turn, exit),
    ).pipe(Effect.interruptible, Effect.exit)
    return yield* settle(attached, yield* Ref.get(state), exit)
  })

  return {
    prompt: Effect.fnUntraced(function* (params, signal) {
      // Synchronous and before setup, so concurrent prompts cannot both register and an early cancel still applies.
      const turn = yield* Effect.withFiber((fiber) => {
        if (FiberMap.hasUnsafe(turns, params.sessionId)) {
          return Effect.fail(
            new ACPError.ServiceFailureError({
              safeMessage: `Session already has an active ACP prompt: ${params.sessionId}`,
              service: "session",
            }),
          )
        }
        const forked = Effect.runForkWith(fiber.context)(run(params), { uninterruptible: true })
        FiberMap.setUnsafe(turns, params.sessionId, forked)
        return Effect.succeed(forked)
      })
      // A `$/cancel_request` for this prompt cancels its turn like `session/cancel`, rather than failing the request.
      yield* aborted(signal).pipe(Effect.andThen(Fiber.interrupt(turn)), Effect.forkChild)
      return yield* Fiber.join(turn)
    }),
    cancel: Effect.fnUntraced(function* (params) {
      yield* FiberMap.remove(turns, params.sessionId)
    }),
    close: Effect.fn("cli.acp.turn.close")(function* (sessionID) {
      if (FiberMap.hasUnsafe(turns, sessionID)) return yield* FiberMap.remove(turns, sessionID)
      yield* ACPClient.decodeSessionID(sessionID).pipe(
        Effect.flatMap((id) => input.client.session.interrupt({ sessionID: id })),
        Effect.catchTag(["ACPInvalidRequestError", "SessionNotFoundError"], () => Effect.void),
        Effect.catch(ACPClient.classify),
      )
    }),
  } satisfies Interface
})

function aborted(signal: AbortSignal) {
  return Effect.callback<void>((resume) => {
    if (signal.aborted) return resume(Effect.void)
    const abort = () => resume(Effect.void)
    signal.addEventListener("abort", abort, { once: true })
    return Effect.sync(() => signal.removeEventListener("abort", abort))
  })
}

