import { MessageTooLargeError, ndJsonStream } from "@agentclientprotocol/sdk"
import { OpenCode } from "@opencode/client/effect"
import { Service } from "@opencode/client/effect/service"
import { CrossSpawnSpawner } from "@opencode/util/cross-spawn-spawner"
import { Effect, Option } from "effect"
import { FetchHttpClient, HttpClient, HttpClientRequest } from "effect/http"
import { Writable } from "node:stream"
import { ACP } from "../../acp/agent"
import { Commands } from "../commands"
import { Runtime } from "../../framework/runtime"
import { Standalone } from "../../services/standalone"

export default Runtime.handler(
  Commands.commands.acp,
  Effect.fn("cli.acp")(function* (input) {
    if (input.login) {
      const login = yield* Effect.promise(() => import("./auth/login"))
      return yield* login.default({
        target: Option.none(),
        method: Option.none(),
        answer: [],
        server: Option.none(),
        standalone: false,
      })
    }
    process.env.OPENCODE_CLIENT = "acp"
    const endpoint = yield* Standalone.start()
    const client = yield* OpenCode.make({ baseUrl: endpoint.url }).pipe(
      Effect.provideServiceEffect(
        HttpClient.HttpClient,
        HttpClient.HttpClient.pipe(
          Effect.map(HttpClient.mapRequest(HttpClientRequest.setHeaders(Service.headers(endpoint) ?? {}))),
        ),
      ),
      Effect.provide(FetchHttpClient.layer),
    )
    const connection = yield* ACP.connect(client, ndJsonStream(Writable.toWeb(process.stdout), Bun.stdin.stream()))
    const failure = yield* Effect.raceFirst(
      Effect.promise(() => connection.closed).pipe(
        Effect.map(() =>
          connection.signal.reason instanceof MessageTooLargeError
            ? `incoming message exceeded the ${connection.signal.reason.maxMessageBytes / 1024 / 1024} MiB limit`
            : undefined,
        ),
      ),
      endpoint.exited.pipe(
        Effect.match({
          onSuccess: (code) => `code ${code}`,
          onFailure: (error) =>
            error.cause instanceof CrossSpawnSpawner.KilledBySignal ? `signal ${error.cause.signal}` : error.message,
        }),
        Effect.map((reason) => `server exited unexpectedly (${reason})`),
      ),
    )
    // Exit directly: closing the scope would wait on the server's graceful shutdown, and its lease pipe ends it anyway.
    yield* Effect.sync(() => {
      if (failure) process.stderr.write(`opencode acp: ${failure}\n`)
      process.exit(failure ? 1 : 0)
    })
  }),
)

import { describe, expect, test } from "bun:test"
import { rawRequest, resolveOperation } from "./api"

describe("api request resolution", () => {
  test("resolves an operation ID with path and query parameters", () => {
    expect(
      resolveOperation(
        {
          paths: {
            "/api/session/{sessionID}": {
              get: { operationId: "session.get" },
            },
          },
        },
        "session.get",
        { sessionID: "ses/a", workspace: "work" },
      ),
    ).toEqual({ method: "GET", path: "/api/session/ses%2Fa?workspace=work" })
  })

  test("rejects a missing path parameter", () => {
    expect(() =>
      resolveOperation(
        { paths: { "/api/session/{sessionID}": { get: { operationId: "session.get" } } } },
        "session.get",
        {},
      ),
    ).toThrow("Missing path parameter: sessionID")
  })

  test("resolves curl-like method and path input", () => {
    expect(rawRequest(["post", "/api/foo"])).toEqual({ method: "POST", path: "/api/foo" })
    expect(rawRequest(["session.list"])).toBeUndefined()
  })
})

import { EOL } from "node:os"
import { Effect, Option } from "effect"
import { Commands } from "../commands"
import { Runtime } from "../../framework/runtime"
import { Service, type Endpoint } from "@opencode/client/effect/service"
import { ServerConnection } from "../../services/server-connection"

const methods = new Set(["delete", "get", "head", "options", "patch", "post", "put"])

type Operation = {
  operationId?: string
}

type OpenApi = {
  paths?: Record<string, Record<string, Operation>>
}

export default Runtime.handler(
  Commands.commands.api,
  Effect.fn("cli.api")(function* (input) {
    const server = yield* ServerConnection.resolve({
      server: Option.getOrUndefined(input.server),
      standalone: input.standalone,
      mismatch: "ignore",
    })
    const endpoint = server.endpoint
    const params = Option.getOrElse(input.param, () => ({}))
    const request = yield* resolveRequest(endpoint, input.request, params)
    const headers = new Headers(Service.headers(endpoint))
    for (const header of input.header) {
      const index = header.indexOf(":")
      if (index < 1) return yield* Effect.fail(new Error(`Invalid header, expected name:value: ${header}`))
      headers.set(header.slice(0, index).trim(), header.slice(index + 1).trim())
    }
    const body = Option.getOrUndefined(input.data)
    if (body !== undefined && !headers.has("content-type")) headers.set("content-type", "application/json")

    const response = yield* Effect.tryPromise(() =>
      fetch(new URL(request.path, endpoint.url), {
        method: request.method,
        headers,
        body,
      }),
    )
    const output = yield* Effect.promise(() => response.text())
    if (output) process.stdout.write(output + (output.endsWith(EOL) ? "" : EOL))
    if (!response.ok) {
      process.stderr.write(`HTTP ${response.status} ${response.statusText}${EOL}`)
      process.exitCode = 1
    }
  }),
)

export function resolveOperation(spec: OpenApi, operationID: string, params: Record<string, string>) {
  for (const [path, operations] of Object.entries(spec.paths ?? {})) {
    for (const [method, operation] of Object.entries(operations)) {
      if (!methods.has(method) || operation.operationId !== operationID) continue
      return { method: method.toUpperCase(), path: interpolate(path, params) }
    }
  }
  throw new Error(`Operation not found: ${operationID}`)
}

export function rawRequest(input: readonly string[]) {
  if (input.length !== 2 || !methods.has(input[0].toLowerCase()) || !input[1].startsWith("/")) return
  return { method: input[0].toUpperCase(), path: input[1] }
}

function resolveRequest(endpoint: Endpoint, input: readonly string[], params: Record<string, string>) {
  const raw = rawRequest(input)
  if (raw) return Effect.succeed(raw)
  if (input.length !== 1) return Effect.fail(new Error("Expected an operation name or an HTTP method and path"))
  return Effect.tryPromise(async () => {
    const response = await fetch(new URL("/openapi.json", endpoint.url), { headers: Service.headers(endpoint) })
    if (!response.ok) throw new Error(`Failed to load OpenAPI document: HTTP ${response.status}`)
    return resolveOperation((await response.json()) as OpenApi, input[0], params)
  })
}

function interpolate(path: string, params: Record<string, string>) {
  const used = new Set<string>()
  const pathname = path.replaceAll(/\{([^}]+)\}/g, (_, name: string) => {
    const value = params[name]
    if (value === undefined) throw new Error(`Missing path parameter: ${name}`)
    used.add(name)
    return encodeURIComponent(value)
  })
  const query = new URLSearchParams(Object.entries(params).filter(([name]) => !used.has(name))).toString()
  return query ? `${pathname}?${query}` : pathname
}

import { autocomplete } from "@clack/prompts"
import { Effect } from "effect"
import type { IntegrationInfo } from "@opencode/client"
import { prompt } from "../../../ui/prompt"
import { resolveIntegration } from "./shared"

export const chooseIntegration = Effect.fn("cli.auth.account.integration")(function* (
  integrations: IntegrationInfo[],
  target?: string,
) {
  if (target) return yield* resolveIntegration(integrations, target)
  const configured = integrations.filter((integration) =>
    integration.connections.some((connection) => connection.type === "credential"),
  )
  if (configured.length === 0) return yield* Effect.fail(new Error("No stored credentials found"))
  const id = yield* prompt<string>(() =>
    autocomplete({
      message: "Select integration",
      maxItems: 8,
      options: configured.map((integration) => ({
        value: integration.id,
        label: integration.name,
        hint: integration.connections
          .filter((connection) => connection.type === "credential")
          .map((connection) => connection.label)
          .join(", "),
      })),
    }),
  )
  return yield* resolveIntegration(configured, id)
})

export const chooseCredential = Effect.fn("cli.auth.account.credential")(function* (
  integration: IntegrationInfo,
  action: "log out" | "switch to",
  target?: string,
) {
  const credentials = integration.connections.filter((connection) => connection.type === "credential")
  if (credentials.length === 0) {
    const environment = integration.connections
      .filter((connection) => connection.type === "env")
      .map((connection) => connection.name)
    if (environment.length && action === "log out") {
      yield* Effect.fail(
        new Error(
          `${integration.name} is authenticated through ${environment.join(", ")}; unset the environment variable to disconnect`,
        ),
      )
    }
    yield* Effect.fail(new Error(`No stored credentials for ${integration.name}`))
  }
  if (target) {
    const byID = credentials.find((credential) => credential.id === target)
    if (byID) return byID.id
    const matches = credentials.filter((credential) => credential.label.toLowerCase() === target.toLowerCase())
    if (matches.length === 1) return matches[0].id
    if (matches.length > 1)
      return yield* Effect.fail(
        new Error(`Credential label "${target}" is ambiguous. Use an ID: ${matches.map((item) => item.id).join(", ")}`),
      )
    return yield* Effect.fail(new Error(`Credential not found for ${integration.name}: ${target}`))
  }
  return yield* prompt<string>(() =>
    autocomplete({
      message: `Select ${integration.name} account to ${action}`,
      maxItems: 8,
      options: credentials.map((credential, index) => ({
        value: credential.id,
        label: index === 0 ? `${credential.label} (active)` : credential.label,
        hint: credential.id,
      })),
    }),
  )
})

import { EOL } from "node:os"
import { Effect, Option } from "effect"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { createClient, loadIntegrations, request, resolveIntegration } from "./shared"
import { errorMessage } from "../../../util/error"

export default Runtime.handler(
  Commands.commands.auth.commands.export,
  Effect.fn("cli.auth.export")(
    function* (input) {
      const client = yield* createClient({ server: Option.getOrUndefined(input.server), standalone: input.standalone })
      const target = Option.getOrUndefined(input.target)
      const integrationID = target ? (yield* resolveIntegration(yield* loadIntegrations(client), target)).id : undefined
      const credentials = (yield* request((signal) => client.credential.list({ signal }))).filter(
        (credential) => !integrationID || credential.integrationID === integrationID,
      )
      if (process.stdout.isTTY)
        process.stderr.write(
          "Warning: the output contains secrets; redirect it to a file or pipe it to auth import" + EOL,
        )
      process.stdout.write(JSON.stringify(credentials, null, 2) + EOL)
    },
    Effect.catch((error) =>
      Effect.sync(() => {
        process.stderr.write(errorMessage(error) + EOL)
        process.exitCode = 1
      }),
    ),
  ),
)

import { confirm, log, multiselect, password, select, text, type Option } from "@clack/prompts"
import { Effect, Schema } from "effect"
import { Form } from "@opencode/schema/form"
import { formValidateValue } from "@opencode/tui/util/form"
import type { FormAnswer, FormField, FormFields } from "@opencode/client"
import { openUrl, prompt, requireInteractive } from "../../../ui/prompt"

const skip = Symbol("skip")
const custom = Symbol("custom")
const decodeAnswer = Schema.decodeUnknownOption(Schema.fromJsonString(Form.Value))

export const answerForm = Effect.fn("cli.auth.form")(function* (
  fields: FormFields | undefined,
  input: ReadonlyArray<string> = [],
) {
  const supplied = new Map<string, string>()
  for (const item of input) {
    const separator = item.indexOf("=")
    if (separator < 1) return yield* Effect.fail(new Error("Expected --answer key=value"))
    const key = item.slice(0, separator)
    if (!fields?.some((field) => field.key === key)) {
      return yield* Effect.fail(new Error(`Unknown form field: ${key}`))
    }
    supplied.set(key, item.slice(separator + 1))
  }
  if (!fields) return undefined
  const answer: FormAnswer = {}
  for (const field of fields) {
    if (!active(field, answer)) {
      if (supplied.has(field.key)) {
        return yield* Effect.fail(new Error(`Form field is not active: ${field.key}`))
      }
      continue
    }
    const provided = supplied.get(field.key)
    const value =
      provided !== undefined
        ? yield* suppliedAnswer(field, provided)
        : field.type !== "external" && field.hidden
          ? field.default
          : yield* answerField(field)
    if (field.type !== "external") {
      const invalid = formValidateValue(field, value)
      if (invalid) return yield* Effect.fail(new Error(`${field.key}: ${invalid}`))
    }
    if (value !== undefined) answer[field.key] = value
  }
  return answer
})

const suppliedAnswer = Effect.fn("cli.auth.form.answer")(function* (field: FormField, input: string) {
  if (field.type === "external") {
    return yield* Effect.fail(new Error(`External form field requires interactive confirmation: ${field.key}`))
  }
  if (field.type === "string") return input
  const value = decodeAnswer(input)
  if (value._tag === "None") {
    return yield* Effect.fail(new Error(`Expected a JSON value for form field: ${field.key}`))
  }
  return typeof value.value === "object" ? [...value.value] : value.value
})

export const secret = Effect.fn("cli.auth.secret")(function* (message: string) {
  yield* requireInteractive("API key input requires an interactive terminal")
  return yield* prompt<string>(() => password({ message, validate: (value) => (!value ? "Required" : undefined) }))
})

const answerField = Effect.fn("cli.auth.form.field")(function* (field: FormField) {
  yield* requireInteractive("Authentication form input requires an interactive terminal")
  const message = field.title ?? field.key
  if (field.description) log.info(field.description)
  if (field.type === "external") {
    log.info(field.url)
    yield* openUrl(field.url)
    const acknowledged = yield* prompt<boolean>(() =>
      confirm({ message: message || "Continue after completing this step?", initialValue: true }),
    )
    if (!acknowledged) return yield* Effect.fail(new Error(`${message || "External step"} is required`))
    return true
  }
  if (field.type === "boolean") {
    if (field.required) return yield* prompt<boolean>(() => confirm({ message, initialValue: field.default ?? true }))
    const options: Array<Option<boolean | typeof skip>> = [
      { value: true, label: "Yes" },
      { value: false, label: "No" },
      { value: skip, label: "Skip" },
    ]
    const value = yield* prompt<boolean | typeof skip>(() =>
      select<boolean | typeof skip>({
        message,
        options,
        initialValue: field.default ?? skip,
      }),
    )
    if (value === skip) return undefined
    return value
  }
  if (field.type === "multiselect") {
    const options: Array<Option<string | typeof custom>> = field.options.map((option) => ({
      value: option.value,
      label: option.label,
      hint: option.description,
    }))
    if (field.custom) options.push({ value: custom, label: "Type another value" })
    const values = yield* prompt<Array<string | typeof custom>>(() =>
      multiselect<string | typeof custom>({
        message,
        options,
        initialValues: field.default,
        required: field.required || (field.minItems ?? 0) > 0,
      }),
    )
    const selected = values.filter((value): value is string => value !== custom)
    if (values.includes(custom)) {
      selected.push(yield* prompt<string>(() => text({ message: "Enter value", validate: required })))
    }
    if (field.minItems !== undefined && selected.length < field.minItems) {
      return yield* Effect.fail(new Error(`Select at least ${field.minItems}`))
    }
    if (field.maxItems !== undefined && selected.length > field.maxItems) {
      return yield* Effect.fail(new Error(`Select at most ${field.maxItems}`))
    }
    return selected
  }
  if (field.type === "string" && field.options) {
    const options: Array<Option<string | typeof custom | typeof skip>> = field.options.map((option) => ({
      value: option.value,
      label: option.label,
      hint: option.description,
    }))
    if (field.custom) options.push({ value: custom, label: "Type your own answer" })
    if (!field.required) options.push({ value: skip, label: "Skip" })
    const value = yield* prompt<string | typeof custom | typeof skip>(() =>
      select<string | typeof custom | typeof skip>({ message, options, initialValue: field.default }),
    )
    if (value === skip) return undefined
    if (value !== custom) return value
  }
  const value = yield* prompt<string>(() =>
    text({
      message,
      placeholder: field.type === "string" ? field.placeholder : undefined,
      initialValue: field.default === undefined ? undefined : String(field.default),
      validate: (input) => validateText(field, input),
    }),
  )
  if (!value && !field.required) return undefined
  if (field.type === "string") return value
  return Number(value)
})

function active(field: FormField, answer: FormAnswer) {
  if (field.type === "external" || !field.when) return true
  return field.when.every((condition) => {
    const value = answer[condition.key]
    if (value === undefined) return false
    const matches = Array.isArray(value) ? value.includes(String(condition.value)) : value === condition.value
    return condition.op === "eq" ? matches : !matches
  })
}

function required(value: string | undefined) {
  return value ? undefined : "Required"
}

function validateText(field: Exclude<FormField, { type: "boolean" | "external" | "multiselect" }>, value?: string) {
  if (!value) return field.required ? "Required" : undefined
  if (field.type === "number" || field.type === "integer") {
    const number = Number(value)
    if (!Number.isFinite(number)) return "Expected a number"
    if (field.type === "integer" && !Number.isInteger(number)) return "Expected an integer"
    if (typeof field.minimum === "number" && number < field.minimum) return `Must be at least ${field.minimum}`
    if (typeof field.maximum === "number" && number > field.maximum) return `Must be at most ${field.maximum}`
    return undefined
  }
  if (field.minLength !== undefined && value.length < field.minLength)
    return `Must be at least ${field.minLength} characters`
  if (field.maxLength !== undefined && value.length > field.maxLength)
    return `Must be at most ${field.maxLength} characters`
  if (field.pattern) {
    try {
      if (!new RegExp(field.pattern).test(value)) return "Invalid format"
    } catch {
      return "Invalid format"
    }
  }
  if (field.format === "uri" && !URL.canParse(value)) return "Expected a URL"
  if (field.format === "email" && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) return "Expected an email address"
  if (field.format === "date") {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return "Expected a date"
    const date = new Date(`${value}T00:00:00.000Z`)
    if (Number.isNaN(date.getTime()) || date.toISOString().slice(0, 10) !== value) return "Expected a date"
  }
  if (field.format === "date-time" && Number.isNaN(Date.parse(value))) return "Expected a date and time"
  return undefined
}

import { EOL } from "node:os"
import { isConflictError, type CredentialCreateInput } from "@opencode/client"
import { Credential } from "@opencode/schema/credential"
import { Effect, Option, Schema } from "effect"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { createClient, request } from "./shared"
import { errorMessage } from "../../../util/error"
import { readStdin } from "../../../util/io"

export default Runtime.handler(
  Commands.commands.auth.commands.import,
  Effect.fn("cli.auth.import")(
    function* (input) {
      const file = Option.getOrUndefined(input.file)
      if (!file && process.stdin.isTTY)
        return yield* Effect.fail(new Error("Pipe auth export output into stdin or pass a file to import"))
      const text = yield* request(() => (file ? Bun.file(file).text() : readStdin()))
      const credentials = yield* Schema.decodeUnknownEffect(Schema.fromJsonString(Schema.Array(Credential.Entry)))(text)
      const client = yield* createClient({ server: Option.getOrUndefined(input.server), standalone: input.standalone })
      const existing = yield* request((signal) => client.credential.list({ signal }))
      const ids = new Set(existing.map((credential) => credential.id))
      const integrations = new Set(existing.map((credential) => credential.integrationID))
      const results = yield* Effect.forEach(credentials, (credential) => {
        if (ids.has(credential.id)) return Effect.succeed(false)
        return request((signal) =>
          client.credential.create(
            {
              id: credential.id,
              integrationID: credential.integrationID,
              label: credential.label,
              // Stored metadata is JSON, but the credential schema types it as unknown while the generated client expects JSON.
              value: credential.value as CredentialCreateInput["value"],
              // Keep the destination's current selections; only integrations new to it adopt the exported selection.
              activate: credential.active && !integrations.has(credential.integrationID),
            },
            { signal },
          ),
        ).pipe(
          Effect.as(true),
          Effect.catchIf(isConflictError, () => Effect.succeed(false)),
        )
      })
      const imported = results.filter(Boolean).length
      process.stderr.write(
        `Imported ${imported} ${imported === 1 ? "credential" : "credentials"}` +
          (results.length > imported ? `, skipped ${results.length - imported} already present` : "") +
          EOL,
      )
    },
    Effect.catch((error) =>
      Effect.sync(() => {
        process.stderr.write(errorMessage(error) + EOL)
        process.exitCode = 1
      }),
    ),
  ),
)

import { EOL } from "node:os"
import { Effect, Option } from "effect"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { createClient, loadIntegrations } from "./shared"
import { errorMessage } from "../../../util/error"

export default Runtime.handler(Commands.commands.auth.commands.list, (input) =>
  list(input).pipe(
    Effect.catch((error) =>
      Effect.sync(() => {
        process.stderr.write(errorMessage(error) + EOL)
        process.exitCode = 1
      }),
    ),
  ),
)

const list = Effect.fn("cli.auth.list")(function* (input) {
  const client = yield* createClient({ server: Option.getOrUndefined(input.server), standalone: input.standalone })
  const integrations = (yield* loadIntegrations(client)).filter((integration) => integration.connections.length > 0)
  if (input.format === "json") {
    process.stdout.write(
      JSON.stringify(
        integrations.map((integration) => ({
          id: integration.id,
          name: integration.name,
          connections: integration.connections,
        })),
        null,
        2,
      ) + EOL,
    )
    return
  }
  const rows = integrations.flatMap((integration) =>
    integration.connections.map((connection) => ({
      integration: integration.name,
      source: connection.type === "credential" ? connection.label : connection.name,
      type: connection.type === "credential" ? "stored" : "environment",
    })),
  )
  if (rows.length === 0) {
    process.stdout.write("No authenticated integrations" + EOL)
    return
  }
  const width = Math.max(...rows.map((row) => row.integration.length)) + 2
  process.stdout.write(
    rows.map((row) => row.integration.padEnd(width) + row.source.padEnd(28) + row.type).join(EOL) + EOL,
  )
})

import { intro, log, outro, select, spinner, text } from "@clack/prompts"
import { Effect, Option } from "effect"
import type { FormAnswer, IntegrationInfo, OpenCodeClient } from "@opencode/client"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { selectIntegration, type IntegrationChoice } from "../../../ui/integration-picker"
import { handlePromptErrors, openUrl, prompt, requireInteractive } from "../../../ui/prompt"
import { answerForm, secret } from "./form"
import {
  createClient,
  connectMethods,
  loadIntegrations,
  location,
  request,
  resolveIntegration,
  resolveMethod,
  type ConnectMethod,
} from "./shared"

const integrationPriority = new Map([
  ["opencode-go", 0],
  ["opencode", 1],
  ["openai", 2],
  ["github-copilot", 3],
  ["anthropic", 4],
  ["google", 5],
])

export default Runtime.handler(
  Commands.commands.auth.commands.login,
  Effect.fn("cli.auth.login")((input) =>
    login({
      target: Option.getOrUndefined(input.target),
      method: Option.getOrUndefined(input.method),
      answer: input.answer,
      server: Option.getOrUndefined(input.server),
      standalone: input.standalone,
    }).pipe(handlePromptErrors),
  ),
)

const login = Effect.fn("cli.auth.login.run")(function* (input: {
  target?: string
  method?: string
  answer?: ReadonlyArray<string>
  server?: string
  standalone: boolean
}) {
  if (!input.target)
    yield* requireInteractive("Pass an integration ID or name when running without an interactive terminal")
  intro("Connect an integration")
  const client = yield* createClient({ server: input.server, standalone: input.standalone })
  const integration = yield* findIntegration(client, input.target)
  const methods = connectMethods(integration)
  if (methods.length === 0) yield* Effect.fail(new Error(`${integration.name} has no interactive login methods`))
  const method = yield* chooseMethod(methods, input.method)
  const answer = yield* answerForm(method.type === "command" ? undefined : method.form, input.answer)
  yield* authenticate(client, integration, method, answer)
  outro("Done")
})

const findIntegration = Effect.fn("cli.auth.login.integration")(function* (client: OpenCodeClient, target?: string) {
  if (target && URL.canParse(target)) {
    const protocol = new URL(target).protocol
    if (protocol === "http:" || protocol === "https:") {
      const progress = spinner()
      progress.start("Discovering authentication provider...")
      yield* request((signal) => client.integration.wellknown.add({ url: target, location }, { signal })).pipe(
        Effect.tap(() => Effect.sync(() => progress.stop("Authentication provider discovered"))),
        Effect.tapCause(() => Effect.sync(() => progress.stop("Discovery failed", 1))),
      )
    }
  }
  const integrations = yield* loadIntegrations(client)
  if (target) return yield* resolveIntegration(integrations, target)
  const choices = loginChoices(integrations)
  if (choices.length === 0) return yield* Effect.fail(new Error("No authentication integrations are available"))
  const id = yield* prompt<string>(() => selectIntegration(choices))
  return yield* resolveIntegration(integrations, id)
})

export function loginChoices(integrations: IntegrationInfo[]): IntegrationChoice[] {
  return integrations
    .filter((integration) => connectMethods(integration).length > 0)
    .toSorted(
      (a, b) =>
        Number(b.metadata?.source === "mcp") - Number(a.metadata?.source === "mcp") ||
        (integrationPriority.get(a.id) ?? integrationPriority.size) -
          (integrationPriority.get(b.id) ?? integrationPriority.size) ||
        a.name.localeCompare(b.name) ||
        a.id.localeCompare(b.id),
    )
    .map((integration) => ({
      value: integration.id,
      label: integration.name,
      category:
        integration.metadata?.source === "mcp"
          ? "MCP"
          : integrationPriority.has(integration.id)
            ? "Popular"
            : "Services",
      connected: integration.connections.length > 0,
    }))
}

const chooseMethod = Effect.fn("cli.auth.login.method")(function* (methods: ConnectMethod[], target?: string) {
  if (target) return yield* resolveMethod(methods, target)
  if (methods.length === 1) return methods[0]
  yield* requireInteractive("Pass --method when running without an interactive terminal")
  const id = yield* prompt<string>(() =>
    select({
      message: "Select login method",
      options: methods.map((method) => {
        if (method.type === "key") return { value: "key", label: method.label ?? "API key" }
        return { value: method.id, label: method.label }
      }),
    }),
  )
  return yield* resolveMethod(methods, id)
})

const authenticate = Effect.fn("cli.auth.login.authenticate")(function* (
  client: OpenCodeClient,
  integration: IntegrationInfo,
  method: ConnectMethod,
  answer?: FormAnswer,
) {
  if (method.type === "key") return yield* keyLogin(client, integration, method, answer)
  if (method.type === "command") return yield* commandLogin(client, integration, method)
  if (method.type === "external") return yield* externalLogin(client, integration, method, answer)
  return yield* oauthLogin(client, integration, method, answer)
})

const externalLogin = Effect.fn("cli.auth.login.external")(function* (
  client: OpenCodeClient,
  integration: IntegrationInfo,
  method: Extract<ConnectMethod, { type: "external" }>,
  answer?: FormAnswer,
) {
  const progress = spinner()
  progress.start("Saving credential...")
  yield* request((signal) =>
    client.integration.connect.external(
      { integrationID: integration.id, methodID: method.id, answer, location },
      { signal },
    ),
  ).pipe(
    Effect.tap(() => Effect.sync(() => progress.stop(`Connected to ${integration.name}`))),
    Effect.tapCause(() => Effect.sync(() => progress.stop("Authentication failed", 1))),
  )
})

const keyLogin = Effect.fn("cli.auth.login.key")(function* (
  client: OpenCodeClient,
  integration: IntegrationInfo,
  method: Extract<ConnectMethod, { type: "key" }>,
  answer?: FormAnswer,
) {
  const key = yield* secret(method.label ?? `Enter your ${integration.name} API key`)
  const progress = spinner()
  progress.start("Saving credential...")
  yield* request((signal) =>
    client.integration.connect.key({ integrationID: integration.id, key, answer, location }, { signal }),
  ).pipe(
    Effect.tap(() => Effect.sync(() => progress.stop(`Connected to ${integration.name}`))),
    Effect.tapCause(() => Effect.sync(() => progress.stop("Authentication failed", 1))),
  )
})

export const oauthLogin = Effect.fn("cli.auth.login.oauth")(function* (
  client: OpenCodeClient,
  integration: IntegrationInfo,
  method: Extract<ConnectMethod, { type: "oauth" }>,
  answer?: FormAnswer,
  label?: string,
) {
  const progress = spinner()
  progress.start("Starting authorization...")
  const started = yield* request((signal) =>
    client.integration.oauth.connect(
      { integrationID: integration.id, methodID: method.id, answer, label, location },
      { signal },
    ),
  ).pipe(Effect.tapCause(() => Effect.sync(() => progress.stop("Authentication failed", 1))))
  const attempt = started.data
  yield* Effect.addFinalizer(() =>
    request(() =>
      client.integration.oauth.cancel(
        { integrationID: integration.id, attemptID: attempt.attemptID, location },
        { signal: AbortSignal.timeout(5_000) },
      ),
    ).pipe(Effect.ignore),
  )
  progress.stop("Authorization started")
  log.info(attempt.instructions)
  log.info(attempt.url)
  if (process.stdin.isTTY && process.stdout.isTTY) yield* openUrl(attempt.url)

  if (attempt.mode === "code") {
    yield* requireInteractive("This login requires an interactive terminal to enter the authorization code")
    const code = yield* prompt<string>(() =>
      text({ message: "Paste the authorization code", validate: (value) => (!value ? "Required" : undefined) }),
    )
    const completing = spinner()
    completing.start("Completing authorization...")
    yield* request((signal) =>
      client.integration.oauth.complete(
        { integrationID: integration.id, attemptID: attempt.attemptID, code, location },
        { signal },
      ),
    ).pipe(
      Effect.tap(() => Effect.sync(() => completing.stop(`Connected to ${integration.name}`))),
      Effect.tapCause(() => Effect.sync(() => completing.stop("Authentication failed", 1))),
    )
    return
  }

  // Clack's spinner captures Ctrl+C and exits the process directly, which would skip the finalizer that
  // cancels the attempt. Waits that can last minutes use plain log lines so Ctrl+C interrupts normally.
  log.step("Waiting for authorization...")
  const status = yield* waitForOAuth(client, integration.id, attempt.attemptID)
  if (status.status === "complete") {
    log.success(`Connected to ${integration.name}`)
    return
  }
  if (status.status === "failed") yield* Effect.fail(new Error(status.message))
  yield* Effect.fail(new Error("Authorization expired"))
})

const commandLogin = Effect.fn("cli.auth.login.command")(function* (
  client: OpenCodeClient,
  integration: IntegrationInfo,
  method: Extract<ConnectMethod, { type: "command" }>,
) {
  const progress = spinner()
  progress.start("Starting authentication command...")
  const started = yield* request((signal) =>
    client.integration.command.connect({ integrationID: integration.id, methodID: method.id, location }, { signal }),
  ).pipe(Effect.tapCause(() => Effect.sync(() => progress.stop("Authentication failed", 1))))
  yield* Effect.addFinalizer(() =>
    request(() =>
      client.integration.command.cancel(
        {
          integrationID: integration.id,
          attemptID: started.data.attemptID,
          location,
        },
        { signal: AbortSignal.timeout(5_000) },
      ),
    ).pipe(Effect.ignore),
  )
  progress.stop("Authentication command started")
  // The status message accumulates the command's stderr; print each completed line once.
  let printed = 0
  log.step("Waiting for authentication command...")
  const status = yield* waitForCommand(client, integration.id, started.data.attemptID, (message) => {
    const end = message.lastIndexOf("\n") + 1
    if (end <= printed) return
    const output = message.slice(printed, end).trim()
    printed = end
    if (output) log.message(output)
  })
  if (status.status === "complete") {
    log.success(`Connected to ${integration.name}`)
    return
  }
  if (status.status === "failed") yield* Effect.fail(new Error(status.message))
  yield* Effect.fail(new Error("Authentication expired"))
})

const waitForOAuth = Effect.fn("cli.auth.login.oauth.wait")(function* (
  client: OpenCodeClient,
  integrationID: string,
  attemptID: string,
) {
  while (true) {
    const response = yield* request((signal) =>
      client.integration.oauth.status({ integrationID, attemptID, location }, { signal }),
    )
    if (response.data.status !== "pending") return response.data
    yield* Effect.sleep(500)
  }
})

const waitForCommand = Effect.fn("cli.auth.login.command.wait")(function* (
  client: OpenCodeClient,
  integrationID: string,
  attemptID: string,
  update: (message: string) => void,
) {
  while (true) {
    const response = yield* request((signal) =>
      client.integration.command.status({ integrationID, attemptID, location }, { signal }),
    )
    if (response.data.status !== "pending") return response.data
    if (response.data.message) update(response.data.message)
    yield* Effect.sleep(500)
  }
})

import { intro, outro, spinner } from "@clack/prompts"
import { Effect, Option } from "effect"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { handlePromptErrors, requireInteractive } from "../../../ui/prompt"
import { createClient, loadIntegrations, request } from "./shared"
import { chooseCredential, chooseIntegration } from "./account"

export default Runtime.handler(
  Commands.commands.auth.commands.logout,
  Effect.fn("cli.auth.logout")((input) =>
    logout({
      target: Option.getOrUndefined(input.target),
      credential: Option.getOrUndefined(input.credential),
      server: Option.getOrUndefined(input.server),
      standalone: input.standalone,
    }).pipe(handlePromptErrors),
  ),
)

const logout = Effect.fn("cli.auth.logout.run")(function* (input: {
  target?: string
  credential?: string
  server?: string
  standalone: boolean
}) {
  if (!input.target)
    yield* requireInteractive("Pass an integration ID or name when running without an interactive terminal")
  if (!input.credential)
    yield* requireInteractive("Pass a credential ID or label when running without an interactive terminal")
  intro("Log out of an account")
  const client = yield* createClient({ server: input.server, standalone: input.standalone })
  const integrations = yield* loadIntegrations(client)
  const integration = yield* chooseIntegration(integrations, input.target)
  const credentialID = yield* chooseCredential(integration, "log out", input.credential)
  const progress = spinner()
  progress.start("Removing credential...")
  yield* request((signal) => client.credential.remove({ credentialID }, { signal })).pipe(
    Effect.tap(() => Effect.sync(() => progress.stop(`Removed account from ${integration.name}`))),
    Effect.tapCause(() => Effect.sync(() => progress.stop("Failed to remove credential", 1))),
  )
  outro("Done")
})

import { Effect } from "effect"
import { OpenCode, type IntegrationInfo, type IntegrationMethod, type OpenCodeClient } from "@opencode/client"
import { Service } from "@opencode/client/effect/service"
import { ServerConnection } from "../../../services/server-connection"

export const location = { directory: process.cwd() }

export const createClient = Effect.fn("cli.auth.client")(function* (input: ServerConnection.Args) {
  const server = yield* ServerConnection.resolve(input)
  return OpenCode.make({ baseUrl: server.endpoint.url, headers: Service.headers(server.endpoint) })
})

export function request<A>(run: (signal: AbortSignal) => Promise<A>) {
  return Effect.tryPromise({ try: run, catch: (cause) => cause })
}

export const loadIntegrations = Effect.fn("cli.auth.integrations")(function* (client: OpenCodeClient) {
  // The model endpoint is the existing public readiness boundary for the initial plugin generation.
  yield* request((signal) => client.model.default({ location }, { signal }))
  return yield* request((signal) => client.integration.list({ location }, { signal })).pipe(
    Effect.map((response) =>
      response.data.toSorted((a, b) => Number(b.id === "opencode-go") - Number(a.id === "opencode-go")),
    ),
  )
})

export const resolveIntegration = Effect.fn("cli.auth.resolve-integration")(function* (
  integrations: IntegrationInfo[],
  target: string,
) {
  const normalized = target.replace(/\/+$/, "")
  const byID = integrations.find((integration) => integration.id === normalized)
  if (byID) return byID
  const matches = integrations.filter((integration) => integration.name.toLowerCase() === normalized.toLowerCase())
  if (matches.length === 1) return matches[0]
  if (matches.length > 1) {
    return yield* Effect.fail(
      new Error(
        `Integration name "${target}" is ambiguous: ${matches.map((integration) => integration.id).join(", ")}`,
      ),
    )
  }
  return yield* Effect.fail(new Error(`Integration not found: ${target}`))
})

export type ConnectMethod = Exclude<IntegrationMethod, { type: "env" }>

export function connectMethods(integration: IntegrationInfo) {
  return integration.methods
    .filter((method): method is ConnectMethod => method.type !== "env")
    .toSorted((a, b) => Number(a.type === "key") - Number(b.type === "key"))
}

export const resolveMethod = Effect.fn("cli.auth.resolve-method")(function* (methods: ConnectMethod[], target: string) {
  const normalized = target.toLowerCase()
  const matches = methods.filter((method) => {
    if (method.type === "key") return normalized === "key" || method.label?.toLowerCase() === normalized
    return method.id === target || method.label.toLowerCase() === normalized
  })
  if (matches.length === 1) return matches[0]
  if (matches.length > 1) return yield* Effect.fail(new Error(`Authentication method "${target}" is ambiguous`))
  const available = methods.map((method) => (method.type === "key" ? "key" : method.id)).join(", ")
  return yield* Effect.fail(
    new Error(`Authentication method not found: ${target}${available ? `. Available: ${available}` : ""}`),
  )
})

import { intro, outro, spinner } from "@clack/prompts"
import { Effect, Option } from "effect"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { handlePromptErrors, requireInteractive } from "../../../ui/prompt"
import { createClient, loadIntegrations, request } from "./shared"
import { chooseCredential, chooseIntegration } from "./account"

export default Runtime.handler(
  Commands.commands.auth.commands.switch,
  Effect.fn("cli.auth.switch")((input) =>
    switchAccount({
      target: Option.getOrUndefined(input.target),
      credential: Option.getOrUndefined(input.credential),
      server: Option.getOrUndefined(input.server),
      standalone: input.standalone,
    }).pipe(handlePromptErrors),
  ),
)

const switchAccount = Effect.fn("cli.auth.switch.run")(function* (input: {
  target?: string
  credential?: string
  server?: string
  standalone: boolean
}) {
  if (!input.target)
    yield* requireInteractive("Pass an integration ID or name when running without an interactive terminal")
  if (!input.credential)
    yield* requireInteractive("Pass a credential ID or label when running without an interactive terminal")
  intro("Switch account")
  const client = yield* createClient({ server: input.server, standalone: input.standalone })
  const integrations = yield* loadIntegrations(client)
  const integration = yield* chooseIntegration(integrations, input.target)
  const credentialID = yield* chooseCredential(integration, "switch to", input.credential)
  const progress = spinner()
  progress.start("Switching account...")
  yield* request((signal) => client.credential.activate({ credentialID }, { signal })).pipe(
    Effect.tap(() => Effect.sync(() => progress.stop(`Switched account for ${integration.name}`))),
    Effect.tapCause(() => Effect.sync(() => progress.stop("Failed to switch account", 1))),
  )
  outro("Done")
})

