// Redact only the debug output; the resolved configuration must remain usable by providers.
const secretName = /(?:api.?key|secret|password|token$|authorization$|cookie$|credential|private.?key)/i

export function redactConfig(value: unknown, headers = false): unknown {
  if (Array.isArray(value)) return value.map((item) => redactConfig(item, headers))
  if (value === null || typeof value !== "object") return value

  return Object.fromEntries(
    Object.entries(value).map(([key, item]) => {
      if (typeof item === "string" && (headers || secretName.test(key))) return [key, "***"]
      if (typeof item === "string" && /^https?:\/\//i.test(item)) {
        if (!URL.canParse(item)) return [key, "***"]
        const url = new URL(item)
        if (url.username || url.password || [...url.searchParams.keys()].some((name) => secretName.test(name)))
          return [key, "***"]
      }
      return [key, redactConfig(item, headers || key.toLowerCase() === "headers")]
    }),
  )
}

import { LayerNode } from "@opencode/util/effect/layer-node"
import { Global } from "@opencode/util/global"
import { run } from "@opencode/tui"
import { Commands } from "../commands"
import { Runtime } from "../../framework/runtime"
import { Config } from "../../config"
import { Context, Effect, FileSystem, Option, Queue, Schedule, Semaphore } from "effect"
import { ServerConnection } from "../../services/server-connection"
import { Updater } from "../../services/updater"
import { UpdatePreflight } from "../../services/update-preflight"
import { Npm } from "@opencode/util/npm"
import { OPENCODE_ARTIFACT, OPENCODE_CHANNEL, OPENCODE_HIGHLIGHTS, OPENCODE_VERSION } from "../../version"
import { Env } from "../../env"
import { Service } from "@opencode/client/effect/service"
import { OpenCode } from "@opencode/client/promise"
import { findSession } from "../../session-target"
import { errorMessage } from "../../util/error"

export default Runtime.handler(Commands, (input) =>
  Effect.gen(function* () {
    const requestedDirectory = Option.getOrUndefined(input.directory)
    const requestedServer = Option.getOrUndefined(input.server)
    if (requestedDirectory !== undefined) process.chdir(requestedDirectory)
    const preflight = UpdatePreflight.make()
    yield* Effect.addFinalizer(() => Effect.promise(() => preflight.close()))
    const serviceStarts = yield* Queue.unbounded<{
      readonly reason: "missing" | "version-mismatch"
      readonly previousVersion?: string
    }>()
    yield* Queue.take(serviceStarts).pipe(
      Effect.flatMap((event) => Effect.logInfo("background service starting", event)),
      Effect.forever,
      Effect.forkScoped,
    )
    const server = yield* ServerConnection.resolve({
      server: requestedServer,
      standalone: input.standalone,
      mismatch: "replace",
      onStart: (reason, previousVersion) => {
        Queue.offerUnsafe(serviceStarts, { reason, previousVersion })
        if (reason === "version-mismatch" && preflight.begin(previousVersion)) return
        process.stderr.write(
          reason === "version-mismatch"
            ? "Restarting background server (version mismatch)...\n"
            : "Starting background server...\n",
        )
      },
    }).pipe(
      Effect.tapError(() =>
        Effect.promise(() => preflight.fail("OpenCode update could not start the new background service")),
      ),
    )
    const session = Option.getOrUndefined(input.session)
    // A missing --session ID becomes the ID of the session the first prompt creates.
    const sessionExists =
      session !== undefined &&
      (yield* Effect.tryPromise({
        try: () =>
          findSession(OpenCode.make({ baseUrl: server.endpoint.url, headers: Service.headers(server.endpoint) }), session),
        catch: (cause) => new Error(errorMessage(cause)),
      })) !== undefined
    const updater = yield* Updater.Service
    let installing: string | undefined
    let latest: Updater.RunResult | undefined
    const installListeners = new Set<(version: string) => void>()
    const resultListeners = new Set<(result: Updater.RunResult) => void>()
    // Background checks, `/update` lookups, and manual installs take turns so two installs never overlap.
    const checking = yield* Semaphore.make(1)
    yield* updater
      .run((version) => {
        installing = version
        installListeners.forEach((notify) => notify(version))
      })
      .pipe(
        Effect.ensuring(Effect.sync(() => (installing = undefined))),
        Effect.tap((result) =>
          Effect.sync(() => {
            if (!result || (result.type === latest?.type && result.version === latest.version)) return
            latest = result
            resultListeners.forEach((notify) => notify(result))
          }),
        ),
        checking.withPermits(1),
        Effect.repeat(Schedule.spaced("10 minutes")),
        Effect.forkScoped({ startImmediately: true }),
      )
    preflight.loading()
    const config = yield* Config.Service
    const npm = yield* Npm.Service
    const fileSystem = yield* FileSystem.FileSystem
    const runServicePromise = Effect.runPromiseWith(Context.make(FileSystem.FileSystem, fileSystem))
    const context = yield* Effect.context<FileSystem.FileSystem>()
    const runFork = Effect.runForkWith(context)
    const runPromise = Effect.runPromiseWith(context)
    const service = server.service
    yield* run({
      app: {
        name: process.env.OPENCODE_CLIENT ?? OPENCODE_ARTIFACT,
        version: OPENCODE_VERSION,
        channel: process.env.OPENCODE_TUI_CHANNEL ?? OPENCODE_CHANNEL,
        highlights: OPENCODE_HIGHLIGHTS,
      },
      server: {
        endpoint: server.endpoint,
        service: service
          ? {
              reconnect: (signal) => runServicePromise(service.reconnect(), { signal }),
              restart: () => runServicePromise(service.restart()),
            }
          : undefined,
      },
      args: {
        continue: input.continue,
        sessionID: sessionExists ? session : undefined,
        newSessionID: sessionExists ? undefined : session,
        prompt: Option.getOrUndefined(input.prompt),
        auto: input.auto || input.yolo || input.dangerouslySkipPermissions,
      },
      config: {
        path: config.path,
        get: () => runPromise(config.get()),
        update: (update) => runPromise(config.update(update)),
      },
      updater: {
        remote: requestedServer !== undefined,
        subscribe: (notify) => {
          if (latest) notify(latest)
          resultListeners.add(notify)
          return () => resultListeners.delete(notify)
        },
        check: (signal, notify) => {
          if (installing) notify(installing)
          installListeners.add(notify)
          return runPromise(checking.withPermits(1)(updater.check()), { signal }).finally(() =>
            installListeners.delete(notify),
          )
        },
        apply: (version) => runPromise(checking.withPermits(1)(updater.apply(version))),
      },
      packages: {
        prepare: (spec, install = true) => runPromise(install ? npm.add(spec) : npm.resolve(spec)),
      },
      environment: requestedServer === undefined ? Env.session() : undefined,
      terminalHandoff: () => preflight.finish(),
      log: (level, message, tags) => {
        const effect =
          level === "debug"
            ? Effect.logDebug(message, tags)
            : level === "warn"
              ? Effect.logWarning(message, tags)
              : level === "error"
                ? Effect.logError(message, tags)
                : Effect.logInfo(message, tags)
        runFork(effect)
      },
    }).pipe(Effect.provide(LayerNode.compile(Global.node)))
  }),
)

import { EOL } from "node:os"
import path from "node:path"
import { readFile, stat, writeFile } from "node:fs/promises"
import { Effect, Option } from "effect"
import { applyEdits, modify } from "jsonc-parser"
import { Global } from "@opencode/util/global"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"

export default Runtime.handler(
  Commands.commands.mcp.commands.add,
  Effect.fn("cli.mcp.add")(function* (input) {
    const url = Option.getOrUndefined(input.url)
    const headers = Option.getOrUndefined(input.header)
    const environment = Option.getOrUndefined(input.env)
    // The CLI framework strands `--` operands on the root command, so read the local server command
    // straight from argv after `--`. This also lets the command carry its own flags (e.g. `npx -y`).
    const dash = process.argv.indexOf("--")
    const command = dash === -1 ? [...input.command] : process.argv.slice(dash + 1)

    const hasCommand = command.length > 0
    if (url && hasCommand)
      return yield* Effect.fail(new Error("Provide either --url <url> or a command after --, not both"))
    if (!url && !hasCommand) return yield* Effect.fail(new Error("Provide either --url <url> or a command after --"))
    if (url && !URL.canParse(url)) return yield* Effect.fail(new Error(`Invalid URL: ${url}`))
    if (url && environment) return yield* Effect.fail(new Error("--env is only valid for local MCP servers"))
    if (hasCommand && headers) return yield* Effect.fail(new Error("--header is only valid for remote MCP servers"))

    const server = url
      ? { type: "remote" as const, url, ...(headers ? { headers } : {}) }
      : { type: "local" as const, command, ...(environment ? { environment } : {}) }

    const global = yield* Global.Service
    const configPath = yield* Effect.promise(() => resolveConfigPath(input.global ? global.config : process.cwd()))
    yield* Effect.promise(() => write(configPath, input.name, server))
    process.stdout.write(`MCP server "${input.name}" added to ${configPath}` + EOL)
  }),
)

export async function resolveConfigPath(directory: string) {
  const candidates = [
    path.join(directory, "opencode.json"),
    path.join(directory, "opencode.jsonc"),
    path.join(directory, ".opencode", "opencode.json"),
    path.join(directory, ".opencode", "opencode.jsonc"),
  ]
  for (const candidate of candidates) {
    if (
      await stat(candidate).then(
        (info) => info.isFile(),
        () => false,
      )
    )
      return candidate
  }
  return candidates[0]
}

async function write(configPath: string, name: string, server: unknown) {
  const text = await readFile(configPath, "utf8").catch((error) => {
    if (typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT") return "{}"
    throw error
  })
  const edits = modify(text, ["mcp", "servers", name], server, {
    formattingOptions: { tabSize: 2, insertSpaces: true },
  })
  await writeFile(configPath, applyEdits(text, edits))
}

import { confirm, intro, log, outro } from "@clack/prompts"
import { Effect, Option } from "effect"
import { OpenCode, type IntegrationInfo, type IntegrationOAuthMethod, type McpServer } from "@opencode/client"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { Service } from "@opencode/client/effect/service"
import { ServerConnection } from "../../../services/server-connection"
import { selectIntegration, type IntegrationChoice } from "../../../ui/integration-picker"
import { handlePromptErrors, prompt, requireInteractive } from "../../../ui/prompt"
import { answerForm } from "../auth/form"
import { oauthLogin } from "../auth/login"
import { loadIntegrations, request } from "../auth/shared"

const location = { directory: process.cwd() }

export default Runtime.handler(
  Commands.commands.mcp.commands.auth,
  Effect.fn("cli.mcp.auth")((input) => authenticate(Option.getOrUndefined(input.name)).pipe(handlePromptErrors)),
)

const authenticate = Effect.fn("cli.mcp.auth.run")(function* (name?: string) {
  if (!name) yield* requireInteractive("Pass an MCP server name when running without an interactive terminal")
  intro("Authenticate an MCP server")
  const { endpoint } = yield* ServerConnection.resolve()
  const client = OpenCode.make({ baseUrl: endpoint.url, headers: Service.headers(endpoint) })
  const integrations = yield* loadIntegrations(client)
  const servers = yield* request((signal) => client.mcp.list({ location }, { signal }))
  const choices = mcpAuthChoices(servers.data, integrations)
  if (!name && choices.length === 0) {
    log.warn("No OAuth-capable MCP servers configured")
    log.info(
      `Remote MCP servers support OAuth by default. Add one with \`opencode mcp add\` or in opencode.json:\n${exampleConfig}`,
    )
    outro("Done")
    return
  }

  const server = name ? servers.data.find((item) => item.name === name) : undefined
  if (name && !server) return yield* Effect.fail(new Error(`MCP server not found: ${name}`))
  const integrationID = server
    ? server.integrationID
    : yield* prompt<string>(() => selectIntegration(choices, "MCP server"))
  const integration = integrations.find((item) => item.id === integrationID)
  const method = integration?.methods.find(
    (candidate): candidate is IntegrationOAuthMethod => candidate.type === "oauth",
  )
  if (!integration || !method)
    return yield* Effect.fail(new Error(`MCP server "${name}" is not an OAuth-capable remote server`))

  if (integration.connections.length > 0) {
    const status = servers.data.find((item) => item.integrationID === integration.id)?.status.status
    if (status === "needs_auth") log.warn(`${integration.name} has expired credentials. Re-authenticating...`)
    if (status !== "needs_auth" && process.stdin.isTTY && process.stdout.isTTY) {
      const again = yield* prompt<boolean>(() =>
        confirm({ message: `${integration.name} already has valid credentials. Re-authenticate?` }),
      )
      if (!again) {
        outro("Cancelled")
        return
      }
    }
  }

  // Re-authenticating replaces the previous sign-in rather than adding an account. The new credential
  // keeps the active one's label, and the old ones are only removed once it is stored, so a failed
  // attempt keeps them.
  const previous = integration.connections.filter((connection) => connection.type === "credential")
  yield* oauthLogin(client, integration, method, yield* answerForm(method.form), previous[0]?.label)
  yield* Effect.forEach(
    previous,
    (connection) => request((signal) => client.credential.remove({ credentialID: connection.id }, { signal })),
    { discard: true },
  )
  outro("Done")
})

const exampleConfig = `
  "mcp": {
    "servers": {
      "my-server": {
        "type": "remote",
        "url": "https://example.com/mcp"
      }
    }
  }`

// Choices carry the server-owned integration ID so provider integrations with colliding names never match.
export function mcpAuthChoices(servers: McpServer[], integrations: IntegrationInfo[]): IntegrationChoice[] {
  const byID = new Map(integrations.map((integration) => [integration.id, integration]))
  return servers
    .flatMap((server) => {
      const integration = server.integrationID ? byID.get(server.integrationID) : undefined
      if (!integration?.methods.some((method) => method.type === "oauth")) return []
      return [
        {
          value: integration.id,
          label: server.name,
          category: "MCP" as const,
          connected: integration.connections.length > 0,
          hint: statusHint(server.status),
        },
      ]
    })
    .toSorted((a, b) => a.label.localeCompare(b.label) || a.value.localeCompare(b.value))
}

function statusHint(status: McpServer["status"]) {
  if (status.status === "needs_auth") return "needs authentication"
  if (status.status === "failed" || status.status === "disabled") return status.status
  return undefined
}

import { EOL } from "node:os"
import { Effect } from "effect"
import { OpenCode, type McpServer } from "@opencode/client"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { Service } from "@opencode/client/effect/service"
import { ServerConnection } from "../../../services/server-connection"

export default Runtime.handler(
  Commands.commands.mcp.commands.list,
  Effect.fn("cli.mcp.list")(function* () {
    const { endpoint } = yield* ServerConnection.resolve()
    const client = OpenCode.make({ baseUrl: endpoint.url, headers: Service.headers(endpoint) })
    const response = yield* Effect.promise(() => client.mcp.list({ location: { directory: process.cwd() } }))
    const servers = response.data.toSorted((a, b) => a.name.localeCompare(b.name))
    if (servers.length === 0) {
      process.stdout.write("No MCP servers configured" + EOL)
      return
    }
    const width = Math.max(...servers.map((server) => server.name.length))
    const lines = servers.map(
      (server) => `${icon(server.status)} ${server.name.padEnd(width)}  ${describe(server.status)}`,
    )
    process.stdout.write(lines.join(EOL) + EOL)
  }),
)

function icon(status: McpServer["status"]) {
  switch (status.status) {
    case "connected":
      return "✓"
    case "needs_auth":
      return "⚠"
    case "failed":
      return "✗"
    default:
      return "○"
  }
}

function describe(status: McpServer["status"]) {
  switch (status.status) {
    case "needs_auth":
      return "needs authentication"
    case "failed":
      return `failed: ${status.error}`
    default:
      return status.status
  }
}

