export default Runtime.handler(
  Commands.commands.pair,
  Effect.fn("cli.pair")(function* (input: Runtime.Input<typeof Commands.commands.pair>) {
    const config = yield* ServiceConfig.read()
    if (config.disabled === true)
      return yield* Effect.fail(
        new Error("Pairing requires the background service; run `opencode service unset disabled` first"),
      )
    if (input.remote && Option.isSome(input.url))
      return yield* Effect.fail(new Error("--remote cannot be combined with --url"))
    if (input.remote && config.remote === undefined) {
      if (!(yield* remoteConsent(config, input))) return
      // Changing the setting restarts the service, and the ensure below starts it again with the tunnel.
      yield* ServiceConfig.set("remote", "true")
    }
    const endpoint = yield* Service.ensure(yield* ServiceConfig.options())
    const client = OpenCode.make({ baseUrl: endpoint.url, headers: Service.headers(endpoint) })
    const urls = yield* pairingURLs(client, input)
    const pairing = yield* Effect.tryPromise(() => client.server.pair())
    const links = urls.map((url) => new URL(`/auth/connect/${pairing.code}`, url).href)
    // Loopback URLs are useless to the scanning device, so the QR code only carries reachable addresses.
    const remote = urls.filter((url) => !isLoopback(new URL(url).hostname))
    process.stdout.write(
      [
        "",
        `  Open a link to connect. Links work once and expire in ${Math.round(pairing.expires_in / 60)} minutes.`,
        "",
        ...(links.length ? links.map((link) => `  ${link}`) : ["  (no server URLs)"]),
        ...(remote.length
          ? [
              "",
              // uqr separates rows with "\n" on every platform, so splitting on EOL ("\r\n" on Windows) indents only the first row.
              renderUnicodeCompact(JSON.stringify({ code: pairing.code, urls: remote }), {
                border: 2,
              })
                .split("\n")
                .map((line) => "  " + line)
                .join(EOL),
            ]
          : []),
        "",
      ].join(EOL) + EOL,
    )

    if (input.remote || Option.isSome(input.url)) return
    const url = new URL(endpoint.url)
    if (!["localhost", "127.0.0.1", "[::1]"].includes(url.hostname)) return
    process.stderr.write(
      [
        `  Over SSH? Forward the port, then open the link on your machine:`,
        `  ssh -L ${url.port}:${url.hostname}:${url.port} <host>`,
        `  If port ${url.port} is busy locally, forward another port and use it in the link.`,
        "",
        "  To connect from other devices, run `opencode service set hostname 0.0.0.0`.",
        "",
      ].join(EOL) + EOL,
    )
  }),
)

export const remoteWarning = [
  "This will expose your OpenCode server to the internet.",
  "Traffic is end-to-end encrypted, and access requires your server password.",
  "To pair locally instead, run `opencode pair` without the --remote flag.",
].join(EOL)

export interface RemoteConsentPrompt {
  readonly interactive: () => boolean
  readonly confirm: () => Promise<boolean | symbol>
}

const terminalPrompt: RemoteConsentPrompt = {
  interactive: () => Boolean(process.stdin.isTTY && process.stdout.isTTY),
  confirm: () => confirm({ message: "Expose your server to the internet?", initialValue: true }),
}

// Remote access is only explained and accepted the first time it is turned on; once accepted, pairing goes straight
// through. Returns whether remote access may be enabled.
export const remoteConsent = Effect.fn("cli.pair.remote-consent")(function* (
  config: ServiceConfig.Info,
  input: { readonly yes: boolean },
  terminal: RemoteConsentPrompt = terminalPrompt,
) {
  if (config.remote !== undefined || config.remoteAccepted === true) return true
  if (!input.yes && !terminal.interactive()) {
    process.stderr.write([remoteWarning, "Run interactively or pass --yes to continue."].join(EOL) + EOL)
    process.exitCode = 1
    return false
  }
  log.warn(remoteWarning)
  if (!input.yes) {
    const accepted = yield* Effect.promise(terminal.confirm)
    if (isCancel(accepted)) {
      cancel("Remote access was not enabled. To pair locally, run `opencode pair`.")
      process.exitCode = 130
      return false
    }
    if (accepted !== true) {
      log.info("Remote access was not enabled. To pair locally, run `opencode pair`.")
      return false
    }
  }
  yield* ServiceConfig.acceptRemote()
  return true
})

const pairingURLs = Effect.fnUntraced(function* (
  client: ReturnType<typeof OpenCode.make>,
  input: Runtime.Input<typeof Commands.commands.pair>,
) {
  if (input.remote) return [yield* remoteURL(client)]
  if (Option.isSome(input.url)) return [input.url.value]
  return (yield* Effect.tryPromise(() => client.server.info())).urls
})

// The service attaches the tunnel in the background, so wait for its URL to appear in server info.
const remoteURL = Effect.fnUntraced(function* (client: ReturnType<typeof OpenCode.make>) {
  const tunnelURL = Effect.gen(function* () {
    const route = (yield* ServiceConfig.read()).remote?.route
    const hostname = route === undefined ? undefined : yield* RemoteTunnel.hostname(route)
    const info = yield* Effect.tryPromise(() => client.server.info())
    const url = info.urls.find((candidate) => hostname !== undefined && new URL(candidate).hostname === hostname)
    if (url === undefined) return yield* Effect.fail(new Error("Remote tunnel is not ready"))
    return url
  })
  return yield* tunnelURL.pipe(
    Effect.retry({ schedule: Schedule.spaced("1 second") }),
    Effect.timeoutOrElse({
      duration: "3 minutes",
      orElse: () =>
        Effect.fail(new Error("Timed out waiting for the remote tunnel; run `opencode pair --remote` again to retry")),
    }),
  )
})

function isLoopback(hostname: string) {
  return (
    hostname === "localhost" || hostname.endsWith(".localhost") || hostname.startsWith("127.") || hostname === "[::1]"
  )
}

import { EOL } from "node:os"
import path from "node:path"
import { mkdir, readFile, rename, writeFile } from "node:fs/promises"
import { Effect } from "effect"
import { applyEdits, modify, parse, type ParseError } from "jsonc-parser"
import { Global } from "@opencode/util/global"
import { Npm } from "@opencode/util/npm"
import { Host } from "@opencode/plugin/host"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { resolveConfigPath } from "../mcp/add"
import { Config } from "../../../config"

export default Runtime.handler(
  Commands.commands.plugin.commands.add,
  Effect.fn("cli.plugin.add")(function* (input) {
    if (!(yield* Effect.promise(() => Npm.isInstallablePackage(input.package))))
      return yield* Effect.fail(new Error("Plugin target must be an npm registry package or Git package specifier"))
    const npm = yield* Npm.Service
    const installed = yield* npm.add(input.package)
    const entrypoints = Host.resolve(installed)
    const target = configurationTarget(entrypoints.server, entrypoints.tui)
    if (!target)
      return yield* Effect.fail(new Error(`Plugin package has no server or TUI entrypoint: ${input.package}`))

    if (target === "server") {
      const global = yield* Global.Service
      const configPath = yield* Effect.promise(() => resolveConfigPath(global.config))
      const changed = yield* Effect.promise(() => writePluginConfig(configPath, input.package))
      process.stdout.write(
        changed
          ? `Plugin "${input.package}" installed and added to ${configPath}${EOL}`
          : `Plugin "${input.package}" is already configured in ${configPath}${EOL}`,
      )
      return
    }

    const config = yield* Config.Service
    yield* config.update((draft) => {
      if (configured(draft.plugins, input.package)) return
      draft.plugins = [...(draft.plugins ?? []), input.package]
    })
    process.stdout.write(`TUI plugin "${input.package}" installed and added to ${config.path}${EOL}`)
  }),
)

export function configurationTarget(server?: string, tui?: string) {
  if (server) return "server" as const
  if (tui) return "tui" as const
}

export async function writePluginConfig(configPath: string, spec: string) {
  const text = await readFile(configPath, "utf8").catch((error) => {
    if (typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT") return "{}"
    throw error
  })
  const errors: ParseError[] = []
  const config: unknown = parse(text, errors, { allowTrailingComma: true })
  if (errors.length || typeof config !== "object" || config === null || Array.isArray(config))
    throw new Error(`Invalid global configuration: ${configPath}`)
  const plugins = "plugins" in config ? config.plugins : undefined
  if (plugins !== undefined && !Array.isArray(plugins)) throw new Error(`Invalid plugins configuration: ${configPath}`)
  if (configured(plugins, spec)) return false

  const updated = applyEdits(
    text,
    modify(text, ["plugins"], [...(plugins ?? []), spec], { formattingOptions: { tabSize: 2, insertSpaces: true } }),
  )
  await mkdir(path.dirname(configPath), { recursive: true })
  const temporary = configPath + ".tmp"
  await writeFile(temporary, updated.endsWith("\n") ? updated : updated + "\n", { mode: 0o600 })
  await rename(temporary, configPath)
  return true
}

function configured(plugins: readonly unknown[] | undefined, spec: string) {
  return plugins?.some(
    (entry) =>
      entry === spec || (typeof entry === "object" && entry !== null && "package" in entry && entry.package === spec),
  )
}

import { EOL } from "node:os"
import { Effect, Option } from "effect"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { format, inspect } from "./inventory"

export default Runtime.handler(
  Commands.commands.plugin.commands.check,
  Effect.fn("cli.plugin.check")(function* (input) {
    const result = yield* inspect(Option.getOrUndefined(input.target))
    process.stdout.write((format(result.items) || "No package plugins found") + EOL)
    if (result.items.some((item) => item.error)) process.exitCode = 1
  }),
)

import { EOL } from "node:os"
import { Cause, Effect, Exit } from "effect"
import { OpenCode } from "@opencode/client"
import { Service } from "@opencode/client/effect/service"
import { Npm } from "@opencode/util/npm"
import { Config } from "../../../config"
import { ServerConnection } from "../../../services/server-connection"

export interface Item {
  readonly runtime: "Server" | "TUI"
  readonly target: string
  readonly name: string
  readonly version?: string
  readonly outdated: boolean
  readonly error?: string
}

export const inspect = Effect.fn("cli.plugin.inspect")(function* (selected?: string) {
  const { endpoint } = yield* ServerConnection.resolve()
  const client = OpenCode.make({ baseUrl: endpoint.url, headers: Service.headers(endpoint) })
  const location = { directory: process.cwd() }
  const listed = yield* Effect.promise(() => client.plugin.list({ location }))
  const serverTargets = new Set(
    listed.data.flatMap((plugin) => (plugin.source.type === "package" ? [plugin.source.target] : [])),
  )
  const server =
    selected === undefined || serverTargets.has(selected)
      ? yield* Effect.promise(() => client.plugin.check({ location, ...(selected ? { target: selected } : {}) }))
      : listed
  const serverItems = server.data.flatMap((plugin): Item[] => {
    if (plugin.source.type !== "package") return []
    if (selected !== undefined && plugin.source.target !== selected) return []
    return [
      {
        runtime: "Server",
        target: plugin.source.target,
        name: plugin.id ?? plugin.source.target,
        ...(plugin.source.version ? { version: displayVersion(plugin.source.version) } : {}),
        outdated: plugin.source.outdated === true,
        ...(plugin.state.status === "failed" ? { error: plugin.state.error } : {}),
      },
    ]
  })

  const config = yield* Config.Service
  const info = yield* config.get()
  const configured = [
    ...new Set(
      (info.plugins ?? []).flatMap((entry) => {
        const target = typeof entry === "string" ? entry : entry.package
        if (target.startsWith("-") || target === "*" || target.endsWith(".*") || target.startsWith("opencode.")) return []
        return [target]
      }),
    ),
  ]
  const tuiTargets = yield* Effect.promise(async () => {
    const installable = await Promise.all(configured.map((target) => Npm.isInstallablePackage(target)))
    return configured.filter((target, index) => installable[index] && (selected === undefined || target === selected))
  })
  const npm = yield* Npm.Service
  const tuiItems = yield* Effect.forEach(
    tuiTargets,
    (target) =>
      Effect.gen(function* () {
        const installed = yield* npm.resolve(target)
        const outdated = yield* npm.check(target).pipe(Effect.exit)
        return {
          runtime: "TUI" as const,
          target,
          name: target,
          ...(installed.version ? { version: displayVersion(installed.version) } : {}),
          outdated: Exit.isSuccess(outdated) && outdated.value,
          ...(Exit.isFailure(outdated) ? { error: Cause.pretty(outdated.cause) } : {}),
        }
      }),
    { concurrency: "unbounded" },
  )
  const items = [...serverItems, ...tuiItems]
  if (selected !== undefined && !items.length) return yield* Effect.fail(new Error(`Plugin is not configured: ${selected}`))
  return { client, location, items }
})

export function displayVersion(version: string) {
  return /^(?:[a-f0-9]{40}|[a-f0-9]{64})$/i.test(version) ? version.slice(0, 7) : version
}

export function format(items: readonly Item[]) {
  return ["Server", "TUI"]
    .flatMap((runtime) => {
      const rows = items.filter((item) => item.runtime === runtime)
      if (!rows.length) return []
      return [
        runtime,
        ...rows.map(
          (item) =>
            `  ${item.name}${item.version ? ` ${item.version}` : ""} (${item.error ? "check failed" : item.outdated ? "update available" : "current"})`,
        ),
      ]
    })
    .join(EOL)
}

import { EOL } from "node:os"
import path from "node:path"
import { Effect } from "effect"
import { OpenCode, type PluginInfo } from "@opencode/client"
import { Service } from "@opencode/client/effect/service"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { ServerConnection } from "../../../services/server-connection"
import { Config } from "../../../config"
import { Global } from "@opencode/util/global"
import { Npm } from "@opencode/util/npm"
import { Host } from "@opencode/plugin/host"
import { fileURLToPath } from "node:url"
import { discoverPluginTargets, localPluginDirectories, localSource } from "@opencode/tui/plugin/discovery"

export default Runtime.handler(
  Commands.commands.plugin.commands.list,
  Effect.fn("cli.plugin.list")(function* (input) {
    const { endpoint } = yield* ServerConnection.resolve()
    const client = OpenCode.make({ baseUrl: endpoint.url, headers: Service.headers(endpoint) })
    const response = yield* Effect.promise(() => client.plugin.list({ location: { directory: process.cwd() } }))
    const config = yield* Config.Service
    const global = yield* Global.Service
    const info = yield* config.get()
    const discovered = yield* Effect.promise(() =>
      localPluginDirectories(process.cwd(), global.config).then(discoverPluginTargets),
    )
    const npm = yield* Npm.Service
    const configured = yield* Effect.forEach([...(info.plugins ?? []), ...discovered], (entry) =>
      Effect.gen(function* () {
        const target = typeof entry === "string" ? entry : entry.package
        if (target.startsWith("-") || target === "*" || target.endsWith(".*") || target.startsWith("opencode."))
          return []
        const local = localSource(target, path.dirname(config.path))
        if (local) {
          const directory = fileURLToPath(local)
          const entrypoints = Host.resolve({ directory })
          return entrypoints.tui ? [{ target: directory, version: "local" }] : []
        }
        if (!(yield* Effect.promise(() => Npm.isInstallablePackage(target)))) return []
        const installed = yield* npm.resolve(target)
        if (!Host.resolve(installed).tui) return []
        return [{ target, version: installed.version }]
      }),
    )
    const output = format(response.data, configured.flat(), input.builtin)
    if (!output) {
      process.stdout.write("No plugins found" + EOL)
      return
    }
    process.stdout.write(output + EOL)
  }),
)

export function format(
  plugins: readonly PluginInfo[],
  tui: ReadonlyArray<{ readonly target: string; readonly version?: string }>,
  builtin = false,
) {
  const server = plugins
    .filter((plugin) => builtin || plugin.source.type !== "builtin")
    .map((plugin) => ({
      id: plugin.id ?? "-",
      version:
        plugin.source.type === "package"
          ? (plugin.source.version ?? "-")
          : plugin.source.type === "local"
            ? "local"
            : "-",
      target:
        plugin.source.type === "package"
          ? plugin.source.target
          : plugin.source.type === "local"
            ? plugin.source.path
            : plugin.source.type,
    }))
  const targets = tui
    .filter(
      (item) =>
        !plugins.some((plugin) =>
          plugin.source.type === "package"
            ? plugin.source.target === item.target
            : plugin.source.type === "local" &&
              (plugin.source.path === item.target ||
                (plugin.features.tui && path.dirname(plugin.source.path) === item.target)),
        ),
    )
    .filter((plugin, index, all) => all.findIndex((candidate) => candidate.target === plugin.target) === index)
    .map((plugin) => ({ id: "-", version: plugin.version ?? "-", target: plugin.target }))
  const rows = [...server, ...targets]
    .toSorted((a, b) => a.id.localeCompare(b.id) || a.target.localeCompare(b.target))
    .map((item) => [
      item.id,
      /^(?:[a-f0-9]{40}|[a-f0-9]{64})$/i.test(item.version) ? item.version.slice(0, 7) : item.version,
      item.target,
    ])
  if (!rows.length) return ""
  const table = [["ID", "VERSION", "SOURCE"], ...rows]
  const widths = [0, 1].map((index) => Math.max(...table.map((row) => row[index].length)))
  return table.map((row) => `${row[0].padEnd(widths[0])}  ${row[1].padEnd(widths[1])}  ${row[2]}`).join(EOL)
}

import { EOL } from "node:os"
import { readFile, rename, writeFile } from "node:fs/promises"
import { Effect } from "effect"
import { applyEdits, modify, parse, type ParseError } from "jsonc-parser"
import { Global } from "@opencode/util/global"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { Config } from "../../../config"
import { resolveConfigPath } from "../mcp/add"

export default Runtime.handler(
  Commands.commands.plugin.commands.remove,
  Effect.fn("cli.plugin.remove")(function* (input) {
    const global = yield* Global.Service
    const configPath = yield* Effect.promise(() => resolveConfigPath(global.config))
    const server = yield* Effect.promise(() => removePluginConfig(configPath, input.package))
    const config = yield* Config.Service
    const info = yield* config.get()
    const tui = configured(info.plugins, input.package)
    if (tui)
      yield* config.update((draft) => {
        draft.plugins = draft.plugins?.filter((entry) => !matches(entry, input.package))
      })

    const removed = [server ? configPath : undefined, tui ? config.path : undefined].filter(
      (file) => file !== undefined,
    )
    process.stdout.write(
      removed.length
        ? `Plugin "${input.package}" removed from ${removed.join(", ")}${EOL}`
        : `Plugin "${input.package}" is not configured${EOL}`,
    )
  }),
)

export async function removePluginConfig(configPath: string, spec: string) {
  const text = await readFile(configPath, "utf8").catch((error) => {
    if (typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT") return undefined
    throw error
  })
  if (text === undefined) return false
  const errors: ParseError[] = []
  const config: unknown = parse(text, errors, { allowTrailingComma: true })
  if (errors.length || typeof config !== "object" || config === null || Array.isArray(config))
    throw new Error(`Invalid global configuration: ${configPath}`)
  const plugins = "plugins" in config ? config.plugins : undefined
  if (plugins !== undefined && !Array.isArray(plugins)) throw new Error(`Invalid plugins configuration: ${configPath}`)
  if (!configured(plugins, spec)) return false

  const updated = applyEdits(
    text,
    modify(
      text,
      ["plugins"],
      plugins?.filter((entry) => !matches(entry, spec)),
      {
        formattingOptions: { tabSize: 2, insertSpaces: true },
      },
    ),
  )
  const temporary = configPath + ".tmp"
  await writeFile(temporary, updated.endsWith("\n") ? updated : updated + "\n", { mode: 0o600 })
  await rename(temporary, configPath)
  return true
}

function configured(plugins: readonly unknown[] | undefined, spec: string) {
  return plugins?.some((entry) => matches(entry, spec)) ?? false
}

function matches(entry: unknown, spec: string) {
  return entry === spec || (typeof entry === "object" && entry !== null && "package" in entry && entry.package === spec)
}

import { EOL } from "node:os"
import { Cause, Effect, Exit, Option } from "effect"
import { Npm } from "@opencode/util/npm"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { inspect } from "./inventory"

export default Runtime.handler(
  Commands.commands.plugin.commands.update,
  Effect.fn("cli.plugin.update")(function* (input) {
    const result = yield* inspect(Option.getOrUndefined(input.target))
    for (const item of result.items) {
      if (!item.error) continue
      process.stderr.write(`Failed to check ${item.runtime} plugin "${item.name}": ${item.error}${EOL}`)
    }
    const selected = result.items.filter((item) => item.outdated)
    if (!selected.length) {
      process.stdout.write("No plugin updates available" + EOL)
      if (result.items.some((item) => item.error)) process.exitCode = 1
      return
    }

    const npm = yield* Npm.Service
    const updated = yield* Effect.forEach(
      selected,
      (item) =>
        (item.runtime === "Server"
          ? Effect.promise(() => result.client.plugin.update({ location: result.location, targets: [item.target] }))
          : npm.update(item.target).pipe(Effect.asVoid)
        ).pipe(
          Effect.exit,
          Effect.map((result) => ({ item, result })),
        ),
      { concurrency: "unbounded" },
    )
    for (const item of updated) {
      if (Exit.isSuccess(item.result)) {
        process.stdout.write(`Updated ${item.item.runtime} plugin "${item.item.name}"${EOL}`)
        continue
      }
      process.stderr.write(
        `Failed to update ${item.item.runtime} plugin "${item.item.name}": ${Cause.pretty(item.result.cause)}${EOL}`,
      )
      process.exitCode = 1
    }
  }),
)

import { EOL } from "node:os"
