import { OpenCode } from "@opencode/client"
import { Service } from "@opencode/client/effect/service"
import { Effect, Option } from "effect"
import { EOL } from "node:os"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { ServerConnection } from "../../../services/server-connection"
import { errorMessage } from "../../../util/error"

const handler = Effect.fn("cli.session.delete")(function* (
  input: Runtime.Input<typeof Commands.commands.session.commands.delete>,
) {
  const server = yield* ServerConnection.resolve({
    server: Option.getOrUndefined(input.server),
    standalone: input.standalone,
  })
  const client = OpenCode.make({ baseUrl: server.endpoint.url, headers: Service.headers(server.endpoint) })
  yield* Effect.tryPromise({
    try: (signal) => client.session.remove({ sessionID: input.sessionID }, { signal }),
    catch: (cause) => cause,
  })
  process.stdout.write(`Session ${input.sessionID} deleted${EOL}`)
})

export default Runtime.handler(Commands.commands.session.commands.delete, (input) =>
  handler(input).pipe(
    Effect.catch((error) =>
      Effect.sync(() => {
        process.stderr.write(errorMessage(error) + EOL)
        process.exitCode = 1
      }),
    ),
  ),
)

import { autocomplete, cancel, intro, isCancel, log, outro } from "@clack/prompts"
import { OpenCode } from "@opencode/client"
import { Service } from "@opencode/client/effect/service"
import { Effect, Option } from "effect"
import { EOL } from "node:os"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { ServerConnection } from "../../../services/server-connection"
import { errorMessage } from "../../../util/error"

export default Runtime.handler(
  Commands.commands.session.commands.export,
  Effect.fn("cli.session.export")((input) =>
    Effect.gen(function* () {
      const requested = Option.getOrUndefined(input.session)
      if (!requested && !process.stdin.isTTY) {
        yield* Effect.fail(new Error("Pass a session ID when running without an interactive terminal"))
      }
      const server = yield* ServerConnection.resolve({
        server: Option.getOrUndefined(input.server),
        standalone: input.standalone,
      })
      const client = OpenCode.make({
        baseUrl: server.endpoint.url,
        headers: Service.headers(server.endpoint),
      })
      const sessionID = requested
        ? requested
        : yield* Effect.gen(function* () {
            intro("Export session", { output: process.stderr })
            const location = yield* Effect.tryPromise({
              try: () => client.location.get({ location: { directory: process.cwd() } }),
              catch: (cause) => cause,
            })
            const page = yield* Effect.tryPromise({
              try: () =>
                client.session.list({
                  directory: location.directory,
                  parentID: null,
                  order: "desc",
                  limit: 50,
                }),
              catch: (cause) => cause,
            })
            if (page.data.length === 0) {
              log.error("No sessions found", { output: process.stderr })
              outro("Done", { output: process.stderr })
              return undefined
            }
            const selected = yield* Effect.tryPromise({
              try: () =>
                autocomplete({
                  message: "Select session to export",
                  maxItems: 10,
                  options: page.data.map((session) => ({
                    label: session.title,
                    value: session.id,
                    hint: `${new Date(session.time.updated).toLocaleString()} - ${session.id.slice(-8)}`,
                  })),
                  output: process.stderr,
                }),
              catch: (cause) => cause,
            })
            if (isCancel(selected)) {
              cancel("Cancelled", { output: process.stderr })
              process.exitCode = 130
              return undefined
            }
            outro("Exporting session...", { output: process.stderr })
            return selected
          })
      if (!sessionID) return
      const data = yield* Effect.tryPromise({
        try: () => client.session.export({ sessionID, sanitize: input.sanitize }),
        catch: (cause) => cause,
      })
      process.stdout.write(JSON.stringify(data, null, 2) + EOL)
    }).pipe(
      Effect.catch((error) =>
        Effect.sync(() => {
          process.stderr.write(errorMessage(error) + EOL)
          process.exitCode = 1
        }),
      ),
    ),
  ),
)

import { OpenCode } from "@opencode/client"
import { Service } from "@opencode/client/effect/service"
import { Session } from "@opencode/schema/session"
import { SessionTransfer } from "@opencode/schema/session-transfer"
import { Effect, Option, Schema } from "effect"
import { EOL } from "node:os"
import path from "node:path"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { ServerConnection } from "../../../services/server-connection"

export default Runtime.handler(
  Commands.commands.session.commands.import,
  Effect.fn("cli.session.import")(function* (input) {
    const text = yield* Effect.tryPromise({
      try: () =>
        input.file.startsWith("http://") || input.file.startsWith("https://")
          ? fetch(input.file).then((response) => {
              if (!response.ok) throw new Error(`Failed to fetch session data: ${response.statusText}`)
              return response.text()
            })
          : Bun.file(input.file).text(),
      catch: (cause) =>
        new Error(`Failed to read session data: ${cause instanceof Error ? cause.message : String(cause)}`),
    })
    const data = yield* Schema.decodeUnknownEffect(Schema.fromJsonString(SessionTransfer.Data))(text)
    const encoded = Schema.encodeSync(SessionTransfer.Data)(data)
    const server = yield* ServerConnection.resolve({
      server: Option.getOrUndefined(input.server),
      standalone: input.standalone,
    })
    const client = OpenCode.make({
      baseUrl: server.endpoint.url,
      headers: Service.headers(server.endpoint),
    })
    const location = yield* Effect.promise(() =>
      client.location.get({
        location: { directory: path.resolve(Option.getOrElse(input.directory, () => process.cwd())) },
      }),
    )
    const response = yield* Effect.promise(() =>
      fetch(new URL("/api/experimental/session/import", server.endpoint.url), {
        method: "POST",
        headers: { ...Service.headers(server.endpoint), "content-type": "application/json" },
        body: JSON.stringify({
          ...encoded,
          location: { directory: location.directory },
        }),
      }),
    )
    if (response.status === 409) {
      process.stderr.write(`Session already exists${EOL}`)
      return
    }
    if (!response.ok) yield* Effect.fail(new Error(`Failed to import session: ${response.statusText}`))
    const imported = yield* Schema.decodeUnknownEffect(Schema.fromJsonString(Schema.Struct({ data: Session.Info })))(
      yield* Effect.promise(() => response.text()),
    )
    process.stdout.write(`Imported session: ${imported.data.id}${EOL}`)
  }),
)

import { OpenCode, type SessionInfo } from "@opencode/client"
import { Service } from "@opencode/client/effect/service"
import { Effect, Option, Stream } from "effect"
import { EOL } from "node:os"
import { Commands } from "../../commands"
import { Runtime } from "../../../framework/runtime"
import { ServerConnection } from "../../../services/server-connection"
import { errorMessage } from "../../../util/error"

const handler = Effect.fn("cli.session.list")(function* (
  input: Runtime.Input<typeof Commands.commands.session.commands.list>,
) {
  const server = yield* ServerConnection.resolve({
    server: Option.getOrUndefined(input.server),
    standalone: input.standalone,
  })
  const client = OpenCode.make({ baseUrl: server.endpoint.url, headers: Service.headers(server.endpoint) })
  const location = yield* Effect.tryPromise({
    try: (signal) => client.location.get({ location: { directory: process.cwd() } }, { signal }),
    catch: (cause) => cause,
  })
  const page = yield* Effect.tryPromise({
    try: (signal) =>
      client.session.list(
        {
          project: location.project.id,
          parentID: null,
          order: "desc",
          limit: Option.getOrElse(input.maxCount, () => 100),
        },
        { signal },
      ),
    catch: (cause) => cause,
  })
  if (input.format === "table" && page.data.length === 0) return
  const output =
    (input.format === "json"
      ? JSON.stringify(
          page.data.map((session) => ({
            id: session.id,
            title: session.title,
            updated: session.time.updated,
            created: session.time.created,
            projectId: session.projectID,
            directory: session.location.directory,
          })),
          null,
          2,
        )
      : formatList(page.data)) + EOL
  const write = Effect.tryPromise(
    () =>
      new Promise<void>((resolve, reject) => {
        process.stdout.write(output, (error) => (error ? reject(error) : resolve()))
      }),
  )
  if (!process.stdout.isTTY || Option.isSome(input.maxCount) || input.format === "json") {
    yield* write
    return
  }

  const { AppProcess } = yield* Effect.promise(() => import("@opencode/util/process"))
  const { LayerNode } = yield* Effect.promise(() => import("@opencode/util/effect/layer-node"))
  const { ChildProcess } = yield* Effect.promise(() => import("effect/process"))
  yield* Effect.gen(function* () {
    const processService = yield* AppProcess.Service
    const pager = yield* processService
      .spawn(
        ChildProcess.make(
          process.platform === "win32" ? "cmd" : "less",
          process.platform === "win32" ? ["/c", "more"] : ["-R", "-S"],
          {
            stdin: Stream.make(new TextEncoder().encode(output)),
            stdout: "inherit",
            stderr: "inherit",
          },
        ),
      )
      .pipe(Effect.option)
    if (Option.isNone(pager)) {
      yield* write
      return
    }
    yield* pager.value.exitCode
  }).pipe(Effect.provide(LayerNode.compile(AppProcess.node)))
})

export default Runtime.handler(Commands.commands.session.commands.list, (input) =>
  handler(input).pipe(
    Effect.catch((error) =>
      Effect.sync(() => {
        process.stderr.write(errorMessage(error) + EOL)
        process.exitCode = 1
      }),
    ),
  ),
)

function formatList(sessions: ReadonlyArray<SessionInfo>) {
  return sessions
    .map((session) =>
      [
        session.id,
        (session.title ?? "Untitled session").replace(/[\r\n\t]/g, " "),
        new Date(session.time.updated).toLocaleString(),
      ].join("\t"),
    )
    .join(EOL)
}

import { ClientError, OpenCode, type SessionStatsInfo } from "@opencode/client"
import { Service } from "@opencode/client/effect/service"
import { TokenUsage } from "@opencode/schema/token-usage"
import { activityCalendar } from "@opencode/util/activity-calendar"
import { Effect, Option } from "effect"
import { EOL } from "node:os"
import { Commands } from "../commands"
import { Runtime } from "../../framework/runtime"
import { ServerConnection } from "../../services/server-connection"
import { errorMessage } from "../../util/error"

const handler = Effect.fn("cli.stats")(function* (input: Runtime.Input<typeof Commands.commands.stats>) {
  const days = Option.getOrUndefined(input.days)
  const year = Option.getOrUndefined(input.year)
  const project = Option.getOrUndefined(input.project)
  if ([days !== undefined, year !== undefined, input.all].filter(Boolean).length > 1)
    yield* Effect.fail(new Error("--days, --year, and --all cannot be combined"))

  const server = yield* ServerConnection.resolve({
    server: Option.getOrUndefined(input.server),
    standalone: input.standalone,
  })
  const client = OpenCode.make({ baseUrl: server.endpoint.url, headers: Service.headers(server.endpoint) })
  const range = statsRange({ days, year, all: input.all })
  const projectID =
    project === "."
      ? yield* request(server.endpoint.url, (signal) =>
          client.location
            .get({ location: { directory: process.cwd() } }, { signal })
            .then((location) => location.project.id),
        )
      : project
  const details = input.models || input.tools || input.cost || input.full
  const stats = yield* request(server.endpoint.url, (signal) =>
    client.session.stats(
      {
        from: range.from,
        to: range.to,
        project: projectID,
        timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC",
        tools: input.json || input.tools || input.full ? "detail" : details ? "none" : "summary",
      },
      { signal },
    ),
  )
  const output = input.json
    ? JSON.stringify(stats, null, 2)
    : renderStats(stats, {
        label: range.label,
        scope: project === undefined ? "all projects" : project === "." ? "current project" : "selected project",
        models: input.models || input.full,
        tools: input.tools || input.full,
        cost: input.cost || input.full,
        limit: input.limit,
        color: process.stdout.isTTY && process.env.NO_COLOR === undefined,
        width: process.stdout.columns ?? 80,
      })
  process.stdout.write(output + EOL)
})

export default Runtime.handler(Commands.commands.stats, (input) =>
  handler(input).pipe(
    Effect.catch((error) =>
      Effect.sync(() => {
        process.stderr.write(errorMessage(error) + EOL)
        process.exitCode = 1
      }),
    ),
  ),
)

export function request<A>(url: string, run: (signal: AbortSignal) => Promise<A>) {
  return Effect.tryPromise({
    try: () => run(AbortSignal.timeout(30_000)),
    catch: (cause) =>
      cause instanceof ClientError && cause.reason === "Transport"
        ? new Error(`Could not reach server at ${url}`, { cause })
        : cause,
  })
}

type RenderOptions = {
  label: string
  scope: string
  models: boolean
  tools: boolean
  cost: boolean
  limit: number
  color: boolean
  width: number
}

const colors = terminalPalette()

export function renderStats(stats: SessionStatsInfo, options: RenderOptions) {
  const totalTokens = TokenUsage.total(stats.tokens)
  const toolTotals = stats.tools.mode === "none" ? undefined : stats.tools.totals
  const terminalTools = toolTotals ? toolTotals.succeeded + toolTotals.failed : 0
  const toolRate = !toolTotals || terminalTools === 0 ? undefined : (toolTotals.succeeded / terminalTools) * 100
  const primary = `1;${colors.primary}`
  const sessionLine = [
    metricCount(stats.sessions, "session", options.color),
    stats.subagents > 0 ? metricCount(stats.subagents, "subagent", options.color) : undefined,
  ]
    .filter((value) => value !== undefined)
    .join(" · ")
  const toolSummary = !toolTotals
    ? "tool stats unavailable"
    : toolRate === undefined
      ? "no tool calls"
      : `${style(formatPercent(toolRate), primary, options.color)} tool success`
  const details = options.models || options.tools || options.cost
  const empty = stats.sessions === 0 && stats.prompts === 0 && stats.steps === 0
  const heading = `${style("opencode stats", primary, options.color)} ${style(`· ${options.label} · ${options.scope}`, "2", options.color)}`
  const lines = details
    ? [style(`${options.label} · ${options.scope}`, "2", options.color)]
    : empty
      ? [
          heading,
          "",
          style("no activity in this range", "2", options.color),
          "",
          style("opencode.ai", "2", options.color),
        ]
      : [
          heading,
          "",
          ...renderActivity(stats.activity, stats.range.from, stats.range.to, options.color, options.width),
          "",
          sessionLine,
          `${metricCount(stats.prompts, "prompt", options.color)} · ${metricCount(stats.steps, "step", options.color)} · ${metricCount(totalTokens, "token", options.color)}`,
          `${toolSummary} · ${metricCount(stats.activeDays, "active day", options.color)} · best streak ${style(stats.streak.toString(), primary, options.color)} day${stats.streak === 1 ? "" : "s"}`,
          "",
          style("opencode.ai", "2", options.color),
        ]

  if (options.cost) lines.push(...(lines.length > 0 ? [""] : []), ...renderCost(stats))
  if (options.models)
    lines.push(...(lines.length > 0 ? [""] : []), ...renderModels(stats, options.limit, options.width))
  if (options.tools) lines.push(...(lines.length > 0 ? [""] : []), ...renderTools(stats, options.limit, options.width))
  return lines.join(EOL)
}

function statsRange(input: { days?: number; year?: number; all: boolean }) {
  const now = new Date()
  const to = now.getTime() + 1
  if (input.all) return { from: undefined, to, label: "all time" }
  if (input.days !== undefined) {
    const from = new Date(now.getFullYear(), now.getMonth(), now.getDate())
    from.setDate(from.getDate() - Math.max(0, input.days - 1))
    return {
      from: from.getTime(),
      to,
      label: input.days === 0 || input.days === 1 ? "today" : `last ${input.days} days`,
    }
  }
  const year = input.year ?? now.getFullYear()
  return {
    from: new Date(year, 0, 1).getTime(),
    to: year === now.getFullYear() ? to : new Date(year + 1, 0, 1).getTime(),
    label: year === now.getFullYear() ? `${year} so far` : year.toString(),
  }
}

function renderActivity(
  activity: SessionStatsInfo["activity"],
  from: number,
  to: number,
  color: boolean,
  width: number,
) {
  const calendar = activityCalendar({ activity, from, to, maxWeeks: width - 4 })
  const months = calendar.months
    .map((month, index) =>
      (index === calendar.months.length - 1 || month.label.length <= month.span ? month.label : "").padEnd(month.span),
    )
    .join("")
    .trimEnd()
  const weekdays = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"]
  return [
    style(
      calendar.clipped ? `activity · last ${calendar.weeks.length} weeks` : "activity",
      `1;${colors.primary}`,
      color,
    ),
    `   ${style(months, "2", color)}`,
    ...weekdays.flatMap((label, day) => [
      `${style(label, "2", color)} ${calendar.weeks.map((week) => (week[day].level < 0 ? " " : paintActivity(week[day].level, color))).join("")}`,
      ...(day === weekdays.length - 1 ? [] : [""]),
    ]),
    "",
    `   ${style("less", "2", color)} ${[0, 1, 2, 3, 4].map((level) => paintActivity(level, color)).join("")} ${style("more", "2", color)}`,
  ]
}

function renderCost(stats: SessionStatsInfo) {
  const input = stats.tokens.input + stats.tokens.cache.read + stats.tokens.cache.write
  const cached = input === 0 ? 0 : (stats.tokens.cache.read / input) * 100
  return [
    "COST & TOKENS",
    row("cost", `$${stats.cost.toFixed(2)}`),
    row("input", formatNumber(stats.tokens.input)),
    row("output", formatNumber(stats.tokens.output)),
    row("reasoning", formatNumber(stats.tokens.reasoning)),
    row("cache read", formatNumber(stats.tokens.cache.read)),
    row("cache write", formatNumber(stats.tokens.cache.write)),
    row("cached input", formatPercent(cached)),
  ]
}

function renderModels(stats: SessionStatsInfo, limit: number, width: number) {
  if (stats.models.length === 0) return ["MODELS", "  no model usage"]
  const models = stats.models.slice(0, limit)
  const more = stats.models.length - models.length
  if (width < 68)
    return [
      "MODELS",
      ...models.flatMap((item) => [
        truncate(
          `${item.model.providerID}/${item.model.id}${item.model.variant ? `#${item.model.variant}` : ""}`,
          width,
        ),
        `  ${formatNumber(TokenUsage.total(item.tokens))} tokens · ${formatNumber(item.steps)} steps · $${item.cost.toFixed(2)}`,
      ]),
      ...(more > 0 ? ["", `+${more.toLocaleString("en-US")} more model${more === 1 ? "" : "s"}`] : []),
    ]
  return [
    "MODELS",
    tableHeader("model", "tokens", "steps", "cost"),
    ...models.map((item) =>
      tableRow(
        `${item.model.providerID}/${item.model.id}${item.model.variant ? `#${item.model.variant}` : ""}`,
        formatNumber(TokenUsage.total(item.tokens)),
        formatNumber(item.steps),
        `$${item.cost.toFixed(2)}`,
      ),
    ),
    ...(more > 0 ? ["", `+${more.toLocaleString("en-US")} more model${more === 1 ? "" : "s"}`] : []),
  ]
}

function renderTools(stats: SessionStatsInfo, limit: number, width: number) {
  if (stats.tools.mode !== "detail") return ["TOOL RELIABILITY", "  tool details unavailable"]
  if (stats.tools.usage.length === 0) return ["TOOL RELIABILITY", "  no tool calls"]
  const tools = stats.tools.usage.slice(0, limit)
  const more = stats.tools.usage.length - tools.length
  if (width < 68)
    return [
      "TOOL RELIABILITY",
      ...tools.flatMap((tool) => {
        const terminal = tool.succeeded + tool.failed
        return [
          truncate(tool.name, width),
          `  ${formatNumber(tool.calls)} calls · ${terminal === 0 ? "-" : formatPercent((tool.failed / terminal) * 100)} error · ${tool.durationP50 === undefined ? "-" : formatDuration(tool.durationP50)} p50`,
        ]
      }),
      "",
      `${formatNumber(stats.tools.totals.succeeded + stats.tools.totals.failed)} finished calls · ${formatNumber(stats.tools.totals.unfinished)} unfinished`,
      ...(more > 0 ? [`+${more.toLocaleString("en-US")} more tool${more === 1 ? "" : "s"}`] : []),
    ]
  return [
    "TOOL RELIABILITY",
    tableHeader("tool", "calls", "error", "p50"),
    ...tools.map((tool) => {
      const terminal = tool.succeeded + tool.failed
      return tableRow(
        tool.name,
        formatNumber(tool.calls),
        terminal === 0 ? "-" : formatPercent((tool.failed / terminal) * 100),
        tool.durationP50 === undefined ? "-" : formatDuration(tool.durationP50),
      )
    }),
    "",
    `${formatNumber(stats.tools.totals.succeeded + stats.tools.totals.failed)} finished calls · ${formatNumber(stats.tools.totals.unfinished)} unfinished`,
    ...(more > 0 ? [`+${more.toLocaleString("en-US")} more tool${more === 1 ? "" : "s"}`] : []),
  ]
}

function row(label: string, value: string) {
  return `  ${label.padEnd(20)}${value}`
}

function tableHeader(label: string, second: string, third: string, fourth: string) {
  return tableRow(label, second, third, fourth)
}

function tableRow(label: string, second: string, third: string, fourth: string) {
  return `${truncate(label, 34).padEnd(34)}${second.padStart(10)}${third.padStart(12)}${fourth.padStart(12)}`
}

function truncate(value: string, width: number) {
  return value.length <= width ? value : value.slice(0, width - 1) + "…"
}

function formatNumber(value: number) {
  if (value >= 1_000_000_000) return `${trimDecimal(value / 1_000_000_000)}b`
  if (value >= 1_000_000) return `${trimDecimal(value / 1_000_000)}m`
  if (value >= 1_000) return `${trimDecimal(value / 1_000)}k`
  return Math.round(value).toLocaleString("en-US")
}

function trimDecimal(value: number) {
  return value.toFixed(1).replace(/\.0$/, "")
}

function formatPercent(value: number) {
  return `${value.toFixed(value >= 10 ? 1 : 2)}%`
}

function formatDuration(value: number) {
  if (value < 1_000) return `${Math.round(value)}ms`
  return `${trimDecimal(value / 1_000)}s`
}

function metricCount(value: number, noun: string, color: boolean) {
  return `${style(formatNumber(value), `1;${colors.primary}`, color)} ${noun}${value === 1 ? "" : "s"}`
}

function style(value: string, code: string, color: boolean) {
  return color ? `\x1b[${code}m${value}\x1b[0m` : value
}

function paintActivity(level: number, color: boolean) {
  const glyph = ["·", "░", "▒", "▓", "█"][level]
  if (!color) return glyph
  if (level === 0) return `\x1b[2m${glyph}\x1b[22m`
  return `\x1b[${colors.activity[level - 1]}m${glyph}\x1b[39m`
}

function terminalPalette() {
  const background = Number(process.env.COLORFGBG?.split(";").at(-1))
  if (Number.isFinite(background) && background >= 7)
    return {
      primary: "38;2;59;125;216",
      activity: ["38;2;153;169;192", "38;2;122;155;200", "38;2;90;140;208", "38;2;59;125;216"],
    }
  if (Number.isFinite(background))
    return {
      primary: "38;2;250;178;131",
      activity: ["38;2;117;99;87", "38;2;161;125;102", "38;2;206;152;116", "38;2;250;178;131"],
    }
  return { primary: "36", activity: ["2;36", "36", "1;36", "1;96"] }
}

import { confirm, intro, log, outro, spinner } from "@clack/prompts"
import { Service } from "@opencode/client/effect/service"
import { Global } from "@opencode/util/global"
import { Effect, FileSystem, Schedule } from "effect"
import path from "node:path"
import { Commands } from "../commands"
import { Runtime } from "../../framework/runtime"
import { ServerConnection } from "../../services/server-connection"
import { RetainedImage } from "../../services/retained-image"
import { Updater } from "../../services/updater"
import { handlePromptErrors, prompt, requireInteractive } from "../../ui/prompt"
import { errorMessage } from "../../util/error"

export default Runtime.handler(
  Commands.commands.uninstall,
  Effect.fn("cli.uninstall")(function* (input) {
    intro("Uninstall OpenCode")
    const fs = yield* FileSystem.FileSystem
    const global = yield* Global.Service
    const updater = yield* Updater.Service
    const method = yield* updater.method()
    const removal = method ? updater.removal(method) : undefined
    // Data, config, and state hold sessions, credentials, settings, and prompt history; uninstall only removes the cache.
    // All channels share the cache. Stop background services before deleting it.
    // Read registrations directly: ServiceConfig.options() can migrate files even during a dry run.
    const services = (yield* fs.exists(global.state))
      ? (yield* fs.readDirectory(global.state)).filter((name) => /^service(?:-.*)?\.json$/.test(name))
      : []
    const shell = method === "curl" ? yield* shellConfigs(global.home) : []

    log.info(`Installation method: ${method ?? "unknown"}`)
    log.message("The following global files will be removed (shared by OpenCode versions and channels):")
    if (yield* fs.exists(global.cache)) log.info(`  Cache: ${global.cache}`)
    services.forEach((name) =>
      log.info(`  Stop background service and persistent terminals: ${path.join(global.state, name)}`),
    )
    shell.forEach((file) => log.info(`  Shell PATH: ${file}`))
    if (removal) log.info(`  Package: ${removal.command.join(" ")}`)
    if (method === "curl") log.info(`  Binary (manual removal): ${process.execPath}`)
    if (!method) log.warn("Could not detect the installation method. Remove the installation manually after cleanup.")

    if (input.dryRun) {
      log.warn("Dry run - no changes made")
      outro("Done")
      return
    }
    if (!input.force) {
      yield* requireInteractive("Use --force to uninstall without an interactive terminal, or --dry-run to preview.")
      const accepted = yield* prompt(() =>
        confirm({ message: "Are you sure you want to uninstall?", initialValue: false }),
      )
      if (!accepted) {
        outro("Cancelled")
        return
      }
    }

    const progress = spinner()
    if (services.length) {
      progress.start("Stopping background services...")
      yield* Effect.forEach(services, (name) =>
        Effect.gen(function* () {
          const options = { file: path.join(global.state, name) }
          yield* ServerConnection.shutdownPersistentPty(options).pipe(Effect.ignore)
          yield* Service.stop(options)
        }),
      ).pipe(
        Effect.tap(() => Effect.sync(() => progress.stop("Background services stopped"))),
        Effect.tapCause(() => Effect.sync(() => progress.stop("Failed to stop background services", 1))),
      )
    }

    // Links that keep an older OpenCode replaceable may still run; move them so the cache can go.
    if (process.platform === "win32") yield* RetainedImage.relocate(global.cache, global.tmp)
    const errors: string[] = []
    progress.start("Removing Cache...")
    yield* fs.remove(global.cache, { recursive: true, force: true }).pipe(
      // Windows reports a terminated service as gone before it releases its file handles,
      // so the first removal can race that teardown.
      Effect.retry({
        while: (error) => process.platform === "win32" && error.reason._tag === "Busy",
        schedule: Schedule.max([Schedule.spaced("250 millis"), Schedule.recurs(40)]),
      }),
      Effect.tap(() => Effect.sync(() => progress.stop("Removed Cache"))),
      Effect.catch((error) =>
        Effect.sync(() => {
          progress.stop("Failed to remove Cache", 1)
          errors.push(`Cache: ${errorMessage(error)}`)
        }),
      ),
    )
    yield* Effect.forEach(shell, (file) =>
      fs.readFileString(file).pipe(
        Effect.flatMap((content) => fs.writeFileString(file, cleanShellConfig(content))),
        Effect.catch((error) => Effect.sync(() => errors.push(`Shell config ${file}: ${errorMessage(error)}`))),
      ),
    )
    if (removal) {
      progress.start(`Running ${removal.command.join(" ")}...`)
      yield* removal.run.pipe(
        Effect.tap(() => Effect.sync(() => progress.stop("Package removed"))),
        Effect.catch((error) =>
          Effect.sync(() => {
            progress.stop("Package manager uninstall failed", 1)
            errors.push(errorMessage(error))
            log.warn(`Run manually: ${removal.command.join(" ")}`)
          }),
        ),
      )
    }
    if (method === "curl") {
      log.message("To finish removing the binary, run:")
      log.info(`  rm '${process.execPath.replaceAll("'", "'\\''")}'`)
    }
    if (errors.length) yield* Effect.fail(new Error(errors.join("\n")))
    outro("Done")
  }, handlePromptErrors),
)

const shellConfigs = Effect.fnUntraced(function* (home: string) {
  const fs = yield* FileSystem.FileSystem
  const bin = path.dirname(process.execPath)
  // V1 and V2 curl installs share a PATH entry; retain it while another binary uses it.
  if ((yield* fs.readDirectory(bin)).some((name) => name !== path.basename(process.execPath))) return []
  const xdg = process.env.XDG_CONFIG_HOME || path.join(home, ".config")
  const zsh = process.env.ZDOTDIR || home
  const candidates: Record<string, string[]> = {
    fish: [path.join(home, ".config/fish/config.fish"), path.join(xdg, "fish/config.fish")],
    zsh: [
      path.join(zsh, ".zshrc"),
      path.join(zsh, ".zshenv"),
      path.join(xdg, "zsh/.zshrc"),
      path.join(xdg, "zsh/.zshenv"),
    ],
    bash: [
      path.join(home, ".bashrc"),
      path.join(home, ".bash_profile"),
      path.join(home, ".profile"),
      path.join(xdg, "bash/.bashrc"),
      path.join(xdg, "bash/.bash_profile"),
    ],
    ash: [path.join(home, ".ashrc"), path.join(home, ".profile")],
    sh: [path.join(home, ".ashrc"), path.join(home, ".profile")],
  }
  const files = [...new Set(candidates[path.basename(process.env.SHELL || "bash")] ?? candidates.bash)]
  return yield* Effect.filter(files, (file) =>
    fs.readFileString(file).pipe(
      Effect.map((content) => cleanShellConfig(content) !== content),
      Effect.orElseSucceed(() => false),
    ),
  )
})

function cleanShellConfig(content: string) {
  const lines = content.split("\n")
  const entry = (line: string) =>
    /^(?:export PATH=|fish_add_path\s)/.test(line.trim()) && line.includes(".opencode/bin")
  return lines
    .filter((line, index) => !entry(line) && !(line.trim() === "# opencode" && entry(lines[index + 1] ?? "")))
    .join("\n")
}

import { intro, log, outro, spinner } from "@clack/prompts"
import { Effect, Option } from "effect"
import { Commands } from "../commands"
import { Runtime } from "../../framework/runtime"
import { Updater } from "../../services/updater"
import { handlePromptErrors } from "../../ui/prompt"
import { OPENCODE_VERSION } from "../../version"
import { stripVTControlCharacters } from "node:util"

export default Runtime.handler(
  Commands.commands.upgrade,
  Effect.fn("cli.upgrade")(
    function* (input) {
      intro("Upgrade")
      const updater = yield* Updater.Service
      const method = Option.getOrUndefined(input.method) ?? (yield* updater.method())
      if (!method)
        return yield* Effect.fail(
          new Error("Could not detect the installation method. Pass --method to choose how to upgrade OpenCode."),
        )

      log.info(`Using method: ${method}`)
      const target = Option.getOrUndefined(input.target) ?? (yield* updater.latest(method))
      const version = target.trim().replace(/^v/, "")
      if (version === OPENCODE_VERSION) {
        log.warn(`OpenCode upgrade skipped: ${version} is already installed`)
        outro("Done")
        return
      }

      log.info(`From ${OPENCODE_VERSION} → ${version}`)
      const progress = spinner()
      progress.start("Upgrading...")
      yield* updater.upgrade(method, target).pipe(
        Effect.tap(() => Effect.sync(() => progress.stop("Upgrade complete"))),
        Effect.tapCause(() => Effect.sync(() => progress.stop("Upgrade failed", 1))),
      )
      outro("Done")
    },
    (effect) =>
      handlePromptErrors(
        effect.pipe(
          Effect.mapError((error) =>
            error instanceof Updater.UpgradeError ? new Error(formatUpgradeError(error), { cause: error }) : error,
          ),
        ),
      ),
  ),
)

function formatUpgradeError(error: Updater.UpgradeError) {
  const clean = (value: string) => stripVTControlCharacters(value).replaceAll("\r", "").trim()
  const line = (value: string) => clean(value).replace(/\s+/g, " ")
  const detail = wrap(clean(error.detail), Math.max(24, (process.stdout.columns ?? 80) - 7)).join("\n")
  return [
    line(error.title),
    "",
    detail,
    ...(error.command ? ["", field("Command", line(error.command))] : []),
    field("Retry", line(error.retry)),
  ].join("\n")
}

function field(label: string, value: string) {
  const prefix = label.padEnd(9)
  const width = Math.max(24, Math.min(61, (process.stdout.columns ?? 80) - prefix.length - 10))
  const lines = wrap(value, width)
  return lines.map((line, index) => `${index === 0 ? prefix : " ".repeat(prefix.length)}${line}`).join("\n")
}

function wrap(value: string, width: number) {
  return value.split("\n").flatMap((source) => {
    if (source.length <= width) return [source]
    return source.split(/\s+/).reduce<string[]>((result, word) => {
      const index = result.length - 1
      if (index < 0 || result[index].length + word.length + 1 > width) result.push(word)
      else result[index] += ` ${word}`
      return result
    }, [])
  })
}

export * as Config from "./config"

import { Global } from "@opencode/util/global"
import { Flock } from "@opencode/util/flock"
import { Context, Effect, FileSystem, Layer, Option, Schema } from "effect"
import { produce, type Draft } from "immer"
import { applyEdits, modify, parse, type ParseError } from "jsonc-parser"
import path from "path"
import { ConfigMigration } from "./migrate"
import { Info, normalizeLegacyTabs, SchemaURL } from "./schema"

export * from "./schema"

export interface Interface {
  readonly path: string
  readonly get: () => Effect.Effect<Info>
  readonly update: (update: (draft: Draft<Info>) => void) => Effect.Effect<Info, Error>
}

export class Service extends Context.Service<Service, Interface>()("@opencode/cli/config/Config") {}

const decode = Schema.decodeUnknownOption(Info)
const decodeRecord = Schema.decodeUnknownOption(Schema.Record(Schema.String, Schema.Unknown))
const empty: Info = {}

export const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem
    const global = yield* Global.Service
    const file = path.join(global.config, "cli.json")
    const content = process.env.OPENCODE_CLI_CONFIG_CONTENT
      ? Option.getOrUndefined(decode(parseRecord(process.env.OPENCODE_CLI_CONFIG_CONTENT)))
      : undefined

    const readJson = Effect.fnUntraced(function* () {
      const text = yield* fs.readFileString(file).pipe(Effect.orElseSucceed(() => undefined))
      if (text === undefined) return undefined
      return parseRecord(text)
    })

    const write = Effect.fnUntraced(function* (text: string) {
      const temp = file + ".tmp"
      yield* fs.makeDirectory(path.dirname(file), { recursive: true })
      yield* fs.writeFileString(temp, text, { mode: 0o600 })
      yield* fs.rename(temp, file)
    })

    const migrate = ConfigMigration.run({ file, config: global.config, state: global.state }).pipe(
      Effect.provideService(FileSystem.FileSystem, fs),
    )
    const withLock = <A, E, R>(effect: Effect.Effect<A, E, R>) =>
      Effect.scoped(
        Effect.uninterruptibleMask((restore) =>
          Effect.gen(function* () {
            const lock = yield* restore(
              Effect.promise((signal) => Flock.acquire(file, { dir: path.join(global.state, "locks"), signal })),
            )
            yield* Effect.addFinalizer(() => Effect.promise(() => lock.release()))
            return yield* restore(effect)
          }),
        ),
      )
    const load = Effect.fnUntraced(function* (migration?: Info) {
      return merge(migration ?? Option.getOrUndefined(decode(yield* readJson())), content)
    })

    const get = Effect.fn("cli.config.get")(() =>
      withLock(
        Effect.gen(function* () {
          const migration = yield* migrate.pipe(
            Effect.catchCause((cause) =>
              Effect.logWarning("failed to migrate cli config", { cause }).pipe(Effect.as(undefined)),
            ),
          )
          if (migration?.cause)
            yield* Effect.logWarning("failed to persist migrated cli config", { cause: migration.cause })
          return yield* load(migration?.info)
        }),
      ),
    )

    const update = Effect.fn("cli.config.update")((update: (draft: Draft<Info>) => void) =>
      withLock(
        Effect.gen(function* () {
          const migration = yield* migrate
          if (migration?.cause) return yield* Effect.failCause(migration.cause)
          const current = yield* load(migration?.info)
          const next = produce(current, update)
          const edits = changes(current, next)
          if (!edits.length) return current
          const text = yield* fs
            .readFileString(file)
            .pipe(Effect.orElseSucceed(() => JSON.stringify({ $schema: SchemaURL }, null, 2)))
          const updated = edits.reduce(
            (text, edit) =>
              applyEdits(
                text,
                modify(text, edit.path, edit.value, { formattingOptions: { tabSize: 2, insertSpaces: true } }),
              ),
            text,
          )
          const errors: ParseError[] = []
          const config = Option.getOrUndefined(decode(parse(updated, errors, { allowTrailingComma: true })))
          if (errors.length || config === undefined) return yield* Effect.fail(new Error("Invalid CLI config update"))
          yield* write(updated.endsWith("\n") ? updated : updated + "\n")
          return merge(config, content)
        }),
      ).pipe(Effect.mapError((cause) => new Error("Failed to update CLI config", { cause }))),
    )

    return Service.of({ path: file, get, update })
  }),
)

type Edit = { readonly path: (string | number)[]; readonly value: any }

function merge(...values: readonly (Info | undefined)[]) {
  return Option.getOrElse(
    decode(
      values.reduce<Record<string, unknown>>(
        (result, value) => mergeRecords(result, normalizeLegacyTabs(value) ?? {}),
        {},
      ),
    ),
    () => empty,
  )
}

function mergeRecords(base: object, overlay: object) {
  return Object.entries(overlay).reduce<Record<string, unknown>>(
    (result, [key, value]) => {
      result[key] = isRecord(result[key]) && isRecord(value) ? mergeRecords(result[key], value) : value
      return result
    },
    { ...base },
  )
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

function parseRecord(text: string) {
  const errors: ParseError[] = []
  const value: unknown = parse(text, errors, { allowTrailingComma: true })
  if (errors.length) return undefined
  return Option.getOrUndefined(decodeRecord(value))
}

function changes(before: any, after: any, path: (string | number)[] = []): Edit[] {
  if (Object.is(before, after)) return []
  if (
    before !== null &&
    after !== null &&
    typeof before === "object" &&
    typeof after === "object" &&
    !Array.isArray(before) &&
    !Array.isArray(after)
  ) {
    return [...new Set([...Object.keys(before), ...Object.keys(after)])].flatMap((key) => {
      if (!(key in after)) return [{ path: [...path, key], value: undefined }]
      if (!(key in before)) return [{ path: [...path, key], value: after[key] }]
      return changes(before[key], after[key], [...path, key])
    })
  }
  return [{ path, value: after }]
}

export * as ConfigMigration from "./migrate"

import { TuiConfigV1 } from "@opencode/tui/config/v1"
import { TuiKeybind } from "@opencode/tui/config/v1/keybind"
import { Definitions } from "@opencode/tui/config/keybind"
import { Effect, FileSystem, Option, Schema } from "effect"
import { randomUUID } from "crypto"
import { applyEdits, createScanner, modify, parse, parseTree, type Node, type ParseError } from "jsonc-parser"
import path from "path"
import { Info, SchemaURL } from "./schema"

const decodeV1 = Schema.decodeUnknownOption(TuiConfigV1.Info)
const decodeInfo = Schema.decodeUnknownOption(Info)
const decodeRecord = Schema.decodeUnknownOption(Schema.Record(Schema.String, Schema.Any))
const LegacyKeybindTargets = new Set<string>(Object.values(TuiKeybind.CommandMap))

export const run = Effect.fn("cli.config.migrate")(function* (input: {
  readonly file: string
  readonly config: string
  readonly state: string
}) {
  const fs = yield* FileSystem.FileSystem
  const persist = Effect.fnUntraced(function* (text: string, info: Info) {
    const temp = `${input.file}.${process.pid}.${randomUUID()}.tmp`
    const cause = yield* Effect.gen(function* () {
      yield* fs.makeDirectory(path.dirname(input.file), { recursive: true })
      yield* fs.writeFileString(temp, text, { mode: 0o600 })
      yield* fs.rename(temp, input.file)
    }).pipe(
      Effect.as(undefined),
      Effect.catchCause((cause) => Effect.succeed(cause)),
      Effect.ensuring(fs.remove(temp).pipe(Effect.ignore)),
    )
    return cause === undefined ? { info } : { info, cause }
  })

  if (yield* fs.exists(input.file).pipe(Effect.orElseSucceed(() => false))) {
    const text = yield* fs.readFileString(input.file)
    const errors: ParseError[] = []
    const value: any = parse(text, errors, { allowTrailingComma: true })
    if (errors.length) return
    const config = Option.getOrUndefined(decodeRecord(value))
    if (config === undefined) return
    const terminal = Option.getOrUndefined(decodeRecord(config.terminal))
    const legacyCopy = terminal?.copy_on_select
    const copy =
      typeof legacyCopy === "boolean" && terminal?.copy === undefined ? (legacyCopy ? "select" : "manual") : undefined
    const renamed =
      typeof legacyCopy !== "boolean"
        ? text
        : [
            ...(copy === undefined ? [] : [{ path: ["terminal", "copy"], value: copy }]),
            { path: ["terminal", "copy_on_select"], value: undefined },
          ].reduce(
            (text, edit) =>
              applyEdits(
                text,
                modify(text, edit.path, edit.value, { formattingOptions: { tabSize: 2, insertSpaces: true } }),
              ),
            text,
          )
    const keybinds = Option.getOrUndefined(decodeRecord(config.keybinds))
    const updated =
      keybinds === undefined
        ? renamed
        : Object.keys(keybinds).reduce(
            (text, name) => {
              const target =
                TuiKeybind.CommandMap[name as keyof typeof TuiKeybind.CommandMap] ??
                (name in Definitions || LegacyKeybindTargets.has(name) ? name : undefined)
              if (target === undefined) return text
              const properties = findKeybindProperties(text, name)
              if (!properties.length) return text
              const remove = !(target in Definitions) || (target !== name && target in keybinds)
              // The parser gives the final duplicate precedence, so remove earlier properties before renaming it.
              const cleaned = properties.slice(0, remove ? properties.length : -1).reduce((text) => {
                const property = findKeybindProperties(text, name)[0]
                return property === undefined ? text : removeProperty(text, property)
              }, text)
              if (remove) return cleaned
              if (target === name) return cleaned
              const key = findKeybindProperties(cleaned, name)[0]?.children?.[0]
              if (key === undefined) return text
              return cleaned.slice(0, key.offset) + JSON.stringify(target) + cleaned.slice(key.offset + key.length)
            },
            findKeybindObjects(renamed)
              .slice(0, -1)
              .reduce((text) => {
                const property = findKeybindObjects(text)[0]
                return property === undefined ? text : removeProperty(text, property)
              }, renamed),
          )
    if (updated === text) return
    const updatedErrors: ParseError[] = []
    const info = Option.getOrUndefined(decodeInfo(parse(updated, updatedErrors, { allowTrailingComma: true })))
    if (updatedErrors.length || info === undefined) return
    return yield* persist(updated, info)
  }

  const legacyValue = yield* readJson(path.join(input.config, "tui.json"))
  const legacy = Option.getOrUndefined(decodeV1(legacyValue))
  const kv = yield* readJson(path.join(input.state, "kv.json"))
  const values = migrateV1(legacy, kv ?? {})
  if (!Object.keys(values).length) return
  const migrated = { $schema: SchemaURL, ...values }

  const result = yield* persist(JSON.stringify(migrated, null, 2) + "\n", migrated)
  if (result.cause === undefined)
    yield* Effect.logInfo("migrated cli config", {
      from: [
        legacyValue === undefined ? undefined : path.join(input.config, "tui.json"),
        kv === undefined ? undefined : path.join(input.state, "kv.json"),
      ].filter(Boolean),
      to: input.file,
    })
  return result
})

function findKeybindProperties(text: string, name: string) {
  const keybinds = findKeybindObjects(text).at(-1)?.children?.[1]
  return keybinds?.children?.filter((property) => property.children?.[0]?.value === name) ?? []
}

function findKeybindObjects(text: string) {
  const tree = parseTree(text)
  if (tree === undefined) return []
  return tree.children?.filter((property) => property.children?.[0]?.value === "keybinds") ?? []
}

function removeProperty(text: string, property: Node) {
  const properties = property.parent?.children ?? []
  const index = properties.indexOf(property)
  const end = property.offset + property.length
  const next = properties[index + 1]
  if (next) {
    const comma = findComma(text, end, next.offset)
    if (comma !== undefined) return text.slice(0, property.offset) + text.slice(end, comma) + text.slice(comma + 1)
  }
  const previous = properties[index - 1]
  if (previous) {
    const comma = findComma(text, previous.offset + previous.length, property.offset)
    if (comma !== undefined) return text.slice(0, comma) + text.slice(comma + 1, property.offset) + text.slice(end)
  }
  const comma = findComma(text, end, (property.parent?.offset ?? 0) + (property.parent?.length ?? 0))
  if (comma !== undefined) return text.slice(0, property.offset) + text.slice(end, comma) + text.slice(comma + 1)
  return text.slice(0, property.offset) + text.slice(end)
}

function findComma(text: string, start: number, end: number) {
  const scanner = createScanner(text, false)
  scanner.setPosition(start)
  while (true) {
    scanner.scan()
    const offset = scanner.getTokenOffset()
    if (scanner.getTokenLength() === 0 || offset >= end) return
    if (text[offset] === ",") return offset
  }
}

export function migrateV1(legacy: TuiConfigV1.Info | undefined, kv: Record<string, any>): Info {
  const plugins = [
    ...(legacy?.plugin?.map((plugin) =>
      typeof plugin === "string" ? plugin : { package: plugin[0], options: plugin[1] },
    ) ?? []),
    ...Object.entries(legacy?.plugin_enabled ?? {}).map(([id, enabled]) => (enabled ? id : `-${id}`)),
  ]
  const themeName = legacy?.theme ?? kv.theme
  const themeMode = kv.theme_mode_lock
  const attentionSoundPack = kv.attention_sound_pack
  const diffView = kv.diff_viewer_view ?? (legacy?.diff_style === "stacked" ? "unified" : undefined)
  const thinking =
    kv.thinking_mode ?? (kv.thinking_visibility === undefined ? undefined : kv.thinking_visibility ? "show" : "hide")
  const keybinds =
    legacy?.keybinds === undefined
      ? undefined
      : Object.fromEntries(
          Object.entries(legacy.keybinds).flatMap(([name, value]) => {
            const target = TuiKeybind.CommandMap[name as keyof typeof TuiKeybind.CommandMap] ?? name
            if (!(target in Definitions)) return []
            return [[target, value]]
          }),
        )

  return {
    ...(themeName !== undefined || themeMode !== undefined
      ? {
          theme: {
            ...(themeName === undefined ? {} : { name: themeName }),
            ...(themeMode === undefined ? {} : { mode: themeMode }),
          },
        }
      : {}),
    ...(keybinds === undefined ? {} : { keybinds }),
    ...(plugins.length ? { plugins } : {}),
    ...(legacy?.leader_timeout === undefined ? {} : { leader: { timeout: legacy.leader_timeout } }),
    ...(legacy?.scroll_speed === undefined && legacy?.scroll_acceleration?.enabled === undefined
      ? {}
      : {
          scroll: {
            ...(legacy.scroll_speed === undefined ? {} : { speed: legacy.scroll_speed }),
            ...(legacy.scroll_acceleration?.enabled === undefined
              ? {}
              : { acceleration: legacy.scroll_acceleration.enabled }),
          },
        }),
    ...(legacy?.attention === undefined && attentionSoundPack === undefined
      ? {}
      : {
          attention: {
            ...legacy?.attention,
            ...(attentionSoundPack === undefined ? {} : { sound_pack: attentionSoundPack }),
          },
        }),
    ...(legacy?.diff_style === undefined &&
    kv.diff_wrap_mode === undefined &&
    kv.diff_viewer_show_file_tree === undefined &&
    kv.diff_viewer_single_patch === undefined &&
    diffView === undefined
      ? {}
      : {
          diffs: {
            ...(kv.diff_wrap_mode === undefined ? {} : { wrap: kv.diff_wrap_mode }),
            ...(kv.diff_viewer_show_file_tree === undefined ? {} : { tree: kv.diff_viewer_show_file_tree }),
            ...(kv.diff_viewer_single_patch === undefined ? {} : { single: kv.diff_viewer_single_patch }),
            ...(diffView === undefined ? {} : { view: diffView }),
          },
        }),
    ...(kv.terminal_title_enabled === undefined ? {} : { terminal: { title: kv.terminal_title_enabled } }),
    ...(kv.file_context_enabled === undefined && kv.paste_summary_enabled === undefined
      ? {}
      : {
          prompt: {
            ...(kv.file_context_enabled === undefined ? {} : { editor: kv.file_context_enabled }),
            ...(kv.paste_summary_enabled === undefined
              ? {}
              : { paste: kv.paste_summary_enabled ? ("compact" as const) : ("full" as const) }),
          },
        }),
    ...(kv.sidebar === undefined &&
    kv.scrollbar_visible === undefined &&
    thinking === undefined &&
    kv.exploration_grouping === undefined
      ? {}
      : {
          session: {
            ...(kv.sidebar === undefined ? {} : { sidebar: kv.sidebar }),
            ...(kv.scrollbar_visible === undefined ? {} : { scrollbar: kv.scrollbar_visible }),
            ...(thinking === undefined ? {} : { thinking }),
            ...(kv.exploration_grouping === undefined
              ? {}
              : { grouping: kv.exploration_grouping ? ("auto" as const) : ("none" as const) }),
          },
        }),
    ...(kv.animations_enabled === undefined ? {} : { animations: kv.animations_enabled }),
    ...(legacy?.mouse === undefined ? {} : { mouse: legacy.mouse }),
    ...(legacy?.cursor === undefined ? {} : { cursor: legacy.cursor }),
  }
}

const readJson = Effect.fnUntraced(function* (target: string) {
  const fs = yield* FileSystem.FileSystem
  const text = yield* fs.readFileString(target).pipe(Effect.orElseSucceed(() => undefined))
  if (text === undefined) return undefined
  const errors: ParseError[] = []
  const value: any = parse(text, errors, { allowTrailingComma: true })
  if (errors.length) return undefined
  return Option.getOrUndefined(decodeRecord(value))
})

