export const INTERACTIVE_INPUT_ERROR = "opencode mini requires a controlling terminal for input"

export type InteractiveStdin = {
  stdin: NodeJS.ReadStream
  cleanup(): void
}

type MiniHost = MiniFrontendInput["host"]

function preferences(statePath: string): MiniHost["preferences"] {
  const repository = createModelPreferenceRepository(path.join(statePath, "model.json"))
  return {
    async resolveVariant(model) {
      if (!model) return
      return repository.resolveVariant(model)
    },
    async saveVariant(model, variant) {
      if (!model) return
      await repository.saveVariant(model, variant).catch(() => undefined)
    },
  }
}

function signal(name: "SIGINT" | "SIGUSR2"): MiniHost["signals"]["sigint"] {
  return {
    subscribe(listener) {
      let subscribed = true
      process.on(name, listener)
      return () => {
        if (!subscribed) return
        subscribed = false
        process.off(name, listener)
      }
    },
  }
}

function createTrace(
  logPath: string,
  diagnostics: { pid: number; cwd: string; argv: string[] },
): MiniHost["diagnostics"]["trace"] {
  if (!process.env.OPENCODE_DIRECT_TRACE) return
  const stamp = new Date()
    .toISOString()
    .replace(/[-:]/g, "")
    .replace(/\.\d+Z$/, "Z")
  const target = path.join(logPath, "direct", `${stamp}-${diagnostics.pid}.jsonl`)
  const text = (data: unknown) =>
    JSON.stringify(data, (_key, value) => (typeof value === "bigint" ? String(value) : value), 0)
  fs.mkdirSync(path.dirname(target), { recursive: true })
  fs.writeFileSync(
    path.join(logPath, "direct", "latest.json"),
    text({
      time: new Date().toISOString(),
      ...diagnostics,
      path: target,
    }) + "\n",
  )
  const trace = {
    write(type: string, data?: unknown) {
      fs.appendFileSync(
        target,
        text({
          time: new Date().toISOString(),
          pid: diagnostics.pid,
          type,
          data,
        }) + "\n",
      )
    },
  }
  trace.write("trace.start", {
    argv: diagnostics.argv,
    cwd: diagnostics.cwd,
    path: target,
  })
  return trace
}

function openTerminalStdin(target: string): NodeJS.ReadStream {
  return new ReadStream(fs.openSync(target, "r"))
}

export function resolveInteractiveStdin(
  stdin: NodeJS.ReadStream = process.stdin,
  open: (target: string) => NodeJS.ReadStream = openTerminalStdin,
  platform: NodeJS.Platform = process.platform,
): InteractiveStdin {
  if (stdin.isTTY) return { stdin, cleanup() {} }
  const target = platform === "win32" ? "CONIN$" : "/dev/tty"
  try {
    const source = open(target)
    let cleaned = false
    return {
      stdin: source,
      cleanup() {
        if (cleaned) return
        cleaned = true
        source.destroy()
      },
    }
  } catch (error) {
    throw new Error(INTERACTIVE_INPUT_ERROR, { cause: error })
  }
}

/** @internal Exported for owner-local resource cleanup tests. */
export async function usingInteractiveStdin<T>(
  run: (terminal: InteractiveStdin) => Promise<T>,
  resolve: () => InteractiveStdin = resolveInteractiveStdin,
) {
  const terminal = resolve()
  try {
    return await run(terminal)
  } finally {
    terminal.cleanup()
  }
}

/** @internal Exported for owner-local host capability tests. */
export function createMiniHost(input: {
  terminal: InteractiveStdin
  directory: string
  paths: { home: string; state: string; log: string }
}): MiniHost {
  const paths = input.paths
  const diagnostics = {
    pid: process.pid,
    cwd: input.directory,
    argv: process.argv.slice(2),
  }
  return {
    version: OPENCODE_VERSION,
    terminal: { stdin: input.terminal.stdin },
    platform: process.platform,
    stdout: {
      write(value) {
        process.stdout.write(value)
      },
    },
    files: {
      readText: (url) => readFile(new URL(url), "utf8"),
    },
    editor: {
      async open(options) {
        const { openEditor } = await import("@opencode/tui/editor")
        return openEditor(options)
      },
    },
    paths: { home: paths.home },
    signals: {
      sigint: signal("SIGINT"),
      sigusr2: signal("SIGUSR2"),
    },
    startup: {
      showTiming: ["1", "true"].includes(process.env.OPENCODE_SHOW_TTFD?.toLowerCase() ?? ""),
      now: () => performance.now(),
    },
    diagnostics: {
      trace: createTrace(paths.log, diagnostics),
    },
    preferences: preferences(paths.state),
  }
}

import { Service, type Endpoint } from "@opencode/client/effect/service"
import { ClientError, OpenCode, type OpenCodeClient } from "@opencode/client/promise"
import type { MiniFrontendInput } from "@opencode/tui/mini"
import { setTimeout } from "node:timers/promises"
import { readStdin } from "./util/io"
import { createMiniHost, INTERACTIVE_INPUT_ERROR, usingInteractiveStdin } from "./mini-host"
import { parseSessionTargetModel, resolveSessionTarget, type SessionTargetPreparation } from "./session-target"
import { Env } from "./env"

export type MiniCommandInput = {
  server: {
    endpoint: Endpoint
    reconnect?: (signal: AbortSignal) => Promise<Endpoint>
  }
  continue?: boolean
  session?: string
  fork?: boolean
  model?: string
  agent?: string
  prompt?: string
  replay?: boolean
  replayLimit?: number
  demo?: boolean
  tuiConfig?: MiniFrontendInput["tuiConfig"]
  config?: MiniFrontendInput["config"]
  paths: { home: string; state: string; log: string }
}

type Model = MiniFrontendInput["model"]

class MiniInputError extends Error {}

export async function runMini(input: MiniCommandInput) {
  try {
    validate(input)
    await usingInteractiveStdin(async (terminal) => {
      const initialInput = mergeInput(process.stdin.isTTY ? undefined : await readStdin(), input.prompt)
      const frontendTask = import("@opencode/tui/mini")
      const directory = localDirectory()
      const connection = createMiniConnection(input.server)
      const sdk = connection.sdk
      const environment = input.server.reconnect ? Env.session() : undefined
      const requested = parseModel(input.model)
      const model = requested ? { providerID: requested.providerID, modelID: requested.id } : undefined
      const prepare = prepareTarget(input.agent)
      const resolveTarget = async (initial: OpenCodeClient, signal: AbortSignal) => {
        const resolved = await resolveMiniTarget({
          sdk: initial,
          reconnect: connection.reconnect,
          signal,
          resolve: (client) =>
            resolveSessionTarget({
              client,
              location: { directory },
              continue: input.continue,
              session: input.session,
              fork: input.fork,
              model: requested,
              agent: input.agent,
              environment,
              prepare,
              signal,
            }).catch((error) => {
              if (error instanceof Error && error.message === "Session not found")
                throw new MiniInputError(error.message)
              throw error
            }),
        })
        const target = resolved.value
        return {
          sdk: resolved.sdk,
          sessionID: target.session.id,
          sessionTitle: target.session.title,
          location: target.location,
          model: target.model ? { providerID: target.model.providerID, modelID: target.model.id } : undefined,
          variant: target.model?.variant,
          agent: target.agent,
          resume: target.resume,
        }
      }
      const create = (
        client: OpenCodeClient,
        next: {
          location: { directory: string }
          agent: string | undefined
          model: Model
          variant: string | undefined
        },
        signal?: AbortSignal,
      ) =>
        resolveSessionTarget({
          client,
          location: { directory: next.location.directory },
          agent: next.agent,
          environment,
          model: next.model
            ? { providerID: next.model.providerID, id: next.model.modelID, variant: next.variant }
            : undefined,
          prepare,
          signal,
        }).then((target) => ({
          sessionID: target.session.id,
          sessionTitle: target.session.title,
          location: target.location,
          model: target.model ? { providerID: target.model.providerID, modelID: target.model.id } : undefined,
          variant: target.model?.variant,
          agent: target.agent,
          resume: false,
        }))
      const frontend = await frontendTask
      return frontend.runMiniFrontend({
        host: createMiniHost({ terminal, directory, paths: input.paths }),
        sdk,
        directory,
        target: resolveTarget,
        reconnect: connection.reconnect,
        createSession: create,
        agent: input.agent,
        model,
        variant: requested?.variant,
        files: [],
        initialInput,
        replay: input.replay ?? true,
        replayLimit: input.replayLimit,
        demo: input.demo,
        tuiConfig: input.tuiConfig,
        config: input.config,
      })
    })
  } catch (error) {
    if (error instanceof MiniInputError || (error instanceof Error && error.message === INTERACTIVE_INPUT_ERROR))
      fail(error.message)
    throw error
  }
}

/** @internal Exported for CLI boundary tests. */
export function createMiniConnection(input: MiniCommandInput["server"]) {
  const make = (endpoint: Endpoint) =>
    OpenCode.make({
      baseUrl: endpoint.url,
      headers: Service.headers(endpoint),
    })
  const reconnect = input.reconnect
  return {
    sdk: make(input.endpoint),
    reconnect: reconnect
      ? async (signal: AbortSignal) => {
          const endpoint = await reconnect(signal)
          return make(endpoint)
        }
      : undefined,
  }
}

/** @internal Exported for reconnect lifecycle tests. */
export async function resolveMiniTarget<A>(input: {
  sdk: OpenCodeClient
  reconnect?: (signal: AbortSignal) => Promise<OpenCodeClient>
  signal: AbortSignal
  resolve: (sdk: OpenCodeClient) => Promise<A>
}) {
  let sdk = input.sdk
  while (true) {
    try {
      return { sdk, value: await input.resolve(sdk) }
    } catch (error) {
      if (!input.reconnect || !(error instanceof ClientError) || error.reason !== "Transport") throw error
      while (true) {
        try {
          sdk = await input.reconnect(input.signal)
          break
        } catch (resolveError) {
          if (input.signal.aborted) throw resolveError
          await setTimeout(250, undefined, { signal: input.signal })
        }
      }
    }
  }
}

export function validateMiniTerminal() {
  if (!process.stdout.isTTY) fail("opencode mini requires a TTY stdout")
}

/** @internal Exported for testing. */
export function mergeInput(piped: string | undefined, prompt: string | undefined) {
  if (!prompt) return piped || undefined
  if (!piped) return prompt
  return piped + "\n" + prompt
}

function validate(input: MiniCommandInput) {
  validateMiniTerminal()
  if (input.replayLimit !== undefined && (!Number.isInteger(input.replayLimit) || input.replayLimit <= 0)) {
    fail("--replay-limit must be a positive integer")
  }
  if (input.fork && !input.continue && !input.session) fail("--fork requires --continue or --session")
}

function localDirectory(): string {
  const root = process.env.PWD ?? process.cwd()
  try {
    process.chdir(root)
    return process.cwd()
  } catch {
    throw new MiniInputError(`Failed to change directory to ${root}`)
  }
}

function parseModel(value?: string) {
  try {
    return parseSessionTargetModel(value)
  } catch {
    throw new MiniInputError("--model must use the format provider/model[#variant]")
  }
}

function prepareTarget(requestedAgent?: string): SessionTargetPreparation {
  return async (input) => ({ model: input.model, agent: requestedAgent ?? input.agent })
}

function fail(message: string): never {
  process.stderr.write(`\x1b[91m\x1b[1mError: \x1b[0m${message}\n`)
  process.exit(1)
}

import type {
  EventSubscribeOutput,
  JsonValue,
  LocationRef,
  OpenCodeClient,
  SessionMessageAssistantTool,
  SessionMessageInfo,
  ToolContent,
} from "@opencode/client/promise"
import { SessionMessage } from "@opencode/schema/session-message"
import { EOL } from "node:os"
import { readFile } from "node:fs/promises"
import { nonEmptyToolContent, toolOutputText, type MiniToolPart } from "@opencode/tui/mini/tool"
import { UI } from "./ui"

type Model = {
  providerID: string
  modelID: string
}

type File = {
  url: string
  filename: string
  mime: string
}

type Input = {
  client: OpenCodeClient
  sessionID: string
  location: LocationRef
  message: string
  files: File[]
  agent?: string
  model?: Model
  variant?: string
  thinking: boolean
  format: "default" | "json"
  auto: boolean
  /** True when the client is attached to a shared server rather than an exclusive in-process one. */
  attached: boolean
  compatibility?: "v1"
  renderTool: (part: SessionMessageAssistantTool) => Promise<void>
  renderToolError: (part: SessionMessageAssistantTool) => Promise<void>
}

type StartedPart = {
  id: string
  timestamp: number
}

type ToolState = StartedPart & {
  assistantMessageID: string
  tool: string
  input: Record<string, JsonValue>
  raw?: string
  provider?: unknown
  providerState?: SessionMessageAssistantTool["providerState"]
  metadata: Record<string, JsonValue>
  content: ToolContent[]
}

type V2Event = EventSubscribeOutput
type FormRequest = Extract<V2Event, { type: "form.created" }>["data"]["form"]

// MCP elicitations are temporarily owned by the "global" sentinel instead of a real
// session. An exclusive local process may treat them as this run's blockers; an
// attached client must not cancel input that may belong to another session.
const GLOBAL_FORM_SESSION_ID = "global"

const QUESTION_CANCELLED_FEEDBACK =
  "This non-interactive run cannot ask the user questions, so the question was cancelled. Continue without an answer; make reasonable assumptions and state them."

const PERMISSION_REJECTED_FEEDBACK =
  "This non-interactive run cannot ask the user for permission, so the request was rejected. Continue without this action."

export async function runNonInteractivePrompt(input: Input) {
  const controller = new AbortController()
  const stream = input.client.event.subscribe({ signal: controller.signal })[Symbol.asyncIterator]()
  const connected = await stream.next()
  if (connected.done) throw new Error("Event stream disconnected before prompt admission")

  const messageID = SessionMessage.ID.create()
  const starts = new Map<string, StartedPart>()
  const tools = new Map<string, ToolState>()
  const renderedText = new Map<string, string>()
  const renderedReasoning = new Map<string, string>()
  const renderedTools = new Set<string>()
  let submitted = false
  let promoted = false
  let emittedError = false
  let permissionRejected = false
  let formCancelled = false
  let interrupted = false
  let v1InvalidOutput = false
  let prePromotionError: { message: string; [key: string]: unknown } | undefined
  let finalizing = false
  let admission: AbortController | undefined
  let pendingStep: { timestamp: number; part: Record<string, unknown>; label: string } | undefined

  const emit = (type: string, timestamp: number, data: Record<string, unknown>) => {
    if (input.format !== "json") return false
    process.stdout.write(JSON.stringify({ type, timestamp, sessionID: input.sessionID, ...data }) + EOL)
    return true
  }

  const writeText = (part: { text: string; [key: string]: unknown }, timestamp: number) => {
    if (emit("text", timestamp, { part })) return
    const text = part.text.trim()
    if (!text) return
    if (!process.stdout.isTTY) {
      process.stdout.write(text + EOL)
      return
    }
    UI.empty()
    UI.println(text)
    UI.empty()
  }

  const writeReasoning = (part: { text: string; [key: string]: unknown }, timestamp: number) => {
    if (emit("reasoning", timestamp, { part })) return
    const text = part.text.trim()
    if (!text) return
    const line = `Thinking: ${text}`
    if (!process.stdout.isTTY) return void process.stdout.write(line + EOL)
    UI.empty()
    UI.println(`${UI.Style.TEXT_DIM}\u001b[3m${line}\u001b[0m${UI.Style.TEXT_NORMAL}`)
    UI.empty()
  }

  const flushStep = () => {
    if (!pendingStep) return
    const value = pendingStep
    pendingStep = undefined
    if (!emit("step_start", value.timestamp, { part: value.part }) && input.format !== "json") {
      UI.empty()
      UI.println(value.label)
      UI.empty()
    }
  }

  // Subagents run in child sessions; their asks and questions belong to this run too. Other
  // sessions on a shared server (e.g. the TUI's) must be left alone.
  const owned = new Map<string, Promise<boolean>>([[input.sessionID, Promise.resolve(true)]])
  const ownsSession = (sessionID: string): Promise<boolean> => {
    const known = owned.get(sessionID)
    if (known) return known
    const result =
      sessionID === GLOBAL_FORM_SESSION_ID
        ? Promise.resolve(false)
        : input.client.session
            .get({ sessionID })
            .then((session) => (session.parentID ? ownsSession(session.parentID) : false))
            .catch(() => false)
    owned.set(sessionID, result)
    return result
  }

  const replyPermission = async (request: {
    id: string
    sessionID: string
    action: string
    resources: ReadonlyArray<string>
  }) => {
    // Nobody can approve here. Outside V1 compatibility, reject with feedback so the tool fails
    // as ordinary model-visible output and the model continues without the action.
    const continuing = !input.auto && input.compatibility !== "v1"
    if (!input.auto) {
      if (!continuing) permissionRejected = true
      UI.println(
        UI.Style.TEXT_WARNING_BOLD + "!",
        UI.Style.TEXT_NORMAL +
          `permission requested: ${request.action} (${request.resources.join(", ")}); auto-rejecting`,
      )
    }
    await input.client.permission
      .reply({
        sessionID: request.sessionID,
        requestID: request.id,
        decision: input.auto ? "once" : "reject",
        ...(continuing ? { message: PERMISSION_REJECTED_FEEDBACK } : {}),
      })
      .catch(() => {})
    if (!input.auto && !continuing) {
      await input.client.session.interrupt({ sessionID: input.sessionID }).catch(() => {})
    }
  }

  const cancelForm = async (request: Pick<FormRequest, "id" | "sessionID" | "metadata">) => {
    // Nobody can answer a question here. Outside V1 compatibility, cancel it with a message so the
    // question tool fails as ordinary model-visible output and the model continues without an answer.
    const continuing = request.metadata?.kind === "question" && input.compatibility !== "v1"
    try {
      await input.client.session.form.cancel(
        {
          sessionID: request.sessionID,
          formID: request.id,
          ...(continuing ? { message: QUESTION_CANCELLED_FEEDBACK } : {}),
        },
        ...formRequestOptions(request.sessionID === GLOBAL_FORM_SESSION_ID ? input.location : undefined),
      )
    } catch (error) {
      if (!formAlreadySettled(error)) throw error
    }
    if (continuing) return
    formCancelled = true
    if (input.compatibility !== "v1") process.exitCode = 1
  }

  const consume = async () => {
    while (!controller.signal.aborted) {
      const next = await stream.next().catch((error) => {
        if (!emittedError) throw error
        return { done: true as const, value: undefined }
      })
      if (next.done) {
        if (emittedError) return
        throw new Error("Event stream disconnected during prompt execution")
      }
      const event = next.value

      if (event.type === "permission.asked" && submitted && (await ownsSession(event.data.sessionID))) {
        await replyPermission(event.data)
        continue
      }
      if (
        event.type === "form.created" &&
        submitted &&
        ((await ownsSession(event.data.form.sessionID)) ||
          (!input.attached &&
            event.data.form.sessionID === GLOBAL_FORM_SESSION_ID &&
            sameLocation(event.location, input.location)))
      ) {
        await cancelForm(event.data.form)
        continue
      }
      if (!("sessionID" in event.data) || event.data.sessionID !== input.sessionID) continue
      const time = toMillis("created" in event ? event.created : undefined)

      if (event.type === "session.inbox.delivered") {
        if (event.data.inboxID === messageID) {
          promoted = true
          prePromotionError = undefined
          continue
        }
      }
      if (
        event.type === "session.execution.interrupted" &&
        event.data.reason === "user" &&
        (interrupted || permissionRejected || formCancelled)
      ) {
        return
      }
      if (!promoted && event.type === "session.execution.failed") {
        prePromotionError = event.data.error
        if (finalizing) return
        continue
      }
      if (
        !promoted &&
        finalizing &&
        (event.type === "session.execution.succeeded" || event.type === "session.execution.interrupted")
      )
        return
      if (!promoted) continue
      if (finalizing && !event.type.startsWith("session.execution.")) continue

      if (event.type === "session.step.started") {
        const part = {
          id: partID(event.id),
          sessionID: input.sessionID,
          messageID: event.data.assistantMessageID,
          type: "step-start",
          snapshot: event.data.snapshot,
        }
        if (input.compatibility === "v1") {
          pendingStep = {
            timestamp: time,
            part,
            label: `> ${event.data.agent} · ${event.data.model.id}`,
          }
          continue
        }
        if (!emit("step_start", time, { part }) && input.format !== "json") {
          UI.empty()
          UI.println(`> ${event.data.agent} · ${event.data.model.id}`)
          UI.empty()
        }
        continue
      }

      if (event.type === "session.text.started") {
        flushStep()
        starts.set(`text\u0000${contentKey(event.data.assistantMessageID, event.data.ordinal)}`, {
          id: partID(event.id),
          timestamp: time,
        })
        continue
      }
      if (event.type === "session.text.ended") {
        const key = contentKey(event.data.assistantMessageID, event.data.ordinal)
        const started = starts.get(`text\u0000${key}`)
        starts.delete(`text\u0000${key}`)
        const part = {
          id: started?.id ?? partID(event.id),
          sessionID: input.sessionID,
          messageID: event.data.assistantMessageID,
          type: "text",
          text: event.data.text,
          time: { start: started?.timestamp ?? time, end: time },
        }
        renderedText.set(key, event.data.text)
        writeText(part, time)
        continue
      }

      if (event.type === "session.reasoning.started") {
        flushStep()
        starts.set(`reasoning\u0000${contentKey(event.data.assistantMessageID, event.data.ordinal)}`, {
          id: partID(event.id),
          timestamp: time,
        })
        continue
      }
      if (event.type === "session.reasoning.ended" && input.thinking) {
        const key = contentKey(event.data.assistantMessageID, event.data.ordinal)
        const started = starts.get(`reasoning\u0000${key}`)
        starts.delete(`reasoning\u0000${key}`)
        const part = {
          id: started?.id ?? partID(event.id),
          sessionID: input.sessionID,
          messageID: event.data.assistantMessageID,
          type: "reasoning",
          text: event.data.text,
          metadata: event.data.state,
          time: { start: started?.timestamp ?? time, end: time },
        }
        renderedReasoning.set(key, event.data.text)
        writeReasoning(part, time)
        continue
      }

      if (event.type === "session.tool.input.started") {
        flushStep()
        tools.set(toolKey(event.data.assistantMessageID, event.data.id), {
          id: partID(event.id),
          timestamp: time,
          assistantMessageID: event.data.assistantMessageID,
          tool: event.data.name,
          input: {},
          metadata: {},
          content: [],
        })
        continue
      }
      if (event.type === "session.tool.input.ended") {
        const current = tools.get(toolKey(event.data.assistantMessageID, event.data.id))
        if (current) current.raw = event.data.text
        continue
      }
      if (event.type === "session.tool.input.delta") {
        const current = tools.get(toolKey(event.data.assistantMessageID, event.data.id))
        if (current) current.raw = (current.raw ?? "") + event.data.delta
        continue
      }
      if (event.type === "session.tool.called") {
        flushStep()
        const key = toolKey(event.data.assistantMessageID, event.data.id)
        const current = tools.get(key)
        tools.set(key, {
          id: current?.id ?? partID(event.id),
          timestamp: current?.timestamp ?? time,
          assistantMessageID: event.data.assistantMessageID,
          tool: current?.tool ?? "tool",
          input: event.data.input,
          raw: current?.raw,
          provider: { executed: event.data.executed, state: event.data.state },
          providerState: event.data.state,
          metadata: {},
          content: [],
        })
        continue
      }
      if (event.type === "session.tool.progress") {
        const current = tools.get(toolKey(event.data.assistantMessageID, event.data.id))
        if (current) {
          current.metadata = event.data.metadata
        }
        continue
      }
      if (event.type === "session.tool.success") {
        const key = toolKey(event.data.assistantMessageID, event.data.id)
        const current = tools.get(key) ?? fallbackTool(event)
        const tool: SessionMessageAssistantTool = {
          type: "tool",
          id: event.data.id,
          name: current.tool,
          executed: event.data.executed,
          providerState: current.providerState,
          providerResultState: event.data.resultState,
          state: {
            status: "completed",
            input: current.input,
            metadata: event.data.metadata,
            content: event.data.content,
          },
          time: { created: current.timestamp, ran: current.timestamp, completed: time },
        }
        const part: MiniToolPart = {
          partID: current.id,
          sessionID: input.sessionID,
          messageID: event.data.assistantMessageID,
          type: "tool",
          id: event.data.id,
          tool: current.tool,
          state: {
            status: "completed",
            input: current.input,
            output: toolOutputText(current.tool, event.data.content),
            title: current.tool,
            metadata: {
              metadata: event.data.metadata,
              content: event.data.content,
              providerCall: current.provider,
              providerResult: { executed: event.data.executed, state: event.data.resultState },
              rawInput: current.raw,
            },
            time: { start: current.timestamp, end: time },
          },
        }
        tools.delete(key)
        renderedTools.add(key)
        if (!emit("tool_use", time, { part })) await input.renderTool(tool)
        continue
      }
      if (event.type === "session.tool.failed") {
        const key = toolKey(event.data.assistantMessageID, event.data.id)
        const current = tools.get(key) ?? fallbackTool(event)
        const error = event.data.error.message
        const metadata = event.data.metadata ?? current.metadata
        const content = event.data.content ?? nonEmptyToolContent(current.content)
        const tool: SessionMessageAssistantTool = {
          type: "tool",
          id: event.data.id,
          name: current.tool,
          executed: event.data.executed,
          providerState: current.providerState,
          providerResultState: event.data.resultState,
          state: {
            status: "error",
            input: current.input,
            metadata,
            content,
            error: event.data.error,
          },
          time: { created: current.timestamp, ran: current.timestamp, completed: time },
        }
        const part: MiniToolPart = {
          partID: current.id,
          sessionID: input.sessionID,
          messageID: event.data.assistantMessageID,
          type: "tool",
          id: event.data.id,
          tool: current.tool,
          state: {
            status: "error",
            input: current.input,
            error,
            metadata: {
              providerCall: current.provider,
              providerResult: { executed: event.data.executed, state: event.data.resultState },
              rawInput: current.raw,
            },
            time: { start: current.timestamp, end: time },
          },
        }
        tools.delete(key)
        renderedTools.add(key)
        if (input.compatibility === "v1" && (permissionRejected || formCancelled)) continue
        if (!emit("tool_use", time, { part })) {
          if (content && toolOutputText(current.tool, content).trim())
            await input.renderTool({
              ...tool,
              state: {
                status: "completed",
                input: current.input,
                metadata,
                content,
              },
            })
          await input.renderToolError(tool)
          UI.error(error)
        }
        continue
      }

      if (event.type === "session.step.ended") {
        flushStep()
        const part = {
          id: partID(event.id),
          sessionID: input.sessionID,
          messageID: event.data.assistantMessageID,
          type: "step-finish",
          reason: event.data.finish,
          snapshot: event.data.snapshot,
          cost: event.data.cost,
          tokens: event.data.tokens,
        }
        emit("step_finish", time, { part })
        continue
      }
      if (event.type === "session.step.failed") {
        if (input.compatibility === "v1" && event.data.error.message === "The provider response ended unexpectedly.") {
          pendingStep = undefined
          v1InvalidOutput = true
          continue
        }
        if (interrupted || permissionRejected || formCancelled) continue
        flushStep()
        emittedError = true
        process.exitCode = 1
        if (!emit("error", time, { error: event.data.error })) UI.error(event.data.error.message)
        continue
      }
      if (event.type === "session.execution.failed") {
        if (input.compatibility === "v1" && (v1InvalidOutput || permissionRejected || formCancelled)) return
        flushStep()
        if (!emittedError && !formCancelled) {
          emittedError = true
          process.exitCode = 1
          if (!emit("error", time, { error: event.data.error })) UI.error(event.data.error.message)
        }
        return
      }
      if (event.type === "session.execution.interrupted") {
        if (input.compatibility === "v1" && (permissionRejected || formCancelled)) return
        if (event.data.reason === "user" && interrupted) process.exitCode = 130
        // A declined tool call ends the step with an interruption; it was already reported above.
        if (event.data.reason !== "user" && !emittedError && !permissionRejected && !formCancelled) {
          emittedError = true
          process.exitCode = 1
          const error = { type: "aborted" as const, message: `Session interrupted: ${event.data.reason}` }
          if (!emit("error", time, { error })) UI.error(error.message)
        }
        return
      }
      if (event.type === "session.execution.succeeded") return
    }
  }

  const projectedMessages = async () => {
    const messages: SessionMessageInfo[] = []
    let cursor: string | undefined
    while (true) {
      const page = await input.client.message.list(
        cursor
          ? { sessionID: input.sessionID, limit: 200, cursor }
          : { sessionID: input.sessionID, limit: 200, order: "desc" },
      )
      for (const message of page.data) {
        if (message.id === messageID) return { found: true, messages: messages.toReversed() }
        messages.push(message)
      }
      cursor = page.cursor.next ?? undefined
      if (!cursor) return { found: false, messages: [] }
    }
  }

  const reconcile = async () => {
    const projected = await projectedMessages()
    for (const message of projected.messages) {
      if (message.type !== "assistant") continue
      const timestamp = message.time.completed ?? message.time.created
      let textOrdinal = 0
      let reasoningOrdinal = 0
      for (const item of message.content) {
        if (item.type === "text") {
          const ordinal = textOrdinal++
          const key = contentKey(message.id, ordinal)
          const rendered = renderedText.get(key) ?? ""
          if (rendered === item.text || !item.text.startsWith(rendered)) continue
          const text = item.text.slice(rendered.length)
          writeText(
            {
              id: projectedPartID(message.id, `text-${ordinal}`),
              sessionID: input.sessionID,
              messageID: message.id,
              type: "text",
              text,
              time: { start: message.time.created, end: timestamp },
            },
            timestamp,
          )
          renderedText.set(key, item.text)
          continue
        }
        if (item.type === "reasoning") {
          const ordinal = reasoningOrdinal++
          if (!input.thinking) continue
          const key = contentKey(message.id, ordinal)
          const rendered = renderedReasoning.get(key) ?? ""
          if (rendered === item.text || !item.text.startsWith(rendered)) continue
          const text = item.text.slice(rendered.length)
          const part = {
            id: projectedPartID(message.id, `reasoning-${ordinal}`),
            sessionID: input.sessionID,
            messageID: message.id,
            type: "reasoning",
            text,
            metadata: item.state,
            time: { start: message.time.created, end: timestamp },
          }
          renderedReasoning.set(key, item.text)
          writeReasoning(part, timestamp)
          continue
        }

        const key = toolKey(message.id, item.id)
        if (renderedTools.has(key) || item.state.status === "streaming" || item.state.status === "running") continue
        const part: MiniToolPart = {
          partID: projectedPartID(message.id, `tool-${item.id}`),
          sessionID: input.sessionID,
          messageID: message.id,
          type: "tool",
          id: item.id,
          tool: item.name,
          state:
            item.state.status === "completed"
              ? {
                  status: "completed",
                  input: item.state.input,
                  output: toolOutputText(item.name, item.state.content),
                  title: item.name,
                  metadata: { metadata: item.state.metadata, content: item.state.content },
                  time: { start: item.time.ran ?? item.time.created, end: item.time.completed ?? timestamp },
                }
              : {
                  status: "error",
                  input: item.state.input,
                  error: item.state.error.message,
                  metadata: { metadata: item.state.metadata, content: item.state.content },
                  time: { start: item.time.ran ?? item.time.created, end: item.time.completed ?? timestamp },
                },
        }
        renderedTools.add(key)
        if (emit("tool_use", timestamp, { part })) continue
        if (item.state.status === "completed") {
          await input.renderTool(item)
          continue
        }
        if (item.state.content && toolOutputText(item.name, item.state.content).trim()) {
          await input.renderTool({
            ...item,
            state: {
              status: "completed",
              input: item.state.input,
              metadata: item.state.metadata,
              content: item.state.content,
            },
          })
        }
        await input.renderToolError(item)
        UI.error(item.state.error.message)
      }

      // A declined tool call ends its step with an interrupted-step error that is
      // only a consequence of our own rejection; it was already reported above.
      if (message.error && !emittedError && !permissionRejected && !formCancelled) {
        emittedError = true
        process.exitCode = 1
        if (!emit("error", timestamp, { error: message.error })) UI.error(message.error.message)
      }
    }
    return {
      found: projected.found,
      responded: projected.messages.some((message) => message.type === "assistant"),
    }
  }

  const interrupt = () => {
    if (interrupted) process.exit(130)
    interrupted = true
    process.exitCode = 130
    admission?.abort()
    void input.client.session.interrupt({ sessionID: input.sessionID }).catch(() => {})
  }
  process.on("SIGINT", interrupt)

  let completed: Promise<void> | undefined
  try {
    if (input.agent) {
      await input.client.session.switchAgent({ sessionID: input.sessionID, agent: input.agent })
    }
    const selected = input.model
      ? { providerID: input.model.providerID, id: input.model.modelID, variant: input.variant }
      : input.variant
        ? await input.client.session
            .get({ sessionID: input.sessionID })
            .then((result) => result.model)
            .then(async (model) => {
              if (model) return { ...model, variant: input.variant }
              const result = await input.client.model.default()
              const fallback = result.data
              return fallback ? { providerID: fallback.providerID, id: fallback.id, variant: input.variant } : undefined
            })
        : undefined
    if (input.variant && !selected) throw new Error("Cannot select a variant before selecting a model")
    if (selected) {
      await input.client.session.switchModel({ sessionID: input.sessionID, model: selected })
    }

    const prepared = await Promise.all(input.files.map(prepareFile))
    if (interrupted) return
    submitted = true
    completed = consume()
    admission = new AbortController()
    const response = await input.client.session
      .prompt(
        {
          sessionID: input.sessionID,
          id: messageID,
          text: [input.message, ...prepared.flatMap((file) => (file.text ? [file.text] : []))].join("\n\n"),
          files: prepared.flatMap((file) => (file.attachment ? [file.attachment] : [])),
          delivery: "steer",
        },
        { signal: admission.signal },
      )
      .catch(async (error) => {
        if (interrupted) {
          await input.client.session.interrupt({ sessionID: input.sessionID }).catch(() => {})
        }
        controller.abort()
        await completed?.catch(() => {})
        if (interrupted || emittedError) return undefined
        throw error
      })
    admission = undefined
    if (!response) return
    if (interrupted) await input.client.session.interrupt({ sessionID: input.sessionID }).catch(() => {})

    const [permissions, forms, globals] = await Promise.all([
      input.client.permission.list({ sessionID: input.sessionID }).catch(() => undefined),
      input.client.session.form.list({ sessionID: input.sessionID }).catch(() => undefined),
      input.attached
        ? Promise.resolve(undefined)
        : input.client.form
            .list({
              location: { directory: input.location.directory },
            })
            .catch(() => undefined),
    ])
    await Promise.all([
      ...(permissions ?? []).map(replyPermission),
      ...(forms ?? []).map(cancelForm),
      ...(globals && sameLocation(globals.location, input.location)
        ? globals.data.filter((form) => form.sessionID === GLOBAL_FORM_SESSION_ID).map(cancelForm)
        : []),
    ])
    if (input.compatibility === "v1") {
      await completed
      return
    }

    const waiting = input.client.session.wait({ sessionID: input.sessionID })
    await Promise.race([waiting, completed.then(() => waiting)])
    finalizing = true
    const projected = await reconcile()
    if (
      !projected.responded &&
      !interrupted &&
      !permissionRejected &&
      !formCancelled &&
      !emittedError &&
      !prePromotionError
    ) {
      await completed
    }
    if (!projected.found && !interrupted && !permissionRejected && !formCancelled && !emittedError) {
      const error = prePromotionError ?? { type: "unknown", message: "Prompt was not promoted" }
      emittedError = true
      process.exitCode = 1
      if (!emit("error", Date.now(), { error })) UI.error(error.message)
    }
  } finally {
    process.off("SIGINT", interrupt)
    controller.abort()
    if (input.compatibility === "v1") await stream.return?.(undefined).catch(() => {})
    else void stream.return?.(undefined).catch(() => {})
  }
}

function sameLocation(left: LocationRef | undefined, right: LocationRef) {
  return !!left && left.directory === right.directory
}

function formRequestOptions(location: LocationRef | undefined): [] | [{ headers: Record<string, string> }] {
  if (!location) return []
  return [
    {
      headers: {
        "x-opencode-directory": encodeURIComponent(location.directory),
      },
    },
  ]
}

function formAlreadySettled(error: unknown) {
  return !!error && typeof error === "object" && "_tag" in error && error._tag === "FormAlreadySettledError"
}

function partID(eventID: string) {
  return `prt_${eventID.replace(/^evt_/, "")}`
}

function toolKey(messageID: string, id: string) {
  return `${messageID}\u0000${id}`
}

function contentKey(messageID: string, ordinal: number) {
  return `${messageID}\u0000${ordinal}`
}

function projectedPartID(messageID: string, part: string) {
  return `prt_${messageID.replace(/^msg_/, "")}_${part}`
}

function fallbackTool(event: {
  id: string
  created: number
  data: { assistantMessageID: string; id: string }
}): ToolState {
  return {
    id: partID(event.id),
    timestamp: toMillis(event.created),
    assistantMessageID: event.data.assistantMessageID,
    tool: "tool",
    input: {},
    metadata: {},
    content: [],
  }
}

function toMillis(value: unknown) {
  if (typeof value === "number") return value
  if (typeof value === "string") return new Date(value).getTime()
  return Date.now()
}

async function prepareFile(file: File) {
  if (file.mime !== "text/plain") {
    const uri = file.url.startsWith("data:")
      ? file.url
      : `data:${file.mime};base64,${(await readFile(new URL(file.url))).toString("base64")}`
    return { attachment: { uri, name: file.filename } }
  }
  const content = file.url.startsWith("data:")
    ? Buffer.from(file.url.slice(file.url.indexOf(",") + 1), "base64").toString("utf8")
    : await readFile(new URL(file.url), "utf8")
  return { text: `<file name="${file.filename}">\n${content}\n</file>` }
}

import { Service, type Endpoint } from "@opencode/client/effect/service"
import { OpenCode, type SessionMessageAssistantTool } from "@opencode/client/promise"
import { FSUtil } from "@opencode/util/fs-util"
import { open } from "node:fs/promises"
import path from "node:path"
import { readStdin } from "../util/io"
import { ServerConnection } from "../services/server-connection"
import { parseSessionTargetModel, resolveSessionTarget } from "../session-target"
import { toolInlineInfo } from "@opencode/tui/mini/tool"
import { runNonInteractivePrompt } from "./noninteractive"
import { UI } from "./ui"
import { Env } from "../env"
import { errorMessage } from "../util/error"

export type RunCommandInput = {
  server: ServerConnection.Resolved
  message: string[]
  continue?: boolean
  session?: string
  fork?: boolean
  model?: string
  agent?: string
  format: "default" | "json"
  file: string[]
  title?: string
  thinking?: boolean
  auto?: boolean
}

type FilePart = {
  url: string
  filename: string
  mime: string
}

type Prepared = {
  directory?: string
  message: string
  files: FilePart[]
}

type ExecutionOptions = {
  root?: string
  directory?: string
  useServerDirectory?: boolean
  variant?: string
  attached?: boolean
  compatibility?: "v1"
}

class RunTargetError extends Error {
  constructor(
    message: string,
    readonly sessionID?: string,
  ) {
    super(message)
  }
}

const ATTACH_FILE_MAX_BYTES = 10 * 1024 * 1024

export function runNonInteractive(input: RunCommandInput) {
  return runNonInteractiveWithOptions(input, {})
}

/** @internal Used only by the V1 command boundary. */
export function runNonInteractiveWithOptions(input: RunCommandInput, options: ExecutionOptions) {
  return run(input, options).catch((error) => reportRunError(input, errorMessage(error)))
}

async function run(input: RunCommandInput, options: ExecutionOptions) {
  if (input.fork && !input.continue && !input.session) fail("--fork requires --continue or --session")
  const root = options.root ?? process.env.PWD ?? process.cwd()
  const local = localDirectory(root)
  const directory = options.useServerDirectory ? undefined : (options.directory ?? local)
  const message = mergeInput(formatMessage(input.message), process.stdin.isTTY ? undefined : await readStdin())
  if (!message?.trim()) fail("You must provide a message")
  const files = await Promise.all(input.file.map((file) => prepareFile(file, root, options)))
  const prepared = { directory, message, files }
  return execute(input, prepared, input.server.endpoint, options)
}

async function execute(input: RunCommandInput, prepared: Prepared, endpoint: Endpoint, options: ExecutionOptions) {
  const client = OpenCode.make({
    baseUrl: endpoint.url,
    headers: Service.headers(endpoint),
    // Bun's default five-minute deadline terminates the event stream used by long-running sessions.
    fetch: ((request: RequestInfo | URL, init?: RequestInit) =>
      fetch(request, { ...init, timeout: false } as BunFetchRequestInit)) as typeof fetch,
  })
  const explicit = parseRunModel(input.model)
  const target = await resolveSessionTarget({
    client,
    location: prepared.directory ? { directory: prepared.directory } : undefined,
    continue: input.continue,
    session: input.session,
    fork: input.fork,
    model: explicit
      ? { providerID: explicit.model.providerID, id: explicit.model.modelID, variant: explicit.variant }
      : undefined,
    agent: input.agent,
    environment: input.server.service ? Env.session() : undefined,
    prepare: async (next) => {
      const selected =
        next.model ??
        (options.variant
          ? await client.model
              .default({ location: { directory: next.location.directory } })
              .then((result) => result.data)
          : undefined)
      const model = selected
        ? {
            providerID: selected.providerID,
            id: selected.id,
            variant: options.variant ?? ("variant" in selected ? selected.variant : undefined),
          }
        : undefined
      if ((options.variant ?? explicit?.variant) && !model)
        throw new RunTargetError("Cannot select a variant before selecting a model", next.session?.id)
      return { model, agent: next.agent }
    },
  }).catch((error) => {
    if (!(error instanceof RunTargetError)) throw error
    reportRunError(input, error.message, error.sessionID)
    return undefined
  })
  if (!target) return
  const model = target.model ? { providerID: target.model.providerID, modelID: target.model.id } : undefined
  const variant = target.model?.variant
  if (!target.resume && input.title !== undefined) {
    await client.session.update({
      sessionID: target.session.id,
      title: input.title || prepared.message.slice(0, 50) + (prepared.message.length > 50 ? "..." : ""),
    })
  }

  await runNonInteractivePrompt({
    client,
    sessionID: target.session.id,
    location: target.location,
    message: prepared.message,
    files: prepared.files,
    agent: target.agent,
    model,
    variant,
    thinking: input.thinking ?? false,
    format: input.format,
    auto: input.auto ?? false,
    attached: options.attached ?? true,
    compatibility: options.compatibility,
    renderTool: (part) => renderTool(part, target.location.directory),
    renderToolError: (part) => renderToolError(part, target.location.directory),
  }).catch((error) => reportRunError(input, errorMessage(error), target.session.id))
}

export function mergeInput(message: string | undefined, piped: string | undefined) {
  if (!message) return piped || undefined
  if (!piped) return message
  return message + "\n" + piped
}

function formatMessage(message: string[]) {
  const value = message.map((part) => (part.includes(" ") ? `"${part.replace(/"/g, '\\"')}"` : part)).join(" ")
  return value || undefined
}

function localDirectory(root: string) {
  try {
    process.chdir(root)
    return process.cwd()
  } catch {
    fail(`Failed to change directory to ${root}`)
  }
}

export function parseRunModel(value?: string) {
  const ref = parseSessionTargetModel(value)
  if (!ref) return
  return {
    model: { providerID: ref.providerID, modelID: ref.id },
    variant: ref.variant,
  }
}

async function prepareFile(input: string, directory: string, options: ExecutionOptions): Promise<FilePart> {
  const file = path.resolve(directory, input)
  const handle = await open(file, "r").catch(() => fail(`File not found: ${input}`))
  try {
    const stat = await handle.stat()
    if (options.compatibility === "v1" && options.attached && stat.isDirectory())
      fail(`Cannot attach local directory without a shared filesystem: ${input}`)
    if (!stat.isFile() || stat.size > ATTACH_FILE_MAX_BYTES)
      fail(`Cannot attach a directory, special file, or file larger than 10 MiB: ${input}`)
    const content = Buffer.alloc(Number(stat.size))
    let offset = 0
    while (offset < content.length) {
      const read = await handle.read(content, offset, content.length - offset, offset)
      if (read.bytesRead === 0) break
      offset += read.bytesRead
    }
    const bytes = content.subarray(0, offset)
    const detected = FSUtil.mimeType(file)
    const text = bytes.toString("utf8")
    const mime =
      detected.startsWith("image/") || detected === "application/pdf"
        ? detected
        : !isBinaryContent(bytes) && Buffer.from(text, "utf8").equals(bytes)
          ? "text/plain"
          : detected
    return {
      url: `data:${mime};base64,${bytes.toString("base64")}`,
      filename: path.basename(file),
      mime,
    }
  } finally {
    await handle.close()
  }
}

function isBinaryContent(bytes: Uint8Array) {
  if (bytes.length === 0) return false
  if (bytes.includes(0)) return true
  return bytes.reduce((count, byte) => count + Number(byte < 9 || (byte > 13 && byte < 32)), 0) / bytes.length > 0.3
}

async function renderTool(part: SessionMessageAssistantTool, directory: string) {
  const info = toolInlineInfo(part, directory)
  if (info.mode === "block") {
    UI.empty()
    UI.println(UI.Style.TEXT_NORMAL + info.icon, UI.Style.TEXT_NORMAL + info.title)
    if (info.body?.trim()) UI.println(info.body)
    UI.empty()
    return
  }
  UI.println(
    UI.Style.TEXT_NORMAL + info.icon,
    UI.Style.TEXT_NORMAL + info.title,
    info.description ? UI.Style.TEXT_DIM + info.description + UI.Style.TEXT_NORMAL : "",
  )
}

async function renderToolError(part: SessionMessageAssistantTool, directory: string) {
  const info = toolInlineInfo(part, directory)
  UI.println(UI.Style.TEXT_NORMAL + "✗", UI.Style.TEXT_NORMAL + `${info.title} failed`)
}

/** @internal Used by the V1 command boundary before a Session exists. */
export function reportRunError(input: Pick<RunCommandInput, "format">, message: string, sessionID?: string) {
  process.exitCode = 1
  if (input.format === "json") {
    process.stdout.write(
      JSON.stringify({
        type: "error",
        timestamp: Date.now(),
        sessionID: sessionID ?? "",
        error: { type: "unknown", message },
      }) + "\n",
    )
    return
  }
  UI.error(message)
}

function fail(message: string): never {
  throw new Error(message)
}

import { EOL } from "node:os"

export const Style = {
  TEXT_DIM: "\x1b[90m",
  TEXT_NORMAL: "\x1b[0m",
  TEXT_WARNING_BOLD: "\x1b[93m\x1b[1m",
  TEXT_DANGER_BOLD: "\x1b[91m\x1b[1m",
}

export function println(...message: string[]) {
  process.stderr.write(message.join(" ") + EOL)
}

let blank = false

export function empty() {
  if (blank) return
  println(Style.TEXT_NORMAL)
  blank = true
}

export function error(message: string) {
  if (message.startsWith("Error: ")) message = message.slice("Error: ".length)
  println(Style.TEXT_DANGER_BOLD + "Error: " + Style.TEXT_NORMAL + message)
}

export * as UI from "./ui"

import type { Endpoint } from "@opencode/client/effect/service"
import { Effect } from "effect"
import path from "node:path"
import { Standalone } from "../services/standalone"
import { errorMessage } from "../util/error"
import { reportRunError, runNonInteractiveWithOptions, type RunCommandInput } from "./run"

export type V1RunCommandInput = {
  message: string[]
  continue?: boolean
  session?: string
  fork?: boolean
  model?: string
  agent?: string
  format: "default" | "json"
  file: string[]
  title?: string
  server?: string
  password?: string
  username?: string
  directory?: string
  variant?: string
  thinking?: boolean
  dangerouslySkipPermissions?: boolean
  standaloneCommand?: ReadonlyArray<string>
}

export function runV1Bridge(input: V1RunCommandInput) {
  const root = process.env.PWD ?? process.cwd()
  const attached = input.server !== undefined
  const local = !attached && input.directory ? path.resolve(root, input.directory) : root
  try {
    process.chdir(local)
  } catch {
    reportRunError(input, `Failed to change directory to ${local}`)
    return Promise.resolve()
  }

  return Effect.runPromise(
    Effect.scoped(
      Effect.gen(function* () {
        const endpoint = attached
          ? explicitEndpoint(input)
          : yield* Standalone.start({ command: input.standaloneCommand })
        yield* Effect.promise(() =>
          runNonInteractiveWithOptions(nativeInput(input, endpoint), {
            root: local,
            directory: attached ? input.directory : local,
            useServerDirectory: attached && input.directory === undefined,
            variant: input.variant,
            attached,
            compatibility: "v1",
          }),
        )
      }),
    ),
  ).catch((error) => reportRunError(input, errorMessage(error)))
}

function nativeInput(input: V1RunCommandInput, endpoint: Endpoint): RunCommandInput {
  return {
    server: { endpoint },
    message: input.message,
    continue: input.continue,
    session: input.session,
    fork: input.fork,
    model: input.model,
    agent: input.agent,
    format: input.format,
    file: input.file,
    title: input.title,
    thinking: input.thinking,
    auto: input.dangerouslySkipPermissions,
  }
}

function explicitEndpoint(input: V1RunCommandInput): Endpoint {
  const url = input.server
  if (!url) throw new Error("Missing V1 server URL")
  return {
    url,
    auth: input.password
      ? { type: "basic", username: input.username ?? "opencode", password: input.password }
      : undefined,
  }
}

export * as ServerProcess from "./server-process"

import { NodeServices } from "@effect/platform-node"
import { Service } from "@opencode/client/effect/service"
import { LayerNode } from "@opencode/util/effect/layer-node"
import { Global } from "@opencode/util/global"
import { OPENCODE_ARTIFACT, OPENCODE_CHANNEL, OPENCODE_VERSION } from "./version"
import { AppProcess } from "@opencode/util/process"
import { randomBytes, randomUUID } from "node:crypto"
import { Effect, Option, Redacted, Schema } from "effect"
import { PersistentPty } from "@opencode/schema/persistent-pty"
import { HttpServer } from "effect/http"
import { NetAddress } from "effect/net"
import { Env } from "./env"
import { ServiceConfig } from "./services/service-config"
import { RetainedImage } from "./services/retained-image"
import { ServiceRegistration } from "./services/service-registration"
import { RemoteTunnel } from "./services/remote-tunnel"
import { WebUi } from "./services/web-ui"
import { databasePath } from "./database-path"

export type Mode = "default" | "service" | "stdio"

export type Options = {
  readonly mode: Mode
  readonly hostname?: string
  readonly port?: number
  readonly cors?: readonly string[]
}

// The process effect lives until server shutdown; tracing it would parent every request to one process-lifetime trace.
export const run = Effect.fnUntraced(function* (options: Options) {
  return yield* processEffect(options).pipe(
    Effect.provide(
      LayerNode.compile(LayerNode.group([Global.node, AppProcess.node]), {
        replacements: [
          Global.node.replace(
            Global.layerWith(process.env.OPENCODE_CONFIG_DIR ? { config: process.env.OPENCODE_CONFIG_DIR } : {}),
          ),
        ],
      }),
    ),
    Effect.provide(NodeServices.layer),
  )
})

const processEffect = Effect.fnUntraced(function* (options: Options) {
  const inherited = process.env.OPENCODE_PTY_HANDOFF
  delete process.env.OPENCODE_PTY_HANDOFF
  const handoff =
    inherited === undefined
      ? undefined
      : yield* Schema.decodeUnknownEffect(Schema.fromJsonString(PersistentPty.Handoff))(inherited).pipe(
          Effect.catch(() =>
            Effect.logWarning("Ignoring invalid PTY restart handoff; persistent terminals will start fresh").pipe(
              Effect.as(undefined),
            ),
          ),
        )
  const global = yield* Global.Service
  if (options.mode === "service") yield* Effect.sync(() => process.chdir(global.home))
  return yield* Effect.scoped(
    Effect.gen(function* () {
      const foreground = options.mode === "default"
      const serviceOptions = options.mode === "service" ? yield* ServiceConfig.options() : undefined
      const config = options.mode === "service" ? yield* ServiceConfig.read() : {}
      const hostname = options.hostname ?? config.hostname ?? "127.0.0.1"
      const port = options.port ?? config.port ?? (options.mode === "service" ? ServiceConfig.defaultPort() : undefined)
      const findIncumbent =
        serviceOptions !== undefined && port !== undefined
          ? Service.incumbent({ ...serviceOptions, url: serviceURL(hostname, port) })
          : undefined
      if (findIncumbent !== undefined && (yield* findIncumbent) !== undefined) return
      // Desktop can launch the service directly without injecting its saved environment.
      Object.assign(process.env, config.env)
      // Keep a package-manager or curl install replaceable while the service runs; Desktop updates its own copy.
      if (options.mode === "service" && process.platform === "win32" && RetainedImage.installed(global.home))
        yield* RetainedImage.retain(global.cache, "service")
      const { start } = yield* Effect.promise(() => import("@opencode/server/process"))
      const environmentPassword = yield* Env.password
      // Keep the lease credential out of the environment inherited by tools.
      if (options.mode === "stdio") {
        delete process.env.OPENCODE_PASSWORD
        delete process.env.OPENCODE_SERVER_PASSWORD
      }
      const password =
        options.mode === "service"
          ? config.password || randomBytes(32).toString("base64url")
          : environmentPassword
            ? Redacted.value(environmentPassword)
            : randomBytes(32).toString("base64url")
      if (!password) return yield* Effect.fail(new Error("Missing server password"))
      const instanceID = randomUUID()
      const transform = yield* WebUi.handler()
      const remote = { urls: [] as ReadonlyArray<string> }
      const launch = start(
        {
          app: {
            name: process.env.OPENCODE_CLIENT ?? OPENCODE_ARTIFACT,
            version: OPENCODE_VERSION,
            channel: OPENCODE_CHANNEL,
          },
          hostname,
          port,
          cors: options.cors ?? config.cors,
          password,
          pty: { handoff },
          simulation: truthy(process.env.OPENCODE_SIMULATE),
          database: {
            path: databasePath(global.data),
          },
          models: {
            url: process.env.OPENCODE_MODELS_URL,
            file: process.env.OPENCODE_MODELS_PATH,
            fetch: !truthy(process.env.OPENCODE_DISABLE_MODELS_FETCH),
          },
          config: {
            directory: process.env.OPENCODE_CONFIG_DIR,
            project: !truthy(
              process.env.OPENCODE_CONFIG_PROJECT_DISABLE ?? process.env.OPENCODE_DISABLE_PROJECT_CONFIG,
            ),
            // .claude is only read for skills, so both flags gate the same roots.
            claude: !(
              truthy(process.env.OPENCODE_DISABLE_CLAUDE_CODE) ||
              truthy(process.env.OPENCODE_DISABLE_CLAUDE_CODE_SKILLS)
            ),
            file: process.env.OPENCODE_CONFIG,
            content: process.env.OPENCODE_CONFIG_CONTENT,
          },
          windows: {
            gitbash: process.env.OPENCODE_GIT_BASH_PATH,
          },
          fs: {
            filewatcher: !truthy(process.env.OPENCODE_FILEWATCHER_DISABLE ?? process.env.OPENCODE_DISABLE_FILEWATCHER),
            fff:
              process.env.OPENCODE_DISABLE_FFF === undefined
                ? process.platform !== "win32"
                : !truthy(process.env.OPENCODE_DISABLE_FFF),
          },
        },
        serviceOptions === undefined
          ? undefined
          : {
              onListen: (address, shutdown) =>
                Effect.gen(function* () {
                  if (!config.password) yield* ServiceConfig.password(password)
                  return yield* ServiceRegistration.register({
                    address,
                    password,
                    id: instanceID,
                    file: serviceOptions.file,
                    shutdown,
                  })
                }),
            },
        transform,
        () => remote.urls,
      )
      const server = yield* launch.pipe(
        Effect.catch((error) => {
          if (findIncumbent === undefined || !addressInUse(error)) return Effect.fail(error)
          return Effect.gen(function* () {
            const deadline = Date.now() + 15_000
            while (Date.now() < deadline) {
              const found = yield* findIncumbent.pipe(Effect.timeoutOption(deadline - Date.now()))
              if (Option.isSome(found) && found.value !== undefined) return
              yield* Effect.sleep("100 millis")
              if (Date.now() >= deadline) break
              // Failed binds close their scope; a successful bind may take longer than this window to boot.
              const server = yield* launch.pipe(Effect.catchIf(addressInUse, () => Effect.void))
              if (server !== undefined) return server
            }
            return yield* Effect.fail(
              new Error(
                `Managed service port ${port} on ${hostname} is already in use by another process. ` +
                  "Configure another port with `opencode service set port <port>` and start the service again.",
                { cause: error },
              ),
            )
          })
        }),
      )
      if (server === undefined) return
      if (serviceOptions !== undefined && config.remote !== undefined && NetAddress.isInetAddress(server.address)) {
        const bound = NetAddress.formatIp(server.address.address)
        // A wildcard bind also listens on loopback, which is all the tunnel needs to reach.
        const target =
          bound === "0.0.0.0" || bound === "::"
            ? `127.0.0.1:${server.address.port}`
            : NetAddress.formatInet(server.address)
        yield* Effect.forkScoped(
          RemoteTunnel.run({
            route: config.remote.route,
            target,
            onURL: (url) => {
              remote.urls = url === undefined ? [] : [url]
            },
          }),
        )
      }
      const url = HttpServer.formatAddress(server.address)
      console.log(options.mode === "stdio" ? JSON.stringify({ url }) : `server listening on ${url}`)
      if (foreground && !environmentPassword) console.log(`server password ${password}`)
      return yield* options.mode === "service"
        ? server.shutdown
        : options.mode === "stdio"
          ? waitForStdinClose()
          : Effect.never
    }).pipe(Effect.annotateLogs({ role: "server" })),
  )
})

function serviceURL(hostname: string, port: number) {
  return `http://${hostname.includes(":") ? `[${hostname}]` : hostname}:${port}`
}

function truthy(value?: string) {
  return value === "1" || value?.toLowerCase() === "true"
}

function addressInUse(error: unknown): boolean {
  if (typeof error !== "object" || error === null) return false
  if ("code" in error && error.code === "EADDRINUSE") return true
  return "cause" in error && addressInUse(error.cause)
}

function waitForStdinClose() {
  return Effect.callback<void>((resume) => {
    const close = () => resume(Effect.void)
    process.stdin.once("end", close)
    process.stdin.once("close", close)
    process.stdin.resume()
    if (process.stdin.readableEnded || process.stdin.destroyed) close()
    return Effect.sync(() => {
      process.stdin.off("end", close)
      process.stdin.off("close", close)
      process.stdin.pause()
    })
  })
}

export * as RemoteTunnel from "./remote-tunnel"

import type { OpenTunnelError } from "@opentunnel/client/effect"
import { Cause, Effect, Schedule } from "effect"
import { EOL } from "os"

// OpenTunnel keeps one tunnel per device in its default profile, shared by the opentunnel CLI and every app
// using the SDK; each claims its own routes. The service claims a subdomain (its route) rather than the tunnel
// hostname, which the CLI may route. Tunnel hostnames appear in public certificate logs but the certificate
// covers subdomains with a wildcard, so a random route keeps the service's address unguessable.

// Holds the route for the life of the service. The SDK reconnects through network failures itself, so only
// setup failures reach the retry here; a rejected token or failed certificate stops it for good.
export const run = Effect.fnUntraced(function* (input: {
  readonly route: string
  readonly target: string
  readonly onURL: (url: string | undefined) => void
}) {
  const { OpenTunnelClient, OpenTunnelAttachError } = yield* Effect.promise(() => import("@opentunnel/client/effect"))
  const fatal = (error: OpenTunnelError) =>
    error._tag === "OpenTunnelClientError" &&
    (error.cause instanceof OpenTunnelAttachError || error.message.startsWith("Certificate issuance failed"))
  yield* Effect.gen(function* () {
    const client = yield* OpenTunnelClient
    const connection = yield* client.tunnel.connect({ routes: { [input.route]: input.target } })
    input.onURL(`https://${input.route}.${connection.tunnel.hostname}`)
    yield* connection.closed
  }).pipe(
    Effect.scoped,
    Effect.ensuring(Effect.sync(() => input.onURL(undefined))),
    Effect.tapError((error) =>
      fatal(error) ? Effect.void : Effect.logWarning("remote access tunnel unavailable; retrying", { cause: error }),
    ),
    Effect.retry({
      while: (error) => !fatal(error),
      schedule: Schedule.min([Schedule.exponential("1 second"), Schedule.spaced("30 seconds")]),
    }),
    Effect.provide(OpenTunnelClient.layer()),
    Effect.catchCause((cause) =>
      Cause.hasInterruptsOnly(cause)
        ? Effect.failCause(cause)
        : Effect.logError("remote access tunnel stopped; run `opencode service set remote true` to retry", { cause }),
    ),
  )
})

// A device without a tunnel creates its shared one here, in the foreground, because issuing the certificate
// takes a while; the service then only attaches its route on start. An interrupted issuance resumes next time.
export const ensure = Effect.fnUntraced(function* () {
  const { OpenTunnelClient } = yield* Effect.promise(() => import("@opentunnel/client/effect"))
  return yield* Effect.gen(function* () {
    const client = yield* OpenTunnelClient
    if ((yield* client.tunnel.get()) === undefined)
      process.stderr.write("Setting up remote access; this can take a minute..." + EOL)
    return (yield* client.tunnel.ensure()).hostname
  }).pipe(
    Effect.provide(OpenTunnelClient.layer()),
    Effect.timeoutOrElse({
      duration: "5 minutes",
      orElse: () => Effect.fail(new Error("Timed out creating the remote access tunnel; run the command again to resume")),
    }),
  )
})

// The tunnel hostname is persisted once the certificate is ready, so this is undefined until then.
export const hostname = Effect.fnUntraced(function* (route: string) {
  const { OpenTunnelStorage } = yield* Effect.promise(() => import("@opentunnel/client/effect"))
  const identity = yield* OpenTunnelStorage.xdg().load("default")
  return identity === undefined ? undefined : `${route}.${identity.hostname}`
})

export * as RetainedImage from "./retained-image"

import { Effect, FileSystem } from "effect"
import { randomBytes } from "node:crypto"
import path from "node:path"

// Windows refuses to delete the last hard link of a running executable, and bun 1.4 spins
// forever when its package replacement meets one. Any other link to the image can be removed,
// so a process that must survive an installer keeps a second link to its own image while it
// runs. Windows reuses process IDs quickly, so names carry a random suffix and only links of
// processes that no longer exist are swept.
const pattern = /^opencode-(?:service|upgrade)-(\d+)-[0-9a-f]+\.exe$/

/** Hold a second link to the running image in `directory` for the lifetime of the scope. */
export const retain = Effect.fnUntraced(function* (directory: string, role: "service" | "upgrade") {
  const fs = yield* FileSystem.FileSystem
  return yield* Effect.acquireRelease(
    Effect.gen(function* () {
      yield* fs.makeDirectory(directory, { recursive: true }).pipe(Effect.ignore)
      const names = yield* fs.readDirectory(directory).pipe(Effect.orElseSucceed((): string[] => []))
      yield* Effect.forEach(names, (name) =>
        Effect.gen(function* () {
          const pid = Number(pattern.exec(name)?.[1])
          if (!pid || (yield* alive(pid))) return
          yield* fs.remove(path.join(directory, name)).pipe(Effect.ignore)
        }),
      )
      const target = path.join(directory, `opencode-${role}-${process.pid}-${randomBytes(4).toString("hex")}.exe`)
      const executable = yield* fs.realPath(process.execPath).pipe(Effect.orElseSucceed(() => process.execPath))
      return yield* fs.link(executable, target).pipe(
        Effect.as(target),
        Effect.tapError((cause) => Effect.logWarning("could not link the running binary", { cause })),
        Effect.orElseSucceed(() => undefined),
      )
    }),
    // The last link of a still-running image refuses deletion; a later sweep removes it.
    (target) => (target === undefined ? Effect.void : fs.remove(target).pipe(Effect.ignore)),
  )
})

/** Move retained links out of `directory` so it can be removed; renaming a running image is allowed. */
export const relocate = Effect.fnUntraced(function* (directory: string, destination: string) {
  const fs = yield* FileSystem.FileSystem
  const names = yield* fs.readDirectory(directory).pipe(Effect.orElseSucceed((): string[] => []))
  const links = names.filter((name) => pattern.test(name))
  if (links.length === 0) return
  yield* fs.makeDirectory(destination, { recursive: true }).pipe(Effect.ignore)
  yield* Effect.forEach(links, (name) =>
    fs.rename(path.join(directory, name), path.join(destination, name)).pipe(Effect.ignore),
  )
})

/**
 * Whether the running binary was installed by a package manager or the curl installer, the installs
 * whose upgrades replace it in place. The updater decides the same question from the install location.
 */
export function installed(home: string) {
  const runtime = path.basename(process.execPath, path.extname(process.execPath)).toLowerCase()
  if (runtime === "bun" || runtime === "node" || runtime === "nodejs") return false
  const executable = path.resolve(process.execPath)
  return (
    executable.split(path.sep).includes("node_modules") ||
    /[\\/]winget[\\/]packages[\\/]/i.test(executable) ||
    executable === path.resolve(home, ".opencode", "bin", "opencode.exe")
  )
}

// Only ESRCH means the process is gone; EPERM is a live process this user cannot open.
const alive = (pid: number) =>
  Effect.try({ try: () => process.kill(pid, 0), catch: (cause) => cause }).pipe(
    Effect.as(true),
    Effect.catch((cause) => Effect.succeed(!(cause instanceof Error && "code" in cause && cause.code === "ESRCH"))),
  )

import { Service, type Endpoint, type EnsureOptions } from "@opencode/client/effect/service"
import { ClientError, isUnauthorizedError, OpenCode } from "@opencode/client/promise"
import { OPENCODE_VERSION } from "../version"
import { Effect, Redacted } from "effect"
import { Env } from "../env"
import { ServiceConfig } from "./service-config"
import { Standalone } from "./standalone"

export type Args = {
  readonly server?: string
  readonly standalone?: boolean
  readonly mismatch?: "replace" | "ignore" | "error"
  readonly onStart?: EnsureOptions["onStart"]
}

export type Resolved = {
  readonly endpoint: Endpoint
  readonly service?: ReturnType<typeof managedService>
}

export const resolve = Effect.fn("cli.server-connection.resolve")(function* (args: Args = {}) {
  if (args.server !== undefined && args.standalone)
    return yield* Effect.fail(new Error("--server and --standalone cannot be combined"))
  if (args.server !== undefined) {
    const password = yield* Env.password
    const endpoint = {
      url: args.server,
      auth: password ? { type: "basic" as const, username: "opencode", password: Redacted.value(password) } : undefined,
    } satisfies Endpoint
    const client = OpenCode.make({ baseUrl: endpoint.url, headers: Service.headers(endpoint) })
    const health = yield* Effect.tryPromise({
      try: () => client.server.info({ signal: AbortSignal.timeout(5_000) }),
      catch: (cause) => connectError(endpoint, cause),
    })
    if (health.version !== OPENCODE_VERSION)
      process.stderr.write(
        `Warning: Server at ${endpoint.url} has version ${health.version}; this client is ${OPENCODE_VERSION}. Continuing anyway.\n`,
      )
    return { endpoint } satisfies Resolved
  }
  if (args.standalone || (yield* ServiceConfig.read()).disabled === true) {
    return { endpoint: yield* Standalone.start() } satisfies Resolved
  }

  const mismatch = args.mismatch ?? "ignore"
  const options = yield* ServiceConfig.options({ checkVersion: mismatch !== "ignore" })
  return {
    endpoint: yield* resolveManaged({ ...options, onStart: args.onStart }, mismatch),
    service: managedService(options),
  } satisfies Resolved
})

function managedService(options: EnsureOptions) {
  const reconnectOptions = { ...options, version: undefined }
  return {
    reconnect: () => Service.ensure(reconnectOptions),
    restart: () =>
      Effect.gen(function* () {
        yield* Service.stop({ file: options.file, pty: "handoff" })
        yield* Service.ensure(reconnectOptions)
      }),
  }
}

export const shutdownPersistentPty = Effect.fn("cli.server-connection.shutdown-persistent-pty")(function* (
  options: EnsureOptions,
) {
  const endpoint = yield* Service.discover({ ...options, version: undefined })
  if (!endpoint) return
  const client = OpenCode.make({ baseUrl: endpoint.url, headers: Service.headers(endpoint) })
  yield* Effect.tryPromise(() => client.experimental.persistentPty.shutdown())
})

const resolveManaged = Effect.fnUntraced(function* (options: EnsureOptions, mismatch: NonNullable<Args["mismatch"]>) {
  if (mismatch === "replace") return yield* Service.ensure(options)
  if (mismatch === "ignore") return yield* Service.ensure({ ...options, version: undefined })

  const compatible = yield* Service.discover(options)
  if (compatible !== undefined) return compatible
  const existing = yield* Service.discover({ ...options, version: undefined })
  if (existing !== undefined)
    return yield* Effect.fail(new Error("Background server version does not match this client"))
  return yield* Service.ensure(options)
})

function connectError(endpoint: Endpoint, cause: unknown) {
  if (isUnauthorizedError(cause)) {
    return new Error(
      endpoint.auth === undefined
        ? `Server at ${endpoint.url} requires a password; set OPENCODE_PASSWORD`
        : `Server at ${endpoint.url} rejected the password`,
      { cause },
    )
  }
  if (cause instanceof ClientError && cause.reason === "Transport")
    return new Error(`Could not reach server at ${endpoint.url}`, { cause })
  return new Error(`Server at ${endpoint.url} did not provide a compatible V2 health response`, { cause })
}

export * as ServerConnection from "./server-connection"

import { Global } from "@opencode/util/global"
import { OPENCODE_CHANNEL, OPENCODE_VERSION } from "../version"
import { Hash } from "@opencode/util/hash"
import { Service } from "@opencode/client/effect/service"
import { Effect, FileSystem, Option, Schema } from "effect"
import { randomBytes } from "crypto"
import path from "path"
import { selfCommand } from "../util/process"
import { RemoteTunnel } from "./remote-tunnel"

// The CLI's service configuration file, plus the Service.EnsureOptions binding that
// points the client package's service operations at this CLI: which
// registration file (by channel), which version, and how to spawn opencode.

export const Info = Schema.Struct({
  disabled: Schema.optional(Schema.Boolean),
  // Present when remote access is on. The route is generated, never user-set: the secret subdomain the service is
  // served on.
  remote: Schema.optional(Schema.Struct({ route: Schema.String })),
  // Set once the user has accepted exposing the service to the internet, or had remote access on before, so turning
  // remote access off and on again does not ask a second time.
  remoteAccepted: Schema.optional(Schema.Literal(true)),
  hostname: Schema.optional(Schema.String),
  port: Schema.optional(Schema.Int.check(Schema.isGreaterThanOrEqualTo(1), Schema.isLessThanOrEqualTo(65_535))),
  password: Schema.optional(Schema.String),
  cors: Schema.optional(Schema.Array(Schema.String)),
  env: Schema.optional(Schema.Record(Schema.String, Schema.String)),
})
export type Info = typeof Info.Type

const keys = ["disabled", "remote", "hostname", "port", "password", "cors", "env"] as const
type Key = (typeof keys)[number]

const decodeInfo = Schema.decodeUnknownEffect(Schema.fromJsonString(Info))
// Earlier builds stored remote access as a boolean.
const decodeLegacy = Schema.decodeUnknownOption(
  Schema.fromJsonString(Schema.Struct({ ...Info.fields, remote: Schema.Boolean })),
)
const decodeRegistration = Schema.decodeUnknownEffect(Schema.fromJsonString(Service.Info))

export function filename(channel = OPENCODE_CHANNEL) {
  if (channel === "latest" || channel === "dev" || channel === "beta" || channel === "next") return "service.json"
  return `service-${channel.replace(/[^a-zA-Z0-9._-]/g, "-")}.json`
}

export function defaultPort(channel = OPENCODE_CHANNEL, platform = process.platform) {
  const port = channelPort(channel)
  // Windows hands out 0xC000-0xFFFF for outgoing connections, and Hyper-V and WinNAT reserve blocks of that range at
  // boot, so a port there can fail as in use while nothing listens on it. Moving into the 0xB000 block keeps the low
  // 12 bits: 0xC0DE becomes 0xB0DE, which is 0xC0DE - 4096, a nod to the v1 port.
  if (platform === "win32" && port >= 0xc000) return 0xb000 | (port & 0xfff)
  return port
}

function channelPort(channel: string) {
  if (channel === "latest" || channel === "dev" || channel === "beta" || channel === "next") return 0xc0de
  if (channel === "local") return 0xc0df
  return 10_000 + (Number.parseInt(Hash.fast(channel).slice(0, 8), 16) % 50_000)
}

export function legacyFilename(channel = OPENCODE_CHANNEL) {
  if (channel === "latest" || channel === "local") return
  return `service-${Hash.fast(channel)}.json`
}

export function versionBelongsToChannel(
  version: string | undefined,
  channel = OPENCODE_CHANNEL,
  installedVersion = OPENCODE_VERSION,
) {
  if (version === undefined) return false
  if (version === installedVersion) return true
  const prefix = `0.0.0-${channel}-`
  if (!version.startsWith(prefix)) return false
  return /^\d+(?:\.\d+)?$/.test(version.slice(prefix.length))
}

export const migrateRegistration = Effect.fnUntraced(function* (
  legacy: string,
  file: string,
  channel = OPENCODE_CHANNEL,
  installedVersion = OPENCODE_VERSION,
) {
  const fs = yield* FileSystem.FileSystem
  const text = yield* fs.readFileString(legacy).pipe(Effect.option)
  if (Option.isNone(text)) return
  const registration = yield* decodeRegistration(text.value).pipe(Effect.option)
  if (Option.isNone(registration)) return
  if (!versionBelongsToChannel(registration.value.version, channel, installedVersion)) return
  yield* fs.writeFileString(file, text.value, { flag: "wx", mode: 0o600 }).pipe(Effect.ignore)
})

export const migrateConfig = Effect.fnUntraced(function* (legacy: string, file: string) {
  const fs = yield* FileSystem.FileSystem
  const text = yield* fs.readFileString(legacy).pipe(Effect.option)
  if (Option.isNone(text)) return
  if (Option.isNone(yield* decodeInfo(text.value).pipe(Effect.option))) return
  yield* fs.writeFileString(file, text.value, { flag: "wx", mode: 0o600 }).pipe(Effect.ignore)
})

function configKey(key: string): Key {
  if (
    key === "disabled" ||
    key === "remote" ||
    key === "hostname" ||
    key === "port" ||
    key === "password" ||
    key === "cors" ||
    key === "env"
  )
    return key
  throw new Error(`Unknown service config key: ${key}`)
}

const paths = Effect.gen(function* () {
  const fs = yield* FileSystem.FileSystem
  const global = yield* Global.Service
  const name = filename()
  const legacy = legacyFilename()
  const file = path.join(global.state, name)
  return {
    fs,
    file,
    legacyConfigFile: legacy ? path.join(global.config, legacy) : undefined,
    legacyRegistrationFiles: [
      ...(legacy ? [path.join(global.state, legacy)] : []),
      ...(name !== "service.json" && OPENCODE_CHANNEL !== "local" ? [path.join(global.state, "service.json")] : []),
    ],
    configFile: path.join(global.config, name),
  }
})

export const options = Effect.fnUntraced(function* (input: { readonly checkVersion?: boolean } = {}) {
  const { file, legacyRegistrationFiles } = yield* paths
  yield* Effect.forEach(legacyRegistrationFiles, (legacy) => migrateRegistration(legacy, file))
  return {
    file,
    version: input.checkVersion ? OPENCODE_VERSION : undefined,
    env: (yield* read()).env,
    command: [
      ...selfCommand(),
      "serve",
      "--service",
    ],
  }
})

export const read = Effect.fn("cli.service-config.read")(function* () {
  const { fs, configFile, legacyConfigFile } = yield* paths
  if (legacyConfigFile) yield* migrateConfig(legacyConfigFile, configFile)
  const text = yield* fs.readFileString(configFile).pipe(Effect.option)
  if (Option.isNone(text)) return {} as Info
  const info = yield* decodeInfo(text.value).pipe(Effect.option)
  if (Option.isSome(info)) return info.value
  const legacy = decodeLegacy(text.value)
  if (Option.isNone(legacy)) return {} as Info
  // Repair the file in place so every reader sees the same route.
  const { remote: enabled, ...rest } = legacy.value
  const repaired: Info = enabled ? { ...rest, remote: { route: route() } } : rest
  yield* write(repaired)
  return repaired
})

// 64 random bits as 16 hex characters, a valid DNS label.
function route() {
  return randomBytes(8).toString("hex")
}

const write = Effect.fn("cli.service-config.write")(function* (value: Info) {
  const { fs, configFile } = yield* paths
  const temp = configFile + ".tmp"
  yield* fs.makeDirectory(path.dirname(configFile), { recursive: true })
  yield* fs.writeFileString(temp, JSON.stringify(value, null, 2) + "\n", { mode: 0o600 })
  yield* fs.rename(temp, configFile)
})

export const password = Effect.fn("cli.service-config.password")(function* (value?: string) {
  const existing = yield* read()
  if (value === undefined && existing.password) return existing.password
  const next = value ?? randomBytes(32).toString("base64url")

  // Keep one private credential across server restarts so discovered clients
  // can reconnect without exposing a password flag or environment variable.
  yield* write({ ...existing, password: next })
  return next
})

export const acceptRemote = Effect.fn("cli.service-config.accept-remote")(function* () {
  yield* write({ ...(yield* read()), remoteAccepted: true })
})

// Disabling forgets the address, so enabling again issues a new unguessable one. Having had it on counts as
// accepting remote access.
const disableRemote = Effect.fnUntraced(function* () {
  const { remote, ...next } = yield* read()
  yield* write(remote === undefined ? next : { ...next, remoteAccepted: true })
})

// Turns remote access on and returns its route, created once and kept so the remote URL survives restarts.
export const remote = Effect.fn("cli.service-config.remote")(function* () {
  const existing = yield* read()
  if (existing.remote) return existing.remote.route
  const next = route()
  yield* write({ ...existing, remote: { route: next } })
  return next
})

export const get = Effect.fn("cli.service-config.get")(function* (key?: string, name?: string) {
  if (key === undefined) {
    const { password: _password, ...safe } = yield* read()
    // The route is as sensitive as the password: it is the unguessable half of the remote address.
    return JSON.stringify(safe.remote === undefined ? safe : { ...safe, remote: {} }, null, 2)
  }
  const selected = configKey(key)
  if (selected !== "env" && name !== undefined) throw new Error(`Usage: opencode service get ${selected}`)
  switch (selected) {
    case "disabled": {
      return String((yield* read()).disabled ?? false)
    }
    case "remote": {
      return String((yield* read()).remote !== undefined)
    }
    case "hostname": {
      return (yield* read()).hostname ?? ""
    }
    case "port": {
      const port = (yield* read()).port
      return port === undefined ? "" : String(port)
    }
    case "password": {
      return yield* password()
    }
    case "cors": {
      return JSON.stringify((yield* read()).cors ?? [], null, 2)
    }
    case "env": {
      const env = (yield* read()).env ?? {}
      return name === undefined ? JSON.stringify(env, null, 2) : (env[name] ?? "")
    }
  }
  throw new Error(`Unknown service config key: ${key}`)
})

export const set = Effect.fn("cli.service-config.set")(function* (key: string, value: string, nestedValue?: string) {
  const selected = configKey(key)
  if (selected !== "env" && nestedValue !== undefined)
    throw new Error(`Usage: opencode service set ${selected} <value>`)
  switch (selected) {
    case "disabled": {
      if (value !== "true" && value !== "false") throw new Error("Disabled must be true or false")
      if (value === "true") yield* Service.stop(yield* options())
      yield* write({ ...(yield* read()), disabled: value === "true" })
      return
    }
    case "remote": {
      if (value !== "true" && value !== "false") throw new Error("Remote must be true or false")
      // A tunnel that cannot be created leaves remote access off instead of a service that keeps retrying.
      if (value === "true") yield* RemoteTunnel.ensure()
      yield* Service.stop(yield* options())
      if (value === "true") {
        yield* remote()
        return
      }
      yield* disableRemote()
      return
    }
    case "hostname": {
      yield* Service.stop(yield* options())
      yield* write({ ...(yield* read()), hostname: value })
      return
    }
    case "port": {
      const port = Number(value)
      if (!Number.isInteger(port) || port < 1 || port > 65_535) throw new Error("Port must be between 1 and 65535")
      yield* Service.stop(yield* options())
      yield* write({ ...(yield* read()), port })
      return
    }
    case "password": {
      yield* Service.stop(yield* options())
      yield* password(value)
      return
    }
    case "env": {
      if (nestedValue === undefined) throw new Error("Usage: opencode service set env <key> <value>")
      yield* Service.stop(yield* options())
      const existing = yield* read()
      yield* write({ ...existing, env: { ...existing.env, [value]: nestedValue } })
      return
    }
    case "cors": {
      const cors = value.split(",").map((origin) => origin.trim())
      if (
        cors.some((origin) => {
          const url = URL.parse(origin)
          return !url || (url.protocol !== "http:" && url.protocol !== "https:") || url.origin !== origin
        })
      )
        throw new Error("CORS must be a comma-separated list of HTTP(S) origins without paths or trailing slashes")
      yield* Service.stop(yield* options())
      yield* write({ ...(yield* read()), cors })
      return
    }
  }
})

export const unset = Effect.fn("cli.service-config.unset")(function* (key: string, name?: string) {
  const selected = configKey(key)
  if (selected !== "env" && name !== undefined) throw new Error(`Usage: opencode service unset ${selected}`)
  switch (selected) {
    case "disabled": {
      const { disabled: _disabled, ...next } = yield* read()
      yield* write(next)
      return
    }
    case "remote": {
      yield* Service.stop(yield* options())
      yield* disableRemote()
      return
    }
    case "hostname": {
      yield* Service.stop(yield* options())
      const { hostname: _hostname, ...next } = yield* read()
      yield* write(next)
      return
    }
    case "port": {
      yield* Service.stop(yield* options())
      const { port: _port, ...next } = yield* read()
      yield* write(next)
      return
    }
    case "password": {
      yield* Service.stop(yield* options())
      const { password: _password, ...next } = yield* read()
      yield* write(next)
      return
    }
    case "env": {
      if (name === undefined) throw new Error("Usage: opencode service unset env <key>")
      yield* Service.stop(yield* options())
      const existing = yield* read()
      const { [name]: _removed, ...env } = existing.env ?? {}
      const { env: _existingEnv, ...rest } = existing
      yield* write(Object.keys(env).length === 0 ? rest : { ...rest, env })
      return
    }
    case "cors": {
      yield* Service.stop(yield* options())
      const { cors: _cors, ...next } = yield* read()
      yield* write(next)
      return
    }
  }
})

export * as ServiceConfig from "./service-config"

import { CrossSpawnSpawner } from "@opencode/util/cross-spawn-spawner"
import { LayerNode } from "@opencode/util/effect/layer-node"
import { Deferred, Effect, Schema, Stream } from "effect"
import { ChildProcess, ChildProcessSpawner } from "effect/process"
import { randomBytes } from "node:crypto"
import { selfCommand } from "../util/process"

const Ready = Schema.Struct({ url: Schema.String })
const decodeReady = Schema.decodeUnknownPromise(Schema.fromJsonString(Ready))

type Options = {
  readonly command?: ReadonlyArray<string>
}

const startupDirectory = process.cwd()

function command(password: string, options: Options) {
  const [executable, ...args] = options.command ?? [...selfCommand(), "serve"]
  if (!executable) throw new Error("Failed to resolve standalone server command")
  return ChildProcess.make(executable, [...args, "--stdio", "--port", "0"], {
    cwd: startupDirectory,
    // Explicit entry wins over anything inherited, so a user-exported
    // OPENCODE_PASSWORD cannot shadow the child's lease credential.
    env: { OPENCODE_PASSWORD: password },
    extendEnv: true,
    // The server treats EOF on this pipe as the end of its ownership lease.
    // The OS closes it even when the TUI is killed before Effect finalizers run.
    stdin: "pipe",
    stderr: process.env.OPENCODE_PRINT_LOGS === "1" ? "inherit" : "ignore",
    killSignal: "SIGTERM",
    forceKillAfter: "3 seconds",
  })
}

const makeEndpoint = Effect.fn("cli.standalone.endpoint")(
  function* (options: Options) {
    const password = randomBytes(32).toString("base64url")
    const spawner = yield* ChildProcessSpawner.ChildProcessSpawner
    const proc = yield* spawner.spawn(command(password, options))
    const readyLine = yield* Deferred.make<string, Error>()
    // Keep draining stdout after readiness so later server writes cannot hit EPIPE.
    yield* proc.stdout.pipe(
      Stream.decodeText(),
      Stream.splitLines,
      Stream.runForEach((line) => Deferred.succeed(readyLine, line)),
      Effect.ensuring(Deferred.fail(readyLine, new Error("Standalone server exited before reporting readiness"))),
      Effect.forkScoped,
    )
    const output = yield* Deferred.await(readyLine)
    const ready = yield* Effect.tryPromise(() => decodeReady(output))
    return {
      url: ready.url,
      auth: { type: "basic" as const, username: "opencode", password },
      pid: proc.pid,
      exited: proc.exitCode,
    }
  },
  Effect.provide(LayerNode.compile(CrossSpawnSpawner.node)),
)

export function start(options: Options = {}) {
  return makeEndpoint(options)
}

