import type { LocationGetOutput, ModelRef, OpenCodeClient, SessionInfo } from "@opencode/client/promise"
import { Model } from "@opencode/schema/model"
import { errorMessage } from "./util/error"

const SESSION_PAGE_LIMIT = 50

export type SessionTarget = {
  session: SessionInfo
  location: LocationGetOutput
  model: ModelRef | undefined
  agent: string | undefined
  resume: boolean
}

export type SessionTargetPreparation = (input: {
  client: OpenCodeClient
  location: LocationGetOutput
  session: SessionInfo | undefined
  model: ModelRef | undefined
  agent: string | undefined
  signal?: AbortSignal
}) => Promise<{ model: ModelRef | undefined; agent: string | undefined }>

export class SessionTargetMutationError extends Error {
  override readonly name = "SessionTargetMutationError"

  constructor(cause: unknown) {
    super(errorMessage(cause), { cause })
  }
}

export async function resolveSessionTarget(input: {
  client: OpenCodeClient
  location?: { directory?: string; workspace?: string }
  continue?: boolean
  session?: string
  fork?: boolean
  model?: ModelRef
  agent?: string
  environment?: Readonly<Record<string, string>>
  prepare: SessionTargetPreparation
  signal?: AbortSignal
}): Promise<SessionTarget> {
  const selection = await selectSession(input)
  const selected = selection.session
  const location =
    selection.location ??
    (await resolveLocation(
      input.client,
      selected ? { directory: selected.location.directory } : input.location,
      input.signal,
    ))
  const prepared = await input.prepare({
    client: input.client,
    location,
    session: selected,
    model: input.model ?? selected?.model,
    agent: input.agent ?? selected?.agent,
    signal: input.signal,
  })
  const session =
    selected ??
    (await input.client.session
      .create(
        {
          id: input.session,
          agent: prepared.agent,
          model: prepared.model,
          location: { directory: location.directory },
        },
        ...requestOptions(input.signal),
      )
      .catch((error) => {
        throw new SessionTargetMutationError(error)
      }))
  if (input.environment !== undefined)
    await input.client.session
      .environment({ sessionID: session.id, variables: input.environment }, ...requestOptions(input.signal))
      .catch((error) => {
        throw new SessionTargetMutationError(error)
      })
  return {
    session,
    location,
    model: prepared.model,
    agent: prepared.agent ?? session.agent,
    resume: selected !== undefined,
  }
}

export function parseSessionTargetModel(value?: string): ModelRef | undefined {
  if (!value) return
  const model = Model.Ref.parse(value)
  return { providerID: model.providerID, id: model.id, variant: model.variant }
}

async function selectSession(input: {
  client: OpenCodeClient
  location?: { directory?: string }
  continue?: boolean
  session?: string
  fork?: boolean
  signal?: AbortSignal
}) {
  const explicit = input.session ? await findSession(input.client, input.session, input.signal) : undefined
  if (input.session && !explicit) {
    if (input.fork) throw new Error("Session not found")
    return { session: undefined }
  }
  if (explicit)
    return {
      session: input.fork
        ? await input.client.session
            .fork({ sessionID: explicit.id }, ...requestOptions(input.signal))
            .catch((error) => {
              throw new SessionTargetMutationError(error)
            })
        : explicit,
    }
  if (!input.continue) return { session: undefined }

  const location = await resolveLocation(input.client, input.location, input.signal)
  const selected = await latestSession(input.client, location, undefined, input.signal)
  if (!selected) return { session: undefined, location }
  return {
    session: input.fork
      ? await input.client.session.fork({ sessionID: selected.id }, ...requestOptions(input.signal)).catch((error) => {
          throw new SessionTargetMutationError(error)
        })
      : selected,
  }
}

export function findSession(client: OpenCodeClient, sessionID: string, signal?: AbortSignal) {
  return client.session.get({ sessionID }, ...requestOptions(signal)).catch((error) => {
    if (error && typeof error === "object" && "_tag" in error && error._tag === "SessionNotFoundError") return undefined
    throw error
  })
}

async function latestSession(
  client: OpenCodeClient,
  location: LocationGetOutput,
  cursor?: string,
  signal?: AbortSignal,
): Promise<SessionInfo | undefined> {
  const page = await client.session.list(
    {
      directory: location.directory,
      parentID: null,
      limit: SESSION_PAGE_LIMIT,
      order: "desc",
      ...(cursor ? { cursor } : {}),
    },
    ...requestOptions(signal),
  )
  const selected = page.data.find((session) => session.location.directory === location.directory)
  if (selected) return selected
  if (!page.cursor.next || page.data.length === 0) return
  return latestSession(client, location, page.cursor.next, signal)
}

function resolveLocation(client: OpenCodeClient, location?: { directory?: string }, signal?: AbortSignal) {
  if (!location && !signal) return client.location.get()
  if (!location) return client.location.get(undefined, { signal })
  return client.location.get({ location }, ...requestOptions(signal))
}

function requestOptions(signal?: AbortSignal): [] | [{ signal: AbortSignal }] {
  return signal ? [{ signal }] : []
}

import { expect, test } from "bun:test"
import { createServer } from "node:net"
import path from "node:path"

test("the executable askpass branch returns only the response, without CLI output", async () => {
  const requests: string[] = []
  const server = createServer((socket) => {
    socket.once("data", (data: Buffer) => {
      requests.push(data.toString())
      socket.end(JSON.stringify({ value: 'passphrase"with spaces' }))
    })
  })
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve))
  const address = server.address()
  if (!address || typeof address === "string") throw new Error("missing listener")
  try {
    const child = Bun.spawn([process.execPath, path.join(import.meta.dir, "index.ts"), "Enter passphrase:"], {
      env: {
        ...process.env,
        OPENCODE_SSH_ASKPASS_PORT: String(address.port),
        OPENCODE_SSH_ASKPASS_TOKEN: "fixture",
        SSH_ASKPASS_PROMPT: "confirm",
      },
      stdout: "pipe",
      stderr: "pipe",
    })
    expect(await new Response(child.stdout).text()).toBe('passphrase"with spaces\n')
    expect(await child.exited).toBe(0)
    expect(requests.map((request) => JSON.parse(request))).toEqual([
      { token: "fixture", text: "Enter passphrase:", confirm: true },
    ])
    expect(await new Response(child.stderr).text()).toBe("")
  } finally {
    await new Promise<void>((resolve) => server.close(() => resolve()))
  }
}, 30_000)

test("a response split inside a multi-byte character is written intact", async () => {
  const response = Buffer.from(JSON.stringify({ value: "pässwörd" }))
  // Split between the two bytes of "ä" so the helper reads them separately.
  const split = response.indexOf(0xc3) + 1
  const server = createServer((socket) => {
    socket.setNoDelay(true)
    socket.once("data", () => {
      socket.write(response.subarray(0, split))
      setTimeout(() => socket.end(response.subarray(split)), 50)
    })
  })
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve))
  const address = server.address()
  if (!address || typeof address === "string") throw new Error("missing listener")
  try {
    const child = Bun.spawn([process.execPath, path.join(import.meta.dir, "index.ts"), "Enter passphrase:"], {
      env: { ...process.env, OPENCODE_SSH_ASKPASS_PORT: String(address.port), OPENCODE_SSH_ASKPASS_TOKEN: "fixture" },
      stdout: "pipe",
      stderr: "pipe",
    })
    expect(await new Response(child.stdout).text()).toBe("pässwörd\n")
    expect(await child.exited).toBe(0)
  } finally {
    await new Promise<void>((resolve) => server.close(() => resolve()))
  }
}, 30_000)

import { NodeSocket } from "@effect/platform-node"
import { Effect, Schema, Stdio, Stream } from "effect"
import { Socket } from "effect/socket"

const Response = Schema.fromJsonString(Schema.Struct({ value: Schema.NullOr(Schema.String) }))
const Port = Schema.NumberFromString.check(Schema.isInt(), Schema.isGreaterThan(0), Schema.isLessThanOrEqualTo(65535))

// OpenSSH invokes the executable directly, including on Windows. Run outside
// normal CLI observability so neither prompts nor responses enter its logs.
export const askpass = Effect.gen(function* () {
  const port = yield* Schema.decodeUnknownEffect(Port)(process.env.OPENCODE_SSH_ASKPASS_PORT)
  const stdio = yield* Stdio.Stdio
  const socket = yield* NodeSocket.makeNet({ host: "127.0.0.1", port })
  const pull = yield* Socket.readerBytes(socket)
  const writer = yield* socket.writer
  yield* writer.write(
    JSON.stringify({
      token: process.env.OPENCODE_SSH_ASKPASS_TOKEN,
      text: process.argv.slice(2).join(" "),
      confirm: process.env.SSH_ASKPASS_PROMPT === "confirm",
    }) + "\n",
  )
  // One streaming decoder, so a character split across reads decodes intact.
  const decoder = new TextDecoder()
  const response = { text: "" }
  yield* Effect.gen(function* () {
    while (true) for (const chunk of yield* pull) response.text += decoder.decode(chunk, { stream: true })
  }).pipe(Effect.catchReason("SocketError", "SocketCloseError", () => Effect.void))
  const result = yield* Schema.decodeUnknownEffect(Response)(response.text)
  if (result.value === null) return 1
  yield* Stream.make(result.value + "\n").pipe(Stream.run(stdio.stdout({ endOnDone: false })))
  return 0
}).pipe(
  Effect.scoped,
  Effect.timeout("5 minutes"),
  Effect.orElseSucceed(() => 1),
)

import { AutocompletePrompt } from "@clack/core"
import { S_BAR, S_BAR_END, S_RADIO_ACTIVE, S_RADIO_INACTIVE, symbol } from "@clack/prompts"
import color from "picocolors"

export type IntegrationChoice = {
  value: string
  label: string
  category: "MCP" | "Popular" | "Services"
  connected: boolean
  hint?: string
}

export async function selectIntegration(choices: IntegrationChoice[], kind = "integration") {
  const result = await new AutocompletePrompt<IntegrationChoice>({
    options: choices,
    filter: (search, choice) =>
      [choice.label, choice.value, choice.category].some((value) => value.toLowerCase().includes(search.toLowerCase())),
    validate: (value) => (value ? undefined : `Select an ${kind}`),
    render() {
      const title = `${color.gray(S_BAR)}\n${symbol(this.state)}  Select ${kind}`
      if (this.state === "submit") {
        const choice = choices.find((item) => item.value === this.value)
        return `${title}\n${color.gray(S_BAR)}  ${color.dim(choice?.label ?? "")}`
      }
      if (this.state === "cancel")
        return `${title}\n${color.gray(S_BAR)}  ${color.strikethrough(color.dim(this.userInput))}`

      // Leave room for the category headings as well as Clack's title and footer.
      const maxItems = Math.min(8, Math.max(2, (process.stdout.rows ?? 24) - 14 - Number(this.state === "error")))
      const compact = (process.stdout.rows ?? 24) < 18
      const start = Math.min(
        Math.max(0, this.cursor - Math.min(2, maxItems - 1)),
        Math.max(0, this.filteredOptions.length - maxItems),
      )
      const visible = this.filteredOptions.slice(start, start + maxItems)
      const rows = visible.flatMap((choice, index) => [
        ...(index === 0 || visible[index - 1].category !== choice.category
          ? [...(compact ? [] : [`${color.cyan(S_BAR)}  `]), `${color.cyan(S_BAR)}  ${color.bold(choice.category)}`]
          : []),
        `${color.cyan(S_BAR)}  ${start + index === this.cursor ? color.green(S_RADIO_ACTIVE) : color.dim(S_RADIO_INACTIVE)} ${
          start + index === this.cursor ? choice.label : color.dim(choice.label)
        }${choice.connected ? ` ${color.green("✓")}` : ""}${choice.hint ? ` ${color.dim(`(${choice.hint})`)}` : ""}`,
      ])
      return [
        title,
        `${color.cyan(S_BAR)}  ${color.dim("Search:")} ${this.isNavigating ? color.dim(this.userInput) : this.userInputWithCursor}`,
        ...(visible.length === 0 && this.userInput
          ? [`${color.cyan(S_BAR)}  ${color.yellow(`No ${kind}s found`)}`]
          : []),
        ...(this.state === "error" && visible.length > 0
          ? [`${color.yellow(S_BAR)}  ${color.yellow(this.error)}`]
          : []),
        ...(start > 0 ? [`${color.cyan(S_BAR)}  ${color.dim("…")}`] : []),
        ...rows,
        ...(start + maxItems < this.filteredOptions.length ? [`${color.cyan(S_BAR)}  ${color.dim("…")}`] : []),
        `${color.cyan(S_BAR)}  ${color.dim(
          (process.stdout.columns ?? 80) < 50
            ? "↑/↓ navigate • Enter select"
