  ...Model.Info.default(Provider.ID.make(providerID), Model.ID.make(id)),
  name,
  variants: variants.map((variant) => ({ id: Model.VariantID.make(variant) })),
})

const catalog: Catalog = {
  models: [
    model("anthropic", "claude/sonnet-4", "Claude Sonnet 4", ["default", "high", "very-high"]),
    model("anthropic", "claude-haiku", "Claude Haiku"),
    model("openai", "gpt-5", "GPT-5", ["minimal", "low"]),
    model("test", "effort", "Effort", ["low", "default", "high"]),
  ],
  defaultModel: { providerID: Provider.ID.make("openai"), id: Model.ID.make("gpt-5") },
  modes: [{ id: Agent.ID.make("build"), name: "Build" }],
  defaultModeID: Agent.ID.make("build"),
  commands: [],
}

const effortOption = (providerID: string, id: string) =>
  configOptions(catalog, {
    model: {
      providerID: Provider.ID.make(providerID),
      id: Model.ID.make(id),
      variant: Model.VariantID.make("missing"),
    },
  }).find((option) => option.id === "effort")

describe("acp config options", () => {
  test("builds effort option from variants and falls back to default when current variant is invalid", () => {
    expect(effortOption("test", "effort")).toEqual({
      id: "effort",
      name: "Effort",
      description: "Available effort levels for this model",
      category: "thought_level",
      type: "select",
      currentValue: "default",
      options: [
        { value: "low", name: "Low" },
        { value: "default", name: "Default" },
        { value: "high", name: "High" },
      ],
    })
    expect(effortOption("openai", "gpt-5")?.currentValue).toBe("minimal")
  })

  test.each([
    ["openai/gpt-5", { providerID: Provider.ID.openai, id: Model.ID.make("gpt-5") }],
    [
      "openai/gpt-5/low",
      { providerID: Provider.ID.openai, id: Model.ID.make("gpt-5"), variant: Model.VariantID.make("low") },
    ],
    ["anthropic/claude/sonnet-4", { providerID: Provider.ID.anthropic, id: Model.ID.make("claude/sonnet-4") }],
    [
      "anthropic/claude/sonnet-4/high",
      {
        providerID: Provider.ID.anthropic,
        id: Model.ID.make("claude/sonnet-4"),
        variant: Model.VariantID.make("high"),
      },
    ],
    [
      "anthropic/claude/sonnet-4/missing",
      { providerID: Provider.ID.anthropic, id: Model.ID.make("claude/sonnet-4/missing") },
    ],
  ])("parses the model selection %s, preferring exact slash-containing model ids", (value, expected) => {
    expect(parseModelSelection(value, catalog.models)).toEqual(expected)
  })
})

import { describe, expect, test } from "bun:test"
import type { CreateElicitationResponse } from "@agentclientprotocol/sdk"
import { ACPElicitation } from "../../src/acp/elicitation"
import {
  delivered,
  ephemeralEvent,
  startSession,
  succeeded,
  textDelta,
  toolStarted,
  toolSucceeded,
} from "./wire-fixture"

const questions = (sessionID: string, id = "frm_question") =>
  ephemeralEvent("form.created", {
    form: {
      id,
      sessionID,
      title: "Questions",
      metadata: { kind: "question", tool: { messageID: "msg_tools", id: "call_question" } },
      fields: [
        {
          key: "q0",
          title: "Runtime",
          description: "Which runtime?",
          type: "string",
          options: [
            { value: "Bun", label: "Bun", description: "Fast" },
            { value: "Node", label: "Node", description: "Stable" },
          ],
          custom: true,
        },
        {
          key: "q1",
          title: "Goals",
          description: "What matters?",
          type: "multiselect",
          options: [{ value: "Fast", label: "Fast", description: "Speed" }],
          custom: true,
        },
      ],
    },
  })

const capable = { childSessionUpdates: false, formElicitation: true, compaction: false }

const form = (
  fields: ACPElicitation.AskedForm["fields"],
  metadata: ACPElicitation.AskedForm["metadata"] = { kind: "question" },
) => ({ id: "frm_test", sessionID: "ses_test", title: "Test", metadata, fields })

const accept = (content: Record<string, string | number | boolean | string[]>): CreateElicitationResponse => ({
  action: "accept",
  content,
})

describe("acp elicitation mapping", () => {
  test("cancels forms from unsupported clients, unknown flows, and credential-looking fields", () => {
    const fields: ACPElicitation.AskedForm["fields"] = [{ key: "name", type: "string" }]
    expect(ACPElicitation.requestedSchema(form(fields), { ...capable, formElicitation: false })).toBeUndefined()
    expect(ACPElicitation.requestedSchema(form(fields, { kind: "mcp-elicitation" }), capable)).toBeUndefined()
    expect(ACPElicitation.requestedSchema(form(fields, {}), capable)).toBeUndefined()
    expect(ACPElicitation.requestedSchema(form(fields, { kind: "websearch.provider" }), capable)).toBeDefined()
    const credentials: Array<ACPElicitation.AskedForm["fields"]> = [
      [{ key: "api_key", type: "string" }],
      [{ key: "q0", title: "GitHub token", type: "string" }],
      [{ key: "q0", title: "Password", type: "string", hidden: true, default: "" }],
      [{ key: "q0", title: "Setup", description: "Paste your API key", type: "string" }],
      [{ key: "q0", title: "Setup", type: "string", options: [{ value: "a", label: "Use my access token" }] }],
    ]
    expect(credentials.map((fields) => ACPElicitation.requestedSchema(form(fields), capable))).toEqual(
      credentials.map(() => undefined),
    )
  })
})

describe("acp elicitation over the wire", () => {
  test("answers a question form through elicitation and continues the turn", async () => {
    await using acp = await startSession({
      capabilities: { elicitation: true },
      onPrompt: ({ sessionID, id }) => [
        delivered(sessionID, id),
        toolStarted(sessionID, "call_question", "question"),
        questions(sessionID),
      ],
      elicitation: () => accept({ q0: "Bun", q1: ["Fast"], q1_custom: "Small" }),
      onFormReply: ({ sessionID, formID }) => [
        ephemeralEvent("form.replied", { sessionID, id: formID, answer: {} }),
        toolSucceeded(sessionID, "call_question", {}, "answered"),
        textDelta(sessionID, "msg_after", "thanks"),
        succeeded(sessionID),
      ],
    })

    expect((await acp.prompt(acp.sessionId, "hello")).stopReason).toBe("end_turn")
    expect(acp.elicitations).toMatchObject([
      { mode: "form", sessionId: acp.sessionId, toolCallId: "call_question", message: "Questions" },
    ])
    expect(acp.server.repliedForms).toEqual([
      { sessionID: acp.sessionId, formID: "frm_question", answer: { q0: "Bun", q1: ["Fast", "Small"] } },
    ])
    expect(acp.server.cancelledForms).toEqual([])
    expect(acp.updates.some((item) => item.update.sessionUpdate === "agent_message_chunk")).toBe(true)
  })

  test("cancels the form when the client declines, cancels, fails, or sends a wrong value type", async () => {
    const responses: Array<() => CreateElicitationResponse> = [
      () => ({ action: "decline" }),
      () => ({ action: "cancel" }),
      () => {
        throw new Error("elicitation UI failed")
      },
      () => ({ action: "accept", content: { q0: { nested: true } } }),
    ]
    const ids = ["frm_decline", "frm_cancel", "frm_fail", "frm_invalid"]
    await using acp = await startSession({
      capabilities: { elicitation: true },
      onPrompt: ({ sessionID, id }) => [delivered(sessionID, id), ...ids.map((form) => questions(sessionID, form))],
      elicitation: () => responses[acp.elicitations.length - 1](),
      onFormCancel: ({ sessionID }) => (acp.server.cancelledForms.length === ids.length ? [succeeded(sessionID)] : []),
    })

    expect((await acp.prompt(acp.sessionId, "hello")).stopReason).toBe("end_turn")
    expect(acp.elicitations).toHaveLength(ids.length)
    expect(acp.server.cancelledForms.map((item) => item.formID)).toEqual(ids)
    expect(acp.server.cancelledForms.map((item) => item.message)).toEqual(ids.map(() => undefined))
    expect(acp.server.repliedForms).toEqual([])
    expect(acp.server.interrupts).toEqual([])
  })
})

import { describe, expect, test } from "bun:test"
import { ACPError } from "../../src/acp/error"
import { delivered, rpcError, startSession, textDelta, type Wire } from "./wire-fixture"

describe("acp errors", () => {
  test("wraps unknown defects without leaking raw details", () => {
    const requestError = ACPError.toRequestError(
      ACPError.fromUnknown(new Error("stack has sk-ant-secret and oauth refresh token")),
    )
    const serialized = JSON.stringify(requestError.toErrorResponse())

    expect(requestError.code).toBe(-32603)
    expect(requestError.message).toBe("Internal error: Internal service failure")
    expect(serialized).not.toContain("sk-ant-secret")
    expect(serialized).not.toContain("oauth refresh token")
    expect(serialized).not.toContain("stack")
  })
})

describe("acp error boundary over the wire", () => {
  test.each<[string, (acp: Wire) => void, string[]]>([
    ["ends", (acp) => acp.server.closeEvents(), []],
    [
      "drops its connection",
      (acp) => acp.server.dropEvents(),
      ["ACP catalog event stream failed", "ACP selection event stream failed"],
    ],
  ])(
    "reports an unavailable server when the event stream %s mid-turn and once the server stops",
    async (_, lose, logs) => {
      await using acp = await startSession({
        onPrompt: ({ sessionID, id }) => [delivered(sessionID, id), textDelta(sessionID, "msg_held", "working")],
      })
      const unavailable = {
        code: -32603,
        message: "Internal error: OpenCode server is unavailable",
        data: { errorName: "ServerUnavailable" },
      }

      const prompt = acp.prompt(acp.sessionId, "hold")
      await acp.waitForUpdate((item) => item.update.sessionUpdate === "agent_message_chunk")
      await acp.request("session/set_mode", { sessionId: acp.sessionId, modeId: "build" })
      lose(acp)

      expect(await rpcError(prompt)).toEqual(unavailable)
      await acp.server.stop()
      expect(await rpcError(acp.request("session/list", {}))).toEqual(unavailable)
      expect(acp.logs.map((log) => String(log.message)).toSorted()).toEqual(logs)
    },
  )
})

import { describe, expect, test } from "bun:test"
import { createAcpFixture, initialize } from "./subprocess"

describe("acp lifecycle subprocess", () => {
  test("stdin EOF exits cleanly", async () => {
    await using fixture = await createAcpFixture()
    const acp = fixture.spawn()
    await initialize(acp)
    expect(await acp.close()).toBe(0)
  }, 60_000)

  // The private server is found with `pgrep`, which Windows lacks.
  const testOutsideWindows = process.platform === "win32" ? test.skip : test
  testOutsideWindows(
    "exits when the private server process dies (https://github.com/anomalyco/opencode/issues/51716)",
    async () => {
      await using fixture = await createAcpFixture()
      const acp = fixture.spawn()
      await initialize(acp)
      const servers = Bun.spawnSync(["pgrep", "-P", String(acp.pid)])
        .stdout.toString()
        .split("\n")
        .filter(Boolean)
        .map(Number)
      expect(servers).toHaveLength(1)

      process.kill(servers[0], "SIGKILL")

      const timeout = Promise.withResolvers<"running">()
      const timer = setTimeout(() => timeout.resolve("running"), 10_000)
      const exited = await Promise.race([acp.exited, timeout.promise]).finally(() => clearTimeout(timer))
      expect(exited).toBe(1)
      await acp[Symbol.asyncDispose]()
      expect(acp.stderr()).toContain("opencode acp: server exited unexpectedly (signal SIGKILL)")
    },
    60_000,
  )
})

import { describe, expect, test } from "bun:test"
import type { AnyRequest, CreateElicitationResponse, RequestPermissionResponse } from "@agentclientprotocol/sdk"
import type { OpenCodeEventEncoded } from "@opencode/protocol/groups/event"
import fs from "node:fs/promises"
import path from "node:path"
import { tmpdir } from "../fixture/tmpdir"
import {
  delivered,
  fileDiff,
  ephemeralEvent,
  interrupted,
  permissionAsked,
  startSession,
  startWire,
  succeeded,
  toolCalled,
  toolStarted,
  turn,
  type Wire,
} from "./wire-fixture"

const allowOnce = () => ({ outcome: { outcome: "selected", optionId: "once" } }) as const

describe("acp permissions over the wire", () => {
  test("forwards allow-once and allow-always selections to the server", async () => {
    const selections: Record<string, () => RequestPermissionResponse> = {
      call_once: allowOnce,
      call_always: () => ({ outcome: { outcome: "selected", optionId: "always" } }),
      perm_selected_reject: () => ({ outcome: { outcome: "selected", optionId: "reject" } }),
      perm_cancelled: () => ({ outcome: { outcome: "cancelled" } }),
      perm_failed: () => {
        throw new Error("client permission UI failed")
      },
    }
    await using acp = await startSession({
      onPrompt: ({ sessionID, id }) =>
        turn(
          sessionID,
          id,
          toolStarted(sessionID, "call_once", "shell"),
          toolCalled(sessionID, "call_once", { command: "printf hello" }),
          toolStarted(sessionID, "call_always", "read"),
          toolCalled(sessionID, "call_always", { path: "/workspace/file.ts" }),
          permissionAsked(sessionID, "perm_once", {
            action: "shell",
            metadata: { command: "printf hello" },
            source: { type: "tool", messageID: "msg_allow", id: "call_once" },
          }),
          permissionAsked(sessionID, "perm_always", {
            action: "read",
            metadata: { path: "/workspace/file.ts" },
            source: { type: "tool", messageID: "msg_allow", id: "call_always" },
          }),
          permissionAsked(sessionID, "perm_selected_reject"),
          permissionAsked(sessionID, "perm_cancelled"),
          permissionAsked(sessionID, "perm_failed"),
        ),
      permission: (request) => selections[request.toolCall.toolCallId](),
    })

    expect(await acp.prompt(acp.sessionId, "hello")).toMatchObject({ stopReason: "end_turn" })

    expect(acp.permissions[0]).toMatchObject({
      sessionId: acp.sessionId,
      toolCall: {
        toolCallId: "call_once",
        status: "pending",
        title: "printf hello",
        kind: "execute",
        locations: [{ path: "/workspace" }],
        rawInput: { command: "printf hello", cwd: "/workspace" },
      },
      options: [
        { optionId: "once", kind: "allow_once", name: "Allow once" },
        { optionId: "always", kind: "allow_always", name: "Always allow" },
        { optionId: "reject", kind: "reject_once", name: "Reject" },
      ],
    })
    expect(acp.permissions[1]).toMatchObject({
      sessionId: acp.sessionId,
      toolCall: {
        toolCallId: "call_always",
        status: "pending",
        title: "/workspace/file.ts",
        kind: "read",
        locations: [{ path: "/workspace/file.ts" }],
        rawInput: { path: "/workspace/file.ts" },
      },
    })
    expect(decisions(acp)).toEqual([
      ["perm_once", "once"],
      ["perm_always", "always"],
      ["perm_selected_reject", "reject"],
      ["perm_cancelled", "reject"],
      ["perm_failed", "reject"],
    ])
  })

  test.each<[string, string, string, (sessionID: string, id: string) => OpenCodeEventEncoded]>([
    ["session/request_permission", "perm", "reject", (sessionID, id) => permissionAsked(sessionID, id)],
    ["elicitation/create", "frm", "cancelled", (sessionID, id) => question(sessionID, id)],
  ])(
    "cancelling the turn cancels its pending %s and settles queued asks without sending them",
    async (method, prefix, outcome, ask) => {
      const pendingUntilAborted =
        <Response>(cancelled: Response) =>
        (_request: unknown, signal: AbortSignal) =>
          new Promise<Response>((resolve) => signal.addEventListener("abort", () => resolve(cancelled), { once: true }))
      await using acp = await startSession({
        capabilities: { elicitation: true },
        onPrompt: ({ sessionID, id }) => [
          delivered(sessionID, id),
          ask(sessionID, `${prefix}_pending`),
          ask(sessionID, `${prefix}_queued`),
        ],
        onInterrupt: ({ sessionID }) => [interrupted(sessionID)],
        permission: pendingUntilAborted<RequestPermissionResponse>({ outcome: { outcome: "cancelled" } }),
        elicitation: pendingUntilAborted<CreateElicitationResponse>({ action: "cancel" }),
      })

      const prompt = acp.prompt(acp.sessionId, "hello")
      await acp.until(() => acp.permissions.length + acp.elicitations.length === 1, "the pending ask")
      await acp.notify("session/cancel", { sessionId: acp.sessionId })

      expect(await prompt).toMatchObject({ stopReason: "cancelled" })
      const settled = () => [
        ...acp.server.replies.map((reply) => [reply.requestID, reply.decision]),
        ...acp.server.cancelledForms.map((form) => [form.formID, "cancelled"]),
      ]
      await acp.until(() => settled().length === 2, "both asks settled")
      expect(settled()).toEqual([
        [`${prefix}_pending`, outcome],
        [`${prefix}_queued`, outcome],
      ])
      expect(acp.server.repliedForms).toEqual([])
      const asked = acp.received.filter(
        (message): message is AnyRequest => "method" in message && "id" in message && message.method === method,
      )
      expect(asked).toHaveLength(1)
      expect(acp.received).toContainEqual({
        jsonrpc: "2.0",
        method: "$/cancel_request",
        params: { requestId: asked[0]?.id },
      })
    },
  )
  test("withdraws permission requests settled elsewhere and still asks the remaining one", async () => {
    await using acp = await startSession({
      onPrompt: ({ sessionID, id }) => [
        delivered(sessionID, id),
        permissionAsked(sessionID, "perm_elsewhere"),
        permissionAsked(sessionID, "perm_queued"),
        permissionAsked(sessionID, "perm_remaining"),
      ],
      fetch: (request) => {
        if (request.path.endsWith("/permission/perm_remaining/reply")) acp.server.send(succeeded(acp.sessionId))
        return undefined
      },
      permission: (_request, signal) =>
        acp.permissions.length === 1
          ? new Promise((resolve) => {
              signal.addEventListener("abort", () => resolve({ outcome: { outcome: "cancelled" } }), { once: true })
            })
          : allowOnce(),
    })

    const prompt = acp.prompt(acp.sessionId, "hello")
    await acp.until(() => acp.permissions.length === 1, "permission request")
    acp.server.send(
      ephemeralEvent("permission.replied", { sessionID: acp.sessionId, requestID: "perm_queued", reply: "always" }),
      ephemeralEvent("permission.replied", { sessionID: acp.sessionId, requestID: "perm_elsewhere", reply: "always" }),
    )

    expect(await prompt).toMatchObject({ stopReason: "end_turn" })
    expect(acp.permissions.map((request) => request.toolCall.toolCallId)).toEqual(["perm_elsewhere", "perm_remaining"])
    expect(decisions(acp)).toEqual([["perm_remaining", "once"]])
    const cancels = acp.received.filter((message) => "method" in message && message.method === "$/cancel_request")
    expect(cancels).toHaveLength(1)
    expect(acp.logs).toEqual([])
  })
})

describe("acp edit previews over the wire", () => {
  test("previews added files as new and deleted files as empty", async () => {
    await using dir = await tmpdir()
    await Promise.all(
      Object.entries({
        "file.ts": "one\r\ntwo\r\n",
        "first.ts": "one\n",
        "second.ts": "alpha\n",
        "gone.ts": "gone\n",
        "stale.ts": "changed\n",
        "unpatched.ts": "changed\n",
      }).map(([name, content]) => fs.writeFile(path.join(dir.path, name), content)),
    )
    await fs.mkdir(path.join(dir.path, "folder"))
    const file = (name: string) => path.join(dir.path, name)
    const patch = (...lines: string[]) => ["*** Begin Patch", ...lines, "*** End Patch"].join("\n")
    const edit = (sessionID: string, call: string, tool: string, input: Record<string, unknown>, metadata = {}) => [
      toolStarted(sessionID, call, tool),
      toolCalled(sessionID, call, input),
      permissionAsked(sessionID, `perm_${call}`, {
        action: "edit",
        metadata,
        source: { type: "tool", messageID: "msg_edit", id: call },
      }),
    ]
    await using acp = await startWire({
      onPrompt: ({ sessionID, id }) =>
        turn(
          sessionID,
          id,
          ...edit(
            sessionID,
            "call_edit",
            "edit",
            { path: "file.ts", oldString: "one\ntwo", newString: "one\nthree" },
            { files: [fileDiff("file.ts", "one\r\ntwo\r\n", "one\r\nthree\r\n")] },
          ),
          ...edit(sessionID, "call_patch", "patch", {
            patchText: patch(
              "*** Update File: first.ts",
              "@@",
              "-one",
              "+two",
              "*** Update File: second.ts",
              "@@",
              "-alpha",
              "+beta",
            ),
          }),
          ...edit(
            sessionID,
            "call_write",
            "write",
            { path: "written.ts", content: "two\n" },
            { files: [fileDiff("written.ts", "", "two\n", "added")] },
          ),
          ...edit(sessionID, "call_add", "patch", { patchText: patch("*** Add File: added.ts", "+one") }),
          permissionAsked(sessionID, "perm_delete", {
            action: "edit",
            metadata: { files: [fileDiff("gone.ts", "gone\n", "", "deleted")] },
          }),
          permissionAsked(sessionID, "perm_stale", {
            action: "edit",
            resources: ["stale.ts"],
            metadata: { files: [fileDiff("stale.ts", "one\n", "two\n")] },
          }),
          permissionAsked(sessionID, "perm_folder", {
            action: "edit",
            resources: ["folder"],
            metadata: { files: [fileDiff("folder", "one\n", "two\n")] },
          }),
          ...edit(sessionID, "call_unpatched", "patch", {
            patchText: patch("*** Update File: unpatched.ts", "@@", "-one", "+two"),
          }),
        ),
      permission: allowOnce,
    })
    await acp.initialize()
    const session = await acp.newSession(dir.path)

    await acp.prompt(session.sessionId, "hello")

    expect(acp.permissions.map((request) => request.toolCall.content)).toEqual([
      [{ type: "diff", path: file("file.ts"), oldText: "one\r\ntwo\r\n", newText: "one\r\nthree\r\n" }],
      [
        { type: "diff", path: file("first.ts"), oldText: "one\n", newText: "two\n" },
        { type: "diff", path: file("second.ts"), oldText: "alpha\n", newText: "beta\n" },
      ],
      [{ type: "diff", path: file("written.ts"), oldText: null, newText: "two\n" }],
      [{ type: "diff", path: file("added.ts"), oldText: null, newText: "one\n" }],
      [{ type: "diff", path: file("gone.ts"), oldText: "gone\n", newText: "" }],
      undefined,
      undefined,
      undefined,
    ])
    expect(acp.permissions.slice(0, 2).map((request) => request.toolCall)).toMatchObject([
      { title: "file.ts", kind: "edit", locations: [{ path: file("file.ts") }] },
      { title: "2 files", kind: "edit", locations: [{ path: file("first.ts") }, { path: file("second.ts") }] },
    ])
    expect(acp.permissions.slice(5).map((request) => request.toolCall.locations)).toEqual([
      [{ path: file("stale.ts") }],
      [{ path: file("folder") }],
      [{ path: file("unpatched.ts") }],
    ])
    expect(acp.permissions[0]?.toolCall.name).toBe("edit")
    expect(acp.permissions[4]?.toolCall).not.toHaveProperty("name")
    expect(decisions(acp)).toHaveLength(8)
  })
})

function question(sessionID: string, id: string) {
  return ephemeralEvent("form.created", {
    form: {
      id,
      sessionID,
      title: "Questions",
      metadata: { kind: "question" },
      fields: [{ key: "q0", title: "Runtime", type: "string", options: [{ value: "Bun", label: "Bun" }] }],
    },
  })
}

function decisions(acp: Wire) {
  return acp.server.replies.map((reply) => [reply.requestID, reply.decision])
}

