  test("reports OAuth status polling failures and cancels the attempt", async () => {
    let cancelled = false
    using server = authServer((request, url) => {
      if (url.pathname === "/api/integration") {
        return Response.json(
          located([
            {
              id: "openai",
              name: "OpenAI",
