import { expect } from "bun:test"
import { mkdtemp, rename, rm } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { waitForExit } from "./service-timing"

// Windows has no catchable SIGTERM: process.kill ends the target at once with exit code 1, so the
// service's SIGTERM handler (record the signal, unregister a lingering server, exit 0) runs only on POSIX.
export const catchesSigterm = process.platform !== "win32"
export const stopSignal = catchesSigterm ? "SIGTERM" : undefined
export const stoppedExitCode = catchesSigterm ? 0 : 1

export async function serviceFixture() {
  const directory = await mkdtemp(join(tmpdir(), "opencode-client-service-"))
  const registration = join(directory, "service.json")
  const processes: Bun.Subprocess[] = []
  const pids = new Set<number>()
  const starts = async () =>
    (
      await Bun.file(registration + ".starts")
        .text()
        .catch(() => "")
    )
      .trim()
      .split("\n")
      .filter(Boolean)
      .map(Number)
  const command = (mode: string, ...args: string[]) => [
    process.execPath,
    join(import.meta.dir, "service.ts"),
    registration,
    mode,
    ...args,
  ]

  return {
    directory,
    registration,
    command,
    starts,
    async waitForStarts(count: number) {
      for (let attempt = 0; attempt < 600; attempt++) {
        const result = await starts()
        if (result.length >= count) return result
        await Bun.sleep(5)
      }
      throw new Error(`Timed out waiting for ${count} contenders`)
    },
    async release(pid: number, action: "fail" | "hang" | "ready") {
      const file = registration + `.release-${pid}`
      await Bun.write(file + ".tmp", action)
      await rename(file + ".tmp", file)
      if (action === "fail") await waitForExit(pid)
    },
    spawn(mode: string, ...args: string[]) {
      const subprocess = Bun.spawn(command(mode, ...args), { stdout: "ignore", stderr: "inherit" })
      processes.push(subprocess)
      return subprocess
    },
    // The service's parent execs `sleep`, which never reaps it, so SIGKILL leaves a zombie that
    // still answers `kill(pid, 0)`. Terminating the returned parent lets init reap the service.
    spawnUnreaped(mode: string, ...args: string[]) {
      const subprocess = Bun.spawn(["sh", "-c", '"$@" & exec sleep 60', "sh", ...command(mode, ...args)], {
        stdout: "ignore",
        stderr: "inherit",
      })
      processes.push(subprocess)
      return subprocess
    },
    // Service.ensure detaches contenders; track the elected process before asserting.
    track(pid: number) {
      pids.add(pid)
    },
    // The signal the service recorded while shutting down, if its handler ran.
    signal() {
      return Bun.file(registration + ".signal")
        .text()
        .catch(() => undefined)
    },
    async waitForFile(file = registration) {
      for (let attempt = 0; attempt < 600; attempt++) {
        if (await Bun.file(file).exists()) return
        await Bun.sleep(5)
      }
      throw new Error(`Timed out waiting for ${file}`)
    },
    async [Symbol.asyncDispose]() {
      // Include detached contenders that never registered, even when an assertion fails.
      for (const pid of await starts()) pids.add(pid)
      await Promise.all([
        ...processes.map(async (subprocess) => {
          subprocess.kill("SIGTERM")
          await subprocess.exited
        }),
        ...[...pids].map(async (pid) => {
          try {
            process.kill(pid, "SIGTERM")
          } catch (error) {
            if (!(error instanceof Error && "code" in error && error.code === "ESRCH")) throw error
          }
          await waitForExit(pid)
        }),
      ]).finally(() => rm(directory, { recursive: true, force: true }))
    },
  }
}

// The service listens on an ephemeral port. Once it stops, any process may reuse that port for an outgoing connection
// (Windows hands them out from 49152 up, and other suites run alongside), so binding it again proves nothing. What the
// tests need is that nothing accepts connections there anymore.
export async function expectNotListening(url: string) {
  const outcome = await fetch(url).then(
    (response) => `listening (${response.status})`,
    () => "no response",
  )
  expect(outcome).toBe("no response")
}

import { withEnsureTiming } from "../../src/service-timing"

const timing = {
  pollInterval: 20,
  requestTimeout: 100,
  spawnDelay: 200,
  maxSpawnDelay: 1_200,
  promiseTimeout: 3_000,
  stopPollInterval: 5,
}

export function accelerate<A extends object, B>(ensure: (options?: A) => B) {
  return (options: A) => ensure(withEnsureTiming(options, timing))
}

export async function waitForExit(pid: number) {
  for (let attempt = 0; attempt < 600; attempt++) {
    try {
      process.kill(pid, 0)
    } catch {
      return
    }
    await Bun.sleep(5)
  }
  throw new Error(`Timed out waiting for process ${pid}`)
}

import { appendFile, rename, rm, writeFile } from "node:fs/promises"

const [registration, mode, delay] = process.argv.slice(2)
if (registration === undefined || mode === undefined) throw new Error("Missing service fixture arguments")
if (mode === "failed") process.exit(1)
if (mode === "stderr-failed") {
  process.stderr.write("x".repeat(16_384) + "\nactionable startup failure\n")
  process.exit(1)
}
if (mode === "record-start") {
  await writeFile(registration + ".started", "")
  process.exit(1)
}
if (mode === "environment") {
  await writeFile(registration + ".environment", process.env.OPENCODE_SERVICE_ENV_TEST ?? "")
  await writeFile(registration + ".handoff", process.env.OPENCODE_PTY_HANDOFF ?? "null")
}
if (mode === "signal") process.kill(process.pid, process.platform === "win32" ? "SIGTERM" : "SIGKILL")

let controlled = ""
if (mode === "controlled") {
  await appendFile(registration + ".starts", process.pid + "\n")
  const release = registration + `.release-${process.pid}`
  while (!(await Bun.file(release).exists())) await Bun.sleep(5)
  controlled = await Bun.file(release).text()
  if (controlled === "fail") {
    process.stderr.write("actionable startup failure: storage initialization denied\n")
    process.exit(23)
  }
}

if (mode === "delayed" || mode === "delayed-failed" || mode === "coordinated" || mode === "coordinated-failed-loser") {
  await appendFile(registration + ".starts", process.pid + "\n")
  const owner = await writeFile(registration + ".owner", String(process.pid), { flag: "wx" })
    .then(() => true)
    .catch(() => false)
  if (!owner) process.exit(mode === "coordinated-failed-loser" ? 1 : 0)
  if (mode === "coordinated" || mode === "coordinated-failed-loser") {
    while ((await Bun.file(registration + ".starts").text()).trim().split("\n").length < 2) await Bun.sleep(10)
    if (mode === "coordinated-failed-loser") await Bun.sleep(Number(delay ?? 1_500))
  } else await Bun.sleep(Number(delay))
  if (mode === "delayed-failed") process.exit(1)
}

let requests = 0
let version = "test"
if (mode === "old" || mode === "handoff") version = "old"
if (mode === "incompatible") version = "1.9.0"
if (mode === "compatible" || mode === "delayed-compatible") version = "2.1.0-next.1"
const id = crypto.randomUUID()
const handoff = {
  directory: registration + ".daemon",
  instanceID: crypto.randomUUID(),
  ticket: crypto.randomUUID(),
  expiresAt: Date.now() + 30_000,
}
const server = Bun.serve({
  port: 0,
  async fetch(request): Promise<Response> {
    const pathname = new URL(request.url).pathname
    if (mode === "protocol" && pathname === "/api/experimental/persistent-pty/handoff") {
      await writeFile(registration + ".handoff-request", "")
      return Response.json({ handoff: null })
    }
    if (pathname === "/api/experimental/persistent-pty/handoff" && mode === "handoff") {
      if (request.method !== "POST" || request.headers.get("authorization") !== "Basic " + btoa("opencode:private"))
        return new Response(null, { status: 401 })
      await writeFile(registration + ".prepared", JSON.stringify(handoff))
      return Response.json({ handoff })
    }
    if (pathname === "/api/experimental/persistent-pty/handoff" && mode === "handoff-broken")
      return new Response(null, { status: 500 })
    if (pathname !== "/api/info") return new Response(null, { status: 404 })
    if (mode === "protocol" && (await Bun.file(registration + ".missing-health").exists()))
      return new Response(null, { status: 404 })
    requests += 1
    if (mode === "starting") await writeFile(registration + ".status-request", "")
    if (mode === "hanging" || controlled === "hang") {
      await appendFile(registration + ".requests", process.pid + "\n")
      return new Promise<Response>(() => {})
    }
    if (mode === "modern" && requests === 1) {
      await writeFile(registration + ".first-request", "")
      while (!(await Bun.file(registration + ".release").exists())) await Bun.sleep(5)
      return new Response(null, { status: 503 })
    }
    if (mode === "starting" && !(await Bun.file(registration + ".release").exists()))
      return Response.json(
        { version, pid: process.pid, urls: [server.url.toString()], paths: { tmp: "/tmp/opencode" } },
        { status: 503 },
      )
    if (mode === "failed-owner")
      return Response.json(
        { version, pid: process.pid, urls: [server.url.toString()], paths: { tmp: "/tmp/opencode" } },
        { status: 500 },
      )
    return Response.json({
      version,
      pid: process.pid,
      urls: [server.url.toString()],
      paths: { tmp: "/tmp/opencode" },
    })
  },
})

// Install handlers before publishing: a test may signal as soon as the registration appears.
if (controlled !== "hang") {
  process.on("SIGTERM", () => void shutdown("SIGTERM"))
  process.on("SIGINT", () => void shutdown("SIGINT"))
}

await writeFile(
  registration + ".tmp",
  JSON.stringify({
    id,
    version,
    url: server.url.toString(),
    pid: process.pid,
    password: "private",
  }),
  { mode: 0o600 },
)
await rename(registration + ".tmp", registration)

async function shutdown(signal?: NodeJS.Signals) {
  if (signal !== undefined) await writeFile(registration + ".signal", signal)
  // A lingering server unregisters on SIGTERM but keeps running, and holds its port, until killed.
  if (mode === "lingering") {
    await rm(registration, { force: true })
    await writeFile(registration + ".unregistered", "")
    await Bun.sleep(Number(delay))
  }
  server.stop(true)
  process.exit()
}

import { describe, expect, test } from "bun:test"
import { realpathSync } from "node:fs"
import { mkdtemp, rm } from "node:fs/promises"
import { join, resolve, sep } from "node:path"

const directory = resolve(import.meta.dir, "..")
const effect = realpathSync(resolve(import.meta.dir, "../node_modules/effect"))
const schema = resolve(import.meta.dir, "../../schema")
const protocol = resolve(import.meta.dir, "../../protocol")
const core = resolve(import.meta.dir, "../../core")
const server = resolve(import.meta.dir, "../../server")

describe("public import boundaries", () => {
  test("isolates each public entrypoint", async () => {
    const root = await bundleInputs("@opencode/client", "browser")

    expect(within(root.all, effect)).toEqual([])
    expect(within(root.all, schema)).toEqual([])
    expect(within(root.all, protocol)).toEqual([])
    expect(within(root.all, core)).toEqual([])
    expect(within(root.all, server)).toEqual([])

    const network = await bundleInputs("@opencode/client/effect", "browser")

    expect(within(network.eager, effect).length).toBeGreaterThan(0)
    expect(within(network.eager, schema).length).toBeGreaterThan(0)
    expect(within(network.eager, protocol).length).toBeGreaterThan(0)
    expect(within(network.all, core)).toEqual([])
    expect(within(network.all, server)).toEqual([])

    const promiseService = await bundleInputs("@opencode/client/service", "bun")

    expect(within(promiseService.all, effect)).toEqual([])
    expect(within(promiseService.all, schema)).toEqual([])
    expect(within(promiseService.all, protocol)).toEqual([])
    expect(within(promiseService.all, core)).toEqual([])
    expect(within(promiseService.all, server)).toEqual([])

    const effectService = await bundleInputs("@opencode/client/effect/service", "bun")

    expect(within(effectService.eager, effect).length).toBeGreaterThan(0)
    expect(within(effectService.all, core)).toEqual([])
    expect(within(effectService.all, server)).toEqual([])
  })
})

async function bundleInputs(specifier: string, target: "browser" | "bun") {
  const temporary = await mkdtemp(join(import.meta.dir, ".import-boundary-"))
  const entrypoint = join(temporary, "index.ts")
  const metafile = join(temporary, "meta.json")
  try {
    await Bun.write(entrypoint, `export * from ${JSON.stringify(specifier)}`)
    const child = Bun.spawn(
      [
        process.execPath,
        "build",
        entrypoint,
        `--target=${target}`,
        "--format=esm",
        "--packages=bundle",
        `--metafile=${metafile}`,
        `--outdir=${join(temporary, "out")}`,
      ],
      { cwd: directory, stdout: "pipe", stderr: "pipe" },
    )
    const [exitCode, stdout, stderr] = await Promise.all([
      child.exited,
      new Response(child.stdout).text(),
      new Response(child.stderr).text(),
    ])
    if (exitCode !== 0) throw new Error(stdout + stderr)
    const metadata: {
      inputs: Record<string, { imports: Array<{ path: string; kind: string; external?: boolean }> }>
    } = await Bun.file(metafile).json()
    const inputs = new Map(Object.entries(metadata.inputs).map(([file, input]) => [resolve(directory, file), input]))
    const eager = new Set<string>()
    const visit = (file: string) => {
      if (eager.has(file)) return
      eager.add(file)
      inputs
        .get(file)
        ?.imports.filter((input) => !input.external && input.kind !== "dynamic-import")
        .forEach((input) => visit(resolve(directory, input.path)))
    }
    visit(entrypoint)
    return { all: Array.from(inputs.keys()), eager: Array.from(eager) }
  } finally {
    await rm(temporary, { recursive: true, force: true })
  }
}

function within(inputs: ReadonlyArray<string>, directory: string) {
  const prefix = directory.endsWith(sep) ? directory : directory + sep
  return inputs.filter((input) => input === directory || input.startsWith(prefix))
}

