  ]) {
    const next = active.next()
    events.connections[0].push(event)
    expect(
      await Promise.race([next, Bun.sleep(1_000).then(() => ({ done: true as const, value: { type: "timeout" } }))]),
    ).toEqual({ done: false, value: event })
  }

  await idle.return!()
  await active.return!()
  await events.connections[0].closed
})

