import { describe, expect, test } from "bun:test"
import { Schema } from "effect"
import { Worktree } from "@opencode/schema/worktree"

describe("Worktree.adopt", () => {
  const event = {
    projectID: "repository",
    directory: "/repo",
    previous: "previous",
    adopted: ["directory-root", "directory-nested"],
  }

  test("adopts explicitly superseded directory projects", () => {
    expect(Worktree.adopt({ projectID: "directory-root", directory: "/repo" }, event)).toEqual({
      projectID: "repository",
      subpath: undefined,
    })
    expect(Worktree.adopt({ projectID: "directory-nested", directory: "/repo/packages/app" }, event)).toEqual({
      projectID: "repository",
      subpath: "packages/app",
    })
  })

  test("preserves existing previous-project and global adoption", () => {
    expect(Worktree.adopt({ projectID: "previous", directory: "/repo/packages/app" }, event)).toEqual({
      projectID: "repository",
      subpath: "packages/app",
    })
    expect(Worktree.adopt({ projectID: "global", directory: "/repo/packages/app" }, event)).toEqual({
      projectID: "repository",
      subpath: "packages/app",
    })
  })

  test("leaves unrelated projects, sibling directories, and workspaces unchanged", () => {
    expect(Worktree.adopt({ projectID: "other", directory: "/repo/vendor" }, event)).toBeUndefined()
    expect(Worktree.adopt({ projectID: "global", directory: "/repo-other" }, event)).toBeUndefined()
    expect(Worktree.adopt({ projectID: "repository", directory: "/repo" }, event)).toBeUndefined()
    expect(
      Worktree.adopt({ projectID: "directory-root", directory: "/repo", workspaceID: "remote" }, event),
    ).toBeUndefined()
  })

  test("normalizes Windows directory separators", () => {
    expect(
      Worktree.adopt(
        { projectID: "directory-nested", directory: "C:\\repo\\packages\\app" },
        { ...event, directory: "C:\\repo" },
      ),
    ).toEqual({ projectID: "repository", subpath: "packages/app" })
    expect(
      Worktree.adopt(
        { projectID: "directory-nested", directory: "c:/Repo/packages/App" },
        { ...event, directory: "C:\\repo" },
      ),
    ).toEqual({ projectID: "repository", subpath: "packages/App" })
  })

  test("normalizes aliases and rejects paths that leave the repository", () => {
    expect(Worktree.adopt({ projectID: "directory-nested", directory: "/repo/alias/../packages/app" }, event)).toEqual({
      projectID: "repository",
      subpath: "packages/app",
    })
    expect(Worktree.adopt({ projectID: "global", directory: "/repo/../other" }, event)).toBeUndefined()
    expect(Worktree.adopt({ projectID: "global", directory: "/app" }, { ...event, directory: "/" })).toEqual({
      projectID: "repository",
      subpath: "app",
    })
  })

  test("decodes existing durable events without adopted project IDs", () => {
    expect(
      Schema.decodeUnknownSync(Worktree.Event.Resolved.data)({
        projectID: "repository",
        directory: "/repo",
        previous: "global",
      }),
    ).toEqual({ projectID: "repository", directory: "/repo", previous: "global" })
  })
})

#!/usr/bin/env bun

import { Script } from "@opencode/script"
import { $ } from "bun"
import { mkdtemp, rm } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { fileURLToPath } from "node:url"

process.chdir(fileURLToPath(new URL("..", import.meta.url)))

const dryRun = Bun.argv.includes("--dry-run")
const originalText = await Bun.file("package.json").text()
const pkg = JSON.parse(originalText) as {
  name: string
  version: string
  exports: Record<string, string | { import: string; types: string }>
  imports?: Record<string, Record<string, string>>
}
const tarball = `${pkg.name.replace("@", "").replace("/", "-")}-${pkg.version}.tgz`
const output = (value: string, types = false) =>
  value.replace("./src/", "./dist/").replace(/\.ts$/, types ? ".d.ts" : ".js")

if (!dryRun && (await $`npm view ${pkg.name}@${pkg.version} version`.nothrow()).exitCode === 0) {
  console.log(`already published ${pkg.name}@${pkg.version}`)
  process.exit(0)
}

try {
  await $`bun run typecheck`
  await $`bun run build`
  pkg.exports = Object.fromEntries(
    Object.entries(pkg.exports).map(([key, value]) => {
      if (typeof value !== "string") return [key, value]
      return [
        key,
        {
          import: output(value),
          types: output(value, true),
        },
      ]
    }),
  )
  if (pkg.imports) {
    pkg.imports = Object.fromEntries(
      Object.entries(pkg.imports).map(([key, conditions]) => [
        key,
        Object.fromEntries(Object.entries(conditions).map(([condition, value]) => [condition, output(value)])),
      ]),
    )
  }
  await Bun.write("package.json", JSON.stringify(pkg, null, 2) + "\n")
  await rm(tarball, { force: true })
  await $`bun pm pack`
  const consumer = await mkdtemp(join(tmpdir(), "opencode-codemode-"))
  try {
    await Bun.write(
      join(consumer, "package.json"),
      JSON.stringify({
        private: true,
        type: "module",
        dependencies: { [pkg.name]: `file:${join(process.cwd(), tarball)}` },
      }),
    )
    await $`npm install --ignore-scripts --no-audit --no-fund`.cwd(consumer)
    await $`node --input-type=module -e ${`await import(${JSON.stringify(pkg.name)})`}`.cwd(consumer)
    await $`bun --conditions=workerd -e ${`await import(${JSON.stringify(pkg.name)})`}`.cwd(consumer)
  } finally {
    await rm(consumer, { recursive: true, force: true })
  }
  if (!dryRun) await $`npm publish ${tarball} --tag ${Script.channel} --access public`
} finally {
  await Bun.write("package.json", originalText)
  await rm(tarball, { force: true })
}

// Copies the manifest's test262 directories from a local checkout into test/test262, verbatim.
// Files needing unsupported flags, features, or harness includes, or whose code crosses one of the
// interpreter's intentional boundaries, are not copied, so the vendored tree is exactly what
// test/test262.test.ts runs.
//
// Usage: bun run script/sync-test262.ts /path/to/test262
import path from "node:path"
import { rm } from "node:fs/promises"

type Frontmatter = { flags?: Array<string>; features?: Array<string>; includes?: Array<string> }

const root = path.resolve(import.meta.dir, "../test/test262")
const manifest = (await Bun.file(path.join(root, "manifest.json")).json()) as {
  revision: string
  directories: Array<string>
  harness: Array<string>
  flags: Array<string>
  features: Array<string>
  boundaries: Record<string, string>
}
const boundaries = Object.entries(manifest.boundaries).map(([name, pattern]) => [name, new RegExp(pattern)] as const)
const checkout = process.argv[2]
if (checkout === undefined) {
  console.error("usage: bun run script/sync-test262.ts /path/to/test262")
  process.exit(1)
}
const head = (await Bun.$`git -C ${checkout} rev-parse HEAD`.text()).trim()
if (head !== manifest.revision) {
  console.error(`checkout is at ${head}; manifest pins ${manifest.revision}`)
  process.exit(1)
}

const excluded = new Map<string, number>()
let copied = 0
for (const dir of manifest.directories) {
  await rm(path.join(root, dir), { recursive: true, force: true })
  const from = path.join(checkout, "test", dir)
  for await (const file of new Bun.Glob("**/*.js").scan({ cwd: from })) {
    if (file.endsWith("_FIXTURE.js")) continue
    const source = await Bun.file(path.join(from, file)).text()
    const start = source.indexOf("/*---")
    const end = source.indexOf("---*/", start)
    const meta = start === -1 ? {} : (Bun.YAML.parse(source.slice(start + 5, end)) as Frontmatter)
    const code = start === -1 ? source : source.slice(end + 5)
    const reason =
      meta.flags?.find((flag) => manifest.flags.includes(flag)) ??
      meta.features?.find((feature) => manifest.features.includes(feature)) ??
      meta.includes?.find((include) => !manifest.harness.includes(include)) ??
      boundaries.find(([, pattern]) => pattern.test(code))?.[0]
    if (reason !== undefined) {
      excluded.set(reason, (excluded.get(reason) ?? 0) + 1)
      continue
    }
    await Bun.write(path.join(root, dir, file), Bun.file(path.join(from, file)))
    copied++
  }
}

console.log(`copied ${copied} files`)
for (const [reason, count] of [...excluded].sort((a, b) => b[1] - a[1])) {
  console.log(`  excluded ${String(count).padStart(5)}  ${reason}`)
}

// Runs every vendored test262 file, including skipped ones, and groups failures by cause. Pass
// --write to regenerate test/test262/skipped.txt from the current failures.
//
// Usage: bun run script/test262-report.ts [--write] [path-prefix]
import path from "node:path"
import { root, run, skipped } from "../test/test262/run.js"

const write = process.argv.includes("--write")
const prefix = process.argv.slice(2).find((arg) => !arg.startsWith("--")) ?? ""
const files = [...new Bun.Glob("**/*.js").scanSync({ cwd: root })].filter((file) => file.startsWith(prefix)).sort()

const failures: Array<{ file: string; reason: string }> = []
const recovered: Array<string> = []
for (const file of files) {
  const outcome = await run(file)
  if (outcome.status === "fail") failures.push({ file, reason: outcome.reason })
  if (outcome.status === "pass" && skipped.has(file)) recovered.push(file)
}

// Collapse a reason to the part that identifies the cause rather than the test.
const bucket = (reason: string) => {
  const syntax = reason.match(/Syntax '([A-Za-z]+)' is not supported/)
  if (syntax) return `unsupported syntax ${syntax[1]}`
  if (reason.startsWith("expected ")) return reason.replace(/ but got .*/, " but the program ran")
  return reason
    .replace(/^(\$DONE: |ExecutionFailure: |InvalidDataValue: |ParseError: |Uncaught: |Test262Error: |Error: )+/, "")
    .replace(/ \(line \d+, col \d+\)/, "")
    .replace(/^[\w$]+\.(\w+) is not a function/, ".$1 is not a function")
    .replace(/^[\w$]+ cannot be constructed/, "… cannot be constructed")
    .replace(/'[^']*'/g, "'…'")
    .slice(0, 100)
}

const buckets = new Map<string, Array<string>>()
for (const failure of failures) {
  const key = bucket(failure.reason)
  buckets.set(key, [...(buckets.get(key) ?? []), failure.file])
}

console.log(`${files.length - failures.length} pass, ${failures.length} fail of ${files.length}\n`)
for (const [key, list] of [...buckets].sort((a, b) => b[1].length - a[1].length)) {
  console.log(`${String(list.length).padStart(5)}  ${key}`)
  for (const file of list.slice(0, 3)) console.log(`         ${file}`)
  if (list.length > 3) console.log(`         … ${list.length - 3} more`)
}
if (recovered.length > 0) {
  console.log(`\n${recovered.length} skipped files pass now; remove them from skipped.txt:`)
  for (const file of recovered) console.log(`         ${file}`)
}

if (write) {
  const lines = failures.map((failure) => `${failure.file}  # ${bucket(failure.reason)}`)
  await Bun.write(path.join(root, "skipped.txt"), `${lines.join("\n")}\n`)
  console.log(`\nwrote ${lines.length} entries to skipped.txt`)
}

import { Effect, Schema } from "effect"
import type { Extension } from "./extension.js"
import { executeProgram } from "./interpreter/execute.js"
import { extensionGlobals } from "./interpreter/extensions.js"
import { globalNames } from "./interpreter/globals.js"
import { type Services, type ToolDescription, ToolRuntime } from "./tool-runtime.js"
import type { Tools } from "./tools.js"

/** A tool call admitted during an execution. */
export type {
  CallResult,
  ExtensionInvocation,
  Hooks,
  ToolCall,
  ToolDescription,
  ToolInvocation,
} from "./tool-runtime.js"
/** Signature-construction helpers for host-owned catalog instructions. */
export { searchSignature, toolExpression } from "./tool-runtime.js"

/** Resource budgets enforced independently during each CodeMode program execution. */
export type ExecutionLimits = {
  /**
   * Wall-clock milliseconds before interruption. Result delivery waits for tool cleanup.
   * No default: absent means no timeout.
   */
  readonly timeoutMs?: number
  /** Maximum number of tool calls admitted by the runtime. No default: absent means unlimited. */
  readonly maxToolCalls?: number
  /**
   * Maximum UTF-8 bytes retained from the result and logs. Warnings have a separate equal budget;
   * truncation notices and host formatting are additional.
   */
  readonly maxOutputBytes?: number
}

export type ResolvedExecutionLimits = {
  readonly timeoutMs: number | undefined
  readonly maxToolCalls: number | undefined
  readonly maxOutputBytes: number | undefined
}

/** Configuration shared by `CodeMode.make` and `CodeMode.execute`. */
export type Options<Provided extends Record<string, unknown> = {}> = {
  /** Explicit tools exposed to the program as `tools`. */
  tools?: Provided & Tools<Services<Provided>>
  /** Hooks around every tool and extension call the program makes; see `Hooks`. */
  hooks?: ToolRuntime.Hooks<Services<Provided>>
  /** Host functions exposed as globals; see `Extension.make`. */
  extensions?: ReadonlyArray<Extension>
  /** Resource limits enforced on each execution. */
  limits?: ExecutionLimits
}

/** Options for one CodeMode execution. */
export type ExecuteOptions<Provided extends Record<string, unknown> = {}> = Options<Provided> & {
  /** Source for one program in the supported JavaScript subset. */
  code: string
}

/** A JSON value that can cross the confined interpreter boundary. */
export type DataValue = Schema.Json

/** Schema for a host tool input containing CodeMode source. */
export const Input = Schema.Struct({ code: Schema.String })
export type Input = typeof Input.Type

export const DiagnosticKind = Schema.Literals([
  "ParseError",
  "UnsupportedSyntax",
  "UnknownTool",
  "InvalidToolInput",
  "InvalidToolOutput",
  "InvalidDataValue",
  "ToolCallLimitExceeded",
  "TimeoutExceeded",
  "ToolFailure",
  "ExecutionFailure",
  "Truncated",
])
/** Stable categories produced by program, schema, tool, limit, and truncation diagnostics. */
export type DiagnosticKind = typeof DiagnosticKind.Type

export const Diagnostic = Schema.Struct({
  kind: DiagnosticKind,
  message: Schema.String,
  location: Schema.optionalKey(Schema.Struct({ line: Schema.Number, column: Schema.Number })),
  suggestions: Schema.optionalKey(Schema.Array(Schema.String)),
})
/** A normalized program diagnostic safe to return across an agent tool boundary. */
export type Diagnostic = typeof Diagnostic.Type

const ToolCallSchema = Schema.Struct({ name: Schema.String })
export const Success = Schema.Struct({
  ok: Schema.Literal(true),
  value: Schema.Json,
  warnings: Schema.optionalKey(Schema.Array(Diagnostic)),
  logs: Schema.optionalKey(Schema.Array(Schema.String)),
  truncated: Schema.optionalKey(Schema.Boolean),
  toolCalls: Schema.Array(ToolCallSchema),
})
/** Successful execution after the result has crossed the plain-data boundary. */
export type Success = typeof Success.Type

export const Failure = Schema.Struct({
  ok: Schema.Literal(false),
  error: Diagnostic,
  logs: Schema.optionalKey(Schema.Array(Schema.String)),
  truncated: Schema.optionalKey(Schema.Boolean),
  toolCalls: Schema.Array(ToolCallSchema),
})
/** Failed execution with calls admitted before the diagnostic was produced. */
export type Failure = typeof Failure.Type

/** Schema for the structured success or diagnostic returned by CodeMode execution. */
export const Result = Schema.Union([Success, Failure])
/** Result of executing a CodeMode program. Program failures are data, not Effect failures. */
export type Result = typeof Result.Type

/** Reusable confined runtime over explicit tools. */
export type Runtime<R = never> = {
  readonly catalog: ReadonlyArray<ToolDescription>
  readonly execute: (code: string) => Effect.Effect<Result, never, R>
}

const validateLimit = (name: keyof ExecutionLimits, value: number | undefined, minimum: number): number | undefined => {
  if (value !== undefined && (!Number.isSafeInteger(value) || value < minimum)) {
    throw new RangeError(`${name} must be a safe integer greater than or equal to ${minimum}.`)
  }
  return value
}

const resolveExecutionLimits = (limits?: ExecutionLimits): ResolvedExecutionLimits => ({
  timeoutMs: validateLimit("timeoutMs", limits?.timeoutMs, 1),
  maxToolCalls: validateLimit("maxToolCalls", limits?.maxToolCalls, 0),
  maxOutputBytes: validateLimit("maxOutputBytes", limits?.maxOutputBytes, 0),
})

/** Executes one Effect-native CodeMode program without constructing a reusable runtime. */
export const execute = <const Provided extends Record<string, unknown>>(
  options: ExecuteOptions<Provided>,
): Effect.Effect<Result, never, Services<Provided>> => make(options).execute(options.code)

/** Creates an Effect-native runtime over explicit, schema-described tools. */
export const make = <const Provided extends Record<string, unknown> = {}>(
  options: Options<Provided> = {},
): Runtime<Services<Provided>> => {
  const prepared = ToolRuntime.prepare((options.tools ?? {}) as Tools<Services<Provided>>)
  const limits = resolveExecutionLimits(options.limits)
  const extensions = options.extensions ?? []
  const bound = new Set(globalNames)
  for (const extension of extensions) {
    for (const name of Object.keys(extension.globals)) {
      if (bound.has(name)) throw new TypeError(`Extension "${extension.name}" global "${name}" is already defined.`)
      bound.add(name)
    }
  }
  return {
    get catalog() {
      return prepared.catalog
    },
    execute: (code) =>
      executeProgram(code, prepared, limits, options.hooks ?? {}, (ctx) => extensionGlobals(ctx, extensions)),
  }
}

