import { Effect, type Schema } from "effect"
import type { Interpreter } from "./interpreter/interpreter.js"
import { MAX_VALUE_DEPTH } from "./interpreter/limits.js"
import { invalidData, rangeError, typeError } from "./interpreter/model.js"
import {
  Arr,
  Bytes,
  Callable,
  define,
  ErrorObj,
  get,
  keys,
  Obj,
  PromiseObj,
  record,
  type Value,
  SetObj,
  URLSearchParamsObj,
  HeadersObj,
} from "./interpreter/objects.js"
import { typeofValue } from "./interpreter/references.js"

export type Json = Schema.Json

type Replacer<R> = (args: Array<Value>, holder: Obj) => Effect.Effect<Value, unknown, R>

/**
 * What `JSON.stringify` would serialize for a program value, as host JSON: `toJSON` is honored, functions and
 * `undefined` vanish, non-finite numbers become null, and everything else is copied. Two departures from JS
 * so a mistake is not a silent `{}`: an Error serializes as `{ name, message, ...own }`, and a promise throws.
 */
export const toJson = <R>(ctx: Interpreter<R>, value: Value, replacer?: Replacer<R>) =>
  walk(ctx, value, replacer, false)

/**
 * The host boundary: `toJson`, plus what a program most likely meant when a value cannot be JSON. A promise is
 * awaited, a Set crosses as an array, a URLSearchParams as its query string, a Uint8Array asks to be encoded as
 * text first, and a `__proto__` key is dropped so host code can never receive one.
 */
export const toBoundary = <R>(ctx: Interpreter<R>, value: Value) => walk(ctx, value, undefined, true)

const walk = <R>(
  ctx: Interpreter<R>,
  value: Value,
  replacer: Replacer<R> | undefined,
  boundary: boolean,
): Effect.Effect<Json | undefined, unknown, R> => {
  const stack = new Set<object>()
  const visit = (holder: Obj, key: string, depth: number): Effect.Effect<Json | undefined, unknown, R> =>
    Effect.gen(function* () {
      if (depth > MAX_VALUE_DEPTH) throw rangeError(`Value exceeds the maximum depth of ${MAX_VALUE_DEPTH}.`)
      const raw = get(holder, key)
      if (raw instanceof PromiseObj && !boundary) {
        throw invalidData(
          "JSON.stringify received an un-awaited Promise; await it first - e.g. `const result = await tools.ns.tool(...)`.",
        )
      }
      const settled = raw instanceof PromiseObj ? yield* ctx.await(raw) : raw
      const toJSON = settled instanceof Obj ? get(settled, "toJSON") : undefined
      const own = toJSON instanceof Callable ? yield* ctx.call(toJSON, settled, [key]) : settled
      const value = replacer === undefined ? own : yield* replacer([key, own], holder)
      if (value === undefined || typeofValue(value) === "function") return undefined
      if (typeof value === "number") return Number.isFinite(value) ? value : null
      if (value === null || typeof value === "string" || typeof value === "boolean") return value
      if (!(value instanceof Obj)) return {}
      if (boundary && value instanceof Bytes) {
        throw invalidData(
          "A Uint8Array cannot cross to the host; pass text instead, e.g. `new TextDecoder().decode(bytes)` or `bytes.toBase64()`.",
        )
      }
      if (boundary && value instanceof URLSearchParamsObj) return value.params.toString()
      if (value instanceof HeadersObj) return Object.fromEntries(value.headers)
      const target = boundary && value instanceof SetObj ? new Arr(ctx.builtins.Array, [...value.set]) : value
      if (stack.has(target)) throw typeError("Converting circular structure to JSON.")
      stack.add(target)
      if (target instanceof Arr) {
        const items: Array<Json> = []
        for (let index = 0; index < target.items.length; index += 1) {
          items.push((yield* visit(target, String(index), depth + 1)) ?? null)
        }
        stack.delete(target)
        return items
      }
      const copied: Record<string, Json> = {}
      // Own data property regardless of the key, so "__proto__" never reaches the Object.prototype setter.
      const put = (name: string, item: Json | undefined) => {
        if (item !== undefined)
          Object.defineProperty(copied, name, { value: item, enumerable: true, writable: true, configurable: true })
      }
      // Errors serialize as { name, message, ...own }: both may be inherited, and neither is enumerable in JS.
      if (target instanceof ErrorObj) {
        put("name", yield* visit(target, "name", depth + 1))
        put("message", yield* visit(target, "message", depth + 1))
      }
      for (const name of keys(target)) {
        if (boundary && name === "__proto__") continue
        put(name, yield* visit(target, name, depth + 1))
      }
      stack.delete(target)
      return copied
    })
  return visit(record(ctx.builtins.Object, { "": value }), "", 0)
}

/** Host JSON as program values: objects and arrays are copied, primitives pass through. */
export const fromJson = <R>(ctx: Interpreter<R>, value: Json | undefined): Value => {
  if (value === null || typeof value !== "object") return value
  if (Array.isArray(value))
    return new Arr(
      ctx.builtins.Array,
      value.map((item) => fromJson(ctx, item)),
    )
  const copied = new Obj(ctx.builtins.Object)
  for (const [key, item] of Object.entries(value)) define(copied, key, fromJson(ctx, item))
  return copied
}

export * as Extension from "./extension.js"

/**
 * Host functions a program calls directly as globals. Values crossing in either direction are converted, never
 * shared: arguments come in as copies, results go out as copies, and a function inside a result is callable the
 * same way. Extension calls are not tool calls.
 */
export type Extension = {
  readonly name: string
  readonly globals: Readonly<Record<string, Function>>
}

export const make = (options: Extension): Extension => {
  for (const [name, value] of Object.entries(options.globals)) {
    if (typeof value !== "function") {
      throw new TypeError(`Extension "${options.name}" global "${name}" must be a function.`)
    }
  }
  return { name: options.name, globals: { ...options.globals } }
}

import { Cause, Effect, Exit } from "effect"
import type { Interpreter } from "./interpreter.js"
import { primitivePrototype } from "./intrinsics.js"
import { GeneratorReturn, typeError } from "./model.js"
import {
  Callable,
  get,
  Native,
  DateObj,
  Obj,
  coerceToNumber,
  coerceToString,
  type Cursor,
  type Value,
} from "./objects.js"
import { isOpaque, typeofValue } from "./references.js"

/** IteratorClose: a consumer failure closes the iterator and wins over any close failure, except that a generator's
 * return() is a return completion, so a failing close wins over it, as after `break`. */
export const preserveConsumerError = <A, R>(
  close: Cursor<R>["close"],
  effect: Effect.Effect<A, unknown, R>,
): Effect.Effect<A, unknown, R> =>
  Effect.flatMap(Effect.exit(effect), (exit) => {
    if (Exit.isSuccess(exit)) return Effect.succeed(exit.value)
    return Effect.flatMap(Effect.exit(close), (closed) => {
      if (!Exit.isSuccess(closed) && Cause.squash(exit.cause) instanceof GeneratorReturn) {
        return Effect.failCause(closed.cause)
      }
      return Effect.failCause(exit.cause)
    })
  })

export type Hint = "number" | "string" | "default"

/**
 * ToPrimitive: calls `valueOf`/`toString` in hint order and returns the first primitive result. Dates treat the
 * default hint as "string", like their `Symbol.toPrimitive`. Opaque values (functions, promises, generators, tool
 * references) pass through unchanged so callers reject or describe them in their built-in form.
 */
export const toPrimitive = <R>(ctx: Interpreter<R>, value: Value, hint: Hint): Effect.Effect<Value, unknown, R> => {
  if (!(value instanceof Obj) || isOpaque(value)) return Effect.succeed(value)
  const asString = hint === "string" || (hint === "default" && value instanceof DateObj)
  const order = asString ? ["toString", "valueOf"] : ["valueOf", "toString"]
  return Effect.gen(function* () {
    for (const method of order) {
      const callable = get(value, method)
      if (!(callable instanceof Callable)) continue
      const result = yield* ctx.call(callable, value, [])
      if (result === null || (typeof result !== "object" && typeof result !== "function")) return result
    }
    throw typeError("Cannot convert object to primitive value.")
  })
}

/** Invoke(value, name): calls the method the value would find through its prototype. */
export const invoke = <R>(ctx: Interpreter<R>, value: Value, name: string, label: string) => {
  const target = value instanceof Obj ? value : primitivePrototype(ctx.builtins, value)
  if (target === undefined) throw typeError(`${label} called on null or undefined.`)
  return ctx.call(get(target, name), value, [])
}

export const toPrimitiveString = <R>(ctx: Interpreter<R>, value: Value) =>
  Effect.map(toPrimitive(ctx, value, "string"), coerceToString)

export const toPrimitiveNumber = <R>(ctx: Interpreter<R>, value: Value) =>
  Effect.map(toPrimitive(ctx, value, "number"), coerceToNumber)

/**
 * Runs a native body on its arguments after ToPrimitive, in order, with one hint for all positions or one per
 * position. Primitive arguments skip the Effect entirely.
 */
export const withPrimitives = <R>(
  ctx: Interpreter<R>,
  hints: Hint | ReadonlyArray<Hint>,
  values: Array<Value>,
  body: (primitives: Array<Value>) => Value | Effect.Effect<Value, unknown, R>,
): Value | Effect.Effect<Value, unknown, R> => {
  if (!values.some((value) => value instanceof Obj)) return body(values)
  return Effect.flatMap(
    Effect.forEach(values, (value, index) =>
      toPrimitive(ctx, value, typeof hints === "string" ? hints : hints[index]!),
    ),
    (primitives) => {
      const result = body(primitives)
      return Effect.isEffect(result) ? result : Effect.succeed(result)
    },
  )
}

// The single acceptance list for callbacks: collections, sort, string replacers,
// Array.from mappers, and promise reactions all admit exactly these callables.
// Admission means dispatchable, not necessarily invocable: new-requiring
// constructors pass the gate and throw a TypeError on call, like JS.
export const isSupportedCallback = (value: Value): value is Callable =>
  value instanceof Callable && !(value instanceof Native && !value.callback)

export const applyCollectionCallback = <R>(
  ctx: Interpreter<R>,
  callback: Value,
  name: string,
): ((args: Array<Value>, thisValue?: Value) => Effect.Effect<Value, unknown, R>) => {
  if (!isSupportedCallback(callback)) {
    if (typeofValue(callback) === "function") {
      throw typeError(
        `${name} cannot use this callable as a callback; wrap it in an arrow function, e.g. (value) => tools.ns.tool(value).`,
      )
    }
    throw typeError(`${name} expects a function callback.`)
  }
  return (callbackArgs, thisValue) => ctx.call(callback, thisValue, callbackArgs)
}

import { Effect } from "effect"
import type { Diagnostic } from "../codemode.js"
import { ToolError } from "../tool-error.js"
import { ToolRuntimeError } from "../tool-runtime.js"
import { type AstNode, formatLocation, PendingThrow, Throw, sourceLocation, typeError } from "./model.js"
import { containsRuntimeReference } from "./references.js"
import { createErrorValue, type ErrorType, isErrorType } from "./intrinsics.js"
import { constructor, methods, prototypeFrom, receiver } from "./native.js"
import {
  type Callable,
  define,
  get,
  has,
  hidden,
  type Native,
  Arr,
  ErrorObj,
  Obj,
  coerceToString,
  type Value,
} from "./objects.js"
import type { Interpreter } from "./interpreter.js"
import { toPrimitiveString } from "./callback.js"
import { formatValue } from "../stdlib/console.js"

export const normalizeError = (error: unknown): Diagnostic => {
  if (error instanceof PendingThrow) {
    return {
      kind: error.kind,
      message: `${error.type}: ${error.message}${formatLocation(error.node)}`,
      ...(error.node?.loc ? { location: sourceLocation(error.node) } : {}),
      ...(error.suggestions ? { suggestions: error.suggestions } : {}),
    }
  }

  if (error instanceof ToolRuntimeError) {
    return {
      kind: error.kind,
      message: error.message,
      ...(error.suggestions.length > 0 ? { suggestions: error.suggestions } : {}),
    }
  }

  if (error instanceof ToolError) {
    return { kind: "ToolFailure", message: error.message }
  }

  if (error instanceof Throw) {
    const value = error.value
    if (value instanceof ErrorObj) {
      return value.host ? normalizeError(value.host) : { kind: "ExecutionFailure", message: errorToString(value) }
    }
    let message: string
    if (containsRuntimeReference(value)) {
      // Never expose runtime reference internals through thrown values.
      message = "a non-data value"
    } else if (typeof value === "string") {
      message = value
    } else {
      message = formatValue(value)
    }
    return { kind: "ExecutionFailure", message: `Uncaught: ${message}` }
  }

  if (error instanceof RangeError && /call stack|recursion/i.test(error.message)) {
    return {
      kind: "ExecutionFailure",
      message: "Execution exceeded the maximum nesting depth.",
    }
  }

  if (error instanceof Error) {
    return {
      kind: error.name === "SyntaxError" ? "ParseError" : "ExecutionFailure",
      message: error.message,
    }
  }

  return {
    kind: "ExecutionFailure",
    message: String(error),
  }
}

/**
 * Gives a failure the source location of the expression that raised it, keeping the first one attached. Host errors
 * that escape a built-in become the equivalent program error here.
 */
export const locate = (error: unknown, node?: AstNode): unknown => {
  if (error instanceof PendingThrow) {
    if (error.node === undefined && node) error.node = node
    return error
  }
  if (error instanceof Error && !(error instanceof ToolError) && !(error instanceof ToolRuntimeError)) {
    return new PendingThrow(isErrorType(error.name) ? error.name : "Error", error.message, node)
  }
  return error
}

/** The program value a handler receives for a failure; one failure always yields the same value. */
export const materialize = <R>(ctx: Interpreter<R>, thrown: unknown): Value => {
  if (thrown instanceof Throw) return thrown.value
  const builtins = ctx.builtins
  if (thrown instanceof PendingThrow) {
    if (thrown.value === undefined) {
      thrown.value = createErrorValue(builtins[thrown.type], thrown.message)
      thrown.value.host = thrown
    }
    return thrown.value
  }
  const type = thrown instanceof Error && isErrorType(thrown.name) ? thrown.name : "Error"
  return createErrorValue(builtins[type], normalizeError(thrown).message)
}

/** Error.prototype.toString: `name: message`, omitting whichever side is empty. */
const errorToString = (self: Obj): string => {
  const name = get(self, "name")
  const message = get(self, "message")
  const shownName = name === undefined ? "Error" : coerceToString(name)
  const shownMessage = message === undefined ? "" : coerceToString(message)
  if (shownMessage === "") return shownName
  if (shownName === "") return shownMessage
  return `${shownName}: ${shownMessage}`
}

export const createAggregateErrorValue = <R>(
  ctx: Interpreter<R>,
  errors: Array<Value>,
  message: string,
  proto: Obj = ctx.builtins.AggregateError,
) => {
  const value = createErrorValue(proto, message)
  define(value, "errors", new Arr(ctx.builtins.Array, errors), { ...hidden })
  return value
}

const constructAggregateErrorValue = <R>(
  ctx: Interpreter<R>,
  args: Array<Value>,
  proto: Obj,
): Effect.Effect<ErrorObj, unknown, R> =>
  Effect.gen(function* () {
    const message = args[1] === undefined ? "" : yield* toPrimitiveString(ctx, args[1])
    const cursor = yield* ctx.iterate(args[0])
    if (cursor === undefined) throw typeError("new AggregateError(...) expects a synchronous iterable of errors.")
    const errors: Array<Value> = []
    while (true) {
      const step = yield* cursor.next
      if (step.done) return createAggregateErrorValue(ctx, errors, message, proto)
      errors.push(step.value)
    }
  })

/** An error constructor such as `Error` or `TypeError`; callable with or without `new`, like JS. */
export const errorGlobal = <R>(type: ErrorType, ctx: Interpreter<R>) => {
  const builtins = ctx.builtins
  const prototype = builtins[type]
  const construct = (args: Array<Value>, newTarget: Callable) => {
    const proto = prototypeFrom(newTarget, prototype)
    const created =
      type === "AggregateError"
        ? constructAggregateErrorValue(ctx, args, proto)
        : Effect.map(args[0] === undefined ? Effect.undefined : toPrimitiveString(ctx, args[0]), (message) =>
            createErrorValue(proto, message),
          )
    // ES2022 `new Error(message, { cause })`: installed only when the options object has the property at all.
    const options = args[type === "AggregateError" ? 2 : 1]
    if (!(options instanceof Obj) || !has(options, "cause")) return created
    return Effect.map(created, (value) => {
      define(value, "cause", get(options, "cause"), hidden)
      return value
    })
  }
  const ctor: Native<R> = constructor<R>(builtins, prototype, {
    name: type,
    length: type === "AggregateError" ? 2 : 1,
    call: (_, args) => construct(args, ctor),
    construct,
  })
  if (type === "Error") {
    methods(builtins, prototype, [
      ["toString", 0, (thisValue) => errorToString(receiver(Obj, thisValue, "Error.prototype.toString"))],
    ])
    methods(builtins, ctor, [["isError", 1, (_, args) => args[0] instanceof ErrorObj]])
    return ctor
  }
  // Derived constructors extend Error itself, so its statics are inherited. The globals table creates Error first.
  ctor.proto = get(builtins.Error, "constructor") as Obj
  return ctor
}

