        const items = target.items
        const length = items.length
        const holeCount = Array.from({ length }, (_, index) => Object.hasOwn(items, index)).filter((o) => !o).length
        const itemCount = length - holeCount
        return Effect.map(sortArray(ctx, items, args[0], "Array.sort"), (sorted) => {
          sorted.slice(0, itemCount).forEach((item, index) => {
            items[index] = item
          })
          Array.from({ length: holeCount }, (_, index) => itemCount + index).forEach((index) => {
            delete items[index]
          })
          return target
        })
      },
    ],
    [
      "toSorted",
      1,
      (thisValue, args) =>
        Effect.map(sortArray(ctx, self(thisValue, "toSorted").items, args[0], "Array.toSorted"), wrap),
    ],
    ["toReversed", 0, (thisValue) => wrap([...self(thisValue, "toReversed").items].reverse())],
    [
      "with",
      2,
      (thisValue, args) => {
        const target = self(thisValue, "with").items
        const index = optNumber(args[0]) ?? 0
        const resolved = index < 0 ? target.length + index : index
        if (resolved < 0 || resolved >= target.length) throw rangeError("Array.with index is out of range.")
        const copied = [...target]
        copied[resolved] = args[1]
        return wrap(copied)
      },
    ],
    [
      "push",
      1,
      (thisValue, args) => {
        const target = mutable(self(thisValue, "push"), args.length)
        // Validate all insertions before mutating to avoid partial cyclic updates.
        for (const item of args) rejectCircularInsertion(target, item, "Array.push result")
        return target.items.push(...args)
      },
    ],
    [
      "unshift",
      1,
      (thisValue, args) => {
        const target = mutable(self(thisValue, "unshift"), args.length)
        for (const item of args) rejectCircularInsertion(target, item, "Array.unshift result")
        return target.items.unshift(...args)
      },
    ],
    ["pop", 0, (thisValue) => mutable(self(thisValue, "pop"), -1).items.pop()],
    ["shift", 0, (thisValue) => mutable(self(thisValue, "shift"), -1).items.shift()],
    [
      "splice",
      2,
      (thisValue, args) => {
        const target = self(thisValue, "splice")
        const length = target.items.length
        const start = optNumber(args[0]) ?? 0
        const from = start < 0 ? Math.max(length + start, 0) : Math.min(start, length)
        const deleteCount =
          args.length === 1 ? length - from : Math.min(Math.max(optNumber(args[1]) ?? 0, 0), length - from)
        const inserted = args.slice(2)
        for (const item of inserted) rejectCircularInsertion(target, item, "Array.splice result")
        mutable(target, inserted.length - deleteCount)
        return wrap(target.items.splice(from, deleteCount, ...inserted))
      },
    ],
    [
      "toSpliced",
      2,
      (thisValue, args) => {
        const copied = [...self(thisValue, "toSpliced").items]
        if (args.length === 0) return wrap(copied)
        const start = optNumber(args[0]) ?? 0
        if (args.length === 1) copied.splice(start)
        else copied.splice(start, optNumber(args[1]) ?? 0, ...args.slice(2))
        return wrap(copied)
      },
    ],
    [
      "fill",
      1,
      (thisValue, args) => {
        const target = mutable(self(thisValue, "fill"))
        rejectCircularInsertion(target, args[0], "Array.fill result")
        target.items.fill(args[0], optNumber(args[1]), optNumber(args[2]))
        return target
      },
    ],
    [
      "copyWithin",
      2,
      (thisValue, args) => {
        const target = mutable(self(thisValue, "copyWithin"))
        target.items.copyWithin(optNumber(args[0]) ?? 0, optNumber(args[1]) ?? 0, optNumber(args[2]))
        return target
      },
    ],
    [
      "toLocaleString",
      0,
      (thisValue) =>
        Effect.map(
          Effect.forEach(self(thisValue, "toLocaleString").items, (item) =>
            item === null || item === undefined
              ? Effect.succeed("")
              : Effect.map(invoke(ctx, item, "toLocaleString", "Array.prototype.toLocaleString"), coerceToString),
          ),
          (parts) => parts.join(","),
        ),
    ],
    ["keys", 0, (thisValue) => hostIterator(builtins, self(thisValue, "keys").items.keys())],
    ["values", 0, (thisValue) => hostIterator(builtins, self(thisValue, "values").items.values())],
    [
      "entries",
      0,
      (thisValue) =>
        hostIterator(
          builtins,
          self(thisValue, "entries")
            .items.entries()
            .map(([index, item]) => wrap([index, item])),
        ),
    ],
    [
      "flatMap",
      1,
      (thisValue, args) => {
        const target = self(thisValue, "flatMap")
        const apply = applyCollectionCallback(ctx, args[0], "Array.flatMap")
        return Effect.gen(function* () {
          const length = target.items.length
          const values: Array<Value> = []
          for (let index = 0; index < length; index += 1) {
            if (!(index in target.items)) continue
            const mapped = yield* apply([target.items[index], index, target], args[1])
            if (mapped instanceof Arr) values.push(...mapped.items)
            else values.push(mapped)
          }
          return wrap(values)
        })
      },
    ],
    ...callbackMethods(ctx, "Array", self, (target) => target.items, wrap),
  ])
  define(proto, IteratorSymbol, get(proto, "values"), hidden)
  return array
}

/**
 * The callback methods Array and Uint8Array share. They fix the iteration length while reading existing elements
 * live; `wrap` builds the collection `map` and `filter` return.
 */
export const callbackMethods = <R, T extends Obj>(
  ctx: Interpreter<R>,
  label: string,
  self: (thisValue: Value, name: string) => T,
  elements: (target: T) => ArrayLike<Value>,
  wrap: (values: Array<Value>) => Value,
): Array<Method> => {
  const iterate = (
    name: string,
    length: number,
    body: (
      target: ArrayLike<Value>,
      receiver: T,
      apply: (args: Array<Value>) => Effect.Effect<Value, unknown, R>,
      args: Array<Value>,
    ) => Effect.Effect<Value, unknown, R>,
  ): Method => [
    name,
    length,
    (thisValue, args) => {
      const target = self(thisValue, name)
      const call = applyCollectionCallback(ctx, args[0], `${label}.${name}`)
      // reduce and reduceRight take an initial value where the others take a thisArg.
      const thisArg = name.startsWith("reduce") ? undefined : args[1]
      return body(elements(target), target, (callbackArgs) => call(callbackArgs, thisArg), args)
    },
  ]
  return [
    iterate("map", 1, (target, receiver, apply) =>
      Effect.gen(function* () {
        const length = target.length
        const values: Array<Value> = []
        values.length = length
        for (let index = 0; index < length; index += 1) {
          if (!(index in target)) continue
          values[index] = yield* apply([target[index], index, receiver])
        }
        return wrap(values)
      }),
    ),
    iterate("filter", 1, (target, receiver, apply) =>
      Effect.gen(function* () {
        const length = target.length
        const values: Array<Value> = []
        for (let index = 0; index < length; index += 1) {
          if (!(index in target)) continue
          const item = target[index]
          if (yield* apply([item, index, receiver])) values.push(item)
        }
        return wrap(values)
      }),
    ),
    iterate("find", 1, (target, receiver, apply) =>
      Effect.gen(function* () {
        const length = target.length
        for (let index = 0; index < length; index += 1) {
          const item = target[index]
          if (yield* apply([item, index, receiver])) return item
        }
        return undefined
      }),
    ),
    iterate("findIndex", 1, (target, receiver, apply) =>
      Effect.gen(function* () {
        const length = target.length
        for (let index = 0; index < length; index += 1) {
          if (yield* apply([target[index], index, receiver])) return index
        }
        return -1
      }),
    ),
    iterate("findLast", 1, (target, receiver, apply) =>
      Effect.gen(function* () {
        for (let index = target.length - 1; index >= 0; index -= 1) {
          const item = target[index]
          if (yield* apply([item, index, receiver])) return item
        }
        return undefined
      }),
    ),
    iterate("findLastIndex", 1, (target, receiver, apply) =>
      Effect.gen(function* () {
        for (let index = target.length - 1; index >= 0; index -= 1) {
          if (yield* apply([target[index], index, receiver])) return index
        }
        return -1
      }),
    ),
    iterate("some", 1, (target, receiver, apply) =>
      Effect.gen(function* () {
        const length = target.length
        for (let index = 0; index < length; index += 1) {
          if (!(index in target)) continue
          if (yield* apply([target[index], index, receiver])) return true
        }
        return false
      }),
    ),
    iterate("every", 1, (target, receiver, apply) =>
      Effect.gen(function* () {
        const length = target.length
        for (let index = 0; index < length; index += 1) {
          if (!(index in target)) continue
          if (!(yield* apply([target[index], index, receiver]))) return false
        }
        return true
      }),
    ),
    iterate("forEach", 1, (target, receiver, apply) =>
      Effect.gen(function* () {
        const length = target.length
        for (let index = 0; index < length; index += 1) {
          if (index in target) yield* apply([target[index], index, receiver])
        }
        return undefined
      }),
    ),
    iterate("reduce", 1, (target, receiver, apply, args) =>
      Effect.gen(function* () {
        const length = target.length
        let start = 0
        let accumulator = args[1]
        if (args.length < 2) {
          while (start < length && !(start in target)) start += 1
          if (start === length) {
            throw typeError(`${label}.reduce of an empty array with no initial value.`)
          }
          accumulator = target[start]
          start += 1
        }
        for (let index = start; index < length; index += 1) {
          if (!(index in target)) continue
          accumulator = yield* apply([accumulator, target[index], index, receiver])
        }
        return accumulator
      }),
    ),
    iterate("reduceRight", 1, (target, receiver, apply, args) =>
      Effect.gen(function* () {
        let start = target.length - 1
        let accumulator = args[1]
        if (args.length < 2) {
          while (start >= 0 && !(start in target)) start -= 1
          if (start < 0) {
            throw typeError(`${label}.reduceRight of an empty array with no initial value.`)
          }
          accumulator = target[start]
          start -= 1
        }
        for (let index = start; index >= 0; index -= 1) {
          if (!(index in target)) continue
          accumulator = yield* apply([accumulator, target[index], index, receiver])
        }
        return accumulator
      }),
    ),
  ]
}

import { Effect } from "effect"
import { checkArrayLength, checkStringLength } from "../interpreter/limits.js"
import { constructor, methods, prototypeFrom, receiver, requiresNew } from "../interpreter/native.js"
import { IteratorSymbol, rangeError, syntaxError, typeError } from "../interpreter/model.js"
import {
  define,
  defineAccessor,
  get,
  hidden,
  Arr,
  Bytes,
  hostIterator,
  Obj,
  coerceToInteger,
  coerceToNumber,
  coerceToString,
  type Value,
} from "../interpreter/objects.js"
import { describeValue } from "../interpreter/references.js"
import type { Interpreter } from "../interpreter/interpreter.js"
import { callbackMethods, sortArray } from "./array.js"

/** The bytes a Uint8Array, array, or other iterable of numbers describes; the host array clamps each value. */
const collectBytes = <R>(ctx: Interpreter<R>, source: Value, name: string): Effect.Effect<Uint8Array, unknown, R> => {
  if (source instanceof Bytes) return Effect.succeed(new Uint8Array(source.bytes))
  return Effect.gen(function* () {
    const cursor = yield* ctx.iterate(source)
    if (cursor === undefined) {
      throw typeError(
        `${name} expects a Uint8Array, an array, or an iterable of numbers, received ${describeValue(source)}.`,
      )
    }
    const values: Array<number> = []
    while (true) {
      const step = yield* cursor.next
      if (step.done) return Uint8Array.from(values)
      values.push(coerceToNumber(step.value))
      checkArrayLength(values.length)
    }
  })
}

const constructBytes = <R>(ctx: Interpreter<R>, args: Array<Value>, proto: Obj) => {
  const source = args[0]
  if (source !== null && typeof source === "object") {
    return Effect.map(collectBytes(ctx, source, "new Uint8Array(...)"), (bytes) => new Bytes(proto, bytes))
  }
  const length = source === undefined ? 0 : coerceToNumber(source)
  if (!Number.isInteger(length) || length < 0) throw rangeError(`Invalid typed array length: ${coerceToString(source)}`)
  checkArrayLength(length)
  return Effect.succeed(new Bytes(proto, new Uint8Array(length)))
}

export const uint8ArrayGlobal = <R>(ctx: Interpreter<R>) => {
  const builtins = ctx.builtins
  const proto = builtins.Uint8Array
  const wrap = (bytes: Uint8Array) => new Bytes(proto, bytes)
  const uint8Array = constructor<R>(builtins, proto, {
    name: "Uint8Array",
    length: 3,
    call: requiresNew("Uint8Array"),
    construct: (args, newTarget) => constructBytes(ctx, args, prototypeFrom(newTarget, proto)),
  })
  const decode = (name: string, args: Array<Value>, from: (text: string) => Uint8Array) => {
    if (typeof args[0] !== "string") throw typeError(`Uint8Array.${name} expects a string.`)
    try {
      return wrap(from(args[0]))
    } catch {
      throw syntaxError(`Uint8Array.${name}: the string is not valid ${name === "fromHex" ? "hex" : "base64"}.`)
    }
  }
  methods(builtins, uint8Array, [
    ["from", 1, (_, args) => Effect.map(collectBytes(ctx, args[0], "Uint8Array.from"), wrap)],
    ["of", 0, (_, args) => wrap(Uint8Array.from(args, coerceToNumber))],
    ["fromBase64", 1, (_, args) => decode("fromBase64", args, (text) => Uint8Array.fromBase64(text))],
    ["fromHex", 1, (_, args) => decode("fromHex", args, (text) => Uint8Array.fromHex(text))],
  ])

  const self = (thisValue: Value, name: string) => receiver(Bytes, thisValue, `Uint8Array.prototype.${name}`)
  const optNumber = (value: Value): number | undefined => (value === undefined ? undefined : coerceToInteger(value))
  const wrapAll = (items: Array<Value>) => new Arr(builtins.Array, items)
  defineAccessor(proto, "length", (thisValue) => self(thisValue, "length").bytes.length)
  methods(builtins, proto, [
    ["at", 1, (thisValue, args) => self(thisValue, "at").bytes.at(optNumber(args[0]) ?? 0)],
    [
      "slice",
      2,
      (thisValue, args) => wrap(self(thisValue, "slice").bytes.slice(optNumber(args[0]), optNumber(args[1]))),
    ],
    // A view on the same bytes, as in JS: writes through one are visible through the other.
    [
      "subarray",
      2,
      (thisValue, args) => wrap(self(thisValue, "subarray").bytes.subarray(optNumber(args[0]), optNumber(args[1]))),
    ],
    [
      "set",
      1,
      (thisValue, args) => {
        const target = self(thisValue, "set")
        const offset = optNumber(args[1]) ?? 0
        return Effect.map(collectBytes(ctx, args[0], "Uint8Array.set"), (source) => {
          if (!Number.isInteger(offset) || offset < 0 || source.length + offset > target.bytes.length) {
            throw rangeError("Uint8Array.set: the source does not fit at that offset.")
          }
          target.bytes.set(source, offset)
          return undefined
        })
      },
    ],
    [
      "fill",
      1,
      (thisValue, args) => {
        const target = self(thisValue, "fill")
        target.bytes.fill(coerceToNumber(args[0]), optNumber(args[1]), optNumber(args[2]))
        return target
      },
    ],
    [
      "reverse",
      0,
      (thisValue) => {
        const target = self(thisValue, "reverse")
        target.bytes.reverse()
        return target
      },
    ],
    [
      "sort",
      1,
      (thisValue, args) => {
        const target = self(thisValue, "sort")
        // Without a comparator, typed arrays sort numerically rather than by string.
        if (args[0] === undefined) {
          target.bytes.sort()
          return target
        }
        return Effect.map(sortArray(ctx, [...target.bytes], args[0], "Uint8Array.sort"), (sorted) => {
          target.bytes.set(Uint8Array.from(sorted, coerceToNumber))
          return target
        })
      },
    ],
    [
      "indexOf",
      1,
      (thisValue, args) => self(thisValue, "indexOf").bytes.indexOf(coerceToNumber(args[0]), optNumber(args[1])),
    ],
    [
      "lastIndexOf",
      1,
      (thisValue, args) => {
        const target = self(thisValue, "lastIndexOf").bytes
        return args.length < 2
          ? target.lastIndexOf(coerceToNumber(args[0]))
          : target.lastIndexOf(coerceToNumber(args[0]), optNumber(args[1]))
      },
    ],
    [
      "includes",
      1,
      (thisValue, args) => self(thisValue, "includes").bytes.includes(coerceToNumber(args[0]), optNumber(args[1])),
    ],
    [
      "join",
      1,
      (thisValue, args) => {
        const joined = self(thisValue, "join").bytes.join(args[0] === undefined ? "," : coerceToString(args[0]))
        checkStringLength(joined.length)
        return joined
      },
    ],
    ["toString", 0, (thisValue) => self(thisValue, "toString").bytes.join(",")],
    ["toBase64", 0, (thisValue) => self(thisValue, "toBase64").bytes.toBase64()],
    ["toHex", 0, (thisValue) => self(thisValue, "toHex").bytes.toHex()],
    ["keys", 0, (thisValue) => hostIterator(builtins, self(thisValue, "keys").bytes.keys())],
    ["values", 0, (thisValue) => hostIterator(builtins, self(thisValue, "values").bytes.values())],
    [
      "entries",
      0,
      (thisValue) =>
        hostIterator(
          builtins,
          self(thisValue, "entries")
            .bytes.entries()
            .map(([index, byte]) => wrapAll([index, byte])),
        ),
    ],
    ...callbackMethods(
      ctx,
      "Uint8Array",
      self,
      (target) => target.bytes,
      (values) => wrap(Uint8Array.from(values, coerceToNumber)),
    ),
  ])
  define(proto, IteratorSymbol, get(proto, "values"), hidden)
  return uint8Array
}

export const textEncoderGlobal = <R>(ctx: Interpreter<R>) => {
  const builtins = ctx.builtins
  const proto = builtins.TextEncoder
  const encoder = new TextEncoder()
  defineAccessor(proto, "encoding", () => "utf-8")
  methods(builtins, proto, [
    ["encode", 0, (_, args) => new Bytes(builtins.Uint8Array, encoder.encode(coerceToString(args[0] ?? "")))],
  ])
  return constructor<R>(builtins, proto, {
    name: "TextEncoder",
    call: requiresNew("TextEncoder"),
    construct: (_, newTarget) => Effect.succeed(new Obj(prototypeFrom(newTarget, proto))),
  })
}

/** A `TextDecoder` holding the host decoder its label and options configured. */
export class TextDecoderObj extends Obj {
  constructor(
    proto: Obj,
    readonly decoder: TextDecoder,
  ) {
    super(proto)
  }
}

// The WHATWG labels for UTF-8, the only encoding CodeMode decodes.
const utf8Labels = new Set(["unicode-1-1-utf-8", "unicode11utf8", "unicode20utf8", "utf-8", "utf8", "x-unicode20utf8"])

export const textDecoderGlobal = <R>(ctx: Interpreter<R>) => {
  const builtins = ctx.builtins
  const proto = builtins.TextDecoder
  const self = (thisValue: Value, name: string) => receiver(TextDecoderObj, thisValue, `TextDecoder.prototype.${name}`)
  defineAccessor(proto, "encoding", (thisValue) => self(thisValue, "encoding").decoder.encoding)
  defineAccessor(proto, "fatal", (thisValue) => self(thisValue, "fatal").decoder.fatal)
  defineAccessor(proto, "ignoreBOM", (thisValue) => self(thisValue, "ignoreBOM").decoder.ignoreBOM)
  methods(builtins, proto, [
    [
      "decode",
      0,
      (thisValue, args) => {
        const decoder = self(thisValue, "decode").decoder
        if (args[0] === undefined) return ""
        if (!(args[0] instanceof Bytes)) {
          throw typeError(`TextDecoder.decode expects a Uint8Array, received ${describeValue(args[0])}.`)
        }
        try {
