          throw typeError(`new WeakSet(...) expects a synchronous iterable, received ${describeValue(args[0])}.`)
        }
        while (true) {
          const step = yield* cursor.next
          if (step.done) return target
          yield* preserveConsumerError(
            cursor.close,
            Effect.sync(() => {
