  const raw = args[0]
  if (name === "Boolean") return Boolean(raw)
  if (name === "parseInt") {
    return withPrimitives(ctx, ["string", "number"], [raw, args[1]], ([text, radix]) =>
      parseInt(coerceToString(text), coerceToNumber(radix)),
    )
