  test("new Error(message, { cause }) installs a non-enumerable cause only when the option is present", async () => {
    expect(
      await value(`
        const inner = new Error("root")
        const e = new TypeError("m", { cause: inner })
        const agg = new AggregateError([], "a", { cause: 3 })
