          attempt(() => { a[0] = 9 }),
          attempt(() => { a[5] = 9 }),
          attempt(() => { a.length = 0 }),
          attempt(() => a.pop()),
          attempt(() => a.sort()),
          attempt(() => a.reverse()),
          attempt(() => a.fill(0)),
          attempt(() => a.copyWithin(0, 1)),
          attempt(() => a.splice(0, 1)),
