      "TypeError: Cannot delete property '1'.",
      "TypeError: Cannot assign to read only property '0'.",
      "TypeError: Cannot assign to read only property '0'.",
      "TypeError: Cannot assign to read only property '0'.",
      "TypeError: Cannot assign to read only property '0'.",
      "TypeError: Cannot delete property '1'.",
      "TypeError: Cannot add property 2, object is not extensible.",
