          has: () => { throw new Error("has should not be called") },
          keys: () => [1],
        }
        return [
          set.isSubsetOf(map), set.isSupersetOf(map), set.isDisjointFrom(map),
          set.isSubsetOf(hasOnly), set.isSupersetOf(keysOnly), set.isDisjointFrom(hasOnly),
        ]
      `),
