          for (name in headerDict) {
            headers.append(name, headerDict[name])
            assert_equals(headers.get(name), String(headerDict[name]), "name: " + name + " has value: " + headerDict[name])
          }
        }, "Check append method")
        test(function() {
          var headers = new Headers()
          for (name in headerDict) {
            headers.set(name, headerDict[name])
            assert_equals(headers.get(name), String(headerDict[name]), "name: " + name + " has value: " + headerDict[name])
          }
        }, "Check set method")
        test(function() {
          var headers = new Headers(headerDict)
          for (name in headerDict) assert_true(headers.has(name), "headers has name " + name)
          assert_false(headers.has("nameNotInHeaders"), "headers do not have header: nameNotInHeaders")
        }, "Check has method")
        test(function() {
          var headers = new Headers(headerDict)
          for (name in headerDict) {
            assert_true(headers.has(name), "headers have a header: " + name)
            headers.delete(name)
            assert_true(!headers.has(name), "headers do not have anymore a header: " + name)
          }
        }, "Check delete method")
        test(function() {
          var headers = new Headers(headerDict)
          for (name in headerDict) assert_equals(headers.get(name), String(headerDict[name]), "name: " + name + " has value: " + headerDict[name])
          assert_equals(headers.get("nameNotInHeaders"), null, "header: nameNotInHeaders has no value")
        }, "Check get method")
        var headerEntriesDict = {"name1": "value1", "Name2": "value2", "name": "value3", "content-Type": "value4", "Content-Typ": "value5", "Content-Types": "value6"}
        var sortedHeaderDict = {}
        var headerValues = []
        var sortedHeaderKeys = Object.keys(headerEntriesDict).map(function(value) {
          sortedHeaderDict[value.toLowerCase()] = headerEntriesDict[value]
          headerValues.push(headerEntriesDict[value])
          return value.toLowerCase()
        }).sort()
        test(function() {
          var headers = new Headers(headerEntriesDict)
          var actual = headers.keys()
          sortedHeaderKeys.forEach(function(key) {
            const entry = actual.next()
            assert_false(entry.done)
            assert_equals(entry.value, key)
          })
          assert_true(actual.next().done)
          assert_true(actual.next().done)
          for (const key of headers.keys()) assert_true(sortedHeaderKeys.indexOf(key) != -1)
        }, "Check keys method")
        test(function() {
          var headers = new Headers(headerEntriesDict)
          var actual = headers.values()
          sortedHeaderKeys.forEach(function(key) {
            const entry = actual.next()
            assert_false(entry.done)
            assert_equals(entry.value, sortedHeaderDict[key])
          })
          assert_true(actual.next().done)
          assert_true(actual.next().done)
          for (const value of headers.values()) assert_true(headerValues.indexOf(value) != -1)
        }, "Check values method")
        test(function() {
          var headers = new Headers(headerEntriesDict)
          var actual = headers.entries()
          sortedHeaderKeys.forEach(function(key) {
            const entry = actual.next()
            assert_false(entry.done)
            assert_equals(entry.value[0], key)
            assert_equals(entry.value[1], sortedHeaderDict[key])
          })
          assert_true(actual.next().done)
          assert_true(actual.next().done)
          for (const entry of headers.entries()) assert_equals(entry[1], sortedHeaderDict[entry[0]])
        }, "Check entries method")
        test(function() {
          var headers = new Headers(headerEntriesDict)
          var actual = headers[Symbol.iterator]()
          sortedHeaderKeys.forEach(function(key) {
            const entry = actual.next()
            assert_false(entry.done)
            assert_equals(entry.value[0], key)
            assert_equals(entry.value[1], sortedHeaderDict[key])
          })
          assert_true(actual.next().done)
          assert_true(actual.next().done)
        }, "Check Symbol.iterator method")
        test(function() {
          var headers = new Headers(headerEntriesDict)
          var reference = sortedHeaderKeys[Symbol.iterator]()
          headers.forEach(function(value, key, container) {
            assert_equals(headers, container)
            const entry = reference.next()
            assert_false(entry.done)
            assert_equals(key, entry.value)
            assert_equals(value, sortedHeaderDict[entry.value])
          })
          assert_true(reference.next().done)
        }, "Check forEach method")
        test(() => {
          const headers = new Headers({"foo": "2", "baz": "1", "BAR": "0"})
          const actualKeys = []
          const actualValues = []
          for (const [header, value] of headers) {
            actualKeys.push(header)
            actualValues.push(value)
            headers.delete("foo")
          }
          assert_array_equals(actualKeys, ["bar", "baz"])
          assert_array_equals(actualValues, ["0", "1"])
        }, "Iteration skips elements removed while iterating")
        test(() => {
          const headers = new Headers({"foo": "2", "baz": "1", "BAR": "0", "quux": "3"})
          const actualKeys = []
          const actualValues = []
          for (const [header, value] of headers) {
            actualKeys.push(header)
            actualValues.push(value)
            if (header === "baz") headers.delete("bar")
          }
          assert_array_equals(actualKeys, ["bar", "baz", "quux"])
          assert_array_equals(actualValues, ["0", "1", "3"])
        }, "Removing elements already iterated over causes an element to be skipped during iteration")
        test(() => {
          const headers = new Headers({"foo": "2", "baz": "1", "BAR": "0", "quux": "3"})
          const actualKeys = []
          const actualValues = []
          for (const [header, value] of headers) {
            actualKeys.push(header)
            actualValues.push(value)
            if (header === "baz") headers.append("X-yZ", "4")
          }
          assert_array_equals(actualKeys, ["bar", "baz", "foo", "quux", "x-yz"])
          assert_array_equals(actualValues, ["0", "1", "2", "3", "4"])
        }, "Appending a value pair during iteration causes it to be reached during iteration")
        test(() => {
          const headers = new Headers({"foo": "2", "baz": "1", "BAR": "0", "quux": "3"})
          const actualKeys = []
          const actualValues = []
          for (const [header, value] of headers) {
            actualKeys.push(header)
            actualValues.push(value)
            if (header === "baz") headers.append("abc", "-1")
          }
          assert_array_equals(actualKeys, ["bar", "baz", "baz", "foo", "quux"])
          assert_array_equals(actualValues, ["0", "1", "1", "2", "3"])
        }, "Prepending a value pair before the current element position causes it to be skipped during iteration and adds the current element a second time")
        return failures
      `),
    ).toEqual([])
  })

  test("headers-errors.any.js", async () => {
    expect(
      await value(`
        ${testharness}
        test(function() { assert_throws_js(TypeError, function() { new Headers([["name"]]) }) }, "Create headers giving an array having one string as init argument")
        test(function() { assert_throws_js(TypeError, function() { new Headers([["invalid", "invalidValue1", "invalidValue2"]]) }) }, "Create headers giving an array having three strings as init argument")
        test(function() { assert_throws_js(TypeError, function() { new Headers([["invalid\u0100", "Value1"]]) }) }, "Create headers giving bad header name as init argument")
        test(function() { assert_throws_js(TypeError, function() { new Headers([["name", "invalidValue\u0100"]]) }) }, "Create headers giving bad header value as init argument")
        var badNames = ["invalid\u0100", {}]
        var badValues = ["invalid\u0100"]
        badNames.forEach(function(name) {
          test(function() { var headers = new Headers(); assert_throws_js(TypeError, function() { headers.get(name) }) }, "Check headers get with an invalid name " + name)
        })
        badNames.forEach(function(name) {
          test(function() { var headers = new Headers(); assert_throws_js(TypeError, function() { headers.delete(name) }) }, "Check headers delete with an invalid name " + name)
        })
        badNames.forEach(function(name) {
          test(function() { var headers = new Headers(); assert_throws_js(TypeError, function() { headers.has(name) }) }, "Check headers has with an invalid name " + name)
        })
        badNames.forEach(function(name) {
          test(function() { var headers = new Headers(); assert_throws_js(TypeError, function() { headers.set(name, "Value1") }) }, "Check headers set with an invalid name " + name)
        })
        badValues.forEach(function(value) {
          test(function() { var headers = new Headers(); assert_throws_js(TypeError, function() { headers.set("name", value) }) }, "Check headers set with an invalid value " + value)
        })
        badNames.forEach(function(name) {
          test(function() { var headers = new Headers(); assert_throws_js(TypeError, function() { headers.append("invalid\u0100", "Value1") }) }, "Check headers append with an invalid name " + name)
        })
        badValues.forEach(function(value) {
          test(function() { var headers = new Headers(); assert_throws_js(TypeError, function() { headers.append("name", value) }) }, "Check headers append with an invalid value " + value)
        })
        test(function() {
          var headers = new Headers([["name", "value"]])
          assert_throws_js(TypeError, function() { headers.forEach() })
          assert_throws_js(TypeError, function() { headers.forEach(undefined) })
          assert_throws_js(TypeError, function() { headers.forEach(1) })
        }, "Headers forEach throws if argument is not callable")
        test(function() {
          var headers = new Headers([["name1", "value1"], ["name2", "value2"], ["name3", "value3"]])
          var counter = 0
          try {
            headers.forEach(function(value, name) {
              counter++
              if (name == "name2") throw "error"
            })
          } catch (e) {
            assert_equals(counter, 2)
            assert_equals(e, "error")
            return
          }
          assert_unreached()
        }, "Headers forEach loop should stop if callback is throwing exception")
        return failures
      `),
    ).toEqual([])
  })
})

import { handleEnterpriseRequest } from "../src/lib/enterprise"
import { z } from "zod"
import { SalesforceCliError, salesforceCliResponse } from "./salesforce-cli-response"
import { handleConsoleSignup } from "../src/lib/console-signup"
import { consoleAccountSchema } from "../src/lib/console-account"

const org = process.env.SF_TARGET_ORG || "opencode"
const crmToken = process.env.CONSOLE_CRM_TOKEN
if (!crmToken) throw new Error("Set CONSOLE_CRM_TOKEN to the shared local Console CRM token")
const accountUrl = process.env.CONSOLE_CRM_LOOKUP_URL || "http://localhost:3100/console/api/internal/console-account"

async function authenticatedRequest(
  path: string,
  payload?: Record<string, unknown>,
  method: "GET" | "POST" | "PATCH" = payload ? "POST" : "GET",
) {
  const child = Bun.spawn(
    [
      "sf",
      "api",
      "request",
      "rest",
      path,
      "--target-org",
      org,
      "--json",
      "--method",
      method,
      ...(payload ? ["--body", "-", "--header", "Content-Type:application/json"] : []),
    ],
    {
      stdin: payload ? new Blob([JSON.stringify(payload)]) : "ignore",
      stdout: "pipe",
      stderr: "pipe",
    },
  )
  const [output] = await Promise.all([
    new Response(child.stdout).text(),
    child.exited,
    new Response(child.stderr).text(),
  ])
  return salesforceCliResponse(output)
}

await authenticatedRequest("/services/data/v59.0/")

const server = Bun.serve({
  hostname: "127.0.0.1",
  port: Number(process.env.ENTERPRISE_DEV_PORT || 3101),
  async fetch(request) {
    const path = new URL(request.url).pathname
    if (path === "/health" && request.method === "GET") {
      return Response.json({ handler: "local-sst-enterprise", salesforceOrg: org })
    }
    if (path === "/api/console-signup" && request.method === "POST") {
      return handleConsoleSignup(request, crmToken, (path, method, payload) =>
        authenticatedRequest(path, payload, method),
      )
    }
    if (path !== "/api/enterprise") return new Response("Not found", { status: 404 })
    if (request.method !== "POST") return new Response("Method not allowed", { status: 405 })
    const failures: string[] = []
    const response = await handleEnterpriseRequest(request, {
      salesforceSubmit: async (payload) => {
        const result = await authenticatedRequest("/services/data/v59.0/sobjects/Lead", payload).catch(
          (error: unknown) => {
            const code = error instanceof SalesforceCliError ? error.code : "CLI_ERROR"
            failures.push(code)
            console.error(`Local Salesforce submission rejected: ${code}`)
            return undefined
          },
        )
        return z.object({ success: z.literal(true) }).safeParse(result).success
      },
      notifications: false,
      accountLookup: async (email) => {
        const response = await fetch(accountUrl, {
          method: "POST",
          headers: { "Content-Type": "application/json", Authorization: `Bearer ${crmToken}` },
          body: JSON.stringify({ email }),
          signal: AbortSignal.timeout(8000),
        })
        if (!response.ok) throw new Error(`Local Console account lookup failed (${response.status})`)
        return z.object({ account: consoleAccountSchema.nullable() }).parse(await response.json()).account
      },
    })
    if (failures.length > 0) {
      return Response.json(
        { error: "Salesforce rejected the request.", errorCode: failures[0] },
        { status: 502, headers: { "X-Enterprise-Handler": "local-sst-enterprise" } },
      )
    }
    response.headers.set("X-Enterprise-Handler", "local-sst-enterprise")
    return response
  },
})

console.log(`Local Enterprise handler: ${server.url.origin}/api/enterprise`)
console.log(`Salesforce CLI org: ${org}; local email and EmailOctopus delivery disabled.`)

#!/usr/bin/env bun
import { readdir, writeFile } from "fs/promises"
import { join, dirname } from "path"
import { fileURLToPath } from "url"
import { config } from "../src/config.js"
import { LOCALES, route } from "../src/lib/language.js"

const __dirname = dirname(fileURLToPath(import.meta.url))
const BASE_URL = config.baseUrl
const PUBLIC_DIR = join(__dirname, "../public")
const DOCS_DIR = join(__dirname, "../../../web/src/content/docs")

interface SitemapEntry {
  url: string
  priority: number
  changefreq: string
}

async function getMainRoutes(): Promise<SitemapEntry[]> {
  const routes: SitemapEntry[] = []

  // Add main static routes
  const staticRoutes = [
    { path: "/", priority: 1.0, changefreq: "daily" },
    { path: "/enterprise", priority: 0.8, changefreq: "weekly" },
    { path: "/brand", priority: 0.6, changefreq: "monthly" },
    { path: "/zen", priority: 0.8, changefreq: "weekly" },
    { path: "/go", priority: 0.8, changefreq: "weekly" },
  ]

  for (const item of staticRoutes) {
    for (const locale of LOCALES) {
      routes.push({
        url: `${BASE_URL}${route(locale, item.path)}`,
        priority: item.priority,
        changefreq: item.changefreq,
      })
    }
  }

  return routes
}

async function getDocsRoutes(): Promise<SitemapEntry[]> {
  const routes: SitemapEntry[] = []

  try {
    const files = await readdir(DOCS_DIR)

    for (const file of files) {
      if (!file.endsWith(".mdx")) continue

      const slug = file.replace(".mdx", "")
      const path = slug === "index" ? "/docs/" : `/docs/${slug}`

      for (const locale of LOCALES) {
        routes.push({
          url: `${BASE_URL}${route(locale, path)}`,
          priority: slug === "index" ? 0.9 : 0.7,
          changefreq: "weekly",
        })
      }
    }
  } catch (error) {
    console.error("Error reading docs directory:", error)
  }

  return routes
}

function generateSitemapXML(entries: SitemapEntry[]): string {
  const urls = entries
    .map(
      (entry) => `  <url>
    <loc>${entry.url}</loc>
    <changefreq>${entry.changefreq}</changefreq>
    <priority>${entry.priority}</priority>
  </url>`,
    )
    .join("\n")

  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls}
</urlset>`
}

async function main() {
  console.log("Generating sitemap...")

  const mainRoutes = await getMainRoutes()
  const docsRoutes = await getDocsRoutes()

  const allRoutes = [...mainRoutes, ...docsRoutes]

  console.log(`Found ${mainRoutes.length} main routes`)
  console.log(`Found ${docsRoutes.length} docs routes`)
  console.log(`Total: ${allRoutes.length} routes`)

  const xml = generateSitemapXML(allRoutes)

  const outputPath = join(PUBLIC_DIR, "sitemap.xml")
  await writeFile(outputPath, xml, "utf-8")

  console.log(`✓ Sitemap generated at ${outputPath}`)
}

void main()

import { expect, test } from "bun:test"
import { SalesforceCliError, salesforceCliResponse } from "./salesforce-cli-response"

test("unwraps a successful Salesforce Lead creation from the CLI HTTP envelope", () => {
  expect(
    salesforceCliResponse(
      JSON.stringify({
        status: 0,
        result: { statusCode: 201, headers: {}, body: { id: "test-lead", success: true, errors: [] } },
      }),
    ),
  ).toEqual({ id: "test-lead", success: true, errors: [] })
})

test("rejects a Salesforce HTTP failure even if the CLI exits successfully", () => {
  expect(() =>
    salesforceCliResponse(
      JSON.stringify({
        status: 0,
        result: { statusCode: 400, body: [{ errorCode: "INVALID_OR_NULL_FOR_RESTRICTED_PICKLIST" }] },
      }),
    ),
  ).toThrow()
})

test("rejects CLI errors and responses missing the HTTP envelope", () => {
  expect(() => salesforceCliResponse(JSON.stringify({ status: 1, message: "CLI error" }))).toThrow()
  expect(() => salesforceCliResponse(JSON.stringify({ status: 0, result: { success: true } }))).toThrow()
})

test("preserves the Salesforce rejection code when the CLI exits nonzero", () => {
  expect(() =>
    salesforceCliResponse(
      JSON.stringify({
        status: 1,
        result: { statusCode: 400, body: [{ errorCode: "DUPLICATES_DETECTED", message: "Duplicate found" }] },
      }),
    ),
  ).toThrow(new SalesforceCliError("DUPLICATES_DETECTED"))
})

import { z } from "zod"

export class SalesforceCliError extends Error {
  constructor(readonly code: string) {
    super(`Salesforce request failed: ${code}`)
  }
}

export function salesforceCliResponse(output: string) {
  const response = z
    .object({
      status: z.number(),
      result: z.object({ statusCode: z.number().int(), body: z.unknown() }).optional(),
    })
    .parse(JSON.parse(output))
  if (!response.result) throw new SalesforceCliError("CLI_ERROR")
  if (response.status !== 0 || response.result.statusCode < 200 || response.result.statusCode > 299) {
    const errors = z
      .array(z.object({ errorCode: z.string().regex(/^[A-Z][A-Z0-9_]+$/) }))
      .safeParse(response.result.body)
    throw new SalesforceCliError(errors.success ? (errors.data[0]?.errorCode ?? "REQUEST_FAILED") : "REQUEST_FAILED")
  }
  return response.result.body
}

