  const params = new URLSearchParams({
    grant_type: "client_credentials",
    client_id: clientId,
    client_secret: clientSecret,
  })

  const res = await fetch(`${url}/services/oauth2/token`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: params.toString(),
  }).catch((err) => {
    console.error("Failed to fetch Salesforce access token:", err)
  })

  if (!res) return

  if (!res.ok) {
    console.error("Failed to fetch Salesforce access token:", res.status, await res.text())
    return
  }

  const data = (await res.json()) as { access_token?: string; instance_url?: string }
  if (!data.access_token) {
    console.error("Salesforce auth response did not include an access token")
    return
  }

  return {
    token: data.access_token,
    url: data.instance_url ?? url,
  }
}

export interface SalesforceLeadInput {
  name: string
  role: string
  company?: string
  email: string
  phone?: string
  inferenceSpend?: string
  message: string
  consoleAccount?: ConsoleAccount | null
}

export async function createLead(
  input: SalesforceLeadInput,
  submit?: (payload: Record<string, unknown>) => Promise<boolean>,
): Promise<boolean> {
  const payload = {
    LastName: input.name,
    Company: input.company?.trim() || "Website",
    Email: input.email,
    Phone: input.phone ?? null,
    Title: input.role,
    Description: input.message,
    Current_Monthly_Inference_Spend__c: input.inferenceSpend,
    LeadSource: "enterprise website form",
    ...(input.consoleAccount === undefined ? {} : consoleAccountFields(input.consoleAccount)),
  }
  if (submit) return submit(payload)
  const auth = await login()
  if (!auth) return false

  const res = await fetch(`${auth.url}/services/data/v59.0/sobjects/Lead`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${auth.token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(payload),
  }).catch((err) => {
    console.error("Failed to create Salesforce lead:", err)
  })

  if (!res) return false

  if (!res.ok) {
    console.error("Failed to create Salesforce lead:", res.status, await res.text())
    return false
  }

  return true
}

export type SalesforceRequest = (
  path: string,
  method?: "GET" | "POST" | "PATCH",
  payload?: Record<string, unknown>,
) => Promise<unknown>

export async function salesforceRequest(): Promise<SalesforceRequest> {
  const auth = await login()
  if (!auth) throw new Error("Salesforce authentication unavailable")
  return async (path, method = "GET", payload) => {
    const response = await fetch(`${auth.url}${path}`, {
      method,
      headers: { Authorization: `Bearer ${auth.token}`, "Content-Type": "application/json" },
      ...(payload ? { body: JSON.stringify(payload) } : {}),
      signal: AbortSignal.timeout(8000),
    })
    if (!response.ok) throw new Error(`Salesforce request failed (${response.status})`)
    if (response.status === 204) return null
    return response.json()
  }
}

/** Update existing people without changing their acquisition source or sales notes. */
export async function syncConsoleAccount(account: ConsoleAccount, request: SalesforceRequest) {
  const quote = (value: string) => value.replace(/\\/g, "\\\\").replace(/'/g, "\\'")
  const matches = async (object: "Contact" | "Lead") => {
    const query = `SELECT Id FROM ${object} WHERE ${object === "Lead" ? "IsConverted = false AND " : ""}(Console_Account_ID__c = '${quote(account.id)}' OR Email = '${quote(account.email.toLowerCase())}')`
    const records: { Id: string }[] = []
    let path: string | undefined = `/services/data/v59.0/query?q=${encodeURIComponent(query)}`
    while (path) {
      const result = z
        .object({
          records: z.array(z.object({ Id: z.string().regex(/^[a-zA-Z0-9]{15,18}$/) })),
          done: z.boolean(),
          nextRecordsUrl: z.string().optional(),
        })
        .parse(await request(path))
      records.push(...result.records)
      if (result.done) break
      if (!result.nextRecordsUrl?.startsWith("/services/data/")) throw new Error("Salesforce query pagination missing")
      path = result.nextRecordsUrl
    }
    return records.map((record) => ({ object, id: record.Id }))
  }
  const people = [...(await matches("Contact")), ...(await matches("Lead"))]
  const fields = consoleAccountFields(account)
  for (const person of people)
    await request(`/services/data/v59.0/sobjects/${person.object}/${person.id}`, "PATCH", fields)
  if (people.length > 0) return { success: true, created: false, updated: people.length }
  const domain = account.email.slice(account.email.lastIndexOf("@") + 1).toLowerCase()
  const result = z.object({ success: z.literal(true), id: z.string() }).parse(
    await request("/services/data/v59.0/sobjects/Lead", "POST", {
      LastName: (account.name?.trim() || account.email).slice(0, 80),
      Company: personalEmailDomains.has(domain) ? "Individual" : domain,
      Email: account.email.toLowerCase(),
      LeadSource: "console signup",
      ...fields,
    }),
  )
  return { success: true, created: true, id: result.id }
}

export function sanitizeServerActionRequest(request: Request) {
  const requestUrl = new URL(request.url)
  if (requestUrl.pathname !== "/_server") return request

  const referer = request.headers.get("referer")
  if (referer && URL.canParse(referer) && new URL(referer).origin === requestUrl.origin) return request

  const sanitized = new Request(request)
  sanitized.headers.set("referer", requestUrl.origin)
  return sanitized
}

import type { APIEvent } from "@solidjs/start/server"
import { Resource, waitUntil } from "@opencode/console-resource"
import { prefersMarkdown } from "~/lib/content-negotiation"
import { LOCALE_HEADER, cookie, localeFromRequest, route, tag } from "~/lib/language"

const dataPath = "/data"
const statsCacheParam = "__opencode_stats_locale"

export async function statsProxy(evt: APIEvent) {
  const req = evt.request.clone()
  const locale = localeFromRequest(req)
  const redirect = redirectToLocalizedData(req, new URL(req.url), locale)
  if (redirect) return redirect

  const cache = defaultCache(caches)
  const cacheKey = statsCacheKey(req, locale)
  if (cacheKey) {
    const cached = await cache.match(cacheKey)
    if (cached) return withStatsCacheStatus(cached, "HIT")
  }

  const targetUrl = new URL(req.url)
  targetUrl.protocol = "https:"
  targetUrl.hostname = Resource.App.stage === "production" ? "stats.opencode.ai" : "stats.dev.opencode.ai"
  targetUrl.port = ""

  if (
    targetUrl.pathname.startsWith(`${dataPath}/_build/`) ||
    targetUrl.pathname === `${dataPath}/banner.jpg` ||
    targetUrl.pathname === `${dataPath}/banner.png` ||
    targetUrl.pathname === `${dataPath}/sitemap.xml`
  ) {
    targetUrl.pathname = targetUrl.pathname.slice(dataPath.length)
  }

  const requestHeaders = new Headers(req.headers)
  requestHeaders.set(LOCALE_HEADER, locale)
  requestHeaders.set("accept-language", tag(locale))

  const response = await fetch(targetUrl, {
    method: req.method,
    headers: requestHeaders,
    body: req.body,
    // Pass canonical redirects from the stats app to the client instead of following them here.
    redirect: "manual",
  })

  const location = response.headers.get("location")
  if (location) return withPublicLocation(response, new URL(location, targetUrl), targetUrl)
  if (!response.headers.get("content-type")?.includes("text/html")) return response

  const headers = new Headers(response.headers)
  headers.delete("content-encoding")
  headers.delete("content-length")
  headers.delete("etag")
  headers.delete("set-cookie")
  appendVary(headers, "Accept", "Accept-Language", "Cookie", LOCALE_HEADER)

  const result = new Response(rewriteStatsHtml(await response.text()), {
    status: response.status,
    statusText: response.statusText,
    headers,
  })
  if (!cacheKey || !response.ok) return result

  void waitUntil(cache.put(cacheKey, result.clone()))
  return withStatsCacheStatus(result, "MISS")
}

export function statsRedirect(evt: APIEvent) {
  const url = new URL(evt.request.url)
  url.pathname = `${dataPath}${url.pathname.slice("/stats".length)}`
  return new Response(null, {
    status: 308,
    headers: {
      Location: url.toString(),
    },
  })
}

// A redirect to the stats origin itself would send clients past the proxy, so keep only the path.
function withPublicLocation(response: Response, location: URL, upstream: URL) {
  if (location.origin !== upstream.origin) return response
  const headers = new Headers(response.headers)
  headers.set("location", `${location.pathname}${location.search}${location.hash}`)
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers })
}

function rewriteStatsHtml(html: string) {
  return html.replaceAll('"/_build/', `"${dataPath}/_build/`).replaceAll("'/_build/", `'${dataPath}/_build/`)
}

function statsCacheKey(request: Request, locale: ReturnType<typeof localeFromRequest>): Request | undefined {
  if (request.method !== "GET") return undefined
  if (!acceptsHtml(request)) return undefined
  if (isDataBypassPath(new URL(request.url).pathname)) return undefined

  const url = new URL(request.url)
  const additionalModels = url.searchParams.get("add")
  url.search = ""
  if (additionalModels) url.searchParams.set("add", additionalModels)
  url.searchParams.set(statsCacheParam, locale)
  return new Request(url)
}

function defaultCache(storage: CacheStorage) {
  if (!isCloudflareCacheStorage(storage)) throw new Error("Cloudflare default cache is unavailable")
  return storage.default
}

function isCloudflareCacheStorage(storage: CacheStorage): storage is CacheStorage & { default: Cache } {
  return "default" in storage
}

function withStatsCacheStatus(response: Response, status: "HIT" | "MISS") {
  const headers = new Headers(response.headers)
  headers.set("x-opencode-stats-cache", status)
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers })
}

function redirectToLocalizedData(request: Request, url: URL, locale: ReturnType<typeof localeFromRequest>) {
  if (locale === "en") return null
  if (request.headers.get(LOCALE_HEADER)) return null
  if (request.method !== "GET" && request.method !== "HEAD") return null
  if (!acceptsHtml(request)) return null
  if (!url.pathname.startsWith(`${dataPath}/`) && url.pathname !== dataPath) return null
  if (isDataBypassPath(url.pathname)) return null

  const next = new URL(url)
  next.pathname = route(locale, url.pathname)

  const headers = new Headers({
    Location: next.toString(),
  })
  headers.append("set-cookie", cookie(locale))
  appendVary(headers, "Accept", "Accept-Language", "Cookie", LOCALE_HEADER)

  return new Response(null, {
    status: 308,
    headers,
  })
}

function acceptsHtml(request: Request) {
  const accept = request.headers.get("accept")
  // The stats app answers Markdown requests itself, so keep them out of the HTML cache and locale redirect.
  if (prefersMarkdown(accept)) return false
  return !accept || accept.includes("text/html") || accept.includes("*/*")
}

function isDataBypassPath(pathname: string) {
  return (
    pathname.startsWith(`${dataPath}/_build/`) ||
    pathname.startsWith(`${dataPath}/api/`) ||
    pathname.startsWith(`${dataPath}/_server`) ||
    pathname === `${dataPath}/banner.jpg` ||
    pathname === `${dataPath}/banner.png` ||
    pathname === `${dataPath}/sitemap.xml` ||
    pathname.endsWith("/llms.txt") ||
    pathname.endsWith(".md") ||
    pathname.endsWith(".json")
  )
}

function appendVary(headers: Headers, ...values: string[]) {
  const existing = headers
    .get("vary")
    ?.split(",")
    .map((value) => value.trim())
    .filter(Boolean)

  headers.set(
    "vary",
    values
      .reduce(
        (result, value) =>
          result.some((item) => item.toLowerCase() === value.toLowerCase()) ? result : [...result, value],
        existing ?? [],
      )
      .join(", "),
  )
}

import { createMiddleware } from "@solidjs/start/middleware"
import { Resource } from "@opencode/console-resource"
import { LOCALE_HEADER, cookie, fromPathname, strip } from "~/lib/language"
import { sanitizeServerActionRequest } from "~/lib/server-action"

export default createMiddleware({
  async onRequest(event) {
    event.request = sanitizeServerActionRequest(event.request)

    const url = new URL(event.request.url)
    const locale = fromPathname(url.pathname)
    if (locale) {
      url.pathname = strip(url.pathname)
      const request = new Request(url, event.request)
      request.headers.set(LOCALE_HEADER, locale)
      event.request = request
      event.response.headers.append("set-cookie", cookie(locale))
    }

    // The legacy dashboard and its sign-in moved to the new Console.
    if (/^\/(auth|workspace)(\/|$)/.test(url.pathname) && Resource.ConsoleMigration.consoleUrl)
      return new Response(null, {
        status: 302,
        headers: { Location: `${Resource.ConsoleMigration.consoleUrl}/login`, "Cache-Control": "no-store" },
      })
  },
})

