import { eq } from "drizzle-orm"
import { Context, DateTime, Effect, Layer, Schema } from "effect"
import { Project } from "@opencode/schema/project"
import { Database } from "../database/database.js"
import { makeGlobalNode } from "@opencode/util/effect/app-node"
import { PermissionTable } from "./sql.js"
import { PermissionSaved } from "@opencode/schema/permission-saved"

export const ID = PermissionSaved.ID
export type ID = typeof ID.Type

export const Info = PermissionSaved.Info
export type Info = typeof Info.Type

export const ListInput = Schema.Struct({
  projectID: Project.ID.pipe(Schema.optional),
}).annotate({ identifier: "PermissionSaved.ListInput" })
export type ListInput = typeof ListInput.Type

export const AddInput = Schema.Struct({
  projectID: Project.ID,
  action: Schema.String,
  resources: Schema.Array(Schema.String),
}).annotate({ identifier: "PermissionSaved.AddInput" })
export type AddInput = typeof AddInput.Type

export interface Interface {
  readonly list: (input?: ListInput) => Effect.Effect<ReadonlyArray<Info>>
  readonly add: (input: AddInput) => Effect.Effect<void>
  readonly remove: (id: ID) => Effect.Effect<void>
}

export class Service extends Context.Service<Service, Interface>()("@opencode/PermissionSaved") {}

const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const db = (yield* Database.Service).db

    const list = Effect.fnUntraced(function* (input?: ListInput) {
      const rows = yield* db
        .select()
        .from(PermissionTable)
        .where(input?.projectID ? eq(PermissionTable.project_id, input.projectID) : undefined)
        .all()
        .pipe(Effect.orDie)
      return rows.map(
        (row): Info => ({
          id: row.id,
          projectID: row.project_id,
          action: row.action,
          resource: row.resource,
          time: {
            created: DateTime.makeUnsafe(row.time_created),
            updated: DateTime.makeUnsafe(row.time_updated),
          },
        }),
      )
    })

    const add = Effect.fn("PermissionSaved.add")(function* (input: AddInput) {
      if (!input.resources.length) return
      yield* db
        .insert(PermissionTable)
        .values(
          input.resources.map((resource) => ({
            id: ID.create(),
            project_id: input.projectID,
            action: input.action,
            resource,
          })),
        )
        .onConflictDoNothing()
        .run()
        .pipe(Effect.orDie)
    })

    const remove = Effect.fn("PermissionSaved.remove")(function* (id: ID) {
      yield* db.delete(PermissionTable).where(eq(PermissionTable.id, id)).run().pipe(Effect.orDie)
    })

    return Service.of({ list, add, remove })
  }),
)

export const node = makeGlobalNode({ service: Service, layer, deps: [Database.node] })

import { createHash } from "node:crypto"
import { chmod, lstat, mkdir, open, readFile, rename, rm } from "node:fs/promises"
import path from "node:path"
import asset from "./pty-binding.js"

// opencode-pty does not ship Windows binaries.
export const available = process.platform !== "win32"

export async function resolveBinary(bin: string) {
  if (process.env.OPENCODE_PTY_BIN) return process.env.OPENCODE_PTY_BIN
  if (!asset) return "opencode-pty"
  if (typeof asset === "string") return asset
  return install(bin, asset)
}

async function install(
  bin: string,
  input: { readonly path: string; readonly version: string; readonly sha256: string },
) {
  const root = path.join(bin, "opencode-pty")
  await privateDirectory(root)
  const directory = path.join(root, `${input.version}-${input.sha256.slice(0, 16)}`)
  await privateDirectory(directory)
  const destination = path.join(directory, "opencode-pty")
  if (await validateIfPresent(destination, input.sha256)) return destination

  const bytes = new Uint8Array(await Bun.file(input.path).arrayBuffer())
  if (sha256(bytes) !== input.sha256) throw new Error("Embedded opencode-pty checksum mismatch")
  const temporary = path.join(directory, `opencode-pty.${process.pid}.${crypto.randomUUID()}.tmp`)
  try {
    const file = await open(temporary, "wx", 0o700)
    try {
      await file.writeFile(bytes)
      await file.sync()
    } finally {
      await file.close()
    }
    await chmod(temporary, 0o755)
    await rename(temporary, destination).catch(async (error) => {
      if (!(await validateIfPresent(destination, input.sha256))) throw error
    })
  } finally {
    await rm(temporary, { force: true })
  }
  return validate(destination, input.sha256)
}

async function privateDirectory(directory: string) {
  await mkdir(directory, { recursive: true, mode: 0o700 })
  const info = await lstat(directory)
  if (!info.isDirectory() || info.isSymbolicLink()) throw new Error(`Unsafe opencode-pty directory: ${directory}`)
  const uid = typeof process.getuid === "function" ? process.getuid() : undefined
  if (uid !== undefined && info.uid !== uid)
    throw new Error(`opencode-pty directory is owned by another user: ${directory}`)
  await chmod(directory, 0o700)
}

async function validateIfPresent(file: string, expected: string) {
  try {
    await validate(file, expected)
    return true
  } catch (error) {
    if (isMissing(error)) return false
    throw error
  }
}

async function validate(file: string, expected: string) {
  const info = await lstat(file)
  if (!info.isFile() || info.isSymbolicLink()) throw new Error(`Unsafe opencode-pty executable: ${file}`)
  const uid = typeof process.getuid === "function" ? process.getuid() : undefined
  if (uid !== undefined && info.uid !== uid)
    throw new Error(`opencode-pty executable is owned by another user: ${file}`)
  if (sha256(await readFile(file)) !== expected) throw new Error(`Cached opencode-pty checksum mismatch: ${file}`)
  await chmod(file, 0o755)
  return file
}

function sha256(bytes: Uint8Array) {
  return createHash("sha256").update(bytes).digest("hex")
}

function isMissing(error: unknown): error is NodeJS.ErrnoException {
  return error instanceof Error && "code" in error && error.code === "ENOENT"
}

// opencode-pty does not ship Windows binaries.
export const available = process.platform !== "win32"

export async function resolveBinary() {
  return process.env.OPENCODE_PTY_BIN || "opencode-pty"
}

export const available = false

export async function resolveBinary(): Promise<string> {
  throw new Error("Persistent PTYs are unavailable in this runtime")
}

import { spawn } from "node:child_process"
import { mkdir, readFile, rename } from "node:fs/promises"
import net from "node:net"
import path from "node:path"
import { Cause, Data, Duration, Effect, Schema, Semaphore } from "effect"
import type { Handoff } from "@opencode/schema/persistent-pty"

const ProtocolVersion = 7
const MaxFrameBytes = 8 * 1024 * 1024

const Lifecycle = Schema.Union([
  Schema.Struct({ status: Schema.Literal("running") }),
  Schema.Struct({ status: Schema.Literal("exited"), exit_code: Schema.NullOr(Schema.Number) }),
  Schema.Struct({ status: Schema.Literal("failed"), message: Schema.String }),
])

export const WireTerminal = Schema.Struct({
  id: Schema.Number,
  pid: Schema.NullOr(Schema.Number),
  title: Schema.String,
  foreground_process: Schema.NullOr(Schema.String),
  group_id: Schema.String,
  command: Schema.Array(Schema.String),
  cwd: Schema.String,
  cols: Schema.Number,
  rows: Schema.Number,
  lifecycle: Lifecycle,
  output_head: Schema.Number,
  output_tail: Schema.Number,
})
export type WireTerminal = typeof WireTerminal.Type

const Registration = Schema.Struct({
  instance_id: Schema.String,
  pid: Schema.Number,
  protocol: Schema.Number,
  socket: Schema.String,
  token: Schema.String,
})
type Registration = typeof Registration.Type

export const WireResponse = Schema.Union([
  Schema.Struct({
    type: Schema.Literal("pong"),
    instance_id: Schema.String,
    pid: Schema.Number,
    protocol: Schema.Number,
  }),
  Schema.Struct({ type: Schema.Literal("created"), terminal: WireTerminal }),
  Schema.Struct({ type: Schema.Literal("terminals"), terminals: Schema.Array(WireTerminal) }),
  Schema.Struct({ type: Schema.Literal("ok") }),
  Schema.Struct({ type: Schema.Literal("owned") }),
  Schema.Struct({ type: Schema.Literal("handoff"), ticket: Schema.String, expires_at: Schema.Number }),
  Schema.Struct({
    type: Schema.Literal("snapshot"),
    terminal: WireTerminal,
    text: Schema.String,
    checkpoint_base64: Schema.String,
    cursor_x: Schema.Number,
    cursor_y: Schema.Number,
  }),
  Schema.Struct({
    type: Schema.Literal("rows"),
    terminal: WireTerminal,
    lines: Schema.Array(Schema.String),
    cursor_x: Schema.Number,
    cursor_y: Schema.Number,
  }),
  Schema.Struct({
    type: Schema.Literal("attached"),
    terminal: WireTerminal,
    role: Schema.Literals(["controller", "observer"]),
    generation: Schema.Number,
    requested_offset: Schema.Number,
    available_offset: Schema.Number,
    end_offset: Schema.Number,
    truncated: Schema.Boolean,
    replay_base64: Schema.String,
  }),
  Schema.Struct({
    type: Schema.Literal("resized"),
    cols: Schema.Number,
    rows: Schema.Number,
    generation: Schema.Number,
    checkpoint_base64: Schema.String,
  }),
  Schema.Struct({
    type: Schema.Literal("exited"),
    exit_code: Schema.NullOr(Schema.Number),
    final_offset: Schema.Number,
  }),
  Schema.Struct({
    type: Schema.Literal("controller_changed"),
    attachment_id: Schema.NullOr(Schema.String),
    generation: Schema.Number,
  }),
  Schema.Struct({ type: Schema.Literal("title_changed"), title: Schema.String }),
  Schema.Struct({ type: Schema.Literal("foreground_process_changed"), process: Schema.NullOr(Schema.String) }),
  Schema.Struct({ type: Schema.Literal("error"), message: Schema.String }),
])
export type WireResponse = typeof WireResponse.Type

export type Role = "controller" | "observer"

export type StreamEvent =
  | { readonly type: "output"; readonly start: number; readonly end: number; readonly data: Uint8Array }
  | {
      readonly type: "resized"
      readonly cols: number
      readonly rows: number
      readonly generation: number
      readonly checkpoint: Uint8Array
    }
  | { readonly type: "exited"; readonly exitCode?: number; readonly finalOffset: number }
  | { readonly type: "controller_changed"; readonly attachmentID?: string; readonly generation: number }
  | { readonly type: "title_changed"; readonly title: string }
  | { readonly type: "foreground_process_changed"; readonly process: string | null }

export type DaemonAttachment = {
  readonly terminal: WireTerminal
  readonly role: Role
  readonly generation: number
  readonly replay: {
    readonly requestedOffset: number
    readonly availableOffset: number
    readonly endOffset: number
    readonly truncated: boolean
    readonly data: Uint8Array
  }
  readonly activate: () => void
  readonly detach: () => void
}

export class DaemonError extends Data.TaggedError("PersistentPty.DaemonError")<{
  readonly kind: "connect" | "response" | "registration" | "protocol" | "spawn"
  readonly message: string
  readonly pid?: number
}> {}

export interface DaemonTransport {
  readonly request: (value: object, start?: boolean) => Effect.Effect<WireResponse, DaemonError>
  readonly requestIfRunning: (value: object) => Effect.Effect<WireResponse | undefined, DaemonError>
  readonly shutdown: Effect.Effect<WireResponse | undefined, DaemonError>
  readonly handoff: Effect.Effect<Handoff | null, DaemonError>
  readonly subscribe: (
    id: number,
    input: {
      readonly cursor: number
      readonly attachmentID: string
      readonly role: Role
      readonly takeover?: boolean
      readonly onEvent: (event: StreamEvent) => void
      readonly onEnd: () => void
    },
  ) => Effect.Effect<DaemonAttachment, DaemonError>
}

export const makeDaemonTransport = Effect.fn("PersistentPty.makeDaemonTransport")(function* (
  root: string,
  initialID: string,
  binary: () => Promise<string> = () => Promise.resolve(process.env.OPENCODE_PTY_BIN || "opencode-pty"),
  inherited?: Handoff,
) {
  const startup = Semaphore.makeUnsafe(1)
  // Each daemon owns the runtime directory `<root>/<id>`.
  let id = initialID
  let registration: Registration | undefined
  let owner: Awaited<ReturnType<typeof openOwner>> | undefined
  let closed = false
  yield* Effect.addFinalizer(() =>
    Effect.sync(() => {
      closed = true
      owner?.socket.destroy()
    }),
  )

  const claim = (current: Registration, ticket?: string) =>
    Effect.tryPromise({
      try: async (signal) => {
        const connection = await openOwner(current, ticket, signal)
        if (closed || signal.aborted) {
          connection.socket.destroy()
          throw new Error("PTY owner scope is closed")
        }
        owner = connection
        registration = current
        connection.socket.once("close", () => {
          if (owner !== connection) return
          owner = undefined
          registration = undefined
        })
      },
      catch: (cause) => failure("connect", cause),
    }).pipe(
      Effect.timeoutOrElse({
        duration: Duration.seconds(5),
        orElse: () => Effect.fail(new DaemonError({ kind: "connect", message: "PTY ownership claim timed out" })),
      }),
    )

  const discover = Effect.fn("PersistentPty.daemon.discover")(function* (directory = path.join(root, id)) {
    const value = yield* Effect.tryPromise({
      try: () => readFile(path.join(directory, "service.json"), "utf8"),
      catch: (cause) => failure("connect", cause),
    })
    const decoded = yield* Schema.decodeUnknownEffect(Schema.fromJsonString(Registration))(value).pipe(
      Effect.mapError((cause) => failure("protocol", cause)),
    )
    if (decoded.protocol !== ProtocolVersion)
      return yield* Effect.fail(
        new DaemonError({
          kind: "protocol",
          message: `opencode-pty protocol mismatch: daemon=${decoded.protocol}, client=${ProtocolVersion}`,
          pid: decoded.pid,
        }),
      )
    const response = yield* oneShot(decoded, { op: "ping" })
    if (
      response.type !== "pong" ||
      response.instance_id !== decoded.instance_id ||
      response.pid !== decoded.pid ||
      response.protocol !== ProtocolVersion
    )
      return yield* Effect.fail(new DaemonError({ kind: "protocol", message: "opencode-pty registration mismatch" }))
    return decoded
  })

  const spawnDaemon = Effect.fn("PersistentPty.daemon.spawn")(function* () {
    const executable = yield* Effect.tryPromise({ try: binary, catch: (cause) => failure("spawn", cause) })
    const child = yield* Effect.tryPromise({
      try: () =>
        new Promise<ReturnType<typeof spawn>>((resolve, reject) => {
          const child = spawn(
            executable,
            ["daemon", "--runtime-dir", root, "--name", id],
            { detached: true, windowsHide: true, stdio: "ignore" },
          )
          child.once("spawn", () => {
            child.unref()
            resolve(child)
          })
          child.once("error", reject)
        }),
      catch: (cause) => failure("spawn", cause),
    })
    return yield* Effect.gen(function* () {
      const deadline = Date.now() + 5_000
      let last: DaemonError | undefined
      while (Date.now() < deadline && child.exitCode === null && child.signalCode === null) {
        const found = yield* discover().pipe(
          Effect.map((value) => ({ value })),
          Effect.catch((error) => {
            last = error
            return Effect.succeed(undefined)
          }),
        )
        if (found) {
          yield* claim(found.value)
          return found.value
        }
        yield* Effect.sleep(50)
      }
      return yield* Effect.fail(
        last ?? new DaemonError({ kind: "connect", message: "opencode-pty did not become ready" }),
      )
    }).pipe(
      Effect.onError(() =>
        Effect.sync(() => {
          child.kill("SIGTERM")
        }),
      ),
    )
  })

  // An unreachable daemon can still hold this directory's lock, so retry once in a fresh directory.
  const start = () =>
    spawnDaemon().pipe(
      Effect.catch((error) =>
        Effect.gen(function* () {
          yield* Effect.logWarning("Starting opencode-pty in a fresh runtime directory", { cause: error.message })
          abandon()
          return yield* spawnDaemon()
        }),
      ),
    )

  const abandon = () => {
    owner?.socket.destroy()
    owner = undefined
    registration = undefined
    id = crypto.randomUUID()
  }

  const connect = Effect.fn("PersistentPty.daemon.connect")(function* (shouldStart: boolean) {
    if (closed) return yield* Effect.fail(new DaemonError({ kind: "connect", message: "PTY owner scope is closed" }))
    if (registration) return registration
    return yield* startup.withPermit(
      Effect.gen(function* () {
        if (registration) return registration
        const found = yield* discover().pipe(
          Effect.catch((error) => {
            if (shouldStart && error.kind === "connect") return start()
            return Effect.fail(error)
          }),
        )
        if (!owner) yield* claim(found)
        registration = found
        return found
      }),
    )
  })

  const attempt = Effect.fn("PersistentPty.daemon.request-attempt")(function* (value: object, shouldStart: boolean) {
    const current = yield* connect(shouldStart)
    return yield* oneShot(current, value).pipe(
      Effect.catch((error) => {
        if (error.kind === "registration" && registration === current) registration = undefined
        return Effect.fail(error)
      }),
    )
  })

  const request = Effect.fn("PersistentPty.daemon.request")(function* (value: object, shouldStart = false) {
    return yield* attempt(value, shouldStart).pipe(
      Effect.catch((error) => {
        if (error.kind === "registration") return attempt(value, shouldStart)
        if (error.kind !== "connect") return Effect.fail(error)
        registration = undefined
        if (!shouldStart) return Effect.fail(error)
        return attempt(value, true)
      }),
    )
  })

  const requestIfRunning = (value: object) =>
    request(value).pipe(
      Effect.catch((error) => (error.kind === "connect" ? Effect.succeed(undefined) : Effect.fail(error))),
    )

  const shutdown = Effect.gen(function* () {
    const response = yield* requestIfRunning({ op: "shutdown" })
    registration = undefined
    if (!response) return undefined
    const deadline = Date.now() + 5_000
    while (Date.now() < deadline) {
      const running = yield* discover().pipe(
        Effect.as(true),
        Effect.orElseSucceed(() => false),
      )
      if (!running) return response
      yield* Effect.sleep(50)
    }
    return yield* Effect.fail(new DaemonError({ kind: "connect", message: "opencode-pty did not stop" }))
  })

  const handoff = startup.withPermit(
    Effect.gen(function* () {
      const current = owner
      const registered = registration
      if (!current || !registered) return null
      const response = yield* Effect.tryPromise({
        try: (signal) => current.exchange({ op: "prepare_handoff" }, signal),
        catch: (cause) => failure("response", cause),
      }).pipe(
        Effect.timeoutOrElse({
          duration: Duration.seconds(5),
          orElse: () =>
            Effect.fail(new DaemonError({ kind: "response", message: "PTY handoff preparation timed out" })),
        }),
      )
      if (response.type !== "handoff")
        return yield* Effect.fail(new DaemonError({ kind: "protocol", message: "Expected PTY handoff ticket" }))
      return {
        directory: path.join(root, id),
        instanceID: registered.instance_id,
        ticket: response.ticket,
        expiresAt: response.expires_at,
      }
    }),
  )

  const subscribe = Effect.fn("PersistentPty.daemon.subscribe")(function* (
    terminalID: number,
    input: Parameters<DaemonTransport["subscribe"]>[1],
  ) {
    const attempt = Effect.gen(function* () {
      const current = yield* connect(false)
      return yield* Effect.tryPromise({
        try: () => subscribePromise(current, terminalID, input),
        catch: (cause) => (cause instanceof DaemonError ? cause : failure("connect", cause)),
      }).pipe(
        Effect.catch((error) => {
          if (error.kind === "registration" && registration === current) registration = undefined
          return Effect.fail(error)
        }),
      )
    })
    return yield* attempt.pipe(Effect.catch((error) => (error.kind === "registration" ? attempt : Effect.fail(error))))
  })

  // A replacement must own its inherited daemon before the server becomes ready. Terminals are
  // best-effort: any failure abandons the old daemon so the restart itself always succeeds.
  if (inherited) {
    let found: Registration | undefined
    yield* Effect.gen(function* () {
      if (inherited.expiresAt <= Date.now())
        return yield* Effect.fail(new DaemonError({ kind: "registration", message: "PTY restart handoff expired" }))
      // Older releases put the daemon directory outside the root; its directory name is still the ID.
      id = path.basename(inherited.directory)
      found = yield* discover(inherited.directory)
      if (found.instance_id !== inherited.instanceID)
        return yield* Effect.fail(new DaemonError({ kind: "registration", message: "PTY restart daemon changed" }))
      if (path.resolve(inherited.directory) !== path.resolve(root, id))
        yield* migrate(inherited.directory, path.join(root, id))
      yield* claim(found, inherited.ticket)
    }).pipe(
      Effect.catchCause((cause) =>
        Effect.gen(function* () {
          if (Cause.hasInterruptsOnly(cause)) return yield* Effect.failCause(cause)
          yield* Effect.logWarning("Discarding PTY restart handoff; persistent terminals will start fresh", {
            cause: Cause.pretty(cause),
          })
          if (found) yield* oneShot(found, { op: "shutdown" }).pipe(Effect.ignore)
          abandon()
        }),
      ),
    )
  }

  return { request, requestIfRunning, shutdown, handoff, subscribe } satisfies DaemonTransport
})

// Older releases kept registrations in purgeable temp directories. Renaming keeps the lock file's
// inode, so the still-running daemon keeps holding its lock in the new location.
const migrate = Effect.fn("PersistentPty.daemon.migrate")(function* (directory: string, target: string) {
  yield* Effect.tryPromise({
    try: async () => {
      await mkdir(target, { recursive: true, mode: 0o700 })
      await rename(path.join(directory, "service.lock"), path.join(target, "service.lock"))
      await rename(path.join(directory, "service.json"), path.join(target, "service.json"))
    },
    catch: (cause) => failure("registration", cause),
  })
})

async function openOwner(registration: Registration, ticket: string | undefined, signal: AbortSignal) {
  const socket = net.createConnection({ path: registration.socket })
  const frames = decoder(socket)
  const abort = () => socket.destroy()
  signal.addEventListener("abort", abort, { once: true })
  const exchange = async (request: object, signal: AbortSignal) => {
    if (signal.aborted) throw new Error("PTY ownership request interrupted")
    signal.addEventListener("abort", abort, { once: true })
    try {
      socket.write(encode({ token: registration.token, request }))
      const frame = await frames.next()
      if (frame.done) throw new Error("PTY daemon closed its ownership connection")
      const response = decode(frame.value)
      if (response.type === "error") throw new Error(response.message)
      return response
    } finally {
      signal.removeEventListener("abort", abort)
    }
  }
  try {
    await new Promise<void>((resolve, reject) => {
      socket.once("connect", resolve)
      socket.once("error", reject)
      socket.once("close", () => reject(new Error("PTY ownership connection closed")))
    })
    const response = await exchange({ op: "own", instance_id: registration.instance_id, ticket }, signal)
    if (response.type !== "owned") throw new Error("PTY daemon does not support server ownership")
    socket.unref()
    return { socket, exchange }
  } catch (error) {
    socket.destroy()
    throw error
  } finally {
    signal.removeEventListener("abort", abort)
  }
}

const oneShot = Effect.fn("PersistentPty.daemon.oneShot")(function* (registration: Registration, request: object) {
  const payload = yield* Effect.try({
    try: () => encode({ token: registration.token, request }),
    catch: (cause) => failure("protocol", cause),
  })
  let dispatched = false
  return yield* Effect.acquireUseRelease(
    Effect.tryPromise({
      try: (signal) =>
        new Promise<net.Socket>((resolve, reject) => {
          const socket = net.createConnection({ path: registration.socket, signal })
          socket.once("connect", () => resolve(socket))
          socket.once("error", reject)
        }),
      catch: (cause) => failure("connect", cause),
    }),
    (socket) =>
      Effect.gen(function* () {
        yield* Effect.try({
          try: () => {
            dispatched = true
            socket.write(payload)
          },
          catch: (cause) => failure("response", cause),
        })
        const first = yield* Effect.tryPromise({
          try: async (signal) => {
            const frames = decoder(socket)
            const abort = () => socket.destroy()
            signal.addEventListener("abort", abort, { once: true })
            try {
              const frame = await frames.next()
              if (frame.done) throw new Error("opencode-pty closed without response")
              return frame.value
            } finally {
              signal.removeEventListener("abort", abort)
            }
          },
          catch: (cause) => failure("response", cause),
        })
        const response = yield* Effect.try({
          try: () => decode(first),
          catch: (cause) => failure("protocol", cause),
        })
        if (response.type === "error")
          return yield* Effect.fail(
            new DaemonError({
              kind: response.message === "authentication failed" ? "registration" : "protocol",
              message: response.message,
            }),
          )
        return response
      }),
    (socket) => Effect.sync(() => socket.destroy()),
  ).pipe(
    Effect.timeoutOrElse({
      duration: Duration.seconds(5),
      orElse: () =>
        Effect.fail(
          new DaemonError({
            kind: dispatched ? "response" : "connect",
            message: "opencode-pty request timed out",
          }),
        ),
    }),
  )
})

async function subscribePromise(
  registration: Registration,
  id: number,
  input: Parameters<DaemonTransport["subscribe"]>[1],
): Promise<DaemonAttachment> {
  const socket = net.createConnection(registration.socket)
  const frames = decoder(socket)
  try {
    await new Promise<void>((resolve, reject) => {
      socket.once("connect", resolve)
      socket.once("error", reject)
    })
    socket.write(
      encode({
        token: registration.token,
        request: {
          op: "subscribe",
          id,
          offset: input.cursor,
          attachment_id: input.attachmentID,
          role: input.role,
          takeover: input.takeover ?? false,
        },
      }),
    )
    const initial = await frames.next()
    if (initial.done) throw new Error("opencode-pty closed before attachment")
    const response = decode(initial.value)
    if (response.type === "error")
      throw new DaemonError({
        kind: response.message === "authentication failed" ? "registration" : "protocol",
        message: response.message,
      })
    if (response.type !== "attached") throw new Error(`unexpected opencode-pty response: ${response.type}`)
    let detached = false
    const pump = async () => {
      try {
        for await (const frame of frames) {
          if (frame[0] === 0) {
            if (frame.length < 17) throw new Error("invalid opencode-pty output frame")
            input.onEvent({
              type: "output",
              start: Number(frame.readBigUInt64BE(1)),
              end: Number(frame.readBigUInt64BE(9)),
              data: frame.subarray(17),
            })
            continue
          }
          const event = decode(frame)
          if (event.type === "resized")
            input.onEvent({
              type: "resized",
              cols: event.cols,
              rows: event.rows,
              generation: event.generation,
              checkpoint: Buffer.from(event.checkpoint_base64, "base64"),
            })
          if (event.type === "controller_changed")
            input.onEvent({
              type: "controller_changed",
              attachmentID: event.attachment_id ?? undefined,
              generation: event.generation,
            })
          if (event.type === "title_changed") input.onEvent({ type: "title_changed", title: event.title })
          if (event.type === "foreground_process_changed")
            input.onEvent({ type: "foreground_process_changed", process: event.process })
          if (event.type === "exited") {
            input.onEvent({
              type: "exited",
              exitCode: event.exit_code ?? undefined,
              finalOffset: event.final_offset,
            })
            return
          }
        }
      } finally {
        if (!detached) input.onEnd()
      }
    }
    let activated = false
    return {
      terminal: response.terminal,
      role: response.role,
      generation: response.generation,
      replay: {
        requestedOffset: response.requested_offset,
        availableOffset: response.available_offset,
        endOffset: response.end_offset,
        truncated: response.truncated,
        data: Buffer.from(response.replay_base64, "base64"),
      },
      activate() {
        if (activated || detached) return
        activated = true
        void pump().catch(() => {})
      },
      detach() {
        if (detached) return
        detached = true
        socket.destroy()
      },
    }
  } catch (error) {
    socket.destroy()
    throw error
  }
}

function encode(value: unknown) {
  const payload = Buffer.from(JSON.stringify(value))
  if (payload.length > MaxFrameBytes) throw new Error("opencode-pty frame too large")
  const output = Buffer.allocUnsafe(payload.length + 4)
  output.writeUInt32BE(payload.length)
  payload.copy(output, 4)
  return output
}

async function* decoder(socket: net.Socket) {
  let pending = Buffer.alloc(0)
  for await (const value of socket) {
    const chunk = Buffer.isBuffer(value) ? value : Buffer.from(value)
    pending = pending.length === 0 ? chunk : Buffer.concat([pending, chunk])
    while (pending.length >= 4) {
      const length = pending.readUInt32BE(0)
      if (length > MaxFrameBytes) throw new Error("opencode-pty frame too large")
      if (pending.length < length + 4) break
      yield pending.subarray(4, length + 4)
      pending = pending.subarray(length + 4)
    }
  }
  if (pending.length !== 0) throw new Error("opencode-pty truncated frame")
}

function decode(payload: Uint8Array) {
  return Schema.decodeUnknownSync(WireResponse)(JSON.parse(Buffer.from(payload).toString("utf8")))
}

function failure(kind: DaemonError["kind"], cause: unknown) {
  return new DaemonError({ kind, message: cause instanceof Error ? cause.message : String(cause) })
}

export * as PersistentPty from "./index.js"

import path from "node:path"
import { Context, Effect, Layer, Schema } from "effect"
import { makeGlobalNode } from "@opencode/util/effect/app-node"
import { Added, Handoff, PersistentPty, ReadLines, Removed, type ReadResult } from "@opencode/schema/persistent-pty"
import { Session } from "@opencode/schema/session"
import { Bus } from "../bus.js"
import { Pty } from "@opencode/schema/pty"
import { Global } from "@opencode/util/global"
import { ShellSelect } from "../shell/select.js"
import {
  makeDaemonTransport,
  type DaemonTransport,
  type Role,
  type StreamEvent,
  type WireResponse,
  type WireTerminal,
} from "./daemon.js"
import { resolveBinary } from "#persistent-pty-binary"

export type { Role, StreamEvent } from "./daemon.js"
export { Handoff } from "@opencode/schema/persistent-pty"
export { available } from "#persistent-pty-binary"

export const Options = Schema.Struct({
  handoff: Schema.optional(Handoff),
  /** Parent of per-server daemon runtime directories; defaults to `<state>/pty`. */
  root: Schema.optional(Schema.String),
})
export type Options = typeof Options.Type

export type Info = PersistentPty.Info

export type Snapshot = PersistentPty.Snapshot

export type Attachment = {
  readonly info: Info
  readonly role: Role
  readonly generation: number
  readonly replay: {
    readonly requestedOffset: number
    readonly availableOffset: number
    readonly endOffset: number
    readonly truncated: boolean
    readonly data: Uint8Array
  }
  readonly activate: () => void
  readonly detach: () => void
}

export class UnavailableError extends Schema.TaggedError<UnavailableError>()("PersistentPty.UnavailableError", {
  message: Schema.String,
}) {}

export class NotFoundError extends Schema.TaggedError<NotFoundError>()("PersistentPty.NotFoundError", {
  ptyID: Pty.ID,
}) {}

export interface Interface {
  readonly list: (sessionID?: Session.ID) => Effect.Effect<Info[], UnavailableError>
  readonly get: (id: Pty.ID) => Effect.Effect<Info, NotFoundError | UnavailableError>
  readonly create: (
    sessionID: Session.ID,
    input: {
      readonly command?: string
      readonly args: readonly string[]
      readonly cwd?: string
      readonly title: string
      readonly env: Readonly<Record<string, string>>
      readonly cols?: number
      readonly rows?: number
    },
  ) => Effect.Effect<Info, UnavailableError>
  readonly write: (
    id: Pty.ID,
    data: string,
    attachmentID?: string,
  ) => Effect.Effect<void, NotFoundError | UnavailableError>
  readonly resize: (
    id: Pty.ID,
    cols: number,
    rows: number,
    attachmentID?: string,
  ) => Effect.Effect<void, NotFoundError | UnavailableError>
  readonly control: (
    id: Pty.ID,
    attachmentID: string,
    cols: number,
    rows: number,
  ) => Effect.Effect<void, NotFoundError | UnavailableError>
  readonly input: (
    id: Pty.ID,
    attachmentID: string,
    cols: number,
    rows: number,
    data: Uint8Array,
  ) => Effect.Effect<void, NotFoundError | UnavailableError>
  readonly snapshot: (id: Pty.ID) => Effect.Effect<Snapshot, NotFoundError | UnavailableError>
  readonly read: (sessionID: Session.ID, lines?: number) => Effect.Effect<ReadResult | null, UnavailableError>
  readonly remove: (id: Pty.ID) => Effect.Effect<void, NotFoundError | UnavailableError>
  readonly shutdown: () => Effect.Effect<void, UnavailableError>
  readonly handoff: () => Effect.Effect<Handoff | null, UnavailableError>
  readonly attach: (
    id: Pty.ID,
    input: {
      readonly cursor: number
      readonly attachmentID: string
      readonly role: Role
      readonly takeover?: boolean
      readonly onEvent: (event: StreamEvent) => void
      readonly onEnd: () => void
    },
  ) => Effect.Effect<Attachment, NotFoundError | UnavailableError>
}

export class Service extends Context.Service<Service, Interface>()("@opencode/PersistentPty") {}

const makeLayer = (options: Options = {}) =>
  Layer.effect(
    Service,
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const global = yield* Global.Service
      const context = yield* Effect.context()
      const runFork = Effect.runForkWith(context)
      let binary: Promise<string> | undefined
      const daemon = yield* makeDaemonTransport(
        options.root ?? path.join(global.state, "pty"),
        crypto.randomUUID(),
        () =>
          (binary ??= resolveBinary(global.bin).catch((error) => {
            binary = undefined
            throw error
          })),
        options.handoff,
      ).pipe(Effect.mapError(unavailable))
      const removing = new Set<Pty.ID>()
      // Controller activity selects a terminal; observer reads and pane visibility do not.
      const current = new Map<Session.ID, Pty.ID>()

      const list = Effect.fn("PersistentPty.list")(function* (sessionID?: Session.ID) {
        const response = yield* optionalRequest(daemon, { op: "list" })
        if (!response) return []
        if (response.type !== "terminals") return yield* unexpected(response)
        return response.terminals
          .map(toInfo)
          .filter((terminal) => sessionID === undefined || terminal.sessionID === sessionID)
      })

      const get = Effect.fn("PersistentPty.get")(function* (id: Pty.ID) {
        const found = (yield* list()).find((terminal) => terminal.id === id)
        if (!found) return yield* new NotFoundError({ ptyID: id })
        return found
      })

      const create = Effect.fn("PersistentPty.create")(function* (
        sessionID: Session.ID,
        input: Parameters<Interface["create"]>[1],
      ) {
        const response = yield* request(
          daemon,
          {
            op: "create",
            program: input.command ?? ShellSelect.environment(global.bin),
            args: input.args,
            cwd: input.cwd ?? path.resolve("/"),
            title: input.title,
            group_id: sessionID,
            env: input.env,
            cols: input.cols ?? 80,
            rows: input.rows ?? 24,
          },
          true,
        )
        if (response.type !== "created") return yield* unexpected(response)
        const terminal = toInfo(response.terminal)
        yield* bus.publish(Added, { sessionID, terminal })
        return terminal
      })

      const write = Effect.fn("PersistentPty.write")(function* (id: Pty.ID, data: string, attachmentID?: string) {
        yield* get(id)
        const response = yield* request(daemon, {
          op: "write",
          id: fromID(id),
          attachment_id: attachmentID ?? null,
          data_base64: Buffer.from(data).toString("base64"),
        })
        if (response.type !== "ok") return yield* unexpected(response)
        return undefined
      })

      const resize = Effect.fn("PersistentPty.resize")(function* (
        id: Pty.ID,
        cols: number,
        rows: number,
        attachmentID?: string,
      ) {
        const terminal = yield* get(id)
        const response = yield* request(daemon, {
          op: "resize",
          id: fromID(id),
          attachment_id: attachmentID ?? null,
          cols,
          rows,
        })
        if (response.type !== "ok") return yield* unexpected(response)
        current.set(terminal.sessionID, id)
        return undefined
      })

      const control = Effect.fn("PersistentPty.control")(function* (
        id: Pty.ID,
        attachmentID: string,
        cols: number,
        rows: number,
      ) {
        const terminal = yield* get(id)
        const response = yield* request(daemon, {
          op: "control",
          id: fromID(id),
          attachment_id: attachmentID,
          cols,
          rows,
        })
        if (response.type !== "ok") return yield* unexpected(response)
        current.set(terminal.sessionID, id)
        return undefined
      })

      const input = Effect.fn("PersistentPty.input")(function* (
        id: Pty.ID,
        attachmentID: string,
        cols: number,
        rows: number,
        data: Uint8Array,
      ) {
        const terminal = yield* get(id)
        const response = yield* request(daemon, {
          op: "input",
          id: fromID(id),
          attachment_id: attachmentID,
          cols,
          rows,
          data_base64: Buffer.from(data).toString("base64"),
        })
        if (response.type !== "ok") return yield* unexpected(response)
        current.set(terminal.sessionID, id)
        return undefined
      })

      const snapshot = Effect.fn("PersistentPty.snapshot")(function* (id: Pty.ID) {
        yield* get(id)
        const response = yield* request(daemon, { op: "snapshot", id: fromID(id) })
        if (response.type !== "snapshot") return yield* unexpected(response)
        return {
          info: toInfo(response.terminal),
          text: response.text,
          checkpoint: Buffer.from(response.checkpoint_base64, "base64"),
          cursor: { x: response.cursor_x, y: response.cursor_y },
        }
      })

      const read = Effect.fn("PersistentPty.read")(function* (sessionID: Session.ID, lines?: number) {
        if (lines !== undefined && !Schema.is(ReadLines)(lines))
          return yield* new UnavailableError({ message: "lines must be an integer between 1 and 65535" })
        const id = current.get(sessionID)
        if (!id) return null
        const terminal = yield* get(id).pipe(Effect.catchTag("PersistentPty.NotFoundError", () => Effect.succeed(null)))
        if (!terminal || terminal.sessionID !== sessionID) {
          if (current.get(sessionID) === id) current.delete(sessionID)
          return null
        }
        // Let the daemon choose the live height in the same snapshot when lines is omitted.
        const response = yield* request(daemon, { op: "read_rows", id: fromID(id), rows: lines })
        if (response.type !== "rows") return yield* unexpected(response)
        const info = toInfo(response.terminal)
        return {
          ptyID: info.id,
          title: info.title,
          cwd: info.cwd,
          foregroundProcess: info.foregroundProcess,
          screen: {
            text: response.lines.join("\n"),
            cols: info.size.cols,
            rows: info.size.rows,
            cursor: { x: response.cursor_x, y: response.cursor_y },
          },
        }
      })

      const remove = Effect.fn("PersistentPty.remove")(function* (id: Pty.ID) {
        const terminal = yield* get(id)
        const response = yield* request(daemon, { op: "terminate", id: fromID(id) })
        if (response.type !== "ok") return yield* unexpected(response)
        if (current.get(terminal.sessionID) === id) current.delete(terminal.sessionID)
        yield* bus.publish(Removed, { sessionID: terminal.sessionID, ptyID: id })
        return undefined
      })

      const shutdown = Effect.fn("PersistentPty.shutdown")(function* () {
        const response = yield* daemon.shutdown.pipe(Effect.mapError(unavailable))
        current.clear()
        if (!response) return
        if (response.type !== "ok") return yield* unexpected(response)
      })

      const handoff = Effect.fn("PersistentPty.handoff")(() => daemon.handoff.pipe(Effect.mapError(unavailable)))

      const removeVisibleExit = (id: Pty.ID) => {
        if (removing.has(id)) return
        removing.add(id)
        runFork(
          remove(id).pipe(
            Effect.catchTags({
              "PersistentPty.NotFoundError": () => Effect.void,
              "PersistentPty.UnavailableError": (error) =>
                Effect.logWarning("failed to remove visible exited terminal", { id, error: error.message }),
            }),
            Effect.ensuring(Effect.sync(() => removing.delete(id))),
          ),
        )
      }

      const attach = Effect.fn("PersistentPty.attach")(function* (
        id: Pty.ID,
        input: Parameters<Interface["attach"]>[1],
      ) {
        yield* get(id)
        const attachment = yield* daemon
          .subscribe(fromID(id), {
            ...input,
            onEvent: (event) => {
              if (event.type === "exited") removeVisibleExit(id)
              input.onEvent(event)
            },
          })
          .pipe(Effect.mapError(unavailable))
        if (attachment.role === "controller") current.set(Session.ID.make(attachment.terminal.group_id), id)
        return {
          info: toInfo(attachment.terminal),
          role: attachment.role,
          generation: attachment.generation,
          replay: attachment.replay,
          activate: attachment.activate,
          detach: attachment.detach,
        }
      })

      return Service.of({
        list,
        get,
        create,
        write,
        resize,
        control,
        input,
        snapshot,
        read,
        remove,
        shutdown,
        handoff,
        attach,
      })
    }),
  )

export const layer = makeLayer()
export const configured = (options?: Options) =>
  makeGlobalNode({
    service: Service,
    layer: options === undefined ? layer : makeLayer(options),
    deps: [Bus.node, Global.node],
  })
export const node = configured()

const request = (daemon: DaemonTransport, value: object, start = false) =>
  daemon.request(value, start).pipe(Effect.mapError(unavailable))

const optionalRequest = (daemon: DaemonTransport, value: object) =>
  daemon.requestIfRunning(value).pipe(Effect.mapError(unavailable))

const unexpected = (response: WireResponse) =>
  Effect.fail(new UnavailableError({ message: `unexpected opencode-pty response: ${response.type}` }))

const unavailable = (error: unknown) =>
  new UnavailableError({ message: error instanceof Error ? error.message : String(error) })

function toInfo(value: WireTerminal): Info {
  const status = value.lifecycle.status
  return {
    ...Pty.Info.make({
      id: toID(value.id),
      title: value.title,
      command: value.command[0] || "",
      args: value.command.slice(1),
      cwd: value.cwd,
      status: status === "running" ? "running" : "exited",
      pid: value.pid ?? 0,
      ...(status === "exited" ? { exitCode: value.lifecycle.exit_code ?? undefined } : {}),
    }),
    sessionID: Session.ID.make(value.group_id),
    foregroundProcess: value.foreground_process,
    size: { cols: value.cols, rows: value.rows },
    output: { head: value.output_head, tail: value.output_tail },
  }
}

function toID(value: number) {
  return Pty.ID.make(`pty_persistent_${value}`)
}

function fromID(value: Pty.ID) {
  if (!value.startsWith("pty_persistent_")) throw new Error(`invalid persistent PTY ID: ${value}`)
  const parsed = Number(value.slice("pty_persistent_".length))
  if (!Number.isSafeInteger(parsed) || parsed < 1) throw new Error(`invalid persistent PTY ID: ${value}`)
  return parsed
}

export * as Plugin from "./plugin.js"
export { Event, ID, Info, Source, State } from "@opencode/schema/plugin"

import { Plugin } from "@opencode/schema/plugin"
import { Node } from "@opencode/util/effect/app-node"
import { LayerNode } from "@opencode/util/effect/layer-node"
import type { PersistentPty } from "./persistent-pty.js"
import { Cause, Context, Effect, Exit, Latch, Layer, Logger, Queue, References, Scope, Semaphore } from "effect"
import { Bus } from "./bus.js"
import { KV } from "./kv.js"
import { PluginHost } from "./plugin/host.js"
import { type Failure, type Generation, Service } from "./plugin/service.js"
import { State } from "./state.js"

export { awaitActivation, type Generation, type Interface, Service } from "./plugin/service.js"

const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const bus = yield* Bus.Service
    const kv = yield* KV.Service
    const scope = yield* Scope.make()
    // One slot per requested definition in activation order, including ones whose setup failed, so
    // the prefix diff below stays index-aligned and a failed revision is not retried until it changes.
    const active = new Map<Plugin.ID, Slot>()
    const lock = Semaphore.makeUnsafe(1)
    const ready = yield* Latch.make(true)
    const pending = new Set<object>()
    let closed = false
    const holdUnsafe = () => {
      if (closed) return Effect.void
      const token = {}
      pending.add(token)
      ready.closeUnsafe()
      return Effect.sync(() => {
        if (pending.delete(token) && pending.size === 0) ready.openUnsafe()
      })
    }
    const hold = () => Effect.sync(holdUnsafe)
    const pendingFailures = yield* Queue.unbounded<PendingFailure>()
    let discovered: readonly Failure[] = []
    let inventory: Plugin.Info[] = []
    const list = Effect.fn("Plugin.list")(function* () {
      return inventory
    })
    const host = yield* PluginHost.make({ list })
    const load = Effect.fnUntraced(function* (plugin: Generation) {
      const activation: Activation = { plugin, scope: yield* Scope.fork(scope) }
      const inherit = yield* State.inherit()
      const grouped = State.group((failure, refresh) => {
        activation.failure = {
          error: `Plugin disabled after ${failure.state}.transform failed. Check server logs for details.`,
          ref: `err_${crypto.randomUUID().slice(0, 8)}`,
        }
        Queue.offerUnsafe(pendingFailures, {
          plugin,
          scope: activation.scope,
          failure,
          refresh,
          ref: activation.failure.ref,
          release: holdUnsafe(),
        })
      })
      const exit = yield* Effect.suspend(() =>
        plugin.effect({ ...host, storage: PluginHost.storage(kv, plugin.id) }),
      ).pipe(
        grouped,
        inherit,
        Effect.updateContext((context: Context.Context<never>) =>
          Context.make(Scope.Scope, activation.scope).pipe(
            Context.add(Logger.CurrentLoggers, Context.get(context, Logger.CurrentLoggers)),
            Context.add(References.MinimumLogLevel, Context.get(context, References.MinimumLogLevel)),
          ),
        ),
        Effect.withSpan("Plugin.load", { attributes: { "plugin.id": plugin.id } }),
        Effect.onExit((exit) =>
          Exit.isFailure(exit) && !activation.failure ? Scope.close(activation.scope, exit) : Effect.void,
        ),
        Effect.exit,
      )
      if (activation.failure || Exit.isSuccess(exit)) return { activation } as const
      yield* Effect.logWarning("failed to load plugin", {
        "plugin.id": plugin.id,
        cause: exit.cause,
      })
      return { error: Cause.pretty(exit.cause) } as const
    })

    const activate = Effect.fn("Plugin.activate")(function* (
      plugins: readonly Generation[],
      failures: readonly Failure[] = [],
    ) {
      const definitions = plugins.map((plugin) => ({ ...plugin, id: Plugin.ID.make(plugin.id) }))
      const ids = new Set<Plugin.ID>()
      for (const definition of definitions) {
        if (ids.has(definition.id)) yield* Effect.die(new Error(`Duplicate plugin ID: ${definition.id}`))
        ids.add(definition.id)
      }

      yield* Effect.acquireUseRelease(
        hold(),
        () =>
          lock.withPermit(
            Effect.gen(function* () {
              if (closed) return
              discovered = failures
              const current = Array.from(active.values())
              const changed = definitions.findIndex((definition, index) => {
                const entry = current[index]
                return entry?.plugin.id !== definition.id || entry.plugin.revision !== definition.revision
              })
              const prefix = changed === -1 ? definitions.length : changed
              for (const definition of definitions.slice(0, prefix)) {
                const entry = active.get(definition.id)
                if (entry) active.set(definition.id, { ...entry, plugin: definition })
              }
              if (prefix === definitions.length && active.size === definitions.length) {
                const nextInventory = [...Array.from(active.values()).map(slotInfo), ...failures]
                if (JSON.stringify(inventory) === JSON.stringify(nextInventory)) return
                inventory = nextInventory
                yield* bus.publish(Plugin.Event.Updated, {})
                return
              }

              yield* State.batch(
                Effect.gen(function* () {
                  // Registrations are ordered by setup, so only the unchanged prefix can stay alive.
                  const previous = new Map(Array.from(active.entries()).slice(prefix))
                  yield* Effect.forEach(
                    Array.from(previous.entries()).toReversed(),
                    ([id, slot]) =>
                      Effect.gen(function* () {
                        active.delete(id)
                        if (slot.activation && !slot.activation.failure)
                          yield* Scope.close(slot.activation.scope, Exit.void)
                      }),
                    { discard: true },
                  )
                  for (const definition of definitions.slice(prefix)) {
                    const slot = previous.get(definition.id)
                    // Reordering healthy registrations does not authorize retrying a failed revision.
                    if (slot?.activation?.failure && slot.plugin.revision === definition.revision) {
                      active.set(definition.id, { ...slot, plugin: definition })
                      continue
                    }
                    const result = yield* load(definition)
                    if (result.activation !== undefined) {
                      active.set(definition.id, {
                        plugin: definition,
                        activation: result.activation,
                      })
                      continue
                    }
                    active.set(definition.id, { plugin: definition, error: result.error })

                    const fallback = slot?.activation
                    if (!fallback || fallback.failure) continue
                    const restored = yield* load(fallback.plugin)
                    if (restored.activation !== undefined) {
                      active.set(definition.id, {
                        plugin: definition,
                        activation: restored.activation,
                        error: result.error,
                      })
                      continue
                    }
                    yield* Effect.logError("failed to restore plugin; deactivating", {
                      "plugin.id": definition.id,
                    })
                  }

                  inventory = [...Array.from(active.values()).map(slotInfo), ...failures]
                }),
              )
              yield* bus.publish(Plugin.Event.Updated, {})
            }),
          ),
        (release) => release,
      )
    })

    yield* Queue.take(pendingFailures).pipe(
      Effect.flatMap((item) =>
        Effect.gen(function* () {
          yield* Effect.logWarning("disabled plugin after transform failure", {
            "plugin.id": item.plugin.id,
            state: item.failure.state,
            ref: item.ref,
            cause: Cause.die(item.failure.cause),
          })
          yield* lock.withPermit(
            Effect.gen(function* () {
              if (closed) return
              // Failure is already recorded on its exact activation, so an old queued item
              // cannot disable a replacement and teardown need not wait for this worker.
              inventory = [...Array.from(active.values()).map(slotInfo), ...discovered]
              const refreshed = yield* State.batch(item.refresh).pipe(Effect.exit)
              yield* bus.publish(Plugin.Event.Updated, {})
              if (Exit.isFailure(refreshed))
                yield* Effect.logWarning("failed to refresh state after disabling plugin", {
                  "plugin.id": item.plugin.id,
                  ref: item.ref,
                  cause: refreshed.cause,
                })
            }),
          )
        }).pipe(
          // Cleanup must also be scheduled if an inventory observer fails. User finalizers
          // may await readiness, so never join them under the activation lock or readiness hold.
          Effect.ensuring(
            Scope.close(item.scope, Exit.void).pipe(
              Effect.catchCause((cause) =>
                Effect.logWarning("failed to clean up disabled plugin", {
                  "plugin.id": item.plugin.id,
                  ref: item.ref,
                  cause,
                }),
              ),
              Effect.forkScoped({ startImmediately: true }),
            ),
          ),
          Effect.catchCauseIf(
            (cause) => !Cause.hasInterrupts(cause),
            (cause) =>
              Effect.logError("failed to report disabled plugin", {
                "plugin.id": item.plugin.id,
                ref: item.ref,
                cause,
              }),
          ),
          Effect.ensuring(item.release),
        ),
      ),
      Effect.forever,
      Effect.forkScoped,
    )

    const close = (exit: Exit.Exit<unknown, unknown>) =>
      lock.withPermit(
        Effect.gen(function* () {
          closed = true
          pending.clear()
          ready.openUnsafe()
          active.clear()
          yield* State.shutdown(Scope.close(scope, exit))
        }),
      )
    yield* Effect.addFinalizer(close)

    return Service.of({
      activate,
      close,
      awaitActivation: ready.await,
      hold,
      list,
    })
  }),
)

// `plugin` is the requested definition; `activation` is its last activation, which may have
// failed or be an older fallback while the requested revision keeps failing setup.
type Slot = {
  readonly plugin: Generation
  readonly activation?: Activation
  readonly error?: string
}

// Share the activation across slot snapshots so teardown sees failures synchronously,
// including failures discovered after activate() has captured its previous slots.
type Activation = {
  readonly plugin: Generation
  readonly scope: Scope.Closeable
  failure?: { readonly error: string; readonly ref: string }
}

type PendingFailure = {
  readonly plugin: Generation
  readonly scope: Scope.Closeable
  readonly failure: State.Failure
  readonly refresh: Effect.Effect<void>
  readonly ref: string
  readonly release: Effect.Effect<void>
}

function slotInfo(slot: Slot): Plugin.Info {
  const failure = slot.activation?.failure ?? (slot.error === undefined ? undefined : { error: slot.error })
  return {
    id: Plugin.ID.make(slot.plugin.id),
    source: slot.plugin.source ?? { type: "builtin" },
    state: failure === undefined ? { status: "active" } : { status: "failed", ...failure },
    features: { server: true, ...slot.plugin.features },
  }
}

export const node: LayerNode.Provider<Service, PersistentPty.UnavailableError, typeof Node.tags.values.location> =
  Node.makeLocationNode({
    service: Service,
    layer,
    deps: [PluginHost.requirements],
  })

export * as CommandPlugin from "./command.js"

import { define } from "@opencode/plugin/effect/plugin"
import { Effect, Stream } from "effect"
import { Bus } from "../bus.js"
import { Location } from "../location.js"
import { Mcp } from "../mcp/index.js"
import PROMPT_INITIALIZE from "./command/initialize.txt"
import PROMPT_REVIEW from "./command/review.txt"

export const Plugin = define({
  id: "opencode.command",
  effect: Effect.fn(function* (ctx) {
    const location = yield* Location.Service
    const mcp = yield* Mcp.Service
    const bus = yield* Bus.Service
    const loaded = { prompts: [] as Mcp.Prompt[] }
    yield* bus.subscribe(Mcp.PromptsChanged).pipe(
      Stream.runForEach(() =>
        mcp.prompts().pipe(
          Effect.tap((prompts) => Effect.sync(() => (loaded.prompts = prompts))),
          Effect.andThen(ctx.command.reload()),
        ),
      ),
      Effect.forkScoped({ startImmediately: true }),
    )
    loaded.prompts = yield* mcp.prompts()
    yield* ctx.command.transform((editor) => {
      editor.add({
        name: "init",
        description: "guided AGENTS.md setup",
        execute: (input) =>
          ctx.session
            .prompt({
              ...input.prompt,
              sessionID: input.sessionID,
              text: append(PROMPT_INITIALIZE.replace("${path}", location.project.directory), input.prompt.text),
              delivery: input.delivery,
            })
            .pipe(Effect.asVoid),
      })
      editor.add({
        name: "review",
        description: "review changes [commit|branch|pr], defaults to uncommitted",
        execute: (input) =>
          ctx.session
            .prompt({
              ...input.prompt,
              sessionID: input.sessionID,
              text: append(PROMPT_REVIEW.replace("${path}", location.project.directory), input.prompt.text),
              delivery: input.delivery,
            })
            .pipe(Effect.asVoid),
      })
      for (const prompt of loaded.prompts) {
        editor.add({
          name: mcpCommandName(prompt.server, prompt.name),
          description: prompt.description,
          execute: (input) =>
            Effect.gen(function* () {
              const args = parseArguments(input.prompt.text)
              const result = yield* mcp.prompt({
                server: prompt.server,
                name: prompt.name,
                args: Object.fromEntries(
                  (prompt.arguments ?? []).map((argument, index) => [argument.name, args[index] ?? ""]),
                ),
              })
              if (!result) return yield* Effect.fail(new Error(`MCP prompt not found: ${prompt.server}:${prompt.name}`))
              yield* ctx.session.prompt({
                ...input.prompt,
                sessionID: input.sessionID,
                text: result.messages
                  .map((message) => promptMessageText(message.content))
                  .join("\n")
                  .trim(),
                delivery: input.delivery,
              })
            }).pipe(Effect.asVoid),
        })
      }
    })
  }),
})

function append(template: string, input: string) {
  const value = input.trim()
  if (template.includes("$ARGUMENTS")) return template.replaceAll("$ARGUMENTS", () => value)
  return [template, value].filter(Boolean).join("\n\n")
}

function parseArguments(input: string) {
  return (input.match(argsRegex) ?? []).map((argument) => argument.replace(quoteTrimRegex, ""))
}

function promptMessageText(content: unknown) {
  if (typeof content === "string") return content
  if (!content || typeof content !== "object") return ""
  if (!("type" in content) || content.type !== "text") return ""
  if (!("text" in content) || typeof content.text !== "string") return ""
  return content.text
}

function mcpCommandName(server: string, prompt: string) {
  return `${sanitize(server)}:${sanitize(prompt)}`
}

function sanitize(value: string) {
  return value.replace(/[^a-zA-Z0-9_-]/g, "_")
}

const argsRegex = /(?:\[Image\s+\d+\]|"[^"]*"|'[^']*'|[^\s"']+)/gi
const quoteTrimRegex = /^["']|["']$/g

export * as PluginHooks from "./hooks.js"

import type { AISDKHooks } from "@opencode/plugin/effect/aisdk"
import type { SessionHooks } from "@opencode/plugin/effect/session"
import type { ShellHooks } from "@opencode/plugin/effect/shell"
import type { ToolFailures, ToolHooks } from "@opencode/plugin/effect/tool"
import type { ModelHookOptions } from "@opencode/plugin/effect/registration"
import type { PermissionHooks } from "@opencode/plugin/effect/permission"
import { Context, Effect, Layer, Scope } from "effect"
import { makeLocationNode } from "@opencode/util/effect/app-node"
import { State } from "../state.js"

export interface Domains {
  readonly aisdk: AISDKHooks
  readonly session: SessionHooks
  readonly permission: PermissionHooks
  readonly shell: ShellHooks
  readonly tool: ToolHooks
}

type NoFailures<Spec> = { readonly [Name in keyof Spec]: never }

// Failure channel for each hook event. Only tool execute.before may fail: a Tool.Error rejects the call before it runs.
interface Failures extends Record<keyof Domains, unknown> {
  readonly aisdk: NoFailures<AISDKHooks>
  readonly session: NoFailures<SessionHooks>
  readonly permission: NoFailures<PermissionHooks>
  readonly shell: NoFailures<ShellHooks>
  readonly tool: ToolFailures
}

type Callback<Event, Error> = (event: Event) => Effect.Effect<void, Error>
type Entry = { readonly callback: Function; readonly options?: ModelHookOptions }

const eventProviderID = (event: unknown) => {
  if (typeof event !== "object" || event === null || !("model" in event)) return undefined
  const model = event.model
  if (typeof model !== "object" || model === null || !("providerID" in model)) return undefined
  return typeof model.providerID === "string" ? model.providerID : undefined
}

export interface Interface {
  readonly has: <Domain extends keyof Domains>(
    domain: Domain,
    name: keyof Domains[Domain] & keyof Failures[Domain],
    providerID?: string,
  ) => Effect.Effect<boolean>
  readonly register: <Domain extends keyof Domains, Name extends keyof Domains[Domain] & keyof Failures[Domain]>(
    domain: Domain,
    name: Name,
    callback: Callback<Domains[Domain][Name], Failures[Domain][Name]>,
    options?: ModelHookOptions,
  ) => Effect.Effect<State.Registration, never, Scope.Scope>
  readonly trigger: <Domain extends keyof Domains, Name extends keyof Domains[Domain] & keyof Failures[Domain]>(
    domain: Domain,
    name: Name,
    event: Domains[Domain][Name],
  ) => Effect.Effect<Domains[Domain][Name], Failures[Domain][Name]>
}

export class Service extends Context.Service<Service, Interface>()("@opencode/PluginHooks") {}

const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const callbacks = new Map<string, Entry[]>()
    const key = (domain: keyof Domains, name: PropertyKey) => `${domain}.${String(name)}`

    const register: Interface["register"] = Effect.fn("PluginHooks.register")(
      function* (domain, name, callback, options) {
        const scope = yield* Scope.Scope
        const id = key(domain, name)
        let active = true
        const entry = { callback, options }
        callbacks.set(id, [...(callbacks.get(id) ?? []), entry])
        const dispose = Effect.sync(() => {
          if (!active) return
          active = false
          const next = (callbacks.get(id) ?? []).filter((item) => item !== entry)
          if (next.length === 0) callbacks.delete(id)
          else callbacks.set(id, next)
        })
        yield* Scope.addFinalizer(scope, dispose)
        return { dispose }
      },
    )

    const trigger: Interface["trigger"] = Effect.fnUntraced(function* (domain, name, event) {
      for (const entry of callbacks.get(key(domain, name)) ?? []) {
        if (entry.options?.providerID !== undefined && entry.options.providerID !== eventProviderID(event)) continue
        const result: Effect.Effect<void, Failures[typeof domain][typeof name]> = entry.callback(event)
        yield* result
      }
      return event
    })

    const has: Interface["has"] = (domain, name, providerID) =>
      Effect.sync(() =>
        (callbacks.get(key(domain, name)) ?? []).some(
          (entry) => entry.options?.providerID === undefined || entry.options.providerID === providerID,
        ),
      )

    return Service.of({ has, register, trigger })
  }),
)

export const node = makeLocationNode({ service: Service, layer, deps: [] })

