export function identity(model: { readonly name: string; readonly ref: Model.Ref }) {
  return [
    "# Your Model",
    `- Name: ${model.name}`,
    `- Provider ID: ${model.ref.providerID}`,
    `- Model ID: ${model.ref.id}`,
  ].join("\n")
}

export const Plugin = define({
  id: "opencode.prompt.identity",
  effect: Effect.fn("IdentityPlugin")(function* (ctx) {
    const hook = (event: SessionHooks["context"]) =>
      Effect.gen(function* () {
        const model =
          (yield* ctx.model.list()).data.find(
            (model) => model.providerID === event.model.providerID && model.id === event.model.id,
          ) ?? Model.Info.default(event.model.providerID, event.model.id)
        event.system.splice(1, 0, SystemPart.make(identity({ name: model.name, ref: event.model })))
      }).pipe(Effect.catch(() => Effect.void))
    yield* ctx.session.hook("context", hook)
    yield* ctx.session.hook("compaction", hook)
    yield* ctx.session.hook("generate", hook)
  }),
})

export * as InstancePlugins from "./instance.js"

import type { Plugin } from "@opencode/plugin/effect/plugin"
import { Context, Layer } from "effect"
import { makeLocationNode } from "@opencode/util/effect/app-node"
import type { Generation } from "../plugin.js"

/**
 * Holds the plugins one instance is born with. Unlike the host-global
 * `SdkPlugins` store, this list is a birth argument of a single instance:
 * `Instance.layer` binds it through the replacement mechanism, so two
 * instances in one process can carry different plugins. The list is immutable
 * for the instance's lifetime; runtime dynamism lives inside plugins through
 * the container transform/reload APIs.
 *
 * Config plugin operations may disable instance plugins by id, matching
 * `SdkPlugins` behavior.
 */
export type List = readonly Plugin[]

export interface Interface {
  readonly all: () => readonly Generation[]
}

export class Service extends Context.Service<Service, Interface>()("@opencode/InstancePlugins") {}

export const node = makeLocationNode({
  service: Service,
  layer: bound([]),
  deps: [],
})

// The constant revision is load-bearing: the plugin registry treats an
// unchanged (id, revision) pair as the same plugin across activations, which
// is only correct because a bound list never changes after creation.
// `source: "sdk"` means host-contributed; an instance list is the
// per-instance form of the same channel.
export function bound(plugins: List) {
  const duplicates = plugins.filter((plugin, index) => plugins.findIndex((other) => other.id === plugin.id) !== index)
  if (duplicates.length > 0) {
    throw new Error(`duplicate instance plugin ids: ${duplicates.map((plugin) => plugin.id).join(", ")}`)
  }
  const stamped = plugins.map((plugin): Generation => ({ ...plugin, revision: "instance", source: { type: "sdk" } }))
  return Layer.succeed(Service, Service.of({ all: () => stamped }))
}

export * as McpCodeModeDefaultsPlugin from "./mcp-codemode-defaults.js"

import { define } from "@opencode/plugin/effect/plugin"
import { Effect } from "effect"

// Defaults that make known MCP servers work well with OpenCode Code Mode, so a server's own Code Mode never ends up
// nested inside OpenCode's. A server with `codemode` set in config is left exactly as configured.

// These servers are Code Mode themselves, so OpenCode Code Mode is turned off for them (`codemode: false`).
const urls = [/^https:\/\/executor\.sh\/[^/]+\/mcp$/]

// PostHog wraps all of its tools in one server-side Code Mode tool unless the client asks for "tools" mode, so OpenCode
// Code Mode stays on and PostHog's is turned off. PostHog also reads `?mode=`, but the header wins over it and leaves
// the URL, which stored credentials are keyed by, unchanged.
const posthog = /^mcp(?:-eu|\.us|\.eu)?\.posthog\.com$/
const mode = "x-posthog-mcp-mode"

export const Plugin = define({
  id: "opencode.mcp.codemode.defaults",
  effect: Effect.fn(function* (ctx) {
    yield* ctx.mcp.transform((editor) => {
      for (const [, server] of editor.list()) {
        if (server.codemode !== undefined) continue
        if (server.type === "local") {
          if (server.command[0] === "executor" && server.command[1] === "mcp") server.codemode = false
          continue
        }
        if (!URL.canParse(server.url)) continue
        const url = new URL(server.url)
        const endpoint = `${url.origin}${url.pathname.replace(/\/+$/, "")}`
        if (urls.some((pattern) => pattern.test(endpoint))) server.codemode = false
        if (
          posthog.test(url.hostname) &&
          !url.searchParams.has("mode") &&
          !Object.keys(server.headers ?? {}).some((key) => key.toLowerCase() === mode)
        )
          server.headers = { ...server.headers, [mode]: "tools" }
      }
    })
  }),
})

