export * as PluginSourceDirectory from "./source-directory.js"

import { FSUtil } from "@opencode/util/fs-util"
import { Effect, Option } from "effect"
import path from "path"

export const names = ["plugin", "plugins"] as const

export const discover = Effect.fn("PluginSourceDirectory.discover")(function* (
  fs: FSUtil.Interface,
  directory: string,
) {
  const children = (yield* Effect.forEach(names, (source) =>
    fs.readDirectoryEntries(path.join(directory, source)).pipe(
      Effect.orElseSucceed(() => []),
      Effect.map((entries) => entries.map((entry) => ({ ...entry, target: path.join(directory, source, entry.name) }))),
    ),
  ))
    .flat()
    .sort((a, b) => (a.target < b.target ? -1 : a.target > b.target ? 1 : 0))
  const targets = yield* Effect.forEach(children, (entry) =>
    Effect.gen(function* () {
      const source = entry.target.endsWith(".ts") || entry.target.endsWith(".js")
      if (entry.type === "file" && source) return Option.some(entry.target)
      if (entry.type === "directory") return Option.some(entry.target)
      if (entry.type !== "symlink") return Option.none<string>()
      if (source && (yield* fs.isFile(entry.target))) return Option.some(entry.target)
      if (yield* fs.isDir(entry.target)) return Option.some(entry.target)
      return Option.none<string>()
    }),
  )
  return targets.flatMap(Option.toArray)
})

export * as PluginSupervisor from "./supervisor.js"

import { Event } from "@opencode/schema/config"
import { Cause, Effect, Layer, Queue, Stream } from "effect"
import path from "path"
import { ConfigPluginSource } from "../config/plugin/source.js"
import { makeLocationNode } from "@opencode/util/effect/app-node"
import { ManagedPolicy } from "../managed-policy.js"
import { Bus } from "../bus.js"
import { Npm } from "@opencode/util/npm"
import { Plugin } from "../plugin.js"
import { InstancePlugins } from "./instance.js"
import { PluginInternal } from "./internal.js"
import { PluginModule } from "./module.js"
import { SdkPlugins } from "./sdk.js"
import { PluginUpdate } from "./update.js"
import { Watcher } from "../filesystem/watcher.js"

const resolve = Effect.fn("PluginSupervisor.resolve")(function* (
  modules: Effect.Success<ReturnType<typeof PluginModule.make>>,
  pre: readonly Plugin.Generation[],
  post: readonly Plugin.Generation[],
  operations: readonly ConfigPluginSource.Operation[],
  install: boolean,
  running: ReadonlyMap<string, Plugin.Generation>,
) {
  const matches = (selector: string, target: string) =>
    selector === "*" || (selector.endsWith(".*") ? target.startsWith(selector.slice(0, -1)) : selector === target)
  const definitions = [...pre, ...post]
  const enabled = new Set(definitions.map((plugin) => plugin.id))
  const packages = new Map<string, Plugin.Generation>()
  const pending = new Set<string>()
  const failures = new Map<
    string,
    Plugin.Info & { readonly state: Extract<Plugin.State, { readonly status: "failed" }> }
  >()
  const plugins = () => [...definitions, ...packages.values()]

  for (const operation of operations) {
    if (operation.type === "remove") {
      if (operation.target === "*") failures.clear()
      plugins()
        .filter((plugin) => matches(operation.target, plugin.id) && !PluginInternal.guarded.has(plugin.id))
        .forEach((plugin) => enabled.delete(plugin.id))
      continue
    }

    const matched = plugins().filter((plugin) => matches(operation.target, plugin.id))
    const selectsPlugins =
      matched.length > 0 ||
      operation.target === "*" ||
      operation.target.endsWith(".*") ||
      operation.target.startsWith("opencode.")
    if (selectsPlugins) {
      matched.forEach((plugin) => enabled.add(plugin.id))
      continue
    }

    const plugin = yield* modules.load(operation, { install }).pipe(
      Effect.catchCause((cause) => {
        const ref = `err_${crypto.randomUUID().slice(0, 8)}`
        const error = Cause.squash(cause)
        return Effect.logWarning("failed to load plugin", { target: operation.target, ref, cause }).pipe(
          Effect.as({ error: error instanceof PluginModule.LoadError ? error.message : "Plugin failed to load", ref }),
        )
      }),
    )
    if ("blocked" in plugin) {
      const previous = packages.get(operation.target)
      if (previous) enabled.delete(previous.id)
      packages.delete(operation.target)
      failures.delete(operation.target)
      continue
    }
    if ("pending" in plugin) {
      pending.add(operation.target)
      continue
    }
    if ("error" in plugin) {
      failures.set(operation.target, {
        source: pluginSource(operation.target),
        state: { status: "failed", error: plugin.error, ref: plugin.ref },
        features: { server: true },
      })
      // The new revision never became a generation, so the one already running keeps its place.
      const retained = packages.get(operation.target) ?? running.get(operation.target)
      if (!retained) continue
      packages.set(operation.target, retained)
      enabled.add(retained.id)
      continue
    }
    failures.delete(operation.target)
    const previous = packages.get(operation.target)
    if (previous) enabled.delete(previous.id)
    packages.set(operation.target, plugin)
    enabled.add(plugin.id)
  }

  const ordered = [
    ...pre.filter((plugin) => enabled.has(plugin.id)),
    ...[...packages.values()].filter((plugin) => enabled.has(plugin.id)),
    ...post.filter((plugin) => enabled.has(plugin.id)),
  ]
  // Registry activation dies on a duplicate ID, which would drop the whole generation including builtins.
  // Keep the first occurrence in boot order and report later ones like any other plugin setup failure.
  const duplicate = (plugin: Plugin.Generation, index: number) =>
    ordered.findIndex((other) => other.id === plugin.id) !== index
  return {
    plugins: ordered.filter((plugin, index) => !duplicate(plugin, index)),
    packages: new Map([...packages].filter(([, plugin]) => enabled.has(plugin.id))),
    failures: [
      ...failures.values(),
      ...ordered.filter(duplicate).map((plugin) => ({
        id: Plugin.ID.make(plugin.id),
        source: plugin.source ?? { type: "builtin" as const },
        state: { status: "failed" as const, error: `Duplicate plugin ID: ${plugin.id}` },
        features: { server: true as const, ...plugin.features },
      })),
    ],
    pending: [...pending],
  }
})

export const layer = Layer.effectDiscard(
  Effect.gen(function* () {
    const managed = yield* ManagedPolicy.Service
    const registry = yield* Plugin.Service
    const sdk = yield* SdkPlugins.Service
    const instance = yield* InstancePlugins.Service
    const sources = yield* ConfigPluginSource.Service
    const modules = yield* PluginModule.make()
    const bus = yield* Bus.Service
    const updates = yield* PluginUpdate.Service
    const internal = yield* PluginInternal.list()
    let release: Effect.Effect<void> | undefined = yield* registry.hold()
    yield* Effect.addFinalizer(() => release ?? Effect.void)
    // Built-ins capture services from this layer; unload them before those services close.
    yield* Effect.addFinalizer(registry.close)
    let packages = new Set<string>()
    // Last generation handed to the registry per target; a failed reload keeps it in place.
    let running = new Map<string, Plugin.Generation>()
    let outdated = new Set<string>()
    const updating = new Set<string>()
    let generation = 0
    let observed = 0

    const activate = Effect.fn("PluginSupervisor.activate")(function* () {
      const current = ++generation
      // Combine internal plugins with host-contributed plugins in boot order.
      // Instance-bound plugins come last: later activation can override earlier
      // container writes, so the instance's explicit choices win over globals.
      const pre = [
        ...internal.pre.map((plugin) => ({ ...plugin, revision: "internal", source: { type: "builtin" as const } })),
        ...sdk.all(),
        ...instance.all(),
      ]
      const post = internal.post.map((plugin) => ({
        ...plugin,
        revision: "internal",
        source: { type: "builtin" as const },
      }))
      const operations = yield* sources.operations()
      // Activate everything available locally before waiting on missing package installs.
      const immediate = yield* resolve(modules, pre, post, operations, false, running)
      const source = (source: Plugin.Source) =>
        source.type === "package"
          ? {
              ...source,
              ...(outdated.has(source.target) ? { outdated: true as const } : {}),
              ...(updating.has(source.target) ? { updating: true as const } : {}),
            }
          : source
      const apply = (resolved: typeof immediate) =>
        registry.activate(
          resolved.plugins.map((plugin) => (plugin.source ? { ...plugin, source: source(plugin.source) } : plugin)),
          resolved.failures.map((failure) => ({ ...failure, source: source(failure.source) })),
        )
      yield* apply(immediate)
      const resolved = immediate.pending.length
        ? yield* resolve(modules, pre, post, operations, true, running)
        : immediate
      if (resolved !== immediate) yield* apply(resolved)
      running = resolved.packages
      const targets = new Set(
        [...resolved.plugins, ...resolved.failures].flatMap((plugin) =>
          plugin.source?.type === "package" ? [plugin.source.target] : [],
        ),
      )
      packages = targets
      yield* Effect.forEach(
        targets,
        (target) => updates.check(target).pipe(Effect.map((available) => [target, available] as const)),
        { concurrency: "unbounded" },
      ).pipe(
        Effect.flatMap((checked) => {
          if (current !== generation) return Effect.void
          const next = new Set(checked.flatMap(([target, available]) => (available ? [target] : [])))
          if (next.size === outdated.size && [...next].every((target) => outdated.has(target))) return Effect.void
          outdated = next
          return apply(resolved)
        }),
        Effect.forkScoped({ startImmediately: true }),
      )
    })
    // Start source consumers before activation, without an extra merge/debounce boundary delaying them.
    // Each source owns its upstream subscriptions; the queue retains the latest observed request.
    const triggers = yield* Queue.sliding<number>(1)
    // Make accepted work visible to awaitActivation before coalescing the burst.
    const notify = Effect.gen(function* () {
      observed++
      if (!release) release = yield* registry.hold()
      yield* Queue.offer(triggers, observed)
    })
    const watch = <A>(stream: Stream.Stream<A>) =>
      stream.pipe(
        Stream.runForEach(() => notify),
        Effect.forkScoped({ startImmediately: true }),
      )
    yield* watch(sources.changes())
    yield* watch(modules.changes())
    yield* watch(managed.changes())
    yield* watch(Stream.fromEffectRepeat(Effect.sleep("24 hours")))
    yield* watch(bus.subscribe([Event.Updated, SdkPlugins.Updated]))
    yield* watch(
      updates.changes().pipe(
        Stream.filter((update) => packages.has(update.target)),
        Stream.tap((update) =>
          Effect.sync(() => {
            update.outdated ? outdated.add(update.target) : outdated.delete(update.target)
            update.updating ? updating.add(update.target) : updating.delete(update.target)
          }),
        ),
      ),
    )
    // Run initial activation immediately; debounce only later requests. One consumer serializes both.
    yield* Stream.concat(Stream.succeed(0), Stream.fromQueue(triggers).pipe(Stream.debounce("100 millis"))).pipe(
      Stream.runForEach((target) =>
        Effect.gen(function* () {
          yield* activate().pipe(Effect.catchCause((cause) => Effect.logError("failed to reload plugins", { cause })))
          if (observed !== target) return
          const settled = release
          release = undefined
          if (settled) yield* settled
        }),
      ),
      Effect.forkScoped({ startImmediately: true }),
    )
  }),
)

const nodeDeps = [
  Plugin.node,
  SdkPlugins.node,
  InstancePlugins.node,
  ConfigPluginSource.node,
  PluginUpdate.node,
  Bus.node,
  Npm.node,
  Watcher.node,
  PluginInternal.requirements,
] as const

function pluginSource(target: string): Plugin.Source {
  if (path.isAbsolute(target)) return { type: "local", path: target }
  return { type: "package", target }
}

export const node = makeLocationNode({ name: "plugin-supervisor", layer, deps: nodeDeps })

export * as ToolInputRepairPlugin from "./tool-input-repair.js"

import { define } from "@opencode/plugin/effect/plugin"
import { Effect, JsonSchema, Option, Predicate, Schema } from "effect"
import { definition } from "../tool/runtime.js"

// Repairs apply only when the input schema unambiguously supports them:
// - Stringified root or nested object: '{"limit":"20"}' -> { limit: 20 }
// - Closed object: { limit: "20", extra: true } -> { limit: 20 }
// - Optional null or empty-object placeholder: { limit: null } -> {}
// - Numeric or boolean string: { limit: "20", enabled: "false" } -> { limit: 20, enabled: false }
// - Nullable field: { count: "2" } -> { count: 2 }
// - Stringified array or compatible item: { tags: '["a"]', count: "2" } -> { tags: ["a"], count: [2] }
// - Positional tuple: { pair: ["2", "false"] } -> { pair: [2, false] }
// - Typed dictionary: { counts: { first: "2" } } -> { counts: { first: 2 } }
// - Nested fields and local references: { items: [{ count: "2" }] } -> { items: [{ count: 2 }] }

const decodeJson = Schema.decodeUnknownOption(Schema.fromJsonString(Schema.Unknown))
const maxDepth = 6

export const Plugin = define({
  id: "opencode.tool.input.repair",
  effect: (ctx) =>
    ctx.tool.hook("execute.before", (event) =>
      Effect.gen(function* () {
        // The outer Code Mode tool is built per snapshot rather than registered, so it cannot be
        // looked up here. Its `{ code }` input is trivial; the tools it calls are repaired normally.
        if (event.tool === "execute") return
        const tool = (yield* ctx.tool.list()).find((tool) => tool.id === event.tool)
        if (!tool) return
        const schema = definition(tool).inputSchema
        if (schema.type !== "object") return
        event.input = repair(event.input, schema, schema, 0)
      }),
    ),
})

function repair(value: unknown, schema: JsonSchema.JsonSchema, root: JsonSchema.JsonSchema, depth: number): unknown {
  if (depth > maxDepth) return value

  if (typeof schema.$ref === "string") {
    const definitions = /^#\/\$defs\/[^/]+$/.test(schema.$ref)
      ? root.$defs
      : /^#\/definitions\/[^/]+$/.test(schema.$ref)
        ? root.definitions
        : undefined
    if (!Predicate.isObject(definitions)) return value
    const target = Object.fromEntries(
      Object.entries(definitions).filter((entry): entry is [string, JsonSchema.JsonSchema] =>
        Predicate.isObject(entry[1]),
      ),
    )[
      schema.$ref
        .slice(schema.$ref.lastIndexOf("/") + 1)
        .replaceAll("~1", "/")
        .replaceAll("~0", "~")
    ]
    return target ? repair(value, target, root, depth + 1) : value
  }

  if (Array.isArray(schema.type)) {
    if (value === null && schema.type.includes("null")) return value
    if (schema.type.includes(typeof value)) return value
    const types = schema.type.filter((type) => type !== "null")
    return types.length === 1 ? repair(value, { ...schema, type: types[0] }, root, depth + 1) : value
  }

  if (schema.type === undefined) {
    if (Array.isArray(schema.anyOf) && Array.isArray(schema.oneOf)) return value
    const branches = Array.isArray(schema.anyOf) ? schema.anyOf : schema.oneOf
    if (!Array.isArray(branches) || value === null) return value
    if (branches.some((branch) => !Predicate.isObject(branch) || branch.type === typeof value)) return value
    const candidates = branches.filter((branch) => Predicate.isObject(branch) && branch.type !== "null")
    return candidates.length === 1 ? repair(value, candidates[0], root, depth + 1) : value
  }

  if (schema.type === "number" || schema.type === "integer") {
    if (typeof value !== "string" || value.trim() === "") return value
    const parsed = Number(value)
    return Number.isFinite(parsed) && (schema.type !== "integer" || Number.isSafeInteger(parsed)) ? parsed : value
  }
  if (schema.type === "boolean") return value === "true" ? true : value === "false" ? false : value
  if (schema.type === "object") return repairObject(value, schema, root, depth)
  if (schema.type === "array") return repairArray(value, schema, root, depth)
  return value
}

function repairObject(
  value: unknown,
  schema: JsonSchema.JsonSchema,
  root: JsonSchema.JsonSchema,
  depth: number,
): unknown {
  const parsed = typeof value === "string" ? Option.getOrUndefined(decodeJson(value)) : value
  if (!Predicate.isObject(parsed)) return value

  const properties = Predicate.isObject(schema.properties) ? schema.properties : {}
  const required = Array.isArray(schema.required) ? schema.required : []
  const patterned = Predicate.isObject(schema.patternProperties)
  const composed = Array.isArray(schema.allOf) || Array.isArray(schema.anyOf) || Array.isArray(schema.oneOf)

  return Object.keys(parsed).reduce<Record<string, unknown>>((result, key) => {
    const current = result[key]
    const declared = Object.hasOwn(properties, key)
    const property = declared ? properties[key] : !patterned ? schema.additionalProperties : undefined

    if (!declared && schema.additionalProperties === false && !patterned && !composed) {
      const next = { ...result }
      delete next[key]
      return next
    }
    if (!Predicate.isObject(property)) return result

    // Only a bare single-type property provably rejects null and `{}`. Compositions, enums,
    // constants, references and nullable flags may accept them, so those are left alone.
    const plain =
      typeof property.type === "string" &&
      property.type !== "null" &&
      !composed &&
      ["anyOf", "oneOf", "allOf", "enum", "const", "$ref", "nullable"].every((keyword) => !(keyword in property))
    const placeholder = Predicate.isObject(current) && Object.keys(current).length === 0 && property.type !== "object"
    if (declared && !required.includes(key) && plain && (current === null || placeholder)) {
      const next = { ...result }
      delete next[key]
      return next
    }

    const repaired = repair(current, property, root, depth + 1)
    return repaired === current ? result : { ...result, [key]: repaired }
  }, parsed)
}

function repairArray(
  value: unknown,
  schema: JsonSchema.JsonSchema,
  root: JsonSchema.JsonSchema,
  depth: number,
): unknown {
  const parsed = typeof value === "string" ? Option.getOrUndefined(decodeJson(value)) : value
  const tuple = Array.isArray(schema.prefixItems)
    ? schema.prefixItems
    : Array.isArray(schema.items)
      ? schema.items
      : undefined

  if (Array.isArray(parsed)) {
    const repaired = parsed.map((item, index) => {
      const member = tuple
        ? (tuple[index] ?? (Array.isArray(schema.prefixItems) ? schema.items : schema.additionalItems))
        : schema.items
      return Predicate.isObject(member) ? repair(item, member, root, depth + 1) : item
    })
    return repaired.every((item, index) => item === parsed[index]) ? parsed : repaired
  }

  if (tuple || !Predicate.isObject(schema.items)) return value
  const repaired = repair(value, schema.items, root, depth + 1)
  const type = schema.items.type
  const compatible =
    type === "object"
      ? Predicate.isObject(repaired)
      : type === "array"
        ? Array.isArray(repaired)
        : type === "integer"
          ? typeof repaired === "number" && Number.isSafeInteger(repaired)
          : type === "number"
            ? typeof repaired === "number" && Number.isFinite(repaired)
            : (type === "string" || type === "boolean") && typeof repaired === type
  return compatible ? [repaired] : value
}

export * as PluginUpdate from "./update.js"

import { Clock, Context, Effect, Exit, Layer, Option, PubSub, Stream } from "effect"
import { Npm } from "@opencode/util/npm"
import { EffectFlock } from "@opencode/util/effect-flock"
import { makeGlobalNode } from "@opencode/util/effect/app-node"
import { KeyedMutex } from "../effect/keyed-mutex.js"

const interval = 24 * 60 * 60 * 1_000

interface Change {
  readonly target: string
  readonly outdated: boolean
  readonly updating: boolean
}

export interface Interface {
  readonly check: (target: string, options?: { readonly refresh?: boolean }) => Effect.Effect<boolean>
  readonly update: (target: string) => Effect.Effect<void, Npm.InstallFailedError | EffectFlock.LockError>
  readonly changes: () => Stream.Stream<Change>
}

export class Service extends Context.Service<Service, Interface>()("@opencode/PluginUpdate") {}

const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const npm = yield* Npm.Service
    const locks = KeyedMutex.makeUnsafe<string>()
    const status = new Map<string, { readonly outdated: boolean; readonly checkedAt: number }>()
    const changes = yield* PubSub.unbounded<Change>()

    return Service.of({
      check: (target, options) =>
        locks.withLock(target)(
          Effect.gen(function* () {
            const checkedAt = yield* Clock.currentTimeMillis
            const current = status.get(target)
            if (!options?.refresh && current && checkedAt - current.checkedAt < interval) return current.outdated
            const outdated = yield* npm.check(target).pipe(
              Effect.tapCause((cause) => Effect.logWarning("failed to check plugin update", { target, cause })),
              Effect.option,
            )
            const value = Option.getOrElse(outdated, () => current?.outdated ?? false)
            status.set(target, { outdated: value, checkedAt })
            if ((current?.outdated ?? false) !== value)
              yield* PubSub.publish(changes, { target, outdated: value, updating: false })
            return value
          }),
        ),
      // Serialize per target so a concurrent update cannot clear the in-progress flag of another still running.
      update: (target) =>
        locks.withLock(target)(
          Effect.gen(function* () {
            const outdated = status.get(target)?.outdated ?? false
            yield* PubSub.publish(changes, { target, outdated, updating: true })
            yield* npm.update(target).pipe(
              Effect.tap(() => Effect.sync(() => status.delete(target))),
              Effect.onExit((exit) =>
                PubSub.publish(changes, {
                  target,
                  outdated: Exit.isSuccess(exit) ? false : outdated,
                  updating: false,
                }),
              ),
            )
          }),
        ),
      changes: () => Stream.fromPubSub(changes),
    })
  }),
)

export const node = makeGlobalNode({ service: Service, layer, deps: [Npm.node] })

export * as VcsGitPlugin from "./git.js"

import { randomUUID } from "crypto"
import fs from "fs/promises"
import os from "os"
import path from "path"
import { define } from "@opencode/plugin/effect/plugin"
import { Effect } from "effect"
import { ChildProcess } from "effect/process"
import { FileDiff } from "@opencode/schema/file-diff"
import { Base, BranchList, FileStatus, Info, Mode } from "@opencode/schema/vcs"
import { AppProcess } from "@opencode/util/process"
import { Location } from "../../location.js"
import type { Adapter, BranchOptions, DiffOptions } from "../../vcs.js"
import { DiffError } from "../../vcs.js"
import { gitExecutable } from "../../util/git-executable.js"
import {
  chunksByFile,
  emptyPatch,
  MAX_PATCH_BYTES,
  MAX_TOTAL_PATCH_BYTES,
  PATCH_CONTEXT_LINES,
  splitGitPatch,
} from "../../vcs/patch.js"
import type { Patch } from "../../vcs/patch.js"

export const Plugin = define({
  id: "opencode.vcs.git",
  effect: Effect.fn("VcsGitPlugin")(function* (ctx) {
    const location = yield* Location.Service
    // Markerless locations need this definition to initialize their first repository.
    if (location.vcs && location.vcs.type !== "git") return

    const processes = yield* AppProcess.Service
    const adapter = make(processes, {
      directory: location.directory,
      worktree: location.project.directory,
    })

    yield* ctx.vcs.transform((editor) => {
      editor.add({
        id: "git",
        name: "Git",
        init: (input) =>
          Effect.gen(function* () {
            const result = yield* processes.run(
              ChildProcess.make(gitExecutable, ["init"], { cwd: input.worktree, stdin: "ignore" }),
            )
            if (result.exitCode !== 0) return yield* Effect.fail(new Error("Git initialization failed"))
          }),
        info: () => adapter.info(),
        base: () => adapter.base(),
        branches: (input) => adapter.branches({ search: input.search, limit: input.limit }),
        status: () => adapter.status(),
        diff: (input) => adapter.diff(input.mode, { context: input.context, base: input.base }),
      })
    })
  }),
})

/**
 * Git adapter for the Vcs service. Ported from the V1 pipeline: patches are
 * batched through one `git diff` invocation where possible and capped by
 * per-file and total byte budgets, falling back to empty patches when capped.
 */
function make(proc: AppProcess.Interface, input: { directory: string; worktree: string }) {
  // Listing commands scope pathspecs to the requested directory; per-file
  // commands run from the worktree root because git lists root-relative paths.
  const ctx: Ctx = { proc, git: makeGit(proc), directory: input.directory, worktree: input.worktree }

  return {
    info: Effect.fn("VcsGit.info")(function* () {
      const [current, root] = yield* Effect.all([ctx.git.branch(ctx.directory), ctx.git.defaultBranch(ctx.directory)], {
        concurrency: 2,
      })
      return { branch: { current, default: root?.name } } satisfies Info
    }),
    base: () => ctx.git.base(ctx.directory),
    branches: Effect.fn("VcsGit.branches")(function* (options?: BranchOptions) {
      return yield* ctx.git.branches(ctx.directory, options)
    }),
    status: Effect.fn("VcsGit.status")(function* () {
      const git = ctx.git
      const ref = (yield* git.hasHead(ctx.directory)) ? "HEAD" : undefined
      const [list, stats] = yield* Effect.all(
        [git.status(ctx.directory), ref ? git.stats(ctx.directory, ref) : Effect.succeed([] as Stat[])],
        { concurrency: 2 },
      )
      const map = nums(stats)
      const untracked = yield* untrackedBatch(
        ctx,
        list.filter((item) => item.status === "added" && !map.has(item.file)).map((item) => item.file),
      )
      return yield* Effect.forEach(
        list.toSorted((a, b) => a.file.localeCompare(b.file)),
        (item) =>
          Effect.gen(function* () {
            const stat =
              map.get(item.file) ??
              (item.status === "added"
                ? (untracked.stats.get(item.file) ?? (yield* git.statUntracked(ctx.worktree, item.file)))
                : undefined)
            return {
              file: item.file,
              additions: stat?.additions ?? 0,
              deletions: stat?.deletions ?? 0,
              status: item.status,
            } satisfies FileStatus
          }),
      )
    }),
    diff: Effect.fn("VcsGit.diff")(function* (mode: Mode, options?: DiffOptions) {
      const git = ctx.git
      if (mode === "working") {
        return yield* track(ctx, (yield* git.hasHead(ctx.directory)) ? "HEAD" : undefined, options)
      }

      if (!(yield* git.hasHead(ctx.directory))) {
        return mode === "committed" ? [] : yield* track(ctx, undefined, options)
      }
      const base = options?.base ?? (yield* git.defaultBranch(ctx.directory))?.ref
      const ref = base ? yield* git.mergeBase(ctx.directory, base) : undefined
      if (!ref) {
        return yield* new DiffError({
          message: base ? `No merge base available for ${base}` : "No review base available",
        })
      }
      return yield* diffAgainstRef(ctx, ref, { ...options, target: mode === "committed" ? "HEAD" : undefined })
    }),
  } satisfies Adapter
}

type Kind = FileStatus["status"]

interface Item {
  readonly file: string
  readonly code: string
  readonly status: Kind
}

interface Stat {
  readonly file: string
  readonly additions: number
  readonly deletions: number
}

interface GitDiffOptions extends DiffOptions {
  readonly target?: "HEAD"
}

interface PatchOptions extends GitDiffOptions {
  readonly maxOutputBytes?: number
}

interface Ctx {
  readonly proc: AppProcess.Interface
  readonly git: GitOps
  readonly directory: string
  readonly worktree: string
}

type GitOps = ReturnType<typeof makeGit>

const cfg = [
  "--no-optional-locks",
  "-c",
  "core.autocrlf=false",
  "-c",
  "core.fsmonitor=false",
  "-c",
  "core.longpaths=true",
  "-c",
  "core.symlinks=true",
  "-c",
  "core.quotepath=false",
] as const

const kind = (code: string): Kind => {
  if (code === "??") return "added"
  if (code.includes("U")) return "modified"
  if (code.includes("A") && !code.includes("D")) return "added"
  if (code.includes("D") && !code.includes("A")) return "deleted"
  return "modified"
}

const nuls = (text: string) => text.split("\0").filter(Boolean)

const numstat = (text: string) =>
  nuls(text).flatMap((item) => {
    const a = item.indexOf("\t")
    const b = item.indexOf("\t", a + 1)
    if (a === -1 || b === -1) return []
    const file = item.slice(b + 1)
    if (!file) return []
    const adds = item.slice(0, a)
    const dels = item.slice(a + 1, b)
    const additions = adds === "-" ? 0 : Number.parseInt(adds || "0", 10)
    const deletions = dels === "-" ? 0 : Number.parseInt(dels || "0", 10)
    return [
      {
        file,
        additions: Number.isFinite(additions) ? additions : 0,
        deletions: Number.isFinite(deletions) ? deletions : 0,
      } satisfies Stat,
    ]
  })

function makeGit(proc: AppProcess.Interface, env?: Record<string, string>) {
  const run = Effect.fnUntraced(
    function* (args: string[], opts: { cwd: string; maxOutputBytes?: number }) {
      const result = yield* proc.run(
        ChildProcess.make(gitExecutable, [...cfg, ...args], {
          cwd: opts.cwd,
          env,
          extendEnv: true,
          stdin: "ignore",
        }),
        { maxOutputBytes: opts.maxOutputBytes },
      )
      return {
        exitCode: result.exitCode,
        text: () => result.stdout.toString("utf8"),
        truncated: result.stdoutTruncated || result.stderrTruncated,
      }
    },
    Effect.orElseSucceed(() => ({ exitCode: 1, text: () => "", truncated: false })),
  )

  const text = Effect.fnUntraced(function* (args: string[], opts: { cwd: string }) {
    return (yield* run(args, opts)).text()
  })

  const lines = Effect.fnUntraced(function* (args: string[], opts: { cwd: string }) {
    return (yield* text(args, opts))
      .split(/\r?\n/)
      .map((item) => item.trim())
      .filter(Boolean)
  })

  const configured = Effect.fnUntraced(function* (cwd: string, list: string[]) {
    const result = yield* run(["config", "init.defaultBranch"], { cwd })
    const name = result.text().trim()
    if (!name || !list.includes(name)) return
    return { name, ref: name }
  })

  const primary = Effect.fnUntraced(function* (cwd: string) {
    const list = yield* lines(["remote"], { cwd })
    if (list.includes("origin")) return "origin"
    if (list.length === 1) return list[0]
    if (list.includes("upstream")) return "upstream"
    return list[0]
  })

  const branch = Effect.fn("VcsGit.branch")(function* (cwd: string) {
    const result = yield* run(["symbolic-ref", "--quiet", "--short", "HEAD"], { cwd })
    if (result.exitCode !== 0) return
    return result.text().trim() || undefined
  })

  const branches = Effect.fn("VcsGit.branches")(function* (cwd: string, options?: BranchOptions) {
    const search = options?.search?.trim().replace(/[*?[\]\\]/g, "\\$&")
    return (yield* lines(
      [
        "for-each-ref",
        "--ignore-case",
        "--sort=refname",
        "--sort=-committerdate",
        "--format=%(refname:short)",
        ...(options?.limit ? [`--count=${options.limit}`] : []),
        ...(search ? [`refs/heads/*${search}*`, `refs/remotes/*${search}*`] : ["refs/heads", "refs/remotes"]),
      ],
      { cwd },
    )).filter((item) => !item.endsWith("/HEAD")) satisfies BranchList
  })

  const defaultBranch = Effect.fn("VcsGit.defaultBranch")(function* (cwd: string) {
    const remote = yield* primary(cwd)
    if (remote) {
      const head = yield* run(["symbolic-ref", `refs/remotes/${remote}/HEAD`], { cwd })
      if (head.exitCode === 0) {
        const ref = head
          .text()
          .trim()
          .replace(/^refs\/remotes\//, "")
        const name = ref.startsWith(`${remote}/`) ? ref.slice(`${remote}/`.length) : ""
        if (name) return { name, ref }
      }
    }

    const list = yield* lines(["for-each-ref", "--format=%(refname:short)", "refs/heads"], { cwd })
    const next = yield* configured(cwd, list)
    if (next) return next
    if (list.includes("main")) return { name: "main", ref: "main" }
    if (list.includes("master")) return { name: "master", ref: "master" }
  })

  const resolve = Effect.fnUntraced(function* (cwd: string, ref: string) {
    const result = yield* run(["rev-parse", "--verify", "--end-of-options", `${ref}^{commit}`], { cwd })
    if (result.exitCode !== 0) return
    return result.text().trim() || undefined
  })

  const ancestor = Effect.fnUntraced(function* (cwd: string, commit: string, ref: string) {
    if (!/^[a-f0-9]{40,64}$/.test(commit)) return false
    return (yield* run(["merge-base", "--is-ancestor", commit, ref], { cwd })).exitCode === 0
  })

  const namedRef = Effect.fnUntraced(function* (cwd: string, input: string) {
    // Creation hints must identify a branch, not HEAD, an object ID, or a revision expression.
    if (input === "HEAD" || input.endsWith("/HEAD") || /[~^:@{}\s]/.test(input)) return
    const ref = (yield* text(["rev-parse", "--symbolic-full-name", "--verify", "--end-of-options", input], {
      cwd,
    })).trim()
    if (!/^refs\/(heads|remotes)\/.+/.test(ref) || ref.endsWith("/HEAD") || !(yield* resolve(cwd, ref))) return
    return { name: ref.replace(/^refs\/heads\//, "").replace(/^refs\/remotes\/[^/]+\//, ""), ref }
  })

  const base = Effect.fn("VcsGit.base")(function* (cwd: string) {
    if (!(yield* hasHead(cwd))) return null
    const current = yield* branch(cwd)
    if (!current) return yield* new DiffError({ message: "Choose a review base" })
    const history = (yield* lines(
      ["reflog", "show", "--max-count=256", "--format=%H%x00%gs", `refs/heads/${current}`],
      {
        cwd,
      },
    )).flatMap((line) => {
      const match = /^([a-f0-9]+)\0(.+)$/.exec(line)
      return match ? [{ commit: match[1], message: match[2] }] : []
    })
    const renamed = history.some((entry) => entry.message.startsWith("Branch: renamed "))
    const creation = renamed ? undefined : history.find((entry) => entry.message.startsWith("branch: Created from "))
    const origin = creation?.message.slice("branch: Created from ".length)
    if (creation && origin) {
      const candidate = yield* namedRef(cwd, origin)
      if (
        candidate &&
        candidate.name !== current &&
        (yield* ancestor(cwd, creation.commit, "HEAD")) &&
        (yield* ancestor(cwd, creation.commit, candidate.ref))
      ) {
        return { ...candidate, source: "reflog" } satisfies Base
      }
    }
    const root = yield* defaultBranch(cwd)
    if (!root || current !== root.name) return yield* new DiffError({ message: "Choose a review base" })
    const candidate = yield* namedRef(cwd, root.ref)
    if (!candidate) return yield* new DiffError({ message: "The default review base is unavailable" })
    return { name: root.name, ref: candidate.ref, source: "default" } satisfies Base
  })

  const hasHead = Effect.fn("VcsGit.hasHead")(function* (cwd: string) {
    const result = yield* run(["rev-parse", "--verify", "HEAD"], { cwd })
    return result.exitCode === 0
  })

  const mergeBase = Effect.fn("VcsGit.mergeBase")(function* (cwd: string, base: string) {
    const ref = yield* resolve(cwd, base)
    if (!ref) return
    const result = yield* run(["merge-base", ref, "HEAD"], { cwd })
    if (result.exitCode !== 0) return
    return result.text().trim() || undefined
  })

  const status = Effect.fn("VcsGit.statusNames")(function* (cwd: string) {
    return nuls(
      yield* text(["status", "--porcelain=v1", "--untracked-files=all", "--no-renames", "-z", "--", "."], { cwd }),
    ).flatMap((item) => {
      const file = item.slice(3)
      if (!file) return []
      const code = item.slice(0, 2)
      return [{ file, code, status: kind(code) } satisfies Item]
    })
  })

  const diff = Effect.fn("VcsGit.diffNames")(function* (cwd: string, ref: string, target?: string) {
    const result = yield* run(
      ["diff", "--no-ext-diff", "--no-renames", "--name-status", "-z", ref, ...(target ? [target] : []), "--", "."],
      { cwd },
    )
    if (result.exitCode !== 0) return yield* new DiffError({ message: "Unable to list Git changes" })
    const list = nuls(result.text())
    return list.flatMap((code, idx) => {
      if (idx % 2 !== 0) return []
      const file = list[idx + 1]
      if (!code || !file) return []
      return [{ file, code, status: kind(code) } satisfies Item]
    })
  })

  const stats = Effect.fn("VcsGit.stats")(function* (cwd: string, ref: string, target?: string) {
    return numstat(
      yield* text(
        ["diff", "--no-ext-diff", "--no-renames", "--numstat", "-z", ref, ...(target ? [target] : []), "--", "."],
        { cwd },
      ),
    )
  })

  const patch = Effect.fn("VcsGit.patch")(function* (cwd: string, ref: string, file: string, options?: PatchOptions) {
    const result = yield* run(
      [
        "diff",
        "--patch",
        "--no-ext-diff",
        "--no-renames",
        `--unified=${options?.context ?? 3}`,
        ref,
        ...(options?.target ? [options.target] : []),
        "--",
        file,
      ],
      { cwd, maxOutputBytes: options?.maxOutputBytes },
    )
    return { text: result.truncated ? "" : result.text(), truncated: result.truncated } satisfies Patch
  })

  const patchAll = Effect.fn("VcsGit.patchAll")(function* (cwd: string, ref: string, options?: PatchOptions) {
    const result = yield* run(
      [
        "diff",
        "--patch",
        "--no-ext-diff",
        "--no-renames",
        `--unified=${options?.context ?? 3}`,
        ref,
        ...(options?.target ? [options.target] : []),
        "--",
        ".",
      ],
      { cwd, maxOutputBytes: options?.maxOutputBytes },
    )
    return { text: result.text(), truncated: result.truncated } satisfies Patch
  })

  const patchUntracked = Effect.fn("VcsGit.patchUntracked")(function* (
    cwd: string,
    file: string,
    options?: PatchOptions,
  ) {
    const result = yield* run(
      [
        "diff",
        "--no-index",
        "--patch",
        "--no-ext-diff",
        "--no-renames",
        `--unified=${options?.context ?? 3}`,
        "--",
        "/dev/null",
        file,
      ],
      { cwd, maxOutputBytes: options?.maxOutputBytes },
    )
    return { text: result.truncated ? "" : result.text(), truncated: result.truncated } satisfies Patch
  })

  const statUntracked = Effect.fn("VcsGit.statUntracked")(function* (cwd: string, file: string) {
    const result = yield* run(["diff", "--no-index", "--numstat", "--", "/dev/null", file], {
      cwd,
      maxOutputBytes: 4096,
    })
    if (result.truncated) return

    const parts = result.text().split("\t")
    if (parts.length < 2) return

    const additions = parts[0] === "-" ? 0 : Number.parseInt(parts[0] || "0", 10)
    const deletions = parts[1] === "-" ? 0 : Number.parseInt(parts[1] || "0", 10)
    return {
      file,
      additions: Number.isFinite(additions) ? additions : 0,
      deletions: Number.isFinite(deletions) ? deletions : 0,
    } satisfies Stat
  })

  // Paths are literal so names containing pathspec magic such as `*` or `[` match only themselves.
  const intentToAdd = Effect.fn("VcsGit.intentToAdd")(function* (cwd: string, list: string) {
    yield* run(
      [
        "--literal-pathspecs",
        "-c",
        "core.splitIndex=false",
        "add",
        "--intent-to-add",
        "--force",
        "--sparse",
        "--ignore-errors",
        `--pathspec-from-file=${list}`,
        "--pathspec-file-nul",
      ],
      { cwd },
    )
  })

  const worktreeStats = Effect.fn("VcsGit.worktreeStats")(function* (cwd: string) {
    return numstat(yield* text(["diff", "--no-ext-diff", "--no-renames", "--numstat", "-z"], { cwd }))
  })

  const worktreePatch = Effect.fn("VcsGit.worktreePatch")(function* (cwd: string, options?: PatchOptions) {
    const result = yield* run(
      ["diff", "--patch", "--no-ext-diff", "--no-renames", `--unified=${options?.context ?? 3}`],
      { cwd, maxOutputBytes: options?.maxOutputBytes },
    )
    return { text: result.text(), truncated: result.truncated } satisfies Patch
  })

  return {
    branch,
    branches,
    base,
    defaultBranch,
    hasHead,
    mergeBase,
    status,
    diff,
    stats,
    patch,
    patchAll,
    patchUntracked,
    statUntracked,
    intentToAdd,
    worktreeStats,
    worktreePatch,
  }
}

const emptyUntracked = () => ({ stats: new Map<string, Stat>(), patches: new Map<string, string>() })

/**
 * Prefetches what `statUntracked` and `patchUntracked` report, in three Git processes instead of two
 * per file. The files are recorded intent-to-add in an otherwise empty throwaway index, so a plain
 * `git diff` against it shows exactly those files as new, with the same attribute handling and patch
 * text as `git diff --no-index /dev/null <file>`. Files the batch cannot reproduce byte for byte are
 * left out, and callers fall back to the per-file commands.
 */
const untrackedBatch = Effect.fnUntraced(function* (
  ctx: Ctx,
  files: readonly string[],
  // Patches are only built when requested; status needs line counts alone.
  patches?: DiffOptions,
) {
  const eligible = yield* Effect.promise(() =>
    Promise.all(
      files.map(async (file) => {
        // Directories (nested repositories) and symlinks diff differently through an index.
        if (file.endsWith("/")) return
        const stat = await fs.lstat(path.join(ctx.worktree, file)).catch(() => undefined)
        if (!stat?.isFile()) return
        // A file this large could crowd every other file out of the batch's output budget.
        if (stat.size > MAX_TOTAL_PATCH_BYTES / 2) return
        return file
      }),
    ).then((list) => list.filter((file) => file !== undefined)),
  )
  // The batch costs up to three processes; for a single file the per-file commands are cheaper.
  if (eligible.length < 2) return emptyUntracked()

  return yield* Effect.acquireUseRelease(
    Effect.promise(async () => {
      const base = path.join(os.tmpdir(), `opencode-untracked-${randomUUID()}`)
      await fs.writeFile(`${base}.list`, eligible.map((file) => `${file}\0`).join(""))
      return base
    }),
    (base) =>
      Effect.gen(function* () {
        const git = makeGit(ctx.proc, { GIT_INDEX_FILE: `${base}.index` })
        yield* git.intentToAdd(ctx.worktree, `${base}.list`)
        const [stats, patch] = yield* Effect.all(
          [
            git.worktreeStats(ctx.worktree),
            patches
              ? git.worktreePatch(ctx.worktree, {
                  context: patches.context ?? PATCH_CONTEXT_LINES,
                  maxOutputBytes: MAX_TOTAL_PATCH_BYTES,
                })
              : Effect.succeed({ text: "", truncated: false } satisfies Patch),
          ],
          { concurrency: 2 },
        )
        const wanted = new Set(eligible)
        const headers = new Map<string, string>(eligible.map((file) => [`diff --git a/${file} b/${file}`, file]))
        return {
          stats: new Map(stats.filter((item) => wanted.has(item.file)).map((item) => [item.file, item] as const)),
          // Only chunks with the default `a/` and `b/` prefixes match the per-file output; configured
          // prefixes and quoted paths fall back to it.
          patches: new Map(
            splitGitPatch(patch).flatMap((chunk) => {
              const file = headers.get(chunk.slice(0, chunk.indexOf("\n")))
              return file === undefined ? [] : [[file, chunk] as const]
            }),
          ),
        }
      }),
    (base) =>
      Effect.promise(() =>
        Promise.all(
          [`${base}.list`, `${base}.index`, `${base}.index.lock`].map((file) => fs.rm(file, { force: true })),
        ),
      ),
  )
})

const nums = (list: Stat[]) =>
  new Map(list.map((item) => [item.file, { additions: item.additions, deletions: item.deletions }] as const))

const merge = (...lists: Item[][]) => {
  const out = new Map<string, Item>()
  lists.flat().forEach((item) => {
    if (!out.has(item.file)) out.set(item.file, item)
  })
  return [...out.values()]
}

const emptyBatch = () => ({ patches: new Map<string, string>(), capped: false })

const batchPatches = Effect.fnUntraced(function* (ctx: Ctx, ref: string, list: Item[], options?: GitDiffOptions) {
  if (list.length === 0) return emptyBatch()

  const result = yield* ctx.git.patchAll(ctx.directory, ref, {
    target: options?.target,
    context: options?.context ?? PATCH_CONTEXT_LINES,
    maxOutputBytes: MAX_TOTAL_PATCH_BYTES,
  })

  return {
    patches: chunksByFile(result, (index) => list[index]?.file),
    capped: result.truncated,
  }
})

const nativePatch = Effect.fnUntraced(function* (
  ctx: Ctx,
  ref: string | undefined,
  item: Item,
  options?: GitDiffOptions,
) {
  const result =
    item.code === "??" || !ref
      ? yield* ctx.git.patchUntracked(ctx.worktree, item.file, {
          context: options?.context ?? PATCH_CONTEXT_LINES,
          maxOutputBytes: MAX_PATCH_BYTES,
        })
      : yield* ctx.git.patch(ctx.worktree, ref, item.file, {
          target: options?.target,
          context: options?.context ?? PATCH_CONTEXT_LINES,
          maxOutputBytes: MAX_PATCH_BYTES,
        })
  if (!result.truncated && result.text) return result.text

  return emptyPatch(item.file)
})

const totalPatch = (file: string, patch: string, total: number) => {
  if (total + Buffer.byteLength(patch) <= MAX_TOTAL_PATCH_BYTES) return { patch, capped: false }
  return { patch: emptyPatch(file), capped: true }
}

const patchForItem = Effect.fnUntraced(function* (
  ctx: Ctx,
  ref: string | undefined,
  item: Item,
  batch: { patches: Map<string, string>; capped: boolean },
  untracked: Map<string, string>,
  capped: boolean,
  options?: GitDiffOptions,
) {
  if (capped) return emptyPatch(item.file)

  const batched = batch.patches.get(item.file)
  if (batched !== undefined) return batched
  if (item.code !== "??" && batch.capped) return emptyPatch(item.file)
  const prefetched = item.code === "??" || !ref ? untracked.get(item.file) : undefined
  if (prefetched !== undefined) return prefetched
  return yield* nativePatch(ctx, ref, item, options)
})

const files = Effect.fnUntraced(function* (
  ctx: Ctx,
  ref: string | undefined,
  list: Item[],
  map: Map<string, { additions: number; deletions: number }>,
  batch: { patches: Map<string, string>; capped: boolean },
  options?: GitDiffOptions,
) {
  const untracked = yield* untrackedBatch(
    ctx,
    list
      .filter(
        (item) => item.code === "??" || !ref || (!options?.target && item.status === "added" && !map.has(item.file)),
      )
      .map((item) => item.file),
    options ?? {},
  )
  const next: FileDiff.Info[] = []
  let total = 0
  let capped = false

  for (const item of list.toSorted((a, b) => a.file.localeCompare(b.file))) {
    const stat =
      map.get(item.file) ??
      (!options?.target && item.status === "added"
        ? (untracked.stats.get(item.file) ?? (yield* ctx.git.statUntracked(ctx.worktree, item.file)))
        : undefined)
    const patch = yield* patchForItem(ctx, ref, item, batch, untracked.patches, capped, options)
    const result: { patch: string; capped: boolean } = capped
      ? { patch, capped: true }
      : totalPatch(item.file, patch, total)
    capped = capped || result.capped
    if (!capped) {
      total += Buffer.byteLength(result.patch)
      capped = total >= MAX_TOTAL_PATCH_BYTES
    }
    next.push({
      file: item.file,
      patch: result.patch,
      additions: stat?.additions ?? 0,
      deletions: stat?.deletions ?? 0,
      status: item.status,
    })
  }

  return next
})

const diffAgainstRef = Effect.fnUntraced(function* (ctx: Ctx, ref: string, options?: GitDiffOptions) {
  const [list, stats, extra] = yield* Effect.all(
    [
      ctx.git.diff(ctx.directory, ref, options?.target),
      ctx.git.stats(ctx.directory, ref, options?.target),
      options?.target ? Effect.succeed([]) : ctx.git.status(ctx.directory),
    ],
    { concurrency: 3 },
  )
  return yield* files(
    ctx,
    ref,
    merge(
      list,
      extra.filter((item) => item.code === "??"),
    ),
    nums(stats),
    yield* batchPatches(ctx, ref, list, options),
    options,
  )
})

const track = Effect.fnUntraced(function* (ctx: Ctx, ref: string | undefined, options?: DiffOptions) {
  if (!ref) return yield* files(ctx, ref, yield* ctx.git.status(ctx.directory), new Map(), emptyBatch(), options)
  return yield* diffAgainstRef(ctx, ref, options)
})

export * as VcsHgPlugin from "./hg.js"

import path from "path"
import { Effect } from "effect"
import { ChildProcess } from "effect/process"
import { define } from "@opencode/plugin/effect/plugin"
import { FileDiff } from "@opencode/schema/file-diff"
import { FileStatus, Info, Mode } from "@opencode/schema/vcs"
import { FSUtil } from "@opencode/util/fs-util"
import { AppProcess } from "@opencode/util/process"
import { Location } from "../../location.js"
import type { Adapter, DiffOptions } from "../../vcs.js"
import { DiffError } from "../../vcs.js"
import {
  addPatch,
  chunksByFile,
  countPatch,
  deletePatch,
  emptyPatch,
  MAX_PATCH_BYTES,
  MAX_TOTAL_PATCH_BYTES,
  PATCH_CONTEXT_LINES,
} from "../../vcs/patch.js"

export const Plugin = define({
  id: "opencode.vcs.hg",
  effect: Effect.fn("VcsHgPlugin")(function* (ctx) {
    const location = yield* Location.Service
    // Markerless locations need this definition to initialize their first repository.
    if (location.vcs && location.vcs.type !== "hg") return

    const processes = yield* AppProcess.Service
    const fs = yield* FSUtil.Service
    const adapter = make(processes, fs, {
      directory: location.directory,
      worktree: location.project.directory,
    })

    yield* ctx.vcs.transform((editor) => {
      editor.add({
        id: "hg",
        name: "Mercurial",
        init: (input) =>
          Effect.gen(function* () {
            const result = yield* processes.run(
              ChildProcess.make("hg", ["init"], {
                cwd: input.worktree,
                env: { HGPLAIN: "1" },
                extendEnv: true,
                stdin: "ignore",
              }),
            )
            if (result.exitCode !== 0) return yield* Effect.fail(new Error("Mercurial initialization failed"))
          }),
        info: () => adapter.info(),
        branches: (input) => adapter.branches({ search: input.search, limit: input.limit }),
        status: () => adapter.status(),
        diff: (input) => adapter.diff(input.mode, { context: input.context, base: input.base }),
      })
    })
  }),
})

/**
 * Mercurial adapter for the Vcs service. `hg diff --git` emits git-format
 * patches for tracked changes; untracked (`?`) and missing (`!`) files never
 * appear in `hg diff`, so their patches are synthesized from file contents.
 */
function make(
  proc: AppProcess.Interface,
  fs: FSUtil.Interface,
  input: { directory: string; worktree: string },
): Adapter {
  const hg = makeHg(proc, input.worktree)
  // All commands run from the worktree root (hg prints root-relative paths);
  // this pathspec scopes them to the requested directory.
  const scope = path.relative(input.worktree, input.directory) || "."

  const patchFor = Effect.fnUntraced(function* (item: Item, rev: string | undefined, chunk: string | undefined) {
    if (chunk !== undefined) return chunk
    if (item.code === "?") {
      const content = yield* fs
        .readFileString(path.join(input.worktree, item.file))
        .pipe(Effect.orElseSucceed(() => undefined))
      if (content === undefined || Buffer.byteLength(content) > MAX_PATCH_BYTES) return emptyPatch(item.file)
      return addPatch(item.file, content)
    }
    if (item.code === "!") {
      const content = yield* hg.cat(rev ?? ".", item.file)
      if (content === undefined || Buffer.byteLength(content) > MAX_PATCH_BYTES) return emptyPatch(item.file)
      return deletePatch(item.file, content)
    }
    return emptyPatch(item.file)
  })

  const diffAgainst = Effect.fnUntraced(function* (rev: string | undefined, options?: DiffOptions) {
    const [items, batch] = yield* Effect.all(
      [hg.status(rev, scope), hg.diff(rev, scope, { context: options?.context ?? PATCH_CONTEXT_LINES })],
      { concurrency: 2 },
    )
    const chunks = chunksByFile(batch, () => undefined)
    const list: FileDiff.Info[] = []
    for (const item of items.toSorted((a, b) => a.file.localeCompare(b.file))) {
      const patch = yield* patchFor(item, rev, chunks.get(item.file))
      const counts = countPatch(patch)
      list.push({
        file: item.file,
        patch,
        additions: counts.additions,
        deletions: counts.deletions,
        status: item.status,
      })
    }
    return list
  })

  return {
    info: Effect.fn("VcsHg.info")(function* () {
      return { branch: { current: yield* hg.branch(), default: "default" } } satisfies Info
    }),
    branches: Effect.fn("VcsHg.branches")(function* () {
      return []
    }),
    status: Effect.fn("VcsHg.status")(function* () {
      return (yield* diffAgainst(undefined, { context: 0 })).map(
        (item) =>
          ({
            file: item.file,
            additions: item.additions,
            deletions: item.deletions,
            status: item.status,
          }) satisfies FileStatus,
      )
    }),
    diff: Effect.fn("VcsHg.diff")(function* (mode: Mode, options?: DiffOptions) {
      if (mode === "working") return yield* diffAgainst(undefined, options)
      if (mode === "committed" || options?.base !== undefined) {
        return yield* new DiffError({
          message: "The Mercurial provider does not support committed reviews or explicit bases",
        })
      }

      const branch = yield* hg.branch()
      if (!branch || branch === "default") return []
      const ancestor = yield* hg.ancestor()
      if (!ancestor) return []
      return yield* diffAgainst(ancestor, options)
    }),
  }
}

type Kind = FileStatus["status"]

interface Item {
  readonly file: string
  readonly code: string
  readonly status: Kind
}

const kind = (code: string): Kind => {
  if (code === "A" || code === "?") return "added"
  if (code === "R" || code === "!") return "deleted"
  return "modified"
}

function makeHg(proc: AppProcess.Interface, worktree: string) {
  const run = Effect.fnUntraced(
    function* (args: string[], opts?: { maxOutputBytes?: number }) {
      const result = yield* proc.run(
        ChildProcess.make("hg", args, {
          cwd: worktree,
          env: { HGPLAIN: "1" },
          extendEnv: true,
          stdin: "ignore",
        }),
        { maxOutputBytes: opts?.maxOutputBytes },
      )
      return {
        exitCode: result.exitCode,
        text: () => result.stdout.toString("utf8"),
        truncated: result.stdoutTruncated || result.stderrTruncated,
      }
    },
    Effect.orElseSucceed(() => ({ exitCode: 1, text: () => "", truncated: false })),
  )

  const status = Effect.fn("VcsHg.statusNames")(function* (rev: string | undefined, scope: string) {
    const result = yield* run(["status", "-0", ...(rev ? ["--rev", rev] : []), scope])
    if (result.exitCode !== 0) return []
    return result
      .text()
      .split("\0")
      .filter(Boolean)
      .flatMap((entry) => {
        const code = entry.slice(0, 1)
        const file = entry.slice(2)
        if (!file) return []
        return [{ file, code, status: kind(code) } satisfies Item]
      })
  })

  const diff = Effect.fn("VcsHg.diffPatch")(function* (
    rev: string | undefined,
    scope: string,
    options: { context: number },
  ) {
    const result = yield* run(
      ["diff", "--git", "--unified", String(options.context), ...(rev ? ["-r", rev] : []), scope],
      { maxOutputBytes: MAX_TOTAL_PATCH_BYTES },
    )
    if (result.exitCode !== 0) return { text: "", truncated: false }
    return { text: result.text(), truncated: result.truncated }
  })

  const branch = Effect.fn("VcsHg.branch")(function* () {
    const result = yield* run(["branch"])
    if (result.exitCode !== 0) return undefined
    return result.text().trim() || undefined
  })

  const ancestor = Effect.fn("VcsHg.ancestor")(function* () {
    const result = yield* run(["log", "-r", "ancestor(., default)", "-T", "{node}"])
    if (result.exitCode !== 0) return undefined
    return result.text().trim() || undefined
  })

  const cat = Effect.fn("VcsHg.cat")(function* (rev: string, file: string) {
    const result = yield* run(["cat", "-r", rev, "--", file], { maxOutputBytes: MAX_PATCH_BYTES })
    if (result.exitCode !== 0 || result.truncated) return undefined
    return result.text()
  })

  return { status, diff, branch, ancestor, cat }
}

export * as VerbosityPlugin from "./verbosity.js"

import { define } from "@opencode/plugin/effect/plugin"
import type { SessionRequest } from "@opencode/plugin/effect/session"
import { Effect } from "effect"
import { Model } from "../model.js"
import { Provider } from "../provider.js"
import type { PluginInternal } from "./internal.js"

const direct = new Set([
  "@opencode/ai/providers/openai",
  "@opencode/ai/providers/openai/responses",
  "@opencode/ai/providers/azure",
  "@opencode/ai/providers/azure/responses",
])
const gateways = new Set([
  "@opencode/ai/providers/cloudflare-ai-gateway",
  "@opencode/ai/providers/vercel-ai-gateway",
  Provider.aisdk("@ai-sdk/gateway"),
])

export const Plugin = define({
  id: "opencode.prompt.verbosity",
  effect: Effect.fn("VerbosityPlugin")(function* (ctx) {
    const models = yield* Model.Service
    const hook = (event: SessionRequest) =>
      Effect.gen(function* () {
        if (event.options.textVerbosity !== undefined) return
        const model = yield* models.get(event.model.providerID, event.model.id)
        if (!model) return
        const id = openAIModelID(model)
        if (!id || !supportsVerbosity(id)) return
        if (model.settings?.textVerbosity !== undefined) return
        const variant = model.variants.find((item) => item.id === event.model.variant)
        if (variant?.settings?.textVerbosity !== undefined) return
        event.options.textVerbosity = "low"
      })
    yield* ctx.session.hook("context", hook)
    yield* ctx.session.hook("compaction", hook)
    yield* ctx.session.hook("generate", hook)
    yield* ctx.session.hook("title", hook)
  }),
} satisfies PluginInternal.InternalPlugin)

function supportsVerbosity(id: string) {
  if (id.includes("gpt-6")) return true
  if (id.includes("-chat") || id.includes("-image")) return false
  // New GPT-5 minor versions remain unset until their support is known.
  return /(?:^|[/.])gpt-5\.[1-6](?:[.:-]|$)/.test(id) || /(?:^|[/.])gpt-5(?:-(?:mini|nano)(?:[.:-]|$)|$)/.test(id)
}

function openAIModelID(model: Model.Info) {
  const id = model.modelID.toLowerCase()
  if (direct.has(model.package ?? "")) return id
  if (model.package === "@opencode/ai/providers/amazon-bedrock/mantle/responses" && id.startsWith("openai."))
    return id.slice("openai.".length)
  if (gateways.has(model.package ?? "") && id.startsWith("openai/")) return id.slice("openai/".length)
}

export * as WarmingPlugin from "./warming.js"

import { define } from "@opencode/plugin/effect/plugin"
import type { SessionHooks } from "@opencode/plugin/effect/session"
import type { Session } from "@opencode/schema/session"
import { Clock, Duration, Effect, Scope } from "effect"
import { Config } from "../config.js"

const defaults = {
  prompt: "This is a keep-alive request. Do not perform any work or use tools. Reply with exactly: OK",
  interval: Duration.minutes(4),
  duration: Duration.minutes(30),
}

export const Plugin = define({
  id: "opencode.warming",
  effect: Effect.fn(function* (ctx) {
    const config = yield* Config.Service
    const loadSettings = Effect.fn("WarmingPlugin.loadSettings")(function* () {
      const warming = Config.latest(yield* config.entries(), "warming")
      if (!warming) return
      const settings = warming === true ? defaults : { ...defaults, ...warming }
      const interval = Duration.toMillis(settings.interval)
      const duration = Duration.toMillis(settings.duration)
      if (Number.isFinite(interval) && interval > 0 && Number.isFinite(duration) && duration > 0) return settings
      yield* Effect.logWarning("warming interval and duration must be finite positive durations")
    })

    const scope = yield* Scope.Scope
    const sessions = new Map<Session.ID, { last: number; expires: number; settings: typeof defaults }>()
    const loop: (sessionID: Session.ID) => Effect.Effect<void> = Effect.fn("WarmingPlugin.loop")(
      function* (sessionID) {
        const current = sessions.get(sessionID)
        if (!current) return

        const now = yield* Clock.currentTimeMillis
        const next = Math.min(current.last + Duration.toMillis(current.settings.interval), current.expires)
        if (now < next) {
          yield* Effect.sleep(Duration.millis(next - now))
          return yield* loop(sessionID)
        }
        if (now >= current.expires) {
          sessions.delete(sessionID)
          return
        }

        const last = current.last
        yield* Effect.logInfo("warming session", { sessionID, last })
        yield* ctx.session
          .generate({ sessionID, prompt: current.settings.prompt })
          .pipe(Effect.catchCause((cause) => Effect.logWarning("failed to warm session", { sessionID, cause })))
        const latest = sessions.get(sessionID)
        if (latest === current && latest.last === last) latest.last = yield* Clock.currentTimeMillis
        return yield* loop(sessionID)
      },
    )

    const hook = (event: SessionHooks["context"]) =>
      Effect.gen(function* () {
        const session = yield* ctx.session.get({ sessionID: event.sessionID }).pipe(Effect.orDie)
        if (session.parentID) return

        const active = sessions.get(event.sessionID)
        const settings = yield* loadSettings()
        if (!settings) {
          sessions.delete(event.sessionID)
          return
        }

        // Once generate exposes request metadata to context hooks, tag warm requests instead of matching the prompt.
        const message = event.messages.at(-1)
        if (
          message?.role === "user" &&
          message.content.length === 1 &&
          message.content[0]?.type === "text" &&
          (message.content[0].text === active?.settings.prompt || message.content[0].text === settings.prompt)
        ) {
          if (active) active.settings = settings
          return
        }

        const now = yield* Clock.currentTimeMillis
        const duration = Duration.toMillis(settings.duration)
        if (active) {
          active.last = now
          active.expires = now + duration
          active.settings = settings
          return
        }
        sessions.set(event.sessionID, { last: now, expires: now + duration, settings })
        yield* Effect.logInfo("scheduled session warming", {
          sessionID: event.sessionID,
          interval: settings.interval,
          expires: now + duration,
        })
        yield* loop(event.sessionID).pipe(
          Effect.catchCause((cause) =>
            Effect.logError("session warming loop failed", { sessionID: event.sessionID, cause }),
          ),
          Effect.forkIn(scope),
        )
      })
    yield* ctx.session.hook("context", hook)
    yield* ctx.session.hook("compaction", hook)
    yield* ctx.session.hook("generate", hook)
  }),
})

