          )))
    )
      state.invalid ??= "dynamic-execution"
    // Bash compgen -C and -F execute their argument immediately to generate completions.
    if (
      state.context.dialect !== "zsh" &&
      builtinName === "compgen" &&
      builtinArgs.some((word) => word.startsWith("-") && /[CF]/.test(word))
    )
      state.invalid ??= "dynamic-execution"
