      if (name === "a") {
        if (frame.link && (activeLink === frame.link || !activeLink)) {
          activeLink = frame.link
          if (linkOpen || (last && last !== "\n"))
            append(`](${destination(frame.link.href)}${title(frame.link.title)})`)
          linkOpen = false
          activeLink = undefined
        }
