      lines
        .map((line, index) => {
          if (line) return line
          const before = lines[index - 1]?.match(/^(?:> )+/)?.[0]
          const after = lines[index + 1]?.match(/^(?:> )+/)?.[0]
          if (!before || !after || before.length === after.length) return line
          return "> ".repeat(Math.min(before.length, after.length) / 2).trimEnd()
