export interface Adapter {
  readonly info: () => Effect.Effect<Info>
  readonly base?: () => Effect.Effect<Base | null, DiffError>
  readonly branches: (options?: BranchOptions) => Effect.Effect<BranchList>
  readonly status: () => Effect.Effect<FileStatus[]>
  readonly diff: (mode: Mode, options?: DiffOptions) => Effect.Effect<FileDiff.Info[], DiffError>
}

export interface Interface extends Adapter, State.Transformable<VcsEditor> {
  readonly base: () => Effect.Effect<Base | null, DiffError>
  readonly initialize: (providerID: string) => Effect.Effect<void, InitializeError>
}

interface Data {
  readonly providers: Map<string, VcsDefinition>
  selection?: string
}

export class Service extends Context.Service<Service, Interface>()("@opencode/Vcs") {}

const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const fs = yield* FSUtil.Service
    const location = yield* Location.Service
    const bus = yield* Bus.Service
    const root = yield* Effect.scope
    const fork = yield* FiberSet.makeRuntime<never, void, never>()
    const vcs = location.vcs
    const current: { info: Info } = { info: { branch: {} } }
    const refreshLock = Semaphore.makeUnsafe(1)
    const scope = {
      directory: location.directory,
      worktree: location.project.directory,
      canonical: location.project.canonical,
      ...(vcs ? { store: vcs.store } : {}),
    }
    const decodeInfo = Schema.decodeUnknownEffect(Schema.toType(Info))
    const decodeBase = Schema.decodeUnknownEffect(Schema.NullOr(Base))
    const decodeBranches = Schema.decodeUnknownEffect(BranchList)
    const decodeStatus = Schema.decodeUnknownEffect(Schema.Array(FileStatus))
    const decodeDiff = Schema.decodeUnknownEffect(Schema.Array(FileDiff.Info))
    const state: State.Interface<Data, VcsEditor> = State.create<Data, VcsEditor>({
      name: "vcs",
      initial: () => ({ providers: new Map() }),
      editor: (editor) => ({
        add: (provider) => editor.providers.set(provider.id, provider),
        default: {
          get: () => editor.selection,
          set: (selection) => (editor.selection = selection),
        },
      }),
      notify: () => State.reconcile(root, fork, () => refresh()),
    })
    const selected = () => {
      const value = state.get()
      const id = value.selection ?? vcs?.type
      return id ? value.providers.get(id) : undefined
    }
    const protect = <A>(provider: VcsDefinition, operation: string, effect: Effect.Effect<A, unknown>, fallback: A) =>
      effect.pipe(
        Effect.catchCause((cause) =>
          Cause.hasInterrupts(cause)
            ? Effect.failCause(cause).pipe(Effect.orDie)
            : Effect.logWarning("vcs provider failed", { provider: provider.id, operation, cause }).pipe(
                Effect.as(fallback),
              ),
        ),
      )
    const review = <A>(provider: VcsDefinition, operation: "base" | "diff", effect: Effect.Effect<A, unknown>) =>
      effect.pipe(
        Effect.catchCause((cause) => {
          if (Cause.hasInterrupts(cause)) return Effect.failCause(cause).pipe(Effect.orDie)
          const error = Cause.squash(cause)
          return Effect.logWarning("vcs provider failed", { provider: provider.id, operation, cause }).pipe(
            Effect.andThen(
              Effect.fail(
                error instanceof DiffError
                  ? error
                  : new DiffError({
                      message:
                        operation === "base"
                          ? "VCS provider could not resolve a review base"
                          : "VCS provider could not produce a diff",
                    }),
              ),
            ),
          )
        }),
      )
    const refresh = Effect.fn("Vcs.refresh")(function* () {
      const changed = yield* Effect.gen(function* () {
        const provider = selected()
        const next: Info = provider
          ? {
              ...(yield* protect(provider, "info", provider.info(scope).pipe(Effect.flatMap(decodeInfo)), {
                branch: {},
              })),
              provider: provider.id,
            }
          : { branch: {} }
        const changed = current.info.branch.current !== next.branch.current
        current.info = next
        return changed
      }).pipe(Semaphore.withPermit(refreshLock))
      if (!changed) return
      // Legacy listeners can publish nested updates before streams and SSE receive
      // this event. Re-announce the latest branch if publication was overtaken.
      while (true) {
        const branch = current.info.branch.current
        yield* bus.publish(VcsEvent.BranchUpdated, { branch })
        if (branch === current.info.branch.current) return
      }
    })

    if (vcs) {
      const store = yield* fs.realPath(vcs.store).pipe(Effect.orElseSucceed(() => vcs.store))
      const isBranchMetadata =
        vcs.type === "git"
          ? (file: string) => path.basename(file) === "HEAD" && FSUtil.contains(store, file)
          : (file: string) => path.resolve(file) === path.join(store, "branch")
      yield* bus.subscribe(FileSystem.Event.Changed).pipe(
        Stream.filter((event) => isBranchMetadata(event.data.file)),
        Stream.runForEach((event) =>
          refresh().pipe(
            Effect.catchCauseIf(
              (cause) => !Cause.hasInterrupts(cause),
              (cause) => Effect.logWarning("vcs refresh failed", { file: event.data.file, cause }),
            ),
            Effect.withSpan("Vcs.refreshBranch", { attributes: { file: event.data.file } }),
          ),
        ),
        Effect.forkScoped({ startImmediately: true }),
      )
    }

    return Service.of({
      transform: state.transform,
      reload: state.reload,
      initialize: Effect.fn("Vcs.initialize")(function* (providerID: string) {
        if (!(yield* fs.isDir(location.project.directory))) return yield* new InitializeError({ kind: "missing" })
        if (yield* Project.root(fs, location.project.directory)) return yield* new InitializeError({ kind: "conflict" })
        const provider = state.get().providers.get(providerID)
        if (!provider) return yield* new InitializeError({ kind: "unknown" })
        if (!provider.init) return yield* new InitializeError({ kind: "unsupported" })
        yield* provider
          .init(scope)
          .pipe(
            Effect.catchCause((cause) =>
              Cause.hasInterrupts(cause)
                ? Effect.failCause(cause).pipe(Effect.orDie)
                : Effect.logWarning("vcs initialization failed", { provider: providerID, cause }).pipe(
                    Effect.andThen(Effect.fail(new InitializeError({ kind: "failed" }))),
                  ),
            ),
          )
      }),
      info: Effect.fn("Vcs.info")(function* () {
        return current.info
      }),
      base: Effect.fn("Vcs.base")(function* () {
        const provider = selected()
        if (!provider?.base) return null
        return yield* review(provider, "base", provider.base(scope).pipe(Effect.flatMap(decodeBase)))
      }),
      branches: Effect.fn("Vcs.branches")(function* (options?: BranchOptions) {
        const provider = selected()
        if (provider)
          return yield* protect(
            provider,
            "branches",
            provider.branches({ ...scope, ...options }).pipe(Effect.flatMap(decodeBranches)),
            [],
          )
        return []
      }),
      status: Effect.fn("Vcs.status")(function* () {
        const provider = selected()
        if (provider)
          return yield* protect(
            provider,
            "status",
            provider.status(scope).pipe(
              Effect.flatMap(decodeStatus),
              Effect.map((rows) => Array.from(rows)),
            ),
            [],
          )
        return []
      }),
      diff: Effect.fn("Vcs.diff")(function* (mode: Mode, options?: DiffOptions) {
        const provider = selected()
        if (!provider) return []
        const rows = yield* review(
          provider,
          "diff",
          provider
            .diff({
              ...scope,
              mode,
              ...(options?.base !== undefined ? { base: options.base } : {}),
              context: options?.context ?? PATCH_CONTEXT_LINES,
              maxOutputBytes: MAX_TOTAL_PATCH_BYTES,
            })
            .pipe(Effect.flatMap(decodeDiff)),
        )
        let total = 0
        return rows.map((row) => {
          const bytes = Buffer.byteLength(row.patch)
          if (total + bytes > MAX_TOTAL_PATCH_BYTES) return { ...row, patch: emptyPatch(row.file) }
          total += bytes
          return row
        })
      }),
    })
  }),
)

export const node = makeLocationNode({
  service: Service,
  layer: layer,
  deps: [FSUtil.node, Location.node, Bus.node],
})

export * as VcsPatch from "./patch.js"

import { formatPatch, structuredPatch } from "diff"

// Effectively "full file" context; adapters use it when no context is requested.
export const PATCH_CONTEXT_LINES = 2_147_483_647
export const MAX_PATCH_BYTES = 10_000_000
export const MAX_TOTAL_PATCH_BYTES = 10_000_000

export interface Patch {
  readonly text: string
  readonly truncated: boolean
}

export const emptyPatch = (file: string) => formatPatch(structuredPatch(file, file, "", "", "", "", { context: 0 }))

export const addPatch = (file: string, content: string) =>
  formatPatch(structuredPatch(file, file, "", content, "", "", { context: 0 }))

export const deletePatch = (file: string, content: string) =>
  formatPatch(structuredPatch(file, file, content, "", "", "", { context: 0 }))

/** Count changed lines in a unified diff, ignoring `+++`/`---` file headers. */
export const countPatch = (patch: string) => {
  let additions = 0
  let deletions = 0
  for (const line of patch.split("\n")) {
    if (line.startsWith("+") && !line.startsWith("+++")) additions++
    else if (line.startsWith("-") && !line.startsWith("---")) deletions++
  }
  return { additions, deletions }
}

const parseQuotedPath = (value: string) => {
  let out = ""
  for (let idx = 1; idx < value.length; idx++) {
    const char = value[idx]
    if (char === '"') return { value: out, end: idx + 1 }
    if (char !== "\\") {
      out += char
      continue
    }

    const next = value[++idx]
    if (next === "t") out += "\t"
    else if (next === "n") out += "\n"
    else if (next === "r") out += "\r"
    else if (next === '"' || next === "\\") out += next
    else out += next ?? ""
  }
}

const parsePathToken = (value: string) => {
  if (!value.startsWith('"')) return value.split("\t")[0]
  return parseQuotedPath(value)?.value ?? value
}

const fileFromDiffPath = (value: string | undefined) => {
  if (!value || value === "/dev/null") return
  const file = parsePathToken(value)
  if (file.startsWith("a/") || file.startsWith("b/")) return file.slice(2)
  return file
}

const fileFromGitHeader = (header: string) => {
  if (header.startsWith('"')) {
    const first = parseQuotedPath(header)
    const second = first ? header.slice(first.end).trimStart() : undefined
    if (!second) return
    if (!second.startsWith('"')) return fileFromDiffPath(second)
    return fileFromDiffPath(parseQuotedPath(second)?.value)
  }

  const separator = header.indexOf(" b/")
  if (separator === -1) return
  return fileFromDiffPath(header.slice(separator + 1))
}

export const fileFromPatchChunk = (chunk: string) => {
  const next = /^\+\+\+ (.+)$/m.exec(chunk)?.[1]
  const before = /^--- (.+)$/m.exec(chunk)?.[1]
  const file = fileFromDiffPath(next) ?? fileFromDiffPath(before)
  if (file) return file

  const header = /^diff --git (.+)$/m.exec(chunk)?.[1]
  return fileFromGitHeader(header ?? "")
}

/** Split `git diff`-format output into per-file chunks, dropping a trailing partial chunk when truncated. */
export const splitGitPatch = (patch: Patch) => {
  const starts = [...patch.text.matchAll(/(?:^|\n)diff --git /g)].map((match) =>
    match[0].startsWith("\n") ? match.index + 1 : match.index,
  )
  const chunks = starts.map((start, index) => patch.text.slice(start, starts[index + 1] ?? patch.text.length))
  if (!patch.truncated) return chunks
  return chunks.slice(0, -1)
}

/** Map per-file chunks by the file they touch, concatenating chunks for the same file. */
export const chunksByFile = (patch: Patch, fallback: (index: number) => string | undefined) =>
  splitGitPatch(patch).reduce((acc, chunk, index) => {
    const file = fileFromPatchChunk(chunk) ?? fallback(index)
    if (!file) return acc
    acc.set(file, (acc.get(file) ?? "") + chunk)
    return acc
  }, new Map<string, string>())

export * as WebSearch from "./websearch.js"

import { WebSearch } from "@opencode/schema/websearch"
import type { Session } from "@opencode/schema/session"
import { SessionEvent } from "@opencode/schema/session-event"
import { Clock, Context, Effect, Layer, Option, Schema, Stream } from "effect"
import { HttpClientError } from "effect/http"
import { makeLocationNode } from "@opencode/util/effect/app-node"
import { Bus } from "./bus.js"
import { KV } from "./kv.js"
import { State } from "./state.js"

export const ID = WebSearch.ID
export type ID = WebSearch.ID

export const Provider = WebSearch.Provider
export type Provider = WebSearch.Provider

export { Event } from "@opencode/schema/websearch"

export const Input = WebSearch.Input
export type Input = WebSearch.Input
export type ProviderInput = WebSearch.ProviderInput

export const Result = WebSearch.Result
export type Result = WebSearch.Result

export const Response = WebSearch.Response
export type Response = WebSearch.Response

export const ProviderKey = "websearch:provider"
export const Selection = Schema.Union([ID, Schema.Literal("random"), Schema.Literal(false)])
export type Selection = typeof Selection.Type

export interface ProviderImplementation extends Provider {
  readonly execute: (input: ProviderInput) => Effect.Effect<readonly Result[], unknown>
}

export class ProviderRequiredError extends Schema.TaggedError<ProviderRequiredError>()(
  "WebSearch.ProviderRequired",
  {},
) {}

export class ProviderNotFoundError extends Schema.TaggedError<ProviderNotFoundError>()("WebSearch.ProviderNotFound", {
  providerID: ID,
}) {}

export class DisabledError extends Schema.TaggedError<DisabledError>()("WebSearch.Disabled", {}) {}

export class RequestError extends Schema.TaggedError<RequestError>()("WebSearch.Request", {
  providerID: ID,
  cause: Schema.Defect(),
}) {}

export type Error = ProviderRequiredError | ProviderNotFoundError | DisabledError | RequestError

export interface Interface extends State.Transformable<Editor> {
  readonly providers: () => Effect.Effect<readonly Provider[]>
  readonly default: () => Effect.Effect<Provider | undefined, DisabledError>
  readonly select: (selection: Selection) => Effect.Effect<void>
  readonly query: (
    input: Input,
    options?: {
      readonly sessionID?: Session.ID
      readonly onProvider?: (provider: Provider) => Effect.Effect<void>
    },
  ) => Effect.Effect<Response, Error>
}

export class Service extends Context.Service<Service, Interface>()("@opencode/WebSearch") {}

type Data = {
  readonly providers: Map<ID, ProviderImplementation>
  selection?: Selection
}

export type Editor = {
  add: (provider: ProviderImplementation) => void
  default: {
    get: () => Selection | undefined
    set: (selection: Selection) => void
  }
}

const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const bus = yield* Bus.Service
    const kv = yield* KV.Service
    const decodeResults = Schema.decodeUnknownEffect(Schema.Array(Result))
    const cooldowns = new Map<ID, { until: number; error: RequestError }>()
    const preferred = new Map<Session.ID | undefined, { provider?: ID }>()
    yield* Effect.addFinalizer(() => Effect.sync(() => preferred.clear()))
    yield* bus.subscribe([SessionEvent.Deleted, SessionEvent.Moved]).pipe(
      Stream.runForEach((event) =>
        Effect.sync(() => {
          preferred.delete(event.data.sessionID)
        }),
      ),
      Effect.forkScoped({ startImmediately: true }),
    )
    const state = State.create<Data, Editor>({
      initial: () => ({ providers: new Map() }),
      editor: (editor) => ({
        add: (provider) => editor.providers.set(provider.id, provider),
        default: {
          get: () => editor.selection,
          set: (selection) => (editor.selection = selection),
        },
      }),
      notify: () => bus.publish(WebSearch.Event.Updated, {}).pipe(Effect.asVoid),
    })

    const requireProvider = (providers: Map<ID, ProviderImplementation>, providerID: ID) => {
      const provider = providers.get(providerID)
      return provider ? Effect.succeed(provider) : Effect.fail(new ProviderNotFoundError({ providerID }))
    }

    const selection = Effect.fn("WebSearch.selection")(function* () {
      const data = state.get()
      if (
        data.selection === false ||
        data.selection === "random" ||
        (data.selection && data.providers.has(data.selection))
      )
        return data.selection
      const stored = yield* kv.get(ProviderKey)
      const decoded = Schema.decodeUnknownOption(Selection)(stored)
      if (stored !== undefined && Option.isNone(decoded)) yield* kv.remove(ProviderKey)
      return Option.getOrUndefined(decoded)
    })

    const randomProvider = (now: number, affinity: { provider?: ID }, attempted?: Set<ID>) => {
      const providers = state.get().providers
      cooldowns.forEach((cooldown, id) => {
        if (cooldown.until <= now || !providers.has(id)) cooldowns.delete(id)
      })
      const current = affinity.provider === undefined ? undefined : providers.get(affinity.provider)
      if (current && !cooldowns.has(current.id) && !attempted?.has(current.id)) return current
      const available = Array.from(providers.values()).filter(
        (provider) => !cooldowns.has(provider.id) && !attempted?.has(provider.id),
      )
      const provider = available[Math.floor(Math.random() * available.length)]
      if (provider) affinity.provider = provider.id
      return provider
    }

    const defaultProvider = Effect.fn("WebSearch.default")(function* (choice: Selection | undefined) {
      if (choice === false) return yield* new DisabledError()
      if (choice === "random") {
        // Inspection must not select a provider or reopen consent when every provider is cooling down.
        const active = preferred.get(undefined)?.provider
        return (
          (active === undefined ? undefined : state.get().providers.get(active)) ??
          state.get().providers.values().next().value
        )
      }
      return choice ? state.get().providers.get(choice) : undefined
    })

    return Service.of({
      transform: state.transform,
      reload: state.reload,
      providers: Effect.fn("WebSearch.providers")(function* () {
        return Array.from(state.get().providers.values(), (provider) => ({
          id: provider.id,
          name: provider.name,
        })).toSorted((a, b) => a.name.localeCompare(b.name))
      }),
      default: Effect.fn("WebSearch.defaultInfo")(function* () {
        const provider = yield* defaultProvider(yield* selection())
        return provider && { id: provider.id, name: provider.name }
      }),
      select: Effect.fn("WebSearch.select")(function* (selection) {
        yield* kv.set(ProviderKey, selection)
      }),
      query: Effect.fn("WebSearch.query")(function* (input, options) {
        const choice = input.providerID ? undefined : yield* selection()
        let provider = input.providerID
          ? yield* requireProvider(state.get().providers, input.providerID)
          : yield* defaultProvider(choice)
        if (!provider) return yield* new ProviderRequiredError()
        // Keep the cell for this query so deletion/movement cannot reinsert an in-flight session's entry.
        const affinity = preferred.get(options?.sessionID) ?? { provider: undefined }
        if (choice === "random") {
          preferred.set(options?.sessionID, affinity)
          provider = randomProvider(yield* Clock.currentTimeMillis, affinity) ?? provider
        }
        const attempted = new Set<ID>()
        while (true) {
          if (options?.onProvider) yield* options.onProvider({ id: provider.id, name: provider.name })
          let cooldown = choice === "random" ? cooldowns.get(provider.id) : undefined
          if (!cooldown || cooldown.until <= (yield* Clock.currentTimeMillis)) {
            attempted.add(provider.id)
            const result = yield* provider
              .execute({ query: input.query })
              .pipe(Effect.flatMap(decodeResults), Effect.result)
            if (result._tag === "Success") return new Response({ providerID: provider.id, results: result.success })
            const cause = result.failure
            const error = new RequestError({ providerID: provider.id, cause })
            if (choice !== "random" || !HttpClientError.isHttpClientError(cause) || cause.response?.status !== 429)
              return yield* error
            const now = yield* Clock.currentTimeMillis
            cooldown = { until: now + cooldownMillis(cause.response.headers["retry-after"], now), error }
            cooldowns.set(provider.id, cooldown)
          }
          provider = randomProvider(yield* Clock.currentTimeMillis, affinity, attempted)
          if (!provider) return yield* cooldown.error
        }
      }),
    })
  }),
)

function cooldownMillis(value: string | undefined, now: number) {
  if (!value?.trim()) return 60_000
  const seconds = Number(value)
  if (Number.isFinite(seconds)) return seconds >= 0 ? seconds * 1000 : 60_000
  const date = Date.parse(value)
  return Number.isFinite(date) ? Math.max(0, date - now) : 60_000
}

export const node = makeLocationNode({
  service: Service,
  layer,
  deps: [Bus.node, KV.node],
})

export * as WellKnown from "./wellknown.js"

import { Integration } from "@opencode/schema/integration"
import { Context, Effect, Layer, Ref, Schema, Semaphore } from "effect"
import { HttpClient, HttpClientRequest, HttpClientResponse } from "effect/http"
import { isDeepStrictEqual } from "node:util"
import { makeGlobalNode } from "@opencode/util/effect/app-node"
import { httpClient } from "@opencode/util/effect/app-node-platform"
import { Bus } from "./bus.js"
import { KV } from "./kv.js"

export interface Auth extends Schema.Schema.Type<typeof Auth> {}
export const Auth = Schema.Struct({
  command: Schema.Array(Schema.String),
  env: Schema.String,
}).annotate({ identifier: "WellKnown.Auth" })

export interface RemoteConfig extends Schema.Schema.Type<typeof RemoteConfig> {}
export const RemoteConfig = Schema.Struct({
  url: Schema.String,
  headers: Schema.optional(Schema.Record(Schema.String, Schema.String)),
}).annotate({ identifier: "WellKnown.RemoteConfig" })

export interface Config extends Schema.Schema.Type<typeof Config> {}
export const Config = Schema.Record(Schema.String, Schema.Json).annotate({ identifier: "WellKnown.Config" })

export interface Manifest extends Schema.Schema.Type<typeof Manifest> {}
export const Manifest = Schema.Struct({
  auth: Schema.optional(Auth),
  config: Schema.optional(Schema.NullOr(Config)),
  remote_config: Schema.optional(RemoteConfig),
}).annotate({ identifier: "WellKnown.Manifest" })

export interface ResolveInput {
  readonly origin: string
  readonly variables?: Readonly<Record<string, string>>
}

export interface Entry {
  readonly origin: string
  readonly integrationID: Integration.ID
  readonly manifest: Manifest
}

export interface Interface {
  readonly entries: () => Effect.Effect<readonly Entry[], Error>
  readonly snapshot: () => readonly Entry[]
  readonly refresh: () => Effect.Effect<boolean, Error>
  readonly add: (origin: string) => Effect.Effect<Entry, Error>
  readonly remove: (origin: string) => Effect.Effect<void>
  /** Resolves and caches the configuration for a registered source. */
  readonly resolve: (entry: Entry, variables: Readonly<Record<string, string>>) => Effect.Effect<Config[], Error>
  /** Returns the last configuration resolved for an origin, kept until the source is removed. */
  readonly cached: (origin: string) => Effect.Effect<Config[]>
}

export class Service extends Context.Service<Service, Interface>()("@opencode/WellKnown") {}

export const Event = {
  Updated: Bus.ephemeral({ type: "wellknown.updated", schema: {} }),
}

const requestTimeout = "15 seconds"

export const inspect = Effect.fn("WellKnown.inspect")(function* (origin: string) {
  const url = `${origin.replace(/\/+$/, "")}/.well-known/opencode`
  const http = HttpClient.filterStatusOk(yield* HttpClient.HttpClient)
  return yield* http.execute(HttpClientRequest.get(url).pipe(HttpClientRequest.acceptJson)).pipe(
    Effect.flatMap(HttpClientResponse.schemaBodyJson(Manifest)),
    Effect.timeout(requestTimeout),
    Effect.mapError((cause) => new Error(`Failed to load wellknown manifest from ${url}`, { cause })),
  )
})

export const resolve = Effect.fn("WellKnown.resolve")(function* (input: ResolveInput) {
  const manifest = yield* inspect(input.origin)
  return yield* resolveEntry(
    { origin: input.origin, integrationID: Integration.ID.make(input.origin.replace(/\/+$/, "")), manifest },
    input.variables ?? {},
  )
})

const resolveEntry = Effect.fnUntraced(function* (entry: Entry, variables: Readonly<Record<string, string>>) {
  const configs = entry.manifest.config ? [entry.manifest.config] : []
  if (!entry.manifest.remote_config) return configs

  const substitute = (value: string) =>
    value.replace(/\{env:([^}]+)\}/g, (_, name: string) => variables[name] ?? process.env[name] ?? "")
  const url = substitute(entry.manifest.remote_config.url)
  const headers = Object.fromEntries(
    Object.entries(entry.manifest.remote_config.headers ?? {}).map(([key, value]) => [key, substitute(value)]),
  )
  const http = HttpClient.filterStatusOk(yield* HttpClient.HttpClient)
  const remote = yield* http
    .execute(HttpClientRequest.get(url).pipe(HttpClientRequest.acceptJson, HttpClientRequest.setHeaders(headers)))
    .pipe(
      Effect.flatMap(HttpClientResponse.schemaBodyJson(Config)),
      Effect.timeout(requestTimeout),
      Effect.mapError((cause) => new Error(`Failed to load wellknown remote config from ${url}`, { cause })),
    )
  if (Schema.is(Config)(remote.config)) return [...configs, remote.config]
  return [...configs, remote]
})

const sourcesKey = "wellknown:sources"
const Sources = Schema.Array(Schema.String)
const manifestKey = (origin: string) => `wellknown:manifest:${origin}`
const configKey = (origin: string) => `wellknown:config:${origin}`
const Configs = Schema.Array(Config)

const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const http = yield* HttpClient.HttpClient
    const kv = yield* KV.Service
    const bus = yield* Bus.Service
    const cache = yield* Ref.make(new Map<string, Entry>())
    const lock = Semaphore.makeUnsafe(1)
    const loadEntry = Effect.fn("WellKnown.loadEntry")(function* (origin: string) {
      const manifest = yield* inspect(origin).pipe(
        Effect.provideService(HttpClient.HttpClient, http),
        Effect.tap((manifest) => kv.set(manifestKey(origin), manifest)),
        // An unreachable source keeps its last manifest so its remote config still loads after a restart.
        Effect.catch((error) =>
          kv
            .get(manifestKey(origin))
            .pipe(
              Effect.flatMap((cached) =>
                Schema.is(Manifest)(cached)
                  ? Effect.logWarning("failed to load wellknown manifest", { origin, error }).pipe(Effect.as(cached))
                  : Effect.fail(error),
              ),
            ),
        ),
      )
      return { origin, integrationID: Integration.ID.make(origin), manifest }
    })

    const load = Effect.fn("WellKnown.load")(function* () {
      const value = yield* kv.get(sourcesKey)
      const origins = Schema.is(Sources)(value) ? value : []
      const current = yield* Ref.get(cache)
      const entries = yield* Effect.forEach(origins, (origin) => {
        const cached = current.get(origin)
        if (cached) return Effect.succeed(cached)
        return loadEntry(origin)
      })
      yield* Ref.set(cache, new Map(entries.map((entry) => [entry.origin, entry])))
      return entries
    })

    const refresh = Effect.fn("WellKnown.refresh")(
      function* () {
        const value = yield* kv.get(sourcesKey)
        const origins = Schema.is(Sources)(value) ? value : []
        if (!origins.length) return false
        const entries = yield* Effect.forEach(origins, loadEntry)
        const next = new Map(entries.map((entry) => [entry.origin, entry]))
        const changed = !isDeepStrictEqual(Ref.getUnsafe(cache), next)
        if (!changed) return false
        yield* Ref.set(cache, next)
        yield* bus.publish(Event.Updated, {}, { global: true })
        return true
      },
      (effect) => lock.withPermit(effect),
    )

    return Service.of({
      entries: load,
      snapshot: () => Array.from(Ref.getUnsafe(cache).values()),
      refresh,
      add: Effect.fn("WellKnown.add")(
        function* (value) {
          const origin = value.replace(/\/+$/, "")
          const entry = yield* loadEntry(origin)
          if (!entry.manifest.auth) return yield* Effect.fail(new Error(`No authentication method found at ${origin}`))
          const sources = yield* kv.get(sourcesKey)
          const origins = Schema.is(Sources)(sources) ? sources : []
          yield* kv.set(sourcesKey, Array.from(new Set([...origins, origin])))
          yield* Ref.update(cache, (current) => new Map(current).set(origin, entry))
          yield* bus.publish(Event.Updated, {}, { global: true })
          return entry
        },
        (effect, _value) => lock.withPermit(effect),
      ),
      remove: Effect.fn("WellKnown.remove")(
        function* (value) {
          const origin = value.replace(/\/+$/, "")
          const sources = yield* kv.get(sourcesKey)
          const origins = Schema.is(Sources)(sources) ? sources : []
          yield* kv.set(
            sourcesKey,
            origins.filter((item) => item !== origin),
          )
          yield* kv.remove(manifestKey(origin))
          yield* kv.remove(configKey(origin))
          yield* Ref.update(cache, (current) => {
            const next = new Map(current)
            next.delete(origin)
            return next
          })
          yield* bus.publish(Event.Updated, {}, { global: true })
        },
        (effect, _value) => lock.withPermit(effect),
      ),
      resolve: Effect.fn("WellKnown.resolveEntry")(function* (entry, variables) {
        const configs = yield* resolveEntry(entry, variables).pipe(Effect.provideService(HttpClient.HttpClient, http))
        yield* kv.set(configKey(entry.origin), configs)
        return configs
      }),
      cached: Effect.fn("WellKnown.cached")(function* (origin) {
        const value = yield* kv.get(configKey(origin))
        return Schema.is(Configs)(value) ? [...value] : []
      }),
    })
  }),
)

export const node = makeGlobalNode({ service: Service, layer, deps: [httpClient, KV.node, Bus.node] })

export * as WellKnownPlugin from "./plugin.js"

import { define } from "@opencode/plugin/effect/plugin"
import { Effect, Stream } from "effect"
import { Bus } from "../bus.js"
import { WellKnown } from "../wellknown.js"

export const Plugin = define({
  id: "opencode.wellknown",
  effect: Effect.fn(function* (ctx) {
    const bus = yield* Bus.Service
    const wellknown = yield* WellKnown.Service
    yield* wellknown.entries().pipe(Effect.orDie)
    yield* ctx.integration.transform((editor) => {
      wellknown.snapshot().forEach((entry) => {
        if (!entry.manifest.auth) return
        editor.update(entry.integrationID, (integration) => {
          integration.name = new URL(entry.origin).hostname
        })
        editor.method.update({
          integrationID: entry.integrationID,
          method: {
            id: "login",
            type: "command",
            label: "Log in",
            command: [...entry.manifest.auth.command],
          },
        })
      })
    })
    yield* bus.subscribe(WellKnown.Event.Updated).pipe(
      Stream.runForEach(() => ctx.integration.reload()),
      Effect.forkScoped({ startImmediately: true }),
    )
  }),
})

export * as Workspace from "./workspace.js"

import { Workspace } from "@opencode/schema/workspace"
import { makeGlobalNode } from "@opencode/util/effect/app-node"
import { eq } from "drizzle-orm"
import { Clock, Context, Deferred, Duration, Effect, Exit, FiberSet, Layer, Ref, Schedule, Schema, Scope } from "effect"
import { systemError } from "effect/PlatformError"
import { make } from "effect/process/ChildProcessSpawner"
import type { EnvironmentDriver } from "./environment/driver.js"
import { execDefaults } from "./environment/exec-defaults.js"
import { Failed, type Files, type FilesImpl } from "./environment/files.js"
import { Database } from "./database/database.js"
import { KeyedMutex } from "./effect/keyed-mutex.js"
import { WorkspaceDriver } from "./workspace/driver.js"
import { WorkspaceTable } from "./workspace/sql.js"

export const ID = Workspace.ID
export type ID = Workspace.ID

export class Info extends Schema.Class<Info>("Workspace.Info")({
  id: ID,
  provider: Schema.String,
  binding: WorkspaceDriver.Binding,
  createdAt: Schema.Number,
  lastUsedAt: Schema.Number,
}) {}

export class NotFound extends Schema.TaggedError<NotFound>()("Workspace.NotFound", { workspaceID: ID }) {}

export class CreateConflict extends Schema.TaggedError<CreateConflict>()("Workspace.CreateConflict", {
  workspaceID: ID,
  provider: Schema.String,
  existingProvider: Schema.String,
}) {}

export interface Interface {
  /** Instantly commits a logical workspace ID. No provider work happens here. */
  readonly create: (input: {
    readonly id?: ID
    readonly provider: string
  }) => Effect.Effect<ID, CreateConflict | WorkspaceDriver.ProviderNotFound>
  /** Starts or joins the shared attempt that makes the backing resource real, then returns it. */
  readonly provision: (
    workspaceID: ID,
  ) => Effect.Effect<Info, NotFound | WorkspaceDriver.Error | WorkspaceDriver.ProviderNotFound>
  readonly connect: (
    workspaceID: ID,
  ) => Effect.Effect<EnvironmentDriver.Driver, NotFound | WorkspaceDriver.Error | WorkspaceDriver.ProviderNotFound>
  /** Makes the workspace absent; reports whether this call destroyed an existing workspace. */
  readonly destroy: (
    workspaceID: ID,
  ) => Effect.Effect<Workspace.DestroyResult, WorkspaceDriver.Error | WorkspaceDriver.ProviderNotFound>
}

export interface Options {
  readonly idleThreshold?: Duration.Input
  readonly pollInterval?: Duration.Input
}

export class Service extends Context.Service<Service, Interface>()("@opencode/Workspace") {}

interface Connection {
  readonly driver: WorkspaceDriver.Interface
  readonly environment: EnvironmentDriver.Driver
  readonly files: Files
  readonly saveBinding: (binding: WorkspaceDriver.Binding) => Effect.Effect<void>
  readonly lastActivity: Ref.Ref<number>
  readonly active: Ref.Ref<number>
  readonly scope: Scope.Closeable
}

type ReadinessError = NotFound | WorkspaceDriver.Error | WorkspaceDriver.ProviderNotFound

export const configured = (options: Options = {}) =>
  makeGlobalNode({
    service: Service,
    layer: layer(options),
    deps: [Database.node, WorkspaceDriver.node],
  })

const layer = (options: Options) =>
  Layer.effect(
    Service,
    Effect.gen(function* () {
      const db = (yield* Database.Service).db
      const registry = yield* WorkspaceDriver.RegistryService
      const lifetime = yield* Scope.Scope
      const connections = new Map<ID, Connection>()
      // Destroy cancels the racing provision body by settling the deferred.
      const attempts = new Map<ID, Deferred.Deferred<Info, ReadinessError>>()
      const locks = KeyedMutex.makeUnsafe<ID>()
      const fork = yield* FiberSet.makeRuntime<never, void, never>()
      const idleThreshold = Duration.toMillis(options.idleThreshold ?? Duration.minutes(20))

      const find = (workspaceID: ID) =>
        db.select().from(WorkspaceTable).where(eq(WorkspaceTable.id, workspaceID)).get().pipe(Effect.orDie)

      const load = Effect.fn("Workspace.load")(function* (workspaceID: ID) {
        const row = yield* find(workspaceID)
        if (!row) return yield* new NotFound({ workspaceID })
        return row
      })

      const saveBinding = (workspaceID: ID, binding: WorkspaceDriver.Binding) =>
        db.update(WorkspaceTable).set({ binding }).where(eq(WorkspaceTable.id, workspaceID)).run().pipe(Effect.orDie)

      const info = (row: typeof WorkspaceTable.$inferSelect, binding: WorkspaceDriver.Binding) =>
        new Info({
          id: row.id,
          provider: row.provider,
          binding,
          createdAt: row.created_at,
          lastUsedAt: row.last_used_at,
        })

      const provision = Effect.fn("Workspace.provision")((workspaceID: ID) =>
        Effect.suspend(() => {
          const existing = attempts.get(workspaceID)
          if (existing) return Deferred.await(existing)

          const attempt = Deferred.makeUnsafe<Info, ReadinessError>()
          attempts.set(workspaceID, attempt)
          fork(
            locks
              .withLock(workspaceID)(
                Effect.gen(function* () {
                  const row = yield* load(workspaceID)
                  if (row.binding) return info(row, row.binding)
                  const driver = yield* registry.get(row.provider)
                  const result = yield* driver.create({ workspaceID })
                  yield* saveBinding(workspaceID, result.binding)
                  return info(row, result.binding)
                }),
              )
              .pipe(
                Effect.raceFirst(Deferred.await(attempt)),
                Effect.onExit((exit) =>
                  Effect.sync(() => {
                    if (attempts.get(workspaceID) === attempt) attempts.delete(workspaceID)
                    Deferred.doneUnsafe(attempt, exit)
                  }),
                ),
                Effect.exit,
                Effect.asVoid,
              ),
          )
          return Deferred.await(attempt)
        }),
      )

      const open = Effect.fn("Workspace.open")(function* (workspaceID: ID) {
        const existing = connections.get(workspaceID)
        if (existing) return existing

        const row = yield* load(workspaceID)
        // Bindings are persisted before provision resolves and never nulled; a raced
        // destroy deletes the whole row and surfaces as NotFound from load above.
        if (!row.binding) return yield* Effect.die(`workspace ${workspaceID} has no binding after provision`)
        const driver = yield* registry.get(row.provider)
        const persistBinding = (binding: WorkspaceDriver.Binding) => saveBinding(workspaceID, binding)
        const scope = yield* Scope.fork(lifetime)
        const environment = yield* driver
          .connect({ workspaceID, binding: row.binding, saveBinding: persistBinding })
          .pipe(
            Effect.provideService(Scope.Scope, scope),
            Effect.onError((cause) => Scope.close(scope, Exit.failCause(cause))),
          )
        const now = yield* Clock.currentTimeMillis
        const connection: Connection = {
          driver,
          environment,
          files: {
            ...execDefaults(environment.spawner),
            ...environment.overrides,
          },
          saveBinding: persistBinding,
          lastActivity: yield* Ref.make(now),
          active: yield* Ref.make(0),
          scope,
        }
        connections.set(workspaceID, connection)
        yield* db
          .update(WorkspaceTable)
          .set({ last_used_at: now })
          .where(eq(WorkspaceTable.id, workspaceID))
          .run()
          .pipe(Effect.orDie)
        return connection
      })

      yield* Effect.gen(function* () {
        const now = yield* Clock.currentTimeMillis
        yield* Effect.forEach(
          [...connections.entries()],
          ([workspaceID, expected]) =>
            locks.withLock(workspaceID)(
              Effect.gen(function* () {
                const connection = connections.get(workspaceID)
                if (connection !== expected || (yield* Ref.get(connection.active)) > 0) return
                const lastActivity = yield* Ref.get(connection.lastActivity)
                if (now - lastActivity < idleThreshold) return
                const row = yield* load(workspaceID)
                if (!row.binding) return
                // Deliberate: a racing spawn blocks, then wakes cleanly. Unlocking mid-suspend could reattach a sandbox being terminated.
                yield* connection.driver.suspendForIdle({
                  workspaceID,
                  binding: row.binding,
                  saveBinding: connection.saveBinding,
                })
                yield* db
                  .update(WorkspaceTable)
                  .set({ last_used_at: lastActivity })
                  .where(eq(WorkspaceTable.id, workspaceID))
                  .run()
                  .pipe(Effect.orDie)
                connections.delete(workspaceID)
                yield* Scope.close(connection.scope, Exit.void)
              }).pipe(Effect.catchCause((cause) => Effect.logError("workspace idle suspension failed", cause))),
            ),
          { concurrency: "unbounded", discard: true },
        )
      }).pipe(Effect.repeat(Schedule.spaced(options.pollInterval ?? Duration.minutes(1))), Effect.forkScoped)

      return Service.of({
        create: Effect.fn("Workspace.create")(function* (input) {
          const workspaceID = input.id ?? ID.create()
          const existing = yield* db
            .select({ provider: WorkspaceTable.provider })
            .from(WorkspaceTable)
            .where(eq(WorkspaceTable.id, workspaceID))
            .get()
            .pipe(Effect.orDie)
          if (existing) {
            if (existing.provider === input.provider) return workspaceID
            return yield* new CreateConflict({
              workspaceID,
              provider: input.provider,
              existingProvider: existing.provider,
            })
          }
          yield* registry.get(input.provider)
          const now = yield* Clock.currentTimeMillis
          const inserted = yield* db
            .insert(WorkspaceTable)
            .values({ id: workspaceID, provider: input.provider, binding: null, created_at: now, last_used_at: now })
            .onConflictDoNothing()
            .returning({ id: WorkspaceTable.id })
            .get()
            .pipe(Effect.orDie)
          if (inserted) return workspaceID
          const row = yield* load(workspaceID).pipe(Effect.orDie)
          if (row.provider !== input.provider)
            return yield* new CreateConflict({
              workspaceID,
              provider: input.provider,
              existingProvider: row.provider,
            })
          return workspaceID
        }),
        provision,
        connect: Effect.fn("Workspace.connect")(function* (workspaceID) {
          const acquire = Effect.acquireRelease(
            // A live connection implies the binding is already persisted, so skip the provision hop.
            Effect.suspend(() => (connections.has(workspaceID) ? Effect.void : provision(workspaceID))).pipe(
              Effect.andThen(
                locks.withLock(workspaceID)(
                  Effect.gen(function* () {
                    const connection = yield* open(workspaceID)
                    yield* Ref.set(connection.lastActivity, yield* Clock.currentTimeMillis)
                    yield* Ref.update(connection.active, (active) => active + 1)
                    return connection
                  }),
                ),
              ),
            ),
            (connection) =>
              locks.withLock(workspaceID)(
                Effect.gen(function* () {
                  yield* Ref.update(connection.active, (active) => active - 1)
                  yield* Ref.set(connection.lastActivity, yield* Clock.currentTimeMillis)
                }),
              ),
          )
          const spawner = make((command) =>
            acquire.pipe(
              Effect.mapError((cause) =>
                systemError({
                  _tag: "Unknown",
                  module: "Workspace",
                  method: "spawn",
                  description: `Failed to wake workspace ${workspaceID}`,
                  cause,
                }),
              ),
              Effect.flatMap((connection) => connection.environment.spawner.spawn(command)),
            ),
          )
          const withFiles = <A, E>(
            path: string,
            use: (files: Files) => Effect.Effect<A, E>,
          ): Effect.Effect<A, E | Failed> =>
            Effect.scoped(
              acquire.pipe(
                Effect.mapError((cause) => new Failed({ path, cause })),
                Effect.flatMap((connection) => use(connection.files)),
              ),
            )
          const overrides: FilesImpl = {
            read: (path, range) => withFiles(path, (files) => files.read(path, range)),
            write: (path, bytes) => withFiles(path, (files) => files.write(path, bytes)),
            stat: (path) => withFiles(path, (files) => files.stat(path)),
            list: (path) => withFiles(path, (files) => files.list(path)),
            remove: (path) => withFiles(path, (files) => files.remove(path)),
            move: (from, to) => withFiles(from, (files) => files.move(from, to)),
            mkdir: (path) => withFiles(path, (files) => files.mkdir(path)),
          }
          return { spawner, overrides }
        }),
        destroy: Effect.fn("Workspace.destroy")(function* (workspaceID) {
          // Settling the shared attempt cancels its racing provision body and fails
          // waiters with NotFound before teardown commits. Accepted tradeoffs: if the
          // locked teardown below fails, those waiters saw NotFound for a workspace
          // that still exists (the next provision retries it), and a provision racing
          // this window may briefly succeed before teardown destroys its fresh binding.
          const attempt = attempts.get(workspaceID)
          if (attempt) {
            attempts.delete(workspaceID)
            Deferred.doneUnsafe(attempt, Exit.fail(new NotFound({ workspaceID })))
          }
          return yield* locks.withLock(workspaceID)(
            Effect.gen(function* () {
              const row = yield* find(workspaceID)
              if (!row) return { destroyed: false }
              const connection = connections.get(workspaceID)
              connections.delete(workspaceID)
              if (connection) yield* Scope.close(connection.scope, Exit.void)
              // Null binding still reaches the driver: an interrupted or crashed
              // provision may have created a resource that was never persisted. A
              // provider missing from the registry cannot block deleting a
              // never-provisioned row.
              yield* registry.get(row.provider).pipe(
                Effect.flatMap((driver) => driver.destroy({ workspaceID, binding: row.binding })),
                Effect.catchTag("WorkspaceDriver.ProviderNotFound", (error) =>
                  row.binding ? Effect.fail(error) : Effect.void,
                ),
              )
              yield* db.delete(WorkspaceTable).where(eq(WorkspaceTable.id, workspaceID)).run().pipe(Effect.orDie)
              return { destroyed: true }
            }),
          )
        }),
      })
    }),
  )

export const node = configured()

// TODO(workspace-plan): add the boot janitor and ~23h safety snapshot rotation in a later PR.
// TODO(workspace-plan): make cold wake interruptible with a re-pin loop against janitor races.
// TODO(workspace-plan): consider extracting a keyed shared-attempt helper (join/cancel, drop-on-settle) beside
