        projectID: Project.ID.global,
      })
      const done = yield* bus.publish(Done, {})
      expect(yield* Fiber.join(first)).toEqual([moved, done])
      expect(yield* Fiber.join(second)).toEqual([moved, after, same, done])
      expect(moved.location).toEqual(a)
    }),
  )

  it.effect("routes forks through their parent before the child exists", () =>
    Effect.gen(function* () {
      yield* seed()
      const bus = yield* Bus.Service
      const database = yield* Database.Service
      yield* bus.publish(SessionEvent.Synthetic, { sessionID: id, text: "Fork boundary" })
      const boundary = yield* database.db
        .select({ id: SessionMessageTable.id })
        .from(SessionMessageTable)
        .where(eq(SessionMessageTable.session_id, id))
        .get()
      if (!boundary) return yield* Effect.die("Missing fork boundary")

      yield* Effect.forEach(["publish", "batch", "replay"] as const, (mode) =>
        Effect.gen(function* () {
          const child = SessionID.create()
          const first = yield* watch(bus, a)
          const second = yield* watch(bus, b)
          const payload = {
            sessionID: child,
            parentID: id,
            boundary: { type: "before" as const, messageID: boundary.id },
          }
          const eventID = Event.ID.create()
          if (mode === "publish") yield* bus.publish(SessionEvent.Forked, payload, { id: eventID })
          if (mode === "batch") yield* bus.publishAll([[SessionEvent.Forked, payload, { id: eventID }]])
          if (mode === "replay")
            yield* bus.replay(
              {
                id: eventID,
                type: Bus.versionedType(SessionEvent.Forked.type, 2),
                seq: 0,
                aggregateID: child,
                data: payload,
              },
              { publish: true },
            )
          const after = yield* bus.publish(SessionEvent.Execution.Succeeded, { sessionID: child })
          const done = yield* bus.publish(Done, {})
          expect((yield* Fiber.join(first)).map((event) => event.id)).toEqual([eventID, after.id, done.id])
          expect(yield* Fiber.join(second)).toEqual([done])
        }),
      )
    }),
  )

  it.effect("routes existing Sessions without changing public events or global delivery", () =>
    Effect.gen(function* () {
      yield* seed()
      const bus = yield* Bus.Service
      const first = yield* watch(bus, a)
      const second = yield* watch(bus, b)
      const workspace = yield* watch(bus, otherWorkspace)
      const global = yield* watch(bus)
      const listened: Event.Payload[] = []
      yield* bus.listen((event) =>
        Effect.sync(() => {
          listened.push(event)
        }),
      )

      const renamed = yield* bus.publish(SessionEvent.Renamed, { sessionID: id, title: "first" })
      const text = yield* delta(bus)
      const broadcast = yield* bus.publish(Global, { sessionID: id })
      const explicit = yield* bus.publish(SessionEvent.Execution.Succeeded, { sessionID: id }, { location: b })
      const done = yield* bus.publish(Done, {})

      expect(yield* Fiber.join(first)).toEqual([renamed, text, broadcast, done])
      expect(yield* Fiber.join(second)).toEqual([broadcast, explicit, done])
      expect(yield* Fiber.join(workspace)).toEqual([broadcast, done])
      expect(yield* Fiber.join(global)).toEqual([renamed, text, broadcast, explicit, done])
      expect(listened).toEqual([renamed, text, broadcast, explicit, done])
      expect(renamed).not.toHaveProperty("location")
      expect(text).not.toHaveProperty("location")
      expect(JSON.parse(JSON.stringify(renamed))).not.toHaveProperty("location")
      const history = yield* bus.log({ aggregateID: id }).pipe(Stream.runCollect)
      expect(
        history.filter((event): event is Event.Payload => !Bus.isSynced(event)).every((event) => !event.location),
      ).toBe(true)
    }),
  )

  it.effect("applies the same routing to typed and multi-type subscriptions", () =>
    Effect.gen(function* () {
      yield* seed()
      const bus = yield* Bus.Service
      const typed = yield* bus
        .subscribe(SessionEvent.Renamed)
        .pipe(
          Stream.take(1),
          Stream.runCollect,
          Effect.provideService(Location.Service, location(b)),
          Effect.forkScoped({ startImmediately: true }),
        )
      const multiple = yield* bus.subscribe([SessionEvent.Renamed, Done]).pipe(
        Stream.takeUntil((event) => event.type === Done.type),
        Stream.runCollect,
        Effect.provideService(Location.Service, location(b)),
        Effect.forkScoped({ startImmediately: true }),
      )
      yield* bus.publish(SessionEvent.Renamed, { sessionID: id, title: "wrong location" })
      yield* bus.publish(SessionEvent.Moved, { sessionID: id, location: b, projectID: Project.ID.global })
      const expected = yield* bus.publish(SessionEvent.Renamed, { sessionID: id, title: "destination" })
      const done = yield* bus.publish(Done, {})
      expect(yield* Fiber.join(typed)).toEqual([expected])
      expect(yield* Fiber.join(multiple)).toEqual([expected, done])
    }),
  )

  it.effect("snapshots routing across creation and moves for slow subscribers", () =>
    Effect.gen(function* () {
      const database = yield* Database.Service
      yield* database.db
        .insert(ProjectTable)
        .values({ id: Project.ID.global, worktree: a.directory, sandboxes: [] })
        .run()
      const bus = yield* Bus.Service
      const gate = yield* Deferred.make<void>()
      const first = yield* watch(bus, a, gate)
      const second = yield* watch(bus, b, gate)
      const created = yield* bus.publish(SessionEvent.Created, {
        sessionID: id,
        location: a,
        projectID: Project.ID.global,
        slug: "routing",
        version: "test",
      })
      const before = yield* bus.publish(SessionEvent.Renamed, { sessionID: id, title: "before" })
      const moved = yield* bus.publish(SessionEvent.Moved, { sessionID: id, location: b, projectID: Project.ID.global })
      const after = yield* delta(bus)
      const done = yield* bus.publish(Done, {})
      yield* Deferred.succeed(gate, undefined)

      expect(yield* Fiber.join(first)).toEqual([created, before, moved, done])
      expect(yield* Fiber.join(second)).toEqual([moved, after, done])
      expect(moved).not.toHaveProperty("location")
    }),
  )

  it.effect("routes a cold Session deletion before its projector removes ownership", () =>
    Effect.gen(function* () {
      yield* seed()
      const bus = yield* Bus.Service
      const first = yield* watch(bus, a)
      const second = yield* watch(bus, b)
      const global = yield* watch(bus)
      const deleted = yield* bus.publish(SessionEvent.Deleted, { sessionID: id })
      const missing = yield* delta(bus)
      const done = yield* bus.publish(Done, {})

      const database = yield* Database.Service
      expect(yield* database.db.select().from(SessionTable).where(eq(SessionTable.id, id)).get()).toBeUndefined()
      expect(yield* Fiber.join(first)).toEqual([deleted, done])
      expect(yield* Fiber.join(second)).toEqual([done])
      expect(yield* Fiber.join(global)).toEqual([deleted, missing, done])
    }),
  )

  it.effect("preserves routing through a batch that moves and deletes a Session", () =>
    Effect.gen(function* () {
      yield* seed()
      const bus = yield* Bus.Service
      const gate = yield* Deferred.make<void>()
      const first = yield* watch(bus, a, gate)
      const second = yield* watch(bus, b, gate)
      const events = yield* bus.publishAll([
        [SessionEvent.Renamed, { sessionID: id, title: "before" }],
        [SessionEvent.Moved, { sessionID: id, location: b, projectID: Project.ID.global }],
        [SessionEvent.Renamed, { sessionID: id, title: "after" }],
        [SessionEvent.Deleted, { sessionID: id }],
      ])
      const done = yield* bus.publish(Done, {})
      yield* Deferred.succeed(gate, undefined)
      expect(yield* Fiber.join(first)).toEqual([events[0], events[1], done])
      expect(yield* Fiber.join(second)).toEqual([events[1], events[2], events[3], done])
    }),
  )

  it.effect("does not change ownership when single or batched moves roll back", () =>
    Effect.gen(function* () {
      yield* seed()
      const bus = yield* Bus.Service
      const first = yield* watch(bus, a)
      const second = yield* watch(bus, b)
      const before = yield* delta(bus)
      const single = yield* bus
        .publish(
          SessionEvent.Moved,
          { sessionID: id, location: b, projectID: Project.ID.global },
          { commit: () => Effect.die("rollback") },
        )
        .pipe(Effect.exit)
      const batch = yield* bus
        .publishAll([
          [SessionEvent.Moved, { sessionID: id, location: b, projectID: Project.ID.global }],
          [SessionEvent.Renamed, { sessionID: id, title: "rollback" }, { commit: () => Effect.die("rollback") }],
        ])
        .pipe(Effect.exit)
      const after = yield* delta(bus)
      const done = yield* bus.publish(Done, {})
      expect(Exit.isFailure(single)).toBe(true)
      expect(Exit.isFailure(batch)).toBe(true)
      expect(yield* Fiber.join(first)).toEqual([before, after, done])
      expect(yield* Fiber.join(second)).toEqual([done])
    }),
  )

  it.effect("updates cached ownership on silent replay and filters published replay", () =>
    Effect.gen(function* () {
      yield* seed()
      const bus = yield* Bus.Service
      yield* delta(bus)
      const first = yield* watch(bus, a)
      const second = yield* watch(bus, b)
      yield* bus.replay({
        id: Event.ID.create(),
        type: Bus.versionedType(SessionEvent.Moved.type, 1),
        seq: 0,
        aggregateID: id,
        data: { sessionID: id, location: b, projectID: Project.ID.global },
      })
      const after = yield* delta(bus)
      const replayID = Event.ID.create()
      yield* bus.replay(
        {
          id: replayID,
          type: Bus.versionedType(SessionEvent.Renamed.type, 1),
          seq: 1,
          aggregateID: id,
          data: { sessionID: id, title: "replayed" },
        },
        { publish: true },
      )
      const done = yield* bus.publish(Done, {})
      expect(yield* Fiber.join(first)).toEqual([done])
      const received = yield* Fiber.join(second)
      expect(received.map((event) => event.id)).toEqual([after.id, replayID, done.id])
      expect(received[1]).not.toHaveProperty("location")
    }),
  )
})

import { describe, expect } from "bun:test"
import { Cause, Deferred, Effect, Exit, Fiber, Layer, Ref, Schema, Stream } from "effect"
import { Bus } from "@opencode/core/bus"
import { Event } from "@opencode/schema/event"
import { Session } from "@opencode/schema/session"
import { SessionEvent } from "@opencode/schema/session-event"
import { Database } from "@opencode/core/database/database"
import { AppNodeBuilder } from "@opencode/core/effect/app-node-builder"
import { LayerNode } from "@opencode/util/effect/layer-node"
import { EventSequenceTable, EventTable } from "@opencode/core/event/sql"
import { Location } from "@opencode/core/location"
import { AbsolutePath } from "@opencode/core/schema"
import { Workspace } from "@opencode/core/workspace"
import { eq } from "drizzle-orm"
import { location } from "./fixture/location"
import { testEffect } from "./lib/effect"

const locationLayer = Layer.succeed(
  Location.Service,
  Location.Service.of(
    location({ directory: AbsolutePath.make("project"), workspaceID: Workspace.ID.make("wrk_test") }),
  ),
)
const Message = Bus.ephemeral({
  type: "test.message",
  schema: {
    text: Schema.String,
  },
})

const SyncMessage = Bus.durable({
  type: "test.sync",
  durable: {
    version: 1,
    aggregate: "id",
  },
  schema: {
    id: Schema.String,
    text: Schema.String,
  },
})

const SyncSent = Bus.durable({
  type: "test.sent",
  durable: {
    version: 1,
    aggregate: "messageID",
  },
  schema: {
    messageID: Schema.String,
    text: Schema.String,
  },
})

const VersionedMessageV1 = Bus.durable({
  type: "test.versioned",
  durable: { version: 1, aggregate: "id" },
  schema: { id: Schema.String },
})
const VersionedMessageV2 = Bus.durable({
  type: "test.versioned",
  durable: { version: 2, aggregate: "id" },
  schema: { id: Schema.String },
})

const GlobalMessage = Bus.ephemeral({
  type: "test.global",
  schema: {
    text: Schema.String,
  },
})
const CountMessage = Bus.ephemeral({
  type: "test.count",
  schema: {
    count: Schema.Number,
  },
})

const VersionedMessage = Bus.durable({
  type: "test.versioned",
  durable: {
    version: 2,
    aggregate: "id",
  },
  schema: {
    id: Schema.String,
    text: Schema.String,
  },
})

const DurableMessage = SessionEvent.Renamed
const durableData = (sessionID: Session.ID, text: string) => ({
  sessionID,
  title: text,
})

/** Followed log read without markers: the old `durable` stream shape. */
const tail = (bus: Bus.Interface, input: { aggregateID: string; after?: number }) =>
  bus.log({ ...input, follow: true }).pipe(Stream.filter((item): item is Event.Payload => !Bus.isSynced(item)))

const it = testEffect(
  AppNodeBuilder.build(LayerNode.group([Database.node, Bus.node, Location.node]), [
    Location.node.replace(locationLayer),
    Bus.node.replace(Bus.configured({ persist: true })),
  ]),
)
const itWithoutLocation = testEffect(
  AppNodeBuilder.build(LayerNode.group([Database.node, Bus.node]), [
    Bus.node.replace(Bus.configured({ persist: true })),
  ]),
)
const itWithoutPersistence = testEffect(AppNodeBuilder.build(LayerNode.group([Database.node, Bus.node])))

describe("Bus", () => {
  it.effect("subscribes to multiple event definitions with a discriminated payload union", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      // @ts-expect-error multi-definition subscriptions require at least one definition
      bus.subscribe([])
      const fiber = yield* bus
        .subscribe([Message, CountMessage])
        .pipe(Stream.take(2), Stream.runCollect, Effect.forkScoped)
      yield* Effect.yieldNow

      yield* bus.publish(Message, { text: "hello" })
      yield* bus.publish(CountMessage, { count: 2 })

      const received = (yield* Fiber.join(fiber)).map((event) =>
        event.type === "test.message" ? event.data.text : event.data.count,
      )
      expect(received).toEqual(["hello", 2])
    }),
  )

  it.effect("publishes events with the current location", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const fiber = yield* bus.subscribe(Message).pipe(Stream.take(1), Stream.runCollect, Effect.forkScoped)
      yield* Effect.yieldNow
      const event = yield* bus.publish(Message, { text: "hello" })
      const received = yield* Fiber.join(fiber)

      expect(received).toEqual([event])
      expect(event.type).toBe("test.message")
      expect(event).not.toHaveProperty("version")
      expect(event.data).toEqual({ text: "hello" })
      expect(event.location).toEqual({
        directory: AbsolutePath.make("project"),
        workspaceID: Workspace.ID.make("wrk_test"),
      })
    }),
  )

  it.effect("omits ambient and explicit locations for global events", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const event = yield* bus.publish(
        GlobalMessage,
        { text: "hello" },
        {
          global: true,
          location: { directory: AbsolutePath.make("explicit"), workspaceID: Workspace.ID.make("wrk_explicit") },
        },
      )

      expect(event).not.toHaveProperty("location")
      expect(event.type).toBe("test.global")
    }),
  )

  itWithoutLocation.effect("omits location when no location is available", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const event = yield* bus.publish(GlobalMessage, { text: "hello" })

      expect(event).not.toHaveProperty("location")
      expect(event.type).toBe("test.global")
    }),
  )

  it.effect("publishes definition version", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const event = yield* bus.publish(VersionedMessage, { id: "one", text: "hello" })

      expect(event.type).toBe("test.versioned")
      expect(event.durable?.version).toBe(Event.Version.make(2))
    }),
  )

  it.effect("selects the latest durable definition independent of declaration order", () =>
    Effect.sync(() => {
      const latest = Bus.durable({
        type: "test.out-of-order",
        durable: { version: 2, aggregate: "id" },
        schema: { id: Schema.String },
      })
      const historical = Bus.durable({
        type: "test.out-of-order",
        durable: { version: 1, aggregate: "id" },
        schema: { id: Schema.String },
      })

      expect(Event.latest([latest, historical]).get("test.out-of-order")).toBe(latest)
      expect(Event.latest([historical, latest]).get("test.out-of-order")).toBe(latest)
    }),
  )

  it.effect("publishes to typed and wildcard subscriptions", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const typed = yield* bus.subscribe(Message).pipe(Stream.take(1), Stream.runCollect, Effect.forkScoped)
      const wildcard = yield* bus.subscribe().pipe(Stream.take(1), Stream.runCollect, Effect.forkScoped)
      yield* Effect.yieldNow
      const event = yield* bus.publish(Message, { text: "hello" })

      expect(yield* Fiber.join(typed)).toEqual([event])
      expect(yield* Fiber.join(wildcard)).toEqual([event])
    }),
  )

  it.effect("runs projectors inline", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const received = new Array<Event.Payload>()
      yield* bus.project(SyncMessage, (event) =>
        Effect.sync(() => {
          received.push(event)
        }),
      )

      const event = yield* bus.publish(SyncMessage, { id: "one", text: "hello" })
      yield* bus.publish(SyncMessage, { id: "one", text: "second event" })

      expect(received[0]).toEqual(event)
      expect(received[1]?.data).toEqual({ id: "one", text: "second event" })
    }),
  )

  it.effect("commits local operational state inside a new durable event transaction", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const received = new Array<string>()
      const aggregateID = Event.ID.create()
      yield* bus.project(SyncMessage, () => Effect.sync(() => received.push("projector")))

      yield* bus.publish(
        SyncMessage,
        { id: aggregateID, text: "hello" },
        { commit: (seq) => Effect.sync(() => received.push(`commit:${seq}`)) },
      )

      expect(received).toEqual(["projector", "commit:0"])
    }),
  )

  it.effect("rolls back the durable event and projector when the local commit fails", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const { db } = yield* Database.Service
      const aggregateID = Event.ID.create()
      yield* db.run("CREATE TABLE IF NOT EXISTS event_commit_probe (value text NOT NULL)")
      yield* db.run("DELETE FROM event_commit_probe")
      yield* bus.project(SyncMessage, () =>
        db.run("INSERT INTO event_commit_probe (value) VALUES ('projected')").pipe(Effect.orDie, Effect.asVoid),
      )

      const exit = yield* bus
        .publish(SyncMessage, { id: aggregateID, text: "hello" }, { commit: () => Effect.die("commit failed") })
        .pipe(Effect.exit)

      expect(String(exit)).toContain("commit failed")
      expect(yield* db.all("SELECT value FROM event_commit_probe")).toEqual([])
      expect(yield* db.select().from(EventTable).where(eq(EventTable.aggregate_id, aggregateID)).all()).toEqual([])
      expect(
        yield* db.select().from(EventSequenceTable).where(eq(EventSequenceTable.aggregate_id, aggregateID)).all(),
      ).toEqual([])
    }),
  )

  itWithoutPersistence.effect("projects durable events without retaining their payloads", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const { db } = yield* Database.Service
      const aggregateID = Event.ID.create()
      yield* db.run("CREATE TABLE IF NOT EXISTS event_commit_probe (value text NOT NULL)")
      yield* bus.project(SyncMessage, () =>
        db.run("INSERT INTO event_commit_probe (value) VALUES ('projected')").pipe(Effect.orDie, Effect.asVoid),
      )

      const event = yield* bus.publish(SyncMessage, { id: aggregateID, text: "hello" })

      expect(event.durable?.seq).toBe(Event.Seq.make(0))
      expect(yield* db.all("SELECT value FROM event_commit_probe")).toEqual([{ value: "projected" }])
      expect(yield* db.select().from(EventTable).where(eq(EventTable.aggregate_id, aggregateID)).all()).toEqual([])
      expect(
        yield* db.select().from(EventSequenceTable).where(eq(EventSequenceTable.aggregate_id, aggregateID)).all(),
      ).toEqual([{ aggregate_id: aggregateID, seq: 0, owner_id: null }])
    }),
  )

  it.effect("rejects local commit hooks on live-only events", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const exit = yield* bus.publish(Message, { text: "hello" }, { commit: () => Effect.void }).pipe(Effect.exit)

      expect(String(exit)).toContain("Local commit hooks require a durable event")
    }),
  )

  it.effect("runs projectors before publishing to streams", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const received = new Array<string>()
      const fiber = yield* bus.subscribe().pipe(
        Stream.take(1),
        Stream.runForEach(() => Effect.sync(() => received.push("stream"))),
        Effect.forkScoped,
      )
      yield* bus.project(SyncMessage, (event) =>
        Effect.sync(() => {
          received.push(event.type)
        }),
      )

      yield* Effect.yieldNow
      yield* bus.publish(SyncMessage, { id: "one", text: "hello" })
      yield* Fiber.join(fiber)

      expect(received).toEqual([SyncMessage.type, "stream"])
    }),
  )

  it.effect("runs listeners inline after projectors", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const received = new Array<string>()
      yield* bus.project(SyncMessage, () =>
        Effect.sync(() => {
          received.push("projector")
        }),
      )
      const unsubscribe = yield* bus.listen(() =>
        Effect.sync(() => {
          received.push("listener")
        }),
      )

      yield* bus.publish(SyncMessage, { id: "one", text: "hello" })
      yield* unsubscribe
      yield* bus.publish(SyncMessage, { id: "one", text: "after unsubscribe" })

      expect(received).toEqual(["projector", "listener", "projector"])
    }),
  )

  it.effect("isolates observer defects after durable events commit", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const received = new Array<string>()
      yield* bus.listen(() => {
        throw new Error("listener defect")
      })
      yield* bus.listen((event) =>
        Effect.sync(() => {
          received.push(event.type)
        }),
      )

      const event = yield* bus.publish(SyncMessage, { id: "one", text: "hello" })

      expect(received).toEqual([SyncMessage.type])
      expect(event.durable?.seq).toBeNumber()
    }),
  )

  it.effect("notifies global listeners only after a durable event is committed", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const { db } = yield* Database.Service
      const aggregateID = Event.ID.create()
      const observed = new Array<{ id: string; seq: number }>()
      yield* bus.listen((event) =>
        event.type !== SyncMessage.type
          ? Effect.void
          : db
              .select({ id: EventTable.id, seq: EventTable.seq })
              .from(EventTable)
              .where(eq(EventTable.id, event.id))
              .get()
              .pipe(
                Effect.orDie,
                Effect.tap((row) =>
                  Effect.sync(() => {
                    if (row) observed.push(row)
                  }),
                ),
                Effect.asVoid,
              ),
      )

      const event = yield* bus.publish(SyncMessage, { id: aggregateID, text: "committed" })
      if (!event.durable) throw new Error("Expected durable event metadata")

      expect(observed).toEqual([{ id: event.id, seq: event.durable.seq }])
    }),
  )

  it.effect("preserves observer interruption", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const { db } = yield* Database.Service
      yield* bus.listen(() => Effect.interrupt)

      const exit = yield* bus.publish(SyncMessage, { id: "interrupted", text: "hello" }).pipe(Effect.exit)
      const committed = yield* db
        .select({ id: EventTable.id })
        .from(EventTable)
        .where(eq(EventTable.aggregate_id, "interrupted"))
        .get()
        .pipe(Effect.orDie)

      expect(Exit.isFailure(exit) && Cause.hasInterrupts(exit.cause)).toBeTrue()
      expect(committed).toBeDefined()
    }),
  )

  it.effect("keeps live-only listener defects fail-fast", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
      const defect = new Error("listener defect")
      yield* bus.listen(() => Effect.die(defect))

      expect(yield* bus.publish(Message, { text: "hello" }).pipe(Effect.catchDefect(Effect.succeed))).toBe(defect)
    }),
  )

  it.effect("inserts durable event rows on publish", () =>
    Effect.gen(function* () {
      const bus = yield* Bus.Service
