const content = {
  uri: "file:///pixel.png",
  content: "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=",
  encoding: "base64" as const,
  mime: "image/png",
}

describe("ConfigImagePlugin.Plugin", () => {
  it.live("merges image limits and reloads changed config", () =>
    Effect.gen(function* () {
      const image = yield* Image.Service
      const bus = yield* Bus.Service
      const config = yield* Config.Test
      const plugins = yield* Plugin.Service
      yield* ConfigImagePlugin.Plugin.effect(yield* PluginHost.make(plugins))

      expect(yield* limits(image)).toEqual({ maxWidth: 1_200, maxHeight: 900, maxBytes: 1 })

      yield* config.setEntries([document({ auto_resize: false, max_width: 700, max_base64_bytes: 1 })])
      yield* bus.publish(Event.Updated, {})
      yield* waitUntil(
        limits(image).pipe(
          Effect.map((current) => current.maxWidth === 700 && current.maxHeight === 2_000 && current.maxBytes === 1),
        ),
      )
    }).pipe(
      Effect.provide(
        Config.testLayer([
          document({ auto_resize: false, max_width: 1_200 }),
          document({ max_height: 900, max_base64_bytes: 1 }),
        ]),
      ),
    ),
  )

  it.live("refetches config after subscribing to updates", () =>
    Effect.gen(function* () {
      const image = yield* Image.Service
      const plugins = yield* Plugin.Service
      let reads = 0
      const config = Config.Service.of({
        entries: () => Effect.sync(() => [document({ max_width: reads++ === 0 ? 1_200 : 700, max_base64_bytes: 1 })]),
        changes: () => Stream.empty,
      })
      yield* ConfigImagePlugin.Plugin.effect(yield* PluginHost.make(plugins)).pipe(
        Effect.provideService(Config.Service, config),
      )

      expect(yield* limits(image)).toEqual({ maxWidth: 700, maxHeight: 2_000, maxBytes: 1 })
    }),
  )
})

function document(image: NonNullable<typeof Info.Encoded.media>["image"]): Entry {
  return new Document({ type: "document", info: decode({ media: { image } }) })
}

const limits = Effect.fnUntraced(function* (image: Image.Interface) {
  const error = yield* image.normalize("pixel.png", content).pipe(Effect.flip, Effect.orDie)
  if (error._tag !== "Image.SizeError") return yield* Effect.die(error)
  return { maxWidth: error.maxWidth, maxHeight: error.maxHeight, maxBytes: error.maxBytes }
})

const waitUntil = Effect.fnUntraced(function* (condition: Effect.Effect<boolean>) {
  for (let attempt = 0; attempt < 200; attempt++) {
    if (yield* condition) return
    yield* Effect.sleep("10 millis")
  }
  yield* Effect.die(new Error("Timed out waiting for image config reload"))
})

import { describe, expect, test } from "bun:test"
import { ConfigMarkdown } from "@opencode/core/config/markdown"

const invalidYaml = `---
description: Use when the user needs to crawl pages. Keywords: crawl, scrape
---
body`

describe("ConfigMarkdown.parse", () => {
  test("recovers unquoted-colon frontmatter via the sanitize fallback", () => {
    const parsed = ConfigMarkdown.parse(invalidYaml)
    expect(parsed.data.description).toBe("Use when the user needs to crawl pages. Keywords: crawl, scrape")
    expect(parsed.content.trim()).toBe("body")
  })

  test("recovers the same content again after a previous failed parse", () => {
    // gray-matter caches by content before parsing; a poisoned entry used to
    // make every later parse of the same text return silently without data.
    expect(() => ConfigMarkdown.parse("---\ndescription: [unclosed\n---\nbody")).toThrow()
    const parsed = ConfigMarkdown.parse(invalidYaml)
    expect(parsed.data.description).toBe("Use when the user needs to crawl pages. Keywords: crawl, scrape")
  })

  test("keeps throwing for the same unparseable content on every call", () => {
    const input = "---\ndescription: [unclosed\n---\nbody"
    expect(() => ConfigMarkdown.parse(input)).toThrow()
    expect(() => ConfigMarkdown.parse(input)).toThrow()
  })

  test("parses plain content without frontmatter", () => {
    const parsed = ConfigMarkdown.parse("just body")
    expect(parsed.content).toBe("just body")
    expect(parsed.data).toEqual({})
  })
})

import { describe, expect, test } from "bun:test"
import { ConfigModel } from "@opencode/schema/config/model"
import { Model } from "@opencode/schema/model"
import { Provider } from "@opencode/schema/provider"
import { Schema } from "effect"

const decode = Schema.decodeUnknownSync(ConfigModel.Selection)

describe("ConfigModel.Selection", () => {
  test("normalizes short and explicit model selections", () => {
    expect(decode("openrouter/openai/gpt-5#high")).toEqual({
      providerID: Provider.ID.make("openrouter"),
      model: Model.ID.make("openai/gpt-5"),
      variant: Model.VariantID.make("high"),
    })
    expect(decode({ providerID: "anthropic", model: "claude-sonnet", variant: "high" })).toEqual({
      providerID: Provider.ID.make("anthropic"),
      model: Model.ID.make("claude-sonnet"),
      variant: Model.VariantID.make("high"),
