import assert from "node:assert/strict"
import { spawn } from "../../src/pty/pty.bun"

const raw = process.argv[2] === "raw"
const pty = spawn(
  Bun.which("pwsh") ?? "powershell.exe",
  [
    "-NoLogo",
    "-NoProfile",
    ...(raw ? [] : ["-NoExit"]),
    "-Command",
    raw
      ? "[Console]::TreatControlCAsInput = $true; Write-Output 'PTY_RAW_READY'; $key = [Console]::ReadKey($true); Write-Output ('PTY_KEY:' + [int]$key.KeyChar)"
      : "Remove-Module PSReadLine -ErrorAction SilentlyContinue; function prompt { 'PTY_PROMPT> ' }",
  ],
  { name: "xterm-256color", cols: 160, rows: 24, env: { ...process.env, TERM: "xterm-256color" } },
)
const output = { text: "", cursor: 0 }
const listeners = new Set<() => void>()
const exited = Promise.withResolvers<number>()
pty.onExit((event) => exited.resolve(event.exitCode))
pty.onData((text) => {
  output.text += text
  listeners.forEach((check) => check())
})

try {
  if (raw) {
    await waitFor("PTY_RAW_READY")
    pty.write("\x03")
    await waitFor("PTY_KEY:3")
  }
  if (!raw) {
    await waitFor("PTY_PROMPT>")
    // Split markers so echoed command text cannot satisfy the output checks.
    pty.write("Write-Output ('PTY_' + 'BUSY'); Start-Sleep -Seconds 60; Write-Output ('PTY_' + 'COMPLETED')\r")
    await waitFor("PTY_BUSY")
    pty.write("\x03")
    await waitFor("PTY_PROMPT>")
    assert.ok(!output.text.includes("PTY_COMPLETED"))
    pty.write("Write-Output ('PTY_' + 'REUSED')\r")
    await waitFor("PTY_REUSED")
    await waitFor("PTY_PROMPT>")
    pty.write("exit 0\r")
  }
  assert.equal(await exited.promise, 0)
} finally {
  pty.kill()
}
process.exit(0)

function waitFor(text: string) {
  return new Promise<void>((resolve, reject) => {
    const timeout = setTimeout(() => {
      listeners.delete(check)
      reject(new Error(`Timed out waiting for ${JSON.stringify(text)}: ${output.text}`))
    }, 5_000)
    const check = () => {
      const index = output.text.indexOf(text, output.cursor)
      if (index === -1) return
      output.cursor = index + text.length
      listeners.delete(check)
      clearTimeout(timeout)
      resolve()
    }
    listeners.add(check)
    check()
  })
}

export function fakeSelectorSdk(calls: string[]) {
  const make = (method: string) => (id: string) => {
    calls.push(`${method}:${id}`)
    return { modelId: id, provider: method, specificationVersion: "v3" }
  }
  return {
    responses: make("responses"),
    messages: make("messages"),
    chat: make("chat"),
    languageModel: make("languageModel"),
  }
}

import fs from "fs/promises"
import os from "os"
import path from "path"
import { Effect } from "effect"

type TempDir = { readonly path: string }

export const tmpdir = async (prefix = "opencode-core-test-") => {
  const dir = await make(prefix)
  return {
    path: dir,
    [Symbol.asyncDispose]() {
      return remove(dir)
    },
  }
}

export const tmpdirScoped = (prefix = "opencode-core-test-") =>
  Effect.acquireRelease(
    Effect.tryPromise(() => make(prefix)),
    (dir) => Effect.tryPromise(() => remove(dir)).pipe(Effect.orDie),
  ).pipe(Effect.map((path) => ({ path })))

export const withTempDir = <A, E, R>(body: (tmp: TempDir) => Effect.Effect<A, E, R>) =>
  Effect.acquireUseRelease(
    Effect.tryPromise(() => make("opencode-core-test-")),
    (path) => body({ path }),
    (dir) => Effect.tryPromise(() => remove(dir)).pipe(Effect.orDie),
  )

const make = async (prefix: string) => fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), prefix)))

// Bun's callback APIs expose short paths and can hang during recursive removal on Windows.
async function remove(dir: string, retries = 30): Promise<void> {
  try {
    await fs.rm(dir, { recursive: true, force: true })
  } catch (error) {
    if (retries === 0 || !error || typeof error !== "object" || !("code" in error) || error.code !== "EBUSY")
      throw error
    Bun.gc(true)
    await Bun.sleep(100)
    return remove(dir, retries - 1)
  }
}

import { describe, expect } from "bun:test"
import { Deferred, Effect, Exit, Fiber } from "effect"
import { AppNodeBuilder } from "@opencode/core/effect/app-node-builder"
import { LayerNode } from "@opencode/util/effect/layer-node"
import { Bus } from "@opencode/core/bus"
import { Form } from "@opencode/core/form"
import { SessionSchema } from "@opencode/core/session/schema"
import { testEffect } from "./lib/effect"

const forms = AppNodeBuilder.build(LayerNode.group([Bus.node, Form.node]))
const it = testEffect(forms)

const formID = Form.ID.create("frm_test")
const input = {
  id: formID,
  sessionID: SessionSchema.ID.make("ses_test"),
  title: "Test form",
  fields: [{ key: "name", type: "string", required: true }],
} satisfies Form.CreateInput

describe("Form", () => {
  it.effect("validates absolute URI formats without restricting schemes", () =>
    Effect.sync(() => {
      const fields = [{ key: "uri", type: "string", format: "uri" }] satisfies ReadonlyArray<Form.Field>

      expect(Form.validateAnswer(fields, { uri: "https://example.com/path" })).toBeUndefined()
      expect(Form.validateAnswer(fields, { uri: "mailto:user@example.com" })).toBeUndefined()
      expect(Form.validateAnswer(fields, { uri: "relative/path" })).toBe("Expected URI for form field: uri")
      expect(Form.validateAnswer(fields, { uri: "://invalid" })).toBe("Expected URI for form field: uri")
    }),
  )

  it.effect("returns a terminal cancelled state from ask", () =>
    Effect.gen(function* () {
      const service = yield* Form.Service
      const bus = yield* Bus.Service
      const created = yield* Deferred.make<Form.Info>()
      const unsubscribe = yield* bus.listen((event) =>
        event.type === Form.Event.Created.type
          ? Deferred.succeed(created, (event.data as { readonly form: Form.Info }).form).pipe(Effect.asVoid)
          : Effect.void,
      )
      yield* Effect.addFinalizer(() => unsubscribe)
      const fiber = yield* service.ask(input).pipe(Effect.forkScoped)
      const form = yield* Deferred.await(created)

      yield* service.cancel(form.id)

      expect(yield* Fiber.join(fiber)).toEqual({ status: "cancelled" })
      expect(yield* service.state(form.id)).toEqual({ status: "cancelled" })
    }),
  )

  it.effect("supports the temporary global mcp elicitation owner", () =>
    Effect.gen(function* () {
      const service = yield* Form.Service
      const created = yield* service.create({
        sessionID: "global",
        title: "MCP input",
        fields: [{ key: "name", type: "string", required: true }],
      })
      expect(created.sessionID).toBe("global")
      expect(created.title).toBe("MCP input")

      const owned = yield* service.list({ sessionID: "global" })
      expect(owned.map((form) => form.id)).toEqual([created.id])
      expect(yield* service.list({ sessionID: "other" })).toEqual([])

      yield* service.reply({ id: created.id, answer: { name: "Ava" } })
      expect(yield* service.state(created.id)).toEqual({ status: "answered", answer: { name: "Ava" } })

      const externalOnly = yield* service.create({
        sessionID: "global",
        title: "External setup",
        fields: [{ key: "setup", type: "external", url: "https://example.com/setup" }],
      })
      yield* service.reply({ id: externalOnly.id, answer: { setup: true } })
      expect(yield* service.state(externalOnly.id)).toEqual({ status: "answered", answer: { setup: true } })
    }),
  )

  it.effect("gates required fields and rejects inactive answers via when", () =>
    Effect.gen(function* () {
      const service = yield* Form.Service
      const created = yield* service.create({
        sessionID: "global",
        title: "Conditional form",
        fields: [
          { key: "confirm", type: "boolean", required: true },
          { key: "reason", type: "string", required: true, when: [{ key: "confirm", op: "eq", value: false }] },
        ],
      })

      const inactive = yield* service
        .reply({ id: created.id, answer: { confirm: true, reason: "x" } })
        .pipe(Effect.flip)
      expect(inactive).toEqual(
        new Form.InvalidAnswerError({ id: created.id, message: "Form field is not active: reason" }),
      )

      const missing = yield* service.reply({ id: created.id, answer: { confirm: false } }).pipe(Effect.flip)
      expect(missing).toEqual(
        new Form.InvalidAnswerError({ id: created.id, message: "Missing required form field: reason" }),
      )

      yield* service.reply({ id: created.id, answer: { confirm: false, reason: "not ready" } })
      expect(yield* service.state(created.id)).toEqual({
        status: "answered",
        answer: { confirm: false, reason: "not ready" },
      })
    }),
  )

  it.effect("evaluates when against multiselect answers as inclusion", () =>
    Effect.gen(function* () {
      const service = yield* Form.Service
      const options = [
        { value: "go", label: "Go" },
        { value: "ts", label: "TypeScript" },
      ]
      const created = yield* service.create({
        sessionID: "global",
        title: "Multiselect form",
        fields: [
          { key: "langs", type: "multiselect", options },
          { key: "goVersion", type: "string", required: true, when: [{ key: "langs", op: "eq", value: "go" }] },
        ],
      })

      const missing = yield* service.reply({ id: created.id, answer: { langs: ["go", "ts"] } }).pipe(Effect.flip)
      expect(missing).toEqual(
        new Form.InvalidAnswerError({ id: created.id, message: "Missing required form field: goVersion" }),
      )

      yield* service.reply({ id: created.id, answer: { langs: ["ts"] } })
      expect(yield* service.state(created.id)).toEqual({ status: "answered", answer: { langs: ["ts"] } })
    }),
  )

  it.effect("requires every when condition to match and treats empty when as active", () =>
    Effect.gen(function* () {
      const service = yield* Form.Service
      const created = yield* service.create({
        sessionID: "global",
        title: "Dependent form",
        fields: [
          { key: "a", type: "boolean" },
          { key: "b", type: "boolean" },
          {
            key: "x",
            type: "string",
            required: true,
            when: [
              { key: "a", op: "eq", value: true },
              { key: "b", op: "eq", value: true },
            ],
          },
          { key: "z", type: "string", required: true, when: [] },
        ],
      })

      const missingX = yield* service.reply({ id: created.id, answer: { a: true, b: true, z: "ok" } }).pipe(Effect.flip)
      expect(missingX).toEqual(
        new Form.InvalidAnswerError({ id: created.id, message: "Missing required form field: x" }),
      )

      const inactiveX = yield* service
        .reply({ id: created.id, answer: { a: true, b: false, x: "nope", z: "ok" } })
        .pipe(Effect.flip)
      expect(inactiveX).toEqual(new Form.InvalidAnswerError({ id: created.id, message: "Form field is not active: x" }))

      const missingZ = yield* service.reply({ id: created.id, answer: { a: true, b: false } }).pipe(Effect.flip)
      expect(missingZ).toEqual(
        new Form.InvalidAnswerError({ id: created.id, message: "Missing required form field: z" }),
      )

      yield* service.reply({ id: created.id, answer: { a: true, b: false, z: "ok" } })
      expect(yield* service.state(created.id)).toEqual({ status: "answered", answer: { a: true, b: false, z: "ok" } })
    }),
  )

  it.effect("evaluates neq against multiselect answers as non-inclusion", () =>
    Effect.gen(function* () {
      const service = yield* Form.Service
      const options = [
        { value: "go", label: "Go" },
        { value: "ts", label: "TypeScript" },
      ]
      const created = yield* service.create({
        sessionID: "global",
        title: "Selection form",
        fields: [
          { key: "langs", type: "multiselect", options },
          { key: "note", type: "string", required: true, when: [{ key: "langs", op: "neq", value: "go" }] },
        ],
      })

      const missing = yield* service.reply({ id: created.id, answer: { langs: ["ts"] } }).pipe(Effect.flip)
      expect(missing).toEqual(
        new Form.InvalidAnswerError({ id: created.id, message: "Missing required form field: note" }),
      )

      // an answered-but-empty multiselect also satisfies neq
      const missingEmpty = yield* service.reply({ id: created.id, answer: { langs: [] } }).pipe(Effect.flip)
      expect(missingEmpty).toEqual(
        new Form.InvalidAnswerError({ id: created.id, message: "Missing required form field: note" }),
      )

      const inactive = yield* service.reply({ id: created.id, answer: { langs: ["go"], note: "x" } }).pipe(Effect.flip)
      expect(inactive).toEqual(
        new Form.InvalidAnswerError({ id: created.id, message: "Form field is not active: note" }),
      )

      yield* service.reply({ id: created.id, answer: { langs: ["go"] } })
      expect(yield* service.state(created.id)).toEqual({ status: "answered", answer: { langs: ["go"] } })
    }),
  )

  it.effect("treats unanswered when references as false and cascades inactivity", () =>
    Effect.gen(function* () {
      const service = yield* Form.Service
      const created = yield* service.create({
        sessionID: "global",
        title: "Cascading form",
        fields: [
          { key: "a", type: "boolean" },
          { key: "b", type: "string", when: [{ key: "a", op: "eq", value: true }] },
          // neq also fails against an unanswered reference, and hiding b cascades here through
          // the reject-inactive-answers rule: b can never be answered while a is false.
          { key: "c", type: "string", required: true, when: [{ key: "b", op: "neq", value: "x" }] },
        ],
      })

      const inactive = yield* service.reply({ id: created.id, answer: { a: false, b: "yes" } }).pipe(Effect.flip)
      expect(inactive).toEqual(new Form.InvalidAnswerError({ id: created.id, message: "Form field is not active: b" }))

      yield* service.reply({ id: created.id, answer: { a: false } })
      expect(yield* service.state(created.id)).toEqual({ status: "answered", answer: { a: false } })
    }),
  )

  it.effect("rejects invalid when definitions at creation", () =>
    Effect.gen(function* () {
      const service = yield* Form.Service
      const flipCreate = (fields: Form.CreateInput["fields"]) =>
        service.create({ sessionID: "global", title: "Invalid form", fields }).pipe(Effect.flip)

      expect(
        yield* flipCreate([{ key: "b", type: "string", when: [{ key: "missing", op: "eq", value: "x" }] }]),
      ).toEqual(
        new Form.InvalidFormError({ message: "Form field condition must reference an earlier field: b -> missing" }),
      )

      expect(
        yield* flipCreate([
          { key: "a", type: "string" },
          { key: "a", type: "string" },
        ]),
      ).toEqual(new Form.InvalidFormError({ message: "Duplicate form field key: a" }))

      expect(
        yield* flipCreate([
          { key: "a", type: "external", url: "https://example.com" },
          { key: "a", type: "string" },
        ]),
      ).toEqual(new Form.InvalidFormError({ message: "Duplicate form field key: a" }))

      expect(
        yield* flipCreate([
          { key: "a", type: "boolean" },
          { key: "b", type: "string", when: [{ key: "a", op: "eq", value: "yes" }] },
        ]),
      ).toEqual(new Form.InvalidFormError({ message: "Form field condition value must be a boolean: b -> a" }))

      expect(
        yield* flipCreate([
          { key: "a", type: "string", options: [{ value: "x", label: "X" }] },
          { key: "b", type: "string", when: [{ key: "a", op: "eq", value: "y" }] },
        ]),
      ).toEqual(
        new Form.InvalidFormError({
          message: "Form field condition value must be one of the field's options: b -> a",
        }),
      )
    }),
  )

  it.effect("requires external field acknowledgements", () =>
    Effect.gen(function* () {
      const service = yield* Form.Service
      const created = yield* service.create({
        sessionID: "global",
        title: "External setup",
        fields: [
          { key: "authorization", type: "external", url: "https://example.com/setup", title: "Open setup" },
          { key: "name", type: "string", required: true },
        ],
      })

      const invalidAnswers: ReadonlyArray<Form.Answer> = [
        { name: "Ava" },
        { authorization: false, name: "Ava" },
        { authorization: "yes", name: "Ava" },
      ]
      for (const answer of invalidAnswers) {
        expect(yield* service.reply({ id: created.id, answer }).pipe(Effect.flip)).toEqual(
          new Form.InvalidAnswerError({
            id: created.id,
            message: "External form field must be acknowledged: authorization",
          }),
        )
      }

      yield* service.reply({ id: created.id, answer: { authorization: true, name: "Ava" } })
      expect(yield* service.state(created.id)).toEqual({
        status: "answered",
        answer: { authorization: true, name: "Ava" },
      })
    }),
  )

  it.effect("cleans up created forms when event publication fails", () =>
    Effect.gen(function* () {
      const service = yield* Form.Service
      const bus = yield* Bus.Service
      const unsubscribe = yield* bus.listen((event) =>
        event.type === Form.Event.Created.type ? Effect.die("create listener failed") : Effect.void,
      )
      yield* Effect.addFinalizer(() => unsubscribe)

      expect(Exit.isFailure(yield* Effect.exit(service.create(input)))).toBe(true)
      expect(yield* service.get(formID).pipe(Effect.flip)).toEqual(new Form.NotFoundError({ id: formID }))

      yield* unsubscribe
      expect(yield* service.create(input)).toMatchObject({ id: formID })
    }),
  )

  it.effect("keeps forms pending when reply event publication fails", () =>
    Effect.gen(function* () {
      const service = yield* Form.Service
      const bus = yield* Bus.Service
      yield* service.create(input)
      const unsubscribe = yield* bus.listen((event) =>
        event.type === Form.Event.Replied.type ? Effect.die("reply listener failed") : Effect.void,
      )
      yield* Effect.addFinalizer(() => unsubscribe)

      expect(Exit.isFailure(yield* Effect.exit(service.reply({ id: formID, answer: { name: "Ava" } })))).toBe(true)
      expect(yield* service.state(formID)).toEqual({ status: "pending" })

      yield* unsubscribe
      yield* service.reply({ id: formID, answer: { name: "Ava" } })
      expect(yield* service.state(formID)).toEqual({ status: "answered", answer: { name: "Ava" } })
    }),
  )
})

import fs from "fs/promises"
import path from "path"
import { describe, expect } from "bun:test"
import { Deferred, Effect, Fiber } from "effect"
import { AppNodeBuilder } from "@opencode/core/effect/app-node-builder"
import { Bus } from "@opencode/core/bus"
import { Database } from "@opencode/core/database/database"
import { LocationServiceMap } from "@opencode/core/location-services"
import { Plugin } from "@opencode/core/plugin"
import { SdkPlugins } from "@opencode/core/plugin/sdk"
import { AbsolutePath } from "@opencode/core/schema"
import { Info } from "@opencode/schema/config"
import { Global } from "@opencode/util/global"
import { LayerNode } from "@opencode/util/effect/layer-node"
import { Formatter } from "../src/formatter"
import { Location } from "../src/location"
import { tempGlobalLayer } from "./fixture/global"
import { offlineModels } from "./fixture/models"
import { tmpdir } from "./fixture/tmpdir"
import { testEffect } from "./lib/effect"

const it = testEffect(
  AppNodeBuilder.build(
    LayerNode.group([Database.node, Bus.node, SdkPlugins.node, LocationServiceMap.node, Global.node]),
    [Global.node.replace(tempGlobalLayer), offlineModels],
  ),
)
type ConfigInput = typeof Info.Encoded

function withTemp<A, E, R>(body: (directory: string) => Effect.Effect<A, E, R>) {
  return Effect.acquireUseRelease(
    Effect.promise(() => tmpdir()),
    (tmp) => body(tmp.path),
    (tmp) => Effect.promise(() => tmp[Symbol.asyncDispose]()),
  )
}

function withFormatter<A, E, R>(
  configured: ConfigInput["formatter"],
  body: (formatter: Formatter.Interface, directory: string) => Effect.Effect<A, E, R>,
) {
  return withTemp((directory) =>
    Effect.promise(() =>
      fs.writeFile(path.join(directory, "opencode.json"), JSON.stringify({ formatter: configured })),
    ).pipe(
      Effect.andThen(
        Effect.gen(function* () {
          const plugins = yield* Plugin.Service
          yield* plugins.awaitActivation
          return yield* body(yield* Formatter.Service, directory)
        }).pipe(
          Effect.scoped,
          Effect.provide(
            LocationServiceMap.Service.get(Location.Ref.make({ directory: AbsolutePath.make(directory) })),
          ),
        ),
      ),
    ),
  )
}

function append(expression: string) {
  return [process.execPath, "-e", `require('fs').appendFileSync(process.argv.at(-1), ${expression})`, "$FILE"]
}

const markdown = { command: append("'md'"), extensions: [".md"] }
const project = { command: append("'project'"), extensions: [".project"] }

// Writes formatter config layers from lowest to highest priority: global, project, then project .opencode.
function withLayers<A, E, R>(
  layers: ConfigInput["formatter"][],
  body: (formatter: Formatter.Interface, directory: string) => Effect.Effect<A, E, R>,
) {
  return withTemp((directory) =>
    Effect.gen(function* () {
      const global = yield* Global.Service
      yield* Effect.promise(async () => {
        await fs.mkdir(path.join(directory, ".opencode"))
        const files = [
          path.join(global.config, "opencode.jsonc"),
          path.join(directory, "opencode.json"),
          path.join(directory, ".opencode", "opencode.jsonc"),
        ]
        await Promise.all(layers.map((formatter, index) => fs.writeFile(files[index], JSON.stringify({ formatter }))))
      })
      return yield* Effect.gen(function* () {
        const plugins = yield* Plugin.Service
        yield* plugins.awaitActivation
        return yield* body(yield* Formatter.Service, directory)
      }).pipe(
        Effect.scoped,
        Effect.provide(LocationServiceMap.Service.get(Location.Ref.make({ directory: AbsolutePath.make(directory) }))),
      )
    }),
  )
}

const layered: { name: string; layers: ConfigInput["formatter"][]; expected: Record<string, string | false> }[] = [
  {
    name: "keeps lower formatters when a higher config adds another",
    layers: [{ markdown }, undefined, { project }],
    expected: { "test.md": "md", "test.project": "project" },
  },
  {
    name: "inherits omitted fields and replaces supplied arrays",
    layers: [
      { markdown: { command: append("'A'"), extensions: [".md", ".project"] } },
      { markdown: { command: append("'B'"), extensions: [".project"] } },
    ],
    expected: { "test.md": false, "test.project": "B" },
  },
  {
    name: "merges environment variables by key",
    layers: [
      {
        markdown: {
          ...markdown,
          command: append("process.env.FIRST + process.env.SECOND"),
          environment: { FIRST: "global", SECOND: "global" },
        },
      },
      { markdown: { environment: { SECOND: "project" } } },
    ],
    expected: { "test.md": "globalproject" },
  },
  {
    name: "keeps a lower disable through overrides that omit it",
    layers: [{ markdown: { ...markdown, disabled: true } }, { markdown: { command: append("'override'") }, project }],
    expected: { "test.md": false, "test.project": "project" },
  },
  {
    name: "re-enables a lower disabled formatter",
    layers: [{ markdown: { ...markdown, disabled: true } }, { markdown: { disabled: false } }],
    expected: { "test.md": "md" },
  },
  {
    name: "keeps lower formatters through an empty object",
    layers: [{ markdown }, {}],
    expected: { "test.md": "md" },
  },
  {
    name: "clears lower formatters when a higher config is false",
    layers: [{ markdown }, false],
    expected: { "test.md": false },
  },
  {
    name: "clears lower formatters before a later object when a higher config is true",
    layers: [{ markdown }, true, { project }],
    expected: { "test.md": false, "test.project": "project" },
  },
  {
    name: "enables only formatters configured after false",
    layers: [{ markdown }, false, { project }],
    expected: { "test.md": false, "test.project": "project" },
  },
]

describe("Formatter", () => {
  layered.forEach((entry) =>
    it.live(entry.name, () =>
      withLayers(entry.layers, (formatter, directory) =>
        Effect.forEach(Object.entries(entry.expected), ([name, expected]) =>
          Effect.gen(function* () {
            const file = path.join(directory, name)
            yield* Effect.promise(() => fs.writeFile(file, ""))
            const formatted = yield* formatter.file(file)
            expect(formatted && (yield* Effect.promise(() => fs.readFile(file, "utf8")))).toBe(expected)
          }),
        ),
      ),
    ),
  )
  ;[
    { file: "test.match", extension: ".match", matches: true },
    { file: "test.other", extension: ".match", matches: false },
    { file: "test.MATCH", extension: ".match", matches: false },
    { file: "test.MATCH", extension: ".MATCH", matches: true },
    { file: ".match", extension: ".match", matches: false },
    { file: ".match", extension: "", matches: true },
    { file: "README", extension: ".match", matches: false },
    { file: "README", extension: "", matches: true },
    { file: "test.part.match", extension: ".match", matches: true },
    { file: "test.part.match", extension: ".part.match", matches: false },
  ].forEach((entry) =>
    it.live(`matches ${entry.file} against ${JSON.stringify(entry.extension)}: ${entry.matches}`, () =>
      withFormatter(
        {
          matching: {
            command: [process.execPath, "-e", "process.exit(0)", "$FILE"],
            extensions: [entry.extension],
          },
        },
        (formatter, directory) =>
          Effect.gen(function* () {
            expect(yield* formatter.file(path.join(directory, entry.file))).toBe(entry.matches)
          }),
      ),
    ),
  )

  it.live("does not run formatters marked as disabled in config", () =>
    withFormatter(
      {
        disabled: {
          disabled: true,
          command: [process.execPath, "-e", "process.exit(0)", "$FILE"],
          extensions: [".disabled"],
        },
      },
      (formatter, directory) =>
        Effect.gen(function* () {
          const file = path.join(directory, "test.disabled")
          expect(yield* formatter.file(file)).toBe(false)
        }),
    ),
  )

  it.live("file() returns false when no formatter runs", () =>
    withFormatter(false, (formatter, directory) =>
      Effect.gen(function* () {
        const file = path.join(directory, "test.txt")
        yield* Effect.promise(() => fs.writeFile(file, "x"))
        expect(yield* formatter.file(file)).toBe(false)
      }),
    ),
  )

  it.live("loads formatter state per directory", () =>
    withFormatter(false, (disabledFormatter, off) =>
      withFormatter(
        {
          isolated: {
            command: [process.execPath, "-e", "process.exit(0)", "$FILE"],
            extensions: [".isolated"],
          },
        },
        (enabledFormatter, on) =>
          Effect.gen(function* () {
            const offFile = path.join(off, "test.isolated")
            const onFile = path.join(on, "test.isolated")
            const disabled = yield* disabledFormatter.file(offFile)
            const enabled = yield* enabledFormatter.file(onFile)
            expect(disabled).toBe(false)
            expect(enabled).toBe(true)
          }),
      ),
    ),
  )

  it.live("stops after the first matching formatter succeeds", () =>
    withFormatter(
      {
        first: {
          command: [
            process.execPath,
            "-e",
            "const fs = require('fs'); const file = process.argv.at(-1); fs.appendFileSync(file, 'A')",
            "$FILE",
          ],
          extensions: [".seq"],
        },
        second: {
          command: [
            process.execPath,
            "-e",
            "const fs = require('fs'); const file = process.argv.at(-1); fs.appendFileSync(file, 'B')",
            "$FILE",
          ],
          extensions: [".seq"],
        },
      },
      (formatter, directory) =>
        Effect.gen(function* () {
          const file = path.join(directory, "test.seq")
          yield* Effect.promise(() => fs.writeFile(file, "x"))
          expect(yield* formatter.file(file)).toBe(true)
          expect(yield* Effect.promise(() => fs.readFile(file, "utf8"))).toBe("xA")
        }),
    ),
  )

  it.live("tries the next matching formatter when the first fails", () =>
    withFormatter(
      {
        first: {
          command: [process.execPath, "-e", "process.exit(1)", "$FILE"],
          extensions: [".fallback"],
        },
        second: {
          command: [
            process.execPath,
            "-e",
            "const fs = require('fs'); const file = process.argv.at(-1); fs.appendFileSync(file, 'B')",
            "$FILE",
          ],
          extensions: [".fallback"],
        },
      },
      (formatter, directory) =>
        Effect.gen(function* () {
          const file = path.join(directory, "test.fallback")
          yield* Effect.promise(() => fs.writeFile(file, "x"))
          expect(yield* formatter.file(file)).toBe(true)
          expect(yield* Effect.promise(() => fs.readFile(file, "utf8"))).toBe("xB")
        }),
    ),
  )

  it.live("rebuilds formatter state and clears resolved commands", () =>
    withFormatter(false, (formatter, directory) =>
      Effect.gen(function* () {
        const command = { suffix: "A" }
        yield* formatter.transform((editor) => {
          const suffix = command.suffix
          editor.set({
            name: "reload",
            extensions: [".reload"],
            enabled: Effect.succeed([
              process.execPath,
              "-e",
              `const fs = require('fs'); const file = process.argv.at(-1); fs.appendFileSync(file, '${suffix}')`,
              "$FILE",
            ]),
          })
        })
        const file = path.join(directory, "test.reload")
        yield* Effect.promise(() => fs.writeFile(file, "x"))
        expect(yield* formatter.file(file)).toBe(true)

        command.suffix = "B"
        yield* formatter.reload()

        expect(yield* formatter.file(file)).toBe(true)
        expect(yield* Effect.promise(() => fs.readFile(file, "utf8"))).toBe("xAB")
      }),
    ),
  )

  it.live("does not cache a command resolved before reload", () =>
    withFormatter(false, (formatter, directory) =>
      Effect.gen(function* () {
        const resolving = yield* Deferred.make<void>()
        const release = yield* Deferred.make<void>()
        const command = { suffix: "A" }
        yield* formatter.transform((editor) => {
          const suffix = command.suffix
          const resolved = [
            process.execPath,
            "-e",
            `const fs = require('fs'); const file = process.argv.at(-1); fs.appendFileSync(file, '${suffix}')`,
            "$FILE",
          ]
          editor.set({
            name: "reload-race",
            extensions: [".race"],
            enabled:
              suffix === "A"
                ? Deferred.succeed(resolving, undefined).pipe(
                    Effect.andThen(Deferred.await(release)),
                    Effect.as(resolved),
                  )
                : Effect.succeed(resolved),
          })
        })
        const file = path.join(directory, "test.race")
        yield* Effect.promise(() => fs.writeFile(file, "x"))
        const first = yield* formatter.file(file).pipe(Effect.forkChild({ startImmediately: true }))
        yield* Deferred.await(resolving)

        command.suffix = "B"
        yield* formatter.reload()
        yield* Deferred.succeed(release, undefined)
        expect(yield* Fiber.join(first)).toBe(true)

        expect(yield* formatter.file(file)).toBe(true)
        expect(yield* Effect.promise(() => fs.readFile(file, "utf8"))).toBe("xAB")
      }),
    ),
  )
})

