import { KV } from "@opencode/core/kv"
import { WebSearch } from "@opencode/core/websearch"
import type { Session } from "@opencode/schema/session"

export interface Interface extends WebSearch.Interface {
  readonly queries: readonly WebSearch.Input[]
  readonly sessionIDs: readonly (Session.ID | undefined)[]
  /** Waits for query arrivals, not provider execution or query completion. */
  readonly wait: (count: number) => Effect.Effect<void>
}

export class Service extends Context.Service<Service, Interface>()("test/WebSearch") {}

export function httpError(status = 429, retryAfter?: string, url = "https://search.example.com") {
  const request = HttpClientRequest.post(url)
  return new HttpClientError.HttpClientError({
    reason: new HttpClientError.StatusCodeError({
      request,
      response: HttpClientResponse.fromWeb(
        request,
        new Response(null, { status, headers: retryAfter === undefined ? {} : { "Retry-After": retryAfter } }),
      ),
    }),
  })
}

// No providers are installed: tests register local executors through transform.
// The normal Bus and KV implementations use the default in-memory database.
export const layer = Layer.effectContext(
  Effect.gen(function* () {
    const context = yield* Layer.build(AppNodeBuilder.build(LayerNode.group([WebSearch.node, Bus.node, KV.node])))
    const websearch = Context.get(context, WebSearch.Service)
    const queries: WebSearch.Input[] = []
    const sessionIDs: (Session.ID | undefined)[] = []
    let started = yield* Deferred.make<void>()
    const wait = (count: number): Effect.Effect<void> =>
      Effect.suspend(() =>
        queries.length >= count ? Effect.void : Deferred.await(started).pipe(Effect.andThen(() => wait(count))),
      )
    const test = Service.of({
      ...websearch,
      queries,
      sessionIDs,
      wait,
      query: Effect.fnUntraced(function* (input, options) {
        queries.push({ ...input })
        sessionIDs.push(options?.sessionID)
        const previous = started
        started = yield* Deferred.make<void>()
        yield* Deferred.succeed(previous, undefined)
        return yield* websearch.query(input, options)
      }),
    })
    return Context.add(context, WebSearch.Service, test).pipe(Context.add(Service, test))
  }),
)

import { Buffer } from "node:buffer"
import { Effect } from "effect"

interface ConnectionData {
  readonly id: number
}

export interface WebSocketServerState {
  readonly headers: Array<Record<string, string>>
  readonly messages: string[]
  opens: number
  closes: number
  pongs: number
}

export interface WebSocketServerFixture {
  readonly url: string
  readonly state: WebSocketServerState
}

export interface WebSocketServerOptions {
  readonly http?: (request: Request) => Response | Promise<Response>
  readonly upgrade?: (request: Request) => boolean
  readonly open?: (socket: Bun.ServerWebSocket<ConnectionData>) => void
  readonly message?: (socket: Bun.ServerWebSocket<ConnectionData>, message: string | Buffer) => void
}

export const makeWebSocketServer = (options: WebSocketServerOptions = {}) =>
  Effect.acquireRelease(
    Effect.sync(() => {
      const state: WebSocketServerState = { headers: [], messages: [], opens: 0, closes: 0, pongs: 0 }
      let connection = 0
      const server = Bun.serve<ConnectionData>({
        hostname: "127.0.0.1",
        port: 0,
        fetch(request, server) {
          state.headers.push(Object.fromEntries(request.headers.entries()))
          if (request.headers.get("upgrade") !== "websocket" && options.http) return options.http(request)
          if ((options.upgrade?.(request) ?? true) && server.upgrade(request, { data: { id: connection++ } }))
            return undefined
          return new Response("WebSocket upgrade required", {
            status: 426,
            headers: { "x-upgrade-rejected": "true" },
          })
        },
        websocket: {
          open(socket) {
            state.opens++
            options.open?.(socket)
          },
          message(socket, message) {
            const text = typeof message === "string" ? message : message.toString()
            state.messages.push(text)
            options.message?.(socket, message)
          },
          close() {
            state.closes++
          },
          pong() {
            state.pongs++
          },
        },
      })
      return {
        server,
        fixture: {
          url: `${server.url.toString().replace(/^http/, "ws")}responses`,
          state,
        } satisfies WebSocketServerFixture,
      }
    }),
    ({ server }) => Effect.promise(() => server.stop(true)),
  ).pipe(Effect.map((item) => item.fixture))

