          Effect.gen(function* () {
            loads.push(`${id}@${revision}`)
            yield* ctx.command.transform((editor) => {
              editor.add({ name: id, execute: () => Effect.void })
              if (id === "broken" && fail) throw new Error("broken failed")
            })
          }),
      })
      const broken = generation("broken", "1")
