  yield* catalog.transform((catalog) => {
    catalog.update(Provider.ID.amazonBedrock, (item) => {
      item.package = "@opencode/ai/providers/amazon-bedrock"
      if (settings) item.settings = settings
    })
  })
  return catalog
})

