      ] as const
      for (const [code, retry] of cases) {
        const cause = new AIError({
          reason: classifyProviderFailure({
            message: "Request failed",
            rawBody: JSON.stringify({ type: "response.failed", response: { error: { code } } }),
          }),
        })
