  it.live(
    "discovers from configured endpoints with bearer authentication",
    () =>
      Effect.acquireUseRelease(
        Effect.sync(() => {
          const requests: Array<{ authorization: string | null; path: string }> = []
          const model = (key: string) => ({
            type: "llm",
            key,
            display_name: key,
            loaded_instances: [],
            max_context_length: 32_768,
          })
