            (model) => model !== undefined,
          )
          expect(requests.count).toBe(1)
        }),
      ({ server }) => Effect.promise(() => server.stop(true)),
    ),
  )

  it.live("replaces the credential-gated Models.dev catalog when discovery succeeds", () =>
    Effect.acquireUseRelease(
      Effect.sync(() => {
