            repository: input.reference.label,
            host: input.reference.host,
            remote: input.reference.remote,
            localPath: Repository.cachePath(Global.Path.repos, input.reference, input.branch),
            status: "cached",
          } satisfies RepositoryCache.Result
        }),
    })
    const referenceLayer = AppNodeBuilder.build(LayerNode.group([Reference.node, Bus.node]), [
      RepositoryCache.node.replace(cache),
    ])

    return Effect.gen(function* () {
      const references = yield* Reference.Service
      const bus = yield* Bus.Service
      const observed: string[][] = []
      yield* Effect.acquireRelease(
        bus.listen((event) =>
          event.type === Reference.Event.Updated.type
            ? references.list().pipe(
                Effect.map((infos) => {
                  observed.push(infos.map((info) => info.name))
                }),
              )
            : Effect.void,
        ),
        (unsubscribe) => unsubscribe,
      )

      yield* State.batch(
        Effect.gen(function* () {
          yield* references.transform((editor) =>
            editor.add("docs", Reference.LocalSource.make({ type: "local", path: AbsolutePath.make("/docs") })),
          )
          expect((yield* references.list()).map((info) => info.name)).toEqual(["docs"])

          yield* references.transform((editor) => {
            editor.add(
              "sdk",
              Reference.GitSource.make({
                type: "git",
                repository: "owner/repo",
                branch: "feature/docs",
                description: "SDK documentation",
                hidden: true,
              }),
            )
            editor.add("invalid", Reference.GitSource.make({ type: "git", repository: "invalid" }))
            editor.add(
              "invalid-branch",
              Reference.GitSource.make({ type: "git", repository: "owner/repo", branch: "../escape" }),
            )
            editor.add("file", Reference.GitSource.make({ type: "git", repository: "file:///docs" }))
          })
          const infos = yield* references.list()
          expect(infos.map((info) => info.name)).toEqual(["docs", "sdk"])
          expect(infos[1]).toMatchObject({
            path: Repository.cachePath(Global.Path.repos, Repository.parseRemote("owner/repo"), "feature/docs"),
            description: "SDK documentation",
            hidden: true,
          })
          yield* Effect.yieldNow
          expect(operations).toEqual([])
          expect(observed).toEqual([])
        }),
      )

      expect(observed).toEqual([["docs", "sdk"]])
      yield* Deferred.await(started)
      expect(operations).toEqual([
        { reference: Repository.parseRemote("owner/repo"), branch: "feature/docs", refresh: "daily" },
      ])
      expect((yield* references.list()).map((info) => info.name)).toEqual(["docs", "sdk"])
      yield* Effect.yieldNow
      expect(operations).toHaveLength(1)
      expect(observed).toHaveLength(1)
      yield* Deferred.succeed(release, undefined)
    }).pipe(Effect.scoped, Effect.provide(referenceLayer))
  })

  it.effect("lets update listeners replace references and refetch current info", () =>
    Effect.gen(function* () {
      const references = yield* Reference.Service
      const bus = yield* Bus.Service
      const scope = yield* Scope.Scope
      const observed: string[][] = []
      let reentered = false
      const first = yield* bus.listen((event) =>
        Effect.gen(function* () {
          if (event.type !== Reference.Event.Updated.type || reentered) return
          reentered = true
          yield* references
            .transform((editor) =>
              editor.add("docs", Reference.LocalSource.make({ type: "local", path: AbsolutePath.make("/new") })),
            )
            .pipe(Scope.provide(scope))
        }),
      )
      const second = yield* bus.listen((event) =>
        event.type === Reference.Event.Updated.type
          ? references.list().pipe(
              Effect.map((infos) => {
                observed.push(infos.map((info) => info.path))
              }),
            )
          : Effect.void,
      )
      yield* Effect.addFinalizer(() => first.pipe(Effect.andThen(second)))

      yield* references.transform((editor) =>
        editor.add("docs", Reference.LocalSource.make({ type: "local", path: AbsolutePath.make("/old") })),
      )

      expect((yield* references.list()).map((info) => info.path)).toEqual([AbsolutePath.make("/new")])
      expect(observed).toEqual([["/new"], ["/new"]])
    }).pipe(Effect.scoped, Effect.provide(referenceLayer)),
  )

  it.effect("registers normalized sources for the owning scope", () =>
    Effect.gen(function* () {
      const references = yield* Reference.Service
      const scope = yield* Scope.make()
      const path = AbsolutePath.make("/docs")
      const source = Reference.LocalSource.make({
        type: "local",
        path,
        description: "Use for API documentation",
        hidden: true,
      })
      yield* references.transform((editor) => editor.add("docs", source)).pipe(Scope.provide(scope))

      expect(yield* references.list()).toEqual([
        Reference.Info.make({ name: "docs", path, description: "Use for API documentation", hidden: true, source }),
      ])

      yield* Scope.close(scope, Exit.void)
      expect(yield* references.list()).toEqual([])
    }).pipe(Effect.provide(referenceLayer)),
  )

  it.effect("derives Git paths without exposing cache operations", () =>
    Effect.gen(function* () {
      const references = yield* Reference.Service
      const repository = Repository.parseRemote("owner/repo")
      const source = Reference.GitSource.make({ type: "git", repository: "owner/repo", branch: "main" })
      yield* references.transform((editor) => editor.add("sdk", source))

      expect(yield* references.list()).toEqual([
        Reference.Info.make({
          name: "sdk",
          path: AbsolutePath.make(Repository.cachePath(Global.Path.repos, repository, "main")),
          source,
        }),
      ])
    }).pipe(Effect.scoped, Effect.provide(referenceLayer)),
  )

  it.effect("preserves configured Git descriptions", () =>
    Effect.gen(function* () {
      const references = yield* Reference.Service
      const repository = Repository.parseRemote("owner/repo")
      const source = Reference.GitSource.make({
        type: "git",
        repository: "owner/repo",
        description: "Use for SDK implementation details",
      })
      yield* references.transform((editor) => editor.add("sdk", source))

      expect(yield* references.list()).toEqual([
        Reference.Info.make({
          name: "sdk",
          path: AbsolutePath.make(Repository.cachePath(Global.Path.repos, repository)),
          description: "Use for SDK implementation details",
          source,
        }),
      ])
    }).pipe(Effect.scoped, Effect.provide(referenceLayer)),
  )
})

import { describe, expect, setDefaultTimeout } from "bun:test"
import fs from "fs/promises"
import path from "path"
import { pathToFileURL } from "url"
import { Clock, Duration, Effect, Layer } from "effect"
import { AppNodeBuilder } from "@opencode/core/effect/app-node-builder"
import { Global } from "@opencode/util/global"
import { Repository } from "@opencode/core/repository"
import { RepositoryCache } from "@opencode/core/repository-cache"
import { Database } from "@opencode/core/database/database"
import { KV } from "@opencode/core/kv"
import { LayerNode } from "@opencode/util/effect/layer-node"
import { branch, commit, git, read, withRemote } from "./fixture/git"
import { testEffect } from "./lib/effect"

const it = testEffect(Layer.empty)

// Cold Git setup and cloning can exceed Bun's five-second default on Windows.
setDefaultTimeout(30_000)

describe("RepositoryCache", () => {
  it.live("persists the daily throttle across cache recreation and serializes competing refreshes", () =>
    withRemote((fixture) =>
      Effect.gen(function* () {
        const initial = yield* Effect.gen(function* () {
          const cache = yield* RepositoryCache.Service
          return yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })
        }).pipe(Effect.provide(cacheLayer(fixture.root)))
        expect(initial.status).toBe("cloned")
        yield* Effect.promise(() => commit(fixture.source, "two\n", "advance main"))

        yield* Effect.gen(function* () {
          const cache = yield* RepositoryCache.Service
          const kv = yield* KV.Service
          expect((yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })).status).toBe("cached")
          expect(yield* read(path.join(initial.localPath, "README.md"))).toBe("one\n")
          const yesterday = (yield* Clock.currentTimeMillis) - Duration.toMillis(Duration.days(1))
          yield* kv.set(`repository-cache:${initial.localPath}`, { attemptedAt: yesterday })
        }).pipe(Effect.provide(cacheLayer(fixture.root)))

        const results = yield* Effect.all(
          [0, 1].map(() =>
            Effect.gen(function* () {
              const cache = yield* RepositoryCache.Service
              return yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })
            }).pipe(Effect.provide(cacheLayer(fixture.root))),
          ),
          { concurrency: "unbounded" },
        )
        expect(results.map((result) => result.status).toSorted()).toEqual(["cached", "refreshed"])
        expect(yield* read(path.join(initial.localPath, "README.md"))).toBe("two\n")

        // A missing checkout must be recreated even when the persisted timestamp is recent.
        yield* Effect.promise(() => fs.rm(initial.localPath, { recursive: true }))
        yield* Effect.gen(function* () {
          const cache = yield* RepositoryCache.Service
          expect((yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })).status).toBe("cloned")
        }).pipe(Effect.provide(cacheLayer(fixture.root)))
        expect(yield* read(path.join(initial.localPath, "README.md"))).toBe("two\n")
      }),
    ),
  )

  it.live("honors legacy attempt records while allowing forced refreshes", () =>
    withRemote((fixture) =>
      Effect.gen(function* () {
        const cache = yield* RepositoryCache.Service
        const kv = yield* KV.Service
        const initial = yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })
        yield* Effect.promise(() => commit(fixture.source, "two\n", "advance main"))

        // Persisted records from older versions include an unused success timestamp.
        yield* kv.set(`repository-cache:${initial.localPath}`, {
          attemptedAt: yield* Clock.currentTimeMillis,
          refreshedAt: 0,
        })
        expect((yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })).status).toBe("cached")
        expect(yield* read(path.join(initial.localPath, "README.md"))).toBe("one\n")

        expect((yield* cache.ensure({ reference: fixture.reference, refresh: true })).status).toBe("refreshed")
        expect(yield* read(path.join(initial.localPath, "README.md"))).toBe("two\n")
        expect((yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })).status).toBe("cached")
      }).pipe(Effect.provide(cacheLayer(fixture.root))),
    ),
  )

  it.live("throttles failed refresh attempts until the next interval", () =>
    withRemote((fixture) =>
      Effect.gen(function* () {
        const cache = yield* RepositoryCache.Service
        const kv = yield* KV.Service
        const initial = yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })
        const key = `repository-cache:${initial.localPath}`
        const yesterday = (yield* Clock.currentTimeMillis) - Duration.toMillis(Duration.days(1))
        yield* kv.set(key, { attemptedAt: yesterday })
        yield* Effect.promise(() =>
          fs.rename(path.join(fixture.root, "origin.git"), path.join(fixture.root, "offline.git")),
        )

        const error = yield* Effect.flip(cache.ensure({ reference: fixture.reference, refresh: "daily" }))
        expect(error).toBeInstanceOf(RepositoryCache.FetchFailedError)
        expect((yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })).status).toBe("cached")
        expect(yield* read(path.join(initial.localPath, "README.md"))).toBe("one\n")

        yield* Effect.promise(async () => {
          await fs.rename(path.join(fixture.root, "offline.git"), path.join(fixture.root, "origin.git"))
          await commit(fixture.source, "two\n", "advance main")
        })
        yield* kv.set(key, { attemptedAt: yesterday })
        expect((yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })).status).toBe("refreshed")
        expect(yield* read(path.join(initial.localPath, "README.md"))).toBe("two\n")
      }).pipe(Effect.provide(cacheLayer(fixture.root))),
    ),
  )

  it.live("refreshes existing untracked checkouts and keeps branch freshness independent", () =>
    withRemote((fixture) =>
      Effect.gen(function* () {
        const cache = yield* RepositoryCache.Service
        const kv = yield* KV.Service
        yield* Effect.promise(() => branch(fixture.source, "feature", "feature\n"))
        const main = yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })
        const feature = yield* cache.ensure({ reference: fixture.reference, branch: "feature", refresh: "daily" })
        yield* kv.remove(`repository-cache:${feature.localPath}`)
        yield* Effect.promise(() => commit(fixture.source, "new feature\n", "advance feature"))

        expect((yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })).status).toBe("cached")
        expect(
          (yield* cache.ensure({ reference: fixture.reference, branch: "feature", refresh: "daily" })).status,
        ).toBe("refreshed")
        expect(yield* read(path.join(main.localPath, "README.md"))).toBe("one\n")
        expect(yield* read(path.join(feature.localPath, "README.md"))).toBe("new feature\n")
      }).pipe(Effect.provide(cacheLayer(fixture.root))),
    ),
  )

  it.live("replaces a stale cache directory before cloning", () =>
    withRemote((fixture) =>
      Effect.gen(function* () {
        const localPath = Repository.cachePath(path.join(fixture.root, "repos"), fixture.reference)
        yield* Effect.promise(async () => {
          await fs.mkdir(localPath, { recursive: true })
          await fs.writeFile(path.join(localPath, "stale.txt"), "stale")
        })

        const cache = yield* RepositoryCache.Service
        const result = yield* cache.ensure({ reference: fixture.reference })

        expect(result.status).toBe("cloned")
        expect(yield* exists(path.join(localPath, "stale.txt"))).toBe(false)
        expect(yield* read(path.join(localPath, "README.md"))).toBe("one\n")
      }).pipe(Effect.provide(cacheLayer(fixture.root))),
    ),
  )

  it.live("serializes concurrent materialization for the same checkout", () =>
    withRemote((fixture) =>
      Effect.gen(function* () {
        const cache = yield* RepositoryCache.Service
        const results = yield* Effect.all(
          [cache.ensure({ reference: fixture.reference }), cache.ensure({ reference: fixture.reference })],
          { concurrency: "unbounded" },
        )

        expect(results.map((result) => result.status).toSorted()).toEqual(["cached", "cloned"])
        expect(results[0].localPath).toBe(results[1].localPath)
      }).pipe(Effect.provide(cacheLayer(fixture.root))),
    ),
  )

  it.live("replaces an existing checkout whose origin does not match", () =>
    withRemote((fixture) =>
      Effect.gen(function* () {
        const cache = yield* RepositoryCache.Service
        const initial = yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })
        yield* Effect.promise(async () => {
          await git(initial.localPath, "config", "remote.origin.url", "https://github.com/other/repo.git")
          await fs.writeFile(path.join(initial.localPath, "stale.txt"), "stale")
        })

        const replaced = yield* cache.ensure({ reference: fixture.reference, refresh: "daily" })

        expect(replaced.status).toBe("cloned")
        expect(yield* exists(path.join(replaced.localPath, "stale.txt"))).toBe(false)
      }).pipe(Effect.provide(cacheLayer(fixture.root))),
    ),
  )

  it.live("keeps branch checkouts isolated from branchless refreshes", () =>
    withRemote((fixture) =>
      Effect.gen(function* () {
        yield* Effect.promise(() => branch(fixture.source, "feature", "two\n"))
        const cache = yield* RepositoryCache.Service

        const featured = yield* cache.ensure({ reference: fixture.reference, branch: "feature" })
        expect(featured.branch).toBe("feature")
        expect(featured.localPath.endsWith("repo@feature")).toBe(true)
        expect(yield* read(path.join(featured.localPath, "README.md"))).toBe("two\n")

        const refreshed = yield* cache.ensure({ reference: fixture.reference, refresh: true })
        expect(refreshed.localPath).not.toBe(featured.localPath)
        expect(yield* read(path.join(refreshed.localPath, "README.md"))).toBe("one\n")

        const cached = yield* cache.ensure({ reference: fixture.reference, branch: "feature" })
        expect(cached.status).toBe("cached")
        expect(yield* read(path.join(cached.localPath, "README.md"))).toBe("two\n")
      }).pipe(Effect.provide(cacheLayer(fixture.root))),
    ),
  )

  it.live("does not mistake an enclosing repository for the cache checkout", () =>
    withRemote((fixture) =>
      Effect.gen(function* () {
        yield* Effect.promise(() => git(fixture.root, "clone", fixture.remote, path.join(fixture.root, "repos")))

        const cache = yield* RepositoryCache.Service
        const result = yield* cache.ensure({ reference: fixture.reference })

        expect(result.status).toBe("cloned")
        expect(yield* read(path.join(result.localPath, "README.md"))).toBe("one\n")
      }).pipe(Effect.provide(cacheLayer(fixture.root))),
    ),
  )

  it.live("returns typed branch validation and clone failures", () =>
    withRemote((fixture) =>
      Effect.gen(function* () {
        const cache = yield* RepositoryCache.Service
        const invalidBranch = yield* Effect.flip(cache.ensure({ reference: fixture.reference, branch: "../unsafe" }))
        expect(invalidBranch).toBeInstanceOf(RepositoryCache.InvalidBranchError)

        const cloneFailure = yield* Effect.flip(
          cache.ensure({
            reference: { ...fixture.reference, remote: pathToFileURL(path.join(fixture.root, "missing.git")).href },
          }),
        )
        expect(cloneFailure).toBeInstanceOf(RepositoryCache.CloneFailedError)
      }).pipe(Effect.provide(cacheLayer(fixture.root))),
    ),
  )
})

function cacheLayer(root: string) {
  return AppNodeBuilder.build(LayerNode.group([RepositoryCache.node, KV.node]), [
    Global.node.replace(Global.layerWith({ state: path.join(root, "state"), repos: path.join(root, "repos") })),
    Database.node.replace(Database.configured({ path: path.join(root, "cache.sqlite") })),
  ])
}

function exists(file: string) {
  return Effect.promise(() =>
    fs.stat(file).then(
      () => true,
      () => false,
    ),
  )
}

import { describe, expect, test } from "bun:test"
import path from "path"
import { pathToFileURL } from "url"
import { Repository } from "@opencode/core/repository"

describe("Repository", () => {
  test("parses github shorthand and builds an explicit-root cache path", () => {
    const reference = Repository.parseRemote("owner/repo")

    expect(reference).toMatchObject({
      host: "github.com",
      path: "owner/repo",
      segments: ["owner", "repo"],
      owner: "owner",
      repo: "repo",
      remote: "https://github.com/owner/repo.git",
      label: "owner/repo",
    })
    expect(Repository.cachePath("/cache", reference)).toBe(path.join("/cache", "github.com", "owner", "repo"))
    expect(Repository.cachePath("/cache", reference, "main")).toBe(
      path.join("/cache", "github.com", "owner", "repo@main"),
    )
    expect(Repository.cachePath("/cache", reference, "feature/x")).toBe(
      path.join("/cache", "github.com", "owner", "repo@feature%2Fx"),
    )
    expect(Repository.cacheIdentity(reference)).toBe("github.com/owner/repo")
  })

  test("parses host path and scp remote references", () => {
    expect(Repository.parseRemote("gitlab.com/group/repo")).toMatchObject({
      host: "gitlab.com",
      path: "group/repo",
      remote: "https://gitlab.com/group/repo.git",
      label: "gitlab.com/group/repo",
    })
    expect(Repository.parseRemote("git@github.com:owner/repo.git")).toMatchObject({
      host: "github.com",
      path: "owner/repo",
      remote: "git@github.com:owner/repo.git",
      label: "owner/repo",
    })
  })

  test("caches a host with a port under a directory per host part", () => {
    expect(Repository.cachePath("/cache", Repository.parseRemote("ssh://git@example.com:2222/owner/repo"))).toBe(
      path.join("/cache", "example.com", "2222", "owner", "repo"),
    )
  })

  test("keeps local file repositories distinct from remote repositories", () => {
    const localPath = path.resolve("repo.git")
    const reference = Repository.parse(pathToFileURL(localPath).href)

    expect(reference).toMatchObject({ host: "file", protocol: "file:", label: localPath })
    expect(reference && Repository.isFile(reference)).toBe(true)
    expect(reference && Repository.isRemote(reference)).toBe(false)
    expect(() => Repository.parseRemote(pathToFileURL(localPath).href)).toThrow(
      Repository.UnsupportedLocalRepositoryError,
    )
  })

  test("rejects unsafe remote references and branches with typed errors", () => {
    expect(() => Repository.parseRemote("not-a-repo")).toThrow(Repository.InvalidReferenceError)
    expect(() => Repository.parseRemote("git@github.com:../../../etc/passwd")).toThrow(Repository.InvalidReferenceError)
    expect(() => Repository.validateBranch("feature/docs.v1")).not.toThrow()
    expect(() => Repository.validateBranch("-bad")).toThrow(Repository.InvalidBranchError)
    expect(() => Repository.validateBranch("bad..branch")).toThrow(Repository.InvalidBranchError)
    expect(() => Repository.validateBranch("bad branch")).toThrow(Repository.InvalidBranchError)
  })

  test.each([
    "..:repo",
    "git@..:repo",
    "../owner/repo",
    "ssh://../repo",
    "ssh://..:22/repo",
    "https://%2e%2e/owner/repo",
    ".:repo",
  ])("rejects %s because its host contains a relative path segment", (input) => {
    expect(() => Repository.parseRemote(input)).toThrow(Repository.InvalidReferenceError)
  })

  test("compares cache identity independent of input spelling", () => {
    const shorthand = Repository.parseRemote("owner/repo")

    expect(Repository.same(shorthand, Repository.parseRemote("https://github.com/owner/repo.git"))).toBe(true)
    expect(Repository.same(shorthand, Repository.parseRemote("github.com/owner/repo"))).toBe(true)
  })
})

import { describe, expect } from "bun:test"
import fs from "fs/promises"
import path from "path"
import { Effect } from "effect"
import { AppNodeBuilder } from "@opencode/core/effect/app-node-builder"
import { Location } from "@opencode/core/location"
import { Ripgrep } from "@opencode/core/ripgrep"
import { RelativePath } from "@opencode/core/schema"
import { tmpdir, tmpdirScoped } from "./fixture/tmpdir"
import { testEffect } from "./lib/effect"
import { tempLocationLayer } from "./fixture/location"

const it = testEffect(AppNodeBuilder.build(Ripgrep.node, [Location.node.replace(tempLocationLayer)]))

describe("Ripgrep", () => {
  for (const hidden of [undefined, false, true]) {
    for (const limit of hidden ? [10] : [1, 10]) {
      it.live(`glob honors hidden=${hidden} before limit=${limit}`, () =>
        Effect.gen(function* () {
          const tmp = yield* tmpdirScoped()
          yield* Effect.promise(() =>
            Promise.all(
              ["src/visible.ts", ".hidden.ts", "src/.hidden.ts", ".hidden/nested.ts", ".git/config.ts"].map((file) =>
                Bun.write(path.join(tmp.path, file), "needle\n"),
              ),
            ),
          )
          const ripgrep = yield* Ripgrep.Service
          const files = yield* ripgrep.glob({
            cwd: tmp.path,
            pattern: "**/*.ts",
            limit,
            ...(hidden === undefined ? {} : { hidden }),
          })

          expect(files.map((item) => item.path).sort()).toEqual(
            (hidden ? [".hidden.ts", ".hidden/nested.ts", "src/.hidden.ts", "src/visible.ts"] : ["src/visible.ts"]).map(
              (file) => RelativePath.make(file),
            ),
          )
        }),
      )
    }
  }

  it.live("globs files as an array", () =>
    Effect.acquireUseRelease(
      Effect.promise(() => tmpdir()),
      (tmp) =>
        Effect.gen(function* () {
          yield* Effect.promise(() => fs.mkdir(path.join(tmp.path, "src")))
          yield* Effect.promise(() => fs.writeFile(path.join(tmp.path, "src", "match.ts"), "needle\n"))

          const ripgrep = yield* Ripgrep.Service
          const result = yield* ripgrep.glob({ cwd: tmp.path, pattern: "**/*.ts", limit: 10 })
          expect(result.map((item) => item.path)).toEqual([RelativePath.make("src/match.ts")])
        }),
      (tmp) => Effect.promise(() => tmp[Symbol.asyncDispose]()),
    ),
  )

  it.live("greps files with include filtering", () =>
    Effect.acquireUseRelease(
      Effect.promise(() => tmpdir()),
      (tmp) =>
        Effect.gen(function* () {
          yield* Effect.promise(() => fs.mkdir(path.join(tmp.path, "src")))
          yield* Effect.promise(() => fs.writeFile(path.join(tmp.path, "src", "match.ts"), "needle\n"))
          yield* Effect.promise(() => fs.writeFile(path.join(tmp.path, "src", "skip.txt"), "needle\n"))

          const ripgrep = yield* Ripgrep.Service
          const result = yield* ripgrep.grep({
            cwd: tmp.path,
            pattern: "needle",
            include: "*.ts",
            limit: 10,
          })
          expect(result).toHaveLength(1)
          expect(result[0]?.entry.path).toBe(RelativePath.make("src/match.ts"))
          expect(result[0]?.submatches[0]?.text).toBe("needle")
        }),
      (tmp) => Effect.promise(() => tmp[Symbol.asyncDispose]()),
    ),
  )

  it.live("keeps ignored files out of catch-all find results", () =>
