                http,
                phase: "send",
                delivery: "ambiguous",
                code: "ECONNRESET",
              },
            },
          })
          if (result._tag !== "Failure") throw new Error("Expected transport failure")
          expect(result.failure.reason).toBeInstanceOf(TransportError)
