describe("Session.revert files", () => {
  it.live(
    "undoes and restores a file rename without losing either path",
    () =>
      Effect.gen(function* () {
        const tmp = yield* tmpdirScoped()
        const directory = path.join(tmp.path, "project")
        const original = path.join(directory, "old name.txt")
        const renamed = path.join(directory, "new name.txt")
        yield* Effect.promise(async () => {
          await fs.mkdir(directory)
          await Bun.write(original, "Preserve this content.\n")
          await Bun.write(path.join(directory, "unrelated.txt"), "Unrelated content.\n")
          await $`git init -q`.cwd(directory).quiet()
          await $`git -c core.fsmonitor=false add .`.cwd(directory).quiet()
        })

        const session = yield* Session.Service
        const database = yield* Database.Service
        const bus = yield* Bus.Service
        const created = yield* session.create({ location: { directory: AbsolutePath.make(directory) } })
        const prompt = yield* session.prompt({ sessionID: created.id, text: "Rename the file", resume: false })
        yield* SessionInbox.promote(database.db, bus, created.id, "steer")

        yield* Effect.gen(function* () {
          const plugins = yield* Plugin.Service
          yield* plugins.awaitActivation
          const snapshot = yield* Snapshot.Service
          const before = yield* snapshot.capture()
          if (!before) throw new Error("Initial snapshot missing")
          const assistantMessageID = SessionMessage.ID.create()
          yield* bus.publish(SessionEvent.Step.Started, {
            sessionID: created.id,
            assistantMessageID,
            agent: Agent.defaultID,
            model: { id: Model.ID.make("test-model"), providerID: Provider.ID.make("test-provider") },
            snapshot: before,
            started: 0,
          })
          yield* Effect.promise(() => fs.rename(original, renamed))
          const after = yield* snapshot.capture()
          if (!after) throw new Error("Renamed snapshot missing")
          yield* bus.publish(SessionEvent.Step.Ended, {
            sessionID: created.id,
            assistantMessageID,
            finish: "stop",
            cost: Money.USD.zero,
            tokens: { input: 0, output: 0, reasoning: 0, cache: { read: 0, write: 0 } },
            snapshot: after,
            files: yield* snapshot.files({ from: before, to: after }),
          })

          yield* Effect.promise(() => Bun.write(path.join(directory, "unrelated.txt"), "Keep this later edit.\n"))
          const reverted = yield* session.revert.stage({ sessionID: created.id, messageID: prompt.id })
          expect({
            original: yield* Effect.promise(() => Bun.file(original).exists()),
            renamed: yield* Effect.promise(() => Bun.file(renamed).exists()),
          }).toEqual({ original: true, renamed: false })
          expect(yield* Effect.promise(() => Bun.file(original).text())).toBe("Preserve this content.\n")
          expect(reverted.files?.map((file) => [file.file, file.status])).toEqual([
            ["new name.txt", "deleted"],
            ["old name.txt", "added"],
          ])
          expect(yield* Effect.promise(() => Bun.file(path.join(directory, "unrelated.txt")).text())).toBe(
            "Keep this later edit.\n",
          )

          yield* session.revert.clear(created.id)
          expect(yield* Effect.promise(() => Bun.file(original).exists())).toBe(false)
          expect(yield* Effect.promise(() => Bun.file(renamed).text())).toBe("Preserve this content.\n")
          expect(yield* Effect.promise(() => Bun.file(path.join(directory, "unrelated.txt")).text())).toBe(
            "Keep this later edit.\n",
          )
          expect((yield* session.get(created.id)).revert).toBeUndefined()
        }).pipe(Effect.provide(LocationServiceMap.Service.get(created.location)))
      }),
    // Real Location/plugin startup and Git snapshots can exceed five seconds under CI load.
    { timeout: 15_000 },
  )
})

import { describe, expect } from "bun:test"
import { Cause, Deferred, Effect, Exit, Fiber, Layer } from "effect"
import { SessionInbox } from "@opencode/core/session/inbox"
import { SessionRunCoordinator } from "@opencode/core/session/run-coordinator"
import { testEffect } from "./lib/effect"

const it = testEffect(Layer.empty)

describe("SessionRunCoordinator", () => {
  it.effect("joins concurrent resumes for one key", () =>
    Effect.gen(function* () {
      const gate = yield* Deferred.make<void>()
      let runs = 0
      const coordinator = yield* SessionRunCoordinator.make({
        drain: () => Effect.sync(() => runs++).pipe(Effect.andThen(Deferred.await(gate))),
      })

      const first = yield* coordinator.run("session").pipe(Effect.forkChild)
      yield* Effect.yieldNow
      const second = yield* coordinator.run("session").pipe(Effect.forkChild)
      yield* Effect.yieldNow

      expect(runs).toBe(1)
      yield* Deferred.succeed(gate, undefined)
      yield* Effect.all([Fiber.join(first), Fiber.join(second)])
      expect(runs).toBe(1)
    }),
  )

  it.effect("joins a wake-started execution without forcing a successor", () =>
    Effect.gen(function* () {
      const started = yield* Deferred.make<void>()
      const gate = yield* Deferred.make<void>()
      const forces: boolean[] = []
      const coordinator = yield* SessionRunCoordinator.make<string, never>({
        drain: (_key, force) =>
          Effect.sync(() => forces.push(force)).pipe(
            Effect.andThen(Deferred.succeed(started, undefined)),
            Effect.andThen(Deferred.await(gate)),
          ),
      })

      yield* coordinator.wake("session")
      yield* Deferred.await(started)
      const resumed = yield* coordinator.run("session").pipe(Effect.forkChild)
      yield* Effect.yieldNow
      yield* Deferred.succeed(gate, undefined)
      yield* Fiber.join(resumed)

      expect(forces).toEqual([false])
    }),
  )

  it.effect("starts execution when woken while idle", () =>
    Effect.gen(function* () {
      const drained = yield* Deferred.make<void>()
      const coordinator = yield* SessionRunCoordinator.make({ drain: () => Deferred.succeed(drained, undefined) })

      yield* coordinator.wake("session")
      yield* Deferred.await(drained)
    }),
  )

  it.effect("snapshots only active executions", () =>
    Effect.gen(function* () {
      const firstStarted = yield* Deferred.make<void>()
      const secondStarted = yield* Deferred.make<void>()
      const firstGate = yield* Deferred.make<void>()
      const secondGate = yield* Deferred.make<void>()
      const coordinator = yield* SessionRunCoordinator.make({
        drain: (key: string) =>
          Deferred.succeed(key === "first" ? firstStarted : secondStarted, undefined).pipe(
            Effect.andThen(Deferred.await(key === "first" ? firstGate : secondGate)),
          ),
      })
      const firstActive = coordinator.isActive("first")

      expect(Array.from(yield* coordinator.active)).toEqual([])
      expect(yield* firstActive).toBe(false)
      const first = yield* coordinator.run("first").pipe(Effect.forkChild)
      yield* Deferred.await(firstStarted)
      expect(Array.from(yield* coordinator.active)).toEqual(["first"])
      expect(yield* firstActive).toBe(true)
      expect(yield* coordinator.isActive("second")).toBe(false)

      const second = yield* coordinator.run("second").pipe(Effect.forkChild)
      yield* Deferred.await(secondStarted)
      expect(Array.from(yield* coordinator.active)).toEqual(["first", "second"])
      expect(yield* coordinator.isActive("second")).toBe(true)

      yield* Deferred.succeed(firstGate, undefined)
      yield* Fiber.join(first)
      expect(Array.from(yield* coordinator.active)).toEqual(["second"])
      expect(yield* firstActive).toBe(false)
      expect(yield* coordinator.isActive("second")).toBe(true)
      yield* Deferred.succeed(secondGate, undefined)
      yield* Fiber.join(second)
      expect(Array.from(yield* coordinator.active)).toEqual([])
      expect(yield* coordinator.isActive("second")).toBe(false)
    }),
  )

  it.effect("cleans active executions after failure and defect", () =>
    Effect.gen(function* () {
      const failure = new Error("failed")
      const defect = new Error("defect")
      const settled: Exit.Exit<void, Error>[] = []
      const coordinator = yield* SessionRunCoordinator.make({
        drain: (key: string) => (key === "failure" ? Effect.fail(failure) : Effect.die(defect)),
        settled: (_key, exit) => Effect.sync(() => void settled.push(exit)),
      })

      const failed = yield* coordinator.run("failure").pipe(Effect.exit)
      expect(Exit.isFailure(failed) && Cause.hasFails(failed.cause)).toBeTrue()
      expect(Array.from(yield* coordinator.active)).toEqual([])
      expect(yield* coordinator.isActive("failure")).toBe(false)

      const died = yield* coordinator.run("defect").pipe(Effect.exit)
      expect(Exit.isFailure(died) && Cause.hasDies(died.cause)).toBeTrue()
      expect(Array.from(yield* coordinator.active)).toEqual([])
      expect(yield* coordinator.isActive("defect")).toBe(false)
      expect(settled).toHaveLength(2)
    }),
  )

  it.effect("preserves settlement hook defects while releasing ownership", () =>
    Effect.gen(function* () {
