import { describe, expect, test } from "bun:test"
import { Effect } from "effect"
import { ShellParse } from "../../src/shell/parse.js"
import { ShellScan } from "../../src/shell/scan.js"

const conditions = ["[[ -n <(scan_probe) ]]", "[[ -n >(scan_probe) ]]"]
const contexts = [
  (source: string) => source,
  (source: string) => `( ${source} )`,
  (source: string) => `{ ${source}; }`,
  (source: string) => `if ${source}; then printf visible; fi`,
  (source: string) => `check() { ${source}; }; check`,
  (source: string) => `printf '%s' "$( ${source}; printf visible)"`,
]

const functions = ["probe", "probe-name", "probe.name", "probe:name"].flatMap((name) =>
  [`${name}()`, `function ${name}`, `function ${name}()`].flatMap((head) =>
    [
      "{ scan_probe; }",
      "(scan_probe)",
      "if true; then scan_probe; fi",
      "[[ $(scan_probe) == ok ]]",
      "(( 1 + $(scan_probe) ))",
    ].map((body) => `${head} ${body}; ${name}`),
  ),
)

describe("legacy-accepted shell syntax regressions", () => {
  test.each(["() { scan_probe; }", "probe() { scan_probe; }; probe"])(
    "preserves deeply indented function definitions: %s",
    async (source) => {
      const command = `( ${" ".repeat(32_000)}${source} )`
      const legacy = await Effect.runPromise(ShellParse.scan(command, "zsh", "/workspace"))
      expect(await Effect.runPromise(ShellParse.scanPortable(command, "zsh", "/workspace"))).toEqual(legacy)
    },
  )

  test.each(conditions.flatMap((source) => contexts.map((context) => context(source))))(
    "retains conditional process substitutions and permission resources: %s",
    async (source) => {
      const legacy = await Effect.runPromise(ShellParse.scan(source, "bash", "/workspace"))
      expect(legacy.commands.some((command) => command.resource === "scan_probe")).toBe(true)
      expect(await Effect.runPromise(ShellParse.scanPortable(source, "bash", "/workspace"))).toEqual(legacy)
    },
  )

  for (const shell of ["bash", "zsh"]) {
    test.each(
      ["probe()", "probe \\\n()", "function \\\nprobe()", "function probe \\\n()"].flatMap((head) =>
        [" \\\n", " \\\n # ignored ) }\n", "# ignored \\\n"].flatMap((gap) =>
          contexts.map((context) => context(`${head}${gap}{ scan_probe; }; probe`)),
        ),
      ),
    )(`${shell} preserves line continuations at function boundaries: %s`, async (source) => {
      const legacy = await Effect.runPromise(ShellParse.scan(source, shell, "/workspace"))
      expect(legacy.commands.some((command) => command.resource === "scan_probe")).toBe(true)
      expect(await Effect.runPromise(ShellParse.scanPortable(source, shell, "/workspace"))).toEqual(legacy)
    })

    test.each(
      ["probe()", "function probe", "function probe()"].flatMap((head) =>
        [" # ignored ) }\n", "\n# ignored ) }\n\n", " # first\n# second\n"].flatMap((gap) =>
          contexts.map((context) => context(`${head}${gap}{ scan_probe; }; probe`)),
        ),
      ),
    )(`${shell} preserves comments between a function head and its body: %s`, async (source) => {
      const legacy = await Effect.runPromise(ShellParse.scan(source, shell, "/workspace"))
      expect(legacy.commands.some((command) => command.resource === "scan_probe")).toBe(true)
      expect(await Effect.runPromise(ShellParse.scanPortable(source, shell, "/workspace"))).toEqual(legacy)
    })

    test.each(functions)(
      `${shell} preserves function resources, saved prefixes, and directories: %s`,
      async (source) => {
        const legacy = await Effect.runPromise(ShellParse.scan(source, shell, "/workspace"))
        expect(legacy.commands.some((command) => command.resource === "scan_probe")).toBe(true)
        expect(await Effect.runPromise(ShellParse.scanPortable(source, shell, "/workspace"))).toEqual(legacy)
      },
    )

    const executable = Bun.which(shell)
    test
      .skipIf(!executable)
      .each([
        "probe-name() { scan_probe; }; probe-name",
        "function probe.name { scan_probe; }; probe.name",
        "probe:name() if true; then scan_probe; fi; probe:name",
        "probe()# ignored ) }\n{ scan_probe; }; probe",
        "probe \\\n() \\\n{ scan_probe; }; probe",
        "function \\\nprobe() # ignored \\\n{ scan_probe; }; probe",
        ...(shell === "bash" ? conditions : ["() { scan_probe; }"]),
      ])(`${shell} really executes the extracted command: %s`, (source) => {
      if (!executable) throw new Error(`${shell} is unavailable`)
      const execution = Bun.spawnSync(
        [
          executable,
          ...(shell === "bash" ? ["--noprofile", "--norc"] : ["-f"]),
          "-c",
          `scan_probe() { printf 'executed\\n' >&2; }; ${source}; wait`,
        ],
        { env: { PATH: "/usr/bin:/bin", LC_ALL: "C" } },
      )
      expect(execution.exitCode).toBe(0)
      expect(execution.stderr.toString()).toBe("executed\n")
      const result = ShellScan.scan(source)
      expect(result.kind).toBe("scanned")
      if (result.kind !== "scanned") throw new Error(result.reason)
      expect(result.commands.map((command) => command.words[0])).toContain("scan_probe")
    })
  }

  test.each([
    "() { scan_probe; }",
    "( () { scan_probe; } )",
    "{ () { scan_probe; }; }",
    "while() { scan_probe; break; }",
    "until() { scan_probe; break; }",
  ])("preserves Zsh anonymous functions and parenthesized loop permissions: %s", async (source) => {
    const legacy = await Effect.runPromise(ShellParse.scan(source, "zsh", "/workspace"))
    expect(legacy.commands.some((command) => command.resource === "scan_probe")).toBe(true)
    expect(await Effect.runPromise(ShellParse.scanPortable(source, "zsh", "/workspace"))).toEqual(legacy)
  })

  // Tree-sitter recovers these valid Zsh forms with synthetic commands or truncated outer resources.
  // Pin both results rather than treating recovery artifacts as executable shell syntax.
  test.each([
    {
      source: "if () { scan_probe; }; then printf visible; fi",
      legacy: ["scan_probe", "then printf visible", "fi"],
      portable: ["scan_probe", "printf visible"],
    },
    {
      source: "check() { () { scan_probe; }; }; check",
      legacy: ["scan_probe", "}", "check"],
      portable: ["scan_probe", "check"],
    },
    {
      source: "printf '%s' \"$( () { scan_probe; }; printf visible)\"",
      legacy: ["printf '%s'", "scan_probe", "printf visible"],
      portable: ["printf '%s' \"$( () { scan_probe; }; printf visible)\"", "scan_probe", "printf visible"],
    },
  ])("accepts anonymous-function compositions despite legacy recovery artifacts: $source", async (fixture) => {
    const legacy = await Effect.runPromise(ShellParse.scan(fixture.source, "zsh", "/workspace"))
    const portable = await Effect.runPromise(ShellParse.scanPortable(fixture.source, "zsh", "/workspace"))
    expect(legacy.commands.map((command) => command.resource)).toEqual([...fixture.legacy])
    expect(portable.commands.map((command) => command.resource)).toEqual([...fixture.portable])
  })

  test.each([
    "[[ -n '<(scan_ignored)' ]]",
    '[[ -n "<(scan_ignored)" ]]',
    "[[ -n '>(scan_ignored)' ]]",
    '[[ -n ">(scan_ignored)" ]]',
    "[[ -n $'<(scan_ignored)' ]]",
  ])("does not turn quoted process-substitution text into commands: %s", (source) => {
    expect(ShellScan.scan(source)).toEqual({ kind: "scanned", commands: [] })
  })
})

import { describe, expect, test } from "bun:test"
import { ShellScan } from "../../src/shell/scan.js"

describe("PowerShell scanner safety", () => {
  test("backticks in single quotes cannot hide subsequent executions", () => {
    const result = ShellScan.scanPowerShell("Write-Output '`'; Remove-Item victim; Write-Output '`'")
    expect(result.kind).toBe("scanned")
    if (result.kind === "opaque") return
    expect(result.commands.map((command) => command.words)).toEqual([
      ["Write-Output", "`"],
      ["Remove-Item", "victim"],
      ["Write-Output", "`"],
    ])
  })

  test.each([" ", "\t", "\v", "\f", "\u00a0", "\u2000", "\u2028", "\u2029", "\n", "\r", "\r\n"])(
    "recognizes comments after escaped whitespace at a token boundary %j",
    (space) => {
      expect(ShellScan.scanPowerShell(`Write-Output \`${space}#'\nRemove-Item victim\n#'`)).toMatchObject({
        kind: "scanned",
        commands: [{ words: ["Write-Output"] }, { words: ["Remove-Item", "victim"] }],
      })
      for (const redirect of ["2>&1", "6>&1", "*>&1"]) {
        expect(
          ShellScan.scanPowerShell(`% { Write-Output ${redirect}\`${space}#} '\nRemove-Item victim\n} #'`),
        ).toMatchObject({
          kind: "scanned",
          commands: [
            { words: ["%", expect.any(String)] },
            { words: ["Write-Output"] },
            { words: ["Remove-Item", "victim"] },
          ],
        })
      }
    },
  )

  test.each([" ", "\t", "\v", "\f", "\u00a0", "\u2000", "\u2028", "\u2029"])(
    "keeps backtick whitespace inside strings literal: %j",
    (space) => {
      const result = ShellScan.scanPowerShell(`% { Write-Output '\`${space}#literal' "\`${space}#literal" }`)
      expect(result.kind).toBe("scanned")
      if (result.kind === "opaque") return
      expect(result.commands[1]?.words).toEqual(["Write-Output", `\`${space}#literal`, `${space}#literal`])
    },
  )

  test.each(["x2>&1", "x6>&1"])("keeps embedded greater-than text distinct from redirects: %s", (token) => {
    expect(ShellScan.scanPowerShell(`Write-Output ${token}#'\nRemove-Item victim\n#'`)).toMatchObject({
      kind: "scanned",
      commands: [
        { resource: `Write-Output ${token.slice(0, 3)}`, words: ["Write-Output", token.slice(0, 3)] },
        { words: ["Remove-Item", "victim"] },
      ],
    })
  })

  test.each([
    "1",
    ",1",
    "+1",
    "-1",
    ".1",
    "0x1",
    "0b1",
    "1L",
    "1kb",
    "1.0",
    "1+1",
    "1..2",
    "-not 1",
    "'x' -eq 1",
    '"x" -eq 1',
    "{} -eq 1",
  ])("recognizes expression-mode comments without inventing command heads: %s", (expression) => {
    expect(ShellScan.scanPowerShell(`${expression}#'\nRemove-Item victim\n#'`)).toMatchObject({
      kind: "scanned",
      commands: [{ words: ["Remove-Item", "victim"] }],
    })
    expect(ShellScan.scanPowerShell(`% { ${expression}#} '\nRemove-Item victim\n} #'`)).toMatchObject({
      kind: "scanned",
      commands: [{ words: ["%", expect.any(String)] }, { words: ["Remove-Item", "victim"] }],
    })
  })

  test.each(["\n", "\r", "\r\n"])("ends nested block comments at %j", (newline) => {
    const result = ShellScan.scanPowerShell(`ForEach-Object { # } ignored${newline}Remove-Item victim }`)
    expect(result.kind).toBe("scanned")
    if (result.kind === "opaque") return
    expect(result.commands.map((command) => command.words[0])).toEqual(["ForEach-Object", "Remove-Item"])
  })

  test.each([
    'ForEach-Object { Write-Output "it\'s } literal"; Remove-Item victim }',
    'ForEach-Object { Write-Output "a\'b{c}"; Remove-Item victim }',
    "ForEach-Object { Write-Output '`'; Remove-Item victim }",
    'ForEach-Object { Write-Output "a`\"}b"; Remove-Item victim }',
    'ForEach-Object { Write-Output "a""}b"; Remove-Item victim }',
  ])("keeps block delimiters inside strings: %s", (input) => {
    const result = ShellScan.scanPowerShell(input)
    expect(result.kind).toBe("scanned")
    if (result.kind === "opaque") return
    expect(result.commands.map((command) => command.words[0])).toEqual([
      "ForEach-Object",
      "Write-Output",
      "Remove-Item",
    ])
  })

  test("preserves doubled double quotes in argument values", () => {
    const result = ShellScan.scanPowerShell('Write-Output "a""b"')
    expect(result).toMatchObject({
      kind: "scanned",
      commands: [{ resource: 'Write-Output "a""b"', words: ["Write-Output", 'a"b'] }],
    })
  })

  test.each(["'safe'", '"safe"', "{ Get-Item x }"])(
    "recognizes comments after complete literal tokens: %s",
    (argument) => {
      const result = ShellScan.scanPowerShell(`Write-Output ${argument}# '\nRemove-Item victim\n# '`)
      expect(result.kind).toBe("scanned")
      if (result.kind === "opaque") return
      expect(result.commands.some((command) => command.words[0] === "Remove-Item")).toBe(true)
      expect(result.commands[0]?.resource).toBe(`Write-Output ${argument}`)
    },
  )

  test("keeps generic-token quotes distinct from standalone strings", () => {
    expect(ShellScan.scanPowerShell("Write-Output pre'safe'#literal; Get-Item x")).toMatchObject({
      kind: "scanned",
      commands: [
        { resource: "Write-Output pre'safe'#literal", words: ["Write-Output", "presafe#literal"] },
        { resource: "Get-Item x", words: ["Get-Item", "x"] },
      ],
    })
    expect(ShellScan.scanPowerShell("Write-Output 'safe'tail")).toMatchObject({
      kind: "scanned",
      commands: [{ resource: "Write-Output 'safe'tail", words: ["Write-Output", "safe", "tail"] }],
    })
  })

  test("block matching agrees with tokenization after a merging redirect", () => {
    const result = ShellScan.scanPowerShell("% { Get-Item x 2>&1# } '\nRemove-Item victim\n} # '")
    expect(result.kind).toBe("scanned")
    if (result.kind === "opaque") return
    expect(result.commands.map((command) => command.words[0])).toEqual(["%", "Get-Item", "Remove-Item"])
  })

  test.each([
    'cmd.exe \u0085--% "ignored\nRemove-Item victim\n# "',
    "Write-Output \u2018a'; Remove-Item victim; Write-Output 'b\u2019",
    'Write-Output \u201ca"; Remove-Item victim; Write-Output "b\u201d',
  ])("refuses unsupported lexical modes: %s", (input) => {
    expect(ShellScan.scanPowerShell(input).kind).toBe("opaque")
  })

  test.each(["\n", "\r", "\r\n"])("ends stop-parsing at %j even adjacent to completed tokens", (newline) => {
    for (const argument of ["'x'", '"x"', "{}"]) {
      const result = ShellScan.scanPowerShell(`Write-Output ${argument}--% '${newline}Remove-Item victim${newline}# '`)
      expect(result).toMatchObject({
        kind: "scanned",
        commands: [{ words: ["Write-Output", expect.any(String), "--%", "'"] }, { words: ["Remove-Item", "victim"] }],
      })
      const block = ShellScan.scanPowerShell(
        `% { Write-Output ${argument}--%} '${newline}Remove-Item victim${newline}} # '`,
      )
      expect(block.kind).toBe("scanned")
      if (block.kind === "scanned") expect(block.commands.at(-1)?.words).toEqual(["Remove-Item", "victim"])
    }
  })

  test.each([
    "& '' victim",
    "Write-Output ok > > out",
    "Write-Output ok > 2>&1",
    "Write-Output ok 2>&",
    "Write-Output ok 2>&2",
    "Write-Output ok 1>&1",
    "Write-Output ok >&1",
    "Write-Output ok 7> out",
    "Write-Output ok 2>>&1",
    "Write-Output ok > # missing target\nRemove-Item victim",
    "Write-Output ok | # missing pipeline\n",
    "| Remove-Item victim",
    "&& Remove-Item victim",
    "& & Remove-Item victim",
