  it.live("passes location scope and bounded diff options to providers", () =>
    withTmp((directory) =>
      Effect.gen(function* () {
        const observed: VcsDiffInput[] = []
        const vcs = yield* Vcs.Service
        yield* vcs.transform((editor) => {
