  it.live("validates provider results and bounds oversized patches", () =>
    withTmp((directory) =>
      Effect.gen(function* () {
        const vcs = yield* Vcs.Service
        yield* vcs.transform((editor) => {
          editor.add(
            provider({
              status: () => Effect.succeed([{ file: "file.txt", additions: -1, deletions: 0, status: "added" }]),
              diff: () =>
