import { TextWriter, Uint8ArrayReader, Uint8ArrayWriter, ZipReader } from "@zip.js/zip.js"
import { ExtensionError } from "./error"
import { archivePath, decodeManifest } from "./manifest"
import { mainImportAllowed } from "./module"

export const archiveLimit = 104_857_600

const entryLimit = 4_096

/** Reads and validates an extension archive before anything replaces a working installation. */
export async function readArchive(data: Uint8Array) {
  if (data.byteLength > archiveLimit) throw new ExtensionError("tooLarge")

  if (data[0] !== 0x50 || data[1] !== 0x4b) throw new ExtensionError("invalidArchive")

  // zip.js expects slice() to copy; Node Buffer.slice() returns a view instead.
  const reader = new ZipReader(new Uint8ArrayReader(Buffer.isBuffer(data) ? new Uint8Array(data) : data), {
    useWebWorkers: false,
  })

  return read(reader)
    .catch((error: unknown) => {
      if (error instanceof ExtensionError) throw error
      throw new ExtensionError("invalidArchive", { cause: error })
    })
    .finally(() => reader.close())
}

async function read(reader: ZipReader<Uint8Array>) {
  const entries = await reader.getEntries()

  if (entries.length > entryLimit || entries.reduce((total, entry) => total + entry.uncompressedSize, 0) > archiveLimit)
    throw new ExtensionError("tooLarge")

  const paths = entries.map((entry) =>
    archivePath(entry.directory ? entry.filename.replace(/\/$/, "") : entry.filename),
  )

  if (new Set(paths).size !== paths.length) throw new ExtensionError("invalidPath")
  const metadata = entries.find((entry) => entry.filename === "manifest.json" && !entry.directory)

  if (!metadata?.getData || metadata.uncompressedSize > 65_536) throw new ExtensionError("invalidManifest")
  const decoded = decodeManifest(await metadata.getData(new TextWriter()))

  if (decoded._tag === "None") throw new ExtensionError("invalidManifest")
  const manifest = decoded.value
  const entrypoints = [manifest.renderer, manifest.main, manifest.style].filter((path) => path !== undefined)
  entrypoints.forEach(archivePath)

  if (!(manifest.imports.main ?? []).every(mainImportAllowed)) throw new ExtensionError("invalidModule")

  const files = await Promise.all(
    entries
      .filter((entry) => !entry.directory)
      .map(async (entry) => {
        if (!entry.getData) throw new ExtensionError("invalidArchive")

        return { path: entry.filename, data: Buffer.from(await entry.getData(new Uint8ArrayWriter())) }
      }),
  )

  if (files.reduce((total, file) => total + file.data.byteLength, 0) > archiveLimit)
    throw new ExtensionError("tooLarge")

  if (!entrypoints.every((path) => files.some((file) => file.path === path)))
    throw new ExtensionError("invalidManifest")

  // Reject syntax errors before replacing a working installation; evaluation happens in the hosts.
  const broken = [manifest.renderer, manifest.main]
    .flatMap((path) => files.filter((file) => file.path === path))
    .find((file) => !compiles(file.data.toString("utf8")))

  if (broken) throw new ExtensionError("invalidModule", { message: broken.path })

  return { manifest, files }
}

function compiles(source: string) {
  // Compiling is the only syntax check the runtime offers, and it reports failure by throwing.
  try {
    new Function("require", "module", "exports", source)

    return true
  } catch {
    return false
  }
}

import { randomUUID } from "node:crypto"
import { ImageView, screen, type BrowserWindow, type WebContentsView } from "electron"
import type { BridgeLayout } from "@opencode/gui-extensions/sdk/bridge"
import type { Embed } from "@opencode/gui-extensions/sdk/main"
import { createCornerImages } from "../native/corners"
import type { Instance } from "./lifecycle"

type Entry = {
  /** The extension instance that created the embed. */
  readonly owner: Instance
  readonly window: BrowserWindow
  readonly windowID: number
  readonly view: WebContentsView
  readonly corners: readonly ImageView[]
  cornerKey: string
  layout?: BridgeLayout
  shown: boolean
  /** Whether the view was on screen after the last apply. */
  onscreen: boolean
  readonly listeners: Set<(visible: boolean) => void>
}

// A box edge this many CSS px from the window edge follows it while the renderer's layout catches up.
const WINDOW_GUTTER = 24

/**
 * The web pages main extensions hand to the host. Each stays hidden until its window's renderer lays
 * it out and the extension shows it; the renderer's bounds already include the window zoom.
 */
export function createEmbeds() {
  const entries = new Map<string, Entry>()
  const resizing = new WeakSet<BrowserWindow>()

  const apply = (entry: Entry) => {
    if (entry.window.isDestroyed()) return
    const layout = entry.layout?.bounds
    const viewport = entry.layout?.viewport
    // The renderer measures a frame or more behind a window resize. Edges beside the window
    // edge follow it now, so the view and its corner masks do not trail inside the panel.
    // This assumes the box takes the whole change, as the side panel beside the fixed-width chat does.
    const [width = 0, height = 0] = entry.window.getContentSize()
    const zoom = entry.window.webContents.getZoomFactor()

    // The renderer's viewport is whole CSS px, so it can be off by one CSS px plus rounding; that is not a resize.
    const follow = (inset: number, change: number) =>
      inset <= WINDOW_GUTTER * zoom && Math.abs(change) >= zoom + 1 ? change : 0

    const dx = layout && viewport ? follow(viewport.width - layout.x - layout.width, width - viewport.width) : 0
    const dy = layout && viewport ? follow(viewport.height - layout.y - layout.height, height - viewport.height) : 0

    // Renderer measurements are fractional; native views take whole DIPs.
    const bounds = layout && {
      x: Math.round(layout.x),
      y: Math.round(layout.y),
      width: Math.round(layout.width + dx),
      height: Math.round(layout.height + dy),
    }

    const placed = !!entry.layout?.visible && !!bounds && bounds.width > 0 && bounds.height > 0

    if (placed && bounds) {
      entry.view.setBounds(bounds)

      const size = Math.min(
        Math.round(entry.layout?.radius ?? 0),
        Math.floor(bounds.width / 2),
        Math.floor(bounds.height / 2),
      )

      const background = entry.layout?.background
      const border = entry.layout?.border
      const scale = screen.getDisplayMatching(entry.window.getBounds()).scaleFactor

      const key =
        background && size > 0 ? `${background}:${size}:${scale}:${border?.color ?? ""}:${border?.width ?? ""}` : ""

      if (background && key && key !== entry.cornerKey)
        createCornerImages(background, size, scale, border).forEach((image, index) =>
          entry.corners[index]?.setImage(image),
        )
      entry.cornerKey = key
      // Plain bounds apply in the same frame as the view's; animated ones land a frame later,
      // which exposes a square page corner whenever the panel moves.
      entry.corners.forEach((corner, index) =>
        corner.setBounds({
          x: bounds.x + (index ? bounds.width - size : 0),
          y: bounds.y + bounds.height - size,
          width: size,
          height: size,
        }),
      )
    }

    // Keep the corner layers up while the box is laid out, even before the page shows.
    // Over the DOM card they match its own rounded corners.
    const visible = placed && entry.shown
    entry.corners.forEach((corner) => corner.setVisible(placed && !!entry.cornerKey))
    entry.view.setVisible(visible)

    if (visible === entry.onscreen) return
    entry.onscreen = visible
    entry.listeners.forEach((listener) => listener(visible))
  }

  const release = (id: string) => {
    const entry = entries.get(id)

    if (!entry) return
    entries.delete(id)
    entry.listeners.clear()

    if (entry.window.isDestroyed()) return
    entry.view.setVisible(false)
    entry.corners.forEach((corner) => entry.window.contentView.removeChildView(corner))
    entry.window.contentView.removeChildView(entry.view)
  }

  const owned = (windowID: number, id: string) => {
    const entry = entries.get(id)

    return entry?.windowID === windowID ? entry : undefined
  }

  return {
    create(owner: Instance, view: WebContentsView, window: BrowserWindow): Embed {
      const id = randomUUID()

      if (!resizing.has(window)) {
        resizing.add(window)
        window.on("resize", () => entries.forEach((entry) => entry.window === window && apply(entry)))
      }

      const corners = [new ImageView(), new ImageView()]
      view.setVisible(false)
      window.contentView.addChildView(view)
      corners.forEach((corner) => {
        // Painting above a WebContentsView needs a composited layer; a zero blur creates one
        // without an animated bounds update.
        corner.setBackgroundBlur(0)
        corner.setVisible(false)
        window.contentView.addChildView(corner)
      })

      const entry: Entry = {
        owner,
        window,
        windowID: window.id,
        view,
        corners,
        cornerKey: "",
        shown: false,
        onscreen: false,
        listeners: new Set(),
      }

      entries.set(id, entry)

      return {
        id,
        show(visible) {
          entry.shown = visible

          if (entries.get(id) === entry) apply(entry)
        },
        on(_event, handler) {
          entry.listeners.add(handler)

          return () => {
            entry.listeners.delete(handler)
          }
        },
        capture: () => capture(entry),
        dispose: () => release(id),
      }
    },
    layout(windowID: number, id: string, layout?: BridgeLayout) {
      const entry = owned(windowID, id)

      if (!entry) return
      entry.layout = layout
      apply(entry)
    },
    capture(windowID: number, id: string) {
      const entry = owned(windowID, id)

      return entry ? capture(entry) : Promise.resolve(undefined)
    },
    /** The window's renderer is reloading; it lays its embeds out again once it is back. */
    reset(windowID: number) {
      entries.forEach((entry) => {
        if (entry.windowID !== windowID) return
        entry.layout = undefined
        apply(entry)
      })
    },
    releaseWindow(windowID: number) {
      entries.forEach((entry, id) => {
        if (entry.windowID === windowID) release(id)
      })
    },
    /** Releases one extension instance's embeds; a replacement of the same extension keeps its own. */
    releaseOwner(owner: Instance) {
      entries.forEach((entry, id) => {
        if (entry.owner === owner) release(id)
      })
    },
  }
}

// Freezes the shown page so the renderer can paint it under DOM overlays while the view hides.
async function capture(entry: Entry) {
  if (entry.window.isDestroyed() || entry.view.webContents.isDestroyed() || !entry.view.getVisible()) return
  const image = await entry.view.webContents.capturePage()

  return image.isEmpty() ? undefined : image
}

import type { DatabaseSync } from "node:sqlite"
import type { EnableState } from "@opencode/gui-extensions/sdk/bridge"

/** Explicit settings only: both startup readers and the manager resolve absent rows through the same SDK rule. */
export function readEnableState(db: DatabaseSync): readonly EnableState[] {
  return db.prepare("SELECT id, enabled FROM extension").all().map((row) => {
    // SAFETY: extension.id is TEXT PRIMARY KEY; extension.enabled is INTEGER NOT NULL in every journaled schema.
    const id = row.id as string

    return { id, enabled: row.enabled === 1 }
  })
}

import type { ExtensionErrorCode, ExtensionFailure } from "../../shared/ipc-rpc/extensions"

/** A failure the renderer maps to its own copy by `code`. */
export class ExtensionError extends Error {
  constructor(
    readonly code: ExtensionErrorCode,
    options?: ErrorOptions & { readonly message?: string },
  ) {
    super(options?.message ?? code, options)
  }
}

export function extensionFailure(error: unknown): ExtensionFailure {
  if (error instanceof ExtensionError) return { code: error.code, message: error.message }

  return { code: "failed", message: error instanceof Error ? error.message : String(error) }
}

import { app, BrowserWindow } from "electron"
import { builtins } from "@opencode/gui-extensions/main"
import type { BridgeLayout, BridgeMenubarItem } from "@opencode/gui-extensions/sdk/bridge"
import {
  MenubarItem,
  type BaseContext,
  type Build,
  type Caller,
  type Catalog,
  type Cleanup,
  type Cli,
  type Definition,
  type Embeds,
  type Ipc,
  type IpcImpl,
  type IpcProvider,
  type IpcSpec,
  type Lifecycle,
  type Log,
  type MainContext,
  type MainSetup,
  type Messages,
  type OS,
  type Params,
  type Registry,
  type ServerEndpoint,
  type ServerEndpoints,
  type Windows,
} from "@opencode/gui-extensions/sdk/main"
import { Exit, Match, Predicate, Schema } from "effect"
import type { ExtensionEndpoint, ExtensionInstalled } from "../../shared/ipc-rpc/extensions"
import {
  ExtensionAvailable,
  ExtensionEvent,
  ExtensionMenubarItemsChanged,
  ExtensionState,
  ExtensionsChanged,
  type DesktopEvent,
} from "../../shared/ipc-rpc/events"
import { CHANNEL, VERSION } from "../constants"
import { emitIpcEvent } from "../ipc-events"
import { refreshMenu, setMenubarProvider } from "../native/menu"
import {
  formatNativeTemplate,
  nativeLocale,
  nativeMessage,
  nativePluralCategory,
  onNativeTranslations,
} from "../native/translations"
import { SidecarCredentials } from "../service/sidecar-credentials"
import type { Database } from "../storage/database"
import type { StateStore } from "../storage/state"
import { getLastFocusedWindow, getMainWindows, onMainWindow } from "../windows"
import { ExtensionError } from "./error"
import { createLifecycle, type ErrorLog, type Instance, type Revision } from "./lifecycle"
import { createManager } from "./manager"
import { evaluateMain } from "./module"
import { getStore } from "../storage/store"
import { createStorage, namespace } from "./storage"
import { createEmbeds } from "./embeds"

export type ExtensionHost = ReturnType<typeof createHost>

type Loaded = {
  readonly setup: MainSetup
  readonly i18n?: Catalog
  readonly stores?: Definition["stores"]
  /** A built-in's declared `provides`, the only Ipcs it may provide; unknown for an installed extension. */
  readonly provides?: NonNullable<Definition["provides"]>
}

/** An Ipc method with its spec erased: Ipcs of every spec share one table, and `call` runs the spec's codecs. */
type Method = IpcImpl<IpcSpec>[string]

/** A value one of an Ipc's schemas governs, erased like the methods that take it. */
type Value = Parameters<Method>[0]

type Provider = {
  readonly extension: string
  readonly signal: AbortSignal
  readonly spec: IpcSpec
  readonly methods: ReadonlyMap<string, Method>
  readonly state?: (window: number) => Value
}

/** The APIs a main context exposes as properties, as each instance creates them on first read. */
type HostApis = {
  -readonly [K in Exclude<keyof MainContext, keyof BaseContext | "scope" | "provide">]?: MainContext[K]
}

/** A contribution as `add` stores it, with its registry's item type erased; `list` restores it. */
type Item = Parameters<MainContext["add"]>[1]

type Entry = { readonly registry: string; readonly extension: string; readonly value: Item }

type Translation = { readonly catalog?: Catalog; messages: Messages }

const os = Match.value(process.platform).pipe(
  Match.when("darwin", () => "macos" as const),
  Match.when("win32", () => "windows" as const),
  Match.orElse(() => "linux" as const),
) satisfies OS

/**
 * The main-process GUI extension host. Every main extension is an app-scoped singleton; windows
 * reach its Ipcs over the bridge and main scopes state and events by `caller.window`.
 */
export function createHost(input: {
  readonly db: Database
  readonly state: StateStore
  readonly cli: Cli
  /** Windows per Ipc that asked for state; shared with the IPC layer, which records them first. */
  readonly subscriptions: Map<string, Set<number>>
  /** The server endpoints each window last pushed. */
  readonly servers: Map<number, readonly ExtensionEndpoint[]>
  readonly restart: (handoff?: () => void | Promise<void>) => Promise<void>
  readonly log: ErrorLog
  /** Extension logs at their own level. */
  readonly write: <Data extends Readonly<Record<string, unknown>>>(
    level: "debug" | "info" | "warn" | "error",
    message: string,
    data: Data,
  ) => void
}) {
  const definitions: readonly Definition[] = builtins
  const local = definitions.filter((definition) => !definition.os || definition.os.includes(os))

  const manager = createManager(
    input.db,
    (id) => id.startsWith("opencode") || definitions.some((definition) => definition.id === id),
    definitions,
  )

  const embeds = createEmbeds()
  const entries = new Map<string, Entry>()
  const ipcs = new Map<string, Provider>()
  // Each live instance's catalog and messages, so a locale change reaches them.
  const translations = new Set<Translation>()
  const reloads = new Map<string, number>()
  const closed = new Set<(win: BrowserWindow) => void>()
  const status = { sequence: 0, disposed: false, menubarQueued: false }

  const broadcast = (event: DesktopEvent) => getMainWindows().forEach((win) => emitIpcEvent(win.webContents, event))
  const changed = () => broadcast(new ExtensionsChanged({ list: installed() }))

  const subscribers = (ipc: string, window?: number) => {
    const ids = input.subscriptions.get(ipc)

    if (!ids) return []

    return [...ids]
      .filter((id) => window === undefined || id === window)
      .flatMap((id) => {
        const win = BrowserWindow.fromId(id)

        if (win && !win.isDestroyed()) return [win]
        ids.delete(id)

        return []
      })
  }

  const pushState = (ipc: string, provider: Provider, window?: number) => {
    const schema = provider.spec.state
    const stateOf = provider.state

    if (!schema || !stateOf) return
    subscribers(ipc, window).forEach((win) => {
      const encoded = Schema.encodeUnknownExit(schema)(stateOf(win.id))

      if (Exit.isFailure(encoded))
        return input.log("extension state encoding failed", { ipc, cause: String(encoded.cause) })
      emitIpcEvent(win.webContents, new ExtensionState({ ipc, state: encoded.value }))
    })
  }

  const menubarItems = () => {
    const items = [...entries.values()].flatMap((entry) => {
      if (entry.registry !== MenubarItem.id) return []
      const item = read(entry)

      return isMenubarItem(item) ? [{ id: `${entry.extension}.${item.id}`, extension: entry.extension, item }] : []
    })

    const published = new Set(items.map((item) => item.id))

    // `after` names a sibling from the same extension by its local id, or a built-in item.
    return items.map((entry) => {
      const after = entry.item.after
      const sibling = `${entry.extension}.${after}`

      return { ...entry, after: after === undefined ? undefined : published.has(sibling) ? sibling : after }
    })
  }

  const publishMenubar = () => {
    status.menubarQueued = false

    if (status.disposed) return
    refreshMenu()
    broadcast(new ExtensionMenubarItemsChanged({ items: listMenubarItems() }))
  }

  const scheduleMenubar = () => {
    if (status.menubarQueued) return
    status.menubarQueued = true
    queueMicrotask(publishMenubar)
  }

  const listMenubarItems = (): BridgeMenubarItem[] =>
    menubarItems().map((entry) => {
      const item = {
        menu: entry.item.menu,
        id: entry.id,
        label: entry.item.label,
        enabled: entry.item.enabled?.() ?? true,
      }

      // The IPC schema takes `after` as an optional key: it is left out rather than undefined.
      return entry.after === undefined ? item : { ...item, after: entry.after }
    })

  const server = (id: string): ServerEndpoint | undefined => {
    const sidecar = SidecarCredentials.get()

    // The app's own server is known here first-hand; the renderer never holds its credential.
    if (id === "sidecar") {
      if (!sidecar) return undefined
      const authorization = SidecarCredentials.authorization(sidecar, sidecar.url)

      return { id, url: sidecar.url, headers: authorization ? { authorization } : {}, local: true }
    }

    const endpoint = [...input.servers]
      .reverse()
      .flatMap(([window, list]) => {
        if (BrowserWindow.fromId(window)) return list
        input.servers.delete(window)

        return []
      })
      .find((item) => item.id === id)

    if (!endpoint) return undefined

    const authorization = endpoint.password
      ? `Basic ${Buffer.from(`${endpoint.username ?? "opencode"}:${endpoint.password}`).toString("base64")}`
      : SidecarCredentials.authorization(sidecar, endpoint.url)

    return {
      id,
      url: endpoint.url,
      headers: authorization ? { authorization } : {},
      local: !!sidecar && URL.canParse(endpoint.url) && new URL(endpoint.url).origin === sidecar.url,
      username: endpoint.username,
      password: endpoint.password,
    }
  }

  const build = { version: VERSION, channel: CHANNEL, platform: "desktop", packaged: app.isPackaged } satisfies Build

  const serverEndpoints = { get: server } satisfies ServerEndpoints

  const desktopLog = {
    write: (level, message, data) => input.write(level, message, data ?? {}),
  } satisfies Log

  const lifecycle = createLifecycle({
    loader: (id) => loader(id),
    enabled: (id) => manager.enabled(id),
    changed: () => changed(),
    log: input.log,
  })

  const loader = (id: string): (() => Promise<Revision>) | undefined => {
    const builtin = local.find((definition) => definition.id === id)

    if (builtin) {
      const main = builtin.main

      if (!main) return undefined

      return () =>
        main().then((module) =>
          // SAFETY: a built-in's main entry exports a `MainSetup`, whose context this host builds.
          prepare(id, {
            setup: module.default as MainSetup,
            i18n: builtin.i18n,
            stores: builtin.stores,
            provides: builtin.provides ?? {},
          }),
        )
    }

    const manifest = manager.installed().find((item) => item.id === id)?.manifest
    const entry = manifest?.main

    if (!manifest || !entry) return undefined

    return () => {
      const source = manager.file(id, entry)

      if (!source) return Promise.reject(new ExtensionError("invalidManifest"))

      return evaluateMain(source.toString("utf8"), manifest.imports.main ?? []).then((loaded) => prepare(id, loaded))
    }
  }

  const resolveMessages = async (catalog?: Catalog): Promise<Messages> => {
    const english = catalog?.en ?? {}
    const locale = nativeLocale()
    const source = locale === "en" ? undefined : catalog?.[locale]

    if (!source) return english
    const loaded = Predicate.isFunction(source) ? (await source()).default : source

    return { ...english, ...loaded }
  }

  /** A loaded revision of the extension's main code; each instance of it gets its own setup context. */
  const prepare =
    (id: string, loaded: Loaded): Revision =>
    (instance) =>
      createContext(id, loaded, instance)

  const createContext = (id: string, loaded: Loaded, instance: Instance): ReturnType<Revision> => {
    const signal = instance.scope.signal
    const contribute = instance.contribute
    // Registered first, so it runs last: the instance's embeds go after everything else it contributed. They are
    // owned by the instance, so releasing them never touches a replacement's.
    contribute(() => embeds.releaseOwner(instance))
    const translation: Translation = { catalog: loaded.i18n, messages: loaded.i18n?.en ?? {} }
    translations.add(translation)
    contribute(() => {
      translations.delete(translation)
    })
    // The instance's HostApis, each created on first read.
    const created: HostApis = {}

    function add<T>(registry: Registry<T>, item: T | (() => T | undefined)): Cleanup {
      if (signal.aborted) return () => {}

      const key = `${id}/${++status.sequence}`
      entries.set(key, { registry: registry.id, extension: id, value: item })

      if (registry.id === MenubarItem.id) scheduleMenubar()

      return contribute(() => {
        if (entries.delete(key) && registry.id === MenubarItem.id) scheduleMenubar()
      })
    }

    function list<T>(registry: Registry<T>): readonly T[] {
      return [...entries.values()].flatMap((entry) => {
        if (entry.registry !== registry.id) return []
        const value = read(entry)

        // SAFETY: only `add` stores entries, under the id of the typed registry it was given, so this registry's items
        // are T.
        return value === undefined ? [] : [value as T]
      })
    }

    function provide<S extends IpcSpec>(token: Ipc<S>, impl: IpcImpl<S>): IpcProvider<S>
    function provide(token: Ipc, impl: IpcImpl<IpcSpec>): IpcProvider<IpcSpec> {
      // Installed extensions are plain JavaScript: a contract token here has no spec to serve.
      if (token.kind !== "ipc") throw new Error("Contracts are provided by an extension's renderer entry")

      const ipc = token.id
      const declared = loaded.provides

      // A built-in's definition is known: it provides only the Ipcs it declares, so the windows' `uses` find them.
      if (declared && !Object.values(declared).some((item) => item.kind === "ipc" && item.id === ipc))
        throw new Error(`${id} provides Ipc "${ipc}" its definition does not declare in provides`)

      const current = ipcs.get(ipc)

      if (current && current.extension !== id)
        throw new Error(`Ipc "${ipc}" is already provided by ${current.extension}`)

      const methods = new Map(
        Object.keys(token.spec.methods).map((name) => {
          const method = Predicate.hasProperty(impl, name) ? impl[name] : undefined

          if (!isMethod(method)) throw new Error(`Ipc "${ipc}" is missing method "${name}"`)

          return [name, (value: Value, caller: Caller) => method.call(impl, value, caller)] as const
        }),
      )

      const stateOf = Predicate.hasProperty(impl, "state") ? impl.state : undefined

      const provider: Provider = {
        extension: id,
        signal,
        spec: token.spec,
        methods,
        state: isState(stateOf) ? (window) => stateOf.call(impl, window) : undefined,
      }

      const live = () => ipcs.get(ipc) === provider

      const dispose = signal.aborted
        ? () => {}
        : contribute(() => {
            if (!live()) return
            ipcs.delete(ipc)
            broadcast(new ExtensionAvailable({ ipc, available: false }))
          })

      if (!signal.aborted) {
        ipcs.set(ipc, provider)
        broadcast(new ExtensionAvailable({ ipc, available: true }))
        pushState(ipc, provider)
      }

      return {
        changed(window) {
          if (live()) pushState(ipc, provider, window)
        },
        emit(name, data, window) {
          if (!live()) return
          const schema = token.spec.events?.[name]

          if (!schema) throw new Error(`Ipc "${ipc}" has no event "${name}"`)
          const encoded = Schema.encodeUnknownExit(schema)(data)

          if (Exit.isFailure(encoded))
            return input.log("extension event encoding failed", { ipc, name, cause: String(encoded.cause) })
          const event = new ExtensionEvent({ ipc, name, data: encoded.value })

          if (window === undefined) return broadcast(event)
          const win = BrowserWindow.fromId(window)

          if (win && !win.isDestroyed()) emitIpcEvent(win.webContents, event)
        },
        dispose,
      }
    }

    const storage = () => (created.storage ??= createStorage(input.state, getStore, id))

    const context: MainContext = {
      id,
      scope: instance.scope,
      // The declared main stores, opened on the first read; main storage reads synchronously, so they are loaded.
      get stores() {
        return (created.stores ??= Object.fromEntries(
          Object.entries(loaded.stores ?? {}).flatMap(([name, declaration]) =>
            declaration.scope === "main" ? [[name, storage().store(name, declaration)] as const] : [],
          ),
        ))
      },
      get storage() {
        return storage()
      },
      get log() {
        return desktopLog
      },
      get lifecycle() {
        return (created.lifecycle ??= {
          restart: (handoff, options) =>
            lifecycle.restart(options?.keep ?? instance.scope, () => input.restart(handoff)),
        } satisfies Lifecycle)
      },
      get build() {
        return build
      },
      get serverEndpoints() {
        return serverEndpoints
      },
      get windows() {
        return (created.windows ??= {
          get: (window) => getMainWindows().find((win) => win.id === window),
          list: getMainWindows,
          focused: () => getLastFocusedWindow() ?? undefined,
          on: (event, handler) => {
            if (event === "open") return contribute(onMainWindow(handler))
            closed.add(handler)

            return contribute(() => {
              closed.delete(handler)
            })
          },
        } satisfies Windows)
      },
      get embeds() {
        return (created.embeds ??= {
          create: (view, win) => {
            const embed = embeds.create(instance, view, win)

            // Created by a setup that outlived its instance: taken down at once, like any late contribution.
            if (signal.aborted) contribute(embed.dispose)

            return embed
          },
        } satisfies Embeds)
      },
      get cli() {
        return input.cli
      },
      add,
      list,
      provide,
      t: (key: string, params?: Params) =>
        formatNativeTemplate(translation.messages[key] ?? nativeMessage(key) ?? key, params),
      plural: (key: string, count: number, params?: Params) => {
        const category = nativePluralCategory(count)

        const template =
          translation.messages[`${key}.${category}`] ??
          translation.messages[`${key}.other`] ??
          nativeMessage(`${key}.${category}`) ??
          nativeMessage(`${key}.other`) ??
          key

        return formatNativeTemplate(template, { ...params, count })
      },
    }

    return {
      ready: resolveMessages(loaded.i18n).then((messages) => {
        translation.messages = messages
      }),
      setup: () => loaded.setup(context),
    }
  }

  const known = (id: string) =>
    local.some((definition) => definition.id === id) || manager.installed().some((item) => item.id === id)

  const installed = (): ExtensionInstalled[] => [
    ...local.map((definition) => ({
      id: definition.id,
      // Built-ins are named by the renderer's own copy.
      name: definition.id,
      version: VERSION,
      builtin: true,
      enabled: manager.enabled(definition.id),
      ...revision(reloads.get(definition.id)?.toString()),
      ...failure(lifecycle.failure(definition.id)),
    })),
    ...manager.installed().map((item) => ({
      id: item.id,
      name: item.manifest?.name ?? item.id,
      version: item.manifest?.version ?? "",
      builtin: false,
      enabled: item.enabled,
      ...revision(item.revision),
      ...failure(item.manifest ? lifecycle.failure(item.id) : "invalidManifest"),
    })),
  ]

  const wire = (win: BrowserWindow) => {
    const window = win.id
    const forget = () => input.subscriptions.forEach((ids) => ids.delete(window))
    win.webContents.on(
      "did-start-navigation",
      (event: Electron.Event<{ isMainFrame: boolean; isSameDocument: boolean }>) => {
        if (!event.isMainFrame || event.isSameDocument) return
        // The renderer is reloading: it lays embeds out and subscribes again once it is back.
        embeds.reset(window)
        forget()
      },
    )
    win.once("closed", () => {
      embeds.releaseWindow(window)
      forget()
      input.servers.delete(window)
      closed.forEach((listener) => listener(win))
    })
  }

  getMainWindows().forEach(wire)
  const stopWindows = onMainWindow(wire)

  const stopLocale = onNativeTranslations(() => {
    const locale = nativeLocale()
    void Promise.all(
      [...translations].map(async (translation) => {
        const messages = await resolveMessages(translation.catalog).catch(() => translation.catalog?.en ?? {})

        if (nativeLocale() === locale) translation.messages = messages
      }),
    ).then(scheduleMenubar)
  })

  setMenubarProvider(() =>
    menubarItems().map((entry) => ({
      menu: entry.item.menu,
      id: entry.id,
      label: entry.item.label,
      after: entry.after,
      enabled: () => entry.item.enabled?.() ?? true,
      run: () => entry.item.run(getLastFocusedWindow() ?? undefined),
    })),
  )

  return {
    /** Activates every enabled main extension. The app calls this once its first window is up. */
    async start() {
      const ids = [...local.map((definition) => definition.id), ...manager.installed().map((item) => item.id)]
      await Promise.all(ids.map((id) => lifecycle.activate(id)))
    },
    /** Activates the declared provider ahead of `start`, falling back to the Ipc id's extension prefix. */
    demand(ipc: string) {
      if (ipcs.has(ipc)) return

      const declared = local.find((definition) =>
        Object.values(definition.provides ?? {}).some((token) => token.id === ipc),
      )

      const id =
        declared?.id ??
        [...local.map((definition) => definition.id), ...manager.installed().map((item) => item.id)].find(
          (id) => ipc === id || ipc.startsWith(`${id}.`),
        )

      if (id) void lifecycle.activate(id)
    },
    snapshot(ipc: string, window: number) {
      const provider = ipcs.get(ipc)

      if (!provider) return { available: false }
      const schema = provider.spec.state
      const stateOf = provider.state

      if (!schema || !stateOf) return { available: true }

      return { available: true, state: Schema.encodeUnknownSync(schema)(stateOf(window)) }
    },
    async call(request: { readonly ipc: string; readonly method: string; readonly input?: unknown }, caller: Caller) {
      const provider = ipcs.get(request.ipc)

      if (!provider) throw new ExtensionError("unavailable")
      const method = provider.methods.get(request.method)
      const spec = method ? provider.spec.methods[request.method] : undefined

      if (!method || !spec) throw new ExtensionError("method")

      const value = spec.input
        ? await Schema.decodeUnknownPromise(spec.input)(request.input).catch((cause: unknown) => {
            throw new ExtensionError("input", { cause, message: String(cause) })
          })
        : undefined

      // Withdrawn while the input decoded: the disposed instance is not called.
      if (ipcs.get(request.ipc) !== provider) throw new ExtensionError("unavailable")

      const output = await method(value, {
        window: caller.window,
        signal: AbortSignal.any([caller.signal, provider.signal]),
      })

      if (!spec.output) return undefined

      return Schema.encodeUnknownPromise(spec.output)(output).catch((cause: unknown) => {
        throw new ExtensionError("output", { cause, message: String(cause) })
      })
    },
    embed: (window: number, id: string, layout?: BridgeLayout) => embeds.layout(window, id, layout),
    capture: (window: number, id: string) =>
      embeds.capture(window, id).then((image) => (image ? new Uint8Array(image.toJPEG(90)) : undefined)),
    listMenubarItems,
    runMenubarItem(window: number, id: string) {
      const entry = menubarItems().find((item) => item.id === id)

      if (!entry || !(entry.item.enabled?.() ?? true)) return
      entry.item.run(BrowserWindow.fromId(window) ?? undefined)
    },
    list: installed,
    async enable(id: string) {
      if (!known(id)) throw new ExtensionError("notFound")
      manager.setEnabled(id, true)
      changed()
      await lifecycle.activate(id)
    },
    async disable(id: string) {
      if (!known(id)) throw new ExtensionError("notFound")
      manager.setEnabled(id, false)
      await lifecycle.deactivate(id)
      changed()
    },
    /** A development tool: packaged builds refuse it. A reload that fails keeps the last good revision running. */
    async reload(id: string) {
      if (!known(id)) throw new ExtensionError("notFound")

      if (local.some((definition) => definition.id === id)) reloads.set(id, (reloads.get(id) ?? 0) + 1)
      else manager.bump(id)
      await lifecycle.reload(id)
      changed()
    },
    async install(source: Uint8Array | string) {
      const manifest = await manager.install(source)
      lifecycle.forget(manifest.id)
      await lifecycle.deactivate(manifest.id)
      changed()
      await lifecycle.activate(manifest.id)
    },
    async remove(id: string) {
      if (local.some((definition) => definition.id === id)) throw new ExtensionError("builtin")

      if (!known(id)) throw new ExtensionError("notFound")
      // Inside the queue, so an activation queued meanwhile finds the extension already gone.
      await lifecycle.deactivate(id, () => {
        manager.remove(id)
        input.state.clear(namespace(id))
        lifecycle.forget(id)
      })
      changed()
    },
    source(id: string) {
      const manifest = manager.installed().find((item) => item.id === id)?.manifest

      if (!manifest) throw new ExtensionError("notFound")
      const file = manager.file(id, manifest.renderer)

      if (!file) throw new ExtensionError("notFound")

      return file.toString("utf8")
    },
    /** Disposes every main extension but one a restart handoff keeps; quitting awaits their async cleanups. */
    async dispose() {
      status.disposed = true
      stopWindows()
      stopLocale()
      // The menu is not rebuilt from here on (`publishMenubar`), so a kept extension's items stay in it.
      await lifecycle.dispose()
    },
  }
}

function read(entry: Entry) {
  return isGetter(entry.value) ? entry.value() : entry.value
}

// Installed extensions are plain JavaScript: these check the shapes the SDK types promise before the host relies on them.
function isGetter(value: Item): value is () => Item {
  return Predicate.isFunction(value)
}

function isMethod(value: unknown): value is Method {
  return Predicate.isFunction(value)
}

function isState(value: unknown): value is (window: number) => Value {
  return Predicate.isFunction(value)
}

function isMenubarItem(value: Item): value is MenubarItem {
  return (
    Predicate.hasProperty(value, "id") &&
    Predicate.hasProperty(value, "menu") &&
    Predicate.hasProperty(value, "label") &&
    Predicate.hasProperty(value, "run") &&
    Predicate.isString(value.id) &&
    Predicate.isString(value.label) &&
    Predicate.isFunction(value.run)
  )
}

function revision(value: string | undefined) {
  return value === undefined ? {} : { revision: value }
}

function failure(value: string | undefined) {
  return value === undefined ? {} : { error: value }
}

export * as Extensions from "./index"

import { app } from "electron"
import { Context, Effect, Layer } from "effect"
import type { ExtensionEndpoint } from "../../shared/ipc-rpc/extensions"
import { ApplicationLifecycle } from "../lifecycle"
import { Shutdown } from "../lifecycle/shutdown"

const LEVELS = { debug: "Debug", info: "Info", warn: "Warn", error: "Error" } as const

import { DesktopCli } from "../service/desktop-cli"
import { DesktopStorage } from "../storage"
import { setAppQuitting } from "../windows"
import { setExtensionAssets } from "../windows/protocol"
import { extensionAsset } from "./assets"
import type { ExtensionHost } from "./host"

/** The host once it loaded, and its load while one is in flight. */
type LoadedHost = { host?: ExtensionHost; loading?: Promise<ExtensionHost> }

export interface Interface {
  /** Loads the host on first use. Main extensions activate only through `start`. */
  readonly host: () => Promise<ExtensionHost>
  /** The host when something already loaded it. */
  readonly loaded: () => ExtensionHost | undefined
  /** Loads the host and activates main extensions. Runs once the first window is up. */
  readonly start: Effect.Effect<void>
  /** Starts state sync for a window. Before the host loads, nothing is available yet. */
  readonly subscribe: (ipc: string, window: number) => { readonly available: boolean; readonly state?: unknown }
  readonly configure: (window: number, servers: readonly ExtensionEndpoint[]) => void
}

export class Service extends Context.Service<Service, Interface>()("opencode/desktop/Extensions") {}

export const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const storage = yield* DesktopStorage.Service
    const shutdown = yield* Shutdown.Service
    const lifecycle = yield* ApplicationLifecycle.Service
    const desktopCli = yield* DesktopCli.Service
    const context = yield* Effect.context()
    const runFork = Effect.runForkWith(context)
    const runPromise = Effect.runPromiseWith(context)
    // Renderers subscribe and push servers while they boot, which can be before the host loads.
    const subscriptions = new Map<string, Set<number>>()
    const servers = new Map<number, readonly ExtensionEndpoint[]>()
    const current: LoadedHost = {}

    setExtensionAssets((request, url) => extensionAsset(storage.db, request, url))

    // Disposes every extension but the caller (the host keeps it), then hands off (e.g. quitAndInstall) or relaunches.
    const restart = async (handoff?: () => void | Promise<void>) => {
      setAppQuitting()
      await runPromise(lifecycle.prepareToRestart)

      if (!handoff) {
        app.relaunch()
        app.quit()

        return
      }

      await Promise.resolve()
        .then(handoff)
        .catch((cause: unknown) => {
          setAppQuitting(false)
          throw cause
        })
    }

    const host = () => {
      current.loading ??= Promise.all([import("./host"), runPromise(desktopCli.resolve)]).then(([module, cli]) => {
        current.host = module.createHost({
          db: storage.db,
          state: storage.state,
          cli: {
            version: cli.version,
            command: cli.command,
            binary: cli.binary,
            development: !app.isPackaged && !cli.binary,
          },
          subscriptions,
          servers,
          restart,
          log: (message, data) => runFork(Effect.logError(message, data)),
          write: (level, message, data) => runFork(Effect.logWithLevel(LEVELS[level])(message, data)),
        })

        return current.host
      })

      return current.loading
    }

    const stop = Effect.promise(async () => {
      if (current.loading)
        await current.loading.then(
          (loaded) => loaded.dispose(),
          () => undefined,
        )
    })

    const remove = yield* shutdown.add(stop)
    yield* Effect.addFinalizer(() => Effect.sync(remove))

    return Service.of({
      host,
      loaded: () => current.host,
      start: Effect.tryPromise(() => host().then((loaded) => loaded.start())).pipe(
        Effect.catch((error) => Effect.logError("extensions failed to start", { error })),
      ),
      subscribe(ipc, window) {
        const ids = subscriptions.get(ipc) ?? new Set()
        ids.add(window)
        subscriptions.set(ipc, ids)
        // A booting window waits on some Ipcs (e.g. server sources) before its first paint, so the
        // extension that provides one starts now instead of with the deferred rest.
        void host().then(
          (loaded) => loaded.demand(ipc),
          () => undefined,
        )

        return current.host?.snapshot(ipc, window) ?? { available: false }
      },
      configure(window, list) {
        // Re-inserting keeps the most recent window last, which resolution prefers.
        servers.delete(window)
        servers.set(window, list)
      },
    })
  }),
)

import { afterEach, beforeEach, describe, expect, jest, test } from "bun:test"
import { createLifecycle, type Instance, type Revision } from "./lifecycle"

// The host's cleanup deadline and setup stall log, as `lifecycle.ts` sets them.
const CLEANUP_MS = 3_000

const STALL_MS = 10_000

type Wait = number | "hang"

type Plan = {
  readonly load?: Wait
  readonly loadFails?: boolean
  readonly ready?: Wait
  readonly setup?: Wait
  readonly setupFails?: boolean
  /** The finalizer setup adds before its await. */
  readonly cleanup?: Wait
  /** The finalizer setup adds after its await, as it finishes. */
  readonly late?: Wait
}

type Made = { readonly id: string; readonly revision: string; readonly label: string; readonly instance: Instance }

type Contribution = { readonly made: Made; readonly kind: "ipc" | "listener" | "embed"; readonly window?: number }

beforeEach(() => jest.useFakeTimers())

afterEach(() => {
  jest.clearAllTimers()
  jest.useRealTimers()
})

// Fake timers leave setImmediate real: one turn drains every pending microtask.
const flush = () => new Promise<void>((resolve) => setImmediate(resolve))

const advance = async (ms: number, step = 10) => {
  for (let left = ms; left > 0; left -= step) {
    jest.advanceTimersByTime(Math.min(step, left))
    await flush()
  }
}

const wait = (value: Wait | undefined) => {
  if (value === "hang") return new Promise<void>(() => {})

  if (!value) return Promise.resolve()

  return new Promise<void>((resolve) => setTimeout(resolve, value))
}

/**
 * A fake host around the real lifecycle: extensions whose code loads, prepares, sets up and cleans up on a plan, and
 * a registry of what each instance contributed, including embeds in windows that open and close.
 */
function world() {
  const logs: { readonly message: string; readonly data: object }[] = []
  const events: string[] = []
  const enabled = new Map<string, boolean>()
  const revisions = new Map<string, { readonly name: string; readonly plan: Plan }>()
  const versions = new Map<string, number>()
  const made: Made[] = []
  const contributions = new Set<Contribution>()
  const violations: string[] = []
  const windows = new Set<number>()
  const openers = new Set<(window: number) => void>()
  const counter = { window: 0 }
  // Setups that finished after their instance stopped, and those that did while a replacement ran.
  const stats = { late: 0, overlapping: 0 }
  /** The instances neither stopped nor stopping. */
  const live = (id?: string) => made.filter((item) => !item.instance.scope.signal.aborted && (!id || item.id === id))

  const contribute = (owner: Made, kind: Contribution["kind"], window?: number, withdraw?: () => void) => {
    const entry: Contribution = { made: owner, kind, window }
    contributions.add(entry)
    owner.instance.contribute(() => {
      // Only the owner's own disposal withdraws what it contributed.
      if (!owner.instance.scope.signal.aborted) violations.push(`${kind} of live ${owner.label} withdrawn`)
      contributions.delete(entry)
      withdraw?.()
    })
  }

  const revision =
    (id: string, name: string, plan: Plan): Revision =>
    (instance) => {
      const owner: Made = { id, revision: name, label: `${name}#${made.length + 1}`, instance }
      made.push(owner)

      return {
        ready: wait(plan.ready),
        setup: async () => {
          events.push(`setup ${owner.label}`)
          contribute(owner, "ipc")
          instance.scope.addFinalizer(async () => {
            events.push(`cleanup ${owner.label}`)
            await wait(plan.cleanup)
            events.push(`cleanup ${owner.label} done`)
          })
          await wait(plan.setup)

          if (plan.setupFails) throw new Error(`${owner.label} setup failed`)

          if (instance.scope.signal.aborted) stats.late++

          if (instance.scope.signal.aborted && live(id).length) stats.overlapping++
          // Registered after an await without checking the signal: a stopped instance withdraws them at once.
          windows.forEach((window) => contribute(owner, "embed", window))
          const opener = (window: number) => contribute(owner, "embed", window)
          openers.add(opener)
          contribute(owner, "listener", undefined, () => openers.delete(opener))
          events.push(`ready ${owner.label}`)
          // Added without checking the signal: a stopped instance runs it at once, and its disposal waits for it.
          instance.scope.addFinalizer(async () => {
            events.push(`late ${owner.label}`)
            await wait(plan.late)
            events.push(`late ${owner.label} done`)
          })
        },
      }
    }

  const lifecycle = createLifecycle({
    loader: (id) => {
      const current = revisions.get(id)

      if (!current) return undefined

      return () =>
        wait(current.plan.load).then(() => {
          if (current.plan.loadFails) throw new Error(`${current.name} load failed`)

          return revision(id, current.name, current.plan)
        })
    },
    enabled: (id) => enabled.get(id) ?? true,
    changed: () => {},
    log: (message, data) => logs.push({ message, data }),
  })

  /** Makes `plan` the extension's current code under a new revision name: a1, a2, … */
  const revise = (id: string, plan: Plan = {}) => {
    const version = (versions.get(id) ?? 0) + 1
    versions.set(id, version)
    revisions.set(id, { name: `${id}${version}`, plan })

    return `${id}${version}`
  }

  return {
    lifecycle,
    logs,
    stats,
    events,
    made,
    contributions,
    violations,
    enabled,
    revise,
    live,
    open() {
      const window = ++counter.window
      windows.add(window)
      ;[...openers].forEach((opener) => opener(window))

      return window
    },
    close(window: number) {
      windows.delete(window)
      // The host releases a closed window's embeds itself, whichever instance owns them.
      contributions.forEach((entry) => {
        if (entry.window === window) contributions.delete(entry)
      })
    },
    // The host's `install` and `remove` around the lifecycle.
    async install(id: string, plan: Plan = {}) {
      revise(id, plan)
      enabled.set(id, true)
      lifecycle.forget(id)
      await lifecycle.deactivate(id)
      await lifecycle.activate(id)
    },
    uninstall(id: string) {
      return lifecycle.deactivate(id, () => {
        revisions.delete(id)
        lifecycle.forget(id)
      })
    },
  }
}

type World = ReturnType<typeof world>

const settled = (promise: Promise<unknown>) => {
  const state = { settled: false, rejected: false }
  void promise.then(
    () => (state.settled = true),
    () => {
      state.settled = true
      state.rejected = true
    },
  )

  return state
}

/** The invariants every lifecycle state keeps. */
function check(w: World) {
  const counts = Map.groupBy(w.live(), (item) => item.id)
  counts.forEach((items, id) => {
    if (items.length > 1) throw new Error(`${items.length} live instances of ${id}: ${items.map((i) => i.label)}`)
  })
  w.contributions.forEach((entry) => {
    if (entry.made.instance.scope.signal.aborted)
      throw new Error(`${entry.kind} of stopped ${entry.made.label} is still contributed`)
  })

  if (w.violations.length) throw new Error(w.violations.join("; "))
}

describe("extension lifecycle contracts", () => {
  test.each([
    {
      name: "reload",
      stop: (w: World) => {
        w.revise("a")

        return w.lifecycle.reload("a")
      },
    },
    {
      name: "disable then enable",
      stop: (w: World) => {
        w.enabled.set("a", false)
        void w.lifecycle.deactivate("a")
        w.enabled.set("a", true)

        return w.lifecycle.activate("a")
      },
    },
    { name: "reinstall", stop: (w: World) => w.install("a") },
  ])("$name during async setup stops the instance at once and starts the next after its late cleanup", async (row) => {
    const w = world()
    w.revise("a", { setup: 50, late: 30 })
    void w.lifecycle.activate("a")
    await advance(10)
    expect(w.events).toEqual(["setup a1#1"])
    const done = settled(row.stop(w))
    // Withdrawn synchronously, before any cleanup runs.
    expect(w.live("a")).toEqual([])
    expect(w.contributions.size).toBe(0)
    await advance(200)
    check(w)
    expect(done.settled).toBe(true)
    const next = w.made[1]
    expect(w.live("a")).toEqual([next])
    // The setup that outlived its instance contributed nothing that stayed, and its late finalizer finished before
    // the next instance's setup started.
    expect(w.events).toEqual([
      "setup a1#1",
      "cleanup a1#1",
      "cleanup a1#1 done",
      "ready a1#1",
      "late a1#1",
      "late a1#1 done",
      `setup ${next.label}`,
      `ready ${next.label}`,
    ])
  })

  test("operations on one extension run in call order, each after the previous one settled", async () => {
    const w = world()
    w.revise("a", { cleanup: 40 })
    void w.lifecycle.activate("a")
    await advance(10)
    w.enabled.set("a", false)
    const disabled = settled(w.lifecycle.deactivate("a"))
    w.enabled.set("a", true)
    const enabled = settled(w.lifecycle.activate("a"))
    await advance(30)
    expect(disabled.settled).toBe(false)
    expect(w.made).toHaveLength(1)
    await advance(20)
    expect(disabled.settled).toBe(true)
    expect(enabled.settled).toBe(true)
    expect(w.events).toEqual([
      "setup a1#1",
      "ready a1#1",
      "late a1#1",
      "late a1#1 done",
      "cleanup a1#1",
      "cleanup a1#1 done",
      "setup a1#2",
      "ready a1#2",
    ])
  })

  test("a hung cleanup holds the queue only until the deadline", async () => {
    const w = world()
    w.revise("a", { cleanup: "hang" })
    void w.lifecycle.activate("a")
    await advance(10)
    w.enabled.set("a", false)
    const disabled = settled(w.lifecycle.deactivate("a"))
    w.enabled.set("a", true)
    void w.lifecycle.activate("a")
    await advance(CLEANUP_MS - 20)
    expect(disabled.settled).toBe(false)
    expect(w.made).toHaveLength(1)
    await advance(20)
    expect(disabled.settled).toBe(true)
    expect(w.live("a").map((item) => item.label)).toEqual(["a1#2"])
    expect(w.logs.map((entry) => entry.message)).toContain("scope finalizer timed out")
  })

  test.each([
    { phase: "loading", plan: { load: "hang" }, setup: false },
    { phase: "preparing", plan: { ready: "hang" }, setup: false },
    { phase: "setting up", plan: { setup: "hang" }, setup: true },
    { phase: "an activation waits behind a hung setup", plan: { setup: "hang" }, queued: true, setup: true },
    { phase: "tearing down", plan: { cleanup: "hang" }, teardown: true, setup: true },
  ] satisfies { phase: string; plan: Plan; setup: boolean; queued?: boolean; teardown?: boolean }[])(
    "quitting while $phase settles by the deadline and leaves nothing behind",
    async (row) => {
      const w = world()
      w.revise("a", row.plan)
      w.revise("b")
      void w.lifecycle.activate("a")
      void w.lifecycle.activate("b")
      await advance(10)

      if (row.queued) void w.lifecycle.activate("a")

      if (row.teardown) void w.lifecycle.deactivate("a")
      const quit = settled(w.lifecycle.dispose())
      expect(w.live()).toEqual([])
      expect(w.contributions.size).toBe(0)
      await advance(CLEANUP_MS + 20)
      expect(quit.settled).toBe(true)
      expect(w.events.includes("setup a1#1")).toBe(row.setup)
      check(w)
    },
  )

  test("a restart handoff keeps its scope's instance through quitting until the handoff settles", async () => {
    const w = world()
    w.revise("a")
    w.revise("b")
    await Promise.all([w.lifecycle.activate("a"), w.lifecycle.activate("b")])
    const [a, b] = w.made
    const handoff = { reject: (_: Error) => {} }

    const restart = settled(
      w.lifecycle.restart(a.instance.scope, async () => {
        await w.lifecycle.dispose()
        await new Promise<void>((_, reject) => (handoff.reject = reject))
      }),
    )

    await advance(CLEANUP_MS)
    expect(w.live()).toEqual([a])
    expect([...w.contributions].filter((entry) => entry.made === b)).toEqual([])
    expect([...w.contributions].some((entry) => entry.made === a)).toBe(true)
    handoff.reject(new Error("install failed"))
    await advance(10)
    expect(restart).toEqual({ settled: true, rejected: true })
    expect(w.live()).toEqual([a])
    // Once the handoff settled, quitting stops it like any other.
    const quit = settled(w.lifecycle.dispose())
    await advance(10)
    expect(quit.settled).toBe(true)
    expect(w.live()).toEqual([])
  })

  test("a restart handoff rejects a scope that is not an instance's", async () => {
    const w = world()
    w.revise("a")
    await w.lifecycle.activate("a")
    const ran = { handoff: false }
    const fork = w.made[0].instance.scope.fork("handoff")
    const restart = settled(w.lifecycle.restart(fork, async () => void (ran.handoff = true)))
    await advance(10)
    expect(restart).toEqual({ settled: true, rejected: true })
    expect(ran.handoff).toBe(false)
  })

  test.each([
    { name: "fails to load", plan: { loadFails: true }, live: "a1#1", failed: true },
    { name: "fails to set up", plan: { setupFails: true }, live: "a1#3", failed: true },
    { name: "succeeds", plan: {}, live: "a2#2", failed: false },
  ] satisfies { name: string; plan: Plan; live: string; failed: boolean }[])(
    "a reload that $name leaves the last good revision running",
    async (row) => {
      const w = world()
      w.revise("a")
      await w.lifecycle.activate("a")
      const previous = w.made[0]
      w.revise("a", row.plan)
      await w.lifecycle.reload("a")
      check(w)
      expect(w.live("a").map((item) => item.label)).toEqual([row.live])
      // The same instance when the new code failed to load: it kept running through the reload.
      expect(previous.instance.scope.signal.aborted).toBe(row.live !== previous.label)
      expect(w.lifecycle.failure("a") !== undefined).toBe(row.failed)
    },
  )

  test("a failed reload with no good revision leaves the extension stopped and failed", async () => {
    const w = world()
    w.revise("a", { setupFails: true })
    await w.lifecycle.activate("a")
    w.revise("a", { setupFails: true })
    await w.lifecycle.reload("a")
    expect(w.live("a")).toEqual([])
    expect(w.lifecycle.failure("a")).toBe("a2#2 setup failed")
  })

  test.each([
    { name: "a setup that hangs is logged once", setup: "hang", logged: 1 },
    { name: "a setup that finishes before the stall deadline is not logged", setup: STALL_MS - 1_000, logged: 0 },
  ] satisfies { name: string; setup: Wait; logged: number }[])("$name", async (row) => {
    const w = world()
    w.revise("a", { setup: row.setup })
    void w.lifecycle.activate("a")
    await advance(STALL_MS * 2, 500)
    expect(w.logs.filter((entry) => entry.message === "extension setup stalled")).toEqual(
      Array.from({ length: row.logged }, () => ({
        message: "extension setup stalled",
        data: { id: "a", ms: STALL_MS },
      })),
    )
  })
})

/** A deterministic random source, so a failing seed replays. */
function random(seed: number) {
  const state = { value: seed >>> 0 }

  const next = () => {
    state.value = (state.value + 0x6d2b79f5) >>> 0
    const mixed = Math.imul(state.value ^ (state.value >>> 15), 1 | state.value)
    const spread = (mixed + Math.imul(mixed ^ (mixed >>> 7), 61 | mixed)) ^ mixed

    return ((spread ^ (spread >>> 14)) >>> 0) / 4294967296
  }

  return {
    next,
    chance: (p: number) => next() < p,
    int: (max: number) => Math.floor(next() * max),
    pick: <T>(items: readonly T[]) => items[Math.floor(next() * items.length)],
  }
}

type Random = ReturnType<typeof random>

// Mostly short; sometimes it hangs, or outlasts the cleanup deadline and then finishes while a replacement runs.
const delay = (rng: Random, hang: number, max: number): Wait => {
  if (rng.chance(hang)) return "hang"

  if (rng.chance(0.08)) return CLEANUP_MS + rng.int(CLEANUP_MS)

  return rng.chance(0.3) ? 0 : 1 + rng.int(max)
}

const plan = (rng: Random): Plan => ({
  load: delay(rng, 0.04, 40),
  loadFails: rng.chance(0.12),
  ready: delay(rng, 0.03, 20),
  setup: delay(rng, 0.05, 60),
  setupFails: rng.chance(0.12),
  cleanup: delay(rng, 0.1, 50),
  late: delay(rng, 0.05, 30),
})

const SEEDS = 1_000

const STEPS = 40

const IDS = ["a", "b", "c"]

/** How often the runs reached the cases the invariants are about, so a generator change cannot make them vacuous. */
const reached = { failedReloads: 0, lateSetups: 0, overlappingSetups: 0, hungFinalizers: 0, stalls: 0 }

async function fuzz(seed: number, trace: string[]) {
  const rng = random(seed)
  const w = world()
  const pending: { readonly op: string; readonly state: { settled: boolean } }[] = []
  // Operations that stop or replace an extension; a reload checked against the last good revision must be the latest.
  const superseded = new Map<string, number>()
  const model = { quitting: false }

  const run = (op: string, promise: Promise<unknown>) => {
    trace.push(op)
    pending.push({ op, state: settled(promise) })
  }

  const supersede = (id: string) => superseded.set(id, (superseded.get(id) ?? 0) + 1)
  IDS.forEach((id) => w.revise(id, plan(rng)))

  const ops = {
    activate: (id) => run(`activate ${id}`, w.lifecycle.activate(id)),
    enable: (id) => {
      w.enabled.set(id, true)
      run(`enable ${id}`, w.lifecycle.activate(id))
    },
    disable: (id) => {
      supersede(id)
      w.enabled.set(id, false)
      run(`disable ${id}`, w.lifecycle.deactivate(id))
    },
    reload: (id) => {
      supersede(id)
      const next = plan(rng)
      const name = w.revise(id, next)
      const marker = superseded.get(id)
      // The live instance whose setup finished: the revision a failed reload must leave running.
      const good = w.live(id).find((item) => w.events.includes(`ready ${item.label}`))
      run(
        `reload ${id} -> ${name} ${JSON.stringify(next)}`,
        w.lifecycle.reload(id).then(() => {
          const stale = superseded.get(id) !== marker || model.quitting || w.enabled.get(id) === false

          if (stale || !good || !(next.loadFails || next.setupFails)) return
          reached.failedReloads++

          if (!w.live(id).some((item) => item.revision === good.revision))
            w.violations.push(`failed reload to ${name} left no instance of ${good.revision} running`)

          if (w.lifecycle.failure(id) === undefined) w.violations.push(`failed reload to ${name} recorded nothing`)
        }),
      )
    },
    install: (id) => {
      supersede(id)
      run(`install ${id}`, w.install(id, plan(rng)))
    },
    remove: (id) => {
      supersede(id)
      run(`remove ${id}`, w.uninstall(id))
    },
    open: () => trace.push(`open window ${w.open()}`),
    close: () => {
      const window = rng.pick([...new Set([...w.contributions].flatMap((entry) => entry.window ?? []))])

      if (window === undefined) return
      trace.push(`close window ${window}`)
      w.close(window)
    },
    quit: () => {
      model.quitting = true
      IDS.forEach(supersede)
      run("quit", w.lifecycle.dispose())
    },
    wait: () => {},
  } satisfies Record<string, (id: string) => void>

  const weights: [keyof typeof ops, number][] = [
    ["activate", 2],
    ["enable", 1.5],
    ["disable", 1.5],
    ["reload", 3],
    ["install", 0.7],
    ["remove", 0.7],
    ["open", 1],
    ["close", 1],
    ["quit", 0.05],
    ["wait", 2],
  ]

  const bounds = weights.map(([op], index) => ({
    op,
    below: weights.slice(0, index + 1).reduce((sum, [, weight]) => sum + weight, 0),
  }))

  const choose = () => {
    const target = rng.next() * bounds[bounds.length - 1].below

    return bounds.find((bound) => target < bound.below)?.op ?? "wait"
  }

  for (let step = 0; step < STEPS; step++) {
    ops[choose()](rng.pick(IDS))
    check(w)
    const long = rng.chance(0.1)
    await advance(long ? CLEANUP_MS + 500 : rng.int(120), long ? 250 : 10)
    check(w)
  }

  // Quitting settles by the cleanup deadline, whatever hangs, and so does every operation still queued.
  ops.quit()
  await advance(CLEANUP_MS + 200, 20)
  const stuck = pending.flatMap((item) => (item.state.settled ? [] : [item.op]))

  if (stuck.length) throw new Error(`still pending ${CLEANUP_MS + 200}ms after quit: ${stuck.join(", ")}`)
  check(w)

  if (w.live().length) throw new Error(`live after quit: ${w.live().map((item) => item.label)}`)

  if (w.contributions.size) throw new Error(`${w.contributions.size} contributions left after quit`)
  reached.lateSetups += w.stats.late
  reached.overlappingSetups += w.stats.overlapping
  reached.hungFinalizers += w.logs.filter((entry) => entry.message === "scope finalizer timed out").length
  reached.stalls += w.logs.filter((entry) => entry.message === "extension setup stalled").length
}

test(`lifecycle invariants hold over ${SEEDS} random operation sequences`, async () => {
  for (let seed = 1; seed <= SEEDS; seed++) {
    const trace: string[] = []
    await fuzz(seed, trace).catch((cause: unknown) => {
      throw new Error(`seed ${seed}: ${cause instanceof Error ? cause.message : String(cause)}\n${trace.join("\n")}`)
    })
    jest.clearAllTimers()
  }

  Object.values(reached).forEach((count) => expect(count).toBeGreaterThan(20))
})

import { Scope, type Cleanup } from "@opencode/gui-extensions/sdk/main"

/** How long disposal waits for an instance's finalizers and a setup still running. */
const CLEANUP_TIMEOUT_MS = 3_000

/** A setup still running after this long is logged once. */
const SETUP_STALL_MS = 10_000

/** One running copy of an extension's main code, from setup until it is stopped. */
export interface Instance {
  readonly id: string
  /** Closes when the instance goes away, right after the host withdrew what the instance contributed. */
  readonly scope: Scope
  /**
   * Records something the host registered for the instance. The host withdraws it synchronously the moment disposal
   * starts, before any finalizer runs, and at once when registered after that. The function returned withdraws it early.
   */
  contribute(withdraw: () => void): Cleanup
}

/** One loaded revision of an extension's main code. Each call prepares a fresh instance of it. */
export type Revision = (instance: Instance) => {
  /** Settles before setup runs; setup never runs when the extension stops first. A failure here does not stop setup. */
  readonly ready: Promise<unknown>
  readonly setup: () => void | Promise<void>
}

/** Writes a structured error log entry; the logger serializes each field of `data` as it is. */
export type ErrorLog = <Data extends Readonly<Record<string, unknown>>>(message: string, data: Data) => void

type Outcome = { readonly ok: true } | { readonly ok: false; readonly error: unknown }

/** Where an instance's setup and disposal stand. */
type Progress = { setup: Promise<Outcome | undefined>; disposed?: Promise<void> }

type Running = {
  readonly instance: Instance
  readonly revision: Revision
  readonly ready: Promise<unknown>
  /** Its setup succeeded while it was active. */
  good: boolean
  /** Runs setup once. A finalizer it adds belongs to the instance, even when setup settles after disposal. */
  start(): Promise<Outcome>
  /**
   * Withdraws everything the instance contributed at once, then settles once its finalizers and a setup still
   * running have finished, or the deadline passed. Idempotent.
   */
  dispose(): Promise<void>
}

/**
 * The extension lifecycle without Electron: one serialized queue of operations per extension, the instances they
 * start and stop, and what the host withdraws when an instance goes away.
 */
export function createLifecycle(input: {
  /** Loads the extension's current main code; undefined when it has none. */
  readonly loader: (id: string) => (() => Promise<Revision>) | undefined
  readonly enabled: (id: string) => boolean
  /** A failure was recorded. */
  readonly changed: () => void
  readonly log: ErrorLog
}) {
  const active = new Map<string, Running>()
  // One serialized lifecycle per extension: each operation starts after the previous one fully settled.
  const queues = new Map<string, Promise<void>>()
  // Each extension's current generation. Stopping aborts it, so the activations queued or running under it
  // wind down at once; operations queued afterwards run under a fresh generation.
  const generations = new Map<string, AbortController>()
  // The revision whose setup last succeeded since the extension was last stopped; a failed reload returns to it.
  const last = new Map<string, Revision>()
  const errors = new Map<string, string>()
  // Scopes a restart handoff keeps. Quitting skips their instances, so a failed handoff leaves them working and a
  // successful one keeps their state and contributions until the app has quit.
  const kept = new Set<Scope>()
  const status = { quitting: false }

  const current = (id: string, signal: AbortSignal) => !signal.aborted && input.enabled(id) && !status.quitting

  const fail = (id: string, cause: unknown) => {
    errors.set(id, cause instanceof Error ? cause.message : String(cause))
    input.log("extension failed", { id, error: cause })
    input.changed()
  }

  const create = (id: string, revision: Revision): Running => {
    const scope = Scope.make(id, { timeout: CLEANUP_TIMEOUT_MS, log: input.log })
    // The host's record of what the instance contributed; the host withdraws it the moment disposal starts.
    const contributions = new Set<() => void>()

    const withdraw = (fn: () => void) => {
      // Host bookkeeping does not throw by design; isolating it keeps one failure from leaving the rest behind.
      try {
        fn()
      } catch (error) {
        input.log("extension withdrawal failed", { id, error })
      }
    }

    const instance: Instance = {
      id,
      scope,
      contribute(fn) {
        if (scope.signal.aborted) {
          withdraw(fn)

          return () => {}
        }

        const remove = () => {
          if (contributions.delete(remove)) fn()
        }

        contributions.add(remove)

        return remove
      },
    }

    const prepared = revision(instance)
    const progress: Progress = { setup: Promise.resolve(undefined) }

    return {
      instance,
      revision,
      ready: prepared.ready.catch(() => undefined),
      good: false,
      start() {
        const stall = setTimeout(() => input.log("extension setup stalled", { id, ms: SETUP_STALL_MS }), SETUP_STALL_MS)

        // A finalizer a setup adds after disposal started runs at once, and disposal waits for it.
        const outcome = Promise.resolve()
          .then(prepared.setup)
          .then(
            (): Outcome => ({ ok: true }),
            (cause: unknown): Outcome => ({ ok: false, error: cause }),
          )
          .finally(() => clearTimeout(stall))

        progress.setup = outcome

        return outcome
      },
      dispose() {
        if (progress.disposed) return progress.disposed

        // Aborts the signal now; the finalizers start only after the withdrawal below.
        const closed = scope.close()

        // The host withdraws first and synchronously: a disposed instance is unreachable even if a finalizer hangs.
        ;[...contributions].reverse().forEach(withdraw)

        // A setup still running settles, and the finalizers it adds late run, before the next lifecycle step.
        const settled = within(
          progress.setup.then(() => scope.close()),
          () => input.log("extension cleanup timed out", { id }),
        )

        progress.disposed = Promise.all([closed, settled]).then(() => undefined)

        return progress.disposed
      },
    }
  }

  // The caller sees the step's own outcome; the queue only waits for it to settle, so a failed step never
  // stalls the steps behind it.
  const enqueue = (id: string, task: () => Promise<void>) => {
    const step = (queues.get(id) ?? Promise.resolve()).then(task).then(() => undefined)

    const tail: Promise<void> = step
      .catch(() => undefined)
      .finally(() => {
        if (queues.get(id) === tail) queues.delete(id)
      })

    queues.set(id, tail)

    return step
  }

  const generation = (id: string) => {
    const existing = generations.get(id)

    if (existing) return existing.signal
    const created = new AbortController()
    generations.set(id, created)

    return created.signal
  }

  const stop = (id: string) => {
    generations.get(id)?.abort()
    generations.delete(id)
  }

  /** The loaded revision, or undefined when loading failed (recorded) or the extension stopped meanwhile. */
  const load = (id: string, signal: AbortSignal, loader: () => Promise<Revision>) =>
    until(
      signal,
      loader().catch((cause: unknown) => {
        if (current(id, signal)) fail(id, cause)

        return undefined
      }),
    )

  /** Starts an instance of the revision. Resolves with its setup's outcome, or undefined when it stopped first. */
  const run = async (id: string, signal: AbortSignal, revision: Revision) => {
    const running = create(id, revision)
    active.set(id, running)
    await until(signal, running.ready)

    // Stopping removed the instance and began disposing it; its setup never runs.
    if (!current(id, signal)) {
      if (active.get(id) === running) active.delete(id)
      await running.dispose()

      return undefined
    }

    const outcome = await until(signal, running.start())

    // A stop during setup settles this step once the disposal has, however long setup takes.
    if (!outcome) {
      await running.dispose()

      return undefined
    }

    if (active.get(id) !== running) return undefined

    if (outcome.ok) {
      running.good = true
      last.set(id, revision)

      return outcome
    }

    fail(id, outcome.error)
    active.delete(id)
    await running.dispose()

    return outcome
  }

  const activate = (id: string) => {
    const signal = generation(id)

    return enqueue(id, async () => {
      const loader = input.loader(id)

      if (!loader || active.has(id) || !current(id, signal)) return
      errors.delete(id)
      const revision = await load(id, signal, loader)

      // Stopped, disabled, or quitting while the code loaded: drop it, it may belong to an older revision.
      if (!revision || active.has(id) || !current(id, signal)) return
      await run(id, signal, revision)
    })
  }

  /**
   * Stops the extension at once and queues its teardown: activations queued before it go stale, the instance
   * withdraws everything it contributed now, and the queue moves on only after its disposal settled. `after`
   * runs inside the queue once the teardown finished.
   */
  const deactivate = (id: string, after?: () => void) => {
    stop(id)
    last.delete(id)
    const running = active.get(id)
    active.delete(id)
    void running?.dispose()

    return enqueue(id, async () => {
      await running?.dispose()
      after?.()
    })
  }

  /**
   * Replaces the extension with its current code. A good instance keeps running until that code loaded; a reload that
   * fails to load or set up leaves the last good revision running, with the failure recorded.
   */
  const reload = (id: string) => {
    errors.delete(id)
    stop(id)
    const previous = active.get(id)
    // An instance still starting is no revision to keep: it stops at once, as on disable.
    const stopped = previous && !previous.good ? previous : undefined

    if (stopped) {
      active.delete(id)
      void stopped.dispose()
    }

    const signal = generation(id)

    return enqueue(id, async () => {
      await stopped?.dispose()
      const loader = input.loader(id)

      if (!loader || !current(id, signal)) return
      const fallback = last.get(id)
      const revision = await load(id, signal, loader)

      if (!current(id, signal)) return
      const running = active.get(id)

      if (!revision) {
        if (!running && fallback) await run(id, signal, fallback)

        return
      }

      if (running) {
        active.delete(id)
        await running.dispose()

        if (!current(id, signal)) return
      }

      const outcome = await run(id, signal, revision)

      if (outcome?.ok === false && fallback) await run(id, signal, fallback)
    })
  }

  return {
    activate,
    deactivate,
    reload,
    failure: (id: string) => errors.get(id),
    forget(id: string) {
      errors.delete(id)
    },
    /**
     * Runs a restart handoff that keeps `keep`, an instance's scope: quitting skips that instance until the handoff
     * settles. Rejects without running the handoff when no instance has that scope.
     */
    restart(keep: Scope, handoff: () => Promise<void>) {
      if (![...active.values()].some((running) => running.instance.scope === keep))
        return Promise.reject(new Error("Lifecycle.restart keeps only an active extension's ctx.scope"))
      kept.add(keep)

      return Promise.resolve()
        .then(handoff)
        .finally(() => kept.delete(keep))
    },
    /** Stops every extension but a kept one; settles once each lifecycle has. */
    async dispose() {
      status.quitting = true
      // Every other extension with an instance or a queued step stops; quitting waits for each lifecycle to settle.
      await Promise.all(
        [...new Set([...active.keys(), ...queues.keys()])].flatMap((id) => {
          const running = active.get(id)

          return running && kept.has(running.instance.scope) ? [] : [deactivate(id)]
        }),
      )
    },
  }
}

/**
 * The promise's value, or undefined as soon as the signal aborts; the promise itself keeps running. Once the promise
 * settled, a later abort changes nothing: a reload aborts the generation of an instance it keeps.
 */
function until<T>(signal: AbortSignal, promise: Promise<T>) {
  if (signal.aborted) return Promise.resolve(undefined)

  return new Promise<T | undefined>((resolve, reject) => {
    const abort = () => resolve(undefined)
    signal.addEventListener("abort", abort, { once: true })
    void promise.then(resolve, reject).finally(() => signal.removeEventListener("abort", abort))
  })
}

/** Waits for the promise until the cleanup deadline, then reports and stops waiting. */
function within(promise: Promise<void>, timedOut: () => void) {
  const deadline = Promise.withResolvers<void>()

  const timer = setTimeout(() => {
    timedOut()
    deadline.resolve()
  }, CLEANUP_TIMEOUT_MS)

  return Promise.race([promise, deadline.promise]).finally(() => clearTimeout(timer))
}

import { expect, test } from "bun:test"
import { extensionEnabled } from "@opencode/gui-extensions/sdk/bridge"
import details from "../../../../gui-extensions/src/details/index"
import context from "../../../../gui-extensions/src/context/index"
import { openDatabase } from "../storage/database"
import { extension } from "../storage/schema"
import { readEnableState } from "./enable-state"
import { createManager } from "./manager"

test.each([
  { name: "no setting", rows: [], expected: true },
  { name: "an old disabled setting", rows: [{ id: "older", enabled: false }], expected: false },
  { name: "an old enabled setting", rows: [{ id: "older", enabled: true }], expected: true },
  {
    name: "the newest old setting",
    rows: [{ id: "older", enabled: false }, { id: "previous", enabled: true }],
    expected: true,
  },
  {
    name: "the current enabled setting",
    rows: [{ id: "previous", enabled: false }, { id: "current", enabled: true }],
    expected: true,
  },
  {
    name: "the current disabled setting",
    rows: [{ id: "previous", enabled: true }, { id: "current", enabled: false }],
    expected: false,
  },
])("both hosts resolve $name from real database rows, and a new setting wins", (input) => {
  const database = openDatabase(":memory:")
  const definition = { id: "current", legacy: ["previous", "older"] }
  const manager = createManager(database.db, () => false, [definition])
  input.rows.forEach((row) => database.db.insert(extension).values(row).run())

  expect(manager.enabled(definition.id)).toBe(input.expected)
  expect(extensionEnabled(definition, readEnableState(database.db.$client))).toBe(input.expected)

  const before = database.db.select().from(extension).all()

  manager.setEnabled(definition.id, !input.expected)
  expect(manager.enabled(definition.id)).toBe(!input.expected)
  expect(extensionEnabled(definition, readEnableState(database.db.$client))).toBe(!input.expected)
  expect(database.db.select().from(extension).all().filter((row) => row.id !== definition.id)).toEqual(
    before.filter((row) => row.id !== definition.id),
  )
  database.close()
})

test.each([details, context])("$id preserves disabled state from its shipping legacy declaration", (definition) => {
