import { randomUUID } from "node:crypto"
import { and, eq, isNotNull } from "drizzle-orm"
import { Option, Predicate } from "effect"
import type { Definition } from "@opencode/gui-extensions/sdk/main"
import { extensionEnabled } from "@opencode/gui-extensions/sdk/bridge"
import type { Database } from "../storage/database"
import { extension, extensionFile } from "../storage/schema"
import { ExtensionError } from "./error"
import { decodeManifest } from "./manifest"
import { readEnableState } from "./enable-state"

/**
 * Enable state and installed archives, committed together in the desktop database. Archive installs are groundwork for
 * `.ocdx` extensions: an installed archive runs its main entry only, the renderer loads built-ins until that format
 * ships renderer bundles, and packaged builds refuse the manager until installs have a trust model.
 */
export function createManager(db: Database, reserved: (id: string) => boolean, definitions: readonly Definition[]) {
  return {
    /** Every installed archive. A manifest that no longer decodes is reported, not dropped. */
    installed() {
      return db
        .select()
        .from(extension)
        .where(isNotNull(extension.manifest))
        .all()
        .map((item) => ({
          id: item.id,
          enabled: item.enabled,
          revision: item.revision ?? undefined,
          manifest: Option.getOrUndefined(decodeManifest(item.manifest)),
        }))
    },
    /** The current id wins, then declared legacy ids newest first; no setting means enabled. */
    enabled(id: string) {
      return extensionEnabled(
        definitions.find((definition) => definition.id === id) ?? { id },
        readEnableState(db.$client),
      )
    },
    setEnabled(id: string, enabled: boolean) {
      db.insert(extension).values({ id, enabled }).onConflictDoUpdate({ target: extension.id, set: { enabled } }).run()
    },
    /** A new revision tells renderers to reload the extension's code and assets. */
    bump(id: string) {
      db.update(extension).set({ revision: randomUUID() }).where(eq(extension.id, id)).run()
    },
    file(id: string, path: string) {
      return db
        .select({ data: extensionFile.data })
        .from(extensionFile)
        .where(and(eq(extensionFile.extension_id, id), eq(extensionFile.path, path)))
        .get()?.data
    },
    async install(source: Uint8Array | string) {
      const { readArchive } = await import("./archive")
      const archive = await readArchive(Predicate.isString(source) ? await download(source) : source)
      const id = archive.manifest.id

      if (reserved(id)) throw new ExtensionError("reserved")

      const values = { enabled: true, manifest: JSON.stringify(archive.manifest), revision: randomUUID() }
      db.transaction((tx) => {
        tx.delete(extensionFile).where(eq(extensionFile.extension_id, id)).run()
        tx.insert(extension)
          .values({ id, ...values })
          .onConflictDoUpdate({ target: extension.id, set: values })
          .run()
        archive.files.forEach((file) =>
          tx.insert(extensionFile).values({ extension_id: id, path: file.path, data: file.data }).run(),
        )
      })

      return archive.manifest
    },
    remove(id: string) {
      db.transaction((tx) => {
        tx.delete(extensionFile).where(eq(extensionFile.extension_id, id)).run()
        tx.delete(extension).where(eq(extension.id, id)).run()
      })
    },
  }
}

async function download(url: string) {
  const { archiveLimit } = await import("./archive")

  if (!URL.canParse(url) || !["http:", "https:"].includes(new URL(url).protocol)) throw new ExtensionError("url")

  const { net } = await import("electron")

  const response = await net.fetch(url).catch((error) => {
    throw new ExtensionError("download", { cause: error })
  })

  if (!response.ok || !response.body) throw new ExtensionError("download", { message: String(response.status) })

  if (Number(response.headers.get("content-length")) > archiveLimit) {
    await response.body.cancel()

    throw new ExtensionError("tooLarge")
  }

  const reader = response.body.getReader()
  const chunks: Uint8Array[] = []

  const pump = async (size: number): Promise<number> => {
    const next = await reader.read()

    if (next.done) return size

    if (size + next.value.byteLength > archiveLimit) {
      await reader.cancel()

      throw new ExtensionError("tooLarge")
    }

    chunks.push(next.value)

    return pump(size + next.value.byteLength)
  }

  await pump(0)

  return Buffer.concat(chunks)
}

import { Schema } from "effect"
import { ExtensionError } from "./error"

const text = (maximum: number) => Schema.String.check(Schema.isMinLength(1), Schema.isMaxLength(maximum))

const path = text(1_024)

/** `manifest.json` at the root of an installed extension archive. */
export const Manifest = Schema.Struct({
  schema: Schema.Literal("opencode.gui-extension/1"),
  id: text(128).check(Schema.isPattern(/^[a-z0-9][a-z0-9._-]*$/)),
  name: text(256),
  version: text(128),
  /** CommonJS bundle the renderer host evaluates. */
  renderer: path,
  /** CommonJS bundle the main host evaluates; it exports `default` (the setup) and optionally `i18n`. */
  main: Schema.optionalKey(path),
  style: Schema.optionalKey(path),
  /** Modules each bundle may `require`; the hosts supply them. */
  imports: Schema.Struct({
    renderer: Schema.Array(Schema.String),
    main: Schema.optionalKey(Schema.Array(Schema.String)),
  }),
})

export type Manifest = typeof Manifest.Type

export const decodeManifest = Schema.decodeUnknownOption(Schema.fromJsonString(Manifest))

/** Archive paths are relative, slash-separated, and never climb out of the archive. */
export function archivePath(value: string) {
  if (
    !value ||
    value.includes("\\") ||
    value.includes(":") ||
    /[\u0000-\u001f]/.test(value) ||
    value.startsWith("/") ||
    value.split("/").some((part) => !part || part === "." || part === "..")
  )
    throw new ExtensionError("invalidPath")

  return value
}

import { createRequire, isBuiltin } from "node:module"
import type { MainSetup } from "@opencode/gui-extensions/sdk/main"
import { Option, Predicate, Schema } from "effect"
import { ExtensionError } from "./error"

const native = createRequire(import.meta.url)

// Installed bundles share the host's module instances, so tokens and schemas they import are the
// same objects the host checks against.
const shared = new Map<string, () => Promise<object>>([
  ["effect", () => import("effect")],
  ["@opencode/gui-extensions/sdk/main", () => import("@opencode/gui-extensions/sdk/main")],
  ["@opencode/schema/rpc", () => import("@opencode/schema/rpc")],
  ["@opencode/client", () => import("@opencode/client")],
  ["@opencode/client/effect", () => import("@opencode/client/effect")],
])

// Installed catalogs ship every locale inline; only built-ins load locales lazily.
const InlineCatalog = Schema.Record(Schema.String, Schema.Record(Schema.String, Schema.String))

/** The CommonJS module an installed main bundle fills: its setup and, optionally, its catalog. */
type Module = { exports: { default?: object; i18n?: object } }

export function mainImportAllowed(name: string) {
  return name === "electron" || isBuiltin(name) || shared.has(name)
}

/** Evaluates an installed extension's main bundle as CommonJS against the shared module map. */
export async function evaluateMain(source: string, imports: readonly string[]) {
  const modules = new Map(
    await Promise.all(
      imports.map(async (name) => {
        if (name === "electron" || isBuiltin(name)) return [name, native(name)] as const
        const load = shared.get(name)

        if (!load) throw new ExtensionError("invalidModule", { message: name })

        return [name, await load()] as const
      }),
    ),
  )

  const module: Module = { exports: {} }

  // Installed extensions are trusted code the user chose to install.
  new Function("require", "module", "exports", source)(
    (name: string) => {
      if (!modules.has(name)) throw new ExtensionError("invalidModule", { message: name })

      return modules.get(name)
    },
    module,
    module.exports,
  )
  const setup = module.exports.default
  const i18n = module.exports.i18n

  if (!Predicate.isFunction(setup)) throw new ExtensionError("invalidModule")
  const catalog = i18n === undefined ? undefined : Schema.decodeUnknownOption(InlineCatalog)(i18n)

  if (catalog && Option.isNone(catalog)) throw new ExtensionError("invalidModule", { message: "i18n" })

  // SAFETY: a bundle is plain JavaScript; a function default export is its setup, all the host can check of it.
  return { setup: setup as MainSetup, i18n: catalog && { en: {}, ...catalog.value } }
}

import { afterEach, describe, expect, test } from "bun:test"
import { mkdtemp, rm } from "node:fs/promises"
import { tmpdir } from "node:os"
import path from "node:path"
import type { MainStoreFrom } from "@opencode/gui-extensions/sdk/main"
import { Schema } from "effect"
import { openDatabase, type Database } from "../storage/database"
import { createStateStore, type StateStore } from "../storage/state"
import { createSettingsStore, type SettingsStore } from "../storage/store"
import { createStorage, type SettingsFiles } from "./storage"

const roots: string[] = []

// Bun's node:sqlite shim pins the WAL files on Windows after close(); tolerate the leftover here only.
afterEach(() =>
  Promise.all(roots.splice(0).map((root) => rm(root, { recursive: true, force: true }).catch(() => undefined))),
)

const directory = async () => {
  const root = await mkdtemp(path.join(tmpdir(), "opencode-extension-storage-"))
  roots.push(root)

  return root
}

/** The desktop's settings files in `root`, one store per file as the app keeps them. */
const settingsIn = (root: string): SettingsFiles => {
  const files = new Map<string, SettingsStore>()

  return (file = "opencode.settings") => {
    const existing = files.get(file)

    if (existing) return existing
    const created = createSettingsStore(path.join(root, file))
    files.set(file, created)

    return created
  }
}

const open = (db: Database, settings: SettingsFiles) => {
  const storage = createStorage(createStateStore(db), settings, "example")

  return {
    storage,
    store: storage.store("servers", { schema: Schema.Array(Schema.String), initial: [] }),
  }
}

/** Where the built-ins kept their main state before `from`: settings files, and pairing's state namespace row. */
type Seed = {
  readonly settings?: readonly { readonly file: string; readonly key: string; readonly value: object }[]
  readonly state?: string
}

describe("main extension storage", () => {
  // A crash right after saving keeps the value: another connection reads it without any flush.
  test.each([
    {
      name: "update",
      write: (opened: ReturnType<typeof open>) =>
        opened.store.update((draft) => {
          draft.push("a")
        }),
      expected: ["a"],
    },
    {
      // The open store holds what was stored, not the caller's list, which changes afterwards.
      name: "set copies a list",
      write: (opened: ReturnType<typeof open>) => {
        const list = ["a"]

        opened.store.set(list)
        list.push("b")
      },
      expected: ["a"],
    },
    {
      name: "remove",
      write: (opened: ReturnType<typeof open>) => {
        opened.store.set(["a"])
        opened.storage.remove("servers")
      },
      expected: [],
    },
    {
      // Every store opened on a key reads one value: this one read before another store on the key wrote.
      name: "an update through another store on the key",
      write: (opened: ReturnType<typeof open>) => {
        expect(opened.store.value).toEqual([])
        opened.storage.store("servers", { schema: Schema.Array(Schema.String), initial: [] }).set(["a"])
      },
      expected: ["a"],
    },
    {
      name: "update rejects a returned replacement",
      write: (opened: ReturnType<typeof open>) =>
        expect(() => {
          // @ts-expect-error JavaScript extensions can still return a replacement at runtime
          opened.store.update(() => ["wrong"])
        }).toThrow("Use set"),
      expected: [],
    },
    {
      name: "set and update retain call order",
      write: (opened: ReturnType<typeof open>) => {
        opened.store.update((draft) => {
          draft.push("before")
        })
        opened.store.set(["replaced"])
        opened.store.update((draft) => {
          draft.push("after")
        })
      },
      expected: ["replaced", "after"],
    },
  ])("$name reaches the database before it returns, and the open store reads it", async (row) => {
    const root = await directory()
    const file = path.join(root, "drafts.sqlite")
    const writer = openDatabase(file)
    const reader = openDatabase(file)
    const settings = settingsIn(root)
    const opened = open(writer.db, settings)
    row.write(opened)
    expect({
      stored: open(reader.db, settings).store.value,
      open: opened.store.value,
      ready: opened.store.ready(),
    }).toEqual({
      stored: row.expected,
      open: row.expected,
      ready: true,
    })
    writer.close()
    reader.close()
  })

  test.each([7, null])("set persists the primitive %p immediately", async (next) => {
    const root = await directory()
    const file = path.join(root, "state.sqlite")
    const writer = openDatabase(file)
    const reader = openDatabase(file)
    const settings = settingsIn(root)
    const options = { schema: Schema.NullOr(Schema.Finite), initial: 0 }
    const store = createStorage(createStateStore(writer.db), settings, "example").store("value", options)
    store.set(next)

    expect(createStorage(createStateStore(reader.db), settings, "example").store("value", options).value).toBe(next)
    writer.close()
    reader.close()
  })

  // The built-ins moved their main state into declared stores: each older home imports into the same row, byte for
  // byte (an unknown field included), and `remove` with the same `from` deletes every home it names.
  test.each<{ name: string; from: MainStoreFrom | readonly MainStoreFrom[]; seed: Seed; id: string; row: string }>([
    {
      name: "a key of the app's settings file",
      from: { settings: "ssh.servers" },
      seed: { settings: [{ file: "opencode.settings", key: "ssh.servers", value: [{ id: "a", kept: 1 }] }] },
      id: "a",
      row: '[{"id":"a","kept":1}]',
    },
    {
      name: "a key of another settings file",
      from: { settings: "ready", file: "opencode.updater" },
      seed: { settings: [{ file: "opencode.updater", key: "ready", value: [{ id: "u" }] }] },
      id: "u",
      row: '[{"id":"u"}]',
    },
    {
      name: "a key of another state namespace",
      from: { state: ["opencode.settings", "keepScreenActive"] },
      seed: { state: '[{"id":"s"}]' },
      id: "s",
      row: '[{"id":"s"}]',
    },
    {
      name: "the newest home of a list that holds a value",
      from: [{ state: ["opencode.settings", "keepScreenActive"] }, { settings: "ssh.servers" }],
      seed: { settings: [{ file: "opencode.settings", key: "ssh.servers", value: [{ id: "older" }] }] },
      id: "older",
      row: '[{"id":"older"}]',
    },
    {
      name: "the next home of a list when the first holds a value the schema rejects",
      from: [{ state: ["opencode.settings", "keepScreenActive"] }, { settings: "ssh.servers" }],
      seed: {
        state: '"off"',
        settings: [{ file: "opencode.settings", key: "ssh.servers", value: [{ id: "older" }] }],
      },
      id: "older",
      row: '[{"id":"older"}]',
    },
    {
      name: "the first home of a list when several hold a value",
      from: [{ state: ["opencode.settings", "keepScreenActive"] }, { settings: "ssh.servers" }],
      seed: {
        state: '[{"id":"newer"}]',
        settings: [{ file: "opencode.settings", key: "ssh.servers", value: [{ id: "older" }] }],
      },
      id: "newer",
      row: '[{"id":"newer"}]',
    },
  ])("imports $name once, and remove forgets every home", async (input) => {
    const root = await directory()
    const database = openDatabase(path.join(root, "state.sqlite"))
    const state = createStateStore(database.db)
    const settings = settingsIn(root)

    input.seed.settings?.forEach((item) => settings(item.file).set(item.key, item.value))

    if (input.seed.state) state.set("opencode.settings", "keepScreenActive", input.seed.state)

    const storage = createStorage(state, settings, "example")
    const schema = Schema.Array(Schema.Struct({ id: Schema.String }))
    const store = storage.store("servers", { schema, initial: [], from: input.from })
    const imported = { value: store.value.map((item) => item.id), row: state.get("extension.example", "servers") }

    storage.remove("servers", { from: input.from })

    expect({ ...imported, left: homes(state, settings) }).toEqual({ value: [input.id], row: input.row, left: [] })
    database.close()
  })
})

/** Every older home the table seeds that still holds a value. */
function homes(state: StateStore, settings: SettingsFiles) {
  return [
    state.get("opencode.settings", "keepScreenActive"),
    settings().get("ssh.servers"),
    settings("opencode.updater").get("ready"),
  ].filter((value) => value !== null && value !== undefined)
}

import type { MainStoreFrom, Mutable, Storage } from "@opencode/gui-extensions/sdk/main"
import { Option, Schema } from "effect"
import type { StateStore } from "../storage/state"
import type { SettingsStore } from "../storage/store"

/**
 * One key as every store opened on it sees it: the stored JSON last read or written, so later reads skip the database.
 * Undefined until read; null while nothing is stored, including after `remove`, so each store reads its `initial`.
 */
type Shared = { json?: string | null }

/** One store's decoded copy of the shared JSON, decoded again when another store on the key writes. */
type Decoded<T> = { value?: { readonly json: string | null; readonly current: T } }

/** A desktop settings file by name; the app's own when the name is left out. */
export type SettingsFiles = (file?: string) => SettingsStore

/**
 * Each extension's values live in the `state` table under `extension.<id>`, stored as canonical JSON. Writes are rare,
 * so each one reaches the database before it returns and survives a crash. A `from` imports an older value once from
 * a settings file or another state namespace.
 */
export function createStorage(state: StateStore, settings: SettingsFiles, id: string): Storage {
  const name = namespace(id)
  // Every store opened on a key shares its entry, so a write through one is what the others read.
  const keys = new Map<string, Shared>()

  const shared = (key: string) => {
    const existing = keys.get(key)

    if (existing) return existing
    const created: Shared = {}
    keys.set(key, created)

    return created
  }

  const sources = (from: MainStoreFrom | readonly MainStoreFrom[] | undefined) =>
    [from ?? []].flat().map((item) => source(state, settings, item))

  const remove = (key: string, from: MainStoreFrom | readonly MainStoreFrom[] | undefined) => {
    // The old copies go too, or the next read would import one again.
    sources(from).forEach((older) => older.remove())

    if (state.get(name, key) !== null) state.delete(name, key)
    state.flush()
    // The stores open on the key read their `initial` again.
    const entry = keys.get(key)

    if (entry) entry.json = null
  }

  return {
    store(key, options) {
      const codec = Schema.toCodecJson(options.schema)
      const legacy = sources(options.from)
      const entry = shared(key)
      const decoded: Decoded<typeof options.initial> = {}

      // The stored JSON, imported once from the newest older home that holds a value this store's schema accepts; the
      // old location keeps its copy for builds that still read it.
      const read = () => {
        const stored = state.get(name, key)

        if (stored !== null) return stored

        // Each home is read once; one whose value the schema rejects holds nothing for this store.
        const found = legacy.reduce<{ readonly value: unknown } | undefined>((match, older) => {
          if (match) return match
          const value = older.read()

          return value !== undefined && Option.isSome(Schema.decodeUnknownOption(codec)(value)) ? { value } : undefined
        }, undefined)

        if (!found) return null
        const json = JSON.stringify(found.value)
        state.set(name, key, json)

        return json
      }

      const current = () => {
        // Null is a known empty key, so only an unread one goes to the database.
        if (entry.json === undefined) entry.json = read()
        const json = entry.json
        const cached = decoded.value

        if (cached && cached.json === json) return cached.current
        const value = json === null ? Option.none() : Schema.decodeUnknownOption(Schema.fromJsonString(codec))(json)
        const next = { json, current: Option.getOrElse(value, () => options.initial) }
        decoded.value = next

        return next.current
      }

      // Keeps a decoded copy of what was stored, so the caller's object never aliases the stored value.
      const write = (value: typeof options.initial) => {
        const encoded = Schema.encodeSync(codec)(value)
        const json = JSON.stringify(encoded)

        state.set(name, key, json)
        state.flush()
        entry.json = json
        decoded.value = { json, current: Schema.decodeSync(codec)(encoded) }
      }

      return {
        get value() {
          return current()
        },
        ready: () => true,
        // The draft is a decoded copy, so mutation cannot touch the cache before the write. Schema readonly fields
        // are type-level only; the decoded JSON's objects and arrays are writable.
        update(mutate) {
          const draft = Schema.decodeSync(codec)(Schema.encodeSync(codec)(current()))
          // SAFETY: the codec above creates a writable copy of the stored JSON, including its nested fields.
          const returned = mutate(draft as Mutable<typeof options.initial>)

          if (returned !== undefined)
            throw new Error("Persisted.update must not return a value. Use set(next) to replace the value.")

          write(draft)
        },
        set: write,
      }
    },
    remove: (key, options) => remove(key, options?.from),
  }
}

export function namespace(id: string) {
  return `extension.${id}`
}

/** One older home: a key of a settings file, or of another state namespace. */
function source(state: StateStore, settings: SettingsFiles, from: MainStoreFrom) {
  if ("settings" in from) {
    const store = () => settings(from.file)

    return {
      read: () => store().get(from.settings),
      remove() {
        if (store().get(from.settings) !== undefined) store().delete(from.settings)
      },
    }
  }

  const [space, key] = from.state

  return {
    read() {
      const value = state.get(space, key)

      if (value === null) return undefined

      return Option.getOrUndefined(Schema.decodeUnknownOption(Schema.fromJsonString(Schema.Unknown))(value))
    },
    remove() {
      if (state.get(space, key) !== null) state.delete(space, key)
    },
  }
}

import { execFile } from "node:child_process"
import util from "node:util"
import { Effect, FileSystem, Path } from "effect"

const execFilePromise = util.promisify(execFile)

export const checkAppExists = Effect.fn("DesktopFiles.checkAppExists")(function* (appName: string) {
  if (process.platform === "win32") return true

  if (process.platform === "linux") return true

  return yield* checkMacosApp(appName)
})

export const resolveAppPath = Effect.fn("DesktopFiles.resolveAppPath")(function* (appName: string) {
  if (process.platform !== "win32") return appName

  return yield* resolveWindowsAppPath(appName)
})

const checkMacosApp = Effect.fn("DesktopFiles.checkMacosApp")(function* (appName: string) {
  const fs = yield* FileSystem.FileSystem
  const locations = [`/Applications/${appName}.app`, `/System/Applications/${appName}.app`]

  const home = process.env.HOME

  if (home) locations.push(`${home}/Applications/${appName}.app`)

  for (const location of locations) {
    if (yield* exists(fs, location)) return true
  }

  return yield* Effect.tryPromise(() => execFilePromise("which", [appName])).pipe(
    Effect.as(true),
    Effect.orElseSucceed(() => false),
  )
})

const resolveWindowsAppPath = Effect.fn("DesktopFiles.resolveWindowsAppPath")(function* (appName: string) {
  const fs = yield* FileSystem.FileSystem
  const path = yield* Path.Path

  const result = yield* Effect.tryPromise(() => execFilePromise("where", [appName], { windowsHide: true })).pipe(
    Effect.orElseSucceed(() => undefined),
  )

  if (!result) return null

  const paths = result.stdout
    .toString()
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0)

  const hasExt = (value: string, ext: string) => path.extname(value).toLowerCase() === `.${ext}`

  const exe = paths.find((path) => hasExt(path, "exe"))

  if (exe) return exe

  const resolveCmd = Effect.fnUntraced(function* (file: string) {
    const content = yield* fs.readFileString(file)

    for (const token of content.split('"').map((value: string) => value.trim())) {
      const lower = token.toLowerCase()

      if (!lower.includes(".exe")) continue

      const index = lower.indexOf("%~dp0")

      if (index >= 0) {
        const base = path.dirname(file)
        const suffix = token.slice(index + 5)

        const resolved = suffix
          .replace(/\//g, "\\")
          .split("\\")
          .filter((part: string) => part && part !== ".")
          .reduce((current: string, part: string) => {
            if (part === "..") return path.dirname(current)

            return path.join(current, part)
          }, base)

        if (yield* exists(fs, resolved)) return resolved
      }

      if (yield* exists(fs, token)) return token
    }

    return null
  })

  for (const file of paths) {
    if (hasExt(file, "cmd") || hasExt(file, "bat")) {
      const resolved = yield* resolveCmd(file)

      if (resolved) return resolved
    }

    if (!path.extname(file)) {
      const cmd = `${file}.cmd`

      if (yield* exists(fs, cmd)) {
        const resolved = yield* resolveCmd(cmd)

        if (resolved) return resolved
      }

      const bat = `${file}.bat`

      if (yield* exists(fs, bat)) {
        const resolved = yield* resolveCmd(bat)

        if (resolved) return resolved
      }
    }
  }

  const key = appName
    .split("")
    .filter((value: string) => /[a-z0-9]/i.test(value))
    .map((value: string) => value.toLowerCase())
    .join("")

  if (key) {
    for (const file of paths) {
      const dirs = [path.dirname(file), path.dirname(path.dirname(file)), path.dirname(path.dirname(path.dirname(file)))]

      for (const dir of dirs) {
        const entries = yield* fs.readDirectory(dir).pipe(Effect.orElseSucceed(() => []))

        for (const entry of entries) {
          const candidate = path.join(dir, entry)

          if (!hasExt(candidate, "exe")) continue
          const stem = entry.replace(/\.exe$/i, "")

          const name = stem
            .split("")
            .filter((value: string) => /[a-z0-9]/i.test(value))
            .map((value: string) => value.toLowerCase())
            .join("")

          if (name.includes(key) || key.includes(name)) return candidate
        }
      }
    }
  }

  return paths[0] ?? null
})

function exists(fs: FileSystem.FileSystem, path: string) {
  return fs.exists(path).pipe(Effect.orElseSucceed(() => false))
}

import { describe, expect, test } from "bun:test"
import { NodeFileSystem } from "@effect/platform-node"
import { mkdtemp, rm, truncate, writeFile } from "node:fs/promises"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { Effect, FileSystem } from "effect"
import {
  assertAttachmentBudget,
  createPickedFileAuthorizations,
  MAX_ATTACHMENT_BYTES,
  readAttachment,
} from "./attachment-picker"

const run = <A, E>(effect: Effect.Effect<A, E, FileSystem.FileSystem>) =>
  Effect.runPromise(effect.pipe(Effect.provide(NodeFileSystem.layer)))

describe("attachment size limit", () => {
  test("rejects the selection before files are read when its total exceeds the limit", () => {
    expect(() =>
      assertAttachmentBudget([{ size: MAX_ATTACHMENT_BYTES / 2 }, { size: MAX_ATTACHMENT_BYTES / 2 }]),
    ).not.toThrow()
    expect(() => assertAttachmentBudget([{ size: MAX_ATTACHMENT_BYTES }, { size: 1 }])).toThrow("20 MB limit")
  })

  test("reads an approved file and rejects an oversized one before allocating its contents", async () => {
    const directory = await mkdtemp(join(tmpdir(), "opencode-attachment-"))
    const file = join(directory, "example.txt")
    const oversized = join(directory, "oversized.txt")

    try {
      await writeFile(file, "lorem ipsum")
      expect(new TextDecoder().decode(await run(readAttachment(file)))).toBe("lorem ipsum")
      await writeFile(oversized, "")
      await truncate(oversized, MAX_ATTACHMENT_BYTES + 1)
      await expect(run(readAttachment(oversized))).rejects.toThrow("20 MB limit")
    } finally {
      await rm(directory, { recursive: true, force: true })
    }
  })
})

describe("picked file authorizations", () => {
  const read = (path: string) => Effect.sync(() => new TextEncoder().encode(path).buffer)

  test("keeps concurrent picker selections isolated", async () => {
    const authorizations = createPickedFileAuthorizations(read)
    const first = authorizations.add(1, ["a.txt", "b.txt"])
    const second = authorizations.add(1, ["c.txt"])

    expect(new TextDecoder().decode(await run(authorizations.read(1, first, "a.txt")))).toBe("a.txt")
    expect(new TextDecoder().decode(await run(authorizations.read(1, second, "c.txt")))).toBe("c.txt")
    expect(new TextDecoder().decode(await run(authorizations.read(1, first, "b.txt")))).toBe("b.txt")
  })

  test("releases unread files for one picker without affecting another", async () => {
    const authorizations = createPickedFileAuthorizations(read)
    const first = authorizations.add(1, ["a.txt"])
    const second = authorizations.add(1, ["b.txt"])
    authorizations.release(1, first)

    await expect(run(authorizations.read(1, first, "a.txt"))).rejects.toThrow("not selected")
    expect(new TextDecoder().decode(await run(authorizations.read(1, second, "b.txt")))).toBe("b.txt")
  })

  test("keeps picker tokens scoped to their renderer", async () => {
    const authorizations = createPickedFileAuthorizations(read)
    const token = authorizations.add(1, ["a.txt"])

    await expect(run(authorizations.read(2, token, "a.txt"))).rejects.toThrow("not selected")
  })

  test("charges actual reads against the selection budget", async () => {
    const size = MAX_ATTACHMENT_BYTES / 2 + 1

    const authorizations = createPickedFileAuthorizations((_path, maxBytes) =>
      Effect.sync(() => {
        if (maxBytes < size) throw new Error("budget exceeded")

        return new ArrayBuffer(size)
      }),
    )

    const token = authorizations.add(1, ["a.txt", "b.txt"])

    await run(authorizations.read(1, token, "a.txt"))
    await expect(run(authorizations.read(1, token, "b.txt"))).rejects.toThrow("budget exceeded")
  })
})

import { randomUUID } from "node:crypto"
import { ByteSize, Effect, FileSystem } from "effect"
import { nativeT } from "../native/translations"

export const MAX_ATTACHMENT_BYTES = 20 * 1024 * 1024

export function createPickedFileAuthorizations(
  read: (path: string, maxBytes: number) => Effect.Effect<ArrayBuffer, unknown>,
) {
  const selections = new Map<string, { sender: number; paths: Set<string>; remaining: number }>()

  return {
    add(sender: number, paths: string[]) {
      const token = randomUUID()
      selections.set(token, { sender, paths: new Set(paths), remaining: MAX_ATTACHMENT_BYTES })

      return token
    },
    read: Effect.fn("DesktopFiles.readPickedFile")(function* (sender: number, token: string, path: string) {
      const selection = selections.get(token)

      if (selection?.sender !== sender || !selection.paths.delete(path))
        throw new Error(nativeT("desktop.picker.error.notSelected"))
      const bytes = yield* read(path, selection.remaining)
      selection.remaining -= bytes.byteLength

      if (selection.paths.size === 0) selections.delete(token)

      return bytes
    }),
    release(sender: number, token: string) {
      if (selections.get(token)?.sender === sender) selections.delete(token)
    },
  }
}

export function assertAttachmentBudget(files: { size: number }[]) {
  const total = files.reduce((sum, file) => sum + file.size, 0)

  if (total <= MAX_ATTACHMENT_BYTES) return
  throw new Error(nativeT("desktop.picker.error.sizeLimit", { limit: MAX_ATTACHMENT_BYTES / 1024 / 1024 }))
}

export function readAttachment(filePath: string, maxBytes = MAX_ATTACHMENT_BYTES) {
  return Effect.scoped(
    Effect.gen(function* () {
      const fs = yield* FileSystem.FileSystem
      const file = yield* fs.open(filePath, { flag: "r" })
      const info = yield* file.stat

      if (info.size > ByteSize.bytes(maxBytes))
        throw new Error(nativeT("desktop.picker.error.sizeLimit", { limit: MAX_ATTACHMENT_BYTES / 1024 / 1024 }))

      const bytes = new Uint8Array(Number(info.size))
      let offset = 0

      while (offset < bytes.byteLength) {
        const read = Number(yield* file.read(bytes.subarray(offset)))

        if (read === 0) break
        offset += read
      }

      return bytes.buffer.slice(0, offset)
    }),
  )
}

import { describe, expect, test } from "bun:test"
import { resolve } from "node:path"
