import { describe, expect, test } from "bun:test"
import { EventEmitter } from "node:events"
import { MessageChannel } from "node:worker_threads"
import type { MessagePortMain, WebContents } from "electron"
import { Effect, Layer, ManagedRuntime, Predicate, Schema, Stream } from "effect"
import { Rpc, RpcGroup, RpcMessage, RpcServer } from "effect/rpc"
import { Transferable } from "effect/workers"
import { omitUndefined } from "../shared/ipc-transport"
import { FilesOpenFilePicker } from "../shared/ipc-rpc/files"
import { IpcPortHandoff, IpcServerProtocolLive } from "./ipc-transport"

describe("desktop RPC transport", () => {
  test("decodes renderer payloads whose optional fields are undefined", async () => {
    let received: unknown
    const rpcs = RpcGroup.make(FilesOpenFilePicker)

    const handlers = rpcs.toLayer({
      FilesOpenFilePicker: ({ options }) =>
        Effect.sync(() => {
          received = options

          return null
        }),
    })

    const live = RpcServer.layer(rpcs).pipe(Layer.provide(handlers), Layer.provideMerge(IpcServerProtocolLive))
    const runtime = ManagedRuntime.make(live)
    const handoff = await runtime.runPromise(IpcPortHandoff)
    const channel = new MessageChannel()
    handoff.bind(sender(1), serverPort(channel.port1))
    // What openAttachmentPickerDialog sends for the composer's attach button.
    const payload = { options: { multiple: true, title: undefined, defaultPath: "C:\\project", extensions: undefined } }

    // Structured clone keeps a present-but-undefined key, so it reaches the JSON codec.
    const rejected = await call(channel.port2, 0, "FilesOpenFilePicker", payload)
    expect(rejected.exit).toMatchObject(died(expect.stringContaining('["options"]["title"]')))

    const accepted = await call(channel.port2, 1, "FilesOpenFilePicker", omitUndefined(payload))
    expect(accepted.exit).toEqual(success(null))
    expect(received).toEqual({ multiple: true, defaultPath: "C:\\project" })

    channel.port2.close()
    await runtime.dispose()
  })

  test("omitting undefined fields leaves bytes and defined values alone", () => {
    const data = new Uint8Array([0, 255, 2])
    expect(omitUndefined(data)).toBe(data)
    // Strict equality: a kept `drop: undefined` key must fail the match.
    expect(omitUndefined({ data, nested: [{ keep: null, drop: undefined }], count: 0 })).toStrictEqual({
      data,
      nested: [{ keep: null }],
      count: 0,
    })
  })

  test("keeps multiple renderer ports independent", async () => {
    let received: unknown

    const handlers = TestRpcs.toLayer(
      Effect.gen(function* () {
        const handoff = yield* IpcPortHandoff

        return TestRpcs.of({
          "test.focused": (_request, context) => Effect.succeed(handoff.sender(context.client.id)?.id === 1),
          "test.blob.put": ({ data }) => {
            received = data

            return Effect.succeed([...data].join(","))
          },
          "test.blob.get": () => Effect.succeed(new Uint8Array([3, 1, 4])),
          "test.events": () => Stream.make(new TestEvent({ value: "session.new" })),
        })
      }),
    )

    const live = RpcServer.layer(TestRpcs).pipe(Layer.provide(handlers), Layer.provideMerge(IpcServerProtocolLive))
    const runtime = ManagedRuntime.make(live)
    const handoff = await runtime.runPromise(IpcPortHandoff)
    const first = new MessageChannel()
    const second = new MessageChannel()
    handoff.bind(sender(1), serverPort(first.port1))
    handoff.bind(sender(2), serverPort(second.port1))

    const [focused, unfocused] = await Promise.all([
      call(first.port2, 0, "test.focused", null),
      call(second.port2, 0, "test.focused", null),
    ])

    expect(focused.exit).toEqual(success(true))
    expect(unfocused.exit).toEqual(success(false))
    const put = await call(first.port2, 1, "test.blob.put", omitUndefined({ data: new Uint8Array([2, 7, 1]) }))
    expect(put.exit).toEqual(success("2,7,1"))
    // Binary payloads arrive as bytes, not as base64 text or a plain object.
    expect(received).toBeInstanceOf(Uint8Array)
    expect((await call(first.port2, 2, "test.blob.get", null)).exit).toEqual(success(new Uint8Array([3, 1, 4])))
    expect((await call(first.port2, 3, "test.events", null)).chunks).toEqual([
      Schema.encodeSync(TestEvent)(new TestEvent({ value: "session.new" })),
    ])

    const reloaded = new MessageChannel()
    handoff.bind(sender(1), serverPort(reloaded.port1))

    const [reloadedFocused, stillUnfocused] = await Promise.all([
      call(reloaded.port2, 0, "test.focused", null),
      call(second.port2, 1, "test.focused", null),
    ])

    expect(reloadedFocused.exit).toEqual(success(true))
    expect(stillUnfocused.exit).toEqual(success(false))

    for (const port of [first.port2, second.port2, reloaded.port2]) port.close()
    await runtime.dispose()
  })
})

class TestEvent extends Schema.TaggedClass<TestEvent>()("TestEvent", { value: Schema.String }) {}

const TestRpcs = RpcGroup.make(
  Rpc.make("test.focused", { success: Schema.Boolean }),
  Rpc.make("test.blob.put", { payload: { data: Transferable.Uint8Array }, success: Schema.String }),
  Rpc.make("test.blob.get", { success: Transferable.Uint8Array }),
  Rpc.make("test.events", { success: TestEvent, stream: true }),
)

// SAFETY: these are the RPC wire format's plain encoded messages and exits, which the tests post and expect as is.
/* oxlint-disable anti-slop-effect/no-manual-tagged-construction -- see SAFETY above */
function success<A>(value: A) {
  return { _tag: "Success", value } as const
}

function died<A>(defect: A) {
  return { _tag: "Failure", cause: [{ _tag: "Die", defect }] } as const
}

// Speaks the wire format the way src/renderer/ipc-client.ts does: post a request, ack each chunk,
// and settle on the exit. The payload is posted as given so a test can send what omitUndefined drops.
function call(port: MessageChannel["port2"], id: number, tag: string, payload: RpcMessage.RequestEncoded["payload"]) {
  const chunks: unknown[] = []

  return new Promise<{ chunks: unknown[]; exit: RpcMessage.ResponseExitEncoded["exit"] }>((resolve) => {
    const onMessage = (message: RpcMessage.FromServerEncoded) => {
      if (!("requestId" in message) || Number(message.requestId) !== id) return

      if (Predicate.isTagged(message, "Chunk")) {
        chunks.push(...message.values)
        port.postMessage({ _tag: "Ack", requestId: message.requestId } satisfies RpcMessage.AckEncoded)

        return
      }

      port.off("message", onMessage)
      resolve({ chunks, exit: message.exit })
    }

    port.on("message", onMessage)
    port.postMessage({ _tag: "Request", id, tag, payload, headers: [] })
  })
}
/* oxlint-enable anti-slop-effect/no-manual-tagged-construction */

function sender(id: number) {
  const events = new EventEmitter()

  // SAFETY: the transport reads only a sender's `id` and `isDestroyed`, and its `destroyed` event.
  // oxlint-disable-next-line anti-slop/no-chained-type-assertions -- see SAFETY above
  return {
    id,
    isDestroyed: () => false,
    once: events.once.bind(events),
    off: events.off.bind(events),
  } as unknown as WebContents
}

function serverPort(port: MessageChannel["port1"]) {
  const listeners = new Map<(event: Electron.MessageEvent) => void, (data: Electron.MessageEvent["data"]) => void>()

  const fake = {
    on(event: string, listener: (event: Electron.MessageEvent) => void) {
      if (event !== "message") {
        port.on(event, listener)

        return
      }

      // SAFETY: the transport reads only the `data` of a message event.
      const wrapped = (data: Electron.MessageEvent["data"]) => listener({ data } as Electron.MessageEvent)
      listeners.set(listener, wrapped)
      port.on("message", wrapped)
    },
    off(event: string, listener: (event: Electron.MessageEvent) => void) {
      if (event !== "message") {
        port.off(event, listener)

        return
      }

      const wrapped = listeners.get(listener)

      if (wrapped) port.off("message", wrapped)
    },
    postMessage: port.postMessage.bind(port),
    start: port.start.bind(port),
    close: port.close.bind(port),
  }

  // SAFETY: the transport uses only these methods of a port.
  // oxlint-disable-next-line anti-slop/no-chained-type-assertions -- see SAFETY above
  return fake as unknown as MessagePortMain
}

import type { MessagePortMain, WebContents } from "electron"
import { Context, Effect, Layer, Option, Queue, Schema, Stream } from "effect"
import { RpcMessage, RpcServer } from "effect/rpc"
import { bindIpcEvents } from "./ipc-events"

type PortBinding = {
  readonly id: number
  readonly sender: WebContents
  readonly port: MessagePortMain
  readonly onMessage: (event: Electron.MessageEvent) => void
  readonly onClose: () => void
  readonly unbindEvents: Effect.Effect<void>
}

type Handoff = {
  readonly bind: (sender: WebContents, port: MessagePortMain) => void
  readonly sender: (clientId: number) => WebContents | undefined
}

export class IpcPortHandoff extends Context.Service<IpcPortHandoff, Handoff>()("opencode/desktop/IpcPortHandoff") {}

// Messages cross the port by structured clone, like Effect's worker protocol: no serialization
// layer, so binary payloads stay binary and nothing is packed into a shared buffer. Electron's
// MessagePortMain can only transfer ports, so byte payloads are cloned in both directions.
export const IpcServerProtocolLive = Layer.unwrap(
  Effect.gen(function* () {
    const handoffs = yield* Queue.unbounded<readonly [WebContents, MessagePortMain]>()
    const bindings = new Map<number, PortBinding>()
    const senderBindings = new Map<number, number>()

    const protocol = Layer.effect(
      RpcServer.Protocol,
      RpcServer.Protocol.make(
        Effect.fnUntraced(function* (writeRequest) {
          const disconnects = yield* Queue.unbounded<number>()
          const inbound = yield* Queue.unbounded<readonly [number, RpcMessage.FromClientEncoded]>()
          const runFork = Effect.runForkWith(yield* Effect.context())
          let nextClientId = 0

          const disconnect = Effect.fnUntraced(function* (id: number) {
            const binding = bindings.get(id)

            if (!binding) return
            bindings.delete(id)

            if (senderBindings.get(binding.sender.id) === id) senderBindings.delete(binding.sender.id)
            binding.port.off("message", binding.onMessage)
            binding.port.off("close", binding.onClose)
            binding.sender.off("destroyed", binding.onClose)
            yield* binding.unbindEvents
            binding.port.close()
            Queue.offerUnsafe(disconnects, id)
          })

          const bind = Effect.fnUntraced(function* (sender: WebContents, port: MessagePortMain) {
            const previous = senderBindings.get(sender.id)

            if (previous !== undefined) yield* disconnect(previous)

            if (sender.isDestroyed()) {
              port.close()

              return
            }

            const id = nextClientId++

            const onMessage = (event: Electron.MessageEvent) => {
              // SAFETY: the other end of this port is the renderer's ipc-client, which posts only RPC client
              // messages; the RPC server decodes each request's payload with that RPC's schema.
              Queue.offerUnsafe(inbound, [id, event.data as RpcMessage.FromClientEncoded] as const)
            }

            const onClose = () => runFork(disconnect(id))
            const unbindEvents = yield* bindIpcEvents(sender.id)
            const binding = { id, sender, port, onMessage, onClose, unbindEvents }
            bindings.set(id, binding)
            senderBindings.set(sender.id, id)
            port.on("message", onMessage)
            port.on("close", onClose)
            sender.once("destroyed", onClose)
            port.start()
          })

          yield* Stream.fromQueue(handoffs).pipe(
            Stream.runForEach(([sender, port]) => bind(sender, port)),
            Effect.forkScoped,
          )
          yield* Stream.fromQueue(inbound).pipe(
            Stream.runForEach(([id, message]) => (bindings.has(id) ? writeRequest(id, message) : Effect.void)),
            Effect.forkScoped,
          )
          yield* Effect.addFinalizer(() => Effect.forEach([...bindings.keys()], disconnect, { discard: true }))

          return {
            codecFor: Schema.toCodecJson,
            disconnects,
            send: (clientId, response) =>
              Effect.sync(() => {
                bindings.get(clientId)?.port.postMessage(response)
              }),
            end: disconnect,
            clientIds: Effect.sync(() => new Set(bindings.keys())),
            initialMessage: Effect.succeed(Option.none()),
            supportsAck: true,
            supportsTransferables: false,
            supportsSpanPropagation: false,
            supportsNotifications: true,
          }
        }),
      ),
    )

    return Layer.merge(
      protocol,
      Layer.succeed(IpcPortHandoff)({
        bind: (sender, port) => {
          Queue.offerUnsafe(handoffs, [sender, port])
        },
        sender: (clientId) => bindings.get(clientId)?.sender,
      }),
    )
  }),
)

export * as Ipc from "./ipc"

import { app, BrowserWindow, MessageChannelMain } from "electron"
import { Effect, Layer } from "effect"
import { RpcServer } from "effect/rpc"
import { DesktopRpcs } from "../shared/ipc-rpc"
import { DragCancelEvent, IpcTransportPort } from "../shared/ipc-transport"
import { Extensions } from "./extension"
import { DesktopFiles, openExternalURL } from "./files"
import { appHandlers } from "./ipc-handlers/app"
import { eventHandlers } from "./ipc-handlers/events"
import { extensionHandlers } from "./ipc-handlers/extensions"
import { fileHandlers } from "./ipc-handlers/files"
import { menuHandlers } from "./ipc-handlers/menu"
import { storageHandlers } from "./ipc-handlers/storage"
import { windowHandlers } from "./ipc-handlers/window"
import { IpcPortHandoff, IpcServerProtocolLive } from "./ipc-transport"
import { ApplicationLifecycle } from "./lifecycle"
import { showCliInstaller } from "./native/install-cli"
import { createMenu, sendMenuCommand } from "./native/menu"
import { DesktopCli } from "./service/desktop-cli"
import { getLastFocusedWindow } from "./windows"

const services = Layer.mergeAll(DesktopFiles.layer, Extensions.layer)

const handlers = Layer.mergeAll(
  appHandlers,
  storageHandlers,
  fileHandlers,
  windowHandlers,
  menuHandlers,
  eventHandlers,
  extensionHandlers,
)

export const layer = RpcServer.layer(DesktopRpcs, { disableFatalDefects: true }).pipe(
  Layer.provide(handlers),
  Layer.provideMerge(IpcServerProtocolLive),
  Layer.provideMerge(services),
)

export const registerIpcHandlers = Effect.gen(function* () {
  const handoff = yield* IpcPortHandoff
  const lifecycle = yield* ApplicationLifecycle.Service
  const desktopCli = yield* DesktopCli.Service
  const runFork = Effect.runForkWith(yield* Effect.context())

  const menu = {
    trigger: (id: string) => {
      const win = getLastFocusedWindow()

      if (win) sendMenuCommand(win, id)
    },
    installCli: () => runFork(showCliInstaller(desktopCli)),
    createWindow: lifecycle.createWindow,
    openExternal: (url: string) => runFork(openExternalURL(url)),
    relaunch: lifecycle.relaunch,
  }

  const wire = (win: BrowserWindow) => {
    win.webContents.on("before-input-event", (_event, input) => {
      if (input.type !== "keyDown" || input.key !== "Escape") return
      win.webContents.send(DragCancelEvent)
    })

    const post = () => {
      if (win.isDestroyed() || win.webContents.isDestroyed()) return
      const channel = new MessageChannelMain()
      handoff.bind(win.webContents, channel.port1)
      win.webContents.postMessage(IpcTransportPort, null, [channel.port2])
    }

    win.webContents.on("did-finish-load", post)

    // The first window starts loading before the layers exist and may already be done.
    if (!win.webContents.isLoading() && win.webContents.getURL()) post()
  }

  const onWindowCreated = (_event: Electron.Event, win: BrowserWindow) => wire(win)

  yield* Effect.sync(() => {
    app.on("browser-window-created", onWindowCreated)
    BrowserWindow.getAllWindows().forEach((win) => wire(win))
  })
  yield* Effect.addFinalizer(() => Effect.sync(() => app.off("browser-window-created", onWindowCreated)))

  return {
    installMenu: () => createMenu(menu),
  }
})

import { randomUUID } from "node:crypto"
import { mkdirSync, rmSync } from "node:fs"
import { enableCompileCache } from "node:module"
import { homedir, tmpdir } from "node:os"
import path from "node:path"
import { app } from "electron"
import { APP_ID, APP_NAME } from "../constants"

const testOnboarding = process.env.OPENCODE_TEST_ONBOARDING === "1"

const jsCallStackFeature = "DocumentPolicyIncludeJSCallStacksInCrashReports"

// Runs synchronously from the entry module, before Chromium is ready: command-line switches only
// take effect before ready, the single-instance lock is scoped to userData, and the early window
// needs userData to find the persisted window list and state.
export function configureApplication() {
  try {
    process.chdir(homedir())
  } catch {}

  process.env.OPENCODE_DISABLE_EMBEDDED_WEB_UI = "true"

  app.setName(APP_NAME)
  app.setAppUserModelId(APP_ID)
  app.commandLine.appendSwitch("proxy-bypass-list", "<-loopback>")
  const features = app.commandLine.getSwitchValue("enable-features")
  app.commandLine.appendSwitch("enable-features", features ? `${jsCallStackFeature},${features}` : jsCallStackFeature)

  if (!app.isPackaged)
    app.commandLine.appendSwitch("remote-debugging-port", process.env.OPENCODE_DESKTOP_REMOTE_DEBUGGING_PORT ?? "9222")

  const testRoot = createTestRoot()
  app.setPath("userData", testRoot ? path.join(testRoot, "desktop") : path.join(app.getPath("appData"), APP_ID))

  if (testRoot) {
    app.setPath("sessionData", path.join(testRoot, "session"))

    if (testOnboarding) app.setPath("documents", path.join(testRoot, "documents"))
  }

  // V8 bytecode for the main bundle survives between launches, like the renderer's code cache.
  enableCompileCache(path.join(app.getPath("userData"), "compile-cache"))
}

export function acquireApplicationLock() {
  if (app.requestSingleInstanceLock()) return true
  app.quit()

  return false
}

function createTestRoot() {
  const root = testOnboarding
    ? path.join(tmpdir(), `opencode-onboarding-${randomUUID()}`)
    : app.isPackaged
      ? undefined
      : process.env.OPENCODE_DESKTOP_TEST_ROOT

  if (!root) return undefined

  if (testOnboarding) rmSync(root, { recursive: true, force: true })

  for (const dir of ["data", "config", "cache", "state", "desktop", "session", "documents"])
    mkdirSync(path.join(root, dir), { recursive: true })

  if (testOnboarding) process.env.OPENCODE_DB = ":memory:"
  process.env.XDG_DATA_HOME = path.join(root, "data")
  process.env.XDG_CONFIG_HOME = path.join(root, "config")
  process.env.XDG_CACHE_HOME = path.join(root, "cache")
  process.env.XDG_STATE_HOME = path.join(root, "state")

  return root
}

import { describe, expect, test } from "bun:test"
import { consoleReturnWindow } from "./deep-link"

describe("Console return deep links", () => {
  test("reads the originating Desktop window", () => {
    expect(consoleReturnWindow("opencode://console/authorized?window=window-a")).toBe("window-a")
    expect(consoleReturnWindow("opencode://console/authorized?window=window%20b")).toBe("window b")
  })

  test("rejects unrelated and malformed links", () => {
    expect(consoleReturnWindow("opencode://console/other?window=window-a")).toBeUndefined()
    expect(consoleReturnWindow("opencode://other/authorized?window=window-a")).toBeUndefined()
    expect(consoleReturnWindow("https://console/authorized?window=window-a")).toBeUndefined()
    expect(consoleReturnWindow("not a url")).toBeUndefined()
    expect(consoleReturnWindow("opencode://console/authorized")).toBeUndefined()
  })
})

export function consoleReturnWindow(value: string) {
  try {
    const url = new URL(value)

    if (url.protocol !== "opencode:" || url.hostname !== "console" || url.pathname !== "/authorized") return
    const id = url.searchParams.get("window")

    if (!id || id.length > 256 || /[\u0000-\u001f\u007f]/.test(id)) return

    return id
  } catch {
    return
  }
}

export * as DesktopInitialization from "./desktop-initialization"

import { app } from "electron"
import { Context, Effect, Layer } from "effect"
import { DesktopLogging } from "../native/logging"
import { marks } from "./marks"
import {
  loadProxyEnvironment,
  preferApplicationEnvironment,
  prepareApplicationEnvironment,
  prepareDesktop,
} from "./environment"

export interface Interface {
  readonly version: string
}

export class Service extends Context.Service<Service, Interface>()("opencode/desktop/DesktopInitialization") {}

export const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const logging = yield* DesktopLogging.Service
    yield* preferApplicationEnvironment
    // System certificates, the proxy and the net log serve later network work; the first window and
    // its IPC port do not wait for them.
    yield* Effect.forkScoped(
      prepareApplicationEnvironment.pipe(Effect.andThen(loadProxyEnvironment), Effect.andThen(logging.startNetwork)),
    )
    yield* Effect.promise(() => app.whenReady())
    yield* prepareDesktop
    marks.init = Date.now()

    return Service.of({
      version: app.getVersion(),
    })
  }),
)

import http from "node:http"
import { getCACertificates, setDefaultCACertificates } from "node:tls"
import { app } from "electron"
import { Effect, Path } from "effect"
import { DesktopPaths } from "../paths"
import { getUserShell, loadShellEnv } from "../service/shell-env"
import { registerRendererProtocol, setDockIcon, setProtocolReporter } from "../windows"
import { scoped } from "../native/logging"

// electron-context-menu attaches to every existing and future window, so it can load once the first
// window is up instead of holding up startup with its dependency tree.
export const installContextMenu = Effect.gen(function* () {
  const { default: contextMenu } = yield* Effect.promise(() => import("electron-context-menu"))
  contextMenu({ showSaveImageAs: true, showLookUpSelection: false, showSearchWithGoogle: false })
})

export const prepareApplicationEnvironment = Effect.gen(function* () {
  yield* loadSystemCertificates
  yield* loadProxyEnvironment
})

export const preferApplicationEnvironment = Effect.gen(function* () {
  const shell = process.platform === "win32" ? null : getUserShell()
  const shellEnv = shell ? yield* loadShellEnv(shell) : null
  yield* Effect.sync(() => {
    if (!shellEnv?.XDG_STATE_HOME) delete process.env.XDG_STATE_HOME
    Object.assign(process.env, {
      ...shellEnv,
      OPENCODE_EXPERIMENTAL_ICON_DISCOVERY: "true",
      OPENCODE_EXPERIMENTAL_FILEWATCHER: "true",
      OPENCODE_CLIENT: "desktop",
    })
  })
})

export const prepareDesktop = Effect.gen(function* () {
  const path = yield* Path.Path
  const paths = yield* DesktopPaths.resolve

  if (app.isPackaged || process.env.OPENCODE_DESKTOP_DISABLE_PROTOCOL_REGISTRATION !== "1")
    app.setAsDefaultProtocolClient("opencode")
  const runFork = Effect.runForkWith(yield* Effect.context())
  setProtocolReporter((level, message, data) =>
    runFork(scoped("protocol", level === "error" ? Effect.logError(message, data) : Effect.logWarning(message, data))),
  )
  registerRendererProtocol(paths.rendererRoot)
  setDockIcon(path, paths)
})

export const loadProxyEnvironment = Effect.gen(function* () {
  yield* Effect.try(() => {
    ensureLoopbackNoProxy()
    // Electron 41.2 has a newer Node API than the current @types/node package.
    const proxyAwareHttp = http as typeof http & { setGlobalProxyFromEnv(): void }
    proxyAwareHttp.setGlobalProxyFromEnv()
  }).pipe(Effect.catch((error) => Effect.logWarning("failed to load proxy environment", { error })))
})

const loadSystemCertificates = Effect.try({
  try: () => {
    setDefaultCACertificates([...new Set([...getCACertificates("default"), ...getCACertificates("system")])])
  },
  catch: (error) => error,
}).pipe(Effect.catch((error) => Effect.logWarning("failed to load system certificates", { error })))

function ensureLoopbackNoProxy() {
  const loopback = ["127.0.0.1", "localhost", "::1"]

  ;["NO_PROXY", "no_proxy"].forEach((key) => {
    const items = (process.env[key] ?? "")
      .split(",")
      .map((value) => value.trim())
      .filter(Boolean)

    loopback.forEach((host) => {
      if (!items.some((value) => value.toLowerCase() === host)) items.push(host)
    })
    process.env[key] = items.join(",")
  })
}

export * as ApplicationLifecycle from "./index"

import { app, BrowserWindow } from "electron"
import type { Event } from "electron"
import { Context, Effect, Layer } from "effect"
import { DeepLinksOpened } from "../../shared/ipc-rpc/events"
import { emitIpcEvent } from "../ipc-events"
import { DesktopLogging, scoped } from "../native/logging"
import { DesktopStorage } from "../storage"
import { safeWebContentsURL } from "../windows/state"
import { getLastFocusedWindow, getWindowByID, makeMainWindows, setAppQuitting, setRelaunchHandler } from "../windows"
import { marks } from "./marks"
import { initializeFirstLaunchOnboarding } from "./onboarding"
import { Shutdown } from "./shutdown"
import { consoleReturnWindow } from "./deep-link"

export interface Interface {
  readonly relaunch: () => void
  readonly prepareToRestart: Effect.Effect<void>
  readonly consumeInitialDeepLinks: () => string[]
  readonly createWindow: () => BrowserWindow
  readonly restoreWindows: () => BrowserWindow[]
}

export class Service extends Context.Service<Service, Interface>()("opencode/desktop/ApplicationLifecycle") {}

const runtime = Layer.effect(
  Service,
  Effect.gen(function* () {
    const shutdown = yield* Shutdown.Service
    const runFork = Effect.runForkWith(yield* Effect.context())
    const windows = yield* makeMainWindows()
    const createWindow = windows.create
    const restoreWindows = windows.restore
    const pendingDeepLinks: string[] = []
    let shutdownReady = false
    const prepareToRestart = shutdown.run.pipe(Effect.ensuring(Effect.sync(() => (shutdownReady = true))))

    const focusWindow = (win: BrowserWindow | null) => {
      if (!win) return

      if (win.isMinimized()) win.restore()
      win.show()
      win.focus()
    }

    const emitDeepLinks = (urls: string[]) => {
      if (!urls.length) return
      pendingDeepLinks.push(...urls)

      const target = urls.flatMap((url) => {
        const id = consoleReturnWindow(url)
        const win = id ? getWindowByID(id) : null

        return win ? [win] : []
      })[0]

      const win = target ?? getLastFocusedWindow()

      if (win) emitIpcEvent(win.webContents, new DeepLinksOpened({ urls }))

      return win
    }

    const relaunch = () => {
      setAppQuitting()
      runFork(
        prepareToRestart.pipe(
          Effect.ensuring(
            Effect.sync(() => {
              app.relaunch()
              app.quit()
            }),
          ),
        ),
      )
    }

    const secondInstance = (_event: Event, argv: string[]) => {
      const urls = argv.filter((arg) => arg.startsWith("opencode://"))

      if (urls.length) {
        runFork(Effect.logInfo("deep link received via second-instance", { urls }))
        focusWindow(emitDeepLinks(urls) ?? null)
      }

      if (!urls.length) focusWindow(getLastFocusedWindow())
    }

    const openUrl = (event: Event, url: string) => {
      event.preventDefault()
      runFork(Effect.logInfo("deep link received via open-url", { url }))
      focusWindow(emitDeepLinks([url]) ?? null)
    }

    const beforeQuit = (event: Event) => {
      setAppQuitting()

      if (shutdownReady) return
      event.preventDefault()
      runFork(prepareToRestart.pipe(Effect.ensuring(Effect.sync(() => app.quit()))))
    }

    const willQuit = () => {
      setAppQuitting()
      runFork(shutdown.run)
    }

    const childProcessGone = (_event: Event, details: Electron.Details) => {
      runFork(scoped("utility", Effect.logError("child process gone", { details })))
    }

    const renderProcessGone = (
      _event: Event,
      webContents: Electron.WebContents,
      details: Electron.RenderProcessGoneDetails,
    ) => {
      runFork(
        scoped("window", Effect.logError("app render process gone", { url: safeWebContentsURL(webContents), details })),
      )
    }

    const signal = () => {
      setAppQuitting()
      runFork(prepareToRestart.pipe(Effect.ensuring(Effect.sync(() => app.quit()))))
    }

    const windowAllClosed = () => {
      if (process.platform !== "darwin") app.quit()
    }

    const activate = () => {
      if (BrowserWindow.getAllWindows().length === 0) restoreWindows()
    }

    const resetRelaunchHandler = setRelaunchHandler(relaunch)
    let windowsWired = false

    app.on("second-instance", secondInstance)
    app.on("open-url", openUrl)
    app.on("before-quit", beforeQuit)
    app.on("will-quit", willQuit)
    app.on("child-process-gone", childProcessGone)
    app.on("render-process-gone", renderProcessGone)
    process.on("SIGINT", signal)
    process.on("SIGTERM", signal)
    yield* Effect.addFinalizer(() =>
      Effect.sync(() => {
        app.off("second-instance", secondInstance)
        app.off("open-url", openUrl)
        app.off("before-quit", beforeQuit)
        app.off("will-quit", willQuit)
        app.off("child-process-gone", childProcessGone)
        app.off("render-process-gone", renderProcessGone)
        app.off("window-all-closed", windowAllClosed)
        app.off("activate", activate)
        process.off("SIGINT", signal)
        process.off("SIGTERM", signal)
        resetRelaunchHandler()
      }),
    )

    return Service.of({
      relaunch,
      prepareToRestart,
      consumeInitialDeepLinks: () => pendingDeepLinks.splice(0),
      createWindow,
      restoreWindows: () => {
        if (!windowsWired) {
          windowsWired = true
          app.on("window-all-closed", windowAllClosed)
          app.on("activate", activate)
        }

        return restoreWindows()
      },
    })
  }),
)

// Storage opens after the entry module has set userData and before the renderer loads, so window
// teardown can clear a window's persisted state and every renderer request finds it ready.
const platform = Layer.mergeAll(
  DesktopLogging.layer,
  Shutdown.layer,
  DesktopStorage.layer.pipe(Layer.provide(DesktopLogging.layer)),
)

export const layer = Layer.unwrap(
  Effect.gen(function* () {
    // Decide first-launch state before the storage layer creates drafts.sqlite, which would
    // otherwise read as evidence of an earlier launch on a fresh install.
    yield* initializeFirstLaunchOnboarding(app.getPath("userData"))
    marks.onboarding = Date.now()

    return runtime.pipe(Layer.provideMerge(platform))
  }),
)

import { app } from "electron"
import { Effect, FileSystem, Option, Path } from "effect"
import { scoped } from "../native/logging"
import { hasExistingAppState } from "../storage/install-state"
import { FIRST_LAUNCH_ONBOARDING_COMPLETE_KEY } from "../storage/keys"
import { getStore } from "../storage/store"
import { nativeT } from "../native/translations"

export const initializeFirstLaunchOnboarding = Effect.fn("Onboarding.initialize")(function* (userDataPath: string) {
  const store = getStore()
  const current = store.get(FIRST_LAUNCH_ONBOARDING_COMPLETE_KEY)

  if (typeof current === "boolean") return current

  const fs = yield* FileSystem.FileSystem
  const path = yield* Path.Path
  const names = (yield* fs.exists(userDataPath)) ? yield* fs.readDirectory(userDataPath) : []

  const entries = yield* Effect.forEach(
    names,
    Effect.fnUntraced(function* (name) {
      const info = yield* fs.stat(path.join(userDataPath, name)).pipe(Effect.option)

      return { name, directory: Option.isSome(info) && info.value.type === "Directory" }
    }),
    { concurrency: "unbounded" },
  )

  const complete = hasExistingAppState(entries)
  store.set(FIRST_LAUNCH_ONBOARDING_COMPLETE_KEY, complete)

  return complete
})

export const isFirstLaunchOnboardingPending = Effect.fn("Onboarding.isPending")(function* () {
  const pending = getStore().get(FIRST_LAUNCH_ONBOARDING_COMPLETE_KEY) !== true
  yield* scoped("onboarding", Effect.logInfo("first launch onboarding pending checked", { pending }))

  return pending
})

export const finishFirstLaunchOnboarding = Effect.fn("Onboarding.finish")(function* (createDefaultProject: boolean) {
  if (!(yield* isFirstLaunchOnboardingPending())) {
    yield* scoped("onboarding", Effect.logInfo("first launch onboarding already completed"))

    return null
  }

  const fs = yield* FileSystem.FileSystem
  const path = yield* Path.Path

  const defaultProject = createDefaultProject
    ? path.join(app.getPath("documents"), nativeT("desktop.onboarding.defaultProject"))
    : null

  if (defaultProject) yield* fs.makeDirectory(defaultProject, { recursive: true })

  getStore().set(FIRST_LAUNCH_ONBOARDING_COMPLETE_KEY, true)
  yield* scoped(
    "onboarding",
    Effect.logInfo("first launch onboarding completed", { createDefaultProject, defaultProject }),
  )

  return defaultProject
})

export * as Shutdown from "./shutdown"

import { Context, Effect, Layer } from "effect"

export interface Interface {
  readonly add: (effect: Effect.Effect<void>) => Effect.Effect<() => void>
  readonly run: Effect.Effect<void>
}

export class Service extends Context.Service<Service, Interface>()("opencode/desktop/Shutdown") {}

export const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const effects = new Set<Effect.Effect<void>>()

    const run = yield* Effect.cached(
      Effect.suspend(() => Effect.forEach(effects, (effect) => effect, { concurrency: "unbounded", discard: true })),
    )

    return Service.of({
      add: (effect) =>
        Effect.sync(() => {
          effects.add(effect)

          return () => effects.delete(effect)
        }),
      run,
    })
  }),
)

import { nativeImage } from "electron"

type Color = readonly [number, number, number, number]

// Native browser surfaces ignore a parent View's clip path. Cover only the
// pixels outside the bottom arcs; never resize or style the page itself.
// The card's ring sits just outside the arc, inside these masks, so draw it here.
export function createCornerImages(
  color: Color,
  radius: number,
  scale: number,
  border?: { readonly color: Color; readonly width: number },
) {
  const size = Math.max(1, Math.round(radius * scale))
  const ring = (border?.width ?? 0) * scale
  const coverage = (edge: number, distance: number) => Math.max(0, Math.min(1, edge - distance + 0.5))

  return [false, true].map((right) => {
    const pixels = Buffer.alloc(size * size * 4)

    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const distance = Math.hypot(right ? x + 0.5 : size - x - 0.5, y + 0.5)
        const inside = coverage(size, distance)
        const base = ((1 - inside) * color[3]) / 255
        const line = border ? ((coverage(size + ring, distance) - inside) * border.color[3]) / 255 : 0

        const channel = (index: number) =>
          Math.round((border ? border.color[index] : 0) * line + color[index] * base * (1 - line))

        const offset = (y * size + x) * 4
        // NativeImage bitmaps use premultiplied BGRA on supported desktop platforms.
        pixels[offset] = channel(2)
        pixels[offset + 1] = channel(1)
        pixels[offset + 2] = channel(0)
        pixels[offset + 3] = Math.round(255 * (line + base * (1 - line)))
      }
    }

    return nativeImage.createFromBitmap(pixels, { width: size, height: size, scaleFactor: scale })
  })
}

import type { WebContents } from "electron"

const focusDebuggerOwners = new WeakSet<WebContents>()

const forcedFocusNodes = new WeakMap<WebContents, number[]>()

const focusableSelector = `
  a[href],
  button:not([disabled]),
  input:not([disabled]),
  select:not([disabled]),
  textarea:not([disabled]),
  summary,
  [contenteditable="true"],
  [tabindex]:not([tabindex="-1"])
`

export async function setForceFocus(contents: WebContents, enabled: boolean) {
  const debuggerApi = contents.debugger

  if (!debuggerApi.isAttached()) {
    if (!enabled) {
      focusDebuggerOwners.delete(contents)
      forcedFocusNodes.delete(contents)

      return
    }

    debuggerApi.attach("1.3")
    focusDebuggerOwners.add(contents)
    debuggerApi.once("detach", () => {
      focusDebuggerOwners.delete(contents)
      forcedFocusNodes.delete(contents)
    })
  }

  if (!enabled) {
    await Promise.allSettled(
      (forcedFocusNodes.get(contents) ?? []).map((nodeId) =>
        debuggerApi.sendCommand("CSS.forcePseudoState", {
          nodeId,
          forcedPseudoClasses: [],
        }),
      ),
    )
    forcedFocusNodes.delete(contents)

    if (!focusDebuggerOwners.delete(contents)) return
    debuggerApi.detach()

    return
  }

  await debuggerApi.sendCommand("DOM.enable")
  await debuggerApi.sendCommand("CSS.enable")

  const document: unknown = await debuggerApi.sendCommand("DOM.getDocument", {
    depth: -1,
    pierce: true,
  })

  const nodes: unknown = await debuggerApi.sendCommand("DOM.querySelectorAll", {
    nodeId: readDocumentNodeId(document),
    selector: focusableSelector,
  })

  const nodeIds = readNodeIds(nodes)
  forcedFocusNodes.set(contents, [...new Set([...(forcedFocusNodes.get(contents) ?? []), ...nodeIds])])
  await Promise.allSettled(
    nodeIds.map((nodeId) =>
      debuggerApi.sendCommand("CSS.forcePseudoState", {
        nodeId,
        forcedPseudoClasses: ["focus", "focus-visible"],
      }),
    ),
  )
}

function readDocumentNodeId(value: unknown) {
  if (
    !value ||
    typeof value !== "object" ||
    !("root" in value) ||
    !value.root ||
    typeof value.root !== "object" ||
    !("nodeId" in value.root) ||
    typeof value.root.nodeId !== "number"
  ) {
    throw new Error("Invalid DOM.getDocument response")
  }

  return value.root.nodeId
}

function readNodeIds(value: unknown) {
  if (
    !value ||
    typeof value !== "object" ||
    !("nodeIds" in value) ||
    !Array.isArray(value.nodeIds) ||
    !value.nodeIds.every((nodeId) => typeof nodeId === "number")
  ) {
    throw new Error("Invalid DOM.querySelectorAll response")
  }

  return value.nodeIds
}

import { dialog } from "electron"
import { Effect } from "effect"
import { DesktopCli } from "../service/desktop-cli"
import { nativeT } from "./translations"

export function showCliInstaller(desktopCli: DesktopCli.Interface) {
  return desktopCli.install.pipe(
    Effect.tap((path) =>
      Effect.promise(() =>
        dialog.showMessageBox({
          type: "info",
          message: nativeT("desktop.cli.installed.message", { path }),
          title: nativeT("desktop.cli.installed.title"),
        }),
      ),
    ),
    Effect.catch((error) =>
      Effect.promise(() =>
        dialog.showMessageBox({
          type: "error",
          message: nativeT("desktop.cli.failed.message", { error: error.message }),
          title: nativeT("desktop.cli.failed.title"),
        }),
      ),
    ),
    Effect.asVoid,
  )
}

export * as DesktopLogging from "./logging"

import log from "electron-log/main.js"
import { app, crashReporter, netLog, shell } from "electron"
import { Context, Effect, FileSystem, Layer, Logger, Option, Path, References, Stream } from "effect"
import { homedir } from "node:os"
import { VERSION } from "../constants"
import { marks } from "../lifecycle/marks"

const MAX_LOG_AGE_DAYS = 7

const TAIL_LINES = 1000

const EXPORT_WINDOW = 24 * 60 * 60 * 1000

const MAX_EXPORT_FILE_SIZE = 50 * 1024 * 1024

const NET_LOG_SIZE = 20 * 1024 * 1024

let root = ""

let run = ""

let netLogPath: string | undefined

export interface Interface {
  readonly startNetwork: Effect.Effect<void>
  readonly startCrashReporter: Effect.Effect<void>
  readonly exportDebug: Effect.Effect<string>
}

export class Service extends Context.Service<Service, Interface>()("opencode/desktop/DesktopLogging") {}

const serviceLayer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem
    const path = yield* Path.Path
    yield* initLogging(fs, path).pipe(Effect.orDie)
    // Old run directories go away in the background; listing them is not worth a wait at startup.
    yield* Effect.forkScoped(cleanup(fs, path).pipe(Effect.catch(() => Effect.void)))
    marks.logging = Date.now()
    yield* Effect.logInfo("app starting", {
      version: VERSION,
      packaged: app.isPackaged,
      onboardingTest: process.env.OPENCODE_TEST_ONBOARDING === "1",
      marks,
    })
    const exportDebug = exportDebugLogsEffect(fs, path).pipe(Effect.orDie)

    return Service.of({
      startNetwork: startNetLog(path).pipe(
        Effect.catch((error) => Effect.logWarning("failed to start net log", { error })),
      ),
      // Starting crashpad spawns its handler process, ~60 ms on the main thread, so the first window
      // and its IPC port come first.
      startCrashReporter: initCrashReporter(fs, path).pipe(
        Effect.tap(() => Effect.sync(() => (marks.crash = Date.now()))),
        Effect.catch((error) => Effect.logWarning("failed to start crash reporter", { error })),
      ),
      exportDebug,
    })
  }),
)

const nativeLogger = Logger.make((options) => {
  try {
    if (!run) return
    const entry = Logger.formatStructured.log(options)
    const scope = typeof entry.annotations.scope === "string" ? entry.annotations.scope : "main"
    const annotations = Object.fromEntries(Object.entries(entry.annotations).filter(([key]) => key !== "scope"))

    const context = {
      ...(Object.keys(annotations).length === 0 ? {} : { annotations }),
      ...(Object.keys(entry.spans).length === 0 ? {} : { spans: entry.spans }),
      ...(entry.cause === undefined ? {} : { cause: entry.cause }),
    }

    const messages = Array.isArray(options.message) ? options.message : [options.message]
    log.scope(safeLogName(scope))[methods[options.logLevel]](
      ...messages,
      ...(Object.keys(context).length === 0 ? [] : [context]),
    )
  } catch {
    // Logging must not interrupt application work.
  }
})

const methods = {
  All: "silly",
  Trace: "silly",
  Debug: "debug",
  Info: "info",
  Warn: "warn",
  Error: "error",
  Fatal: "error",
  None: "silly",
} as const

const nativeLoggerLayer = Layer.merge(
  Logger.layer([nativeLogger], { mergeWithExisting: false }),
  Layer.succeed(References.MinimumLogLevel, "All"),
)

export const layer = serviceLayer.pipe(Layer.provideMerge(nativeLoggerLayer))

function initLogging(fs: FileSystem.FileSystem, path: Path.Path) {
  return Effect.gen(function* () {
    yield* initRunDirectory(fs, path)
    yield* Effect.sync(() => {
      log.transports.file.maxSize = 5 * 1024 * 1024
      log.transports.file.resolvePathFn = (_vars, message) =>
        path.join(
          run,
          `${safeLogName(message?.scope ?? (message?.variables?.processType === "renderer" ? "renderer" : "main"))}.log`,
        )
      log.initialize({ preload: false, spyRendererConsole: true })
      initConsoleTransport()
    })
  })
}

function initCrashReporter(fs: FileSystem.FileSystem, path: Path.Path) {
  return Effect.gen(function* () {
    const dir = path.join(app.getPath("userData"), "Crashpad")
    yield* fs.makeDirectory(dir, { recursive: true })
    yield* Effect.sync(() => {
      app.setPath("crashDumps", dir)
      crashReporter.start({ uploadToServer: false, compress: true })
    })
    yield* scoped("crash", Effect.logInfo("crash reporter started", { path: dir }))
  })
}

function startNetLog(path: Path.Path) {
  if (netLog.currentlyLogging) return Effect.void
  const target = path.join(run, "network.netlog")
  netLogPath = target

  return Effect.tryPromise(() => netLog.startLogging(target, { captureMode: "default", maxFileSize: NET_LOG_SIZE })).pipe(
    Effect.tap(() => scoped("network", Effect.logInfo("net log started", { path: target }))),
  )
}

function exportDebugLogsEffect(fs: FileSystem.FileSystem, path: Path.Path) {
  return Effect.gen(function* () {
    const restartNetLog = netLog.currentlyLogging

    if (restartNetLog) {
      yield* Effect.tryPromise(() => netLog.stopLogging()).pipe(
        Effect.catch((error) => scoped("network", Effect.logWarning("failed to stop net log", { error }))),
      )
    }

    const output = path.join(app.getPath("downloads"), `opencode-debug-${stamp()}.zip`)

    return yield* Effect.gen(function* () {
      yield* Effect.logInfo("exporting debug logs", { output })

      const files = [
        ...(yield* collect(fs, path, root, "desktop")),
        ...(yield* Effect.forEach(serverLogRoots(path), (dir, i) => collect(fs, path, dir, `server-${i + 1}`))).flat(),
        ...(yield* collect(fs, path, app.getPath("crashDumps"), "crashpad")),
      ]

      const truncated = files.filter((file) => file.offset > 0).map((file) => file.name)
      yield* writeZip(fs, output, [
        { name: "manifest.json", data: Buffer.from(JSON.stringify({ ...manifest(path), truncated }, null, 2)) },
        ...files,
      ])
      yield* Effect.sync(() => shell.showItemInFolder(output))

      return output
    }).pipe(
      Effect.ensuring(
        restartNetLog
          ? startNetLog(path).pipe(
              Effect.catch((error) =>
                scoped("network", Effect.logWarning("failed to restart net log", { error })),
              ),
            )
          : Effect.void,
      ),
    )
  })
}

export const tail = Effect.fn("DesktopLogging.tail")(function* () {
  const fs = yield* FileSystem.FileSystem

  return yield* Effect.gen(function* () {
    const path = log.transports.file.getFile().path
    const contents = yield* fs.readFileString(path)
    const lines = contents.split("\n")

    return lines.slice(Math.max(0, lines.length - TAIL_LINES)).join("\n")
  }).pipe(Effect.orElseSucceed(() => ""))
})

function initRunDirectory(fs: FileSystem.FileSystem, path: Path.Path) {
  root = path.join(app.getPath("userData"), "logs")
  run = path.join(root, stamp())

  return fs.makeDirectory(run, { recursive: true })
}

function stamp() {
  return new Date()
    .toISOString()
    .replace(/[-:]/g, "")
    .replace(/\.\d+Z$/, "")
}

function safeLogName(name: string) {
  return name.replace(/[^a-z0-9_.-]/gi, "_") || "main"
}

function cleanup(fs: FileSystem.FileSystem, path: Path.Path) {
  return Effect.gen(function* () {
    const dir = root || path.dirname(log.transports.file.getFile().path)
    const cutoff = Date.now() - MAX_LOG_AGE_DAYS * 24 * 60 * 60 * 1000
    const entries = yield* fs.readDirectory(dir)
    yield* Effect.forEach(
      entries,
      (entry) =>
        Effect.gen(function* () {
          const file = path.join(dir, entry)
          const info = yield* fs.stat(file)

          if (Option.getOrElse(info.mtime, () => new Date(0)).getTime() < cutoff) {
            yield* fs.remove(file, { recursive: true, force: true })
          }
        }).pipe(Effect.catch(() => Effect.void)),
      { discard: true },
    )
  })
}

function manifest(path: Path.Path) {
  return {
    generated: new Date().toISOString(),
    version: VERSION,
    name: app.getName(),
    packaged: app.isPackaged,
    platform: process.platform,
    arch: process.arch,
    versions: process.versions,
    uptime: process.uptime(),
    userData: app.getPath("userData"),
    logs: root,
    currentRun: run,
    crashDumps: app.getPath("crashDumps"),
    serverLogs: serverLogRoots(path),
    netLog: netLogPath,
  }
}

function serverLogRoots(path: Path.Path) {
  const xdgData = process.env.XDG_DATA_HOME || path.join(homedir(), ".local", "share")

  return [
    ...new Set([path.join(xdgData, "opencode", "log"), path.join(app.getPath("userData"), "opencode", "log")]),
  ]
}

type Entry = { name: string; path: string; offset: number } | { name: string; data: Uint8Array }

function collect(fs: FileSystem.FileSystem, path: Path.Path, dir: string, prefix: string) {
  return Effect.gen(function* () {
    if (!(yield* fs.exists(dir).pipe(Effect.orElseSucceed(() => false)))) return []
    const cutoff = Date.now() - EXPORT_WINDOW
    const entries = yield* fs.readDirectory(dir, { recursive: true })

    return (yield* Effect.forEach(entries, (entry) =>
      Effect.gen(function* () {
        const file = path.join(dir, entry)
        const info = yield* fs.stat(file)

        if (info.type === "Directory") return null

        if (Option.getOrElse(info.mtime, () => new Date(0)).getTime() < cutoff) return null

        if (file.endsWith(".heapsnapshot")) return null
        // Server logs append forever without rotation, so the active log is often the largest
        // file. Export its tail rather than dropping the most relevant file from the bundle.
        const offset = Math.max(0, Number(info.size) - MAX_EXPORT_FILE_SIZE)

        return { name: path.join(prefix, entry).replace(/\\/g, "/"), path: file, offset }
      }),
    )).filter((entry) => entry !== null)
  })
}

function writeZip(fs: FileSystem.FileSystem, output: string, entries: Entry[]) {
  return Effect.gen(function* () {
    const { BlobReader, BlobWriter, ZipWriter } = yield* Effect.promise(() => import("@zip.js/zip.js"))
    const writer = new ZipWriter(new BlobWriter("application/zip"))
    yield* Effect.forEach(
      entries,
      (entry) =>
        Effect.gen(function* () {
          const data =
            "data" in entry
              ? entry.data
              : entry.offset === 0
                ? yield* fs.readFile(entry.path)
                : Buffer.concat(yield* Stream.runCollect(fs.stream(entry.path, { offset: entry.offset })))

          yield* Effect.tryPromise(() => writer.add(entry.name, new BlobReader(new Blob([new Uint8Array(data)]))))
        }),
      { concurrency: 1, discard: true },
    )
    const zip = yield* Effect.tryPromise(() => writer.close())
    yield* fs.writeFile(output, new Uint8Array(yield* Effect.tryPromise(() => zip.arrayBuffer())))
  })
}

function initConsoleTransport() {
  if (app.isPackaged) {
    log.transports.console.level = false

    return
  }

  const writeConsole = log.transports.console.writeFn.bind(log.transports.console)
  log.transports.console.writeFn = (options) => {
    try {
      writeConsole(options)
    } catch (err) {
      if (!isBrokenPipe(err)) throw err
      log.transports.console.level = false
    }
  }
}

function isBrokenPipe(err: unknown) {
  return typeof err === "object" && err !== null && "code" in err && err.code === "EPIPE"
}

export function scoped(name: string, effect: Effect.Effect<void>) {
  return effect.pipe(Effect.annotateLogs("scope", name))
}

import { BrowserWindow, Menu } from "electron"
import type { MenuItemConstructorOptions } from "electron"
import {
  DESKTOP_MENU,
  desktopMenuKey,
  desktopMenuVisible,
  desktopMenuWithExtensions,
  type DesktopMenu,
  type DesktopMenuEntry,
  type DesktopMenuRole,
} from "@opencode/app/desktop-menu"
import { MenuCommandTriggered } from "../../shared/ipc-rpc/events"
import { emitIpcEvent } from "../ipc-events"

import { runDesktopMenuAction } from "./menu-actions"
import { nativeT } from "./translations"

type Deps = {
  trigger: (id: string) => void
  installCli: () => void
  createWindow: () => void
  openExternal: (url: string) => void
  relaunch: () => void
}

/** A GUI extension's contribution to the native menu, already translated by the extension. */
export type MenubarEntry = {
  readonly menu: string
  readonly id: string
  readonly label: string
  /** A built-in item's command, action, or role, or another contribution's id. */
  readonly after?: string
  enabled(): boolean
  run(): void
}

let menubar: () => readonly MenubarEntry[] = () => []

let installed: Deps | undefined

/** Contributions are read on every build; setting a provider rebuilds an installed menu. */
export function setMenubarProvider(provider: () => readonly MenubarEntry[]) {
  menubar = provider
  refreshMenu()
}

/** Rebuilds an installed menu after its contributions changed. */
export function refreshMenu() {
  if (installed) createMenu(installed)
}

export function createMenu(deps: Deps) {
  installed = deps

  if (process.platform !== "darwin") return

  const extra = menubar()

  const template = DESKTOP_MENU.filter((menu) => desktopMenuVisible(menu, "macos")).map((menu) =>
    nativeMenu(
      menu,
      extra.filter((item) => item.menu === menu.id),
      deps,
    ),
  )

  const built = Menu.buildFromTemplate(template)

  // Electron freezes a built item's state; contributions re-read theirs whenever a menu opens.
  const refresh = () =>
    extra.forEach((item) => {
      const target = built.getMenuItemById(item.id)

      if (target) target.enabled = item.enabled()
    })

  if (extra.length) built.items.forEach((item) => item.submenu?.on("menu-will-show", refresh))
  Menu.setApplicationMenu(built)
}

export function sendMenuCommand(win: BrowserWindow, id: string) {
  emitIpcEvent(win.webContents, new MenuCommandTriggered({ id }))
}

function nativeMenu(menu: DesktopMenu, extra: readonly MenubarEntry[], deps: Deps): MenuItemConstructorOptions {
  if (menu.role && !extra.length) return { role: nativeRole(menu.role), label: nativeT(menu.labelKey) }

  const items = desktopMenuWithExtensions(
    (menu.items ?? [])
      .filter((entry) => desktopMenuVisible(entry, "macos"))
      .map((entry) => ({ key: desktopMenuKey(entry), entry })),
    extra,
  )

  return {
    ...(menu.role ? { role: nativeRole(menu.role) } : {}),
    label: nativeT(menu.labelKey),
    submenu: items.map((item) => {
      const entry = item.entry

      if ("menu" in entry)
        return { id: entry.id, label: entry.label, enabled: entry.enabled(), click: () => entry.run() }

      return nativeItem(entry, deps)
    }),
  }
}

function nativeItem(entry: DesktopMenuEntry, deps: Deps): MenuItemConstructorOptions {
  if (entry.type === "separator") return { type: "separator" }

  if (entry.role) return { role: nativeRole(entry.role), label: entry.labelKey ? nativeT(entry.labelKey) : undefined }

  const item: MenuItemConstructorOptions = {
    label: entry.labelKey ? nativeT(entry.labelKey) : undefined,
    accelerator: entry.accelerator?.macos,
  }

  if (entry.command) {
    const command = entry.command
    item.click = () => deps.trigger(command)
  }

  if (entry.action) {
    const action = entry.action
    item.click = () =>
      runDesktopMenuAction(BrowserWindow.getFocusedWindow(), action, {
        installCli: deps.installCli,
        createWindow: deps.createWindow,
        relaunch: deps.relaunch,
      })
  }

  if (entry.href) {
    const href = entry.href
    item.click = () => deps.openExternal(href)
  }

  return item
}

function nativeRole(role: DesktopMenuRole) {
  return role as NonNullable<MenuItemConstructorOptions["role"]>
}

import {
  DESKTOP_NATIVE_ENGLISH,
  DESKTOP_NATIVE_KEYS,
  DESKTOP_NATIVE_LOCALE_TAGS,
  formatDesktopNativeMessage,
  type DesktopNativeBundle,
  type DesktopNativeKey,
} from "@opencode/app/i18n/desktop-native"

let bundle: DesktopNativeBundle = { locale: "en", messages: { ...DESKTOP_NATIVE_ENGLISH } }

const listeners = new Set<() => void>()

export function setNativeTranslations(next: DesktopNativeBundle) {
  if (
    next.locale === bundle.locale &&
    DESKTOP_NATIVE_KEYS.every((key) => next.messages[key] === bundle.messages[key])
  ) {
    return false
  }

  bundle = next
  listeners.forEach((listener) => listener())

  return true
}

export function nativeT(key: DesktopNativeKey, params?: Record<string, string | number>) {
  return formatDesktopNativeMessage(bundle.messages[key], params)
}

/** The app locale the renderer last pushed. GUI extension catalogs resolve against it. */
export function nativeLocale() {
  return bundle.locale
}

/** Runs after the renderer pushes a different bundle, such as when the user switches language. */
export function onNativeTranslations(listener: () => void) {
  listeners.add(listener)

  return () => {
    listeners.delete(listener)
  }
}

/** A shared app message for a key that is only known at runtime, such as one an extension asks for. */
export function nativeMessage(key: string) {
  const messages: Readonly<Record<string, string>> = bundle.messages

  return Object.hasOwn(messages, key) ? messages[key] : undefined
}

export function nativePluralCategory(count: number) {
  return new Intl.PluralRules(DESKTOP_NATIVE_LOCALE_TAGS[bundle.locale]).select(count)
}

// Same placeholder syntax the renderer's language API resolves, so one catalog serves both hosts.
export function formatNativeTemplate(template: string, params?: Readonly<Record<string, string | number | boolean>>) {
  if (!params) return template

  return template.replace(/\{\{\s*([^{}\s]+)\s*\}\}/g, (match, key: string) =>
    Object.hasOwn(params, key) ? String(params[key]) : match,
  )
}

