import { DatabaseSync } from "node:sqlite"
import { drizzle } from "drizzle-orm/node-sqlite"
import { migrateDatabase } from "./migration"

export type Database = ReturnType<typeof drizzle>

export function openDatabase(filename: string) {
  const native = new DatabaseSync(filename)
  // WAL keeps readers off the writer. NORMAL fsyncs at checkpoints only, which survives an app
  // crash but not power loss; the right trade for UI state and far cheaper on Windows.
  native.exec("PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL; PRAGMA temp_store=MEMORY")
  const db = drizzle({ client: native })
  migrate(db)

  return { db, close: () => native.close() }
}

export function migrate(db: Database) {
  return migrateDatabase(db.$client)
}

import { afterEach, beforeEach, describe, expect, setSystemTime, test } from "bun:test"
import { sql } from "drizzle-orm"
import { openDatabase } from "./database"
import { blobGrace, createDraftStore } from "./drafts"

const collectInterval = 60_000

const start = Date.UTC(2026, 6, 1)

const clock = (ms: number) => setSystemTime(new Date(start + ms))

const text = (...ids: string[]) =>
  JSON.stringify({ prompt: [{ type: "text", content: { blob: { kind: "text", ids } } }] })

beforeEach(() => clock(0))

afterEach(() => setSystemTime())

describe("draft store", () => {
  test("queues documents and reads them back before and after flush", () => {
    const database = openDatabase(":memory:")
    const drafts = createDraftStore(database.db)
    drafts.set("a:draft:prompt", "{}")
    expect(drafts.get("a:draft:prompt")).toBe("{}")
    drafts.flush()
    expect(drafts.get("a:draft:prompt")).toBe("{}")
    drafts.set("a:draft:prompt", null)
    expect(drafts.get("a:draft:prompt")).toBeNull()
    drafts.flush()
    expect(database.db.all(sql`SELECT key FROM document`)).toEqual([])
  })

  test("stores blobs by content hash and collects unreferenced ones shortly after open", async () => {
    const database = openDatabase(":memory:")
    const first = createDraftStore(database.db)
    const used = first.putBlob(new Uint8Array([1, 2, 3]))
    const unused = first.putBlob(new Uint8Array([4, 5, 6]))
    expect(first.putBlob(new Uint8Array([1, 2, 3]))).toBe(used)
    first.set("doc", JSON.stringify({ parts: [{ blob: { id: used } }] }))
    first.flush()
    first.close()
    // The startup collection runs off the window's critical path and keeps the usual grace, so a
    // blob from a session that ended within the grace period is still there...
    const second = createDraftStore(database.db, { collectDelay: 0 })
    await new Promise((resolve) => setTimeout(resolve, 5))
    expect(second.getBlob(unused)).toEqual(new Uint8Array([4, 5, 6]))
    second.close()
    // ...and gone once the grace has passed.
    clock(blobGrace + 1)
    const third = createDraftStore(database.db, { collectDelay: 0 })
    await new Promise((resolve) => setTimeout(resolve, 5))
    expect(third.getBlob(used)).toEqual(new Uint8Array([1, 2, 3]))
    expect(third.getBlob(unused)).toBeNull()
    third.close()
  })

  test("collects a retired chunk only once it is unreferenced and past the grace period", () => {
    const database = openDatabase(":memory:")
    const drafts = createDraftStore(database.db)
    const a = drafts.putBlob(new TextEncoder().encode("chunk a"))
    const b = drafts.putBlob(new TextEncoder().encode("chunk b"))
    drafts.set("doc", text(a, b))
    drafts.flush()
    const c = drafts.putBlob(new TextEncoder().encode("chunk c"))
    drafts.set("doc", text(a, c))
    drafts.flush()
    // Retired but recently touched: survives a due collection.
    clock(120_000)
    drafts.putBlob(new TextEncoder().encode("chunk d"))
    drafts.set("other", "{}")
    drafts.flush()
    expect(drafts.getBlob(b)).not.toBeNull()
    // Past the grace period and still unreferenced: collected. Referenced chunks stay.
    clock(120_000 + blobGrace + 1)
    drafts.putBlob(new TextEncoder().encode("chunk e"))
    drafts.set("other", "{}")
    drafts.flush()
    expect(drafts.getBlob(a)).not.toBeNull()
    expect(drafts.getBlob(c)).not.toBeNull()
    expect(drafts.getBlob(b)).toBeNull()
  })

  test("a document that republishes a cached chunk id refreshes the chunk without an upload", () => {
    const database = openDatabase(":memory:")
    const drafts = createDraftStore(database.db)
    const a = drafts.putBlob(new TextEncoder().encode("A"))
    drafts.set("doc", text(a))
    drafts.flush()
    // Edit away from A; A becomes unreferenced.
    const b = drafts.putBlob(new TextEncoder().encode("A!"))
    drafts.set("doc", text(b))
    drafts.flush()
    // Long after, undo republishes A from the renderer cache with no upload. The write touches A.
    clock(blobGrace - 1)
    drafts.set("doc", text(a))
    drafts.flush()
    clock(blobGrace + collectInterval)
    drafts.putBlob(new TextEncoder().encode("unrelated"))
    drafts.set("other", "{}")
    drafts.flush()
    expect(drafts.getBlob(a)).not.toBeNull()
    expect(drafts.getBlob(b)).toBeNull()
  })

  test("set reports referenced blobs the store does not hold so the renderer can upload them again", () => {
    const database = openDatabase(":memory:")
    const drafts = createDraftStore(database.db)
    const kept = drafts.putBlob(new TextEncoder().encode("kept"))
    const image = drafts.putBlob(new Uint8Array([9]))

    const document = JSON.stringify({
      prompt: [
        { type: "text", content: { blob: { kind: "text", ids: [kept, "gone-chunk"] } } },
        { type: "image", blob: { id: image } },
        { type: "image", blob: { id: "gone-image" } },
      ],
    })

    // A strict write with missing blobs is refused: the previous document remains.
    drafts.set("doc", JSON.stringify({ previous: true }))
    expect(drafts.set("doc", document, true).sort()).toEqual(["gone-chunk", "gone-image"])
    expect(drafts.get("doc")).toBe(JSON.stringify({ previous: true }))
    // A non-strict write stores it anyway and still reports what is missing.
    expect(drafts.set("doc", document, false).sort()).toEqual(["gone-chunk", "gone-image"])
    expect(drafts.get("doc")).toBe(document)
    expect(drafts.set("plain", "not json", true)).toEqual([])
    expect(drafts.set("doc", null, true)).toEqual([])
    expect(drafts.set("doc", document, true)).not.toContain(kept)
  })

  test("an uploaded attachment survives a due collection before its document is written", () => {
    const database = openDatabase(":memory:")
    const drafts = createDraftStore(database.db)
    drafts.putBlob(new TextEncoder().encode("old"))
    drafts.set("other", JSON.stringify({ n: 1 }))
    drafts.flush()
    clock(collectInterval + 1)
    // The renderer uploads first and saves the referencing document up to a second later.
    const image = drafts.putBlob(new Uint8Array([1, 2, 3]))
    drafts.set("other", JSON.stringify({ n: 2 }))
    drafts.flush()
    expect(drafts.getBlob(image)).not.toBeNull()
    drafts.set("doc", JSON.stringify({ prompt: [{ type: "image", blob: { id: image } }] }))
    drafts.flush()
    expect(drafts.getBlob(image)).not.toBeNull()
  })
})

import { createHash } from "node:crypto"
import { eq, sql } from "drizzle-orm"
import type { Database } from "./database"
import { blobs, document } from "./schema"
import { createWriteBehind } from "./write-behind"

export type DraftStore = ReturnType<typeof createDraftStore>

// Editing a large paste retires one text chunk per save, so orphans accumulate while the app runs.
const collectInterval = 60_000

// A blob stays collectable-proof for this long after its last upload or document reference. The
// renderer reuses a cached chunk id without uploading for far less than this (see
// draftChunkCacheTtl), so a reference it publishes always points at a retained blob.
export const blobGrace = 15 * 60_000

// Every blob id a document references: image parts `{ blob: { id } }` and text chunk lists
// `{ blob: { kind: "text", ids: [...] } }`. SQLite walks the JSON; nothing parses drafts in JS.
const referenced = (value: unknown) => sql`
  SELECT json_extract(node.value, '$.id') AS id
  FROM json_tree(${value}) AS node
  WHERE node.key = 'blob' AND node.type = 'object' AND json_type(node.value, '$.id') = 'text'
  UNION
  SELECT chunk.value AS id
  FROM json_tree(${value}) AS node, json_each(node.value, '$.ids') AS chunk
  WHERE node.key = 'blob' AND node.type = 'object' AND json_type(node.value, '$.ids') = 'array'
`

export function createDraftStore(
  db: Database,
  input: { collectDelay?: number; onError?: (error: unknown) => void } = {},
) {
  // Orphans left by an earlier session are collected once the window is up rather than before it:
  // the scan walks every stored document, and the usual grace keeps anything a renderer has
  // uploaded in the meantime.
  const startup = setTimeout(() => collectBlobs(db, Date.now() - blobGrace), input.collectDelay ?? 10_000)
  startup.unref()
  let collected = Date.now()
  let orphans = false
  const byKey = eq(document.key, sql.placeholder("key"))
  const read = db.select({ value: document.value }).from(document).where(byKey).prepare()
  const remove = db.delete(document).where(byKey).prepare()

  const upsert = db
    .insert(document)
    .values({ key: sql.placeholder("key"), value: sql.placeholder("value") })
    .onConflictDoUpdate({ target: document.key, set: { value: sql.placeholder("value") } })
    .prepare()

  const writer = createWriteBehind<string | null>({
    delay: 500,
    onError: input.onError,
    write: (batch) => {
      const at = Date.now()
      db.transaction(() => {
        for (const [key, value] of batch) {
          if (value === null) {
            remove.run({ key })
            continue
          }

          upsert.run({ key, value })

          // Referencing a blob keeps it alive; done here so a reference the renderer republished
          // from its cache is refreshed even though no upload happened.
          if (json(value))
            db.run(sql`UPDATE ${blobs} SET touched_at = ${at} WHERE ${blobs.id} IN (${referenced(value)})`)
        }
      })

      // Only a document rewrite can orphan a blob, so collect right after one when due.
      if (!orphans || at - collected < collectInterval) return
      collectBlobs(db, at - blobGrace)
      collected = at
      orphans = false
    },
  })

  return {
    get(key: string) {
      if (writer.has(key)) return writer.get(key) ?? null

      return read.get({ key })?.value ?? null
    },
    // Returns the referenced blob ids this store does not hold so the renderer can upload them
    // again. A strict write is refused while any are missing, so the previously stored document
    // stays visible instead of one with dangling references.
    set(key: string, value: string | null, strict = false) {
      const missing =
        value === null || !json(value)
          ? []
          : db
              .all<{
                id: string
              }>(sql`SELECT ref.id FROM (${referenced(value)}) AS ref WHERE ref.id NOT IN (SELECT ${blobs.id} FROM ${blobs})`)
              .map((row) => row.id)

      if (!strict || missing.length === 0) writer.set(key, value)

      return missing
    },
    putBlob(data: Uint8Array) {
      const id = createHash("sha256").update(data).digest("hex")
      const touched_at = Date.now()
      db.insert(blobs)
        .values({ id, data: Buffer.from(data), touched_at })
        .onConflictDoUpdate({ target: blobs.id, set: { touched_at } })
        .run()
      orphans = true

      return id
    },
    getBlob(id: string): Uint8Array<ArrayBuffer> | null {
      const data = db.select({ data: blobs.data }).from(blobs).where(eq(blobs.id, id)).get()?.data

      // node:sqlite allocates a dedicated ArrayBuffer per BLOB column value.
      return data ? (data as Uint8Array<ArrayBuffer>) : null
    },
    flush: writer.flush,
    close() {
      clearTimeout(startup)
      writer.close()
    },
  }
}

function json(value: string) {
  return value.startsWith("{") || value.startsWith("[")
}

// Drop blobs no stored document references and nothing has touched since `before`.
function collectBlobs(db: Database, before: number) {
  db.run(sql`
    DELETE FROM ${blobs}
    WHERE ${blobs.touched_at} < ${before === Infinity ? Number.MAX_SAFE_INTEGER : before}
      AND ${blobs.id} NOT IN (
        SELECT json_extract(node.value, '$.id')
        FROM ${document}, json_tree(${document.value}) AS node
        WHERE json_valid(${document.value}) AND node.key = 'blob' AND node.type = 'object'
          AND json_type(node.value, '$.id') = 'text'
        UNION
        SELECT chunk.value
        FROM ${document}, json_tree(${document.value}) AS node, json_each(node.value, '$.ids') AS chunk
        WHERE json_valid(${document.value}) AND node.key = 'blob' AND node.type = 'object'
          AND json_type(node.value, '$.ids') = 'array'
      )
  `)
}

export * as DesktopStorage from "./index"

import { app, BrowserWindow } from "electron"
import { Context, Effect, Layer, Path } from "effect"
import { marks } from "../lifecycle/marks"
import { openDatabase } from "./database"
import { setStorageSnapshotProvider } from "./snapshot"
import { createDraftStore } from "./drafts"
import { importLegacyStores } from "./legacy"
import { createStateStore } from "./state"
import { readEnableState } from "../extension/enable-state"

export type Interface = ReturnType<typeof make>

export class Service extends Context.Service<Service, Interface>()("opencode/desktop/DesktopStorage") {}

export const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const path = yield* Path.Path
    const runFork = Effect.runForkWith(yield* Effect.context())
    const userData = app.getPath("userData")

    const storage = make(path.join(userData, "drafts.sqlite"), (error) =>
      runFork(Effect.logError("storage flush failed", { error })),
    )

    yield* importLegacyStores(storage.db, userData).pipe(
      Effect.tap((result) =>
        result.removed.length === 0
          ? Effect.void
          : Effect.logInfo("imported legacy store files", { imported: result.imported, files: result.removed }),
      ),
      Effect.catch((error) => Effect.logWarning("failed to import legacy store files", { error })),
    )
    const wire = (_event: Electron.Event | undefined, win: BrowserWindow) => win.on("session-end", storage.flush)
    app.on("before-quit", storage.flush)
    app.on("browser-window-created", wire)
    BrowserWindow.getAllWindows().forEach((win) => wire(undefined, win))
    yield* Effect.addFinalizer(() =>
      Effect.sync(() => {
        app.off("before-quit", storage.flush)
        app.off("browser-window-created", wire)
        BrowserWindow.getAllWindows().forEach((win) => win.off("session-end", storage.flush))
        storage.close()
      }),
    )
    setStorageSnapshotProvider((names) => ({
      storage: Object.fromEntries(names.map((name) => [name, storage.state.items(name)])),
      extensions: readEnableState(storage.db.$client),
    }))
    marks.storage = Date.now()

    return Service.of(storage)
  }),
)

// The file keeps its historical name; renaming it would mean moving the drafts it already holds.
// SAFETY: this observer only reports caught write failures; it never interprets them as stored values.
// oxlint-disable-next-line anti-slop/no-unknown-parameters -- see SAFETY above
export function make(filename: string, onError?: (error: unknown) => void) {
  const database = openDatabase(filename)
  const state = createStateStore(database.db, { onError })
  const drafts = createDraftStore(database.db, { onError })

  return {
    db: database.db,
    state,
    drafts,
    flush() {
      state.flush()
      drafts.flush()
    },
    close() {
      state.close()
      drafts.close()
      database.close()
    },
  }
}

import { describe, expect, test } from "bun:test"
import { hasExistingAppState } from "./install-state"

const file = (name: string) => ({ name, directory: false })

const directory = (name: string) => ({ name, directory: true })

describe("hasExistingAppState", () => {
  test("recognizes state from an earlier OpenCode launch but not files Electron creates on a fresh install", () => {
    expect(hasExistingAppState([])).toBe(false)
    expect(hasExistingAppState([file("Local State"), directory("Crashpad")])).toBe(false)
    expect(hasExistingAppState([file("opencode.settings")])).toBe(true)
    expect(hasExistingAppState([file("opencode.global.dat")])).toBe(true)
    expect(hasExistingAppState([file("drafts.sqlite")])).toBe(true)
    expect(hasExistingAppState([file("window-state-abc.json")])).toBe(true)
    expect(hasExistingAppState([directory("opencode")])).toBe(true)
  })
