export function hasExistingAppState(entries: Array<{ name: string; directory: boolean }>) {
  return entries.some((entry) => {
    if (entry.name === "opencode.settings") return true

    if (entry.name.endsWith(".dat")) return true

    if (entry.name === "drafts.sqlite") return true

    if (/^window-state-.+\.json$/.test(entry.name)) return true

    return entry.directory && entry.name === "opencode"
  })
}

import { afterEach, beforeEach, describe, expect, setSystemTime, test } from "bun:test"
import { mkdtempSync, readdirSync, rmSync, utimesSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import path from "node:path"
import { NodeFileSystem, NodePath } from "@effect/platform-node"
import { sql } from "drizzle-orm"
import { Effect, Layer } from "effect"
import { openDatabase } from "./database"
import { importLegacyStores } from "./legacy"

const now = new Date("2026-07-01T00:00:00.000Z")

const day = 24 * 60 * 60 * 1000

const roots: string[] = []

beforeEach(() => setSystemTime(now))

afterEach(() => {
  setSystemTime()

  for (const root of roots.splice(0)) rmSync(root, { recursive: true, force: true })
})

function tempRoot() {
  const root = mkdtempSync(path.join(tmpdir(), "opencode-legacy-store-"))
  roots.push(root)

  return root
}

function writeStore(root: string, name: string, value: string, modified = now) {
  writeFileSync(path.join(root, name), value)
  utimesSync(path.join(root, name), modified, modified)
}

const listing = (root: string) => readdirSync(root).sort()

const rows = (db: ReturnType<typeof openDatabase>["db"]) =>
  db.all<{ name: string; key: string; value: string }>(sql`SELECT name, key, value FROM state ORDER BY name, key`)

const run = (db: ReturnType<typeof openDatabase>["db"], root: string) =>
  Effect.runPromise(
    importLegacyStores(db, root).pipe(Effect.provide(Layer.merge(NodeFileSystem.layer, NodePath.layer))),
  )

describe("legacy store import", () => {
  test("copies every namespace into state and removes the files", async () => {
    const root = tempRoot()
    const database = openDatabase(":memory:")
    writeStore(root, "opencode.global.dat", JSON.stringify({ model: "m", layout: { sidebar: 1 } }))
    writeStore(root, "opencode.window.w1.dat", JSON.stringify({ tabs: "[]" }))
    writeStore(root, "default.dat", JSON.stringify({ "settings.v3": "{}" }))
    writeStore(root, "opencode.settings", JSON.stringify({ keep: true }))
    writeStore(root, "unrelated.txt", "x")

    const result = await run(database.db, root)

    expect(result.imported).toBe(4)
    expect(rows(database.db)).toEqual([
      { name: "default.dat", key: "settings.v3", value: "{}" },
      { name: "opencode.global.dat", key: "layout", value: '{"sidebar":1}' },
      { name: "opencode.global.dat", key: "model", value: "m" },
      { name: "opencode.window.w1.dat", key: "tabs", value: "[]" },
    ])
    expect(listing(root)).toEqual(["opencode.settings", "unrelated.txt"])
  })

  test("does not overwrite state that already exists", async () => {
    const root = tempRoot()
    const database = openDatabase(":memory:")
    database.db.run(sql`INSERT INTO state VALUES ('opencode.global.dat', 'model', 'new', 0)`)
    writeStore(root, "opencode.global.dat", JSON.stringify({ model: "old" }))

    await run(database.db, root)

    expect(rows(database.db)).toEqual([{ name: "opencode.global.dat", key: "model", value: "new" }])
    expect(listing(root)).toEqual([])
  })

  test("leaves unreadable files in place", async () => {
    const root = tempRoot()
    const database = openDatabase(":memory:")
    writeStore(root, "opencode.global.dat", "{not json")
    writeStore(root, "opencode.workspace.x.dat", JSON.stringify({ terminal: "{}" }))

    const result = await run(database.db, root)

    expect(result.imported).toBe(1)
    expect(listing(root)).toEqual(["opencode.global.dat"])
  })

  test("applies draft retention: skips empty, stale, and excess draft files", async () => {
    const root = tempRoot()
    const database = openDatabase(":memory:")
    writeStore(root, "opencode.draft.empty.dat", "{}")
    writeStore(
      root,
      "opencode.draft.stale.dat",
      JSON.stringify({ "draft:prompt": "old" }),
      new Date(now.getTime() - 31 * day),
    )
    Array.from({ length: 102 }).forEach((_, index) =>
      writeStore(
        root,
        `opencode.draft.${index}.dat`,
        JSON.stringify({ "draft:prompt": `${index}` }),
        new Date(now.getTime() - index * 1_000),
      ),
    )

    const result = await run(database.db, root)

    expect(result.imported).toBe(100)
    const names = rows(database.db).map((row) => row.name)
    expect(names).toContain("opencode.draft.0.dat")
    expect(names).toContain("opencode.draft.99.dat")
    expect(names).not.toContain("opencode.draft.100.dat")
    expect(names).not.toContain("opencode.draft.101.dat")
    expect(names).not.toContain("opencode.draft.stale.dat")
    expect(names).not.toContain("opencode.draft.empty.dat")
    expect(listing(root)).toEqual([])
  })
})

import { Effect, FileSystem, Option, Path, Schema } from "effect"
import type { Database } from "./database"
import { state } from "./schema"

const DRAFT_RETENTION_MS = 30 * 24 * 60 * 60 * 1000

const DRAFT_KEEP_RECENT = 100

const Entries = Schema.fromJsonString(Schema.Record(Schema.String, Schema.Unknown))

const decode = Schema.decodeUnknownOption(Entries)

type Candidate = { name: string; path: string; modified: number; entries: Record<string, unknown> }

// Before the state table existed, every namespace the renderer persisted was an electron-store
// JSON file in userData. Copy them into SQLite once and remove them; this is the only place the
// storage layer touches the filesystem, and it runs before the first renderer request.
export const importLegacyStores = Effect.fn("DesktopStorage.importLegacyStores")(function* (
  db: Database,
  userData: string,
) {
  const fs = yield* FileSystem.FileSystem
  const path = yield* Path.Path
  const names = (yield* fs.readDirectory(userData).pipe(Effect.orElseSucceed(() => []))).filter(isStoreFile)

  const files = yield* Effect.forEach(
    names,
    Effect.fnUntraced(function* (name) {
      const file = path.join(userData, name)
      const stats = yield* fs.stat(file).pipe(Effect.orElseSucceed(() => undefined))

      if (stats?.type !== "File") return
      const raw = yield* fs.readFileString(file).pipe(Effect.orElseSucceed(() => undefined))

      if (raw === undefined) return
      const entries = decode(raw)

      if (Option.isNone(entries)) {
        yield* Effect.logWarning("legacy store is not readable, leaving it in place", { name })

        return
      }

      return {
        name,
        path: file,
        modified: Option.getOrElse(stats.mtime, () => new Date(0)).getTime(),
        entries: entries.value,
      } satisfies Candidate
    }),
    { concurrency: 5 },
  )

  const candidates = files.filter((file) => !!file)

  const kept = new Set(
    candidates
      .filter((file) => isDraft(file.name) && Object.keys(file.entries).length > 0)
      .filter((file) => Date.now() - file.modified <= DRAFT_RETENTION_MS)
      .sort((a, b) => b.modified - a.modified)
      .slice(0, DRAFT_KEEP_RECENT)
      .map((file) => file.name),
  )

  const rows = candidates
    .filter((file) => !isDraft(file.name) || kept.has(file.name))
    .flatMap((file) =>
      Object.entries(file.entries).map(([key, value]) => ({
        name: file.name,
        key,
        value: typeof value === "string" ? value : JSON.stringify(value),
        updated_at: file.modified,
      })),
    )

  // Existing rows win: a file left behind by an interrupted import must not overwrite newer state.
  if (rows.length > 0) {
    db.transaction((tx) => {
      rows.forEach((row) => tx.insert(state).values(row).onConflictDoNothing().run())
    })
  }

  yield* Effect.forEach(candidates, (file) => fs.remove(file.path, { force: true }), {
    concurrency: "unbounded",
    discard: true,
  })

  return { imported: rows.length, removed: candidates.map((file) => file.name) }
})

function isStoreFile(name: string) {
  return name === "default.dat" || /^opencode\..+\.dat$/.test(name)
}

function isDraft(name: string) {
  return name.startsWith("opencode.draft.")
}

import type { DatabaseSync } from "node:sqlite"
import { migrations } from "./migration.gen"

/** The desktop journal, usable by the early preload read without loading Drizzle or Effect. */
export function migrateDatabase(db: DatabaseSync) {
  db.exec("CREATE TABLE IF NOT EXISTS migration (id TEXT PRIMARY KEY, time_completed INTEGER NOT NULL)")

  const applied = new Set(db.prepare("SELECT id FROM migration").all().map((row) => row.id))

  // drafts.sqlite predates the journal: adopt its existing draft tables instead of creating them again.
  const legacy =
    applied.size === 0 &&
    db.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'document'").get() !== undefined

  const pending = migrations.filter((migration) => !applied.has(migration.id))

  if (pending.length === 0) return []
  db.exec("BEGIN")

  try {
    const record = db.prepare("INSERT INTO migration (id, time_completed) VALUES (?, ?)")
    pending.forEach((migration, index) => {
      if (!(legacy && index === 0)) migration.statements.forEach((statement) => db.exec(statement))
      record.run(migration.id, Date.now())
    })
    db.exec("COMMIT")
  } catch (error) {
    db.exec("ROLLBACK")
    throw error
  }

  return pending.map((migration) => migration.id)
}

import { blob, integer, primaryKey, sqliteTable, text } from "drizzle-orm/sqlite-core"

// Prompt drafts and history. `key` is `${storage}:${key}` as the renderer draft store writes it.
export const document = sqliteTable("document", {
  key: text().primaryKey(),
  value: text().notNull(),
})

// Images and text chunks referenced from documents by content hash. `touched_at` is the last time
// a blob was uploaded or a written document referenced it; collection leaves recent blobs alone.
export const blobs = sqliteTable("blob", {
  id: text().primaryKey(),
  data: blob({ mode: "buffer" }).notNull(),
  touched_at: integer().notNull().default(0),
})

// Everything the renderer persists through `platform.storage(name)`. `name` is the storage
// namespace the app chooses (still spelled like the `.dat` file it used to be) and `key` the
// entry within it, so the app's relocation and alias logic keeps working unchanged.
export const state = sqliteTable(
  "state",
  {
    name: text().notNull(),
    key: text().notNull(),
    value: text().notNull(),
    updated_at: integer().notNull(),
  },
  (table) => [primaryKey({ columns: [table.name, table.key] })],
)

// GUI extensions. Installed archives carry their manifest and a revision that changes on every
// install or reload; built-ins get a row only once their enable state changes.
export const extension = sqliteTable("extension", {
  id: text().primaryKey(),
  enabled: integer({ mode: "boolean" }).notNull().default(true),
  manifest: text(),
  revision: text(),
})

// Every file of an installed archive, keyed by its archive path.
export const extensionFile = sqliteTable(
  "extension_file",
  {
    extension_id: text().notNull(),
    path: text().notNull(),
    data: blob({ mode: "buffer" }).notNull(),
  },
  (table) => [primaryKey({ columns: [table.extension_id, table.path] })],
)

import { app, ipcMain } from "electron"
import { WindowSnapshotChannel, type WindowSnapshot } from "../../shared/ipc-transport"
import { isRendererUrl } from "../windows/scheme"
import { readWindowSnapshot } from "./window-snapshot"

// A window's preload asks for the namespaces its shell reads before the page runs, so the first
// render is the hydrated one. Until the storage layer is up (the first window asks before it exists)
// the answer comes from the database file; the layer takes over so later windows see queued writes.
type Provider = (names: ReadonlyArray<string>) => WindowSnapshot

let provider: Provider = (names) => readWindowSnapshot(app.getPath("userData"), names)

export function setStorageSnapshotProvider(next: Provider) {
  provider = next
}

export function registerStorageSnapshotHandler() {
  // SAFETY: Electron delivers untrusted IPC arguments; accept only an array whose every element is a string here.
  // oxlint-disable-next-line anti-slop/no-unknown-parameters -- see SAFETY above
  ipcMain.handle(WindowSnapshotChannel, (event, names: unknown): WindowSnapshot => {
    if (!isRendererUrl(event.senderFrame?.url)) return { storage: {} }

    // SAFETY: this dependency-free boundary check establishes the complete array-of-strings contract.
    // oxlint-disable-next-line anti-slop/no-runtime-typeof -- see SAFETY above
    if (!Array.isArray(names) || !names.every((name) => typeof name === "string")) return { storage: {} }

    return provider(names)
  })
}

