    const { db, store } = open()
    store.set("w1", "tabs", "[]")
    store.set("w2", "tabs", "[]")
    store.flush()
    store.set("w1", "recent", "{}")
    store.set("w2", "recent", "{}")
    store.clear("w1")
    expect(store.get("w1", "recent")).toBeNull()
    store.flush()
    expect(rows(db)).toEqual([
      { name: "w2", key: "recent", value: "{}" },
      { name: "w2", key: "tabs", value: "[]" },
    ])
  })

  test("a failed flush keeps every acknowledged write until a later flush succeeds", () => {
    const database = openDatabase(":memory:")
    const errors: unknown[] = []
    const store = createStateStore(database.db, { onError: (error) => errors.push(error) })
    store.set("w", "tabs", "[1]")
    store.set("w", "recent", "{}")
    database.db.run(sql`DROP TABLE state`)
    store.flush()
    expect(errors).toHaveLength(1)
    expect(store.get("w", "tabs")).toBe("[1]")
    database.db.run(
      sql`CREATE TABLE state (name TEXT NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (name, key))`,
    )
    store.set("w", "info", "{}")
    // A write made after the failure wins over the retried one.
    store.set("w", "tabs", "[2]")
    store.flush()
    expect(rows(database.db)).toEqual([
      { name: "w", key: "info", value: "{}" },
      { name: "w", key: "recent", value: "{}" },
      { name: "w", key: "tabs", value: "[2]" },
    ])
  })

  test("survives close and reopen on disk", async () => {
    const root = await mkdtemp(path.join(tmpdir(), "opencode-state-"))
    roots.push(root)
    const file = path.join(root, "drafts.sqlite")
    const first = openDatabase(file)
    const store = createStateStore(first.db)
    store.set("global", "model", "a")
    store.close()
    first.close()
    const second = openDatabase(file)
    expect(createStateStore(second.db).get("global", "model")).toBe("a")
    second.close()
  })
})

import { and, eq, sql } from "drizzle-orm"
import type { Database } from "./database"
import { state } from "./schema"
import { createWriteBehind } from "./write-behind"

export type StateStore = ReturnType<typeof createStateStore>

type Row = { name: string; key: string; value: string | null }

// Reads hit SQLite directly: they happen at mount time and a point lookup on the primary key
// costs microseconds, so a second in-memory copy would only duplicate the renderer's cache.
export function createStateStore(db: Database, input: { onError?: (error: unknown) => void } = {}) {
  // Prepared once; the flush loop then only binds values instead of rebuilding SQL per row.
  const byKey = and(eq(state.name, sql.placeholder("name")), eq(state.key, sql.placeholder("key")))
  const read = db.select({ value: state.value }).from(state).where(byKey).prepare()
  const remove = db.delete(state).where(byKey).prepare()

  const upsert = db
    .insert(state)
    .values({
      name: sql.placeholder("name"),
      key: sql.placeholder("key"),
      value: sql.placeholder("value"),
      updated_at: sql.placeholder("updated_at"),
    })
    .onConflictDoUpdate({
      target: [state.name, state.key],
      set: { value: sql.placeholder("value"), updated_at: sql.placeholder("updated_at") },
    })
    .prepare()

  const writer = createWriteBehind<Row>({
    delay: 250,
    onError: input.onError,
    write: (batch) =>
      db.transaction(() => {
        const updated_at = Date.now()

        for (const row of batch.values()) {
          if (row.value === null) remove.run({ name: row.name, key: row.key })
          else upsert.run({ name: row.name, key: row.key, value: row.value, updated_at })
        }
      }),
  })

  const id = (name: string, key: string) => `${name}\0${key}`
  const set = (name: string, key: string, value: string) => writer.set(id(name, key), { name, key, value })
  const unset = (name: string, key: string) => writer.set(id(name, key), { name, key, value: null })
  // Orders updates for renderer caches: acks and change events reach a window on different
  // paths, so a window compares revisions rather than arrival order. Process-local is enough
  // because every renderer cache dies with the process too.
  let revision = 0

  return {
    get(name: string, key: string) {
      const queued = writer.get(id(name, key))

      if (queued) return queued.value

      return read.get({ name, key })?.value ?? null
    },
    set,
    delete: unset,
    // A renderer loads a namespace once, so queued rows must be folded in for it to see its own
    // writes from a previous window session that have not flushed yet.
    items(name: string) {
      const items = Object.fromEntries(
        db
          .select({ key: state.key, value: state.value })
          .from(state)
          .where(eq(state.name, name))
          .all()
          .map((row) => [row.key, row.value]),
      )

      for (const row of writer.entries()) {
        if (row.name !== name) continue

        if (row.value === null) delete items[row.key]
        else items[row.key] = row.value
      }

      return { items, revision }
    },
    update(name: string, insert: Record<string, string>, removed: readonly string[]) {
      for (const [key, value] of Object.entries(insert)) set(name, key, value)

      for (const key of removed) unset(name, key)

      return ++revision
    },
    // Rare (window closed for good, explicit clear) so it goes straight to the database.
    clear(name: string) {
      writer.drop((row) => row.name === name)
      db.delete(state).where(eq(state.name, name)).run()
    },
    flush: writer.flush,
    close: writer.close,
  }
}

import { describe, expect, test } from "bun:test"
import { existsSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import path from "node:path"
import { createSettingsStore } from "./store"

const dir = () => mkdtempSync(path.join(tmpdir(), "opencode-settings-"))

describe("settings store", () => {
  test("reads the tab-indented file electron-store wrote and rewrites it in the same shape", () => {
    const file = path.join(dir(), "opencode.settings")
    writeFileSync(file, JSON.stringify({ windowIds: ["a"], backgroundColor: "#121212" }, null, "\t"))
    const store = createSettingsStore(file)
    expect(store.get("windowIds")).toEqual(["a"])
    store.set("backgroundColor", "#ffffff")
    expect(readFileSync(file, "utf8")).toBe(
      JSON.stringify({ windowIds: ["a"], backgroundColor: "#ffffff" }, null, "\t"),
    )
    expect(createSettingsStore(file).get("backgroundColor")).toBe("#ffffff")
  })

  test("starts empty without a file, creates it on the first write, and refuses undefined", () => {
    const file = path.join(dir(), "nested", "opencode.updater")
    const store = createSettingsStore(file)
    expect(store.get("ready")).toBeUndefined()
    expect(existsSync(file)).toBe(false)
    store.set("ready", { version: "1.0.0" })
    // Like electron-store, undefined is refused instead of treated as a delete.
    expect(() => store.set("ready", undefined)).toThrow(TypeError)
    expect(store.get("ready")).toEqual({ version: "1.0.0" })
    expect(JSON.parse(readFileSync(file, "utf8"))).toEqual({ ready: { version: "1.0.0" } })
    store.delete("ready")
    expect(store.get("ready")).toBeUndefined()
    expect(readFileSync(file, "utf8")).toBe("{}")
  })

  test("sets an unreadable file aside instead of failing", () => {
    const file = path.join(dir(), "opencode.settings")
    writeFileSync(file, "{ not json")
    const store = createSettingsStore(file)
    expect(store.get("anything")).toBeUndefined()
    expect(existsSync(`${file}.corrupt`)).toBe(true)
    store.set("firstLaunchOnboardingComplete", true)
    expect(JSON.parse(readFileSync(file, "utf8"))).toEqual({ firstLaunchOnboardingComplete: true })
  })
})

import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs"
import path from "node:path"
import electron from "electron"

import { SETTINGS_STORE } from "./keys"

const cache = new Map<string, SettingsStore>()

export type SettingsStore = ReturnType<typeof createSettingsStore>

// Main-process settings only (onboarding, default server, window list, appearance, extension storage).
// These are read synchronously before the storage layer exists and written on user action, so a
// synchronous whole-file write is acceptable here. Renderer state goes through DesktopStorage.
//
// The file is the tab-indented JSON object electron-store used to write, so existing profiles
// (and older builds) read the same data.
//
// We cannot instantiate the store at module load time because module import hoisting causes this
// to run before app.setPath("userData", ...) has executed, which would result in files being
// written to the default directory (e.g. bad: %APPDATA%\@opencode\desktop\opencode.settings vs
// good: %APPDATA%\ai.opencode.desktop.dev\opencode.settings).
export function getStore(name = SETTINGS_STORE) {
  const cached = cache.get(name)

  if (cached) return cached
  const next = createSettingsStore(path.join(electron.app.getPath("userData"), name))
  cache.set(name, next)

  return next
}

export function createSettingsStore(file: string) {
  let data = read(file)

  const write = () => {
    mkdirSync(path.dirname(file), { recursive: true })
    writeFileSync(`${file}.tmp`, JSON.stringify(data, null, "\t"))
    renameSync(`${file}.tmp`, file)
  }

  return {
    path: file,
    get: (key: string): unknown => data[key],
    set: (key: string, value: unknown) => {
      if (value === undefined) throw new TypeError(`Use \`delete()\` to clear values: ${key}`)
      data = { ...data, [key]: value }
      write()
    },
    delete: (key: string) => {
      data = Object.fromEntries(Object.entries(data).filter(([item]) => item !== key))
      write()
    },
  }
}

// A missing file is an empty store. An unreadable one is set aside instead of blocking startup.
function read(file: string): Record<string, unknown> {
  if (!existsSync(file)) return {}

  try {
    const parsed: unknown = JSON.parse(readFileSync(file, "utf8"))

    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? (parsed as Record<string, unknown>) : {}
  } catch {
    renameSync(file, `${file}.corrupt`)

    return {}
  }
}

