import { existsSync, readdirSync } from "node:fs"
import path from "node:path"
import { DatabaseSync } from "node:sqlite"
import type { WindowSnapshot } from "../../shared/ipc-transport"
import { migrateDatabase } from "./migration"
import { readEnableState } from "../extension/enable-state"

// Before the storage layer exists, nothing has been written in this process and every namespace is at revision 0.
// Legacy electron-store files can make storage stale, but explicit extension settings still come from SQLite.
export function readWindowSnapshot(userData: string, names: readonly string[]): WindowSnapshot {
  const file = path.join(userData, "drafts.sqlite")

  if (!existsSync(file)) return { storage: {}, extensions: [] }

  try {
    const legacy = readdirSync(userData).some((name) => name === "default.dat" || /^opencode\..+\.dat$/.test(name))
    const db = new DatabaseSync(file)

    try {
      migrateDatabase(db)

      const rows = db.prepare("SELECT key, value FROM state WHERE name = ?")

      return {
        storage: legacy
          ? {}
          : Object.fromEntries(
              names.map((name) => [
                name,
                {
                  // SAFETY: the journaled state table declares both selected columns TEXT NOT NULL.
                  items: Object.fromEntries(
                    (rows.all(name) as { key: string; value: string }[]).map((row) => [row.key, row.value]),
                  ),
                  revision: 0,
                },
              ]),
            ),
        extensions: readEnableState(db),
      }
    } finally {
      db.close()
    }
  } catch {
    return { storage: {} }
  }
}

// Coalesces a burst of writes into one batch. The latest value per key wins, so a store that
// re-serializes on every mutation costs one row write per flush instead of one per change.
export function createWriteBehind<T>(input: {
  delay: number
  write: (batch: Map<string, T>) => void
  onError?: (error: unknown) => void
}) {
  const pending = new Map<string, T>()
  let timer: ReturnType<typeof setTimeout> | undefined
  let closed = false

  const flush = () => {
    clearTimeout(timer)
    timer = undefined

    if (closed || pending.size === 0) return
    const batch = new Map(pending)
    pending.clear()

    try {
      input.write(batch)
    } catch (error) {
      // The renderer already saw these writes succeed. Keep them queued so the next flush retries
      // them; anything written for the same key since then takes precedence.
      for (const [key, value] of batch) if (!pending.has(key)) pending.set(key, value)

      if (!input.onError) throw error
      input.onError(error)
    }
  }

  return {
    get: (key: string) => pending.get(key),
    has: (key: string) => pending.has(key),
    entries: () => pending.values(),
    set(key: string, value: T) {
      if (closed) return
      pending.set(key, value)
      timer ??= setTimeout(flush, input.delay)
    },
    drop(predicate: (value: T) => boolean) {
      for (const [key, value] of pending) if (predicate(value)) pending.delete(key)
    },
    flush,
    close() {
      flush()
      closed = true
    },
  }
}

import { app, BrowserWindow, nativeImage, nativeTheme } from "electron"
import type { Path } from "effect"
import { type TitlebarTheme } from "../../shared/ipc-contract"
import { WindowFullscreenChanged, WindowPinchZoomChanged, WindowZoomChanged } from "../../shared/ipc-rpc/events"
import { emitIpcEvent } from "../ipc-events"
import type { DesktopPaths } from "../paths"
import { BACKGROUND_COLOR_KEY, PINCH_ZOOM_ENABLED_KEY } from "../storage/keys"
import { getStore } from "../storage/store"
import { storedBackgroundColor, titlebarOverlay, tone } from "./defaults"

const titlebarThemes = new WeakMap<BrowserWindow, Partial<TitlebarTheme>>()

const pinchZoomEnabled = new WeakMap<BrowserWindow, boolean>()

const maxZoomLevel = 10

const minZoomLevel = 0.2

let backgroundColor: string | undefined

export function windowAppearance(path: Path.Path, paths: DesktopPaths.Resolved) {
  const mode = tone()

  return {
    title: "OpenCode",
    icon: iconPath(path, paths),
    backgroundColor: backgroundColor ?? storedBackgroundColor(),
    ...(process.platform === "darwin"
      ? {
          titleBarStyle: "hidden" as const,
          trafficLightPosition: { x: 14, y: 14 },
        }
      : {}),
    ...(process.platform === "win32"
      ? {
          frame: false,
          titleBarStyle: "hidden" as const,
          titleBarOverlay: overlay({ mode }),
        }
      : {}),
    webPreferences: {
      preload: paths.preloadPath,
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
    },
  }
}

export function setDockIcon(path: Path.Path, paths: DesktopPaths.Resolved) {
  if (process.platform !== "darwin") return
  const icon = nativeImage.createFromPath(path.join(iconsDir(path, paths), "dock.png"))

  if (!icon.isEmpty()) app.dock?.setIcon(icon)
}

export function setBackgroundColor(color: string) {
  // The renderer reports its theme background on every boot; electron-store rewrites and fsyncs the
  // settings file on each set, so only persist a change.
  if (getBackgroundColor() !== color) getStore().set(BACKGROUND_COLOR_KEY, color)
  backgroundColor = color
  BrowserWindow.getAllWindows().forEach((win) => {
    win.setBackgroundColor(color)

    if (process.platform === "darwin") win.invalidateShadow()
  })
}

export function getBackgroundColor() {
  const stored = getStore().get(BACKGROUND_COLOR_KEY)

  return backgroundColor ?? (typeof stored === "string" ? stored : undefined)
}

export function setTitlebar(win: BrowserWindow, theme: Partial<TitlebarTheme> = {}) {
  titlebarThemes.set(win, theme)

  // Native window controls follow nativeTheme, not the renderer theme.
  if (process.platform === "darwin" || process.platform === "win32") {
    nativeTheme.themeSource = theme.scheme ?? theme.mode ?? "system"
  }

  updateTitlebar(win)
}

export function updateTitlebar(win: BrowserWindow) {
  if (process.platform !== "win32") return
  win.setTitleBarOverlay(overlay(titlebarThemes.get(win), win.webContents.getZoomFactor()))
}

export function setPinchZoomEnabled(enabled: boolean) {
  getStore().set(PINCH_ZOOM_ENABLED_KEY, enabled)
  BrowserWindow.getAllWindows().forEach((win) => {
    pinchZoomEnabled.set(win, enabled)
    emitIpcEvent(win.webContents, new WindowPinchZoomChanged({ enabled }))

    if (!enabled && win.webContents.getZoomFactor() !== 1) win.webContents.setZoomFactor(1)
    updateZoom(win)
  })
}

export function getPinchZoomEnabled() {
  return getStore().get(PINCH_ZOOM_ENABLED_KEY) === true
}

export function setZoomFactor(win: BrowserWindow, factor: number) {
  win.webContents.setZoomFactor(clampZoom(factor))
  updateZoom(win)
}

export function wireZoom(win: BrowserWindow) {
  pinchZoomEnabled.set(win, getPinchZoomEnabled())
  win.webContents.setZoomFactor(1)
  win.webContents.on("zoom-changed", (event, direction) => {
    event.preventDefault()

    if (pinchZoomEnabled.get(win)) {
      const delta = direction === "in" ? 0.2 : -0.2
      win.webContents.setZoomFactor(clampZoom(win.webContents.getZoomFactor() + delta))
      updateZoom(win)

      return
    }

    if (win.webContents.getZoomFactor() !== 1) win.webContents.setZoomFactor(1)
    updateZoom(win)
  })
}

export function wireFullscreen(win: BrowserWindow) {
  const send = (fullscreen: boolean) => {
    if (win.isDestroyed() || win.webContents.isDestroyed()) return
    emitIpcEvent(win.webContents, new WindowFullscreenChanged({ fullscreen }))
  }

  win.on("enter-full-screen", () => send(true))
  win.on("leave-full-screen", () => send(false))
}

function iconsDir(path: Path.Path, paths: DesktopPaths.Resolved) {
  return app.isPackaged ? path.join(process.resourcesPath, "icons") : path.join(paths.developmentResourcesRoot, "icons")
}

function iconPath(path: Path.Path, paths: DesktopPaths.Resolved) {
  return path.join(iconsDir(path, paths), `icon.${process.platform === "win32" ? "ico" : "png"}`)
}

function overlay(theme: Partial<TitlebarTheme> = {}, zoom = 1) {
  return titlebarOverlay(theme.mode ?? tone(), zoom)
}

function clampZoom(value: number) {
  return Math.min(Math.max(value, minZoomLevel), maxZoomLevel)
}

function updateZoom(win: BrowserWindow) {
  updateTitlebar(win)
  emitIpcEvent(win.webContents, new WindowZoomChanged({ factor: win.webContents.getZoomFactor() }))
}

import { app } from "electron"
import { Predicate } from "effect"
import { windowBootstrapArgument, type WindowBootstrap } from "../../shared/window-bootstrap"
import { FIRST_LAUNCH_ONBOARDING_COMPLETE_KEY } from "../storage/keys"
import { getStore } from "../storage/store"

// The settings store is already in memory when a window is created, so the renderer gets the
// answers its shell gate would otherwise ask for over IPC. A fresh install has no onboarding
// decision yet; the renderer asks once the layers have made one.
export function windowBootstrap(id: string): WindowBootstrap {
  const complete = getStore().get(FIRST_LAUNCH_ONBOARDING_COMPLETE_KEY)

  return {
    id,
    firstLaunchPending: Predicate.isBoolean(complete) ? !complete : undefined,
    packaged: app.isPackaged,
  }
}

export function windowArguments(id: string) {
  return [windowBootstrapArgument(windowBootstrap(id))]
}

import { resolveThemeVariant } from "@opencode/ui/theme/resolve"
import type { DesktopTheme } from "@opencode/ui/theme/types"
import { nativeTheme } from "electron"
import oc2ThemeJson from "../../../../ui/src/theme/themes/oc-2.json"
import { BACKGROUND_COLOR_KEY } from "../storage/keys"
import { getStore } from "../storage/store"

// Frame defaults shared by the early window (created on ready, before the renderer exists) and the
// full window setup in appearance.ts, so both draw the same frame.

const oc2Theme = oc2ThemeJson as DesktopTheme

// Match the renderer's 36px titlebar plus its former 8px content inset.
export const titlebarHeight = 44

export function tone() {
  return nativeTheme.shouldUseDarkColors ? "dark" : "light"
}

// The colour the renderer reported on its last run, or the default theme's for the system tone, so
// a window shown before the renderer paints already has the right background. Resolving a palette
// costs tens of milliseconds before the first window, so it only happens when nothing is stored.
export function storedBackgroundColor() {
  const stored = getStore().get(BACKGROUND_COLOR_KEY)

  if (typeof stored === "string") return stored
  const dark = tone() === "dark"

  return resolveThemeVariant(dark ? oc2Theme.dark : oc2Theme.light, dark)["background-base"]
}

export function titlebarOverlay(mode: "light" | "dark" = tone(), zoom = 1) {
  return {
    color: "#00000000",
    symbolColor: mode === "dark" ? "white" : "black",
    height: Math.max(titlebarHeight, Math.round(titlebarHeight * zoom)),
  }
}

import { randomUUID } from "node:crypto"
import path from "node:path"
import { fileURLToPath } from "node:url"
import { app, BrowserWindow, screen, shell } from "electron"
import { resolveExternalURL } from "../files/external-url"
import { windowArguments } from "./bootstrap"
import { WINDOW_IDS_KEY } from "../storage/keys"
import { getStore } from "../storage/store"
import { storedBackgroundColor, titlebarOverlay } from "./defaults"
import { registerRendererProtocol } from "./protocol"
import { loadWindow } from "./scheme"
import { allowRendererPermissions, wireNavigationPolicy, wireRendererHeaders } from "./security"
import { manageWindowState, readWindowState, resolveWindowState, windowStateFile, type WindowState } from "./window-state"

export type EarlyWindow = {
  id: string
  win: BrowserWindow
  state: WindowState
  shownAt: number
  // Navigation policy is wired before the layers exist; the adopter swaps in the logged version.
  openExternal: (url: string) => void
}

let pending: EarlyWindow | undefined

const displays = {
  all: () => screen.getAllDisplays().map((display) => display.bounds),
  primary: () => screen.getPrimaryDisplay().bounds,
  matching: (bounds: Electron.Rectangle) => screen.getDisplayMatching(bounds).bounds,
}

// Creates and shows the first restored window the moment Electron is ready, before the rest of the
// main process has loaded. The frame options mirror windowAppearance(); the persisted background
// colour stands in for the theme until the renderer applies it, so the window is on screen while the
// bundle, the layers and the renderer boot. restoreWindows() adopts it through takeEarlyWindow().
export function createEarlyWindow() {
  const ids = getStore().get(WINDOW_IDS_KEY)
  const id = Array.isArray(ids) && typeof ids[0] === "string" ? ids[0] : randomUUID()
  const root = path.dirname(fileURLToPath(import.meta.url))
  const file = path.join(app.getPath("userData"), windowStateFile(id))
  const state = resolveWindowState(readWindowState(file), { width: 1280, height: 800 }, displays)
  const icons = app.isPackaged ? path.join(process.resourcesPath, "icons") : path.join(root, "../../resources/icons")

  const win = new BrowserWindow({
    x: state.x,
    y: state.y,
    width: state.width,
    height: state.height,
    show: true,
    autoHideMenuBar: true,
    title: "OpenCode",
    icon: path.join(icons, `icon.${process.platform === "win32" ? "ico" : "png"}`),
    backgroundColor: storedBackgroundColor(),
    ...(process.platform === "darwin" ? { titleBarStyle: "hidden" as const, trafficLightPosition: { x: 14, y: 14 } } : {}),
    ...(process.platform === "win32" ? { frame: false, titleBarStyle: "hidden" as const, titleBarOverlay: titlebarOverlay() } : {}),
    webPreferences: {
      preload: path.join(root, "../preload/index.cjs"),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
      additionalArguments: windowArguments(id),
    },
  })

  manageWindowState(win, file, state, displays)
  // Closing the only window before the rest of the app has adopted it is a quit.
  win.once("closed", () => {
    if (pending?.win !== win) return
    pending = undefined
    app.quit()
  })

  const record: EarlyWindow = {
    id,
    win,
    state,
    shownAt: Date.now(),
    openExternal: (url) => {
      const target = resolveExternalURL(url)

      if (target) void shell.openExternal(target)
    },
  }

  pending = record
  // The renderer boots while the main bundle and layers load, instead of after them. Everything the
  // page needs before its first request is wired here; the IPC port arrives once the layers are up.
  registerRendererProtocol(path.join(root, "../renderer"))
  allowRendererPermissions(win)
  wireNavigationPolicy(win, (url) => record.openExternal(url))
  wireRendererHeaders(win)
  loadWindow(win, "index.html")
}

export function takeEarlyWindow() {
  const taken = pending
  pending = undefined

  return taken
}

import { describe, expect, test } from "bun:test"
import { addRendererHeaders, documentPolicyHeader, jsCallStacksDocumentPolicy } from "./headers"

describe("renderer response headers", () => {
  test("keeps the server's exact allow-headers list so Chromium can reuse the cached preflight", () => {
    const headers = {
      "access-control-allow-origin": ["oc://renderer"],
      "access-control-allow-headers": ["authorization"],
      "access-control-max-age": ["86400"],
    }

    addRendererHeaders(headers, { document: false })
    expect(headers).toEqual({
      "access-control-allow-origin": ["*"],
      "access-control-allow-headers": ["authorization"],
      "access-control-max-age": ["86400"],
    })
  })

  test("fills CORS headers for servers that send none, naming authorization explicitly", () => {
    const headers: Record<string, string[]> = { "content-type": ["application/json"] }
    addRendererHeaders(headers, { document: false })
    expect(headers["Access-Control-Allow-Origin"]).toEqual(["*"])
    expect(headers["Access-Control-Allow-Headers"]).toEqual(["*, authorization"])
    expect(headers["Access-Control-Max-Age"]).toEqual(["7200"])
  })

  test("adds the crash-report document policy only to renderer documents", () => {
    const document = {}
    addRendererHeaders(document, { document: true })
    expect(document[documentPolicyHeader]).toEqual([jsCallStacksDocumentPolicy])
    const asset = {}
    addRendererHeaders(asset, { document: false })
    expect(Object.keys(asset)).not.toContain(documentPolicyHeader)
  })
})

export const documentPolicyHeader = "Document-Policy"

export const jsCallStacksDocumentPolicy = "include-js-call-stacks-in-crash-reports"

// The renderer lives at oc://renderer, so every server it talks to is cross-origin. Servers that
// send no CORS headers get permissive ones here so the renderer can still reach them.
//
// A server's own `Access-Control-Allow-Headers` is kept as-is. Chromium reuses a cached preflight
// only when that header names `authorization` explicitly (`*` never covers it), so overwriting the
// server's exact list with `*` forced a fresh OPTIONS round trip in front of every API call.
export function addRendererHeaders(headers: Record<string, string | string[]>, options: { document: boolean }) {
  upsertHeader(headers, "Access-Control-Allow-Origin", ["*"])

  if (!hasHeader(headers, "Access-Control-Allow-Headers")) {
    upsertHeader(headers, "Access-Control-Allow-Headers", ["*, authorization"])
  }

  if (!hasHeader(headers, "Access-Control-Max-Age")) {
    // Chromium caps preflight cache lifetime at two hours; without the header it caches for 5s.
    upsertHeader(headers, "Access-Control-Max-Age", ["7200"])
  }

  if (options.document) upsertHeader(headers, documentPolicyHeader, [jsCallStacksDocumentPolicy])
}

export function hasHeader(headers: Record<string, string | string[]>, key: string) {
  return Object.keys(headers).some((header) => header.toLowerCase() === key.toLowerCase())
}

export function upsertHeader(headers: Record<string, string | string[]>, key: string, value: string | string[]) {
  const current = Object.keys(headers).find((header) => header.toLowerCase() === key.toLowerCase())
  headers[current ?? key] = value
}

import { randomUUID } from "node:crypto"
import { app, BrowserWindow, screen } from "electron"
import { Effect, FileSystem, Path } from "effect"
import { openExternalURL } from "../files"
import { scoped } from "../native/logging"
import { DesktopPaths } from "../paths"
import { DesktopStorage } from "../storage"
import { getStore } from "../storage/store"
import { WINDOW_IDS_KEY } from "../storage/keys"
import { windowDataFile } from "../../shared/ipc-transport"
import { windowArguments } from "./bootstrap"
import {
  getBackgroundColor,
  getPinchZoomEnabled,
  setBackgroundColor,
  setDockIcon,
  setPinchZoomEnabled,
  setTitlebar,
  setZoomFactor,
  updateTitlebar,
  windowAppearance,
  wireFullscreen,
  wireZoom,
} from "./appearance"
import { registerRendererProtocol, setProtocolReporter } from "./protocol"
import { loadWindow } from "./scheme"
import { createWindowRegistry } from "./registry"
import { makeWindowRecovery } from "./recovery"
import { takeEarlyWindow, type EarlyWindow } from "./early"
import { manageWindowState, readWindowState, resolveWindowState, windowStateFile } from "./window-state"
import { allowRendererPermissions, wireNavigationPolicy, wireRendererHeaders } from "./security"

const themeReady = new WeakMap<BrowserWindow, () => void>()

const displays = {
  all: () => screen.getAllDisplays().map((display) => display.bounds),
  primary: () => screen.getPrimaryDisplay().bounds,
  matching: (bounds: Electron.Rectangle) => screen.getDisplayMatching(bounds).bounds,
}

const registry = createWindowRegistry<BrowserWindow>({
  read: () => getStore().get(WINDOW_IDS_KEY),
  write: (ids) => getStore().set(WINDOW_IDS_KEY, ids),
})

const opened = new Set<(win: BrowserWindow) => void>()

let relaunchHandler = () => {
  setAppQuitting()
  app.relaunch()
  app.exit(0)
}

export {
  getBackgroundColor,
  getPinchZoomEnabled,
  registerRendererProtocol,
  setProtocolReporter,
  setBackgroundColor,
  setDockIcon,
  setPinchZoomEnabled,
  setTitlebar,
  setZoomFactor,
  updateTitlebar,
}

export function setRelaunchHandler(handler: () => void) {
  const previous = relaunchHandler
  relaunchHandler = handler

  return () => {
    if (relaunchHandler === handler) relaunchHandler = previous
  }
}

export function setAppQuitting(quitting = true) {
  registry.setQuitting(quitting)
}

export function getLastFocusedWindow() {
  const focused = BrowserWindow.getFocusedWindow()

  if (focused) return focused
  const win = registry.lastFocused()

  if (!win || win.isDestroyed()) return null

  return win
}

export function getWindowByID(id: string) {
  const win = registry.get(id)

  if (!win || win.isDestroyed()) return null

  return win
}

/** App windows that host the renderer, excluding popups and other native windows. */
export function getMainWindows() {
  return registry.list().filter((win) => !win.isDestroyed())
}

/** Runs for each app window as it registers, before its renderer loads. */
export function onMainWindow(listener: (win: BrowserWindow) => void) {
  opened.add(listener)

  return () => {
    opened.delete(listener)
  }
}

export function setWindowThemeReady(win: BrowserWindow) {
  themeReady.get(win)?.()
}

export const makeMainWindows = Effect.fn("Window.make")(function* () {
  const fs = yield* FileSystem.FileSystem
  const path = yield* Path.Path
  const paths = yield* DesktopPaths.resolve
  const storage = yield* DesktopStorage.Service
  const runFork = Effect.runForkWith(yield* Effect.context())
  const wireWindowRecovery = yield* makeWindowRecovery

  const restore = () => {
    // The entry module created and showed the first restored window on ready; it is adopted here,
    // before any renderer loads, so the user never waited for the layers to see a window.
    const early = takeEarlyWindow()
    const usable = early && !early.win.isDestroyed() ? early : undefined
    const ids = registry.persisted()
    const list = ids.length ? ids : [usable?.id ?? randomUUID()]

    if (usable && !list.includes(usable.id)) usable.win.destroy()

    return list.map((id) => create(id, usable?.id === id ? usable : undefined))
  }

  const create = (id: string = randomUUID(), early?: EarlyWindow) => {
    const stateFile = path.join(app.getPath("userData"), windowStateFile(id))
    const state = early?.state ?? resolveWindowState(readWindowState(stateFile), { width: 1280, height: 800 }, displays)
    const appearance = windowAppearance(path, paths)

    const win =
      early?.win ??
      new BrowserWindow({
        x: state.x,
        y: state.y,
        width: state.width,
        height: state.height,
        show: false,
        autoHideMenuBar: true,
        ...appearance,
        webPreferences: {
          ...appearance.webPreferences,
          additionalArguments: windowArguments(id),
        },
      })

    // The early window was secured and loaded when it was created; only its external-URL policy is
    // upgraded to the logged one.
    if (early) early.openExternal = (url) => runFork(openExternalURL(url))

    if (!early) {
      allowRendererPermissions(win)
      wireNavigationPolicy(win, (url) => runFork(openExternalURL(url)))
      wireRendererHeaders(win)
      manageWindowState(win, stateFile, state, displays)
    }

    wireWindowRecovery(win, id, () => relaunchHandler())
    register(win, id)
    wireFullscreen(win)

    if (!early) loadWindow(win, "index.html")
    wireZoom(win)
    let contentReady = false
    let appliedTheme = false
    let revealed = !!early

    const focusForTests = () => {
      if (app.isPackaged || process.env.OPENCODE_TEST_ONBOARDING !== "1") return

      if (process.platform === "darwin") app.focus({ steal: true })
      win.focus()
    }

    if (early) {
      focusForTests()
      runFork(Effect.logInfo("main window visible", { window: id, shownAt: early.shownAt }))
    }

    const reveal = () => {
      if (!contentReady || !appliedTheme || revealed || win.isDestroyed()) return
      revealed = true
      win.show()
      focusForTests()
      runFork(Effect.logInfo("main window visible", { window: id }))
    }

    const ready = () => {
      contentReady = true
      reveal()
    }

    themeReady.set(win, () => {
      appliedTheme = true
      reveal()
    })
    win.once("ready-to-show", ready)

    if (process.platform === "linux") win.webContents.once("did-finish-load", ready)
    win.once("closed", () => themeReady.delete(win))

    return win
  }

  const register = (win: BrowserWindow, id: string) => {
    registry.register(id, win)
    win.on("focus", () => registry.focused(id))
    // Windows emits session-end, but not before-quit, during shutdown and logoff.
    win.on("session-end", () => registry.setQuitting())
    win.on("closed", () => {
      if (!registry.closed(id)) return
      runFork(
        Effect.gen(function* () {
          yield* Effect.try(() => storage.state.clear(windowDataFile(id)))
          yield* fs.remove(path.join(app.getPath("userData"), windowStateFile(id)), { force: true })
        }).pipe(
          Effect.catch((error) => scoped("window", Effect.logError("failed to clean window state", { id, error }))),
        ),
      )
    })
    opened.forEach((listener) => listener(win))
  }

  return { create, restore }
})

import { net, protocol } from "electron"
import path from "node:path"
import { pathToFileURL } from "node:url"
import { documentPolicyHeader, jsCallStacksDocumentPolicy } from "./headers"
import { extensionHost, rendererHost, rendererProtocol } from "./scheme"

export type ProtocolReport = (level: "warning" | "error", message: string, data: Record<string, unknown>) => void

export type ExtensionAssets = (request: Request, url: URL) => Response | Promise<Response>

// The entry module registers the handler the moment the first window exists, before logging is up,
// so problems go to the console until the logging layer installs a reporter.
let report: ProtocolReport = (level, message, data) => console[level === "error" ? "error" : "warn"](message, data)

// Extension files live in the storage database, which opens after the first window starts loading.
let extensionAssets: ExtensionAssets = () => new Response(null, { status: 503 })

export function setProtocolReporter(reporter: ProtocolReport) {
  report = reporter
}

export function setExtensionAssets(provider: ExtensionAssets) {
  extensionAssets = provider
}

// Requests in flight and when the last one arrived. The entry module holds the main bundle back
// until the renderer's initial burst of asset requests has been answered, because this handler
// runs on the main thread and a 100 ms module evaluation would otherwise sit between the renderer
// and its HTML.
let inflight = 0

let served = 0

let lastRequest = 0

export function rendererAssetsServed(options: { quietMs: number; capMs: number }) {
  const start = Date.now()

  return new Promise<void>((resolve) => {
    const check = () => {
      const now = Date.now()

      if (now - start >= options.capMs) return resolve()

      if (served > 0 && inflight === 0 && now - lastRequest >= options.quietMs) return resolve()
      setTimeout(check, 5)
    }

    check()
  })
}

export function registerRendererProtocol(rendererRoot: string) {
  if (protocol.isProtocolHandled(rendererProtocol)) return

  protocol.handle(rendererProtocol, async (request) => {
    inflight++
    lastRequest = Date.now()

    try {
      return await serve(request, rendererRoot)
    } finally {
      inflight--
      served++
    }
  })
}

async function serve(request: Request, rendererRoot: string) {
  const url = new URL(request.url)

  if (url.host === extensionHost) {
    return Promise.resolve()
      .then(() => extensionAssets(request, url))
      .catch((error: unknown) => {
        report("error", "extension asset error", { url: request.url, error })

        return new Response(null, { status: 500 })
      })
  }

  if (url.host !== rendererHost) {
    report("warning", "rejected host", { url: request.url })

    return new Response("Not found", { status: 404 })
  }

  const file = path.resolve(rendererRoot, `.${decodeURIComponent(url.pathname)}`)
  const rel = path.relative(rendererRoot, file)

  if (rel.startsWith("..") || path.isAbsolute(rel)) {
    report("warning", "rejected path", { url: request.url, file })

    return new Response("Not found", { status: 404 })
  }

  try {
    const range = request.headers.get("range")
    const response = await net.fetch(pathToFileURL(file).toString(), { headers: range ? { range } : undefined })

    if (response.status >= 400) {
      report("error", "fetch failed", {
        url: request.url,
        file,
        status: response.status,
        statusText: response.statusText,
      })
    }

    return addDocumentPolicy(response, file)
  } catch (error) {
    report("error", "fetch error", { url: request.url, file, error })

    return new Response("Not found", { status: 404 })
  }
}

function addDocumentPolicy(response: Response, file: string) {
  if (!file.toLowerCase().endsWith(".html")) return response
  const headers = new Headers(response.headers)
  headers.set(documentPolicyHeader, jsCallStacksDocumentPolicy)

  return new Response(response.body, { status: response.status, statusText: response.statusText, headers })
}

import { app, dialog } from "electron"
import type { BrowserWindow } from "electron"
import { Effect } from "effect"
import { DesktopLogging, scoped } from "../native/logging"
import { nativeT } from "../native/translations"
import { safeWindowURL } from "./state"
import { makeUnresponsiveSampler } from "./unresponsive"

export const makeWindowRecovery = Effect.gen(function* () {
  const context = yield* Effect.context()
  const runFork = Effect.runForkWith(context)
  const runPromise = Effect.runPromiseWith(context)
  const logging = yield* DesktopLogging.Service
  const createUnresponsiveSampler = yield* makeUnresponsiveSampler

  function wireWindowRecovery(win: BrowserWindow, name: string, relaunch: () => void) {
    let showing = false
    const sampler = createUnresponsiveSampler(win, name)

    type RecoveryAction = "relaunch" | "export-logs" | "keep-waiting" | "quit"

    const handle = async (action: RecoveryAction | undefined, wait: boolean) => {
      if (action === "export-logs") {
        const sampling = sampler.stopAndFlush()
        await runPromise(logging.exportDebug).catch((error) =>
          runFork(Effect.logError("failed to export debug logs", { error })),
        )

        if (wait && sampling) sampler.start()

        return true
      }

      if (action === "relaunch") {
        sampler.stopAndFlush()
        relaunch()

        return false
      }

      if (action === "quit") {
        sampler.stopAndFlush()
        app.quit()
      }

      return false
    }

    const show = async (message: string, detail: string, wait: boolean) => {
      if (showing || win.isDestroyed()) return
      showing = true

      try {
        while (!win.isDestroyed()) {
          const actions: { id: RecoveryAction; label: string }[] = wait
            ? [
                { id: "relaunch", label: nativeT("desktop.recovery.action.relaunch") },
                { id: "export-logs", label: nativeT("desktop.recovery.action.exportLogs") },
                { id: "keep-waiting", label: nativeT("desktop.recovery.action.keepWaiting") },
              ]
            : [
                { id: "relaunch", label: nativeT("desktop.recovery.action.relaunch") },
                { id: "export-logs", label: nativeT("desktop.recovery.action.exportLogs") },
                { id: "quit", label: nativeT("desktop.recovery.action.quit") },
              ]

          const result = await dialog.showMessageBox(win, {
            type: "warning",
            buttons: actions.map((action) => action.label),
            defaultId: 0,
            cancelId: 2,
            message,
            detail,
          })

          if (await handle(actions[result.response]?.id, wait)) continue

          return
        }
      } finally {
        showing = false
      }
    }

    const failed = (
      event: string,
      errorCode: number,
      errorDescription: string,
      validatedURL: string,
      isMainFrame: boolean,
    ) => {
      runFork(
        scoped(
          "window",
          Effect.logError("renderer load failed", {
            window: name,
            event,
            errorCode,
            errorDescription,
            validatedURL,
            currentURL: safeWindowURL(win),
            isMainFrame,
          }),
        ),
      )

      if (!isMainFrame || errorCode === -3) return
      void show(
        nativeT("desktop.recovery.loadFailed"),
        nativeT("desktop.recovery.loadFailed.detail", {
          window: name,
          url: validatedURL,
          code: errorCode,
          description: errorDescription,
        }),
        false,
      )
    }

    win.webContents.on("did-fail-load", (_event, code, description, url, mainFrame) => {
      failed("did-fail-load", code, description, url, mainFrame)
    })
    win.webContents.on("did-fail-provisional-load", (_event, code, description, url, mainFrame) => {
      failed("did-fail-provisional-load", code, description, url, mainFrame)
    })
    win.webContents.on("render-process-gone", (_event, details) => {
      sampler.stopAndFlush()
      runFork(
        scoped(
          "window",
          Effect.logError("renderer process gone", { window: name, currentURL: safeWindowURL(win), details }),
        ),
      )
      void show(
        nativeT("desktop.recovery.terminated"),
        nativeT("desktop.recovery.terminated.detail", {
          window: name,
          reason: details.reason,
          code: details.exitCode ?? nativeT("desktop.recovery.unknown"),
        }),
        false,
      )
    })
    win.on("unresponsive", () => {
      runFork(
        scoped("window", Effect.logError("renderer unresponsive", { window: name, currentURL: safeWindowURL(win) })),
      )
      sampler.start()
      void show(nativeT("desktop.recovery.unresponsive"), nativeT("desktop.recovery.unresponsive.detail"), true)
    })
    win.on("responsive", () => {
      runFork(
        scoped("window", Effect.logError("renderer responsive", { window: name, currentURL: safeWindowURL(win) })),
      )
      sampler.stopAndFlush()
    })
    win.webContents.on("console-message", (event) => {
      if (event.message.toLowerCase().includes("terminal") || event.sourceId.toLowerCase().includes("terminal")) {
        runFork(
          scoped(
            "pty",
            Effect.logInfo("console", {
              window: name,
              level: event.level,
              message: event.message,
              line: event.lineNumber,
              sourceId: event.sourceId,
            }),
          ),
        )
      }
    })
    win.webContents.on("preload-error", (_event, path, error) => {
      runFork(scoped("preload", Effect.logError("preload error", { window: name, preloadPath: path, error })))
    })
  }

  return wireWindowRecovery
})

import { describe, expect, test } from "bun:test"
import { createWindowRegistry } from "./registry"

function setup(initial: unknown = []) {
  const state = { stored: initial }

  const registry = createWindowRegistry<{ name: string }>({
    read: () => state.stored,
    write: (ids) => {
      state.stored = ids
    },
  })

  return { registry, state }
}

function opened(...ids: string[]) {
  const app = setup()

  for (const id of ids) app.registry.register(id, { name: id })

  return app
}

describe("window registry", () => {
  test("restores persisted ids and ignores malformed entries", () => {
    expect(setup(["a", "", 42, "b"]).registry.persisted()).toEqual(["a", "b"])
    expect(setup("junk").registry.persisted()).toEqual([])
    expect(setup(undefined).registry.persisted()).toEqual([])
  })

  test("registers each id once and forgets a deliberately closed window", () => {
    const app = opened("a", "a", "b")
    expect(app.state.stored).toEqual(["a", "b"])
    expect(app.registry.get("a")).toEqual({ name: "a" })
    expect(app.registry.get("missing")).toBeUndefined()
    expect(app.registry.closed("a")).toBe(true)
    expect(app.state.stored).toEqual(["b"])
  })

  test("keeps ids for relaunch when the last window closes or the app quits", () => {
    const last = opened("a")
    expect(last.registry.closed("a")).toBe(false)
    expect(last.state.stored).toEqual(["a"])
    expect(setup(last.state.stored).registry.persisted()).toEqual(["a"])

    const quitting = opened("a", "b")
    quitting.registry.setQuitting()
    expect(quitting.registry.closed("a")).toBe(false)
    expect(quitting.registry.closed("b")).toBe(false)
    expect(quitting.state.stored).toEqual(["a", "b"])

    // A cancelled quit (such as a failed extension restart) resumes forgetting closed windows.
    const resumed = opened("a", "b")
    resumed.registry.setQuitting()
    resumed.registry.setQuitting(false)
    expect(resumed.registry.closed("a")).toBe(true)
    expect(resumed.state.stored).toEqual(["b"])
  })

  test("tracks the last focused window and falls back on close", () => {
    const app = opened("a", "b")
    app.registry.focused("a")
    expect(app.registry.lastFocused()).toEqual({ name: "a" })
    app.registry.closed("a")
    expect(app.registry.lastFocused()).toEqual({ name: "b" })
    app.registry.closed("b")
    expect(app.registry.lastFocused()).toBeUndefined()
  })
})

// Tracks open windows and the persisted window id list used to restore
// windows (and their per-window persisted state) across app launches.
export function createWindowRegistry<W>(persistence: {
  read: () => unknown
  write: (ids: string[]) => void
}) {
  const windows = new Map<string, W>()
  let quitting = false
  let lastFocusedID: string | undefined

  const persisted = () => {
    const value = persistence.read()

    if (!Array.isArray(value)) return []

    return value.filter((id): id is string => typeof id === "string" && id.length > 0)
  }

  return {
    persisted,
    setQuitting(value = true) {
      quitting = value
    },
    register(id: string, window: W) {
      windows.set(id, window)
      const ids = persisted()

      if (!ids.includes(id)) persistence.write([...ids, id])
    },
    focused(id: string) {
      lastFocusedID = id
    },
    lastFocused() {
      if (!lastFocusedID) return

      return windows.get(lastFocusedID)
    },
    get(id: string) {
      return windows.get(id)
    },
    list() {
      return [...windows.values()]
    },
    closed(id: string) {
      windows.delete(id)

      if (lastFocusedID === id) lastFocusedID = windows.keys().next().value

      // Only a deliberate close (app keeps running with other windows open)
      // forgets a window. Closing the last window quits the app and fires
      // `closed` before `before-quit`, so treat it as a quit and keep the id
      // for restore on next launch.
      if (quitting || windows.size === 0) return false
      persistence.write(persisted().filter((item) => item !== id))

      return true
    },
  }
}

import { protocol } from "electron"
import type { BrowserWindow } from "electron"

export const rendererProtocol = "oc"

export const rendererHost = "renderer"

/** Files of installed GUI extensions: `oc://extensions/<id>/<path>`. */
export const extensionHost = "extensions"

export function loadWindow(win: BrowserWindow, html: string) {
  const devUrl = process.env.ELECTRON_RENDERER_URL

  if (devUrl) {
    void win.loadURL(new URL(html, devUrl).toString())

    return
  }

  void win.loadURL(`${rendererProtocol}://${rendererHost}/${html}`)
}

export function isRendererUrl(value?: string, html = false) {
  if (!value || !URL.canParse(value)) return false
  const url = new URL(value)

  if (html && !url.pathname.endsWith(".html")) return false

  if (url.protocol === `${rendererProtocol}:` && url.host === rendererHost) return true
  const devUrl = process.env.ELECTRON_RENDERER_URL

  if (!devUrl || !URL.canParse(devUrl)) return false

  return url.origin === new URL(devUrl).origin
}

// Scheme privileges can only be granted before the app is ready, so the entry module calls this
// before it loads anything else.
export function registerRendererScheme() {
  protocol.registerSchemesAsPrivileged([
    {
      scheme: rendererProtocol,
      privileges: {
        secure: true,
        standard: true,
        supportFetchAPI: true,
        // Extension fonts and fetched assets are cross-origin to the renderer.
        corsEnabled: true,
        stream: true,
        // Let Chromium keep V8 bytecode for the renderer bundle between launches.
        codeCache: true,
      },
    },
  ])
}

import type { BrowserWindow } from "electron"
import { SidecarCredentials } from "../service/sidecar-credentials"
import { addRendererHeaders, hasHeader, upsertHeader } from "./headers"
import { isRendererUrl } from "./scheme"

const rendererPermissions = new Set(["clipboard-sanitized-write", "notifications"])

export function allowRendererPermissions(win: BrowserWindow) {
  const webContentsId = win.webContents.id
  win.webContents.session.setPermissionRequestHandler((webContents, permission, callback, details) => {
    callback(
      rendererPermissions.has(permission) && isRendererUrl(details.requestingUrl) && webContents.id === webContentsId,
    )
  })
  win.webContents.session.setPermissionCheckHandler((webContents, permission, requestingOrigin, details) => {
    if (!rendererPermissions.has(permission)) return false

    if (webContents && webContents.id !== webContentsId) return false

    return isRendererUrl(details.requestingUrl) || isRendererUrl(requestingOrigin)
  })
}

export function wireNavigationPolicy(win: BrowserWindow, openExternalURL: (url: string) => unknown) {
  win.webContents.setWindowOpenHandler(({ url }) => {
    if (!isRendererUrl(url)) openExternalURL(url)

    return { action: "deny" }
  })
  win.webContents.on("will-navigate", (event, url) => {
    if (isRendererUrl(url)) return
    event.preventDefault()
    openExternalURL(url)
  })
}

export function wireRendererHeaders(win: BrowserWindow) {
  // The renderer sends sidecar requests without credentials, so its GETs are CORS-simple and need no
  // preflight. Electron applies these listeners in Chromium's extraHeaders mode, after the CORS
  // decision, so adding Authorization here does not reintroduce one.
  //
  // Only the renderer's own top-level frame is credentialed. Other content in this session (web views,
  // embedded pages) can reach the same loopback origin and must not inherit its access. Requests with
  // no frame, such as from a service worker, are not credentialed either; the renderer registers none.
  win.webContents.session.webRequest.onBeforeSendHeaders(
    { urls: ["http://127.0.0.1/*", "http://localhost/*"] },
    (details, callback) => {
      const frame = details.frame
      const renderer = !!frame && frame.parent === null && isRendererUrl(frame.url)
      const authorization = renderer && SidecarCredentials.authorization(SidecarCredentials.get(), details.url)

      if (authorization && !hasHeader(details.requestHeaders, "Authorization")) {
        upsertHeader(details.requestHeaders, "Authorization", authorization)
      }

      callback({ requestHeaders: details.requestHeaders })
    },
  )
  win.webContents.session.webRequest.onHeadersReceived((details, callback) => {
    const responseHeaders = details.responseHeaders ?? {}
    addRendererHeaders(responseHeaders, { document: isRendererUrl(details.url, true) })
    callback({ responseHeaders })
  })
}

export const destroyedWindowURL = "<destroyed>"

type WebContentsURLState = {
  isDestroyed(): boolean
  getURL(): string
}

type WindowURLState = {
  isDestroyed(): boolean
  readonly webContents: WebContentsURLState
}

export function safeWebContentsURL(webContents: WebContentsURLState) {
  try {
    if (webContents.isDestroyed()) return destroyedWindowURL

    return webContents.getURL()
  } catch {
    return destroyedWindowURL
  }
}

export function safeWindowURL(win: WindowURLState) {
  try {
    if (win.isDestroyed()) return destroyedWindowURL

    return safeWebContentsURL(win.webContents)
  } catch {
    return destroyedWindowURL
  }
}

import type { BrowserWindow } from "electron"
import { Effect } from "effect"
import { scoped } from "../native/logging"
import { safeWindowURL } from "./state"

const sampleInterval = 1000

const samplePeriod = 15000

export const makeUnresponsiveSampler = Effect.gen(function* () {
  const runFork = Effect.runForkWith(yield* Effect.context())

  function createUnresponsiveSampler(win: BrowserWindow, name: string) {
    let sampleTimer: ReturnType<typeof setTimeout> | undefined
    let stopTimer: ReturnType<typeof setTimeout> | undefined
    let sampling = false
    const samples = new Map<string, number>()

    const active = () => sampling && !win.isDestroyed() && !win.webContents.isDestroyed()

    const clearTimers = () => {
      if (sampleTimer) clearTimeout(sampleTimer)

      if (stopTimer) clearTimeout(stopTimer)
      sampleTimer = undefined
      stopTimer = undefined
    }

    const schedule = () => {
      sampleTimer = setTimeout(() => {
        void collect()
      }, sampleInterval)
    }

    const collect = async () => {
      if (!active()) return

      const stack = await win.webContents.mainFrame.collectJavaScriptCallStack().catch((error) => {
        runFork(scoped("window", Effect.logError("failed to collect unresponsive sample", { window: name, error })))

        return undefined
      })

      if (!active()) return

      if (stack) samples.set(stack, (samples.get(stack) ?? 0) + 1)
      schedule()
    }

    const stopAndFlush = () => {
      const wasSampling = sampling
      sampling = false
      clearTimers()

      if (samples.size === 0) return wasSampling

      const entries = [...samples.entries()].sort((a, b) => b[1] - a[1])
      const total = entries.reduce((sum, entry) => sum + entry[1], 0)

      const message = [
        "renderer unresponsive samples",
        `Window: ${name}`,
        `URL: ${safeWindowURL(win)}`,
        ...entries.map((entry) => `<${entry[1]}> ${entry[0]}`),
        `Total Samples: ${total}`,
      ].join("\n")

      runFork(scoped("window", Effect.logError(message)))
      samples.clear()

      return wasSampling
    }

    const start = () => {
      if (sampling || win.isDestroyed() || win.webContents.isDestroyed() || win.webContents.isDevToolsOpened()) return
      sampling = true
      samples.clear()
      schedule()
      stopTimer = setTimeout(stopAndFlush, samplePeriod)
    }

    win.on("closed", stopAndFlush)

    return { start, stopAndFlush }
  }

  return createUnresponsiveSampler
})

import { describe, expect, test } from "bun:test"
import { mkdtempSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import path from "node:path"
import { readWindowState, resolveWindowState } from "./window-state"

const defaults = { width: 1280, height: 800 }

const primary = { x: 0, y: 0, width: 1920, height: 1080 }

const displays = {
  all: () => [primary, { x: 1920, y: 0, width: 2560, height: 1440 }],
  primary: () => primary,
  matching: () => primary,
}

describe("window state", () => {
  test("keeps bounds that still fit on a display", () => {
    const saved = { x: 2000, y: 100, width: 1000, height: 700, displayBounds: { x: 1920, y: 0, width: 2560, height: 1440 } }
    expect(resolveWindowState(saved, defaults, displays)).toEqual(saved)
  })

  test("falls back to the default size on the primary display when the saved display is gone", () => {
    const saved = { x: 5000, y: 100, width: 1000, height: 700, displayBounds: { x: 4480, y: 0, width: 1920, height: 1080 } }
    expect(resolveWindowState(saved, defaults, displays)).toEqual({ ...defaults, x: 0, y: 0, displayBounds: primary })
  })

  test("uses defaults without a position when nothing usable was saved", () => {
    expect(resolveWindowState(undefined, defaults, displays)).toEqual(defaults)
    expect(resolveWindowState({ width: 0, height: -1 }, defaults, displays)).toEqual(defaults)
    expect(resolveWindowState("junk", defaults, displays)).toEqual(defaults)
  })

  test("keeps a maximized flag even without bounds", () => {
    expect(resolveWindowState({ isMaximized: true }, defaults, displays)).toEqual({ ...defaults, isMaximized: true })
  })

  test("reads the file electron-window-state wrote and ignores an unreadable one", () => {
    const dir = mkdtempSync(path.join(tmpdir(), "opencode-window-state-"))
    const file = path.join(dir, "window-state-a.json")
    writeFileSync(
      file,
      '{"width":1280,"height":800,"x":0,"y":0,"displayBounds":{"x":0,"y":0,"width":3440,"height":1440},"isMaximized":false,"isFullScreen":false}',
    )
    expect(resolveWindowState(readWindowState(file), defaults, displays)).toEqual({
      width: 1280,
      height: 800,
      x: 0,
      y: 0,
      displayBounds: { x: 0, y: 0, width: 3440, height: 1440 },
      isMaximized: false,
      isFullScreen: false,
    })
    writeFileSync(file, "{oops")
    expect(readWindowState(file)).toBeUndefined()
    expect(readWindowState(path.join(dir, "missing.json"))).toBeUndefined()
  })
})

import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs"
import path from "node:path"
import type { BrowserWindow, Rectangle } from "electron"

// Remembers a window's bounds and maximized / fullscreen flags across launches in the same JSON
// file electron-window-state wrote, so existing profiles restore where they were.

export type WindowState = {
  x?: number
  y?: number
  width: number
  height: number
  displayBounds?: Rectangle
  isMaximized?: boolean
  isFullScreen?: boolean
}

export type Displays = {
  all: () => Rectangle[]
  primary: () => Rectangle
  matching: (bounds: Rectangle) => Rectangle
}

// Bounds are only trusted when they still fit on one of the current displays; otherwise the window
// falls back to the default size on the primary display. A saved maximized or fullscreen state
// without bounds is kept so manage() can restore it.
export function resolveWindowState(saved: unknown, defaults: { width: number; height: number }, displays: Displays) {
  const state = isState(saved) ? saved : undefined

  if (!state) return { width: defaults.width, height: defaults.height } satisfies WindowState

  if (!hasBounds(state)) {
    return state.isMaximized || state.isFullScreen
      ? ({ ...state, width: defaults.width, height: defaults.height } satisfies WindowState)
      : ({ width: defaults.width, height: defaults.height } satisfies WindowState)
  }

  if (!state.displayBounds) return state
  const visible = displays.all().some((bounds) => within(state, bounds))

  if (visible) return state

  return {
    width: defaults.width,
    height: defaults.height,
    x: 0,
    y: 0,
    displayBounds: displays.primary(),
  } satisfies WindowState
}

export function windowStateFile(id: string) {
  return `window-state-${id.replace(/[^a-zA-Z0-9._-]/g, "-")}.json`
}

export function readWindowState(file: string): unknown {
  if (!existsSync(file)) return undefined

  try {
    return JSON.parse(readFileSync(file, "utf8"))
  } catch {
    return undefined
  }
}

// Tracks the window until it closes and writes the final state then. Bounds are recorded while
// the window is in its normal state so a maximized window restores to its previous size.
export function manageWindowState(win: BrowserWindow, file: string, initial: WindowState, displays: Displays) {
  const state = { ...initial }

  if (state.isMaximized) win.maximize()

  if (state.isFullScreen) win.setFullScreen(true)
  let timer: ReturnType<typeof setTimeout> | undefined

  const update = () => {
    if (win.isDestroyed()) return
    const bounds = win.getBounds()

    if (!win.isMaximized() && !win.isMinimized() && !win.isFullScreen()) {
      state.x = bounds.x
      state.y = bounds.y
      state.width = bounds.width
      state.height = bounds.height
    }

    state.isMaximized = win.isMaximized()
    state.isFullScreen = win.isFullScreen()
    state.displayBounds = displays.matching(bounds)
  }

  const changed = () => {
    clearTimeout(timer)
    timer = setTimeout(update, 100)
  }

  const closed = () => {
    clearTimeout(timer)
    win.off("resize", changed)
    win.off("move", changed)
    win.off("close", update)
    win.off("closed", closed)
    mkdirSync(path.dirname(file), { recursive: true })
    writeFileSync(`${file}.tmp`, JSON.stringify(state))
    renameSync(`${file}.tmp`, file)
  }

  win.on("resize", changed)
  win.on("move", changed)
  win.on("close", update)
  win.on("closed", closed)
}

function isState(value: unknown): value is WindowState {
  return typeof value === "object" && value !== null
}

function hasBounds(state: WindowState): state is WindowState & Required<Pick<WindowState, "x" | "y">> {
  return (
    Number.isInteger(state.x) &&
    Number.isInteger(state.y) &&
    Number.isInteger(state.width) &&
    state.width > 0 &&
    Number.isInteger(state.height) &&
    state.height > 0
  )
}

function within(state: WindowState & { x: number; y: number }, bounds: Rectangle) {
  return (
    state.x >= bounds.x &&
    state.y >= bounds.y &&
    state.x + state.width <= bounds.x + bounds.width &&
    state.y + state.height <= bounds.y + bounds.height
  )
}

import { contextBridge, ipcRenderer, webUtils } from "electron"
import {
  DragCancelEvent,
  IpcTransportPort,
  WindowSnapshotChannel,
  storageSnapshotNames,
