// Load the complete preload contract before App's optional browser bridge declaration.
import {
  AppBaseProviders,
  AppInterface,
  currentRoute,
  PlatformProvider,
  preloadRoute,
  ServerConnection,
  useCommand,
  useCurrentRoute,
  useLanguage,
  useExtensionServers,
  useTabs,
  type LayoutRoute,
} from "@opencode/app/desktop"
import { useTheme } from "@opencode/ui/theme/context"
import type { BaseRouterProps } from "@solidjs/router"
import { createEffect, createMemo, createResource, lazy, Show, Suspense } from "solid-js"
import { createStore } from "solid-js/store"
import type { ElectronAPI } from "./api-types"
import { DesktopFirstLaunchOnboarding } from "./onboarding"
import { createDesktopPlatform } from "./platform"
import { bindDesktopMenu } from "./platform/menu"
import { createSidecarResolver, initializationData, sidecarHttp } from "./startup/initialization"
import { preloadStoredLocale } from "./startup/locale"
import { LoadingSplash } from "./startup/splash"
import { getLastActiveUrl } from "./window/route-storage"
import { DesktopMemoryRouter } from "./window/router"

const MigrationStatus = lazy(() => import("./migration-status").then((module) => ({ default: module.MigrationStatus })))

export function DesktopApp(props: { api: ElectronAPI; version: string }) {
  const windowState = { id: props.api.getWindowID(), version: props.version }
  const initialUrl = getLastActiveUrl(windowState.id)
  const url = new URL(initialUrl, "http://localhost")
  const route = currentRoute(url.pathname, url.search)

  const [startup, setStartup] = createStore({
    ready: false,
    visible: true,
    themeReady: false,
    onboardingReady: false,
    drawingReady: false,
    route,
  })

  // The window was created with the answers the shell gate needs; only a fresh install, which has no
  // onboarding decision yet, asks over IPC and waits for the port.
  const bootstrap = props.api.getWindowBootstrap()

  const [firstLaunch] = createResource(() =>
    bootstrap.firstLaunchPending !== undefined
      ? Promise.resolve(bootstrap.firstLaunchPending)
      : props.api.isFirstLaunchOnboardingPending().catch((error) => {
          console.error("[desktop-onboarding] first launch check failed", error)

          return false
        }),
  )

  const platform = createDesktopPlatform(props.api, windowState)
  const [sidecar, { mutate: setSidecar }] = createResource(() => props.api.awaitInitialization())

  const [locale] = createResource(() => preloadStoredLocale(platform))

  const [initialRoute] = createResource(
    () => !firstLaunch.loading && (firstLaunch() && initialUrl === "/" ? "/new-session" : initialUrl),
    preloadRoute,
  )

  const router = (routerProps: BaseRouterProps) => <DesktopMemoryRouter {...routerProps} windowID={windowState.id} />

  const readyToReveal = () =>
    startup.ready &&
    (!import.meta.env.OPENCODE_TEST_ONBOARDING || !firstLaunch() || initialUrl !== "/" || startup.drawingReady)

  // Reveal only after the theme and the first-launch splash choice are both resolved.
  createEffect(() => {
    if (!startup.themeReady || firstLaunch.loading) return
    void props.api.themeReady()
  })

  function ReadyApp() {
    const extensions = useExtensionServers()
    const language = useLanguage()

    const ready = createMemo(() => !firstLaunch.loading && !sidecar.loading && !locale.loading && extensions.ready())

    const servers = createMemo(() => {
      const data = initializationData(sidecar)
      const list: ServerConnection.Any[] = []

      if (data) {
        list.push({
          displayName: language.t("desktop.server.local"),
          type: "sidecar",
          variant: "base",
          http: sidecarHttp(data),
          reconnect: createSidecarResolver({ api: props.api, current: sidecar, update: setSidecar }),
        })
      }

      list.push(...extensions.list())

      return list
    })

    return (
      <Show when={ready()}>
        <AppInterface servers={servers()} router={router}>
          <DesktopStartupReady
            routeReady={!initialRoute.loading && startup.onboardingReady}
            onReady={() => setStartup("ready", true)}
            onRoute={(route) => setStartup("route", route)}
          />
          <DesktopFirstLaunchOnboarding
            api={props.api}
            initialUrl={initialUrl}
            pending={firstLaunch() ?? false}
            onReady={() => setStartup("onboardingReady", true)}
          />
          <DesktopEffects api={props.api} />
          <Suspense fallback={null}>
            <Show when={initializationData(sidecar)} keyed>
              {(server) => <MigrationStatus server={server} />}
            </Show>
          </Suspense>
        </AppInterface>
      </Show>
    )
  }

  return (
    <PlatformProvider value={platform}>
      <AppBaseProviders
        locale={locale.latest}
        onNativeTranslations={(bundle) => void props.api.setNativeTranslations(bundle).catch(() => undefined)}
        onThemeApplied={(mode, scheme) => {
          void props.api.setTitlebar({ mode, scheme })
          setStartup("themeReady", true)
        }}
      >
        <Show when={true}>{(_) => <ReadyApp />}</Show>
        <Show when={!firstLaunch.loading && startup.visible}>
          <div
            data-component="startup-overlay"
            class="fixed inset-0 z-[100] transition-opacity duration-300 ease-out"
            classList={{ "pointer-events-none opacity-0": readyToReveal() }}
            onTransitionEnd={(event) => {
              if (event.target !== event.currentTarget || !readyToReveal()) return
              setStartup("visible", false)
            }}
          >
            <LoadingSplash
              firstLaunch={!!firstLaunch() && initialUrl === "/"}
              deep={startup.route.type === "draft"}
              platform={platform}
              preview={import.meta.env.OPENCODE_TEST_ONBOARDING}
              onDrawEnd={() => setStartup("drawingReady", true)}
            />
          </div>
        </Show>
      </AppBaseProviders>
    </PlatformProvider>
  )
}

function DesktopStartupReady(props: {
  routeReady: boolean
  onReady: () => void
  onRoute: (route: LayoutRoute) => void
}) {
  const tabs = useTabs()
  const route = useCurrentRoute()
  createEffect(() => props.onRoute(route()))
  createEffect(() => {
    if (!props.routeReady || !tabs.ready() || !tabs.infoReady()) return
    props.onReady()
  })

  return null
}

function DesktopEffects(props: { api: ElectronAPI }) {
  const command = useCommand()
  bindDesktopMenu((id) => command.trigger(id))
  const theme = useTheme()

  createEffect(() => {
    theme.themeId()
    theme.mode()
    const background = getComputedStyle(document.documentElement).getPropertyValue("--background-base").trim()

    if (background) void props.api.setBackgroundColor(background)
  })

  return null
}

const resizeLoopWarning = "ResizeObserver loop completed with undelivered notifications."

if (import.meta.env.DEV) {
  installConsoleStacks()
  window.addEventListener("error", (event) => {
    if (event.message === resizeLoopWarning) event.preventDefault()
  })
}

function installConsoleStacks() {
  console.warn = tracedConsole(console.warn.bind(console), "Console warning")
  console.error = tracedConsole(console.error.bind(console), "Console error")
}

function tracedConsole(write: (...args: unknown[]) => void, label: string) {
  const pending = new Map<string, { count: number }>()

  return (...args: unknown[]) => {
    const stack = diagnosticStack(label)
    const key = `${String(args[0])}\n${stack}`
    const current = pending.get(key)

    if (current) {
      current.count += 1

      return
    }

    const entry = { count: 0 }
    pending.set(key, entry)
    write(...args, stack)
    window.setTimeout(() => {
      pending.delete(key)

      if (entry.count) write(`${String(args[0])} (repeated ${entry.count} times)`)
    }, 1_000)
  }
}

function diagnosticStack(label: string) {
  return new Error(label).stack ?? label
}

import { Predicate } from "effect"
import type { Bridge, BridgeMessage } from "@opencode/gui-extensions/sdk/bridge"
import type { ExtensionFailure } from "../shared/ipc-rpc/extensions"
import { api } from "./api"
import { cancellable, invoke, listen, send } from "./ipc-client"

/** The listeners' attachment to main's extension events, while any listener is registered. */
type Attachment = { stop?: () => void }

/** The renderer end of the GUI extension bridge; main hosts every Ipc, embed, and archive. */
export function createExtensionBridge(): Bridge {
  const listeners = new Set<(message: BridgeMessage) => void>()
  const dispatch = (message: BridgeMessage) => listeners.forEach((listener) => listener(message))
  const attached: Attachment = {}
  // MenubarItem contributions change through events; a window that starts listening late asks once.
  const menubar = { revision: 0 }

  const attach = () => {
    const stops = [
      listen("ExtensionState", (event) => dispatch({ type: "state", ipc: event.ipc, state: event.state })),
      listen("ExtensionEvent", (event) =>
        dispatch({ type: "event", ipc: event.ipc, name: event.name, data: event.data }),
      ),
      listen("ExtensionAvailable", (event) =>
        dispatch({ type: "available", ipc: event.ipc, available: event.available }),
      ),
      listen("ExtensionsChanged", (event) => dispatch({ type: "extensions", list: event.list })),
      listen("ExtensionMenubarItemsChanged", (event) => {
        menubar.revision++
        dispatch({ type: "menubarItems", items: event.items })
      }),
    ]

    const revision = menubar.revision
    void invoke("ExtensionMenubarItems").then((items) => {
      if (attached.stop && menubar.revision === revision) dispatch({ type: "menubarItems", items })
    })

    return () => stops.forEach((stop) => stop())
  }

  return {
    packaged: api.getWindowBootstrap().packaged ?? false,
    call: (input, signal) =>
      cancellable("ExtensionCall", input, signal).catch((cause: unknown) => {
        throw failure(cause)
      }),
    subscribe: (ipc) => invoke("ExtensionSubscribe", { ipc }),
    on(listener) {
      listeners.add(listener)
      attached.stop ??= attach()

      return () => {
        listeners.delete(listener)

        if (listeners.size > 0) return
        attached.stop?.()
        attached.stop = undefined
      }
    },
    embed: (id, layout) => send("ExtensionEmbed", { id, layout }),
    capture: (id) => invoke("ExtensionCapture", { id }).then((data) => data ?? undefined),
    runMenubarItem: (id) => send("ExtensionMenubarItem", { id }),
    configure: (servers) => send("ExtensionConfigure", { servers }),
    manager: {
      initial: window.electron.extensions,
      list: () => invoke("ExtensionList"),
      enable: (id) => manage(invoke("ExtensionEnable", { id })),
      disable: (id) => manage(invoke("ExtensionDisable", { id })),
      reload: (id) => manage(invoke("ExtensionReload", { id })),
      install: (source) =>
        manage(invoke("ExtensionInstall", { source: Predicate.isString(source) ? source : new Uint8Array(source) })),
      remove: (id) => manage(invoke("ExtensionRemove", { id })),
      source: (id) => manage(invoke("ExtensionSource", { id })),
      asset: (id, path) =>
        `oc://extensions/${encodeURIComponent(id)}/${path.split("/").map(encodeURIComponent).join("/")}`,
    },
  }
}

function manage<Value>(request: Promise<Value>) {
  return request.catch((cause: unknown) => {
    throw failure(cause)
  })
}

// Main fails with a code the renderer host maps to its own copy; the code is also the message.
function failure(cause: unknown) {
  if (!isFailure(cause)) return cause

  return Object.assign(new Error(cause.message ?? cause.code), { code: cause.code })
}

function isFailure(error: unknown): error is ExtensionFailure {
  return Predicate.hasProperty(error, "code") && Predicate.isString(error.code)
}

