import { OpenCode, type MigrationV1StatusOutput } from "@opencode/client/promise"
import { useLanguage } from "@opencode/app/desktop"
import { Loader } from "@opencode/ui/loader"
import { showToast, toaster, Toast } from "@opencode/ui/toast"
import { createRoot, createSignal, onCleanup, onMount } from "solid-js"
import type { ServerReadyData } from "../shared/ipc-contract"

type Progress = Extract<MigrationV1StatusOutput, { status: "running" }>["progress"]

export function MigrationStatus(props: { server: ServerReadyData }) {
  const language = useLanguage()
  const [progress, setProgress] = createSignal<Progress>()
  const abort = new AbortController()
  let toastID: number | undefined
  let disposeToast: (() => void) | undefined

  const format = (progress: Progress | undefined) => {
    if (!progress) return ""

    if (progress.label === "Clearing old events") return language.t("toast.migration.progress.clearingOldEvents")

    if (progress.label === "Migrating sessions") {
      if (progress.numerator === undefined) return language.t("toast.migration.progress.migratingSessions")

      if (progress.denominator === undefined)
        return language.t("toast.migration.progress.migratingSessions.current", { current: progress.numerator })

      return language.t("toast.migration.progress.migratingSessions.progress", {
        current: progress.numerator,
        total: progress.denominator,
      })
    }

    if (progress.numerator === undefined) return language.tDynamic("toast.migration.progress.working", progress.label)

    if (progress.denominator === undefined)
      return language.tDynamic("toast.migration.progress.working.current", `${progress.label} ${progress.numerator}`, {
        current: progress.numerator,
      })

    return language.tDynamic(
      "toast.migration.progress.working.progress",
      `${progress.label} ${progress.numerator}/${progress.denominator}`,
      { current: progress.numerator, total: progress.denominator },
    )
  }

  const hide = () => {
    if (toastID !== undefined) toaster.dismiss(toastID)
    toastID = undefined
    disposeToast?.()
    disposeToast = undefined
  }

  const show = () => {
    if (toastID !== undefined) return
    toastID = toaster.show(
      ({ toastId }) =>
        createRoot((dispose) => {
          disposeToast?.()
          disposeToast = dispose

          return (
            <Toast toastId={toastId}>
              <div data-slot="toast-v2-header" class="col-span-full">
                <Toast.Icon>
                  <Loader />
                </Toast.Icon>
                <Toast.Content>
                  <Toast.Title dir="auto">{format(progress())}</Toast.Title>
                </Toast.Content>
              </div>
            </Toast>
          )
        }),
      { persistent: true },
    )
  }

  onMount(async () => {
    await wait(1_000, abort.signal)

    if (abort.signal.aborted) return

    // The main process credentials sidecar requests; see `wireRendererHeaders`.
    const client = OpenCode.make({ baseUrl: props.server.url })

    void (async () => {
      while (true) {
        const status = await client.migration.v1.status({ signal: abort.signal })
        setProgress(status.status === "running" ? status.progress : undefined)

        if (status.status === "running") show()
        else hide()

        if (status.status === "completed") return

        if (status.status === "error") throw new Error(status.error)
        await wait(1_000, abort.signal)
      }
    })().catch((error) => {
      if (abort.signal.aborted) return
      hide()
      showToast({
        variant: "error",
        title: language.t("toast.migration.failed.title"),
        description: error instanceof Error ? error.message : String(error),
        duration: 10_000,
      })
    })
  })

  onCleanup(() => {
    abort.abort()
    hide()
  })

  return null
}

function wait(delay: number, signal: AbortSignal) {
  return new Promise<void>((resolve) => {
    const timer = setTimeout(done, delay)
    signal.addEventListener("abort", done, { once: true })

    function done() {
      clearTimeout(timer)
      signal.removeEventListener("abort", done)
      resolve()
    }
  })
}

import { ServerConnection, useCurrentRoute, useGlobal, useServers, useTabs } from "@opencode/app/desktop"
import { createResource } from "solid-js"
import type { ElectronAPI } from "../api-types"

export function DesktopFirstLaunchOnboarding(props: {
  api: ElectronAPI
  initialUrl: string
  pending: boolean
  onReady: () => void
}) {
  const server = useServers()
  const global = useGlobal()
  const tabs = useTabs()
  const route = useCurrentRoute()

  const [completed] = createResource(async () => {
    await runFirstLaunchOnboarding()

    return null
  })

  async function runFirstLaunchOnboarding() {
    try {
      if (!props.pending) return

      await Promise.all([tabs.ready.promise, tabs.recentReady.promise].map((p) => p ?? Promise.resolve()))

      const shouldTrigger =
        props.initialUrl === "/" &&
        route().type === "home" &&
        tabs.store.length === 0 &&
        server.list.every(ServerConnection.builtin)

      console.info("[desktop-onboarding] first launch onboarding evaluated", {
        pending: props.pending,
        shouldTrigger,
        initialUrl: props.initialUrl,
        tabs: tabs.store.length,
        servers: server.list.map(ServerConnection.key),
      })

      const directory = await props.api.finishFirstLaunchOnboarding(shouldTrigger)

      if (!shouldTrigger || !directory) return

      console.info("[desktop-onboarding] starting first launch draft", { directory })
      const sidecar = ServerConnection.Key.make("sidecar")
      const projects = server.projects.forServer(sidecar)
      projects.open(directory)
      projects.touch(directory)
      const connection = server.list.find((connection) => ServerConnection.key(connection) === sidecar)

      if (connection) {
        const data = global.ensureServerCtx(connection).data
        // Load the initial provider/model state before the draft transition exposes the composer.
        await Promise.all([data.location.provider.sync({ directory }), data.location.model.sync({ directory })])
      }

      tabs.select(await tabs.newDraft({ server: sidecar, directory }))
    } finally {
      props.onReady()
    }
  }

  // Let startup failures reach the app's recovery screen, including its splash boundary.
  return <>{completed()}</>
}

import { describe, expect, test } from "bun:test"
import { createDesktopFiles } from "./files"

function fileApi(events: string[]): Parameters<typeof createDesktopFiles>[0] {
  return {
    openDirectoryPicker: async () => null,
    openFilePicker: async () => ({
      token: "selection",
      files: [
        { path: "C:\\first.txt", name: "first.txt", size: 5 },
        { path: "C:\\second.txt", name: "second.txt", size: 6 },
      ],
    }),
    readPickedFile: async (_token: string, path: string) => {
      events.push(`read:${path}`)

      return new TextEncoder().encode(path).buffer
    },
    releasePickedFiles: async (token: string) => {
      events.push(`release:${token}`)
    },
    getPathForFile: () => "fallback",
    saveFile: async () => false,
    openExternal: () => {},
    openBrowser: async () => true,
    openLocalFile: () => {},
    resolveAppPath: async () => null,
    openPath: async () => undefined,
    revealPath: async () => false,
    readClipboardImage: async () => null,
    writeClipboardText: async (text: string) => {
      events.push(`clipboard:${text}`)
    },
  }
}

describe("desktop attachment files", () => {
  test("returns the native browser launch result and forwards clipboard text", async () => {
    const events: string[] = []
    const files = createDesktopFiles({ ...fileApi(events), openBrowser: async () => false }, "macos")

    expect(await files.openBrowser("https://opencode.ai/console")).toBe(false)
    await files.writeClipboardText("ses_123")
    expect(events).toEqual(["clipboard:ses_123"])
  })

  test("reads selected files sequentially and releases the token", async () => {
    const events: string[] = []
    const files = createDesktopFiles(fileApi(events), "windows")

    await files.openAttachmentPickerDialog({}, async (file) => {
      events.push(`file:${file.name}`)
    })

    expect(events).toEqual([
      "read:C:\\first.txt",
      "file:first.txt",
      "read:C:\\second.txt",
      "file:second.txt",
      "release:selection",
    ])
  })

  test("releases the token when a selected file callback fails", async () => {
    const events: string[] = []
    const files = createDesktopFiles(fileApi(events), "windows")

    await expect(
      files.openAttachmentPickerDialog({}, async () => {
        throw new Error("attachment rejected")
      }),
    ).rejects.toThrow("attachment rejected")
    expect(events.at(-1)).toBe("release:selection")
  })
})

import type { Platform } from "@opencode/app/desktop"
import type { ElectronAPI } from "../api-types"

type DesktopOS = Extract<Platform, { platform: "desktop" }>["os"]

type DesktopFileAPI = Pick<
  ElectronAPI,
  | "openDirectoryPicker"
  | "openFilePicker"
  | "readPickedFile"
  | "releasePickedFiles"
  | "getPathForFile"
  | "saveFile"
  | "openExternal"
  | "openBrowser"
  | "openLocalFile"
  | "resolveAppPath"
  | "openPath"
  | "revealPath"
  | "readClipboardImage"
  | "writeClipboardText"
>

export function createDesktopFiles(api: DesktopFileAPI, os: DesktopOS) {
  const attachmentPaths = new WeakMap<File, string>()

  const openDirectoryPickerDialog: Extract<Platform, { platform: "desktop" }>["openDirectoryPickerDialog"] = async (
    options,
  ) => {
    return api.openDirectoryPicker({
      multiple: options?.multiple ?? false,
      title: options?.title,
    })
  }

  const openAttachmentPickerDialog: NonNullable<Platform["openAttachmentPickerDialog"]> = async (options, onFile) => {
    const result = await api.openFilePicker({
      multiple: options?.multiple ?? false,
      title: options?.title,
      defaultPath: options?.defaultPath,
      extensions: options?.extensions,
    })

    if (!result) return

    try {
      for (const file of result.files) {
        const selected = new File([await api.readPickedFile(result.token, file.path)], file.name)
        attachmentPaths.set(selected, file.path)
        await onFile(selected)
      }
    } finally {
      await api.releasePickedFiles(result.token)
    }
  }

  return {
    openDirectoryPickerDialog,
    openAttachmentPickerDialog,
    getPathForFile: (file: File) => attachmentPaths.get(file) ?? api.getPathForFile(file),
    saveFile: (options: { title?: string; defaultPath?: string }, content: string) =>
      api.saveFile({ title: options.title, defaultPath: options.defaultPath }, content),
    openExternal: (url: string) => api.openExternal(url),
    openBrowser: (url: string) => api.openBrowser(url),
    openLocalFile: (url: string) => api.openLocalFile(url),
    async openPath(path: string, app?: string) {
      if (os !== "windows") {
        await api.openPath(path, app)

        return
      }

      const resolvedApp = app ? await api.resolveAppPath(app).catch(() => null) : null
      await api.openPath(path, resolvedApp ?? undefined)
    },
    async revealPath(path: string) {
      return api.revealPath(path)
    },
    async readClipboardImage() {
      const image = await api.readClipboardImage().catch(() => null)

      if (!image) return null

      return new File([new Blob([image.buffer], { type: "image/png" })], `pasted-image-${Date.now()}.png`, {
        type: "image/png",
      })
    },
    writeClipboardText(text: string) {
      return api.writeClipboardText(text)
    },
  }
}

import type { Platform } from "@opencode/app/desktop"
import type { ElectronAPI } from "../api-types"
import { setPinchZoomEnabled, webviewZoom } from "../window/zoom"
import { windowFullscreen } from "../window/fullscreen"
import { DragCancelEvent } from "../../shared/ipc-transport"
import { createExtensionBridge } from "../extensions"
import { createDesktopFiles } from "./files"
import { createDesktopMenuAction } from "./menu"
import { createDesktopNotify } from "./notifications"
import { createDesktopStorage } from "./storage"

export type DesktopWindowState = {
  id: string
  version: string
}

export function createDesktopPlatform(api: ElectronAPI, windowState: DesktopWindowState): Platform {
  const os = desktopOS()

  return {
    platform: "desktop",
    os,
    version: windowState.version,
    windowID: windowState.id,
    ...createDesktopFiles(api, os),
    ...createDesktopStorage(api),
    exportDebugLogs: () => api.exportDebugLogs(),
    setForceFocus: (enabled) => api.setForceFocus(enabled),
    recordFatalRendererError: (error) => api.recordFatalRendererError(error),
    restart: async () => api.relaunch(),
    notify: createDesktopNotify(api),
    fetch: (input, init) => {
      if (input instanceof Request) return fetch(input)

      return fetch(input, init)
    },
    webviewZoom,
    windowFullscreen,
    getPinchZoomEnabled: () => api.getPinchZoomEnabled(),
    setPinchZoomEnabled,
    onDragCancel: (callback) => {
      window.addEventListener(DragCancelEvent, callback)

      return () => window.removeEventListener(DragCancelEvent, callback)
    },
    runDesktopMenuAction: createDesktopMenuAction(api),
    checkAppExists: async (appName) => {
      return api.checkAppExists(appName)
    },
    extensions: createExtensionBridge(),
  }
}

function desktopOS() {
  if (navigator.userAgent.includes("Mac")) return "macos"

  if (navigator.userAgent.includes("Windows")) return "windows"

  if (navigator.userAgent.includes("Linux")) return "linux"

  return undefined
}

import type { Platform } from "@opencode/app/desktop"
import type { ElectronAPI } from "../api-types"
import { resetZoom, zoomIn, zoomOut } from "../window/zoom"

let trigger: ((id: string) => void) | null = null

export function startDesktopMenu(api: ElectronAPI) {
  api.onMenuCommand((id) => trigger?.(id))
}

export function bindDesktopMenu(next: (id: string) => void) {
  trigger = next
}

export function createDesktopMenuAction(api: ElectronAPI): NonNullable<Platform["runDesktopMenuAction"]> {
  return (action) => {
    switch (action) {
      case "view.resetZoom":
        resetZoom()

        return
      case "view.zoomIn":
        zoomIn()

        return
      case "view.zoomOut":
        zoomOut()

        return
    }

    return api.runDesktopMenuAction(action)
  }
}

import type { Platform } from "@opencode/app/desktop"
import type { ElectronAPI } from "../api-types"

export function createDesktopNotify(api: ElectronAPI): Platform["notify"] {
  return async (title, description, onClick) => {
    const focused = await api.getWindowFocused().catch(() => document.hasFocus())

    if (focused) return

    const notification = new Notification(title, {
      body: description ?? "",
      icon: "https://opencode.ai/favicon-96x96-v3.png",
      silent: true,
    })

    notification.onclick = () => {
      void api.showWindow()
      void api.setWindowFocus()
      onClick?.()
      notification.close()
    }
  }
}

import {
  createDraftStore,
  createNamespaceStorage,
  flushPersisted,
  type NamespaceStorage,
  type Platform,
} from "@opencode/app/desktop"
import type { ElectronAPI } from "../api-types"
import { onBeforeDispose } from "../ipc-client"

export function createDesktopStorage(api: ElectronAPI) {
  const namespaces = new Map<string, NamespaceStorage>()
  const driver = { items: api.storeItems, update: api.storeUpdate, clear: api.storeClear }

  const storage: NonNullable<Platform["storage"]> = (name = "default.dat") => {
    const cached = namespaces.get(name)

    if (cached) return cached
    const next = createNamespaceStorage(driver, name)
    namespaces.set(name, next)

    return next
  }

  // Dirty stores must serialize into their namespaces before the namespaces are sent; the app's
  // own pagehide listener registers after the IPC client's, so it cannot be relied on here.
  const flush = () => {
    flushPersisted()

    return Promise.all([...namespaces.values()].map((namespace) => namespace.flush()))
  }

  api.onStoreChanged((name, insert, remove, revision) => namespaces.get(name)?.accept(insert, remove, revision))
  // Durability boundaries: the window going away, and it leaving the foreground.
  onBeforeDispose(flush)
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "hidden") void flush()
  })

  return {
    storage,
    draftStore: createDraftStore({
      get: api.draftGet,
      set: api.draftSet,
      remove: api.draftDelete,
      putBlob: (blob) => blob.arrayBuffer().then(api.draftBlobPut),
      getBlob: (id) => api.draftBlobGet(id).then((data) => data && new Blob([data])),
    }),
  }
}

import type { ElectronAPI } from "../api-types"

const deepLinkEvent = "opencode:deep-link"

export function startDeepLinks(api: ElectronAPI) {
  void api.consumeInitialDeepLinks().then(emitDeepLinks)
  api.onDeepLink(emitDeepLinks)
}

function emitDeepLinks(urls: string[]) {
  if (urls.length === 0) return
  window.__OPENCODE__ ??= {}
  window.__OPENCODE__.deepLinks = [...(window.__OPENCODE__.deepLinks ?? []), ...urls]
  window.dispatchEvent(new CustomEvent(deepLinkEvent, { detail: { urls } }))
}

import { describe, expect, test } from "bun:test"
import { createSidecarResolver, initializationData } from "./initialization"

function failure(error: unknown) {
  try {
    initializationData(Object.assign(() => undefined, { error }))
  } catch (caught) {
    return caught
  }
}

describe("desktop renderer initialization", () => {
  test("throws the original initialization error, marked as a local server startup, before rendering", () => {
    const error = new Error("Cannot migrate session_message projections")
    expect(failure(error)).toBe(error)
    expect(error).toHaveProperty("localServerStartup", true)
    // The RPC error text reaches the error screen unchanged.
    expect(error.message).toBe("Cannot migrate session_message projections")
    // A falsy error is still an error.
    const empty = failure("")
    expect(empty).toBeInstanceOf(Error)
    expect(empty).toHaveProperty("message", "")
    expect(empty).toHaveProperty("localServerStartup", true)
    const sidecar = { url: "http://127.0.0.1:1234" }
    expect(initializationData(Object.assign(() => sidecar, { error: undefined }))).toBe(sidecar)
  })

  test("refreshes the managed sidecar endpoint", async () => {
    const sidecar = { url: "http://127.0.0.1:4321" }
    const updates: (typeof sidecar)[] = []

    const resolve = createSidecarResolver({
      api: { reconnectService: async () => sidecar },
      current: () => undefined,
      update: (next) => updates.push(next),
    })

    expect(await resolve(new AbortController().signal)).toEqual(sidecar)
    expect(updates).toEqual([sidecar])
  })

