    const resolve = createSidecarResolver({
      api: { reconnectService: () => pending.promise },
      current: () => undefined,
      update: (next) => updates.push(next),
    })

    const abort = new AbortController()
    const result = resolve(abort.signal)
    abort.abort()
    pending.resolve(sidecar)

