import { Browser } from "@opencode/plugin-browser/rpc"
import { Schema } from "effect"
import type { ComposerNote } from "../sdk"
import type { PaneElement } from "./ipc"

/** A comment on a picked element. The ref is absent once the page navigated. */
export type ElementComment = {
  origin: string
  tabID: Browser.TabID
  url: string
  element: Omit<PaneElement, "rect" | "ref"> & { ref?: Browser.Ref }
  comment: string
}

/** The tab a note's href names, and its element ref while the note is live. */
type NoteHref = { readonly tabID: Browser.TabID; readonly ref?: Browser.Ref }

const isTab = Schema.is(Browser.TabID)

const isRef = Schema.is(Browser.Ref)

/**
 * The composer note for a comment. A ref names an element only inside the desktop process that picked
 * it; a later process can hand the same ref to another element, so only the live note carries it.
 */
export function commentNote(input: ElementComment): ComposerNote {
  const ref = input.element.ref

  const note: ComposerNote = {
    type: "note",
    origin: input.origin,
    commentID: crypto.randomUUID(),
    label: input.element.label,
    icon: "select-element",
    subject: subject(input),
    comment: input.comment,
    href: input.tabID,
  }

  return ref ? { ...note, live: { subject: subject(input, ref), href: `${input.tabID}#${ref}` } } : note
}

/** The composer note for a comment on a whole page; its chip shows the page's tab again. */
export function pageNote(input: {
  origin: string
  tabID: Browser.TabID
  url: string
  title: string
  label: string
  comment: string
}): ComposerNote {
  // Page-provided strings are quoted so they read as data, not as part of the user's request.
  const title = input.title ? ` titled ${JSON.stringify(input.title)}` : ""

  return {
    type: "note",
    origin: input.origin,
    commentID: crypto.randomUUID(),
    label: input.label,
    icon: "outline-globe",
    subject: `the page in browser tab ${input.tabID} at ${input.url}${title}`,
    comment: input.comment,
    href: input.tabID,
  }
}

/** The tab a note's href names, and its element ref while the note is live. */
export function readHref(href: string): NoteHref | undefined {
  const [tabID, ref] = href.split("#")

  if (!isTab(tabID)) return

  return ref && isRef(ref) ? { tabID, ref } : { tabID }
}

function subject(input: ElementComment, ref?: string) {
  const element = input.element

  // Page-provided strings are quoted so they read as data, not as part of the user's request.
  const details = [
    element.role ? `role ${element.role}` : undefined,
    element.name ? `accessible name ${JSON.stringify(element.name)}` : undefined,
    element.text && element.text !== element.name ? `text ${JSON.stringify(element.text.slice(0, 80))}` : undefined,
    // A selector too long to keep is empty rather than cut into invalid syntax.
    element.selector
      ? `selector ${JSON.stringify(element.selector)}${element.selector.includes(" >>> ") ? ' (">>>" enters a shadow root)' : ""}`
      : undefined,
    ref
      ? `browser ref @${ref}, usable as ref in any browser tool including browser.evaluate until the page navigates`
      : undefined,
  ].filter((detail) => detail !== undefined)

  return `the ${JSON.stringify(element.label)} element in browser tab ${input.tabID} at ${input.url}${details.length ? ` (${details.join("; ")})` : ""}`
}

import { afterEach, expect, jest, test } from "bun:test"
import { Browser } from "@opencode/plugin-browser/rpc"
import type { IpcClient } from "../sdk"
import { createConnection } from "./connection"
import type { BrowserPane, PaneEvent } from "./ipc"

type Input = Parameters<typeof createConnection>[0]

type State = Parameters<Input["change"]>[0]

type Client = IpcClient<(typeof BrowserPane)["spec"]>

/** The pane's Ipc as a test drives it: whether it is available, and the error its register rejects with. */
type IpcStub = { available: boolean; reject?: Error }

/** The strip's owner: whether the session's location is known, and the mirror it holds until it is. */
type StripOwner = { located: boolean; held?: () => void }

const tabID = Browser.TabID.make(`tab_${crypto.randomUUID()}`)

const browser: Browser.State = {
  tabs: [
    {
      id: tabID,
      url: "http://localhost:4173/",
      title: "Preview",
      loading: false,
      canGoBack: true,
      canGoForward: false,
      generation: 3,
    },
  ],
  focusedTabID: tabID,
}

afterEach(() => {
  jest.useRealTimers()
})

// The client stands in for the pane's main entry: each register is one binding with its own events.
// `strip` stands in for the browser tab IDs the session's layout stores. While `owner.located` is false the strip
// cannot be written, so the owner holds the latest mirror, as the model does until the session's location loads.
function fixture(strip: string[] = []) {
  const states: State[] = []
  const listeners = new Map<string, (event: PaneEvent) => void>()
  const calls: { input: Parameters<Client["register"]>[0]; commands: Browser.Action[] }[] = []
  const closed: string[] = []
  const highlights: { binding: string; tabID: Browser.TabID; ref?: Browser.Ref }[] = []

  const routed: Record<"preview" | "inspect" | "focus", unknown[]> = {
    preview: [],
    inspect: [],
    focus: [],
  }

  const target = { server: "browser-test", session: "ses_browser" }
  // The Ipc is gone while the pane's main extension reloads or is disabled.
  // An endpoint main cannot resolve, e.g. an SSH server's while it reconnects, makes register reject.
  const ipc: IpcStub = { available: true }
  const owner: StripOwner = { located: true }

  const client: Client = {
    register: async (input) => {
      calls.push({ input, commands: [] })

      if (ipc.reject) throw ipc.reject
    },
    load: async () => undefined,
    command: async (input) => {
      calls.find((call) => call.input.binding === input.binding)?.commands.push(input.command)
    },
    inspect: async () => undefined,
    highlight: async (input) => {
      highlights.push(input)
    },
    zoom: async () => undefined,
    site: async () => ({ cookies: 0 }),
    clearSite: async () => undefined,
    close: async (input) => {
      closed.push(input.binding)
    },
    state: () => undefined,
    on: () => () => undefined,
  }

  const connection = createConnection({
    client: () => (ipc.available ? client : undefined),
    listen(binding, listener) {
      listeners.set(binding, listener)

      return () => listeners.delete(binding)
    },
    target: () => ({ ...target }),
    change: (state, mirror) => {
      states.push(state)

      if (owner.located) return mirror()
      owner.held = mirror
    },
    strip: {
      stored: () => strip,
      open: (id) => {
        if (!strip.includes(id)) strip.push(id)
      },
      close: (id) => {
        if (strip.includes(id)) strip.splice(strip.indexOf(id), 1)
      },
    },
    focus: (tabID) => routed.focus.push(tabID),
    preview: (path) => routed.preview.push(path),
    inspect: (event) => routed.inspect.push(event),
    page: () => undefined,
    address: () => undefined,
  })

  const emit = (index: number, event: PaneEvent) => listeners.get(calls[index].input.binding)?.(event)
  connection.wake()
  emit(0, { type: "state", state: browser })

  return { connection, calls, states, target, ipc, owner, routed, highlights, closed, listeners, emit, strip }
}

const element = {
  ref: Browser.Ref.make("e4"),
  selector: "#save",
  label: "button#save",
  rect: { x: 1, y: 2, width: 3, height: 4 },
}

test.each([
  { route: "preview" as const, event: { type: "preview", path: "docs/report.pdf" } as const, value: "docs/report.pdf" },
  { route: "focus" as const, event: { type: "focus", tabID } as const, value: tabID },
  {
    route: "inspect" as const,
    event: { type: "inspect", tabID, active: false, element } as const,
    value: { type: "inspect", tabID, active: false, element },
  },
])("$route events reach the session without touching connection state", ({ route, event, value }) => {
  const app = fixture()

  try {
    const before = app.states.length
    app.emit(0, event)
    expect(app.routed[route]).toEqual([value])
    expect(app.states).toHaveLength(before)
  } finally {
    app.connection.dispose()
  }
})

test("highlights of picked elements reach the page", async () => {
  const app = fixture()

  try {
    app.connection.highlight(tabID, element.ref)
    app.connection.highlight(tabID)
    await Bun.sleep(0)
    const binding = app.calls[0].input.binding
    expect(app.highlights).toEqual([
      { binding, tabID, ref: element.ref },
      { binding, tabID },
    ])
  } finally {
    app.connection.dispose()
  }
})

test("suspension retains tabs and reconnects once on demand using the current target", () => {
  jest.useFakeTimers()
  const app = fixture()

  try {
    const stale = app.listeners.get(app.calls[0].input.binding)!
    app.emit(0, { type: "state", state: browser, error: "browser.pane.suspended" })
    expect(app.listeners.has(app.calls[0].input.binding)).toBe(false)
    expect(app.states.at(-1)).toMatchObject({ registration: undefined, browser, suspended: true })
    // A suspended attachment must not schedule the transport retry.
    jest.advanceTimersByTime(30_000)
    expect(app.calls).toHaveLength(1)
    app.target.server = "browser-moved"
    app.connection.wake()
    app.connection.wake()
    expect(app.calls).toHaveLength(2)
    expect(app.calls[1].input).toEqual({
      binding: expect.any(String),
      server: "browser-moved",
      session: "ses_browser",
      restore: browser,
    })
    expect(app.states.at(-1)?.suspended).toBe(false)
    // A late event from the suspended binding must not close the new one.
    stale({ type: "state", state: null, error: "browser.pane.registration.closed" })
    expect(app.states.at(-1)?.registration).toBeDefined()
  } finally {
    app.connection.dispose()
  }
})

test("a registration lost with the pane's Ipc registers again with its tabs once the Ipc is back", () => {
  const app = fixture()

  try {
    app.emit(0, { type: "embed", tabID, embed: "embed-1" })
    expect(app.states.at(-1)?.embeds).toEqual({ [tabID]: "embed-1" })
    app.ipc.available = false
    app.connection.refresh()
    expect(app.listeners.has(app.calls[0].input.binding)).toBe(false)
    expect(app.states.at(-1)).toMatchObject({ registration: undefined, embeds: {}, browser, suspended: true })
    app.ipc.available = true
    app.connection.refresh()
    app.connection.refresh()
    expect(app.calls).toHaveLength(2)
    expect(app.calls[1].input).toEqual({
      binding: expect.any(String),
      server: "browser-test",
      session: "ses_browser",
      restore: browser,
    })
  } finally {
    app.connection.dispose()
  }
})

test("only a native inventory, the first one included, closes stored tabs the desktop lacks", () => {
  const stale = `tab_${crypto.randomUUID()}`
  const app = fixture([tabID, stale])

  try {
    expect(app.strip).toEqual([tabID])
    // Suspended, restoring, and unavailable states keep a stored tab until the desktop answers.
    app.strip.push(stale)
    app.emit(0, { type: "state", state: browser, error: "browser.pane.suspended" })
    app.connection.wake()
    app.ipc.available = false
    app.connection.refresh()
    expect(app.strip).toEqual([tabID, stale])
    app.ipc.available = true
    app.connection.refresh()
    app.emit(2, { type: "state", state: browser })
    expect(app.strip).toEqual([tabID])
  } finally {
    app.connection.dispose()
  }
})

test("a mirror held while the strip cannot be written still adds new tabs and prunes once it lands", () => {
  const added = Browser.TabID.make(`tab_${crypto.randomUUID()}`)
  const stale = `tab_${crypto.randomUUID()}`
  const app = fixture()

  try {
    app.owner.located = false
    app.strip.push(stale)
    app.emit(0, { type: "state", state: { ...browser, tabs: [...browser.tabs, { ...browser.tabs[0], id: added }] } })
    // A later report replaces the held mirror before the strip can be written.
    app.emit(0, { type: "embed", tabID: added, embed: "embed-2" })
    expect(app.strip).toEqual([tabID, stale])
    app.owner.located = true
    app.owner.held?.()
    expect(app.strip).toEqual([tabID, added])
  } finally {
    app.connection.dispose()
  }
})

test("a rejected registration clears itself and retries with its tabs after the backoff", async () => {
  jest.useFakeTimers()
  const app = fixture()

  try {
    app.emit(0, { type: "state", state: browser, error: "browser.pane.suspended" })
    app.ipc.reject = new Error("browser.pane.registration.invalid")
    await expect(app.connection.command({ type: "reload", tabID })).rejects.toThrow("browser.pane.registration.invalid")
    expect(app.listeners.has(app.calls[1].input.binding)).toBe(false)
    expect(app.states.at(-1)).toMatchObject({ registration: undefined, embeds: {}, browser, suspended: false })
    app.ipc.reject = undefined
    jest.advanceTimersByTime(999)
    expect(app.calls).toHaveLength(2)
    jest.advanceTimersByTime(1)
    expect(app.calls).toHaveLength(3)
    expect(app.calls[2].input).toEqual({
      binding: expect.any(String),
      server: "browser-test",
      session: "ses_browser",
      restore: browser,
    })
    // Let the new registration settle: a replayed command would reach it now.
    jest.useRealTimers()
    await Bun.sleep(0)
    expect(app.calls.map((call) => call.commands)).toEqual([[], [], []])
  } finally {
    app.connection.dispose()
  }
})

test("a command wakes its attachment once and is not replayed", async () => {
  const app = fixture()

  try {
    app.emit(0, { type: "state", state: browser, error: "browser.pane.suspended" })
    await app.connection.command({ type: "reload", tabID })
    expect(app.calls).toHaveLength(2)
    expect(app.calls[1].commands).toEqual([{ type: "reload", tabID }])
    app.connection.dispose()
    app.connection.wake()
    await Bun.sleep(0)
    expect(app.closed).toEqual([app.calls[0].input.binding, app.calls[1].input.binding])
    expect(app.calls).toHaveLength(2)
  } finally {
    app.connection.dispose()
  }
})

// Main rejects the register of a binding it closes, and that reply can overtake the closed-state event.
test.each([
  { error: "browser.pane.replaced", rejected: false },
  { error: "browser.pane.unsupported", rejected: false },
  { error: "browser.pane.replaced", rejected: true },
  { error: "browser.pane.unsupported", rejected: true },
])("$error blocks automatic ownership recovery (register rejected first: $rejected)", async ({ error, rejected }) => {
  jest.useFakeTimers()
  const app = fixture()

  try {
    if (rejected) {
      app.emit(0, { type: "state", state: browser, error: "browser.pane.suspended" })
      app.ipc.reject = new Error("browser.pane.registration.closed")
      app.connection.wake()
      await Promise.resolve()
    }

    app.emit(app.calls.length - 1, { type: "state", state: null, error })
    jest.advanceTimersByTime(30_000)
    app.connection.wake()
    expect(app.calls).toHaveLength(rejected ? 2 : 1)
    expect(app.states.at(-1)?.error).toBe(error)
  } finally {
    app.connection.dispose()
  }
})

import type { Browser } from "@opencode/plugin-browser/rpc"
import type { IpcClient } from "../sdk"
import type { BrowserPane, PaneEvent } from "./ipc"

type Client = IpcClient<(typeof BrowserPane)["spec"]>

export type InspectEvent = Extract<PaneEvent, { type: "inspect" }>

export type PageEvent = Extract<PaneEvent, { type: "page" }>

export type Zoom = "in" | "out" | "reset"

export type Connection = ReturnType<typeof createConnection>

export type Registration = {
  /** Creates a restored tab's page, which then reports its embed. */
  load(tabID: Browser.TabID): void
  command(command: Browser.Action): Promise<void>
  inspect(tabID: Browser.TabID, enabled: boolean): void
  highlight(tabID: Browser.TabID, ref?: Browser.Ref): void
  zoom(tabID: Browser.TabID, zoom: Zoom): void
  site(tabID: Browser.TabID): Promise<{ cookies: number }>
  clearSite(tabID: Browser.TabID): Promise<void>
  close(): void
}

type ConnectionState = {
  registration?: Registration
  browser: Browser.State | null
  /** Host embed per tab page of the current registration. */
  embeds: Readonly<Record<string, string>>
  suspended: boolean
  error?: string
}

// Owns native registration, retry, and suspended tab metadata independently of the mounted session route, and
// mirrors the desktop's tabs into the session's strip.
export function createConnection(input: {
  client: () => Client | undefined
  listen: (binding: string, listener: (event: PaneEvent) => void) => () => void
  target: () => { server: string; session: string }
  /**
   * `mirror` applies the current tabs to the strip; call it right after storing the state, in the same batch, or
   * later once the strip can be written. A mirror that never runs leaves the strip's tabs as they are. `native` is true
   * for an inventory the desktop reported, false for a change made here, such as a new embed or a suspension.
   */
  change: (state: ConnectionState, mirror: () => void, native: boolean) => void
  /** The session's strip: the browser tab IDs it stores, and quietly adding or removing one. */
  strip: {
    stored: () => readonly string[]
    open: (tabID: Browser.TabID) => void
    close: (tabID: string) => void
  }
  focus: (tabID: Browser.TabID) => void
  preview: (path: string) => void
  inspect: (event: InspectEvent) => void
  /** A page's icon or zoom changed. */
  page: (event: PageEvent) => void
  /** The user pressed the address shortcut while the page had focus. */
  address: (tabID: Browser.TabID) => void
}) {
  const state: ConnectionState = { browser: null, embeds: {}, suspended: false }
  let disposed = false
  let blocked = false
  let attempts = 0
  let retry: ReturnType<typeof setTimeout> | undefined
  // A registration was wanted while the pane's Ipc was gone; it registers once the Ipc is back.
  let lost = false
  // Tab IDs of the last inventory the strip received, to tell new tabs from ones the user just closed.
  let known: readonly Browser.TabID[] | undefined
  // A native inventory the strip has not received yet; the next mirror that runs prunes with it.
  let pruning = false

  // Mirrors the tabs into the strip, applied after the state so closing a strip tab already finds the desktop's answer.
  // Only tabs new since the last mirrored inventory are added, so a tab the user just closed is not reopened before
  // the desktop confirms. Only a native inventory removes: it closes every stored tab it lacks, so the desktop decides
  // which tabs exist, while suspended, unavailable, and restoring states keep the tabs they will restore.
  const mirror = () => {
    const previous = new Set<string>(known ?? [])
    const ids = state.browser?.tabs.map((tab) => tab.id)
    const prune = pruning
    known = ids
    pruning = false

    if (!ids) return

    if (prune) {
      const listed = new Set<string>(ids)
      input.strip
        .stored()
        .filter((tabID) => !listed.has(tabID))
        .forEach((tabID) => input.strip.close(tabID))
    }

    ids.forEach((tabID) => {
      if (!previous.has(tabID)) input.strip.open(tabID)
    })
  }

  const publish = (native = false) => {
    pruning ||= native
    input.change({ ...state }, mirror, native)
  }

  // The pane itself is unreachable while its main extension restarts or is disabled, and main drops every
  // binding without reporting it. Keep the tabs, like an idle eviction, and register again when it returns.
  const suspend = (registration: Registration) => {
    if (disposed || state.registration !== registration) return
    lost = true
    registration.close()
    state.registration = undefined
    state.embeds = {}
    state.suspended = true
    state.error = undefined
    publish()
  }

  // Main closed the binding, or never took it (an SSH server's endpoint is missing while it reconnects).
  // Keep the tabs and register again with backoff; commands sent through it already failed and are not replayed.
  const reopen = (registration: Registration) => {
    if (disposed || state.registration !== registration) return
    registration.close()
    state.registration = undefined
    state.embeds = {}
    state.suspended = false
    state.error = undefined
    publish()
    retry = setTimeout(register, Math.min(30_000, 1_000 * 2 ** attempts++))
  }

  const register = () => {
    if (disposed || blocked || state.registration) return
    const current = input.client()

    if (!current) {
      lost = true

      return
    }

    lost = false
    clearTimeout(retry)

    const registration: Registration = open(
      current,
      input.listen,
      state.browser ? { ...input.target(), restore: state.browser } : input.target(),
      (event) => {
        if (disposed || state.registration !== registration) return

        if (event.type === "focus") return input.focus(event.tabID)

        if (event.type === "preview") return input.preview(event.path)

        if (event.type === "inspect") return input.inspect(event)

        if (event.type === "page") return input.page(event)

        if (event.type === "address") return input.address(event.tabID)

        if (event.type === "embed") {
          state.embeds = { ...state.embeds, [event.tabID]: event.embed }

          return publish()
        }

        if (event.error === "browser.pane.unsupported" || event.error === "browser.pane.replaced") {
          blocked = true
          registration.close()
          state.registration = undefined
          state.embeds = {}
          state.browser = null
          state.error = event.error
          publish()

          return
        }

        if (event.error === "browser.pane.registration.closed") return reopen(registration)

        if (event.error === "browser.pane.suspended") {
          registration.close()
          state.registration = undefined
          state.embeds = {}
          state.suspended = true

          if (event.state) state.browser = event.state
          state.error = undefined
          publish()

          // Idle eviction has no retry timer. A user or Session execution wakes it on demand.
          return
        }

        if (event.state) attempts = 0
        state.browser = event.state
        state.error = event.error
        publish(true)
      },
      (error) => {
        if (unavailable(error)) return suspend(registration)

        // Main closed a binding it took; its closed-state event decides, whichever of the two arrives first.
        if (error instanceof Error && error.message === "browser.pane.registration.closed") return
        reopen(registration)
      },
    )

    state.registration = registration
    state.embeds = {}
    state.suspended = false
    state.error = undefined
    publish()
  }

  return {
    wake: register,
    /** Follows the pane's Ipc going away and coming back. */
    refresh() {
      if (!input.client()) {
        if (state.registration) suspend(state.registration)

        return
      }

      if (lost) register()
    },
    command(command: Browser.Action) {
      register()
      const registration = state.registration

      if (!registration) {
        const error = new Error("browser.pane.unavailable")

        return Promise.reject(input.client() ? error : Object.assign(error, { code: "unavailable" }))
      }

      return registration.command(command).catch((cause: unknown) => {
        if (unavailable(cause)) suspend(registration)
        throw cause
      })
    },
    inspect(tabID: Browser.TabID, enabled: boolean) {
      state.registration?.inspect(tabID, enabled)
    },
    highlight(tabID: Browser.TabID, ref?: Browser.Ref) {
      state.registration?.highlight(tabID, ref)
    },
    zoom(tabID: Browser.TabID, zoom: Zoom) {
      state.registration?.zoom(tabID, zoom)
    },
    /** The page's site data; undefined while no registration can answer. */
    site: (tabID: Browser.TabID) => state.registration?.site(tabID),
    clearSite: (tabID: Browser.TabID) => state.registration?.clearSite(tabID),
    dispose() {
      disposed = true
      clearTimeout(retry)
      state.registration?.close()
      state.registration = undefined
    },
  }
}

function open(
  client: Client,
  listen: (binding: string, listener: (event: PaneEvent) => void) => () => void,
  target: { server: string; session: string; restore?: Browser.State },
  listener: (event: PaneEvent) => void,
  failed: (cause: unknown) => void,
): Registration {
  const binding = crypto.randomUUID()
  const status = { closed: false }

  const stop = listen(binding, (event) => {
    if (!status.closed) listener(event)
  })

  const ready = client.register({ binding, ...target })
  // Other failures reach the owner through the closed-state event; keep the bare promise handled.
  void ready.catch(failed)

  return {
    load(tabID) {
      if (status.closed) return
      void ready.then(() => client.load({ binding, tabID })).catch(() => undefined)
    },
    command: (command) => ready.then(() => client.command({ binding, command })),
    inspect(tabID, enabled) {
      if (status.closed) return
      void ready.then(() => client.inspect({ binding, tabID, enabled })).catch(() => undefined)
    },
    highlight(tabID, ref) {
      if (status.closed) return
      void ready
        .then(() => client.highlight(ref === undefined ? { binding, tabID } : { binding, tabID, ref }))
        .catch(() => undefined)
    },
    zoom(tabID, zoom) {
      if (status.closed) return
      void ready.then(() => client.zoom({ binding, tabID, zoom })).catch(() => undefined)
    },
    site: (tabID) => ready.then(() => client.site({ binding, tabID })),
    clearSite: (tabID) => ready.then(() => client.clearSite({ binding, tabID })),
    close() {
      if (status.closed) return
      status.closed = true
      stop()
      void ready.then(() => client.close({ binding })).catch(() => undefined)
    },
  }
}

// The bridge rejects with code "unavailable" while the pane's main extension is not running.
export function unavailable(cause: unknown) {
  return cause instanceof Error && "code" in cause && cause.code === "unavailable"
}

import { Browser } from "@opencode/plugin-browser/rpc"
import type { Protocol } from "devtools-protocol"
import type { Cdp } from "./cdp"

type Request = {
  info: Browser.NetworkRequest
  nativeID: string
  sessionID?: string
  /** Monotonic start; unknown for a WebSocket until its handshake is sent. */
  started?: number
  request: Pick<Protocol.Network.Request, "headers" | "postData" | "hasPostData">
  response?: Pick<Protocol.Network.Response, "headers" | "mimeType">
  headersTruncated: boolean
  postDataTruncated: boolean
  redirected?: boolean
  /** ExtraInfo arrives once per redirect hop, in order; these mark which hops consumed theirs. */
  wire: { request: boolean; response: boolean }
}

type Wire = { headers: Protocol.Network.Headers; statusCode: number }

const levels = ["debug", "info", "warning", "error"] as const

// Values the model must not read; the header name still shows it was sent.
const redacted: readonly string[] = ["cookie", "set-cookie", "authorization", "proxy-authorization"]

export function createDiagnostics(cdp: Cdp) {
  const messages: Browser.ConsoleEntry[] = []
  const requests = new Map<string, Request>()
  // Chromium reuses one request ID across a redirect chain; every hop is retained in order.
  const hops = new Map<string, Request[]>()
  const latest = (key: string) => hops.get(key)?.at(-1)
  // Network-stack headers and wire status arrive as ExtraInfo events, in either order relative to
  // the renderer-side events; stash whichever comes first.
  const extra = new Map<string, { request?: Protocol.Network.Headers; response?: Wire }>()
  const scope = crypto.randomUUID()
  let sequence = 0
  let droppedMessages = 0
  let droppedRequests = 0

  const add = (
    level: (typeof levels)[number],
    text: string,
    timestampMs: number,
    source?: Browser.ConsoleEntry["source"],
  ) => {
    messages.push({
      id: `${scope}:${++sequence}`,
      timestampMs,
      level,
      text: text.slice(0, 2_000),
      textTruncated: text.length > 2_000,
      ...(source ? { source } : {}),
    })

    if (messages.length > 500) {
      messages.shift()
      droppedMessages++
    }
  }

  cdp.on("Runtime.consoleAPICalled", (event) => {
    const source = event.stackTrace?.callFrames[0]
    add(
      event.type === "error" || event.type === "assert"
        ? "error"
        : event.type === "warning"
          ? "warning"
          : event.type === "debug"
            ? "debug"
            : "info",
      event.args
        .map((arg) =>
          typeof arg.value === "string"
            ? arg.value
            : arg.value !== undefined
              ? JSON.stringify(arg.value)
              : (arg.description ?? arg.unserializableValue ?? arg.type),
        )
        .join(" "),
      event.timestamp,
      source
        ? { url: source.url.slice(0, Browser.MAX_TEXT), line: source.lineNumber + 1, column: source.columnNumber + 1 }
        : undefined,
    )
  })
  // Chromium's own messages (CSP refusals, mixed content, failed resource loads, deprecations)
  // are Log entries, not Runtime console calls.
  cdp.on("Log.entryAdded", (event) => {
    const entry = event.entry
    add(
      entry.level === "verbose" ? "debug" : entry.level,
      entry.text,
      entry.timestamp,
      entry.url
        ? { url: entry.url.slice(0, Browser.MAX_TEXT), line: (entry.lineNumber ?? 0) + 1, column: 1 }
        : undefined,
    )
  })
  cdp.on("Runtime.exceptionThrown", (event) => {
    const error = event.exceptionDetails
    add(
      "error",
      error.exception?.description ?? error.text,
      event.timestamp,
      error.url ? { url: error.url, line: error.lineNumber + 1, column: error.columnNumber + 1 } : undefined,
    )
  })

  const begin = (
    key: string,
    sessionID: string | undefined,
    nativeID: string,
    started: number | undefined,
    wallTime: number,
    info: Pick<Browser.NetworkRequest, "url" | "method" | "resourceType">,
    request: Request["request"],
  ) => {
    const headers = trimHeaders(request.headers)

    const entry: Request = {
      nativeID,
      sessionID,
      started,
      request: { ...request, headers: headers.headers, postData: request.postData?.slice(0, 20_000) },
      headersTruncated: headers.truncated,
      postDataTruncated: (request.postData?.length ?? 0) > 20_000,
      wire: { request: false, response: false },
      info: {
        id: `${scope}:${++sequence}`,
        ...info,
        url: info.url.slice(0, 16_384),
        timestampMs: wallTime * 1000,
        state: "pending",
      },
    }

    requests.set(entry.info.id, entry)
    hops.set(key, [...(hops.get(key) ?? []), entry])
    // A stash can only belong to this hop: earlier hops would have consumed it on arrival.
    const stashed = extra.get(key)

    if (stashed?.request) requestHeaders(entry, stashed.request)

    if (stashed?.response) responseInfo(entry, stashed.response)
    extra.delete(key)

    if (requests.size > 500) {
      const first = requests.values().next().value

      if (first) {
        requests.delete(first.info.id)
        const firstKey = `${first.sessionID ?? ""}:${first.nativeID}`
        const rest = hops.get(firstKey)?.filter((hop) => hop !== first) ?? []

        if (rest.length) hops.set(firstKey, rest)

        if (!rest.length) hops.delete(firstKey)
      }

      droppedRequests++
    }

    return entry
  }

  const requestHeaders = (request: Request, headers: Protocol.Network.Headers) => {
    const trimmed = trimHeaders({ ...request.request.headers, ...headers })
    request.request = { ...request.request, headers: trimmed.headers }
    request.headersTruncated ||= trimmed.truncated
    request.wire.request = true
  }

  const responseInfo = (request: Request, wire: Wire) => {
    const trimmed = trimHeaders({ ...request.response?.headers, ...wire.headers })
    request.response = { mimeType: request.response?.mimeType ?? "", headers: trimmed.headers }
    request.headersTruncated ||= trimmed.truncated
    request.info = { ...request.info, statusCode: wire.statusCode }
    request.wire.response = true
  }

  const finish = (key: string, timestamp: number, failure?: string) => {
    const request = latest(key)

    if (!request) return
    const durationMs = request.started === undefined ? 0 : Math.max(0, (timestamp - request.started) * 1000)
    request.info =
      failure === undefined
        ? { ...request.info, state: "completed", durationMs }
        : { ...request.info, state: "failed", failure: failure.slice(0, 2_048), durationMs }
  }

  cdp.on("Network.requestWillBeSent", (event, sessionID) => {
    const key = `${sessionID ?? ""}:${event.requestId}`
    const previous = latest(key)

    if (previous && event.redirectResponse) {
      // Wire headers for this hop may already be merged in; the renderer copy lacks set-cookie.
      const response = trimHeaders({ ...event.redirectResponse.headers, ...previous.response?.headers })
      previous.response = { mimeType: event.redirectResponse.mimeType, headers: response.headers }
      previous.headersTruncated ||= response.truncated
      previous.redirected = true

      // A cached redirect never gets ExtraInfo; the next hop's must not be attributed to it.
      if (!event.redirectHasExtraInfo) previous.wire = { request: true, response: true }
      previous.info = {
        ...previous.info,
        state: "completed",
        statusCode: previous.info.statusCode ?? event.redirectResponse.status,
        durationMs: Math.max(0, (event.timestamp - (previous.started ?? event.timestamp)) * 1000),
      }
    }

    begin(
      key,
      sessionID,
      event.requestId,
      event.timestamp,
      event.wallTime,
      {
        url: event.request.url,
        method: event.request.method,
        resourceType: resourceType((event.type ?? "other").toLowerCase()),
      },
      { headers: event.request.headers, hasPostData: event.request.hasPostData, postData: event.request.postData },
    )
  })
  // ExtraInfo for a redirect hop can land after the renderer already started the next hop, so it
  // goes to the earliest hop that has not consumed its own rather than to the latest.
  cdp.on("Network.requestWillBeSentExtraInfo", (event, sessionID) => {
    const key = `${sessionID ?? ""}:${event.requestId}`
    const request = hops.get(key)?.find((hop) => !hop.wire.request)

    if (request) return requestHeaders(request, event.headers)
    extra.set(key, { ...extra.get(key), request: event.headers })
  })
  cdp.on("Network.responseReceived", (event, sessionID) => {
    const request = latest(`${sessionID ?? ""}:${event.requestId}`)

    if (!request) return
    const headers = trimHeaders({ ...event.response.headers, ...request.response?.headers })
    request.response = { mimeType: event.response.mimeType, headers: headers.headers }
    request.headersTruncated ||= headers.truncated
    // ExtraInfo already carries the wire status when it arrived first; the renderer may report 200 for a 304.
    request.info = { ...request.info, statusCode: request.info.statusCode ?? event.response.status }

    if (!event.hasExtraInfo) request.wire = { request: true, response: true }
  })
  cdp.on("Network.responseReceivedExtraInfo", (event, sessionID) => {
    const key = `${sessionID ?? ""}:${event.requestId}`
    const request = hops.get(key)?.find((hop) => !hop.wire.response)

    if (request) return responseInfo(request, event)
    extra.set(key, { ...extra.get(key), response: event })
  })
  // WebSockets never emit requestWillBeSent; their handshake is the whole request lifecycle.
  cdp.on("Network.webSocketCreated", (event, sessionID) => {
    begin(
      `${sessionID ?? ""}:${event.requestId}`,
      sessionID,
      event.requestId,
      undefined,
      Date.now() / 1000,
      { url: event.url, method: "GET", resourceType: "websocket" },
      { headers: {}, hasPostData: false },
    )
  })
  cdp.on("Network.webSocketWillSendHandshakeRequest", (event, sessionID) => {
    const request = latest(`${sessionID ?? ""}:${event.requestId}`)

    if (!request) return
    request.started = event.timestamp
    request.info = { ...request.info, timestampMs: event.wallTime * 1000 }
    requestHeaders(request, event.request.headers)
  })
  cdp.on("Network.webSocketHandshakeResponseReceived", (event, sessionID) => {
    const key = `${sessionID ?? ""}:${event.requestId}`
    const request = latest(key)

    if (!request) return
    responseInfo(request, { headers: event.response.headers, statusCode: event.response.status })
    finish(key, event.timestamp)
  })
  cdp.on("Network.webSocketFrameError", (event, sessionID) =>
    finish(`${sessionID ?? ""}:${event.requestId}`, event.timestamp, event.errorMessage),
  )
  cdp.on("Network.webSocketClosed", (event, sessionID) => {
    const key = `${sessionID ?? ""}:${event.requestId}`

    if (latest(key)?.info.state === "pending") finish(key, event.timestamp, "Closed before the handshake completed")
  })
  cdp.on("Network.loadingFinished", (event, sessionID) =>
    finish(`${sessionID ?? ""}:${event.requestId}`, event.timestamp),
  )
  cdp.on("Network.loadingFailed", (event, sessionID) =>
    finish(`${sessionID ?? ""}:${event.requestId}`, event.timestamp, event.errorText),
  )

  return {
    clear() {
      messages.length = 0
      requests.clear()
      hops.clear()
      extra.clear()
      droppedMessages = 0
      droppedRequests = 0
    },
    async enable(sessionID?: string) {
      await cdp.send("Runtime.enable", {}, sessionID)
      await cdp.send("Log.enable", {}, sessionID)
      await cdp.send(
        "Network.enable",
        { maxTotalBufferSize: 5 * 1024 * 1024, maxResourceBufferSize: 1024 * 1024, maxPostDataSize: 20_000 },
        sessionID,
      )
    },
    console(input: Extract<Browser.Action, { type: "console" }>) {
      const matching = messages.filter((entry) => levels.indexOf(entry.level) >= levels.indexOf(input.level ?? "info"))
      const result = bounded(matching, input.limit ?? 100)

      return { messages: result, truncated: matching.length > result.length, dropped: droppedMessages }
    },
    list(input: Extract<Browser.Action, { type: "network.list" }>) {
      const matching = Array.from(requests.values())
        .map((request) => request.info)
        .filter(
          (request) =>
            (!input.urlContains || request.url.includes(input.urlContains)) &&
            (!input.resourceType || input.resourceType === request.resourceType),
        )

      const result = bounded(matching, input.limit ?? 100)

      return { requests: result, truncated: matching.length > result.length, dropped: droppedRequests }
    },
    info(id: string) {
      const request = requests.get(id)

      if (!request)
        throw new Error(
          "Request is no longer retained. Call browser.network.list({tabID}) and use a current request id. Do not reload or resend it just to inspect it.",
        )

      return request.info
    },
    async get(input: Extract<Browser.Action, { type: "network.get" }>) {
      const request = requests.get(input.id)

      if (!request)
        throw new Error(
          "Request ID is no longer retained in this tab or belongs to another tab. Call browser.network.list({tabID}) and copy a current id into browser.network.get with the same tabID. Do not reload or resend a request just to inspect it.",
        )
      const max = input.maxBodyChars ?? 20_000

      const text = (value: string): Browser.Body => ({
        state: "text",
        text: value.slice(0, max),
        truncated: value.length > max,
      })

      const responseBody = async (): Promise<Browser.Body> => {
        if (!input.includeBody) return { state: "notRequested" }

        if (request.info.state === "pending") return { state: "pending" }

        if (request.redirected || !request.response || request.info.resourceType === "websocket")
          return { state: "unavailable", reason: "notCaptured" }

        if (
          !/^(text\/|application\/(json|.*\+json|javascript|xml|.*\+xml|x-www-form-urlencoded))/i.test(
            request.response.mimeType,
          )
        )
          return { state: "unavailable", reason: "binary" }

        const body = await cdp
          .send("Network.getResponseBody", { requestId: request.nativeID }, request.sessionID)
          .catch(() => undefined)

        if (!body) return { state: "unavailable", reason: "backendUnavailable" }
        const value = body.base64Encoded ? Buffer.from(body.body, "base64").toString("utf8") : body.body

        return value.length ? text(value) : { state: "empty" }
      }

      const requestBody: Browser.Body = !input.includeBody
        ? { state: "notRequested" }
        : request.request.postData !== undefined
          ? {
              state: "text",
              text: request.request.postData.slice(0, max),
              truncated: request.postDataTruncated || request.request.postData.length > max,
            }
          : request.request.hasPostData
            ? { state: "unavailable", reason: "notCaptured" }
            : { state: "empty" }

      return {
        request: request.info,
        requestHeaders: headerEntries(request.request.headers),
        responseHeaders: headerEntries(request.response?.headers ?? {}),
        headersTruncated: request.headersTruncated,
        requestBody,
        responseBody: await responseBody(),
      }
    },
  }
}

function resourceType(type: string): Browser.ResourceType {
  switch (type) {
    case "document":
    case "stylesheet":
    case "image":
    case "media":
    case "font":
    case "script":
    case "xhr":
    case "fetch":
    case "eventsource":
    case "websocket":
    case "manifest":
      return type
    default:
      return "other"
  }
}

function trimHeaders(headers: Protocol.Network.Headers) {
  const entries = Object.entries(headers)
  const kept: [string, string][] = []
  let size = 0
  let truncated = entries.length > 100

  for (const [key, value] of entries.slice(0, 100)) {
    // Lower-case names so renderer and wire copies of one header merge instead of duplicating.
    const name = key.toLowerCase().slice(0, 2_048)
    const text = redacted.includes(name) ? "<redacted>" : String(value)
    const remaining = Math.max(0, 16_000 - size - name.length)

    if (!remaining) {
      truncated = true
      break
    }

    const bounded = text.slice(0, Math.min(2_000, remaining))
    truncated ||= bounded.length < text.length || name.length < key.length
    kept.push([name, bounded])
    size += name.length + bounded.length
  }

  return { headers: Object.fromEntries(kept), truncated }
}

function bounded<Item>(items: readonly Item[], limit: number) {
  const selected: Item[] = []
  let size = 0

  for (const item of items.slice(-limit).reverse()) {
    size += JSON.stringify(item).length

    if (size > Browser.MAX_TEXT) break
    selected.push(item)
  }

  return selected.reverse()
}

function headerEntries(headers: Protocol.Network.Headers) {
  return Object.entries(headers).map(([name, value]) => ({ name, value: String(value) }))
}

import { expect, test } from "bun:test"
import { Browser } from "@opencode/plugin-browser/rpc"
import { browserFailure, protocolError } from "./errors"

const tabID = Browser.TabID.make(`tab_${crypto.randomUUID()}`)

test("navigation failures explain the server network and never recommend disabling TLS", () => {
  const action: Browser.Action = { type: "navigate", tabID, url: "https://example.com" }
  const refused = browserFailure(action, new Error("net::ERR_CONNECTION_REFUSED"))
  expect(refused.code).toBe("navigation_failed")
  expect(refused.message).toContain("localhost means that server")
  expect(refused.message).toContain("hostname/port")
  const tls = browserFailure(action, new Error("net::ERR_CERT_AUTHORITY_INVALID"))
  expect(tls.message).toContain("do not bypass certificate checks")
  const aborted = browserFailure(action, new Error("net::ERR_ABORTED"))
  expect(aborted.message).toContain("browser.files.list({tabID})")
})

test("native protocol errors keep the cause and give a valid recovery operation", () => {
  expect(protocolError("DOM.resolveNode", new Error("Could not find node with given id")).message).toContain(
    "browser.snapshot({tabID})",
  )
  expect(protocolError("Runtime.evaluate", new Error("Cannot find context with specified id")).message).toContain(
    "browser.frames({tabID})",
  )
  expect(
    protocolError("Runtime.callFunctionOn", new Error("Given expression does not evaluate to a function")).message,
  ).toContain("(element) => element.textContent")
  const unsupported = protocolError("Target.getBrowserContexts", new Error("Not allowed"))
  expect(unsupported.message).toContain("does not support or allow")
  expect(unsupported.message).toContain("do not retry unchanged")
  expect(unsupported.cause).toBeInstanceOf(Error)
  const failure = browserFailure({ type: "screenshot", tabID }, new Error("UnknownVizError"))
  expect(failure.message).toContain("browser.tabs.focus({tabID})")
  expect(failure.message).toContain("report the capture failure")
})

test("long page errors retain the operation context without classifying script text as a navigation error", () => {
  const failure = browserFailure(
    { type: "evaluate", tabID, script: "throw Error()" },
    new Error("ERR_CONNECTION_REFUSED " + "x".repeat(10_000)),
  )

  expect(failure.code).toBe("operation_failed")
  expect(failure.message.startsWith("browser.evaluate failed.")).toBe(true)
  expect(failure.message.length).toBeLessThanOrEqual(2_048)
})

import type { Browser } from "@opencode/plugin-browser/rpc"

export function protocolError(method: string, error: unknown) {
  const detail = message(error)

  const recovery =
    method === "DOM.setFileInputFiles" && /not.*file input/i.test(detail)
      ? "Target is not a file input. Call browser.snapshot({tabID}) and choose an input[type=file] ref for browser.files.upload, or use browser.files.drop for a drop area."
      : method === "Runtime.callFunctionOn" && /not evaluate to a function/i.test(detail)
        ? "With ref, browser.evaluate needs a function that receives the element, for example (element) => element.textContent."
        : /(?:node|object).*(?:not found|not exist)|(?:find|resolve).*(?:node|object)|detached/i.test(detail)
          ? "The element may have detached. Call browser.snapshot({tabID}) and use a fresh ref from that tab."
          : /context.*(?:destroyed|not found)|find.*context|session.*not found/i.test(detail)
            ? "The document or frame changed. Call browser.frames({tabID}) and browser.snapshot({tabID}); use current frame IDs and refs."
            : /wasn't found|method not found|not implemented|not allowed/i.test(detail)
              ? "This Chromium target does not support or allow the operation. Check desktop/plugin compatibility and report it; do not retry unchanged or disable browser security."
              : "Inspect browser.tabs.list({}) and the target tab before deciding to retry; a partially completed action is not automatically safe to repeat."

  return new Error(`${recovery} Chromium command ${method} failed: ${detail}`, { cause: error })
}

export function browserFailure(action: Browser.Action, error: unknown): Extract<Browser.Outcome, { type: "failure" }> {
  const detail = message(error, 1_700)
  const navigation = ["tabs.open", "navigate", "back", "forward", "reload"].includes(action.type)
  const network = navigation ? detail.match(/\bERR_[A-Z_]+\b/)?.[0] : undefined

  const hint =
    network === "ERR_CONNECTION_REFUSED"
      ? "The browser could not connect to the site. Check its hostname/port on the connected server. localhost means that server, not the desktop."
      : network === "ERR_NAME_NOT_RESOLVED"
        ? "The connected server could not resolve the hostname. Check the URL spelling and the server's DNS/network connection."
        : network?.startsWith("ERR_CERT_") || network?.startsWith("ERR_SSL_")
          ? "The desktop rejected the site's TLS connection. Ask the user to fix the certificate or trust configuration; do not bypass certificate checks."
          : network === "ERR_ABORTED"
            ? "Navigation was interrupted or became a download. Inspect browser.tabs.list({}) and browser.files.list({tabID}) before deciding to navigate again."
            : network
              ? "The site failed to load through the connected server. Check its URL/network and the OC2 connection before retrying; inspect the current tab first."
              : action.type === "screenshot" && /UnknownVizError|capture.*(?:failed|unavailable)/i.test(detail)
                ? "Chromium could not capture a rendered frame. Call browser.tabs.focus({tabID}) and keep the desktop window visible. If it is already visible, report the capture failure instead of repeating it unchanged."
                : undefined

  return {
    type: "failure",
    code: network ? "navigation_failed" : "operation_failed",
    message: `browser.${action.type} failed. ${hint ? `${hint} Details: ${detail.slice(0, 400)}` : detail}`.slice(
      0,
      2_048,
    ),
  }
}

function message(error: unknown, limit = 400) {
  return (error instanceof Error ? error.message : String(error)).slice(0, limit)
}

import { expect, test } from "bun:test"
import { rm } from "node:fs/promises"
import path from "node:path"
import { Browser } from "@opencode/plugin-browser/rpc"
import { createBrowserFiles } from "./files"

test("files distinguish pending, failed, unknown and missing desktop copies", async () => {
  const files = createBrowserFiles(() => ["https://example.com"])
  await files.ready

  try {
    const pending = files.add("download.txt", "text/plain")
    expect(() => files.get(pending.id)).toThrow("do not start a duplicate download")
    pending.state = "failed"
    expect(() => files.get(pending.id)).toThrow("Inspect browser.console")
    expect(() => files.get(Browser.FileID.make(`file_${crypto.randomUUID()}`))).toThrow(
      "not a server path or request ID",
    )
    const id = await files.save("capture.json", "application/json", new TextEncoder().encode("{}"))
    await rm(files.get(id).path)
    await expect(files.transfer(id)).rejects.toThrow("on the desktop")
    await expect(
      files.save("large.bin", "application/octet-stream", new Uint8Array(Browser.MAX_FILE_BYTES + 1)),
    ).rejects.toThrow("Do not retry an identical capture")
    // The page sees the temp basename as File.name: spaces and non-ASCII stay, only characters no
    // filesystem accepts change, and a bare dot or separator cannot leave the per-file directory.
    expect(path.basename(files.add("Quarter 1 日本語.csv", "text/csv").path)).toBe("Quarter 1 日本語.csv")
    expect(path.basename(files.add("a/b:c?.txt", "text/plain").path)).toBe("a_b_c_.txt")
    expect(path.basename(files.add("..", "text/plain").path)).toBe("file")
    expect(path.dirname(files.add(".", "text/plain").path).startsWith(files.directory)).toBe(true)
  } finally {
    await files.dispose()
  }
})

import { Browser } from "@opencode/plugin-browser/rpc"
import { mkdir, readFile, stat, writeFile, rm } from "node:fs/promises"
import { mkdirSync } from "node:fs"
import { tmpdir } from "node:os"
import path from "node:path"

export type BrowserFiles = ReturnType<typeof createBrowserFiles>

export function createBrowserFiles(source: () => readonly string[]) {
  const directory = path.join(tmpdir(), `opencode-browser-client-${crypto.randomUUID()}`)

  const files = new Map<
    Browser.FileID,
    {
      id: Browser.FileID
      name: string
      mime: string
      bytes: number
      state: "pending" | "completed" | "failed"
      path: string
      resources: readonly string[]
    }
  >()

  // Captures, uploads, and heap snapshots sit in the shared temp directory; keep them owner-only.
  const ready = mkdir(directory, { recursive: true, mode: 0o700 })

  return {
    directory,
    ready,
    list: () => Array.from(files.values()).map(({ path: _path, resources: _resources, ...file }) => file),
    add(name: string, mime: string, resources = source()) {
      const id = Browser.FileID.make(`file_${crypto.randomUUID()}`)
      const target = path.join(directory, id)
      // setSavePath must run during Electron's synchronous will-download callback.
      mkdirSync(target, { recursive: true, mode: 0o700 })

      const file = {
        id,
        name: name.slice(0, 2_048),
        mime,
        bytes: 0,
        state: "pending" as "pending" | "completed" | "failed",
        // A page receives this basename as the uploaded File.name, so spaces and non-ASCII stay;
        // only characters no supported filesystem accepts are replaced. Each file has its own
        // directory, so names never collide.
        path: path.join(
          target,
          name
            .replace(/[<>:"/\\|?*\u0000-\u001f]/g, "_")
            .replace(/[. ]+$/, "")
            .slice(-120) || "file",
        ),
        resources: [...new Set(resources)].sort(),
      }

      files.set(id, file)

      return file
    },
    async save(name: string, mime: string, data: Uint8Array, resources = source()) {
      if (data.byteLength > Browser.MAX_FILE_BYTES)
        throw new Error(
          "Capture exceeds the 5 MiB transfer limit. Reduce screenshot maxWidth/quality or trace duration; for a heap snapshot, use a smaller page/test case. Do not retry an identical capture.",
        )
      await ready
      const file = this.add(name, mime, resources)
      await writeFile(file.path, data, { mode: 0o600 }).catch((error: unknown) => {
        file.state = "failed"
        throw new Error(
          "Cannot write the capture on the desktop. Ask the user to check desktop temporary-directory access and free space before retrying.",
          { cause: error },
        )
      })
      file.bytes = data.byteLength
      file.state = "completed"

      return file.id
    },
    get(id: Browser.FileID) {
      const file = files.get(id)

      if (!file)
        throw new Error(
          "File ID is not retained in this tab. Call browser.files.list({tabID}) and use an exact returned fileID from the same tab, not a server path or request ID.",
        )

      if (file.state === "pending")
        throw new Error(
          "File is still being downloaded or captured. Check browser.files.list({tabID}) again and wait for state completed; do not start a duplicate download.",
        )

      if (file.state === "failed")
        throw new Error(
          "The download or capture failed, so this file cannot be read. Inspect browser.console and browser.network.list for the cause before deciding to start it again.",
        )

      return file
    },
    async transfer(id: Browser.FileID, authorized?: readonly string[]): Promise<Browser.File> {
      const file = this.get(id)

      if (authorized && file.resources.some((url) => !authorized.includes(url)))
        throw new Error(
          "Capture source changed before export. Inspect the tab and request the file again to check its source permissions; no bytes were exported.",
        )

      if (
        (
          await stat(file.path).catch((error: unknown) => {
            throw unavailableFile(error)
          })
        ).size > Browser.MAX_FILE_BYTES
      )
        throw new Error(
          "File exceeds the 5 MiB transfer limit. Choose a smaller completed file; repeating browser.files.get for this file will not help.",
        )

      const data = await readFile(file.path).catch((error: unknown) => {
        throw unavailableFile(error)
      })

      return { id, name: file.name, mime: file.mime, data: new Uint8Array(data) }
    },
    dispose: () => ready.then(() => rm(directory, { recursive: true, force: true })),
  }
}

function unavailableFile(error: unknown) {
  return new Error(
    "The retained file cannot be read on the desktop. Its temporary copy may have been removed. Use an already exported server-local path if available, or deliberately create a new capture.",
    { cause: error },
  )
}

import { Schema } from "effect"

/** A page the browser showed, newest first in the history. */
export const Visit = Schema.Struct({
  url: Schema.String,
  title: Schema.String,
  /** The page's icon as a data URL, when it was small enough to keep. */
  icon: Schema.optionalKey(Schema.String),
})

export type Visit = typeof Visit.Type

export const History = Schema.Struct({ visits: Schema.Array(Visit) })

export type History = typeof History.Type

/** Visits the history keeps; the new tab page shows the first few. */
const MAX_VISITS = 30

/** Icons larger than this stay out of the stored history; a 32px PNG is a few kilobytes. */
const MAX_STORED_ICON = 6_000

/** The pages the history records: web pages and workspace files, not blank or internal ones. */
export function recordable(url: string) {
  return /^(?:https?|file):\/\//i.test(url)
}

/**
 * Puts a visit first, replacing an earlier visit of the same URL, and drops the oldest past the limit. A visit without
 * a title or icon yet keeps the earlier visit's.
 */
export function remember(visits: readonly Visit[], visit: Pick<Visit, "url" | "title">, icon?: string): Visit[] {
  const earlier = visits.find((item) => item.url === visit.url)
  const kept = storable(icon) ?? earlier?.icon
  const title = visit.title || earlier?.title || ""

  const next: Visit = kept ? { url: visit.url, title, icon: kept } : { url: visit.url, title }

  // Copies, so a store that reconciles the new list in place never sees its own records at moved positions.
  return [next, ...visits.flatMap((item) => (item.url === visit.url ? [] : [{ ...item }]))].slice(0, MAX_VISITS)
}

/** The visits with a newly loaded icon on the visit of `url`, or undefined when nothing would change. */
export function withIcon(visits: readonly Visit[], url: string, icon: string) {
  const stored = storable(icon)

  if (!stored || !visits.some((visit) => visit.url === url && visit.icon !== stored)) return

  return visits.map((visit) => (visit.url === url ? { ...visit, icon: stored } : { ...visit }))
}

function storable(icon: string | undefined) {
  return icon && icon.length <= MAX_STORED_ICON ? icon : undefined
}

/**
 * Visits whose address or title contains the query, case-insensitively. Addresses that begin with the query come
 * first, as the address field completes them; within each group the newest visit leads.
 */
export function suggest(visits: readonly Visit[], query: string, limit: number) {
  const needle = query.trim().toLowerCase()

  if (!needle) return []

  const matches = visits.filter(
    (visit) => bare(visit.url).toLowerCase().includes(needle) || visit.title.toLowerCase().includes(needle),
  )

  return [
    ...matches.filter((visit) => completes(visit, needle)),
    ...matches.filter((visit) => !completes(visit, needle)),
  ].slice(0, limit)
}

/** Whether the visit's address begins with what the user typed, so Enter may open it in place of the typed text. */
export function completes(visit: Visit, query: string) {
  const needle = query.trim().toLowerCase()

  return !!needle && bare(visit.url).toLowerCase().startsWith(needle)
}

/** Splits text around case-insensitive matches of the query, for drawing the matched parts. */
export function highlight(text: string, query: string) {
  const needle = query.trim().toLowerCase()

  if (!needle) return [{ text, match: false }]
  const lower = text.toLowerCase()

  const starts = Array.from(lower.matchAll(new RegExp(escape(needle), "g")), (found) => found.index)
  const bounds = starts.flatMap((start) => [start, start + needle.length])

  return [0, ...bounds, text.length].flatMap((start, index, all) => {
    const end = all[index + 1]

    return end === undefined || end === start ? [] : [{ text: text.slice(start, end), match: index % 2 === 1 }]
  })
}

/** The address without its web scheme or a leading `www.`, as people type it. */
export function bare(url: string) {
  return url.replace(/^https?:\/\//i, "").replace(/^www\./i, "")
}

function escape(text: string) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
}

import { nativeImage } from "electron"
import { MAX_ICON_URL } from "./ipc"
import type { BrowserNetwork } from "./network"

type Fetched = { mime: string; data: Buffer }

/**
 * The first of a page's icon candidates that loads, as a data URL small enough to report and store. An SVG stays as
 * it is; any other format is redrawn as a PNG of at most 32px, which also drops anything that is not an image. Never
 * rejects: a candidate that fails falls through to the next.
 */
export function loadIcon(candidates: readonly string[], network: BrowserNetwork | null) {
  return candidates
    .filter((url) => /^(?:https?:|data:image\/)/i.test(url))
    .slice(0, 3)
    .reduce<Promise<string | undefined>>(
      (found, url) =>
        found.then(async (icon) => {
          if (icon) return icon
          const fetched = /^data:/i.test(url) ? inline(url) : await network?.icon(url).catch(() => undefined)

          return fetched ? encode(fetched) : undefined
        }),
      Promise.resolve(undefined),
    )
}

function inline(url: string): Fetched | undefined {
  const match = /^data:(image\/[\w.+-]+)(;base64)?,(.*)$/is.exec(url)

  if (!match) return
  const body = match[3] ?? ""

  return { mime: (match[1] ?? "").toLowerCase(), data: match[2] ? Buffer.from(body, "base64") : unescape(body) }
}

// Percent-decodes to bytes. A stray `%`, as in `width="100%"`, stays as it is rather than failing the whole icon.
function unescape(text: string) {
  return Buffer.concat(
    text
      .split(/(%[\da-f]{2})/i)
      .map((part) => (/^%[\da-f]{2}$/i.test(part) ? Buffer.from([parseInt(part.slice(1), 16)]) : Buffer.from(part))),
  )
}

function encode(fetched: Fetched) {
  // An SVG in an <img> runs no script and loads nothing, so it needs no redrawing; one with no drawing is no icon.
  if (fetched.mime === "image/svg+xml") {
    if (!/<svg[\s>]/i.test(fetched.data.toString("utf8"))) return
    const url = `data:image/svg+xml;base64,${fetched.data.toString("base64")}`

    return url.length <= MAX_ICON_URL ? url : undefined
  }

  const image = nativeImage.createFromBuffer(fetched.data)

  if (image.isEmpty()) return
  const size = image.getSize()

  // The longer side fits 32px; resizing one side keeps the shape.
  const fitted =
    Math.max(size.width, size.height) <= 32
      ? image
      : image.resize(size.width >= size.height ? { width: 32, quality: "best" } : { height: 32, quality: "best" })

  const url = fitted.toDataURL()

  return url.length <= MAX_ICON_URL ? url : undefined
}

import { Browser } from "@opencode/plugin-browser/rpc"
import { Schema } from "effect"
import { Ipc } from "../sdk"

const text = (maximum: number) => Schema.String.check(Schema.isMinLength(1), Schema.isMaxLength(maximum))

const detail = (maximum: number) => Schema.String.check(Schema.isMaxLength(maximum))

const binding = text(128)

/** The longest page icon data URL main reports: a 32px PNG is a few kilobytes; larger icons are dropped. */
export const MAX_ICON_URL = 24_576

/** An element the user picked in the page. The ref stays valid for browser tools until the page navigates. */
export const PaneElement = Schema.Struct({
  ref: Browser.Ref,
  selector: detail(2_048),
  label: detail(512),
  role: Schema.optionalKey(detail(128)),
  name: Schema.optionalKey(detail(512)),
  text: Schema.optionalKey(detail(512)),
  /** Border box in the native view's DIPs. */
  rect: Schema.Struct({ x: Schema.Finite, y: Schema.Finite, width: Schema.Finite, height: Schema.Finite }),
})

export type PaneElement = typeof PaneElement.Type

export const PaneEvent = Schema.Union([
  Schema.Struct({ type: Schema.Literal("focus"), tabID: Browser.TabID }),
  Schema.Struct({ type: Schema.Literal("preview"), path: text(2_048) }),
  Schema.Struct({
    type: Schema.Literal("state"),
    state: Schema.NullOr(Browser.State),
    error: Schema.optionalKey(Schema.String),
  }),
  // A tab's page exists; the renderer lays it out through this host embed.
  Schema.Struct({ type: Schema.Literal("embed"), tabID: Browser.TabID, embed: text(256) }),
  // The page's element picker started, stopped, or picked an element.
  Schema.Struct({
    type: Schema.Literal("inspect"),
    tabID: Browser.TabID,
    active: Schema.Boolean,
    element: Schema.optionalKey(PaneElement),
  }),
  // Details only this desktop shows, kept out of the server's tab state: the page's icon as a data URL, and its zoom
  // factor, 1 at 100%.
  Schema.Struct({
    type: Schema.Literal("page"),
    tabID: Browser.TabID,
    icon: Schema.optionalKey(detail(MAX_ICON_URL).check(Schema.isStartingWith("data:image/"))),
    zoom: Schema.Finite.check(Schema.isBetween({ minimum: 0.25, maximum: 5 })),
  }),
  // The page asked for the address field, with the platform's address shortcut.
  Schema.Struct({ type: Schema.Literal("address"), tabID: Browser.TabID }),
])

export type PaneEvent = typeof PaneEvent.Type

/**
 * The native browser pane in the main process. A binding is one registration of a session's pane
 * by a window; its events go to that window only.
 */
export const BrowserPane = Ipc.define({
  id: "browser.pane",
  methods: {
    register: {
      input: Schema.Struct({
        binding,
        server: text(16_384),
        session: text(256).check(Schema.isStartingWith("ses")),
        restore: Schema.optionalKey(Browser.State),
      }),
    },
    // Creates the page of a restored tab the first time the pane shows it.
    load: { input: Schema.Struct({ binding, tabID: Browser.TabID }) },
    command: { input: Schema.Struct({ binding, command: Browser.Action }) },
    // Starts or stops the page's element picker; the page reports picks and exits as inspect events.
    inspect: { input: Schema.Struct({ binding, tabID: Browser.TabID, enabled: Schema.Boolean }) },
    // Highlights a picked element briefly, or clears any highlight when ref is omitted.
    highlight: { input: Schema.Struct({ binding, tabID: Browser.TabID, ref: Schema.optionalKey(Browser.Ref) }) },
    // Zooms the page one step in or out, or back to 100%; the page reports its new zoom as a page event.
    zoom: {
      input: Schema.Struct({ binding, tabID: Browser.TabID, zoom: Schema.Literals(["in", "out", "reset"]) }),
    },
    // The site data the page's address can read in this desktop's browser: its cookie count. Zero for a page that is
    // not a web page.
    site: {
      input: Schema.Struct({ binding, tabID: Browser.TabID }),
      output: Schema.Struct({ cookies: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)) }),
    },
    // Deletes the cookies the page's address can read and its origin's stored data, then reloads the page.
    clearSite: { input: Schema.Struct({ binding, tabID: Browser.TabID }) },
    close: { input: Schema.Struct({ binding }) },
  },
  events: {
    event: Schema.Struct({ binding: Schema.String, event: PaneEvent }),
  },
})

import type { WebContents } from "electron"
import { EventEmitter } from "node:events"
import type { BrowserFiles } from "./files"
import type { Cdp } from "./cdp"

export async function audit(contents: WebContents, files: BrowserFiles, cdp: Cdp, resources: readonly string[]) {
  const { snapshot, generateReport } = await import("lighthouse")
  const info = (await contents.debugger.sendCommand("Target.getTargetInfo")) as { targetInfo: { targetId: string } }
  const sessions = new Map<string, ReturnType<typeof session>>()

  function session(id: string) {
    const emitter = new EventEmitter()

    const value = Object.assign(emitter, {
      id: () => id,
      send: (method: string, params?: object) => cdp.send(method as Parameters<Cdp["send"]>[0], params, id),
      detach: async () => {
        sessions.delete(id)
        await contents.debugger.sendCommand("Target.detachFromTarget", { sessionId: id })
      },
    })

    sessions.set(id, value)

    return value
  }

  const event = (_event: Electron.Event, method: string, params: unknown, sessionID?: string) => {
    const owner = sessionID ? sessions.get(sessionID) : undefined

    if (!owner) return

    if (method === "Target.attachedToTarget") {
      const child = params as { sessionId: string }
      owner.emit("sessionattached", session(child.sessionId))
    }

    owner.emit(method, params)
    owner.emit("*", method, params)
  }

  contents.debugger.on("message", event)

  try {
    const attached = (await contents.debugger.sendCommand("Target.attachToTarget", {
      targetId: info.targetInfo.targetId,
      flatten: true,
    })) as { sessionId: string }

    const root = session(attached.sessionId)

    // Lighthouse's snapshot driver uses only url() and target().createCDPSession().
    // Adapt that narrow boundary to Electron instead of exposing a browser-wide
    // Puppeteer connection or emulating unsupported Browser/Target commands.
    const page = {
      url: () => contents.getURL(),
      target: () => ({ createCDPSession: async () => root }),
    } as unknown as Parameters<typeof snapshot>[0]

    // Our screenshot tool handles captures separately. Lighthouse's screenshot
    // gatherer resizes the viewport and waits for frames that hidden views may not paint.
    const result = await snapshot(page, {
      flags: {
        onlyCategories: ["accessibility", "seo", "best-practices"],
        formFactor: "desktop",
        screenEmulation: { disabled: true },
        throttlingMethod: "provided",
        disableStorageReset: true,
        disableFullPageScreenshot: true,
      },
    })

    if (!result)
      throw new Error(
        "Lighthouse did not produce a report. Check browser.console and browser.network.list for page failures and confirm the tab has loaded. Report an audit failure if the page is healthy; do not repeat the audit unchanged.",
      )

    return {
      scores: Object.values(result.lhr.categories).map((category) => ({
        id: category.id,
        title: category.title,
        score: category.score,
      })),
      failures: Object.values(result.lhr.audits)
        .filter((audit) => audit.score !== null && audit.score < 1)
        .map((audit) => ({ id: audit.id, title: audit.title, description: audit.description }))
        .slice(0, 100),
      files: await Promise.all([
        files.save("lighthouse.json", "application/json", Buffer.from(generateReport(result.lhr, "json")), [
          ...resources,
          contents.getURL(),
        ]),
        files.save("lighthouse.html", "text/html", Buffer.from(generateReport(result.lhr, "html")), [
          ...resources,
          contents.getURL(),
        ]),
      ]),
    }
  } finally {
    contents.debugger.off("message", event)
    await Promise.all(Array.from(sessions.values(), (session) => session.detach().catch(() => undefined)))
  }
}

import { encodeFilePath } from "@opencode/util/path"
import type { Files } from "../sdk"

/** The file:// URL of a workspace-relative path. */
export function workspaceFileURL(files: Files, path: string) {
  return `file://${encodeFilePath(`${files.root.replaceAll("\\", "/").replace(/\/+$/, "")}/${path}`)}`
}

import type { MainSetup } from "../sdk/main"
import type definition from "./index"
import type { Pane } from "./pane"
import { BrowserPane } from "./ipc"

/** The pane once a window first registered one. */
type LoadedPane = { pane?: Promise<Pane> }

const setup: MainSetup<typeof definition> = (ctx) => {
  const loaded: LoadedPane = {}

  // The pane brings the CDP driver and the full RPC client with every protocol schema;
  // load it when a window first registers a pane instead of at startup.
  const load = () =>
    (loaded.pane ??= import("./pane").then((module) =>
      module.createBrowserPane({
        windows: ctx.windows,
        serverEndpoints: ctx.serverEndpoints,
        storage: ctx.storage,
        refs: ctx.stores.refs,
        embeds: ctx.embeds,
        emit: (window, value) => provider.emit("event", value, window),
      }),
    ))

  // Every other call names a binding, and bindings exist only after a register loaded the pane.
  const existing = () => loaded.pane ?? Promise.reject(new Error("browser.pane.unavailable"))

  const provider = ctx.provide(BrowserPane, {
    register: async (input, caller) => (await load()).register(caller.window, input.binding, input),
    load: async (input, caller) => (await existing()).load(caller.window, input.binding, input.tabID),
    command: async (input, caller) => (await existing()).command(caller.window, input.binding, input.command),
    inspect: async (input, caller) =>
      (await existing()).inspect(caller.window, input.binding, input.tabID, input.enabled),
    highlight: async (input, caller) =>
      (await existing()).highlight(caller.window, input.binding, input.tabID, input.ref),
    zoom: async (input, caller) => (await existing()).zoom(caller.window, input.binding, input.tabID, input.zoom),
    site: async (input, caller) => (await existing()).site(caller.window, input.binding, input.tabID),
    clearSite: async (input, caller) => (await existing()).clearSite(caller.window, input.binding, input.tabID),
    close: async (input, caller) => (await existing()).close(caller.window, input.binding),
  })

  // The host withdraws the Ipc before this runs, so windows hear nothing; they suspend on the Ipc going away.
  ctx.scope.addFinalizer(async () => {
    if (loaded.pane) await (await loaded.pane).dispose()
  })
}

export default setup

import { batch, createRoot, createSignal, getOwner, onCleanup } from "solid-js"
import { createStore, reconcile } from "solid-js/store"
import { makeEventListener } from "@solid-primitives/event-listener"
import type { Browser } from "@opencode/plugin-browser/rpc"
import { createKeyed, type SessionRef, type SetupContext } from "../sdk"
import { readHref } from "./comment"
import {
