import type definition from "./index"
import { workspaceFileURL } from "./link"
import { BrowserPane, type PaneEvent } from "./ipc"

type Session = Pick<SessionRef, "key">

/** What panels read. `registration` numbers each registration so a new one is observable. */
type Attachment = {
  registration?: number
  browser: Browser.State | null
  embeds: Readonly<Record<string, string>>
  suspended: boolean
  error?: string
}

type Live = {
  ref: SessionRef
  connection: Connection
  registration?: Registration
  revision: number
  /** Strip writes waiting for the session's location, without which the strip cannot be written. */
  held: { mirror?: () => void; focus?: Browser.TabID }
  /** The agent's previews waiting for the session's screen, which resolves their paths. */
  previews: string[]
  dispose: () => void
}

type ModelState = {
  attachments: Record<string, Attachment | undefined>
  /** Servers whose plugin lacks the browser RPC; sessions on them stop retrying. */
  unsupported: Record<string, true | undefined>
  errors: Record<string, string | undefined>
  /** Each session's page icons and zoom by tab, as this desktop reports them. */
  pages: Record<string, Record<string, PageDetail | undefined> | undefined>
}

/** A page's icon as a data URL, and its zoom factor, 1 at 100%. */
type PageDetail = { icon?: string; zoom: number }

/** A mounted pane; the newest one answers the reload and inspect commands. */
type PaneHandle = {
  visible: () => boolean
  address: () => string
  reload: () => void
  /** Closes the selected browser tab, including a blank page. */
  close: () => void
  inspectable: () => boolean
  /** Turns the element picker on or off. */
  inspect: () => void
  /** Focuses the address field and selects its text. */
  focusAddress: () => void
}

export type Model = ReturnType<typeof createModel>

// Attachments belong to the shell session tab, not the session route: native pages and the agent's
// browser survive visiting Settings or another tab and close when the session tab does.
export function createModel(ctx: SetupContext<typeof definition>) {
  const sessions = ctx.sessions
  const layout = ctx.layout
  const links = ctx.links
  // The extension's own main entry provides the pane. `uses` declares it by reference; its full token, which this chunk
  // loads with the protocol schemas, resolves it.
  const pane = ctx.uses.pane.load(BrowserPane)

  const client = () => {
    const current = pane()

    return current.status === "active" ? current.value : undefined
  }

  const owner = getOwner()
  const history = ctx.stores.history
  const [state, setState] = createStore<ModelState>({ attachments: {}, unsupported: {}, errors: {}, pages: {} })
  const [panes, setPanes] = createSignal<readonly PaneHandle[]>([])
  const live = new Map<string, Live>()
  const listeners = new Map<string, (event: PaneEvent) => void>()
  const inspectors = new Map<string, Set<(event: InspectEvent) => void>>()
  const addressed = new Map<string, Set<(tabID: Browser.TabID) => void>>()
  // Sessions where the user just opened a tab; its pane focuses the address field once the blank page shows.
  const opening = new Set<string>()
  // Each tab's last recorded page, so a state that repeats it does not write the history again.
  const recorded = new Map<string, string>()
  const key = (tabID: string) => `${ctx.id}:${tabID}`

  // Main names why it moved control elsewhere or refused an address; any other failure is a failed request.
  const describe = (error: string) => {
    if (error === "browser.pane.replaced") return ctx.t("replaced")

    if (error === "browser.address.credentials") return ctx.t("refused.credentials")

    if (error === "browser.address.workspace") return ctx.t("refused.workspace")

    if (error === "browser.address.web") return ctx.t("refused.web")

    return ctx.t("common.requestFailed")
  }

  // Pages the user or the agent opened, once loaded: only a tab whose page exists has a real URL and title, as a
  // restored tab's saved URL carries no title until it loads again. Only the desktop's own reports count: a restored
  // tab's embed arrives before its page loads, with the saved URL as if it had.
  const record = (session: string, next: { browser: Browser.State | null; embeds: Readonly<Record<string, string>> }) =>
    next.browser?.tabs.forEach((tab) => {
      if (tab.loading || tab.loadError || !next.embeds[tab.id] || !recordable(tab.url)) return
      const page = `${tab.url}\n${tab.title}`

      if (recorded.get(`${session}\n${tab.id}`) === page) return
      recorded.set(`${session}\n${tab.id}`, page)
      history.set({
        visits: remember(
          history.value.visits,
          { url: tab.url, title: tab.title },
          state.pages[session]?.[tab.id]?.icon,
        ),
      })
    })

  // The SDK removes the listener when the Ipc's generation ends.
  createKeyed(pane, (current) => current.on("event", (value) => listeners.get(value.binding)?.(value.event)))

  const wakeCurrent = () => {
    if (document.visibilityState !== "visible") return
    const view = sessions.current()

    if (view) live.get(view.key)?.connection.wake()
  }

  // The pane's Ipc goes away while its main extension reloads or is disabled, taking every binding with it.
  // Each attachment keeps its tabs and registers again once the Ipc is back. Created before the first attachment,
  // so its first run finds nothing to refresh or wake.
  createKeyed(
    pane,
    () => {
      live.forEach((entry) => entry.connection.refresh())
      wakeCurrent()
    },
    { otherwise: () => live.forEach((entry) => entry.connection.refresh()) },
  )

  const close = (id: string) => {
    live.get(id)?.dispose()
    live.delete(id)
    opening.delete(id)
    Array.from(recorded.keys())
      .filter((item) => item.startsWith(`${id}\n`))
      .forEach((item) => recorded.delete(item))
    batch(() => {
      setState("attachments", id, undefined)
      setState("pages", id, undefined)
    })
  }

  const attach = (ref: SessionRef) => {
    const id = ref.key

    if (live.has(id) || state.unsupported[ref.server.id] || !ref.server.compatible) return

    const entry: Live = {
      ref,
      revision: 0,
      held: {},
      previews: [],
      dispose: () => undefined,
      connection: createConnection({
        client,
        listen(binding, listener) {
          listeners.set(binding, listener)

          return () => {
            listeners.delete(binding)
          }
        },
        target: () => ({ server: ref.server.id, session: ref.id }),
        // Focus requests write to the owning session's panel even while another shell tab is routed,
        // so the side panel and browser tab are already selected when the user returns to it.
        focus: (tabID) => {
          if (!ref.location) {
            entry.held.focus = tabID

            return
          }

          layout.open(key(tabID), ref, { tab: "select" })
        },
        preview: (path) => preview(entry, path),
        inspect: (event) => inspectors.get(id)?.forEach((listener) => listener(event)),
        page: (event) => {
          setState("pages", id, (pages) => ({
            ...pages,
            [event.tabID]: event.icon ? { icon: event.icon, zoom: event.zoom } : { zoom: event.zoom },
          }))
          const url = tab({ key: id }, event.tabID)?.url
          const visits = url && event.icon ? withIcon(history.value.visits, url, event.icon) : undefined

          if (visits) history.set({ visits })
        },
        address: (tabID) => addressed.get(id)?.forEach((listener) => listener(tabID)),
        change: (next, mirror, native) => {
          if (next.error === "browser.pane.unsupported") {
            setState("unsupported", ref.server.id, true)

            return close(id)
          }

          if (next.registration !== entry.registration) {
            entry.registration = next.registration

            if (next.registration) entry.revision++
          }

          batch(() => {
            setState(
              "attachments",
              id,
              reconcile({
                registration: next.registration ? entry.revision : undefined,
                browser: next.browser,
                embeds: next.embeds,
                suspended: next.suspended,
                error: next.error ? describe(next.error) : undefined,
              }),
            )

            if (native) record(id, next)

            // After the store: closing a strip tab asks this model whether the desktop still has it.
            if (ref.location) return mirror()
            entry.held.mirror = mirror
          })
        },
        strip: {
          stored: () => layout.stored(ref),
          open(tabID) {
            if (layout.state(key(tabID), ref) === "closed") layout.open(key(tabID), ref, { tab: "append" })
          },
          close: (tabID) => layout.close(key(tabID), ref),
        },
      }),
    }

    live.set(id, entry)
    setState("attachments", id, { browser: null, embeds: {}, suspended: false })

    // The attachment's own root, not the route effect that happened to call attach(), so `entry.dispose` ends it.
    const unwatch = createRoot((dispose) => {
      // A new session appears in the UI before its server-side creation finishes. The listeners follow the server's
      // live data: a re-authenticated server gets a new controller under the same ref.
      createKeyed(
        () => ref.server.data,
        (data) => {
          onCleanup(
            data.on("session.created", (event) => {
              if (event.data.sessionID === ref.id) entry.connection.wake()
            }),
          )
          onCleanup(
            data.on("session.execution.started", (event) => {
              if (event.data.sessionID === ref.id) entry.connection.wake()
            }),
          )
        },
      )

      // Mirrors the desktop's inventory and focus requests into the strip: writes held while the session's location
      // was unknown land once the server reports it.
      createKeyed(
        () => ref.location,
        () =>
          batch(() => {
            const held = entry.held
            entry.held = {}
            held.mirror?.()

            if (held.focus) layout.open(key(held.focus), ref, { tab: "select" })
          }),
      )

      // Previews made while another session was on screen open once the user returns to this one.
      createKeyed(
        () => sessions.current()?.key === ref.key && ctx.screen.current(),
        () => entry.previews.splice(0).forEach((path) => preview(entry, path)),
      )

      return dispose
    }, owner)

    if (!ref.pending) entry.connection.wake()
    entry.dispose = () => {
      unwatch()
      entry.connection.dispose()
    }
  }

  // The routed session attaches, once its server is compatible.
  createKeyed(() => {
    const view = sessions.current()

    if (!view?.id) return
    const ref = sessions.list().find((item) => item.key === view.key)

    return ref?.server.compatible ? ref : undefined
  }, attach)

  // An attachment closes with its shell tab, or when its server stops being compatible. The store's keys mirror `live`,
  // and reading them follows new attachments.
  createKeyed(
    () => {
      const owned = new Set(sessions.list().map((ref) => ref.key))

      const stale = Object.keys(state.attachments).filter((id) => {
        const entry = live.get(id)

        return !!entry && !(owned.has(id) && entry.ref.server.compatible)
      })

      return stale.length > 0 ? stale : undefined
    },
    (stale) => stale.forEach(close),
  )
  onCleanup(() => Array.from(live.keys()).forEach(close))

  // These are edges, not a reactive dependency on suspended state: eviction while the window
  // remains focused must not immediately reopen the browser and defeat resource cleanup.
  createKeyed(() => sessions.current()?.key, wakeCurrent)
  makeEventListener(window, "focus", wakeCurrent)
  makeEventListener(document, "visibilitychange", wakeCurrent)
  makeEventListener(document, "pointerdown", wakeCurrent)
  makeEventListener(document, "keydown", wakeCurrent)

  const attachment = (session: Session) => state.attachments[session.key]

  const attached = (session: Session) => {
    const value = attachment(session)

    return value?.registration !== undefined || !!value?.browser
  }

  // The desktop has not answered with its first inventory yet: the routed session is about to attach, or it registered
  // and waits.
  const pending = (session: SessionRef) => {
    const value = attachment(session)

    if (!value) return !state.unsupported[session.server.id] && session.server.compatible && !session.pending

    return value.registration !== undefined && !value.browser && !value.error
  }

  const available = (session: SessionRef) =>
    !state.unsupported[session.server.id] && !!session.id && session.server.compatible && !layout.narrow()

  const tab = (session: Session, tabID: string) => attachment(session)?.browser?.tabs.find((item) => item.id === tabID)

  const command = (session: Session, action: Browser.Action) => {
    const id = session.key
    batch(() => {
      setState("errors", id, undefined)

      if (state.attachments[id]) setState("attachments", id, "error", undefined)
    })

    // An unreachable pane is suspended, not a failed request. A tab that never opened has no address field to focus.
    const failed = (cause: unknown) => {
      if (action.type === "tabs.open") opening.delete(id)

      if (!unavailable(cause)) setState("errors", id, describe(cause instanceof Error ? cause.message : ""))
    }

    const connection = live.get(id)?.connection

    if (!connection) return failed(new Error("browser.pane.unavailable"))
    void connection.command(action).catch(failed)
  }

  const openURL = (session: Session, url: string) => command(session, { type: "tabs.open", url })

  // Only the routed session has a file model to resolve workspace paths with: the session screen's.
  const files = (session: Session) => {
    const screen = ctx.screen.current()

    return screen && sessions.current()?.key === session.key ? screen.file : undefined
  }

  // The desktop's own sidecar shares this disk, and its browser pane accepts file:// URLs inside the
  // session workspace only. Forwarded loopback servers do not qualify, matching the desktop policy.
  const canOpen = (session: SessionRef, path?: string) => {
    if (!session.server.builtin || !available(session) || !attached(session)) return false

    if (path === undefined) return true
    const current = files(session)

    return !!current && !current.absolute(path)
  }

  const openFile = (session: Session, path: string) => {
    const current = files(session)

    if (current) openURL(session, workspaceFileURL(current, path))
  }

  // The agent's browser.preview tool: the file extension opens HTML in the browser, other files in the file panel. Only the
  // session's screen resolves workspace paths, so a preview for a session that is not on screen waits for it.
  const preview = (entry: Live, path: string) => {
    const view = sessions.current()

    if (view?.key === entry.ref.key && ctx.screen.current()) {
      links.open({ href: path, session: view, background: true })

      return
    }

    if (!entry.previews.includes(path)) entry.previews.push(path)
  }

  return {
    available,
    attached,
    canOpen,
    openFile,
    openURL,
    command,
    tab,
    /** Opens a blank tab for the user, whose pane then focuses the address field. */
    open(session: SessionRef) {
      if (!available(session)) return
      opening.add(session.key)
      command(session, { type: "tabs.open" })
    },
    /** Whether the user just opened a tab in this session; true once, for the pane that focuses its address. */
    opened: (session: Session) => opening.delete(session.key),
    /** A page's icon and zoom, once this desktop reported them. */
    page: (session: Session, tabID: string) => state.pages[session.key]?.[tabID],
    zoom(session: Session, tabID: Browser.TabID, zoom: Zoom) {
      live.get(session.key)?.connection.zoom(tabID, zoom)
    },
    /** The page's cookie count; undefined while the pane cannot answer. */
    site: (session: Session, tabID: Browser.TabID) => live.get(session.key)?.connection.site(tabID),
    /** Deletes the page's cookies and stored data, and reloads it. */
    clearSite: (session: Session, tabID: Browser.TabID) => live.get(session.key)?.connection.clearSite(tabID),
    /** Pages the browser showed, newest first. */
    visits: () => history.value.visits,
    clearHistory: () => {
      recorded.clear()
      history.set({ visits: [] })
    },
    /** The page asking for the address field with its shortcut. */
    onAddress(session: Session, listener: (tabID: Browser.TabID) => void) {
      const set = addressed.get(session.key) ?? new Set()
      set.add(listener)
      addressed.set(session.key, set)

      return () => {
        set.delete(listener)

        if (!set.size) addressed.delete(session.key)
      }
    },
    pending,
    /**
     * Tab IDs to list in the side panel: the desktop's inventory, limited to tabs stored in the strip. Until the first
     * inventory arrives, the stored tabs, so a restored selection holds; that inventory then prunes the ones it lacks.
     */
    tabs(session: SessionRef, open: readonly string[]) {
      if (pending(session)) return open

      if (!attached(session)) return []

      return attachment(session)?.browser?.tabs.flatMap((item) => (open.includes(item.id) ? [item.id] : [])) ?? []
    },
    error: (session: Session) => state.errors[session.key] ?? attachment(session)?.error,
    suspended: (session: Session) => attachment(session)?.suspended ?? false,
    /** The host embed of a tab's page, once main created the page. */
    embed: (session: Session, tabID: string) => attachment(session)?.embeds[tabID],
    /**
     * Creates a restored tab's page, which then reports its embed. Holds for the caller's scope: a new registration,
     * e.g. after a suspension, has no page for the tab and loads it again.
     */
    load(session: Session, tabID: Browser.TabID) {
      createKeyed(
        () => attachment(session)?.registration,
        () => live.get(session.key)?.registration?.load(tabID),
      )
    },
    closeTab(session: Session, tabID: string) {
      const item = tab(session, tabID)

      if (item) command(session, { type: "tabs.close", tabID: item.id })
    },
    focusTab(session: Session, tabID: string) {
      const item = tab(session, tabID)

      if (item && item.id !== attachment(session)?.browser?.focusedTabID)
        command(session, { type: "tabs.focus", tabID: item.id })
    },
    /** The page's element picker starting, stopping, or picking an element. */
    onInspect(session: Session, listener: (event: InspectEvent) => void) {
      const set = inspectors.get(session.key) ?? new Set()
      set.add(listener)
      inspectors.set(session.key, set)

      return () => {
        set.delete(listener)

        if (!set.size) inspectors.delete(session.key)
      }
    },
    inspect(session: Session, tabID: Browser.TabID, enabled: boolean) {
      live.get(session.key)?.connection.inspect(tabID, enabled)
    },
    /** Flashes a picked element, or clears any highlight when ref is omitted. */
    highlight(session: Session, tabID: Browser.TabID, ref?: Browser.Ref) {
      live.get(session.key)?.connection.highlight(tabID, ref)
    },
    /** Shows the browser tab a comment names and flashes its element while the page still has it. */
    reveal(session: SessionRef, href: string) {
      const target = readHref(href)
      const item = target && tab(session, target.tabID)

      if (!item) return
      layout.open(key(item.id), session, { tab: "select" })

      if (target.ref) live.get(session.key)?.connection.highlight(item.id, target.ref)
    },
    pane: () => panes()[0],
    mount(handle: PaneHandle) {
      setPanes((list) => [handle, ...list])

      return () => setPanes((list) => list.filter((item) => item !== handle))
    },
  }
}

import { net, session, type WebContents } from "electron"
import type { RpcClient } from "@opencode/client/effect/api"
import type { Session } from "@opencode/schema/session"
import { Browser } from "@opencode/plugin-browser/rpc"
import { BrowserProxy } from "@opencode/plugin-browser/proxy"
import { Effect } from "effect"
import { Base64 } from "effect/encoding"

export type BrowserNetwork = Effect.Success<ReturnType<typeof createBrowserNetwork>>

export const createBrowserNetwork = Effect.fn("BrowserNetwork.create")(function* (input: {
  rpc: RpcClient<typeof Browser.Definition, unknown>
  attachment: { sessionID: Session.ID; connectionID: string }
  location: { directory: string; workspace?: string }
  partition: string
}) {
  const options = { location: input.location }

  const proxy = yield* Effect.acquireRelease(
    Effect.tryPromise(() =>
      BrowserProxy.make({
        open: (target, signal) =>
          Effect.runPromise(input.rpc["tunnel.open"]({ ...input.attachment, target }, options), { signal }),
        read: (tunnelID, signal) =>
          Effect.runPromise(input.rpc["tunnel.read"]({ ...input.attachment, tunnelID }, options), { signal }),
        write: (tunnelID, data, end, signal) =>
          Effect.runPromise(
            input.rpc["tunnel.write"]({ ...input.attachment, tunnelID, data: Base64.encode(data), end }, options),
            { signal },
          ),
        close: (tunnelID) =>
          Effect.runPromise(
            input.rpc["tunnel.close"]({ ...input.attachment, tunnelID }, options).pipe(Effect.timeout("5 seconds")),
          ),
      }),
    ),
    (proxy) => Effect.promise(() => proxy.close()),
  )

  const partition = session.fromPartition(input.partition)
  yield* Effect.addFinalizer(() => Effect.promise(() => partition.closeAllConnections()))
  // This is the browser's private partition, not the app/API connection. Never
  // bypass localhost: it must resolve on the machine running the OC2 server.
  yield* Effect.tryPromise(() =>
    partition.setProxy({ mode: "fixed_servers", proxyRules: proxy.url, proxyBypassRules: "<-loopback>" }),
  )
  yield* Effect.tryPromise(() => partition.closeAllConnections())

  return {
    attach(contents: WebContents) {
      const login = (
        event: Electron.Event,
        _details: Electron.AuthenticationResponseDetails,
        auth: Electron.AuthInfo,
        callback: (username?: string, password?: string) => void,
      ) => {
        if (
          !auth.isProxy ||
          auth.scheme !== "basic" ||
          auth.host !== proxy.host ||
          auth.port !== proxy.port ||
          auth.realm !== "OpenCode Browser Proxy"
        )
          return
        event.preventDefault()
        callback(proxy.credentials.username, proxy.credentials.password)
      }

      contents.on("login", login)
      contents.setWebRTCIPHandlingPolicy("disable_non_proxied_udp")

      return () => contents.off("login", login)
    },
    /**
     * Fetches a page icon through the server's network, as the page loaded it. Resolves undefined for anything but a
     * small image: a failure, a timeout, another content type, or more than `MAX_ICON_BYTES`.
     */
    icon: (url: string) =>
      new Promise<{ mime: string; data: Buffer } | undefined>((resolve) => {
        const request = net.request({ url, session: partition, useSessionCookies: true, redirect: "follow" })
        const chunks: Buffer[] = []

        const finish = (value?: { mime: string; data: Buffer }) => {
          clearTimeout(timeout)
          resolve(value)
        }

        const fail = () => {
          request.abort()
          finish()
        }

        const timeout = setTimeout(fail, 5_000)
        request.on("login", (auth, callback) => {
          if (auth.isProxy && auth.host === proxy.host && auth.port === proxy.port)
            return callback(proxy.credentials.username, proxy.credentials.password)
          callback()
        })
        request.on("response", (response) => {
          const header = response.headers["content-type"]
          const mime = (Array.isArray(header) ? header[0] : header)?.split(";")[0]?.trim().toLowerCase() ?? ""

          if (response.statusCode !== 200 || !mime.startsWith("image/")) return fail()
          response.on("data", (chunk) => {
            chunks.push(chunk)

            if (chunks.reduce((size, item) => size + item.length, 0) > MAX_ICON_BYTES) fail()
          })
          response.on("end", () => finish({ mime, data: Buffer.concat(chunks) }))
          response.on("error", fail)
        })
        request.on("error", fail)
        request.end()
      }),
  }
})

/** Icons larger than this are not worth reducing; sites list a favicon of a few kilobytes. */
const MAX_ICON_BYTES = 256 * 1024

import { createSignal, Show } from "solid-js"
import { Icon } from "@opencode/ui/icon"

/**
 * A page's icon, or the globe while it has none or its image fails to decode. Clicks pass through to what holds it, so
 * the address field focuses from its icon too.
 */
export function PageIcon(props: { icon: string | undefined; class?: string }) {
  // The icon that failed; a new icon for the page is tried again.
  const [broken, setBroken] = createSignal<string>()

  return (
    <Show
      when={props.icon !== broken() ? props.icon : undefined}
      fallback={<Icon name="outline-globe" class={`pointer-events-none size-4 shrink-0 ${props.class ?? ""}`} />}
    >
      {(icon) => (
        <img
          src={icon()}
          alt=""
          class="pointer-events-none size-4 shrink-0 object-contain"
          onError={() => setBroken(icon())}
        />
      )}
    </Show>
  )
}

import { NodeHttpClient } from "@effect/platform-node"
import { Browser } from "@opencode/plugin-browser/rpc"
import { OpenCode } from "@opencode/client/effect"
import { SessionID } from "@opencode/schema/session-id"
import electron, { type BrowserWindow } from "electron"
import { Deferred, Effect, ManagedRuntime, Queue, Schedule, Schema, Stream } from "effect"
import { HttpClient, HttpClientRequest } from "effect/http"
import type { Embeds, Persisted, ServerEndpoints, Storage, Windows } from "../sdk/main"
import { createBrowserPage, type BrowserPage, type Shared } from "./chromium"
import { browserFailure } from "./errors"
import { createBrowserNetwork, type BrowserNetwork } from "./network"
import { destinationOrigin, fileURLWithin, refusal } from "./policy"
import { createRefs } from "./refs"
import type { PaneEvent } from "./ipc"
import { createBrowserRestoreStore } from "./restore"

type Target = { readonly server: string; readonly session: string; readonly restore?: Browser.State }

type Entry = {
  binding: string
  window: number
  win: BrowserWindow
  abort: AbortController
  registered: ReturnType<typeof Promise.withResolvers<void>>
  requests: Map<string, { abort: AbortController; tabID?: Browser.TabID }>
  report?: (event: PaneEvent) => void
  cleanup?: () => void
  pages: Map<Browser.TabID, BrowserPage>
  tabs: Map<Browser.TabID, Browser.Tab>
  focusedTabID: Browser.TabID | null
  partition: string
  lastState?: string
  network?: BrowserNetwork
  storageKey: string
  /**
   * Workspace directories whose files may load as file:// documents. Set only for the desktop's
   * own sidecar: a forwarded or explicit loopback server does not share this machine's disk.
   */
  fileRoots: string[]
}

export type Pane = ReturnType<typeof createBrowserPane>

export function createBrowserPane(input: {
  readonly windows: Windows
  readonly serverEndpoints: ServerEndpoints
  readonly storage: Storage
  /** The declared store of reserved element refs. */
  readonly refs: Persisted<number, number>
  readonly embeds: Embeds
  readonly emit: (window: number, value: { readonly binding: string; readonly event: PaneEvent }) => void
}) {
  const entries = new Map<string, Entry>()
  const restore = createBrowserRestoreStore(input.storage)
  const shared: Shared = { ref: createRefs(input.refs) }
  // Page disposals in flight. Finishing a trace or CPU profile can hold a page open, and the pane's own disposal waits
  // for them so a replacement never starts beside old pages still recording.
  const releasing = new Set<Promise<void>>()
  // Keep long-lived RPC requests off Chromium's shared HTTP connection pool.
  const runtime = ManagedRuntime.make(NodeHttpClient.layerNodeHttp)
  let disposed = false

  return {
    async register(window: number, binding: string, target: Target) {
      const server = input.serverEndpoints.get(target.server)

      if (disposed || !server || !destinationOrigin(server.url)) throw new Error("browser.pane.registration.invalid")

      if (server.username && !server.password) throw new Error("browser.pane.endpoint.invalid")
      const win = input.windows.get(window)

      if (!win || entries.has(binding)) throw new Error("browser.pane.owner.invalid")

      if (win.isDestroyed() || win.webContents.isDestroyed()) throw new Error("browser.pane.owner.unavailable")
      const sessionID = SessionID.make(target.session)
      const storageKey = `${target.server}\n${sessionID}`
      const saved = restore.load(storageKey)

      const previous = target.restore ?? {
        tabs: saved.tabs.map((tab) => ({
          ...tab,
          title: "",
          generation: 0,
        })),
        focusedTabID: saved.focusedTabID,
      }

      const entry: Entry = {
        binding,
        window,
        win,
        abort: new AbortController(),
        registered: Promise.withResolvers(),
        requests: new Map(),
        pages: new Map(),
        tabs: new Map(
          previous.tabs.map((tab) => [
            tab.id,
            {
              ...tab,
              loading: false,
              canGoBack: false,
              canGoForward: false,
              generation: tab.generation + 1,
            },
          ]),
        ),
        focusedTabID: previous.focusedTabID,
        partition: `opencode-browser-${crypto.randomUUID()}`,
        storageKey,
        fileRoots: [],
      }

      // Navigation guards cover documents; subresources (img, script, fetch) also must not read
      // file: URLs outside the roots. One listener per partition covers every page in this attachment.
      electron.session
        .fromPartition(entry.partition)
        .webRequest.onBeforeRequest({ urls: ["file://*/*"] }, (details, callback) =>
          callback({ cancel: !fileURLWithin(details.url, entry.fileRoots) }),
        )
      // "unsupported" means the server has no browser plugin; the renderer stops retrying.
      let reason: "browser.pane.unsupported" | "browser.pane.replaced" | "browser.pane.suspended" | undefined
      let attached = false
      const stop = () => close(entry, reason)

      const navigate = (event: Electron.Event<{ isMainFrame: boolean; isSameDocument: boolean }>) => {
        if (event.isMainFrame && !event.isSameDocument) stop()
      }

      win.webContents.once("destroyed", stop)
      win.webContents.on("did-start-navigation", navigate)
      entry.cleanup = () => {
        if (win.isDestroyed()) return
        win.webContents.off("destroyed", stop)
        win.webContents.off("did-start-navigation", navigate)
      }

      entries.set(binding, entry)
      void runtime
        .runPromise(
          Effect.gen(function* () {
            const http = yield* HttpClient.HttpClient

            // The renderer never holds the managed sidecar's password; Node requests bypass
            // the webRequest header injection, so the host resolves the credential here in main.
            const client = yield* OpenCode.make({ baseUrl: server.url }).pipe(
              Effect.provideService(
                HttpClient.HttpClient,
                Object.keys(server.headers).length
                  ? HttpClient.mapRequest(http, HttpClientRequest.setHeaders(server.headers))
                  : http,
              ),
            )

            const session = yield* client.session.get({ sessionID })

            // The agent can already read this workspace, so showing its files adds no access.
            if (server.local) entry.fileRoots = [session.location.directory]

            const options = {
              location: { directory: session.location.directory, workspace: session.location.workspaceID },
            }

            const attachment = { sessionID, connectionID: crypto.randomUUID() }
            const rpc = client.rpc(Browser.Definition)
            entry.network = yield* createBrowserNetwork({
              rpc,
              attachment,
              location: options.location,
              partition: entry.partition,
            })
            const connected = yield* Deferred.make<void>()
            const outbound = yield* Queue.unbounded<Effect.Effect<void>>()

            // A send that fails because the server already replaced or closed this attachment must
            // not decide the close reason; only the attach call's outcome does.
            const send = (effect: Effect.Effect<unknown, unknown>) =>
              Queue.offerUnsafe(
                outbound,
                effect.pipe(Effect.catchCause((cause) => Effect.logWarning("Browser send failed", cause))),
              )

            const reply = (requestID: string, outcome: Browser.Outcome) =>
              send(
                rpc.result({ ...attachment, requestID, outcome: Schema.encodeSync(Browser.Outcome)(outcome) }, options),
              )

            // Report state before publishing it locally or completing a command. The server's copy of
            // the inventory resolves every tab ID, so a state is retried until it arrives or the
            // attachment ends; the results queued behind it then never name a tab the server lacks.
            // "unavailable" means the server already dropped this attachment, which attach reports.
            entry.report = (event) => {
              const local = Effect.sync(() => publish(entry, event))

              if (event.type !== "state") return send(local)
              send(
                rpc.state({ ...attachment, state: event.state ?? { tabs: [], focusedTabID: null } }, options).pipe(
                  Effect.retry({
                    while: (error) => !("type" in error && error.type === "unavailable"),
                    schedule: Schedule.min([Schedule.exponential("250 millis"), Schedule.spaced("10 seconds")]),
                  }),
                  Effect.ensuring(local),
                ),
              )
            }

            const receive = client.event.subscribe().pipe(
              Stream.runForEach((event) =>
                Effect.gen(function* () {
                  if (event.type === "server.connected") {
                    yield* Deferred.succeed(connected, undefined)

                    return
                  }

                  if (
                    event.type !== "rpc.experimental.browser.control" ||
                    event.data.connectionID !== attachment.connectionID
                  )
                    return

                  const message = yield* Schema.decodeUnknownEffect(Browser.Control)(event.data).pipe(
                    Effect.tapError(() =>
                      Effect.sync(() => {
                        reason = "browser.pane.unsupported"
                      }),
                    ),
                  )

                  if (message.type === "attached") {
                    attached = true

                    return entry.registered.resolve()
                  }

                  if (message.type === "cancel") return entry.requests.get(message.requestID)?.abort.abort()
                  const abort = new AbortController()
                  entry.requests.set(message.requestID, { abort })
                  yield* rpc.command({ ...attachment, requestID: message.requestID }, options).pipe(
                    Effect.flatMap((command) =>
                      Effect.promise(async () => {
                        entry.requests.set(
                          message.requestID,
                          "tabID" in command.action ? { abort, tabID: command.action.tabID } : { abort },
                        )
                        reply(
                          message.requestID,
                          await execute(entry, command, abort.signal).then(
                            (result) => ({ type: "success" as const, result }),
                            (cause: unknown) => browserFailure(command.action, cause),
                          ),
                        )
                      }),
                    ),
                    Effect.ensuring(Effect.sync(() => entry.requests.delete(message.requestID))),
                    // An operation this desktop cannot decode comes from a newer plugin; answer it so
                    // the agent does not wait out the server's timeout.
                    Effect.tapError((error) =>
                      Effect.sync(() => {
                        if (!Schema.isSchemaError(error)) return
                        reply(message.requestID, {
                          type: "failure",
                          code: "unsupported",
                          message:
                            "This desktop app does not support the requested browser operation. Ask the user to update the desktop app, or use another operation.",
                        })
                      }),
                    ),
                    // A request that vanished (cancelled before retrieval) fails only that request.
                    // Transport loss surfaces through the event stream and attach call instead.
                    Effect.catchCause((cause) =>
                      abort.signal.aborted ? Effect.void : Effect.logWarning("Browser command failed", cause),
                    ),
                    Effect.forkScoped,
                  )
                }),
              ),
            )

            yield* Effect.raceAllFirst([
              receive,
              Stream.fromQueue(outbound).pipe(Stream.runForEach((send) => send)),
              Deferred.await(connected).pipe(
                Effect.andThen(rpc.attach({ ...attachment, version: 4 }, options)),
                Effect.tap((result) =>
                  Effect.sync(() => {
                    if (result === "replaced") reason = "browser.pane.replaced"
                  }),
                ),
              ),
            ])
          }).pipe(
            Effect.scoped,
            Effect.tapError((error) =>
              Effect.sync(() => {
                const type = error instanceof Object && "type" in error ? error.type : undefined

                if (type === "rpc.unavailable" && attached) {
                  reason = "browser.pane.suspended"

                  return
                }

                if (type === "rpc.unavailable" || type === "rpc.method_not_found" || type === "rpc.invalid_input")
                  reason = "browser.pane.unsupported"
              }),
            ),
            Effect.ensuring(Effect.sync(stop)),
          ),
          { signal: entry.abort.signal },
        )
        .catch(stop)
      const timeout = setTimeout(stop, 15_000)
      await entry.registered.promise.finally(() => clearTimeout(timeout))

      if (entries.get(binding) !== entry) throw new Error("browser.pane.registration.closed")
      publishState(entry)
    },
    load(window: number, binding: string, tabID: Browser.TabID) {
      load(owned(window, binding), tabID)
    },
    async inspect(window: number, binding: string, tabID: Browser.TabID, enabled: boolean) {
      await owned(window, binding).pages.get(tabID)?.inspect(enabled)
    },
    async highlight(window: number, binding: string, tabID: Browser.TabID, ref?: Browser.Ref) {
      await owned(window, binding).pages.get(tabID)?.highlight(ref)
    },
    zoom(window: number, binding: string, tabID: Browser.TabID, direction: "in" | "out" | "reset") {
      owned(window, binding).pages.get(tabID)?.zoom(direction)
    },
    async site(window: number, binding: string, tabID: Browser.TabID) {
      return (await owned(window, binding).pages.get(tabID)?.site()) ?? { cookies: 0 }
    },
    async clearSite(window: number, binding: string, tabID: Browser.TabID) {
      await owned(window, binding).pages.get(tabID)?.clearSite()
    },
    async command(window: number, binding: string, command: Browser.Action) {
      const entry = owned(window, binding)
      const url = command.type === "navigate" || command.type === "tabs.open" ? command.url : undefined
      // The window explains a refused address by its code; the agent's commands get main's own message instead.
      const reason = url === undefined ? undefined : refusal(url, { fileRoots: entry.fileRoots })

      if (reason) throw new Error(reason)
      await execute(entry, { action: command, files: [] }, new AbortController().signal)
    },
    async close(window: number, binding: string) {
      const entry = owned(window, binding)
      restore.remove(entry.storageKey)
      close(entry)
    },
    /**
     * The extension is going away (reload, disable, or quit). Windows keep each pane's tabs as a
     * suspended attachment, like an idle server eviction, and register again once the pane is back.
     */
    async dispose() {
      disposed = true
      entries.forEach((entry) => close(entry, "browser.pane.suspended"))
      await Promise.all(releasing)
      await runtime.dispose()
    },
  }

  function owned(window: number, binding: string) {
    const entry = entries.get(binding)

    if (!entry || entry.window !== window) throw new Error("browser.pane.unavailable")

    return entry
  }

  function publish(entry: Entry, event: PaneEvent) {
    if (!entries.has(entry.binding) || entry.win.isDestroyed() || entry.win.webContents.isDestroyed()) return
    input.emit(entry.window, { binding: entry.binding, event })
  }

  function close(entry: Entry, reason = "browser.pane.registration.closed") {
    if (entries.get(entry.binding) !== entry) return
    entry.report = undefined
    entry.requests.forEach((request) => request.abort.abort())
    entry.requests.clear()
    const suspended = reason === "browser.pane.suspended"

    if (suspended) publishState(entry, reason)
    entry.pages.forEach((page) => void release(page).catch(() => undefined))
    entry.pages.clear()
    entry.tabs.clear()
    entry.focusedTabID = null

    if (!suspended) publishState(entry, reason)
    entries.delete(entry.binding)
    entry.registered.reject(new Error("browser.pane.registration.closed"))
    entry.cleanup?.()
    entry.abort.abort()
  }

  async function closePage(entry: Entry, tabID: Browser.TabID, error?: string) {
    const page = entry.pages.get(tabID)

    if (!entry.tabs.has(tabID))
      throw new Error(
        "This tab is no longer available. Call browser.tabs.list({}) and use an existing tabID from this session.",
      )
    const focused = entry.focusedTabID === tabID
    entry.requests.forEach((request) => {
      if (request.tabID === tabID) request.abort.abort()
    })
    entry.pages.delete(tabID)
    entry.tabs.delete(tabID)

    if (focused) entry.focusedTabID = entry.tabs.keys().next().value ?? null

    if (page) await release(page)
    publishState(entry, error)
  }

  function release(page: BrowserPage) {
    const done = page.dispose()
    const settled = done.catch(() => undefined)
    releasing.add(settled)
    void settled.finally(() => releasing.delete(settled))

    return done
  }

  function publishState(entry: Entry, error?: string) {
    const current = { type: "state" as const, state: inventory(entry) }
    const event = error === undefined ? current : { ...current, error }

    // Teardown publishes an empty inventory to the renderer, but the saved URLs survive app exit.
    if (entry.report)
      restore.save(entry.storageKey, {
        tabs: event.state.tabs.map((tab) => ({
          id: tab.id,
          // A restored page can publish before Chromium assigns its URL.
          url: tab.url || entry.tabs.get(tab.id)?.url || "about:blank",
        })),
        focusedTabID: entry.focusedTabID,
      })
    const next = JSON.stringify(event)

    if (entry.lastState === next) return
    entry.lastState = next
    report(entry, event)
  }

  function report(entry: Entry, event: PaneEvent) {
    if (entry.report) return entry.report(event)
    publish(entry, event)
  }

  function inventory(entry: Entry): Browser.State {
    return {
      tabs: Array.from(entry.tabs, ([id, tab]) => entry.pages.get(id)?.state() ?? tab),
      focusedTabID: entry.focusedTabID,
    }
  }

  function load(entry: Entry, tabID: Browser.TabID) {
    const page = entry.pages.get(tabID)

    if (page) return page
    const tab = entry.tabs.get(tabID)

    return tab ? create(entry, true, undefined, tab) : undefined
  }

  function create(
    entry: Entry,
    initialize = true,
    popupOptions?: Electron.BrowserWindowConstructorOptions,
    restore?: Browser.Tab,
  ) {
    if (!entry.network) throw new Error("Browser network is not ready; no tab was opened.")
    const id = restore?.id ?? Browser.TabID.make(`tab_${crypto.randomUUID()}`)

    const fail = () => {
      if (entry.pages.has(id)) void closePage(entry, id, "page_crashed").catch(() => undefined)
    }

    const page = createBrowserPage(entry.win, {
      id,
      partition: entry.partition,
      network: entry.network,
      initialize,
      restore,
      popupOptions,
      fileRoots: () => entry.fileRoots,
      shared,
      embeds: input.embeds,
      fail,
      publish: (error) => {
        if (entry.pages.has(id)) publishState(entry, error)
      },
      inspect: (event) => {
        if (entry.pages.has(id)) report(entry, { type: "inspect", tabID: id, ...event })
      },
      // Icons and zoom are local to this desktop, but wait behind the states reported before them, so the window files
      // a new page's icon under that page's URL.
      detail: (value) => {
        if (entry.pages.has(id)) report(entry, { type: "page", tabID: id, ...value })
      },
      zoomed: () => entry.pages.forEach((page) => page.detail()),
      address: () => {
        if (!entry.pages.has(id) || entry.win.isDestroyed()) return
        // The page held keyboard focus; the app's address field needs it back.
        entry.win.webContents.focus()
        publish(entry, { type: "address", tabID: id })
      },
      popup: (popupOptions, background) => {
        const popup = create(entry, false, popupOptions)

        if (!background) focus(entry, popup.state().id)

        return popup.contents
      },
    })

    entry.pages.set(id, page)
    entry.tabs.set(id, restore ?? page.state())
    // Straight to the window, not through the server report: the embed is local to this desktop.
    publish(entry, { type: "embed", tabID: id, embed: page.embed })
    void page.ready
      .then(() => {
        if (entry.pages.get(id) === page) publishState(entry)
      })
      .catch(fail)

    return page
  }

  async function execute(entry: Entry, command: Browser.Command, signal: AbortSignal) {
    const action = command.action

    if (signal.aborted)
      throw new Error(
        "Browser request was cancelled. Do not repeat a mutating action until you have inspected its outcome.",
      )

    if (action.type === "tabs.list") return { value: inventory(entry), files: [] }

    if (action.type === "preview") {
      // The renderer owns file tabs; it resolves the path against the session's workspace.
      report(entry, { type: "preview", path: action.path })

      return { value: { path: action.path }, files: [] }
    }

    if (action.type === "tabs.open") {
      const page = create(entry)

      if (action.focus !== false) focus(entry, page.state().id)
      await page.ready
      await page.execute(
        { action: { type: "navigate", tabID: page.state().id, url: action.url ?? "about:blank" }, files: [] },
        signal,
      )
      publishState(entry)

      return { value: page.state(), files: [] }
    }

    const tab = inventory(entry).tabs.find((tab) => tab.id === action.tabID)

    if (!tab)
      throw new Error(
        "Browser tab is unavailable. Call browser.tabs.list({}) and use an existing tabID from this session; a closed tab is not replaced automatically.",
      )

    if (action.type === "tabs.focus") {
      focus(entry, action.tabID)

      return { value: tab, files: [] }
    }

    if (action.type === "tabs.close") {
      await closePage(entry, action.tabID)

      return { value: inventory(entry), files: [] }
    }

    const page = entry.pages.get(action.tabID) ?? create(entry, true, undefined, tab)
    await page.ready
    const result = await page.execute(command, signal)
    publishState(entry)

    return result
  }

  function focus(entry: Entry, tabID: Browser.TabID) {
    entry.focusedTabID = tabID
    publishState(entry)
    report(entry, { type: "focus", tabID })
  }
}

