    const embeds = input.createEmbeds({ bridge: bridge as Bridge, zoom: () => 1, dialog: () => false })

    const t = (key: string, params?: Readonly<Partial<Record<string, string | number>>>) =>
      (messages.get(key) ?? language.t(key)).replace(/\{\{(\w+)\}\}/g, (_, name: string) =>
        String(params?.[name] ?? ""),
      )

    const base = {
      id: "browser",
      keybinds: { keybind: () => [], keys: (bind: string) => bind.split("+") },
      desktop: { zoom: () => 1 },
      embeds,
      t,
      // English plural forms, as the host picks them.
      plural: (key: string, count: number) => t(`${key}.${count === 1 ? "one" : "other"}`, { count }),
    }

    const panel: PanelFrame = {
      visible: () => store.visible,
      present: () => store.visible,
      placement: () => "side",
      reserve: () => false,
      animate: () => false,
      sidebar: { opened: () => false, width: () => 0, transition: () => false, resize() {}, toggle() {} },
      open: () => [],
    }

    const server = {
      id: "browser-test",
      name: "Local",
      local: true,
      compatible: true,
      data: { on: () => () => undefined },
    }

    const [reads, setReads] = createStore({ directory: 0 })

    // Frozen session refs, as the real host supplies. Only the key belongs in the pane's transient state.
    const views = new Map(
      ["Alpha", "Beta", "Empty"].map((key) => {
        const value = Object.freeze({
          key,
          id: key,
          server,
          pending: false,
          location: { directory: "/repo" },
          get directory() {
            setReads("directory", (count) => count + 1)

            return "/repo"
          },
        })

        // SAFETY: the pane reads only `key`; the real model reads these listed fields and `server.data.on`.
        // oxlint-disable-next-line anti-slop/no-chained-type-assertions -- see SAFETY above
        return [key, value as unknown as MountedSession] as const
      }),
    )

    const session = () => views.get(store.session) ?? views.get("Alpha")

    // The session screen: one object that follows the route, with the composer the pane attaches comments to.
    // SAFETY: the pane reads only file.search and composer.attach; the model's workspace-link paths are not invoked.
    // oxlint-disable-next-line anti-slop/no-chained-type-assertions -- see SAFETY above
    const screen = {
      file: { search: async () => [] },
      composer: { attach: (note: ComposerNote) => setStore("comments", (items) => [...items, note]) },
    } as unknown as SessionScreen

    const report = (key = store.session) => {
      const tab = tabs.find((item) => item.title === key)

      if (!tab) return
      emit(key, {
        type: "state",
        state: {
          tabs: [
            {
              ...tab,
              url: store.url ?? tab.url,
              loading: store.loading,
              generation: store.generation,
              loadError: store.loadErrors[key],
            },
          ],
          focusedTabID: tab.id,
        },
        error: store.error,
      })
    }

    // Address rejection counters and cleanup run through the real model over this main-process Ipc boundary.
    const pane: PaneClient = {
      register: async (value) => {
        bindings.set(value.session, value.binding)
        queueMicrotask(() => {
          report(value.session)
          const tab = tabs.find((item) => item.title === value.session)

          if (tab) emit(value.session, { type: "embed", tabID: tab.id, embed: `embed-${tab.title}` })
        })
      },
      load: async () => undefined,
      command: async (value) => {
        const command = value.command
        // Main refuses what it does not open before anything happens, naming why.
        const reason = command.type === "navigate" ? refusal(command.url) : undefined

        if (reason) throw new Error(reason)
        setStore("error", undefined)

        if (command.type === "navigate" || command.type === "reload") setStore("loadErrors", store.session, undefined)

        if (command.type === "navigate") {
          if (store.delayNavigation) {
            setStore("pendingURL", command.url)

            return
          }

          setStore({ url: command.url, loading: false, generation: store.generation + 1 })
        }

        if (command.type === "stop") setStore("loading", false)
        report()
      },
      // The desktop confirms each picker change, as the page does once inspect mode is armed.
      inspect: async (value) => {
        const key = Array.from(bindings).find((item) => item[1] === value.binding)?.[0]

        if (!key) throw new Error("Unknown picker binding")
        setStore("picker", key, value.enabled)
        emit(key, { type: "inspect", tabID: value.tabID, active: value.enabled })
      },
      highlight: async (value) => {
        const key = Array.from(bindings).find((item) => item[1] === value.binding)?.[0]

        if (!key) throw new Error("Unknown highlight binding")
        setStore("highlights", (items) => [...items, { sessionKey: key, ref: value.ref }])
      },
      // Main steps through Chromium's presets and reports the page's new zoom.
      zoom: async (value) => {
        const steps = [0.9, 1, 1.1, 1.25]
        const index = steps.indexOf(store.zoom)
        const next = value.zoom === "reset" ? 1 : (steps[index + (value.zoom === "in" ? 1 : -1)] ?? store.zoom)
        setStore("zoom", next)
        emit(store.session, { type: "page", tabID: value.tabID, zoom: next })
      },
      site: async () => ({ cookies: store.cookies }),
      // Main deletes the site's data and reloads the page.
      clearSite: async () => {
        setStore({ cookies: 0, generation: store.generation + 1 })
        report()
      },
      close: async () => undefined,
      state: () => undefined,
      on: (_name, listener) => {
        // SAFETY: the pane's Ipc has one event, whose payload is exactly this binding and PaneEvent.
        const added = listener as (value: { binding: string; event: PaneEvent }) => void
        listeners.add(added)

        return () => void listeners.delete(added)
      },
    }

    const live = Live.accessor(() => ({ status: "active", generation: 1, value: pane }))

    const fake = {
      ...base,
      uses: { pane: { load: () => live } },
      sessions: { current: session, list: () => Array.from(views.values()).filter((view) => view.key !== "Empty") },
      screen: { current: () => screen },
      layout: { narrow: () => false, stored: () => [], state: () => "visible", open() {}, close() {} },
      links: { open() {} },
      stores: {
        history: {
          get value() {
            return store.history
          },
          set: (next: History) => setStore("history", reconcile(next)),
        },
      },
      system: {
        copy: async () => undefined,
        openExternal: (url: string) => setStore("external", (items) => [...items, url]),
      },
    }

    // SAFETY: the real model and pane use only the host boundaries implemented above in this fixture's flows.
    // oxlint-disable-next-line anti-slop/no-chained-type-assertions -- see SAFETY above
    const extension = fake as unknown as Context & SetupContext<typeof definition>
    const model = createModel(extension)

    const pick = () => {
      setStore("picker", store.session, false)
      emit(store.session, {
        type: "inspect",
        tabID: current().id,
        active: false,
        element: {
          ref: Browser.Ref.make("e7"),
          selector: "main > button.primary",
          label: "button.primary",
          role: "button",
          name: "Save changes",
          rect: { x: 48, y: 40, width: 160, height: 36 },
        },
      })
    }

    return (
      <ExtensionContext.Provider value={extension}>
        <PanelContext.Provider value={panel}>
          {/* The extension contributes the bar's styles through the host's Style registry, which this fixture skips.
              Menus and suggestions portal into <body>, under this fixture's fixed host unless raised above it. */}
          <style>{`${barStyles}\n[data-popper-positioner] { z-index: 1001 !important; }`}</style>
          <h1 style={{ "font-size": "24px", "margin-bottom": "16px" }}>Browser pane lifecycle</h1>
          <nav style={{ display: "flex", "flex-wrap": "wrap", gap: "12px", margin: "16px 0" }}>
            <For each={["Alpha", "Beta", "Empty"]}>
              {(name) => <button onClick={() => setStore({ session: name, mounted: name !== "Empty" })}>{name}</button>}
            </For>
            <button onClick={() => setStore("mounted", false)}>Unmount pane</button>
            <button
              onClick={() => {
                setStore({ url: "about:blank", loading: false })
                report()
              }}
            >
              Blank page
            </button>
            <button
              onClick={() => {
                setStore({ url: "about:blank", loading: true })
                report()
              }}
            >
              Loading page
            </button>
            <button
              onClick={() => {
                setStore({
                  loading: true,
                  generation: store.generation + 1,
                  loadErrors: { [store.session]: undefined },
                })
                report()
              }}
            >
              Load current page
            </button>
            <button
              onClick={() => {
                setStore("loadErrors", store.session, "ERR_CONNECTION_REFUSED")
                report()
              }}
            >
              Failed page
            </button>
            <button onClick={() => setStore("delayNavigation", true)}>Delay navigation</button>
            <button
              onClick={() => {
                setStore({ error: "browser.address.web", pendingURL: undefined })
                report()
              }}
            >
              Block navigation
            </button>
            <button
              onClick={() => {
                setStore({
                  url: store.pendingURL,
                  pendingURL: undefined,
                  loading: false,
                  generation: store.generation + 1,
                })
                report()
              }}
            >
              Complete navigation
            </button>
            <button onClick={() => setStore("visible", (visible) => !visible)}>Toggle Review tab</button>
            <button onClick={() => setStore("holdCapture", true)}>Hold capture</button>
            <button onClick={() => held.splice(0).forEach((resolve) => resolve())}>Release capture</button>
            <button onClick={() => setStore("covered", (covered) => !covered)}>Toggle popover</button>
            <button onClick={pick}>Pick element</button>
            <button onClick={() => setStore("history", { visits })}>Seed history</button>
            <button onClick={() => emit(store.session, { type: "page", tabID: current().id, icon, zoom: store.zoom })}>
              Page icon
            </button>
            <button onClick={() => emit(store.session, { type: "address", tabID: current().id })}>
              Address shortcut
            </button>
          </nav>
          <p>Captures: {store.captures}</p>
          <p>Zoom: {Math.round(store.zoom * 100)}</p>
          <p>Visits: {store.history.visits.map((visit) => visit.url).join(" ")}</p>
          <p>External: {store.external.join(" ")}</p>
          <p>Session getter reads: {reads.directory}</p>
          <p>Picker: {store.picker[store.session] ? "on" : "off"}</p>
          <For each={tabs}>
            {(tab) => (
              <p>
                Picker {tab.title}: {store.picker[tab.title] ? "on" : "off"}
              </p>
            )}
          </For>
          <p>Highlights: {store.highlights.map((item) => item.ref ?? "clear").join(",")}</p>
          <p>Highlight owners: {store.highlights.map((item) => item.sessionKey).join(",")}</p>
          <div style={{ position: "relative", width: "640px", height: "360px", border: "1px solid #555" }}>
            <Show when={store.mounted && session()}>
              {(view) => <SessionBrowserPane tab={() => current()} session={view()} screen={screen} model={model} />}
            </Show>
          </div>
          <ul data-testid="fixture-comments">
            <For each={store.comments}>
              {(note) => (
                <li>
                  {note.label} {note.live?.href?.includes("#") ? `@${note.live.href.split("#")[1]}` : "(no ref)"}:{" "}
                  {note.comment}
                </li>
              )}
            </For>
          </ul>
          <Show when={store.covered}>
            {/* Floating content portals into <body> like a menu or hover card over the page. */}
            <Portal mount={document.body}>
              <div
                data-popper-positioner
                style={{
                  position: "fixed",
                  top: "0",
                  left: "0",
                  width: "320px",
                  height: "480px",
                  "z-index": "1001",
                  "pointer-events": "none",
                }}
              />
            </Portal>
          </Show>
          <For each={tabs}>
            {(tab) => (
              <div
                data-testid={`native-${tab.title}`}
                data-visible={!!store.layouts[`embed-${tab.title}`]?.visible}
                style={{ padding: "12px", margin: "8px 0", border: "1px solid #555" }}
              >
                {tab.title}: {store.layouts[`embed-${tab.title}`]?.visible ? "visible" : "hidden"}
              </div>
            )}
          </For>
        </PanelContext.Provider>
      </ExtensionContext.Provider>
    )
  }

  return render(
    () => (
      <input.LanguageProvider locale="en">
        <input.UiI18nBridge>
          <Fixture />
        </input.UiI18nBridge>
      </input.LanguageProvider>
    ),
    host,
  )
}

type StripTabs = {
  all(): string[]
  active(): string | undefined
  setAll(all: string[]): void
  setActive(tab: string | undefined): void
  close(tab: string): void
  remap(rewrite: (tab: string) => string): void
}

type PaneClient = IpcClient<(typeof BrowserPane)["spec"]>

/** The app's extension host and side region, passed in by `packages/app/component-tests/browser-pane-restore.spec.ts`. */
type RegionHost = {
  LanguageProvider: Component<{ locale: string; children: JSX.Element }>
  ExtensionHostProvider: Component<
    ParentProps<{
      definitions: readonly Definition[]
      disabled: Accessor<ReadonlySet<string> | undefined>
      /** The HostApis the fixture provides, by context property; the host provides links and dialogs itself. */
      apis: { readonly [api: string]: (extension: string) => object | undefined }
      /** Runs once the app interface mounts; the fixture's is always mounted. */
      whenMounted: (run: () => void) => () => void
      ipc: (token: Ipc) => PaneClient | undefined
    }>
  >
  useExtensionHost(): { ready(): boolean }
  createRegion(input: {
    region: "side"
    view: Accessor<MountedSession>
    screen: SessionScreen
    tabs: Accessor<StripTabs>
  }): {
    keys(): readonly string[]
    active(): string | undefined
    entry(key: string): { readonly tab: PanelTab; readonly extension: string; readonly provider: Panel } | undefined
  }
  /** The real browser and file extensions. */
  definitions: readonly Definition[]
  /** Real shell command providers for shortcut cases. */
  Shell: ParentComponent
  /** Shell fallback and the real extension command adapter. */
  Commands: Component<{ close: () => void }>
  /** The real host wrapper that renders an extension in its context. */
  Contribution: Component<{ extension: string; children: () => JSX.Element }>
}

type RegionFixtureState = {
  session: string
  strips: Record<string, { all: string[]; active?: string }>
  /** Each registration of a pane binding, with how many tabs it asked main to restore. */
  registrations: { binding: string; session: string; restore: number }[]
  /** The pane's Ipc is gone, as while its main extension reloads or is disabled. */
  away: boolean
  /** Whether the fixture's shell session was closed by its fallback shortcut. */
  closed: boolean
  /** The page main reports, blank or loaded. */
  blank: boolean
  /** Native browser tab close requests, by tab id. */
  closes: string[]
}

// Component-test fixture: the real side region over the real browser and file extensions, with the host's
// session, layout, and storage HostApis and the pane's main-process Ipc faked at their boundaries. Alpha was
// left on a file tab; Beta on a browser tab whose page the desktop reports only with its first inventory.
export function mountBrowserRegion(input: RegionHost) {
  const host = document.createElement("main")
  host.dataset.testid = "browser-region-fixture"
  host.style.cssText = "position:fixed;inset:0;z-index:1000;background:#181818;color:#eee;padding:24px"
  document.body.appendChild(host)

  function Fixture() {
    const alpha = "browser-test\nses_alpha"
    const beta = "browser-test\nses_beta"
    const tabID = Browser.TabID.make("tab_33333333-3333-3333-3333-333333333333")

    const [store, setStore] = createStore<RegionFixtureState>({
      session: alpha,
      strips: {
        [alpha]: { all: ["file://alpha.ts"], active: "file://alpha.ts" },
        [beta]: { all: ["file://beta.ts", `browser:${tabID}`], active: `browser:${tabID}` },
      },
      registrations: [],
      away: false,
      closed: false,
      blank: false,
      closes: [],
    })

    // The file tree's state, Changes or All files, as the file extension stores it.
    const [tree, setTree] = createSignal<object>()
    const strip = (session: string) => store.strips[session] ?? { all: [] }
    const setAll = (session: string, all: string[]) => setStore("strips", session, "all", all)

    const close = (session: string, key: string) =>
      batch(() => {
        setAll(
          session,
          strip(session).all.filter((item) => item !== key),
        )

        if (strip(session).active === key) setStore("strips", session, "active", undefined)
      })

    const server = {
      id: "browser-test",
      name: "Browser test",
      url: "http://127.0.0.1:4096",
      data: { on: () => () => undefined },
      local: true,
      builtin: true,
      compatible: true,
      connected: true,
    }

    const location = { directory: "/repo" }

    const refs = [alpha, beta].map(
      // SAFETY: the extensions read only these fields of a listed session, and of its server the ones `server` has.
      // oxlint-disable-next-line anti-slop/no-chained-type-assertions -- see SAFETY above
      (key) => ({ key, id: key.split("\n")[1], tab: key, server, pending: false, location }) as unknown as SessionRef,
    )

    // The session screen's file model, which follows the route.
    const file = {
      root: "/repo",
      ready: () => false,
      resolve: (path: string) => path.replace(/^file:\/\//, ""),
      absolute: () => false,
      get: () => undefined,
      missing: () => false,
      sync: async () => undefined,
      exists: async () => true,
      search: async () => [],
    }

    // One object per routed session, as the host gives each its own.
    const views = new Map(
      [alpha, beta].map((key) => {
        const routed = {
          key,
          id: key.split("\n")[1],
          tab: key,
          visit: {},
          server,
          pending: false,
          location,
          directory: "/repo",
          local: true,
          background: [],
        }

        // SAFETY: the browser and file extensions read only these fields of the routed session in this fixture's flows.
        // oxlint-disable-next-line anti-slop/no-chained-type-assertions -- see SAFETY above
        return [key, routed as unknown as MountedSession] as const
      }),
    )

    const fallback = views.get(alpha)

    if (!fallback) throw new Error("The fixture has no Alpha session")

    const view = () => views.get(store.session) ?? fallback

    // One screen object while the strip mounts, whichever session it routes.
    // SAFETY: this fixture draws file tab triggers and the browser pane. Its file model implements list,
    // normalize and focus; the browser has a composer attach callback. File-view operations are never invoked here.
    // oxlint-disable-next-line anti-slop/no-chained-type-assertions -- see SAFETY above
    const screen = { file, composer: { attach() {} } } as unknown as SessionScreen

    const layout = (extension: string): Layout => ({
      narrow: () => false,
      ready: () => true,
      open(key, session, options) {
        if (!strip(session.key).all.includes(key)) setAll(session.key, [...strip(session.key).all, key])

        if (options?.tab !== "append") setStore("strips", session.key, "active", key)
      },
      close: (key, session) => close(session.key, key),
      toggle() {},
      state(key, session) {
        if (strip(session.key).active === key) return "visible"

        return strip(session.key).all.includes(key) ? "open" : "closed"
      },
      stored: (session) =>
        strip(session.key).all.flatMap((key) =>
          key.startsWith(`${extension}:`) ? [key.slice(extension.length + 1)] : [],
        ),
      side: { opened: () => true, toggle() {} },
      sidebar: { opened: () => true },
      dock: { opened: () => false, placement: () => "side" },
      scroll: { get: () => undefined, set() {} },
      settings() {},
      project() {},
    })

    const keep = <T extends object>(key: string, initial: T) => {
      const [value, set] = createStore<T>(structuredClone(initial))

      if (key === "file:tree") setTree(() => value)

      return {
        memory: [value, (mutation: (draft: T) => void) => set(produce(mutation))] as const,
        store: {
          value,
          ready: () => true,
          update: (mutate: (draft: Mutable<T>) => undefined) =>
            set(
              produce((draft) => {
                // SAFETY: keep uses Solid's writable produce draft; readonly schema fields apply only to readers.
                const returned = mutate(draft as Mutable<T>)

                if (returned !== undefined) throw new Error("Use set(next) to replace the value.")
              }),
            ),
          set: (next: T) => set(reconcile(next)),
        },
      }
    }

    // Loaded at once.
    const storage = (extension: string): Storage => ({
      store: (key, options) => keep(`${extension}:${key}`, options.initial).store,
      memory: (key, options) => keep(`${extension}:${key}`, options.initial).memory,
      remove() {},
    })

    const build: Build = { version: "", channel: "dev", platform: "desktop", packaged: false }
    const locale: Locale = { locale: () => "en", direction: () => "ltr", setDirection() {} }
    const appearance: Appearance = { font: () => "monospace" }
    const router: Router = { routing: () => false, path: () => "/" }
    const keybinds: Keybinds = { keybind: () => [], keys: (bind) => bind.split("+"), matches: () => false }
    const servers: Servers = { list: () => [server.id], get: () => undefined }
    const workspaces: Workspaces = { on: () => () => undefined }

    const listeners = new Set<(value: { binding: string; event: PaneEvent }) => void>()

    const pane: PaneClient = {
      register: async (value) => {
        setStore("registrations", (items) => [
          ...items,
          { binding: value.binding, session: value.session, restore: value.restore?.tabs.length ?? 0 },
        ])
      },
      load: async () => undefined,
      command: async (value) => {
        if (value.command.type !== "tabs.close") return

        const tabID = value.command.tabID

        setStore("closes", (items) => [...items, tabID])
        listeners.forEach((listener) =>
          listener({ binding: value.binding, event: { type: "state", state: { tabs: [], focusedTabID: null } } }),
        )
      },
      inspect: async () => undefined,
      highlight: async () => undefined,
      zoom: async () => undefined,
      site: async () => ({ cookies: 0 }),
      clearSite: async () => undefined,
      close: async () => undefined,
      state: () => undefined,
      on: (_name, listener) => {
        // SAFETY: the pane's Ipc has one event, so every listener takes that event's payload.
        const added = listener as (value: { binding: string; event: PaneEvent }) => void
        listeners.add(added)

        return () => void listeners.delete(added)
      },
    }

    const apis = {
      build: () => build,
      locale: () => locale,
      appearance: () => appearance,
      router: () => router,
      keybinds: () => keybinds,
      servers: () => servers,
      workspaces: () => workspaces,
      desktop: () => ({ zoom: () => 1 }),
      embeds: () => ({ View: () => null, capture: async () => undefined }),
      system: () => ({ copy: async () => undefined, openExternal() {}, save: async () => false }),
      sessions: () => ({ list: () => refs, current: view }),
      screen: () => ({ current: () => screen }),
      layout,
      storage,
    }

    const latest = () => store.registrations.filter((item) => item.session === "ses_beta").at(-1)

    // The desktop answers Beta's latest registration with the tab it restored.
    const inventory = () => {
      const binding = latest()?.binding

      if (!binding) return

      const tab = {
        id: tabID,
        url: store.blank ? "about:blank" : "http://localhost:4173/",
        title: store.blank ? "" : "Preview",
        loading: false,
        canGoBack: false,
        canGoForward: false,
        generation: 0,
      }

      listeners.forEach((listener) =>
        listener({ binding, event: { type: "state", state: { tabs: [tab], focusedTabID: tabID } } }),
      )
    }

    // Mounts once every extension is active, as the session screen does.
    function Strip() {
      const region = input.createRegion({
        region: "side",
        view,
        screen,
        tabs: () => ({
          all: () => strip(view().key).all,
          active: () => strip(view().key).active,
          setAll: (all) => setAll(view().key, all),
          setActive: (tab) => setStore("strips", view().key, "active", tab),
          close: (tab) => close(view().key, tab),
          remap(rewrite) {
            const all = strip(view().key).all
            const next = Array.from(new Set(all.map(rewrite)))

            if (next.length !== all.length || next.some((key, index) => key !== all[index])) setAll(view().key, next)
          },
        }),
      })

      const browser = () => {
        const entry = region.entry(region.active() ?? "")

        return entry?.extension === "browser" ? entry : undefined
      }

      return (
        <>
          {/* The host strip draws a trigger for each of these keys. */}
          <div role="tablist" aria-label="Side panel" style={{ display: "flex", gap: "8px", margin: "16px 0" }}>
            <For each={region.keys()}>
              {(key) => (
                <span role="tab" aria-selected={region.active() === key} style={{ padding: "4px 8px" }}>
                  {region.entry(key)?.tab.title}
                </span>
              )}
            </For>
          </div>
          <p data-testid="selected">{region.active() ?? "none"}</p>
          <Show when={browser()}>
            {(entry) => (
              <PanelContext.Provider
                value={{
                  visible: () => true,
                  present: () => true,
                  placement: () => "side",
                  reserve: () => false,
                  animate: () => false,
                  sidebar: { opened: () => false, width: () => 0, transition: () => false, resize() {}, toggle() {} },
                  open: () => [tabID],
                }}
              >
                <input.Contribution extension={entry().extension}>
                  {() =>
                    entry().provider.render({
                      get tab() {
                        return entry().tab
                      },
                      get session() {
                        return view()
                      },
                      screen,
                    })
                  }
                </input.Contribution>
              </PanelContext.Provider>
            )}
          </Show>
        </>
      )
    }

    function Ready(props: ParentProps) {
      const extensions = input.useExtensionHost()

      return <Show when={extensions.ready()}>{props.children}</Show>
    }

    return (
      <DialogProvider>
        <input.Shell>
          <input.ExtensionHostProvider
            definitions={input.definitions}
            disabled={() => new Set<string>()}
            apis={apis}
            whenMounted={(run) => {
              run()

              return () => undefined
            }}
            ipc={(token) => (token.id === BrowserPane.id && !store.away ? pane : undefined)}
          >
            <input.Commands close={() => setStore("closed", true)} />
            <h1 style={{ "font-size": "24px", "margin-bottom": "16px" }}>Restored side strip</h1>
            <nav style={{ display: "flex", gap: "12px", margin: "16px 0" }}>
              <button onClick={() => setStore({ session: beta, closed: false })}>Beta</button>
              <button onClick={inventory}>First inventory</button>
              <button
                onClick={() => {
                  setStore("blank", true)
                  inventory()
                }}
              >
                Blank page
              </button>
              <button onClick={() => setStore("away", true)}>Pane away</button>
              <button onClick={() => setStore("away", false)}>Pane back</button>
            </nav>
            <p>Registrations: {store.registrations.length}</p>
            <p>Beta restores: {latest()?.restore ?? 0}</p>
            <p data-testid="tree">{JSON.stringify(tree())}</p>
            <p data-testid="session-state">{store.closed ? "closed" : "open"}</p>
            <p data-testid="browser-closes">{JSON.stringify(store.closes)}</p>
            <Ready>
              <Strip />
            </Ready>
          </input.ExtensionHostProvider>
        </input.Shell>
      </DialogProvider>
    )
  }

  return render(
    () => (
      <input.LanguageProvider locale="en">
        <Fixture />
      </input.LanguageProvider>
    ),
    host,
  )
}

import { Popover } from "@kobalte/core/popover"
import { Button } from "@opencode/ui/button"
import { Icon } from "@opencode/ui/icon"
import type { IconName } from "@opencode/ui/icons/catalog"
import { IconButton } from "@opencode/ui/icon-button"
import { LineCommentEditor } from "@opencode/ui/line-comment"
import { Loader } from "@opencode/ui/loader"
import { Keybind } from "@opencode/ui/keybind"
import { Menu } from "@opencode/ui/menu"
import { showToast } from "@opencode/ui/toast"
import { Tooltip } from "@opencode/ui/tooltip"
import { createEventListener } from "@solid-primitives/event-listener"
import { createResizeObserver } from "@solid-primitives/resize-observer"
import { createMemo, For, on, onCleanup, Show, type Accessor, type JSX } from "solid-js"
import { createStore } from "solid-js/store"
import type { Browser } from "@opencode/plugin-browser/rpc"
import { createKeyed, useExtension, usePanel, type PanelTab, type MountedSession, type SessionScreen } from "../sdk"
import { addressParts, connection, loopback, resolveAddress, searches } from "./address"
import { commentNote, pageNote } from "./comment"
import { bare, completes, highlight, suggest, type Visit } from "./history"
import type { Model } from "./model"
import type { PaneElement } from "./ipc"
import { PageIcon } from "./page-icon"

type PaneState = {
  /** The address field's text while the user edits it, and the submitted address it keeps afterwards. */
  address: string
  editing: boolean
  /**
   * The report counts when an address was submitted; the next URL change, finished load or rejection shows the
   * page's URL.
   */
  kept: { followed: number; rejected: number } | undefined
  /** The movement count at a submit; the next reported movement ends the submitted navigation. */
  navigating: number | undefined
  /** The user typed since focusing the address field; suggestions follow typing, not a focused URL. */
  typed: boolean
  /** The suggestion Enter opens; -1 opens the typed text. */
  active: number
  /** Escape closed the suggestions; typing opens them again. */
  dismissed: boolean
  /** The tab whose element picker is on. */
  picking: { sessionKey: string; tabID: Browser.TabID } | undefined
  /** A picked element awaiting its comment. The page stays frozen as a still until it closes. */
  comment:
    | {
        sessionKey: string
        tabID: Browser.TabID
        url: string
        /** The tab's navigation count at the pick; the element's ref dies when it changes. */
        generation: number
        element: PaneElement
        draft: string
      }
    | undefined
  /** A comment on the whole page awaiting its text, frozen like an element comment. */
  note: { sessionKey: string; tabID: Browser.TabID; url: string; title: string; draft: string } | undefined
  size: { width: number; height: number }
  editorHeight: number
}

/** Suggestions the address field lists, and pages the new tab page lists. */
const SUGGESTIONS = 5

const RECENT = 5

export default function SessionBrowserPane(props: {
  tab: Accessor<PanelTab>
  session: MountedSession
  screen: SessionScreen
  model: Model
}) {
  const extension = useExtension()
  const keybinds = extension.keybinds
  const desktop = extension.desktop
  const embeds = extension.embeds
  const system = extension.system
  const panel = usePanel()
  const visible = () => panel.visible()
  const state = () => props.model.tab(props.session, props.tab().id)
  const address = () => (state()?.url === "about:blank" ? "" : (state()?.url ?? ""))
  const failed = () => !!state()?.loadError
  const suspended = () => props.model.suspended(props.session)
  const command = (action: Browser.Action) => props.model.command(props.session, action)

  const page = () => {
    const tab = state()

    return tab ? props.model.page(props.session, tab.id) : undefined
  }

  const [store, setStore] = createStore<PaneState>({
    address: "",
    editing: false,
    kept: undefined,
    navigating: undefined,
    typed: false,
    active: -1,
    dismissed: false,
    picking: undefined,
    comment: undefined,
    note: undefined,
    size: { width: 0, height: 0 },
    editorHeight: 0,
  })

  // Finished loads, counted. A submitted address that lands on the URL the page already had (say "example.com" on
  // https://example.com/) changes no URL, only this.
  const settled = createMemo(
    on(
      () => !!state()?.loading,
      (loading, previous, count: number = 0) => (previous && !loading ? count + 1 : count),
    ),
  )

  // Page reports, counted: a count moves on every report, even one that repeats a value. Tab switches, URL changes and
  // finished loads:
  const followed = createMemo(
    on([() => state()?.id, address, settled], (_input, _previous, count: number = 0) => count + 1),
  )

  // Rejections: a blocked or rejected request leaves the page where it was.
  const rejected = createMemo(
    on(
      () => props.model.error(props.session),
      (error, _previous, count: number = 0) => (error ? count + 1 : count),
    ),
  )

  // Any reported movement, including a rejected or blocked request. A command clearing the last error is not one.
  const moved = createMemo(
    on(
      [() => state()?.id, () => state()?.generation, () => state()?.loading, rejected],
      (_input, _previous, count: number = 0) => count + 1,
    ),
  )

  // A submitted navigation the browser has not reported yet; keeps the empty state hidden meanwhile.
  const navigating = () => store.navigating === moved()

  // The address field: the user's text while editing, and a submitted address until the page reports a URL change or a
  // rejection; otherwise the page's URL.
  const field = () => {
    if (store.editing) return store.address
    const kept = store.kept

    return kept?.followed === followed() && kept.rejected === rejected() ? store.address : address()
  }

  const empty = () => !address() && !state()?.loading && !navigating()
  // The desktop page hides blank and loading documents itself; only hide here
  // while the pane shows its own empty or failed state over the embed.
  const shown = () => visible() && !empty() && !failed()

  const embed = () => {
    const tab = state()

    return tab ? props.model.embed(props.session, tab.id) : undefined
  }

  let box: HTMLDivElement | undefined
  let input: HTMLInputElement | undefined
  let anchor: HTMLFormElement | undefined

  const error = () => {
    const value = props.model.error(props.session)

    if (value === "browser.pane.replaced") return extension.t("replaced")

    if (value === "browser.pane.unsupported") return extension.t("unsupported")

    return value
  }

  const inspectable = () => !!address() && !failed() && !suspended()
  const picking = () => store.picking?.sessionKey === props.session.key && store.picking?.tabID === state()?.id
  // A comment on a picked element freezes the page so its editor can float above it.
  const commenting = () => store.comment?.sessionKey === props.session.key && store.comment?.tabID === state()?.id
  const noting = () => store.note?.sessionKey === props.session.key && store.note?.tabID === state()?.id

  // The address field always shows the whole URL; at rest it draws the host emphasized.
  const parts = () => addressParts(field())
  const site = () => !!field() && !store.editing

  // Suggestions follow what the user typed; a focused address is not a query.
  const suggestions = createMemo(() =>
    store.editing && store.typed ? suggest(props.model.visits(), store.address, SUGGESTIONS) : [],
  )

  const listed = () => suggestions().length > 0 && !store.dismissed
  const chosen = () => (listed() ? suggestions()[store.active] : undefined)
  const recent = () => props.model.visits().slice(0, RECENT)

  // A loopback address opens on the machine that runs the server; the system browser here reaches it only when the
  // server runs here too.
  const reachable = () => {
    const url = address()

    if (!URL.canParse(url)) return false
    const parsed = new URL(url)

    if (parsed.protocol === "file:") return props.session.server.local

    return /^https?:$/.test(parsed.protocol) && (props.session.server.local || !loopback(parsed.hostname))
  }

  const setPicking = (current: NonNullable<PaneState["picking"]>, enabled: boolean) => {
    props.model.inspect({ key: current.sessionKey }, current.tabID, enabled)
    setStore("picking", enabled ? current : undefined)
  }

  const closeComment = () => {
    const current = store.comment

    if (!current) return
    props.model.highlight({ key: current.sessionKey }, current.tabID)
    setStore("comment", undefined)
  }

  const closeNote = () => setStore("note", undefined)

  const toggleInspect = () => {
    const tab = state()

    if (!tab || !inspectable()) return

    if (store.comment) closeComment()
    closeNote()
    setPicking({ sessionKey: props.session.key, tabID: tab.id }, !picking())
  }

  const focusAddress = () => {
    input?.focus()
    input?.select()
  }

  // Navigates the tab and keeps the submitted address in the field until the page reports where it went; a blank page
  // keeps the field empty. Ends editing here rather than on blur: a click elsewhere, such as a recent page, may have
  // blurred the field already.
  const go = (url: string) => {
    const tab = state()

    if (!tab) return
    setStore({
      editing: false,
      typed: false,
      active: -1,
      address: url === "about:blank" ? "" : url,
      navigating: moved(),
      kept: { followed: followed(), rejected: rejected() },
    })
    command({ type: "navigate", tabID: tab.id, url })
    input?.blur()
  }

  const step = (by: number) => {
    const count = suggestions().length

    if (!count) return
    setStore({
      dismissed: false,
      active: store.active + by < -1 ? count - 1 : ((store.active + by + 1) % (count + 1)) - 1,
    })
  }

  const submitComment = (value: string) => {
    const current = store.comment

    if (!current) return
    const tab = state()

    // The draft outlives a reload or agent navigation, but the ref no longer names anything.
    const live =
      props.session.key === current.sessionKey && tab?.id === current.tabID && tab.generation === current.generation

    // The owning screen's composer serves the session the pane shows.
    props.screen.composer.attach(
      commentNote({
        origin: extension.id,
        tabID: current.tabID,
        url: current.url,
        element: {
          ref: live ? current.element.ref : undefined,
          selector: current.element.selector,
          label: current.element.label,
          role: current.element.role,
          name: current.element.name,
          text: current.element.text,
        },
        comment: value,
      }),
    )
    closeComment()
  }

  const openNote = () => {
    const tab = state()

    if (!tab || !address()) return

    // The editor is already open: the button keeps what the user wrote.
    if (noting()) return

    if (picking() && store.picking) setPicking(store.picking, false)
    closeComment()
    setStore("note", { sessionKey: props.session.key, tabID: tab.id, url: tab.url, title: tab.title, draft: "" })
  }

  const submitNote = (value: string) => {
    const current = store.note

    if (!current) return
    props.screen.composer.attach(
      pageNote({
        origin: extension.id,
        tabID: current.tabID,
        url: current.url,
        title: current.title,
        label: current.title || addressParts(current.url).host || current.url,
        comment: value,
      }),
    )
    closeNote()
  }

  const zoomed = () => !!address() && (page()?.zoom ?? 1) !== 1

  const zoomPage = (direction: "in" | "out" | "reset") => {
    const tab = state()

    if (tab) props.model.zoom(props.session, tab.id, direction)
  }

  const copyLink = () => {
    const url = address()

    if (!url) return
    void system.copy(url).then(
      () => showToast({ title: extension.t("common.copied") }),
      () => showToast({ title: extension.t("common.requestFailed") }),
    )
  }

  // The picked element in surface pixels, and the editor anchored below it, above it, or over it.
  const spotlight = () => {
    const rect = store.comment?.element.rect

    if (!rect) return
    const zoom = desktop?.zoom() ?? 1

    return { x: rect.x / zoom, y: rect.y / zoom, width: rect.width / zoom, height: rect.height / zoom }
  }

  const placement = () => {
    const rect = spotlight()

    if (!rect) return
    const gap = 8
    const width = Math.max(0, Math.min(400, store.size.width - gap * 2))
    // The editor scrolls rather than growing past the surface, so its actions stay reachable.
    const maxHeight = Math.max(0, store.size.height - gap * 2)
    // Until the editor has been measured once, assume its default three-row height.
    const height = Math.min(store.editorHeight || 176, maxHeight)
    const left = Math.min(Math.max(gap, rect.x), Math.max(gap, store.size.width - width - gap))
    const below = rect.y + rect.height + gap
    const above = rect.y - gap - height

    const top =
      below + height <= store.size.height - gap
        ? below
        : above >= gap
          ? above
          : Math.max(gap, store.size.height - height - gap)

    return { left, top, width, maxHeight }
  }

  onCleanup(
    props.model.mount({
      visible,
      address,
      reload: () => {
        const tab = state()

        if (tab) command({ type: "reload", tabID: tab.id })
      },
      close: () => {
        const tab = state()

        if (tab) props.model.closeTab(props.session, tab.id)
      },
      inspectable,
      inspect: toggleInspect,
      focusAddress,
    }),
  )

  // The pane stays mounted when another session is routed; it listens to the routed session's picker.
  createKeyed(
    () => props.session.key,
    (sessionKey) =>
      onCleanup(
        props.model.onInspect({ key: sessionKey }, (event) => {
          if (event.active) {
            setStore("picking", { sessionKey, tabID: event.tabID })

            return
          }

          if (store.picking?.sessionKey === sessionKey && store.picking.tabID === event.tabID)
            setStore("picking", undefined)

          if (!event.element) return
          const tab = state()

          if (tab?.id !== event.tabID || !visible()) {
            props.model.highlight({ key: sessionKey }, event.tabID)

            return
          }

          setStore("comment", {
            sessionKey,
            tabID: tab.id,
            url: tab.url,
            generation: tab.generation,
            element: event.element,
            draft: "",
          })
        }),
      ),
  )

  // The page's address shortcut moves focus to this field when the page is the one on screen.
  createKeyed(
    () => props.session.key,
    (sessionKey) =>
      onCleanup(
        props.model.onAddress({ key: sessionKey }, (tabID) => {
          if (tabID === state()?.id && visible()) focusAddress()
        }),
      ),
  )

  // A tab the user just opened starts in its address field, once its blank page is on screen. Syncs DOM focus.
  createKeyed(
    () => (visible() && empty() ? state()?.id : undefined),
    () => {
      if (props.model.opened(props.session)) focusAddress()
    },
  )

  // A picker or comment belongs to the page on screen: the page's picker stops when its tab is switched away or the
  // pane hides, and a comment closes with its tab.
  const endPicker = () => {
    const current = store.picking

    if (current && (current.sessionKey !== props.session.key || current.tabID !== state()?.id || !visible()))
      setPicking(current, false)
  }

  onCleanup(() => {
    if (store.picking) setPicking(store.picking, false)
    closeComment()
  })

  createKeyed(visible, endPicker, { otherwise: endPicker })
  createKeyed(
    () => {
      const tab = state()

      return tab ? { session: props.session.key, tabID: tab.id } : undefined
    },
    (current) => {
      endPicker()

      if (store.comment?.sessionKey !== current.session || store.comment.tabID !== current.tabID) closeComment()

      if (store.note?.sessionKey !== current.session || store.note.tabID !== current.tabID) closeNote()
    },
    {
      equals: (previous, next) => previous.session === next.session && previous.tabID === next.tabID,
      otherwise: () => {
        endPicker()
        closeComment()
        closeNote()
      },
    },
  )
  // The page does not have focus while the picker waits for a hover, so Escape reaches the app.
  createEventListener(
    window,
    "keydown",
    (event) => {
      if (event.key !== "Escape" || !store.picking) return
      event.preventDefault()
      event.stopPropagation()
      setPicking(store.picking, false)
    },
    { capture: true },
  )
  createResizeObserver(
    () => box,
    (rect) => setStore("size", { width: rect.width, height: rect.height }),
  )

  // A restored tab has no page until the pane first shows it.
  createKeyed(
    () => {
      const tab = state()

      return tab && shown() && !embed() ? tab.id : undefined
    },
    (tabID) => props.model.load(props.session, tabID),
  )

  const tip = (label: string, keys?: readonly string[]): JSX.Element => (
    <div class="flex items-center gap-2">
      <span>{label}</span>
      <Show when={keys && keys.length > 0}>
        <Keybind keys={[...(keys ?? [])]} variant="neutral" />
      </Show>
    </div>
  )

  return (
    <aside id="browser-panel" class="relative size-full min-w-0 overflow-hidden bg-v2-background-bg-base flex flex-col">
      <div
        data-component="browser-bar"
        class="h-11 shrink-0 flex items-center gap-2 px-3 border-b-[0.5px] border-v2-border-border-muted"
      >
        <div class="flex shrink-0 items-center">
          <For each={["back", "forward"] as const}>
            {(direction) => (
              <Tooltip placement="top" value={extension.t(direction === "back" ? "common.goBack" : "common.goForward")}>
                <IconButton
                  variant="ghost-muted"
                  size="large"
                  disabled={!state()?.[direction === "back" ? "canGoBack" : "canGoForward"]}
                  aria-label={extension.t(direction === "back" ? "common.goBack" : "common.goForward")}
                  onClick={() => {
                    const tab = state()

                    if (tab) command({ type: direction, tabID: tab.id })
                  }}
                  icon={<Icon name={direction === "back" ? "outline-arrow-left" : "outline-arrow-right"} />}
                />
              </Tooltip>
            )}
          </For>
          <Tooltip
            placement="top"
            value={
              state()?.loading
                ? extension.t("action.stop")
                : tip(extension.t("action.reload"), keybinds.keybind("browser.reload"))
            }
          >
            <IconButton
              variant="ghost-muted"
              size="large"
              disabled={!state()?.loading && !address()}
              aria-label={extension.t(state()?.loading ? "action.stop" : "action.reload")}
              onClick={() => {
                const tab = state()

                if (tab) command({ type: tab.loading ? "stop" : "reload", tabID: tab.id })
              }}
              icon={
                <Show when={state()?.loading} fallback={<Icon name="outline-rotate-clockwise" />}>
                  <Loader />
                </Show>
              }
            />
          </Tooltip>
        </div>
        <Popover
          open={store.editing && listed()}
          anchorRef={() => anchor}
          placement="bottom-start"
          gutter={4}
          // The list overhangs the field by its 8px padding, so suggestion icons and text line up with the field's.
          shift={-8}
          modal={false}
        >
          <form
            ref={anchor}
            dir="ltr"
            data-component="browser-address"
            data-editing={store.editing ? "" : undefined}
            data-site={site() ? "" : undefined}
            data-address={store.editing && !store.typed && field() ? "" : undefined}
            onPointerDown={(event) => {
              // The whole field focuses the input, as the site button and page actions handle their own clicks.
              if (event.target === event.currentTarget) {
                event.preventDefault()
                input?.focus()
              }
            }}
            onSubmit={(event) => {
              event.preventDefault()
              const picked = chosen()
              const text = field().trim()

              if (picked) return go(picked.url)

              if (text || failed()) return go(resolveAddress(text))
              input?.blur()
            }}
          >
            {/* Editing shows the icon of the page Enter would open: the page's own, or the chosen suggestion's. */}
            <Show
              when={site()}
              fallback={
                <PageIcon
                  icon={store.editing && field() ? (store.typed ? chosen()?.icon : page()?.icon) : undefined}
                  class="text-v2-icon-icon-muted"
                />
              }
            >
              {/* Site information describes one page: another tab or URL closes it, and opening it reads anew. */}
              <Show when={`${props.session.key}\n${state()?.id}\n${address()}`} keyed>
                <SiteInformation
                  url={address()}
                  server={props.session.server.local ? undefined : props.session.server.name}
                  site={() => {
                    const tab = state()

                    return tab ? props.model.site(props.session, tab.id) : undefined
                  }}
                  clear={() => {
                    const tab = state()

                    return tab ? props.model.clearSite(props.session, tab.id) : undefined
                  }}
                />
              </Show>
            </Show>
            <div data-slot="browser-address-text">
              <input
                ref={input}
                data-slot="browser-address-input"
                role="combobox"
                aria-autocomplete="list"
                aria-expanded={store.editing && listed()}
                aria-controls={listed() ? "browser-suggestions" : undefined}
                aria-activedescendant={chosen() ? `browser-suggestion-${store.active}` : undefined}
                spellcheck={false}
                autocomplete="off"
                value={field()}
                disabled={!state()}
                placeholder={extension.t("address.search")}
                aria-label={extension.t("address.label")}
                onFocus={(event) => {
                  setStore({ editing: true, address: field(), typed: false, active: -1, dismissed: false })
                  event.currentTarget.select()
                }}
                // Leaving the field without submitting cancels the edit; a submit already ended it. Focus that leaves
                // for the page or another window keeps the field as the document's focus, so the window's return would
                // focus it again and start an edit under the returning click, such as one on the site button.
                onBlur={(event) => {
                  if (store.editing) setStore({ editing: false, typed: false, active: -1, kept: undefined })

                  if (!document.hasFocus()) event.currentTarget.blur()
                }}
                onInput={(event) => {
                  const value = event.currentTarget.value
                  const first = suggest(props.model.visits(), value, 1)[0]

                  // Typing completes the first suggestion, as a search would; deleting never does.
                  const complete =
                    !!first && !event.inputType.startsWith("delete") && (completes(first, value) || searches(value))

                  setStore({ address: value, typed: true, dismissed: false, active: complete ? 0 : -1 })
                }}
                onKeyDown={(event) => {
                  // Keys during IME composition pick and cancel candidates, not suggestions. Safari can report the
                  // composition-confirming keydown with isComposing false but keyCode 229.
                  if (event.isComposing || event.keyCode === 229) return

                  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
                    if (!suggestions().length) return
                    event.preventDefault()
                    step(event.key === "ArrowDown" ? 1 : -1)

                    return
                  }

                  if (event.key !== "Escape") return
                  event.preventDefault()

                  if (listed()) return setStore({ dismissed: true, active: -1 })
                  event.currentTarget.blur()
                }}
              />
              {/* At rest, draw the whole URL over the input's hidden text with its host emphasized. While editing, the
                  input shows its own text so selection and the caret need no mirror. */}
              <Show when={!store.editing && field()}>
                <div aria-hidden="true" data-slot="browser-address-display">
                  <span data-slot="browser-address-url" data-host={parts().host ? "" : undefined}>
                    <span data-slot="browser-address-muted">{parts().scheme}</span>
                    <span data-slot="browser-address-host">{parts().host}</span>
                    {parts().rest}
                  </span>
                </div>
              </Show>
              {/* The suggestion Enter opens, after the typed text. Long text scrolls the input, which a mirror cannot
                  follow, so only a short query shows it. */}
              <Show when={store.editing && store.address.length <= 48 && chosen()}>
                {(visit) => (
                  <div aria-hidden="true" data-slot="browser-address-hint">
                    <span class="invisible shrink-0">{store.address}</span>
                    <span class="ms-1.5 min-w-0 truncate">{`- ${bare(visit().url)}`}</span>
                  </div>
                )}
              </Show>
            </div>
            {/* Any zoom but 100% stays in sight, as the system browser shows it; a click resets it. */}
            <Show when={zoomed()}>
              <Tooltip placement="top" value={extension.t("zoom.reset")}>
                <button
                  type="button"
                  data-slot="browser-address-zoom"
                  onPointerDown={(event) => event.preventDefault()}
                  onClick={() => zoomPage("reset")}
                >
                  {extension.t("zoom.percent", { percent: Math.round((page()?.zoom ?? 1) * 100) })}
                </button>
              </Tooltip>
            </Show>
            <Show when={address()}>
              <div data-slot="browser-address-actions">
                <Tooltip placement="top" value={extension.t("page.add")}>
                  <IconButton
                    type="button"
                    variant="ghost-muted"
                    size="small"
                    aria-label={extension.t("page.add")}
                    disabled={suspended() || failed()}
                    onPointerDown={(event) => event.preventDefault()}
                    onClick={openNote}
                    icon={<Icon name="outline-globe-plus" />}
                  />
                </Tooltip>
                <Tooltip placement="top" value={extension.t(reachable() ? "external.open" : "external.unavailable")}>
                  <IconButton
                    type="button"
                    variant="ghost-muted"
                    size="small"
                    aria-label={extension.t("external.open")}
                    disabled={!reachable()}
                    onPointerDown={(event) => event.preventDefault()}
                    onClick={() => system.openExternal(address())}
                    icon={<Icon name="outline-arrow-up-right" />}
                  />
                </Tooltip>
              </div>
            </Show>
          </form>
          <Popover.Portal>
            <Popover.Content
              data-component="browser-suggestions"
              onOpenAutoFocus={(event) => event.preventDefault()}
              onCloseAutoFocus={(event) => event.preventDefault()}
            >
              <div id="browser-suggestions" role="listbox" aria-label={extension.t("address.suggestions")}>
                <For each={suggestions()}>
                  {(visit, index) => (
                    <PageRow
                      visit={visit}
                      query={store.address}
                      option={{ id: `browser-suggestion-${index()}`, selected: index() === store.active }}
                      onClick={() => go(visit.url)}
                    />
                  )}
                </For>
              </div>
            </Popover.Content>
          </Popover.Portal>
        </Popover>
        <div class="flex shrink-0 items-center gap-1">
          <Tooltip
            placement="top"
            value={
              <div class="flex flex-col gap-1">
                {tip(extension.t("inspect"), keybinds.keybind("browser.inspect"))}
                {/* The page claims Chromium's picker chord itself; the app leaves it to the terminal. */}
                {tip(extension.t("inspect.pageShortcut"), keybinds.keys("mod+shift+c"))}
              </div>
            }
          >
            {/* The ghost variant sets the button color, so the active accent needs precedence over it. */}
            <IconButton
              variant="ghost-muted"
              size="large"
              data-action="browser-inspect"
              disabled={!inspectable()}
              state={picking() ? "pressed" : undefined}
              classList={{ "!text-v2-icon-icon-accent": picking() || commenting() }}
              aria-pressed={picking()}
              aria-label={extension.t("inspect")}
              onClick={toggleInspect}
              icon={<Icon name="outline-browser-annotate" />}
            />
          </Tooltip>
          <Menu gutter={4} modal={false} placement="bottom-end">
            <Tooltip placement="top" value={extension.t("options")}>
              <Menu.Trigger
                as={IconButton}
                variant="ghost-muted"
                size="large"
                disabled={!state()}
                icon={<Icon name="outline-dots" />}
                aria-label={extension.t("options")}
              />
            </Tooltip>
            <Menu.Portal>
              <Menu.Content class="min-w-56">
                {/* Zooming closes the menu: the page stays a still while the menu covers it, so a zoom would show
                    only once it closed. The address field shows any zoom but 100% afterwards. */}
                <Menu.Group>
                  <Menu.Item
                    disabled={!address()}
                    onSelect={() => zoomPage("in")}
                    shortcut={<Keybind keys={[...keybinds.keys("mod+plus")]} variant="neutral" />}
                  >
                    {extension.t("zoom.in")}
                  </Menu.Item>
                  <Menu.Item
                    disabled={!address()}
                    onSelect={() => zoomPage("out")}
                    shortcut={<Keybind keys={[...keybinds.keys("mod+-")]} variant="neutral" />}
                  >
                    {extension.t("zoom.out")}
                  </Menu.Item>
                  <Menu.Item
                    disabled={!zoomed()}
                    onSelect={() => zoomPage("reset")}
                    badge={extension.t("zoom.percent", { percent: Math.round((page()?.zoom ?? 1) * 100) })}
                  >
                    {extension.t("zoom.reset")}
                  </Menu.Item>
                </Menu.Group>
                <Menu.Separator />
                <Menu.Item disabled={!address()} onSelect={copyLink}>
                  {extension.t("link.copy")}
                </Menu.Item>
                <Menu.Item disabled={!reachable()} onSelect={() => system.openExternal(address())}>
                  {extension.t("external.open")}
                </Menu.Item>
                <Menu.Separator />
                <Menu.Item disabled={props.model.visits().length === 0} onSelect={() => props.model.clearHistory()}>
                  {extension.t("history.clear")}
                </Menu.Item>
              </Menu.Content>
            </Menu.Portal>
          </Menu>
        </div>
      </div>
      <Show when={error() && !failed()}>
        <div
          class="shrink-0 px-3 py-1.5 text-12-regular text-v2-state-fg-danger border-b border-v2-border-border-muted"
          role="alert"
          aria-live="assertive"
        >
          {error()}
        </div>
      </Show>
      <embeds.View
        id={embed()}
        visible={shown()}
        frozen={commenting() || noting()}
        radius={10}
        class="relative min-h-0 flex-1 bg-v2-background-bg-base flex items-center justify-center"
      >
        <div ref={box} aria-hidden="true" class="pointer-events-none absolute inset-0" />
        <Show when={empty() && !failed() && !suspended()}>
          {/* As designed: the heading 80px from the top, the recent list centered above a 160px bottom inset. The
              minimum height keeps a full list clear of the heading in a short pane, which then scrolls. */}
          <div dir="auto" class="size-full overflow-y-auto">
            <div class="relative flex min-h-[max(100%,732px)] items-center justify-center px-6 pb-40">
              <div class="absolute inset-x-6 top-20 mx-auto flex max-w-[360px] flex-col items-center gap-4 text-center">
                <Icon name="outline-globe" size="large" class="text-v2-icon-icon-muted" />
                <div class="flex flex-col gap-2">
                  <div class="text-[13px] font-[530] leading-[var(--line-height-compact)] text-v2-text-text-base">
                    {extension.t("home.title")}
                  </div>
                  <div class="text-[13px] font-[440] leading-[var(--line-height-compact)] text-v2-text-text-muted">
                    {extension.t("home.description")}
                  </div>
                </div>
              </div>
              {/* One visit is enough to list; the list stops at a handful. */}
              <Show when={recent().length > 0}>
                <div class="flex w-full max-w-[685px] flex-col gap-4">
                  <div class="px-2 text-[13px] font-[440] leading-[var(--line-height-compact)] text-v2-text-text-muted">
                    {extension.t("home.recent")}
                  </div>
                  <div class="flex flex-col gap-2">
                    <For each={recent()}>{(visit) => <PageRow visit={visit} onClick={() => go(visit.url)} />}</For>
                  </div>
                </div>
              </Show>
            </div>
          </div>
        </Show>
        <Show when={failed() && !suspended()}>
          {/* Add the 40px toolbar to the file empty state's 160px bottom padding to align their centers. */}
          <div
            dir="auto"
            class="flex size-full flex-col items-center justify-center gap-2 p-6 pb-[200px] text-center text-text-weak"
          >
            <Icon name="globe" size="large" class="mb-2 shrink-0" />
            <div class="text-[13px] font-medium leading-[var(--line-height-compact)] text-text-strong">
              {extension.t("failed.title")}
            </div>
            <div class="text-13-regular leading-[var(--line-height-base)]">{extension.t("failed.description")}</div>
          </div>
        </Show>
        <Show when={suspended()}>
          <p class="px-6 text-center text-13-regular text-v2-text-text-subtle" role="status">
            {extension.t("suspended")}
          </p>
        </Show>
        <Show when={commenting() && store.comment}>
          {(current) => (
            <div
              data-component="browser-comment"
              class="absolute inset-0 z-10"
              onPointerDown={(event) => {
                // A click beside the editor dismisses it unless it would discard a draft.
                if (event.target === event.currentTarget && !current().draft.trim()) closeComment()
              }}
            >
              <Show when={spotlight()}>
                {(rect) => (
                  <div
                    data-slot="browser-comment-spotlight"
                    class="pointer-events-none absolute rounded-[2px]"
                    style={{
                      left: `${rect().x}px`,
                      top: `${rect().y}px`,
                      width: `${rect().width}px`,
                      height: `${rect().height}px`,
                    }}
                  />
                )}
              </Show>
              <Show when={placement()}>
                {(position) => (
                  <div
                    ref={(element) =>
                      createResizeObserver(element, (rect) => setStore("editorHeight", Math.ceil(rect.height)))
                    }
                    data-slot="browser-comment-editor"
                    data-prevent-autofocus
                    class="absolute overflow-y-auto rounded-[6px] shadow-[var(--v2-elevation-raised)]"
                    style={{
                      left: `${position().left}px`,
                      top: `${position().top}px`,
                      width: `${position().width}px`,
                      "max-height": `${position().maxHeight}px`,
                    }}
                  >
                    <LineCommentEditor
                      value={current().draft}
                      onInput={(value) => setStore("comment", "draft", value)}
                      onCancel={closeComment}
                      onSubmit={submitComment}
                      mention={{
                        items: (query) => props.screen.file.search(query, { kind: "any" }),
                      }}
                      selection={
                        <span class="flex min-w-0 items-center gap-1" dir="ltr">
                          <Icon name="select-element" size="small" class="shrink-0" />
                          <span class="min-w-0 truncate leading-[var(--line-height-tight)]">
                            {current().element.label}
                          </span>
                        </span>
                      }
                    />
                  </div>
                )}
              </Show>
            </div>
          )}
        </Show>
        <Show when={noting() && store.note}>
          {(current) => (
            <div
              data-component="browser-comment"
              class="absolute inset-0 z-10"
              onPointerDown={(event) => {
                if (event.target === event.currentTarget && !current().draft.trim()) closeNote()
              }}
            >
              {/* Under the page actions at the address field's end, which opened it. */}
              <div
                data-slot="browser-comment-editor"
                data-prevent-autofocus
                class="absolute end-2 top-2 overflow-y-auto rounded-[6px] shadow-[var(--v2-elevation-raised)]"
                style={{
                  width: `${Math.max(0, Math.min(400, store.size.width - 16))}px`,
                  "max-height": `${Math.max(0, store.size.height - 16)}px`,
                }}
              >
                <LineCommentEditor
                  value={current().draft}
                  onInput={(value) => setStore("note", "draft", value)}
                  onCancel={closeNote}
                  onSubmit={submitNote}
                  placeholder={extension.t("page.placeholder")}
                  mention={{
                    items: (query) => props.screen.file.search(query, { kind: "any" }),
                  }}
                  selection={
                    <span class="flex min-w-0 items-center gap-1" dir="ltr">
                      <Icon name="outline-globe" size="small" class="shrink-0" />
                      <span class="min-w-0 truncate leading-[var(--line-height-tight)]">
                        {current().title || addressParts(current().url).host || current().url}
                      </span>
                    </span>
                  }
                />
              </div>
            </div>
          )}
        </Show>
      </embeds.View>
      <p class="sr-only" role="status" aria-live="polite">
        {picking() ? extension.t("inspect.active") : ""}
      </p>
    </aside>
  )
}

/** A page in the suggestions or the new tab page: its icon, title and address, with the query's matches drawn. */
function PageRow(props: {
  visit: Visit
  query?: string
  /** Set for a suggestion: an option of the address field's list, which keeps keyboard focus in the field. */
  option?: { id: string; selected: boolean }
  onClick: () => void
}) {
  const body = () => (
    <>
      <PageIcon icon={props.visit.icon} class="text-v2-icon-icon-muted" />
      <span data-slot="browser-page-row-text">
        <Show when={props.visit.title}>
          <span data-slot="browser-page-row-title">
            <Marked text={props.visit.title} query={props.query ?? ""} />
          </span>
          <span>-</span>
        </Show>
        <span data-slot="browser-page-row-url">
          <Marked text={bare(props.visit.url)} query={props.query ?? ""} />
        </span>
      </span>
    </>
  )

  return (
    <Show
      when={props.option}
      fallback={
        <button type="button" data-component="browser-page-row" dir="ltr" onClick={() => props.onClick()}>
          {body()}
        </button>
      }
    >
      {(option) => (
        <div
          id={option().id}
          role="option"
          aria-selected={option().selected}
          data-component="browser-page-row"
          dir="ltr"
          // The address field keeps focus, so a click does not end editing before it opens the page.
          onPointerDown={(event) => event.preventDefault()}
          onClick={() => props.onClick()}
        >
          {body()}
        </div>
      )}
    </Show>
  )
}

function Marked(props: { text: string; query: string }) {
  return (
    <For each={highlight(props.text, props.query)}>
      {(part) => (
        <Show when={part.match} fallback={part.text}>
          <mark>{part.text}</mark>
        </Show>
      )}
    </For>
  )
}

const connections = {
  secure: { icon: "lock", title: "site.secure", description: undefined },
  insecure: { icon: "outline-hexagonal-warning", title: "site.insecure", description: "site.insecure.description" },
  local: { icon: "monitor", title: "site.local", description: "site.local.description" },
  file: { icon: "folder", title: "site.file", description: "site.file.description" },
} as const

/**
 * What the page can do and what can reach it, under the site button at the address field's start: its connection,
 * its stored data, the permissions it never gets, the agent's access, and the network it loads through.
 */
function SiteInformation(props: {
  url: string
  server: string | undefined
  /** The page's cookie count; undefined while the pane cannot answer. */
  site: () => Promise<{ cookies: number }> | undefined
  clear: () => Promise<void> | undefined
}) {
  const extension = useExtension()

  // `load` counts openings and clears, so a count for an earlier one never replaces a later one.
  const [state, setState] = createStore<{ open: boolean; cookies?: number; clearing: boolean; load: number }>({
    open: false,
    clearing: false,
    load: 0,
  })

  const kind = () => {
    const value = connection(props.url)

    return value ? connections[value] : undefined
  }

  // Only web pages have cookies and ask for permissions; a workspace file has neither.
  const web = () => {
    const value = connection(props.url)

    return !!value && value !== "file"
  }

  const load = () => {
    const run = state.load + 1
    setState({ load: run, cookies: undefined })
    void props.site()?.then(
      (value) => {
        if (state.load === run) setState("cookies", value.cookies)
      },
      () => undefined,
    )
  }

  const clear = () => {
    setState("clearing", true)
    void (props.clear() ?? Promise.reject(new Error("browser.pane.unavailable")))
      .catch(() => showToast({ title: extension.t("common.requestFailed") }))
      .finally(() => {
        setState("clearing", false)
        load()
      })
  }

  return (
    <Popover
      open={state.open}
      placement="bottom-start"
      gutter={8}
      modal={false}
      onOpenChange={(open) => {
        setState("open", open)

        if (open) load()
      }}
    >
      <Tooltip placement="top" value={extension.t("site.info")}>
        <Popover.Trigger
          as={IconButton}
          type="button"
          variant="ghost-muted"
          size="small"
          aria-label={extension.t("site.info")}
          icon={<Icon name="outline-sliders" />}
        />
      </Tooltip>
      <Popover.Portal>
        <Popover.Content
          data-component="browser-site"
          // The panel takes focus itself rather than its close button, so a pointer opening shows no focus ring there.
          onOpenAutoFocus={(event: Event) => {
            event.preventDefault()

            if (event.currentTarget instanceof HTMLElement) event.currentTarget.focus()
          }}
        >
          <div class="flex items-center justify-between gap-2">
            <Popover.Title data-slot="browser-site-host" dir="ltr">
              {addressParts(props.url).host || props.url}
            </Popover.Title>
            {/* A plain button: Kobalte's close button carries the open popover's data-expanded, which icon buttons
                draw as pressed. */}
            <IconButton
              variant="ghost-muted"
              size="small"
              aria-label={extension.t("common.close")}
              icon={<Icon name="outline-xmark" />}
              onClick={() => setState("open", false)}
            />
          </div>
          <Show when={kind()}>
            {(value) => (
              <SiteRow
                icon={value().icon}
                title={extension.t(value().title)}
                detail={value().description ? extension.t(value().description ?? "") : undefined}
              />
            )}
          </Show>
          <Show when={web()}>
            <SiteRow
              icon="outline-cookie"
              title={extension.t("site.cookies")}
              detail={state.cookies === undefined ? undefined : extension.plural("site.cookies.count", state.cookies)}
            >
              <Button
                size="small"
                variant="neutral"
                disabled={state.clearing || state.cookies === undefined}
                onClick={clear}
              >
                {extension.t("site.cookies.clear")}
              </Button>
            </SiteRow>
            <SiteRow
              icon="outline-eye-slash"
              title={extension.t("site.permissions")}
              detail={extension.t("site.permissions.description")}
            />
          </Show>
          <SiteRow
            icon="select-element"
            title={extension.t("site.agent")}
            detail={extension.t("site.agent.description")}
          />
          <Show when={props.server}>
            {(server) => <SiteRow icon="server" title={extension.t("site.network", { server: server() })} />}
          </Show>
        </Popover.Content>
      </Popover.Portal>
    </Popover>
  )
}

function SiteRow(props: { icon: IconName; title: string; detail?: string; children?: JSX.Element }) {
  return (
    <div data-slot="browser-site-row">
      <Icon name={props.icon} class="shrink-0" />
      <div class="flex min-w-0 flex-1 flex-col gap-0.5">
        <span class="text-v2-text-text-base">{props.title}</span>
        <Show when={props.detail}>{(detail) => <span data-slot="browser-site-detail">{detail()}</span>}</Show>
      </div>
      {props.children}
    </div>
  )
}

// URL policy shared by the pane and page. Electron-free so it stays unit-testable under Bun.

export function destinationOrigin(input: string) {
  if (!URL.canParse(input)) return
  const url = new URL(input)

  return /^https?:$/.test(url.protocol) && !url.username && !url.password ? url.origin : undefined
}

/** A file URL for this machine: no host, so UNC shares and remote hosts are rejected. */
export function localFileURL(input: string) {
  if (!URL.canParse(input)) return
  const url = new URL(input)

  return url.protocol === "file:" && !url.hostname ? url.href : undefined
}

/** Case-insensitive on Windows, where drive letters and paths compare that way. */
function canonicalPath(input: string) {
  const value = decodeURIComponent(input)
    .replaceAll("\\", "/")
    .replace(/^\/([A-Za-z]:\/)/, "$1")

  return process.platform === "win32" ? value.toLowerCase() : value
}

/**
 * Whether a file URL points inside one of the allowed directories. The agent already has read
 * access to the session's workspace, so files there may be shown; anything else stays behind the
 * server's file permissions.
 */
export function fileURLWithin(input: string, roots: ReadonlyArray<string>) {
  const href = localFileURL(input)

  if (!href || roots.length === 0) return false
  const path = canonicalPath(new URL(href).pathname)

  return roots.some((root) => {
    const prefix = canonicalPath(root).replace(/\/+$/, "")

    return path === prefix || path.startsWith(`${prefix}/`)
  })
}

export type Policy = { readonly fileRoots?: ReadonlyArray<string> }

export function allowedDestination(input: string, policy?: Policy) {
  return !!destinationOrigin(input) || fileURLWithin(input, policy?.fileRoots ?? [])
}

export function normalizeURL(input: string, policy?: Policy) {
  const url = withScheme(input)
  const reason = refusal(url, policy)

  if (reason === "browser.address.credentials")
    throw new Error("URLs with a user name or password are not supported. Remove them from the URL.")

  if (reason)
    throw new Error(
      policy?.fileRoots?.length
        ? "Only HTTP, HTTPS, about:blank, and file URLs inside the workspace are supported."
        : "Only HTTP, HTTPS, and about:blank URLs are supported.",
    )

  return url
}

/**
 * Why the pane does not open an address, as the code the window explains it with; undefined when it opens.
 * - `browser.address.credentials`: a web page address with a user name or password.
 * - `browser.address.workspace`: anything but a web page or a file in the workspace.
 * - `browser.address.web`: anything but a web page, where no files open.
 */
export function refusal(input: string, policy?: Policy) {
  const url = withScheme(input)

  if (url === "about:blank" || allowedDestination(url, policy)) return

  // A web page is refused only for its credentials.
  if (URL.canParse(url) && /^https?:$/.test(new URL(url).protocol)) return "browser.address.credentials"

  return policy?.fileRoots?.length ? "browser.address.workspace" : "browser.address.web"
}

// The URL an address opens: a blank page for none, else the address with a scheme, `http` for this machine's names.
function withScheme(input: string) {
  const value = input.trim()

  if (!value || /^about:blank$/i.test(value)) return "about:blank"

  if (/^[a-z][a-z\d+.-]*:\/\//i.test(value)) return value
  const local = /^(?:(?:[a-z\d-]+\.)*localhost|127(?:\.\d{1,3}){3}|\[::1\])(?::\d+)?(?:[/?#]|$)/i.test(value)

  return `${local ? "http" : "https"}://${value}`
}

import type { WebContents } from "electron"
import { Browser } from "@opencode/plugin-browser/rpc"
import { gzipSync, gunzipSync } from "node:zlib"
import { Schema } from "effect"
import type { Cdp } from "./cdp"
import type { BrowserFiles } from "./files"
import { analyzeCpu, analyzeTrace, parseHeap } from "./analysis"

export type Recording = {
  owner: WebContents
  pid: number
  started: number
  timer?: ReturnType<typeof setTimeout>
  finish: () => Promise<{ id: Browser.FileID; durationMs: number; incomplete: boolean }>
}

/** Only one trace records across every tab of the app; `shared` holds it. */
export function createProfiling(
  contents: WebContents,
  cdp: Cdp,
  files: BrowserFiles,
  source: () => readonly string[],
  shared: { recording?: Recording },
) {
  let trace: Promise<{ id: Browser.FileID; durationMs: number; incomplete: boolean }> | undefined
  let traceResources = new Set<string>()
  let traceID = ""

  let cpu:
    | {
        started: number
        id: string
        resources: Set<string>
        timer?: ReturnType<typeof setTimeout>
        result?: Promise<{ id: Browser.FileID; durationMs: number }>
      }
    | undefined

  let takingHeap = false
  cdp.on("Page.frameNavigated", ({ frame }) => {
    if (shared.recording?.owner === contents) traceResources.add(frame.url)

    if (cpu && !cpu.result) cpu.resources.add(frame.url)
  })

  const json = async (id: Browser.FileID) => {
    const file = await files.transfer(id)

    try {
      const data = Buffer.from(file.data)

      return Schema.decodeUnknownSync(Schema.fromJsonString(Schema.Unknown))(
        (file.name.endsWith(".gz") ? gunzipSync(data, { maxOutputLength: 128 * 1024 * 1024 }) : data).toString("utf8"),
      )
    } catch (error) {
      throw new Error(
        "Selected file cannot be decoded as a JSON capture, or expands beyond the 128 MiB analysis limit. Call browser.files.list({tabID}) and choose the fileID from the matching trace, CPU, or heap capture, not a screenshot/download. Do not retry the same invalid file.",
        { cause: error },
      )
    }
  }

  const stopCpu = () => {
    if (!cpu)
      return Promise.reject(
        new Error(
          "No CPU profile has been started in this tab. Call browser.cpu.start({tabID}), perform the interaction to inspect, then browser.cpu.stop({tabID}).",
        ),
      )

    if (cpu.result) return cpu.result
    const resources = cpu.resources
    clearTimeout(cpu.timer)
    cpu.result = cdp.send("Profiler.stop").then(async ({ profile }) => ({
      id: await files.save("profile.cpuprofile", "application/json", Buffer.from(JSON.stringify(profile)), [
        ...resources,
      ]),
      durationMs: (profile.endTime - profile.startTime) / 1000,
    }))

    return cpu.result
  }

  return {
    target(type: "trace" | "cpu"): Browser.Target {
      return {
        resources: (type === "trace" ? [...traceResources] : [...(cpu?.resources ?? [])]).sort(),
        key: type === "trace" ? traceID : (cpu?.id ?? ""),
      }
    },
    async startTrace(durationMs = 10_000) {
      if (shared.recording)
        throw new Error(
          shared.recording.owner === contents
            ? "A performance trace is already active in this tab. Use browser.trace.stop({tabID}) to finish it before starting another."
            : "Another tab owns the active performance trace. Wait for its owner to finish; do not stop or replace another tab's recording.",
        )
      const complete = Promise.withResolvers<{ stream?: string; dataLossOccurred: boolean }>()
      const off = cdp.on("Tracing.tracingComplete", (event) => complete.resolve(event))

      const owner = {
        owner: contents,
        pid: contents.getOSProcessId(),
        started: performance.now(),
        timer: undefined as ReturnType<typeof setTimeout> | undefined,
        finish: () => {
          if (trace) return trace
          trace = (async () => {
            clearTimeout(owner.timer)
            const durationMs = performance.now() - owner.started
            const deadline = Promise.withResolvers<never>()

            const timeout = setTimeout(
              () =>
                deadline.reject(
                  new Error(
                    "Chromium did not finish flushing the trace within 10 seconds. No complete export is confirmed. Check browser.files.list({tabID}); do not start another recording until the current trace has finished or the user resolves the failure.",
                  ),
                ),
              10_000,
            )

            try {
              const result = await Promise.race([
                cdp.send("Tracing.end").then(() => complete.promise),
                deadline.promise,
              ])

              if (!result.stream)
                throw new Error(
                  "Chromium stopped tracing without returning a trace stream. No export is available. Check desktop/plugin compatibility and report the failure; repeating trace.stop cannot recover a missing stream.",
                )
              const chunks: Buffer[] = []
              let bytes = 0

              try {
                while (true) {
                  const part = await cdp.send("IO.read", { handle: result.stream, size: 256 * 1024 })
                  const buffer = Buffer.from(part.data, part.base64Encoded ? "base64" : "utf8")
                  bytes += buffer.byteLength

                  if (bytes > 64 * 1024 * 1024)
                    throw new Error(
                      "Trace exceeded its 64 MiB desktop capture limit. Record a shorter interaction with a smaller durationMs in browser.trace.start; do not repeat the same recording unchanged.",
                    )
                  chunks.push(buffer)

                  if (part.eof) break
                }
              } finally {
                await cdp.send("IO.close", { handle: result.stream })
              }

              const raw = Schema.decodeUnknownSync(
                Schema.fromJsonString(
                  Schema.Struct({ traceEvents: Schema.Array(Schema.Record(Schema.String, Schema.Json)) }),
                ),
              )(Buffer.concat(chunks).toString("utf8"))

              // A CDP trace is browser-wide. Export only this renderer process, never
              // the application renderer or another session's process metadata.
              const traceEvents = raw.traceEvents.filter((event) => event.pid === owner.pid)

              const id = await files.save(
                "trace.json.gz",
                "application/gzip",
                gzipSync(
                  JSON.stringify({
                    traceEvents,
                    metadata: { source: "opencode", scope: "renderer-process", processId: owner.pid },
                  }),
                ),
                [...traceResources],
              )

              return {
                id,
                durationMs,
                incomplete:
                  result.dataLossOccurred || contents.isDestroyed() || contents.getOSProcessId() !== owner.pid,
              }
            } finally {
              clearTimeout(timeout)
              off()

              if (shared.recording === owner) shared.recording = undefined
            }
          })()

          return trace
        },
      }

      shared.recording = owner
      trace = undefined
      traceResources = new Set(source())
      traceID = crypto.randomUUID()

      try {
        await cdp.send("Tracing.start", {
          transferMode: "ReturnAsStream",
          traceConfig: {
            recordMode: "recordUntilFull",
            traceBufferSizeInKb: 8192,
            includedCategories: [
              "devtools.timeline",
              "disabled-by-default-devtools.timeline",
              "disabled-by-default-devtools.timeline.stack",
              "v8.execute",
              "blink.user_timing",
              "disabled-by-default-v8.cpu_profiler",
            ],
            excludedCategories: ["*"],
          },
        })
        owner.timer = setTimeout(() => {
          void owner.finish().catch(() => undefined)
        }, durationMs)
      } catch (error) {
        off()

        if (shared.recording === owner) shared.recording = undefined
        throw error
      }
    },
    stopTrace() {
      if (shared.recording?.owner === contents) return shared.recording.finish()

      if (trace) return trace

      return Promise.reject(
        new Error(
          "This tab has no performance trace to stop. Call browser.trace.start({tabID}), perform the interaction to inspect, then browser.trace.stop({tabID}).",
        ),
      )
    },
    async startCpu() {
      if (cpu && !cpu.result)
        throw new Error(
          "A CPU profile is already active in this tab. Use browser.cpu.stop({tabID}) before starting another profile.",
        )
      await cdp.send("Profiler.enable")
      await cdp.send("Profiler.start")
      cpu = { started: Date.now(), id: crypto.randomUUID(), resources: new Set(source()) }
      cpu.timer = setTimeout(() => {
        void stopCpu().catch(() => undefined)
      }, 30_000)
    },
    stopCpu,
    async heap() {
      if (takingHeap)
        throw new Error(
          "A heap snapshot is already being captured in this tab. Await that call before taking another; do not capture the same tab's heaps in parallel.",
        )
      takingHeap = true
      const resources = source()
      const chunks: string[] = []
      let size = 0
      let overflow = false

      const off = cdp.on("HeapProfiler.addHeapSnapshotChunk", ({ chunk }) => {
        size += Buffer.byteLength(chunk)

        if (size > 128 * 1024 * 1024) overflow = true

        if (!overflow) chunks.push(chunk)
      })

      try {
        await cdp.send("HeapProfiler.enable")
        await cdp.send("HeapProfiler.takeHeapSnapshot", { reportProgress: false })
      } finally {
        takingHeap = false
        off()
      }

      if (overflow)
        throw new Error(
          "Heap snapshot exceeded the 128 MiB desktop capture limit. Use a smaller page/test case or ask the user to inspect the heap with desktop developer tools; this tool has no size override.",
        )

      return files.save("heap.heapsnapshot.gz", "application/gzip", gzipSync(chunks.join("")), [
        ...resources,
        ...source(),
      ])
    },
    async analyze(
      action: Extract<
        Browser.Action,
        { type: "trace.analyze" | "cpu.analyze" | "heap.summary" | "heap.query" | "heap.object" | "heap.compare" }
      >,
    ) {
      if (action.type === "heap.compare") {
        const before = parseHeap(await json(action.before)).classes
        const after = parseHeap(await json(action.after)).classes

        return {
          classes: Array.from(new Set([...before.keys(), ...after.keys()]))
            .map((name) => ({
              name,
              countDelta: (after.get(name)?.count ?? 0) - (before.get(name)?.count ?? 0),
              bytesDelta: (after.get(name)?.bytes ?? 0) - (before.get(name)?.bytes ?? 0),
            }))
            .filter((item) => item.countDelta || item.bytesDelta)
            .sort((a, b) => Math.abs(b.bytesDelta) - Math.abs(a.bytesDelta))
            .slice(0, action.limit ?? 100),
        }
      }

      const value = await json(action.fileID)

      if (action.type === "trace.analyze") return analyzeTrace(value, action.limit)

      if (action.type === "cpu.analyze") return analyzeCpu(value, action.limit)
      const heap = parseHeap(value)

      if (action.type === "heap.summary") return heap.summary(action.limit)

      if (action.type === "heap.query") return heap.query(action.name, action.limit)

      return heap.object(action.id, action.limit)
    },
    async dispose() {
      if (shared.recording?.owner === contents) await shared.recording.finish().catch(() => undefined)

      if (cpu && !cpu.result) await stopCpu().catch(() => undefined)
    },
  }
}

import { expect, test } from "bun:test"
import { Schema } from "effect"
import browser from "./index"
import { createRefs } from "./refs"

/** Main storage's row for the store, as its schema encodes it. */
type Disk = { stored?: number }

test("element refs stay unique when the pane's main entry reloads over the same storage", () => {
  const values: Disk = {}
  const declared = browser.stores.refs

  // The declared store as the host opens it on each load: each value kept as its schema encodes it.
  const open = () => {
    const read = () =>
      "stored" in values ? Schema.decodeUnknownSync(declared.schema)(values.stored) : declared.initial

    return {
      get value() {
        return read()
      },
      ready: () => true,
      update: (mutate: (draft: number) => void) => mutate(read()),
      set: (next: number) => void (values.stored = Schema.encodeUnknownSync(declared.schema)(next)),
    }
  }

  const before = createRefs(open())
  const issued = [before(), before()]
  const after = createRefs(open())
  expect(issued).toEqual(["e1", "e2"])
  expect(issued).not.toContain(after())
})

import type { Persisted } from "../sdk/main"

// Reserving in blocks keeps storage writes rare while refs stay short.
const block = 10_000

/**
 * Element refs for every page of the pane. A composer chip or an agent's message can still name a ref from
 * before the pane's main entry reloaded, so a new pane starts past every ref the previous one could hand out.
 */
export function createRefs(reserved: Persisted<number, number>) {
  const state = { next: reserved.value, end: reserved.value }

  return () => {
    if (state.next >= state.end) {
      state.end = state.next + block
      reserved.set(state.end)
    }

    return `e${++state.next}`
  }
}

import { createMemo, createSignal, getOwner, lazy, onCleanup, runWithOwner, Show, Suspense } from "solid-js"
import { Command, createKeyed, LinkHandler, MenuItem, onIdle, Panel, Style, type PanelTab, type Setup } from "../sdk"
import { Browser } from "./contract"
import type definition from "./index"
import type { Model } from "./model"
import { PageIcon } from "./page-icon"
import barStyles from "./bar.css?inline"
import commentStyles from "./comment.css?inline"
import tabStyles from "./tabs.css?inline"

const setup: Setup<typeof definition> = (ctx) => {
  const sessions = ctx.sessions
  const [model, setModel] = createSignal<Model>()
  // Settings > Shortcuts lists the command on every platform; it stays disabled until the pane can open.
  ctx.add(Command, (): Command | undefined => {
    const view = sessions.current()

    if (!view) return undefined
    const value = model()

    return {
      id: "open",
      title: ctx.t("command.open"),
      group: ctx.t("command.category.view"),
      bind: "mod+shift+b",
      enabled: !!value?.available(view),
      run: () => value?.open(view),
    }
  })

  // The native pane is a desktop feature.
  if (ctx.build.platform !== "desktop") return
  // Tab trigger styles render with the strip, before the pane chunk loads.
  ctx.add(Style, tabStyles)
  ctx.add(Style, commentStyles)
  ctx.add(Style, barStyles)
  // Everything here serves a mounted session, so the attachment model and the pane's protocol
  // schemas load when the first session opens instead of at startup.
  const opened = createMemo((seen: boolean) => seen || !!sessions.current(), false)
  createKeyed(opened, () => {
    const owner = getOwner()
    void import("./model").then((module) => {
      if (ctx.signal.aborted) return
      const created = runWithOwner(owner, () => module.createModel(ctx))
      setModel(() => created)
    })
  })

  ctx.provide(Browser, {
    attached: (session) => model()?.attached(session) ?? false,
    canOpen: (session, path) => model()?.canOpen(session, path) ?? false,
    open: (session, url) => model()?.openURL(session, url),
    openFile: (session, path) => model()?.openFile(session, path),
  })

  ctx.add(Command, (): Command | undefined => {
    const pane = model()?.pane()

    if (!pane) return undefined

    return {
      id: "reload",
      title: ctx.t("command.reload"),
      group: ctx.t("command.category.view"),
      bind: "f5",
      editable: true,
      enabled: pane.visible() && !!pane.address(),
      run: pane.reload,
    }
  })

  // The system browser's address shortcut. While the page has focus, the page claims it and main forwards it; here it
  // covers focus elsewhere in the pane. Ctrl+L focuses the composer outside the pane on Windows and Linux.
  ctx.add(Command, (): Command | undefined => {
    const pane = model()?.pane()

    if (!pane) return undefined

    return {
      id: "address",
      title: ctx.t("command.address"),
      group: ctx.t("command.category.view"),
      bind: "mod+l",
      scope: "#browser-panel",
      editable: true,
      enabled: pane.visible(),
      run: pane.focusAddress,
    }
  })

  // Blank pages have no focused native view, so the app must claim close inside the pane too.
  ctx.add(Command, (): Command | undefined => {
    const pane = model()?.pane()

    if (!pane) return undefined

    return {
      id: "close",
      title: ctx.t("command.close"),
      group: ctx.t("command.category.view"),
      bind: "mod+w",
      scope: "#browser-panel",
      hidden: true,
      editable: true,
      enabled: pane.visible(),
      run: pane.close,
    }
  })

  // Ctrl+Shift+C copies in the terminal, so only the focused page claims it, as in Chromium.
  ctx.add(Command, (): Command | undefined => {
    const pane = model()?.pane()

    if (!pane) return undefined

    return {
      id: "inspect",
      title: ctx.t("command.inspect"),
      group: ctx.t("command.category.view"),
      enabled: pane.visible() && pane.inspectable(),
      run: pane.inspect,
    }
  })

  ctx.add(MenuItem, (): MenuItem | undefined => {
    const view = sessions.current()
    const value = model()

    if (!view || !value?.available(view)) return undefined

    return {
      menu: "session.panel",
      id: "open",
      title: ctx.t("tab.title"),
      icon: "globe",
      keybind: "browser.open",
      order: 20,
      run: () => value.open(view),
    }
  })

  // Workspace HTML links reach the pane through the file extension, which resolves the path first.
  // A composer chip for a comment on a picked element.
  ctx.add(LinkHandler, {
    priority: 10,
    match: (link) => link.origin === ctx.id && !!link.session,
    open(link) {
      if (link.session) model()?.reveal(link.session, link.href)
    },
  })

  // Stable tab objects with live labels, so title and URL changes never remount a trigger.
  const tabs = new Map<string, Map<string, PanelTab>>()

  const create = (session: string, id: string): PanelTab => {
    const text = () => {
      const tab = model()?.tab({ key: session }, id)

      return !tab?.url || tab.url === "about:blank" ? ctx.t("tab.new") : tab.title || tab.url
    }

    const icon = () => model()?.page({ key: session }, id)?.icon

    return {
      id,
      get title() {
        return text()
      },
      label: () => (
        <div class="flex items-center gap-1.5">
          <PageIcon icon={icon()} />
          <span class="max-w-40 truncate">{text()}</span>
        </div>
      ),
      // Listed only to hold the restored selection until the desktop's first inventory names the tab.
      get hidden() {
        return !model()?.tab({ key: session }, id)
      },
      group: "browser",
      dom: { tab: `session-side-panel-browser-tab-${id}`, panel: "session-side-panel-browser-tabpanel" },
    }
  }

  const SessionBrowserPane = lazy(() => import("./panel"))
  onCleanup(onIdle(() => void SessionBrowserPane.preload()))
  ctx.add(Panel, {
    id: "main",
    region: "side",
    list(input) {
      // While the model loads, the stored tabs hold the strip and its selection, as before the first inventory.
      const ids = model()?.tabs(input.session, input.open) ?? input.open

      if (ids.length === 0) {
        tabs.delete(input.session.key)

        return []
      }

      const previous = tabs.get(input.session.key)
      const next = new Map(ids.map((id) => [id, previous?.get(id) ?? create(input.session.key, id)]))
      tabs.set(input.session.key, next)

      return [...next.values()]
    },
    // The pane shows nothing until the desktop's first inventory names its tabs.
    render: (props) => (
      <Show when={model()}>
        {(value) => (
          <Show when={!value().pending(props.session)}>
            <Suspense>
              <SessionBrowserPane tab={() => props.tab} session={props.session} screen={props.screen} model={value()} />
            </Suspense>
          </Show>
        )}
      </Show>
    ),
    close: (input) => model()?.closeTab(input.session, input.tab.id),
    focus: (input) => model()?.focusTab(input.session, input.tab.id),
  })
}

export default setup

import { Browser } from "@opencode/plugin-browser/rpc"
import { Schema } from "effect"
import type { MainStoreFrom, Storage } from "../sdk/main"

const Stored = Schema.Struct({
  tabs: Schema.Array(Schema.Struct({ id: Browser.TabID, url: Browser.Tab.fields.url })),
  focusedTabID: Schema.NullOr(Browser.TabID),
})

type Stored = typeof Stored.Type

const empty: Stored = { tabs: [], focusedTabID: null }

/** Tab URLs and focus per `${server}\n${session}`, imported once from the desktop's own `opencode.browser.dat` rows. */
export function createBrowserRestoreStore(storage: Storage) {
  const from = (key: string): MainStoreFrom => ({ state: ["opencode.browser.dat", key] })
  const open = (key: string) => storage.store(`restore:${key}`, { schema: Stored, initial: empty, from: from(key) })

  const stores = new Map<string, ReturnType<typeof open>>()

  const store = (key: string) => {
    const existing = stores.get(key)

    if (existing) return existing
    const created = open(key)
    stores.set(key, created)

    return created
  }

  return {
    load: (key: string) => store(key).value,
    save(key: string, state: Stored) {
      const target = store(key)
      const value = { tabs: state.tabs.map((tab) => ({ id: tab.id, url: tab.url })), focusedTabID: state.focusedTabID }

      if (JSON.stringify(target.value) !== JSON.stringify(value)) target.set(value)
    },
    // Also drops the unimported desktop row, as the pane's own close always did.
    remove(key: string) {
      storage.remove(`restore:${key}`, { from: from(key) })
      stores.delete(key)
    },
  }
}

import { batch, onCleanup } from "solid-js"
import { createStore } from "solid-js/store"
import { showToast } from "@opencode/ui/toast"
import type { MountedSession, SetupContext } from "../sdk"
import type Btw from "./index"

const instructions = [
  "The user is asking a quick side question about the conversation so far.",
  "Answer directly and concisely in markdown from what you already know.",
  "Do not call any tools and do not take any actions.",
].join(" ")

/** One-shot side questions per session, one tab each, stored until the tab closes. */
export function createBtw(ctx: SetupContext<typeof Btw>) {
  const controllers = new Map<string, AbortController>()
  const [requests, setRequests] = createStore<{ pending: string[] }>({ pending: [] })
  const saved = (session: MountedSession) => ctx.stores.chats(session)

  const stop = (id: string) => {
    controllers.get(id)?.abort()
    controllers.delete(id)
    setRequests("pending", (list) => list.filter((item) => item !== id))
  }

  // In-flight questions keep running when the user leaves their session and answer into its store; only a reload,
  // closing the question's tab or disposing the extension abandons one, which leaves it retryable.
  onCleanup(() => Array.from(controllers.keys()).forEach(stop))

  const entry = (session: MountedSession, id: string) => saved(session).value?.chats.find((item) => item.id === id)
  const pending = (id: string) => requests.pending.includes(id)

  // Takes the question rather than reading it back, because a new chat's write may still wait for the store to load.
  const generate = (session: MountedSession, id: string, question: string) => {
    if (pending(id)) return

    const store = saved(session)
    const controller = new AbortController()
    controllers.set(id, controller)
    setRequests("pending", (list) => [...list, id])

    return (
      session.server.client.session
        .generate(
          { sessionID: session.id, prompt: [instructions, question].join("\n\n") },
          { signal: controller.signal },
        )
        .then((result) => {
          if (ctx.signal.aborted || controller.signal.aborted) return
          store.update((draft) => {
            const chat = draft.chats.find((item) => item.id === id)

            if (chat) chat.answer = result.text.trim()
          })
        })
        // A missing answer is the retry state; no transient error flag is stored.
        .catch(() => undefined)
        .finally(() => {
          if (controllers.get(id) === controller) stop(id)
        })
    )
  }

  const ask = (value?: string) => {
    const question = value?.trim()

    if (!question) {
      showToast({ title: ctx.t("question.required") })

      return
    }

    const session = ctx.sessions.current()

    if (!session?.id) return

    const id = crypto.randomUUID()

    // Desktop storage loads asynchronously. A write before load queues and lands in the same batch that marks the
    // store ready, and the panel keeps a tab hidden until then, so the chat and its tab need not wait. The session's
    // store lives while its tab stays open, so leaving the session first still records the chat.
    batch(() => {
      saved(session).update((draft) => {
        draft.chats.push({ id, question })
      })
      ctx.layout.open(`${ctx.id}:${id}`, session, { tab: "select" })
    })
    void generate(session, id, question)
  }

  return {
    ask,
    saved,
    pending,
    question: (session: MountedSession, id: string) => entry(session, id)?.question,
    answer: (session: MountedSession, id: string) => entry(session, id)?.answer,
    error: (session: MountedSession, id: string) => {
      const item = entry(session, id)

      return !!item && item.answer === undefined && !pending(id)
    },
    retry: (session: MountedSession, id: string) => {
      const question = entry(session, id)?.question

      if (question) void generate(session, id, question)
    },
    /** Closing a tab forgets its question and answer. */
    remove: (session: MountedSession, id: string) => {
      stop(id)
      saved(session).update((draft) => {
        draft.chats = draft.chats.filter((item) => item.id !== id)
      })
    },
  }
}

export type BtwModel = ReturnType<typeof createBtw>

import { createMemo, lazy, onCleanup, Suspense } from "solid-js"
import { Icon } from "@opencode/ui/icon"
import { Command, createKeyed, onIdle, Panel, type PanelTab, type Setup } from "../sdk"
import type Btw from "./index"
import { createBtw } from "./model"

const setup: Setup<typeof Btw> = (ctx) => {
  const SessionBtwPanel = lazy(() => import("./panel"))
  onCleanup(onIdle(() => void SessionBtwPanel.preload()))
  const layout = ctx.layout
  const sessions = ctx.sessions
  const btw = createBtw(ctx)
  // Changes when a session mounts or unmounts, not on every switch between sessions.
  const mounted = createMemo(() => !!sessions.current())

  // Tab objects per session, reused so strip updates and session switches do not rebuild a trigger.
  const tabs = new Map<string, Map<string, PanelTab>>()

  // Drops the tab objects of sessions whose shell tab closed.
  createKeyed(
    () => [...sessions.list().map((session) => session.key), sessions.current()?.key].join("\u0000"),
    () => {
      const keep = new Set([...sessions.list().map((session) => session.key), sessions.current()?.key])
      tabs.forEach((_cache, key) => {
        if (!keep.has(key)) tabs.delete(key)
      })
    },
  )

  ctx.add(
    Command,
    (): Command => ({
      id: "ask",
      title: ctx.t("command.title"),
      description: ctx.t("command.description"),
      group: ctx.t("command.category.session"),
      section: "session",
      slash: { name: "btw", arguments: true },
      hidden: true,
      // Offered only while a session is open in a desktop-width window.
      enabled: !layout.narrow() && mounted(),
      run: (input) => btw.ask(input),
    }),
  )

  ctx.add(Panel, {
    id: "main",
    region: "side",
    transient: true,
    // Layouts saved before extensions store the tab as "btw"; as a panel key it leaves like any unlisted transient tab.
    legacy: { btw: "main" },
    // One tab per stored question. Until the session's store loads, its tabs stay listed but hidden so restore keeps
    // them; afterwards a tab without a stored question leaves the strip.
    list: (input) => {
      if (input.open.length === 0) return []

      const saved = btw.saved(input.session)
      const cache = tabs.get(input.session.key) ?? new Map<string, PanelTab>()
      tabs.set(input.session.key, cache)

      return input.open.flatMap((id) => {
        if (saved.ready() && !saved.value?.chats.some((item) => item.id === id)) return []

        const existing = cache.get(id)

        if (existing) return [existing]

        const tab: PanelTab = {
          id,
          get title() {
            return saved.value?.chats.find((item) => item.id === id)?.question ?? ctx.t("tab.title")
          },
          get hidden() {
            return !saved.ready()
          },
          label: (state) => (
            <div class="flex min-w-0 items-center gap-1.5">
              <Icon name="bubble-5" size="small" />
              <span class="truncate">{btw.question(state.session, id) ?? ctx.t("tab.title")}</span>
            </div>
          ),
        }

        cache.set(id, tab)

        return [tab]
      })
    },
    render: (props) => (
      <Suspense>
        <SessionBtwPanel btw={btw} session={props.session} id={props.tab.id} />
      </Suspense>
    ),
    close: (input) => {
      btw.remove(input.session, input.tab.id)
      tabs.get(input.session.key)?.delete(input.tab.id)
    },
  })
}

export default setup

// Type-level check of the built-in compositions, run by `bun typecheck`. Nothing imports this file. Every Ipc a
// renderer entry declares in `provides`, `uses` or `requires` needs a main entry that provides it: an unprovided Ipc in
// `ctx.uses` stays pending forever, and an unprovided `requires` would also hold the window's startup gate. Each
// `@ts-expect-error` fails the typecheck if its line stops being an error.
import { Extension, Ipc, type MissingMain, type IpcsProvided } from "./sdk"
import type { builtins } from "./renderer"
// Both compositions export `builtins`, and this file names the two together.
import type { builtins as mainBuiltins } from "./main"
import type browser from "./browser"

type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false

const equal = <A, B>(value: Equal<A, B>) => value

export const ipcs: IpcsProvided<typeof builtins, typeof mainBuiltins> = true

// The main composition with the browser's definition but not its main entry, which provides the pane.
type Mainless = readonly (Exclude<(typeof mainBuiltins)[number], { readonly id: "browser" }> | typeof browser)[]

// @ts-expect-error no main entry provides browser.pane, which the browser's renderer reads through `provides`
export const mainless: IpcsProvided<typeof builtins, Mainless> = true

equal<IpcsProvided<typeof builtins, Mainless>, MissingMain<"browser.pane">>(true)

const Orphan = Ipc.define({ id: "fixture.orphan", methods: {} })

// A renderer that uses an Ipc nothing in main provides.
const Uses = Extension.define({ id: "fixture", uses: { orphan: Orphan } })

// @ts-expect-error no main entry provides fixture.orphan
export const used: IpcsProvided<readonly [...typeof builtins, typeof Uses], typeof mainBuiltins> = true

// A renderer that requires it, from an extension listed in main without the main entry that would provide it.
const Provider = Extension.define({ id: "fixture.provider", provides: { orphan: Orphan } })

const Requires = Extension.define({ id: "fixture.requires", requires: { orphan: Orphan } })

// @ts-expect-error a renderer `requires` with no main provider would hold the startup gate
export const held: IpcsProvided<
  readonly [...typeof builtins, typeof Provider, typeof Requires],
  readonly [...typeof mainBuiltins, typeof Provider]
> = true

import { createMemo, type Accessor } from "solid-js"
import { createKeyed, type MountedSession } from "../sdk"

const location = (session: MountedSession) => (session.directory ? { directory: session.directory } : undefined)

/** Loads the provider and model catalogs of the routed session's location. */
export function syncCatalog(session: Accessor<MountedSession>) {
  // The same target while another session of the same directory is routed, so a session switch loads nothing.
  const target = createMemo(
    () => {
      const current = session()

      return current.server.connected ? { data: current.server.data, ref: location(current) } : undefined
    },
    undefined,
    { equals: (a, b) => a?.data === b?.data && a?.ref?.directory === b?.ref?.directory },
  )

  // Loads again when the server reconnects or is replaced, and when another session's directory is routed.
  createKeyed(
    target,
    (current) =>
      void (async () => {
        if (!current.ref) await current.data.location.syncInfo()
        const resolved = current.ref ?? current.data.location.default()
        await Promise.all([current.data.location.provider.sync(resolved), current.data.location.model.sync(resolved)])
      })().catch(() => undefined),
  )
}

/** The catalog entries of a message's model, matching the app's provider catalog: both lists must load, and deprecated models are skipped. */
export function catalogModel(session: MountedSession, model: { readonly providerID: string; readonly id: string }) {
  const ref = location(session)
  const providers = session.server.data.location.provider.list(ref)
  const models = session.server.data.location.model.list(ref)

  if (!providers || !models) return
  const provider = providers.findLast((item) => item.id === model.providerID)

  if (!provider) return

  return {
    provider,
    model: models.findLast(
      (item) => item.providerID === model.providerID && item.id === model.id && item.status !== "deprecated",
    ),
  }
}

import type { OpenCodeClient } from "@opencode/client/promise"

export async function fetchSessionExport(input: {
  sessionID: string
  api: Pick<OpenCodeClient, "session" | "message">
}) {
  const [info, first] = await Promise.all([
    input.api.session.get({ sessionID: input.sessionID }),
    input.api.message.list({ sessionID: input.sessionID, limit: 200, order: "asc" }),
  ])

  const pages = [first]

  while (pages.at(-1)?.cursor.next) {
    pages.push(
      await input.api.message.list({
        sessionID: input.sessionID,
        limit: 200,
        cursor: pages.at(-1)!.cursor.next ?? undefined,
      }),
    )
  }

  return {
    info,
    messages: pages.flatMap((page) => page.data),
  }
}

export function sessionExportFilename(session: { id: string; title?: string; slug?: string }) {
  const name = session.title || session.slug || session.id

  const clean = name
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/gi, "-")
    .replace(/^-+|-+$/g, "")

  return `${clean || session.id}.json`
}

export function createSessionContextFormatter(locale: string) {
  // The fields luxon's DATETIME_MED preset passed to Intl; output is identical.
  const dateTime = new Intl.DateTimeFormat(locale, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "numeric",
  })

  return {
    number(value: number | null | undefined) {
      if (value === undefined) return "—"

      if (value === null) return "—"

      return value.toLocaleString(locale)
    },
    percent(value: number | null | undefined) {
      if (value === undefined) return "—"

      if (value === null) return "—"

      return value.toLocaleString(locale) + "%"
    },
    time(value: number | undefined) {
      if (!value) return "—"

      return dateTime.format(value)
    },
  }
}

import { Show, createMemo, type ComponentProps, type JSX } from "solid-js"
import { ProgressCircle } from "@opencode/ui/progress-circle"
