const emptyMessages: SessionMessageInfo[] = []

export default function SessionContextTab(props: { session: MountedSession }) {
  const ctx = useExtension()
  const layout = ctx.layout
  const system = ctx.system
  const i18n = useI18n()
  const data = () => props.session.server.data
  syncCatalog(() => props.session)

  const info = createMemo(() => (props.session.id ? data().session.get(props.session.id) : undefined))

  const messages = createMemo(
    () => {
      const id = props.session.id

      if (!id) return emptyMessages

      return data().session.message.list(id)
    },
    emptyMessages,
    { equals: same },
  )

  const usd = createMemo(
    () =>
      new Intl.NumberFormat(i18n.locale(), {
        style: "currency",
        currency: "USD",
      }),
  )

  // Same step as the TUI and the header button: after the last completed compaction and before an undo boundary.
  const context = createMemo(() => {
    const message = lastAssistantWithUsage(messages(), info()?.revert?.messageID)

    if (!message) return
    const entry = catalogModel(props.session, message.model)

    const total =
      message.tokens.input +
      message.tokens.output +
      message.tokens.reasoning +
      message.tokens.cache.read +
      message.tokens.cache.write

    return {
      message,
      tokens: message.tokens,
      providerLabel: entry?.provider.name ?? message.model.providerID,
      modelLabel: entry?.model?.name ?? message.model.id,
      limit: entry?.model?.limit.context,
      input: message.tokens.input,
      total,
      usage: entry?.model?.limit.context ? Math.round((total / entry.model.limit.context) * 100) : null,
    }
  })

  const formatter = createMemo(() => createSessionContextFormatter(i18n.locale()))

  // A root session's cost includes its subagent sessions, as in the TUI.
  const cost = createMemo(() => usd().format(props.session.id ? data().session.cost(props.session.id) : 0))

  const counts = createMemo(() => {
    const all = messages()
    const user = all.reduce((count, message) => count + (message.type === "user" ? 1 : 0), 0)
    const assistant = all.reduce((count, message) => count + (message.type === "assistant" ? 1 : 0), 0)

    return {
      all: all.length,
      user,
      assistant,
    }
  })

  const systemPrompt = createMemo(() => {
    const system = messages().findLast((message) => message.type === "system")?.text

    if (!system) return
    const trimmed = system.trim()

    if (!trimmed) return

    return trimmed
  })

  const providerLabel = createMemo(() => {
    const c = context()

    if (!c) return "—"

    return c.providerLabel
  })

  const modelLabel = createMemo(() => {
    const c = context()

    if (!c) return "—"

    return c.modelLabel
  })

  const stats = [
    { label: "stats.session", value: () => info()?.title ?? (props.session.id || "—") },
    { label: "stats.messages", value: () => counts().all.toLocaleString(i18n.locale()) },
    { label: "stats.provider", value: providerLabel },
    { label: "stats.model", value: modelLabel },
    { label: "stats.limit", value: () => formatter().number(context()?.limit) },
    { label: "stats.totalTokens", value: () => formatter().number(context()?.total) },
    { label: "stats.usage", value: () => formatter().percent(context()?.usage) },
    { label: "stats.inputTokens", value: () => formatter().number(context()?.input) },
    { label: "stats.outputTokens", value: () => formatter().number(context()?.tokens.output) },
    { label: "stats.reasoningTokens", value: () => formatter().number(context()?.tokens.reasoning) },
    {
      label: "stats.cacheTokens",
      value: () =>
        `${formatter().number(context()?.tokens.cache.read)} / ${formatter().number(context()?.tokens.cache.write)}`,
    },
    { label: "stats.userMessages", value: () => counts().user.toLocaleString(i18n.locale()) },
    { label: "stats.assistantMessages", value: () => counts().assistant.toLocaleString(i18n.locale()) },
    { label: "stats.totalCost", value: cost },
    { label: "stats.sessionCreated", value: () => formatter().time(info()?.time.created) },
    { label: "stats.lastActivity", value: () => formatter().time(context()?.message.time.created) },
  ] satisfies { label: string; value: () => JSX.Element }[]

  const exportSession = async () => {
    const sessionID = props.session.id

    if (!sessionID) return

    try {
      const data = await fetchSessionExport({
        sessionID,
        api: props.session.server.client,
      })

      const filename = sessionExportFilename(data.info)

      if (!(await system.save({ name: filename, content: JSON.stringify(data, null, 2) }))) return
      showToast({
        variant: "success",
        // Solid resolves JSX accessors under the toast's render owner, not this imperative call site.
        icon: () => <Icon name="circle-check" />,
        title: ctx.t("export.success.title"),
        description: ctx.t("export.success.description", { filename }),
      })
    } catch (err) {
      showToast({
        variant: "error",
        title: ctx.t("export.failed.title"),
        description: err instanceof Error ? err.message : ctx.t("export.failed.description"),
      })
    }
  }

  let scroll: HTMLDivElement | undefined
  let frame: number | undefined
  let pending: { x: number; y: number } | undefined

  const restoreScroll = () => {
    const el = scroll

    if (!el) return

    const s = layout.scroll.get(props.session, "context")

    if (!s) return

    if (el.scrollTop !== s.y) el.scrollTop = s.y

    if (el.scrollLeft !== s.x) el.scrollLeft = s.x
  }

  const handleScroll = (event: Event & { currentTarget: HTMLDivElement }) => {
    pending = {
      x: event.currentTarget.scrollLeft,
      y: event.currentTarget.scrollTop,
    }

    if (frame !== undefined) return

    frame = requestAnimationFrame(() => {
      frame = undefined

      const next = pending
      pending = undefined

      if (!next) return

      layout.scroll.set(props.session, "context", next)
    })
  }

  // Restores the stored scroll a frame after the messages change; on mount the viewport ref restores it.
  createKeyed(
    createMemo(on(messages, (list) => list, { defer: true })),
    () => void requestAnimationFrame(restoreScroll),
  )

  onCleanup(() => {
    if (frame === undefined) return
    cancelAnimationFrame(frame)
  })

  return (
    <ScrollView
      class="@container h-full"
      viewportRef={(el) => {
        scroll = el
        restoreScroll()
      }}
      onScroll={handleScroll}
    >
      <div data-slot="session-usage-content" class="px-4 pt-4 pb-6 flex flex-col gap-6 md:px-6 md:pb-10 md:gap-10">
        <div class="grid grid-cols-1 @[32rem]:grid-cols-2 gap-4">
          <For each={stats}>{(stat) => <Stat label={ctx.t(stat.label)} value={stat.value()} />}</For>
        </div>

        <Show when={systemPrompt()}>
          {(prompt) => (
            <div class="flex flex-col gap-2">
              <div class="text-12-regular text-text-weak">{ctx.t("systemPrompt.title")}</div>
              <div class="border border-border-base rounded-md bg-surface-base px-3 py-2">
                <Markdown text={prompt()} class="text-12-regular" />
              </div>
            </div>
          )}
        </Show>

        <div class="flex flex-col gap-2">
          <div class="flex items-center justify-between">
            <div class="text-12-regular text-text-weak">{ctx.t("rawMessages.title")}</div>
            <Button
              size="small"
              variant="ghost"
              class="gap-1.5 px-2 text-text-weak hover:text-text-base"
              onClick={exportSession}
            >
              <Icon name="download" size="small" />
              <span>{ctx.t("export.session")}</span>
            </Button>
          </div>
          <Accordion multiple>
            <For each={messages()}>
              {(message) => <RawMessage message={message} onRendered={restoreScroll} time={formatter().time} />}
            </For>
          </Accordion>
        </div>
      </div>
    </ScrollView>
  )
}

function same<T>(a: readonly T[] | undefined, b: readonly T[] | undefined) {
  if (a === b) return true

  if (!a || !b) return false

  if (a.length !== b.length) return false

  return a.every((x, i) => x === b[i])
}

import { batch, createMemo, createSignal, onCleanup, onMount, Show } from "solid-js"
import { createStore } from "solid-js/store"
import { makeEventListener } from "@solid-primitives/event-listener"
import { Tooltip } from "@opencode/ui/tooltip"
import { createKeyed, useExtension } from "../sdk"
import {
  applyProviderMetricEvent,
  isProviderMetricEvent,
  projectedProviderMetrics,
  type ProviderMetrics,
  type ProviderMetricState,
} from "./metrics"

type Mem = Performance & {
  memory?: {
    usedJSHeapSize: number
    jsHeapSizeLimit: number
  }
}

type Evt = PerformanceEntry & {
  interactionId?: number
  processingStart?: number
}

type Shift = PerformanceEntry & {
  hadRecentInput: boolean
  value: number
}

type Obs = PerformanceObserverInit & {
  durationThreshold?: number
}

type Readings = {
  cls: number | undefined
  delay: number | undefined
  fps: number | undefined
  gap: number | undefined
  focus: boolean
  heap: { limit: number | undefined; used: number | undefined }
  inp: number | undefined
  jank: number | undefined
  long: { block: number | undefined; count: number | undefined; max: number | undefined }
  nav: { dur: number | undefined; pending: boolean }
}

const span = 5000

const ms = (n?: number, d = 0) => {
  if (n === undefined || Number.isNaN(n)) return

  return `${n.toFixed(d)}ms`
}

const time = (n?: number) => {
  if (n === undefined || Number.isNaN(n)) return

  return `${Math.round(n)}`
}

const fixed = (n?: number, digits = 0) => {
  if (n === undefined || Number.isNaN(n)) return

  return n.toFixed(digits)
}

const mb = (n?: number) => {
  if (n === undefined || Number.isNaN(n)) return
  const v = n / 1024 / 1024

  return `${v >= 1024 ? v.toFixed(0) : v.toFixed(1)}MB`
}

const duration = (n?: number) => {
  if (n === undefined || Number.isNaN(n)) return

  if (n < 1_000) return `${Math.round(n)}ms`

  return `${(n / 1_000).toFixed(n < 10_000 ? 1 : 0)}s`
}

const bad = (n: number | undefined, limit: number, low = false) => {
  if (n === undefined || Number.isNaN(n)) return false

  return low ? n < limit : n > limit
}

const session = (path: string) => path.includes("/session")

function Cell(props: {
  bad?: boolean
  dim?: boolean
  inline?: boolean
  label: string
  tip: string
  value: string
  span?: 2 | 3
}) {
  const content = () => (
    <div
      classList={{
        "flex min-w-0 items-center": true,
        "min-h-[20px] w-fit justify-start px-1.5 py-0.5 text-left": !!props.inline,
        "justify-center text-center": !props.inline,
        "min-h-[42px] w-full flex-col rounded-[8px] px-0.5 py-1": !props.inline,
        "col-span-2": props.span === 2 && !props.inline,
        "col-span-3": props.span === 3 && !props.inline,
      }}
    >
      <div
        classList={{
          "flex min-w-0": true,
          "-translate-y-px items-baseline gap-1.5": !!props.inline,
          "flex-col items-center": !props.inline,
        }}
      >
        <div
          dir="ltr"
          classList={{
            "text-[10px] leading-none font-black uppercase tracking-[0.04em] opacity-70": true,
          }}
        >
          {props.label}
        </div>
        <div
          dir="ltr"
          classList={{
            "uppercase font-bold tabular-nums": true,
            "text-[11px] leading-text-tight": !!props.inline,
            "text-[13px] leading-text-compact sm:text-[14px]": !props.inline,
            "text-text-on-critical-base": !!props.bad,
            "opacity-70": !!props.dim,
          }}
        >
          {props.value}
        </div>
      </div>
    </div>
  )

  return (
    <Tooltip appearance={props.inline ? "compact" : "standard"} value={props.tip} placement="top">
      {content()}
    </Tooltip>
  )
}

function ToggleCell(props: {
  active: boolean
  inline?: boolean
  label: string
  onClick: () => void
  tip: string
  value: string
}) {
  const content = () => (
    <button
      type="button"
      aria-label={`${props.label}: ${props.value}`}
      aria-pressed={props.active}
      classList={{
        "flex min-w-0 items-center font-mono uppercase hover:bg-surface-raised-base focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-border-focus": true,
        "min-h-[20px] w-fit justify-start rounded px-1.5 py-0.5 text-left": !!props.inline,
        "min-h-[42px] w-full flex-col justify-center rounded-[8px] px-0.5 py-1 text-center": !props.inline,
        "bg-surface-raised-base text-text-strong": props.active,
      }}
      onClick={props.onClick}
    >
      <span
        classList={{
          flex: true,
          "-translate-y-px items-baseline gap-1.5": !!props.inline,
          "flex-col items-center": !props.inline,
        }}
      >
        <span dir="ltr" class="text-[10px] leading-none font-black tracking-[0.04em] opacity-70">
          {props.label}
        </span>
        <span dir="ltr" class="text-[11px] leading-none font-bold">
          {props.value}
        </span>
      </span>
    </button>
  )

  return (
    <Tooltip appearance={props.inline ? "compact" : "standard"} value={props.tip} placement="top">
      {content()}
    </Tooltip>
  )
}

export default function DebugBar(props: { diagnostics?: boolean; inline?: boolean }) {
  const ctx = useExtension()
  const router = ctx.router
  const locale = ctx.locale
  const desktop = ctx.desktop
  const sessions = ctx.sessions

  const [state, setState] = createStore<Readings>({
    cls: undefined,
    delay: undefined,
    fps: undefined,
    gap: undefined,
    focus: false,
    heap: {
      limit: undefined,
      used: undefined,
    },
    inp: undefined,
    jank: undefined,
    long: {
      block: undefined,
      count: undefined,
      max: undefined,
    },
    nav: {
      dur: undefined,
      pending: false,
    },
  })

  const target = createMemo(
    () => {
      const session = sessions.current()

      if (!session?.id) return

      return { server: session.server, data: session.server.data, id: session.id }
    },
    undefined,
    { equals: (a, b) => a?.data === b?.data && a?.id === b?.id },
  )

  // History comes from the already-loaded message projection; live requests refine it in place.
  const projected = createMemo(() => {
    const current = target()

    if (!current) return

    return projectedProviderMetrics(current.data.session.message.list(current.id))
  })

  // Missed events during an outage are never replayed, so live metrics hold only for the target and the outage count
  // they were measured under: after a disconnect the refreshed projection wins until the next live request.
  const outages = createMemo((count: number = 0) => (target()?.server.connected ? count : count + 1))
  const [live, setLive] = createSignal<{ target: object; outages: number; metrics: ProviderMetrics }>()

  const metrics = () => {
    const current = live()

    return current && current.target === target() && current.outages === outages() ? current.metrics : projected()
  }

  createKeyed(target, (current) => {
    const accumulator: ProviderMetricState = {}

    onCleanup(
      current.data.listen(({ details }) => {
        if (!isProviderMetricEvent(details) || details.data.sessionID !== current.id) return
        applyProviderMetricEvent(accumulator, details)

        if (accumulator.latest) setLive({ target: current, outages: outages(), metrics: accumulator.latest })
      }),
    )
  })

  const na = () => ctx.t("na").toUpperCase()
  const heap = () => (state.heap.limit ? (state.heap.used ?? 0) / state.heap.limit : undefined)

  const heapv = () => {
    const value = heap()

    if (value === undefined) return na()

    return `${Math.round(value * 100)}%`
  }

  const longv = () => (state.long.count === undefined ? na() : `${time(state.long.block) ?? na()}/${state.long.count}`)
  const navv = () => (state.nav.pending ? "…" : (time(state.nav.dur) ?? na()))

  const toggleFocus = async () => {
    if (!desktop) return
    const enabled = !state.focus
    await desktop.forceFocus(enabled)
    setState("focus", enabled)
  }

  onCleanup(() => {
    if (state.focus) void desktop?.forceFocus(false).catch(() => undefined)
  })

  let prev = ""
  let start = 0
  let init = false
  let one = 0
  let two = 0

  // Times navigations to and from a session: from the route starting to change until two frames after it settles.
  createKeyed(
    () => props.diagnostics && { busy: router.routing(), next: router.path() },
    (route) => {
      const next = route.next

      if (!init) {
        init = true
        prev = next

        return
      }

      if (route.busy) {
        if (one !== 0) cancelAnimationFrame(one)

        if (two !== 0) cancelAnimationFrame(two)
        one = 0
        two = 0

        if (start !== 0) return
        start = performance.now()

        if (session(prev)) setState("nav", { dur: undefined, pending: true })

        return
      }

      if (start === 0) {
        prev = next

        return
      }

      const at = start
      const from = prev

      start = 0
      prev = next

      if (!(session(from) || session(next))) return

      if (one !== 0) cancelAnimationFrame(one)

      if (two !== 0) cancelAnimationFrame(two)
      one = requestAnimationFrame(() => {
        one = 0
        two = requestAnimationFrame(() => {
          two = 0
          setState("nav", { dur: performance.now() - at, pending: false })
        })
      })
    },
  )

  onMount(() => {
    if (!props.diagnostics) return
    const obs: PerformanceObserver[] = []
    const fps: Array<{ at: number; dur: number }> = []
    const long: Array<{ at: number; dur: number }> = []
    const seen = new Map<number | string, { at: number; delay: number; dur: number }>()
    let hasLong = false
    let poll: number | undefined
    let raf = 0
    let last = 0
    let snap = 0

    const trim = (list: Array<{ at: number; dur: number }>, span: number, at: number) => {
      while (list[0] && at - list[0].at > span) list.shift()
    }

    const syncFrame = (at: number) => {
      trim(fps, span, at)
      const total = fps.reduce((sum, entry) => sum + entry.dur, 0)
      const gap = fps.reduce((max, entry) => Math.max(max, entry.dur), 0)
      const jank = fps.filter((entry) => entry.dur > 32).length
      batch(() => {
        setState("fps", total > 0 ? (fps.length * 1000) / total : undefined)
        setState("gap", gap > 0 ? gap : undefined)
        setState("jank", jank)
      })
    }

    const syncLong = (at = performance.now()) => {
      if (!hasLong) return
      trim(long, span, at)
      const block = long.reduce((sum, entry) => sum + Math.max(0, entry.dur - 50), 0)
      const max = long.reduce((hi, entry) => Math.max(hi, entry.dur), 0)
      setState("long", { block, count: long.length, max })
    }

    const syncInp = (at = performance.now()) => {
      for (const [key, entry] of seen) {
        if (at - entry.at > span) seen.delete(key)
      }

      let delay = 0
      let inp = 0

      for (const entry of seen.values()) {
        delay = Math.max(delay, entry.delay)
        inp = Math.max(inp, entry.dur)
      }

      batch(() => {
        setState("delay", delay > 0 ? delay : undefined)
        setState("inp", inp > 0 ? inp : undefined)
      })
    }

    const syncHeap = () => {
      const timing: Mem = performance
      const mem = timing.memory

      if (!mem) return
      setState("heap", { limit: mem.jsHeapSizeLimit, used: mem.usedJSHeapSize })
    }

    const reset = () => {
      fps.length = 0
      long.length = 0
      seen.clear()
      last = 0
      snap = 0
      batch(() => {
        setState("fps", undefined)
        setState("gap", undefined)
        setState("jank", undefined)
        setState("delay", undefined)
        setState("inp", undefined)

        if (hasLong) setState("long", { block: 0, count: 0, max: 0 })
      })
    }

    const watch = (type: string, init: Obs, fn: (entries: PerformanceEntry[]) => void) => {
      if (typeof PerformanceObserver === "undefined") return false

      if (!(PerformanceObserver.supportedEntryTypes ?? []).includes(type)) return false
      const ob = new PerformanceObserver((list) => fn(list.getEntries()))

      try {
        ob.observe(init)
        obs.push(ob)

        return true
      } catch {
        ob.disconnect()

        return false
      }
    }

    if (
      watch("layout-shift", { buffered: true, type: "layout-shift" }, (entries) => {
        const add = entries.reduce((sum, entry) => {
          // SAFETY: this observer subscribes to "layout-shift" entries alone, which carry these fields.
          const item = entry as Shift

          if (item.hadRecentInput) return sum

          return sum + item.value
        }, 0)

        if (add === 0) return
        setState("cls", (value) => (value ?? 0) + add)
      })
    ) {
      setState("cls", 0)
    }

    if (
      watch("longtask", { buffered: true, type: "longtask" }, (entries) => {
        const at = performance.now()
        long.push(...entries.map((entry) => ({ at: entry.startTime, dur: entry.duration })))
        syncLong(at)
      })
    ) {
      hasLong = true
      setState("long", { block: 0, count: 0, max: 0 })
    }

    watch("event", { buffered: true, durationThreshold: 16, type: "event" }, (entries) => {
      for (const raw of entries) {
        // SAFETY: this observer subscribes to "event" entries alone, which carry these optional fields.
        const entry = raw as Evt

        if (entry.duration < 16) continue

        const key =
          entry.interactionId && entry.interactionId > 0
            ? entry.interactionId
            : `${entry.name}:${Math.round(entry.startTime)}`

        const prev = seen.get(key)
        const delay = Math.max(0, (entry.processingStart ?? entry.startTime) - entry.startTime)
        seen.set(key, {
          at: entry.startTime,
          delay: Math.max(prev?.delay ?? 0, delay),
          dur: Math.max(prev?.dur ?? 0, entry.duration),
        })

        if (seen.size <= 200) continue
        const first = seen.keys().next().value

        if (first !== undefined) seen.delete(first)
      }

      syncInp()
    })

    const loop = (at: number) => {
      if (document.visibilityState !== "visible") {
        raf = 0

        return
      }

      if (last === 0) {
        last = at
        raf = requestAnimationFrame(loop)

        return
      }

      fps.push({ at, dur: at - last })
      last = at

      if (at - snap >= 250) {
        snap = at
        syncFrame(at)
      }

      raf = requestAnimationFrame(loop)
    }

    const stop = () => {
      if (raf !== 0) cancelAnimationFrame(raf)
      raf = 0

      if (poll === undefined) return
      clearInterval(poll)
      poll = undefined
    }

    const start = () => {
      if (document.visibilityState !== "visible") return

      if (poll === undefined) {
        poll = window.setInterval(() => {
          syncLong()
          syncInp()
          syncHeap()
        }, 1000)
      }

      if (raf !== 0) return
      raf = requestAnimationFrame(loop)
    }

    const vis = () => {
      if (document.visibilityState !== "visible") {
        stop()

        return
      }

      reset()
      start()
    }

    syncHeap()
    start()
    makeEventListener(document, "visibilitychange", vis)

    onCleanup(() => {
      if (one !== 0) cancelAnimationFrame(one)

      if (two !== 0) cancelAnimationFrame(two)
      stop()

      for (const ob of obs) ob.disconnect()
    })
  })

  return (
    <aside
      aria-label={ctx.t(props.diagnostics ? "ariaLabel" : "providerAriaLabel")}
      classList={{
        "pointer-events-auto hidden overflow-hidden text-text-strong md:block": true,
        "mt-[-6px] w-full shrink-0 px-3 py-1": !!props.inline,
        "fixed bottom-3 right-3 z-50 w-[308px] max-w-[calc(100vw-1.5rem)] rounded-xl border border-border-base bg-surface-raised-stronger-non-alpha p-0.5 shadow-[var(--shadow-lg-border-base)] sm:bottom-4 sm:right-4 sm:w-[324px]":
          !props.inline,
      }}
    >
      <div
        classList={{
          "font-mono": true,
          "gap-[9px]": !!props.inline,
          "gap-px": !props.inline,
          "flex w-full flex-nowrap items-center justify-start": !!props.inline,
          "grid-cols-4": !props.inline,
          grid: !props.inline,
        }}
      >
        <Cell
          label={ctx.t("tps.label")}
          tip={ctx.t("tps.tip")}
          value={fixed(metrics()?.tps, 1) ?? na()}
          dim={metrics()?.tps === undefined}
          inline={props.inline}
        />
        <Cell
          label={ctx.t("ttft.label")}
          tip={ctx.t("ttft.tip")}
          value={duration(metrics()?.ttft) ?? na()}
          dim={metrics()?.ttft === undefined}
          inline={props.inline}
        />
        <Cell
          label={ctx.t("ttfa.label")}
          tip={ctx.t("ttfa.tip")}
          value={duration(metrics()?.ttfa) ?? na()}
          dim={metrics()?.ttfa === undefined}
          inline={props.inline}
        />
        <Cell
          label={ctx.t("e2e.label")}
          tip={ctx.t("e2e.tip")}
          value={duration(metrics()?.e2e) ?? na()}
          dim={metrics()?.e2e === undefined}
          inline={props.inline}
        />
        <Show when={props.diagnostics}>
          <Cell
            label={ctx.t("nav.label")}
            tip={ctx.t("nav.tip")}
            value={navv()}
            bad={bad(state.nav.dur, 400)}
            dim={state.nav.dur === undefined && !state.nav.pending}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("fps.label")}
            tip={ctx.t("fps.tip")}
            value={state.fps === undefined ? na() : `${Math.round(state.fps)}`}
            bad={bad(state.fps, 50, true)}
            dim={state.fps === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("frame.label")}
            tip={ctx.t("frame.tip")}
            value={time(state.gap) ?? na()}
            bad={bad(state.gap, 50)}
            dim={state.gap === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("jank.label")}
            tip={ctx.t("jank.tip")}
            value={state.jank === undefined ? na() : `${state.jank}`}
            bad={bad(state.jank, 8)}
            dim={state.jank === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("long.label")}
            tip={ctx.t("long.tip", { max: ms(state.long.max) ?? na() })}
            value={longv()}
            bad={bad(state.long.block, 200)}
            dim={state.long.count === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("delay.label")}
            tip={ctx.t("delay.tip")}
            value={time(state.delay) ?? na()}
            bad={bad(state.delay, 100)}
            dim={state.delay === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("inp.label")}
            tip={ctx.t("inp.tip")}
            value={time(state.inp) ?? na()}
            bad={bad(state.inp, 200)}
            dim={state.inp === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("cls.label")}
            tip={ctx.t("cls.tip")}
            value={state.cls === undefined ? na() : state.cls.toFixed(2)}
            bad={bad(state.cls, 0.1)}
            dim={state.cls === undefined}
            inline={props.inline}
          />
          <Cell
            label={ctx.t("mem.label")}
            tip={
              state.heap.used === undefined
                ? ctx.t("mem.tipUnavailable")
                : ctx.t("mem.tip", {
                    used: mb(state.heap.used) ?? na(),
                    limit: mb(state.heap.limit) ?? na(),
                  })
            }
            value={heapv()}
            bad={bad(heap(), 0.8)}
            dim={state.heap.used === undefined}
            inline={props.inline}
            span={desktop ? 2 : 3}
          />
          <ToggleCell
            active={locale.direction() === "rtl"}
            inline={props.inline}
            label={ctx.t("direction.label")}
            tip={ctx.t("direction.tip")}
            value={ctx.t(`direction.${locale.direction()}`)}
            onClick={() => locale.setDirection(locale.direction() === "rtl" ? "ltr" : "rtl")}
          />
          <Show when={desktop}>
            <ToggleCell
              active={state.focus}
              inline={props.inline}
              label={ctx.t("focus.label")}
              tip={ctx.t("focus.tip")}
              value={ctx.t(state.focus ? "focus.on" : "focus.off")}
              onClick={() => void toggleFocus()}
            />
          </Show>
        </Show>
      </div>
    </aside>
  )
}

import { expect, test } from "bun:test"
import type { SessionMessageAssistant, SessionMessageInfo } from "@opencode/client/promise"
import type { ProviderMetricEvent, ProviderMetricState } from "./metrics"
import { applyProviderMetricEvent, projectedProviderMetrics } from "./metrics"

const durable = { aggregateID: "ses_test", seq: 0, version: 1 } as const

const events: ProviderMetricEvent[] = [
  {
    id: "evt_started",
    created: 1_000,
    type: "session.step.started",
    durable,
    data: {
      sessionID: "ses_test",
      assistantMessageID: "msg_assistant",
      agent: "build",
      model: { id: "model", providerID: "provider" },
      started: 1_000,
    },
  },
  {
    id: "evt_reasoning",
    created: 1_300,
    type: "session.reasoning.started",
    durable: { ...durable, seq: 1 },
    data: { sessionID: "ses_test", assistantMessageID: "msg_assistant", ordinal: 0 },
  },
  {
    id: "evt_text",
    created: 1_800,
    type: "session.text.started",
    durable: { ...durable, seq: 2 },
    data: { sessionID: "ses_test", assistantMessageID: "msg_assistant", ordinal: 0 },
  },
  {
    id: "evt_streamed",
    created: 3_800,
    type: "session.step.streamed",
    durable: { ...durable, seq: 3 },
    data: { sessionID: "ses_test", assistantMessageID: "msg_assistant" },
  },
  {
    id: "evt_ended",
    created: 4_000,
    type: "session.step.ended",
    durable: { ...durable, seq: 4 },
    data: {
      sessionID: "ses_test",
      assistantMessageID: "msg_assistant",
      finish: "stop",
      cost: 0,
      tokens: { input: 200, output: 100, reasoning: 20, cache: { read: 0, write: 0 } },
    },
  },
]

test("calculates provider response metrics from durable events", () => {
  const state: ProviderMetricState = {}
  events.forEach((event) => applyProviderMetricEvent(state, event))
  expect(state.latest).toEqual({
    tps: 50,
    ttft: 300,
    ttfa: 800,
    e2e: 2_800,
  })
})

const assistant: SessionMessageAssistant = {
  id: "msg_assistant",
  type: "assistant",
  agent: "build",
  model: { id: "model", providerID: "provider" },
  content: [
    { type: "reasoning", text: "Think", time: { created: 1_300, completed: 1_700 } },
    { type: "text", text: "Answer" },
  ],
  tokens: { input: 200, output: 100, reasoning: 20, cache: { read: 0, write: 0 } },
  time: { created: 1_000, streamed: 3_800, completed: 4_000 },
}

test("derives a baseline from the latest completed projected request", () => {
  const messages: SessionMessageInfo[] = [
    { id: "msg_user", type: "user", text: "Hi", time: { created: 1 } },
    assistant,
    { ...assistant, id: "msg_running", tokens: undefined, time: { created: 5_000 } },
  ]
  // Reasoning ended at 1_700, so TPS spans 1_700 → 3_800 = 100 / 2.1s.
  expect(projectedProviderMetrics(messages)).toEqual({ tps: 100 / 2.1, ttft: 300, ttfa: 700, e2e: 2_800 })
})

import type {
  SessionLogItem,
  SessionMessageAssistant,
  SessionMessageInfo,
  TokenUsageInfo,
} from "@opencode/client/promise"

type ProviderMetricEventType =
  | "session.step.started"
  | "session.step.streamed"
  | "session.step.ended"
  | "session.step.failed"
  | "session.text.started"
  | "session.reasoning.started"
  | "session.tool.input.started"

const types: ReadonlySet<string> = new Set<ProviderMetricEventType>([
  "session.step.started",
  "session.step.streamed",
  "session.step.ended",
  "session.step.failed",
  "session.text.started",
  "session.reasoning.started",
  "session.tool.input.started",
])

export type ProviderMetricEvent = Extract<SessionLogItem, { type: ProviderMetricEventType }>

export type ProviderMetrics = {
  tps?: number
  ttft?: number
  ttfa?: number
  e2e?: number
}

type Attempt = {
  assistantMessageID: string
  started: number
  first?: number
  answer?: number
  streamed?: number
  tokens?: TokenUsageInfo
}

export type ProviderMetricState = { attempt?: Attempt; latest?: ProviderMetrics }

export function isProviderMetricEvent(event: { type: string }): event is ProviderMetricEvent {
  return types.has(event.type)
}

export function applyProviderMetricEvent(state: ProviderMetricState, event: ProviderMetricEvent) {
  if (event.type === "session.step.started") {
    state.attempt = {
      assistantMessageID: event.data.assistantMessageID,
      started: event.data.started,
    }
    return
  }

  if (!state.attempt || event.data.assistantMessageID !== state.attempt.assistantMessageID) return

  if (
    event.type === "session.text.started" ||
    event.type === "session.reasoning.started" ||
    event.type === "session.tool.input.started"
  ) {
    state.attempt.first ??= event.created
    if (event.type === "session.text.started") state.attempt.answer ??= event.created
    return
  }

  if (event.type === "session.step.streamed") {
    state.attempt.streamed = event.created
    return
  }

  // Interrupted or failed attempts without usage would publish misleading partial numbers.
  if (!event.data.tokens || state.attempt.first === undefined || state.attempt.streamed === undefined) return
  state.attempt.tokens = event.data.tokens
  state.latest = attemptMetrics(state.attempt)
}

/**
 * Baseline from already-loaded history. Text parts carry no start timestamp yet, so TTFT, TTFA,
 * and TPS stay unavailable for text-first requests until a live request supplies them.
 */
export function projectedProviderMetrics(messages: readonly SessionMessageInfo[]): ProviderMetrics | undefined {
  const message = messages.findLast(
    (item): item is SessionMessageAssistant =>
      item.type === "assistant" && item.time.streamed !== undefined && item.tokens !== undefined,
  )
  if (!message) return
  // Content is chronological; only a non-text head carries the first-output time.
  const head = message.content[0]
  const first = head && head.type !== "text" ? head.time?.created : undefined
  // Reasoning ends when the answer starts, so a reasoning part right before the first text
  // approximates the live `session.text.started` timestamp.
  const text = message.content.findIndex((item) => item.type === "text")
  const before = text > 0 ? message.content[text - 1] : undefined
  const answer = first !== undefined && before?.type === "reasoning" ? before.time?.completed : undefined
  return attemptMetrics({
    assistantMessageID: message.id,
    started: message.time.created,
    first,
    answer,
    streamed: message.time.streamed,
    tokens: message.tokens,
  })
}

function attemptMetrics(attempt: Attempt): ProviderMetrics {
  const ttft = elapsed(attempt.started, attempt.first)
  const ttfa = elapsed(attempt.started, attempt.answer)
  const e2e = elapsed(attempt.started, attempt.streamed)
  // Output tokens exclude reasoning, so measure them from the answer start when one exists.
  const generation = elapsed(attempt.answer ?? attempt.first, attempt.streamed)
  const output = attempt.tokens?.output
  return {
    tps: generation && output && generation > 0 && output > 0 ? output / (generation / 1_000) : undefined,
    ttft,
    ttfa,
    e2e,
  }
}

function elapsed(start: number | undefined, end: number | undefined) {
  if (start === undefined || end === undefined) return
  return Math.max(0, end - start)
}

import { createSignal, lazy, Show, Suspense } from "solid-js"
import { Command, Slot, TitlebarItem, type Setup } from "../sdk"
import type Debug from "./index"

const setup: Setup<typeof Debug> = (ctx) => {
  const DebugBar = lazy(() => import("./bar"))
  const channel = ctx.build.channel
  // Window-local; every window starts with the bar hidden.
  const [visible, setVisible] = createSignal(false)

  const toggle = () => {
    setVisible((value) => !value)
  }

  ctx.add(
    Command,
    (): Command => ({
      id: "toggle",
      title: ctx.t("command.toggle"),
      group: ctx.t("command.category.view"),
      run: toggle,
    }),
  )

  ctx.add(Slot, {
    at: "window.bottom",
    render: () => (
      <Show when={visible()}>
        <Suspense>
          <DebugBar diagnostics={import.meta.env.DEV} inline />
        </Suspense>
      </Show>
    ),
  })

  if (channel !== "dev" && channel !== "local") return
  ctx.add(
    TitlebarItem,
    (): TitlebarItem => ({
      id: "toggle",
      placement: "channel",
      label: ctx.t("status.toggle"),
      pressed: visible(),
      run: toggle,
    }),
  )
}

export default setup

import { expect, test } from "bun:test"
import { configuredLsps } from "./configured-lsp"

test("lists configured LSP names with project overrides and no inferred built-ins", () => {
  expect(
    configuredLsps([
      {
        type: "document",
        info: {
          lsp: {
            typescript: { command: ["typescript-language-server", "--stdio"] },
            rust: { command: ["rust-analyzer"] },
          },
        },
      },
      {
        type: "document",
        info: {
          lsp: {
            typescript: { disabled: true },
            eslint: { command: ["vscode-eslint-language-server", "--stdio"] },
          },
        },
      },
    ]),
  ).toEqual(["eslint", "rust"])
  expect(configuredLsps([{ type: "document", info: { lsp: true } }])).toEqual([])
})

test("a later whole-LSP setting clears earlier names", () => {
  expect(
    configuredLsps([
      { type: "document", info: { lsp: { rust: { command: ["rust-analyzer"] } } } },
      { type: "document", info: { lsp: false } },
      { type: "document", info: { lsp: { custom: { command: ["custom-lsp"] } } } },
    ]),
  ).toEqual(["custom"])
})

import { DiffChanges } from "@opencode/ui/diff-changes"
import { Icon } from "@opencode/ui/icon"
import { containsDirectory, getFilename } from "@opencode/util/path"
import { createMemo, Show } from "solid-js"
import { useExtension, type Project, type MountedSession } from "../sdk"
import { workspaceDirectories } from "./paths"
import { ProjectDetailsCard } from "./project-card"
import { SessionServerPanel } from "./server-panel"
import { SessionWorkspaceMenu } from "./workspace-menu"

export type Disclosure = {
  project(): boolean
  server(): boolean
  setProject(expanded: boolean): void
  setServer(expanded: boolean): void
}

export type DetailsPanelProps = {
  session: MountedSession
  project: Project
  shown?: boolean
  mobile?: boolean
  diffs?: readonly { additions: number; deletions: number }[]
  moveDismissed: boolean
  onMoveDismiss: () => void
  /** Absent while the review extension is disabled, which also leaves `diffs` undefined. */
  onReview?: () => void
  disclosure: Disclosure
}

export default function SessionDetailsPanel(props: DetailsPanelProps) {
  const ctx = useExtension()
  const locale = ctx.locale
  const data = () => props.session.server.data

  const placement = createMemo(() =>
    props.mobile ? "top-end" : locale.direction() === "rtl" ? "right-start" : "left-start",
  )

  const location = () => {
    if (props.session.local) return ctx.t("workspace.local")

    const workspace = workspaceDirectories(props.project).find((item) =>
      containsDirectory(item, props.session.directory),
    )

    return getFilename(workspace ?? props.session.directory)
  }

  // A subagent shares its parent's workspace, so it shows where it runs but cannot move on its own.
  const subagent = () => !!data().session.get(props.session.id)?.parentID

  const workspace = () => (
    <>
      <Icon name={props.session.local ? "monitor" : "outline-worktree"} class="shrink-0 text-v2-icon-icon-muted" />
      <span dir="auto" class="session-summary-label">
        {location()}
      </span>
    </>
  )

  const branch = () => data().location.vcs.info({ directory: props.session.directory })?.branch.current
  const baseBranch = () => data().location.vcs.info({ directory: props.project.worktree })?.branch.current

  return (
    <div data-component="session-summary-panel" data-mobile={props.mobile || undefined}>
      <div>
        <ProjectDetailsCard
          project={props.project}
          expanded={props.disclosure.project()}
          onExpandedChange={props.disclosure.setProject}
        >
          <Show when={!subagent()} fallback={<div class="session-summary-row">{workspace()}</div>}>
            <SessionWorkspaceMenu
              session={props.session}
              project={props.project}
              directory={props.session.directory}
              placement={placement()}
              class="session-summary-row"
            >
              {workspace()}
              <Icon name="fill-triangle-down" class="session-summary-menu-indicator shrink-0 text-v2-icon-icon-muted" />
            </SessionWorkspaceMenu>
          </Show>
          <div class="session-summary-row">
            <Icon name="branch" class="shrink-0 text-v2-icon-icon-muted" />
            <Show
              when={branch()}
              fallback={
                <span class="flex min-w-0 items-center gap-1.5">
                  <span class="shrink-0 whitespace-nowrap">{ctx.t("noBranch")}</span>
                  <Show when={baseBranch()}>
                    {(base) => (
                      <>
                        <span class="text-v2-text-text-muted">·</span>
                        <span class="truncate text-v2-text-text-faint">{ctx.t("basedOn", { branch: base() })}</span>
                      </>
                    )}
                  </Show>
                </span>
              }
            >
              <span dir="auto" class="min-w-0 truncate">
                {branch()}
              </span>
            </Show>
          </div>
          <Show when={props.onReview}>
            <button type="button" class="session-summary-row" onClick={() => props.onReview?.()}>
              <Icon name="review" class="shrink-0 text-v2-icon-icon-muted" />
              <span class="session-summary-label flex items-center gap-2">
                <Show
                  when={props.diffs}
                  fallback={<span class="truncate text-v2-text-text-muted">{ctx.t("loadingChanges")}</span>}
                >
                  {(diffs) => (
                    <Show
                      when={diffs().length > 0}
                      fallback={<span class="truncate text-v2-text-text-muted">{ctx.t("noChanges")}</span>}
                    >
                      <span class="min-w-0 truncate">{ctx.plural("ui.sessionTurn.diffs.changed", diffs().length)}</span>
                      <span class="shrink-0 text-v2-text-text-muted">·</span>
                      <DiffChanges appearance="standard" changes={[...diffs()]} />
                    </Show>
                  )}
                </Show>
              </span>
            </button>
          </Show>
        </ProjectDetailsCard>
        <Show
          when={
            !subagent() &&
            props.disclosure.project() &&
            props.session.local &&
            props.diffs?.length &&
            !props.moveDismissed
          }
        >
          <div class="session-summary-move">
            <SessionWorkspaceMenu
              session={props.session}
              project={props.project}
              directory={props.session.directory}
              placement={placement()}
              class="session-summary-row"
            >
              <Icon name="outline-worktree" class="shrink-0 text-v2-icon-icon-muted" />
              <span class="min-w-0 truncate">{ctx.t("move.title")}</span>
            </SessionWorkspaceMenu>
            <button
              type="button"
              class="session-summary-dismiss"
              aria-label={ctx.t("common.dismiss")}
              onClick={props.onMoveDismiss}
            >
              <Icon name="xmark-small" />
            </button>
          </div>
        </Show>
      </div>
      <SessionServerPanel
        session={props.session}
        directory={props.session.directory}
        shown={props.shown !== false}
        mobile={props.mobile}
        expanded={props.disclosure.server()}
        onExpandedChange={props.disclosure.setServer}
      />
    </div>
  )
}

import { sameDirectory } from "@opencode/util/path"

export function workspaceDirectories(project: { worktree: string; sandboxes?: readonly string[] }) {
  return (project.sandboxes ?? []).filter((directory) => !sameDirectory(project.worktree, directory))
}

import { Popover } from "@kobalte/core/popover"
import { Icon } from "@opencode/ui/icon"
import { IconButton } from "@opencode/ui/icon-button"
import { Keybind } from "@opencode/ui/keybind"
import { Tooltip } from "@opencode/ui/tooltip"
import { createMemo, onCleanup, Show, Suspense, type Component, type ParentProps } from "solid-js"
import { createStore } from "solid-js/store"
import { Command, createKeyed, createVisitState, useExtension, type MountedSession, type SessionScreen } from "../sdk"
import type Details from "./index"
import type { Disclosure, DetailsPanelProps } from "./panel"

/** The session details button of one timeline header. Cached timelines each keep their own. */
export function DetailsHeader(props: {
  session: MountedSession
  screen: SessionScreen
  active: boolean
  panel: Component<DetailsPanelProps>
  disclosure: Disclosure
}) {
  const changes = useExtension<typeof Details>().uses.changes
  const Panel = props.panel
  // Cached timelines stay mounted while hidden; routing away from the session closes its details.
  const [open, setOpen] = createVisitState(false)
  const [store, setStore] = createStore({ dismissed: false })
  const project = createMemo(() => props.session.project)

  // Review is optional: the changes row offers it only while the review extension is active.
  const review = createMemo(() => {
    const live = changes()

    if (live.status !== "active") return

    return {
      details: () => live.value.details(props.session),
      open: () => {
        setOpen(false)
        live.value.open(props.session)
      },
    }
  })

  // The changes row loads the session directory's changes only while the details show.
  createKeyed(changes, (service) =>
    createKeyed(
      () => open() && props.screen,
      (screen) => onCleanup(service.watch(screen, "details")),
    ),
  )

  return (
    <Show when={project()}>
      {(project) => (
        <DetailsPopover active={props.active} open={open()} onOpenChange={setOpen}>
          <Suspense>
            <Panel
              session={props.session}
              shown={open()}
              project={project()}
              diffs={project().vcs ? review()?.details() : []}
              moveDismissed={store.dismissed}
              onMoveDismiss={() => setStore("dismissed", true)}
              onReview={review()?.open}
              disclosure={props.disclosure}
            />
          </Suspense>
        </DetailsPopover>
      )}
    </Show>
  )
}

function DetailsPopover(props: ParentProps<{ active: boolean; open: boolean; onOpenChange: (open: boolean) => void }>) {
  const ctx = useExtension()
  const keybinds = ctx.keybinds

  // Cached timelines remain mounted; only the visible details own the command. It leaves with this component.
  ctx.add(Command, (): Command | undefined =>
    props.active
      ? {
          id: "toggle",
          title: ctx.t("command.toggle"),
          group: ctx.t("command.category.view"),
          section: "session",
          bind: "mod+shift+y",
          run: () => props.onOpenChange(!props.open),
        }
      : undefined,
  )

  const keybind = () => [...keybinds.keybind(`${ctx.id}.toggle`)]

  return (
    <Popover open={props.open} placement="bottom-end" gutter={8} overflowPadding={16} onOpenChange={props.onOpenChange}>
      {/* Match the button's vertical bounds; the 8px gutter plus 4px content padding gives a 12px card gap. */}
      <Popover.Anchor class="pointer-events-none absolute end-3 top-2.5 h-7 w-0" aria-hidden="true" />
      <Tooltip
        placement="bottom"
        value={
          <>
            {ctx.t("tooltip")}
            <Show when={keybind().length > 0}>
              <Keybind keys={keybind()} variant="neutral" />
            </Show>
          </>
        }
      >
        <Popover.Trigger
          as={IconButton}
          icon={<Icon name="window-analytics" />}
          variant="ghost-muted"
          size="large"
          state={props.open ? "pressed" : undefined}
          aria-label={ctx.t("title")}
          aria-expanded={props.open}
        />
      </Tooltip>
      <Popover.Portal>
        <Popover.Content
          class="session-summary-popover z-50 max-h-[calc(100dvh-96px)] overflow-y-auto border-0 bg-transparent p-1 outline-none"
          aria-label={ctx.t("title")}
        >
          {props.children}
        </Popover.Content>
      </Popover.Portal>
    </Popover>
  )
}

import { Icon } from "@opencode/ui/icon"
import {
  displayName,
  getProjectAvatarSource,
  getProjectAvatarVariant,
  ProjectAvatar,
} from "@opencode/ui/project-avatar"
import { createUniqueId, Show, type ParentProps } from "solid-js"
import type { Project } from "../sdk"

export function ProjectDetailsCard(
  props: ParentProps<{
    project: Pick<Project, "name" | "worktree" | "icon"> & { id?: string }
    expanded: boolean
    onExpandedChange: (expanded: boolean) => void
  }>,
) {
  const contentID = createUniqueId()

  return (
    <section class="session-summary-card" data-section="project">
      <button
        type="button"
        class="session-summary-row session-summary-heading"
        aria-label={displayName(props.project)}
        aria-expanded={props.expanded}
        aria-controls={contentID}
        onClick={() => props.onExpandedChange(!props.expanded)}
      >
        <ProjectAvatar
          fallback={displayName(props.project)}
          src={getProjectAvatarSource(props.project.id, props.project.icon)}
          variant={getProjectAvatarVariant(props.project.icon?.color)}
        />
        <span dir="auto" class="session-summary-label">
          {displayName(props.project)}
        </span>
        <Icon name="chevron-down" size="small" class="session-summary-disclosure" />
      </button>
      <Show when={props.expanded}>
        <div id={contentID} class="session-summary-rows">
          {props.children}
        </div>
      </Show>
    </section>
  )
}

import { createMemo, lazy, onCleanup, Show, Suspense } from "solid-js"
import { createStore } from "solid-js/store"
import { createKeyed, onIdle, Panel, Slot, Style, useDrawer, usePanel, type Setup } from "../sdk"
import type Details from "./index"
import type { Disclosure } from "./panel"
import { DetailsHeader } from "./popover"

const setup: Setup<typeof Details> = (ctx) => {
  const sessions = ctx.sessions
  const changes = ctx.uses.changes
  const prefs = ctx.stores.prefs

  const disclosure: Disclosure = {
    project: () => prefs.value.projectExpanded,
    server: () => prefs.value.serverExpanded,
    setProject: (expanded) =>
      prefs.update((draft) => {
        draft.projectExpanded = expanded
      }),
    setServer: (expanded) =>
      prefs.update((draft) => {
        draft.serverExpanded = expanded
      }),
  }

  const DetailsPanel = lazy(() =>
    Promise.all([import("./panel"), import("./details.css?inline")]).then(([panel, css]) => {
      ctx.add(Style, css.default)

      return panel
    }),
  )

  // Compile the panel while the app idles, so the first open renders at once.
  onCleanup(onIdle(() => void DetailsPanel.preload()))

  ctx.add(Slot, {
    at: "session.header",
    order: 20,
    render: (input) => (
      <DetailsHeader
        session={input.session}
        screen={input.screen}
        active={input.active}
        panel={DetailsPanel}
        disclosure={disclosure}
      />
    ),
  })

  // The narrow-screen details drawer, offered for sessions of a project, subagents included.
  const panel: Panel = {
    id: "main",
    region: "side",
    mobile: {
      get title() {
        return ctx.t("title")
      },
      order: 50,
      kind: "drawer",
      icon: "info",
    },
    list: () => [],
    render: (props) => {
      const frame = usePanel()
      const drawer = useDrawer()
      const [store, setStore] = createStore({ dismissed: false })

      // Review is optional: the changes row offers it only while the review extension is active.
      const review = createMemo(() => {
        const live = changes()

        if (live.status !== "active") return

        return {
          details: () => live.value.details(props.session),
          open: () => {
            drawer?.close()
            live.value.open(props.session)
          },
        }
      })

      // The changes row loads the session directory's changes only while the drawer shows.
      createKeyed(changes, (service) =>
        createKeyed(frame.visible, () => onCleanup(service.watch(props.screen, "details"))),
      )

      return (
        <Show when={props.session.project}>
          {(project) => (
            <Suspense>
              <DetailsPanel
                mobile
                shown={frame.visible()}
                session={props.session}
                project={project()}
                diffs={project().vcs ? review()?.details() : []}
                moveDismissed={store.dismissed}
                onMoveDismiss={() => setStore("dismissed", true)}
                onReview={review()?.open}
                disclosure={disclosure}
              />
            </Suspense>
          )}
        </Show>
      )
    },
  }

  ctx.add(Panel, () => {
    const session = sessions.current()

    if (!session?.project) return

    return panel
  })
}

export default setup

import { Popover } from "@kobalte/core/popover"
import type { PluginInfo } from "@opencode/client"
import { Icon } from "@opencode/ui/icon"
import { Switch } from "@opencode/ui/switch"
import { showToast } from "@opencode/ui/toast"
import { Tooltip } from "@opencode/ui/tooltip"
import { getDirectory } from "@opencode/util/path"
import { useMutation } from "@tanstack/solid-query"
import {
  children,
  createMemo,
  createResource,
  createSignal,
  createUniqueId,
  For,
  Index,
  on,
  onCleanup,
  Show,
  type JSX,
} from "solid-js"
import { createStore } from "solid-js/store"
import { createKeyed, useDrawer, useExtension, type MountedSession } from "../sdk"
import { configuredLsps } from "./configured-lsp"

const services = [
  { type: "mcp", icon: "mcp", label: "mcp" },
  { type: "plugins", icon: "cube", label: "plugins" },
  { type: "skills", icon: "graduation-cap", label: "skills" },
  { type: "lsp", icon: "code-slash", label: "lsp" },
] as const

type Service = (typeof services)[number]["type"]

type ServiceMenuProps = {
  session: MountedSession
  service: (typeof services)[number]
  directory: string
  shown: boolean
  open: boolean
  mobile?: boolean
  onOpenChange: (open: boolean) => void
}

export function SessionServerPanel(props: {
  session: MountedSession
  directory: string
  shown: boolean
  mobile?: boolean
  expanded: boolean
  onExpandedChange: (expanded: boolean) => void
}) {
  const ctx = useExtension()
  const servers = ctx.servers
  const contentID = createUniqueId()
  // With one server the card is generic; with several it names the session's server.
  const name = () => (servers.list().length < 2 ? ctx.t("server") : props.session.server.name)
  // A new scope whenever the directory, the details' visibility or the disclosure changes closes the open submenu.
  const scope = createMemo(on([() => props.directory, () => props.shown, () => props.expanded], () => ({})))
  const [submenu, setSubmenu] = createSignal<{ readonly scope: object; readonly service: Service }>()

  const open = () => {
    const current = submenu()

    return current?.scope === scope() ? current.service : undefined
  }

  return (
    <section class="session-summary-card" data-section="server">
      <button
        type="button"
        class="session-summary-row session-summary-heading"
        aria-expanded={props.expanded}
        aria-controls={contentID}
        onClick={() => props.onExpandedChange(!props.expanded)}
      >
        <Icon name="server" class="shrink-0 text-v2-icon-icon-muted" />
        <span dir="auto" class="session-summary-label">
          {name()}
        </span>
        <Icon name="chevron-down" size="small" class="session-summary-disclosure" />
      </button>
      <Show when={props.expanded ? props.directory : undefined} keyed>
        {(directory) => (
          <div id={contentID} class="session-summary-rows">
            <For each={services}>
              {(service) => (
                <ServiceMenu
                  session={props.session}
                  service={service}
                  directory={directory}
                  shown={props.shown}
                  open={open() === service.type}
                  mobile={props.mobile}
                  onOpenChange={(value) => setSubmenu(value ? { scope: scope(), service: service.type } : undefined)}
                />
              )}
            </For>
          </div>
        )}
      </Show>
    </section>
  )
}

function ServiceMenu(props: ServiceMenuProps) {
  if (props.service.type === "mcp") return <McpMenu {...props} />

  if (props.service.type === "lsp") return <LspMenu {...props} />

  return <ServiceCatalog {...props} />
}

function LspMenu(props: ServiceMenuProps) {
  const ctx = useExtension()
  const data = () => props.session.server.data

  const [load, { refetch }] = createResource(
    () => props.shown && data(),
    (current) => {
      const directory = props.directory

      current.location.config.invalidate({ directory })

      return current.location.config.sync({ directory })
    },
  )

  const names = createMemo(() => configuredLsps(data().location.config.list({ directory: props.directory }) ?? []))

  createKeyed(data, (current) =>
    onCleanup(
      current.on("config.updated", (event) => {
        if (event.location?.directory !== props.directory) return
        void refetch()
      }),
    ),
  )

  return (
    <ServicePopover
      {...props}
      loading={load.loading}
      ready={data().location.config.list({ directory: props.directory }) !== undefined}
      empty={names().length === 0}
      error={load.error}
      retry={refetch}
    >
      <Show
        when={names().length}
        fallback={
          <ServiceEmpty session={props.session} title={ctx.t("lsp.empty")} directory={props.directory} service="lsp" />
        }
      >
        <h3 class="session-service-title">{ctx.t("lsp.configured")}</h3>
        <For each={names()}>
          {(name) => (
            <div class="session-service-row">
              <span dir="auto" class="session-summary-label">
                {name}
              </span>
            </div>
          )}
        </For>
        <div class="session-service-footer">
          <ServiceConfigLink session={props.session} directory={props.directory} service="lsp" />
        </div>
      </Show>
    </ServicePopover>
  )
}

function McpMenu(props: ServiceMenuProps) {
  const ctx = useExtension()
  const system = ctx.system
  const data = () => props.session.server.data

  const toggle = useMutation(() => ({
    mutationFn: async (input: { name: string; enabled: boolean }) => {
      const client = props.session.server.client
      const source = data()
      const ref = { directory: props.directory }
      const server = (await client.mcp.list({ location: ref })).data.find((item) => item.name === input.name)

      if (!server) return

      if (!input.enabled) {
        await client.mcp.disconnect({ server: input.name, location: ref })
      }

      if (input.enabled && server.status.status !== "needs_auth") {
        await client.mcp.connect({ server: input.name, location: ref })
      }

      source.location.mcp.server.invalidate(ref)
      await source.location.mcp.server.sync(ref)
      const current = source.location.mcp.server.list(ref)?.find((item) => item.name === input.name)

      if (input.enabled && current?.status.status === "needs_auth" && current.integrationID) {
        const integration = await client.integration.get({ integrationID: current.integrationID, location: ref })
        const method = integration.data?.methods.find((item) => item.type === "oauth" && !item.form?.length)

        if (!method || method.type !== "oauth") throw new Error(ctx.t("mcp.interactiveAuth", { name: input.name }))

        const attempt = await client.integration.oauth.connect({
          integrationID: current.integrationID,
          methodID: method.id,
          location: ref,
        })

        system.openExternal(attempt.data.url)
      }

      source.location.mcp.resource.invalidate(ref)
      await source.location.mcp.resource.sync(ref)
      // A successful HTTP response can still leave the MCP connection in a failed state.
      const status = current?.status

      if (status?.status === "failed") throw new Error(`${input.name}: ${status.error}`)
    },
    onError: (error) =>
      showToast({
        variant: "error",
        title: ctx.t("common.requestFailed"),
        description: error instanceof Error ? error.message : String(error),
      }),
  }))

  const [load, { refetch }] = createResource(
    () => props.shown && data(),
    async (current) => {
      const directory = props.directory

      current.location.mcp.server.invalidate({ directory })
      await current.location.mcp.server.sync({ directory })
    },
  )

  const servers = createMemo(() =>
    (data().location.mcp.server.list({ directory: props.directory }) ?? []).toSorted((a, b) =>
      a.name.localeCompare(b.name),
    ),
  )

  return (
    <ServicePopover
      {...props}
      loading={load.loading}
      ready={data().location.mcp.server.list({ directory: props.directory }) !== undefined}
      empty={servers().length === 0}
      error={load.error}
      retry={refetch}
    >
      <Show
        when={servers().length}
        fallback={
          <ServiceEmpty session={props.session} title={ctx.t("mcp.empty")} directory={props.directory} service="mcp" />
        }
      >
        <h3 class="session-service-title">{ctx.t("mcp.title")}</h3>
        <Index each={servers()}>
          {(server) => {
            const enabled = () => server().status.status !== "disabled"
            const pending = () => toggle.isPending || server().status.status === "pending"

            const error = () => {
              const status = server().status

              return status.status === "failed" ? status.error : undefined
            }

            const label = () => {
              const status = server().status.status

              if (status === "failed") return ctx.t("failed")

              if (status === "pending") return ctx.t("connecting")

              if (status === "needs_auth") return ctx.t("needsAuth")

              return undefined
            }

            const change = (value: boolean) => {
              if (pending()) return
              toggle.mutate({ name: server().name, enabled: value })
            }

            return (
              <Switch
                class="session-mcp-row [&_[data-slot=switch-description]]:sr-only"
                description={label()}
                checked={enabled()}
                readOnly={pending()}
                aria-disabled={pending()}
                aria-busy={toggle.isPending}
                onChange={change}
                onClick={(event: MouseEvent) => {
                  if (
                    !(event.target instanceof Element) ||
                    event.target.closest('[data-slot="switch-control"], [data-slot="switch-input"]')
                  )
                    return

                  // Outside the switch itself, a row that requires sign-in starts sign-in instead of toggling.
                  if (server().status.status === "needs_auth") {
                    event.preventDefault()

                    return change(true)
                  }

                  if (event.target === event.currentTarget) change(!enabled())
                }}
                title={error() ?? server().name}
              >
                <span class="session-service-dot" data-status={server().status.status} aria-hidden="true" />
                <span dir="auto" class="session-summary-label">
                  {server().name}
                </span>
                <Show when={label()}>
                  {(status) => (
                    <span class="session-service-status" aria-hidden="true">
                      {status()}
                    </span>
                  )}
                </Show>
              </Switch>
            )
          }}
        </Index>
        <div class="session-service-footer">
          <ServiceConfigLink session={props.session} directory={props.directory} service="mcp" />
        </div>
      </Show>
    </ServicePopover>
  )
}

function ServiceCatalog(props: ServiceMenuProps) {
  const ctx = useExtension()
  const data = () => props.session.server.data

  const [items, { refetch }] = createResource(
    () => props.shown && data(),
    async (current) => {
      const directory = props.directory

      if (props.service.type === "plugins") {
        const result = await props.session.server.client.plugin.list({ location: { directory } })

        return result.data
          .filter((plugin) => plugin.source.type !== "builtin")
          .map((plugin) => ({
            name: pluginLabel(plugin),
            status: plugin.state.status,
            error: plugin.state.status === "failed" ? plugin.state.error : undefined,
          }))
      }

      current.location.skill.invalidate({ directory })
      await current.location.skill.sync({ directory })

      return undefined
    },
  )

  const loaded = () => items.state === "ready" || items.state === "refreshing"

  const list = createMemo(() => {
    const entries =
      props.service.type === "plugins"
        ? loaded()
          ? (items.latest ?? [])
          : []
        : (data().location.skill.list({ directory: props.directory }) ?? []).map((skill) => ({
            name: skill.name,
            status: "active",
            error: undefined,
          }))

    return entries.toSorted((a, b) => a.name.localeCompare(b.name))
  })

  createKeyed(data, (current) =>
    onCleanup(
      current.on(props.service.type === "plugins" ? "plugin.updated" : "skill.updated", (event) => {
        if (event.location?.directory !== props.directory) return
        void refetch()
      }),
    ),
  )

  return (
    <ServicePopover
      {...props}
      loading={items.loading}
      ready={
        props.service.type === "plugins"
          ? loaded()
          : data().location.skill.list({ directory: props.directory }) !== undefined
      }
      empty={list().length === 0}
      error={items.error}
      retry={refetch}
    >
      <Show
        when={list().length}
        fallback={
          <ServiceEmpty
            session={props.session}
            title={ctx.t(props.service.type === "plugins" ? "plugins.empty" : "skills.empty")}
            directory={props.directory}
            service={props.service.type}
          />
        }
      >
        <h3 class="session-service-title">
          {ctx.t(props.service.type === "plugins" ? "plugins.configured" : "skills.configured")}
        </h3>
        <For each={list()}>
          {(item) => (
            <div class="session-service-row" title={item.error ?? item.name}>
              <span class="session-service-dot" data-status={item.status} aria-hidden="true" />
              <span dir="auto" class="session-summary-label">
                {item.name}
              </span>
              <Show when={item.status === "failed"}>
                <span class="session-service-status">{ctx.t("failed")}</span>
              </Show>
            </div>
          )}
        </For>
        <div class="session-service-footer">
          <ServiceConfigLink session={props.session} directory={props.directory} service={props.service.type} />
        </div>
      </Show>
    </ServicePopover>
  )
}

type ServiceBodyProps = {
  loading: boolean
  ready: boolean
  error: unknown
  retry: () => void
  children: JSX.Element
}

function ServicePopover(props: ServiceMenuProps & ServiceBodyProps & { empty: boolean }) {
  const ctx = useExtension()
  const locale = ctx.locale
  const drawer = useDrawer()

  const placement = createMemo(() =>
    props.mobile ? "top-end" : locale.direction() === "rtl" ? "right-start" : "left-start",
  )

  // In a narrow-screen drawer the service list replaces the drawer's view instead of opening a popover over it.
  if (props.mobile && drawer) {
    const content = children(() => (
      <div
        class="session-summary-card session-service-drawer"
        data-service={props.service.type}
        aria-busy={props.loading}
      >
        <ServiceBody {...props} />
      </div>
    ))

    return (
      <button
        type="button"
        class="session-summary-row"
        onClick={(event) => {
          if (!props.loading) void props.retry()
          drawer.open({ title: ctx.t(props.service.label), content: content(), trigger: event.currentTarget })
        }}
      >
        <Icon name={props.service.icon} class="shrink-0 text-v2-icon-icon-muted" />
        <span class="session-summary-label">{ctx.t(props.service.label)}</span>
        <Icon name="chevron-right" class="session-summary-menu-indicator shrink-0 text-v2-icon-icon-muted" />
      </button>
    )
  }

  return (
    <Popover
      open={props.open}
      onOpenChange={(open) => {
        props.onOpenChange(open)

        if (open && !props.loading) void props.retry()
      }}
      placement={placement()}
      gutter={4}
      overflowPadding={16}
      modal={false}
    >
      <Popover.Trigger as="button" type="button" class="session-summary-row">
        <Icon name={props.service.icon} class="shrink-0 text-v2-icon-icon-muted" />
        <span class="session-summary-label">{ctx.t(props.service.label)}</span>
        <Icon name="fill-triangle-down" class="session-summary-menu-indicator shrink-0 text-v2-icon-icon-muted" />
      </Popover.Trigger>
      <Popover.Portal>
        <Popover.Content
          class="session-service-menu"
          data-service={props.service.type}
          data-empty={(props.ready && !props.error && props.empty) || undefined}
          aria-busy={props.loading}
          aria-label={ctx.t(props.service.label)}
        >
          <ServiceBody {...props} />
        </Popover.Content>
      </Popover.Portal>
    </Popover>
  )
}

function ServiceBody(props: ServiceBodyProps) {
  const ctx = useExtension()

  return (
    <Show
      when={props.ready || !props.loading}
      fallback={
        <div class="session-service-message" role="status">
          {ctx.t("common.loading")}
        </div>
      }
    >
      <Show
        when={!props.error}
        fallback={
          <div class="session-service-message" role="alert">
            <p>{ctx.t("common.requestFailed")}</p>
            <button type="button" class="session-summary-row" onClick={() => props.retry()}>
              {ctx.t("retry")}
            </button>
          </div>
        }
      >
        {props.children}
      </Show>
    </Show>
  )
}

function ServiceConfigLink(props: { session: MountedSession; directory: string; service: Service }) {
  const ctx = useExtension()
  const desktop = ctx.desktop
  const system = ctx.system
  const local = () => props.session.server.local
  const [store, setStore] = createStore({ opening: false, copied: false })
  const label = () => ctx.t(local() ? "configure" : "copyConfigPath")
  // Clears the copied mark two seconds after the latest copy.
  let reset: ReturnType<typeof setTimeout> | undefined

  onCleanup(() => clearTimeout(reset))

  const activate = async () => {
    if (store.opening || (local() && !desktop)) return
    setStore({ opening: true, copied: false })
    const directory = props.directory
    await props.session.server.client.config
      .get({ location: { directory } })
      .then(async (entries) => {
        const documents = entries
          .filter((entry) => entry.type === "document")
          .filter((entry) => entry.path !== undefined && /\.jsonc?$/.test(entry.path))

        const path =
          documents.findLast((entry) => entry.info[props.service] !== undefined)?.path ?? documents.at(-1)?.path

        if (!local()) {
          if (!path) throw new Error(ctx.t("configFileMissing"))
          await system.copy(path)
          setStore("copied", true)
          clearTimeout(reset)
          reset = setTimeout(() => setStore("copied", false), 2000)

          return
        }

        if (path && (await desktop?.reveal(path))) return
        await desktop?.launch(path ? getDirectory(path) : directory)
      })
      .catch((error) =>
        showToast({
          variant: "error",
          title: ctx.t("common.requestFailed"),
          description: error instanceof Error ? error.message : String(error),
        }),
      )
      .finally(() => setStore("opening", false))
  }

  return (
    <>
      <span class="session-service-config-separator" role="separator" />
      <Show
        when={!local() || desktop}
        fallback={
          <span class="session-service-row">
            <Icon name="settings-gear" class="shrink-0 text-v2-icon-icon-muted" />
            {label()}
          </span>
        }
      >
        <Tooltip
          inactive={local()}
          value={ctx.t(store.copied ? "ui.message.copied" : "ui.message.copy")}
          placement="top"
          getAnchorRect={(anchor) => anchor?.querySelector("svg")?.getBoundingClientRect()}
          forceOpen={store.copied ? true : undefined}
          class="w-full"
        >
          <button
            type="button"
            class="session-service-config"
            disabled={store.opening}
            onMouseDown={(event) => {
              if (!local()) event.preventDefault()
            }}
            onClick={() => void activate()}
          >
            <Icon
              name={local() ? "settings-gear" : store.copied ? "check" : "outline-copy"}
              class="shrink-0 text-v2-icon-icon-muted"
            />
            <span class="session-summary-label">{label()}</span>
            <Show when={local()}>
              <Icon name="arrow-up-right" class="session-service-config-arrow shrink-0" />
            </Show>
          </button>
        </Tooltip>
      </Show>
    </>
  )
}

function ServiceEmpty(props: { session: MountedSession; title: string; directory: string; service: Service }) {
  return (
    <div class="session-service-empty">
      <strong>{props.title}</strong>
      <div class="session-service-footer">
        <ServiceConfigLink session={props.session} directory={props.directory} service={props.service} />
      </div>
    </div>
  )
}

function pluginLabel(plugin: PluginInfo) {
  if (plugin.id) return plugin.id

  if (plugin.source.type === "package") return plugin.source.target

  if (plugin.source.type === "local") return plugin.source.path

  return plugin.source.type
}

import { Menu } from "@opencode/ui/menu"
import { Icon } from "@opencode/ui/icon"
import { showToast } from "@opencode/ui/toast"
import { comparablePath, containsDirectory, getFilename, sameDirectory } from "@opencode/util/path"
import { createStore } from "solid-js/store"
import { For, onCleanup, Show, type ComponentProps, type JSX } from "solid-js"
import { createKeyed, useExtension, type Project, type MountedSession } from "../sdk"
import { workspaceDirectories } from "./paths"

export function SessionWorkspaceMenu(props: {
  session: MountedSession
  project: Project
  directory: string
  placement?: ComponentProps<typeof Menu>["placement"]
  class?: string
  children: JSX.Element
}) {
  const ctx = useExtension()
  const data = () => props.session.server.data

  const [store, setStore] = createStore<{ selected: string | undefined; directories: string[] }>({
    selected: undefined,
    directories: workspaceDirectories(props.project),
  })

  const blocked = () => data().session.status(props.session.id) === "running"
  const currentWorkspace = () => store.directories.find((workspace) => containsDirectory(workspace, props.directory))

  const workspaces = () =>
    store.directories.filter(
      (workspace) => comparablePath(workspace) !== comparablePath(currentWorkspace() ?? props.directory),
    )

  const update = (items: readonly { directory: string }[]) =>
    setStore(
      "directories",
      items.flatMap((item) => (sameDirectory(props.project.worktree, item.directory) ? [] : [item.directory])),
    )

  createKeyed(data, (current) =>
    onCleanup(
      current.on("worktree.updated", (event) => {
        if (event.data.projectID !== props.project.id) return
        void props.session.server.client.worktree
          .list({ projectID: props.project.id })
          .then(update)
          .catch(() => undefined)
      }),
    ),
  )

  const onOpenChange = (open: boolean) => {
    if (!open) return
    const client = props.session.server.client
    void client.worktree
      .list({ projectID: props.project.id })
      .then(update)
      .then(() => client.worktree.refresh({ projectID: props.project.id }))
      .catch(() => undefined)
  }

  const createWorktree = async (client: MountedSession["server"]["client"], directory: string) => {
    const project =
      data().location.info({ directory })?.project ?? (await client.location.get({ location: { directory } })).project

    const created = await client.worktree.create({ projectID: project.id, from: project.canonical })
    // Populate the client cache before the destination session mounts.
    await data().location.syncInfo({ directory: created.directory })

    return created.directory
  }

  const move = async (selection: "create" | string) => {
    if (store.selected || blocked()) return
    const client = props.session.server.client
    const sessionID = props.session.id
    setStore("selected", selection)

    try {
      const destination = selection === "create" ? await createWorktree(client, props.directory) : selection

      if (!destination) return

      await client.session.move({ sessionID, directory: destination })
    } catch (error) {
      showToast({
        variant: "error",
        title: ctx.t("move.failed"),
        description: error instanceof Error ? error.message : ctx.t("common.requestFailed"),
      })
    } finally {
      setStore("selected", undefined)
    }
  }

  return (
    <Menu
      placement={props.placement ?? "bottom-end"}
      gutter={4}
      overflowPadding={24}
      modal={false}
      onOpenChange={onOpenChange}
    >
      <Menu.Trigger class={props.class} disabled={blocked()}>
        {props.children}
      </Menu.Trigger>
      <Menu.Portal>
        <Menu.Content class="w-[200px]">
          <Menu.Group>
            <Menu.GroupLabel>{ctx.t("move.menu")}</Menu.GroupLabel>
            <Show when={comparablePath(props.directory) !== comparablePath(props.project.worktree)}>
              <Menu.Item disabled={!!store.selected || blocked()} onSelect={() => void move(props.project.worktree)}>
                <Icon name="monitor" />
                {ctx.t("workspace.local")}
              </Menu.Item>
            </Show>
            <Menu.Item disabled={!!store.selected || blocked()} onSelect={() => void move("create")}>
              <Icon name="plus" />
              {ctx.t("workspace.new")}
            </Menu.Item>
            <Show when={workspaces().length > 0}>
              <Menu.Sub gutter={0} overlap overflowPadding={24}>
                <Menu.SubTrigger>
                  <Icon name="outline-worktree" />
                  {ctx.t("workspace.existing")}
                </Menu.SubTrigger>
                <Menu.Portal>
                  <Menu.SubContent class="max-h-[66.667dvh] w-[200px] overflow-y-auto !pb-0 [&>[data-component=menu-v2-item]:last-child]:mb-0.5 [@media(max-height:600px)]:max-h-[calc(100dvh-48px)]">
                    <For each={workspaces()}>
                      {(workspace) => (
                        <Menu.Item disabled={!!store.selected || blocked()} onSelect={() => void move(workspace)}>
                          <Icon name="outline-worktree" />
                          <span class="min-w-0 flex-1 truncate">{getFilename(workspace)}</span>
                        </Menu.Item>
                      )}
                    </For>
                  </Menu.SubContent>
                </Menu.Portal>
              </Menu.Sub>
            </Show>
          </Menu.Group>
        </Menu.Content>
      </Menu.Portal>
    </Menu>
  )
}

import {
  createMemo,
  createSignal,
  ErrorBoundary,
  For,
  Match,
  onCleanup,
  Show,
  Switch,
  untrack,
  type JSX,
} from "solid-js"
import { createStore } from "solid-js/store"
import { Dynamic } from "solid-js/web"
import { makeEventListener } from "@solid-primitives/event-listener"
import { createResizeObserver } from "@solid-primitives/resize-observer"
import { Button } from "@opencode/ui/button"
import { FileIcon } from "@opencode/ui/file-icon"
import { SegmentedControl, SegmentedControlItem } from "@opencode/ui/segmented-control"
import { ScrollView } from "@opencode/ui/scroll-view"
import { Markdown } from "@opencode/session-ui/markdown"
import { MarkdownProvider, useMarkdown } from "@opencode/session-ui/context/markdown"
import { artifactKind, type ArtifactKind } from "@opencode/util/artifact"
import { getDirectory, getFilename } from "@opencode/util/path"
import { createKeyed, useExtension, type FileContent, type MountedSession } from "../sdk"
import { blobUrlFromContent, bytesFromContent, contentBytes, parseDelimited, resolveArtifactPath } from "./artifact"
import { current, useShared } from "./context"
import { FileViewer } from "./contract"
import { workspaceFileUrl } from "./path"

type ArtifactMode = "preview" | "source"

/** Facts a viewer learns from the decoded media, shown in the toolbar. */
type ArtifactInfo = {
  width?: number
  height?: number
  duration?: number
  rows?: number
  columns?: number
  /** Facts an extension's viewer reports, already localized. */
  details?: readonly string[]
}

type ViewerState = {
  readonly mode: ArtifactMode
  readonly info: ArtifactInfo
  readonly undecodable: boolean
  /** Why the file shows as binary, when a viewer said. */
  readonly reason?: string
}

type MediaProps = {
  path: string
  content: FileContent
  onInfo: (info: ArtifactInfo) => void
  /** The browser could not decode the bytes; the host falls back to the binary placeholder. */
  onError: () => void
}

/** Kinds that render a preview from their text and can toggle back to highlighted source. */
const previewableKinds: readonly ArtifactKind[] = ["svg", "html", "markdown", "mermaid", "table"]

/**
 * Renders a loaded non-text file: media, documents, and data get a dedicated viewer with a toolbar;
 * previewable text kinds can switch to `source`, which the host supplies (its code view).
 */
export default function ArtifactView(props: {
  session: MountedSession
  path: string
  content: FileContent
  cacheKey?: string
  source: JSX.Element
}) {
  const ctx = useExtension()
  const locale = ctx.locale
  // Media the browser could not decode falls back to the binary placeholder.
  const initial: ViewerState = { mode: "preview", info: {}, undecodable: false }
  // The viewer state belongs to one loaded content: a reloaded file starts from the preview again.
  const [saved, setSaved] = createSignal({ ...initial, content: props.content })

  const state = () => {
    const value = saved()

    return value.content === props.content ? value : initial
  }

  const change = (next: Partial<ViewerState>) => setSaved({ ...state(), ...next, content: props.content })

  const kind = createMemo<ArtifactKind | "binary">(() => {
    if (props.content.type === "binary" && !props.content.mimeType) return "binary"

    if (state().undecodable) return "binary"

    return artifactKind(props.path)
  })

  const previewable = createMemo(() => {
    const value = kind()

    return value !== "binary" && previewableKinds.includes(value)
  })

  const table = createMemo(() =>
    kind() === "table"
      ? parseDelimited(props.content.content, props.path.toLowerCase().endsWith(".tsv") ? "\t" : ",")
      : undefined,
  )

  const meta = createMemo(() => {
    const parsed = table()
    const info: ArtifactInfo = parsed ? { rows: parsed.total, columns: parsed.columns } : state().info

    return [
      info.width && info.height ? `${info.width} × ${info.height}` : undefined,
      info.duration ? formatDuration(info.duration) : undefined,
      info.rows !== undefined ? ctx.plural("view.table.rows", Math.max(0, info.rows - 1)) : undefined,
      info.columns !== undefined ? ctx.plural("view.table.columns", info.columns) : undefined,
      ...(info.details ?? []),
      formatBytes(locale.locale(), contentBytes(props.content)),
    ].filter((item): item is string => !!item)
  })

  // A file that fails also drops the facts its viewer reported, such as a page count.
  const fail = (reason?: string) => change({ undecodable: true, info: {}, reason })

  const media = { onInfo: (info: ArtifactInfo) => change({ info }), onError: () => fail() }

  const size = () => formatBytes(locale.locale(), contentBytes(props.content))

  // A kind the file view does not render itself goes to the first extension viewer that lists it.
  const viewer = createMemo(() => {
    const value = kind()

    return value === "binary" ? undefined : ctx.list(FileViewer).find((item) => item.kinds.includes(value))
  })

  const rendered = () => (
    <ScrollView class="min-h-0 flex-1">
      <Show
        when={kind() === "markdown"}
        fallback={<ArtifactMermaid text={props.content.content} cacheKey={props.cacheKey} />}
      >
        <ArtifactMarkdown
          session={props.session}
          path={props.path}
          text={props.content.content}
          cacheKey={props.cacheKey}
        />
      </Show>
    </ScrollView>
  )

  return (
    <>
      <ArtifactToolbar
        mode={state().mode}
        onModeChange={previewable() ? (mode) => change({ mode }) : undefined}
        meta={meta()}
        actions={
          <Show when={kind() === "html"}>
            <OpenInBrowserButton session={props.session} path={props.path} />
          </Show>
        }
      />
      <Show when={!previewable() || state().mode === "preview"} fallback={props.source}>
        <Switch fallback={<ArtifactBinary path={props.path} size={size()} reason={state().reason} />}>
          <Match when={kind() === "image" || kind() === "svg"}>
            <ArtifactImage path={props.path} content={props.content} {...media} />
          </Match>
          <Match when={kind() === "video"}>
            <ArtifactVideo path={props.path} content={props.content} {...media} />
          </Match>
          <Match when={kind() === "audio"}>
            <ArtifactAudio path={props.path} content={props.content} {...media} />
          </Match>
          <Match when={kind() === "pdf" || kind() === "html"}>
            <ArtifactFrame path={props.path} content={props.content} kind={kind() === "pdf" ? "pdf" : "html"} />
          </Match>
          <Match when={kind() === "font"}>
            <ArtifactFont path={props.path} content={props.content} />
          </Match>
          <Match when={table()}>{(parsed) => <ArtifactTable parsed={parsed()} />}</Match>
          <Match when={kind() === "markdown" || kind() === "mermaid"}>{rendered()}</Match>
          {/* Keyed, so another viewer for the file mounts with bytes of its own. */}
          <Match when={viewer()} keyed>
            {(viewer) => (
              <ArtifactViewer
                viewer={viewer}
                path={props.path}
                size={size()}
                content={props.content}
                onDetails={(details) => change({ info: { details } })}
                onError={fail}
              />
            )}
          </Match>
        </Switch>
      </Show>
    </>
  )
}

function formatBytes(locale: string, bytes: number) {
  const units = ["byte", "kilobyte", "megabyte", "gigabyte"] as const
  const index = Math.min(units.length - 1, bytes > 0 ? Math.floor(Math.log10(bytes) / 3) : 0)
  const value = bytes / 1000 ** index

  return new Intl.NumberFormat(locale, {
    style: "unit",
    unit: units[index],
    // "short" bytes render as the singular "byte"; the long form pluralizes correctly.
    unitDisplay: index === 0 ? "long" : "short",
    maximumFractionDigits: value >= 100 || index === 0 ? 0 : 1,
  }).format(value)
}

function formatDuration(seconds: number) {
  const total = Math.round(seconds)
  const minutes = Math.floor(total / 60)

  return `${minutes}:${String(total % 60).padStart(2, "0")}`
}

function ArtifactToolbar(props: {
  mode?: ArtifactMode
  onModeChange?: (mode: ArtifactMode) => void
  meta: string[]
  actions?: JSX.Element
}) {
  const ctx = useExtension()

  return (
    <div data-slot="artifact-toolbar" class="flex h-10 shrink-0 items-center gap-3 px-4">
      <Show when={props.onModeChange}>
        <SegmentedControl
          value={props.mode ?? "preview"}
          onChange={(value) => {
            if (value === "preview" || value === "source") props.onModeChange?.(value)
          }}
        >
          <SegmentedControlItem value="preview">{ctx.t("view.preview")}</SegmentedControlItem>
          <SegmentedControlItem value="source">{ctx.t("view.source")}</SegmentedControlItem>
        </SegmentedControl>
      </Show>
      <div class="ms-auto flex min-w-0 items-center gap-3">
        <div class="flex min-w-0 items-center gap-2 text-12-regular text-text-weak">
          <For each={props.meta}>
            {(item, index) => (
              <>
                <Show when={index() > 0}>
                  <span aria-hidden class="text-text-faint">
                    ·
                  </span>
                </Show>
                <span class="truncate tabular-nums">{item}</span>
              </>
            )}
          </For>
        </div>
        {props.actions}
      </div>
    </div>
  )
}

/** Shows only while the browser pane is active and can load the file. */
function OpenInBrowserButton(props: { session: MountedSession; path: string }) {
  const ctx = useExtension()
  const shared = useShared()

  const pane = () => {
    const browser = current(shared.browser())

    return browser?.canOpen(props.session, props.path) ? browser : undefined
  }

  return (
    <Show when={pane()}>
      {(browser) => (
        <Button
          size="small"
          variant="ghost"
          icon="globe"
          onClick={() => {
            // The screen's workspace root, read when the user acts.
            const root = ctx.screen.current()?.file.root

            if (root !== undefined) browser().open(props.session, workspaceFileUrl(root, props.path))
          }}
        >
          {ctx.t("view.openInBrowser")}
        </Button>
      )}
    </Show>
  )
}

function createBlobUrl(content: () => FileContent) {
  return createMemo(() => {
    const value = blobUrlFromContent(content())
    onCleanup(() => URL.revokeObjectURL(value))

    return value
  })
}

/** Images and SVG previews: each decoded image owns its viewport. */
function ArtifactImage(props: MediaProps) {
  const url = createBlobUrl(() => props.content)

  return (
    <Show when={url()} keyed>
      {(src) => <ImageStage {...props} src={src} />}
    </Show>
  )
}

function ImageStage(props: MediaProps & { src: string }) {
  const ctx = useExtension()

  const [view, setView] = createStore({
    width: 0,
    height: 0,
    imageWidth: 0,
    imageHeight: 0,
    zoom: 1,
    x: 0,
    y: 0,
    dragging: false,
  })

  const fit = () =>
    Math.min(
      1,
      Math.max(1, view.width - 48) / (view.imageWidth || 1),
      Math.max(1, view.height - 48) / (view.imageHeight || 1),
    )

  const bound = (offset: number, image: number, zoom: number) => {
    // Keep the fitted footprint covered, including its letterboxing. Clamping to
    // the stage edges instead would move the anchor during small pinch increments.
    const limit = (image * fit() * (zoom - 1)) / 2

    return Math.max(-limit, Math.min(limit, offset))
  }

  const x = () => bound(view.x, view.imageWidth, view.zoom)
  const y = () => bound(view.y, view.imageHeight, view.zoom)
  const reset = () => setView({ zoom: 1, x: 0, y: 0 })

  const pan = (left: number, top: number) =>
    setView({ x: bound(left, view.imageWidth, view.zoom), y: bound(top, view.imageHeight, view.zoom) })

  let stage: HTMLDivElement | undefined
  let drag: { id: number; clientX: number; clientY: number; x: number; y: number } | undefined
  let dragged = false

  const cursor = () => {
    if (view.zoom === 1) return undefined

    return view.dragging ? "grabbing" : "grab"
  }

  const endDrag = (event: PointerEvent) => {
    if (event.pointerId !== drag?.id) return

    drag = undefined
    setView("dragging", false)
  }

  const zoomAt = (zoom: number, clientX: number, clientY: number) => {
    if (!stage) return

    const rect = stage.getBoundingClientRect()
    const next = Math.max(1, Math.min(Math.max(8, 1 / fit()), zoom))
    const ratio = next / view.zoom
    const anchor = { x: clientX - rect.left - rect.width / 2, y: clientY - rect.top - rect.height / 2 }
    setView({
      zoom: next,
      x: bound(anchor.x - (anchor.x - x()) * ratio, view.imageWidth, next),
      y: bound(anchor.y - (anchor.y - y()) * ratio, view.imageHeight, next),
    })
  }

  createResizeObserver(
    () => stage,
    () => {
      if (!stage) return

      setView({ width: stage.clientWidth, height: stage.clientHeight })
      setView({ x: x(), y: y() })
    },
  )

  return (
    <div
      ref={stage}
      data-slot="artifact-stage"
      data-checker
      data-zoom={view.zoom === 1 ? "fit" : "actual"}
      data-overflow={fit() < 1 || undefined}
      class="relative min-h-0 flex-1 overflow-hidden"
      on:wheel={(event) => {
        if (!view.imageWidth || (!event.ctrlKey && view.zoom === 1)) return

        // Chromium delivers trackpad pinch as Ctrl-wheel. Consume it here before
        // Desktop's window-level zoom handler; ordinary fitted scrolling stays native.
        event.preventDefault()
        event.stopPropagation()
        const unit = [1, 16, view.height][event.deltaMode] ?? 1

        if (event.ctrlKey) {
          zoomAt(view.zoom * Math.exp((-event.deltaY * unit) / 100), event.clientX, event.clientY)

          return
        }

        // Use the OS's trackpad momentum directly, with no second animation loop.
        pan(x() - event.deltaX * unit, y() - event.deltaY * unit)
      }}
    >
      <img
        data-slot="artifact-media"
        src={props.src}
        alt={getFilename(props.path)}
        draggable={false}
        class="absolute left-1/2 top-1/2 select-none"
        style={{
          width: view.imageWidth ? `${view.imageWidth * fit()}px` : undefined,
          height: view.imageHeight ? `${view.imageHeight * fit()}px` : undefined,
          "max-width": "none",
          "max-height": "none",
          transform: `translate(-50%, -50%) translate(${x()}px, ${y()}px) scale(${view.zoom})`,
          "touch-action": view.zoom > 1 ? "none" : "auto",
          cursor: cursor(),
        }}
        onPointerDown={(event) => {
          if (!event.isPrimary || event.button !== 0) return

          dragged = false

          if (view.zoom === 1) return

          drag = { id: event.pointerId, clientX: event.clientX, clientY: event.clientY, x: x(), y: y() }
          event.currentTarget.setPointerCapture(event.pointerId)
          setView("dragging", true)
        }}
        onPointerMove={(event) => {
          if (!drag || drag.id !== event.pointerId) return

          const dx = event.clientX - drag.clientX
          const dy = event.clientY - drag.clientY

          if (!dragged && Math.hypot(dx, dy) < 3) return

          dragged = true
          pan(drag.x + dx, drag.y + dy)
        }}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        onLostPointerCapture={endDrag}
        onError={() => props.onError()}
        onLoad={(event) => {
          const image = event.currentTarget
          const width = image.naturalWidth || image.width || image.clientWidth || 300
          const height = image.naturalHeight || image.height || image.clientHeight || 150

          setView({
            imageWidth: width,
            imageHeight: height,
            width: stage?.clientWidth ?? 0,
            height: stage?.clientHeight ?? 0,
          })
          props.onInfo({ width, height })
        }}
        onClick={(event) => {
          if (dragged) {
            dragged = false

            return
          }

          if (view.zoom > 1) return reset()

          zoomAt(1 / fit(), event.clientX, event.clientY)
        }}
      />
      <div class="absolute end-3 top-3">
        <Button size="small" variant="neutral" disabled={view.zoom === 1} onClick={reset}>
          {ctx.t("view.fit")}
        </Button>
      </div>
    </div>
  )
}

function ArtifactVideo(props: MediaProps) {
  const ctx = useExtension()
  const url = createBlobUrl(() => props.content)
  // Fullscreen belongs to one video: a new file starts fitted in the pane.
  const [expandedUrl, setExpandedUrl] = createSignal<string>()
  const [paused, setPaused] = createSignal(true)
  const [active, setActive] = createSignal(false)
  const [box, setBox] = createStore({ left: 0, top: 0, ready: false })
  const expanded = () => expandedUrl() === url()

  let stage: HTMLDivElement | undefined
  let video: HTMLVideoElement | undefined
  let idleTimer: ReturnType<typeof setTimeout> | undefined

  const clearIdle = () => {
    if (idleTimer !== undefined) clearTimeout(idleTimer)
    idleTimer = undefined
  }

  const wake = () => {
    setActive(true)
    clearIdle()
    idleTimer = setTimeout(() => setActive(false), 2500)
  }

  onCleanup(clearIdle)

  const close = () => setExpandedUrl(undefined)
  const toggle = () => setExpandedUrl(expanded() ? undefined : url())

  const measure = () => {
    if (!video || video.offsetWidth === 0 || video.offsetHeight === 0) return

    // Chromium's media controls place the 48x48 fullscreen slot 48px from the right edge (beside the
    // 48px overflow button) and 24px above the bottom edge (above the 24px timeline scrubber).
    setBox({
      left: video.offsetLeft + video.offsetWidth - 96,
      top: video.offsetTop + video.offsetHeight - 72,
      ready: true,
    })
  }

  createResizeObserver(
    () => [stage, video],
    () => measure(),
  )

  // Top-layer promotion escapes the side panel's stacking context and <main>'s content containment
  // while keeping the same <video> element mounted so playback never resets.
  createKeyed(expanded, (open) => {
    const el = stage

    if (!el || !open) return

    el.setAttribute("popover", "manual")
    el.showPopover?.()
    measure()

    makeEventListener(
      window,
      "keydown",
      (event: KeyboardEvent) => {
        if (event.key !== "Escape") return

        event.preventDefault()
        event.stopPropagation()
        close()
      },
      { capture: true },
    )

    onCleanup(() => {
      if (el.isConnected) el.hidePopover?.()
      el.removeAttribute("popover")
      measure()
    })
  })

  const label = () => ctx.t(expanded() ? "view.exitFullscreen" : "view.fullscreen")
  const controlsVisible = () => paused() || active()

  return (
    <div
      ref={stage}
      data-slot="artifact-stage"
      data-zoom="fit"
      data-expanded={expanded() ? "" : undefined}
      class="relative min-h-0 flex-1 overflow-hidden"
      onPointerMove={wake}
      onPointerLeave={() => {
        clearIdle()
        setActive(false)
      }}
    >
      <div
        classList={{
          "absolute inset-0 flex items-center justify-center p-6": !expanded(),
          "absolute inset-0 flex items-center justify-center px-8 pt-12 pb-8": expanded(),
        }}
        onClick={(event) => {
          if (expanded() && event.target === event.currentTarget) close()
        }}
      >
        <video
          ref={video}
          data-slot="artifact-media"
          class="w-full bg-black"
          controls
          preload="metadata"
          playsinline
          onError={() => props.onError()}
          src={url()}
          onClick={(event) => {
            // Chromium's controls answer the second click of a double click with a native fullscreen request, which
            // covers the theatre the double click opens. Opting out with controlslist="nofullscreen" would also end
            // their click-to-play. The fullscreen element ready check refuses an open popover, so the video is one
            // while its controls handle this click, and is released before the next frame renders.
            const el = event.currentTarget

            // In native fullscreen, the controls' own exit must run; showPopover would throw there.
            if (event.detail < 2 || document.fullscreenElement === el) return
            el.setAttribute("popover", "manual")
            el.showPopover?.()
            requestAnimationFrame(() => el.removeAttribute("popover"))
          }}
          onDblClick={toggle}
          onPlay={() => setPaused(false)}
          onPause={() => setPaused(true)}
          onEnded={() => setPaused(true)}
          onLoadedMetadata={(event) => {
            const el = event.currentTarget
            setPaused(el.paused)
            props.onInfo({ width: el.videoWidth, height: el.videoHeight, duration: el.duration })
            measure()
          }}
        />
        <button
          type="button"
          data-slot="artifact-video-fullscreen"
          aria-label={label()}
          aria-pressed={expanded()}
          title={label()}
          onClick={toggle}
          style={box.ready ? { left: `${box.left}px`, top: `${box.top}px` } : { right: "72px", bottom: "48px" }}
          classList={{
            "absolute z-10 flex size-12 items-center justify-center transition-opacity focus-visible:opacity-100 focus-visible:outline-none":
              true,
            "opacity-100": controlsVisible(),
            "pointer-events-none opacity-0": !controlsVisible(),
          }}
        >
          <span class="flex size-9 items-center justify-center rounded-full transition-colors">
            <Show
              when={expanded()}
              fallback={
                <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
                  <path
                    d="M3 6V3H6M10 3H13V6M13 10V13H10M6 13H3V10"
                    stroke="currentColor"
                    stroke-width="1.5"
                    stroke-linecap="square"
                  />
                </svg>
              }
            >
              <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
                <path
                  d="M3 5.5H5.5V3M13 5.5H10.5V3M10.5 13V10.5H13M5.5 13V10.5H3"
                  stroke="currentColor"
                  stroke-width="1.5"
                  stroke-linecap="square"
                />
              </svg>
            </Show>
          </span>
        </button>
      </div>
    </div>
  )
}

function ArtifactAudio(props: MediaProps) {
  const url = createBlobUrl(() => props.content)

  return (
    <div data-slot="artifact-stage" class="relative min-h-0 flex-1 overflow-auto">
      <div class="absolute inset-0 flex items-center justify-center p-6">
        <div class="flex w-full max-w-lg flex-col items-center gap-5 rounded-xl border border-v2-border-border-muted bg-v2-background-bg-base px-8 py-8 shadow-[var(--v2-elevation-raised)]">
          <div class="flex size-14 items-center justify-center rounded-full bg-v2-background-bg-layer-02">
            <FileIcon node={{ path: props.path, type: "file" }} class="size-7" />
          </div>
          <div class="max-w-full truncate text-14-medium text-text-strong">{getFilename(props.path)}</div>
          <audio
            class="w-full"
            onError={() => props.onError()}
            controls
            preload="metadata"
            src={url()}
            onLoadedMetadata={(event) => props.onInfo({ duration: event.currentTarget.duration })}
          />
        </div>
      </div>
    </div>
  )
}

function ArtifactFrame(props: { path: string; content: FileContent; kind: "pdf" | "html" }) {
  const url = createBlobUrl(() => props.content)
  // PDF Open Parameters: start with the thumbnail pane closed and the page fitted to the pane width.
  const src = () => (props.kind === "pdf" ? `${url()}#navpanes=0&view=FitH` : url())

  return (
    <iframe
      class="block h-full w-full flex-1 border-0 bg-white"
      title={getFilename(props.path)}
      src={src()}
      // The PDF viewer is Chromium's own and does not run in a sandboxed frame. HTML runs as an
      // opaque origin: no app storage, cookies, or credentialed requests reach it.
      sandbox={props.kind === "html" ? "allow-scripts allow-popups allow-forms allow-modals" : undefined}
      referrerPolicy="no-referrer"
    />
  )
}

function ArtifactMarkdown(props: { session: MountedSession; path: string; text: string; cacheKey?: string }) {
  const ctx = useExtension()
  const links = ctx.links
  const parent = useMarkdown()
  // getDirectory yields "/" for a root-level file, which would make relative links absolute.
  const dir = createMemo(() => (props.path.includes("/") || props.path.includes("\\") ? getDirectory(props.path) : ""))
  // Absolute references bypass the file's directory; relative ones resolve against it.
  const resolve = (href: string) => (/^([a-z]:)?\//i.test(href) ? href : (resolveArtifactPath(dir(), href) ?? href))

  return (
    <MarkdownProvider
      readImage={(src, signal) => parent?.readImage?.(resolve(src), signal) ?? Promise.resolve(undefined)}
      openLocalFile={(href) => void links.open({ href, base: dir(), session: props.session })}
      localFileExists={(href) => untrack(() => links.exists({ href, base: dir(), session: props.session }))}
    >
      <div class="mx-auto w-full max-w-3xl px-8 py-6">
        <Markdown text={props.text} cacheKey={props.cacheKey} />
      </div>
    </MarkdownProvider>
  )
}

