type ScrollPos = { x: number; y: number }

type ScrollSyncState = { scroll?: HTMLDivElement; scrollFrame?: number; restoreFrame?: number; pending?: ScrollPos }

type NoteState = { openedComment: string | null; commenting: LineRange | null; selected: LineRange | null }

type FindState = { find: FileSearchHandle | null }

function createScrollSync(input: { get: () => ScrollPos | undefined; set: (pos: ScrollPos) => void }) {
  const state: ScrollSyncState = {}
  const [code, setCode] = createSignal<HTMLElement[]>([])

  const getCode = () => {
    const el = state.scroll

    if (!el) return []

    const host = el.querySelector("diffs-container")

    if (!(host instanceof HTMLElement)) return []

    const root = host.shadowRoot

    if (!root) return []

    return Array.from(root.querySelectorAll("[data-code]")).filter(
      (node): node is HTMLElement => node instanceof HTMLElement && node.clientWidth > 0,
    )
  }

  const save = (next: ScrollPos) => {
    state.pending = next

    if (state.scrollFrame !== undefined) return

    state.scrollFrame = requestAnimationFrame(() => {
      state.scrollFrame = undefined

      const out = state.pending
      state.pending = undefined

      if (!out) return

      input.set(out)
    })
  }

  const onCodeScroll = (event: Event) => {
    const el = state.scroll

    if (!el) return

    const target = event.currentTarget

    if (!(target instanceof HTMLElement)) return

    save({
      x: target.scrollLeft,
      y: el.scrollTop,
    })
  }

  const sync = () => {
    const next = getCode()
    const current = code()

    if (next.length === current.length && next.every((el, i) => el === current[i])) return
    setCode(next)
  }

  const restore = () => {
    const el = state.scroll

    if (!el) return

    const pos = input.get()

    if (!pos) return

    sync()

    if (code().length > 0) {
      for (const item of code()) {
        if (item.scrollLeft !== pos.x) item.scrollLeft = pos.x
      }
    }

    if (el.scrollTop !== pos.y) el.scrollTop = pos.y

    if (code().length > 0) return

    if (el.scrollLeft !== pos.x) el.scrollLeft = pos.x
  }

  const queueRestore = () => {
    if (state.restoreFrame !== undefined) return

    state.restoreFrame = requestAnimationFrame(() => {
      state.restoreFrame = undefined
      restore()
    })
  }

  const handleScroll = (event: Event & { currentTarget: HTMLDivElement }) => {
    if (code().length === 0) sync()

    save({
      x: code()[0]?.scrollLeft ?? event.currentTarget.scrollLeft,
      y: event.currentTarget.scrollTop,
    })
  }

  // The diff's code columns scroll on their own; listen to the ones on screen.
  createKeyed(code, (items) => items.forEach((item) => makeEventListener(item, "scroll", onCodeScroll)))

  const setViewport = (el: HTMLDivElement) => {
    state.scroll = el
    restore()
  }

  onCleanup(() => {
    if (state.scrollFrame !== undefined) cancelAnimationFrame(state.scrollFrame)

    if (state.restoreFrame !== undefined) cancelAnimationFrame(state.restoreFrame)
  })

  return {
    handleScroll,
    queueRestore,
    setViewport,
  }
}

export function SessionFileView(props: { session: MountedSession; screen: SessionScreen; id: string }) {
  const ctx = useExtension()
  const layout = ctx.layout
  const shared = useShared()
  const fileComponent = useFileComponent()
  const file = props.screen.file
  const comment = props.screen.comment
  const composer = props.screen.composer
  // The stored side tab key doubles as the scroll key, as it did before extensions.
  const key = () => `file:${props.id}`
  const active = () => shared.active(props.session, props.id)

  const state: FindState = { find: null }

  const search = {
    register: (handle: FileSearchHandle | null) => {
      state.find = handle
    },
  }

  const path = createMemo(() => fileTabPath(file, props.id))

  const current = createMemo(() => {
    const p = path()

    if (!p) return

    return file.get(p)
  })

  const contents = createMemo(() => current()?.content?.content ?? "")
  const cacheKey = createMemo(() => sampledChecksum(contents()))

  // Plain text keeps the code view; every other kind is rendered by ArtifactView.
  const artifact = createMemo(() => {
    const content = current()?.content

    return content?.type === "binary" || artifactKind(path() ?? "") !== "text"
  })

  const selectedLines = createMemo<LineRange | null>(() => {
    const p = path()

    if (!p) return null

    if (file.ready()) return file.selection.get(p) ?? null

    return shared.handoff.get(props.session.key, p) ?? null
  })

  const scrollSync = createScrollSync({
    get: () => layout.scroll.get(props.session, key()),
    set: (pos) => layout.scroll.set(props.session, key(), pos),
  })

  const selectionPreview = (source: string, selection: FileSelection) => {
    return previewSelectedLines(source, {
      start: selection.startLine,
      end: selection.endLine,
    })
  }

  const buildPreview = (filePath: string, lines: LineRange) => {
    const source = filePath === path() ? contents() : file.get(filePath)?.content?.content

    if (!source) return undefined

    return selectionPreview(source, selectionFromLines(lines))
  }

  const addCommentToContext = (input: {
    file: string
    selection: LineRange
    comment: string
    preview?: string
    origin?: "review" | "file"
  }) => {
    const selection = selectionFromLines(input.selection)
    const preview = input.preview ?? buildPreview(input.file, input.selection)

    const saved = comment.add({
      file: input.file,
      selection: input.selection,
      comment: input.comment,
    })

    composer.attach({
      type: "file",
      path: input.file,
      selection,
      comment: input.comment,
      commentID: saved.id,
      commentOrigin: input.origin,
      preview,
    })
  }

  const updateCommentInContext = (input: { id: string; file: string; selection: LineRange; comment: string }) => {
    comment.update(input.id, input.comment)
    const preview = input.file === path() ? buildPreview(input.file, input.selection) : undefined
    // The composer keeps a chip's preview unless the update names a new one.
    composer.update(input.id, preview ? { comment: input.comment, preview } : { comment: input.comment })
  }

  const removeCommentFromContext = (input: { id: string; file: string }) => {
    comment.remove(input.id)
    composer.detach(input.id)
  }

  const fileComments = createMemo(() => {
    const p = path()

    if (!p) return []

    return [...comment.list(p)]
  })

  const commentedLines = createMemo(() => fileComments().map((comment) => comment.selection))

  const [note, setNote] = createStore<NoteState>({ openedComment: null, commenting: null, selected: null })

  const syncSelected = (range: LineRange | null) => {
    const p = path()

    if (!p) return
    file.selection.set(p, range ? cloneSelectedLineRange(range) : null)
  }

  const activeSelection = () => note.selected ?? selectedLines()

  const commentsUi = createLineCommentControllerV2({
    comments: fileComments,
    label: ctx.t("ui.lineComment.submit"),
    draftKey: () => path() ?? props.id,
    mention: {
      items: (query) => file.search(query, { kind: "any" }),
    },
    getSide: selectionSide,
    state: {
      opened: () => note.openedComment,
      setOpened: (id) => setNote("openedComment", id),
      selected: () => note.selected,
      setSelected: (range) => setNote("selected", range),
      commenting: () => note.commenting,
      setCommenting: (range) => setNote("commenting", range),
      syncSelected,
      hoverSelected: syncSelected,
    },
    onSubmit: ({ comment, selection }) => {
      const p = path()

      if (!p) return
      addCommentToContext({ file: p, selection, comment, origin: "file" })
    },
    onUpdate: ({ id, comment, selection }) => {
      const p = path()

      if (!p) return
      updateCommentInContext({ id, file: p, selection, comment })
    },
    onDelete: (comment) => {
      const p = path()

      if (!p) return
      removeCommentFromContext({ id: comment.id, file: p })
    },
    editSubmitLabel: ctx.t("common.save"),
    renderCommentActions: (_, controls) => (
      <FileCommentMenu
        moreLabel={ctx.t("common.moreOptions")}
        editLabel={ctx.t("common.edit")}
        deleteLabel={ctx.t("common.delete")}
        onEdit={controls.edit}
        onDelete={controls.remove}
      />
    ),
  })

  // Mod+F finds in the shown file.
  makeEventListener(
    window,
    "keydown",
    (event: KeyboardEvent) => {
      if (!active()) return

      if (!(event.metaKey || event.ctrlKey) || event.altKey || event.shiftKey) return

      if (event.key.toLowerCase() !== "f") return

      event.preventDefault()
      event.stopPropagation()
      state.find?.focus()
    },
    { capture: true },
  )

  // A new path, e.g. after the workspace directory changes, drops the comment draft and selection of the old one.
  const moved = createMemo(on(path, () => ({}), { defer: true }))

  createKeyed(moved, () => commentsUi.note.reset())

  // A comment focused elsewhere, e.g. from its composer chip, opens here once this file shows.
  createKeyed(
    () => {
      const focus = comment.focus.current()
      const p = path()

      if (!focus || !p || focus.file !== p || !active()) return

      const target = fileComments().find((item) => item.id === focus.id)

      return target && { target }
    },
    (focus) => {
      commentsUi.note.openComment(focus.target.id, focus.target.selection, { cancelDraft: true })
      requestAnimationFrame(() => comment.focus.set(null))
    },
  )

  const previous = { loaded: false, ready: false, active: false }

  createKeyed(
    () => {
      const p = path()

      return p ? { session: props.session.key, path: p } : undefined
    },
    (target) =>
      onCleanup(
        shared.reveal.register(target.session, target.path, () => {
          setNote("selected", null)
          scrollSync.queueRestore()
        }),
      ),
    { equals: (previous, next) => previous?.session === next?.session && previous?.path === next?.path },
  )

  // Restores the stored scroll when the file loads, its view state loads, or the tab shows a loaded file again.
  createKeyed(
    () => ({ loaded: !!current()?.loaded, ready: file.ready(), shown: active() }),
    (next) => {
      const restore =
        (next.loaded && !previous.loaded) ||
        (next.ready && !previous.ready) ||
        (next.shown && next.loaded && !previous.active)

      previous.loaded = next.loaded
      previous.ready = next.ready
      previous.active = next.shown

      if (restore) scrollSync.queueRestore()
    },
    {
      // The file's content changing while it stays loaded is the same key.
      equals: (previous, next) =>
        previous.loaded === next.loaded && previous.ready === next.ready && previous.shown === next.shown,
    },
  )

  const renderFile = (source: string) => (
    <div class="relative overflow-hidden pb-40">
      <Dynamic
        component={fileComponent}
        mode="text"
        file={{
          name: path() ?? "",
          contents: source,
          cacheKey: cacheKey(),
        }}
        enableLineSelection
        enableGutterUtility
        selectedLines={activeSelection()}
        commentedLines={commentedLines()}
        onRendered={() => {
          scrollSync.queueRestore()
        }}
        annotations={commentsUi.annotations()}
        renderAnnotation={commentsUi.renderAnnotation}
        renderGutterUtility={commentsUi.renderGutterUtility}
        onLineSelected={(range: LineRange | null) => {
          commentsUi.onLineSelected(range)
        }}
        onLineSelectionEnd={(range: LineRange | null) => {
          if (!range) {
            commentsUi.note.select(null)
            commentsUi.note.cancelDraft()

            return
          }

          commentsUi.onLineSelectionEnd(range)
        }}
        onLineNumberSelectionEnd={(range: LineRange | null) => {
          commentsUi.onLineNumberSelectionEnd(range)
        }}
        search={search}
        class="select-text"
        // Media and previews have their own viewers below; the code view only ever shows text.
        media={{ mode: "off" }}
      />
    </div>
  )

  // The code view scrolls inside ScrollView so line state and scroll position persist per tab.
  const codeView = (source: string) => (
    <ScrollView class="min-h-0 flex-1" viewportRef={scrollSync.setViewport} onScroll={scrollSync.handleScroll}>
      {renderFile(source)}
    </ScrollView>
  )

  return (
    <div class="mt-3 relative h-full min-h-0 flex flex-col">
      <Switch>
        <Match when={current()?.loaded ? current()?.content : undefined}>
          {(value) => (
            <Show when={artifact()} fallback={codeView(value().content)}>
              <ArtifactView
                session={props.session}
                path={path() ?? ""}
                content={value()}
                cacheKey={cacheKey()}
                source={codeView(value().content)}
              />
            </Show>
          )}
        </Match>
        <Match when={current()?.loading}>
          <div class="px-6 py-4 text-text-weak">{ctx.t("common.loading")}…</div>
        </Match>
        <Match when={current()?.notFound ? current()?.name : undefined}>
          {(name) => <div class="px-6 py-4 text-text-weak">{ctx.t("tab.notFound", { name: name() })}</div>}
        </Match>
        <Match when={current()?.error}>{(err) => <div class="px-6 py-4 text-text-weak">{err()}</div>}</Match>
      </Switch>
    </div>
  )
}

import { createSignal, For, onCleanup, Show, type Accessor } from "solid-js"
import { createStore } from "solid-js/store"
import { Loader } from "@opencode/ui/loader"
import { createKeyed, createLatest, useExtension } from "../sdk"
import { OfficePages, type PaintPage, type ScrollToPage } from "./pages"
import {
  layerFont,
  lineHeight,
  type WordLink,
  type WordMethods,
  type WordPageSize,
  type WordSpan,
} from "./word-protocol"
import { createWorkerClient, movableBuffer } from "./worker-rpc"
import type { FileViewerProps } from "../file/contract"

type Opened = {
  readonly pages: Accessor<readonly WordPageSize[]>
  /** The pages shown so far are the document's first; the rest are still being laid out. */
  readonly loading: Accessor<boolean>
  readonly paint: PaintPage
  /** The page's text layer. */
  readonly text: (index: number, signal: AbortSignal) => Promise<readonly WordSpan[]>
  /** Where a bookmark sits: its page and the height on it, in page pixels. Waits for the layout when it needs to. */
  readonly bookmark: (name: string) => Promise<{ readonly index: number; readonly y: number } | undefined>
  /** Lays the rest of the document out, a step at a time between paints; resolves with its page count. */
  readonly finish: () => Promise<number>
}

type Client = ReturnType<typeof createWorkerClient<WordMethods>>

/** Scrolls the page column; set once the column mounts. */
type Scroll = { to: ScrollToPage | undefined }

/** A value built on first use. */
type Lazy<T> = { value: T | undefined }

/**
 * A read-only, paginated Word document. Its engine runs in a worker of its own (`document.worker.ts`), which opens the
 * file, lays it out, builds and paints its pages and computes their text; the window only shows the bitmaps and the text
 * layer, so no engine work holds it. The worker loads only the Yrs engine: the parse and layout engines and the
 * collaboration code stay unloaded, and embedded fonts give way to the bundled metric-compatible faces. The first pages
 * show as soon as they are laid out, and the rest lay out in short steps between paints. A transparent text layer over
 * each page makes its text selectable, findable and readable, and its links followable.
 */
export default function OfficeDocument(props: FileViewerProps) {
  const ctx = useExtension()
  const [opened, setOpened] = createSignal<Opened>()

  // Syncs one document worker with the loaded bytes. Terminating it is what frees the engine's memory.
  createKeyed(
    () => props.bytes,
    (bytes) => {
      const controller = new AbortController()
      const worker = new Worker(new URL("./document.worker.ts", import.meta.url), { type: "module" })
      const client = createWorkerClient<WordMethods>(worker)

      const fail = () => {
        if (controller.signal.aborted) return

        controller.abort()
        props.onError()
      }

      // A worker that dies after the pages showed takes them with it.
      worker.addEventListener("error", fail)
      worker.addEventListener("messageerror", fail)
      onCleanup(() => {
        controller.abort()
        client.close()
        setOpened(undefined)
      })

      void open(client, bytes)
        .then((value) => {
          if (controller.signal.aborted) return

          setOpened(value)

          // The worker runs calls in order, so the full layout waits until the first pages have asked for their paints:
          // they do once the column is laid out and its observer reports them, which takes up to two frames.
          return new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)))
            .then(() => (controller.signal.aborted ? undefined : value.finish()))
            .then((count) => {
              if (count !== undefined && !controller.signal.aborted) props.onDetails([ctx.plural("pages", count)])
            })
        })
        .catch(fail)
    },
  )

  return (
    <Show
      when={opened()}
      fallback={
        <div class="flex min-h-0 flex-1 items-center justify-center">
          <Loader />
        </div>
      }
    >
      {(opened) => {
        const scroll: Scroll = { to: undefined }

        const follow = (link: WordLink) => {
          if (link.kind === "external") return ctx.system.openExternal(link.url)

          void opened()
            .bookmark(link.bookmark)
            .then(
              (target) => {
                if (target) scroll.to?.(target.index, target.y)
              },
              () => undefined,
            )
        }

        return (
          <OfficePages
            pages={opened().pages()}
            maxScale={1}
            paint={opened().paint}
            label={(index) => ctx.t("page", { number: index + 1 })}
            overlay={(input) => (
              <WordTextLayer
                index={input.index}
                page={opened().pages()[input.index]}
                text={opened().text}
                follow={follow}
              />
            )}
            text
            footer={(index) => (
              <Show when={opened().loading() && index === opened().pages().length - 1}>
                <Loader />
              </Show>
            )}
            onScrollTo={(scrollTo) => {
              scroll.to = scrollTo
            }}
          />
        )
      }}
    </Show>
  )
}

/**
 * Transparent text over a page's painted glyphs. Positions are fractions of the page and sizes fractions of its width
 * (container query units), so the layer tracks the page's CSS size at once while a resize waits to repaint.
 */
function WordTextLayer(props: {
  index: number
  /** The page's size object, which the full layout replaces when it changes the page. */
  page: WordPageSize | undefined
  text: (index: number, signal: AbortSignal) => Promise<readonly WordSpan[]>
  follow: (link: WordLink) => void
}) {
  // A changed page asks for its text again; the old text stays until the new arrives.
  const spans = createLatest(
    () => props.page,
    (_, signal) => props.text(props.index, signal),
  )

  return (
    <div
      class="absolute inset-0 select-text overflow-hidden whitespace-pre text-transparent [container-type:inline-size] selection:bg-[rgb(0_120_215/0.3)] selection:text-transparent"
      // Separators flow at the layer's corner; at no size they keep words and paragraphs apart in copied text unseen.
      style={{ "font-family": layerFont, "font-size": "0", "line-height": lineHeight }}
    >
      <For each={spans.latest}>
        {(span) => (
          <>
            <Show
              when={span.link}
              fallback={
                <span dir={span.dir} class="absolute origin-top-left cursor-text" style={place(span)}>
                  {span.text}
                </span>
              }
            >
              {(link) => (
                <span
                  role="link"
                  tabIndex={0}
                  title={span.title}
                  dir={span.dir}
                  class="absolute origin-top-left cursor-pointer focus-visible:outline focus-visible:outline-2 focus-visible:outline-border-focus"
                  style={place(span)}
                  onClick={(event) => {
                    // A drag that ends on the link selects text instead of following it.
                    if (event.button === 0 && (globalThis.getSelection()?.isCollapsed ?? true)) props.follow(link())
                  }}
                  onKeyDown={(event) => {
                    if (event.key !== "Enter") return

                    event.preventDefault()
                    props.follow(link())
                  }}
                >
                  {span.text}
                </span>
              )}
            </Show>
            <Show when={span.after === "br"}>
              <br />
            </Show>
            <Show when={span.after === "tab"}>{"\t"}</Show>
          </>
        )}
      </For>
    </div>
  )
}

function place(span: WordSpan) {
  return {
    left: `${span.left * 100}%`,
    top: `${span.top * 100}%`,
    "font-size": `${span.size * 100}cqw`,
    transform: span.transform,
  }
}

/** Opens the bytes in the worker and returns as soon as the document's first pages can show. */
async function open(client: Client, bytes: Uint8Array): Promise<Opened> {
  // The view owns its bytes, so they move to the worker rather than being copied.
  const buffer = movableBuffer(bytes)
  const first = await client.call("open", { bytes: buffer }, { transfer: [buffer] })
  const [layout, setLayout] = createStore({ pages: first.pages, loading: first.loading })

  const layOut = async (): Promise<number> => {
    const step = await client.call("layout", undefined)

    if (!step.done) return layOut()

    // A page keeps its object, and so its bitmap and text layer, unless the full layout changed it. A changed page
    // keeps its row and paints again over its old bitmap.
    const sizes = step.pages.map((page, index) => {
      const size = layout.pages[index]

      return size && step.kept[index] && sameSize(size, page) ? size : page
    })

    // The column mounts the new rows a slice at a time.
    setLayout({ pages: sizes, loading: false })

    return sizes.length
  }

  const rest: Lazy<Promise<number>> = { value: undefined }
  // Each page's text layer, kept for its page object: a page that scrolls back into view shows it without asking the
  // worker. A page the full layout changed gets a new object, and asks again.
  const texts = new WeakMap<WordPageSize, readonly WordSpan[]>()
  const pages = () => layout.pages
  const loading = () => layout.loading

  const finish = () => (rest.value ??= loading() ? layOut() : Promise.resolve(pages().length))

  return {
    pages,
    loading,
    finish,
    paint: async (index, canvas, scale, signal) => {
      const painted = client.call(
        "paint",
        { index, scale, ratio: window.devicePixelRatio || 1 },
        // A newer paint of the page, such as at another scale, replaces this one while it waits, and a page that
        // scrolled away withdraws it.
        { key: `paint:${index}`, signal },
      )

      // Builds the next page after the paints waiting, so scrolling on rarely waits for it. Pages stay unbuilt beyond
      // that, and a paint releases the pages far from its own: each built page holds megabytes in the engine.
      void client.call("build", { index: index + 1 }, { key: "build" }).catch(() => undefined)

      // A withdrawn paint rejects here, and the worker closes any bitmap it made for it.
      const bitmap = await painted

      if (!bitmap) return

      const context = canvas.getContext("bitmaprenderer")

      if (!context) return bitmap.close()

      canvas.width = bitmap.width
      canvas.height = bitmap.height
      context.transferFromImageBitmap(bitmap)
    },
    text: async (index, signal) => {
      const page = pages()[index]
      const cached = page && texts.get(page)

      if (cached) return cached

      const spans = await client.call("text", { index }, { signal })

      if (page) texts.set(page, spans)

      return spans
    },
    bookmark: async (name) => {
      const found = await client.call("bookmark", { name })

      // The bookmark may sit past the pages laid out so far.
      if (found || !loading()) return found

      await finish()

      return client.call("bookmark", { name })
    },
  }
}

function sameSize(size: WordPageSize, page: WordPageSize) {
  return size.width === page.width && size.height === page.height && size.background === page.background
}

import { Schema } from "effect"
import {
  buildResidentRegionLayoutRequest,
  getLayoutKernelInputs,
  workerLayoutComputation,
} from "@betteroffice/docx/editor"
import { createRustMeasureSource } from "@betteroffice/docx/layout"
import {
  applyFrameDelta,
  decodeFrameDelta,
  encodeDisplayListFrameExtras,
  GlyphCache,
  rasterizeDisplayPageToBackBuffer,
  type DisplayPage,
  type RetainedFrame,
} from "@betteroffice/docx/layout/render"
import { createYrsPositionProjection, createYrsSession, type YrsPositionProjection } from "@betteroffice/docx/yrs"
import { wordFonts } from "./fonts"
import { createBitmapImageResolver } from "./word-images"
import { layerFont, type WordMethods, type WordPageSize, type WordSpan } from "./word-protocol"
import { pageText, positionTarget, type TextMeasure } from "./word-text"
import { serveWorker, Transfer } from "./worker-rpc"

// One worker holds one open Word document: its engine session, fonts, layout, built pages and painting. The window
// terminates the worker when the document closes, which is the only way the engine's memory is given back.

const FontRequirements = Schema.fromJsonString(
  Schema.Array(
    Schema.Struct({
      key: Schema.String,
      family: Schema.String,
      bold: Schema.Boolean,
      italic: Schema.Boolean,
      scripts: Schema.optional(
        Schema.Array(Schema.Literals(["cjk-sc", "cjk-tc", "cjk-jp", "cjk-kr", "arabic", "hebrew"])),
      ),
    }),
  ),
)

const decodeFontRequirements = Schema.decodeUnknownSync(FontRequirements)

/** A prefix layout's reply marks itself provisional when the document goes on past it. */
const decodeLayoutReply = Schema.decodeUnknownSync(
  Schema.fromJsonString(Schema.Struct({ provisional: Schema.optional(Schema.Boolean) })),
)

/** Pages laid out and built before the first paint; later pages are built as they near the viewport. */
const firstPages = 3

/** How long one layout step may hold back a paint that waits behind it, in milliseconds. */
const stepBudget = 24

/**
 * How many pages either side of the page painted last stay built. A built page holds about 5 MB in the engine and
 * builds again in about 100 ms. This keeps every page near the viewport, which paints a viewport ahead in both
 * directions, and lets a reader scroll back a few screens without waiting, while a long read holds at most 21 pages.
 */
const keptAround = 10

type Opened = Awaited<ReturnType<typeof open>>

/** A value built on first use. */
type Lazy<T> = { value: T | undefined }

/** The document this worker opened, once it has. */
const opened: Lazy<Opened> = { value: undefined }

serveWorker<WordMethods>({
  open: async (input) => {
    if (opened.value) throw new Error("The worker already holds a document")

    const loaded = await open(new Uint8Array(input.bytes))

    opened.value = loaded

    return { pages: loaded.pages().map(pageSize), loading: loaded.loading() }
  },
  layout: () => required().step(),
  paint: async (input, signal) => {
    const bitmap = await required().paint(input.index, input.scale, input.ratio, signal)

    return bitmap ? new Transfer(bitmap, [bitmap]) : undefined
  },
  build: (input) => {
    required().built(input.index)

    return undefined
  },
  text: (input) => required().text(input.index),
  bookmark: (input) => required().target(input.name),
})

function required() {
  if (!opened.value) throw new Error("The worker holds no document")

  return opened.value
}

/** Opens the document and lays out its first pages; the rest lay out a `step` at a time. */
async function open(bytes: Uint8Array) {
  const session = await createYrsSession()
  const document = session.openDocx(bytes, true, { mediaTokens: true }).document
  const settings = document.package.settings

  const measure = createRustMeasureSource({
    engine: {
      registerFont: (font) => session.registerFont(font),
      registerSubstituteFont: (id, family) => session.registerSubstituteFont(id, family),
      clearFonts: () => session.clearFonts(),
    },
    bundled: wordFonts(),
  })

  measure.setCompat(settings?.compatibilityFlags)

  const request = buildResidentRegionLayoutRequest(document, 0, {
    themeColors: Object.fromEntries(
      Object.entries(document.package.theme?.colorScheme ?? {}).filter(
        (entry): entry is [string, string] => entry[1] !== undefined,
      ),
    ),
    defaultTabStopTwips: settings?.defaultTabStop ?? null,
    numericIds: {},
    mediaTokens: true,
  })

  const requirements = decodeFontRequirements(session.layoutFontRequirementsJson(JSON.stringify(request))).map(
    (requirement) => ({ ...requirement, scripts: requirement.scripts && [...requirement.scripts] }),
  )

  await measure.prepareFontRequirements(requirements)

  const measurement = measure.measurementConfigForRequirements(requirements)

  if (!measurement) throw new Error("The document's fonts could not be prepared")

  const input = JSON.stringify({ ...request, measurement })

  // Word shows resolved comments without the active highlight.
  const resolvedCommentIds = (document.package.document.comments ?? [])
    .filter((comment) => (comment.done || comment.status === "resolved") && comment.parentId === undefined)
    .map((comment) => comment.id)

  // The session keeps the layout it last ran and builds display frames from it: only the display extras go in, and a
  // binary frame comes back with the window's pages built and every other page a placeholder carrying its geometry.
  const display = (previous: RetainedFrame | null, reply: string) => {
    const layout = workerLayoutComputation(reply).layout

    session.setDisplayWindow(0, firstPages)

    const extras = encodeDisplayListFrameExtras({
      measured: [],
      options: undefined,
      layout,
      fontChains: measurement.fontChains,
      headersFooters: getLayoutKernelInputs(layout)?.headersFooters,
      resolvedCommentIds,
    })

    return applyFrameDelta(previous, decodeFrameDelta(session.buildDisplayListFrame(extras, previous?.frameEpoch ?? 0)))
  }

  // Only as much of the body as fills the first pages; a long document goes on past it.
  const prefix = session.layoutDocumentWithRegionsPrefixRetainedJson(input, firstPages)
  const retained = { frame: display(null, prefix) }

  if (retained.frame.displayList.pages.length === 0) throw new Error("The document produced no pages")

  // The region layout that finishes the document: begun on the first step, `cost` the running average milliseconds a
  // body block takes.
  const layout = { loading: decodeLayoutReply(prefix).provisional ?? false, begun: false, cost: 3 }

  // Builds a page's content when it is needed and not built, the first time or again after `release`.
  const built = (index: number) => {
    const page = retained.frame.displayList.pages[index]

    if (!page?.unbuilt) return page

    retained.frame = applyFrameDelta(
      retained.frame,
      decodeFrameDelta(session.buildDisplayPagesFrame([index], retained.frame.frameEpoch)),
    )

    return retained.frame.displayList.pages[index]
  }

  // Gives back the built pages far from the page about to paint, so a long read keeps only the pages around the
  // viewport. A released page keeps its geometry and document positions, which bookmarks search, and builds again
  // when it is needed.
  const release = (painted: number) => {
    // The engine releases pages of the whole document's layout only, and few pages show before it.
    if (layout.loading) return

    const far = retained.frame.displayList.pages.flatMap((page, index) =>
      !page.unbuilt && Math.abs(painted - index) > keptAround ? [index] : [],
    )

    if (far.length === 0) return

    const frame = session.releaseDisplayPagesFrame(far, retained.frame.frameEpoch)

    // A superseded release changes nothing; the next one tries again.
    if (frame) retained.frame = applyFrameDelta(retained.frame, decodeFrameDelta(frame))
  }

  // The whole document's layout replaces the prefix's frame.
  const complete = (reply: string) => {
    const before = retained.frame.displayList.pages

    retained.frame = display(retained.frame, reply)
    layout.loading = false

    const pages = retained.frame.displayList.pages

    return {
      done: true as const,
      pages: pages.map(pageSize),
      kept: pages.map((page, index) => {
        const was = before[index]

        return was === page || (!!was?.unbuilt && !!page.unbuilt)
      }),
    }
  }

  const glyphCache = new GlyphCache({ provider: (font, glyph) => session.outlineGlyphJson(font, glyph) })
  const images = createBitmapImageResolver((token) => session.mediaSource(token))
  const surface = new OffscreenCanvas(1, 1)
  const textMeasure = layerMeasure()
  const texts = new WeakMap<DisplayPage, readonly WordSpan[]>()
  // Built on the first followed bookmark: most documents are read without one.
  const projection: Lazy<YrsPositionProjection | null> = { value: undefined }

  return {
    pages: () => retained.frame.displayList.pages,
    loading: () => layout.loading,
    built,
    /**
     * Lays out about `stepBudget` milliseconds more of the body. Blocks vary widely, and sizing a step by the last one
     * alone overshoots after a run of cheap blocks.
     */
    step: () => {
      if (!layout.loading) {
        const pages = retained.frame.displayList.pages

        return { done: true as const, pages: pages.map(pageSize), kept: pages.map(() => true) }
      }

      if (!layout.begun) {
        layout.begun = true

        const begun = session.beginRegionLayout(input)

        return begun.layoutJson === undefined ? { done: false as const } : complete(begun.layoutJson)
      }

      const blocks = Math.min(8192, Math.max(1, Math.round(stepBudget / layout.cost)))
      const started = performance.now()
      const progress = session.resumeRegionLayout(blocks)

      layout.cost = layout.cost * 0.7 + ((performance.now() - started) / blocks) * 0.3

      return progress.layoutJson === undefined ? { done: false as const } : complete(progress.layoutJson)
    },
    paint: async (index: number, scale: number, ratio: number, signal: AbortSignal) => {
      // A page that scrolled away before its paint began, or while it rasterized, needs no bitmap.
      if (signal.aborted) return undefined

      // Released first, so the page builds in the memory they free.
      release(index)

      const page = built(index)

      if (!page) return undefined

      // The window drew image elements, which shrink smoothly at the default quality; a bitmap needs medium quality to
      // look the same. Sizing the surface first keeps the setting: the painter resizes it, which resets the context,
      // only when its size differs.
      const context = surface.getContext("2d")
      const width = Math.ceil(page.width * ratio * scale)
      const height = Math.ceil(page.height * ratio * scale)

      if (surface.width !== width) surface.width = width

      if (surface.height !== height) surface.height = height

      if (context) context.imageSmoothingQuality = "medium"

      await rasterizeDisplayPageToBackBuffer(surface, page, { glyphCache, resolveImage: images.resolve }, ratio, scale)
      images.trim()

      if (signal.aborted) return undefined

      return surface.transferToImageBitmap()
    },
    text: (index: number) => {
      const page = built(index)

      if (!page || !textMeasure) return []

      const cached = texts.get(page)

      if (cached) return cached

      const spans = pageText(page, textMeasure)

      texts.set(page, spans)

      return spans
    },
    target: (name: string) => {
      projection.value ??= createYrsPositionProjection(session, "body")

      const position = projection.value?.bookmarkPosition(name) ?? undefined

      if (position !== undefined) return positionTarget(retained.frame.displayList.pages, position, built)

      // Word's reserved bookmark for the start of the document.
      return name === "_top" ? { index: 0, y: 0 } : undefined
    },
  }
}

function pageSize(page: DisplayPage): WordPageSize {
  return { width: page.width, height: page.height, background: page.background }
}

/** Measures the text layer's font with a detached canvas; undefined where the worker offers no 2D context. */
function layerMeasure(): TextMeasure | undefined {
  const context = new OffscreenCanvas(1, 1).getContext("2d")

  if (!context) return undefined

  // Measured large and scaled down, so rounding stays well below a pixel at any zoom.
  const size = 100

  context.font = `${size}px ${layerFont}`

  const metrics = context.measureText("Hg")

  return {
    width: (text) => context.measureText(text).width / size,
    ascent: metrics.fontBoundingBoxAscent / size,
    descent: metrics.fontBoundingBoxDescent / size,
  }
}

import { describe, expect, test } from "bun:test"
import { loadFace, presentationFace, wordFonts } from "./fonts"

// East Asian families the font package maps to its CJK add-on, which the app does not ship: by name, by alias, and as
// weight variants that resolve through their base family.
const eastAsian = [
  "Microsoft YaHei",
  "DengXian",
  "等线",
  "等线 Light",
  "Microsoft YaHei Light",
  "Yu Gothic Medium",
  "Malgun Gothic Semilight",
  "MS Mincho",
]

describe("presentationFace", () => {
  test("draws East Asian families with a face the app ships", async () => {
    const faces = eastAsian.map((family) => presentationFace(family, false, false))

    expect(faces.map((face) => face.script)).toEqual(eastAsian.map(() => undefined))

    const bytes = await Promise.all(faces.map(loadFace))

    expect(bytes.every((buffer) => buffer.byteLength > 0)).toBe(true)
  })

  test("keeps a serif East Asian family serif when only its weight variant is named", () => {
    expect(presentationFace("Yu Mincho Light", false, false).family).toBe("Liberation Serif")
    expect(presentationFace("Yu Gothic Light", false, false).family).toBe("Carlito")
  })

  test("still resolves Latin families to their metric-compatible faces", () => {
    expect(presentationFace("Calibri", true, false)).toMatchObject({ family: "Carlito", weight: 700 })
    expect(presentationFace("Calibri Light", false, false).family).toBe("Carlito")
    expect(presentationFace("Arial", false, true)).toMatchObject({ family: "Liberation Sans", style: "italic" })
  })
})

describe("wordFonts", () => {
  test("offers no metric-compatible face for an East Asian family, so Word's fallback measures it", () => {
    const fonts = wordFonts()

    expect(eastAsian.map((family) => fonts.resolve(family, false, false))).toEqual(eastAsian.map(() => undefined))
    expect(eastAsian.map((family) => fonts.resolveFamily?.(family, false, false))).toEqual(
      eastAsian.map(() => undefined),
    )
    expect(fonts.resolveScriptFallback?.("cjk-sc", false, false)).toBeUndefined()
  })

  test("loads a last-resort face for every East Asian weight variant", async () => {
    const fonts = wordFonts()

    const bytes = await Promise.all(
      eastAsian.map((family) => fonts.resolveLastResort?.(family, false, false, "word")?.()),
    )

    expect(bytes.map((buffer) => (buffer?.byteLength ?? 0) > 0)).toEqual(eastAsian.map(() => true))
  })

  test("still loads metric-compatible faces for Latin families", async () => {
    const bytes = await wordFonts().resolve("Times New Roman", false, false)?.()

    expect(bytes?.byteLength).toBeGreaterThan(0)
  })
})

import type { BundledFontProvider } from "@betteroffice/docx/layout"
import {
  loadBundledFontBytes,
  resolveBundledFamilyFace,
  resolveLastResortFace,
  resolveMetricCompatFace,
  resolveScriptFallbackFace,
  type BundledFontFace,
  type BundledFontScript,
} from "@betteroffice/fonts"

// Every face loads from the app's own files, so no font request leaves the machine. The Chinese, Japanese and Korean
// faces are an add-on the app does not ship (see `fonts-cjk.ts`), yet the font package still maps East Asian families
// such as Microsoft YaHei or Yu Gothic Medium to them, so every lookup passes through `shippedFace`.
function shipped(script: BundledFontScript) {
  return !script.startsWith("cjk-")
}

/** The faces Word substitutes for a document's fonts: metric-compatible ones first, then Word's own fallbacks. */
export function wordFonts(): BundledFontProvider {
  const loader = (face: BundledFontFace | undefined) => (face ? () => loadFace(face) : undefined)

  return {
    resolve: (family, bold, italic) => loader(shippedFace(resolveMetricCompatFace(family, bold, italic))),
    resolveFamily: (family, bold, italic) => loader(shippedFace(resolveBundledFamilyFace(family, bold, italic))),
    resolveScriptFallback: (script, bold, italic) => loader(scriptFace(script, bold, italic)),
    resolveLastResort: (family, bold, italic) => () => loadFace(lastResortFace(family, bold, italic, "word")),
  }
}

/** The face PowerPoint draws a family with: its metric-compatible or bundled face, else PowerPoint's substitute. */
export function presentationFace(family: string, bold: boolean, italic: boolean): BundledFontFace {
  return (
    shippedFace(resolveMetricCompatFace(family, bold, italic)) ??
    shippedFace(resolveBundledFamilyFace(family, bold, italic)) ??
    lastResortFace(family, bold, italic, "powerpoint")
  )
}

function shippedFace(face: BundledFontFace | undefined) {
  return face && (!face.script || shipped(face.script)) ? face : undefined
}

/**
 * The substitute an application picks for a family it lacks. Only a weight variant of an East Asian family, such as
 * Yu Mincho Light, resolves to a face the app does not ship; its name without the weight still tells serif from sans.
 */
function lastResortFace(family: string, bold: boolean, italic: boolean, office: "word" | "powerpoint") {
  const face = resolveLastResortFace(family, bold, italic, office)

  if (shippedFace(face)) return face

  const base = family
    .trim()
    .split(/[\s-]+/)
    .slice(0, -1)
    .join(" ")

  return (
    shippedFace(resolveLastResortFace(base, bold, italic, office)) ?? resolveLastResortFace("", bold, italic, office)
  )
}

/** The face that covers a script the Latin faces lack, or undefined when the app ships none. */
export function scriptFace(script: BundledFontScript, bold: boolean, italic: boolean) {
  return shipped(script) ? resolveScriptFallbackFace(script, bold, italic) : undefined
}

/**
 * A bundled face's bytes. The font package caches them per worker, so a face loads once per open file; the browser's
 * caches, which every worker shares, serve the files to the next.
 */
export function loadFace(face: BundledFontFace) {
  return loadBundledFontBytes(face)
}

import { describe, expect, test } from "bun:test"
import { externalUrl, wordLink } from "./links"

describe("externalUrl", () => {
  test("allows the web and mail addresses the host opens", () => {
    expect(externalUrl("https://example.com/a b")).toBe("https://example.com/a%20b")
    expect(externalUrl("http://example.com")).toBe("http://example.com/")
    expect(externalUrl("mailto:someone@example.com")).toBe("mailto:someone@example.com")
    expect(externalUrl("HTTPS://EXAMPLE.COM/#Sheet2!A1")).toBe("https://example.com/#Sheet2!A1")
  })

  test("refuses every other scheme and anything that is not a URL", () => {
    expect(externalUrl("javascript:alert(1)")).toBeUndefined()
    expect(externalUrl("file:///C:/Windows/System32/calc.exe")).toBeUndefined()
    expect(externalUrl("data:text/html,<script>alert(1)</script>")).toBeUndefined()
    expect(externalUrl("tel:+15550100")).toBeUndefined()
    expect(externalUrl("vbscript:msgbox")).toBeUndefined()
    expect(externalUrl("example.com/page")).toBeUndefined()
  })
})

describe("wordLink", () => {
  test("follows bookmarks and allowed addresses", () => {
    expect(wordLink("#_Toc123")).toEqual({ kind: "internal", bookmark: "_Toc123" })
    expect(wordLink("https://example.com")).toEqual({ kind: "external", url: "https://example.com/" })
    expect(wordLink("mailto:someone@example.com")).toEqual({ kind: "external", url: "mailto:someone@example.com" })
  })

  test("leaves other links as text", () => {
    expect(wordLink(undefined)).toBeUndefined()
    expect(wordLink("")).toBeUndefined()
    expect(wordLink("#")).toBeUndefined()
    expect(wordLink("javascript:alert(1)")).toBeUndefined()
    expect(wordLink("file:///etc/passwd")).toBeUndefined()
    expect(wordLink("data:text/plain,hi")).toBeUndefined()
    expect(wordLink("tel:+15550100")).toBeUndefined()
  })
})

import type { WordLink } from "./word-protocol"

/** The schemes the host opens outside the app; it refuses any other, such as `javascript:`, `file:` or `tel:`. */
const schemes = ["http:", "https:", "mailto:"]

/** A document's link address, normalized, when the host may open it; undefined otherwise, so the link stays text. */
export function externalUrl(href: string) {
  const url = URL.parse(href)

  return url && schemes.includes(url.protocol) ? url.href : undefined
}

/** Where a Word link leads, if it is one a reader may follow: a bookmark in the document, or an `externalUrl`. */
export function wordLink(href: string | undefined): WordLink | undefined {
  if (!href) return undefined

  if (href.startsWith("#")) return href.length > 1 ? { kind: "internal", bookmark: href.slice(1) } : undefined

  const url = externalUrl(href)

  return url ? { kind: "external", url } : undefined
}

import { createMemo, createSignal, Index, onCleanup, onMount, Show, type JSX } from "solid-js"
import { createResizeObserver } from "@solid-primitives/resize-observer"
import { createKeyed } from "../sdk"
import { paper } from "./paper"

/** Paints one page into `canvas` at `scale`; `signal` aborts once a newer paint replaces this one or the page leaves. */
export type PaintPage = (index: number, canvas: HTMLCanvasElement, scale: number, signal: AbortSignal) => Promise<void>

/** Content laid over one page while it is near the viewport, in page pixels times `scale`. */
export type PageOverlay = (input: { readonly index: number; readonly scale: number }) => JSX.Element

/** Scrolls the column so a point of a page shows near the top. */
export type ScrollToPage = (index: number, y: number) => void

/** A page's size and paper colour; a new object for a page is a changed page, which paints again. */
type PageSize = { readonly width: number; readonly height: number; readonly background?: string }

/** Tells a page whether it is near the viewport. */
type Watch = (element: Element, change: (near: boolean) => void) => void

/** A scroll to a page whose row is not mounted yet, if one waits. */
type PendingScroll = { target: { readonly index: number; readonly y: number } | undefined }

/** The observer every page shares, made once the first page mounts. */
type SharedObserver = { value: IntersectionObserver | undefined }

/** The timer of the next slice of rows, and how many rows it mounts. */
type Growth = { timer: ReturnType<typeof setTimeout> | undefined; slice: number }

const padding = 24

/** How long a resize has to settle before visible pages paint again at the new scale. */
const settleDelay = 150

/** The rows mounted with the column: enough to fill a tall screen with the first pages. */
const firstSlice = 6

/** How long mounting one later slice of rows should take, in milliseconds. */
const sliceBudget = 12

/** The most rows one slice mounts. */
const maxSlice = 200

/**
 * A column of pages that fit the pane's width, up to `maxScale`. Only pages near the viewport hold a bitmap, an
 * overlay and the work that keeps them: a long document would otherwise keep hundreds of page-sized canvases in memory,
 * and mount the work for each at once.
 */
export function OfficePages(props: {
  pages: readonly PageSize[]
  maxScale: number
  paint: PaintPage
  label: (index: number) => string
  /** Laid over each page near the viewport, such as a text layer for selection, links and screen readers. */
  overlay?: PageOverlay
  /** The overlay carries the page's text, so screen readers read it as a page instead of an image. */
  text?: boolean
  /** Shown under each page, such as a slide's speaker notes. */
  footer?: (index: number) => JSX.Element
  /** Receives the column's scroll function once it mounts. */
  onScrollTo?: (scrollTo: ScrollToPage) => void
}) {
  const [width, setWidth] = createSignal(0)
  // The width pages paint at: a resize repaints each visible page once it settles, while the CSS size follows at once.
  const [settled, setSettled] = createSignal(0)
  const [ratio, setRatio] = createSignal(window.devicePixelRatio || 1)
  // How many rows are mounted: the first slice at once, the rest a slice per task.
  const [mounted, setMounted] = createSignal(firstSlice)
  const shown = createMemo(() => props.pages.slice(0, mounted()))
  // A scroll to a page whose row is not mounted yet.
  const pending: PendingScroll = { target: undefined }
  const pages: HTMLDivElement[] = []
  const watched = new Map<Element, (near: boolean) => void>()
  const observer: SharedObserver = { value: undefined }
  let scroller: HTMLDivElement | undefined
  let timer: ReturnType<typeof setTimeout> | undefined

  createResizeObserver(
    () => scroller,
    (rect) => {
      setWidth(rect.width)
      clearTimeout(timer)

      if (settled() === 0) return void setSettled(rect.width)

      timer = setTimeout(() => setSettled(rect.width), settleDelay)
    },
  )

  onCleanup(() => {
    clearTimeout(timer)
    observer.value?.disconnect()
  })

  // Syncs with the display's pixel ratio, which changes when the window moves to another screen. A media query
  // matches one ratio, so each new ratio arms a new one.
  createKeyed(ratio, (value) => {
    const query = window.matchMedia(`(resolution: ${value}dppx)`)
    const change = () => setRatio(window.devicePixelRatio || 1)

    query.addEventListener("change", change)
    onCleanup(() => query.removeEventListener("change", change))
  })

  // Scrolls to a page once its row is mounted.
  const scrollTo: ScrollToPage = (index, y) => {
    const page = pages[index]
    const target = props.pages[index]

    if (!target) return

    if (!scroller || !page || index >= mounted()) return void (pending.target = { index, y })

    pending.target = undefined
    scroller.scrollTo({ top: page.offsetTop + y * fit(width(), target.width) - padding })
  }

  onMount(() => props.onScrollTo?.(scrollTo))

  // Mounts the rows a slice at a time, each slice sized to take about `sliceBudget`, so no one update builds hundreds
  // of them; rows only ever join below the ones mounted, so nothing on screen moves.
  createKeyed(
    () => props.pages.length,
    (total) => {
      const state: Growth = { timer: undefined, slice: firstSlice }

      const grow = () => {
        if (mounted() >= total) return

        const started = performance.now()
        const before = mounted()

        setMounted(Math.min(total, before + state.slice))

        const each = (performance.now() - started) / (mounted() - before)

        state.slice = Math.min(maxSlice, Math.max(1, Math.floor(sliceBudget / each)))

        if (pending.target && pending.target.index < mounted()) scrollTo(pending.target.index, pending.target.y)

        state.timer = setTimeout(grow)
      }

      state.timer = setTimeout(grow)
      onCleanup(() => clearTimeout(state.timer))
    },
  )

  // One observer for every page. It paints a viewport ahead in both directions, so scrolling rarely reaches a blank
  // page. The column clips its pages, so the margin applies to it: an observer of the window would only see what shows.
  const watch: Watch = (element, change) => {
    observer.value ??= new IntersectionObserver(
      (entries) => entries.forEach((entry) => watched.get(entry.target)?.(entry.isIntersecting)),
      { root: scroller, rootMargin: "100% 0px" },
    )

    watched.set(element, change)
    observer.value.observe(element)
    onCleanup(() => {
      watched.delete(element)
      observer.value?.unobserve(element)
    })
  }

  const fit = (available: number, page: number) =>
    Math.max(0, Math.min(props.maxScale, (available - padding * 2) / page))

  return (
    <div ref={scroller} data-slot="artifact-stage" class="relative min-h-0 flex-1 overflow-auto">
      <div class="flex flex-col items-center gap-4 py-6">
        {/* Keyed by position: a replaced page keeps its row and canvas, and paints over its old bitmap. */}
        <Index each={shown()}>
          {(page, index) => (
            <div class="flex shrink-0 flex-col items-center gap-3">
              <OfficePage
                ref={(element) => (pages[index] = element)}
                watch={watch}
                index={index}
                page={page()}
                scale={fit(width(), page().width)}
                rasterScale={fit(settled(), page().width)}
                ratio={ratio()}
                paint={props.paint}
                overlay={props.overlay}
                text={props.text ?? false}
                label={props.label(index)}
              />
              {props.footer?.(index)}
            </div>
          )}
        </Index>
      </div>
    </div>
  )
}

function OfficePage(props: {
  ref: (element: HTMLDivElement) => void
  watch: Watch
  index: number
  page: PageSize
  scale: number
  rasterScale: number
  ratio: number
  paint: PaintPage
  overlay: PageOverlay | undefined
  text: boolean
  label: string
}) {
  const [visible, setVisible] = createSignal(false)
  let frame: HTMLDivElement | undefined
  let canvas: HTMLCanvasElement | undefined

  onMount(() => {
    if (frame) props.watch(frame, setVisible)
  })

  return (
    <div
      ref={(element) => {
        frame = element
        props.ref(element)
      }}
      role={props.text ? "group" : undefined}
      aria-label={props.text ? props.label : undefined}
      class="relative shrink-0 shadow-[var(--v2-elevation-raised)]"
      style={{
        width: `${props.page.width * props.scale}px`,
        height: `${props.page.height * props.scale}px`,
        // Paper keeps the document's own colour in every theme, as it would print.
        background: props.page.background ?? paper,
      }}
    >
      <canvas
        ref={canvas}
        role={props.text ? undefined : "img"}
        aria-label={props.text ? undefined : props.label}
        aria-hidden={props.text ? "true" : undefined}
        class="absolute inset-0 block size-full"
      />
      <Show when={visible() && canvas}>
        {(target) => (
          <PageBitmap
            canvas={target()}
            index={props.index}
            page={props.page}
            scale={props.scale}
            rasterScale={props.rasterScale}
            ratio={props.ratio}
            paint={props.paint}
            overlay={props.overlay}
