    expect(parseRange("$F$20:a1")).toEqual({ top: 0, left: 0, bottom: 19, right: 5 })
    expect(parseRange("XFD1048576")).toEqual({
      top: lastCell.row,
      left: lastCell.col,
      bottom: lastCell.row,
      right: lastCell.col,
    })
  })

  test("rejects anything else, including cells past the sheet", () => {
    expect(parseRange("")).toBeUndefined()
    expect(parseRange("A0")).toBeUndefined()
    expect(parseRange("1A")).toBeUndefined()
    expect(parseRange("XFE1")).toBeUndefined()
    expect(parseRange("A1048577")).toBeUndefined()
    expect(parseRange("A1:")).toBeUndefined()
    expect(parseRange("Sheet1!A1")).toBeUndefined()
  })
})

describe("parseSpans", () => {
  test("reads hidden row and column spans and drops malformed ones", () => {
    expect(parseSpans(["5:7", "10", "0:1", "9:8", "x"], "rows")).toEqual([
      { start: 4, end: 6 },
      { start: 9, end: 9 },
    ])
    expect(parseSpans(["C:D", "AA", "D:C", "1:2"], "columns")).toEqual([
      { start: 2, end: 3 },
      { start: 26, end: 26 },
    ])
  })
})

describe("hiddenAt", () => {
  test("tells whether an index lies in a span, ends included", () => {
    const spans = [{ start: 2, end: 4 }]

    expect([1, 2, 3, 4, 5].map((index) => hiddenAt(spans, index))).toEqual([false, true, true, true, false])
  })
})

describe("coverMerges", () => {
  test("grows a range over every merge it touches, including merges a grown range reaches", () => {
    // The range reaches the first merge only once the second has grown it.
    const merges = [
      { top: 1, left: 2, bottom: 4, right: 3 },
      { top: 0, left: 1, bottom: 1, right: 2 },
      { top: 10, left: 10, bottom: 11, right: 11 },
    ]

    expect(coverMerges({ top: 0, left: 0, bottom: 0, right: 1 }, merges)).toEqual({
      top: 0,
      left: 0,
      bottom: 4,
      right: 3,
    })
    expect(coverMerges({ top: 6, left: 6, bottom: 7, right: 7 }, merges)).toEqual({
      top: 6,
      left: 6,
      bottom: 7,
      right: 7,
    })
  })
})

describe("settleMerges", () => {
  const merges = [{ top: 2, left: 2, bottom: 4, right: 3 }]

  test("selects a merge's first cell when a move lands in it", () => {
    expect(settleMerges(selectionAt({ row: 1, col: 3 }), selectionAt({ row: 2, col: 3 }), merges)).toEqual(
      selectionAt({ row: 2, col: 2 }),
    )
  })

  test("steps past the merge it started in, in the direction of the move", () => {
    expect(settleMerges(selectionAt({ row: 2, col: 2 }), selectionAt({ row: 3, col: 2 }), merges)).toEqual(
      selectionAt({ row: 5, col: 2 }),
    )
    expect(settleMerges(selectionAt({ row: 2, col: 2 }), selectionAt({ row: 2, col: 1 }), merges)).toEqual(
      selectionAt({ row: 2, col: 1 }),
    )
    expect(settleMerges(selectionAt({ row: 2, col: 2 }), selectionAt({ row: 2, col: 3 }), merges)).toEqual(
      selectionAt({ row: 2, col: 4 }),
    )
  })

  test("leaves a range selection and a move clear of merges as they are", () => {
    const range = { anchor: { row: 0, col: 0 }, focus: { row: 3, col: 3 } }
    const clear = selectionAt({ row: 8, col: 8 })

    expect(settleMerges(selectionAt({ row: 0, col: 0 }), range, merges)).toBe(range)
    expect(settleMerges(selectionAt({ row: 7, col: 8 }), clear, merges)).toBe(clear)
  })
})

describe("skipHidden", () => {
  const hidden = { rows: [{ start: 2, end: 3 }], columns: [{ start: 0, end: 1 }] }

  test("moves on past hidden rows in the direction of the move", () => {
    expect(skipHidden({ row: 1, col: 4 }, selectionAt({ row: 2, col: 4 }), hidden)).toEqual(
      selectionAt({ row: 4, col: 4 }),
    )
    expect(skipHidden({ row: 4, col: 4 }, selectionAt({ row: 3, col: 4 }), hidden)).toEqual(
      selectionAt({ row: 1, col: 4 }),
    )
  })

  test("stays where it started when only hidden cells lie ahead", () => {
    expect(skipHidden({ row: 0, col: 2 }, selectionAt({ row: 0, col: 1 }), hidden)).toEqual(
      selectionAt({ row: 0, col: 2 }),
    )
  })

  test("keeps a range's anchor and a selection already clear", () => {
    const range = { anchor: { row: 0, col: 4 }, focus: { row: 2, col: 4 } }
    const clear = selectionAt({ row: 6, col: 6 })

    expect(skipHidden({ row: 1, col: 4 }, range, hidden)).toEqual({
      anchor: { row: 0, col: 4 },
      focus: { row: 4, col: 4 },
    })
    expect(skipHidden({ row: 5, col: 6 }, clear, hidden)).toBe(clear)
  })
})

import type { XlsxAnchor } from "@betteroffice/xlsx"
import { selectionAt, type CellAddr, type CellRange, type Selection } from "@betteroffice/xlsx/headless"

/** The sheet's last cell, zero-based: row 1,048,576 in column XFD. */
export const lastCell = { row: 1048575, col: 16383 }

/** A column's letters, such as "A", "Z" or "AA". */
export function columnName(index: number): string {
  return (index < 26 ? "" : columnName(Math.floor(index / 26) - 1)) + String.fromCharCode(65 + (index % 26))
}

/** The cells an export anchor names: one range for a cell or range anchor, none for any other kind. */
export function anchorRange(anchor: XlsxAnchor): CellRange[] {
  if (anchor.kind !== "cell" && anchor.kind !== "range") return []

  const range = parseRange(anchor.a1)

  return range ? [range] : []
}

/** An A1 cell or range, such as "B2" or "A1:F20"; undefined for anything else. */
export function parseRange(a1: string): CellRange | undefined {
  // A lone cell is its own last corner; an empty one, as in "A1:", names no range.
  const corners = a1.split(":")
  const first = parseCell(corners[0] ?? "")
  const last = corners.length === 1 ? first : parseCell(corners[1] ?? "")

  if (!first || !last) return undefined

  return {
    top: Math.min(first.row, last.row),
    left: Math.min(first.col, last.col),
    bottom: Math.max(first.row, last.row),
    right: Math.max(first.col, last.col),
  }
}

/** Grows a range until it covers every merged cell it touches, as Excel selects. */
export function coverMerges(range: CellRange, merges: readonly CellRange[]): CellRange {
  const grown = merges.reduce(
    (current, merge) =>
      overlaps(current, merge)
        ? {
            top: Math.min(current.top, merge.top),
            left: Math.min(current.left, merge.left),
            bottom: Math.max(current.bottom, merge.bottom),
            right: Math.max(current.right, merge.right),
          }
        : current,
    range,
  )

  // A merge the range grew into can touch another one it did not reach before.
  if (same(grown, range)) return grown

  return coverMerges(grown, merges)
}

/**
 * Moves a collapsed selection the way Excel moves its active cell around merged cells: landing in one selects its
 * first cell, and a step that stays inside the merged cell it started from steps past it.
 */
export function settleMerges(previous: Selection, next: Selection, merges: readonly CellRange[]): Selection {
  if (!collapsed(next)) return next

  const merge = merges.find((candidate) => contains(candidate, next.focus))

  if (!merge) return next

  if (!collapsed(previous) || !contains(merge, previous.focus)) return selectionAt({ row: merge.top, col: merge.left })

  const cell = {
    row: Math.min(lastCell.row, Math.max(0, past(previous.focus.row, next.focus.row, merge.top, merge.bottom))),
    col: Math.min(lastCell.col, Math.max(0, past(previous.focus.col, next.focus.col, merge.left, merge.right))),
  }

  const landed = merges.find((candidate) => contains(candidate, cell))

  return selectionAt(landed ? { row: landed.top, col: landed.left } : cell)
}

/** A run of hidden rows or columns, zero-based and inclusive. */
export type Span = { readonly start: number; readonly end: number }

/** Hidden row spans such as "5:7", or column spans such as "C:D", as the export lists them. */
export function parseSpans(spans: readonly string[], axis: "rows" | "columns"): Span[] {
  return spans.flatMap((span) => {
    const [first = "", last = first] = span.split(":")
    const start = axis === "rows" ? Number(first) - 1 : columnIndex(first)
    const end = axis === "rows" ? Number(last) - 1 : columnIndex(last)

    return Number.isInteger(start) && Number.isInteger(end) && start >= 0 && end >= start ? [{ start, end }] : []
  })
}

/**
 * Moves a selection's focus off hidden rows and columns, on in the direction it moved, as Excel's arrow keys skip
 * them. A move that would leave the sheet stays where it started.
 */
export function skipHidden(
  from: CellAddr,
  selection: Selection,
  hidden: { readonly rows: readonly Span[]; readonly columns: readonly Span[] },
): Selection {
  const focus = {
    row: clear(from.row, selection.focus.row, hidden.rows, lastCell.row),
    col: clear(from.col, selection.focus.col, hidden.columns, lastCell.col),
  }

  if (focus.row === selection.focus.row && focus.col === selection.focus.col) return selection

  if (collapsed(selection)) return selectionAt(focus)

  return { anchor: selection.anchor, focus }
}

/** Whether a row or column lies in one of the hidden spans. */
export function hiddenAt(spans: readonly Span[], index: number) {
  return spans.some((span) => index >= span.start && index <= span.end)
}

/** Runs an engine call that throws on input it cannot take, such as a viewport with too many cells to draw. */
export function attempt<T>(run: () => T): T | undefined {
  try {
    return run()
  } catch {
    return undefined
  }
}

/** Whether a range holds a cell. */
export function contains(range: CellRange, cell: CellAddr) {
  return cell.row >= range.top && cell.row <= range.bottom && cell.col >= range.left && cell.col <= range.right
}

function parseCell(a1: string): CellAddr | undefined {
  const match = /^\$?([A-Z]{1,3})\$?([1-9]\d*)$/i.exec(a1)

  if (!match) return undefined

  const col = columnIndex(match[1])
  const row = Number(match[2]) - 1

  if (col > lastCell.col || row > lastCell.row) return undefined

  return { row, col }
}

/** A column's zero-based index from its letters; NaN for anything but one to three letters. */
function columnIndex(letters: string) {
  if (!/^[A-Z]{1,3}$/i.test(letters)) return Number.NaN

  return [...letters.toUpperCase()].reduce((total, letter) => total * 26 + letter.charCodeAt(0) - 64, 0) - 1
}

/** Where a move along one axis lands once past any hidden span it ended in. */
function clear(from: number, to: number, spans: readonly Span[], last: number): number {
  const span = spans.find((candidate) => to >= candidate.start && to <= candidate.end)

  if (!span || to === from) return to

  const next = to > from ? span.end + 1 : span.start - 1

  if (next < 0 || next > last) return from

  return clear(from, next, spans, last)
}

/** One step along an axis: past the merge's far edge in the direction of the move, or where it was. */
function past(from: number, to: number, low: number, high: number) {
  if (to > from) return high + 1

  if (to < from) return low - 1

  return from
}

function collapsed(selection: Selection) {
  return selection.anchor.row === selection.focus.row && selection.anchor.col === selection.focus.col
}

function overlaps(a: CellRange, b: CellRange) {
  return a.left <= b.right && a.right >= b.left && a.top <= b.bottom && a.bottom >= b.top
}

function same(a: CellRange, b: CellRange) {
  return a.top === b.top && a.left === b.left && a.bottom === b.bottom && a.right === b.right
}

import { paintDisplayList, type DisplayList, type GridMeta, type WorkbookHandle } from "@betteroffice/xlsx"
import { attempt } from "./sheet-cells"
import { frozenSize } from "./sheet-paint"
import type { SheetViewport } from "./sheet-protocol"

// The workbook worker's frames: the display lists of one viewport, split into tiles where the engine refuses it whole,
// and their painting.

/** The most tiles a side of a frame splits into before the frame gives up. */
const maxSplit = 8

/**
 * How far a tile reaches past each of its seams, in CSS pixels. The engine draws pane dividers and cut tracks at a
 * frame's edges, which the next tile has to cover, and the seam falls inside a device pixel.
 */
const seamOverlap = 8

/** Part of a frame: its display list, where its origin sits in the frame, and where it starts to show. */
type Tile = {
  readonly list: DisplayList
  readonly x: number
  readonly y: number
  readonly clipX: number
  readonly clipY: number
}

/**
 * A frame of cells: the tiles that draw it, one display list for its grid and links, without draw commands, and the
 * viewport it shows.
 */
export type Frame = { readonly list: DisplayList; readonly tiles: readonly Tile[]; readonly viewport: SheetViewport }

/**
 * The cells of one viewport, as the engine draws them; `undefined` when even its smallest tiles fail. A `wider`
 * viewport around it is drawn instead when the engine takes it whole.
 */
export function drawFrame(
  workbook: WorkbookHandle,
  viewport: SheetViewport,
  frozen: { readonly rows: number; readonly cols: number },
  wider?: SheetViewport,
): Frame | undefined {
  const around = wider && attempt(() => workbook.displayList(wider))

  if (wider && around)
    return { list: around, tiles: [{ list: around, x: 0, y: 0, clipX: 0, clipY: 0 }], viewport: wider }

  const whole = attempt(() => workbook.displayList(viewport))

  if (whole) return { list: whole, tiles: [{ list: whole, x: 0, y: 0, clipX: 0, clipY: 0 }], viewport }

  // The engine refuses a viewport with too many cells, as a wide pane of narrow columns has. One row and one column of
  // the frame give its tracks, and so where its frozen panes end.
  const columns = attempt(() => workbook.displayList({ ...viewport, height: 1 }).grid)
  const rows = attempt(() => workbook.displayList({ ...viewport, width: 1 }).grid)

  if (!columns || !rows) return undefined

  const grid = {
    startRow: rows.startRow,
    rowIndices: rows.rowIndices,
    rowOffsets: rows.rowOffsets,
    startCol: columns.startCol,
    colIndices: columns.colIndices,
    colOffsets: columns.colOffsets,
  }

  return tiled(workbook, viewport, frozenSize(grid, frozen), grid, 2)
}

/**
 * Draws a frame's tiles with the cells' top-left corner at `origin`, in device pixels, each tile from its seam on, so a
 * tile covers the panes it repeats.
 */
export function paintFrame(
  context: OffscreenCanvasRenderingContext2D,
  frame: Frame,
  input: { readonly ratio: number; readonly origin: { readonly x: number; readonly y: number } },
) {
  const ratio = input.ratio
  const origin = input.origin
  // SAFETY: the painter draws through the members a worker's 2D context shares with the window's. Only the window's
  // context type is declared, and it has focus and attribute members the worker's lacks, hence the double cast.
  // oxlint-disable-next-line anti-slop/no-chained-type-assertions -- see SAFETY above
  const painter = context as unknown as CanvasRenderingContext2D

  frame.tiles.forEach((tile) => {
    const at = { x: origin.x + tile.x * ratio, y: origin.y + tile.y * ratio }

    if (tile.clipX === 0 && tile.clipY === 0) return paintDisplayList(painter, tile.list, ratio, at)

    context.save()
    context.setTransform(1, 0, 0, 1, 0, 0)
    context.beginPath()
    context.rect(
      Math.round(origin.x + tile.clipX * ratio),
      Math.round(origin.y + tile.clipY * ratio),
      context.canvas.width,
      context.canvas.height,
    )
    context.clip()
    paintDisplayList(painter, tile.list, ratio, at)
    context.restore()
  })
}

/**
 * A frame split into `split` tiles a side, each under the engine's cap. A tile past the first along an axis asks for
 * the frozen panes too, as every viewport has them, so the cells past them start just before its seam.
 */
function tiled(
  workbook: WorkbookHandle,
  viewport: SheetViewport,
  panes: { readonly width: number; readonly height: number },
  grid: GridMeta,
  split: number,
): Frame | undefined {
  const columns = segments(viewport.width, panes.width, split)
  const rows = segments(viewport.height, panes.height, split)
  const tiles: Tile[] = []

  const complete = rows.every((row) =>
    columns.every((column) => {
      const x = column.start === 0 ? 0 : column.start - seamOverlap - panes.width
      const y = row.start === 0 ? 0 : row.start - seamOverlap - panes.height
      // A tile but the last along an axis reaches past its end, which the next tile paints over.
      const right = column.end === viewport.width ? column.end : column.end + seamOverlap
      const bottom = row.end === viewport.height ? row.end : row.end + seamOverlap

      const list = attempt(() =>
        workbook.displayList({ x: viewport.x + x, y: viewport.y + y, width: right - x, height: bottom - y }),
      )

      if (list) tiles.push({ list, x, y, clipX: column.start, clipY: row.start })

      return !!list
    }),
  )

  if (complete) {
    const hyperlinks = tiles.flatMap((tile) => tile.list.hyperlinks ?? [])

    return { list: { width: viewport.width, height: viewport.height, commands: [], grid, hyperlinks }, tiles, viewport }
  }

  if (split >= maxSplit) return undefined

  return tiled(workbook, viewport, panes, grid, split + 1)
}

/** Even spans of a side, the first holding the frozen panes whole; a seam inside them is dropped. */
function segments(size: number, panes: number, split: number) {
  const starts = Array.from({ length: split }, (_, part) => Math.round((part * size) / split)).filter(
    (start, part) => part === 0 || (start >= panes + seamOverlap && start < size),
  )

  return starts.map((start, part) => ({ start, end: starts[part + 1] ?? size }))
}

import { rangeRect, type CellRange, type GridMeta } from "@betteroffice/xlsx/headless"
import { columnName } from "./sheet-cells"
import type { SheetFrame, SheetFrameRequest } from "./sheet-protocol"

/** Excel's light headers and green selection. The sheet keeps them on its white paper in every theme. */
const colours = {
  header: "#f5f5f5",
  label: "#5c5c5c",
  line: "#d4d4d4",
  edge: "#bdbdbd",
  corner: "#c8c8c8",
  selectedHeader: "#d3ecdd",
  selectedLabel: "#185c37",
  accent: "#217346",
  selection: "rgba(33, 115, 70, 0.12)",
}

const font = "11px ui-sans-serif, system-ui, sans-serif"

/** The height of the column headers, in CSS pixels. */
export const headerHeight = 20

/** The sizes of the header strips, in CSS pixels: the row headers' width and the column headers' height. */
export type Headers = { readonly width: number; readonly height: number }

/**
 * The frozen panes' size in a frame: the offset of the first track past them. Without panes, the first track can start
 * before the frame, part of it scrolled away.
 */
export function frozenSize(grid: GridMeta | undefined, frozen: { readonly rows: number; readonly cols: number }) {
  if (!grid) return { width: 0, height: 0 }

  const pane = (offsets: readonly number[], start: number, indices: readonly number[] | undefined, count: number) => {
    if (count === 0) return 0

    const first = offsets.findIndex(
      (_, position) => position === offsets.length - 1 || trackIndex(start, indices, position) >= count,
    )

    return Math.max(0, offsets[first] ?? 0)
  }

  return {
    width: pane(grid.colOffsets, grid.startCol, grid.colIndices, frozen.cols),
    height: pane(grid.rowOffsets, grid.startRow, grid.rowIndices, frozen.rows),
  }
}

/** A frame from the workbook worker and the request it answers, which says where its cells sit. */
export type Painted = { readonly request: SheetFrameRequest; readonly frame: SheetFrame }

/**
 * Draws a frame's cells beside the headers at the current scroll position. A frame painted at another position, as one
 * is while the next renders, moves with the scroll: the frozen panes stay put and the cells past them shift, leaving
 * the paper where the frame has no cells yet.
 */
export function paintCells(
  context: CanvasRenderingContext2D,
  painted: Painted,
  input: {
    readonly ratio: number
    readonly headers: Headers
    readonly x: number
    readonly y: number
    readonly width: number
    readonly height: number
  },
) {
  const request = painted.request
  const bitmap = painted.frame.bitmap
  const panes = painted.frame.frozen
  const ratio = input.ratio
  const scale = ratio / request.ratio
  const origin = { x: input.headers.width * ratio, y: input.headers.height * ratio }

  // Each side splits at the frozen panes: the panes stay put, the cells past them follow the scroll.
  const columns = [
    { start: 0, end: Math.min(panes.width, input.width), shift: 0 },
    { start: panes.width, end: input.width, shift: painted.frame.viewport.x - input.x },
  ]

  const rows = [
    { start: 0, end: Math.min(panes.height, input.height), shift: 0 },
    { start: panes.height, end: input.height, shift: painted.frame.viewport.y - input.y },
  ]

  // The whole canvas clears, headers included: their edges cover part of a device pixel, which would darken with every
  // paint drawn over the last.
  context.save()
  context.setTransform(1, 0, 0, 1, 0, 0)
  context.clearRect(0, 0, context.canvas.width, context.canvas.height)

  rows.forEach((row) =>
    columns.forEach((column) => {
      if (row.end <= row.start || column.end <= column.start) return

      const left = Math.round(origin.x + column.start * ratio)
      const top = Math.round(origin.y + row.start * ratio)

      context.save()
      context.beginPath()
      context.rect(
        left,
        top,
        Math.round(origin.x + column.end * ratio) - left,
        Math.round(origin.y + row.end * ratio) - top,
      )
      context.clip()
      // Whole device pixels, so a frame at its own position lands exactly where the worker painted its cells.
      context.drawImage(
        bitmap,
        Math.round(origin.x + column.shift * ratio - request.offset.x * scale),
        Math.round(origin.y + row.shift * ratio - request.offset.y * scale),
        bitmap.width * scale,
        bitmap.height * scale,
      )
      context.restore()
    }),
  )

  context.restore()
}

/**
 * A frame's grid at another scroll position, moved as `paintCells` moves its cells: the tracks past the frozen panes
 * shift by `shift`, and never under the panes, so headers, selection and hit tests follow the cells on screen.
 */
export function shiftGrid(
  grid: GridMeta,
  frozen: { readonly rows: number; readonly cols: number },
  panes: { readonly width: number; readonly height: number },
  shift: { readonly x: number; readonly y: number },
): GridMeta {
  if (shift.x === 0 && shift.y === 0) return grid

  const axis = (
    offsets: readonly number[],
    start: number,
    indices: readonly number[] | undefined,
    count: number,
    edge: number,
    by: number,
  ) => {
    // The offsets up to the panes' far edge belong to the panes; without panes, every track moves.
    const fixed = count === 0 ? -1 : offsets.findIndex((_, position) => trackIndex(start, indices, position) >= count)

    return offsets.map((offset, position) => {
      if (fixed === -1 && count > 0) return offset

      if (position <= fixed) return offset

      return count === 0 ? offset + by : Math.max(edge, offset + by)
    })
  }

  return {
    ...grid,
    colOffsets: axis(grid.colOffsets, grid.startCol, grid.colIndices, frozen.cols, panes.width, shift.x),
    rowOffsets: axis(grid.rowOffsets, grid.startRow, grid.rowIndices, frozen.rows, panes.height, shift.y),
  }
}

/** The sheet row or column at a position in a frame's grid: its indices when tracks are skipped, else consecutive. */
export function trackIndex(start: number, indices: readonly number[] | undefined, position: number) {
  return indices?.[position] ?? start + position
}

/** The width of the row headers that fits row numbers up to `rows`, as Excel widens them for longer numbers. */
export function rowHeaderWidth(context: CanvasRenderingContext2D, rows: number) {
  context.font = font

  return Math.max(28, Math.ceil(context.measureText(String(rows)).width) + 12)
}

/**
 * Draws the column letters and row numbers of a frame's tracks, frozen panes first, along the top and left edges.
 * Hidden tracks have no width in the grid, so they get no header.
 */
export function paintHeaders(
  context: CanvasRenderingContext2D,
  input: {
    readonly grid: GridMeta
    readonly ratio: number
    readonly headers: Headers
    readonly width: number
    readonly height: number
    readonly selected: CellRange | undefined
  },
) {
  const grid = input.grid
  const headers = input.headers
  const selected = input.selected

  context.save()
  context.setTransform(input.ratio, 0, 0, input.ratio, 0, 0)
  context.fillStyle = colours.header
  context.fillRect(0, 0, input.width, headers.height)
  context.fillRect(0, 0, headers.width, input.height)
  context.font = font
  context.textAlign = "center"
  context.textBaseline = "middle"

  grid.colOffsets.slice(0, -1).forEach((offset, position) => {
    const index = trackIndex(grid.startCol, grid.colIndices, position)

    paintHeader(context, {
      x: headers.width + offset,
      y: 0,
      width: grid.colOffsets[position + 1] - offset,
      height: headers.height,
      label: columnName(index),
      selected: !!selected && index >= selected.left && index <= selected.right,
      clip: { x: headers.width, width: input.width - headers.width },
    })
  })
  grid.rowOffsets.slice(0, -1).forEach((offset, position) => {
    const index = trackIndex(grid.startRow, grid.rowIndices, position)

    paintHeader(context, {
      x: 0,
      y: headers.height + offset,
      width: headers.width,
      height: grid.rowOffsets[position + 1] - offset,
      label: String(index + 1),
      selected: !!selected && index >= selected.top && index <= selected.bottom,
      clip: { y: headers.height, height: input.height - headers.height },
    })
  })

  line(context, colours.edge, 0, headers.height, input.width, headers.height)
  line(context, colours.edge, headers.width, 0, headers.width, input.height)
  // Excel's select-all corner: a small triangle pointing at the cells.
  context.fillStyle = colours.corner
  context.beginPath()
  context.moveTo(headers.width - 4, headers.height - 12)
  context.lineTo(headers.width - 4, headers.height - 4)
  context.lineTo(headers.width - 12, headers.height - 4)
  context.closePath()
  context.fill()
  context.restore()
}

/** Outlines the selected range and tints it, leaving its active cell clear, in the cells beside the headers. */
export function paintSelection(
  context: CanvasRenderingContext2D,
  input: {
    readonly grid: GridMeta
    readonly ratio: number
    readonly headers: Headers
    readonly width: number
    readonly height: number
    readonly range: CellRange
    readonly active: CellRange
  },
) {
  const range = rangeRect(input.grid, input.range)

  if (!range) return

  const active = rangeRect(input.grid, input.active)

  context.save()
  context.setTransform(
    input.ratio,
    0,
    0,
    input.ratio,
    input.headers.width * input.ratio,
    input.headers.height * input.ratio,
  )
  context.beginPath()
  context.rect(0, 0, input.width, input.height)
  context.clip()

  if (!sameRect(range, active)) {
    context.beginPath()
    context.rect(range.x, range.y, range.w, range.h)

    if (active) context.rect(active.x, active.y, active.w, active.h)

    context.fillStyle = colours.selection
    context.fill("evenodd")
  }

  context.strokeStyle = colours.accent
  context.lineWidth = 2
  context.strokeRect(range.x, range.y, range.w, range.h)
  context.restore()
}

function paintHeader(
  context: CanvasRenderingContext2D,
  header: {
    readonly x: number
    readonly y: number
    readonly width: number
    readonly height: number
    readonly label: string
    readonly selected: boolean
    readonly clip: { readonly x?: number; readonly y?: number; readonly width?: number; readonly height?: number }
  },
) {
  if (header.width <= 0 || header.height <= 0) return

  const columns = header.y === 0

  context.save()
  context.beginPath()
  context.rect(
    header.clip.x ?? header.x,
    header.clip.y ?? header.y,
    header.clip.width ?? header.width,
    header.clip.height ?? header.height,
  )
  context.clip()

  // A selected header is tinted, with a bar on the edge that meets the cells.
  if (header.selected) {
    context.fillStyle = colours.selectedHeader
    context.fillRect(header.x, header.y, header.width, header.height)
    context.fillStyle = colours.accent
    context.fillRect(
      columns ? header.x : header.x + header.width - 2,
      columns ? header.y + header.height - 2 : header.y,
      columns ? header.width : 2,
      columns ? 2 : header.height,
    )
  }

  // A track too small for its label shows none, rather than labels piled over each other.
  if (columns ? context.measureText(header.label).width + 2 <= header.width : header.height >= 9) {
    context.fillStyle = header.selected ? colours.selectedLabel : colours.label
    context.fillText(header.label, header.x + header.width / 2, header.y + header.height / 2 + 0.5)
  }

  context.restore()

  // The line after the header, where the gridline between its cells and the next ones meets it.
  const x = columns ? header.x + header.width : header.x
  const y = columns ? header.y : header.y + header.height

  line(context, colours.line, x, y, columns ? x : x + header.width, columns ? y + header.height : y)
}

/** A one-pixel line centred on its coordinates, as the display list draws gridlines, so the two meet. */
function line(context: CanvasRenderingContext2D, colour: string, x1: number, y1: number, x2: number, y2: number) {
  context.strokeStyle = colour
  context.lineWidth = 1
  context.beginPath()
  context.moveTo(x1, y1)
  context.lineTo(x2, y2)
  context.stroke()
}

function sameRect(a: { x: number; y: number; w: number; h: number }, b: typeof a | null) {
  return !!b && a.x === b.x && a.y === b.y && a.w === b.w && a.h === b.h
}

import type { PositionedTextRun, PresentationHandle, SlideDisplayList, SlidePrimitive } from "@betteroffice/pptx"
import { loadFace, presentationFace, scriptFace } from "./fonts"
import type { DeckText, FallbackScript, FontStyle } from "./slide-text"

/** A face the deck asks for: a family it names, or the fallback for a script the Latin faces lack. */
type Want =
  | { readonly family: string; readonly script?: undefined }
  | { readonly script: FallbackScript; readonly family?: undefined }

/** A face registered with both the engine and the browser. */
type Face = { readonly want: Want; readonly style: FontStyle; readonly css: string }

/**
 * The faces one open deck draws with, added to `fonts`: the font set of the deck's own worker, which paints it. The
 * engine shapes each face under the family name the deck uses, and the browser holds the same bytes under a private
 * name that the laid-out frames are renamed to. Painting then matches shaping, and the deck's names (such as Inter or
 * Segoe UI) never replace a font the painter itself needs.
 */
export function slideFonts(deck: PresentationHandle, fonts: FontFaceSet) {
  const faces = new Map<number, Face>()
  const names = new Map<string, string>()
  const registered = new Set<string>()
  const loads = new Map<string, Promise<void>>()
  const settled = new Set<string>()

  /** Loads a face's bytes and browser face; the returned function registers both, so callers choose the order. */
  const prepare = async (want: Want, requested: FontStyle) => {
    const source = want.script
      ? scriptFace(want.script, requested.bold, requested.italic)
      : presentationFace(want.family, requested.bold, requested.italic)

    if (!source) return

    // A family without the requested style gets the face it has, which the browser then slants or emboldens.
    const style = { bold: source.weight === 700, italic: source.style === "italic" }
    // The worker holds this deck's faces alone, so the names only need to differ from each other.
    const css = names.get(wantKey(want)) ?? `slide-${names.size}`
    const key = faceKey(want, style)

    names.set(wantKey(want), css)

    if (registered.has(key)) return

    const buffer = await loadFace(source).catch(() => undefined)

    if (!buffer) return

    const browser = await new FontFace(css, buffer, {
      weight: style.bold ? "700" : "400",
      style: style.italic ? "italic" : "normal",
    })
      .load()
      .catch(() => undefined)

    if (!browser) return

    return () => {
      if (registered.has(key)) return

      registered.add(key)
      fonts.add(browser)

      const face = { family: want.script ? css : want.family, ...style, bytes: new Uint8Array(buffer) }

      faces.set(want.script ? deck.registerFallbackFont(face) : deck.registerFont(face), { want, style, css })
    }
  }

  /** Loads and registers one face once; later requests share the first. */
  const request = (want: Want, style: FontStyle) => {
    const key = faceKey(want, style)
    const existing = loads.get(key)

    if (existing) return existing

    const load = prepare(want, style).then((register) => {
      register?.()
      settled.add(key)
    })

    loads.set(key, load)

    return load
  }

  /** The faces a frame drew in a substitute style whose own face has not loaded or failed yet. */
  const missing = (primitives: readonly SlidePrimitive[]) =>
    textRuns(primitives).flatMap((run) => {
      const face = faces.get(run.fontId)
      const style = { bold: run.bold, italic: run.italic }

      if (!face || sameStyle(face.style, style) || settled.has(faceKey(face.want, style))) return []

      return [{ want: face.want, style }]
    })

  const rename = (primitive: SlidePrimitive): SlidePrimitive => {
    if (primitive.kind === "textBox")
      return {
        ...primitive,
        lines: primitive.lines.map((line) => ({
          ...line,
          runs: line.runs.map((run) => ({ ...run, fontFamily: faces.get(run.fontId)?.css ?? run.fontFamily })),
        })),
      }

    if (primitive.kind === "table" || primitive.kind === "chart")
      return { ...primitive, primitives: primitive.primitives.map(rename) }

    return primitive
  }

  return {
    /**
     * Registers the faces the deck's text names, in the order `text` ranks them: the engine draws every family it
     * cannot find with the first. Resolves once each face has loaded or failed.
     */
    load: async (text: DeckText) => {
      const regular = { bold: false, italic: false }
      // The engine lays no text out without a face, so a deck that names none gets PowerPoint's own default.
      const families = text.families.length > 0 ? text.families : [{ name: "Calibri", styles: [regular] }]

      const wants: { want: Want; style: FontStyle }[] = [
        ...families.flatMap((family) => family.styles.map((style) => ({ want: { family: family.name }, style }))),
        ...text.scripts.map((script) => ({ want: { script }, style: regular })),
      ]

      const registers = await Promise.all(wants.map((entry) => prepare(entry.want, entry.style)))

      registers.forEach((register) => register?.())
      wants.forEach((entry) => {
        const key = faceKey(entry.want, entry.style)

        loads.set(key, Promise.resolve())
        settled.add(key)
      })
    },

    /**
     * Lays a slide out. When its text asks for a style a registered face lacks, such as a bold the title style
     * inherits, that face loads and the slide lays out again. The frame names the browser's faces, ready to paint.
     */
    layout: async (index: number) => {
      const settle = async (rounds: number): Promise<SlideDisplayList> => {
        const frame = deck.layoutSlide(index)
        const wanted = rounds === 0 ? [] : missing(frame.primitives)

        if (wanted.length === 0) return { ...frame, primitives: frame.primitives.map(rename) }

        await Promise.all(wanted.map((entry) => request(entry.want, entry.style)))

        return settle(rounds - 1)
      }

      return settle(2)
    },
  }
}

function textRuns(primitives: readonly SlidePrimitive[]): PositionedTextRun[] {
  return primitives.flatMap((primitive) => {
    if (primitive.kind === "textBox") return primitive.lines.flatMap((line) => line.runs)

    if (primitive.kind === "table" || primitive.kind === "chart") return textRuns(primitive.primitives)

    return []
  })
}

function wantKey(want: Want) {
  return want.script ? `script:${want.script}` : `family:${want.family.toLowerCase()}`
}

function faceKey(want: Want, style: FontStyle) {
  return `${wantKey(want)}|${style.bold}|${style.italic}`
}

function sameStyle(left: FontStyle, right: FontStyle) {
  return left.bold === right.bold && left.italic === right.italic
}

import { describe, expect, test } from "bun:test"
import { withoutMedia } from "./slide-text"

type File = { readonly name: string; readonly text: string }

const files: readonly File[] = [
  { name: "[Content_Types].xml", text: "<Types/>" },
  { name: "ppt/media/image1.png", text: "png bytes" },
  { name: "ppt/presentation.xml", text: "<p:presentation/>" },
  { name: "ppt/media/image2.jpeg", text: "jpeg bytes" },
  { name: "ppt/slides/slide1.xml", text: "<p:sld>Hello</p:sld>" },
]

describe("withoutMedia", () => {
  test("drops the media entries and keeps every other entry readable", () => {
    const stripped = withoutMedia(zip(files))

    expect(read(stripped)).toEqual(
      files.flatMap((file) => (file.name.startsWith("ppt/media/") ? [] : [{ ...file, crc: crc(file.text) }])),
    )
  })

  test("reads a package that is a slice of a larger buffer", () => {
    const archive = zip(files)
    const padded = new Uint8Array(archive.length + 16)

    padded.set(archive, 7)

    expect(read(withoutMedia(padded.subarray(7, 7 + archive.length))).map((file) => file.name)).toEqual([
      "[Content_Types].xml",
      "ppt/presentation.xml",
      "ppt/slides/slide1.xml",
    ])
  })

  test("returns a package without media as it is", () => {
    const archive = zip(files.filter((file) => !file.name.startsWith("ppt/media/")))

    expect(withoutMedia(archive)).toBe(archive)
  })

  test("returns bytes that are not a zip package as they are", () => {
    const empty = new Uint8Array(0)
    const text = new TextEncoder().encode("not a zip archive, only some text that is long enough to search")

    expect(withoutMedia(empty)).toBe(empty)
    expect(withoutMedia(text)).toBe(text)
  })

  test("returns a ZIP64 package as it is", () => {
    const counted = zip(files)
    const offset = zip(files)
    const local = zip(files)

    end(counted).setUint16(10, 0xffff, true)
    end(offset).setUint32(16, 0xffffffff, true)
    record(local, 2).setUint32(42, 0xffffffff, true)

    expect(withoutMedia(counted)).toBe(counted)
    expect(withoutMedia(offset)).toBe(offset)
    expect(withoutMedia(local)).toBe(local)
  })

  test("returns a truncated package as it is", () => {
    const archive = zip(files)
    const cut = archive.subarray(0, archive.length - 30)

    expect(withoutMedia(cut)).toBe(cut)
  })

  test("returns a package with a malformed central directory as it is", () => {
    const missing = zip(files)
    const misplaced = zip(files)
    const longName = zip(files)
    const longExtra = zip(files)
    const pastDirectory = zip(files)
    const atDirectory = zip(files)

    // More records than the directory holds: the end record follows the last one.
    end(missing).setUint16(10, files.length + 1, true)
    end(misplaced).setUint32(16, 3, true)
    // The last record's name, then its extra field, run past the directory into the end record and beyond the file.
    record(longName, files.length - 1).setUint16(28, 0xffff, true)
    record(longExtra, files.length - 1).setUint16(30, 40, true)
    // A kept entry's local header at or past the directory.
    record(pastDirectory, 0).setUint32(42, end(pastDirectory).getUint32(16, true) + 100, true)
    record(atDirectory, 2).setUint32(42, end(atDirectory).getUint32(16, true), true)

    expect(withoutMedia(missing)).toBe(missing)
    expect(withoutMedia(misplaced)).toBe(misplaced)
    expect(withoutMedia(longName)).toBe(longName)
    expect(withoutMedia(longExtra)).toBe(longExtra)
    expect(withoutMedia(pastDirectory)).toBe(pastDirectory)
    expect(withoutMedia(atDirectory)).toBe(atDirectory)
  })
})

/** A stored (uncompressed) zip package of the files, without a comment. */
function zip(entries: readonly File[]) {
  const encoder = new TextEncoder()

  const parts = entries.map((entry) => ({
    name: encoder.encode(entry.name),
    data: encoder.encode(entry.text),
    crc: crc(entry.text),
  }))

  const locals = parts.map((part) => {
    const local = new Uint8Array(30 + part.name.length + part.data.length)
    const view = new DataView(local.buffer)

    view.setUint32(0, 0x04034b50, true)
    view.setUint16(4, 20, true)
    view.setUint32(14, part.crc, true)
    view.setUint32(18, part.data.length, true)
    view.setUint32(22, part.data.length, true)
    view.setUint16(26, part.name.length, true)
    local.set(part.name, 30)
    local.set(part.data, 30 + part.name.length)

    return local
  })

  const starts = locals.map((_, index) => locals.slice(0, index).reduce((total, local) => total + local.length, 0))
  const directory = locals.reduce((total, local) => total + local.length, 0)

  const records = parts.map((part, index) => {
    const entry = new Uint8Array(46 + part.name.length)
    const view = new DataView(entry.buffer)

    view.setUint32(0, 0x02014b50, true)
    view.setUint16(4, 20, true)
    view.setUint16(6, 20, true)
    view.setUint32(16, part.crc, true)
    view.setUint32(20, part.data.length, true)
    view.setUint32(24, part.data.length, true)
    view.setUint16(28, part.name.length, true)
    view.setUint32(42, starts[index] ?? 0, true)
    entry.set(part.name, 46)

    return entry
  })

  const size = records.reduce((total, entry) => total + entry.length, 0)
  const tail = new Uint8Array(22)
  const view = new DataView(tail.buffer)

  view.setUint32(0, 0x06054b50, true)
  view.setUint16(8, parts.length, true)
  view.setUint16(10, parts.length, true)
  view.setUint32(12, size, true)
  view.setUint32(16, directory, true)

  const out = new Uint8Array(directory + size + 22)

  ;[...locals, ...records, tail].reduce((at, chunk) => {
    out.set(chunk, at)

    return at + chunk.length
  }, 0)

  return out
}

/** Reads every entry of a stored package through its central directory and local headers, as an unzipper does. */
function read(bytes: Uint8Array) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
  const decoder = new TextDecoder()
  const last = bytes.length - 22

  expect(view.getUint32(last, true)).toBe(0x06054b50)
  expect(view.getUint16(last + 8, true)).toBe(view.getUint16(last + 10, true))

  const count = view.getUint16(last + 10, true)
  const directory = view.getUint32(last + 16, true)

  expect(directory + view.getUint32(last + 12, true)).toBe(last)

  return Array.from({ length: count }).reduce<{ at: number; files: (File & { crc: number })[] }>(
    (state) => {
      expect(view.getUint32(state.at, true)).toBe(0x02014b50)

      const nameLength = view.getUint16(state.at + 28, true)
      const name = decoder.decode(bytes.subarray(state.at + 46, state.at + 46 + nameLength))
      const local = view.getUint32(state.at + 42, true)
      const size = view.getUint32(state.at + 20, true)

      expect(view.getUint32(local, true)).toBe(0x04034b50)
      expect(decoder.decode(bytes.subarray(local + 30, local + 30 + view.getUint16(local + 26, true)))).toBe(name)

      const data = local + 30 + view.getUint16(local + 26, true) + view.getUint16(local + 28, true)
      const text = decoder.decode(bytes.subarray(data, data + size))

      expect(crc(text)).toBe(view.getUint32(state.at + 16, true))
      state.files.push({ name, text, crc: view.getUint32(local + 14, true) })

      const length = 46 + nameLength + view.getUint16(state.at + 30, true) + view.getUint16(state.at + 32, true)

      return { at: state.at + length, files: state.files }
    },
    { at: directory, files: [] },
  ).files
}

function crc(text: string) {
  return Bun.hash.crc32(new TextEncoder().encode(text))
}

/** The end of central directory record of a package built by `zip`. */
function end(bytes: Uint8Array) {
  return new DataView(bytes.buffer, bytes.byteOffset + bytes.length - 22, 22)
}

/** The central directory record of a package built by `zip`, by index. */
function record(bytes: Uint8Array, index: number) {
  const directory = end(bytes).getUint32(16, true)
  const view = new DataView(bytes.buffer, bytes.byteOffset)

  const at = Array.from({ length: index }).reduce<number>(
    (current) => current + 46 + view.getUint16(current + 28, true),
    directory,
  )

  return new DataView(bytes.buffer, bytes.byteOffset + at)
}

import { Option, Schema } from "effect"
import { inspectPresentation, type DeckSnapshot } from "@betteroffice/pptx"

/** A text style a deck draws with. */
export type FontStyle = { readonly bold: boolean; readonly italic: boolean }

/** A family the deck names, with the styles its text asks for. */
export type DeckFamily = { readonly name: string; readonly styles: readonly FontStyle[] }

/** The scripts the bundled Latin faces may lack, which have a bundled fallback face. */
export type FallbackScript = "hebrew" | "arabic"

/** What a deck's text needs from the fonts, and which slides it hides. */
export type DeckText = {
  /** Most important first: the face registered first also draws every family the deck names but nobody found. */
  readonly families: readonly DeckFamily[]
  readonly scripts: readonly FallbackScript[]
  /** One flag per slide, in deck order. */
  readonly hidden: readonly boolean[]
}

const RunStyle = Schema.Struct({
  bold: Schema.optional(Schema.NullOr(Schema.Boolean)),
  italic: Schema.optional(Schema.NullOr(Schema.Boolean)),
  fontFamily: Schema.optional(Schema.NullOr(Schema.String)),
})

const Body = Schema.Struct({
  paragraphs: Schema.Array(
    Schema.Struct({
      runs: Schema.Array(Schema.Struct({ text: Schema.String, properties: Schema.optional(Schema.NullOr(RunStyle)) })),
    }),
  ),
})

type Drawing = {
  readonly text?: typeof Body.Type | null | undefined
  readonly children?: readonly Drawing[] | undefined
  readonly data?: typeof Table.Type | null | undefined
}

const Table = Schema.Struct({
  rows: Schema.optional(
    Schema.Array(Schema.Struct({ cells: Schema.Array(Schema.Struct({ text: Schema.optional(Schema.NullOr(Body)) })) })),
  ),
})

/** A slide object: a shape, group, picture or graphic frame. */
const Drawing: Schema.Codec<Drawing> = Schema.Struct({
  text: Schema.optional(Schema.NullOr(Body)),
  children: Schema.optional(Schema.Array(Schema.suspend((): Schema.Codec<Drawing> => Drawing))),
  // A table's cells; other frames, such as charts, carry no rows.
  data: Schema.optional(Schema.NullOr(Table)),
})

const ThemeFont = Schema.Struct({ latin: Schema.String })

const Inspected = Schema.Struct({
  slides: Schema.Array(
    Schema.Struct({ hidden: Schema.optional(Schema.Boolean), drawings: Schema.Array(Drawing) }).pipe(
      Schema.encodeKeys({ drawings: "shapes" }),
    ),
  ),
  layouts: Schema.optional(
    Schema.Array(Schema.Struct({ drawings: Schema.Array(Drawing) }).pipe(Schema.encodeKeys({ drawings: "shapes" }))),
  ),
  masters: Schema.optional(
    Schema.Array(
      Schema.Struct({
        drawings: Schema.Array(Drawing),
        textStyles: Schema.optional(
          Schema.NullOr(
            Schema.Record(
              Schema.String,
              Schema.Array(Schema.Struct({ defaultRun: Schema.optional(Schema.NullOr(RunStyle)) })),
            ),
          ),
        ),
      }).pipe(Schema.encodeKeys({ drawings: "shapes" })),
    ),
  ),
  themes: Schema.optional(
    Schema.Array(
      Schema.Struct({
        theme: Schema.optional(
          Schema.NullOr(
            Schema.Struct({
              fontScheme: Schema.optional(Schema.NullOr(Schema.Struct({ majorFont: ThemeFont, minorFont: ThemeFont }))),
            }),
          ),
        ),
      }),
    ),
  ),
})

const decodeInspected = Schema.decodeUnknownOption(Inspected)

const scriptRanges: readonly (readonly [FallbackScript, RegExp])[] = [
  ["hebrew", /[\u0590-\u05FF\uFB1D-\uFB4F]/u],
  ["arabic", /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/u],
]

/**
 * Reads the families, styles and scripts a deck's text uses, from its slides, layouts, masters and theme. When the
 * engine's inspection does not decode, the slides' own runs stand in, without theme fonts or hidden flags.
 */
export function deckText(bytes: Uint8Array, snapshot: DeckSnapshot): DeckText {
  return Option.match(decodeInspected(inspectPresentation(withoutMedia(bytes))), {
    onNone: () => fromSnapshot(snapshot),
    onSome: (inspected) => {
      const scheme = inspected.themes?.flatMap((theme) => (theme.theme?.fontScheme ? [theme.theme.fontScheme] : []))[0]
      const major = scheme?.majorFont.latin ?? ""
      const minor = scheme?.minorFont.latin ?? ""

      const drawings = [
        ...inspected.slides.flatMap((slide) => slide.drawings),
        ...(inspected.layouts ?? []).flatMap((layout) => layout.drawings),
        ...(inspected.masters ?? []).flatMap((master) => master.drawings),
      ]

      const defaults = (inspected.masters ?? []).flatMap((master) =>
        Object.values(master.textStyles ?? {}).flatMap((levels) =>
          levels.flatMap((level) => (level.defaultRun ? [{ text: "", style: level.defaultRun }] : [])),
        ),
      )

      return summarize(
        [...drawings.flatMap(drawingRuns), ...defaults],
        (family) => {
          if (!family || family.startsWith("+mn")) return minor

          if (family.startsWith("+mj")) return major

          if (family.startsWith("+")) return ""

          return family
        },
