    )
  }

  // A link to a hidden or missing sheet goes nowhere, as in Excel.
  const navigate = (name: string, cell: CellAddr) => {
    const tab = state.opened?.tabs.find((candidate) => candidate.name.toLowerCase() === name.toLowerCase())

