          const start = position.start
          const next = position.next

          const left =
            cell.col < info().frozenCols
              ? scroller.scrollLeft
              : place(start.x, next.x - start.x, scroller.scrollLeft, view.width - view.frozenWidth, align)

          const top =
            cell.row < info().frozenRows
              ? scroller.scrollTop
