    return (
      clear(rect.x, view.frozenWidth, cell.col < info().frozenCols) &&
      clear(rect.y, view.frozenHeight, cell.row < info().frozenRows) &&
      rect.x + rect.w <= view.width &&
      rect.y + rect.h <= view.height
