    const start = attempt(() => workbook.cellPosition(input.sheet, cell.row, cell.col))

    const next = attempt(() =>
      workbook.cellPosition(input.sheet, Math.min(cell.row + 1, lastCell.row), Math.min(cell.col + 1, lastCell.col)),
