/** Makes a sheet the active one and reads what its grid needs. */
function show(opened: Opened, sheet: number): SheetLayout {
  opened.workbook.setActiveSheet(sheet)
  opened.info = opened.workbook.sheetInfo()

  return { info: opened.info, ...layout(opened.workbook, sheet) }
}

/**
 * The used range, the merged cells, the hidden rows and columns, and how far the charts reach, from one export of the
 * sheet's metadata. One cell is enough: the lists before the cells are complete however soon the export stops.
 */
function layout(workbook: WorkbookHandle, sheet: number) {
  const result = attempt(() =>
    workbook.exportStructured({
      scope: [{ sheet, range: "A1:XFD1048576" }],
      maxCells: 1,
      includeDefinedNames: false,
    }),
  )

  const exported = result?.ok ? result.content.sheets[0] : undefined

  const charts = (exported?.objects ?? [])
    .filter((object) => object.kind === "chart" && !object.hidden)
    .flatMap((object) => (object.anchor ? anchorRange(object.anchor) : []))
    // The corner cell holds the chart's edge somewhere inside it, so the cell past it bounds the chart.
    .flatMap((range) => {
      const corner = attempt(() =>
        workbook.cellPosition(sheet, Math.min(range.bottom + 1, lastCell.row), Math.min(range.right + 1, lastCell.col)),
      )

      return corner ? [corner] : []
    })

  return {
    used: exported?.usedRange ? parseRange(exported.usedRange) : undefined,
    merges: (exported?.merges ?? []).flatMap((merge) => anchorRange(merge.anchor)),
    hidden: {
      rows: parseSpans(exported?.hiddenRows ?? [], "rows"),
      columns: parseSpans(exported?.hiddenColumns ?? [], "columns"),
    },
    chartWidth: Math.max(0, ...charts.map((corner) => corner.x)),
    chartHeight: Math.max(0, ...charts.map((corner) => corner.y)),
  }
}

/** Where the sheet's last cell ends, past the frozen panes. A viewport past it makes the engine throw. */
function end(opened: Opened, sheet: number, frozen: { readonly width: number; readonly height: number }) {
  const key = `${sheet}:${frozen.width}:${frozen.height}`

  if (opened.ends.has(key)) return opened.ends.get(key)

  const measured = measureEnd(opened.workbook, sheet, frozen)

  opened.ends.set(key, measured)

  return measured
}

function measureEnd(
  workbook: WorkbookHandle,
  sheet: number,
  frozen: { readonly width: number; readonly height: number },
) {
  const last = attempt(() => workbook.cellPosition(sheet, lastCell.row, lastCell.col))

  if (!last) return undefined

  // A viewport one pixel past the frozen panes, on the last cell, reports where that cell ends.
  const grid = attempt(
    () => workbook.displayList({ x: last.x, y: last.y, width: frozen.width + 1, height: frozen.height + 1 }).grid,
  )

  // The engine works in single precision there, so stay a little short of the edge.
  const margin = 2

  return {
    x: last.x + Math.max(0, (grid ? grid.colOffsets[grid.colOffsets.length - 1] : 0) - frozen.width) - margin,
    y: last.y + Math.max(0, (grid ? grid.rowOffsets[grid.rowOffsets.length - 1] : 0) - frozen.height) - margin,
  }
}

/** The cells of a range on a sheet as the engine reads them, row by row; undefined when it cannot. */
function read(opened: Opened, sheet: number, range: CellRange) {
  const target: XlsxRangeTarget = {
    sheetId: opened.info.sheetIds[sheet],
    range: { kind: "rowCol", start: { row: range.top, col: range.left }, end: { row: range.bottom, col: range.right } },
  }

  const result = attempt(() => opened.workbook.readCells({ ranges: [target] }))

  return result?.ok ? result.ranges[0]?.cells : undefined
}

/** The workbook's sheets but its hidden and very hidden ones, which Excel lists only to unhide. */
function visibleTabs(workbook: WorkbookHandle, info: SheetInfo): SheetTab[] {
  const names = info.sheetNames

  const result = attempt(() =>
    workbook.exportStructured({
      includeHiddenSheets: true,
      includeDefinedNames: false,
      scope: names.map((_, sheet) => ({ sheet, range: "A1" })),
    }),
  )

  const hidden = new Set(
    (result?.ok ? result.content.sheets : [])
      .filter((sheet) => sheet.visibility === "hidden" || sheet.visibility === "veryHidden")
      .flatMap((sheet) => (sheet.anchor.kind === "sheet" ? [sheet.anchor.sheet.index] : [])),
  )

  return names.flatMap((name, index) => (hidden.has(index) ? [] : [{ index, name }]))
}

/**
 * Whether a cell's text pastes as it is. `toTsv` quotes text that a spreadsheet would read as a formula; a number shown
 * with a sign, such as "-12.50", is safe, and quoting it would paste text instead of the number.
 */
function literal(cell: XlsxCellRead) {
  return cell.value.kind === "number" && /^[-+][\d\s.,%\p{Sc}]+(?:e[-+]\d+)?$/iu.test(cell.displayText)
}

import type { ImageResolver } from "@betteroffice/docx/layout/render"
import type { YrsMediaSource } from "@betteroffice/docx/yrs"

/** An embedded image's source, which names a part of the package the session reads. */
const mediaToken = /^media:(0|[1-9]\d*)$/u

/** How many bytes of decoded images stay for repaints; the least recently drawn go first past it. */
const budget = 256 * 1024 * 1024

type Decoded = {
  readonly image: Promise<CanvasImageSource | null>
  /** The decoded image once it is one; the shared placeholder is never closed. */
  bitmap: ImageBitmap | undefined
}

/**
 * Resolves the display list's images in a worker, where there is no `Image` element: a `media:{n}` source decodes
 * from the bytes the session reads, and a `data:` or `blob:` source decodes in place. Anything else, such as a remote
 * address, resolves to nothing, so painting never makes a request. A part that is missing or cannot be decoded paints a
 * grey box, as the window's resolver does. Decoded images stay for repaints within `budget`.
 */
export function createBitmapImageResolver(media: (token: string) => YrsMediaSource | null) {
  const cache = new Map<string, Decoded>()
  const placeholder = greyBox()

  const decode = (source: string): Promise<CanvasImageSource | null> => {
    const token = mediaToken.test(source)
    const found = token ? media(source) : undefined

    if (token && !found) return Promise.resolve(placeholder)

    const blob = found
      ? Promise.resolve(new Blob([new Uint8Array(found.bytes)], { type: found.mimeType }))
      : fetch(source).then((response) => response.blob())

    return blob
      .then((value) => createImageBitmap(value))
      .then(
        (bitmap): CanvasImageSource => bitmap,
        () => (token ? placeholder : null),
      )
  }

  const resolve: ImageResolver = (source) => {
    if (!mediaToken.test(source) && !source.startsWith("blob:") && !source.startsWith("data:")) return null

    const cached = cache.get(source)

    if (cached) {
      // Map order is drawing order: the least recently drawn come first.
      cache.delete(source)
      cache.set(source, cached)

      return cached.image
    }

    const entry: Decoded = {
      image: decode(source).then((image) => {
        if (image instanceof ImageBitmap) entry.bitmap = image

        return image
      }),
      bitmap: undefined,
    }

    cache.set(source, entry)

    return entry.image
  }

  return {
    resolve,
    /** Closes the least recently drawn images past the budget. Call it between paints, never during one. */
    trim() {
      const size = (entry: Decoded) => (entry.bitmap ? entry.bitmap.width * entry.bitmap.height * 4 : 0)

      ;[...cache].reduce(
        (total, [source, entry]) => {
          if (total <= budget || !entry.bitmap) return total

          const freed = size(entry)

          entry.bitmap.close()
          cache.delete(source)

          return total - freed
        },
        [...cache.values()].reduce((total, entry) => total + size(entry), 0),
      )
    },
  }
}

/** The grey box a missing image paints: one pixel the painter stretches over the image's place. */
function greyBox() {
  const canvas = new OffscreenCanvas(1, 1)
  const context = canvas.getContext("2d")

  if (!context) return null

  context.fillStyle = "#e6e6e6"
  context.fillRect(0, 0, 1, 1)

  return canvas
}

import {
  fontSizePxFromShorthand,
  glyphRunRect,
  textRunRect,
  type DisplayPage,
  type DisplayPrimitive,
  type GeoRect,
  type GlyphRunPrimitive,
  type TextRunPrimitive,
} from "@betteroffice/docx/layout/render"
import { wordLink } from "./links"
import { lineHeight, type WordSpan } from "./word-protocol"

/** Measures text in the layer's font. */
export type TextMeasure = {
  /** The natural width of `text` at a font size of 1. */
  readonly width: (text: string) => number
  /** The font's ascent and descent, at a font size of 1. */
  readonly ascent: number
  readonly descent: number
}

/**
 * Builds a page's text layer from its display list: its header, body, notes and footer in reading order. Each glyph
 * run's text sits over its painted glyphs, merged with its neighbours on the line while their text runs on, so
 * selection, find and screen readers see whole words and lines.
 */
export function pageText(page: DisplayPage, measure: TextMeasure): WordSpan[] {
  const body = page.primitives.slice(Math.min(page.watermarkPrimitiveCount ?? 0, page.primitives.length))
  const notes = (page.noteAreas ?? []).map((area) => area.primitives ?? [])

  return [page.header?.primitives ?? [], body, ...notes, page.footer?.primitives ?? []].flatMap((region) =>
    regionText(region, page, measure),
  )
}

/**
 * The page and height of the first body text at or after a document position, such as a bookmark's: the heading a
 * table of contents entry points to. Undefined when no text follows it. A page whose content is not built yet is
 * built through `build` only when its body reaches the position.
 */
export function positionTarget(
  pages: readonly DisplayPage[],
  position: number,
  build: (index: number) => DisplayPage | undefined,
) {
  for (const [index, listed] of pages.entries()) {
    const page = listed.unbuilt ? ((listed.positionSpan?.[1] ?? -1) >= position ? build(index) : undefined) : listed
    const first = page && bodyAfter(page, position).toSorted((left, right) => left.start - right.start)[0]

    if (first) return { index, y: first.y }
  }

  return undefined
}

function bodyAfter(page: DisplayPage, position: number) {
  return page.primitives.flatMap((primitive) => {
    const piece = toPiece(primitive)

    return piece?.start !== undefined && piece.start >= position ? [{ start: piece.start, y: piece.rect.y }] : []
  })
}

type Piece = {
  readonly text: string
  readonly rect: GeoRect
  readonly baseline: number
  readonly size: number
  readonly dir: "ltr" | "rtl"
  readonly href: string | undefined
  readonly title: string | undefined
  readonly rotation: number
  readonly line: string
  /** A list item's number or bullet, which Word follows with a tab. */
  readonly marker: boolean
  readonly start: number | undefined
  readonly end: number | undefined
}

function regionText(primitives: readonly DisplayPrimitive[], page: DisplayPage, measure: TextMeasure): WordSpan[] {
  const lines = primitives
    .flatMap((primitive) => {
      const piece = toPiece(primitive)

      return piece ? [piece] : []
    })
    .reduce<Piece[][]>((groups, piece) => {
      const line = groups.at(-1)
      const first = line?.[0]

      if (line && first && first.line === piece.line && Math.abs(first.baseline - piece.baseline) < first.size * 0.6) {
        line.push(piece)

        return groups
      }

      groups.push([piece])

      return groups
    }, [])
    .map((line) => mergeLine(logical(line)))

  return lines.flatMap((line, index) => {
    const next = lines[index + 1]?.[0]
    const last = line.at(-1)
    // A line that wraps inside its paragraph runs on into the next: copied text joins them as one paragraph.
    const wraps = !!next && last?.end !== undefined && next.start === last.end

    return line.map((piece, at) => {
      const following = line[at + 1]

      if (!following) return toSpan(piece, page, measure, wraps ? undefined : "br")

      return toSpan(piece, page, measure, separated(piece, following) ? "tab" : undefined)
    })
  })
}

/** Neighbours on a line with a gap between them and no space on either side of it read as separate words. */
function separated(previous: Piece, next: Piece) {
  if (/\s$/u.test(previous.text) || /^\s/u.test(next.text)) return false

  // A number's painted width runs up to its text, over the tab between them.
  if (previous.marker) return true

  const gap = Math.max(next.rect.x - (previous.rect.x + previous.rect.w), previous.rect.x - (next.rect.x + next.rect.w))

  return gap > next.size * 0.35
}

function toPiece(primitive: DisplayPrimitive): Piece | undefined {
  if (primitive.kind === "glyphRun") return glyphPiece(primitive)

  if (primitive.kind === "text") return textPiece(primitive)

  return undefined
}

function glyphPiece(primitive: GlyphRunPrimitive): Piece | undefined {
  if (!primitive.text || primitive.glyphs.length === 0 || primitive.decorative) return undefined

  // Marks sit off the baseline with no advance; the first glyph that advances sits on it.
  const base = primitive.glyphs.find((glyph) => glyph.advance) ?? primitive.glyphs[0]

  return {
    ...common(primitive),
    text: primitive.text,
    rect: glyphRunRect(primitive),
    baseline: base?.y ?? 0,
    size: primitive.size,
  }
}

function textPiece(primitive: TextRunPrimitive): Piece | undefined {
  if (!primitive.text || primitive.decorative) return undefined

  return {
    ...common(primitive),
    text: primitive.text,
    rect: textRunRect(primitive),
    baseline: primitive.baselineY,
    size: fontSizePxFromShorthand(primitive.font),
  }
}

function common(primitive: GlyphRunPrimitive | TextRunPrimitive) {
  const link = wordLink(primitive.href)

  return {
    dir: primitive.rtl || (primitive.bidiLevel ?? 0) % 2 === 1 ? ("rtl" as const) : ("ltr" as const),
    href: link ? primitive.href : undefined,
    title: primitive.linkTitle ?? primitive.tooltip ?? (link?.kind === "external" ? link.url : undefined),
    rotation: primitive.rotationDeg ?? 0,
    line: `${primitive.lineIndex ?? ""}|${primitive.cell?.cellId ?? `${primitive.cell?.row ?? ""},${primitive.cell?.col ?? ""}`}`,
    marker: primitive.listMarker ?? false,
    start: primitive.docStart,
    end: primitive.docEnd,
  }
}

/** A line paints right-to-left runs in visual order; document positions restore the order they are read in. */
function logical(line: Piece[]) {
  if (line.some((piece) => piece.start === undefined)) return line

  return line.toSorted((left, right) => (left.start ?? 0) - (right.start ?? 0))
}

/**
 * Joins pieces whose text runs on: same link, direction and size, next in the document and touching on the page. A wide
 * gap, such as a tab or a justified space, starts a new span, so each span's text stays close to its glyphs.
 */
function mergeLine(line: Piece[]) {
  return line.reduce<Piece[]>((merged, piece) => {
    const previous = merged.at(-1)

    if (!previous || !joins(previous, piece)) {
      merged.push(piece)

      return merged
    }

    const left = Math.min(previous.rect.x, piece.rect.x)
    const right = Math.max(previous.rect.x + previous.rect.w, piece.rect.x + piece.rect.w)

    merged[merged.length - 1] = {
      ...previous,
      text: previous.text + piece.text,
      rect: { ...previous.rect, x: left, w: right - left },
      end: piece.end,
    }

    return merged
  }, [])
}

function joins(previous: Piece, piece: Piece) {
  if (previous.marker || piece.marker) return false

  if (previous.href !== piece.href || previous.dir !== piece.dir || previous.title !== piece.title) return false

  if (previous.rotation !== 0 || piece.rotation !== 0 || Math.abs(previous.size - piece.size) > 0.01) return false

  if (previous.end === undefined || previous.end !== piece.start) return false

  const gap =
    piece.dir === "rtl"
      ? previous.rect.x - (piece.rect.x + piece.rect.w)
      : piece.rect.x - (previous.rect.x + previous.rect.w)

  return Math.abs(gap) < piece.size * 0.35
}

function toSpan(piece: Piece, page: DisplayPage, measure: TextMeasure, after: WordSpan["after"]): WordSpan {
  const natural = measure.width(piece.text)
  const stretch = natural > 0 && piece.rect.w > 0 ? piece.rect.w / (natural * piece.size) : 1
  // The line box puts the baseline this many ems below its top.
  const above = (lineHeight + measure.ascent - measure.descent) / 2
  const top = piece.baseline - piece.size * above
  const width = piece.rect.w / piece.size
  const middle = (piece.rect.y + piece.rect.h / 2 - top) / piece.size

  // A rotated run turns about its painted box's centre; ems keep the turn in step with the page's scale.
  const rotation =
    piece.rotation === 0
      ? ""
      : `translate(${width / 2}em, ${middle}em) rotate(${piece.rotation}deg) translate(${-width / 2}em, ${-middle}em) `

  return {
    text: piece.text,
    left: piece.rect.x / page.width,
    top: top / page.height,
    size: piece.size / page.width,
    transform: `${rotation}scaleX(${stretch})`,
    dir: piece.dir,
    link: wordLink(piece.href),
    title: piece.title,
    after,
  }
}

import { serveWorker, Transfer, type Method } from "./worker-rpc"

// The worker end of `worker-rpc.test.ts`, run in a Bun worker.

/** The methods the test calls, each recording that it ran. */
export type FixtureMethods = {
  readonly echo: Method<string, string>
  readonly sleep: Method<number, undefined>
  /** Holds the worker for `input` milliseconds without yielding, so a cancel can only arrive after the reply left. */
  readonly spin: Method<number, ArrayBuffer>
  /** Runs until its caller aborts it. */
  readonly hold: Method<undefined, undefined>
  /** A bitmap after `input` milliseconds. */
  readonly paint: Method<number, ImageBitmap>
  readonly log: Method<
    undefined,
    { readonly ran: readonly string[]; readonly aborted: readonly string[]; readonly closed: number }
  >
}

type Log = { ran: string[]; aborted: string[]; closed: number }

const log: Log = { ran: [], aborted: [], closed: 0 }

// Bun's workers have no ImageBitmap. This stand-in counts the bitmaps the server closes; it cannot be posted.
class StandInBitmap {
  close() {
    log.closed += 1
  }
}

Object.assign(globalThis, { ImageBitmap: StandInBitmap })

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

serveWorker<FixtureMethods>({
  echo: (input) => {
    log.ran.push(`echo:${input}`)

    return input
  },
  sleep: async (input) => {
    log.ran.push("sleep")
    await sleep(input)

    return undefined
  },
  spin: (input) => {
    log.ran.push("spin")

    const until = performance.now() + input

    while (performance.now() < until) {
      // Busy: no message reaches the worker meanwhile.
    }

    const buffer = new ArrayBuffer(8)

    return new Transfer(buffer, [buffer])
  },
  hold: (_, signal) => {
    log.ran.push("hold")

    return new Promise((resolve) =>
      signal.addEventListener("abort", () => {
        log.aborted.push("hold")
        resolve(undefined)
      }),
    )
  },
  paint: async (input) => {
    log.ran.push("paint")
    await sleep(input)

    const bitmap = new ImageBitmap()

    return new Transfer(bitmap, [bitmap])
  },
  log: () => log,
})

import { afterEach, describe, expect, test } from "bun:test"
import type { FixtureMethods } from "./worker-rpc.fixture"
import { createWorkerClient, SupersededError, WorkerClosedError } from "./worker-rpc"

const clients: ReturnType<typeof createWorkerClient<FixtureMethods>>[] = []

afterEach(() => clients.splice(0).forEach((client) => client.close()))

describe("worker rpc", () => {
  test("a newer call with the same key replaces one still waiting to run", async () => {
    const client = start()
    const busy = client.call("sleep", 50)
    const first = client.call("echo", "first", { key: "echo" })
    const second = client.call("echo", "second", { key: "echo" })

    await expect(first).rejects.toBeInstanceOf(SupersededError)
    expect(await second).toBe("second")
    await busy
    expect((await client.call("log", undefined)).ran).toEqual(["sleep", "echo:second"])
  })

  test("an aborted call rejects at once, and never runs while it waits", async () => {
    const client = start()
    const controller = new AbortController()
    const busy = client.call("sleep", 50)
    const call = client.call("echo", "aborted", { signal: controller.signal })

    controller.abort()
    await expect(call).rejects.toBeInstanceOf(WorkerClosedError)
    await busy
    expect(await client.call("echo", "next")).toBe("next")
    expect((await client.call("log", undefined)).ran).toEqual(["sleep", "echo:next"])
  })

  test("an aborted running call aborts its handler's signal", async () => {
    const client = start()
    const controller = new AbortController()
    const call = client.call("hold", undefined, { signal: controller.signal })

    await Bun.sleep(30)
    controller.abort()
    await expect(call).rejects.toBeInstanceOf(WorkerClosedError)
    expect(await client.call("log", undefined)).toEqual({ ran: ["hold"], aborted: ["hold"], closed: 0 })
  })

  test("a handler that finishes after its call was aborted closes its bitmaps instead of replying", async () => {
    const client = start()
    const controller = new AbortController()
    const call = client.call("paint", 50, { signal: controller.signal })

    await Bun.sleep(20)
    controller.abort()
    await expect(call).rejects.toBeInstanceOf(WorkerClosedError)
    // The stand-in bitmap cannot be posted, so a reply would fail in the worker before it counted a close.
    expect(await client.call("log", undefined)).toEqual({ ran: ["paint"], aborted: [], closed: 1 })
  })

  test("a reply that crosses its call's cancel is dropped", async () => {
    const client = start()
    const controller = new AbortController()
    const call = client.call("spin", 100, { signal: controller.signal })

    await Bun.sleep(30)
    controller.abort()
    await expect(call).rejects.toBeInstanceOf(WorkerClosedError)
    // The worker replied before it read the cancel, and the window's next calls still settle with their own replies.
    expect(await client.call("echo", "after")).toBe("after")
    expect((await client.call("log", undefined)).ran).toEqual(["spin", "echo:after"])
  })

  test("close rejects the pending calls and every later one", async () => {
    const client = start()
    const pending = client.call("sleep", 1000)

    client.close()
    await expect(pending).rejects.toBeInstanceOf(WorkerClosedError)
    await expect(client.call("echo", "late")).rejects.toBeInstanceOf(WorkerClosedError)
  })
})

function start() {
  const client = createWorkerClient<FixtureMethods>(
    new Worker(new URL("./worker-rpc.fixture.ts", import.meta.url), { type: "module" }),
  )

  clients.push(client)

  return client
}

// The engines run in a worker per open file, so no layout, recalculation or painting holds the window. These are the
// two ends of that worker's protocol: typed calls by method name, a key that lets a newer call replace a queued one
// (as the markdown worker's queue does), transferable payloads, and a worker that fails every pending call when it dies.

/** What one method takes and returns. */
export type Method<Input, Output> = { readonly input: Input; readonly output: Output }

/** A worker's methods by name. */
export type Methods = { readonly [name: string]: Method<unknown, unknown> }

type Request = { readonly id: number; readonly method: string; readonly key?: string; readonly input: unknown }

/** Withdraws a call whose caller aborted it. */
type Cancel = { readonly cancel: number }

type Response =
  /** `transferred` lists the objects the reply moved, so a reply nobody waits for can close its bitmaps. */
  | { readonly id: number; readonly ok: true; readonly value: unknown; readonly transferred: readonly Transferable[] }
  | { readonly id: number; readonly ok: false; readonly superseded: boolean; readonly message: string }

/** A value a method returns with the buffers to move to the caller rather than copy. */
export class Transfer<T> {
  constructor(
    readonly value: T,
    readonly transfer: readonly Transferable[],
  ) {}
}

/**
 * The buffer to move a file's bytes to a worker in: their own when they span all of it, as a viewer's bytes do, so the
 * file is never copied; a copy of the span otherwise. Moving it leaves `bytes` empty.
 */
export function movableBuffer(bytes: Uint8Array): ArrayBuffer {
  const buffer = bytes.buffer

  if (buffer instanceof ArrayBuffer && bytes.byteOffset === 0 && bytes.byteLength === buffer.byteLength) return buffer

  return bytes.slice().buffer
}

/** A call that a newer call with the same key replaced before it ran. */
export class SupersededError extends Error {}

/** A call made after the worker failed or was closed, or pending when that happened. */
export class WorkerClosedError extends Error {}

type CallOptions = {
  /** A newer call with the same key replaces this one while it waits to run. */
  readonly key?: string
  /** Buffers to move to the worker rather than copy, such as the file's bytes or a transferred canvas. */
  readonly transfer?: readonly Transferable[]
  /** Drops the reply and a call still queued; a call that has started sees its handler's signal abort. */
  readonly signal?: AbortSignal
}

/** A call waiting for its reply. */
type Pending = { readonly settle: (response: Response) => void; readonly reject: (error: Error) => void }

/** The next call id, and why the worker stopped answering once it has. */
type ClientState = { next: number; failure: Error | undefined }

/** The window's end: starts the worker and calls its methods. */
export function createWorkerClient<M extends Methods>(worker: Worker) {
  const pending = new Map<number, Pending>()
  const state: ClientState = { next: 0, failure: undefined }

  const fail = (error: Error) => {
    state.failure ??= error
    pending.forEach((call) => call.reject(error))
    pending.clear()
    worker.terminate()
  }

  worker.onmessage = (event: MessageEvent<Response>) => {
    const call = pending.get(event.data.id)

    // A reply that crossed its call's cancel on the way: its bitmaps would hold their memory until collected.
    if (!call) {
      if (event.data.ok) closeBitmaps(event.data.transferred)

      return
    }

    pending.delete(event.data.id)
    call.settle(event.data)
  }

  worker.onerror = (event) => fail(new WorkerClosedError(event.message || "The Office engine stopped"))
  worker.onmessageerror = () => fail(new WorkerClosedError("The Office engine sent an unreadable reply"))

  return {
    call<K extends keyof M & string>(
      method: K,
      input: M[K]["input"],
      options: CallOptions = {},
    ): Promise<M[K]["output"]> {
      if (state.failure) return Promise.reject(state.failure)

      if (options.signal?.aborted) return Promise.reject(new WorkerClosedError("The call was aborted"))

      const id = ++state.next

      return new Promise<M[K]["output"]>((resolve, reject) => {
        const abort = () => {
          pending.delete(id)
          reject(new WorkerClosedError("The call was aborted"))
          worker.postMessage({ cancel: id } satisfies Cancel)
        }

        options.signal?.addEventListener("abort", abort, { once: true })
        pending.set(id, {
          settle: (response) => {
            options.signal?.removeEventListener("abort", abort)

            if (!response.ok)
              return reject(response.superseded ? new SupersededError(response.message) : new Error(response.message))

            // SAFETY: the worker answers each id with the output of the method that id called (see `serveWorker`).
            resolve(response.value as M[K]["output"])
          },
          reject,
        })
        worker.postMessage({ id, method, key: options.key, input } satisfies Request, [...(options.transfer ?? [])])
      })
    },
    /** Stops the worker, which frees its engine's memory, and fails every pending call. */
    close() {
      fail(new WorkerClosedError("The Office engine was closed"))
    },
  }
}

/** Whether a call runs, and which call it is, so its caller can abort it. */
type ServerState = {
  running: boolean
  current: { readonly id: number; readonly controller: AbortController } | undefined
}

/**
 * The worker's end: runs calls one at a time, in order, letting messages through between them. A handler's signal
 * aborts when its caller aborts the call.
 */
export function serveWorker<M extends Methods>(handlers: {
  readonly [K in keyof M]: (
    input: M[K]["input"],
    signal: AbortSignal,
  ) => M[K]["output"] | Transfer<M[K]["output"]> | Promise<M[K]["output"] | Transfer<M[K]["output"]>>
}) {
  const queue: Request[] = []

  const state: ServerState = { running: false, current: undefined }

  const reply = (response: Response, transfer: readonly Transferable[] = []) =>
    self.postMessage(response, { transfer: [...transfer] })

  const run = async () => {
    if (state.running) return

    state.running = true

    // Each call returns to the event loop before it leaves the queue, so calls that arrived meanwhile can replace it.
    while (queue.length > 0) {
      await new Promise((resolve) => setTimeout(resolve))

      const request = queue.shift()

      if (!request) break

      const handler = handlers[request.method]
      const controller = new AbortController()

      state.current = { id: request.id, controller }

      if (!handler) {
        reply({ id: request.id, ok: false, superseded: false, message: `Unknown method ${request.method}` })
        continue
      }

      // SAFETY: the client sends each method the input its `Methods` entry declares (see `createWorkerClient`).
      const input = request.input as never

      await Promise.try(() => handler(input, controller.signal)).then(
        (result) => {
          const transfer = result instanceof Transfer ? result.transfer : []

          // The caller already settled a call it aborted, so nothing would take the reply or its bitmaps.
          if (controller.signal.aborted) return closeBitmaps(transfer)

          reply(
            {
              id: request.id,
              ok: true,
              value: result instanceof Transfer ? result.value : result,
              transferred: transfer,
            },
            transfer,
          )
        },
        (cause: unknown) => {
          if (controller.signal.aborted) return

          reply({
            id: request.id,
            ok: false,
            superseded: false,
            message: cause instanceof Error ? cause.message : String(cause),
          })
        },
      )
    }

    state.running = false
    state.current = undefined
  }

  self.onmessage = (event: MessageEvent<Request | Cancel>) => {
    // The caller already settled a cancelled call, so it gets no reply.
    if ("cancel" in event.data) {
      const id = event.data.cancel
      const queued = queue.findIndex((request) => request.id === id)

      if (queued !== -1) queue.splice(queued, 1)

      if (state.current?.id === id) state.current.controller.abort()

      return
    }

    const key = event.data.key
    const replaced = key === undefined ? -1 : queue.findIndex((request) => request.key === key)

    if (replaced !== -1) {
      const [old] = queue.splice(replaced, 1)

      if (old) reply({ id: old.id, ok: false, superseded: true, message: "Replaced by a newer call" })
    }

    queue.push(event.data)
    void run()
  }
}

/** Frees the bitmaps among objects that were moved for a reply nobody takes. */
function closeBitmaps(transfer: readonly Transferable[]) {
  transfer.forEach((item) => {
    if (item instanceof ImageBitmap) item.close()
  })
}

import { execFile } from "node:child_process"
import { powerSaveBlocker } from "electron"
import type { MainSetup } from "../sdk/main"
import { Pairing } from "./contract"
import type definition from "./index"

/** The display sleep blocker this instance holds, if any. */
type Blocker = { id?: number }

/** The last `opencode service` command; the next one starts after it settles. */
type Queue = { tail: Promise<unknown> }

const setup: MainSetup<typeof definition> = (ctx) => {
  const stored = ctx.stores.keepScreenActive
  const cli = ctx.cli
  const log = ctx.log
  const blocker: Blocker = {}
  const queue: Queue = { tail: Promise.resolve() }

  const release = () => {
    if (blocker.id === undefined) return
    powerSaveBlocker.stop(blocker.id)
    blocker.id = undefined
  }

  const keepScreenActive = (enabled: boolean) => {
    if (enabled && blocker.id === undefined) blocker.id = powerSaveBlocker.start("prevent-display-sleep")

    if (!enabled) release()
    stored.set(enabled)
  }

  // Remote access is a setting of the background service, so it changes through the CLI the app runs, as with
  // `opencode pair --remote`. A change restarts the service, so commands run one at a time.
  const service = (args: readonly string[], signal: AbortSignal) => {
    const run = queue.tail.then(
      () =>
        new Promise<string>((resolve, reject) => {
          execFile(
            cli.command[0] ?? "opencode",
            [...cli.command.slice(1), "service", ...args],
            { signal, windowsHide: true },
            (error, stdout, stderr) => {
              if (!error) return resolve(stdout.trim())
              log.write("error", "pairing service command failed", { args, error: error.message, stderr })
              reject(error)
            },
          )
        }),
    )

    queue.tail = run.catch(() => undefined)

    return run
  }

  if (stored.value) keepScreenActive(true)
  ctx.scope.addFinalizer(release)

  ctx.provide(Pairing, {
    remote: async (_, caller) => (await service(["get", "remote"], caller.signal)) === "true",
    // Changing the setting stops the service. Starting it here brings it back, with the tunnel when remote access is
    // on. A window that closes meanwhile does not cancel the change.
    setRemote: async (enabled) => {
      await service(["set", "remote", String(enabled)], ctx.scope.signal)
      await service(["start"], ctx.scope.signal)
    },
    screenActive: () => blocker.id !== undefined && powerSaveBlocker.isStarted(blocker.id),
    setScreenActive: (enabled) => keepScreenActive(enabled),
  })
}

export default setup

