    ])
  })
})

import type { FileDiffInfo } from "@opencode/client/promise"
import type { ChangeKind } from "./contract"

export type RenderDiff = FileDiffInfo

export function normalizePath(value: string) {
  return value
    .replaceAll("\\", "/")
    .replace(/^\/+|\/+$/g, "")
    .replace(/\/{2,}/g, "/")
}

export function filterRenderableDiff(value: FileDiffInfo): value is RenderDiff {
  return typeof value.file === "string"
}

export function reviewDiffNeedsLoad(diff: RenderDiff) {
  if (diff.additions === 0 && diff.deletions === 0) return false

  return !diff.patch || !/^@@ /m.test(diff.patch)
}

export function reviewRootDirectory(root: string) {
  return root === "/" || /^[A-Za-z]:[/\\]?$/.test(root) ? root : root.replace(/[/\\]+$/, "")
}

export function reviewDiffDirectory(root: string, file: string) {
  const path = normalizePath(file)
  const index = path.lastIndexOf("/")
  const separator = root.includes("\\") ? "\\" : "/"
  const base = reviewRootDirectory(root)

  if (index < 0) return base

  return `${base.endsWith(separator) ? base : base + separator}${path.slice(0, index).replaceAll("/", separator)}`
}

export function reviewDiffKinds(diffs: readonly RenderDiff[]) {
  const merge = (a: ChangeKind | undefined, b: ChangeKind) => {
    if (!a) return b

    if (a === b) return a

    return "mix" as const
  }

  const out = new Map<string, ChangeKind>()

  for (const diff of diffs) {
    const file = normalizePath(diff.file)
    const kind = diff.status === "added" ? "add" : diff.status === "deleted" ? "del" : "mix"

    out.set(file, kind)

    const parts = file.split("/")
    parts.slice(0, -1).forEach((_, idx) => {
      const dir = parts.slice(0, idx + 1).join("/")

      if (!dir) return
      out.set(dir, merge(out.get(dir), kind))
    })
  }

  return out
}

export function filterReviewFiles(files: string[], query: string) {
  const value = query.trim().toLowerCase()

  if (!value) return files

  return files.filter((file) => file.toLowerCase().includes(value))
}

/** Depth-first file order with directories before sibling files, as the change tree lists them. */
export function sortReviewPaths(paths: readonly string[]) {
  type Node = { name: string; path: string; file: boolean; original: string }

  const nodes = new Map<string, Node>()
  paths.forEach((value) => {
    const file = normalizePath(value)

    if (!file) return
    const parts = file.split("/")
    parts.forEach((name, index) => {
      const path = parts.slice(0, index + 1).join("/")

      if (nodes.has(path)) return
      const leaf = index === parts.length - 1
      nodes.set(path, { name, path, file: leaf, original: leaf ? value : path })
    })
  })
  const children = new Map<string, Node[]>()
  nodes.forEach((node) => {
    const index = node.path.lastIndexOf("/")
    const parent = index === -1 ? "" : node.path.slice(0, index)
    const list = children.get(parent)

    if (list) list.push(node)
    else children.set(parent, [node])
  })
  children.forEach((list) =>
    list.sort((a, b) => {
      if (a.file !== b.file) return a.file ? 1 : -1

      return a.name.localeCompare(b.name)
    }),
  )
  const out: string[] = []
  const stack = (children.get("") ?? []).toReversed()

  while (stack.length > 0) {
    const node = stack.pop()!

    if (node.file) {
      out.push(node.original)
      continue
    }

    stack.push(...(children.get(node.path) ?? []).toReversed())
  }

  return out
}

// Drives the highlight/selection of the flat search-result list from the filter
// input's keyboard events.
export function applyFileListKeyDown(
  event: KeyboardEvent,
  files: readonly string[],
  highlighted: string | undefined,
  options: { onHighlight: (path: string) => void; onSelect: (path: string) => void },
) {
  if (files.length === 0) return

  if (event.key === "ArrowDown" || event.key === "ArrowUp") {
    const currentIndex = highlighted ? files.indexOf(highlighted) : -1
    const delta = event.key === "ArrowDown" ? 1 : -1
    const start = currentIndex === -1 ? (delta > 0 ? 0 : files.length - 1) : currentIndex + delta
    const index = Math.max(0, Math.min(files.length - 1, start))
    options.onHighlight(files[index]!)
    event.preventDefault()

    return
  }

  if (event.key !== "Enter") return
  const target = highlighted ?? files[0]

  if (!target) return
  options.onSelect(target)
  event.preventDefault()
}

import { onCleanup, Show } from "solid-js"
import { makeEventListener } from "@solid-primitives/event-listener"
import { SessionReview } from "@opencode/session-ui/session-review"
import { createKeyed, useExtension, type MountedSession } from "../sdk"
import type Review from "./index"
import type { ReviewModel } from "./model"
import { ReviewEmpty, ReviewTitle } from "./parts"

type ScrollState = {
  scroll?: HTMLDivElement
  restoreFrame?: number
  userInteracted: boolean
  restored?: { x: number; y: number }
}

/** The narrow-screen review: every changed file as one scrollable list. */
export default function SessionMobileReview(props: { review: ReviewModel; session: MountedSession }) {
  const ctx = useExtension<typeof Review>()
  const links = ctx.links
  const mobileDiff = ctx.stores.mobileDiff

  return (
    <div class="relative h-full overflow-hidden">
      <Show when={!props.review.deferRender()}>
        <SessionReviewTab
          review={props.review}
          session={props.session}
          overflow={mobileDiff.value.wrap ? "wrap" : "scroll"}
          onViewFile={(file) => void links.open({ href: file, exact: true, session: props.session })}
        />
      </Show>
    </div>
  )
}

function SessionReviewTab(props: {
  review: ReviewModel
  session: MountedSession
  overflow: "wrap" | "scroll"
  onViewFile: (file: string) => void
}) {
  const ctx = useExtension()
  const layout = ctx.layout
  const review = props.review
  const state: ScrollState = { userInteracted: false }

  const handleInteraction = () => {
    state.userInteracted = true

    if (state.restoreFrame !== undefined) {
      cancelAnimationFrame(state.restoreFrame)
      state.restoreFrame = undefined
    }
  }

  const doRestore = () => {
    state.restoreFrame = undefined
    const el = state.scroll

    if (!el || !layout.ready() || state.userInteracted) return

    if (el.clientHeight === 0 || el.clientWidth === 0) return

    const s = layout.scroll.get(props.session, "review")

    if (!s || (s.x === 0 && s.y === 0)) return

    const maxY = Math.max(0, el.scrollHeight - el.clientHeight)
    const maxX = Math.max(0, el.scrollWidth - el.clientWidth)

    const targetY = Math.min(s.y, maxY)
    const targetX = Math.min(s.x, maxX)

    if (el.scrollTop === targetY && el.scrollLeft === targetX) return

    if (el.scrollTop !== targetY) el.scrollTop = targetY

    if (el.scrollLeft !== targetX) el.scrollLeft = targetX
    state.restored = { x: el.scrollLeft, y: el.scrollTop }
  }

  const queueRestore = () => {
    if (state.userInteracted || state.restoreFrame !== undefined) return
    state.restoreFrame = requestAnimationFrame(doRestore)
  }

  const handleScroll = (event: Event & { currentTarget: HTMLDivElement }) => {
    const el = event.currentTarget
    const prev = state.restored

    if (prev && el.scrollTop === prev.y && el.scrollLeft === prev.x) {
      state.restored = undefined

      return
    }

    state.restored = undefined
    handleInteraction()

    if (!layout.ready()) return

    if (el.clientHeight === 0 || el.clientWidth === 0) return

    layout.scroll.set(props.session, "review", {
      x: el.scrollLeft,
      y: el.scrollTop,
    })
  }

  // Restores the stored scroll once the layout loads, and again when the list or its wrapping changes.
  createKeyed(
    () => {
      const count = review.diffs().length
      const overflow = props.overflow

      return layout.ready() ? { count, overflow } : undefined
    },
    () => queueRestore(),
  )

  onCleanup(() => {
    if (state.restoreFrame !== undefined) cancelAnimationFrame(state.restoreFrame)
    review.setScroll(undefined)
  })

  return (
    <SessionReview
      title={<ReviewTitle review={review} />}
      empty={<ReviewEmpty review={review} loadingClass="px-2 py-2 text-text-weak" />}
      scrollRef={(el) => {
        state.scroll = el
        makeEventListener(el, "wheel", handleInteraction, { passive: true, capture: true })
        makeEventListener(el, "mousewheel", handleInteraction, { passive: true, capture: true })
        makeEventListener(el, "pointerdown", handleInteraction, { passive: true, capture: true })
        makeEventListener(el, "touchstart", handleInteraction, { passive: true, capture: true })
        makeEventListener(el, "keydown", handleInteraction, { capture: true })
        review.setScroll(el)
        queueRestore()
      }}
      onScroll={handleScroll}
      onDiffRendered={queueRestore}
      open={review.open()}
      onOpenChange={review.setOpen}
      classes={{
        root: "[&_[data-slot=session-review-list]]:pb-0 [&_[data-slot=accordion-trigger]]:!rounded-none [&_[data-slot=accordion-trigger]]:!border-x-0 [&_[data-slot=accordion-item]:first-child_[data-slot=accordion-trigger]]:!border-t-0 [&_[data-slot=accordion-item]:last-child:not([data-expanded])_[data-slot=accordion-trigger]]:!border-b-0 [&_[data-slot=accordion-item]:last-child_[data-slot=accordion-content]]:!border-b-0 [&_[data-slot=accordion-item]:last-child_[data-slot=session-review-diff-placeholder]]:!border-b-0 [&_[data-slot=accordion-content]]:!rounded-none [&_[data-slot=accordion-content]]:!border-x-0 [&_[data-slot=session-review-diff-placeholder]]:!rounded-none [&_[data-slot=session-review-diff-placeholder]]:!border-x-0",
        header:
          "!px-2 !h-10 !pb-0 relative before:pointer-events-none before:absolute before:inset-x-0 before:bottom-0 before:h-px before:bg-v2-border-border-base before:content-['']",
        container: "!px-0",
      }}
      diffs={review.diffs()}
      diffStyle="unified"
      changeSummary
      overflow={props.overflow}
      disableLineNumbers={false}
      onViewFile={props.onViewFile}
      focusedFile={review.activeFile()}
      readFile={review.readFile}
      onLineComment={review.comments.add}
      onLineCommentUpdate={review.comments.update}
      onLineCommentDelete={review.comments.remove}
      lineCommentActions={review.comments.actions()}
      lineCommentMention={{ items: review.comments.mentions }}
      comments={review.comments.all()}
      focusedComment={review.comments.focus()}
      onFocusedCommentChange={review.comments.setFocus}
    />
  )
}

import type { FileDiffInfo } from "@opencode/client/promise"
import type { SessionReviewLineComment } from "@opencode/session-ui/session-review"
import { previewSelectedLines } from "@opencode/session-ui/pierre/selection-bridge"
import { artifactMime } from "@opencode/util/artifact"
import { bytesToBase64 } from "@opencode/util/base64"
import { checksum } from "@opencode/util/encode"
import { showToast } from "@opencode/ui/toast"
import { createQuery, useQueryClient } from "@tanstack/solid-query"
import { debounce } from "@solid-primitives/scheduled"
import { createMemo, on, onCleanup, type Accessor } from "solid-js"
import { createStore } from "solid-js/store"
import {
  createKeyed,
  createVisitState,
  type LineRange,
  type MountedSession,
  type SessionScreen,
  type SetupContext,
} from "../sdk"
import type Review from "./index"
import {
  filterRenderableDiff,
  reviewDiffDirectory,
  reviewDiffKinds,
  reviewDiffNeedsLoad,
  reviewRootDirectory,
} from "./kinds"

export type ChangeMode = "git" | "branch" | "turn"

type FileSelection = { startLine: number; endLine: number; startChar: number; endChar: number }

export type Demand = { tree: number; files: number; panel: number; details: number }

const selectionFromLines = (range: LineRange): FileSelection => ({
  startLine: Math.min(range.start, range.end),
  endLine: Math.max(range.start, range.end),
  startChar: 0,
  endChar: 0,
})

/**
 * The routed session's review: its diffs, selection, and comments. Lives as long as the session screen; `view`
 * returns the screen's routed session, a new object on each switch.
 */
export function createReviewModel(input: {
  ctx: SetupContext<typeof Review>
  screen: SessionScreen
  view: Accessor<MountedSession>
  demand: Demand
}) {
  const ctx = input.ctx
  const screen = input.screen
  const view = input.view
  const layout = ctx.layout
  const queryClient = useQueryClient()
  const directory = () => screen.file.root

  // The filter is transient by design: a persisted filter would silently hide files after a reload.
  const [state, setState] = createStore<{ filter: string; initializingGit: Record<string, true | undefined> }>({
    filter: "",
    initializingGit: {},
  })

  // The review panel's scroller and the file it scrolls to belong to the session the view shows.
  const [scroll, setScroll] = createVisitState<HTMLDivElement | undefined>(undefined)
  const [pendingFile, setPendingFile] = createVisitState<string | undefined>(undefined)
  const [rendered, setRendered] = createVisitState(false)

  // The routed session's review state. Desktop loads it asynchronously; until it has, its defaults are not the
  // session's choice, so nothing shows them or requests their diff, and changes wait to apply over the stored state.
  const saved = createMemo(() => ctx.stores.session(view()))
  const stored = () => saved().value

  const update: ReturnType<typeof ctx.stores.session>["update"] = (mutation) => saved().update(mutation)

  // A memo, so the store a session switch reopens does not recompute the diffs, kinds and tree rows it feeds.
  const selectedFile = createMemo(() => stored()?.file)

  // After a session switch the review renders a frame later, so the switch paints first.
  createKeyed(
    () => view().visit,
    () => {
      const run = { ended: false }

      onCleanup(() => {
        run.ended = true
      })
      requestAnimationFrame(() => {
        setTimeout(() => {
          if (!run.ended) setRendered(true)
        }, 0)
      })
    },
  )

  const vcs = createMemo(() => view().server.data.location.vcs.info({ directory: directory() }))

  const options = createMemo<ChangeMode[]>(() => {
    const list: ChangeMode[] = []
    const project = view().project

    if (project?.vcs) list.push("git")

    if (
      project?.vcs &&
      vcs()?.branch.current &&
      vcs()?.branch.default &&
      vcs()?.branch.current !== vcs()?.branch.default
    ) {
      list.push("branch")
    }

    // Turn snapshots are captured only for Git sessions.
    if (project?.vcs === "git" && view().id) list.push("turn")

    return list
  })

  // The session's chosen mode while it is offered. One it no longer offers, such as Branch back on the default branch,
  // shows as the first mode offered; the stored choice stays, so it returns once its mode is offered again.
  const mode = createMemo<ChangeMode>(() => {
    const chosen = stored()?.mode ?? "git"

    // Until the server and the project answer, what the session offers is unknown.
    if (!view().server.connected || !view().project) return chosen

    const list = options()

    return list.includes(chosen) ? chosen : (list[0] ?? "git")
  })

  const vcsKey = createMemo(
    () =>
      [
        ctx.id,
        view().server.id,
        "session-vcs",
        directory(),
        vcs()?.branch.current ?? "",
        vcs()?.branch.default ?? "",
      ] as const,
  )

  const wantsReview = createMemo(() => {
    const demand = input.demand

    return demand.tree + demand.files + demand.panel > 0
  })

  const turnKey = () => [ctx.id, view().server.id, "session-turn", view().id] as const

  const diffQuery = createQuery(() => {
    const value = mode()
    const turn = value === "turn"

    return {
      queryKey: turn ? turnKey() : ([...vcsKey(), value] as const),
      // Desktop storage loads asynchronously; until this session's mode is known, a request would use the default.
      enabled: !!stored() && view().server.connected && wantsReview() && !!view().project?.vcs,
      refetchOnMount: "always" as const,
      // A finished turn does not change on focus or filesystem events; refresh it when the session goes idle.
      refetchOnWindowFocus: !turn,
      queryFn: turn
        ? () => view().server.client.session.diff({ sessionID: view().id })
        : () =>
            view()
              .server.client.vcs.diff({
                location: { directory: directory() },
                mode: value === "git" ? "working" : value,
              })
              .then((result) => result.data),
    }
  })

  // The session details' changes row: the session directory's working tree, loaded only while the details show.
  const detailsKey = () => [ctx.id, view().server.id, "session-details", view().directory] as const

  const detailsQuery = createQuery(() => ({
    queryKey: detailsKey(),
    enabled: input.demand.details > 0 && view().server.connected && !!view().project?.vcs,
    queryFn: () =>
      view()
        .server.client.vcs.diff({ location: { directory: view().directory }, mode: "working" })
        .then((result) => result.data)
        .catch((error) => {
          console.debug("[session-review] failed to load session details diff", { error })

          return []
        }),
  }))

  const refresh = debounce(() => {
    void queryClient.invalidateQueries({ queryKey: vcsKey() })
    void queryClient.invalidateQueries({ queryKey: detailsKey() })
  }, 100)

  // The server reports file changes in the directory; its event stream follows a restarted server. Routing another
  // session of the same directory and server keeps the listener.
  createKeyed(
    () => ({ directory: directory(), data: view().server.data }),
    (current) =>
      onCleanup(
        current.data.listen(({ details }) => {
          if (details.type === "filesystem.changed" && details.location?.directory === current.directory) refresh()
        }),
      ),
    { equals: (previous, next) => previous.directory === next.directory && previous.data === next.data },
  )

  // Opening the side region refreshes changes a tree already shows. Otherwise it loads them once, so the
  // pinned tab reads "Files Changed N": v2 opened the region on the review tab before selecting another.
  // A region restored open does not load them until something shows them.
  const opened = createMemo(
    on(
      () => !layout.narrow() && layout.side.opened(view()),
      (open, previous) => (open && !previous ? {} : undefined),
      { defer: true },
    ),
  )

  createKeyed(opened, () => {
    if (diffQuery.isFetching) return

    if (input.demand.tree > 0) {
      refresh()

      return
    }

    if (view().server.connected && view().project?.vcs) void diffQuery.refetch()
  })

  const diffs = (): FileDiffInfo[] => (diffQuery.isFetched ? (diffQuery.data ?? []) : [])
  const renderable = createMemo(() => diffs().filter(filterRenderableDiff))
  const kinds = createMemo(() => reviewDiffKinds(renderable()))

  const activeFile = () => {
    const list = diffs()
    const selected = selectedFile()

    if (selected && list.some((diff) => diff.file === selected)) return selected

    return list[0]?.file
  }

  const count = () => diffs().length
  const hasChanges = () => count() > 0

  const ready = () => {
    // A project without VCS never enables diffQuery, so its status stays "pending" forever.
    const project = view().project

    if (project && !project.vcs) return true

    if (!stored()) return false

    return !diffQuery.isPending
  }

  const lifetime = { disposed: false }

  onCleanup(() => {
    lifetime.disposed = true
  })

  const alive = () => !lifetime.disposed && !ctx.signal.aborted

  // Initializes Git for the routed session. The request keeps that session's object, so its server and location stay
  // its own. Cache refresh follows the request's session; only error feedback depends on which session is routed.
  const initializeGit = () => {
    const session = view()

    if (state.initializingGit[session.key]) return
    const location = session.location

    if (!location || !session.server.connected) {
      showToast({ variant: "error", title: ctx.t("common.requestFailed") })

      return
    }

    const current = () => alive() && view().key === session.key

    setState("initializingGit", session.key, true)
    void session.server.client.vcs
      .init({ location, provider: "git" })
      .then(async () => {
        if (!alive()) return

        const data = session.server.data

        data.project.invalidate()
        data.session.invalidate(session.id)
        data.location.invalidate(location)
        data.location.vcs.invalidate(location)
        await data.project.sync()

        if (!alive()) return
        await data.session.sync(session.id)

        if (!alive()) return
        await Promise.all([data.location.syncInfo(location), data.location.vcs.sync(location)])
      })
      .catch((error) => {
        if (!current()) return

        showToast({
          variant: "error",
          title: ctx.t("common.requestFailed"),
          description: error instanceof Error ? error.message : undefined,
        })
      })
      .finally(() => {
        if (alive()) setState("initializingGit", session.key, undefined)
      })
  }

  const loadDiff = async (path: string, version?: number): Promise<FileDiffInfo | undefined> => {
    const source = diffs().find((diff) => diff.file === path)

    const valid = (diff: FileDiffInfo | undefined): FileDiffInfo | undefined => {
      if (!diff || !source) return undefined

      if (diff.additions !== source.additions || diff.deletions !== source.deletions) return undefined

      if (reviewDiffNeedsLoad(diff)) return undefined

      return diff
    }

    const value = mode()

    // Oversized full-file patches come back empty; bounded context usually fits.
    if (value === "turn") {
      return queryClient
        .fetchQuery({
          queryKey: [...turnKey(), "bounded", version] as const,
          staleTime: Number.POSITIVE_INFINITY,
          retry: 2,
          queryFn: () => view().server.client.session.diff({ sessionID: view().id, context: 3 }),
        })
        .then((result) => valid(result.find((diff) => diff.file === path)))
        .catch((error) => {
          console.debug("[session-review] failed to load bounded turn diff", { path, error })

          return undefined
        })
    }

    const root = reviewRootDirectory(view().project?.worktree ?? directory())
    const scoped = reviewDiffDirectory(root, path)

    const request = (scope: string, context?: number) =>
      queryClient
        .fetchQuery({
          queryKey: [ctx.id, ...vcsKey(), value, "directory", scope, context, version] as const,
          staleTime: Number.POSITIVE_INFINITY,
          retry: 2,
          queryFn: () =>
            view()
              .server.client.vcs.diff({
                location: { directory: scope },
                mode: value === "git" ? "working" : value,
                context,
              })
              .then((result) => result.data),
        })
        .then((result) => result.find((diff) => diff.file === path))

    if (scoped !== root) {
      const result = await request(scoped).then(valid, (error) => {
        console.debug("[session-review] failed to load scoped vcs diff", {
          mode: value,
          path,
          directory: scoped,
          error,
        })

        return undefined
      })

      if (result) return result
    }

    return request(root, 3).then(valid, (error) => {
      console.debug("[session-review] failed to load bounded vcs diff", { mode: value, path, root, error })

      return undefined
    })
  }

  // Previews read files only to show images and audio, which need the raw bytes and their MIME type.
  const readFile = (path: string) =>
    view()
      .server.client.file.read({ path, location: { directory: directory() } })
      .then((bytes) => ({
        type: "binary" as const,
        content: bytesToBase64(bytes),
        encoding: "base64" as const,
        mimeType: artifactMime(path),
      }))
      .catch((error) => {
        console.debug("[session-review] failed to read file", { path, error })

        return undefined
      })

  const selectionPreview = (path: string, selection: FileSelection): string | undefined => {
    const content = screen.file.get(path)?.content?.content

    if (!content) return undefined

    return previewSelectedLines(content, { start: selection.startLine, end: selection.endLine })
  }

  const addComment = (comment: SessionReviewLineComment) => {
    const selection = selectionFromLines(comment.selection)
    const saved = screen.comment.add({ file: comment.file, selection: comment.selection, comment: comment.comment })

    screen.composer.attach({
      type: "file",
      path: comment.file,
      selection,
      comment: comment.comment,
      commentID: saved.id,
      commentOrigin: "review",
      preview: comment.preview ?? selectionPreview(comment.file, selection),
    })
  }

  const updateComment = (comment: {
    id: string
    file: string
    selection: LineRange
    comment: string
    preview?: string
  }) => {
    screen.comment.update(comment.id, comment.comment)
    // The composer keeps a chip's preview unless the update names a new one.
    screen.composer.update(
      comment.id,
      comment.preview ? { comment: comment.comment, preview: comment.preview } : { comment: comment.comment },
    )
  }

  const removeComment = (comment: { id: string; file: string }) => {
    screen.comment.remove(comment.id)
    screen.composer.detach(comment.id)
  }

  const commentActions = createMemo(() => ({
    moreLabel: ctx.t("common.moreOptions"),
    editLabel: ctx.t("common.edit"),
    deleteLabel: ctx.t("common.delete"),
    saveLabel: ctx.t("common.save"),
  }))

  const open = () => {
    if (!layout.side.opened(view())) layout.side.toggle(view())
  }

  const openPath = (path: string) =>
    update((draft) => {
      if (draft.open.includes(path)) return

      draft.open = [...draft.open, path]
    })

  const reviewDiffId = (path: string): string | undefined => {
    const sum = checksum(path)

    if (!sum) return undefined

    return `session-review-diff-${sum}`
  }

  const reviewDiffTop = (element: HTMLDivElement, path: string): number | undefined => {
    const id = reviewDiffId(path)

    if (!id) return undefined

    const target = document.getElementById(id)

    if (!(target instanceof HTMLElement) || !element.contains(target)) return undefined

    return target.getBoundingClientRect().top - element.getBoundingClientRect().top + element.scrollTop
  }

  const scrollToFile = (element: HTMLDivElement, path: string) => {
    const top = reviewDiffTop(element, path)

    if (top === undefined) return false

    layout.scroll.set(view(), "review", { x: element.scrollLeft, y: top })
    element.scrollTo({ top, behavior: "auto" })

    return true
  }

  const focusFile = (path: string) => {
    open()
    openPath(path)
    update((draft) => {
      draft.file = path
    })
    setPendingFile(path)
  }

  // Scrolls the review panel to a focused file once its diff has rendered.
  createKeyed(
    () => {
      const pending = pendingFile()

      if (!pending || !scroll() || !ready()) return

      return { pending }
    },
    (current) => {
      const attempt = (count: number) => {
        if (pendingFile() !== current.pending) return

        if (count > 60) {
          setPendingFile(undefined)

          return
        }

        const element = scroll()

        if (!element || !scrollToFile(element, current.pending)) {
          requestAnimationFrame(() => attempt(count + 1))

          return
        }

        const top = reviewDiffTop(element, current.pending)

        if (top === undefined || Math.abs(element.scrollTop - top) > 1) {
          requestAnimationFrame(() => attempt(count + 1))

          return
        }

        setPendingFile(undefined)
      }

      requestAnimationFrame(() => attempt(0))
    },
  )

  const idled = createMemo(
    on(
      () => view().server.data.session.status(view().id),
      (next, previous) => (next === "idle" && previous !== undefined && previous !== "idle" ? {} : undefined),
      { defer: true },
    ),
  )

  // A session that goes idle has finished its turn, which may have changed files.
  createKeyed(idled, () => {
    refresh()
    void queryClient.invalidateQueries({ queryKey: turnKey() })
  })

  const deferRender = () => !rendered()
  const panelRendered = createMemo<boolean>((previous) => previous || !deferRender(), false)

  return {
    screen,
    view,
    activeFile,
    // The mode picker waits for the stored mode.
    canReview: () => !!view().project && !!stored(),
    comments: {
      actions: commentActions,
      add: addComment,
      all: () => [...screen.comment.list()],
      focus: () => screen.comment.focus.current(),
      mentions: (query: string) => screen.file.search(query, { kind: "any" }),
      remove: removeComment,
      changeFocus: (focus: { file: string; id: string } | null) => {
        if (!focus) {
          const current = screen.comment.focus.current()

          if (current && diffs().some((diff) => diff.file === current.file)) focusFile(current.file)
        }

        screen.comment.focus.set(focus)
      },
      setFocus: (focus: { file: string; id: string } | null) => screen.comment.focus.set(focus),
      update: updateComment,
    },
    count,
    deferRender,
    details: (): FileDiffInfo[] | undefined => (detailsQuery.isFetched ? (detailsQuery.data ?? []) : undefined),
    diffVersion: () => diffQuery.dataUpdatedAt,
    diffs,
    renderable,
    kinds,
    focusFile,
    hasChanges,
    initializeGit,
    initializingGit: () => !!state.initializingGit[view().key],
    loadDiff,
    readFile,
    mode,
    noGit: createMemo(() => {
      const project = view().project

      return !!project && !project.vcs
    }),
    filter: () => state.filter,
    setFilter: (value: string) => setState("filter", value),
    open: () => stored()?.open ?? [],
    setOpen: (next: string[]) =>
      update((draft) => {
        const unique = Array.from(new Set(next))

        if (unique.length === draft.open.length && unique.every((path, index) => path === draft.open[index])) return

        draft.open = unique
      }),
    options,
    panelRendered,
    ready,
    setMode: (value: ChangeMode) =>
      update((draft) => {
        draft.mode = value
      }),
    setScroll,
  }
}

export type ReviewModel = ReturnType<typeof createReviewModel>

import { createMemo, createResource, createSignal, Show, type JSX } from "solid-js"
import { Dynamic } from "solid-js/web"
import type { FileDiffInfo } from "@opencode/client/promise"
import {
  SESSION_REVIEW_V2_SIDEBAR_WIDTH_MAX,
  SESSION_REVIEW_V2_SIDEBAR_WIDTH_MIN,
  SessionReviewV2,
  SessionReviewV2Sidebar,
  SessionReviewV2SidebarToggle,
  type SessionReviewExpandMode,
} from "@opencode/session-ui/v2/session-review-v2"
import { SessionReviewFilePreviewV2 } from "@opencode/session-ui/v2/session-review-file-preview-v2"
import { DiffChanges } from "@opencode/ui/diff-changes"
import type {
  SessionReviewComment,
  SessionReviewCommentActions,
  SessionReviewCommentDelete,
  SessionReviewCommentUpdate,
  SessionReviewDiffStyle,
  SessionReviewFocus,
  SessionReviewLineComment,
} from "@opencode/session-ui/session-review"
import { useExtension, usePanel, type MountedSession, type PanelSidebar, type SessionScreen } from "../sdk"
import type Review from "./index"
import {
  applyFileListKeyDown,
  filterReviewFiles,
  reviewDiffKinds,
  reviewDiffNeedsLoad,
  sortReviewPaths,
  type RenderDiff,
} from "./kinds"
import type { ReviewModel } from "./model"
import { ReviewPanelEmpty, ReviewTitle } from "./parts"

type ReviewPanelState = {
  sidebar: PanelSidebar
  filter: () => string
  setFilter: (value: string) => void
  expandMode: () => SessionReviewExpandMode
  setExpandMode: (mode: SessionReviewExpandMode) => void
}

type ReviewPanelProps = {
  session: MountedSession
  /** The session screen, whose workspace the panel reads files from. */
  screen: SessionScreen
  title?: JSX.Element
  empty?: JSX.Element
  /** Renderable diffs and their change kinds, computed once by the review model. */
  diffs: FileDiffInfo[]
  kinds: ReturnType<typeof reviewDiffKinds>
  diffsReady: boolean
  diffVersion?: number
  loadDiff?: (path: string, version?: number) => Promise<RenderDiff | undefined>
  readFile: ReviewModel["readFile"]
  activeFile?: string
  onSelectFile: (path: string) => void
  diffStyle: SessionReviewDiffStyle
  onDiffStyleChange?: (style: SessionReviewDiffStyle) => void
  state: ReviewPanelState
  onLineComment?: (comment: SessionReviewLineComment) => void
  onLineCommentUpdate?: (comment: SessionReviewCommentUpdate) => void
  onLineCommentDelete?: (comment: SessionReviewCommentDelete) => void
  lineCommentActions?: SessionReviewCommentActions
  comments?: SessionReviewComment[]
  focusedComment?: SessionReviewFocus | null
  onFocusedCommentChange?: (focus: SessionReviewFocus | null) => void
}

/** The desktop review panel. */
export default function ReviewPanelContent(props: {
  review: ReviewModel
  session: MountedSession
  diffStyle: SessionReviewDiffStyle
  onDiffStyleChange: (style: SessionReviewDiffStyle) => void
  expandMode: SessionReviewExpandMode
  onExpandModeChange: (mode: SessionReviewExpandMode) => void
}) {
  const panel = usePanel()

  return (
    <ReviewPanel
      session={props.session}
      screen={props.review.screen}
      title={<ReviewTitle review={props.review} />}
      empty={<ReviewPanelEmpty review={props.review} />}
      diffs={props.review.renderable()}
      kinds={props.review.kinds()}
      diffsReady={props.review.ready()}
      diffVersion={props.review.diffVersion()}
      loadDiff={props.review.loadDiff}
      readFile={props.review.readFile}
      activeFile={props.review.activeFile()}
      onSelectFile={props.review.focusFile}
      diffStyle={props.diffStyle}
      onDiffStyleChange={props.onDiffStyleChange}
      state={{
        sidebar: panel.sidebar,
        filter: props.review.filter,
        setFilter: props.review.setFilter,
        expandMode: () => props.expandMode,
        setExpandMode: props.onExpandModeChange,
      }}
      onLineComment={props.review.comments.add}
      onLineCommentUpdate={props.review.comments.update}
      onLineCommentDelete={props.review.comments.remove}
      lineCommentActions={props.review.comments.actions()}
      comments={props.review.comments.all()}
      focusedComment={props.review.comments.focus()}
      onFocusedCommentChange={props.review.comments.changeFocus}
    />
  )
}

function ReviewPanel(props: ReviewPanelProps) {
  const ctx = useExtension<typeof Review>()

  const openIn = () => {
    const live = ctx.uses.openIn()

    return live.status === "active" ? live.value : undefined
  }

  const diffs = () => props.diffs

  const filteredFiles = createMemo(() =>
    filterReviewFiles(
      diffs().map((diff) => diff.file),
      props.state.filter(),
    ),
  )

  const searching = createMemo(() => props.state.filter().trim().length > 0)
  const navigationFiles = createMemo(() => (searching() ? filteredFiles() : sortReviewPaths(filteredFiles())))
  const kinds = () => props.kinds
  // Changes-only trees omit "M" — every row is already a change; A/D stay visible.
  const treeKinds = createMemo(() => new Map([...kinds()].filter(([, kind]) => kind !== "mix")))

  const activeDiff = createMemo(() => {
    // A focused comment takes over the preview until the preview applies it and
    // clears the focus; the owner then persists the file as the active selection.
    const focus = props.focusedComment

    if (focus && diffs().some((diff) => diff.file === focus.file)) return focus.file
    const active = props.activeFile

    if (searching()) return active
    const files = navigationFiles()

    if (active && files.includes(active)) return active

    return files[0]
  })

  const sourceActiveItem = createMemo(() => diffs().find((diff) => diff.file === activeDiff()))

  const detailSource = createMemo(() => {
    const diff = sourceActiveItem()
    const load = props.loadDiff

    if (!diff || !load || !reviewDiffNeedsLoad(diff)) return undefined

    return { diff, load, version: props.diffVersion }
  })

  const [loadedDiff] = createResource(detailSource, async ({ diff, load, version }) => {
    const value = await load(diff.file, version)

    if (value?.file !== diff.file) return undefined

    return { source: diff, version, value }
  })

  const activeItem = createMemo(() => {
    const source = sourceActiveItem()

    if (loadedDiff.state !== "ready") return source
    const loaded = loadedDiff()

    if (loaded && loaded.source === source && loaded.version === props.diffVersion) return loaded.value

    return source
  })

  return (
    <SessionReviewV2
      title={props.title}
      stats={<DiffChanges changes={diffs()} />}
      empty={props.empty}
      sidebarOpen={props.state.sidebar.opened()}
      sidebarToggle={
        <SessionReviewV2SidebarToggle opened={props.state.sidebar.opened()} onToggle={props.state.sidebar.toggle} />
      }
      toolbarAction={
        <Show when={openIn()}>
          {(openIn) => <Dynamic component={openIn().Button} screen={props.screen} session={props.session} />}
        </Show>
      }
      sidebar={
        // Always mounted: the sidebar header hosts the changes-mode dropdown,
        // which must stay reachable when the current mode has zero diffs.
        <ReviewPanelSidebar
          screen={props.screen}
          session={props.session}
          title={props.title}
          state={props.state}
          diffsReady={props.diffsReady}
          onSelectFile={props.onSelectFile}
          diffs={diffs()}
          filteredFiles={filteredFiles()}
          searching={searching()}
          kinds={treeKinds()}
          activeDiff={activeDiff()}
        />
      }
      activeFile={activeDiff()}
      files={navigationFiles()}
      onSelectFile={props.onSelectFile}
      diffStyle={props.diffStyle}
      onDiffStyleChange={props.onDiffStyleChange}
      expandMode={props.state.expandMode()}
      onExpandModeChange={props.state.setExpandMode}
      hasDiffs={diffs().length > 0}
      preview={
        // Key on the file path, not the diff object identity, so refreshed diff data
        // updates the mounted preview instead of remounting the whole viewer.
        <Show when={activeDiff()} keyed>
          {(file) => (
            <Show when={activeItem()}>
              {(diff) => (
                <SessionReviewFilePreviewV2
                  file={file}
                  diff={diff()}
                  diffStyle={props.diffStyle}
                  expandMode={props.state.expandMode()}
                  readFile={props.readFile}
                  onLineComment={props.onLineComment}
                  onLineCommentUpdate={props.onLineCommentUpdate}
                  onLineCommentDelete={props.onLineCommentDelete}
                  lineCommentActions={props.lineCommentActions}
                  comments={props.comments}
                  focusedComment={props.focusedComment}
                  onFocusedCommentChange={props.onFocusedCommentChange}
                />
              )}
            </Show>
          )}
        </Show>
      }
    />
  )
}

function ReviewPanelSidebar(props: {
  screen: SessionScreen
  session: MountedSession
  title?: JSX.Element
  state: ReviewPanelState
  diffsReady: boolean
  onSelectFile: (path: string) => void
  diffs: RenderDiff[]
  filteredFiles: string[]
  searching: boolean
  kinds: ReturnType<typeof reviewDiffKinds>
  activeDiff: string | undefined
}) {
  const ctx = useExtension<typeof Review>()

  // The file extension draws the change tree; while it is unavailable the list stays empty.
  const views = () => {
    const tree = ctx.uses.tree()

    return tree.status === "active" ? tree.value : undefined
  }

  const [explicitHighlight, setExplicitHighlight] = createSignal<string | undefined>()

  const highlightedPath = createMemo(() => {
    if (!props.searching) return undefined
    const files = props.filteredFiles

    if (files.length === 0) return undefined
    const explicit = explicitHighlight()

    if (explicit && files.includes(explicit)) return explicit

    return files[0]
  })

  const onFilterKeyDown = (event: KeyboardEvent & { currentTarget: HTMLInputElement }) => {
    if (!props.searching) return
    applyFileListKeyDown(event, props.filteredFiles, highlightedPath(), {
      onHighlight: setExplicitHighlight,
      onSelect: props.onSelectFile,
    })
  }

  return (
    <SessionReviewV2Sidebar
      open={props.state.sidebar.opened()}
      transition={props.state.sidebar.transition()}
      title={props.title}
      stats={<DiffChanges changes={props.diffs} />}
      filter={props.state.filter()}
      onFilterChange={props.state.setFilter}
      onFilterKeyDown={onFilterKeyDown}
      width={props.state.sidebar.width()}
      onWidthChange={props.state.sidebar.resize}
      minWidth={SESSION_REVIEW_V2_SIDEBAR_WIDTH_MIN}
      maxWidth={SESSION_REVIEW_V2_SIDEBAR_WIDTH_MAX}
    >
      <Show
        when={props.diffsReady}
        fallback={
          <div class="px-2 py-2 text-12-regular text-text-weak">
            {ctx.t("common.loading")}
            {ctx.t("common.loading.ellipsis")}
          </div>
        }
      >
        <Show
          when={props.searching}
          fallback={
            <Show when={views()}>
              {(views) => (
                <Dynamic
                  component={views().Tree}
                  screen={props.screen}
                  session={props.session}
                  allowed={props.filteredFiles}
                  kinds={props.kinds}
                  active={props.activeDiff}
                  onFileClick={props.onSelectFile}
                />
              )}
            </Show>
          }
        >
          <Show
            when={props.filteredFiles.length > 0}
            fallback={<div class="px-2 py-2 text-12-regular text-text-weak">{ctx.t("palette.empty")}</div>}
          >
            <Show when={views()}>
              {(views) => (
                <Dynamic
                  component={views().List}
                  screen={props.screen}
                  session={props.session}
                  files={props.filteredFiles}
                  kinds={props.kinds}
                  active={props.activeDiff}
                  highlighted={highlightedPath()}
                  onFileClick={(path: string) => {
                    setExplicitHighlight(path)
                    props.onSelectFile(path)
                  }}
                />
              )}
            </Show>
          </Show>
        </Show>
      </Show>
    </SessionReviewV2Sidebar>
  )
}

import { Match, Show, Switch } from "solid-js"
import { SessionReviewEmptyChangesV2 } from "@opencode/session-ui/v2/session-review-empty-changes-v2"
import { SessionReviewEmptyNoGitV2 } from "@opencode/session-ui/v2/session-review-empty-no-git-v2"
import { Select } from "@opencode/ui/select"
import { useExtension } from "../sdk"
import type { ChangeMode, ReviewModel } from "./model"

export function ReviewTitle(props: { review: ReviewModel }) {
  const ctx = useExtension()

  const label = (option: ChangeMode) => {
    if (option === "git") return ctx.t("ui.sessionReview.title.git")

    if (option === "branch") return ctx.t("ui.sessionReview.title.branch")

    return ctx.t("ui.sessionReview.title.lastTurn")
  }

  return (
    <Show when={props.review.canReview() && props.review.options().length > 0}>
      <Show
        when={props.review.options().length === 1 && props.review.options()[0]}
        fallback={
          <Select
            options={props.review.options()}
            current={props.review.mode()}
            label={label}
            placement="bottom-start"
            gutter={6}
            onSelect={(option) => option && props.review.setMode(option)}
          />
        }
      >
        {(only) => (
          <span class="inline-flex h-6 items-center ps-2 pe-1 text-[13px] leading-[var(--line-height-compact)] font-[530] tracking-[-0.04px] text-v2-text-text-base">
            {label(only())}
          </span>
        )}
      </Show>
    </Show>
  )
}

export function ReviewEmpty(props: { review: ReviewModel; loadingClass: string }) {
  const ctx = useExtension()
  const loading = () => !props.review.ready()

  const text = () => {
    if (props.review.mode() === "git") return ctx.t("empty.git")

    if (props.review.mode() === "branch") return ctx.t("empty.branch")

    return ctx.t("noChanges")
  }

  return (
    <Switch>
      <Match when={loading()}>
        <div class={props.loadingClass}>{ctx.t("loadingChanges")}</div>
      </Match>
      <Match when={props.review.noGit()}>
        <div class="h-full flex flex-col">
          <SessionReviewEmptyNoGitV2 pending={props.review.initializingGit()} onInitGit={props.review.initializeGit} />
        </div>
      </Match>
      <Match when={true}>
        <div class="h-full pb-64 -mt-4 flex flex-col items-center justify-center text-center gap-6">
          <div class="text-14-regular text-text-weak max-w-56">{text()}</div>
        </div>
      </Match>
    </Switch>
  )
}

export function ReviewPanelEmpty(props: { review: ReviewModel }) {
  const ctx = useExtension()
  const loading = () => !props.review.ready()

  return (
    <Switch>
      <Match when={loading()}>
        <div class="px-6 py-4 text-text-weak">{ctx.t("loadingChanges")}</div>
      </Match>
      <Match when={props.review.noGit()}>
        <SessionReviewEmptyNoGitV2 pending={props.review.initializingGit()} onInitGit={props.review.initializeGit} />
      </Match>
      <Match when={true}>
        <SessionReviewEmptyChangesV2 />
      </Match>
    </Switch>
  )
}

import {
  batch,
  createMemo,
  createRoot,
  createSignal,
  getOwner,
  lazy,
  onCleanup,
  Show,
  Suspense,
  untrack,
} from "solid-js"
import { createStore } from "solid-js/store"
import type { FileDiffInfo } from "@opencode/client/promise"
import {
  createKeyed,
  LinkHandler,
  Panel,
  SettingsPage,
  usePanel,
  type PanelTab,
  type SessionScreen,
  type SessionRef,
  type MountedSession,
  type Setup,
  onIdle,
} from "../sdk"
import { Changes, type ChangeKind } from "./contract"
import type Review from "./index"
import { createReviewModel, type Demand, type ReviewModel } from "./model"

const TAB = "changes"

const KEY = `review:${TAB}`

const setup: Setup<typeof Review> = (ctx) => {
  const owner = getOwner()
  const sessions = ctx.sessions
  const layout = ctx.layout
  const diff = ctx.stores.diff
  const panel = ctx.stores.panel

  // Who shows a screen's changes: the review render, the file tree, and file tabs. Keyed by the session screen, which
  // stays while it routes another session, so a session switch keeps the demand.
  const demands = new WeakMap<SessionScreen, ReturnType<typeof createStore<Demand>>>()

  const demand = (screen: SessionScreen) => {
    const existing = demands.get(screen)

    if (existing) return existing

    const created = createStore<Demand>({ tree: 0, files: 0, panel: 0, details: 0 })

    demands.set(screen, created)

    return created
  }

  // Views receive their screen before the public attachment is published, so initial render effects can watch it.
  const watch = (screen: SessionScreen, source: keyof Demand) => {
    const set = demand(screen)[1]

    set(source, (count) => count + 1)

    return () => set(source, (count) => Math.max(0, count - 1))
  }

  // One review model per session screen, like the review the screen created before extensions, created once the
  // screen routes a session. It follows the routed session, a new object on each switch, through `view`.
  const [entry, setEntry] = createSignal<{ screen: SessionScreen; model: ReviewModel; dispose: () => void }>()

  createKeyed(
    ctx.screen.current,
    (screen) => {
      const current = untrack(entry)
      const initial = untrack(sessions.current)

      if (current?.screen === screen || !initial) return

      current?.dispose()
      setEntry(
        createRoot((dispose) => {
          // The routed session of this screen; the last one stays while none is routed for a moment.
          const view = createMemo<MountedSession>(
            (last) => (ctx.screen.current() === screen ? sessions.current() : undefined) ?? last,
            initial,
          )

          return { screen, model: createReviewModel({ ctx, screen, view, demand: demand(screen)[0] }), dispose }
        }, owner),
      )
    },
    {
      // A screen that unmounts and remounts in one update keeps its model.
      otherwise: () => {
        const current = untrack(entry)

        queueMicrotask(() => {
          if (sessions.current() || untrack(entry) !== current) return

          current?.dispose()
          setEntry(undefined)
        })
      },
    },
  )
  onCleanup(() => untrack(entry)?.dispose())

  const modelFor = (session: SessionRef) => {
    const model = entry()?.model

    return model && model.view().key === session.key ? model : undefined
  }

  const count = () => entry()?.model.count() ?? 0

  // One tab object for every session, so a session switch never renders its trigger again.
  const tab: PanelTab = {
    id: TAB,
    get title() {
      return count() > 0 ? ctx.plural("tab.count", count()) : ctx.t("tab.title")
    },
    pinned: true,
    // Without focusable content the panel itself joins the tab order.
    get tabbable() {
      return !(count() > 0 || layout.sidebar.opened())
    },
    fallback: true,
    dom: { tab: "session-side-panel-review-tab", panel: "session-side-panel-review-tabpanel" },
  }

  const ReviewPanel = lazy(() => import("./panel"))
  const MobileReview = lazy(() => import("./mobile"))

  onCleanup(onIdle(() => void (layout.narrow() ? MobileReview : ReviewPanel).preload()))

  ctx.add(Panel, {
    id: "main",
    region: "side",
    // The split diff needs the wider session minimum while the side region is open.
    get wide() {
      return diff.value.diffStyle === "split"
    },
    // The review tab is pinned, never stored; a stored key, such as one from before extensions, leaves the strip.
    transient: true,
    legacy: { review: TAB },
    mobile: {
      get title() {
        return ctx.plural("mobile.title", 0)
      },
      order: 10,
      kind: "tab",
    },
    list: (input) => (!layout.narrow() && input.session.project ? [tab] : []),
    render: (props) => {
      const frame = usePanel()

      // A server switch mounts a new screen before the owned model effect runs. Never render the old screen's model.
      const model = () => {
        const current = entry()

        return current?.screen === props.screen ? current.model : undefined
      }

      return (
        <Show when={model()} keyed>
          {(model) => {
            createKeyed(frame.visible, () => onCleanup(watch(props.screen, "panel")))

            return (
              <Show
                when={frame.placement() === "mobile"}
                fallback={
                  <div class="flex flex-col h-full overflow-hidden bg-v2-background-bg-base contain-strict">
                    <Show when={model.panelRendered()}>
                      <Suspense>
                        <ReviewPanel
                          review={model}
                          session={props.session}
                          diffStyle={diff.value.diffStyle}
                          onDiffStyleChange={(style) =>
                            diff.update((draft) => {
                              draft.diffStyle = style
                            })
                          }
                          expandMode={panel.value.expandMode}
                          onExpandModeChange={(mode) =>
                            panel.update((draft) => {
                              draft.expandMode = mode
                            })
                          }
                        />
                      </Suspense>
                    </Show>
                  </div>
                }
              >
                <Suspense>
                  <MobileReview review={model} session={props.session} />
                </Suspense>
              </Show>
            )
          }}
        </Show>
      )
    },
  })

  const reveals = new Set<() => void>()

  // A review comment in the composer reveals its diff.
  ctx.add(LinkHandler, {
    priority: 1,
    match: (link) => link.origin === "review",
    open(link) {
      const session = sessions.current()

      if (!session || (link.session && link.session.key !== session.key)) return

      batch(() => {
        // Narrow screens keep their view, as they did before extensions.
        if (!layout.narrow() && session.project) layout.open(KEY, session)

        reveals.forEach((listener) => listener())
        modelFor(session)?.focusFile(link.href)
      })
    },
  })

  const WrapLinesRow = lazy(() => import("./settings"))
  // Settings rows are small; load them while idle so settings opens without a blank row.
  onCleanup(onIdle(() => void WrapLinesRow.preload()))

  // The narrow-screen diff wrap toggle, in its place in the host's General section.
  ctx.add(SettingsPage, {
    id: "mobile-diff",
    page: "general",
    section: "general",
    get title() {
      return ctx.t("settings.wrapLines.title")
    },
    get entries() {
      return [
        { id: "settings-mobile-diff-wrap", title: ctx.t("settings.wrapLines.title"), keywords: "diff wrap lines" },
      ]
    },
    render: () => (
      <Suspense>
        <WrapLinesRow />
      </Suspense>
    ),
  })

  const none: readonly FileDiffInfo[] = []
  const noKinds: ReadonlyMap<string, ChangeKind> = new Map()

  ctx.provide(Changes, {
    diffs: (session) => modelFor(session)?.diffs() ?? none,
    ready: (session) => modelFor(session)?.ready() ?? false,
    kinds: (session) => modelFor(session)?.kinds() ?? noKinds,
    active: (session) => modelFor(session)?.activeFile(),
    details: (session) => modelFor(session)?.details(),
    focus: (session, path) => modelFor(session)?.focusFile(path),
    open(session) {
      // The session details' changes row: narrow screens switch to the Changes view; wide ones open the side region.
      if (layout.narrow()) return layout.open(KEY, session)

      if (!layout.side.opened(session)) layout.side.toggle(session)
    },
    watch,
    onReveal(listener) {
      reveals.add(listener)

      return () => {
        reveals.delete(listener)
      }
    },
  })
}

