import { Button } from "@opencode/ui/button"
import { Dialog, DialogBody, DialogFooter, DialogHeader, DialogTitle } from "@opencode/ui/dialog"
import { Divider } from "@opencode/ui/divider"
import { TextInput } from "@opencode/ui/text-input"
import { useDialog } from "@opencode/ui/context/dialog"
import { createMemo, createSignal, on, onCleanup, onMount, Show } from "solid-js"
import { createStore } from "solid-js/store"
import { createKeyed, useExtension } from "../sdk"
import type { SshConfig, SshItem } from "./contract"
import { isSshConnecting, sshName } from "./name"
import type { SshController } from "./state"

export { default as css } from "./ssh.css?inline"

export function DialogSsh(props: {
  ssh: SshController
  config?: SshConfig
  connect?: boolean
  promptOnly?: boolean
  /** Runs with the server id once it connects. Only the palette entry point opens a project. */
  onOpenProject?: (id: string) => void
  onConnected?: () => void
}) {
  const dialog = useDialog()
  const extension = useExtension()
  const ssh = props.ssh
  // Entry-point behavior is fixed for the lifetime of this dialog.
  const openProject = props.onOpenProject
  const id = props.config?.id ?? crypto.randomUUID()
  let cancelButton: HTMLButtonElement | undefined

  const [state, setState] = createStore({
    target: props.config?.target ?? "",
    name: props.config?.name ?? "",
    started: !!props.promptOnly,
    // Counts `start` calls, each of which forgets the challenges shown before it.
    starts: 0,
    complete: false,
  })

  const item = createMemo(() => ssh.item(id))

  const error = createMemo(() => {
    if (ssh.error(id)) return extension.t("common.requestFailed")
    const error = item()?.error

    return error ? extension.t(`error.${error}`) : undefined
  })

  const busy = createMemo(
    () => ssh.submitting(id) || (state.started && !ssh.error(id) && isSshConnecting(item()?.stage ?? "connecting")),
  )

  const prompt = createMemo<SshItem["prompt"]>((previous) => item()?.prompt ?? (busy() ? previous : undefined))
  // A new object for each challenge shown, and when one goes away.
  const challenge = createMemo(on([prompt, () => prompt()?.id], () => ({})))

  // A challenge showed since the dialog opened, or since the last start when it was started again.
  const prompted = createMemo(
    (previous: { readonly starts: number; readonly value: boolean }) => {
      const shown = !!prompt()

      return previous.starts === state.starts
        ? { starts: state.starts, value: previous.value || shown }
        : { starts: state.starts, value: shown }
    },
    { starts: 0, value: !!props.promptOnly },
  )

  // What the user typed belongs to the challenge it was typed for; the next one starts empty.
  const [typed, setTyped] = createSignal({ challenge: challenge(), value: "" })

  const response = () => {
    const current = typed()

    return current.challenge === challenge() ? current.value : ""
  }

  const waiting = () => busy() || ssh.answered(id)

  const start = (replace = false) => {
    if (busy() || !state.target.trim()) return
    setState({ started: true, starts: state.starts + 1 })
    ssh.connect({ id, target: state.target, name: state.name }, { dialog: true, replace })
  }

  const respond = () => {
    const current = item()?.prompt

    if (!current || waiting() || (!current.confirm && !response())) return
    ssh.respond(id, current.id, current.confirm ? "yes" : response())
  }

  // Never let a focused Continue button become Trust between SSH challenges.
  createKeyed(
    () => (prompt()?.confirm ? challenge() : undefined),
    () => queueMicrotask(() => cancelButton?.focus()),
  )

  // Closes the dialog once the server it started is ready.
  createKeyed(
    () => state.started && item()?.stage === "ready" && !ssh.submitting(id) && !state.complete,
    () => {
      setState("complete", true)
      dialog.close()

      if (openProject) queueMicrotask(() => openProject(id))

      if (props.onConnected) queueMicrotask(props.onConnected)
    },
  )
  onMount(() => {
    if (props.connect) start()
  })
  onCleanup(() => {
    if (state.started && !state.complete) ssh.cancel(id)
  })

  const keyDown = (event: KeyboardEvent) => {
    if (event.key !== "Enter" || event.isComposing) return
    event.preventDefault()

    if (prompt()) return
    start(item()?.stage === "incompatible")
  }

  return (
    <Dialog fit class="settings-server-dialog">
      <DialogHeader hideClose={true}>
        <DialogTitle>
          {prompted().value || props.config ? extension.t("connectTo", { host: sshName(state) }) : extension.t("add")}
        </DialogTitle>
      </DialogHeader>
      <Divider />
      <DialogBody class="flex w-full min-w-0 flex-1 flex-col px-4 pt-4 pb-2">
        <div class="flex w-full min-w-0 flex-col gap-6">
          <Show
            when={
              !props.promptOnly && item()?.stage !== "incompatible" && (!prompted().value || (!!error() && !prompt()))
            }
          >
            <div class="flex w-full min-w-0 flex-col gap-2">
              <label class="settings-server-dialog-label" for="ssh-target">
                {extension.t("target")}
              </label>
              <TextInput
                id="ssh-target"
                type="text"
                appearance="large"
                class="!w-full self-stretch"
                dir="ltr"
                value={state.target}
                autofocus
                placeholder={extension.t("placeholder")}
                spellcheck={false}
                autocomplete="off"
                disabled={busy() || !!prompt()}
                invalid={!!error()}
                onInput={(event) => setState("target", event.currentTarget.value)}
                onKeyDown={keyDown}
              />
            </div>
            <div class="flex w-full min-w-0 flex-col gap-2">
              <label class="settings-server-dialog-label" for="ssh-name">
                {extension.t("form.name")}
              </label>
              <TextInput
                id="ssh-name"
                type="text"
                appearance="large"
                class="!w-full self-stretch"
                dir="auto"
                value={state.name}
                placeholder={extension.t("form.namePlaceholder")}
                disabled={busy() || !!prompt()}
                onInput={(event) => setState("name", event.currentTarget.value)}
                onKeyDown={keyDown}
              />
            </div>
          </Show>
          <Show when={item()?.stage === "incompatible"}>
            <div class="flex w-full min-w-0 flex-col gap-2" role="status" aria-live="polite">
              <span class="text-14-medium text-v2-text-text-base">{extension.t("stage.incompatible")}</span>
              <span class="text-13-regular text-v2-text-text-muted">{extension.t("error.version")}</span>
            </div>
          </Show>
          <Show when={prompt()} keyed>
            {(prompt) => (
              <div class="flex w-full min-w-0 flex-col gap-2">
                <pre id="ssh-prompt" class="ssh-prompt" dir="auto">
                  {prompt.text}
                </pre>
                <Show when={!prompt.confirm}>
                  <TextInput
                    id="ssh-response"
                    aria-labelledby="ssh-prompt"
                    ref={(element) =>
                      queueMicrotask(() => {
                        if (element.isConnected) element.focus()
                      })
                    }
                    type="password"
                    appearance="large"
                    class="!w-full self-stretch"
                    autofocus
                    value={response()}
                    autocomplete="off"
                    spellcheck={false}
                    disabled={waiting()}
                    onInput={(event) => setTyped({ challenge: challenge(), value: event.currentTarget.value })}
                    onKeyDown={(event) => {
                      if (event.key === "Enter" && !event.isComposing) {
                        event.preventDefault()
                        respond()
                      }
                    }}
                  />
                </Show>
              </div>
            )}
          </Show>
          <Show when={item()?.stage !== "incompatible" && error()}>
            {(error) => (
              <span class="settings-server-dialog-error !leading-[var(--line-height-compact)]" role="alert">
                {error()}
              </span>
            )}
          </Show>
        </div>
      </DialogBody>
      <DialogFooter>
        <Button
          ref={(element: HTMLButtonElement) => {
            cancelButton = element
          }}
          variant="neutral"
          onClick={() => dialog.close()}
        >
          {extension.t("common.cancel")}
        </Button>
        <Show
          when={prompt()}
          fallback={
            <Button
              variant="contrast"
              disabled={busy() || !state.target.trim()}
              onClick={() => start(item()?.stage === "incompatible")}
            >
              {busy()
                ? extension.t("stage.connecting")
                : item()?.stage === "incompatible"
                  ? extension.t("update")
                  : props.config
                    ? extension.t("connect")
                    : extension.t("form.add")}
            </Button>
          }
        >
          {(prompt) => (
            <Button variant="contrast" disabled={waiting() || (!prompt().confirm && !response())} onClick={respond}>
              {waiting() ? extension.t("stage.connecting") : extension.t(prompt().confirm ? "trust" : "continue")}
            </Button>
          )}
        </Show>
      </DialogFooter>
    </Dialog>
  )
}

import { NodeServices } from "@effect/platform-node"
import { Effect, Exit, Fiber, Layer, ManagedRuntime, Scope, Stream } from "effect"
import { FetchHttpClient } from "effect/http"
import type { MainSetup } from "../sdk/main"
import { SshFailure } from "./command"
import { Ssh } from "./contract"
import { createSshController } from "./controller"
import type definition from "./index"

const setup: MainSetup<typeof definition> = async (ctx) => {
  const cli = ctx.cli
  const saved = ctx.stores.servers

  // Each resource's teardown is registered as it is acquired, so a setup that fails or is aborted part way releases
  // what it holds. The scope runs finalizers in reverse: the changes, the controller, its scope, then the runtime.
  const runtime = ManagedRuntime.make(Layer.mergeAll(NodeServices.layer, FetchHttpClient.layer))
  ctx.scope.addFinalizer(() => runtime.dispose())

  const scope = await runtime.runPromise(Scope.make())
  ctx.scope.addFinalizer(() => runtime.runPromise(Scope.close(scope, Exit.void)))

  if (ctx.scope.signal.aborted) return

  const controller = await runtime.runPromise(
    createSshController({
      version: cli.version,
      development: cli.development,
      binary: cli.binary ?? cli.command[0] ?? "opencode",
      command: cli.command,
      configs: saved.value,
      save: (configs) => Effect.try({ try: () => saved.set(configs), catch: SshFailure.from }),
    }).pipe(Scope.provide(scope)),
  )

  ctx.scope.addFinalizer(() => runtime.runPromise(controller.close))

  if (ctx.scope.signal.aborted) return

  const status = { revision: 0 }

  const provider = ctx.provide(Ssh, {
    // Each window sees only the prompts of the attempts it started.
    state: (window: number) => ({ ...runtime.runSync(controller.state(window)), revision: status.revision }),
    start: async (input, caller) => {
      await runtime.runPromise(controller.start(input, input.background ? undefined : caller.window))

      return push()
    },
    resolve: (input, caller) => runtime.runPromise(controller.resolve(input.id), { signal: caller.signal }),
    respond: (input, caller) =>
      runtime.runPromise(controller.respond(input.id, input.prompt, input.value, caller.window)),
    cancel: (input, caller) => runtime.runPromise(controller.cancel(input.id, caller.window)),
    forget: (input) => runtime.runPromise(controller.forget(input.id).pipe(Effect.orDie)),
  })

  function push() {
    status.revision++
    provider.changed()

    return status.revision
  }

  const changes = runtime.runFork(controller.changes().pipe(Stream.runForEach(() => Effect.sync(push))))
  ctx.scope.addFinalizer(() => runtime.runPromise(Fiber.interrupt(changes)))
  // A closed window cancels the attempts it was answering.
  ctx.windows.on("close", (win) => void runtime.runPromise(controller.detach(win.id)))
}

export default setup

import type { ServerState } from "../sdk"
import type { SshConfig, SshItem } from "./contract"

export function sshHostname(target: string) {
  // Accepted SSH targets end with a hostname or user@hostname, never a remote
  // command. Strip shell quoting for display only; keep the saved target intact.
  return (
    (target.trim().split(/\s+/).at(-1) ?? "")
      .replace(/["'\\]/g, "")
      .split("@")
      .at(-1) ?? ""
  )
}

export function sshName(config: Pick<SshConfig, "name" | "target">) {
  return config.name || sshHostname(config.target)
}

export function isSshConnecting(stage: SshItem["stage"]) {
  return (
    stage === "connecting" ||
    stage === "checking" ||
    stage === "downloading" ||
    stage === "uploading" ||
    stage === "starting"
  )
}

/** Another window answering the challenge reads as connecting here, not as a prompt of its own. */
export function sshServerState(item: SshItem): ServerState {
  if (isSshConnecting(item.stage) || item.authenticatingElsewhere) return "starting"

  if (item.stage === "authentication") return "auth"

  if (item.stage === "ready" || item.stage === "failed" || item.stage === "incompatible") return item.stage

  return "stopped"
}

export * as RemoteCli from "./remote-cli"

import { Effect, Schema } from "effect"
import { HttpClient, HttpClientResponse } from "effect/http"

export class Failure extends Schema.TaggedError<Failure>()("RemoteCliFailure", {
  code: Schema.Literals(["platform", "version", "install"]),
  detail: Schema.String,
}) {
  override get message() {
    return this.detail
  }
}

export function quote(value: string) {
  return `'${value.replaceAll("'", "'\\''")}'`
}

export function requireVersion(version: string) {
  if (version !== "local" && !/^[0-9][a-zA-Z0-9.+-]*$/.test(version))
    throw new Failure({ code: "version", detail: version })

  return version
}

export function discoverScript(options: { fromPath?: boolean; cache?: { directory: string; prefix: string } } = {}) {
  return `cli=${options.fromPath ? "$(command -v opencode || true)" : '""'}
if [ -z "$cli" ] && [ -x "$HOME/.opencode/bin/opencode" ]; then cli="$HOME/.opencode/bin/opencode"; fi
${
  options.cache
    ? `if [ -z "$cli" ]; then
  for binary in "$HOME"/${quote(options.cache.directory)}/${quote(options.cache.prefix)}*/opencode; do
    if [ -x "$binary" ]; then cli="$binary"; fi
  done
fi
`
    : ""
}if [ -n "$cli" ]; then printf '%s\\n' "$cli"; fi
`
}

// Adapters supply a quoted shell expression, including remote HOME or wslpath expansion.
export function versionScript(command: string) {
  return `if [ -x ${command} ]; then ${command} --version 2>/dev/null || true; fi\n`
}

export function parseVersion(output: string) {
  const line = output
    .split(/\r?\n/)
    .find((line) => line.trim())
    ?.trim()

  if (!line) return null
  const marker = line.lastIndexOf(" v")
  const version = marker === -1 ? line : line.slice(marker + 2)

  if (!version) throw new Error("V2 CLI did not provide a version")

  return version
}

export const probeScript = `set -eu
os=$(uname -s | tr '[:upper:]' '[:lower:]')
arch=$(uname -m)
case "$os" in linux|darwin) ;; *) exit 2 ;; esac
case "$arch" in x86_64|amd64) arch=x64 ;; aarch64|arm64) arch=arm64 ;; *) exit 2 ;; esac
target="$os-$arch"
if [ "$arch" = x64 ]; then target="$target-baseline"; fi
if [ "$os" = linux ]; then
  if [ -f /etc/alpine-release ] || (ldd --version 2>&1 | grep -qi musl); then target="$target-musl"; fi
fi
printf 'OPENCODE_REMOTE_TARGET=%s\\n' "$target"
`

export function archiveUrl(target: string, version: string) {
  if (!/^(linux|darwin)-(x64-baseline|arm64)(-musl)?$/.test(target))
    throw new Failure({ code: "platform", detail: target })

  return `https://registry.npmjs.org/@opencode/cli-${target}/-/cli-${target}-${requireVersion(version)}.tgz`
}

type Source = { type: "download"; url: string } | { type: "archive" } | { type: "installer"; binary?: string }

export function installScript(input: { version: string; directory?: string; source: Source }) {
  const version = requireVersion(input.version)

  // The managed CLI installer also configures the user's shell PATH. Private
  // installations use archives so their destination and shell setup stay isolated.
  if (input.source.type === "installer")
    return `set -eu
curl -fsSL https://raw.githubusercontent.com/anomalyco/opencode/v2/install | bash -s -- ${input.source.binary ? `--binary ${input.source.binary}` : `--version ${quote(version)}`}
${verifyScript('"$HOME/.opencode/bin/opencode"', version)}
`

  return `set -eu
umask 077
destination="$HOME"/${quote(`${input.directory ?? ".opencode/bin"}/opencode`)}
mkdir -p "$(dirname "$destination")"
stage=$(mktemp -d "$(dirname "$destination")/.install-XXXXXX")
trap 'rm -rf "$stage"' EXIT
${stageBinary(input.source)}
chmod 755 "$stage/package/bin/opencode"
${verifyScript('"$stage/package/bin/opencode"', version)}
mv "$stage/package/bin/opencode" "$destination"
`
}

function stageBinary(source: Exclude<Source, { type: "installer" }>) {
  if (source.type === "archive") return 'cat > "$stage/archive.tgz"\ntar -xzf "$stage/archive.tgz" -C "$stage"'

  return `url=${quote(source.url)}
if command -v curl >/dev/null 2>&1; then
  curl -fsSL --connect-timeout 15 --max-time 180 "$url" -o "$stage/archive.tgz"
else
  wget -T 180 -O "$stage/archive.tgz" "$url"
fi
tar -xzf "$stage/archive.tgz" -C "$stage"`
}

function verifyScript(command: string, version: string) {
  return `test "$(${command} --version | awk '{print $NF}' | sed 's/^v//')" = ${quote(version)}`
}

const Beta = Schema.Struct({ version: Schema.String.check(Schema.isPattern(/^0\.0\.0-beta-\d+(?:\.\d+)?$/)) })

export const latestBeta = Effect.fn("RemoteCli.latestBeta")(function* () {
  const http = yield* HttpClient.HttpClient

  const metadata = yield* http.get("https://registry.npmjs.org/@opencode%2fcli/beta").pipe(
    Effect.flatMap(HttpClientResponse.filterStatusOk),
    Effect.flatMap(HttpClientResponse.schemaBodyJson(Beta)),
    Effect.timeout("30 seconds"),
    Effect.mapError(() => new Failure({ code: "install", detail: "https://registry.npmjs.org/@opencode%2fcli/beta" })),
  )

  return metadata.version
})

import { showToast } from "@opencode/ui/toast"
import { createMemo, createRoot, lazy, onCleanup, Suspense, type JSX } from "solid-js"
import { Command, createKeyed, MenuItem, onIdle, Server, Style, type ServerEntry, type Setup } from "../sdk"
import type { SshConfig, SshItem } from "./contract"
import { SshCover, type SshOffer } from "./cover"
import type definition from "./index"
import { sshName, sshServerState } from "./name"
import { createSshController } from "./state"

const loadDialog = () => import("./dialog")

const setup: Setup<typeof definition> = (ctx) => {
  // SSH lives in the desktop main process.
  if (ctx.build.platform !== "desktop") return
  const router = ctx.router
  const ipc = ctx.uses.ssh
  const layout = ctx.layout
  const dialog = ctx.dialogs
  const Row = lazy(() => import("./row"))
  // Settings rows are small; load them while idle so settings opens without a blank row.
  onCleanup(onIdle(() => void Row.preload()))

  const client = () => {
    const live = ipc()

    return live.status === "active" ? live.value : undefined
  }

  const state = () => client()?.state()

  const ssh = createSshController({
    items: () => state()?.servers ?? [],
    api: client,
    // Resolves once main publishes the revision; disabling the extension resolves it early.
    refresh: (revision) =>
      new Promise<void>((resolve) =>
        createRoot((dispose) => {
          const done = () => {
            dispose()
            resolve()
          }

          ctx.signal.addEventListener("abort", done, { once: true })
          createKeyed(
            () => (state()?.revision ?? 0) >= revision,
            () => {
              ctx.signal.removeEventListener("abort", done)
              done()
            },
          )
        }),
      ),
    error: () => showToast({ variant: "error", title: ctx.t("common.requestFailed") }),
  })

  // A visit to the routed page: a new token each time another tab or page is routed, whether or not a cover shows.
  const visit = createMemo(() => ({ path: router.path() }))
  const offer: SshOffer = { visit: undefined }
  const styled = { added: false }
  const byKey = (key: string) => (key.startsWith("ssh:") ? ssh.item(key.slice(4)) : undefined)

  const show = (render: (module: Awaited<ReturnType<typeof loadDialog>>) => JSX.Element) =>
    void loadDialog().then((module) => {
      if (ctx.signal.aborted) return

      if (!styled.added) ctx.add(Style, module.css)
      styled.added = true
      dialog.open(() => render(module))
    })

  const add = (openProject: boolean) =>
    show((module) => (
      <module.DialogSsh
        ssh={ssh}
        onOpenProject={
          openProject
            ? (id) => {
                const item = ssh.item(id)

                if (!item) return
                layout.project(`ssh:${id}`, ctx.t("project", { host: sshName(item.config) }))
              }
            : undefined
        }
      />
    ))

  const entry = (item: SshItem): ServerEntry => {
    const id = item.config.id
    const config = (): SshConfig => ssh.item(id)?.config ?? item.config

    return {
      id,
      name: sshName(item.config),
      label: ctx.t("label"),
      state: sshServerState(item),
      http: item.http,
      reconnect: (signal) => ssh.resolve(id, signal),
      connect: () => new Promise((resolve) => ssh.connect(config(), { onConnected: resolve })),
      remove: () => {
        const live = ipc()

        // Loading or gone, main keeps the server: the removal fails rather than leaving it saved behind the list.
        if (live.status !== "active") return Promise.reject(new Error(ctx.t("error.unavailable")))

        return live.value.forget({ id })
      },
      row: (row) => (
        <Suspense>
          <Row row={row} id={id} ssh={ssh} />
        </Suspense>
      ),
      cover: () => <SshCover id={id} visit={visit()} ssh={ssh} offer={offer} />,
    }
  }

  ctx.add(Server, () => {
    const current = state()

    return {
      ready: current !== undefined,
      order: 2,
      entries: (current?.servers ?? []).filter((item) => item.saved).map(entry),
    }
  })

  ctx.add(
    MenuItem,
    (): MenuItem => ({ menu: "server.add", id: "add", title: ctx.t("add"), order: 1, run: () => add(false) }),
  )
  ctx.add(
    Command,
    (): Command => ({
      id: "add",
      title: ctx.t("add"),
      group: ctx.t("command.category.server"),
      run: () => add(true),
    }),
  )
  ctx.add(
    MenuItem,
    (): MenuItem => ({
      menu: "server.row",
      id: "connect",
      title: ctx.t("connect"),
      order: 1,
      when: (key) => {
        const stage = byKey(key)?.stage

        return stage !== undefined && stage !== "ready" && stage !== "authentication"
      },
      enabled: (key) => !ssh.pending(key.slice(4)),
      run: (key) => {
        const item = byKey(key)

        if (item) ssh.connect(item.config)
      },
    }),
  )
  ctx.add(
    MenuItem,
    (): MenuItem => ({
      menu: "server.row",
      id: "authenticate",
      title: ctx.t("authenticate"),
      order: 1,
      when: (key) => byKey(key)?.stage === "authentication",
      enabled: (key) => !ssh.pending(key.slice(4)),
      run: (key) => {
        const item = byKey(key)

        if (item) ssh.connect(item.config)
      },
    }),
  )

  // Reconnect saved servers in the background once per window. Mark active
  // connections too, so a later manual disconnect is respected.
  const restored = new Set<string>()

  createKeyed(
    () => {
      const unseen = (state()?.servers ?? []).filter((item) => item.saved && !restored.has(item.config.id))

      return unseen.length > 0 ? unseen : undefined
    },
    (unseen) =>
      unseen.forEach((item) => {
        restored.add(item.config.id)

        if (item.stage === "disconnected") void ssh.restore(item.config)
      }),
  )

  // Challenges of an attempt started without its dialog open one of their own.
  createKeyed(
    () => (dialog.active() ? undefined : ssh.dialog.next()),
    (item) => {
      ssh.dialog.opened(item.config.id)
      const config = item.config
      show((module) => <module.DialogSsh ssh={ssh} config={config} promptOnly />)
    },
  )
}

export default setup

import { Button } from "@opencode/ui/button"
import { Icon } from "@opencode/ui/icon"
import { IconButton } from "@opencode/ui/icon-button"
import { Menu } from "@opencode/ui/menu"
import { Spinner } from "@opencode/ui/spinner"
import { Show } from "solid-js"
import { useExtension, type ServerRow } from "../sdk"
import { isSshConnecting, sshName } from "./name"
import type { SshController } from "./state"

export default function SshRow(props: { row: ServerRow; id: string; ssh: SshController }) {
  const extension = useExtension()
  const pending = () => props.ssh.pending(props.id)

  return (
    <Show when={props.ssh.item(props.id)}>
      {(item) => {
        const indicator = () => {
          if (item().stage === "ready") return props.row.health() ?? { healthy: true }

          if (item().stage === "incompatible") return { healthy: false, incompatible: true }

          if (item().stage === "failed") return { healthy: false }

          return undefined
        }

        return (
          <div class="settings-servers-row">
            <div class="settings-servers-lead">
              <props.row.Indicator
                health={indicator()}
                connecting={isSshConnecting(item().stage)}
                auth={item().stage === "authentication"}
              />
              <div class="settings-servers-copy">
                <span class="flex min-w-0 items-center gap-1">
                  <bdi class="settings-servers-name truncate" dir={item().config.name ? "auto" : "ltr"}>
                    {sshName(item().config)}
                  </bdi>
                  <span class="shrink-0 rounded-[3px] border border-v2-border-border-base px-1 py-0.5 text-[9px] leading-none text-v2-text-text-muted">
                    {extension.t("label")}
                  </span>
                </span>
                <Show
                  when={item().stage === "authentication"}
                  fallback={
                    <Show when={props.row.health()?.version}>
                      {(version) => <span class="settings-servers-meta">v{version()}</span>}
                    </Show>
                  }
                >
                  <span class="settings-servers-meta">{extension.t("stage.authentication")}</span>
                </Show>
              </div>
            </div>
            <div class="settings-servers-actions">
              <Show when={item().stage === "authentication" || pending()}>
                <Button
                  size="small"
                  variant="ghost-muted"
                  disabled={pending()}
                  aria-busy={pending()}
                  onClick={() => props.ssh.connect(item().config)}
                >
                  <Show when={pending()}>
                    <Spinner class="size-3.5" />
                  </Show>
                  {pending() ? extension.t("session.connecting") : extension.t("action.authenticate")}
                </Button>
              </Show>
              <Menu gutter={4} modal={false} placement="bottom-end">
                <Menu.Trigger
                  as={IconButton}
                  variant="ghost-muted"
                  size="small"
                  icon={<Icon name="outline-dots" />}
                  aria-label={extension.t("common.moreOptions")}
                />
                <Menu.Portal>
                  <Menu.Content>
                    <Menu.Group>
                      <Menu.GroupLabel>{extension.t("server.menu.label")}</Menu.GroupLabel>
                      <props.row.Items />
                      <Menu.Separator />
                      <Menu.Item onSelect={() => void props.row.remove()}>{extension.t("menu.delete")}</Menu.Item>
                    </Menu.Group>
                  </Menu.Content>
                </Menu.Portal>
              </Menu>
            </div>
          </div>
        )
      }}
    </Show>
  )
}

import { Effect, Fiber, Schedule } from "effect"
import { onCleanup, type Accessor } from "solid-js"
import { createStore } from "solid-js/store"
import { createKeyed, type IpcClient } from "../sdk"
import type { Ssh, SshConfig, SshItem } from "./contract"
import { isSshConnecting } from "./name"

export type SshController = ReturnType<typeof createSshController>

export function createSshController(input: {
  items: () => readonly SshItem[]
  /** Undefined while the main side is loading or gone. */
  api: Accessor<IpcClient<(typeof Ssh)["spec"]> | undefined>
  /** Resolves once this window's state includes `revision`. */
  refresh: (revision: number) => Promise<void>
  error: () => void
}) {
  const [attempts, setAttempts] = createStore<
    Record<
      string,
      | {
          active: boolean
          submitting: boolean
          prompted: boolean
          answered?: string
          error: boolean
          onConnected?: (ready: boolean) => void
        }
      | undefined
    >
  >({})

  const tasks = new Map<string, Fiber.Fiber<void>>()
  const item = (id: string) => input.items().find((item) => item.config.id === id)

  const settle = (id: string) => {
    const attempt = attempts[id]

    if (!attempt?.active) return
    const onConnected = attempt.onConnected
    setAttempts(id, { active: false, onConnected: undefined })
    const ready = item(id)?.stage === "ready"

    if (onConnected) queueMicrotask(() => onConnected(ready))
  }

  const run = (id: string, effect: Effect.Effect<unknown, unknown>) => {
    setAttempts(id, { submitting: true, error: false })
    tasks.set(
      id,
      Effect.runFork(
        effect.pipe(
          Effect.asVoid,
          Effect.catch(() =>
            Effect.sync(() => {
              setAttempts(id, "error", true)

              if (!attempts[id]?.prompted) input.error()
            }),
          ),
          Effect.ensuring(
            Effect.sync(() => {
              tasks.delete(id)
              setAttempts(id, "submitting", false)
            }),
          ),
        ),
      ),
    )
  }

  // Without the main side nothing can connect or answer: the attempt fails at once, as one main rejects.
  const unavailable = (id: string, onConnected?: (ready: boolean) => void) => {
    setAttempts(id, { active: false, submitting: false, error: true, onConnected: undefined })
    input.error()

    if (onConnected) queueMicrotask(() => onConnected(false))
  }

  onCleanup(() => {
    Effect.runFork(Effect.forEach([...tasks.values()], Fiber.interrupt, { discard: true }))
  })
  // Attempts whose server reached an outcome in main's state: they settle and tell whoever waits on them.
  createKeyed(
    () => {
      const done = input.items().flatMap((item) => {
        const attempt = attempts[item.config.id]

        if (!attempt?.active || attempt.submitting) return []

        return item.stage === "ready" ||
          item.stage === "failed" ||
          item.stage === "disconnected" ||
          item.authenticatingElsewhere ||
          (attempt.prompted && item.stage === "authentication" && !item.prompt)
          ? [item.config.id]
          : []
      })

      return done.length > 0 ? done : undefined
    },
    (done) => done.forEach(settle),
  )

  return {
    item,
    submitting: (id: string) => !!attempts[id]?.submitting,
    error: (id: string) => !!attempts[id]?.error,
    answered: (id: string) =>
      !!item(id)?.prompt && !attempts[id]?.error && attempts[id]?.answered === item(id)?.prompt?.id,
    pending: (id: string) =>
      !!attempts[id]?.submitting ||
      !!item(id)?.authenticatingElsewhere ||
      isSshConnecting(item(id)?.stage ?? "disconnected"),
    dialog: {
      next: () =>
        input.items().find((item) => {
          const attempt = attempts[item.config.id]

          return (
            attempt?.active &&
            !attempt.submitting &&
            !attempt.prompted &&
            !attempt.error &&
            (item.prompt || item.stage === "incompatible")
          )
        }),
      opened: (id: string) => setAttempts(id, "prompted", true),
    },
    /** `onConnected` runs once the attempt settles, with whether the server is ready. */
    connect: (
      config: SshConfig,
      options?: { dialog?: boolean; replace?: boolean; onConnected?: (ready: boolean) => void },
    ) => {
      const api = input.api()

      if (!api) return unavailable(config.id, options?.onConnected)

      if (item(config.id)?.authenticatingElsewhere) return

      if (
        attempts[config.id]?.submitting ||
        (attempts[config.id]?.active && !attempts[config.id]?.error && !options?.replace)
      )
        return
      setAttempts(config.id, {
        active: true,
        submitting: true,
        prompted: !!options?.dialog,
        answered: undefined,
        error: false,
        onConnected: options?.onConnected ?? (options?.replace ? attempts[config.id]?.onConnected : undefined),
      })
      run(
        config.id,
        Effect.gen(function* () {
          const revision = yield* Effect.tryPromise(() => api.start({ ...config, replace: options?.replace }))
          // Observe admission before treating an older disconnected snapshot as cancellation.
          yield* Effect.tryPromise(() => input.refresh(revision))
        }),
      )
    },
    respond: (id: string, prompt: string, value: string) => {
      const api = input.api()

      if (!api) return unavailable(id)

      if (item(id)?.prompt?.id !== prompt || attempts[id]?.submitting) return

      if (attempts[id]?.answered === prompt && !attempts[id]?.error) return
      setAttempts(id, "answered", prompt)
      run(
        id,
        Effect.tryPromise(() => api.respond({ id, prompt, value })),
      )
    },
    cancel: (id: string) => {
      const task = tasks.get(id)
      const api = input.api()
      Effect.runFork(
        Effect.gen(function* () {
          if (task) yield* Fiber.interrupt(task)
          setAttempts(id, undefined)

          if (!api) return
          yield* Effect.tryPromise(() => api.cancel({ id }))

          if (!item(id)?.saved) yield* Effect.tryPromise(() => api.forget({ id }))
        }).pipe(Effect.ignore),
      )
    },
    restore: (config: SshConfig) => input.api()?.start({ ...config, background: true }),
    /** Waits for a healthy tunnel, starting one in the background when the last one dropped. */
    resolve: (id: string, signal: AbortSignal) =>
      Effect.runPromise(
        Effect.tryPromise((abort) => {
          const api = input.api()

          if (!api) return Promise.resolve(null)

          return api.resolve({ id }, { signal: abort })
        }).pipe(
          Effect.repeat({ until: (http) => http !== null, schedule: Schedule.spaced(3000) }),
          Effect.flatMap((http) => (http === null ? Effect.interrupt : Effect.succeed(http))),
        ),
        { signal },
      ),
  }
}

export const focusTerminalById = (id: string) => {
  const wrapper = document.getElementById(`terminal-wrapper-${id}`)
  const terminal = wrapper?.querySelector('[data-component="terminal"]')

  if (!(terminal instanceof HTMLElement)) return false

  const textarea = terminal.querySelector("textarea")

  if (textarea instanceof HTMLTextAreaElement) {
    textarea.focus({ preventScroll: true })

    return true
  }

  terminal.focus({ preventScroll: true })
  terminal.dispatchEvent(
    typeof PointerEvent === "function"
      ? new PointerEvent("pointerdown", { bubbles: true, cancelable: true })
      : new MouseEvent("pointerdown", { bubbles: true, cancelable: true }),
  )

  return true
}

import { batch, createMemo, createRoot, getOwner, onCleanup, untrack } from "solid-js"
import { createStore } from "solid-js/store"
import { createKeyed, type Mutable, type Storage, type ServerRef, type MountedSession, type Sessions } from "../sdk"
import { MAX_TERMINAL_SESSIONS, numberFromTitle, TerminalState, type LocalPTY } from "./state"
import { defaultTitle } from "./title"

const STORE = "terminals"

// The raw key terminals used before extensions, in the same workspace storage file.
const LEGACY = "workspace:terminal"

const HANDOFF_MAX = 40

export type TerminalModel = ReturnType<typeof createTerminalModel>

export type TerminalWorkspace = ReturnType<typeof createWorkspace>

type CacheEntry = {
  value: TerminalWorkspace
  dispose: VoidFunction
}

type FocusRequest = { request: number; id?: string; pending: boolean }

const importGhostty = () => import("ghostty-web").then(async (mod) => ({ mod, ghostty: await mod.Ghostty.load() }))

/** The one ghostty-web load the window's terminals share; a failed load is retried by the next terminal. */
type Ghostty = { shared?: ReturnType<typeof importGhostty> }

const workspaceKey = (server: string, directory: string) => `${server}\0${directory}`

const trimTerminal = (pty: Mutable<LocalPTY>) => {
  if (!pty.buffer && pty.cursor === undefined && pty.scrollY === undefined) return

  pty.buffer = undefined
  pty.cursor = undefined
  pty.scrollY = undefined
}

export function createTerminalModel(input: { storage: Storage; sessions: Sessions }) {
  const owner = getOwner()
  const cache = new Map<string, CacheEntry>()
  const [handoff] = input.storage.memory("handoff", { initial: { terminal: new Map<string, string[]>() } })
  const ghostty: Ghostty = {}

  const prune = () => {
    while (cache.size > MAX_TERMINAL_SESSIONS) {
      const first = cache.keys().next().value

      if (!first) return

      const entry = cache.get(first)

      entry?.dispose()
      cache.delete(first)
    }
  }

  return {
    load(session: Pick<MountedSession, "server" | "directory">) {
      // Terminals are workspace-scoped so tabs persist while switching sessions in the same directory.
      const key = workspaceKey(session.server.id, session.directory)
      const existing = cache.get(key)

      if (existing) {
        cache.delete(key)
        cache.set(key, existing)

        return existing.value
      }

      // A cached workspace keeps talking to its own server after the route moves on.
      const server =
        untrack(() => input.sessions.list()).find((ref) => ref.server.id === session.server.id)?.server ??
        session.server

      const directory = session.directory

      const entry = createRoot(
        (dispose) => ({ value: createWorkspace({ storage: input.storage, server, directory, key }), dispose }),
        owner,
      )

      cache.set(key, entry)
      prune()

      return entry.value
    },
    ghostty() {
      if (ghostty.shared) return ghostty.shared

      ghostty.shared = importGhostty().catch((err) => {
        ghostty.shared = undefined
        throw err
      })

      return ghostty.shared
    },
    handoff: {
      set(key: string, value: string[]) {
        const map = handoff.terminal

        map.delete(key)
        map.set(key, value)

        while (map.size > HANDOFF_MAX) {
          const first = map.keys().next().value

          if (first === undefined) return

          map.delete(first)
        }
      },
      get: (key: string) => handoff.terminal.get(key),
    },
    remove(value: { readonly server: string; readonly directory: string }) {
      cache.get(workspaceKey(value.server, value.directory))?.value.clear()
      // Also drops terminals saved before extensions, which opening the store would otherwise import.
      input.storage.remove(STORE, { scope: { server: value.server, directory: value.directory }, from: LEGACY })
    },
    dispose() {
      for (const entry of cache.values()) {
        entry.dispose()
      }

      cache.clear()
    },
  }
}

function createWorkspace(input: { storage: Storage; server: ServerRef; directory: string; key: string }) {
  const location = { directory: input.directory }

  const stored = input.storage.store(STORE, {
    schema: TerminalState,
    initial: { all: [] },
    scope: { server: input.server.id, directory: input.directory },
    from: LEGACY,
  })

  // Empty until the stored terminals load; changes made before then apply over them in order.
  const all = createMemo(() => stored.value?.all ?? [])
  const active = createMemo(() => stored.value?.active)
  const [ui, setUi] = createStore<{ focus?: FocusRequest }>({})
  const focus = { request: 0 }

  const requestFocus = (id?: string, pending = false) => {
    focus.request += 1
    setUi("focus", { request: focus.request, id, pending })

    return focus.request
  }

  const focusRequested = (id?: string) => {
    if (!id) return false

    if (!ui.focus || ui.focus.pending) return false

    return !ui.focus.id || ui.focus.id === id
  }

  const consumeFocus = (id: string) => {
    if (!focusRequested(id)) return

    setUi("focus", undefined)
  }

  const cancelFocus = (request?: number) => {
    if (request !== undefined && ui.focus?.request !== request) return

    setUi("focus", undefined)
  }

  if (typeof document !== "undefined") {
    const cancelOnOutsideFocus = (event: FocusEvent) => {
      if (!ui.focus) return

      if (!(event.target instanceof Element)) return

      if (event.target.closest("#terminal-panel")) return

      cancelFocus()
    }

    document.addEventListener("focusin", cancelOnOutsideFocus)
    onCleanup(() => document.removeEventListener("focusin", cancelOnOutsideFocus))
  }

  const pickNextTerminalNumber = () => {
    const existingTitleNumbers = new Set(
      all().flatMap((pty) => {
        const direct = Number.isFinite(pty.titleNumber) && pty.titleNumber > 0 ? pty.titleNumber : undefined

        if (direct !== undefined) return [direct]

        const parsed = numberFromTitle(pty.title)

        if (parsed === undefined) return []

        return [parsed]
      }),
    )

    return (
      Array.from({ length: existingTitleNumbers.size + 1 }, (_, index) => index + 1).find(
        (number) => !existingTitleNumbers.has(number),
      ) ?? 1
    )
  }

  const removeExited = (id: string) => {
    const list = all()
    const index = list.findIndex((x) => x.id === id)

    if (index === -1) return

    const next = active() === id ? (index === 0 ? list[1]?.id : list[0]?.id) : active()

    stored.update((draft) => {
      draft.active = next
      draft.all.splice(index, 1)
    })
  }

  // A restarted server replaces its data under the same ref, so the subscription follows it.
  createKeyed(
    () => input.server.data,
    (data) =>
      onCleanup(
        data.on("pty.exited", (event) => {
          if (event.location?.directory !== input.directory) return

          removeExited(event.data.id)
        }),
      ),
  )

  const update = (pty: Partial<LocalPTY> & { id: string }) => {
    const index = all().findIndex((x) => x.id === pty.id)
    const previous = index >= 0 ? all()[index] : undefined

    if (index >= 0) {
      stored.update((draft) => void Object.assign(draft.all[index], pty))
    }

    const doUpdate = async () => {
      await input.server.client.pty.update({
        ptyID: pty.id,
        location,
        title: pty.title,
        size: pty.cols && pty.rows ? { rows: pty.rows, cols: pty.cols } : undefined,
      })
    }

    doUpdate().catch((error) => {
      if (previous) {
        const currentIndex = all().findIndex((item) => item.id === pty.id)

        if (currentIndex >= 0) stored.update((draft) => void Object.assign(draft.all[currentIndex], previous))
      }

      console.error("Failed to update terminal", error)
    })
  }

  const clone = async (id: string) => {
    const index = all().findIndex((x) => x.id === id)
    const pty = all()[index]

    if (!pty) return

    const data = await input.server.client.pty
      .create({ location, title: pty.title })
      .then((result) => result.data)
      .catch((error) => {
        console.error("Failed to clone terminal", error)

        return undefined
      })

    if (!data?.id) return

    const wasActive = active() === pty.id

    stored.update((draft) => {
      Object.assign(draft.all[index], {
        id: data.id,
        title: data.title ?? pty.title,
        titleNumber: pty.titleNumber,
        buffer: undefined,
        cursor: undefined,
        scrollY: undefined,
        rows: undefined,
        cols: undefined,
      })

      if (wasActive) draft.active = data.id
    })
  }

  return {
    key: input.key,
    // An accessor, so storing the workspace in a Solid store never unwraps the host's server data.
    server: () => input.server,
    directory: input.directory,
    ready: () => stored.ready(),
    all,
    active,
    clear() {
      stored.set({ active: undefined, all: [] })
    },
    new() {
      const nextNumber = pickNextTerminalNumber()
      const focusRequest = requestFocus(undefined, true)

      const doCreate = async () => {
        return input.server.client.pty
          .create({ location, title: defaultTitle(nextNumber) })
          .then((result) => result.data)
      }

      doCreate()
        .then((data) => {
          const id = data?.id

          if (!id) {
            cancelFocus(focusRequest)

            return
          }

          const newTerminal = {
            id,
            title: data?.title ?? defaultTitle(nextNumber),
            titleNumber: nextNumber,
          }

          batch(() => {
            stored.update((draft) => {
              draft.all.push(newTerminal)
              draft.active = id
            })

            if (ui.focus?.request === focusRequest) {
              setUi("focus", { request: focusRequest, id, pending: false })
            }
          })
        })
        .catch((error) => {
          cancelFocus(focusRequest)
          console.error("Failed to create terminal", error)
        })
    },
    update,
    trim(id: string) {
      const index = all().findIndex((x) => x.id === id)

      if (index === -1) return

      stored.update((draft) => {
        trimTerminal(draft.all[index])
      })
    },
    trimAll() {
      stored.update((draft) => {
        draft.all.forEach(trimTerminal)
      })
    },
    clone,
    open(id: string) {
      stored.update((draft) => {
        draft.active = id
      })
    },
    requestFocus(id?: string) {
      requestFocus(id)
    },
    focusRequested,
    consumeFocus,
    cancelFocus() {
      cancelFocus()
    },
    async close(id: string) {
      const index = all().findIndex((f) => f.id === id)

      if (index !== -1) {
        stored.update((draft) => {
          if (draft.active === id) {
            draft.active = index > 0 ? draft.all[index - 1]?.id : draft.all[1]?.id
          }

          draft.all.splice(index, 1)
        })
      }

      await input.server.client.pty.remove({ ptyID: id, location }).catch((error) => {
        console.error("Failed to close terminal", error)
      })
    },
    move(id: string, to: number) {
      const index = all().findIndex((f) => f.id === id)

      if (index === -1) return

      stored.update((draft) => {
        draft.all.splice(to, 0, draft.all.splice(index, 1)[0])
      })
    },
  }
}

import { For, Show, createMemo, onCleanup, onMount, untrack } from "solid-js"
import { createStore } from "solid-js/store"
import { makeEventListener } from "@solid-primitives/event-listener"
import { DragDropProvider, PointerSensor } from "@dnd-kit/solid"
import { isSortable } from "@dnd-kit/solid/sortable"
import { Accessibility, AutoScroller, Feedback, PointerActivationConstraints } from "@dnd-kit/dom"
import { RestrictToHorizontalAxis } from "@dnd-kit/abstract/modifiers"
import { RestrictToElement } from "@dnd-kit/dom/modifiers"
import { Tabs } from "@opencode/ui/tabs"
import { IconButton } from "@opencode/ui/icon-button"
import { Icon } from "@opencode/ui/icon"
import { Tooltip } from "@opencode/ui/tooltip"
import { Keybind } from "@opencode/ui/keybind"
import { createKeyed, useExtension, usePanel, type MountedSession } from "../sdk"
import type { TerminalModel, TerminalWorkspace } from "./model"
import type { LocalPTY } from "./state"
import { SortableTerminalTab } from "./tab"
import { Terminal } from "./terminal"
import { terminalTabLabel } from "./title"
import { focusTerminalById } from "./focus"

const MAX_CACHED_TERMINAL_WORKSPACES = 20

type CachedTerminalSurface = {
  key: string
  workspace: string
  pty: LocalPTY
  ops: TerminalWorkspace
  focus: boolean
}

type TerminalPanelState = {
  recovered: Record<string, boolean>
  surfaces: CachedTerminalSurface[]
  workspaces: string[]
}

export default function TerminalPanel(props: { model: TerminalModel; session: MountedSession; onClose: () => void }) {
  const extension = useExtension()
  const keybinds = extension.keybinds
  const frame = usePanel()
  const terminal = createMemo(() => props.model.load(props.session))
  const workspaceKey = () => terminal().key
  const opened = frame.visible
  const present = frame.present
  const close = () => props.onClose()
  let tabList: HTMLDivElement | undefined

  onCleanup(() => terminal().cancelFocus())

  const [store, setStore] = createStore<TerminalPanelState>({ recovered: {}, surfaces: [], workspaces: [] })

  const newTerminalKeybind = createMemo(() => [...keybinds.keybind("terminal.new")])

  onMount(() => {
    makeEventListener(document, "focusin", (event) => {
      if (event.target instanceof Element && event.target.closest("#terminal-panel")) return

      setStore("surfaces", (surface) => surface.focus, "focus", false)
    })
  })

  // While the dock shows, a workspace first observed empty gets its first terminal, once per workspace in a row.
  createKeyed(opened, () => {
    const seen = { workspace: "" }

    createKeyed(
      () => {
        const workspace = terminal()

        return workspace.ready() ? workspace : undefined
      },
      (workspace) => {
        if (seen.workspace === workspace.key) return

        seen.workspace = workspace.key

        if (workspace.all().length === 0) workspace.new()
      },
    )
  })

  // The dock closes when the shown workspace loses its last terminal, e.g. when its shell exits.
  createKeyed(
    () => (terminal().all().length > 0 ? terminal() : undefined),
    (workspace) =>
      onCleanup(() =>
        untrack(() => {
          if (terminal() === workspace && workspace.all().length === 0 && opened()) close()
        }),
      ),
  )

  // Focuses the active terminal once the dock shows it and a focus request names it.
  createKeyed(
    () => {
      const id = terminal().active()

      return opened() && id && terminal().focusRequested(id) ? { id } : undefined
    },
    (request) =>
      requestAnimationFrame(() => {
        if (!opened() || terminal().active() !== request.id || !terminal().focusRequested(request.id)) return

        focusTerminalById(request.id)
      }),
  )

  // The titles outlive this instance: after a reload they show until the stored terminals load.
  createKeyed(
    () => {
      if (!props.session.directory || !terminal().ready()) return

      return {
        workspace: workspaceKey(),
        titles: terminal()
          .all()
          .map((pty) => terminalTabLabel({ title: pty.title, titleNumber: pty.titleNumber, t: extension.t })),
      }
    },
    (handoff) => props.model.handoff.set(handoff.workspace, handoff.titles),
    {
      // A terminal changing anything but its title keeps the titles.
      equals: (previous, next) =>
        previous.workspace === next.workspace &&
        previous.titles.length === next.titles.length &&
        previous.titles.every((title, index) => title === next.titles[index]),
    },
  )

  const handoff = createMemo(() => {
    const dir = props.session.directory

    if (!dir) return []

    return props.model.handoff.get(workspaceKey()) ?? []
  })

  const all = () => terminal().all()

  // Keeps each shown terminal mounted for the workspaces shown last, so switching back keeps its screen and session.
  createKeyed(
    () => ({
      workspace: workspaceKey(),
      ready: terminal().ready(),
      active: terminal().active(),
      ptys: terminal().all(),
    }),
    (current) => {
      if (!current.ready) return

      const ids = new Set(current.ptys.map((pty) => pty.id))

      const surfaces = store.surfaces.filter(
        (surface) => surface.workspace !== current.workspace || ids.has(surface.pty.id),
      )

      const pty = current.ptys.find((item) => item.id === current.active)
      const key = pty ? `${current.workspace}\0${pty.id}` : undefined

      if (pty && key && !surfaces.some((surface) => surface.key === key)) {
        surfaces.push({
          key,
          workspace: current.workspace,
          pty,
          ops: terminal(),
          focus: terminal().focusRequested(pty.id),
        })
      }

      const workspaces = [...store.workspaces.filter((item) => item !== current.workspace), current.workspace].slice(
        -MAX_CACHED_TERMINAL_WORKSPACES,
      )

      const keep = new Set(workspaces)

      setStore({ surfaces: surfaces.filter((surface) => keep.has(surface.workspace)), workspaces })
    },
    {
      equals: (previous, next) =>
        previous.workspace === next.workspace &&
        previous.ready === next.ready &&
        previous.active === next.active &&
        previous.ptys === next.ptys,
    },
  )

  const recoverTerminal = (key: string, id: string, clone: (id: string) => Promise<void>) => {
    if (store.recovered[key]) return
    setStore("recovered", key, true)
    void clone(id)
  }

  const markTerminalConnected = (key: string, id: string, trim: (id: string) => void) => {
    setStore("recovered", key, false)
    trim(id)
    const index = store.surfaces.findIndex((surface) => surface.key === key)

    if (!store.surfaces[index]?.focus) return
    setStore("surfaces", index, "focus", false)

    if (!opened() || terminal().active() !== id) return
    focusTerminalById(id)
    terminal().consumeFocus(id)
  }

  const handleTerminalDragEnd = () => {
    const activeId = terminal().active()

    if (!activeId) return
    requestAnimationFrame(() => {
      if (terminal().active() !== activeId) return
      focusTerminalById(activeId)
    })
  }

  return (
    <Show
      when={terminal().ready() || store.surfaces.length > 0}
      fallback={
        <div class="flex flex-col h-full pointer-events-none">
          <div
            class="h-10 flex items-center gap-2 px-2 border-b border-border-weaker-base bg-v2-background-bg-base overflow-hidden"
            classList={{ "pe-12": frame.reserve() }}
          >
            <For each={handoff()}>
              {(title) => (
                <div class="px-2 py-1 rounded-md bg-surface-base text-14-regular text-text-weak truncate max-w-40">
                  {title}
                </div>
              )}
            </For>
            <div class="flex-1" />
            <div class="text-text-weak pr-2">
              {extension.t("common.loading")}
              {extension.t("common.loading.ellipsis")}
            </div>
          </div>
          <div class="flex-1 flex items-center justify-center text-text-weak">{extension.t("loading")}</div>
        </div>
      }
    >
      <DragDropProvider
        sensors={[
          PointerSensor.configure({
            activationConstraints: [new PointerActivationConstraints.Distance({ value: 4 })],
            preventActivation: (event) =>
              event.target instanceof Element &&
              !!event.target.closest('[data-slot="tabs-trigger-close-button"], input, [contenteditable="true"]'),
          }),
        ]}
        modifiers={[RestrictToHorizontalAxis, RestrictToElement.configure({ element: () => tabList ?? null })]}
        plugins={(defaults) => [
          ...defaults.filter((plugin) => plugin !== Accessibility),
          AutoScroller.configure({ acceleration: 8, threshold: { x: 0.05, y: 0 } }),
          Feedback.configure({ dropAnimation: null }),
        ]}
        onDragEnd={(event) => {
          const source = event.operation.source

          if (!event.canceled && isSortable(source) && source.initialIndex !== source.index) {
            terminal().move(source.id.toString(), source.index)
          }

          handleTerminalDragEnd()
        }}
      >
        <div class="flex flex-col h-full">
          <div class="h-[49px] shrink-0 flex border-b border-border-weaker-base">
            <Tabs
              variant="panel"
              value={terminal().active()}
              onChange={(id) => terminal().open(id)}
              class="!h-full min-w-0 !flex-1"
            >
              <Tabs.List
                ref={tabList}
                class="!border-b-0"
                onPointerDown={(event: PointerEvent & { currentTarget: HTMLDivElement }) => {
                  const active = document.activeElement

                  if (event.target === active) return

                  if (active instanceof HTMLInputElement && event.currentTarget.contains(active)) active.blur()
                }}
              >
                <For each={all()}>
                  {(pty, index) => (
                    <SortableTerminalTab terminal={pty} workspace={terminal()} index={index()} onClose={close} />
                  )}
                </For>
                <div class="h-full flex items-center justify-center">
                  <Tooltip
                    value={
                      <>
                        {extension.t("command.new")}
                        <Show when={newTerminalKeybind().length > 0}>
                          <Keybind keys={newTerminalKeybind()} variant="neutral" />
                        </Show>
                      </>
                    }
                    placement="bottom"
                    class="flex items-center"
                  >
                    <IconButton
                      icon={<Icon name="plus-small" size="large" />}
                      variant="ghost"
                      onClick={() => terminal().new()}
                      aria-label={extension.t("command.new")}
                    />
                  </Tooltip>
                </div>
              </Tabs.List>
            </Tabs>
            {/* Reserve outside the scroll viewport so overflowing tabs cannot cover the toggle. */}
            <Show when={frame.reserve()}>
              <div class="w-12 shrink-0" aria-hidden />
            </Show>
          </div>
          <div class="flex-1 min-h-0 relative">
            <For each={store.surfaces}>
              {(surface) => (
                <div
                  id={`terminal-wrapper-${surface.pty.id}`}
                  class="absolute inset-0"
                  classList={{
                    hidden:
                      !present() || surface.workspace !== workspaceKey() || surface.pty.id !== terminal().active(),
                  }}
                >
                  <Terminal
                    pty={surface.pty}
                    server={surface.ops.server()}
                    directory={surface.ops.directory}
                    ghostty={props.model.ghostty}
                    autoFocus={terminal().focusRequested(surface.pty.id)}
                    onAutoFocus={() => {
                      focusTerminalById(surface.pty.id)
                      terminal().consumeFocus(surface.pty.id)
                    }}
                    class="!px-[14px]"
                    onConnect={() =>
                      markTerminalConnected(surface.key, surface.pty.id, (terminalID) => surface.ops.trim(terminalID))
                    }
                    onCleanup={(terminal) => surface.ops.update(terminal)}
                    onConnectError={() =>
                      recoverTerminal(surface.key, surface.pty.id, (terminalID) => surface.ops.clone(terminalID))
                    }
                  />
                </div>
              )}
            </For>
          </div>
        </div>
      </DragDropProvider>
    </Show>
  )
}

import { createMemo, lazy, on, onCleanup, Suspense } from "solid-js"
import { Command, createKeyed, onIdle, Panel, type Setup } from "../sdk"
import type Terminal from "./index"
import { createTerminalModel, type TerminalWorkspace } from "./model"

const DOCK = "terminal:main"

const setup: Setup<typeof Terminal> = (ctx) => {
  const sessions = ctx.sessions
  const layout = ctx.layout
  const model = createTerminalModel({ storage: ctx.storage, sessions })

  onCleanup(model.dispose)
  // The host withdraws the listener with the extension.
  ctx.workspaces.on("remove", model.remove)

  // The routed session's workspace stays loaded while no panel renders it, like the session route did.
  const workspace = createMemo<TerminalWorkspace | undefined>((previous) => {
    const session = sessions.current()

    return session ? model.load(session) : previous
  })

  // The workspace each later route change leaves.
  const left = createMemo(
    on(workspace, (next, previous) => (previous && next !== previous ? previous : undefined), { defer: true }),
  )

  // A workspace the route leaves drops its restore buffers.
  createKeyed(left, (previous) => previous.trimAll())

  const routed = createMemo(() => !!sessions.current())

  const current = () => {
    const session = sessions.current()

    if (!session) return

    return { session, terminal: model.load(session) }
  }

  ctx.add(
    Command,
    (): Command => ({
      id: "toggle",
      title: ctx.t("command.toggle"),
      group: ctx.t("command.category.view"),
      section: "terminal",
      featured: true,
      bind: "ctrl+`",
      slash: { name: "terminal", after: "open" },
      editable: true,
      enabled: routed(),
      run() {
        const target = current()

        if (!target) return

        if (layout.dock.opened(target.session)) {
          target.terminal.cancelFocus()
          layout.close(DOCK, target.session)

          return
        }

        layout.open(DOCK, target.session)
        target.terminal.requestFocus(target.terminal.active())
      },
    }),
  )

  ctx.add(
    Command,
    (): Command => ({
      id: "new",
      title: ctx.t("command.new"),
      description: ctx.t("command.new.description"),
      group: ctx.t("command.category"),
      section: "terminal",
      bind: "ctrl+alt+t",
      editable: true,
      enabled: routed(),
      run() {
        const target = current()

        if (!target) return

        layout.open(DOCK, target.session)

        if (target.terminal.all().length > 0) target.terminal.new()

        if (target.terminal.all().length === 0) target.terminal.requestFocus()
      },
    }),
  )

  ctx.add(
    Command,
    (): Command => ({
      id: "close",
      title: ctx.t("close"),
      group: ctx.t("command.category"),
      section: "terminal",
      bind: "mod+w",
      hidden: true,
      scope: '[data-component="terminal"]',
      enabled: routed(),
      run() {
        const target = current()

        if (!target) return

        const id = target.terminal.active()

        if (!id) return

        const last = target.terminal.all().length === 1

        void target.terminal.close(id)

        if (last) layout.close(DOCK, target.session)
      },
    }),
  )

  const TerminalPanel = lazy(() => import("./panel"))

  // Warms the panel chunk so the first dock open has no blank frame. ghostty-web still loads on the first terminal.
  onCleanup(onIdle(() => void TerminalPanel.preload()))
  // A dock stored open renders with its session at startup, so its chunk loads with the app, not when it idles.
  createKeyed(
    () => sessions.list().some((session) => layout.dock.opened(session)),
    () => void TerminalPanel.preload(),
  )

  // Stable objects with live titles, so a locale change never remounts the dock's terminals.
  const tab = {
    id: "main",
    get title() {
      return ctx.t("tab.title")
    },
  }

  ctx.add(Panel, {
    id: "main",
    region: "dock",
    mobile: {
      get title() {
        return ctx.t("tab.title")
      },
      order: 30,
      kind: "menu",
      icon: "terminal",
    },
    list: () => [tab],
    render: (props) => (
      <Suspense>
        <TerminalPanel model={model} session={props.session} onClose={() => layout.close(DOCK, props.session)} />
      </Suspense>
    ),
  })
}

export default setup

type RecordValue = Record<string, unknown>

const isRecord = (value: unknown): value is RecordValue => {
  return typeof value === "object" && value !== null
}

const isDisposable = (value: unknown): value is { dispose: () => void } => {
  return isRecord(value) && typeof value.dispose === "function"
}

export const disposeIfDisposable = (value: unknown) => {
  if (!isDisposable(value)) return
  value.dispose()
}

const hasSetOption = (value: unknown): value is { setOption: (key: string, next: unknown) => void } => {
  return isRecord(value) && typeof value.setOption === "function"
}

export const setOptionIfSupported = (value: unknown, key: string, next: unknown) => {
  if (!hasSetOption(value)) return
  value.setOption(key, next)
}

export const getHoveredLinkText = (value: unknown) => {
  if (!isRecord(value)) return
  const link = value.currentHoveredLink

  if (!isRecord(link)) return

  if (typeof link.text !== "string") return

  return link.text
}

import { describe, test, expect, afterEach, spyOn } from "bun:test"
import { Terminal, Ghostty } from "ghostty-web"
import { SerializeAddon } from "./serialize"

const ghostty = await Ghostty.load()

const terminals: Terminal[] = []

afterEach(() => {
  for (const term of terminals) {
    term.dispose()
  }

  terminals.length = 0
  document.body.innerHTML = ""
})

function createTerminal(cols = 80, rows = 24): { term: Terminal; addon: SerializeAddon; container: HTMLElement } {
  const container = document.createElement("div")
  document.body.appendChild(container)

  const term = new Terminal({ cols, rows, ghostty })
  const addon = new SerializeAddon()
  term.loadAddon(addon)
  term.open(container)
  terminals.push(term)

  return { term, addon, container }
}

function writeAndWait(term: Terminal, data: string): Promise<void> {
  return new Promise((resolve) => {
    term.write(data, resolve)
  })
}

describe("SerializeAddon", () => {
  test("scrollback reads only the requested tail and restores the cursor on its screen row", async () => {
    const { term, addon } = createTerminal(20, 5)
    await writeAndWait(term, Array.from({ length: 30 }, (_, i) => `line ${i}`).join("\r\n"))
    await writeAndWait(term, "\x1b[2A\x1b[3G")
    expect(term.buffer.normal.length).toBe(30)
    expect([term.buffer.normal.cursorX, term.buffer.normal.cursorY]).toEqual([2, 2])

    const reads = spyOn(term.buffer.normal, "getLine")
    const serialized = addon.serialize({ scrollback: 3 })
    expect(new Set(reads.mock.calls.map((args) => args[0]))).toEqual(new Set([22, 23, 24, 25, 26, 27, 28, 29]))
    reads.mockRestore()

    const restored = createTerminal(20, 5)
    await writeAndWait(restored.term, serialized)
    expect(restored.term.getScrollbackLength()).toBe(3)

    for (let row = 0; row < 8; row++) {
      expect(restored.term.buffer.normal.getLine(row)?.translateToString(true)).toBe(`line ${22 + row}`)
    }

    expect([restored.term.buffer.normal.cursorX, restored.term.buffer.normal.cursorY]).toEqual([2, 2])
  })

  test("preserves color scheme reporting mode", async () => {
    const { term, addon } = createTerminal()
    await writeAndWait(term, "\x1b[?2031h")

    expect(addon.serialize().startsWith("\x1b[?2031h")).toBe(true)
    expect(addon.serialize({ excludeModes: true }).startsWith("\x1b[?2031h")).toBe(false)
  })

  test("round trip keeps text, alternate screen, and colors", async () => {
    const prompt = createTerminal()
    await writeAndWait(
      prompt.term,
      ["\x1b[1;32m❯\x1b[0m \x1b[34mcd\x1b[0m /some/path", "\x1b[1;32m❯\x1b[0m \x1b[34mls\x1b[0m -la", "total 42"].join(
        "\r\n",
      ),
    )
    const text = await roundTrip(prompt)
    expect(/\x1b\[\d+X/.test(text.serialized)).toBe(false)
    expect([0, 1, 2].map((row) => text.restored.buffer.active.getLine(row)?.translateToString(true))).toEqual([
      "❯ cd /some/path",
      "❯ ls -la",
      "total 42",
    ])

    const alternate = createTerminal(20, 5)
    await writeAndWait(alternate.term, "normal\r\n")
    await writeAndWait(alternate.term, "\x1b[?1049h\x1b[HALT")
    expect(alternate.term.buffer.active.type).toBe("alternate")
    const screen = (await roundTrip(alternate)).restored.buffer.active
    expect(screen.type).toBe("alternate")
    expect(screen.getLine(0)?.translateToString(true)).toBe("ALT")
    expect([0, 32]).toContain(screen.getLine(0)!.getCell(10)!.getCode())

    const colors = createTerminal(40, 5)
    await writeAndWait(
      colors.term,
      "\x1b[38;2;255;0;0mHello\x1b[0m \x1b[38;2;0;255;0mWorld\x1b[0m!                            ",
    )
    const original = colors.term.buffer.active.getLine(0)!
    const line = (await roundTrip(colors, { range: { start: 0, end: 0 } })).restored.buffer.active.getLine(0)!
    expect([0, 6, 11].map((cell) => line.getCell(cell)!.getChars())).toEqual(["H", "W", "!"])
    expect([0, 6].map((cell) => line.getCell(cell)!.getFgColor())).toEqual(
      [0, 6].map((cell) => original.getCell(cell)!.getFgColor()),
    )
  })
})

async function roundTrip(
  source: ReturnType<typeof createTerminal>,
  options?: Parameters<SerializeAddon["serialize"]>[0],
) {
  const serialized = source.addon.serialize(options)
  const restored = createTerminal(source.term.cols, source.term.rows).term
  await writeAndWait(restored, serialized)

  return { serialized, restored }
}

/**
 * SerializeAddon - Serialize terminal buffer contents
 *
 * Port of xterm.js addon-serialize for ghostty-web.
 * Enables serialization of terminal contents to a string that can
 * be written back to restore terminal state.
 *
 * Usage:
 * ```typescript
 * const serializeAddon = new SerializeAddon();
 * term.loadAddon(serializeAddon);
 * const content = serializeAddon.serialize();
 * ```
 */

import type { ITerminalAddon, ITerminalCore, IBufferRange } from "ghostty-web"

// ============================================================================
// Buffer Types (matching ghostty-web internal interfaces)
// ============================================================================

interface IBuffer {
  readonly type: "normal" | "alternate"
  readonly cursorX: number
  readonly cursorY: number
  readonly viewportY: number
  readonly baseY: number
  readonly length: number
  getLine(y: number): IBufferLine | undefined
  getNullCell(): IBufferCell
}

interface IBufferLine {
  readonly length: number
  readonly isWrapped: boolean
  getCell(x: number): IBufferCell | undefined
  translateToString(trimRight?: boolean, startColumn?: number, endColumn?: number): string
}

interface IBufferCell {
  getChars(): string
  getCode(): number
  getWidth(): number
  getFgColorMode(): number
  getBgColorMode(): number
  getFgColor(): number
  getBgColor(): number
  isBold(): number
  isItalic(): number
  isUnderline(): number
  isStrikethrough(): number
  isBlink(): number
  isInverse(): number
  isInvisible(): number
  isFaint(): number
  isDim(): boolean
}

type TerminalBuffers = {
  active?: IBuffer
  normal?: IBuffer
  alternate?: IBuffer
}

const isRecord = (value: unknown): value is Record<string, unknown> => {
  return typeof value === "object" && value !== null
}

const isBuffer = (value: unknown): value is IBuffer => {
  if (!isRecord(value)) return false

  if (typeof value.length !== "number") return false

  if (typeof value.cursorX !== "number") return false

  if (typeof value.cursorY !== "number") return false

  if (typeof value.baseY !== "number") return false

  if (typeof value.viewportY !== "number") return false

  if (typeof value.getLine !== "function") return false

  if (typeof value.getNullCell !== "function") return false

  return true
}

const getTerminalBuffers = (value: ITerminalCore): TerminalBuffers | undefined => {
  if (!isRecord(value)) return
  const raw = value.buffer

  if (!isRecord(raw)) return
  const active = isBuffer(raw.active) ? raw.active : undefined
  const normal = isBuffer(raw.normal) ? raw.normal : undefined
  const alternate = isBuffer(raw.alternate) ? raw.alternate : undefined

  if (!active && !normal) return

  return { active, normal, alternate }
}

const getTerminalMode = (value: ITerminalCore, mode: number) => {
  if (!isRecord(value)) return false
  const terminal = value.wasmTerm

  if (!isRecord(terminal) || typeof terminal.getMode !== "function") return false

  return terminal.getMode(mode) === true
}

// ============================================================================
// Types
// ============================================================================

export interface ISerializeOptions {
  /**
   * The row range to serialize. When an explicit range is specified, the cursor
   * will get its final repositioning.
   */
  range?: ISerializeRange
  /**
   * The number of rows in the scrollback buffer to serialize, starting from
   * the bottom of the scrollback buffer. When not specified, all available
   * rows in the scrollback buffer will be serialized.
   */
  scrollback?: number
  /**
   * Whether to exclude the terminal modes from the serialization.
   * Default: false
   */
  excludeModes?: boolean
  /**
   * Whether to exclude the alt buffer from the serialization.
   * Default: false
   */
  excludeAltBuffer?: boolean
}

export interface ISerializeRange {
  /**
   * The line to start serializing (inclusive).
   */
  start: number
  /**
   * The line to end serializing (inclusive).
   */
  end: number
}

export interface IHTMLSerializeOptions {
  /**
   * The number of rows in the scrollback buffer to serialize, starting from
   * the bottom of the scrollback buffer.
   */
  scrollback?: number
  /**
   * Whether to only serialize the selection.
   * Default: false
   */
  onlySelection?: boolean
  /**
   * Whether to include the global background of the terminal.
   * Default: false
   */
  includeGlobalBackground?: boolean
  /**
   * The range to serialize. This is prioritized over onlySelection.
   */
  range?: {
    startLine: number
    endLine: number
    startCol: number
  }
}

// ============================================================================
// Helper Functions
// ============================================================================

function constrain(value: number, low: number, high: number): number {
  return Math.max(low, Math.min(value, high))
}

function equalFg(cell1: IBufferCell, cell2: IBufferCell): boolean {
  return cell1.getFgColorMode() === cell2.getFgColorMode() && cell1.getFgColor() === cell2.getFgColor()
}

function equalBg(cell1: IBufferCell, cell2: IBufferCell): boolean {
  return cell1.getBgColorMode() === cell2.getBgColorMode() && cell1.getBgColor() === cell2.getBgColor()
}

function equalFlags(cell1: IBufferCell, cell2: IBufferCell): boolean {
  return (
    !!cell1.isInverse() === !!cell2.isInverse() &&
    !!cell1.isBold() === !!cell2.isBold() &&
    !!cell1.isUnderline() === !!cell2.isUnderline() &&
    !!cell1.isBlink() === !!cell2.isBlink() &&
    !!cell1.isInvisible() === !!cell2.isInvisible() &&
    !!cell1.isItalic() === !!cell2.isItalic() &&
    !!cell1.isDim() === !!cell2.isDim() &&
    !!cell1.isStrikethrough() === !!cell2.isStrikethrough()
  )
}

// ============================================================================
// Base Serialize Handler
// ============================================================================

abstract class BaseSerializeHandler {
  constructor(protected readonly _buffer: IBuffer) {}

  public serialize(range: IBufferRange, excludeFinalCursorPosition?: boolean): string {
    let oldCell = this._buffer.getNullCell()

    const startRow = range.start.y
    const endRow = range.end.y
    const startColumn = range.start.x
    const endColumn = range.end.x

    this._beforeSerialize(endRow - startRow + 1, startRow, endRow)

    for (let row = startRow; row <= endRow; row++) {
      const line = this._buffer.getLine(row)

      if (line) {
        const startLineColumn = row === range.start.y ? startColumn : 0
        const endLineColumn = Math.min(endColumn, line.length)

        for (let col = startLineColumn; col < endLineColumn; col++) {
          const c = line.getCell(col)

          if (!c) {
            continue
          }

          this._nextCell(c, oldCell, row, col)
          oldCell = c
        }
      }

      this._rowEnd(row, row === endRow)
    }

    this._afterSerialize()

    return this._serializeString(excludeFinalCursorPosition)
  }

  protected _nextCell(_cell: IBufferCell, _oldCell: IBufferCell, _row: number, _col: number): void {}
  protected _rowEnd(_row: number, _isLastRow: boolean): void {}
  protected _beforeSerialize(_rows: number, _startRow: number, _endRow: number): void {}
  protected _afterSerialize(): void {}
  protected _serializeString(_excludeFinalCursorPosition?: boolean): string {
    return ""
  }
}

// ============================================================================
// String Serialize Handler
// ============================================================================

class StringSerializeHandler extends BaseSerializeHandler {
  private _rowIndex: number = 0
  private _allRows: string[] = []
  private _allRowSeparators: string[] = []
  private _currentRow: string = ""
  private _nullCellCount: number = 0
  private _cursorStyle: IBufferCell
  private _firstRow: number = 0
  private _lastContentCursorRow: number = 0

  constructor(
    buffer: IBuffer,
    private readonly _terminal: ITerminalCore,
  ) {
    super(buffer)
    this._cursorStyle = this._buffer.getNullCell()
  }

  protected _beforeSerialize(rows: number, start: number, _end: number): void {
    this._allRows = Array.from<string>({ length: rows })
    this._allRowSeparators = Array.from<string>({ length: rows })
    this._rowIndex = 0

    this._currentRow = ""
    this._nullCellCount = 0
    this._cursorStyle = this._buffer.getNullCell()

    this._lastContentCursorRow = start
    this._firstRow = start
  }

  protected _rowEnd(row: number, isLastRow: boolean): void {
    let rowSeparator = ""

    const nextLine = isLastRow ? undefined : this._buffer.getLine(row + 1)
    const wrapped = !!nextLine?.isWrapped

    if (this._nullCellCount > 0 && wrapped) {
      this._currentRow += " ".repeat(this._nullCellCount)
    }

    this._nullCellCount = 0

    if (!isLastRow && !wrapped) {
      rowSeparator = "\r\n"
    }

    this._allRows[this._rowIndex] = this._currentRow
    this._allRowSeparators[this._rowIndex++] = rowSeparator
    this._currentRow = ""
    this._nullCellCount = 0
  }

  private _diffStyle(cell: IBufferCell, oldCell: IBufferCell): number[] {
    const sgrSeq: number[] = []
    const fgChanged = !equalFg(cell, oldCell)
    const bgChanged = !equalBg(cell, oldCell)
    const flagsChanged = !equalFlags(cell, oldCell)

    if (fgChanged || bgChanged || flagsChanged) {
      if (this._isAttributeDefault(cell)) {
        if (!this._isAttributeDefault(oldCell)) {
          sgrSeq.push(0)
        }
      } else {
        if (flagsChanged) {
          if (!!cell.isInverse() !== !!oldCell.isInverse()) {
            sgrSeq.push(cell.isInverse() ? 7 : 27)
          }

          if (!!cell.isBold() !== !!oldCell.isBold()) {
            sgrSeq.push(cell.isBold() ? 1 : 22)
          }

          if (!!cell.isUnderline() !== !!oldCell.isUnderline()) {
            sgrSeq.push(cell.isUnderline() ? 4 : 24)
          }

          if (!!cell.isBlink() !== !!oldCell.isBlink()) {
            sgrSeq.push(cell.isBlink() ? 5 : 25)
          }

          if (!!cell.isInvisible() !== !!oldCell.isInvisible()) {
            sgrSeq.push(cell.isInvisible() ? 8 : 28)
          }

          if (!!cell.isItalic() !== !!oldCell.isItalic()) {
            sgrSeq.push(cell.isItalic() ? 3 : 23)
          }

          if (!!cell.isDim() !== !!oldCell.isDim()) {
            sgrSeq.push(cell.isDim() ? 2 : 22)
          }

          if (!!cell.isStrikethrough() !== !!oldCell.isStrikethrough()) {
            sgrSeq.push(cell.isStrikethrough() ? 9 : 29)
          }
        }

        if (fgChanged) {
          const color = cell.getFgColor()
          const mode = cell.getFgColorMode()

          if (mode === 2 || mode === 3 || mode === -1) {
            sgrSeq.push(38, 2, (color >>> 16) & 0xff, (color >>> 8) & 0xff, color & 0xff)
          } else if (mode === 1) {
            // Palette
            if (color >= 16) {
              sgrSeq.push(38, 5, color)
            } else {
              sgrSeq.push(color & 8 ? 90 + (color & 7) : 30 + (color & 7))
            }
          } else {
            sgrSeq.push(39)
          }
        }

        if (bgChanged) {
          const color = cell.getBgColor()
          const mode = cell.getBgColorMode()

          if (mode === 2 || mode === 3 || mode === -1) {
            sgrSeq.push(48, 2, (color >>> 16) & 0xff, (color >>> 8) & 0xff, color & 0xff)
          } else if (mode === 1) {
            // Palette
            if (color >= 16) {
              sgrSeq.push(48, 5, color)
            } else {
              sgrSeq.push(color & 8 ? 100 + (color & 7) : 40 + (color & 7))
            }
          } else {
            sgrSeq.push(49)
          }
        }
      }
    }

    return sgrSeq
  }

  private _isAttributeDefault(cell: IBufferCell): boolean {
    const mode = cell.getFgColorMode()
    const bgMode = cell.getBgColorMode()

    if (mode === 0 && bgMode === 0) {
      return (
        !cell.isBold() &&
        !cell.isItalic() &&
        !cell.isUnderline() &&
        !cell.isBlink() &&
        !cell.isInverse() &&
        !cell.isInvisible() &&
        !cell.isDim() &&
        !cell.isStrikethrough()
      )
    }

    const fgColor = cell.getFgColor()
    const bgColor = cell.getBgColor()
    const nullCell = this._buffer.getNullCell()
    const nullFg = nullCell.getFgColor()
    const nullBg = nullCell.getBgColor()

    return (
      fgColor === nullFg &&
      bgColor === nullBg &&
      !cell.isBold() &&
      !cell.isItalic() &&
      !cell.isUnderline() &&
      !cell.isBlink() &&
      !cell.isInverse() &&
      !cell.isInvisible() &&
      !cell.isDim() &&
      !cell.isStrikethrough()
    )
  }

  protected _nextCell(cell: IBufferCell, _oldCell: IBufferCell, row: number, col: number): void {
    const isPlaceHolderCell = cell.getWidth() === 0

    if (isPlaceHolderCell) {
      return
    }

    const codepoint = cell.getCode()
    const isInvalidCodepoint = codepoint > 0x10ffff || (codepoint >= 0xd800 && codepoint <= 0xdfff)
    const isGarbage = isInvalidCodepoint || (codepoint >= 0xf000 && cell.getWidth() === 1)
    const isEmptyCell = codepoint === 0 || cell.getChars() === "" || isGarbage

    const sgrSeq = this._diffStyle(cell, this._cursorStyle)

    const styleChanged = sgrSeq.length > 0

    if (styleChanged) {
      if (this._nullCellCount > 0) {
        this._currentRow += " ".repeat(this._nullCellCount)
        this._nullCellCount = 0
      }

      this._lastContentCursorRow = row

      this._currentRow += `\u001b[${sgrSeq.join(";")}m`

      // Ghostty cells are snapshots; rereading this cell copies the whole row again.
      this._cursorStyle = cell
    }

    if (isEmptyCell) {
      this._nullCellCount += cell.getWidth()
    } else {
      if (this._nullCellCount > 0) {
        this._currentRow += " ".repeat(this._nullCellCount)
        this._nullCellCount = 0
      }

      this._currentRow += cell.getChars()

      this._lastContentCursorRow = row
    }
  }

  protected _serializeString(excludeFinalCursorPosition?: boolean): string {
    let rowEnd = this._allRows.length

    if (this._buffer.length - this._firstRow <= this._terminal.rows) {
      rowEnd = this._lastContentCursorRow + 1 - this._firstRow
    }

    let content = ""

    for (let i = 0; i < rowEnd; i++) {
      content += this._allRows[i]

      if (i + 1 < rowEnd) {
        content += this._allRowSeparators[i]
      }
    }

    if (excludeFinalCursorPosition) return content

    // CUP addresses the screen and ghostty-web reports cursorY relative to the screen, so the
    // serialized range start must not shift the row. The cursor line sits in the screen region
    // at the bottom of the buffer, after any scrollback rows.
    content += `\u001b[${this._buffer.cursorY + 1};${this._buffer.cursorX + 1}H`

    const line = this._buffer.getLine(this._buffer.length - this._terminal.rows + this._buffer.cursorY)
    const cell = line?.getCell(this._buffer.cursorX)

    const style = (() => {
      if (!cell) return this._buffer.getNullCell()

      if (cell.getWidth() !== 0) return cell

      if (this._buffer.cursorX > 0) return line?.getCell(this._buffer.cursorX - 1) ?? cell

      return cell
    })()

    const sgrSeq = this._diffStyle(style, this._cursorStyle)

    if (sgrSeq.length) content += `\u001b[${sgrSeq.join(";")}m`

    return content
  }
}

// ============================================================================
// SerializeAddon Class
// ============================================================================

export class SerializeAddon implements ITerminalAddon {
  private _terminal?: ITerminalCore

  /**
   * Activate the addon (called by Terminal.loadAddon)
   */
  public activate(terminal: ITerminalCore): void {
    this._terminal = terminal
  }

  /**
   * Dispose the addon and clean up resources
   */
  public dispose(): void {
    this._terminal = undefined
  }

  /**
   * Serializes terminal rows into a string that can be written back to the
   * terminal to restore the state. The cursor will also be positioned to the
   * correct cell.
   *
   * @param options Custom options to allow control over what gets serialized.
   */
  public serialize(options?: ISerializeOptions): string {
    if (!this._terminal) {
      throw new Error("Cannot use addon until it has been loaded")
    }

    const buffer = getTerminalBuffers(this._terminal)

    if (!buffer) {
      return ""
    }

    const normalBuffer = buffer.normal ?? buffer.active
    const altBuffer = buffer.alternate

    if (!normalBuffer) {
      return ""
    }

    let content = !options?.excludeModes && getTerminalMode(this._terminal, 2031) ? "\u001b[?2031h" : ""
    content += options?.range
      ? this._serializeBufferByRange(normalBuffer, options.range, true)
      : this._serializeBufferByScrollback(normalBuffer, options?.scrollback)

    if (!options?.excludeAltBuffer && buffer.active?.type === "alternate" && altBuffer) {
      const alternateContent = this._serializeBufferByScrollback(altBuffer, undefined)
      content += `\u001b[?1049h\u001b[H${alternateContent}`
    }

    return content
  }

  /**
   * Serializes terminal content as plain text (no escape sequences)
   * @param options Custom options to allow control over what gets serialized.
   */
  public serializeAsText(options?: { scrollback?: number; trimWhitespace?: boolean }): string {
    if (!this._terminal) {
      throw new Error("Cannot use addon until it has been loaded")
    }

    const buffer = getTerminalBuffers(this._terminal)

    if (!buffer) {
      return ""
    }

    const activeBuffer = buffer.active ?? buffer.normal

    if (!activeBuffer) {
      return ""
    }

    const maxRows = activeBuffer.length
    const scrollback = options?.scrollback
    const correctRows = scrollback === undefined ? maxRows : constrain(scrollback + this._terminal.rows, 0, maxRows)

    const startRow = maxRows - correctRows
    const endRow = maxRows - 1
    const lines: string[] = []

    for (let row = startRow; row <= endRow; row++) {
      const line = activeBuffer.getLine(row)

      if (line) {
        const text = line.translateToString(options?.trimWhitespace ?? true)
        lines.push(text)
      }
    }

    // Trim trailing empty lines if requested
    if (options?.trimWhitespace) {
      while (lines.length > 0 && lines[lines.length - 1] === "") {
        lines.pop()
      }
    }

    return lines.join("\n")
  }

  private _serializeBufferByScrollback(buffer: IBuffer, scrollback?: number): string {
    const maxRows = buffer.length
    const rows = this._terminal?.rows ?? 24
    const correctRows = scrollback === undefined ? maxRows : constrain(scrollback + rows, 0, maxRows)

    return this._serializeBufferByRange(
      buffer,
      {
        start: maxRows - correctRows,
        end: maxRows - 1,
      },
      false,
    )
  }

  private _serializeBufferByRange(
    buffer: IBuffer,
    range: ISerializeRange,
    excludeFinalCursorPosition: boolean,
  ): string {
    const handler = new StringSerializeHandler(buffer, this._terminal!)
    const cols = this._terminal?.cols ?? 80

    return handler.serialize(
      {
        start: { x: 0, y: range.start },
        end: { x: cols, y: range.end },
      },
      excludeFinalCursorPosition,
    )
  }
}

import { describe, expect, test } from "bun:test"
import { Schema } from "effect"
import { TerminalState } from "./state"

const decodeTerminalState = Schema.decodeUnknownSync(TerminalState)

describe("TerminalState", () => {
  test("drops invalid terminals and restores a valid active terminal", () => {
    const decoded = decodeTerminalState({
      active: "missing",
      all: [
        null,
        { id: "one", title: "Terminal 2" },
        { id: "one", title: "duplicate", titleNumber: 9 },
        { id: "two", title: "logs", titleNumber: 4, rows: 24, cols: 80, buffer: "output", cursor: 12, scrollY: 3 },
        { title: "no-id" },
      ],
    })

    expect(decoded).toEqual({
