import { Effect, Option, Schema, SchemaGetter } from "effect"
import { titleNumber } from "./title"

// Same recovery rules as the host's persistence schema helpers, so stored terminals decode as before.
function fallback<S extends Schema.ConstraintCodec<unknown, unknown>>(schema: S, value: () => S["Type"]) {
  const defaulted = Schema.withDecodingDefaultType<S>(Effect.sync(value))(schema)

  return Schema.catchDecoding<typeof defaulted>(() => Effect.sync(() => Option.some(value())))(defaulted)
}

function optional<S extends Schema.ConstraintCodec<unknown, unknown>>(schema: S) {
  const field = Schema.optional(schema)

  return Schema.catchDecoding<typeof field>(() => Effect.succeed(Option.none()))(field)
}

// Recover individual entries rather than discarding the whole collection.
function array<S extends Schema.ConstraintCodec<unknown, unknown>>(schema: S) {
  const decode = Schema.decodeUnknownOption(schema)
  const encode = Schema.encodeSync(schema)

  return fallback(
    Schema.Array(Schema.Unknown).pipe(
      Schema.decodeTo(Schema.Array(Schema.toType(schema)), {
        decode: SchemaGetter.transform((items) => items.flatMap((item) => Option.toArray(decode(item)))),
        encode: SchemaGetter.transform((items) => items.map((item) => encode(item))),
      }),
    ),
    () => [],
  )
}

const PTY = Schema.Struct({
  id: Schema.NonEmptyString,
  title: fallback(Schema.String, () => ""),
  titleNumber: fallback(Schema.Finite, () => 0),
  rows: optional(Schema.Finite),
  cols: optional(Schema.Finite),
  buffer: optional(Schema.String),
  scrollY: optional(Schema.Finite),
  cursor: optional(Schema.Finite),
})

export type LocalPTY = typeof PTY.Type

export const MAX_TERMINAL_SESSIONS = 20

export function numberFromTitle(title: string) {
  return titleNumber(title, MAX_TERMINAL_SESSIONS)
}

const State = Schema.Struct({
  active: optional(Schema.String),
  all: array(PTY),
})

export const TerminalState = State.pipe(
  Schema.decodeTo(Schema.toType(State), {
    decode: SchemaGetter.transform((value) => {
      const seen = new Set<string>()

      const all = value.all.flatMap((pty) => {
        if (seen.has(pty.id)) return []
        seen.add(pty.id)

        return [{ ...pty, titleNumber: pty.titleNumber > 0 ? pty.titleNumber : (numberFromTitle(pty.title) ?? 0) }]
      })

      return {
        active: value.active && seen.has(value.active) ? value.active : all[0]?.id,
        all,
      }
    }),
    encode: SchemaGetter.transform((value) => value),
  }),
)

import type { JSX } from "solid-js"
import { Show, onCleanup } from "solid-js"
import { createStore } from "solid-js/store"
import { useSortable } from "@dnd-kit/solid/sortable"
import { Tabs } from "@opencode/ui/tabs"
import { Menu } from "@opencode/ui/menu"
import { useExtension } from "../sdk"
import type { TerminalWorkspace } from "./model"
import type { LocalPTY } from "./state"
import { terminalTabLabel } from "./title"
import { focusTerminalById } from "./focus"

export function SortableTerminalTab(props: {
  terminal: LocalPTY
  workspace: TerminalWorkspace
  index: number
  onClose?: () => void
}): JSX.Element {
  const extension = useExtension()

  const sortable = useSortable({
    get id() {
      return props.terminal.id
    },
    get index() {
      return props.index
    },
  })

  const [store, setStore] = createStore({
    editing: false,
    title: props.terminal.title,
    blurEnabled: false,
  })

  let input: HTMLInputElement | undefined
  let blurFrame: number | undefined
  let editRequested = false

  const label = () =>
    terminalTabLabel({ title: props.terminal.title, titleNumber: props.terminal.titleNumber, t: extension.t })

  const close = () => {
    const count = props.workspace.all().length
    void props.workspace.close(props.terminal.id)

    if (count === 1) {
      props.onClose?.()
    }
  }

  const focus = () => {
    if (store.editing) return
    props.workspace.requestFocus(props.terminal.id)
    props.workspace.open(props.terminal.id)

    if (document.activeElement instanceof HTMLElement) document.activeElement.blur()
    focusTerminalById(props.terminal.id)
    const input = document.getElementById(`terminal-wrapper-${props.terminal.id}`)?.querySelector("textarea")

    if (input === document.activeElement) props.workspace.consumeFocus(props.terminal.id)
  }

  const edit = (e?: Event) => {
    if (e) {
      e.stopPropagation()
      e.preventDefault()
    }

    const editing = store.editing

    setStore("blurEnabled", false)
    setStore("title", props.terminal.title)
    setStore("editing", true)

    // The input mounts with `editing`; a rename already in progress keeps its focus.
    if (editing || !input) return

    input.focus()
    input.select()

    if (blurFrame !== undefined) cancelAnimationFrame(blurFrame)

    blurFrame = requestAnimationFrame(() => {
      blurFrame = undefined
      setStore("blurEnabled", true)
    })
  }

  const save = () => {
    if (!store.blurEnabled) return

    const value = store.title.trim()

    if (value && value !== props.terminal.title) {
      props.workspace.update({ id: props.terminal.id, title: value })
    }

    setStore("editing", false)
  }

  const keydown = (e: KeyboardEvent) => {
    if (e.key === "Enter") {
      e.preventDefault()
      save()

      return
    }

    if (e.key === "Escape") {
      e.preventDefault()
      setStore("editing", false)
    }
  }

  onCleanup(() => {
    if (blurFrame === undefined) return
    cancelAnimationFrame(blurFrame)
  })

  return (
    <div ref={sortable.ref} class="h-full flex items-center outline-none focus:outline-none focus-visible:outline-none">
      <Menu.Context>
        <Menu.Context.Trigger class="relative" as="div">
          <Tabs.Trigger
            value={props.terminal.id}
            onMouseDown={(e) => {
              // Switch on mousedown to shave the press-release delay off tab switches.
              if (e.button !== 0) return

              if (store.editing) return
              focus()
            }}
            onClick={(e) => {
              // Mouse navigation already happened on mousedown; detail 0 means keyboard activation.
              if (e.detail > 0) return
              focus()
            }}
            onMiddleClick={close}
            closeButton={<Tabs.CloseButton class="h-5 w-5" onClick={close} aria-label={extension.t("close")} />}
            hideCloseButton
          >
            <span
              class="truncate"
              data-slot="terminal-tab-title"
              onDblClick={edit}
              classList={{ invisible: store.editing }}
            >
              {label()}
            </span>
          </Tabs.Trigger>
          <Show when={store.editing}>
            <div class="absolute inset-0 flex items-center bg-v2-background-bg-layer-01 z-10 pointer-events-auto rounded-[6px] shadow-[inset_0_0_0_0.5px_var(--v2-border-border-muted)] px-2">
              <input
                ref={input}
                type="text"
                value={store.title}
                onInput={(e) => setStore("title", e.currentTarget.value)}
                onBlur={save}
                onKeyDown={keydown}
                onMouseDown={(e) => e.stopPropagation()}
                class="bg-transparent border-none outline-none min-w-0 flex-1 p-0 text-[13px] leading-4 tracking-[-0.04px] text-v2-text-text-base [font-weight:440] [font-variation-settings:'slnt'_0] [font-variant-numeric:tabular-nums]"
              />
            </div>
          </Show>
        </Menu.Context.Trigger>
        <Menu.Context.Portal>
          <Menu.Context.Content
            onCloseAutoFocus={(e) => {
              if (!editRequested) return
              e.preventDefault()
              editRequested = false
              requestAnimationFrame(() => edit())
            }}
          >
            <Menu.Item onSelect={() => (editRequested = true)}>{extension.t("common.rename")}</Menu.Item>
            <Menu.Item onSelect={close}>{extension.t("common.close")}</Menu.Item>
          </Menu.Context.Content>
        </Menu.Context.Portal>
      </Menu.Context>
    </div>
  )
}

export function terminalKeyInput(event: KeyboardEvent) {
  if (!event.metaKey || event.ctrlKey || event.altKey || event.shiftKey) return

  if (event.key.toLowerCase() !== "backspace") return

  return "\x15"
}

import { withAlpha } from "@opencode/ui/theme/color"
import { useTheme } from "@opencode/ui/theme/context"
import { resolveThemeVariant } from "@opencode/ui/theme/resolve"
import { resolveThemeVariantV2 } from "@opencode/ui/theme/v2/resolve"
import type { HexColor, ResolvedV2Theme } from "@opencode/ui/theme/types"
import { showToast } from "@opencode/ui/toast"
import { createPtyClient } from "@opencode/client/solid"
import type { FitAddon, Terminal as Term } from "ghostty-web"
import { Option, Predicate, Schema } from "effect"
import { type ComponentProps, createMemo, onCleanup, onMount, splitProps } from "solid-js"
import { createKeyed, useExtension, type ServerRef } from "../sdk"
import type { TerminalModel } from "./model"
import type { LocalPTY } from "./state"
import { SerializeAddon } from "./serialize"
import { disposeIfDisposable, getHoveredLinkText, setOptionIfSupported } from "./runtime-adapters"
import { terminalKeyInput } from "./terminal-key-event"
import { terminalWriter } from "./writer"

// Serialization on unmount is a synchronous O(rows x cols) walk on the main thread and the
// result is written to localStorage or desktop state for every terminal in the workspace.
// Persisting the most recent 2k scrollback rows keeps restore fidelity for the history users
// actually scroll back through while capping teardown cost and snapshot size; the live
// terminal keeps its full 10k scrollback while mounted.
const persistedScrollbackRows = 2_000

export interface TerminalProps extends ComponentProps<"div"> {
  pty: LocalPTY
  server: ServerRef
  directory: string
  ghostty: TerminalModel["ghostty"]
  autoFocus?: boolean
  onAutoFocus?: () => void
  onSubmit?: () => void
  onCleanup?: (pty: Partial<LocalPTY> & { id: string }) => void
  onConnect?: () => void
  onConnectError?: (error: Error) => void
}

type TerminalColors = {
  background: string
  foreground: string
  cursor: string
  selectionBackground: string
}

const DEFAULT_TERMINAL_COLORS = {
  light: {
    background: "#fcfcfc",
    foreground: "#211e1e",
    cursor: "#211e1e",
    selectionBackground: withAlpha("#211e1e", 0.2),
  },
  dark: {
    background: "#191515",
    foreground: "#d4d4d4",
    cursor: "#d4d4d4",
    selectionBackground: withAlpha("#d4d4d4", 0.25),
  },
} as const satisfies Record<"light" | "dark", TerminalColors>

// The server's binary control frames carry JSON such as the output cursor.
const ControlFrame = Schema.fromJsonString(Schema.Struct({ cursor: Schema.optional(Schema.Number) }))

const decodeControlFrame = Schema.decodeUnknownOption(ControlFrame)

const isHexColor = (value: string): value is HexColor => value.startsWith("#")

const debugTerminal = (...values: unknown[]) => {
  if (!import.meta.env.DEV) return
  console.debug("[terminal]", ...values)
}

const resolveV2Token = (tokens: ResolvedV2Theme, key: string) => {
  let current = tokens[key]

  for (let i = 0; i < 8 && current; i++) {
    const match = /^var\(--([^)]+)\)$/.exec(current.trim())

    if (!match) {
      const hex = current.trim()

      if (/^#[0-9a-fA-F]{8}$/.test(hex)) return hex.slice(0, 7)

      return hex
    }

    current = tokens[match[1]]
  }
}

const useTerminalUiBindings = (input: {
  container: HTMLDivElement
  term: Term
  cleanups: VoidFunction[]
  handlePointerDown: () => void
  handleLinkClick: (event: MouseEvent) => void
}) => {
  const handleCopy = (event: ClipboardEvent) => {
    const selection = input.term.getSelection()

    if (!selection) return

    const clipboard = event.clipboardData

    if (!clipboard) return

    event.preventDefault()
    clipboard.setData("text/plain", selection)
  }

  const handlePaste = (event: ClipboardEvent) => {
    const clipboard = event.clipboardData
    const text = clipboard?.getData("text/plain") ?? clipboard?.getData("text") ?? ""

    if (!text) return

    event.preventDefault()
    event.stopPropagation()
    input.term.paste(text)
  }

  const handleTextareaFocus = () => {
    input.term.options.cursorBlink = true
  }

  const handleTextareaBlur = () => {
    input.term.options.cursorBlink = false
  }

  input.container.addEventListener("copy", handleCopy, true)
  input.cleanups.push(() => input.container.removeEventListener("copy", handleCopy, true))

  input.container.addEventListener("paste", handlePaste, true)
  input.cleanups.push(() => input.container.removeEventListener("paste", handlePaste, true))

  input.container.addEventListener("pointerdown", input.handlePointerDown)
  input.cleanups.push(() => input.container.removeEventListener("pointerdown", input.handlePointerDown))

  input.container.addEventListener("click", input.handleLinkClick, {
    capture: true,
  })
  input.cleanups.push(() =>
    input.container.removeEventListener("click", input.handleLinkClick, {
      capture: true,
    }),
  )

  input.term.textarea?.addEventListener("focus", handleTextareaFocus)
  input.term.textarea?.addEventListener("blur", handleTextareaBlur)
  input.cleanups.push(() => input.term.textarea?.removeEventListener("focus", handleTextareaFocus))
  input.cleanups.push(() => input.term.textarea?.removeEventListener("blur", handleTextareaBlur))
}

const persistTerminal = (input: {
  term: Term | undefined
  addon: SerializeAddon | undefined
  cursor: number
  id: string
  onCleanup?: (pty: Partial<LocalPTY> & { id: string }) => void
}) => {
  if (!input.addon || !input.onCleanup || !input.term) return

  const buffer = (() => {
    try {
      return input.addon.serialize({ scrollback: persistedScrollbackRows })
    } catch {
      debugTerminal("failed to serialize terminal buffer")

      return ""
    }
  })()

  input.onCleanup({
    id: input.id,
    buffer,
    cursor: input.cursor,
    rows: input.term.rows,
    cols: input.term.cols,
    scrollY: input.term.getViewportY(),
  })
}

export const Terminal = (props: TerminalProps) => {
  const extension = useExtension()
  const appearance = extension.appearance
  const keybinds = extension.keybinds
  const system = extension.system
  const desktop = extension.desktop
  const theme = useTheme()
  let container!: HTMLDivElement

  const [local, others] = splitProps(props, [
    "pty",
    "server",
    "directory",
    "ghostty",
    "class",
    "classList",
    "autoFocus",
    "onAutoFocus",
    "onConnect",
    "onConnectError",
  ])

  // Intentional mount-time capture: the imperative xterm/WebSocket lifecycle needs stable values, and each
  // cached surface belongs to one workspace.
  const server = local.server
  const directory = local.directory
  const id = local.pty.id
  const restore = local.pty.buffer ?? ""
  const stored = { cols: local.pty.cols, rows: local.pty.rows }

  const restoreSize =
    restore &&
    stored.cols !== undefined &&
    Number.isSafeInteger(stored.cols) &&
    stored.cols > 0 &&
    stored.rows !== undefined &&
    Number.isSafeInteger(stored.rows) &&
    stored.rows > 0
      ? { cols: stored.cols, rows: stored.rows }
      : undefined

  const scrollY = local.pty.scrollY
  let ws: WebSocket | undefined
  let term: Term | undefined
  let serializeAddon: SerializeAddon
  let fitAddon: FitAddon
  let handleResize: () => void
  let fitFrame: number | undefined
  let sizeTimer: ReturnType<typeof setTimeout> | undefined
  let pendingSize: { cols: number; rows: number } | undefined
  let lastSize: { cols: number; rows: number } | undefined
  let disposed = false
  const cleanups: VoidFunction[] = []

  const start = local.pty.cursor !== undefined && Number.isSafeInteger(local.pty.cursor) ? local.pty.cursor : undefined

  let cursor = start ?? 0
  let seek = start !== undefined ? start : restore ? -1 : 0
  let output: ReturnType<typeof terminalWriter> | undefined
  let drop: VoidFunction | undefined
  let reconn: ReturnType<typeof setTimeout> | undefined
  let tries = 0
  let revealed = false

  const reveal = () => {
    if (revealed) return

    if (!serializeAddon.serializeAsText({ trimWhitespace: true })) return
    revealed = true
    container.style.opacity = "1"
  }

  const cleanup = () => {
    if (!cleanups.length) return
    const fns = cleanups.splice(0).reverse()

    for (const fn of fns) {
      try {
        fn()
      } catch (err) {
        debugTerminal("cleanup failed", err)
      }
    }
  }

  const pushSize = async (cols: number, rows: number) => {
    return server.client.pty
      .update({
        ptyID: id,
        location: { directory },
        size: { cols, rows },
      })
      .catch((err) => {
        debugTerminal("failed to sync terminal size", err)
      })
  }

  const getTerminalColors = (): TerminalColors => {
    const mode = theme.mode() === "dark" ? "dark" : "light"
    const fallback = DEFAULT_TERMINAL_COLORS[mode]
    const currentTheme = theme.themes()[theme.themeId()]

    if (!currentTheme) return fallback
    const variant = mode === "dark" ? currentTheme.dark : currentTheme.light

    if (!variant?.seeds && !variant?.palette) return fallback
    const resolved = resolveThemeVariant(variant, mode === "dark")
    const text = resolved["text-stronger"] ?? fallback.foreground

    const background =
      resolveV2Token(resolveThemeVariantV2(variant, mode === "dark"), "v2-background-bg-base") ?? fallback.background

    const alpha = mode === "dark" ? 0.25 : 0.2
    const base = isHexColor(text) ? text : fallback.foreground
    const selectionBackground = withAlpha(base, alpha)

    return {
      background,
      foreground: text,
      cursor: text,
      selectionBackground,
    }
  }

  const terminalColors = createMemo(getTerminalColors)

  const scheduleFit = () => {
    if (disposed) return

    if (!fitAddon) return

    if (fitFrame !== undefined) return

    fitFrame = requestAnimationFrame(() => {
      fitFrame = undefined

      if (disposed) return
      fitAddon.fit()
    })
  }

  const scheduleSize = (cols: number, rows: number) => {
    if (disposed) return

    if (lastSize?.cols === cols && lastSize?.rows === rows) {
      pendingSize = undefined

      if (sizeTimer !== undefined) clearTimeout(sizeTimer)
      sizeTimer = undefined

      return
    }

    pendingSize = { cols, rows }

    if (!lastSize) {
      lastSize = pendingSize
      void pushSize(cols, rows)

      return
    }

    if (sizeTimer !== undefined) return
    sizeTimer = setTimeout(() => {
      sizeTimer = undefined
      const next = pendingSize

      if (!next) return
      pendingSize = undefined

      if (disposed) return

      if (lastSize?.cols === next.cols && lastSize?.rows === next.rows) return
      lastSize = next
      void pushSize(next.cols, next.rows)
    }, 100)
  }

  // The terminal follows the theme and font; it is created with the current ones, so changes before then wait.
  createKeyed(
    () => ({ colors: terminalColors(), mode: theme.mode() === "dark" ? "dark" : "light" }),
    (current) => {
      if (!term) return

      setOptionIfSupported(term, "theme", current.colors)
      setOptionIfSupported(term, "colorScheme", current.mode)
    },
  )

  createKeyed(
    () => appearance.font("mono"),
    (font) => {
      if (!term) return

      setOptionIfSupported(term, "fontFamily", font)
      scheduleFit()
    },
  )

  // A new zoom refits; the first value finds no fit addon yet.
  createKeyed(
    () => desktop?.zoom(),
    () => scheduleFit(),
  )

  const focusTerminal = () => {
    const t = term

    if (!t) return
    const focus = () => (t.textarea ? t.textarea.focus({ preventScroll: true }) : t.focus())
    focus()
    setTimeout(focus, 0)
  }

  const handlePointerDown = () => {
    const activeElement = document.activeElement

    if (activeElement instanceof HTMLElement && activeElement !== container && !container.contains(activeElement)) {
      activeElement.blur()
    }

    focusTerminal()
  }

  const handleLinkClick = (event: MouseEvent) => {
    if (!event.shiftKey && !event.ctrlKey && !event.metaKey) return

    if (event.altKey) return

    if (event.button !== 0) return

    const t = term

    if (!t) return

    const text = getHoveredLinkText(t)

    if (!text) return

    event.preventDefault()
    event.stopImmediatePropagation()
    system.openExternal(text)
  }

  onMount(() => {
    const run = async () => {
      const loaded = await local.ghostty()

      if (disposed) return

      const mod = loaded.mod
      const g = loaded.ghostty

      const t = new mod.Terminal({
        cursorBlink: true,
        cursorStyle: "bar",
        cols: restoreSize?.cols,
        rows: restoreSize?.rows,
        fontSize: 14,
        fontFamily: appearance.font("mono"),
        allowTransparency: false,
        convertEol: false,
        theme: terminalColors(),
        scrollback: 10_000,
        ghostty: g,
      })

      cleanups.push(() => t.dispose())

      if (disposed) {
        cleanup()

        return
      }

      term = t
      setOptionIfSupported(t, "colorScheme", theme.mode() === "dark" ? "dark" : "light")
      output = terminalWriter((data, done) =>
        t.write(data, () => {
          done?.()
        }),
      )

      t.attachCustomKeyEventHandler((event) => {
        const key = event.key.toLowerCase()

        const input = terminalKeyInput(event)

        if (input) {
          t.input(input, true)

          return true
        }

        if (event.ctrlKey && event.shiftKey && !event.metaKey && key === "c") {
          document.execCommand("copy")

          return true
        }

        // allow for toggle terminal keybinds in parent
        return keybinds.matches("terminal.toggle", event)
      })

      const fit = new mod.FitAddon()
      const serializer = new SerializeAddon()
      cleanups.push(() => disposeIfDisposable(fit))
      t.loadAddon(serializer)
      t.loadAddon(fit)
      fitAddon = fit
      serializeAddon = serializer

      const active = document.activeElement
      t.open(container)
      useTerminalUiBindings({
        container,
        term: t,
        cleanups,
        handlePointerDown,
        handleLinkClick,
      })

      if (local.autoFocus === true) {
        focusTerminal()
        local.onAutoFocus?.()
      }

      if (local.autoFocus !== true) {
        const restoreFocus = () => {
          const current = document.activeElement

          if (current !== container && !container.contains(current)) return
          t.blur()
          t.textarea?.blur()

          if (active instanceof HTMLElement && active.isConnected) active.focus()
        }

        restoreFocus()
        const timer = setTimeout(restoreFocus, 0)
        cleanups.push(() => clearTimeout(timer))
      }

      if (typeof document !== "undefined" && document.fonts) {
        void document.fonts.ready.then(scheduleFit)
      }

      const onResize = t.onResize((size) => {
        scheduleSize(size.cols, size.rows)
      })

      cleanups.push(() => disposeIfDisposable(onResize))

      const onData = t.onData((data) => {
        if (ws?.readyState === WebSocket.OPEN) ws.send(data)
      })

      cleanups.push(() => disposeIfDisposable(onData))

      const onKey = t.onKey((key) => {
        if (key.key == "Enter") {
          props.onSubmit?.()
        }
      })

      cleanups.push(() => disposeIfDisposable(onKey))

      const startResize = () => {
        fit.observeResize()
        handleResize = scheduleFit
        window.addEventListener("resize", handleResize)
        cleanups.push(() => window.removeEventListener("resize", handleResize))
      }

      const write = (data: string) =>
        new Promise<void>((resolve) => {
          if (!output) {
            resolve()

            return
          }

          output.push(data)
          output.flush(resolve)
        })

      if (restore && restoreSize) {
        await write(restore)
        reveal()
        fit.fit()
        scheduleSize(t.cols, t.rows)

        if (scrollY !== undefined) t.scrollToLine(scrollY)
        startResize()
      } else {
        fit.fit()
        scheduleSize(t.cols, t.rows)

        if (restore) {
          await write(restore)
          reveal()

          if (scrollY !== undefined) t.scrollToLine(scrollY)
        }

        startResize()
      }

      const once = { value: false }
      const decoder = new TextDecoder()

      const fail = (err: Error) => {
        if (disposed) return

        if (once.value) return

        once.value = true
        local.onConnectError?.(err)
      }

      const gone = async () => {
        return server.client.pty
          .get({ ptyID: id, location: { directory } })
          .then((result) => result.data.status === "exited")
          .catch((err) => {
            if (Predicate.isTagged(err, "PtyNotFoundError")) return true

            debugTerminal("failed to inspect terminal session", err)

            return false
          })
      }

      const retry = (err: Error) => {
        if (disposed) return

        if (reconn !== undefined) return

        const ms = Math.min(250 * 2 ** Math.min(tries, 4), 4_000)
        reconn = setTimeout(async () => {
          reconn = undefined

          if (disposed) return

          if (await gone()) {
            if (disposed) return
            fail(err)

            return
          }

          if (disposed) return
          tries += 1
          open()
        }, ms)
      }

      const open = async () => {
        if (disposed) return
        drop?.()

        const socket = await createPtyClient(server.client, { url: server.url })
          .connect({
            ptyID: id,
            location: { directory },
            cursor: seek,
          })
          .catch((err) => {
            // A failed connection does not mean the PTY exited; retry checks its status first.
            retry(err)

            return undefined
          })

        if (!socket || once.value) return

        if (disposed) {
          socket.close(1000)

          return
        }

        ws = socket

        const handleOpen = () => {
          if (disposed) return
          tries = 0
          local.onConnect?.()
          scheduleSize(t.cols, t.rows)

          if (t.getMode(2031)) t.write("\x1b[?996n")
        }

        const handleMessage = (event: MessageEvent) => {
          if (disposed) return

          if (event.data instanceof ArrayBuffer) {
            const bytes = new Uint8Array(event.data)

            if (bytes[0] !== 0) return
            const meta = decodeControlFrame(decoder.decode(bytes.subarray(1)))

            if (Option.isNone(meta)) {
              debugTerminal("invalid websocket control frame")

              return
            }

            const next = meta.value.cursor

            if (next !== undefined && Number.isSafeInteger(next) && next >= 0) {
              cursor = next
              seek = next
            }

            return
          }

          // The PTY client receives binary frames as ArrayBuffers, handled above; the rest are text.
          const data = String(event.data)

          if (!data) return
          output?.push(data)

          if (!revealed) output?.flush(reveal)
          cursor += data.length
          seek = cursor
        }

        const handleError = (error: Event) => {
          if (disposed) return
          debugTerminal("websocket error", error)
        }

        const stop = () => {
          socket.removeEventListener("open", handleOpen)
          socket.removeEventListener("message", handleMessage)
          socket.removeEventListener("error", handleError)
          socket.removeEventListener("close", handleClose)

          if (ws === socket) ws = undefined

          if (drop === stop) drop = undefined

          if (socket.readyState !== WebSocket.CLOSED && socket.readyState !== WebSocket.CLOSING) socket.close(1000)
        }

        const handleClose = (event: CloseEvent) => {
          if (ws === socket) ws = undefined

          if (drop === stop) drop = undefined
          socket.removeEventListener("open", handleOpen)
          socket.removeEventListener("message", handleMessage)
          socket.removeEventListener("error", handleError)
          socket.removeEventListener("close", handleClose)

          if (disposed) return

          if (event.code === 1000) return
          retry(new Error(extension.t("connectionLost.abnormalClose", { code: event.code })))
        }

        drop = stop
        socket.addEventListener("open", handleOpen)
        socket.addEventListener("message", handleMessage)
        socket.addEventListener("error", handleError)
        socket.addEventListener("close", handleClose)
      }

      open()
    }

    void run().catch((err) => {
      if (disposed) return
      showToast({
        variant: "error",
        title: extension.t("connectionLost.title"),
        description: err instanceof Error ? err.message : extension.t("connectionLost.description"),
      })
      local.onConnectError?.(err)
    })
  })

  onCleanup(() => {
    disposed = true

    if (fitFrame !== undefined) cancelAnimationFrame(fitFrame)

    if (sizeTimer !== undefined) clearTimeout(sizeTimer)

    if (reconn !== undefined) clearTimeout(reconn)
    drop?.()

    if (ws && ws.readyState !== WebSocket.CLOSED && ws.readyState !== WebSocket.CLOSING) ws.close(1000)

    const finalize = () => {
      persistTerminal({ term, addon: serializeAddon, cursor, id, onCleanup: props.onCleanup })
      cleanup()
    }

    if (!output) {
      finalize()

      return
    }

    output.flush(finalize)
  })

  return (
    <div
      ref={container}
      data-component="terminal"
      dir="ltr"
      data-prevent-autofocus
      tabIndex={-1}
      style={{ "background-color": terminalColors().background, "caret-color": "transparent", opacity: 0 }}
      classList={{
        ...local.classList,
        "select-text": true,
        "size-full px-6 py-3 font-mono relative overflow-hidden": true,
        [local.class ?? ""]: !!local.class,
      }}
      {...others}
    />
  )
}

const template = "Terminal {{number}}"

const numbered = [
  template,
  "محطة طرفية {{number}}",
  "Терминал {{number}}",
  "ターミナル {{number}}",
  "터미널 {{number}}",
  "เทอร์มินัล {{number}}",
  "终端 {{number}}",
  "終端機 {{number}}",
]

export function defaultTitle(number: number) {
  return template.replace("{{number}}", String(number))
}

export function isDefaultTitle(title: string, number: number) {
  return numbered.some((text) => title === text.replace("{{number}}", String(number)))
}

export function titleNumber(title: string, max: number) {
  return Array.from({ length: max }, (_, idx) => idx + 1).find((number) => isDefaultTitle(title, number))
}

export const terminalTabLabel = (input: {
  title?: string
  titleNumber?: number
  t: (key: string, vars?: Record<string, string | number | boolean>) => string
}) => {
  const title = input.title ?? ""
  const number = input.titleNumber ?? 0
  const defaultTitle = Number.isFinite(number) && number > 0 && isDefaultTitle(title, number)

  if (title && !defaultTitle) return title

  if (number > 0) return input.t("title.numbered", { number })

  if (title) return title

  return input.t("tab.title")
}

import { describe, expect, test } from "bun:test"
import { terminalWriter } from "./writer"

describe("terminalWriter", () => {
  test("final flush preserves output queued behind an in-flight write", () => {
    const scheduled: VoidFunction[] = []
    const completions: VoidFunction[] = []
    const events: string[] = []

    const writer = terminalWriter(
      (data, done) => {
        events.push(data)

        if (done) completions.push(done)
      },
      (flush) => scheduled.push(flush),
    )

    writer.push("build started\r\n")
    scheduled.shift()?.()
    writer.push("\x1b[32mPASS\x1b[0m ")
    writer.push("session/history.test.ts\r\n")
    writer.flush(() => events.push("persist and dispose"))
    expect(events).toEqual(["build started\r\n"])
    completions.shift()?.()
    scheduled.shift()?.()
    expect(events).toEqual(["build started\r\n", "\x1b[32mPASS\x1b[0m session/history.test.ts\r\n"])
    completions.shift()?.()
    expect(events).toEqual([
      "build started\r\n",
      "\x1b[32mPASS\x1b[0m session/history.test.ts\r\n",
      "persist and dispose",
    ])
  })
})

export function terminalWriter(
  write: (data: string, done?: VoidFunction) => void,
  schedule: (flush: VoidFunction) => void = queueMicrotask,
) {
  let chunks: string[] | undefined
  let waits: VoidFunction[] | undefined
  let scheduled = false
  let writing = false

  const settle = () => {
    if (scheduled || writing || chunks?.length) return
    const list = waits

    if (!list?.length) return
    waits = undefined

    for (const fn of list) {
      fn()
    }
  }

  const run = () => {
    if (writing) return
    scheduled = false
    const items = chunks

    if (!items?.length) {
      settle()

      return
    }

    chunks = undefined
    writing = true
    write(items.join(""), () => {
      writing = false

      if (chunks?.length) {
        if (scheduled) return
        scheduled = true
        schedule(run)

        return
      }

      settle()
    })
  }

  const push = (data: string) => {
    if (!data) return

    if (chunks) chunks.push(data)
    else chunks = [data]

    if (scheduled || writing) return
    scheduled = true
    schedule(run)
  }

  const flush = (done?: VoidFunction) => {
    if (!scheduled && !writing && !chunks?.length) {
      done?.()

      return
    }

    if (done) {
      if (waits) waits.push(done)
      else waits = [done]
    }

    run()
  }

  return { push, flush }
}

import type { UpdaterState } from "./contract"

/** The one update action the settings row and the titlebar pill offer for a state. */
export function updaterAction(state: UpdaterState | undefined) {
  if (!state) return { label: "action.checkNow" as const }

  switch (state.status) {
    case "checking":
      return { label: "action.checking" as const }
    case "downloading":
      return { label: "action.downloading" as const }
    case "ready":
      return { label: "action.installRestart" as const, run: "install" as const }
    case "download-required":
      return { label: "action.download" as const, run: "install" as const }
    case "installing":
      return { label: "action.installing" as const }
    case "disabled":
      return { label: "action.checkNow" as const }
    default:
      return { label: "action.checkNow" as const, run: "check" as const }
  }
}

import { Button } from "@opencode/ui/button"
import { Dialog, DialogFooter, DialogHeader, DialogTitleGroup } from "@opencode/ui/dialog"
import { Icon } from "@opencode/ui/icon"
import { showToast } from "@opencode/ui/toast"
import type { DialogHandle, IpcClient, SetupContext } from "../sdk"
import type { Updater } from "./contract"
import type definition from "./index"

type Client = IpcClient<typeof Updater.spec>

type Context = SetupContext<typeof definition>

/** Restarts into the staged update. A beta build moving to stable confirms the installer download first. */
export function install(ctx: Context, client: Client) {
  const download = () => client.install().catch((cause: unknown) => requestFailed(ctx, cause))

  const state = client.state()

  if (state?.status !== "download-required") {
    void download()

    return
  }

  ctx.dialogs.open(
    (dialog) => <DialogStableDownload ctx={ctx} dialog={dialog} version={state.version} download={download} />,
    { replace: true },
  )
}

export async function check(ctx: Context, client: Client) {
  const state = await client
    .check({ signal: ctx.signal })
    .catch((cause: unknown) => requestFailed(ctx, cause))

  if (!state || ctx.signal.aborted) return

  if (state.status === "download-required") {
    install(ctx, client)

    return
  }

  if (state.status === "up-to-date") {
    showToast({
      variant: "success",
      icon: () => <Icon name="circle-check" />,
      title: ctx.t("toast.latest.title"),
      description: ctx.t("toast.latest.description", { version: ctx.build.version }),
    })
  }

  if (state.status === "error") {
    showToast({ title: ctx.t("common.requestFailed"), description: state.message })
  }
}

function requestFailed(ctx: Context, cause: unknown) {
  if (ctx.signal.aborted) return

  showToast({
    title: ctx.t("common.requestFailed"),
    description: cause instanceof Error && cause.message ? cause.message : undefined,
  })
}

function DialogStableDownload(props: {
  ctx: Context
  dialog: DialogHandle
  version: string
  download: () => Promise<void>
}) {
  const ctx = props.ctx

  const download = () => {
    props.dialog.close()
    void props.download()
  }

  return (
    <Dialog fit>
      <DialogHeader>
        <DialogTitleGroup
          title={ctx.t("migration.title")}
          description={ctx.t("migration.description", { version: props.version })}
        />
      </DialogHeader>
      <DialogFooter>
        <Button type="button" variant="neutral" onClick={() => props.dialog.close()}>
          {ctx.t("common.cancel")}
        </Button>
        <Button type="button" variant="contrast" autofocus onClick={download}>
          {ctx.t("action.download")}
        </Button>
      </DialogFooter>
    </Dialog>
  )
}

import { Effect, Layer, Logger, References } from "effect"

/** Services for running the updater's effects: every log goes to the desktop log file, debug included. */
export function logContext(
  log: (level: "debug" | "info" | "warn" | "error", message: string, data?: Record<string, unknown>) => void,
) {
  const logger = Logger.make((options) => {
    const entry = Logger.formatStructured.log(options)
    const [message, ...details] = Array.isArray(options.message) ? options.message : [options.message]
    const detail = details.length === 1 && isRecord(details[0]) ? details[0] : details.length ? { details } : {}
    log(LEVELS[options.logLevel] ?? "info", typeof message === "string" ? message : String(message), {
      ...detail,
      ...(Object.keys(entry.annotations).length === 0 ? {} : { annotations: entry.annotations }),
      ...(entry.cause === undefined ? {} : { cause: entry.cause }),
    })
  })

  return Effect.runSync(
    Effect.context<never>().pipe(
      Effect.provide(
        Layer.merge(
          Logger.layer([logger], { mergeWithExisting: false }),
          Layer.succeed(References.MinimumLogLevel, "All"),
        ),
      ),
    ),
  )
}

const LEVELS: Partial<Record<string, "debug" | "info" | "warn" | "error">> = {
  Trace: "debug",
  Debug: "debug",
  Info: "info",
  Warn: "warn",
  Error: "error",
  Fatal: "error",
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

import { afterEach, describe, expect, test } from "bun:test"
import { Effect, Exit, Scope } from "effect"
import type { UpdaterState } from "./contract"
import { make, type Dependencies } from "./machine"

const scopes: Scope.Closeable[] = []

afterEach(async () => {
  await Promise.all(scopes.splice(0).map((scope) => Effect.runPromise(Scope.close(scope, Exit.void))))
})

// Drives the updater the way the app does: start or check, then install like a button click. `calls` records the platform
// operations in order; downloads record whether a differential download was allowed and installs record the staged
// version they would apply. `seen` records every state the updater published.
async function setup(input?: {
  currentVersion?: string
  ready?: { version: string }
  /** The release each platform check finds, in order; the last one repeats. "offline" fails the check. */
  checks?: readonly string[]
  stage?: () => Promise<void>
  install?: () => Promise<void>
  external?: boolean
  open?: () => Promise<void>
}) {
  const calls: string[] = []
  const seen: UpdaterState[] = []
  const store = { ready: input?.ready }
  const checks = input?.checks ?? ["2.0.0"]
  const cursor = { check: 0 }

  const dependencies: Dependencies = {
    currentVersion: input?.currentVersion ?? "1.0.0",
    platform: {
      checkForUpdate: Effect.try({
        try: () => {
          calls.push("check")
          const version = checks[Math.min(cursor.check++, checks.length - 1)] ?? "2.0.0"

          if (version === "offline") throw new Error("offline")

          return input?.external
            ? { mode: "external" as const, version, url: `https://files.test/${version}.dmg` }
            : { mode: "restart" as const, version }
        },
        catch: (error) => error,
      }),
      stageUpdate: (options) =>
        Effect.tryPromise(async () => {
          calls.push(options.differential ? "download" : "download:full")
          await input?.stage?.()
        }),
      installAndRestart: Effect.suspend(() => {
        calls.push(`install:${store.ready?.version}`)

        return Effect.tryPromise({
          try: () => input?.install?.() ?? new Promise<void>(() => {}),
          catch: (error) => error,
        })
      }),
      externalInstall: input?.external
        ? (url) =>
            Effect.tryPromise(async () => {
              calls.push(`external:${url}`)
              await input.open?.()
            })
        : undefined,
    },
    restart: (handoff) =>
      Effect.suspend(() => {
        calls.push("prepare")

        return handoff
      }),
    persistence: {
      get: Effect.sync(() => store.ready),
      set: (value) =>
        Effect.sync(() => {
          store.ready = value
        }),
      clear: Effect.sync(() => {
        store.ready = undefined
      }),
    },
    changed: (state) => seen.push(state),
  }

  const scope = Scope.makeUnsafe()
  scopes.push(scope)
  const updater = await Effect.runPromise(make(dependencies).pipe(Scope.provide(scope)))

  return {
    calls,
    seen,
    getReady: () => store.ready,
    state: updater.state,
    start: () => Effect.runPromise(updater.started),
    check: () => Effect.runPromise(updater.check),
    install: () => Effect.runPromise(updater.install),
    installFork: () => Effect.runFork(updater.install),
  }
}

const tick = () => new Promise((resolve) => setTimeout(resolve, 0))

describe("updater", () => {
  // The launch check, then one silent re-check per further entry in `checks`. `rechecks` lists the states the
  // re-checks published: a ready or offered update never leaves the screen while one runs.
  test.each([
    {
      name: "revalidates a persisted target through the updater cache on launch without a differential download",
      input: { ready: { version: "2.0.0" }, checks: ["2.0.0"] },
      calls: ["check", "download:full"],
      state: { status: "ready", version: "2.0.0" },
      ready: { version: "2.0.0" },
      rechecks: [],
    },
    {
      name: "reports up to date and clears the record once the update is installed",
      input: { currentVersion: "2.0.0", ready: { version: "2.0.0" }, checks: ["2.0.0"] },
      calls: ["check"],
      state: { status: "up-to-date" },
      ready: undefined,
      rechecks: [],
    },
    {
      name: "keeps differential downloads after the persisted target was installed",
      input: { currentVersion: "2.0.0", ready: { version: "2.0.0" }, checks: ["3.0.0"] },
      calls: ["check", "download"],
      state: { status: "ready", version: "3.0.0" },
      ready: { version: "3.0.0" },
      rechecks: [],
    },
    {
      name: "downloads newer releases in full once one is staged",
      input: { checks: ["2.0.0", "3.0.0"] },
      calls: ["check", "download", "check", "download:full"],
      state: { status: "ready", version: "3.0.0" },
      ready: { version: "3.0.0" },
      rechecks: [{ status: "ready", version: "3.0.0" }],
    },
    {
      name: "later checks stay silent while ready and pick up newer versions",
      input: { checks: ["2.0.0", "2.0.0", "3.0.0"] },
      calls: ["check", "download", "check", "check", "download:full"],
      state: { status: "ready", version: "3.0.0" },
      ready: { version: "3.0.0" },
      rechecks: [{ status: "ready", version: "3.0.0" }],
    },
    {
      name: "keeps the staged update installable when a silent re-check fails",
      input: { checks: ["2.0.0", "offline"] },
      calls: ["check", "download", "check"],
      state: { status: "ready", version: "2.0.0" },
      ready: { version: "2.0.0" },
      rechecks: [],
    },
    {
      name: "offers an external installer when its version equals the running beta",
      input: { currentVersion: "2.0.0", external: true, checks: ["2.0.0"] },
      calls: ["check"],
      state: { status: "download-required", version: "2.0.0" },
      ready: undefined,
      rechecks: [],
    },
    {
      name: "keeps an external installer available when a refresh fails",
      input: { external: true, checks: ["2.0.0", "offline"] },
      calls: ["check", "check"],
      state: { status: "download-required", version: "2.0.0" },
      ready: undefined,
      rechecks: [],
    },
  ])("$name", async (row) => {
    const app = await setup(row.input)
    await app.start()
    const launched = app.seen.length

    await row.input.checks.slice(1).reduce<Promise<unknown>>((chain) => chain.then(app.check), Promise.resolve())

    expect(app.calls).toEqual([...row.calls])
    expect(app.state()).toEqual(row.state)
    expect(app.getReady()).toEqual(row.ready)
    expect(app.seen.slice(launched)).toEqual([...row.rechecks])
  })

  // After launch staged 2.0.0, a click shows it installing at once; `then` is a second action right after the click.
  test.each([
    {
      name: "clicking install twice checks once and installs the staged version once",
      checks: ["2.0.0"],
      then: "install",
      calls: ["check", "download", "check", "prepare", "install:2.0.0"],
      state: { status: "installing", version: "2.0.0" },
    },
    {
      name: "ignores checks while an installation is in progress",
      checks: ["2.0.0"],
      then: "check",
      calls: ["check", "download", "check", "prepare", "install:2.0.0"],
      state: { status: "installing", version: "2.0.0" },
    },
    {
      name: "clicking install downloads and installs a newer release",
      checks: ["2.0.0", "3.0.0"],
      then: undefined,
      calls: ["check", "download", "check", "download:full", "prepare", "install:3.0.0"],
      state: { status: "installing", version: "3.0.0" },
    },
    {
      name: "clicking install uses the staged release when the final check fails",
      checks: ["2.0.0", "offline"],
      then: undefined,
      calls: ["check", "download", "check", "prepare", "install:2.0.0"],
      state: { status: "installing", version: "2.0.0" },
    },
  ])("$name", async (row) => {
    const app = await setup({ checks: row.checks })
    await app.start()

    app.installFork()
    expect(app.state()).toEqual({ status: "installing", version: "2.0.0" })

    if (row.then === "install") app.installFork()

    if (row.then === "check") await app.check()
    await tick()

    expect(app.calls).toEqual([...row.calls])
    expect(app.state()).toEqual(row.state)
  })

  test("offers an external installer without staging or preparing to restart", async () => {
    const app = await setup({ external: true })

    await app.start()
    expect(app.calls).toEqual(["check"])
    expect(app.state()).toEqual({ status: "download-required", version: "2.0.0" })
    expect(app.getReady()).toBeUndefined()

    await app.install()
    expect(app.calls).toEqual(["check", "check", "external:https://files.test/2.0.0.dmg"])
    expect(app.state()).toEqual({ status: "download-required", version: "2.0.0" })
  })

  test("opens an external installer once for concurrent clicks", async () => {
    const opened = Promise.withResolvers<void>()
    const app = await setup({ external: true, open: () => opened.promise })
    await app.start()

    const clicks = Promise.all([app.install(), app.install()])
    await tick()

    expect(app.calls).toEqual(["check", "check", "external:https://files.test/2.0.0.dmg"])
    opened.resolve()
    await clicks
    expect(app.state()).toEqual({ status: "download-required", version: "2.0.0" })
  })

  test("concurrent checks share one platform check", async () => {
    const app = await setup()

    await Promise.all([app.check(), app.check(), app.check()])

    expect(app.calls).toEqual(["check", "download"])
  })

  test("install during a silent refresh waits for the download, then installs the newer version", async () => {
    const download = { slow: false, done: Promise.withResolvers<void>() }

    const app = await setup({
      checks: ["2.0.0", "3.0.0"],
      stage: () => (download.slow ? download.done.promise : Promise.resolve()),
    })

    await app.start()

    download.slow = true
    const refresh = app.check()
    await tick()
    app.installFork()
    expect(app.state()).toEqual({ status: "installing", version: "2.0.0" })

    download.done.resolve()
    await refresh
    expect(app.state()).toEqual({ status: "installing", version: "3.0.0" })
    await tick()
    expect(app.calls).toEqual(["check", "download", "check", "download:full", "prepare", "install:3.0.0"])
  })

  test("returns to ready after a failed installation and allows a retry", async () => {
    const attempts = { count: 0 }

    const app = await setup({
      install() {
        attempts.count++

        if (attempts.count === 1) return Promise.reject(new Error("install failed"))

        return new Promise<void>(() => {})
      },
    })

    await app.start()

    await expect(app.install()).rejects.toThrow("install failed")
    expect(app.state()).toEqual({ status: "ready", version: "2.0.0" })

    app.installFork()
    await tick()
    expect(attempts.count).toBe(2)
    expect(app.state()).toEqual({ status: "installing", version: "2.0.0" })
  })
})

import { Deferred, Effect, Exit, Fiber } from "effect"
import type { UpdaterState } from "./contract"

export type UpdateTarget =
  | { readonly mode: "restart"; readonly version: string }
  | { readonly mode: "external"; readonly version: string; readonly url: string }

export type Platform = {
  readonly checkForUpdate: Effect.Effect<UpdateTarget | undefined, unknown>
  readonly stageUpdate: (options: { readonly differential: boolean }) => Effect.Effect<unknown, unknown>
  /** Starts quitAndInstall; succeeds once the app begins quitting for the update. */
  readonly installAndRestart: Effect.Effect<void, unknown>
  readonly externalInstall?: (url: string) => Effect.Effect<void, unknown>
}

export type Dependencies = {
  readonly currentVersion: string
  readonly platform?: Platform
  /** Prepares the app to quit, then runs the handoff; resets the quitting state if the handoff fails. */
  readonly restart: (handoff: Effect.Effect<void, unknown>) => Effect.Effect<void, unknown>
  readonly persistence: {
    readonly get: Effect.Effect<{ version: string } | undefined, unknown>
    readonly set: (value: { version: string }) => Effect.Effect<void, unknown>
    readonly clear: Effect.Effect<void, unknown>
  }
  readonly changed: (state: UpdaterState) => void
}

/** The update state machine. Fibers it forks belong to the caller's scope. */
export const make = Effect.fn("Updater.make")(function* (dependencies: Dependencies) {
  const runFork = Effect.runForkWith(yield* Effect.context())
  let state: UpdaterState = dependencies.platform ? { status: "idle" } : { status: "disabled" }
  let pending: Deferred.Deferred<UpdaterState> | undefined
  let installing: Deferred.Deferred<void, unknown> | undefined

  const transition = (next: UpdaterState) => {
    runFork(Effect.logInfo("updater state changed", { from: state.status, to: next.status }))
    state = next
    dependencies.changed(state)

    return state
  }

  // electron-updater builds NSIS deltas against the installer of the running version but reads the "old" blockmap from
  // the last download. Once a release is staged without installing, the two no longer match and every later delta fails
  // its checksum before falling back to a full download, so remember which release the cache holds and skip the attempt.
  let downloaded: string | undefined
  let target: UpdateTarget | undefined

  const stage = (platform: Platform, version: string) =>
    Effect.gen(function* () {
      if (downloaded)
        yield* Effect.logInfo("skipping differential download, updater cache is stale", {
          current: dependencies.currentVersion,
          staged: downloaded,
          version,
        })
      yield* platform.stageUpdate({ differential: !downloaded })
      downloaded = version
      yield* dependencies.persistence.set({ version })
    })

  const findAndStage = (platform: Platform) =>
    Effect.gen(function* () {
      yield* Effect.sync(() => transition({ status: "checking" }))
      const next = yield* platform.checkForUpdate

      if (!next || (next.mode === "restart" && next.version === dependencies.currentVersion)) {
        yield* dependencies.persistence.clear

        return transition({ status: "up-to-date" })
      }

      target = next

      if (next.mode === "external") {
        yield* dependencies.persistence.clear

        return transition({ status: "download-required", version: next.version })
      }

      transition({ status: "downloading", version: next.version })
      yield* stage(platform, next.version)

      return transition({ status: "ready", version: next.version })
    }).pipe(
      Effect.catch((error) =>
        Effect.sync(() =>
          transition({ status: "error", message: error instanceof Error ? error.message : String(error) }),
        ),
      ),
    )

  const refreshStaged = (platform: Platform, staged: string) =>
    Effect.gen(function* () {
      const next = yield* platform.checkForUpdate

      if (!next) return state
      target = next

      if (next.mode === "external") {
        yield* dependencies.persistence.clear

        return transition({ status: "download-required", version: next.version })
      }

      if (next.version === staged || next.version === dependencies.currentVersion) return state
      yield* stage(platform, next.version)

      return transition({ status: installing ? "installing" : "ready", version: next.version })
    }).pipe(
      Effect.catch((error) =>
        Effect.sync(() => {
          runFork(
            Effect.logWarning("updater refresh failed, keeping staged update", {
              staged,
              message: error instanceof Error ? error.message : String(error),
            }),
          )

          return state
        }),
      ),
    )

  const refreshExternal = (platform: Platform) =>
    Effect.gen(function* () {
      const next = yield* platform.checkForUpdate

      if (!next || next.mode !== "external") return state
      target = next

      if (state.status === "download-required" && state.version === next.version) return state

      return transition({ status: "download-required", version: next.version })
    }).pipe(
      Effect.catch((error) =>
        Effect.sync(() => {
          runFork(
            Effect.logWarning("external updater refresh failed, keeping download available", {
              message: error instanceof Error ? error.message : String(error),
            }),
          )

          return state
        }),
      ),
    )

  const check = Effect.suspend(() => {
    const platform = dependencies.platform

    if (!platform || state.status === "installing") return Effect.succeed(state)

    if (pending) return Deferred.await(pending)
    const deferred = Deferred.makeUnsafe<UpdaterState>()
    pending = deferred

    const update =
      state.status === "ready"
        ? refreshStaged(platform, state.version)
        : state.status === "download-required"
          ? refreshExternal(platform)
          : findAndStage(platform)

    return update.pipe(
      Effect.tap((result) => Deferred.succeed(deferred, result)),
      Effect.ensuring(Effect.sync(() => (pending = undefined))),
    )
  })

  const install = Effect.suspend(() => {
    if (installing) return Deferred.await(installing)
    const platform = dependencies.platform

    if (!platform) return Effect.fail(new Error("Update is not ready to install"))

    if (state.status === "download-required") {
      const staged = state.version
      const deferred = Deferred.makeUnsafe<void, unknown>()
      installing = deferred

      return Effect.gen(function* () {
        yield* pending ? Deferred.await(pending) : refreshExternal(platform)

        if (!target || target.mode !== "external" || !platform.externalInstall)
          return yield* Effect.fail(new Error("External installer is unavailable"))
        transition({ status: "installing", version: target.version })

        return yield* platform.externalInstall(target.url)
      }).pipe(
        Effect.exit,
        Effect.flatMap((exit) =>
          Deferred.done(deferred, exit).pipe(
            Effect.andThen(
              Effect.sync(() => {
                installing = undefined

                if (state.status === "installing")
                  transition({ status: "download-required", version: target?.version ?? staged })
              }),
            ),
            Effect.andThen(Deferred.await(deferred)),
          ),
        ),
      )
    }

    if (state.status !== "ready") return Effect.fail(new Error("Update is not ready to install"))
    const staged = state.version
    transition({ status: "installing", version: staged })
    const deferred = Deferred.makeUnsafe<void, unknown>()
    installing = deferred

    return Effect.gen(function* () {
      yield* pending ? Deferred.await(pending) : refreshStaged(platform, staged)
      yield* dependencies.restart(platform.installAndRestart)

      // The app is quitting into the installer.
      return yield* Effect.never
    }).pipe(
      Effect.exit,
      Effect.flatMap((exit) =>
        Deferred.done(deferred, exit).pipe(
          Effect.andThen(
            Effect.sync(() => {
              installing = undefined

              if (Exit.isFailure(exit) && state.status === "installing") {
                transition({ status: "ready", version: state.version })
              }
            }),
          ),
          Effect.andThen(Deferred.await(deferred)),
        ),
      ),
    )
  })

  const start = Effect.gen(function* () {
    const ready = yield* dependencies.persistence.get

    if (ready?.version === dependencies.currentVersion) yield* dependencies.persistence.clear

    // Any other persisted target was downloaded by an earlier launch and never installed, so its blockmap is cached.
    if (ready && ready.version !== dependencies.currentVersion) downloaded = ready.version
    yield* check
  })

  const starting = yield* start.pipe(Effect.forkScoped)
  yield* Effect.gen(function* () {
    yield* Effect.sleep("10 minutes")
    yield* check
  }).pipe(Effect.forever, Effect.forkScoped)

  return {
    check,
    install,
    state: () => state,
    started: Fiber.join(starting).pipe(Effect.orDie),
  }
})

import { dialog } from "electron"
import { Effect, Exit, Scope } from "effect"
import { MenubarItem, type MainSetup } from "../sdk/main"
import { Updater } from "./contract"
import type definition from "./index"
import { logContext } from "./log"
import { make } from "./machine"

const setup: MainSetup<typeof definition> = async (ctx) => {
  const build = ctx.build
  const lifecycle = ctx.lifecycle
  const enabled = build.packaged && build.channel !== "dev"
  // Holds no resources, so it needs no cleanup.
  const context = logContext(ctx.log.write)
  const runPromise = Effect.runPromiseWith(context)
  const runFork = Effect.runForkWith(context)
  const ready = ctx.stores.ready

  // electron-updater loads only in packaged builds that update, after the first window is up.
  const platform = enabled
    ? await import("./platform").then((module) => runPromise(module.make(build.channel)))
    : undefined

  if (ctx.scope.signal.aborted) return
  const scope = Scope.makeUnsafe()
  ctx.scope.addFinalizer(() => runPromise(Scope.close(scope, Exit.void)))
  const publish = { changed: () => {} }

  const updater = await runPromise(
    make({
      currentVersion: build.version,
      platform,
      // The updater stays active through the handoff, so a failed install returns to a state the user can retry.
      restart: (handoff) =>
        Effect.tryPromise({
          try: () => lifecycle.restart(() => runPromise(handoff), { keep: ctx.scope }),
          catch: (error) => error,
        }),
      persistence: {
        get: Effect.sync(() => ready.value ?? undefined),
        set: (value) => Effect.sync(() => ready.set(value)),
        clear: Effect.sync(() => ready.set(null)),
      },
      changed: () => publish.changed(),
    }).pipe(Scope.provide(scope)),
  )

  const provider = ctx.provide(Updater, {
    state: () => updater.state(),
    check: () => runPromise(updater.check),
    install: () => runPromise(updater.install),
  })

  publish.changed = () => provider.changed()

  const show = Effect.gen(function* () {
    const state = yield* updater.check

    if (state.status === "error") {
      yield* promise(() =>
        dialog.showMessageBox({
          type: "error",
          message: ctx.t("dialog.checkFailed.message"),
          title: ctx.t("dialog.checkFailed.title"),
        }),
      )

      return
    }

    if (state.status === "up-to-date") {
      yield* promise(() =>
        dialog.showMessageBox({
          type: "info",
          message: ctx.t("dialog.upToDate.message"),
          title: ctx.t("dialog.upToDate.title"),
        }),
      )

      return
    }

    if (state.status !== "ready") return

    const response = yield* promise(() =>
      dialog.showMessageBox({
        type: "info",
        message: ctx.t("dialog.ready.message", { version: state.version }),
        title: ctx.t("dialog.ready.title"),
        buttons: [ctx.t("dialog.restart"), ctx.t("dialog.later")],
        defaultId: 0,
        cancelId: 1,
      }),
    )

    if (response.response === 0) yield* updater.install
  })

  ctx.add(
    MenubarItem,
    (): MenubarItem => ({
      menu: "app",
      id: "check",
      label: ctx.t("menu.check"),
      after: "about",
      enabled: () => enabled,
      run(window) {
        // Beta builds check in the focused window, which reports the result in-app.
        if (build.channel !== "beta") return void runFork(show)

        if (window) provider.emit("check", null, window.id)
      },
    }),
  )
}

function promise<A>(evaluate: () => Promise<A>) {
  return Effect.tryPromise(evaluate).pipe(Effect.orDie)
}

export default setup

import { app, autoUpdater } from "electron"
import pkg from "electron-updater"
import { Effect } from "effect"
import type { Platform } from "./machine"

const updateClient = pkg.autoUpdater

const restartTimeout = 10_000

export const make = Effect.fn("Updater.platform")(function* (channel: string) {
  const userAgent = `opencode/${channel === "prod" ? "latest" : channel}/${app.getVersion()}/desktop`
  const runFork = Effect.runForkWith(yield* Effect.context())
  updateClient.logger = {
    info: (...args) => runFork(Effect.logInfo(...args)),
    warn: (...args) => runFork(Effect.logWarning(...args)),
    error: (...args) => runFork(Effect.logError(...args)),
    debug: (...args) => runFork(Effect.logDebug(...args)),
  }
  updateClient.channel = "latest"
  updateClient.requestHeaders = { "User-Agent": userAgent }
  updateClient.allowPrerelease = false
  updateClient.allowDowngrade = true
  updateClient.autoDownload = false
  updateClient.autoInstallOnAppQuit = process.platform === "darwin"
  yield* Effect.logInfo("auto updater configured", {
    channel: updateClient.channel,
    allowPrerelease: updateClient.allowPrerelease,
    allowDowngrade: updateClient.allowDowngrade,
    currentVersion: app.getVersion(),
  })

  return {
    checkForUpdate: Effect.tryPromise({
      try: async () => {
        const result = await updateClient.checkForUpdates()

        if (!result?.isUpdateAvailable) return undefined
        const files = result.updateInfo.files
        // electron-updater picks the installer whose name contains process.arch, which emulation on Windows ARM64
        // reports as x64. downloadUpdate() reads this same list, so keeping only the ARM64 installer moves the install
        // to the native build. macOS needs nothing here: electron-updater already prefers arm64 under Rosetta.
        const native = files.filter((file) => file.url.includes("arm64"))

        if (process.platform === "win32" && app.runningUnderARM64Translation && native.length > 0) {
          files.splice(0, files.length, ...native)
          runFork(
            Effect.logInfo("updating emulated x64 install to native ARM64", { urls: native.map((file) => file.url) }),
          )
        }

        return { mode: "restart", version: result.updateInfo.version } as const
      },
      catch: (error) => error,
    }),
    stageUpdate,
    installAndRestart,
  } satisfies Platform
})

function stageUpdate(options: { readonly differential: boolean }) {
  if (process.platform !== "darwin")
    return Effect.tryPromise({
      try: () => {
        // Only the NSIS cache goes stale: macOS refreshes its cached zip with every download and AppImage reads the
        // blockmap embedded in the running file. An emulated x64 install updates to the ARM64 installer, which cannot
        // be patched from the cached x64 one.
        updateClient.disableDifferentialDownload =
          process.platform === "win32" && (!options.differential || app.runningUnderARM64Translation)

        return updateClient.downloadUpdate()
      },
      catch: (error) => error,
    }).pipe(Effect.asVoid)

  return Effect.callback<void, Error>((resume) => {
    const cleanup = () => {
      autoUpdater.removeListener("update-downloaded", complete)
      updateClient.removeListener("error", fail)
    }

    const complete = () => {
      cleanup()
      resume(Effect.void)
    }

    const fail = (error: Error) => {
      cleanup()
      resume(Effect.fail(error))
    }

    autoUpdater.once("update-downloaded", complete)
    updateClient.once("error", fail)
    void updateClient.downloadUpdate().catch(fail)

    return Effect.sync(cleanup)
  })
}

const installAndRestart = Effect.callback<void, Error>((resume) => {
  const cleanup = () => {
    autoUpdater.removeListener("before-quit-for-update", started)
    updateClient.removeListener("error", fail)
  }

  const started = () => {
    cleanup()
    resume(Effect.void)
  }

  const fail = (error: Error) => {
    cleanup()
    resume(Effect.fail(error))
  }

  autoUpdater.once("before-quit-for-update", started)
  updateClient.once("error", fail)

  try {
    updateClient.quitAndInstall()
  } catch (error) {
    fail(error instanceof Error ? error : new Error(String(error)))
  }

  return Effect.sync(cleanup)
}).pipe(
  Effect.timeoutOrElse({
    duration: restartTimeout,
    orElse: () =>
      Effect.logError("update restart did not start").pipe(
        Effect.andThen(Effect.fail(new Error("Update restart did not start"))),
      ),
  }),
)

import { showToast } from "@opencode/ui/toast"
import { lazy, onCleanup, Suspense } from "solid-js"
import { createKeyed, onIdle, Command, SettingsPage, TitlebarItem, type Setup, type SetupContext } from "../sdk"
import { updaterAction } from "./action"
import type definition from "./index"

const setup: Setup<typeof definition> = (ctx) => {
  whatsNew(ctx)

  if (!ctx.desktop) return
  const updater = ctx.uses.updater

  const state = () => {
    const live = updater()

    return live.status === "active" ? live.value.state() : undefined
  }

  const act = (name: "check" | "install") => {
    const live = updater()

    if (live.status === "active") return void import("./actions").then((module) => module[name](ctx, live.value))

    // Not loaded yet, or gone (disabled, failed, blocked, restarting): nothing can check or install.
    showToast({ title: ctx.t("common.requestFailed") })
  }

  const Section = lazy(() => import("./section"))
  // Settings rows are small; load them while idle so settings opens without a blank row.
  onCleanup(onIdle(() => void Section.preload()))

  ctx.add(TitlebarItem, () => {
    const current = state()
    const installing = current?.status === "installing"
    const ready = current?.status === "ready" || current?.status === "download-required"

    if (!ready && !installing) return

    return {
      id: "update",
      label: ctx.t("status.label"),
      title: ctx.t(updaterAction(current).label),
      busy: installing,
      run: () => act("install"),
    }
  })

  ctx.add(SettingsPage, {
    id: "updates",
    page: "general",
    available: "desktop",
    get title() {
      return ctx.t("section.title")
    },
    get entries() {
      return [
        { id: "settings-release-notes", title: ctx.t("releaseNotes.title") },
        { id: "settings-check-updates", title: ctx.t("check.title") },
      ]
    },
    render: () => (
      <Suspense>
        <Section
          state={state}
          run={() => {
            const run = updaterAction(state()).run

            if (run) act(run)
          }}
        />
      </Suspense>
    ),
  })

  ctx.add(Command, {
    id: "check",
    get title() {
      return ctx.t("menu.check")
    },
    hidden: true,
    run: () => act("check"),
  })

  // Beta builds answer the app menu's Check for Updates in the focused window instead of a native dialog. The
  // listener ends with the generation of the main side that sends it.
  createKeyed(updater, (client) => void client.on("check", () => act("check")))
}

/**
 * What's New after an update, on every platform: the release highlights since the version last seen. The first run
 * and a disabled What's New only remember the version.
 */
function whatsNew(ctx: SetupContext<typeof definition>) {
  const version = ctx.build.version
  const seen = ctx.stores.seen
  const previous = seen.value.version

  if (!version || previous === version) return

  const markSeen = () =>
    seen.update((draft) => {
      draft.version = version
    })

  if (!previous || !ctx.stores.releaseNotes.value.enabled) return markSeen()

  void import("./whats-new").then((module) => {
    if (ctx.signal.aborted) return

    module.showWhatsNew(ctx, { previous, current: version, markSeen })
  })
}

