  })
}

function unavailable(error: string): WslServersState {
  return {
    runtime: { available: false, version: null, error },
    installed: [],
    online: [],
    distroProbes: {},
    opencodeChecks: {},
    pendingRestart: false,
    servers: [],
    job: null,
  }
}

import { execFile } from "node:child_process"
import { copyFile, mkdtemp, readFile, rm } from "node:fs/promises"
import { tmpdir } from "node:os"
import { dirname, join } from "node:path"
import { promisify } from "node:util"

const execFileAsync = promisify(execFile)

/** Development only: builds the Linux CLI from this checkout so WSL runs the same source. */
export async function buildLocalWslCli(input: { version: string; script: string; output: string }) {
  const directory = await mkdtemp(join(tmpdir(), "opencode-wsl-cli-"))
  const root = join(dirname(input.script), "../../..")

  const build = async () => {
    const packageManager = (
      JSON.parse(await readFile(join(root, "package.json"), "utf8")) as { packageManager: string }
    ).packageManager

    const target = `linux-${process.arch}`
    await execFileAsync("bunx", [packageManager, "install", "--os=*", "--cpu=*", "--frozen-lockfile"], {
      cwd: root,
      env: process.env,
      windowsHide: true,
    })
    await execFileAsync(
      "bunx",
      [
        packageManager,
        input.script,
        `--target=opencode-${target}`,
        "--skip-install",
        "--skip-web-ui",
        `--outdir=${directory}`,
      ],
      { cwd: root, env: { ...process.env, OPENCODE_VERSION: input.version }, windowsHide: true },
    )
    await copyFile(join(directory, `cli-${target}`, "bin", "opencode"), input.output)

    return input.output
  }

  return build().finally(() => rm(directory, { recursive: true, force: true }))
}

import { Option, Schema } from "effect"
import type { MainSetup } from "../sdk/main"
import { Wsl } from "./contract"
import type definition from "./index"
import { createWslRuntime } from "./runtime"
import { createWslServersController, wslServerIdForDistro } from "./servers"
import { spawnWslSidecar } from "./sidecar"

// A record is kept when it names a distro; an id that is missing or not a non-empty string is derived from the distro.
const Distro = Schema.Struct({ distro: Schema.NonEmptyString })

const Id = Schema.Struct({ id: Schema.NonEmptyString })

const setup: MainSetup<typeof definition> = (ctx) => {
  const cli = ctx.cli
  const packaged = ctx.build.packaged
  const desktopLog = ctx.log
  const t = ctx.t
  const runtime = createWslRuntime(t)
  // Read leniently like the settings file it migrates from: one bad record must not drop the others.
  const saved = ctx.stores.servers

  // Development builds of the desktop app can build the Linux CLI from this checkout.
  const local =
    packaged || !process.env.OPENCODE_DESKTOP_WSL_CLI_BUILD || !process.env.OPENCODE_DESKTOP_WSL_CLI_OUTPUT
      ? undefined
      : { script: process.env.OPENCODE_DESKTOP_WSL_CLI_BUILD, output: process.env.OPENCODE_DESKTOP_WSL_CLI_OUTPUT }

  const log = <Data extends Readonly<Record<string, unknown>>>(level: "info" | "error", message: string, data: Data) =>
    desktopLog.write(level, `[wsl] ${message}`, data)

  const controller = createWslServersController({
    cli: { version: cli.version },
    runtime,
    t,
    log,
    readServers: () =>
      saved.value.servers.flatMap((value) => {
        const record = Schema.decodeUnknownOption(Distro)(value)

        if (Option.isNone(record)) return []
        const distro = record.value.distro
        const id = Schema.decodeUnknownOption(Id)(value)

        return [{ id: Option.isSome(id) ? id.value.id : wslServerIdForDistro(distro), distro }]
      }),
    writeServers: (servers) => saved.set({ servers }),
    installCli: local
      ? async (distro) => {
          const { buildLocalWslCli } = await import("./local")
          const binary = await buildLocalWslCli({ ...local, version: cli.version })
          await runtime.installCli(distro, { version: cli.version, binary })
        }
      : (distro, build) => runtime.installCli(distro, build),
    spawnSidecar: (distro, signal) => {
      log("info", "spawning wsl sidecar", { distro })

      return spawnWslSidecar(distro, {
        runtime,
        t,
        packaged,
        signal,
        onLine: (line) => log("info", "wsl sidecar", { distro, stream: line.stream, text: line.text }),
      })
    },
  })

  const provider = ctx.provide(Wsl, {
    state: () => controller.getState(),
    probeRuntime: () => controller.probeRuntime(),
    refreshDistros: () => controller.refreshDistros(),
    installWsl: () => controller.installWsl(),
    installDistro: (input) => controller.installDistro(input.name),
    probeAddable: (input) => controller.probeAddable(input.distros),
    installOpencode: (input) => controller.installOpencode(input.name),
    addServer: (input) => controller.addServer(input.distro),
    removeServer: (input) => controller.removeServer(input.id),
    startServer: (input) => controller.startServer(input.id),
  })

  ctx.scope.addFinalizer(controller.subscribe(() => provider.changed()))
  // Finalizers run in reverse: the servers stop before the state stops being published.
  ctx.scope.addFinalizer(() => controller.stopServers())
  controller.startConfiguredServers()
}

export default setup

import fuzzysort from "fuzzysort"
import type { WslInstalledDistro, WslOnlineDistro, WslOpencodeCheck, WslServersState } from "./contract"

export type AddServerText = {
  key: string
  params?: Record<string, string>
}

export type DistroStatusTone = "success" | "warning" | "muted"

export type DistroStatus = {
  label: AddServerText
  tone: DistroStatusTone
}

export type AddServerPrimaryButton = {
  variant: "neutral" | "contrast"
  label: AddServerText
  disabled: boolean
  action: "install-opencode" | "add" | null
  loading: boolean
  width: string | null
}

export type AddServerRuntimeState = "loading" | "pendingRestart" | "checking" | "unavailable" | "ready"

export type AddableProbePlan = {
  key: string
  distros: string[]
}

export type AutoProbePlan = { key: "runtime"; action: "probeRuntime" } | { key: "distros"; action: "refreshDistros" }

export type AddServerProbePlan =
  | { kind: "auto"; key: string; plan: AutoProbePlan }
  | { kind: "addable"; key: string; plan: AddableProbePlan }

export type WslAddServerView = "main" | "catalog"

function isHiddenDistro(name: string) {
  return /^docker-desktop(?:-data)?$/i.test(name)
}

export function wslOpencodeAction(check?: WslOpencodeCheck) {
  if (!check) return

  if (!check.resolvedPath) return "onboarding.installOpencode"

  if (check.matchesDesktop === false) return "onboarding.updateOpencode"
}

export function wslDistroReady(state: WslServersState | undefined, name: string) {
  const installed = state?.installed.find((item) => item.name === name)
  const probe = state?.distroProbes[name]

  if (!probe || !installed) return false

  if (installed.version === 1) return false

  return probe.canExecute && probe.hasBash && probe.hasCurl
}

export function addServerViewModel(input: {
  state: WslServersState | undefined
  view: WslAddServerView
  selectedDistro: string | null
  catalogSearch: string
  catalogTarget: string | null
  adding: boolean
  probingAddable: boolean
}) {
  const state = input.state
  const visibleInstalledDistros = (state?.installed ?? []).filter((item) => !isHiddenDistro(item.name))
  const visibleOnlineDistros = (state?.online ?? []).filter((item) => !isHiddenDistro(item.name))
  const existingServerDistros = new Set((state?.servers ?? []).map((item) => item.config.distro))
  const addableInstalledDistros = visibleInstalledDistros.filter((item) => !existingServerDistros.has(item.name))
  const selectedDistro = addServerSelectedDistro(input.selectedDistro, visibleInstalledDistros, addableInstalledDistros)
  const opencodeCheck = selectedDistro ? (state?.opencodeChecks[selectedDistro] ?? null) : null
  const installableDistros = addServerInstallableDistros(visibleInstalledDistros, visibleOnlineDistros)
  const filteredInstallableDistros = addServerFilteredInstallableDistros(installableDistros, input.catalogSearch)
  const catalogTarget = addServerCatalogTarget(input.catalogTarget, filteredInstallableDistros)
  const busy = !!state?.job || input.adding || input.probingAddable

  return {
    busy,
    runtimeState: addServerRuntimeState(state),
    visibleInstalledDistros,
    visibleOnlineDistros,
    addableInstalledDistros,
    selectedDistro,
    opencodeCheck,
    wslReady: !!state?.runtime?.available && !state?.pendingRestart,
    distroStatuses: Object.fromEntries(
      addableInstalledDistros.flatMap((item) => {
        const status = addServerDistroStatus({ state, name: item.name, probingAddable: input.probingAddable })

        if (!status) return []

        return [[item.name, status] as const]
      }),
    ),
    primaryButton: addServerPrimaryButton({
      state,
      selectedDistro,
      opencodeCheck,
      adding: input.adding,
      probingAddable: input.probingAddable,
    }),
    installableDistros,
    filteredInstallableDistros,
    catalogTarget,
    installingCatalogDistro: state?.job?.kind === "install-distro",
  }
}

function addServerSelectedDistro(
  selected: string | null,
  visibleInstalledDistros: WslInstalledDistro[],
  addableInstalledDistros: WslInstalledDistro[],
) {
  if (selected && addableInstalledDistros.some((item) => item.name === selected && item.version !== 1)) return selected
  const defaultDistro = visibleInstalledDistros.find((item) => item.isDefault)

  if (
    defaultDistro &&
    defaultDistro.version !== 1 &&
    addableInstalledDistros.some((item) => item.name === defaultDistro.name)
  ) {
    return defaultDistro.name
  }

  return addableInstalledDistros.find((item) => item.version !== 1)?.name ?? null
}

function addServerRuntimeState(state: WslServersState | undefined): AddServerRuntimeState {
  if (!state) return "loading"

  if (state.pendingRestart) return "pendingRestart"

  if (!state.runtime) return "checking"

  if (!state.runtime.available) return "unavailable"

  return "ready"
}

function addServerDistroStatus(input: {
  state: WslServersState | undefined
  name: string
  probingAddable: boolean
}): DistroStatus | undefined {
  const installed = input.state?.installed.find((item) => item.name === input.name)

  if (installed?.version === 1) return { label: { key: "onboarding.distroStatus.unsupported" }, tone: "muted" }
  const job = input.state?.job
  const probe = input.state?.distroProbes[input.name]

  if (!probe) {
    if (input.probingAddable || (job?.kind === "probe-addable" && job.distros.includes(input.name))) {
      return checkingStatus()
    }

    return
  }

  if (!probe.canExecute) {
    if (!installed) {
      return { label: { key: "onboarding.distroNotInstalled", params: { distro: input.name } }, tone: "warning" }
    }

    return { label: { key: "onboarding.openDistroOnce", params: { distro: input.name } }, tone: "warning" }
  }

  if (!probe.hasBash || !probe.hasCurl) {
    return { label: { key: "onboarding.distroStatus.missingTools" }, tone: "warning" }
  }

  const check = input.state?.opencodeChecks[input.name]

  if (!check) {
    if (input.probingAddable || (job?.kind === "probe-addable" && job.distros.includes(input.name))) {
      return checkingStatus()
    }

    return
  }

  if (check.matchesDesktop === false) return { label: { key: "onboarding.updateOpencode" }, tone: "warning" }

  if (!check.resolvedPath) return { label: { key: "onboarding.distroStatus.opencodeMissing" }, tone: "warning" }

  if (check.error) return { label: { key: "onboarding.installOpencode" }, tone: "warning" }

  return { label: { key: "onboarding.distroStatus.ready" }, tone: "success" }
}

function checkingStatus(): DistroStatus {
  return { label: { key: "onboarding.distroStatus.checking" }, tone: "muted" }
}

function addServerPrimaryButton(input: {
  state: WslServersState | undefined
  selectedDistro: string | null
  opencodeCheck: WslOpencodeCheck | null
  adding: boolean
  probingAddable: boolean
}): AddServerPrimaryButton {
  const ready = !!input.selectedDistro && wslDistroReady(input.state, input.selectedDistro)
  const probingSelected = input.probingAddable && !addServerSelectedDistroSettled(input.state, input.selectedDistro)

  const probingOpencode =
    probingSelected ||
    (ready &&
      (!input.opencodeCheck ||
        (!!input.selectedDistro &&
          input.state?.job?.kind === "probe-addable" &&
          input.state.job.distros.includes(input.selectedDistro))))

  const installingOpencode =
    input.state?.job?.kind === "install-opencode" && input.state.job.distro === input.selectedDistro

  if (!ready || probingOpencode) {
    return {
      variant: "contrast",
      label: probingSelected ? { key: "onboarding.distroStatus.checking" } : { key: "server.add" },
      disabled: true,
      action: null,
      loading: probingSelected,
      width: null,
    }
  }

  if (!addServerOpencodeReady(input.opencodeCheck)) {
    const update = !!input.opencodeCheck?.resolvedPath && input.opencodeCheck.matchesDesktop === false

    return {
      variant: "neutral",
      label: installingOpencode
        ? { key: "onboarding.updatingOpencode" }
        : update
          ? { key: "onboarding.updateOpencode" }
          : { key: "onboarding.installOpencode" },
      disabled: !!input.state?.job || input.adding,
      action: "install-opencode",
      loading: installingOpencode,
      width: update ? "138px" : "129px",
    }
  }

  return {
    variant: "contrast",
    label: input.adding ? { key: "onboarding.adding" } : { key: "server.add" },
    disabled: input.adding || !!input.state?.job,
    action: "add",
    loading: input.adding,
    width: null,
  }
}

function addServerOpencodeReady(check: WslOpencodeCheck | null) {
  return !!check?.resolvedPath && check.matchesDesktop !== false && !check.error
}

function addServerSelectedDistroSettled(state: WslServersState | undefined, selectedDistro: string | null) {
  if (!selectedDistro) return false
  const installed = state?.installed.find((item) => item.name === selectedDistro)

  if (installed?.version === 1) return false

  if (!state?.distroProbes[selectedDistro]) return false

  if (!wslDistroReady(state, selectedDistro)) return true

  return !!state.opencodeChecks[selectedDistro]
}

function addServerInstallableDistros(installedDistros: WslInstalledDistro[], onlineDistros: WslOnlineDistro[]) {
  const installed = new Set(installedDistros.map((item) => item.name))
  const hasVersionedUbuntu = onlineDistros.some((item) => /^Ubuntu-\d/.test(item.name))

  return onlineDistros
    .filter((item) => !installed.has(item.name))
    .filter((item) => item.name !== "Ubuntu" || !hasVersionedUbuntu)
}

function addServerFilteredInstallableDistros(installableDistros: WslOnlineDistro[], search: string) {
  const query = search.trim()

  if (!query) return installableDistros

  return fuzzysort.go(query, installableDistros, { keys: ["label", "name"] }).map((item) => item.obj)
}

function addServerCatalogTarget(target: string | null, distros: WslOnlineDistro[]) {
  if (target && distros.some((item) => item.name === target)) return target

  return distros[0]?.name ?? null
}

export function addableProbePlan(input: {
  state: WslServersState | undefined
  view: WslAddServerView
  adding: boolean
  selectedDistro: string | null
  addableInstalledDistros: WslInstalledDistro[]
}) {
  const state = input.state

  if (!state?.runtime?.available || state.pendingRestart || input.view !== "main" || input.adding) return

  if (state.job) return

  const ordered = input.selectedDistro
    ? [
        ...input.addableInstalledDistros.filter((item) => item.name === input.selectedDistro),
        ...input.addableInstalledDistros.filter((item) => item.name !== input.selectedDistro),
      ]
    : input.addableInstalledDistros

  const pending = ordered.flatMap((item) => {
    if (item.version === 1) return []

    if (!state.distroProbes[item.name]) return [`distro:${item.name}`]

    if (wslDistroReady(state, item.name) && !state.opencodeChecks[item.name]) return [`opencode:${item.name}`]

    return []
  })

  if (!pending.length) return

  return {
    key: pending.join("|"),
    distros: ordered.filter((item) => item.version !== 1).map((item) => item.name),
  } satisfies AddableProbePlan
}

export function autoProbePlan(input: { state: WslServersState | undefined; busy: boolean }) {
  if (!input.state || input.busy || input.state.pendingRestart) return

  if (!input.state.runtime) return { key: "runtime", action: "probeRuntime" } satisfies AutoProbePlan

  if (!input.state.runtime.available) return

  if (input.state.installed.length || input.state.online.length) return

  return { key: "distros", action: "refreshDistros" } satisfies AutoProbePlan
}

export function addServerProbePlan(input: {
  state: WslServersState | undefined
  view: WslAddServerView
  adding: boolean
  busy: boolean
  selectedDistro: string | null
  addableInstalledDistros: WslInstalledDistro[]
}) {
  const auto = autoProbePlan({ state: input.state, busy: input.busy })

  if (auto) return { kind: "auto", key: `auto:${auto.key}`, plan: auto } satisfies AddServerProbePlan
  const addable = addableProbePlan(input)

  if (addable) return { kind: "addable", key: `addable:${addable.key}`, plan: addable } satisfies AddServerProbePlan
}

export function createProbeFailureGate() {
  let failed: string | undefined

  return {
    accepts(key: string) {
      return key !== failed
    },
    settle(key: string, succeeded: boolean) {
      if (!succeeded) failed = key
    },
    reset() {
      failed = undefined
    },
  }
}

export async function runAddableProbePlan(input: {
  plan: AddableProbePlan
  probeAddable: (distros: string[]) => Promise<void>
}) {
  await input.probeAddable(input.plan.distros)
}

import { useMutation } from "@tanstack/solid-query"
import { createMemo } from "solid-js"
import type { Accessor } from "solid-js"
import { createKeyed, type IpcClient } from "../sdk"
import type { Wsl, WslInstalledDistro, WslServersState } from "./contract"
import {
  addServerProbePlan,
  createProbeFailureGate,
  runAddableProbePlan,
  type AddServerProbePlan,
  type WslAddServerView,
} from "./model"

export function useWslAddServerProbes(input: {
  state: Accessor<WslServersState | undefined>
  api: () => IpcClient<(typeof Wsl)["spec"]>
  view: Accessor<WslAddServerView>
  adding: Accessor<boolean>
  busy: Accessor<boolean>
  selectedDistro: Accessor<string | null>
  addableInstalledDistros: Accessor<WslInstalledDistro[]>
  onError: (cause: unknown) => void
}) {
  const gate = createProbeFailureGate()

  const probe = useMutation(() => ({
    mutationFn: async (command: AddServerProbePlan) => {
      if (command.kind === "addable") {
        await runAddableProbePlan({
          plan: command.plan,
          probeAddable: (distros) => input.api().probeAddable({ distros }),
        })

        return
      }

      if (command.plan.action === "probeRuntime") await input.api().probeRuntime()

      if (command.plan.action === "refreshDistros") await input.api().refreshDistros()
    },
    onError: input.onError,
    onSettled: (_result, error, command) => {
      if (command) gate.settle(command.key, error === null)
    },
  }))

  // The probe main should run next for what the dialog shows: one at a time, and not again after it failed until the
  // user asks to check again.
  const next = createMemo(() => {
    if (probe.isPending) return

    const command = addServerProbePlan({
      state: input.state(),
      view: input.view(),
      adding: input.adding(),
      busy: input.busy(),
      selectedDistro: input.selectedDistro(),
      addableInstalledDistros: input.addableInstalledDistros(),
    })

    return command && gate.accepts(command.key) ? command : undefined
  })

  // Asks main to probe; its answer arrives as a new state.
  createKeyed(next, (command) => probe.mutate(command))

  return {
    probingAddable: () => probe.isPending && probe.variables?.kind === "addable",
    resetProbeFailure: () => gate.reset(),
  }
}

// The part of the SSH extension's remote CLI scripts that WSL uses. Extensions share only contracts, so
// keep the two copies in step.

export function quote(value: string) {
  return `'${value.replaceAll("'", "'\\''")}'`
}

function requireVersion(version: string) {
  if (version !== "local" && !/^[0-9][a-zA-Z0-9.+-]*$/.test(version)) throw new Error(version)

  return version
}

export function discoverScript() {
  return `cli=""
if [ -z "$cli" ] && [ -x "$HOME/.opencode/bin/opencode" ]; then cli="$HOME/.opencode/bin/opencode"; fi
if [ -n "$cli" ]; then printf '%s\\n' "$cli"; fi
`
}

// Adapters supply a quoted shell expression, including remote HOME or wslpath expansion.
export function versionScript(command: string) {
  return `if [ -x ${command} ]; then ${command} --version 2>/dev/null || true; fi\n`
}

export function parseVersion(output: string) {
  const line = output
    .split(/\r?\n/)
    .find((line) => line.trim())
    ?.trim()

  if (!line) return null
  const marker = line.lastIndexOf(" v")
  const version = marker === -1 ? line : line.slice(marker + 2)

  if (!version) throw new Error("V2 CLI did not provide a version")

  return version
}

/** The managed CLI installer also configures the user's shell PATH. */
export function installScript(input: { version: string; binary?: string }) {
  const version = requireVersion(input.version)

  return `set -eu
curl -fsSL https://raw.githubusercontent.com/anomalyco/opencode/v2/install | bash -s -- ${input.binary ? `--binary ${input.binary}` : `--version ${quote(version)}`}
test "$("$HOME/.opencode/bin/opencode" --version | awk '{print $NF}' | sed 's/^v//')" = ${quote(version)}
`
}

import { showToast } from "@opencode/ui/toast"
import { lazy, onCleanup, Suspense } from "solid-js"
import { createStore } from "solid-js/store"
import { MenuItem, onIdle, Server, Style, type ServerEntry, type ServerState, type Setup } from "../sdk"
import type { WslServerItem } from "./contract"
import type definition from "./index"

const loadDialog = () => import("./dialog")

const setup: Setup<typeof definition> = (ctx) => {
  if (ctx.build.platform !== "desktop") return
  const ipc = ctx.uses.wsl
  const dialog = ctx.dialogs
  const Row = lazy(() => import("./row"))
  // Settings rows are small; load them while idle so settings opens without a blank row.
  onCleanup(onIdle(() => void Row.preload()))

  const client = () => {
    const live = ipc()

    return live.status === "active" ? live.value : undefined
  }

  // Without its main side, loading or gone, every action fails as WSL being unavailable, as the add dialog shows.
  const api = () => {
    const live = ipc()

    if (live.status === "active") return live.value
    throw new Error(ctx.t("error.unavailable"))
  }

  const state = () => client()?.state()
  const styled = { added: false }
  // Row actions of one server share a pending state, like one request per row.
  const [requests, setRequests] = createStore<Record<string, number>>({})
  const pending = (key: string) => (requests[key] ?? 0) > 0

  const request = <T,>(key: string, action: () => Promise<T>) => {
    setRequests(key, (count = 0) => count + 1)
    void Promise.try(action)
      .catch((cause: unknown) =>
        showToast({
          variant: "error",
          title: ctx.t("common.requestFailed"),
          description: cause instanceof Error ? cause.message : String(cause),
        }),
      )
      .finally(() => setRequests(key, (count = 1) => count - 1))
  }

  const byKey = (key: string) => state()?.servers.find((item) => `wsl:${item.config.distro}` === key)

  const add = () =>
    void loadDialog().then((module) => {
      if (ctx.signal.aborted) return

      if (!styled.added) ctx.add(Style, module.css)
      styled.added = true
      dialog.open(() => <module.DialogAddWslServer api={client()} state={state()} />)
    })

  const entry = (item: WslServerItem): ServerEntry => {
    const runtime = item.runtime

    return {
      id: item.config.distro,
      name: item.config.distro,
      label: ctx.t("server.label"),
      state: serverState(item),
      // A distro joins the app's servers once its server is up; settings lists it before that.
      listed: runtime.kind === "ready",
      http: runtime.kind === "ready" ? { url: runtime.url, password: runtime.password ?? undefined } : undefined,
      remove: () => Promise.try(() => api().removeServer({ id: item.config.id })),
      row: (row) => (
        <Suspense>
          <Row row={row} distro={item.config.distro} state={state} api={client} pending={pending} request={request} />
        </Suspense>
      ),
    }
  }

  ctx.add(Server, () => {
    const current = state()

    return {
      ready: current !== undefined,
      order: 1,
      entries: (current?.servers ?? []).map(entry),
    }
  })

  ctx.add(MenuItem, (): MenuItem => ({ menu: "server.add", id: "add", title: ctx.t("server.add"), order: 2, run: add }))
  ctx.add(
    MenuItem,
    (): MenuItem => ({
      menu: "server.row",
      id: "retry",
      title: ctx.t("server.retryStart"),
      when: (key) => {
        const kind = byKey(key)?.runtime.kind

        return kind === "failed" || kind === "stopped"
      },
      run: (key) =>
        request(key, async () => {
          const wsl = api()
          const item = byKey(key)

          if (item) await wsl.startServer({ id: item.config.id })
        }),
    }),
  )
}

function serverState(item: WslServerItem): ServerState {
  if (item.runtime.kind === "ready") return "ready"

  if (item.runtime.kind === "starting") return "starting"

  if (item.runtime.kind === "failed") return "failed"

  return "stopped"
}

export default setup

