// Exercise the real wsl.exe argv path: with `--`, WSL routes the command line through the distro's
// default shell, which expands `$cli` to "" before `sh` runs the script (#48640).
const runtime = createWslRuntime((key) => key)

const distro =
  process.platform === "win32" && (await runtime.probeRuntime()).available
    ? (await runtime.listInstalled().catch(() => [])).find((item) => item.isDefault)?.name
    : undefined

// A cold WSL VM takes several seconds to answer.
test.skipIf(!distro)(
  "inline scripts keep their own variable expansion inside WSL",
  async () => {
    const result = await runtime.runWslSh(['cli="from-script"', 'printf "%s\\n" "$cli"'].join("\n"), distro)
    expect(result.code).toBe(0)
    expect(result.stdout.trim()).toBe("from-script")
  },
  30_000,
)

import { spawn } from "node:child_process"
import { existsSync } from "node:fs"
import { join } from "node:path"
import type { MainContext } from "../sdk/main"
import type { WslDistroProbe, WslInstalledDistro, WslOnlineDistro, WslRuntimeCheck } from "./contract"
import { discoverScript, installScript, parseVersion, versionScript } from "./remote-cli"

export type WslCommandLine = {
  stream: "stdout" | "stderr"
  text: string
}

export type WslCommandResult = {
  code: number | null
  signal: NodeJS.Signals | null
  stdout: string
  stderr: string
}

export type RunWslOptions = {
  signal?: AbortSignal
  /**
   * Ceiling on how long we wait for the child process to exit. When the
   * LXSS service or a specific distro wedges (e.g. Ubuntu-24.04 with a
   * pending first-run prompt), `wsl.exe` never returns and any command
   * that doesn't specify a timeout hangs the entire startup flow. Default
   * is 20s - enough for slow cold-starts, short enough to fail fast on
   * a wedge. Callers can override for longer-running jobs.
   */
  timeoutMs?: number
}

export type WslCliBuild = {
  version: string
  binary?: string
}

export type WslRuntime = ReturnType<typeof createWslRuntime>

const DEFAULT_WSL_TIMEOUT_MS = 20_000

const DEFAULT_WSL_INSTALL_TIMEOUT_MS = 15 * 60_000

export function wslArgs(args: string[], distro?: string | null, user?: string | null) {
  // `--` hands the command line to the distro's default shell, which expands `$VAR` and `$(...)`
  // inside our inline scripts before `sh -lc` ever runs them. `--exec` runs the command directly.
  return [...(distro ? ["-d", distro] : []), ...(user ? ["--user", user] : []), "--exec", ...args]
}

export function wslCliInstallCommand(cli: WslCliBuild) {
  return installScript({
    version: cli.version,
    binary: cli.binary ? `"$(wslpath -a ${shellEscape(cli.binary)})"` : undefined,
  })
}

export function summarize(value: string) {
  return value
    .split(/\r?\n/g)
    .map((line) => line.trim())
    .filter(Boolean)
    .join("\n")
}

export function shellEscape(value: string) {
  return `'${value.replace(/'/g, `'"'"'`)}'`
}

/** WSL commands; `t` resolves the extension's copy for errors the user sees. */
export function createWslRuntime(t: MainContext["t"]) {
  const runWsl = (args: string[], opts: RunWslOptions = {}) => runCommand("wsl", args, opts)

  const runPowerShell = (command: string, opts: RunWslOptions = {}) =>
    runCommand(
      "powershell.exe",
      ["-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", command],
      opts,
    )

  const runCommand = (command: string, args: string[], opts: RunWslOptions = {}) =>
    new Promise<WslCommandResult>((resolve, reject) => {
      const child = spawn(command, args, {
        stdio: ["ignore", "pipe", "pipe"],
        windowsHide: true,
        signal: opts.signal,
      })

      // Guard every wsl.exe invocation with a timeout. When the distro or
      // the LXSS service is wedged (Ubuntu first-run state, Windows update
      // pending, etc.) wsl.exe produces no output and never exits; without
      // this the whole sidecar spawn flow stalls the app forever.
      const timeoutMs = opts.timeoutMs ?? DEFAULT_WSL_TIMEOUT_MS

      const timeoutId = setTimeout(() => {
        try {
          child.kill()
        } catch {
          /* ignore */
        }

        reject(new Error(t("error.commandTimeout", { command, args: args.join(" "), timeout: timeoutMs })))
      }, timeoutMs)

      let stdout = ""
      let stderr = ""
      const stdoutDecoder = createOutputDecoder()
      const stderrDecoder = createOutputDecoder()

      const append = (stream: WslCommandLine["stream"], chunk: string) => {
        if (!chunk) return

        if (stream === "stdout") {
          stdout += chunk

          return
        }

        stderr += chunk
      }

      child.stdout.on("data", (chunk: Buffer) => {
        append("stdout", stdoutDecoder.decode(chunk))
      })
      child.stdout.on("end", () => {
        append("stdout", stdoutDecoder.flush())
      })

      child.stderr.on("data", (chunk: Buffer) => {
        append("stderr", stderrDecoder.decode(chunk))
      })
      child.stderr.on("end", () => {
        append("stderr", stderrDecoder.flush())
      })

      child.once("error", (error) => {
        clearTimeout(timeoutId)
        reject(error)
      })
      child.once("close", (code, signal) => {
        clearTimeout(timeoutId)
        resolve({ code, signal, stdout, stderr })
      })
    })

  const runInteractiveCommand = async (
    command: string,
    args: string[],
    opts: RunWslOptions = {},
    defaultTimeoutMs: number,
  ) => {
    // The native addon is only needed for interactive installs; loading it here keeps it out of startup.
    const pty = await import("@lydell/node-pty")

    return new Promise<WslCommandResult>((resolve, reject) => {
      const child = pty.spawn(command, args, {
        name: "xterm-color",
        cols: 80,
        rows: 24,
        cwd: process.cwd(),
        env: process.env,
        useConpty: true,
      })

      let settled = false
      let stdout = ""

      const cleanup = () => {
        clearTimeout(timeoutId)
        abortCleanup?.()
      }

      const timeoutMs = opts.timeoutMs ?? defaultTimeoutMs

      const timeoutId = setTimeout(() => {
        try {
          child.kill()
        } catch {
          /* ignore */
        }

        if (settled) return
        settled = true
        cleanup()
        reject(new Error(t("error.commandTimeout", { command, args: args.join(" "), timeout: timeoutMs })))
      }, timeoutMs)

      const abortHandler = () => {
        try {
          child.kill()
        } catch {
          /* ignore */
        }

        if (settled) return
        settled = true
        cleanup()
        reject(new DOMException("Aborted", "AbortError"))
      }

      const abortCleanup = opts.signal
        ? (() => {
            opts.signal?.addEventListener("abort", abortHandler, { once: true })

            return () => opts.signal?.removeEventListener("abort", abortHandler)
          })()
        : undefined

      child.onData((data: string) => {
        stdout += data
      })
      child.onExit((event: { exitCode: number }) => {
        if (settled) return
        settled = true
        cleanup()
        resolve({ code: event.exitCode, signal: null, stdout, stderr: "" })
      })
    })
  }

  const runWslInDistro = (args: string[], distro?: string | null, opts?: RunWslOptions) =>
    runWsl(wslArgs(args, distro), opts)

  const runWslSh = (script: string, distro?: string | null, opts?: RunWslOptions) =>
    runWslInDistro(["sh", "-lc", script], distro, opts)

  const requireSuccess = (result: WslCommandResult, fallback: string) => {
    if (result.code === 0) return
    throw new Error(summarize(result.stderr || result.stdout) || fallback)
  }

  return {
    runWslSh,

    async probeRuntime(opts?: RunWslOptions): Promise<WslRuntimeCheck> {
      const version = await runWsl(["--version"], opts).catch((error) => ({
        code: 1,
        signal: null,
        stdout: "",
        stderr: error instanceof Error ? error.message : String(error),
      }))

      if (version.code !== 0) {
        return {
          available: false,
          version: null,
          error: summarize(version.stderr || version.stdout) || t("error.unavailable"),
        }
      }

      return {
        available: true,
        version: firstLine(version.stdout),
        error: null,
      }
    },

    async listInstalled(opts?: RunWslOptions) {
      const result = await runWsl(["--list", "--verbose"], opts)

      if (result.code !== 0) {
        throw new Error(summarize(result.stderr || result.stdout) || t("error.listInstalled"))
      }

      return parseInstalledDistros(result.stdout)
    },

    async listOnline(opts?: RunWslOptions) {
      const result = await runWsl(["--list", "--online"], opts)

      if (result.code !== 0) {
        throw new Error(summarize(result.stderr || result.stdout) || t("error.listOnline"))
      }

      return parseOnlineDistros(result.stdout)
    },

    async installRuntimeElevated(opts?: RunWslOptions) {
      const script = [
        "$ErrorActionPreference = 'Stop'",
        "$process = Start-Process -FilePath 'wsl.exe' -Verb RunAs -ArgumentList @('--install','--no-distribution') -Wait -PassThru",
        "if ($null -ne $process.ExitCode) { exit $process.ExitCode }",
      ].join("; ")

      const result = await runPowerShell(script, withTimeout(opts, DEFAULT_WSL_INSTALL_TIMEOUT_MS))
      requireSuccess(result, t("error.installWsl"))
    },

    async installDistro(distro: string, opts?: RunWslOptions) {
      const result = await runInteractiveCommand(
        system32("wsl.exe"),
        ["--install", "-d", distro, "--web-download", "--no-launch"],
        withTimeout(opts, DEFAULT_WSL_INSTALL_TIMEOUT_MS),
        DEFAULT_WSL_INSTALL_TIMEOUT_MS,
      )

      requireSuccess(result, t("error.installDistro", { distro }))
    },

    async installCli(distro: string, cli: WslCliBuild, opts?: RunWslOptions) {
      const result = await runInteractiveCommand(
        system32("wsl.exe"),
        wslArgs(["bash", "-lc", wslCliInstallCommand(cli)], distro),
        withTimeout(opts, DEFAULT_WSL_INSTALL_TIMEOUT_MS),
        DEFAULT_WSL_INSTALL_TIMEOUT_MS,
      )

      requireSuccess(result, t("error.installOpencode"))
    },

    async probeDistro(name: string, opts?: RunWslOptions): Promise<WslDistroProbe> {
      const executable = await runWslInDistro(["/bin/true"], name, opts).catch((error) => ({
        code: 1,
        signal: null,
        stdout: "",
        stderr: error instanceof Error ? error.message : String(error),
      }))

      if (executable.code !== 0) {
        return {
          name,
          canExecute: false,
          hasBash: false,
          hasCurl: false,
          error: summarize(executable.stderr || executable.stdout) || t("error.executeDistro"),
        }
      }

      const [bash, curl] = await Promise.all([
        runWslSh("command -v bash >/dev/null && printf yes || printf no", name, opts),
        runWslSh("command -v curl >/dev/null && printf yes || printf no", name, opts),
      ])

      return {
        name,
        canExecute: true,
        hasBash: bash.code === 0 && summarize(bash.stdout) === "yes",
        hasCurl: curl.code === 0 && summarize(curl.stdout) === "yes",
        error: null,
      }
    },

    async resolveCli(distro: string, opts?: RunWslOptions) {
      return firstLine((await runWslSh(discoverScript(), distro, opts)).stdout)
    },

    async readCliVersion(command: string, distro: string, opts?: RunWslOptions) {
      const result = await runWslSh(versionScript(shellEscape(command)), distro, opts)

      return parseVersion(result.stdout)
    },
  }
}

function createOutputDecoder() {
  let decoder: TextDecoder | undefined

  return {
    decode(chunk: Buffer) {
      decoder ??= new TextDecoder(detectOutputEncoding(chunk))

      return decoder.decode(chunk, { stream: true })
    },
    flush() {
      return decoder?.decode() ?? ""
    },
  }
}

function detectOutputEncoding(chunk: Uint8Array) {
  if (chunk[0] === 0xff && chunk[1] === 0xfe) return "utf-16le"
  const pairs = Math.floor(chunk.length / 2)

  if (pairs < 2) return "utf-8"
  const oddZeroes = Array.from({ length: pairs }).filter((_, index) => chunk[index * 2 + 1] === 0).length
  const evenZeroes = Array.from({ length: pairs }).filter((_, index) => chunk[index * 2] === 0).length

  return oddZeroes >= Math.ceil(pairs / 3) && evenZeroes * 2 <= oddZeroes ? "utf-16le" : "utf-8"
}

function parseInstalledDistros(output: string) {
  return output.split(/\r?\n/g).flatMap((line) => {
    const trimmed = line.trim()

    if (!trimmed) return []
    const match = line.match(/^\s*(\*)?\s*(.*?)\s{2,}\S+\s+(\d+)\s*$/)

    if (!match) return []
    const [, marker, name, version] = match

    if (!name || /^name$/i.test(name)) return []

    return [
      {
        name: name.trim(),
        version: Number.isNaN(Number.parseInt(version, 10)) ? null : Number.parseInt(version, 10),
        isDefault: marker === "*",
      } satisfies WslInstalledDistro,
    ]
  })
}

function parseOnlineDistros(output: string) {
  return output.split(/\r?\n/g).flatMap((line) => {
    const trimmed = line.trim()

    if (!trimmed) return []
    const match = trimmed.match(/^([A-Za-z0-9._-]+)\s{2,}(.+)$/)

    if (!match) return []
    const [, name, label] = match

    if (/^name$/i.test(name)) return []

    return [{ name, label: label.trim() } satisfies WslOnlineDistro]
  })
}

function firstLine(value: string) {
  return (
    value
      .split(/\r?\n/g)
      .map((line) => line.trim())
      .find(Boolean) ?? null
  )
}

function system32(command: string) {
  const root = process.env.SystemRoot ?? process.env.windir

  if (!root) return command
  const resolved = join(root, "System32", command)

  return existsSync(resolved) ? resolved : command
}

function withTimeout(opts: RunWslOptions | undefined, timeoutMs: number): RunWslOptions {
  return {
    ...opts,
    timeoutMs: opts?.timeoutMs ?? timeoutMs,
  }
}

import { expect, test } from "bun:test"
import { spawn, type ChildProcess } from "node:child_process"
import type { WslServerConfig } from "./contract"
import type { WslRuntime } from "./runtime"
import { createWslServersController } from "./servers"

test("teardown during a pending start resolves only after the started process exited", async () => {
  const children: ChildProcess[] = []
  const saved: WslServerConfig[] = []

  const controller = createWslServersController({
    cli: { version: "1.0.0" },
    runtime: {} as WslRuntime,
    t: (key) => key,
    log: () => undefined,
    installCli: async () => undefined,
    readServers: () => saved,
    writeServers: (servers) => saved.splice(0, saved.length, ...servers),
    // A real server process that never turns healthy; an abort ends it and rejects once it exited.
    spawnSidecar: (_distro, signal) => {
      const child = spawn(process.execPath, ["-e", "setInterval(() => {}, 1000)"], { stdio: "ignore" })
      children.push(child)

      return new Promise((_, reject) =>
        signal.addEventListener(
          "abort",
          () => {
            child.once("exit", () => reject(signal.reason))
            child.kill()
          },
          { once: true },
        ),
      )
    },
  })

  await controller.addServer("Debian")

  while (!children.length) await Bun.sleep(1)
  expect(children[0].exitCode).toBeNull()
  await controller.stopServers()
  expect(children[0].exitCode !== null || children[0].signalCode !== null).toBe(true)
})

import type { MainContext } from "../sdk/main"
import type {
  WslDistroProbe,
  WslJob,
  WslOpencodeCheck,
  WslServerConfig,
  WslServerItem,
  WslServerRuntime,
  WslServersState,
} from "./contract"
import type { WslCliBuild, WslRuntime } from "./runtime"

type RunningSidecar = {
  stop: () => Promise<void>
  onExit: (cb: (code: number | null, signal: NodeJS.Signals | null) => void) => void
  url: string
  password: string
}

type WslServersControllerOptions = {
  cli: WslCliBuild
  runtime: WslRuntime
  t: MainContext["t"]
  log: <Data extends Readonly<Record<string, unknown>>>(level: "info" | "error", message: string, data: Data) => void
  /** Rejects once signal aborts, after any process it started has exited. */
  spawnSidecar: (distro: string, signal: AbortSignal) => Promise<RunningSidecar>
  installCli: (distro: string, cli: WslCliBuild) => Promise<void>
  readServers: () => WslServerConfig[]
  writeServers: (servers: WslServerConfig[]) => void
}

export type WslServersController = ReturnType<typeof createWslServersController>

export function wslServerIdForDistro(distro: string) {
  return `wsl:${distro}`
}

export function createWslServersController(options: WslServersControllerOptions) {
  const t = options.t
  const runtime = options.runtime
  let state: WslServersState = initialState()
  const listeners = new Set<() => void>()
  const sidecars = new Map<string, RunningSidecar>()
  // Starts in flight. Stopping one aborts its CLI discovery and health polling and waits until its process exited,
  // so a restart, reload, disable or quit never leaves a sidecar running beside or after it.
  const starts = new Map<string, { readonly abort: AbortController; readonly done: Promise<void> }>()
  let closed = false

  const emit = () => {
    for (const listener of listeners) listener()
  }

  const setState = (next: Partial<WslServersState>) => {
    state = { ...state, ...next }
    emit()
  }

  const updateServer = (id: string, update: (item: WslServerItem) => WslServerItem) => {
    const next = state.servers.map((item) => (item.config.id === id ? update(item) : item))
    setState({ servers: next })
  }

  const refreshFromStore = () => {
    const persisted = options.readServers()

    const items: WslServerItem[] = persisted.map((config) => {
      const existing = state.servers.find((item) => item.config.id === config.id)

      return {
        config,
        runtime: existing?.runtime ?? { kind: "stopped" },
      }
    })

    setState({ servers: items })
  }

  const setRuntime = (id: string, runtime: WslServerRuntime) => {
    updateServer(id, (item) => ({ ...item, runtime }))
  }

  const setCliCheck = (distro: string, check: WslOpencodeCheck) => {
    setState({
      opencodeChecks: {
        ...state.opencodeChecks,
        [distro]: check,
      },
    })
  }

  const inspectCli = async (distro: string) => {
    const resolved = await runtime.resolveCli(distro)
    const version = resolved ? await runtime.readCliVersion(resolved, distro) : null

    return cliCheck(t, distro, resolved, version, options.cli.version)
  }

  const refreshCliCheck = async (distro: string) => {
    const check = await inspectCli(distro)
    setCliCheck(distro, check)

    return check
  }

  const probeAddableDistros = async (distros: readonly string[]) => {
    const unique = [...new Set(distros)]

    const distroProbes = await Promise.all(
      unique.flatMap((distro) =>
        state.distroProbes[distro] ? [] : [runtime.probeDistro(distro).then((probe) => [distro, probe] as const)],
      ),
    )

    if (distroProbes.length) {
      setState({ distroProbes: { ...state.distroProbes, ...Object.fromEntries(distroProbes) } })
    }

    const opencodeChecks = await Promise.all(
      unique.flatMap((distro) =>
        distroProbeReady(state.distroProbes[distro]) && !state.opencodeChecks[distro]
          ? [inspectCli(distro).then((check) => [distro, check] as const)]
          : [],
      ),
    )

    if (opencodeChecks.length) {
      setState({ opencodeChecks: { ...state.opencodeChecks, ...Object.fromEntries(opencodeChecks) } })
    }
  }

  const refreshCliCheckSafely = (id: string, distro: string) => {
    return refreshCliCheck(distro).catch((error) => {
      const message = error instanceof Error ? error.message : String(error)
      options.log("error", "wsl CLI check failed", { id, distro, message })
    })
  }

  const refreshCliChecks = async () => {
    await Promise.all(state.servers.map((item) => refreshCliCheckSafely(item.config.id, item.config.distro)))
  }

  const refreshDistroLists = async () => {
    const [installed, online] = await Promise.all([runtime.listInstalled(), runtime.listOnline()])

    return { installed, online }
  }

  const startServer = async (id: string) => {
    const item = state.servers.find((x) => x.config.id === id)

    if (!item) return
    await stopServer(id)

    if (closed) return
    const abort = new AbortController()
    const startup = { abort, done: launch(id, item.config.distro, abort) }
    starts.set(id, startup)
    await startup.done
  }

  const launch = async (id: string, distro: string, abort: AbortController) => {
    // A later start or a stop replaced this one.
    const current = () => starts.get(id)?.abort === abort
    setRuntime(id, { kind: "starting" })
    options.log("info", "wsl sidecar starting", { id, distro })

    try {
      const sidecar = await options.spawnSidecar(distro, abort.signal)

      if (!current()) {
        await sidecar.stop()

        return
      }

      starts.delete(id)
      sidecars.set(id, sidecar)
      setRuntime(id, {
        kind: "ready",
        url: sidecar.url,
        password: sidecar.password,
      })
      sidecar.onExit((code, signal) => {
        if (sidecars.get(id) !== sidecar) return
        sidecars.delete(id)
        const message = t("error.serverExited", { code: code ?? "null", signal: signal ?? "null" })
        setRuntime(id, { kind: "failed", message })
        options.log("error", "wsl sidecar exited", { id, distro, code, signal })
      })
      void refreshCliCheckSafely(id, distro)
      options.log("info", "wsl sidecar ready", { id, distro, url: sidecar.url })
    } catch (error) {
      if (!current()) return
      starts.delete(id)
      const message = error instanceof Error ? error.message : String(error)
      setRuntime(id, { kind: "failed", message })
      options.log("error", "wsl sidecar failed to start", { id, distro, message })
    }
  }

  const stopServer = async (id: string) => {
    const startup = starts.get(id)
    starts.delete(id)
    startup?.abort.abort()
    await startup?.done
    const existing = sidecars.get(id)
    sidecars.delete(id)
    await existing?.stop()

    if (startup || existing) setRuntime(id, { kind: "stopped" })
  }

  const runJob = async <T>(job: WslJob, runner: () => Promise<T>) => {
    setState({ job })

    try {
      return await runner()
    } finally {
      setState({ job: null })
    }
  }

  return {
    getState() {
      return state
    },
    subscribe(listener: () => void) {
      listeners.add(listener)

      return () => {
        listeners.delete(listener)
      }
    },

    startConfiguredServers() {
      closed = false
      refreshFromStore()
      void refreshCliChecks()
      state.servers.forEach((item) => void startServer(item.config.id))
    },

    async probeRuntime() {
      await runJob({ kind: "runtime", startedAt: Date.now() }, async () => {
        const next = await runtime.probeRuntime()
        setState({
          runtime: next,
          pendingRestart: state.pendingRestart && !next.available ? state.pendingRestart : false,
        })
      })
    },

    async refreshDistros() {
      await runJob({ kind: "distros", startedAt: Date.now() }, async () => {
        setState(await refreshDistroLists())
      })
    },

    async installWsl() {
      await runJob({ kind: "install-wsl", startedAt: Date.now() }, async () => {
        await runtime.installRuntimeElevated()
        const next = await runtime.probeRuntime()
        setState({ runtime: next, pendingRestart: !next.available })
      })
    },

    async installDistro(distro: string) {
      await runJob({ kind: "install-distro", distro, startedAt: Date.now() }, async () => {
        await runtime.installDistro(distro)
        const distros = await refreshDistroLists()
        const probe = await runtime.probeDistro(distro)
        setState({
          ...distros,
          distroProbes: { ...state.distroProbes, [distro]: probe },
        })
      })
    },

    async probeAddable(distros: readonly string[]) {
      if (!distros.length) return
      await runJob({ kind: "probe-addable", distros, startedAt: Date.now() }, () => probeAddableDistros(distros))
    },

    async installOpencode(distro: string) {
      await runJob({ kind: "install-opencode", distro, startedAt: Date.now() }, async () => {
        const id = state.servers.find((item) => item.config.distro === distro)?.config.id

        if (id) await stopServer(id)
        await options.installCli(distro, options.cli)
        requireMatchingCli(t, await refreshCliCheck(distro), options.cli.version)

        if (id) await startServer(id)
      })
    },

    async addServer(distro: string): Promise<WslServerConfig> {
      const id = wslServerIdForDistro(distro)

      if (state.servers.some((item) => item.config.id === id)) {
        throw new Error(t("error.alreadyAdded", { distro }))
      }

      const config: WslServerConfig = {
        id,
        distro,
      }

      options.writeServers([...options.readServers(), config])
      setState({
        servers: [...state.servers, { config, runtime: { kind: "starting" } }],
      })
      void startServer(id)

      return config
    },

    async removeServer(id: string) {
      const distro = state.servers.find((item) => item.config.id === id)?.config.distro
      await stopServer(id)
      const remaining = options.readServers().filter((item) => item.id !== id)
      options.writeServers(remaining)
      const servers = state.servers.filter((item) => item.config.id !== id)

      setState(distro ? { servers, ...removeDistroState(state, distro) } : { servers })
    },

    startServer,

    async stopServers() {
      closed = true
      const pending = [...starts.values()]
      starts.clear()
      pending.forEach((startup) => startup.abort.abort())
      await Promise.all([
        ...pending.map((startup) => startup.done),
        ...[...sidecars.values()].map((sidecar) => sidecar.stop()),
      ])
      sidecars.clear()
    },
  }
}

function initialState(): WslServersState {
  return {
    runtime: null,
    installed: [],
    online: [],
    distroProbes: {},
    opencodeChecks: {},
    pendingRestart: false,
    servers: [],
    job: null,
  }
}

function cliCheck(
  t: MainContext["t"],
  distro: string,
  resolvedPath: string | null,
  version: string | null,
  expectedVersion: string,
): WslOpencodeCheck {
  if (!resolvedPath) {
    return {
      distro,
      resolvedPath: null,
      version: null,
      expectedVersion,
      matchesDesktop: null,
      error: t("error.opencodeMissing"),
    }
  }

  if (!version) {
    return {
      distro,
      resolvedPath,
      version: null,
      expectedVersion,
      matchesDesktop: null,
      error: t("error.opencodeCannotRun"),
    }
  }

  return {
    distro,
    resolvedPath,
    version,
    expectedVersion,
    matchesDesktop: version === expectedVersion,
    error: null,
  }
}

function requireMatchingCli(t: MainContext["t"], check: WslOpencodeCheck, expected: string) {
  if (check.version === expected) return
  throw new Error(
    t("error.updateVersion", {
      distro: check.distro,
      installed: check.version ?? t("error.noVersion"),
      expected,
    }),
  )
}

function removeDistroState(state: WslServersState, distro: string) {
  const distroProbes = { ...state.distroProbes }
  const opencodeChecks = { ...state.opencodeChecks }
  delete distroProbes[distro]
  delete opencodeChecks[distro]

  return { distroProbes, opencodeChecks }
}

function distroProbeReady(probe: WslDistroProbe | undefined) {
  return !!probe?.canExecute && probe.hasBash && probe.hasCurl
}

import { spawn, type ChildProcess } from "node:child_process"
import { randomUUID } from "node:crypto"
import { createServer } from "node:net"
import { Predicate } from "effect"
import type { MainContext } from "../sdk/main"
import { type WslCommandLine, type WslRuntime, shellEscape, wslArgs } from "./runtime"

export type WslSidecar = {
  stop: () => Promise<void>
  onExit: (cb: (code: number | null, signal: NodeJS.Signals | null) => void) => void
  url: string
  password: string
}

export async function spawnWslSidecar(
  distro: string,
  opts: {
    runtime: WslRuntime
    t: MainContext["t"]
    packaged: boolean
    /** Aborts the start: CLI discovery, health polling, and the server process, which has exited when this rejects. */
    signal: AbortSignal
    onLine?: (line: WslCommandLine) => void
    healthTimeoutMs?: number
  },
): Promise<WslSidecar> {
  const t = opts.t
  const opencode = await opts.runtime.resolveCli(distro, { signal: opts.signal })

  if (!opencode) throw new Error(t("error.opencodeNotInstalled", { distro }))

  const port = await allocatePort(t)
  opts.signal.throwIfAborted()
  const password = randomUUID()

  const script = [
    "set -euo pipefail",
    'cd "$HOME" || cd /',
    'PATH=$(awk -v RS=: -v ORS=: \'$0 !~ /^\\/mnt\\//\' <<<"$PATH" | sed "s/:$//")',
    "export PATH",
    "export WSLENV=",
    "export OPENCODE_EXPERIMENTAL_DISABLE_FILEWATCHER=true",
    "export OPENCODE_CLIENT=desktop",
    `export OPENCODE_SERVER_PASSWORD=${shellEscape(password)}`,
    'export XDG_STATE_HOME="$HOME/.local/state"',
    `exec ${shellEscape(opencode)} --log-level ${opts.packaged ? "warn" : "info"} serve --hostname 0.0.0.0 --port ${port}`,
  ].join("\n")

  const child = spawn("wsl", wslArgs(["bash", "-se"], distro), {
    stdio: ["pipe", "pipe", "pipe"],
    windowsHide: true,
  })

  child.stdin.end(script)

  const recentOutput: string[] = []

  const emit = (line: WslCommandLine) => {
    if (!line.text.trim()) return
    recentOutput.push(`[${line.stream}] ${line.text}`)

    if (recentOutput.length > 12) recentOutput.shift()
    opts.onLine?.(line)
  }

  forwardLines(child.stdout, "stdout", emit)
  forwardLines(child.stderr, "stderr", emit)

  const exit = new Promise<never>((_, reject) => {
    child.once("error", reject)
    child.once("exit", (code, signal) =>
      reject(
        new Error(
          t("error.serverExitedBeforeHealthy", {
            code: code ?? "null",
            signal: signal ?? "null",
            output: recentOutput.length ? `\n${recentOutput.join("\n")}` : "",
          }),
        ),
      ),
    )
  })

  const aborted = Promise.withResolvers<never>()
  const abort = () => aborted.reject(opts.signal.reason)
  opts.signal.addEventListener("abort", abort, { once: true })
  const url = `http://127.0.0.1:${port}`
  const startup = new AbortController()
  const health = pollWslHealth(() => checkHealth(url, password), startup.signal)
  const timeoutMs = opts.healthTimeoutMs ?? 30_000
  let timeout: ReturnType<typeof setTimeout>

  const timedOut = new Promise<never>(
    (_, reject) =>
      (timeout = setTimeout(
        () => reject(new Error(t("error.healthTimeout", { distro, timeout: timeoutMs }))),
        timeoutMs,
      )),
  )

  await Promise.race([health, exit, timedOut, aborted.promise])
    .catch(async (error) => {
      await stop(child)
      throw error
    })
    .finally(() => {
      clearTimeout(timeout)
      startup.abort()
      opts.signal.removeEventListener("abort", abort)
    })

  return {
    stop: () => stop(child),
    onExit: (cb) => child.once("exit", cb),
    url,
    password,
  }
}

function stop(child: ChildProcess) {
  // A process that never started or already exited has nothing to wait for.
  if (child.pid === undefined || child.exitCode !== null || child.signalCode !== null) return Promise.resolve()

  return new Promise<void>((resolve) => {
    child.once("exit", () => resolve())
    child.kill()
  })
}

async function checkHealth(url: string, password: string) {
  const auth = Buffer.from(`opencode:${password}`).toString("base64")

  return fetch(new URL("/api/info", url), {
    method: "GET",
    headers: { authorization: `Basic ${auth}` },
    signal: AbortSignal.timeout(3000),
  }).then(
    (res) => res.ok,
    () => false,
  )
}

async function pollWslHealth(check: () => Promise<boolean>, signal: AbortSignal) {
  while (!signal.aborted) {
    if (await check()) return
    await new Promise((resolve) => setTimeout(resolve, 100))
  }
}

function allocatePort(t: MainContext["t"]) {
  return new Promise<number>((resolve, reject) => {
    const server = createServer()
    server.on("error", reject)
    server.listen(0, "127.0.0.1", () => {
      const address = server.address()

      // A TCP server reports its address as an object; a string is a pipe or socket path.
      if (!address || Predicate.isString(address)) {
        server.close()
        reject(new Error(t("error.failedPort")))

        return
      }

      server.close(() => resolve(address.port))
    })
  })
}

function forwardLines(
  stream: NodeJS.ReadableStream,
  source: WslCommandLine["stream"],
  onLine: (line: WslCommandLine) => void,
) {
  let pending = ""
  stream.setEncoding("utf8")
  stream.on("data", (chunk: string) => {
    pending += chunk
    const lines = pending.split(/\r?\n/g)
    pending = lines.pop() ?? ""
    lines.forEach((text) => onLine({ stream: source, text }))
  })
  stream.on("end", () => {
    if (pending) onLine({ stream: source, text: pending })
  })
}

