export const layerWebSocketConstructor = (
  name: string,
  options: SocketRecorderOptions = {},
): Layer.Layer<Socket.WebSocketConstructor, never, Socket.WebSocketConstructor> =>
  provideCassette(
    Layer.effect(
      Socket.WebSocketConstructor,
      Effect.gen(function* () {
