import { describe, expect, test } from "bun:test"
import { renderLatex } from "./render"

describe("root geometry", () => {
  test.each([
    ["x", String.raw`\frac{1}{2}`],
    ["x", String.raw`\sqrt{n}`],
    ["x", "123456789"],
    ["x", String.raw`\frac{123456789}{\frac{n}{m}}`],
    [String.raw`\frac{a}{b}`, "3"],
    [String.raw`\sqrt{\frac{a}{b}}`, String.raw`\sqrt{\frac{n}{m}}`],
    [String.raw`\text{界}`, String.raw`\text{次}`],
    ["", String.raw`\frac{1}{2}`],
  ])("preserves body %s and index %s", (bodySource, indexSource) => {
    const body = renderLatex(bodySource, { color: "red" })
    const index = renderLatex(indexSource, { color: "blue" })
    const root = renderLatex(String.raw`\sqrt[\textcolor{blue}{${indexSource}}]{\textcolor{red}{${bodySource}}}`)
    const bodyX = root.width - body.width
    const bodyY = root.height - body.height

    expect(root.cells).toHaveLength(root.height)
    expect(root.baseline).toBe(bodyY + body.baseline)
    expect(bodyX).toBeGreaterThan(index.width)
    expect(bodyY).toBeGreaterThanOrEqual(index.height)
    for (const row of root.cells) expect(row).toHaveLength(root.width)
    for (const [y, row] of body.cells.entries()) {
      for (const [x, cell] of row.entries()) expect(root.cells[bodyY + y][bodyX + x]).toEqual(cell)
    }
    for (const [y, row] of index.cells.entries()) {
      for (const [x, cell] of row.entries()) expect(root.cells[y][x]).toEqual(cell)
    }
    expect(root.cells.flat().filter((cell) => cell?.style?.color === "red")).toHaveLength(
      body.cells.flat().filter(Boolean).length,
    )
    expect(root.cells.flat().filter((cell) => cell?.style?.color === "blue")).toHaveLength(
      index.cells.flat().filter(Boolean).length,
    )
  })

  test("connects each nested overbar to a full-height stem", () => {
    const root = renderLatex(String.raw`\sqrt{\sqrt{\sqrt{x}}}`)
    expect(root.toString()).toBe([" ╭─────", " │ ╭───", " │ │ ╭─", "╰╯╰╯╰╯x"].join("\n"))
    expect(root.height).toBe(4)
    expect(root.baseline).toBe(3)
    for (const depth of [0, 1, 2]) {
      for (let y = depth; y < root.height; y++) expect(root.cells[y][depth * 2 + 1]).toBeDefined()
    }
    expect(root.cells.flat().filter((cell) => cell?.char === "x")).toHaveLength(1)
  })

  test("extends a fraction root below the math axis without moving its baseline", () => {
    const root = renderLatex(String.raw`\sqrt{\frac{a}{b}}`)
    expect(root.toString()).toBe([" ╭───", " │ a", " │───", "╰╯ b"].join("\n"))
    expect(root.height).toBe(4)
    expect(root.baseline).toBe(2)
    for (let y = 0; y < root.height; y++) expect(root.cells[y][1]).toBeDefined()
    expect(root.cells[root.baseline].map((cell) => cell?.char ?? " ").join("")).toContain("───")
    expect(root.cells[root.height - 1].some((cell) => cell?.char === "b")).toBe(true)
  })

  test.each([
    [String.raw`\sqrt{x}`, [" ╭─", "╰╯x"]],
    [String.raw`\sqrt[3]{x}`, ["3╭─", "╰╯x"]],
    [String.raw`\sqrt[\frac{1}{2}]{x}`, [" 1", "───", " 2 ╭─", "  ╰╯x"]],
    [String.raw`\sqrt[\sqrt{n}]{x}`, [" ╭─", "╰╯n╭─", "  ╰╯x"]],
  ])("uses the same connected construction for %s", (source, expected) => {
    expect(renderLatex(source).toString()).toBe(expected.join("\n"))
  })
})

export type MathVariant = "normal" | "bold" | "italic" | "sans" | "monospace" | "double-struck" | "script" | "fraktur"

export type MathNode =
  | { type: "row"; body: MathNode[] }
  | { type: "symbol"; value: string; role?: SymbolRole }
  | { type: "text"; value: string }
  | { type: "space"; width: number }
  | {
      type: "fraction"
      numerator: MathNode
      denominator: MathNode
      bar: boolean
      numeratorAlign?: "left" | "right"
    }
  | { type: "root"; body: MathNode; index?: MathNode }
  | { type: "scripts"; base: MathNode; superscript?: MathNode; subscript?: MathNode }
  | { type: "delimited"; left: string; body: MathNode; right: string }
  | { type: "matrix"; rows: MathNode[][]; environment: MatrixEnvironment; columns?: string }
  | { type: "brace"; body: MathNode; position: "over" | "under" }
  | { type: "accent"; accent: AccentKind; body: MathNode }
  | { type: "variant"; variant: MathVariant; body: MathNode }
  | { type: "operator"; value: string; limits: boolean }
  | { type: "overunder"; base: MathNode; over?: MathNode; under?: MathNode }
  | { type: "color"; color: string; body: MathNode }

export type SymbolRole = "ordinary" | "binary" | "relation" | "operator" | "punctuation" | "opening" | "closing"

export type MatrixEnvironment =
  | "matrix"
  | "pmatrix"
  | "bmatrix"
  | "Bmatrix"
  | "vmatrix"
  | "Vmatrix"
  | "cases"
  | "aligned"
  | "align"
  | "gathered"
  | "gather"
  | "smallmatrix"
  | "array"

export type AccentKind = "hat" | "widehat" | "bar" | "overline" | "underline" | "vec" | "tilde" | "dot" | "ddot"

export interface ParseOptions {
  macros?: Readonly<Record<string, string>>
  maxExpand?: number
  /**
   * Maximum accepted input length. This guards interactive and AI-generated
   * formulas against accidentally exhausting the terminal process.
   */
  maxSourceLength?: number
  /**
   * Maximum length after user-macro expansion. Defaults to
   * `maxSourceLength`.
   */
  maxExpandedLength?: number
  /** Maximum structural nesting depth. */
  maxDepth?: number
  strict?: boolean
}

export class LatexParseError extends Error {
  public readonly position: number

  constructor(message: string, position: number) {
    super(`${message} at offset ${position}`)
    this.name = "LatexParseError"
    this.position = position
  }
}

export interface MathStyle {
  color?: string
  bold?: boolean
  italic?: boolean
  dim?: boolean
}

export interface MathCell {
  char: string
  style?: MathStyle
}

export interface MathLayout {
  readonly width: number
  readonly height: number
  readonly baseline: number
  readonly cells: ReadonlyArray<ReadonlyArray<MathCell | undefined>>
  toString(): string
}

export interface RenderLatexOptions extends ParseOptions {
  displayMode?: boolean
  compactScripts?: boolean
  color?: string
}

import { describe, expect, test } from "bun:test"
import stringWidth from "string-width"
import { DiagramCanvas, DiagramCanvasSizeError, type DiagramCanvasCell } from "./canvas.js"

describe("DiagramCanvas", () => {
  test("rejects canvases that exceed the rendering budget", () => {
    expect(() => new DiagramCanvas(1_000, 251)).toThrow(DiagramCanvasSizeError)
  })

  test("rejects invalid canvas dimensions", () => {
    for (const [width, height] of [
      [-1, 10],
      [10, -1],
      [1.5, 10],
      [Number.NaN, 10],
      [Number.POSITIVE_INFINITY, 10],
    ]) {
      expect(() => new DiagramCanvas(width, height)).toThrow(DiagramCanvasSizeError)
    }
  })

  test("writes cells and text while clipping out-of-bounds positions", () => {
    const canvas = new DiagramCanvas<"label">(5, 2)

    canvas.setCell(0, 0, "A", "label")
    canvas.setCell(9, 0, "X", "label")
    canvas.setText(2, 1, "hey", "label")

    expect(canvas.toString()).toBe("A\n  hey")
  })

  test("uses measured character widths for text placement", () => {
    const canvas = new DiagramCanvas<"label">(5, 1)

    canvas.setText(0, 0, "a界b", "label")

    expect(canvas.toString()).toBe("a界b")
    expect(stringWidth(canvas.toString())).toBe(4)
  })

  test("does not emit partial wide graphemes", () => {
    const clipped = new DiagramCanvas<"label">(1, 1)
    clipped.setText(0, 0, "界", "label")
    expect(clipped.toString()).toBe("")
  })

  test("keeps custom measurement for ASCII text", () => {
    let measurements = 0
    const canvas = new DiagramCanvas<"label">(5, 1, {
      measure: () => {
        measurements += 1
        return 2
      },
    })

    canvas.setText(0, 0, "ab", "label")

    expect(measurements).toBe(2)
    expect(canvas.getCell(2, 0)?.char).toBe("b")
  })

  test("preserves combined graphemes while placing later text", () => {
    const canvas = new DiagramCanvas<"label">(4, 1)

    canvas.setText(0, 0, "e\u0301x", "label")

    expect(canvas.toString()).toBe("e\u0301x")
    expect(stringWidth(canvas.toString())).toBe(2)
  })

  test("merges cells through the adapter-provided merge function", () => {
    type Style = "line"
    const canvas = new DiagramCanvas<Style>(3, 1, {
      mergeCell: (existing, incoming): DiagramCanvasCell<Style> => ({
        ...incoming,
        char: existing.char === "─" && incoming.char === "│" ? "┼" : incoming.char,
      }),
    })

    canvas.setCell(1, 0, "─", "line")
    canvas.setCell(1, 0, "│", "line")

    expect(canvas.toString()).toBe(" ┼")

    canvas.replaceCell(1, 0, "│", "line")
    expect(canvas.toString()).toBe(" │")
  })

  test("iterates style and metadata runs", () => {
    interface Metadata {
      stateId?: string
    }
    const canvas = new DiagramCanvas<"state", Metadata>(4, 1)
    const runs: string[] = []

    canvas.setText(0, 0, "AB", "state", { stateId: "A" })
    canvas.setText(2, 0, "CD", "state", { stateId: "B" })
    canvas.forEachRun(
      (run) => runs.push(`${run.text}:${run.style}:${run.cell.stateId}`),
      () => runs.push("newline"),
      { key: (cell) => [cell.style, cell.stateId] },
    )

    expect(runs).toEqual(["AB:state:A", "CD:state:B"])
  })

  test("retains styled trailing padding in render runs without changing plain text", () => {
    const canvas = new DiagramCanvas<"label">(8, 1)
    const runs: string[] = []
    canvas.setText(1, 0, " start ", "label")

    canvas.forEachRun(
      (run) => runs.push(run.text),
      () => {},
    )

    expect(canvas.toString()).toBe("  start")
    expect(runs).toEqual([" ", " start "])
  })

  test("can trim bottom whitespace for renderers with dynamic height", () => {
    const canvas = new DiagramCanvas<"label">(3, 3)
    const runs: string[] = []
    canvas.setText(0, 0, "top", "label")

    expect(canvas.toString()).toBe("top\n\n")
    expect(canvas.toString({ trimBottom: true })).toBe("top")
    expect(canvas.getTextSize()).toEqual({ width: 3, height: 3 })
    expect(canvas.getTextSize({ trimBottom: true })).toEqual({ width: 3, height: 1 })

    canvas.forEachRun(
      (run) => runs.push(run.text),
      () => runs.push("newline"),
      { trimBottom: true },
    )
    expect(runs).toEqual(["top"])
  })

  test("can trim unused leading whitespace reserved by layout", () => {
    const canvas = new DiagramCanvas<"label">(3, 3)
    canvas.setText(0, 2, "end", "label")

    expect(canvas.toString({ trimTop: true })).toBe("end")
    expect(canvas.getTextSize({ trimTop: true })).toEqual({ width: 3, height: 1 })
  })

  test("measures trim-aware text height without measuring row width", () => {
    let measurements = 0
    const canvas = new DiagramCanvas(8, 5, {
      measure: (text) => {
        measurements += 1
        return stringWidth(text)
      },
    })
    canvas.setText(1, 2, "middle")
    measurements = 0

    expect(canvas.getTextHeight({ trimTop: true, trimBottom: true })).toBe(1)
    expect(measurements).toBe(0)
  })

  test("updates tracked row extents when the last visible cell is cleared", () => {
    const canvas = new DiagramCanvas(8, 1)
    canvas.setText(1, 0, "abc")
    canvas.setCell(3, 0, " ")

    expect(canvas.toString()).toBe(" ab")
    expect(canvas.getTextSize()).toEqual({ width: 3, height: 1 })
  })

  test("keeps tracked extents equivalent to scanning after mixed writes", () => {
    const canvas = new DiagramCanvas<"line">(20, 10, {
      mergeCell: (_existing, incoming) => incoming,
    })
    let seed = 42
    const next = (limit: number) => {
      seed = (seed * 1_664_525 + 1_013_904_223) >>> 0
      return seed % limit
    }

    for (let index = 0; index < 200; index++) {
      const x = next(canvas.width)
      const y = next(canvas.height)
      const char = [" ", "x", "─"][next(3)]!
      if (next(2) === 0) canvas.setCell(x, y, char, "line")
      else canvas.replaceCell(x, y, char, "line")
    }

    const scanned = canvas.rows.map((row) => {
      let end = row.length
      while (end > 0 && row[end - 1]?.char === " ") end -= 1
      return row
        .slice(0, end)
        .map((cell) => cell.char)
        .join("")
    })
    const first = scanned.findIndex((line) => line.length > 0)
    const last = scanned.findLastIndex((line) => line.length > 0)

    expect(canvas.toString()).toBe(scanned.join("\n"))
    expect(canvas.getTextHeight({ trimTop: true, trimBottom: true })).toBe(first < 0 ? 0 : last - first + 1)
  })
})

import stringWidth from "string-width"
import { diagramTextGraphemes } from "./text.js"

export type DiagramCanvasCell<Style extends string, Metadata extends object = object> = {
  char: string
  style?: Style
} & Partial<Metadata>

export interface DiagramCanvasRun<Style extends string, Metadata extends object = object> {
  text: string
  style: Style | undefined
  cell: DiagramCanvasCell<Style, Metadata>
}

export interface DiagramCanvasOptions<Style extends string, Metadata extends object = object> {
  measure?: (text: string) => number
  mergeCell?: (
    existing: DiagramCanvasCell<Style, Metadata>,
    incoming: DiagramCanvasCell<Style, Metadata>,
  ) => DiagramCanvasCell<Style, Metadata>
}

export interface DiagramCanvasTextOptions {
  trimTop?: boolean
  trimBottom?: boolean
}

export interface DiagramCanvasTextSize {
  width: number
  height: number
}

export type DiagramCanvasTextMetadata<Metadata extends object> =
  | Partial<Metadata>
  | ((x: number, y: number) => Partial<Metadata>)

export interface DiagramCanvasRunOptions<Style extends string, Metadata extends object = object> {
  key?: (cell: DiagramCanvasCell<Style, Metadata>) => readonly unknown[]
  trimTop?: boolean
  trimBottom?: boolean
}

const MAX_DIAGRAM_CELLS = 250_000

export class DiagramCanvasSizeError extends Error {
  constructor(
    readonly width: number,
    readonly height: number,
  ) {
    const invalid = !Number.isSafeInteger(width) || !Number.isSafeInteger(height) || width < 0 || height < 0
    super(
      invalid
        ? `Diagram canvas dimensions must be non-negative safe integers, received ${width}x${height}`
        : `Diagram canvas ${width}x${height} exceeds the ${MAX_DIAGRAM_CELLS.toLocaleString()} cell limit`,
    )
    this.name = "DiagramCanvasSizeError"
  }
}

function createEmptyCell<Style extends string, Metadata extends object>(): DiagramCanvasCell<Style, Metadata> {
  return { char: " " } as DiagramCanvasCell<Style, Metadata>
}

function sameKey(left: readonly unknown[] | undefined, right: readonly unknown[]): boolean {
  return Boolean(left && left.length === right.length && left.every((value, index) => Object.is(value, right[index])))
}

export class DiagramCanvas<Style extends string, Metadata extends object = object> {
  private readonly cells: Array<Array<DiagramCanvasCell<Style, Metadata>>>
  private readonly measure: (text: string) => number
  private readonly mergeCell?: DiagramCanvasOptions<Style, Metadata>["mergeCell"]
  private readonly rowEnds: Uint32Array

  constructor(
    readonly width: number,
    readonly height: number,
    options: DiagramCanvasOptions<Style, Metadata> = {},
  ) {
    if (!Number.isSafeInteger(width) || !Number.isSafeInteger(height) || width < 0 || height < 0) {
      throw new DiagramCanvasSizeError(width, height)
    }
    if (width * height > MAX_DIAGRAM_CELLS) throw new DiagramCanvasSizeError(width, height)
    this.measure = options.measure ?? stringWidth
    this.mergeCell = options.mergeCell
    this.cells = Array.from({ length: height }, () => Array.from({ length: width }, () => createEmptyCell()))
    this.rowEnds = new Uint32Array(height)
  }

  get rows(): ReadonlyArray<ReadonlyArray<Readonly<DiagramCanvasCell<Style, Metadata>>>> {
    return this.cells
  }

  private rowText(row: Array<DiagramCanvasCell<Style, Metadata>>, rowEnd: number): string {
    return row
      .slice(0, rowEnd)
      .map((cell) => cell.char)
      .join("")
  }

  private textRowRange(trimTop: boolean, trimBottom: boolean): { start: number; end: number } {
    let start = 0
    let end = this.cells.length
    if (trimTop) while (start < end && this.rowEnds[start] === 0) start += 1
    if (trimBottom) while (end > start && this.rowEnds[end - 1] === 0) end -= 1
    return { start, end }
  }

  setCell(x: number, y: number, char: string, style?: Style, metadata?: Partial<Metadata>): void {
    this.writeCell(x, y, char, style, metadata, true)
  }

  replaceCell(x: number, y: number, char: string, style?: Style, metadata?: Partial<Metadata>): void {
    this.writeCell(x, y, char, style, metadata, false)
  }

  private writeCell(
    x: number,
    y: number,
    char: string,
    style: Style | undefined,
    metadata: Partial<Metadata> | undefined,
    merge: boolean,
  ): void {
    if (y < 0 || y >= this.cells.length || x < 0 || x >= this.cells[y]!.length) return
    const incoming = { char, style, ...metadata } as DiagramCanvasCell<Style, Metadata>
    const cell = merge ? (this.mergeCell?.(this.cells[y]![x]!, incoming) ?? incoming) : incoming
    this.cells[y]![x] = cell
    if (cell.char !== " ") {
      this.rowEnds[y] = Math.max(this.rowEnds[y]!, x + 1)
    } else if (this.rowEnds[y] === x + 1) {
      let end = x
      while (end > 0 && this.cells[y]![end - 1]?.char === " ") end -= 1
      this.rowEnds[y] = end
    }
  }

  getCell(x: number, y: number): Readonly<DiagramCanvasCell<Style, Metadata>> | undefined {
    return this.cells[y]?.[x]
  }

  setText(x: number, y: number, text: string, style?: Style, metadata?: DiagramCanvasTextMetadata<Metadata>): void {
    const metadataAt = (cellX: number) => (typeof metadata === "function" ? metadata(cellX, y) : metadata)
    if (this.measure === stringWidth && /^[\x20-\x7e]*$/.test(text)) {
      for (let index = 0; index < text.length; index++) {
        this.setCell(x + index, y, text[index]!, style, metadataAt(x + index))
      }
      return
    }

    let offset = 0
    for (const grapheme of diagramTextGraphemes(text)) {
      const width = Math.max(1, this.measure(grapheme))
      if (x + offset < 0 || x + offset + width > this.width) {
        offset += width
        continue
      }
      this.setCell(x + offset, y, grapheme, style, metadataAt(x + offset))
      for (let continuation = 1; continuation < width; continuation++) {
        this.setCell(x + offset + continuation, y, "", style, metadataAt(x + offset + continuation))
      }
      offset += width
    }
  }

  toString(options: DiagramCanvasTextOptions = {}): string {
    const lines: string[] = []
    const rows = this.textRowRange(options.trimTop ?? false, options.trimBottom ?? false)
    for (let rowIndex = rows.start; rowIndex < rows.end; rowIndex++) {
      lines.push(this.rowText(this.cells[rowIndex]!, this.rowEnds[rowIndex]!))
    }
    return lines.join("\n")
  }

  getTextSize(options: DiagramCanvasTextOptions = {}): DiagramCanvasTextSize {
    const rows = this.textRowRange(options.trimTop ?? false, options.trimBottom ?? false)
    let width = 0
    for (let rowIndex = rows.start; rowIndex < rows.end; rowIndex++) {
      const row = this.cells[rowIndex]!
      const rowEnd = this.rowEnds[rowIndex]!
      if (rowEnd > 0) width = Math.max(width, this.measure(this.rowText(row, rowEnd)))
    }
    return { width, height: rows.end - rows.start }
  }

  getTextHeight(options: DiagramCanvasTextOptions = {}): number {
    const rows = this.textRowRange(options.trimTop ?? false, options.trimBottom ?? false)
    return rows.end - rows.start
  }

  forEachRun(
    onRun: (run: DiagramCanvasRun<Style, Metadata>) => void,
    onLineEnd: () => void,
    options: DiagramCanvasRunOptions<Style, Metadata> = {},
  ): void {
    const key = options.key
    const rows = this.textRowRange(options.trimTop ?? false, options.trimBottom ?? false)

    for (let rowIndex = rows.start; rowIndex < rows.end; rowIndex++) {
      const row = this.cells[rowIndex]!
      let rowEnd = this.rowEnds[rowIndex]!
      while (rowEnd < row.length && row[rowEnd]?.style !== undefined) rowEnd += 1

      let currentCell: DiagramCanvasCell<Style, Metadata> | undefined
      let currentKey: readonly unknown[] | undefined
      let currentText = ""
      const flush = () => {
        if (!currentText || !currentCell) return
        onRun({ text: currentText, style: currentCell.style, cell: currentCell })
        currentText = ""
      }

      for (let x = 0; x < rowEnd; x++) {
        const cell = row[x]!
        const nextKey = key?.(cell)
        const sameRun = currentCell && (key ? sameKey(currentKey, nextKey!) : currentCell.style === cell.style)
        if (!sameRun) {
          flush()
          currentCell = cell
          currentKey = nextKey
        }
        currentText += cell.char
      }

      flush()
      if (rowIndex < rows.end - 1) onLineEnd()
    }
  }
}

import { describe, expect, test } from "bun:test"
import { RGBA } from "@opentui/core"
import { blendColor, createColorRampTheme, numberedStyleKeys, rgba } from "./style.js"

describe("diagram style helpers", () => {
  test("converts rgb tuples and blends optional RGBA values", () => {
    const black = RGBA.fromInts(0, 0, 0, 255)
    const white = RGBA.fromInts(10, 20, 30, 255)

    expect(rgba([1, 2, 3]).equals(RGBA.fromInts(1, 2, 3, 255))).toBe(true)
    expect(blendColor(black, white, 0.5).equals(RGBA.fromInts(5, 10, 15, 255))).toBe(true)
    expect(blendColor(undefined, white, 0.5)?.equals(white)).toBe(true)
    expect(blendColor(undefined, undefined, 0.5)).toBeUndefined()
  })

