    trimBottom: true,
  })
}

import { expect, test } from "bun:test"
import { auditAllFixtures, auditFixture, summarizeAudits, worstAudits } from "./test/layout-audit/harness.js"
import { layoutFixtures } from "./test/layout-audit/fixtures.js"

test("audits deterministic flowchart and state layout families", () => {
  const fixtures = layoutFixtures()
  const flowcharts = fixtures.filter((fixture) => fixture.kind === "flowchart")
  const states = fixtures.filter((fixture) => fixture.kind === "state")
  expect(flowcharts.length).toBeGreaterThanOrEqual(100)
  expect(states.length).toBeGreaterThanOrEqual(100)
  expect(new Set(fixtures.map((fixture) => fixture.id)).size).toBe(fixtures.length)

  const startedAt = performance.now()
  const audits = auditAllFixtures()
  const elapsedMs = performance.now() - startedAt
  const violations = audits.flatMap((audit) =>
    audit.violations.map((violation) => `${audit.fixture.id} @${audit.viewport}: ${violation}`),
  )
  const summary = summarizeAudits(audits)

  expect(audits.length).toBeGreaterThanOrEqual(fixtures.length)
  expect(violations).toEqual([])
  for (const audit of audits.filter((audit) => audit.fixture.kind === "state")) {
    expect(audit.viewport).toBe(audit.fixture.profile === "short" ? 60 : audit.fixture.profile === "unicode" ? 80 : 120)
  }
  for (const id of ["state/chain/lr-long", "state/chain/rl-long"]) {
    const audit = audits.find((candidate) => candidate.fixture.id === id)!
    expect(audit.viewport).toBe(120)
    expect([audit.metrics.width, audit.metrics.height, audit.metrics.overflow]).toEqual([84, 41, 0])
  }
  expect(
    audits
      .filter((audit) => audit.fixture.id === "flowchart/deployment-architecture/curated")
      .map((audit) => audit.viewport),
  ).toEqual([60, 80, 120])
  // decision-loops is a deliberately crossing-heavy family; ceiling it separately so it cannot absorb the
  // p95 headroom of the established families.
  const established = summarizeAudits(audits.filter((audit) => audit.fixture.family !== "decision-loops")).total
  expect(established.area.max).toBeLessThanOrEqual(11_011)
  expect(established.area.p95).toBeLessThanOrEqual(5_313)
  expect(established.bends.max).toBeLessThanOrEqual(30)
  expect(established.bends.p95).toBeLessThanOrEqual(11)
  expect(established.crossings.total).toBeLessThanOrEqual(40)
  expect(established.crossings.max).toBeLessThanOrEqual(3)
  expect(established.routeLength.max).toBeLessThanOrEqual(930)
  expect(established.routeLength.p95).toBeLessThanOrEqual(364)
  expect(established.sharedRouteCells.max).toBeLessThanOrEqual(547)
  expect(established.sharedRouteCells.p95).toBeLessThanOrEqual(122)
  expect(established.overflow.max).toBeLessThanOrEqual(170)
  expect(established.overflow.p95).toBeLessThanOrEqual(99)
  const decisionLoops = summarizeAudits(audits.filter((audit) => audit.fixture.family === "decision-loops")).total
  expect(decisionLoops.runs).toBeGreaterThan(0)
  expect(decisionLoops.area.max).toBeLessThanOrEqual(8_784)
  expect(decisionLoops.bends.max).toBeLessThanOrEqual(24)
  expect(decisionLoops.crossings.total).toBeLessThanOrEqual(24)
  expect(decisionLoops.crossings.max).toBeLessThanOrEqual(8)
  expect(decisionLoops.routeLength.max).toBeLessThanOrEqual(526)
  expect(decisionLoops.sharedRouteCells.max).toBeLessThanOrEqual(352)
  expect(decisionLoops.overflow.max).toBeLessThanOrEqual(84)
  expect(summary.state.crossings.total).toBe(0)

  for (const fixture of [...Map.groupBy(fixtures, (candidate) => `${candidate.kind}/${candidate.family}`).values()].map(
    (family) => family[0]!,
  )) {
    const first = auditFixture(fixture, 80)
    const second = auditFixture(fixture, 80)
    expect(second.output).toBe(first.output)
    expect(second.metrics).toEqual(first.metrics)
    expect(second.violations).toEqual(first.violations)
  }

  console.log(
    `[layout-audit] ${fixtures.length} sources, ${audits.length} runs, ${elapsedMs.toFixed(0)}ms`,
    JSON.stringify({
      summary,
      worst: {
        area: worstAudits(audits, "area", 3).map((audit) => [audit.fixture.id, audit.viewport, audit.metrics.area]),
        bends: worstAudits(audits, "bends", 3).map((audit) => [audit.fixture.id, audit.viewport, audit.metrics.bends]),
        crossings: worstAudits(audits, "crossings", 3).map((audit) => [
          audit.fixture.id,
          audit.viewport,
          audit.metrics.crossings,
        ]),
        overflow: worstAudits(audits, "overflow", 3).map((audit) => [
          audit.fixture.id,
          audit.viewport,
          audit.metrics.overflow,
        ]),
      },
    }),
  )
}, 40_000)

import {
  TextRenderable,
  RenderableEvents,
  createMarkdownCodeBlockRenderer,
  parseColor,
  type ColorInput,
  type MarkdownOptions,
  type MarkdownCodeBlockRenderer,
  type MouseEvent,
  type RenderContext,
  type RGBA,
  type StyledText,
} from "@opentui/core"
import { MermaidSyntaxError } from "./diagnostics.js"
import type { OpenCodeDiagramPalette } from "./palette.js"
import { DiagramCanvasSizeError } from "./core/canvas.js"
import { detectMermaidDiagram } from "./detect.js"
import { drawFlowchartDiagramGrid } from "./flowchart/drawing.js"
import { parseMermaidFlowchartDiagram } from "./flowchart/parser.js"
import { renderGridStyledText, resolveFlowchartStyleColors } from "./flowchart/style.js"
import { drawGanttDiagramGrid } from "./gantt/drawing.js"
import { parseMermaidGanttDiagram } from "./gantt/parser.js"
import { renderGanttGridStyledText } from "./gantt/render-grid.js"
import { resolveGanttStyleColors } from "./gantt/style.js"
import type { GanttDiagramRenderOptions } from "./gantt/types.js"
import { drawGitGraphDiagramGrid } from "./gitgraph/drawing.js"
import { parseMermaidGitGraphDiagram } from "./gitgraph/parser.js"
import { renderGitGraphGridStyledText } from "./gitgraph/render-grid.js"
import { resolveGitGraphStyleColors } from "./gitgraph/style.js"
import { drawSequenceDiagramGrid } from "./sequence/drawing.js"
import { parseMermaidSequenceDiagram } from "./sequence/parser.js"
import { renderSequenceGridStyledText } from "./sequence/render-grid.js"
import { resolveSequenceStyleColors } from "./sequence/style.js"
import { drawStateDiagramGrid } from "./state/drawing.js"
import { parseMermaidStateDiagram } from "./state/parser.js"
import { renderStateGridStyledText } from "./state/render-grid.js"
import { resolveStateStyleColors } from "./state/style.js"
import { drawTimelineDiagramGrid } from "./timeline/drawing.js"
import { parseMermaidTimelineDiagram } from "./timeline/parser.js"
import { renderTimelineGridStyledText } from "./timeline/render-grid.js"
import { resolveTimelineStyleColors } from "./timeline/style.js"

type DiagramKind = NonNullable<ReturnType<typeof detectMermaidDiagram>>

interface PreparedDiagram {
  readonly kind: DiagramKind
  readonly source: string
  readonly text: StyledText
  readonly height: number
}

export interface MermaidMarkdownRendererOptions {
  /** Use terminal-optimized diagram spacing. Defaults to true. */
  compact?: boolean
  /** Fold responsive horizontal diagrams that exceed this width. Defaults to 120 columns. */
  layoutMaxWidth?: number
  /** Gantt-specific terminal rendering options. */
  gantt?: Omit<GanttDiagramRenderOptions, "layoutMaxWidth">
  colors?: Partial<Record<keyof OpenCodeDiagramPalette, ColorInput>>
}

function color(value: ColorInput | undefined): RGBA | undefined {
  return value === undefined ? undefined : parseColor(value)
}

class StaticDiagramRenderable extends TextRenderable {
  constructor(ctx: RenderContext, prepared: PreparedDiagram) {
    super(ctx, {
      content: prepared.text,
      width: "100%",
      height: prepared.height,
      wrapMode: "none",
      selectable: false,
      marginTop: 1,
    })
    let dragX: number | undefined
    this.onMouseDown = (event: MouseEvent) => {
      if (event.button !== 0) return
      ctx.clearSelection()
      dragX = event.x
      event.preventDefault()
      event.stopPropagation()
    }
    this.onMouseDrag = (event: MouseEvent) => {
      event.preventDefault()
      event.stopPropagation()
      if (dragX === undefined) return
      const dx = event.x - dragX
      dragX = event.x
      if (dx) this.scrollX -= dx
    }
    this.onMouseDragEnd = (event: MouseEvent) => {
      dragX = undefined
      event.preventDefault()
      event.stopPropagation()
    }
    this.onMouseUp = (event: MouseEvent) => {
      if (event.button !== 0) return
      dragX = undefined
      event.preventDefault()
      event.stopPropagation()
    }
    this.onMouseScroll = (event: MouseEvent) => {
      const scroll = event.scroll
      if (!scroll || (scroll.direction !== "left" && scroll.direction !== "right")) return
      event.preventDefault()
      event.stopPropagation()
    }
  }
}

function prepareDiagram(
  kind: DiagramKind,
  source: string,
  options: MermaidMarkdownRendererOptions,
  layoutMaxWidth: number,
): PreparedDiagram {
  const colors = options.colors ?? {}
  const compact = options.compact ?? true
  switch (kind) {
    case "flowchart": {
      const grid = drawFlowchartDiagramGrid(parseMermaidFlowchartDiagram(source), {
        compact,
        layoutMaxWidth,
      })
      const size = grid.getTextSize({ trimTop: true, trimBottom: true })
      return {
        kind,
        source,
        text: renderGridStyledText(
          grid,
          resolveFlowchartStyleColors({
            node: color(colors.boxText ?? colors.primary),
            nodeBorder: color(colors.boxBorder ?? colors.muted),
            database: color(colors.boxText ?? colors.primary),
            databaseBorder: color(colors.boxBorder ?? colors.muted),
            edge: color(colors.line ?? colors.secondary),
            label: color(colors.text),
            group: color(colors.group ?? colors.muted),
            groupLabel: color(colors.groupText ?? colors.group ?? colors.muted),
          }),
          { label: color(colors.labelBackground) },
        ),
        height: size.height,
      }
    }
    case "gitGraph": {
      const grid = drawGitGraphDiagramGrid(parseMermaidGitGraphDiagram(source))
      const size = grid.getTextSize({ trimBottom: true })
      return {
        kind,
        source,
        text: renderGitGraphGridStyledText(
          grid,
          resolveGitGraphStyleColors({
            primary: color(colors.primary),
            secondary: color(colors.secondary),
            muted: color(colors.muted),
            warning: color(colors.warning),
            text: color(colors.text),
          }),
        ),
        height: size.height,
      }
    }
    case "gantt": {
      const grid = drawGanttDiagramGrid(parseMermaidGanttDiagram(source), { ...options.gantt, layoutMaxWidth })
      const size = grid.getTextSize({ trimBottom: true })
      return {
        kind,
        source,
        text: renderGanttGridStyledText(
          grid,
          resolveGanttStyleColors({
            title: color(colors.text),
            axis: color(colors.muted),
            background: color(colors.background),
            section: color(colors.secondary),
            task: color(colors.primary),
            active: color(colors.primary),
            critical: color(colors.warning),
            done: color(colors.muted),
          }),
        ),
        height: size.height,
      }
    }
    case "sequence": {
      const grid = drawSequenceDiagramGrid(parseMermaidSequenceDiagram(source), { compact })
      const size = grid.getTextSize()
      return {
        kind,
        source,
        text: renderSequenceGridStyledText(
          grid,
          resolveSequenceStyleColors({
            participant: color(colors.primary),
            lifeline: color(colors.muted),
            group: color(colors.secondary),
            request: color(colors.request ?? colors.primary),
            response: color(colors.response ?? colors.primary),
            fragment: color(colors.secondary),
            fragmentLabelBg: color(colors.background),
            note: color(colors.note ?? colors.warning),
            noteBg: color(colors.noteBackground ?? colors.background),
          }),
        ),
        height: size.height,
      }
    }
    case "state": {
      const grid = drawStateDiagramGrid(parseMermaidStateDiagram(source), { layoutMaxWidth })
      const size = grid.getTextSize({ trimTop: true, trimBottom: true })
      return {
        kind,
        source,
        text: renderStateGridStyledText(
          grid,
          resolveStateStyleColors({
            state: color(colors.boxText ?? colors.primary),
            stateBorder: color(colors.boxBorder ?? colors.primary),
            composite: color(colors.group ?? colors.muted),
            compositeLabel: color(colors.groupText ?? colors.group ?? colors.muted),
            transition: color(colors.line ?? colors.secondary),
            label: color(colors.text),
            noteBorder: color(colors.noteBorder ?? colors.warning),
            noteText: color(colors.noteText ?? colors.warning),
            noteConnector: color(colors.noteConnector ?? colors.muted),
            start: color(colors.marker ?? colors.muted),
            end: color(colors.marker ?? colors.muted),
            choice: color(colors.marker ?? colors.secondary),
          }),
          { label: color(colors.labelBackground) },
        ),
        height: size.height,
      }
    }
    case "timeline": {
      const grid = drawTimelineDiagramGrid(parseMermaidTimelineDiagram(source))
      const size = grid.getTextSize({ trimBottom: true })
      return {
        kind,
        source,
        text: renderTimelineGridStyledText(
          grid,
          resolveTimelineStyleColors({
            title: color(colors.text),
            section: color(colors.secondary),
            period: color(colors.warning),
            spine: color(colors.muted),
            event: color(colors.primary),
          }),
        ),
        height: size.height,
      }
    }
  }
}

/** Create an OpenTUI Markdown node renderer for fenced Mermaid diagrams. */
export function createMermaidMarkdownRenderer(
  ctx: RenderContext,
  input: MermaidMarkdownRendererOptions | (() => MermaidMarkdownRendererOptions) = {},
): NonNullable<MarkdownOptions["renderNode"]> {
  return createMarkdownCodeBlockRenderer({ mermaid: createMermaidCodeBlockRenderer(ctx, input) })!
}

export function createMermaidCodeBlockRenderer(
  ctx: RenderContext,
  input: MermaidMarkdownRendererOptions | (() => MermaidMarkdownRendererOptions) = {},
): MarkdownCodeBlockRenderer {
  const lastGood = new Map<string, PreparedDiagram>()
  return (token, context) => {
    const kind = detectMermaidDiagram(token.text)
    if (!kind) return undefined
    // OpenTUI's default block ID is the stable identity available for this fence across streaming updates.
    const key = context.defaultRender()?.id
    const options = typeof input === "function" ? input() : input
    const configuredMaxWidth =
      options.layoutMaxWidth === undefined ? 120 : Math.max(1, Math.trunc(options.layoutMaxWidth))
    const layoutMaxWidth = Math.min(configuredMaxWidth, Math.max(1, Math.trunc(ctx.width)))

    try {
      const prepared = prepareDiagram(kind, token.text, options, layoutMaxWidth)
      const diagram = new StaticDiagramRenderable(ctx, prepared)
      if (key) claimLastGood(key, prepared, diagram, lastGood)
      return diagram
    } catch (error) {
      if (error instanceof MermaidSyntaxError) {
        const previous = key ? lastGood.get(key) : undefined
        if (previous?.kind === kind) {
          const diagram = new StaticDiagramRenderable(ctx, previous)
          claimLastGood(key!, previous, diagram, lastGood)
          return diagram
        }

        const lines = token.text.split("\n")
        if (error.lineNumber <= 2 || lines.slice(error.lineNumber).some((line) => line.trim())) return undefined

        try {
          const prepared = prepareDiagram(
            kind,
            lines.slice(0, error.lineNumber - 1).join("\n"),
            options,
            layoutMaxWidth,
          )
          if (!prepared.height) return undefined
          const diagram = new StaticDiagramRenderable(ctx, prepared)
          if (key) claimLastGood(key, prepared, diagram, lastGood)
          return diagram
        } catch (error) {
          if (error instanceof MermaidSyntaxError || error instanceof DiagramCanvasSizeError) return undefined
          throw error
        }
      }
      if (error instanceof DiagramCanvasSizeError) return undefined
      throw error
    }
  }
}

function claimLastGood(
  key: string,
  value: PreparedDiagram,
  owner: StaticDiagramRenderable,
  cache: Map<string, PreparedDiagram>,
): void {
  const claim = { ...value }
  cache.set(key, claim)
  owner.once(RenderableEvents.DESTROYED, () => {
    // Reconciliation destroys the old block before synchronously creating its replacement.
    queueMicrotask(() => {
      if (cache.get(key) === claim) cache.delete(key)
    })
  })
}

import { describe, expect, test } from "bun:test"
import { RGBA } from "@opentui/core"
import { blendColor } from "./core/color/style.js"
import { createOpenCodeDiagramPalette, resolveOpenCodeDiagramPalette } from "./palette.js"

type Rgb = readonly [number, number, number]

const rgb = (value: Rgb) => RGBA.fromInts(...value)

describe("OpenCode diagram palette", () => {
  test.each([
    {
      name: "dark theme",
      text: [230, 232, 240],
      subdued: [114, 120, 138],
      secondary: [172, 176, 189],
      muted: [149, 154, 169],
    },
    {
      name: "light theme",
      text: [32, 35, 43],
      subdued: [119, 125, 138],
      secondary: [76, 80, 91],
      muted: [93, 98, 110],
    },
  ] satisfies ReadonlyArray<{
    name: string
    text: Rgb
    subdued: Rgb
    secondary: Rgb
    muted: Rgb
  }>)("derives a controlled neutral ladder for a $name", ({ text, subdued, secondary, muted }) => {
    const primary = rgb(text)
    const info = RGBA.fromInts(40, 120, 220)
    const success = RGBA.fromInts(80, 180, 120)
    const warning = RGBA.fromInts(220, 160, 80)
    const background = RGBA.fromInts(10, 20, 30)
    const accent = {
      soft: RGBA.fromInts(180, 100, 40),
      clear: RGBA.fromInts(240, 160, 80),
    }
    const palette = createOpenCodeDiagramPalette({
      text: primary,
      subdued: rgb(subdued),
      info,
      success,
      warning,
      background,
      accent,
    })

    expect(palette.text).toBe(primary)
    expect(palette.primary).toBe(primary)
    expect(palette.secondary.equals(rgb(secondary))).toBe(true)
    expect(palette.muted.equals(rgb(muted))).toBe(true)
    expect(palette.warning).toBe(info)
    expect(palette.background).toBe(background)
    expect(palette.request).toBe(success)
    expect(palette.response).toBe(warning)
    expect(palette.note).toBe(primary)
    expect(palette.noteBackground.equals(blendColor(background, rgb(subdued), 0.25))).toBe(true)
    expect(palette.boxText).toBe(primary)
    expect(palette.boxBorder.equals(rgb(muted))).toBe(true)
    expect(palette.line.equals(rgb(subdued))).toBe(true)
    expect(palette.labelBackground.toInts()[3]).toBe(20)
    expect(palette.group).toBe(accent.soft)
    expect(palette.groupText).toBe(accent.soft)
    expect(palette.marker.equals(rgb(secondary))).toBe(true)
    expect(palette.noteBorder).toBe(accent.soft)
    expect(palette.noteText).toBe(accent.clear)
    expect(palette.noteConnector).toBe(accent.soft)
  })

  test.each([
    { mode: "dark", soft: 300, clear: 200 },
    { mode: "light", soft: 700, clear: 800 },
  ] as const)("uses the selected $mode mode even with a literal background", ({ mode, soft, clear }) => {
    const accent = {
      200: rgb([200, 100, 100]),
      300: rgb([180, 90, 90]),
      700: rgb([120, 60, 60]),
      800: rgb([100, 50, 50]),
    }
    const theme = {
      text: {
        base: rgb([230, 232, 240]),
        muted: rgb([114, 120, 138]),
        feedback: {
          info: { base: rgb([40, 120, 220]) },
          success: { base: rgb([80, 180, 120]) },
          warning: { base: rgb([220, 160, 80]) },
        },
      },
      background: { base: rgb([250, 250, 250]) },
      categorical: [accent],
    }
    const palette = resolveOpenCodeDiagramPalette(theme, mode)

    expect(palette.group).toBe(accent[soft])
    expect(palette.noteBorder).toBe(accent[soft])
    expect(palette.noteText).toBe(accent[clear])
  })
})

import { RGBA } from "@opentui/core"
import { blendColor } from "./core/color/style.js"

export interface OpenCodeDiagramPaletteInput {
  readonly text: RGBA
  readonly subdued: RGBA
  readonly info: RGBA
  readonly success: RGBA
  readonly warning: RGBA
  readonly background: RGBA
  readonly accent: {
    readonly soft: RGBA
    readonly clear: RGBA
  }
}

export type OpenCodeDiagramPalette = ReturnType<typeof createOpenCodeDiagramPalette>

export function createOpenCodeDiagramPalette(input: OpenCodeDiagramPaletteInput) {
  const secondary = blendColor(input.text, input.subdued, 0.5)
  const muted = blendColor(input.text, input.subdued, 0.7)
  return {
    text: input.text,
    primary: input.text,
    secondary,
    muted,
    warning: input.info,
    background: input.background,
    request: input.success,
    response: input.warning,
    note: input.text,
    noteBackground: blendColor(input.background, input.subdued, 0.25),
    boxText: input.text,
    boxBorder: muted,
    line: input.subdued,
    labelBackground: RGBA.fromValues(input.text.r, input.text.g, input.text.b, 0.08),
    group: input.accent.soft,
    groupText: input.accent.soft,
    marker: secondary,
    noteBorder: input.accent.soft,
    noteText: input.accent.clear,
    noteConnector: input.accent.soft,
  }
}

export function resolveOpenCodeDiagramPalette(
  theme: {
    readonly text: {
      readonly base: RGBA
      readonly muted: RGBA
      readonly feedback: {
        readonly info: { readonly base: RGBA }
        readonly success: { readonly base: RGBA }
        readonly warning: { readonly base: RGBA }
      }
    }
    readonly background: { readonly base: RGBA }
    readonly categorical: readonly Readonly<Record<200 | 300 | 700 | 800, RGBA>>[]
  },
  mode: "dark" | "light",
) {
  const accent = theme.categorical[3] ?? theme.categorical[0]!
  return createOpenCodeDiagramPalette({
    text: theme.text.base,
    subdued: theme.text.muted,
    info: theme.text.feedback.info.base,
    success: theme.text.feedback.success.base,
    warning: theme.text.feedback.warning.base,
    background: theme.background.base,
    accent: {
      soft: accent[mode === "dark" ? 300 : 700],
      clear: accent[mode === "dark" ? 200 : 800],
    },
  })
}

