describe("createStateTransitionRenderPlans", () => {
  test("prepares concrete cells, labels, and route paths before painting", () => {
    const diagram: StateVisibleDiagram = {
      direction: "LR",
      states: ["A", "B"].map((id) => ({ id, label: id, kind: "state" })),
