      ).toEqual(Array.from({ length: 3 }, () => ({ temperature: 0.25, tools: ["thread_echo"] })))
      yield* Scope.close(secondScope, Exit.void)
      expect(closed).toEqual([1, 2])
    }),
  15_000,
)

