import { tmpdir } from "../../core/test/fixture/tmpdir"
import { OpenCode, Session } from "../src"

test("Promise host uses the embedded router", async () => {
  await using directory = await tmpdir("opencode-promise-sdk-")
  const config = join(directory.path, "config")
  await mkdir(config)
  const opencode = await OpenCode.create({
    events: { persist: true },
    config: { directory: config, project: false, content: "{}" },
  })

  try {
    const location = { directory: directory.path }
    const session = await opencode.sessions.create({ location })
    const selected = await opencode.sessions.get({ sessionID: session.id })
    const page = await opencode.sessions.list({ directory: directory.path })
    const events = Array.fromAsync(opencode.sessions.log({ sessionID: session.id }))

    expect(selected.id).toBe(session.id)
    expect(page.data.some((item) => item.id === session.id)).toBe(true)
    expect((await events).some((event) => event.type === "session.created")).toBe(true)

    const missingSessionID = Session.ID.create()
    const missing = await opencode.sessions.get({ sessionID: missingSessionID }).catch((error: unknown) => error)
    expect(missing).toMatchObject({ _tag: "SessionNotFoundError", sessionID: missingSessionID })
  } finally {
    await opencode.close()
    await opencode.close()
  }
})

test("Promise event streams support cancellation", async () => {
  await using directory = await tmpdir("opencode-promise-stream-")
  const config = join(directory.path, "config")
  await mkdir(config)
  {
    await using opencode = await OpenCode.create({ config: { directory: config, project: false, content: "{}" } })
    const controller = new AbortController()
    const events = opencode.events.subscribe({ signal: controller.signal })[Symbol.asyncIterator]()
    expect(await events.next()).toMatchObject({ value: { type: "server.connected" }, done: false })
    const pending = events.next()
    controller.abort()
    // A caller abort ends only this subscriber; client tests pin closing the shared transport after the last one.
    expect(await pending).toEqual({ done: true, value: undefined })
    await events.return?.()
  }
})

test("closing cancels active Promise event streams", async () => {
  await using directory = await tmpdir("opencode-promise-stream-close-")
  const config = join(directory.path, "config")
  await mkdir(config)
  const opencode = await OpenCode.create({ config: { directory: config, project: false, content: "{}" } })
  const events = opencode.events.subscribe()[Symbol.asyncIterator]()
  expect(await events.next()).toMatchObject({ value: { type: "server.connected" }, done: false })
  const pending = events.next()

  await opencode.close()
  const error = await pending.catch((error: unknown) => error)
  expect(error).toMatchObject({ name: "ClientError", reason: "Transport" })
})

import { expect } from "bun:test"
import { fullGC, heapStats } from "bun:jsc"
import { Effect, Layer } from "effect"
import { tmpdirScoped } from "../../core/test/fixture/tmpdir"
import { testEffect } from "../../core/test/lib/effect"
import { OpenCode } from "../src/effect"
import { OwnedFetch } from "../src/internal/fetch"

const it = testEffect(Layer.empty)

it.live("releases completed embedded requests while the host stays open", () =>
  Effect.gen(function* () {
    const directory = yield* tmpdirScoped()
    const client = yield* OpenCode.create({
      app: { version: "request-retention-test" },
      config: { directory: directory.path, project: false, content: "{}" },
      events: { persist: true },
      models: { fetch: false },
      fs: { filewatcher: false },
    })

    fullGC()
    const before = heapStats().objectTypeCounts.Request ?? 0
    for (let index = 0; index < 200; index++) {
      expect((yield* client.server.info()).version).toBe("request-retention-test")
    }

    // Completed response cleanup crosses an event-loop turn in the embedded transport.
    yield* Effect.promise(() => Bun.sleep(100))
    fullGC()
    expect((heapStats().objectTypeCounts.Request ?? 0) - before).toBeLessThan(20)
  }),
)

it.live("releases failed embedded requests while the host and caller signal stay open", () =>
  Effect.promise(async () => {
    const caller = new AbortController()
    const requests: WeakRef<Request>[] = []
    const transport = OwnedFetch.make(
      async (request) => {
        requests.push(new WeakRef(request))
        request.signal.addEventListener("abort", () => void request.url)
        throw new Error("handler failed")
      },
      async () => {},
    )

    for (let index = 0; index < 120; index++) {
      expect(
        await transport
          .fetch(`http://opencode.local/${index}`, { signal: caller.signal })
          .catch((cause: unknown) => cause),
      ).toMatchObject({
        message: "handler failed",
      })
    }

    await Bun.sleep(50)
    fullGC()
    expect(caller.signal.aborted).toBe(false)
    expect(requests.filter((ref) => ref.deref() !== undefined).length).toBeLessThanOrEqual(3)
    await transport.close()
  }),
)

it.live("keeps caller abort and host shutdown wired to active requests", () =>
  Effect.promise(async () => {
    const seen: unknown[] = []
    let disposed = false
    const transport = OwnedFetch.make(
      async (request) => {
        await new Promise<void>((resolve) => {
          request.signal.addEventListener(
            "abort",
            () => {
              seen.push(request.signal.reason)
              resolve()
            },
            { once: true },
          )
        })
        return new Response("aborted")
      },
      async () => {
        disposed = true
      },
    )
    const controller = new AbortController()
    const first = transport.fetch("http://opencode.local/", { signal: controller.signal })
    controller.abort("caller")
    expect(await first.catch((error: unknown) => error)).toBe("caller")

    const second = transport.fetch("http://opencode.local/")
    const closed = transport.close()
    const failure = await second.catch((error: unknown) => error)
    expect(failure).toBeInstanceOf(Error)
    expect(failure).toMatchObject({ message: "OpenCode host is closed" })
    await closed
    expect(disposed).toBe(true)
    expect(seen).toEqual(["caller", failure])
  }),
)

it.live("cancels an open response body on host shutdown before disposing the handler", () =>
  Effect.promise(async () => {
    const cancelled = Promise.withResolvers<unknown>()
    let disposed = false
    const transport = OwnedFetch.make(
      async () =>
        new Response(
          new ReadableStream({
            cancel(reason) {
              cancelled.resolve(reason)
            },
          }),
        ),
      async () => {
        disposed = true
      },
    )

    const response = await transport.fetch("http://opencode.local/stream")
    const reading = response.body!.getReader().read()
    const closing = transport.close()
    const reason = await cancelled.promise

    expect(reason).toBeInstanceOf(Error)
    expect(reason).toMatchObject({ message: "OpenCode host is closed" })
    expect(await reading.catch((cause: unknown) => cause)).toBe(reason)
    await closing
    expect(disposed).toBe(true)
  }),
)

import { expect } from "bun:test"
import { Context, Effect, Exit, Layer, Scope, Stream } from "effect"
import { FetchHttpClient } from "effect/http"
import { tmpdirScoped } from "../../core/test/fixture/tmpdir"
import { testEffect } from "../../core/test/lib/effect"
import { AbsolutePath, Location, OpenCode, Session } from "../src/effect"

const it = testEffect(Layer.empty)

for (const entrypoint of ["create", "layer"] as const) {
  it.live(`${entrypoint} keeps requests and streams on its own transport despite an ambient Fetch`, () =>
    Effect.gen(function* () {
      const directory = yield* tmpdirScoped()
      const calls: string[] = []
      const ambient = Object.assign(
        (input: RequestInfo | URL) => {
          calls.push(input instanceof Request ? input.url : String(input))
          return Promise.reject(new Error("The caller's Fetch must not receive embedded SDK requests"))
        },
        { preconnect: () => undefined },
      )
      const parent = yield* Effect.scope
      const scope = yield* Scope.fork(parent)
      const options: OpenCode.CreateOptions = {
        app: { version: "transport-test" },
        config: { directory: directory.path, project: false, content: "{}" },
        events: { persist: true },
        models: { fetch: false },
        fs: { filewatcher: false },
      }
      const client = yield* (
        entrypoint === "create"
          ? OpenCode.create(options).pipe(Scope.provide(scope))
          : Layer.buildWithScope(OpenCode.layer(options), scope).pipe(Effect.map(Context.get(OpenCode.Service)))
      ).pipe(Effect.provideService(FetchHttpClient.Fetch, ambient))

      yield* Effect.gen(function* () {
        expect(yield* client.server.info()).toMatchObject({ version: "transport-test" })
        const session = yield* client.sessions.create({
          location: Location.Ref.make({ directory: AbsolutePath.make(directory.path) }),
        })
        expect((yield* client.sessions.get({ sessionID: session.id })).id).toBe(session.id)
        const events = yield* client.sessions.log({ sessionID: session.id }).pipe(Stream.runCollect)
        expect(events.some((event) => event.type === "session.created")).toBe(true)
        expect(yield* client.events.subscribe().pipe(Stream.take(1), Stream.runCollect)).toMatchObject([
          { type: "server.connected" },
        ])
        const missing = Session.ID.create()
        // Error responses must decode over the SDK transport too; sessions.get is served by core without HTTP.
        expect(yield* client.sessions.export({ sessionID: missing }).pipe(Effect.flip)).toMatchObject({
          _tag: "SessionNotFoundError",
        })
        expect(yield* client.sessions.get({ sessionID: missing }).pipe(Effect.flip)).toMatchObject({
          _tag: "Session.NotFoundError",
        })
        // Binding the SDK's transport must not change the caller's surrounding context.
        expect(yield* FetchHttpClient.Fetch).toBe(ambient)
      }).pipe(Effect.provideService(FetchHttpClient.Fetch, ambient))
      expect(calls).toEqual([])

      yield* Scope.close(scope, Exit.void)
      expect(
        Exit.isFailure(
          yield* client.server.info().pipe(Effect.provideService(FetchHttpClient.Fetch, ambient), Effect.exit),
        ),
      ).toBe(true)
      expect(calls).toEqual([])
    }),
  )
}

import { expect, test } from "bun:test"
import { mkdir, rm } from "node:fs/promises"
import { join } from "node:path"
import { Plugin } from "@opencode/plugin"
import { initRepo } from "../../core/test/fixture/git"
import { tmpdir } from "../../core/test/fixture/tmpdir"
import { OpenCode } from "../src"

test("embedded worktree APIs use project IDs and SDK-registered strategies", async () => {
  await using directory = await tmpdir("opencode-sdk-worktree-")
  await initRepo(directory.path)
  const state = { activated: 0, discovered: 0, removed: 0 }
  const plugin = Plugin.define({
    id: "sdk-worktrees",
    async setup(ctx) {
      state.activated++
      await ctx.worktree.transform((editor) =>
        editor.add({
          id: "sdk-copy",
          async create(input, { signal }) {
            signal.throwIfAborted()
            await mkdir(input.directory)
            return { directory: input.directory }
          },
          async remove(input, { signal }) {
            signal.throwIfAborted()
            await rm(input.directory, { recursive: true })
            state.removed++
          },
          async list(_source, { signal }) {
            signal.throwIfAborted()
            state.discovered++
            return []
          },
        }),
      )
    },
  })
  await using opencode = await OpenCode.create({
    plugins: [plugin],
    config: { directory: directory.path, project: false },
    models: { fetch: false },
    fs: { filewatcher: false },
  })
  const session = await opencode.sessions.create({ location: { directory: directory.path } })
  const projectID = session.projectID
  expect(await opencode.worktree.list({ projectID })).toHaveLength(1)
  expect(state.activated).toBe(0)
  const worktree = await opencode.worktree.create({
    projectID,
    directory: join(directory.path, "copies"),
    name: "task",
  })
  expect(state.activated).toBe(1)
  expect(await opencode.worktree.list({ projectID })).toContainEqual({
    directory: worktree.directory,
    strategy: "sdk-copy",
  })
  expect(state.discovered).toBe(0)
  await opencode.worktree.refresh({ projectID })
  expect(state.discovered).toBe(1)
  await opencode.worktree.remove({ projectID, directory: worktree.directory, force: false })
  expect(state.removed).toBe(1)
  expect(await opencode.worktree.list({ projectID })).toHaveLength(1)
})

#!/usr/bin/env bun

import { $ } from "bun"
import { rm } from "node:fs/promises"
import path from "node:path"
import { fileURLToPath } from "node:url"

process.chdir(fileURLToPath(new URL("..", import.meta.url)))

await rm("dist", { recursive: true, force: true })
await $`bun tsc -p tsconfig.build.json`
const root = path.resolve("src")
const result = await Bun.build({
  entrypoints: await Array.fromAsync(new Bun.Glob("**/*.ts").scan({ cwd: root, absolute: true })).then((files) =>
    files.filter((file) => !file.endsWith(".d.ts")),
  ),
  root,
  outdir: "dist",
  target: "node",
  format: "esm",
  packages: "external",
  splitting: true,
  naming: {
    entry: "[dir]/[name].[ext]",
    chunk: "chunks/[name]-[hash].[ext]",
  },
})
if (!result.success) throw new AggregateError(result.logs, "Failed to build Server")

#!/usr/bin/env bun

import { Script } from "@opencode/script"
import { $ } from "bun"
import { rm } from "node:fs/promises"
import { fileURLToPath } from "node:url"

process.chdir(fileURLToPath(new URL("..", import.meta.url)))

const dryRun = Bun.argv.includes("--dry-run")
const originalText = await Bun.file("package.json").text()
const pkg = JSON.parse(originalText) as {
  name: string
  version: string
  exports: Record<string, string | { import: string; types: string }>
}
const tarball = `${pkg.name.replace("@", "").replace("/", "-")}-${pkg.version}.tgz`

if (!dryRun && (await $`npm view ${pkg.name}@${pkg.version} version`.nothrow()).exitCode === 0) {
  console.log(`already published ${pkg.name}@${pkg.version}`)
  process.exit(0)
}

try {
  await $`bun run typecheck`
  await $`bun run build`
  pkg.exports = Object.fromEntries(
    Object.entries(pkg.exports).map(([key, value]) => {
      if (typeof value !== "string") return [key, value]
      return [
        key,
        {
          import: value.replace("./src/", "./dist/").replace(/\.ts$/, ".js"),
          types: value.replace("./src/", "./dist/").replace(/\.ts$/, ".d.ts"),
        },
      ]
    }),
  )
  await Bun.write("package.json", JSON.stringify(pkg, null, 2) + "\n")
  await rm(tarball, { force: true })
  await $`bun pm pack`
  if (!dryRun) await $`npm publish ${tarball} --tag ${Script.channel} --access public`
} finally {
  await Bun.write("package.json", originalText)
  await rm(tarball, { force: true })
}

#!/usr/bin/env bun
/**
 * Bundle probe for the workerd profile: verifies the full module graph behind
 * src/workerd.ts resolves under the `workerd` condition without any `bun:`
 * builtins. `node:` builtins stay external (workerd provides them through
 * nodejs_compat); the probe prints the surviving externals so the A4 boot
 * spike knows exactly what the runtime must supply.
 */
import path from "node:path"
import { mkdtempSync } from "node:fs"
import os from "node:os"

const outdir = mkdtempSync(path.join(os.tmpdir(), "opencode-workerd-probe-"))
const result = await Bun.build({
  entrypoints: [path.join(import.meta.dir, "../src/workerd.ts")],
  conditions: ["workerd"],
  target: "node",
  outdir,
  sourcemap: "none",
  throw: false,
})

if (!result.success) {
  console.error(`workerd bundle probe FAILED (${result.logs.length} issues)`)
  for (const log of result.logs) console.error(String(log))
  process.exit(1)
}

// Everything in the graph is bundled, so any import specifier that survives in
// the output is an external the runtime must provide. A specifier reached only
// through `import()` is loaded lazily behind a runtime guard, so it costs
// nothing on a runtime that never takes that branch; a static import is
// evaluated on module load and must resolve.
const transpiler = new Bun.Transpiler({ loader: "js" })
const externals = new Map<string, { static: boolean }>()
const record = (specifier: string, isStatic: boolean) => {
  const seen = externals.get(specifier)
  externals.set(specifier, { static: (seen?.static ?? false) || isStatic })
}
for (const artifact of result.outputs) {
  const text = await artifact.text()
  for (const imported of transpiler.scanImports(text)) record(imported.path, imported.kind !== "dynamic-import")
  for (const match of text.matchAll(/\brequire\(\s*"([^"]+)"\s*\)/g)) record(match[1], true)
}
const sorted = Array.from(externals.keys()).toSorted()
const isBun = (specifier: string) => specifier === "bun" || specifier.startsWith("bun:")
const leaked = sorted.filter((specifier) => isBun(specifier) && externals.get(specifier)!.static)
const bytes = result.outputs.reduce((total, artifact) => total + artifact.size, 0)

console.log(`workerd bundle probe OK: ${result.outputs.length} artifacts, ${(bytes / 1024 / 1024).toFixed(1)} MiB`)
console.log(`external builtins (${sorted.length}):`)
for (const specifier of sorted) {
  const lazy = externals.get(specifier)!.static ? "" : " (lazy)"
  console.log(`  ${specifier}${lazy}`)
}
if (leaked.length > 0) {
  console.error(`FAILED: bun builtins statically imported in the workerd graph: ${leaked.join(", ")}`)
  process.exit(1)
}

export * as ServerAuth from "./auth"

import { Context, Layer, Option, Redacted } from "effect"
import { createHmac, timingSafeEqual } from "node:crypto"

export type DecodedCredentials = {
  readonly username: string
  readonly password: Redacted.Redacted
}

export type Info = {
  readonly password: Option.Option<string>
  readonly username: string
}

export const SESSION_TTL_SECONDS = 30 * 24 * 60 * 60

export class Config extends Context.Service<Config, Info>()("@opencode/ServerAuthConfig") {
  static configLayer(input: Pick<Info, "password">) {
    return Layer.succeed(this, this.of({ ...input, username: "opencode" }))
  }

  static get layer() {
    return this.configLayer({ password: Option.none() })
  }
}

export function required(config: Info) {
  return Option.isSome(config.password) && config.password.value !== ""
}

// Session tokens issued by pairing links are accepted anywhere the password is.
export function authorized(credentials: DecodedCredentials, config: Info) {
  if (Option.isNone(config.password) || credentials.username !== config.username) return false
  const password = Redacted.value(credentials.password)
  return password === config.password.value || verifySession(password, config)
}

// Sessions are signed with a key derived from the server password, so rotating the password revokes every session.
export function issueSession(config: Info, now = Date.now()) {
  if (Option.isNone(config.password)) return
  const expires = String(Math.floor(now / 1000) + SESSION_TTL_SECONDS)
  return `${expires}.${sign(config.password.value, expires)}`
}

export function verifySession(token: string, config: Info, now = Date.now()) {
  if (Option.isNone(config.password)) return false
  const parts = token.split(".")
  if (parts.length !== 2) return false
  const expires = Number(parts[0])
  if (!Number.isSafeInteger(expires) || expires * 1000 <= now) return false
  const expected = Buffer.from(sign(config.password.value, parts[0]))
  const actual = Buffer.from(parts[1])
  return actual.length === expected.length && timingSafeEqual(actual, expected)
}

// Browsers share cookies across ports on the same host, so the name carries the port to keep local servers apart.
export function sessionCookieName(host: string | undefined) {
  const port = URL.parse(`http://${host ?? ""}`)?.port
  return port ? `opencode_session_${port}` : "opencode_session"
}

function sign(password: string, payload: string) {
  const key = createHmac("sha256", password).update("opencode-session-v1").digest()
  return createHmac("sha256", key).update(payload).digest("base64url")
}

import { Context } from "effect"

const opencodeOrigin = /^https:\/\/([a-z0-9-]+\.)*opencode\.ai$/

export type CorsOptions = { readonly cors?: ReadonlyArray<string> }

export const CorsConfig = Context.Reference<CorsOptions | undefined>("@opencode/ServerCorsConfig", {
  defaultValue: () => undefined,
})

export function isAllowedCorsOrigin(input: string | undefined, opts?: CorsOptions) {
  if (!input) return true
  if (input.startsWith("http://localhost:")) return true
  if (input.startsWith("http://127.0.0.1:")) return true
  if (input.startsWith("oc://renderer")) return true
  if (input === "tauri://localhost" || input === "http://tauri.localhost" || input === "https://tauri.localhost")
    return true
  if (opencodeOrigin.test(input)) return true
  return opts?.cors?.includes(input) ?? false
}

export function isAllowedRequestOrigin(input: string | undefined, host: string | undefined, opts?: CorsOptions) {
  if (!input) return true
  if (host && sameHost(input, host)) return true
  return isAllowedCorsOrigin(input, opts)
}

function sameHost(origin: string, host: string) {
  try {
    return new URL(origin).host === host
  } catch {
    return false
  }
}

export * as EventFeed from "./event-feed"

import { Bus } from "@opencode/core/bus"
import { Event } from "@opencode/schema/event"
import { isOpenCodeEvent, type OpenCodeEvent } from "@opencode/protocol/groups/event"
import { Cause, Context, Effect, Layer, Queue, Schema, Scope, Stream } from "effect"

export const SubscriberCapacity = 4_096

export class SubscriberOverflowError extends Schema.TaggedError<SubscriberOverflowError>()(
  "EventFeed.SubscriberOverflow",
  { capacity: Schema.Int },
) {}

export class EncodingError extends Schema.TaggedError<EncodingError>()("EventFeed.EncodingError", {
  eventID: Event.ID,
  eventType: Schema.String,
  cause: Schema.Defect(),
}) {}

export type Error = SubscriberOverflowError | EncodingError

export interface Interface {
  readonly subscribe: Effect.Effect<Stream.Stream<string, Error>, never, Scope.Scope>
}

export class Service extends Context.Service<Service, Interface>()("@opencode/server/EventFeed") {}

export function frame(event: OpenCodeEvent) {
  return `data: ${JSON.stringify(event)}\n\n`
}

export const make = Effect.fn("EventFeed.make")(function* (
  observe: (subscriber: Bus.Subscriber) => Effect.Effect<Bus.Unsubscribe>,
  options?: { readonly capacity?: number; readonly encode?: (event: OpenCodeEvent) => string },
) {
  const capacity = options?.capacity ?? SubscriberCapacity
  const render = options?.encode ?? frame
  const subscribers = new Set<Queue.Queue<string, Error>>()

  const fail = (error: Error) =>
    Effect.sync(() => {
      const current = Array.from(subscribers)
      subscribers.clear()
      for (const subscriber of current) Queue.failCauseUnsafe(subscriber, Cause.fail(error))
    })

  const publish = Effect.fnUntraced(function* (event: Event.Payload) {
    if (!isOpenCodeEvent(event)) return
    if (subscribers.size === 0) return
    const encoded = yield* Effect.try({
      try: () => render(event),
      catch: (cause) => new EncodingError({ eventID: event.id, eventType: event.type, cause }),
    }).pipe(
      Effect.catch((error) =>
        Effect.logError("Failed to encode public event", {
          eventID: error.eventID,
          eventType: error.eventType,
          cause: error.cause,
        }).pipe(Effect.andThen(fail(error)), Effect.as(undefined)),
      ),
    )
    if (encoded === undefined) return
    for (const subscriber of subscribers) {
      if (Queue.offerUnsafe(subscriber, encoded)) continue
      subscribers.delete(subscriber)
      Queue.failCauseUnsafe(subscriber, Cause.fail(new SubscriberOverflowError({ capacity })))
    }
  })

  const unsubscribe = yield* observe(publish)
  yield* Effect.addFinalizer(() => unsubscribe)

  return Service.of({
    subscribe: Effect.acquireRelease(
      Queue.dropping<string, Error>(capacity).pipe(Effect.tap((queue) => Effect.sync(() => subscribers.add(queue)))),
      (queue) =>
        Effect.sync(() => subscribers.delete(queue)).pipe(Effect.andThen(Queue.shutdown(queue)), Effect.asVoid),
    ).pipe(Effect.map(Stream.fromQueue)),
  })
})

export const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const bus = yield* Bus.Service
    return yield* make(bus.listen)
  }),
)

import { Agent } from "@opencode/core/agent"
import { Effect } from "effect"
import { HttpApiBuilder } from "effect/http-api"
import { Api } from "../api"
import { response } from "../location"
import { AgentNotFoundError } from "@opencode/protocol/errors"

export const AgentHandler = HttpApiBuilder.group(Api, "server.agent", (handlers) =>
  handlers
    .handle("agent.list", () =>
      Effect.gen(function* () {
        return yield* response(Agent.Service.use((agent) => agent.list()))
      }),
    )
    .handle(
      "agent.get",
      Effect.fn(function* (ctx) {
        const agent = yield* Agent.Service.use((service) => service.get(ctx.params.agentID))
        if (!agent)
          return yield* new AgentNotFoundError({
            agentID: ctx.params.agentID,
            message: `Agent not found: ${ctx.params.agentID}`,
          })
        return yield* response(Effect.succeed(agent))
      }),
    ),
)

