      takeover.socket.close()
      yield* Effect.promise(() => client.experimental.persistentPty.remove({ ptyID: first.id }))
      expect((yield* Effect.promise(() => client.experimental.persistentPty.read({ sessionID })))?.ptyID).toBe(
