import { createSignal, Show } from "solid-js"
import { render } from "solid-js/web"
import { Markdown } from "../../src/components/markdown"
import { getCachedMarkdown } from "../../src/components/markdown-cache"
import type { MarkdownWorkerRequest, MarkdownWorkerResponse } from "../../src/components/markdown-worker-protocol"
import "@opencode/ui/styles"
import "@opencode/ui/styles/tokens"
import "../../src/components/markdown.css"

const scenario = new URLSearchParams(location.search).get("scenario") ?? "mounted"

const sections = Array.from({ length: 36 }, (_, index) => {
  const service = ["catalog", "billing", "delivery", "inventory", "accounts", "notifications"][index % 6]

  return [
    `## ${index + 1}. Validate the ${service} recovery boundary`,
    `The ${service} service should publish durable progress before acknowledging a request. Keep the request ID in the transaction so a retry does not create a second operation. The implementation below separates admission from delivery and makes the recovery decision explicit.`,
    "Check the existing rows before scheduling work. A disconnected client is not evidence that the operation failed, and the background processor must not delete accepted work when a view closes. Use the stored status for the next attempt, not a process-local flag.",
    `\`\`\`typescript\nexport async function recover${index}(db: Database, request: Request) {\n  const previous = await db.operations.find(request.id)\n  if (previous?.status === "complete") return previous.result\n  const operation = previous ?? await db.transaction(async (tx) => {\n    const row = await tx.operations.insert({\n      id: request.id,\n      service: "${service}",\n      status: "accepted",\n      payload: request.payload,\n    })\n    await tx.events.publish({ type: "operation.accepted", id: row.id })\n    return row\n  })\n  await schedule(operation.id)\n  return { id: operation.id, status: operation.status }\n}\n\`\`\``,
    "| Condition | Expected behavior |\n| --- | --- |\n| Duplicate request | Return the first accepted result |\n| Worker restart | Resume the stored operation |\n| Client leaves | Retain accepted work without retaining the view |",
    `Run the focused test with \`bun test test/${service}/recovery.test.ts\`. Verify the [transaction contract](https://example.com/transactions) and inspect the operation's final state before expanding the rollout.`,
  ].join("\n\n")
})

const answer = `# Recovery implementation review\n\n${sections.join("\n\n")}\n\n**Review complete.**`

const destination =
  "## Current destination\n\nThe new session is ready.\n\n```typescript\nconst current = { ready: true }\n```"

const stats = {
  bytes: new TextEncoder().encode(answer).length,
  fences: sections.length,
  messages: 1,
  parts: 1,
  requests: 0,
  responses: 0,
  released: 0,
  ready: 0,
  settled: 0,
  disposed: false,
  cacheChars: 0,
}

// Keep the real worker and parser. Only hold delivery of this answer's result so
// disposal always happens after admission and before main-thread postprocessing.
const descriptor = Object.getOwnPropertyDescriptor(Worker.prototype, "onmessage")!

const post = Worker.prototype.postMessage

let held: (() => void) | undefined

let answerID: number | undefined

Object.defineProperty(Worker.prototype, "onmessage", {
  configurable: true,
  get: descriptor.get,
  set(callback: (event: MessageEvent<MarkdownWorkerResponse>) => void) {
    descriptor.set!.call(this, (event: MessageEvent<MarkdownWorkerResponse>) => {
      if (event.data.type === "parse" && event.data.id === answerID) {
        stats.responses++
        held = () => callback.call(this, event)
        document.querySelector<HTMLButtonElement>("#continue")!.disabled = false

        return
      }

      callback.call(this, event)
    })
  },
})

Worker.prototype.postMessage = function (request: MarkdownWorkerRequest) {
  if (request.type === "parse" && request.text === answer) {
    answerID = request.id
    stats.requests++
  }

  post.call(this, request)
}

const observer = new MutationObserver(() => {
  if (!stats.released || stats.ready) return
  const target = document.querySelector(scenario === "leave" ? "#destination" : "#survivor")

  if (!target?.hasAttribute("data-markdown-ready")) return
  stats.ready = performance.now()
  document.body.dataset.ready = "true"
})

observer.observe(document.body, { subtree: true, attributes: true, childList: true })

render(() => {
  const [admitted, setAdmitted] = createSignal(false)
  const [leaving, setLeaving] = createSignal(false)

  return (
    <main style={{ "max-width": "960px", margin: "24px auto", "font-family": "sans-serif", "line-height": "1.5" }}>
      <button id="admit" onClick={() => setAdmitted(true)} disabled={admitted()}>
        Admit answer
      </button>
      <button
        id="continue"
        disabled
        onClick={() => {
          stats.released = performance.now()
          performance.mark("markdown-lifetime-release")

          if (scenario !== "mounted") {
            stats.disposed = true
            setLeaving(true)
          }

          held!()
          held = undefined
          const channel = new MessageChannel()
          channel.port1.onmessage = () => {
            stats.settled = performance.now()
            stats.cacheChars = getCachedMarkdown("lifetime:0:full")?.html.length ?? 0
            document.body.dataset.settled = "true"
            channel.port1.close()
            channel.port2.close()
          }

          channel.port2.postMessage(null)
        }}
      >
        Continue
      </button>
      <Show when={admitted()}>
        <Show when={!leaving()}>
          <Markdown
            id={scenario === "shared" ? "departing" : "survivor"}
            text={answer}
            cacheKey="lifetime"
            deferUntilReady
          />
        </Show>
        <Show when={scenario === "shared"}>
          <Markdown id="survivor" text={answer} cacheKey="lifetime" deferUntilReady />
        </Show>
        <Show when={leaving() && scenario === "leave"}>
          <Markdown id="destination" text={destination} cacheKey="destination" deferUntilReady />
        </Show>
      </Show>
    </main>
  )
}, document.getElementById("root")!)

declare global {
  interface Window {
    markdownLifetime: Omit<typeof stats, "cacheChars"> & { cacheChars?: number; cacheBytes?: number }
  }
}

Object.defineProperty(window, "markdownLifetime", { value: stats })

import { benchmark, expect } from "../../../app/e2e/performance/benchmark"

for (const scenario of ["mounted", "leave", "shared"]) {
  benchmark(`completed Markdown: ${scenario}`, async ({ page, report }) => {
    const errors: string[] = []
    page.on("pageerror", (error) => errors.push(error.message))
    await page.goto(`/?scenario=${scenario}`)
    await page.getByRole("button", { name: "Admit answer" }).click()
    await expect(page.getByRole("button", { name: "Continue", exact: true })).toBeEnabled()
    const session = await page.context().newCDPSession(page)
    await session.send("Performance.enable")
    const before = await session.send("Performance.getMetrics")
    await page.getByRole("button", { name: "Continue", exact: true }).click()
    await expect(page.locator("body")).toHaveAttribute("data-ready", "true")
    await expect(page.locator("body")).toHaveAttribute("data-settled", "true")
    const after = await session.send("Performance.getMetrics")
    const stats = await page.evaluate(() => window.markdownLifetime)
    // The frozen initial baseline used a byte label for this character count.
    stats.cacheChars ??= stats.cacheBytes ?? 0
    delete stats.cacheBytes
    expect(stats.requests).toBe(1)
    expect(stats.responses).toBe(1)
    expect(stats.ready).toBeGreaterThan(stats.released)
    expect(stats.settled).toBeGreaterThan(stats.released)
    expect(errors).toEqual([])

    if (scenario === "leave") {
      await expect(page.locator("#survivor")).toHaveCount(0)
      await expect(page.getByRole("heading", { name: "Current destination" })).toBeVisible()

      if (process.env.MARKDOWN_ASSERT_DISPOSAL === "1") expect(stats.cacheChars).toBe(0)
    } else {
      await expect(page.locator("#survivor pre code")).toHaveCount(stats.fences)
      await expect(page.locator("#survivor")).toContainText("Review complete.")
      expect(stats.cacheChars).toBeGreaterThan(0)

      if (scenario === "shared") await expect(page.locator("#departing")).toHaveCount(0)
    }

    const value = (data: typeof after, name: string) => data.metrics.find((item) => item.name === name)!.value
    const retained = process.env.MARKDOWN_RETAINED === "1"

    if (retained) await session.send("HeapProfiler.collectGarbage")
    const heap = await session.send("Runtime.getHeapUsage")
    report(
      {
        ...stats,
        readyMs: stats.ready - stats.released,
        settledMs: stats.settled - stats.released,
        taskMs: (value(after, "TaskDuration") - value(before, "TaskDuration")) * 1000,
        scriptMs: (value(after, "ScriptDuration") - value(before, "ScriptDuration")) * 1000,
        usedHeapBytes: heap.usedSize,
      },
      { scenario, retained, build: process.env.MARKDOWN_BUILD_DIR, revision: process.env.MARKDOWN_REVISION },
    )

    if (process.env.MARKDOWN_SCREENSHOT)
      await page.screenshot({ path: `${process.env.MARKDOWN_SCREENSHOT}/${scenario}.png` })
    await session.detach()
  })
}

import { deflateSync } from "node:zlib"

const size = 16

const frameRate = 30

const duration = 1.2

const frameCount = frameRate * duration

const opacity = [0.2, 0.5, 0.75, 1]

// Each digit selects one dot opacity for one of the eight source key poses.
const poses = [
  "0000000000003000031000321",
  "0000000000003000320032100",
  "0000000000333002100010000",
  "3000023000123000000000000",
  "1230001300003000000000000",
  "0012300230003000000000000",
  "0000100022003330000000000",
  "0000000000003330002200001",
].map((pose) => Array.from(pose, (value) => opacity[Number(value)]))

const crcTable = Array.from({ length: 256 }, (_, value) =>
  Array.from({ length: 8 }).reduce<number>((crc) => ((crc & 1) !== 0 ? 0xedb88320 ^ (crc >>> 1) : crc >>> 1), value),
)

await Bun.write(new URL("../src/v2/components/session-progress-indicator-v2-1x.png", import.meta.url), apng(1))

function apng(scale: number) {
  const frameSize = size * scale
  const header = Buffer.alloc(13)
  header.writeUInt32BE(frameSize, 0)
  header.writeUInt32BE(frameSize, 4)
  header[8] = 8
  header[9] = 6

  const animation = Buffer.alloc(8)
  animation.writeUInt32BE(frameCount, 0)
  animation.writeUInt32BE(0, 4)
  const chunks = [chunk("IHDR", header), chunk("acTL", animation)]
  const sequence = { value: 0 }

  Array.from({ length: frameCount }, (_, frame) => {
    const control = Buffer.alloc(26)
    control.writeUInt32BE(sequence.value++, 0)
    control.writeUInt32BE(frameSize, 4)
    control.writeUInt32BE(frameSize, 8)
    control.writeUInt16BE(1, 20)
    control.writeUInt16BE(frameRate, 22)
    chunks.push(chunk("fcTL", control))

    const data = deflateSync(pixels(scale, frame), { level: 9 })

    if (frame === 0) {
      chunks.push(chunk("IDAT", data))

      return
    }

    const frameData = Buffer.alloc(data.length + 4)
    frameData.writeUInt32BE(sequence.value++, 0)
    data.copy(frameData, 4)
    chunks.push(chunk("fdAT", frameData))
  })

  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), ...chunks, chunk("IEND", Buffer.alloc(0))])
}

function pixels(scale: number, frame: number) {
  const frameSize = size * scale
  const stride = frameSize * 4 + 1
  const pixels = Buffer.alloc(stride * frameSize)
  const progress = (frame / frameCount) * poses.length
  const current = Math.floor(progress)
  const next = (current + 1) % poses.length
  const mix = easeOut(progress - current)

  Array.from({ length: frameSize }, (_, y) => (pixels[y * stride] = 0))
  poses[current].forEach((value, index) => {
    draw(
      pixels,
      stride,
      (1 + (index % 5) * 3) * scale,
      (1 + Math.floor(index / 5) * 3) * scale,
      3 * scale,
      value + (poses[next][index] - value) * mix,
    )
  })

  return pixels
}

function draw(pixels: Buffer, stride: number, x: number, y: number, size: number, opacity: number) {
  const left = Math.floor(x)
  const top = Math.floor(y)
  const right = Math.ceil(x + size)
  const bottom = Math.ceil(y + size)

  Array.from({ length: bottom - top }, (_, row) => top + row).forEach((py) =>
    Array.from({ length: right - left }, (_, column) => left + column).forEach((px) => {
      const coverageX = Math.max(0, Math.min(px + 1, x + size) - Math.max(px, x))
      const coverageY = Math.max(0, Math.min(py + 1, y + size) - Math.max(py, y))
      const offset = py * stride + 1 + px * 4
      pixels[offset] = 255
      pixels[offset + 1] = 255
      pixels[offset + 2] = 255
      pixels[offset + 3] = Math.round(opacity * coverageX * coverageY * 255)
    }),
  )
}

function easeOut(progress: number) {
  const curve = (value: number, first: number, second: number) => {
    const inverse = 1 - value

    return 3 * inverse * inverse * value * first + 3 * inverse * value * value * second + value * value * value
  }

  const parameter = Array.from({ length: 16 }).reduce<[number, number]>(
    (range) => {
      const middle = (range[0] + range[1]) / 2

      return curve(middle, 0, 0.58) < progress ? [middle, range[1]] : [range[0], middle]
    },
    [0, 1],
  )

  return curve((parameter[0] + parameter[1]) / 2, 0, 1)
}

function chunk(type: string, data: Buffer) {
  const name = Buffer.from(type)
  const result = Buffer.alloc(data.length + 12)
  result.writeUInt32BE(data.length, 0)
  name.copy(result, 4)
  data.copy(result, 8)
  result.writeUInt32BE(crc32(Buffer.concat([name, data])), data.length + 8)

  return result
}

function crc32(data: Buffer) {
  return (
    (data.reduce<number>((crc, value) => crcTable[(crc ^ value) & 0xff] ^ (crc >>> 8), 0xffffffff) ^ 0xffffffff) >>> 0
  )
}

import { describe, expect, test } from "bun:test"
import { createTwoFilesPatch } from "diff"
import { patchFile, patchFileGroups, patchFiles } from "./apply-patch-file"
import { text } from "./session-diff"

describe("apply patch files", () => {
  test("parses current file diffs", () => {
    const file = patchFile({
      file: "src/session.ts",
      patch: "@@ -1 +1 @@\n-old\n+new",
      additions: 1,
      deletions: 1,
      status: "modified",
    })

    expect(file?.path).toBe("src/session.ts")
    expect(file?.type).toBe("update")
    expect(file?.view.additions).toBe(1)
  })

  test("keeps only current file diff values", () => {
    expect(
      patchFiles([
        { file: "src/new.ts", patch: "@@ -0,0 +1 @@\n+new", additions: 1, deletions: 0, status: "added" },
        { file: "src/old.ts", patch: "@@ -1 +0,0 @@\n-old", additions: 0, deletions: 1, status: "deleted" },
        { file: "src/incomplete.ts", additions: 1, deletions: 1, status: "modified" },
      ]).map((file) => ({ path: file.path, type: file.type })),
    ).toEqual([
      { path: "src/new.ts", type: "add" },
      { path: "src/old.ts", type: "delete" },
    ])
  })

  test("removes files without diff changes", () => {
    expect(
      patchFiles([
        { file: "src/changed.ts", patch: "@@ -1 +1 @@\n-old\n+new", additions: 1, deletions: 1, status: "modified" },
        { file: "src/unchanged.ts", patch: "", additions: 0, deletions: 0, status: "modified" },
      ]).map((file) => file.path),
    ).toEqual(["src/changed.ts"])
  })

  test("composes sequential complete patches for the same file", () => {
    const before = "const a = 1\nconst b = 2\n"
    const middle = "const a = 2\nconst b = 2\n"
    const after = "const a = 2\nconst b = 3\n"

    const patch = (oldText: string, newText: string) =>
      createTwoFilesPatch("a/src/a.ts", "b/src/a.ts", oldText, newText).replace(
        /^(?:Index: [^\n]+\n)?=+\n/,
        "diff --git a/src/a.ts b/src/a.ts\n",
      )

    const groups = patchFileGroups([
      {
        file: "src/a.ts",
        patch: patch(before, middle),
        additions: 1,
        deletions: 1,
        status: "modified",
      },
      {
        file: "src/a.ts",
        patch: patch(middle, after),
        additions: 1,
        deletions: 1,
        status: "modified",
      },
    ])

    expect(groups).toHaveLength(1)
    expect(groups[0]?.views).toHaveLength(1)
    expect(groups[0]?.additions).toBe(2)
    expect(groups[0]?.deletions).toBe(2)
  })

  test("keeps sequential partial patches under one file", () => {
    const groups = patchFileGroups([
      { file: "src/a.ts", patch: "@@ -1 +1 @@\n-a\n+b", additions: 1, deletions: 1, status: "modified" },
      { file: "src/a.ts", patch: "@@ -2 +2 @@\n-c\n+d", additions: 1, deletions: 1, status: "modified" },
    ])

    expect(groups).toHaveLength(1)
    expect(groups[0]?.views).toHaveLength(2)
  })

  test.each(["\n", "\r\n"])("preserves complete chained contents with %j line endings", (newline) => {
    const before = `const count = 1${newline}export { count }`
    const middle = `const count = 2${newline}export { count }`
    const after = `const count = 3${newline}export { count }`

    const groups = patchFileGroups(
      [before, middle].map((value, index) => ({
        file: "count.ts",
        patch: createTwoFilesPatch("count.ts", "count.ts", value, index === 0 ? middle : after, "", "", {
          context: Infinity,
        }),
        status: "modified",
        additions: 1,
        deletions: 1,
      })),
    )

    expect(groups).toHaveLength(1)
    expect(groups[0]).toMatchObject({ type: "update", additions: 1, deletions: 1 })
    expect(groups[0]!.views).toHaveLength(1)
    expect(text(groups[0]!.views[0]!, "deletions")).toBe(before)
    expect(text(groups[0]!.views[0]!, "additions")).toBe(after)
    expect(groups[0]!.views).toBe(groups[0]!.views)
  })

  test("uses net counts for complete patches instead of producer counts", () => {
    const groups = patchFileGroups([
      {
        file: "count.ts",
        patch: createTwoFilesPatch("count.ts", "count.ts", "one\n", "two\n", "", "", { context: Infinity }),
        status: "modified",
        additions: 4,
        deletions: 5,
      },
    ])

    expect(groups[0]).toMatchObject({ additions: 1, deletions: 1 })
    expect(groups[0]!.views[0]).toMatchObject({ additions: 1, deletions: 1 })
  })

  test("keeps disconnected complete patches separate and preserves file order", () => {
    const groups = patchFileGroups(
      [
        ["b.ts", "one\n", "two\n"],
        ["a.ts", "first\n", "second\n"],
        ["b.ts", "three\n", "four\n"],
      ].map(([file, before, after]) => ({
        file,
        patch: createTwoFilesPatch(file!, file!, before!, after!, "", "", { context: Infinity }),
        status: "modified",
        additions: 1,
        deletions: 1,
      })),
    )

    expect(groups.map((group) => group.path)).toEqual(["b.ts", "a.ts"])
    expect(groups[0]).toMatchObject({ additions: 2, deletions: 2 })
    expect(groups[0]!.views.map((view) => text(view, "additions"))).toEqual(["two\n", "four\n"])
  })

  test.each([
    ["", "created\n", "", "added", "deleted", "delete", 0, 0],
    ["original\n", "changed\n", "original\n", "modified", "modified", "update", 0, 0],
    ["", "created\n", "changed\n", "added", "modified", "add", 1, 0],
  ])("preserves chain status and cancellation %#", (before, middle, after, first, last, type, additions, deletions) => {
    const groups = patchFileGroups(
      [
        { before, after: middle, status: first },
        { before: middle, after, status: last },
      ].map((value) => ({
        file: "chain.ts",
        patch: createTwoFilesPatch("chain.ts", "chain.ts", value.before, value.after, "", "", { context: Infinity }),
        status: value.status,
        additions: 1,
        deletions: 1,
      })),
    )

    expect(groups[0]).toMatchObject({ type, additions, deletions })
    expect(groups[0]!.views).toHaveLength(1)
    expect(text(groups[0]!.views[0]!, "deletions")).toBe(before)
    expect(text(groups[0]!.views[0]!, "additions")).toBe(after)
  })
})

import type { FileDiffInfo } from "@opencode/client/promise"
import { completePatchContents, normalize, type ViewDiff } from "./session-diff"

type Kind = "add" | "update" | "delete"

export type ApplyPatchFile = {
  path: string
  type: Kind
  additions: number
  deletions: number
  view: ViewDiff
  contents?: { before: string; after: string }
}

export type ApplyPatchFileGroup = Omit<ApplyPatchFile, "view" | "contents"> & { views: ViewDiff[] }

export function changedFileDiff(value: unknown): value is FileDiffInfo {
  if (!value || typeof value !== "object") return false

  if (!("file" in value) || typeof value.file !== "string") return false

  if (!("patch" in value) || typeof value.patch !== "string") return false

  if (!("additions" in value) || typeof value.additions !== "number") return false

  if (!("deletions" in value) || typeof value.deletions !== "number") return false

  if (!("status" in value)) return false

  if (value.status !== "added" && value.status !== "deleted" && value.status !== "modified") return false

  return value.additions > 0 || value.deletions > 0
}

export function patchFile(value: unknown): ApplyPatchFile | undefined {
  if (!changedFileDiff(value)) return
  let view: ViewDiff | undefined

  return {
    path: value.file,
    type: value.status === "added" ? "add" : value.status === "deleted" ? "delete" : "update",
    additions: value.additions,
    deletions: value.deletions,
    get view() {
      return (view ??= normalize(value))
    },
    contents: completePatchContents(value.patch),
  }
}

export function patchFiles(value: unknown) {
  if (!Array.isArray(value)) return []

  return value.map(patchFile).filter((file): file is ApplyPatchFile => !!file)
}

export function patchFileGroups(value: unknown): ApplyPatchFileGroup[] {
  const groups = patchFiles(value).reduce((result, file) => {
    const files = result.get(file.path)

    if (files) files.push(file)

    if (!files) result.set(file.path, [file])

    return result
  }, new Map<string, ApplyPatchFile[]>())

  return [...groups].map(([path, files]) => {
    const first = files[0]!
    const last = files.at(-1)!
    const type = last.type === "delete" ? "delete" : first.type === "add" ? "add" : "update"

    const chained = files.every(
      (file, index) => !!file.contents && (index === 0 || files[index - 1]?.contents?.after === file.contents.before),
    )

    if (!chained) {
      return {
        path,
        type,
        additions: files.reduce((total, file) => total + file.additions, 0),
        deletions: files.reduce((total, file) => total + file.deletions, 0),
        views: files.map((file) => file.view),
      }
    }

    const view =
      files.length === 1
        ? first.view
        : normalize({
            file: path,
            before: first.contents!.before,
            after: last.contents!.after,
            status: type === "add" ? "added" : type === "delete" ? "deleted" : "modified",
            additions: 0,
            deletions: 0,
          })

    // Parsed hunks already contain net change counts, excluding unchanged context.
    const counts = view.fileDiff.hunks.reduce(
      (result, hunk) => ({
        additions: result.additions + hunk.additionLines,
        deletions: result.deletions + hunk.deletionLines,
      }),
      { additions: 0, deletions: 0 },
    )

    return {
      path,
      type,
      ...counts,
      views: [{ ...view, ...counts }],
    }
  })
}

import {
  createEffect,
  createMemo,
  For,
  Match,
  on,
  onCleanup,
  onMount,
  Show,
  Switch,
  type Accessor,
  type JSX,
} from "solid-js"
import { animate, type AnimationPlaybackControls } from "motion"
import { useI18n } from "@opencode/ui/context/i18n"
import { createStore } from "solid-js/store"
import { Collapsible } from "@opencode/ui/collapsible"
import type { IconProps } from "@opencode/ui/icon"
import { TextShimmer } from "@opencode/ui/text-shimmer"

export type TriggerTitle = {
  title: string
  titleClass?: string
  subtitle?: string
  subtitleClass?: string
  args?: string[]
  argsClass?: string
  action?: JSX.Element
}

const isTriggerTitle = (val: unknown): val is TriggerTitle => {
  if (typeof val !== "object" || val === null) return false

  if (typeof Node !== "undefined" && val instanceof Node) return false

  return "title" in val && typeof val.title === "string"
}

export interface BasicToolProps {
  icon: IconProps["name"]
  trigger: TriggerTitle | JSX.Element | ((open: Accessor<boolean>) => JSX.Element)
  children?: JSX.Element
  /** Declare known content without constructing lazy JSX to test its presence. */
  hasContent?: boolean
  status?: string
  hideDetails?: boolean
  defaultOpen?: boolean
  open?: boolean
  onOpenChange?: (open: boolean) => void
  forceOpen?: boolean
  allowOpenWhilePending?: boolean
  defer?: boolean
  locked?: boolean
  animated?: boolean
  rail?: boolean
  onSubtitleClick?: () => void
  onTriggerClick?: JSX.EventHandlerUnion<HTMLElement, MouseEvent>
  onTriggerKeyDown?: JSX.EventHandlerUnion<HTMLElement, KeyboardEvent>
  triggerHref?: string
  triggerAsLink?: boolean
  clickable?: boolean
  compact?: boolean
}

const SPRING = { type: "spring" as const, visualDuration: 0.35, bounce: 0 }

const deferredMounts: Array<{ active: boolean; fn: () => void }> = []

let deferredFrame: number | undefined

function flushDeferredMounts() {
  while (deferredMounts.length > 0) {
    // Timeline tools are mounted top-to-bottom, but the viewport starts at the latest turn.
    // Pop from the end so heavy default-open bodies near the bottom become interactive first.
    const item = deferredMounts.pop()!

    if (item.active) {
      deferredFrame = deferredMounts.length > 0 ? requestAnimationFrame(flushDeferredMounts) : undefined
      item.fn()

      return
    }
  }

  deferredFrame = undefined
}

function scheduleDeferredFlush() {
  if (deferredFrame !== undefined) return
  deferredFrame = requestAnimationFrame(() => {
    deferredFrame = requestAnimationFrame(flushDeferredMounts)
  })
}

function scheduleDeferredMount(fn: () => void) {
  const item = { active: true, fn }
  deferredMounts.push(item)
  scheduleDeferredFlush()

  return () => {
    item.active = false
  }
}

function scheduleFrameMount(fn: () => void) {
  const frame = requestAnimationFrame(fn)

  return () => cancelAnimationFrame(frame)
}

export function BasicTool(props: BasicToolProps) {
  const [state, setState] = createStore({
    open: props.defaultOpen ?? false,
    ready: !props.defer && (props.defaultOpen ?? false),
  })

  const open = () => props.open ?? state.open
  const ready = () => state.ready
  const pending = () => props.status === "streaming" || props.status === "running"
  const hasChildren = () => props.hasContent ?? (props.defer ? "children" in props : props.children)

  const triggerContent = createMemo(() => {
    const value = props.trigger

    return typeof value === "function" ? value(open) : value
  })

  const triggerTitle = createMemo(() => {
    const value = triggerContent()

    return isTriggerTitle(value) ? value : undefined
  })

  let cancelReady: (() => void) | undefined

  const cancel = () => {
    cancelReady?.()
    cancelReady = undefined
  }

  const scheduleReady = (initial = false) => {
    cancel()
    cancelReady = (initial ? scheduleDeferredMount : scheduleFrameMount)(() => {
      cancelReady = undefined

      if (!open()) return
      setState("ready", true)
    })
  }

  onCleanup(cancel)

  onMount(() => {
    if (props.defer && open()) scheduleReady(true)
  })

  const setOpen = (value: boolean) => {
    if (props.open === undefined) setState("open", value)
    props.onOpenChange?.(value)
  }

  createEffect(() => {
    if (!props.forceOpen) return

    if (open()) return
    setOpen(true)
  })

  createEffect(
    on(
      open,
      (value) => {
        if (!props.defer) return

        if (!value) {
          cancel()
          setState("ready", false)

          return
        }

        scheduleReady()
      },
      { defer: true },
    ),
  )

  // Animated height for collapsible open/close
  let contentRef: HTMLDivElement | undefined
  let heightAnim: AnimationPlaybackControls | undefined
  const initialOpen = open()

  createEffect(
    on(
      open,
      (isOpen) => {
        if (!props.animated || !contentRef) return
        heightAnim?.stop()

        if (isOpen) {
          contentRef.style.overflow = "hidden"
          heightAnim = animate(contentRef, { height: "auto" }, SPRING)
          void heightAnim.finished.then(() => {
            if (!contentRef || !open()) return
            contentRef.style.overflow = "visible"
            contentRef.style.height = "auto"
          })
        } else {
          contentRef.style.overflow = "hidden"
          heightAnim = animate(contentRef, { height: "0px" }, SPRING)
        }
      },
      { defer: true },
    ),
  )

  onCleanup(() => {
    heightAnim?.stop()
  })

  const handleOpenChange = (value: boolean) => {
    if (pending() && !props.allowOpenWhilePending) return

    if (props.locked && !value) return
    setOpen(value)
  }

  const trigger = () => (
    <div
      data-component="tool-trigger"
      data-clickable={props.clickable ? "true" : undefined}
      data-hide-details={props.hideDetails ? "true" : undefined}
    >
      <div data-slot="basic-tool-tool-trigger-content">
        <div data-slot="basic-tool-tool-info">
          <Switch>
            <Match when={triggerTitle()}>
              {(title) => (
                <div data-slot="basic-tool-tool-info-structured">
                  <div data-slot="basic-tool-tool-info-main">
                    <span
                      data-slot="basic-tool-tool-title"
                      classList={{
                        [title().titleClass ?? ""]: !!title().titleClass,
                      }}
                    >
                      <TextShimmer text={title().title} active={pending()} />
                    </span>
                    <Show when={!pending() || title().subtitle || title().args?.length}>
                      <Show when={title().subtitle}>
                        <span
                          data-slot="basic-tool-tool-subtitle"
                          classList={{
                            [title().subtitleClass ?? ""]: !!title().subtitleClass,
                            clickable: !!props.onSubtitleClick,
                          }}
                          onClick={(e) => {
                            if (props.onSubtitleClick) {
                              e.stopPropagation()
                              props.onSubtitleClick()
                            }
                          }}
                        >
                          {title().subtitle}
                        </span>
                      </Show>
                      <Show when={title().args?.length}>
                        <For each={title().args}>
                          {(arg) => (
                            <span
                              data-slot="basic-tool-tool-arg"
                              classList={{
                                [title().argsClass ?? ""]: !!title().argsClass,
                              }}
                            >
                              {arg}
                            </span>
                          )}
                        </For>
                      </Show>
                    </Show>
                  </div>
                  <Show when={!pending() && title().action}>
                    <span data-slot="basic-tool-tool-action">{title().action}</span>
                  </Show>
                </div>
              )}
            </Match>
            <Match when={true}>{triggerContent() as JSX.Element}</Match>
          </Switch>
        </div>
      </div>
      <Show when={hasChildren() && !props.hideDetails && !props.locked && (!pending() || props.allowOpenWhilePending)}>
        <Collapsible.Arrow />
      </Show>
    </div>
  )

  return (
    <Collapsible
      open={open()}
      onOpenChange={props.locked ? undefined : handleOpenChange}
      class="tool-collapsible"
      data-compact={props.compact ? "true" : undefined}
      data-rail={props.rail === false ? "false" : undefined}
    >
      <Show
        when={!props.locked && (props.triggerAsLink || props.triggerHref)}
        fallback={
          <Show
            when={!props.locked}
            fallback={
              <div
                data-slot="collapsible-trigger"
                data-locked
                data-hide-details={props.hideDetails ? "true" : undefined}
              >
                {trigger()}
              </div>
            }
          >
            <Collapsible.Trigger
              data-hide-details={props.hideDetails ? "true" : undefined}
              onClick={props.onTriggerClick}
            >
              {trigger()}
            </Collapsible.Trigger>
          </Show>
        }
      >
        <Collapsible.Trigger
          as="a"
          href={props.triggerHref}
          role={!props.triggerHref && props.clickable ? "button" : undefined}
          tabIndex={!props.triggerHref && props.clickable ? 0 : undefined}
          data-hide-details={props.hideDetails ? "true" : undefined}
          onClick={props.onTriggerClick}
          onKeyDown={props.onTriggerKeyDown}
        >
          {trigger()}
        </Collapsible.Trigger>
      </Show>
      <Show when={props.animated && hasChildren() && !props.hideDetails}>
        <div
          ref={contentRef}
          data-slot="collapsible-content"
          data-animated
          style={{
            height: initialOpen ? "auto" : "0px",
            overflow: initialOpen ? "visible" : "hidden",
          }}
        >
          <Show when={!props.defer || ready()}>{props.children}</Show>
        </div>
      </Show>
      <Show when={!props.animated && hasChildren() && !props.hideDetails}>
        <Show
          when={props.locked && open() && !props.defer}
          fallback={
            <Collapsible.Content>
              <Show when={!props.defer || ready()}>{props.children}</Show>
            </Collapsible.Content>
          }
        >
          <div data-slot="collapsible-content" data-expanded="">
            {props.children}
          </div>
        </Show>
      </Show>
    </Collapsible>
  )
}

function label(input: Record<string, unknown> | undefined) {
  const keys = ["description", "query", "url", "path", "pattern", "name"]

  return keys.map((key) => input?.[key]).find((value): value is string => typeof value === "string" && value.length > 0)
}

function args(input: Record<string, unknown> | undefined) {
  if (!input) return []
  const skip = new Set(["description", "query", "url", "path", "pattern", "name"])

  return Object.entries(input)
    .filter(([key]) => !skip.has(key))
    .flatMap(([key, value]) => {
      if (typeof value === "string") return [`${key}=${value}`]

      if (typeof value === "number") return [`${key}=${value}`]

      if (typeof value === "boolean") return [`${key}=${value}`]

      return []
    })
    .slice(0, 3)
}

export function GenericTool(props: {
  tool: string
