import type { MarkdownToken } from "./markdown-worker-protocol"

export type RenderedCodeState = {
  language: string
  generation: number
  stableCount: number
  unstable: MarkdownToken[]
  raw: string
}

export function shouldResetCodeTokens(
  previous: RenderedCodeState | undefined,
  next: { language: string; generation: number; stableCount: number; raw: string },
) {
  return (
    !previous ||
    previous.language !== next.language ||
    previous.generation !== next.generation ||
    next.stableCount < previous.stableCount ||
    !next.raw.startsWith(previous.raw)
  )
}

import { isLineRangeHash, parsePathLineSuffix } from "@opencode/util/path"
import type { ReadMarkdownImage } from "../context/markdown"

export function localImagePath(source: string) {
  // Marked percent-encodes image sources, so `C:\tmp\chart.png` arrives as `C:%5Ctmp%5Cchart.png`.
  const value = source.trim().replace(/\\|%5c/gi, "/")

  if (!value || /[\u0000-\u001f\u007f]/.test(value) || value.startsWith("//")) return

  if (/^file:/i.test(value)) {
    if (!URL.canParse(value)) return
    const url = new URL(value)

    if (url.hostname && url.hostname !== "localhost") return

    return decodePath(url.pathname.replace(/^\/([a-z]:\/)/i, "$1"))
  }

  if (/^[a-z][a-z\d+.-]*:/i.test(value) && !/^[a-z]:\//i.test(value)) return

  return decodePath(value)
}

/**
 * A link is local when it names a file on disk instead of a web resource. Fragment-only and
 * query-only hrefs stay in-page; mailto and other schemes stay external. Line-range fragments
 * such as `#L42` and `#L42-L58` stay attached so the file viewer can select the target lines.
 */
export function localLinkPath(href: string) {
  const value = href.trim()

  if (!value || value.startsWith("#") || value.startsWith("?")) return

  const hashIndex = value.indexOf("#")
  const hash = hashIndex === -1 ? "" : value.slice(hashIndex)
  const target = (value.split(/[?#]/, 1)[0] ?? "").replace(/\\|%5c/gi, "/")
  // `app.tsx:42` is a file and line, not a URL scheme. The `.` or `/` keeps `tel:5551234` external.
  const cited = parsePathLineSuffix(target)
  const line = cited.path !== target && /[./]/.test(cited.path) ? cited : undefined
  const base = localImagePath(line?.path ?? target)

  if (!base) return

  if (line?.selection) {
    const range = line.selection.end === line.selection.start ? "" : `-L${line.selection.end}`

    return `${base}#L${line.selection.start}${range}`
  }

  return `${base}${isLineRangeHash(hash) ? hash : ""}`
}

function decodePath(value: string) {
  try {
    const path = decodeURIComponent(value)

    if (/[\u0000-\u001f\u007f]/.test(path) || path.startsWith("//") || path.startsWith("\\\\")) return

    return path
  } catch {
    return
  }
}

type ImageEntry = { controller: AbortController; result: Promise<string | undefined>; url?: string }

export function createMarkdownImages(read: ReadMarkdownImage) {
  const entries = new Map<string, ImageEntry>()

  return {
    update(root: HTMLElement) {
      const images = Array.from(root.querySelectorAll<HTMLImageElement>("img[data-local-image]"))
      const paths = new Set(images.map((image) => image.dataset.localImage))
      entries.forEach((entry, path) => {
        if (paths.has(path)) return
        entry.controller.abort()

        if (entry.url) URL.revokeObjectURL(entry.url)
        entries.delete(path)
      })
      images.forEach((image) => {
        const path = image.dataset.localImage

        if (!path) return
        const existing = entries.get(path)

        const entry: ImageEntry = existing ?? {
          controller: new AbortController(),
          result: Promise.resolve(undefined),
        }

        if (!existing) {
          entries.set(path, entry)
          entry.result = read(path, entry.controller.signal)
            .then(async (blob) => {
              if (!blob || entry.controller.signal.aborted) return

              // SVG documents must not inherit the app origin if opened outside the image element.
              if (blob.type === "image/svg+xml")
                return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(await blob.text())}`
              entry.url = URL.createObjectURL(blob)

              return entry.url
            })
            .catch(() => undefined)
        }

        void entry.result.then((url) => {
          if (!url || entry.controller.signal.aborted || !root.contains(image) || image.dataset.localImage !== path)
            return
          image.src = url
        })
      })
    },
    dispose() {
      entries.forEach((entry) => {
        entry.controller.abort()

        if (entry.url) URL.revokeObjectURL(entry.url)
      })
      entries.clear()
    },
  }
}

let loaded: ReturnType<typeof loadMermaid> | undefined

let sequence = 0

export async function renderMermaidSvg(source: string) {
  const mermaid = await (loaded ??= loadMermaid())

  if (!(await mermaid.parse(source, { suppressErrors: true }))) return

  return (await mermaid.render(`markdown-mermaid-${sequence++}`, source)).svg
}

async function loadMermaid() {
  const { default: mermaid } = await import("mermaid")
  mermaid.initialize({
    startOnLoad: false,
    securityLevel: "strict",
    theme: document.documentElement.dataset.colorScheme === "light" ? "default" : "dark",
    flowchart: { htmlLabels: false },
  })

  return mermaid
}

import type { Block, Projection } from "./markdown-stream"

export function completedProjection(text: string): Projection {
  return { text, blocks: [{ raw: text, src: text, mode: "full" }] }
}

export function canReusePendingBlock(current: Pick<Block, "mode" | "raw"> | undefined, next: Block) {
  if (!current || current.mode !== next.mode) return false

  if (next.mode === "code" || next.mode === "live") return next.raw.startsWith(current.raw)

  return current.raw === next.raw
}

// Generated session IDs have a 26-character alphanumeric suffix. Require a complete token
// so a partially streamed ID, an identifier suffix, or a path does not become a link.
const sessionID = /(?<![A-Za-z0-9_])ses_[A-Za-z0-9]{26}(?![A-Za-z0-9_])/g

const exactSessionID = /^ses_[A-Za-z0-9]{26}$/

export function markSessionLinks(root: HTMLElement) {
  if (!root.textContent?.includes("ses_")) return

  // The worker's escaped-raw fallback has no markdown elements; linking its text
  // would turn IDs inside still-unparsed fenced code into buttons.
  if (!root.querySelector("p, li, blockquote, td, th, h1, h2, h3, h4, h5, h6")) return

  root.querySelectorAll("code").forEach((code) => {
    if (code.closest("pre, a, button") || !exactSessionID.test(code.textContent ?? "")) return
    const link = sessionButton(code.textContent!)
    code.replaceWith(link)
    link.replaceChildren(code)
  })

  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT)
  const nodes: Text[] = []

  while (walker.nextNode()) {
    const node = walker.currentNode as Text

    if (node.parentElement?.closest("a, button, code, pre")) continue

    if (node.data.includes("ses_")) nodes.push(node)
  }

  nodes.forEach((node) => {
    const matches = [...node.data.matchAll(sessionID)]

    if (!matches.length) return
    const fragment = document.createDocumentFragment()
    let start = 0
    matches.forEach((match) => {
      fragment.append(node.data.slice(start, match.index), sessionButton(match[0]))
      start = match.index + match[0].length
    })
    fragment.append(node.data.slice(start))
    node.replaceWith(fragment)
  })
}

function sessionButton(id: string) {
  const button = document.createElement("button")
  button.type = "button"
  button.className = "markdown-session-link"
  button.dataset.sessionId = id
  button.textContent = id

  return button
}

export function setupSessionLinks(root: HTMLElement, open: () => ((id: string) => void) | undefined) {
  const click = (event: MouseEvent) => {
    if (event.defaultPrevented || !(event.target instanceof Element)) return
    const button = event.target.closest("button[data-session-id]")

    if (!(button instanceof HTMLButtonElement) || !root.contains(button)) return
    const handler = open()

    if (!handler) return
    event.stopPropagation()
    handler(button.dataset.sessionId!)
  }

  root.addEventListener("click", click)

  return () => root.removeEventListener("click", click)
}

