type RenderedBlock =
  | (MarkdownCacheEntry & { key: string; mode: Exclude<Block["mode"], "code"> })
  | {
      key: string
      mode: "code"
      raw: string
      hash: string
      language: string
      complete: boolean
      generation: number
      stable: MarkdownToken[]
      unstable: MarkdownToken[]
    }

type RenderResult = {
  text: string
  blocks: RenderedBlock[]
  ready: boolean
}

const renderedCodeTokens = new WeakMap<HTMLDivElement, RenderedCodeState>()

const renderedMarkdown = new WeakMap<
  HTMLDivElement,
  { renderer: ReturnType<typeof createMarkdownRenderer>; raw: string }
>()

function escape(text: string) {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;")
}

function fallback(markdown: string) {
  return escape(markdown).replace(/\r\n?/g, "\n").replace(/\n/g, "<br>")
}

async function code(text: string, language: string | undefined, key: string, complete = false) {
  try {
    const result = await highlightStreamingCode(key, text, language ?? "text", complete)

    return {
      language: result.language,
      generation: result.generation,
      stable: result.stable,
      unstable: result.unstable,
    }
  } catch (error) {
    if (
      !(error instanceof MarkdownWorkerDisposedError) &&
      !(error instanceof MarkdownWorkerSupersededError) &&
      !(error instanceof MarkdownWorkerUnavailableError)
    )
      console.error("Markdown highlighting worker failed", error)

    const fallbackToken: MarkdownToken = [text, ""]

    return { language: language ?? "text", generation: 0, stable: [], unstable: [fallbackToken] }
  }
}

type CopyLabels = {
  copy: string
  copied: string
}

type CopyButtonState = {
  setLabels: Setter<CopyLabels>
  setCopied: Setter<boolean>
  dispose: () => void
}

const copyButtonState = new WeakMap<HTMLElement, CopyButtonState>()

const urlPattern = /^https?:\/\/[^\s<>()`"']+$/

function codeUrl(text: string) {
  const href = text.trim().replace(/[),.;!?]+$/, "")

  if (!urlPattern.test(href)) return

  try {
    const url = new URL(href)

    return url.toString()
  } catch {
    return
  }
}

function createCopyButton(labels: CopyLabels) {
  const host = document.createElement("div")
  host.setAttribute("data-slot", "markdown-copy-button")

  const state: Partial<CopyButtonState> = {}

  const dispose = render(() => {
    const [labelState, setLabels] = createSignal(labels, { equals: false })
    const [copied, setCopied] = createSignal(false)
    state.setLabels = setLabels
    state.setCopied = setCopied

    return <MarkdownCopyButton labels={labelState()} copied={copied()} />
  }, host)

  state.dispose = dispose
  // SAFETY: `render` runs its function synchronously, so both setters are assigned before this line.
  copyButtonState.set(host, state as CopyButtonState)

  return host
}

function MarkdownCopyButton(props: { labels: CopyLabels; copied: boolean }) {
  const label = () => (props.copied ? props.labels.copied : props.labels.copy)

  return (
    <Tooltip placement="top" value={label()}>
      <IconButton
        type="button"
        size="normal"
        variant="ghost-muted"
        aria-label={label()}
        icon={
          <>
            <Icon name="outline-copy" data-copy-icon />
            <Icon name="check" data-check-icon />
          </>
        }
      />
    </Tooltip>
  )
}

function setCopyState(host: HTMLElement, labels: CopyLabels, copied: boolean) {
  const state = copyButtonState.get(host)
  state?.setLabels(labels)
  state?.setCopied(copied)

  if (copied) {
    host.setAttribute("data-copied", "true")

    return
  }

  host.removeAttribute("data-copied")
}

function disposeCopyButton(host: HTMLElement) {
  copyButtonState.get(host)?.dispose()
  copyButtonState.delete(host)
}

function disposeCopyButtons(root: Element) {
  const hosts = [
    ...(root instanceof HTMLElement && root.getAttribute("data-slot") === "markdown-copy-button" ? [root] : []),
    ...Array.from(root.querySelectorAll('[data-slot="markdown-copy-button"]')).filter(
      (el): el is HTMLElement => el instanceof HTMLElement,
    ),
  ]

  hosts.forEach(disposeCopyButton)
}

function disposeRenderedMarkdown(root: Element) {
  const blocks = [
    ...(root instanceof HTMLDivElement && root.hasAttribute("data-markdown-block") ? [root] : []),
    ...Array.from(root.querySelectorAll<HTMLDivElement>("[data-markdown-block]")),
  ]

  blocks.forEach((block) => {
    renderedMarkdown.get(block)?.renderer.dispose()
    renderedMarkdown.delete(block)
  })
}

const shellLanguages = new Set(["bash", "sh", "shell", "zsh", "fish", "console", "terminal"])

function codeKind(language: string | undefined) {
  const value = language?.toLowerCase()

  if (!value) return

  if (shellLanguages.has(value)) return "shell"
}

function applyCodeMetadata(wrapper: HTMLElement, language: string | undefined) {
  if (language) wrapper.dataset.language = language
  else delete wrapper.dataset.language

  const kind = codeKind(language)

  if (kind) wrapper.dataset.codeKind = kind
  else delete wrapper.dataset.codeKind
}

function decorateMermaid(wrapper: HTMLElement, code: HTMLElement, complete: boolean) {
  if (!code.classList.contains("language-mermaid")) {
    clearMermaid(wrapper)

    return
  }

  const source = code.textContent ?? ""

  if (!source) return
  const diagram = wrapper.querySelector('[data-component="markdown-mermaid"]') ?? document.createElement("div")
  diagram.setAttribute("data-component", "markdown-mermaid")

  if (!diagram.parentElement) wrapper.appendChild(diagram)
  wrapper.dataset.mermaidPending = "true"
  const input = complete ? source : source.slice(0, source.lastIndexOf("\n") + 1)

  if (!input) return
  const attempt = `${complete ? "complete" : "streaming"}:${input.length}`

  if (wrapper.dataset.mermaidAttempt === attempt) return
  wrapper.dataset.mermaidAttempt = attempt
  void renderMermaidSvg(input)
    .then((svg) => {
      if (!svg) {
        if (complete && code.textContent === source) clearMermaid(wrapper)

        return
      }

      if (!(code.textContent ?? "").startsWith(input)) return
      diagram.innerHTML = svg
      delete wrapper.dataset.mermaidPending
      wrapper.dataset.mermaidReady = "true"
    })
    .catch(() => {
      if (!complete || code.textContent !== source) return
      clearMermaid(wrapper)
    })
}

function clearMermaid(wrapper: HTMLElement) {
  delete wrapper.dataset.mermaidAttempt
  delete wrapper.dataset.mermaidPending
  delete wrapper.dataset.mermaidReady
  wrapper.querySelector('[data-component="markdown-mermaid"]')?.remove()
}

function markCodeLinks(root: HTMLDivElement) {
  const codeNodes = Array.from(root.querySelectorAll(":not(pre) > code"))

  for (const code of codeNodes) {
    const href = codeUrl(code.textContent ?? "")

    const parentLink =
      code.parentElement instanceof HTMLAnchorElement &&
      code.parentElement.classList.contains("external-link") &&
      !code.parentElement.hasAttribute("data-local-link")
        ? code.parentElement
        : null

    if (!href) {
      if (parentLink) parentLink.replaceWith(code)
      continue
    }

    if (parentLink) {
      parentLink.href = href
      continue
    }

    const link = document.createElement("a")
    link.href = href
    link.className = "external-link"
    link.target = "_blank"
    link.rel = "noopener noreferrer"
    code.parentNode?.replaceChild(link, code)
    link.appendChild(code)
  }
}

const publicFaviconHost = /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/

const privateFaviconSuffix = /\.(?:alt|example|internal|invalid|local|localhost|onion|test|ts\.net)$/

function markExternalLinkFavicons(root: HTMLDivElement) {
  root.querySelectorAll<HTMLAnchorElement>("a.external-link[href]").forEach((link) => {
    if (!link.textContent?.trim() || link.querySelector("img")) return

    if (!URL.canParse(link.href)) return
    const url = new URL(link.href)

    if (url.protocol !== "http:" && url.protocol !== "https:") return

    if (url.hostname.toLowerCase() === "github.com") return

    const favicon = document.createElement("span")
    favicon.className = "markdown-link-favicon"
    favicon.setAttribute("aria-hidden", "true")
    const host = url.hostname.toLowerCase()

    if (
      publicFaviconHost.test(host) &&
      !privateFaviconSuffix.test(host) &&
      host !== "home.arpa" &&
      !host.endsWith(".home.arpa")
    ) {
      const image = document.createElement("img")
      image.src = `https://www.google.com/s2/favicons?domain=${encodeURIComponent(url.host)}&sz=32`
      image.alt = ""
      image.setAttribute("data-markdown-favicon", "")
      image.width = 14
      image.height = 14
      image.decoding = "async"
      favicon.appendChild(image)
    }

    link.insertBefore(favicon, link.firstChild)
  })
}

function setupExternalLinkFavicons(root: HTMLDivElement) {
  const loaded = (event: Event) => {
    const image = event.target

    if (!(image instanceof HTMLImageElement) || !image.hasAttribute("data-markdown-favicon")) return

    if (image.naturalWidth > 0) image.dataset.loaded = ""
  }

  root.addEventListener("load", loaded, true)

  return () => root.removeEventListener("load", loaded, true)
}

// A path becomes a link once `localFileExists` says the file exists. A streaming block skips the check: its last code
// span may still be half written, and the block renders again once it completes.
function markInlineCode(
  source: HTMLDivElement,
  target: HTMLDivElement,
  live: boolean,
  localFileExists?: MarkdownLocalFileExists,
) {
  const checked = new Set<string>()

  for (const code of source.querySelectorAll<HTMLElement>(":not(pre) > code")) {
    delete code.dataset.inlineCodeKind
    const text = (code.textContent ?? "").trim()
    const kind = inlineCodeKind(text)

    if (kind === "url") code.dataset.inlineCodeKind = kind

    // Code inside a link already goes where the link does.
    if (kind !== "path" || live || !localFileExists || code.closest("a") || checked.has(text)) continue

    checked.add(text)
    void Promise.resolve(localFileExists(text))
      .then((exists) => {
        if (!exists) return
        target.querySelectorAll<HTMLElement>(":not(pre) > code").forEach((node) => {
          if (!node.closest("a") && (node.textContent ?? "").trim() === text) node.dataset.inlineCodeKind = "path"
        })
      })
      .catch(() => undefined)
  }
}

function localLinkTarget(target: EventTarget | null) {
  if (!(target instanceof Element)) return
  const link = target.closest("a[data-local-link]")

  if (link instanceof HTMLElement) return link.dataset.localLink
  // Bare inline paths such as `src/app.ts` open like links when the host can resolve them.
  const code = target.closest(':not(pre) > code[data-inline-code-kind="path"]')

  if (code instanceof HTMLElement && !code.closest("a")) return code.textContent?.trim() || undefined
}

function setupLocalLinks(root: HTMLDivElement, open: () => OpenMarkdownLocalFile | undefined) {
  const handleClick = (event: MouseEvent) => {
    if (event.defaultPrevented || event.button !== 0) return
    const path = localLinkTarget(event.target)

    if (!path) return
    const handler = open()

    if (!handler) return
    event.preventDefault()
    handler(path)
  }

  const handleKeyDown = (event: KeyboardEvent) => {
    if (event.key !== "Enter" || event.defaultPrevented) return

    if (!(event.target instanceof HTMLElement) || !event.target.matches("a[data-local-link]")) return
    const path = event.target.dataset.localLink
    const handler = open()

    if (!path || !handler) return
    event.preventDefault()
    handler(path)
  }

  root.addEventListener("click", handleClick)
  root.addEventListener("keydown", handleKeyDown)

  return () => {
    root.removeEventListener("click", handleClick)
    root.removeEventListener("keydown", handleKeyDown)
  }
}

function setupCodeCopy(root: HTMLDivElement, getLabels: () => CopyLabels) {
  const timeouts = new Map<HTMLElement, ReturnType<typeof setTimeout>>()

  const updateLabel = (button: HTMLElement) => {
    const labels = getLabels()
    const copied = button.getAttribute("data-copied") === "true"
    setCopyState(button, labels, copied)
  }

  const handleClick = async (event: MouseEvent) => {
    const target = event.target

    if (!(target instanceof Element)) return

    const button = target.closest('[data-slot="markdown-copy-button"]')

    if (!(button instanceof HTMLElement)) return
    const code = button.closest('[data-component="markdown-code"]')?.querySelector("code")
    const content = code?.textContent ?? ""

    if (!content) return
    const clipboard = navigator?.clipboard

    if (!clipboard) return
    await clipboard.writeText(content)
    const labels = getLabels()
    setCopyState(button, labels, true)
    const existing = timeouts.get(button)

    if (existing) clearTimeout(existing)
    const timeout = setTimeout(() => setCopyState(button, labels, false), 2000)
    timeouts.set(button, timeout)
  }

  const buttons = Array.from(root.querySelectorAll('[data-slot="markdown-copy-button"]'))

  for (const button of buttons) {
    if (button instanceof HTMLElement) updateLabel(button)
  }

  root.addEventListener("click", handleClick)

  return () => {
    root.removeEventListener("click", handleClick)

    for (const timeout of timeouts.values()) {
      clearTimeout(timeout)
    }

    disposeCopyButtons(root)
  }
}

function initialResult(
  text: string,
  key: string | undefined,
  projection: Projection,
  owner: string,
  deferUntilReady: boolean | undefined,
): RenderResult {
  if (!text) return { text, blocks: [], ready: true }
  const base = key ?? checksum(text)

  if (base) {
    const blocks = projection.blocks.flatMap((block, index) => {
      if (block.mode === "code") return []
      const cacheKey = `${base}:${index}:${block.mode}`
      const cached = block.mode === "full" ? getReadyMarkdown(block, cacheKey) : getCachedMarkdown(cacheKey)

      if (cached?.raw !== block.raw) return []

      if (block.mode !== "full") touchCachedMarkdown(cacheKey, cached)

      return [{ key: `${owner}:${cacheKey}`, mode: block.mode, ...cached }]
    })

    if (blocks.length === projection.blocks.length) return { text, blocks, ready: true }
  }

  if (deferUntilReady) return { text, blocks: [], ready: false }

  return {
    text,
    ready: false,
    blocks: [
      {
        key: "initial",
        mode: "full",
        raw: text,
        hash: checksum(text) ?? "",
        html: fallback(text),
      },
    ],
  }
}

function pendingProjection(text: string): Projection {
  return { text, blocks: text ? [{ raw: text, src: text, mode: "live" }] : [] }
}

export function Markdown(
  props: ComponentProps<"div"> & {
    text: string
    cacheKey?: string
    streaming?: boolean
    deferUntilReady?: boolean
    class?: string
    classList?: Record<string, boolean>
  },
) {
  const [local, others] = splitProps(props, ["text", "cacheKey", "streaming", "deferUntilReady", "class", "classList"])
  const i18n = useI18n()
  const markdown = useMarkdown()
  const previewImages = createImagePreview()
  const [root, setRoot] = createSignal<HTMLDivElement>()
  const owner = createUniqueId()
  const lifetime = new AbortController()
  const activeCodeKeys = new Set<string>()
  const completedCode = new Map<string, Extract<RenderedBlock, { mode: "code" }>>()
  let streamed = false

  const [projection] = createResource(
    () => {
      if (isServer) return
      const live = local.streaming ?? false

      if (live) streamed = true

      if (!live && !streamed) return

      return { key: owner, text: local.text, live }
    },
    (src) => projectMarkdown(src.key, src.text, src.live),
    { initialValue: pendingProjection("") },
  )

  const currentProjection = () => {
    if (!(local.streaming ?? false) && !streamed) return completedProjection(local.text)
    const value = projection.latest

    if (value?.text === local.text) return value

    if (value?.text) return value

    return pendingProjection(local.text)
  }

  const initial = initialResult(
    local.text,
    local.cacheKey,
    local.streaming ? pendingProjection(local.text) : completedProjection(local.text),
    owner,
    local.deferUntilReady,
  )

  const [html] = createResource(
    () => {
      if (isServer)
        return {
          text: local.text,
          key: local.cacheKey,
          projection: pendingProjection(local.text),
        }
      const value = !(local.streaming ?? false) && !streamed ? completedProjection(local.text) : projection.latest

      if (!value || value.text !== local.text) return

      return {
        text: local.text,
        key: local.cacheKey,
        projection: value,
      }
    },
    (src): RenderResult | Promise<RenderResult> => {
      if (isServer)
        return {
          text: src.text,
          ready: true,
          blocks: [
            {
              key: "server",
              mode: "full" as const,
              raw: src.text,
              hash: checksum(src.text) ?? "",
              html: fallback(src.text),
            },
          ],
        } satisfies RenderResult

      if (!src.text) return { text: src.text, blocks: [], ready: true } satisfies RenderResult

      if (!streamed && initial.ready && initial.text === src.text) return initial

      const base = src.key ?? checksum(src.text)

      return Promise.all(
        src.projection.blocks.map(async (block, index) => {
          const key = base ? `${base}:${index}:${block.mode}` : undefined
          const blockKey = markdownBlockKey(owner, src.key, index, block.mode)

          if (block.mode === "code") {
            const cached = completedCode.get(blockKey)

            if (block.complete && cached?.raw === block.raw) return cached
            const result = await code(block.src, block.language, blockKey, block.complete)

            const rendered = {
              key: blockKey,
              mode: block.mode,
              raw: block.raw,
              hash: String(block.raw.length),
              complete: !!block.complete,
              ...result,
            }

            if (block.complete) completedCode.set(blockKey, rendered)

            return rendered
          }

          const ready = block.mode === "full" ? getReadyMarkdown(block, key) : undefined

          return {
            key: blockKey,
            mode: block.mode,
            ...(ready ?? (await renderCachedMarkdown(block, key, lifetime.signal))),
          }
        }),
      )
        .then((blocks) => ({ text: src.text, blocks, ready: true }) satisfies RenderResult)
        .catch(
          () =>
            (lifetime.signal.aborted
              ? { text: src.text, blocks: [], ready: false }
              : {
                  text: src.text,
                  ready: true,
                  blocks: [
                    {
                      key: base ?? "fallback",
                      mode: "full" as const,
                      raw: src.text,
                      hash: checksum(src.text) ?? "",
                      html: fallback(src.text),
                    },
                  ],
                }) satisfies RenderResult,
        )
    },
    { initialValue: initial },
  )

  let copyCleanup: (() => void) | undefined
  let linkCleanup: (() => void) | undefined
  let faviconCleanup: (() => void) | undefined
  let sessionLinkCleanup: (() => void) | undefined
  let readImage: ReadMarkdownImage | undefined
  let images: ReturnType<typeof createMarkdownImages> | undefined

  createEffect(() => {
    const container = root()
    const result = html.latest ?? html()
    const projected = currentProjection()
    const content = local.text ? pendingBlocks(result, projected, local.cacheKey, owner, local.deferUntilReady) : []

    if (!container) return

    if (isServer) return

    if (readImage !== markdown?.readImage) {
      images?.dispose()
      readImage = markdown?.readImage
      images = readImage ? createMarkdownImages(readImage) : undefined
    }

    delete container.dataset.markdownReady

    if (content.length === 0) {
      disposeCopyButtons(container)
      disposeRenderedMarkdown(container)
      container.innerHTML = ""
      images?.update(container)

      if (result?.ready && result.text === local.text) container.dataset.markdownReady = ""

      return
    }

    const labels = {
      copy: i18n.t("ui.message.copy"),
      copied: i18n.t("ui.message.copied"),
    }

    const nextCodeKeys = new Set(content.filter((block) => block.mode === "code").map((block) => block.key))
    activeCodeKeys.forEach((key) => {
      if (!nextCodeKeys.has(key)) disposeCode(key)
    })
    activeCodeKeys.clear()
    nextCodeKeys.forEach((key) => activeCodeKeys.add(key))
    content.forEach((block, index) =>
      updateBlock(container, index, block, labels, !!markdown?.openSession, markdown?.localFileExists),
    )

    while (container.children.length > content.length) {
      const child = container.lastElementChild

      if (!child) break
      disposeCopyButtons(child)
      disposeRenderedMarkdown(child)
      child.remove()
    }

    images?.update(container)
    previewImages(container)
    container.querySelectorAll<HTMLImageElement>("img[data-markdown-favicon]").forEach((image) => {
      if (image.complete && image.naturalWidth > 0) image.dataset.loaded = ""
    })
    container
      .querySelectorAll<HTMLElement>('[data-slot="markdown-copy-button"]')
      .forEach((button) => setCopyState(button, labels, button.dataset.copied === "true"))

    if (!copyCleanup)
      copyCleanup = setupCodeCopy(container, () => ({
        copy: i18n.t("ui.message.copy"),
        copied: i18n.t("ui.message.copied"),
      }))

    if (!linkCleanup) linkCleanup = setupLocalLinks(container, () => markdown?.openLocalFile)

    if (!sessionLinkCleanup) sessionLinkCleanup = setupSessionLinks(container, () => markdown?.openSession)

    if (!faviconCleanup) faviconCleanup = setupExternalLinkFavicons(container)
    container.toggleAttribute("data-local-links", !!markdown?.openLocalFile)

    if (result?.ready && result.text === local.text) container.dataset.markdownReady = ""
  })

  onCleanup(() => {
    lifetime.abort()
    images?.dispose()

    if (copyCleanup) copyCleanup()

    if (linkCleanup) linkCleanup()

    if (sessionLinkCleanup) sessionLinkCleanup()

    if (faviconCleanup) faviconCleanup()
    const container = root()

    if (container) disposeRenderedMarkdown(container)

    if (streamed) disposeMarkdownProjection(owner)
    activeCodeKeys.forEach(disposeCode)
    completedCode.clear()
  })

  return (
    <div
      data-component="markdown"
      data-streaming={local.streaming ? "" : undefined}
      dir="auto"
      classList={{
        ...local.classList,
        [local.class ?? ""]: !!local.class,
      }}
      ref={setRoot}
      {...others}
    />
  )
}

function pendingBlocks(
  result: RenderResult | undefined,
  projection: Projection | undefined,
  cacheKey: string | undefined,
  owner: string,
  deferUntilReady: boolean | undefined,
) {
  if (!result) return []

  if (!projection || result.text === projection.text) return result.blocks

  if (deferUntilReady) return result.blocks
  const initial = result.blocks.length === 1 && result.blocks[0]?.key === "initial"

  return projection.blocks.map((block, index) => {
    const current = initial ? undefined : result.blocks[index]

    if (current && canReusePendingBlock(current, block)) return current
    const key = markdownBlockKey(owner, cacheKey, index, block.mode)

    if (block.mode !== "code")
      return { key, mode: block.mode, raw: block.raw, hash: String(block.raw.length), html: fallback(block.src) }

    const fallbackToken: MarkdownToken = [block.src, ""]

    return {
      key,
      mode: block.mode,
      raw: block.raw,
      hash: String(block.raw.length),
      language: block.language ?? "text",
      complete: !!block.complete,
      stable: [],
      generation: 0,
      unstable: [fallbackToken],
    }
  })
}

function disposeCode(key: string) {
  disposeStreamingCode(key)
}

function updateBlock(
  container: HTMLDivElement,
  index: number,
  block: RenderedBlock,
  labels: CopyLabels,
  sessionLinks: boolean,
  localFileExists?: MarkdownLocalFileExists,
) {
  const current = container.children[index]

  if (block.mode === "code") {
    updateCodeBlock(container, current, block, labels)

    return
  }

  const existing =
    current instanceof HTMLDivElement && current.dataset.markdownKey === block.key && !renderedCodeTokens.has(current)
      ? current
      : undefined

  if (existing?.dataset.markdownHash === block.hash) {
    // A block that finishes streaming keeps its DOM and the user's selection; only its file paths get checked now.
    if (existing.dataset.markdownMode === "live" && block.mode !== "live") {
      existing.dataset.markdownMode = block.mode
      markInlineCode(existing, existing, false, localFileExists)
    }

    return
  }

  const next = existing ?? document.createElement("div")
  next.dataset.markdownBlock = ""
  next.dataset.markdownKey = block.key
  next.dataset.markdownHash = block.hash
  next.dataset.markdownMode = block.mode
  next.style.display = "contents"
  const rendered = renderedMarkdown.get(next)
  // Keep live renderers in control of their DOM, including after completion.
  const source = rendered || block.mode === "live" ? document.createElement("div") : next

  if (source === next) disposeCopyButtons(next)
  source.innerHTML = block.html
  markInlineCode(source, next, block.mode === "live", localFileExists)
  markCodeLinks(source)

  if (sessionLinks) markSessionLinks(source)
  markExternalLinkFavicons(source)

  if (rendered) {
    rendered.renderer.update(source.innerHTML, block.mode === "live", rendered.raw !== block.raw)
    rendered.raw = block.raw

    return
  }

  if (block.mode === "live") {
    next.replaceChildren()
    renderedMarkdown.set(next, {
      renderer: createMarkdownRenderer(next, source.innerHTML, true),
      raw: block.raw,
    })
  }

  if (block.mode !== "live") {
    next.querySelectorAll<HTMLElement>("pre > code").forEach((code) => {
      const pre = code.parentElement!
      const wrapper = document.createElement("div")
      wrapper.dataset.component = "markdown-code"
      applyCodeMetadata(
        wrapper,
        Array.from(code.classList)
          .find((name) => name.startsWith("language-"))
          ?.slice(9),
      )
      pre.replaceWith(wrapper)
      wrapper.appendChild(pre)
      wrapper.appendChild(createCopyButton(labels))
      decorateMermaid(wrapper, code, true)
    })
  }

  if (existing) return

  if (!current) {
    container.appendChild(next)

    return
  }

  disposeCopyButtons(current)
  disposeRenderedMarkdown(current)
  current.replaceWith(next)
}

function updateCodeBlock(
  container: HTMLDivElement,
  current: Element | undefined,
  block: Extract<RenderedBlock, { mode: "code" }>,
  labels: CopyLabels,
) {
  const existing =
    current instanceof HTMLDivElement && current.dataset.markdownKey === block.key && renderedCodeTokens.has(current)
      ? current
      : undefined

  const next = existing ?? document.createElement("div")
  next.dataset.markdownBlock = ""
  next.dataset.markdownKey = block.key
  next.dataset.markdownHash = block.hash
  next.dataset.markdownComplete = block.complete ? "true" : "false"
  next.style.display = "contents"

  const code = existing?.querySelector("code")

  if (code instanceof HTMLElement) {
    const wrapper = code.closest('[data-component="markdown-code"]')

    if (wrapper instanceof HTMLElement) applyCodeMetadata(wrapper, block.language)
    code.className = `language-${block.language}`
    const previous = renderedCodeTokens.get(next)

    const reset = shouldResetCodeTokens(previous, {
      language: block.language,
      generation: block.generation,
      stableCount: block.stable.length,
      raw: block.raw,
    })

    const stableCount = reset ? 0 : previous!.stableCount
    const tail = [...block.stable.slice(stableCount), ...block.unstable]
    const prior = reset ? [] : previous!.unstable
    const prefix = prior.findIndex((token, index) => !sameToken(token, tail[index]))
    const keep = stableCount + (prefix < 0 ? Math.min(prior.length, tail.length) : prefix)

    while (code.children.length > keep) code.lastElementChild?.remove()
    tail
      .slice(keep - stableCount)
      .map(createTokenSpan)
      .forEach((span) => code.appendChild(span))
    renderedCodeTokens.set(next, {
      language: block.language,
      generation: block.generation,
      stableCount: block.stable.length,
      unstable: block.unstable,
      raw: block.raw,
    })

    if (wrapper instanceof HTMLElement) decorateMermaid(wrapper, code, block.complete)

    return
  }

  const wrapper = document.createElement("div")
  wrapper.setAttribute("data-component", "markdown-code")
  applyCodeMetadata(wrapper, block.language)
  const pre = document.createElement("pre")
  pre.className = "shiki OpenCode"
  const codeElement = document.createElement("code")
  codeElement.className = `language-${block.language}`
  ;[...block.stable, ...block.unstable].map(createTokenSpan).forEach((span) => codeElement.appendChild(span))
  pre.appendChild(codeElement)
  wrapper.appendChild(pre)
  wrapper.appendChild(createCopyButton(labels))
  decorateMermaid(wrapper, codeElement, block.complete)
  next.appendChild(wrapper)
  renderedCodeTokens.set(next, {
    language: block.language,
    generation: block.generation,
    stableCount: block.stable.length,
    unstable: block.unstable,
    raw: block.raw,
  })

  if (current) {
    disposeCopyButtons(current)
    disposeRenderedMarkdown(current)
    current.replaceWith(next)

    return
  }

  container.appendChild(next)
}

function sameToken(left: MarkdownToken, right: MarkdownToken | undefined) {
  return !!right && left[0] === right[0] && left[1] === right[1]
}

function createTokenSpan(token: MarkdownToken) {
  const span = document.createElement("span")
  span.setAttribute("style", token[1])
  span.textContent = token[0]

  return span
}

/// <reference lib="webworker" />

import { ShikiStreamTokenizer } from "@shikijs/stream"
import { createMarkdownParser } from "@opencode/ui/context/marked-parser"
import { OpenCodeTheme } from "@opencode/ui/context/marked-theme"
import {
  bundledLanguages,
  createHighlighter,
  getTokenStyleObject,
  stringifyTokenStyle,
  type BundledLanguage,
  type ThemedToken,
} from "shiki"
import type { MarkdownToken, MarkdownWorkerRequest, MarkdownWorkerResponse } from "./markdown-worker-protocol"
import { createLatestWorkerQueue } from "./markdown-worker-queue"
import { project, type Projection } from "./markdown-stream"

type Stream = {
  language: string
  source: string
  tokenizer: ShikiStreamTokenizer
}

const streams = new Map<string, Stream>()

const projections = new Map<string, Projection>()

let highlighter: ReturnType<typeof createHighlighter> | undefined

const highlightQueue = createLatestWorkerQueue<Extract<MarkdownWorkerRequest, { type: "highlight" }>>({
  run: highlight,
  supersede: (request) => post({ type: "superseded", id: request.id, key: request.key }),
  dispose: (key) => void streams.delete(key),
})

const projectQueue = createLatestWorkerQueue<Extract<MarkdownWorkerRequest, { type: "project" }>>({
  run: runProject,
  supersede: (request) => post({ type: "superseded", id: request.id, key: request.key }),
  dispose: (key) => void projections.delete(key),
})

const parser = createMarkdownParser(async (code, language) => {
  const instance = await getHighlighter()
  const name = language in bundledLanguages ? language : "text"

  if (!instance.getLoadedLanguages().includes(name))
    await instance.loadLanguage(bundledLanguages[name as BundledLanguage])

  return instance
    .codeToHtml(code, { lang: name as BundledLanguage, theme: "OpenCode", tabindex: false })
    .replace("<code>", `<code class="language-${name}">`)
})

self.onmessage = (event: MessageEvent<MarkdownWorkerRequest>) => {
  if (event.data.type === "dispose") {
    highlightQueue.dispose(event.data.key)
    projectQueue.dispose(event.data.key)

    return
  }

  if (event.data.type === "parse") {
    void parse(event.data)

    return
  }

  if (event.data.type === "project") {
    projectQueue.highlight(event.data)

    return
  }

  highlightQueue.highlight(event.data)
}

async function parse(request: Extract<MarkdownWorkerRequest, { type: "parse" }>) {
  try {
    post({ type: "parse", id: request.id, html: await parser.parse(request.text) })
  } catch (error) {
    post({ type: "error", id: request.id, message: error instanceof Error ? error.message : String(error) })
  }
}

async function runProject(request: Extract<MarkdownWorkerRequest, { type: "project" }>) {
  try {
    const projection = project(projections.get(request.key), request.text, request.live)
    projections.set(request.key, projection)
    post({ type: "project", id: request.id, key: request.key, projection })
  } catch (error) {
    post({
      type: "error",
      id: request.id,
      key: request.key,
      message: error instanceof Error ? error.message : String(error),
    })
  }
}

async function highlight(request: Extract<MarkdownWorkerRequest, { type: "highlight" }>) {
  try {
    const instance = await getHighlighter()
    const language = request.language in bundledLanguages ? request.language : "text"

    if (!instance.getLoadedLanguages().includes(language))
      await instance.loadLanguage(bundledLanguages[language as BundledLanguage])

    if (request.complete) {
      const result = instance.codeToTokens(request.text, { lang: language as BundledLanguage, theme: "OpenCode" })
      streams.delete(request.key)
      post({
        type: "highlight",
        id: request.id,
        key: request.key,
        language,
        reset: true,
        stable: result.tokens
          .flatMap((line, index) =>
            index === result.tokens.length - 1 ? line : [...line, { content: "\n", offset: 0 }],
          )
          .map(token),
        unstable: [],
      })

      return
    }

    const previous = streams.get(request.key)
    const reset = !previous || previous.language !== language || !request.text.startsWith(previous.source)

    const stream = reset
      ? {
          language,
          source: "",
          tokenizer: new ShikiStreamTokenizer({ highlighter: instance, lang: language, theme: "OpenCode" }),
        }
      : previous

    const result = await stream.tokenizer.enqueue(request.text.slice(stream.source.length))
    stream.source = request.text
    streams.set(request.key, stream)
    post({
      type: "highlight",
      id: request.id,
      key: request.key,
      language,
      reset,
      stable: result.stable.filter((token) => token.content.length > 0).map(token),
      unstable: result.unstable.filter((token) => token.content.length > 0).map(token),
    })
  } catch (error) {
    post({
      type: "error",
      id: request.id,
      key: request.key,
      message: error instanceof Error ? error.message : String(error),
    })
  }
}

function getHighlighter() {
  return (highlighter ??= createHighlighter({ themes: [OpenCodeTheme], langs: [] }))
}

function post(response: MarkdownWorkerResponse) {
  self.postMessage(response)
}

function token(value: ThemedToken): MarkdownToken {
  return [value.content, stringifyTokenStyle(value.htmlStyle ?? getTokenStyleObject(value))]
}

import { describe, expect, test } from "bun:test"
import type { PromptFileAttachment } from "@opencode/client/promise"
import { attached, typeLabel } from "./message-file"

function file(source: PromptFileAttachment["source"], mention = false): PromptFileAttachment {
  const item: PromptFileAttachment = {
    data: "",
    mime: "text/plain",
    source,
  }

  if (mention) item.mention = { text: "@README.md", start: 0, end: 10 }

  return item
}

describe("message-file", () => {
  test("only treats data-backed files without mentions as attachments", () => {
    expect(attached(file({ type: "inline" }))).toBe(true)
    expect(attached(file({ type: "uri", uri: "data:text/plain;base64,SGVsbG8=" }))).toBe(true)
    expect(attached(file({ type: "uri", uri: "blob:http://localhost/image-1" }))).toBe(true)
    expect(attached(file({ type: "uri", uri: "file:///repo/README.md" }))).toBe(false)
    expect(attached(file({ type: "inline" }, true))).toBe(false)
  })

  test("labels attachment types from the basename extension", () => {
    expect(typeLabel("list.md", "text/plain", "File")).toBe("Markdown")
    expect(typeLabel("/repo/src/main.ts", "text/plain", "File")).toBe("TypeScript")
    expect(typeLabel("/tmp/report.pdf", "application/pdf", "File")).toBe("PDF")
    expect(typeLabel("notes.xyz", "text/plain", "File")).toBe("XYZ")
    expect(typeLabel("/home/user/my.project/Makefile", "text/plain", "File")).toBe("File")
    expect(typeLabel(".gitignore", "text/plain", "File")).toBe("File")
    expect(typeLabel("/repo/.env", "text/plain", "File")).toBe("File")
  })
})

import { bundledLanguagesInfo } from "shiki"
import { getFilename } from "@opencode/util/path"
import type { PromptFileAttachment } from "@opencode/client/promise"

export function attached(file: PromptFileAttachment) {
  if (file.mention) return false

  if (file.source.type === "inline") return true

  return file.source.uri.startsWith("data:") || file.source.uri.startsWith("blob:")
}

// language metadata only; grammars stay behind shiki's lazy imports
const LANGUAGE_NAMES = new Map<string, string>(
  bundledLanguagesInfo.flatMap((info) =>
    [info.id, ...(info.aliases ?? [])].map((alias): [string, string] => [alias, info.name]),
  ),
)

// attachments carry text/plain for all text files, so the label comes from the extension;
// filename may be an absolute path, so extract the basename before looking for one
export function typeLabel(filename: string, mime: string, fallback: string) {
  if (mime === "application/pdf") return "PDF"
  const base = getFilename(filename)
  // idx 0 is a dotfile like .gitignore, not an extension
  const idx = base.lastIndexOf(".")
  const suffix = idx <= 0 ? "" : base.slice(idx + 1).toLowerCase()

  if (!suffix) return fallback

  return LANGUAGE_NAMES.get(suffix) ?? suffix.toUpperCase()
}

import type { FileDiffInfo, SessionMessageUser } from "@opencode/client/promise"
import { HoverCard } from "@kobalte/core/hover-card"
import { ComponentProps, For, Match, Show, createMemo, createSignal, splitProps, Switch } from "solid-js"
import { useI18n } from "@opencode/ui/context/i18n"

export function MessageNav(
  props: ComponentProps<"ul"> & {
    messages: SessionMessageUser[]
    current?: SessionMessageUser
    size: "normal" | "compact"
    onMessageSelect: (message: SessionMessageUser) => void
    getLabel?: (message: SessionMessageUser) => string | undefined
    getChanges?: (message: SessionMessageUser) => FileDiffInfo[] | undefined
  },
) {
  const i18n = useI18n()

  const [local, others] = splitProps(props, [
    "messages",
    "current",
    "size",
    "onMessageSelect",
    "getLabel",
    "getChanges",
    "class",
  ])

  const [hovercardOpen, setHovercardOpen] = createSignal(false)

  const selectMessage = (message: SessionMessageUser) => {
    setHovercardOpen(false)
    local.onMessageSelect(message)
  }

  const content = (className?: string) => (
    <ul role="list" data-component="message-nav" data-size={local.size} class={className} {...others}>
      <For each={local.messages}>
        {(message) => {
          const handleClick = () => selectMessage(message)

          const handleKeyPress = (event: KeyboardEvent) => {
            if (event.key !== "Enter" && event.key !== " ") return
            event.preventDefault()
            selectMessage(message)
          }

          return (
            <li data-slot="message-nav-item">
              <Switch>
                <Match when={local.size === "compact"}>
                  <div
                    data-slot="message-nav-tick-button"
                    data-active={message.id === local.current?.id || undefined}
                    role="button"
                    tabindex={0}
                    onClick={handleClick}
                    onKeyDown={handleKeyPress}
                  >
                    <div data-slot="message-nav-tick-line" />
                  </div>
                </Match>
                <Match when={local.size === "normal"}>
                  <button data-slot="message-nav-message-button" onClick={handleClick} onKeyDown={handleKeyPress}>
                    <MessageDiffBars changes={local.getChanges?.(message) ?? []} />
                    <div
                      data-slot="message-nav-title-preview"
                      data-active={message.id === local.current?.id || undefined}
                    >
                      <Show when={local.getLabel?.(message)} fallback={i18n.t("ui.messageNav.newMessage")}>
                        {local.getLabel?.(message)}
                      </Show>
                    </div>
                  </button>
                </Match>
              </Switch>
            </li>
          )
        }}
      </For>
    </ul>
  )

  return (
    <Switch>
      <Match when={local.size === "compact"}>
        <HoverCard
          open={hovercardOpen()}
          onOpenChange={setHovercardOpen}
          openDelay={0}
          closeDelay={120}
          placement="right-start"
          gutter={8}
          overflowPadding={24}
          fitViewport
        >
          <HoverCard.Trigger as="div" data-component="message-nav-hovercard" class={local.class}>
            {content()}
          </HoverCard.Trigger>
          <HoverCard.Portal>
            <HoverCard.Content data-slot="message-nav-hovercard-content">
              <MessageNav {...props} size="normal" class="" onMessageSelect={selectMessage} />
            </HoverCard.Content>
          </HoverCard.Portal>
        </HoverCard>
      </Match>
      <Match when={local.size === "normal"}>{content(local.class)}</Match>
    </Switch>
  )
}

function MessageDiffBars(props: { changes: { additions: number; deletions: number }[] }) {
  const additions = createMemo(() => props.changes.reduce((total, diff) => total + diff.additions, 0))
  const deletions = createMemo(() => props.changes.reduce((total, diff) => total + diff.deletions, 0))

  const colors = createMemo(() => {
    const added = additions()
    const deleted = deletions()

    if (added === 0 && deleted === 0) return Array(5).fill("var(--icon-weak-base)")

    if (added + deleted < 5) {
      return [
        ...Array(added > 0 ? 1 : 0).fill("var(--icon-diff-add-base)"),
        ...Array(deleted > 0 ? 1 : 0).fill("var(--icon-diff-delete-base)"),
        ...Array(5 - (added > 0 ? 1 : 0) - (deleted > 0 ? 1 : 0)).fill("var(--icon-weak-base)"),
      ]
    }

    const total = added + deleted
    const ratio = added > deleted ? added / deleted : deleted / added
    const colored = total < 20 || ratio < 4 ? 4 : 5
    const addedRaw = (added / total) * colored
    const deletedRaw = (deleted / total) * colored

    const addedBars =
      added === 0 ? 0 : Math.min(added <= 5 ? 1 : added <= 10 ? 2 : colored, Math.max(1, Math.round(addedRaw)))

    const deletedBars =
      deleted === 0 ? 0 : Math.min(deleted <= 5 ? 1 : deleted <= 10 ? 2 : colored, Math.max(1, Math.round(deletedRaw)))

    const overflow = Math.max(0, addedBars + deletedBars - colored)
    const adjustedAdded = overflow > 0 && addedRaw > deletedRaw ? addedBars - overflow : addedBars
    const adjustedDeleted = overflow > 0 && addedRaw <= deletedRaw ? deletedBars - overflow : deletedBars

    return [
      ...Array(adjustedAdded).fill("var(--icon-diff-add-base)"),
      ...Array(adjustedDeleted).fill("var(--icon-diff-delete-base)"),
      ...Array(5 - adjustedAdded - adjustedDeleted).fill("var(--icon-weak-base)"),
    ]
  })

  return (
    <svg data-slot="message-nav-diff-bars" viewBox="0 0 18 14" aria-hidden="true">
      <For each={colors().slice(0, 5)}>
        {(color, index) => <rect x={index() * 4} width="2" height="14" rx="1" fill={color} />}
      </For>
    </svg>
  )
}

import { describe, expect, test } from "bun:test"
import { parseDiffFromFile } from "@pierre/diffs"
import { completePatchContents, normalize, resolveFileDiff, text } from "./session-diff"

const header = "diff --git a/a.ts b/a.ts\nindex 1a2b3c4..5d6e7f8 100644\n--- a/a.ts\n+++ b/a.ts\n"

describe("session diff", () => {
  test.each([
    ["carriage return", "\r"],
    ["line separator", "\u2028"],
    ["paragraph separator", "\u2029"],
  ])(
    "parses adversarial patch headers containing a %s",
    (_, separator) => {
      // GHSA-73rr-hh4g-fpgx: isolate synchronous hangs and memory growth from the test runner.
      const name = `a${separator}b.ts`
      const padding = " ".repeat(10_000)

      const patches = [
        `--- ${name}\t\n+++ b.ts\t\n`,
        `--- a.ts\t\n+++ ${name}\t\n`,
        `--- ${padding}${name}\t\n+++ b.ts\t\n`,
        `--- a.ts\t\n+++ ${padding}${name}\t\n`,
        `Index: ${padding}${name}\n--- a.ts\t\n+++ b.ts\t\n`,
        `diff -r abc -r def ${padding}${name}\n--- a.ts\t\n+++ b.ts\t\n`,
      ].map((header) => `${header}@@ -1 +1 @@\n-old\n+new\n`)

      const result = Bun.spawnSync({
        cmd: [
          process.execPath,
          "--eval",
          `import { completePatchContents } from "./session-diff.ts"
         console.log(JSON.stringify((await Bun.stdin.json()).map(completePatchContents)))`,
        ],
        cwd: import.meta.dir,
        stdin: Buffer.from(JSON.stringify(patches)),
        timeout: 5_000,
        killSignal: "SIGKILL",
      })

      expect(result.exitCode, result.stderr.toString()).toBe(0)
      expect(JSON.parse(result.stdout.toString())).toEqual(patches.map(() => ({ before: "old\n", after: "new\n" })))
    },
    10_000,
  )

  test("renders whole-file unified patches as complete diffs", () => {
    const diff = {
      file: "a.ts",
      patch:
        "Index: a.ts\n===================================================================\n--- a.ts\t\n+++ a.ts\t\n@@ -1,2 +1,2 @@\n one\n-two\n+three\n",
      additions: 1,
      deletions: 1,
      status: "modified" as const,
    }

    const view = normalize(diff)

    expect(view.fileDiff.name).toBe("a.ts")
    expect(view.fileDiff.isPartial).toBe(false)
    expect(text(view, "deletions")).toBe("one\ntwo\n")
    expect(text(view, "additions")).toBe("one\nthree\n")
  })

  test("keeps missing final newlines from unified patches", () => {
    const diff = {
      file: "a.ts",
      patch:
        "Index: a.ts\n===================================================================\n--- a.ts\t\n+++ a.ts\t\n@@ -1,2 +1,2 @@\n one\n-two\n\\ No newline at end of file\n+three\n\\ No newline at end of file\n",
      additions: 1,
      deletions: 1,
      status: "modified" as const,
    }

    const view = normalize(diff)

    expect(text(view, "deletions")).toBe("one\ntwo")
    expect(text(view, "additions")).toBe("one\nthree")
  })

  test("renders whole-file VCS patches as complete diffs", () => {
    const fileDiff = resolveFileDiff({
      file: "a.ts",
      patch:
        "diff --git a/a.ts b/a.ts\nindex 1a2b3c4..5d6e7f8 100644\n--- a/a.ts\n+++ b/a.ts\n@@ -1,2 +1,2 @@\n one\n-old\n+new\n",
    })

    expect(fileDiff.isPartial).toBe(false)
    expect(fileDiff.additionLines).toEqual(["one\n", "new\n"])
  })

  test("keeps the producer's line alignment for complete patches", () => {
    // Valid but not minimal: diffing the rebuilt files again would keep `b` as unchanged context.
    const patch = `${header}@@ -1,3 +1,3 @@\n a\n-b\n-c\n+b\n+d\n`
    const fileDiff = resolveFileDiff({ file: "a.ts", patch })

    expect(fileDiff.isPartial).toBe(false)
    expect(fileDiff.hunks.map((hunk) => [hunk.deletionLines, hunk.additionLines])).toEqual([[2, 2]])
    // A content diff of the same files has different hunks, so it must not share the highlight identity.
    expect(resolveFileDiff({ file: "a.ts", before: "a\nb\nc\n", after: "a\nb\nd\n" }).cacheKey).not.toBe(
      fileDiff.cacheKey,
    )
  })

  test.each([
    ["missing final newlines", "@@ -1,2 +1,2 @@\n one\n-two\n\\ No newline at end of file\n+three\n\\ No newline at end of file\n"],
    ["an added final newline", "@@ -1,2 +1,2 @@\n one\n-two\n\\ No newline at end of file\n+two\n"],
    ["CRLF lines", "@@ -1,3 +1,3 @@\n one\r\n-two\r\n+three\r\n four\r\n"],
    ["a new file", "@@ -0,0 +1,3 @@\n+one\n+two\n+three\n"],
    ["a deleted file", "@@ -1,3 +0,0 @@\n-one\n-two\n-three\n"],
    ["a leading marker", "@@ -1,1 +1,1 @@\n\\ No newline at end of file\n-old\n+new\n"],
    ["interleaved changes", "@@ -1,4 +1,4 @@\n keep\n-a\n+b\n-c\n+d\n keep\n"],
  ])("splits complete patches with %s like a fresh file diff", (_, hunk) => {
    const patch = `${header}${hunk}`
    const contents = completePatchContents(patch)!

    const expected = parseDiffFromFile(
      { name: "a.ts", contents: contents.before },
      { name: "a.ts", contents: contents.after },
    )

    expect({ ...resolveFileDiff({ file: "a.ts", patch }), cacheKey: undefined }).toEqual({ ...expected, cacheKey: undefined })
  })

  test.each(["a\tb.ts", "a\nb.ts", '"quoted"', " padded.ts "])("keeps the exact file name %j for complete patches", (file) => {
    expect(resolveFileDiff({ file, patch: `${header}@@ -1,2 +1,2 @@\n one\n-old\n+new\n` }).name).toBe(file)
    expect(resolveFileDiff({ file, patch: `${header}@@ -0,0 +0,0 @@\n` }).name).toBe(file)
  })

  test("collapses unchanged runs in complete patches into the hunks of a fresh file diff", () => {
    const before = Array.from({ length: 40 }, (_, index) => `line ${index}\n`)
    const after = before.map((line, index) => (index === 3 || index === 30 ? `changed ${index}\n` : line))
    const body = before.map((line, index) => (line === after[index] ? ` ${line}` : `-${line}+${after[index]}`)).join("")

    const fileDiff = resolveFileDiff({
      file: "a.ts",
      patch: `${header}@@ -1,40 +1,40 @@\n${body}`,
    })

    expect(fileDiff.hunks).toHaveLength(2)
    expect(fileDiff.hunks).toEqual(
      parseDiffFromFile({ name: "a.ts", contents: before.join("") }, { name: "a.ts", contents: after.join("") }).hunks,
    )
  })

  test("keeps ordinary leading tool patches partial", () => {
    const fileDiff = resolveFileDiff({
      file: "a.ts",
      patch:
        "Index: a.ts\n===================================================================\n--- a.ts\n+++ a.ts\n@@ -1,5 +1,5 @@\n-old\n+new\n two\n three\n four\n five\n",
    })

    expect(fileDiff.isPartial).toBe(true)
    expect(fileDiff.additionLines).toEqual(["new\n", "two\n", "three\n", "four\n", "five\n"])
  })

  test("keeps separated patch hunks partial without complete file contents", () => {
    const fileDiff = resolveFileDiff({
      file: "project.ts",
      patch:
        'Index: project.ts\n===================================================================\n--- project.ts\t\n+++ project.ts\t\n@@ -1,3 +1,2 @@\n import { and } from "drizzle-orm"\n-import { sql } from "drizzle-orm"\n import { ProjectTable } from "./project.sql"\n@@ -346,3 +345,3 @@\n import { Database } from "@/storage/db"\n-import { ProjectTable } from "./project.sql"\n+import { ProjectTable } from "../project/project.sql"\n import { SessionTable } from "../session/session.sql"\n',
    })

    expect(fileDiff.isPartial).toBe(true)
    expect(fileDiff.hunks).toHaveLength(2)
    expect(fileDiff.hunks[1]?.collapsedBefore).toBeGreaterThan(0)
  })

  test("renders headerless persisted patches", () => {
    const view = normalize({
      file: "a.ts",
      patch: "@@ -1 +1 @@\n-old\n+new\n",
      additions: 1,
      deletions: 1,
      status: "modified" as const,
    })

    expect(view.fileDiff.name).toBe("a.ts")
    expect(view.fileDiff.isPartial).toBe(true)
    expect(text(view, "deletions")).toBe("old\n")
    expect(text(view, "additions")).toBe("new\n")
  })

  test("does not share headerless patch metadata between files", () => {
    const patch = "@@ -1 +1 @@\n-old\n+new\n"

    expect(resolveFileDiff({ file: "a.ts", patch }).name).toBe("a.ts")
    expect(resolveFileDiff({ file: "b.ts", patch }).name).toBe("b.ts")
  })

  test.each([
    "@@ -1 +1 @@\n-old\n+new\n",
    "--- a.ts\t\n+++ a.ts\t\n@@ -1 +1 @@\n-old\n+new\n",
  ])("reuses a highlight identity for the same cached patch: %s", (patch) => {
    const first = resolveFileDiff({ file: "a.ts", patch })
    expect(first.cacheKey).toBeString()
    expect(resolveFileDiff({ file: "a.ts", patch }).cacheKey).toBe(first.cacheKey)
    expect(resolveFileDiff({ file: "b.ts", patch }).cacheKey).not.toBe(first.cacheKey)
    expect(resolveFileDiff({ file: "a.ts", patch: patch.replace("+new", "+next") }).cacheKey).not.toBe(first.cacheKey)
  })

  test("keys preloaded content diffs by file name and content", () => {
    const diff = { file: "a.ts", before: "one\n", after: "two\n", additions: 1, deletions: 1 }
    const first = normalize(diff).fileDiff
    expect(first.cacheKey).toBeString()
    expect(normalize(diff).fileDiff.cacheKey).toBe(first.cacheKey)
    expect(normalize({ ...diff, file: "a.py" }).fileDiff.cacheKey).not.toBe(first.cacheKey)
    expect(normalize({ ...diff, after: "three\n" }).fileDiff.cacheKey).not.toBe(first.cacheKey)
  })

  test("does not reuse an evicted highlight identity for different content", () => {
    const patch = "@@ -1 +1 @@\n-old\n+new\n"
    const first = resolveFileDiff({ file: "evicted.ts", patch })

    const keys = Array.from({ length: 20 }, (_, index) =>
      resolveFileDiff({ file: "evicted.ts", patch: patch.replace("+new", `+new${index}`) }).cacheKey,
    )

    expect(keys).not.toContain(first.cacheKey)
    const restored = resolveFileDiff({ file: "evicted.ts", patch })
    expect(restored.additionLines).toEqual(first.additionLines)
    expect(restored.cacheKey).toBeString()
  })

  test("keeps capped header-only patches partial", () => {
    const fileDiff = resolveFileDiff({
      file: "a.ts",
      patch:
        "Index: a.ts\n===================================================================\n--- a.ts\t\n+++ a.ts\t\n",
    })

    expect(fileDiff.name).toBe("a.ts")
    expect(fileDiff.isPartial).toBe(true)
    expect(fileDiff.hunks).toEqual([])
  })

  test("keeps full preloaded content as a complete diff", () => {
    const diff = {
      file: "a.ts",
      before: "one\n",
      after: "two\n",
      additions: 1,
      deletions: 1,
      status: "modified" as const,
    }

    const view = normalize(diff)

    expect(view.fileDiff.isPartial).toBe(false)
    expect(text(view, "deletions")).toBe("one\n")
    expect(text(view, "additions")).toBe("two\n")
  })

  test("ignores malformed persisted patches", () => {
    const diff = {
      file: "a.ts",
      patch:
        "diff --git a/a.ts b/a.ts\nindex ff4ceb2..65a1de0 100644\n--- a/a.ts\n+++ b/a.ts\n@@ -1,3 +1,3 @@\n keep\n+add\n same\r",
      additions: 1,
      deletions: 1,
      status: "modified" as const,
    }

    const view = normalize(diff)

    expect(text(view, "deletions")).toBe("")
    expect(text(view, "additions")).toBe("")
  })
})

import { parseDiffFromFile, parsePatchFiles, processFile, type FileDiffMetadata } from "@pierre/diffs"
import { parsePatch } from "diff"
import { checksum } from "@opencode/util/encode"
import type { FileDiffInfo } from "@opencode/client/promise"
import type { PresentationFileDiff } from "../file-presentation"

type LegacyDiff = {
  file: string
  patch?: string
  before?: string
  after?: string
  additions: number
  deletions: number
  status?: "added" | "deleted" | "modified"
}

type ReviewDiff = (PresentationFileDiff & { file: string }) | FileDiffInfo | LegacyDiff

export type DiffSource = Pick<LegacyDiff, "file" | "patch" | "before" | "after">

export type ViewDiff = {
  file: string
  additions: number
  deletions: number
  status?: "added" | "deleted" | "modified"
  fileDiff: FileDiffMetadata
}

const diffCacheLimit = 16

const patchFileDiffCache = new Map<string, FileDiffMetadata>()

export function resolveFileDiff(diff: DiffSource) {
  // Untyped persisted payloads may carry `patch: null`; those render from their contents.
  if (diff.patch != null) return fileDiffFromPatch(diff.file, diff.patch)

  return fileDiffFromContent(diff.file, diff.before ?? "", diff.after ?? "")
}

export function normalize(diff: ReviewDiff): ViewDiff {
  return {
    file: diff.file,
    additions: diff.additions,
    deletions: diff.deletions,
    status: diff.status,
    fileDiff: resolveFileDiff(diff),
  }
}

export function text(diff: ViewDiff, side: "deletions" | "additions") {
  if (side === "deletions") return diff.fileDiff.deletionLines.join("")

  return diff.fileDiff.additionLines.join("")
}

function fileDiffFromPatch(file: string, patch: string) {
  const key = `${file}\0${patch}`
  const hit = patchFileDiffCache.get(key)

  if (hit) {
    patchFileDiffCache.delete(key)
    patchFileDiffCache.set(key, hit)

    return hit
  }

  const complete = completePatch(patch)
  const input = complete ? undefined : patchInput(file, patch)

  const value = complete
    ? fileDiffFromCompletePatch(file, complete)
    : ((input ? parsePatchFiles(input)[0]?.files[0] : undefined) ?? emptyFileDiff(file))

  // The patch text fixes both the content and the producer's alignment, so equal keys always mean equal hunks.
  value.cacheKey = highlightKey(key)
  patchFileDiffCache.set(key, value)

  while (patchFileDiffCache.size > diffCacheLimit) patchFileDiffCache.delete(patchFileDiffCache.keys().next().value!)

  return value
}

export function completePatchContents(patch: string) {
  const complete = completePatch(patch)

  if (!complete) return

  return { before: complete.before, after: complete.after }
}

function completePatch(patch: string) {
  try {
    const parsed = parsePatch(patch)[0]

    if (!parsed || (!parsed.index && !parsed.oldFileName && !parsed.newFileName)) return

    // Snapshot and VCS producers request full context. Tool patches use jsdiff's shorter default context.
    if (!patch.startsWith("diff --git ") && !/^--- [^\n]*\t\r?\n\+\+\+ [^\n]*\t(?:\r?\n|$)/m.test(patch)) return

    // Full patches collapse into one leading hunk. Separated hunks omit ranges and must stay partial.
    if (parsed.hunks.length !== 1) return

    const hunk = parsed.hunks[0]

    if (!hunk || hunk.oldStart > 1 || hunk.newStart > 1) return

    const before: Array<{ text: string; newline: boolean }> = []
    const after: Array<{ text: string; newline: boolean }> = []
    let previous: "-" | "+" | " " | undefined

    for (const line of hunk.lines) {
      if (line.startsWith("\\")) {
        if (previous === "-" || previous === " ") {
          const value = before.at(-1)

          if (value) value.newline = false
        }

        if (previous === "+" || previous === " ") {
          const value = after.at(-1)

          if (value) value.newline = false
        }

        continue
      }

      if (line.startsWith("-")) {
        before.push({ text: line.slice(1), newline: true })
        previous = "-"
        continue
      }

      if (line.startsWith("+")) {
        after.push({ text: line.slice(1), newline: true })
        previous = "+"
        continue
      }

      if (!line.startsWith(" ")) return
      before.push({ text: line.slice(1), newline: true })
      after.push({ text: line.slice(1), newline: true })
      previous = " "
    }

    const text = (lines: Array<{ text: string; newline: boolean }>) =>
      lines.map((line) => line.text + (line.newline ? "\n" : "")).join("")

    return { before: text(before), after: text(after), lines: hunk.lines }
  } catch {
    return
  }
}

// A complete patch already carries the producer's line diff. Splitting its single full-context hunk at long
// unchanged runs yields, in linear time, the collapsed hunks Pierre would get by diffing the reconstructed files
// again whenever both algorithms choose the same alignment.
function fileDiffFromCompletePatch(file: string, patch: { before: string; after: string; lines: string[] }) {
  // Pierre reads names back from header text, so a fixed header keeps tabs, quotes, and newlines in `file` intact.
  const value =
    processFile(`--- a\n+++ a\n${splitHunk(patch.lines)}`, {
      isGitDiff: false,
      oldFile: { name: file, contents: patch.before },
      newFile: { name: file, contents: patch.after },
    }) ?? emptyFileDiff(file)

  value.name = file

  return value
}

// Pierre's file diffs use jsdiff's default of four context lines; longer unchanged runs end one hunk and start the next.
const hunkContext = 4

function splitHunk(lines: string[]) {
  const rows = lines.reduce<{ line: string; marker?: string }[]>((result, line) => {
    const previous = result.at(-1)

    // A marker annotates the line before it; completePatch ignores a marker with nothing to annotate.
    if (line.startsWith("\\")) {
      if (previous) previous.marker = line

      return result
    }

    result.push({ line })

    return result
  }, [])

  const changes = rows.flatMap((row, index) => (row.line.startsWith(" ") ? [] : [index]))

  const ranges = changes.reduce<{ start: number; end: number }[]>((result, index) => {
    const previous = result.at(-1)
    const start = Math.max(0, index - hunkContext)
    const end = Math.min(rows.length - 1, index + hunkContext)

    if (previous && start <= previous.end + 1) {
      previous.end = end

      return result
    }

    result.push({ start, end })

    return result
  }, [])

  const positions = rows.reduce<{ old: number; new: number }[]>(
    (result, row) => {
      const current = result.at(-1)!

      result.push({
        old: current.old + (row.line.startsWith("+") ? 0 : 1),
        new: current.new + (row.line.startsWith("-") ? 0 : 1),
      })

      return result
    },
    [{ old: 0, new: 0 }],
  )

  return ranges
    .map((range) => {
      const start = positions[range.start]!
      const end = positions[range.end + 1]!
      const oldCount = end.old - start.old
      const newCount = end.new - start.new

      const body = rows
        .slice(range.start, range.end + 1)
        .map((row) => (row.marker ? `${row.line}\n${row.marker}` : row.line))
        .join("\n")

      return `@@ -${oldCount === 0 ? start.old : start.old + 1},${oldCount} +${newCount === 0 ? start.new : start.new + 1},${newCount} @@\n${body}`
    })
    .join("\n")
}

function patchInput(file: string, patch: string) {
  try {
    const parsed = parsePatch(patch)[0]

    if (!parsed) return

    if (parsed.index || parsed.oldFileName || parsed.newFileName) return patch

    if (!parsed.hunks.length) return

    return `Index: ${file}\n===================================================================\n--- ${file}\t\n+++ ${file}\t\n${patch}`
  } catch {
    return
  }
}

function fileDiffFromContent(file: string, before: string, after: string) {
  if (!before && !after) return emptyFileDiff(file)
  const value = parseDiffFromFile({ name: file, contents: before }, { name: file, contents: after })
  value.cacheKey = highlightKey(`${file}\0${before}\0${after}`)

  return value
}

// Pierre reuses and dedups worker highlighting only for diffs that carry a cacheKey, and it treats diffs with equal
// keys as the same target. Derive the key from every input that shapes the highlighted output: the file name selects
// the language and the content selects the lines.
function highlightKey(value: string) {
  return `${value.length}:${checksum(value) ?? 0}`
}

function emptyFileDiff(file: string) {
  return parseDiffFromFile({ name: file, contents: "" }, { name: file, contents: "" })
}

