  return {
    type: "tool",
    id: input.id,
    name: input.name,
    state: {
      status: "completed",
      input: input.args,
      content: [{ type: "text", text: input.output }],
      metadata: input.metadata,
    },
    time: {
      created: STORY_TIME + input.offset,
      ran: STORY_TIME + input.offset + 100,
      completed: STORY_TIME + input.offset + 900,
