  id: string
  name: string
  offset: number
  args: Record<string, JsonValue>
  output?: string
  metadata?: Record<string, JsonValue>
}): SessionMessageAssistantTool {
  const metadata = { ...input.metadata }

  if (input.output !== undefined) metadata.output = input.output

  return {
    type: "tool",
    id: input.id,
    name: input.name,
    state: {
      status: "running",
      input: input.args,
