import { expect, test } from "bun:test"

test("progress indicator PNG loops 36 frames at 30 fps in a 16x16 canvas", async () => {
  const png = Buffer.from(
    await Bun.file(new URL("./session-progress-indicator-v2-1x.png", import.meta.url)).arrayBuffer(),
  )

  expect(png.subarray(0, 8)).toEqual(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))

  const chunks: { type: string; data: Buffer }[] = []

  for (let offset = 8; offset < png.length; ) {
    const length = png.readUInt32BE(offset)
    expect(offset + length + 12).toBeLessThanOrEqual(png.length)
    chunks.push({
      type: png.toString("ascii", offset + 4, offset + 8),
      data: png.subarray(offset + 8, offset + 8 + length),
    })
    offset += length + 12
  }

  expect(chunks[0].type).toBe("IHDR")
  expect(chunks[0].data.readUInt32BE(0)).toBe(16)
  expect(chunks[0].data.readUInt32BE(4)).toBe(16)
  expect(chunks.at(-1)?.type).toBe("IEND")

  const animation = chunks.filter((chunk) => chunk.type === "acTL")
  expect(animation).toHaveLength(1)
  expect(animation[0].data.readUInt32BE(0)).toBe(36)
  expect(animation[0].data.readUInt32BE(4)).toBe(0)

  const frames = chunks.filter((chunk) => chunk.type === "fcTL")
  expect(frames).toHaveLength(36)
  const delays = frames.map((frame) => frame.data.readUInt16BE(20) / (frame.data.readUInt16BE(22) || 100))
  expect(delays.every((delay) => delay === 1 / 30)).toBe(true)
  expect(delays.reduce((total, delay) => total + delay, 0)).toBeCloseTo(1.2, 10)
})

import { createUniqueId, splitProps, type ComponentProps } from "solid-js"
import "./session-progress-indicator-v2.css"

const frames = new URL("./session-progress-indicator-v2-1x.png", import.meta.url).href

const dots = Array.from({ length: 25 }, (_, index) => {
  const x = 1 + (index % 5) * 3
  const y = 1 + Math.floor(index / 5) * 3

  return `M${x} ${y}h2v2h-2z`
}).join("")

export function SessionProgressIndicatorV2(props: ComponentProps<"svg">) {
  const [local, rest] = splitProps(props, ["class", "classList", "width", "height"])
  const id = createUniqueId()
  const filter = `session-progress-indicator-filter-${id}`
  const clip = `session-progress-indicator-clip-${id}`

  return (
    <svg
      {...rest}
      class={local.class}
      classList={local.classList}
      width={local.width ?? 16}
      height={local.height ?? 16}
      viewBox="0 0 16 16"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      data-component="session-progress-indicator-v2"
      aria-hidden={rest["aria-hidden"] ?? "true"}
    >
      <defs>
        <filter id={filter} filterUnits="userSpaceOnUse" x={0} y={0} width={16} height={16}>
          <feFlood flood-color="currentColor" result="color" />
          <feComposite in="color" in2="SourceAlpha" operator="in" />
        </filter>
        <clipPath id={clip}>
          <path d={dots} />
        </clipPath>
      </defs>
      <image
        data-frame-content
        href={frames}
        x={0}
        y={0}
        width={16}
        height={16}
        filter={`url(#${filter})`}
        clip-path={`url(#${clip})`}
      />
      <rect data-reduced-motion x={7} y={7} width={2} height={2} />
    </svg>
  )
}

