    completed: new Map(),
    activeOverlays: new Set(),
    reconciliation: new Map(),
  })
  const registrationUpdates = yield* PubSub.unbounded<ToolRegistrationUpdate>()
  const lock = yield* Semaphore.make(1)
  const attachmentLock = yield* Semaphore.make(1)

  const remove = (current: ToolState, id: string) => {
    const pending = new Map(current.pending)
    pending.delete(id)
    return { ...current, pending }
  }

  const complete = (current: ToolState, id: string, completion: string) => {
    const completed = new Map(current.completed)
    completed.set(id, completion)
    if (completed.size > completedRetention) {
      const oldest = completed.keys().next().value
      if (oldest !== undefined) completed.delete(oldest)
    }
    return { ...remove(current, id), completed }
  }

  const notify = (
    socket: ControlSocket,
    method: "tool.invocation" | "tool.cancel",
    params: SimulationProtocol.Backend.ToolInvocation | SimulationProtocol.Backend.ToolCancellation,
  ) => socket.send(JSON.stringify({ jsonrpc: "2.0", method, params }))

  const requireController = (socket: ControlSocket) =>
    Effect.gen(function* () {
      const current = yield* Ref.get(state)
      if (current.controller?.socket === socket) return current
      return yield* Effect.fail(new ToolControllerError({ message: "Drive tool controller is not attached" }))
    })

  const requireInvocation = (socket: ControlSocket, id: string) =>
    Effect.gen(function* () {
      const current = yield* requireController(socket)
      const invocation = current.pending.get(id)
      if (invocation) return { current, invocation }
      return yield* Effect.fail(
        new ToolInvocationNotFoundError({
          id,
          message: `Simulated tool invocation not found or already finished: ${id}`,
        }),
      )
    })

  const cancel = (id: string) =>
    Effect.gen(function* () {
      const invocation = yield* lock.withPermit(Ref.get(state).pipe(Effect.map((current) => current.pending.get(id))))
      if (!invocation) return
      yield* invocation.operations.withPermit(
        lock.withPermit(
          Effect.gen(function* () {
            const current = yield* Ref.get(state)
            if (current.pending.get(id) !== invocation) return
            yield* Ref.set(state, remove(current, id))
            if (current.controller && !current.controller.socket.data.closed)
              yield* notify(current.controller.socket, "tool.cancel", { id, reason: "interrupted" })
          }),
        ),
      )
    })

  const invoke = (
    registrationGeneration: number,
    name: string,
    input: unknown,
    context: Tool.Context,
  ): Effect.Effect<Tool.Result, Tool.Error> =>
    Effect.gen(function* () {
      const encoded = yield* Schema.decodeUnknownEffect(Schema.Json)(input).pipe(
        Effect.mapError((error) => new Tool.Error({ message: `Simulated tool input is not JSON: ${error.message}` })),
      )
      const invocation = yield* Effect.uninterruptibleMask((restore) =>
        attachmentLock
          .withPermit(
            lock.withPermit(
              Effect.gen(function* () {
                const current = yield* Ref.get(state)
                if (current.generation !== registrationGeneration)
                  yield* Effect.fail(
                    new Tool.Error({ message: `Simulated tool registration is no longer active: ${name}` }),
                  )
                const id = `tool_${current.counter + 1}`
                const completion = yield* Deferred.make<ToolCompletion>()
                const notification: SimulationProtocol.Backend.ToolInvocation = {
                  id,
                  name,
                  input: encoded,
                  context: {
                    sessionID: context.sessionID,
                    agent: context.agent,
                    messageID: context.messageID,
                    id: context.id,
                  },
                }
                const pending: PendingToolInvocation = {
                  id,
                  notification,
                  progress: context.progress,
                  completion,
                  operations: Semaphore.makeUnsafe(1),
                }
                yield* Ref.set(state, {
                  counter: current.counter + 1,
                  generation: current.generation,
                  appliedGeneration: current.appliedGeneration,
                  ...(current.controller === undefined ? {} : { controller: current.controller }),
                  registrations: current.registrations,
                  pending: new Map(current.pending).set(id, pending),
                  completed: current.completed,
                  activeOverlays: current.activeOverlays,
                  reconciliation: current.reconciliation,
                })
                if (current.controller && !current.controller.socket.data.closed)
                  yield* notify(current.controller.socket, "tool.invocation", notification)
                return pending
              }),
            ),
          )
          .pipe(
            Effect.flatMap((pending) =>
              restore(Deferred.await(pending.completion)).pipe(
                Effect.onInterrupt(() => cancel(pending.id)),
                Effect.ensuring(
                  lock.withPermit(
                    Ref.update(state, (current) =>
                      current.pending.get(pending.id) === pending ? remove(current, pending.id) : current,
                    ),
                  ),
                ),
              ),
            ),
          ),
      )
      // The simulation wire protocol keeps its historical field names; map to the
      // canonical output at this boundary.
      if (invocation.type === "success")
        return {
          output: invocation.output.structured,
          ...(invocation.output.content.length === 0
            ? {}
            : {
                content: invocation.output.content.map((part) =>
                  part.type === "text"
                    ? part
                    : {
                        type: "file" as const,
                        uri: `data:${part.mime};base64,${part.data}`,
                        mime: part.mime,
                        ...(part.name === undefined ? {} : { name: part.name }),
                      },
                ),
              }),
        }
      return yield* new Tool.Error({ message: invocation.message })
    })

  yield* plugins.register(
    Plugin.define({
      id: "opencode.simulation.tools",
      effect: (ctx) =>
        Effect.gen(function* () {
          const scope = yield* Scope.Scope
          const token = {}
          const registrationLock = Semaphore.makeUnsafe(1)
          let currentScope: Scope.Closeable | undefined
          const reconcile = (
            generation: number,
            nextRegistrations: ReadonlyArray<SimulationProtocol.Backend.ToolRegistration>,
          ) =>
            registrationLock.withPermit(
              Effect.gen(function* () {
                const nextScope = yield* Scope.fork(scope)
                const applied = yield* Effect.exit(
                  ctx.tool
                    .transform((draft) => {
                      for (const registration of nextRegistrations)
                        draft.add({
                          name: registration.name,
                          options:
                            registration.permission === undefined
                              ? registration.options
                              : { ...registration.options, permission: registration.permission },
                          description: registration.description,
                          input: registration.inputSchema,
                          output: registration.outputSchema ?? {},
                          execute: (input, context) =>
                            invoke(
                              generation,
                              SimulationProtocol.Backend.exposedToolName(registration),
                              input,
                              context,
                            ),
                        })
                    })
                    .pipe(Scope.provide(nextScope)),
                )
                if (Exit.isFailure(applied)) {
                  yield* Scope.close(nextScope, applied)
                  yield* Effect.failCause(applied.cause)
                }
                const previousScope = currentScope
                currentScope = nextScope
                if (previousScope) yield* Scope.close(previousScope, Exit.void)
              }),
            )

          const acknowledge = (generation: number, result: Exit.Exit<void, unknown>) =>
            lock.withPermit(
              Effect.gen(function* () {
                const current = yield* Ref.get(state)
                const reconciliation = current.reconciliation.get(token)
                if (reconciliation?.generation !== generation) return
                yield* Deferred.succeed(reconciliation.result, result)
              }),
            )

          const initialized = yield* lock.withPermit(
            Effect.gen(function* () {
              const subscription = yield* PubSub.subscribe(registrationUpdates)
              const current = yield* Ref.get(state)
              const activeOverlays = new Set(current.activeOverlays).add(token)
              yield* Ref.set(state, { ...current, activeOverlays })
              return { subscription, generation: current.generation, registrations: current.registrations }
            }),
          )
          yield* Effect.addFinalizer(() =>
            lock.withPermit(
              Effect.gen(function* () {
                const current = yield* Ref.get(state)
                const activeOverlays = new Set(current.activeOverlays)
                activeOverlays.delete(token)
                const reconciliation = new Map(current.reconciliation)
                const pending = reconciliation.get(token)
                reconciliation.delete(token)
                yield* Ref.set(state, { ...current, activeOverlays, reconciliation })
                if (pending) yield* Deferred.succeed(pending.result, Exit.void)
              }),
            ),
          )
          yield* reconcile(initialized.generation, initialized.registrations)
          yield* Stream.fromEffectRepeat(PubSub.take(initialized.subscription)).pipe(
            Stream.runForEach((update) =>
              Effect.gen(function* () {
                const result = yield* Effect.exit(reconcile(update.generation, update.registrations))
                yield* acknowledge(update.generation, result)
              }),
            ),
            Effect.forkScoped({ startImmediately: true }),
          )
        }),
    }),
  )

  const reconcileRegistrations = (
    controller: ToolController | undefined,
    registrations: ReadonlyArray<SimulationProtocol.Backend.ToolRegistration>,
    targetGeneration?: number,
  ) =>
    Effect.gen(function* () {
      const reconciliation = yield* lock.withPermit(
        Effect.gen(function* () {
          const current = yield* Ref.get(state)
          const generation = targetGeneration ?? current.generation + 1
          const reconciliation = new Map<object, ToolReconciliation>()
          for (const token of current.activeOverlays)
            reconciliation.set(token, {
              generation,
              result: Deferred.makeUnsafe<Exit.Exit<void, unknown>>(),
            })
          yield* Ref.set(state, {
            counter: current.counter,
            generation,
            appliedGeneration: current.appliedGeneration,
            ...(controller === undefined ? {} : { controller }),
            registrations,
            pending: current.pending,
            completed: current.completed,
            activeOverlays: current.activeOverlays,
            reconciliation,
          })
          yield* PubSub.publish(registrationUpdates, { generation, registrations })
          return { generation, previous: current, reconciliation }
        }),
      )
      const results = yield* Effect.forEach(reconciliation.reconciliation.values(), (item) =>
        Deferred.await(item.result),
      )
      const failure = results.find(Exit.isFailure)
      yield* lock.withPermit(
        Ref.update(state, (current) =>
          current.generation === reconciliation.generation
            ? {
                ...current,
                ...(failure === undefined ? { appliedGeneration: reconciliation.generation } : {}),
                reconciliation: new Map(),
              }
            : current,
        ),
      )
      return { failure, previous: reconciliation.previous }
    })

  const attach: ToolDriver["attach"] = (socket, registrations) =>
    attachmentLock.withPermit(
      Effect.gen(function* () {
        if (socket.data.closed)
          return yield* Effect.fail(
            new ToolControllerError({ message: "Drive tool controller disconnected before attachment" }),
          )
        const current = yield* Ref.get(state)
        if (current.controller && current.controller.socket !== socket && !current.controller.socket.data.closed)
          return yield* Effect.fail(
            new ToolControllerError({ message: "Another Drive tool controller is already attached" }),
          )
        const controller: ToolController = { socket }
        const replay = current.controller?.socket !== socket
        const sameRegistrations =
          current.appliedGeneration === current.generation &&
          fingerprintJson(current.registrations) === fingerprintJson(registrations)
        if (replay && current.pending.size > 0 && !sameRegistrations)
          return yield* Effect.fail(
            new ToolControllerError({
              message: "A reconnecting Drive tool controller must settle pending invocations before replacing tools",
            }),
          )
        if (sameRegistrations) {
          yield* lock.withPermit(
            Effect.gen(function* () {
              const current = yield* Ref.get(state)
              yield* Ref.set(state, { ...current, controller })
              if (replay)
                yield* Effect.forEach(
                  current.pending.values(),
                  (invocation) => notify(socket, "tool.invocation", invocation.notification),
                  { discard: true },
                )
            }),
          )
          return { attached: true as const }
        }
        const reconciled = yield* reconcileRegistrations(controller, registrations)
        if (reconciled.failure) {
          const rolledBack = yield* reconcileRegistrations(
            reconciled.previous.controller,
            reconciled.previous.registrations,
            reconciled.previous.generation,
          )
          return yield* Effect.fail(
            new ToolControllerError({
              message: rolledBack.failure
                ? `Failed to apply and restore simulated tools: ${Cause.pretty(reconciled.failure.cause)}; ${Cause.pretty(rolledBack.failure.cause)}`
                : `Failed to apply simulated tools: ${Cause.pretty(reconciled.failure.cause)}`,
            }),
          )
        }
        if (replay)
          yield* lock.withPermit(
            Effect.gen(function* () {
              const current = yield* Ref.get(state)
              if (current.controller?.socket !== socket) return
              yield* Effect.forEach(
                current.pending.values(),
                (invocation) => notify(socket, "tool.invocation", invocation.notification),
                { discard: true },
              )
            }),
          )
        return { attached: true as const }
      }),
    )

  const update: ToolDriver["update"] = (socket, params) =>
    Effect.gen(function* () {
      const { invocation } = yield* lock.withPermit(requireInvocation(socket, params.id))
      yield* invocation.operations.withPermit(
        Effect.gen(function* () {
          const current = yield* lock.withPermit(Ref.get(state))
          if (current.pending.get(params.id) !== invocation)
            yield* Effect.fail(
              new ToolInvocationNotFoundError({
                id: params.id,
                message: `Simulated tool invocation not found or already finished: ${params.id}`,
              }),
            )
          const fingerprint = fingerprintJson(params.update)
          const applied = invocation.update
          if (applied?.sequence === params.sequence && applied.fingerprint === fingerprint) return
          if (applied?.sequence === params.sequence)
            yield* Effect.fail(
              new ToolControllerError({
                message: `Simulated tool update sequence ${params.sequence} was reused with different progress`,
              }),
            )
          const expected = applied === undefined ? 0 : applied.sequence + 1
          if (params.sequence !== expected)
            yield* Effect.fail(
              new ToolControllerError({
                message: `Expected simulated tool update sequence ${expected}, received ${params.sequence}`,
              }),
            )
          yield* invocation.progress(params.update)
          invocation.update = { sequence: params.sequence, fingerprint }
        }),
      )
    })

  const settle = (socket: ControlSocket, id: string, completion: ToolCompletion) =>
    Effect.gen(function* () {
      const current = yield* lock.withPermit(requireController(socket))
      const fingerprint = fingerprintJson(completion)
      const invocation = current.pending.get(id)
      if (!invocation) {
        if (current.completed.get(id) === fingerprint) return
        yield* Effect.fail(
          new ToolInvocationNotFoundError({
            id,
            message: `Simulated tool invocation not found or already finished: ${id}`,
          }),
        )
        return
      }
      yield* invocation.operations.withPermit(
        Effect.uninterruptible(
          lock.withPermit(
            Effect.gen(function* () {
              const current = yield* Ref.get(state)
              if (current.pending.get(id) !== invocation) {
                if (current.completed.get(id) === fingerprint) return
                yield* Effect.fail(
                  new ToolInvocationNotFoundError({
                    id,
                    message: `Simulated tool invocation not found or already finished: ${id}`,
                  }),
                )
                return
              }
              yield* Ref.set(state, complete(current, id, fingerprint))
              yield* Deferred.succeed(invocation.completion, completion)
            }),
          ),
        ),
      )
    })

  const release: ToolDriver["release"] = (socket) =>
    attachmentLock.withPermit(
      lock.withPermit(
        Ref.update(
          state,
          (current): ToolState =>
            current.controller?.socket !== socket
              ? current
              : {
                  counter: current.counter,
                  generation: current.generation,
                  appliedGeneration: current.appliedGeneration,
                  registrations: current.registrations,
                  pending: current.pending,
                  completed: current.completed,
                  activeOverlays: current.activeOverlays,
                  reconciliation: current.reconciliation,
                },
        ),
      ),
    )

  const shutdown = attachmentLock.withPermit(
    Effect.gen(function* () {
      yield* reconcileRegistrations(undefined, [])
      const current = yield* lock.withPermit(
        Effect.gen(function* () {
          const current = yield* Ref.get(state)
          yield* Ref.set(state, {
            counter: current.counter,
            generation: current.generation,
            appliedGeneration: current.appliedGeneration,
            registrations: [],
            pending: new Map(),
            completed: current.completed,
            activeOverlays: new Set<object>(),
            reconciliation: new Map(),
          })
          return current
        }),
      )
      yield* Effect.forEach(
        current.pending.values(),
        (invocation) =>
          Deferred.succeed(invocation.completion, {
            type: "failure",
            message: "Simulated tool controller shut down",
          }),
        { discard: true },
      )
      yield* PubSub.shutdown(registrationUpdates)
    }),
  )

  return {
    attach,
    update,
    finish: (socket, params) => settle(socket, params.id, { type: "success", output: params.output }),
    fail: (socket, params) => settle(socket, params.id, { type: "failure", message: params.message }),
    release,
    shutdown,
  } satisfies ToolDriver
})

function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`
  if (typeof value === "object" && value !== null) {
    const entries = Object.entries(value).sort(([left], [right]) => left.localeCompare(right))
    return `{${entries.map(([key, item]) => `${JSON.stringify(key)}:${canonicalJson(item)}`).join(",")}}`
  }
  return JSON.stringify(value) ?? String(value)
}

function fingerprintJson(value: unknown) {
  return createHash("sha256").update(canonicalJson(value)).digest("base64url")
}

function releaseController(
  activeController: Ref.Ref<Fiber.Fiber<void> | undefined>,
  controllerLock: Semaphore.Semaphore,
  socket: ControlSocket,
) {
  return controllerLock.withPermit(
    Effect.gen(function* () {
      const attachment = socket.data.attachment
      if (!attachment) return
      yield* Fiber.interrupt(attachment)
      yield* Ref.update(activeController, (active) => (active === attachment ? undefined : active))
    }),
  )
}

export * as SimulatedProvider from "./simulated-provider"

import { Effect, Fiber, FiberSet, Queue, Stream } from "effect"
import { SimulationProtocol } from "./protocol"

export interface Server {
  readonly url: string
}

interface Request {
  readonly id?: string | number | null
}

export interface SocketData {
  readonly drive?: true
  attachment?: Fiber.Fiber<void>
  closed?: true
}

export interface Socket {
  readonly data: SocketData
  readonly send: (message: string) => Effect.Effect<void>
}

const maxOutboundBytes = 64 * 1024 * 1024

export function start<RequestType extends Request, Error, Services>(options: {
  readonly endpoint: string
  readonly label: string
  readonly data: () => SocketData
  readonly decode: (input: string) => Effect.Effect<RequestType, Error>
  readonly handle: (socket: Socket, request: RequestType) => Effect.Effect<unknown, unknown, Services>
  readonly close?: (socket: Socket) => Effect.Effect<void, never, Services>
}) {
  return Effect.gen(function* () {
    const messages = yield* Queue.bounded<{ readonly socket: Socket; readonly input: string }>(256)
    yield* Stream.fromQueue(messages).pipe(
      Stream.runForEach((message) =>
        options.decode(message.input).pipe(
          Effect.flatMap((request) =>
            options.handle(message.socket, request).pipe(
              Effect.matchEffect({
                onFailure: (error) => send(message.socket, SimulationProtocol.JsonRpc.failure(request.id, error)),
                onSuccess: (result) => send(message.socket, SimulationProtocol.JsonRpc.success(request.id, result)),
              }),
            ),
          ),
          Effect.catch((error) => send(message.socket, SimulationProtocol.JsonRpc.failure(undefined, error))),
          Effect.catchCause((cause) => Effect.logWarning(`${options.label}: request failed`, cause)),
        ),
      ),
      Effect.forkScoped,
    )
    const url = yield* Effect.try({ try: () => new URL(options.endpoint), catch: (cause) => cause })
    const websocket = yield* Effect.promise(() => import("ws"))
    const runPromise = yield* FiberSet.makeRuntimePromise<Services, void, never>()
    yield* Effect.acquireRelease(
      Effect.tryPromise(
        () =>
          new Promise<{
            readonly close: () => Promise<void>
          }>((resolve, reject) => {
            const server = new websocket.WebSocketServer({ host: url.hostname, port: Number(url.port) })
            const sockets = new Map<
              InstanceType<typeof websocket.WebSocket>,
              { socket: Socket; cleanup: () => Promise<void> }
            >()
            const report = (scope: string, cause: unknown) =>
              void runPromise(Effect.logWarning(`${options.label}: ${scope} error`, cause))
            const onServerError = (cause: Error) => report("server", cause)
            const onStartupError = (cause: Error) => {
              server.off("listening", onListening)
              server.on("error", onServerError)
              reject(cause)
            }
            const onListening = () => {
              server.off("error", onStartupError)
              server.on("error", onServerError)
              resolve({
                close: async () => {
                  const accepted = Array.from(sockets.entries())
                  accepted.forEach(([connection, record]) => {
                    record.socket.data.closed = true
                    connection.terminate()
                  })
                  await Promise.all([
                    new Promise<void>((resolveClose, rejectClose) => {
                      server.close((cause) => (cause ? rejectClose(cause) : resolveClose()))
                      // Bun releases the listener but does not invoke ws' close callback after an upgraded socket.
                      queueMicrotask(() => {
                        if (server.address() === null) resolveClose()
                      })
                    }),
                    Promise.all(accepted.map(([, record]) => record.cleanup())),
                  ])
                  server.off("error", onServerError)
                },
              })
            }
            server.once("listening", onListening)
            server.once("error", onStartupError)
            server.on("connection", (connection) => {
              let pendingBytes = 0
              let outbound = Promise.resolve()
              let cleanup: Promise<void> | undefined
              const socket: Socket = {
                data: options.data(),
                send: (message) =>
                  Effect.tryPromise({
                    try: () => {
                      const bytes = Buffer.byteLength(message)
                      if (bytes > maxOutboundBytes || pendingBytes + bytes > maxOutboundBytes)
                        return Promise.reject(new Error(`Simulation outbound queue exceeds ${maxOutboundBytes} bytes`))
                      pendingBytes += bytes
                      const current = outbound.then(
                        () =>
                          new Promise<void>((resolveSend, rejectSend) => {
                            if (connection.readyState !== websocket.WebSocket.OPEN) {
                              rejectSend(new Error("Simulation control socket is not open"))
                              return
                            }
                            connection.send(message, (cause) => (cause ? rejectSend(cause) : resolveSend()))
                          }),
                      )
                      outbound = current.catch(() => undefined)
                      return current.finally(() => {
                        pendingBytes -= bytes
                      })
                    },
                    catch: (cause) => (cause instanceof Error ? cause : new Error(String(cause))),
                  }).pipe(
                    Effect.tapError(() =>
                      Effect.sync(() => {
                        connection.terminate()
                      }),
                    ),
                    Effect.orDie,
                  ),
              }
              const close = () => {
                socket.data.closed = true
                cleanup ??= runPromise(options.close?.(socket) ?? Effect.void).finally(() => sockets.delete(connection))
                return cleanup
              }
              sockets.set(connection, { socket, cleanup: close })
              connection.on("close", () => void close())
              connection.on("error", (cause) => {
                report("socket", cause)
                connection.terminate()
              })
              connection.on("message", (message) => {
                const input = Array.isArray(message)
                  ? Buffer.concat(message).toString()
                  : message instanceof ArrayBuffer
                    ? Buffer.from(message).toString()
                    : message.toString()
                if (Queue.offerUnsafe(messages, { socket, input })) return
                void runPromise(
                  socket
                    .send(
                      JSON.stringify(
                        SimulationProtocol.JsonRpc.failure(undefined, new Error("Simulation control queue is full")),
                      ),
                    )
                    .pipe(
                      Effect.catchCause((cause) =>
                        Effect.logWarning(`${options.label}: queue rejection failed`, cause),
                      ),
                    ),
                )
              })
            })
          }),
      ),
      ({ close }) => Effect.promise(close),
    )
    return { url: options.endpoint } satisfies Server
  })
}

function send(socket: Socket, response: SimulationProtocol.JsonRpc.Response | undefined) {
  if (!response) return Effect.void
  return socket.send(JSON.stringify(response))
}

export * as SimulationControlServer from "./control-server"

import { ImageRenderable, type CliRenderer, type Renderable } from "@opentui/core"
import {
  createMockKeys,
  createMockMouse,
  KeyCodes,
  type KeyInput,
  type MockInput,
  type MockMouse,
} from "@opentui/core/testing"
import { Effect, Schema } from "effect"
import { Base64 } from "effect/encoding"
import { SimulationProtocol } from "../protocol"
import { SimulationRenderer } from "./renderer"
import { SimulationSemantics } from "./semantics"

export type Action = SimulationProtocol.Frontend.Action
export type Element = SimulationProtocol.Frontend.Element

export interface Harness {
  readonly renderer: CliRenderer
  readonly mockInput: MockInput
  readonly mockMouse: MockMouse
  readonly resize: (cols: number, rows: number) => void
  readonly renderOnce: () => Promise<void>
  readonly screen: () => string
}

type RenderBuffer = {
  readonly width: number
  readonly height: number
  getRealCharBytes(includeAnsi?: boolean): Uint8Array
}

const decoder = new TextDecoder()

function isKeyCode(key: string): key is keyof typeof KeyCodes {
  return Object.hasOwn(KeyCodes, key)
}

function keyInput(key: string): KeyInput {
  const named = key.toUpperCase()
  return isKeyCode(named) ? named : key
}

function children(renderable: Renderable) {
  return renderable.getChildren().filter((child): child is Renderable => "num" in child)
}

function all(renderable: Renderable): Renderable[] {
  return [renderable, ...children(renderable).flatMap(all)]
}

function mouseListeners(renderable: Renderable) {
  // oxlint-disable-next-line no-restricted-globals -- OpenTUI does not expose listener state through its public API.
  const general = Reflect.get(renderable, "_mouseListener")
  // oxlint-disable-next-line no-restricted-globals -- OpenTUI does not expose listener state through its public API.
  const specific = Reflect.get(renderable, "_mouseListeners")
  return Boolean(general) || (specific && typeof specific === "object" && Object.keys(specific).length > 0)
}

function hit(renderer: CliRenderer, renderable: Renderable) {
  if (renderable.width <= 0 || renderable.height <= 0) return false
  const x = Math.floor(renderable.screenX + renderable.width / 2)
  const y = Math.floor(renderable.screenY + renderable.height / 2)
  const target = renderer.hitTest(x, y)
  return all(renderable).some((item) => item.num === target)
}

/**
 * Builds the harness the simulation server drives.
 *
 * When the renderer is the headless simulation renderer, its TestRendererSetup
 * provides the supported testing APIs. For the visible terminal renderer the
 * harness falls back to `requestRender` + `idle` and reading the private
 * `currentRenderBuffer`.
 */
export function createHarness(renderer: CliRenderer): Harness {
  const setup = SimulationRenderer.setupFor(renderer)
  return {
    renderer,
    mockInput: setup?.mockInput ?? createMockKeys(renderer),
    mockMouse: setup?.mockMouse ?? createMockMouse(renderer),
    resize: setup?.resize ?? ((cols, rows) => renderer.resize(cols, rows)),
    renderOnce:
      setup?.renderOnce ??
      (async () => {
        renderer.requestRender()
        await renderer.idle()
      }),
    // captureCharFrame follows the test renderer's output sink. Recording
    // redirects that sink to the timeline, so read the live render buffer
    // instead; it is also the source used by screenshots.
    // oxlint-disable-next-line no-restricted-globals -- OpenTUI does not expose the live render buffer publicly.
    screen: () => decoder.decode((Reflect.get(renderer, "currentRenderBuffer") as RenderBuffer).getRealCharBytes()),
  }
}

export function elements(renderer: CliRenderer): Element[] {
  return all(renderer.root)
    .filter((renderable) => renderable.visible && !renderable.isDestroyed)
    .map((renderable) => {
      const clickable = mouseListeners(renderable) && hit(renderer, renderable)
      return {
        id: renderable.id,
        num: renderable.num,
        x: renderable.screenX,
        y: renderable.screenY,
        width: renderable.width,
        height: renderable.height,
        focusable: renderable.focusable,
        focused: renderable.focused,
        clickable,
        editor: renderer.currentFocusedEditor === renderable,
      } satisfies Element
    })
    .filter((element) => element.focusable || element.clickable || element.editor)
}

export function state(harness: Harness) {
  const renderable = harness.renderer.currentFocusedRenderable?.num
  return {
    focused: {
      ...(renderable === undefined ? {} : { renderable }),
      editor: Boolean(harness.renderer.currentFocusedEditor),
    },
    elements: elements(harness.renderer),
  }
}

export function snapshot(harness: Harness): SimulationProtocol.Frontend.SemanticSnapshot {
  const ids = new Set<string>()
  const visit = (renderable: Renderable, parent?: string): SimulationProtocol.Frontend.SemanticNode[] => {
    if (!renderable.visible || renderable.isDestroyed) return []
    const definition = SimulationSemantics.read(renderable)?.()
    if (definition && ids.has(renderable.id)) throw new Error(`duplicate semantic UI id: ${renderable.id}`)
    if (definition) ids.add(renderable.id)
    const node = definition
      ? [{ id: renderable.id, ...definition, ...(parent === undefined ? {} : { parent }), element: renderable.num }]
      : []
    const ancestor = definition ? renderable.id : parent
    return [...node, ...children(renderable).flatMap((child) => visit(child, ancestor))]
  }
  return Schema.decodeUnknownSync(SimulationProtocol.Frontend.SemanticSnapshot)({
    format: "opencode-ui-snapshot-v1",
    nodes: visit(harness.renderer.root),
  })
}

export function matches(harness: Pick<Harness, "screen">, text: string) {
  return harness.screen().includes(text)
}

export const capture = Effect.fn("SimulationActions.capture")(function* (harness: Harness) {
  yield* Effect.tryPromise(() => harness.renderOnce())
  const buffer = harness.renderer.currentRenderBuffer
  return {
    cols: buffer.width,
    rows: buffer.height,
    cursor: [0, 0] as const,
    lines: buffer.getSpanLines().map((line) => ({
      spans: line.spans.map((span) => ({
        text: span.text,
        fg: span.fg.toInts(),
        bg: span.bg.toInts(),
        attributes: span.attributes,
        width: span.width,
      })),
    })),
    images: captureImages(harness.renderer),
  } satisfies SimulationProtocol.Frontend.CapturedFrame
})

function captureImages(renderer: CliRenderer): SimulationProtocol.Frontend.CapturedImage[] {
  return all(renderer.root).flatMap((renderable) => {
    if (!(renderable instanceof ImageRenderable) || !renderable.visible || renderable.isDestroyed || !renderable.image)
      return []
    const fitted = renderable.fit === "cover"
      ? { width: renderable.width, height: renderable.height }
      : renderable.getFittedSize(renderable.width, renderable.height)
    if (fitted.width <= 0 || fitted.height <= 0) return []
    const x = renderable.screenX + Math.floor((renderable.width - fitted.width) / 2)
    const y = renderable.screenY + Math.floor((renderable.height - fitted.height) / 2)
    let source = renderable.image
    let extracted: typeof source | undefined
    if (renderable.fit === "cover") {
      const targetAspect = renderable.width / (renderable.height * renderable.cellAspectRatio)
      const sourceAspect = source.width / source.height
      const width = sourceAspect > targetAspect ? Math.max(1, Math.round(source.height * targetAspect)) : source.width
      const height = sourceAspect > targetAspect ? source.height : Math.max(1, Math.round(source.width / targetAspect))
      extracted = source.extract({
        left: Math.floor((source.width - width) / 2),
        top: Math.floor((source.height - height) / 2),
        width,
        height,
      })
      source = extracted
    }
    try {
      const raw = source.raw("rgba8")
      const rgba = new Uint8Array(raw.width * raw.height * 4)
      for (let row = 0; row < raw.height; row++)
        rgba.set(raw.data.subarray(row * raw.stride, row * raw.stride + raw.width * 4), row * raw.width * 4)
      return [{
        x,
        y,
        width: fitted.width,
        height: fitted.height,
        pixelWidth: raw.width,
        pixelHeight: raw.height,
        rgba: Base64.encode(rgba),
      }]
    } finally {
      extracted?.dispose()
    }
  })
}

export const execute = Effect.fn("SimulationActions.execute")(function* (harness: Harness, action: Action) {
  switch (action.type) {
    case "ui.type":
      yield* Effect.tryPromise(() => harness.mockInput.typeText(action.text))
      break
    case "ui.press":
      harness.mockInput.pressKey(keyInput(action.key), action.modifiers)
      break
    case "ui.enter":
      harness.mockInput.pressEnter()
      break
    case "ui.arrow":
      harness.mockInput.pressArrow(action.direction)
      break
    case "ui.focus":
      all(harness.renderer.root)
        .find((item) => item.num === action.target)
        ?.focus()
      break
    case "ui.mouse": {
      const params = action.params
      if (params.x >= harness.renderer.width || params.y >= harness.renderer.height)
        return yield* Effect.fail(new Error("mouse position must be within the terminal viewport"))
      const options = { modifiers: params.modifiers }
      SimulationRenderer.recordPointer(harness.renderer, params.action, params.x, params.y)
      switch (params.action) {
        case "move":
          yield* Effect.tryPromise(() => harness.mockMouse.moveTo(params.x, params.y, options))
          break
        case "down":
          yield* Effect.tryPromise(() =>
            harness.mockMouse.pressDown(params.x, params.y, mouseButton(params.button), options),
          )
          break
        case "up":
          yield* Effect.tryPromise(() =>
            harness.mockMouse.release(params.x, params.y, mouseButton(params.button), options),
          )
          break
        case "scroll":
          yield* Effect.tryPromise(() => harness.mockMouse.scroll(params.x, params.y, params.direction, options))
          break
      }
      break
    }
    case "ui.click": {
      const target = all(harness.renderer.root).find((item) => item.num === action.target)
      if (!target || !target.visible || target.isDestroyed)
        return yield* Effect.fail(new Error(`click target is stale or unavailable: ${action.target}`))
      if (action.semantic) {
        const current = snapshot(harness).nodes.find((node) => node.element === action.target)
        if (
          current?.id !== action.semantic.id ||
          current.instance !== action.semantic.instance ||
          current.element !== action.semantic.element
        )
          return yield* Effect.fail(new Error(`semantic click target is stale or unavailable: ${action.semantic.id}`))
      }
      if (
        !Number.isFinite(action.x) ||
        action.x < 0 ||
        action.x >= target.width ||
        !Number.isFinite(action.y) ||
        action.y < 0 ||
        action.y >= target.height
      )
        return yield* Effect.fail(new Error("click position must be within the target element"))
      SimulationRenderer.recordPointer(harness.renderer, "click", target.screenX + action.x, target.screenY + action.y)
      yield* Effect.tryPromise(() => harness.mockMouse.click(target.screenX + action.x, target.screenY + action.y))
      break
    }
    case "ui.resize":
      if (
        !Number.isSafeInteger(action.cols) ||
        action.cols <= 0 ||
        !Number.isSafeInteger(action.rows) ||
        action.rows <= 0
      ) {
        return yield* Effect.fail(new Error("resize cols and rows must be positive integers"))
      }
      harness.resize(action.cols, action.rows)
      SimulationRenderer.recordResize(harness.renderer, action.cols, action.rows)
      break
  }
  yield* Effect.tryPromise(() => harness.renderOnce())
  return state(harness)
})

