        const socket = yield* connect(endpoint)
        const messages = yield* messagesFrom(socket)
        const registration = {
          name: "lookup",
          description: "Look up a value",
          inputSchema: {
            type: "object",
            properties: { query: { type: "string" } },
            required: ["query"],
            additionalProperties: false,
          },
          outputSchema: { type: "object" },
