export function isProviderlessLab(lab: string | undefined) {
  return !lab || catalogSlug(lab) === "unknown"
}

export function isKnownCatalogLab(lab: string | undefined, catalogLabs: readonly string[]) {
  if (!lab || isProviderlessLab(lab)) return false
  const key = catalogSlug(formatCatalogLabName(lab))
  return catalogLabs.some((candidate) => catalogSlug(formatCatalogLabName(candidate)) === key)
}

export function catalogSlug(value: string) {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .replace(/-{2,}/g, "-")
}

export function buildModelCatalog(payload: unknown, pricingPayload?: unknown, labPayload?: unknown): ModelCatalog {
  const costs = readCatalogCosts(pricingPayload)
  const labDescriptions = readCatalogLabDescriptions(payload, pricingPayload, labPayload)
  const models = readCatalogModels(payload)
    .flatMap(readModelCatalogEntry)
    .map((model) => ({
      ...model,
      cost:
        costs.get(catalogIdKey(model.id)) ??
        costs.get(`${model.lab}/${model.slug}`) ??
        costs.get(`opencode-go/${model.slug}`) ??
        costs.get(model.slug) ??
        model.cost,
    }))
    .toSorted((a, b) => a.lab.localeCompare(b.lab) || displayDateTime(b.releaseDate) - displayDateTime(a.releaseDate))
  return {
    models,
    // Contributor is a serving tier of these Muse models, with its own pricing.
    // Keep aliases out of the model population used to normalize benchmark scores.
    aliases: ["meta/muse-spark-1.2", "meta/muse-spark-1.3"].flatMap((id) => {
      const model = models.find((entry) => entry.id === id)
      if (!model) return []
      const alias = `${id}-contributor`
      return [
        {
          ...model,
          id: alias,
          slug: `${model.slug}-contributor`,
          name: `${model.name} Contributor`,
          cost:
            costs.get(catalogIdKey(alias)) ??
            costs.get(`${model.lab}/${model.slug}-contributor`) ??
            costs.get(`${model.slug}-contributor`),
        },
      ]
    }),
    labs: Object.values(
      models.reduce<Record<string, ModelCatalogLab>>((result, model) => {
        result[model.lab] = {
          id: model.lab,
          name: formatCatalogLabName(model.lab),
          description: result[model.lab]?.description ?? labDescriptions.get(model.lab),
          models: [...(result[model.lab]?.models ?? []), model],
        }
        return result
      }, {}),
    ).toSorted((a, b) => a.name.localeCompare(b.name)),
    stealthSpecs: readStealthModelSpecs(pricingPayload),
  }
}

function readStealthModelSpecs(payload: unknown): Record<string, ModelCatalogSpecs> {
  if (!isRecord(payload)) return {}
  return Object.fromEntries(
    // Later entries win, so the opencode listing takes precedence over opencode-go.
    ["opencode-go", "opencode"]
      .map((provider) => payload[provider])
      .flatMap((provider) => (isRecord(provider) && isRecord(provider.models) ? Object.entries(provider.models) : []))
      .flatMap(([id, value]) => {
        const model = statModel(id, undefined)
        if (!STEALTH_MODELS.has(model) || !isRecord(value)) return []
        return [
          [
            model,
            {
              knowledge: stringValue(value.knowledge),
              releaseDate: stringValue(value.release_date),
              limit: readCatalogLimit(value.limit),
              modalities: readCatalogModalities(value.modalities),
            },
          ] as const,
        ]
      }),
  )
}

function readModelCatalogEntry(value: unknown): ModelCatalogEntry[] {
  if (!isRecord(value)) return []
  const id = stringValue(value.id)
  const name = stringValue(value.name)
  const lab = id?.split("/")[0]
  const slug = id?.split("/").slice(1).join("/")
  if (!id || !name || !lab || !slug) return []
  return [
    {
      id,
      lab: catalogSlug(lab),
      slug: catalogSlug(slug),
      name,
      description: stringValue(value.description),
      family: stringValue(value.family),
      knowledge: stringValue(value.knowledge),
      releaseDate: stringValue(value.release_date),
      lastUpdated: stringValue(value.last_updated),
      limit: readCatalogLimit(value.limit),
      modalities: readCatalogModalities(value.modalities),
      openWeights: booleanValue(value.open_weights),
      reasoning: typeof value.reasoning === "boolean" ? value.reasoning : undefined,
      toolCall: typeof value.tool_call === "boolean" ? value.tool_call : undefined,
      attachment: booleanValue(value.attachment),
      temperature: booleanValue(value.temperature),
      cost: readCatalogCost(value.cost),
      weights: readCatalogWeights(value.weights),
      benchmarks: readCatalogBenchmarks(value.benchmarks),
    },
  ]
}

function readCatalogModels(payload: unknown): unknown[] {
  if (Array.isArray(payload)) return payload
  if (!isRecord(payload)) return []
  if (Array.isArray(payload.models)) return payload.models
  if (isRecord(payload.models)) return Object.values(payload.models)
  return Object.values(payload)
}

function readCatalogLabDescriptions(...payloads: unknown[]) {
  const descriptions = new Map<string, string>()
  const add = (value: unknown, fallbackId?: string) => {
    if (!isRecord(value)) return
    const description = stringValue(value.description)
    if (!description) return
    const id = stringValue(value.id) ?? fallbackId
    const name = stringValue(value.name)
    const title = stringValue(value.title)
    const keys = [id, name, title]
    keys.forEach((key) => {
      if (!key) return
      descriptions.set(catalogLabSlug(key), description)
    })
  }
  const addCollection = (value: unknown) => {
    if (Array.isArray(value)) {
      value.forEach((item) => add(item))
      return
    }
    if (!isRecord(value)) return
    Object.entries(value).forEach(([key, item]) => add(item, key))
  }

  payloads.forEach((payload) => {
    if (Array.isArray(payload)) {
      payload.forEach((item) => add(item))
      return
    }
    if (!isRecord(payload)) return
    addCollection(payload.labs)
    addCollection(payload.providers)
    Object.entries(payload).forEach(([key, value]) => add(value, key))
  })

  return descriptions
}

async function fetchCatalogPayload(url: string) {
  return fetch(url)
    .then((response): Promise<unknown> => (response.ok ? (response.json() as Promise<unknown>) : Promise.resolve()))
    .catch(() => undefined)
}

async function fetchLabCatalogPayload(url: string) {
  return fetch(url)
    .then((response) => (response.ok ? response.text() : Promise.resolve("")))
    .then(readLabSearchIndex)
    .catch(() => undefined)
}

function readLabSearchIndex(html: string) {
  const match = /<script[^>]*id=["']search-index["'][^>]*>([\s\S]*?)<\/script>/.exec(html)
  if (!match) return undefined
  const parsed = JSON.parse(match[1]) as unknown
  if (!Array.isArray(parsed)) return undefined
  return parsed.filter((item) => isRecord(item) && item.type === "lab")
}

function readCatalogCosts(payload: unknown) {
  const costs = new Map<string, ModelCatalogCost>()
  const add = (model: unknown, provider?: string) => {
    if (!isRecord(model)) return
    const id = stringValue(model.id)
    const cost = readCatalogCost(model.cost)
    if (!id || !cost) return
    costs.set(catalogIdKey(id), cost)
    costs.set(catalogSlug(id), cost)
    if (provider && !id.includes("/")) costs.set(`${catalogSlug(provider)}/${catalogSlug(id)}`, cost)
  }

  if (Array.isArray(payload)) {
    payload.forEach((model) => add(model))
    return costs
  }
  if (!isRecord(payload)) return costs

  Object.entries(payload).forEach(([key, value]) => {
    if (!isRecord(value)) return
    if (isRecord(value.models)) {
      Object.values(value.models).forEach((model) => add(model, stringValue(value.id) ?? key))
      return
    }
    add(value)
  })
  return costs
}

function readCatalogCost(value: unknown): ModelCatalogCost | undefined {
  if (!isRecord(value)) return undefined
  const input = numberValue(value.input)
  const output = numberValue(value.output)
  if (input === undefined || output === undefined) return undefined
  return {
    input,
    output,
    cacheRead: numberValue(value.cache_read),
    cacheWrite: numberValue(value.cache_write),
  }
}

function readCatalogLimit(value: unknown) {
  if (!isRecord(value)) return undefined
  return {
    context: numberValue(value.context),
    output: numberValue(value.output),
  }
}

function readCatalogModalities(value: unknown) {
  if (!isRecord(value)) return { input: [], output: [] }
  return {
    input: stringArrayValue(value.input),
    output: stringArrayValue(value.output),
  }
}

function readCatalogWeights(value: unknown) {
  if (!Array.isArray(value)) return []
  return value.flatMap((item) => {
    if (!isRecord(item)) return []
    const label = stringValue(item.label)
    const url = stringValue(item.url)
    return label && url ? [{ label, url }] : []
  })
}

function readCatalogBenchmarks(value: unknown) {
  if (!Array.isArray(value)) return []
  return value.flatMap((item) => {
    if (!isRecord(item)) return []
    const name = stringValue(item.name)
    const score = numberValue(item.score)
    return name && score !== undefined
      ? [
          {
            name,
            score,
            metric: stringValue(item.metric),
            harness: stringValue(item.harness),
            variant: stringValue(item.variant),
            dataset: stringValue(item.dataset),
            version: stringValue(item.version),
            source: stringValue(item.source),
          },
        ]
      : []
  })
}

function displayDateTime(value: string | undefined) {
  return value ? new Date(value).getTime() || 0 : 0
}

function catalogIdKey(value: string) {
  return value.split("/").map(catalogSlug).join("/")
}

function catalogLabSlug(value: string) {
  const slug = catalogSlug(value)
  const aliases: Record<string, string> = {
    moonshot: "moonshotai",
    qwen: "alibaba",
    zhipu: "zhipuai",
    zai: "zhipuai",
  }
  return aliases[slug] ?? slug
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

function stringValue(value: unknown) {
  return typeof value === "string" && value.trim() ? value : undefined
}

function numberValue(value: unknown) {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined
}

function booleanValue(value: unknown) {
  return value === true
}

function stringArrayValue(value: unknown) {
  return Array.isArray(value)
    ? value.filter((item): item is string => typeof item === "string" && item.trim() !== "")
    : []
}

export function SectionHeading(props: { href: string; title: string; description?: string; slot?: string }) {
  return (
    <h2 data-slot={props.slot ?? "section-title"}>
      <strong>
        <a data-slot="heading-link" href={props.href}>
          <span data-slot="heading-anchor" aria-hidden="true">
            #
          </span>
          {props.title}
          {props.description ? "." : ""}
        </a>
      </strong>
      {props.description && (
        <>
          {" "}
          <span>{props.description}</span>
        </>
      )}
    </h2>
  )
}

import { getStatsHomeData } from "@opencode/stats-core/domain/home"
import { runtime } from "@opencode/stats-core/runtime"
import {
  canonicalFamilyComparisonPath,
  canonicalModelComparisonPath,
  comparisonFamilies,
  comparisonSitemapModels,
  latestFamilyComparisonPath,
  resolveComparisonFamily,
} from "../lib/comparison-pages"
import { baseUrl } from "../lib/language"
import { catalogModelPath, findModelCatalogEntry, loadModelCatalog } from "./model-catalog"

type SitemapEntry = {
  path: string
  lastmod?: string
}

export async function GET() {
  const [catalog, stats] = await Promise.all([
    loadModelCatalog(),
    runtime.runPromise(getStatsHomeData()).catch(() => undefined),
  ])
  const lastmod = sitemapDate(
    stats?.updatedAt,
    ...catalog.models.map((model) => model.lastUpdated ?? model.releaseDate),
  )
  const families = comparisonFamilies.flatMap((family) => {
    const resolved = resolveComparisonFamily(catalog, family.slug)
    return resolved ? [resolved] : []
  })
  const familyComparisons = families.flatMap((first, index) =>
    families.slice(index + 1).map((second) => ({
      path: canonicalFamilyComparisonPath(first, second),
      lastmod: sitemapDate(
        stats?.updatedAt,
        first.model.lastUpdated ?? first.model.releaseDate,
        second.model.lastUpdated ?? second.model.releaseDate,
      ),
    })),
  )
  const models = comparisonSitemapModels(catalog, stats?.leaderboard["All Users"]["2M"])
  const modelComparisons = models.flatMap((first, index) =>
    models.slice(index + 1).flatMap((second) => {
      if (latestFamilyComparisonPath(catalog, first, second)) return []
      return [
        {
          path: canonicalModelComparisonPath(first, second),
          lastmod: sitemapDate(
            stats?.updatedAt,
            first.lastUpdated ?? first.releaseDate,
            second.lastUpdated ?? second.releaseDate,
          ),
        },
      ]
    }),
  )
  const labPages = catalog.labs.map((lab) => ({
    path: `/data/${lab.id}`,
    lastmod: sitemapDate(stats?.updatedAt, ...lab.models.map((model) => model.lastUpdated ?? model.releaseDate)),
  }))
  // Skip entries whose URL resolves to another model, such as stats aliases.
  const modelPages = [...catalog.models, ...(catalog.aliases ?? [])]
    .filter((model) => findModelCatalogEntry(catalog, model.slug, model.lab)?.id === model.id)
    .map((model) => ({
      path: catalogModelPath(model),
      lastmod: sitemapDate(stats?.updatedAt, model.lastUpdated ?? model.releaseDate),
    }))
  const entries = uniqueSitemapEntries([
    { path: "/data/", lastmod: sitemapDate(stats?.updatedAt) },
    { path: "/data/compare", lastmod },
    ...labPages,
    ...modelPages,
    ...familyComparisons,
    ...modelComparisons,
  ])

  return new Response(sitemapXml(entries), {
    headers: {
      "Cache-Control": "public, max-age=300, s-maxage=3600, stale-while-revalidate=86400",
      "Content-Type": "application/xml; charset=utf-8",
    },
  })
}

function uniqueSitemapEntries(entries: SitemapEntry[]) {
  return Object.values(
    entries.reduce<Record<string, SitemapEntry>>((result, entry) => {
      result[entry.path] = entry
      return result
    }, {}),
  ).toSorted((a, b) => a.path.localeCompare(b.path))
}

function sitemapXml(entries: SitemapEntry[]) {
  const urls = entries
    .map(
      (entry) => `  <url>
    <loc>${escapeXml(new URL(entry.path, baseUrl).toString())}</loc>${
      entry.lastmod
        ? `
    <lastmod>${entry.lastmod}</lastmod>`
        : ""
    }
  </url>`,
    )
    .join("\n")
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls}
</urlset>`
}

function sitemapDate(...values: (string | undefined | null)[]) {
  const dates = values.flatMap((value) => {
    if (!value) return []
    const date = new Date(value)
    return Number.isNaN(date.getTime()) ? [] : [date]
  })
  if (dates.length === 0) return undefined
  return new Date(Math.min(Date.now(), Math.max(...dates.map((date) => date.getTime())))).toISOString().slice(0, 10)
}

function escapeXml(value: string) {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
}

import { LOCALE_HEADER } from "../lib/language"

// Stats change throughout the day; expired snapshots must refresh before reuse.
export const statsPageCacheControl = "public, max-age=60, s-maxage=300, must-revalidate"

export function setStatsPageCacheHeaders(headers: Headers | undefined) {
  if (!headers) return

  headers.set("Cache-Control", statsPageCacheControl)
  // The same URL serves Markdown to clients that ask for it.
  appendVary(headers, "Accept", "Accept-Language", "Cookie", LOCALE_HEADER)
}

function appendVary(headers: Headers, ...values: string[]) {
  const existing = headers
    .get("vary")
    ?.split(",")
    .map((value) => value.trim())
    .filter(Boolean)

  headers.set(
    "vary",
    values
      .reduce(
        (result, value) =>
          result.some((item) => item.toLowerCase() === value.toLowerCase()) ? result : [...result, value],
        existing ?? [],
      )
      .join(", "),
  )
}

import { Effect } from "effect"

export function runStatsEffect<A, E>(effect: Effect.Effect<A, E>) {
  return Effect.runPromise(effect)
}

