    red: "#fca5a5",
    orange: "#fdba74",
    yellow: "#fde047",
    green: "#86efac",
    cyan: "#67e8f9",
    blue: "#93c5fd",
    purple: "#d8b4fe",
  },
  dark: {
    red: "#b91c1c",
    orange: "#c2410c",
    yellow: "#a16207",
