async function formAnswer(dialog: ReturnType<typeof useDialog>, title: string, fields: FormFields) {
  const answer: FormAnswer = {}
  for (const field of fields) {
    if (!active(field, answer)) continue
    const value = field.type !== "external" && field.hidden ? field.default : await fieldAnswer(dialog, title, field)
    if (value === CANCELLED) return null
    if (value !== undefined) answer[field.key] = value
  }
  return answer
}

function active(field: FormField, answer: FormAnswer) {
  if (field.type === "external" || !field.when) return true
  return field.when.every((when) => {
    const value = answer[when.key]
    if (value === undefined) return false
    const hit = Array.isArray(value) ? value.includes(String(when.value)) : value === when.value
    return when.op === "eq" ? hit : !hit
  })
}

function fieldAnswer(
  dialog: ReturnType<typeof useDialog>,
  title: string,
  field: FormField,
): Promise<FormValue | undefined | typeof CANCELLED> {
  if (field.type === "external") return externalAnswer(dialog, title, field)
  if (field.type === "multiselect") return multiselectAnswer(dialog, title, field)
  if (field.type === "boolean" || (field.type === "string" && field.options)) {
    return selectAnswer(dialog, title, field)
  }
  return textAnswer(dialog, title, field)
}

async function selectAnswer(
  dialog: ReturnType<typeof useDialog>,
  title: string,
  field: Extract<FormAnswerField, { type: "boolean" | "string" }>,
): Promise<FormValue | undefined | typeof CANCELLED> {
  if (field.type === "string" && field.custom)
    return new Promise((resolve) => {
      dialog.replace(
        () => <StringChoiceField field={field} onSubmit={resolve} />,
        () => resolve(CANCELLED),
      )
    })
  const options =
    field.type === "boolean"
      ? field.default === false
        ? [
            { title: "No", value: false as FormValue },
            { title: "Yes", value: true as FormValue },
          ]
        : [
            { title: "Yes", value: true as FormValue },
            { title: "No", value: false as FormValue },
          ]
      : (field.options ?? []).map((option) => ({
          title: option.label,
          value: option.value as FormValue,
          description: option.description,
        }))
  return new Promise<FormValue | undefined | typeof CANCELLED>((resolve) => {
    dialog.replace(
      () => (
        <DialogSelect<FormValue | undefined>
          title={formLabel(field) || title}
          options={[...options, ...(!field.required ? [{ title: "Skip", value: undefined }] : [])]}
          current={field.type === "string" ? field.default : undefined}
          onSelect={(option) => resolve(option.value)}
        />
      ),
      () => resolve(CANCELLED),
    )
  })
}

function StringChoiceField(props: {
  field: Extract<FormAnswerField, { type: "string" }>
  onSubmit: (value: string | undefined) => void
}) {
  const dialog = useDialog()
  const theme = useTheme().surface("dialog")
  const dimensions = useTerminalDimensions()
  const rows = formRows(props.field)
  const count = rows.length + (props.field.required ? 1 : 2)
  const [store, setStore] = createStore({
    selected: formSelected(props.field, props.field.default),
    editing: false,
    text: formInitialValues([props.field]).custom[props.field.key] ?? "",
    error: "",
  })
  const [textarea, setTextarea] = createSignal<TextareaRenderable>()
  let scroll: ScrollBoxRenderable | undefined
  createEffect(() => {
    const row = scroll?.getChildren()[store.selected]
    if (row) scroll?.scrollChildIntoView(row.id)
  })
  const fg = (index: number) => (store.selected === index ? theme.text.formfield.focused : theme.text.formfield.base)
  const submit = (value: string | undefined) => {
    const invalid = formValidateValue(props.field, value)
    if (invalid) return setStore("error", invalid)
    props.onSubmit(value)
  }
  const select = (index: number) => {
    setStore({ selected: index, error: "" })
    if (index === rows.length) return setStore("editing", true)
    submit(index < rows.length ? String(rows[index].value) : undefined)
  }
  const back = () => setStore({ editing: false, text: textarea()?.plainText ?? store.text, error: "" })
  Keymap.createLayer(() => ({
    mode: "modal",
    enabled: !store.editing,
    commands: [
      {
        id: "dialog.select.prev",
        title: "Previous answer",
        group: "Form",
        run: () => setStore("selected", (store.selected + count - 1) % count),
      },
      {
        id: "dialog.select.next",
        title: "Next answer",
        group: "Form",
        run: () => setStore("selected", (store.selected + 1) % count),
      },
      { id: "dialog.select.submit", title: "Select answer", group: "Form", run: () => select(store.selected) },
    ],
  }))
  Keymap.createLayer(() => ({
    mode: "modal",
    priority: 1,
    target: textarea,
    enabled: store.editing,
    commands: [
      {
        id: "dialog.prompt.submit",
        title: "Submit answer",
        group: "Form",
        run: () => submit(textarea()?.plainText.trim() || undefined),
      },
      { bind: "escape", title: "Back to answers", group: "Form", run: back },
    ],
  }))
  return (
    <DialogLayout
      header={<DialogHeader title={formLabel(props.field)} onClose={() => (store.editing ? back() : dialog.clear())} />}
      footer={{
        actions: {
          secondary: store.editing
            ? [
                { title: "submit", key: "enter", onTrigger: () => submit(textarea()?.plainText.trim() || undefined) },
                { title: "back", key: "esc", onTrigger: back },
              ]
            : [
                { title: "select", key: "↑/↓" },
                { title: "confirm", key: "enter", onTrigger: () => select(store.selected) },
                { title: "cancel", key: "esc", onTrigger: () => dialog.clear() },
              ],
        },
      }}
    >
      <box gap={1}>
        <Show when={props.field.description}>
          {(description) => <text fg={theme.text.muted}>{description()}</text>}
        </Show>
        <scrollbox
          gap={1}
          height={Math.min(
            count + rows.filter((row) => row.description).length,
            Math.max(3, Math.floor(dimensions().height / 2) - 6),
          )}
          scrollbarOptions={{ visible: false }}
          ref={(value: ScrollBoxRenderable) => {
            scroll = value
          }}
        >
          <For each={rows}>
            {(row, index) => (
              <box onMouseUp={() => select(index())}>
                <text fg={fg(index())}>
                  {index() + 1}. {row.label}
                </text>
                <Show when={row.description}>
                  {(description) => (
                    <box paddingLeft={3}>
                      <text fg={theme.text.muted}>{description()}</text>
                    </box>
                  )}
                </Show>
              </box>
            )}
          </For>
          <box flexDirection="row" gap={1} onMouseUp={() => select(rows.length)}>
            <text fg={fg(rows.length)}>{rows.length + 1}.</text>
            <Show
              when={store.editing}
              fallback={<text fg={fg(rows.length)}>{store.text || "Type your own answer"}</text>}
            >
              <textarea
                height={1}
                flexGrow={1}
                wrapMode="none"
                initialValue={store.text}
                placeholder={props.field.placeholder ?? "Type your own answer"}
                placeholderColor={theme.text.muted}
                textColor={theme.text.formfield.focused}
                focusedTextColor={theme.text.formfield.focused}
                cursorColor={theme.text.formfield.focused}
                ref={(value: TextareaRenderable) => {
                  setTextarea(value)
                  value.traits = { status: "ANSWER" }
                  queueMicrotask(() => {
                    if (value.isDestroyed) return
                    value.focus()
                    value.gotoLineEnd()
                  })
                }}
                onContentChange={() => {
                  const text = textarea()?.plainText ?? ""
                  setStore("text", text)
                  if (store.error && !formValidateValue(props.field, text.trim() || undefined)) setStore("error", "")
                }}
              />
            </Show>
          </box>
          <Show when={!props.field.required}>
            <text fg={fg(rows.length + 1)} onMouseUp={() => select(rows.length + 1)}>
              {rows.length + 2}. Skip
            </text>
          </Show>
        </scrollbox>
        <Show when={store.error}>{(error) => <text fg={theme.text.feedback.error.base}>{error()}</text>}</Show>
      </box>
    </DialogLayout>
  )
}

function textAnswer(
  dialog: ReturnType<typeof useDialog>,
  title: string,
  field: Extract<FormAnswerField, { type: "string" | "number" | "integer" }>,
  initial = field.default === undefined ? undefined : String(field.default),
): Promise<FormValue | undefined | typeof CANCELLED> {
  return new Promise<FormValue | undefined | typeof CANCELLED>((resolve) => {
    dialog.replace(
      () => {
        const theme = useTheme().surface("dialog")
        const [error, setError] = createSignal<string>()
        return (
          <DialogPrompt
            title={formLabel(field) || title}
            placeholder={field.type === "string" ? field.placeholder : undefined}
            value={initial}
            onConfirm={(input) => {
              const text = input.trim()
              const value = text === "" && !field.required ? undefined : field.type === "string" ? text : Number(text)
              const invalid = formValidateValue(field, value)
              if (invalid) {
                setError(invalid)
                return
              }
              resolve(value)
            }}
            description={() => (
              <box gap={1}>
                <Show when={field.description}>
                  {(description) => <text fg={theme.text.muted}>{description()}</text>}
                </Show>
                <Show when={error()}>{(value) => <text fg={theme.text.feedback.error.base}>{value()}</text>}</Show>
              </box>
            )}
          />
        )
      },
      () => resolve(CANCELLED),
    )
  })
}

async function multiselectAnswer(
  dialog: ReturnType<typeof useDialog>,
  title: string,
  field: Extract<FormAnswerField, { type: "multiselect" }>,
): Promise<FormValue | typeof CANCELLED> {
  const selected = field.default ? [...field.default] : []
  while (true) {
    const invalid = formValidateValue(field, selected)
    const choice = await new Promise<string | typeof CUSTOM | typeof SUBMIT | typeof CANCELLED>((resolve) => {
      dialog.replace(
        () => (
          <DialogSelect<string | typeof CUSTOM | typeof SUBMIT>
            title={formLabel(field) || title}
            options={[
              ...field.options.map((option) => ({
                title: `[${selected.includes(option.value) ? "x" : " "}] ${option.label}`,
                value: option.value,
                description: option.description,
                disabled:
                  !selected.includes(option.value) && field.maxItems !== undefined && selected.length >= field.maxItems,
              })),
              ...(field.custom ? [{ title: "Type your own answer", value: CUSTOM as typeof CUSTOM }] : []),
              {
                title: "Continue",
                value: SUBMIT as typeof SUBMIT,
                description: invalid,
                disabled: invalid !== undefined,
              },
            ]}
            onSelect={(option) => resolve(option.value)}
          />
        ),
        () => resolve(CANCELLED),
      )
    })
    if (choice === CANCELLED) return CANCELLED
    if (choice === SUBMIT) return selected
    if (choice === CUSTOM) {
      const value = await customAnswer(dialog, title, field)
      if (value === CANCELLED) return CANCELLED
      if (value && !selected.includes(value)) selected.push(value)
      continue
    }
    selected.splice(0, selected.length, ...formToggleMultiselect(selected, choice))
  }
}

function customAnswer(
  dialog: ReturnType<typeof useDialog>,
  title: string,
  field: Extract<FormAnswerField, { type: "multiselect" }>,
): Promise<string | typeof CANCELLED> {
  return new Promise<string | typeof CANCELLED>((resolve) => {
    dialog.replace(
      () => (
        <DialogPrompt
          title={formLabel(field) || title}
          placeholder="Type your own answer"
          onConfirm={(value) => {
            if (value) resolve(value)
          }}
        />
      ),
      () => resolve(CANCELLED),
    )
  })
}

async function externalAnswer(
  dialog: ReturnType<typeof useDialog>,
  title: string,
  field: Extract<FormField, { type: "external" }>,
): Promise<true | typeof CANCELLED> {
  let opened = false
  while (true) {
    const choice = await new Promise<true | typeof OPEN | typeof CANCELLED>((resolve) => {
      dialog.replace(
        () => (
          <DialogSelect<true | typeof OPEN>
            title={formLabel(field) || title}
            options={[
              { title: opened ? "Open link again" : "Open link", value: OPEN as typeof OPEN, description: field.url },
              { title: "I finished", value: true as const, description: field.description, disabled: !opened },
            ]}
            onSelect={(option) => resolve(option.value)}
          />
        ),
        () => resolve(CANCELLED),
      )
    })
    if (choice === CANCELLED) return CANCELLED
    if (choice === true) return true
    const result = await new Promise<boolean | typeof CANCELLED>((resolve) => {
      dialog.replace(
        () => <OAuthView title={formLabel(field) || title} message="Opening link…" />,
        () => resolve(CANCELLED),
      )
      void openUrl(field.url).then(
        () => resolve(true),
        () => resolve(false),
      )
    })
    if (result === CANCELLED) return CANCELLED
    opened ||= result
  }
}

async function connected(
  integration: IntegrationInfo,
  location: LocationRef,
  data: ReturnType<typeof useData>,
  dialog: ReturnType<typeof useDialog>,
  toast: ReturnType<typeof useToast>,
  onConnected?: OnIntegrationConnected,
) {
  data.location.integration.invalidate(location)
  data.location.model.invalidate(location)
  data.location.provider.invalidate(location)
  await Promise.all([
    data.location.integration.sync(location),
    data.location.model.sync(location),
    data.location.provider.sync(location),
  ])
  toast.show({ variant: "success", message: `Connected ${integration.name}` })
  if (onConnected && integration.metadata?.source !== "mcp") {
    onConnected(providerID(data, location, integration.id))
    return
  }
  dialog.clear()
}

function providerID(data: ReturnType<typeof useData>, location: LocationRef, integrationID: string) {
  const models = data.location.model.list(location) ?? []
  const matches = (data.location.provider.list(location) ?? []).filter(
    (provider) => provider.integrationID === integrationID || provider.id === integrationID,
  )
  return (
    matches.find((provider) =>
      models.some((model) => model.providerID === provider.id && model.status !== "deprecated"),
    )?.id ?? matches[0]?.id
  )
}

function locationQuery(location: LocationRef) {
  return { directory: location.directory }
}

import { createEffect, createMemo, createSignal, Show } from "solid-js"
import { useData } from "../context/data"
import { useClient } from "../context/client"
import { pipe, sortBy } from "remeda"
import { DialogSelect } from "../ui/dialog-select"
import { useDialog } from "../ui/dialog"
import { useTheme } from "../context/theme"
import { TextAttributes } from "@opentui/core"
import type { McpServer } from "@opencode/client"
import { useToast } from "../ui/toast"
import { DialogErrorDetails } from "./dialog-error-details"
import { DialogIntegration } from "./dialog-integration"
import { useLocation } from "../context/location"

function statusError(status: McpServer["status"]) {
  if (status.status === "failed" || status.status === "needs_auth") return status.error
  return undefined
}

function Status(props: { status: McpServer["status"]; loading: boolean }) {
  if (props.loading || props.status.status === "pending") {
    return <>Connecting …</>
  }
  if (props.status.status === "connected") {
    return <span style={{ attributes: TextAttributes.BOLD }}>Connected ✓</span>
  }
  if (props.status.status === "failed") {
    return <>Failed !</>
  }
  if (props.status.status === "needs_auth") {
    return <>Sign in required →</>
  }
  return <>Disabled ○</>
}

export function DialogMcp(props: { initialServer?: string; details?: boolean } = {}) {
  const data = useData()
  const dialog = useDialog()
  const client = useClient()
  const location = useLocation()
  const toast = useToast()
  const theme = useTheme().surface("dialog")
  const current = () => location.ref ?? data.location.default()
  const servers = createMemo(() =>
    pipe(
      data.location.mcp.server.list(current()) ?? [],
      sortBy((server) => server.name),
    ),
  )
  const initial = props.initialServer ? servers().find((server) => server.name === props.initialServer) : undefined
  const [focused, setFocused] = createSignal<string | undefined>(props.initialServer)
  const [detail, setDetail] = createSignal<McpServer | undefined>(
    props.details && initial?.status.status === "failed" ? initial : undefined,
  )
  const [loading, setLoading] = createSignal<ReadonlySet<string>>(new Set())

  const statusColor = (status: McpServer["status"]) => {
    if (status.status === "connected") return theme.text.feedback.success.base
    if (status.status === "failed") return theme.text.feedback.error.base
    if (status.status === "needs_auth") return theme.text.feedback.warning.base
    return theme.text.muted
  }

  createEffect(() => {
    if (focused()) return
    const first = servers()[0]
    if (first) setFocused(first.name)
  })

  const options = createMemo(() => {
    const loadingMcp = loading()
    return servers().map((server) => {
      const pending = loadingMcp.has(server.name) || server.status.status === "pending"
      return {
        value: server.name,
        title: server.name,
        footer: <Status status={server.status} loading={pending} />,
        footerColor: pending ? theme.text.muted : statusColor(server.status),
      }
    })
  })

  const focusedServer = createMemo(() => servers().find((server) => server.name === focused()))

  const toggleTitle = createMemo(() => {
    const status = focusedServer()?.status.status
    if (status === "connected") return "disconnect"
    if (status === "failed") return "retry"
    if (status === "needs_auth") return "sign in"
    return "connect"
  })

  const focusedError = createMemo(() => {
    const server = focusedServer()
    // Enter starts sign-in for auth-gated integrations instead of showing the auth reason
    if (server?.status.status === "needs_auth" && server.integrationID) return undefined
    return server ? statusError(server.status) : undefined
  })

  const select = (name: string | undefined) => {
    const server = servers().find((entry) => entry.name === name)
    if (!server) return
    if (server.status.status === "needs_auth" && server.integrationID) {
      dialog.replace(() => <DialogIntegration integrationID={server.integrationID} autoConnect />)
      return
    }
    if (!statusError(server.status)) return
    setDetail(server)
  }

  // Auth-gated servers enter the integration flow; other inactive states retry the connection.
  // The mcp.status.changed event refreshes the list, so no manual sync is needed.
  const toggle = (name: string) => {
    if (loading().has(name)) return
    const server = servers().find((entry) => entry.name === name)
    if (!server || server.status.status === "pending") return
    if (server.status.status === "needs_auth" && server.integrationID) {
      select(name)
      return
    }
    setLoading((prev) => new Set(prev).add(name))
    const target = current()
    const input = { server: name, location: { directory: target.directory } }
    const call = server.status.status === "connected" ? client.api.mcp.disconnect(input) : client.api.mcp.connect(input)
    void call.catch(toast.error).finally(() =>
      setLoading((prev) => {
        const next = new Set(prev)
        next.delete(name)
        return next
      }),
    )
  }

  return (
    <box>
      <Show
        when={detail()}
        fallback={
          <DialogSelect
            title="MCP servers"
            searchInTitle
            titlePlaceholder="Search MCP servers"
            options={options()}
            preserveSelection
            onMove={(option) => setFocused(option.value as string)}
            onSelect={(option) => select(option.value as string)}
            actions={[
              {
                title: toggleTitle(),
                command: "dialog.mcp.toggle",
                onTrigger: (option) => {
                  setFocused(option.value as string)
                  toggle(option.value as string)
                },
              },
            ]}
            footerHints={focusedError() ? [{ title: "view error", label: "enter", group: "primary" }] : []}
          />
        }
      >
        {(server) => (
          <DialogErrorDetails
            title={`MCP server: ${server().name}`}
            error={statusError(server().status) ?? "Unknown MCP connection error"}
            context={`Status: ${server().status.status}\nConfiguration: mcp.servers.${server().name}${
              server().integrationID ? `\nIntegration: ${server().integrationID}` : ""
            }`}
            onBack={() => {
              setDetail(undefined)
              dialog.setSize("medium")
            }}
          />
        )}
      </Show>
    </box>
  )
}

import { createMemo, createSignal } from "solid-js"
import { useLocal } from "../context/local"
import { DialogSelect } from "../ui/dialog-select"
import { useDialog } from "../ui/dialog"
import { DialogIntegration } from "./dialog-integration"
import { DialogVariant } from "./dialog-variant"
import * as fuzzysort from "fuzzysort"
import { useConnected } from "./use-connected"
import { useData } from "../context/data"
import { modelPreferenceKey } from "../model-preference"
import { useLocation } from "../context/location"
import { useNewDesigns } from "../config"

export function DialogModel(props: { providerID?: string }) {
  const local = useLocal()
  const newDesigns = useNewDesigns()
  const data = useData()
  const dialog = useDialog()
  const location = useLocation()
  const [query, setQuery] = createSignal("")
  const favoritePriority = new Set(local.model.favorite().map(modelPreferenceKey))

  const connected = useConnected()
  const providers = createMemo(
    () => new Map((data.location.provider.list(location.ref) ?? []).map((item) => [item.id, item])),
  )
  const models = createMemo(() => data.location.model.list(location.ref) ?? [])

  const showExtra = createMemo(() => connected() && !props.providerID)

  const options = createMemo(() => {
    const needle = query().trim()
    const showSections = showExtra() && needle.length === 0
    const favorites = connected() ? local.model.favorite() : []
    const recents = local.model.recent()

    function toOptions(items: typeof favorites, category: string) {
      if (!showSections) return []
      return items.flatMap((item) => {
        const model = models().find((model) => model.providerID === item.providerID && model.id === item.modelID)
        if (!model) return []
        const provider = providers().get(model.providerID)
        return [
          {
            key: item,
            value: { providerID: model.providerID, modelID: model.id },
            title: model.name,
            releaseDate: model.time.released,
            description: provider?.name ?? model.providerID,
            category,
            footer: free(model) ? "Free" : undefined,
            onSelect: () => {
              onSelect(model.providerID, model.id)
            },
          },
        ]
      })
    }

    const favoriteOptions = toOptions(favorites, "Favorites")
    const recentOptions = toOptions(
      recents.filter(
        (item) => !favorites.some((fav) => fav.providerID === item.providerID && fav.modelID === item.modelID),
      ),
      "Recent",
    )

    const modelOptions = sortModelOptions(
      models()
        .filter((model) => model.status !== "deprecated")
        .filter((model) => (props.providerID ? model.providerID === props.providerID : true))
        .map((model) => {
          const provider = providers().get(model.providerID)
          const key = modelPreferenceKey({ providerID: model.providerID, modelID: model.id })
          const favorite = favorites.some((item) => modelPreferenceKey(item) === key)
          return {
            value: { providerID: model.providerID, modelID: model.id },
            providerID: model.providerID,
            providerName: provider?.name ?? model.providerID,
            title: model.name,
            releaseDate: model.time.released,
            description: favorite ? "(Favorite)" : undefined,
            category: connected() ? (provider?.name ?? model.providerID) : undefined,
            footer: free(model) ? "Free" : undefined,
            onSelect() {
              onSelect(model.providerID, model.id)
            },
          }
        })
        .filter((option) => {
          if (!showSections) return true
          if (
            favorites.some(
              (item) => item.providerID === option.value.providerID && item.modelID === option.value.modelID,
            )
          )
            return false
          if (
            recents.some((item) => item.providerID === option.value.providerID && item.modelID === option.value.modelID)
          )
            return false
          return true
        }),
      connected(),
    )

    if (needle) {
      return prioritizeFavorites(
        sortModelOptions(
          fuzzysort.go(needle, modelOptions, { keys: ["title", "category"] }).map((item) => item.obj),
          false,
        ),
        favoritePriority,
      )
    }

    return [...favoriteOptions, ...recentOptions, ...modelOptions]
  })

  const provider = createMemo(() => (props.providerID ? providers().get(props.providerID) : undefined))

  const title = createMemo(() => {
    const value = provider()
    if (!value) return "Select model"
    return value.name
  })

  function onSelect(providerID: string, modelID: string) {
    local.model.set({ providerID, modelID }, { recent: true })
    const list = local.model.variant.list()
    const cur = local.model.variant.current()
    if (cur && list.includes(cur)) {
      dialog.clear()
      return
    }
    if (list.length > 0) {
      dialog.replace(() => <DialogVariant />)
      return
    }
    dialog.clear()
  }

  return (
    <DialogSelect<ReturnType<typeof options>[number]["value"]>
      searchInTitle
      titlePlaceholder="Search models"
      options={options()}
      actions={[
        {
          command: "model.dialog.provider",
          title: newDesigns()
            ? connected()
              ? "connect integration"
              : "view all integrations"
            : connected()
              ? "Connect an integration"
              : "View all integrations",
          selection: "none",
          onTrigger() {
            dialog.replace(() => (
              <DialogIntegration
                onConnected={(providerID) => dialog.replace(() => <DialogModel providerID={providerID} />)}
              />
            ))
          },
        },
        {
          command: "model.dialog.favorite",
          title: newDesigns() ? "favorite" : "Favorite",
          hidden: !connected(),
          onTrigger: (option) => {
            local.model.toggleFavorite(option.value as { providerID: string; modelID: string })
          },
        },
      ]}
      onFilter={setQuery}
      flat={true}
      skipFilter={true}
      title={title()}
      current={local.model.current()}
      focusCurrent={false}
    />
  )
}

export function prioritizeFavorites<T extends { value: { providerID: string; modelID: string } }>(
  options: T[],
  favorites: Set<string>,
) {
  return options.toSorted(
    (a, b) => Number(favorites.has(modelPreferenceKey(b.value))) - Number(favorites.has(modelPreferenceKey(a.value))),
  )
}

export function sortModelOptions<
  T extends {
    providerID?: string
    providerName?: string
    releaseDate: string | number
    title: string
    footer?: string
  },
>(options: T[], grouped = true) {
  return options.toSorted((a, b) => {
    const provider = grouped
      ? Number(b.providerID === "opencode-go") - Number(a.providerID === "opencode-go") ||
        Number(b.providerID === "opencode") - Number(a.providerID === "opencode")
      : 0
    if (provider !== 0) return provider

    const name = grouped ? (a.providerName ?? "").localeCompare(b.providerName ?? "") : 0
    if (name !== 0) return name

    const free = Number(b.footer === "Free") - Number(a.footer === "Free")
    if (free !== 0) return free

    const release = Number(b.releaseDate) - Number(a.releaseDate)
    if (release !== 0) return release

    return a.title.localeCompare(b.title)
  })
}

function free(model: { cost: Array<{ input: number }> }) {
  return model.cost.length > 0 && model.cost.every((cost) => cost.input === 0)
}

import { batch, createEffect, createMemo, createResource, createSignal, onCleanup, Show } from "solid-js"
import type { OpenCodeEvent, SessionInfo } from "@opencode/client"
import path from "path"
import { useTerminalDimensions } from "@opentui/solid"
import { DIALOG_LIST_INSET, dialogWidth, useDialog } from "../ui/dialog"
import { DialogSelect, dialogSelectContentWidth, type DialogSelectRef } from "../ui/dialog-select"
import { DialogPrompt } from "../ui/dialog-prompt"
import { useRoute } from "../context/route"
import { useData } from "../context/data"
import { useClient } from "../context/client"
import { useLocation } from "../context/location"
import { useSessionTabs } from "../context/session-tabs"
import { useTheme } from "../context/theme"
import { Keymap } from "../context/keymap"
import { Locale } from "../util/locale"
import { abbreviateHome } from "../runtime"
import { useTuiPaths } from "../context/runtime"
import { truncateFilePath } from "../ui/file-path"
import { useToast } from "../ui/toast"
import { errorMessage } from "../util/error"
import { stringWidth } from "../util/string-width"
import { withTimestampedFallback } from "@opencode/util/session-title-fallback"
import { sessionStatusGutter } from "./dialog-session-list"
import { Spinner } from "./spinner"
import { projectName } from "../util/project"

const RECENT_LIMIT = 8
export const DialogOpenKey = Symbol("DialogOpen")

type OpenTarget =
  | { type: "session"; sessionID: string }
  | { type: "project"; directory: string; projectID?: string }

type OpenView = { type: "projects" } | { type: "worktrees"; projectID: string }

type OpenSelection = { view: OpenView; filter: string; selected?: OpenTarget }

export function DialogOpen(props: { sessions: SessionInfo[]; onLoad: (sessions: SessionInfo[]) => void }) {
  const dialog = useDialog()
  const route = useRoute()
  const data = useData()
  const client = useClient()
  const location = useLocation()
  const sessionTabs = useSessionTabs()
  const toast = useToast()
  const theme = useTheme().surface("dialog")
  const paths = useTuiPaths()
  const dimensions = useTerminalDimensions()
  const shortcuts = Keymap.useShortcuts()
  const [filter, setFilter] = createSignal("")
  const [selectionMoved, setSelectionMoved] = createSignal(false)
  let closed = false
  onCleanup(() => {
    closed = true
  })
  const [recent] = createResource(() => {
    // A late read must not overwrite deletion or placement facts observed in flight.
    const changed = new Map<string, Extract<OpenCodeEvent, { type: "session.deleted" | "session.moved" }>>()
    const unsubscribe = client.event.listen((message) => {
      const event = message.details
      if (event.type === "session.deleted" || event.type === "session.moved") changed.set(event.data.sessionID, event)
    })
    onCleanup(unsubscribe)
    return client.api.session
      .list({ limit: 50, order: "desc", parentID: null })
      .then((response) => {
        if (!closed)
          props.onLoad(
            response.data.flatMap((session) => {
              const event = changed.get(session.id)
              if (!event) return [session]
              if (event.type === "session.deleted") return []
              return [moveOpenSession(props.sessions.find((entry) => entry.id === session.id) ?? session, event)]
            }),
          )
        return true
      })
      .catch(() => false)
      .finally(unsubscribe)
  })
  const [projects] = createResource(() =>
    data.project.sync().then(
      () => true,
      () => false,
    ),
  )
  const [view, setView] = createSignal<OpenView>({ type: "projects" })
  const projectID = () => {
    const current = view()
    return current.type === "worktrees" ? current.projectID : undefined
  }
  const [focus, setFocus] = createSignal<OpenTarget>()
  const [creation, setCreation] = createSignal<OpenSelection>()
  const [creating, setCreating] = createSignal(false)
  let projectsSelection: OpenSelection | undefined
  let select: DialogSelectRef<OpenTarget> | undefined
  let pending: OpenSelection | undefined
  function snapshot(): OpenSelection {
    return { view: view(), filter: select?.filter ?? "", selected: select?.selected?.value }
  }
  function restore(next: OpenSelection) {
    batch(() => {
      setView(next.view)
      setSelectionMoved(false)
      setFocus(next.selected)
      select?.setFilter(next.filter)
    })
    if (next.selected) select?.moveTo(next.selected)
  }
  function back() {
    if (projectsSelection) restore(projectsSelection)
  }
  function newWorktree() {
    if (!projectID()) return
    setCreation(snapshot())
  }
  function cancelCreation() {
    pending = creation()
    setCreation(undefined)
  }
  const [worktrees, worktreeActions] = createResource(projectID, (projectID) =>
    client.api.worktree.list({ projectID }).catch((error: unknown) => {
      toast.show({ title: "Loading worktrees failed", message: errorMessage(error), variant: "error" })
      return []
    }),
  )

  const refreshed = new Set<string>()
  createEffect(() => {
    const id = projectID()
    if (!id || worktrees.latest === undefined || refreshed.has(id)) return
    refreshed.add(id)
    void client.api.worktree.refresh({ projectID: id }).catch(() => undefined)
  })
  onCleanup(
    client.event.on("worktree.updated", (event) => {
      if (event.data.projectID === projectID()) void worktreeActions.refetch()
    }),
  )

  const [matched] = createResource(
    () => {
      const value = filter().trim()
      return /^ses_[0-9A-Za-z]{26}$/.test(value) ? value : undefined
    },
    (sessionID) =>
      client.api.session
        .get({ sessionID })
        .then((session) => (session.id === sessionID ? session : undefined))
        .catch(() => undefined),
  )

  const openTabs = createMemo(
    () => new Set(sessionTabs.enabled() ? sessionTabs.tabs().map((tab) => tab.sessionID) : []),
  )
  const currentSessionID = createMemo(() =>
    route.data.type === "session" ? data.session.root(route.data.sessionID) : undefined,
  )
  const attention = (sessionID: string) => sessionTabs.status(sessionID).attention
  const sessions = createMemo(() => {
    const seen = new Set<string>()
    const match = matched()
    const list = [...data.session.list(), ...props.sessions, ...(match ? [match] : [])].filter((session) => {
      if (session.parentID || seen.has(session.id)) return false
      seen.add(session.id)
      return true
    })
    const attentionByID = new Map(list.map((session) => [session.id, Boolean(attention(session.id))]))
    return list.toSorted((a, b) => {
      const attentionA = attentionByID.get(a.id) ?? false
      const attentionB = attentionByID.get(b.id) ?? false
      if (attentionA !== attentionB) return attentionA ? -1 : 1
      return b.time.updated - a.time.updated
    })
  })

  createEffect(() => {
    const knownRoots = new Set(props.sessions.map((session) => session.id))
    const active = data.session.active()
    active.forEach((id) => {
      void data.session.permission.sync(id).catch(() => undefined)
      void data.session.form.sync(id).catch(() => undefined)
    })
    new Set(
      [
        ...data.session.permission.sessions(),
        ...data.session.form.sessions(),
        ...(recent() === true ? active : []),
      ].map((id) => data.session.root(id)),
    ).forEach((rootID) => {
      if (!knownRoots.has(rootID) && !data.session.get(rootID)) {
        void data.session.sync(rootID).catch(() => undefined)
      }
    })
  })

  const options = createMemo(() => {
    const tabs = openTabs()
    const currentID = currentSessionID()
    // With an empty query the menu shows what is not already one keystroke away: open tabs are
    // visible in the strip, so recents exclude them unless a background session is awaiting input.
    // Typing widens the pool to every session so matching a loaded tab by name still switches to it.
    const candidates = sessions().filter(
      (session) => !tabs.has(session.id) || (attention(session.id) && session.id !== currentID),
    )
    const attentionCount = candidates.filter((session) => attention(session.id)).length
    const recent = filter().trim() ? sessions() : candidates.slice(0, Math.max(RECENT_LIMIT, attentionCount))
    const sessionOptions = recent.map((session) => {
      const project = data.project.get(session.projectID)
      const name = projectName(project)
      const basename = path.basename(session.location.directory)
      const label =
        name && session.location.directory !== project?.canonical && name.toLowerCase() !== basename.toLowerCase()
          ? `${name} · ${basename}`
          : name || basename
      const state = attention(session.id)
      const running =
        !state &&
        (data.session.status(session.id) === "running" ||
          data.session.family(session.id).some((id) => data.session.status(id) === "running"))
      return {
        title: withTimestampedFallback(session),
        searchText: `${session.id} ${session.location.directory}`,
        value: { type: "session", sessionID: session.id } as OpenTarget,
        category: "Sessions",
        footer: `${label ? `${Locale.truncate(label, 30)} · ` : ""}${timeAgo(session.time.updated)}`,
        onSelect: () => location.set(session.location),
        gutter: sessionStatusGutter(
          theme,
          state,
          running,
          tabs.has(session.id) ? () => <text fg={theme.hue.accent[200]}>▪</text> : undefined,
        ),
      }
    })

    const current = location.ref ?? data.location.default()
    const projectOptions = data.project
      .list()
      .filter((project) => project.canonical !== "/")
      // Historical project identities can share a checkout. The list is newest-active first.
      .filter((project, index, projects) => projects.findIndex((item) => item.canonical === project.canonical) === index)
      .map((project) => ({ directory: project.canonical, project }))
      .map((item) => {
        const title =
          item.directory === item.project?.canonical
            ? (projectName(item.project) ?? path.basename(item.directory))
            : path.basename(item.directory)
        const footer = abbreviateHome(item.directory, paths.home)
        const git = item.project?.vcs === "git"
        const width =
          dialogSelectContentWidth(Math.min(dialogWidth("large"), dimensions().width - 2)) -
          stringWidth(title) -
          (git ? 2 : 0)
        return {
          title,
          footer: `${truncateFilePath(footer, width)}${git ? " →" : ""}`,
          searchText: `${footer} ${projectName(item.project) ?? ""}`,
          value: {
            type: "project",
            directory: item.directory,
            ...(git ? { projectID: item.project!.id } : {}),
          } as OpenTarget,
          category: "Projects",
          gutter:
            item.directory === current.directory ||
            item.directory === location.current?.project.canonical
              ? () => <text fg={theme.text.formfield.selected}>●</text>
              : undefined,
        }
      })

    return [...sessionOptions, ...projectOptions]
  })

  const worktreeOptions = createMemo(() => {
    const id = projectID()
    if (!id) return []
    const project = data.project.get(id)
    if (!project) return []
    const current = location.ref ?? data.location.default()
    const directories = [
      project.canonical,
      ...(worktrees.loading ? [] : (worktrees() ?? [])).map((worktree) => worktree.directory),
    ]
    const width = Math.max(
      0,
      dialogSelectContentWidth(Math.min(dialogWidth("large"), dimensions().width - 2)) -
        Math.max(
          ...directories.map((directory) =>
            stringWidth(
              directory === project.canonical
                ? (projectName(project) ?? path.basename(directory))
                : path.basename(directory),
            ),
          ),
        ),
    )
    return directories
      .filter((directory, index) => directories.indexOf(directory) === index)
      .toSorted((a, b) => {
        if (a === project.canonical) return -1
        if (b === project.canonical) return 1
        if (a === current.directory) return -1
        if (b === current.directory) return 1
        return 0
      })
      .map((directory) => {
        const title =
          directory === project.canonical
            ? (projectName(project) ?? path.basename(directory))
            : path.basename(directory)
        const footer = truncateFilePath(abbreviateHome(directory, paths.home), width)
        return {
          title,
          footer: footer + " ".repeat(Math.max(0, width - stringWidth(footer))),
          value: { type: "project", directory } as OpenTarget,
          gutter:
            directory === current.directory ? () => <text fg={theme.text.formfield.selected}>●</text> : undefined,
        }
      })
  })

  return (
    <box>
      <Show
        when={creation()}
        fallback={
          <DialogSelect
            ref={(value) => {
              select = value
              dialog.setSize("large")
              if (!pending) return
              const previous = pending
              pending = undefined
              restore(previous)
            }}
            title={projectID() ? `${projectName(data.project.get(projectID()!)) ?? "Project"} / Worktrees` : "Open"}
            placeholder={projectID() ? "Search worktrees…" : "Search sessions and projects…"}
            options={projectID() ? worktreeOptions() : options()}
            current={
              currentSessionID() ? ({ type: "session", sessionID: currentSessionID()! } as OpenTarget) : undefined
            }
            focusTarget={focus()}
            focusCurrent={focus() !== undefined}
            sectionNavigation={true}
            preserveSelection={selectionMoved()}
            onMove={() => {
              setSelectionMoved(true)
            }}
            onCancel={view().type === "projects" ? undefined : back}
            onFilter={setFilter}
            emptyView={
              <Show when={!recent.loading && !projects.loading}>
                <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
                  <text fg={theme.text.muted}>No recent sessions or projects</text>
                </box>
              </Show>
            }
            footer={
              <Show
                when={
                  projectID()
                    ? worktrees.loading
                    : recent.loading || projects.loading || recent() === false || projects() === false
                }
              >
                <box>
                  <Show when={projectID() && worktrees.loading}>
                    <Spinner color={theme.text.muted}>Loading worktrees…</Spinner>
                  </Show>
                  <Show when={!projectID() && (recent.loading || projects.loading)}>
                    <Spinner color={theme.text.muted}>Refreshing sessions and projects…</Spinner>
                  </Show>
                  <Show when={!projectID() && (recent() === false || projects() === false)}>
                    <text fg={theme.text.feedback.error.base}>
                      Could not refresh{" "}
                      {recent() === false ? (projects() === false ? "sessions and projects" : "sessions") : "projects"}.
                    </text>
                  </Show>
                </box>
              </Show>
            }
            bindings={[
              ...(!projectID()
                ? [
                    {
                      bind: "right",
                      title: "Show project worktrees",
                      group: "Dialog",
                      run: () => {
                        const target = select?.selected?.value
                        if (target?.type !== "project" || !target.projectID) return
                        projectsSelection = snapshot()
                        restore({
                          view: { type: "worktrees", projectID: target.projectID },
                          filter: "",
                          selected: {
                            type: "project",
                            directory: target.directory,
                          },
                        })
                      },
                    },
                  ]
                : []),
              ...(projectID()
                ? [
                    {
                      bind: "left",
                      title: "Return to projects",
                      group: "Dialog",
                      run: back,
                    },
                    { bind: "ctrl+n", title: "New worktree", group: "Dialog", run: newWorktree },
                  ]
                : []),
            ]}
            footerHints={[...(projectID() ? [{ title: "new worktree", label: "ctrl+n" }] : [])]}
            noMatchView={
              <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
                <text fg={theme.text.muted}>
                  {projectID()
                    ? worktrees.loading
                      ? "Loading worktrees…"
                      : "No matching worktrees"
                    : recent.loading || projects.loading || matched.loading
                      ? "Searching sessions and projects…"
                      : shortcuts.get("session.list")
                        ? `No matches · search all sessions with ${shortcuts.get("session.list")}`
                        : "No matches"}
                </text>
              </box>
            }
            onSelect={(option) => {
              dialog.clear()
              if (option.value.type === "session") {
                route.navigate({ type: "session", sessionID: option.value.sessionID })
                return
              }
              const target = {
                directory: option.value.directory,
              }
              route.navigate({ type: "home", location: target })
              location.set(target)
            }}
          />
        }
      >
        <DialogPrompt
          size="large"
          title={`${projectName(data.project.get(projectID()!)) ?? "Project"} / New worktree`}
          placeholder="Worktree name (optional)"
          description={() => <text fg={theme.text.muted}>Leave blank for a random name.</text>}
          busy={creating()}
          busyText="Creating worktree…"
          onCancel={cancelCreation}
          onConfirm={(value) => {
            const id = projectID()!
            const previous = creation()
            setCreating(true)
            void client.api.worktree
              .create({
                projectID: id,
                ...(value.trim() ? { name: value.trim() } : {}),
              })
              .then((created) => {
                if (closed || creation() !== previous) return
                const target = {
                  directory: created.directory,
                }
                dialog.clear()
                route.navigate({ type: "home", location: target })
                location.set(target)
              })
              .catch((error: unknown) =>
                toast.show({ title: "Creating worktree failed", message: errorMessage(error), variant: "error" }),
              )
              .finally(() => setCreating(false))
          }}
        />
      </Show>
    </box>
  )
}

export function moveOpenSession(session: SessionInfo, event: Extract<OpenCodeEvent, { type: "session.moved" }>) {
  return {
    ...session,
    location: event.data.location,
    projectID: event.data.projectID ?? session.projectID,
    subpath: event.data.subpath,
    time: { ...session.time, updated: Math.max(session.time.updated, event.created) },
  }
}

function timeAgo(timestamp: number) {
  const minutes = Math.floor((Date.now() - timestamp) / 60_000)
  if (minutes < 1) return "now"
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours}h`
  const days = Math.floor(hours / 24)
  if (days < 30) return `${days}d`
  const months = Math.floor(days / 30)
  if (months < 12) return `${months}mo`
  return `${Math.floor(days / 365)}y`
}

import { TextAttributes } from "@opentui/core"
import { useTerminalDimensions } from "@opentui/solid"
import { createMemo, createResource, createSignal, For, Show } from "solid-js"
import { renderUnicodeCompact } from "uqr"
import { useClient } from "../context/client"
import { useTheme } from "../context/theme"
import { DialogHeader, DialogLayout, useDialog } from "../ui/dialog"
import { Link } from "../ui/link"
import { errorMessage } from "../util/error"

export function DialogPair() {
  const client = useClient()
  const dialog = useDialog()
  const dimensions = useTerminalDimensions()
  const theme = useTheme().surface("dialog")
  const [loadError, setLoadError] = createSignal<unknown>()

  dialog.setSize("large")
  dialog.setCentered(true)

  const [info] = createResource(() =>
    Promise.all([client.api.server.info(), client.api.server.pair()])
      .then(([server, pairing]) => {
        const link = (url: string) => new URL(`/auth/connect/${pairing.code}`, url).href
        const local = server.urls[0] ? new URL(server.urls[0]) : undefined
        if (local) local.hostname = "localhost"
        return {
          links: server.urls.map(link),
          localhost: local ? link(local.href) : undefined,
          minutes: Math.round(pairing.expires_in / 60),
          loopback: server.urls.some((url) => ["localhost", "127.0.0.1", "[::1]"].includes(new URL(url).hostname)),
        }
      })
      .catch((error) => {
        setLoadError(error)
        return undefined
      }),
  )
  const horizontal = createMemo(() => dimensions().width >= 96)
  const content = () => {
    const value = info()
    if (!value) return
    return (
      <box flexDirection={horizontal() ? "row" : "column"} alignItems={horizontal() ? "flex-start" : "center"} gap={2}>
        <box width={horizontal() ? 29 : "100%"} flexShrink={0} gap={1}>
          <text fg={theme.text.muted} wrapMode="word">
            Open a link to connect. Links work once and expire in {value.minutes} minutes.
          </text>
          <Show when={value.localhost}>
            {(url) => (
              <box>
                <text fg={theme.text.muted}>This device</text>
                <Link href={url()} fg={theme.text.base}>
                  {url()}
                </Link>
              </box>
            )}
          </Show>
          <box>
            <text fg={theme.text.muted}>Links</text>
            <For each={value.links}>
              {(url) => (
                <Link href={url} fg={theme.text.base}>
                  {url}
                </Link>
              )}
            </For>
          </box>
          <Show when={value.loopback}>
            <text fg={theme.text.muted} wrapMode="word">
              Run `opencode service set hostname 0.0.0.0` to access the service remotely.
            </text>
          </Show>
        </box>
        <box
          width={horizontal() ? undefined : "100%"}
          flexGrow={horizontal() ? 1 : 0}
          flexShrink={0}
          alignItems={horizontal() ? "flex-end" : "center"}
        >
          <Show when={value.links[0]}>
            {(url) => <text fg={theme.text.base}>{renderUnicodeCompact(url(), { border: 1 })}</text>}
          </Show>
        </box>
      </box>
    )
  }

  return (
    <DialogLayout header={<DialogHeader title="Pair" />}>
      <Show
        when={loadError()}
        fallback={
          <Show when={info()} fallback={<text fg={theme.text.muted}>Loading server information…</text>}>
            <Show
              when={dimensions().height >= 36}
              fallback={
                <scrollbox
                  height={Math.max(8, dimensions().height - Math.floor(dimensions().height / 4) - 6)}
                  scrollbarOptions={{ visible: false }}
                >
                  {content()}
                </scrollbox>
              }
            >
              {content()}
            </Show>
          </Show>
        }
      >
        {(error) => (
          <box>
            <text fg={theme.text.feedback.error.base} attributes={TextAttributes.BOLD}>
              Could not load server information
            </text>
            <text fg={theme.text.muted}>{errorMessage(error())}</text>
            <text fg={theme.text.muted}>Close and reopen Pair to try again.</text>
          </box>
        )}
      </Show>
    </DialogLayout>
  )
}

import { createMemo, createResource, createSignal, onMount, Show, type JSX } from "solid-js"
import path from "path"
import type { SessionInfo } from "@opencode/client"
import { Project } from "@opencode/schema/project"
import { TextAttributes, type RGBA } from "@opentui/core"
import { DIALOG_LIST_INSET, useDialog } from "../ui/dialog"
import { DialogSelect } from "../ui/dialog-select"
import { useRoute } from "../context/route"
import { useData } from "../context/data"
import { Keymap } from "../context/keymap"
import { Locale } from "../util/locale"
import { useTheme } from "../context/theme"
import { useClient } from "../context/client"
import { useLocal } from "../context/local"
import { createDebouncedSignal } from "../util/signal"
import { useToast } from "../ui/toast"
import { DialogSessionRename } from "./dialog-session-rename"
import { Spinner } from "./spinner"
import { errorMessage } from "../util/error"
import { useSessionTabs } from "../context/session-tabs"
import { useStorage } from "../context/storage"
import { useConfig, useNewDesigns } from "../config"
import { withTimestampedFallback } from "@opencode/util/session-title-fallback"
import { projectName } from "../util/project"
import { useLocation } from "../context/location"

export function DialogSessionList() {
  const dialog = useDialog()
  const route = useRoute()
  const data = useData()
  const theme = useTheme().surface("dialog")
  const client = useClient()
  const local = useLocal()
  const sessionTabs = useSessionTabs()
  const config = useConfig().data
  const newDesigns = useNewDesigns()
  const toast = useToast()
  const activeLocation = useLocation()
  const [filter, setFilter] = createSignal("")
  const shortcuts = Keymap.useShortcuts()
  const [search, setSearch] = createDebouncedSignal("", 150)
  const [toDelete, setToDelete] = createSignal<string>()
  const [prefs, updatePrefs] = useStorage().store("session-list", {
    initial: { allProjects: config.tabs?.scope !== "cwd" },
  })
  const allProjects = () => prefs.allProjects
  const pickerLocation = () =>
    (route.data.type === "session" ? data.session.get(route.data.sessionID)?.location : undefined) ??
    activeLocation.ref ??
    data.location.default()

  const [searchResults, { mutate: setSearchResults }] = createResource(
    () => ({
      query: search().trim(),
      allProjects: allProjects(),
      location: pickerLocation(),
    }),
    async ({ query, allProjects, location }) => {
      try {
        if (!data.location.info(location)) await data.location.sync(location)
        const current = data.location.info(location)
        if (!current) throw new Error("Location unavailable")
        const response = await client.api.session.list({
          ...(allProjects
            ? {}
            : current.project.id === Project.ID.global
              ? { directory: current.directory }
              : {
                  project: current.project.id,
                  subpath: path.relative(current.project.directory, current.directory).replaceAll("\\", "/"),
                }),
          ...(query ? { search: query } : {}),
          limit: 50,
          order: "desc",
          parentID: null,
        })
        return { query, allProjects, sessions: response.data, error: undefined }
      } catch (error) {
        // A transient transport failure must degrade search, not crash the TUI
        // through the root ErrorBoundary when the errored resource is read.
        return { query, allProjects, sessions: [] as SessionInfo[], error }
      }
    },
  )

  const currentSessionID = createMemo(() => (route.data.type === "session" ? route.data.sessionID : undefined))
  const localSessions = createMemo(() => {
    const query = filter().trim().toLowerCase()
    const current = data.location.info(pickerLocation())
    const sessions = data.session
      .list()
      .filter(
        (session) =>
          allProjects() ||
          (session.projectID === current?.project.id && session.location.directory === current.directory),
      )
    if (!query) return sessions
    return sessions.filter(
      (session) => !session.parentID && withTimestampedFallback(session).toLowerCase().includes(query),
    )
  })
  const sessions = createMemo(() => {
    const query = filter().trim()
    const local = localSessions()
    if (query !== search().trim()) return searchResults.latest?.sessions ?? local
    if (searchResults.loading) return searchResults.latest?.sessions ?? []
    const result = searchResults()
    if (result?.query !== query || result.allProjects !== allProjects() || result.error) return local
    return result.sessions
  })
  const searchState = createMemo(() => {
    const query = filter().trim()
    if (query !== search().trim() || searchResults.loading)
      return { message: query ? "Searching sessions…" : "Loading sessions…", error: false }
    const result = searchResults()
    if (result?.query === query && result.error)
      return {
        message: query ? "Could not search sessions. Change the search to try again." : "Could not load sessions.",
        error: true,
      }
    return { message: query ? "No sessions found" : "No sessions available", error: false }
  })

  const quickSwitchHint = createMemo(() => {
    if (sessionTabs.enabled()) return
    const first = shortcuts.get("session.quick_switch.1")
    const last = shortcuts.get("session.quick_switch.9")
    if (!first || !last) return
    return quickSwitchRange(first, last)
  })
  const quickSwitchFooterHints = createMemo(() => {
    const hint = quickSwitchHint()
    return hint && local.session.slots().length > 0 ? [{ title: "switch", label: hint }] : []
  })
  const currentProjectName = createMemo(() => {
    const current = data.location.info(pickerLocation())
    if (!current) return ""
    const project = data.project.get(current.project.id)
    return projectName(project) ?? ""
  })

  const options = createMemo(() => {
    const today = new Date().toDateString()
    const sessionMap = new Map(
      sessions()
        .filter((session) => !session.parentID)
        .map((session) => [session.id, session]),
    )
    const pinned = sessionTabs.enabled() ? [] : local.session.pinned().filter((sessionID) => sessionMap.has(sessionID))
    const pinnedSet = new Set(pinned)
    const slotByID = new Map(local.session.slots().map((sessionID, index) => [sessionID, index + 1]))

    const option = (session: SessionInfo, category: string) => {
      const directory = session.location.directory
      const project = data.project.get(session.projectID)
      const root = session.subpath ? path.resolve(directory, ...session.subpath.split("/").map(() => "..")) : directory
      const relative = path.relative(project?.canonical ?? root, root)
      const footer =
        relative.startsWith("..") || path.isAbsolute(relative)
          ? Locale.truncate(path.basename(relative), 25)
          : undefined
      const slot = sessionTabs.enabled() ? undefined : slotByID.get(session.id)
      const deleting = toDelete() === session.id
      const attention = sessionTabs.status(session.id).attention
      return {
        title: deleting
          ? `Press ${shortcuts.get("session.delete")} again to confirm`
          : withTimestampedFallback(session),
        value: session.id,
        category,
        footer,
        bg: deleting ? theme.background.action.destructive.focused : undefined,
        fg: deleting ? theme.text.action.destructive.focused : undefined,
        gutter: sessionStatusGutter(
          theme,
          attention,
          !attention &&
            (data.session.status(session.id) === "running" ||
              data.session.family(session.id).some((id) => data.session.status(id) === "running")),
          slot === undefined ? undefined : () => <text fg={theme.hue.accent[200]}>{slot}</text>,
        ),
      }
    }

    const remaining = sessions()
      .filter((session) => !session.parentID && !pinnedSet.has(session.id))
      .map((session) => {
        const date = new Date(session.time.updated).toDateString()
        return option(session, date === today ? "Today" : date)
      })

    return [...pinned.map((sessionID) => option(sessionMap.get(sessionID)!, "Pinned")), ...remaining]
  })

  onMount(() => dialog.setSize("large"))

  return (
    <DialogSelect
      title="Sessions"
      titleView={
        <box flexDirection="row">
          <text fg={theme.text.base} attributes={TextAttributes.BOLD}>
            Sessions
          </text>
          <Show when={!allProjects() && currentProjectName()}>
            <text fg={theme.text.muted}> for {currentProjectName()}</text>
          </Show>
        </box>
      }
      searchInTitle
      titlePlaceholder={
        !allProjects() && currentProjectName() ? `Search sessions in ${currentProjectName()}` : "Search sessions"
      }
      options={options()}
      skipFilter={true}
      current={currentSessionID()}
      onFilter={(query) => {
        setFilter(query)
        setSearch(query)
      }}
      bindings={[
        {
          bind: "ctrl+a",
          title: allProjects() ? "Show current directory sessions" : "Show all project sessions",
          group: "Dialog",
          run: () => {
            void updatePrefs((draft) => {
              draft.allProjects = !draft.allProjects
            }).catch(() => {})
          },
        },
      ]}
      emptyView={
        <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
          <text fg={searchState().error ? theme.text.feedback.error.base : theme.text.muted}>
            {searchState().message}
          </text>
        </box>
      }
      noMatchView={
        <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
          <text fg={searchState().error ? theme.text.feedback.error.base : theme.text.muted}>
            {searchState().message}
          </text>
        </box>
      }
      onMove={() => setToDelete(undefined)}
      onSelect={(option) => {
        route.navigate({ type: "session", sessionID: option.value })
        dialog.clear()
      }}
      actions={[
        {
          command: "session.pin.toggle",
          title: "pin/unpin",
          hidden: sessionTabs.enabled(),
          onTrigger: (option) => local.session.togglePin(option.value),
        },
        {
          command: "session.delete",
          title: "delete",
          onTrigger: (option: { value: string }) => {
            if (toDelete() !== option.value) {
              setToDelete(option.value)
              return
            }
            void client.api.session
              .remove({ sessionID: option.value })
              .then(() => {
                setSearchResults((result) =>
                  result
                    ? { ...result, sessions: result.sessions.filter((session) => session.id !== option.value) }
                    : result,
                )
              })
              .catch((error) => {
                setToDelete(undefined)
                toast.show({
                  message: `Failed to delete session: ${errorMessage(error)}`,
                  variant: "error",
                  duration: 5000,
                })
              })
          },
        },
        {
          command: "session.rename",
          title: "rename",
          onTrigger: (option: { value: string; title: string }) =>
            DialogSessionRename.show(dialog, option.value, option.title),
        },
      ]}
      footerHints={[
        ...(newDesigns() ? [] : quickSwitchFooterHints()),
        { title: allProjects() ? "current directory" : "all projects", label: "ctrl+a", side: "right" },
      ]}
    />
  )
}

function quickSwitchRange(first: string, last: string) {
  const prefix = first.slice(0, -1)
  if (first.endsWith("1") && last === `${prefix}9`) return `${prefix}1-9`
  return `${first} through ${last}`
}

export function sessionStatusGutter(
  theme: ReturnType<ReturnType<typeof useTheme>["surface"]>,
  attention: "permission" | "question" | false,
  running: boolean,
  fallback?: () => JSX.Element,
) {
  if (attention) {
    return (color: RGBA) => (
      <text
        fg={color === theme.text.action.primary.focused ? color : theme.text.feedback.warning.base}
        attributes={TextAttributes.BOLD}
      >
        {attention === "permission" ? "!" : "?"}
      </text>
    )
  }
  if (running) return (color: RGBA) => <Spinner color={color} />
  return fallback
}

import { DialogPrompt } from "../ui/dialog-prompt"
import { type DialogContext, useDialog } from "../ui/dialog"
import { useClient } from "../context/client"
import { useToast } from "../ui/toast"
import { errorMessage } from "../util/error"

export function DialogSessionRename(props: { sessionID: string; currentTitle?: string }) {
  const dialog = useDialog()
  const client = useClient()
  const toast = useToast()

  return (
    <DialogPrompt
      title="Rename session"
      placeholder="Session title"
      value={props.currentTitle}
      onConfirm={(value) => {
        const title = value.trim()
        if (!title) return
        void client.api.session
          .update({ sessionID: props.sessionID, title })
          .then(() => dialog.clear())
          .catch((error) =>
            toast.show({
              message: `Failed to rename session: ${errorMessage(error)}`,
