import { TextAttributes, type ScrollBoxRenderable } from "@opentui/core"
import { useTerminalDimensions } from "@opentui/solid"
import { isShellNotFoundError, type LocationRef, type ShellInfo } from "@opencode/client"
import { createEffect, createMemo, createSignal, onCleanup, Show, untrack } from "solid-js"
import stripAnsi from "strip-ansi"
import { useClient } from "../context/client"
import { Keymap } from "../context/keymap"
import { useTheme } from "../context/theme"
import { DialogFooter, DialogHeader, DialogLayout, useDialog } from "../ui/dialog"

const PAGE_BYTES = 64 * 1024

export function DialogShellOutput(props: { shell: ShellInfo; location: LocationRef }) {
  const client = useClient()
  const dialog = useDialog()
  const theme = useTheme().surface("dialog")
  const dimensions = useTerminalDimensions()
  const [info, setInfo] = createSignal(props.shell)
  const [output, setOutput] = createSignal<string>()
  const [omitted, setOmitted] = createSignal(false)
  const [error, setError] = createSignal("")
  const text = createMemo(() => stripAnsi(output() ?? "").replace(/\r\n?/g, "\n"))
  const height = () => Math.max(3, Math.floor(dimensions().height * 0.6) - 6)
  let scroll: ScrollBoxRenderable | undefined

  dialog.setSize("xlarge")
  dialog.setCentered(true)

  createEffect(() => {
    // The running-shell inventory drops exited commands. Keep this view tied to
    // the opened ID and its original Location, not the list's current selection.
    const id = props.shell.id
    const location = { directory: props.location.directory }
    let cursor: number | undefined
    let disposed = false
    let missing = false
    let timer: ReturnType<typeof setTimeout> | undefined

    const load = async () => {
      if (untrack(info).status === "running") {
        const current = await client.api.shell.get({ id, location })
        if (disposed) return false
        setInfo(current.data)
      }
      if (cursor === undefined) {
        const head = await client.api.shell.output({ id, location, cursor: Number.MAX_SAFE_INTEGER })
        if (disposed) return false
        cursor = Math.max(0, head.data.size - PAGE_BYTES)
        setOmitted(cursor > 0)
      }
      const page = await client.api.shell.output({ id, location, cursor, limit: PAGE_BYTES })
      if (disposed) return false
      cursor = page.data.cursor
      setOutput((previous) => {
        const next = (previous ?? "") + page.data.output
        if (next.length > PAGE_BYTES) setOmitted(true)
        return next.slice(-PAGE_BYTES)
      })
      setError("")
      return cursor < page.data.size
    }

    const poll = () => {
      void load()
        .catch((cause: unknown) => {
          if (disposed) return
          missing = isShellNotFoundError(cause)
          setError(missing ? "Shell output is no longer available." : "Unable to read shell output. Retrying…")
        })
        .then((more) => {
          // Poll only while the viewer is open, including after exit so the final
          // file flush is observed. Never overlap reads or reload earlier pages.
          if (!disposed && !missing) timer = setTimeout(poll, more ? 0 : 1_000)
        })
    }
    poll()
    onCleanup(() => {
      disposed = true
      clearTimeout(timer)
    })
  })

  const status = () => {
    if (info().status === "running") return "Running"
    if (info().status === "timeout") return "Timed out"
    if (info().status === "killed") return "Killed"
    return info().exit === undefined ? "Exited" : `Exited · code ${info().exit}`
  }

  Keymap.createLayer(() => ({
    mode: "modal",
    commands: [
      { bind: "up", title: "Scroll output up", group: "Shell", run: () => scroll?.scrollBy(-1) },
      { bind: "down", title: "Scroll output down", group: "Shell", run: () => scroll?.scrollBy(1) },
      { bind: "pageup", title: "Previous output page", group: "Shell", run: () => scroll?.scrollBy(-height()) },
      { bind: "pagedown", title: "Next output page", group: "Shell", run: () => scroll?.scrollBy(height()) },
      { bind: "home", title: "First loaded output", group: "Shell", run: () => scroll?.scrollTo(0) },
      { bind: "end", title: "Follow shell output", group: "Shell", run: () => scroll?.scrollTo(Infinity) },
    ],
  }))

  return (
    <DialogLayout
      header={
        <DialogHeader
          gap={dimensions().width < 60 ? 1 : 2}
          titleView={
            <text fg={theme.text.base} attributes={TextAttributes.BOLD} flexGrow={1}>
              Shell output
            </text>
          }
        >
          <text fg={theme.text.muted}>{status()}</text>
        </DialogHeader>
      }
      legacyFooter={
        <DialogFooter
          actions={{
            secondary: [
              { title: "scroll", key: "↑/↓" },
              { title: "follow", key: "end" },
              { title: "back", key: "esc" },
            ],
          }}
        />
      }
    >
      <box gap={1}>
        <text fg={theme.text.muted} maxHeight={3} wrapMode="word">
          {props.shell.command}
        </text>
        <Show when={omitted()}>
          <text fg={theme.text.muted}>Earlier output omitted · showing recent output</text>
        </Show>
        <scrollbox
          id="shell-output-scroll"
          ref={(value: ScrollBoxRenderable) => (scroll = value)}
          height={height()}
          stickyScroll
          stickyStart="bottom"
          scrollbarOptions={{ visible: false }}
        >
          <text fg={theme.text.base} wrapMode="word">
            {text() ||
              (output() === undefined
                ? "Loading output…"
                : "No captured output. Output redirected to files is not shown here.")}
          </text>
        </scrollbox>
        <Show when={error()}>
          <text fg={theme.text.feedback.error.base}>{error()}</text>
        </Show>
      </box>
    </DialogLayout>
  )
}

import { TextAttributes } from "@opentui/core"
import { DialogSelect, type DialogSelectOption } from "../ui/dialog-select"
import { createResource, createMemo, createSignal, Match, Switch } from "solid-js"
import { DIALOG_LIST_INSET, useDialog } from "../ui/dialog"
import { useTheme } from "../context/theme"
import { errorMessage } from "../util/error"
import { useData } from "../context/data"
import type { LocationRef } from "@opencode/client"

export type DialogSkillProps = {
  location?: LocationRef
  onSelect: (skill: string) => void
}

export function DialogSkill(props: DialogSkillProps) {
  const dialog = useDialog()
  const data = useData()
  const theme = useTheme()
  dialog.setSize("large")

  const [loadError, setLoadError] = createSignal<unknown>()

  const [skills] = createResource(() =>
    Promise.resolve()
      .then(async () => {
        const current = data.location.skill.list(props.location)
        if (current) return current
        await data.location.skill.sync(props.location)
        return data.location.skill.list(props.location) ?? []
      })
      // Catch so the rejected resource never reaches the memo below: reading
      // skills() in an errored state re-throws and tears down the dialog.
      .catch((error) => {
        setLoadError(error)
        return undefined
      }),
  )

  const showError = createMemo(() => Boolean(loadError()))

  const options = createMemo<DialogSelectOption<string>[]>(() => {
    if (showError()) return []
    const list = skills() ?? []
    const maxWidth = Math.max(0, ...list.map((s) => s.name.length))
    return list.map((skill) => ({
      title: skill.name.padEnd(maxWidth),
      description: skill.description?.replace(/\s+/g, " ").trim(),
      value: skill.id,
      onSelect: () => {
        props.onSelect(skill.id)
        dialog.clear()
      },
    }))
  })

  return (
    <DialogSelect
      title="Skills"
      options={options()}
      renderFilter={!showError() && !skills.loading}
      locked={showError() || skills.loading}
      emptyView={
        <Switch
          fallback={
            <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
              <text fg={theme.text.muted}>No skills available</text>
            </box>
          }
        >
          <Match when={showError()}>
            <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
              <text fg={theme.text.feedback.error.base} attributes={TextAttributes.BOLD}>
                Could not load skills
              </text>
              <text fg={theme.text.muted}>{errorMessage(loadError())}</text>
              <text fg={theme.text.muted}>Close and reopen Skills to try again.</text>
            </box>
          </Match>
          <Match when={skills.loading}>
            <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
              <text fg={theme.text.muted}>Loading skills…</text>
            </box>
          </Match>
        </Switch>
      }
      noMatchView={
        <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
          <text fg={theme.text.muted}>No skills found</text>
        </box>
      }
    />
  )
}

import { useDialog } from "../ui/dialog"
import { DialogSelect } from "../ui/dialog-select"
import { createMemo, createSignal } from "solid-js"
import { Locale } from "../util/locale"
import { Keymap } from "../context/keymap"
import { useTheme } from "../context/theme"
import { usePromptStash, type StashEntry } from "../prompt/stash"

function getRelativeTime(timestamp: number): string {
  const now = Date.now()
  const diff = now - timestamp
  const seconds = Math.floor(diff / 1000)
  const minutes = Math.floor(seconds / 60)
  const hours = Math.floor(minutes / 60)
  const days = Math.floor(hours / 24)

  if (seconds < 60) return "just now"
  if (minutes < 60) return `${minutes}m ago`
  if (hours < 24) return `${hours}h ago`
  if (days < 7) return `${days}d ago`
  return Locale.datetime(timestamp)
}

function getStashPreview(input: string, maxLength: number = 50): string {
  const firstLine = input.split("\n")[0].trim()
  return Locale.truncate(firstLine, maxLength)
}

export function DialogStash(props: { onSelect: (entry: StashEntry) => void }) {
  const dialog = useDialog()
  const stash = usePromptStash()
  const theme = useTheme().surface("dialog")
  const shortcuts = Keymap.useShortcuts()

  const [toDelete, setToDelete] = createSignal<number>()

  const options = createMemo(() => {
    const entries = stash.list()
    // Show most recent first
    return entries
      .map((entry, index) => {
        const isDeleting = toDelete() === index
        const lineCount = (entry.prompt.text.match(/\n/g)?.length ?? 0) + 1
        return {
          title: isDeleting
            ? `Press ${shortcuts.get("stash.delete")} again to confirm`
            : getStashPreview(entry.prompt.text),
          bg: isDeleting ? theme.background.action.destructive.focused : undefined,
          fg: isDeleting ? theme.text.action.destructive.focused : undefined,
          value: index,
          description: getRelativeTime(entry.timestamp),
          footer: lineCount > 1 ? `~${lineCount} lines` : undefined,
        }
      })
      .toReversed()
  })

  return (
    <DialogSelect
      title="Stash"
      options={options()}
      onMove={() => {
        setToDelete(undefined)
      }}
      onSelect={(option) => {
        const entries = stash.list()
        const entry = entries[option.value]
        if (entry) {
          stash.remove(option.value)
          props.onSelect(entry)
        }
        dialog.clear()
      }}
      actions={[
        {
          command: "stash.delete",
          title: "delete",
          onTrigger: (option) => {
            if (toDelete() === option.value) {
              stash.remove(option.value)
              setToDelete(undefined)
              return
            }
            setToDelete(option.value)
          },
        },
      ]}
    />
  )
}

import { DialogSelect, type DialogSelectRef } from "../ui/dialog-select"
import { useThemes } from "../context/theme"
import { useDialog } from "../ui/dialog"
import { onCleanup } from "solid-js"

export function DialogThemeList() {
  const themes = useThemes()
  const options = Object.keys(themes.all())
    .sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base" }))
    .map((value) => ({
      title: value,
      value: value,
    }))
  const dialog = useDialog()
  let confirmed = false
  let ref: DialogSelectRef<string>
  const initial = themes.selected

  onCleanup(() => {
    if (!confirmed) themes.set(initial)
  })

  return (
    <DialogSelect
      title="Themes"
      searchInTitle
      titlePlaceholder="Search themes"
      options={options}
      current={initial}
      onMove={(opt) => {
        themes.set(opt.value)
      }}
      onSelect={(opt) => {
        themes.set(opt.value)
        confirmed = true
        dialog.clear()
      }}
      ref={(r) => {
        ref = r
      }}
      onFilter={(query) => {
        if (query.length === 0) {
          themes.set(initial)
          return
        }

        const first = ref.filtered[0]
        if (first) themes.set(first.value)
      }}
    />
  )
}

import { createEffect, createMemo, createResource, createSignal, For, Match, onCleanup, Show, Switch } from "solid-js"
import { Keymap } from "../context/keymap"
import { useNewDesigns } from "../config"
import { useTheme } from "../context/theme"
import type { UpdateState } from "../context/update-notification"
import { DialogHeader, DialogLayout, useDialog } from "../ui/dialog"
import { errorMessage } from "../util/error"
import { Spinner } from "./spinner"

export function DialogUpdate(props: {
  check?: (signal: AbortSignal) => Promise<string | undefined>
  state: () => UpdateState | undefined
  skip: () => void
  install: () => Promise<void>
  restart: () => void
}) {
  const dialog = useDialog()
  const theme = useTheme().surface("dialog")
  const newDesigns = useNewDesigns()
  const [error, setError] = createSignal<string>()
  const [active, setActive] = createSignal(0)
  const controller = new AbortController()
  onCleanup(() => controller.abort())

  dialog.setCentered(true)

  const [check] = createResource(
    () => props.check,
    (check) =>
      check(controller.signal).catch((error) => {
        if (!controller.signal.aborted) setError(errorMessage(error))
        return undefined
      }),
  )
  const state = createMemo(() => {
    const message = error()
    if (message) return { type: "check-failed" as const, message }
    const current = props.state()
    if (current?.type === "installing") return current
    if (check.loading) return { type: "checking" as const }
    const unavailable = check()
    if (unavailable) return { type: "unavailable" as const, message: unavailable }
    return current ?? { type: "current" as const }
  })
  const buttons = createMemo(() => {
    const type = state().type
    if (type === "installing") return []
    const confirm =
      type === "available"
        ? { label: "Update", run: props.install }
        : type === "installed"
          ? { label: "Restart", run: props.restart }
          : undefined
    return [
      {
        label: "Skip",
        run: () => {
          props.skip()
          dialog.clear()
        },
      },
      ...(confirm ? [confirm] : []),
    ]
  })

  createEffect(() => setActive(Math.max(0, buttons().length - 1)))

  Keymap.createLayer(() => ({
    mode: "modal",
    commands: [
      {
        bind: "return",
        title: "Confirm update action",
        group: "Dialog",
        run: () => void buttons()[newDesigns() ? buttons().length - 1 : active()]?.run(),
      },
      ...(newDesigns() ? [] : ["left", "right", "tab", "shift+tab"]).map((bind) => ({
        bind,
        title: bind === "left" || bind === "shift+tab" ? "Previous update action" : "Next update action",
        group: "Dialog",
        run: () => {
          const count = buttons().length
          if (count) setActive((value) => (value + 1) % count)
        },
      })),
    ],
  }))

  return (
    <DialogLayout
      header={
        <DialogHeader
          title={
            state().type === "installing"
              ? "Updating OpenCode"
              : state().type === "available" || state().type === "failed"
                ? "Update available"
                : "Update"
          }
        />
      }
      footer={{
        actions: {
          primary: buttons().map((button, index) => ({
            title: button.label.toLowerCase(),
            key: index === buttons().length - 1 ? "enter" : undefined,
            onTrigger: () => void button.run(),
          })),
        },
      }}
      legacyFooter={
        <Show when={buttons().length > 0}>
          <box flexDirection="row" justifyContent="flex-end">
            <For each={buttons()}>
              {(button, index) => (
                <box
                  paddingLeft={1}
                  paddingRight={1}
                  backgroundColor={active() === index() ? theme.background.action.primary.focused : undefined}
                  onMouseUp={() => void button.run()}
                >
                  <text fg={active() === index() ? theme.text.action.primary.focused : theme.text.muted}>
                    {button.label}
                  </text>
                </box>
              )}
            </For>
          </box>
        </Show>
      }
    >
      <Show when={state()} keyed>
        {(current) => (
          <Switch>
            <Match when={current.type === "checking"}>
              <Spinner shimmer={theme.text.base}>Checking for updates…</Spinner>
            </Match>
            <Match when={current.type === "available"}>
              <text fg={theme.text.muted}>
                An update is available. After installing, you'll be prompted to restart OpenCode.
              </text>
            </Match>
            <Match when={current.type === "installing"}>
              <Spinner shimmer={theme.text.base}>
                {current.type === "installing" ? `Installing OpenCode ${current.version}…` : ""}
              </Spinner>
            </Match>
            <Match when={current.type === "installed"}>
              <text fg={theme.text.muted} wrapMode="word">
                Update successful! A restart is required. Any active sessions will be resumed automatically.
              </text>
            </Match>
            <Match when={current.type === "current"}>
              <text fg={theme.text.muted}>OpenCode is already up to date.</text>
            </Match>
            <Match when={current.type === "unavailable"}>
              <text fg={theme.text.muted} wrapMode="word">
                {current.type === "unavailable" ? current.message : ""}
              </text>
            </Match>
            <Match when={current.type === "failed" || current.type === "check-failed"}>
              <text fg={theme.text.feedback.error.base}>
                {current.type === "failed" || current.type === "check-failed" ? current.message : ""}
              </text>
            </Match>
          </Switch>
        )}
      </Show>
    </DialogLayout>
  )
}

import { createMemo } from "solid-js"
import { useLocal } from "../context/local"
import { DialogSelect } from "../ui/dialog-select"
import { useDialog } from "../ui/dialog"
import { useNewDesigns } from "../config"

export function DialogVariant() {
  const local = useLocal()
  const dialog = useDialog()
  const newDesigns = useNewDesigns()

  const options = createMemo(() => [
    {
      value: "default",
      title: "Default",
      onSelect: () => {
        dialog.clear()
        local.model.variant.set(undefined)
      },
    },
    ...local.model.variant
      .list()
      .filter((variant) => variant !== "default")
      .map((variant) => ({
        value: variant,
        title: variant,
        onSelect: () => {
          dialog.clear()
          local.model.variant.set(variant)
        },
      })),
  ])

  return (
    <DialogSelect<string>
      options={options()}
      title={"Select variant"}
      renderFilter={!newDesigns()}
      current={local.model.variant.current() ?? "default"}
      flat={true}
    />
  )
}

import { useKeyboard, useTerminalDimensions } from "@opentui/solid"
import type { VcsFileStatus } from "@opencode/client"
import { createMemo, For } from "solid-js"
import { createStore } from "solid-js/store"
import { FilePath } from "../ui/file-path"
import { useTheme } from "../context/theme"
import { useConfig, useNewDesigns } from "../config"
import {
  DIALOG_INSET,
  DialogBleed,
  dialogWidth,
  DialogHeader,
  DialogLayout,
  useDialog,
  type DialogContext,
} from "../ui/dialog"
import { getScrollAcceleration } from "../util/scroll"

const options = ["no", "yes"] as const

export type WorkspaceFileChangesChoice = (typeof options)[number]

export function statusLabel(status: VcsFileStatus["status"]) {
  if (status === "added") return "A"
  if (status === "deleted") return "D"
  return "M"
}

function changeCountWidth(file: VcsFileStatus) {
  // The "plus 2" is for spaces
  return `${file.additions ? `+${file.additions}` : ""}${file.deletions ? ` -${file.deletions}` : ""}`.length + 2
}

export function DialogWorkspaceFileChanges(props: {
  files: VcsFileStatus[]
  onSelect: (choice: WorkspaceFileChangesChoice) => void
  title?: string
  message?: string
  /** Footer action for the "yes" choice under the "new-designs" experiment, e.g. `{ title: "delete", key: "d" }`. */
  confirm?: { title: string; key: string }
}) {
  const dialog = useDialog()
  const theme = useTheme().surface("dialog")
  const overlayTheme = useTheme()
  const config = useConfig().data
  const dimensions = useTerminalDimensions()
  const scrollAcceleration = createMemo(() => getScrollAcceleration(config))
  const newDesigns = useNewDesigns()
  const [store, setStore] = createStore({ active: "yes" as WorkspaceFileChangesChoice })
  const height = createMemo(() => Math.min(props.files.length, 8))
  const fileNameWidth = createMemo(() =>
    Math.max(
      2,
      Math.min(dialogWidth("medium"), dimensions().width - 2) -
        DIALOG_INSET * 2 -
        2 -
        Math.max(7, ...props.files.map(changeCountWidth)),
    ),
  )

  function choose(choice: WorkspaceFileChangesChoice) {
    props.onSelect(choice)
    dialog.clear()
  }

  const confirmAction = () => props.confirm ?? { title: "confirm", key: "enter" }

  useKeyboard((evt) => {
    // Escape needs no handling here: the dialog closes on escape, which resolves as a cancel.
    if (newDesigns()) {
      if (evt.name !== (confirmAction().key === "enter" ? "return" : confirmAction().key)) return
      evt.preventDefault()
      evt.stopPropagation()
      choose("yes")
      return
    }
    if (evt.name === "return") {
      evt.preventDefault()
      evt.stopPropagation()
      choose(store.active)
      return
    }
    if (evt.name === "left") {
      evt.preventDefault()
      evt.stopPropagation()
      const index = options.indexOf(store.active)
      setStore("active", options[Math.max(index - 1, 0)])
      return
    }
    if (evt.name === "right") {
      evt.preventDefault()
      evt.stopPropagation()
      const index = options.indexOf(store.active)
      setStore("active", options[Math.min(index + 1, options.length - 1)])
    }
  })

  return (
    <DialogLayout
      header={<DialogHeader title={props.title ?? "File Changes Found"} />}
      footer={{
        actions: {
          primary: [
            { title: "cancel", key: "esc", onTrigger: () => choose("no") },
            { title: confirmAction().title, key: confirmAction().key, onTrigger: () => choose("yes") },
          ],
        },
      }}
      legacyFooter={
        <box flexDirection="row" justifyContent="flex-end">
          <For each={options}>
            {(item) => (
              <box
                paddingLeft={2}
                paddingRight={2}
                backgroundColor={item === store.active ? theme.background.action.primary.focused : undefined}
                onMouseUp={() => {
                  setStore("active", item)
                  props.onSelect(item)
                  dialog.clear()
                }}
              >
                <text fg={item === store.active ? theme.text.action.primary.focused : theme.text.muted}>{item}</text>
              </box>
            )}
          </For>
        </box>
      }
    >
      <box gap={1}>
        <text fg={theme.text.muted} wrapMode="word">
          {props.message ?? "Do you want to move these changes with the session?"}
        </text>
        <DialogBleed>
          <scrollbox
            height={height()}
            backgroundColor={overlayTheme.background.raised.high}
            scrollbarOptions={{ visible: false }}
            scrollAcceleration={scrollAcceleration()}
          >
            <For each={props.files}>
              {(item) => (
                <box
                  flexDirection="row"
                  justifyContent="space-between"
                  paddingLeft={DIALOG_INSET}
                  paddingRight={DIALOG_INSET}
                >
                  <box flexDirection="row" minWidth={0} flexShrink={1}>
                    <box width={2} flexShrink={0}>
                      <text fg={overlayTheme.text.muted}>{statusLabel(item.status)}</text>
                    </box>
                    <FilePath value={item.file} maxWidth={fileNameWidth()} fg={overlayTheme.text.muted} />
                  </box>
                  <box flexDirection="row" gap={1} minWidth={7} flexShrink={0} justifyContent="flex-end">
                    <text>
                      {" "}
                      {item.additions ? (
                        <span style={{ fg: overlayTheme.diff.text.added }}>+{item.additions}</span>
                      ) : null}
                      {item.deletions ? (
                        <span style={{ fg: overlayTheme.diff.text.removed }}> -{item.deletions}</span>
                      ) : null}
                    </text>
                  </box>
                </box>
              )}
            </For>
          </scrollbox>
        </DialogBleed>
      </box>
    </DialogLayout>
  )
}

DialogWorkspaceFileChanges.show = (
  dialog: DialogContext,
  files: VcsFileStatus[],
  options?: { title?: string; message?: string; confirm?: { title: string; key: string } },
) => {
  return new Promise<WorkspaceFileChangesChoice | undefined>((resolve) => {
    dialog.replace(
      () => <DialogWorkspaceFileChanges files={files} onSelect={resolve} {...options} />,
      () => resolve(undefined),
    )
  })
}

import { useTerminalDimensions } from "@opentui/solid"
import { TextAttributes } from "@opentui/core"
import { createEffect, createMemo, createResource, createSignal, onCleanup, onMount, Show } from "solid-js"
import path from "path"
import { DialogSelect, dialogSelectContentWidth, type DialogSelectOption } from "../ui/dialog-select"
import { DIALOG_LIST_INSET, dialogWidth, useDialog } from "../ui/dialog"
import { useClient } from "../context/client"
import { Keymap } from "../context/keymap"
import { useTheme } from "../context/theme"
import { useData } from "../context/data"
import { abbreviateHome } from "../runtime"
import { useTuiPaths } from "../context/runtime"
import { Locale } from "../util/locale"
import { errorMessage } from "../util/error"
import { isRecord } from "../util/record"
import { useToast } from "../ui/toast"
import { Spinner } from "./spinner"
import { DialogWorkspaceFileChanges } from "./dialog-workspace-file-changes"
import type { WorktreeListOutput } from "@opencode/client"
import { useRoute } from "../context/route"
import { DialogWorktreeName } from "./dialog-worktree-name"

export type WorkspaceSelection =
  | { type: "directory"; directory: string; subdirectory: boolean }
  | { type: "new"; name: string }
type ProjectDirectory = WorktreeListOutput[number]

type DialogWorkspacesProps = {
  projectID: string
  location?: { directory: string }
  current?: WorkspaceSelection
  onSelect: (selection: WorkspaceSelection) => void
  onCurrentChange?: (selection: WorkspaceSelection) => void
  initialDirectories?: ReadonlyArray<ProjectDirectory>
  fixture?: boolean
  initialRemoving?: string
}

export function DialogWorkspaces(props: DialogWorkspacesProps) {
  const dialog = useDialog()
  const client = useClient()
  const dimensions = useTerminalDimensions()
  const theme = useTheme().surface("dialog")
  const sessionData = useData()
  const route = useRoute()
  const toast = useToast()
  const paths = useTuiPaths()
  const shortcuts = Keymap.useShortcuts()
  const location = createMemo(() => sessionData.location.info(props.location))
  const [working, setWorking] = createSignal(Boolean(props.initialRemoving))
  const [toDelete, setToDelete] = createSignal<string>()
  const [removing, setRemoving] = createSignal(props.initialRemoving)
  const [replacementCurrent, setReplacementCurrent] = createSignal<string>()
  const [loadError, setLoadError] = createSignal<unknown>()
  onMount(() => dialog.setSize("xlarge"))

  function reopen(initialRemoving?: string) {
    dialog.replace(() => (
      <DialogWorkspaces {...props} initialDirectories={directoryData()} initialRemoving={initialRemoving} />
    ))
  }

  // A failed current-checkout lookup only affects which row is highlighted, so
  // swallow it and let the directory list render without a current marker.
  // Once the current project is known, a mismatch is a guaranteed miss.
  const [loadedProject] = createResource(
    () => (location()?.project.id === props.projectID ? undefined : props.projectID),
    (projectID) =>
      client.api.location
        .get({ location: { directory: location()?.directory || paths.cwd } })
        .then((result) => (result.project.id === projectID ? result.project.directory : undefined))
        .catch(() => undefined),
  )
  const currentCheckout = createMemo(() => {
    if (location()?.project.id === props.projectID) return location()?.project.directory
    return loadedProject()
  })

  const [directories, { refetch }] = createResource(
    () => (props.fixture || props.initialRemoving ? undefined : props.projectID),
    async (projectID, info): Promise<ReadonlyArray<ProjectDirectory> | undefined> => {
      try {
        const directories = await client.api.worktree.list({ projectID })
        setLoadError(undefined)
        return directories
      } catch (error) {
        setLoadError(error)
        // An initial load with no data surfaces the inline error view below. A
        // failed refresh intentionally stays quiet and keeps the already-shown
        // list interactive; reopening the dialog retries the load.
        return info.value
      }
    },
  )
  let refreshed = false
  createEffect(() => {
    if (props.fixture || props.initialRemoving || directories.latest === undefined || refreshed) return
    refreshed = true
    void refresh().catch(() => undefined)
  })
  onCleanup(
    client.event.on("worktree.updated", (event) => {
      if (event.data.projectID === props.projectID) void refetch()
    }),
  )
  function refresh() {
    return client.api.worktree.refresh({ projectID: props.projectID })
  }
  const directoryData = createMemo(() => directories.latest ?? props.initialDirectories)
  // Show the locked error view only when we have nothing to display. A refresh
  // that fails after the list rendered keeps the list and its actions.
  const showError = createMemo(() => Boolean(loadError()) && !directoryData())

  const currentDirectory = createMemo(
    () => replacementCurrent() ?? (props.current?.type === "directory" ? props.current.directory : currentCheckout()),
  )
  const currentRoot = createMemo<ProjectDirectory | undefined>(() => {
    if (showError()) return
    const directory = currentDirectory()
    if (!directory) return
    return directoryData()
      ?.filter((root) => contains(root.directory, directory))
      .toSorted((a, b) => b.directory.length - a.directory.length)[0]
  })

  const options = createMemo<DialogSelectOption<WorkspaceSelection | undefined>[]>(() => {
    if (showError()) return []
    const data = directoryData()
    const current = currentRoot()?.directory
    if (directories.loading && !data && !current) return []
    const roots = [...(data ?? [])]
    roots.sort((a, b) => {
      if (a.directory === current) return -1
      if (b.directory === current) return 1
      if (Boolean(a.strategy) !== Boolean(b.strategy)) return a.strategy ? 1 : -1
      if (!a.strategy && !b.strategy) return a.directory.length - b.directory.length
      return 0
    })
    if (roots.length === 0) return []

    const subdirectories = sessionData.session
      .list()
      .filter(
        (session) => session.projectID === props.projectID && session.subpath && ![".", "/"].includes(session.subpath),
      )
      .map((session) => session.location.directory)
      .filter((directory) => currentRoot() || directory !== currentDirectory())
      .filter((directory) => !roots.some((root) => root.directory === directory))
      .filter((directory, index, directories) => directories.indexOf(directory) === index)
      .map((location) => ({
        location,
        root: roots
          .filter((root) => contains(root.directory, location))
          .toSorted((a, b) => b.directory.length - a.directory.length)[0],
      }))
      .filter((item): item is { location: string; root: ProjectDirectory } => item.root !== undefined)

    const list = [...roots.map((root) => ({ location: root.directory, root })), ...subdirectories].toSorted((a, b) => {
      const root = roots.indexOf(a.root) - roots.indexOf(b.root)
      if (root !== 0) return root
      if (a.location === a.root.directory) return -1
      if (b.location === b.root.directory) return 1
      return a.location.localeCompare(b.location)
    })
    const titleWidth = Math.max(1, dialogSelectContentWidth(Math.min(dialogWidth("xlarge"), dimensions().width - 2)))

    return list.map((item) => {
      const title = abbreviateHome(item.location, paths.home)
      const suffix =
        item.location === item.root.directory ? undefined : path.sep + path.relative(item.root.directory, item.location)
      const visible = Locale.truncateLeft(title, titleWidth)
      const split = suffix ? Math.max(0, visible.length - suffix.length) : visible.length
      const deleting = toDelete() === item.location
      const isRemoving = removing() === item.location
      return {
        title,
        titleView: isRemoving ? (
          <span style={{ fg: theme.text.feedback.error.base }}>Deleting {item.location}</span>
        ) : deleting ? (
          <span style={{ fg: theme.text.action.destructive.base }}>
            Press {shortcuts.get("dialog.move_session.delete")} again to confirm
          </span>
        ) : suffix ? (
          <>
            {visible.slice(0, split)}
            <span style={{ fg: theme.text.muted }}>{visible.slice(split)}</span>
          </>
        ) : undefined,
        bg: deleting ? theme.background.action.destructive.base : undefined,
        value: {
          type: "directory",
          directory: item.location,
          subdirectory: item.location !== item.root.directory,
        } as const,
        category: item.root.directory === current ? "Current" : "Other",
        titleWidth,
        truncateTitle: "left" as const,
      }
    })
  })

  const current = createMemo(() => {
    if (directories.loading || loadedProject.loading) return
    const replacement = replacementCurrent()
    if (replacement) return { type: "directory", directory: replacement, subdirectory: false } as const
    return props.current
  })

  async function removedCurrent(current: boolean) {
    if (!current) return false
    const fallback = directoryData()?.findLast((item) => item.strategy === undefined)?.directory
    if (fallback) setReplacementCurrent(fallback)
    if (route.data.type === "session") {
      route.navigate({ type: "home" })
      dialog.clear()
      return true
    }
    if (fallback) {
      props.onCurrentChange?.({ type: "directory", directory: fallback, subdirectory: false })
      return true
    }
    dialog.clear()
    return true
  }

  async function remove(option: DialogSelectOption<WorkspaceSelection | undefined>) {
    if (!option.value || option.value.type !== "directory" || option.value.subdirectory || removing()) return
    const data = directoryData()
    const selected = option.value
    const root = data?.find((item) => item.directory === selected.directory)
    if (!root?.strategy) return
    const deletingCurrent = selected.directory === currentRoot()?.directory
    if (toDelete() !== selected.directory) {
      setToDelete(selected.directory)
      return
    }
    setToDelete(undefined)
    setRemoving(selected.directory)
    setWorking(true)
    const request = {
      directory: selected.directory,
      projectID: props.projectID,
    }
    const error = await client.api.worktree
      .remove({
        ...request,
        force: false,
      })
      .then(
        () => undefined,
        (error) => error,
      )
    if (error) {
      setRemoving(undefined)
      setWorking(false)
      if (isRecord(error) && isRecord(error.data) && error.data.forceRequired === true) {
        const status = await client.api.vcs
          .status({ location: { directory: selected.directory } })
          .catch(() => undefined)
        const choice = await DialogWorkspaceFileChanges.show(dialog, status?.data ?? [], {
          title: "Delete worktree?",
          message: "This worktree has file changes. Do you want to delete it anyway?",
          confirm: { title: "delete", key: "d" },
        })
        if (choice !== "yes") {
          reopen()
          return
        }
        reopen(selected.directory)
        const forcedError = await client.api.worktree
          .remove({
            ...request,
            force: true,
          })
          .then(
            () => undefined,
            (error) => error,
          )
        if (forcedError) {
          toast.show({
            variant: "error",
            title: "Failed to delete worktree",
            message: errorMessage(forcedError),
          })
          reopen()
          return
        }
        setRemoving(undefined)
        setWorking(false)
        if (await removedCurrent(deletingCurrent)) return
        reopen()
        return
      }
      toast.show({
        variant: "error",
        title: "Failed to delete worktree",
        message: errorMessage(error),
      })
      return
    }
    await refetch()
    setRemoving(undefined)
    setWorking(false)
    if (await removedCurrent(deletingCurrent)) return
  }

  async function create() {
    const name = await DialogWorktreeName.show(dialog)
    if (name === null) return
    props.onSelect({ type: "new", name })
  }

  async function move(option: DialogSelectOption<WorkspaceSelection | undefined>) {
    if (route.data.type !== "session" || option.value?.type !== "directory") return
    const sessionID = route.data.sessionID
    const directory = option.value.directory
    dialog.clear()
    await client.api.session.move({ sessionID, directory }).catch(toast.error)
  }

  const fullHeight = createMemo(() =>
    Math.max(8, Math.min(16, dimensions().height - Math.floor(dimensions().height / 4) - 2)),
  )

  return (
    <box minHeight={showError() ? 5 : fullHeight()}>
      <DialogSelect
        title="Worktrees"
        titleView={
          <box flexDirection="row" gap={1}>
            <text fg={theme.text.base} attributes={TextAttributes.BOLD}>
              Worktrees
            </text>
            <Show when={working() || directories.loading || loadedProject.loading}>
              <Spinner />
            </Show>
          </box>
        }
        renderFilter={!showError()}
        flat={true}
        options={options()}
        emptyView={
          showError() ? (
            <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
              <text fg={theme.text.feedback.error.base} attributes={TextAttributes.BOLD}>
                Could not load worktrees
              </text>
              <text fg={theme.text.muted}>{errorMessage(loadError())}</text>
              <text fg={theme.text.muted}>Close and reopen Worktrees to try again.</text>
            </box>
          ) : directories.loading || loadedProject.loading ? (
            <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
              <text fg={theme.text.muted}>Loading worktrees…</text>
            </box>
          ) : (
            <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
              <text fg={theme.text.muted}>No worktrees available</text>
            </box>
          )
        }
        noMatchView={
          <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
            <text fg={theme.text.muted}>No worktrees found</text>
          </box>
        }
        locked={showError() || directories.loading || loadedProject.loading || Boolean(removing())}
        current={current()}
        onSelect={(option) => {
          if (option.value) props.onSelect(option.value)
        }}
        onMove={() => setToDelete(undefined)}
        actions={
          showError() || props.fixture
            ? []
            : [
                ...(route.data.type === "session"
                  ? [{ command: "dialog.move_session.move", title: "move", onTrigger: move }]
                  : []),
                {
                  command: "dialog.move_session.new",
                  title: "new",
                  selection: "none",
                  onTrigger: () => void create(),
                },
                {
                  command: "dialog.move_session.delete",
                  title: "delete",
                  disabled: (option) => {
                    const value = option?.value
                    if (!value || value.type !== "directory" || value.subdirectory) return true
                    return !directoryData()?.find((item) => item.directory === value.directory)?.strategy
                  },
                  onTrigger: remove,
                },
                {
                  command: "dialog.move_session.refresh",
                  title: "refresh",
                  selection: "none",
                  onTrigger: () => void refresh().catch(toast.error),
                },
              ]
        }
      />
    </box>
  )
}

function contains(root: string, directory: string) {
  if (root === directory) return true
  const relative = path.relative(root, directory)
  return relative && relative !== ".." && !relative.startsWith(".." + path.sep) && !path.isAbsolute(relative)
}

import { Slug } from "@opencode/core/util/slug"
import { useNewDesigns } from "../config"
import { type DialogContext } from "../ui/dialog"
import { DialogPrompt } from "../ui/dialog-prompt"

export function DialogWorktreeName(props: { onConfirm: (name: string) => void }) {
  const newDesigns = useNewDesigns()
  return (
    <DialogPrompt
      title="Name worktree"
      placeholder="Worktree name"
      onConfirm={(value) => props.onConfirm(slugify(value) || Slug.create())}
      actions={[
        {
          title: newDesigns() ? "generate name" : "generate one",
          command: "dialog.worktree.generate",
          commandTitle: "Generate worktree name",
          onTrigger: (prompt) => prompt.setValue(Slug.create()),
        },
      ]}
    />
  )
}

DialogWorktreeName.show = (dialog: DialogContext) =>
  new Promise<string | null>((resolve) => {
    dialog.replace(
      () => <DialogWorktreeName onConfirm={resolve} />,
      () => resolve(null),
    )
  })

function slugify(input: string) {
  return input
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+/, "")
    .replace(/-+$/, "")
}

import { TextAttributes, type ScrollBoxRenderable } from "@opentui/core"
import { useKeyboard, useTerminalDimensions } from "@opentui/solid"
import { createSignal, For, Show } from "solid-js"
import { getScrollAcceleration } from "../util/scroll"
import { useClipboard } from "../context/clipboard"
import { useExit } from "../context/exit"
import { useTuiApp } from "../context/runtime"
import { describeOS, describeTerminal } from "../util/system"

export function ErrorComponent(props: { error: Error; reset: () => void; mode?: "dark" | "light" }) {
  const term = useTerminalDimensions()
  const exit = useExit()
  const clipboard = useClipboard()
  const app = useTuiApp()
  const [copyState, setCopyState] = createSignal<"idle" | "copied" | "failed">("idle")

  // Safe fallback palette per mode (mirrors theme/assets/opencode.json) since the
  // theme context may be the thing that crashed.
  const isLight = props.mode === "light"
  const colors = isLight
    ? {
        bg: "#ffffff",
        element: "#f5f5f5",
        borderSubtle: "#d4d4d4",
        text: "#1a1a1a",
        muted: "#8a8a8a",
        primary: "#3b7dd8",
        onPrimary: "#ffffff",
        error: "#d1383d",
        success: "#3d9a57",
      }
    : {
        bg: "#0a0a0a",
        element: "#1e1e1e",
        borderSubtle: "#3c3c3c",
        text: "#eeeeee",
        muted: "#808080",
        primary: "#fab283",
        onPrimary: "#0a0a0a",
        error: "#e06c75",
        success: "#7fd88f",
      }

  const message = props.error.message || "An unknown error occurred."
  const stack = props.error.stack || "No stack trace available."
  const issueURL = buildIssueURL(message, stack, app.version)

  const copyReport = () => {
    void clipboard
      .write(issueURL.toString())
      .then(() => setCopyState("copied"))
      .catch(() => setCopyState("failed"))
  }

  const actions = [
    {
      key: "c",
      label: () => ({ idle: "Copy report", copied: "✓ Copied", failed: "Copy failed" })[copyState()],
      copy: true,
      onUse: copyReport,
    },
    { key: "r", label: () => "Restart", onUse: props.reset },
    { key: "q", label: () => "Quit", onUse: () => exit() },
  ]
  const [selected, setSelected] = createSignal(0)
  const move = (delta: number) => setSelected((prev) => (prev + delta + actions.length) % actions.length)
  let scroll: ScrollBoxRenderable | undefined

  useKeyboard((evt) => {
    if (evt.ctrl && evt.name === "c") return exit()
    if (evt.name === "return") {
      evt.preventDefault()
      evt.stopPropagation()
      return actions[selected()].onUse()
    }
    if (evt.name === "left") {
      evt.preventDefault()
      evt.stopPropagation()
      return move(-1)
    }
    if (evt.name === "right") {
      evt.preventDefault()
      evt.stopPropagation()
      return move(1)
    }
    if (evt.name === "tab") {
      evt.preventDefault()
      evt.stopPropagation()
      return move(evt.shift ? -1 : 1)
    }
    // Vertical keys scroll the stack trace; buttons navigate horizontally.
    if (evt.name === "up") return scroll?.scrollBy(-1)
    if (evt.name === "down") return scroll?.scrollBy(1)
    if (evt.name === "pageup" && scroll) return scroll.scrollBy(-scroll.height)
    if (evt.name === "pagedown" && scroll) return scroll.scrollBy(scroll.height)
    if (evt.name === "home" && scroll) return scroll.scrollTo(0)
    if (evt.name === "end" && scroll) return scroll.scrollTo(scroll.scrollHeight)
    if (evt.name === "q") return exit()
    if (evt.name === "c") return copyReport()
    if (evt.name === "r") return props.reset()
  })

  // Responsive thresholds.
  const contentWidth = () => Math.min(84, Math.max(24, term().width - 4))
  const showSubtext = () => term().height >= 18
  const showFooter = () => term().height >= 20

  return (
    <box
      width={term().width}
      height={term().height}
      backgroundColor={colors.bg}
      flexDirection="column"
      alignItems="center"
    >
      <box width={contentWidth()} flexGrow={1} flexDirection="column" paddingTop={1} paddingBottom={1} gap={1}>
        {/* Headline */}
        <box flexDirection="column" alignItems="center" flexShrink={0}>
          <text attributes={TextAttributes.BOLD} fg={colors.text}>
            OpenCode crashed
          </text>
          <Show when={showSubtext()}>
            <text fg={colors.muted}>An unexpected error stopped the session.</text>
          </Show>
        </box>

        {/* Error message panel */}
        <box
          flexShrink={0}
          border
          borderStyle="rounded"
          borderColor={colors.error}
          title=" Error "
          titleColor={colors.error}
          paddingLeft={2}
          paddingRight={2}
        >
          <text fg={colors.text}>{message}</text>
        </box>

        {/* Actions */}
        <box flexDirection="row" flexWrap="wrap" justifyContent="center" gap={2} rowGap={1} flexShrink={0}>
          <For each={actions}>
            {(action, index) => {
              const isSelected = () => selected() === index()
              const copyColor = () =>
                action.copy
                  ? copyState() === "copied"
                    ? colors.success
                    : copyState() === "failed"
                      ? colors.error
                      : undefined
                  : undefined
              return (
                <box flexDirection="column" alignItems="center" flexShrink={0}>
                  <box
                    onMouseDown={() => setSelected(index())}
                    onMouseUp={() => action.onUse()}
                    backgroundColor={copyColor() ?? (isSelected() ? colors.primary : colors.element)}
                    minWidth={15}
                    alignItems="center"
                    paddingLeft={2}
                    paddingRight={2}
                  >
                    <text
                      attributes={TextAttributes.BOLD}
                      fg={copyColor() || isSelected() ? colors.onPrimary : colors.text}
                    >
                      {action.label()}
                    </text>
                  </box>
                  <text fg={isSelected() ? colors.primary : colors.muted}>{action.key}</text>
                </box>
              )
            }}
          </For>
        </box>

        {/* Stack trace */}
        <box
          flexGrow={1}
          flexBasis={0}
          minHeight={3}
          border
          borderStyle="rounded"
          borderColor={colors.borderSubtle}
          title=" Stack trace "
          titleColor={colors.muted}
          bottomTitle=" ↑↓ scroll "
          bottomTitleAlignment="right"
          paddingLeft={1}
          paddingRight={1}
        >
          <scrollbox
            ref={(element: ScrollBoxRenderable) => (scroll = element)}
            flexGrow={1}
            scrollAcceleration={getScrollAcceleration()}
          >
            <text fg={colors.muted}>{stack}</text>
          </scrollbox>
        </box>

        {/* Footer */}
        <Show when={showFooter()}>
          <box flexDirection="column" alignItems="center" flexShrink={0}>
            <text fg={colors.muted}>
              {copyState() === "copied"
                ? "Report copied — paste it into a new GitHub issue."
                : copyState() === "failed"
                  ? "Clipboard write failed. Try again or report the crash manually."
                  : "Copy the report and open a GitHub issue to help us fix this."}
            </text>
            <text fg={colors.muted}>OpenCode {app.version}</text>
          </box>
        </Show>
      </box>
    </box>
  )
}

function buildIssueURL(message: string, stack: string, version: string) {
  // Field keys match the ids in .github/ISSUE_TEMPLATE/bug-report.yml so the issue
  // form opens pre-filled. Populating os/terminal/reproduce keeps the report past
  // the contributing-guidelines compliance check, which pushes for system info.
  const url = new URL("https://github.com/anomalyco/opencode/issues/new?template=bug-report.yml")
  url.searchParams.set("title", `TUI crash: ${message}`)
  url.searchParams.set("opencode-version", version)
  url.searchParams.set("os", describeOS())
  url.searchParams.set("terminal", describeTerminal())
  url.searchParams.set(
    "reproduce",
    "Reported automatically from the OpenCode crash screen. If you can, describe what you were doing when it crashed.",
  )

  // Budget the stack against the fully URL-encoded length (not the raw length) so
  // the final link stays under GitHub's practical limit; flag truncation so a
  // clipped trace is obvious. searchParams.set handles encoding without throwing,
  // so measuring url.toString() is both correct and safe on any input.
  const MAX_URL_LENGTH = 6000
  const marker = "\n… (truncated)"
  const head = `The OpenCode TUI crashed with an unexpected error.\n\n**Error:** ${message}\n\n**Stack trace:**\n`
  const setBody = (body: string) => url.searchParams.set("description", head + "```\n" + body + "\n```")

  setBody(stack)
  if (url.toString().length <= MAX_URL_LENGTH) return url

  // Largest raw stack prefix whose encoded URL (with the marker) still fits.
  let lo = 0
  let hi = stack.length
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2)
    setBody(stack.slice(0, mid) + marker)
    if (url.toString().length <= MAX_URL_LENGTH) lo = mid
    else hi = mid - 1
  }
  setBody(stack.slice(0, lo) + marker)
  return url
}

import { RGBA, type OptimizedBuffer, type RenderContext, type TextOptions } from "@opentui/core"
import { extend, type JSX } from "@opentui/solid"
import { splitProps } from "solid-js"
import { useConfig } from "../config"
import { MaskedTextRenderable } from "./masked-text"
import { clamp, coast, smootherstep } from "./tab-pulse"

type FadeInTextOptions = TextOptions & {
  backdrop?: RGBA
  enabled?: boolean
  sweepOffset?: number
  sweepWidth?: number
}

const DURATION = 200
const FEATHER = 8

class FadeInTextRenderable extends MaskedTextRenderable {
  private _backdrop = RGBA.defaultBackground()
  private _enabled = true
  private _sweepOffset = 0
  private _sweepWidth: number | undefined
  private elapsed = 0

  constructor(ctx: RenderContext, options: FadeInTextOptions) {
    super(ctx, options)
    this.matrix[15] = 1
    this.updateBackdrop()
    if (options.backdrop) this.backdrop = options.backdrop
    if (options.enabled === false) this.enabled = false
    this.live = this._enabled
  }

  set backdrop(value: RGBA) {
    if (value.equals(this._backdrop)) return
    this._backdrop = value
    this.updateBackdrop()
    this.requestRender()
  }

  set enabled(value: boolean) {
    if (value === this._enabled) return
    this._enabled = value
    this.live = value && this.elapsed < DURATION
    this.requestRender()
  }

  set sweepOffset(value: number | undefined) {
    this._sweepOffset = value ?? 0
    this.requestRender()
  }

  set sweepWidth(value: number | undefined) {
    this._sweepWidth = value
    this.requestRender()
  }

  private updateBackdrop() {
    this.matrix[3] = this._backdrop.r
    this.matrix[7] = this._backdrop.g
    this.matrix[11] = this._backdrop.b
  }

  override render(buffer: OptimizedBuffer, deltaTime: number) {
    if (!this._enabled || this.elapsed >= DURATION) return super.render(buffer, deltaTime)
    if (!this.visible || this.isDestroyed || !Number.isFinite(this.width) || this.width <= 0 || this.height <= 0) return
    this.elapsed = Math.min(DURATION, this.elapsed + deltaTime)
    this.renderMasked(buffer, 1, (end) => {
      const progress = this.elapsed / DURATION
      const front = -FEATHER + coast(progress) * ((this._sweepWidth ?? end) + FEATHER * 2)
      return (column) => 1 - smootherstep(clamp((front - (this._sweepOffset + column)) / FEATHER))
    })
    if (this.elapsed >= DURATION) this.live = false
  }
}

extend({ fade_in_text: FadeInTextRenderable })

