export const TAB_SPINNERS = {
  dots: { frames: SPINNER_FRAMES, interval: 80 },
  arcs: { frames: ["◜", "◝", "◞", "◟"], interval: 120 },
  quadrants: { frames: ["◴", "◷", "◶", "◵"], interval: 120 },
  line: { frames: ["|", "/", "-", "\\"], interval: 120 },
}
export type TabSpinner = keyof typeof TAB_SPINNERS

export const TAB_UNREAD_MARKERS = {
  "small-dot": "•",
  dot: "●",
  square: "▪",
  "large-square": "■",
}
export type TabUnreadMarker = keyof typeof TAB_UNREAD_MARKERS

// A long title fades out over its last cells instead of cutting hard.
const FADE_WIDTH = 4
// The add button renders as " + " at the end of the strip, so the tab layout leaves it room.
const ADD_TAB_WIDTH = 3
const MARQUEE_DELAY = 600
const MARQUEE_INTERVAL = 80
const CONTEXT_MENU_WIDTH = 20
const MIDDLE_MOUSE_BUTTON = 1
const RIGHT_MOUSE_BUTTON = 2
const MOUSE_CLOSE_HOLD_MS = 5_000

type MouseCloseHold = {
  items: string[]
  ids: string[]
  widths: number[]
  closed: string
  target: string
  x: number
}

type TabContextMenuState = {
  x: number
  y: number
  sessionID?: string
  title?: string
}

type ContextController = ReturnType<typeof useSessionTabs>
export type SessionTabsStatus = Omit<ReturnType<ContextController["status"]>, "unread"> & {
  unread: SessionTabUnread | undefined
}
export const EMPTY_SESSION_TAB_STATUS: SessionTabsStatus = {
  unread: undefined,
  promptPulse: 0,
  attention: false,
  busy: false,
  renaming: false,
}
export type SessionTabsController = Pick<ContextController, "tabs" | "current" | "select" | "close" | "move"> & {
  newTab?: () => boolean
  add?: () => void
  recentlyClosed?: ContextController["recentlyClosed"]
  reopen?: ContextController["reopen"]
  detail?: (sessionID: string) => string | undefined
  rename?: (sessionID: string) => void
  search?: () => void
  status(sessionID: string): SessionTabsStatus
}
const NEW_SESSION_TAB: SessionTab = { sessionID: "new", title: NEW_SESSION_TAB_TITLE }
const glowTextColor = (base: RGBA, glow: RGBA, index: number, width: number, level = 1) =>
  tint(base, glow, 0.12 * unreadGlowIntensity(index, width) * level)

function tabFeedbackColor(status: SessionTabsStatus, theme: ReturnType<typeof useTheme>) {
  if (status.attention) return theme.hue.accent[200]
  if (status.unread === "error") return theme.text.feedback.error.base
  return undefined
}

function TabIndicator(props: {
  status: SessionTabsStatus
  label: string
  idleLabel?: string
  width: number
  centered?: boolean
  color: RGBA
  unreadColor: RGBA
  backgroundColor: RGBA
  flashColor: RGBA
  animations: boolean
  numbers: boolean
  selected?: boolean
  spinner?: TabSpinner
  unreadMarker?: TabUnreadMarker
  attributes?: number
}) {
  const runs = () => props.status.busy && !props.status.attention
  const pending = createMemo(() => props.status.busy || Boolean(props.status.attention))
  const unread = createMemo(() => Boolean(props.status.unread) && !pending())
  const unreadColor = createMemo<RGBA>((previous) => (unread() ? props.unreadColor : previous), props.unreadColor)
  const fade = createAnimatable(
    { opacity: unread() ? 1 : 0 },
    { enabled: () => props.animations, transition: tween({ duration: 0.18 }) },
  )
  createComputed(() => {
    if (unread()) return fade.jump({ opacity: 1 })
    if (pending()) return fade.jump({ opacity: 0 })
    fade.animate({ opacity: 0 })
  })
  const fading = () => !props.status.unread && fade.value().opacity > 0
  const color = () => {
    if (props.numbers || props.selected) return props.color
    if (unread()) return props.unreadColor
    if (!fading()) return props.color
    const opacity = fade.value().opacity
    // Brighten during the first fifth, then dissolve into the tab background.
    const flash = Math.max(0, 1 - Math.abs(opacity - 0.8) / 0.2)
    return tint(props.backgroundColor, tint(unreadColor(), props.flashColor, flash * 0.3), Math.min(1, opacity / 0.8))
  }
  const spinner = () => TAB_SPINNERS[props.spinner ?? "dots"]
  const label = () => {
    if (props.numbers) return props.label
    if (props.status.attention === "permission") return "!"
    if (props.status.attention === "question") return "?"
    if (runs()) return spinner().frames[0]
    if (props.label === "+") return "+"
    if (props.status.unread || fading()) return TAB_UNREAD_MARKERS[props.unreadMarker ?? "small-dot"]
    return props.idleLabel ?? ""
  }
  return (
    <box
      width={props.width + (props.centered ? 0 : 1)}
      height={props.centered ? 1 : undefined}
      flexShrink={0}
      flexDirection="row"
      justifyContent={props.centered ? "center" : "flex-end"}
      paddingRight={props.centered ? 0 : 1}
    >
      <Show
        when={runs() && props.animations && !props.numbers}
        fallback={
          <text fg={color()} selectable={false} attributes={props.attributes}>
            {label()}
          </text>
        }
      >
        <spinner frames={spinner().frames} interval={spinner().interval} color={props.color} />
      </Show>
    </box>
  )
}

function createGlowLevel(dimmed: () => boolean, animations: () => boolean) {
  const motion = createAnimatable(
    { level: dimmed() ? 0.7 : 1 },
    { enabled: animations, transition: tween({ duration: 0.2 }) },
  )
  createEffect(() => motion.animate({ level: dimmed() ? 0.7 : 1 }))
  return () => motion.value().level
}

function createNumberIgnition(runs: () => boolean, prompt: () => number, animations: () => boolean) {
  const ignition = createAnimatable({ level: 0 }, { enabled: animations, transition: tween({ duration: 0.7 }) })
  let wasRunning = runs()
  let promptPulse = prompt()
  createEffect(() => {
    const running = runs()
    const nextPromptPulse = prompt()
    if (running !== wasRunning || nextPromptPulse !== promptPulse) {
      ignition.jump({ level: 0.85 })
      ignition.animate({ level: 0 })
    }
    wasRunning = running
    promptPulse = nextPromptPulse
  })
  return ignition
}

function fadeTitleColor(color: RGBA, background: RGBA, index: number, length: number, leading: number) {
  const fade = (position: number) => (position <= 0 ? 0 : 0.2 + 0.72 * ((position - 1) / Math.max(1, FADE_WIDTH - 1)))
  const start = index < FADE_WIDTH ? FADE_WIDTH - index : 0
  const end = index - (length - FADE_WIDTH) + 1
  const opacity = Math.max(fade(start) * leading, fade(end))
  return opacity === 0 ? color : tint(color, background, opacity)
}

function heldSessionTabLayout(hold: MouseCloseHold, tabs: readonly SessionTab[]) {
  const ids = tabs.map((tab) => tab.sessionID)
  const expected = hold.items.filter((id) => id !== hold.closed)
  const unchanged = ids.length === hold.items.length && ids.every((id, index) => id === hold.items[index])
  const removed = ids.length === expected.length && ids.every((id, index) => id === expected[index])
  if (!unchanged && !removed) return undefined

  const visibleIDs = hold.ids.filter((id) => ids.includes(id))
  if (removed && !visibleIDs.includes(hold.target)) {
    visibleIDs.push(hold.target)
    visibleIDs.sort((a, b) => ids.indexOf(a) - ids.indexOf(b))
  }
  const positions = visibleIDs.map((id) => ids.indexOf(id))
  const start = positions[0]
  if (start === undefined || positions.some((position, index) => position !== start + index)) return undefined
  const visible = visibleIDs.flatMap((id) => tabs.find((tab) => tab.sessionID === id) ?? [])
  if (visible.length !== visibleIDs.length) return undefined

  const widths = visibleIDs.map((id) => hold.widths[hold.ids.indexOf(id)] ?? 1)
  if (removed) {
    const index = visibleIDs.indexOf(hold.target)
    if (index === -1) return undefined
    const leading = start > 0 ? sessionTabOverflowWidth(start) : 0
    const preceding = widths.slice(0, index).reduce((sum, width) => sum + width, 0)
    // The close glyph sits one cell in from the right edge: x = tab start + width - 2.
    const width = hold.x - leading - preceding + 2
    if (width < 1) return undefined
    widths[index] = width
  }
  return {
    tabs: visible,
    widths,
    before: start,
    after: tabs.length - start - visible.length,
    start,
    total: widths.reduce((sum, width) => sum + width, 0),
  }
}

export function createMarquee(animations: () => boolean) {
  const [offset, setOffset] = createSignal(0)
  const [active, setActive] = createSignal<string>()
  const leading = createAnimatable({ opacity: 0 }, { enabled: animations, transition: tween({ duration: 0.25 }) })
  let delay: ReturnType<typeof setTimeout> | undefined
  let interval: ReturnType<typeof setInterval> | undefined
  let cycleWidth = 0

  const clear = () => {
    if (delay) clearTimeout(delay)
    if (interval) clearInterval(interval)
    delay = undefined
    interval = undefined
  }
  const scroll = () => {
    interval = setInterval(
      () =>
        setOffset((value) => {
          if (value + 1 < cycleWidth) return value + 1
          clear()
          leading.animate({ opacity: 0 })
          return 0
        }),
      MARQUEE_INTERVAL,
    )
  }
  const enter = (sessionID: string, title: string, width: number) => {
    if (!marqueeOverflows(title, width)) {
      reset()
      return
    }
    if (active() === sessionID) return
    clear()
    cycleWidth = marqueeCycleWidth(title)
    setActive(sessionID)
    setOffset(0)
    leading.jump({ opacity: 0 })
    delay = setTimeout(() => {
      setOffset(1)
      leading.animate({ opacity: 1 })
      scroll()
    }, MARQUEE_DELAY)
  }
  const leave = (sessionID: string) => {
    if (active() !== sessionID) return
    reset()
  }
  const reset = () => {
    clear()
    setActive(undefined)
    setOffset(0)
    leading.jump({ opacity: 0 })
  }
  onCleanup(clear)

  return { offset, active, enter, leave, reset, leading: () => leading.value().opacity }
}

export function createTabMarquee(animations: () => boolean) {
  const [hovered, setHovered] = createSignal<string>()
  const marquee = createMarquee(animations)
  let hoverClear: ReturnType<typeof setTimeout> | undefined

  const enter = (sessionID: string, title: string, width: number) => {
    if (hoverClear) clearTimeout(hoverClear)
    setHovered(sessionID)
    marquee.enter(sessionID, title, width)
  }
  const leave = (sessionID: string) => {
    if (hoverClear) clearTimeout(hoverClear)
    hoverClear = setTimeout(() => {
      if (hovered() !== sessionID) return
      setHovered(undefined)
      marquee.leave(sessionID)
    })
  }
  const leaveHovered = () => {
    const sessionID = hovered()
    if (sessionID) leave(sessionID)
  }
  const reset = () => {
    if (hoverClear) clearTimeout(hoverClear)
    hoverClear = undefined
    setHovered(undefined)
    marquee.reset()
  }
  onCleanup(() => {
    if (hoverClear) clearTimeout(hoverClear)
  })

  return { ...marquee, hovered, enter, leave, leaveHovered, reset }
}

function TabContextMenu(props: { state: TabContextMenuState; tabs: SessionTabsController; onClose: () => void }) {
  const dimensions = useTerminalDimensions()
  const theme = useTheme()
  const background = () => theme.background.raised.base
  const actionHovered = () => theme.background.raised.high
  const dialog = useDialog()
  const clipboard = useClipboard()
  const toast = useToast()
  onCleanup(Keymap.use().mode.push("menu"))
  Keymap.createLayer(() => ({
    mode: "menu",
    commands: [{ bind: "escape,ctrl+c", title: "Close tab menu", group: "Tabs", run: props.onClose }],
  }))
  const actions = createMemo<Array<{ title: string; run?: () => void }>>(() => {
    const sessionID = props.state.sessionID
    const title = props.state.title
    const closed = (props.tabs.recentlyClosed?.() ?? []).slice(0, 10)
    return [
      ...(sessionID && props.tabs.add ? [{ title: NEW_SESSION_TAB_TITLE, run: () => props.tabs.add?.() }] : []),
      ...(sessionID
        ? [
            {
              title: "Rename",
              run: () =>
                props.tabs.rename ? props.tabs.rename(sessionID) : DialogSessionRename.show(dialog, sessionID, title),
            },
            {
              title: "Copy session ID",
              run: () =>
                void clipboard
                  .write(sessionID)
                  .then(() => toast.show({ message: "Session ID copied to clipboard", variant: "info" }))
                  .catch(toast.error),
            },
            { title: "Close", run: () => props.tabs.close(sessionID) },
          ]
        : []),
      ...(!sessionID && props.tabs.reopen
        ? [
            { title: "Recently closed tabs" },
            ...closed.map((tab) => ({
              title: tab.title || "Untitled session",
              run: () => props.tabs.reopen?.(tab.sessionID),
            })),
            ...(closed.length === 0 ? [{ title: "No recently closed tabs" }] : []),
          ]
        : []),
    ]
  })
  const [selected, setSelected] = createSignal<number>()
  const width = () =>
    Math.min(
      dimensions().width,
      Math.max(CONTEXT_MENU_WIDTH, ...actions().map((action) => Math.min(50, stringWidth(action.title) + 2))),
    )
  const height = () => Math.min(actions().length, dimensions().height)
  const top = () => Math.max(0, Math.min(props.state.y + 1, dimensions().height - height()))
  const left = () => Math.max(0, Math.min(props.state.x, dimensions().width - width()))
  const run = (index: number) => {
    const action = actions()[index]
    if (!action?.run) return
    props.onClose()
    action.run()
  }

  return (
    <Portal
      ref={(container) => {
        if (!(container instanceof BoxRenderable)) return
        // Portal's wrapper otherwise follows the full-height app in root layout.
        container.position = "absolute"
        container.left = 0
        container.top = 0
        container.zIndex = 2500
      }}
    >
      <box
        position="absolute"
        left={0}
        top={0}
        width={dimensions().width}
        height={dimensions().height}
        zIndex={2500}
        onMouseDown={(event) => {
          props.onClose()
          event.preventDefault()
          event.stopPropagation()
        }}
      >
        <scrollbox
          position="absolute"
          left={left()}
          top={top()}
          height={height()}
          width={width()}
          scrollX={false}
          scrollbarOptions={{ visible: false }}
          backgroundColor={background()}
          onMouseDown={(event) => {
            if (event.button === RIGHT_MOUSE_BUTTON) props.onClose()
            event.preventDefault()
            event.stopPropagation()
          }}
        >
          <For each={actions()}>
            {(action, index) => (
              <box
                width="100%"
                paddingLeft={1}
                paddingRight={1}
                height={1}
                flexShrink={0}
                backgroundColor={action.run && selected() === index() ? actionHovered() : undefined}
                onMouseOver={() => setSelected(action.run ? index() : undefined)}
                onMouseOut={() => setSelected(undefined)}
                onMouseUp={(event) => {
                  event.preventDefault()
                  event.stopPropagation()
                  if (event.button === RIGHT_MOUSE_BUTTON) return
                  run(index())
                }}
              >
                <text fg={action.run ? theme.text.base : theme.text.muted} selectable={false} truncate>
                  {action.title}
                </text>
              </box>
            )}
          </For>
        </scrollbox>
      </box>
    </Portal>
  )
}

export function SessionTabs(
  props: {
    controller?: SessionTabsController
    animations?: boolean
    spinner?: TabSpinner
    unreadMarker?: TabUnreadMarker
    indicators?: "status" | "numbers"
    orientation?: "horizontal" | "vertical"
    width?: number
  } = {},
) {
  const config = useConfig().data

  return (
    <Switch>
      <Match when={props.orientation === "vertical"}>
        <VerticalSessionTabs
          controller={props.controller}
          animations={props.animations}
          spinner={props.spinner}
          unreadMarker={props.unreadMarker}
          numbers={(props.indicators ?? config.tabs.indicators) === "numbers"}
          width={props.width}
        />
      </Match>
      <Match when={true}>
        <HorizontalSessionTabs
          controller={props.controller}
          animations={props.animations}
          spinner={props.spinner}
          unreadMarker={props.unreadMarker}
          numbers={(props.indicators ?? config.tabs.indicators) === "numbers"}
        />
      </Match>
    </Switch>
  )
}

function VerticalSessionTabs(props: {
  controller?: SessionTabsController
  animations?: boolean
  numbers: boolean
  spinner?: TabSpinner
  unreadMarker?: TabUnreadMarker
  width?: number
}) {
  const tabs: SessionTabsController = props.controller ?? useSessionTabs()
  const data = props.controller ? undefined : useData()
  const dimensions = useTerminalDimensions()
  const renderer = useRenderer()
  const theme = useTheme()
  const background = () => theme.background.raised.base
  const actionSelected = () => theme.background.action.primary.selected
  const actionHovered = () => theme.background.raised.high
  const base = useTheme()
  const config = useConfig().data
  const animations = () => props.animations ?? config.animations ?? true
  const width = () => props.width ?? SESSION_SIDEBAR_WIDTH
  const compact = createMemo(() => width() < SESSION_TABS_COMPACT_BREAKPOINT)
  const tooltipWidth = () => Math.min(54, dimensions().width - width())
  const stride = () => (compact() ? 2 : 3)
  const unreadColor = () => theme.hue.accent[200]
  const activeNumber = () => theme.hue.interactive[200]
  const idleNumber = () => tint(theme.text.formfield.base, background(), 0.55)
  const separatorUpperPulseColor = createMemo(() => tint(background(), theme.text.base, 0.04))
  const separatorLowerPulseColor = createMemo(() => tint(background(), theme.text.base, 0.05))
  const [addHovered, setAddHovered] = createSignal(false)
  const marquee = createTabMarquee(animations)
  const hovered = marquee.hovered
  createEffect(() => {
    compact()
    untrack(marquee.reset)
  })
  const [hoverY, setHoverY] = createSignal(0)
  const [scrollTop, setScrollTop] = createSignal(0)
  const detail = (sessionID: string) => {
    const fixture = tabs.detail?.(sessionID)
    if (fixture !== undefined) return fixture
    const session = data?.session.get(sessionID)
    const project = session ? data?.project.get(session.projectID) : undefined
    const vcs = session ? data?.location.vcs.info(session.location) : undefined
    const location = session ? data?.location.info(session.location) : undefined
    return sessionTabDetail(
      projectName(project, session?.location.directory) ?? "",
      vcs?.branch.current,
      vcs?.branch.default,
      !!location && location.project.directory !== location.project.canonical,
    )
  }
  // OpenTUI captures the first drag target, which may differ from the tab pressed on a fast move.
  const [dragging, setDragging] = createSignal<string>()
  const [preview, setPreview] = createSignal<{ sessionID: string; index: number }>()
  const [contextMenu, setContextMenu] = createSignal<TabContextMenuState>()
  const newTab = () => tabs.newTab?.() ?? false
  const activeID = createMemo(() => (newTab() ? undefined : tabs.current()))
  const ordered = createMemo(() => {
    const pending = preview()
    if (!pending) return tabs.tabs()
    return moveSessionTab(tabs.tabs(), pending.sessionID, pending.index)
  })
  const items = ordered
  const highlightColor = createMemo(() =>
    tint(background(), actionHovered(), actionHovered().a),
  )
  const highlighted = (sessionID: string | undefined) =>
    sessionID !== undefined && (activeID() === sessionID || hovered() === sessionID || dragging() === sessionID)
  const addHighlighted = () => newTab() || addHovered()
  const belowHighlighted = createMemo(() => {
    const tab = items()[Math.floor(scrollTop() / stride())]
    return tab ? highlighted(tab.sessionID) : addHighlighted()
  })
  createEffect(() => {
    const active = marquee.active()
    if (active && !items().some((tab) => tab.sessionID === active)) marquee.reset()
  })
  const statuses = createMemo(
    () =>
      new Map(
        items().map((tab) => {
          const status = tabs.status(tab.sessionID)
          return [
            tab.sessionID,
            {
              ...status,
              complete: sessionTabComplete(status.unread, status.busy),
              runs: status.busy && !status.attention,
              glows: Boolean(
                status.attention || (tab.sessionID !== activeID() && !status.busy && status.unread !== undefined),
              ),
            },
          ] as const
        }),
      ),
  )
  const itemStatus = (tab: SessionTab) => statuses().get(tab.sessionID)!
  let rail: { screenX: number; screenY: number } | undefined
  let scroll: ScrollBoxRenderable | undefined
  const updateScroll = () => setScrollTop(scroll?.scrollTop ?? 0)
  onCleanup(() => scroll?.verticalScrollBar.off("change", updateScroll))
  let didDrag = false
  let addPressed = false
  // A captured drag ends with a synthetic up on its drop target; do not turn that into a click.
  let suppressClick = false

  createEffect(() => {
    const pending = preview()
    if (!pending || dragging()) return
    const index = tabs.tabs().findIndex((tab) => tab.sessionID === pending.sessionID)
    if (index === -1 || index === Math.min(pending.index, tabs.tabs().length - 1)) setPreview(undefined)
  })

  createEffect(() => {
    if (!scroll) return
    dimensions()
    const index = newTab() ? items().length : items().findIndex((tab) => tab.sessionID === activeID())
    if (index === -1) return
    const top = index * stride()
    const height = compact() ? 3 : newTab() ? 1 : 2
    // Scroll after layout: newly opened tabs do not contribute to the scroll range yet.
    const reveal = () => {
      if (!scroll) return
      if (top < scroll.scrollTop) return scroll.scrollTo(top)
      if (top + height > scroll.scrollTop + scroll.viewport.height) {
        scroll.scrollTo(top + height - scroll.viewport.height)
      }
    }
    renderer.once(CliRenderEvents.FRAME, reveal)
    renderer.requestRender()
    onCleanup(() => renderer.off(CliRenderEvents.FRAME, reveal))
  })

  const release = () => {
    const source = dragging()
    if (!source) return
    if (didDrag) suppressClick = true
    setDragging(undefined)
    const pending = preview()
    if (pending?.sessionID === source) tabs.move(pending.sessionID, pending.index)
    tabs.select(source)
  }

  const drag = (event: MouseEvent) => {
    if (!rail) return
    const source = dragging()
    if (!source) return
    didDrag = true
    const target = Math.max(
      0,
      Math.min(
        tabs.tabs().length - 1,
        Math.floor(
          (event.y - (scroll?.viewport.screenY ?? rail.screenY + 1) - (compact() ? 1 : 0) + (scroll?.scrollTop ?? 0)) /
            stride(),
        ),
      ),
    )
    const sourceIndex = items().findIndex((item) => item.sessionID === source)
    if (target !== sourceIndex && preview()?.index !== target) setPreview({ sessionID: source, index: target })
  }

  return (
    <box
      ref={(element) => (rail = element)}
      width={width()}
      height="100%"
      flexShrink={0}
      flexDirection="column"
      position="relative"
      paddingTop={1}
      backgroundColor={background()}
      onMouseOut={marquee.leaveHovered}
      onMouseUp={(event) => {
        if (event.button === RIGHT_MOUSE_BUTTON) return
        release()
        if (!didDrag) return
        didDrag = false
        queueMicrotask(() => (suppressClick = false))
      }}
      onMouseDrag={drag}
      onMouseDragEnd={release}
    >
      <Show when={compact()}>
        <SessionTabsRailControls width={width()} tabs={tabs} belowHighlighted={belowHighlighted()} />
      </Show>
      <scrollbox
        ref={(element) => {
          scroll = element
          scroll.verticalScrollBar.on("change", updateScroll)
          updateScroll()
        }}
        flexGrow={1}
        minHeight={0}
        backgroundColor={background()}
        scrollbarOptions={{ visible: false }}
      >
        <box flexShrink={0} flexDirection="column" gap={1} paddingY={compact() ? 1 : 0}>
          <For each={items()}>
            {(tab, index) => {
              const selected = () => activeID() === tab.sessionID
              const status = createMemo(() => itemStatus(tab))
              const [sweepLevel, setSweepLevel] = createSignal(0)
              const [closeHovered, setCloseHovered] = createSignal(false)
              const session = createMemo(() => data?.session.get(tab.sessionID))
              const numberWidth = () => Math.max(2, String(items().length).length)
              const prefixWidth = () => numberWidth() + 1
              const restingTitleWidth = () => Math.max(1, width() - prefixWidth() - 1)
              const hoveredTitleWidth = () => Math.max(1, restingTitleWidth() - 1)
              const titleWidth = () => (hovered() === tab.sessionID ? hoveredTitleWidth() : restingTitleWidth())
              const title = () => (props.controller ? undefined : session()?.title) ?? tab.title ?? "Untitled session"
              const scrolling = () => marquee.active() === tab.sessionID
              const visibleTitleParts = createMemo(() =>
                scrolling()
                  ? marqueeTextParts(title(), titleWidth(), marquee.offset())
                  : Locale.graphemes(Locale.takeWidth(title(), titleWidth())).map((value) => ({
                      value,
                      separator: false,
                    })),
              )
              const visibleTitle = createMemo(() =>
                visibleTitleParts()
                  .map((part) => part.value)
                  .join(""),
              )
              const titleFades = createMemo(() => marqueeOverflows(title(), titleWidth()) && titleWidth() > FADE_WIDTH)
              const tabDetail = createMemo(() => detail(tab.sessionID))
              const visibleDetail = createMemo(() => Locale.takeWidth(tabDetail(), titleWidth()))
              const visibleDetailParts = createMemo(() => Locale.graphemes(visibleDetail()))
              const detailFades = createMemo(
                () => marqueeOverflows(tabDetail(), titleWidth()) && titleWidth() > FADE_WIDTH,
              )
              const tabBackground = createMemo(() => {
                if (selected() && !compact()) return actionSelected()
                if ((compact() && selected()) || hovered() === tab.sessionID || dragging() === tab.sessionID)
                  return actionHovered()
                return background()
              })
              const pulseBackground = createMemo(() => tint(background(), tabBackground(), tabBackground().a))
              const runs = () => status().runs
              const numberIgnition = createNumberIgnition(runs, () => status().promptPulse, animations)
              const numberColor = () => {
                const base =
                  hovered() === tab.sessionID && !selected()
                    ? foreground()
                    : tint(idleNumber(), tint(theme.text.base, pulseBackground(), 0.25), Number(selected()))
                const color = tabFeedbackColor(status(), theme) ?? tint(base, glowHue(), numberGlow.value().level)
                const runningColor = runs() ? activeNumber() : color
                return sweepLevel() === 0
                  ? tint(runningColor, theme.text.base, numberIgnition.value().level)
                  : tint(runningColor, theme.text.base, Math.max(numberIgnition.value().level, 0.35 * sweepLevel()))
              }
              const foreground = () => {
                if (hovered() === tab.sessionID) return theme.text.base
                return selected() ? theme.text.base : theme.text.muted
              }
              const complete = () => status().complete
              // Latched so a resolving glow fades out in the hue it lit with instead of snapping to the unread color.
              let lastGlowHue: RGBA | undefined
              const glowHue = () => {
                const feedback = tabFeedbackColor(status(), theme)
                if (feedback) return (lastGlowHue = feedback)
                if (status().unread !== undefined) return (lastGlowHue = unreadColor())
                return lastGlowHue ?? unreadColor()
              }
              const pulseColor = createMemo(() => tint(pulseBackground(), theme.text.base, 0.25))
              const flashColor = createMemo(() => tint(pulseBackground(), theme.text.base, 0.7))
              const glowLevel = createGlowLevel(() => selected() && Boolean(status().attention), animations)
              const glowColor = createMemo(() => tint(pulseBackground(), glowHue(), 0.45 * glowLevel()))
              const detailPulseColor = createMemo(() => tint(pulseBackground(), theme.text.base, 0.13))
              const detailFlashColor = createMemo(() => tint(pulseBackground(), theme.text.base, 0.42))
              const detailGlowColor = createMemo(() => tint(pulseBackground(), glowHue(), 0.25 * glowLevel()))
              const detailColor = createMemo(() => tint(theme.text.muted, pulseBackground(), 0.35))
              const detailTextColor = (index: number) =>
                detailFades()
                  ? fadeTitleColor(detailColor(), pulseBackground(), index, visibleDetailParts().length, 0)
                  : detailColor()
              const glows = () => status().glows
              // Text tints ride an eased level so they diffuse away with the background glow instead of snapping.
              const titleGlow = createAnimatable(
                { level: 0 },
                { enabled: animations, transition: tween({ duration: 0.4 }) },
              )
              createEffect(() => titleGlow.animate({ level: glows() ? 1 : 0 }))
              const numberGlow = createAnimatable(
                { level: 0 },
                { enabled: animations, transition: tween({ duration: 0.4 }) },
              )
              createEffect(() =>
                numberGlow.animate({
                  level: status().attention || status().unread === "error" || complete() ? 1 : 0,
                }),
              )
              const previous = createMemo(() => items()[index() - 1])
              const previousStatus = createMemo(() => {
                const tab = previous()
                return tab
                  ? itemStatus(tab)
                  : { ...EMPTY_SESSION_TAB_STATUS, complete: false, runs: false, glows: false }
              })
              const previousGlows = () => previousStatus().glows
              const previousRuns = () => previousStatus().runs
              const previousGlowLevel = createGlowLevel(
                () => previous()?.sessionID === activeID() && Boolean(previousStatus().attention),
                animations,
              )
              const indicatorWidth = 10
              let lastPreviousGlowHue: RGBA | undefined
              const previousGlowHue = () => {
                const feedback = tabFeedbackColor(previousStatus(), theme)
                if (feedback) return (lastPreviousGlowHue = feedback)
                if (previousStatus().unread !== undefined) return (lastPreviousGlowHue = unreadColor())
                return lastPreviousGlowHue ?? unreadColor()
              }
              const separatorUpperColor = createMemo(() =>
                tint(background(), previousGlowHue(), 0.1 * previousGlowLevel()),
              )
              const separatorLowerColor = createMemo(() =>
                tint(background(), glowHue(), 0.12 * glowLevel()),
              )
              const titleColor = (index: number, separator: boolean) => {
                const level = titleGlow.value().level
                const color =
                  level === 0
                    ? foreground()
                    : glowTextColor(foreground(), glowColor(), 1 + numberWidth() + index, width(), level)
                const faded = titleFades()
                  ? fadeTitleColor(
                      color,
                      pulseBackground(),
                      index,
                      visibleTitleParts().length,
                      scrolling() ? marquee.leading() : 0,
                    )
                  : color
                return separator ? tint(faded, pulseBackground(), 0.55) : faded
              }
              return (
                <box
                  height={compact() ? 1 : 2}
                  width="100%"
                  position="relative"
                  flexDirection="column"
                  backgroundColor={tabBackground()}
                  onMouseOver={(event) => {
                    setHoverY(event.y)
                    marquee.enter(tab.sessionID, title(), compact() ? Infinity : hoveredTitleWidth())
                  }}
                  onMouseOut={() => marquee.leave(tab.sessionID)}
                  onMouseDown={(event) => {
                    if (event.button === MIDDLE_MOUSE_BUTTON) {
                      didDrag = false
                      setDragging(undefined)
                      tabs.close(tab.sessionID)
                      event.preventDefault()
                      event.stopPropagation()
                      return
                    }
                    if (event.button === RIGHT_MOUSE_BUTTON) {
                      didDrag = false
                      setDragging(undefined)
                      if (!rail) return
                      setContextMenu({
                        x: event.x,
                        y: event.y,
                        sessionID: tab.sessionID,
                        title: tab.title,
                      })
                      event.preventDefault()
                      event.stopPropagation()
                      return
                    }
                    didDrag = false
                    marquee.enter(tab.sessionID, title(), compact() ? Infinity : hoveredTitleWidth())
                    setDragging(tab.sessionID)
                  }}
                >
                  <Show when={compact()}>
                    <Show when={highlighted(tab.sessionID)}>
                      <SessionTabHalfRow
                        top={-1}
                        edge="top"
                        width={width()}
                        color={pulseBackground()}
                        background={
                          highlighted(items()[index() - 1]?.sessionID) ? highlightColor() : background()
                        }
                      />
                      <SessionTabHalfRow
                        top={1}
                        edge="bottom"
                        width={width()}
                        color={pulseBackground()}
                        background={
                          (
                            index() === items().length - 1
                              ? addHighlighted()
                              : highlighted(items()[index() + 1]?.sessionID)
                          )
                            ? highlightColor()
                            : background()
                        }
                      />
                    </Show>
                    <box height={1} flexDirection="row" justifyContent="center">
                      <TabIndicator
                        centered
                        selected={selected()}
                        width={width()}
                        status={status()}
                        label={sessionTabNumberLabel(index())}
                        idleLabel={Locale.graphemes(title().trimStart())[0] ?? "U"}
                        color={
                          selected()
                            ? theme.text.base
                            : props.numbers
                              ? numberColor()
                              : (tabFeedbackColor(status(), theme) ?? (runs() ? activeNumber() : foreground()))
                        }
                        unreadColor={tabFeedbackColor(status(), theme) ?? unreadColor()}
                        backgroundColor={pulseBackground()}
                        flashColor={theme.text.base}
                        animations={animations()}
                        numbers={props.numbers}
                        spinner={props.spinner}
                        unreadMarker={props.unreadMarker}
                        attributes={selected() ? TextAttributes.BOLD : undefined}
                      />
                    </box>
                  </Show>
                  <Show when={!compact()}>
                    <TabPulse
                      top={-1}
                      edge="above"
                      enabled={animations()}
                      active={runs()}
                      outerActive={previousRuns()}
                      promptPulse={status().promptPulse}
                      outerPromptPulse={previousStatus().promptPulse}
                      complete={complete() && !status().attention}
                      outerComplete={previousStatus().complete && !previousStatus().attention}
                      glow={glows()}
                      outerGlow={previousGlows()}
                      color={separatorLowerPulseColor()}
                      width={indicatorWidth}
                      outerColor={separatorUpperPulseColor()}
                      flashColor={tint(background(), theme.text.base, 0.22)}
                      outerFlashColor={tint(background(), theme.text.base, 0.18)}
                      flashTail={8}
                      glowColor={separatorLowerColor()}
                      outerGlowColor={separatorUpperColor()}
                      glowTail={8}
                      outerGlowTail={5}
                      completionColor={separatorLowerColor()}
                      outerCompletionColor={separatorUpperColor()}
                      backgroundColor={background()}
                    />
                    <Show when={index() === items().length - 1}>
                      <TabPulse
                        top={2}
                        edge="below"
                        enabled={animations()}
                        active={runs()}
                        outerActive={false}
                        promptPulse={status().promptPulse}
                        outerPromptPulse={0}
                        complete={complete() && !status().attention}
                        outerComplete={false}
                        glow={glows()}
                        outerGlow={false}
                        color={tint(background(), theme.text.base, 0.04)}
                        width={indicatorWidth}
                        outerColor={tint(background(), theme.text.base, 0.006)}
                        flashColor={tint(background(), theme.text.base, 0.18)}
                        flashTail={8}
                        glowColor={tint(background(), glowHue(), 0.1 * glowLevel())}
                        outerGlowColor={background()}
                        glowTail={8}
                        outerGlowTail={5}
                        completionColor={tint(background(), glowHue(), 0.1 * glowLevel())}
                        outerCompletionColor={background()}
                        backgroundColor={background()}
                      />
                    </Show>
                    <box height={1} width="100%" flexDirection="row" position="relative">
                      <TabPulse
                        enabled={animations()}
                        active={runs()}
                        promptPulse={status().promptPulse}
                        complete={complete() && !status().attention}
                        glow={glows()}
                        color={pulseColor()}
                        width={indicatorWidth}
                        glowColor={glowColor()}
                        flashColor={flashColor()}
                        flashTail={8}
                        completionColor={glowColor()}
                        backgroundColor={pulseBackground()}
                        onLevel={setSweepLevel}
                      />
                      <box zIndex={1} width="100%" flexDirection="row" paddingRight={1}>
                        <TabIndicator
                          status={status()}
                          label={sessionTabNumberLabel(index())}
                          width={numberWidth()}
                          color={numberColor()}
                          unreadColor={tabFeedbackColor(status(), theme) ?? unreadColor()}
                          backgroundColor={pulseBackground()}
                          flashColor={theme.text.base}
                          animations={animations()}
                          numbers={props.numbers}
                          spinner={props.spinner}
                          unreadMarker={props.unreadMarker}
                          attributes={selected() ? TextAttributes.BOLD : undefined}
                        />
                        <title_shimmer
                          width={titleWidth()}
                          height={1}
                          fg={foreground()}
                          rename={{ pending: status().renaming, title: title() }}
                          enabled={animations()}
                          backdrop={pulseBackground()}
                          wrapMode="none"
                          selectable={false}
                          attributes={
                            status().renaming && !animations()
                              ? TextAttributes.DIM
                              : selected()
                                ? TextAttributes.BOLD
                                : undefined
                          }
                        >
                          <Show
                            when={scrolling() || titleGlow.value().level > 0 || titleFades()}
                            fallback={visibleTitle()}
                          >
                            <Index each={visibleTitleParts()}>
                              {(part, index) => (
                                <span style={{ fg: titleColor(index, part().separator) }}>{part().value}</span>
                              )}
                            </Index>
                          </Show>
                        </title_shimmer>
                        <text
                          position="absolute"
                          right={1}
                          zIndex={2}
                          width={1}
                          fg={closeHovered() ? theme.text.base : theme.text.muted}
                          selectable={false}
                          onMouseOver={() => setCloseHovered(true)}
                          onMouseOut={() => setCloseHovered(false)}
                          onMouseDown={(event) => {
                            if (event.button === RIGHT_MOUSE_BUTTON || hovered() !== tab.sessionID) return
                            didDrag = false
                            event.stopPropagation()
                          }}
                          onMouseUp={(event) => {
                            if (event.button === RIGHT_MOUSE_BUTTON) return
                            if (suppressClick) return
                            if (hovered() !== tab.sessionID) return
                            event.stopPropagation()
                            tabs.close(tab.sessionID)
                          }}
                        >
                          {hovered() === tab.sessionID ? "✕" : ""}
                        </text>
                      </box>
                    </box>
                    <box height={1} width="100%" position="relative" flexDirection="row">
                      <TabPulse
                        enabled={animations()}
                        active={runs()}
                        promptPulse={status().promptPulse}
                        complete={complete() && !status().attention}
                        glow={glows()}
                        color={detailPulseColor()}
                        width={indicatorWidth}
                        glowColor={detailGlowColor()}
                        glowTail={10}
                        flashColor={detailFlashColor()}
                        flashTail={8}
                        completionColor={detailGlowColor()}
                        backgroundColor={pulseBackground()}
                      />
                      <box zIndex={1} width="100%" flexDirection="row" paddingLeft={prefixWidth()} paddingRight={2}>
                        <text fg={detailColor()} wrapMode="none" selectable={false}>
                          <Show when={detailFades()} fallback={visibleDetail()}>
                            <For each={visibleDetailParts()}>
                              {(character, index) => <span style={{ fg: detailTextColor(index()) }}>{character}</span>}
                            </For>
                          </Show>
                        </text>
                      </box>
                    </box>
                  </Show>
                </box>
              )
            }}
          </For>
          {/* One slot with two states: a muted affordance that promotes in place into the
              active new-session tab, instead of spawning a separate pseudo tab above itself. */}
          <Show when={tabs.add || newTab()}>
            <box
              height={1}
              width="100%"
              position="relative"
              flexDirection="row"
              paddingLeft={compact() ? 0 : 1}
              justifyContent={compact() ? "center" : "flex-start"}
              alignItems="center"
              backgroundColor={
                newTab() && !compact()
                  ? actionSelected()
                  : addHovered() || (compact() && newTab())
                    ? actionHovered()
                    : background()
              }
              onMouseOver={() => setAddHovered(true)}
              onMouseOut={() => setAddHovered(false)}
              onMouseDown={(event: MouseEvent) => {
                didDrag = false
                setDragging(undefined)
                addPressed = event.button !== RIGHT_MOUSE_BUTTON
                if (addPressed) return
                if (!rail) return
                setContextMenu({ x: event.x, y: event.y })
                event.preventDefault()
                event.stopPropagation()
              }}
              onMouseUp={(event: MouseEvent) => {
                if (event.button === RIGHT_MOUSE_BUTTON) return
                if (suppressClick) return
                if (!addPressed) return
                addPressed = false
                if (!newTab()) tabs.add?.()
              }}
              onMouseDragEnd={() => (addPressed = false)}
            >
              <Show when={compact() && addHighlighted()}>
                <SessionTabHalfRow
                  top={-1}
                  edge="top"
                  width={width()}
                  color={highlightColor()}
                  background={highlighted(items().at(-1)?.sessionID) ? highlightColor() : background()}
                />
                <SessionTabHalfRow
                  top={1}
                  edge="bottom"
                  width={width()}
                  color={highlightColor()}
                  background={background()}
                />
              </Show>
              <text
                width={compact() ? 1 : 2}
                fg={newTab() || addHovered() ? theme.text.base : idleNumber()}
                selectable={false}
                attributes={newTab() ? TextAttributes.BOLD : undefined}
              >
                +
              </text>
              <Show when={!compact()}>
                <text
                  fg={newTab() || addHovered() ? theme.text.base : theme.text.muted}
                  wrapMode="none"
                  selectable={false}
                  attributes={newTab() ? TextAttributes.BOLD : undefined}
                >
                  {NEW_SESSION_TAB_TITLE}
                </text>
              </Show>
              <Show when={newTab() && !compact()}>
                <text
                  position="absolute"
                  right={1}
                  zIndex={2}
                  width={1}
                  fg={theme.text.muted}
                  selectable={false}
                  onMouseUp={(event) => {
                    if (event.button === RIGHT_MOUSE_BUTTON) return
                    if (suppressClick) return
                    if (!addHovered()) return
                    event.stopPropagation()
                    tabs.close()
                  }}
                >
                  {addHovered() ? "×" : ""}
                </text>
              </Show>
            </box>
          </Show>
        </box>
      </scrollbox>
      <Show when={compact() && !dragging() && !contextMenu() && hovered()}>
        {(sessionID) => (
          <box
            position="absolute"
            left={width()}
            top={Math.max(0, Math.min(hoverY() - 1, dimensions().height - 4) - (rail?.screenY ?? 0))}
            width={tooltipWidth()}
            height={4}
            paddingY={1}
            zIndex={2000}
          >
            <SessionTabHalfRow
              top={0}
              edge="top"
              width={tooltipWidth()}
              color={background()}
              background={base.background.base}
            />
            <box height={2} paddingX={1} backgroundColor={background()}>
              <text fg={theme.text.base} wrapMode="none" selectable={false}>
                {Locale.truncateWidth(
                  data?.session.get(sessionID())?.title ??
                    items().find((tab) => tab.sessionID === sessionID())?.title ??
                    "Untitled session",
                  tooltipWidth() - 2,
                )}
              </text>
              <text fg={theme.text.muted} wrapMode="none" selectable={false}>
                {Locale.takeWidth(detail(sessionID()), tooltipWidth() - 2)}
              </text>
            </box>
            <SessionTabHalfRow
              top={3}
              edge="bottom"
              width={tooltipWidth()}
              color={background()}
              background={base.background.base}
            />
          </box>
        )}
      </Show>
      <Show when={contextMenu()}>
        {(state) => <TabContextMenu state={state()} tabs={tabs} onClose={() => setContextMenu(undefined)} />}
      </Show>
    </box>
  )
}

function HorizontalSessionTabs(props: {
  controller?: SessionTabsController
  animations?: boolean
  spinner?: TabSpinner
  unreadMarker?: TabUnreadMarker
  numbers: boolean
}) {
  const tabs = props.controller ?? useSessionTabs()
  const data = props.controller ? undefined : useData()
  const dimensions = useTerminalDimensions()
  const theme = useTheme()
  const config = useConfig().data
  const animations = () => props.animations ?? config.animations ?? true
  const [addHovered, setAddHovered] = createSignal(false)
  const marquee = createTabMarquee(animations)
  const hovered = marquee.hovered
  // OpenTUI captures the first drag target, which may differ from the tab pressed on a fast move.
  const [dragging, setDragging] = createSignal<string>()
  // A drag reorders a local preview and persists one move on release instead of writing
  // per slot crossing; the preview holds after release until the store reflects the move,
  // so the strip never flashes the pre-drag order while the write is in flight.
  const [preview, setPreview] = createSignal<{ sessionID: string; index: number }>()
  const [contextMenu, setContextMenu] = createSignal<TabContextMenuState>()
  const [closeHold, setCloseHold] = createSignal<MouseCloseHold>()
  let strip: { screenX: number; screenY: number; width: number; height: number } | undefined
  let didDrag = false
  let addPressed = false
  let closeHoldTimer: ReturnType<typeof setTimeout> | undefined
  let releasingCloseHold = false
  const clearCloseHold = () => {
    setCloseHold(undefined)
    if (closeHoldTimer) clearTimeout(closeHoldTimer)
    closeHoldTimer = undefined
  }
  const releaseCloseHold = () => {
    if (!closeHold()) return
    releasingCloseHold = true
    clearCloseHold()
  }
  onCleanup(clearCloseHold)
  // A captured drag ends with a synthetic up on its drop target; do not turn that into a click.
  let suppressClick = false
  const unreadColor = () => theme.hue.accent[200]
  const activeNumber = () => theme.hue.interactive[200]
  const idleNumber = () => tint(theme.text.formfield.base, theme.background.base, 0.55)
  const newTab = () => tabs.newTab?.() ?? false
  const activeID = createMemo(() => (newTab() ? NEW_SESSION_TAB.sessionID : tabs.current()))
  const ordered = createMemo(() => {
    const pending = preview()
    if (!pending) return tabs.tabs()
    return moveSessionTab(tabs.tabs(), pending.sessionID, pending.index)
  })
  // The promoted new-session slot joins the strip as the active tab; the idle plus affordance
  // and the promoted slot are mutually exclusive states of one control.
  const items = createMemo(() => (newTab() ? [...ordered(), NEW_SESSION_TAB] : ordered()))
  const showPlus = () => Boolean(tabs.add) && !newTab()
  createEffect(() => {
    const pending = preview()
    if (!pending || dragging()) return
    const index = tabs.tabs().findIndex((tab) => tab.sessionID === pending.sessionID)
    if (index === -1 || index === Math.min(pending.index, tabs.tabs().length - 1)) setPreview(undefined)
  })
  const heldLayout = createMemo(() => {
    const hold = closeHold()
    return hold ? heldSessionTabLayout(hold, items()) : undefined
  })
  const layout = createMemo(
    (previous: ReturnType<typeof adaptiveSessionTabLayout> | undefined) =>
      heldLayout() ??
      adaptiveSessionTabLayout(
        items(),
        activeID(),
        dimensions().width - (showPlus() ? ADD_TAB_WIDTH : 0),
        previous?.start,
      ),
  )
  createEffect(() => {
    if (closeHold() && !heldLayout()) clearCloseHold()
  })
  createEffect(() => {
    const active = marquee.active()
    if (active && !layout().tabs.some((tab) => tab.sessionID === active)) marquee.reset()
  })
  const statuses = createMemo(
    () =>
      new Map(
        layout().tabs.map((tab) => {
          const status = tab === NEW_SESSION_TAB ? EMPTY_SESSION_TAB_STATUS : tabs.status(tab.sessionID)
          return [
            tab.sessionID,
            {
              ...status,
              complete: sessionTabComplete(status.unread, status.busy),
            },
          ] as const
        }),
      ),
  )
  const targets = createMemo(() => ({
    widths: layout().widths,
    selections: layout().tabs.map((tab) => Number(tab.sessionID === activeID())),
    activities: layout().tabs.map((tab) => Number(statuses().get(tab.sessionID)!.complete)),
  }))
  const motion = createAnimatable(targets(), {
    enabled: animations,
    transition: spring({ visualDuration: 0.1 }),
  })
  const identity = createMemo(() =>
    layout()
      .tabs.map((tab) => tab.sessionID)
      .join(":"),
  )
  let signature = ""
  let total = 0
  let terminalWidth = dimensions().width

  // createComputed runs before render effects, so seeded widths are visible on the first frame
  // of a membership change instead of flashing the final layout.
  createComputed(() => {
    const next = targets()
    const nextSignature = identity()
    const changed = Boolean(signature) && signature !== nextSignature
    const resized = Boolean(total) && total !== layout().total
    const terminalResized = terminalWidth !== dimensions().width
    const previous = signature
    signature = nextSignature
    total = layout().total
    terminalWidth = dimensions().width
    const releasing = releasingCloseHold
    releasingCloseHold = false
    if (terminalResized && closeHold()) {
      clearCloseHold()
      return
    }
    if (closeHold() && heldLayout()) {
      const current = untrack(motion.value)
      const seeded = changed
        ? seedSessionTabMotion(
            previous.split(":"),
            layout().tabs.map((tab) => tab.sessionID),
            current,
            next,
          )
        : current
      if (!seeded) return motion.jump(next)
      motion.jump({ ...seeded, widths: next.widths })
      return motion.animate(next)
    }
    if (!changed && !resized) return motion.animate(next)
    // Identity-stable total changes are terminal resizes and still jump.
    if (!changed) return releasing ? motion.animate(next) : motion.jump(next)
    const seeded = seedSessionTabMotion(
      previous.split(":"),
      layout().tabs.map((tab) => tab.sessionID),
      untrack(motion.value),
      next,
    )
    if (!seeded) return motion.jump(next)
    motion.jump(seeded)
    motion.animate(next)
  })

  const activeIndex = createMemo(() => layout().tabs.findIndex((tab) => tab.sessionID === activeID()))
  const visuals = createMemo(() => {
    const current = signature === identity() && total === layout().total ? motion.value() : targets()
    const widths = current.widths.map((width) => Math.max(1, Math.round(width)))
    const active = activeIndex()
    const remainder = layout().total - widths.reduce((sum, width) => sum + width, 0)
    // Absorb only rounding slack; membership animations leave a real gap while widths grow into place.
    if (active !== -1 && Math.abs(remainder) <= layout().tabs.length) widths[active] += remainder
    return new Map(
      layout().tabs.map((tab, index) => [
        tab.sessionID,
        {
          width: widths[index],
          selection: current.selections[index] ?? Number(tab.sessionID === activeID()),
          activity: current.activities[index] ?? Number(statuses().get(tab.sessionID)!.complete),
        },
      ]),
    )
  })

  const holdCloseCell = (sessionID: string, x: number) => {
    if (!strip) return clearCloseHold()
    const current = layout()
    const index = current.tabs.findIndex((tab) => tab.sessionID === sessionID)
    const all = items()
    const itemIndex = all.findIndex((tab) => tab.sessionID === sessionID)
    const target = all[itemIndex + 1] ?? all[itemIndex - 1]
    if (index === -1 || itemIndex === -1 || !target) return clearCloseHold()
    const ids = current.tabs.map((tab) => tab.sessionID)
    const values = ids.map((id) => visuals().get(id))
    if (values.some((value) => !value)) return clearCloseHold()
    setCloseHold({
      items: all.map((tab) => tab.sessionID),
      ids,
      widths: values.map((value) => value!.width),
      closed: sessionID,
      target: target.sessionID,
      x: x - strip.screenX,
    })
    if (closeHoldTimer) clearTimeout(closeHoldTimer)
    closeHoldTimer = setTimeout(releaseCloseHold, MOUSE_CLOSE_HOLD_MS)
  }

  // Map an absolute pointer column to the items index of the visible slot beneath it.
  const slotAt = (x: number) => {
    if (!strip) return undefined
    const stripX = x - strip.screenX
    let edge = layout().before > 0 ? sessionTabOverflowWidth(layout().before) : 0
    for (const [index, width] of layout().widths.entries()) {
      edge += width
      if (stripX < edge) return layout().before + index
    }
    return layout().before + layout().widths.length - 1
  }

  const release = () => {
    const source = dragging()
    if (!source) return
    if (didDrag) suppressClick = true
    setDragging(undefined)
    const pending = preview()
    if (pending?.sessionID === source) tabs.move(pending.sessionID, pending.index)
    if (source === NEW_SESSION_TAB.sessionID) return
    tabs.select(source)
  }

  const drag = (event: MouseEvent) => {
    const source = dragging()
    if (!source || source === NEW_SESSION_TAB.sessionID) return
    didDrag = true
    const slot = slotAt(event.x)
    const target = slot === undefined ? undefined : Math.min(slot, tabs.tabs().length - 1)
    const sourceIndex = items().findIndex((item) => item.sessionID === source)
    if (target !== undefined && target !== sourceIndex && preview()?.index !== target) {
      setPreview({ sessionID: source, index: target })
    }
  }

  return (
    <box
      ref={(element) => (strip = element)}
      height={1}
      flexShrink={0}
      position="relative"
      flexDirection="row"
      zIndex={1}
      onMouseOut={(event) => {
        marquee.leaveHovered()
        if (!strip) return
        if (
          event.x < strip.screenX ||
          event.x >= strip.screenX + strip.width ||
          event.y < strip.screenY ||
          event.y >= strip.screenY + strip.height
        )
          releaseCloseHold()
      }}
      onMouseUp={(event) => {
        if (event.button === RIGHT_MOUSE_BUTTON) return
        release()
        if (!didDrag) return
        didDrag = false
        queueMicrotask(() => (suppressClick = false))
      }}
      onMouseDrag={drag}
      onMouseDragEnd={release}
    >
      <Show when={layout().before > 0}>
        <text width={sessionTabOverflowWidth(layout().before)} fg={theme.text.muted} selectable={false}>
          ‹{layout().before}
        </text>
      </Show>
      <For each={layout().tabs}>
        {(tab) => {
          const selected = () => activeID() === tab.sessionID
          const status = () => statuses().get(tab.sessionID)!
          const width = () => visuals().get(tab.sessionID)?.width ?? 1
          const selection = () => visuals().get(tab.sessionID)?.selection ?? Number(selected())
          const activity = () => visuals().get(tab.sessionID)?.activity ?? Number(status().complete)
          const dragged = () => dragging() === tab.sessionID
          const background = createMemo(() => {
            const lifted = (hovered() === tab.sessionID || dragged()) && !selected()
            const base = lifted ? theme.background.action.primary.hovered : theme.background.base
            // A dragged tab lifts to full selected elevation while it is held.
            return tint(base, theme.decrease(theme.background.raised.base), dragged() ? 1 : selection())
          })
          const pulseColor = () => tint(background(), theme.text.base, 0.45)
          // The edge flash washes toward a brighter stop on the same background-to-text ramp,
          // so it reads as a lift of the pulse color rather than a different hue.
          const flashColor = () => tint(background(), theme.text.base, 0.65)
          const feedbackColor = () => tabFeedbackColor(status(), theme)
          const glowLevel = createGlowLevel(() => selected() && Boolean(status().attention), animations)
          const glowColor = createMemo(() => tint(background(), feedbackColor() ?? unreadColor(), glowLevel()))
          const glows = () =>
            Boolean(status().attention || (!selected() && !status().busy && status().unread !== undefined))
          const title = () => data?.session.get(tab.sessionID)?.title ?? tab.title ?? "Untitled session"
          const tabNumber = createMemo(() => items().findIndex((item) => item.sessionID === tab.sessionID) + 1)
          const numberWidth = () => Math.max(2, String(items().length).length)
          // Hovering reveals the close mark, so the title's right bound shifts left of it.
          const restingTitleWidth = () => Math.max(1, width() - 1 - numberWidth())
          const hoveredTitleWidth = () => Math.max(1, restingTitleWidth() - 2)
          const availableTitleWidth = () => (hovered() === tab.sessionID ? hoveredTitleWidth() : restingTitleWidth())
          const scrolling = () => marquee.active() === tab.sessionID
          const visibleTitleParts = createMemo(() =>
            scrolling()
              ? marqueeTextParts(title(), availableTitleWidth(), marquee.offset())
              : Locale.graphemes(Locale.takeWidth(title(), availableTitleWidth())).map((value) => ({
                  value,
                  separator: false,
                })),
          )
          const visibleTitle = createMemo(() =>
            visibleTitleParts()
              .map((part) => part.value)
              .join(""),
          )
          const titleFades = createMemo(
            () => marqueeOverflows(title(), availableTitleWidth()) && availableTitleWidth() > FADE_WIDTH,
          )
          const runs = () => status().busy && !status().attention
          const numberIgnition = createNumberIgnition(runs, () => status().promptPulse, animations)
          const foreground = () => {
            if (hovered() === tab.sessionID) return theme.text.base
            return tint(theme.text.muted, theme.text.base, selection())
          }
          // Title characters sitting over the glow tinge toward its color, following the same
          // spatial falloff as the glow itself; characters beyond the tail stay neutral.
          const characterColor = (index: number, separator: boolean) => {
            const base = foreground()
            const color = glows() ? glowTextColor(base, glowColor(), 1 + numberWidth() + index, width()) : base
            const faded = titleFades()
              ? fadeTitleColor(
                  color,
                  background(),
                  index,
                  visibleTitleParts().length,
                  scrolling() ? marquee.leading() : 0,
                )
              : color
            return separator ? tint(faded, background(), 0.55) : faded
          }
          // The running sweep's level under the number cell, reported by the pulse renderable.
          const [sweepLevel, setSweepLevel] = createSignal(0)
          const [closeHovered, setCloseHovered] = createSignal(false)
          const numberColor = () => {
            const feedback = feedbackColor()
            const base =
              hovered() === tab.sessionID && !selected()
                ? foreground()
                : tint(idleNumber(), tint(theme.text.base, background(), 0.25), selection())
            const color = runs() ? activeNumber() : (feedback ?? tint(base, unreadColor(), activity()))
            // The number brightens faintly as the running sweep passes beneath it.
            return tint(color, theme.text.base, Math.max(numberIgnition.value().level, 0.15 * sweepLevel()))
          }
          const bold = () => (selected() || dragged() ? TextAttributes.BOLD : undefined)
          const closeColor = () => tint(theme.text.muted, theme.text.base, 0.6)
          return (
            <box
              width={width()}
              position="relative"
              flexDirection="row"
              backgroundColor={background()}
              onMouseOver={() => marquee.enter(tab.sessionID, title(), hoveredTitleWidth())}
              onMouseOut={() => marquee.leave(tab.sessionID)}
              onMouseDown={(event) => {
                if (event.button === MIDDLE_MOUSE_BUTTON) {
                  releaseCloseHold()
                  didDrag = false
                  setDragging(undefined)
                  tabs.close(tab === NEW_SESSION_TAB ? undefined : tab.sessionID)
                  event.preventDefault()
                  event.stopPropagation()
                  return
                }
                if (event.button === RIGHT_MOUSE_BUTTON) {
                  releaseCloseHold()
                  didDrag = false
                  setDragging(undefined)
                  setContextMenu({
                    x: event.x,
                    y: event.y,
                    sessionID: tab === NEW_SESSION_TAB ? undefined : tab.sessionID,
                    title: tab === NEW_SESSION_TAB ? undefined : tab.title,
                  })
                  event.preventDefault()
                  event.stopPropagation()
                  return
                }
                didDrag = false
                releaseCloseHold()
                marquee.enter(tab.sessionID, title(), hoveredTitleWidth())
                setDragging(tab.sessionID)
              }}
            >
              <TabPulse
                enabled={animations()}
                active={status().busy && !status().attention}
                promptPulse={status().promptPulse}
                complete={status().complete && !status().attention}
                glow={glows()}
                color={pulseColor()}
                glowColor={glowColor()}
                flashColor={flashColor()}
                completionColor={unreadColor()}
                backgroundColor={background()}
                onLevel={setSweepLevel}
              />
              <box zIndex={1} width="100%" flexDirection="row">
                <TabIndicator
                  status={status()}
                  label={tab === NEW_SESSION_TAB ? "+" : sessionTabNumberLabel(tabNumber() - 1)}
                  width={numberWidth()}
                  color={numberColor()}
                  unreadColor={feedbackColor() ?? unreadColor()}
                  backgroundColor={background()}
                  flashColor={theme.text.base}
                  animations={animations()}
                  numbers={props.numbers}
                  spinner={props.spinner}
                  unreadMarker={props.unreadMarker}
                  attributes={bold()}
                />
                <title_shimmer
                  width={availableTitleWidth()}
                  height={1}
                  fg={foreground()}
                  rename={{ pending: status().renaming, title: title() }}
                  enabled={animations()}
                  backdrop={background()}
                  wrapMode="none"
                  selectable={false}
                  attributes={status().renaming && !animations() ? TextAttributes.DIM : bold()}
                >
                  <Show when={scrolling() || glows() || titleFades()} fallback={visibleTitle()}>
                    <Index each={visibleTitleParts()}>
                      {(part, index) => (
                        <span style={{ fg: characterColor(index, part().separator) }}>{part().value}</span>
                      )}
                    </Index>
                  </Show>
                </title_shimmer>
                <text
                  position="absolute"
                  right={1}
                  zIndex={2}
                  width={1}
                  fg={closeHovered() ? theme.text.base : closeColor()}
                  selectable={false}
                  onMouseOver={() => setCloseHovered(true)}
                  onMouseOut={() => setCloseHovered(false)}
                  onMouseDown={(event) => {
                    if (event.button === RIGHT_MOUSE_BUTTON || hovered() !== tab.sessionID) return
                    didDrag = false
                    event.stopPropagation()
                  }}
                  onMouseUp={(event) => {
                    if (event.button === RIGHT_MOUSE_BUTTON) return
                    if (suppressClick) return
                    // The close mark only renders while hovered; without motion events a click can
                    // land here first, and must select the tab instead of closing it invisibly.
                    if (hovered() !== tab.sessionID) return
                    event.stopPropagation()
                    holdCloseCell(tab.sessionID, event.x)
                    tabs.close(tab === NEW_SESSION_TAB ? undefined : tab.sessionID)
                  }}
                >
                  {hovered() === tab.sessionID ? "✕" : ""}
                </text>
              </box>
            </box>
          )
        }}
      </For>
      <Show when={layout().after > 0}>
        <text width={sessionTabOverflowWidth(layout().after)} fg={theme.text.muted} selectable={false}>
          {" " + layout().after}›
        </text>
      </Show>
      <Show when={showPlus()}>
        <text
          width={ADD_TAB_WIDTH}
          fg={addHovered() ? theme.text.base : theme.text.muted}
          bg={addHovered() ? theme.background.action.primary.hovered : undefined}
          selectable={false}
          onMouseOver={() => setAddHovered(true)}
          onMouseOut={() => setAddHovered(false)}
          onMouseDown={(event) => {
            releaseCloseHold()
            didDrag = false
            setDragging(undefined)
            addPressed = event.button !== RIGHT_MOUSE_BUTTON
            if (addPressed) return
            setContextMenu({ x: event.x, y: event.y })
            event.preventDefault()
            event.stopPropagation()
          }}
          onMouseUp={(event) => {
            if (event.button === RIGHT_MOUSE_BUTTON) return
            if (suppressClick) return
            if (!addPressed) return
            addPressed = false
            tabs.add?.()
          }}
          onMouseDragEnd={() => (addPressed = false)}
        >
          {" + "}
        </text>
      </Show>
      <Show when={contextMenu()}>
        {(state) => <TabContextMenu state={state()} tabs={tabs} onClose={() => setContextMenu(undefined)} />}
      </Show>
    </box>
  )
}

import { RGBA, type OptimizedBuffer, type RenderContext, type TextOptions } from "@opentui/core"
import { extend, type JSX } from "@opentui/solid"
import { splitProps } from "solid-js"
import { MaskedTextRenderable } from "./masked-text"
import { coast, intensityAt } from "./tab-pulse"

type ShimmerTextOptions = TextOptions & {
  shimmer: RGBA
}

const DURATION = 1200

class ShimmerTextRenderable extends MaskedTextRenderable {
  private _shimmer = RGBA.defaultForeground()
  private elapsed = 0

  constructor(ctx: RenderContext, options: ShimmerTextOptions) {
    super(ctx, options)
    this.matrix[3] = this._shimmer.r
    this.matrix[7] = this._shimmer.g
    this.matrix[11] = this._shimmer.b
    this.matrix[15] = 1
    if (options.shimmer) this.shimmer = options.shimmer
    this.live = true
  }

  set shimmer(value: RGBA) {
    if (value.equals(this._shimmer)) return
    this._shimmer = value
    this.matrix[3] = value.r
    this.matrix[7] = value.g
    this.matrix[11] = value.b
    this.requestRender()
  }

  override render(buffer: OptimizedBuffer, deltaTime: number) {
    if (!this.visible || this.isDestroyed || !Number.isFinite(this.width) || this.width <= 0 || this.height <= 0) return
    this.elapsed = (this.elapsed + deltaTime) % DURATION
    this.renderMasked(buffer, 0, (end) => {
      const front = -4 + coast(this.elapsed / DURATION) * (end + 22)
      return (column) => intensityAt(column, front, 4, 18)
    })
  }
}

extend({ shimmer_text: ShimmerTextRenderable })

declare module "@opentui/solid" {
  interface OpenTUIComponents {
    shimmer_text: typeof ShimmerTextRenderable
  }
}

type Props = Omit<JSX.IntrinsicElements["text"], "ref"> & { shimmer: RGBA }

export function ShimmerText(props: Props) {
  const [local, text] = splitProps(props, ["shimmer"])
  return <shimmer_text {...text} shimmer={local.shimmer} />
}

import { createEffect, createSignal, onCleanup, Show } from "solid-js"
import { useTheme } from "../context/theme"
import { useConfig } from "../config"
import type { JSX } from "@opentui/solid"
import type { RGBA } from "@opentui/core"
import { registerOpencodeSpinner } from "./register-spinner"
import { SPINNER_FRAMES } from "./spinner-frames"
import { ShimmerText } from "./shimmer-text"

export { SPINNER_FRAMES } from "./spinner-frames"

registerOpencodeSpinner()

export function Spinner(props: { children?: JSX.Element; color?: RGBA; shimmer?: RGBA }) {
  const theme = useTheme()
  const config = useConfig().data
  const color = () => props.color ?? theme.text.muted
  const [frame, setFrame] = createSignal(0)
  createEffect(() => {
    if (!(config.animations ?? true) || !props.shimmer) return
    const timer = setInterval(() => setFrame((value) => (value + 1) % SPINNER_FRAMES.length), 80)
    onCleanup(() => clearInterval(timer))
  })
  // A bare spinner beside a long sibling shrinks to a fractional width that rounds to 0, so the
  // glyph paints on top of the row gap. Only a labeled spinner may shrink (to wrap its text).
  return (
    <Show
      when={config.animations ?? true}
      fallback={<text fg={color()}>{props.children ? <>⋯ {props.children}</> : "⋯"}</text>}
    >
      <Show
        when={props.shimmer}
        fallback={
          <box flexDirection="row" gap={1} flexShrink={props.children ? 1 : 0}>
            <box flexShrink={0}>
              <spinner frames={SPINNER_FRAMES} interval={80} color={color()} />
            </box>
            <Show when={props.children}>
              <text fg={color()}>{props.children}</text>
            </Show>
          </box>
        }
      >
        {(shimmer) => (
          <ShimmerText fg={color()} shimmer={shimmer()}>
            {SPINNER_FRAMES[frame()]} {props.children}
          </ShimmerText>
        )}
      </Show>
    </Show>
  )
}

import { createEffect, createMemo, createSignal, onCleanup, Show } from "solid-js"
import { useTheme } from "../context/theme"
import { Spinner } from "./spinner"

export function StartupLoading(props: { ready: () => boolean }) {
  const theme = useTheme()
  const [show, setShow] = createSignal(false)
  const text = createMemo(() => (props.ready() ? "Finishing startup…" : "Loading plugins…"))
  let wait: NodeJS.Timeout | undefined
  let hold: NodeJS.Timeout | undefined
  let stamp = 0

  createEffect(() => {
    if (props.ready()) {
      if (wait) {
        clearTimeout(wait)
        wait = undefined
      }
      if (!show()) return
      if (hold) return

      const left = 3000 - (Date.now() - stamp)
      if (left <= 0) {
        setShow(false)
        return
      }

      hold = setTimeout(() => {
        hold = undefined
        setShow(false)
      }, left).unref()
      return
    }

    if (hold) {
      clearTimeout(hold)
      hold = undefined
    }
    if (show()) return
    if (wait) return

    wait = setTimeout(() => {
      wait = undefined
      stamp = Date.now()
      setShow(true)
    }, 500).unref()
  })

  onCleanup(() => {
    if (wait) clearTimeout(wait)
    if (hold) clearTimeout(hold)
  })

  return (
    <Show when={show()}>
      <box position="absolute" zIndex={5000} left={0} right={0} bottom={1} justifyContent="center" alignItems="center">
        <box backgroundColor={theme.background.raised.base} paddingLeft={1} paddingRight={1}>
          <Spinner color={theme.text.muted}>{text()}</Spinner>
        </box>
      </box>
    </Show>
  )
}

import { OptimizedBuffer, Renderable, RGBA, type RenderableOptions, type RenderContext } from "@opentui/core"
import { extend } from "@opentui/solid"

type TabPulseOptions = RenderableOptions<TabPulseRenderable> & {
  edge?: "above" | "below"
  enabled?: boolean
  active?: boolean
  outerActive?: boolean
  promptPulse?: number
  outerPromptPulse?: number
  complete?: boolean
  outerComplete?: boolean
  glow?: boolean
  outerGlow?: boolean
  color?: RGBA
  outerColor?: RGBA
  glowColor?: RGBA
  outerGlowColor?: RGBA
  glowTail?: number
  outerGlowTail?: number
  flashColor?: RGBA
  outerFlashColor?: RGBA
  flashTail?: number
  outerFlashTail?: number
  completionColor?: RGBA
  outerCompletionColor?: RGBA
  backgroundColor?: RGBA
  /** Reports the running sweep's intensity at the tab number's cell, quantized; 0 when idle. */
  onLevel?: (level: number) => void
}

export const clamp = (value: number) => Math.max(0, Math.min(1, value))
export const smootherstep = (value: number) => value * value * value * (value * (value * 6 - 15) + 10)
const RUN_DURATION = 2_800
const RUN_ATTACK = 450
const RUN_HEAD = 4
const RUN_TAIL = 18
const RUN_FADE_OUT = 500
const COMPLETION_DURATION = 1_200
const COMPLETION_ATTACK = 0.12
const COMPLETION_OPACITY = 0.18
const EDGE_FLASH_DURATION = 800
const EDGE_FLASH_ATTACK = 0.1
const EDGE_FLASH_OPACITY = 0.1
const PROMPT_FLASH_SCALE = 2
const GLOW_IGNITION_DURATION = 600
const GLOW_IGNITION_PEAK = 1.5
const GLOW_IGNITION_ATTACK = 0.3
const GLOW_FADE_OUT = 200
const GLOW_RELEASE_DURATION = 900
const GLOW_RELEASE_ATTACK = 0.12
const GLOW_RELEASE_PEAK = 1.25
const GLOW_TAIL = 12
const GLOW_OPACITY = 0.16
const DEFAULT_FOREGROUND = RGBA.defaultForeground()
export const intensityAt = (index: number, front: number, head: number, tail: number) => {
  const distance = front - index
  return distance < 0 ? smootherstep(clamp(1 + distance / head)) : smootherstep(clamp(1 - distance / tail))
}
export const coast = (value: number) => {
  const ramp = 0.2
  if (value < ramp) return (value * value) / (2 * ramp * (1 - ramp))
  if (value > 1 - ramp) return 1 - ((1 - value) * (1 - value)) / (2 * ramp * (1 - ramp))
  return (value - ramp / 2) / (1 - ramp)
}
const fadeOut = (progress: number) => 1 - smootherstep(progress)
/** Rise to peak over the attack fraction, then settle to rest over the remainder. */
const attackDecay = (progress: number, attack: number, peak: number, rest: number) =>
  progress < attack
    ? peak * smootherstep(clamp(progress / attack))
    : peak - (peak - rest) * smootherstep(clamp((progress - attack) / (1 - attack)))
export const completionPulseOpacity = (progress: number) => attackDecay(progress, COMPLETION_ATTACK, 1, 0)
export const glowIgnitionLevel = (progress: number) =>
  attackDecay(progress, GLOW_IGNITION_ATTACK, GLOW_IGNITION_PEAK, 1)
const glowIntensityAt = (index: number, tail: number) => smootherstep(clamp(1 - Math.max(0, index - 1) / tail))
export const tabFlashIntensity = (index: number, tail: number) => glowIntensityAt(index, tail)
export const unreadGlowIntensity = (index: number, width: number, maximumTail = GLOW_TAIL) => {
  const tail = Math.min(maximumTail, Math.max(1, width - 2))
  return glowIntensityAt(index, tail)
}
/** How far a resolving glow has diffused: the resting tail spreads across the full width as it thins away. */
const glowReleaseSpread = (progress: number, tail: number, width: number) => tail + smootherstep(progress) * width
// The resting glow drains away over this leading fraction of the release, i.e. the old 200ms fade.
const GLOW_RELEASE_DRAIN_FRACTION = GLOW_FADE_OUT / GLOW_RELEASE_DURATION
const glowReleaseDrain = (progress: number) => fadeOut(clamp(progress / GLOW_RELEASE_DRAIN_FRACTION))
/** The diffusing glow swells gently above its resting level, then decays to nothing. */
const glowReleaseSwell = (progress: number) => attackDecay(progress, GLOW_RELEASE_ATTACK, GLOW_RELEASE_PEAK, 0)
export function blendTabPulseColor(
  output: RGBA,
  background: RGBA,
  glowColor: RGBA,
  runningColor: RGBA,
  flashColor: RGBA,
  completionColor: RGBA,
  glow: number,
  running: number,
  flash: number,
  completion: number,
) {
  if (glow === 0) {
    output.r = background.r
    output.g = background.g
    output.b = background.b
  } else {
    output.r = background.r + (glowColor.r - background.r) * glow
    output.g = background.g + (glowColor.g - background.g) * glow
    output.b = background.b + (glowColor.b - background.b) * glow
  }
  if (running !== 0) {
    output.r += (runningColor.r - output.r) * running
    output.g += (runningColor.g - output.g) * running
    output.b += (runningColor.b - output.b) * running
  }
  if (flash !== 0) {
    output.r += (flashColor.r - output.r) * flash
    output.g += (flashColor.g - output.g) * flash
    output.b += (flashColor.b - output.b) * flash
  }
  if (completion !== 0) {
    output.r += (completionColor.r - output.r) * completion
    output.g += (completionColor.g - output.g) * completion
    output.b += (completionColor.b - output.b) * completion
  }
}

/** A one-shot animation clock: level() follows shape over duration, scaled by the value passed to start. */
class Envelope {
  private clock: number | undefined
  private scale = 1

  constructor(
    private duration: number,
    private shape: (progress: number) => number,
  ) {}

  start(scale = 1) {
    if (this.clock !== undefined) return
    this.clock = 0
    this.scale = scale
  }

  restart(scale = 1) {
    this.clock = 0
    this.scale = scale
  }

  stop() {
    this.clock = undefined
  }

  advance(delta: number) {
    if (this.clock === undefined) return
    this.clock += delta
    if (this.clock >= this.duration) this.clock = undefined
  }

  get active() {
    return this.clock !== undefined
  }

  level() {
    return this.clock === undefined ? 0 : this.scale * this.shape(this.clock / this.duration)
  }
}

type GateStage = {
  duration: number
  shape: (progress: number) => number
}

/**
 * A gated animation stage, in the synthesizer sense: trigger runs the attack shape and holds
 * sustain at 1; release fades out from whatever level the stage had at note-off. Sustain is
 * motionless, so only the attack and release phases count as animating.
 */
class GatedEnvelope {
  private phase: "idle" | "attack" | "sustain" | "release"
  private phaseClock = 0
  // Level captured at note-off; only meaningful while releasing.
  private releaseScale = 1

  constructor(
    private attackStage: GateStage,
    private releaseStage: GateStage,
    initial: "idle" | "sustain" = "idle",
  ) {
    this.phase = initial
  }

  /** Note-on: run the attack from silence and hold sustain. */
  trigger() {
    this.phase = "attack"
    this.phaseClock = 0
  }

  /** Note-off: fade out from the current level. */
  release() {
    if (this.phase === "idle") return
    this.releaseScale = this.level
    this.phase = "release"
    this.phaseClock = 0
  }

  /** Halt mid-motion without a fade, e.g. when animations are disabled. */
  settle(phase: "idle" | "sustain") {
    this.phase = phase
    this.phaseClock = 0
  }

  advance(delta: number) {
    if (this.phase === "idle" || this.phase === "sustain") return
    this.phaseClock += delta
    const duration = this.phase === "attack" ? this.attackStage.duration : this.releaseStage.duration
    if (this.phaseClock < duration) return
    this.phase = this.phase === "attack" ? "sustain" : "idle"
    this.phaseClock = 0
  }

  get level() {
    if (this.phase === "idle") return 0
    if (this.phase === "sustain") return 1
    if (this.phase === "attack") return this.attackStage.shape(this.phaseClock / this.attackStage.duration)
    return this.releaseScale * this.releaseStage.shape(this.phaseClock / this.releaseStage.duration)
  }

  get animating() {
    return this.phase === "attack" || this.phase === "release"
  }

  get idle() {
    return this.phase === "idle"
  }

  get releaseProgress() {
    return this.phase === "release" ? this.phaseClock / this.releaseStage.duration : undefined
  }

  get noteOffLevel() {
    return this.releaseScale
  }
}

type PulseStateOptions = {
  enabled: boolean
  active: boolean
  promptPulse: number
  complete: boolean
  glow: boolean
}

class PulseState {
  private enabled: boolean
  private active: boolean
  private promptPulse: number
  private complete: boolean
  private glow: boolean
  private completionPending = false
  private sweepClock = 0
  // Two gated voices: the running sweep and the unread glow. One-shots handle flash and completion.
  private runEnvelope = new GatedEnvelope(
    { duration: RUN_ATTACK, shape: smootherstep },
    { duration: RUN_FADE_OUT, shape: fadeOut },
  )
  private glowEnvelope: GatedEnvelope
  private completionPulse = new Envelope(COMPLETION_DURATION, completionPulseOpacity)
  private edgeFlash = new Envelope(EDGE_FLASH_DURATION, (progress) => attackDecay(progress, EDGE_FLASH_ATTACK, 1, 0))

  constructor(options: PulseStateOptions) {
    this.enabled = options.enabled
    this.active = options.active
    this.promptPulse = options.promptPulse
    this.complete = options.complete
    this.glow = options.glow
    // A glow that exists at mount holds sustain without an ignition flash, even when animations are off.
    this.glowEnvelope = new GatedEnvelope(
      { duration: GLOW_IGNITION_DURATION, shape: glowIgnitionLevel },
      { duration: GLOW_RELEASE_DURATION, shape: glowReleaseDrain },
      options.glow ? "sustain" : "idle",
    )
    if (this.enabled && this.active) this.runEnvelope.trigger()
  }

  get live() {
    return (
      this.enabled &&
      (this.active ||
        this.runEnvelope.animating ||
        this.glowEnvelope.animating ||
        this.completionPulse.active ||
        this.edgeFlash.active)
    )
  }

  get running() {
    return this.runEnvelope.level
  }

  get completion() {
    return this.completionPulse.level() * COMPLETION_OPACITY
  }

  get flash() {
    return this.edgeFlash.level() * EDGE_FLASH_OPACITY
  }

  /** The resting glow's amplitude: ignition attack, sustain, or the draining note-off residue. */
  get glowLevel() {
    return this.glowEnvelope.level
  }

  get glowReleaseProgress() {
    return this.glowEnvelope.releaseProgress
  }

  /** The diffusing swell's amplitude; it rides above the glow it released from, never below its resting level. */
  get glowReleaseSwell() {
    const progress = this.glowEnvelope.releaseProgress
    if (progress === undefined) return 0
    return glowReleaseSwell(progress) * Math.max(1, this.glowEnvelope.noteOffLevel)
  }

  setEnabled(value: boolean) {
    if (value === this.enabled) return false
    this.enabled = value
    if (!value) {
      this.runEnvelope.settle("idle")
      this.glowEnvelope.settle(this.glow ? "sustain" : "idle")
      this.completionPulse.stop()
      this.edgeFlash.stop()
      this.completionPending = false
    } else if (this.active) {
      // Re-enable resumes the sweep from its prior position, so no sweep clock reset here.
      this.runEnvelope.trigger()
    }
    return true
  }

  setActive(value: boolean) {
    if (value === this.active) return false
    this.active = value
    if (!this.enabled) return true
    if (value) {
      this.sweepClock = 0
      this.runEnvelope.trigger()
      this.completionPulse.stop()
      this.completionPending = false
    } else {
      this.runEnvelope.release()
      this.completionPending = true
    }
    this.edgeFlash.start()
    return true
  }

  setPromptPulse(value: number) {
    if (value === this.promptPulse) return false
    this.promptPulse = value
    if (this.enabled) this.edgeFlash.restart(PROMPT_FLASH_SCALE)
    return true
  }

  setComplete(value: boolean) {
    if (value === this.complete) return false
    this.complete = value
    if (!value) {
      this.completionPulse.stop()
      this.completionPending = false
    }
    if (value && this.completionPending) {
      this.completionPending = false
      if (this.enabled) this.completionPulse.start()
    }
    return true
  }

  setGlow(value: boolean) {
    if (value === this.glow) return false
    this.glow = value
    // Without animations the glow still holds statically; it just skips the ignition and release motion.
    if (!this.enabled) {
      this.glowEnvelope.settle(value ? "sustain" : "idle")
      return true
    }
    if (value) this.glowEnvelope.trigger()
    else this.glowEnvelope.release()
    return true
  }

  advance(deltaTime: number) {
    if (!this.live) return
    // The sweep keeps coasting from note-on through the release fade.
    if (!this.runEnvelope.idle) this.sweepClock += deltaTime
    this.runEnvelope.advance(deltaTime)
    this.glowEnvelope.advance(deltaTime)
    this.completionPulse.advance(deltaTime)
    this.edgeFlash.advance(deltaTime)
    if (!this.completionPending) return
    if (this.complete) {
      this.completionPending = false
      this.completionPulse.start()
      return
    }
    if (this.runEnvelope.releaseProgress === undefined) this.completionPending = false
  }

  // Scratch tuple reused across frames so the steady-state render allocates nothing.
  private sweepFronts: [number, number] = [0, 0]

  fronts(width: number) {
    const cycles = this.sweepClock / RUN_DURATION
    const progress = cycles % 1
    const start = -RUN_HEAD
    const end = width - 1 + RUN_TAIL
    const secondProgress = cycles < 0.5 ? 0 : (cycles + 0.5) % 1
    this.sweepFronts[0] = start + coast(progress) * (end - start)
    this.sweepFronts[1] = start + coast(secondProgress) * (end - start)
    return this.sweepFronts
  }
}

class TabPulseRenderable extends Renderable {
  private _enabled: boolean
  private inner: PulseState
  private outer: PulseState
  private _color: RGBA
  private _outerColor: RGBA
  private _glowColor: RGBA
  private _outerGlowColor: RGBA
  private _glowTail: number
  private _outerGlowTail: number
  private _edge: "above" | "below" | undefined
  private _flashColor: RGBA
  private _outerFlashColor: RGBA
  private _flashTail: number | undefined
  private _outerFlashTail: number | undefined
  private _completionColor: RGBA
  private _outerCompletionColor: RGBA
  private _backgroundColor: RGBA
  private renderColor = RGBA.fromInts(0, 0, 0)
  private outerRenderColor = RGBA.fromInts(0, 0, 0)
  private _onLevel: ((level: number) => void) | undefined
  private lastLevel = 0

  constructor(ctx: RenderContext, options: TabPulseOptions = {}) {
    const enabled = options.enabled ?? true
    const active = options.active ?? false
    const glow = options.glow ?? false
    const edge = options.edge
    const outerActive = options.outerActive ?? active
    const outerGlow = options.outerGlow ?? glow
    super(ctx, {
      ...options,
      height: 1,
      live: enabled && (active || (edge !== undefined && outerActive)),
    })
    this._enabled = enabled
    this.inner = new PulseState({
      enabled,
      active,
      promptPulse: options.promptPulse ?? 0,
      complete: options.complete ?? false,
      glow,
    })
    this.outer = new PulseState({
      enabled: enabled && edge !== undefined,
      active: outerActive,
      promptPulse: options.outerPromptPulse ?? options.promptPulse ?? 0,
      complete: options.outerComplete ?? options.complete ?? false,
      glow: outerGlow,
    })
    this._color = options.color ?? RGBA.defaultForeground()
    this._outerColor = options.outerColor ?? this._color
    this._glowColor = options.glowColor ?? this._color
    this._outerGlowColor = options.outerGlowColor ?? this._glowColor
    this._glowTail = options.glowTail ?? GLOW_TAIL
    this._outerGlowTail = options.outerGlowTail ?? this._glowTail
    this._edge = edge
    this._flashColor = options.flashColor ?? this._color
    this._outerFlashColor = options.outerFlashColor ?? options.flashColor ?? this._outerColor
    this._flashTail = options.flashTail
    this._outerFlashTail = options.outerFlashTail ?? options.flashTail
    this._completionColor = options.completionColor ?? this._color
    this._outerCompletionColor = options.outerCompletionColor ?? options.completionColor ?? this._outerColor
    this._backgroundColor = options.backgroundColor ?? RGBA.defaultBackground()
    this._onLevel = options.onLevel
  }

  set onLevel(value: ((level: number) => void) | undefined) {
    this._onLevel = value
  }

  private emitLevel(value: number) {
    if (!this._onLevel) return
    const quantized = Math.round(value * 32) / 32
    if (quantized === this.lastLevel) return
    this.lastLevel = quantized
    this._onLevel?.(quantized)
  }

  set enabled(value: boolean) {
    if (value === this._enabled) return
    this._enabled = value
    this.inner.setEnabled(value)
    this.outer.setEnabled(value && this._edge !== undefined)
    this.live = this.inner.live || this.outer.live
    this.requestRender()
  }

  set active(value: boolean) {
    if (this.inner.setActive(value)) this.changed()
  }

  set outerActive(value: boolean) {
    if (this.outer.setActive(value)) this.changed()
  }

  set promptPulse(value: number) {
    if (this.inner.setPromptPulse(value)) this.changed()
  }

  set outerPromptPulse(value: number) {
    if (this.outer.setPromptPulse(value)) this.changed()
  }

  set complete(value: boolean) {
    if (this.inner.setComplete(value)) this.changed()
  }

  set outerComplete(value: boolean) {
    if (this.outer.setComplete(value)) this.changed()
  }

  set glow(value: boolean) {
    if (this.inner.setGlow(value)) this.changed()
  }

  set outerGlow(value: boolean) {
    if (this.outer.setGlow(value)) this.changed()
  }

  private changed() {
    this.live = this.inner.live || this.outer.live
    this.requestRender()
  }

  set color(value: RGBA) {
    if (value.equals(this._color)) return
    this._color = value
    this.requestRender()
  }

  set glowColor(value: RGBA) {
    if (value.equals(this._glowColor)) return
    this._glowColor = value
    this.requestRender()
  }

  set outerColor(value: RGBA) {
    if (value.equals(this._outerColor)) return
    this._outerColor = value
    this.requestRender()
  }

  set outerGlowColor(value: RGBA) {
    if (value.equals(this._outerGlowColor)) return
    this._outerGlowColor = value
    this.requestRender()
  }

  set glowTail(value: number) {
    if (value === this._glowTail) return
    this._glowTail = value
    this.requestRender()
  }

  set outerGlowTail(value: number) {
    if (value === this._outerGlowTail) return
    this._outerGlowTail = value
    this.requestRender()
  }

  set edge(value: "above" | "below" | undefined) {
    if (value === this._edge) return
    this._edge = value
    this.outer.setEnabled(this._enabled && value !== undefined)
    this.live = this.inner.live || this.outer.live
    this.requestRender()
  }

  set flashColor(value: RGBA) {
    if (value.equals(this._flashColor)) return
    this._flashColor = value
    this.requestRender()
  }

  set outerFlashColor(value: RGBA) {
    if (value.equals(this._outerFlashColor)) return
    this._outerFlashColor = value
    this.requestRender()
  }

  set flashTail(value: number | undefined) {
    if (value === this._flashTail) return
    this._flashTail = value
    this.requestRender()
  }

  set outerFlashTail(value: number | undefined) {
    if (value === this._outerFlashTail) return
    this._outerFlashTail = value
    this.requestRender()
  }

  set completionColor(value: RGBA) {
    if (value.equals(this._completionColor)) return
    this._completionColor = value
    this.requestRender()
  }

  set outerCompletionColor(value: RGBA) {
    if (value.equals(this._outerCompletionColor)) return
    this._outerCompletionColor = value
    this.requestRender()
  }

  set backgroundColor(value: RGBA) {
    if (value.equals(this._backgroundColor)) return
    this._backgroundColor = value
    this.requestRender()
  }

  protected override onUpdate(deltaTime: number): void {
    if (!this.live) return
    this.inner.advance(deltaTime)
    this.outer.advance(deltaTime)
    this.live = this.inner.live || this.outer.live
  }

  protected override renderSelf(buffer: OptimizedBuffer): void {
    if (!this.visible || this.isDestroyed || this.width <= 0) return
    const running = this.inner.running
    const completion = this.inner.completion
    const flash = this.inner.flash
    const glowLevel = this.inner.glowLevel
    const releaseProgress = this.inner.glowReleaseProgress
    const outerRunning = this.outer.running
    const outerCompletion = this.outer.completion
    const outerFlash = this.outer.flash
    const outerGlowLevel = this.outer.glowLevel
    const outerReleaseProgress = this.outer.glowReleaseProgress
    if (
      glowLevel === 0 &&
      releaseProgress === undefined &&
      running === 0 &&
      completion === 0 &&
      flash === 0 &&
      outerGlowLevel === 0 &&
      outerReleaseProgress === undefined &&
      outerRunning === 0 &&
      outerCompletion === 0 &&
      outerFlash === 0
    ) {
      this.emitLevel(0)
      return
    }
    const fronts = running === 0 ? undefined : this.inner.fronts(this.width)
    const outerFronts = outerRunning === 0 ? undefined : this.outer.fronts(this.width)
    if (this._onLevel)
      this.emitLevel(
        running === 0
          ? 0
          : Math.max(intensityAt(1, fronts![0], RUN_HEAD, RUN_TAIL), intensityAt(1, fronts![1], RUN_HEAD, RUN_TAIL)) *
              running,
      )
    const glowTail = Math.min(this._glowTail, Math.max(1, this.width - 2))
    const outerGlowTail = Math.min(this._outerGlowTail, Math.max(1, this.width - 2))
    const releaseSwell = this.inner.glowReleaseSwell
    const releaseSpread = releaseSwell === 0 ? 0 : glowReleaseSpread(releaseProgress!, glowTail, this.width)
    const outerReleaseSwell = this.outer.glowReleaseSwell
    const outerReleaseSpread =
      outerReleaseSwell === 0 ? 0 : glowReleaseSpread(outerReleaseProgress!, outerGlowTail, this.width)
    const flashTail = this._flashTail === undefined ? undefined : Math.min(this._flashTail, Math.max(1, this.width - 2))
    const outerFlashTail =
      this._outerFlashTail === undefined ? undefined : Math.min(this._outerFlashTail, Math.max(1, this.width - 2))
    for (let index = 0; index < this.width; index++) {
      // Skip per-cell sweep and glow math when that stage is idle, e.g. a steady breathing glow.
      const sweep =
        running === 0
          ? 0
          : Math.max(
              intensityAt(index, fronts![0], RUN_HEAD, RUN_TAIL),
              intensityAt(index, fronts![1], RUN_HEAD, RUN_TAIL),
            ) *
            0.14 *
            running
      const outerSweep =
        outerRunning === 0
          ? 0
          : Math.max(
              intensityAt(index, outerFronts![0], RUN_HEAD, RUN_TAIL),
              intensityAt(index, outerFronts![1], RUN_HEAD, RUN_TAIL),
            ) *
            0.14 *
            outerRunning
      blendTabPulseColor(
        this.renderColor,
        this._backgroundColor,
        this._glowColor,
        this._color,
        this._flashColor,
        this._completionColor,
        Math.max(
          glowLevel === 0 ? 0 : glowIntensityAt(index, glowTail) * GLOW_OPACITY * glowLevel,
          releaseSwell === 0 ? 0 : glowIntensityAt(index, releaseSpread) * GLOW_OPACITY * releaseSwell,
        ),
        sweep,
        flashTail === undefined ? flash : flash * tabFlashIntensity(index, flashTail),
        completion,
      )
      if (!this._edge) {
        buffer.setCell(this.screenX + index, this.screenY, " ", DEFAULT_FOREGROUND, this.renderColor)
        continue
      }
      blendTabPulseColor(
        this.outerRenderColor,
        this._backgroundColor,
        this._outerGlowColor,
        this._outerColor,
        this._outerFlashColor,
        this._outerCompletionColor,
        Math.max(
          outerGlowLevel === 0 ? 0 : glowIntensityAt(index, outerGlowTail) * GLOW_OPACITY * outerGlowLevel,
          outerReleaseSwell === 0 ? 0 : glowIntensityAt(index, outerReleaseSpread) * GLOW_OPACITY * outerReleaseSwell,
        ),
        outerSweep,
        outerFlashTail === undefined ? outerFlash : outerFlash * tabFlashIntensity(index, outerFlashTail),
        outerCompletion,
      )
      buffer.setCell(
        this.screenX + index,
        this.screenY,
        this._edge === "above" ? "▄" : "▀",
        this.renderColor,
        this.outerRenderColor,
      )
    }
  }
}

declare module "@opentui/solid" {
  interface OpenTUIComponents {
    tab_pulse: typeof TabPulseRenderable
  }
}

extend({ tab_pulse: TabPulseRenderable })

export function TabPulse(props: {
  top?: number
  width?: number
  edge?: "above" | "below"
  enabled?: boolean
  active: boolean
  outerActive?: boolean
  promptPulse?: number
  outerPromptPulse?: number
  complete?: boolean
  outerComplete?: boolean
  glow?: boolean
  outerGlow?: boolean
  color: RGBA
  outerColor?: RGBA
  glowColor?: RGBA
  outerGlowColor?: RGBA
  glowTail?: number
  outerGlowTail?: number
  flashColor?: RGBA
  outerFlashColor?: RGBA
  flashTail?: number
  completionColor?: RGBA
  outerCompletionColor?: RGBA
  backgroundColor: RGBA
  onLevel?: (level: number) => void
}) {
  return (
    <tab_pulse
      position="absolute"
      top={props.top}
      edge={props.edge}
      zIndex={0}
      width={props.width ?? "100%"}
      enabled={props.enabled ?? true}
      active={props.active}
      outerActive={props.outerActive ?? props.active}
      promptPulse={props.promptPulse ?? 0}
      outerPromptPulse={props.outerPromptPulse ?? props.promptPulse ?? 0}
      complete={props.complete ?? false}
      outerComplete={props.outerComplete ?? props.complete ?? false}
      glow={props.glow ?? false}
      outerGlow={props.outerGlow ?? props.glow ?? false}
      color={props.color}
      outerColor={props.outerColor ?? props.color}
      glowColor={props.glowColor ?? props.color}
      outerGlowColor={props.outerGlowColor ?? props.glowColor ?? props.color}
      glowTail={props.glowTail ?? GLOW_TAIL}
      outerGlowTail={props.outerGlowTail ?? props.glowTail ?? GLOW_TAIL}
      flashColor={props.flashColor ?? props.color}
      outerFlashColor={props.outerFlashColor ?? props.flashColor ?? props.outerColor ?? props.color}
      flashTail={props.flashTail}
      outerFlashTail={props.flashTail}
      completionColor={props.completionColor ?? props.color}
      outerCompletionColor={props.outerCompletionColor ?? props.completionColor ?? props.outerColor ?? props.color}
      backgroundColor={props.backgroundColor}
      onLevel={props.onLevel}
    />
  )
}

import { EmbeddedTerminalRenderable, type RGBA } from "@opentui/core"
import { rgbToOklch, type ResolvedThemeTokens } from "@opencode/theme/tui"
import { extend, useRenderer } from "@opentui/solid"
import { createEffect, createSignal, onCleanup, onMount, Show } from "solid-js"
import { useClient } from "../context/client"
import { Keymap } from "../context/keymap"
import { useTheme, useThemes } from "../context/theme"
import { errorMessage } from "../util/error"

declare module "@opentui/solid" {
  interface OpenTUIComponents {
    embeddedTerminal: typeof EmbeddedTerminalRenderable
  }
}

extend({ embeddedTerminal: EmbeddedTerminalRenderable })

type TerminalSize = { cols: number; rows: number }
type StreamItem =
  | { type: "output"; data: Uint8Array }
  | { type: "resize"; size: TerminalSize; checkpoint?: Uint8Array }
  | { type: "ready" }

export function TerminalPane(props: {
  ptyID: string
  resizing?: boolean
  autoFocus?: boolean
  onAutoFocus?: () => void
  onFocusRequest?: (focus: (() => void) | undefined) => void
  onDisconnect?: () => void
}) {
  const client = useClient()
  const keymap = Keymap.use()
  const leader = Keymap.useLeaderActive()
  const theme = useTheme()
  const themes = useThemes()
  const renderer = useRenderer()
  const [failure, setFailure] = createSignal<string>()
  const attachmentID = crypto.randomUUID()
  const stream: StreamItem[] = []
  const pendingInput: Uint8Array[] = []
  let terminal: EmbeddedTerminalRenderable | undefined
  let socket: WebSocket | undefined
  let attached = false
  let controller = false
  let restored = false
  let wantsControl = false
  let disposed = false
  let exited = false
  let size: TerminalSize | undefined
  let canonicalSize: TerminalSize | undefined
  let terminalSize: TerminalSize | undefined
  let lastIntermediateRender = 0
  let terminalTheme: Uint8Array | undefined
  let waitingSize: { size: TerminalSize; resolve: () => void } | undefined

  const setCanonicalSize = (value: TerminalSize) => {
    canonicalSize = value
    if (!terminal) return
    terminal.width = value.cols
    terminal.height = value.rows
  }

  const applyTerminalTheme = () => {
    if (terminalTheme) terminal?.write(terminalTheme)
  }

  const send = (data: Uint8Array) => {
    if (attached && socket?.readyState === WebSocket.OPEN) socket.send(data)
  }

  const interact = () => {
    if (!restored) {
      wantsControl = true
      return
    }
    if (!size) return
    send(interactionFrame(size))
  }

  createEffect(() => {
    if (props.resizing) interact()
  })

  const sendInput = (data: Uint8Array) => {
    if (!restored) {
      pendingInput.push(data)
      return
    }
    if (size) send(interactionFrame(size, data))
  }

  const processStream = () => {
    if (disposed || !terminal || !sameSize(canonicalSize, terminalSize)) return
    while (stream.length > 0) {
      const item = stream[0]!
      if (item.type === "output") {
        stream.shift()
        const output = [item.data]
        while (true) {
          const next = stream[0]
          if (!next || next.type !== "output") break
          output.push(next.data)
          stream.shift()
        }
        terminal.write(output.length === 1 ? output[0] : Buffer.concat(output))
        continue
      }
      if (item.type === "resize") {
        setCanonicalSize(item.size)
        if (!sameSize(canonicalSize, terminalSize)) return
        stream.shift()
        if (item.checkpoint) {
          terminal.write(Buffer.concat([Buffer.from("\x1bc"), Buffer.from(item.checkpoint)]))
          applyTerminalTheme()
        }
        continue
      }
      stream.shift()
      restored = true
      const input = pendingInput.splice(0)
      if (input.length > 0) input.forEach(sendInput)
      if (input.length === 0 && (controller || wantsControl)) interact()
      wantsControl = false
    }
  }

  const enqueue = (item: StreamItem) => {
    stream.push(item)
    processStream()
  }

  const waitForTerminalSize = (value: TerminalSize) => {
    if (sameSize(value, terminalSize)) return Promise.resolve()
    return new Promise<void>((resolve) => {
      waitingSize = { size: value, resolve }
    })
  }

  const offKeys = keymap.intercept(
    "key",
    ({ event }) => {
      if (!terminal?.focused) return
      if (keymap.isLeader(event) || leader()) return
      event.preventDefault()
      event.stopPropagation()
      terminal.handleKeyPress(event)
    },
    { priority: 100 },
  )
  createEffect(() => {
    if (!props.autoFocus || !terminal) return
    terminal.focus()
    props.onAutoFocus?.()
  })

  createEffect(() => {
    const tokens = themes.currentTokens()
    terminalTheme = terminalPalette(tokens, themes.mode(), tokens.background.raised.base)
    applyTerminalTheme()
  })

  onMount(() => {
    void connect().catch((error) => setFailure(errorMessage(error)))
  })

  onCleanup(() => {
    disposed = true
    waitingSize?.resolve()
    socket?.close()
    offKeys()
    props.onFocusRequest?.(undefined)
  })

  async function connect() {
    const snapshot = await client.api.experimental.persistentPty.snapshot({ ptyID: props.ptyID })
    if (disposed) return
    setCanonicalSize(snapshot.info.size)
    await waitForTerminalSize(snapshot.info.size)
    if (disposed) return
    terminal?.write(Buffer.from(snapshot.checkpoint, "base64"))
    applyTerminalTheme()
    const next = await client.persistentPty.connect({
      ptyID: props.ptyID,
      cursor: snapshot.info.output.tail,
      attachmentID,
      takeover: true,
    })
    if (disposed) {
      next.close()
      return
    }
    next.addEventListener("message", (event) => {
      if (disposed) return
      if (event.data instanceof ArrayBuffer) {
        enqueue({ type: "output", data: new Uint8Array(event.data) })
        const now = performance.now()
        if (now - lastIntermediateRender >= 16) {
          lastIntermediateRender = now
          renderer.intermediateRender()
        }
        return
      }
      if (typeof event.data !== "string") return
      const message: unknown = JSON.parse(event.data)
      if (!message || typeof message !== "object" || !("type" in message)) return
      if (message.type === "exited") {
        exited = true
        return
      }
      if (
        message.type === "resized" &&
        "cols" in message &&
        typeof message.cols === "number" &&
        "rows" in message &&
        typeof message.rows === "number" &&
        "checkpoint" in message &&
        typeof message.checkpoint === "string"
      ) {
        enqueue({
          type: "resize",
          size: { cols: message.cols, rows: message.rows },
          checkpoint: Buffer.from(message.checkpoint, "base64"),
        })
        return
      }
      if (message.type === "replay_complete") {
        enqueue({ type: "ready" })
        return
      }
      if (
        message.type === "controller_changed" &&
        "attachmentID" in message &&
        (typeof message.attachmentID === "string" || message.attachmentID === undefined)
      ) {
        const previous = controller
        controller = message.attachmentID === attachmentID
        if (controller && !previous && restored) interact()
        return
      }
      if (message.type !== "attached") return
      if (!("inputProtocol" in message) || message.inputProtocol !== 1) {
        setFailure("Persistent terminal server is out of date; restart OpenCode")
        next.close()
        return
      }
      if (
        "info" in message &&
        message.info &&
        typeof message.info === "object" &&
        "size" in message.info &&
        message.info.size &&
        typeof message.info.size === "object" &&
        "cols" in message.info.size &&
        typeof message.info.size.cols === "number" &&
        "rows" in message.info.size &&
        typeof message.info.size.rows === "number"
      )
        enqueue({ type: "resize", size: { cols: message.info.size.cols, rows: message.info.size.rows } })
      controller = "role" in message && message.role === "controller"
      attached = true
    })
    next.addEventListener("error", () => {
      if (disposed) return
      const focused = terminal?.focused
      terminal = undefined
      setFailure("Terminal connection failed")
      if (focused) props.onDisconnect?.()
    })
    next.addEventListener("close", () => {
      if (disposed) return
      const focused = terminal?.focused
      terminal = undefined
      // The removal event arrives separately; keep the terminal visible until then.
      if (!exited) setFailure("Terminal disconnected")
      if (focused) props.onDisconnect?.()
    })
    socket = next
  }

  return (
    <box
      flexGrow={1}
      minWidth={0}
      minHeight={0}
      overflow="hidden"
      backgroundColor={themes.currentTokens().background.raised.base}
      onSizeChange={function () {
        size = { cols: Math.max(1, this.width - 2), rows: this.height }
        if (controller && restored) interact()
      }}
      // TODO: Revisit when embedded terminal mouse handlers can compose without replacing its internal focus handler.
      onMouseDown={() => interact()}
    >
      <Show when={!failure()} fallback={<text fg={theme.text.feedback.error.base}>{failure()}</text>}>
        <>
          <embeddedTerminal
            transparentBackground={themes.currentTokens().background.raised.base.a === 0}
            ref={(value) => {
              terminal = value
              props.onFocusRequest?.(() => {
                value.focus()
                interact()
              })
              terminalSize = { cols: 80, rows: 24 }
              if (canonicalSize) {
                value.width = canonicalSize.cols
                value.height = canonicalSize.rows
              }
              applyTerminalTheme()
            }}
            position="absolute"
            left={1}
            top={0}
            width={80}
            height={24}
            onData={(data, source) => {
              if (source === "input") sendInput(data)
            }}
            onTerminalResize={(cols, rows) => {
              terminalSize = { cols, rows }
              if (waitingSize && sameSize(waitingSize.size, terminalSize)) {
                waitingSize.resolve()
                waitingSize = undefined
              }
              processStream()
            }}
          />
        </>
      </Show>
    </box>
  )
}

function sameSize(first: TerminalSize | undefined, second: TerminalSize | undefined) {
  return !!first && !!second && first.cols === second.cols && first.rows === second.rows
}

export function terminalPalette(theme: ResolvedThemeTokens, mode: "light" | "dark", background: RGBA) {
  const black = theme.hue.neutral[mode === "dark" ? 800 : 200]
  const white = theme.hue.neutral[mode === "dark" ? 200 : 800]
  const brightWhite = theme.hue.neutral[mode === "dark" ? 100 : 900]
  const blue = terminalHue(theme, rgbToOklch(0, 0, 1).h)
  const magenta = terminalHue(theme, rgbToOklch(1, 0, 1).h)
  const normal = [
    theme.text.feedback.error.base,
    theme.text.feedback.success.base,
    theme.text.feedback.warning.base,
    blue,
    magenta,
    theme.text.feedback.info.base,
    white,
  ]
  const colors = [
    black,
    ...normal,
    theme.text.muted,
    ...normal.slice(0, -1).map((color) => theme.decrease(color)),
    brightWhite,
  ]
  return Buffer.from(
    colors
      .map((color, index) => `\x1b]4;${index};${hex(color)}\x1b\\`)
      .concat(`\x1b]10;${hex(theme.text.base)}\x1b\\`, `\x1b]11;${hex(background)}\x1b\\`)
      .join(""),
  )
}

function terminalHue(theme: ResolvedThemeTokens, target: number) {
  const nearest = Object.values(theme.hue)
    .map((scale) => {
      const color = scale[200]
      const [red, green, blue, alpha] = color.toInts()
      const converted = rgbToOklch(red / 255, green / 255, blue / 255)
      return { color, alpha, chroma: converted.c, distance: hueDistance(converted.h, target) }
    })
    .filter((item) => item.alpha > 0 && item.chroma >= 0.03)
    .sort((first, second) => first.distance - second.distance)[0]
  if (!nearest || nearest.distance > 30) return theme.hue.accent[200]
  return nearest.color
}

function hueDistance(first: number, second: number) {
  const difference = Math.abs(first - second)
  return Math.min(difference, 360 - difference)
}

function hex(color: RGBA) {
  return `#${color
    .toInts()
    .slice(0, 3)
    .map((value) => value.toString(16).padStart(2, "0"))
    .join("")}`
}

function interactionFrame(size: { cols: number; rows: number }, data?: Uint8Array) {
  const frame = new Uint8Array(5 + (data?.byteLength ?? 0))
  const view = new DataView(frame.buffer)
  frame[0] = data ? 1 : 0
  view.setUint16(1, size.cols)
  view.setUint16(3, size.rows)
  if (data) frame.set(data, 5)
  return frame
}

import { onCleanup } from "solid-js"
import { useThemes } from "../context/theme"
import { useToast } from "../ui/toast"

export function ThemeErrorToast() {
  const themes = useThemes()
  const toast = useToast()

  onCleanup(
    themes.onError(({ name, error }) =>
      toast.show({
        variant: "error",
        title: `Failed to load theme: ${name}`,
        message: error.message,
      }),
    ),
  )

  return null
}

import {
  BoxRenderable,
  OptimizedBuffer,
  RGBA,
  TargetChannel,
  TextRenderable,
  type RenderContext,
  type TextOptions,
} from "@opentui/core"
import { extend } from "@opentui/solid"
import { coast, intensityAt, smootherstep } from "./tab-pulse"

type TitleShimmerOptions = TextOptions & {
  rename?: { title: string; pending: boolean }
  enabled?: boolean
  backdrop?: RGBA
}

const SHIMMER_DURATION = 1200
const SHIMMER_FADE = 240
const ARRIVAL_DURATION = 450
const WIPE_FEATHER = 4
const TRANSPARENT = RGBA.fromValues(0, 0, 0, 0)
// Native text draws wide glyphs as a head followed by flagged continuation cells.
const CONTINUATION = 0xc0000000 | 0

export class TitleShimmerRenderable extends TextRenderable {
  private _rename: TitleShimmerOptions["rename"]
  private _enabled: boolean
  private _backdrop: RGBA
  private pendingTitle: string | undefined
  private elapsed = 0
  private blend = 0
  private fresh = true
  private arrival: number | undefined
  private scratch: OptimizedBuffer | undefined
  private previous: OptimizedBuffer | undefined
  private mask = new Float32Array(0)
  private matrix = new Float32Array(16)

  constructor(ctx: RenderContext, options: TitleShimmerOptions) {
    super(ctx, options)
    this._rename = options.rename
    this.pendingTitle = options.rename?.title
    this._enabled = options.enabled ?? true
    this._backdrop = options.backdrop ?? RGBA.defaultBackground()
    this.matrix[15] = 1
    this.updateBackdrop()
    this.live = this.animating
  }

  private get animating() {
    return this._enabled && (this.shimmering || this.arrival !== undefined || this.blend > 0)
  }

  private get shimmering() {
    return this._rename?.pending && this._rename.title === this.pendingTitle
  }

  set rename(value: TitleShimmerOptions["rename"]) {
    if (value?.title === this._rename?.title && value?.pending === this._rename?.pending) return
    if (value?.pending && !this._rename?.pending) {
      if (this.pendingTitle !== value.title) this.blend = 0
      this.pendingTitle = value.title
      if (this.blend === 0) this.elapsed = 0
      this.arrival = undefined
      this.previous?.destroy()
      this.previous = undefined
    }
    // Only an automatic rename replaces the last painted title with a wipe.
    if (value?.title !== this._rename?.title) {
      this.arrival = value && this._rename?.pending && this._enabled && this.previous ? 0 : undefined
      if (this.arrival === undefined) this.blend = 0
    }
    this._rename = value
    this.changed()
  }

  set enabled(value: boolean) {
    if (value === this._enabled) return
    this._enabled = value
    if (!value) {
      this.arrival = undefined
      this.blend = 0
    }
    this.changed()
  }

  set backdrop(value: RGBA) {
    if (value.equals(this._backdrop)) return
    this._backdrop = value
    this.updateBackdrop()
    this.requestRender()
  }

  private updateBackdrop() {
    this.matrix[3] = this._backdrop.r
    this.matrix[7] = this._backdrop.g
    this.matrix[11] = this._backdrop.b
  }

  private changed() {
    if (!this.live && this.animating) this.fresh = true
    this.live = this.animating
    if (!this.animating) {
      this.previous?.destroy()
      this.previous = undefined
    }
    this.requestRender()
  }

  override render(buffer: OptimizedBuffer, deltaTime: number) {
    if (!this.visible || this.isDestroyed || !Number.isFinite(this.width) || this.width <= 0 || this.height <= 0) return
    if (!this.animating) return super.render(buffer, deltaTime)
    // A newly live title must not inherit time spent idle before its fade started.
    const delta = this.fresh ? 0 : deltaTime
    this.fresh = false
    this.elapsed = (this.elapsed + delta) % SHIMMER_DURATION
    if (this.arrival !== undefined) {
      this.arrival += delta
      if (this.arrival >= ARRIVAL_DURATION) {
        this.arrival = undefined
        this.blend = 0
      }
    }
    this.blend = Math.max(
      0,
      Math.min(1, this.blend + (this.shimmering || this.arrival !== undefined ? delta : -delta) / SHIMMER_FADE),
    )
    this.live = this.animating
    if (!this.animating) {
      this.previous?.destroy()
      this.previous = undefined
      return super.render(buffer, deltaTime)
    }
    if (!this.scratch)
      this.scratch = OptimizedBuffer.create(this.width, this.height, this._ctx.widthMethod, { respectAlpha: true })
    if (this.scratch.width !== this.width || this.scratch.height !== this.height)
      this.scratch.resize(this.width, this.height)

    // Shade locally, then composite: colorMatrix itself does not respect ancestor scissors.
    this.scratch.clear(TRANSPARENT)
    // OpenTUI's framebuffer compositor can paint a cut wide glyph. Clip the native text draw first.
    const clip = {
      left: Math.max(0, -this.screenX),
      top: Math.max(0, -this.screenY),
      right: Math.min(this.width, buffer.width - this.screenX),
      bottom: Math.min(this.height, buffer.height - this.screenY),
    }
    for (let parent = this.parent; parent; parent = parent.parent) {
      if (parent.overflow === "visible" || parent.width <= 0 || parent.height <= 0) continue
      const border = parent instanceof BoxRenderable ? parent.border : false
      const left = Number(border === true || (Array.isArray(border) && border.includes("left")))
      const top = Number(border === true || (Array.isArray(border) && border.includes("top")))
      clip.left = Math.max(clip.left, parent.screenX - this.screenX + left)
      clip.top = Math.max(clip.top, parent.screenY - this.screenY + top)
      clip.right = Math.min(
        clip.right,
        parent.screenX -
          this.screenX +
          parent.width -
          Number(border === true || (Array.isArray(border) && border.includes("right"))),
      )
      clip.bottom = Math.min(
        clip.bottom,
        parent.screenY -
          this.screenY +
          parent.height -
          Number(border === true || (Array.isArray(border) && border.includes("bottom"))),
      )
    }
    this.scratch.pushScissorRect(
      clip.left,
      clip.top,
      Math.max(0, clip.right - clip.left),
      Math.max(0, clip.bottom - clip.top),
    )
    this.scratch.drawTextBuffer(this.textBufferView, 0, 0)
    const characters = this.scratch.buffers.char
    let end = 0
    for (let row = 0; row < this.height; row++) {
      let column = this.width
      while (
        column > 0 &&
        (characters[row * this.width + column - 1] === 32 || characters[row * this.width + column - 1] === 0)
      )
        column--
      end = Math.max(end, column)
    }
    const wipeFront =
      this.arrival !== undefined && this.previous
        ? -WIPE_FEATHER +
          coast(this.arrival / ARRIVAL_DURATION) * (Math.max(end, this.previous.width) + WIPE_FEATHER * 2)
        : undefined
    const cut = Math.max(0, Math.min(this.width, Math.round(wipeFront ?? 0)))
    if (wipeFront !== undefined && this.previous) {
      this.scratch.clear(TRANSPARENT)
      this.scratch.pushScissorRect(0, 0, cut, this.height)
      this.scratch.drawTextBuffer(this.textBufferView, 0, 0)
      this.scratch.popScissorRect()
      // Snapshot slices must also end on whole glyphs; framebuffer clipping alone can split them.
      for (let row = 0; row < Math.min(this.height, this.previous.height); row++) {
        let left = Math.max(cut, clip.left)
        let right = Math.min(this.previous.width, clip.right)
        const offset = row * this.previous.width
        while (left < right && (this.previous.buffers.char[offset + left] & CONTINUATION) === CONTINUATION) left++
        while (
          right > left &&
          right < this.previous.width &&
          (this.previous.buffers.char[offset + right] & CONTINUATION) === CONTINUATION
        )
          right--
        if (right > left) this.scratch.drawFrameBuffer(left, row, this.previous, left, row, right - left, 1)
      }
    }
    this.scratch.clearScissorRects()
    if (this.mask.length !== this.width * this.height * 3) this.mask = new Float32Array(this.width * this.height * 3)
    if (wipeFront === undefined) {
      if (!this.previous)
        this.previous = OptimizedBuffer.create(Math.max(1, end), this.height, this._ctx.widthMethod, {
          respectAlpha: true,
        })
      if (this.previous.width !== Math.max(1, end) || this.previous.height !== this.height)
        this.previous.resize(Math.max(1, end), this.height)
      this.previous.clear(TRANSPARENT)
      this.previous.drawFrameBuffer(0, 0, this.scratch)
    }
    const front = -4 + coast(this.elapsed / SHIMMER_DURATION) * ((this.previous?.width ?? end) + 4 + 18)
    const level = smootherstep(this.blend)
    let strength = 0
    for (let cell = 0; cell < characters.length; cell++) {
      const column = cell % this.width
      if ((characters[cell] & CONTINUATION) !== CONTINUATION) {
        const old = wipeFront === undefined || column >= cut
        let visibility = old ? 1 - 0.6 * level * (1 - intensityAt(column, front, 4, 18)) : 1
        if (wipeFront !== undefined) {
          let width = 1
          while (column + width < this.width && (characters[cell + width] & CONTINUATION) === CONTINUATION) width++
          const distance = old ? column - wipeFront : wipeFront - (column + width)
          visibility *= smootherstep(Math.max(0, Math.min(1, distance / WIPE_FEATHER)))
        }
        strength = 1 - visibility
      }
      this.mask[cell * 3] = column
      this.mask[cell * 3 + 1] = Math.floor(cell / this.width)
      this.mask[cell * 3 + 2] = strength
    }
    this.scratch.colorMatrix(this.matrix, this.mask, 1, TargetChannel.FG)
    buffer.drawFrameBuffer(this.screenX, this.screenY, this.scratch)
    this.markClean()
    this._ctx.addToHitGrid(this.screenX, this.screenY, this.width, this.height, this.num)
  }

  override destroy() {
    this.previous?.destroy()
    this.previous = undefined
    this.scratch?.destroy()
    this.scratch = undefined
    super.destroy()
  }
}

