import { createStore, reconcile } from "solid-js/store"
import type { LocationRef } from "@opencode/client"
import { createSimpleContext } from "./helper"
import type { PromptInfo } from "../prompt/history"
import { useTuiStartup } from "./runtime"

export type HomeRoute = {
  type: "home"
  prompt?: PromptInfo
  // Location carried over from the previous session or project picker so a new session lands there.
  location?: LocationRef
}

export type SessionRoute = {
  type: "session"
  sessionID: string
  prompt?: PromptInfo
}

export type PluginRoute = {
  type: "plugin"
  id: string
  name: string
  data?: Record<string, unknown>
}

export type Route = HomeRoute | SessionRoute | PluginRoute

export const { use: useRoute, provider: RouteProvider } = createSimpleContext({
  name: "Route",
  init: (props: { initialRoute?: Route }) => {
    const startup = useTuiStartup()
    const [store, setStore] = createStore<Route>(
      props.initialRoute ?? initialRoute(startup.initialRoute) ?? { type: "home" },
    )

    return {
      get data() {
        return store
      },
      navigate(route: Route) {
        setStore(reconcile(route))
      },
    }
  },
})

function initialRoute(value: unknown): Route | undefined {
  if (!value || typeof value !== "object" || !("type" in value)) return
  if (value.type === "home") return { type: "home" }
  if (value.type === "session" && "sessionID" in value && typeof value.sessionID === "string") {
    return { type: "session", sessionID: value.sessionID }
  }
  if (
    value.type === "plugin" &&
    "id" in value &&
    typeof value.id === "string" &&
    "name" in value &&
    typeof value.name === "string"
  ) {
    const data =
      "data" in value && typeof value.data === "object" && value.data !== null && !Array.isArray(value.data)
        ? (value.data as Record<string, unknown>)
        : undefined
    if (data) return { type: "plugin", id: value.id, name: value.name, data }
    return { type: "plugin", id: value.id, name: value.name }
  }
}

export function useRouteData<T extends Route["type"]>(type: T) {
  const route = useRoute()
  return route.data as Extract<Route, { type: typeof type }>
}

import { createComponent, createContext, type JSX, useContext } from "solid-js"

export type TuiHighlight = Readonly<{
  title: string
  body: string
}>

export type TuiApp = Readonly<{
  name: string
  version: string
  channel: string
  /** The current release's highlights, embedded only in stable release builds. */
  highlights?: ReadonlyArray<TuiHighlight>
}>

export type TuiPaths = Readonly<{
  cwd: string
  home: string
  state: string
  worktree: string
}>

export type TuiTerminalEnvironment = Readonly<{
  platform: string
  variables?: Readonly<Record<string, string>>
}>

export type TuiStartup = Readonly<{
  initialRoute?: unknown
  skipInitialLoading: boolean
}>

export type TuiLifecycle = Readonly<{
  add(finalizer: () => Promise<void>): () => void
}>

const PathsContext = createContext<TuiPaths>()
const AppContext = createContext<TuiApp>()
const TerminalEnvironmentContext = createContext<TuiTerminalEnvironment>()
const StartupContext = createContext<TuiStartup>()
const LifecycleContext = createContext<TuiLifecycle>()

function provider<T>(context: ReturnType<typeof createContext<T>>, value: T, children: () => JSX.Element) {
  return createComponent(context.Provider, {
    value: Object.freeze({ ...value }),
    get children() {
      return children()
    },
  })
}

export function TuiPathsProvider(props: { value: TuiPaths; children: JSX.Element }) {
  return provider(PathsContext, props.value, () => props.children)
}

export function TuiAppProvider(props: { value: TuiApp; children: JSX.Element }) {
  return provider(AppContext, props.value, () => props.children)
}

export function TuiTerminalEnvironmentProvider(props: { value: TuiTerminalEnvironment; children: JSX.Element }) {
  return provider(TerminalEnvironmentContext, props.value, () => props.children)
}

export function TuiStartupProvider(props: { value: TuiStartup; children: JSX.Element }) {
  return provider(StartupContext, props.value, () => props.children)
}

export function TuiLifecycleProvider(props: { value: TuiLifecycle; children: JSX.Element }) {
  return provider(LifecycleContext, props.value, () => props.children)
}

function required<T>(context: ReturnType<typeof createContext<T>>, name: string) {
  const value = useContext(context)
  if (!value) throw new Error(`${name} is missing`)
  return value
}

export function useTuiPaths() {
  return required(PathsContext, "TuiPathsProvider")
}

export function useTuiApp() {
  return required(AppContext, "TuiAppProvider")
}

export function useTuiTerminalEnvironment() {
  return required(TerminalEnvironmentContext, "TuiTerminalEnvironmentProvider")
}

export function useTuiStartup() {
  return required(StartupContext, "TuiStartupProvider")
}

export function useTuiLifecycle() {
  return required(LifecycleContext, "TuiLifecycleProvider")
}

import { createEffect, untrack, type Accessor } from "solid-js"
import type { Data } from "@opencode/client/solid"

export function createSessionRetention(input: {
  session: Pick<Data["session"], "list" | "root" | "evict">
  current: Accessor<string | undefined>
  keep: Accessor<readonly string[]>
  limit: number
}) {
  let previous: string | undefined
  let recent: string[] = []
  let evicted = new Map<string, string>()

  createEffect(() => {
    const viewed = input.current()
    const current = viewed === undefined ? undefined : input.session.root(viewed)
    const keep = new Set(input.keep().map((id) => input.session.root(id)))
    // Resolve again when metadata arrives, but only navigation advances recency.
    recent = [
      ...new Set([
        ...(viewed !== previous && current !== undefined ? [current] : []),
        ...recent.map((id) => input.session.root(id)),
      ]),
    ]
    previous = viewed
    const retained = new Set([...keep, ...recent.filter((id) => !keep.has(id)).slice(0, input.limit)])
    if (current !== undefined) retained.add(current)
    recent = recent.filter((id) => retained.has(id))

    const excluded = new Map(
      input.session.list().flatMap((session) => {
        const root = input.session.root(session.id)
        return retained.has(root) ? [] : [[session.id, root] as const]
      }),
    )
    // New descendants need eviction even when their root was already evicted.
    const roots = new Set([...excluded].filter(([id, root]) => evicted.get(id) !== root).map(([, root]) => root))
    evicted = excluded
    untrack(() => roots.forEach((root) => input.session.evict(root)))
  })
}

export type SessionTab = {
  sessionID: string
  title?: string
}

export type SessionTabUnread = "activity" | "error"

export const NEW_SESSION_TAB_TITLE = "New session"

export function sessionTabNumberLabel(index: number) {
  return String(index + 1)
}

export function sessionTabDetail(
  project: string,
  current: string | undefined,
  defaultBranch: string | undefined,
  worktree: boolean,
) {
  const branch = worktree && current !== defaultBranch ? current : undefined
  return branch && project ? `${project} ⎇ ${branch}` : (branch ?? project)
}

export type SessionTabHistory = {
  entries: readonly string[]
  index: number
}

export function sessionTabComplete(unread: SessionTabUnread | undefined, busy: boolean) {
  return unread === "activity" && !busy
}

export const SESSION_TAB_WIDTH = 22
export const SESSION_TAB_MAX_WIDTH = 32
export const SESSION_TAB_MIN_WIDTH = 8
// Overflow markers reserve one gap cell beside the arrow and count, e.g. "‹12 " and " 12›".
export const sessionTabOverflowWidth = (count: number) => String(count).length + 2

export function openSessionTab(tabs: SessionTab[], tab: SessionTab): SessionTab[] {
  const index = tabs.findIndex((item) => item.sessionID === tab.sessionID)
  if (index === -1) return [...tabs, tab]
  if (!tab.title || tabs[index]?.title === tab.title) return tabs
  return tabs.map((item, position) => (position === index ? { ...item, title: tab.title } : item))
}

export function closeSessionTab(tabs: SessionTab[], sessionID: string) {
  const index = tabs.findIndex((tab) => tab.sessionID === sessionID)
  // Like openSessionTab and moveSessionTab, a no-op returns the same reference so callers can
  // detect it by identity.
  if (index === -1) return { tabs, next: undefined }
  return {
    tabs: tabs.filter((tab) => tab.sessionID !== sessionID),
    next: tabs[index + 1]?.sessionID ?? tabs[index - 1]?.sessionID,
  }
}

export type ClosedSessionTab = {
  tab: SessionTab
  index: number
}

const CLOSED_SESSION_TAB_LIMIT = 25

export function recordClosedSessionTab(
  stack: readonly ClosedSessionTab[],
  tab: SessionTab,
  index: number,
): ClosedSessionTab[] {
  return [...stack.filter((entry) => entry.tab.sessionID !== tab.sessionID), { tab, index }].slice(
    -CLOSED_SESSION_TAB_LIMIT,
  )
}

/**
 * Pop the most recently closed tab that is not already open and restore it at its original
 * position. Entries for already-open sessions are consumed so repeated reopens walk the stack.
 * Selecting a session removes only its entry, preserving the rest of the closed history.
 */
export function reopenSessionTab(stack: readonly ClosedSessionTab[], tabs: readonly SessionTab[], sessionID?: string) {
  const remaining = [...stack]
  while (remaining.length > 0) {
    const index = sessionID ? remaining.findIndex((entry) => entry.tab.sessionID === sessionID) : remaining.length - 1
    if (index === -1) break
    const [entry] = remaining.splice(index, 1)
    if (tabs.some((tab) => tab.sessionID === entry.tab.sessionID)) continue
    const next = [...tabs]
    next.splice(Math.min(entry.index, tabs.length), 0, entry.tab)
    return { stack: remaining, tabs: next, sessionID: entry.tab.sessionID }
  }
  return { stack: remaining, tabs: undefined, sessionID: undefined }
}

export function moveSessionTab(tabs: SessionTab[], sessionID: string, index: number): SessionTab[] {
  const from = tabs.findIndex((tab) => tab.sessionID === sessionID)
  const to = Math.max(0, Math.min(tabs.length - 1, index))
  if (from === -1 || from === to) return tabs
  const next = tabs.filter((tab) => tab.sessionID !== sessionID)
  next.splice(to, 0, tabs[from])
  return next
}

export function cycleSessionTab(
  tabs: readonly SessionTab[],
  active: string | undefined,
  direction: 1 | -1,
  matches: (tab: SessionTab) => boolean = () => true,
) {
  if (tabs.length === 0) return
  const index = tabs.findIndex((tab) => tab.sessionID === active)
  const start = index === -1 ? (direction === 1 ? -1 : 0) : index
  return Array.from(
    { length: tabs.length },
    (_, offset) => tabs[(start + direction * (offset + 1) + tabs.length * 2) % tabs.length],
  ).find(matches)
}

// In-memory navigation history is bounded so a long-lived TUI does not accumulate one entry per
// session switch forever; the oldest entries fall off first.
const SESSION_TAB_HISTORY_LIMIT = 100

export function recordSessionTabHistory(history: SessionTabHistory, sessionID: string): SessionTabHistory {
  if (history.entries[history.index] === sessionID) return history
  const entries = [...history.entries.slice(0, history.index + 1), sessionID].slice(-SESSION_TAB_HISTORY_LIMIT)
  return { entries, index: entries.length - 1 }
}

export function moveSessionTabHistory(
  history: SessionTabHistory,
  tabs: readonly SessionTab[],
  active: string | undefined,
  direction: 1 | -1,
) {
  if (!active) {
    const sessionID = history.entries[history.index]
    return tabs.some((tab) => tab.sessionID === sessionID) ? { history, sessionID } : { history, sessionID: undefined }
  }
  const entries = history.entries.map((sessionID, index) => ({ sessionID, index }))
  const candidates = direction === -1 ? entries.slice(0, history.index).reverse() : entries.slice(history.index + 1)
  const target = candidates.find(
    (entry) => entry.sessionID !== active && tabs.some((tab) => tab.sessionID === entry.sessionID),
  )
  if (!target) return { history, sessionID: undefined }
  return { history: { ...history, index: target.index }, sessionID: target.sessionID }
}

export type SessionTabMotionValues = {
  widths: number[]
  selections: number[]
  activities: number[]
}

/**
 * Seed width motion for a visible-tab membership change: retained tabs keep their current animated
 * values and first-seen tabs grow in from zero width. Returns undefined when nothing is retained,
 * meaning the window was fully replaced and the strip should jump.
 */
export function seedSessionTabMotion(
  previous: readonly string[],
  ids: readonly string[],
  current: SessionTabMotionValues,
  next: SessionTabMotionValues,
): SessionTabMotionValues | undefined {
  const positions = ids.map((id) => previous.indexOf(id))
  if (positions.every((position) => position === -1)) return undefined
  return {
    widths: positions.map((position, index) =>
      position === -1 ? 0 : (current.widths[position] ?? next.widths[index] ?? 0),
    ),
    selections: positions.map(
      (position, index) => (position === -1 ? next.selections[index] : current.selections[position]) ?? 0,
    ),
    activities: positions.map(
      (position, index) => (position === -1 ? next.activities[index] : current.activities[position]) ?? 0,
    ),
  }
}

export function adaptiveSessionTabLayout(
  tabs: readonly SessionTab[],
  active: string | undefined,
  available: number,
  previousStart = 0,
) {
  if (tabs.length === 0) return { tabs: [], widths: [], before: 0, after: 0, start: 0, total: 0 }

  const activeIndex = tabs.findIndex((tab) => tab.sessionID === active)
  const fit = (width: number) =>
    Math.min(
      tabs.length,
      Math.max(
        1,
        activeIndex === -1
          ? Math.floor(Math.max(0, width) / SESSION_TAB_MIN_WIDTH)
          : 1 + Math.floor((Math.max(0, width) - SESSION_TAB_WIDTH) / SESSION_TAB_MIN_WIDTH),
      ),
    )
  const solve = (count: number, start: number, attempts: number): { count: number; start: number } => {
    const boundedStart = Math.min(Math.max(0, start), tabs.length - count)
    const nextStart = Math.min(
      Math.max(
        0,
        activeIndex === -1
          ? boundedStart
          : activeIndex < boundedStart
            ? activeIndex
            : activeIndex >= boundedStart + count
              ? activeIndex - count + 1
              : boundedStart,
      ),
      tabs.length - count,
    )
    const markers =
      (nextStart > 0 ? sessionTabOverflowWidth(nextStart) : 0) +
      (nextStart + count < tabs.length ? sessionTabOverflowWidth(tabs.length - nextStart - count) : 0)
    const nextCount = fit(available - markers)
    if (nextCount === count || attempts === 0) return { count, start: nextStart }
    return solve(nextCount, nextStart, attempts - 1)
  }
  const solved = solve(fit(available), previousStart, 3)
  const visible = tabs.slice(solved.start, solved.start + solved.count)
  const before = solved.start
  const after = tabs.length - solved.start - solved.count
  const contentWidth = Math.max(
    1,
    available - (before > 0 ? sessionTabOverflowWidth(before) : 0) - (after > 0 ? sessionTabOverflowWidth(after) : 0),
  )
  const roomy = contentWidth >= SESSION_TAB_WIDTH * visible.length
  const total = roomy ? Math.min(contentWidth, SESSION_TAB_MAX_WIDTH * visible.length) : contentWidth
  if (roomy || activeIndex === -1) {
    const width = Math.floor(total / visible.length)
    const remainder = total - width * visible.length
    return {
      tabs: visible,
      widths: visible.map((_, index) => width + Number(index < remainder)),
      before,
      after,
      start: solved.start,
      total,
    }
  }
  const inactiveWidth =
    visible.length === 1
      ? 0
      : Math.min(
          SESSION_TAB_WIDTH,
          Math.max(
            SESSION_TAB_MIN_WIDTH,
            Math.floor((total - Math.min(SESSION_TAB_WIDTH, total)) / (visible.length - 1)),
          ),
        )
  const activeWidth = visible.length === 1 ? total : total - inactiveWidth * (visible.length - 1)

  return {
    tabs: visible,
    widths: visible.map((tab) => (tab.sessionID === active ? activeWidth : inactiveWidth)),
    before,
    after,
    start: solved.start,
    total,
  }
}

import { createEffect, createMemo, createSignal, on, onCleanup } from "solid-js"
import { createStore } from "solid-js/store"
import { useKeyboard, useRenderer } from "@opentui/solid"
import { isDeepEqual } from "remeda"
import { createSimpleContext } from "./helper"
import { useClient } from "./client"
import { locationKey, useData } from "./data"
import { withTimestampedFallback } from "@opencode/util/session-title-fallback"
import { useEvent } from "./event"
import { useRoute } from "./route"
import { useConfig } from "../config"
import { useLocation } from "./location"
import { useStorage } from "./storage"
import { useTuiPaths } from "./runtime"
import { newSessionLocation } from "../config/new-session-location"
import { createSessionRetention } from "./session-retention"
import { anchorKey, type AnchorTarget } from "../routes/session/anchors"
import {
  closeSessionTab,
  cycleSessionTab,
  moveSessionTab,
  moveSessionTabHistory,
  NEW_SESSION_TAB_TITLE,
  openSessionTab,
  recordClosedSessionTab,
  recordSessionTabHistory,
  reopenSessionTab,
  type ClosedSessionTab,
  type SessionTab,
  type SessionTabHistory,
} from "./session-tabs-model"

type TabsState = {
  tabs: SessionTab[]
  // Kept empty for rollback compatibility with clients that still read this field.
  unread: Record<string, unknown>
}

type PersistedState = {
  global: TabsState
  cwd: Record<string, TabsState>
}

export type ScrollAnchor = {
  target: AnchorTarget
  screenY: number
}

const empty = (): TabsState => ({ tabs: [], unread: {} })

// Deliberately after connect settles: the visible session's mount syncs win the first slots.
const TAB_PREFETCH_DELAY = 300
const VIEW_RETRY_DELAY = 250
const VIEW_RETRY_MAX_DELAY = 5_000

export const { use: useSessionTabs, provider: SessionTabsProvider } = createSimpleContext({
  name: "SessionTabs",
  init: () => {
    const route = useRoute()
    const client = useClient()
    const data = useData()
    const event = useEvent()
    const config = useConfig().data
    const location = useLocation()
    const paths = useTuiPaths()
    const renderer = useRenderer()
    const storage = useStorage()
    const enabled = () => config.tabs.enabled
    const [focused, setFocused] = createSignal<boolean>()
    // Keyed reconcile keeps tab object identity across reorders, so strip rows move instead of
    // mutating in place, which per-row animations and drag state depend on.
    const [store, updateStore] = storage.store<PersistedState>("tabs", {
      initial: {
        global: empty(),
        cwd: {},
      },
      key: "sessionID",
    })
    const fallback = empty()
    const [promptPulses, setPromptPulses] = createSignal<Record<string, number>>({})
    let history: SessionTabHistory = { entries: [], index: -1 }
    // User-closed tabs eligible for reopening; in-memory like history, deleted sessions pruned.
    const [closedTabs, setClosedTabs] = createSignal<ClosedSessionTab[]>([])
    // Storage mutations apply against the on-disk draft under a file lock, so
    // a registration queued by the route effect can land AFTER a removal that
    // ran while the write was still in flight — resurrecting a tab that was
    // just closed. Removing a tab marks it cancelled so any late-applying
    // registration becomes a no-op; navigating to the session again clears
    // the mark.
    const cancelledTabs = new Set<string>()
    const scrollAnchors = new Map<string, ScrollAnchor>()
    const [expandedGroups, setExpandedGroups] = createStore<Record<string, Record<string, boolean> | undefined>>({})

    const onFocus = () => setFocused(true)
    const onBlur = () => setFocused(false)
    useKeyboard(onFocus)
    renderer.on("focus", onFocus)
    renderer.on("blur", onBlur)
    onCleanup(() => {
      renderer.off("focus", onFocus)
      renderer.off("blur", onBlur)
    })

    function state() {
      if (config.tabs.scope === "cwd") return store.cwd[paths.cwd] ?? fallback
      return store.global
    }

    function update(mutation: (draft: TabsState) => void) {
      const scope = config.tabs.scope
      void updateStore((draft) => mutation(scope === "cwd" ? (draft.cwd[paths.cwd] ??= empty()) : draft.global)).catch(
        // Failed writes lose only tab layout, but silence would hide tabs resetting every launch.
        (error) => console.error("Failed to persist session tabs", error),
      )
    }

    const root = (sessionID: string) => data.session.root(sessionID)
    const title = (sessionID: string, persisted?: string, fallback?: string) => {
      const session = data.session.get(sessionID)
      return session?.title ?? persisted ?? fallback ?? (session ? withTimestampedFallback(session) : undefined)
    }
    const isUnread = (sessionID: string) => {
      const info = data.session.get(sessionID)
      return info?.time.idle !== undefined && (info.time.viewed === undefined || info.time.idle > info.time.viewed)
    }
    const family = (sessionID: string) => {
      const session = root(sessionID)
      const members = data.session.family(session)
      return members.includes(session) ? members : [session, ...members]
    }
    const normalize = (value: TabsState) => ({
      tabs: value.tabs.reduce<SessionTab[]>((tabs, tab) => {
        const sessionID = root(tab.sessionID)
        return openSessionTab(tabs, { sessionID, title: title(sessionID, tab.title) })
      }, []),
      unread: {},
    })
    const current = () => (route.data.type === "session" ? root(route.data.sessionID) : undefined)
    createSessionRetention({
      session: data.session,
      current: () =>
        route.data.type === "session" && route.data.sessionID !== "dummy" ? route.data.sessionID : undefined,
      keep: () => (enabled() ? state().tabs.map((tab) => tab.sessionID) : []),
      limit: 3,
    })
    const newTab = createMemo((open = false) => {
      if (route.data.type === "home") return true
      if (!open) return false
      const sessionID = current()
      return sessionID !== undefined && !state().tabs.some((tab) => tab.sessionID === sessionID)
    }, false)
    const status = (sessionID: string) => {
      const session = root(sessionID)
      const members = family(session)
      return {
        // Unread reads the root session only: background subagent completions wake the parent,
        // whose own idle transition then carries the signal.
        unread: !isUnread(session)
          ? undefined
          : data.session.get(session)?.outcome === "failed"
            ? ("error" as const)
            : ("activity" as const),
        promptPulse: promptPulses()[session] ?? 0,
        attention: members.some((id) => (data.session.permission.list(id)?.length ?? 0) > 0)
          ? ("permission" as const)
          : members.some((id) => (data.session.form.list(id)?.length ?? 0) > 0)
            ? ("question" as const)
            : (false as const),
        // Parked synthetic context (user shells, plan reminders) stays pending without execution; only work counts as busy.
        busy: members.some(
          (id) =>
            data.session.status(id) === "running" ||
            data.session.pending.list(id).some((item) => item.type !== "synthetic"),
        ),
        renaming: data.session.title.pending(session),
      }
    }

    // Shared storage updates must not re-admit a tab unless this client changes route or scope.
    createEffect(
      on(
        [
          () => (enabled() && route.data.type === "session" ? route.data.sessionID : undefined),
          () => config.tabs.scope,
        ],
        ([routed]) => {
          if (!routed || routed === "dummy") return
          const sessionID = root(routed)
          cancelledTabs.delete(sessionID)
          history = recordSessionTabHistory(history, sessionID)
          if (state().tabs.some((tab) => tab.sessionID === sessionID)) return
          const fallback = newTab() ? NEW_SESSION_TAB_TITLE : undefined
          update((draft) => {
            if (cancelledTabs.has(sessionID)) return
            const tab = {
              sessionID,
              title: title(sessionID, draft.tabs.find((tab) => tab.sessionID === sessionID)?.title, fallback),
            }
            draft.tabs = openSessionTab(draft.tabs, tab)
          })
        },
      ),
    )

    // Viewed state is server-global, so acknowledgement runs even with tabs disabled: other
    // clients rely on this client reporting what its user has seen.
    const acknowledged = new Map<string, number>()
    const [viewRetry, setViewRetry] = createSignal(0)
    let viewRetryTimer: ReturnType<typeof setTimeout> | undefined
    let viewRetryAttempt = 0
    onCleanup(() => clearTimeout(viewRetryTimer))
    createEffect(() => {
      viewRetry()
      if (focused() !== true) return
      if (route.data.type !== "session" || route.data.sessionID === "dummy") return
      const sessionID = root(route.data.sessionID)
      const idle = data.session.get(sessionID)?.time.idle
      if (idle === undefined || !isUnread(sessionID) || acknowledged.get(sessionID) === idle) return
      // Record before the request so event-driven re-runs don't re-post the same watermark.
      acknowledged.set(sessionID, idle)
      void client.api.session.view({ sessionID, idle }).then(
        () => {
          clearTimeout(viewRetryTimer)
          viewRetryTimer = undefined
          viewRetryAttempt = 0
        },
        () => {
          if (acknowledged.get(sessionID) !== idle) return
          acknowledged.delete(sessionID)
          if (viewRetryTimer) return
          const delay = Math.min(VIEW_RETRY_DELAY * 2 ** viewRetryAttempt, VIEW_RETRY_MAX_DELAY)
          viewRetryAttempt++
          viewRetryTimer = setTimeout(() => {
            viewRetryTimer = undefined
            setViewRetry((value) => value + 1)
          }, delay)
        },
      )
    })

    createEffect(() => {
      if (!enabled()) return
      const next = normalize(state())
      if (isDeepEqual(next, state())) return
      update((draft) => {
        const next = normalize(draft)
        draft.tabs = next.tabs
        draft.unread = next.unread
      })
    })

    // Load lightweight session and location metadata concurrently so persisted tabs can resolve
    // their project and branch labels. Delay the heavier per-tab data so the visible session keeps
    // the first connection slots and switches still render from a warm cache.
    const openTabSessions = createMemo(() =>
      state()
        .tabs.map((tab) => tab.sessionID)
        .sort()
        .join("\n"),
    )
    createEffect(() => {
      if (!enabled()) return
      if (client.connection.status() !== "connected") return
      const signature = openTabSessions()
      if (signature === "") return
      const sessionIDs = signature.split("\n")
      let stale = false
      void (async () => {
        await Promise.allSettled(sessionIDs.map((sessionID) => data.session.sync(sessionID, { children: true })))
        if (stale) return
        const locations = new Map(
          sessionIDs
            .map((sessionID) => data.session.get(sessionID)?.location)
            .filter((location) => location !== undefined)
            .map((location) => [locationKey(location), location]),
        )
        await Promise.allSettled(
          Array.from(locations.values(), (location) =>
            Promise.all([data.location.syncInfo(location), data.location.vcs.sync(location)]),
          ),
        )
      })()
      const timer = setTimeout(async () => {
        const sessions = state()
          .tabs.map((tab) => tab.sessionID)
          .filter((sessionID) => sessionID !== current())
        for (const sessionID of sessions) {
          if (stale) return
          await Promise.allSettled([
            data.session.message.sync(sessionID),
            data.session.pending.sync(sessionID),
            data.session.permission.sync(sessionID),
            data.session.form.sync(sessionID),
          ])
        }
      }, TAB_PREFETCH_DELAY)
      onCleanup(() => {
        stale = true
        clearTimeout(timer)
      })
    })

    onCleanup(
      event.on("session.moved", (evt) => {
        if (!enabled() || !state().tabs.some((tab) => tab.sessionID === root(evt.data.sessionID))) return
        void Promise.allSettled([data.location.syncInfo(evt.data.location), data.location.vcs.sync(evt.data.location)])
      }),
    )
    onCleanup(
      event.on("session.inbox.enqueued", (evt) => {
        if (!enabled() || evt.data.item.type !== "user") return
        const sessionID = root(evt.data.sessionID)
        if (current() === sessionID || !state().tabs.some((tab) => tab.sessionID === sessionID)) return
        setPromptPulses((pulses) => ({ ...pulses, [sessionID]: (pulses[sessionID] ?? 0) + 1 }))
      }),
    )
    onCleanup(
      event.on("session.deleted", (evt) => {
        const target = root(evt.data.sessionID)
        setClosedTabs((entries) => entries.filter((entry) => entry.tab.sessionID !== target))
        remove(evt.data.sessionID, enabled())
      }),
    )

    function remove(sessionID: string, navigate: boolean) {
      const target = root(sessionID)
      cancelledTabs.add(target)
      family(target).forEach((id) => {
        scrollAnchors.delete(id)
        setExpandedGroups(id, undefined)
      })
      const closed = closeSessionTab(state().tabs, target)
      const selected = navigate && current() === target
      if (closed.tabs === state().tabs && !selected) return
      const previous = selected
        ? moveSessionTabHistory(recordSessionTabHistory(history, target), closed.tabs, target, -1)
        : { history, sessionID: undefined }
      const next = previous.sessionID ?? closed.next
      history = previous.history
      update((draft) => {
        draft.tabs = closeSessionTab(draft.tabs, target).tabs
      })
      setPromptPulses((pulses) => {
        if (pulses[target] === undefined) return pulses
        const next = { ...pulses }
        delete next[target]
        return next
      })
      if (selected) route.navigate(next ? { type: "session", sessionID: next } : { type: "home" })
    }

    return {
      enabled,
      tabs() {
        return state().tabs
      },
      recentlyClosed() {
        return closedTabs()
          .filter((entry) => !state().tabs.some((tab) => tab.sessionID === entry.tab.sessionID))
          .toReversed()
          .map((entry) => ({
            ...entry.tab,
            title: data.session.get(entry.tab.sessionID)?.title ?? entry.tab.title,
          }))
      },
      newTab() {
        return newTab()
      },
      current,
      status,
      scrollAnchor(sessionID: string) {
        const target = root(sessionID)
        if (!state().tabs.some((tab) => tab.sessionID === target)) return
        return scrollAnchors.get(sessionID)
      },
      setScrollAnchor(sessionID: string, anchor: ScrollAnchor | undefined) {
        const target = root(sessionID)
        if (anchor === undefined || !state().tabs.some((tab) => tab.sessionID === target)) {
          scrollAnchors.delete(sessionID)
          return
        }
        const current = scrollAnchors.get(sessionID)
        if (current && anchorKey(current.target) === anchorKey(anchor.target) && current.screenY === anchor.screenY)
          return
        scrollAnchors.set(sessionID, anchor)
      },
      groupExpanded(sessionID: string, groupID: string) {
        return expandedGroups[sessionID]?.[groupID]
      },
      setGroupExpanded(sessionID: string, groupID: string, expanded: boolean) {
        setExpandedGroups(sessionID, (current) => ({ ...current, [groupID]: expanded }))
      },
      select(sessionID: string) {
        if (!enabled()) return
        route.navigate({ type: "session", sessionID: root(sessionID) })
      },
      open(sessionID: string) {
        if (!enabled()) return
        const session = root(sessionID)
        if (state().tabs.some((tab) => tab.sessionID === session)) return
        cancelledTabs.delete(session)
        update((draft) => {
          draft.tabs = openSessionTab(draft.tabs, { sessionID: session, title: title(session) })
        })
      },
      add() {
        if (!enabled()) return
        const sessionID = current()
        const currentLocation = (sessionID ? data.session.get(sessionID)?.location : undefined) ?? location.ref
        route.navigate({
          type: "home",
          location: newSessionLocation(
            config.session.new_location,
            data.location.default().directory,
            currentLocation,
            location.error?.location,
          ),
        })
      },
      close(sessionID?: string) {
        if (!enabled()) return
        const target = sessionID ? root(sessionID) : current()
        if (!target) {
          const previous = moveSessionTabHistory(history, state().tabs, undefined, -1)
          history = previous.history
          const session = previous.sessionID ?? state().tabs.at(-1)?.sessionID
          if (route.data.type === "home" && session) route.navigate({ type: "session", sessionID: session })
          return
        }
        const index = state().tabs.findIndex((tab) => tab.sessionID === target)
        const tab = state().tabs[index]
        if (tab) setClosedTabs((entries) => recordClosedSessionTab(entries, tab, index))
        remove(target, true)
      },
      reopen(sessionID?: string) {
        if (!enabled()) return
        const result = reopenSessionTab(closedTabs(), state().tabs, sessionID)
        setClosedTabs(result.stack)
        const tabs = result.tabs
        if (!tabs || !result.sessionID) return
        cancelledTabs.delete(result.sessionID)
        update((draft) => {
          draft.tabs = tabs
        })
        route.navigate({ type: "session", sessionID: result.sessionID })
      },
      move(sessionID: string, index: number) {
        if (!enabled()) return
        const session = root(sessionID)
        if (moveSessionTab(state().tabs, session, index) === state().tabs) return
        update((draft) => {
          draft.tabs = moveSessionTab(draft.tabs, session, index)
        })
      },
      cycle(direction: 1 | -1) {
        if (!enabled()) return
        const tab = cycleSessionTab(state().tabs, current(), direction)
        if (tab) route.navigate({ type: "session", sessionID: tab.sessionID })
      },
      cycleUnread(direction: 1 | -1) {
        if (!enabled()) return
        const tab = cycleSessionTab(state().tabs, current(), direction, (tab) =>
          Boolean(status(tab.sessionID).unread || status(tab.sessionID).attention),
        )
        if (tab) route.navigate({ type: "session", sessionID: tab.sessionID })
      },
      selectIndex(index: number) {
        if (!enabled()) return
        const tab = state().tabs[index]
        if (tab) route.navigate({ type: "session", sessionID: tab.sessionID })
      },
    }
  },
})

import type { PersistentPtyInfo } from "@opencode/client"
import { createSignal, onCleanup } from "solid-js"
import { createSimpleContext } from "./helper"
import { useClient } from "./client"
import { useData } from "./data"
import { useEvent } from "./event"
import { useStorage } from "./storage"

type SessionTerminalsState = {
  sessions: Record<string, string | null>
}

export const { use: useSessionTerminals, provider: SessionTerminalsProvider } = createSimpleContext({
  name: "SessionTerminals",
  init: () => {
    const client = useClient()
    const data = useData()
    const event = useEvent()
    const [available, setAvailable] = createSignal(false)
    const [focus, setFocus] = createSignal<string>()
    const storage = useStorage()
    const [store, update] = storage.store<SessionTerminalsState>("session-terminal-selection", {
      initial: { sessions: {} },
    })
    const [terminals, updateTerminals] = storage.memory<Record<string, PersistentPtyInfo[]>>("session-terminals", {
      initial: {},
    })

    const refresh = async (sessionID: string) => {
      if (!terminals[sessionID]) updateTerminals((draft) => (draft[sessionID] = []))
      const result = await client.api.experimental.persistentPty.list({ sessionID })
      updateTerminals((draft) => (draft[sessionID] = result))
      const selected = store.sessions[sessionID]
      if (!selected || result.some((terminal) => terminal.id === selected)) return
      await update((draft) => {
        if (draft.sessions[sessionID] !== selected) return
        draft.sessions[sessionID] = null
      })
    }

    const selectTerminal = async (sessionID: string, ptyID: string | null) => {
      if (ptyID !== null && !terminals[sessionID]?.some((terminal) => terminal.id === ptyID)) return
      setFocus(ptyID ?? undefined)
      await update((draft) => {
        draft.sessions[sessionID] = ptyID
      })
    }

    for (const type of ["persistent-pty.added", "persistent-pty.removed"] as const) {
      onCleanup(
        event.on(type, (evt) => {
          if (!available() || !terminals[evt.data.sessionID]) return
          void refresh(evt.data.sessionID).catch((error) =>
            console.error("Failed to refresh persistent terminal panes", error),
          )
        }),
      )
    }
    // The event stream opens with server.connected, so this runs for the first connection and every reconnect.
    onCleanup(
      event.on("server.connected", () => {
        void client.api.server
          .info()
          .then((info) => {
            // Servers that predate the field omit it; keep offering terminals as clients did before.
            setAvailable(info.capabilities?.persistentPty !== false)
            if (!available()) return
            Object.keys(terminals).forEach((sessionID) => {
              void refresh(sessionID).catch((error) =>
                console.error("Failed to refresh persistent terminal panes", error),
              )
            })
          })
          .catch((error) => {
            setAvailable(false)
            console.error("Failed to read server terminal support", error)
          })
      }),
    )

    return {
      available,
      get(sessionID: string) {
        return {
          terminals: terminals[sessionID] ?? [],
          selectedTerminalID: store.sessions[sessionID] ?? null,
        }
      },
      refresh,
      selectTerminal,
      async newTerminal(sessionID: string): Promise<PersistentPtyInfo> {
        const session = data.session.get(sessionID)
        const terminal = await client.api.experimental.persistentPty.create({
          sessionID,
          args: [],
          cwd: session?.location.directory,
          title: "Terminal",
          env: {},
        })
        await refresh(sessionID)
        await selectTerminal(sessionID, terminal.id)
        return terminal
      },
      shouldFocus(ptyID: string) {
        return focus() === ptyID
      },
      clearFocus(ptyID: string) {
        setFocus((current) => (current === ptyID ? undefined : current))
      },
    }
  },
})

import { batch, createContext, onCleanup, useContext, type ParentProps } from "solid-js"
import { createStore, produce, reconcile, type Store } from "solid-js/store"
import path from "path"
import { mkdirSync, readFileSync, watch } from "fs"
import { Flock } from "@opencode/util/flock"
import { writeJsonAtomic } from "../util/persistence"
import { useTuiApp, useTuiPaths } from "./runtime"

type Options<Value extends object> = {
  readonly initial: Value
  /** Reconcile key for arrays inside the stored value, preserving item identity across updates. Defaults to "id". */
  readonly key?: string
}

type Entry<Value extends object> = readonly [Store<Value>, (mutation: (draft: Value) => void) => Promise<void>]
type MemoryEntry<Value extends object> = readonly [Store<Value>, (mutation: (draft: Value) => void) => void]

export interface Storage {
  store<Value extends object>(
    key: string,
    options: Options<Value>,
  ): readonly [Store<Value>, (mutation: (draft: Value) => void) => Promise<void>]
  /**
   * Ephemeral in-process state. Entries are memoized here, above consumer
   * lifecycles, so the same live store survives plugin hot reloads; it is
   * gone when the TUI exits. Updates are synchronous and values need not be
   * JSON-serializable.
   */
  memory<Value extends object>(key: string, options: { readonly initial: Value }): MemoryEntry<Value>
  flush(): Promise<void>
}

function clone<Value extends object>(value: Value) {
  const json = JSON.stringify(value)
  if (json === undefined) throw new TypeError("Storage values must be JSON-compatible objects")
  const result = JSON.parse(json) as Value
  if (typeof result !== "object" || result === null) throw new TypeError("Storage values must be objects")
  return result as Value
}

function segment(value: string) {
  if (!/^[a-zA-Z0-9][a-zA-Z0-9._-]*$/.test(value) || value === "." || value === "..")
    throw new TypeError(`Invalid storage segment: ${value}`)
  return value
}

export function createStorage(root: string, channel: string) {
  const entries = new Map<string, { readonly value: Entry<object>; readonly reload: () => void }>()
  const memories = new Map<string, MemoryEntry<object>>()
  const pending = new Set<Promise<void>>()
  const directory = path.join(root, segment(channel), "tui")
  const locks = path.join(root, segment(channel), "locks")
  mkdirSync(directory, { recursive: true })

  const storage: Storage = {
    store<Value extends object>(key: string, options: Options<Value>) {
      const file = path.join(directory, segment(key) + ".json")
      const existing = entries.get(file)
      if (existing) return existing.value as Entry<Value>

      const load = () => {
        try {
          return clone(JSON.parse(readFileSync(file, "utf8")) as Value)
        } catch {
          return clone(options.initial)
        }
      }
      const [store, setStore] = createStore(load())
      const merge = (next: Value) => reconcile(next, { key: options.key })
      const reload = () => batch(() => setStore(merge(load())))
      const update = (mutation: (draft: Value) => void) => {
        const operation = Flock.withLock(
          file,
          async () => {
            const draft = load()
            mutation(draft)
            const next = clone(draft)
            await writeJsonAtomic(file, next)
            batch(() => setStore(merge(next)))
          },
          { dir: locks },
        )
        pending.add(operation)
        operation.then(
          () => pending.delete(operation),
          () => pending.delete(operation),
        )
        return operation
      }
      const entry = [store, update] as const
      entries.set(file, { value: entry as Entry<object>, reload })
      return entry
    },
    memory<Value extends object>(key: string, options: { readonly initial: Value }) {
      const existing = memories.get(key)
      if (existing) return existing as MemoryEntry<Value>
      const [store, setStore] = createStore(options.initial)
      const entry = [store, (mutation: (draft: Value) => void) => setStore(produce(mutation))] as const
      memories.set(key, entry as MemoryEntry<object>)
      return entry
    },
    async flush() {
      const failures: unknown[] = []
      while (pending.size > 0) {
        const results = await Promise.allSettled(pending)
        failures.push(...results.filter((result) => result.status === "rejected").map((result) => result.reason))
      }
      if (failures.length === 1) throw failures[0]
      if (failures.length > 1) throw new AggregateError(failures, "Storage writes failed")
    },
  }

  let reloadTimer: ReturnType<typeof setTimeout> | undefined
  let watcher: ReturnType<typeof watch> | undefined
  try {
    watcher = watch(directory, () => {
      clearTimeout(reloadTimer)
      // Atomic writes notify for the temporary file before its final rename, and some
      // platforms coalesce the rename event. Reload after the event burst has settled.
      reloadTimer = setTimeout(() => entries.forEach((entry) => entry.reload()), 50)
    })
    watcher.on("error", (error) => {
      clearTimeout(reloadTimer)
      watcher?.close()
      watcher = undefined
      console.error("Storage directory watcher failed, live-reload disabled", { directory, error })
    })
  } catch (error) {
    // fs.watch throws synchronously (e.g. ENOSPC when the inotify watch limit is
    // exhausted). Losing cross-process live-reload is recoverable; crashing the
    // whole TUI over it is not, so degrade instead of propagating.
    console.error("Failed to watch storage directory, live-reload disabled", { directory, error })
  }
  return {
    storage,
    close: () => {
      clearTimeout(reloadTimer)
      watcher?.close()
    },
  }
}

const Context = createContext<Storage>()

export function StorageProvider(props: ParentProps) {
  const result = createStorage(useTuiPaths().state, useTuiApp().channel)
  onCleanup(result.close)
  return <Context.Provider value={result.storage}>{props.children}</Context.Provider>
}

export function useStorage() {
  const storage = useContext(Context)
  if (!storage) throw new Error("StorageProvider is missing")
  return storage
}

export function useStorageOptional() {
  return useContext(Context)
}

import { CliRenderEvents, SyntaxStyle, type TerminalColors } from "@opentui/core"
import { useRenderer } from "@opentui/solid"
import {
  generateSyntax,
  resolveThemeDocument,
  themeModes,
  type ResolvedTheme,
  type SurfaceName,
} from "@opencode/theme/tui"
import {
  allThemes,
  getOpenCode2Theme,
  hasTheme,
  parseTheme,
  setCustomThemes,
  setSystemTheme,
  subscribeThemes,
  type ThemeDocumentSource,
} from "../theme"
import { generateSystem, terminalMode } from "../theme/system"
import { discoverThemes } from "../theme/discovery"
import { createComponentTheme, type ComponentTheme } from "../theme/component"
import { createEffect, createMemo, createSignal, onCleanup, onMount, type Accessor, type ParentProps } from "solid-js"
import { createStore, produce } from "solid-js/store"
import { createSimpleContext } from "./helper"
import { useConfig, useNewDesigns } from "../config"
import { useStorageOptional } from "./storage"
import { DevTools } from "../devtools"
import { configDirectories } from "../util/config-directories"

const themePerformance = DevTools.register({ id: "theme-performance", title: "Theme performance" })
export type ThemeError = { name: string; error: Error }
type ThemeErrorHandler = (event: ThemeError) => void

function createThemeErrors() {
  let handler: ThemeErrorHandler | undefined
  let pending: ThemeError | undefined

  return {
    emit(name: string, cause: unknown) {
      const event = { name, error: cause instanceof Error ? cause : new Error(String(cause)) }
      if (handler) {
        handler(event)
        return
      }
      pending = event
    },
    onError(next: ThemeErrorHandler) {
      handler = next
      if (pending) {
        next(pending)
        pending = undefined
      }
      return () => {
        if (handler === next) handler = undefined
      }
    },
  }
}

const themeErrors = createThemeErrors()

export type ThemeSource = Readonly<{
  discover(): Promise<Record<string, unknown>>
  subscribeRefresh?(refresh: () => void): () => void
}>

export const createThemeSource = (config: string): ThemeSource => ({
  async discover() {
    return discoverThemes(configDirectories(config, process.cwd()))
  },
  subscribeRefresh(refresh) {
    process.on("SIGUSR2", refresh)
    return () => process.off("SIGUSR2", refresh)
  },
})

const THEME_REFRESH_DELAYS = [250, 1000] as const

type State = {
  mode: "dark" | "light"
  lock: "dark" | "light" | undefined
  active: string
  ready: boolean
}

type Themes = {
  current: ComponentTheme
  currentTokens: Accessor<ResolvedTheme>
  readonly selected: string
  all: typeof allThemes
  has: typeof hasTheme
  currentSyntax: Accessor<SyntaxStyle>
  mode: Accessor<"dark" | "light">
  modes: Accessor<readonly ("dark" | "light")[]>
  supports(mode: "dark" | "light"): boolean
  locked: Accessor<boolean>
  lock(): void
  unlock(): void
  setMode(mode?: "dark" | "light", persist?: boolean): boolean
  set(theme: string): boolean
  afterPaint(): void
  onError(handler: ThemeErrorHandler): () => void
  readonly ready: boolean
}

type ThemeContextValue = {
  current: ComponentTheme
  themes: Themes
  readonly ready: boolean
}

const [store, setStore] = createStore<State>({
  mode: "dark",
  lock: undefined,
  active: "opencode",
  ready: false,
})
const [themeSources, setThemeSources] = createSignal(allThemes())

subscribeThemes(setThemeSources)

const themeContext = createSimpleContext({
  name: "Theme",
  init: (props: { mode: "dark" | "light"; source: ThemeSource }): ThemeContextValue => {
    const renderer = useRenderer()
    const configState = useConfig()
    const newDesigns = useNewDesigns()
    const config = configState.data
    const themes = props.source
    const cache = useStorageOptional()?.store<{ colors?: TerminalColors }>("system-theme", { initial: {} })

    setStore(
      produce((draft) => {
        const lock = config.theme?.mode === "dark" || config.theme?.mode === "light" ? config.theme.mode : undefined
        const mode = lock ?? renderer.themeMode ?? props.mode
        draft.mode = mode
        draft.lock = lock
        draft.active = config.theme?.name ?? "opencode"
        draft.ready = false
      }),
    )

    createEffect(() => {
      const theme = config.theme?.name
      if (!theme) return
      setStore("active", theme)
      if (theme === "system") refreshPalette()
    })

    createEffect(() => {
      const mode = config.theme?.mode
      if (mode === "dark" || mode === "light") {
        pin(mode, false)
        return
      }
      if (mode === "system" && store.lock !== undefined) free(false)
    })

    function syncCustomThemes() {
      return themes
        .discover()
        .then((themes) => {
          setCustomThemes(themes)
        })
        .catch(() => setStore("active", "opencode"))
    }

    onMount(() => {
      // Terminal palette queries serialize with frame output. First paint uses the cached palette or built-in fallback.
      void syncCustomThemes().finally(() => {
        tokens()
        setStore("ready", true)
      })
    })

    const cachedPalette = cache?.[0].colors
    let palette = usablePalette(cachedPalette) ? cachedPalette : undefined
    const applyPalette = () => {
      if (palette) setSystemTheme(generateSystem(palette, store.mode))
    }
    if (palette) {
      const mode = store.lock ?? terminalMode(palette) ?? store.mode
      if (store.mode !== mode) setStore("mode", mode)
      applyPalette()
    } else setSystemTheme(undefined)

    let canProbe = false
    let probing = false
    let queued = false
    let disposed = false
    function refreshPalette() {
      if (store.active !== "system") return
      queued = true
      if (!canProbe || probing || disposed) return

      queued = false
      probing = true
      // Clearing does not cancel a query already owned by the renderer. Share it, then run one fresh query.
      const retry = renderer.paletteDetectionStatus === "detecting"
      renderer.clearPaletteCache()
      void renderer
        .getPalette({ size: 16 })
        .then((colors) => {
          if (disposed || !usablePalette(colors)) return
          palette = colors
          const mode = store.lock ?? terminalMode(colors) ?? store.mode
          if (store.mode !== mode) setStore("mode", mode)
          applyPalette()
          void cache?.[1]((draft) => {
            draft.colors = colors
          }).catch(() => {})
        })
        .catch(() => {})
        .finally(() => {
          probing = false
          if (disposed || (!retry && !queued)) return
          refreshPalette()
        })
    }

    function afterPaint() {
      canProbe = true
      refreshPalette()
    }

    function apply(mode: "dark" | "light") {
      if (store.mode !== mode) {
        setStore("mode", mode)
        applyPalette()
      }
      refreshPalette()
    }

    function pin(mode: "dark" | "light" = store.mode, persist = true) {
      setStore("lock", mode)
      apply(mode)
      if (!persist) return
      void configState
        .update((draft) => {
          draft.theme = { ...draft.theme, mode }
        })
        .catch(() => {})
    }

    function free(persist = true) {
      setStore("lock", undefined)
      apply(renderer.themeMode ?? store.mode)
      if (!persist) return
      void configState
        .update((draft) => {
          draft.theme = { ...draft.theme, mode: "system" }
        })
        .catch(() => {})
    }

    const handleMode = (mode: "dark" | "light") => {
      if (store.lock) return
      apply(mode)
    }
    renderer.on(CliRenderEvents.THEME_MODE, handleMode)

    const handleThemeNotification = (sequence: string) => {
      if (sequence !== "\x1b[?997;1n" && sequence !== "\x1b[?997;2n") return false
      queueMicrotask(refreshPalette)
      return false
    }
    renderer.prependInputHandler(handleThemeNotification)

    let themeRefreshTimeouts: ReturnType<typeof setTimeout>[] = []
    const refreshThemes = () => {
      for (const timeout of themeRefreshTimeouts) clearTimeout(timeout)
      themeRefreshTimeouts = THEME_REFRESH_DELAYS.map((delay) =>
        setTimeout(() => {
          refreshPalette()
          if (delay === THEME_REFRESH_DELAYS[THEME_REFRESH_DELAYS.length - 1]) void syncCustomThemes()
        }, delay),
      )
    }
    const unsubscribeRefresh = themes.subscribeRefresh?.(refreshThemes)

    onCleanup(() => {
      disposed = true
      renderer.off(CliRenderEvents.THEME_MODE, handleMode)
      renderer.removeInputHandler(handleThemeNotification)
      unsubscribeRefresh?.()
      for (const timeout of themeRefreshTimeouts) clearTimeout(timeout)
      themeRefreshTimeouts.length = 0
    })

    const available = createMemo(
      (): Record<string, ThemeDocumentSource> =>
        newDesigns() ? { opencode2: getOpenCode2Theme(), ...themeSources() } : themeSources(),
    )
    const has = (name: string) => Boolean(name) && available()[name] !== undefined

    const initStarted = performance.now()
    const selected = createMemo(() => {
      const sources = available()
      const name = sources[store.active] ? store.active : "opencode"
      try {
        return loadTheme(sources[name], name, store.mode)
      } catch (error) {
        if (name === "opencode") throw error
        themeErrors.emit(name, error)
        setStore("active", "opencode")
        return loadTheme(sources.opencode, "opencode", store.mode)
      }
    })
    const modes = () => selected().modes
    const mode = () => selected().mode
    const tokens = () => selected().theme
    tokens()
    themePerformance.set("Init", `${(performance.now() - initStarted).toFixed(2)} ms`)
    const current = createComponentTheme(tokens)

    createEffect(() => renderer.setBackgroundColor(tokens().background.base))

    const currentSyntax = createSyntaxStyleMemo(() => generateSyntax(tokens()))
    const service: Themes = {
      current,
      currentTokens: tokens,
      currentSyntax,
      get selected() {
        return store.active
      },
      all: available,
      has,
      mode,
      modes,
      supports: (requested) => modes().includes(requested),
      locked: () => store.lock !== undefined,
      lock: () => pin(mode()),
      unlock: free,
      setMode(requested = mode(), persist = true) {
        if (!modes().includes(requested)) return false
        pin(requested, persist)
        return true
      },
      set(theme: string) {
        if (!has(theme)) return false
        setStore("active", theme)
        if (theme === "system") refreshPalette()
        void configState
          .update((draft) => {
            draft.theme = { ...draft.theme, name: theme }
          })
          .catch(() => {})
        return true
      },
      afterPaint,
      onError: themeErrors.onError,
      get ready() {
        return store.ready
      },
    }
    return {
      current,
      themes: service,
      get ready() {
        return service.ready
      },
    }
  },
})

export function useThemes() {
  return themeContext.use().themes
}
export function useTheme(): ComponentTheme {
  return themeContext.use().current
}
export const ThemeProvider = themeContext.provider

/** Switches the ambient theme surface without remounting children; undefined inherits the enclosing view. */
export function ThemeContextProvider(props: ParentProps<{ context: SurfaceName | undefined }>) {
  const value = themeContext.use()
  const current = createComponentTheme(() => {
    const name = props.context
    return name ? value.themes.currentTokens().surface(name) : value.current
  })
  return (
    <themeContext.context.Provider value={{ current, themes: value.themes, ready: value.ready }}>
      {props.children}
    </themeContext.context.Provider>
  )
}

function usablePalette(colors: TerminalColors | undefined): colors is TerminalColors {
  return Boolean(
    colors && (colors.defaultBackground ?? colors.palette[0]) && (colors.defaultForeground ?? colors.palette[7]),
  )
}

function loadTheme(source: ThemeDocumentSource, name: string, requested: "dark" | "light") {
  const document = parseTheme(source, name)
  const modes = themeModes(document)
  const mode = modes.includes(requested) ? requested : (modes[0] ?? requested)
  return { modes, mode, theme: resolveThemeDocument(document, mode) }
}

export function createSyntaxStyleMemo(factory: () => SyntaxStyle) {
  const renderer = useRenderer()
  const retained = new Set<SyntaxStyle>()
  let current: SyntaxStyle | undefined

  const release = (style: SyntaxStyle) => {
    retained.add(style)
    void renderer
      .idle()
      .catch(() => {})
      .finally(() => {
        if (!retained.delete(style)) return
        style.destroy()
      })
  }

  onCleanup(() => {
    if (current) release(current)
  })

  return createMemo(() => {
    const previous = current
    current = factory()
    if (previous) release(previous)
    return current
  })
}

export type ThinkingMode = "show" | "hide"

const MODES: readonly ThinkingMode[] = ["show", "hide"] as const

// OpenAI's Responses API surfaces reasoning summaries that start with a bolded
// title block: "**Inspecting PR workflow**\n\n<body>". Treat that first block,
// or a complete title still awaiting its body while streaming, as disclosure
// metadata so the TUI can style its header independently from the markdown body.
export function reasoningSummary(text: string) {
  const content = text.trim()
  const match = content.match(/^\*\*([^*\n]+)\*\*(?:\r?\n\r?\n|$)/)
  if (!match) return { title: null, body: content }
  return { title: match[1].trim(), body: content.slice(match[0].length).trimEnd() }
}

// Cycle order matches the slash command: show → hide → show.
export function nextThinkingMode(current: ThinkingMode): ThinkingMode {
  const idx = MODES.indexOf(current)
  return MODES[(idx + 1) % MODES.length] ?? "show"
}

import { createSignal, onCleanup, onMount } from "solid-js"
import { createSimpleContext } from "./helper"
import { useLog } from "./log"
import { useStorage } from "./storage"
import { useEvent } from "./event"
import { errorMessage } from "../util/error"
import { useExit } from "./exit"
import { useDialog } from "../ui/dialog"
import { DialogUpdate } from "../component/dialog-update"

type ClientNotice = { readonly type: "available" | "installed"; readonly version: string }
type Notice = ClientNotice & ({ readonly source: "client" } | { readonly source: "server"; readonly remote: boolean })
export type UpdateState =
  | ClientNotice
  | { readonly type: "installing"; readonly version: string }
  | { readonly type: "failed"; readonly message: string }

export type UpdateSource = {
  readonly remote: boolean
  readonly subscribe: (notify: (notice: ClientNotice) => void) => () => void
  readonly check: (
    signal: AbortSignal,
    onInstall: (version: string) => void,
  ) => Promise<ClientNotice | { readonly type: "unavailable"; readonly message: string } | undefined>
  readonly apply: (version: string) => Promise<void>
}

export const { use: useUpdateNotification, provider: UpdateNotificationProvider } = createSimpleContext({
  name: "UpdateNotification",
  init: (props: { updater?: UpdateSource }) => {
    const event = useEvent()
    const exit = useExit()
    const dialog = useDialog()
    const log = useLog({ component: "update-notification" })
    const [state, setState] = createSignal<UpdateState>()
    const [notification, setNotification] = createSignal<Notice>()
    const [notifications, markNotification] = useStorage().store<{ versions: string[] }>("update-notifications", {
      initial: { versions: [] },
    })

    const notify = (notice: Notice) => {
      if (!props.updater) return
      if (
        notifications.versions.includes(`${notice.source}:${notice.version}`) ||
        (notice.source === "client" && notifications.versions.includes(notice.version))
      )
        return
      setNotification((current) => {
        if (notice.source === "server" && current?.source === "client") return current
        return notice
      })
    }

    const dismiss = () => {
      const current = notification()
      if (!current) return
      setNotification(undefined)
      // Only interactions with the automatic notification update its history.
      void markNotification((draft) => {
        draft.versions = [...draft.versions, `${current.source}:${current.version}`].slice(-100)
      }).catch((error) => log.error("failed to persist update notification", { error }))
    }

    const install = async () => {
      const updater = props.updater
      const current = state()
      if (!updater || !current || current.type !== "available") return
      setState({ type: "installing", version: current.version })
      await updater.apply(current.version).then(
        () => setState({ type: "installed", version: current.version }),
        (error) => setState({ type: "failed", message: errorMessage(error) }),
      )
    }

    const check = async (signal: AbortSignal) => {
      const updater = props.updater
      if (!updater || state()?.type === "installing") return
      const result = await updater
        .check(signal, (version) => {
          if (!signal.aborted) setState({ type: "installing", version })
        })
        .finally(() => {
          if (state()?.type === "installing") setState(undefined)
        })
      if (signal.aborted) return
      if (result?.type === "unavailable") return result.message
      setState(result)
    }

    const restart = () => {
      const current = state()
      if (current?.type !== "installed") return
      exit()
    }

    const open = (origin: "manual" | "notification") => {
      if (!props.updater) return
      const current = notification()
      const known = current && (current.source === "client" || !current.remote) ? current : undefined
      if (origin === "notification" && !known) return
      const active = state()
      // The notification can predate an installation through /update.
      if (known && active?.type !== "installing" && !(active?.type === "installed" && active.version === known.version))
        setState({ type: known.type, version: known.version })
      const status = state()?.type
      dialog.replace(() => (
        <DialogUpdate
          check={status === undefined || status === "failed" ? check : undefined}
          state={state}
          skip={dismiss}
          install={install}
          restart={restart}
        />
      ))
    }

    onMount(() => {
      if (!props.updater) return
      onCleanup(props.updater.subscribe((notice) => notify({ ...notice, source: "client" })))
    })

    onCleanup(
      event.on("installation.update-available", (event) =>
        notify({
          source: "server",
          remote: props.updater?.remote ?? false,
          type: "available",
          version: event.data.version,
        }),
      ),
    )
    onCleanup(
      event.on("installation.updated", (event) =>
        notify({
          source: "server",
          remote: props.updater?.remote ?? false,
          type: "installed",
          version: event.data.version,
        }),
      ),
    )

    return {
      notification,
      dismiss,
      open: props.updater ? open : undefined,
    }
  },
})

export * as DevTools from "."

import { createSignal } from "solid-js"

export type Value = string | number | boolean | null

export type Group = Readonly<{
  id: string
  title: string
  entries: readonly Readonly<{ key: string; value: Value }>[]
}>

const [groups, setGroups] = createSignal<readonly Group[]>([])

export function register(input: { id: string; title: string }) {
  setGroups((groups) => {
    if (groups.some((group) => group.id === input.id)) {
      return groups.map((group) => (group.id === input.id ? { ...group, title: input.title } : group))
    }
    return [...groups, { ...input, entries: [] }]
  })

  return {
    set(key: string, value: Value) {
      setGroups((groups) =>
        groups.map((group) => {
          if (group.id !== input.id) return group
          if (group.entries.some((entry) => entry.key === key)) {
            return {
              ...group,
              entries: group.entries.map((entry) => (entry.key === key ? { key, value } : entry)),
            }
          }
          return { ...group, entries: [...group.entries, { key, value }] }
        }),
      )
    },
  }
}

export const data = groups

import { DatabaseSync, type SQLInputValue } from "node:sqlite"

export class Database {
  readonly #database: DatabaseSync

  constructor(file: string, options?: { readonly?: boolean }) {
    this.#database = new DatabaseSync(file, { readOnly: options?.readonly })
  }

  query(sql: string) {
    const statement = this.#database.prepare(sql)
    return {
      all: (parameters?: Record<string, SQLInputValue>) => (parameters ? statement.all(parameters) : statement.all()),
      get: (parameters?: Record<string, SQLInputValue>) => (parameters ? statement.get(parameters) : statement.get()),
    }
  }

  close() {
    this.#database.close()
  }
}

import { Database } from "#zed-sqlite"
import { statSync } from "node:fs"
import { readFile as readFileAsync } from "node:fs/promises"
import os from "node:os"
import path from "node:path"
import { Option, Schema } from "effect"
import type { EditorSelection } from "./context/editor"

const ZedEditorRowSchema = Schema.Struct({
  item_kind: Schema.String,
  editor_id: Schema.NullOr(Schema.Number),
  workspace_id: Schema.Number,
  workspace_paths: Schema.NullOr(Schema.String),
  timestamp: Schema.String,
  buffer_path: Schema.NullOr(Schema.String),
})

const ZedSelectionRowSchema = Schema.Struct({
  selection_start: Schema.NullOr(Schema.Number),
  selection_end: Schema.NullOr(Schema.Number),
})

const ZedEditorContentsSchema = Schema.Struct({
  contents: Schema.NullOr(Schema.String),
})

const decodeZedEditorRow = Schema.decodeUnknownOption(ZedEditorRowSchema)
const decodeZedSelectionRow = Schema.decodeUnknownOption(ZedSelectionRowSchema)
const decodeZedEditorContents = Schema.decodeUnknownOption(ZedEditorContentsSchema)

const utf8 = new TextEncoder()

type ZedEditorRow = Schema.Schema.Type<typeof ZedEditorRowSchema>
type ZedActiveEditorRow = ZedEditorRow & { item_kind: "Editor"; editor_id: number }

export type ZedSelectionResult =
  | { type: "selection"; selection: EditorSelection }
  | { type: "empty" }
  | { type: "unavailable" }

export async function resolveZedSelection(dbPath: string, cwd = process.cwd()): Promise<ZedSelectionResult> {
  const active = queryZedActiveEditor(dbPath, cwd)
  if (active.type !== "row") return active

  const row = active.row
  if (!row.buffer_path) return { type: "empty" }

  const selections = queryZedEditorSelections(dbPath, row)
  if (selections.type !== "selections") return selections
  const byteRanges = selections.selections
    .flatMap((selection) => {
      if (selection.selection_start == null || selection.selection_end == null) return []
      return [
        {
          start: Math.min(selection.selection_start, selection.selection_end),
          end: Math.max(selection.selection_start, selection.selection_end),
        },
      ]
    })
    .sort((left, right) => left.start - right.start || left.end - right.end)
  if (byteRanges.length === 0) return { type: "unavailable" }

  const contents = queryZedEditorContents(dbPath, row)
  const text =
    contents.type === "contents" && contents.contents != null
      ? contents.contents
      : await readFileAsync(row.buffer_path, "utf8").catch(() => undefined)
  if (text == null) return { type: "unavailable" }

  const ranges = byteRanges.map((range) => {
    const startOffset = utf8ByteOffsetToStringIndex(text, range.start)
    const endOffset = utf8ByteOffsetToStringIndex(text, range.end)
    return {
      text: text.slice(startOffset, endOffset),
      selection: offsetsToSelection(text, startOffset, endOffset),
    }
  })

  return {
    type: "selection",
    selection: {
      filePath: row.buffer_path,
      source: "zed",
      ranges,
    },
  }
}

function queryZedActiveEditor(dbPath: string, cwd: string) {
  let db: Database | undefined
  try {
    db = new Database(dbPath, { readonly: true })
    const raw = db
      .query(
        `select
          i.kind as item_kind,
          e.item_id as editor_id,
          i.workspace_id as workspace_id,
          w.paths as workspace_paths,
          w.timestamp as timestamp,
          e.buffer_path as buffer_path
        from items i
        join panes p on p.pane_id = i.pane_id and p.workspace_id = i.workspace_id
        join workspaces w on w.workspace_id = i.workspace_id
        left join editors e on e.item_id = i.item_id and e.workspace_id = i.workspace_id
        where i.active = 1 and p.active = 1
        order by w.timestamp desc`,
      )
      .all()

    const rows = raw.flatMap((row) => {
      const parsed = decodeZedEditorRow(row)
      return Option.isSome(parsed) ? [parsed.value] : []
    })

    if (raw.length > 0 && rows.length === 0) return { type: "unavailable" as const }

    const row = rows
      .map((row) => ({ row, score: scoreZedWorkspace(row.workspace_paths, cwd) }))
      .filter((entry) => entry.score > 0)
      .sort((left, right) => right.score - left.score || right.row.timestamp.localeCompare(left.row.timestamp))[0]?.row
    if (!row) return { type: "empty" as const }
    if (row.item_kind !== "Editor") return { type: "unavailable" as const }
    if (!isZedActiveEditorRow(row)) return { type: "empty" as const }
    return { type: "row" as const, row }
  } catch {
    return { type: "unavailable" as const }
  } finally {
    db?.close()
  }
}

function queryZedEditorSelections(dbPath: string, row: ZedActiveEditorRow) {
  let db: Database | undefined
  try {
    db = new Database(dbPath, { readonly: true })
    const raw = db
      .query(
        `select
          start as selection_start,
          end as selection_end
        from editor_selections
        where editor_id = $editorID and workspace_id = $workspaceID`,
      )
      .all({ $editorID: row.editor_id, $workspaceID: row.workspace_id })

    const selections = raw.flatMap((selection) => {
      const parsed = decodeZedSelectionRow(selection)
      return Option.isSome(parsed) ? [parsed.value] : []
    })

    if (raw.length > 0 && selections.length === 0) return { type: "unavailable" as const }
    return { type: "selections" as const, selections }
  } catch {
    return { type: "unavailable" as const }
  } finally {
    db?.close()
  }
}

function queryZedEditorContents(dbPath: string, row: ZedActiveEditorRow) {
  let db: Database | undefined
  try {
    db = new Database(dbPath, { readonly: true })
    const parsed = decodeZedEditorContents(
      db
        .query(
          `select contents
        from editors
        where item_id = $editorID and workspace_id = $workspaceID`,
        )
        .get({ $editorID: row.editor_id, $workspaceID: row.workspace_id }),
    )
    if (Option.isNone(parsed)) return { type: "unavailable" as const }
    return { type: "contents" as const, contents: parsed.value.contents }
  } catch {
    return { type: "unavailable" as const }
  } finally {
    db?.close()
  }
}

function isZedActiveEditorRow(row: ZedEditorRow): row is ZedActiveEditorRow {
  return row.item_kind === "Editor" && row.editor_id != null
}

export function resolveZedDbPath() {
  const candidates = [
    process.env.OPENCODE_ZED_DB,
    path.join(os.homedir(), "Library", "Application Support", "Zed", "db", "0-stable", "db.sqlite"),
    path.join(os.homedir(), ".local", "share", "zed", "db", "0-stable", "db.sqlite"),
  ].filter((item): item is string => Boolean(item))

  return candidates.find((item) => isFile(item))
}

function isFile(item: string) {
  try {
    return statSync(item).isFile()
  } catch {
    return false
  }
}

function scoreZedWorkspace(workspacePaths: string | null, cwd: string) {
  return zedWorkspacePaths(workspacePaths).reduce((score, item) => {
    if (pathContains(item, cwd)) return Math.max(score, path.resolve(item).length)
    return score
  }, 0)
}

function zedWorkspacePaths(value: string | null) {
  if (!value) return []
  const parsed = parseJson(value)
  if (Array.isArray(parsed)) return parsed.filter((item): item is string => typeof item === "string")
  return value.split(/\r?\n/).filter(Boolean)
}

function utf8ByteOffsetToStringIndex(text: string, byteOffset: number) {
  if (byteOffset <= 0) return 0

  let bytes = 0
  for (let index = 0; index < text.length; ) {
    const codePoint = text.codePointAt(index)
    if (codePoint === undefined) return text.length

    const nextIndex = index + (codePoint > 0xffff ? 2 : 1)
    bytes += utf8.encode(text.slice(index, nextIndex)).length
    if (bytes >= byteOffset) return nextIndex
    index = nextIndex
  }

  return text.length
}

function offsetsToSelection(text: string, startOffset: number, endOffset: number) {
  const start = Math.max(0, Math.min(startOffset, text.length))
  const end = Math.max(0, Math.min(endOffset, text.length))
  let line = 1
  let lineStart = 0
  let startPosition = position(line, lineStart, start)
  let endPosition = position(line, lineStart, end)

  for (let index = 0; index <= end; index++) {
    if (index === start) startPosition = position(line, lineStart, index)
    if (index === end) {
      endPosition = position(line, lineStart, index)
      break
    }
    if (text[index] === "\n") {
      line += 1
      lineStart = index + 1
    }
  }

  return { start: startPosition, end: endPosition }
}

function position(line: number, lineStart: number, offset: number) {
  return {
    line,
    character: offset - lineStart + 1,
  }
}

function pathContains(parent: string, child: string) {
  const relative = path.relative(path.resolve(parent), path.resolve(child))
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative))
}

function parseJson(value: string) {
  try {
    return JSON.parse(value) as unknown
  } catch {
    return
  }
}

import type { CliRenderer } from "@opentui/core"
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs"
import { readFile, rm, writeFile } from "node:fs/promises"
import os from "node:os"
import path from "node:path"
import { spawn } from "node:child_process"
import type { Stream } from "node:stream"
import { resolveZedDbPath, resolveZedSelection } from "./editor-zed"

export { normalizePromptContent } from "./prompt/content"

type EditorStdio = "inherit" | "pipe" | "ignore" | number | Stream

export async function openEditor(input: { value: string; renderer: CliRenderer; cwd?: string; stdin?: EditorStdio }) {
  const editor = process.env.VISUAL || process.env.EDITOR
  if (!editor) throw new Error("Set $VISUAL or $EDITOR to open an external editor")
  const file = path.join(os.tmpdir(), `${Date.now()}.md`)
  await writeFile(file, input.value)
  input.renderer.suspend()
  input.renderer.currentRenderBuffer.clear()
  try {
    await new Promise<void>((resolve, reject) => {
      const parts = editor.split(" ")
      const child = spawn(parts[0]!, [...parts.slice(1), file], {
        cwd: input.cwd && existsSync(input.cwd) ? input.cwd : process.cwd(),
        stdio: [input.stdin ?? "inherit", "inherit", "inherit"],
        shell: process.platform === "win32",
      })
      child.on("error", reject)
      child.on("exit", (code, signal) => {
        if (code === 0) return resolve()
        reject(new Error(`Editor exited with ${signal ? `signal ${signal}` : `code ${code}`}`))
      })
    })
    return (await readFile(file, "utf8")) || undefined
  } finally {
    await rm(file, { force: true }).catch(() => {})
    input.renderer.currentRenderBuffer.clear()
    input.renderer.resume()
    input.renderer.requestRender()
  }
}

export function discoverEditorConnection(directory: string) {
  const root = path.join(os.homedir(), ".claude", "ide")
  const contains = (parent: string) => {
    const resolved = path.resolve(parent)
    const relative = path.relative(resolved, path.resolve(directory))
    return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative)) ? resolved.length : 0
  }
  try {
    return readdirSync(root)
      .filter((entry) => entry.endsWith(".lock"))
      .flatMap((entry) => {
        const file = path.join(root, entry)
        const port = Number.parseInt(path.basename(file, ".lock"), 10)
        if (!Number.isInteger(port) || port <= 0 || port > 65535) return []
        try {
          const value = JSON.parse(readFileSync(file, "utf8")) as Record<string, unknown>
          if (value.transport !== undefined && value.transport !== "ws") return []
          const folders = Array.isArray(value.workspaceFolders)
            ? value.workspaceFolders.filter((item): item is string => typeof item === "string")
            : []
          const score = Math.max(0, ...folders.map(contains))
          if (!score) return []
          return [
            {
              url: `ws://127.0.0.1:${port}`,
              authToken: typeof value.authToken === "string" ? value.authToken : undefined,
              source: `lock:${port}`,
              score,
              mtime: statSync(file).mtimeMs,
            },
          ]
        } catch {
          return []
        }
      })
      .sort((left, right) => right.score - left.score || right.mtime - left.mtime)
      .map(({ url, authToken, source }) => ({ url, authToken, source }))[0]
  } catch {
    return undefined
  }
}

export const editorIntegration = {
  connection: discoverEditorConnection,
  selection: (directory: string) => resolveZedSelection(resolveZedDbPath() ?? "", directory),
}

