import { Plugin } from "@opencode/plugin/tui"
import { TextAttributes, type ScrollBoxRenderable } from "@opentui/core"
import { useKeyboard, useTerminalDimensions } from "@opentui/solid"
import { createMemo, createSignal, Show } from "solid-js"
import { Spinner } from "../../component/spinner"
import { useConfig } from "../../config"
import { useClipboard } from "../../context/clipboard"
import { Keymap } from "../../context/keymap"
import { useTheme, useThemes } from "../../context/theme"
import { usePlugin } from "../../plugin/context"
import { DIALOG_INSET, DialogBleed, DialogFooter, DialogHeader, DialogLayout } from "../../ui/dialog"
import { useToast } from "../../ui/toast"
import { getScrollAcceleration } from "../../util/scroll"

// session.generate exposes the session's tools but runs no tool loop, so a
// tool call would surface as an empty answer.
const instructions = [
  "The user is asking a quick side question about the conversation so far.",
  "Answer directly and concisely in markdown from what you already know.",
  "Do not call any tools and do not take any actions.",
].join(" ")

export default Plugin.define({
  id: "opencode.btw",
  setup(context) {
    const [pending, setPending] = createSignal(0)

    context.ui.slot({
      append: "prompt.footer.status",
      render: () => {
        const theme = useTheme()
        return (
          <Show when={pending() > 0}>
            <box flexShrink={0}>
              <Spinner color={theme.hue.interactive[200]}>/btw</Spinner>
            </box>
          </Show>
        )
      },
    })

    context.ui.slot({
      append: "app",
      render() {
        const toast = useToast()
        // Dialogs render beside PluginProvider, so Answer cannot call usePlugin().
        const plugins = usePlugin()
        context.keymap.layer(() => ({
          mode: "global",
          commands: [
            {
              id: "session.aside",
              title: "Ask a side question",
              description: "One-shot answer from the session's context without adding to the conversation",
              group: "Session",
              palette: true,
              slash: { name: "btw", arguments: true },
              async run(input) {
                const route = context.ui.router.current()
                if (route.type !== "session") {
                  toast.show({ message: "Open a session first", variant: "warning" })
                  return
                }
                const question =
                  input?.trim() || (await context.ui.dialog.prompt({ title: "/btw", placeholder: "Ask anything" }))
                if (!question) return
                setPending((count) => count + 1)
                await context.client.session
                  .generate({ sessionID: route.sessionID, prompt: [instructions, question].join("\n\n") })
                  .then((result) => {
                    context.ui.dialog.show(() => (
                      <Answer question={question} answer={result.text.trim()} markdown={plugins.markdown} />
                    ))
                    context.ui.dialog.set({ size: "large", centered: true })
                  })
                  .catch((cause: unknown) => toast.error(cause))
                  .finally(() => setPending((count) => count - 1))
              },
            },
          ],
        }))
        return null
      },
    })
  },
})

export function Answer(props: {
  question: string
  answer: string
  markdown: ReturnType<typeof usePlugin>["markdown"]
}) {
  const toast = useToast()
  const clipboard = useClipboard()
  const theme = useTheme().surface("dialog")
  const overlay = useTheme()
  const syntax = useThemes().currentSyntax
  const config = useConfig().data
  const dimensions = useTerminalDimensions()
  const maxHeight = createMemo(() => Math.max(8, Math.floor(dimensions().height * 0.6)))
  const [copied, setCopied] = createSignal(false)
  let scroll: ScrollBoxRenderable | undefined

  const copy = () => {
    void clipboard
      .write(props.answer)
      .then(() => setCopied(true))
      .catch(toast.error)
  }

  Keymap.createLayer(() => ({
    mode: "modal",
    commands: [{ bind: "c", title: "Copy answer", group: "Dialog", run: copy }],
  }))

  useKeyboard((event) => {
    if (!scroll) return
    if (event.name === "up" || event.name === "k") return scroll.scrollBy(-1)
    if (event.name === "down" || event.name === "j") return scroll.scrollBy(1)
    if (event.name === "pageup") return scroll.scrollBy(-maxHeight())
    if (event.name === "pagedown") return scroll.scrollBy(maxHeight())
    if (event.name === "home") return scroll.scrollTo(0)
    if (event.name === "end") return scroll.scrollTo(scroll.scrollHeight)
  })

  return (
    <DialogLayout
      header={
        <DialogHeader
          gap={2}
          titleView={
            <text attributes={TextAttributes.BOLD} fg={theme.text.base} flexShrink={0}>
              /btw
            </text>
          }
        >
          <text fg={theme.text.muted} wrapMode="none" flexGrow={1} truncate>
            {props.question.replace(/\s+/g, " ")}
          </text>
        </DialogHeader>
      }
      footer={{
        actions: {
          primary: [
            copied()
              ? { title: "✓ copied", color: theme.text.feedback.success.base, onTrigger: copy }
              : { title: "copy response", key: "c", onTrigger: copy },
          ],
        },
      }}
      legacyFooter={
        <DialogFooter
          actions={{
            secondary: [
              copied()
                ? { title: "✓ copied", color: theme.text.feedback.success.base, onTrigger: copy }
                : { title: "copy", key: "c", onTrigger: copy },
              { title: "scroll", key: "j/k ↑/↓" },
            ],
          }}
        />
      }
    >
      <DialogBleed>
        <scrollbox
          ref={(element: ScrollBoxRenderable) => (scroll = element)}
          maxHeight={maxHeight()}
          contentOptions={{ minHeight: 0 }}
          backgroundColor={overlay.background.raised.high}
          scrollbarOptions={{ visible: false }}
          scrollAcceleration={getScrollAcceleration(config)}
        >
          <box paddingLeft={DIALOG_INSET} paddingRight={DIALOG_INSET} paddingTop={1} paddingBottom={1}>
            <markdown
              syntaxStyle={syntax()}
              renderNode={props.markdown()}
              content={props.answer}
              conceal
              internalBlockMode="top-level"
              tableOptions={{ style: "grid", cellPaddingX: 1 }}
              fg={overlay.markdown.text}
              bg={overlay.background.raised.high}
            />
          </box>
        </scrollbox>
      </DialogBleed>
    </DialogLayout>
  )
}

import { Plugin } from "@opencode/plugin/tui"
import { createMemo, createSignal, Match, Show, Switch } from "solid-js"
import { contextUsage, formatContextUsage } from "../../util/session"
import { useTerminalDimensions } from "@opentui/solid"
import { TextAttributes } from "@opentui/core"
import { useInteractivity } from "../../context/interactivity"
import { stringWidth } from "../../util/string-width"

const money = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
})

export function PromptFooter(props: {
  context: Plugin.Context
  sessionID?: string
  mode: "normal" | "shell"
  showDetails: boolean
}) {
  const dimensions = useTerminalDimensions()
  const [liveHovered, setLiveHovered] = createSignal(false)
  const subagents = createMemo(() => {
    if (!props.sessionID) return 0
    const count = props.context.data.session
      .family(props.sessionID)
      .filter((id) => id !== props.sessionID && props.context.data.session.status(id) === "running").length
    return count ? `${count} subagent${count === 1 ? "" : "s"}` : undefined
  })
  const shells = createMemo(() => {
    if (!props.sessionID) return 0
    const count = props.context.data.shell
      .list(props.context.location)
      .filter((shell) => shell.metadata.sessionID === props.sessionID).length
    return count ? `${count} shell${count === 1 ? "" : "s"}` : undefined
  })
  const status = createMemo(() => {
    if (!props.sessionID) return []
    const session = props.context.data.session.get(props.sessionID)
    if (!session) return []
    const usage = contextUsage(
      props.context.data.session.message.list(props.sessionID),
      props.context.data.location.model.list(session.location),
      session.revert?.messageID,
    )
    const cost = props.context.data.session.cost(props.sessionID)
    return [
      usage ? formatContextUsage(usage.tokens, usage.percent) : undefined,
      cost > 0 ? money.format(cost) : undefined,
    ].filter((item): item is string => Boolean(item))
  })
  const live = createMemo(() => Boolean(subagents() || shells()))
  // Prompt hints read as disabled while the session does not own input, e.g. while a side panel is focused.
  const interactive = useInteractivity()
  const shortcut = (id: string) => props.context.keymap.shortcuts(id)[0]
  const layout = createMemo(() => {
    const command = shortcut("command.palette.show")
    if (status().length === 0) return { usage: false, shortcuts: dimensions().width >= 44 }
    return promptFooterLayout({
      width: Math.max(0, dimensions().width - 8),
      usage: status(),
      shortcuts: command ? [`${command} commands`] : [],
    })
  })

  return (
    <Switch>
      <Match when={props.mode === "normal"}>
        <Switch>
          <Match when={live() || status().length > 0}>
            <box flexDirection="row" flexShrink={props.showDetails && layout().usage ? 0 : 1} minWidth={0}>
              <Show when={live()}>
                <box
                  flexShrink={0}
                  onMouseOver={() => setLiveHovered(true)}
                  onMouseOut={() => setLiveHovered(false)}
                  onMouseUp={() => props.context.keymap.dispatch("session.child.first")}
                >
                  <text
                    fg={liveHovered() ? props.context.theme.text.base : props.context.theme.text.muted}
                    wrapMode="none"
                  >
                    <Show when={shortcut("session.child.first")}>
                      {(value) => <span style={{ fg: props.context.theme.text.base }}>{value()} </span>}
                    </Show>
                    <Show when={subagents()}>{(value) => <>{value()}</>}</Show>
                    <Show when={subagents() && shells()}> · </Show>
                    <Show when={shells()}>{(value) => <>{value()}</>}</Show>
                  </text>
                </box>
              </Show>
              <Show when={props.showDetails && layout().usage && status().length > 0}>
                <text fg={props.context.theme.text.muted} wrapMode="none" flexShrink={0}>
                  <Show when={live()}> · </Show>
                  {status().join(" · ")}
                </text>
              </Show>
            </box>
          </Match>
          <Match when={props.showDetails && layout().shortcuts}>
            <text
              fg={interactive() ? props.context.theme.text.base : props.context.theme.text.action.primary.disabled}
              attributes={interactive() ? 0 : TextAttributes.DIM}
              flexShrink={0}
            >
              {shortcut("agent.cycle")}{" "}
              <span style={interactive() ? { fg: props.context.theme.text.muted } : {}}>agents</span>
            </text>
          </Match>
        </Switch>
        <Show when={props.showDetails && layout().shortcuts}>
          <text
            fg={interactive() ? props.context.theme.text.base : props.context.theme.text.action.primary.disabled}
            attributes={interactive() ? 0 : TextAttributes.DIM}
            wrapMode="none"
            flexShrink={0}
          >
            {shortcut("command.palette.show")}{" "}
            <span style={interactive() ? { fg: props.context.theme.text.muted } : {}}>commands</span>
          </text>
        </Show>
      </Match>
      <Match when={props.mode === "shell"}>
        <text fg={props.context.theme.text.base} flexShrink={0}>
          esc{" "}
          <span style={{ fg: props.context.theme.text.muted }}>
            {dimensions().width < 44 ? "shell" : "exit shell mode"}
          </span>
        </text>
      </Match>
    </Switch>
  )
}

export default Plugin.define({
  id: "opencode.prompt.footer",
  setup(context) {
    context.ui.slot({
      append: "prompt.footer",
      render: (props) => (
        <PromptFooter context={context} sessionID={props.sessionID} mode={props.mode} showDetails={props.showDetails} />
      ),
    })
  },
})

function promptFooterLayout(input: { width: number; usage: string[]; shortcuts: string[] }) {
  const usage = input.usage.join(" · ")
  const shortcuts = input.shortcuts.join(" · ")
  const available = Math.max(0, input.width - Math.min(28, Math.floor(input.width / 2)))
  if (usage && shortcuts && stringWidth(`${usage} · ${shortcuts}`) <= available) {
    return { usage: true, shortcuts: true }
  }
  if (usage && stringWidth(usage) <= available) return { usage: true, shortcuts: false }
  if (!usage && shortcuts && stringWidth(shortcuts) <= available) return { usage: false, shortcuts: true }
  return { usage: false, shortcuts: false }
}

