import { Plugin } from "@opencode/plugin/tui"
import { useTerminalDimensions } from "@opentui/solid"
import { createSignal, For, type JSX } from "solid-js"
import { StoryFooter } from "./footer"
import { mermanLayoutsStory } from "./merman-layouts"
import { sessionTabsStory } from "./session-tabs"
import { sessionLocationMissingStory } from "./session-location-missing"
import { oneCellSpinnerStory } from "./one-cell-spinner"
import { linkClicksStory } from "./link-clicks"
import { highlightsStory } from "./highlights"

/**
 * A story is a full-screen, fixture-driven simulation of a real production component. Stories own
 * their entire screen (including any footer) and should bind escape back to the storybook index.
 */
export type Story = {
  id: string
  title: string
  render: (context: Plugin.Context) => JSX.Element
}

const stories: Story[] = [
  mermanLayoutsStory,
  sessionTabsStory,
  sessionLocationMissingStory,
  oneCellSpinnerStory,
  linkClicksStory,
  highlightsStory,
]

function Commands(props: { context: Plugin.Context }) {
  props.context.keymap.layer(() => ({
    mode: "global",
    commands: [
      {
        id: "app.storybook",
        title: "Open storybook",
        group: "Debug",
        palette: true,
        run() {
          props.context.ui.router.navigate({ type: "plugin", name: "storybook" })
          props.context.ui.dialog.clear()
        },
      },
      ...stories.map((story) => ({
        id: `app.storybook.${story.id}`,
        title: `Storybook: ${story.title}`,
        group: "Debug",
        palette: true as const,
        run() {
          props.context.ui.router.navigate({ type: "plugin", name: "storybook", data: { story: story.id } })
          props.context.ui.dialog.clear()
        },
      })),
    ],
  }))
  return null
}

function StorybookIndex(props: { context: Plugin.Context }) {
  const dimensions = useTerminalDimensions()
  const theme = props.context.theme
  const [selected, setSelected] = createSignal(0)
  const open = (story: Story) =>
    props.context.ui.router.navigate({ type: "plugin", name: "storybook", data: { story: story.id } })

  props.context.keymap.layer(() => ({
    commands: [
      {
        bind: "escape",
        title: "Back home",
        group: "Storybook",
        run() {
          props.context.ui.router.navigate({ type: "home" })
        },
      },
      {
        bind: "up,k",
        title: "Previous story",
        group: "Storybook",
        run: () => setSelected((current) => (current + stories.length - 1) % stories.length),
      },
      {
        bind: "down,j",
        title: "Next story",
        group: "Storybook",
        run: () => setSelected((current) => (current + 1) % stories.length),
      },
      {
        bind: "return",
        title: "Open story",
        group: "Storybook",
        run: () => open(stories[selected()]),
      },
      ...stories.map((story, index) => ({
        bind: String(index + 1),
        title: `Open ${story.title}`,
        group: "Storybook",
        run: () => open(story),
      })),
    ],
  }))

  return (
    <box
      width={dimensions().width}
      height={dimensions().height}
      flexDirection="column"
      backgroundColor={theme.background.base}
    >
      <box paddingTop={2} paddingLeft={2} flexDirection="column">
        <text fg={theme.text.base}>storybook</text>
        <text fg={theme.text.muted}>fixture-driven simulations of production components</text>
        <box height={1} />
        <For each={stories}>
          {(story, index) => (
            <text fg={index() === selected() ? theme.text.base : theme.text.muted}>
              {index() === selected() ? "› " : "  "}
              {index() + 1} {story.title}
            </text>
          )}
        </For>
      </box>
      <box flexGrow={1} />
      <StoryFooter
        context={props.context}
        title="storybook"
        controls={[
          { shortcut: "↑/↓", label: "select" },
          { shortcut: "enter", label: "open" },
          { shortcut: "esc", label: "home" },
        ]}
      />
    </box>
  )
