      },
      {
        bind: "left,k",
        title: "Previous fixture",
        group: "Storybook",
        run: () => move(-1),
      },
      {
        bind: "right,j",
        title: "Next fixture",
        group: "Storybook",
        run: () => move(1),
      },
      {
        bind: "r",
        title: "Reset fixture",
