export function RunSettingsBody(props: {
  theme: Accessor<RunFooterTheme>
  settings: Accessor<MiniSettings>
  onClose: () => void
  onChange: (change: MiniSettingChange) => void | Promise<void>
  mono?: boolean
  animations?: boolean
}) {
  const [saving, setSaving] = createSignal<SettingEntry["key"]>()
  const entries = createMemo<SettingEntry[]>(() => [
    {
      category: "Transcript",
      display: "Verbosity",
      footer: saving() === "verbosity" ? "saving" : verbosityLabel(matchMiniVerbosity(props.settings())),
      footerTone: saving() === "verbosity" ? "running" : "selection",
      keywords: `verbosity quiet default everything custom noise ${verbosityLabel(matchMiniVerbosity(props.settings()))}`,
      key: "verbosity",
    },
    {
      category: "Transcript",
      display: "Thinking",
      footer: saving() === "thinking" ? "saving" : props.settings().thinking,
      footerTone: saving() === "thinking" ? "running" : "selection",
      keywords: `thinking reasoning ${props.settings().thinking}`,
      key: "thinking",
    },
    {
      category: "Transcript",
      display: "Tools",
      footer: saving() === "tools" ? "saving" : props.settings().tools,
      footerTone: saving() === "tools" ? "running" : "selection",
      keywords: `tools files skills activity work steps intermediate ${props.settings().tools}`,
      key: "tools",
    },
    {
      category: "Transcript",
      display: "Shell",
      footer: saving() === "shell_output" ? "saving" : props.settings().shell_output,
      footerTone: saving() === "shell_output" ? "running" : "selection",
      keywords: `shell tool command output ${props.settings().shell_output}`,
      key: "shell_output",
    },
    {
      category: "Transcript",
      display: "Turn summary",
      footer: saving() === "turn_summary" ? "saving" : props.settings().turn_summary,
      footerTone: saving() === "turn_summary" ? "running" : "selection",
      keywords: `turn summary agent model duration ${props.settings().turn_summary}`,
      key: "turn_summary",
    },
    {
      category: "Terminal",
      display: "Footer details",
      footer: saving() === "footer" ? "saving" : props.settings().footer,
      footerTone: saving() === "footer" ? "running" : "selection",
      keywords: `footer status activity model context usage ${props.settings().footer}`,
      key: "footer",
    },
    {
      category: "Terminal",
      display: "Splash",
      footer: saving() === "splash" ? "saving" : props.settings().splash,
      footerTone: saving() === "splash" ? "running" : "selection",
      keywords: `splash entry exit banner ${props.settings().splash}`,
      key: "splash",
    },
    {
      category: "Terminal",
      display: "Monochrome UI",
      footer: saving() === "mono" ? "saving" : props.settings().mono ? "on" : "off",
      footerTone: saving() === "mono" ? "running" : "selection",
      keywords: `mono monochrome ascii legacy compat terminal ${props.settings().mono ? "on" : "off"}`,
      key: "mono",
    },
    {
      category: "Terminal",
      display: "Work spinner",
      icon: (color) => (
        <OneCellSpinner
          animation={props.mono ? SEED_MONO : WORK_SPINNERS[props.settings().work_spinner]}
          color={color}
          animations={props.animations}
          glow={!props.mono}
          still={props.mono ? "*" : undefined}
        />
      ),
      footer:
        saving() === "work_spinner"
          ? "saving"
          : props.settings().work_spinner.replace("block-", "").replaceAll("-", " "),
      footerTone: saving() === "work_spinner" ? "running" : "selection",
      keywords: `work spinner animation ${props.settings().work_spinner}`,
      key: "work_spinner",
    },
  ])
  const change = (item: SettingEntry, direction = 1) => {
    if (saving()) return
    const spinners = Config.MiniWorkSpinner.literals
    const next: MiniSettingChange | undefined =
      item.key === "verbosity"
        ? verbosityChange(props.settings(), direction < 0 ? -1 : 1)
        : item.key === "work_spinner"
          ? {
              key: "work_spinner",
              value:
                spinners[
                  (spinners.indexOf(props.settings().work_spinner) + direction + spinners.length) % spinners.length
                ]!,
            }
          : item.key === "mono"
            ? { key: "mono", value: !props.settings().mono }
            : { key: item.key, value: props.settings()[item.key] === "show" ? "hide" : "show" }
    if (!next) return
    setSaving(item.key)
    void Promise.resolve(props.onChange(next))
      .catch(() => {})
      .finally(() => setSaving())
  }
  const controller = createSearchablePanelController({
    entries,
    limit: PANEL_LIST_ROWS,
    onClose: props.onClose,
    onSelect: change,
    onKey(event, item) {
      const name = event.name.toLowerCase()
      if (name !== "left" && name !== "right") return false
      event.preventDefault()
      if (item) change(item, name === "left" ? -1 : 1)
      return true
    },
  })

  return (
    <PanelShell
      title="Settings"
      layout={controller.layout()}
      countVisible={false}
      query={controller.query()}
      count={controller.items().length}
      total={entries().length}
      placeholder="Search"
      theme={props.theme}
      inputRef={controller.inputRef}
      onQuery={controller.setQuery}
      hint="left/right change"
      mono={props.mono}
    >
      <RunFooterMenu
        theme={props.theme}
        items={controller.items}
        selected={controller.menu.selected}
        offset={controller.menu.offset}
        rows={controller.menu.limit}
        limit={controller.menu.limit()}
        compact={controller.layout().compact}
        empty="No settings found"
        border={false}
        paddingLeft={panelPad(props.mono)}
        paddingRight={panelPad(props.mono)}
        grouped={!controller.query().trim()}
        background
        headerColor={props.theme().muted}
        mono={props.mono}
      />
    </PanelShell>
  )
}

export function RunSubagentSelectBody(props: {
  theme: Accessor<RunFooterTheme>
  tabs: Accessor<FooterSubagentTab[]>
  current: Accessor<string | undefined>
  onClose: () => void
  onSelect: (sessionID: string) => void
  onRows?: (rows: number) => void
  mono?: boolean
}) {
  const [active, setActive] = createSignal(true)
  const entries = createMemo<SubagentEntry[]>(() =>
    props
      .tabs()
      .filter((item) => (active() ? item.status === "running" : item.status !== "running"))
      .map((item) => {
        const title = item.description || item.title || item.label
        return {
          category: "",
          display: title,
          description: title === item.label ? undefined : item.label,
          footer: subagentStatusLabel(item.status),
          footerTone:
            item.status === "running" || item.status === "error"
              ? item.status
              : item.status === "completed"
                ? ("success" as const)
                : undefined,
          keywords: `${item.label} ${item.description} ${item.title ?? ""} ${item.status}`,
          sessionID: item.sessionID,
          current: props.current() === item.sessionID,
        }
      }),
  )
  const controller = createSearchablePanelController({
    entries,
    limit: SUBAGENT_LIST_ROWS,
    onClose: props.onClose,
    onSelect: (item) => props.onSelect(item.sessionID),
    isCurrent: (item) => item.current,
    closeOnFirstUp: true,
    onKey(event) {
      if (event.name.toLowerCase() !== "tab") return false
      event.preventDefault()
      setActive((value) => !value)
      return true
    },
    onRows: props.onRows,
  })

  return (
    <PanelShell
      title="Select subagent"
      layout={controller.layout()}
      query={controller.query()}
      count={controller.items().length}
      total={entries().length}
      placeholder="Search"
      theme={props.theme}
      inputRef={controller.inputRef}
      onQuery={controller.setQuery}
      hint={`tab show ${active() ? "inactive" : "active"}`}
      mono={props.mono}
    >
      <RunFooterMenu
        theme={props.theme}
        items={controller.items}
        selected={controller.menu.selected}
        offset={controller.menu.offset}
        rows={controller.menu.rows}
        limit={controller.menu.limit()}
        compact={controller.layout().compact}
        empty="No subagents found"
        border={false}
        paddingLeft={panelPad(props.mono)}
        paddingRight={panelPad(props.mono)}
        grouped={false}
        background
        mono={props.mono}
      />
    </PanelShell>
  )
}

export function RunQueuedPromptSelectBody(props: {
  theme: Accessor<RunFooterTheme>
  prompts: Accessor<FooterQueuedPrompt[]>
  onClose: () => void
  onSelect: (prompt: FooterQueuedPrompt) => void
  onUndo: (prompt: FooterQueuedPrompt) => void
  onDelete: (prompt: FooterQueuedPrompt) => void
  onRows?: (rows: number) => void
  mono?: boolean
}) {
  const entries = createMemo<QueuedPromptEntry[]>(() =>
    props.prompts().map((prompt) => ({
      category: "",
      display: prompt.prompt.text.replaceAll("\n", " "),
      footer: prompt.delivery === "queue" ? "queued" : "steering",
      keywords: prompt.prompt.text,
      prompt,
    })),
  )
  const controller = createSearchablePanelController({
    entries,
    limit: SUBAGENT_LIST_ROWS,
    onClose: props.onClose,
    onSelect: (item) => props.onSelect(item.prompt),
    onRows: props.onRows,
  })
  const shortcuts = Keymap.useShortcuts()
  const undoShortcut = () => monoShortcut(shortcuts.get("queued_prompt.undo") ?? "", props.mono ?? false)
  const deleteShortcut = () => monoShortcut(shortcuts.get("queued_prompt.delete") ?? "", props.mono ?? false)
  Keymap.createLayer(() => ({
    priority: 1,
    commands: [
      {
        id: "queued_prompt.undo",
        title: "Undo",
        group: "Prompt",
        run() {
          const item = controller.items()[controller.menu.selected()]
          if (!item) return false
          props.onUndo(item.prompt)
        },
      },
      {
        id: "queued_prompt.delete",
        title: "Delete pending prompt",
        group: "Prompt",
        run() {
          const item = controller.items()[controller.menu.selected()]
          if (!item) return false
          props.onDelete(item.prompt)
        },
      },
    ],
  }))

  return (
    <PanelShell
      title="Pending prompts"
      layout={controller.layout()}
      query={controller.query()}
      count={controller.items().length}
      total={entries().length}
      placeholder="Search"
      theme={props.theme}
      inputRef={controller.inputRef}
      onQuery={controller.setQuery}
      hint={[
        controller.items()[controller.menu.selected()]?.prompt.delivery === "steer" ? "enter queue" : "enter steer",
        deleteShortcut() ? `${deleteShortcut()} delete` : undefined,
        undoShortcut() ? `${undoShortcut()} undo` : undefined,
      ]
        .filter(Boolean)
        .join(" · ")}
      mono={props.mono}
    >
      <RunFooterMenu
        theme={props.theme}
        items={controller.items}
        selected={controller.menu.selected}
        offset={controller.menu.offset}
        rows={controller.menu.rows}
        limit={controller.menu.limit()}
        compact={controller.layout().compact}
        empty="No pending prompts"
        border={false}
        paddingLeft={panelPad(props.mono)}
        paddingRight={panelPad(props.mono)}
        grouped={false}
        background
        mono={props.mono}
      />
    </PanelShell>
  )
}

export function RunVariantSelectBody(props: {
  theme: Accessor<RunFooterTheme>
  variants: Accessor<string[]>
  current: Accessor<string | undefined>
  onClose: () => void
  onSelect: (variant: string | undefined) => void
  mono?: boolean
}) {
  const entries = createMemo<VariantEntry[]>(() => [
    {
      category: "",
      display: "Default",
      footer: props.current() === undefined ? "current" : undefined,
      footerTone: "selection",
      keywords: "default",
      variant: undefined,
      current: props.current() === undefined,
    },
    ...props.variants().map((variant) => ({
      category: "",
      display: variant,
      footer: props.current() === variant ? "current" : undefined,
      footerTone: "selection" as const,
      keywords: variant,
      variant,
      current: props.current() === variant,
    })),
  ])
  const controller = createSearchablePanelController({
    entries,
    limit: PANEL_LIST_ROWS,
    onClose: props.onClose,
    onSelect: (item) => props.onSelect(item.variant),
    isCurrent: (item) => item.current,
  })

  return (
    <PanelShell
      title="Select variant"
      layout={controller.layout()}
      query={controller.query()}
      count={controller.items().length}
      total={entries().length}
      placeholder="Search"
      theme={props.theme}
      inputRef={controller.inputRef}
      onQuery={controller.setQuery}
      mono={props.mono}
    >
      <RunFooterMenu
        theme={props.theme}
        items={controller.items}
        selected={controller.menu.selected}
        offset={controller.menu.offset}
        rows={controller.menu.limit}
        limit={controller.menu.limit()}
        compact={controller.layout().compact}
        empty="No results found"
        border={false}
        paddingLeft={panelPad(props.mono)}
        paddingRight={panelPad(props.mono)}
        grouped={false}
        background
        mono={props.mono}
      />
    </PanelShell>
  )
}

export function RunModelSelectBody(props: {
  theme: Accessor<RunFooterTheme>
  providers: Accessor<RunProvider[] | undefined>
  current: Accessor<RunInput["model"]>
  onClose: () => void
  onSelect: (model: NonNullable<RunInput["model"]>) => void
  mono?: boolean
}) {
  const entries = createMemo<ModelEntry[]>(() =>
    (props.providers() ?? [])
      .flatMap((provider) =>
        Object.entries(provider.models)
          .filter(([, model]) => model.status !== "deprecated")
          .map(([modelID, model]) => {
            const title = model.name ?? modelID
            const current = props.current()?.providerID === provider.id && props.current()?.modelID === modelID
            const footer = current
              ? "current"
              : model.cost?.input === 0 && provider.id === "opencode"
                ? "Free"
                : title !== modelID
                  ? modelID
                  : undefined
            return {
              providerID: provider.id,
              modelID,
              providerName: provider.name,
              category: provider.name,
              display: title,
              footer,
              footerTone: current ? ("selection" as const) : undefined,
              keywords: `${provider.id} ${provider.name} ${modelID} ${title} ${footer ?? ""}`,
              current,
            }
          }),
      )
      .sort((a, b) => {
        const provider = Number(a.providerID !== "opencode") - Number(b.providerID !== "opencode")
        if (provider !== 0) {
          return provider
        }

        const name = a.providerName.localeCompare(b.providerName)
        if (name !== 0) {
          return name
        }

        return a.display.localeCompare(b.display)
      }),
  )
  const controller = createSearchablePanelController({
    entries,
    limit: PANEL_LIST_ROWS,
    onClose: props.onClose,
    onSelect: (item) => props.onSelect({ providerID: item.providerID, modelID: item.modelID }),
    isCurrent: (item) => item.current,
  })

  return (
    <PanelShell
      title="Select model"
      layout={controller.layout()}
      query={controller.query()}
      count={controller.items().length}
      total={entries().length}
      placeholder="Search"
      theme={props.theme}
      inputRef={controller.inputRef}
      onQuery={controller.setQuery}
      mono={props.mono}
      background={false}
    >
      <RunFooterMenu
        theme={props.theme}
        items={() =>
          controller.query().trim() ||
          (controller.layout().compact && new Set(controller.items().map((item) => item.providerID)).size > 1)
            ? controller.items().map((item) => ({ ...item, footer: item.providerName, footerTone: undefined }))
            : controller.items()
        }
        selected={controller.menu.selected}
        offset={controller.menu.offset}
        rows={controller.menu.limit}
        limit={controller.menu.limit()}
        compact={controller.layout().compact}
        empty={props.providers() ? "No results found" : "Models loading"}
        border={false}
        paddingLeft={panelPad(props.mono)}
        paddingRight={panelPad(props.mono)}
        grouped={!controller.query().trim()}
        headerColor={props.theme().muted}
        mono={props.mono}
      />
    </PanelShell>
  )
}

/** @jsxImportSource @opentui/solid */
import type { BoxRenderable, ScrollBoxRenderable, TextareaRenderable } from "@opentui/core"
import { useKeyboard, useTerminalDimensions } from "@opentui/solid"
import { For, Show, createEffect, createMemo, createSignal, onCleanup } from "solid-js"
import {
  createFormBodyState,
  formAcknowledge,
  formCommitInput,
  formConfirm,
  formCurrent,
  formCustom,
  formDisplay,
  formErrorMessage,
  formInput,
  formLabel,
  formMove,
  formPick,
  formPlaceholder,
  formReply,
  formRows,
  formSetError,
  formSetExternalReady,
  formSetDraft,
  formSetField,
  formSetSelected,
  formSetSubmitting,
  formSingle,
  formSync,
  formTextual,
  formUnsupported,
  formValidate,
  formValidateValue,
} from "./form.shared"
import type { FormBodyState } from "./form.shared"
import type { RunFooterTheme } from "./theme"
import type { FormCancel, FormReply, MiniFormRequest } from "./types"
import { stringWidth } from "../util/string-width"

export function RunFormBody(props: {
  request: MiniFormRequest
  theme: RunFooterTheme
  onReply: (input: FormReply) => void | Promise<void>
  onCancel: (input: FormCancel) => void | Promise<void>
  openExternal?: (url: string) => Promise<unknown>
  state?: FormBodyState
  onState?: (state: FormBodyState) => void
  mono?: boolean
}) {
  const dims = useTerminalDimensions()
  const [size, setSize] = createSignal(dims())
  const [contentHeight, setContentHeight] = createSignal(1)
  const [viewportHeight, setViewportHeight] = createSignal(0)
  const compact = () => size().width < 56 || size().height < 12
  const [state, setLocalState] = createSignal(props.state ?? createFormBodyState(props.request))
  const setState = (next: FormBodyState | ((previous: FormBodyState) => FormBodyState)) => {
    const value = typeof next === "function" ? next(state()) : next
    setLocalState(value)
    props.onState?.(value)
  }
  const unsupported = createMemo(() => formUnsupported(props.request))
  const current = createMemo(() => formCurrent(props.request, state()))
  const answerField = createMemo(() => {
    const field = current()
    return field?.type === "external" ? undefined : field
  })
  const externalField = createMemo(() => {
    const field = current()
    return field?.type === "external" ? field : undefined
  })
  const confirm = createMemo(() => formConfirm(props.request, state()))
  const rows = createMemo(() => formRows(current()))
  const custom = createMemo(() => formCustom(current()))
  const textual = createMemo(() => formTextual(current()))
  const multiple = createMemo(() => current()?.type === "multiselect")
  const editing = () => !unsupported() && !confirm() && (textual() || state().editing)
  const message = createMemo(() => {
    const value = props.request.metadata?.message
    return typeof value === "string" ? value : undefined
  })
  let area: TextareaRenderable | undefined
  let scroll: ScrollBoxRenderable | undefined
  const choices = new Map<number, BoxRenderable>()

  const revealChoice = () => {
    const row = choices.get(state().selected)
    if (!scroll || scroll.isDestroyed || !row || row.isDestroyed || state().editing || confirm()) return
    if (row.y < scroll.viewport.y) scroll.scrollBy(row.y - scroll.viewport.y)
    const height = Math.min(row.height, scroll.viewport.height)
    if (row.y + height > scroll.viewport.y + scroll.viewport.height)
      scroll.scrollBy(row.y + height - scroll.viewport.y - scroll.viewport.height)
  }

  createEffect(() => {
    state().field
    state().selected
    size()
    revealChoice()
  })

  const action = createMemo(() => {
    if (confirm()) return "submit"
    if (textual() || state().editing) return "save"
    const field = externalField()
    if (!field) return "choose"
    if (state().answers[field.key] === true) return formSingle(props.request) ? "submit" : "next"
    return state().externalReady[field.key] ? (size().width < 24 ? "done" : "acknowledge") : "open URL"
  })

  createEffect(() => {
    setState((previous) => formSync(previous, props.request))
  })

  onCleanup(() => {
    const currentArea = area
    if (!currentArea || currentArea.isDestroyed) return
    setState((previous) => formSetDraft(previous, current(), currentArea.plainText))
  })

  createEffect(() => {
    if (!state().editing || !area || area.isDestroyed) return
    const value = formInput(state(), current())
    if (area.plainText !== value) {
      area.setText(value)
      area.cursorOffset = value.length
    }
    queueMicrotask(() => {
      if (!area || area.isDestroyed || !state().editing) return
      area.focus()
      area.cursorOffset = area.plainText.length
    })
  })

  const beginReply = async (input: FormReply) => {
    const formID = props.request.id
    setState((previous) => formSetSubmitting(previous, true))
    try {
      await props.onReply(input)
    } catch (error) {
      setState((previous) => (previous.formID === formID ? formSetError(previous, formErrorMessage(error)) : previous))
    }
  }

  const submit = (next = state()) => {
    const invalid = formValidate(props.request, next)
    if (invalid) {
      setState((previous) => formSetError(previous, invalid))
      return
    }
    const reply = formReply(props.request, next)
    if (reply) void beginReply(reply)
  }

  const cancel = async () => {
    const formID = props.request.id
    setState((previous) => formSetSubmitting(previous, true))
    try {
      await props.onCancel({
        sessionID: props.request.sessionID,
        formID: props.request.id,
        location: props.request.location,
      })
    } catch (error) {
      setState((previous) => (previous.formID === formID ? formSetError(previous, formErrorMessage(error)) : previous))
    }
  }

  const commitInput = () => {
    const next = formCommitInput(state(), props.request, area?.plainText ?? formInput(state(), current()))
    setState(next)
    if (next.error) return
    if (formSingle(props.request)) {
      submit(next)
      return
    }
    setState(formSetField(next, props.request, next.field + 1))
  }

  const choose = (selected = state().selected) => {
    const base = formSetSelected(state(), selected)
    const row = choices.get(selected)
    if (scroll && row && (row.y < scroll.viewport.y || row.y >= scroll.viewport.y + scroll.viewport.height)) {
      setState(base)
      revealChoice()
      return
    }
    const next = formPick(base, props.request)
    setState(next)
    if (next.editing || multiple()) return
    if (formSingle(props.request)) submit(next)
  }

  const moveField = (direction: -1 | 1) => {
    const next = (state().field + direction + props.request.fields.length + 1) % (props.request.fields.length + 1)
    if (direction < 0 || confirm()) {
      setState((previous) => formSetField(previous, props.request, next))
      return
    }
    const field = current()
    if (field?.type === "external") {
      if (state().answers[field.key] !== true) {
        setState((previous) => formSetError(previous, `Acknowledge ${formLabel(field)}`))
        return
      }
    } else if (field) {
      const invalid = formValidateValue(field, state().answers[field.key])
      if (invalid) {
        setState((previous) => formSetError(previous, invalid))
        return
      }
    }
    setState((previous) => formSetField(previous, props.request, next))
  }

  const external = async () => {
    const field = current()
    if (field?.type !== "external") return
    if (state().answers[field.key] === true) {
      if (formSingle(props.request)) submit()
      else moveField(1)
      return
    }
    if (state().externalReady[field.key]) {
      const next = formAcknowledge(state(), props.request)
      setState(next)
      if (formSingle(props.request)) submit(next)
      return
    }
    try {
      if (props.openExternal) await props.openExternal(field.url)
      else {
        const { openUrl } = await import("@opencode/util/open")
        await openUrl(field.url)
      }
      setState((previous) => formSetExternalReady(previous, field.key))
    } catch {
      setState((previous) => formSetExternalReady(previous, field.key))
      setState((previous) => formSetError(previous, "Could not open the URL. Open it manually, then press enter."))
    }
  }

  useKeyboard((event) => {
    if (state().submitting) {
      event.preventDefault()
      return
    }
    if (event.name === "escape") {
      void cancel()
      event.preventDefault()
      return
    }
    if (event.name === "pageup" || event.name === "pagedown") {
      scroll?.scrollBy(event.name === "pageup" ? -1 : 1, "viewport")
      event.preventDefault()
      return
    }
    if (unsupported()) return
    if (state().editing) return
    if (
      event.name === "tab" ||
      event.name === "left" ||
      event.name === "right" ||
      event.name === "h" ||
      event.name === "l"
    ) {
      const direction = event.shift || event.name === "left" || event.name === "h" ? -1 : 1
      moveField(direction)
      event.preventDefault()
      return
    }
    if (confirm() && event.name === "return") {
      submit()
      event.preventDefault()
      return
    }
    if (current()?.type === "external" && event.name === "return") {
      void external()
      event.preventDefault()
      return
    }
    const total = rows().length + (custom() ? 1 : 0)
    const digit = Number(event.name)
    if (!Number.isNaN(digit) && digit >= 1 && digit <= Math.min(total, 9)) {
      choose(digit - 1)
      event.preventDefault()
      return
    }
    if (event.name === "up" || event.name === "k") {
      setState((previous) => formMove(previous, props.request, -1))
      event.preventDefault()
      return
    }
    if (event.name === "down" || event.name === "j") {
      setState((previous) => formMove(previous, props.request, 1))
      event.preventDefault()
      return
    }
    if (event.name === "return") {
      choose()
      event.preventDefault()
    }
  })

  return (
    <box
      width="100%"
      height="100%"
      minHeight={0}
      flexDirection="column"
      backgroundColor={props.theme.surface}
      paddingLeft={compact() ? 0 : 2}
      paddingRight={compact() ? 0 : 3}
      paddingTop={compact() ? 0 : 1}
      paddingBottom={compact() ? 0 : 1}
      onSizeChange={function () {
        setSize({ width: this.width, height: this.height })
      }}
    >
      <box height={1} flexDirection="row" gap={1} flexShrink={0} marginBottom={compact() ? 0 : 1}>
        <text fg={unsupported() ? props.theme.warning : props.theme.question} wrapMode="none" flexShrink={0}>
          {props.mono ? "*" : "◆"}
        </text>
        <text fg={props.theme.text} wrapMode="none" truncate minWidth={0}>
          {props.request.title}
        </text>
        <Show when={!unsupported() && !formSingle(props.request)}>
          <text fg={props.theme.muted} wrapMode="none" flexShrink={0}>
            {confirm()
              ? "Review"
              : `${Math.min(state().field + 1, props.request.fields.length)}/${props.request.fields.length}`}
          </text>
        </Show>
      </box>
      <scrollbox
        width="100%"
        height={!compact() && editing() ? Math.min(contentHeight(), Math.max(1, size().height - 9)) : undefined}
        flexGrow={!compact() && editing() ? 0 : 1}
        minHeight={0}
        viewportOptions={{
          paddingRight: props.mono ? 0 : 1,
          onSizeChange() {
            setViewportHeight(this.height)
          },
        }}
        verticalScrollbarOptions={{
          visible: !props.mono && contentHeight() > viewportHeight(),
          trackOptions: { backgroundColor: props.theme.surface, foregroundColor: props.theme.line },
        }}
        onSizeChange={revealChoice}
        ref={(item) => {
          scroll = item
        }}
      >
        <box
          width="100%"
          flexDirection="column"
          flexShrink={0}
          gap={compact() ? 0 : 1}
          onSizeChange={function () {
            setContentHeight(this.height)
          }}
        >
          <Show when={message()}>
            {(value) => (
              <text width="100%" fg={props.theme.muted} flexShrink={0}>
                {value()}
              </text>
            )}
          </Show>
          <Show when={unsupported()}>
            {(value) => (
              <box width="100%" flexDirection="column" flexShrink={0} gap={compact() ? 0 : 1}>
                <text width="100%" fg={props.theme.warning} wrapMode="word" flexShrink={0}>
                  {value()}
                </text>
                <text width="100%" fg={props.theme.muted} flexShrink={0}>
                  This request remains pending until you dismiss it.
                </text>
              </box>
            )}
          </Show>
          <Show when={!unsupported() && externalField()}>
            {(field) => (
              <box width="100%" flexDirection="column" flexShrink={0} gap={compact() ? 0 : 1}>
                <text width="100%" fg={props.theme.text} wrapMode="word" flexShrink={0}>
                  {field().description ?? formLabel(field())}
                </text>
                <text width="100%" fg={props.theme.link} wrapMode="word" flexShrink={0}>
                  {field().url}
                </text>
                <text
                  width="100%"
                  fg={state().answers[field().key] === true ? props.theme.selection : props.theme.muted}
                  flexShrink={0}
                >
                  {state().answers[field().key] === true
                    ? "Acknowledged"
                    : state().externalReady[field().key]
                      ? "Press enter to acknowledge completion"
                      : "Press enter to open the URL"}
                </text>
              </box>
            )}
          </Show>
          <Show when={!unsupported() && answerField() && !confirm()}>
            <box width="100%" flexDirection="column" flexShrink={0} gap={compact() ? 0 : 1}>
              <text width="100%" fg={props.theme.text} wrapMode="word" flexShrink={0}>
                {answerField()!.description ?? formLabel(answerField()!)}
                {answerField()!.required ? " (required)" : ""}
                {multiple() ? " (select all that apply)" : ""}
              </text>
              <Show when={!textual() && !state().editing}>
                <box width="100%" flexDirection="column" flexShrink={0}>
                  <For each={rows()}>
                    {(row, index) => {
                      const active = () => state().selected === index()
                      const picked = () => {
                        const field = current()
                        if (!field) return false
                        const value = state().answers[field.key]
                        return Array.isArray(value) ? value.includes(String(row.value)) : value === row.value
                      }
                      const ordinal = () => (props.mono ? `${active() ? ">" : " "}${index() + 1}.` : `${index() + 1}.`)
                      const inline = () =>
                        !!row.description &&
                        stringWidth(ordinal()) +
                          2 +
                          stringWidth(row.label) +
                          (multiple() ? 4 : picked() ? 2 : 0) +
                          stringWidth(row.description) <=
                          size().width - (compact() ? 0 : 5) - (props.mono ? 0 : 1)
                      return (
                        <box
                          ref={(item) => {
                            choices.set(index(), item)
                          }}
                          onSizeChange={revealChoice}
                          flexShrink={0}
                          flexDirection="row"
                          gap={1}
                          alignItems="flex-start"
                          onMouseMove={() => setState((previous) => formSetSelected(previous, index()))}
                          backgroundColor={active() ? props.theme.formfieldFocusedBg : "transparent"}
                          onMouseUp={() => choose(index())}
                        >
                          <text
                            fg={active() ? props.theme.formfieldFocusedText : props.theme.formfieldText}
                            wrapMode="none"
                            flexShrink={0}
                          >
                            {ordinal()}
                          </text>
                          <box
                            flexDirection={inline() ? "row" : "column"}
                            gap={inline() ? 1 : 0}
                            flexGrow={1}
                            minWidth={0}
                          >
                            <text
                              fg={active() ? props.theme.formfieldFocusedText : props.theme.formfieldText}
                              wrapMode="word"
                              flexShrink={0}
                            >
                              <span style={{ fg: picked() ? props.theme.selection : undefined }}>
                                {multiple() ? `[${picked() ? "x" : " "}] ` : ""}
                              </span>
                              {row.label}
                              <span style={{ fg: props.theme.selection }}>{!multiple() && picked() ? " *" : ""}</span>
                            </text>
                            <Show when={row.description}>
                              <text fg={props.theme.muted} wrapMode="word" flexShrink={0}>
                                {row.description}
                              </text>
                            </Show>
                          </box>
                        </box>
                      )
                    }}
                  </For>
                  <Show when={custom()}>
                    <box
                      ref={(item) => {
                        choices.set(rows().length, item)
                      }}
                      onSizeChange={revealChoice}
                      flexShrink={0}
                      flexDirection="row"
                      gap={1}
                      backgroundColor={
                        state().selected === rows().length ? props.theme.formfieldFocusedBg : "transparent"
                      }
                      onMouseUp={() => choose(rows().length)}
                    >
                      <text
                        wrapMode="none"
                        flexShrink={0}
                        fg={
                          state().selected === rows().length
                            ? props.theme.formfieldFocusedText
                            : props.theme.formfieldText
                        }
                      >
                        {props.mono
                          ? `${state().selected === rows().length ? ">" : " "}${rows().length + 1}.`
                          : `${rows().length + 1}.`}
                      </text>
                      <text
                        wrapMode="word"
                        flexGrow={1}
                        minWidth={0}
                        fg={
                          state().selected === rows().length
                            ? props.theme.formfieldFocusedText
                            : props.theme.formfieldText
                        }
                      >
                        Type your own answer
                      </text>
                    </box>
                  </Show>
                </box>
              </Show>
            </box>
          </Show>
          <Show when={!unsupported() && confirm()}>
            <box width="100%" flexDirection="column" flexShrink={0}>
              <For each={props.request.fields}>
                {(field) => (
                  <text width="100%" fg={props.theme.muted} wrapMode="word" flexShrink={0}>
                    {formLabel(field)}:{" "}
                    {field.type === "external"
                      ? state().answers[field.key] === true
                        ? "acknowledged"
                        : "required"
                      : formDisplay(field, state().answers[field.key]) || "(not answered)"}
                  </text>
                )}
              </For>
            </box>
          </Show>
          <Show when={stringWidth(state().error) > size().width || state().error.includes("\n")}>
            <text width="100%" fg={props.theme.error} wrapMode="word" flexShrink={0}>
              {state().error}
            </text>
          </Show>
        </box>
      </scrollbox>
      <Show when={!unsupported() && answerField() && editing()}>
        <textarea
          ref={(item: TextareaRenderable) => {
            area = item
          }}
          width="100%"
          minHeight={1}
          maxHeight={Math.max(1, Math.min(3, size().height - 6))}
          flexShrink={0}
          marginTop={compact() ? 0 : 1}
          initialValue={formInput(state(), current())}
          placeholder={formPlaceholder(answerField())}
          placeholderColor={props.theme.muted}
          textColor={props.theme.formfieldText}
          focusedTextColor={props.theme.formfieldFocusedText}
          backgroundColor={props.theme.surface}
          focusedBackgroundColor={props.theme.formfieldFocusedBg}
          cursorColor={props.theme.formfieldFocusedText}
          focused
          onSubmit={commitInput}
          onContentChange={() => {
            const currentArea = area
            if (!currentArea || currentArea.isDestroyed) return
            setState((previous) => formSetDraft(previous, current(), currentArea.plainText))
          }}
          onKeyDown={(event) => {
            if (event.name === "escape") {
              event.preventDefault()
              void cancel()
            }
          }}
        />
      </Show>
      <Show when={state().error && compact()}>
        <text height={1} fg={props.theme.error} wrapMode="none" truncate flexShrink={0}>
          {state().error}
        </text>
      </Show>
      <Show when={!compact() && editing()}>
        <box flexGrow={1} minHeight={0} />
      </Show>
      <Show
        when={compact()}
        fallback={
          <box flexDirection="row" justifyContent="space-between" gap={1} flexShrink={0}>
            <text
              fg={state().submitting ? props.theme.running : props.theme.muted}
              wrapMode="word"
              flexShrink={1}
              minWidth={0}
            >
              {state().submitting
                ? "submitting…"
                : unsupported()
                  ? "esc dismiss"
                  : confirm()
                    ? "enter submit   esc dismiss"
                    : editing()
                      ? "enter save   esc dismiss"
                      : externalField()
                        ? `enter ${action()}   esc dismiss`
                        : props.mono
                          ? "up/down select   enter choose   tab next   esc dismiss"
                          : "↑↓ select   enter choose   tab next   esc dismiss"}
            </text>
            <Show when={state().error}>
              <text fg={props.theme.error} wrapMode="none" truncate flexShrink={1}>
                {state().error}
              </text>
            </Show>
          </box>
        }
      >
        <box flexDirection="row" flexWrap="wrap" columnGap={1} flexShrink={0}>
          <Show when={!unsupported()}>
            <text
              height={1}
              fg={state().submitting ? props.theme.running : props.theme.muted}
              wrapMode="none"
              flexShrink={0}
            >
              {state().submitting ? "submitting…" : `enter ${action()}`}
            </text>
          </Show>
          <Show when={!state().submitting}>
            <text height={1} fg={props.theme.muted} wrapMode="none" flexShrink={0}>
              esc dismiss
            </text>
          </Show>
          <Show when={!state().submitting && size().height >= 10}>
            <text fg={props.theme.muted} wrapMode="word" maxWidth="100%" flexShrink={0}>
              {size().width >= 56 && rows().length > 0 && !state().editing ? "up/down select  tab next  " : ""}pgup/pgdn
              scroll
            </text>
          </Show>
        </box>
      </Show>
    </box>
  )
}

/** @jsxImportSource @opentui/solid */
import { TextAttributes, type ColorInput } from "@opentui/core"
import { useTerminalDimensions, type JSX } from "@opentui/solid"
import { createEffect, createMemo, createSignal, type Accessor } from "solid-js"
import { transparent, type RunFooterTheme } from "./theme"
import { Locale } from "../util/locale"
import { stringWidth } from "../util/string-width"
import { moveSelection, moveSelectionOffset, reconcileSelection, revealSelectionOffset } from "../ui/select-controller"

export const FOOTER_MENU_ROWS = 8
export const FOOTER_COMPACT_WIDTH = 40

export function footerMenuText(text: string, width: number, mono = false) {
  if (!mono) return Locale.truncateWidth(text, width)
  if (stringWidth(text) <= width) return text
  const suffix = ".".repeat(Math.min(3, Math.max(0, width)))
  return Locale.takeWidth(text, width - suffix.length) + suffix
}

export type RunFooterMenuItem = {
  display: string
  icon?: (color: ColorInput) => JSX.Element
  current?: boolean
  description?: string
  category?: string
  footer?: string
  footerTone?: "selection" | "running" | "error" | "success"
}

type RunFooterMenuRow =
  | { type: "header"; label: string }
  | { type: "item"; item: RunFooterMenuItem; index: number }
  | { type: "spacer" }

export function createFooterMenuState(input: { count: Accessor<number>; limit?: number | Accessor<number> }) {
  const [selected, setSelected] = createSignal(0)
  const [offset, setOffset] = createSignal(0)
  const limit = () => Math.max(1, typeof input.limit === "function" ? input.limit() : (input.limit ?? FOOTER_MENU_ROWS))
  const rows = createMemo(() => Math.max(1, Math.min(limit(), input.count())))

  const reveal = (index: number) => {
    const count = input.count()
    const next = reconcileSelection(index, count)
    setSelected(next)
    setOffset((value) => revealSelectionOffset(value, { count, limit: limit(), selected: next }))
  }

  const reset = () => {
    setSelected(0)
    setOffset(0)
  }

  createEffect(() => {
    const count = input.count()
    const next = reconcileSelection(selected(), count)
    setSelected(next)
    setOffset((value) => revealSelectionOffset(value, { count, limit: limit(), selected: next }))
  })

  const move = (dir: -1 | 1) => {
    const count = input.count()
    const next = moveSelection(selected(), { count, delta: dir, policy: "clamp" })
    setSelected(next)
    setOffset((value) => moveSelectionOffset(value, { count, limit: limit(), selected: next, direction: dir }))
  }

  return {
    selected,
    offset,
    rows,
    limit,
    reveal,
    reset,
    move,
  }
}

export function RunFooterMenu(props: {
  theme: Accessor<RunFooterTheme>
  items: Accessor<RunFooterMenuItem[]>
  selected: Accessor<number>
  offset: Accessor<number>
  rows: Accessor<number>
  limit?: number
  empty?: string
  border?: boolean
  paddingLeft?: number
  paddingRight?: number
  grouped?: boolean
  compact?: boolean
  background?: boolean
  headerColor?: ColorInput
  mono?: boolean
}) {
  const term = useTerminalDimensions()
  const limit = () => Math.max(1, Math.min(props.rows(), props.limit ?? FOOTER_MENU_ROWS))
  const border = () => props.border ?? true
  const paddingLeft = () => Math.min(props.paddingLeft ?? 1, term().width < FOOTER_COMPACT_WIDTH ? 1 : Infinity)
  const paddingRight = () => Math.min(props.paddingRight ?? 0, term().width < FOOTER_COMPACT_WIDTH ? 1 : Infinity)
  const width = () => Math.max(0, term().width - (border() ? 1 : 0) - paddingLeft() - paddingRight())
  const [groupOffset, setGroupOffset] = createSignal(0)
  let previous = -1
  const groupedRows = createMemo<RunFooterMenuRow[]>(() => {
    const all: RunFooterMenuRow[] = []
    let category = ""
    props.items().forEach((item, index) => {
      if (item.category && item.category !== category) {
        if (all.length > 0 && !props.compact) {
          all.push({ type: "spacer" })
        }

        category = item.category
        if (!props.compact) all.push({ type: "header", label: item.category })
      }

      all.push({ type: "item", item, index })
    })
    return all
  })

  createEffect(() => {
    if (!props.grouped) {
      return
    }

    const all = groupedRows()
    const selected = all.findIndex((item) => item.type === "item" && item.index === props.selected())
    if (all.length === 0 || selected === -1) {
      setGroupOffset(0)
      previous = props.selected()
      return
    }

    const dir = props.selected() === previous + 1 ? 1 : props.selected() === previous - 1 ? -1 : undefined
    setGroupOffset((value) =>
      dir
        ? moveSelectionOffset(value, { count: all.length, limit: limit(), selected, direction: dir })
        : revealSelectionOffset(value, { count: all.length, limit: limit(), selected }),
    )
    previous = props.selected()
  })

  const rows = createMemo<RunFooterMenuRow[]>(() => {
    if (!props.grouped) {
      return props
        .items()
        .slice(props.offset(), props.offset() + limit())
        .map((item, index) => ({
          type: "item",
          item,
          index: index + props.offset(),
        }))
    }

    const all = groupedRows()
    const start = Math.max(0, Math.min(groupOffset(), all.length - limit()))
    return all.slice(start, start + limit())
  })
  const descriptionColumn = createMemo(() => {
    const width = Math.max(
      0,
      ...props
        .items()
        .filter((item) => item.description)
        .map((item) => stringWidth(item.display)),
    )
    return width === 0 ? 0 : width + 2
  })
  return (
    <box
      width="100%"
      height={props.rows()}
      flexShrink={0}
      backgroundColor={props.background ? props.theme().shade : transparent}
      flexDirection="column"
    >
      {rows().length === 0 ? (
        <box
          paddingRight={0}
          flexDirection="row"
          backgroundColor={props.background ? props.theme().shade : transparent}
        >
          {border() ? (
            <text fg={props.theme().border} wrapMode="none">
              {props.mono ? "|" : "┃"}
            </text>
          ) : undefined}
          <box
            flexGrow={1}
            flexShrink={1}
            paddingLeft={paddingLeft()}
            paddingRight={paddingRight()}
            backgroundColor={props.background ? props.theme().shade : transparent}
          >
            <text fg={props.theme().muted} wrapMode="none" truncate>
              {props.empty ?? "No matching items"}
            </text>
          </box>
        </box>
      ) : (
        rows().map((row) => {
          if (row.type === "spacer") {
            return <box height={1} flexShrink={0} />
          }

          if (row.type === "header") {
            return (
              <box height={1} flexShrink={0} paddingLeft={paddingLeft()} paddingRight={paddingRight()}>
                <text
                  fg={props.headerColor ?? props.theme().muted}
                  attributes={TextAttributes.BOLD}
                  wrapMode="none"
                  truncate
                >
                  {row.label}
                </text>
              </box>
            )
          }

          const active = () => row.index === props.selected()
          const available = () => Math.max(0, width() - (row.item.icon ? 2 : 0))
          const attributes = () =>
            active() ? TextAttributes.BOLD | (props.mono ? TextAttributes.INVERSE : 0) : undefined
          const background = () =>
            active() ? props.theme().actionFocusedBg : props.background ? props.theme().shade : transparent
          const footer = () => {
            if (!row.item.footer) return
            const title = stringWidth(row.item.display)
            const primary = row.item.footerTone && !(row.item.current && row.item.footerTone === "selection")
            return (primary ? Math.min(row.item.icon ? 4 : 8, title) : title) + 1 + stringWidth(row.item.footer) <=
              available()
              ? row.item.footer
              : undefined
          }
          const description = () => {
            if (!row.item.description) return
            const remaining = available() - descriptionColumn() - (footer() ? stringWidth(footer()!) + 1 : 0)
            if (remaining < Math.min(12, stringWidth(row.item.description))) return
            return footerMenuText(row.item.description, remaining, props.mono)
          }
          return (
            <box height={1} flexShrink={0} paddingRight={0} flexDirection="row" backgroundColor={background()}>
              {border() ? (
                <text fg={props.theme().actionFocusedText} bg={background()} wrapMode="none">
                  {active() ? (props.mono ? ">" : "▌") : " "}
                </text>
              ) : undefined}
              <box
                flexGrow={1}
                flexShrink={1}
                paddingLeft={paddingLeft()}
                paddingRight={paddingRight()}
                backgroundColor={background()}
              >
                <box width="100%" flexDirection="row" justifyContent="space-between" gap={1}>
                  <box flexDirection="row" gap={0} flexGrow={1} flexShrink={1}>
                    {row.item.icon ? (
                      <box width={2} flexShrink={0}>
                        {row.item.icon(active() ? props.theme().actionFocusedText : props.theme().formfieldText)}
                      </box>
                    ) : undefined}
                    <text
                      fg={active() ? props.theme().actionFocusedText : props.theme().formfieldText}
                      attributes={attributes()}
                      wrapMode="none"
                      flexShrink={0}
                    >
                      {footerMenuText(
                        row.item.display,
                        available() - (footer() ? stringWidth(footer()!) + 1 : 0),
                        props.mono,
                      )}
                    </text>
                    {description() ? (
                      <>
                        <text
                          fg={active() ? props.theme().actionFocusedText : props.theme().muted}
                          wrapMode="none"
                          flexShrink={0}
                        >
                          {" ".repeat(Math.max(1, descriptionColumn() - stringWidth(row.item.display)))}
                        </text>
                        <text
                          fg={active() ? props.theme().actionFocusedText : props.theme().muted}
                          wrapMode="none"
                          flexGrow={1}
                          flexShrink={1}
                        >
                          {description()}
                        </text>
                      </>
                    ) : undefined}
                  </box>
                  {footer() ? (
                    <text
                      fg={active() ? props.theme().actionFocusedText : props.theme()[row.item.footerTone ?? "muted"]}
                      attributes={attributes()}
                      wrapMode="none"
                      flexShrink={0}
                    >
                      {footer()}
                    </text>
                  ) : undefined}
                </box>
              </box>
            </box>
          )
        })
      )}
    </box>
  )
}

// Permission UI body for the direct-mode footer.
//
// Renders inside the footer when the reducer pushes a FooterView of type
// "permission". Uses a three-stage state machine (permission.shared.ts):
//
//   permission → shows the request with Allow once / Always / Reject buttons
//   always     → confirmation step before granting permanent access
//   reject     → text field for the rejection message
//
// Keyboard: left/right to select, enter to confirm, esc to reject.
// The diff view (when available) uses the same diff component as scrollback
// tool snapshots.
/** @jsxImportSource @opentui/solid */
import { TextAttributes, type ScrollBoxRenderable, type TextareaRenderable } from "@opentui/core"
import { useKeyboard, useTerminalDimensions } from "@opentui/solid"
import { For, Match, Show, Switch, createEffect, createMemo, createSignal } from "solid-js"
import {
  createPermissionBodyState,
  permissionAlwaysLines,
  permissionCancel,
  permissionEscape,
  permissionHover,
  permissionInfo,
  permissionLabel,
  permissionOptions,
  permissionReject,
  permissionRun,
  permissionShift,
  type PermissionOption,
} from "./permission.shared"
import { stringWidth } from "../util/string-width"
import { toolFiletype } from "./tool"
import { transparent, type RunBlockTheme, type RunFooterTheme } from "./theme"
import type { MiniPermissionRequest, PermissionReply } from "./types"
import { PatchDiff } from "../component/patch-diff"

function buttons(
  list: PermissionOption[],
  selected: PermissionOption,
  theme: RunFooterTheme,
  disabled: boolean,
  onHover: (option: PermissionOption) => void,
  onSelect: (option: PermissionOption) => void,
  mono: boolean,
) {
  return (
    <box width="100%" flexDirection="row" flexWrap="wrap" columnGap={1} flexShrink={0}>
      <For each={list}>
        {(option) => (
          <box
            width={stringWidth(permissionLabel(option)) + 2}
            height={1}
            flexShrink={0}
            paddingLeft={1}
            paddingRight={1}
            backgroundColor={option === selected ? theme.actionFocusedBg : transparent}
            onMouseMove={() => {
              if (!disabled) onHover(option)
            }}
            onMouseUp={() => {
              if (!disabled) onSelect(option)
            }}
          >
            <text
              wrapMode="none"
              fg={option === selected ? theme.actionFocusedText : theme.actionSecondaryText}
              attributes={option === selected && mono ? TextAttributes.INVERSE : undefined}
            >
              {permissionLabel(option)}
            </text>
          </box>
        )}
      </For>
    </box>
  )
}

/** @internal Exported to test managed textarea submission without permission navigation. */
export function RejectField(props: {
  theme: RunFooterTheme
  text: string
  disabled: boolean
  onChange: (text: string) => void
  onConfirm: () => void
  onCancel: () => void
}) {
  let area: TextareaRenderable | undefined

  createEffect(() => {
    if (!area || area.isDestroyed) {
      return
    }

    if (area.plainText !== props.text) {
      area.setText(props.text)
      area.cursorOffset = props.text.length
    }

    queueMicrotask(() => {
      if (!area || area.isDestroyed || props.disabled) {
        return
      }
      area.focus()
    })
  })

  return (
    <textarea
      width="100%"
      minHeight={1}
      maxHeight={3}
      wrapMode="word"
      placeholder="Tell OpenCode what to do differently"
      placeholderColor={props.theme.muted}
      textColor={props.theme.formfieldText}
      focusedTextColor={props.theme.formfieldFocusedText}
      backgroundColor={props.theme.surface}
      focusedBackgroundColor={props.theme.formfieldFocusedBg}
      cursorColor={props.theme.formfieldFocusedText}
      focused={!props.disabled}
      onSubmit={props.onConfirm}
      onContentChange={() => {
        if (!area || area.isDestroyed) {
          return
        }
        props.onChange(area.plainText)
      }}
      onKeyDown={(event) => {
        if (event.name === "escape") {
          event.preventDefault()
          props.onCancel()
          return
        }
      }}
      ref={(item) => {
        area = item
      }}
    />
  )
}

export function RunPermissionBody(props: {
  request: MiniPermissionRequest
  directory?: () => string
  theme: RunFooterTheme
  block: RunBlockTheme
  onReply: (input: PermissionReply) => void | Promise<void>
  mono?: boolean
}) {
  const dims = useTerminalDimensions()
  const [size, setSize] = createSignal(dims())
  const width = () => size().width
  const compact = () => width() < 56 || size().height < 12
  const [state, setState] = createSignal(createPermissionBodyState(props.request))
  const stage = createMemo(() => state().stage)
  const info = createMemo(() => permissionInfo(props.request, props.directory?.(), props.mono))
  const ft = createMemo(() => toolFiletype(info().file))
  let scroll: ScrollBoxRenderable | undefined
  const scrollbar = createMemo(() => ({
    visible: !props.mono,
    trackOptions: {
      backgroundColor: props.theme.surface,
      foregroundColor: props.theme.line,
    },
  }))
  const opts = createMemo(() =>
    permissionOptions(stage()).filter((option) => option !== "always" || (props.request.save?.length ?? 0) > 0),
  )
  const busy = createMemo(() => state().submitting)
  const controlsWidth = () => opts().reduce((total, option) => total + stringWidth(permissionLabel(option)) + 3, -1)
  const hint = () =>
    compact() && width() < 56
      ? "pgup/pgdn scroll"
      : `${props.mono ? "left/right" : "⇆"} select  enter confirm  esc ${stage() === "always" ? "cancel" : "reject"}`
  const inlineControls = () => controlsWidth() + stringWidth(hint()) + 1 <= width() - (compact() ? 0 : 5)
  const title = createMemo(() => {
    if (stage() === "always") {
      return "Always allow"
    }

    if (stage() === "reject") {
      return width() < 24 ? "Reject" : "Reject permission"
    }

    return width() < 24 ? "Permission" : "Permission required"
  })

  createEffect(() => {
    const id = props.request.id
    if (state().requestID === id) {
      return
    }

    setState(createPermissionBodyState(props.request))
  })

  const shift = (dir: -1 | 1) => {
    setState((prev) => permissionShift(prev, dir, opts()))
  }

  createEffect(() => {
    stage()
    props.request.id
    if (scroll && !scroll.isDestroyed) scroll.scrollTo(0)
  })

  const submit = async (next: PermissionReply) => {
    setState((prev) => ({
      ...prev,
      submitting: true,
    }))

    try {
      await props.onReply(next)
    } catch {
      setState((prev) => ({
        ...prev,
        submitting: false,
      }))
    }
  }

  const run = (option: PermissionOption) => {
    const cur = state()
    const next = permissionRun(cur, props.request.id, option)
    if (next.state !== cur) {
      setState(next.state)
    }

    if (!next.reply) {
      return
    }

    void submit(next.reply)
  }

  const reject = () => {
    const next = permissionReject(state(), props.request.id)
    if (!next) {
      return
    }

    void submit(next)
  }

  const cancelReject = () => {
    setState((prev) => permissionCancel(prev))
  }

  useKeyboard((event) => {
    const cur = state()
    if (cur.stage === "reject") {
      return
    }

    if (event.name === "pageup" || event.name === "pagedown") {
      scroll?.scrollBy(event.name === "pageup" ? -1 : 1, "viewport")
      event.preventDefault()
      return
    }

    if (cur.submitting) {
      if (["left", "right", "h", "l", "tab", "return", "escape"].includes(event.name)) {
        event.preventDefault()
      }
      return
    }

    if (event.name === "tab") {
      shift(event.shift ? -1 : 1)
      event.preventDefault()
      return
    }

    if (event.name === "left" || event.name === "h") {
      shift(-1)
      event.preventDefault()
      return
    }

    if (event.name === "right" || event.name === "l") {
      shift(1)
      event.preventDefault()
      return
    }

    if (event.name === "return") {
      run(state().selected)
      event.preventDefault()
      return
    }

    if (event.name !== "escape") {
      return
    }

    setState((prev) => permissionEscape(prev))
    event.preventDefault()
  })

  return (
    <box
      width="100%"
      height="100%"
      minHeight={0}
      flexDirection="column"
      backgroundColor={props.theme.surface}
      onSizeChange={function () {
        setSize({ width: this.width, height: this.height })
      }}
    >
      <box
        paddingLeft={compact() ? 0 : 2}
        paddingRight={compact() ? 0 : 3}
        paddingTop={compact() ? 0 : 1}
        paddingBottom={compact() ? 0 : 1}
        gap={compact() ? 0 : 1}
        flexShrink={0}
      >
        <text height={1} fg={props.theme.text} wrapMode="none" truncate>
          <span style={{ fg: props.theme.permission }}>{props.mono ? "! " : "△ "}</span>
          {title()}
        </text>
        <Show when={!compact() && stage() === "reject"}>
          <text fg={props.theme.muted}>Tell OpenCode what to do differently</text>
        </Show>
      </box>

      <Show
        when={stage() !== "reject"}
        fallback={
          <box width="100%" flexGrow={1} minHeight={0} justifyContent="flex-end">
            <box
              backgroundColor={props.theme.line}
              flexDirection={width() >= 80 ? "row" : "column"}
              alignItems={width() >= 80 ? "center" : "stretch"}
              justifyContent="space-between"
              paddingLeft={compact() ? 0 : 2}
              paddingRight={compact() ? 0 : 3}
              paddingTop={compact() ? 0 : 1}
              paddingBottom={compact() ? 0 : 1}
              gap={compact() ? 0 : 1}
              flexShrink={0}
            >
              <box width={width() >= 80 ? undefined : "100%"} flexGrow={1} flexShrink={1} minWidth={0}>
                <RejectField
                  theme={props.theme}
                  text={state().message}
                  disabled={busy()}
                  onChange={(text) => {
                    setState((prev) => ({
                      ...prev,
                      message: text,
                    }))
                  }}
                  onConfirm={reject}
                  onCancel={cancelReject}
                />
              </box>
              <Show
                when={!busy()}
                fallback={
                  <text fg={props.theme.running} height={1} wrapMode="none" truncate flexShrink={0}>
                    {compact() ? "Waiting…" : "Waiting for permission event…"}
                  </text>
                }
              >
                <box flexDirection="row" flexWrap="wrap" columnGap={compact() ? 1 : 2} flexShrink={0}>
                  <text fg={props.theme.text} height={1} wrapMode="none" flexShrink={0}>
                    enter <span style={{ fg: props.theme.muted }}>{compact() ? "reject" : "confirm"}</span>
                  </text>
                  <text fg={props.theme.text} height={1} wrapMode="none" flexShrink={0}>
                    esc <span style={{ fg: props.theme.muted }}>{compact() ? "back" : "cancel"}</span>
                  </text>
                </box>
              </Show>
            </box>
          </box>
        }
      >
        <box
          width="100%"
          flexGrow={1}
          minHeight={0}
          paddingLeft={compact() ? 0 : 1}
          paddingRight={compact() ? 0 : 3}
          paddingBottom={compact() ? 0 : 1}
        >
          <scrollbox
            width="100%"
            flexGrow={1}
            minHeight={0}
            viewportOptions={{
              paddingLeft: compact() ? 0 : 1,
              paddingRight: props.mono ? 0 : 1,
            }}
            verticalScrollbarOptions={scrollbar()}
            ref={(item) => {
              scroll = item
            }}
          >
            <Switch>
              <Match when={stage() === "permission"}>
                <box width="100%" flexDirection="column" flexShrink={0} gap={compact() ? 0 : 1}>
                  <box width="100%" paddingLeft={compact() ? 0 : 1} flexShrink={0}>
                    <text width="100%" fg={props.theme.text} wrapMode="word" flexShrink={0}>
                      <span style={{ fg: props.theme.muted }}>{info().icon} </span>
                      {info().title}
                    </text>
                  </box>
                  <Show
                    when={info().diff}
                    fallback={
                      <Show
                        when={info().patch}
                        fallback={
                          <box width="100%" flexDirection="column" flexShrink={0} gap={compact() ? 0 : 1}>
                            <For each={info().lines}>
                              {(line) => (
                                <text width="100%" fg={props.theme.text} wrapMode="word" flexShrink={0}>
                                  {line}
                                </text>
                              )}
                            </For>
                          </box>
                        }
                      >
                        {(patch) => (
                          <Show
                            when={props.block.syntax}
                            fallback={
                              <text width="100%" fg={props.theme.muted} wrapMode="word" flexShrink={0}>
                                {patch()}
                              </text>
                            }
                          >
                            {(syntax) => (
                              <code
                                width="100%"
                                flexShrink={0}
                                wrapMode="word"
                                filetype="diff"
                                drawUnstyledText={false}
                                streaming={true}
                                syntaxStyle={syntax()}
                                content={patch()}
                                fg={props.theme.muted}
                              />
                            )}
                          </Show>
                        )}
                      </Show>
                    }
                  >
                    <Show
                      when={width() >= 40}
                      fallback={
                        <text width="100%" fg={props.theme.text} wrapMode="word" flexShrink={0}>
                          {info().diff}
                        </text>
                      }
                    >
                      <PatchDiff
                        diff={info().diff!}
                        hunkFg={props.block.diffLineNumber}
                        view="unified"
                        filetype={ft()}
                        syntaxStyle={props.block.syntax}
                        showLineNumbers={true}
                        width="100%"
                        flexShrink={0}
                        wrapMode="word"
                        fg={props.theme.text}
                        addedBg={props.block.diffAddedBg}
                        removedBg={props.block.diffRemovedBg}
                        contextBg={props.block.diffContextBg}
                        addedSignColor={props.block.diffHighlightAdded}
                        removedSignColor={props.block.diffHighlightRemoved}
                        lineNumberFg={props.block.diffLineNumber}
                        lineNumberBg={props.block.diffContextBg}
                        addedLineNumberBg={props.block.diffAddedLineNumberBg}
                        removedLineNumberBg={props.block.diffRemovedLineNumberBg}
                      />
                    </Show>
                  </Show>
                  <Show when={!info().diff && !info().patch && info().lines.length === 0}>
                    <text width="100%" fg={props.theme.muted} flexShrink={0}>
                      No diff provided
                    </text>
                  </Show>
                </box>
              </Match>
              <Match when={true}>
                <box width="100%" flexDirection="column" flexShrink={0} gap={compact() ? 0 : 1}>
                  <For each={permissionAlwaysLines(props.request)}>
                    {(line) => (
                      <text width="100%" fg={props.theme.text} wrapMode="word" flexShrink={0}>
                        {line}
                      </text>
                    )}
                  </For>
                </box>
              </Match>
            </Switch>
          </scrollbox>
        </box>

        <box
          width="100%"
          flexDirection={inlineControls() ? "row" : "column"}
          justifyContent="space-between"
          gap={compact() ? 0 : 1}
          paddingLeft={compact() ? 0 : 2}
          paddingRight={compact() ? 0 : 3}
          paddingTop={compact() ? 0 : 1}
          paddingBottom={compact() ? 0 : 1}
          flexShrink={0}
          backgroundColor={props.theme.pane}
        >
          <box width={inlineControls() ? controlsWidth() : "100%"} flexShrink={0}>
            {buttons(
              opts(),
              state().selected,
              props.theme,
              busy(),
              (option) => {
                setState((prev) => permissionHover(prev, option))
              },
              run,
              props.mono ?? false,
            )}
          </box>
          <Show
            when={!busy()}
            fallback={
              <text fg={props.theme.running} height={1} wrapMode="none" truncate flexShrink={0}>
                {compact() ? "Waiting…" : "Waiting for permission event…"}
              </text>
            }
          >
            <text fg={props.theme.text} height={1} wrapMode="none" flexShrink={0}>
              <Show
                when={compact() && width() < 56}
                fallback={
                  <>
                    {props.mono ? "left/right" : "⇆"}
                    <span style={{ fg: props.theme.muted }}>{" select  "}</span>
                    enter<span style={{ fg: props.theme.muted }}>{" confirm  "}</span>
                    esc<span style={{ fg: props.theme.muted }}> {stage() === "always" ? "cancel" : "reject"}</span>
                  </>
                }
              >
                pgup/pgdn<span style={{ fg: props.theme.muted }}> scroll</span>
              </Show>
            </text>
          </Show>
        </box>
      </Show>
    </box>
  )
}

// Prompt composer and its state machine for direct interactive mode.
//
// createPromptState() wires keymap command layers, history navigation, and
// `@` autocomplete for files, subagents, and project references.
// It produces a PromptState that RunPromptBody renders as a slim single-line
// composer while the footer view renders any active menus below it.
/** @jsxImportSource @opentui/solid */
import {
  StyledText,
  decodePasteBytes,
  fg,
  stripAnsiSequences,
  type ColorInput,
  type KeyEvent,
  type PasteEvent,
  type TextareaRenderable,
} from "@opentui/core"
import { useRenderer, useTerminalDimensions } from "@opentui/solid"
import { normalizePromptContent } from "../prompt/content"
import { deduplicatePromptImages, promptAttachmentLabel } from "../prompt/attachment"
import { resolvePastedAttachments } from "../component/prompt/local-attachment"
import { createTuiClipboard, type OwnedClipboardService } from "../clipboard"
import type { ClipboardService } from "../context/clipboard"
import fuzzysort from "fuzzysort"
import path from "path"
import { pathToFileURL } from "node:url"
import {
  For,
  Show,
  createEffect,
  createMemo,
  createResource,
  createSignal,
  onCleanup,
  onMount,
  type Accessor,
} from "solid-js"
import { stringWidth } from "../util/string-width"
import { errorMessage } from "../util/error"
import {
  createPromptHistory,
  displayCharAt,
  displaySlice,
  EXIT_COMMANDS,
  isExitCommand,
  isCompactCommand,
  mentionTriggerIndex,
  slashTriggerIndex,
  isNewCommand,
  movePromptHistory,
  promptCopy,
  pushPromptHistory,
} from "./prompt.shared"
import { parseFileLineRange, parseSlashHead, stripFileLineRange } from "../prompt/parse"
import { Keymap } from "../context/keymap"
import { realignEditorPromptParts, resolveEditorSlashValue } from "./prompt.editor"
import { FOOTER_COMPACT_WIDTH, FOOTER_MENU_ROWS, createFooterMenuState, type RunFooterMenuItem } from "./footer.menu"
import type { RunFooterTheme } from "./theme"
import type {
  FooterQueuedPrompt,
  FooterState,
  RunAgent,
  RunCommand,
  RunDelivery,
  RunPrompt,
  RunPromptPart,
  RunReference,
  RunTuiConfig,
} from "./types"
import { EmptyBorder } from "../ui/border"

const AUTOCOMPLETE_ROWS = FOOTER_MENU_ROWS

export const TEXTAREA_MIN_ROWS = 1
const TEXTAREA_MAX_ROWS = 6
export const PROMPT_MAX_ROWS = TEXTAREA_MAX_ROWS + AUTOCOMPLETE_ROWS

export function footerPromptLayout(
  height: number,
  lines = TEXTAREA_MIN_ROWS,
  options = 0,
  statusRows = 1,
  images = false,
) {
  const padding = height >= PROMPT_MAX_ROWS + 4 ? 1 : 0
  // Reserve status and, where possible, one transcript row.
  const available = Math.max(1, height - 1 - statusRows - padding * 2)
  const preview = images && options === 0 ? Math.min(4, available - Math.min(TEXTAREA_MAX_ROWS, Math.max(1, lines))) : 0
  const imageRows = preview >= 3 ? preview : 0
  const textarea = Math.max(1, Math.min(TEXTAREA_MAX_ROWS, available - imageRows - (options > 0 ? 1 : 0)))
  const rows = Math.min(textarea, Math.max(1, lines))
  const menu = options > 0 ? Math.max(1, Math.min(AUTOCOMPLETE_ROWS, options, available - rows)) : 0
  return { padding, textarea, menu, images: imageRows, rows: rows + menu + imageRows }
}

type Mention = Extract<RunPromptPart, { type: "file" | "agent" | "skill" }>

type Auto = RunFooterMenuItem & {
  kind: "mention"
  value: string
  part: Mention
  directory?: boolean
}

type SlashOption = RunFooterMenuItem & {
  kind: "slash"
  name: string
  action?: "editor" | "settings"
}

type PromptOption = Auto | SlashOption

type MenuMode = false | "mention" | "slash"

type PromptInput = {
  directory: Accessor<string>
  findFiles: (query: string) => Promise<string[]>
  agents: Accessor<RunAgent[]>
  references: Accessor<RunReference[]>
  commands: Accessor<RunCommand[] | undefined>
  state: Accessor<FooterState>
  view: Accessor<string>
  prompt: Accessor<boolean>
  width: Accessor<number>
  statusRows: Accessor<number>
  theme: Accessor<RunFooterTheme>
  mono: Accessor<boolean>
  imagePreview?: boolean
  clipboard?: Pick<ClipboardService, "read">
  history?: Accessor<RunPrompt[]>
  queuedPrompts: Accessor<FooterQueuedPrompt[]>
  onQueuedPromptSteer: (inboxID: string) => Promise<boolean>
  onSubmit: (input: RunPrompt) => boolean | Promise<boolean>
  onCycle: () => void
  onInterrupt: () => boolean
  onEditorOpen: (input: { value: string }) => Promise<string | undefined>
  onInputClear: () => void
  onExitRequest?: () => boolean
  onExit: () => void
  onSettings: () => void
  onRows: (rows: number) => void
  onStatus: (text: string) => void
}

export type PromptState = {
  placeholder: Accessor<StyledText | string>
  shell: Accessor<boolean>
  visible: Accessor<boolean>
  options: Accessor<PromptOption[]>
  selected: Accessor<number>
  offset: Accessor<number>
  rows: Accessor<number>
  images: Accessor<ReadonlyArray<{ uri: string }>>
  layout: Accessor<ReturnType<typeof footerPromptLayout>>
  requestExit: () => boolean
  onSubmit: () => void
  submitText: (text: string) => void
  openEditor: (input?: { value?: string }) => Promise<void>
  onKeyDown: (event: KeyEvent) => void
  onPaste: (event: PasteEvent) => Promise<void>
  onContentChange: () => void
  onSizeChange: () => void
  current: () => RunPrompt
  replacePrompt: (prompt: RunPrompt, cursor?: number) => void
  bind: (area?: TextareaRenderable) => void
}

function emptyPrompt(shell: boolean): RunPrompt {
  return shell ? { text: "", parts: [], mode: "shell" } : { text: "", parts: [] }
}

function slashQuery(text: string, cursor: number) {
  const at = slashTriggerIndex(text, cursor)
  if (at === undefined) return
  return { at, value: displaySlice(text, at + 1, cursor) }
}

function parseSlashCommand(text: string, commands: RunCommand[] | undefined) {
  const head = parseSlashHead(text)
  if (!head || head.name.length === 0) {
    return { type: "none" as const }
  }

  if (!commands) {
    return { type: "pending" as const }
  }

  const item = commands.find((entry) => entry.name === head.name)
  if (!item) {
    return { type: "none" as const }
  }

  return {
    type: "command" as const,
    command: { name: head.name, arguments: head.arguments, ...(item.source ? { source: item.source } : {}) },
  }
}

export function selectedCommand(text: string, command: RunPrompt["command"]) {
  if (!command) {
    return
  }

  const head = parseSlashHead(text)
  if (!head || head.name !== command.name) {
    return
  }

  return {
    name: command.name,
    arguments: head.arguments,
    ...(command.source ? { source: command.source } : {}),
  }
}

export function RunPromptBody(props: {
  theme: () => RunFooterTheme
  background: () => ColorInput
  rail: () => ColorInput
  mono: boolean
  cursorStyle: RunTuiConfig["cursor"]
  placeholder: () => StyledText | string
  onSubmit: () => void
  onKeyDown: (event: KeyEvent) => void
  onPaste: (event: PasteEvent) => Promise<void>
  images: Accessor<ReadonlyArray<{ uri: string }>>
  layout: Accessor<ReturnType<typeof footerPromptLayout>>
  onContentChange: () => void
  onSizeChange: () => void
  bind: (area?: TextareaRenderable) => void
}) {
  const renderer = useRenderer()
  let area: TextareaRenderable | undefined
  let pasteTick: ReturnType<typeof setTimeout> | undefined

  const refreshPasteLayout = () => {
    if (pasteTick) {
      clearTimeout(pasteTick)
    }

    pasteTick = setTimeout(() => {
      pasteTick = undefined
      if (!area || area.isDestroyed) {
        return
      }

      // Paste can leave the textarea layout stale until the next edit.
      area.getLayoutNode().markDirty()
      renderer.requestRender()
      void renderer
        .idle()
        .then(() => {
          if (!area || area.isDestroyed) {
            return
          }

          props.onContentChange()
        })
        .catch(() => {})
    }, 0)
  }

  onMount(() => {
    props.bind(area)
  })

  onCleanup(() => {
    if (pasteTick) {
      clearTimeout(pasteTick)
    }
    props.bind(undefined)
  })

  return (
    <box width="100%" paddingTop={props.layout().padding} paddingBottom={props.layout().padding}>
      <box
        border={["left"]}
        borderColor={props.rail()}
        customBorderChars={{ ...EmptyBorder, vertical: props.mono ? "|" : "┃" }}
        paddingLeft={1}
        paddingRight={2}
        onSizeChange={props.onSizeChange}
      >
        <Show when={props.layout().images > 0}>
          <box width="100%" height={props.layout().images} flexDirection="row" gap={1}>
            <For
              each={props
                .images()
                .slice(0, 3)
                .map((image) => image.uri)}
            >
              {(image, index) => {
                const [failed, setFailed] = createSignal(false)
                return (
                  <box width={props.layout().images * 2} height="100%" flexShrink={1}>
                    <Show when={!failed()} fallback={<text fg={props.theme().muted}>No preview</text>}>
                      <image
                        id={`mini-prompt-image-${index()}`}
                        source={image}
                        fit="fit"
                        protocol="auto"
                        width="100%"
                        height="100%"
                        onError={() => setFailed(true)}
                      />
                    </Show>
                  </box>
                )
              }}
            </For>
            <Show when={props.images().length > 3}>
              <text fg={props.theme().muted} wrapMode="none" truncate>
                +{props.images().length - 3} more
              </text>
            </Show>
          </box>
        </Show>
        <textarea
          width="100%"
          minHeight={TEXTAREA_MIN_ROWS}
          maxHeight={props.layout().textarea}
          wrapMode="word"
          placeholder={props.placeholder()}
          placeholderColor={props.theme().muted}
          textColor={props.theme().text}
          focusedTextColor={props.theme().text}
          backgroundColor={props.background()}
          focusedBackgroundColor={props.background()}
          cursorColor={props.theme().text}
          cursorStyle={props.cursorStyle}
          onSubmit={props.onSubmit}
          onKeyDown={props.onKeyDown}
          onPaste={(event) => {
            void props.onPaste(event).finally(refreshPasteLayout)
          }}
          onContentChange={props.onContentChange}
          ref={(next) => {
            area = next
          }}
        />
      </box>
    </box>
  )
}

export function createPromptState(input: PromptInput): PromptState {
  const renderer = useRenderer()
  const term = useTerminalDimensions()
  const [lines, setLines] = createSignal(TEXTAREA_MIN_ROWS)
  const [statusRows, setStatusRows] = createSignal(1)
  const [shell, setShell] = createSignal(false)
  const placeholder = createMemo(() => {
    if (shell()) {
      return new StyledText([fg(input.theme().muted)('Run a command… "git status"')])
    }

    if (!input.state().first) {
      return ""
    }

    return new StyledText([
      fg(input.theme().muted)(`Ask anything, / for commands, @ for context${input.mono() ? "..." : "…"}`),
    ])
  })

  let history = createPromptHistory(input.history?.())
  createEffect(() => {
    history = createPromptHistory(input.history?.())
  })
  let draft: RunPrompt = { text: "", parts: [] }
  let stash: RunPrompt = { text: "", parts: [] }
  let area: TextareaRenderable | undefined
  let tick = false
  let prev = input.view()
  let type = 0
  let parts: Mention[] = []
  let marks = new Map<number, number>()
  const [draftParts, setDraftParts] = createSignal<RunPromptPart[]>([])
  const attachments = createMemo(() =>
    draftParts().flatMap((part) =>
      part.type === "file"
        ? [
            {
              uri: part.url,
              name: part.filename,
              description: part.description,
              mention: part.source?.text
                ? { start: part.source.text.start, end: part.source.text.end, text: part.source.text.value }
                : undefined,
            },
          ]
        : [],
    ),
  )
  const images = createMemo(() =>
    (deduplicatePromptImages(attachments()) ?? []).filter((file) => file.uri.startsWith("data:image/")),
  )
  let clipboard: OwnedClipboardService | undefined
  let pasteQueue: Promise<void> | undefined
  let applyingPaste = false
  let disposed = false
  let revision = 0

  const [mode, setMode] = createSignal<MenuMode>(false)
  const [at, setAt] = createSignal(0)
  const [query, setQuery] = createSignal("")
  const visible = createMemo(() => mode() !== false)

  const setShellMode = (value: boolean) => {
    revision += 1
    setShell(value)
    draft = value ? { ...draft, mode: "shell" } : { text: draft.text, parts: structuredClone(draft.parts) }
  }

  const width = createMemo(() => Math.max(0, input.width() - (input.width() < FOOTER_COMPACT_WIDTH ? 2 : 4)))
  const agents = createMemo<Auto[]>(() => {
    return input
      .agents()
      .filter((item) => !item.hidden && item.mode !== "primary")
      .map((item) => ({
        kind: "mention",
        display: "@" + item.name,
        value: item.id,
        part: {
          type: "agent",
          name: item.id,
          source: {
            start: 0,
            end: 0,
            value: "",
          },
        },
      }))
  })
  const references = createMemo<Auto[]>(() => {
    return input.references().map((item) => ({
      kind: "mention",
      display: "@" + item.name,
      value: item.name,
      description: item.description ?? (item.source.type === "git" ? item.source.repository : item.source.path),
      part: {
        type: "file",
        mime: "application/x-directory",
        filename: item.name,
        url: pathToFileURL(item.path).href,
        source: {
          type: "file",
          path: item.name,
          text: {
            start: 0,
            end: 0,
            value: "",
          },
        },
      },
    }))
  })
  const [fileResults] = createResource(
    query,
    async (value) => {
      if (!visible() || mode() !== "mention") {
        return []
      }

      const next = parseFileLineRange(value)
      const list = await input.findFiles(next.base)
      return list.map((item): Auto => {
        const url = pathToFileURL(path.resolve(input.directory(), item))
        let filename = item
        if (next.lineRange && !item.endsWith("/")) {
          filename = `${item}#${next.lineRange.startLine}${next.lineRange.endLine ? `-${next.lineRange.endLine}` : ""}`
          url.searchParams.set("start", String(next.lineRange.startLine))
          if (next.lineRange.endLine !== undefined) {
            url.searchParams.set("end", String(next.lineRange.endLine))
          }
        }

        return {
          kind: "mention",
          display: "@" + filename,
          value: filename,
          directory: item.endsWith("/"),
          part: {
            type: "file",
            mime: item.endsWith("/") ? "application/x-directory" : "text/plain",
            filename,
            url: url.href,
            source: {
              type: "file",
              path: item,
              text: {
                start: 0,
                end: 0,
                value: "",
              },
            },
          },
        }
      })
    },
    { initialValue: [] as Auto[] },
  )
  const files = createMemo(() =>
    fileResults().map((item) => {
      const parts = item.value.split("/")
      const paths = parts
        .slice(0, item.directory ? -1 : undefined)
        .map((_, index) => "@" + parts.slice(index).join("/"))
      return { ...item, display: paths.find((value) => stringWidth(value) <= width()) ?? paths.at(-1) ?? item.display }
    }),
  )
  const mentionOptions = createMemo(() => [...agents(), ...files(), ...references()])
  const slashOptions = createMemo<SlashOption[]>(() => {
    const builtins = [
      {
        kind: "slash",
        action: "editor" as const,
        name: "editor",
        display: "/editor",
        description: "compose in your external editor",
      } satisfies SlashOption,
      {
        kind: "slash",
        action: "settings" as const,
        name: "settings",
        display: "/settings",
        description: "configure Mini transcript output",
      } satisfies SlashOption,
      { kind: "slash", name: "new", display: "/new", description: "start a new session" } satisfies SlashOption,
      {
        kind: "slash",
        name: "compact",
        display: "/compact",
        description: "compact older session context to free space",
      } satisfies SlashOption,
      ...EXIT_COMMANDS.map(
        (name) => ({ kind: "slash", name, display: `/${name}`, description: "close OpenCode" }) satisfies SlashOption,
      ),
    ]
    const hidden = new Set(builtins.map((item) => item.name))
    return [
      ...(input.commands() ?? [])
        .filter((item) => !hidden.has(item.name))
        .map(
          (item) =>
            ({
              kind: "slash",
              name: item.name,
              display: `/${item.name}${item.source === "mcp" ? ":mcp" : ""}`,
              description: item.description,
            }) satisfies SlashOption,
        ),
      ...builtins,
    ].sort((a, b) => a.display.localeCompare(b.display))
  })
  const options = createMemo<PromptOption[]>(() => {
    const mixed: PromptOption[] = mode() === "slash" ? slashOptions() : mentionOptions()
    if (!query()) {
      return mixed
    }

    const next = stripFileLineRange(query())
    if (mode() === "mention") {
      return [
        ...fuzzysort.go(next, agents(), { keys: ["value", "display", "description"] }).map((item) => item.obj),
        ...files(),
        ...fuzzysort.go(next, references(), { keys: ["value", "display", "description"] }).map((item) => item.obj),
      ]
    }

    return fuzzysort
      .go(next, mixed, {
        keys: [(item) => (item.kind === "mention" ? item.value : item.name).trimEnd(), "display", "description"],
      })
      .map((item) => item.obj)
  })
  const layout = createMemo(() => {
    term()
    return footerPromptLayout(
      renderer.terminalHeight,
      lines(),
      visible() ? Math.max(1, options().length) : 0,
      statusRows(),
      input.imagePreview === true && !input.mono() && !shell() && images().length > 0,
    )
  })
  const menu = createFooterMenuState({ count: () => options().length, limit: () => Math.max(1, layout().menu) })

  const hide = () => {
    setMode(false)
    setQuery("")
    menu.reset()
  }

  const syncRows = () => {
    if (!area || area.isDestroyed) {
      return
    }

    setLines(Math.max(area.lineCount, area.virtualLineCount))
    input.onRows(layout().rows)
  }

  const scheduleRows = () => {
    if (tick) {
      return
    }

    tick = true
    queueMicrotask(() => {
      tick = false
      syncRows()
    })
  }

  const syncParts = () => {
    if (!area || area.isDestroyed || type === 0) {
      return
    }

    const next = parts.map<Mention | undefined>((part) =>
      part.type === "file" && !part.source?.text ? part : undefined,
    )
    let tracked = 0
    for (const item of area.extmarks.getAllForTypeId(type)) {
      const idx = marks.get(item.id)
      if (idx === undefined) {
        continue
      }

      const part = parts[idx]
      if (!part) {
        continue
      }

      const text = displaySlice(area.plainText, item.start, item.end)
      const prev =
        part.type === "agent"
          ? (part.source?.value ?? "@" + part.name)
          : part.type === "skill"
            ? (part.source?.value ?? "/" + part.id)
            : (part.source?.text.value ?? "@" + (part.filename ?? ""))
      if (text !== prev) {
        continue
      }

      const copy = structuredClone(part)
      if (copy.type === "agent" || copy.type === "skill") {
        copy.source = {
          start: item.start,
          end: item.end,
          value: text,
        }
      }
      if (copy.type === "file" && copy.source?.text) {
        copy.source.text.start = item.start
        copy.source.text.end = item.end
        copy.source.text.value = text
      }

      tracked += 1
      next[idx] = copy
    }

    const retained = next.filter((part): part is Mention => part !== undefined)
    const stale = tracked !== marks.size || retained.length !== parts.length
    parts = retained
    if (stale) {
      restoreParts(retained)
    }
  }

  const clearParts = () => {
    if (area && !area.isDestroyed) {
      area.extmarks.clear()
    }
    parts = []
    marks = new Map()
    setDraftParts([])
  }

  const restoreParts = (value: RunPromptPart[]) => {
    clearParts()
    parts = value
      .filter((item): item is Mention => item.type === "file" || item.type === "agent" || item.type === "skill")
      .map((item) => structuredClone(item))
    setDraftParts(parts)
    if (!area || area.isDestroyed || type === 0) {
      return
    }

    const box = area
    parts.forEach((item, idx) => {
      const start = item.type === "file" ? item.source?.text.start : item.source?.start
      const end = item.type === "file" ? item.source?.text.end : item.source?.end
      if (start === undefined || end === undefined) {
        return
      }

      const id = box.extmarks.create({
        start,
        end,
        virtual: true,
        typeId: type,
      })
      marks.set(id, idx)
    })
  }

  const restore = (value: RunPrompt, cursor = stringWidth(value.text)) => {
    revision += 1
    draft = promptCopy(value)
    setShell(value.mode === "shell")
    if (!area || area.isDestroyed) {
      return
    }

    hide()
    area.setText(value.text)
    restoreParts(value.parts)
    area.cursorOffset = Math.min(cursor, stringWidth(area.plainText))
    scheduleRows()
    area.focus()
  }

  const resetDraft = () => {
    revision += 1
    if (area && !area.isDestroyed) {
      area.setText("")
    }

    clearParts()
    hide()
    draft = emptyPrompt(shell())
    if (!area || area.isDestroyed) {
      return
    }

    scheduleRows()
    area.focus()
  }

  const refresh = () => {
    if (!area || area.isDestroyed) {
      return
    }

    const cursor = area.cursorOffset
    const text = area.plainText
    const slash = slashQuery(text, cursor)
    if (mode() === "slash") {
      if (slash === undefined) {
        hide()
        return
      }

      setAt(slash.at)
      setQuery(slash.value)
      return
    }

    if (slash !== undefined) {
      setAt(slash.at)
      menu.reset()
      setMode("slash")
      setQuery(slash.value)
      return
    }

    if (visible() && mode() === "mention") {
      const query = displaySlice(text, at(), cursor)
      if (cursor <= at() || /\s/.test(query)) {
        hide()
        return
      }

      setQuery(displaySlice(text, at() + 1, cursor))
      return
    }

    if (cursor === 0) {
      return
    }

    const idx = mentionTriggerIndex(text, cursor)
    if (idx !== undefined) {
      setAt(idx)
      menu.reset()
      setMode("mention")
      setQuery(displaySlice(text, idx + 1, cursor))
    }
  }

  const bind = (next?: TextareaRenderable) => {
    if (area === next) {
      return
    }

    if (area && !area.isDestroyed) {
      area.off("line-info-change", scheduleRows)
    }

    area = next
    if (!area || area.isDestroyed) {
      return
    }

    if (type === 0) {
      type = area.extmarks.registerType("run-direct-prompt-part")
    }
    area.on("line-info-change", scheduleRows)
    queueMicrotask(() => {
      if (!area || area.isDestroyed || !input.prompt()) {
        return
      }

      restore(draft)
      refresh()
    })
  }

  const syncDraft = () => {
    if (!area || area.isDestroyed) {
      return
    }

    syncParts()
    setDraftParts(parts)
    const command = shell() ? undefined : selectedCommand(area.plainText, draft.command)
    draft = shell()
      ? {
          text: area.plainText,
          parts: structuredClone(parts),
          mode: "shell",
        }
      : {
          text: area.plainText,
          parts: structuredClone(parts),
          ...(command ? { command } : {}),
        }
  }

  const pasteAttachment = (file: { uri: string; filename?: string }) => {
    if (!area || area.isDestroyed) return
    syncDraft()
    const value = promptAttachmentLabel(attachments(), { uri: file.uri, name: file.filename })
    area.insertText(value + " ")
    const end = area.cursorOffset - 1
    const start = end - stringWidth(value)
    const id = area.extmarks.create({ start, end, virtual: true, typeId: type })
    marks.set(id, parts.length)
    parts.push({
      type: "file",
      url: file.uri,
      filename: file.filename,
      mime: file.uri.slice(5, file.uri.indexOf(";")),
      source: { type: "file", text: { start, end, value } },
    })
    syncDraft()
  }

  const paste = (text?: string) => {
    const next = (pasteQueue ?? Promise.resolve())
      .then(async () => {
        const target = area
        if (disposed || !target || target.isDestroyed || !input.prompt()) return
        const before = revision
        const changed = () =>
          disposed || area !== target || target.isDestroyed || revision !== before || !input.prompt()
        const content =
          text === undefined
            ? await (input.clipboard ?? (clipboard ??= createTuiClipboard(renderer))).read()
            : { mime: "text/plain", data: text }
        if (!content || changed()) return
        const image = content.mime.startsWith("image/")
        if (image && shell()) {
          input.onStatus("image attachments are unavailable in shell mode")
          return
        }
        if (!image && content.mime !== "text/plain") return
        const normalized = image ? content.data : stripAnsiSequences(content.data).replace(/\r\n?/g, "\n")
        const files = image
          ? [{ type: "file" as const, uri: `data:${content.mime};base64,${content.data}`, filename: "clipboard" }]
          : shell()
            ? undefined
            : await resolvePastedAttachments(normalized, process.platform)
        if (changed()) return
        // A paste's own text edits must not cancel a submit waiting on that paste.
        applyingPaste = true
        try {
          files?.forEach((file) => {
            if (file.type === "file") {
              pasteAttachment(file)
              return
            }
            target.insertText(file.content)
          })
          if (!files) target.insertText(normalized)
        } finally {
          applyingPaste = false
        }
        hide()
        syncDraft()
        target.getLayoutNode().markDirty()
        renderer.requestRender()
        scheduleRows()
      })
      .catch((error) => {
        revision += 1
        if (!disposed) input.onStatus(errorMessage(error))
      })
      .finally(() => {
        if (pasteQueue === next) pasteQueue = undefined
      })
    pasteQueue = next
    return next
  }

  const onPaste = (event: PasteEvent) => {
    event.preventDefault()
    return paste(event.bytes.length ? decodePasteBytes(event.bytes) : undefined)
  }

  const push = (value: RunPrompt) => {
    history = pushPromptHistory(history, value)
  }

  const move = (dir: -1 | 1, event: KeyEvent) => {
    if (!area || area.isDestroyed) {
      return false
    }

    if (history.index === null && dir === -1) {
      stash = promptCopy(draft)
    }

    const next = movePromptHistory(history, dir, area.plainText, area.cursorOffset)
    if (!next.apply || next.text === undefined || next.cursor === undefined) {
      return false
    }

    history = next.state
    const value =
      next.state.index === null ? stash : (next.state.items[next.state.index] ?? { text: next.text, parts: [] })
    restore(value, next.cursor)
    event.preventDefault()
    return true
  }

  const historyCommand = (dir: -1 | 1, event: KeyEvent) => {
    if (move(dir, event)) return
    if (!area || area.isDestroyed) return false

    const endOffset = stringWidth(area.plainText)
    if (dir === -1) {
      if (area.cursorOffset === 0) return false
      if (area.visualCursor.visualRow === 0) {
        area.cursorOffset = 0
        return
      }
      area.moveCursorUp()
      return
    }

    const end =
      typeof area.height === "number" && Number.isFinite(area.height) && area.height > 0
        ? area.height - 1
        : Math.max(0, (area.virtualLineCount ?? 1) - 1)
    if (area.cursorOffset === endOffset) return false
    if (area.visualCursor.visualRow === end) {
      area.cursorOffset = endOffset
      return
    }
    area.moveCursorDown()
  }

  const requestExit = () => {
    const text = area && !area.isDestroyed ? area.plainText : draft.text
    revision += 1
    if (input.prompt() && (text.length > 0 || draft.parts.some((part) => part.type === "file"))) {
      input.onInputClear()
      resetDraft()
      return true
    }

    return input.onExitRequest ? input.onExitRequest() : (input.onExit(), true)
  }

  const cancelAutocomplete = () => {
    if (!area || area.isDestroyed) {
      return
    }

    const cursor = area.cursorOffset
    const startOffset = at()
    area.cursorOffset = startOffset
    const start = area.logicalCursor
    area.cursorOffset = cursor
    const end = area.logicalCursor
    area.deleteRange(start.row, start.col, end.row, end.col)
    area.cursorOffset = startOffset
    hide()
    syncDraft()
    scheduleRows()
    area.focus()
  }

  const openEditor = async (inputValue?: { value?: string }) => {
    input.onInputClear()
    syncDraft()
    hide()

    const current = promptCopy(draft)
    try {
      const content = await input.onEditorOpen({
        value: inputValue?.value ?? current.text,
      })
      if (content === undefined) {
        return
      }
      const normalized = normalizePromptContent(content)

      restore({
        text: normalized,
        parts: realignEditorPromptParts(normalized, current.parts),
        ...(current.mode ? { mode: current.mode } : {}),
        ...(current.command ? { command: current.command } : {}),
      })
    } catch {
      restore(current)
      input.onStatus("failed to open editor")
    }
  }

  const select = (item?: PromptOption, delivery: RunDelivery = "steer") => {
    const next = item ?? options()[menu.selected()]
    if (!next || !area || area.isDestroyed) {
      return
    }

    if (next.kind === "slash") {
      if (next.action === "editor") {
        void openEditor({
          value: resolveEditorSlashValue(area.plainText),
        })
        return
      }

      if (next.action === "settings" && !shell()) {
        cancelAutocomplete()
        input.onSettings()
        return
      }

      const cursor = area.cursorOffset
      const head = parseSlashHead(area.plainText)
      const local = !shell() && (next.name === "new" || isExitCommand(`/${next.name}`))
      const separator = !shell() && !local && head && /\s/.test(area.plainText[head.end] ?? "") ? "" : " "
      const text = `/${next.name}${separator}`

      area.cursorOffset = 0
      const start = area.logicalCursor
      area.cursorOffset =
        shell() || !head ? cursor : local ? stringWidth(area.plainText) : stringWidth(area.plainText.slice(0, head.end))
      const end = area.logicalCursor

      area.deleteRange(start.row, start.col, end.row, end.col)
      area.insertText(text)
      area.cursorOffset = stringWidth(text)
      hide()
      syncDraft()
      if (!shell()) {
        submitPrompt(promptCopy(draft), delivery)
        return
      }

      scheduleRows()
      area.focus()
      return
    }

    const cursor = area.cursorOffset
    const tail = displayCharAt(area.plainText, cursor)
    const append = "@" + next.value + (tail === " " ? "" : " ")
    area.cursorOffset = at()
    const start = area.logicalCursor
    area.cursorOffset = cursor
    const end = area.logicalCursor
    area.deleteRange(start.row, start.col, end.row, end.col)
    area.insertText(append)

    const text = "@" + next.value
    const startOffset = at()
    const endOffset = startOffset + stringWidth(text)
    const part = structuredClone(next.part)
    if (part.type === "agent") {
      part.source = {
        start: startOffset,
        end: endOffset,
        value: text,
      }
    }
    if (part.type === "file" && part.source?.text) {
      part.source.text.start = startOffset
      part.source.text.end = endOffset
      part.source.text.value = text
    }

    if (part.type === "file") {
      const prev = parts.findIndex((item) => item.type === "file" && item.url === part.url)
      if (prev !== -1) {
        const mark = [...marks.entries()].find((item) => item[1] === prev)?.[0]
        if (mark !== undefined) {
          area.extmarks.delete(mark)
        }
        parts = parts.filter((_, idx) => idx !== prev)
        marks = new Map(
          [...marks.entries()]
            .filter((item) => item[0] !== mark)
            .map((item) => [item[0], item[1] > prev ? item[1] - 1 : item[1]]),
        )
      }
    }

    const id = area.extmarks.create({
      start: startOffset,
      end: endOffset,
      virtual: true,
      typeId: type,
    })
    marks.set(id, parts.length)
    parts.push(part)
    hide()
    syncDraft()
    scheduleRows()
    area.focus()
  }

  const expand = () => {
    const next = options()[menu.selected()]
    if (!next || next.kind !== "mention" || !next.directory || !area || area.isDestroyed) {
      return
    }

    const cursor = area.cursorOffset
    area.cursorOffset = at()
    const start = area.logicalCursor
    area.cursorOffset = cursor
    const end = area.logicalCursor
    area.deleteRange(start.row, start.col, end.row, end.col)
    area.insertText("@" + next.value)
    syncDraft()
    refresh()
  }

  const baseBindingsEnabled = () => {
    const current = input.view()
    if (current === "command") return false
    if (current === "skill") return false
    if (current === "model") return false
    if (current === "variant") return false
    if (current === "settings") return false
    if (current === "queued-menu") return false
    if (current === "subagent-menu") return false
    return true
  }

  Keymap.createLayer(() => ({
    enabled: baseBindingsEnabled(),
    commands: [
      {
        id: "prompt.clear",
        title: "Clear prompt or exit",
        group: "Prompt",
        run() {
          if (requestExit()) return
          return false
        },
      },
    ],
  }))

  Keymap.createLayer(() => ({
    enabled: input.prompt(),
    commands: [
      {
        id: "prompt.paste",
        title: "Paste",
        group: "Prompt",
        run: () => paste(),
      },
      {
        id: "session.interrupt",
        title: "Interrupt session",
        group: "Session",
        run() {
          if (input.onInterrupt()) return
          return false
        },
      },
    ],
  }))

  Keymap.createLayer(() => ({
    priority: 1,
    enabled: input.prompt() && (!visible() || mode() === "slash"),
    commands: [
      {
        id: "prompt.queue",
        title: "Queue prompt",
        group: "Prompt",
        palette: true,
        run() {
          onSubmit("queue")
        },
      },
    ],
  }))

  Keymap.createLayer(() => ({
    priority: 1,
    enabled: input.prompt() && !visible(),
    commands: [
      {
        id: "prompt.editor",
        title: "Open editor",
        group: "Prompt",
        run() {
          void openEditor()
        },
      },
    ],
  }))

  Keymap.createLayer(() => ({
    priority: 1,
    enabled: input.prompt() && !visible(),
    commands: [
      {
        id: "prompt.history.previous",
        title: "Previous prompt history",
        group: "Prompt",
        run(_input: string | undefined, event?: KeyEvent) {
          if (!event) return false
          return historyCommand(-1, event)
        },
      },
      {
        id: "prompt.history.next",
        title: "Next prompt history",
        group: "Prompt",
        run(_input: string | undefined, event?: KeyEvent) {
          if (!event) return false
          return historyCommand(1, event)
        },
      },
    ],
  }))

  Keymap.createLayer(() => ({
    enabled: input.prompt() && !visible(),
    commands: [
      {
        bind: "!",
        title: "Shell mode",
        group: "Prompt",
        run() {
          if (shell()) return false
          if (!area || area.isDestroyed) return false
          if (area.cursorOffset !== 0) return false
          setShellMode(true)
        },
      },
    ],
  }))

  Keymap.createLayer(() => ({
    enabled: input.prompt() && shell() && !visible(),
    commands: [
      {
        bind: "escape",
        title: "Exit shell mode",
        group: "Prompt",
        run: () => setShellMode(false),
      },
      {
        bind: "backspace",
        title: "Exit shell mode",
        group: "Prompt",
        run() {
          if (!area || area.isDestroyed) return false
          if (area.cursorOffset !== 0) return false
          setShellMode(false)
        },
      },
    ],
  }))

  Keymap.createLayer(() => ({
    enabled: input.prompt() && visible(),
    commands: [
      {
        id: "prompt.autocomplete.prev",
        title: "Previous autocomplete item",
        group: "Autocomplete",
        run: () => menu.move(-1),
      },
      {
        id: "prompt.autocomplete.next",
        title: "Next autocomplete item",
        group: "Autocomplete",
        run: () => menu.move(1),
      },
      {
        id: "prompt.autocomplete.hide",
        title: "Hide autocomplete",
        group: "Autocomplete",
        run: cancelAutocomplete,
      },
      {
        id: "prompt.autocomplete.select",
        title: "Select autocomplete item",
        group: "Autocomplete",
        run() {
          if (mode() === "slash" && options().length === 0) {
            hide()
            return
          }
          select()
        },
      },
      {
        id: "prompt.autocomplete.complete",
        title: "Complete autocomplete item",
        group: "Autocomplete",
        run() {
          if (mode() === "slash" && options().length === 0) {
            hide()
            return
          }
          const item = options()[menu.selected()]
          if (item?.kind === "mention" && item.directory) {
            expand()
            return
          }
          select()
        },
      },
    ],
  }))

  const onKeyDown = (event: KeyEvent) => {
    if (input.state().phase === "idle" && event.name.toLowerCase() === "escape") {
      input.onInputClear()
    }
  }

  let submitting = false
  const submitPrompt = (next: RunPrompt, delivery: RunDelivery = "steer") => {
    if (!area || area.isDestroyed) {
      draft = promptCopy(next)
    }

    if (visible()) {
      if (mode() !== "slash" || options().length > 0) {
        select(undefined, delivery)
        return
      }

      hide()
    }

    if (submitting) return

    if (!next.text.trim() && !next.parts.some((part) => part.type === "file")) {
      const queued = delivery === "steer" ? input.queuedPrompts()[0] : undefined
      if (queued) {
        submitting = true
        void input.onQueuedPromptSteer(queued.messageID).finally(() => {
          submitting = false
        })
        return
      }
      input.onStatus(input.state().phase === "running" ? "waiting for current response" : "empty prompt ignored")
      return
    }

    const command = next.mode === "shell" ? undefined : selectedCommand(next.text, next.command)
    if (
      delivery === "queue" &&
      (next.mode === "shell" ||
        isNewCommand(next.text) ||
        isCompactCommand(next.text) ||
        isExitCommand(next.text) ||
        next.text.trim().toLowerCase() === "/settings")
    ) {
      input.onStatus("this prompt cannot be queued")
      return
    }
    if (!command && next.mode !== "shell" && isExitCommand(next.text)) {
      input.onExit()
      return
    }

    if (!command && next.mode !== "shell" && next.text.trim().toLowerCase() === "/settings") {
      resetDraft()
      input.onSettings()
      return
    }

    const parsed =
      command || next.parts.some((part) => part.type === "skill") || next.mode === "shell" || isNewCommand(next.text)
        ? undefined
        : parseSlashCommand(next.text, input.commands())
    if (parsed?.type === "pending") {
      input.onStatus("loading commands")
      return
    }

    const submit = command
      ? { ...next, command, delivery }
      : parsed?.type === "command"
        ? { ...next, command: parsed.command, delivery }
        : { ...next, delivery }
    const shellMode = next.mode === "shell"

    submitting = true
    resetDraft()
    queueMicrotask(async () => {
      try {
        if (await input.onSubmit(submit)) {
          push(next)
          if (shellMode) {
            setShellMode(false)
            draft = emptyPrompt(false)
          }
          return
        }
        restore(next)
      } finally {
        submitting = false
      }
    })
  }

  const onSubmit = (delivery: RunDelivery = "steer") => {
    if (pasteQueue) {
      const before = revision
      void pasteQueue.then(() => {
        if (revision === before) onSubmit(delivery)
      })
      return
    }
    if (disposed || !input.prompt()) return
    syncDraft()
    submitPrompt(promptCopy(draft), delivery)
  }

  const submitText = (text: string) => {
    submitPrompt({ text, parts: [] })
  }

  onCleanup(() => {
    disposed = true
    void clipboard?.dispose().catch(() => {})
    if (area && !area.isDestroyed) {
      area.off("line-info-change", scheduleRows)
    }
  })

  createEffect(() => {
    setStatusRows(input.statusRows())
  })

  createEffect(() => {
    input.width()
    layout()
    if (input.prompt()) {
      scheduleRows()
    }
  })

  createEffect(() => {
    query()
    menu.reset()
  })

  createEffect(() => {
    input.state().phase
    if (!input.prompt() || !area || area.isDestroyed || input.state().phase !== "idle") {
      return
    }

    queueMicrotask(() => {
      if (!area || area.isDestroyed) {
        return
      }

      area.focus()
    })
  })

  createEffect(() => {
    const kind = input.view()
    if (kind === prev) {
      return
    }

    if (prev === "prompt") {
      syncDraft()
    }

    hide()
    prev = kind
    if (kind !== "prompt") {
      return
    }

    queueMicrotask(() => {
      restore(draft)
    })
  })

  return {
    placeholder,
    shell,
    visible,
    options,
    selected: menu.selected,
    offset: menu.offset,
    rows: menu.rows,
    images,
    layout,
    requestExit,
    onSubmit: () => onSubmit(),
    submitText,
    openEditor,
    onKeyDown,
    onPaste,
    onContentChange: () => {
      if (!applyingPaste && area && area.plainText !== draft.text) revision += 1
      input.onInputClear()
      syncDraft()
      refresh()
      scheduleRows()
    },
    onSizeChange: scheduleRows,
    current: () => {
      syncDraft()
      return promptCopy(draft)
    },
    replacePrompt: restore,
    bind,
  }
}

/** @jsxImportSource @opentui/solid */
import type { ScrollBoxRenderable } from "@opentui/core"
import { useKeyboard, useTerminalDimensions } from "@opentui/solid"
import { registerOpencodeSpinner } from "../component/register-spinner"
import { Show, createMemo, createSignal, indexArray } from "solid-js"
import { SPINNER_FRAMES } from "../component/spinner-frames"
import { RunEntryContent, separatorRows } from "./scrollback.writer"
import type { FooterSubagentDetail, FooterSubagentTab } from "./types"
import type { RunFooterTheme, RunTheme } from "./theme"
import { stringWidth } from "../util/string-width"
import { footerMenuText } from "./footer.menu"

registerOpencodeSpinner()

export const SUBAGENT_INSPECTOR_ROWS = 14

function statusColor(theme: RunFooterTheme, status: FooterSubagentTab["status"]) {
  if (status === "completed") {
    return theme.success
  }

  if (status === "cancelled") {
    return theme.muted
  }

  if (status === "error") {
    return theme.error
  }

  return theme.running
}

function statusIcon(status: FooterSubagentTab["status"], mono: boolean) {
  if (status === "completed") {
    return mono ? "*" : "●"
  }

  if (status === "cancelled") {
    return mono ? "-" : "○"
  }

  if (status === "error") {
    return mono ? "!" : "◍"
  }

  return mono ? "." : "◔"
}

export function RunFooterSubagentBody(props: {
  active: () => boolean
  theme: () => RunTheme
  tab: () => FooterSubagentTab | undefined
  index: () => number
  total: () => number
  detail: () => FooterSubagentDetail | undefined
  onCycle: (dir: -1 | 1) => void
  onClose: () => void
  // Formatted interrupt shortcut from the registered keymap binding; the
  // command itself is dispatched through the keymap in footer.view.
  interrupt?: () => string | undefined
  shellOutput?: () => boolean
  mono?: boolean
}) {
  const dims = useTerminalDimensions()
  const [size, setSize] = createSignal(dims())
  const width = () => size().width
  const compact = () => width() < 56 || size().height < 12
  const theme = createMemo(() => props.theme())
  const footer = createMemo(() => theme().footer)
  const tab = createMemo(() => props.tab())
  const commits = createMemo(() => props.detail()?.commits ?? [])
  const scrollbar = createMemo(() => ({
    trackOptions: {
      backgroundColor: footer().surface,
      foregroundColor: footer().line,
    },
    visible: !props.mono,
  }))
  const title = createMemo(() => {
    const current = tab()
    if (!current) {
      return ""
    }

    return current.description || current.title || current.label
  })
  const subtitle = createMemo(() => {
    const current = tab()
    if (!current || title() === current.label) {
      return ""
    }

    return current.label
  })
  const rows = indexArray(commits, (commit, index) => (
    <box flexDirection="column" gap={0} flexShrink={0}>
      {index > 0 && separatorRows(commits()[index - 1], commit()) > 0 ? <box height={1} flexShrink={0} /> : null}
      <RunEntryContent
        commit={commit()}
        theme={theme()}
        opts={{ shellOutput: props.shellOutput?.() ?? true, mono: props.mono }}
      />
    </box>
  ))
  let scroll: ScrollBoxRenderable | undefined

  const interruptHint = createMemo(() => {
    if (tab()?.status !== "running") return undefined
    return props.interrupt?.()
  })
  const count = () => (props.total() > 1 && props.index() > 0 ? `${props.index()} of ${props.total()}` : "")
  const headerControlsWidth = () =>
    (interruptHint() ? stringWidth(`${interruptHint()} interrupt`) + 1 : 0) + (count() ? stringWidth(count()) + 1 : 0)
  const headerControls = () => !compact() && stringWidth(title()) + 2 + headerControlsWidth() <= width() - 4
  const titleWidth = () => Math.max(1, width() - (compact() ? 2 : 6) - (headerControls() ? headerControlsWidth() : 0))

  useKeyboard((event) => {
    if (!props.active()) {
      return
    }

    if (event.name === "escape") {
      event.preventDefault()
      props.onClose()
      return
    }

    if (event.name === "tab" && !event.shift) {
      event.preventDefault()
      props.onCycle(1)
      return
    }

    if (event.name === "up" || event.name === "k") {
      event.preventDefault()
      scroll?.scrollBy(-1)
      return
    }

    if (event.name === "down" || event.name === "j") {
      event.preventDefault()
      scroll?.scrollBy(1)
      return
    }

    if (event.name === "pageup" || event.name === "pagedown") {
      event.preventDefault()
      scroll?.scrollBy(event.name === "pageup" ? -1 : 1, "viewport")
    }
  })

  return (
    <box
      width="100%"
      height="100%"
      minHeight={0}
      flexDirection="column"
      backgroundColor={footer().surface}
      paddingTop={compact() ? 0 : 1}
      paddingLeft={compact() ? 0 : 1}
      paddingRight={compact() ? 0 : 3}
      paddingBottom={compact() ? 0 : 1}
      onSizeChange={function () {
        setSize({ width: this.width, height: this.height })
      }}
    >
      <Show when={tab()}>
        {(current) => (
          <box
            width="100%"
            height={compact() ? 1 : 2}
            paddingBottom={compact() ? 0 : 1}
            flexDirection="row"
            gap={1}
            flexShrink={0}
          >
            {current().status === "running" ? (
              <box flexShrink={0}>
                <spinner
                  frames={props.mono ? ["-", "\\", "|", "/"] : SPINNER_FRAMES}
                  interval={props.mono ? 160 : 80}
                  color={statusColor(footer(), current().status)}
                />
              </box>
            ) : (
              <text fg={statusColor(footer(), current().status)} wrapMode="none" truncate flexShrink={0}>
                {statusIcon(current().status, props.mono ?? false)}
              </text>
            )}
            <text fg={footer().text} wrapMode="none" flexGrow={1} flexShrink={1}>
              {footerMenuText(title(), titleWidth(), props.mono)}
              <Show when={subtitle().length > 0 && titleWidth() >= stringWidth(title()) + stringWidth(subtitle()) + 2}>
                <span style={{ fg: footer().muted }}>{"  " + subtitle()}</span>
              </Show>
            </text>
            <Show when={headerControls()}>
              <Show when={interruptHint()}>
                {(hint) => (
                  <text fg={footer().muted} wrapMode="none" flexShrink={0}>
                    {hint()} interrupt
                  </text>
                )}
              </Show>
              <Show when={count()}>
                {(value) => (
                  <text fg={footer().muted} wrapMode="none" flexShrink={0}>
                    {value()}
                  </text>
                )}
              </Show>
            </Show>
          </box>
        )}
      </Show>
      <scrollbox
        width="100%"
        flexGrow={1}
        minHeight={0}
        stickyScroll={true}
        stickyStart="bottom"
        verticalScrollbarOptions={scrollbar()}
        viewportOptions={{ paddingRight: props.mono ? 0 : 1 }}
        ref={(item) => {
          scroll = item
        }}
      >
        <box width="100%" flexDirection="column" gap={0} flexShrink={0}>
          {commits().length > 0 ? (
            rows()
          ) : (
            <text width="100%" fg={footer().muted} wrapMode="word" flexShrink={0}>
              No subagent activity yet
            </text>
          )}
        </box>
      </scrollbox>
      <Show when={!headerControls()}>
        <box width="100%" flexDirection="row" flexWrap="wrap" columnGap={1} flexShrink={0}>
          <text height={1} fg={footer().actionSecondaryText} wrapMode="none" flexShrink={0} onMouseUp={props.onClose}>
            esc back
          </text>
          <Show when={interruptHint()}>
            {(hint) => (
              <text maxWidth="100%" fg={footer().actionSecondaryText} wrapMode="word" flexShrink={0}>
                {hint()} {width() >= stringWidth(hint()) + 10 ? "interrupt" : "stop"}
              </text>
            )}
          </Show>
          <Show when={width() >= 56}>
            <text height={1} fg={footer().muted} wrapMode="none" flexShrink={0}>
              pgup/pgdn scroll
            </text>
            <Show when={props.total() > 1 && props.index() > 0}>
              <text
                height={1}
                fg={footer().actionSecondaryText}
                wrapMode="none"
                flexShrink={0}
                onMouseUp={() => props.onCycle(1)}
              >
                tab next {props.index()}/{props.total()}
              </text>
            </Show>
          </Show>
        </box>
      </Show>
    </box>
  )
}

// RunFooter -- the mutable control surface for direct interactive mode.
//
// In the split-footer architecture, scrollback is immutable (append-only)
// and the footer is the only region that can repaint. RunFooter owns both
// sides of that boundary:
//
//   Scrollback: append() queues StreamCommit entries and flush() drains them
//   through retained scrollback surfaces. Commits coalesce in a microtask
//   queue so direct-mode transcript updates still preserve ordering without
//   rebuilding the session model.
//
//   Footer: event() updates the SolidJS signal-backed FooterState, which
//   drives the reactive footer view (prompt, status, permission, form).
//   present() swaps the active footer view and resizes the footer region.
//
// Lifecycle:
//   - close() flushes pending commits and notifies listeners (the prompt
//     queue uses this to know when to stop).
//   - destroy() does the same plus tears down event listeners and clears
//     internal state.
//   - The renderer's DESTROY event triggers destroy() so the footer
//     doesn't outlive the renderer.
//
// Ctrl-c clears a live prompt draft first; otherwise interrupt and exit use a
// two-press pattern where the first press shows a hint and the second press
// within 5 seconds actually fires the action.
import { CliRenderEvents, type CliRenderer, type CliRendererExternalOutputEvent } from "@opentui/core"
import { render } from "@opentui/solid"
import { batch, createComponent, createSignal, type Accessor, type Setter } from "solid-js"
import { createStore, reconcile } from "solid-js/store"
import { Keymap } from "../context/keymap"
import { Locale } from "../util/locale"
import { RUN_SUBAGENT_PANEL_ROWS, footerPanelLayout } from "./footer.command"
import { SUBAGENT_INSPECTOR_ROWS } from "./footer.subagent"
import { TEXTAREA_MIN_ROWS, footerPromptLayout } from "./footer.prompt"
import { RunFooterView } from "./footer.view"
import { monoSnapshot } from "./mono"
import { RunScrollbackStream } from "./scrollback.surface"
import { resolveRunTheme, type RunTheme } from "./theme"
import { modelInfo } from "./variant.shared"
import { entrySplash } from "./splash"
import { SEED_LAUNCH } from "../ui/one-cell-motion"
import type {
  FooterApi,
  FooterEvent,
  FooterPatch,
  FooterPromptRoute,
  FooterQueuedPrompt,
  FooterState,
  FooterSubagentState,
  FooterView,
  FormCancel,
  FormReply,
  MiniSettingChange,
  MiniSettings,
  PermissionReply,
  QueuedPromptAction,
  RunAgent,
  RunCommand,
  RunInput,
  RunPrompt,
  RunProvider,
  RunReference,
  RunTuiConfig,
  StreamCommit,
} from "./types"

type CycleResult = {
  modelLabel?: string
  status?: string
  variant?: string | undefined
  variants?: string[]
}

type RunFooterOptions = {
  directory: () => string
  findFiles: (query: string) => Promise<string[]>
  agents: RunAgent[]
  references: RunReference[]
  wrote?: boolean
  startup?: { version: string; detail: string }
  agent: string | undefined
  modelLabel: string
  model: RunInput["model"]
  variant: string | undefined
  first: boolean
  history?: RunPrompt[]
  theme: RunTheme
  tuiConfig: RunTuiConfig
  miniSettings: {
    current: MiniSettings
    update?: (change: MiniSettingChange) => Promise<MiniSettings>
  }
  onMonoChange?: (mono: boolean) => void
  onPermissionReply: (input: PermissionReply) => void | Promise<void>
  onFormReply: (input: FormReply) => void | Promise<void>
  onFormCancel: (input: FormCancel) => void | Promise<void>
  onCycleVariant?: () => CycleResult | void
  onAgentSelect?: (agent: string) => void
  onModelSelect?: (model: NonNullable<RunInput["model"]>) => CycleResult | void | Promise<CycleResult | void>
  onVariantSelect?: (variant: string | undefined) => CycleResult | void | Promise<CycleResult | void>
  onInterrupt?: () => void
  onBackground?: () => void
  onQueuedPromptAction?: (action: QueuedPromptAction, inboxID: string) => Promise<void>
  onEditorOpen: (input: { value: string }) => Promise<string | undefined>
  onSubagentSelect?: (sessionID: string | undefined) => void
  onSubagentInterrupt?: (sessionID: string) => void
  subscribeThemeSignal: (listener: () => void) => () => void
}

export function resolveRunAgent(agents: RunAgent[], current: string | undefined) {
  const selectable = agents.filter((agent) => agent.mode !== "subagent" && !agent.hidden)
  if (current === undefined) return selectable.at(0)
  return selectable.find((agent) => agent.id === current)
}

const PERMISSION_ROWS = 12
const FORM_ROWS = 14
const SUBAGENT_ROWS = RUN_SUBAGENT_PANEL_ROWS
const NOTICE_DURATION = 3000
const THEME_REFRESH_DELAYS = [1000, 1000] as const

function createEmptySubagentState(): FooterSubagentState {
  return {
    tabs: [],
    details: {},
    permissions: [],
    forms: [],
  }
}

function eventPatch(next: FooterEvent): FooterPatch | undefined {
  if (next.type === "first") {
    return { first: next.first }
  }

  if (next.type === "model") {
    return { model: next.model }
  }

  if (next.type === "turn.send") {
    return {
      phase: "running",
      status: "sending prompt",
      interrupt: 0,
      exit: 0,
    }
  }

  if (next.type === "turn.idle") {
    return {
      phase: "idle",
      status: "",
    }
  }

  if (next.type === "stream.patch") {
    return next.patch
  }

  return undefined
}

export class RunFooter implements FooterApi {
  private closed = false
  private destroyed = false
  private prompts = new Set<(input: RunPrompt) => void>()
  private closes = new Set<() => void>()
  // Microtask-coalesced commit queue. Flushed on next microtask or on close/destroy.
  private queue: StreamCommit[] = []
  private pending = false
  private flushing: Promise<void> = Promise.resolve()
  private flushError: unknown
  // Fixed portion of footer height above the textarea.
  private base: number
  private rows = TEXTAREA_MIN_ROWS
  private agents: Accessor<RunAgent[]>
  private setAgents: Setter<RunAgent[]>
  private references: Accessor<RunReference[]>
  private setReferences: Setter<RunReference[]>
  private commands: Accessor<RunCommand[] | undefined>
  private setCommands: Setter<RunCommand[] | undefined>
  private providers: Accessor<RunProvider[] | undefined>
  private setProviders: Setter<RunProvider[] | undefined>
  private currentAgent: Accessor<string>
  private currentAgentID: Accessor<string | undefined>
  private setCurrentAgentID: Setter<string | undefined>
  private currentModel: Accessor<RunInput["model"]>
  private setCurrentModel: Setter<RunInput["model"]>
  private variants: Accessor<string[]>
  private setVariants: Setter<string[]>
  private currentVariant: Accessor<string | undefined>
  private setCurrentVariant: Setter<string | undefined>
  private theme: Accessor<RunTheme>
  private setTheme: Setter<RunTheme>
  private state: Accessor<FooterState>
  private setState: Setter<FooterState>
  private view: Accessor<FooterView>
  private setView: Setter<FooterView>
  private subagent: Accessor<FooterSubagentState>
  private setSubagent: (next: FooterSubagentState) => void
  private queuedPrompts: Accessor<FooterQueuedPrompt[]>
  private setQueuedPrompts: Setter<FooterQueuedPrompt[]>
  private history: Accessor<RunPrompt[]>
  private setHistory: Setter<RunPrompt[]>
  private miniSettings: Accessor<MiniSettings>
  private setMiniSettings: Setter<MiniSettings>
  private promptRoute: FooterPromptRoute = { type: "composer" }
  private subagentMenuRows = SUBAGENT_ROWS
  private interruptTimeout: NodeJS.Timeout | undefined
  private exitTimeout: NodeJS.Timeout | undefined
  private noticeTimeout: NodeJS.Timeout | undefined
  private turnAgent: string | undefined
  private requestExitHandler: (() => boolean) | undefined
  private startup: Accessor<RunFooterOptions["startup"]>
  private setStartup: Setter<RunFooterOptions["startup"]>
  private startupTimer: ReturnType<typeof setTimeout> | undefined
  private scrollback: RunScrollbackStream
  private themes: RunTheme[]
  private paletteRefreshRunning = false
  private paletteRefreshQueued = false
  private themeRefreshTimeouts: NodeJS.Timeout[] = []
  private unsubscribeThemeSignal = () => {}

  private createScrollback(wrote: boolean): RunScrollbackStream {
    return new RunScrollbackStream(this.renderer, this.theme(), {
      wrote,
      onThemeRelease: (theme) => {
        void this.renderer
          .idle()
          .catch(() => {})
          .finally(() => this.destroyTheme(theme))
      },
      shellOutput: () => this.miniSettings().shell_output === "show",
      mono: this.miniSettings().mono,
      imagePreview: this.options.tuiConfig.session?.image_preview,
    })
  }

  constructor(
    private renderer: CliRenderer,
    private options: RunFooterOptions,
  ) {
    const [state, setState] = createSignal<FooterState>({
      phase: "idle",
      status: "",
      notice: "",
      model: options.modelLabel,
      usage: undefined,
      first: options.first,
      interrupt: 0,
      exit: 0,
    })
    this.state = state
    this.setState = setState
    const [view, setView] = createSignal<FooterView>({ type: "prompt" })
    this.view = view
    this.setView = setView
    const [agents, setAgents] = createSignal(options.agents)
    this.agents = agents
    this.setAgents = setAgents
    const [references, setReferences] = createSignal(options.references)
    this.references = references
    this.setReferences = setReferences
    const [commands, setCommands] = createSignal<RunCommand[] | undefined>()
    this.commands = commands
    this.setCommands = setCommands
    const [providers, setProviders] = createSignal<RunProvider[] | undefined>()
    this.providers = providers
    this.setProviders = setProviders
    const [selectedAgentID, setCurrentAgentID] = createSignal(options.agent)
    const currentAgent = () => resolveRunAgent(this.agents(), selectedAgentID())
    this.currentAgentID = () => currentAgent()?.id ?? selectedAgentID()
    this.setCurrentAgentID = setCurrentAgentID
    this.currentAgent = () => {
      const agent = currentAgent()
      if (agent) return agent.name
      const selected = selectedAgentID()
      return selected ? Locale.titlecase(selected) : "Default"
    }
    const [currentModel, setCurrentModel] = createSignal<RunInput["model"]>(options.model)
    this.currentModel = currentModel
    this.setCurrentModel = setCurrentModel
    const [variants, setVariants] = createSignal<string[]>([])
    this.variants = variants
    this.setVariants = setVariants
    const [currentVariant, setCurrentVariant] = createSignal(options.variant)
    this.currentVariant = currentVariant
    this.setCurrentVariant = setCurrentVariant
    const [theme, setTheme] = createSignal(options.theme)
    this.theme = theme
    this.setTheme = setTheme
    this.themes = [options.theme]
    const [subagent, setSubagent] = createStore<FooterSubagentState>(createEmptySubagentState())
    this.subagent = () => subagent
    this.setSubagent = (next) => {
      setSubagent("tabs", reconcile(next.tabs, { key: "sessionID" }))
      setSubagent("details", reconcile(next.details))
      setSubagent("permissions", reconcile(next.permissions, { key: "id" }))
      setSubagent("forms", reconcile(next.forms, { key: "id" }))
    }
    const [queuedPrompts, setQueuedPrompts] = createSignal<FooterQueuedPrompt[]>([])
    this.queuedPrompts = queuedPrompts
    this.setQueuedPrompts = setQueuedPrompts
    const [history, setHistory] = createSignal(options.history ?? [])
    this.history = history
    this.setHistory = setHistory
    const [miniSettings, setMiniSettings] = createSignal(options.miniSettings.current)
    this.miniSettings = miniSettings
    this.setMiniSettings = setMiniSettings
    const [startup, setStartup] = createSignal(options.startup)
    this.startup = startup
    this.setStartup = setStartup
    this.base = Math.max(1, renderer.footerHeight - TEXTAREA_MIN_ROWS)
    this.scrollback = this.createScrollback(options.wrote ?? false)

    this.renderer.on(CliRenderEvents.DESTROY, this.handleDestroy)
    this.renderer.on(CliRenderEvents.RESIZE, this.handleResize)
    this.renderer.on(CliRenderEvents.EXTERNAL_OUTPUT, this.handleExternalOutput)
    this.renderer.on(CliRenderEvents.PALETTE, this.handlePalette)
    this.renderer.on(CliRenderEvents.THEME_MODE, this.handleThemeRefresh)
    this.renderer.prependInputHandler(this.handleThemeNotification)
    this.unsubscribeThemeSignal = options.subscribeThemeSignal(this.handleThemeSignal)

    const footer = this
    void render(
      () =>
        createComponent(Keymap.Provider, {
          config: options.tuiConfig,
          get children() {
            return createComponent(RunFooterView, {
              directory: options.directory,
              state: footer.state,
              startup: footer.startup,
              view: footer.view,
              subagent: footer.subagent,
              queuedPrompts: footer.queuedPrompts,
              findFiles: options.findFiles,
              agents: footer.agents,
              references: footer.references,
              commands: footer.commands,
              providers: footer.providers,
              currentAgent: footer.currentAgent,
              currentAgentID: footer.currentAgentID,
              currentModel: footer.currentModel,
              variants: footer.variants,
              currentVariant: footer.currentVariant,
              theme: footer.theme,
              tuiConfig: options.tuiConfig,
              get mono() {
                return footer.miniSettings().mono
              },
              miniSettings: footer.miniSettings,
              history: footer.history,
              onSubmit: footer.handlePrompt,
              onPermissionReply: footer.handlePermissionReply,
              onFormReply: footer.handleFormReply,
              onFormCancel: footer.handleFormCancel,
              onCycle: footer.handleCycle,
              onInterrupt: footer.handleInterrupt,
              onBackground: options.onBackground,
              onQueuedPromptAction: options.onQueuedPromptAction,
              onEditorOpen: (input) => {
                footer.finishStartup()
                return options.onEditorOpen(input)
              },
              onInputClear: footer.handleInputClear,
              onExitRequest: footer.handleExit,
              onRequestExit: footer.setRequestExitHandler,
              onExit: () => footer.close(),
              onAgentSelect: footer.handleAgentSelect,
              onModelSelect: footer.handleModelSelect,
              onVariantSelect: footer.handleVariantSelect,
              onRows: footer.syncRows,
              onLayout: footer.syncLayout,
              onStatus: footer.setStatus,
              onMiniSettingChange: footer.handleMiniSettingChange,
              onSubagentSelect: options.onSubagentSelect,
              onSubagentInterrupt: options.onSubagentInterrupt,
            })
          },
        }),
      this.renderer,
    ).catch(() => {
      if (!this.isGone) {
        this.close()
      }
    })
    if (options.startup)
      this.startupTimer = setTimeout(() => this.finishStartup(), (SEED_LAUNCH.frames.length - 1) * SEED_LAUNCH.interval)
  }

  public finishStartup(): void {
    const startup = this.startup()
    if (!startup) return
    clearTimeout(this.startupTimer)
    this.startupTimer = undefined
    this.setStartup(undefined)
    if (this.isGone) return
    this.applyHeight()
    this.renderer.writeToScrollback(
      entrySplash({
        ...startup,
        theme: this.theme().splash,
        mono: this.miniSettings().mono,
      }),
    )
    this.renderer.requestRender()
  }

  public get isClosed(): boolean {
    return this.closed || this.isGone
  }

  private get isGone(): boolean {
    return this.destroyed || this.renderer.isDestroyed
  }

  public onPrompt(fn: (input: RunPrompt) => void): () => void {
    this.prompts.add(fn)
    return () => {
      this.prompts.delete(fn)
    }
  }

  public onClose(fn: () => void): () => void {
    if (this.isClosed) {
      fn()
      return () => {}
    }

    this.closes.add(fn)
    return () => {
      this.closes.delete(fn)
    }
  }

  public event(next: FooterEvent): void {
    if (next.type === "history") {
      this.setHistory(next.history)
      return
    }

    if (next.type === "agent") {
      this.setCurrentAgentID(next.agent)
      return
    }

    if (next.type === "model") {
      this.setCurrentModel(next.selection)
    }

    if (next.type === "turn.duration") {
      this.finishStartup()
      const agent = this.turnAgent ?? this.currentAgent()
      this.turnAgent = undefined
      if (this.miniSettings().turn_summary === "hide") return
      const current = this.currentModel()
      this.flush()
      this.flushing = this.flushing
        .then(() =>
          this.scrollback.writeTurnSummary({
            agent,
            model: current ? modelInfo(this.providers(), current).model : this.state().model,
            duration: next.duration,
          }),
        )
        .catch((error) => {
          this.flushError = error
        })
      return
    }

    if (next.type === "catalog") {
      if (this.isGone) {
        return
      }

      this.setAgents(next.agents)
      this.setReferences(next.references)
      if (next.commands !== undefined) {
        this.setCommands(next.commands)
      }
      return
    }

    if (next.type === "models") {
      if (this.isGone) {
        return
      }

      this.setProviders(next.providers)
      return
    }

    if (next.type === "variants") {
      if (this.isGone) {
        return
      }

      this.setVariants(next.variants)
      this.setCurrentVariant(next.current)
      return
    }

    if (next.type === "queued.prompts") {
      if (this.isGone) {
        return
      }

      this.setQueuedPrompts(next.prompts)
      return
    }

    const patch = eventPatch(next)
    if (patch) {
      if (typeof patch.status === "string") {
        this.clearNoticeTimer()
        patch.notice = ""
      }
      if (next.type === "turn.send") {
        this.turnAgent = this.currentAgent()
        this.clearInterruptTimer()
        this.clearExitTimer()
      }
      this.patch(patch)
      return
    }

    if (next.type === "stream.subagent") {
      if (this.isGone) {
        return
      }

      this.setSubagent(next.state)
      this.applyHeight()
      return
    }

    if (next.type === "stream.view") {
      this.present(next.view)
    }
  }

  private patch(next: FooterPatch): void {
    if (this.isGone) {
      return
    }

    const prev = this.state()
    const state = {
      phase: next.phase ?? prev.phase,
      status: typeof next.status === "string" ? next.status : prev.status,
      notice: typeof next.notice === "string" ? next.notice : prev.notice,
      model: typeof next.model === "string" ? next.model : prev.model,
      usage: "usage" in next ? next.usage : prev.usage,
      first: typeof next.first === "boolean" ? next.first : prev.first,
      interrupt:
        typeof next.interrupt === "number" && Number.isFinite(next.interrupt)
          ? Math.max(0, Math.floor(next.interrupt))
          : prev.interrupt,
      exit:
        typeof next.exit === "number" && Number.isFinite(next.exit) ? Math.max(0, Math.floor(next.exit)) : prev.exit,
    }

    if (state.phase === "idle") {
      state.interrupt = 0
    }

    this.setState(state)

    if (prev.phase === "running" && state.phase === "idle") {
      this.flush()
      this.completeScrollback()
    }
  }

  private completeScrollback(): void {
    this.flushing = this.flushing
      .then(() => this.scrollback.complete())
      .catch((error) => {
        this.flushError = error
      })
  }

  private present(view: FooterView): void {
    if (this.isGone) {
      return
    }

    if (view.type !== "prompt") this.finishStartup()
    this.setView(view)
    this.applyHeight()
  }

  // Queues a scrollback commit. Consecutive progress chunks for the same
  // part coalesce by appending text, reducing the number of retained-surface
  // updates. Actual flush happens on the next microtask, so a burst of events
  // from one reducer pass becomes a single ordered drain.
  public append(commit: StreamCommit): void {
    if (this.isGone) {
      return
    }

    this.finishStartup()
    if (this.miniSettings().tools === "hide" && toolTranscript(commit)) return
    const last = this.queue.at(-1)
    const merged = last ? coalesceProgressCommit(last, commit) : undefined
    if (merged) this.queue[this.queue.length - 1] = merged
    else this.queue.push(commit)

    if (this.pending) {
      return
    }

    this.pending = true
    queueMicrotask(() => {
      this.pending = false
      this.flush()
    })
  }

  public idle(): Promise<void> {
    if (this.isGone) {
      return Promise.resolve()
    }

    this.flush()
    if (this.state().phase === "idle") {
      this.completeScrollback()
    }

    return this.flushing.then(async () => {
      if (this.flushError !== undefined) {
        const error = this.flushError
        this.flushError = undefined
        throw error
      }

      if (this.isGone) {
        return
      }

      if (this.queue.length > 0) {
        return this.idle()
      }

      await this.renderer.idle().catch(() => {})
    })
  }

  public resetForReplay(wrote: boolean): void {
    if (this.isGone) {
      return
    }

    this.finishStartup()
    this.scrollback.destroy()
    this.scrollback = this.createScrollback(wrote)
  }

  public currentTheme(): RunTheme {
    return this.theme()
  }

  public currentMiniSettings(): MiniSettings {
    return this.miniSettings()
  }

  private destroyTheme(theme: RunTheme): void {
    const index = this.themes.indexOf(theme)
    if (index === -1) {
      return
    }

    this.themes.splice(index, 1)
    theme.block.syntax?.destroy()
  }

  public close(): void {
    if (this.closed) {
      return
    }

    this.finishStartup()
    this.flush()
    this.notifyClose()
  }

  public requestExit(): boolean {
    return this.requestExitHandler?.() ?? this.handleExit()
  }

  public destroy(): void {
    this.handleDestroy()
  }

  private notifyClose(): void {
    if (this.closed) {
      return
    }

    this.closed = true
    for (const fn of [...this.closes]) {
      fn()
    }
  }

  private setStatus = (status: string): void => {
    this.setNotice(status)
  }

  private setNotice(status: string): void {
    this.clearNoticeTimer()
    this.patch({ notice: status })
    if (!status) return

    this.noticeTimeout = setTimeout(() => {
      this.noticeTimeout = undefined
      this.patch({ notice: "" })
    }, NOTICE_DURATION)
  }

  private setRequestExitHandler = (fn?: () => boolean): void => {
    this.requestExitHandler = fn
  }

  private handleInputClear = (): void => {
    this.clearInterruptTimer()
    this.clearExitTimer()
    if (this.state().interrupt === 0 && this.state().exit === 0) {
      return
    }

    this.patch({ interrupt: 0, exit: 0 })
  }

  private handleResize = (): void => {
    if (!this.isGone) this.applyHeight()
  }

  private applyHeight(): void {
    const type = this.view().type
    const route = this.promptRoute.type
    const panel = footerPanelLayout(this.renderer.terminalHeight)
    const prompt = footerPromptLayout(this.renderer.terminalHeight)
    const desired =
      type === "permission"
        ? this.base + PERMISSION_ROWS
        : type === "form"
          ? this.base + FORM_ROWS
          : ["command", "skill", "agent", "model", "variant", "settings"].includes(route)
            ? 1 + panel.frame + panel.limit
            : route === "queued-menu" || route === "subagent-menu"
              ? 1 + this.subagentMenuRows
              : route === "subagent"
                ? this.base + SUBAGENT_INSPECTOR_ROWS
                : prompt.padding * 2 + 1 + this.rows
    const height = Math.max(
      1,
      Math.min(
        desired + (this.startup() ? 1 : 0),
        this.renderer.terminalHeight - (type === "prompt" && route === "composer" ? 1 : 0),
      ),
    )

    if (height !== this.renderer.footerHeight) {
      this.renderer.footerHeight = height
    }
  }

  private syncRows = (value: number): void => {
    if (this.isGone) {
      return
    }

    const rows = Math.max(TEXTAREA_MIN_ROWS, value)
    if (rows === this.rows) {
      return
    }

    this.rows = rows
    if (this.view().type === "prompt") {
      this.applyHeight()
    }
  }

  private syncLayout = (next: { route: FooterPromptRoute; subagentRows: number }): void => {
    if (next.route.type !== "composer") this.finishStartup()
    this.promptRoute = next.route
    this.subagentMenuRows = next.subagentRows
    if (this.view().type === "prompt") {
      this.applyHeight()
    }
  }

  private handlePrompt = (input: RunPrompt): boolean => {
    if (this.isClosed) {
      return false
    }

    if (this.state().first) {
      this.patch({ first: false })
    }

    if (this.prompts.size === 0) {
      this.setNotice("input queue unavailable")
      return false
    }

    for (const fn of [...this.prompts]) {
      fn(input)
    }

    return true
  }

  private handlePermissionReply = async (input: PermissionReply): Promise<void> => {
    if (this.isClosed) {
      return
    }

    await this.options.onPermissionReply(input)
  }

  private handleFormReply = async (input: FormReply): Promise<void> => {
    if (this.isClosed) return
    await this.options.onFormReply(input)
  }

  private handleFormCancel = async (input: FormCancel): Promise<void> => {
    if (this.isClosed) return
    await this.options.onFormCancel(input)
  }

  private handleCycle = (): void => {
    const result = this.options.onCycleVariant?.()
    if (!result) {
      this.setNotice("no variants available")
      return
    }

    this.applySelectionResult(result)
    if (result.status === undefined) this.setNotice("variant updated")
  }

  private handleModelSelect = (model: NonNullable<RunInput["model"]>): void => {
    if (this.isClosed) {
      return
    }

    const previous = this.currentModel()
    this.setCurrentModel(model)
    if (!previous || previous.providerID !== model.providerID || previous.modelID !== model.modelID) {
      this.setCurrentVariant(undefined)
    }
    void Promise.resolve()
      .then(() => this.options.onModelSelect?.(model))
      .then((result) => {
        const current = this.currentModel()
        if (
          !result ||
          this.isClosed ||
          !current ||
          current.providerID !== model.providerID ||
          current.modelID !== model.modelID
        ) {
          return
        }
        this.applySelectionResult(result)
      })
      .catch(() => {})
  }

  private handleAgentSelect = (agent: string): void => {
    if (this.isClosed || this.currentAgentID() === agent) return
    this.setCurrentAgentID(agent)
    this.options.onAgentSelect?.(agent)
    this.setNotice(`agent ${this.currentAgent()}`)
  }

  private handleVariantSelect = (variant: string | undefined): void => {
    if (this.isClosed) {
      return
    }

    const model = this.currentModel()
    void Promise.resolve()
      .then(() => this.options.onVariantSelect?.(variant))
      .then((result) => {
        const current = this.currentModel()
        if (
          !result ||
          this.isClosed ||
          (model && (!current || current.providerID !== model.providerID || current.modelID !== model.modelID))
        ) {
          return
        }
        this.applySelectionResult(result)
      })
      .catch(() => {})
  }

  private applySelectionResult(result: CycleResult): void {
    if ("variants" in result) this.setVariants(result.variants ?? [])
    if ("variant" in result) this.setCurrentVariant(result.variant)
    if (result.modelLabel) this.patch({ model: result.modelLabel })
    if (result.status) this.setNotice(result.status)
  }

  private handleMiniSettingChange = async (change: MiniSettingChange): Promise<void> => {
    if (!this.options.miniSettings.update) {
      this.setNotice("settings are unavailable")
      return
    }

    try {
      const settings = await this.options.miniSettings.update(change)
      if (this.isClosed) return
      if (settings.mono === this.miniSettings().mono) {
        this.setMiniSettings(settings)
        this.setNotice("settings updated")
        return
      }
      const theme = await resolveRunTheme(this.renderer, this.options.tuiConfig.theme, settings.mono)
      this.flush()
      this.flushing = this.flushing.then(async () => {
        if (this.isClosed) {
          theme.block.syntax?.destroy()
          return
        }
        await this.scrollback.setMono(settings.mono)
        batch(() => {
          this.setMiniSettings(settings)
          this.applyTheme(theme)
          this.options.onMonoChange?.(settings.mono)
        })
      })
      await this.flushing
      this.setNotice("settings updated")
    } catch (error) {
      this.setNotice("failed to save settings")
      throw error
    }
  }

  private clearInterruptTimer(): void {
    if (!this.interruptTimeout) {
      return
    }

    clearTimeout(this.interruptTimeout)
    this.interruptTimeout = undefined
  }

  private clearNoticeTimer(): void {
    if (this.noticeTimeout) clearTimeout(this.noticeTimeout)
    this.noticeTimeout = undefined
  }

  private armInterruptTimer(): void {
    this.clearInterruptTimer()
    this.interruptTimeout = setTimeout(() => {
      this.interruptTimeout = undefined
      if (this.isGone || this.state().phase !== "running") {
        return
      }

      this.patch({ interrupt: 0 })
    }, 5000)
  }

  private clearExitTimer(): void {
    if (!this.exitTimeout) {
      return
    }

    clearTimeout(this.exitTimeout)
    this.exitTimeout = undefined
  }

  private armExitTimer(): void {
    this.clearExitTimer()
    this.exitTimeout = setTimeout(() => {
      this.exitTimeout = undefined
      if (this.isGone || this.isClosed) {
        return
      }

      this.patch({ exit: 0 })
    }, 5000)
  }

  // Two-press interrupt: first press shows a hint ("esc again to interrupt"),
  // second press within 5 seconds fires onInterrupt. The timer resets the
  // counter if the user doesn't follow through.
  private handleInterrupt = (): boolean => {
    if (this.isClosed || this.state().phase !== "running") {
      return false
    }

    const next = this.state().interrupt + 1
    this.patch({ interrupt: next })

    if (next < 2) {
      this.armInterruptTimer()
      return true
    }

    this.clearInterruptTimer()
    this.patch({ interrupt: 0 })
    this.setNotice("interrupting")
    this.options.onInterrupt?.()
    return true
  }

  private handleExit = (): boolean => {
    if (this.isClosed) {
      return true
    }

    this.clearInterruptTimer()
    const next = this.state().exit + 1
    this.patch({ exit: next, interrupt: 0 })

    if (next < 2) {
      this.armExitTimer()
      return true
    }

    this.clearExitTimer()
    this.patch({ exit: 0, status: "exiting" })
    this.close()
    return true
  }

  private applyTheme(theme: RunTheme): void {
    if (theme === this.theme()) return
    this.themes.push(theme)
    this.setTheme(theme)
    this.renderer.setBackgroundColor(theme.background)
    this.scrollback.setTheme(theme)
  }

  private handleExternalOutput = (event: CliRendererExternalOutputEvent): void => {
    if (this.miniSettings().mono) monoSnapshot(event)
  }

  private handlePalette = (): Promise<void> | undefined => {
    if (this.isGone || this.paletteRefreshRunning) return
    const mono = this.miniSettings().mono
    return resolveRunTheme(this.renderer, this.options.tuiConfig.theme, mono).then((theme) => {
      this.flushing = this.flushing
        .then(() => {
          if (this.isGone || mono !== this.miniSettings().mono) {
            theme.block.syntax?.destroy()
            return
          }
          this.applyTheme(theme)
        })
        .catch((error) => {
          this.flushError = error
        })
      return this.flushing
    })
  }

  private handleThemeNotification = (sequence: string): boolean => {
    if (sequence !== "\x1b[?997;1n" && sequence !== "\x1b[?997;2n") {
      return false
    }

    // OpenTUI clears its palette cache only when dark/light mode changes.
    // Refresh for same-mode terminal theme swaps too.
    queueMicrotask(this.handleThemeRefresh)
    return false
  }

  private handleThemeRefresh = (): Promise<void> | undefined => {
    if (this.isGone) {
      return
    }
    if (this.miniSettings().mono) return this.handlePalette()

    if (this.paletteRefreshRunning) {
      this.paletteRefreshQueued = true
      return
    }

    this.paletteRefreshRunning = true
    const retry = this.renderer.paletteDetectionStatus === "detecting"
    this.renderer.clearPaletteCache()
    return this.renderer
      .getPalette({ size: 256 })
      .catch(() => {})
      .then(() => {
        this.paletteRefreshRunning = false
        if (!retry && !this.paletteRefreshQueued) {
          // Theme files can change without a new terminal palette.
          return this.handlePalette()
        }

        this.paletteRefreshQueued = false
        return this.handleThemeRefresh()
      })
  }

  public refreshTheme() {
    return this.handleThemeRefresh()
  }

  private handleThemeSignal = (): void => {
    // Omarchy signals immediately after requesting a terminal config reload.
    for (const timeout of this.themeRefreshTimeouts) clearTimeout(timeout)
    this.themeRefreshTimeouts = THEME_REFRESH_DELAYS.map((delay) =>
      setTimeout(() => {
        this.handleThemeRefresh()
      }, delay),
    )
  }

  private handleDestroy = (): void => {
    if (this.destroyed) {
      return
    }

    clearTimeout(this.startupTimer)
    this.startupTimer = undefined
    this.flush()
    this.destroyed = true
    this.notifyClose()
    this.clearInterruptTimer()
    this.clearExitTimer()
    this.clearNoticeTimer()
    this.renderer.off(CliRenderEvents.DESTROY, this.handleDestroy)
    this.renderer.off(CliRenderEvents.RESIZE, this.handleResize)
    this.renderer.off(CliRenderEvents.EXTERNAL_OUTPUT, this.handleExternalOutput)
    this.renderer.off(CliRenderEvents.PALETTE, this.handlePalette)
    this.renderer.off(CliRenderEvents.THEME_MODE, this.handleThemeRefresh)
    this.renderer.removeInputHandler(this.handleThemeNotification)
    this.unsubscribeThemeSignal()
    for (const timeout of this.themeRefreshTimeouts) clearTimeout(timeout)
    this.themeRefreshTimeouts.length = 0
    this.prompts.clear()
    this.closes.clear()
    this.scrollback.destroy()
    for (const theme of [...this.themes]) this.destroyTheme(theme)
  }

  // Drains the commit queue to scrollback. The surface manager owns grouping,
  // spacing, and progressive markdown/code settling so direct mode can append
  // immutable transcript rows without rewriting history.
  private flush(): void {
    if (this.isGone || this.queue.length === 0) {
      this.queue.length = 0
      return
    }

    const batch = this.queue.splice(0)
    this.flushing = this.flushing
      .then(async () => {
        for (const item of batch) {
          await this.scrollback.append(item)
        }
      })
      .catch((error) => {
        this.flushError = error
      })
  }
}

function toolTranscript(commit: StreamCommit) {
  return commit.kind === "tool" || commit.partID?.startsWith("skill:")
}

/** @internal Exported for queue identity regression tests. */
export function coalesceProgressCommit(previous: StreamCommit, current: StreamCommit): StreamCommit | undefined {
  if (
    previous.phase !== "progress" ||
    current.phase !== "progress" ||
    previous.kind !== current.kind ||
    previous.source !== current.source ||
    previous.messageID !== current.messageID ||
    previous.partID !== current.partID ||
    previous.tool !== current.tool ||
    previous.toolState !== current.toolState
  )
    return
  return { ...current, text: previous.text + current.text }
}

// Footer layout
//
// Renders the footer region as a compact vertical stack:
//   1. Single-line composer or active footer body
//   2. Optional autocomplete/menu panels below the composer
//   3. A statusline-style footer row carrying state, hints, and model info
//
// All state comes from the parent RunFooter through SolidJS signals.
// The view itself is stateless except for derived memos.
/** @jsxImportSource @opentui/solid */
import { useRenderer, useTerminalDimensions } from "@opentui/solid"
import { TextBuffer, TextBufferView } from "@opentui/core"
import { For, Match, Show, Switch, createEffect, createMemo, createSignal, onCleanup } from "solid-js"
import { OneCellSpinner } from "../component/one-cell-spinner"
import { WORK_SPINNERS, SEED_LAUNCH, SEED_MONO } from "../ui/one-cell-motion"
import { entrySplashLayout } from "./splash"
import {
  RUN_SUBAGENT_PANEL_ROWS,
  RunAgentSelectBody,
  RunCommandMenuBody,
