} from "./types"
import type { RunTheme } from "./theme"

const money = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" })

const EMPTY_BORDER = {
  topLeft: "",
  bottomLeft: "",
  vertical: "",
  topRight: "",
  bottomRight: "",
  horizontal: " ",
  bottomT: "",
  topT: "",
  cross: "",
  leftT: "",
  rightT: "",
}

type RunFooterViewProps = {
  directory: () => string
  findFiles: (query: string) => Promise<string[]>
  agents: () => RunAgent[]
  references: () => RunReference[]
  commands: () => RunCommand[] | undefined
  providers: () => RunProvider[] | undefined
  currentAgent: () => string
  currentAgentID: () => string | undefined
  currentModel: () => RunInput["model"]
  variants: () => string[]
  currentVariant: () => string | undefined
  state: () => FooterState
  startup?: () => { version: string; detail: string } | undefined
  view?: () => FooterView
  subagent?: () => FooterSubagentState
  queuedPrompts?: () => FooterQueuedPrompt[]
  theme: () => RunTheme
  tuiConfig: RunTuiConfig
  mono: boolean
  miniSettings: () => MiniSettings
  history?: () => RunPrompt[]
  clipboard?: Pick<ClipboardService, "read">
  onSubmit: (input: RunPrompt) => boolean | Promise<boolean>
  onPermissionReply: (input: PermissionReply) => void | Promise<void>
  onFormReply: (input: FormReply) => void | Promise<void>
  onFormCancel: (input: FormCancel) => void | Promise<void>
  onCycle: () => void
  onInterrupt: () => boolean
  onBackground?: () => void
  onQueuedPromptAction?: (action: QueuedPromptAction, inboxID: string) => Promise<void>
  onEditorOpen: (input: { value: string }) => Promise<string | undefined>
  onInputClear: () => void
  onExitRequest?: () => boolean
  onRequestExit?: (fn: (() => boolean) | undefined) => void
  onExit: () => void
  onAgentSelect: (agent: string) => void
  onModelSelect: (model: NonNullable<RunInput["model"]>) => void
  onVariantSelect: (variant: string | undefined) => void
  onRows: (rows: number) => void
  onLayout: (input: { route: FooterPromptRoute; subagentRows: number }) => void
  onStatus: (text: string) => void
  onMiniSettingChange: (change: MiniSettingChange) => void | Promise<void>
  onSubagentSelect?: (sessionID: string | undefined) => void
  onSubagentInterrupt?: (sessionID: string) => void
}

export function RunFooterView(props: RunFooterViewProps) {
  const renderer = useRenderer()
  const term = useTerminalDimensions()
  const width = createMemo(() => term().width)
  const startup = createMemo(() => {
    const value = props.startup?.()
    return value ? entrySplashLayout({ ...value, width: width(), mono: props.mono }) : undefined
  })
  const active = createMemo<FooterView>(() => props.view?.() ?? { type: "prompt" })
  const subagent = createMemo<FooterSubagentState>(() => {
    return (
      props.subagent?.() ?? {
        tabs: [],
        details: {},
        permissions: [],
        forms: [],
      }
    )
  })
  const [route, setRoute] = createSignal<FooterPromptRoute>({ type: "composer" })
  const [subagentMenuRows, setSubagentMenuRows] = createSignal(RUN_SUBAGENT_PANEL_ROWS)
  const queuedPrompts = createMemo(() => props.queuedPrompts?.() ?? [])
  const queue = createMemo(() => queuedPrompts().filter((item) => item.delivery === "queue"))
  const prompt = createMemo(() => active().type === "prompt" && route().type === "composer")
  const selectingSubagent = createMemo(() => active().type === "prompt" && route().type === "subagent-menu")
  const selectingQueued = createMemo(() => active().type === "prompt" && route().type === "queued-menu")
  const inspecting = createMemo(() => active().type === "prompt" && route().type === "subagent")
  const commanding = createMemo(() => active().type === "prompt" && route().type === "command")
  const agenting = createMemo(() => active().type === "prompt" && route().type === "agent")
  const modeling = createMemo(() => active().type === "prompt" && route().type === "model")
  const varianting = createMemo(() => active().type === "prompt" && route().type === "variant")
  const setting = createMemo(() => active().type === "prompt" && route().type === "settings")
  const panel = createMemo(
    () =>
      active().type === "permission" ||
      active().type === "form" ||
      selectingQueued() ||
      selectingSubagent() ||
      commanding() ||
      agenting() ||
      modeling() ||
      varianting() ||
      setting(),
  )
  const selected = createMemo(() => {
    const current = route()
    return current.type === "subagent" ? current.sessionID : undefined
  })
  const tabs = createMemo(() => subagent().tabs)
  const activeTabs = createMemo(() => tabs().filter((item) => item.status === "running"))
  const selectedTab = createMemo(() => tabs().find((item) => item.sessionID === selected()))
  const selectedIndex = createMemo(() => {
    const sessionID = selected()
    if (!sessionID) {
      return 0
    }

    return tabs().findIndex((item) => item.sessionID === sessionID) + 1
  })
  const foregroundSubagents = createMemo(() => activeTabs().some((item) => !item.background))
  const model = createMemo(() => {
    const current = props.currentModel()
    return current ? modelInfo(props.providers(), current) : undefined
  })
  const detail = createMemo(() => {
    const current = route()
    return current.type === "subagent" ? subagent().details[current.sessionID] : undefined
  })
  const shortcuts = Keymap.useShortcuts()
  const shortcut = (id: string) => monoShortcut(shortcuts.get(id) ?? "", props.mono)
  const command = () => shortcut("command.palette.show")
  const subagentShortcut = () => shortcut("session.child.first")
  const queuedShortcut = () => shortcut("session.queued_prompts")
  const backgroundShortcut = () => shortcut("session.background")
  const subagentInterruptShortcut = () => shortcut("composer.subagent.interrupt")
  const interrupt = () => shortcut("session.interrupt")
  const variantCycle = () => monoShortcut(shortcuts.all("variant.cycle") ?? "", props.mono)
  const clearShortcut = () => shortcut("prompt.clear")
  const busy = createMemo(() => props.state().phase === "running")
  const started = createMemo(() => (busy() ? performance.now() : undefined))
  const statusWidth = createMemo(() => Math.max(1, width() - (busy() ? 2 : 0)))
  const armed = createMemo(() => props.state().interrupt > 0)
  const exiting = createMemo(() => props.state().exit > 0)
  const usage = createMemo(() => props.state().usage)
  const contextUsage = createMemo(() => {
    const current = usage()
    return current && current.tokens > 0 ? formatContextUsage(current.tokens, current.percent) : ""
  })
  const cost = createMemo(() => (usage()?.cost ? money.format(usage()!.cost!) : ""))
  const takeover = createMemo(() => exiting() || (busy() && armed()) || !!props.state().notice.trim())
  const footerDetails = createMemo(() => props.miniSettings().footer === "show" && !takeover())
  const interruptLabel = createMemo(() => {
    if (!interrupt()) {
      return
    }

    return interrupt() === "escape" ? "esc" : interrupt()
  })
  const runTheme = createMemo(() => props.theme())
  const theme = createMemo(() => runTheme().footer)
  const agentColor = createMemo(() => {
    const colors = theme().categorical
    const index = props
      .agents()
      .filter((agent) => !agent.hidden)
      .findIndex((agent) => agent.id === props.currentAgentID())
    return colors[Math.max(0, index) % colors.length]!
  })
  const block = createMemo(() => runTheme().block)
  const footerStatus = createMemo(() => {
    const current = model()?.model ?? props.state().model.trim()
    const variant = props.currentVariant()
    const details = [busy() ? "running" : "idle", `agent ${props.currentAgent()}`]
    if (current) details.push(variant ? `${current} ${variant}` : current)
    if (contextUsage()) details.push(contextUsage())
    if (cost()) details.push(cost())
    if (queuedPrompts().length > 0) details.push(`${queuedPrompts().length} pending`)
    if (activeTabs().length > 0) details.push(`${activeTabs().length} subagent${activeTabs().length === 1 ? "" : "s"}`)
    return details.join(props.mono ? " - " : " · ")
  })
  const permission = createMemo<Extract<FooterView, { type: "permission" }> | undefined>(() => {
    const view = active()
    return view.type === "permission" ? view : undefined
  })
  const form = createMemo<Extract<FooterView, { type: "form" }> | undefined>(() => {
    const view = active()
    return view.type === "form" ? view : undefined
  })
  const formStates = new Map<string, FormBodyState>()
  const settledForms = new Set<string>()
  let formsAbsent = true

  createEffect(() => {
    const view = active()
    if (view.type === "form") {
      formsAbsent = false
      return
    }
    if (view.type === "permission") return
    formsAbsent = true
    formStates.clear()
    settledForms.clear()
  })
  const promptView = createMemo(() => {
    if (active().type !== "prompt") {
      return active().type
    }

    const current = route()
    return current.type === "composer" ? "prompt" : current.type
  })

  const openRoute = (next: FooterPromptRoute) => {
    setRoute(next)
    props.onSubagentSelect?.(undefined)
  }

  const openCommand = () => {
    openRoute({ type: "command" })
  }

  const openModel = () => {
    openRoute({ type: "model" })
  }

  const openAgent = () => {
    openRoute({ type: "agent" })
  }

  const openVariant = () => {
    openRoute({ type: "variant" })
  }

  const openSettings = () => {
    openRoute({ type: "settings" })
  }

  const openSubagentMenu = () => {
    if (tabs().length === 0) {
      return
    }

    openRoute({ type: "subagent-menu" })
  }

  const openQueuedMenu = () => {
    if (queuedPrompts().length === 0) return
    openRoute({ type: "queued-menu" })
  }

  const closePanel = () => {
    setRoute({ type: "composer" })
  }

  const runQueuedAction = createSingleFlight<string>()
  const queuedPromptAction = async (action: QueuedPromptAction, inboxID: string, failureLabel?: string) => {
    const run = props.onQueuedPromptAction
    if (!run) return false
    const result = await runQueuedAction(inboxID, async () => {
      const error = await run(action, inboxID).then(
        () => undefined,
        (error) => error,
      )
      if (!error) return true
      props.onStatus(
        `failed to ${failureLabel ?? (action === "cancel" ? "delete" : action)} pending prompt: ${errorMessage(error)}`,
      )
      return false
    })
    return result ?? false
  }

  const openTab = (sessionID: string) => {
    setRoute({ type: "subagent", sessionID })
    props.onSubagentSelect?.(sessionID)
  }

  const closeTab = () => {
    openRoute({ type: "composer" })
  }

  const cycleTab = (dir: -1 | 1) => {
    if (tabs().length === 0) {
      return
    }

    const routeState = route()
    const current =
      routeState.type === "subagent" ? tabs().findIndex((item) => item.sessionID === routeState.sessionID) : -1
    const index = current === -1 ? 0 : (current + dir + tabs().length) % tabs().length
    const next = tabs()[index]
    if (!next) {
      return
    }

    openTab(next.sessionID)
  }
  const [promptRows, setPromptRows] = createSignal(1)
  const composer = createPromptState({
    directory: props.directory,
    findFiles: props.findFiles,
    agents: props.agents,
    references: props.references,
    commands: props.commands,
    state: props.state,
    view: promptView,
    prompt,
    width,
    statusRows: () => (menu() ? 0 : statusRows()),
    theme,
    mono: () => props.mono,
    imagePreview: props.tuiConfig.prompt?.image_preview,
    clipboard: props.clipboard,
    history: props.history,
    queuedPrompts: queue,
    onQueuedPromptSteer: (inboxID) => queuedPromptAction("steer", inboxID),
    onSubmit: props.onSubmit,
    onCycle: props.onCycle,
    onInterrupt: props.onInterrupt,
    onEditorOpen: props.onEditorOpen,
    onInputClear: props.onInputClear,
    onExitRequest: props.onExitRequest,
    onExit: props.onExit,
    onSettings: openSettings,
    onRows: setPromptRows,
    onStatus: props.onStatus,
  })
  const shell = createMemo(() => prompt() && composer.shell())
  const menu = createMemo(() => prompt() && composer.visible())
  const stateStatus = createMemo(() => props.state().status.trim())
  const notice = createMemo(() => props.state().notice.trim())
  const statusText = createMemo(() => {
    if (exiting() || (busy() && armed())) {
      const key = exiting() ? clearShortcut() : interruptLabel()
      const action = exiting() ? "exit" : "stop"
      if (!key) return exiting() ? "Exit pending" : "Stop pending"
      const phrases = [
        `Press ${key} again to ${exiting() ? "exit" : "interrupt"}`,
        `${key} again to ${exiting() ? "exit" : "interrupt"}`,
        `${key} again: ${action}`,
        `${key} ${action}`,
      ]
      return phrases.find((text) => stringWidth(text) <= statusWidth()) ?? phrases[phrases.length - 1]!
    }

    if (notice()) return notice()
    if (!footerDetails()) return shell() ? "Shell" : ""
    if (busy()) {
      if (stateStatus() === "reconnecting") return "reconnecting"
      return interruptLabel() ? `${interruptLabel()} stop` : "Running"
    }
    return stateStatus() || (shell() ? "Shell" : "")
  })
  const agentStatus = createMemo(() => {
    if (!footerDetails() || !prompt() || shell()) return undefined
    return props.currentAgent()
  })
  const modelStatus = createMemo(() => {
    const current = model()?.model ?? props.state().model.trim()
    if (!footerDetails() || !prompt() || shell() || !current) return
    return {
      model: current,
      provider: model()?.provider,
      variant: props.currentVariant(),
    }
  })
  const statusColor = createMemo(() => {
    if (exiting()) {
      return theme().error
    }

    if (armed()) {
      return theme().warning
    }

    if (busy() || notice().length > 0 || stateStatus().length > 0) {
      return theme().text
    }

    return theme().muted
  })
  const contextHintCandidates = createMemo(() => {
    if (!footerDetails() || !prompt() || shell()) {
      return []
    }

    const items: Array<{ id: "queued" | "subagents" | "background"; key: string; label: string; expanded?: string }> =
      []
    if (queuedPrompts().length > 0 && queuedShortcut()) {
      items.push({ id: "queued", key: queuedShortcut(), label: `${queuedPrompts().length} pending` })
    }
    if (activeTabs().length > 0 && subagentShortcut()) {
      items.push({
        id: "subagents",
        key: subagentShortcut(),
        label: `${activeTabs().length} sub`,
        expanded: `${activeTabs().length} subagent${activeTabs().length === 1 ? "" : "s"}`,
      })
    }
    if (foregroundSubagents() && backgroundShortcut()) {
      items.push({ id: "background", key: backgroundShortcut(), label: "bg", expanded: "background" })
    }
    return items
  })
  const commandHint = createMemo(() => {
    if (!prompt() || takeover() || shell()) return
    if (command()) {
      return { key: command(), label: "menu" }
    }
  })
  const statuslineLayout = createMemo(() => {
    const info = modelStatus()
    return footerStatuslinePolicy({
      width: width(),
      mono: props.mono,
      status: {
        text: statusText(),
        expanded: footerDetails() && busy() && interruptLabel() ? `${interruptLabel()} interrupt` : undefined,
      },
      escape: shell() && !takeover() ? { key: "esc", label: "normal" } : undefined,
      work: contextHintCandidates(),
      model: info ? { name: info.model, variant: info.variant } : undefined,
      agent: agentStatus(),
      context:
        footerDetails() && contextUsage()
          ? {
              compact: usage()?.percent === undefined ? contextUsage() : `${usage()!.percent}% ctx`,
              full: contextUsage(),
            }
          : undefined,
      cost: footerDetails() ? cost() : undefined,
      provider: info?.provider,
      menu: commandHint(),
      spinner: busy() ? (props.mono ? "*" : "\u25aa") : undefined,
    })
  })
  const statusSections = createMemo(() => statuslineLayout().groups.filter((group) => group.id !== "spinner"))
  const statusColors = createMemo(() => ({
    text: theme().text,
    muted: theme().muted,
    agent: agentColor(),
    status: statusColor(),
  }))
  const statusRows = createMemo(() => {
    const text = statusSections()
      .map((group) => group.parts.map((part) => part.text).join(""))
      .join(props.mono ? " - " : " \u00b7 ")
    if (stringWidth(text) <= statusWidth() && !text.includes("\n")) return 1
    // Measure outside the clipped footer so wrapped required controls can grow it.
    const buffer = TextBuffer.create(renderer.widthMethod)
    const view = TextBufferView.create(buffer)
    buffer.setText(text)
    view.setWrapMode("word")
    view.setWrapWidth(statusWidth())
    const rows = Math.max(1, view.getVirtualLineCount())
    view.destroy()
    buffer.destroy()
    return rows
  })
  createEffect(() => {
    props.onRows(promptRows() + (!panel() && !menu() && !inspecting() ? statusRows() : 0) - 1)
  })

  createEffect(() => {
    props.onRequestExit?.(composer.requestExit)
  })

  onCleanup(() => {
    props.onRequestExit?.(undefined)
  })

  const clearScreen = () => {
    if (renderer.isDestroyed) return
    if (renderer.screenMode !== "split-footer") return
    if (renderer.externalOutputMode !== "capture-stdout") return
    if (renderer.currentControlState === "explicit_suspended") return
    // Home, erase the visible display, keep terminal scrollback, then repaint the footer.
    renderer.resetSplitFooterForReplay({ clearSavedLines: false })
  }

  Keymap.createLayer(() => ({
    commands: [
      {
        id: "app.clear",
        title: "Clear screen",
        group: "System",
        run: clearScreen,
      },
    ],
  }))

  Keymap.createLayer(() => ({
    enabled: active().type === "prompt" && route().type === "composer" && !composer.visible(),
    commands: [
      {
        id: "command.palette.show",
        title: "Open command palette",
        group: "Prompt",
        run: openCommand,
      },
      {
        id: "variant.cycle",
        title: "Cycle model variant",
        group: "Model",
        run: props.onCycle,
      },
    ],
  }))

  Keymap.createLayer(() => ({
    enabled: active().type === "prompt" && route().type === "composer" && foregroundSubagents() && !!props.onBackground,
    priority: 1,
    commands: [
      {
        id: "session.background",
        title: "Background subagents",
        group: "Session",
        run: () => props.onBackground?.(),
      },
    ],
  }))

  Keymap.createLayer(() => ({
    enabled: active().type === "prompt" && route().type === "composer" && tabs().length > 0,
    commands: [
      {
        id: "session.child.first",
        title: "View subagents",
        group: "Session",
        run: openSubagentMenu,
      },
    ],
  }))

  Keymap.createLayer(() => ({
    enabled: active().type === "prompt" && route().type === "composer" && queuedPrompts().length > 0,
    commands: [
      {
        id: "session.queued_prompts",
        title: "View pending prompts",
        group: "Prompt",
        run: openQueuedMenu,
      },
    ],
  }))

  Keymap.createLayer(() => ({
    enabled:
      active().type === "prompt" &&
      route().type === "subagent" &&
      selectedTab()?.status === "running" &&
      !!props.onSubagentInterrupt,
    priority: 1,
    commands: [
      {
        id: "composer.subagent.interrupt",
        title: "Interrupt subagent",
        group: "Session",
        run: () => {
          const current = selectedTab()
          if (current?.status !== "running") {
            return
          }

          props.onSubagentInterrupt?.(current.sessionID)
        },
      },
    ],
  }))

  createEffect(() => {
    const current = route()
    if (current.type !== "subagent") {
      return
    }

    if (tabs().some((item) => item.sessionID === current.sessionID)) {
      return
    }

    closeTab()
  })

  createEffect(() => {
    if (route().type !== "subagent-menu") {
      return
    }

    if (tabs().length > 0) {
      return
    }

    closePanel()
  })

  createEffect(() => {
    if (route().type !== "queued-menu" || queuedPrompts().length > 0) return
    closePanel()
  })

  createEffect(() => {
    if (active().type === "prompt") {
      return
    }

    const current = route()
    if (
      current.type !== "command" &&
      current.type !== "agent" &&
      current.type !== "model" &&
      current.type !== "variant" &&
      current.type !== "settings" &&
      current.type !== "queued-menu" &&
      current.type !== "subagent-menu"
    ) {
      return
    }

    closePanel()
  })

  createEffect(() => {
    props.onLayout({
      route: route(),
      subagentRows: subagentMenuRows(),
    })
  })

  return (
    <box
      width="100%"
      height="100%"
      border={false}
      backgroundColor="transparent"
      flexDirection="column"
      gap={0}
      padding={0}
    >
      {/* The renderer seeds the leading blank row that entrySplash includes in scrollback. */}
      <Show when={startup()}>
        {(layout) => (
          <box id="mini-startup" height={1} flexShrink={0} flexDirection="row">
            <Show when={layout().label.startsWith("\u25aa")}>
              <OneCellSpinner
                animation={SEED_LAUNCH}
                color={runTheme().splash.right}
                animations={props.tuiConfig.animations}
              />
            </Show>
            <text fg={runTheme().splash.right} wrapMode="none">
              {layout().label.startsWith("\u25aa") ? layout().label.slice(1) : layout().label}
              <span style={{ fg: runTheme().splash.left }}>{layout().metadata}</span>
            </text>
          </box>
        )}
      </Show>
      <Show when={panel() || inspecting()}>
        <box width="100%" height={1} flexShrink={0} backgroundColor="transparent" />
      </Show>

      <Show
        when={inspecting()}
        fallback={
          <box width="100%" flexDirection="column" gap={0}>
            <For each={[promptView()]}>
              {() => (
                <box
                  width="100%"
                  flexShrink={0}
                  border={panel() || prompt() ? false : ["left"]}
                  borderColor={panel() || prompt() ? undefined : theme().border}
                  customBorderChars={
                    panel() || prompt()
                      ? undefined
                      : {
                          ...EMPTY_BORDER,
                          vertical: props.mono ? "|" : "█",
                        }
                  }
                >
                  <box
                    width="100%"
                    flexGrow={1}
                    paddingLeft={0}
                    paddingRight={0}
                    paddingTop={0}
                    flexDirection="column"
                    backgroundColor={panel() || prompt() ? "transparent" : theme().surface}
                    gap={0}
                  >
                    <box width="100%" flexGrow={1} flexShrink={1} flexDirection="column">
                      <Switch>
                        <Match when={active().type === "prompt" && route().type === "composer"}>
                          <RunPromptBody
                            theme={theme}
                            cursorStyle={props.tuiConfig.cursor}
                            background={() => runTheme().background}
                            rail={() => (shell() ? theme().formfieldFocusedText : agentColor())}
                            mono={props.mono}
                            placeholder={composer.placeholder}
                            onSubmit={composer.onSubmit}
                            onKeyDown={composer.onKeyDown}
                            onPaste={composer.onPaste}
                            images={composer.images}
                            layout={composer.layout}
                            onContentChange={composer.onContentChange}
                            onSizeChange={composer.onSizeChange}
                            bind={composer.bind}
                          />
                        </Match>
                        <Match when={selectingSubagent()}>
                          <RunSubagentSelectBody
                            theme={theme}
                            tabs={tabs}
                            current={selected}
                            onClose={closePanel}
                            onSelect={openTab}
                            onRows={setSubagentMenuRows}
                            mono={props.mono}
                          />
                        </Match>
                        <Match when={selectingQueued()}>
                          <RunQueuedPromptSelectBody
                            theme={theme}
                            prompts={queuedPrompts}
                            onClose={closePanel}
                            onSelect={async (item) => {
                              if (
                                await queuedPromptAction(item.delivery === "queue" ? "steer" : "queue", item.messageID)
                              )
                                closePanel()
                            }}
                            onUndo={async (item) => {
                              const current = composer.current()
                              if (current.mode === "shell" && current.text) {
                                props.onStatus("leave shell mode before undoing a queued prompt")
                                return
                              }
                              if (!(await queuedPromptAction("cancel", item.messageID, "undo"))) return
                              closePanel()
                              const next = promptAppend(composer.current(), item.prompt)
                              composer.replacePrompt(next, promptOffsetWidth(next.text))
                            }}
                            onDelete={(item) => {
                              void queuedPromptAction("cancel", item.messageID)
                            }}
                            onRows={setSubagentMenuRows}
                            mono={props.mono}
                          />
                        </Match>
                        <Match when={commanding()}>
                          <RunCommandMenuBody
                            theme={theme}
                            commands={props.commands}
                            subagents={tabs}
                            queued={queuedPrompts}
                            variants={props.variants}
                            variantCycle={variantCycle()}
                            onClose={closePanel}
                            onAgent={openAgent}
                            onModel={openModel}
                            onEditor={() => {
                              closePanel()
                              void composer.openEditor()
                            }}
                            onSubagent={openSubagentMenu}
                            onQueued={openQueuedMenu}
                            onVariant={openVariant}
                            onSettings={openSettings}
                            onVariantCycle={() => {
                              props.onCycle()
                              closePanel()
                            }}
                            onStatus={() => {
                              props.onStatus(footerStatus())
                              closePanel()
                            }}
                            onCommand={(name) => {
                              composer.submitText(`/${name}`)
                              closePanel()
                            }}
                            onNew={() => {
                              composer.submitText("/new")
                              closePanel()
                            }}
                            onClear={() => {
                              closePanel()
                              clearScreen()
                            }}
                            onExit={props.onExit}
                            clearShortcut={shortcut("app.clear")}
                            mono={props.mono}
                          />
                        </Match>
                        <Match when={agenting()}>
                          <RunAgentSelectBody
                            theme={theme}
                            agents={props.agents}
                            current={props.currentAgentID}
                            onClose={closePanel}
                            onSelect={(agent) => {
                              props.onAgentSelect(agent)
                              closePanel()
                            }}
                            mono={props.mono}
                          />
                        </Match>
                        <Match when={modeling()}>
                          <RunModelSelectBody
                            theme={theme}
                            providers={props.providers}
                            current={props.currentModel}
                            onClose={closePanel}
                            onSelect={(model) => {
                              props.onModelSelect(model)
                              closePanel()
                            }}
                            mono={props.mono}
                          />
                        </Match>
                        <Match when={varianting()}>
                          <RunVariantSelectBody
                            theme={theme}
                            variants={props.variants}
                            current={props.currentVariant}
                            onClose={closePanel}
                            onSelect={(variant) => {
                              props.onVariantSelect(variant)
                              closePanel()
                            }}
                            mono={props.mono}
                          />
                        </Match>
                        <Match when={setting()}>
                          <RunSettingsBody
                            theme={theme}
                            settings={props.miniSettings}
                            onClose={closePanel}
                            onChange={props.onMiniSettingChange}
                            mono={props.mono}
                            animations={props.tuiConfig.animations}
                          />
                        </Match>
                        <Match when={active().type === "permission"}>
                          <RunPermissionBody
                            request={permission()!.request}
                            directory={props.directory}
                            theme={theme()}
                            block={block()}
                            onReply={props.onPermissionReply}
                            mono={props.mono}
                          />
                        </Match>
                        <Match when={active().type === "form"}>
                          <For each={form() ? [form()!] : []}>
                            {(value) => (
                              <RunFormBody
                                request={value.request}
                                theme={theme()}
                                state={formStates.get(value.request.id) ?? createFormBodyState(value.request)}
                                onState={(state) => {
                                  if (!formsAbsent && !settledForms.has(state.formID))
                                    formStates.set(state.formID, state)
                                }}
                                onReply={async (input) => {
                                  await props.onFormReply(input)
                                  settledForms.add(input.formID)
                                  formStates.delete(input.formID)
                                }}
                                onCancel={async (input) => {
                                  await props.onFormCancel(input)
                                  settledForms.add(input.formID)
                                  formStates.delete(input.formID)
                                }}
                                mono={props.mono}
                              />
                            )}
                          </For>
                        </Match>
                      </Switch>
                    </box>
                  </box>
                </box>
              )}
            </For>

            <Show when={!panel() && menu()}>
              <RunFooterMenu
                theme={theme}
                items={composer.options}
                selected={composer.selected}
                offset={composer.offset}
                rows={composer.rows}
                limit={FOOTER_MENU_ROWS}
                border={false}
                paddingLeft={2}
                paddingRight={2}
                mono={props.mono}
              />
            </Show>

            <Show when={!panel() && !menu()}>
              <box
                id="mini-statusline"
                width="100%"
                flexDirection="row"
                gap={1}
                flexShrink={0}
                backgroundColor="transparent"
              >
                <Show when={busy()}>
                  <box id="mini-work-spinner" width={1} flexShrink={0}>
                    <OneCellSpinner
                      animation={props.mono ? SEED_MONO : WORK_SPINNERS[props.miniSettings().work_spinner]}
                      color={agentColor()}
                      animations={props.tuiConfig.animations}
                      glow={!props.mono}
                      still={props.mono ? "*" : undefined}
                      age={performance.now() - (started() ?? performance.now())}
                    />
                  </box>
                </Show>
                <Show when={statusSections().length > 0}>
                  <text fg={statusColor()} wrapMode="word" width={statusWidth()} flexShrink={0} height={statusRows()}>
                    <For each={statusSections()}>
                      {(section, index) => (
                        <>
                          <Show when={index() > 0}>
                            <span style={{ fg: theme().muted }}>{props.mono ? " - " : " · "}</span>
                          </Show>
                          <For each={section.parts}>
                            {(part) => <span style={{ fg: statusColors()[part.tone] }}>{part.text}</span>}
                          </For>
                        </>
                      )}
                    </For>
                  </text>
                </Show>
              </box>
            </Show>
          </box>
        }
      >
        <box
          width="100%"
          flexGrow={1}
          flexShrink={1}
          border={["left"]}
          borderColor={theme().border}
          customBorderChars={{
            ...EMPTY_BORDER,
            vertical: props.mono ? "|" : "┃",
          }}
        >
          <RunFooterSubagentBody
            active={inspecting}
            theme={runTheme}
            tab={selectedTab}
            index={selectedIndex}
            total={() => tabs().length}
            detail={detail}
            onCycle={cycleTab}
            onClose={closeTab}
            interrupt={() => subagentInterruptShortcut() || undefined}
            shellOutput={() => props.miniSettings().shell_output === "show"}
            mono={props.mono}
          />
        </box>
      </Show>
    </box>
  )
}

import { Locale } from "../util/locale"
import { stringWidth } from "../util/string-width"

type FooterAction = {
  key: string
  label: string
  expanded?: string
}

export type FooterStatuslineGroup = {
  id:
    | "spinner"
    | "status"
    | "escape"
    | "queued"
    | "subagents"
    | "background"
    | "agent"
    | "model"
    | "context"
    | "cost"
    | "provider"
    | "menu"
  parts: Array<{ text: string; tone: "text" | "muted" | "agent" | "status" }>
}

export function footerStatuslinePolicy(input: {
  width: number
  mono?: boolean
  status?: { text: string; expanded?: string }
  escape?: FooterAction
  work: Array<FooterAction & { id: "queued" | "subagents" | "background" }>
  model?: { name: string; variant?: string }
  agent?: string
  context?: { compact: string; full: string }
  cost?: string
  provider?: string
  menu?: FooterAction
  spinner?: string
}) {
  const group = (
    id: FooterStatuslineGroup["id"],
    text: string,
    tone: FooterStatuslineGroup["parts"][number]["tone"] = "muted",
  ): FooterStatuslineGroup => ({ id, parts: [{ text, tone }] })
  const action = (id: FooterStatuslineGroup["id"], value: FooterAction, expanded = false): FooterStatuslineGroup => ({
    id,
    parts: [
      { text: value.key, tone: "text" },
      { text: ` ${expanded ? (value.expanded ?? value.label) : value.label}`, tone: "muted" },
    ],
  })
  const identity = (cells: number) => {
    const name = input.model!.name
    const ellipsis = input.mono ? "..." : "\u2026"
    const text =
      stringWidth(name) > cells + stringWidth(ellipsis) ? Locale.takeWidth(name, cells).trimEnd() + ellipsis : name
    return group("model", text + (input.model!.variant ? ` [${input.model!.variant}]` : ""), "text")
  }
  const selected = new Map<FooterStatuslineGroup["id"], FooterStatuslineGroup>()
  if (input.spinner) selected.set("spinner", group("spinner", input.spinner, "text"))
  if (input.status?.text) selected.set("status", group("status", input.status.text, "status"))
  if (input.escape) selected.set("escape", action("escape", input.escape))

  const place = () => {
    const order: FooterStatuslineGroup["id"][] = [
      "spinner",
      "status",
      "escape",
      "queued",
      "subagents",
      "background",
      "agent",
      "model",
      "context",
      "provider",
      "cost",
      "menu",
    ]
    const groups = order.flatMap((id) => selected.get(id) ?? [])
    const separator = input.mono ? " - " : " \u00b7 "
    return {
      groups,
      text: groups
        .map(
          (item, index) =>
            (index === 0 ? "" : groups[index - 1]!.id === "spinner" ? " " : separator) +
            item.parts.map((part) => part.text).join(""),
        )
        .join(""),
    }
  }
  let layout = place()
  // Required controls may wrap. Optional information never crowds that fallback.
  if (stringWidth(layout.text) > input.width || layout.text.includes("\n")) return layout

  // Each stage retains earlier information. Stop at the first non-fitting stage:
  // backfilling shorter, lower-priority groups would make resizing unstable.
  const stages = [
    ...input.work.map((item) => action(item.id, item)),
    ...(input.model ? [identity(8)] : []),
    ...(input.agent ? [group("agent", input.agent, "agent")] : []),
    ...(input.context ? [group("context", input.context.compact)] : []),
    ...(input.model ? [identity(24)] : []),
    ...(input.context ? [group("context", input.context.full)] : []),
    ...(input.cost ? [group("cost", input.cost)] : []),
    ...(input.provider ? [group("provider", input.provider)] : []),
    ...(input.menu ? [action("menu", input.menu)] : []),
    ...(input.model ? [identity(Infinity)] : []),
    ...input.work.filter((item) => item.expanded).map((item) => action(item.id, item, true)),
    ...(input.status?.expanded ? [group("status", input.status.expanded, "status")] : []),
  ]
  for (const stage of stages) {
    selected.set(stage.id, stage)
    const next = place()
    if (stringWidth(next.text) > input.width || next.text.includes("\n")) break
    layout = next
  }
  return layout
}

import type { FormAnswer, FormField, FormInfo, FormValue } from "@opencode/client/promise"
import {
  formCustom,
  formDisplayValue,
  formInitialValues,
  formLabel,
  formRows,
  formSelected,
  formSetMultiselectCustom,
  formTextual,
  formToggleMultiselect,
  formValidateValue,
} from "../util/form"
import type { FormAnswerField } from "../util/form"
import type { FormReply, MiniFormRequest } from "./types"

export { formCustom, formLabel, formRows, formTextual, formValidateValue }

export type FormBodyState = {
  formID: string
  field: number
  answers: Record<string, FormValue | undefined>
  custom: Record<string, string>
  selected: number
  editing: boolean
  externalReady: Record<string, boolean>
  submitting: boolean
  error: string
}

export function createFormBodyState(form: FormInfo): FormBodyState {
  const initial = formInitialValues(form.fields)
  return {
    formID: form.id,
    field: 0,
    answers: initial.answers,
    custom: initial.custom,
    selected: formSelected(form.fields[0], initial.answers[form.fields[0]?.key ?? ""]),
    editing: formTextual(form.fields[0]),
    externalReady: {},
    submitting: false,
    error: "",
  }
}

export function formSync(state: FormBodyState, form: FormInfo): FormBodyState {
  return state.formID === form.id ? state : createFormBodyState(form)
}

export function formUnsupported(form: FormInfo): string | undefined {
  if (!Array.isArray(form.fields) || form.fields.length === 0) return "This form has no supported fields."
  for (const field of form.fields as ReadonlyArray<FormField | Record<string, unknown>>) {
    if (!field || typeof field !== "object" || typeof field.type !== "string") return "This form uses an unknown field."
    if (!("key" in field) || typeof field.key !== "string") return "This form uses an invalid field."
    if ("when" in field && Array.isArray(field.when) && field.when.length > 0)
      return "Conditional forms are not supported in Mini yet."
    if (field.type === "string" && "pattern" in field && field.pattern !== undefined)
      return "Pattern-constrained forms are not supported in Mini yet."
    if (!["string", "number", "integer", "boolean", "multiselect", "external"].includes(field.type))
      return `Field type ${field.type} is not supported in Mini yet.`
  }
}

export function formCurrent(form: FormInfo, state: FormBodyState) {
  return form.fields[state.field]
}

export function formConfirm(form: FormInfo, state: FormBodyState) {
  return state.field >= form.fields.length
}

export function formSingle(form: FormInfo) {
  if (form.fields.length !== 1) return false
  const field = form.fields[0]
  return (
    field?.type === "boolean" ||
    field?.type === "number" ||
    field?.type === "integer" ||
    field?.type === "external" ||
    field?.type === "string"
  )
}

export function formPlaceholder(field: FormField | undefined) {
  if (field?.type === "string") return field.placeholder ?? "Type your answer"
  return "Enter a number"
}

export function formMove(state: FormBodyState, form: FormInfo, direction: -1 | 1): FormBodyState {
  const field = formCurrent(form, state)
  const total = formRows(field).length + (formCustom(field) ? 1 : 0)
  if (total === 0) return state
  return { ...state, selected: (state.selected + direction + total) % total, error: "" }
}

export function formSetSelected(state: FormBodyState, selected: number): FormBodyState {
  return { ...state, selected, error: "" }
}

function formSetEditing(state: FormBodyState, editing: boolean): FormBodyState {
  return { ...state, editing, error: "" }
}

export function formSetSubmitting(state: FormBodyState, submitting: boolean, error = ""): FormBodyState {
  return { ...state, submitting, error }
}

export function formSetError(state: FormBodyState, error: string): FormBodyState {
  return { ...state, error, submitting: false }
}

export function formSetExternalReady(state: FormBodyState, key: string): FormBodyState {
  return { ...state, externalReady: { ...state.externalReady, [key]: true }, error: "" }
}

export function formInput(state: FormBodyState, field: FormField | undefined) {
  if (!field || field.type === "external") return ""
  return state.custom[field.key] ?? formDisplay(field, state.answers[field.key])
}

export function formSetDraft(state: FormBodyState, field: FormField | undefined, value: string): FormBodyState {
  if (!field || field.type === "external") return state
  return { ...state, custom: { ...state.custom, [field.key]: value } }
}

export function formValidate(form: FormInfo, state: FormBodyState): string | undefined {
  const unsupported = formUnsupported(form)
  if (unsupported) return unsupported
  for (const field of form.fields) {
    if (field.type === "external") {
      if (state.answers[field.key] !== true) return `Acknowledge ${formLabel(field)}`
      continue
    }
    const invalid = formValidateValue(field, state.answers[field.key])
    if (invalid) return `${formLabel(field)}: ${invalid}`
  }
}

export function formAnswer(form: FormInfo, state: FormBodyState): FormAnswer | undefined {
  if (formValidate(form, state)) return
  return Object.fromEntries(
    form.fields.flatMap((field) => {
      const value = state.answers[field.key]
      return value === undefined ? [] : [[field.key, value] as const]
    }),
  )
}

export function formReply(form: MiniFormRequest, state: FormBodyState): FormReply | undefined {
  const answer = formAnswer(form, state)
  if (!answer) return
  return { sessionID: form.sessionID, formID: form.id, answer, location: form.location }
}

export function formSetField(state: FormBodyState, form: FormInfo, index: number): FormBodyState {
  const bounded = Math.max(0, Math.min(form.fields.length, index))
  const field = form.fields[bounded]
  return {
    ...state,
    field: bounded,
    selected: formSelected(field, field ? state.answers[field.key] : undefined),
    editing: formTextual(field),
    error: "",
  }
}

export function formPick(state: FormBodyState, form: FormInfo): FormBodyState {
  const field = formCurrent(form, state)
  if (!field || field.type === "external" || formTextual(field)) return state
  const rows = formRows(field)
  if (state.selected === rows.length && formCustom(field)) return formSetEditing(state, true)
  const row = rows[state.selected]
  if (!row) return state
  if (field.type === "multiselect") {
    return {
      ...state,
      answers: { ...state.answers, [field.key]: formToggleMultiselect(state.answers[field.key], String(row.value)) },
      error: "",
    }
  }
  const next = {
    ...state,
    answers: { ...state.answers, [field.key]: row.value },
    error: "",
  }
  return formSetField(next, form, formSingle(form) ? state.field : state.field + 1)
}

export function formCommitInput(state: FormBodyState, form: FormInfo, text: string): FormBodyState {
  const field = formCurrent(form, state)
  if (!field || field.type === "external" || field.type === "boolean") return state
  const input = text.trim()
  const value = !input ? undefined : field.type === "number" || field.type === "integer" ? Number(input) : input
  if (field.type === "multiselect") {
    const values = formSetMultiselectCustom(state.answers[field.key], state.custom[field.key], input)
    const invalid = formValidateValue(field, values)
    if (invalid) return formSetError(state, invalid)
    return {
      ...state,
      answers: { ...state.answers, [field.key]: values },
      custom: { ...state.custom, [field.key]: input },
      editing: false,
      error: "",
    }
  }
  const invalid = formValidateValue(field, value)
  if (invalid) return formSetError(state, invalid)
  return {
    ...state,
    answers: { ...state.answers, [field.key]: value },
    custom: { ...state.custom, [field.key]: typeof value === "string" ? value : input },
    editing: false,
    error: "",
  }
}

export function formAcknowledge(state: FormBodyState, form: FormInfo): FormBodyState {
  const field = formCurrent(form, state)
  if (field?.type !== "external" || !state.externalReady[field.key]) return state
  const next = {
    ...state,
    answers: { ...state.answers, [field.key]: true },
    error: "",
  }
  return formSetField(next, form, formSingle(form) ? state.field : state.field + 1)
}

export function formDisplay(field: FormAnswerField, value: FormValue | undefined) {
  return formDisplayValue(field, value, "")
}

export function formErrorMessage(error: unknown) {
  if (typeof error === "string" && error.trim()) return error
  if (error && typeof error === "object") {
    const message = "message" in error ? error.message : undefined
    if (typeof message === "string" && message.trim()) return message
    const tag = "_tag" in error ? error._tag : undefined
    if (typeof tag === "string" && tag.trim()) return tag
  }
  return "Form request failed"
}

import { runInteractiveDeferredMode, type RunDeferredInput } from "./runtime"

export type MiniFrontendInput = RunDeferredInput

export async function runMiniFrontend(input: MiniFrontendInput): Promise<void> {
  await runInteractiveDeferredMode(input)
}

import {
  BoxRenderable,
  CodeRenderable,
  MarkdownRenderable,
  RGBA,
  Renderable,
  StyledText,
  TextRenderable,
  TextTableRenderable,
  isStyledText,
  stringToStyledText,
  type BorderCharacters,
  type CliRendererExternalOutputEvent,
  type TreeSitterClient,
} from "@opentui/core"

const prefixes: Record<number, string> = {
  0x2192: "->",
  0x2190: "<-",
  0x2731: "*",
  0x2699: "*",
  0x2716: "!",
  0x2717: "!",
  0x25c8: "*",
  0x25c9: "*",
  0x27f3: "*",
}

const markdown: Record<number, string> = {
  ...prefixes,
  0x00a0: " ",
  0x00b7: "-",
  0x2010: "-",
  0x2011: "-",
  0x2012: "-",
  0x2013: "-",
  0x2014: "--",
  0x2018: "'",
  0x2019: "'",
  0x201c: '"',
  0x201d: '"',
  0x2022: "*",
  0x2026: "...",
  0x2191: "up",
  0x2193: "down",
}

const asciiBorder: BorderCharacters = {
  topLeft: "+",
  topRight: "+",
  bottomLeft: "+",
  bottomRight: "+",
  horizontal: "-",
  vertical: "|",
  topT: "+",
  bottomT: "+",
  leftT: "+",
  rightT: "+",
  cross: "+",
}

const hooked = new WeakSet<Renderable>()

export const monoMarkdownTableOptions = {
  style: "columns" as const,
  widthMode: "content" as const,
  borders: false,
}

export function monoMarkdownRenderable(renderable: MarkdownRenderable): void {
  monoRenderable(renderable)
}

function monoRenderable(renderable: Renderable): void {
  if (hooked.has(renderable)) return
  hooked.add(renderable)
  // Markdown reconciles nested lists and tables without calling renderNode.
  // Hook the actual tree so future descendants are transformed before layout.
  const add = renderable.add.bind(renderable)
  renderable.add = (child, index) => {
    if (child instanceof Renderable) monoRenderable(child)
    return add(child, index)
  }

  if (renderable instanceof BoxRenderable) renderable.customBorderChars = asciiBorder
  if (renderable instanceof CodeRenderable) monoCode(renderable)
  if (renderable instanceof TextRenderable) renderable.content = monoStyledText(renderable.content)
  if (renderable instanceof TextTableRenderable) monoTable(renderable)
  renderable.getChildren().forEach(monoRenderable)
}

function monoCode(renderable: CodeRenderable): void {
  const onChunks = renderable.onChunks
  renderable.onChunks = async (chunks, context) => monoChunks((await onChunks?.(chunks, context)) ?? chunks)
  renderable.treeSitterClient = monoTreeSitter(renderable.treeSitterClient)
  // Streaming markdown writes the preview buffer here, skipping the setters below.
  const updateStreamingPreview = renderable.updateStreamingPreview.bind(renderable)
  renderable.updateStreamingPreview = (content, initialStyledText) => {
    updateStreamingPreview(content, monoStyledText(initialStyledText))
  }

  const initialDescriptor = Object.getOwnPropertyDescriptor(CodeRenderable.prototype, "initialStyledText")
  const contentDescriptor = Object.getOwnPropertyDescriptor(CodeRenderable.prototype, "content")
  if (!initialDescriptor?.set || !contentDescriptor?.get || !contentDescriptor.set) return
  const initialSetter = initialDescriptor.set.bind(renderable)
  const contentGetter = contentDescriptor.get.bind(renderable)
  const contentSetter = contentDescriptor.set.bind(renderable)
  // oxlint-disable-next-line no-restricted-globals -- OpenTUI does not expose its eager styled-text cache publicly.
  const initial = Reflect.get(renderable, "_initialStyledText")
  Object.defineProperty(renderable, "initialStyledText", {
    configurable: true,
    set(value: StyledText | undefined) {
      initialSetter(value ? monoStyledText(value) : value)
    },
  })
  Object.defineProperty(renderable, "content", {
    configurable: true,
    get: contentGetter,
    set(value: string) {
      // oxlint-disable-next-line no-restricted-globals -- OpenTUI does not expose its eager styled-text cache publicly.
      if (renderable.filetype !== "markdown" || !isStyledText(Reflect.get(renderable, "_initialStyledText"))) {
        renderable.drawUnstyledText = true
        renderable.initialStyledText = stringToStyledText(value)
      }
      contentSetter(renderable.filetype === "markdown" ? value : monoText(value))
    },
  })

  if (isStyledText(initial)) {
    renderable.initialStyledText = initial
  } else {
    renderable.drawUnstyledText = true
    renderable.initialStyledText = stringToStyledText(renderable.content)
  }
  if (!renderable.drawUnstyledText) return

  // Refresh the eager buffer with the transformed initial text. Highlighted
  // chunks continue through onChunks without changing the Markdown source.
  const content = renderable.content
  renderable.content = ""
  renderable.content = content
}

function monoTreeSitter(client: TreeSitterClient): TreeSitterClient {
  return new Proxy(client, {
    get(target, property) {
      // oxlint-disable-next-line no-restricted-globals -- Proxy forwarding requires receiver-aware property access.
      if (property !== "highlightOnce") return Reflect.get(target, property, target)
      // Keep parser failures on the chunk path instead of OpenTUI's raw-text fallback.
      return (...args: Parameters<TreeSitterClient["highlightOnce"]>) =>
        target.highlightOnce(...args).catch(() => ({ highlights: [] }))
    },
  })
}

function monoTable(renderable: TextTableRenderable): void {
  const descriptor = Object.getOwnPropertyDescriptor(TextTableRenderable.prototype, "content")
  if (!descriptor?.get || !descriptor.set) return
  const cells = new WeakMap<StyledText["chunks"], StyledText["chunks"]>()
  const content = renderable.content
  Object.defineProperty(renderable, "content", {
    configurable: true,
    get: () => descriptor.get!.call(renderable),
    set: (value: TextTableRenderable["content"]) => {
      descriptor.set!.call(
        renderable,
        value.map((row) =>
          row.map((cell) => {
            if (!cell) return cell
            const cached = cells.get(cell)
            if (cached) return cached
            const next = monoChunks(cell)
            cells.set(cell, next)
            return next
          }),
        ),
      )
    },
  })
  renderable.content = content
}

function monoStyledText(value: StyledText): StyledText {
  return new StyledText(monoChunks(value.chunks))
}

function monoChunks(value: StyledText["chunks"]): StyledText["chunks"] {
  return value.map((chunk) => ({ ...chunk, text: monoText(chunk.text) }))
}

function monoText(value: string): string {
  return value.replace(/[^\t\n\x20-\x7e]/gu, (char) => markdown[char.codePointAt(0)!] ?? "?")
}

export function monoSnapshot(event: CliRendererExternalOutputEvent): void {
  const buffers = event.snapshot.buffers
  const chars = buffers.char
  for (let index = 0; index < chars.length; index += 1) {
    const point = chars[index]
    if (point <= 0x7f) continue
    const offset = index * 4
    event.snapshot.setCell(
      index % event.snapshot.width,
      Math.floor(index / event.snapshot.width),
      monoCell(point),
      RGBA.fromArray(buffers.fg.subarray(offset, offset + 4)),
      RGBA.fromArray(buffers.bg.subarray(offset, offset + 4)),
      buffers.attributes[index],
    )
  }
}

function monoCell(point: number): string {
  const kind = point >>> 30
  if (kind === 2) return "?"
  if (kind === 3) return " "
  if (point === 0x2500) return "-"
  if (point === 0x2502) return "|"
  return markdown[point]?.[0] ?? "?"
}

export function monoPrefix(value: string, mono: boolean): string {
  if (!mono) return value
  const point = value.codePointAt(0)
  if (point === undefined) return value
  const prefix = prefixes[point]
  if (!prefix) return value
  return prefix + value.slice(point > 0xffff ? 2 : 1)
}

export function monoToolText(value: string, mono: boolean): string {
  const result = monoPrefix(value, mono)
  if (!mono) return result
  const separator = ` ${String.fromCodePoint(0xb7)} `
  const index = result.lastIndexOf(separator)
  if (index === -1) return result
  const head = result.slice(0, index)
  if (!head.includes(" completed") && head !== "patch" && !/^\d+ questions$/.test(head)) return result
  return result.slice(0, index) + " - " + result.slice(index + separator.length)
}

export function monoShortcut(value: string, mono: boolean): string {
  if (!mono) return value
  return value
    .replaceAll(String.fromCodePoint(0x2192), "right")
    .replaceAll(String.fromCodePoint(0x2190), "left")
    .replaceAll(String.fromCodePoint(0x2191), "up")
    .replaceAll(String.fromCodePoint(0x2193), "down")
}

export function monoTruncate(value: string, width: number, mono: boolean): string {
  if (!mono || value.length <= width) return value
  if (width <= 3) return ".".repeat(Math.max(0, width))
  return value.slice(0, width - 3) + "..."
}

import type { MiniPermissionRequest, PermissionReply } from "./types"
import { permissionAlwaysLines, permissionOptionLabel, permissionPresentation } from "../util/permission"
import { toolPath } from "./tool"
import { monoPrefix } from "./mono"

export type PermissionStage = "permission" | "always" | "reject"
export type PermissionOption = "once" | "always" | "reject" | "confirm" | "cancel"

export type PermissionBodyState = {
  requestID: string
  sessionID: string
  stage: PermissionStage
  selected: PermissionOption
  message: string
  submitting: boolean
}

export type PermissionStep = {
  state: PermissionBodyState
  reply?: PermissionReply
}

export function createPermissionBodyState(
  request: Pick<MiniPermissionRequest, "id" | "sessionID">,
): PermissionBodyState {
  return {
    requestID: request.id,
    sessionID: request.sessionID,
    stage: "permission",
    selected: "once",
    message: "",
    submitting: false,
  }
}

export function permissionOptions(stage: PermissionStage): PermissionOption[] {
  if (stage === "permission") {
    return ["once", "always", "reject"]
  }

  if (stage === "always") {
    return ["confirm", "cancel"]
  }

  return []
}

export function permissionInfo(request: MiniPermissionRequest, directory?: string, mono = false) {
  const state = request.tool?.state
  const info = permissionPresentation(
    {
      action: request.action,
      resources: request.resources,
      metadata: request.metadata,
      input: state?.status === "streaming" ? undefined : state?.input,
      toolMetadata: state?.status === "streaming" ? undefined : state?.metadata,
    },
    (value) => toolPath(value, { home: true, directory }),
  )
  if (!mono) return info
  return {
    ...info,
    icon: monoPrefix(info.icon, true),
    lines: [
      ...(info.diff || info.patch ? [info.diff ?? info.patch!] : []),
      ...info.lines.map((line) => monoPrefix(line, true)),
    ],
    diff: undefined,
    patch: undefined,
  }
}

export function permissionLabel(option: PermissionOption): string {
  return permissionOptionLabel(option)
}

export { permissionAlwaysLines }

function permissionReply(
  sessionID: string,
  requestID: string,
  decision: PermissionReply["decision"],
  message?: string,
): PermissionReply {
  return {
    sessionID,
    requestID,
    decision,
    ...(message && message.trim() ? { message: message.trim() } : {}),
  }
}

export function permissionShift(
  state: PermissionBodyState,
  dir: -1 | 1,
  list = permissionOptions(state.stage),
): PermissionBodyState {
  if (list.length === 0) {
    return state
  }

  const idx = Math.max(0, list.indexOf(state.selected))
  const selected = list[(idx + dir + list.length) % list.length]
  return {
    ...state,
    selected,
  }
}

export function permissionHover(state: PermissionBodyState, option: PermissionOption): PermissionBodyState {
  return {
    ...state,
    selected: option,
  }
}

export function permissionRun(state: PermissionBodyState, requestID: string, option: PermissionOption): PermissionStep {
  if (state.submitting) {
    return { state }
  }

  if (state.stage === "permission") {
    if (option === "always") {
      return {
        state: {
          ...state,
          stage: "always",
          selected: "confirm",
        },
      }
    }

    if (option === "reject") {
      return {
        state: {
          ...state,
          stage: "reject",
          selected: "reject",
        },
      }
    }

    return {
      state,
      reply: permissionReply(state.sessionID, requestID, "once"),
    }
  }

  if (state.stage !== "always") {
    return { state }
  }

  if (option === "cancel") {
    return {
      state: {
        ...state,
        stage: "permission",
        selected: "always",
      },
    }
  }

  return {
    state,
    reply: permissionReply(state.sessionID, requestID, "always"),
  }
}

export function permissionReject(state: PermissionBodyState, requestID: string): PermissionReply | undefined {
  if (state.submitting) {
    return undefined
  }

  return permissionReply(state.sessionID, requestID, "reject", state.message)
}

export function permissionCancel(state: PermissionBodyState): PermissionBodyState {
  return {
    ...state,
    stage: "permission",
    selected: "reject",
  }
}

export function permissionEscape(state: PermissionBodyState): PermissionBodyState {
  if (state.stage === "always") {
    return {
      ...state,
      stage: "permission",
      selected: "always",
    }
  }

  return {
    ...state,
    stage: "reject",
    selected: "reject",
  }
}

import type { RunPromptPart } from "./types"
import { realignPromptMentions } from "../prompt/mention"
import { parseSlashHead } from "../prompt/parse"

type Mention = Extract<RunPromptPart, { type: "file" | "agent" | "skill" }>

export function resolveEditorSlashValue(text: string) {
  const head = parseSlashHead(text)
  if (!head || head.name.toLowerCase() !== "editor") {
    return text
  }

  return head.arguments
}

export function realignEditorPromptParts(content: string, parts: RunPromptPart[]): RunPromptPart[] {
  const matches = realignPromptMentions(
    content,
    parts.map((part) => {
      if (part.type !== "file" && part.type !== "agent" && part.type !== "skill") return
      return promptPartMention(part)
    }),
  )

  return parts.flatMap((part, index) => {
    if (part.type !== "file" && part.type !== "agent" && part.type !== "skill") return [part]
    const mention = promptPartMention(part)
    if (!mention?.text) return [part]
    const match = matches[index]
    return match ? [updatePromptPart(part, match.start, match.end, match.text)] : []
  })
}

function promptPartMention(part: Mention) {
  const source = part.type === "file" ? part.source?.text : part.source
  if (!source) return
  return { start: source.start, end: source.end, text: source.value }
}

function updatePromptPart(part: Mention, start: number, end: number, text: string): Mention {
  if (part.type === "agent" || part.type === "skill") {
    return {
      ...part,
      source: {
        start,
        end,
        value: text,
      },
    }
  }

  if (!part.source?.text) {
    return part
  }

  return {
    ...part,
    source: {
      ...part.source,
      text: {
        ...part.source.text,
        start,
        end,
        value: text,
      },
    },
  }
}

// Pure state machine for the prompt input.
//
// Handles history ring navigation and prompt text helpers. All functions are
// pure -- they take state in and return new state out, with no side effects.
//
// The history ring (PromptHistoryState) stores past prompts and tracks
// the current browse position. When the user arrows up at cursor offset 0,
// the current draft is saved and history begins. Arrowing past the end
// restores the draft.
export { displayCharAt, displaySlice, mentionTriggerIndex, slashTriggerIndex } from "../prompt/display"
import { promptOffsetWidth } from "../prompt/display"
import { stringWidth } from "../util/string-width"
import type { RunPrompt } from "./types"

const HISTORY_LIMIT = 200

export type PromptHistoryState = {
  items: RunPrompt[]
  index: number | null
  draft: string
}

export type PromptMove = {
  state: PromptHistoryState
  text?: string
  cursor?: number
  apply: boolean
}

export function promptCopy(prompt: RunPrompt): RunPrompt {
  return {
    text: prompt.text,
    parts: structuredClone(prompt.parts),
    ...(prompt.mode ? { mode: prompt.mode } : {}),
    ...(prompt.command ? { command: prompt.command } : {}),
  }
}

// Part ranges are textarea offsets, so shift by display width rather than string length.
export function promptAppend(prompt: RunPrompt, following: RunPrompt): RunPrompt {
  const text = prompt.text ? `${prompt.text}\n\n` : ""
  const offset = promptOffsetWidth(text)
  const shift = <T extends { start: number; end: number }>(range: T) => ({
    ...range,
    start: range.start + offset,
    end: range.end + offset,
  })
  const command = prompt.text ? prompt.command : following.command
  return {
    text: text + following.text,
    parts: [
      ...structuredClone(prompt.parts),
      ...structuredClone(following.parts).map((part) => {
        if (!part.source) return part
        if (part.type === "file") return { ...part, source: { ...part.source, text: shift(part.source.text) } }
        return { ...part, source: shift(part.source) }
      }),
    ],
    ...(command ? { command } : {}),
  }
}

export function promptSame(a: RunPrompt, b: RunPrompt): boolean {
  return (
    a.mode === b.mode &&
    a.text === b.text &&
    JSON.stringify(a.parts) === JSON.stringify(b.parts) &&
    JSON.stringify(a.command) === JSON.stringify(b.command)
  )
}

export const EXIT_COMMANDS = ["exit", "quit", "q"]

export function isExitCommand(input: string): boolean {
  const text = input.trim().toLowerCase()
  return text === ":q" || EXIT_COMMANDS.some((name) => text === `/${name}`)
}

export function isNewCommand(input: string): boolean {
  return input.trim().toLowerCase() === "/new"
}

export function isCompactCommand(input: string): boolean {
  return input.trim().toLowerCase() === "/compact"
}

export function createPromptHistory(items?: RunPrompt[]): PromptHistoryState {
  const list = (items ?? [])
    .filter((item) => item.text.trim().length > 0 || item.parts.some((part) => part.type === "file"))
    .map(promptCopy)
  const next: RunPrompt[] = []
  for (const item of list) {
    if (next.length > 0 && promptSame(next[next.length - 1], item)) {
      continue
    }

    next.push(item)
  }

  return {
    items: next.slice(-HISTORY_LIMIT),
    index: null,
    draft: "",
  }
}

export function pushPromptHistory(state: PromptHistoryState, prompt: RunPrompt): PromptHistoryState {
  if (!prompt.text.trim() && !prompt.parts.some((part) => part.type === "file")) {
    return state
  }

  const next = promptCopy(prompt)
  if (state.items[state.items.length - 1] && promptSame(state.items[state.items.length - 1], next)) {
    return {
      ...state,
      index: null,
      draft: "",
    }
  }

  const items = [...state.items, next].slice(-HISTORY_LIMIT)
  return {
    ...state,
    items,
    index: null,
    draft: "",
  }
}

export function movePromptHistory(state: PromptHistoryState, dir: -1 | 1, text: string, cursor: number): PromptMove {
  if (state.items.length === 0) {
    return { state, apply: false }
  }

  if (dir === -1 && cursor !== 0) {
    return { state, apply: false }
  }

  if (dir === 1 && cursor !== stringWidth(text)) {
    return { state, apply: false }
  }

  if (state.index === null) {
    if (dir === 1) {
      return { state, apply: false }
    }

    const idx = state.items.length - 1
    return {
      state: {
        ...state,
        index: idx,
        draft: text,
      },
      text: state.items[idx].text,
      cursor: 0,
      apply: true,
    }
  }

  const idx = state.index + dir
  if (idx < 0) {
    return { state, apply: false }
  }

  if (idx >= state.items.length) {
    return {
      state: {
        ...state,
        index: null,
      },
      text: state.draft,
      cursor: stringWidth(state.draft),
      apply: true,
    }
  }

  return {
    state: {
      ...state,
      index: idx,
    },
    text: state.items[idx].text,
    cursor: dir === -1 ? 0 : stringWidth(state.items[idx].text),
    apply: true,
  }
}

// Boot-time resolution for direct interactive mode.
//
// These functions run concurrently at startup to gather everything the runtime
// needs before the first frame: TUI keymap config, model catalog, and session history for the prompt
// history ring. All are async because they read config or hit the SDK, but
// none block each other.
import type { LocationRef } from "@opencode/client/promise"
import { resolve } from "../config"
import { loadRunProviders } from "./catalog.shared"
import { resolveCurrentSession, sessionHistory } from "./session.shared"
import type { MiniSettings, RunInput, RunPrompt, RunProvider, RunTuiConfig } from "./types"
import { pickVariant } from "./variant.shared"

export type ModelInfo = {
  providers: RunProvider[]
}

export type SessionInfo = {
  first: boolean
  history: RunPrompt[]
  model?: NonNullable<RunInput["model"]>
  variant: string | undefined
}

function emptyModelInfo(): ModelInfo {
  return {
    providers: [],
  }
}

function emptySessionInfo(): SessionInfo {
  return {
    first: true,
    history: [],
    variant: undefined,
  }
}

function defaultRunTuiConfig(platform: NodeJS.Platform): RunTuiConfig {
  return resolve({}, { terminalSuspend: platform !== "win32" })
}

async function loadModelInfo(sdk: RunInput["sdk"], location: LocationRef, signal?: AbortSignal): Promise<ModelInfo> {
  return { providers: await loadRunProviders(sdk, location, signal) }
}

// Fetches available providers and variants.
export async function resolveModelInfo(
  sdk: RunInput["sdk"],
  location: LocationRef,
  signal?: AbortSignal,
): Promise<ModelInfo> {
  return loadModelInfo(sdk, location, signal).catch(() => emptyModelInfo())
}

export function resolveModelInfoStrict(sdk: RunInput["sdk"], location: LocationRef, signal?: AbortSignal) {
  return loadModelInfo(sdk, location, signal)
}

// Fetches session messages to determine if this is the first turn and build prompt history.
export async function resolveSessionInfo(
  sdk: RunInput["sdk"],
  sessionID: string,
  model: RunInput["model"],
  signal?: AbortSignal,
): Promise<SessionInfo> {
  return resolveCurrentSession(sdk, sessionID, signal)
    .then((session) => ({
      first: session.first,
      history: sessionHistory(session),
      model: session.model,
      variant: pickVariant(model ?? session.model, session),
    }))
    .catch(() => emptySessionInfo())
}

// Reads TUI config once for direct mode keymap setup and display preferences.
export async function resolveRunTuiConfig(
  config?: RunTuiConfig | Promise<RunTuiConfig>,
  platform: NodeJS.Platform = "linux",
): Promise<RunTuiConfig> {
  return Promise.resolve(config)
    .then((value) => value ?? defaultRunTuiConfig(platform))
    .catch(() => defaultRunTuiConfig(platform))
}

export function resolveMiniSettings(config?: { mini?: Partial<MiniSettings> }): MiniSettings {
  return {
    thinking: config?.mini?.thinking ?? "show",
    tools: config?.mini?.tools ?? "hide",
    shell_output: config?.mini?.shell_output ?? "hide",
    turn_summary: config?.mini?.turn_summary ?? "show",
    footer: config?.mini?.footer ?? "show",
    splash: config?.mini?.splash ?? "show",
    work_spinner: config?.mini?.work_spinner ?? "block-soft-slide",
    mono: config?.mini?.mono ?? false,
  }
}

// Lifecycle management for the split-footer renderer.
//
// Creates the OpenTUI CliRenderer in split-footer mode, resolves the theme
// from the terminal palette, writes the entry splash to scrollback, and
// constructs the RunFooter. Returns a Lifecycle handle whose close() writes
// the exit splash and tears everything down in the right order:
// footer.close → footer.destroy → renderer shutdown.
//
// Also wires SIGINT so Ctrl-c clears a live prompt draft first, then falls
// back to the usual two-press exit sequence through RunFooter.requestExit().
import path from "path"
import {
  CliRenderEvents,
  buildKittyKeyboardFlags,
  createCliRenderer,
  type CliRenderer,
  type ScrollbackWriter,
} from "@opentui/core"
import { isFallbackTitle } from "@opencode/util/session-title-fallback"
import { monoSnapshot } from "./mono"
import { entrySplash, exitSplash } from "./splash"
import { resolveRunTheme } from "./theme"
import type {
  FooterApi,
  FormCancel,
  FormReply,
  MiniSettingChange,
  MiniSettings,
  MiniHost,
  PermissionReply,
  QueuedPromptAction,
  RunAgent,
  RunInput,
  RunPrompt,
  RunReference,
  RunTuiConfig,
} from "./types"
import { resolveMiniSettings } from "./runtime.boot"
import { formatModelLabel } from "./variant.shared"

const FOOTER_HEIGHT = 4

type SplashState = {
  entry: boolean
  exit: boolean
}

type CycleResult = {
  modelLabel?: string
  status?: string
  variant?: string | undefined
  variants?: string[]
}

export type LifecycleInput = {
  host: MiniHost
  getDirectory: () => string
  findFiles: (query: string) => Promise<string[]>
  agents: RunAgent[]
  references: RunReference[]
  sessionID: string
  sessionTitle?: string
  getSessionID?: () => string | undefined
  first: boolean
  history: RunPrompt[]
  agent: string | undefined
  model: RunInput["model"]
  variant: string | undefined
  tuiConfig: RunTuiConfig | Promise<RunTuiConfig>
  onMiniSettingChange?: (change: MiniSettingChange) => Promise<MiniSettings>
  onPermissionReply: (input: PermissionReply) => void | Promise<void>
  onFormReply: (input: FormReply) => void | Promise<void>
  onFormCancel: (input: FormCancel) => void | Promise<void>
  onCycleVariant?: () => CycleResult | void
  onAgentSelect?: (agent: string) => void
  onModelSelect?: (model: NonNullable<RunInput["model"]>) => CycleResult | void | Promise<CycleResult | void>
  onVariantSelect?: (variant: string | undefined) => CycleResult | void | Promise<CycleResult | void>
  onInterrupt?: () => void
  onBackground?: () => void
  onQueuedPromptAction?: (action: QueuedPromptAction, inboxID: string) => Promise<void>
  onSubagentSelect?: (sessionID: string | undefined) => void
  onSubagentInterrupt?: (sessionID: string) => void
}

export type Lifecycle = {
  footer: FooterApi
  onResize(fn: () => void): () => void
  refreshTheme(): void
  setTitle(title?: string): void
  resetForReplay(): Promise<void>
  close(input: { showExit: boolean; sessionTitle?: string; sessionID?: string; history?: RunPrompt[] }): Promise<void>
}

// Gracefully tears down the renderer. Order matters: switch external output
// back to passthrough before leaving split-footer mode, so pending stdout
// doesn't get captured into the now-dead scrollback pipeline.
function shutdown(renderer: CliRenderer): void {
  if (renderer.isDestroyed) {
    return
  }

  if (renderer.externalOutputMode === "capture-stdout") {
    renderer.externalOutputMode = "passthrough"
  }

  if (renderer.screenMode === "split-footer") {
    renderer.screenMode = "main-screen"
  }

  if (!renderer.isDestroyed) {
    renderer.destroy()
  }
}

function splashTitle(title: string | undefined, history: RunPrompt[]) {
  if (title && !isFallbackTitle(title)) return title
  return history.find((item) => item.text.trim().length > 0)?.text ?? title
}

function directoryLabel(directory: string, home: string) {
  const resolved = path.resolve(directory)
  const display =
    resolved === home ? "~" : resolved.startsWith(`${home}${path.sep}`) ? resolved.replace(home, "~") : resolved
  return display.replaceAll("\\", "/")
}

function queueSplash(
  renderer: Pick<CliRenderer, "writeToScrollback" | "requestRender">,
  state: SplashState,
  phase: keyof SplashState,
  write: ScrollbackWriter | undefined,
): boolean {
  if (state[phase]) {
    return false
  }

  if (!write) {
    return false
  }

  state[phase] = true
  renderer.writeToScrollback(write)
  renderer.requestRender()
  return true
}

// Boots the split-footer renderer and constructs the RunFooter.
//
// The renderer starts in split-footer mode with captured stdout so that
// scrollback commits and footer repaints happen in the same frame. After
// the entry splash, RunFooter takes over the footer region.
export async function createRuntimeLifecycle(input: LifecycleInput): Promise<Lifecycle> {
  const footerTask = import("./footer")
  const tuiConfig = await input.tuiConfig
  const miniSettings = resolveMiniSettings(tuiConfig)
  const mono = miniSettings.mono
  const renderer = await createCliRenderer({
    stdin: input.host.terminal.stdin,
    targetFps: 30,
    maxFps: 60,
    useMouse: false,
    autoFocus: false,
    openConsoleOnError: false,
    exitOnCtrlC: false,
    useKittyKeyboard: mono
      ? { disambiguate: false, alternateKeys: false, events: false, allKeysAsEscapes: false, reportText: false }
      : { events: input.host.platform === "win32" },
    screenMode: "split-footer",
    footerHeight: FOOTER_HEIGHT,
    externalOutputMode: "capture-stdout",
    consoleMode: "disabled",
    clearOnShutdown: false,
  })
  if (mono) renderer.on(CliRenderEvents.EXTERNAL_OUTPUT, monoSnapshot)
  const setTitle = (title?: string) => {
    if (input.host.platform !== "linux") return
    if (!title || isFallbackTitle(title)) return renderer.setTerminalTitle("OpenCode")
    renderer.setTerminalTitle(`OC | ${title.length > 40 ? title.slice(0, 37) + "…" : title}`)
  }
  setTitle(input.sessionTitle)
  const theme = await resolveRunTheme(renderer, tuiConfig.theme, mono)
  renderer.setBackgroundColor(theme.background)
  const state: SplashState = {
    entry: false,
    exit: false,
  }
  const startup =
    miniSettings.splash === "show" && !mono && tuiConfig.animations !== false
      ? { version: input.host.version, detail: directoryLabel(input.getDirectory(), input.host.paths.home) }
      : undefined
  queueSplash(
    renderer,
    state,
    "entry",
    miniSettings.splash === "show" && !startup
      ? entrySplash({
          version: input.host.version,
          theme: theme.splash,
          detail: directoryLabel(input.getDirectory(), input.host.paths.home),
          mono,
        })
      : undefined,
  )
  await renderer.idle().catch(() => {})
  if (mono) renderer.off(CliRenderEvents.EXTERNAL_OUTPUT, monoSnapshot)

  const { RunFooter } = await footerTask
  let closed = false
  let sigintRegistered = false
  let detachSigintListener: (() => void) | undefined

  const footer = new RunFooter(renderer, {
    directory: input.getDirectory,
    findFiles: input.findFiles,
    agents: input.agents,
    references: input.references,
    agent: input.agent,
    modelLabel: input.model ? formatModelLabel(input.model, input.variant) : "Default model",
    model: input.model,
    variant: input.variant,
    first: input.first,
    history: input.history,
    theme,
    // The transcript always starts one row below the terminal's prior output,
    // even when the entry splash itself is hidden.
    wrote: true,
    startup,
    tuiConfig,
    miniSettings: {
      current: miniSettings,
      update: input.onMiniSettingChange,
    },
    onMonoChange: (mono) => {
      if (mono) {
        renderer.disableKittyKeyboard()
        return
      }
      renderer.enableKittyKeyboard(buildKittyKeyboardFlags({ events: input.host.platform === "win32" }))
    },
    onPermissionReply: input.onPermissionReply,
    onFormReply: input.onFormReply,
    onFormCancel: input.onFormCancel,
    onCycleVariant: input.onCycleVariant,
    onAgentSelect: input.onAgentSelect,
    onModelSelect: input.onModelSelect,
    onVariantSelect: input.onVariantSelect,
    onInterrupt: input.onInterrupt,
    onBackground: input.onBackground,
    onQueuedPromptAction: input.onQueuedPromptAction,
    onEditorOpen: async ({ value }) => {
      if (closed || renderer.isDestroyed) {
        return
      }

      await renderer.idle().catch(() => {})
      detachSigint()
      const detachIgnore = input.host.signals.sigint.subscribe(() => {})
      try {
        return await input.host.editor.open({
          value,
          cwd: input.getDirectory(),
          renderer,
          stdin: input.host.terminal.stdin,
        })
      } finally {
        detachIgnore()
        attachSigint()
      }
    },
    subscribeThemeSignal: input.host.signals.sigusr2.subscribe,
    onSubagentSelect: input.onSubagentSelect,
    onSubagentInterrupt: input.onSubagentInterrupt,
  })

  const sigint = () => {
    footer.requestExit()
  }

  const attachSigint = () => {
    if (closed || sigintRegistered) {
      return
    }

    detachSigintListener = input.host.signals.sigint.subscribe(sigint)
    sigintRegistered = true
  }

  const detachSigint = () => {
    if (!sigintRegistered) {
      return
    }

    detachSigintListener?.()
    detachSigintListener = undefined
    sigintRegistered = false
  }

  attachSigint()

  const close = async (next: {
    showExit: boolean
    sessionTitle?: string
    sessionID?: string
    history?: RunPrompt[]
  }) => {
    if (closed) {
      return
    }

    closed = true
    detachSigint()
    let wroteExit = false

    try {
      footer.finishStartup()
      await footer.idle().catch(() => {})

      if (!renderer.isDestroyed && next.showExit && footer.currentMiniSettings().splash === "show") {
        const sessionID = next.sessionID || input.getSessionID?.() || input.sessionID
        wroteExit = queueSplash(
          renderer,
          state,
          "exit",
          exitSplash({
            title: splashTitle(next.sessionTitle ?? input.sessionTitle, next.history ?? input.history),
            session_id: sessionID,
            theme: footer.currentTheme().splash,
            mono: footer.currentMiniSettings().mono,
          }),
        )
        await renderer.idle().catch(() => {})
      }
    } finally {
      footer.close()
      await footer.idle().catch(() => {})
      footer.destroy()
      if (input.host.platform === "linux") renderer.setTerminalTitle("")
      shutdown(renderer)
      if (!wroteExit) {
        input.host.stdout.write("\n")
      }
    }
  }

  return {
    footer,
    refreshTheme() {
      footer.refreshTheme()
    },
    setTitle,
    onResize(fn) {
      let width = renderer.terminalWidth
      let height = renderer.terminalHeight
      const resize = () => {
        if (width === renderer.terminalWidth && height === renderer.terminalHeight) {
          return
        }

        width = renderer.terminalWidth
        height = renderer.terminalHeight
        fn()
      }
      renderer.on(CliRenderEvents.RESIZE, resize)
      return () => renderer.off(CliRenderEvents.RESIZE, resize)
    },
    async resetForReplay() {
      if (closed || renderer.isDestroyed || footer.isClosed) {
        throw new Error("runtime closed")
      }

      await footer.idle()
      if (closed || renderer.isDestroyed || footer.isClosed) {
        throw new Error("runtime closed")
      }

      footer.resetForReplay(true)
      renderer.resetSplitFooterForReplay({ clearSavedLines: true })
      renderer.writeToScrollback(
        entrySplash({
          version: input.host.version,
          theme: footer.currentTheme().splash,
          detail: directoryLabel(input.getDirectory(), input.host.paths.home),
          mono: footer.currentMiniSettings().mono,
        }),
      )
      renderer.requestRender()
      await renderer.idle().catch(() => {})
    },
    close,
  }
}

// Serial prompt queue for direct interactive mode.
//
// Prompts arrive from the footer (user types and hits enter) and local
// operations drain one at a time. Ordinary prompts submitted during an active
// ordinary turn are admitted immediately to the server's durable queue.
//
// The queue also handles local session commands, empty-prompt rejection,
// and tracks per-turn wall-clock duration for the footer status line.
//
// Resolves when the footer closes and all in-flight work finishes.
import { SessionMessage } from "@opencode/schema/session-message"
import { Locale } from "../util/locale"
import { isCompactCommand, isExitCommand, isNewCommand } from "./prompt.shared"
import type { FooterApi, FooterEvent, RunDelivery, RunPrompt } from "./types"

type Trace = {
  write(type: string, data?: unknown): void
}

export type QueueInput = {
  footer: FooterApi
  initialInput?: string
  trace?: Trace
  onSend?: (prompt: RunPrompt, emittedUser: boolean) => void
  onAdmissionError?: (prompt: RunPrompt, error: unknown) => void | Promise<void>
  onNewSession?: () => void | Promise<void>
  onCompact?: () => void | Promise<void>
  admit: (prompt: RunPrompt, delivery: RunDelivery, signal: AbortSignal) => Promise<void>
  settle: () => Promise<void>
  run: (prompt: RunPrompt, signal: AbortSignal, admitted: () => void) => Promise<void>
}

type State = {
  queue: RunPrompt[]
  active?: RunPrompt
  admission?: Promise<void>
  ctrl?: AbortController
  closed: boolean
}

// Runs the prompt queue until the footer closes.
//
// Subscribes to footer prompt events and drains operations through input.run().
// Ordinary prompts submitted during an ordinary active turn are admitted as
// durable queued work instead of remaining editable process-local state.
export async function runPromptQueue(input: QueueInput): Promise<void> {
  const stop = Promise.withResolvers<{ type: "closed" }>()
  const done = Promise.withResolvers<void>()
  const state: State = {
    queue: [],
    closed: input.footer.isClosed,
  }
  let draining: Promise<void> | undefined
  let admissions = Promise.resolve()
  let admissionVersion = 0
  const admissionController = new AbortController()

  const emit = (next: FooterEvent, row: Record<string, unknown>) => {
    input.trace?.write("ui.patch", row)
    input.footer.event(next)
  }

  const finish = () => {
    if (!state.closed || draining) {
      return
    }

    done.resolve()
  }

  const close = () => {
    if (state.closed) {
      return
    }

    state.closed = true
    state.queue.length = 0
    // Ordinary turn signals map to session.interrupt; exiting should only detach the TUI.
    if (state.active?.mode === "shell") state.ctrl?.abort()
    admissionController.abort()
    stop.resolve({ type: "closed" })
    finish()
  }

  const drain = () => {
    if (draining || state.closed || state.queue.length === 0) {
      return
    }

    draining = (async () => {
      try {
        while (!state.closed && state.queue.length > 0) {
          const prompt = state.queue.shift()!

          if (prompt.mode !== "shell" && isNewCommand(prompt.text)) {
            if (!input.onNewSession) {
              emit(
                {
                  type: "stream.patch",
                  patch: {
                    status: "new sessions unavailable",
                  },
                },
                {
                  status: "new sessions unavailable",
                },
              )
              continue
            }

            emit(
              {
                type: "stream.patch",
                patch: {
                  phase: "running",
                  status: "starting new session",
                },
              },
              {
                phase: "running",
                status: "starting new session",
              },
            )
            await input.onNewSession()
            continue
          }

          if (prompt.mode !== "shell" && isCompactCommand(prompt.text)) {
            emit(
              {
                type: "stream.patch",
                patch: {
                  phase: "running",
                  status: "compacting session",
                },
              },
              {
                phase: "running",
                status: "compacting session",
              },
            )
            await input.onCompact?.()
            continue
          }

          const sent =
            prompt.mode === "shell"
              ? prompt
              : {
                  ...prompt,
                  messageID: prompt.messageID ?? SessionMessage.ID.create(),
                }
          state.active = sent

          emit(
            { type: "turn.send" },
            {
              phase: "running",
              status: "sending prompt",
            },
          )
          const start = Date.now()
          const ctrl = new AbortController()
          const admission = Promise.withResolvers<void>()
          const version = admissionVersion
          state.ctrl = ctrl
          state.admission = admission.promise

          try {
            await input.footer.idle()
            if (state.closed) {
              break
            }

            input.onSend?.(sent, false)

            if (state.closed) {
              break
            }

            const task = input.run(sent, ctrl.signal, admission.resolve).then(
              () => ({ type: "done" as const }),
              (error) => ({ type: "error" as const, error }),
            )

            const next = await Promise.race([task, stop.promise])
            if (next.type === "closed") {
              break
            }

            if (next.type === "error") {
              throw next.error
            }
            if (sent.mode !== "shell" && admissionVersion !== version) {
              do {
                const current = admissionVersion
                await admissions
                if (state.closed) break
                await input.settle()
                if (current === admissionVersion) break
              } while (!state.closed)
            }
          } finally {
            admission.resolve()
            if (state.ctrl === ctrl) {
              state.ctrl = undefined
            }
            if (state.admission === admission.promise) state.admission = undefined

            if (sent.mode !== "shell") {
              const duration = Locale.duration(Math.max(0, Date.now() - start))
              emit(
                {
                  type: "turn.duration",
                  duration,
                },
                {
                  duration,
                },
              )
            }
            state.active = undefined
          }
        }
      } catch (error) {
        done.reject(error)
        return
      } finally {
        draining = undefined
        emit(
          { type: "turn.idle" },
          {
            phase: "idle",
            status: "",
          },
        )
      }

      finish()
    })()
  }

  const submit = (prompt: RunPrompt) => {
    if (
      state.closed ||
      (!prompt.text.trim() && (prompt.mode === "shell" || !prompt.parts.some((part) => part.type === "file")))
    ) {
      return
    }

    if (prompt.mode !== "shell" && isExitCommand(prompt.text)) {
      input.footer.close()
      return
    }

    const active = state.active
    if (
      active &&
      active.mode !== "shell" &&
      prompt.mode !== "shell" &&
      prompt.command?.source !== "skill" &&
      !isNewCommand(prompt.text) &&
      !isCompactCommand(prompt.text) &&
      !state.queue.some((item) => item.mode !== "shell" && (isNewCommand(item.text) || isCompactCommand(item.text)))
    ) {
      const sent = { ...prompt, messageID: SessionMessage.ID.create() }
      const admission = state.admission
      admissionVersion += 1
      const delivery = prompt.delivery ?? "queue"
      input.onSend?.(sent, false)
      admissions = admissions
        .then(() => admission)
        .then(() => input.admit(sent, delivery, admissionController.signal))
        .catch((error) => (state.closed ? undefined : input.onAdmissionError?.(sent, error)))
      return
    }

    state.queue.push(prompt)
    if (prompt.mode !== "shell" && (isNewCommand(prompt.text) || isCompactCommand(prompt.text))) {
      drain()
      return
    }

    emit(
      {
        type: "first",
        first: false,
      },
      {
        first: false,
      },
    )
    drain()
  }

  const offPrompt = input.footer.onPrompt((prompt) => {
    submit(prompt)
  })
  const offClose = input.footer.onClose(() => {
    close()
  })
  try {
    if (state.closed) {
      return
    }

    submit({
      text: input.initialInput ?? "",
      parts: [],
    })
    finish()
    await done.promise
  } finally {
    offPrompt()
    offClose()
    close()
    await draining?.catch(() => {})
    await admissions
  }
}

// Top-level orchestrator for `opencode mini`.
//
// Wires the boot sequence, lifecycle (renderer + footer), stream transport,
// and prompt queue together into a single session loop. The frontend paints
// before resolving its Session, then:
//   1. resolves TUI config, model info, and session history,
//   2. creates the split-footer lifecycle (renderer + RunFooter),
//   3. starts the stream transport (SDK event subscription), lazily for fresh
//      local sessions,
//   4. runs the prompt queue until the footer closes.
import { SessionMessage } from "@opencode/schema/session-message"
import type { LocationRef } from "@opencode/client/promise"
import type { Config } from "../config"
import { newSessionLocation } from "../config/new-session-location"
import { errorMessage } from "../util/error"
import { loadRunAgents, loadRunCommands, loadRunReferences } from "./catalog.shared"
import {
  resolveMiniSettings,
  resolveModelInfo,
  resolveModelInfoStrict,
  resolveRunTuiConfig,
  resolveSessionInfo,
} from "./runtime.boot"
import { createRuntimeLifecycle } from "./runtime.lifecycle"
import { cycleVariant, formatModelLabel, resolveVariant } from "./variant.shared"
import { verbosityPreset } from "./verbosity"
import type {
  LocalReplayRow,
  MiniHost,
  MiniSettings,
  RunInput,
  RunPrompt,
  RunProvider,
  RunTuiConfig,
  StreamCommit,
} from "./types"

type BootContext = Pick<RunInput, "sdk" | "agent" | "model" | "variant"> & {
  location: LocationRef
}

type CreateSessionInput = {
  location: LocationRef
  agent: string | undefined
  model: RunInput["model"]
  variant: string | undefined
}

type CreateSession = (sdk: RunInput["sdk"], input: CreateSessionInput, signal?: AbortSignal) => Promise<ResolvedSession>
type Reconnect = (signal: AbortSignal) => Promise<RunInput["sdk"]>

type RunRuntimeInput = {
  host: MiniHost
  directory: string
  boot: () => Promise<BootContext>
  resolveSession: (sdk: RunInput["sdk"], signal: AbortSignal) => Promise<ResolvedSession>
  createSession?: CreateSession
  reconnect?: Reconnect
  files: RunInput["files"]
  initialInput?: string
  replay?: boolean
  replayLimit?: number
  demo?: RunInput["demo"]
  tuiConfig?: RunTuiConfig | Promise<RunTuiConfig>
  config?: Pick<Config.Interface, "update">
}

export type RunDeferredInput = {
  host: MiniHost
  sdk: RunInput["sdk"]
  reconnect?: Reconnect
  directory: string
  target: (sdk: RunInput["sdk"], signal: AbortSignal) => Promise<ResolvedSession>
  createSession?: CreateSession
  agent: RunInput["agent"]
  model: RunInput["model"]
  variant: RunInput["variant"]
  files: RunInput["files"]
  initialInput?: string
  replay?: boolean
  replayLimit?: number
  demo?: RunInput["demo"]
  tuiConfig?: RunTuiConfig | Promise<RunTuiConfig>
  config?: Pick<Config.Interface, "update">
}

type StreamTransportModule = Pick<
  Awaited<typeof import("./stream-v2.transport")>,
  "createSessionTransport" | "formatUnknownError"
>

export type RunRuntimeDeps = {
  createRuntimeLifecycle?: typeof createRuntimeLifecycle
  streamTransport?: Promise<StreamTransportModule>
}

type StreamState = {
  mod: StreamTransportModule
  handle: Awaited<ReturnType<StreamTransportModule["createSessionTransport"]>>
}

type RunDemo = ReturnType<(typeof import("./demo"))["createRunDemo"]>

type ResolvedSession = {
  sdk?: RunInput["sdk"]
  sessionID: string
  sessionTitle?: string
  location: RunInput["location"]
  model: RunInput["model"]
  variant: string | undefined
  agent?: string | undefined
  resume?: boolean
}

type RuntimeState = {
  sdk: RunInput["sdk"]
  shown: boolean
  model: RunInput["model"]
  defaultModel: RunInput["model"]
  providers: RunProvider[]
  variants: string[]
  activeVariant: string | undefined
  sessionID: string
  history: RunPrompt[]
  localRows: LocalReplayRow[]
  sessionTitle?: string
  agent: string | undefined
  location: LocationRef
  switching?: Promise<void>
  demo?: RunDemo
  selectSubagent?: (sessionID: string | undefined) => void
  session?: Promise<void>
  stream?: Promise<StreamState>
}

type ClientAttempt = {
  sdk: RunInput["sdk"]
  generation: number
  signal: AbortSignal
}

function variantsFor(providers: RunProvider[], model: RunInput["model"]) {
  if (!model) {
    return []
  }

  return Object.keys(providers.find((item) => item.id === model.providerID)?.models?.[model.modelID]?.variants ?? {})
}

function formRequestOptions(location: LocationRef | undefined) {
  if (!location) return
  return {
    headers: {
      "x-opencode-directory": encodeURIComponent(location.directory),
    },
  }
}

function formAlreadySettled(error: unknown) {
  return !!error && typeof error === "object" && "_tag" in error && error._tag === "FormAlreadySettledError"
}

const RESIZE_DELAY = 250
const LOCAL_REPLAY_ROW_LIMIT = 100

function abortable<A>(task: Promise<A>, signal: AbortSignal): Promise<A | undefined> {
  if (signal.aborted) return Promise.resolve(undefined)
  return new Promise((resolve) => {
    const abort = () => {
      signal.removeEventListener("abort", abort)
      resolve(undefined)
    }
    signal.addEventListener("abort", abort, { once: true })
    void task.then(
      (value) => {
        signal.removeEventListener("abort", abort)
        resolve(value)
      },
      () => {
        signal.removeEventListener("abort", abort)
        resolve(undefined)
      },
    )
  })
}

// Core runtime loop. Boot resolves the SDK context, then we set up the
// lifecycle (renderer + footer), wire the stream transport for SDK events,
// and feed prompts through the queue until the user exits.
//
// Files only attach on the first prompt turn -- after that, includeFiles
// flips to false so subsequent turns don't re-send attachments.
async function runInteractiveRuntime(input: RunRuntimeInput, deps: RunRuntimeDeps = {}): Promise<void> {
  const start = input.host.startup.now()
  const log = input.host.diagnostics.trace
  const config = input.config
  const configState: { current: MiniSettings } = { current: resolveMiniSettings() }
  const tuiConfigTask = resolveRunTuiConfig(input.tuiConfig, input.host.platform).then((tuiConfig) => {
    configState.current = resolveMiniSettings(tuiConfig)
    return tuiConfig
  })
  const ctx = await input.boot()
  const runtimeController = new AbortController()
  const session = {
    first: true,
    history: [] as RunPrompt[],
    model: undefined as RunInput["model"],
    variant: undefined as string | undefined,
  }
  const savedVariant = await input.host.preferences.resolveVariant(ctx.model)
  const state: RuntimeState = {
    sdk: ctx.sdk,
    shown: !session.first,
    model: ctx.model ?? session.model,
    defaultModel: undefined,
    providers: [],
    variants: [],
    activeVariant: resolveVariant(ctx.variant, session.variant, savedVariant, []),
    sessionID: "",
    history: [...session.history],
    localRows: [],
    agent: ctx.agent,
    location: ctx.location,
  }
  const settleForm = async (sessionID: string, formID: string) => {
    if (!state.stream) return
    const stream = await state.stream
    stream.handle.settleForm?.(sessionID, formID)
  }
  const shell = await (deps.createRuntimeLifecycle ?? createRuntimeLifecycle)({
    host: input.host,
    getDirectory: () => state.location.directory,
    findFiles: (query) =>
      state.sdk.file
        .find({
          query,
          type: "file",
          location: { directory: state.location.directory },
        })
        .then((result) => result.data.map((file) => file.path))
        .catch(() => []),
    agents: [],
    references: [],
    sessionID: state.sessionID,
    sessionTitle: state.sessionTitle,
    getSessionID: () => state.sessionID,
    first: session.first,
    history: state.history,
    agent: state.agent,
    model: state.model,
    variant: state.activeVariant,
    tuiConfig: tuiConfigTask,
    onMiniSettingChange: config
      ? async (change) => {
          const info = await config.update((draft) => {
            if (!draft.mini || typeof draft.mini !== "object") draft.mini = {}
            if (change.key === "verbosity") {
              Object.assign(draft.mini, verbosityPreset(change.value))
              return
            }
            draft.mini[change.key] = change.value
          })
          configState.current = resolveMiniSettings(info)
          return configState.current
        }
      : undefined,
    onPermissionReply: async (next) => {
      if (state.demo?.permission(next)) {
        return
      }

      log?.write("send.permission.reply", next)
      await state.sdk.permission.reply(next)
    },
    onFormReply: async (next) => {
      if (state.demo?.formReply(next)) return
      try {
        await state.sdk.session.form.reply(next, formRequestOptions(next.sessionID === "global" ? next.location : undefined))
      } catch (error) {
        if (!formAlreadySettled(error)) throw error
      }
      await settleForm(next.sessionID, next.formID)
    },
    onFormCancel: async (next) => {
      if (state.demo?.formCancel(next)) return
      try {
        await state.sdk.session.form.cancel(next, formRequestOptions(next.sessionID === "global" ? next.location : undefined))
      } catch (error) {
        if (!formAlreadySettled(error)) throw error
      }
      await settleForm(next.sessionID, next.formID)
    },
    onCycleVariant: () => {
      const model = state.model ?? state.defaultModel
      if (!model || state.variants.length === 0) {
        return {
          status: "no variants available",
        }
      }

      if (!state.model) state.model = model
      state.activeVariant = cycleVariant(state.activeVariant, state.variants)
      void input.host.preferences.saveVariant(model, state.activeVariant)
      return {
        status: state.activeVariant ? `variant ${state.activeVariant}` : "variant default",
        modelLabel: formatModelLabel(model, state.activeVariant, state.providers),
        variant: state.activeVariant,
      }
    },
    onAgentSelect: (agent) => {
      state.agent = agent
    },
    onModelSelect: async (model) => {
      if (state.model?.providerID === model.providerID && state.model.modelID === model.modelID) {
        return
      }

      state.model = model
      state.activeVariant = undefined
      state.variants = variantsFor(state.providers, model)
      const switching = input.host.preferences.resolveVariant(model).then((saved) => {
        const current = state.model
        if (!current || current.providerID !== model.providerID || current.modelID !== model.modelID) {
          return
        }

        state.activeVariant = resolveVariant(undefined, undefined, saved, state.variants)
      })
      state.switching = switching
      await switching
      if (state.switching === switching) {
        state.switching = undefined
      }

      const current = state.model
      if (!current || current.providerID !== model.providerID || current.modelID !== model.modelID) {
        return
      }

      return {
        modelLabel: formatModelLabel(model, state.activeVariant, state.providers),
        status: `model ${model.modelID}`,
        variant: state.activeVariant,
        variants: state.variants,
      }
    },
    onVariantSelect: async (variant) => {
      const model = state.model ?? state.defaultModel
      if (!model || state.variants.length === 0) {
        return {
          status: "no variants available",
        }
      }

      if (variant && !state.variants.includes(variant)) {
        return {
          status: `variant ${variant} unavailable`,
        }
      }

      if (!state.model) state.model = model
      state.activeVariant = variant
      void input.host.preferences.saveVariant(model, state.activeVariant)
      return {
        status: state.activeVariant ? `variant ${state.activeVariant}` : "variant default",
        modelLabel: formatModelLabel(model, state.activeVariant, state.providers),
        variant: state.activeVariant,
        variants: state.variants,
      }
    },
    onInterrupt: () => {
      if (state.demo?.interrupt()) return true
      if (!state.sessionID) {
        return false
      }

      // No in-flight guard: interruption acknowledges immediately server-side and repeating
      // it is an idempotent no-op, so repeated presses are never swallowed.
      void (
        state.stream
          ? state.stream.then((item) => item.handle.interruptActiveTurn())
          : state.sdk.session.interrupt({ sessionID: state.sessionID, resume: true })
      ).catch(() => {})
      return true
    },
    onBackground: () => {
      if (!state.sessionID) {
        return
      }

      log?.write("send.background", { sessionID: state.sessionID })
      void state.sdk.session.background({ sessionID: state.sessionID }).catch(() => {})
    },
    onQueuedPromptAction: async (action, inboxID) => {
      if (!state.sessionID) return
      log?.write(`send.pending.${action}`, { sessionID: state.sessionID, inboxID })
      if (action === "cancel") {
        await state.sdk.session.inbox.cancel({ sessionID: state.sessionID, inboxID })
        return
      }
      await state.sdk.session.inbox.update({ sessionID: state.sessionID, inboxID, delivery: action })
    },
    onSubagentInterrupt: (sessionID) => {
      log?.write("send.subagent.interrupt", { sessionID })
      void state.sdk.session.interrupt({ sessionID }).catch(() => {})
    },
    onSubagentSelect: (sessionID) => {
      state.selectSubagent?.(sessionID)
      log?.write("subagent.select", {
        sessionID,
      })
    },
  })
  await tuiConfigTask
  const thinking = () => configState.current.thinking === "show"
  const footer = shell.footer
  const firstPaint = footer.idle().catch(() => {})
  const offRuntimeClose = footer.onClose(() => {
    state.demo?.interrupt()
    runtimeController.abort()
  })
  let clientGeneration = 0
  let clientController = new AbortController()
  let modelAttempt: AbortController | undefined
  let modelLoad: Promise<void> | undefined
  let modelLoadQueued = false
  let modelLoadStarted = false

  const updateClient = (sdk: RunInput["sdk"]) => {
    if (state.sdk === sdk) return
    state.sdk = sdk
    clientGeneration++
    clientController.abort()
    clientController = new AbortController()
    modelAttempt?.abort()
    if (modelLoadStarted && !state.model) void requestModelLoad()
  }

  const clientAttempt = (signal?: AbortSignal): ClientAttempt => ({
    sdk: state.sdk,
    generation: clientGeneration,
    signal: AbortSignal.any(
      signal
        ? [runtimeController.signal, clientController.signal, signal]
        : [runtimeController.signal, clientController.signal],
    ),
  })

  const currentClient = (attempt: ClientAttempt) =>
    !footer.isClosed && !attempt.signal.aborted && attempt.generation === clientGeneration && attempt.sdk === state.sdk

  const ensureSession = () => {
    if (state.sessionID) {
      return Promise.resolve()
    }

    if (state.session) {
      return state.session
    }

    const task = input
      .resolveSession(state.sdk, runtimeController.signal)
      .then(async (next) => {
        if (next.sdk) updateClient(next.sdk)
        if (footer.isClosed || runtimeController.signal.aborted) return
        state.sessionID = next.sessionID
        state.sessionTitle = next.sessionTitle ?? state.sessionTitle
        shell.setTitle(state.sessionTitle)
        state.agent = next.agent
        state.location = next.location
        state.model = next.model
        state.activeVariant = next.variant
        footer.event({ type: "agent", agent: state.agent })
        if (!next.resume) return
        const resumed = await resolveSessionInfo(state.sdk, next.sessionID, next.model, runtimeController.signal)
        if (footer.isClosed || runtimeController.signal.aborted) return
        session.first = resumed.first
        session.history = resumed.history
        session.model = resumed.model
        session.variant = resumed.variant
        state.shown = !resumed.first
        state.history = [...resumed.history]
        state.model = next.model ?? resumed.model
        const resumedSavedVariant = state.model ? await input.host.preferences.resolveVariant(state.model) : undefined
        state.activeVariant = resolveVariant(next.variant, resumed.variant, resumedSavedVariant, [])
        session.variant = state.activeVariant
        footer.event({ type: "history", history: resumed.history })
        footer.event({ type: "first", first: resumed.first })
        if (footer.isClosed || runtimeController.signal.aborted) return
        await shell.resetForReplay()
      })
      .catch((error) => {
        if (footer.isClosed || runtimeController.signal.aborted) return
        throw error
      })
    state.session = task
    void task.catch(() => {
      if (state.session === task) state.session = undefined
    })
    return task
  }

  const currentModelLoad = (generation: number, sdk: RunInput["sdk"]) =>
    !footer.isClosed && !runtimeController.signal.aborted && generation === clientGeneration && sdk === state.sdk

  const loadCurrentModel = async () => {
    const generation = clientGeneration
    const sdk = state.sdk
    const selected = state.model
    const controller = new AbortController()
    const signal = AbortSignal.any([runtimeController.signal, controller.signal])
    modelAttempt = controller
    try {
      const info = await abortable(resolveModelInfo(sdk, state.location, signal), signal)
      if (
        !info ||
        !currentModelLoad(generation, sdk) ||
        (selected && (state.model?.providerID !== selected.providerID || state.model.modelID !== selected.modelID))
      )
        return
      applyModelInfo(
        info,
        selected ? session.variant : state.activeVariant,
        { sdk, generation, signal },
        !!selected,
        savedVariant,
      )
    } finally {
      if (modelAttempt === controller) modelAttempt = undefined
    }
  }

  function requestModelLoad(): Promise<void> {
    modelLoadQueued = true
    if (modelLoad || footer.isClosed) return modelLoad ?? Promise.resolve()
    const task = (async () => {
      while (modelLoadQueued && !footer.isClosed) {
        modelLoadQueued = false
        await loadCurrentModel()
      }
    })()
    modelLoad = task
    const cleanup = () => {
      if (modelLoad === task) modelLoad = undefined
      if (modelLoadQueued && !footer.isClosed) void requestModelLoad()
    }
    void task.then(cleanup, cleanup)
    return task
  }

  const modelTask = firstPaint.then(async () => {
    if (footer.isClosed) return
    await ensureSession()
    if (footer.isClosed) return
    modelLoadStarted = true
    return requestModelLoad()
  })
  const rememberLocal = (commit: StreamCommit) => {
    const last = state.localRows.at(-1)
    if (
      last &&
      (commit.kind === "assistant" || commit.kind === "reasoning") &&
      last.commit.kind === commit.kind &&
      last.commit.source === commit.source &&
      last.commit.messageID === commit.messageID &&
      last.commit.partID === commit.partID &&
      last.commit.tool === commit.tool
    ) {
      state.localRows = [...state.localRows.slice(0, -1), { commit }]
      return
    }
    state.localRows = [...state.localRows, { commit }].slice(-LOCAL_REPLAY_ROW_LIMIT)
  }

  const applyCatalog = (
    catalog: {
      agents: Awaited<ReturnType<typeof loadRunAgents>>
      references: Awaited<ReturnType<typeof loadRunReferences>>
      commands: Awaited<ReturnType<typeof loadRunCommands>>
    },
    attempt: ClientAttempt,
  ) => {
    if (!currentClient(attempt)) return
    footer.event({
      type: "catalog",
      agents: catalog.agents,
      references: catalog.references,
      commands: catalog.commands,
    })
  }

  const fetchCatalog = async (attempt: ClientAttempt) => {
    const [agents, references, commands] = await Promise.all([
      loadRunAgents(attempt.sdk, state.location, attempt.signal),
      loadRunReferences(attempt.sdk, state.location, attempt.signal),
      loadRunCommands(attempt.sdk, state.location, attempt.signal),
    ])
    return { agents, references, commands }
  }

  const loadCatalog = async (attempt: ClientAttempt) => {
    const catalog = await abortable(
      Promise.all([
        loadRunAgents(attempt.sdk, state.location, attempt.signal).catch(() => []),
        loadRunReferences(attempt.sdk, state.location, attempt.signal).catch(() => []),
        loadRunCommands(attempt.sdk, state.location, attempt.signal).catch(() => []),
      ]).then(([agents, references, commands]) => ({ agents, references, commands })),
      attempt.signal,
    )
    if (catalog) applyCatalog(catalog, attempt)
  }

  function applyModelInfo(
    info: Awaited<ReturnType<typeof resolveModelInfo>>,
    current: string | undefined,
    attempt: ClientAttempt,
    boot = false,
    saved = savedVariant,
  ) {
    if (!currentClient(attempt)) return
    state.providers = info.providers
    const model = state.model ?? state.defaultModel
    state.variants = variantsFor(state.providers, model)
    state.activeVariant = boot
      ? resolveVariant(ctx.variant, current, saved, state.variants)
      : current && !state.variants.includes(current)
        ? undefined
        : current
    if (footer.isClosed) return
    footer.event({ type: "models", providers: info.providers })
    footer.event({ type: "variants", variants: state.variants, current: state.activeVariant })
    if (model)
      footer.event({
        type: "model",
        model: formatModelLabel(model, state.activeVariant, state.providers),
        selection: model,
      })
  }

  let catalogRefresh:
    | {
        attempt: ClientAttempt
        source: AbortSignal | undefined
        queued: boolean
        task: Promise<void>
      }
    | undefined
  let defaultModelLoad: Promise<void> | undefined
  let defaultModelQueued = false
  const loadDefaultModel = (attempt: ClientAttempt) => {
    if (state.model || !currentClient(attempt)) return
    if (defaultModelLoad) {
      defaultModelQueued = true
      return
    }
    defaultModelQueued = false
    defaultModelLoad = attempt.sdk.model
      .default(
        {
          location: {
            directory: state.location.directory,
          },
        },
        { signal: attempt.signal },
      )
      .then(async (result) => {
        if (!result.data || state.model || !currentClient(attempt)) return
        const model = { providerID: result.data.providerID, modelID: result.data.id }
        const changed =
          state.defaultModel?.providerID !== model.providerID || state.defaultModel.modelID !== model.modelID
        const saved = changed ? await input.host.preferences.resolveVariant(model) : undefined
        if (state.model || !currentClient(attempt)) return
        state.defaultModel = model
        state.variants = variantsFor(state.providers, model)
        if (changed) state.activeVariant = resolveVariant(ctx.variant, state.activeVariant, saved, state.variants)
        if (state.activeVariant) state.model = model
        footer.event({ type: "variants", variants: state.variants, current: state.activeVariant })
        footer.event({
          type: "model",
          model: formatModelLabel(model, state.activeVariant, state.providers),
          selection: model,
        })
      })
      .catch(() => {})
      .finally(() => {
        defaultModelLoad = undefined
        if (defaultModelQueued) loadDefaultModel(clientAttempt())
      })
  }
  const requestCatalogRefresh = (signal?: AbortSignal): Promise<void> => {
    const attempt = clientAttempt(signal)
    if (!currentClient(attempt)) return Promise.resolve()
    const running = catalogRefresh
    if (
      running &&
      !running.attempt.signal.aborted &&
      running.attempt.generation === attempt.generation &&
      running.attempt.sdk === attempt.sdk
    ) {
      running.queued = true
      return running.task
    }

    const refresh = {
      attempt,
      source: signal,
      queued: true,
      task: Promise.resolve(),
    }
    const task = (async () => {
      await Promise.all([abortable(modelTask, attempt.signal), abortable(initialCatalog, attempt.signal)])
      while (refresh.queued && currentClient(attempt)) {
        refresh.queued = false
        const [catalog, info] = await Promise.all([
          abortable(fetchCatalog(attempt), attempt.signal),
          abortable(resolveModelInfoStrict(attempt.sdk, state.location, attempt.signal), attempt.signal),
        ])
        if (!currentClient(attempt)) return
        if (catalog) applyCatalog(catalog, attempt)
        if (info) applyModelInfo(info, state.activeVariant, attempt)
        loadDefaultModel(attempt)
      }
    })()
    refresh.task = task
    catalogRefresh = refresh
    const cleanup = () => {
      if (catalogRefresh !== refresh) return
      catalogRefresh = undefined
      if (refresh.queued && currentClient(attempt)) void requestCatalogRefresh(refresh.source)
    }
    void task.then(cleanup, cleanup)
    return task
  }

  const initialCatalog = firstPaint
    .then(() => (footer.isClosed ? undefined : ensureSession()))
    .then(() => (footer.isClosed ? undefined : loadCatalog(clientAttempt())))
    .catch(() => {})
  void initialCatalog

  if (input.host.startup.showTiming) {
    void firstPaint.then(() => {
      if (footer.isClosed) return
      footer.append({
        kind: "system",
        text: `startup ${Math.max(0, Math.round(input.host.startup.now() - start))}ms`,
        phase: "final",
        source: "system",
      })
    })
  }

  const createDemo = async () => {
    const { createRunDemo } = await import("./demo")
    return createRunDemo({
      footer,
      sessionID: state.sessionID,
      thinking: thinking(),
    })
  }

  if (input.demo) {
    await firstPaint
    if (!footer.isClosed) {
      await ensureSession()
      state.demo = await createDemo()
    }
  }

  let streamTask = deps.streamTransport
  const loadStreamTransport = () => {
    if (streamTask) return streamTask
    streamTask = import("./stream-v2.transport")
    return streamTask
  }
  const ensureStream = () => {
    if (state.stream) {
      return state.stream
    }

    // Share eager prewarm and first-turn boot through one in-flight promise,
    // but clear it if transport creation fails so a later prompt can retry.
    const next = (async () => {
      await ensureSession()
      if (footer.isClosed) {
        throw new Error("runtime closed")
      }

      const mod = await loadStreamTransport()
      if (footer.isClosed) {
        throw new Error("runtime closed")
      }

      const handle = await mod.createSessionTransport({
        sdk: state.sdk,
        reconnect: input.reconnect,
        onClient: updateClient,
        readTextFile: input.host.files.readText,
        location: state.location,
        sessionID: state.sessionID,
        thinking: thinking(),
        tools: configState.current.tools === "show",
        replay: input.replay,
        replayLimit: input.replayLimit,
        footer,
        onCommit: rememberLocal,
        onSessionTitle: (title) => {
          state.sessionTitle = title
          shell.setTitle(title)
        },
        trace: log,
        onCatalogRefresh: requestCatalogRefresh,
        contextLimit: (model) =>
          state.providers.find((provider) => provider.id === model.providerID)?.models[model.modelID]?.limit?.context,
      })
      if (footer.isClosed) {
        await handle.close()
        throw new Error("runtime closed")
      }

      state.selectSubagent = (sessionID) => handle.selectSubagent(sessionID)
      return { mod, handle }
    })()
    state.stream = next
    void next.catch(() => {
      if (state.stream === next) {
        state.stream = undefined
      }
    })
    return next
  }

  let resizeTimer: ReturnType<typeof setTimeout> | undefined
  const offResize = shell.onResize(() => {
    if (resizeTimer) {
      clearTimeout(resizeTimer)
    }

    resizeTimer = setTimeout(() => {
      resizeTimer = undefined
      if (footer.isClosed) {
        return
      }

      shell.refreshTheme()
      if (!input.replay || !state.stream) {
        return
      }

      void state.stream
        .then((item) =>
          item.handle.replayOnResize({
            localRows: () => state.localRows,
            reset: () => shell.resetForReplay(),
          }),
        )
        .catch(() => {})
    }, RESIZE_DELAY)
  })

  const renderPromptError = async (prompt: RunPrompt, error: unknown, signal?: AbortSignal) => {
    if (signal?.aborted || footer.isClosed) return
    const text =
      (await state.stream?.then((item) => item.mod).catch(() => undefined))?.formatUnknownError(error) ??
      errorMessage(error)
    const commit = {
      kind: "error",
      text,
      phase: "start",
      source: "system",
      messageID: prompt.messageID,
    } as const
    rememberLocal(commit)
    footer.append(commit)
  }

  const runQueue = async () => {
    await firstPaint
    if (footer.isClosed) return
    await ensureSession()
    if (footer.isClosed) return
    await modelTask
    if (footer.isClosed) return
    let includeFiles = true
    if (state.demo) {
      await state.demo.start()
    }

    const mod = await import("./runtime.queue")
    const createSession = input.createSession
    await mod.runPromptQueue({
      footer,
      initialInput: input.initialInput,
      trace: log,
      onSend: (prompt, emittedUser) => {
        state.shown = true
        state.history.push({ ...prompt, delivery: undefined })
        // Pending inputs can still be cancelled; only replay rows already printed.
        if (emittedUser) {
          rememberLocal({
            kind: "user",
            text: prompt.text,
            phase: "start",
            source: "system",
            messageID: prompt.messageID,
          })
        }
      },
      admit: async (prompt, delivery, signal) => {
        await state.switching?.catch(() => {})
        const next = await ensureStream()
        await next.handle.admitPromptTurn(
          {
            agent: state.agent,
            model: state.model,
            variant: state.activeVariant,
            prompt,
            files: input.files,
            includeFiles: false,
            signal,
          },
          delivery,
        )
      },
      onAdmissionError: renderPromptError,
      onCompact: async () => {
        await state.sdk.session.compact({ sessionID: state.sessionID }, formRequestOptions(state.location))
      },
      settle: async () => {
        const next = await ensureStream()
        await next.handle.waitForIdle()
      },
      onNewSession: createSession
        ? async () => {
            try {
              await state.switching?.catch(() => {})
              const created = await createSession(
                state.sdk,
                {
                  location: newSessionLocation(
                    (await tuiConfigTask).session.new_location,
                    input.directory,
                    state.location,
                  ),
                  agent: state.agent,
                  model: state.model,
                  variant: state.activeVariant,
                },
                runtimeController.signal,
              )
              if (!created.sessionID) throw new Error("Failed to create session")
              await footer.idle().catch(() => {})
              await state.stream?.then((item) => item.handle.close()).catch(() => {})
              state.stream = undefined
              state.session = undefined
              state.selectSubagent = undefined
              state.shown = false
              state.sessionID = created.sessionID
              state.sessionTitle = created.sessionTitle
              shell.setTitle(state.sessionTitle)
              state.agent = created.agent ?? state.agent
              state.location = created.location
              state.model = created.model
              state.activeVariant = created.variant
              footer.event({ type: "agent", agent: state.agent })
              state.history = []
              state.localRows = []
              includeFiles = true
              state.demo = input.demo ? await createDemo() : undefined
              log?.write("session.new", {
                sessionID: state.sessionID,
              })
              footer.event({
                type: "stream.subagent",
                state: {
                  tabs: [],
                  details: {},
                  permissions: [],
                  forms: [],
                },
              })
              footer.event({ type: "stream.view", view: { type: "prompt" } })
              footer.event({ type: "queued.prompts", prompts: [] })
              footer.event({
                type: "stream.patch",
                patch: {
                  phase: "idle",
                  usage: undefined,
                  first: true,
                },
              })
              footer.append({
                kind: "system",
                text: `new session ${state.sessionID}`,
                phase: "final",
                source: "system",
              })
              await state.demo?.start()
            } catch (error) {
              footer.event({
                type: "stream.patch",
                patch: {
                  phase: "idle",
                  status: "failed to start new session",
                },
              })
              const commit = {
                kind: "error",
                text: errorMessage(error),
                phase: "start",
                source: "system",
                messageID: SessionMessage.ID.create(),
              } as const
              rememberLocal(commit)
              footer.append(commit)
            }
          }
        : undefined,
      run: async (prompt, signal, admitted) => {
        if (state.demo && (await state.demo.prompt(prompt, signal))) {
          return
        }

        await state.switching?.catch(() => {})

        try {
          const next = await ensureStream()
          await next.handle.runPromptTurn(
            {
              agent: state.agent,
              model: state.model,
              variant: state.activeVariant,
              prompt,
              files: input.files,
              includeFiles,
              signal,
            },
            admitted,
          )
          if (prompt.messageID) {
            state.localRows = state.localRows.filter(
              (row) => row.commit.kind !== "user" || row.commit.messageID !== prompt.messageID,
            )
          }
          // Shell and skill turns never send CLI file attachments; keep them
          // pending for the next prompt-shaped turn.
          if (prompt.mode !== "shell" && prompt.command?.source !== "skill") includeFiles = false
        } catch (error) {
          await renderPromptError(prompt, error, signal)
        }
      },
    })
  }

  try {
    if (input.demo) {
      await firstPaint
      if (footer.isClosed) return
      await ensureStream()
    } else {
      void firstPaint
        .then(() => {
          if (footer.isClosed) {
            return
          }

          return ensureStream()
        })
        .catch(() => {})
    }

    try {
      await runQueue()
    } finally {
      if (resizeTimer) {
        clearTimeout(resizeTimer)
      }
      offResize()
      await state.stream?.then((item) => item.handle.close()).catch(() => {})
    }
  } finally {
    runtimeController.abort()
    offRuntimeClose()

    await shell.close({
      showExit: state.shown && !!state.sessionID,
      sessionTitle: state.sessionTitle,
      sessionID: state.sessionID,
      history: state.history,
    })
  }
}

// Deferred mode paints before session resolution. The caller may back the
// generated client with a transport that is still acquiring a daemon.
export async function runInteractiveDeferredMode(input: RunDeferredInput, deps?: RunRuntimeDeps): Promise<void> {
  const sdk = input.sdk

  return runInteractiveRuntime(
    {
      host: input.host,
      directory: input.directory,
      files: input.files,
      initialInput: input.initialInput,
      replay: input.replay,
      replayLimit: input.replayLimit,
      demo: input.demo,
      tuiConfig: input.tuiConfig,
      config: input.config,
      reconnect: input.reconnect,
      resolveSession: input.target,
      createSession: input.createSession,
      boot: async () => {
        return {
          sdk,
          location: { directory: input.directory },
          agent: input.agent,
          model: input.model,
          variant: input.variant,
        }
      },
    },
    deps,
  )
}

import { SyntaxStyle, TextAttributes, type ColorInput } from "@opentui/core"
import { type RunEntryTheme, type RunTheme } from "./theme"
import type { StreamCommit } from "./types"

function syntax(style?: SyntaxStyle): SyntaxStyle {
  return style ?? SyntaxStyle.fromTheme([])
}

export function entrySyntax(theme: RunTheme): SyntaxStyle {
  return syntax(theme.block.syntax)
}

function entryFailed(commit: StreamCommit): boolean {
  return commit.kind === "tool" && (commit.toolState === "error" || commit.part?.state.status === "error")
}

export function entryLook(commit: StreamCommit, theme: RunEntryTheme): { fg: ColorInput; attrs?: number } {
  if (commit.kind === "user") {
    return {
      fg: theme.user.body,
      //attrs: TextAttributes.BOLD,
    }
  }

  if (entryFailed(commit)) {
    return {
      fg: theme.error.body,
      attrs: TextAttributes.BOLD,
    }
  }

  if (commit.phase === "final") {
    return {
      fg: theme.system.body,
    }
  }

  if (commit.kind === "tool" && commit.phase === "start") {
    return {
      fg: theme.tool.start ?? theme.tool.body,
    }
  }

  if (commit.kind === "assistant") {
    return { fg: theme.assistant.body }
  }

  if (commit.kind === "reasoning") {
    return {
      fg: theme.reasoning.body,
    }
  }

  if (commit.kind === "error") {
    return {
      fg: theme.error.body,
      attrs: TextAttributes.BOLD,
    }
  }

  if (commit.kind === "tool") {
    return { fg: theme.tool.body }
  }

  return { fg: theme.system.body }
}

export function entryColor(commit: StreamCommit, theme: RunTheme): ColorInput {
  if (commit.kind === "assistant") {
    return theme.entry.assistant.body
  }

  if (commit.kind === "reasoning") {
    return theme.entry.reasoning.body
  }

  if (entryFailed(commit)) {
    return theme.entry.error.body
  }

  if (commit.kind === "tool") {
    return theme.block.text
  }

  return entryLook(commit, theme.entry).fg
}

// Retained streaming append logic for direct-mode scrollback.
//
// Static text entries are rendered through `scrollback.writer.tsx`. Retained
// surfaces keep streaming markdown/code layout stable and wait for image loads
// before their snapshots enter scrollback.
import {
  CodeRenderable,
  ImageRenderable,
  MarkdownRenderable,
  TextRenderable,
  getTreeSitterClient,
  type TreeSitterClient,
  type CliRenderer,
  type ScrollbackSurface,
} from "@opentui/core"
import { entryBody, entryCanStream, entryDone, entryFlags } from "./entry.body"
import { monoMarkdownRenderable, monoMarkdownTableOptions } from "./mono"
import { entryColor, entryLook, entrySyntax } from "./scrollback.shared"
import { turnSummaryCommit } from "./turn-summary"
import { entryWriter, sameEntryGroup, separatorRows, spacerWriter, turnSummaryWriter } from "./scrollback.writer"
import { type RunTheme } from "./theme"
import type { RunEntryBody, StreamCommit } from "./types"

type ActiveBody = Exclude<RunEntryBody, { type: "none" | "structured" }>

type ActiveEntry = {
  body: ActiveBody
  commit: StreamCommit
  surface: ScrollbackSurface
  renderable: TextRenderable | CodeRenderable | MarkdownRenderable
  content: string
  committedRows: number
  committedBlocks: number
  pendingSpacerRows: number
  rendered: boolean
}

function commitMarkdownBlocks(input: {
  surface: ScrollbackSurface
  renderable: MarkdownRenderable
  startBlock: number
  endBlockExclusive: number
  trailingNewline: boolean
  beforeCommit?: () => void
}) {
  if (input.endBlockExclusive <= input.startBlock) {
    return false
  }

  const first = input.renderable._blockStates[input.startBlock]
  const last = input.renderable._blockStates[input.endBlockExclusive - 1]
  if (!first || !last) {
    return false
  }

  const next = input.renderable._blockStates[input.endBlockExclusive]
  const start = first.renderable.y
  const end = next ? next.renderable.y : last.renderable.y + last.renderable.height

  input.beforeCommit?.()
  input.surface.commitRows(start, end, {
    trailingNewline: input.trailingNewline,
  })
  return true
}

function staticBody(commit: StreamCommit, body: RunEntryBody, spaced: number): RunEntryBody {
  if (spaced === 0 || body.type !== "text") {
    return body
  }

  if (commit.kind !== "tool" || commit.phase !== "progress" || commit.toolState !== "completed") {
    return body
  }

  if (!body.content.startsWith("\n")) {
    return body
  }

  return {
    ...body,
    content: body.content.replace(/^\n/, ""),
  }
}

export class RunScrollbackStream {
  private tail: StreamCommit | undefined
  private rendered: StreamCommit | undefined
  private active: ActiveEntry | undefined
  private imageSurface: ScrollbackSurface | undefined
  private treeSitterClient: TreeSitterClient | undefined
  private wrote: boolean
  private shellOutput: () => boolean
  private mono: boolean
  private imagePreview: boolean
  private destroyed = false
  private pendingThemes: RunTheme[] = []

  constructor(
    private renderer: CliRenderer,
    private theme: RunTheme,
    options: {
      wrote?: boolean
      treeSitterClient?: TreeSitterClient
      onThemeRelease?: (theme: RunTheme) => void
      shellOutput?: () => boolean
      mono?: boolean
      imagePreview?: boolean
    } = {},
  ) {
    this.treeSitterClient = options.treeSitterClient
    this.wrote = options.wrote ?? false
    this.shellOutput = options.shellOutput ?? (() => true)
    this.mono = options.mono ?? false
    this.imagePreview = options.imagePreview ?? false
    this.onThemeRelease = options.onThemeRelease
  }

  private onThemeRelease: ((theme: RunTheme) => void) | undefined

  public async setMono(mono: boolean): Promise<void> {
    if (this.mono === mono) return
    const active = this.active
    if (active?.body.type !== "markdown") await this.complete()
    this.mono = mono
    if (active?.body.type !== "markdown") return

    // Rebuild the Markdown tree, keeping its source and printed block boundary.
    // Mono hooks are one-way, and ending the entry would lose open fence/list context.
    const next = this.createEntry(active.commit, active.body)
    this.active = { ...active, surface: next.surface, renderable: next.renderable }
    active.surface.destroy()
    this.releasePendingThemes()
  }

  private releasePendingThemes(): void {
    if (this.pendingThemes.length === 0) {
      return
    }

    for (const theme of this.pendingThemes.splice(0)) this.onThemeRelease?.(theme)
  }

  public setTheme(theme: RunTheme): void {
    if (this.theme === theme) {
      return
    }

    const previous = this.theme
    this.theme = theme
    const active = this.active
    if (!active) {
      this.onThemeRelease?.(previous)
      return
    }

    this.pendingThemes.push(previous)

    const style = entryLook(active.commit, theme.entry)
    if (active.renderable instanceof TextRenderable) {
      active.renderable.fg = style.fg
      active.renderable.attributes = style.attrs ?? 0
      return
    }

    active.renderable.fg = entryColor(active.commit, theme)
    active.renderable.syntaxStyle = entrySyntax(theme)
  }

  private createEntry(commit: StreamCommit, body: ActiveBody): ActiveEntry {
    const surface = this.renderer.createScrollbackSurface({
      startOnNewLine: entryFlags(commit).startOnNewLine,
    })
    const style = entryLook(commit, this.theme.entry)
    const treeSitterClient = body.type === "text" ? undefined : (this.treeSitterClient ??= getTreeSitterClient())
    const renderable =
      body.type === "text"
        ? new TextRenderable(surface.renderContext, {
            content: "",
            width: "100%",
            wrapMode: "word",
            fg: style.fg,
            attributes: style.attrs,
          })
        : body.type === "code"
          ? new CodeRenderable(surface.renderContext, {
              content: "",
              filetype: body.filetype,
              syntaxStyle: entrySyntax(this.theme),
              width: "100%",
              wrapMode: "word",
              drawUnstyledText: false,
              streaming: true,
              fg: entryColor(commit, this.theme),
              treeSitterClient,
            })
          : new MarkdownRenderable(surface.renderContext, {
              content: "",
              syntaxStyle: entrySyntax(this.theme),
              width: "100%",
              streaming: true,
              internalBlockMode: "top-level",
              tableOptions: this.mono ? monoMarkdownTableOptions : { widthMode: "content" },
              fg: entryColor(commit, this.theme),
              treeSitterClient,
            })

    if (this.mono && renderable instanceof MarkdownRenderable) monoMarkdownRenderable(renderable)
    surface.root.add(renderable)

    const rows = separatorRows(this.rendered, commit, body)

    return {
      body,
      commit,
      surface,
      renderable,
      content: "",
      committedRows: 0,
      committedBlocks: 0,
      pendingSpacerRows: rows || (!this.rendered && this.wrote ? 1 : 0),
      rendered: false,
    }
  }

  private markRendered(commit: StreamCommit | undefined): void {
    if (!commit) {
      return
    }

    this.rendered = commit
  }

  private writeSpacer(rows: number): void {
    if (rows === 0) {
      return
    }

    this.renderer.writeToScrollback(spacerWriter())
    this.wrote = false
  }

  private flushPendingSpacer(active: ActiveEntry): void {
    this.writeSpacer(active.pendingSpacerRows)
    active.pendingSpacerRows = 0
  }

  private async flushActive(done: boolean, trailingNewline: boolean): Promise<boolean> {
    const active = this.active
    if (!active) {
      return false
    }

    if (active.body.type === "text") {
      if (!(active.renderable instanceof TextRenderable)) {
        return false
      }

      const renderable = active.renderable
      renderable.content = active.content
      active.surface.render()
      this.releasePendingThemes()
      const targetRows = done ? active.surface.height : Math.max(active.committedRows, active.surface.height - 1)
      if (targetRows <= active.committedRows) {
        return false
      }

      this.flushPendingSpacer(active)
      active.surface.commitRows(active.committedRows, targetRows, {
        trailingNewline: done && targetRows === active.surface.height ? trailingNewline : false,
      })
      active.committedRows = targetRows
      active.rendered = true
      return true
    }

    if (active.body.type === "code") {
      if (!(active.renderable instanceof CodeRenderable)) {
        return false
      }

      const renderable = active.renderable
      renderable.content = active.content
      renderable.streaming = !done
      await active.surface.settle()
      this.releasePendingThemes()
      const targetRows = done ? active.surface.height : Math.max(active.committedRows, active.surface.height - 1)
      if (targetRows <= active.committedRows) {
        return false
      }

      this.flushPendingSpacer(active)
      active.surface.commitRows(active.committedRows, targetRows, {
        trailingNewline: done && targetRows === active.surface.height ? trailingNewline : false,
      })
      active.committedRows = targetRows
      active.rendered = true
      return true
    }

    if (!(active.renderable instanceof MarkdownRenderable)) {
      return false
    }

    const renderable = active.renderable
    renderable.content = active.content
    renderable.streaming = !done
    await active.surface.settle()
    this.releasePendingThemes()
    const targetBlockCount = done ? renderable._blockStates.length : renderable._stableBlockCount
    if (targetBlockCount <= active.committedBlocks) {
      return false
    }

    if (
      commitMarkdownBlocks({
        surface: active.surface,
        renderable,
        startBlock: active.committedBlocks,
        endBlockExclusive: targetBlockCount,
        trailingNewline: done && targetBlockCount === renderable._blockStates.length ? trailingNewline : false,
        beforeCommit: () => this.flushPendingSpacer(active),
      })
    ) {
      active.committedBlocks = targetBlockCount
      active.rendered = true
      return true
    }

    return false
  }

  private async finishActive(trailingNewline: boolean): Promise<StreamCommit | undefined> {
    if (!this.active) {
      return undefined
    }

    const active = this.active

    try {
      await this.flushActive(true, trailingNewline)
    } finally {
      if (this.active === active) {
        this.active = undefined
      }

      if (!active.surface.isDestroyed) {
        active.surface.destroy()
      }
      this.releasePendingThemes()
    }

    return active.rendered ? active.commit : undefined
  }

  private async writeStreaming(commit: StreamCommit, body: ActiveBody): Promise<void> {
    if (!this.active || !sameEntryGroup(this.active.commit, commit) || this.active.body.type !== body.type) {
      this.markRendered(await this.finishActive(false))
      this.active = this.createEntry(commit, body)
    }

    this.active.body = body
    this.active.commit = commit
    this.active.content += body.content
    await this.flushActive(false, false)
    if (this.active.rendered) {
      this.markRendered(this.active.commit)
    }
  }

  private async writeImage(commit: StreamCommit): Promise<void> {
    const surface = this.renderer.createScrollbackSurface(entryFlags(commit))
    this.imageSurface = surface

    try {
      const image = new ImageRenderable(surface.renderContext, {
        source: commit.image,
        fit: "fit",
        visible: false,
        alignSelf: "flex-start",
        flexShrink: 0,
      })
      surface.root.add(image)
      // settle() waits for code highlighting, not image decoding.
      await image.loadPromise
      if (surface.isDestroyed) return

      const body = entryBody(commit, { mono: this.mono })
      if (body.type !== "text") return
      const style = entryLook(commit, this.theme.entry)
      const caption = new TextRenderable(surface.renderContext, {
        content: body.content + (image.image ? "" : "\nNo preview"),
        width: "100%",
        wrapMode: "word",
        fg: style.fg,
        attributes: style.attrs,
        flexShrink: 0,
      })
      surface.root.add(caption, 0)
      surface.render()

      if (image.image && !this.mono) {
        const resolution = this.renderer.resolution
        const fitted = image.getFittedSize(
          Math.min(
            surface.width,
            resolution?.width
              ? Math.max(1, Math.floor((image.image.width * this.renderer.terminalWidth) / resolution.width))
              : Infinity,
          ),
          Math.min(
            Math.max(0, this.renderer.terminalHeight - this.renderer.height - caption.height),
            resolution?.height
              ? Math.max(1, Math.floor((image.image.height * this.renderer.terminalHeight) / resolution.height))
              : Infinity,
          ),
          image.cellAspectRatio,
        )
        // fit centers within its rectangle, so the rectangle itself must be fitted.
        image.width = fitted.width
        image.height = fitted.height
        image.visible = fitted.width > 0 && fitted.height > 0
        surface.render()
      }

      this.writeSpacer(separatorRows(this.rendered, commit, body) || (!this.rendered && this.wrote ? 1 : 0))
      surface.commitRows(0, surface.height, { trailingNewline: entryFlags(commit).trailingNewline })
      this.markRendered(commit)
    } finally {
      surface.destroy()
      this.imageSurface = undefined
    }
  }

  public async append(commit: StreamCommit): Promise<void> {
    if (this.destroyed || this.renderer.isDestroyed) return
    const same = sameEntryGroup(this.tail, commit)
    if (!same || commit.image) {
      this.markRendered(await this.finishActive(false))
    }
    if (this.destroyed || this.renderer.isDestroyed) return

    if (commit.summary) {
      this.writeSpacer(1)
      this.renderer.writeToScrollback(turnSummaryWriter({ ...commit.summary, theme: this.theme, mono: this.mono }))
      this.markRendered(commit)
      this.tail = commit
      return
    }

    if (commit.image && this.imagePreview && !this.mono) {
      await this.writeImage(commit)
      this.tail = commit
      return
    }

    const body = entryBody(commit, { shellOutput: this.shellOutput(), mono: this.mono })
    if (body.type === "none") {
      if (entryDone(commit)) {
        this.markRendered(await this.finishActive(false))
      }

      this.tail = commit
      return
    }

    if (
      body.type !== "structured" &&
      (entryCanStream(commit, body) || (commit.kind === "tool" && commit.phase === "final" && body.type === "markdown"))
    ) {
      await this.writeStreaming(commit, body)
      if (entryDone(commit)) {
        this.markRendered(await this.finishActive(entryFlags(commit).trailingNewline))
      }
      this.tail = commit
      return
    }

    if (same) {
      this.markRendered(await this.finishActive(false))
    }

    const rows = separatorRows(this.rendered, commit, body)
    const spaced = rows || (!this.rendered && this.wrote ? 1 : 0)
    this.writeSpacer(spaced)

    this.renderer.writeToScrollback(
      entryWriter({
        commit,
        body: staticBody(commit, body, spaced),
        theme: this.theme,
        opts: { mono: this.mono },
      }),
    )
    this.markRendered(commit)
    this.tail = commit
  }

  private resetActive(): void {
    if (!this.active) {
      return
    }

    if (!this.active.surface.isDestroyed) {
      this.active.surface.destroy()
    }

    this.active = undefined
    this.releasePendingThemes()
  }

  public async complete(trailingNewline = false): Promise<void> {
    this.markRendered(await this.finishActive(trailingNewline))
  }

  public async writeTurnSummary(input: { agent: string; model: string; duration: string }): Promise<void> {
    await this.append(turnSummaryCommit(input))
  }

  public destroy(): void {
    this.destroyed = true
    this.imageSurface?.destroy()
    this.imageSurface = undefined
    this.resetActive()
    this.releasePendingThemes()
  }
}

import { createScrollbackWriter } from "@opentui/solid"
import {
  MarkdownRenderable,
  TextRenderable,
  type ColorInput,
  type ScrollbackRenderContext,
  type ScrollbackWriter,
} from "@opentui/core"
import { For, Match, Switch, createMemo } from "solid-js"
import { entryBody, entryFlags } from "./entry.body"
import { monoMarkdownRenderable, monoMarkdownTableOptions } from "./mono"
import { entryColor, entryLook, entrySyntax } from "./scrollback.shared"
import { toolFiletype, toolStructuredFinal } from "./tool"
import { RUN_THEME_FALLBACK, transparent, type RunTheme } from "./theme"
import type { EntryLayout, RunEntryBody, ScrollbackOptions, StreamCommit, TurnSummary } from "./types"
import { PatchDiff } from "../component/patch-diff"

export function entryGroupKey(commit: StreamCommit): string | undefined {
  if (!commit.partID) {
    return undefined
  }

  const part = `${commit.messageID ?? ""}\u0000${commit.partID}`
  if (toolStructuredFinal(commit)) {
    return `tool:${part}:final`
  }

  return `${commit.kind}:${part}`
}

export function sameEntryGroup(left: StreamCommit | undefined, right: StreamCommit): boolean {
  if (!left) {
    return false
  }

  const current = entryGroupKey(left)
  const next = entryGroupKey(right)
  return Boolean(current && next && current === next)
}

function entryLayout(commit: StreamCommit, body: RunEntryBody = entryBody(commit)): EntryLayout {
  if (commit.image) return "block"
  if (commit.kind === "tool") {
    if (body.type === "structured" || body.type === "markdown") {
      return "block"
    }

    if (
      commit.phase === "progress" &&
      commit.toolState === "completed" &&
      body.type === "text" &&
      body.content.includes("\n")
    ) {
      return "block"
    }

    return "inline"
  }

  return "block"
}

export function separatorRows(
  prev: StreamCommit | undefined,
  next: StreamCommit,
  body: RunEntryBody = entryBody(next),
): number {
  if (!prev || sameEntryGroup(prev, next)) {
    return 0
  }

  if (entryLayout(prev) === "inline" && entryLayout(next, body) === "inline") {
    return 0
  }

  return 1
}

export function RunEntryContent(props: {
  commit: StreamCommit
  body?: RunEntryBody
  theme?: RunTheme
  opts?: ScrollbackOptions
}) {
  const theme = createMemo(() => props.theme ?? RUN_THEME_FALLBACK)
  const body = createMemo(() => props.body ?? entryBody(props.commit, props.opts))
  const style = createMemo(() => entryLook(props.commit, theme().entry))
  const syntax = createMemo(() => entrySyntax(theme()))
  const color = createMemo(() => entryColor(props.commit, theme()))
  const suppressBackgrounds = createMemo(() => props.opts?.suppressBackgrounds === true)
  const diffBg = (color: ColorInput) => (suppressBackgrounds() ? transparent : color)
  const streaming = createMemo(() => props.commit.phase === "progress")
  const text = createMemo(() => {
    const next = body()
    return next.type === "text" ? next : undefined
  })
  const code = createMemo(() => {
    const next = body()
    return next.type === "code" ? next : undefined
  })
  const structured = createMemo(() => {
    const next = body()
    return next.type === "structured" ? next.snapshot : undefined
  })
  const markdown = createMemo(() => {
    const next = body()
    return next.type === "markdown" ? next : undefined
  })
  const code_snapshot = createMemo(() => {
    const next = structured()
    return next?.kind === "code" ? next : undefined
  })
  const diff_snapshot = createMemo(() => {
    const next = structured()
    return next?.kind === "diff" ? next : undefined
  })
  const task_snapshot = createMemo(() => {
    const next = structured()
    return next?.kind === "task" ? next : undefined
  })
  const question_snapshot = createMemo(() => {
    const next = structured()
    return next?.kind === "question" ? next : undefined
  })

  return (
    <Switch fallback={null}>
      <Match when={props.commit.compaction}>
        <box width="100%" flexDirection="row" alignItems="center">
          <box border={["top"]} borderColor={theme().block.muted} flexGrow={1} />
          <box paddingLeft={1} paddingRight={1}>
            <text fg={theme().block.muted}>{props.commit.text}</text>
          </box>
          <box border={["top"]} borderColor={theme().block.muted} flexGrow={1} />
        </box>
      </Match>
      <Match when={text()}>
        <text width="100%" wrapMode="word" fg={style().fg} attributes={style().attrs}>
          {text()!.content}
        </text>
      </Match>
      <Match when={code()}>
        <code
          width="100%"
          wrapMode="word"
          filetype={code()!.filetype}
          drawUnstyledText={false}
          streaming={streaming()}
          syntaxStyle={syntax()}
          content={code()!.content}
          fg={color()}
        />
      </Match>
      <Match when={code_snapshot()}>
        <box width="100%" flexDirection="column" gap={1}>
          <text width="100%" wrapMode="word" fg={theme().block.muted}>
            {code_snapshot()!.title}
          </text>
          <box width="100%" paddingLeft={1}>
            <line_number width="100%" fg={theme().block.muted} minWidth={3} paddingRight={1}>
              <code
                width="100%"
                wrapMode="char"
                filetype={toolFiletype(code_snapshot()!.file)}
                streaming={false}
                syntaxStyle={syntax()}
                content={code_snapshot()!.content}
                fg={theme().block.text}
              />
            </line_number>
          </box>
        </box>
      </Match>
      <Match when={diff_snapshot()}>
        <box width="100%" flexDirection="column" gap={1}>
          {diff_snapshot()!.items.map((item) => (
            <box width="100%" flexDirection="column" gap={1}>
              <text width="100%" wrapMode="word" fg={theme().block.muted}>
                {item.title}
              </text>
              {item.diff.trim() ? (
                <box width="100%" paddingLeft={1}>
                  <PatchDiff
                    diff={item.diff}
                    hunkFg={theme().block.diffLineNumber}
                    view="unified"
                    filetype={toolFiletype(item.file)}
                    syntaxStyle={syntax()}
                    showLineNumbers={true}
                    width="100%"
                    wrapMode="word"
                    fg={theme().block.text}
                    addedBg={diffBg(theme().block.diffAddedBg)}
                    removedBg={diffBg(theme().block.diffRemovedBg)}
                    contextBg={diffBg(theme().block.diffContextBg)}
                    addedSignColor={theme().block.diffHighlightAdded}
                    removedSignColor={theme().block.diffHighlightRemoved}
                    lineNumberFg={theme().block.diffLineNumber}
                    lineNumberBg={diffBg(theme().block.diffContextBg)}
                    addedLineNumberBg={diffBg(theme().block.diffAddedLineNumberBg)}
                    removedLineNumberBg={diffBg(theme().block.diffRemovedLineNumberBg)}
                  />
                </box>
              ) : (
                <text width="100%" wrapMode="word" fg={theme().block.diffRemoved}>
                  -{item.deletions ?? 0} line{item.deletions === 1 ? "" : "s"}
                </text>
              )}
            </box>
          ))}
        </box>
      </Match>
      <Match when={task_snapshot()}>
        <box width="100%" flexDirection="column" gap={1}>
          <text width="100%" wrapMode="word" fg={theme().block.muted}>
            {task_snapshot()!.title}
          </text>
          <box width="100%" flexDirection="column" gap={0} paddingLeft={1}>
            {task_snapshot()!.rows.map((row) => (
              <text width="100%" wrapMode="word" fg={theme().block.text}>
                {row}
              </text>
            ))}
            {task_snapshot()!.tail ? (
              <text width="100%" wrapMode="word" fg={theme().block.muted}>
                {task_snapshot()!.tail}
              </text>
            ) : null}
          </box>
        </box>
      </Match>
      <Match when={question_snapshot()}>
        <box width="100%" flexDirection="column" gap={1}>
          <text width="100%" wrapMode="word" fg={theme().block.muted}>
            # Questions
          </text>
          <box width="100%" flexDirection="column" gap={1}>
            {question_snapshot()!.items.map((item) => (
              <box width="100%" flexDirection="column" gap={0}>
                <text width="100%" wrapMode="word" fg={theme().block.muted}>
                  {item.question}
                </text>
                <text width="100%" wrapMode="word" fg={theme().block.text}>
                  {item.answer}
                </text>
              </box>
            ))}
            {question_snapshot()!.tail ? (
              <text width="100%" wrapMode="word" fg={theme().block.muted}>
                {question_snapshot()!.tail}
              </text>
            ) : null}
          </box>
        </box>
      </Match>
      <Match when={markdown()}>
        {/* Mono hooks mutate renderables, so toggling needs a fresh Markdown leaf. */}
        <For each={[props.opts?.mono === true]}>
          {(mono) => (
            <markdown
              ref={(renderable: MarkdownRenderable) => {
                if (mono) monoMarkdownRenderable(renderable)
              }}
              width="100%"
              syntaxStyle={syntax()}
              streaming={streaming()}
              content={markdown()!.content}
              fg={color()}
              tableOptions={mono ? monoMarkdownTableOptions : { widthMode: "content" }}
            />
          )}
        </For>
      </Match>
    </Switch>
  )
}

export function entryWriter(input: {
  commit: StreamCommit
  body?: RunEntryBody
  theme?: RunTheme
  opts?: ScrollbackOptions
}): ScrollbackWriter {
  return createScrollbackWriter(
    () => (
      <RunEntryContent
        commit={input.commit}
        body={input.body}
        theme={input.theme}
        opts={{ ...input.opts, suppressBackgrounds: true }}
      />
    ),
    entryFlags(input.commit),
  )
}

export function spacerWriter(): ScrollbackWriter {
  return (ctx: ScrollbackRenderContext) => ({
    root: new TextRenderable(ctx.renderContext, {
      width: Math.max(1, Math.trunc(ctx.width)),
      height: 1,
      content: "",
    }),
    width: Math.max(1, Math.trunc(ctx.width)),
    height: 1,
    startOnNewLine: true,
    trailingNewline: true,
  })
}

export function turnSummaryWriter(input: TurnSummary & { theme: RunTheme; mono?: boolean }) {
  return createScrollbackWriter(
    () => (
      <box width="100%" height={1}>
        <text wrapMode="none" truncate>
          <span style={{ fg: input.theme.block.text }}>{input.agent}</span>
          <span style={{ fg: input.theme.block.muted }}>
            {" "}
            {input.mono ? "-" : "·"} {input.model} {input.mono ? "-" : "·"} {input.duration}
          </span>
        </text>
      </box>
    ),
    { startOnNewLine: true, trailingNewline: false },
  )
}

import type { FooterView, MiniFormRequest, MiniPermissionRequest } from "./types"

export function pickBlockerView(input: { permission?: MiniPermissionRequest; form?: MiniFormRequest }): FooterView {
  if (input.permission) return { type: "permission", request: input.permission }
  if (input.form) return { type: "form", request: input.form }
  return { type: "prompt" }
}

export function blockerStatus(view: FooterView) {
  if (view.type === "permission") return "awaiting permission"
  if (view.type === "form") return "awaiting form"
  return ""
}

import type { SessionMessageInfo, SessionMessageUser } from "@opencode/client/promise"
import { projectedPromptInput } from "../prompt/codec"
import { requestOptions } from "./catalog.shared"
import { promptCopy, promptSame } from "./prompt.shared"
import type { RunInput, RunPrompt } from "./types"

const LIMIT = 200

export type SessionMessages = SessionMessageInfo[]

type Turn = {
  prompt: RunPrompt
  provider: string | undefined
  model: string | undefined
  variant: string | undefined
}

export type RunSession = {
  first: boolean
  turns: Turn[]
  model?: NonNullable<RunInput["model"]>
  variant?: string
}

export function messagePrompt(message: Pick<SessionMessageUser, "text" | "files" | "agents" | "skills">): RunPrompt {
  const input = projectedPromptInput(message)
  return {
    text: input.text,
    parts: [
      ...(input.files ?? []).map((file, index) => ({
        type: "file" as const,
        url: file.uri,
        mime: message.files?.[index]?.mime,
        filename: file.name,
        ...(file.description === undefined ? {} : { description: file.description }),
        source: file.mention
          ? {
              type: "file",
              path: file.name ?? (file.uri.startsWith("data:") ? "inline attachment" : file.uri),
              text: { start: file.mention.start, end: file.mention.end, value: file.mention.text },
            }
          : undefined,
      })),
      ...(input.agents ?? []).map((agent) => ({
        type: "agent" as const,
        name: agent.name,
        source: agent.mention
          ? { start: agent.mention.start, end: agent.mention.end, value: agent.mention.text }
          : undefined,
      })),
      ...(input.skills ?? []).map((skill) => ({
        type: "skill" as const,
        id: skill.id,
        source: skill.mention
          ? { start: skill.mention.start, end: skill.mention.end, value: skill.mention.text }
          : undefined,
      })),
    ],
  }
}

export function createSession(messages: SessionMessages): RunSession {
  return {
    first: messages.length === 0,
    turns: messages.flatMap((message) =>
      message.type === "user"
        ? [{ prompt: messagePrompt(message), provider: undefined, model: undefined, variant: undefined }]
        : [],
    ),
  }
}

export async function resolveCurrentSession(
  sdk: RunInput["sdk"],
  sessionID: string,
  signal?: AbortSignal,
  limit = LIMIT,
): Promise<RunSession> {
  const [response, session] = await Promise.all([
    sdk.message.list({ sessionID, limit, order: "desc" }, ...requestOptions(signal)),
    sdk.session.get({ sessionID }, ...requestOptions(signal)),
  ])
  const current = createSession(response.data.toReversed())
  return {
    ...current,
    turns: current.turns.map((turn) => ({
      ...turn,
      provider: session.model?.providerID,
      model: session.model?.id,
      variant: session.model?.variant,
    })),
    ...(session.model && {
      model: { providerID: session.model.providerID, modelID: session.model.id },
      variant: session.model.variant,
    }),
  }
}

export function sessionHistory(session: RunSession, limit = LIMIT): RunPrompt[] {
  return session.turns
    .map((turn) => turn.prompt)
    .filter((prompt) => prompt.text.trim() || prompt.parts.some((part) => part.type === "file"))
    .filter((prompt, index, prompts) => index === 0 || !promptSame(prompts[index - 1], prompt))
    .map(promptCopy)
    .slice(-limit)
}

export function sessionVariant(session: RunSession, model: RunInput["model"]): string | undefined {
  if (!model) return
  if (session.model?.providerID === model.providerID && session.model.modelID === model.modelID) return session.variant

  return session.turns.findLast((turn) => turn.provider === model.providerID && turn.model === model.modelID)?.variant
}

// Entry and exit splash banners for direct interactive mode scrollback.
//
// The entry header is a single flex row; the exit banner retains its cell-based
// logo and resume information. Both become immutable terminal history.
import {
  BoxRenderable,
  type ColorInput,
  TextAttributes,
  TextRenderable,
  StyledText,
  fg,
  type ScrollbackRenderContext,
  type ScrollbackSnapshot,
  type ScrollbackWriter,
} from "@opentui/core"
import { Locale } from "../util/locale"
import { stringWidth } from "../util/string-width"
import { go } from "../logo"
import { monoTruncate } from "./mono"
import type { RunSplashTheme } from "./theme"

const SPLASH_TITLE_LIMIT = 50
const SPLASH_TITLE_FALLBACK = "Untitled session"

type SplashInput = {
  title: string | undefined
  session_id: string
  mono?: boolean
}

type SplashWriterInput = SplashInput & {
  theme: RunSplashTheme
  showSession?: boolean
}

export type SplashMeta = {
  title: string
  session_id: string
}

type Cell = {
  char: string
  mark: "text" | "full" | "mix" | "top"
}

function cells(line: string): Cell[] {
  const list: Cell[] = []
  for (const char of line) {
    if (char === "_") {
      list.push({ char: " ", mark: "full" })
      continue
    }

    if (char === "^") {
      list.push({ char: "▀", mark: "mix" })
      continue
    }

    if (char === "~") {
      list.push({ char: "▀", mark: "top" })
      continue
    }

    list.push({ char, mark: "text" })
  }

  return list
}

function title(text: string | undefined, mono = false): string {
  if (!text) {
    return SPLASH_TITLE_FALLBACK
  }

  let value = ""
  let gap = false
  for (const char of text.trim()) {
    if (char === " " || char === "\n" || char === "\r" || char === "\t") {
      gap = true
      continue
    }

    if (gap && value.length > 0) {
      value += " "
    }

    value += char
    gap = false
  }

  if (!value) {
    return SPLASH_TITLE_FALLBACK
  }

  return mono ? monoTruncate(value, SPLASH_TITLE_LIMIT, true) : Locale.truncate(value, SPLASH_TITLE_LIMIT)
}

function write(
  root: BoxRenderable,
  ctx: ScrollbackRenderContext,
  line: {
    left: number
    top: number
    text: string
    fg: ColorInput
    bg?: ColorInput
    attrs?: number
  },
): void {
  if (line.left >= ctx.width) {
    return
  }

  root.add(
    new TextRenderable(ctx.renderContext, {
      position: "absolute",
      left: line.left,
      top: line.top,
      width: Math.max(1, ctx.width - line.left),
      height: 1,
      wrapMode: "none",
      content: line.text,
      fg: line.fg,
      bg: line.bg,
      attributes: line.attrs,
    }),
  )
}

function push(
  lines: Array<{ left: number; top: number; text: string; fg: ColorInput; bg?: ColorInput; attrs?: number }>,
  left: number,
  top: number,
  text: string,
  fg: ColorInput,
  bg?: ColorInput,
  attrs?: number,
): void {
  lines.push({ left, top, text, fg, bg, attrs })
}

function draw(
  lines: Array<{ left: number; top: number; text: string; fg: ColorInput; bg?: ColorInput; attrs?: number }>,
  row: string,
  input: {
    left: number
    top: number
    fg: ColorInput
    shadow: ColorInput
    attrs?: number
  },
) {
  let x = input.left
  for (const cell of cells(row)) {
    if (cell.mark === "full" || cell.mark === "mix") {
      push(lines, x, input.top, cell.char, input.fg, input.shadow, input.attrs)
      x += 1
      continue
    }

    if (cell.mark === "top") {
      push(lines, x, input.top, cell.char, input.shadow, undefined, input.attrs)
      x += 1
      continue
    }

    push(lines, x, input.top, cell.char, input.fg, undefined, input.attrs)
    x += 1
  }
}

function buildExit(input: SplashWriterInput, ctx: ScrollbackRenderContext): ScrollbackSnapshot {
  const width = Math.max(1, ctx.width)
  const meta = splashMeta(input)
  const lines: Array<{ left: number; top: number; text: string; fg: ColorInput; bg?: ColorInput; attrs?: number }> = []
  const left = input.theme.left
  const right = input.theme.right
  const leftShadow = input.theme.leftShadow
  const mark = input.mono ? ["[O]"] : go.right.slice(1)
  const top = 1
  const body_left = (mark[0]?.length ?? 0) + 2
  const session = "Session  "
  const label = "Continue "
  const command = `opencode mini -s ${meta.session_id}`
  const wide = body_left + stringWidth(label + command) <= width
  const commandHeight = wide ? 1 : Math.ceil(stringWidth(command) / width)

  if (wide) {
    for (let i = 0; i < mark.length; i += 1) {
      draw(lines, mark[i] ?? "", {
        left: 0,
        top: top + i,
        fg: left,
        shadow: leftShadow,
      })
    }

    if (input.showSession !== false) {
      push(lines, body_left, top, session, left)
      push(lines, body_left + session.length, top, meta.title, right, undefined, TextAttributes.BOLD)
    }
    push(lines, body_left, top + 1, label, left)
  }

  const height = top + (wide ? Math.max(mark.length, 2) : commandHeight)
  const root = new BoxRenderable(ctx.renderContext, {
    position: "absolute",
    left: 0,
    top: 0,
    width,
    height,
  })

  for (const line of lines) {
    write(root, ctx, line)
  }
  root.add(
    new TextRenderable(ctx.renderContext, {
      position: "absolute",
      left: wide ? body_left + label.length : 0,
      top: wide ? top + 1 : top,
      width: wide ? width - body_left - label.length : width,
      height: commandHeight,
      wrapMode: "char",
      content: command,
      fg: right,
      attributes: TextAttributes.BOLD,
    }),
  )

  return {
    root,
    width,
    height,
    rowColumns: width,
    startOnNewLine: true,
    trailingNewline: false,
  }
}

export function splashMeta(input: SplashInput): SplashMeta {
  return {
    title: title(input.title, input.mono),
    session_id: input.session_id,
  }
}

export function entrySplash(input: {
  version: string
  detail?: string
  mono?: boolean
  theme: RunSplashTheme
}): ScrollbackWriter {
  return (ctx) => {
    const width = Math.max(1, ctx.width)
    const layout = entrySplashLayout({ ...input, width })
    const root = new BoxRenderable(ctx.renderContext, {
      width,
      height: 2,
      paddingTop: 1,
      flexDirection: "row",
      overflow: "hidden",
    })
    root.add(
      new TextRenderable(ctx.renderContext, {
        content: new StyledText([fg(input.theme.right)(layout.label), fg(input.theme.left)(layout.metadata)]),
        width,
        height: 1,
        wrapMode: "none",
      }),
    )
    return { root, width, height: 2, rowColumns: width, startOnNewLine: true, trailingNewline: false }
  }
}

export function entrySplashLayout(input: { width: number; version: string; detail?: string; mono?: boolean }) {
  const detail = input.detail ?? ""
  const segments = detail.split(/[/\\]/).filter(Boolean)
  const leaf = segments.at(-1) ?? detail
  const separator = input.mono ? " - " : " · "
  const ellipsis = input.mono ? "..." : "…"
  const slash = detail.includes("\\") ? "\\" : "/"
  const paths = segments
    .slice(1)
    .map((_, index) => ellipsis + slash + segments.slice(index + 1).join(slash))
    .reverse()
    .filter((path) => stringWidth(path) < stringWidth(detail))
  let layout = { label: Locale.takeWidth("oc mini", input.width), version: "", path: "", metadata: "" }
  const stages = [
    { label: `${input.mono ? "[O]" : "▪"} oc mini` },
    ...(leaf ? [{ path: leaf }] : []),
    ...(input.version ? [{ version: input.version }] : []),
    ...paths.concat(detail ? [detail] : []).map((path) => ({ path })),
  ]
  // Stop at the first non-fitting stage instead of backfilling lower-priority metadata.
  for (const stage of stages) {
    const next = { ...layout, ...stage }
    const metadata = (next.version ? ` v${next.version}` : "") + (next.path ? separator + next.path : "")
    if (stringWidth(next.label + metadata) > input.width) break
    layout = { ...next, metadata }
  }
  return layout
}

export function exitSplash(input: SplashWriterInput): ScrollbackWriter {
  return (ctx) => buildExit(input, ctx)
}

export type FragmentRef = {
  messageID: string
  partID: string
}

type FragmentState = {
  text: string
  projected?: string
}

export type FragmentUpdate = FragmentRef & {
  key: string
  previous: string
  text: string
}

export type FragmentRestore = { type: "append"; suffix: string } | { type: "covered" } | { type: "conflict" }

export function fragmentRef(messageID: string, kind: "text" | "reasoning", ordinal: number): FragmentRef {
  return { messageID, partID: `${kind}:${ordinal}` }
}

export function createFragmentReconciler() {
  const fragments = new Map<string, FragmentState>()
  const key = (fragment: FragmentRef) => `${fragment.messageID}\u0000${fragment.partID}`

  return {
    clear() {
      fragments.clear()
    },
    key,
    value(fragment: FragmentRef) {
      return fragments.get(key(fragment))?.text
    },
    project(fragment: FragmentRef, text: string, visible: boolean): FragmentUpdate {
      const id = key(fragment)
      const current = fragments.get(id)
      fragments.set(id, {
        text,
        projected: visible ? text : current?.projected,
      })
      return { ...fragment, key: id, previous: current?.text ?? "", text }
    },
    delta(fragment: FragmentRef, delta: string): FragmentUpdate | undefined {
      const id = key(fragment)
      const current = fragments.get(id)
      // Replay may start after an unseen prefix, so consume a covered chunk
      // from anywhere in the remaining projection rather than only its start.
      const covered = current?.projected?.indexOf(delta) ?? -1
      if (current?.projected && covered >= 0) {
        current.projected = current.projected.slice(covered + delta.length)
        return
      }
      const previous = current?.text ?? ""
      const text = previous + delta
      fragments.set(id, { text, projected: current?.projected })
      return { ...fragment, key: id, previous, text }
    },
    end(fragment: FragmentRef, text: string): FragmentUpdate {
      const id = key(fragment)
      const previous = fragments.get(id)?.text ?? ""
      fragments.set(id, { text })
      return { ...fragment, key: id, previous, text }
    },
    restore(fragment: FragmentRef, text: string): FragmentRestore {
      const id = key(fragment)
      const current = fragments.get(id)
      if (!current) {
        fragments.set(id, { text, projected: text })
        return { type: "append", suffix: text }
      }
      if (text.startsWith(current.text)) {
        const suffix = text.slice(current.text.length)
        fragments.set(id, { text, projected: text })
        return { type: "append", suffix }
      }
      if (current.text.startsWith(text)) return { type: "covered" }
      return { type: "conflict" }
    },
  }
}

export type FragmentReconciler = ReturnType<typeof createFragmentReconciler>

import type { SessionMessageAssistantTool, SessionMessageUser } from "@opencode/client/promise"
import { deduplicateVisibleImages } from "../prompt/attachment"
import { toolDisplayContent } from "../util/tool-display"
import type { StreamCommit } from "./types"

export type ImageCommit = StreamCommit & { image: string; messageID: string; partID: string }

export function userImageCommits(messageID: string, files: SessionMessageUser["files"]): ImageCommit[] {
  return deduplicateVisibleImages(files ?? [])
    .filter((file) => file.mime.startsWith("image/"))
    .map((file, index) => ({
      kind: "user",
      source: "system",
      text: file.name ?? file.mention?.text ?? `[Image ${index + 1}]`,
      image: `data:${file.mime};base64,${file.data}`,
      phase: "final",
      messageID,
      partID: `image:${index}`,
    }))
}

export function toolImageCommits(part: SessionMessageAssistantTool, messageID: string): ImageCommit[] {
  return toolDisplayContent(part.state)
    .flatMap((content) =>
      content.type === "file" && content.mime.startsWith("image/") && content.uri.startsWith("data:image/")
        ? [content]
        : [],
    )
    .map((content, index) => ({
      kind: "tool",
      source: "tool",
      text: content.name ?? `[Image ${index + 1}]`,
      image: content.uri,
      phase: "final",
      messageID,
      partID: `prt_${part.id}:image:${index}`,
    }))
}

// Current-native subagent (child Session) tracking for the mini transport.
//
// Discovers child Sessions of the active parent from four current sources:
//   1. projected subagent tool output (`metadata.sessionID`) during hydration
//   2. the current session list filtered by `parentID` during hydration
//   3. the process-local active-session map during hydration
//   4. live events from unknown sessions whose `parentID` matches the parent
//
// Tracks one footer tab per child and a detail transcript for the selected
// child, reduced from the same current live event stream the parent uses.
// Detail transcripts rebuild from projected messages on discovery, selection,
// and reconnect, then continue from live deltas using the same
// projected-prefix dedup the parent transport uses.
//
// Per-child interruption uses `v2.session.interrupt(childID)`. Per-child
// backgrounding is intentionally absent: subagent jobs block the parent
// session, so only whole-session `v2.session.background(parentID)` exists.
import type {
  EventSubscribeOutput,
  OpenCodeClient,
  PermissionRequest,
  SessionMessageAssistantTool,
  SessionMessageInfo,
  SessionMessageUser,
} from "@opencode/client/promise"
import { Locale } from "../util/locale"
import { createFragmentReconciler, fragmentRef, type FragmentReconciler } from "./stream-v2.fragment"
import { toolImageCommits, userImageCommits } from "./stream-v2.image"
import type {
  FooterSubagentDetail,
  FooterSubagentState,
  FooterSubagentTab,
  MiniFormRequest,
  MiniPermissionRequest,
  StreamCommit,
} from "./types"
import { canonicalToolName, normalizeTool, toolOutputText, toolView } from "./tool"
import { toolDisplayContent } from "../util/tool-display"
import { isRecord } from "../util/record"

const CHILD_MESSAGE_LIMIT = 80
const CHILD_FRAME_LIMIT = 80
const CHILD_EVENT_BUFFER_LIMIT = 64
const FAMILY_LIST_LIMIT = 100
const FAMILY_DISCOVERY_CONCURRENCY = 8
const BLOCKER_RETRY_INITIAL_MS = 50
const BLOCKER_RETRY_MAX_MS = 2_000
const FALLBACK_LABEL = "Subagent"

type V2Event = EventSubscribeOutput

export function toolCommit(
  input: SessionMessageAssistantTool,
  messageID: string,
  phase: "start" | "progress" | "final",
  value?: string,
  directory?: string,
  version = 0,
): StreamCommit {
  const part = normalizeTool(input)
  const status = part.state.status
  const output = status === "streaming" ? "" : toolOutputText(part.name, toolDisplayContent(part.state))
  const partial = status === "error" && phase === "progress" && value !== undefined
  const text =
    status === "running" || partial
      ? (value ?? (part.name === "subagent" ? "running subagent" : `running ${part.name}`))
      : status === "completed"
        ? (value ?? output)
        : status === "error"
          ? part.state.error.message
          : ""
  return {
    kind: "tool",
    source: "tool",
    text,
    phase,
    messageID,
    partID: `prt_${part.id}${version > 0 ? `:snapshot:${version}` : ""}`,
    tool: part.name,
    directory,
    part,
    toolState: status === "error" && !partial ? "error" : status === "completed" ? "completed" : "running",
    toolError: status === "error" && !partial ? part.state.error.message : undefined,
  }
}

export function toolFinalPhase(part: SessionMessageAssistantTool) {
  const tool = normalizeTool(part)
  if (tool.state.status !== "completed") return "final" as const
  return toolView(tool.name).output && toolOutputText(tool.name, tool.state.content)
    ? ("progress" as const)
    : ("final" as const)
}

type Frame = {
  key: string
  commit: StreamCommit
}

type ToolTrack = {
  part: SessionMessageAssistantTool
}

type ChildState = {
  sessionID: string
  label: string
  description: string
  status: FooterSubagentTab["status"]
  background: boolean
  title?: string
  lastUpdatedAt: number
  frames: Frame[]
  fragments: FragmentReconciler
  tools: Map<string, ToolTrack>
  toolSources: Map<string, SessionMessageAssistantTool>
  finishedTools: Set<string>
  permissions: MiniPermissionRequest[]
  forms: MiniFormRequest[]
  messageIDs: Set<string>
  prompts: Map<string, Pick<SessionMessageUser, "text" | "files">>
  hydrated: boolean
  detailStale: boolean
  blockersHydrated: boolean
}

export type SubagentTrackerInput = {
  sessionID: string
  thinking: boolean
  directory?: string
  signal: AbortSignal
  emit: () => void
}

export type SubagentTracker = {
  main(sdk: OpenCodeClient, event: V2Event, signal?: AbortSignal): void
  foreign(sdk: OpenCodeClient, sessionID: string, event: V2Event, signal?: AbortSignal): void
  hydrate(next: {
    sdk: OpenCodeClient
    messages: SessionMessageInfo[]
    active: Record<string, unknown>
    signal?: AbortSignal
    reconnect?: boolean
  }): Promise<void>
  ready(): Promise<void>
  select(sdk: OpenCodeClient, sessionID: string | undefined): void
  snapshot(): FooterSubagentState
  settleForm(sessionID: string, formID: string): void
  close(): void
}

type DiscoveryJob = {
  sdk: OpenCodeClient
  sessionID: string
  signal: AbortSignal
  task: Promise<void>
  resolve: () => void
}

function record(value: unknown): Record<string, unknown> | undefined {
  return isRecord(value) ? value : undefined
}

function text(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined
  const next = value.trim()
  return next || undefined
}

function sourceKey(messageID: string, id: string) {
  return `${messageID}\u0000${id}`
}

function permissionTool(request: PermissionRequest, tools: Map<string, SessionMessageAssistantTool>) {
  if (request.source?.type !== "tool") return request
  const tool = tools.get(sourceKey(request.source.messageID, request.source.id))
  return tool ? { ...request, tool } : request
}

function blockerCategory(event: V2Event): "permission" | "form" | undefined {
  if (event.type === "permission.asked" || event.type === "permission.replied") return "permission"
  if (event.type === "form.created" || event.type === "form.replied" || event.type === "form.cancelled") return "form"
}

function childSessionID(metadata: Record<string, unknown> | undefined) {
  const sessionID = text(metadata?.sessionID)
  if (!sessionID || !sessionID.startsWith("ses")) return undefined
  const status = metadata?.status
  if (status !== "running" && status !== "completed") return undefined
  return { sessionID, running: status === "running" }
}

function tab(child: ChildState): FooterSubagentTab {
  return {
    sessionID: child.sessionID,
    label: child.label,
    description: child.description || child.title || "",
    status: child.status,
    background: child.background ? true : undefined,
    title: child.title,
  }
}

export function createSubagentTracker(input: SubagentTrackerInput): SubagentTracker {
  const children = new Map<string, ChildState>()
  // Live subagent tool calls in the parent, so tool.success metadata
  // can be joined with the call's input metadata.
  const pendingCalls = new Map<string, Record<string, unknown>>()
  // Recently resolved non-family sessions. Retention is bounded so unrelated
  // process activity cannot grow tracker state for the lifetime of the TUI.
  const checked = new Set<string>()
  // Foreign events buffered while a session.get discovery is in flight, so a
  // fast child (including its settled event) is not lost mid-discovery.
  const pendingEvents = new Map<string, V2Event[]>()
  const hydrationEvents = new Map<string, V2Event[]>()
  const hydrationOverflow = new Set<string>()
  const hydrations = new Map<string, Promise<void>>()
  const blockerEvents = new Map<string, V2Event[]>()
  const blockerHydrations = new Map<string, Promise<void>>()
  const blockerRetryTimers = new Map<string, ReturnType<typeof setTimeout>>()
  const blockerRetryAttempts = new Map<string, number>()
  const discoveryJobs = new Map<string, DiscoveryJob>()
  const discoveryQueue: DiscoveryJob[] = []
  let activeDiscoveries = 0
  let selected: string | undefined
  let blockerEpoch = 0
  let closed = false
  const active = (signal = input.signal) => !closed && !input.signal.aborted && !signal.aborted
  const admitChild = (sessionID: string): ChildState | undefined => {
    const existing = children.get(sessionID)
    if (!existing && children.size >= FAMILY_LIST_LIMIT) return
    const child: ChildState = existing ?? {
      sessionID,
      label: FALLBACK_LABEL,
      description: "",
      status: "running",
      background: false,
      lastUpdatedAt: 0,
      frames: [],
      fragments: createFragmentReconciler(),
      tools: new Map(),
      toolSources: new Map(),
      finishedTools: new Set(),
      permissions: [],
      forms: [],
      messageIDs: new Set(),
      prompts: new Map(),
      hydrated: false,
      detailStale: false,
      blockersHydrated: false,
    }
    if (!existing) children.set(sessionID, child)
    // Adopting a child while its session.get discovery is still in flight:
    // drain the buffered events now. They arrived before whatever the caller
    // applies next, so replaying them first preserves bus order, and the
    // resolved discovery can no longer replay stale events (e.g. step.started)
    // after a terminal settled event was applied directly.
    const buffered = pendingEvents.get(sessionID)
    if (buffered) {
      pendingEvents.delete(sessionID)
      for (const event of buffered) reduce(child, event)
    }
    return child
  }

  const touch = (child: ChildState, timestamp?: number) => {
    child.lastUpdatedAt = Math.max(child.lastUpdatedAt, timestamp ?? Date.now())
  }

  const notifyDetail = (child: ChildState) => {
    if (child.sessionID === selected) input.emit()
  }

  const setFrame = (child: ChildState, key: string, commit: StreamCommit) => {
    const index = child.frames.findIndex((item) => item.key === key)
    if (index === -1) {
      child.frames.push({ key, commit })
      if (child.frames.length > CHILD_FRAME_LIMIT) child.frames.splice(0, child.frames.length - CHILD_FRAME_LIMIT)
      return
    }
    child.frames[index] = { key, commit }
  }

  const applyMeta = (child: ChildState, meta: Record<string, unknown> | undefined) => {
    if (!meta) return
    const agent = text(meta.agent)
    if (agent) child.label = Locale.titlecase(agent)
    const description = text(meta.description)
    if (description) child.description = description
    if (meta.background === true) child.background = true
  }

  const userFrame = (child: ChildState, messageID: string, prompt: Pick<SessionMessageUser, "text" | "files">) => {
    if (child.messageIDs.has(messageID)) return false
    child.messageIDs.add(messageID)
    if (prompt.text.trim())
      setFrame(child, `user:${messageID}`, {
        kind: "user",
        source: "system",
        text: prompt.text,
        phase: "start",
        messageID,
      })
    for (const commit of userImageCommits(messageID, prompt.files))
      setFrame(child, sourceKey(messageID, commit.partID), commit)
    return true
  }

  const childTool = (child: ChildState, item: SessionMessageAssistantTool, messageID: string) => {
    const part = normalizeTool(item)
    const key = sourceKey(messageID, part.id)
    const frame = `tool:${key}`
    child.toolSources.set(key, part)
    if (part.state.status === "streaming") {
      child.tools.set(key, { part })
      return
    }
    const current = child.tools.get(key)
    const output = toolOutputText(part.name, toolDisplayContent(part.state))
    if (part.state.status === "running") {
      const ready = part.name !== "websearch" || typeof part.state.metadata.provider === "string"
      const awaitingProvider =
        current?.part.name === "websearch" &&
        current.part.state.status === "running" &&
        typeof current.part.state.metadata.provider !== "string"
      if (ready && (!current || current.part.state.status === "streaming" || awaitingProvider))
        setFrame(child, frame, toolCommit(part, messageID, "start", undefined, input.directory))
      if (output) setFrame(child, frame, toolCommit(part, messageID, "progress", output, input.directory))
      child.tools.set(key, { part })
      return
    }
    child.finishedTools.add(key)
    child.tools.delete(key)
    const partial = part.state.status === "error" && output
    if (partial) setFrame(child, frame, toolCommit(part, messageID, "progress", output, input.directory))
    setFrame(
      child,
      partial ? `${frame}:final` : frame,
      toolCommit(part, messageID, toolFinalPhase(part), undefined, input.directory),
    )
    for (const commit of toolImageCommits(part, messageID)) setFrame(child, sourceKey(messageID, commit.partID), commit)
  }

  const rebuild = (child: ChildState, messages: SessionMessageInfo[]) => {
    child.frames = []
    child.fragments.clear()
    child.finishedTools.clear()
    child.toolSources.clear()
    child.messageIDs.clear()
    for (const message of messages) {
      if (message.type === "user") {
        child.prompts.delete(message.id)
        userFrame(child, message.id, message)
        continue
      }
      if (message.type !== "assistant") continue
      child.messageIDs.add(message.id)
      let textOrdinal = 0
      let reasoningOrdinal = 0
      for (const item of message.content) {
        if (item.type === "text") {
          const fragment = fragmentRef(message.id, "text", textOrdinal++)
          const update = child.fragments.project(fragment, item.text, true)
          setFrame(child, update.key, {
            kind: "assistant",
            source: "assistant",
            text: item.text,
            phase: "progress",
            messageID: message.id,
            partID: fragment.partID,
          })
          continue
        }
        if (item.type === "reasoning") {
          const fragment = fragmentRef(message.id, "reasoning", reasoningOrdinal++)
          const update = child.fragments.project(fragment, item.text, true)
          if (input.thinking)
            setFrame(child, update.key, {
              kind: "reasoning",
              source: "reasoning",
              text: `Thinking: ${item.text}`,
              phase: "progress",
              messageID: message.id,
              partID: fragment.partID,
            })
          continue
        }
        childTool(child, item, message.id)
      }
      if (message.error) {
        setFrame(child, `error:${message.id}`, {
          kind: "error",
          source: "system",
          text: message.error.message,
          phase: "start",
          messageID: message.id,
        })
      }
    }
  }

  const hydrateChild = (sdk: OpenCodeClient, child: ChildState, signal = input.signal): Promise<void> => {
    if (!active(signal)) return Promise.resolve()
    const existing = hydrations.get(child.sessionID)
    if (existing) return existing
    const pendingPrompts = new Map(child.prompts)
    const pendingTools = new Map(child.tools)
    let retry = false
    const task = Promise.all([
      sdk.message.list({ sessionID: child.sessionID, limit: CHILD_MESSAGE_LIMIT, order: "desc" }, { signal }),
      sdk.session.inbox.list({ sessionID: child.sessionID }, { signal }),
    ])
      .then(([response, pending]) => {
        if (!active(signal)) return
        const buffered = hydrationEvents.get(child.sessionID) ?? []
        hydrationEvents.delete(child.sessionID)
        if (hydrationOverflow.delete(child.sessionID)) {
          child.hydrated = false
          retry = true
          notifyDetail(child)
          return
        }
        for (const item of pending) {
          if (item.type === "user") child.prompts.set(item.id, item.payload)
        }
        for (const [id, prompt] of pendingPrompts) {
          if (!child.prompts.has(id)) child.prompts.set(id, prompt)
        }
        rebuild(child, structuredClone(response.data).toReversed() as SessionMessageInfo[])
        child.permissions = child.permissions.map((request) => permissionTool(request, child.toolSources))
        for (const [id, tool] of pendingTools) {
          if (!child.finishedTools.has(id) && !child.tools.has(id)) child.tools.set(id, tool)
        }
        for (const event of buffered) reduce(child, event)
        child.hydrated = true
        child.detailStale = false
        notifyDetail(child)
      })
      .catch(() => {
        hydrationEvents.delete(child.sessionID)
        hydrationOverflow.delete(child.sessionID)
      })
      .finally(() => {
        hydrations.delete(child.sessionID)
        if (retry && active(signal)) queueMicrotask(() => void hydrateChild(sdk, child, signal))
      })
    hydrations.set(child.sessionID, task)
    return task
  }

  const blockerCurrent = (child: ChildState, epoch: number, signal = input.signal) =>
    active(signal) && epoch === blockerEpoch && children.get(child.sessionID) === child

  const resolvePermissionTools = async (
    sdk: OpenCodeClient,
    child: ChildState,
    permissions: PermissionRequest[],
    epoch: number,
    signal = input.signal,
  ) => {
    const messageIDs = [
      ...new Set(
        permissions.flatMap((request) => {
          if (request.source?.type !== "tool") return []
          const key = sourceKey(request.source.messageID, request.source.id)
          return child.toolSources.has(key) ? [] : [request.source.messageID]
        }),
      ),
    ]
    for (let offset = 0; offset < messageIDs.length; offset += FAMILY_DISCOVERY_CONCURRENCY) {
      const batch = messageIDs.slice(offset, offset + FAMILY_DISCOVERY_CONCURRENCY)
      const messages = await Promise.allSettled(
        batch.map((messageID) => sdk.session.message.get({ sessionID: child.sessionID, messageID }, { signal })),
      )
      if (!blockerCurrent(child, epoch, signal)) return permissions
      if (
        messages.some(
          (result, index) =>
            result.status !== "fulfilled" || result.value.type !== "assistant" || result.value.id !== batch[index],
        )
      )
        throw new Error("Permission source message is unavailable")
      for (const [index, result] of messages.entries()) {
        if (result.status !== "fulfilled" || result.value.type !== "assistant" || result.value.id !== batch[index])
          continue
        for (const item of result.value.content) {
          if (item.type !== "tool") continue
          child.toolSources.set(sourceKey(result.value.id, item.id), normalizeTool(item))
        }
      }
    }
    if (
      permissions.some(
        (request) =>
          request.source?.type === "tool" &&
          !child.toolSources.has(sourceKey(request.source.messageID, request.source.id)),
      )
    )
      throw new Error("Permission source tool is unavailable")
    return permissions.map((request) => permissionTool(request, child.toolSources))
  }

  const replayBlockerEvents = (child: ChildState, category: "permission" | "form") => {
    for (const event of blockerEvents.get(child.sessionID) ?? []) {
      if (blockerCategory(event) === category) reduce(child, event)
    }
  }

  function scheduleBlockerRetry(sdk: OpenCodeClient, child: ChildState, epoch: number, signal = input.signal) {
    if (!blockerCurrent(child, epoch, signal) || child.blockersHydrated || blockerRetryTimers.has(child.sessionID))
      return
    const attempt = blockerRetryAttempts.get(child.sessionID) ?? 0
    const delay = Math.min(BLOCKER_RETRY_INITIAL_MS * 2 ** Math.min(attempt, 30), BLOCKER_RETRY_MAX_MS)
    blockerRetryAttempts.set(child.sessionID, attempt + 1)
    const timer = setTimeout(() => {
      if (blockerRetryTimers.get(child.sessionID) !== timer) return
      blockerRetryTimers.delete(child.sessionID)
      if (blockerCurrent(child, epoch, signal) && !child.blockersHydrated)
        void hydrateBlockers(sdk, child, epoch, signal)
    }, delay)
    blockerRetryTimers.set(child.sessionID, timer)
  }

  function hydrateBlockers(
    sdk: OpenCodeClient,
    child: ChildState,
    epoch = blockerEpoch,
    signal = input.signal,
  ): Promise<void> {
    if (!blockerCurrent(child, epoch, signal) || child.blockersHydrated) return Promise.resolve()
    const existing = blockerHydrations.get(child.sessionID)
    if (existing) return existing
    const timer = blockerRetryTimers.get(child.sessionID)
    if (timer) clearTimeout(timer)
    blockerRetryTimers.delete(child.sessionID)
    const tasks = [
      sdk.permission.list({ sessionID: child.sessionID }, { signal }).then(async (permissions) => {
        if (!blockerCurrent(child, epoch, signal)) return
        const resolved = await resolvePermissionTools(sdk, child, permissions, epoch, signal)
        if (!blockerCurrent(child, epoch, signal)) return
        child.permissions = resolved
        replayBlockerEvents(child, "permission")
        input.emit()
      }),
      sdk.session.form.list({ sessionID: child.sessionID }, { signal }).then((forms) => {
        if (!blockerCurrent(child, epoch, signal)) return
        child.forms = forms
        replayBlockerEvents(child, "form")
        input.emit()
      }),
    ]
    const task = Promise.allSettled(tasks)
      .then((results) => {
        if (!blockerCurrent(child, epoch, signal)) return
        blockerEvents.delete(child.sessionID)
        child.blockersHydrated = results.every((result) => result.status === "fulfilled")
        if (child.blockersHydrated) blockerRetryAttempts.delete(child.sessionID)
      })
      .finally(() => {
        blockerHydrations.delete(child.sessionID)
        if (blockerCurrent(child, epoch, signal) && !child.blockersHydrated)
          scheduleBlockerRetry(sdk, child, epoch, signal)
      })
    blockerHydrations.set(child.sessionID, task)
    return task
  }

  const resetBlockerHydration = () => {
    blockerEpoch++
    for (const timer of blockerRetryTimers.values()) clearTimeout(timer)
    blockerRetryTimers.clear()
    blockerRetryAttempts.clear()
    blockerEvents.clear()
    return blockerEpoch
  }

  const rememberChecked = (sessionID: string) => {
    checked.delete(sessionID)
    checked.add(sessionID)
    if (checked.size <= FAMILY_LIST_LIMIT) return
    const oldest = checked.values().next().value
    if (oldest) checked.delete(oldest)
  }

  const runDiscovery = async (job: DiscoveryJob) => {
    try {
      const lineage = []
      const visited = new Set<string>()
      let session = await job.sdk.session.get({ sessionID: job.sessionID }, { signal: job.signal })
      while (lineage.length < FAMILY_LIST_LIMIT && !visited.has(session.id)) {
        if (!active(job.signal)) return
        visited.add(session.id)
        lineage.push(session)
        if (session.parentID === input.sessionID || (session.parentID && children.has(session.parentID))) {
          const buffered = pendingEvents.get(job.sessionID) ?? []
          pendingEvents.delete(job.sessionID)
          for (const item of lineage.toReversed()) {
            const child = admitChild(item.id)
            if (!child) break
            if (item.agent) child.label = Locale.titlecase(item.agent)
            child.title = item.title
            touch(child, item.time.updated)
          }
          const child = children.get(job.sessionID)
          if (!child) return
          const blockers = hydrateBlockers(job.sdk, child, blockerEpoch, job.signal)
          blockerEvents.set(
            job.sessionID,
            buffered.filter((event) => blockerCategory(event) !== undefined),
          )
          for (const event of buffered) reduce(child, event)
          input.emit()
          void blockers
          void hydrateChild(job.sdk, child, job.signal)
          return
        }
        if (!session.parentID || visited.has(session.parentID)) break
        session = await job.sdk.session.get({ sessionID: session.parentID }, { signal: job.signal })
      }
      pendingEvents.delete(job.sessionID)
      rememberChecked(job.sessionID)
    } catch {
      // A later event may retry discovery after a transient lookup failure.
      pendingEvents.delete(job.sessionID)
    }
  }

  const pumpDiscoveries = () => {
    while (activeDiscoveries < FAMILY_DISCOVERY_CONCURRENCY) {
      const job = discoveryQueue.shift()
      if (!job) return
      activeDiscoveries++
      void runDiscovery(job).finally(() => {
        activeDiscoveries--
        if (discoveryJobs.get(job.sessionID) === job) discoveryJobs.delete(job.sessionID)
        job.resolve()
        pumpDiscoveries()
      })
    }
  }

  const discover = (sdk: OpenCodeClient, sessionID: string, signal = input.signal) => {
    if (!active(signal) || children.size >= FAMILY_LIST_LIMIT) return Promise.resolve()
    if (checked.has(sessionID) || children.has(sessionID) || sessionID === input.sessionID) return Promise.resolve()
    const existing = discoveryJobs.get(sessionID)
    if (existing) return existing.task
    let resolve!: () => void
    const task = new Promise<void>((done) => {
      resolve = done
    })
    const job = { sdk, sessionID, signal, task, resolve }
    discoveryJobs.set(sessionID, job)
    pendingEvents.set(sessionID, [])
    discoveryQueue.push(job)
    pumpDiscoveries()
    return task
  }

  const reduce = (child: ChildState, event: V2Event) => {
    if (event.type === "session.inbox.enqueued") {
      if (event.data.item.type === "user") child.prompts.set(event.data.inboxID, event.data.item.payload)
      return
    }
    if (event.type === "session.inbox.delivered") {
      const prompt = child.prompts.get(event.data.inboxID)
      if (prompt === undefined) return
      child.prompts.delete(event.data.inboxID)
      if (userFrame(child, event.data.inboxID, prompt)) {
        touch(child, event.created)
        notifyDetail(child)
      }
      return
    }
    if (event.type === "session.inbox.cancelled") {
      child.prompts.delete(event.data.inboxID)
      return
    }
    if (event.type === "session.step.started") {
      touch(child, event.created)
      if (child.label === FALLBACK_LABEL && event.data.agent) child.label = Locale.titlecase(event.data.agent)
      if (child.status !== "running") child.status = "running"
      input.emit()
      return
    }
    if (event.type === "session.text.started") {
      return
    }
    if (event.type === "session.text.delta") {
      const update = child.fragments.delta(
        fragmentRef(event.data.assistantMessageID, "text", event.data.ordinal),
        event.data.delta,
      )
      if (!update) return
      setFrame(child, update.key, {
        kind: "assistant",
        source: "assistant",
        text: update.text,
        phase: "progress",
        messageID: event.data.assistantMessageID,
        partID: update.partID,
      })
      touch(child, event.created)
      notifyDetail(child)
      return
    }
    if (event.type === "session.text.ended") {
      const update = child.fragments.end(
        fragmentRef(event.data.assistantMessageID, "text", event.data.ordinal),
        event.data.text,
      )
      setFrame(child, update.key, {
        kind: "assistant",
        source: "assistant",
        text: event.data.text,
        phase: "progress",
        messageID: event.data.assistantMessageID,
        partID: update.partID,
      })
      touch(child, event.created)
      notifyDetail(child)
      return
    }
    if (event.type === "session.reasoning.started") {
      return
    }
    if (event.type === "session.reasoning.delta") {
      const update = child.fragments.delta(
        fragmentRef(event.data.assistantMessageID, "reasoning", event.data.ordinal),
        event.data.delta,
      )
      if (!update) return
      if (!input.thinking) return
      setFrame(child, update.key, {
        kind: "reasoning",
        source: "reasoning",
        text: `Thinking: ${update.text}`,
        phase: "progress",
        messageID: event.data.assistantMessageID,
        partID: update.partID,
      })
      notifyDetail(child)
      return
    }
    if (event.type === "session.reasoning.ended") {
      const update = child.fragments.end(
        fragmentRef(event.data.assistantMessageID, "reasoning", event.data.ordinal),
        event.data.text,
      )
      if (!input.thinking) return
      setFrame(child, update.key, {
        kind: "reasoning",
        source: "reasoning",
        text: `Thinking: ${event.data.text}`,
        phase: "progress",
        messageID: event.data.assistantMessageID,
        partID: update.partID,
      })
      notifyDetail(child)
      return
    }
    if (event.type === "session.tool.input.started") {
      if (child.finishedTools.has(sourceKey(event.data.assistantMessageID, event.data.id))) return
      childTool(
        child,
        {
          type: "tool",
          id: event.data.id,
          name: event.data.name,
          state: { status: "streaming", input: "" },
          time: { created: event.created },
        },
        event.data.assistantMessageID,
      )
      return
    }
    if (event.type === "session.tool.input.delta" || event.type === "session.tool.input.ended") {
      const current = child.tools.get(sourceKey(event.data.assistantMessageID, event.data.id))
      if (!current || current.part.state.status !== "streaming") return
      childTool(
        child,
        {
          ...current.part,
          state: {
            status: "streaming",
            input:
              event.type === "session.tool.input.ended" ? event.data.text : current.part.state.input + event.data.delta,
          },
        },
        event.data.assistantMessageID,
      )
      return
    }
    if (event.type === "session.tool.called") {
      const key = sourceKey(event.data.assistantMessageID, event.data.id)
      if (child.finishedTools.has(key)) return
      const current = child.tools.get(key)
      childTool(
        child,
        {
          type: "tool",
          id: event.data.id,
          name: current?.part.name ?? "tool",
          executed: event.data.executed,
          providerState: event.data.state,
          state: { status: "running", input: event.data.input, metadata: {} },
          time: { created: current?.part.time.created ?? event.created, ran: event.created },
        },
        event.data.assistantMessageID,
      )
      touch(child, event.created)
      notifyDetail(child)
      return
    }
    if (event.type === "session.tool.progress") {
      const key = sourceKey(event.data.assistantMessageID, event.data.id)
      if (child.finishedTools.has(key)) return
      const current = child.tools.get(key)
      const part = current?.part
      childTool(
        child,
        {
          type: "tool",
          id: event.data.id,
          name: part?.name ?? "tool",
          executed: part?.executed,
          providerState: part?.providerState,
          state: {
            status: "running",
            input: part && part.state.status !== "streaming" ? part.state.input : {},
            metadata: event.data.metadata,
          },
          time: {
            created: part?.time.created ?? event.created,
            ran: part?.time.ran ?? event.created,
          },
        },
        event.data.assistantMessageID,
      )
      touch(child, event.created)
      notifyDetail(child)
      return
    }
    if (event.type === "session.tool.success" || event.type === "session.tool.failed") {
      const key = sourceKey(event.data.assistantMessageID, event.data.id)
      if (child.finishedTools.has(key)) return
      const current = child.tools.get(key)
      const part = current?.part
      const failed = event.type === "session.tool.failed"
      childTool(
        child,
        {
          type: "tool",
          id: event.data.id,
          name: part?.name ?? "tool",
          executed: event.data.executed,
          providerState: part?.providerState,
          providerResultState: event.data.resultState,
          state: failed
            ? {
                status: "error",
                input: part && part.state.status !== "streaming" ? part.state.input : {},
                metadata: event.data.metadata,
                content: event.data.content,
                error: event.data.error,
              }
            : {
                status: "completed",
                input: part && part.state.status !== "streaming" ? part.state.input : {},
                metadata: event.data.metadata,
                content: event.data.content,
              },
          time: {
            created: part?.time.created ?? event.created,
            ran: part?.time.ran,
            completed: event.created,
          },
        },
        event.data.assistantMessageID,
      )
      touch(child, event.created)
      notifyDetail(child)
      return
    }
    if (event.type === "permission.asked") {
      if (!child.permissions.some((item) => item.id === event.data.id))
        child.permissions.push(permissionTool(event.data, child.toolSources))
      input.emit()
      return
    }
    if (event.type === "permission.replied") {
      child.permissions = child.permissions.filter((item) => item.id !== event.data.requestID)
      input.emit()
      return
    }
    if (event.type === "form.created") {
      if (!child.forms.some((item) => item.id === event.data.form.id)) child.forms.push(event.data.form)
      input.emit()
      return
    }
    if (event.type === "form.replied" || event.type === "form.cancelled") {
      child.forms = child.forms.filter((item) => item.id !== event.data.id)
      input.emit()
      return
    }
    if (event.type === "session.step.ended") return
    if (event.type === "session.step.failed") {
      setFrame(child, `error:${event.data.assistantMessageID}`, {
        kind: "error",
        source: "system",
        text: event.data.error.message,
        phase: "start",
        messageID: event.data.assistantMessageID,
      })
      touch(child, event.created)
      notifyDetail(child)
      return
    }
    if (event.type === "session.execution.started") {
      child.status = "running"
      touch(child, event.created)
      input.emit()
      return
    }
    if (
      event.type === "session.execution.succeeded" ||
      event.type === "session.execution.failed" ||
      event.type === "session.execution.interrupted"
    ) {
      child.status =
        event.type === "session.execution.succeeded"
          ? "completed"
          : event.type === "session.execution.interrupted"
            ? "cancelled"
            : "error"
      touch(child, event.created)
      input.emit()
    }
  }

  const mainTool = (item: SessionMessageAssistantTool, active?: Record<string, unknown>) => {
    const tool = normalizeTool(item)
    if (tool.name !== "subagent" || tool.state.status === "streaming") return
    const found = childSessionID(record(tool.state.metadata))
    if (!found) return
    const child = admitChild(found.sessionID)
    if (!child) return
    applyMeta(child, record(tool.state.input))
    if (tool.state.status === "completed" && found.running) child.background = true
    if (child.status === "running") {
      const running = found.running && (!active || found.sessionID in active)
      child.status = running ? "running" : "completed"
    }
    touch(child, tool.time.completed ?? tool.time.created)
  }

  const settleHydrations = async () => {
    while (true) {
      await Promise.resolve()
      const pending = [...discoveryJobs.values()]
        .map((job) => job.task)
        .concat([...hydrations.values(), ...blockerHydrations.values()])
      if (pending.length === 0) return
      await Promise.allSettled(pending)
    }
  }

  return {
    main(sdk, event, signal = input.signal) {
      if (!active(signal)) return
      if (event.type === "session.tool.input.started") {
        if (canonicalToolName(event.data.name) === "subagent")
          pendingCalls.set(sourceKey(event.data.assistantMessageID, event.data.id), {})
        return
      }
      if (event.type === "session.tool.called") {
        const key = sourceKey(event.data.assistantMessageID, event.data.id)
        if (pendingCalls.has(key)) pendingCalls.set(key, event.data.input)
        return
      }
      if (
        event.type !== "session.tool.progress" &&
        event.type !== "session.tool.success" &&
        event.type !== "session.tool.failed"
      )
        return
      const key = sourceKey(event.data.assistantMessageID, event.data.id)
      const pending = pendingCalls.get(key)
      if (event.type !== "session.tool.progress") pendingCalls.delete(key)
      const found = childSessionID(record(event.data.metadata))
      if (!found) return
      const child = admitChild(found.sessionID)
      if (!child) return
      applyMeta(child, pending)
      if (event.type === "session.tool.success" && found.running) {
        child.background = true
        child.status = "running"
      }
      if (event.type === "session.tool.success" && !found.running && child.status === "running")
        child.status = "completed"
      touch(child, event.created)
      input.emit()
      if (!child.blockersHydrated) void hydrateBlockers(sdk, child, blockerEpoch, signal)
      if (!child.hydrated) void hydrateChild(sdk, child, signal)
    },
    foreign(sdk, sessionID, event, signal = input.signal) {
      if (!active(signal)) return
      const child = children.get(sessionID)
      if (child) {
        if (blockerHydrations.has(sessionID) && blockerCategory(event)) {
          const buffered = blockerEvents.get(sessionID) ?? []
          if (buffered.length < CHILD_EVENT_BUFFER_LIMIT) buffered.push(event)
          blockerEvents.set(sessionID, buffered)
        }
        if (hydrations.has(sessionID)) {
          const buffered = hydrationEvents.get(sessionID) ?? []
          if (buffered.length < CHILD_EVENT_BUFFER_LIMIT) buffered.push(event)
          else hydrationOverflow.add(sessionID)
          hydrationEvents.set(sessionID, buffered)
        }
        reduce(child, event)
        return
      }
      void discover(sdk, sessionID, signal)
      const buffered = pendingEvents.get(sessionID)
      if (buffered && buffered.length < CHILD_EVENT_BUFFER_LIMIT) buffered.push(event)
    },
    async hydrate(next) {
      const signal = next.signal ?? input.signal
      if (!active(signal)) return
      const blockerHydrationEpoch = resetBlockerHydration()
      await settleHydrations()
      if (!active(signal)) return
      if (next.reconnect) {
        for (const child of children.values()) {
          child.hydrated = false
          child.detailStale = true
        }
      }
      for (const message of next.messages) {
        if (message.type !== "assistant") continue
        for (const item of message.content) {
          if (item.type === "tool") mainTool(item, next.active)
        }
      }
      // Family index: adopt children directly from the current session list so
      // historical subagents beyond the projected message window still get tabs.
      const queue = [input.sessionID]
      const visited = new Set(queue)
      while (queue.length > 0 && children.size < FAMILY_LIST_LIMIT) {
        const owner = queue.shift()
        if (!owner) continue
        const family = await next.sdk.session
          .list({ parentID: owner, limit: FAMILY_LIST_LIMIT - children.size, order: "desc" }, { signal })
          .then((response) => response.data)
          .catch(() => [])
        if (!active(signal)) return
        for (const session of family) {
          if (visited.has(session.id) || children.size >= FAMILY_LIST_LIMIT) continue
          visited.add(session.id)
          const child = admitChild(session.id)
          if (!child) break
          if (session.agent && child.label === FALLBACK_LABEL) child.label = Locale.titlecase(session.agent)
          if (!child.title) child.title = session.title
          touch(child, session.time.updated)
          queue.push(session.id)
        }
      }
      const activeSessions = Object.keys(next.active)
      for (
        let offset = 0;
        offset < activeSessions.length && children.size < FAMILY_LIST_LIMIT;
        offset += FAMILY_DISCOVERY_CONCURRENCY
      )
        await Promise.all(
          activeSessions
            .slice(offset, offset + FAMILY_DISCOVERY_CONCURRENCY)
            .map((sessionID) => discover(next.sdk, sessionID, signal)),
        )
      if (!active(signal)) return
      for (const child of children.values()) {
        // Reconnect can miss a child's settled event; the active map is the
        // authoritative live signal for still-running children.
        if (child.status === "running" && !(child.sessionID in next.active)) child.status = "completed"
        child.blockersHydrated = false
      }
      const descendants = [...children.values()]
      for (let offset = 0; offset < descendants.length; offset += FAMILY_DISCOVERY_CONCURRENCY)
        await Promise.all(
          descendants
            .slice(offset, offset + FAMILY_DISCOVERY_CONCURRENCY)
            .map((child) => hydrateBlockers(next.sdk, child, blockerHydrationEpoch, signal)),
        )
      if (!active(signal)) return
      const current = selected ? children.get(selected) : undefined
      if (current) await hydrateChild(next.sdk, current, signal)
      if (!active(signal)) return
      if (children.size > 0) input.emit()
    },
    ready: settleHydrations,
    select(sdk, sessionID) {
      selected = sessionID
      const child = sessionID ? children.get(sessionID) : undefined
      if (child && !child.hydrated) void hydrateChild(sdk, child)
      input.emit()
    },
    snapshot() {
      const tabs = [...children.values()]
        .toSorted((a, b) => {
          const active = Number(b.status === "running") - Number(a.status === "running")
          if (active !== 0) return active
          return b.lastUpdatedAt - a.lastUpdatedAt
        })
        .map(tab)
      const child = selected ? children.get(selected) : undefined
      const details: Record<string, FooterSubagentDetail> =
        child && !child.detailStale ? { [child.sessionID]: { commits: child.frames.map((item) => item.commit) } } : {}
      return {
        tabs,
        details,
        permissions: [...children.values()].flatMap((item) => item.permissions),
        forms: [...children.values()].flatMap((item) => item.forms),
      }
    },
    settleForm(sessionID, formID) {
      const child = children.get(sessionID)
      if (!child) return
      child.forms = child.forms.filter((item) => item.id !== formID)
      input.emit()
    },
    close() {
      closed = true
      resetBlockerHydration()
      for (const job of discoveryQueue.splice(0)) {
        if (discoveryJobs.get(job.sessionID) === job) discoveryJobs.delete(job.sessionID)
        job.resolve()
      }
      hydrationEvents.clear()
      hydrationOverflow.clear()
      pendingEvents.clear()
    },
  }
}

