import { ansiToRgba } from "../theme/color"
import { discoverThemes } from "../theme/discovery"
import { generateSystem, terminalMode } from "../theme/system"
import { configDirectories } from "../util/config-directories"
import { dedupeWith } from "effect/Array"
import type { EntryKind, RunTuiConfig } from "./types"

type Tone = {
  body: ColorInput
  start?: ColorInput
}

export type RunEntryTheme = Record<EntryKind, Tone>

export type RunSplashTheme = {
  left: ColorInput
  right: ColorInput
  leftShadow: ColorInput
}

export type RunFooterTheme = {
  actionSecondaryText: ColorInput
  actionFocusedBg: ColorInput
  actionFocusedText: ColorInput
  formfieldText: ColorInput
  formfieldFocusedBg: ColorInput
  formfieldFocusedText: ColorInput
  selection: ColorInput
  running: ColorInput
  question: ColorInput
  permission: ColorInput
  success: ColorInput
  link: ColorInput
  categorical: ColorInput[]
  warning: ColorInput
  error: ColorInput
  muted: ColorInput
  text: ColorInput
  shade: ColorInput
  surface: ColorInput
  pane: ColorInput
  border: ColorInput
  line: ColorInput
}

export type RunBlockTheme = {
  text: ColorInput
  muted: ColorInput
  syntax?: SyntaxStyle
  diffRemoved: ColorInput
  diffAddedBg: ColorInput
  diffRemovedBg: ColorInput
  diffContextBg: ColorInput
  diffHighlightAdded: ColorInput
  diffHighlightRemoved: ColorInput
  diffLineNumber: ColorInput
  diffAddedLineNumberBg: ColorInput
  diffRemovedLineNumberBg: ColorInput
}

export type RunTheme = {
  background: ColorInput
  footer: RunFooterTheme
  entry: RunEntryTheme
  splash: RunSplashTheme
  block: RunBlockTheme
}

export const transparent = RGBA.fromValues(0, 0, 0, 0)

const ansiPalette = Array.from({ length: 256 }, (_, index) => RGBA.fromIndex(index, ansiToRgba(index)))
const palettes = new WeakMap<CliRenderer, TerminalColors>()

function srgbToLinear(value: number): number {
  return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4
}

function oklab(color: RGBA) {
  const r = srgbToLinear(color.r)
  const g = srgbToLinear(color.g)
  const b = srgbToLinear(color.b)
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b)
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b)
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b)
  return {
    l: 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s,
    a: 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s,
    b: 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s,
  }
}

function nearestIndexed(indexed: RGBA[], color: RGBA): RGBA {
  const target = oklab(color)
  const hit = indexed.reduce(
    (best, item) => {
      const sample = oklab(item)
      const dl = sample.l - target.l
      const da = sample.a - target.a
      const db = sample.b - target.b
      const dist = dl * dl * 2 + da * da + db * db
      return dist >= best.dist ? best : { dist, item }
    },
    { dist: Number.POSITIVE_INFINITY, item: indexed[0]! },
  )
  return RGBA.clone(hit.item)
}

function map(
  theme: ResolvedTheme,
  indexed: RGBA[],
  syntax?: SyntaxStyle,
  system = false,
): RunTheme {
  // V1 system migration serializes colors; restore terminal defaults before quantizing scrollback.
  const exact = (color: RGBA) => {
    if (system && color.equals(theme.text.base)) return RGBA.defaultForeground(color)
    if (system && color.equals(theme.background.base)) return RGBA.defaultBackground(color)
    return color
  }
  const scrollback = (color: RGBA) => {
    const value = exact(color)
    return value.a === 0 || value.intent !== "rgb" ? value : nearestIndexed(indexed, value)
  }
  syntax?.getAllStyles().forEach((style, name) => {
    syntax.registerStyle(name, {
      ...style,
      fg: style.fg && scrollback(style.fg),
      bg: style.bg && scrollback(style.bg),
    })
  })

  return {
    background: RGBA.defaultBackground(theme.background.base),
    footer: {
      actionSecondaryText: exact(theme.text.action.secondary.base),
      actionFocusedBg: exact(theme.background.action.primary.focused),
      actionFocusedText: exact(theme.text.action.primary.focused),
      formfieldText: exact(theme.text.formfield.base),
      formfieldFocusedBg: exact(theme.background.formfield.focused),
      formfieldFocusedText: exact(theme.text.formfield.focused),
      selection: exact(theme.text.formfield.selected),
      running: exact(theme.hue.interactive[200]),
      question: exact(theme.hue.accent[200]),
      permission: exact(theme.hue.accent[200]),
      success: exact(theme.text.feedback.success.base),
      link: exact(theme.markdown.link),
      categorical: dedupeWith(
        theme.categorical.map((scale) => exact(scale[200])),
        (a, b) => a.equals(b),
      ),
      warning: exact(theme.text.feedback.warning.base),
      error: exact(theme.text.feedback.error.base),
      muted: exact(theme.text.muted),
      text: exact(theme.text.base),
      shade: exact(theme.background.raised.base),
      surface: exact(theme.background.raised.base),
      pane: exact(theme.background.raised.high),
      border: exact(theme.border.base),
      line: exact(theme.background.raised.high),
    },
    entry: {
      system: { body: scrollback(theme.text.muted) },
      user: { body: scrollback(theme.text.base) },
      assistant: { body: scrollback(theme.markdown.text) },
      reasoning: { body: scrollback(theme.text.muted) },
      tool: { body: scrollback(theme.text.muted), start: scrollback(theme.text.muted) },
      error: { body: scrollback(theme.text.feedback.error.base) },
    },
    splash: {
      left: nearestIndexed(indexed, theme.text.muted),
      right: nearestIndexed(indexed, theme.text.base),
      leftShadow: nearestIndexed(indexed, theme.background.raised.base),
    },
    block: {
      text: scrollback(theme.text.base),
      muted: scrollback(theme.text.muted),
      syntax,
      diffRemoved: scrollback(theme.diff.text.removed),
      diffAddedBg: scrollback(theme.diff.background.added),
      diffRemovedBg: scrollback(theme.diff.background.removed),
      diffContextBg: scrollback(theme.diff.background.context),
      diffHighlightAdded: scrollback(theme.diff.highlight.added),
      diffHighlightRemoved: scrollback(theme.diff.highlight.removed),
      diffLineNumber: scrollback(theme.diff.lineNumber.text),
      diffAddedLineNumberBg: scrollback(theme.diff.lineNumber.background.added),
      diffRemovedLineNumberBg: scrollback(theme.diff.lineNumber.background.removed),
    },
  }
}

export const RUN_THEME_FALLBACK = map(
  resolveThemeDocument(parseTheme(getOpenCodeTheme()), "dark"),
  ansiPalette,
)
export const RUN_THEME_FALLBACK_LIGHT = map(
  resolveThemeDocument(parseTheme(getOpenCodeTheme()), "light"),
  ansiPalette,
)

function monoTheme(mode: "dark" | "light"): RunTheme {
  const foreground = RGBA.defaultForeground(mode === "light" ? "#000000" : "#ffffff")
  const background = RGBA.defaultBackground(mode === "light" ? "#ffffff" : "#000000")
  return {
    background,
    footer: {
      actionSecondaryText: foreground,
      actionFocusedBg: background,
      actionFocusedText: foreground,
      formfieldText: foreground,
      formfieldFocusedBg: background,
      formfieldFocusedText: foreground,
      selection: foreground,
      running: foreground,
      question: foreground,
      permission: foreground,
      success: foreground,
      link: foreground,
      categorical: [foreground],
      warning: foreground,
      error: foreground,
      muted: foreground,
      text: foreground,
      shade: background,
      surface: background,
      pane: background,
      border: foreground,
      line: background,
    },
    entry: {
      system: { body: foreground },
      user: { body: foreground },
      assistant: { body: foreground },
      reasoning: { body: foreground },
      tool: { body: foreground },
      error: { body: foreground },
    },
    splash: { left: foreground, right: foreground, leftShadow: background },
    block: {
      text: foreground,
      muted: foreground,
      diffRemoved: foreground,
      diffAddedBg: background,
      diffRemovedBg: background,
      diffContextBg: background,
      diffHighlightAdded: foreground,
      diffHighlightRemoved: foreground,
      diffLineNumber: foreground,
      diffAddedLineNumberBg: background,
      diffRemovedLineNumberBg: background,
    },
  }
}

export const RUN_THEME_MONO = monoTheme("dark")
const RUN_THEME_MONO_LIGHT = monoTheme("light")

export async function resolveRunTheme(
  renderer: CliRenderer,
  config?: RunTuiConfig["theme"],
  mono = false,
): Promise<RunTheme> {
  if (mono) {
    const mode = renderer.themeMode ?? (await renderer.waitForThemeMode(300)) ?? config?.mode
    return mode === "light" ? RUN_THEME_MONO_LIGHT : RUN_THEME_MONO
  }

  const detected = await renderer.getPalette({ size: 256 }).catch(() => undefined)
  // A transient OSC timeout must not remap immutable scrollback against an unrelated ANSI palette.
  const colors =
    (detected?.defaultBackground ?? detected?.palette[0]) && (detected?.defaultForeground ?? detected?.palette[7])
      ? detected
      : palettes.get(renderer)
  if (colors) palettes.set(renderer, colors)
  // Mini stays transparent: fresh OSC 11 wins, but cached colors must not override a new renderer mode.
  const mode =
    (detected && terminalMode(detected)) ??
    renderer.themeMode ??
    (colors && terminalMode(colors)) ??
    (config?.mode === "light" ? "light" : "dark")
  const name = config?.name ?? "opencode"
  if (name === "system" && !colors) {
    return mode === "light" ? RUN_THEME_FALLBACK_LIGHT : RUN_THEME_FALLBACK
  }

  const resolved = await themeSource(name, colors, mode)
    .then((source) => {
      const document = parseTheme(source, name)
      // Mini keeps the terminal background, so the opposite theme mode is not a safe fallback.
      if (themeModes(document).includes(mode)) return resolveThemeDocument(document, mode)
    })
    .catch(() => undefined)
  const theme = resolved ?? resolveThemeDocument(parseTheme(getOpenCodeTheme()), mode)
  const indexed = colors
    ? ansiPalette.map((color, index) => (colors.palette[index] ? RGBA.fromIndex(index, colors.palette[index]!) : color))
    : ansiPalette
  return {
    ...map(theme, indexed, generateSyntax(theme), name === "system" && resolved !== undefined),
    background: RGBA.defaultBackground(colors?.defaultBackground ?? theme.background.base),
  }
}

async function themeSource(
  name: string,
  colors: TerminalColors | undefined,
  mode: "dark" | "light",
): Promise<ThemeDocumentSource> {
  if (name === "system" && colors) return generateSystem(colors, mode)
  const { Global } = await import("@opencode/util/global")
  const custom = await discoverThemes(
    configDirectories(process.env.OPENCODE_CONFIG_DIR ?? Global.Path.config, process.cwd()),
  )
  const source = custom[name] ?? allThemes()[name] ?? getOpenCodeTheme()
  return isThemeSource(source) ? source : getOpenCodeTheme()
}

// Per-tool display rules shared across `opencode run` output paths.
//
// Each known tool (shell, edit, write, subagent, etc.) has a ToolRule that controls
// four display hooks:
//
//   view       → visibility policy for progress/final scrollback entries and
//                whether completed finals can render as structured snapshots
//   run        → inline summary for the non-interactive `run` command output
//   scroll     → text formatting for start/progress/final scrollback entries
//   snap       → structured snapshot (code block, diff, task card) for rich
//                scrollback entries
//
// Tools not in TOOL_RULES get fallback formatting.
import os from "os"
import path from "path"
import stripAnsi from "strip-ansi"
import type { SessionMessageAssistantTool } from "@opencode/client/promise"
import { LANGUAGE_EXTENSIONS } from "../util/filetype"
import { Locale } from "../util/locale"
import {
  canonicalToolName,
  finiteNumber,
  primitiveInputSummary,
  toolDisplayContent,
  toolDisplayMetadata,
  webSearchProviderLabel,
} from "../util/tool-display"
import { formatPath } from "../util/path-format"
import { isRecord } from "../util/record"
import type { RunEntryBody, StreamCommit, ToolSnapshot } from "./types"

export { canonicalToolName } from "../util/tool-display"

type ToolView = {
  output: boolean
  final: boolean
  snap?: "code" | "diff" | "structured"
}

type ToolPhase = "start" | "progress" | "final"

type ToolDict = Record<string, unknown>

type PatchFile = {
  status?: string
  file?: string
  from?: string
  patch?: string
  deletions?: number
}

type ToolInput = ToolDict & {
  id?: string
  path?: string
  pattern?: string
  url?: string
  query?: string
  agent?: string
  description?: string
  name?: string
  operation?: string
  line?: number
  character?: number
  content?: string
  command?: string
  workdir?: string
  questions?: Array<{ question?: string }>
  diff?: string
}

type ToolMetadata = ToolDict & {
  name?: string
  count?: number
  matches?: number
  diff?: string
  provider?: unknown
  files?: PatchFile[]
  answers?: string[][]
  exit?: number
}

type ToolFrame = {
  directory?: string
  raw: string
  name: string
  input: ToolDict
  meta: ToolDict
  state: ToolDict
  status: string
  error: string
  output: string
  time: {
    start?: number
    end?: number
  }
}

type ToolInline = {
  icon: string
  title: string
  description?: string
  mode?: "inline" | "block"
  body?: string
}

type ToolProps = {
  input: ToolInput
  metadata: ToolMetadata
  frame: ToolFrame
}

type ToolName =
  | "invalid"
  | "shell"
  | "write"
  | "edit"
  | "patch"
  | "batch"
  | "subagent"
  | "question"
  | "read"
  | "glob"
  | "grep"
  | "list"
  | "lsp"
  | "webfetch"
  | "websearch"
  | "skill"

type ToolRule = {
  view: ToolView
  run: (props: ToolProps) => ToolInline
  scroll?: Partial<Record<ToolPhase, (props: ToolProps) => string>>
  snap?: (props: ToolProps) => ToolSnapshot | undefined
}

type ToolRegistry = Record<ToolName, ToolRule>

type AnyToolRule = ToolRule

function dict(v: unknown): ToolDict {
  return isRecord(v) ? { ...v } : {}
}

function props(frame: ToolFrame): ToolProps {
  return {
    input: frame.input,
    metadata: frame.meta,
    frame,
  }
}

function text(v: unknown): string {
  return typeof v === "string" ? v : ""
}

export function toolOutputText(name: string, content: ReadonlyArray<{ type: string; text?: string }> | undefined) {
  if (!content) return ""
  // V2 shell content appends model-only status after the user-visible command output.
  if (canonicalToolName(name) === "shell") return content.find((item) => item.type === "text")?.text ?? ""
  const joined = content.flatMap((item) => (item.type === "text" && item.text ? [item.text] : [])).join("\n")
  if (canonicalToolName(name) === "read") return readDisplayText(joined) ?? joined
  return joined
}

/** Read's model content is a JSON page envelope; unwrap the human-facing text. */
export function readDisplayText(text: string): string | undefined {
  if (!text.startsWith("{")) return undefined
  const parsed = (() => {
    try {
      return JSON.parse(text) as unknown
    } catch {
      return undefined
    }
  })()
  const envelope = dict(parsed)
  if (typeof envelope.content === "string" && (envelope.type === "text-page" || envelope.encoding === "utf8"))
    return envelope.content
  if (!Array.isArray(envelope.entries)) return undefined
  return envelope.entries
    .flatMap((entry): string[] => {
      if (typeof entry === "string") return [entry]
      const path = dict(entry).path
      return typeof path === "string" ? [path] : []
    })
    .join("\n")
}

function normalizeInput(name: string, value: unknown) {
  const input = dict(value)
  const path = typeof input.path === "string" ? input.path : text(input.filePath)
  const agent = typeof input.agent === "string" ? input.agent : text(input.subagent_type)
  return {
    ...input,
    ...(["read", "write", "edit", "lsp"].includes(name) && path ? { path } : {}),
    ...(name === "subagent" && agent ? { agent } : {}),
  }
}

function normalizeFile(value: unknown): PatchFile | undefined {
  const file = dict(value)
  const name = text(file.file) || text(file.relativePath) || text(file.filePath)
  if (!name) return
  const legacy = text(file.type)
  const status =
    text(file.status) ||
    (legacy === "add"
      ? "added"
      : legacy === "delete"
        ? "deleted"
        : legacy === "update"
          ? "modified"
          : legacy === "move"
            ? "moved"
            : legacy)
  const patch = typeof file.patch === "string" ? file.patch : undefined
  const deletions = finiteNumber(file.deletions)
  return {
    ...file,
    file: name,
    ...(status === "moved" && text(file.filePath) ? { from: text(file.filePath) } : {}),
    ...(status ? { status } : {}),
    ...(patch === undefined ? {} : { patch }),
    ...(deletions === undefined ? {} : { deletions }),
  }
}

function normalizeMetadata(name: string, value: unknown) {
  const metadata = dict(value)
  const files = list(metadata.files).flatMap((item) => {
    const file = normalizeFile(item)
    return file ? [file] : []
  })
  const sessionID = text(metadata.sessionID) || text(metadata.sessionId)
  return {
    ...metadata,
    ...(["edit", "patch"].includes(name) && Array.isArray(metadata.files) ? { files } : {}),
    ...(name === "subagent" && sessionID ? { sessionID } : {}),
  }
}

export function normalizeTool(tool: SessionMessageAssistantTool): SessionMessageAssistantTool {
  const name = canonicalToolName(tool.name)
  if (tool.state.status === "streaming") return { ...tool, name }
  return {
    ...tool,
    name,
    state: {
      ...tool.state,
      input: normalizeInput(name, tool.state.input),
      metadata: normalizeMetadata(name, toolDisplayMetadata(tool.state)),
    },
  } as SessionMessageAssistantTool
}

function list<T>(v: unknown): T[] {
  if (!Array.isArray(v)) {
    return []
  }

  return v
}

function span(frame: ToolFrame): string {
  const start = frame.time.start
  const end = frame.time.end
  if (start === undefined || end === undefined || end <= start) {
    return ""
  }

  return Locale.duration(end - start)
}

function fail(ctx: ToolFrame): string {
  const error = toolError(ctx)
  if (error) {
    return `✖ ${ctx.name} failed: ${error}`
  }

  return `✖ ${ctx.name} failed`
}

function toolError(ctx: ToolFrame): string {
  if (ctx.error) {
    return ctx.error
  }

  const state = text(ctx.state.error).trim()
  if (state) {
    return state
  }

  return ctx.raw.trim()
}

function fallbackStart(ctx: ToolFrame): string {
  const extra = primitiveInputSummary(ctx.input)
  if (!extra) {
    return `⚙ ${ctx.name}`
  }

  return `⚙ ${ctx.name} ${extra}`
}

function fallbackFinal(ctx: ToolFrame): string {
  if (ctx.status === "error") {
    return fail(ctx)
  }

  if (ctx.status && ctx.status !== "completed") {
    return ctx.raw.trim()
  }

  const time = span(ctx)
  if (!time) {
    return `${ctx.name} completed`
  }

  return `${ctx.name} completed · ${time}`
}

export function toolPath(input?: string, opts: { home?: boolean; directory?: string } = {}): string {
  return formatPath(input, {
    base: opts.directory ?? process.cwd(),
    home: opts.home ? os.homedir() : undefined,
    forwardSlashes: true,
  })
}

function displayPath(p: ToolProps, input?: string, opts: { home?: boolean } = {}) {
  return toolPath(input, { ...opts, directory: p.frame.directory })
}

function fallbackInline(ctx: ToolFrame): ToolInline {
  const title = Object.keys(ctx.input).length > 0 ? JSON.stringify(ctx.input) : "Unknown"

  return {
    icon: "⚙",
    title: `${ctx.name} ${title}`,
  }
}

function count(n: number, label: string): string {
  return `${n} ${label}${n === 1 ? "" : "es"}`
}

function runGlob(p: ToolProps): ToolInline {
  const root = p.input.path ?? ""
  const title = `Glob "${p.input.pattern ?? ""}"`
  const suffix = root ? `in ${displayPath(p, root)}` : ""
  const matches = p.metadata.count
  const description = matches === undefined ? suffix : `${suffix}${suffix ? " · " : ""}${count(matches, "match")}`
  return {
    icon: "✱",
    title,
    ...(description && { description }),
  }
}

function runGrep(p: ToolProps): ToolInline {
  const root = p.input.path ?? ""
  const title = `Grep "${p.input.pattern ?? ""}"`
  const suffix = root ? `in ${displayPath(p, root)}` : ""
  const matches = p.metadata.matches
  const description = matches === undefined ? suffix : `${suffix}${suffix ? " · " : ""}${count(matches, "match")}`
  return {
    icon: "✱",
    title,
    ...(description && { description }),
  }
}

function runList(p: ToolProps): ToolInline {
  const dir = text(dict(p.input).path)
  return {
    icon: "→",
    title: dir ? `List ${displayPath(p, dir)}` : "List",
  }
}

function runRead(p: ToolProps): ToolInline {
  const file = displayPath(p, p.input.path)
  const description = primitiveInputSummary(p.frame.input, ["path"]) || undefined
  return {
    icon: "→",
    title: `Read ${file}`,
    ...(description && { description }),
  }
}

function runWrite(p: ToolProps): ToolInline {
  return {
    icon: "←",
    title: `Write ${displayPath(p, p.input.path)}`,
    mode: "block",
    body: p.frame.status === "completed" ? p.frame.output : undefined,
  }
}

function runWebfetch(p: ToolProps): ToolInline {
  const url = p.input.url ?? ""
  return {
    icon: "%",
    title: url ? `WebFetch ${url}` : "WebFetch",
  }
}

function runEdit(p: ToolProps): ToolInline {
  const file = list<PatchFile>(p.metadata.files)[0]
  return {
    icon: "←",
    title: `Edit ${displayPath(p, p.input.path)}`,
    mode: "block",
    body: file?.patch ?? p.metadata.diff,
  }
}

