} as const satisfies ToolRegistry

function key(name: string): name is ToolName {
  return Object.prototype.hasOwnProperty.call(TOOL_RULES, name)
}

function rule(name?: string): AnyToolRule | undefined {
  if (!name || !key(name)) {
    return undefined
  }

  return TOOL_RULES[name]
}

function frame(part: SessionMessageAssistantTool, directory?: string): ToolFrame {
  const tool = normalizeTool(part)
  if (tool.state.status === "streaming")
    return {
      directory,
      raw: tool.state.input,
      name: tool.name,
      input: {},
      meta: {},
      state: dict(tool.state),
      status: tool.state.status,
      error: "",
      output: "",
      time: { start: tool.time.created },
    }
  const output = toolOutputText(tool.name, toolDisplayContent(tool.state))
  return {
    directory,
    raw: output,
    name: tool.name,
    input: normalizeInput(tool.name, tool.state.input),
    meta: normalizeMetadata(tool.name, tool.state.metadata),
    state: dict(tool.state),
    status: tool.state.status,
    error: tool.state.status === "error" ? tool.state.error.message : "",
    output,
    time: {
      start: tool.time.ran ?? tool.time.created,
      end: tool.time.completed,
    },
  }
}

function toolFrame(commit: StreamCommit, raw: string): ToolFrame {
  const current = commit.part ? frame(commit.part, commit.directory) : undefined
  return {
    directory: commit.directory,
    raw,
    name: canonicalToolName(commit.tool || current?.name || "tool"),
    input: current?.input ?? {},
    meta: current?.meta ?? {},
    state: current?.state ?? {},
    status: commit.toolState ?? current?.status ?? "",
    error: (commit.toolError ?? current?.error ?? "").trim(),
    output: current?.output ?? raw,
    time: current?.time ?? {},
  }
}

function runShell(p: ToolProps): ToolInline {
  return {
    icon: "$",
    title: p.input.command || "",
    mode: "block",
    body: p.frame.status === "completed" ? p.frame.output.trim() : undefined,
  }
}

export function toolView(name?: string): ToolView {
  return (
    rule(name ? canonicalToolName(name) : undefined)?.view ?? {
      output: true,
      final: true,
    }
  )
}

export function toolStructuredFinal(commit: StreamCommit): boolean {
  const state = commit.toolState ?? commit.part?.state.status
  return (
    commit.kind === "tool" &&
    commit.phase === "final" &&
    state === "completed" &&
    Boolean(toolView(commit.tool ?? commit.part?.name).snap)
  )
}

export function toolInlineInfo(part: SessionMessageAssistantTool, directory?: string): ToolInline {
  const ctx = frame(part, directory)
  const draw = rule(ctx.name)?.run
  try {
    if (draw) {
      return draw(props(ctx))
    }
  } catch {
    return fallbackInline(ctx)
  }

  return fallbackInline(ctx)
}

export function toolScroll(phase: ToolPhase, ctx: ToolFrame): string {
  const draw = rule(ctx.name)?.scroll?.[phase]
  try {
    if (draw) {
      return draw(props(ctx))
    }
  } catch {
    if (phase === "start") {
      return fallbackStart(ctx)
    }
    if (phase === "progress") {
      return ctx.raw
    }
    return fallbackFinal(ctx)
  }

  if (phase === "start") {
    return fallbackStart(ctx)
  }

  if (phase === "progress") {
    return ctx.raw
  }

  return fallbackFinal(ctx)
}

function toolSnapshot(commit: StreamCommit, raw: string): ToolSnapshot | undefined {
  const ctx = toolFrame(commit, raw)
  const draw = rule(ctx.name)?.snap
  if (!draw) {
    return undefined
  }

  try {
    return draw(props(ctx))
  } catch {
    return undefined
  }
}

function textBody(content: string): RunEntryBody | undefined {
  if (!content) {
    return undefined
  }

  return {
    type: "text",
    content,
  }
}

function markdownBody(content: string): RunEntryBody | undefined {
  if (!content) {
    return undefined
  }

  return {
    type: "markdown",
    content,
  }
}

function structuredBody(commit: StreamCommit, raw: string): RunEntryBody | undefined {
  const snap = toolSnapshot(commit, raw)
  if (!snap) {
    return undefined
  }

  return {
    type: "structured",
    snapshot: snap,
  }
}

const STRUCTURED_FALLBACK_LENGTH = 4_096

function structuredFallback(value: ToolDict): RunEntryBody | undefined {
  if (Object.keys(value).length === 0) return
  const content = JSON.stringify(value, null, 2)
  if (!content) return
  const suffix = "\n… [truncated]"
  return {
    type: "code",
    content:
      content.length <= STRUCTURED_FALLBACK_LENGTH
        ? content
        : content.slice(0, STRUCTURED_FALLBACK_LENGTH - suffix.length) + suffix,
    filetype: "json",
  }
}

function shellOutput(command: string, raw: string): string | undefined {
  const body = stripAnsi(raw).replace(/^\n+/, "").replace(/\n+$/, "")
  if (!body) {
    return undefined
  }

  if (!command) {
    return body
  }

  return `\n${body}`
}

export function toolEntryBody(
  commit: StreamCommit,
  raw: string,
  options?: { shellOutput?: boolean },
): RunEntryBody | undefined {
  if (commit.shell) {
    if (commit.phase === "start") {
      return textBody(`$ ${commit.shell.command}`)
    }

    if (commit.phase === "progress") {
      return textBody(shellOutput(commit.shell.command, raw) ?? "")
    }

    if (commit.toolState === "error") {
      const ctx = toolFrame(commit, raw)
      return textBody(toolScroll("final", ctx))
    }

    return undefined
  }

  const ctx = toolFrame(commit, raw)
  const view = toolView(ctx.name)

  if (ctx.name === "shell" && commit.phase === "progress" && options?.shellOutput === false) return undefined

  if (ctx.name === "subagent") {
    if (commit.phase === "start") {
      return undefined
    }

    if (commit.phase === "final" && ctx.status === "completed") {
      const result = taskResult(ctx.output)
      if (result) {
        return markdownBody(result)
      }
    }
  }

  if (commit.phase === "progress" && !view.output) {
    return undefined
  }

  if (commit.phase === "final") {
    if (ctx.status === "error") {
      return textBody(toolScroll("final", ctx))
    }

    if (!view.final) {
      return undefined
    }

    if (ctx.status && ctx.status !== "completed") {
      return textBody(ctx.raw.trim())
    }

    if (toolStructuredFinal(commit)) {
      return structuredBody(commit, raw) ?? textBody(toolScroll("final", ctx))
    }

    if (!rule(ctx.name) && !ctx.output.trim()) {
      return structuredFallback(ctx.meta) ?? textBody(toolScroll("final", ctx))
    }
  }

  return textBody(toolScroll(commit.phase, ctx))
}

export function toolFiletype(input?: string): string | undefined {
  if (!input) {
    return undefined
  }

  const ext = path.extname(input)
  const lang = LANGUAGE_EXTENSIONS[ext]
  if (["typescriptreact", "javascriptreact", "javascript"].includes(lang)) {
    return "typescript"
  }

  return lang
}

import type { StreamCommit } from "./types"

export function turnSummaryCommit(input: {
  agent: string
  model: string
  duration: string
  messageID?: string
}): StreamCommit {
  return {
    kind: "system",
    text: `${input.agent} · ${input.model} · ${input.duration}`,
    phase: "final",
    source: "system",
    summary: {
      agent: input.agent,
      model: input.model,
      duration: input.duration,
    },
    messageID: input.messageID,
  }
}

// Model variant resolution and persistence.
//
// Variants are provider-specific reasoning effort levels (e.g., "high", "max").
// Resolution priority: CLI --variant flag > valid session history > saved preference.
//
// The saved variant persists across sessions in ~/.local/state/opencode/model.json
// so your last-used variant sticks. Cycling (ctrl+t) updates both the active
// variant and the persisted file.
import { createSession, sessionVariant, type RunSession, type SessionMessages } from "./session.shared"
import type { RunInput, RunProvider } from "./types"
import { cycleModelVariant, normalizeModelVariant } from "../model-preference"

export function modelInfo(providers: RunProvider[] | undefined, model: NonNullable<RunInput["model"]>) {
  const provider = providers?.find((item) => item.id === model.providerID)
  return {
    provider: provider?.name ?? model.providerID,
    model: provider?.models[model.modelID]?.name ?? model.modelID,
  }
}

export function formatModelLabel(
  model: NonNullable<RunInput["model"]>,
  variant: string | undefined,
  providers?: RunProvider[],
): string {
  const names = modelInfo(providers, model)
  const label = variant ? ` · ${variant}` : ""
  return `${names.model} · ${names.provider}${label}`
}

export function cycleVariant(current: string | undefined, variants: string[]): string | undefined {
  return cycleModelVariant(current, variants)
}

export function pickVariant(model: RunInput["model"], input: RunSession | SessionMessages): string | undefined {
  return sessionVariant(Array.isArray(input) ? createSession(input) : input, model)
}

function fitVariant(value: string | undefined, variants: string[]): string | undefined {
  const normalized = normalizeModelVariant(value)
  return normalized && (variants.length === 0 || variants.includes(normalized)) ? normalized : undefined
}

// Picks the active variant. CLI flag wins, then valid session history, then the
// saved preference. Saved and session values are dropped when the provider no
// longer offers them.
export function resolveVariant(
  input: string | undefined,
  session: string | undefined,
  saved: string | undefined,
  variants: string[],
): string | undefined {
  if (input !== undefined) {
    return normalizeModelVariant(input)
  }

  return fitVariant(session, variants) ?? fitVariant(saved, variants)
}

import type { MiniSettingChange, MiniSettings, MiniVerbosity } from "./types"

const levels: readonly MiniVerbosity[] = ["quiet", "default", "everything"]

const knobs = ["thinking", "tools", "shell_output", "turn_summary", "footer"] as const

type VerbosityKnobs = Pick<MiniSettings, (typeof knobs)[number]>

const presets = {
  quiet: {
    thinking: "hide",
    tools: "hide",
    shell_output: "hide",
    turn_summary: "hide",
    footer: "hide",
  },
  default: {
    thinking: "show",
    tools: "hide",
    shell_output: "hide",
    turn_summary: "show",
    footer: "show",
  },
  everything: {
    thinking: "show",
    tools: "show",
    shell_output: "show",
    turn_summary: "show",
    footer: "show",
  },
} as const satisfies Record<MiniVerbosity, VerbosityKnobs>

const labels = {
  quiet: "Quiet",
  default: "Default",
  everything: "Everything",
  custom: "Custom",
} as const

export function verbosityPreset(level: MiniVerbosity): VerbosityKnobs {
  return { ...presets[level] }
}

export function verbosityLabel(level: MiniVerbosity | "custom") {
  return labels[level]
}

export function matchMiniVerbosity(settings: MiniSettings): MiniVerbosity | "custom" {
  for (const level of levels) {
    if (knobs.every((key) => settings[key] === presets[level][key])) return level
  }
  return "custom"
}

export function cycleMiniVerbosity(settings: MiniSettings, direction: 1 | -1): MiniVerbosity {
  const current = matchMiniVerbosity(settings)
  const index = current === "custom" ? nearestMiniVerbosity(settings) : levels.indexOf(current)
  const next = index + direction
  if (next < 0) return levels[0]!
  if (next >= levels.length) return levels[levels.length - 1]!
  return levels[next]!
}

export function verbosityChange(settings: MiniSettings, direction: 1 | -1): MiniSettingChange | undefined {
  const value = cycleMiniVerbosity(settings, direction)
  if (matchMiniVerbosity(settings) === value) return
  return { key: "verbosity", value }
}

export function applyMiniSettingChange(settings: MiniSettings, change: MiniSettingChange): MiniSettings {
  if (change.key === "verbosity") return { ...settings, ...verbosityPreset(change.value) }
  return { ...settings, [change.key]: change.value }
}

function nearestMiniVerbosity(settings: MiniSettings) {
  return levels.reduce((best, level, index) => {
    if (verbosityDistance(settings, level) < verbosityDistance(settings, levels[best]!)) return index
    return best
  }, 0)
}

function verbosityDistance(settings: MiniSettings, level: MiniVerbosity) {
  return knobs.filter((key) => settings[key] !== presets[level][key]).length
}

import { readJson, writeJsonAtomic } from "./util/persistence"
import { isRecord } from "./util/record"
import { Flock } from "@opencode/util/flock"
import { watch } from "node:fs"
import path from "node:path"

export type ModelPreferenceModel = {
  providerID: string
  modelID: string
}

export type ModelPreference = {
  recent: ModelPreferenceModel[]
  favorite: ModelPreferenceModel[]
  variant: Record<string, string | undefined>
}

export type ModelPreferenceDocument = Record<string, unknown> & ModelPreference

function models(value: unknown) {
  if (!Array.isArray(value)) return []
  return value.flatMap((item): ModelPreferenceModel[] => {
    if (!isRecord(item)) return []
    if (typeof item.providerID !== "string" || item.providerID.length === 0) return []
    if (typeof item.modelID !== "string" || item.modelID.length === 0) return []
    return [{ providerID: item.providerID, modelID: item.modelID }]
  })
}

function variants(value: unknown) {
  if (!isRecord(value)) return {}
  return Object.fromEntries(
    Object.entries(value).flatMap(([key, item]) => {
      if (key.length === 0 || typeof item !== "string" || item.length === 0) return []
      // Preserve explicit "default" so it can override an agent's configured variant.
      return [[key, item]] as const
    }),
  )
}

export function normalizeModelVariant(value: string | undefined) {
  return value === "default" ? undefined : value
}

export function modelPreferenceKey(model: ModelPreferenceModel) {
  return `${model.providerID}/${model.modelID}`
}

export function recentModels(model: ModelPreferenceModel, recent: ModelPreferenceModel[]) {
  const seen = new Set<string>()
  return [model, ...recent]
    .filter((item) => {
      const key = modelPreferenceKey(item)
      if (seen.has(key)) return false
      seen.add(key)
      return true
    })
    .slice(0, 10)
    .map((item) => ({ providerID: item.providerID, modelID: item.modelID }))
}

export function favoriteModels(model: ModelPreferenceModel, favorite: ModelPreferenceModel[], enabled: boolean) {
  const current = favorite.filter((item) => modelPreferenceKey(item) !== modelPreferenceKey(model))
  return enabled ? [model, ...current] : current
}

export function cycleModelVariant(current: string | undefined, variants: string[]) {
  const named = variants.filter((variant) => variant !== "default")
  if (named.length === 0) return undefined
  const value = normalizeModelVariant(current)
  if (value === undefined) return named[0]
  const index = named.indexOf(value)
  if (index === -1 || index === named.length - 1) return undefined
  return named[index + 1]
}

export function decodeModelPreference(value: unknown): ModelPreferenceDocument {
  const root = isRecord(value) ? value : {}
  return {
    ...root,
    recent: models(root.recent),
    favorite: models(root.favorite),
    variant: variants(root.variant),
  }
}

function preference(value: ModelPreferenceDocument): ModelPreference {
  return {
    recent: value.recent,
    favorite: value.favorite,
    variant: value.variant,
  }
}

function patch(value: Partial<ModelPreference>) {
  return {
    ...(value.recent === undefined ? {} : { recent: models(value.recent) }),
    ...(value.favorite === undefined ? {} : { favorite: models(value.favorite) }),
    ...(value.variant === undefined ? {} : { variant: variants(value.variant) }),
  }
}

export function createModelPreferenceRepository(filePath: string) {
  let pending = Promise.resolve()
  let revision = 0
  let watcher: ReturnType<typeof watch> | undefined
  let reload: ReturnType<typeof setTimeout> | undefined
  const listeners = new Set<(value: ModelPreference) => void>()
  const read = () =>
    readJson<unknown>(filePath)
      .then(decodeModelPreference)
      .catch(() => decodeModelPreference(undefined))

  function update(change: (current: ModelPreference) => Partial<ModelPreference>) {
    const result = pending.then(() =>
      Flock.withLock(
        filePath,
        async () => {
          const current = await read()
          await writeJsonAtomic(filePath, { ...current, ...patch(change(preference(current))) })
        },
        { dir: path.join(path.dirname(filePath), "locks") },
      ),
    )
    pending = result.then(
      () => undefined,
      () => undefined,
    )
    return result
  }

  function load() {
    return pending.then(read).then(preference)
  }

  async function refresh() {
    const current = ++revision
    const value = await load()
    if (current !== revision) return
    listeners.forEach((listener) => listener(value))
  }

  return {
    load,
    addRecent(model: ModelPreferenceModel) {
      return update((current) => ({ recent: recentModels(model, current.recent) }))
    },
    setFavorite(model: ModelPreferenceModel, enabled: boolean) {
      return update((current) => ({ favorite: favoriteModels(model, current.favorite, enabled) }))
    },
    subscribe(listener: (value: ModelPreference) => void) {
      listeners.add(listener)
      void refresh()
      if (!watcher) {
        watcher = watch(path.dirname(filePath), (_event, filename) => {
          const changed = filename?.toString()
          const name = path.basename(filePath)
          if (changed !== undefined && changed !== name && !changed.startsWith(name + ".")) return
          clearTimeout(reload)
          reload = setTimeout(() => void refresh(), 50)
        })
        watcher.on("error", () => {
          watcher?.close()
          watcher = undefined
        })
      }
      return () => {
        listeners.delete(listener)
        if (listeners.size > 0) return
        clearTimeout(reload)
        watcher?.close()
        watcher = undefined
      }
    },
    async resolveVariant(model: ModelPreferenceModel) {
      return normalizeModelVariant((await load()).variant[modelPreferenceKey(model)])
    },
    saveVariant(model: ModelPreferenceModel, value: string | undefined) {
      const key = modelPreferenceKey(model)
      const next = normalizeModelVariant(value) ?? "default"
      return update((current) => ({ variant: { ...current.variant, [key]: next } }))
    },
  }
}

import { PluginContextProvider } from "@opencode/plugin/tui"
import { createRoot, createUniqueId, getOwner, onCleanup, runWithOwner, untrack, type JSX } from "solid-js"
import type {
  Context,
  Dialog,
  DialogSelectOptions,
  Page,
  SlotClaim,
  SlotMap,
  SlotPath,
  Toast,
} from "@opencode/plugin/tui/context"
import type { Placement, PlacementKind } from "./structure"
import { infoStringToFiletype, type MarkdownCodeBlockRenderer } from "@opentui/core"
import { useRenderer } from "@opentui/solid"
import { useClient } from "../context/client"
import { useData } from "../context/data"
import { Keymap } from "../context/keymap"
import { useRoute } from "../context/route"
import { useTuiApp, useTuiPaths } from "../context/runtime"
import { useLocation } from "../context/location"
import { useThemes } from "../context/theme"
import { DialogAlert } from "../ui/dialog-alert"
import { DialogConfirm } from "../ui/dialog-confirm"
import { DialogPrompt } from "../ui/dialog-prompt"
import { DialogSelect } from "../ui/dialog-select"
import { useDialog } from "../ui/dialog"
import { useToast } from "../ui/toast"
import { useAttention } from "../context/attention"
import { useStorage } from "../context/storage"
import { useSessionTabs } from "../context/session-tabs"
import { useOptionalPanel } from "../context/panel"
import { useLocal } from "../context/local"
import { abbreviateHome } from "../util/path-format"

export type Dispose = () => Promise<void>

// Slot inputs erased to their union: the registry stores one render shape
// regardless of which path a claim targets.
export type SlotRender = (input: SlotMap[SlotPath]) => JSX.Element

// A registered claim as stored by the plugin provider's registry.
export type RegisteredSlot = {
  readonly placement: Placement
  readonly render: SlotRender
}

const placements = ["prepend", "append", "before", "after", "replace"] as const satisfies readonly PlacementKind[]

// The provider's registration store, narrowed to what a plugin context needs:
// route/slot registration lands there, but ordering and lifecycle stay owned
// by the provider.
export type Registry = {
  has(kind: "routes" | "slots" | "markdown", name: string): boolean
  set(kind: "routes", name: string, page: Page): void
  set(kind: "slots", name: string, claim: RegisteredSlot): void
  set(kind: "markdown", name: string, render: MarkdownCodeBlockRenderer): void
  remove(kind: "routes" | "slots" | "markdown", name: string): void
  active(): boolean
}

// The host services a plugin context adapts. Collected once by the provider
// (hooks must run during component setup) and shared by every activation.
export function usePluginHost() {
  return {
    owner: getOwner(),
    renderer: useRenderer(),
    client: useClient(),
    data: useData(),
    route: useRoute(),
    keymap: Keymap.use(),
    shortcuts: Keymap.useShortcuts(),
    keymapState: Keymap.useState(),
    app: useTuiApp(),
    paths: useTuiPaths(),
    location: useLocation(),
    themes: useThemes(),
    dialog: useDialog(),
    toast: useToast(),
    attention: useAttention(),
    storage: useStorage(),
    sessionTabs: useSessionTabs(),
    panel: useOptionalPanel(),
    local: useLocal(),
  }
}

// Build the API surface handed to one plugin activation: host services
// adapted to the plugin contract, with everything registered through it
// unwinding via `owned` when the activation is disposed.
export function createPluginContext(input: {
  host: ReturnType<typeof usePluginHost>
  id: string
  options: Readonly<Record<string, any>> | undefined
  owned: Dispose[]
  registry: Registry
}): Context {
  const host = input.host
  input.owned.push(async () => host.panel?.release(input.id))
  let context: Context
  let claims = 0
  // Every dialog and registered render is wrapped so plugin components can
  // reach their own context through usePlugin().
  const provide = (render: () => JSX.Element) => (
    <PluginContextProvider value={context}>{render()}</PluginContextProvider>
  )
  const dialogApi = createDialogApi(host.dialog, provide)
  const toastApi: Toast = {
    show(options) {
      const toast = {
        title: options.title,
        message: options.message,
        variant: options.variant ?? "info",
        duration: options.duration,
      }
      const sessionID = options.sessionID
      if (sessionID === undefined) {
        host.toast.show(toast)
        return
      }
      const route = host.route.data
      if (route.type === "session" && host.data.session.root(route.sessionID) === host.data.session.root(sessionID)) {
        host.toast.show(toast)
        return
      }
      host.toast.show({
        ...toast,
        title: toast.title ?? host.data.session.get(sessionID)?.title,
        action: { label: "Open", run: () => host.route.navigate({ type: "session", sessionID }) },
      })
    },
  }
  // Unregistering after deactivation is a no-op: deactivate already resets
  // the registration's routes and slots wholesale.
  const registration = (kind: "routes" | "slots" | "markdown", name: string) => {
    let registered = true
    const unregister = () => {
      if (!registered) return
      registered = false
      if (!input.registry.active()) return
      input.registry.remove(kind, name)
    }
    input.owned.push(async () => unregister())
    return unregister
  }
  let cleanups: Set<() => void> | undefined = new Set()
  input.owned.push(async () => {
    const active = cleanups
    cleanups = undefined
    active?.forEach((dispose) => dispose())
  })
  context = {
    options: input.options ?? {},
    get location() {
      return host.location.current
    },
    app: { version: host.app.version, channel: host.app.channel },
    renderer: host.renderer,
    client: host.client.api,
    data: host.data,
    attention: host.attention,
    get theme() {
      return host.themes.currentTokens()
    },
    get themeMode() {
      return host.themes.mode()
    },
    markdown: {
      registerCodeBlockRenderer(language, render) {
        const name = infoStringToFiletype(language)
        if (!name) throw new Error("Markdown code-block language is required")
        if (input.registry.has("markdown", name)) {
          throw new Error(`Markdown code-block renderer already registered: ${name}`)
        }
        input.registry.set("markdown", name, render)
        return registration("markdown", name)
      },
    },
    keymap: {
      layer(factory) {
        const active = cleanups
        if (!active) return
        // Validate outside Solid, whose error routing would bypass the caller.
        Keymap.validateCommands(untrack(factory).commands)
        const caller = getOwner()
        createRoot((dispose) => {
          active.add(dispose)
          onCleanup(() => active.delete(dispose))
          if (caller) runWithOwner(caller, () => onCleanup(dispose))
          Keymap.createLayer(factory)
        }, caller ?? host.owner)
      },
      dispatch: host.keymap.dispatch,
      shortcuts: host.shortcuts.list,
      commands: host.keymapState.commands,
      pending: host.keymapState.pending,
      active: host.keymapState.active,
      mode: host.keymap.mode,
    },
    storage: {
      store: (key, options) => host.storage.store(`plugin.${input.id}.${key}`, options),
      memory: (key, options) => host.storage.memory(`plugin.${input.id}.${key}`, options),
    },
    ui: {
      dialog: dialogApi,
      toast: toastApi,
      format: {
        path: (value) => abbreviateHome(value, host.paths.home),
      },
      router: {
        register(page) {
          if (input.registry.has("routes", page.name)) throw new Error(`Route already registered: ${page.name}`)
          input.registry.set("routes", page.name, {
            ...page,
            render: (data) => provide(() => page.render(data)),
          })
          return registration("routes", page.name)
        },
        navigate(destination) {
          if (destination.type === "plugin") {
            host.route.navigate({ ...destination, id: "id" in destination ? destination.id : input.id })
            return
          }
          host.route.navigate(destination)
        },
        current() {
          return host.route.data
        },
      },
      panel: {
        open(name, options) {
          if (!host.panel || !input.registry.active()) return false
          const route = host.route.data
          if (route.type !== "session") return false
          host.panel.open({ plugin: input.id, name, sessionID: route.sessionID }, options?.presentation)
          return true
        },
        close: () => host.panel?.release(input.id),
        current() {
          const current = host.panel?.current()
          if (current?.plugin !== input.id) return
          return { name: current.name, sessionID: current.sessionID }
        },
      },
      tabs: {
        enabled: host.sessionTabs.enabled,
        list: () =>
          host.sessionTabs.tabs().map((tab) => {
            const status = host.sessionTabs.status(tab.sessionID)
            return {
              ...tab,
              active: host.sessionTabs.current() === tab.sessionID,
              ...status,
              attention: Boolean(status.attention),
            }
          }),
        open(sessionID) {
          if (!host.sessionTabs.enabled()) return false
          host.sessionTabs.open(sessionID)
          return true
        },
        focus(sessionID) {
          if (!host.sessionTabs.enabled()) return false
          host.sessionTabs.select(sessionID)
          return true
        },
        move(sessionID, index) {
          if (!host.sessionTabs.enabled()) return false
          const target = host.data.session.root(sessionID)
          if (!host.sessionTabs.tabs().some((tab) => tab.sessionID === target)) return false
          host.sessionTabs.move(target, index)
          return true
        },
        close(sessionID) {
          if (!host.sessionTabs.enabled()) return false
          const target = sessionID ?? host.sessionTabs.current()
          if (!target || !host.sessionTabs.tabs().some((tab) => tab.sessionID === target)) return false
          host.sessionTabs.close(target)
          return true
        },
      },
      model: {
        current() {
          const selection = host.local.model.selection()
          if (!selection) return
          return { providerID: selection.providerID, modelID: selection.modelID, variant: selection.variant }
        },
        variant: {
          list: () => host.local.model.variant.list(),
          set(variant) {
            if (!host.local.model.selection()) return false
            if (variant !== undefined && !host.local.model.variant.list().includes(variant)) return false
            host.local.model.variant.set(variant)
            return true
          },
        },
      },
      slot(value: SlotClaim) {
        // Keys are counter-suffixed so one plugin may claim several places;
        // order within the plugin is registration order.
        const key = `slot#${claims++}`
        // Exactly one placement kind, enforced at runtime for untyped plugins.
        const kinds = placements.filter((item) => value[item] !== undefined)
        if (kinds.length !== 1) throw new Error("Slot claim requires exactly one placement key")
        const kind = kinds[0]
        input.registry.set("slots", key, {
          placement: { kind, target: value[kind] as string },
          // The registration map erases the path-specific input type.
          render: (slotInput) => provide(() => (value.render as SlotRender)(slotInput)),
        })
        return registration("slots", key)
      },
    },
  }
  return context
}

// A dialog promise must settle exactly once even when confirm and close
// callbacks both fire.
function settle<T>(resolve: (value: T) => void) {
  let settled = false
  return (value: T) => {
    if (settled) return
    settled = true
    resolve(value)
  }
}

export function createDialogApi(
  dialog: ReturnType<typeof useDialog>,
  provide: (render: () => JSX.Element) => JSX.Element,
) {
  const api: Dialog = {
    show(render, onClose) {
      dialog.replace(() => provide(render), onClose)
    },
    set(options) {
      dialog.setSize(options.size ?? "medium")
      dialog.setCentered(options.centered ?? false)
    },
    clear() {
      dialog.clear()
    },
    alert(options) {
      return new Promise<void>((resolve) => {
        const done = settle(resolve)
        api.show(() => <DialogAlert title={options.title} message={options.message} onConfirm={done} />, done)
      })
    },
    confirm(options) {
      return new Promise<boolean | undefined>((resolve) => {
        const done = settle(resolve)
        api.show(
          () => (
            <DialogConfirm
              title={options.title}
              message={options.message}
              label={options.label}
              onConfirm={() => done(true)}
              onCancel={() => done(false)}
            />
          ),
          () => done(undefined),
        )
      })
    },
    prompt(options) {
      return new Promise<string | undefined>((resolve) => {
        const done = settle(resolve)
        api.show(
          () => (
            <DialogPrompt
              title={options.title}
              description={options.description ? () => <text>{options.description}</text> : undefined}
              placeholder={options.placeholder}
              value={options.value}
              onConfirm={(value) => {
                done(value)
                api.clear()
              }}
            />
          ),
          () => done(undefined),
        )
      })
    },
    select<Value>(options: DialogSelectOptions<Value>) {
      return new Promise<Value | undefined>((resolve) => {
        const done = settle<Value | undefined>(resolve)
        const search = options.search
        const id = createUniqueId()
        api.show(
          () => (
            <DialogSelect<Value>
              title={options.title}
              placeholder={options.placeholder}
              options={options.options.map((option) => ({ ...option }))}
              current={options.current}
              search={
                search &&
                ((query) =>
                  search(
                    query,
                    options.options.filter((option) => !option.disabled),
                  ))
              }
              actions={options.actions?.map((action, index) => {
                const base = {
                  command: `plugin.dialog.select.${id}.${index}`,
                  title: action.title,
                  side: action.side,
                  bind: action.bind,
                }
                if (action.selection === "none")
                  return { ...base, selection: action.selection, onTrigger: action.onTrigger }
                return { ...base, onTrigger: (option) => action.onTrigger(option.value) }
              })}
              onSelect={(option) => {
                done(option.value)
                api.clear()
              }}
            />
          ),
          () => done(undefined),
        )
      })
    },
  }
  return api
}

