import { createPluginContext, usePluginHost, type Dispose, type RegisteredSlot, type SlotRender } from "./api"
import { createSourceWatcher } from "./watch"
import { discoverPluginTargets, localSource, mergePluginTargets } from "./discovery"
import { createPluginSources } from "./source"
import { isMissingPath } from "../util/config-directories"
import { createMarkdownRenderer } from "./markdown"
import { useLog, type LogTags } from "../context/log"

export interface PackageSource {
  readonly prepare: (spec: string, install?: boolean) => Promise<Host.Target>
}

type State =
  | { readonly target: string; readonly id: string; readonly status: "active" | "inactive" }
  | { readonly target: string; readonly status: "unsupported" }
  | { readonly target: string; readonly id?: string; readonly status: "failed"; readonly error: string }

type RegisteredPlugin = {
  readonly id: string
  readonly source: "builtin" | "external"
  readonly active: boolean
}

type Value = {
  readonly ready: () => boolean
  readonly list: () => ReadonlyArray<State>
  readonly server: () => readonly PluginInfo[]
  readonly registered: () => ReadonlyArray<RegisteredPlugin>
  readonly route: (id: string, name: string) => Page["render"] | undefined
  readonly slots: {
    // A mounted <Slot> instance registers its path; the disposer unregisters.
    readonly register: (path: string) => () => void
    readonly resolved: () => ReturnType<typeof resolveSlots<SlotRender>>
  }
  readonly markdown: () => MarkdownOptions["renderNode"]
  readonly activate: (id: string) => Promise<boolean>
  readonly deactivate: (id: string) => Promise<boolean>
}

type Registration = {
  plugin: Plugin.Definition
  source: RegisteredPlugin["source"]
  target?: string
  version: string
  options?: Readonly<Record<string, any>>
  active: boolean
  routes: Record<string, Page>
  slots: Record<string, RegisteredSlot>
  markdown: Record<string, MarkdownCodeBlockRenderer>
  cleanups: Dispose[]
}

// One entry of the desired plugin generation produced by the resolve phase.
type Desired = Pick<Registration, "plugin" | "source" | "target" | "version" | "options"> & { enabled: boolean }
type Trace = <T>(stage: string, tags: LogTags, task: () => Promise<T>) => Promise<T>

const PluginContext = createContext<Value>()

export function PluginProvider(props: ParentProps<{ packages: PackageSource; directories: string[] }>) {
  const host = usePluginHost()
  const log = useLog({ component: "plugin" })
  const config = useConfig()
  const lifecycle = useTuiLifecycle()
  const client = useClient()
  const data = useData()
  const [serverPlugins, setServerPlugins] = createSignal<readonly PluginInfo[]>([])
  const serverTuiPlugins = createMemo(() =>
    serverPlugins().filter(
      (plugin): plugin is PluginInfo & { readonly source: { readonly type: "package" } | { readonly type: "local" } } =>
        plugin.state.status === "active" &&
        plugin.features.tui === true &&
        (plugin.source.type === "package" || plugin.source.type === "local"),
    ),
  )
  const directory = config.path ? path.dirname(config.path) : process.cwd()
  const [store, setStore] = createStore({
    ready: false,
    states: [] as ReadonlyArray<State>,
    registrations: {} as Record<string, Registration>,
  })
  // One save can emit several watch events. Remember setup failures so those
  // events do not repeatedly tear down and restore the last good generation.
  const setupFailures = new Map<string, { version: string; options: Registration["options"]; error: string }>()
  let operationID = 0
  const trace: Trace = (stage, tags, task) => {
    const id = ++operationID
    const started = Date.now()
    log.debug("plugin operation started", { id, stage, ...tags })
    const stalled = setTimeout(
      () => log.warn("plugin operation stalled", { id, stage, elapsedMs: Date.now() - started, ...tags }),
      5_000,
    )
    return task()
      .then(
        (value) => {
          log.debug("plugin operation completed", { id, stage, durationMs: Date.now() - started, ...tags })
          return value
        },
        (error) => {
          log.warn("plugin operation failed", {
            id,
            stage,
            durationMs: Date.now() - started,
            error: errorMessage(error),
            ...tags,
          })
          throw error
        },
      )
      .finally(() => clearTimeout(stalled))
  }
  const markdown = createMarkdownRenderer(() =>
    Object.values(store.registrations).flatMap((registration) => (registration.active ? [registration.markdown] : [])),
  )
  const clearContributions = (id: string) => {
    setStore("registrations", id, "routes", reconcileStore({}))
    setStore("registrations", id, "slots", reconcileStore({}))
    setStore("registrations", id, "markdown", reconcileStore({}))
  }

  const activate = async (id: string) => {
    const item = store.registrations[id]
    if (!item) return false
    await deactivate(id)
    batch(() => {
      clearContributions(id)
      setStore("registrations", id, "cleanups", [])
    })
    const owned: Dispose[] = []
    const context = createPluginContext({
      host,
      id,
      options: item.options,
      owned,
      registry: {
        has: (kind, name) => Boolean(store.registrations[id]?.[kind][name]),
        set: (
          kind: "routes" | "slots" | "markdown",
          name: string,
          value: Page | RegisteredSlot | MarkdownCodeBlockRenderer,
        ) => setStore("registrations", id, kind, name, () => value),
        remove: (kind, name) =>
          setStore(
            "registrations",
            produce((registrations) => {
              if (!registrations[id]) return
              delete registrations[id][kind][name]
            }),
          ),
        active: () => Boolean(store.registrations[id]?.active),
      },
    })
    const cleanup = await trace("setup", { plugin: id, target: item.target }, () =>
      setup(item.plugin, context, owned),
    ).catch((error) => {
      clearContributions(id)
      if (item.target)
        setupFailures.set(item.target, {
          version: item.version,
          options: snapshotOptions(item.options),
          error: errorMessage(error),
        })
      throw error
    })
    if (cleanup) owned.push(async () => cleanup())
    if (item.target && sameGeneration(setupFailures.get(item.target), item)) setupFailures.delete(item.target)
    batch(() => {
      setStore("registrations", id, "cleanups", owned)
      setStore("registrations", id, "active", true)
      setStore("states", (items) =>
        items.map((state) =>
          "id" in state && state.id === id ? { target: state.target, id, status: "active" } : state,
        ),
      )
    })
    return true
  }

  const deactivate = async (id: string) => {
    const item = store.registrations[id]
    if (!item?.active) return false
    const cleanups = [...item.cleanups]
    batch(() => {
      setStore("registrations", id, "active", false)
      setStore("registrations", id, "cleanups", [])
    })
    await trace("cleanup", { plugin: id, target: item.target, cleanups: cleanups.length }, () =>
      disposeAll(cleanups),
    ).finally(() =>
      batch(() => {
        if (store.registrations[id]) {
          clearContributions(id)
        }
        setStore("states", (items) =>
          items.map((state) =>
            "id" in state && state.id === id ? { target: state.target, id, status: "inactive" } : state,
          ),
        )
      }),
    )
    return true
  }

  // Cleanup failures must not stop a swap or teardown, but they should not
  // vanish either: the old generation may still own listeners or intervals.
  const deactivateNoisily = (id: string) =>
    deactivate(id).catch((error) =>
      host.toast.show({ variant: "error", title: "Plugin", message: `${id}: cleanup failed: ${errorMessage(error)}` }),
    )

  // Every lifecycle mutation — reconciles, manual dialog toggles, shutdown —
  // is serialized through one chain so generations can never interleave.
  let loading = Promise.resolve()
  const enqueue = <T,>(task: () => Promise<T>) => {
    const result = loading.catch(() => undefined).then(task)
    loading = result.then(
      () => undefined,
      () => undefined,
    )
    return result
  }

  // Hot-reload local plugin sources: watch the discovery directory and any
  // local entrypoints (see watch.ts for the mechanics), debounced into a
  // serialized reconcile so bursts of events rebuild the generation once.
  let pending: ReturnType<typeof setTimeout> | undefined
  const watcher = createSourceWatcher(() => {
    clearTimeout(pending)
    pending = setTimeout(() => {
      // Observe failures immediately: a plugin cleanup that throws would
      // otherwise surface as an unhandled rejection until the next trigger.
      void enqueue(reconcile).catch(() => undefined)
    }, 100)
  })
  const stopWatching = () => {
    clearTimeout(pending)
    watcher.dispose()
  }
  const sources = createPluginSources(watcher.wait)
  onCleanup(stopWatching)

  // Rebuild the plugin generation as resolve → compare → swap, mirroring the
  // core plugin registry: fold the ordered entries into a desired end state
  // (importing only new or changed sources, before anything running is
  // touched), no-op when the generation is unchanged, and restart only the
  // plugins that differ. Membership or order changes rebuild the whole
  // generation to preserve slot-order semantics.
  // Package resolution failures would otherwise retry a full npm install on
  // every watch event; remember them until the configuration changes.
  const npmFailures = new Map<string, string>()
  let reconciliationID = 0
  const reconcile = async () => {
    const id = ++reconciliationID
    const started = Date.now()
    log.info("plugin reconciliation started", { id })
    await trace("watch", { reconciliation: id, directories: props.directories }, () =>
      Promise.all(props.directories.map(watcher.wait)).then(() => undefined),
    )
    // Discovery admits TUI-only plugins while server inventory carries combined plugins.
    // Their overlap is intentional; explicit configuration remains the final authority.
    const entries = mergePluginTargets(
      [
        ...(
          await trace("discover", { reconciliation: id, directories: props.directories }, () =>
            discoverPluginTargets(props.directories),
          )
        ).map((entry) => ({
          entry,
          install: true,
          optional: true,
        })),
        ...serverTuiPlugins().map((plugin) => ({
          entry: plugin.source.type === "package" ? plugin.source.target : path.dirname(plugin.source.path),
          install: false,
          optional: true,
        })),
        ...(config.data.plugins ?? []).map((entry) => ({ entry, install: true, optional: false })),
      ],
      directory,
    )

    // Resolve: fold entries into one desired generation. A source that fails
    // to import keeps its running previous version and only reports failure.
    const { builtins } = await import("./builtins")
    const desired = new Map<string, Desired>()
    for (const plugin of builtins)
      desired.set(plugin.id, { plugin, source: "builtin", version: "builtin", enabled: true })
    const failures: State[] = []
    for (const source of entries) {
      const entry = source.entry
      const target = typeof entry === "string" ? entry : entry.package
      if (target.startsWith("-")) {
        for (const item of desired.values()) if (matches(target.slice(1), item.plugin.id)) item.enabled = false
        continue
      }

      const selected = [...desired.values()].filter((item) => matches(target, item.plugin.id))
      if (selected.length || target === "*" || target.endsWith(".*") || target.startsWith("opencode.")) {
        for (const item of selected) item.enabled = true
        continue
      }

      const options = typeof entry === "string" ? undefined : entry.options
      const local = localSource(target, directory)
      if (
        local &&
        (await stat(local).then(
          (info) => info.isFile(),
          (error) => (isMissingPath(error) ? false : Promise.reject(error)),
        ))
      )
        continue
      // Watch even when the resolve below fails so fixing a broken plugin reloads it.
      if (local) await watcher.add(fileURLToPath(local))
      const previous = Object.values(store.registrations).find((registration) => registration.target === target)
      const memo = local ? undefined : npmFailures.get(target)
      const resolved = memo
        ? { status: "failed" as const, error: memo }
        : await resolvePlugin(
            target,
            local,
            options,
            previous,
            props.packages,
            source.install,
            sources.read,
            trace,
            id,
          ).catch((error) => ({
            status: "failed" as const,
            error: errorMessage(error),
          }))
      if (resolved.status === "unsupported") {
        if (source.optional) continue
        failures.push({ target, status: "unsupported" })
        continue
      }
      if (resolved.status === "failed") {
        if (!local && !previous) npmFailures.set(target, resolved.error)
        failures.push({
          target,
          id: previous?.plugin.id,
          status: "failed",
          error: previous?.active ? `${resolved.error} (previous version still active)` : resolved.error,
        })
        if (previous) desired.set(previous.plugin.id, toDesired(previous))
        continue
      }
      const setupFailure = setupFailures.get(target)
      if (setupFailure && sameGeneration(setupFailure, { version: resolved.version, options }) && previous) {
        failures.push({
          target,
          id: previous.plugin.id,
          status: "failed",
          error: previous.active ? `${setupFailure.error} (previous version still active)` : setupFailure.error,
        })
        desired.set(previous.plugin.id, toDesired(previous))
        continue
      }
      setupFailures.delete(target)
      desired.set(resolved.plugin.id, {
        plugin: resolved.plugin,
        source: "external",
        target,
        version: resolved.version,
        options,
        enabled: true,
      })
    }

    // Compare: unchanged plugins are never touched, and a fully unchanged
    // generation is a no-op, so spurious watch events cost nothing.
    const currentIds = Object.keys(store.registrations)
    const desiredIds = [...desired.keys()]
    const structural =
      currentIds.length !== desiredIds.length || currentIds.some((id, index) => desiredIds[index] !== id)
    if (structural) {
      await Promise.all(
        Object.entries(store.registrations)
          .filter(([, registration]) => registration.active)
          .map(([id]) => deactivateNoisily(id)),
      )
      setStore("registrations", reconcileStore({}))
    }
    const changed = structural
      ? desiredIds
      : desiredIds.filter((id) => {
          const registration = store.registrations[id]!
          const item = desired.get(id)!
          // enabled derives from config directives alone, so config wins over
          // manual dialog toggles on every reconcile — the same semantics
          // config saves had before hot reload existed, just more frequent.
          return !sameGeneration(registration, item) || registration.active !== item.enabled
        })

    // Swap: cleanup failures surface as a toast, never propagate, so one
    // broken plugin cannot take the rest of the generation down.
    const errors = new Map<string, string>()
    for (const id of changed) {
      const item = desired.get(id)!
      const registration = store.registrations[id]
      const replaced = !registration || !sameGeneration(registration, item)
      // Snapshot the running version before it is overwritten: an import
      // failure keeps last-good in the resolve phase, and a setup failure
      // must not cost the previous version either.
      const fallback = replaced && registration ? toDesired(registration) : undefined
      if (replaced) {
        if (registration) await deactivateNoisily(id)
        // In-place replacement keeps the registration's key position, which
        // slot ordering (mode "replace" takes the last one) depends on.
        setStore("registrations", id, toRegistration(item))
      }
      if (!item.enabled) {
        await deactivateNoisily(id)
        continue
      }
      const error = await activate(id).then(() => undefined, errorMessage)
      if (!error) continue
      errors.set(id, error)
      if (!fallback) continue
      setStore("registrations", id, toRegistration(fallback))
      if (!fallback.enabled) continue
      const restored = await activate(id).then(
        () => true,
        () => false,
      )
      if (restored) errors.set(id, `${error} (previous version still active)`)
    }

    const failedTargets = new Set(failures.map((failure) => failure.target))
    const states: State[] = [
      ...[...desired.values()].flatMap((item): State[] => {
        if (item.target === undefined) return []
        // A failed reload keeps this item running; the failure entry covers it.
        if (failedTargets.has(item.target)) return []
        const error = errors.get(item.plugin.id)
        if (error) return [{ target: item.target, id: item.plugin.id, status: "failed", error }]
        const status = store.registrations[item.plugin.id]?.active ? "active" : "inactive"
        return [{ target: item.target, id: item.plugin.id, status }]
      }),
      ...failures,
    ]
    // Surface newly failing plugins; repeated reconciles stay silent.
    for (const state of states)
      if (
        state.status === "failed" &&
        !store.states.some(
          (prev) => prev.status === "failed" && prev.target === state.target && prev.error === state.error,
        )
      )
        host.toast.show({
          variant: "error",
          title: `Plugin failed: ${state.target}`,
          message: "Run /plugins to view details.",
          action: { label: "Open plugins", run: () => host.keymap.dispatch("plugins.list") },
        })
    setStore("states", reconcileStore(states))
    log.info("plugin reconciliation completed", { id, durationMs: Date.now() - started, plugins: desired.size })
  }
  const slotItems = new WeakMap<SlotRender, Claim<SlotRender>>()
  // The mounted slot tree: path -> live <Slot> instance count. Reference
  // counted because the same path can be mounted several times (one composer
  // footer per session tab); a path exists while any instance is mounted.
  const [mounted, setMounted] = createStore<Record<string, number>>({})
  const registerSlot = (slotPath: string) => {
    setMounted(slotPath, (count) => (count ?? 0) + 1)
    return () =>
      setMounted(
        produce((counts) => {
          const count = counts[slotPath]
          if (count && count > 1) counts[slotPath] = count - 1
          else delete counts[slotPath]
        }),
      )
  }
  // Claims come back in enable order: registration-store key order across
  // plugins (generations preserve key positions in place), then registration
  // order within one plugin. The resolver's last-wins rules depend on it.
  const claims = createMemo(() =>
    Object.entries(store.registrations).flatMap(([id, registration]) =>
      Object.entries(registration.active ? registration.slots : {}).map(([key, slot]) => {
        // Rows downstream diff by reference; a stable claim per render
        // function keeps untouched plugins' slot rows (and their state)
        // alive across other plugins' reloads.
        const cached = slotItems.get(slot.render)
        if (cached) return cached
        // Placements are immutable once registered; unwrap the store proxy
        // so resolver reads don't subscribe tracked scopes.
        const item = { key: `${id}/${key}`, plugin: id, placement: unwrap(slot.placement), render: slot.render }
        slotItems.set(slot.render, item)
        return item
      }),
    ),
  )
  // Object.keys tracks the store's keys node only: refcount changes on an
  // already-mounted path (a second tab's composer) skip re-resolution.
  const resolved = createMemo(() => resolveSlots({ paths: new Set(Object.keys(mounted)), claims: claims() }))
  createEffect(
    on(
      () => JSON.stringify([serverTuiPlugins(), config.data.plugins ?? []]),
      () => {
        npmFailures.clear()
        void enqueue(reconcile).then(
          () => setStore("ready", true),
          () => setStore("ready", true),
        )
      },
    ),
  )
  const syncServerPlugins = () =>
    client.api.plugin
      .list({ location: data.location.default() })
      .then((response) => {
        const failed = response.data.filter(
          (plugin) =>
            plugin.state.status === "failed" &&
            !serverPlugins().some(
              (previous) =>
                serverPluginName(previous) === serverPluginName(plugin) && isDeepEqual(previous.state, plugin.state),
            ),
        )
        setServerPlugins(response.data)
        const first = failed[0]
        if (!first) return
        host.toast.show({
          variant: "error",
          title: failed.length === 1 ? `Plugin failed: ${serverPluginName(first)}` : `${failed.length} plugins failed`,
          message:
            (failed.length > 1 ? `${failed.map(serverPluginName).join(", ")}\n` : "") + "Run /plugins to view details.",
          action: { label: "Open plugins", run: () => host.keymap.dispatch("plugins.list") },
        })
      })
      .catch(() => undefined)
  createEffect(
    on(
      () => JSON.stringify(data.location.default()),
      () => void syncServerPlugins(),
    ),
  )
  onCleanup(client.event.on("plugin.updated", syncServerPlugins))
  onCleanup(client.event.on("server.connected", syncServerPlugins))
  onMount(() => {
    let disposing: Promise<void> | undefined
    const dispose = () => {
      if (disposing) return disposing
      stopWatching()
      disposing = loading
        .catch(() => undefined)
        .then(() =>
          Promise.all(
            Object.entries(store.registrations)
              .filter(([, registration]) => registration.active)
              .map(([id]) => deactivate(id).catch(() => undefined)),
          ),
        )
        .then(() => setStore("registrations", reconcileStore({})))
        .finally(sources.dispose)
      return disposing
    }
    const unregister = lifecycle.add(dispose)
    onCleanup(() => {
      unregister()
      void dispose()
    })
  })

  return (
    <PluginContext.Provider
      value={{
        ready: () => store.ready,
        list: () => store.states,
        server: serverPlugins,
        registered: () =>
          Object.entries(store.registrations).map(([id, plugin]) => ({
            id,
            source: plugin.source,
            active: plugin.active,
          })),
        route: (id, name) => store.registrations[id]?.routes[name]?.render,
        slots: { register: registerSlot, resolved },
        markdown,
        // Manual dialog toggles join the same chain as reconciles so a
        // toggle mid-reload cannot mix registrations across generations.
        activate: (id) => enqueue(() => activate(id)),
        deactivate: (id) => enqueue(() => deactivate(id)),
      }}
    >
      {props.children}
    </PluginContext.Provider>
  )
}

function serverPluginName(plugin: PluginInfo) {
  return (
    plugin.id ??
    (plugin.source.type === "package"
      ? plugin.source.target
      : plugin.source.type === "local"
        ? plugin.source.path
        : plugin.source.type)
  )
}

async function disposeAll(cleanups: Dispose[]) {
  const failures: unknown[] = []
  for (const cleanup of cleanups.splice(0).reverse()) await cleanup().catch((error) => failures.push(error))
  if (failures.length) throw failures[0]
}

async function setup(plugin: Plugin.Definition, context: Plugin.Context, owned: Dispose[]) {
  try {
    return await plugin.setup(context)
  } catch (error) {
    await disposeAll(owned).catch(() => undefined)
    throw error
  }
}

function matches(selector: string, id: string) {
  return selector === "*" || selector === id || (selector.endsWith(".*") && id.startsWith(selector.slice(0, -1)))
}

async function resolvePlugin(
  spec: string,
  local: URL | undefined,
  options: Readonly<Record<string, any>> | undefined,
  previous: Registration | undefined,
  packages: PackageSource,
  install: boolean,
  readSource: ReturnType<typeof createPluginSources>["read"],
  trace: Trace,
  reconciliation: number,
) {
  // Package entrypoints never change within a session, so a loaded previous
  // version needs no re-resolution (which could otherwise hit npm).
  if (!local && previous && sameOptions(previous.options, options))
    return { status: "unchanged" as const, plugin: previous.plugin, version: previous.version }
  const target = local
    ? { directory: fileURLToPath(local) }
    : await trace("prepare", { reconciliation, target: spec, install }, () => packages.prepare(spec, install))
  const entrypoint = Host.resolve(target).tui
  if (!entrypoint) return { status: "unsupported" as const }
  // Content remains stable across the several mtimes one save may expose to
  // filesystem watchers, while the generation keeps reverted modules fresh.
  let source = local
    ? await trace("read", { reconciliation, target: spec, entrypoint }, () => readSource(entrypoint))
    : {
        version: entrypoint,
        module: await trace("load", { reconciliation, target: spec, entrypoint }, () => Host.load(entrypoint)),
      }
  while (true) {
    const version = source.version
    if (previous && previous.version === version && sameOptions(previous.options, options))
      return { status: "unchanged" as const, plugin: previous.plugin, version }
    const mod = source.module
    if (local) {
      const observed = await readSource(entrypoint)
      // In-place saves can change the file between hashing and import. Retry
      // so setup always runs under the generation of the imported bytes.
      if (version !== observed.version) {
        source = observed
        continue
      }
    }
    if (typeof mod !== "object" || mod === null || !("default" in mod) || !isPlugin(mod.default))
      throw new Error(`Invalid V2 TUI plugin module: ${spec}`)
    return { status: "loaded" as const, plugin: mod.default, version }
  }
}

function toRegistration(item: Desired): Registration {
  return {
    plugin: item.plugin,
    source: item.source,
    target: item.target,
    version: item.version,
    options: snapshotOptions(item.options),
    active: false,
    routes: {},
    slots: {},
    markdown: {},
    cleanups: [],
  }
}

function toDesired(item: Registration): Desired {
  return {
    plugin: item.plugin,
    source: item.source,
    target: item.target,
    version: item.version,
    options: item.options,
    enabled: item.active,
  }
}

function sameOptions(a: Registration["options"], b: Registration["options"]) {
  return isDeepEqual(a ?? null, b ?? null)
}

function sameGeneration(
  a: Pick<Registration, "version" | "options"> | undefined,
  b: Pick<Registration, "version" | "options">,
) {
  return a?.version === b.version && sameOptions(a.options, b.options)
}

function snapshotOptions(options: Registration["options"]) {
  return options ? structuredClone(unwrap(options)) : undefined
}

function isPlugin(value: unknown): value is Plugin.Definition {
  return (
    typeof value === "object" &&
    value !== null &&
    "id" in value &&
    typeof value.id === "string" &&
    value.id.length > 0 &&
    "setup" in value &&
    typeof value.setup === "function"
  )
}

export function usePlugin() {
  const value = useContext(PluginContext)
  if (!value) throw new Error("PluginProvider is missing")
  return value
}

import { readdir, stat } from "node:fs/promises"
import path from "node:path"
import { localSource } from "@opencode/plugin/source"
import { isMissingPath, localProjectDirectory, projectConfigDirectories } from "../util/config-directories"

export { localSource }

export async function localPluginDirectories(cwd: string, configDirectory: string) {
  const projectDirectory = await localProjectDirectory(cwd)
  const projectConfig = path.join(projectDirectory, ".opencode")
  const directories = [configDirectory, ...projectConfigDirectories(projectDirectory, cwd)]
  const exists = await Promise.all(
    directories.map(async (directory) => {
      if (directory === configDirectory || directory === projectConfig) return true
      return await stat(directory).then(
        (info) => info.isDirectory(),
        (error) => (isMissingPath(error) ? false : Promise.reject(error)),
      )
    }),
  )
  return directories.filter((_, index) => exists[index]).map((directory) => path.join(directory, "plugins"))
}

export async function discoverPluginTargets(directories: string[]) {
  return (
    await Promise.all(
      directories.map(async (directory) => {
        const entries = await readdir(directory, { withFileTypes: true }).catch((error: unknown) => {
          if (isMissingPath(error)) return []
          return Promise.reject(error)
        })
        return (
          await Promise.all(
            entries
              .filter((entry) => entry.isDirectory() || entry.isSymbolicLink())
              .sort((a, b) => a.name.localeCompare(b.name))
              .map(async (entry): Promise<string | undefined> => {
                const plugin = path.join(directory, entry.name)
                const isDirectory =
                  entry.isDirectory() ||
                  (await stat(plugin).then(
                    (info) => info.isDirectory(),
                    (error) => (isMissingPath(error) ? false : Promise.reject(error)),
                  ))
                if (!isDirectory) return undefined
                return plugin
              }),
          )
        ).filter((entry): entry is string => entry !== undefined)
      }),
    )
  ).flat()
}

export function mergePluginTargets<const Target extends { readonly entry: string | { readonly package: string } }>(
  targets: readonly Target[],
  directory: string,
) {
  return [
    ...targets
      .reduce((result, target) => {
        const value = typeof target.entry === "string" ? target.entry : target.entry.package
        return result.set(localSource(value, directory)?.href ?? value, target)
      }, new Map<string, Target>())
      .values(),
  ]
}

import { createMarkdownCodeBlockRenderer, type MarkdownCodeBlockRenderer } from "@opentui/core"
import { isShallowEqual } from "remeda"
import { createMemo } from "solid-js"

export function createMarkdownRenderer(
  sources: () => ReadonlyArray<Readonly<Record<string, MarkdownCodeBlockRenderer>>>,
) {
  // Changing renderNode makes OpenTUI destroy and rebuild every Markdown block.
  // Only invalidate it when the effective last-wins language handlers change.
  const renderers = createMemo(
    () => Object.fromEntries(sources().flatMap((source) => Object.entries(source))),
    undefined,
    { equals: isShallowEqual },
  )
  return createMemo(() =>
    Object.keys(renderers()).length === 0 ? undefined : createMarkdownCodeBlockRenderer(renderers()),
  )
}

import {
  createComponent,
  createContext,
  createMemo,
  ErrorBoundary,
  For,
  mergeProps,
  onCleanup,
  onMount,
  Show,
  useContext,
  type JSX,
  type ParentProps,
} from "solid-js"
import { isShallowEqual } from "remeda"
import type { SlotMap, SlotPath } from "@opencode/plugin/tui/context"
import type { SlotRender } from "./api"
import { contains, emptySlotted, type Claim } from "./structure"
import { useRoute } from "../context/route"
import { useToast } from "../ui/toast"
import { errorMessage } from "../util/error"
import { usePlugin } from "./context"

// Contain render-time plugin crashes: a throwing slot or route must not take
// down the app or the other plugins. The crash surfaces as one error toast.
function PluginBoundary(props: ParentProps<{ id: string; where: string }>) {
  const toast = useToast()
  return (
    <ErrorBoundary
      fallback={(error) => {
        // One toast per crash: onMount is untracked, so prop updates while
        // the boundary is latched cannot re-toast.
        onMount(() =>
          toast.show({
            variant: "error",
            title: "Plugin",
            message: `${props.id} crashed in ${props.where}: ${errorMessage(error)}`,
          }),
        )
        return null
      }}
    >
      {props.children}
    </ErrorBoundary>
  )
}

export function PluginRoute(props: { readonly fallback: (id: string, name: string) => JSX.Element }) {
  const plugins = usePlugin()
  const route = useRoute()
  const current = createMemo(() => {
    if (route.data.type !== "plugin") return
    return {
      id: route.data.id,
      name: route.data.name,
      render: plugins.route(route.data.id, route.data.name),
      data: route.data.data,
    }
  })
  return (
    // Keyed so navigation or a hot reload recreates the boundary; otherwise
    // one crash would latch every future plugin route into the fallback.
    <Show keyed when={current()}>
      {(item) => (
        <PluginBoundary id={item.id} where="route">
          {item.render ? createComponent(item.render, { data: item.data }) : props.fallback(item.id, item.name)}
        </PluginBoundary>
      )}
    </Show>
  )
}

// The nearest enclosing slot's path. Root slots mount outside any provider.
const SlotParent = createContext<string>()

// `input` is required exactly when the path publishes a non-empty input.
type SlotProps<Path extends SlotPath> = ParentProps<{ readonly path: Path }> &
  ({} extends SlotMap[Path] ? { readonly input?: SlotMap[Path] } : { readonly input: SlotMap[Path] })

// One named boundary of the host UI's slot tree. The host's own content are
// the children; every active plugin claim targeting this path resolves into
// siblings around it, contributions inside it, or one takeover of it.
// Placement policy lives in resolveSlots; this component only renders its
// own path's buckets.
export function Slot<Path extends SlotPath>(props: SlotProps<Path>) {
  const plugins = usePlugin()
  // A slot's path is its identity for the whole mount; instances are
  // reference-counted so the same path may be mounted several times (one
  // composer footer per session tab).
  const path = props.path
  // Paths are declared, not inferred: nesting under the wrong parent would
  // silently publish a mislocated public path, so containment fails loudly
  // at mount. Only host code can trip this — plugins cannot mount slots.
  const parent = useContext(SlotParent)
  if (parent !== undefined && !contains(parent, path)) {
    throw new Error(`Slot "${path}" is mounted inside "${parent}" but its path does not extend it`)
  }
  onCleanup(plugins.slots.register(path))
  const input = () => (props as { readonly input?: SlotMap[Path] }).input ?? ({} as SlotMap[Path])
  const slotted = createMemo(
    () => plugins.slots.resolved().slotted.get(path) ?? emptySlotted<SlotRender>(),
    emptySlotted<SlotRender>(),
    // Claim objects are reference-stable across resolutions, so a bucketwise
    // comparison makes a claim change elsewhere in the tree a no-op here.
    {
      equals: (a, b) =>
        isShallowEqual(a.before, b.before) &&
        isShallowEqual(a.prepend, b.prepend) &&
        isShallowEqual(a.append, b.append) &&
        isShallowEqual(a.after, b.after) &&
        a.replace === b.replace,
    },
  )
  // Component semantics: the render body runs once and untracked, so state
  // created inside is stable while the slot input stays reactive through the
  // merged getter.
  const contribution = (claim: Claim<SlotRender>) => (
    <PluginBoundary id={claim.plugin} where={`slot ${path}`}>
      {createComponent(claim.render, mergeProps(input))}
    </PluginBoundary>
  )
  return (
    <>
      <For each={slotted().before}>{contribution}</For>
      {/* before/after are siblings outside the boundary, so outside the provider. */}
      <SlotParent.Provider value={path}>
        <Show
          keyed
          when={slotted().replace}
          fallback={
            <>
              <For each={slotted().prepend}>{contribution}</For>
              {props.children}
              <For each={slotted().append}>{contribution}</For>
            </>
          }
        >
          {contribution}
        </Show>
      </SlotParent.Provider>
      <For each={slotted().after}>{contribution}</For>
    </>
  )
}

// Pure resolution of the slot tree: the mounted slot paths plus plugin claims
// in, per-path placement buckets plus diagnostics out. No solid, no I/O —
// every policy rule (replacement takeover, hierarchy-beats-timeline,
// last-enabled-wins, missing-target degradation) is testable as a data
// transform.

export type PlacementKind = "prepend" | "append" | "before" | "after" | "replace"

// Normalized from the public SlotClaim shape by the plugin API: exactly one
// placement kind, the target path erased to a string so the resolver stays
// independent of the slot map.
export type Placement = { readonly kind: PlacementKind; readonly target: string }

// One plugin's registered slot claim, in enable order within the claims array.
export type Claim<Render> = {
  readonly key: string
  readonly plugin: string
  readonly placement: Placement
  readonly render: Render
}

// Everything one mounted slot renders besides its own children: siblings
// around the boundary, contributions inside it, and at most one takeover.
export type Slotted<Render> = {
  readonly before: ReadonlyArray<Claim<Render>>
  readonly prepend: ReadonlyArray<Claim<Render>>
  readonly append: ReadonlyArray<Claim<Render>>
  readonly after: ReadonlyArray<Claim<Render>>
  readonly replace?: Claim<Render>
}

export type Suppressed<Render> = {
  readonly claim: Claim<Render>
  // The winning claim for a conflict or boundary suppression; absent when a
  // replacement's target no longer exists (missing replacements never degrade).
  readonly by?: Claim<Render>
}

export type Degraded<Render> = {
  readonly claim: Claim<Render>
  // The surviving ancestor path the claim was appended to.
  readonly to: string
}

const EMPTY: Slotted<never> = { before: [], prepend: [], append: [], after: [] }

export function emptySlotted<Render>(): Slotted<Render> {
  return EMPTY
}

// The tree's one containment rule: a path contains every path it prefixes.
// Shared with the <Slot> mount assertion so the spellings cannot drift.
export function contains(ancestor: string, path: string) {
  return path.startsWith(ancestor + ".")
}

// `paths` is the set of currently mounted slot paths; `claims` is every
// active claim in plugin enable order. The result maps each targeted path to
// its placement buckets — untargeted paths are absent and render as empty.
export function resolveSlots<Render>(input: {
  readonly paths: ReadonlySet<string>
  readonly claims: ReadonlyArray<Claim<Render>>
}): {
  readonly slotted: ReadonlyMap<string, Slotted<Render>>
  readonly suppressed: ReadonlyArray<Suppressed<Render>>
  readonly degraded: ReadonlyArray<Degraded<Render>>
} {
  const suppressed: Suppressed<Render>[] = []
  const degraded: Degraded<Render>[] = []

  // Pass 1 — replacement boundaries. Per target the last-enabled claim wins;
  // then an accepted boundary swallows every replacement strictly inside it,
  // regardless of enable order (hierarchy beats timeline).
  const winners = new Map<string, Claim<Render>>()
  for (const claim of input.claims) {
    if (claim.placement.kind !== "replace") continue
    if (!input.paths.has(claim.placement.target)) {
      suppressed.push({ claim })
      continue
    }
    const prior = winners.get(claim.placement.target)
    if (prior) suppressed.push({ claim: prior, by: claim })
    winners.set(claim.placement.target, claim)
  }
  const boundaries = new Map<string, Claim<Render>>()
  const containing = (path: string) => {
    for (const [boundary, winner] of boundaries) if (contains(boundary, path)) return winner
    return undefined
  }
  // Shallow boundaries first, so a nested replacement meets its container.
  for (const [path, winner] of [...winners].sort((a, b) => depth(a[0]) - depth(b[0]))) {
    const outer = containing(path)
    if (outer) {
      suppressed.push({ claim: winner, by: outer })
      continue
    }
    boundaries.set(path, winner)
  }

  // Pass 2 — additive claims, in enable order. A claim whose target sits
  // inside a replaced boundary is suppressed; a claim whose target is gone
  // degrades to appending on the nearest surviving ancestor.
  const buckets = new Map<
    string,
    { before: Claim<Render>[]; prepend: Claim<Render>[]; append: Claim<Render>[]; after: Claim<Render>[] }
  >()
  const bucket = (path: string) => {
    const existing = buckets.get(path)
    if (existing) return existing
    const fresh = { before: [], prepend: [], append: [], after: [] }
    buckets.set(path, fresh)
    return fresh
  }
  for (const claim of input.claims) {
    const kind = claim.placement.kind
    if (kind === "replace") continue
    const target = claim.placement.target
    // Inside placements targeting a replaced boundary are part of its
    // contents; sibling placements on the boundary itself stay outside it.
    const inside = kind === "prepend" || kind === "append" ? boundaries.get(target) : undefined
    const outer = inside ?? containing(target)
    if (outer) {
      suppressed.push({ claim, by: outer })
      continue
    }
    if (input.paths.has(target)) {
      bucket(target)[kind].push(claim)
      continue
    }
    const ancestor = survivingAncestor(target, input.paths)
    if (ancestor === undefined) {
      suppressed.push({ claim })
      continue
    }
    // The ancestor is never a replaced boundary (containing() caught that).
    // Appending is load-bearing: a parent slot registers before its children
    // and <Slot> renders append after them, so the transient degradation
    // during a nested mount never instantiates anything.
    degraded.push({ claim, to: ancestor })
    bucket(ancestor).append.push(claim)
  }

  const slotted = new Map<string, Slotted<Render>>()
  for (const [path, lists] of buckets) slotted.set(path, lists)
  for (const [path, winner] of boundaries) slotted.set(path, { ...(buckets.get(path) ?? EMPTY), replace: winner })
  return { slotted, suppressed, degraded }
}

function depth(path: string) {
  return path.split(".").length
}

function survivingAncestor(path: string, paths: ReadonlySet<string>) {
  for (let index = path.lastIndexOf("."); index !== -1; index = path.lastIndexOf(".", index - 1)) {
    const ancestor = path.slice(0, index)
    if (paths.has(ancestor)) return ancestor
  }
  return undefined
}

import path from "path"
import { existsSync, watch } from "fs"
import { lstat, realpath, stat } from "fs/promises"

// Watch plugin sources for changes. Files are watched through their parent
// directory (editors that save by rename replace the inode, which silently
// kills a direct file watch) and filtered by basename so bursts in busy
// directories stay quiet. Symlinked files are additionally watched at their
// resolved target, since edits there emit nothing at the link's location.
// Directory targets are watched at their root only; the plugin source loader
// adds each resolved local dependency separately, including nested helpers.
// Watches are never torn down individually (a stale watch costs one fs handle and a
// spurious onChange); all die with dispose(). Missing retryable targets are
// polled until they can be armed without relying on a racy chain of ancestor
// watches.
export function createSourceWatcher(onChange: () => void) {
  const watchers = new Map<string, ReturnType<typeof watch>>()
  const watched = new Map<string, Set<string> | null>()
  const missing = new Set<string>()
  const arming = new Map<string, Promise<void>>()
  let disposed = false
  const notify = () => {
    if (!disposed) onChange()
  }
  const forget = (dir: string) => {
    watchers.get(dir)?.close()
    watchers.delete(dir)
    watched.delete(dir)
  }
  const arm = (target: string, retry: boolean) => {
    const active = arming.get(target)
    if (active) return active
    const result = stat(target)
      .then((info) => {
        if (disposed) return
        const appeared = missing.delete(target)
        const dir = info.isDirectory() ? target : path.dirname(target)
        // Directories accept every filename (null); files accept their basename.
        const name = info.isDirectory() ? null : path.basename(target)
        const existing = watched.get(dir)
        if (existing !== undefined) {
          if (name === null) watched.set(dir, null)
          else existing?.add(name)
          if (appeared) notify()
          return
        }
        const watcher = watch(dir, (_event, filename) => {
          // A replaced directory keeps this watcher on the dead inode (Linux
          // emits rename, not error); forget it so a later add() re-arms on
          // the recreated path, and still schedule so reconcile runs now.
          if (!existsSync(dir)) {
            forget(dir)
            notify()
            return
          }
          // A null filename (platform-dependent) always schedules.
          const accept = watched.get(dir)
          if (filename && accept && !accept.has(filename.toString())) return
          notify()
        })
        watched.set(dir, name === null ? null : new Set([name]))
        // Reconcile after watcher errors so every source is re-added and any
        // temporarily unavailable target moves into the polling set.
        watcher.on("error", () => {
          forget(dir)
          notify()
        })
        watchers.set(dir, watcher)
        if (appeared) notify()
      })
      .catch((error: unknown) => {
        if (!disposed && retry && isMissing(error)) missing.add(target)
      })
      .finally(() => arming.delete(target))
    arming.set(target, result)
    return result
  }
  const add = async (target: string, retry: boolean) => {
    await arm(target, retry)
    // A symlinked source receives edits at its resolved target.
    await lstat(target)
      .then((info) => {
        if (!info.isSymbolicLink()) return
        return realpath(target).then((target) => arm(target, retry))
      })
      .catch(() => undefined)
  }
  const dispose = () => {
    disposed = true
    clearInterval(poll)
    for (const watcher of watchers.values()) watcher.close()
    watchers.clear()
    watched.clear()
    missing.clear()
  }
  const poll = setInterval(() => missing.forEach((target) => arm(target, true)), 500)
  poll.unref()
  return {
    add: (target: string) => add(target, false),
    wait: (target: string) => add(target, true),
    dispose,
  }
}

function isMissing(error: unknown) {
  if (!error || typeof error !== "object") return false
  const code = "code" in error ? error.code : undefined
  return code === "ENOENT" || code === "ENOTDIR"
}

import type { PromptInput } from "@opencode/schema"

type PromptFile = PromptInput.FileAttachment
type PromptFileIdentity = Pick<PromptFile, "uri" | "name" | "description">
type ProjectedFile = Readonly<{
  data: string
  mime: string
  source: { type: string }
  name?: string
  description?: string
  mention?: { text: string }
}>

function attachmentKind(uri: string) {
  if (uri.startsWith("data:image/")) return "Image"
  if (uri.startsWith("data:application/pdf;")) return "PDF"
  return undefined
}

function attachmentMetadata(file: PromptFileIdentity) {
  return JSON.stringify([file.name ?? null, file.description ?? null])
}

function deduplicateByIdentity<T>(
  items: readonly T[],
  identity: (item: T) => { metadata: string; payload: string } | undefined,
) {
  const seen = new Map<string, Set<string>>()
  return items.filter((item) => {
    const key = identity(item)
    if (!key) return true
    const payloads = seen.get(key.metadata) ?? new Set<string>()
    if (payloads.has(key.payload)) return false
    payloads.add(key.payload)
    seen.set(key.metadata, payloads)
    return true
  })
}

export function deduplicatePromptImages(files: readonly PromptFile[] | undefined) {
  if (!files || files.length < 2) return files
  return deduplicateByIdentity(files, (file) =>
    file.uri.startsWith("data:image/") && file.mention?.text
      ? {
          metadata: JSON.stringify([file.name ?? null, file.description ?? null, file.mention.text]),
          payload: file.uri,
        }
      : undefined,
  )
}

export function preserveMentionlessPromptAttachments(
  files: readonly PromptFile[] | undefined,
  mentioned: PromptFile[],
) {
  if (!files) return mentioned
  const tracked = mentioned.values()
  return files.flatMap((file) => {
    if (!file.mention?.text) return [file]
    const next = tracked.next()
    return next.done ? [] : [next.value]
  })
}

export function deduplicateVisibleImages<T extends ProjectedFile>(files: readonly T[]) {
  return deduplicateByIdentity(files, (file) =>
    file.mime.startsWith("image/") && file.source.type === "inline" && file.mention?.text
      ? {
          metadata: JSON.stringify([file.mime, file.name ?? null, file.description ?? null, file.mention.text]),
          payload: file.data,
        }
      : undefined,
  )
}

export function promptAttachmentLabel(files: readonly PromptFile[] | undefined, file: PromptFileIdentity) {
  const kind = attachmentKind(file.uri)
  if (!kind) throw new Error(`Unsupported inline attachment: ${file.uri}`)
  const metadata = attachmentMetadata(file)
  const existing =
    kind === "Image"
      ? files?.find(
          (candidate) =>
            candidate.uri === file.uri && attachmentMetadata(candidate) === metadata && candidate.mention?.text,
        )?.mention?.text
      : undefined
  if (existing) return existing

  const pattern = new RegExp(`^\\[${kind} (\\d+)\\]$`)
  const count =
    files?.reduce((highest, candidate) => {
      const match = candidate.mention?.text.match(pattern)
      return match ? Math.max(highest, Number(match[1])) : highest
    }, 0) ?? 0
  return `[${kind} ${count + 1}]`
}

import type { Prompt, PromptInput } from "@opencode/schema"
import { Skill } from "@opencode/schema/skill"
import type { Types } from "effect"

export type EditablePromptInput = Types.DeepMutable<PromptInput.Prompt>

type ProjectedPrompt = Pick<Prompt, "text" | "files" | "agents"> & {
  readonly skills?: ReadonlyArray<{ readonly id: string; readonly mention?: PromptInput.SkillAttachment["mention"] }>
}

export function projectedPromptInput(input: ProjectedPrompt): EditablePromptInput {
  return {
    text: input.text,
    files: input.files?.map((file) => ({
      uri: file.source.type === "uri" ? file.source.uri : `data:${file.mime};base64,${file.data}`,
      name: file.name,
      description: file.description,
      mention: file.mention ? { ...file.mention } : undefined,
    })),
    agents: input.agents?.map((agent) => ({
      name: agent.name,
      mention: agent.mention ? { ...agent.mention } : undefined,
    })),
    skills: input.skills?.map((skill) => ({
      id: Skill.ID.make(skill.id),
      mention: skill.mention ? { ...skill.mention } : undefined,
    })),
  }
}

export function normalizePromptContent(content: string) {
  if (content.endsWith("\r\n")) {
    const body = content.slice(0, -2)
    return !body.includes("\n") && !body.includes("\r") ? body : content
  }

  if (content.endsWith("\n")) {
    const body = content.slice(0, -1)
    return !body.includes("\n") && !body.includes("\r") ? body : content
  }

  return content
}

import type { KeymapCommand } from "@opencode/plugin/tui/context"
import type { OpenCodeClient } from "@opencode/client"
import path from "path"
import { displaySlice, promptOffsetWidth } from "./display"
import { parseSlashHead } from "./parse"

export async function directoryAutocomplete(
  file: Pick<OpenCodeClient["file"], "list">,
  location: { directory: string },
  query: string,
  home: string,
) {
  const search = directoryAutocompleteSearch(query, location.directory, home)
  const result = await file.list({ location, path: search.directory })
  const exact = directoryAutocompleteExactValue(query, search)
  return [
    ...(exact ? [{ value: exact, absolute: search.directory }] : []),
    ...result.data
      .filter((item) => item.type === "directory")
      .map((item) => path.resolve(result.location.directory, item.path))
      .filter((absolute) => directoryAutocompleteMatches(path.basename(absolute), search.query))
      .map((absolute) => ({
        value: directoryAutocompleteResultValue(path.basename(absolute) + "/", search),
        absolute,
      })),
  ]
}

export function slashArgumentAutocomplete(
  value: string,
  offset: number,
  commands: readonly KeymapCommand[],
  autocomplete: ((command: KeymapCommand) => "directory" | undefined) | undefined,
) {
  const beforeCursor = displaySlice(value, 0, offset)
  const head = parseSlashHead(beforeCursor, /\s/)
  if (!head || head.end === beforeCursor.length) return

  const command = commands.find(
    (command) =>
      command.slash?.arguments &&
      (command.slash.name === head.name || command.slash.aliases?.includes(head.name) === true),
  )
  if (!command) return
  const type = autocomplete?.(command)
  if (!type) return

  return {
    type,
    index: promptOffsetWidth(beforeCursor.slice(0, head.end + 1)),
  }
}

export function directoryAutocompleteSearch(query: string, directory: string, home: string) {
  if (query === "~") return { directory: home, prefix: "~/", query: "" }
  if (query.startsWith("~/")) return directorySearch(query.slice(2), home, "~/")
  if (/^(?:\.\.\/)*\.\.$/.test(query))
    return { directory: path.resolve(directory, query), prefix: query + "/", query: "" }
  if (query.startsWith("/")) return directorySearch(query.slice(1), path.parse(directory).root, "/")
  return directorySearch(query, directory, "")
}

function directorySearch(query: string, root: string, prefix: string) {
  const separator = query.lastIndexOf("/")
  if (separator === -1) return { directory: root, prefix, query }
  const parent = query.slice(0, separator + 1)
  return {
    directory: path.resolve(root, parent),
    prefix: prefix + parent,
    query: query.slice(separator + 1),
  }
}

export function directoryAutocompleteResultValue(
  directory: string,
  search: ReturnType<typeof directoryAutocompleteSearch>,
) {
  return search.prefix + directory.replace(/^[\\/]+/, "")
}

export function directoryAutocompleteExactValue(value: string, search: ReturnType<typeof directoryAutocompleteSearch>) {
  if (!value || !search.prefix || search.query) return
  return value
}

export function directoryAutocompleteMatches(directory: string, query: string) {
  const value = directory.replace(/^[\\/]+/, "")
  if (!query && value.startsWith(".")) return false
  return value.toLowerCase().startsWith(query.toLowerCase())
}

export function directoryRecentValue(directory: string, home: string) {
  const relative = path.relative(home, directory)
  if (!relative) return "~"
  if (relative !== ".." && !relative.startsWith(".." + path.sep) && !path.isAbsolute(relative))
    return "~/" + relative.split(path.sep).join("/")
  return directory
}

import { useStorage } from "../context/storage"

type RecentDirectory = {
  directory: string
  usedAt: number
}

type PersistedState = {
  projects: Record<string, RecentDirectory[]>
}

export function useDirectoryRecents() {
  const [store, updateStore] = useStorage().store<PersistedState>("directory-recents", {
    initial: { projects: {} },
    key: "directory",
  })

  return {
    list(projectID: string) {
      return (store.projects[projectID] ?? []).toSorted((a, b) => b.usedAt - a.usedAt)
    },
    touch(projectID: string, directory: string) {
      void updateStore((draft) => {
        draft.projects[projectID] = [
          { directory, usedAt: Date.now() },
          ...(draft.projects[projectID] ?? []).filter((item) => item.directory !== directory),
        ].slice(0, 10)
      }).catch((error) => console.error("Failed to persist directory recents", error))
    },
    remove(projectID: string, directory: string) {
      void updateStore((draft) => {
        draft.projects[projectID] = (draft.projects[projectID] ?? []).filter((item) => item.directory !== directory)
      }).catch((error) => console.error("Failed to remove directory recent", error))
    },
  }
}

import { stringWidth } from "../util/string-width"

const graphemes = new Intl.Segmenter(undefined, { granularity: "grapheme" })

export function promptOffsetWidth(value: string) {
  let width = 0
  for (const part of graphemes.segment(value)) {
    // Textarea offsets count newlines as one position; terminal width counts them as zero.
    width += part.segment === "\n" ? 1 : stringWidth(part.segment)
  }
  return width
}

function displayOffsetIndex(value: string, offset: number) {
  if (offset <= 0) return 0

  let width = 0
  for (const part of graphemes.segment(value)) {
    const next = width + promptOffsetWidth(part.segment)
    if (next > offset) return part.index
    width = next
  }

  return value.length
}

export function displaySlice(value: string, start = 0, end = promptOffsetWidth(value)) {
  return value.slice(displayOffsetIndex(value, start), displayOffsetIndex(value, end))
}

export function displayCharAt(value: string, offset: number) {
  let width = 0
  for (const part of graphemes.segment(value)) {
    const next = width + promptOffsetWidth(part.segment)
    if (offset === width || offset < next) return part.segment
    width = next
  }
}

export function mentionTriggerIndex(value: string, offset = promptOffsetWidth(value)) {
  const text = displaySlice(value, 0, offset)
  const index = text.lastIndexOf("@")
  if (index === -1) return

  const before = index === 0 ? undefined : text[index - 1]
  const query = text.slice(index)
  if ((before === undefined || /\s/.test(before)) && !/\s/.test(query)) {
    return promptOffsetWidth(text.slice(0, index))
  }
}

export function slashTriggerIndex(value: string, offset = promptOffsetWidth(value)) {
  const text = displaySlice(value, 0, offset)
  for (let index = text.lastIndexOf("/"); index >= 0; index = text.lastIndexOf("/", index - 1)) {
    const before = index === 0 ? undefined : text[index - 1]
    const query = text.slice(index)
    if (before !== undefined && !/\s/.test(before)) continue
    if (/\s/.test(query) || query.slice(1).includes("/")) return
    return promptOffsetWidth(text.slice(0, index))
  }
}

import path from "path"
import { onMount } from "solid-js"
import { createStore } from "solid-js/store"
import { createSimpleContext } from "../context/helper"
import { useTuiPaths } from "../context/runtime"
import { appendText, readText, writeText } from "../util/persistence"

type FrecencyEntry = { path: string; frequency: number; lastOpen: number }

export const MAX_FRECENCY_ENTRIES = 1000

export function parseFrecency(text: string) {
  const latest = text
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      try {
        return JSON.parse(line) as FrecencyEntry
      } catch {
        return undefined
      }
    })
    .filter((line): line is FrecencyEntry => line !== undefined)
    .reduce<Record<string, FrecencyEntry>>((result, entry) => {
      result[entry.path] = entry
      return result
    }, {})
  return Object.values(latest)
    .sort((a, b) => b.lastOpen - a.lastOpen)
    .slice(0, MAX_FRECENCY_ENTRIES)
}

function calculateFrecency(entry?: { frequency: number; lastOpen: number }) {
  if (!entry) return 0
  return entry.frequency / (1 + (Date.now() - entry.lastOpen) / 86400000)
}

export const { use: useFrecency, provider: FrecencyProvider } = createSimpleContext({
  name: "Frecency",
  init: () => {
    const paths = useTuiPaths()
    const frecencyPath = path.join(paths.state, "frecency.jsonl")
    onMount(async () => {
      const lines = parseFrecency(await readText(frecencyPath).catch(() => ""))
      setStore(
        "data",
        Object.fromEntries(
          lines.map((entry) => [entry.path, { frequency: entry.frequency, lastOpen: entry.lastOpen }]),
        ),
      )
      if (lines.length > 0)
        writeText(frecencyPath, lines.map((entry) => JSON.stringify(entry)).join("\n") + "\n").catch(() => {})
    })

    const [store, setStore] = createStore({ data: {} as Record<string, { frequency: number; lastOpen: number }> })

    function updateFrecency(filePath: string) {
      const absolutePath = path.resolve(paths.cwd, filePath)
      const newEntry = { frequency: (store.data[absolutePath]?.frequency || 0) + 1, lastOpen: Date.now() }
      setStore("data", absolutePath, newEntry)
      appendText(frecencyPath, JSON.stringify({ path: absolutePath, ...newEntry }) + "\n").catch(() => {})

      if (Object.keys(store.data).length <= MAX_FRECENCY_ENTRIES) return
      const sorted = Object.entries(store.data)
        .sort(([, a], [, b]) => b.lastOpen - a.lastOpen)
        .slice(0, MAX_FRECENCY_ENTRIES)
      setStore("data", Object.fromEntries(sorted))
      writeText(
        frecencyPath,
        sorted.map(([entryPath, entry]) => JSON.stringify({ path: entryPath, ...entry })).join("\n") + "\n",
      ).catch(() => {})
    }

    return {
      getFrecency: (filePath: string) => calculateFrecency(store.data[path.resolve(paths.cwd, filePath)]),
      updateFrecency,
      data: () => store.data,
    }
  },
})

import path from "path"
import { onMount } from "solid-js"
import { createStore, produce, unwrap } from "solid-js/store"
import type { PromptInput } from "@opencode/schema"
import type { Types } from "effect"
import { createSimpleContext } from "../context/helper"
import { useTuiPaths } from "../context/runtime"
import { appendText, readText, writeText } from "../util/persistence"
import { promptOffsetWidth } from "./display"

export type PastedText = {
  text: string
  source: {
    start: number
    end: number
    text: string
  }
}

export type PromptInfo = Types.DeepMutable<Pick<PromptInput.Prompt, "text" | "files" | "agents" | "skills">> & {
  pasted: PastedText[]
  mode?: "normal" | "shell"
}

export type PromptPartRef = {
  type: "file" | "agent" | "skill" | "pasted"
  index: number
}

export const emptyPrompt = (): PromptInfo => ({ text: "", files: [], agents: [], skills: [], pasted: [] })

// Part ranges are textarea offsets, so shift by display width rather than string length.
export function appendPrompt(prompt: PromptInfo, following: PromptInfo): PromptInfo {
  const text = prompt.text ? `${prompt.text}\n\n` : ""
  const offset = promptOffsetWidth(text)
  const shift = <T extends { start: number; end: number }>(range: T, by: number) => ({
    ...range,
    start: range.start + by,
    end: range.end + by,
  })
  const mentions = <T extends { mention?: { start: number; end: number } }>(
    items: T[] | undefined,
    next: T[] | undefined,
  ) => [
    ...(items ?? []).map((item) => ({ ...item, mention: item.mention && shift(item.mention, 0) })),
    ...(next ?? []).map((item) => ({ ...item, mention: item.mention && shift(item.mention, offset) })),
  ]
  return {
    text: text + following.text,
    files: mentions(prompt.files, following.files),
    agents: mentions(prompt.agents, following.agents),
    skills: mentions(prompt.skills, following.skills),
    pasted: [
      ...prompt.pasted.map((part) => ({ ...part, source: shift(part.source, 0) })),
      ...following.pasted.map((part) => ({ ...part, source: shift(part.source, offset) })),
    ],
  }
}

export const MAX_HISTORY_ENTRIES = 50

export function parsePromptHistory(text: string) {
  return text
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      try {
        return parsePromptInfo(JSON.parse(line))
      } catch {
        return undefined
      }
    })
    .filter((line): line is PromptInfo => line !== undefined)
    .slice(-MAX_HISTORY_ENTRIES)
}

export function isDuplicateEntry(previous: PromptInfo | undefined, next: PromptInfo): boolean {
  if (!previous) return false
  return JSON.stringify(previous) === JSON.stringify(next)
}

export function parsePromptInfo(value: unknown): PromptInfo | undefined {
  if (!value || typeof value !== "object") return
  const input = value as Record<string, unknown>
  if (typeof input.text !== "string" || !Array.isArray(input.pasted)) return
  return input as PromptInfo
}

export const { use: usePromptHistory, provider: PromptHistoryProvider } = createSimpleContext({
  name: "PromptHistory",
  init: () => {
    const paths = useTuiPaths()
    const historyPath = path.join(paths.state, "prompt-history.jsonl")
    onMount(async () => {
      const lines = parsePromptHistory(await readText(historyPath).catch(() => ""))
      setStore("history", lines)

      // Rewrite valid retained entries to self-heal corruption and enforce the limit.
      if (lines.length > 0)
        writeText(historyPath, lines.map((line) => JSON.stringify(line)).join("\n") + "\n").catch(() => {})
    })

    const [store, setStore] = createStore({ index: 0, history: [] as PromptInfo[] })

    return {
      move(direction: 1 | -1, input: string) {
        if (!store.history.length) return undefined
        const current = store.history.at(store.index)
        if (!current) return undefined
        if (current.text !== input && input.length) return
        const next = store.index + direction
        if (Math.abs(next) > store.history.length || next > 0) return
        setStore("index", next)
        if (next === 0) return emptyPrompt()
        return store.history.at(next)
      },
      append(item: PromptInfo) {
        const entry = structuredClone(unwrap(item))
        if (isDuplicateEntry(store.history.at(-1), entry)) {
          setStore("index", 0)
          return
        }
        let trimmed = false
        setStore(
          produce((draft) => {
            draft.history.push(entry)
            if (draft.history.length > MAX_HISTORY_ENTRIES) {
              draft.history = draft.history.slice(-MAX_HISTORY_ENTRIES)
              trimmed = true
            }
            draft.index = 0
          }),
        )

        if (trimmed) {
          writeText(historyPath, store.history.map((line) => JSON.stringify(line)).join("\n") + "\n").catch(() => {})
          return
        }
        appendText(historyPath, JSON.stringify(entry) + "\n").catch(() => {})
      },
    }
  },
})

import type { PromptInput, PromptMention } from "@opencode/schema"
import type { EditablePromptInput } from "./codec"
import { promptOffsetWidth } from "./display"
import { expandTrackedPastedText } from "./part"

type TextRange = {
  start: number
  end: number
}

type MentionItem = {
  index: number
  mention: PromptMention
}

type CandidateRange = TextRange & {
  offset: number
}

export function realignPromptMentions(
  content: string,
  mentions: readonly (PromptMention | undefined)[],
): Array<PromptMention | undefined> {
  const protectedRanges: TextRange[] = []
  const aligned = mentions.map((mention) => (mention && !mention.text ? { ...mention } : undefined))
  const groups = mentions.reduce((result, mention, index) => {
    if (!mention?.text) return result
    const group = result.get(mention.text) ?? []
    group.push({ mention, index })
    result.set(mention.text, group)
    return result
  }, new Map<string, MentionItem[]>())

  for (const [text, items] of [...groups.entries()].sort(
    ([left], [right]) => right.length - left.length || left.localeCompare(right),
  )) {
    const candidates = mentionRanges(content, text)
    const available = candidates.filter((candidate) => !protectedRanges.some((range) => overlaps(candidate, range)))
    for (const [item, candidate] of assignMentions(items, available)) {
      aligned[item.index] = {
        text,
        start: candidate.offset,
        end: candidate.offset + promptOffsetWidth(text),
      }
    }
    protectedRanges.push(...candidates)
  }

  return aligned
}

export function realignPromptInputMentions(content: string, input: PromptInput.Prompt): EditablePromptInput {
  const files = input.files ?? []
  const agents = input.agents ?? []
  const skills = input.skills ?? []
  const mentions = realignPromptMentions(content, [
    ...files.map((file) => file.mention),
    ...agents.map((agent) => agent.mention),
    ...skills.map((skill) => skill.mention),
  ])
  const align = <T extends { mention?: PromptMention }>(items: readonly T[] | undefined, offset = 0) =>
    items?.flatMap((item, index) => {
      if (!item.mention?.text) return [{ ...item, mention: item.mention ? { ...item.mention } : undefined }]
      const mention = mentions[offset + index]
      return mention ? [{ ...item, mention }] : []
    })

  return {
    text: content,
    files: align(input.files),
    agents: align(input.agents, files.length),
    skills: align(input.skills, files.length + agents.length),
  }
}

export function expandPromptInputPastedText(
  input: PromptInput.Prompt,
  pasted: readonly { text: string; source: { start: number; end: number } }[],
): EditablePromptInput {
  const ranges = pasted.map((part) => ({ ...part.source, text: part.text }))
  const shift = (mention: PromptMention | undefined) => {
    if (!mention) return
    const offset = ranges.reduce(
      (total, range) =>
        range.end <= mention.start ? total + promptOffsetWidth(range.text) - (range.end - range.start) : total,
      0,
    )
    return { ...mention, start: mention.start + offset, end: mention.end + offset }
  }

  return {
    text: expandTrackedPastedText(input.text, ranges),
    files: input.files?.map((file) => ({ ...file, mention: shift(file.mention) })),
    agents: input.agents?.map((agent) => ({ ...agent, mention: shift(agent.mention) })),
    skills: input.skills?.map((skill) => ({ ...skill, mention: shift(skill.mention) })),
  }
}

function mentionRanges(content: string, text: string): CandidateRange[] {
  const ranges: CandidateRange[] = []
  let searchFrom = 0
  while (true) {
    const start = content.indexOf(text, searchFrom)
    if (start === -1) return ranges
    ranges.push({ start, end: start + text.length, offset: promptOffsetWidth(content.slice(0, start)) })
    searchFrom = start + text.length
  }
}

function assignMentions(items: MentionItem[], candidates: CandidateRange[]) {
  const ordered = items.toSorted((left, right) => left.mention.start - right.mention.start || left.index - right.index)
  const memo = new Map<string, { matches: number; cost: number; pairs: Array<[MentionItem, CandidateRange]> }>()

  function solve(
    item: number,
    candidate: number,
  ): { matches: number; cost: number; pairs: Array<[MentionItem, CandidateRange]> } {
    if (item >= ordered.length || candidate >= candidates.length) return { matches: 0, cost: 0, pairs: [] }
    const key = `${item}:${candidate}`
    const cached = memo.get(key)
    if (cached) return cached

    const tail = solve(item + 1, candidate + 1)
    const current = ordered[item]!
    const range = candidates[candidate]!
    const matched = {
      matches: tail.matches + 1,
      cost: tail.cost + Math.abs(range.offset - current.mention.start),
      pairs: [[current, range] as [MentionItem, CandidateRange], ...tail.pairs],
    }
    const result = [matched, solve(item + 1, candidate), solve(item, candidate + 1)].reduce((best, next) => {
      if (next.matches !== best.matches) return next.matches > best.matches ? next : best
      return next.cost < best.cost ? next : best
    })
    memo.set(key, result)
    return result
  }

  return solve(0, 0).pairs
}

function overlaps(left: TextRange, right: TextRange) {
  return left.start < right.end && left.end > right.start
}

export function parseFileLineRange(input: string) {
  const hash = input.lastIndexOf("#")
  if (hash === -1) return { base: input }

  const base = input.slice(0, hash)
  const match = input.slice(hash + 1).match(/^(\d+)(?:-(\d*))?$/)
  if (!match) return { base }

  const startLine = Number(match[1])
  const endLine = match[2] && startLine < Number(match[2]) ? Number(match[2]) : undefined
  return { base, lineRange: { startLine, endLine } }
}

export function stripFileLineRange(input: string) {
  return parseFileLineRange(input).base
}

export function parseSlashHead(text: string, separator = /[ \t\n]/) {
  if (!text.startsWith("/")) return

  const end = text.slice(1).search(separator)
  if (end === -1) return { name: text.slice(1), arguments: "", end: text.length }

  const split = end + 1
  return { name: text.slice(1, split), arguments: text.slice(split + 1), end: split }
}

import { displaySlice } from "./display"

export function expandPastedTextPlaceholders(
  text: string,
  pasted: readonly { text: string; source: { text: string } }[],
) {
  return pasted.reduce((result, part) => result.replace(part.source.text, part.text), text)
}

export function expandTrackedPastedText(text: string, ranges: { start: number; end: number; text: string }[]) {
  return ranges
    .slice()
    .sort((a, b) => b.start - a.start)
    .reduce((result, part) => displaySlice(result, 0, part.start) + part.text + displaySlice(result, part.end), text)
}

import path from "path"
import { onMount } from "solid-js"
import { createStore, produce, unwrap } from "solid-js/store"
import { createSimpleContext } from "../context/helper"
import { useTuiPaths } from "../context/runtime"
import { appendText, readText, writeText } from "../util/persistence"
import { parsePromptInfo, type PromptInfo } from "./history"

export type StashEntry = {
  prompt: PromptInfo
  timestamp: number
}

export const MAX_STASH_ENTRIES = 50

export function parsePromptStash(text: string) {
  return text
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      try {
        const value = JSON.parse(line) as unknown
        if (!value || typeof value !== "object") return
        const entry = value as Record<string, unknown>
        const prompt = parsePromptInfo(entry.prompt)
        if (!prompt || typeof entry.timestamp !== "number") return
        return { prompt, timestamp: entry.timestamp }
      } catch {
        return undefined
      }
    })
    .filter((line): line is StashEntry => line !== undefined)
    .slice(-MAX_STASH_ENTRIES)
}

export const { use: usePromptStash, provider: PromptStashProvider } = createSimpleContext({
  name: "PromptStash",
  init: () => {
    const paths = useTuiPaths()
    const stashPath = path.join(paths.state, "prompt-stash.jsonl")
    onMount(async () => {
      const lines = parsePromptStash(await readText(stashPath).catch(() => ""))
      setStore("entries", lines)
      if (lines.length > 0)
        writeText(stashPath, lines.map((line) => JSON.stringify(line)).join("\n") + "\n").catch(() => {})
    })

    const [store, setStore] = createStore({ entries: [] as StashEntry[] })

    return {
      list() {
        return store.entries
      },
      push(entry: Omit<StashEntry, "timestamp">) {
        const stash = structuredClone(unwrap({ ...entry, timestamp: Date.now() }))
        let trimmed = false
        setStore(
          produce((draft) => {
            draft.entries.push(stash)
            if (draft.entries.length > MAX_STASH_ENTRIES) {
              draft.entries = draft.entries.slice(-MAX_STASH_ENTRIES)
              trimmed = true
            }
          }),
        )

        if (trimmed) {
          writeText(stashPath, store.entries.map((line) => JSON.stringify(line)).join("\n") + "\n").catch(() => {})
          return
        }
        appendText(stashPath, JSON.stringify(stash) + "\n").catch(() => {})
      },
      pop() {
        if (store.entries.length === 0) return undefined
        const entry = store.entries[store.entries.length - 1]
        setStore(produce((draft) => void draft.entries.pop()))
        writeText(
          stashPath,
          store.entries.length > 0 ? store.entries.map((line) => JSON.stringify(line)).join("\n") + "\n" : "",
        ).catch(() => {})
        return entry
      },
      remove(index: number) {
        if (index < 0 || index >= store.entries.length) return
        setStore(produce((draft) => void draft.entries.splice(index, 1)))
        writeText(
          stashPath,
          store.entries.length > 0 ? store.entries.map((line) => JSON.stringify(line)).join("\n") + "\n" : "",
        ).catch(() => {})
      },
    }
  },
})

import type { EditorTraits } from "@opentui/core"

export type PromptMode = "normal" | "shell"

export interface PromptTraitsInput {
  mode: PromptMode
  autocompleteVisible: boolean
}

export type PromptTraits = EditorTraits & {
  owner: "opencode"
  role: "prompt"
}

/** The managed textarea keymap owns `suspend`; these traits only describe capture and status. */
export function computePromptTraits(input: PromptTraitsInput): PromptTraits {
  const capture =
    input.mode === "normal"
      ? input.autocompleteVisible
        ? (["escape", "navigate", "submit", "tab"] as const)
        : (["tab"] as const)
      : undefined
  return {
    capture,
    status: input.mode === "shell" ? "SHELL" : undefined,
    owner: "opencode",
    role: "prompt",
  }
}

