export function Home() {
  const route = useRouteData("home")
  const promptRef = usePromptRef()
  const [ref, setRef] = createSignal<PromptRef | undefined>()
  const args = useArgs()
  const local = useLocal()
  const editor = useEditorContext()
  const data = useData()
  const location = useLocation()
  const dimensions = useTerminalDimensions()
  const [logoWidth, setLogoWidth] = createSignal(0)
  // Global MCP elicitations can arrive without a session route, so keep them reachable from Home.
  const currentLocation = () => route.location ?? data.location.default()
  const forms = createMemo(() => data.session.form.list("global", currentLocation()) ?? [])
  let sent = false

  // Track only the route location and (when absent) the default location; location.set
  // reads other signals internally and tracking them would re-assert the route location
  // after the user overrides it with /cd.
  createEffect(() => {
    const target = currentLocation()
    untrack(() => location.set(target))
  })

  onMount(() => {
    editor.clearSelection()
  })

  const bind = (r: PromptRef | undefined) => {
    setRef(r)
    promptRef.set(r)
    if (once || !r || route.prompt || !args.prompt) return
    r.set({ text: args.prompt, files: [], agents: [], pasted: [] })
    once = true
  }

  createEffect(() => {
    const composer = ref()
    const prompt = route.prompt
    if (!composer || prompt?.text === undefined) return
    untrack(() => composer.set(prompt))
  })

  // Wait for everything submit needs before auto-submitting --prompt; it runs once.
  createEffect(() => {
    const r = ref()
    if (sent) return
    if (!r) return
    if (!local.model.ready || !local.model.catalogReady) return
    if (!local.agent.current() || !local.model.current()) return
    if (!args.prompt) return
    if (r.current.text !== args.prompt) return
    sent = true
    r.submit()
  })

  return (
    <>
      <box
        flexGrow={1}
        alignItems="center"
        paddingLeft={dimensions().width < 44 ? 1 : 2}
        paddingRight={dimensions().width < 44 ? 1 : 2}
      >
        <box flexGrow={1} minHeight={0} />
        <box height={3} minHeight={0} flexShrink={1} />
        <box
          flexShrink={0}
          onSizeChange={function () {
            setLogoWidth(this.width)
          }}
        >
          <Logo />
        </box>
        <box height={1} flexShrink={0} />
        <UpdateNotification width={logoWidth()} />
        <box width="100%" maxWidth={75} zIndex={1000} paddingTop={1} flexShrink={0} position="relative">
          <Prompt ref={bind} placeholders={placeholder} disabled={forms().length > 0} />
        </box>
        <box flexGrow={1} minHeight={0} />
      </box>
      <box width="100%" flexShrink={0}>
        <Slot path="home.footer" />
      </box>
      <Show when={forms()[0]?.id} keyed>
        {(_) => {
          const form = forms()[0]
          return form ? (
            <box position="absolute" zIndex={2000} left={0} right={0} bottom={1} paddingLeft={2} paddingRight={2}>
              <box width="100%">
                <FormPrompt form={form} />
              </box>
            </box>
          ) : null
        }}
      </Show>
    </>
  )
}

function UpdateNotification(props: { width: number }) {
  const update = useUpdateNotification()
  const exit = useExit()
  const theme = useTheme()
  const [hovered, setHovered] = createSignal(false)
  const backdrop = () => (hovered() ? theme.background.action.primary.hovered : theme.background.base)
  createEffect(() => {
    update.notification()
    setHovered(false)
  })

  return (
    <Show when={update.notification()} keyed>
      {(state) => {
        const remote = state.source === "server" && state.remote
        return (
          <Show when={!remote || state.type === "available"}>
            <box
              flexShrink={0}
              flexDirection="row"
              justifyContent="center"
              width={props.width}
              maxWidth="100%"
              gap={1}
              backgroundColor={hovered() ? theme.background.action.primary.hovered : undefined}
              onMouseOver={() => setHovered(true)}
              onMouseOut={() => setHovered(false)}
              onMouseUp={() => {
                if (remote) return update.dismiss()
                if (state.type === "installed") return exit()
                update.open?.("notification")
              }}
            >
              <FadeInText fg={theme.text.muted} backdrop={backdrop()}>
                <Show when={!remote}>
                  <span style={{ fg: theme.text.action.primary.selected }}>
                    {state.type === "installed" ? "/exit" : "/update"}
                  </span>
                </Show>
                {remote
                  ? "remote server update available"
                  : state.type === "installed"
                    ? ` restart to use v${state.version}`
                    : ` to install v${state.version}`}
              </FadeInText>
            </box>
          </Show>
        )
      }}
    </Show>
  )
}

import type {
  SessionMessageAssistant,
  SessionMessageAssistantReasoning,
  SessionMessageAssistantTool,
  SessionMessageInfo,
} from "@opencode/client"
import { canonicalToolName, executeCalls } from "../../util/tool-display"
import { visitEntries } from "./anchor-view"
import { instructionPaths, type PartRef, type SessionEntry, type SessionNode } from "./grouping/session"
import { reasoningContent } from "./message-parts"
import { resolvePart } from "./rows"

type Item = {
  message: SessionMessageAssistant
  part: SessionMessageAssistantReasoning | SessionMessageAssistantTool
}

/**
 * Summary for an activity group's subtree; permission-blocked tools are left out.
 * Until something finishes, the label is the first running item's status, e.g. "Running command…".
 */
export function summarizeActivity(
  node: Extract<SessionNode, { type: "group" }>,
  message: (messageID: string) => SessionMessageInfo | undefined,
  pending: readonly PartRef[],
  closed: boolean,
) {
  const entries: SessionEntry[] = []
  visitEntries(node.children, (entry) => entries.push(entry))
  const items = entries.flatMap((entry) => {
    if (entry.type !== "part") return []
    if (pending.some((ref) => ref.messageID === entry.ref.messageID && ref.partID === entry.ref.partID)) return []
    const item = message(entry.ref.messageID)
    if (item?.type !== "assistant") return []
    const part = resolvePart(item, entry.ref.partID)
    return part?.type === "reasoning" || part?.type === "tool" ? [{ entry, message: item, part }] : []
  })
  const files = new Set(
    entries.flatMap((entry) => (entry.type === "message" ? instructionPaths(message(entry.messageID)) : [])),
  )
  const summary = activitySummary(items, files.size, closed)
  const current = items.find((item) => isActive(item, closed))
  return { ...summary, label: summary.label || (current ? busyLabel(current.part) : "") }
}

/** Status for a running item, independent of its details, so it doesn't flicker as they arrive. */
export function busyLabel(part: Item["part"]) {
  if (part.type === "reasoning") return "Thinking…"
  const name = canonicalToolName(part.name)
  const noun = name === "shell" ? "command" : name === "execute" ? "code" : name
  return `${part.state.status === "streaming" ? "Preparing" : "Running"} ${noun}…`
}

/**
 * Low verbosity's activity summary, e.g. "3 commands, 1 edit, 2 thoughts, 4 reads".
 * The label counts only finished work; running items are reported through `active`.
 * Code-mode `execute` counts its finished nested calls rather than itself.
 * Instructions count distinct loaded files, matching the instruction subgroup.
 * Once a later row closes the group, its thoughts count as finished, as in Medium.
 */
export function activitySummary(items: readonly Item[], instructions: number, closed = false) {
  const counts = { command: 0, edit: 0, thought: 0, read: 0, tool: 0, instruction: instructions }
  items.forEach((item) => {
    if (item.part.type === "reasoning") {
      // Redacted-only reasoning renders nothing, so it isn't a visible thought.
      if (!isActive(item, closed) && reasoningContent(item.part)) counts.thought++
      return
    }
    const name = canonicalToolName(item.part.name)
    if (name === "execute") {
      const calls = executeCalls(
        item.part.state.status === "streaming" ? undefined : item.part.state.metadata?.toolCalls,
      ).filter((call) => call.status !== "running")
      calls.forEach((call) => {
        if (canonicalToolName(call.tool) === "read") counts.read++
        else counts.tool++
      })
      // With no finished nested calls to count, a finished execute counts as itself.
      if (calls.length === 0 && !isActive(item, closed)) counts.tool++
      return
    }
    if (isActive(item, closed)) return
    if (name === "shell") counts.command++
    else if (name === "read") counts.read++
    else if (name === "edit" || name === "write" || name === "patch") counts.edit++
    else counts.tool++
  })
  return {
    label: Object.entries(counts)
      .filter(([, count]) => count > 0)
      .map(([name, count]) => `${count} ${name}${count === 1 ? "" : "s"}`)
      .join(", "),
    active: items.some((item) => isActive(item, closed)),
  }
}

function isActive(item: Item, closed: boolean) {
  if (item.part.type === "reasoning")
    return !closed && item.part.time?.completed === undefined && item.message.time.completed === undefined
  return item.part.state.status === "streaming" || item.part.state.status === "running"
}

import { createEffect, createSignal, onCleanup, type Accessor } from "solid-js"
import type { BoxRenderable } from "@opentui/core"
import type { JSX } from "@opentui/solid"
import type { SessionEntry, SessionNode } from "./grouping/session"
import { entryRef } from "./anchors"
import { use } from "./render-context"

export function visitEntries(nodes: readonly SessionNode[], visit: (entry: SessionEntry) => void) {
  nodes.forEach((node) => {
    if (node.type === "entry") visit(node.entry)
    if (node.type === "group") visitEntries(node.children, visit)
  })
}

export function useEntryAnchor(props: {
  entry: Accessor<SessionEntry | undefined>
  node: Accessor<BoxRenderable | undefined>
}) {
  const ctx = use()
  createEffect(() => {
    const entry = props.entry()
    const node = props.node()
    const ref = entry && entryRef(entry)
    if (!ref || !node) return
    onCleanup(ctx.anchors.register({ target: { type: "part", ref }, node }))
  })
}

export function EntryAnchor(props: { entry: SessionEntry; children: JSX.Element; marginTop?: number }) {
  const [node, setNode] = createSignal<BoxRenderable>()
  useEntryAnchor({ entry: () => props.entry, node })
  return (
    <box ref={setNode} marginTop={props.marginTop} flexShrink={0}>
      {props.children}
    </box>
  )
}

export function GroupAnchor(props: { groupID: string | undefined; active: boolean; children: JSX.Element }) {
  const ctx = use()
  const [node, setNode] = createSignal<BoxRenderable>()
  createEffect(() => {
    const target = node()
    const groupID = props.groupID
    if (!target || !groupID || !props.active) return
    onCleanup(ctx.anchors.register({ target: { type: "group", groupID }, node: target }))
  })
  return (
    <box ref={setNode} flexDirection="column" flexShrink={0}>
      {props.children}
    </box>
  )
}

import type { Renderable } from "@opentui/core"
import type { PartRef, SessionEntry, SessionNode } from "./grouping/session"

export type AnchorTarget = { type: "part"; ref: PartRef } | { type: "group"; groupID: string }

type Anchor = {
  target: AnchorTarget
  node: Pick<Renderable, "y" | "height" | "isDestroyed">
}

export function anchorKey(target: AnchorTarget) {
  return target.type === "part"
    ? JSON.stringify(["part", target.ref.messageID, target.ref.partID])
    : JSON.stringify(["group", target.groupID])
}

/** Whole non-assistant messages have one canonical UI body part. Derived
 * footer/usage rows use the preceding entry as their scroll reference. */
export function entryRef(entry: SessionEntry): PartRef | undefined {
  // Saved identities must not follow an in-place Solid store reconciliation.
  if (entry.type === "part") return { messageID: entry.ref.messageID, partID: entry.ref.partID }
  if (entry.type === "message") return { messageID: entry.messageID, partID: "message" }
}

export function groupID(node: Extract<SessionNode, { type: "group" }>, level: number) {
  const ref = firstRef(node.children)
  return ref && JSON.stringify([ref.messageID, ref.partID, node.kind, level])
}

function firstRef(nodes: readonly SessionNode[]): PartRef | undefined {
  for (const node of nodes) {
    const ref = node.type === "entry" ? entryRef(node.entry) : firstRef(node.children)
    if (ref) return ref
  }
}

export function containsAnchor(
  node: SessionEntry | Extract<SessionNode, { type: "group" }>,
  target: AnchorTarget,
  level = 0,
): boolean {
  if (node.type === "group") {
    if (target.type === "group" && groupID(node, level) === target.groupID) return true
    return node.children.some((child) =>
      containsAnchor(child.type === "entry" ? child.entry : child, target, level + 1),
    )
  }
  const ref = entryRef(node)
  return target.type === "part" && ref?.messageID === target.ref.messageID && ref.partID === target.ref.partID
}

/** Only mounted parts and actual group headers register. Geometry stays in OpenTUI. */
export function createTimelineAnchors() {
  const entries = new Map<string, Anchor>()
  const list = () =>
    [...entries.values()]
      .filter((anchor) => !anchor.node.isDestroyed && anchor.node.height > 0)
      .sort((a, b) => a.node.y - b.node.y)
  return {
    register(anchor: Anchor) {
      const key = anchorKey(anchor.target)
      entries.set(key, anchor)
      return () => {
        if (entries.get(key) === anchor) entries.delete(key)
      }
    },
    get(target: AnchorTarget) {
      const anchor = entries.get(anchorKey(target))
      return anchor && !anchor.node.isDestroyed && anchor.node.height > 0 ? anchor : undefined
    },
    forMessage(messageID: string) {
      return list().find((anchor) => anchor.target.type === "part" && anchor.target.ref.messageID === messageID)
    },
    messagePositions() {
      const seen = new Set<string>()
      return list().flatMap((anchor) => {
        if (anchor.target.type !== "part" || seen.has(anchor.target.ref.messageID)) return []
        const id = anchor.target.ref.messageID
        seen.add(id)
        return [{ id, y: anchor.node.y }]
      })
    },
    list,
  }
}

import { createContext, useContext } from "solid-js"

export interface ComposerHint {
  label: string
  shortcut: string
}

export interface ComposerTab {
  id: string
  label: string
  hints?: () => ComposerHint[]
}

export const ComposerContext = createContext<{
  register: (tab: ComposerTab) => () => void
  active: (id: string) => boolean
  close: () => void
}>()

export function useComposerTab() {
  const ctx = useContext(ComposerContext)
  if (!ctx) throw new Error("useComposerTab must be used within a Composer")
  return ctx
}

import { createEffect, createMemo, For, onCleanup, Show } from "solid-js"
import { createStore } from "solid-js/store"
import { TextAttributes } from "@opentui/core"
import { useTheme } from "../../../context/theme"
import { SplitBorder } from "../../../ui/border"
import { Keymap } from "../../../context/keymap"
import { SubagentsTab } from "./subagents-tab"
import { ShellTab } from "./shell-tab"
import { TerminalsTab } from "./terminals-tab"
import { ComposerContext, type ComposerTab } from "./context"

export type ComposerProps = {
  sessionID: string
  open: boolean
  defaultTab?: string
  onClose?: () => void
  terminals?: boolean
  visibleTerminalID?: string
}

export function Composer(props: ComposerProps) {
  const theme = useTheme()

  const [store, setStore] = createStore({
    tabs: {} as Record<string, ComposerTab>,
    active: "",
  })

  const tabList = createMemo(() => Object.values(store.tabs))
  const activeTab = createMemo(() => tabList().find((t) => t.id === store.active))
  const footerHints = createMemo(() => activeTab()?.hints?.() ?? [])

  // Set active tab when opened
  createEffect(() => {
    if (!props.open) return
    const tabs = tabList()
    if (tabs.length === 0) return
    const match = props.defaultTab && tabs.find((t) => t.id === props.defaultTab)
    setStore("active", match ? match.id : tabs[0].id)
  })

  function close() {
    props.onClose?.()
  }

  const ctx = {
    register(tab: ComposerTab) {
      setStore("tabs", tab.id, tab)
      if (!store.active) setStore("active", tab.id)
      return () => setStore("tabs", tab.id, undefined!)
    },
    active(id: string) {
      return props.open && store.active === id
    },
    close,
  }

  const keymap = Keymap.use()
  createEffect(() => {
    if (!props.open) return
    const popMode = keymap.mode.push("composer")
    onCleanup(popMode)
  })

  const switchTab = (dir: number) => {
    const tabs = tabList()
    if (tabs.length <= 1) return
    const idx = tabs.findIndex((t) => t.id === store.active)
    setStore("active", tabs[(idx + dir + tabs.length) % tabs.length].id)
  }

  Keymap.createLayer(() => ({
    mode: "composer",
    enabled: () => props.open,
    priority: 1,
    commands: [
      { bind: "left", title: "Previous tab", group: "Composer", run: () => switchTab(-1) },
      { bind: "right", title: "Next tab", group: "Composer", run: () => switchTab(1) },
      { bind: "escape", title: "Close composer", group: "Composer", run: close },
      { bind: "ctrl+c", title: "Close composer", group: "Composer", run: close },
    ],
  }))

  return (
    <ComposerContext.Provider value={ctx}>
      <box flexShrink={0} visible={props.open}>
        <box
          {...SplitBorder}
          border={["left"]}
          borderColor={theme.border.base}
          backgroundColor={theme.background.raised.base}
          paddingLeft={1}
          paddingRight={2}
          paddingTop={1}
          paddingBottom={1}
        >
          <box gap={1}>
            <box flexDirection="row" justifyContent="space-between" paddingLeft={1}>
              <Show
                when={tabList().length > 1}
                fallback={
                  <text fg={theme.text.base} attributes={TextAttributes.BOLD}>
                    {tabList()[0]?.label ?? ""}
                  </text>
                }
              >
                <box flexDirection="row" gap={2}>
                  <For each={tabList()}>
                    {(t) => {
                      const isActive = createMemo(() => store.active === t.id)
                      return (
                        <text
                          fg={isActive() ? theme.text.base : theme.text.muted}
                          attributes={isActive() ? TextAttributes.BOLD : undefined}
                        >
                          {t.label}
                        </text>
                      )
                    }}
                  </For>
                </box>
              </Show>
              <text fg={theme.text.muted} onMouseUp={close}>
                esc
              </text>
            </box>
            <SubagentsTab sessionID={props.sessionID} />
            <ShellTab sessionID={props.sessionID} />
            <Show when={props.terminals}>
              <TerminalsTab sessionID={props.sessionID} visibleTerminalID={props.visibleTerminalID} />
            </Show>
            <box flexDirection="row" gap={2} paddingLeft={1} flexShrink={0}>
              <For each={footerHints()}>
                {(hint) => (
                  <text>
                    <span style={{ fg: theme.text.base }}>
                      <b>{hint.label}</b>{" "}
                    </span>
                    <span style={{ fg: theme.text.muted }}>{hint.shortcut}</span>
                  </text>
                )}
              </For>
              <Show when={tabList().length > 1}>
                <text>
                  <span style={{ fg: theme.text.base }}>
                    <b>tabs</b>{" "}
                  </span>
                  <span style={{ fg: theme.text.muted }}>←/→</span>
                </text>
              </Show>
            </box>
          </box>
        </box>
      </box>
    </ComposerContext.Provider>
  )
}

import { createMemo, For, Show, createEffect, onMount, onCleanup } from "solid-js"
import { createStore } from "solid-js/store"
import { TextAttributes, ScrollBoxRenderable } from "@opentui/core"
import { useData } from "../../../context/data"
import { useClient } from "../../../context/client"
import { useTheme } from "../../../context/theme"
import { Keymap } from "../../../context/keymap"
import { useComposerTab } from "./context"
import { useDialog } from "../../../ui/dialog"
import { DialogShellOutput } from "../../../component/dialog-shell-output"

export function ShellTab(props: { sessionID: string }) {
  const data = useData()
  const client = useClient()
  const theme = useTheme()
  const composer = useComposerTab()
  const shortcuts = Keymap.useShortcuts()
  const dialog = useDialog()

  const entries = createMemo(() =>
    data.shell.listBySession(props.sessionID).filter((shell) => shell.status === "running"),
  )

  const [store, setStore] = createStore({ selected: 0 })
  let scroll: ScrollBoxRenderable | undefined

  const selectedEntry = createMemo(() => entries()[store.selected])

  const open = () => {
    const entry = selectedEntry()
    if (entry) dialog.replace(() => <DialogShellOutput shell={entry} location={entry.location} />)
  }

  createEffect(() => {
    if (store.selected >= entries().length) setStore("selected", Math.max(0, entries().length - 1))
  })

  createEffect(() => {
    if (!scroll) return
    const target = scroll.getChildren()[store.selected]
    if (!target) return
    const y = target.y - scroll.y
    if (y >= scroll.height || y < 0) {
      const center = Math.floor(scroll.height / 2)
      scroll.scrollBy(y - center)
    }
  })

  onMount(() => {
    const cleanup = composer.register({
      id: "shell",
      label: "Shell",
      hints: () =>
        selectedEntry()
          ? [
              { label: "output", shortcut: shortcuts.get("composer.shell.select") ?? "" },
              { label: "kill", shortcut: shortcuts.get("composer.shell.kill") ?? "" },
            ]
          : [],
    })
    onCleanup(cleanup)
  })

  Keymap.createLayer(() => ({
    mode: "composer",
    enabled: () => composer.active("shell"),
    priority: 1,
    commands: [
      {
        id: "composer.shell.up",
        title: "Previous shell",
        group: "Composer",
        run() {
          if (store.selected === 0) {
            composer.close()
            return
          }
          setStore("selected", (prev) => prev - 1)
        },
      },
      {
        id: "composer.shell.down",
        title: "Next shell",
        group: "Composer",
        run() {
          const list = entries()
          if (list.length === 0) return
          setStore("selected", (prev) => (prev + 1) % list.length)
        },
      },
      {
        id: "composer.shell.select",
        title: "View shell output",
        group: "Composer",
        run: open,
      },
      {
        id: "composer.shell.kill",
        title: "Kill shell command",
        group: "Composer",
        run() {
          const entry = selectedEntry()
          if (!entry) return
          void client.api.shell.remove({
            id: entry.id,
            location: { directory: entry.location.directory },
          })
        },
      },
    ],
  }))

  return (
    <Show when={composer.active("shell")}>
      <scrollbox scrollbarOptions={{ visible: false }} maxHeight={5} ref={(r: ScrollBoxRenderable) => (scroll = r)}>
        <Show when={entries().length > 0} fallback={<text fg={theme.text.muted}> No shell commands</text>}>
          <For each={entries()}>
            {(shell, index) => {
              const active = createMemo(() => index() === store.selected)
              return (
                <box
                  flexDirection="row"
                  paddingLeft={1}
                  paddingRight={1}
                  backgroundColor={
                    active() ? theme.background.action.primary.focused : theme.background.action.primary.base
                  }
                  onMouseMove={() => setStore("selected", index())}
                  onMouseUp={() => {
                    setStore("selected", index())
                    open()
                  }}
                >
                  <text
                    fg={active() ? theme.text.action.primary.focused : theme.text.action.primary.base}
                    attributes={active() ? TextAttributes.BOLD : undefined}
                    wrapMode="none"
                  >
                    {shell.command.split("\n", 1)[0]}
                  </text>
                </box>
              )
            }}
          </For>
        </Show>
      </scrollbox>
    </Show>
  )
}

import { createMemo, For, Show, createEffect, onMount, onCleanup } from "solid-js"
import { createStore } from "solid-js/store"
import { TextAttributes, ScrollBoxRenderable } from "@opentui/core"
import type { SessionInfo } from "@opencode/client"
import { useRoute, useRouteData } from "../../../context/route"
import { useData } from "../../../context/data"
