import { useTheme } from "../../../context/theme"
import { useStorage } from "../../../context/storage"
import { Locale } from "../../../util/locale"
import { Keymap } from "../../../context/keymap"
import { useComposerTab } from "./context"
import { withTimestampedFallback } from "@opencode/util/session-title-fallback"
import { sessionFamily } from "../../../util/session"

interface SubagentEntry {
  sessionID: string
  agent: string
  title: string
  status: string
  current: boolean
  prefix: string
}

export function SubagentsTab(props: { sessionID: string }) {
  const route = useRouteData("session")
  const data = useData()
  const client = useClient()
  const theme = useTheme()
  const navigate = useRoute().navigate
  const composer = useComposerTab()
  const shortcuts = Keymap.useShortcuts()

  const session = createMemo(() => data.session.get(props.sessionID))
  const [store, setStore] = createStore({ selected: 0 })
  // The session route remounts on navigation, so the filter lives in TUI memory and only ctrl+a changes it.
  const [filter, updateFilter] = useStorage().memory("subagents-filter", { initial: { active: true } })

  const entries = createMemo<SubagentEntry[]>(() => {
    const current = session()
    if (!current) return []

    const result = sessionFamily<SessionInfo>(data.session.list(), current.id).map(
      ({ session, prefix }): SubagentEntry => {
        const title = withTimestampedFallback(session)
        const agentMatch = title.match(/@(\w+) subagent/)
        return {
          sessionID: session.id,
          agent: session.agent
            ? Locale.titlecase(session.agent)
            : agentMatch
              ? Locale.titlecase(agentMatch[1])
              : "Subagent",
          title: agentMatch ? title.replace(agentMatch[0], "").trim() || title : title,
          status: data.session.status(session.id),
          current: session.id === route.sessionID,
          prefix,
        }
      },
    )

    return result.filter((entry) => (filter.active ? entry.status === "running" : entry.status !== "running"))
  })

  let selectedSessionID = ""
  let wasActive = false
  let scroll: ScrollBoxRenderable | undefined

  const selectedEntry = createMemo(() => entries()[store.selected])

  createEffect(() => {
    const active = composer.active("subagents")
    if (!active) {
      if (wasActive) {
        selectedSessionID = ""
        setStore("selected", 0)
      }
      wasActive = false
      return
    }
    const list = entries()
    if (selectedSessionID !== route.sessionID && list.length > 0) {
      const currentIdx = list.findIndex((e) => e.current)
      const next = currentIdx >= 0 ? currentIdx : 0
      selectedSessionID = route.sessionID
      setStore("selected", next)
      const scrollCurrentIntoView = () => scrollToIndex(next, true)
      scrollCurrentIntoView()
      // The remounted scrollbox finishes layout on the next frame and resets its scroll position.
      requestAnimationFrame(() => requestAnimationFrame(scrollCurrentIntoView))
    }
    wasActive = true
    if (store.selected >= list.length) moveTo(Math.max(0, list.length - 1))
  })

  function moveTo(next: number, center = false) {
    setStore("selected", next)
    scrollToIndex(next, center)
  }

  function scrollToIndex(index: number, center: boolean) {
    if (!scroll) return
    if (center) {
      scroll.scrollTo(Math.max(0, index - Math.floor(scroll.viewport.height / 2)))
      return
    }
    if (index >= scroll.scrollTop + scroll.viewport.height) {
      scroll.scrollTo(index - scroll.viewport.height + 1)
    }
    if (index < scroll.scrollTop) {
      scroll.scrollTo(index)
      if (index === 0) scroll.scrollTo(0)
    }
  }

  onMount(() => {
    const cleanup = composer.register({
      id: "subagents",
      label: "Subagents",
      hints: () => {
        const entry = selectedEntry()
        return [
          ...(entry?.status === "running"
            ? [{ label: "interrupt", shortcut: shortcuts.get("composer.subagent.interrupt") ?? "" }]
            : []),
          {
            label: `show ${filter.active ? "inactive" : "active"}`,
            shortcut: shortcuts.get("composer.subagent.toggle-activity") ?? "",
          },
        ]
      },
    })
    onCleanup(cleanup)
  })

  Keymap.createLayer(() => ({
    mode: "composer",
    enabled: () => composer.active("subagents"),
    priority: 1,
    commands: [
      {
        id: "composer.subagent.up",
        title: "Previous subagent",
        group: "Composer",
        run() {
          if (store.selected === 0) {
            composer.close()
            return
          }
          moveTo(store.selected - 1, true)
        },
      },
      {
        id: "composer.subagent.down",
        title: "Next subagent",
        group: "Composer",
        run() {
          const list = entries()
          if (list.length === 0) return
          moveTo((store.selected + 1) % list.length, true)
        },
      },
      {
        id: "composer.subagent.select",
        title: "Navigate to subagent",
        group: "Composer",
        run() {
          const entry = entries()[store.selected]
          if (entry) navigate({ type: "session", sessionID: entry.sessionID })
        },
      },
      {
        id: "composer.subagent.toggle-activity",
        title: "Toggle active subagents",
        group: "Composer",
        bind: "ctrl+a",
        run() {
          updateFilter((draft) => (draft.active = !draft.active))
          setStore("selected", 0)
          scroll?.scrollTo(0)
        },
      },
      {
        id: "composer.subagent.interrupt",
        title: "Interrupt subagent",
        group: "Composer",
        run() {
          const entry = selectedEntry()
          if (!entry || entry.status !== "running") return
          void client.api.session.interrupt({ sessionID: entry.sessionID })
        },
      },
    ],
  }))

  return (
    <Show when={composer.active("subagents")}>
      <scrollbox scrollbarOptions={{ visible: false }} maxHeight={5} ref={(r: ScrollBoxRenderable) => (scroll = r)}>
        <Show
          when={entries().length > 0}
          fallback={<text fg={theme.text.muted}> No {filter.active ? "active" : "inactive"} subagents</text>}
        >
          <For each={entries()}>
            {(entry, index) => {
              const active = createMemo(() => index() === store.selected)
              const status = createMemo(() => {
                if (entry.status === "running") return "Running"
                return ""
              })
              return (
                <box
                  flexDirection="row"
                  paddingLeft={1}
                  paddingRight={1}
                  backgroundColor={
                    active()
                      ? theme.background.action.primary.focused
                      : entry.current
                        ? theme.background.action.primary.selected
                        : theme.background.action.primary.base
                  }
                  onMouseMove={() => setStore("selected", index())}
                  onMouseUp={() => {
                    setStore("selected", index())
                    navigate({ type: "session", sessionID: entry.sessionID })
                  }}
                >
                  <box flexGrow={1} minWidth={0} flexDirection="row">
                    <text
                      fg={
                        active()
                          ? theme.text.action.primary.focused
                          : entry.current
                            ? theme.text.action.primary.selected
                            : theme.text.action.primary.base
                      }
                      attributes={active() ? TextAttributes.BOLD : undefined}
                      wrapMode="none"
                    >
                      {entry.prefix}
                      {entry.agent}: {entry.title}
                    </text>
                  </box>
                  <Show when={status()}>
                    <text fg={active() ? theme.text.action.primary.focused : theme.text.muted} wrapMode="none">
                      {status()}
                    </text>
                  </Show>
                </box>
              )
            }}
          </For>
        </Show>
      </scrollbox>
    </Show>
  )
}

import { createEffect, createMemo, createSignal, For, onCleanup, onMount, Show } from "solid-js"
import { TextAttributes } from "@opentui/core"
import { Keymap } from "../../../context/keymap"
import { useSessionTerminals } from "../../../context/session-terminals"
import { useTheme } from "../../../context/theme"
import { useToast } from "../../../ui/toast"
import { useComposerTab } from "./context"

export function TerminalsTab(props: { sessionID: string; visibleTerminalID?: string }) {
  const composer = useComposerTab()
  const terminals = useSessionTerminals()
  const theme = useTheme()
  const toast = useToast()
  const failure = () => toast.show({ variant: "error", message: "Unable to load terminal" })
  const [selected, setSelected] = createSignal<number>()
  const session = () => terminals.get(props.sessionID)
  const entries = () => session()?.terminals ?? []

  onMount(() => {
    const cleanup = composer.register({ id: "terminals", label: "Terminals" })
    onCleanup(cleanup)
  })

  createEffect(() => {
    if (!composer.active("terminals")) return
    const index = entries().findIndex((terminal) => terminal.id === props.visibleTerminalID)
    setSelected(index < 0 ? undefined : index)
  })

  const select = () => {
    const index = selected()
    if (index === undefined) return
    const terminal = entries()[index]
    composer.close()
    if (terminal) {
      void terminals.selectTerminal(props.sessionID, terminal.id).catch(failure)
      return
    }
    void terminals.newTerminal(props.sessionID).catch(failure)
  }

  Keymap.createLayer(() => ({
    mode: "composer",
    enabled: () => composer.active("terminals"),
    priority: 1,
    commands: [
      {
        id: "composer.terminal.up",
        title: "Previous terminal",
        group: "Composer",
        run: () => setSelected((index) => ((index ?? 0) + entries().length) % (entries().length + 1)),
      },
      {
        id: "composer.terminal.down",
        title: "Next terminal",
        group: "Composer",
        run: () => setSelected((index) => ((index ?? -1) + 1) % (entries().length + 1)),
      },
      {
        id: "composer.terminal.select",
        title: "Select terminal",
        group: "Composer",
        run: select,
      },
    ],
  }))

  return (
    <Show when={composer.active("terminals")}>
      <scrollbox scrollbarOptions={{ visible: false }} maxHeight={5}>
        <For each={[...entries(), undefined]}>
          {(terminal, index) => {
            const active = createMemo(() => index() === selected())
            const current = () => terminal !== undefined && terminal.id === props.visibleTerminalID
            return (
              <box
                flexDirection="row"
                paddingLeft={1}
                paddingRight={1}
                backgroundColor={
                  active()
                    ? theme.background.action.primary.focused
                    : current()
                      ? theme.background.action.primary.selected
                      : theme.background.action.primary.base
                }
                onMouseMove={() => setSelected(index())}
                onMouseUp={() => {
                  setSelected(index())
                  select()
                }}
              >
                <text
                  fg={
                    active()
                      ? theme.text.action.primary.focused
                      : current()
                        ? theme.text.action.primary.selected
                        : theme.text.action.primary.base
                  }
                  attributes={active() ? TextAttributes.BOLD : undefined}
                  wrapMode="none"
                  truncate
                >
                  {terminal?.foregroundProcess ?? terminal?.title ?? "+ New terminal"}
                </text>
              </box>
            )
          }}
        </For>
      </scrollbox>
    </Show>
  )
}

import { TextAttributes, type CodeRenderable, type LineInfo, type ScrollBoxRenderable } from "@opentui/core"
import { useTerminalDimensions } from "@opentui/solid"
import type { SessionMessageAssistantTool } from "@opencode/client/promise"
import { Option, Schema } from "effect"
import { createMemo, createSignal, onCleanup, Show } from "solid-js"
import stripAnsi from "strip-ansi"
import { useConfig } from "../../config"
import { useClipboard } from "../../context/clipboard"
import { Keymap } from "../../context/keymap"
import { useTheme, useThemes } from "../../context/theme"
import {
  DIALOG_INSET,
  DialogBleed,
  DialogFooter,
  DialogHeader,
  DialogLayout,
  dialogWidth,
  useDialog,
} from "../../ui/dialog"
import { useToast } from "../../ui/toast"
import { Locale } from "../../util/locale"
import { getScrollAcceleration } from "../../util/scroll"

const decodeJson = Schema.decodeUnknownOption(Schema.fromJsonString(Schema.Unknown))

// The part is the live store object, so the dialog follows the tool while child
// calls stream and the output arrives.
export function DialogExecute(props: { part: SessionMessageAssistantTool }) {
  const dialog = useDialog()
  const clipboard = useClipboard()
  const toast = useToast()
  const theme = useTheme().surface("dialog")
  const contentTheme = useTheme()
  const dimensions = useTerminalDimensions()
  const config = useConfig().data
  const [copied, setCopied] = createSignal<"code" | "output">()
  const maxHeight = createMemo(() => Math.max(3, Math.floor(dimensions().height * 0.7) - 6))
  let scroll: ScrollBoxRenderable | undefined

  dialog.setSize("xlarge")
  dialog.setCentered(true)

  const code = createMemo(() => executeCode(props.part.state.input))
  const text = createMemo(() => outputText(props.part.state))
  const highlighted = createMemo(() => {
    const value = text()
    return value ? highlightedOutput(value) : undefined
  })
  const failed = createMemo(() => {
    const state = props.part.state
    if (state.status === "error") return true
    if (state.status === "streaming") return false
    return state.metadata?.error === true
  })
  // Both blocks share one gutter width so their content starts on the same column.
  const digits = createMemo(() => String(Math.max(lineCount(code()), lineCount(highlighted()?.json), 1)).length)
  // Code and JSON wrap by character, so the content height is known up front.
  // Sizing synchronously lets the dialog open complete instead of growing over frames.
  const height = createMemo(() => {
    const width = Math.max(20, Math.min(dialogWidth(dialog.size), dimensions().width - 2) - DIALOG_INSET * 2)
    const codeWidth = Math.max(1, width - digits() - 1)
    const body = highlighted()
    const outputRows = body
      ? wrappedRows(body.json, codeWidth) + wrappedRows(body.rest, codeWidth)
      : wrappedRows(text(), width) || 1
    return Math.min(maxHeight(), (wrappedRows(code(), codeWidth) || 1) + outputRows + 5)
  })
  const status = createMemo(() => {
    const state = props.part.state
    if (state.status === "streaming") return "Receiving code…"
    if (state.status === "running") return "Running"
    const duration = props.part.time.completed
      ? ` · ${Locale.duration(props.part.time.completed - (props.part.time.ran ?? props.part.time.created))}`
      : ""
    if (failed()) return `Failed${duration}`
    return `Completed${duration}`
  })

  const copy = (kind: "code" | "output") => {
    const value = kind === "code" ? code() : text()
    if (!value) return
    void clipboard
      .write(value)
      .then(() => setCopied(kind))
      .catch(toast.error)
  }

  Keymap.createLayer(() => ({
    mode: "modal",
    commands: [
      { bind: "up", title: "Scroll up", group: "Execute", run: () => scroll?.scrollBy(-1) },
      { bind: "down", title: "Scroll down", group: "Execute", run: () => scroll?.scrollBy(1) },
      { bind: "pageup", title: "Previous page", group: "Execute", run: () => scroll?.scrollBy(-maxHeight()) },
      { bind: "pagedown", title: "Next page", group: "Execute", run: () => scroll?.scrollBy(maxHeight()) },
      { bind: "home", title: "Scroll to code", group: "Execute", run: () => scroll?.scrollTo(0) },
      { bind: "end", title: "Scroll to output", group: "Execute", run: () => scroll?.scrollTo(Infinity) },
      { bind: "c", title: "Copy code", group: "Execute", run: () => copy("code") },
      { bind: "o", title: "Copy output", group: "Execute", run: () => copy("output") },
    ],
  }))

  const copyActions = () => [
    copied() === "code"
      ? { title: "✓ copied", color: theme.text.feedback.success.base, onTrigger: () => copy("code") }
      : { title: "copy code", key: "c", onTrigger: () => copy("code") },
    copied() === "output"
      ? { title: "✓ copied", color: theme.text.feedback.success.base, onTrigger: () => copy("output") }
      : { title: "copy output", key: "o", onTrigger: () => copy("output") },
  ]

  return (
    <DialogLayout
      header={
        <DialogHeader
          gap={2}
          titleView={
            <text fg={theme.text.base} attributes={TextAttributes.BOLD} flexGrow={1}>
              execute
            </text>
          }
        >
          <text fg={failed() ? theme.text.feedback.error.base : theme.text.muted}>{status()}</text>
        </DialogHeader>
      }
      footer={{ actions: { primary: copyActions() } }}
      legacyFooter={
        <DialogFooter
          actions={{
            secondary: [
              { title: "scroll", key: "↑/↓" },
              ...copyActions(),
              { title: "back", key: "esc", onTrigger: () => dialog.clear() },
            ],
          }}
        />
      }
    >
      <DialogBleed>
        <scrollbox
          id="execute-detail-scroll"
          ref={(value: ScrollBoxRenderable) => (scroll = value)}
          height={height()}
          contentOptions={{ minHeight: 0 }}
          backgroundColor={contentTheme.background.raised.high}
          scrollbarOptions={{ visible: false }}
          scrollAcceleration={getScrollAcceleration(config)}
        >
          <box gap={1} paddingLeft={DIALOG_INSET} paddingRight={DIALOG_INSET} paddingTop={1} paddingBottom={1}>
            <box>
              <text fg={contentTheme.text.muted} attributes={TextAttributes.BOLD}>
                Code
              </text>
              <Show when={code()} fallback={<text fg={contentTheme.text.muted}>Waiting for code…</text>}>
                {(value) => <GutteredCode content={value()} filetype="typescript" digits={digits()} />}
              </Show>
            </box>
            <box>
              <text fg={contentTheme.text.muted} attributes={TextAttributes.BOLD}>
                Output
              </text>
              <Show
                when={highlighted()}
                fallback={
                  <text
                    fg={
                      text()
                        ? failed()
                          ? contentTheme.text.feedback.error.base
                          : contentTheme.text.base
                        : contentTheme.text.muted
                    }
                    wrapMode="word"
                  >
                    {text() ?? (props.part.state.status === "completed" ? "No output" : "Waiting for output…")}
                  </text>
                }
              >
                {(body) => (
                  <>
                    <GutteredCode content={body().json} filetype="json" digits={digits()} />
                    <Show when={body().rest}>
                      {(rest) => (
                        <box paddingLeft={digits() + 1}>
                          <text
                            fg={failed() ? contentTheme.text.feedback.error.base : contentTheme.text.base}
                            wrapMode="word"
                          >
                            {rest()}
                          </text>
                        </box>
                      )}
                    </Show>
                  </>
                )}
              </Show>
            </box>
          </box>
        </scrollbox>
      </DialogBleed>
    </DialogLayout>
  )
}

function executeCode(input: SessionMessageAssistantTool["state"]["input"]) {
  if (typeof input === "string") return
  return typeof input.code === "string" && input.code ? input.code : undefined
}

function outputText(state: SessionMessageAssistantTool["state"]) {
  if (state.status === "error") return state.error.message || undefined
  if (state.status !== "completed") return
  const text = stripAnsi(
    state.content
      .flatMap((item) => (item.type === "text" ? [item.text] : []))
      .join("\n")
      .trim(),
  )
  return text || undefined
}

// The tool prints a JSON result, optionally followed by "\n\nWarnings:" and "\n\nLogs:".
function highlightedOutput(text: string) {
  if (!text.startsWith("{") && !text.startsWith("[")) return
  const end = text.search(/\n\n(Warnings|Logs):\n/)
  const json = end === -1 ? text : text.slice(0, end)
  if (Option.isNone(decodeJson(json))) return
  return { json, rest: text.slice(json.length).trim() || undefined }
}

function lineCount(text: string | undefined) {
  return text ? text.split("\n").length : 0
}

function wrappedRows(text: string | undefined, width: number) {
  if (!text) return 0
  return text.split("\n").reduce((sum, line) => sum + Math.max(1, Math.ceil(line.length / width)), 0)
}

// `<line_number>` right-aligns digits in a gutter sized to that block alone, so
// the column "1" starts on depends on the line count and differs between calls.
// One shared left-aligned gutter keeps the title and every line number on the
// same column, and keeps code and output on one content column. The gutter
// follows the wrapped layout so continuation rows stay unnumbered.
function GutteredCode(props: { content: string; filetype: "typescript" | "json"; digits: number }) {
  const theme = useTheme()
  const syntax = useThemes().currentSyntax
  const [info, setInfo] = createSignal<LineInfo>()
  const gutter = createMemo(() => {
    const sources = info()?.lineSources ?? props.content.split("\n").map((_, index) => index)
    return sources
      .map((source, index) => (sources[index - 1] === source ? "" : String(source + 1)).padEnd(props.digits))
      .join("\n")
  })
  const track = (block: CodeRenderable) => {
    const update = () => setInfo({ ...block.lineInfo })
    block.on("line-info-change", update)
    onCleanup(() => block.off("line-info-change", update))
  }

  return (
    <box flexDirection="row" gap={1} width="100%">
      <text fg={theme.text.muted} flexShrink={0} width={props.digits}>
        {gutter()}
      </text>
      <box flexGrow={1} flexShrink={1} minWidth={0}>
        <code
          ref={track}
          width="100%"
          conceal={false}
          wrapMode="char"
          fg={theme.text.base}
          filetype={props.filetype}
          syntaxStyle={syntax()}
          content={props.content}
        />
      </box>
    </box>
  )
}

import { createMemo, createSignal, onMount, Show } from "solid-js"
import { useData } from "../../context/data"
import { useRoute } from "../../context/route"
import { useClient } from "../../context/client"
import { Spinner } from "../../component/spinner"
import { DialogSelect, type DialogSelectOption } from "../../ui/dialog-select"
import { DIALOG_LIST_INSET, DialogHeader, DialogLayout, useDialog } from "../../ui/dialog"
import { useToast } from "../../ui/toast"
import { errorMessage } from "../../util/error"
import { Locale } from "../../util/locale"
import { projectedPromptInput } from "../../prompt/codec"

export function DialogFork(props: { sessionID: string; messageID?: string; onMove?: (messageID?: string) => void }) {
  const data = useData()
  const dialog = useDialog()
  const client = useClient()
  const route = useRoute()
  const toast = useToast()
  const [pending, setPending] = createSignal(!!props.messageID)

  const fork = async (messageID?: string) => {
    setPending(true)
    const result = await client.api.session
      .fork({
        sessionID: props.sessionID,
        before: messageID,
      })
      .catch((error) => {
        toast.show({ message: errorMessage(error), variant: "error", duration: 5000 })
        return undefined
      })
    if (!result) return dialog.clear()
    const message = messageID ? data.session.message.get(props.sessionID, messageID) : undefined
    const prompt = message?.type === "user" ? projectedPromptInput(message) : undefined
    route.navigate({
      sessionID: result.id,
      type: "session",
      prompt: prompt
        ? {
            ...prompt,
            agents: prompt.agents ?? [],
            pasted: [],
          }
        : undefined,
    })
    dialog.clear()
    toast.show({ message: "Forked session", variant: "success", duration: 4000 })
  }

  onMount(() => {
    dialog.setSize("large")
    if (props.messageID) void fork(props.messageID)
  })

  const options = createMemo((): DialogSelectOption<string | undefined>[] => [
    {
      title: "Full session",
      value: undefined,
      onSelect: () => fork(),
    },
    ...data.session.message
      .list(props.sessionID)
      .filter((message) => message.type === "user")
      .toReversed()
      .map((message) => ({
        title: message.text.replace(/\n/g, " "),
        value: message.id,
        footer: Locale.time(message.time.created),
        onSelect: () => fork(message.id),
      })),
  ])

  return (
    <Show
      when={!pending()}
      fallback={
        <DialogLayout inset={DIALOG_LIST_INSET} header={<DialogHeader title="Fork session" />}>
          <Spinner>Forking session…</Spinner>
        </DialogLayout>
      }
    >
      <DialogSelect onMove={(option) => props.onMove?.(option.value)} title="Fork session" options={options()} />
    </Show>
  )
}

import { createMemo } from "solid-js"
import { useData } from "../../context/data"
import { DialogSelect } from "../../ui/dialog-select"
import { useClipboard } from "../../context/clipboard"
import { useToast } from "../../ui/toast"
import { useClient } from "../../context/client"
import { errorMessage } from "../../util/error"
import { DialogFork } from "./dialog-fork"
import type { PromptInfo } from "../../prompt/history"
import { projectedPromptInput } from "../../prompt/codec"
import { useNewDesigns } from "../../config"

export function DialogMessage(props: {
  messageID: string
  sessionID: string
  setPrompt?: (prompt: PromptInfo) => void
}) {
  const data = useData()
  const clipboard = useClipboard()
  const toast = useToast()
  const client = useClient()
  const newDesigns = useNewDesigns()
  const message = createMemo(() => data.session.message.get(props.sessionID, props.messageID))

  return (
    <DialogSelect
      title="Message Actions"
      renderFilter={!newDesigns()}
      options={[
        {
          title: "Jump to",
          value: "message.jump",
          description: "view message in session",
          onSelect: (dialog) => dialog.clear(),
        },
        {
          title: "Revert",
          value: "session.revert",
          description: "undo messages and file changes",
          onSelect: (dialog) => {
            const value = message()
            if (value?.type === "user") {
              props.setPrompt?.({
                ...projectedPromptInput(value),
                pasted: [],
              })
            }
            void client.api.session.revert
              .stage({ sessionID: props.sessionID, messageID: props.messageID })
              .catch((error) => toast.show({ message: errorMessage(error), variant: "error", duration: 5000 }))
            dialog.clear()
          },
        },
        {
          title: "Copy",
          value: "message.copy",
          description: "message text to clipboard",
          onSelect: async (dialog) => {
            const value = message()
            if (!value) return
            const text =
              value.type === "user"
                ? value.text
                : value.type === "assistant"
                  ? value.content
                      .filter((content) => content.type === "text")
                      .map((content) => content.text)
                      .join("\n")
                  : "text" in value
                    ? value.text
                    : ""
            try {
              await clipboard.write(text)
              dialog.clear()
            } catch (error) {
              toast.error(error)
            }
          },
        },
        {
          title: "Fork",
          value: "session.fork",
          description: "create a new session",
          onSelect: (dialog) => {
            const value = message()
            if (!value || value.type !== "user") return
            dialog.replace(() => <DialogFork sessionID={props.sessionID} messageID={props.messageID} />)
          },
        },
      ]}
    />
  )
}

import { createMemo, onMount } from "solid-js"
import { useData } from "../../context/data"
import { DialogSelect, type DialogSelectOption } from "../../ui/dialog-select"
import { Locale } from "../../util/locale"
import { DialogMessage } from "./dialog-message"
import { useDialog } from "../../ui/dialog"
import type { PromptInfo } from "../../prompt/history"

export function DialogTimeline(props: {
  sessionID: string
  onMove: (messageID: string) => void
  setPrompt?: (prompt: PromptInfo) => void
}) {
  const data = useData()
  const dialog = useDialog()

  onMount(() => {
    dialog.setSize("large")
  })

  const options = createMemo((): DialogSelectOption<string>[] => {
    const messages = data.session.message.list(props.sessionID)
    const result = [] as DialogSelectOption<string>[]
    for (const message of messages) {
      if (message.type !== "user") continue
      result.push({
        title: message.text.replace(/\n/g, " "),
        value: message.id,
        footer: Locale.time(message.time.created),
        onSelect: (dialog) => {
          dialog.replace(() => (
            <DialogMessage messageID={message.id} sessionID={props.sessionID} setPrompt={props.setPrompt} />
          ))
        },
      })
    }
    result.reverse()
    return result
  })

  return (
    <DialogSelect
      onMove={(option) => props.onMove(option.value)}
      title="Timeline"
      searchInTitle
      titlePlaceholder="Search timeline"
      options={options()}
    />
  )
}

import { createStore, unwrap } from "solid-js/store"
import { createEffect, createMemo, createSignal, For, onCleanup, onMount, Show } from "solid-js"
import { usePaste, useRenderer, useTerminalDimensions } from "@opentui/solid"
import {
  decodePasteBytes,
  stripAnsiSequences,
  TextAttributes,
  type BoxRenderable,
  type ScrollBoxRenderable,
  type TextareaRenderable,
} from "@opentui/core"
import { openUrl } from "@opencode/util/open"
import { useTheme } from "../../context/theme"
import type { FormAnswer, FormField, FormValue } from "@opencode/client"
import { useData, type FormWithLocation } from "../../context/data"
import { useClipboard } from "../../context/clipboard"
import { SplitBorder } from "../../ui/border"
import { useToast } from "../../ui/toast"
import { Keymap } from "../../context/keymap"
import { useInteractivity } from "../../context/interactivity"
import { useConfig } from "../../config"
import { errorMessage } from "../../util/error"
import {
  formCustom,
  formDisplayValue,
  formInitialValues,
  formLabel,
  formRows,
  formSelected,
  formSetMultiselectCustom,
  formTextual,
  formToggleMultiselect,
  formValidateValue,
  isFormAnswerField,
} from "../../util/form"
import type { FormAnswerField } from "../../util/form"

export const FORM_MODE = "form"

function truncate(label: string, max: number) {
  return label.length > max ? label.slice(0, max - 1).trimEnd() + "…" : label
}

type FormDraft = {
  tab: number
  answers: Record<string, FormValue | undefined>
  custom: Record<string, string | undefined>
  externalReady: Record<string, boolean>
  selected: number
  editing: boolean
  error: string
}

// Holds in-progress answers per form across FormPrompt remounts, since the
// session route is keyed by sessionID and unmounts on tab switch. Mirrors
// component/prompt/draft-stash.ts: a draft is consumed on take.
const drafts = new Map<string, FormDraft>()

export function FormPrompt(props: { form: FormWithLocation }) {
  const data = useData()
  const theme = useTheme()
  const renderer = useRenderer()
  const dimensions = useTerminalDimensions()
  const keymap = Keymap.use()
  const enabled = useInteractivity()
  const active = () => enabled() && keymap.mode.current() === FORM_MODE
  const config = useConfig().data
  const clipboard = useClipboard()
  const toast = useToast()
  const configuredFields = props.form.fields.filter(isFormAnswerField)
  const initial = formInitialValues(props.form.fields)
  const draft = drafts.get(props.form.id)
  drafts.delete(props.form.id)

  const [tabHover, setTabHover] = createSignal<number | "confirm" | null>(null)
  const [reviewContentHeight, setReviewContentHeight] = createSignal(0)
  const [store, setStore] = createStore<FormDraft>(
    draft ?? {
      tab: 0,
      answers: initial.answers,
      custom: initial.custom,
      externalReady: {},
      selected: formSelected(configuredFields[0], configuredFields[0]?.default),
      editing: false,
      error: "",
    },
  )

  let textarea: TextareaRenderable | undefined
  const [inputTarget, setInputTarget] = createSignal<TextareaRenderable>()
  let review: ScrollBoxRenderable | undefined

  const message = createMemo(() => {
    const value = props.form.metadata?.["message"]
    return typeof value === "string" ? value : undefined
  })
  const fields = createMemo(() => {
    const answers: Record<string, FormValue | undefined> = {}
    return props.form.fields.filter((field) => {
      if (field.type === "external") return true
      const active = (field.when ?? []).every((when) => {
        const value = answers[when.key]
        if (value === undefined) return false
        const hit = Array.isArray(value) ? value.some((item) => item === when.value) : value === when.value
        return when.op === "eq" ? hit : !hit
      })
      if (active) answers[field.key] = store.answers[field.key]
      return active
    })
  })
  const single = createMemo(() => {
    const list = fields()
    if (list.length !== 1) return false
    const field = list[0]
    if (field.type === "external") return false
    return field.type === "boolean" || (field.type === "string" && field.options !== undefined)
  })
  const tabs = createMemo(() => (single() ? 1 : fields().length + 1))
  const tabbed = createMemo(() => {
    const width = fields().reduce((sum, item) => sum + truncate(formLabel(item), 24).length + 3, "Submit".length + 3)
    return width <= dimensions().width - 8
  })
  const completed = (item: FormField) => {
    const value = store.answers[item.key]
    if (value === undefined) return false
    if (item.type === "external") return value === true
    return formValidateValue(item, value) === undefined
  }
  const answered = createMemo(() => fields().filter(completed).length)
  const field = createMemo(() => fields()[store.tab])
  const answerField = createMemo(() => {
    const current = field()
    return current && isFormAnswerField(current) ? current : undefined
  })
  const externalField = createMemo(() => {
    const current = field()
    return current?.type === "external" ? current : undefined
  })
  const confirm = createMemo(() => !single() && store.tab >= fields().length)
  const reviewMaxHeight = createMemo(() => Math.max(3, dimensions().height - 14))
  const configuredRows = createMemo(() => {
    const current = answerField()
    return current ? formRows(current) : []
  })
  const rows = createMemo(() => {
    const current = answerField()
    if (!current) return []
    const configured = configuredRows()
    const value = store.answers[current.key]
    if (current.type !== "multiselect" || !Array.isArray(value)) return configured
    const known = new Set(configured.map((row) => row.value))
    return [
      ...configured,
      ...value
        .filter((item) => !known.has(item) && item !== store.custom[current.key])
        .map((item) => ({ value: item, label: item, description: undefined })),
    ]
  })
  const textual = createMemo(() => {
    if (confirm()) return false
    return formTextual(answerField())
  })
  const custom = createMemo(() => {
    return formCustom(answerField())
  })
  const multi = createMemo(() => answerField()?.type === "multiselect")
  const placeholder = createMemo(() => {
    const current = answerField()
    if (current?.type === "string") {
      if (current.placeholder) return current.placeholder
      if (current.format === "email") return "name@example.com"
      if (current.format === "uri") return "https://example.com"
      if (current.format === "date") return "YYYY-MM-DD"
      if (current.format === "date-time") return "YYYY-MM-DDTHH:MM:SSZ"
    }
    if (current?.type === "number" || current?.type === "integer") {
      const minimum = typeof current.minimum === "number" ? current.minimum : undefined
      const maximum = typeof current.maximum === "number" ? current.maximum : undefined
      if (minimum !== undefined && maximum !== undefined) return `${minimum}-${maximum}`
      if (minimum !== undefined) return `at least ${minimum}`
      if (maximum !== undefined) return `at most ${maximum}`
    }
    return "Type your answer"
  })
  const other = createMemo(() => custom() && store.selected === rows().length)
  const input = createMemo(() => store.custom[answerField()?.key ?? ""] ?? "")
  const customPicked = createMemo(() => {
    const value = input()
    if (!value) return false
    const answer = store.answers[answerField()?.key ?? ""]
    if (Array.isArray(answer)) return answer.includes(value)
    return answer === value
  })
  const customChecked = createMemo(() => customPicked() || (multi() && other() && store.editing))
  const actionLabel = createMemo(() => {
    if (confirm()) return "submit"
    const external = externalField()
    if (external) {
      if (store.answers[external.key] === true) return "continue"
      return store.externalReady[external.key] ? "I finished" : "open link"
    }
    if (multi()) {
      if (other() && store.editing) return "done"
      if (other() && !input()) return "edit"
      return "toggle"
    }
    if (single()) return "submit"
    return "confirm"
  })

  onCleanup(() => {
    // A reply or cancel removes the form from data before this unmount runs, so a
    // form still listed here is only hidden by navigation and worth restoring.
    const pending = data.session.form
      .list(props.form.sessionID, props.form.location)
      ?.some((item) => item.id === props.form.id)
    if (!pending) return
    // Textual answers live in the editor until committed, so capture them here.
    const current = answerField()
    const snapshot = unwrap(store)
    drafts.set(props.form.id, {
      ...snapshot,
      custom:
        current && textarea && !textarea.isDestroyed
          ? { ...snapshot.custom, [current.key]: textarea.plainText }
          : snapshot.custom,
    })
  })

  // Refs publish after initialization so burst typing stays with the interceptor until the editor is ready.
  createEffect(() => {
    const target = inputTarget()
    if (!target || target.isDestroyed) return
    if (!active()) {
      target.blur()
      target.focusable = false
      return
    }
    target.focusable = true
    target.focus()
  })

  onCleanup(
    keymap.intercept("key", ({ event, consume }) => {
      if (!active()) return
      if (textual() || !other() || (store.editing && renderer.currentFocusedEditor === textarea)) return
      if (event.ctrl || event.meta || event.option || event.super || event.hyper) return
      if ((!store.editing && event.sequence === " ") || !/^[^\p{C}\p{Zl}\p{Zp}]$/u.test(event.sequence)) return
      const current = answerField()
      if (!current) return
      updateCustom(current, input() + event.sequence)
      if (!store.editing) setStore("editing", true)
      consume()
    }),
  )

  function answer(key: string, value: FormValue | undefined) {
    const field = fields().find((item) => item.key === key)
    setStore(
      "answers",
      key,
      Array.isArray(value) && value.length === 0 && field?.type === "multiselect" && !field.required
        ? undefined
        : value,
    )
    setStore("error", "")
  }

  function reply(answer: FormAnswer) {
    void data.session.form
      .reply({ sessionID: props.form.sessionID, formID: props.form.id, answer }, props.form.location)
      .catch(showError)
  }

  function replySingle(field: FormAnswerField, value: FormValue) {
    reply({ [field.key]: value })
  }

  function pick(value: FormValue, customValue?: string) {
    const current = answerField()
    if (!current) return
    const invalid = formValidateValue(current, value)
    if (invalid) {
      setStore("error", invalid)
      return
    }
    answer(current.key, value)
    if (customValue !== undefined) setStore("custom", current.key, customValue)
    if (single()) {
      replySingle(current, value)
      return
    }
    selectTab(store.tab + 1)
  }

  function toggle(value: string) {
    const current = answerField()
    if (!current) return
    answer(current.key, formToggleMultiselect(store.answers[current.key], value))
  }

  function updateCustom(current: FormAnswerField, value: string) {
    const previous = store.custom[current.key]
    if (previous === value) return
    setStore("custom", current.key, value)
    answer(
      current.key,
      current.type === "multiselect"
        ? formSetMultiselectCustom(store.answers[current.key], previous, value)
        : value || undefined,
    )
  }

  function selectTab(index: number) {
    const next = fields()[index]
    setStore("tab", index)
    setStore("selected", next && isFormAnswerField(next) ? formSelected(next, store.answers[next.key]) : 0)
    setStore("editing", false)
    setStore("error", "")
  }

  function selectOption() {
    if (other()) {
      if (!multi()) {
        setStore("editing", true)
        return
      }
      const value = input()
      if (value && customPicked()) {
        toggle(value)
        return
      }
      setStore("editing", true)
      return
    }
    const row = rows()[store.selected]
    if (!row) return
    if (multi()) {
      toggle(String(row.value))
      return
    }
    pick(row.value)
  }

  function pasteCustom(value: string) {
    const current = answerField()
    if (!current || textual() || !custom() || confirm()) return false
    setStore("selected", rows().length)
    updateCustom(current, input() + value)
    setStore("editing", true)
    return true
  }

  usePaste((event) => {
    if (!active()) return
    const value = stripAnsiSequences(decodePasteBytes(event.bytes)).replace(/\r\n?/g, "\n")
    if (store.editing && renderer.currentFocusedEditor === textarea) {
      textarea.insertText(value)
      event.preventDefault()
      return
    }
    if (!pasteCustom(value)) return
    event.preventDefault()
  })

  function pasteClipboard() {
    return clipboard
      .read()
      .then((content) => {
        if (!active() || content?.mime !== "text/plain") return
        const value = stripAnsiSequences(content.data).replace(/\r\n?/g, "\n")
        if (store.editing || textual()) {
          textarea?.insertText(value)
          return
        }
        pasteCustom(value)
      })
      .catch(toast.error)
  }

  function commitInput(text: string) {
    const current = answerField()
    if (!current) return false
    const isTextual = textual()
    const isMulti = multi()
    if (!text) {
      const value =
        !isTextual && isMulti
          ? formSetMultiselectCustom(store.answers[current.key], store.custom[current.key], "")
          : undefined
      if (isTextual || !isMulti) {
        const invalid = formValidateValue(current, value)
        if (invalid) {
          setStore("error", invalid)
          return false
        }
      }
      answer(current.key, value)
      setStore("custom", current.key, "")
      setStore("editing", false)
      return true
    }

    if (isTextual && (current.type === "number" || current.type === "integer")) {
      const value = Number(text)
      const invalid = formValidateValue(current, value)
      if (invalid) {
        setStore("error", invalid)
        return false
      }
      answer(current.key, value)
    }

    if (isTextual && current.type === "string") {
      const invalid = formValidateValue(current, text)
      if (invalid) {
        setStore("error", invalid)
        return false
      }
      answer(current.key, text)
    }

    if (!isTextual && isMulti) {
      answer(current.key, formSetMultiselectCustom(store.answers[current.key], store.custom[current.key], text))
    }

    if (!isTextual && !isMulti) {
      const invalid = formValidateValue(current, text)
      if (invalid) {
        setStore("error", invalid)
        return false
      }
      answer(current.key, text)
    }

    const configured = current.type === "string" && current.options?.some((option) => option.value === text)
    setStore("custom", current.key, configured ? "" : text)
    setStore("editing", false)
    return true
  }

  function submitInput(text: string, direction: 1 | -1 = 1) {
    if (!commitInput(text)) {
      if (direction === -1) selectTab((store.tab + direction + tabs()) % tabs())
      return
    }
    if (!single()) selectTab((store.tab + direction + tabs()) % tabs())
  }

  function selectTabFromMouse(target?: FormField) {
    const targetIndex = () => {
      const index = target ? fields().findIndex((field) => field === target) : fields().length
      return index === -1 ? fields().length : index
    }
    const move = () => selectTab(targetIndex())
    if (!textual() && !store.editing) {
      move()
      return
    }
    if (!commitInput(textarea?.plainText?.trim() ?? "")) {
      if (targetIndex() < store.tab) move()
      return
    }
    move()
  }

  function cancel() {
    void data.session.form
      .cancel({ sessionID: props.form.sessionID, formID: props.form.id }, props.form.location)
      .catch(showError)
  }

  function showError(error: unknown) {
    setStore("error", errorMessage(error))
  }

  function openExternal() {
    const current = externalField()
    if (!current) return
    setStore("error", "")
    void openUrl(current.url)
      .then(() => setStore("externalReady", { ...store.externalReady, [current.key]: true }))
      .catch(() => setStore("error", "Could not open the browser. Copy the URL and continue manually."))
  }

  function copyExternal() {
    const current = externalField()
    if (!current) return
    void clipboard
      .write(current.url)
      .then(() => {
        setStore("externalReady", { ...store.externalReady, [current.key]: true })
        toast.show({ message: "Copied URL to clipboard", variant: "info" })
      })
      .catch(toast.error)
  }

  function acknowledgeExternal() {
    const current = externalField()
    if (!current) return
    if (store.answers[current.key] === true) {
      selectTab(store.tab + 1)
      return
    }
    if (!store.externalReady[current.key]) {
      openExternal()
      return
    }
    answer(current.key, true)
    selectTab(store.tab + 1)
  }

  function submit() {
    const unacknowledged = fields().find((field) => field.type === "external" && store.answers[field.key] !== true)
    if (unacknowledged) {
      setStore("error", `External action must be acknowledged: ${formLabel(unacknowledged)}`)
      return
    }
    const invalid = fields()
      .filter(isFormAnswerField)
      .find((field) => formValidateValue(field, store.answers[field.key]))
    if (invalid) {
      setStore("error", formValidateValue(invalid, store.answers[invalid.key]) ?? "Invalid answer")
      return
    }
    reply(
      Object.fromEntries(
        fields().flatMap((field) => {
          const value = store.answers[field.key]
          return value === undefined ? [] : [[field.key, value] as const]
        }),
      ),
    )
  }

  onMount(() => onCleanup(keymap.mode.push(FORM_MODE)))

  Keymap.createLayer(() => ({
    mode: FORM_MODE,
    enabled: !confirm() && answerField() !== undefined,
    commands: [
      {
        id: "prompt.paste",
        title: "Paste from clipboard",
        group: "Form",
        run: (_input, event) => {
          event?.preventDefault()
          event?.stopPropagation()
          return pasteClipboard()
        },
      },
    ],
  }))

  Keymap.createLayer(() => ({
    mode: FORM_MODE,
    priority: 1,
    enabled: (store.editing || textual()) && !confirm(),
    commands: [
      {
        id: "prompt.clear",
        title: "Clear answer edit",
        group: "Form",
        run() {
          const text = textarea?.plainText ?? ""
          if (!text) {
            if (textual()) {
              cancel()
              return
            }
            setStore("editing", false)
            return
          }
          textarea?.setText("")
        },
      },
      {
        bind: "escape",
        title: textual() ? "Dismiss form" : "Close answer edit",
        group: "Form",
        run: () => {
          if (textual()) {
            cancel()
            return
          }
          setStore("editing", false)
        },
      },
      {
        bind: "tab",
        title: "Next field",
        group: "Form",
        run: () => {
          const text = textarea?.plainText?.trim() ?? ""
          submitInput(text)
        },
      },
      {
        bind: "shift+tab",
        title: "Previous field",
        group: "Form",
        run: () => {
          const text = textarea?.plainText?.trim() ?? ""
          submitInput(text, -1)
        },
      },
      {
        bind: "up",
        title: "Leave answer edit",
        group: "Form",
        run: () => {
          if (textual() || !textarea || textarea.isDestroyed || store.selected === 0) return false
          if (textarea.scrollY + textarea.visualCursor.visualRow > 0) return false
          setStore("editing", false)
          setStore("selected", store.selected - 1)
        },
      },
      {
        bind: "return",
        title: "Submit answer edit",
        group: "Form",
        run: () => {
          const text = textarea?.plainText?.trim() ?? ""
          const current = answerField()
          if (!current) return
          if (textual()) {
            submitInput(text)
            return
          }
          const wasMulti = multi()
          if (!commitInput(text) || wasMulti || !text) return
          if (single()) {
            replySingle(current, text)
            return
          }
          selectTab(store.tab + 1)
        },
      },
    ],
  }))

  Keymap.createLayer(() => {
    const total = rows().length + (custom() ? 1 : 0)
    const max = Math.min(total, 9)
    const external = externalField()

    return {
      mode: FORM_MODE,
      enabled: !store.editing && !textual(),
      commands: [
        {
          id: "app.exit",
          title: "Dismiss form",
          group: "Form",
          run: cancel,
        },
        {
          bind: "left",
          title: "Previous field",
          group: "Form",
          run: () => selectTab((store.tab - 1 + tabs()) % tabs()),
        },
        {
          bind: "h",
          title: "Previous field",
          group: "Form",
          run: () => selectTab((store.tab - 1 + tabs()) % tabs()),
        },
        { bind: "right", title: "Next field", group: "Form", run: () => selectTab((store.tab + 1) % tabs()) },
        { bind: "l", title: "Next field", group: "Form", run: () => selectTab((store.tab + 1) % tabs()) },
        {
          bind: "tab",
          title: "Next field",
          group: "Form",
          run: () => selectTab((store.tab + 1) % tabs()),
        },
        {
          bind: "shift+tab",
          title: "Previous field",
          group: "Form",
          run: () => selectTab((store.tab - 1 + tabs()) % tabs()),
        },
        ...(external
          ? [
              {
                bind: "return",
                title:
                  store.answers[external.key] === true
                    ? "Continue"
                    : store.externalReady[external.key]
                      ? "Confirm completion"
                      : "Open link",
                group: "Form",
                run: acknowledgeExternal,
              },
              { bind: "c", title: "Copy link", group: "Form", run: copyExternal },
              { bind: "escape", title: "Dismiss form", group: "Form", run: cancel },
            ]
          : confirm()
            ? [
                {
                  bind: "return",
                  title: "Submit form",
                  group: "Form",
                  run: submit,
                },
                {
                  bind: "escape",
                  title: "Dismiss form",
                  group: "Form",
                  run: cancel,
                },
                { bind: "up", title: "Scroll review", group: "Form", run: () => review?.scrollBy(-1) },
                { bind: "k", title: "Scroll review", group: "Form", run: () => review?.scrollBy(-1) },
                { bind: "down", title: "Scroll review", group: "Form", run: () => review?.scrollBy(1) },
                { bind: "j", title: "Scroll review", group: "Form", run: () => review?.scrollBy(1) },
              ]
            : [
                ...Array.from({ length: max }, (_, index) => ({
                  bind: String(index + 1),
                  title: `Select answer ${index + 1}`,
                  group: "Form",
                  run: () => {
                    setStore("selected", index)
                    selectOption()
                  },
                })),
                {
                  bind: "up",
                  title: "Previous answer",
                  group: "Form",
                  run: () => setStore("selected", (store.selected - 1 + total) % total),
                },
                {
                  bind: "k",
                  title: "Previous answer",
                  group: "Form",
                  run: () => setStore("selected", (store.selected - 1 + total) % total),
                },
                {
                  bind: "down",
                  title: "Next answer",
                  group: "Form",
                  run: () => setStore("selected", (store.selected + 1) % total),
                },
                {
                  bind: "j",
                  title: "Next answer",
                  group: "Form",
                  run: () => setStore("selected", (store.selected + 1) % total),
                },
                { bind: "return", title: "Select answer", group: "Form", run: () => selectOption() },
                ...(multi()
                  ? [{ bind: "space", title: "Toggle answer", group: "Form", run: () => selectOption() }]
                  : []),
                {
                  bind: "escape",
                  title: "Dismiss form",
                  group: "Form",
                  run: cancel,
                },
              ]),
      ],
    }
  })

  return (
    <box
      backgroundColor={theme.background.raised.base}
      border={["left"]}
      borderColor={theme.background.action.primary.focused}
      customBorderChars={SplitBorder.customBorderChars}
    >
      <box gap={1} paddingLeft={1} paddingRight={3} paddingTop={1} paddingBottom={1}>
        <box paddingLeft={1}>
          <text fg={theme.text.muted}>{props.form.title}</text>
        </box>
        <Show when={message()}>
          <box paddingLeft={1}>
            <text fg={theme.text.base}>{message()}</text>
          </box>
        </Show>
        <Show when={!single() && !tabbed()}>
          <box flexDirection="row" gap={3} paddingLeft={1}>
            <text fg={theme.text.muted}>
              {confirm() ? "Review" : `Field ${Math.min(store.tab, fields().length - 1) + 1} of ${fields().length}`}
            </text>
            <Show when={fields().length > 0}>
              <text fg={theme.text.muted}>
                · {answered()}/{fields().length} completed
              </text>
            </Show>
          </box>
        </Show>
        <Show when={!single() && tabbed()}>
          <box flexDirection="row" paddingLeft={1}>
            <For each={fields()}>
              {(item, index) => {
                const isTab = () => index() === store.tab
                const color = () =>
                  isTab()
                    ? theme.text.base
                    : tabHover() === index()
                      ? theme.text.formfield.focused
                      : theme.text.muted
                return (
                  <box
                    paddingRight={2}
                    backgroundColor={theme.background.raised.base}
                    onMouseOver={() => setTabHover(index())}
                    onMouseOut={() => setTabHover(null)}
                    onMouseUp={() => {
                      if (renderer.getSelection()?.getSelectedText()) return
                      selectTabFromMouse(item)
                    }}
                  >
                    <text fg={color()} attributes={isTab() ? TextAttributes.BOLD : undefined}>
                      {truncate(formLabel(item), 24)}
                    </text>
                  </box>
                )
              }}
            </For>
            <box
              backgroundColor={theme.background.raised.base}
              onMouseOver={() => setTabHover("confirm")}
              onMouseOut={() => setTabHover(null)}
              onMouseUp={() => {
                if (renderer.getSelection()?.getSelectedText()) return
                selectTabFromMouse()
              }}
            >
              <text
                fg={
                  confirm()
                    ? theme.text.base
                    : tabHover() === "confirm"
                      ? theme.text.formfield.focused
                      : theme.text.muted
                }
                attributes={confirm() ? TextAttributes.BOLD : undefined}
              >
                Submit
              </text>
            </box>
          </box>
        </Show>

        <Show when={!confirm() && externalField()}>
          {(external) => (
            <box paddingLeft={1} gap={1}>
              <Show when={external().title}>
                <text fg={theme.text.base}>{external().title}</text>
              </Show>
              <Show when={external().description}>
                <text fg={theme.text.muted}>{external().description}</text>
              </Show>
              <text
                fg={theme.text.action.primary.base}
                onMouseUp={() => {
                  if (renderer.getSelection()?.getSelectedText()) return
                  openExternal()
                }}
              >
                {external().url}
              </text>
              <text
                fg={store.answers[external().key] === true ? theme.text.feedback.success.base : theme.text.muted}
              >
                {store.answers[external().key] === true
                  ? "✓ Acknowledged"
                  : store.externalReady[external().key]
                    ? "Complete the external action, then press enter to confirm."
                    : "Open or copy the URL, complete the external action, then confirm."}
              </text>
            </box>
          )}
        </Show>

        <Show when={!confirm() && answerField()}>
          <box paddingLeft={1} gap={1}>
            <box>
              <text fg={theme.text.base}>{answerField()!.description ?? formLabel(answerField()!)}</text>
            </box>
            <Show when={textual() ? answerField()!.key : undefined} keyed>
              <box paddingLeft={1}>
                <textarea
                  cursorStyle={config.cursor}
                  ref={(val: TextareaRenderable) => {
                    textarea = val
                    val.traits = { status: "ANSWER" }
                    queueMicrotask(() => {
                      if (val.isDestroyed) return
                      val.gotoLineEnd()
                      setInputTarget(val)
                    })
                  }}
                  initialValue={
                    input() || formDisplayValue(answerField()!, store.answers[answerField()!.key], "(none)")
                  }
                  placeholder={placeholder()}
                  placeholderColor={theme.text.muted}
                  minHeight={1}
                  maxHeight={6}
                  textColor={theme.text.base}
                  focusedTextColor={theme.text.base}
                  cursorColor={theme.text.base}
                />
              </box>
            </Show>
            <Show when={!textual()}>
              <box>
                <For each={rows()}>
                  {(row, i) => {
                    const active = () => i() === store.selected
                    const picked = () => {
                      const value = store.answers[answerField()?.key ?? ""]
                      if (Array.isArray(value)) return value.includes(String(row.value))
                      return value === row.value
                    }
                    return (
                      <box
                        onMouseMove={() => setStore("selected", i())}
                        onMouseDown={() => setStore("selected", i())}
                        onMouseUp={() => {
                          if (renderer.getSelection()?.getSelectedText()) return
                          selectOption()
                        }}
                      >
                        <box flexDirection="row">
                          <box
                            backgroundColor={theme.background.raised.base}
                            paddingRight={1}
                          >
                            <text
                              fg={active() ? theme.text.formfield.focused : theme.text.muted}
                            >{`${i() + 1}.`}</text>
                          </box>
                          <box
                            backgroundColor={theme.background.raised.base}
                            flexDirection="row"
                          >
                            <Show when={multi()}>
                              <text
                                width={4}
                                flexShrink={0}
                                fg={
                                  active()
                                    ? theme.text.formfield.focused
                                    : picked()
                                      ? theme.text.formfield.selected
                                      : theme.text.muted
                                }
                              >
                                [{picked() ? "✓" : " "}]
                              </text>
                            </Show>
                            <text fg={active() ? theme.text.formfield.focused : theme.text.formfield.base}>
                              {row.label}
                            </text>
                          </box>
                          <Show when={!multi()}>
                            <text fg={theme.text.formfield.selected}>{picked() ? " ✓" : ""}</text>
                          </Show>
                        </box>
                        <Show when={row.description}>
                          <box paddingLeft={multi() ? 7 : 3}>
                            <text fg={theme.text.muted}>{row.description}</text>
                          </box>
                        </Show>
                      </box>
                    )
                  }}
                </For>
                <Show when={custom()}>
                  <box
                    onMouseMove={() => setStore("selected", rows().length)}
                    onMouseDown={() => setStore("selected", rows().length)}
                    onMouseUp={() => {
                      if (renderer.getSelection()?.getSelectedText()) return
                      selectOption()
                    }}
                  >
                    <box flexDirection="row">
                      <box
                        backgroundColor={theme.background.raised.base}
                        paddingRight={1}
                      >
                        <text fg={other() ? theme.text.formfield.focused : theme.text.muted}>
                          {`${rows().length + 1}.`}
                        </text>
                      </box>
                      <box
                        flexDirection="row"
                        flexGrow={1}
                        backgroundColor={theme.background.raised.base}
                      >
                        <Show when={multi()}>
                          <text
                            width={4}
                            flexShrink={0}
                            fg={
                              other()
                                ? theme.text.formfield.focused
                                : customChecked()
                                  ? theme.text.formfield.selected
                                  : theme.text.muted
                            }
                          >
                            [{customChecked() ? "✓" : " "}]
                          </text>
                        </Show>
                        <Show
                          when={store.editing}
                          fallback={
                            <>
                              <text fg={other() ? theme.text.formfield.focused : theme.text.formfield.base}>
                                {input() || "Type your own answer"}
                              </text>
                              <Show when={!multi() && customPicked()}>
                                <text fg={theme.text.formfield.selected}>✓</text>
                              </Show>
                            </>
                          }
                        >
                          <textarea
                            flexGrow={1}
                            cursorStyle={config.cursor}
                            ref={(val: TextareaRenderable) => {
                              textarea = val
                              val.traits = { status: "ANSWER" }
                              queueMicrotask(() => {
                                if (val.isDestroyed) return
                                val.setText(input())
                                val.gotoLineEnd()
                                setInputTarget(val)
                              })
                            }}
                            initialValue={input()}
                            placeholder="Type your own answer"
                            placeholderColor={theme.text.muted}
                            minHeight={1}
                            maxHeight={6}
                            textColor={theme.text.formfield.focused}
                            focusedTextColor={theme.text.formfield.focused}
                            cursorColor={theme.text.formfield.focused}
                            onContentChange={(value) => {
                              const current = answerField()
                              if (!current || !textarea || textarea.isDestroyed) return
                              updateCustom(current, typeof value === "string" ? value : textarea.plainText)
                            }}
                          />
                        </Show>
                      </box>
                    </box>
                  </box>
                </Show>
              </box>
            </Show>
          </box>
        </Show>

        <Show when={confirm()}>
          <scrollbox
            maxHeight={reviewMaxHeight()}
            contentOptions={{ minHeight: 0 }}
            scrollbarOptions={{ visible: false }}
            ref={(r: ScrollBoxRenderable) => (review = r)}
          >
            <box
              onSizeChange={function (this: BoxRenderable) {
                setReviewContentHeight(this.height)
              }}
            >
              <For each={fields()}>
                {(item) => {
                  if (item.type === "external") {
                    const acknowledged = () => store.answers[item.key] === true
                    return (
                      <box paddingLeft={1}>
                        <text>
                          <span style={{ fg: theme.text.muted }}>{truncate(formLabel(item), 40)}:</span>{" "}
                          <span
                            style={{
                              fg: acknowledged()
                                ? theme.text.feedback.success.base
                                : theme.text.feedback.error.base,
                            }}
                          >
                            {acknowledged() ? "Acknowledged" : "(acknowledgement required)"}
                          </span>
                        </text>
                      </box>
                    )
                  }
                  const value = () => formDisplayValue(item, store.answers[item.key], "(none)")
                  const answered = () => store.answers[item.key] !== undefined
                  const missing = () => !answered() && item.required === true
                  const invalid = () => formValidateValue(item, store.answers[item.key])
                  return (
                    <box paddingLeft={1}>
                      <text>
                        <span style={{ fg: theme.text.muted }}>{truncate(formLabel(item), 40)}:</span>{" "}
                        <span
                          style={{
                            fg:
                              invalid() || missing()
                                ? theme.text.feedback.error.base
                                : answered()
                                  ? theme.text.base
                                  : theme.text.muted,
                          }}
                        >
                          {invalid() ?? (answered() ? value() : missing() ? "(required)" : "(not answered)")}
                        </span>
                      </text>
                    </box>
                  )
                }}
              </For>
            </box>
          </scrollbox>
        </Show>
      </box>
      <box
        flexDirection="row"
        flexShrink={0}
        gap={1}
        paddingLeft={2}
        paddingRight={3}
        paddingBottom={1}
        justifyContent="space-between"
      >
        <box flexDirection="row" gap={2}>
          <Show when={!single()}>
            <text fg={theme.text.base}>
              {"⇆"} <span style={{ fg: theme.text.muted }}>tab</span>
            </text>
          </Show>
          <Show when={!confirm() && !textual() && !externalField() && !store.editing}>
            <text fg={theme.text.base}>
              {"↑↓"} <span style={{ fg: theme.text.muted }}>select</span>
            </text>
          </Show>
          <Show when={confirm() && reviewContentHeight() > reviewMaxHeight()}>
            <text fg={theme.text.base}>
              {"↑↓"} <span style={{ fg: theme.text.muted }}>scroll</span>
            </text>
          </Show>
          <text
            fg={theme.text.base}
            onMouseUp={() => {
              if (renderer.getSelection()?.getSelectedText()) return
              if (confirm()) submit()
              if (externalField()) acknowledgeExternal()
            }}
          >
            enter <span style={{ fg: theme.text.muted }}>{actionLabel()}</span>
          </text>
          <Show when={externalField()}>
            <text fg={theme.text.base} onMouseUp={copyExternal}>
              c <span style={{ fg: theme.text.muted }}>copy</span>
            </text>
          </Show>
          <text fg={theme.text.base} onMouseUp={cancel}>
            esc <span style={{ fg: theme.text.muted }}>{store.editing && !textual() ? "close" : "dismiss"}</span>
          </text>
        </box>
        <Show when={store.error}>
          <text fg={theme.text.feedback.error.base}>{store.error}</text>
        </Show>
      </box>
    </box>
  )
}

import { createMemo, createSignal, For, Match, Show, Switch } from "solid-js"
import { RGBA, type Renderable } from "@opentui/core"
import { useRenderer, type JSX } from "@opentui/solid"
import type { SessionMessageAssistantTool, SessionMessageInfo } from "@opencode/client"
import { createSyntaxStyleMemo, useTheme, useThemes } from "../../context/theme"
import { reasoningSummary } from "../../context/thinking"
import { SplitBorder } from "../../ui/border"
import { Locale } from "../../util/locale"
import { EntryAnchor, GroupAnchor, visitEntries } from "./anchor-view"
import { groupID } from "./anchors"
import { instructionPaths, type PartRef, type SessionEntry, type SessionGroup, type SessionNode } from "./grouping/session"
import { summarizeActivity } from "./activity-summary"
import { InlineToolRow, reasoningContent, toolDisplay } from "./message-parts"
import { use } from "./render-context"
import { resolvePart } from "./rows"
import { generateThinkingSyntax } from "./thinking-syntax"

type Renderers = {
  message: (messageID: string) => SessionMessageInfo | undefined
  entry: (entry: SessionEntry, images?: boolean) => JSX.Element
  images: (parts: readonly SessionMessageAssistantTool[]) => JSX.Element
}

type GroupProps = Renderers & {
  node: Extract<SessionNode, { type: "group" }>
  level: number
  completed: boolean
  pending: readonly PartRef[]
  pendingOutside?: boolean
  imagesOutside?: boolean
}

export function SessionGroupView(props: Renderers & { row: SessionGroup }) {
  return (
    <Group
      {...props}
      node={props.row}
      level={0}
      completed={props.row.completed}
      pending={props.row.kind === "exploration" || props.row.kind === "activity" ? props.row.pending : []}
    />
  )
}

function Group(props: GroupProps) {
  // Keep kind-specific hover/title state isolated during reconciliation.
  return (
    <Show when={props.node.kind} keyed>
      {(kind) => (
        <Switch fallback={<GroupContent {...props} />}>
          <Match when={kind === "activity"}>
            <ActivityGroup {...props} />
          </Match>
          <Match when={kind === "instructions"}>
            <InstructionsGroup {...props} />
          </Match>
        </Switch>
      )}
    </Show>
  )
}

function GroupContent(props: GroupProps) {
  const ctx = use()
  const theme = useTheme()
  const disclosure = useDisclosure(props)
  const id = disclosure.id
  const expanded = disclosure.expanded
  const [hover, setHover] = createSignal(false)
  const entries = createMemo(() => descendants(props.node))
  const refs = createMemo(() =>
    entries().flatMap((entry) => (entry.type === "part" && !isPending(entry, props.pending) ? [entry.ref] : [])),
  )
  const thoughts = createMemo(() =>
    props.node.kind !== "reasoning"
      ? []
      : refs().flatMap((ref) => {
          const message = props.message(ref.messageID)
          if (message?.type !== "assistant") return []
          const part = resolvePart(message, ref.partID)
          if (part?.type !== "reasoning" || !reasoningContent(part)) return []
          return [{ message, part }]
        }),
  )
  const tools = createMemo(() =>
    props.node.kind !== "exploration"
      ? []
      : refs().flatMap((ref) => {
          const message = props.message(ref.messageID)
          if (message?.type !== "assistant") return []
          const part = resolvePart(message, ref.partID)
          return part?.type === "tool" ? [part] : []
        }),
  )
  const latest = createMemo((previous: string | null) => {
    const item = thoughts().at(-1)
    if (!item) return previous
    const title = reasoningSummary(reasoningContent(item.part)).title
    if (title) return title
    if (item.part.time?.completed !== undefined || item.message.time.completed !== undefined) return null
    return previous
  }, null)
  const duration = createMemo(() =>
    thoughts().reduce((total, item) => {
      const start = item.part.time?.created
      const end = item.part.time?.completed
      return total + (start === undefined || end === undefined ? 0 : Math.max(0, end - start))
    }, 0),
  )
  const grouped = () => (props.node.kind === "reasoning" ? ctx.thinkingMode() === "hide" : ctx.groupExploration())
  const completed = () =>
    props.node.kind === "reasoning"
      ? props.completed
      : props.completed || (tools().length > 0 && tools().every((part) => part.time.completed !== undefined))
  const label = createMemo(() => {
    const counts = tools().reduce<Record<string, number>>((result, part) => {
      const tool = toolDisplay(part.name)
      const name =
        tool === "grep" || tool === "glob" || tool === "websearch" ? "search" : tool === "webfetch" ? "fetch" : tool
      result[name] = (result[name] ?? 0) + 1
      return result
    }, {})
    const names = Object.entries(counts).map(
      ([name, count]) =>
        `${count} ${count === 1 ? name : name === "search" || name === "fetch" ? `${name}es` : `${name}s`}`,
    )
    return `${completed() ? "Explored" : "Exploring"}: ${names.join(", ")}`
  })
  const toggle = () => disclosure.toggle()
  const children = (mode: "normal" | "thought" | "tool") => (
    <Children {...props} nodes={props.node.children} mode={mode} />
  )

  return (
    <GroupAnchor
      groupID={id()}
      active={grouped() && (props.node.kind === "reasoning" ? thoughts().length > 0 : tools().length > 0)}
    >
      <Show
        when={props.node.kind === "reasoning"}
        fallback={
          <Show when={grouped()} fallback={children("normal")}>
            <Show when={tools().length > 0}>
              <InlineToolRow
                icon={completed() ? "→" : "✱"}
                color={hover() ? theme.text.base : theme.text.muted}
                complete={completed()}
                pending={label()}
                spinner={!completed()}
                onMouseOver={() => setHover(true)}
                onMouseOut={() => setHover(false)}
                onMouseUp={toggle}
              >
                {label()}
              </InlineToolRow>
            </Show>
            <Show when={expanded() && tools().length > 0}>{children("tool")}</Show>
            <Show when={!props.imagesOutside}>{props.images(tools())}</Show>
          </Show>
        }
      >
        <Show when={thoughts().length > 0}>
          <Show when={grouped()} fallback={children("normal")}>
            <InlineToolRow
              icon={expanded() ? "-" : "+"}
              color={
                !props.completed
                  ? theme.text.base
                  : hover() || expanded()
                    ? theme.text.feedback.warning.base
                    : RGBA.fromValues(
                        theme.text.feedback.warning.base.r,
                        theme.text.feedback.warning.base.g,
                        theme.text.feedback.warning.base.b,
                        0.6,
                      )
              }
              complete={props.completed}
              pending={latest() ? `Thinking: ${latest()}` : "Thinking"}
              spinner={!props.completed}
              onMouseOver={() => setHover(true)}
              onMouseOut={() => setHover(false)}
              onMouseUp={toggle}
            >
              {props.completed ? "Thought" : latest() ? `Thinking: ${latest()}` : "Thinking"}
              <Show when={props.completed && !expanded() && latest()}>: {latest()}</Show>
              <Show when={props.completed && thoughts().length > 1}> · {thoughts().length} steps</Show>
              <Show when={props.completed && duration()}> · {Locale.duration(duration())}</Show>
            </InlineToolRow>
            <Show when={expanded()}>
              <box paddingLeft={3}>{children("thought")}</box>
            </Show>
          </Show>
        </Show>
      </Show>
      <PendingEntries {...props} entries={entries()} />
    </GroupAnchor>
  )
}

/** Low verbosity: one summary for a run of tools, thoughts and instruction loads. */
function ActivityGroup(props: GroupProps) {
  const theme = useTheme()
  const disclosure = useDisclosure(props)
  const [hover, setHover] = createSignal(false)
  const entries = createMemo(() => descendants(props.node))
  const summary = createMemo(() => summarizeActivity(props.node, props.message, props.pending, props.completed))
  return (
    <GroupAnchor groupID={disclosure.id()} active={summary().label !== ""}>
      <Show when={summary().label}>
        <InlineToolRow
          icon={disclosure.expanded() ? "−" : "+"}
          color={hover() ? theme.text.base : theme.text.muted}
          complete={true}
          pending={summary().label}
          spinner={!disclosure.expanded() && summary().active}
          onMouseOver={() => setHover(true)}
          onMouseOut={() => setHover(false)}
          onMouseUp={(event) => disclosure.toggle(event.currentTarget)}
        >
          {summary().label}
        </InlineToolRow>
        <Show when={disclosure.expanded()}>
          <box flexDirection="column" gap={1} marginTop={1}>
            <Children {...props} nodes={props.node.children} mode="normal" />
          </box>
        </Show>
      </Show>
      <PendingEntries {...props} entries={entries()} />
    </GroupAnchor>
  )
}

/** Consecutive instruction loads, summarized by the number of distinct files. */
function InstructionsGroup(props: GroupProps) {
  const theme = useTheme()
  const disclosure = useDisclosure(props)
  const [hover, setHover] = createSignal(false)
  const files = createMemo(
    () =>
      new Set(
        descendants(props.node).flatMap((entry) =>
          entry.type === "message" ? instructionPaths(props.message(entry.messageID)) : [],
        ),
      ).size,
  )
  return (
    <GroupAnchor groupID={disclosure.id()} active={files() > 0}>
      <InlineToolRow
        icon="◈"
        color={hover() ? theme.text.base : theme.text.muted}
        complete={true}
        pending=""
        onMouseOver={() => setHover(true)}
        onMouseOut={() => setHover(false)}
        onMouseUp={() => disclosure.toggle()}
      >
        Instructions: {files()} {files() === 1 ? "file" : "files"}
      </InlineToolRow>
      <Show when={disclosure.expanded()}>
        <Children {...props} nodes={props.node.children} mode="normal" />
      </Show>
    </GroupAnchor>
  )
}

function useDisclosure(props: GroupProps) {
  const ctx = use()
  const renderer = useRenderer()
  const id = createMemo(() => groupID(props.node, props.level))
  const expanded = () => {
    const key = id()
    return key ? ctx.groupExpanded(key, props.node.kind) : false
  }
  return {
    id,
    expanded,
    toggle(anchor?: Renderable | null) {
      if (renderer.getSelection()?.getSelectedText()) return
      const key = id()
      if (key) ctx.setGroupExpanded(key, !expanded(), anchor)
    },
  }
}

function descendants(node: Extract<SessionNode, { type: "group" }>) {
  const result: SessionEntry[] = []
  visitEntries(node.children, (entry) => result.push(entry))
  return result
}

/** Permission-blocked tools stay visible below the root group, even when collapsed. */
function PendingEntries(props: GroupProps & { entries: readonly SessionEntry[] }) {
  return (
    <Show when={!props.pendingOutside}>
      <For each={props.pending}>
        {(ref) => {
          const leaf = createMemo(() =>
            props.entries.find(
              (entry) =>
                entry.type === "part" && entry.ref.messageID === ref.messageID && entry.ref.partID === ref.partID,
            ),
          )
          return <Show when={leaf()}>{(item) => <EntryAnchor entry={item()}>{props.entry(item())}</EntryAnchor>}</Show>
        }}
      </For>
    </Show>
  )
}

function Children(props: GroupProps & { nodes: readonly SessionNode[]; mode: "normal" | "thought" | "tool" }) {
  return (
    <For each={props.nodes}>
      {(node, index) => {
        return (
          <Switch>
            <Match when={node.type === "group" ? node : undefined}>
              {(node) => (
                <Group
                  {...props}
                  node={node()}
                  level={props.level + 1}
                  pendingOutside
                  imagesOutside={props.imagesOutside || props.mode === "tool"}
                  completed={
                    props.completed ||
                    props.nodes
                      .slice(index() + 1)
                      .some((next) => next.type === "group" || !isPending(next.entry, props.pending)) ||
                    (node().kind === "reasoning" && reasoningCompleted(node().children, props.message))
                  }
                />
              )}
            </Match>
            <Match when={node.type === "entry" ? node : undefined}>
              {(node) => (
                <Show when={!isPending(node().entry, props.pending)}>
                  <Show
                    when={props.mode === "thought"}
                    fallback={
                      <EntryAnchor entry={node().entry}>
                        {props.entry(node().entry, props.mode === "tool" ? false : undefined)}
                      </EntryAnchor>
                    }
                  >
                    <ThoughtEntry entry={node().entry} message={props.message} />
                  </Show>
                </Show>
              )}
            </Match>
          </Switch>
        )
      }}
    </For>
  )
}

function ThoughtEntry(props: { entry: SessionEntry; message: Renderers["message"] }) {
  const ctx = use()
  const theme = useTheme()
  const { currentSyntax: syntax } = useThemes()
  const thinkingSyntax = createSyntaxStyleMemo(() => generateThinkingSyntax(syntax(), theme.text.muted))
  const message = createMemo(() => {
    if (props.entry.type !== "part") return
    const item = props.message(props.entry.ref.messageID)
    return item?.type === "assistant" ? item : undefined
  })
  const part = createMemo(() => {
    const item = message()
    if (!item || props.entry.type !== "part") return
    const part = resolvePart(item, props.entry.ref.partID)
    return part?.type === "reasoning" ? part : undefined
  })
  const content = createMemo(() => {
    const item = part()
    return item ? reasoningContent(item) : ""
  })
  return (
    <Show when={content()}>
      <EntryAnchor entry={props.entry} marginTop={1}>
        <box
          border={["left"]}
          customBorderChars={SplitBorder.customBorderChars}
          borderColor={theme.decrease(theme.background.raised.base)}
          paddingLeft={1}
        >
          <code
            filetype="markdown"
            drawUnstyledText={false}
            streaming={part()?.time?.completed === undefined && message()?.time.completed === undefined}
            syntaxStyle={thinkingSyntax()}
            content={content()}
            conceal={ctx.markdownMode() === "rendered"}
            fg={theme.text.muted}
          />
        </box>
      </EntryAnchor>
    </Show>
  )
}

function isPending(entry: SessionEntry, pending: readonly PartRef[]) {
  return (
    entry.type === "part" &&
    pending.some((ref) => ref.messageID === entry.ref.messageID && ref.partID === entry.ref.partID)
  )
}

function reasoningCompleted(nodes: readonly SessionNode[], message: Renderers["message"]): boolean {
  return nodes.every((node) => {
    if (node.type === "group") return reasoningCompleted(node.children, message)
    if (node.entry.type !== "part") return false
    const item = message(node.entry.ref.messageID)
    if (item?.type !== "assistant") return false
    const part = resolvePart(item, node.entry.ref.partID)
    return part?.type === "reasoning" && part.time?.completed !== undefined
  })
}

import type { SessionMessageAssistant, SessionMessageInfo } from "@opencode/client"
import { groupEntries, mergeGroups, splitGroups, type GroupNode } from "./tree"

export type PartRef = {
  messageID: string
  partID: string
}

export type CacheUsage = {
  read: number
  model: SessionMessageAssistant["model"]
}

export type SessionEntry =
  | { type: "message"; messageID: string }
  | { type: "compaction-queued"; inboxID: string }
  | { type: "part"; ref: PartRef }
  | { type: "assistant-footer"; messageID: string }
  | { type: "turn-usage"; messageIDs: string[]; previousCache?: CacheUsage }

export type GroupKind = "activity" | "reasoning" | "exploration" | "instructions"
export type SessionNode = GroupNode<SessionEntry, GroupKind>
export type SessionGroup = {
  type: "group"
  children: readonly GroupNode<SessionEntry, GroupKind>[]
  size: number
  completed: boolean
} & ({ kind: "reasoning" | "instructions" } | { kind: "exploration" | "activity"; pending: PartRef[] })

/** Experimental transcript detail; undefined selects the default production rules. */
export type Verbosity = "low" | "medium" | "high"
export const defaultVerbosity: Verbosity = "medium"

export type SessionRow = SessionEntry | SessionGroup

export type AppendPart =
  | { type: "text" }
  | { type: "reasoning"; time?: { completed?: number } }
  | { type: "tool"; name: string }

export type ProjectionEntry = {
  entry: SessionEntry
  part?: AppendPart
  path?: readonly GroupKind[]
  closesPrevious?: boolean
}

/** Hydrate a fresh history batch in one pass rather than merging one leaf at a time. */
export function projectEntries(entries: ProjectionEntry[]): SessionRow[] {
  const nodes = groupEntries(entries, (item) => item.path ?? [])
  return nodes.map((node, index) => {
    if (node.type === "entry") return node.entry.entry
    const next = nodes[index + 1]
    const completed =
      (next !== undefined && (next.type === "group" || next.entry.closesPrevious !== false)) ||
      (node.kind === "reasoning" &&
        node.children.every(
          (child) =>
            child.type === "entry" &&
            child.entry.part?.type === "reasoning" &&
            child.entry.part.time?.completed !== undefined,
        ))
    return sessionGroup({ ...node, children: node.children.map(unwrap) }, completed)
  })
}

function sessionGroup(node: Extract<SessionNode, { type: "group" }>, completed: boolean): SessionGroup {
  if (node.kind === "exploration" || node.kind === "activity")
    return { ...node, kind: node.kind, pending: [], completed }
  return { ...node, kind: node.kind, completed }
}

function unwrap(node: GroupNode<ProjectionEntry, GroupKind>): GroupNode<SessionEntry, GroupKind> {
  if (node.type === "entry") return { ...node, entry: node.entry.entry }
  return { ...node, children: node.children.map(unwrap) }
}

const explorationTools = new Set(["read", "glob", "grep", "webfetch", "websearch"])

/**
 * Grouping path for an assistant part. Adjacent thoughts group, as do reads, searches
 * and web fetches. Low wraps every run of tools and thoughts in one activity summary.
 * Questions always stand alone.
 */
export function partPath(part: AppendPart, verbosity: Verbosity): readonly GroupKind[] {
  if (part.type === "tool" && part.name.toLowerCase() === "question") return []
  const activity: GroupKind[] = verbosity === "low" && part.type !== "text" ? ["activity"] : []
  if (part.type === "reasoning") return [...activity, "reasoning"]
  if (part.type === "tool" && explorationTools.has(part.name.toLowerCase())) return [...activity, "exploration"]
  return activity
}

/** Instruction loads group; other messages stand alone. */
export function messagePath(message: SessionMessageInfo, verbosity: Verbosity): readonly GroupKind[] {
  if (instructionPaths(message).length === 0) return []
  return verbosity === "low" ? ["activity", "instructions"] : ["instructions"]
}

/** Files loaded by an instruction message; one load can carry several. */
export function instructionPaths(message: SessionMessageInfo | undefined): string[] {
  if (message?.type !== "synthetic") return []
  const instruction = message.metadata?.instruction
  if (typeof instruction !== "object" || instruction === null || Array.isArray(instruction)) return []
  return Array.isArray(instruction.paths)
    ? instruction.paths.filter((path): path is string => typeof path === "string")
    : []
}

/** Production rules only: keep lifecycle/status decisions outside the tree engine. */
export function append(
  rows: SessionRow[],
  ref: PartRef,
  part: AppendPart,
  index = rows.length,
  verbosity = defaultVerbosity,
) {
  const [node] = groupEntries<SessionEntry, GroupKind>([{ type: "part", ref }], () => partPath(part, verbosity))
  if (node.type === "entry") {
    completePrevious(rows, index)
    rows.splice(index, 0, node.entry)
    return
  }
  const previous = rows[index - 1]
  if (previous?.type === "group" && previous.kind === node.kind) {
    // Permission-blocked tools remain at the end, just as the former refs/pending
    // partition did. Inserting a new ref must precede those blocked tools.
    const pending = previous.kind === "exploration" ? previous.pending.length : 0
    const [left, right] = splitGroups([previous], previous.size - pending)
    const [merged] = mergeGroups(mergeGroups(left, [node]), right)
    if (merged.type !== "group") throw new Error("Expected merged session group")
    previous.children = merged.children
    previous.size = merged.size
    if (part.type === "reasoning") previous.completed &&= part.time?.completed !== undefined
    return
  }
  completePrevious(rows, index)
  rows.splice(
    index,
    0,
    sessionGroup(node, node.kind === "reasoning" && part.type === "reasoning" && part.time?.completed !== undefined),
  )
}

export function completePrevious(rows: SessionRow[], index = rows.length) {
  const previous = rows[index - 1]
  if (previous?.type === "group") previous.completed = true
}

/** Part references for an existing production subgroup, not a flat timeline. */
export function groupRefs(row: SessionGroup, includePending = false): PartRef[] {
  const pending = !includePending && (row.kind === "exploration" || row.kind === "activity") ? row.pending : []
  const visit = (nodes: readonly GroupNode<SessionEntry, GroupKind>[]): PartRef[] =>
    nodes.flatMap((node) => {
      if (node.type === "group") return visit(node.children)
      if (node.entry.type !== "part") return []
      const ref = node.entry.ref
      if (pending.some((item) => item.messageID === ref.messageID && item.partID === ref.partID)) return []
      return [ref]
    })
  return visit(row.children)
}

export function partitionPending(rows: SessionRow[], pending: Set<string>) {
  rows.forEach((row) => {
    if (row.type !== "group" || (row.kind !== "exploration" && row.kind !== "activity")) return
    // The production exploration rule creates direct part children. Preserve the
    // existing stable partition order when permissions are admitted or dismissed.
    // Activity groups render blocked tools outside the summary without reordering.
    if (row.kind === "exploration") {
      const blocked = (node: GroupNode<SessionEntry, GroupKind>) =>
        node.type === "entry" && node.entry.type === "part" && pending.has(node.entry.ref.partID)
      row.children = [...row.children.filter((node) => !blocked(node)), ...row.children.filter(blocked)]
    }
    row.pending = groupRefs(row, true).filter((ref) => pending.has(ref.partID))
  })
}

export function hasPart(rows: SessionRow[], ref: PartRef) {
  return rows.some((row) => {
    if (row.type === "part") return row.ref.messageID === ref.messageID && row.ref.partID === ref.partID
    if (row.type !== "group") return false
    return groupRefs(row, true).some((item) => item.messageID === ref.messageID && item.partID === ref.partID)
  })
}

export type GroupNode<Entry, Kind extends string> =
  | { readonly type: "entry"; readonly entry: Entry; readonly size: 1 }
  | {
      readonly type: "group"
      readonly kind: Kind
      readonly children: readonly GroupNode<Entry, Kind>[]
      /** Number of descendant leaves, independent of disclosure state. */
      readonly size: number
    }

/**
 * Group adjacent entries by their configured nesting paths. For example, a read
 * can use ["exploration"] today or ["activity", "exploration"] in Low.
 * Entries are opaque: message/part identity, visibility and live state remain
 * owned by the session projection. A path of [] creates a standalone leaf.
 */
export function groupEntries<Entry, Kind extends string>(
  entries: readonly Entry[],
  path: (entry: Entry) => readonly Kind[],
): readonly GroupNode<Entry, Kind>[] {
  const result: BuildingNode<Entry, Kind>[] = []
  entries.forEach((entry) => {
    appendEntry(result, entry, path(entry))
  })
  return result
}

// Only freshly constructed nodes are writable; the published tree is readonly.
type BuildingNode<Entry, Kind extends string> =
  | { type: "entry"; entry: Entry; size: 1 }
  | { type: "group"; kind: Kind; children: BuildingNode<Entry, Kind>[]; size: number }

function appendEntry<Entry, Kind extends string>(
  nodes: BuildingNode<Entry, Kind>[],
  entry: Entry,
  path: readonly Kind[],
  depth = 0,
) {
  const kind = path[depth]
  if (kind === undefined) {
    nodes.push({ type: "entry", entry, size: 1 })
    return
  }
  const previous = nodes.at(-1)
  if (previous?.type === "group" && previous.kind === kind) {
    previous.size++
    appendEntry(previous.children, entry, path, depth + 1)
    return
  }
  const children: BuildingNode<Entry, Kind>[] = []
  appendEntry(children, entry, path, depth + 1)
  nodes.push({ type: "group", kind, children, size: 1 })
}

/**
 * Concatenate ordered, disjoint chunks, recursively merging compatible groups
 * at their seam. Untouched subtrees retain their object identity.
 *
 * This is concatenation, not ingestion: callers must reconcile overlapping
 * pages/replayed message IDs before merging. Equal payloads may be distinct
 * entries and must not be silently deduplicated here.
 */
export function mergeGroups<Entry, Kind extends string>(
  left: readonly GroupNode<Entry, Kind>[],
  right: readonly GroupNode<Entry, Kind>[],
): readonly GroupNode<Entry, Kind>[] {
  if (!left.length) return right
  if (!right.length) return left
  const a = left[left.length - 1]
  const b = right[0]
  if (a.type !== "group" || b.type !== "group" || a.kind !== b.kind) return [...left, ...right]
  return [
    ...left.slice(0, -1),
    {
      type: "group",
      kind: a.kind,
      size: a.size + b.size,
      children: mergeGroups(a.children, b.children),
    },
    ...right.slice(1),
  ]
}

/**
 * Split at a depth-first leaf offset. Group headers count as zero. Cached sizes
 * skip whole subtrees; only the ancestors crossing the cut are reconstructed.
 * The returned halves can be seam-merged again without changing their meaning.
 */
export function splitGroups<Entry, Kind extends string>(
  nodes: readonly GroupNode<Entry, Kind>[],
  count: number,
): readonly [readonly GroupNode<Entry, Kind>[], readonly GroupNode<Entry, Kind>[]] {
  if (!Number.isInteger(count) || count < 0) throw new RangeError("Group split requires a non-negative integer")
  if (count === 0) return [[], nodes]
  let offset = 0
  for (const [index, node] of nodes.entries()) {
    const end = offset + node.size
    if (count === end) return [nodes.slice(0, index + 1), nodes.slice(index + 1)]
    if (count < end) {
      if (node.type !== "group") throw new RangeError("Cannot split inside an entry")
      const size = count - offset
      const [left, right] = splitGroups(node.children, size)
      return [
        [...nodes.slice(0, index), { ...node, children: left, size }],
        [{ ...node, children: right, size: node.size - size }, ...nodes.slice(index + 1)],
      ]
    }
    offset = end
  }
  throw new RangeError("Group split exceeds entry count")
}

export function createHistoryPrepend(input: {
  sessionID: () => string
  more: (sessionID: string) => boolean
  loadMore: (sessionID: string) => Promise<void>
  height: () => number
  afterLayout: (continuation: () => void) => void
  active: (sessionID: string) => boolean
  scrollBy: (amount: number) => void
}) {
  let pending: { scrollBy: number; continuation?: () => void; after?: () => void } | undefined

  return Object.assign(
    (scrollBy = 0, continuation?: () => void) => {
      const sessionID = input.sessionID()
      if (pending) {
        if (continuation || (!pending.scrollBy && scrollBy)) {
          pending.scrollBy = scrollBy
          pending.continuation = continuation
          return true
        }
        return false
      }
      if (!input.more(sessionID)) return false
      const current = { scrollBy, continuation }
      pending = current
      const before = input.height()
      void input.loadMore(sessionID).then(
        () =>
          input.afterLayout(() => {
            if (pending !== current) return
            const after = pending.after
            pending = undefined
            if (!input.active(sessionID)) return
            input.scrollBy(input.height() - before + current.scrollBy)
            current.continuation?.()
            after?.()
          }),
        () => {
          if (pending !== current) return
          const after = pending.after
          pending = undefined
          if (input.active(sessionID)) after?.()
        },
      )
      return true
    },
    {
      cancel() {
        if (!pending) return
        pending.continuation = undefined
        pending.after = undefined
      },
      after(continuation: () => void) {
        if (!pending) return continuation()
        // A jump supersedes deferred scrolling, but must wait for anchor compensation.
        pending.scrollBy = 0
        pending.after = continuation
      },
    },
  )
}

