}

function stringValue(value: unknown) {
  return typeof value === "string" ? value : undefined
}

function recordValue(value: unknown): Record<string, unknown> | undefined {
  return isRecord(value) ? value : undefined
}

function formatSessionTranscript(
  session: SessionInfo,
  messages: SessionMessageInfo[],
  thinking: boolean,
  tools = true,
) {
  const body = messages.flatMap((message) => {
    if (message.type === "user") return [`## User\n\n${message.text}`]
    if (message.type === "shell")
      return [`## Shell\n\n\`\`\`\n$ ${message.command}\n${message.output?.output ?? ""}\n\`\`\``]
    if (message.type !== "assistant") return []
    const content = message.content.flatMap((item) => {
      if (item.type === "text") return [item.text]
      if (item.type === "reasoning") return thinking ? [`_Thinking:_\n\n${item.text}`] : []
      if (!tools) return []
      const input = typeof item.state.input === "string" ? item.state.input : JSON.stringify(item.state.input, null, 2)
      const output =
        item.state.status === "error"
          ? item.state.error.message
          : item.state.status === "streaming"
            ? ""
            : toolDisplayContent(item.state)
                .flatMap((entry) => (entry.type === "text" ? [entry.text] : [entry.name ?? entry.uri]))
                .join("\n")
      return [`**Tool: ${item.name}**\n\n**Input:**\n\`\`\`json\n${input}\n\`\`\`\n\n${output}`]
    })
    if (content.length === 0) return []
    return [`## Assistant\n\n${content.join("\n\n")}`]
  })
  return `# ${withTimestampedFallback(session)}\n\n**Session ID:** ${session.id}\n**Created:** ${new Date(session.time.created).toLocaleString()}\n**Updated:** ${new Date(session.time.updated).toLocaleString()}\n\n---\n\n${body.join("\n\n---\n\n")}\n`
}

export function parseApplyPatchFiles(value: unknown) {
  if (!Array.isArray(value)) return []
  return value.flatMap((item) => {
    const file = recordValue(item)
    if (!file) return []
    const status = stringValue(file.status)
    const type =
      stringValue(file.type) ??
      (status === "added" ? "add" : status === "deleted" ? "delete" : status === "modified" ? "update" : undefined)
    const relativePath = stringValue(file.file) ?? stringValue(file.relativePath)
    const filePath = stringValue(file.filePath) ?? relativePath
    const patch = stringValue(file.patch)
    const additions = finiteNumber(file.additions)
    const deletions = finiteNumber(file.deletions)
    if (
      !type ||
      !relativePath ||
      !filePath ||
      patch === undefined ||
      additions === undefined ||
      deletions === undefined
    )
      return []
    return [{ type, relativePath, filePath, patch, additions, deletions, movePath: stringValue(file.movePath) }]
  })
}

export function parseQuestions(value: unknown) {
  if (!Array.isArray(value)) return []
  return value.flatMap((item) => {
    const question = stringValue(recordValue(item)?.question)
    return question ? [{ question }] : []
  })
}

export function parseQuestionAnswers(value: unknown) {
  if (!Array.isArray(value)) return
  return value.map((answer) =>
    Array.isArray(answer) ? answer.filter((item): item is string => typeof item === "string") : [],
  )
}

export function parseDiagnostics(value: unknown, filePath: string) {
  const diagnostics = recordValue(value)?.[filePath]
  if (!Array.isArray(diagnostics)) return []
  return diagnostics
    .flatMap((item) => {
      const diagnostic = recordValue(item)
      const start = recordValue(recordValue(diagnostic?.range)?.start)
      const line = finiteNumber(start?.line)
      const character = finiteNumber(start?.character)
      const message = stringValue(diagnostic?.message)
      if (diagnostic?.severity !== 1 || line === undefined || character === undefined || !message) return []
      return [{ range: { start: { line, character } }, message }]
    })
    .slice(0, 3)
}

import { createMemo } from "solid-js"
import { useTuiPaths } from "../../context/runtime"
import { useTheme } from "../../context/theme"
import { Locale } from "../../util/locale"
import { abbreviateHome } from "../../util/path-format"
import { SessionQuestion } from "./permission"
import { useDialog } from "../../ui/dialog"
import { useClient } from "../../context/client"
import { useToast } from "../../ui/toast"
import { errorMessage } from "../../util/error"
import { DialogWorkspaces, type WorkspaceSelection } from "../../component/dialog-workspaces"
import { useData } from "../../context/data"

export function SessionLocationMissing(props: { directory: string; projectID: string; sessionID: string }) {
  const dialog = useDialog()
  const client = useClient()
  const toast = useToast()
  const data = useData()

  function open() {
    dialog.replace(() => (
      <DialogWorkspaces
        projectID={props.projectID}
        location={{ directory: props.directory }}
        current={{
          type: "directory",
          directory: props.directory,
          subdirectory: !!data.session.get(props.sessionID)?.subpath,
        }}
        onSelect={(selection) => void select(selection)}
      />
    ))
  }

  async function select(selection: WorkspaceSelection) {
    dialog.clear()
    const directory =
      selection.type === "directory"
        ? selection.directory
        : await client.api.worktree
            .create({ projectID: props.projectID, name: selection.name })
            .then((result) => {
              if (!result.directory) throw new Error("No worktree directory returned")
              return result.directory
            })
            .catch((error) => {
              toast.show({ title: "Creating workspace failed", message: errorMessage(error), variant: "error" })
              return undefined
            })
    if (!directory) return
    await client.api.session.move({ sessionID: props.sessionID, directory }).catch((error) => {
      toast.show({ title: "Failed to move session", message: errorMessage(error), variant: "error" })
    })
  }

  return <SessionLocationUnavailable directory={props.directory} onMove={open} />
}

export function SessionLocationUnavailable(props: { directory: string; onMove: () => void }) {
  const paths = useTuiPaths()
  const theme = useTheme()
  const directory = createMemo(() => Locale.truncateMiddle(abbreviateHome(props.directory, paths.home), 72))

  return (
    <SessionQuestion
      id="session.location-missing"
      group="Session recovery"
      choicesLabel="Recovery actions"
      instance={props.directory}
      title="Session location unavailable"
      body={
        <box paddingLeft={1} gap={1}>
          <text fg={theme.text.muted}>{directory()}</text>
          <text fg={theme.text.base}>Choose another directory to continue this session.</text>
        </box>
      }
      options={{ move: "Choose directory" }}
      onSelect={props.onMove}
    />
  )
}

import type { SessionMessageInfo } from "@opencode/client"

type MessageChild = {
  readonly id?: string
  readonly y: number
}

export function messageNavigationSlack(input: {
  top: number
  viewportHeight: number
  scrollHeight: number
  currentSlack: number
}) {
  const contentHeight = input.scrollHeight - input.currentSlack
  return Math.max(0, Math.ceil(input.top + input.viewportHeight - contentHeight))
}

export function findMessageBoundary(input: {
  direction: "next" | "prev"
  children: readonly MessageChild[]
  messages: readonly SessionMessageInfo[]
  scrollTop: number
  viewportY: number
  currentID?: string
  userOnly?: boolean
}) {
  const messages = new Map(input.messages.map((message) => [message.id, message]))
  const visible = input.children
    .flatMap((child) => {
      if (!child.id) return []
      const message = messages.get(child.id)
      if (!message) return []
      if (message.type === "user" && message.text.trim()) {
        const y = input.scrollTop + child.y - input.viewportY
        return [{ id: child.id, y, top: y }]
      }
      if (input.userOnly || message.type !== "assistant") return []
      if (!message.content.some((content) => content.type === "text" && content.text.trim())) return []
      const y = input.scrollTop + child.y - input.viewportY
      return [{ id: child.id, y, top: Math.max(0, y - 1) }]
    })
    .sort((a, b) => a.y - b.y)

  const current = visible.findIndex((child) => child.id === input.currentID)
  if (current !== -1) return visible[current + (input.direction === "next" ? 1 : -1)] ?? null
  if (input.direction === "next") return visible.find((child) => child.y > input.scrollTop) ?? null
  return visible.findLast((child) => child.y < input.scrollTop) ?? null
}

import { createMemo, createSignal, Match, Show, Switch } from "solid-js"
import { RGBA, TextAttributes, type MouseEvent } from "@opentui/core"
import type { JSX } from "@opentui/solid"
import type {
  SessionMessageAssistant,
  SessionMessageAssistantReasoning,
  SessionMessageAssistantText,
} from "@opencode/client"
import { Spinner } from "../../component/spinner"
import { createSyntaxStyleMemo, useTheme, useThemes } from "../../context/theme"
import { reasoningSummary } from "../../context/thinking"
import { usePlugin } from "../../plugin/context"
import { SplitBorder } from "../../ui/border"
import { Locale } from "../../util/locale"
import { use } from "./render-context"
import { generateThinkingSyntax } from "./thinking-syntax"
import { canonicalToolName } from "../../util/tool-display"

export const INLINE_TOOL_ICON_WIDTH = 2

const toolDisplays = new Set([
  "shell",
  "glob",
  "read",
  "grep",
  "webfetch",
  "websearch",
  "write",
  "edit",
  "subagent",
  "execute",
  "patch",
  "question",
  "skill",
])

export function toolDisplay(tool: string) {
  const normalized = canonicalToolName(tool)
  return toolDisplays.has(normalized) ? normalized : "generic"
}

export function ReasoningPart(props: {
  last: boolean
  part: SessionMessageAssistantReasoning
  message: SessionMessageAssistant
}) {
  const theme = useTheme()
  const { currentSyntax: syntax } = useThemes()
  const thinkingSyntax = createSyntaxStyleMemo(() => generateThinkingSyntax(syntax(), theme.text.muted))
  const ctx = use()
  // Collapsed by default in hide mode: a single line throughout, so the
  // layout never shifts. Click to open the full markdown block, click to close.
  const [expanded, setExpanded] = createSignal(false)

  const content = createMemo(() => reasoningContent(props.part))
  const isDone = createMemo(
    () => props.part.time?.completed !== undefined || props.message.time.completed !== undefined,
  )
  const inMinimal = createMemo(() => ctx.thinkingMode() === "hide")
  const duration = createMemo(() => {
    const end = props.part.time?.completed ?? props.message.time.completed
    const start = props.part.time?.created ?? props.message.time.created
    return end === undefined ? 0 : Math.max(0, end - start)
  })
  const summary = createMemo(() => reasoningSummary(content()))
  const toggle = () => {
    if (!inMinimal()) return
    setExpanded((prev) => !prev)
  }

  return (
    <Show when={content()}>
      <box paddingLeft={3} flexDirection="column" flexShrink={0}>
        <box
          border={!inMinimal() || expanded() ? ["left"] : undefined}
          customBorderChars={SplitBorder.customBorderChars}
          borderColor={theme.decrease(theme.background.base)}
          paddingLeft={!inMinimal() || expanded() ? 1 : 0}
        >
          <box onMouseUp={toggle}>
            <ReasoningHeader
              toggleable={inMinimal()}
              open={!inMinimal() || expanded()}
              done={isDone()}
              title={inMinimal() && !expanded() ? summary().title : null}
              duration={isDone() ? Locale.duration(duration()) : undefined}
            />
          </box>
        </box>
        <Show when={!inMinimal() || expanded()}>
          <box marginTop={1}>
            <box
              border={["left"]}
              customBorderChars={SplitBorder.customBorderChars}
              borderColor={theme.decrease(theme.background.base)}
              paddingLeft={inMinimal() ? 3 : 1}
            >
              <code
                filetype="markdown"
                drawUnstyledText={false}
                streaming={true}
                syntaxStyle={thinkingSyntax()}
                content={content()}
                conceal={ctx.markdownMode() === "rendered"}
                fg={theme.text.muted}
              />
            </box>
          </box>
        </Show>
      </box>
    </Show>
  )
}

export function reasoningContent(part: SessionMessageAssistantReasoning) {
  // OpenRouter encrypts some reasoning blocks; drop the placeholder.
  return part.text.replace("[REDACTED]", "").trim()
}

function ReasoningHeader(props: {
  toggleable: boolean
  open: boolean
  done: boolean
  title: string | null
  duration?: string
}) {
  const theme = useTheme()
  const fg = () =>
    props.open
      ? RGBA.fromValues(
          theme.text.feedback.warning.base.r,
          theme.text.feedback.warning.base.g,
          theme.text.feedback.warning.base.b,
          0.6,
        )
      : theme.text.feedback.warning.base

  return (
    <Switch>
      <Match when={!props.done}>
        <box flexDirection="row">
          <Spinner color={fg()}>{props.title ? "Thinking: " + props.title : "Thinking"}</Spinner>
        </box>
      </Match>
      <Match when={true}>
        <text fg={fg()} wrapMode="none">
          <Show when={props.toggleable}>
            <span>{props.open ? "- " : "+ "}</span>
          </Show>
          <span>Thought</span>
          <Show when={props.title || props.duration}>
            <span>: </span>
          </Show>
          <Show when={props.title}>
            <span>{props.title}</span>
          </Show>
          <Show when={props.duration}>
            <span>
              {props.title ? " · " : ""}
              {props.duration}
            </span>
          </Show>
        </text>
      </Match>
    </Switch>
  )
}

export function TextPart(props: {
  last: boolean
  part: SessionMessageAssistantText
  message: SessionMessageAssistant
}) {
  const ctx = use()
  const theme = useTheme()
  const { currentSyntax: syntax } = useThemes()
  const plugins = usePlugin()
  return (
    <Show when={props.part.text.trim()}>
      <box paddingLeft={3} flexShrink={0}>
        {/* Configure custom nodes before parsing; apply content before streaming so completion keeps the final tokens. */}
        <markdown
          syntaxStyle={syntax()}
          renderNode={plugins.markdown()}
          content={props.part.text.trim()}
          streaming={props.message.time.completed === undefined}
          internalBlockMode="top-level"
          tableOptions={{ style: "grid", cellPaddingX: 1 }}
          conceal={ctx.markdownMode() === "rendered"}
          fg={theme.markdown.text}
          bg={theme.background.base}
        />
      </box>
    </Show>
  )
}

export function InlineToolRow(props: {
  icon: string
  iconColor?: RGBA
  color?: RGBA
  errorColor?: RGBA
  failed?: boolean
  denied?: boolean
  error?: string
  errorExpanded?: boolean
  complete: unknown
  pending: string
  failure?: string
  spinner?: boolean
  status?: JSX.Element
  children: JSX.Element
  onMouseOver?: () => void
  onMouseOut?: () => void
  onMouseUp?: (event: MouseEvent) => void
}) {
  return (
    <box paddingLeft={3} onMouseOver={props.onMouseOver} onMouseOut={props.onMouseOut} onMouseUp={props.onMouseUp}>
      <Switch>
        <Match when={props.spinner}>
          <Show when={props.status} fallback={<Spinner color={props.color} children={props.children} />}>
            {(status) => (
              <box flexDirection="row" gap={1}>
                <Spinner color={props.color} />
                <InlineToolLabel color={props.color} status={status()}>
                  {props.children}
                </InlineToolLabel>
              </box>
            )}
          </Show>
        </Match>
        <Match when={true}>
          <Show fallback={<Spinner color={props.color}>{props.pending}</Spinner>} when={props.complete || props.failed}>
            <box flexDirection="row">
              <text
                width={INLINE_TOOL_ICON_WIDTH}
                fg={props.failed ? props.errorColor : (props.iconColor ?? props.color)}
                attributes={props.denied ? TextAttributes.STRIKETHROUGH : undefined}
              >
                {props.icon}
              </text>
              <Show
                when={props.status}
                fallback={
                  <text
                    flexGrow={1}
                    fg={props.failed ? props.errorColor : props.color}
                    attributes={props.denied ? TextAttributes.STRIKETHROUGH : undefined}
                  >
                    {props.failed && !props.complete ? (props.failure ?? props.children) : props.children}
                  </text>
                }
              >
                {(status) => (
                  <InlineToolLabel
                    color={props.failed ? props.errorColor : props.color}
                    denied={props.denied}
                    status={status()}
                  >
                    {props.failed && !props.complete ? (props.failure ?? props.children) : props.children}
                  </InlineToolLabel>
                )}
              </Show>
            </box>
          </Show>
        </Match>
      </Switch>
      <Show when={props.failed && props.errorExpanded}>
        <box paddingLeft={INLINE_TOOL_ICON_WIDTH}>
          <text fg={props.errorColor}>{props.error}</text>
        </box>
      </Show>
    </box>
  )
}

function InlineToolLabel(props: { color?: RGBA; denied?: boolean; status: JSX.Element; children: JSX.Element }) {
  return (
    <box flexDirection="row" flexWrap="wrap" columnGap={1} flexGrow={1}>
      <text
        maxWidth="100%"
        flexShrink={0}
        fg={props.color}
        attributes={props.denied ? TextAttributes.STRIKETHROUGH : undefined}
      >
        {props.children}
      </text>
      {props.status}
    </box>
  )
}

import { groupID } from "./anchors"
import type { GroupKind, SessionNode, SessionRow } from "./grouping/session"

/**
 * Transcript mounting is budgeted by rendered entries, not rows. A collapsed group
 * renders one header however many parts it holds; an expanded or ungrouped one
 * renders its children. With every group collapsed each row costs one, which is
 * the former row-count budget.
 */
export function rowWeight(
  row: SessionRow,
  input: { expanded: (groupID: string, kind: GroupKind) => boolean; grouped: (kind: GroupKind) => boolean },
) {
  if (row.type !== "group") return 1
  const visit = (node: Extract<SessionNode, { type: "group" }>, level: number): number => {
    if (!input.grouped(node.kind)) return node.size
    const id = groupID(node, level)
    if (!id || !input.expanded(id, node.kind)) return 1
    return node.children.reduce((total, child) => total + (child.type === "group" ? visit(child, level + 1) : 1), 1)
  }
  return visit(row, 0)
}

/** First row index such that rows [index, end) spend at least `budget`. */
export function rowsBefore(weights: readonly number[], end: number, budget: number) {
  let index = end
  let spent = 0
  while (index > 0 && spent < budget) spent += weights[--index]
  return index
}

/** End row index such that rows [start, index) spend at least `budget`. */
export function rowsAfter(weights: readonly number[], start: number, budget: number) {
  let index = start
  let spent = 0
  while (index < weights.length && spent < budget) spent += weights[index++]
  return index
}

import { createStore } from "solid-js/store"
import { createMemo, For, Match, Show, Switch } from "solid-js"
import { Portal, useRenderer, useTerminalDimensions, type JSX } from "@opentui/solid"
import type { TextareaRenderable } from "@opentui/core"
import { useTheme, useThemes } from "../../context/theme"
import type { PermissionReply, PermissionRequest } from "@opencode/client"
import { SplitBorder } from "../../ui/border"
import { useData } from "../../context/data"
import { filetype } from "../../util/filetype"
import { permissionAlwaysLines, permissionOptionLabel, permissionPresentation } from "../../util/permission"
import { getScrollAcceleration } from "../../util/scroll"
import { useConfig } from "../../config"
import { Keymap } from "../../context/keymap"
import { useInteractivity } from "../../context/interactivity"
import { usePathFormatter } from "../../context/path-format"
import { SimulationSemantics } from "../../simulation/semantics"
import { PatchDiff } from "../../component/patch-diff"
import { useToast } from "../../ui/toast"

type PermissionStage = "permission" | "reject"

function EditBody(props: { file?: string; diff?: string; patch?: string }) {
  const theme = useTheme()
  const themes = useThemes()
  const syntax = themes.currentSyntax
  const config = useConfig().data
  const dimensions = useTerminalDimensions()

  const filepath = createMemo(() => props.file ?? "")
  const diff = createMemo(() => props.diff ?? "")

  const view = createMemo(() => {
    const diffView = config.diffs?.view
    if (diffView === "unified") return "unified"
    if (diffView === "split") return "split"
    return dimensions().width > 120 ? "split" : "unified"
  })

  const ft = createMemo(() => filetype(filepath()))
  const scrollAcceleration = createMemo(() => getScrollAcceleration(config))

  return (
    <box flexDirection="column" gap={1}>
      <Show when={diff()}>
        <scrollbox
          height="100%"
          scrollAcceleration={scrollAcceleration()}
          verticalScrollbarOptions={{
            trackOptions: {
              backgroundColor: theme.background.base,
              foregroundColor: theme.scrollbar.base,
            },
          }}
        >
          <PatchDiff
            diff={diff()}
            hunkFg={theme.diff.text.hunkHeader}
            view={view()}
            filetype={ft()}
            syntaxStyle={syntax()}
            showLineNumbers={true}
            width="100%"
            wrapMode="word"
            fg={theme.text.base}
            addedBg={theme.diff.background.added}
            removedBg={theme.diff.background.removed}
            contextBg={theme.diff.background.context}
            addedSignColor={theme.diff.highlight.added}
            removedSignColor={theme.diff.highlight.removed}
            lineNumberFg={theme.diff.lineNumber.text}
            lineNumberBg={theme.diff.background.context}
            addedLineNumberBg={theme.diff.lineNumber.background.added}
            removedLineNumberBg={theme.diff.lineNumber.background.removed}
          />
        </scrollbox>
      </Show>
      <Show when={!diff()}>
        <Show
          when={props.patch}
          fallback={
            <box paddingLeft={1}>
              <text fg={theme.text.muted}>No diff provided</text>
            </box>
          }
        >
          {(patch) => (
            <scrollbox
              height="100%"
              scrollAcceleration={scrollAcceleration()}
              verticalScrollbarOptions={{
                trackOptions: {
                  backgroundColor: theme.background.base,
                  foregroundColor: theme.scrollbar.base,
                },
              }}
            >
              <code
                filetype="diff"
                drawUnstyledText={false}
                streaming={true}
                syntaxStyle={syntax()}
                content={patch()}
                fg={theme.text.muted}
              />
            </scrollbox>
          )}
        </Show>
      </Show>
    </box>
  )
}

export function PermissionPrompt(props: { request: PermissionRequest; directory?: string }) {
  const data = useData()
  const toast = useToast()
  const [store, setStore] = createStore({
    stage: "permission" as PermissionStage,
  })
  const pathFormatter = usePathFormatter()
  const session = createMemo(() => data.session.get(props.request.sessionID))

  const source = createMemo(() => {
    const tool = props.request.source
    if (!tool) return { input: undefined, metadata: undefined }
    const message = data.session.message.get(props.request.sessionID, tool.messageID)
    if (message?.type !== "assistant") return { input: undefined, metadata: undefined }
    const part = message.content.find((part) => part.type === "tool" && part.id === tool.id)
    if (part?.type === "tool" && part.state.status !== "streaming") {
      return { input: part.state.input, metadata: part.state.metadata }
    }
    return { input: undefined, metadata: undefined }
  })

  const theme = useTheme()

  function reply(value: PermissionReply, message?: string) {
    void data.session.permission
      .reply({ sessionID: props.request.sessionID, requestID: props.request.id, decision: value, message })
      .catch((error: unknown) => toast.error(error))
  }

  return (
    <Switch>
      <Match when={store.stage === "reject"}>
        <RejectPrompt
          action={props.request.action}
          instance={props.request.id}
          onConfirm={(message) => {
            reply("reject", message || undefined)
          }}
          onCancel={() => {
            setStore("stage", "permission")
          }}
        />
      </Match>
      <Match when={store.stage === "permission"}>
        {(() => {
          const current = permissionPresentation(
            {
              action: props.request.action,
              resources: props.request.resources,
              metadata: props.request.metadata,
              input: source().input,
              toolMetadata: source().metadata,
            },
            pathFormatter.format,
          )
          const presentationBody = () =>
            props.request.action === "edit" ? (
              <EditBody file={current.file} diff={current.diff} patch={current.patch} />
            ) : props.request.action === "external_directory" ? (
              <Show when={current.lines.length > 0}>
                <box paddingLeft={1} gap={1}>
                  <text fg={theme.text.muted}>Patterns</text>
                  <box>
                    <For each={current.lines}>{(line) => <text fg={theme.text.base}>{line}</text>}</For>
                  </box>
                </box>
              </Show>
            ) : (
              <box paddingLeft={1}>
                <For each={current.lines}>
                  {(line) => (
                    <text
                      fg={
                        props.request.action === "shell" ||
                        props.request.action === "subagent" ||
                        props.request.action === "task"
                          ? theme.text.base
                          : theme.text.muted
                      }
                    >
                      {line}
                    </text>
                  )}
                </For>
              </box>
            )

          const header = () => (
            <box flexDirection="column" gap={0}>
              <box flexDirection="row" gap={1} flexShrink={0}>
                <text fg={theme.text.feedback.warning.base}>{"△"}</text>
                <text fg={theme.text.base}>Permission required</text>
              </box>
              <Show when={props.request.action !== "shell" && current.title}>
                <box flexDirection="row" gap={1} paddingLeft={2} flexShrink={0}>
                  <text fg={theme.text.muted} flexShrink={0}>
                    {current.icon}
                  </text>
                  <text fg={theme.text.base}>{current.title}</text>
                </box>
              </Show>
            </box>
          )

          const body = (
            <SessionQuestion
              title="Permission required"
              semanticLabel={permissionSemanticLabel(props.request.action, current.title)}
              instance={props.request.id}
              header={header()}
              body={(option) => (
                <Show when={option === "always"} fallback={presentationBody()}>
                  <box paddingLeft={1} gap={1}>
                    <For each={permissionAlwaysLines(props.request)}>
                      {(line, index) => <text fg={index() === 0 ? theme.text.muted : theme.text.base}>{line}</text>}
                    </For>
                  </box>
                </Show>
              )}
              options={
                props.request.save?.length
                  ? {
                      once: permissionOptionLabel("once"),
                      always: permissionOptionLabel("always"),
                      reject: permissionOptionLabel("reject"),
                    }
                  : { once: permissionOptionLabel("once"), reject: permissionOptionLabel("reject") }
              }
              escapeKey="reject"
              fullscreen
              onSelect={(option) => {
                if (option === "always") {
                  reply("always")
                  return
                }
                if (option === "reject") {
                  if (session()?.parentID) {
                    setStore("stage", "reject")
                    return
                  }
                  reply("reject")
                  return
                }
                reply("once")
              }}
            />
          )

          return body
        })()}
      </Match>
    </Switch>
  )
}

export function permissionSemanticLabel(action: string, title?: string) {
  return `Permission required: ${title ?? action}`
}

function RejectPrompt(props: {
  action: string
  instance: string
  onConfirm: (message: string) => void
  onCancel: () => void
}) {
  let input: TextareaRenderable
  const enabled = useInteractivity()
  const theme = useTheme()
  const config = useConfig().data
  const dimensions = useTerminalDimensions()
  const narrow = createMemo(() => dimensions().width < 80)
  Keymap.createLayer(() => ({
    mode: "base",
    commands: [
      {
        id: "app.exit",
        title: "Cancel permission rejection",
        group: "Permission",
        run(_input, event) {
          if (event?.ctrl && event.name === "c" && input.plainText) {
            input.setText("")
            return
          }
          props.onCancel()
        },
      },
      { bind: "escape", title: "Cancel permission rejection", group: "Permission", run: () => props.onCancel() },
      {
        bind: "return",
        title: "Confirm permission rejection",
        group: "Permission",
        run: () => props.onConfirm(input.plainText),
      },
    ],
  }))

  return (
    <box
      id="session.permission.reject"
      ref={SimulationSemantics.bind(() => ({
        instance: props.instance,
        role: "dialog",
        label: `Reject permission: ${props.action}`,
      }))}
      backgroundColor={theme.background.raised.base}
      border={["left"]}
      borderColor={theme.text.feedback.error.base}
      customBorderChars={SplitBorder.customBorderChars}
    >
      <box gap={1} paddingLeft={1} paddingRight={3} paddingTop={1} paddingBottom={1}>
        <box flexDirection="row" gap={1} paddingLeft={1}>
          <text fg={theme.text.feedback.error.base}>{"△"}</text>
          <text fg={theme.text.base}>Reject permission</text>
        </box>
        <box paddingLeft={1}>
          <text fg={theme.text.muted}>Tell OpenCode what to do differently</text>
        </box>
      </box>
      <box
        flexDirection={narrow() ? "column" : "row"}
        flexShrink={0}
        paddingTop={1}
        paddingLeft={2}
        paddingRight={3}
        paddingBottom={1}
        backgroundColor={theme.decrease(theme.background.raised.base)}
        justifyContent={narrow() ? "flex-start" : "space-between"}
        alignItems={narrow() ? "flex-start" : "center"}
        gap={1}
      >
        <textarea
          id="session.permission.reject.message"
          ref={(val: TextareaRenderable) => {
            input = val
            SimulationSemantics.bind(() => ({
              instance: props.instance,
              role: "textbox",
              label: "Rejection reason",
              focused: val.focused,
              disabled: false,
            }))(val)
            val.traits = { status: "REJECT" }
          }}
          focused={enabled()}
          textColor={theme.text.base}
          focusedTextColor={theme.text.base}
          cursorColor={theme.text.base}
          cursorStyle={config.cursor}
        />
        <box
          id="session.permission.reject.actions"
          ref={SimulationSemantics.bind(() => ({
            instance: props.instance,
            role: "group",
            label: "Rejection actions",
          }))}
          flexDirection="row"
          gap={2}
          flexShrink={0}
        >
          <box
            id="session.permission.reject.confirm"
            ref={SimulationSemantics.bind(() => ({
              instance: props.instance,
              role: "button",
              label: "Confirm rejection",
              disabled: false,
            }))}
            onMouseUp={() => props.onConfirm(input.plainText)}
          >
            <text fg={theme.text.base}>
              enter <span style={{ fg: theme.text.muted }}>confirm</span>
            </text>
          </box>
          <box
            id="session.permission.reject.cancel"
            ref={SimulationSemantics.bind(() => ({
              instance: props.instance,
              role: "button",
              label: "Cancel rejection",
              disabled: false,
            }))}
            onMouseUp={props.onCancel}
          >
            <text fg={theme.text.base}>
              esc <span style={{ fg: theme.text.muted }}>cancel</span>
            </text>
          </box>
        </box>
      </box>
    </box>
  )
}

export function SessionQuestion<const T extends Record<string, string>>(props: {
  title: string
  semanticLabel?: string
  instance: string
  id?: string
  group?: string
  choicesLabel?: string
  header?: JSX.Element
  body: JSX.Element | ((option: keyof T) => JSX.Element)
  options: T
  escapeKey?: keyof T
  fullscreen?: boolean
  onSelect: (option: keyof T) => void
}) {
  const theme = useTheme()
  const dimensions = useTerminalDimensions()
  const keys = Object.keys(props.options) as (keyof T)[]
  const [store, setStore] = createStore({
    selected: keys[0],
    expanded: false,
  })
  const narrow = createMemo(() => dimensions().width < 80)
  const shortcuts = Keymap.useShortcuts()
  const id = () => props.id ?? "session.permission"
  const group = () => props.group ?? "Permission"
  const dismiss = () => {
    if (store.expanded) {
      setStore("expanded", false)
      return
    }
    if (props.escapeKey) props.onSelect(props.escapeKey)
  }

  Keymap.createLayer(() => ({
    mode: "base",
    commands: [
      ...(props.escapeKey
        ? [
            {
              id: "app.exit",
              title: "Reject permission",
              group: group(),
              bind: false as const,
              run: dismiss,
            },
          ]
        : []),
      ...(props.fullscreen
        ? [
            {
              id: "permission.prompt.fullscreen",
              title: "Toggle permission fullscreen",
              group: group(),
              bind: false as const,
              run: () => setStore("expanded", (value) => !value),
            },
          ]
        : []),
      ...(keys.length > 1
        ? [
            {
              bind: "left,h",
              title: "Previous option",
              group: group(),
              run: () => {
                const index = keys.indexOf(store.selected)
                setStore("selected", keys[(index - 1 + keys.length) % keys.length])
              },
            },
            {
              bind: "right,l",
              title: "Next option",
              group: group(),
              run: () => {
                const index = keys.indexOf(store.selected)
                setStore("selected", keys[(index + 1) % keys.length])
              },
            },
          ]
        : []),
      {
        bind: "return",
        title: "Select option",
        group: group(),
        run: () => props.onSelect(store.selected),
      },
      ...(props.escapeKey ? [{ bind: "escape", title: "Reject permission", group: group(), run: dismiss }] : []),
    ],
    bindings: [...(props.escapeKey ? ["app.exit"] : []), ...(props.fullscreen ? ["permission.prompt.fullscreen"] : [])],
  }))

  const hint = createMemo(() => (store.expanded ? "minimize" : "fullscreen"))
  useRenderer()

  const content = () => (
    <box
      id={id()}
      ref={SimulationSemantics.bind(() => ({
        instance: props.instance,
        role: "dialog",
        label: props.semanticLabel ?? props.title,
        expanded: store.expanded,
      }))}
      backgroundColor={theme.background.raised.base}
      border={["left"]}
      borderColor={theme.background.action.primary.focused}
      customBorderChars={SplitBorder.customBorderChars}
      {...(store.expanded
        ? { top: dimensions().height * -1 + 1, bottom: 1, left: 2, right: 2, position: "absolute" }
        : {
            top: 0,
            maxHeight: 15,
            bottom: 0,
            left: 0,
            right: 0,
            position: "relative",
          })}
    >
      <box gap={1} paddingLeft={1} paddingRight={3} paddingTop={1} paddingBottom={1} flexGrow={1}>
        <Show
          when={props.header}
          fallback={
            <box flexDirection="row" gap={1} paddingLeft={1} flexShrink={0}>
              <text fg={theme.text.feedback.warning.base}>{"△"}</text>
              <text fg={theme.text.base}>{props.title}</text>
            </box>
          }
        >
          <box paddingLeft={1} flexShrink={0}>
            {props.header}
          </box>
        </Show>
        {typeof props.body === "function" ? props.body(store.selected) : props.body}
      </box>
      <box
        flexDirection={narrow() ? "column" : "row"}
        flexShrink={0}
        gap={1}
        paddingTop={1}
        paddingLeft={2}
        paddingRight={3}
        paddingBottom={1}
        backgroundColor={theme.decrease(theme.background.raised.base)}
        justifyContent={narrow() ? "flex-start" : "space-between"}
        alignItems={narrow() ? "flex-start" : "center"}
      >
        <box
          id={`${id()}.actions`}
          ref={SimulationSemantics.bind(() => ({
            instance: props.instance,
            role: "listbox",
            label: props.choicesLabel ?? "Permission choices",
          }))}
          flexDirection="row"
          gap={1}
          flexShrink={0}
        >
          <For each={keys}>
            {(option) => (
              <box
                id={`${id()}.action.${String(option)}`}
                ref={SimulationSemantics.bind(() => ({
                  instance: props.instance,
                  role: "option",
                  label: props.options[option],
                  focused: option === store.selected,
                  selected: option === store.selected,
                  disabled: false,
                }))}
                paddingLeft={1}
                paddingRight={1}
                backgroundColor={
                  option === store.selected
                    ? theme.background.action.primary.focused
                    : theme.background.action.primary.base
                }
                onMouseMove={() => setStore("selected", option)}
                onMouseUp={() => {
                  setStore("selected", option)
                  props.onSelect(option)
                }}
              >
                <text
                  fg={option === store.selected ? theme.text.action.primary.focused : theme.text.action.primary.base}
                >
                  {props.options[option]}
                </text>
              </box>
            )}
          </For>
        </box>
        <box flexDirection="row" gap={2} flexShrink={0}>
          <Show when={props.fullscreen}>
            <text fg={theme.text.base}>
              {shortcuts.get("permission.prompt.fullscreen")} <span style={{ fg: theme.text.muted }}>{hint()}</span>
            </text>
          </Show>
          <Show when={keys.length > 1}>
            <text fg={theme.text.base}>
              {"⇆"} <span style={{ fg: theme.text.muted }}>select</span>
            </text>
          </Show>
          <text fg={theme.text.base}>
            enter <span style={{ fg: theme.text.muted }}>confirm</span>
          </text>
        </box>
      </box>
    </box>
  )

  return (
    <Show when={!store.expanded} fallback={<Portal>{content()}</Portal>}>
      {content()}
    </Show>
  )
}

import type { SessionInboxEnqueued, SessionMessageAssistant, SessionMessageInfo } from "@opencode/client"
import { createEffect, on, onCleanup, type Accessor } from "solid-js"
import { createStore, produce, reconcile } from "solid-js/store"
import { useConfig } from "../../config"
import { useData } from "../../context/data"
import { useClient } from "../../context/client"
import {
  append,
  completePrevious,
  groupRefs,
  hasPart,
  messagePath,
  partitionPending,
  partPath,
  projectEntries,
  type AppendPart,
  type CacheUsage,
  type PartRef,
  type ProjectionEntry,
  type SessionRow,
  type Verbosity,
  defaultVerbosity,
} from "./grouping/session"
import { groupID } from "./anchors"
export type { CacheUsage, PartRef, SessionRow } from "./grouping/session"

/**
 * A page boundary can cut a group in half, which would show a partial summary and
 * give the group a provisional ID (derived from its first part). While the oldest
 * row is a group, keep loading older pages until something precedes it.
 */
export async function completeGroupBoundary(input: {
  rows: readonly SessionRow[]
  messages: () => number
  more: () => boolean
  loadMore: () => Promise<void>
  active: () => boolean
}) {
  while (input.active() && input.rows[0]?.type === "group" && input.more()) {
    const before = input.messages()
    await input.loadMore()
    // A page that adds nothing would otherwise loop forever.
    if (input.messages() === before) return
  }
}

export function createSessionRows(sessionID: Accessor<string>, onSynced?: (sessionID: string) => void) {
  const data = useData()
  const client = useClient()
  const config = useConfig()
  const [rows, setRows] = createStore<(SessionRow & { key?: string })[]>([])
  const revertBoundary = () => data.session.get(sessionID())?.revert?.messageID
  const turnTokens = () => Boolean(config.data.debug?.turn_tokens)
  const verbosity = () => config.data.session?.verbosity ?? defaultVerbosity

  function reduce() {
    const messages = data.session.message.list(sessionID())
    const inputs = new Set(data.session.input.list(sessionID()))
    const pending = data.session.pending.list(sessionID())
    const queued = new Set(
      pending.flatMap((item) => (item.type === "user" && item.delivery === "queue" ? [item.id] : [])),
    )
    const visible = queued.size === 0 ? messages : messages.filter((message) => !queued.has(message.id))
    const boundary = revertBoundary()
    const rows = reduceSessionRows(
      boundary ? visible.filter((message) => message.id < boundary) : visible,
      inputs,
      turnTokens(),
      verbosity(),
    )
    partitionPending(rows, pendingPermissions())
    const position = rows.findIndex((row) => row.type === "message" && inputs.has(row.messageID))
    rows.splice(
      position === -1 ? rows.length : position,
      0,
      ...pending
        .filter((item) => item.type === "compaction")
        .map((item): SessionRow => ({ type: "compaction-queued", inboxID: item.id })),
    )
    return rows
  }

  // Rows have no `id`, Solid's default reconcile key. Matching by position instead would move every
  // row into another store object whenever older history is prepended, remounting the whole transcript.
  // Rows inserted live carry no key, so key the current rows too before matching.
  function rebuild() {
    setRows(
      produce((draft) => {
        draft.forEach((row) => {
          row.key = rowKey(row)
        })
      }),
    )
    setRows(
      reconcile(
        reduce().map((row) => ({ ...row, key: rowKey(row) })),
        { key: "key" },
      ),
    )
  }

  function pendingPermissions() {
    return new Set(
      (data.session.permission.list(sessionID()) ?? []).flatMap((request) =>
        request.source?.type === "tool" ? [request.source.id] : [],
      ),
    )
  }

  createEffect(() => {
    const pending = pendingPermissions()
    setRows(
      produce((draft) => {
        partitionPending(draft, pending)
      }),
    )
  })

  createEffect(
    on([sessionID, () => client.connection.status()], ([id, status]) => {
      if (status !== "connected") return
      rebuild()
      void data.session.pending.sync(id).catch(() => undefined)
      void data.session.message
        .sync(id)
        .then(async () => {
          if (sessionID() !== id) return
          rebuild()
          // Restoration waits for complete boundary groups so saved group IDs resolve.
          await completeGroupBoundary({
            rows,
            messages: () => data.session.message.list(id).length,
            more: () => data.session.message.more(id),
            loadMore: () => data.session.message.loadMore(id),
            active: () => sessionID() === id,
          }).catch(() => undefined)
          if (sessionID() === id) onSynced?.(id)
        })
        .catch(() => undefined)
    }),
  )

  // Re-reduce when the revert boundary changes (stage/clear/commit). These reactions defer
  // their first run: the mount effect above has already reduced the same state.
  createEffect(on(revertBoundary, rebuild, { defer: true }))

  createEffect(
    on(
      () =>
        data.session.pending.list(sessionID()).flatMap((item) => {
          if (item.type === "compaction") return [`${item.id}:compaction`]
          if (item.type === "user" && item.delivery === "queue") return [`${item.id}:queue`]
          return []
        }),
      rebuild,
      { defer: true },
    ),
  )

  createEffect(
    on(
      () =>
        data.session.message.list(sessionID()).flatMap((message) =>
          message.type === "user" || message.type === "synthetic"
            ? [
                {
                  id: message.id,
                  created: message.time.created,
                  input: data.session.input.has(sessionID(), message.id),
                },
              ]
            : message.type === "compaction" || message.type === "idle"
              ? [
                  {
                    id: message.id,
                    created: message.time.created,
                  },
                ]
              : [],
        ),
      rebuild,
      { defer: true },
    ),
  )

  createEffect(on([turnTokens, verbosity], rebuild, { defer: true }))

  const appendMessage = (messageID: string) =>
    setRows(
      produce((draft) => {
        if (draft.some((row) => row.type === "message" && row.messageID === messageID)) return
        const pending = isPending(messageID)
        const message = data.session.message.get(sessionID(), messageID)
        const index =
          message?.type === "compaction" && pending ? queuedStart(draft) : pending ? draft.length : queuedStart(draft)
        if (!pending) completePrevious(draft, index)
        draft.splice(index, 0, { type: "message", messageID })
      }),
    )

  const appendPart = (ref: PartRef, part: AppendPart) =>
    setRows(
      produce((draft) => {
        if (!hasPart(draft, ref)) {
          append(draft, ref, part, queuedStart(draft), verbosity())
          return
        }
        if (part.type !== "reasoning" || part.time?.completed === undefined) return
        const row = draft.find(
          (row) =>
            row.type === "group" &&
            row.kind === "reasoning" &&
            groupRefs(row).some((item) => item.messageID === ref.messageID && item.partID === ref.partID),
        )
        if (row?.type === "group" && row.kind === "reasoning") row.completed = true
      }),
    )

  const appendFooter = (messageID: string) =>
    setRows(
      produce((draft) => {
        if (draft.some((row) => row.type === "assistant-footer" && row.messageID === messageID)) return
        const index = queuedStart(draft)
        completePrevious(draft, index)
        draft.splice(index, 0, { type: "assistant-footer", messageID })
      }),
    )

  const removeFooter = (messageID: string) =>
    setRows(
      produce((draft) => {
        const index = draft.findIndex((row) => row.type === "assistant-footer" && row.messageID === messageID)
        if (index !== -1) draft.splice(index, 1)
      }),
    )

  const isPending = (messageID: string) => {
    const message = data.session.message.get(sessionID(), messageID)
    if (message?.type === "user" || message?.type === "synthetic") return data.session.input.has(sessionID(), messageID)
    return message?.type === "compaction" && message.status === "running"
  }

  const queuedStart = (rows: SessionRow[]) => {
    const index = rows.findIndex(
      (row) => row.type === "compaction-queued" || (row.type === "message" && isPending(row.messageID)),
    )
    return index === -1 ? rows.length : index
  }

  const message = (event: { id: string; data: { sessionID: string } }) => {
    if (event.data.sessionID === sessionID()) appendMessage(event.id.replace(/^evt_/, "msg_"))
  }
  const input = (event: SessionInboxEnqueued) => {
    if (
      event.data.sessionID === sessionID() &&
      (event.data.item.type === "user" ||
        (event.data.item.type === "synthetic" && event.data.item.payload.description?.trim()))
    )
      appendMessage(event.data.inboxID)
  }
  const subscriptions = [
    data.on("session.inbox.enqueued", input),
    data.on("session.compaction.started", (event) => {
      if (event.data.sessionID === sessionID()) appendMessage(event.data.inputID ?? event.id.replace(/^evt_/, "msg_"))
    }),
    data.on("session.instructions.updated", message),
    data.on("session.synthetic", (event) => {
      if (event.data.sessionID === sessionID() && event.data.description?.trim())
        appendMessage(event.id.replace(/^evt_/, "msg_"))
    }),
    data.on("session.shell.started", message),
    data.on("session.agent.selected", message),
    data.on("session.model.selected", message),
    data.on("session.text.delta", (event) => {
      if (event.data.sessionID === sessionID() && event.data.delta.trim())
        appendPart({ messageID: event.data.assistantMessageID, partID: `text:${event.data.ordinal}` }, { type: "text" })
    }),
    data.on("session.text.ended", (event) => {
      if (event.data.sessionID === sessionID() && event.data.text.trim())
        appendPart({ messageID: event.data.assistantMessageID, partID: `text:${event.data.ordinal}` }, { type: "text" })
    }),
    data.on("session.reasoning.delta", (event) => {
      if (event.data.sessionID === sessionID() && event.data.delta.trim())
        appendPart(
          { messageID: event.data.assistantMessageID, partID: `reasoning:${event.data.ordinal}` },
          { type: "reasoning" },
        )
    }),
    data.on("session.reasoning.ended", (event) => {
      if (event.data.sessionID === sessionID() && event.data.text.trim())
        appendPart(
          { messageID: event.data.assistantMessageID, partID: `reasoning:${event.data.ordinal}` },
          { type: "reasoning", time: { completed: event.created } },
        )
    }),
    data.on("session.tool.input.started", (event) => {
      if (event.data.sessionID === sessionID())
        appendPart(
          { messageID: event.data.assistantMessageID, partID: event.data.id },
          { type: "tool", name: event.data.name },
        )
    }),
    data.on("session.retry.scheduled", (event) => {
      if (event.data.sessionID === sessionID()) appendFooter(event.data.assistantMessageID)
    }),
    data.on("session.step.started", (event) => {
      if (event.data.sessionID === sessionID()) removeFooter(event.data.assistantMessageID)
    }),
    data.on("session.step.ended", (event) => {
      if (event.data.sessionID !== sessionID() || ["tool-calls", "unknown"].includes(event.data.finish)) return
      appendFooter(event.data.assistantMessageID)
      if (turnTokens()) rebuild()
    }),
    data.on("session.step.failed", (event) => {
      if (event.data.sessionID !== sessionID()) return
      appendFooter(event.data.assistantMessageID)
      if (turnTokens()) rebuild()
    }),
  ]
  onCleanup(() => subscriptions.forEach((unsubscribe) => unsubscribe()))

  return rows
}

function rowKey(row: SessionRow) {
  switch (row.type) {
    case "group":
      return groupID(row, 0)
    case "part":
      return JSON.stringify([row.type, row.ref.messageID, row.ref.partID])
    case "message":
    case "assistant-footer":
      return JSON.stringify([row.type, row.messageID])
    case "compaction-queued":
      return JSON.stringify([row.type, row.inboxID])
    case "turn-usage":
      return JSON.stringify([row.type, row.messageIDs[0]])
    default:
      return row satisfies never
  }
}

export function reduceSessionRows(
  messages: SessionMessageInfo[],
  inputs = new Set<string>(),
  turnTokens = false,
  verbosity: Verbosity = defaultVerbosity,
) {
  const isInput = (message: SessionMessageInfo) => inputs.has(message.id)
  const pendingCompactions = messages.filter((message) => message.type === "compaction" && message.status === "running")
  const pending = new Set([...pendingCompactions.map((message) => message.id), ...inputs])
  const usage = turnTokens
    ? { steps: [] as SessionMessageAssistant[], previousTurnCache: undefined as CacheUsage | undefined }
    : undefined
  // Without any idle marker, history predates markers and a turn ends with its terminal step.
  // With markers, steers keep the turn open, so usage accumulates until the marker closes it.
  const legacy = !messages.some((message) => message.type === "idle")
  const flushTurn = (rows: ProjectionEntry[]) => {
    if (!usage) return
    const steps = usage.steps.filter(hasTokenUsage)
    const last = steps.at(-1)
    usage.steps.length = 0
    if (!last) return
    rows.push({
      entry: {
        type: "turn-usage",
        messageIDs: steps.map((step) => step.id),
        ...(usage.previousTurnCache === undefined ? {} : { previousCache: usage.previousTurnCache }),
      },
    })
    usage.previousTurnCache = { read: last.tokens.cache.read, model: last.model }
  }
  const entries = [
    ...messages.filter((message) => !pending.has(message.id)),
    ...pendingCompactions,
    ...messages.filter(isInput),
  ].reduce<ProjectionEntry[]>((rows, message) => {
    if (message.type !== "assistant") {
      if (message.type === "idle") {
        flushTurn(rows)
        return rows
      }
      if (message.type === "synthetic" && !message.description?.trim()) return rows
      if (message.type === "compaction" && message.status === "completed" && usage) usage.previousTurnCache = undefined
      rows.push({
        entry: { type: "message", messageID: message.id },
        path: messagePath(message, verbosity),
        closesPrevious: !pending.has(message.id),
      })
      return rows
    }
    usage?.steps.push(message)
    const ordinals = { text: 0, reasoning: 0 }
    message.content.forEach((part) => {
      const partID = part.type === "tool" ? part.id : `${part.type}:${ordinals[part.type]++}`
      if ((part.type === "text" || part.type === "reasoning") && !part.text.trim()) return
      rows.push({
        entry: { type: "part", ref: { messageID: message.id, partID } },
        part,
        path: partPath(part, verbosity),
      })
    })
    const terminal = (message.finish && !["tool-calls", "unknown"].includes(message.finish)) || message.error
    if (terminal || message.retry) {
      rows.push({ entry: { type: "assistant-footer", messageID: message.id } })
    }
    if (terminal && legacy) flushTurn(rows)
    return rows
  }, [])
  return projectEntries(entries)
}

export function cacheReuseDrop(previous: CacheUsage | undefined, current: CacheUsage) {
  if (previous === undefined) return
  if (
    previous.model.providerID !== current.model.providerID ||
    previous.model.id !== current.model.id ||
    previous.model.variant !== current.model.variant
  )
    return
  const drop = previous.read - current.read
  // OpenAI cache reads can move between one and two 1,024-token buckets without a material loss of reuse.
  if (current.model.providerID === "openai" && drop >= 1_024 && drop <= 2_048) return
  return drop > 0 ? drop : undefined
}

// `legacy` marks a session without idle markers, where a turn ends at the next prompt. Reactive
// callers should pass it from a shared memo: the default scans every message, which subscribes
// the footer to the whole history.
export function turnDuration(
  message: SessionMessageAssistant,
  messages: SessionMessageInfo[],
  position?: number,
  legacy = legacyTurns(messages),
) {
  if (message.time.completed === undefined) return 0
  const index = position ?? messages.findIndex((item) => item.id === message.id)
  const input = messages[inputIndex(messages, index === -1 ? messages.length : index, legacy)]
  return Math.max(0, message.time.completed - (input?.time.created ?? message.time.created))
}

export function turnTokensPerSecond(
  message: SessionMessageAssistant,
  messages: SessionMessageInfo[],
  position?: number,
  legacy = legacyTurns(messages),
) {
  const index = position ?? messages.findIndex((item) => item.id === message.id)
  const end = index === -1 ? messages.length : index + 1
  const start = inputIndex(messages, end, legacy)
  const steps = messages
    .slice(start + 1, end)
    .filter((item): item is SessionMessageAssistant => item.type === "assistant")
  const durations = steps.flatMap((step) =>
    step.time.streamed === undefined ? [] : [Math.max(0, step.time.streamed - step.time.created)],
  )
  if (steps.length === 0 || durations.length !== steps.length) return
  const output = steps.reduce((total, step) => total + (step.tokens?.output ?? 0) + (step.tokens?.reasoning ?? 0), 0)
  const duration = durations.reduce((total, value) => total + value, 0)
  if (output <= 0 || duration <= 0) return
  // Aggregate before dividing so each step is weighted by its provider-active duration.
  return output / (duration / 1_000)
}

export function legacyTurns(messages: SessionMessageInfo[]) {
  return !messages.some((message) => message.type === "idle")
}

function inputIndex(messages: SessionMessageInfo[], end: number, legacy: boolean) {
  // Reading a sliced prefix subscribes every footer to unrelated historical messages, so walk
  // back only as far as the turn boundary: the nearest input in legacy sessions, otherwise the
  // first input after the previous idle marker.
  let input = -1
  for (let index = end - 1; index >= 0; index--) {
    const message = messages[index]
    if (message.type === "idle") return input
    if (message.type !== "user" && message.type !== "synthetic") continue
    if (legacy) return index
    input = index
  }
  return input
}

function hasTokenUsage(
  message: SessionMessageAssistant,
): message is SessionMessageAssistant & { tokens: NonNullable<SessionMessageAssistant["tokens"]> } {
  return message.tokens !== undefined && tokenTotal(message.tokens) > 0
}

function tokenTotal(tokens: NonNullable<SessionMessageAssistant["tokens"]>) {
  return tokens.input + tokens.output + tokens.reasoning + tokens.cache.read + tokens.cache.write
}

export function messageBoundaryIDs(rows: SessionRow[], messages: SessionMessageInfo[]) {
  const byID = new Map(messages.map((message) => [message.id, message]))
  const seen = new Set<string>()
  return rows.map((row) => {
    const id = rowBoundaryMessageID(row, byID)
    if (!id || seen.has(id)) return undefined
    seen.add(id)
    return id
  })
}

export function sessionRowID(row: SessionRow, boundaryID?: string) {
  if (boundaryID) return boundaryID
  if (row.type === "part") return `session-part:${row.ref.messageID}:${row.ref.partID}`
}

function rowBoundaryMessageID(row: SessionRow, messages: Map<string, SessionMessageInfo>) {
  if (row.type === "message") {
    const message = messages.get(row.messageID)
    if (message?.type === "user" && message.text.trim()) return message.id
    return undefined
  }
  const messageID =
    row.type === "part"
      ? row.ref.messageID
      : row.type === "group"
        ? groupRefs(row)[0]?.messageID
        : row.type === "assistant-footer"
          ? row.messageID
          : row.type === "turn-usage"
            ? row.messageIDs[0]
            : undefined
  if (!messageID) return undefined
  const message = messages.get(messageID)
  if (message?.type === "assistant") return message.id
}

export function resolvePart(message: SessionMessageAssistant, partID: string) {
  const tool = message.content.find((part) => part.type === "tool" && part.id === partID)
  if (tool) return tool
  const match = /^(text|reasoning):(\d+)$/.exec(partID)
  if (!match) return
  const ordinal = Number(match[2])
  return message.content.filter((part) => part.type === match[1])[ordinal]
}

import { useData } from "../../context/data"
import { createMemo, Show } from "solid-js"
import { useTheme } from "../../context/theme"
import { useConfig } from "../../config"
import { Slot } from "../../plugin/render"
import { withTimestampedFallback } from "@opencode/util/session-title-fallback"
import { TextAttributes } from "@opentui/core"
import "../../component/title-shimmer"

import { getScrollAcceleration } from "../../util/scroll"
import { SESSION_SIDEBAR_WIDTH } from "../../ui/layout"

export function Sidebar(props: { sessionID: string }) {
  const data = useData()
  const theme = useTheme()
  const config = useConfig().data
  const session = createMemo(() => data.session.get(props.sessionID))
  const scrollAcceleration = createMemo(() => getScrollAcceleration(config))

  return (
    <Show when={session()}>
      <box
        backgroundColor={theme.background.raised.base}
        width={SESSION_SIDEBAR_WIDTH}
        height="100%"
        paddingTop={1}
        paddingBottom={1}
        paddingLeft={2}
        paddingRight={2}
        position="relative"
      >
        <box flexShrink={0} paddingRight={2} paddingBottom={1}>
          <title_shimmer
            fg={theme.text.base}
            rename={{
              pending: data.session.title.pending(props.sessionID),
              title: withTimestampedFallback(session()),
            }}
            enabled={config.animations ?? true}
            backdrop={theme.background.raised.base}
            attributes={
              data.session.title.pending(props.sessionID) && config.animations === false
                ? TextAttributes.DIM
                : TextAttributes.BOLD
            }
          >
            {withTimestampedFallback(session())}
          </title_shimmer>
        </box>
        <scrollbox
          flexGrow={1}
          minHeight={0}
          scrollAcceleration={scrollAcceleration()}
          // The sidebar only scrolls vertically; a horizontal bar steals a row during initial layout.
          horizontalScrollbarOptions={{ visible: false }}
          verticalScrollbarOptions={{
            // Use the content's reserved right padding instead of changing its width when the bar toggles.
            position: "absolute",
            right: 0,
            top: 0,
            width: 1,
            height: "100%",
            trackOptions: {
              backgroundColor: theme.background.raised.base,
              foregroundColor: theme.scrollbar.base,
            },
          }}
        >
          <box flexShrink={0} gap={1} paddingRight={1}>
            <Slot path="sidebar.content" input={{ sessionID: props.sessionID }} />
          </box>
        </scrollbox>

        <box flexShrink={0} gap={1} paddingTop={1}>
          <Slot path="sidebar.footer" input={{ sessionID: props.sessionID }} />
        </box>
      </box>
    </Show>
  )
}

import { SyntaxStyle, type RGBA } from "@opentui/core"

export function generateThinkingSyntax(syntax: SyntaxStyle, foreground: RGBA) {
  return SyntaxStyle.fromStyles(
    Object.fromEntries(syntax.getRegisteredNames().map((name) => [name, { ...syntax.getStyle(name), fg: foreground }])),
  )
}

import type { Renderable } from "@opentui/core"
import type { SimulationProtocol } from "@opencode/simulation/protocol"

type Definition = Omit<SimulationProtocol.Frontend.SemanticNode, "id" | "element" | "parent">

const key = Symbol.for("opencode.simulation.semantics")

const bind = (definition: () => Definition) => (renderable: Renderable) => {
  Object.defineProperty(renderable, key, { value: definition, configurable: true })
}

export const SimulationSemantics = { bind }

import { RGBA } from "@opentui/core"

export function ansiToRgba(code: number): RGBA {
  if (code < 16) {
    const ansiColors = [
      "#000000",
      "#800000",
      "#008000",
      "#808000",
      "#000080",
      "#800080",
      "#008080",
      "#c0c0c0",
      "#808080",
      "#ff0000",
      "#00ff00",
      "#ffff00",
      "#0000ff",
      "#ff00ff",
      "#00ffff",
      "#ffffff",
    ]
    return RGBA.fromHex(ansiColors[code] ?? "#000000")
  }

  if (code < 232) {
    const index = code - 16
    const b = index % 6
    const g = Math.floor(index / 6) % 6
    const r = Math.floor(index / 36)
    const val = (x: number) => (x === 0 ? 0 : x * 40 + 55)
    return RGBA.fromInts(val(r), val(g), val(b))
  }

  if (code < 256) {
    const gray = (code - 232) * 10 + 8
    return RGBA.fromInts(gray, gray, gray)
  }

  return RGBA.fromInts(0, 0, 0)
}

export function tint(base: RGBA, overlay: RGBA, alpha: number): RGBA {
  const r = base.r + (overlay.r - base.r) * alpha
  const g = base.g + (overlay.g - base.g) * alpha
  const b = base.b + (overlay.b - base.b) * alpha
  return RGBA.fromInts(Math.round(r * 255), Math.round(g * 255), Math.round(b * 255))
}

import type { RGBA } from "@opentui/core"
import type { Accessor } from "solid-js"
import type { ResolvedTheme, SurfaceName } from "@opencode/theme/tui"

export function createComponentTheme(
  view: Accessor<ResolvedTheme>,
  // Shared across a theme's surface views so `surface()` stays absolute at the wrapper level too.
  surfaces = new Map<SurfaceName, ComponentTheme>(),
): ComponentTheme {
  return {
    get hue() {
      return view().hue
    },
    get categorical() {
      return view().categorical
    },
    get text() {
      return view().text
    },
    get background() {
      return view().background
    },
    get border() {
      return view().border
    },
    get scrollbar() {
      return view().scrollbar
    },
    get diff() {
      return view().diff
    },
    get syntax() {
      return view().syntax
    },
    get markdown() {
      return view().markdown
    },
    source: (color: RGBA) => view().source(color),
    increase: (color: RGBA, amount = 1) => view().increase(color, amount),
    decrease: (color: RGBA, amount = 1) => view().decrease(color, amount),
    surface(name: SurfaceName) {
      const cached = surfaces.get(name)
      if (cached) return cached
      const created = createComponentTheme(() => view().surface(name), surfaces)
      surfaces.set(name, created)
      return created
    },
  }
}

export type ComponentTheme = ResolvedTheme

import { readdir, readFile } from "node:fs/promises"
import path from "node:path"

export async function discoverThemes(directories: string[]) {
  const result: Record<string, unknown> = {}
  for (const directory of directories) {
    const themeDirectory = path.join(directory, "themes")
    const entries = await readdir(themeDirectory, { withFileTypes: true }).catch((error: unknown) => {
      if (error && typeof error === "object" && "code" in error && error.code === "ENOENT") return []
      return Promise.reject(error)
    })
    const files = entries
      .filter((entry) => (entry.isFile() || entry.isSymbolicLink()) && path.extname(entry.name) === ".json")
      .map((entry) => path.join(themeDirectory, entry.name))
      .sort()
    for (const file of files) {
      result[path.basename(file, ".json")] = JSON.parse(await readFile(file, "utf8")) as unknown
    }
  }
  return result
}

import { migrateV1, parseThemeDocument, type ThemeDocument, type ModeDefinition } from "@opencode/theme/tui"
import { resolveThemeColors } from "./resolve"
import { DEFAULT_THEMES, type Theme, type ThemeV1Json } from "./v1"
import opencode from "./assets/v2/opencode.json" with { type: "json" }
import opencode2 from "./assets/v2/opencode2.json" with { type: "json" }

export { DEFAULT_THEMES, type Theme, type ThemeV1Json } from "./v1"

export type ThemeDocumentSource = Record<string, unknown>

let customThemes: Record<string, ThemeDocumentSource> = {}
let systemTheme: ThemeDocumentSource | undefined
const listeners = new Set<(themes: Record<string, ThemeDocumentSource>) => void>()
const parsed = new WeakMap<object, ThemeDocument>()
let opencodeTheme: (ThemeDocument & {
  readonly light: ModeDefinition
  readonly dark: ModeDefinition
}) | undefined

export function getOpenCodeTheme() {
  if (opencodeTheme) return opencodeTheme
  const document = parseThemeDocument(opencode, "opencode") as NonNullable<typeof opencodeTheme>
  opencodeTheme = document
  return document
}

let opencode2Theme: ThemeDocument | undefined

// Temporary theme for the "new-designs" experiment. It is not part of allThemes(), so only the
// TUI theme context offers it, and only while the experiment is enabled.
export function getOpenCode2Theme() {
  opencode2Theme ??= parseThemeDocument(opencode2, "opencode2")
  return opencode2Theme
}

function listThemes(): Record<string, ThemeDocumentSource> {
  // Priority: defaults < custom files < generated system.
  const themes: Record<string, ThemeDocumentSource> = {
    ...DEFAULT_THEMES,
    opencode: getOpenCodeTheme(),
    ...customThemes,
  }
  return {
    ...themes,
    system: systemTheme ?? themes.system ?? themes.opencode,
  }
}

function syncThemes() {
  const themes = listThemes()
  for (const listener of listeners) listener(themes)
}

export function allThemes() {
  return listThemes()
}

export function isThemeSource(source: unknown): source is ThemeDocumentSource {
  if (typeof source !== "object" || source === null || Array.isArray(source)) return false
  return "theme" in source || "base" in source
}

export function parseTheme(source: ThemeDocumentSource, name = "theme") {
  const cached = parsed.get(source)
  if (cached) return cached

  const document = "theme" in source ? migrateV1(source as ThemeV1Json) : parseThemeDocument(source, name)

  parsed.set(source, document)
  return document
}

export function subscribeThemes(listener: (themes: Record<string, ThemeDocumentSource>) => void) {
  listeners.add(listener)
  return () => listeners.delete(listener)
}

export function setCustomThemes(themes: Record<string, unknown>) {
  customThemes = Object.fromEntries(
    Object.entries(themes).filter((entry): entry is [string, ThemeDocumentSource] => isThemeSource(entry[1])),
  )
  syncThemes()
}

export function setSystemTheme(theme: ThemeDocumentSource | undefined) {
  systemTheme = theme
  syncThemes()
}

export function hasTheme(name: string) {
  if (!name) return false
  return allThemes()[name] !== undefined
}

export function resolveTheme(theme: ThemeV1Json, mode: "dark" | "light"): Theme {
  const resolved = resolveThemeColors(theme, mode)
  return {
    ...resolved.theme,
    _hasSelectedListItemText: resolved.hasSelectedListItemText,
    thinkingOpacity: resolved.thinkingOpacity,
  }
}

import { RGBA } from "@opentui/core"
import { ansiToRgba } from "./color"
import type { ColorValue, Theme, ThemeColor, ThemeV1Json } from "./v1"

export function resolveThemeColors(
  theme: ThemeV1Json,
  mode: "dark" | "light",
  resolveAnsi: (code: number) => RGBA = ansiToRgba,
) {
  const defs = theme.defs ?? {}
  function resolveColor(color: ColorValue, chain: string[] = []): RGBA {
    if (color instanceof RGBA) return color
    if (typeof color === "string") {
      if (color === "transparent" || color === "none") return RGBA.fromInts(0, 0, 0, 0)

      if (color.startsWith("#")) return RGBA.fromHex(color)

      if (chain.includes(color)) {
        throw new Error(`Circular color reference: ${[...chain, color].join(" -> ")}`)
      }

      const next = defs[color] ?? theme.theme[color as ThemeColor]
      if (next === undefined) {
        throw new Error(`Color reference "${color}" not found in defs or theme`)
      }
      return resolveColor(next, [...chain, color])
    }
    if (typeof color === "number") return resolveAnsi(color)
    return resolveColor(color[mode], chain)
  }

  const resolved = Object.fromEntries(
    Object.entries(theme.theme)
      .filter(([key]) => key !== "selectedListItemText" && key !== "backgroundMenu" && key !== "thinkingOpacity")
      .map(([key, value]) => [key, resolveColor(value as ColorValue)]),
  ) as Partial<Record<ThemeColor, RGBA>>

  const hasSelectedListItemText = theme.theme.selectedListItemText !== undefined
  return {
    theme: {
      ...(resolved as Record<ThemeColor, RGBA>),
      selectedListItemText: hasSelectedListItemText
        ? resolveColor(theme.theme.selectedListItemText!)
        : resolved.background!,
      backgroundMenu:
        theme.theme.backgroundMenu === undefined
          ? resolved.backgroundElement!
          : resolveColor(theme.theme.backgroundMenu),
    } satisfies Omit<Theme, "_hasSelectedListItemText" | "thinkingOpacity">,
    hasSelectedListItemText,
    thinkingOpacity: theme.theme.thinkingOpacity ?? 0.6,
  }
}

import { RGBA, type TerminalColors } from "@opentui/core"
import { ansiToRgba, tint } from "./color"

export function terminalMode(colors: TerminalColors): "dark" | "light" | undefined {
  const bg = colors.defaultBackground
  if (!bg) return
  const { r, g, b } = RGBA.fromHex(bg)
  return 0.299 * r + 0.587 * g + 0.114 * b > 0.5 ? "light" : "dark"
}

export function generateSystem(colors: TerminalColors, mode: "dark" | "light") {
  const bg = RGBA.fromHex(colors.defaultBackground ?? colors.palette[0]!)
  const fg = RGBA.fromHex(colors.defaultForeground ?? colors.palette[7]!)
  const transparent = RGBA.fromValues(bg.r, bg.g, bg.b, 0)
  const isDark = mode === "dark"

  const col = (index: number) => {
    const value = colors.palette[index]
    if (value) return RGBA.fromHex(value)
    return ansiToRgba(index)
  }

  const grays = generateGrayScale(bg, isDark)
  const textMuted = generateMutedTextColor(bg, isDark)
  const ansiColors = {
    red: col(1),
    green: col(2),
    yellow: col(3),
    blue: col(4),
    magenta: col(5),
    cyan: col(6),
    redBright: col(9),
    greenBright: col(10),
  }

  const diffAlpha = isDark ? 0.22 : 0.14
  const diffAddedBg = tint(bg, ansiColors.green, diffAlpha)
  const diffRemovedBg = tint(bg, ansiColors.red, diffAlpha)
  const diffContextBg = grays[2]
  const diffAddedLineNumberBg = tint(diffContextBg, ansiColors.green, diffAlpha)
  const diffRemovedLineNumberBg = tint(diffContextBg, ansiColors.red, diffAlpha)

  return {
    theme: {
      primary: ansiColors.cyan,
      secondary: ansiColors.magenta,
      accent: ansiColors.cyan,
      error: ansiColors.red,
      warning: ansiColors.yellow,
      success: ansiColors.green,
      info: ansiColors.cyan,
      text: fg,
      textMuted,
      selectedListItemText: bg,
      background: transparent,
      backgroundPanel: grays[2],
      backgroundElement: grays[3],
      backgroundMenu: grays[3],
      borderSubtle: grays[6],
      border: grays[7],
      borderActive: grays[8],
      diffAdded: ansiColors.green,
      diffRemoved: ansiColors.red,
      diffContext: grays[7],
      diffHunkHeader: grays[7],
      diffHighlightAdded: ansiColors.greenBright,
      diffHighlightRemoved: ansiColors.redBright,
      diffAddedBg,
      diffRemovedBg,
      diffContextBg,
      diffLineNumber: textMuted,
      diffAddedLineNumberBg,
      diffRemovedLineNumberBg,
      markdownText: fg,
      markdownHeading: fg,
      markdownLink: ansiColors.blue,
      markdownLinkText: ansiColors.cyan,
      markdownCode: ansiColors.green,
      markdownBlockQuote: ansiColors.yellow,
      markdownEmph: ansiColors.yellow,
      markdownStrong: fg,
      markdownHorizontalRule: grays[7],
      markdownListItem: ansiColors.blue,
      markdownListEnumeration: ansiColors.cyan,
      markdownImage: ansiColors.blue,
      markdownImageText: ansiColors.cyan,
      markdownCodeBlock: fg,
      syntaxComment: textMuted,
      syntaxKeyword: ansiColors.magenta,
      syntaxFunction: ansiColors.blue,
      syntaxVariable: fg,
      syntaxString: ansiColors.green,
      syntaxNumber: ansiColors.yellow,
      syntaxType: ansiColors.cyan,
      syntaxOperator: ansiColors.cyan,
      syntaxPunctuation: fg,
    },
  }
}

function generateGrayScale(bg: RGBA, isDark: boolean): Record<number, RGBA> {
  const grays: Record<number, RGBA> = {}
  const bgR = bg.r * 255
  const bgG = bg.g * 255
  const bgB = bg.b * 255
  const luminance = 0.299 * bgR + 0.587 * bgG + 0.114 * bgB

  for (let i = 1; i <= 12; i++) {
    const factor = i / 12

    if (isDark && luminance < 10) {
      const gray = Math.floor(factor * 0.4 * 255)
      grays[i] = RGBA.fromInts(gray, gray, gray)
      continue
    }

    if (!isDark && luminance > 245) {
      const gray = Math.floor(255 - factor * 0.4 * 255)
      grays[i] = RGBA.fromInts(gray, gray, gray)
      continue
    }

    const next = isDark ? luminance + (255 - luminance) * factor * 0.4 : luminance * (1 - factor * 0.4)
    const ratio = next / luminance
    grays[i] = RGBA.fromInts(
      Math.floor(Math.min(Math.max(bgR * ratio, 0), 255)),
      Math.floor(Math.min(Math.max(bgG * ratio, 0), 255)),
      Math.floor(Math.min(Math.max(bgB * ratio, 0), 255)),
    )
  }

  return grays
}

function generateMutedTextColor(bg: RGBA, isDark: boolean): RGBA {
  const luminance = 0.299 * bg.r * 255 + 0.587 * bg.g * 255 + 0.114 * bg.b * 255
  if (isDark) {
    const gray = luminance < 10 ? 180 : Math.min(Math.floor(160 + luminance * 0.3), 200)
    return RGBA.fromInts(gray, gray, gray)
  }

  const gray = luminance > 245 ? 75 : Math.max(Math.floor(100 - (255 - luminance) * 0.2), 60)
  return RGBA.fromInts(gray, gray, gray)
}

import { createEffect, createSignal, onCleanup, type Accessor } from "solid-js"

type AnimatableValue = number | readonly number[]
type AnimatableTarget = Record<string, AnimatableValue>
type Ease = (progress: number) => number

type SpringTransition = {
  type: "spring"
  visualDuration: number
  restDelta: number
  restSpeed: number
}

type TweenTransition = {
  type: "tween"
  duration: number
  ease: Ease
}

type Transition = SpringTransition | TweenTransition

type ValueState = {
  scalar: boolean
  value: number[]
  target: number[]
  velocity: number[]
  from: number[]
}

type AnimationTask = (now: number) => boolean

const tasks = new Set<AnimationTask>()
let timer: ReturnType<typeof setInterval> | undefined

const smoothstep = (progress: number) => progress * progress * (3 - 2 * progress)

export function spring(options: { visualDuration: number; restDelta?: number; restSpeed?: number }): Transition {
  return {
    type: "spring",
    visualDuration: options.visualDuration,
    restDelta: options.restDelta ?? 0.002,
    restSpeed: options.restSpeed ?? 0.002,
  }
}

export function tween(options: { duration: number; ease?: Ease }): Transition {
  return {
    type: "tween",
    duration: options.duration,
    ease: options.ease ?? smoothstep,
  }
}

export function createAnimatable<T extends AnimatableTarget>(
  initial: T,
  options: {
    transition: Transition
    enabled?: Accessor<boolean>
  },
) {
  const enabled = options.enabled ?? (() => true)
  const state = new Map<string, ValueState>()
  const [value, setValue] = createSignal(clone(initial), { equals: false })
  let target = clone(initial)
  let started = performance.now()
  let previous = started

  rebuild(initial)

  const step: AnimationTask = (now) => {
    if (!enabled()) {
      jump(target)
      return false
    }

    const delta = Math.min(0.05, (now - previous) / 1_000)
    previous = now
    const moving = options.transition.type === "spring" ? advanceSpring(delta) : advanceTween(now)
    if (!moving) {
      jump(target)
      return false
    }
    setValue(() => read())
    return true
  }

  function animate(next: T) {
    if (sameTarget(next)) return
    target = clone(next)
    if (!enabled() || !sameShape(next)) return jump(next)

    started = performance.now()
    previous = started
    for (const [key, current] of state) {
      current.from = [...current.value]
      current.target = values(next[key]!)
    }
    if (settled()) return jump(next)
    schedule(step)
  }

  function jump(next: T) {
    target = clone(next)
    unschedule(step)
    rebuild(next)
    setValue(() => clone(next))
  }

  function stop() {
    unschedule(step)
  }

  function rebuild(next: T) {
    state.clear()
    for (const [key, nextValue] of Object.entries(next)) {
      const value = values(nextValue)
      state.set(key, {
        scalar: typeof nextValue === "number",
        value,
        target: [...value],
        velocity: value.map(() => 0),
        from: [...value],
      })
    }
    started = performance.now()
    previous = started
  }

  function sameShape(next: T) {
    const entries = Object.entries(next)
    if (entries.length !== state.size) return false
    return entries.every(([key, nextValue]) => {
      const current = state.get(key)
      if (!current || current.scalar !== (typeof nextValue === "number")) return false
      return current.value.length === values(nextValue).length
    })
  }

  function sameTarget(next: T) {
    if (!sameShape(next)) return false
    return Object.entries(next).every(([key, value]) =>
      values(value).every((part, index) => part === state.get(key)!.target[index]),
    )
  }

  function settled() {
    return [...state.values()].every(
      (current) =>
        current.value.every((value, index) => value === current.target[index]) &&
        current.velocity.every((velocity) => velocity === 0),
    )
  }

  function advanceSpring(delta: number) {
    const transition = options.transition
    if (transition.type !== "spring") return false
    const frequency = (2 * Math.PI) / (Math.max(0.001, transition.visualDuration) * 1.2)
    let moving = false

    for (const current of state.values()) {
      current.value.forEach((value, index) => {
        const target = current.target[index]!
        const velocity = current.velocity[index]!
        const offset = value - target
        const decay = Math.exp(-frequency * delta)
        const nextVelocity = velocity + frequency * offset
        current.value[index] = target + (offset + nextVelocity * delta) * decay
        current.velocity[index] = (velocity - frequency * nextVelocity * delta) * decay
        moving ||=
          Math.abs(current.value[index]! - target) > transition.restDelta ||
          Math.abs(current.velocity[index]!) > transition.restSpeed
      })
    }
    return moving
  }

  function advanceTween(now: number) {
    const transition = options.transition
    if (transition.type !== "tween") return false
    const progress = Math.min(1, (now - started) / 1_000 / Math.max(0.001, transition.duration))
    const eased = transition.ease(progress)
    for (const current of state.values())
      current.value.forEach((_, index) => {
        const from = current.from[index]!
        current.value[index] = from + (current.target[index]! - from) * eased
        current.velocity[index] = 0
      })
    return progress < 1
  }

  function read() {
    return Object.fromEntries(
      [...state].map(([key, current]) => [key, current.scalar ? current.value[0]! : [...current.value]]),
    ) as T
  }

  createEffect(() => {
    if (enabled()) return
    jump(target)
  })
  onCleanup(stop)

  return { value, animate, jump }
}

function values(value: AnimatableValue) {
  return typeof value === "number" ? [value] : [...value]
}

function clone<T extends AnimatableTarget>(target: T) {
  return Object.fromEntries(
    Object.entries(target).map(([key, value]) => [key, typeof value === "number" ? value : [...value]]),
  ) as T
}

function schedule(task: AnimationTask) {
  tasks.add(task)
  if (timer) return
  timer = setInterval(tick, 16)
}

function unschedule(task: AnimationTask) {
  tasks.delete(task)
  if (tasks.size > 0 || !timer) return
  clearInterval(timer)
  timer = undefined
}

function tick() {
  const now = performance.now()
  for (const task of tasks) if (!task(now)) tasks.delete(task)
  if (tasks.size > 0 || !timer) return
  clearInterval(timer)
  timer = undefined
}

import { Keymap } from "../context/keymap"
import { useTheme } from "../context/theme"
import { DialogHeader, DialogLayout, useDialog } from "./dialog"

export type DialogAlertProps = {
  title: string
  message: string
  onConfirm?: () => void
}

export function DialogAlert(props: DialogAlertProps) {
  const dialog = useDialog()
  const theme = useTheme().surface("dialog")

  const confirm = () => {
    props.onConfirm?.()
    dialog.clear()
  }

  Keymap.createLayer(() => ({
    mode: "modal",
    commands: [
      {
        bind: "return",
        title: "Confirm alert",
        group: "Dialog",
        run: confirm,
      },
    ],
  }))
  return (
    <DialogLayout
      header={<DialogHeader title={props.title} />}
      footer={{ actions: { primary: [{ title: "ok", key: "enter", onTrigger: confirm }] } }}
      legacyFooter={
        <box flexDirection="row" justifyContent="flex-end">
          <box
            paddingLeft={3}
            paddingRight={3}
            backgroundColor={theme.background.action.primary.focused}
            onMouseUp={confirm}
          >
            <text fg={theme.text.action.primary.focused}>ok</text>
          </box>
        </box>
      }
    >
      <text fg={theme.text.muted}>{props.message}</text>
    </DialogLayout>
  )
}

import { Keymap } from "../context/keymap"
import { useTheme } from "../context/theme"
import { useNewDesigns } from "../config"
import { DialogHeader, DialogLayout, useDialog } from "./dialog"
import { createStore } from "solid-js/store"
import { For } from "solid-js"
import { Locale } from "../util/locale"

export type DialogConfirmProps = {
  title: string
  message: string
  onConfirm?: () => void
  onCancel?: () => void
  label?: {
    confirm?: string
    cancel?: string
  }
}

export function DialogConfirm(props: DialogConfirmProps) {
  const dialog = useDialog()
  const theme = useTheme().surface("dialog")
  const newDesigns = useNewDesigns()
  const [store, setStore] = createStore({
    active: "confirm" as "confirm" | "cancel",
  })

  const choose = (key: "confirm" | "cancel") => {
    if (key === "confirm") props.onConfirm?.()
    if (key === "cancel") props.onCancel?.()
    dialog.clear()
  }

  Keymap.createLayer(() => ({
    mode: "modal",
    commands: newDesigns()
      ? [
          { bind: "return", title: "Confirm", group: "Dialog", run: () => choose("confirm") },
          { bind: "escape", title: "Cancel", group: "Dialog", run: () => choose("cancel") },
        ]
      : [
          {
            bind: "return",
            title: "Confirm dialog selection",
            group: "Dialog",
            run: () => choose(store.active),
          },
          {
            bind: "left",
            title: "Previous dialog option",
            group: "Dialog",
            run: () => {
              setStore("active", store.active === "confirm" ? "cancel" : "confirm")
            },
          },
          {
            bind: "right",
            title: "Next dialog option",
            group: "Dialog",
            run: () => {
              setStore("active", store.active === "confirm" ? "cancel" : "confirm")
            },
          },
        ],
  }))
  return (
    <DialogLayout
      header={<DialogHeader title={props.title} />}
      footer={{
        actions: {
          primary: [
            // Footer labels are lowercase; the legacy buttons title-case the same labels.
            { title: (props.label?.cancel ?? "cancel").toLowerCase(), key: "esc", onTrigger: () => choose("cancel") },
            {
              title: (props.label?.confirm ?? "confirm").toLowerCase(),
              key: "enter",
              onTrigger: () => choose("confirm"),
            },
          ],
        },
      }}
      legacyFooter={
        <box flexDirection="row" justifyContent="flex-end">
          <For each={["cancel", "confirm"] as const}>
            {(key) => (
              <box
                paddingLeft={1}
                paddingRight={1}
                backgroundColor={key === store.active ? theme.background.action.primary.focused : undefined}
                onMouseUp={() => choose(key)}
              >
                <text fg={key === store.active ? theme.text.action.primary.focused : theme.text.muted}>
                  {Locale.titlecase(props.label?.[key] ?? key)}
                </text>
              </box>
            )}
          </For>
        </box>
      }
    >
      <text fg={theme.text.muted}>{props.message}</text>
    </DialogLayout>
  )
}

import { Keymap } from "../context/keymap"
import { useNewDesigns } from "../config"
import { useTheme } from "../context/theme"
import { DialogHeader, DialogLayout, type DialogContext } from "./dialog"
import { createStore } from "solid-js/store"
import { For, Show } from "solid-js"

export type ExportFormat = "markdown" | "json"

export type DialogExportOptionsProps = {
  defaultThinking: boolean
  onConfirm?: (options: {
    action: "copy" | "export"
    format: ExportFormat
    thinking: boolean
    tools: boolean
    sanitize: boolean
  }) => void
  onCancel?: () => void
}

type Active = ExportFormat | "thinking" | "tools" | "sanitize" | "copy" | "export"

export function DialogExportOptions(props: DialogExportOptionsProps) {
  const theme = useTheme().surface("dialog")
  const overlayTheme = useTheme()
  const newDesigns = useNewDesigns()
  const [store, setStore] = createStore({
    format: "markdown" as ExportFormat,
    thinking: props.defaultThinking,
    tools: true,
    sanitize: false,
    active: "markdown" as Active,
  })

  const confirm = (action: "copy" | "export") =>
    props.onConfirm?.({
      action,
      format: store.format,
      thinking: store.thinking,
      tools: store.tools,
      sanitize: store.sanitize,
    })

  const activate = () => {
    if (store.active === "markdown" || store.active === "json") {
      setStore("format", store.active)
      return
    }
    if (store.active === "thinking") setStore("thinking", !store.thinking)
    if (store.active === "tools") setStore("tools", !store.tools)
    if (store.active === "sanitize") setStore("sanitize", !store.sanitize)
    if (store.active === "copy" || store.active === "export") confirm(store.active)
  }

  Keymap.createLayer(() => ({
    mode: "modal",
    commands: [
      {
        bind: "tab",
        title: "Next export option",
        group: "Dialog",
        run: () => {
          const options: Active[] =
            store.format === "markdown" ? ["markdown", "json", "thinking", "tools"] : ["markdown", "json", "sanitize"]
          const order: Active[] = newDesigns() ? options : [...options, "copy", "export"]
          setStore("active", order[(order.indexOf(store.active) + 1) % order.length])
        },
      },
      ...(newDesigns()
        ? [
            // The footer owns enter (save) and c (copy), so space toggles the focused option instead.
            { bind: "return", title: "Save to file", group: "Dialog", run: () => confirm("export") },
            { bind: "c", title: "Copy export", group: "Dialog", run: () => confirm("copy") },
            { bind: "space", title: "Toggle export option", group: "Dialog", run: activate },
          ]
        : [
            {
              bind: "return",
              title: "Select export option",
              group: "Dialog",
              run: activate,
            },
          ]),
    ],
  }))

  const selectFormat = (format: ExportFormat) => {
    setStore("format", format)
    setStore("active", format)
  }

  return (
    <DialogLayout
      header={<DialogHeader title="Export session" />}
      footer={{
        actions: {
          primary: [
            { title: "copy", key: "c", onTrigger: () => confirm("copy") },
            { title: "save to file", key: "enter", onTrigger: () => confirm("export") },
          ],
        },
      }}
      legacyFooter={
        <box flexDirection="row" justifyContent="flex-end" gap={1}>
          <box
            paddingLeft={4}
            paddingRight={4}
            backgroundColor={overlayTheme.background.raised.high}
            onMouseUp={() => confirm("copy")}
          >
            <text fg={overlayTheme.text.base}>Copy</text>
          </box>
          <box
            paddingLeft={4}
            paddingRight={4}
            backgroundColor={
              store.active === "export" ? theme.background.action.primary.focused : theme.background.action.primary.base
            }
            onMouseUp={() => confirm("export")}
          >
            <text fg={store.active === "export" ? theme.text.action.primary.focused : theme.text.action.primary.base}>
              Export
            </text>
          </box>
        </box>
      }
    >
      <box gap={1}>
        <box flexDirection="row" gap={1}>
          <text fg={theme.text.base}>Export as:</text>
          <box flexDirection="row" gap={1}>
            <For each={["markdown", "json"] as const}>
              {(format) => (
                <box
                  paddingLeft={1}
                  paddingRight={1}
                  backgroundColor={
                    store.active === format
                      ? theme.background.formfield.focused
                      : store.format === format
                        ? theme.background.formfield.selected
                        : theme.background.formfield.base
                  }
                  onMouseUp={() => selectFormat(format)}
                >
                  <text
                    fg={
                      store.active === format
                        ? theme.text.formfield.focused
                        : store.format === format
                          ? theme.text.formfield.selected
                          : theme.text.formfield.base
                    }
                  >
                    {store.format === format ? "◉" : "○"} {format === "markdown" ? "Markdown" : "JSON"}
                  </text>
                </box>
              )}
            </For>
          </box>
        </box>
        <Show when={store.format === "markdown"}>
          <box
            flexDirection="row"
            gap={1}
            backgroundColor={
              store.active === "thinking"
                ? theme.background.formfield.focused
                : store.thinking
                  ? theme.background.formfield.selected
                  : theme.background.formfield.base
            }
            onMouseUp={() => {
              setStore("active", "thinking")
              setStore("thinking", !store.thinking)
            }}
          >
            <text
              fg={
                store.active === "thinking"
                  ? theme.text.formfield.focused
                  : store.thinking
                    ? theme.text.formfield.selected
                    : theme.text.formfield.base
              }
            >
              {store.thinking ? "[x]" : "[ ]"}
            </text>
            <text
              fg={
                store.active === "thinking"
                  ? theme.text.formfield.focused
                  : store.thinking
                    ? theme.text.formfield.selected
                    : theme.text.formfield.base
              }
            >
              Include thinking
            </text>
          </box>
          <box
            flexDirection="row"
            gap={1}
            backgroundColor={
              store.active === "tools"
                ? theme.background.formfield.focused
                : store.tools
                  ? theme.background.formfield.selected
                  : theme.background.formfield.base
            }
            onMouseUp={() => {
              setStore("active", "tools")
              setStore("tools", !store.tools)
            }}
          >
            <text
              fg={
                store.active === "tools"
                  ? theme.text.formfield.focused
                  : store.tools
                    ? theme.text.formfield.selected
                    : theme.text.formfield.base
              }
            >
              {store.tools ? "[x]" : "[ ]"}
            </text>
            <text
              fg={
                store.active === "tools"
                  ? theme.text.formfield.focused
                  : store.tools
                    ? theme.text.formfield.selected
                    : theme.text.formfield.base
              }
            >
              Include tools
            </text>
          </box>
        </Show>
        <Show when={store.format === "json"}>
          <box
            flexDirection="row"
            gap={1}
            backgroundColor={
              store.active === "sanitize"
                ? theme.background.formfield.focused
                : store.sanitize
                  ? theme.background.formfield.selected
                  : theme.background.formfield.base
            }
            onMouseUp={() => {
              setStore("active", "sanitize")
              setStore("sanitize", !store.sanitize)
            }}
          >
            <text
              fg={
                store.active === "sanitize"
                  ? theme.text.formfield.focused
                  : store.sanitize
                    ? theme.text.formfield.selected
                    : theme.text.formfield.base
              }
            >
              {store.sanitize ? "[x]" : "[ ]"}
            </text>
            <text
              fg={
                store.active === "sanitize"
                  ? theme.text.formfield.focused
                  : store.sanitize
                    ? theme.text.formfield.selected
                    : theme.text.formfield.base
              }
            >
              Sanitize sensitive data
            </text>
          </box>
        </Show>
      </box>
    </DialogLayout>
  )
}

DialogExportOptions.show = (dialog: DialogContext, defaultThinking: boolean) => {
  return new Promise<{
    action: "copy" | "export"
    format: ExportFormat
    thinking: boolean
    tools: boolean
    sanitize: boolean
  } | null>((resolve) => {
    dialog.replace(
      () => (
        <DialogExportOptions
          defaultThinking={defaultThinking}
          onConfirm={(options) => resolve(options)}
          onCancel={() => resolve(null)}
        />
      ),
      () => resolve(null),
    )
  })
}

import { createSignal } from "solid-js"
import { useNewDesigns } from "../config"
import { useClipboard } from "../context/clipboard"
import { Keymap } from "../context/keymap"
import { useTheme } from "../context/theme"
import { DialogHeader, DialogLayout, useDialog, type DialogContext } from "./dialog"
import { useToast } from "./toast"

export function DialogExportResult(props: { path: string; onClose?: () => void }) {
  const dialog = useDialog()
  const theme = useTheme().surface("dialog")
  const clipboard = useClipboard()
  const toast = useToast()
  const newDesigns = useNewDesigns()
  const [copied, setCopied] = createSignal(false)

  const close = () => {
    props.onClose?.()
    dialog.clear()
  }

  const copy = () => {
    void clipboard
      .write(props.path)
      .then(() => setCopied(true))
      .catch(toast.error)
  }

  Keymap.createLayer(() => ({
    mode: "modal",
    commands: [
      {
        bind: "return",
        title: "Close export result",
        group: "Dialog",
        run: close,
      },
    ],
  }))

  Keymap.createLayer(() => ({
    mode: "modal",
    enabled: newDesigns(),
    commands: [{ bind: "c", title: "Copy export path", group: "Dialog", run: copy }],
  }))

  return (
    <DialogLayout
      header={<DialogHeader title="Session exported" onClose={close} />}
      footer={{
        actions: {
          primary: [
            copied()
              ? { title: "✓ copied", color: theme.text.feedback.success.base, onTrigger: copy }
              : { title: "copy path", key: "c", onTrigger: copy },
          ],
        },
      }}
      legacyFooter={
        <box flexDirection="row" justifyContent="flex-end" gap={1}>
          <box
            paddingLeft={3}
            paddingRight={3}
            backgroundColor={theme.background.action.primary.focused}
            onMouseUp={close}
          >
            <text fg={theme.text.action.primary.focused}>Close</text>
          </box>
        </box>
      }
    >
      <text fg={theme.text.base}>{props.path}</text>
    </DialogLayout>
  )
}

DialogExportResult.show = (dialog: DialogContext, path: string) =>
  new Promise<void>((resolve) => {
    dialog.replace(() => <DialogExportResult path={path} onClose={resolve} />, resolve)
  })

