import { TextareaRenderable } from "@opentui/core"
import { Keymap } from "../context/keymap"
import { useTheme } from "../context/theme"
import { DialogFooter, DialogHeader, DialogLayout, useDialog, type DialogSize } from "./dialog"
import { Show, createEffect, createSignal, onMount, type JSX } from "solid-js"
import { Spinner } from "../component/spinner"
import { useConfig, useNewDesigns } from "../config"
import { useRenderer } from "@opentui/solid"

export type DialogPromptAction = {
  title: string
  /** Keymap command id, bound while the prompt input is focused and shown in the footer. */
  command: string
  /** Keymap command title, e.g. for help listings. Defaults to `title`. */
  commandTitle?: string
  onTrigger: (prompt: { setValue: (value: string) => void }) => void
}

export type DialogPromptProps = {
  title: string
  size?: DialogSize
  /** Faint line below the title, under the "new-designs" experiment. */
  subtitle?: string
  description?: () => JSX.Element
  placeholder?: string
  value?: string
  busy?: boolean
  busyText?: string
  actions?: DialogPromptAction[]
  onConfirm?: (value: string) => void
  onCancel?: () => void
}

export function DialogPrompt(props: DialogPromptProps) {
  const dialog = useDialog()
  const renderer = useRenderer()
  const theme = useTheme().surface("dialog")
  const config = useConfig().data
  const newDesigns = useNewDesigns()
  const [textareaTarget, setTextareaTarget] = createSignal<TextareaRenderable>()
  let textarea: TextareaRenderable

  function confirm() {
    if (props.busy) return
    props.onConfirm?.(textarea.plainText)
  }

  const handle = {
    setValue(value: string) {
      textarea.setText(value)
      textarea.gotoLineEnd()
    },
  }

  const extraActions = () =>
    (props.actions ?? []).map((action) => ({
      title: action.title,
      command: action.command,
      disabled: props.busy,
      onTrigger: () => action.onTrigger(handle),
    }))

  Keymap.createLayer(() => ({
    mode: "modal",
    target: textareaTarget,
    enabled: textareaTarget() !== undefined && !props.busy,
    // Dialog form semantics must win over the global managed textarea input layer.
    priority: 1,
    commands: [
      {
        id: "dialog.prompt.submit",
        title: "Submit dialog prompt",
        group: "Dialog",
        run: confirm,
      },
      ...(props.actions ?? []).map((action) => ({
        id: action.command,
        title: action.commandTitle ?? action.title,
        group: "Dialog",
        run: () => action.onTrigger(handle),
      })),
    ],
  }))

  Keymap.createLayer(() => ({
    mode: "modal",
    enabled: props.onCancel !== undefined,
    priority: 1,
    commands: [
      {
        bind: "escape",
        title: "Back",
        group: "Dialog",
        run: () => {
          if (renderer.getSelection()) {
            renderer.clearSelection()
            return
          }
          if (!props.busy) props.onCancel?.()
        },
      },
    ],
  }))

  onMount(() => {
    dialog.setSize(props.size ?? "medium")
    setTimeout(() => {
      if (!textarea || textarea.isDestroyed) return
      if (props.busy) return
      textarea.focus()
    }, 1)
    textarea.gotoLineEnd()
  })

  createEffect(() => {
    if (!textarea || textarea.isDestroyed) return
    const traits = props.busy
      ? {
          suspend: true,
          status: "BUSY",
        }
      : {}
    textarea.traits = traits
    if (props.busy) {
      textarea.blur()
      return
    }
    textarea.focus()
  })

  return (
    <DialogLayout
      header={
        <DialogHeader
          title={props.title}
          description={props.subtitle}
          onClose={() => {
            if (!props.busy) (props.onCancel ?? dialog.clear)()
          }}
        />
      }
      footer={{
        actions: {
          primary: [
            ...extraActions(),
            { title: "submit", command: "dialog.prompt.submit", disabled: props.busy, onTrigger: confirm },
          ],
        },
      }}
      legacyFooter={
        <Show when={!props.busy} fallback={<text fg={theme.text.muted}>processing…</text>}>
          <DialogFooter
            actions={{
              secondary: [{ title: "submit", command: "dialog.prompt.submit", onTrigger: confirm }, ...extraActions()],
            }}
          />
        </Show>
      }
    >
      <box gap={1}>
        {props.description?.()}
        <textarea
          height={1}
          wrapMode="none"
          ref={(val: TextareaRenderable) => {
            textarea = val
            setTextareaTarget(val)
          }}
          initialValue={props.value}
          placeholder={props.placeholder ?? "Enter text"}
          placeholderColor={newDesigns() ? theme.text.faint : theme.text.muted}
          textColor={props.busy ? theme.text.formfield.disabled : theme.text.formfield.base}
          focusedTextColor={props.busy ? theme.text.formfield.disabled : theme.text.formfield.base}
          cursorColor={props.busy ? theme.background.formfield.disabled : theme.text.base}
          cursorStyle={config.cursor}
        />
        <Show when={props.busy}>
          <Spinner color={theme.text.muted}>{props.busyText ?? "Working…"}</Spinner>
        </Show>
      </box>
    </DialogLayout>
  )
}

import { CliRenderEvents, InputRenderable, RGBA, ScrollBoxRenderable, TextAttributes } from "@opentui/core"
import { Keymap, type KeymapCommand } from "../context/keymap"
import { useTheme } from "../context/theme"
import { entries, filter, flatMap, groupBy, pipe } from "remeda"
import { batch, createEffect, createMemo, createSignal, For, Show, type JSX, on, onCleanup, onMount } from "solid-js"
import { createStore } from "solid-js/store"
import { useRenderer, useTerminalDimensions } from "@opentui/solid"
import * as fuzzysort from "fuzzysort"
import { isDeepEqual } from "remeda"
import {
  DIALOG_INSET,
  DIALOG_LIST_INSET,
  DialogBleed,
  DialogFooter,
  DialogHeader,
  DialogLayout,
  dialogWidth,
  useDialog,
  type DialogContext,
} from "./dialog"
import { Locale } from "../util/locale"
import { getScrollAcceleration } from "../util/scroll"
import { useConfig, useNewDesigns } from "../config"
import { moveSelection, reconcileSelection } from "./select-controller"

export interface DialogSelectProps<T> {
  title: string
  titleView?: JSX.Element
  placeholder?: string
  footer?: JSX.Element
  emptyView?: JSX.Element
  noMatchView?: JSX.Element
  options: DialogSelectOption<T>[]
  flat?: boolean
  filterThreshold?: number
  ref?: (ref: DialogSelectRef<T>) => void
  onMove?: (option: DialogSelectOption<T>) => void
  onFilter?: (query: string) => void
  onSelect?: (option: DialogSelectOption<T>) => void
  onCancel?: () => void
  skipFilter?: boolean
  search?: (query: string) => readonly DialogSelectOption<T>[]
  renderFilter?: boolean
  locked?: boolean
  preserveSelection?: boolean
  actions?: DialogSelectAction<T>[]
  footerHints?: {
    title: string
    label: string
    /** Footer placement while the "new-designs" experiment is off. */
    side?: "left" | "right"
    /** Footer group under the "new-designs" experiment. Defaults to `secondary`. */
    group?: "primary" | "secondary"
  }[]
  bindings?: readonly KeymapCommand[]
  current?: T
  focusTarget?: T
  focusCurrent?: boolean
  sectionNavigation?: boolean
  /** Under the "new-designs" experiment, puts the search input in the header row in place of the title. */
  searchInTitle?: boolean
  /** Placeholder for the search input while it replaces the title, e.g. "Search models". */
  titlePlaceholder?: string
}

type DialogSelectActionBase<T> = {
  command: string
  title: string
  bind?: string
  /** Footer placement while the "new-designs" experiment is off. */
  side?: "left" | "right"
  /**
   * Footer group under the "new-designs" experiment. Defaults to `primary` for actions on the selected
   * option and `secondary` for dialog-level actions (`selection: "none"`).
   */
  group?: "primary" | "secondary"
  hidden?: boolean
  disabled?: boolean | ((option: DialogSelectOption<T> | undefined) => boolean)
}

type DialogSelectAction<T> =
  | (DialogSelectActionBase<T> & {
      selection?: "required"
      onTrigger: (option: DialogSelectOption<T>) => void
    })
  | (DialogSelectActionBase<T> & {
      selection: "none"
      onTrigger: () => void
    })

export interface DialogSelectOption<T = any> {
  title: string
  titleView?: JSX.Element
  value: T
  description?: string
  searchText?: string
  searchFooter?: JSX.Element | string
  details?: string[]
  footer?: JSX.Element | string
  footerColor?: RGBA
  titleWidth?: number
  truncateTitle?: boolean | "left"
  category?: string
  disabled?: boolean
  bg?: RGBA
  fg?: RGBA
  gutter?: (color: RGBA) => JSX.Element
  margin?: JSX.Element
  onSelect?: (ctx: DialogContext) => void
}

export function dialogSelectContentWidth(dialogWidth: number) {
  // Scroll padding, row padding, the gutter, title padding, and the separating gap.
  return dialogWidth - DIALOG_LIST_INSET * 2 - 4
}

export type DialogSelectRef<T> = {
  filter: string
  filtered: DialogSelectOption<T>[]
  selected: DialogSelectOption<T> | undefined
  setFilter(value: string): void
  moveTo(value: T): void
}

export function DialogSelect<T>(props: DialogSelectProps<T>) {
  type Action = NonNullable<DialogSelectProps<T>["actions"]>[number]
  type FooterHint = NonNullable<DialogSelectProps<T>["footerHints"]>[number]
  type VisibleAction = (Action & { label: string }) | FooterHint

  const dialog = useDialog()
  const theme = useTheme().surface("dialog")
  const config = useConfig().data
  const newDesigns = useNewDesigns()
  const scrollAcceleration = createMemo(() => getScrollAcceleration(config))
  const renderer = useRenderer()

  const [store, setStore] = createStore({
    selected: 0,
    filter: "",
  })
  let selection: { value: T; category?: string } | undefined
  let resetSelection = false
  let pendingScroll: (() => void) | undefined

  function scrollAfterLayout(center: boolean, value: T) {
    if (pendingScroll) renderer.off(CliRenderEvents.FRAME, pendingScroll)
    pendingScroll = () => {
      pendingScroll = undefined
      if (!isDeepEqual(selected()?.value, value)) return
      scrollToSelection(center)
    }
    renderer.once(CliRenderEvents.FRAME, pendingScroll)
    renderer.requestRender()
  }

  createEffect(
    on(
      [() => props.focusTarget ?? props.current, () => (props.focusTarget === undefined ? undefined : flat())],
      ([current]) => {
        if (props.search || props.focusCurrent === false) return
        if (props.focusTarget !== undefined && (props.preserveSelection || store.filter.length > 0)) return
        if (current !== undefined) {
          const currentIndex = flat().findIndex((opt) => isDeepEqual(opt.value, current))
          if (currentIndex >= 0) {
            setStore("selected", currentIndex)
            selection = flat()[currentIndex]
            scrollAfterLayout(true, current)
          }
        }
      },
    ),
  )

  let input: InputRenderable | undefined

  const actions = createMemo(() => props.actions ?? [])
  const shownActions = createMemo(() => actions().filter((item) => !item.hidden))
  const shortcuts = Keymap.useShortcuts()

  const actionLabels = createMemo(() => {
    const labels = new Map<string, string>()

    for (const action of shownActions()) {
      const label = shortcuts.all(action.command)
      if (label) labels.set(action.command, label)
    }

    return labels
  })
  const visibleActions = createMemo(() => [
    ...shownActions()
      .map((item) => ({ ...item, label: actionLabels().get(item.command) ?? "" }))
      .filter((item) => item.label),
    ...(props.footerHints ?? []),
  ])

  const filtered = createMemo(() => {
    if (props.search) return props.search(store.filter).filter((x) => x.disabled !== true)
    if (props.skipFilter || props.renderFilter === false) return props.options.filter((x) => x.disabled !== true)
    const needle = store.filter.toLowerCase()
    const options = pipe(
      props.options,
      filter((x) => x.disabled !== true),
    )
    if (!needle) return options

    // prioritize title matches (weight: 2) over category and supplemental search text matches (weight: 1).
    // users typically search by the item name, and not its category.
    const result = fuzzysort
      .go(needle, options, {
        keys: ["title", "category", "searchText"],
        scoreFn: (r) => r[0].score * 2 + r[1].score + r[2].score,
        threshold: props.filterThreshold,
      })
      .map((x) => x.obj)

    return result
  })

  const flatten = createMemo(() => props.search !== undefined || (props.flat && store.filter.length > 0))

  const grouped = createMemo<[string, DialogSelectOption<T>[]][]>(() => {
    if (flatten()) return filtered().length ? [["", filtered()]] : []
    const result = pipe(
      filtered(),
      groupBy((x) => x.category ?? ""),
      // mapValues((x) => x.sort((a, b) => a.title.localeCompare(b.title))),
      entries(),
    )
    return result
  })

  const flat = createMemo(() => {
    return pipe(
      grouped(),
      flatMap(([_, options]) => options),
    )
  })

  const rows = createMemo(() => {
    const headers = grouped().reduce((acc, [category], i) => {
      if (!category) return acc
      return acc + (i > 0 ? 2 : 1)
    }, 0)
    return flat().reduce((acc, option) => acc + 1 + (option.details?.length ?? 0), headers)
  })

  const dimensions = useTerminalDimensions()
  const limit = createMemo(() => Math.floor(dimensions().height / 2) - 6)
  // Under new designs an overflowing list gives its last row to a "…" indicator.
  const overflows = createMemo(() => newDesigns() && rows() > limit())
  const height = createMemo(() => Math.min(rows(), limit()) - (overflows() ? 1 : 0))
  const [moreBelow, setMoreBelow] = createSignal(false)
  function updateMoreBelow() {
    if (!scroll || scroll.isDestroyed) return
    setMoreBelow(scroll.scrollTop + scroll.viewport.height < scroll.scrollHeight)
  }

  const selected = createMemo(() => flat()[store.selected])

  createEffect(
    on(
      () => props.options,
      () => {
        if (props.search) return
        if (
          !props.preserveSelection &&
          ((props.focusTarget ?? props.current) === undefined || props.focusCurrent === false)
        ) {
          const count = flat().length
          if (count === 0) return
          const next = reconcileSelection(store.selected, count)
          if (next !== store.selected) setStore("selected", next)
          return
        }
        if (resetSelection && store.filter.length > 0) {
          const option = flat()[0]
          if (!option) return
          setStore("selected", 0)
          selection = option
          return
        }
        if (!selection) {
          if (props.focusCurrent !== false && (props.focusTarget ?? props.current) !== undefined) {
            const index = flat().findIndex((option) => isDeepEqual(option.value, props.focusTarget ?? props.current))
            if (index >= 0) {
              setStore("selected", index)
              selection = flat()[index]
              return
            }
          }
          const option = selected()
          if (!option) return
          selection = option
          return
        }
        const previous = selection
        const index = flat().findIndex((option) => isDeepEqual(option.value, previous.value))
        if (index >= 0) {
          const option = flat()[index]
          const moved = index !== store.selected || option.category !== previous.category
          setStore("selected", index)
          selection = option
          if (!moved) return
          if (
            !props.preserveSelection &&
            ((props.focusTarget ?? props.current) === undefined ||
              props.focusCurrent === false ||
              store.filter.length > 0)
          )
            return
          scrollAfterLayout(false, option.value)
          return
        }
        const next = reconcileSelection(store.selected, flat().length)
        if (flat().length === 0) return
        setStore("selected", next)
        selection = flat()[next]
      },
    ),
  )
  createEffect(
    on(
      [
        flat,
        () => store.filter,
        () => (props.focusCurrent === false ? undefined : (props.focusTarget ?? props.current)),
      ],
      ([options, query, current], previous) => {
        if (!props.search) return
        const queryChanged = previous !== undefined && query !== previous[1]
        const currentChanged = current !== undefined && (previous === undefined || !isDeepEqual(current, previous[2]))
        selection = intent()
        const intended = selection
        const index = intended ? options.findIndex((option) => isDeepEqual(option.value, intended.value)) : -1
        const next = index >= 0 ? index : reconcileSelection(store.selected, options.length)
        const option = options[next]
        if (!option) return
        setStore("selected", next)
        selection = option
        scrollAfterLayout(queryChanged || currentChanged, option.value)

        function intent() {
          if (queryChanged && query) return options[0]
          if ((queryChanged || currentChanged) && current !== undefined) return { value: current }
          if (queryChanged) return options[reconcileSelection(store.selected, options.length)]
          return selection
        }
      },
    ),
  )
  onCleanup(() => {
    if (!pendingScroll) return
    renderer.off(CliRenderEvents.FRAME, pendingScroll)
    pendingScroll = undefined
  })

  createEffect(
    on([() => store.filter, () => props.focusTarget ?? props.current], ([filter, current]) => {
      if (props.search) return
      if (filter.length > 0) resetSelection = true
      if (filter.length > 0) {
        const option = flat()[0]
        if (!option) return
        moveTo(0, true, false)
        scrollAfterLayout(true, option.value)
        return
      }
      if (current === undefined || props.focusCurrent === false) return
      const currentIndex = flat().findIndex((opt) => isDeepEqual(opt.value, current))
      if (currentIndex < 0) return
      moveTo(currentIndex, true)
      scrollAfterLayout(true, current)
    }),
  )

  function move(direction: number) {
    if (props.locked) return
    if (flat().length === 0) return
    moveTo(moveSelection(store.selected, { count: flat().length, delta: direction, policy: "wrap" }), true)
  }

  function moveSection(direction: 1 | -1) {
    if (props.locked) return
    const sections = grouped().filter(([_, options]) => options.length > 0)
    if (sections.length === 0) return
    const current = sections.findIndex(([category]) => category === selected()?.category)
    const section = sections[(current + direction + sections.length) % sections.length]
    moveTo(flat().indexOf(section[1][0]), true)
  }

  function moveTo(next: number, center = false, preserve = true) {
    setStore("selected", next)
    const option = selected()
    if (option) {
      selection = option
      resetSelection = !preserve
    }
    if (option) props.onMove?.(option)
    scrollToSelection(center)
  }

  function scrollToSelection(center: boolean) {
    if (!scroll) return
    let remaining = store.selected
    let index = 0
    // Locate the row by position because a unique renderable ID cannot currently be ensured.
    for (const [category, options] of grouped()) {
      if (category) index++
      if (remaining < options.length) {
        index += remaining
        break
      }
      index += options.length
      remaining -= options.length
    }
    const target = scroll.getChildren()[index]
    if (!target) return
    const y = target.y - scroll.y
    if (center) {
      const centerOffset = Math.floor(scroll.height / 2)
      scroll.scrollBy(y - centerOffset)
    } else {
      if (y >= scroll.height) {
        scroll.scrollBy(y - scroll.height + 1)
      }
      if (y < 0) {
        scroll.scrollBy(y)
        if (isDeepEqual(flat()[0].value, selected()?.value)) {
          scroll.scrollTo(0)
        }
      }
    }
  }

  function submit() {
    if (props.locked) return
    const option = selected()
    if (!option) return
    option.onSelect?.(dialog)
    props.onSelect?.(option)
  }

  Keymap.createLayer(() => {
    const visible = shownActions()

    return {
      mode: "modal",
      commands: [
        {
          id: "dialog.select.prev",
          title: "Previous item",
          group: "Dialog",
          run() {
            move(-1)
          },
        },
        {
          id: "dialog.select.next",
          title: "Next item",
          group: "Dialog",
          run() {
            move(1)
          },
        },
        {
          id: "dialog.select.page_up",
          title: "Page up",
          group: "Dialog",
          run() {
            move(-10)
          },
        },
        {
          id: "dialog.select.page_down",
          title: "Page down",
          group: "Dialog",
          run() {
            move(10)
          },
        },
        {
          id: "dialog.select.home",
          title: "First item",
          group: "Dialog",
          run() {
            if (props.locked) return
            moveTo(0)
          },
        },
        {
          id: "dialog.select.end",
          title: "Last item",
          group: "Dialog",
          run() {
            if (props.locked) return
            moveTo(flat().length - 1)
          },
        },
        {
          id: "dialog.select.submit",
          title: "Select item",
          group: "Dialog",
          run: submit,
        },
        ...visible.map((item) => ({
          id: item.command,
          title: item.title,
          group: "Dialog",
          bind: item.bind,
          run: () => trigger(item),
        })),
        ...(props.bindings ?? []),
        ...(props.onCancel
          ? [
              {
                bind: "escape",
                title: "Back",
                group: "Dialog",
                run: () => {
                  if (renderer.getSelection()) {
                    renderer.clearSelection()
                    return
                  }
                  props.onCancel?.()
                },
              },
            ]
          : []),
        ...(props.sectionNavigation
          ? [
              {
                bind: "alt+up",
                title: "Previous section",
                group: "Dialog",
                run: () => moveSection(-1),
              },
              {
                bind: "alt+down",
                title: "Next section",
                group: "Dialog",
                run: () => moveSection(1),
              },
            ]
          : []),
      ],
    }
  })

  let scroll: ScrollBoxRenderable | undefined
  const ref: DialogSelectRef<T> = {
    get filter() {
      return store.filter
    },
    get filtered() {
      return filtered()
    },
    get selected() {
      return selected()
    },
    setFilter(value) {
      if (input) {
        input.value = value
        return
      }
      if (value === store.filter) return
      batch(() => {
        setStore("filter", value)
        props.onFilter?.(value)
      })
    },
    moveTo(value) {
      const index = flat().findIndex((option) => isDeepEqual(option.value, value))
      if (index >= 0) moveTo(index, true)
    },
  }
  onMount(() => props.ref?.(ref))

  const footerActions = createMemo(() =>
    visibleActions().map((item) => {
      if (!isActionItem(item))
        return { side: item.side, group: item.group ?? "secondary", action: { title: item.title, key: item.label } }
      return {
        side: item.side,
        group: item.group ?? (item.selection === "none" ? "secondary" : "primary"),
        action: {
          title: item.title,
          key: item.label,
          disabled: isActionDisabled(item),
          onTrigger: () => trigger(item),
        },
      }
    }),
  )
  const footerGroup = (match: (item: ReturnType<typeof footerActions>[number]) => boolean) =>
    footerActions()
      .filter(match)
      .map((item) => item.action)

  function trigger(item: Action | undefined) {
    if (props.locked || !item || isActionDisabled(item)) return
    if (item.selection === "none") {
      item.onTrigger()
      return
    }
    const option = selected()
    if (!option) return
    item.onTrigger(option)
  }

  function isActionItem(item: VisibleAction): item is Action & { label: string } {
    return "onTrigger" in item
  }

  function isActionDisabled(item: Action) {
    const option = selected()
    if (item.selection !== "none" && !option) return true
    return typeof item.disabled === "function" ? item.disabled(option) : item.disabled
  }

  const searchInTitle = () => newDesigns() && props.searchInTitle === true && props.renderFilter !== false

  const searchInput = () => (
    <input
      flexGrow={1}
      onInput={(e) => {
        if (props.locked) return
        batch(() => {
          setStore("filter", e)
          props.onFilter?.(e)
        })
      }}
      focusedBackgroundColor={theme.background.formfield.focused}
      cursorColor={newDesigns() ? theme.text.base : theme.text.formfield.focused}
      cursorStyle={config.cursor}
      focusedTextColor={theme.text.formfield.focused}
      ref={(r) => {
        input = r
        input.traits = { status: "FILTER" }
        setTimeout(() => {
          if (!input) return
          if (r.isDestroyed) return
          r.focus()
        }, 1)
      }}
      placeholder={(searchInTitle() ? props.titlePlaceholder : undefined) ?? props.placeholder ?? "Search"}
      placeholderColor={newDesigns() ? theme.text.faint : theme.text.muted}
    />
  )

  return (
    <DialogLayout
      header={
        // Rows reserve a gutter, so the header and footer line up with the list's inset rather than the layout's.
        <box paddingLeft={DIALOG_LIST_INSET - DIALOG_INSET} paddingRight={DIALOG_LIST_INSET - DIALOG_INSET}>
          <Show
            when={searchInTitle()}
            fallback={
              <>
                <DialogHeader title={props.title} titleView={props.titleView} onClose={props.onCancel} />
                <Show when={props.renderFilter !== false}>
                  <box paddingTop={1}>{searchInput()}</box>
                </Show>
              </>
            }
          >
            <DialogHeader titleView={searchInput()} gap={2} onClose={props.onCancel} />
          </Show>
        </box>
      }
      footer={{
        inset: DIALOG_LIST_INSET - DIALOG_INSET,
        actions: {
          secondary: footerGroup((item) => item.group === "secondary"),
          primary: footerGroup((item) => item.group === "primary"),
        },
        get children() {
          return props.footer
        },
      }}
      legacyFooter={
        <Show when={props.footer || visibleActions().length} fallback={<box flexShrink={0} />}>
          <DialogFooter
            inset={DIALOG_LIST_INSET - DIALOG_INSET}
            actions={{
              secondary: footerGroup((item) => item.side !== "right"),
              primary: footerGroup((item) => item.side === "right"),
            }}
          >
            {props.footer}
          </DialogFooter>
        </Show>
      }
    >
      <DialogBleed>
        <Show
          when={grouped().length > 0}
          fallback={
            <Show
              when={props.renderFilter !== false && store.filter.length > 0}
              fallback={
                props.emptyView ?? (
                  <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
                    <text fg={theme.text.muted}>No items available</text>
                  </box>
                )
              }
            >
              {props.noMatchView ?? (
                <box paddingLeft={DIALOG_LIST_INSET} paddingRight={DIALOG_LIST_INSET}>
                  <text fg={theme.text.muted}>No results found</text>
                </box>
              )}
            </Show>
          }
        >
          {/* The 1-cell inset keeps the row highlight off the panel edge; rows add the rest of DIALOG_LIST_INSET. */}
          <scrollbox
            // Under new designs rows run edge to edge: a 1-cell gutter holds the selection bar on the left.
            paddingLeft={newDesigns() ? 0 : 1}
            paddingRight={newDesigns() ? 0 : 1}
            scrollbarOptions={{ visible: false }}
            scrollAcceleration={scrollAcceleration()}
            ref={(r: ScrollBoxRenderable) => {
              scroll = r
              r.verticalScrollBar.on("change", updateMoreBelow)
              r.content.on("resize", updateMoreBelow)
              r.viewport.on("resize", updateMoreBelow)
            }}
            maxHeight={height()}
          >
            <For each={grouped()}>
              {([category, options], index) => (
                <>
                  <Show when={category}>
                    <DialogSelectCategory title={category} first={index() === 0} />
                  </Show>
                  <For each={options}>
                    {(option) => {
                      const active = createMemo(() => !props.locked && isDeepEqual(option.value, selected()?.value))
                      const current = createMemo(() => isDeepEqual(option.value, props.current))
                      return (
                        <box
                          flexDirection="column"
                          position="relative"
                          onMouseMove={() => {
                            if (props.locked) return
                            const index = flat().findIndex((x) => isDeepEqual(x.value, option.value))
                            if (index === -1 || index === store.selected) return
                            moveTo(index)
                          }}
                          onMouseUp={() => {
                            if (props.locked) return
                            option.onSelect?.(dialog)
                            props.onSelect?.(option)
                          }}
                          onMouseDown={() => {
                            if (props.locked) return
                            const index = flat().findIndex((x) => isDeepEqual(x.value, option.value))
                            if (index === -1) return
                            moveTo(index)
                          }}
                        >
                          <DialogSelectRow
                            title={option.title}
                            titleView={option.titleView}
                            footer={
                              flatten() ? (option.searchFooter ?? option.category ?? option.footer) : option.footer
                            }
                            footerColor={option.footerColor}
                            titleWidth={option.titleWidth}
                            truncateTitle={option.truncateTitle}
                            description={option.description !== category ? option.description : undefined}
                            active={active()}
                            current={current()}
                            activeBackground={option.bg}
                            activeColor={option.fg}
                            gutter={option.gutter}
                            margin={option.margin}
                          />
                          <DialogSelectDetails details={option.details} />
                        </box>
                      )
                    }}
                  </For>
                </>
              )}
            </For>
          </scrollbox>
          <Show when={overflows()}>
            <box paddingLeft={DIALOG_LIST_INSET} flexShrink={0}>
              <text fg={theme.text.faint}>{moreBelow() ? "…" : " "}</text>
            </box>
          </Show>
        </Show>
      </DialogBleed>
    </DialogLayout>
  )
}

function DialogSelectCategory(props: { title: string; first: boolean }) {
  const theme = useTheme().surface("dialog")
  const newDesigns = useNewDesigns()
  return (
    <box paddingTop={props.first ? 0 : 1} paddingLeft={DIALOG_LIST_INSET - (newDesigns() ? 0 : 1)}>
      <text fg={newDesigns() ? theme.text.faint : theme.hue.accent[200]} attributes={TextAttributes.BOLD}>
        {props.title}
      </text>
    </box>
  )
}

function DialogSelectRow(props: {
  title: string
  titleView?: JSX.Element
  description?: string
  active: boolean
  current: boolean
  footer?: JSX.Element | string
  footerColor?: RGBA
  titleWidth?: number
  truncateTitle?: boolean | "left"
  gutter?: (color: RGBA) => JSX.Element
  margin?: JSX.Element
  activeBackground?: RGBA
  activeColor?: RGBA
}) {
  const theme = useTheme().surface("dialog")
  const newDesigns = useNewDesigns()
  const text = createMemo(() => {
    if (props.active) return props.activeColor ?? theme.text.action.primary.focused
    if (props.current && !newDesigns()) return theme.text.formfield.selected
    return theme.text.base
  })
  // Secondary text (description and footer) on the highlighted row.
  const secondary = () => (newDesigns() ? theme.text.action.secondary.focused : text())

  const row = () => (
    // A marker or gutter takes its cell plus the row gap out of the left padding,
    // so titles line up with unmarked rows: scroll pad (1) + marker (1) + gap (1).
    <box
      flexDirection="row"
      flexGrow={newDesigns() ? 1 : undefined}
      paddingLeft={props.current || props.gutter ? DIALOG_LIST_INSET - 3 : DIALOG_LIST_INSET - 1}
      paddingRight={DIALOG_LIST_INSET - (newDesigns() ? 0 : 1)}
      gap={1}
      backgroundColor={
        props.active ? (props.activeBackground ?? theme.background.action.primary.focused) : RGBA.fromInts(0, 0, 0, 0)
      }
    >
      <Show when={!props.current && props.margin}>
        <box position="absolute" left={DIALOG_LIST_INSET - 3} flexShrink={0}>
          {props.margin}
        </box>
      </Show>
      <Show when={props.current && !props.gutter}>
        <text flexShrink={0} fg={newDesigns() ? theme.text.formfield.selected : text()}>
          {newDesigns() ? "▪" : "●"}
        </text>
      </Show>
      <Show when={props.gutter}>
        <box flexShrink={0}>{props.gutter?.(text())}</box>
      </Show>
      <text
        flexGrow={1}
        fg={text()}
        attributes={props.active && !newDesigns() ? TextAttributes.BOLD : undefined}
        overflow="hidden"
        wrapMode="none"
        paddingLeft={3}
      >
        {props.titleView ??
          (props.truncateTitle === false
            ? props.title
            : props.truncateTitle === "left"
              ? Locale.truncateLeft(props.title, props.titleWidth ?? 61)
              : Locale.truncate(props.title, props.titleWidth ?? 61))}
        <Show when={props.description}>
          <span style={{ fg: props.active ? secondary() : theme.text.muted }}>{" " + props.description}</span>
        </Show>
      </text>
      <Show when={props.footer}>
        <box flexShrink={0}>
          <text fg={props.active ? secondary() : (props.footerColor ?? theme.text.muted)}>{props.footer}</text>
        </box>
      </Show>
    </box>
  )

  return (
    <Show when={newDesigns()} fallback={row()}>
      <box flexDirection="row">
        <text width={1} flexShrink={0} fg={theme.text.formfield.focused}>
          {props.active ? "┃" : " "}
        </text>
        {row()}
      </box>
    </Show>
  )
}

function DialogSelectDetails(props: { details?: string[] }) {
  const theme = useTheme().surface("dialog")
  const dialog = useDialog()
  const dimensions = useTerminalDimensions()
  const width = createMemo(() => dialogSelectContentWidth(Math.min(dialogWidth(dialog.size), dimensions().width)))
  const newDesigns = useNewDesigns()
  return (
    <For each={props.details}>
      {(detail) => (
        <box
          paddingLeft={DIALOG_LIST_INSET - (newDesigns() ? 0 : 1)}
          paddingRight={DIALOG_LIST_INSET - (newDesigns() ? 0 : 1)}
        >
          <text fg={theme.text.muted} wrapMode="none">
            {Locale.truncateMiddle(detail, Math.max(1, width()))}
          </text>
        </box>
      )}
    </For>
  )
}

import { useRenderer, useTerminalDimensions } from "@opentui/solid"
import {
  batch,
  children,
  createContext,
  createEffect,
  createSignal,
  For,
  onCleanup,
  Show,
  useContext,
  type JSX,
  type ParentProps,
} from "solid-js"
import { Keymap } from "../context/keymap"
import { ThemeContextProvider, useTheme } from "../context/theme"
import { InputRenderable, MouseButton, Renderable, RGBA, TextAttributes } from "@opentui/core"
import { createStore } from "solid-js/store"
import { useToast } from "./toast"
import { useClipboard } from "../context/clipboard"
import { useConfig, useNewDesigns } from "../config"
import { copy, copyOnSelectRelease } from "../util/selection"

export type DialogSize = "medium" | "large" | "xlarge"

export const DIALOG_INSET = 3
// List rows reserve a 1-cell gutter for the ▌ bar / ● marker.
export const DIALOG_LIST_INSET = DIALOG_INSET + 1

export function dialogWidth(size: DialogSize) {
  if (size === "xlarge") return 116
  if (size === "large") return 88
  return 60
}

export function Dialog(
  props: ParentProps<{
    size?: DialogSize
    centered?: boolean
    onClose: () => void
  }>,
) {
  const dimensions = useTerminalDimensions()
  const theme = useTheme().surface("dialog")
  const renderer = useRenderer()

  let dismiss = false
  return (
    <ThemeContextProvider context="dialog">
      <box
        onMouseDown={() => {
          dismiss = !!renderer.getSelection()
        }}
        onMouseUp={() => {
          if (dismiss) {
            dismiss = false
            return
          }
          props.onClose?.()
        }}
        width={dimensions().width}
        height={dimensions().height}
        alignItems="center"
        justifyContent={props.centered ? "center" : undefined}
        position="absolute"
        zIndex={3000}
        paddingTop={props.centered ? 0 : dimensions().height / 4}
        left={0}
        top={0}
        backgroundColor={RGBA.fromInts(0, 0, 0, 150)}
      >
        <box
          onMouseUp={(e: { stopPropagation(): void }) => {
            // A selection release must bubble up to the copy-on-select handler in
            // DialogProvider; the backdrop's dismiss flag keeps it from closing the dialog.
            if (renderer.getSelection()?.getSelectedText()) return
            dismiss = false
            e.stopPropagation()
          }}
          width={dialogWidth(props.size ?? "medium")}
          maxWidth={dimensions().width - 2}
          backgroundColor={theme.background.base}
          paddingTop={1}
        >
          {props.children}
        </box>
      </box>
    </ThemeContextProvider>
  )
}

export function DialogHeader(
  props: ParentProps<{
    title?: JSX.Element
    titleView?: JSX.Element
    closeLabel?: string
    onClose?: () => void
    gap?: number
    /** Faint line below the title. Shown only under the "new-designs" experiment. */
    description?: string
  }>,
) {
  const dialog = useDialog()
  const theme = useTheme().surface("dialog")
  const newDesigns = useNewDesigns()
  const row = () => (
    <box flexDirection="row" justifyContent="space-between" gap={props.gap}>
      {props.titleView ?? (
        <text attributes={newDesigns() ? undefined : TextAttributes.BOLD} fg={theme.text.base}>
          {props.title}
        </text>
      )}
      {props.children}
      <text
        fg={newDesigns() ? theme.text.faint : theme.text.muted}
        flexShrink={0}
        onMouseUp={() => (props.onClose ?? dialog.clear)()}
      >
        {props.closeLabel ?? "esc"}
      </text>
    </box>
  )
  return (
    <Show when={newDesigns() && props.description} fallback={row()}>
      <box>
        {row()}
        <text fg={theme.text.faint} wrapMode="word">
          {props.description}
        </text>
      </box>
    </Show>
  )
}

/**
 * Standard dialog layout: header, body and an optional footer, one blank row between
 * each and one blank row at the bottom, with the shared side padding.
 */
export function DialogLayout(
  props: ParentProps<{
    id?: string
    /** Usually a `DialogHeader`. */
    header: JSX.Element
    /** Rendered as a `DialogFooter`. */
    footer?: DialogFooterProps
    /** Footer shown while the "new-designs" experiment is off. Remove when the experiment graduates. */
    legacyFooter?: JSX.Element
    /** Side padding in cells. Defaults to DIALOG_INSET. */
    inset?: number
  }>,
) {
  const inset = () => props.inset ?? DIALOG_INSET
  const newDesigns = useNewDesigns()
  return (
    <box id={props.id} paddingLeft={inset()} paddingRight={inset()} paddingBottom={1} gap={1}>
      {props.header}
      <box>{props.children}</box>
      <Show when={newDesigns() || props.legacyFooter === undefined} fallback={props.legacyFooter}>
        <Show when={props.footer}>
          {(footer) => (
            <DialogFooter actions={footer().actions} inset={footer().inset}>
              {footer().children}
            </DialogFooter>
          )}
        </Show>
      </Show>
    </box>
  )
}

/** Stretches a raised band inside a `DialogLayout` across the side padding; its content re-applies `DIALOG_INSET`. */
export function DialogBleed(props: ParentProps) {
  return (
    <box marginLeft={-DIALOG_INSET} marginRight={-DIALOG_INSET}>
      {props.children}
    </box>
  )
}

export type DialogFooterAction = {
  title: string
  /** Literal key label, e.g. "enter". */
  key?: string
  /** Keymap command id whose first shortcut is shown when `key` is not set. The action hides when it has no shortcut. */
  command?: string
  onTrigger?: () => void
  disabled?: boolean
  /** Overrides the title color, e.g. for a "✓ copied" confirmation. */
  color?: RGBA
}

/**
 * Alignment separates scope: `secondary` holds dialog-level actions on the left, `primary` holds actions
 * on the selected item (or the dialog's main action) on the right.
 */
export type DialogFooterActions = {
  secondary?: DialogFooterAction[]
  primary?: DialogFooterAction[]
}

export type DialogFooterProps = ParentProps<{
  actions?: DialogFooterActions
  /** Side padding in cells, e.g. DIALOG_INSET or DIALOG_LIST_INSET. Omit when the parent already pads. */
  inset?: number
}>

export function DialogFooter(props: DialogFooterProps) {
  const dimensions = useTerminalDimensions()
  const shortcuts = Keymap.useShortcuts()
  const theme = useTheme().surface("dialog")
  const newDesigns = useNewDesigns()
  const narrow = () => dimensions().width < 60
  const resolve = (actions: DialogFooterAction[] = []) =>
    actions.flatMap((action) => {
      if (action.key !== undefined || action.command === undefined) return [action]
      const key = shortcuts.get(action.command)
      return key ? [{ ...action, key }] : []
    })
  const secondary = () => resolve(props.actions?.secondary)
  const primary = () => resolve(props.actions?.primary)
  const content = children(() => props.children)
  // The raised band bleeds across the parent's DIALOG_INSET padding and the layout's bottom row,
  // so it spans the dialog edge to edge and sits flush with its bottom.
  const band = () => newDesigns() && (secondary().length > 0 || primary().length > 0 || content.toArray().length > 0)
  // Hoverable actions carry one cell of padding on each side; the band gives that cell back so labels keep their column.
  const bandInset = () => DIALOG_INSET + (props.inset ?? 0) - 1
  return (
    <box
      marginLeft={band() ? -DIALOG_INSET : undefined}
      marginRight={band() ? -DIALOG_INSET : undefined}
      marginBottom={band() ? -1 : undefined}
      paddingLeft={band() ? bandInset() : props.inset}
      paddingRight={band() ? bandInset() : props.inset}
      paddingTop={band() ? 1 : undefined}
      paddingBottom={band() ? 1 : undefined}
      backgroundColor={band() ? theme.background.raised.high : undefined}
      flexDirection="row"
      justifyContent="space-between"
      gap={newDesigns() ? 2 : undefined}
      flexShrink={0}
    >
      <box
        flexDirection={narrow() ? "column" : "row"}
        gap={narrow() || newDesigns() ? 0 : 2}
        columnGap={newDesigns() && !narrow() ? 1 : undefined}
        // Under new designs the primary group keeps its width and the secondary group wraps instead of overlapping.
        flexWrap={newDesigns() ? "wrap" : undefined}
        flexShrink={newDesigns() ? 1 : undefined}
        minWidth={newDesigns() ? 0 : undefined}
      >
        {content()}
        <For each={secondary()}>{(action) => <DialogFooterItem action={action} variant="secondary" />}</For>
      </box>
      <box flexDirection="row" gap={newDesigns() ? 1 : 2} flexShrink={newDesigns() ? 0 : undefined}>
        <For each={primary()}>{(action) => <DialogFooterItem action={action} variant="primary" />}</For>
      </box>
    </box>
  )
}

function DialogFooterItem(props: { action: DialogFooterAction; variant: "primary" | "secondary" }) {
  const theme = useTheme().surface("dialog")
  const newDesigns = useNewDesigns()
  const [hovered, setHovered] = createSignal(false)
  const trigger = () => {
    if (props.action.disabled) return
    props.action.onTrigger?.()
  }
  const label = (key: RGBA) => (
    <>
      <span
        style={{
          fg: props.action.disabled ? theme.text.action.primary.disabled : (props.action.color ?? theme.text.base),
        }}
      >
        {props.action.title}
      </span>
      <Show when={props.action.key}>
        <span style={{ fg: props.action.disabled ? theme.text.action.primary.disabled : key }}>
          {" " + props.action.key}
        </span>
      </Show>
    </>
  )
  return (
    <Show when={newDesigns()} fallback={<text onMouseUp={trigger}>{label(theme.text.muted)}</text>}>
      <box
        paddingLeft={1}
        paddingRight={1}
        flexShrink={0}
        backgroundColor={
          hovered() && !props.action.disabled ? theme.background.action[props.variant].hovered : undefined
        }
        onMouseOver={() => setHovered(true)}
        onMouseOut={() => setHovered(false)}
        onMouseUp={trigger}
      >
        <text>{label(theme.text.faint)}</text>
      </box>
    </Show>
  )
}

function init() {
  const [store, setStore] = createStore({
    stack: [] as {
      element: () => JSX.Element
      onClose?: () => void
      key?: unknown
    }[],
    size: "medium" as DialogSize,
    centered: false,
  })

  const renderer = useRenderer()
  const keymap = Keymap.use()

  createEffect(() => {
    if (store.stack.length === 0) return
    const popMode = keymap.mode.push("modal")
    onCleanup(popMode)
  })

  let focus: Renderable | null
  function refocus() {
    setTimeout(() => {
      if (store.stack.length > 0) return
      if (!focus) return
      if (focus.isDestroyed) return
      function find(item: Renderable) {
        for (const child of item.getChildren()) {
          if (child === focus) return true
          if (find(child)) return true
        }
        return false
      }
      const found = find(renderer.root)
      if (!found) return
      focus.focus()
    }, 1)
  }

  Keymap.createLayer(() => ({
    mode: "modal",
    enabled: store.stack.length > 0,
    commands: [
      {
        bind: "escape",
        title: "Close dialog",
        group: "Dialog",
        run: () => {
          if (renderer.getSelection()) {
            renderer.clearSelection()
            return
          }
          const current = store.stack.at(-1)
          current?.onClose?.()
          setStore("stack", store.stack.slice(0, -1))
          refocus()
        },
      },
      {
        bind: "ctrl+c",
        title: "Close dialog",
        group: "Dialog",
        run: () => {
          if (renderer.getSelection()) {
            renderer.clearSelection()
            return
          }
          const editor = renderer.currentFocusedEditor
          if (editor?.plainText) {
            if (editor instanceof InputRenderable) editor.value = ""
            else editor.setText("")
            return
          }
          const current = store.stack.at(-1)
          current?.onClose?.()
          setStore("stack", store.stack.slice(0, -1))
          refocus()
        },
      },
    ],
  }))

  return {
    clear() {
      for (const item of store.stack) {
        if (item.onClose) item.onClose()
      }
      batch(() => {
        setStore("size", "medium")
        setStore("centered", false)
        setStore("stack", [])
      })
      refocus()
    },
    replace(input: () => JSX.Element, onClose?: () => void, options?: { key?: unknown; size?: DialogSize }) {
      if (store.stack.length === 0) {
        focus = renderer.currentFocusedRenderable
        focus?.blur()
      }
      for (const item of store.stack) {
        if (item.onClose) item.onClose()
      }
      batch(() => {
        setStore("size", options?.size ?? "medium")
        setStore("centered", false)
        setStore("stack", [
          {
            element: input,
            onClose,
            key: options?.key,
          },
        ])
      })
    },
    get stack() {
      return store.stack
    },
    get size() {
      return store.size
    },
    get centered() {
      return store.centered
    },
    get key() {
      return store.stack.at(-1)?.key
    },
    setSize(size: "medium" | "large" | "xlarge") {
      setStore("size", size)
    },
    setCentered(centered: boolean) {
      setStore("centered", centered)
    },
  }
}

export type DialogContext = ReturnType<typeof init>

const ctx = createContext<DialogContext>()

export function DialogProvider(props: ParentProps) {
  const value = init()
  const renderer = useRenderer()
  const toast = useToast()
  const clipboard = useClipboard()
  const config = useConfig()
  const copyOnSelectEnabled = () =>
    (config.data.terminal?.copy ?? (process.platform === "win32" ? "manual" : "select")) === "select"

  return (
    <ctx.Provider value={value}>
      {props.children}
      <box
        position="absolute"
        zIndex={3000}
        onMouseDown={(evt: { button: number; preventDefault(): void; stopPropagation(): void }) => {
          if (copyOnSelectEnabled()) return
          if (evt.button !== MouseButton.RIGHT) return

          if (!copy(renderer, toast, clipboard)) return
          evt.preventDefault()
          evt.stopPropagation()
        }}
        onMouseUp={
          copyOnSelectEnabled() ? (event) => copyOnSelectRelease(event, renderer, toast, clipboard) : undefined
        }
      >
        <Show when={value.stack.length}>
          <Dialog onClose={() => value.clear()} size={value.size} centered={value.centered}>
            {/* Render each entry once: inserting the element function directly would re-run it, remounting
                the dialog with fresh state, whenever a signal it reads at its root (e.g. a top-level <Show>) changes. */}
            <Show when={value.stack.at(-1)} keyed>
              {(item) => item.element()}
            </Show>
          </Dialog>
        </Show>
      </box>
    </ctx.Provider>
  )
}

export function useDialog() {
  const value = useContext(ctx)
  if (!value) {
    throw new Error("useDialog must be used within a DialogProvider")
  }
  return value
}

import type { RGBA } from "@opentui/core"
import { createMemo } from "solid-js"
import { stringWidth } from "../util/string-width"

const graphemeSegmenter = new Intl.Segmenter(undefined, { granularity: "grapheme" })

export interface FilePathProps {
  value: string
  maxWidth: number
  fg?: RGBA
  basenameFg?: RGBA
}

export function FilePath(props: FilePathProps) {
  const display = createMemo(() => {
    const value = truncateFilePath(props.value, props.maxWidth)
    const index = Math.max(value.lastIndexOf("/"), value.lastIndexOf("\\"))
    return {
      parent: value.slice(0, index + 1),
      basename: value.slice(index + 1),
    }
  })
  return (
    <text fg={props.fg} wrapMode="none" truncate>
      <span style={{ fg: props.fg }}>{display().parent}</span>
      <span style={{ fg: props.basenameFg ?? props.fg }}>{display().basename}</span>
    </text>
  )
}

export function truncateFilePath(value: string, maxWidth: number) {
  if (maxWidth <= 0) return ""
  if (stringWidth(value) <= maxWidth) return value

  const drive = value.match(/^([A-Za-z]:)([\\/])/)
  const unc = value.match(/^(\\\\|\/\/)([^\\/]+)[\\/]([^\\/]+)(?:[\\/]|$)/)
  const windows = drive !== null || unc !== null || (!value.includes("/") && value.includes("\\"))
  const separator = drive?.[2] ?? (unc?.[1] === "//" ? "/" : windows ? "\\" : "/")
  const root = drive
    ? drive[1] + separator
    : unc
      ? unc[1] + unc[2] + separator + unc[3] + separator
      : value.startsWith("/")
        ? "/"
        : ""
  const source = value.slice(drive?.[0].length ?? unc?.[0].length ?? root.length)
  const segments = source.split(windows ? /[\\/]/ : separator).filter(Boolean)
  const basename = segments.at(-1) ?? value
  if (segments.length < 2) {
    const rootWidth = stringWidth(root)
    if (rootWidth >= maxWidth) return takeStart(root, maxWidth)
    return root + truncateBasename(basename, maxWidth - rootWidth)
  }

  const prefix = `${root}…${separator}`
  const basenameWidth = maxWidth - stringWidth(prefix)
  if (basenameWidth <= 0) return takeStart(prefix, maxWidth)
  const compact = truncateBasename(basename, basenameWidth)
  if (compact !== basename) return prefix + compact

  const selected = [basename]
  const separatorWidth = stringWidth(separator)
  let width = stringWidth(prefix + basename)
  for (let index = segments.length - 2; index >= 0; index--) {
    const segment = segments[index]!
    const next = stringWidth(segment) + separatorWidth
    if (width + next > maxWidth) {
      const available = maxWidth - width - separatorWidth
      if (available > 1) selected.unshift(takeStart(segment, available - 1) + "…")
      break
    }
    selected.unshift(segment)
    width += next
  }
  return prefix + selected.join(separator)
}

function truncateBasename(value: string, maxWidth: number) {
  if (stringWidth(value) <= maxWidth) return value
  if (maxWidth <= 1) return takeStart("…", maxWidth)

  const dot = value.lastIndexOf(".")
  const extension = dot > 0 ? value.slice(dot) : ""
  const extensionWidth = stringWidth(extension)
  if (extensionWidth >= maxWidth) return "…" + takeEnd(extension, maxWidth - 1)

  const stem = extension ? value.slice(0, dot) : value
  return takeStart(stem, maxWidth - extensionWidth - 1) + "…" + extension
}

function takeStart(value: string, maxWidth: number) {
  return take(value, maxWidth, false)
}

function takeEnd(value: string, maxWidth: number) {
  return take(value, maxWidth, true)
}

function take(value: string, maxWidth: number, reverse: boolean) {
  const segments = Array.from(graphemeSegmenter.segment(value), (item) => item.segment)
  if (reverse) segments.reverse()
  const selected: string[] = []
  let width = 0
  for (const segment of segments) {
    const next = stringWidth(segment)
    if (width + next > maxWidth) break
    selected.push(segment)
    width += next
  }
  if (reverse) selected.reverse()
  return selected.join("")
}

export const SESSION_SIDEBAR_WIDTH = 42
export const SESSION_TABS_COMPACT_WIDTH = 5
export const SESSION_TABS_COMPACT_BREAKPOINT = 12
export const SESSION_SIDEBAR_MAX_WIDTH = 72
const SESSION_CONTENT_MIN_WIDTH = 44
const SESSION_CONTENT_PREFERRED_WIDTH = 64
// Like vertical tabs, a docked panel fits when the session keeps its preferred width beside a minimum-width pane.
// Narrower, panels take over the screen.
export const SESSION_PANEL_SPLIT_MIN_WIDTH = SESSION_CONTENT_PREFERRED_WIDTH + SESSION_CONTENT_MIN_WIDTH

export function sessionTabsFitVertically(total: number, width = SESSION_SIDEBAR_WIDTH) {
  return total >= width + SESSION_CONTENT_PREFERRED_WIDTH
}

export function clampSessionTabsWidth(width: number, total: number) {
  return Math.max(
    SESSION_TABS_COMPACT_WIDTH,
    Math.min(width, SESSION_SIDEBAR_MAX_WIDTH, total - SESSION_CONTENT_MIN_WIDTH),
  )
}

export function clampSessionPaneWidth(width: number, total: number) {
  const half = Math.max(1, Math.floor(total / 2))
  // Preserve the equal split when there is not enough room for both pane minima.
  return Math.max(Math.min(24, half), Math.min(width, Math.max(half, total - SESSION_CONTENT_MIN_WIDTH)))
}

import type { JSX } from "solid-js"
import type { CliRenderer, MouseEvent, RGBA } from "@opentui/core"
import { openUrl } from "@opencode/util/open"

export interface LinkProps {
  href: string
  children?: JSX.Element | string
  fg?: RGBA
  bg?: RGBA
  width?: number | "auto" | `${number}%`
  wrapMode?: "word" | "none"
}

/**
 * Link component that renders clickable hyperlinks.
 * Clicking anywhere on the link text opens the URL in the default browser.
 */
export function Link(props: LinkProps) {
  const displayText = props.children ?? props.href

  return (
    <text
      fg={props.fg}
      bg={props.bg}
      width={props.width}
      wrapMode={props.wrapMode}
      onMouseUp={() => {
        openUrl(props.href).catch(() => {})
      }}
    >
      <a href={props.href}>{displayText}</a>
    </text>
  )
}

/**
 * Returns the hyperlink under a plain left click. opentui marks the release that ends a selection gesture with
 * `isDragging`, and a fresh "cell" selection means the pointer never moved; other releases, such as the end of a drag
 * that started outside text, are not clicks. Each rendered cell stores its full URL, so a click on any row of a wrapped
 * link resolves the whole link. Modified clicks are left to the terminal's own hyperlink handling.
 */
export function clickedLink(renderer: CliRenderer, event: MouseEvent) {
  if (!event.isDragging || event.modifiers.ctrl || event.modifiers.alt || event.modifiers.shift) return
  const selection = renderer.getSelection()
  if (!selection?.isStart || selection.behavior !== "cell") return
  return renderer.getLinkAt(event.x, event.y) ?? undefined
}

import { octantGlyph } from "./subcell"
import type { Config } from "../config"

export type OneCellMotion = {
  frames: string[]
  interval: number
  levels?: number[]
  intro?: Pick<OneCellMotion, "frames" | "interval" | "levels">
  once?: boolean
  pace?: { initial: number; final: number; after: number; duration: number }
}

export function oneCellFrame(animation: OneCellMotion, elapsed: number) {
  const introDuration = animation.intro ? animation.intro.frames.length * animation.intro.interval : 0
  const intro = elapsed < introDuration
  const clip = intro ? animation.intro! : animation
  const pace = animation.pace
  const progress = pace ? Math.max(0, Math.min(1, (elapsed - pace.after) / pace.duration)) : 0
  // Integrate the changing rate so slowing down does not jump or restart the motion.
  const time = intro
    ? elapsed
    : !pace
      ? elapsed - introDuration
      : (elapsed - introDuration) * pace.initial +
        (pace.final - pace.initial) *
          (pace.duration * (progress ** 3 - progress ** 4 / 2) + Math.max(0, elapsed - pace.after - pace.duration))
  // Keep cycle boundaries exact when individual frame intervals are fractional.
  const frame = Math.floor((time * clip.frames.length) / (clip.interval * clip.frames.length))
  const index = !intro && animation.once ? Math.min(frame, clip.frames.length - 1) : frame % clip.frames.length
  return {
    glyph: clip.frames[index]!,
    level: clip.levels?.[index] ?? 1,
    complete: !intro && !!animation.once && frame >= clip.frames.length - 1,
  }
}

export const SEED_WORK: OneCellMotion = {
  frames: Array.from({ length: 40 }, () => "\u25aa"),
  interval: 40,
  levels: Array.from({ length: 40 }, (_, index) => 0.3 + (0.7 * (1 - Math.cos((index / 40) * 2 * Math.PI))) / 2),
  intro: {
    frames: Array.from({ length: 80 }, () => "\u25aa"),
    interval: 40,
    levels: Array.from({ length: 80 }, (_, index) => {
      const phase = index / 80
      return 0.3 + 0.7 * (phase < 0.125 ? phase / 0.125 : phase < 0.375 ? 1 : ((1 - phase) / 0.625) ** 3)
    }),
  },
  pace: { initial: 1.25, final: 0.5, after: 30_000, duration: 30_000 },
}

const WORK_PACE = { initial: 1.2, final: 0.96, after: 30_000, duration: 30_000 }
const lower = [2, 3, 5, 7, 6, 4]

export const BLOCK_LOW_COMET: OneCellMotion = {
  frames: lower.flatMap((point, index, path) => {
    const leading = (1 << point) | (1 << path[(index + 5) % 6]!)
    const full = leading | (1 << path[(index + 4) % 6]!)
    return [full, full, full, leading, leading].map(octantGlyph)
  }),
  interval: 40,
  pace: WORK_PACE,
}

