import { MouseButton, type MouseEvent } from "@opentui/core"
import { createEffect, createSignal } from "solid-js"

export function createPaneResize(options: {
  value: () => number
  defaultValue: () => number
  clamp: (size: number) => number
  fromMouse: (event: MouseEvent) => number
  contains: (event: MouseEvent, size: number) => boolean
  onCommit: (size: number) => void
}) {
  const [preferredSize, setPreferredSize] = createSignal(options.value())
  const [hovered, setHovered] = createSignal(false)
  const [resizing, setResizing] = createSignal(false)
  let requestedSize = options.value()
  createEffect(() => {
    if (resizing()) return
    requestedSize = options.value()
    setPreferredSize(requestedSize)
  })
  const size = () => options.clamp(preferredSize())
  const commit = (value: number) => {
    const next = options.clamp(value)
    setPreferredSize(next)
    if (requestedSize === next) return
    requestedSize = next
    options.onCommit(next)
  }
  let moved = false
  let lastBoundaryClick = 0
  const finish = (event: MouseEvent) => {
    if (!resizing()) return
    const next = moved ? options.fromMouse(event) : size()
    setResizing(false)
    lastBoundaryClick = moved ? 0 : Date.now()
    commit(next)
    setHovered(options.contains(event, options.clamp(next)))
    event.stopPropagation()
  }

  // Bind drag/release on the parent so resizing continues outside the handle.
  return {
    preferredSize,
    size,
    hovered,
    resizing,
    onMouseOver: () => setHovered(true),
    onMouseOut: () => setHovered(false),
    onMouseDown: (event: MouseEvent) => {
      if (event.button !== MouseButton.LEFT) return
      const now = Date.now()
      if (now - lastBoundaryClick < 300) {
        lastBoundaryClick = 0
        setResizing(false)
        setHovered(false)
        commit(options.defaultValue())
        event.preventDefault()
        event.stopPropagation()
        return
      }
      moved = false
      setResizing(true)
      event.preventDefault()
      event.stopPropagation()
    },
    onMouseDrag: (event: MouseEvent) => {
      if (!resizing()) return
      moved = true
      lastBoundaryClick = 0
      setPreferredSize(options.clamp(options.fromMouse(event)))
      event.stopPropagation()
    },
    onMouseDragEnd: finish,
    onMouseUp: finish,
  }
}

export function reconcileSelection(selected: number, count: number) {
  return Math.max(0, Math.min(count - 1, selected))
}

export function moveSelection(selected: number, input: { count: number; delta: number; policy: "clamp" | "wrap" }) {
  if (input.count <= 0) return 0
  const next = selected + input.delta
  if (input.policy === "clamp") return reconcileSelection(next, input.count)
  if (next < 0) return input.count - 1
  if (next >= input.count) return 0
  return next
}

export function revealSelectionOffset(offset: number, input: { count: number; limit: number; selected: number }) {
  const max = maxOffset(input.count, input.limit)
  if (input.selected < offset) return Math.min(max, input.selected)
  if (input.selected >= offset + input.limit) return Math.min(max, input.selected - input.limit + 1)
  return Math.max(0, Math.min(max, offset))
}

export function reconcileSelectionWindow(selected: number, input: { count: number; limit: number; offset: number }) {
  if (input.count <= 0) return 0
  const first = reconcileSelection(input.offset, input.count)
  const last = Math.min(input.count - 1, first + Math.max(1, input.limit) - 1)
  return Math.max(first, Math.min(last, selected))
}

export function moveSelectionOffset(
  offset: number,
  input: { count: number; limit: number; selected: number; direction: -1 | 1 },
) {
  const max = maxOffset(input.count, input.limit)
  const margin = Math.max(0, Math.min(2, Math.floor((input.limit - 1) / 2)))
  if (input.direction < 0 && input.selected < offset + margin) {
    return Math.max(0, Math.min(max, input.selected - margin))
  }
  if (input.direction > 0 && input.selected > offset + input.limit - margin - 1) {
    return Math.min(max, input.selected - input.limit + margin + 1)
  }
  return Math.max(0, Math.min(max, offset))
}

function maxOffset(count: number, limit: number) {
  return Math.max(0, count - limit)
}

import type { ColorInput } from "@opentui/core"
import { RGBA } from "@opentui/core"
import type { ColorGenerator } from "opentui-spinner"

interface AdvancedGradientOptions {
  colors: ColorInput[]
  trailLength: number
  defaultColor?: ColorInput
  direction?: "forward" | "backward" | "bidirectional"
  holdFrames?: { start?: number; end?: number }
  enableFading?: boolean
  minAlpha?: number
}

interface ScannerState {
  activePosition: number
  isHolding: boolean
  holdProgress: number
  holdTotal: number
  movementProgress: number
  movementTotal: number
  isMovingForward: boolean
}

function getScannerState(
  frameIndex: number,
  totalChars: number,
  options: Pick<AdvancedGradientOptions, "direction" | "holdFrames">,
): ScannerState {
  const { direction = "forward", holdFrames = {} } = options

  if (direction === "bidirectional") {
    const forwardFrames = totalChars
    const holdEndFrames = holdFrames.end ?? 0
    const backwardFrames = totalChars - 1

    if (frameIndex < forwardFrames) {
      // Moving forward
      return {
        activePosition: frameIndex,
        isHolding: false,
        holdProgress: 0,
        holdTotal: 0,
        movementProgress: frameIndex,
        movementTotal: forwardFrames,
        isMovingForward: true,
      }
    } else if (frameIndex < forwardFrames + holdEndFrames) {
      // Holding at end
      return {
        activePosition: totalChars - 1,
        isHolding: true,
        holdProgress: frameIndex - forwardFrames,
        holdTotal: holdEndFrames,
        movementProgress: 0,
        movementTotal: 0,
        isMovingForward: true,
      }
    } else if (frameIndex < forwardFrames + holdEndFrames + backwardFrames) {
      // Moving backward
      const backwardIndex = frameIndex - forwardFrames - holdEndFrames
      return {
        activePosition: totalChars - 2 - backwardIndex,
        isHolding: false,
        holdProgress: 0,
        holdTotal: 0,
        movementProgress: backwardIndex,
        movementTotal: backwardFrames,
        isMovingForward: false,
      }
    } else {
      // Holding at start
      return {
        activePosition: 0,
        isHolding: true,
        holdProgress: frameIndex - forwardFrames - holdEndFrames - backwardFrames,
        holdTotal: holdFrames.start ?? 0,
        movementProgress: 0,
        movementTotal: 0,
        isMovingForward: false,
      }
    }
  } else if (direction === "backward") {
    return {
      activePosition: totalChars - 1 - (frameIndex % totalChars),
      isHolding: false,
      holdProgress: 0,
      holdTotal: 0,
      movementProgress: frameIndex % totalChars,
      movementTotal: totalChars,
      isMovingForward: false,
    }
  } else {
    return {
      activePosition: frameIndex % totalChars,
      isHolding: false,
      holdProgress: 0,
      holdTotal: 0,
      movementProgress: frameIndex % totalChars,
      movementTotal: totalChars,
      isMovingForward: true,
    }
  }
}

function calculateColorIndex(
  frameIndex: number,
  charIndex: number,
  totalChars: number,
  options: Pick<AdvancedGradientOptions, "direction" | "holdFrames" | "trailLength">,
  state?: ScannerState,
): number {
  const { trailLength } = options
  const { activePosition, isHolding, holdProgress, isMovingForward } =
    state ?? getScannerState(frameIndex, totalChars, options)

  // Calculate directional distance (positive means trailing behind)
  const directionalDistance = isMovingForward
    ? activePosition - charIndex // For forward: trail is to the left (lower indices)
    : charIndex - activePosition // For backward: trail is to the right (higher indices)

  // Handle hold frame fading: keep the lead bright, fade the trail
  if (isHolding) {
    // Shift the color index by how long we've been holding
    return directionalDistance + holdProgress
  }

  // Normal movement - show gradient trail only behind the movement direction
  if (directionalDistance > 0 && directionalDistance < trailLength) {
    return directionalDistance
  }

  // At the active position, show the brightest color
  if (directionalDistance === 0) {
    return 0
  }

  return -1
}

function createKnightRiderTrail(options: AdvancedGradientOptions): ColorGenerator {
  const { colors, defaultColor, enableFading = true, minAlpha = 0 } = options

  // Use the provided defaultColor if it's an RGBA instance, otherwise convert/default
  // We use RGBA.fromHex for the fallback to ensure we have an RGBA object.
  // Note: If defaultColor is a string, we convert it once here.
  const defaultRgba = defaultColor instanceof RGBA ? defaultColor : RGBA.fromHex((defaultColor as string) || "#000000")

  // Store the base alpha from the inactive factor
  const baseInactiveAlpha = defaultRgba.a

  let cachedFrameIndex = -1
  let cachedState: ScannerState | null = null

  return (frameIndex: number, charIndex: number, _totalFrames: number, totalChars: number) => {
    if (frameIndex !== cachedFrameIndex) {
      cachedFrameIndex = frameIndex
      cachedState = getScannerState(frameIndex, totalChars, options)
    }

    const state = cachedState!

    const index = calculateColorIndex(frameIndex, charIndex, totalChars, options, state)

    // Calculate global fade for inactive dots during hold or movement
    const { isHolding, holdProgress, holdTotal, movementProgress, movementTotal } = state

    let fadeFactor = 1.0
    if (enableFading) {
      if (isHolding && holdTotal > 0) {
        // Fade out linearly to minAlpha
        const progress = Math.min(holdProgress / holdTotal, 1)
        fadeFactor = Math.max(minAlpha, 1 - progress * (1 - minAlpha))
      } else if (!isHolding && movementTotal > 0) {
        // Fade in linearly from minAlpha during movement
        const progress = Math.min(movementProgress / Math.max(1, movementTotal - 1), 1)
        fadeFactor = minAlpha + progress * (1 - minAlpha)
      }
    }

    // Combine base inactive alpha with the fade factor
    // This ensures inactiveFactor is respected while still allowing fading animation
    defaultRgba.a = baseInactiveAlpha * fadeFactor

    if (index === -1) {
      return defaultRgba
    }

    return colors[index] ?? defaultRgba
  }
}

/**
 * Derives a gradient of tail colors from a single bright color using alpha falloff
 * @param brightColor The brightest color (center/head of the scanner)
 * @param steps Number of gradient steps (default: 6)
 * @returns Array of RGBA colors with alpha-based trail fade (background-independent)
 */
export function deriveTrailColors(brightColor: ColorInput, steps: number = 6): RGBA[] {
  const baseRgba = brightColor instanceof RGBA ? brightColor : RGBA.fromHex(brightColor as string)

  const colors: RGBA[] = []

  for (let i = 0; i < steps; i++) {
    // Alpha-based falloff with optional bloom effect
    let alpha: number
    let brightnessFactor: number

    if (i === 0) {
      // Lead position: full brightness and opacity
      alpha = 1.0
      brightnessFactor = 1.0
    } else if (i === 1) {
      // Slight bloom/glare effect: brighten color but reduce opacity slightly
      alpha = 0.9
      brightnessFactor = 1.15
    } else {
      // Exponential alpha decay for natural-looking trail fade
      alpha = Math.pow(0.65, i - 1)
      brightnessFactor = 1.0
    }

    const r = Math.min(1.0, baseRgba.r * brightnessFactor)
    const g = Math.min(1.0, baseRgba.g * brightnessFactor)
    const b = Math.min(1.0, baseRgba.b * brightnessFactor)

    colors.push(RGBA.fromValues(r, g, b, alpha))
  }

  return colors
}

/**
 * Derives the inactive/default color from a bright color using alpha
 * @param brightColor The brightest color (center/head of the scanner)
 * @param factor Alpha factor for inactive color (default: 0.2, range: 0-1)
 * @returns The same color with reduced alpha for background-independent dimming
 */
export function deriveInactiveColor(brightColor: ColorInput, factor: number = 0.2): RGBA {
  const baseRgba = brightColor instanceof RGBA ? brightColor : RGBA.fromHex(brightColor as string)

  // Use the full color brightness but adjust alpha for background-independent dimming
  return RGBA.fromValues(baseRgba.r, baseRgba.g, baseRgba.b, factor)
}

export type KnightRiderStyle = "blocks" | "diamonds"

export interface KnightRiderOptions {
  width?: number
  style?: KnightRiderStyle
  holdStart?: number
  holdEnd?: number
  colors?: ColorInput[]
  /** Single color to derive trail from (alternative to providing colors array) */
  color?: ColorInput
  /** Number of trail steps when using single color (default: 6) */
  trailSteps?: number
  defaultColor?: ColorInput
  /** Alpha factor for inactive color when using single color (default: 0.2, range: 0-1) */
  inactiveFactor?: number
  /** Enable fading of inactive dots during hold and movement (default: true) */
  enableFading?: boolean
  /** Minimum alpha value when fading (default: 0, range: 0-1) */
  minAlpha?: number
}

/**
 * Creates frame strings for a Knight Rider style scanner animation
 * @param options Configuration options for the Knight Rider effect
 * @returns Array of frame strings
 */
export function createFrames(options: KnightRiderOptions = {}): string[] {
  const width = options.width ?? 8
  const style = options.style ?? "diamonds"
  const holdStart = options.holdStart ?? 30
  const holdEnd = options.holdEnd ?? 9

  const colors =
    options.colors ??
    (options.color
      ? deriveTrailColors(options.color, options.trailSteps)
      : [
          RGBA.fromHex("#ff0000"), // Brightest Red (Center)
          RGBA.fromHex("#ff5555"), // Glare/Bloom
          RGBA.fromHex("#dd0000"), // Trail 1
          RGBA.fromHex("#aa0000"), // Trail 2
          RGBA.fromHex("#770000"), // Trail 3
          RGBA.fromHex("#440000"), // Trail 4
        ])

  const defaultColor =
    options.defaultColor ??
    (options.color ? deriveInactiveColor(options.color, options.inactiveFactor) : RGBA.fromHex("#330000"))

  const trailOptions = {
    colors,
    trailLength: colors.length,
    defaultColor,
    direction: "bidirectional" as const,
    holdFrames: { start: holdStart, end: holdEnd },
    enableFading: options.enableFading,
    minAlpha: options.minAlpha,
  }

  // Bidirectional cycle: Forward (width) + Hold End + Backward (width-1) + Hold Start
  const totalFrames = width + holdEnd + (width - 1) + holdStart

  // Generate dynamic frames where inactive pixels are dots and active ones are blocks
  const frames = Array.from({ length: totalFrames }, (_, frameIndex) => {
    return Array.from({ length: width }, (_, charIndex) => {
      const index = calculateColorIndex(frameIndex, charIndex, width, trailOptions)

      if (style === "diamonds") {
        const shapes = ["⬥", "◆", "⬩", "⬪"]
        if (index >= 0 && index < trailOptions.colors.length) {
          return shapes[Math.min(index, shapes.length - 1)]
        }
        return "·"
      }

      // Default to blocks
      // It's active if we have a valid color index that is within our colors array
      const isActive = index >= 0 && index < trailOptions.colors.length
      return isActive ? "■" : "⬝"
    }).join("")
  })

  return frames
}

/**
 * Creates a color generator function for Knight Rider style scanner animation
 * @param options Configuration options for the Knight Rider effect
 * @returns ColorGenerator function
 */
export function createColors(options: KnightRiderOptions = {}): ColorGenerator {
  const holdStart = options.holdStart ?? 30
  const holdEnd = options.holdEnd ?? 9

  const colors =
    options.colors ??
    (options.color
      ? deriveTrailColors(options.color, options.trailSteps)
      : [
          RGBA.fromHex("#ff0000"), // Brightest Red (Center)
          RGBA.fromHex("#ff5555"), // Glare/Bloom
          RGBA.fromHex("#dd0000"), // Trail 1
          RGBA.fromHex("#aa0000"), // Trail 2
          RGBA.fromHex("#770000"), // Trail 3
          RGBA.fromHex("#440000"), // Trail 4
        ])

  const defaultColor =
    options.defaultColor ??
    (options.color ? deriveInactiveColor(options.color, options.inactiveFactor) : RGBA.fromHex("#330000"))

  const trailOptions = {
    colors,
    trailLength: colors.length,
    defaultColor,
    direction: "bidirectional" as const,
    holdFrames: { start: holdStart, end: holdEnd },
    enableFading: options.enableFading,
    minAlpha: options.minAlpha,
  }

  return createKnightRiderTrail(trailOptions)
}

import { createContext, createSignal, onCleanup, useContext, type ParentProps, Show } from "solid-js"
import { createStore } from "solid-js/store"
import { useTheme } from "../context/theme"
import { useRenderer, useTerminalDimensions } from "@opentui/solid"
import { SplitBorder } from "./border"
import { TextAttributes } from "@opentui/core"
import { errorMessage } from "../util/error"
export type ToastOptions = {
  title?: string
  message: string
  variant: "info" | "success" | "warning" | "error"
  duration: number
  action?: {
    label: string
    run: () => void
  }
}
type ToastInput = Omit<ToastOptions, "duration"> & { duration?: number }

function ToastSurface(props: {
  toast: ToastOptions
  pending?: number
  onHover?: (hovered: boolean) => void
  onActivate: () => void
}) {
  const theme = useTheme()
  const dimensions = useTerminalDimensions()
  const renderer = useRenderer()
  const [hovered, setHovered] = createSignal(false)
  const hover = (value: boolean) => {
    setHovered(value)
    props.onHover?.(value)
  }
  const affordance = () => (
    <text
      flexShrink={0}
      marginLeft={2}
      wrapMode="none"
      attributes={hovered() && props.toast.action ? TextAttributes.BOLD : undefined}
      fg={hovered() ? theme.text.action.primary.base : theme.text.muted}
    >
      {props.toast.action ? `› ${props.toast.action.label}` : "x"}
    </text>
  )

  return (
    <box
      position="absolute"
      top={1}
      right={2}
      maxWidth={Math.min(60, dimensions().width - 6)}
      justifyContent="center"
      alignItems="flex-start"
      borderColor={theme.text.feedback[props.toast.variant].base}
      border={["left", "right"]}
      customBorderChars={SplitBorder.customBorderChars}
      onMouseOver={() => hover(true)}
      onMouseOut={() => hover(false)}
      onMouseUp={() => {
        if (renderer.getSelection()?.getSelectedText()) return
        props.onActivate()
      }}
    >
      <box
        width="100%"
        paddingLeft={2}
        paddingRight={2}
        paddingTop={1}
        paddingBottom={1}
        backgroundColor={theme.background.raised.high}
      >
        <Show
          when={props.toast.title}
          fallback={
            <box flexDirection="row" width="100%">
              <text fg={theme.text.base} wrapMode="word" flexGrow={1}>
                {props.toast.message}
              </text>
              {affordance()}
            </box>
          }
        >
          <box flexDirection="row" width="100%" marginBottom={1}>
            <text attributes={TextAttributes.BOLD} fg={theme.text.base}>
              {props.toast.title}
            </text>
            <box flexGrow={1} />
            {affordance()}
          </box>
          <text fg={theme.text.base} wrapMode="word" width="100%">
            {props.toast.message}
          </text>
        </Show>
        <Show when={props.pending}>
          <text fg={theme.text.muted} marginTop={1}>
            +{props.pending} more
          </text>
        </Show>
      </box>
    </box>
  )
}

export function Toast() {
  const toast = useToast()

  return (
    <Show when={toast.currentToast}>
      {(current) => (
        <ToastSurface
          toast={current()}
          pending={toast.pending}
          onHover={(hovered) => (hovered ? toast.pause() : toast.resume())}
          onActivate={toast.activate}
        />
      )}
    </Show>
  )
}

function init() {
  const [store, setStore] = createStore({
    currentToast: null as ToastOptions | null,
    queue: [] as ToastOptions[],
  })

  let timeoutHandle: NodeJS.Timeout | null = null
  let startedAt = 0
  let remaining = 0
  let paused = false

  const clear = () => {
    if (!timeoutHandle) return
    clearTimeout(timeoutHandle)
    timeoutHandle = null
  }

  const start = (duration: number) => {
    clear()
    remaining = duration
    startedAt = Date.now()
    timeoutHandle = setTimeout(() => dismiss(), duration).unref()
  }

  const dismiss = () => {
    clear()
    const next = store.queue[0]
    setStore("queue", (queue) => queue.slice(1))
    setStore("currentToast", next ?? null)
    if (!next) {
      paused = false
      return
    }
    remaining = next.duration
    if (!paused) start(next.duration)
  }

  const toast = {
    show(options: ToastInput) {
      const toastOptions = { ...options, duration: options.duration ?? 5000 }
      if (store.currentToast && (paused || store.queue.length > 0)) {
        setStore("queue", (queue) => [...queue, toastOptions])
        return
      }
      setStore("currentToast", toastOptions)
      start(toastOptions.duration)
    },
    error: (err: unknown) => {
      toast.show({ variant: "error", message: errorMessage(err) })
    },
    pause() {
      if (!store.currentToast || paused) return
      paused = true
      remaining = Math.max(0, remaining - (Date.now() - startedAt))
      clear()
    },
    resume() {
      if (!store.currentToast || !paused) return
      paused = false
      start(remaining)
    },
    dismiss,
    activate() {
      const action = store.currentToast?.action
      dismiss()
      action?.run()
    },
    get currentToast(): ToastOptions | null {
      return store.currentToast
    },
    get pending() {
      return store.queue.length
    },
  }
  onCleanup(clear)
  return toast
}

export type ToastContext = ReturnType<typeof init>

const ctx = createContext<ToastContext>()

export function ToastProvider(props: ParentProps) {
  const value = init()
  return <ctx.Provider value={value}>{props.children}</ctx.Provider>
}

export function useToast() {
  const value = useContext(ctx)
  if (!value) {
    throw new Error("useToast must be used within a ToastProvider")
  }
  return value
}

import { createSignal } from "solid-js"
import { openPath } from "@opencode/util/open"
import { useRenderer } from "@opentui/solid"
import { useClipboard } from "../context/clipboard"
import { useDialog } from "./dialog"
import { DialogSelect } from "./dialog-select"
import { useToast } from "./toast"

export function useWorkingDirectoryActions(input: { directory: () => string | undefined; onMove?: () => void }) {
  const clipboard = useClipboard()
  const dialog = useDialog()
  const renderer = useRenderer()
  const toast = useToast()
  const [hovered, setHovered] = createSignal(false)

  function openMenu() {
    if (renderer.getSelection()?.getSelectedText()) return
    const directory = input.directory()
    if (!directory) return
    dialog.replace(() => (
      <DialogSelect
        title="Working directory"
        renderFilter={false}
        options={[
          {
            title: "Copy path",
            value: "location.copy",
            description: directory,
            onSelect: (dialog) => {
              void clipboard.write(directory).then(() => {
                dialog.clear()
                toast.show({ message: "Path copied to clipboard", variant: "info" })
              }, toast.error)
            },
          },
          {
            title: "Open folder",
            value: "location.open",
            description: "in system file manager",
            onSelect: (dialog) => {
              dialog.clear()
              void openPath(directory).catch(toast.error)
            },
          },
          ...(input.onMove
            ? [
                {
                  title: "Workspaces",
                  value: "session.move",
                  description: "to another working directory",
                  onSelect: () => void input.onMove?.(),
                },
              ]
            : []),
        ]}
      />
    ))
  }

  return {
    hovered,
    onMouseOver: () => setHovered(true),
    onMouseOut: () => setHovered(false),
    onMouseUp: openMenu,
  }
}

import { Locale } from "./locale"
import { stringWidth } from "./string-width"

export function collapseToolOutput(output: string, maxLines: number, maxChars: number) {
  const lines = output.split("\n")
  if (lines.length <= maxLines && Array.from(output).length <= maxChars) {
    return { output, overflow: false }
  }

  const visible = lines.slice(0, maxLines)
  if (lines.length > maxLines && visible.length > 0) visible[visible.length - 1] += "…"
  const preview = visible.join("\n")
  if (Array.from(preview).length > maxChars) {
    return {
      output:
        Array.from(preview)
          .slice(0, Math.max(0, maxChars - 1))
          .join("") + "…",
      overflow: true,
    }
  }

  return { output: preview, overflow: true }
}

export function collapseShellOutput(input: string, output: string, maxLines: number, maxChars: number) {
  if (!input) {
    const collapsed = collapseToolOutput(output, maxLines, maxChars)
    return {
      input,
      output: collapsed.overflow ? collapseTail(output, maxLines, maxChars) : output,
      overflow: collapsed.overflow,
    }
  }

  const commandLines = Math.min(2, maxLines)
  const lineChars = Math.max(1, Math.floor(maxChars / Math.max(1, maxLines)))
  const command = collapseShellCommand(input, commandLines, lineChars)
  if (!output) return { input: command.output, output, overflow: command.overflow }

  const lines = Math.max(1, maxLines - command.lines - 1)
  const chars = Math.max(1, maxChars - Array.from(command.output).length - 2)
  const collapsed = collapseToolOutput(output, lines, chars)
  return {
    input: command.output,
    output: collapsed.overflow ? collapseTail(output, lines, chars) : output,
    overflow: command.overflow || collapsed.overflow,
  }
}

function collapseShellCommand(input: string, maxLines: number, lineWidth: number) {
  const visible: string[] = []
  let lines = 1
  let width = 0
  const overflow = Locale.graphemes(input).some((segment) => {
    if (segment === "\n") {
      if (lines >= maxLines) return true
      visible.push(segment)
      lines++
      width = 0
      return false
    }

    const next = stringWidth(segment)
    if (width + next > lineWidth) {
      if (lines >= maxLines) return true
      lines++
      width = 0
    }
    visible.push(segment)
    width += next
    return false
  })
  if (!overflow) return { output: input, overflow, lines }

  if (width >= lineWidth) {
    const removed = visible.pop()
    if (removed !== undefined && removed !== "\n") width -= stringWidth(removed)
  }
  return { output: visible.join("") + "…", overflow, lines }
}

function collapseTail(output: string, maxLines: number, maxChars: number) {
  const lines = output.split("\n")
  if (lines.length <= maxLines && Array.from(output).length <= maxChars) return output

  const count = Math.max(1, lines.length - Math.max(0, maxLines - 1))
  const label = `(${count} earlier ${count === 1 ? "line" : "lines"})`
  if (maxLines <= 1) return label

  const preview = Array.from(lines.slice(-(maxLines - 1)).join("\n"))
  const available = maxChars - Array.from(label).length - 1
  if (available <= 0) return label
  return `${label}\n${preview.slice(-available).join("")}`
}

import path from "node:path"
import { stat } from "node:fs/promises"

export function configDirectories(config: string, cwd: string) {
  return [...new Set([config, ...ancestors(cwd).map((directory) => path.join(directory, ".opencode"))])]
}

export function projectConfigDirectories(project: string, cwd: string) {
  const directories = ancestors(cwd)
  return directories
    .slice(directories.indexOf(path.resolve(project)))
    .map((directory) => path.join(directory, ".opencode"))
}

export async function localProjectDirectory(cwd: string) {
  const directories = ancestors(cwd)
  const repositories = await Promise.all(
    directories.map((directory) =>
      Promise.all(
        [".git", ".hg"].map((name) =>
          stat(path.join(directory, name)).then(
            () => true,
            (error) => (isMissingPath(error) ? false : Promise.reject(error)),
          ),
        ),
      ).then((matches) => matches.some(Boolean)),
    ),
  )
  return directories.findLast((_, index) => repositories[index]) ?? path.resolve(cwd)
}

export function isMissingPath(error: unknown) {
  if (!error || typeof error !== "object") return false
  const code = "code" in error ? error.code : undefined
  return code === "ENOENT" || code === "ENOTDIR"
}

function ancestors(cwd: string) {
  const directories: string[] = []
  for (let current = path.resolve(cwd); ; current = path.dirname(current)) {
    directories.push(current)
    if (path.dirname(current) === current) break
  }
  return directories.reverse()
}

import type { IntegrationInfo } from "@opencode/client"

export function hasConnectedProvider(integrations: readonly Pick<IntegrationInfo, "connections">[]) {
  return integrations.some((integration) => integration.connections.length > 0)
}

import { createEffect, createMemo, createSignal, onCleanup, type Accessor } from "solid-js"

export function createDelayedPresence<T>(
  source: Accessor<T | undefined>,
  delay: number | ((value: T) => number),
  equals?: (previous: T, next: T) => boolean,
) {
  const [visible, setVisible] = createSignal(false)
  const value = equals
    ? createMemo(source, undefined, {
        equals: (previous, next) => {
          if (previous === undefined || next === undefined) return previous === next
          return equals(previous, next)
        },
      })
    : source

  createEffect(() => {
    const current = value()
    setVisible(false)
    if (current === undefined) return

    const remaining = typeof delay === "function" ? delay(current) : delay
    if (remaining <= 0) {
      setVisible(true)
      return
    }

    const timer = setTimeout(() => setVisible(true), remaining)
    onCleanup(() => clearTimeout(timer))
  })

  return visible
}

export interface PatchHunk {
  readonly patch: string
  readonly header?: string
  readonly rows?: number
}

export interface AddedPatchChunk {
  readonly patch: string
  readonly lines: readonly string[]
  readonly rows: number
}

/**
 * Splits a new-file patch into chunks of `size` lines, each a valid patch with its own `@@ -0,0 +start,count @@`
 * header. Returns undefined for anything else: patches with context or removed lines would need old and new line
 * numbers recomputed at every cut, so they are not split.
 */
export function splitAddedPatch(patch: string, size: number): AddedPatchChunk[] | undefined {
  const header = /^@@ -0,0 \+1,(\d+) @@[^\n]*\n/m.exec(patch)
  if (!header) return
  const count = Number(header[1])
  const lines = patch
    .slice(header.index + header[0].length)
    .replace(/\n$/, "")
    .split("\n")
  const marker = lines.at(-1)?.startsWith("\\ No newline at end of file") ? lines.pop() : undefined
  if (lines.length !== count || lines.some((line) => !line.startsWith("+"))) return
  const prefix = patch.slice(0, header.index)
  return Array.from({ length: Math.ceil(count / size) }, (_, index) => {
    const start = index * size
    const slice = lines.slice(start, start + size)
    return {
      patch: `${prefix}@@ -0,0 +${start + 1},${slice.length} @@\n${slice.join("\n")}${marker && start + size >= count ? `\n${marker}` : ""}`,
      lines: slice,
      rows: slice.length,
    }
  })
}

export function splitPatchHunks(patch: string): PatchHunk[] {
  const starts = [...patch.matchAll(/^@@ -\d+(?:,\d+)? \+\d+(?:,\d+)? @@.*$/gm)].map((match) => match.index)
  if (starts.length <= 1) return [{ patch }]

  const prefix = patch.slice(0, starts[0])
  return starts.map((start, index) => {
    const end = starts[index + 1] ?? patch.length
    const lineEnd = patch.indexOf("\n", start)
    return {
      header: patch.slice(start, lineEnd === -1 ? end : lineEnd),
      patch: prefix + patch.slice(start, end),
      rows: splitRows(patch.slice(start, end)),
    }
  })
}

function splitRows(hunk: string) {
  const lines = hunk.replace(/\n$/, "").split("\n").slice(1)
  let rows = 0
  let index = 0

  while (index < lines.length) {
    const prefix = lines[index][0]
    if (prefix === " " || !prefix) {
      rows++
      index++
      continue
    }
    if (prefix === "\\") {
      index++
      continue
    }

    let additions = 0
    let deletions = 0
    while (index < lines.length && (lines[index][0] === "+" || lines[index][0] === "-")) {
      if (lines[index][0] === "+") additions++
      if (lines[index][0] === "-") deletions++
      index++
    }
    rows += Math.max(additions, deletions)
  }

  return rows
}

export function errorDetails(input: { title: string; error: string; context?: string; diagnosticRef?: string }) {
  const text = [
    input.title,
    ...(input.context ? [input.context] : []),
    `Error: ${input.error}`,
    ...(input.diagnosticRef ? [`Reference: ${input.diagnosticRef}`] : []),
  ].join("\n")
  return {
    text,
    prompt: [
      "Investigate why this OpenCode component failed in the current project.",
      text,
      ...(input.diagnosticRef
        ? [
            `Find the server log entry matching reference ${input.diagnosticRef} and inspect its original cause. If the server logs are not accessible from this session, say so and ask for the matching log entry; do not infer the cause from the reference alone.`,
          ]
        : []),
      "Inspect the relevant project and global OpenCode configuration, startup or loading behavior, required environment variables or credentials, dependencies, and logs. Identify the root cause and recommend a fix. Do not expose credentials.",
    ].join("\n\n"),
  }
}

import { isRecord } from "./record"

type ConfigIssue = { message: string; path: string[] }

export function cliErrorMessage(input: unknown): string | undefined {
  if (input instanceof Error && isRecord(input.cause) && "body" in input.cause) {
    const formatted = cliErrorMessage(input.cause.body)
    if (formatted) return formatted
  }

  if (tagged(input, "CliError")) {
    if (typeof input.exitCode === "number") process.exitCode = input.exitCode
    return field(input, "message") ?? ""
  }
  if (tagged(input, "AccountServiceError") || tagged(input, "AccountTransportError")) {
    return field(input, "message") ?? ""
  }

  const model = configData(input, "ProviderModelNotFoundError")
  if (model) {
    const suggestions = Array.isArray(model.suggestions)
      ? model.suggestions.filter((item): item is string => typeof item === "string")
      : []
    return [
      `Model not found: ${field(model, "providerID")}/${field(model, "modelID")}`,
      ...(suggestions.length ? ["Did you mean: " + suggestions.join(", ")] : []),
      "Try: `opencode models` to list available models",
      "Or check your config (opencode.json) provider/model names",
    ].join("\n")
  }

  const provider = configData(input, "ProviderInitError")
  if (provider)
    return `Failed to initialize provider "${field(provider, "providerID")}". Check credentials and configuration.`

  const json = configData(input, "ConfigJsonError")
  if (json) {
    const message = field(json, "message")
    return `Config file at ${field(json, "path")} is not valid JSON(C)` + (message ? `: ${message}` : "")
  }

  const directory = configData(input, "ConfigDirectoryTypoError")
  if (directory) {
    return `Directory "${field(directory, "dir")}" in ${field(directory, "path")} is not valid. Rename the directory to "${field(directory, "suggestion")}" or remove it. This is a common typo.`
  }

  const frontmatter = configData(input, "ConfigFrontmatterError")
  if (frontmatter) return field(frontmatter, "message") ?? ""

  const invalid = configData(input, "ConfigInvalidError")
  if (invalid) {
    const path = field(invalid, "path")
    const message = field(invalid, "message")
    const issues = Array.isArray(invalid.issues)
      ? invalid.issues.filter((issue): issue is ConfigIssue => {
          return (
            isRecord(issue) &&
            typeof issue.message === "string" &&
            Array.isArray(issue.path) &&
            issue.path.every((item) => typeof item === "string")
          )
        })
      : []
    return [
      `Configuration is invalid${path && path !== "config" ? ` at ${path}` : ""}` + (message ? `: ${message}` : ""),
      ...issues.map((issue) => "↳ " + issue.message + " " + issue.path.join(".")),
    ].join("\n")
  }

  if (tagged(input, "UICancelledError") || named(input, "UICancelledError")) return ""
  return undefined
}

function tagged(input: unknown, tag: string): input is Record<string, unknown> {
  return isRecord(input) && input._tag === tag
}

function named(input: unknown, name: string) {
  return isRecord(input) && (input.name === name || input._tag === name)
}

function configData(input: unknown, tag: string) {
  if (!isRecord(input)) return undefined
  if (input.name === tag && isRecord(input.data)) return input.data
  if (input._tag === tag) return input
  return undefined
}

function field(input: Record<string, unknown>, key: string) {
  return typeof input[key] === "string" ? input[key] : undefined
}

export function errorFormat(error: unknown): string {
  if (error instanceof Error) {
    return error.stack ?? `${error.name}: ${error.message}`
  }

  if (typeof error === "object" && error !== null) {
    try {
      const json = JSON.stringify(error, null, 2)
      // Plain objects whose own properties are all non-enumerable (or empty)
      // serialize to "{}", which prints as a useless bare `{}` on stderr.
      // Fall back to a custom toString first, then to ctor name + own prop names.
      if (json === "{}") {
        const str = String(error)
        if (str && str !== "[object Object]") return str
        const ctor = error.constructor?.name
        const prefix = ctor && ctor !== "Object" ? ctor : "Error"
        const names = Object.getOwnPropertyNames(error)
        return names.length === 0 ? `${prefix} (no message)` : `${prefix} { ${names.join(", ")} }`
      }
      return json
    } catch {
      return "Unexpected error (unserializable)"
    }
  }

  return String(error)
}

export function errorMessage(error: unknown): string {
  if (error instanceof Error) {
    if (error.message) return error.message
    if (error.name) return error.name
  }

  if (isRecord(error) && typeof error.message === "string" && error.message) {
    return error.message
  }

  if (isRecord(error) && isRecord(error.data) && typeof error.data.message === "string" && error.data.message) {
    return error.data.message
  }

  const text = String(error)
  if (text && text !== "[object Object]") return text

  const formatted = errorFormat(error)
  if (formatted) return formatted
  return "unknown error"
}

import type { FormField, FormValue } from "@opencode/client"

export type FormAnswerField = Exclude<FormField, { type: "external" }>

export type FormRow = {
  value: string | boolean
  label: string
  description?: string
}

export function isFormAnswerField(field: FormField): field is FormAnswerField {
  return field.type !== "external"
}

export function formLabel(field: FormField) {
  return field.title ?? (field.type === "external" ? field.url : field.key)
}

export function formInitialValues(fields: ReadonlyArray<FormField>) {
  return {
    answers: Object.fromEntries(
      fields.flatMap((field) =>
        isFormAnswerField(field) && field.default !== undefined ? [[field.key, field.default]] : [],
      ),
    ) as Record<string, FormValue | undefined>,
    custom: Object.fromEntries(
      fields.flatMap((field) => {
        if (field.type !== "string" || !field.options || !field.custom || typeof field.default !== "string") return []
        if (field.options.some((option) => option.value === field.default)) return []
        return [[field.key, field.default]]
      }),
    ) as Record<string, string>,
  }
}

export function formTextual(field: FormField | undefined) {
  if (!field) return false
  return field.type === "number" || field.type === "integer" || (field.type === "string" && !field.options)
}

export function formCustom(field: FormField | undefined) {
  if (!field) return false
  if (field.type === "string" && field.options) return field.custom === true
  return field.type === "multiselect" && field.custom === true
}

export function formRows(field: FormField | undefined): FormRow[] {
  if (!field) return []
  if (field.type === "boolean")
    return [
      { value: true, label: "Yes" },
      { value: false, label: "No" },
    ]
  const options = field.type === "multiselect" ? field.options : field.type === "string" ? field.options : undefined
  if (!options) return []
  return options.map((option) => ({
    value: option.value,
    label: option.label,
    description: option.description,
  }))
}

export function formSelected(field: FormField | undefined, value: FormValue | undefined) {
  if (!field || value === undefined || Array.isArray(value)) return 0
  const rows = formRows(field)
  const index = rows.findIndex((row) => row.value === value)
  if (index !== -1) return index
  if (typeof value === "string" && formCustom(field)) return rows.length
  return 0
}

export function formValidateValue(field: FormAnswerField, value: FormValue | undefined): string | undefined {
  if (value === undefined) return field.required ? "Answer required" : undefined
  if (field.required && (value === "" || (Array.isArray(value) && value.length === 0)))
    return field.type === "multiselect" ? "Select at least one option" : "Answer required"
  if (field.type === "string") {
    if (typeof value !== "string") return "Expected text"
    if (field.minLength !== undefined && value.length < field.minLength)
      return `Must be at least ${field.minLength} characters`
    if (field.maxLength !== undefined && value.length > field.maxLength)
      return `Must be at most ${field.maxLength} characters`
    if (field.pattern !== undefined) {
      try {
        if (!new RegExp(field.pattern).test(value)) return `Must match pattern: ${field.pattern}`
      } catch {
        return `Invalid pattern: ${field.pattern}`
      }
    }
    if (field.format === "email" && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) return "Expected an email address"
    if (field.format === "uri" && !validURL(value)) return "Expected a URL"
    if (field.format === "date" && !validDate(value)) return "Expected a date (YYYY-MM-DD)"
    if (field.format === "date-time" && Number.isNaN(new Date(value).getTime())) return "Expected a date and time"
    if (field.options && !field.custom && !field.options.some((option) => option.value === value))
      return "Select an available option"
    return
  }
  if (field.type === "number" || field.type === "integer") {
    if (typeof value !== "number" || !Number.isFinite(value)) return "Expected a number"
    if (field.type === "integer" && !Number.isInteger(value)) return "Expected an integer"
    if (typeof field.minimum === "number" && value < field.minimum) return `Must be at least ${field.minimum}`
    if (typeof field.maximum === "number" && value > field.maximum) return `Must be at most ${field.maximum}`
    return
  }
  if (field.type === "boolean") return typeof value === "boolean" ? undefined : "Expected yes or no"
  if (!Array.isArray(value)) return "Expected selections"
  if (field.minItems !== undefined && value.length < field.minItems) return `Select at least ${field.minItems}`
  if (field.maxItems !== undefined && value.length > field.maxItems) return `Select at most ${field.maxItems}`
  if (!field.custom && value.some((item) => !field.options.some((option) => option.value === item)))
    return "Select only available options"
}

export function formDisplayValue(field: FormAnswerField, value: FormValue | undefined, emptyMultiselect: string) {
  if (value === undefined) return ""
  const label = (item: string | number | boolean) =>
    formRows(field).find((row) => row.value === item)?.label ?? String(item)
  if (Array.isArray(value)) return value.length === 0 ? emptyMultiselect : value.map(label).join(", ")
  return label(value)
}

export function formToggleMultiselect(value: FormValue | undefined, item: string) {
  const values = Array.isArray(value) ? value : []
  const index = values.indexOf(item)
  return index === -1 ? [...values, item] : values.toSpliced(index, 1)
}

export function formSetMultiselectCustom(value: FormValue | undefined, previous: string | undefined, next: string) {
  const values = Array.isArray(value) ? value : []
  const index = previous ? values.indexOf(previous) : -1
  const current = index === -1 ? [...values] : values.toSpliced(index, 1)
  return next && !current.includes(next) ? [...current, next] : current
}

function validURL(value: string) {
  try {
    new URL(value)
    return true
  } catch {
    return false
  }
}

function validDate(value: string) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false
  const date = new Date(`${value}T00:00:00.000Z`)
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === value
}

import type { Storage } from "../context/storage"

export type HighlightsInput = {
  readonly version: string
  /** Number of highlights embedded in this build. */
  readonly count: number
  /** Whether this user has used the TUI before, so a first run with no state is still an update. */
  readonly history: boolean
}

type State = { seen?: string }

/**
 * Decides what to do with the current release's highlights: `show` opens the dialog and records the version,
 * `record` marks a version seen silently, and `none` leaves the state untouched. Only stable versions count.
 */
export function decide(input: HighlightsInput & { readonly seen?: string }) {
  const current = stable(input.version)
  if (!current) return "none"
  const seen = input.seen === undefined ? undefined : stable(input.seen)
  if (!seen && !input.history) return "record"
  if (seen && !newer(current, seen)) return "none"
  return input.count > 0 ? "show" : "record"
}

/**
 * Applies the decision inside the locked storage update, so only one of several TUIs starting together shows the
 * dialog. Resolves to whether this TUI should show it.
 */
export async function claim(storage: Storage, input: HighlightsInput) {
  const [state, update] = storage.store<State>("highlights", { initial: {} })
  if (decide({ ...input, seen: state.seen }) === "none") return false
  const result = { action: "none" as ReturnType<typeof decide> }
  await update((draft) => {
    result.action = decide({ ...input, seen: draft.seen })
    if (result.action !== "none") draft.seen = input.version
  })
  return result.action === "show"
}

function stable(version: string) {
  return version
    .match(/^(\d+)\.(\d+)\.(\d+)$/)
    ?.slice(1)
    .map(Number)
}

function newer(current: number[], seen: number[]) {
  const index = current.findIndex((part, index) => part !== seen[index])
  return index !== -1 && current[index] > seen[index]
}

import { stringWidth } from "./string-width"

export function titlecase(str: string) {
  return str.replace(/\b\w/g, (c) => c.toUpperCase())
}

export function time(input: number): string {
  const date = new Date(input)
  return date.toLocaleTimeString(undefined, { timeStyle: "short" })
}

export function datetime(input: number): string {
  const date = new Date(input)
  const localTime = time(input)
  const localDate = date.toLocaleDateString()
  return `${localTime} · ${localDate}`
}

export function number(num: number): string {
  // 999950+ would round to "1000.0K"
  if (num >= 999950) {
    return (num / 1000000).toFixed(1) + "M"
  } else if (num >= 1000) {
    return (num / 1000).toFixed(1) + "K"
  }
  return num.toString()
}

export function duration(input: number) {
  if (input < 1000) {
    return `${input}ms`
  }
  if (input < 60000) {
    return `${(input / 1000).toFixed(1)}s`
  }
  if (input < 3600000) {
    const minutes = Math.floor(input / 60000)
    const seconds = Math.floor((input % 60000) / 1000)
    return `${minutes}m ${seconds}s`
  }
  if (input < 86400000) {
    const hours = Math.floor(input / 3600000)
    const minutes = Math.floor((input % 3600000) / 60000)
    return `${hours}h ${minutes}m`
  }
  const days = Math.floor(input / 86400000)
  const hours = Math.floor((input % 86400000) / 3600000)
  return `${days}d ${hours}h`
}

export function truncate(str: string, len: number): string {
  if (str.length <= len) return str
  return str.slice(0, len - 1) + "…"
}

const graphemeSegmenter = new Intl.Segmenter(undefined, { granularity: "grapheme" })

export function graphemes(str: string) {
  return Array.from(graphemeSegmenter.segment(str), (item) => item.segment)
}

export function takeWidth(str: string, width: number) {
  if (width <= 0) return ""
  if (stringWidth(str) <= width) return str

  const result: string[] = []
  let used = 0
  for (const segment of graphemes(str)) {
    const next = stringWidth(segment)
    if (used + next > width) break
    result.push(segment)
    used += next
  }
  return result.join("")
}

export function truncateWidth(str: string, width: number): string {
  if (width <= 0) return ""
  if (stringWidth(str) <= width) return str
  if (width === 1) return "…"
  return takeWidth(str, width - 1) + "…"
}

export function truncateLeft(str: string, len: number): string {
  if (str.length <= len) return str
  return "…" + str.slice(-(len - 1))
}

export function truncateMiddle(str: string, maxLength: number = 35): string {
  if (str.length <= maxLength) return str

  const ellipsis = "…"
  const keepStart = Math.ceil((maxLength - ellipsis.length) / 2)
  const keepEnd = Math.floor((maxLength - ellipsis.length) / 2)

  return str.slice(0, keepStart) + ellipsis + str.slice(-keepEnd)
}

export * as Locale from "./locale"

import { Locale } from "./locale"
import { stringWidth } from "./string-width"

const GAP = " · "

export type MarqueeTextPart = {
  value: string
  separator: boolean
}

export function marqueeCycleWidth(value: string) {
  return stringWidth(value + GAP)
}

export function marqueeOverflows(value: string, width: number) {
  return stringWidth(value) > width
}

export function marqueeText(value: string, width: number, offset: number) {
  return marqueeTextParts(value, width, offset)
    .map((part) => part.value)
    .join("")
}

export function marqueeTextParts(value: string, width: number, offset: number): MarqueeTextPart[] {
  if (width <= 0) return []
  if (stringWidth(value) <= width || offset <= 0)
    return Locale.graphemes(Locale.takeWidth(value, width)).map((value) => ({ value, separator: false }))

  const loop = [
    ...Locale.graphemes(value).map((value) => ({ value, separator: false })),
    ...Locale.graphemes(GAP).map((value) => ({ value, separator: value === "·" })),
  ]
  const cursor = offset % marqueeCycleWidth(value)
  const parts = [...loop, ...loop]
  const start = parts.reduce(
    (state, part, index) =>
      state.width >= cursor ? state : { index: index + 1, width: state.width + stringWidth(part.value) },
    { index: 0, width: 0 },
  ).index
  const visible = parts.slice(start).reduce(
    (state, part) => {
      if (state.done) return state
      const next = stringWidth(part.value)
      if (state.width + next > width) return { ...state, done: true }
      return { count: state.count + 1, width: state.width + next, done: false }
    },
    { count: 0, width: 0, done: false },
  ).count
  return parts.slice(start, start + visible)
