    await first.flush()
    await wait(
      () => !second.tabs.tabs().some((tab) => tab.sessionID === "shared"),
      2_000,
      "second client to observe close",
    )
    await second.flush()

    const stored = await Bun.file(path.join(temporary.path, "test", "tui", "tabs.json")).json()
