    await second.flush()
    await wait(
      () => first.tabs.tabs().some((tab) => tab.sessionID === "shared"),
      2_000,
      "first client to observe reopen",
    )
  } finally {
    await Promise.allSettled(clients.map((client) => client.destroy()))
  }
})

