import { describe, expect, test } from "bun:test"
import { footerStatuslinePolicy, type FooterStatuslineGroup } from "../../src/mini/footer.width"
import { stringWidth } from "../../src/util/string-width"

const screenshot = {
  work: [],
  model: { name: "GPT-5.6 Sol (50% Off)", variant: "max" },
  agent: "Build",
  context: { compact: "1% ctx", full: "14.1K (1%)" },
  cost: "$0.04",
  provider: "Anomaly / OpenCode",
  menu: { key: "ctrl+p", label: "menu" },
} satisfies Omit<Parameters<typeof footerStatuslinePolicy>[0], "width">

describe("run footer width", () => {
  test.each([false, true])("progressive layouts fit and preserve information at every width (mono=%s)", (mono) => {
    const fixtures: Array<Omit<Parameters<typeof footerStatuslinePolicy>[0], "width">> = [
      { work: [] },
      screenshot,
      { ...screenshot, model: { name: "GPT-5", variant: "xhigh" } },
      { ...screenshot, model: { name: "a model name with a very long and informative suffix".repeat(3) } },
      {
        ...screenshot,
        model: { name: "\u6a21\u578b\ud83d\ude80e\u0301\u5f00\u53d1 Model".repeat(3), variant: "\u9ad8\u7ea7" },
      },
      { ...screenshot, model: { name: "GPT-5", variant: "an-unusually-long-but-complete-variant" } },
      { ...screenshot, status: { text: "esc stop", expanded: "esc interrupt" }, spinner: mono ? "*" : "\u25aa" },
      {
        ...screenshot,
        status: { text: "ctrl+shift+alt+i stop", expanded: "ctrl+shift+alt+i interrupt" },
        work: [
          { id: "queued", key: "ctrl+x q", label: "12 queued" },
          { id: "subagents", key: mono ? "down" : "\u2193", label: "2 sub", expanded: "2 subagents" },
          { id: "background", key: "ctrl+b", label: "bg", expanded: "background" },
        ],
      },
      { work: [], status: { text: "Shell" }, escape: { key: "esc", label: "normal" }, context: screenshot.context },
    ]
    for (const fixture of fixtures) {
      let previous: FooterStatuslineGroup["id"][] = []
      for (let width = 0; width <= 280; width++) {
        const layout = footerStatuslinePolicy({ ...fixture, mono, width })
        const ids = layout.groups.map((group) => group.id)
        if (fixture.spinner) {
          expect(ids[0]).toBe("spinner")
          expect(layout.text).toStartWith(`${fixture.spinner} `)
          if (width >= stringWidth(`${fixture.spinner} ${fixture.status!.text}`)) {
            expect(stringWidth(layout.text)).toBeLessThanOrEqual(width)
          }
        }
        if (stringWidth(layout.text) > width) {
          expect(ids.every((id) => id === "spinner" || id === "status" || id === "escape")).toBe(true)
        }
        for (const id of previous) expect(ids).toContain(id)
        expect(new Set(ids).size).toBe(ids.length)
        if (ids.includes("menu")) expect(ids.at(-1)).toBe("menu")
        const identity = layout.groups.find((group) => group.id === "model")
        if (identity && fixture.model?.variant) {
          expect(identity.parts.map((part) => part.text).join("")).toEndWith(` [${fixture.model.variant}]`)
        }
        expect(layout.text).not.toContain("\ufffd")
        previous = ids
      }
    }
  })

  test("identity admission cannot separate the selected variant from its model", () => {
    const input = { work: [], model: { name: "GPT-5", variant: "max" } }
    expect(footerStatuslinePolicy({ ...input, width: 10 }).groups).toEqual([])
    expect(footerStatuslinePolicy({ ...input, width: 11 }).text).toBe("GPT-5 [max]")
  })

  test("allocation priority is separate from placement", () => {
    expect(footerStatuslinePolicy({ ...screenshot, width: 15 }).groups.map((group) => group.id)).toEqual(["model"])
    expect(footerStatuslinePolicy({ ...screenshot, width: 60 }).groups.map((group) => group.id)).toEqual([
      "agent",
      "model",
      "context",
      "cost",
    ])
    const full = footerStatuslinePolicy({ ...screenshot, width: 112 })
    expect(full.text).toBe(
      "Build \u00b7 GPT-5.6 Sol (50% Off) [max] \u00b7 14.1K (1%) \u00b7 Anomaly / OpenCode \u00b7 $0.04 \u00b7 ctrl+p menu",
    )
  })

  test("a non-fitting high-priority stage does not backfill with shorter facts", () => {
    const input = {
      ...screenshot,
      work: [{ id: "queued" as const, key: "ctrl+shift+alt+q", label: "12 queued" }],
    }
    expect(footerStatuslinePolicy({ ...input, width: 24 }).groups).toEqual([])
    expect(footerStatuslinePolicy({ ...input, width: 26 }).groups.map((group) => group.id)).toEqual(["queued"])
  })

  test("context and cost are distinct additions", () => {
    const input = { work: [], context: screenshot.context, cost: screenshot.cost }
    expect(footerStatuslinePolicy({ ...input, width: 6 }).text).toBe("1% ctx")
    expect(footerStatuslinePolicy({ ...input, width: 10 }).text).toBe("14.1K (1%)")
    expect(footerStatuslinePolicy({ ...input, width: 18 }).text).toBe("14.1K (1%) \u00b7 $0.04")
  })

  test("stop-label enhancement cannot remove identity at the former 56-column breakpoint", () => {
    const input = { ...screenshot, status: { text: "esc stop", expanded: "esc interrupt" } }
    for (const width of [55, 56, 57, 79, 80, 81]) {
      const layout = footerStatuslinePolicy({ ...input, width })
      expect(layout.text).toContain("GPT-5.6 Sol (50% Off) [max]")
      expect(layout.text).toStartWith("esc stop")
    }
    expect(footerStatuslinePolicy({ ...input, width: 160 }).text).toStartWith("esc interrupt")
  })

  test("required controls use an explicit wrapping fallback without optional groups", () => {
    expect(footerStatuslinePolicy({ ...screenshot, width: 16, status: { text: "ctrl+shift+alt+x exit" } }).text).toBe(
      "ctrl+shift+alt+x exit",
    )
    expect(
      footerStatuslinePolicy({ ...screenshot, width: 80, status: { text: "Please confirm\nExit now?" } }).text,
    ).toBe("Please confirm\nExit now?")
  })
})

import { describe, expect, test } from "bun:test"
import type { FormField, FormInfo } from "@opencode/client/promise"
import {
  createFormBodyState,
  formAcknowledge,
  formAnswer,
  formCommitInput,
  formPick,
  formReply,
  formSetExternalReady,
  formSetField,
  formSetSelected,
  formUnsupported,
  formValidate,
} from "../../src/mini/form.shared"

function request(fields: FormField[]): FormInfo {
  return { id: "frm_1", sessionID: "ses_1", title: "Input", fields: fields as FormInfo["fields"] }
}

describe("Mini form state", () => {
  test("builds every supported answer and preserves owner location", () => {
    const form = request([
      { key: "choice", type: "string", options: [{ value: "fast", label: "Fast" }], default: "fast" },
      { key: "count", type: "number" },
      { key: "whole", type: "integer", default: 2 },
      { key: "enabled", type: "boolean", default: false },
      { key: "tags", type: "multiselect", options: [], custom: true },
      { key: "external", type: "external", url: "https://example.com/action" },
    ])
    let state = formSetField(createFormBodyState(form), form, 1)
    state = formCommitInput(state, form, "1.5")
    state = formSetField(state, form, 4)
    state = formSetSelected(state, 0)
    state = formPick(state, form)
    state = formCommitInput(state, form, "custom")
    state = formSetField(state, form, 5)
    state = formAcknowledge(formSetExternalReady(state, "external"), form)

    const answer = { choice: "fast", count: 1.5, whole: 2, enabled: false, tags: ["custom"], external: true }
    expect(formAnswer(form, state)).toEqual(answer)
    expect(formReply({ ...form, location: { directory: "/tmp", workspaceID: "wrk_1" } }, state)).toEqual({
      sessionID: "ses_1",
      formID: "frm_1",
      answer,
      location: { directory: "/tmp", workspaceID: "wrk_1" },
    })
  })

  test("rejects invalid and deliberately unsupported shapes", () => {
    const invalid = request([
      { key: "required", type: "string", required: true },
      { key: "external", type: "external", url: "https://example.com" },
    ])
    expect(formValidate(invalid, createFormBodyState(invalid))).toContain("Answer required")
    expect(formUnsupported(request([{ key: "value", type: "string", pattern: "^a" }]))).toContain("Pattern")
    expect(
      formUnsupported(
        request([
          { key: "toggle", type: "boolean" },
          { key: "value", type: "string", when: [{ key: "toggle", op: "eq", value: true }] },
        ]),
      ),
    ).toContain("Conditional")
  })
})

import { describe, expect, test } from "bun:test"
import {
  createPermissionBodyState,
  permissionAlwaysLines,
  permissionCancel,
  permissionEscape,
  permissionInfo,
  permissionReject,
  permissionRun,
} from "../../src/mini/permission.shared"
import type { MiniPermissionRequest } from "../../src/mini/types"
import { canonicalToolPart } from "./fixture/tool-part"

function req(input: Partial<MiniPermissionRequest> = {}): MiniPermissionRequest {
  return {
    id: "perm-1",
    sessionID: "session-1",
    action: "read",
    resources: [],
    metadata: {},
    save: [],
    ...input,
  }
}

function body() {
  return createPermissionBodyState(req())
}

describe("run permission shared", () => {
  test("replies immediately for allow once", () => {
    const out = permissionRun(body(), "perm-1", "once")

    expect(out.reply).toEqual({
      sessionID: "session-1",
      requestID: "perm-1",
      decision: "once",
    })
  })

  test("requires confirmation for allow always", () => {
    const next = permissionRun(body(), "perm-1", "always")
    expect(next.state.stage).toBe("always")
    expect(next.state.selected).toBe("confirm")
    expect(next.reply).toBeUndefined()

    expect(permissionRun(next.state, "perm-1", "confirm").reply).toEqual({
      sessionID: "session-1",
      requestID: "perm-1",
      decision: "always",
    })

    expect(permissionRun(next.state, "perm-1", "cancel").state).toMatchObject({
      stage: "permission",
      selected: "always",
    })
  })

  test("builds trimmed reject replies and stage transitions", () => {
    const next = permissionRun(body(), "perm-1", "reject")
    expect(next.state.stage).toBe("reject")

    const out = permissionReject({ ...next.state, message: "  use rg  " }, "perm-1")
    expect(out).toEqual({
      sessionID: "session-1",
      requestID: "perm-1",
      decision: "reject",
      message: "use rg",
    })

    expect(permissionCancel(next.state)).toMatchObject({
      stage: "permission",
      selected: "reject",
    })

    expect(permissionEscape(body())).toMatchObject({
      stage: "reject",
      selected: "reject",
    })

    expect(permissionEscape({ ...next.state, stage: "always", selected: "confirm" })).toMatchObject({
      stage: "permission",
      selected: "always",
    })
  })

  test("maps supported permission types into display info", () => {
    expect(
      permissionInfo(
        req({
          action: "shell",
          source: { type: "tool", messageID: "msg-shell", id: "call-shell" },
          tool: canonicalToolPart(
            "shell",
            {
              status: "running",
              input: { command: "git status --short" },
              metadata: {},
            },
            "call-shell",
          ),
        }),
      ),
    ).toMatchObject({
      title: "Shell command",
      lines: ["$ git status --short"],
    })

    expect(
      permissionInfo(
        req({
          action: "external_directory",
          resources: ["/tmp/work/**/*.ts", "/tmp/work/**/*.tsx"],
        }),
      ),
    ).toMatchObject({
      title: "Access external directory /tmp/work",
      lines: ["- /tmp/work/**/*.ts", "- /tmp/work/**/*.tsx"],
    })

    expect(permissionInfo(req({ action: "doom_loop" }))).toMatchObject({
      title: "Continue after repeated failures",
    })

    expect(permissionInfo(req({ action: "custom_tool" }))).toMatchObject({
      title: "Call tool custom_tool",
      lines: ["Tool: custom_tool"],
    })
  })

  test("prefers canonical request metadata over source tool metadata", () => {
    expect(
      permissionInfo(
        req({
          action: "websearch",
          metadata: { provider: "parallel" },
          source: { type: "tool", messageID: "msg-search", id: "call-search" },
          tool: canonicalToolPart(
            "websearch",
            {
              status: "running",
              input: { query: "current releases" },
              metadata: { provider: "exa", retained: true },
            },
            "call-search",
          ),
        }),
      ),
    ).toMatchObject({
      title: 'Web Search via Parallel "current releases"',
      lines: ["Query: current releases"],
    })
  })

  test("uses source patch text when an edit has no generated diff", () => {
    const patch = '*** Begin Patch\n*** Update File: src/index.ts\n@@\n-old\n+const arrow = "→"\n*** End Patch'
    const request = req({
      action: "edit",
      resources: ["src/index.ts"],
      source: { type: "tool", messageID: "msg-edit", id: "call-edit" },
      tool: canonicalToolPart(
        "edit",
        {
          status: "running",
          input: { patchText: patch },
          metadata: {},
        },
        "call-edit",
      ),
    })
    expect(permissionInfo(request)).toMatchObject({
      title: "Edit src/index.ts",
      diff: undefined,
      patch,
    })
    expect(permissionInfo(request, undefined, true)).toMatchObject({
      title: "Edit src/index.ts",
      lines: [patch],
      diff: undefined,
      patch: undefined,
    })
  })

  test("formats always-allow copy for wildcard and explicit patterns", () => {
    expect(permissionAlwaysLines(req({ action: "bash", save: ["*"] }))).toEqual([
      "This will always allow bash for this project.",
    ])

    expect(permissionAlwaysLines(req({ save: ["src/**/*.ts", "src/**/*.tsx"] }))).toEqual([
      "This will always allow the following patterns for this project.",
      "- src/**/*.ts",
      "- src/**/*.tsx",
    ])
  })
})

