import type { RunPrompt } from "../../src/mini/types"
import { createFooterApiFixture } from "./fixture/footer-api"

function runPromptQueue(input: Omit<QueueInput, "admit" | "settle"> & Partial<Pick<QueueInput, "admit" | "settle">>) {
  return runPromptQueueBase({
    admit: async () => {},
    settle: async () => {},
    ...input,
  })
}

describe("run runtime queue", () => {
  test("ignores empty prompts", async () => {
    const ui = createFooterApiFixture()
    let calls = 0

    const task = runPromptQueue({
      footer: ui.api,
      run: async () => {
        calls += 1
      },
    })

    ui.submit("   ")
    ui.api.close()
    await task

    expect(calls).toBe(0)
  })

  test("runs and queues image-only prompts without optimistic image rows", async () => {
    const ui = createFooterApiFixture()
    const active = Promise.withResolvers<void>()
    const queued = Promise.withResolvers<RunPrompt>()
    const prompt: RunPrompt = {
      text: "",
      parts: [{ type: "file", url: "data:image/png;base64,cG5n", mime: "image/png", filename: "image.png" }],
    }
    const task = runPromptQueue({
      footer: ui.api,
      run: async (input, _signal, admitted) => {
        expect(input.parts).toEqual(prompt.parts)
        admitted()
        await active.promise
      },
      admit: async (input, delivery) => {
        expect(delivery).toBe("queue")
        queued.resolve(input)
      },
      settle: async () => ui.api.close(),
    })

    ui.submit({ ...prompt, mode: "shell" })
    ui.submit(prompt)
    ui.submit(prompt)
    expect((await queued.promise).parts).toEqual(prompt.parts)
    expect(ui.commits).toEqual([])
    active.resolve()
    await task
  })

  test.each(["/exit", "/quit", "/q", ":q"])("treats %s as a close command", async (text) => {
    const ui = createFooterApiFixture()
    let calls = 0

    const task = runPromptQueue({
      footer: ui.api,
      run: async () => {
        calls += 1
      },
    })

    ui.submit(text)
    await task

    expect(calls).toBe(0)
  })

  test("treats /new as a local session command", async () => {
    const ui = createFooterApiFixture()
    const seen: string[] = []
    let created = 0

    const task = runPromptQueue({
      footer: ui.api,
      onNewSession: async () => {
        created += 1
      },
      run: async (input) => {
        seen.push(input.text)
        ui.api.close()
      },
    })

    ui.submit("/new")
    ui.submit("hello")
    await task

    expect(created).toBe(1)
    expect(seen).toEqual(["hello"])
    expect(ui.commits).toEqual([])
  })

  test("treats /compact as a local compaction command", async () => {
    const ui = createFooterApiFixture()
    const seen: string[] = []
    let compacted = 0

    const task = runPromptQueue({
      footer: ui.api,
      onCompact: async () => {
        compacted += 1
      },
      run: async (input) => {
        seen.push(input.text)
        ui.api.close()
      },
    })

    ui.submit("/compact")
    ui.submit("hello")
    await task

    expect(compacted).toBe(1)
    expect(seen).toEqual(["hello"])
    expect(ui.commits).toEqual([])
  })

  test("keeps prompts submitted after an in-flight /compact behind the compaction barrier", async () => {
    const ui = createFooterApiFixture()
    const active = Promise.withResolvers<void>()
    const order: string[] = []

    const task = runPromptQueue({
      footer: ui.api,
      onCompact: async () => {
        order.push("compact")
      },
      admit: async (prompt) => {
        order.push(`admit:${prompt.text}`)
      },
      run: async (prompt) => {
        order.push(`run:${prompt.text}`)
        if (prompt.text === "first") await active.promise
        if (prompt.text === "later") ui.api.close()
      },
    })

    ui.submit("first")
    await Promise.resolve()
    ui.submit("/compact")
    ui.submit("later")
    await Promise.resolve()
    expect(order).toEqual(["run:first"])

    active.resolve()
    await task
    expect(order).toEqual(["run:first", "compact", "run:later"])
  })

  test("shell mode submits /exit as a shell command", async () => {
    const ui = createFooterApiFixture()
    const seen: RunPrompt[] = []

    const task = runPromptQueue({
      footer: ui.api,
      run: async (input) => {
        seen.push(input)
        ui.api.close()
      },
    })

    ui.submit("/exit", "shell")
    await task

    expect(seen).toEqual([{ text: "/exit", parts: [], mode: "shell" }])
    expect(ui.commits).toEqual([])
  })

  test("shell mode submits /new instead of creating a session", async () => {
    const ui = createFooterApiFixture()
    const seen: RunPrompt[] = []
    let created = 0

    const task = runPromptQueue({
      footer: ui.api,
      onNewSession: async () => {
        created += 1
      },
      run: async (input) => {
        seen.push(input)
        ui.api.close()
      },
    })

    ui.submit("/new", "shell")
    await task

    expect(created).toBe(0)
    expect(seen).toEqual([{ text: "/new", parts: [], mode: "shell" }])
    expect(ui.commits).toEqual([])
  })

  test("shell mode does not append a synthetic user row", async () => {
    const ui = createFooterApiFixture()

    const task = runPromptQueue({
      footer: ui.api,
      run: async () => {
        expect(ui.commits).toEqual([])
        ui.api.close()
      },
    })

    ui.submit("ls", "shell")
    await task
  })

  test("shell mode does not emit a turn duration summary", async () => {
    const ui = createFooterApiFixture()

    const task = runPromptQueue({
      footer: ui.api,
      run: async () => {
        ui.api.close()
      },
    })

    ui.submit("ls", "shell")
    await task

    expect(ui.events.some((event) => event.type === "turn.duration")).toBe(false)
  })

  test("preserves whitespace for initial input", async () => {
    const ui = createFooterApiFixture()
    const seen: string[] = []

    await runPromptQueue({
      footer: ui.api,
      initialInput: "  hello  ",
      run: async (input) => {
        seen.push(input.text)
        ui.api.close()
      },
    })

    expect(seen).toEqual(["  hello  "])
    expect(ui.commits).toEqual([])
  })

  test("demo commands own their local input echo", async () => {
    const { createRunDemo } = await import("../../src/mini/demo")
    const ui = createFooterApiFixture()
    const demo = createRunDemo({ sessionID: "ses_demo", thinking: false, footer: ui.api })
    expect(await demo.prompt({ text: "ordinary prompt", parts: [] })).toBe(false)
    expect(ui.commits).toEqual([])
    const task = runPromptQueue({
      footer: ui.api,
      run: async (prompt) => {
        expect(await demo.prompt(prompt)).toBe(true)
        ui.api.close()
      },
    })

    ui.submit("/help")
    await task
    expect(ui.commits.filter((commit) => commit.kind === "user")).toMatchObject([{ text: "/help" }])
  })

  test("durably admits in-flight follow-ups in submission order", async () => {
    const ui = createFooterApiFixture()
    const admitted: string[] = []
    const gate = Promise.withResolvers<void>()

    const task = runPromptQueue({
      footer: ui.api,
      run: async (input, _signal, onAdmitted) => {
        admitted.push(`${input.text}:steer`)
        onAdmitted()
        await gate.promise
      },
      admit: async (input) => {
        admitted.push(`${input.text}:queue`)
      },
      settle: async () => ui.api.close(),
    })

    ui.submit("one")
    ui.submit("two")
    ui.submit("three")
    while (admitted.length < 3) await Bun.sleep(0)
    expect(admitted).toEqual(["one:steer", "two:queue", "three:queue"])
    expect(ui.commits).toEqual([])

    gate.resolve()
    await task
  })

  test("preserves explicit steer and queue delivery for in-flight prompts", async () => {
    const ui = createFooterApiFixture()
    const admitted: string[] = []
    const emitted: boolean[] = []
    const gate = Promise.withResolvers<void>()

    const task = runPromptQueue({
      footer: ui.api,
      onSend: (_prompt, emittedUser) => emitted.push(emittedUser),
      run: async (_input, _signal, onAdmitted) => {
        onAdmitted()
        await gate.promise
      },
      admit: async (input, delivery) => {
        admitted.push(`${input.text}:${delivery}`)
      },
      settle: async () => ui.api.close(),
    })

    ui.submit("one")
    ui.submit("two", undefined, "steer")
    ui.submit("three", undefined, "queue")
    while (admitted.length < 2) await Bun.sleep(0)
    expect(admitted).toEqual(["two:steer", "three:queue"])
    expect(emitted).toEqual([false, false, false])
    expect(ui.commits).toEqual([])

    gate.resolve()
    await task
  })

  test("continues durable admission after one fails", async () => {
    const ui = createFooterApiFixture()
    const admitted: string[] = []
    const errors: string[] = []
    const gate = Promise.withResolvers<void>()
    const task = runPromptQueue({
      footer: ui.api,
      run: async (_input, _signal, admitted) => {
        admitted()
        await gate.promise
      },
      admit: async (input) => {
        if (input.text === "two") throw new Error("admission failed")
        admitted.push(input.text)
      },
      onAdmissionError: (_prompt, error) => {
        errors.push(error instanceof Error ? error.message : String(error))
      },
      settle: async () => ui.api.close(),
    })

    ui.submit("one")
    ui.submit("two")
    ui.submit("three")
    while (admitted.length === 0) await Bun.sleep(0)
    gate.resolve()
    await task

    expect(errors).toEqual(["admission failed"])
    expect(admitted).toEqual(["three"])
  })

  test("close aborts an in-flight durable admission", async () => {
    const ui = createFooterApiFixture()
    let admissionHit = false
    const admissionStarted = Promise.withResolvers<void>()

    const task = runPromptQueue({
      footer: ui.api,
      run: async (_input, signal, admitted) => {
        admitted()
        await new Promise<void>((resolve) => signal.addEventListener("abort", () => resolve(), { once: true }))
      },
      admit: async (_prompt, _delivery, signal) => {
        admissionStarted.resolve()
        await new Promise<void>((resolve) => {
          if (signal.aborted) {
            admissionHit = true
            resolve()
            return
          }
          signal.addEventListener(
            "abort",
            () => {
              admissionHit = true
              resolve()
            },
            { once: true },
          )
        })
      },
    })

    ui.submit("one")
    await Promise.resolve()
    ui.submit("two")
    await admissionStarted.promise
    ui.api.close()
    await task

    expect(admissionHit).toBe(true)
  })

  test.each([
    ["session", undefined, false],
    ["shell", "shell", true],
  ] as const)("close handles an active %s turn", async (_name, mode, aborted) => {
    const ui = createFooterApiFixture()
    const started = Promise.withResolvers<AbortSignal>()
    const active = Promise.withResolvers<void>()
    const task = runPromptQueue({
      footer: ui.api,
      run: async (_input, signal) => {
        started.resolve(signal)
        await active.promise
      },
    })

    ui.submit("one", mode)
    const signal = await started.promise
    ui.api.close()
    await task

    expect(signal.aborted).toBe(aborted)
    active.resolve()
  })

  test("propagates run errors", async () => {
    const ui = createFooterApiFixture()

    const task = runPromptQueue({
      footer: ui.api,
      run: async () => {
        throw new Error("boom")
      },
    })

    ui.submit("one")
    await expect(task).rejects.toThrow("boom")
  })
})

import { afterEach, describe, expect, mock, spyOn, test } from "bun:test"
import { OpenCode } from "@opencode/client/promise"
import { runInteractiveDeferredMode } from "../../src/mini/runtime"
import type { LifecycleInput } from "../../src/mini/runtime.lifecycle"
import type { FooterEvent, MiniHost } from "../../src/mini/types"
import { catalogModel, catalogProvider, stubCatalogLists } from "./fixture/catalog"
import { createFooterApiFixture } from "./fixture/footer-api"
import { createTuiResolvedConfig } from "../fixture/tui-runtime"

function defer<T>() {
  let resolve!: (value: T | PromiseLike<T>) => void
  const promise = new Promise<T>((done) => {
    resolve = done
  })
  return { promise, resolve }
}

function ok<T>(data: T) {
  return Promise.resolve(data)
}

function host(): MiniHost {
  return {
    version: "local",
    terminal: { stdin: process.stdin },
    platform: "linux",
    stdout: { write() {} },
    files: { readText: async () => "" },
    editor: { open: async () => undefined },
    paths: { home: "/home/test" },
    signals: {
      sigint: { subscribe: () => () => {} },
      sigusr2: { subscribe: () => () => {} },
    },
    startup: { showTiming: false, now: () => 0 },
    diagnostics: {},
    preferences: {
      resolveVariant: async () => undefined,
      saveVariant: async () => {},
    },
  }
}

function footer(events: FooterEvent[] = []) {
  return createFooterApiFixture({ events }).api
}

afterEach(() => {
  mock.restore()
})

describe("run interactive runtime", () => {
  test("resolves the default model reactively without blocking catalog startup", async () => {
    const sdk = OpenCode.make({ baseUrl: "https://opencode.test" })
    const events: FooterEvent[] = []
    const ui = createFooterApiFixture({ events })
    const api = ui.api
    const selected = defer<Awaited<ReturnType<typeof sdk.model.default>>>()
    const catalogLoaded = defer<void>()
    const defaultModelReloaded = defer<void>()
    const modelShown = defer<void>()
    const turnStarted = defer<void>()
    const model = catalogModel({
      id: "resolved",
      providerID: "test",
      name: "Resolved Model",
      variants: ["low", "high"],
    })
    let lifecycle!: LifecycleInput
    let turnAgent: string | undefined
    let turnModel: { providerID: string; modelID: string } | undefined
    let refreshCatalog: (() => Promise<unknown>) | undefined
    stubCatalogLists(sdk, {
      providers: [catalogProvider("test", "Test Provider")],
      models: [model],
    })
    let defaultModelCalls = 0
    const defaultModel = spyOn(sdk.model, "default").mockImplementation(() => {
      defaultModelCalls++
      if (defaultModelCalls === 2) defaultModelReloaded.resolve()
      return selected.promise
    })
    const emit = api.event.bind(api)
    api.event = (event) => {
      emit(event)
      if (event.type === "model") modelShown.resolve()
    }

    const task = runInteractiveDeferredMode(
      {
        host: host(),
        sdk,
        directory: "/tmp",
        target: async () => ({
          sessionID: "ses_root",
          location: { directory: "/tmp", project: { id: "pro-1", directory: "/tmp", canonical: "/tmp" } },
          agent: "build",
          model: undefined,
          variant: undefined,
          resume: false,
        }),
        agent: "build",
        model: undefined,
        variant: undefined,
        files: [],
      },
      {
        createRuntimeLifecycle: async (input) => {
          lifecycle = input
          return {
            footer: api,
            onResize: () => () => {},
            refreshTheme: () => {},
            setTitle: () => {},
            resetForReplay: () => Promise.resolve(),
            close: () => Promise.resolve(),
          }
        },
        streamTransport: Promise.resolve({
          createSessionTransport: async (input) => {
            refreshCatalog = () => Promise.resolve(input.onCatalogRefresh?.())
            await refreshCatalog()
            catalogLoaded.resolve()
            return {
              runPromptTurn: async (input) => {
                turnAgent = input.agent
                turnModel = input.model
                turnStarted.resolve()
                api.close()
              },
              admitPromptTurn: async () => {},
              waitForIdle: async () => {},
              interruptActiveTurn: async () => {},
              selectSubagent: () => {},
              replayOnResize: async () => false,
              close: async () => {},
            }
          },
          formatUnknownError: (error: unknown) => String(error),
        }),
      },
    )

    await catalogLoaded.promise
    expect(events.some((event) => event.type === "model")).toBe(false)
    await refreshCatalog?.()
    expect(defaultModel).toHaveBeenCalledTimes(1)
    selected.resolve({
      location: { directory: "/tmp" },
      data: model,
    })
    await defaultModelReloaded.promise
    await modelShown.promise
    expect(events).toContainEqual({
      type: "model",
      model: "Resolved Model · Test Provider",
      selection: { providerID: "test", modelID: "resolved" },
    })
    expect(lifecycle.onCycleVariant?.()).toMatchObject({ status: "variant low", variant: "low" })
    lifecycle.onAgentSelect?.("review")
    await ui.promptReady
    expect(ui.submit("hello")).toBe(true)
    await turnStarted.promise
    expect(turnAgent).toBe("review")
    expect(turnModel).toEqual({ providerID: "test", modelID: "resolved" })
    await task
  })

  test("routes form responses to their owners with global location and local settlement", async () => {
    const sdk = OpenCode.make({ baseUrl: "https://opencode.test" })
    const api = footer()
    const streamStarted = defer<void>()
    let lifecycle!: LifecycleInput
    const settled: Array<{ sessionID: string; formID: string }> = []
    stubCatalogLists(sdk)
    const reply = spyOn(sdk.session.form, "reply").mockImplementation(() => ok(undefined))

    const task = runInteractiveDeferredMode(
      {
        host: host(),
        sdk,
        directory: "/tmp",
        target: async () => ({
          sessionID: "ses_root",
          location: { directory: "/tmp", project: { id: "pro-1", directory: "/tmp", canonical: "/tmp" } },
          agent: "build",
          model: { providerID: "test", modelID: "model" },
          variant: undefined,
          resume: false,
        }),
        agent: "build",
        model: { providerID: "test", modelID: "model" },
        variant: undefined,
        files: [],
      },
      {
        createRuntimeLifecycle: async (input) => {
          lifecycle = input
          return {
            footer: api,
            onResize: () => () => {},
            refreshTheme: () => {},
            setTitle: () => {},
            resetForReplay: () => Promise.resolve(),
            close: () => Promise.resolve(),
          }
        },
        streamTransport: Promise.resolve({
          createSessionTransport: async () => {
            streamStarted.resolve()
            return {
              runPromptTurn: async () => {},
              admitPromptTurn: async () => {},
              waitForIdle: async () => {},
              interruptActiveTurn: async () => {},
              selectSubagent: () => {},
              settleForm: (sessionID: string, formID: string) => settled.push({ sessionID, formID }),
              replayOnResize: async () => false,
              close: async () => {},
            }
          },
          formatUnknownError: (error: unknown) => (error instanceof Error ? error.message : String(error)),
        }),
      },
    )
    await streamStarted.promise

    await lifecycle.onFormReply({
      sessionID: "global",
      formID: "frm_global",
      answer: { value: "yes" },
      location: { directory: "/remote work" },
    })
    expect(reply).toHaveBeenCalledWith(
      {
        sessionID: "global",
        formID: "frm_global",
        answer: { value: "yes" },
        location: { directory: "/remote work" },
      },
      {
        headers: {
          "x-opencode-directory": "%2Fremote%20work",
        },
      },
    )
    expect(settled).toEqual([{ sessionID: "global", formID: "frm_global" }])

    reply.mockImplementationOnce(() => Promise.reject({ _tag: "FormInvalidAnswerError", message: "Invalid answer" }))
    await expect(
      lifecycle.onFormReply({ sessionID: "ses_child", formID: "frm_invalid", answer: { value: 3 } }),
    ).rejects.toEqual({ _tag: "FormInvalidAnswerError", message: "Invalid answer" })
    expect(settled.some((item) => item.formID === "frm_invalid")).toBe(false)

    api.close()
    await task
  })

  test("resolves the deferred session only after first paint", async () => {
    const sdk = OpenCode.make({ baseUrl: "https://opencode.test" })
    const lifecycleStarted = defer<void>()
    const painted = defer<void>()
    const api = footer()
    let resolved = 0
