      text: "Review @note.ts and image.png with @scan",
      files: [
        {
          data: "",
          mime: "text/plain",
          source: { type: "uri", uri: "file:///tmp/note.ts" },
          name: "note.ts",
          mention: { start: 7, end: 15, text: "@note.ts" },
        },
        {
