  const setup = await renderHistory(tmp.path)
  try {
    setup.history.append({ text: "previous", files: [], agents: [], pasted: [] })

    expect(setup.history.move(1, "")).toBeUndefined()
    expect(setup.history.move(-1, "")?.text).toBe("previous")
