function VariantE(props: { active: boolean; text: string }) {
  const progress = useSpring(
    () => (props.active ? 1 : 0),
    () => ({ visualDuration: 0.35, bounce: 0 }),
  )

  return (
    <span
      style={{
        display: "grid",
        color: props.active ? "var(--text-weak, #888)" : "var(--text-strong, #eee)",
