    )
  },
}

import { createEffect, onCleanup, Show, type ValidComponent } from "solid-js"
import { createStore } from "solid-js/store"
import { Dynamic } from "solid-js/web"

export const Typewriter = <T extends ValidComponent = "p">(props: { text?: string; class?: string; as?: T }) => {
  const [store, setStore] = createStore({
    typing: false,
    displayed: "",
    cursor: true,
  })

  createEffect(() => {
    const text = props.text

    if (!text) return

    let i = 0
    const timeouts: ReturnType<typeof setTimeout>[] = []
    setStore("typing", true)
    setStore("displayed", "")
    setStore("cursor", true)

    const getTypingDelay = () => {
      const random = Math.random()

      if (random < 0.05) return 150 + Math.random() * 100

      if (random < 0.15) return 80 + Math.random() * 60

      return 30 + Math.random() * 50
    }

    const type = () => {
      if (i < text.length) {
        setStore("displayed", text.slice(0, i + 1))
        i++
        timeouts.push(setTimeout(type, getTypingDelay()))
      } else {
        setStore("typing", false)
        timeouts.push(setTimeout(() => setStore("cursor", false), 2000))
      }
    }

    timeouts.push(setTimeout(type, 200))

    onCleanup(() => {
      for (const timeout of timeouts) clearTimeout(timeout)
    })
  })

  return (
    <Dynamic component={props.as || "p"} class={props.class}>
      {store.displayed}
      <Show when={store.cursor}>
        <span classList={{ "blinking-cursor": !store.typing }}>│</span>
      </Show>
    </Dynamic>
  )
}

import {
  createContext,
  createEffect,
  createRoot,
  createSignal,
  getOwner,
  onCleanup,
  type Owner,
  type ParentProps,
  runWithOwner,
  useContext,
  type JSX,
  startTransition,
  For,
} from "solid-js"
import { Dialog as Kobalte } from "@kobalte/core/dialog"
import { makeEventListener } from "@solid-primitives/event-listener"

type DialogElement = () => JSX.Element

type FocusReturn = { element: HTMLElement; range?: Range }

type Active = {
  id: string
  node: JSX.Element
  dispose: () => void
  owner: Owner
  onClose?: () => void
  setClosing: (closing: boolean) => void
  /** Where focus was before this dialog opened, or before the dialogs it replaced opened. */
  focus?: FocusReturn
  returnFocus: () => void
}

const Context = createContext<ReturnType<typeof init>>()

// Lets the dialog rendered in a layer opt out of closing on a backdrop click.
const LayerContext = createContext<{ setBackdropDismiss: (value: boolean) => void }>()

export function useDialogLayer() {
  return useContext(LayerContext)
}

function init() {
  const [stack, setStack] = createSignal<Active[]>([])
  // A dialog is closing from the moment its close starts until its exit animation ends and it is disposed.
  const closing = new Map<string, ReturnType<typeof setTimeout> | undefined>()
  // The same ids, reactive, so the top dialog that stays open owns the focus trap during an exit animation.
  const [exiting, setExiting] = createSignal<ReadonlySet<string>>(new Set())
  // The top dialog that stays open. A dialog without an exit animation leaves the DOM as soon as it starts closing, so
  // it stops being the active dialog then, not when it is disposed.
  const top = () => stack().findLast((item) => !exiting().has(item.id))
  const lock = { value: false }
  const state = { disposed: false }

  // Detach the stack before disposing, so cleanups that close dialogs find nothing to admit. Every dialog is
  // drained even when one throws. A replaced dialog that was not already closing still hears onClose.
  const disposeAll = (notify: boolean) => {
    const items = stack()
    const exited = new Set(closing.keys())
    setStack([])
    closing.forEach((timer) => clearTimeout(timer))
    closing.clear()
    setExiting(new Set<string>())
    items.forEach((item) => {
      if (notify && !exited.has(item.id)) isolate(() => item.onClose?.())
      isolate(item.dispose)
    })
  }

  onCleanup(() => {
    state.disposed = true
    disposeAll(false)
  })

  const finish = (current: Active) => {
    // Scheduled first, so the dialog still goes away when a callback throws.
    closing.set(
      current.id,
      setTimeout(() => {
        closing.delete(current.id)

        if (closing.size === 0) lock.value = false
        setExiting((ids) => new Set([...ids].filter((id) => id !== current.id)))
        setStack((items) => items.filter((item) => item.id !== current.id))
        current.dispose()
      }, 100),
    )
    setExiting((ids) => new Set([...ids, current.id]))
    isolate(() => current.onClose?.())
    current.setClosing(true)

    // Only the top open dialog holds focus. It returns before close() does, as a native dialog's does, so an
    // action that runs after closing, such as a palette command that opens the terminal, can move it on.
    if (stack().findLast((item) => item === current || !closing.has(item.id)) === current) current.returnFocus()
  }

  /** Programmatic close. Without an id it closes the top dialog, one at a time; with an id it never waits. */
  const close = (id?: string) => {
    const current = id ? stack().find((item) => item.id === id) : stack().at(-1)

    if (!current || closing.has(current.id) || (!id && lock.value)) return
    closing.set(current.id, undefined)
    lock.value = true
    finish(current)
  }

  /** Escape, a backdrop click, or Kobalte dismissing: only the top dialog, and one per exit animation. */
  const dismiss = (id?: string) => {
    const current = stack().at(-1)

    if (!current || (id && current.id !== id) || closing.has(current.id) || lock.value) return
    closing.set(current.id, undefined)
    lock.value = true
    finish(current)
  }

  createEffect(() => {
    if (stack().length === 0) return

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return

      // A control that cancels its own edit on Escape, such as an inline rename, keeps the dialog open.
      if (event.target instanceof Element && event.target.closest("[data-owns-escape]")) return
      dismiss()
      event.preventDefault()
      event.stopPropagation()
    }

    makeEventListener(window, "keydown", onKeyDown, { capture: true })
  })

  const mount = (
    element: DialogElement,
    owner: Owner,
    onClose: (() => void) | undefined,
    key: string | undefined,
    focus: FocusReturn | undefined,
  ) => {
    // A deferred open (e.g. from a focus callback) must not mount after the provider is gone.
    if (state.disposed) return
    const id = key ?? Math.random().toString(36).slice(2)

    // The layer follows the dialog's current place in the stack, so a new top dialog always renders above.
    const layer = () =>
      Math.max(
        0,
        stack().findIndex((item) => item.id === id),
      )

    const zIndex = () => String(50 + layer() * 10)
    let dispose: (() => void) | undefined
    let setClosing: ((closing: boolean) => void) | undefined
    let layerRef: HTMLDivElement | undefined

    // Stacked dialogs render as sibling portals, so only the top layer may own the focus trap.
    const node = runWithOwner(owner, () =>
      createRoot((d: () => void) => {
        dispose = d
        const [closing, setClosingSignal] = createSignal(false)
        const [backdropDismiss, setBackdropDismiss] = createSignal(true)
        setClosing = setClosingSignal

        return (
          <Kobalte
            modal={top()?.id === id}
            open={!closing()}
            onOpenChange={(open: boolean) => {
              if (!open) dismiss(id)
            }}
          >
            <Kobalte.Portal>
              <Kobalte.Overlay
                data-component="dialog-overlay"
                style={{ "z-index": zIndex() }}
                onClick={() => {
                  if (backdropDismiss()) dismiss(id)
                }}
              />
              <div
                ref={layerRef}
                data-dialog-layer={layer()}
                style={{
                  position: "fixed",
                  inset: "0",
                  "z-index": zIndex(),
                  display: "flex",
                  "align-items": "center",
                  "justify-content": "center",
                  "pointer-events": "none",
                }}
              >
                <LayerContext.Provider value={{ setBackdropDismiss }}>{element()}</LayerContext.Provider>
              </div>
            </Kobalte.Portal>
          </Kobalte>
        )
      }),
    )

    if (!dispose || !setClosing) return

    const active: Active = {
      id,
      node,
      dispose,
      owner,
      onClose,
      setClosing,
      focus,
      returnFocus: () => {
        // A close inside a reactive update unmounts the dialog, and its focus trap, only when the update ends.
        if (layerRef?.contains(document.activeElement)) return queueMicrotask(() => returnFocus(focus, layerRef))
        returnFocus(focus, layerRef)
      },
    }

    setStack((items) => [...items, active])
  }

  const push = (element: DialogElement, owner: Owner, onClose?: () => void, id?: string) => {
    lock.value = false
    mount(element, owner, onClose, id, captureFocus())
  }

  const show = (element: DialogElement, owner: Owner, onClose?: () => void, id?: string) => {
    // A replacement returns focus to where the dialogs it replaces would have, not to their now-removed content.
    const focus = stack().length > 0 ? stack()[0].focus : captureFocus()
    disposeAll(true)
    lock.value = false
    mount(element, owner, onClose, id, focus)
  }

  return {
    stack,
    top,
    close,
    show,
    push,
  }
}

/** Runs a dialog callback so its throw is reported without stopping the caller's cleanup. */
function isolate(fn: () => void) {
  try {
    fn()
  } catch (error) {
    console.error("[dialog]", error)
  }
}

/** Remembers the focused element and, in editable content, the caret, which focusing alone does not restore. */
function captureFocus(): FocusReturn | undefined {
  const element = document.activeElement

  if (!(element instanceof HTMLElement) || element === document.body) return
  const selection = document.getSelection()

  if (!element.isContentEditable || !selection?.rangeCount || !element.contains(selection.anchorNode)) {
    return { element }
  }

  return { element, range: selection.getRangeAt(0).cloneRange() }
}

/** Kobalte only returns focus to a dialog trigger, and these dialogs open without one. */
function returnFocus(focus: FocusReturn | undefined, layer: HTMLElement | undefined) {
  const active = document.activeElement

  if (!focus?.element.isConnected) return

  // Something outside the closed dialog already has focus, for example because the dialog's onClose moved it.
  if (active && active !== document.body && !layer?.contains(active)) return
  focus.element.focus({ preventScroll: true })

  if (!focus.range || !focus.element.contains(focus.range.commonAncestorContainer)) return
  const selection = document.getSelection()
  selection?.removeAllRanges()
  selection?.addRange(focus.range)
}

export function DialogProvider(props: ParentProps) {
  const ctx = init()

  return (
    <Context.Provider value={ctx}>
      {props.children}
      <div data-component="dialog-stack">
        <For each={ctx.stack()}>{(item) => item.node}</For>
      </div>
    </Context.Provider>
  )
}

export function useDialog() {
  const ctx = useContext(Context)
  const owner = getOwner()

  if (!owner) {
    throw new Error("useDialog must be used within a DialogProvider")
  }

  if (!ctx) {
    throw new Error("useDialog must be used within a DialogProvider")
  }

  return {
    /** The top dialog that is open. One that has started closing no longer counts, though it waits to be disposed. */
    get active() {
      return ctx.top()
    },
    /**
     * id lets the caller close this dialog later rather than whichever is on top. Opening is deferred; once
     * signal aborts, the open neither mounts nor replaces anything and onClose runs as for a replaced dialog.
     */
    show(element: DialogElement, onClose?: () => void, id?: string, signal?: AbortSignal) {
      const base = ctx.stack().at(-1)?.owner ?? owner

      return startTransition(() => {
        if (signal?.aborted) return isolate(() => onClose?.())
        ctx.show(element, base, onClose, id)
      })
    },
    push(element: DialogElement, onClose?: () => void, id?: string, signal?: AbortSignal) {
      const base = ctx.stack().at(-1)?.owner ?? owner

      return startTransition(() => {
        if (signal?.aborted) return isolate(() => onClose?.())
        ctx.push(element, base, onClose, id)
      })
    },
    close(id?: string) {
      ctx.close(id)
    },
  }
}

import { createContext, createMemo, Show, useContext, type ParentProps, type Accessor } from "solid-js"

export function createSimpleContext<T, Props extends Record<string, any>>(
  input: {
    name: string
    init: ((input: Props) => T) | (() => T)
  } & (T extends { ready: unknown } ? { gate: boolean } : { gate?: boolean }),
) {
  const ctx = createContext<T>()

  return {
    provider: (props: ParentProps<Props>) => {
      const init = input.init(props)
      const gate = input.gate ?? true

      if (!gate) {
        return <ctx.Provider value={init}>{props.children}</ctx.Provider>
      }

      // Access init.ready inside the memo to make it reactive for getter properties
      const isReady = createMemo(() => {
        // @ts-expect-error
        const ready = init.ready as Accessor<boolean> | boolean | undefined

        return ready === undefined || (typeof ready === "function" ? ready() : ready)
      })

      return (
        <Show when={isReady()}>
          <ctx.Provider value={init}>{props.children}</ctx.Provider>
        </Show>
      )
    },
    use() {
      const value = useContext(ctx)

      if (!value) throw new Error(`${input.name} context must be used within a context provider`)

      return value
    },
  }
}

import { describe, expect, test } from "bun:test"
import { createUiI18n, localizedListSeparator, pluralCategory, type UiI18nSource } from "./i18n"

const i18n = (locale: string, translated: string) => {
  const source: UiI18nSource = {
    locale: () => locale,
    t: () => translated,
    plural: () => "",
  }

  return createUiI18n(source)
}

describe("pluralCategory", () => {
  test.each([
    ["en", 0, "other"],
    ["en", 1, "one"],
    ["fr", 0, "one"],
    ["fr", 1_000_000, "many"],
    ["ru", 1, "one"],
    ["ru", 2, "few"],
    ["ru", 5, "many"],
    ["ru", 21, "one"],
    ["ar", 0, "zero"],
    ["ar", 1, "one"],
    ["ar", 2, "two"],
    ["ar", 3, "few"],
    ["ar", 11, "many"],
    ["ar", 100, "other"],
    ["ja", 1, "other"],
  ] as const)("selects %s for %d as %s", (locale, count, expected) => {
    expect(pluralCategory(locale, count)).toBe(expected)
  })
})

describe("dynamic source copy", () => {
  test("keeps runtime copy for English locale tags", () => {
    expect(
      i18n("en-US", "Dictionary copy").tDynamic("dialog.usageExceeded.freeTier.title", "Runtime {{name}}", {
        name: "copy",
      }),
    ).toBe("Runtime copy")
  })

  test("uses dictionary copy for non-English locales", () => {
    expect(i18n("fr", "Texte traduit").tDynamic("dialog.usageExceeded.freeTier.title", "Runtime copy")).toBe(
      "Texte traduit",
    )
  })
})

describe("localizedListSeparator", () => {
  test("uses locale list punctuation and conjunctions", () => {
    expect(localizedListSeparator("en", 1, 3)).toBe(", ")
    expect(localizedListSeparator("en", 2, 3)).toBe(", and ")
    expect(localizedListSeparator("de", 1, 2)).toBe(" und ")
  })

  test("formats a complete localized list", () => {
    expect(i18n("en", "").list(["Read", "Search", "List"])).toBe("Read, Search, List")
    expect(i18n("en-US", "").list(["Read", "Search"])).toBe("Read, Search")
    expect(i18n("en", "").listSeparator(2, 3)).toBe(",")
    expect(i18n("de", "").list(["Lesen", "Suchen"])).toBe("Lesen und Suchen")
  })
})

import { createContext, useContext, type Accessor, type ParentProps } from "solid-js"
import { I18nProvider } from "@kobalte/core/i18n"
import { dict as en } from "../i18n/en"
import type { Key, LocaleKey, PluralCategory, PluralKey, PluralLookupKey } from "../i18n/en"

export type UiI18nKey = Key

export type UiI18nPluralKey = PluralKey

export type UiPluralCategory = PluralCategory

export type UiI18nPluralLookupKey = PluralLookupKey

export type UiI18nLocaleKey = LocaleKey

type UiTranslationKey<Value extends string> = Value extends UiI18nPluralLookupKey ? never : Value

export type UiI18nOrdinaryKey = UiTranslationKey<UiI18nKey>

export type UiI18nParams = Record<string, string | number | boolean>

export type UiTranslate = <Value extends string>(key: UiTranslationKey<Value>, params?: UiI18nParams) => string

export type UiI18nSource = {
  locale: Accessor<string>
  layoutLocale?: Accessor<string>
  t: UiTranslate
  plural: (key: UiI18nPluralKey, count: number, params?: UiI18nParams) => string
  pluralForm?: (key: UiI18nPluralKey, category: UiPluralCategory, params?: UiI18nParams) => string
}

export type UiI18n = UiI18nSource & {
  /** Preserve runtime-generated English copy while using the keyed dictionary for every other locale. */
  tDynamic: (key: UiI18nOrdinaryKey, source: string, params?: UiI18nParams) => string
  list: (items: readonly string[]) => string
  listSeparator: (index: number, count: number) => string
}

const rules = new Map<string, Intl.PluralRules>()

export function pluralCategory(locale: string, count: number): UiPluralCategory {
  const cached = rules.get(locale)

  if (cached) return cached.select(count)
  const next = new Intl.PluralRules(locale)

  if (rules.size >= 32) rules.delete(rules.keys().next().value!)
  rules.set(locale, next)

  return next.select(count)
}

export function pluralKey(key: UiI18nPluralKey, category: UiPluralCategory) {
  return `${key}.${category}` as UiI18nPluralLookupKey
}

export function localizedListSeparator(locale: string, index: number, count: number) {
  if (index <= 0 || index >= count) return ""

  const parts = new Intl.ListFormat(locale, { style: "long", type: "conjunction" }).formatToParts(
    Array.from({ length: count }, (_, item) => String(item)),
  )

  const current = parts.findIndex((part) => part.type === "element" && part.value === String(index))

  const previous = parts.findLastIndex(
    (part, partIndex) => partIndex < current && part.type === "element" && part.value === String(index - 1),
  )

  return parts
    .slice(previous + 1, current)
    .map((part) => part.value)
    .join("")
}

function resolveTemplate(text: string, params?: UiI18nParams) {
  if (!params) return text

  return text.replace(/{{\s*([^}]+?)\s*}}/g, (_, rawKey) => {
    const key = String(rawKey)
    const value = params[key]

    return value === undefined ? "" : String(value)
  })
}

export function createUiI18n(source: UiI18nSource): UiI18n {
  return {
    ...source,
    tDynamic: (key, value, params) =>
      source.locale().toLowerCase().split("-")[0] === "en" ? resolveTemplate(value, params) : source.t(key, params),
    // English tool labels intentionally use comma-only lists; the animated count labels use the same punctuation.
    list: (items) =>
      source.locale().toLowerCase().split("-")[0] === "en"
        ? items.join(", ")
        : new Intl.ListFormat(source.locale(), { style: "long", type: "conjunction" }).format(items),
    listSeparator: (index, count) =>
      source.locale().toLowerCase().split("-")[0] === "en"
        ? index > 0 && index < count
          ? ","
          : ""
        : localizedListSeparator(source.locale(), index, count),
  }
}

const fallbackSource: UiI18nSource = {
  locale: () => "en",
  t: (key, params) => {
    const value = en[key as UiI18nKey] ?? String(key)

    return resolveTemplate(value, params)
  },
  plural: (key, count, params) =>
    fallback.pluralForm!(key, pluralCategory(fallback.locale(), count), { ...params, count }),
  pluralForm: (key, category, params) => {
    const values = en as Partial<Record<UiI18nLocaleKey, string>>
    const value = values[pluralKey(key, category)] ?? values[`${key}.other`] ?? `${key}.other`

    return resolveTemplate(value, params)
  },
}

const fallback = createUiI18n(fallbackSource)

const Context = createContext<UiI18n>(fallback)

function UiI18nProvider(props: ParentProps<{ value: UiI18nSource }>) {
  const value = createUiI18n(props.value)

  return (
