import { type ComponentProps, createMemo, Show, splitProps } from "solid-js"
import "./progress-circle.css"

export interface ProgressCircleProps extends Pick<ComponentProps<"svg">, "class" | "classList" | "style"> {
  percentage: number
  appearance?: "compact" | "indicator"
  size?: number
  strokeWidth?: number
}

export function ProgressCircle(props: ProgressCircleProps) {
  const [local, rest] = splitProps(props, ["percentage", "appearance", "size", "strokeWidth", "class", "classList"])

  const appearance = () => local.appearance ?? "compact"
  const viewBoxSize = () => (appearance() === "indicator" ? 16 : 14)
  const size = () => local.size ?? viewBoxSize()
  const strokeWidth = () => local.strokeWidth ?? (appearance() === "indicator" ? 3 : 1.5)
  const center = () => viewBoxSize() / 2
  const radius = () => center() - strokeWidth() / 2
  const circumference = createMemo(() => 2 * Math.PI * radius())
  const offset = createMemo(() => circumference() * (1 - Math.max(0, Math.min(100, local.percentage || 0)) / 100))

  return (
    <svg
      {...rest}
      width={size()}
      height={size()}
      viewBox={`0 0 ${viewBoxSize()} ${viewBoxSize()}`}
      fill="none"
      data-component="progress-circle"
      data-appearance={appearance()}
      classList={{
        ...local.classList,
        [local.class ?? ""]: !!local.class,
      }}
    >
      <circle
        cx={center()}
        cy={center()}
        r={radius()}
        data-slot="progress-circle-background"
        stroke-width={strokeWidth()}
      />
      <Show when={appearance() === "indicator"}>
        <circle
          cx={center()}
          cy={center()}
          r={radius()}
          data-slot="progress-circle-background-overlay"
          stroke-width={strokeWidth()}
        />
      </Show>
      <circle
        cx={center()}
        cy={center()}
        r={radius()}
        data-slot="progress-circle-progress"
        stroke-width={strokeWidth()}
        stroke-dasharray={circumference().toString()}
        stroke-dashoffset={offset()}
      />
    </svg>
  )
}

import { describe, expect, test } from "bun:test"
import { boundToastDescription, toastDescriptionLimit } from "./description"

describe("toast description bound", () => {
  test("keeps ordinary descriptions and the options object", () => {
    const options = { title: "Failed", description: "Attachment exceeds the limit" }
    expect(boundToastDescription(options)).toBe(options)
    expect(boundToastDescription({ description: undefined })).toEqual({ description: undefined })
  })

  test("cuts a description that embeds a whole data URL", () => {
    const description = `Attachment exceeds the limit: data:text/plain;base64,${"Q".repeat(50 * 1024 * 1024)}`
    const bounded = boundToastDescription({ title: "Failed to send prompt", description })
    expect(bounded.description!.length).toBe(toastDescriptionLimit + 1)
    expect(bounded.description!.endsWith("…")).toBe(true)
    expect(bounded.description!.startsWith("Attachment exceeds the limit: data:text/plain;base64,")).toBe(true)
    expect(bounded.title).toBe("Failed to send prompt")
  })
})

// A toast shows a few lines; the rest of a long description would only be retained (in the dedupe
// key, the active-toast registry and the toaster's store) for as long as the toast lives. Server
// errors have carried a whole data URL here.
export const toastDescriptionLimit = 2000

export function boundToastDescription<T extends { description?: string }>(options: T): T {
  if (!options.description || options.description.length <= toastDescriptionLimit) return options

  return { ...options, description: `${options.description.slice(0, toastDescriptionLimit)}…` }
}

import { Toaster, toast, type ToasterProps } from "solid-sonner"
