let toastV2Id = 0

export const toaster = {
  show(
    render: (props: { toastId: number }) => JSX.Element,
    options?: {
      duration?: number
      persistent?: boolean
      /** Reactive value the toast's height depends on; sonner re-measures when it changes. */
      resize?: () => void
    },
  ) {
    const toastId = --toastV2Id
    toast.custom((id) => render({ toastId: Number(id) }), {
      id: toastId,
      className: "toast-v2",
      duration: options?.persistent ? Number.POSITIVE_INFINITY : options?.duration,
      unstyled: true,
      // Sonner only re-measures on title/description changes, so a function-valued description is
      // the hook for a custom toast whose height depends on reactive state. It renders nothing;
      // toast.css collapses the empty description element.
      description: options?.resize
        ? (): JSX.Element => {
            options.resize?.()

            return undefined
          }
        : undefined,
    })

    return toastId
  },
  dismiss(toastId?: number) {
    if (toastId === undefined) {
      activeToastByKey.clear()
      activeToastById.clear()
    } else {
      releaseToast(activeToastById.get(toastId))
    }

    return toast.dismiss(toastId)
  },
}

export interface ToastAction {
  label: string
  variant?: "primary" | "secondary"
  onClick: "dismiss" | (() => void)
}

export interface ToastOptions {
  title?: string
  description?: string
  /** An element, or a render function the toast calls under its own owner, for icons created from imperative code. */
  icon?: JSX.Element | (() => JSX.Element)
  variant?: "default" | "success" | "error" | "loading"
  duration?: number
  persistent?: boolean
  actions?: ToastAction[]
}

interface ActiveToast {
  id: number
  key: string
  options: ToastOptions
  actions?: JSX.Element
}

const activeToastByKey = new Map<string, ActiveToast>()

const activeToastById = new Map<number, ActiveToast>()

export function showToast(options: ToastOptions | string) {
  // SAFETY: `options` is declared `ToastOptions | string`; `typeof` separates the string shorthand from the object.
  // oxlint-disable-next-line anti-slop/no-runtime-typeof -- see SAFETY above
  const opts = boundToastDescription(typeof options === "string" ? { description: options } : options)

  const key = JSON.stringify({
    title: opts.title,
    description: opts.description,
    variant: opts.variant,
    duration: opts.duration,
    persistent: opts.persistent,
    actions: opts.actions?.map((action) => [action.label, action.variant]),
  })

  const active = activeToastByKey.get(key)
  const toasts = toast.getToasts()

  if (active && toasts.at(-1)?.id === active.id) {
    active.options = opts
    publishToast(active)
    pulseToast(active.id)

    return active.id
  }

  if (active && toasts.some((item) => item.id === active.id)) toaster.dismiss(active.id)
  releaseToast(active)

  const entry: ActiveToast = { id: --toastV2Id, key, options: opts }
  entry.actions = createToastActions(entry)
  activeToastByKey.set(key, entry)
  activeToastById.set(entry.id, entry)
  publishToast(entry)

  return entry.id
}

function publishToast(entry: ActiveToast) {
  const release = () => releaseToast(entry)
  toast(entry.options.title ?? "", {
    id: entry.id,
    description: entry.options.description,
    // SAFETY: solid-sonner inserts `icon` as a JSX child, and Solid calls a function child under the toast's render
    // owner; solid-sonner's type omits function children.
    icon: entry.options.icon as JSX.Element,
    action: entry.actions,
    closeButton: true,
    duration: entry.options.persistent ? Number.POSITIVE_INFINITY : entry.options.duration,
    className: `toast-v2 toast-v2--${entry.options.variant ?? "default"}`,
    testId: `toast-v2-${entry.id}`,
    unstyled: true,
    onDismiss: release,
    onAutoClose: release,
  })
}

function createToastActions(entry: ActiveToast) {
  if (!entry.options.actions?.length) return undefined

  return (
    <Toast.Actions>
      {/* Static map, not <For>: this JSX is created imperatively outside any Solid
          root, where a <For> computation would never be disposed. */}
      {entry.options.actions.map((action, index) => (
        <button
          type="button"
          data-component="button-v2"
          data-variant={action.variant === "secondary" ? "ghost" : "neutral"}
          data-size="small"
          data-action-variant={action.variant ?? "primary"}
          onClick={() => {
            const onClick = entry.options.actions?.[index]?.onClick

            if (onClick && onClick !== "dismiss") onClick()
            toaster.dismiss(entry.id)
          }}
        >
          {action.label}
        </button>
      ))}
    </Toast.Actions>
  )
}

function pulseToast(toastId: number) {
  if (typeof document === "undefined" || typeof requestAnimationFrame === "undefined") return
  requestAnimationFrame(() => {
    const element = document.querySelector<HTMLElement>(`[data-testid="toast-v2-${toastId}"]`)

    if (!element || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return
    element.animate([{ scale: 1 }, { scale: 1.025 }, { scale: 1 }], { duration: 160, easing: "ease-out" })
  })
}

function releaseToast(entry: ActiveToast | undefined) {
  if (!entry) return

  if (activeToastByKey.get(entry.key) === entry) activeToastByKey.delete(entry.key)

  if (activeToastById.get(entry.id) === entry) activeToastById.delete(entry.id)
}

export interface ToastPromiseOptions<T, U = unknown> {
  loading?: JSX.Element
  success?: (data: T) => JSX.Element
  error?: (error: U) => JSX.Element
}

import {
  createContext,
  createEffect,
  createSignal,
  createUniqueId,
  onCleanup,
  onMount,
  splitProps,
  useContext,
  Show,
  type ComponentProps,
  type ParentProps,
} from "solid-js"
import { Tooltip } from "@opencode/ui/tooltip"
import "./field.css"

type FieldContextValue = {
  controlId: string
  labelId: string
  prefixId: string
  suffixId: string
  invalid: () => boolean
  registerPrefix: () => void
  unregisterPrefix: () => void
  registerSuffix: () => void
  unregisterSuffix: () => void
  getDescribedBy: () => string | undefined
}

const FieldContext = createContext<FieldContextValue>()

function useField() {
  const ctx = useContext(FieldContext)

  if (!ctx) {
    throw new Error("Field subcomponents must be used within <Field>")
  }

  return ctx
}

const CONTROL_SELECTOR = [
  "[data-slot='text-input-v2-input']",
  "[data-slot='textarea-v2-textarea']",
  "[data-component='inline-input']",
].join(", ")

export interface FieldProps extends ComponentProps<"div"> {
  invalid?: boolean
}

function FieldRoot(props: ParentProps<FieldProps>) {
  const [local, rest] = splitProps(props, ["invalid", "class", "classList", "children"])

  const controlId = `field-control-${createUniqueId()}`
  const labelId = `field-label-${createUniqueId()}`
  const prefixId = `field-prefix-${createUniqueId()}`
  const suffixId = `field-suffix-${createUniqueId()}`

  const [prefixCount, setPrefixCount] = createSignal(0)
  const [suffixCount, setSuffixCount] = createSignal(0)

  let rootRef: HTMLDivElement | undefined

  const ctx: FieldContextValue = {
    controlId,
    labelId,
    prefixId,
    suffixId,
    invalid: () => !!local.invalid,
    registerPrefix: () => setPrefixCount((n) => n + 1),
    unregisterPrefix: () => setPrefixCount((n) => Math.max(0, n - 1)),
    registerSuffix: () => setSuffixCount((n) => n + 1),
    unregisterSuffix: () => setSuffixCount((n) => Math.max(0, n - 1)),
    getDescribedBy: () => {
      const ids: string[] = []

      if (prefixCount() > 0) ids.push(prefixId)

      if (suffixCount() > 0) ids.push(suffixId)

      return ids.length > 0 ? ids.join(" ") : undefined
    },
  }

  const syncControlA11y = () => {
    const root = rootRef

    if (!root) return

    const control = root.querySelector(CONTROL_SELECTOR) as HTMLInputElement | HTMLTextAreaElement | null

    if (!control) return

    const shell = control.closest(
      "[data-component='text-input-v2'], [data-component='textarea-v2'], [data-component='inline-input']",
    ) as HTMLElement | null

    control.id = controlId
    control.setAttribute("aria-labelledby", labelId)

    const describedBy = ctx.getDescribedBy()

    if (describedBy) {
      control.setAttribute("aria-describedby", describedBy)
    } else {
      control.removeAttribute("aria-describedby")
    }

    if (ctx.invalid()) {
      control.setAttribute("aria-invalid", "true")
      shell?.setAttribute("data-invalid", "")
    } else {
      control.removeAttribute("aria-invalid")
      shell?.removeAttribute("data-invalid")
    }
  }

  onMount(() => {
    syncControlA11y()
  })

  createEffect(() => {
    prefixCount()
    suffixCount()
    local.invalid
    syncControlA11y()
  })

  return (
    <FieldContext.Provider value={ctx}>
      <div
        {...rest}
        ref={rootRef}
        data-component="field-v2"
        data-invalid={local.invalid ? "" : undefined}
        classList={{
          ...local.classList,
          [local.class ?? ""]: !!local.class,
        }}
      >
        {local.children}
      </div>
    </FieldContext.Provider>
  )
}

