  { prefix: "\uFEFF", bom: false, expected: "" },
  { prefix: "\uFEFF", bom: true, expected: undefined },
  { prefix: "\uFEFF\uFEFF", bom: false, expected: "" },
  { prefix: "\uFEFF\uFEFF", bom: true, expected: "\uFEFF" },
])("syncBytes(%j)", (row) => {
