export * as Bom from "./bom.js"

import { Effect } from "effect"
import type { FSUtil } from "./fs-util.js"

const code = 0xfeff
const value = String.fromCharCode(code)

export function split(text: string) {
  const stripped = text.replace(/^\uFEFF+/, "")
  return { bom: stripped.length !== text.length, text: stripped }
}

export function join(text: string, bom: boolean) {
  const stripped = split(text).text
  return bom ? value + stripped : stripped
}

export function has(content: Uint8Array) {
  return content[0] === 0xef && content[1] === 0xbb && content[2] === 0xbf
}

export function decodeBytes(content: Uint8Array) {
  return split(decode(content))
}

export function syncBytes(content: Uint8Array, bom: boolean) {
  const decoded = decode(content)
  const current = split(decoded)
  const canonical = bom ? value + current.text : current.text
  return { text: current.text, bytes: decoded === canonical ? undefined : new TextEncoder().encode(canonical) }
}

export const readFile = Effect.fn("Bom.readFile")(function* (fs: FSUtil.Interface, filepath: string) {
  return decodeBytes(yield* fs.readFile(filepath))
})

export const syncFile = Effect.fn("Bom.syncFile")(function* (fs: FSUtil.Interface, filepath: string, bom: boolean) {
  const synced = syncBytes(yield* fs.readFile(filepath), bom)
  if (synced.bytes) yield* fs.writeWithDirs(filepath, synced.bytes)
  return synced.text
})

function decode(content: Uint8Array) {
  return new TextDecoder("utf-8", { ignoreBOM: true }).decode(content)
}

import { isArrayNonEmpty } from "effect/Array"
import * as NodeSink from "@effect/platform-node/NodeSink"
import * as NodeStream from "@effect/platform-node/NodeStream"
import { Deferred, Effect, Exit, FileSystem, Layer, Path, PlatformError, Predicate, Sink, Stream } from "effect"
import type { Scope } from "effect"
import { ChildProcess } from "effect/process"
import {
  ChildProcessSpawner,
  ExitCode,
  make,
  makeHandle,
  ProcessId,
  type ChildProcessHandle,
} from "effect/process/ChildProcessSpawner"
// ast-grep-ignore: no-star-import
import * as NodeChildProcess from "node:child_process"
import { PassThrough } from "node:stream"
import launch from "cross-spawn"
import { makeGlobalNode } from "./effect/app-node.js"
import { filesystem, path } from "./effect/app-node-platform.js"

const toError = (err: unknown): Error => (err instanceof globalThis.Error ? err : new globalThis.Error(String(err)))

const toTag = (err: NodeJS.ErrnoException): PlatformError.SystemErrorTag => {
  switch (err.code) {
    case "ENOENT":
      return "NotFound"
    case "EACCES":
      return "PermissionDenied"
    case "EEXIST":
      return "AlreadyExists"
    case "EISDIR":
      return "BadResource"
    case "ENOTDIR":
      return "BadResource"
    case "EBUSY":
      return "Busy"
    case "ELOOP":
      return "BadResource"
    default:
      return "Unknown"
  }
}

const flatten = (command: ChildProcess.Command) => {
  const commands: Array<ChildProcess.StandardCommand> = []
  const opts: Array<ChildProcess.PipeOptions> = []

  const walk = (cmd: ChildProcess.Command): void => {
    switch (cmd._tag) {
      case "StandardCommand":
        commands.push(cmd)
        return
      case "PipedCommand":
        walk(cmd.left)
        opts.push(cmd.options)
        walk(cmd.right)
        return
    }
  }

  walk(command)
  if (!isArrayNonEmpty(commands)) throw new Error("flatten produced empty commands array")
  return {
    commands,
    opts,
  }
}

const toPlatformError = (
  method: string,
  err: NodeJS.ErrnoException,
  command: ChildProcess.Command,
): PlatformError.PlatformError => {
  const cmd = flatten(command)
    .commands.map((x) => `${x.command} ${x.args.join(" ")}`)
    .join(" | ")
  return PlatformError.systemError({
    _tag: toTag(err),
    module: "ChildProcess",
    method,
    pathOrDescriptor: cmd,
    syscall: err.syscall,
    cause: err,
  })
}

export class KilledBySignal extends Error {
  readonly signal: NodeJS.Signals

  constructor(signal: NodeJS.Signals) {
    super(`Process interrupted due to receipt of signal: '${signal}'`)
    this.signal = signal
  }
}

type ExitSignal = Deferred.Deferred<readonly [code: number | null, signal: NodeJS.Signals | null]>
type Spawned = readonly [process: NodeChildProcess.ChildProcess, closed: ExitSignal, exited: ExitSignal]

const makeCrossSpawnSpawner = Effect.gen(function* () {
  const fs = yield* FileSystem.FileSystem
  const path = yield* Path.Path

  const cwd = Effect.fnUntraced(function* (opts: ChildProcess.CommandOptions) {
    if (Predicate.isUndefined(opts.cwd)) return undefined
    yield* fs.access(opts.cwd)
    return path.resolve(opts.cwd)
  })

  const env = (opts: ChildProcess.CommandOptions) =>
    opts.extendEnv ? { ...globalThis.process.env, ...opts.env } : opts.env

  const input = (x: ChildProcess.CommandInput | undefined): NodeChildProcess.IOType | undefined =>
    Stream.isStream(x) ? "pipe" : x

  const output = (x: ChildProcess.CommandOutput | undefined): NodeChildProcess.IOType | undefined =>
    Sink.isSink(x) ? "pipe" : x

  const stdin = (opts: ChildProcess.CommandOptions): ChildProcess.StdinConfig => {
    const cfg: ChildProcess.StdinConfig = { stream: "pipe", encoding: "utf-8", endOnDone: true }
    if (Predicate.isUndefined(opts.stdin)) return cfg
    if (typeof opts.stdin === "string") return { ...cfg, stream: opts.stdin }
    if (Stream.isStream(opts.stdin)) return { ...cfg, stream: opts.stdin }
    return {
      stream: opts.stdin.stream,
      encoding: opts.stdin.encoding ?? cfg.encoding,
      endOnDone: opts.stdin.endOnDone ?? cfg.endOnDone,
    }
  }

  const stdio = (opts: ChildProcess.CommandOptions, key: "stdout" | "stderr"): ChildProcess.StdoutConfig => {
    const cfg = opts[key]
    if (Predicate.isUndefined(cfg)) return { stream: "pipe" }
    if (typeof cfg === "string") return { stream: cfg }
    if (Sink.isSink(cfg)) return { stream: cfg }
    return { stream: cfg.stream }
  }

  const fds = (opts: ChildProcess.CommandOptions) => {
    if (Predicate.isUndefined(opts.additionalFds)) return []
    return Object.entries(opts.additionalFds)
      .flatMap(([name, config]) => {
        const fd = ChildProcess.parseFdName(name)
        return Predicate.isUndefined(fd) ? [] : [{ fd, config }]
      })
      .toSorted((a, b) => a.fd - b.fd)
  }

  const stdios = (
    sin: ChildProcess.StdinConfig,
    sout: ChildProcess.StdoutConfig,
    serr: ChildProcess.StderrConfig,
    extra: ReadonlyArray<{ fd: number; config: ChildProcess.AdditionalFdConfig }>,
  ): NodeChildProcess.StdioOptions => {
    const pipe = (x: NodeChildProcess.IOType | undefined) =>
      process.platform === "win32" && x === "pipe" ? "overlapped" : x
    const arr: Array<NodeChildProcess.IOType | undefined> = [
      pipe(input(sin.stream)),
      pipe(output(sout.stream)),
      pipe(output(serr.stream)),
    ]
    if (extra.length === 0) return arr as NodeChildProcess.StdioOptions
    const max = extra.reduce((acc, x) => Math.max(acc, x.fd), 2)
    for (let i = 3; i <= max; i++) arr[i] = "ignore"
    for (const x of extra) arr[x.fd] = pipe("pipe")
    return arr as NodeChildProcess.StdioOptions
  }

  const setupFds = Effect.fnUntraced(function* (
    command: ChildProcess.StandardCommand,
    proc: NodeChildProcess.ChildProcess,
    extra: ReadonlyArray<{ fd: number; config: ChildProcess.AdditionalFdConfig }>,
  ) {
    if (extra.length === 0) {
      return {
        getInputFd: () => Sink.drain,
        getOutputFd: () => Stream.empty,
      }
    }

    const ins = new Map<number, Sink.Sink<void, Uint8Array, never, PlatformError.PlatformError>>()
    const outs = new Map<number, Stream.Stream<Uint8Array, PlatformError.PlatformError>>()

    for (const x of extra) {
      const node = proc.stdio[x.fd]
      switch (x.config.type) {
        case "input": {
          let sink: Sink.Sink<void, Uint8Array, never, PlatformError.PlatformError> = Sink.drain
          if (node && "write" in node) {
            sink = NodeSink.fromWritable({
              evaluate: () => node,
              onError: (err) => toPlatformError(`fromWritable(fd${x.fd})`, toError(err), command),
              endOnDone: true,
            })
          }
          if (x.config.stream) yield* Effect.forkScoped(Stream.run(x.config.stream, sink))
          ins.set(x.fd, sink)
          break
        }
        case "output": {
          let stream: Stream.Stream<Uint8Array, PlatformError.PlatformError> = Stream.empty
          if (node && "read" in node) {
            const tap = new PassThrough()
            node.on("error", (err) => tap.destroy(toError(err)))
            node.pipe(tap)
            stream = NodeStream.fromReadable({
              evaluate: () => tap,
              onError: (err) => toPlatformError(`fromReadable(fd${x.fd})`, toError(err), command),
            })
          }
          if (x.config.sink) stream = Stream.transduce(stream, x.config.sink)
          outs.set(x.fd, stream)
          break
        }
      }
    }

    return {
      getInputFd: (fd: number) => ins.get(fd) ?? Sink.drain,
      getOutputFd: (fd: number) => outs.get(fd) ?? Stream.empty,
    }
  })

  const setupStdin = (
    command: ChildProcess.StandardCommand,
    proc: NodeChildProcess.ChildProcess,
    cfg: ChildProcess.StdinConfig,
  ) =>
    Effect.suspend(() => {
      let sink: Sink.Sink<void, unknown, never, PlatformError.PlatformError> = Sink.drain
      if (Predicate.isNotNull(proc.stdin)) {
        sink = NodeSink.fromWritable({
          evaluate: () => proc.stdin!,
          onError: (err) => toPlatformError("fromWritable(stdin)", toError(err), command),
          endOnDone: cfg.endOnDone,
          encoding: cfg.encoding,
        })
      }
      if (Stream.isStream(cfg.stream)) return Effect.as(Effect.forkScoped(Stream.run(cfg.stream, sink)), sink)
      return Effect.succeed(sink)
    })

  const setupOutput = (
    command: ChildProcess.StandardCommand,
    proc: NodeChildProcess.ChildProcess,
    out: ChildProcess.StdoutConfig,
    err: ChildProcess.StderrConfig,
    stopOutput: Deferred.Deferred<void>,
  ) => {
    const capture = (readable: NodeChildProcess.ChildProcess["stdout"], name: string) => {
      if (!readable) return Stream.empty
      // Bun resumes stdio on exit; retain bytes before the lazy Effect reader attaches.
      const buffer = new PassThrough()
      readable.on("error", (cause) => buffer.destroy(toError(cause)))
      readable.pipe(buffer)
      return NodeStream.fromReadable({
        evaluate: () => buffer,
        onError: (cause) => toPlatformError(`fromReadable(${name})`, toError(cause), command),
      }).pipe(
        Stream.interruptWhen(Deferred.await(stopOutput)),
        Stream.ensuring(
          Effect.gen(function* () {
            // Only the capture deadline transfers the reader back to the process scope.
            if (yield* Deferred.isDone(stopOutput)) return
            readable.destroy()
          }),
        ),
      )
    }

    let stdout = capture(proc.stdout, "stdout")
    let stderr = capture(proc.stderr, "stderr")
    if (Sink.isSink(out.stream)) stdout = Stream.transduce(stdout, out.stream)
    if (Sink.isSink(err.stream)) stderr = Stream.transduce(stderr, err.stream)

    return { stdout, stderr, all: Stream.merge(stdout, stderr) }
  }

  const launchProcess = (command: ChildProcess.StandardCommand, opts: NodeChildProcess.SpawnOptions) =>
    Effect.callback<Spawned, PlatformError.PlatformError>((resume) => {
      const closed = Deferred.makeUnsafe<readonly [code: number | null, signal: NodeJS.Signals | null]>()
      const exited = Deferred.makeUnsafe<readonly [code: number | null, signal: NodeJS.Signals | null]>()
      const proc = launch(command.command, command.args, opts)
      let end = false
      let exit: readonly [code: number | null, signal: NodeJS.Signals | null] | undefined
      proc.on("error", (err) => {
        resume(Effect.fail(toPlatformError("spawn", err, command)))
      })
      proc.on("exit", (...args) => {
        exit = args
        Deferred.doneUnsafe(exited, Exit.succeed(args))
      })
      proc.on("close", (...args) => {
        if (end) return
        end = true
        Deferred.doneUnsafe(exited, Exit.succeed(exit ?? args))
        Deferred.doneUnsafe(closed, Exit.succeed(exit ?? args))
      })
      proc.on("spawn", () => {
        resume(Effect.succeed([proc, closed, exited]))
      })
      return Effect.sync(() => {
        proc.kill("SIGTERM")
      })
    })

  const spawn = Effect.fnUntraced(function* (
    command: ChildProcess.StandardCommand,
    opts: NodeChildProcess.SpawnOptions,
  ) {
    yield* Effect.logInfo("spawning process", { command: command.command, args: command.args, cwd: opts.cwd })
    const [proc, closed, exited] = yield* launchProcess(command, opts)
    const stopOutput = yield* Deferred.make<void>()
    // Register before process release so the deadline remains active during termination.
    yield* Effect.forkScoped(
      Effect.gen(function* () {
        yield* Deferred.await(exited)
        // Particularly on Windows, some shell calls will cause detached descendants. Inherited stdio can hang the call.
        // Almost every ecosystem has tried to fix this; there's no single "good" answer here.
        // Calls that trigger this are e.g. dotnet build with warmed MSBuild processes, agent-browser, etc.
        // One shared deadline covers stdout and stderr, then the output pump finishes its file.
        if ((yield* Effect.timeoutOption(Deferred.await(closed), "1 second"))._tag === "Some") return
        yield* Deferred.succeed(stopOutput, undefined)
        discard(proc.stdout)
        discard(proc.stderr)
      }),
    )
    return [proc, closed, exited, stopOutput] as const
  })

  const discard = (readable: NodeChildProcess.ChildProcess["stdout"]) => {
    if (!readable || readable.destroyed) return
    readable.unpipe()
    // Discard descendant output without refilling a capture buffer that is no longer consumed.
    const drain = () => {
      while (readable.read() !== null) {}
    }
    readable.on("readable", drain)
    readable.once("error", () => {})
    readable.once("close", () => readable.off("readable", drain))
    drain()
  }

  const killGroup = (
    command: ChildProcess.StandardCommand,
    proc: NodeChildProcess.ChildProcess,
    signal: NodeJS.Signals,
  ) => {
    if (globalThis.process.platform === "win32") {
      return Effect.callback<void, PlatformError.PlatformError>((resume) => {
        NodeChildProcess.exec(`taskkill /pid ${proc.pid} /T /F`, { windowsHide: true }, (err) => {
          if (err) return resume(Effect.fail(toPlatformError("kill", toError(err), command)))
          resume(Effect.void)
        })
      })
    }

    return Effect.try({
      try: () => {
        globalThis.process.kill(-proc.pid!, signal)
      },
      catch: (err) => toPlatformError("kill", toError(err), command),
    })
  }

  const killOne = (
    command: ChildProcess.StandardCommand,
    proc: NodeChildProcess.ChildProcess,
    signal: NodeJS.Signals,
  ) =>
    Effect.suspend(() => {
      if (proc.kill(signal)) return Effect.void
      return Effect.fail(toPlatformError("kill", new Error("Failed to kill child process"), command))
    })

  const stop = (
    command: ChildProcess.StandardCommand,
    proc: NodeChildProcess.ChildProcess,
    closed: ExitSignal,
    stopOutput: Deferred.Deferred<void>,
    opts: ChildProcess.KillOptions | undefined,
  ) => {
    const terminate = (signal: NodeJS.Signals) =>
      Effect.catch(killGroup(command, proc, signal), () => killOne(command, proc, signal)).pipe(
        Effect.andThen(
          signal === "SIGKILL"
            ? Effect.raceFirst(Deferred.await(closed), Deferred.await(stopOutput))
            : Deferred.await(closed),
        ),
        Effect.asVoid,
      )
    const attempt = terminate(opts?.killSignal ?? "SIGTERM")
    if (opts?.forceKillAfter === undefined) return attempt
    return Effect.timeoutOrElse(attempt, {
      duration: opts.forceKillAfter,
      orElse: () => terminate("SIGKILL"),
    })
  }

  const source = (handle: ChildProcessHandle, from: ChildProcess.PipeFromOption | undefined) => {
    const opt = from ?? "stdout"
    switch (opt) {
      case "stdout":
        return handle.stdout
      case "stderr":
        return handle.stderr
      case "all":
        return handle.all
      default: {
        const fd = ChildProcess.parseFdName(opt)
        return Predicate.isNotUndefined(fd) ? handle.getOutputFd(fd) : handle.stdout
      }
    }
  }

  const spawnCommand: (
    command: ChildProcess.Command,
  ) => Effect.Effect<ChildProcessHandle, PlatformError.PlatformError, Scope.Scope> = Effect.fnUntraced(
    function* (command) {
      switch (command._tag) {
        case "StandardCommand": {
          const sin = stdin(command.options)
          const sout = stdio(command.options, "stdout")
          const serr = stdio(command.options, "stderr")
          const extra = fds(command.options)
          const dir = yield* cwd(command.options)

          const [proc, closed, exited, stopOutput] = yield* Effect.acquireRelease(
            spawn(command, {
              cwd: dir,
              env: env(command.options),
              stdio: stdios(sin, sout, serr, extra),
              detached: command.options.detached ?? process.platform !== "win32",
              shell: command.options.shell,
              windowsHide: process.platform === "win32",
            }),
            Effect.fnUntraced(
              function* ([proc, closed, exited, stopOutput]) {
                const done = (yield* Deferred.isDone(closed)) || (yield* Deferred.isDone(stopOutput))
                if (done) {
                  const [code] = yield* Deferred.await(exited)
                  if (process.platform === "win32") return
                  if (code === 0 || Predicate.isNull(code)) return
                  if (command.options.forceKillAfter === undefined) {
                    return yield* Effect.ignore(killGroup(command, proc, command.options.killSignal ?? "SIGTERM"))
                  }
                }
                yield* Effect.ignore(stop(command, proc, closed, stopOutput, command.options))
              },
              (effect, [proc, , , stopOutput]) =>
                effect.pipe(
                  Effect.ensuring(
                    Effect.gen(function* () {
                      yield* Deferred.succeed(stopOutput, undefined)
                      proc.stdout?.destroy()
                      proc.stderr?.destroy()
                    }),
                  ),
                ),
            ),
          )

          const completion = Effect.raceFirst(
            Deferred.await(closed),
            Deferred.await(stopOutput).pipe(Effect.andThen(Deferred.await(exited))),
          )
          const fd = yield* setupFds(command, proc, extra)
          const out = setupOutput(command, proc, sout, serr, stopOutput)
          let ref = true
          return makeHandle({
            pid: ProcessId(proc.pid!),
            stdin: yield* setupStdin(command, proc, sin),
            stdout: out.stdout,
            stderr: out.stderr,
            all: out.all,
            getInputFd: fd.getInputFd,
            getOutputFd: fd.getOutputFd,
            isRunning: Effect.gen(function* () {
              return !(yield* Deferred.isDone(closed)) && !(yield* Deferred.isDone(stopOutput))
            }),
            exitCode: Effect.flatMap(completion, ([code, signal]) => {
              if (Predicate.isNotNull(code)) return Effect.succeed(ExitCode(code))
              // Node reports a signal whenever the exit code is null.
              return Effect.fail(toPlatformError("exitCode", new KilledBySignal(signal!), command))
            }),
            kill: (opts?: ChildProcess.KillOptions) => stop(command, proc, closed, stopOutput, opts),
            unref: Effect.sync(() => {
              if (ref) {
                proc.unref()
                ref = false
              }
              return Effect.sync(() => {
                if (!ref) {
                  proc.ref()
                  ref = true
                }
              })
            }),
          })
        }
        case "PipedCommand": {
          const flat = flatten(command)
          const [head, ...tail] = flat.commands
          let handle = spawnCommand(head)
          for (let i = 0; i < tail.length; i++) {
            const next = tail[i]
            const opts = flat.opts[i] ?? {}
            const sin = stdin(next.options)
            const stream = Stream.unwrap(Effect.map(handle, (x) => source(x, opts.from)))
            const to = opts.to ?? "stdin"
            if (to === "stdin") {
              handle = spawnCommand(
                ChildProcess.make(next.command, next.args, {
                  ...next.options,
                  stdin: { ...sin, stream },
                }),
              )
              continue
            }
            const fd = ChildProcess.parseFdName(to)
            if (Predicate.isUndefined(fd)) {
              handle = spawnCommand(
                ChildProcess.make(next.command, next.args, {
                  ...next.options,
                  stdin: { ...sin, stream },
                }),
              )
              continue
            }
            handle = spawnCommand(
              ChildProcess.make(next.command, next.args, {
                ...next.options,
                additionalFds: {
                  ...next.options.additionalFds,
                  [ChildProcess.fdName(fd) as `fd${number}`]: { type: "input", stream },
                },
              }),
            )
          }
          return yield* handle
        }
      }
    },
  )

  return make(spawnCommand)
})

const layer: Layer.Layer<ChildProcessSpawner, never, FileSystem.FileSystem | Path.Path> = Layer.effect(
  ChildProcessSpawner,
  makeCrossSpawnSpawner,
)

export const node = makeGlobalNode({ service: ChildProcessSpawner, layer, deps: [filesystem, path] })

export * as CrossSpawnSpawner from "./cross-spawn-spawner.js"

import path from "path"
import os from "os"
import { randomUUID } from "crypto"
import { Context, Effect, Function, Layer, Option, Schedule, Schema } from "effect"
import type { FileSystem, Scope } from "effect"
import type { PlatformError } from "effect/PlatformError"
import { FSUtil } from "./fs-util.js"
import { Global } from "./global.js"
import { makeGlobalNode } from "./effect/app-node.js"
import { Hash } from "./hash.js"

export namespace EffectFlock {
  // ---------------------------------------------------------------------------
  // Errors
  // ---------------------------------------------------------------------------

  export class LockTimeoutError extends Schema.TaggedError<LockTimeoutError>()("LockTimeoutError", {
    key: Schema.String,
  }) {}

  export class LockCompromisedError extends Schema.TaggedError<LockCompromisedError>()("LockCompromisedError", {
    detail: Schema.String,
  }) {}

  class ReleaseError extends Schema.TaggedError<ReleaseError>()("ReleaseError", {
    detail: Schema.String,
    cause: Schema.optional(Schema.Defect()),
  }) {
    override get message() {
      return this.detail
    }
  }

  /** Internal: signals "lock is held, retry later". Never leaks to callers. */
  class NotAcquired extends Schema.TaggedError<NotAcquired>()("NotAcquired", {}) {}

  export type LockError = LockTimeoutError | LockCompromisedError

  export interface Options {
    readonly staleMs?: number
    readonly timeoutMs?: number
  }

  // ---------------------------------------------------------------------------
  // Timing defaults
  // ---------------------------------------------------------------------------

  const DEFAULT_STALE_MS = 60_000
  const DEFAULT_TIMEOUT_MS = 5 * 60_000
  const BASE_DELAY_MS = 100
  const MAX_DELAY_MS = 2_000

  const retrySchedule = (timeoutMs: number) =>
    Schedule.min([
      Schedule.exponential(BASE_DELAY_MS, 1.7),
      Schedule.spaced(Math.min(MAX_DELAY_MS, Math.max(BASE_DELAY_MS, Math.floor(timeoutMs / 10)))),
    ]).pipe(
      Schedule.jittered,
      Schedule.while((meta) => meta.elapsed < timeoutMs),
    )

  // ---------------------------------------------------------------------------
  // Lock metadata schema
  // ---------------------------------------------------------------------------

  const LockMetaJson = Schema.fromJsonString(
    Schema.Struct({
      token: Schema.String,
      pid: Schema.Number,
      hostname: Schema.String,
      createdAt: Schema.String,
    }),
  )

  const decodeMeta = Schema.decodeUnknownSync(LockMetaJson)
  const encodeMeta = Schema.encodeSync(LockMetaJson)

  // ---------------------------------------------------------------------------
  // Service
  // ---------------------------------------------------------------------------

  export interface Interface {
    readonly acquire: (key: string, dir?: string, options?: Options) => Effect.Effect<void, LockError, Scope.Scope>
    readonly withLock: {
      (key: string, dir?: string): <A, E, R>(body: Effect.Effect<A, E, R>) => Effect.Effect<A, E | LockError, R>
      <A, E, R>(body: Effect.Effect<A, E, R>, key: string, dir?: string): Effect.Effect<A, E | LockError, R>
    }
  }

  export class Service extends Context.Service<Service, Interface>()("EffectFlock") {}

  // ---------------------------------------------------------------------------
  // Layer
  // ---------------------------------------------------------------------------

  function wall() {
    return performance.timeOrigin + performance.now()
  }

  const mtimeMs = (info: FileSystem.File.Info) => Option.getOrElse(info.mtime, () => new Date(0)).getTime()

  const isPathGone = (e: PlatformError) => e.reason._tag === "NotFound" || e.reason._tag === "Unknown"

  const layer: Layer.Layer<Service, never, Global.Service | FSUtil.Service> = Layer.effect(
    Service,
    Effect.gen(function* () {
      const global = yield* Global.Service
      const fs = yield* FSUtil.Service
      const lockRoot = path.join(global.state, "locks")
      const hostname = os.hostname()
      const ensuredDirs = new Set<string>()

      // -- helpers (close over fs) --

      const safeStat = (file: string) =>
        fs.stat(file).pipe(
          Effect.catchIf(isPathGone, () => Effect.void),
          Effect.orDie,
        )

      const forceRemove = (target: string) => fs.remove(target, { recursive: true }).pipe(Effect.ignore)

      /** Atomic mkdir — returns true if created, false if already exists, dies on other errors. */
      const atomicMkdir = (dir: string) =>
        fs.makeDirectory(dir, { mode: 0o700 }).pipe(
          Effect.as(true),
          Effect.catchIf(
            (e) => e.reason._tag === "AlreadyExists",
            () => Effect.succeed(false),
          ),
          Effect.orDie,
        )

      /** Write with exclusive create — compromised error if file already exists. */
      const exclusiveWrite = (filePath: string, content: string, lockDir: string, detail: string) =>
        fs.writeFileString(filePath, content, { flag: "wx" }).pipe(
          Effect.catch(() =>
            Effect.gen(function* () {
              yield* forceRemove(lockDir)
              return yield* new LockCompromisedError({ detail })
            }),
          ),
        )

      const cleanStaleBreaker = Effect.fnUntraced(function* (breakerPath: string, staleMs: number) {
        const bs = yield* safeStat(breakerPath)
        if (bs && wall() - mtimeMs(bs) > staleMs) yield* forceRemove(breakerPath)
        return false
      })

      const ensureDir = Effect.fnUntraced(function* (dir: string) {
        if (ensuredDirs.has(dir)) return
        yield* fs.makeDirectory(dir, { recursive: true }).pipe(Effect.orDie)
        ensuredDirs.add(dir)
      })

      const isStale = Effect.fnUntraced(function* (
        lockDir: string,
        heartbeatPath: string,
        metaPath: string,
        staleMs: number,
      ) {
        const now = wall()

        const hb = yield* safeStat(heartbeatPath)
        if (hb) return now - mtimeMs(hb) > staleMs

        const meta = yield* safeStat(metaPath)
        if (meta) return now - mtimeMs(meta) > staleMs

        const dir = yield* safeStat(lockDir)
        if (!dir) return false

        return now - mtimeMs(dir) > staleMs
      })

      // -- single lock attempt --

      type Handle = { token: string; metaPath: string; heartbeatPath: string; lockDir: string }

      const tryAcquireLockDir = (lockDir: string, key: string, staleMs: number) =>
        Effect.gen(function* () {
          const token = randomUUID()
          const metaPath = path.join(lockDir, "meta.json")
          const heartbeatPath = path.join(lockDir, "heartbeat")

          // Atomic mkdir — the POSIX lock primitive
          const created = yield* atomicMkdir(lockDir)

          if (!created) {
            if (!(yield* isStale(lockDir, heartbeatPath, metaPath, staleMs))) return yield* new NotAcquired()

            // Stale — race for breaker ownership
            const breakerPath = lockDir + ".breaker"

            const claimed = yield* fs.makeDirectory(breakerPath, { mode: 0o700 }).pipe(
              Effect.as(true),
              Effect.catchIf(
                (e) => e.reason._tag === "AlreadyExists",
                () => cleanStaleBreaker(breakerPath, staleMs),
              ),
              Effect.catchIf(isPathGone, () => Effect.succeed(false)),
              Effect.orDie,
            )

            if (!claimed) return yield* new NotAcquired()

            // We own the breaker — double-check staleness, nuke, recreate
            const recreated = yield* Effect.gen(function* () {
              if (!(yield* isStale(lockDir, heartbeatPath, metaPath, staleMs))) return false
              yield* forceRemove(lockDir)
              return yield* atomicMkdir(lockDir)
            }).pipe(Effect.ensuring(forceRemove(breakerPath)))

            if (!recreated) return yield* new NotAcquired()
          }

          // We own the lock dir — write heartbeat + meta with exclusive create
          yield* exclusiveWrite(heartbeatPath, "", lockDir, "heartbeat already existed")

          const metaJson = encodeMeta({ token, pid: process.pid, hostname, createdAt: new Date().toISOString() })
          yield* exclusiveWrite(metaPath, metaJson, lockDir, "meta.json already existed")

          return { token, metaPath, heartbeatPath, lockDir } satisfies Handle
        }).pipe(
          Effect.withSpan("EffectFlock.tryAcquire", {
            attributes: { key },
          }),
        )

      // -- retry wrapper (preserves Handle type) --

      const acquireHandle = (
        lockfile: string,
        key: string,
        options: { staleMs: number; timeoutMs: number },
      ): Effect.Effect<Handle, LockError> =>
        tryAcquireLockDir(lockfile, key, options.staleMs).pipe(
          Effect.retry({
            while: (err) => err._tag === "NotAcquired",
            schedule: retrySchedule(options.timeoutMs),
          }),
          Effect.catchTag("NotAcquired", () => Effect.fail(new LockTimeoutError({ key }))),
          Effect.timeoutOrElse({
            duration: options.timeoutMs,
            orElse: () => Effect.fail(new LockTimeoutError({ key })),
          }),
        )

      // -- release --

      const release = (handle: Handle) =>
        Effect.gen(function* () {
          const raw = yield* fs.readFileString(handle.metaPath).pipe(
            Effect.catch((err) => {
              if (isPathGone(err)) return Effect.die(new ReleaseError({ detail: "metadata missing" }))
              return Effect.die(err)
            }),
          )

          const parsed = yield* Effect.try({
            try: () => decodeMeta(raw),
            catch: (cause) => new ReleaseError({ detail: "metadata invalid", cause }),
          }).pipe(Effect.orDie)

          if (parsed.token !== handle.token) return yield* Effect.die(new ReleaseError({ detail: "token mismatch" }))

          yield* forceRemove(handle.lockDir)
        })

      // -- build service --

      const acquire = Effect.fn("EffectFlock.acquire")(function* (key: string, dir?: string, options: Options = {}) {
        const lockDir = dir ?? lockRoot
        const staleMs = options.staleMs ?? DEFAULT_STALE_MS
        const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS
        yield* ensureDir(lockDir)

        const lockfile = path.join(lockDir, Hash.fast(key) + ".lock")

        // acquireRelease: acquire is uninterruptible, release is guaranteed
        const handle = yield* Effect.acquireRelease(acquireHandle(lockfile, key, { staleMs, timeoutMs }), (handle) =>
          release(handle),
        )

        // Heartbeat fiber — scoped, so it's interrupted before release runs
        yield* Effect.suspend(() => {
          const now = new Date()
          return fs.utimes(handle.heartbeatPath, now, now)
        }).pipe(
          Effect.ignore,
          Effect.repeat(Schedule.spaced(Math.max(100, Math.floor(staleMs / 3)))),
          Effect.forkScoped,
        )
      })

      const withLock: Interface["withLock"] = Function.dual(
        (args) => Effect.isEffect(args[0]),
        <A, E, R>(body: Effect.Effect<A, E, R>, key: string, dir?: string): Effect.Effect<A, E | LockError, R> =>
          Effect.scoped(
            Effect.gen(function* () {
              yield* acquire(key, dir)
              return yield* body
            }),
          ),
      )

      return Service.of({ acquire, withLock })
    }),
  )

  export const node = makeGlobalNode({ service: Service, layer: layer, deps: [Global.node, FSUtil.node] })
}

import { Brand, Context, Effect, Layer, type Scope } from "effect"

export * as LayerNode from "./layer-node.js"

const GraphTypeId = Symbol("LayerNode.Graph")
const VarianceTypeId = Symbol("LayerNode.Variance")
const NodeTypeId = Symbol("LayerNode.Node")
const ReplacementTypeId = Symbol("LayerNode.Replacement")

export type Tag<Name extends string = string> = Name & Brand.Brand<"LayerNode.Tag">
const makeTag = Brand.nominal<Tag>()

export type Graph<A, E = never, T extends Tag | undefined = Tag | undefined> = GraphValue<A, E, T>
export type Node<A, E = never, T extends Tag | undefined = undefined> = NodeValue<A, E, T>
export type Provider<A, E = never, T extends Tag | undefined = undefined> = ProviderNode<A, E, T>
export type Replacement = ReplacementValue
export type Replacements = readonly Replacement[]

type AnyGraph = Graph<never, unknown>
type AnyNode = AnyGraph & { readonly [NodeTypeId]: unknown; readonly tag: Tag | undefined }
type RuntimeLayer = Layer.Layer<never, unknown, unknown>
type GraphList = readonly [] | readonly [AnyGraph, ...AnyGraph[]]

export type Output<Item> = CommonOutput<Item, Item extends Graph<infer A, unknown> ? A : never>
export type Error<Item> = Item extends Graph<never, infer E> ? E : never
type GraphTag<Item> = [Item] extends [never] ? undefined : Item extends Graph<never, unknown, infer T> ? T : never
type CommonOutput<Item, A> = A extends unknown ? ([Item] extends [Graph<A, unknown>] ? A : never) : never
type LayerOutput<Item extends Layer.Any, A = Layer.Success<Item>> = A extends unknown
  ? [Item] extends [Layer.Layer<A, unknown, unknown>]
    ? A
    : never
  : never
type ListOutput<Items extends readonly AnyGraph[], A = never> = [Items] extends [
  readonly [infer Head extends AnyGraph, ...infer Tail extends readonly AnyGraph[]],
]
  ? ListOutput<Tail, A | Output<Head>>
  : A

type Definition =
  | { readonly kind: "group"; readonly name: string; readonly dependencies: readonly AnyGraph[] }
  | { readonly kind: "unbound"; readonly name: string }
  | {
      readonly kind: "layer"
      readonly name: string
      readonly implementation: RuntimeLayer
      readonly dependencies: readonly AnyGraph[]
    }

class GraphValue<in A, out E, out T extends Tag | undefined> {
  declare private readonly graph: void
  // Public symbol types survive declaration emit; the private brand prevents structural forgery.
  declare readonly [VarianceTypeId]: {
    readonly output: (_: A) => void
    readonly error: () => E
    readonly tags: () => T
  }

  readonly [GraphTypeId]: Definition

  constructor(definition: Definition) {
    this[GraphTypeId] = definition
  }

  get name() {
    return this[GraphTypeId].name
  }
}

class NodeValue<in out A, in out E, in out T extends Tag | undefined> extends GraphValue<A, E, T> {
  // Forgetting part of a node's contract must not authorize a weaker replacement.
  declare readonly [NodeTypeId]: (_: [A, E, T]) => [A, E, T]

  constructor(
    definition: Exclude<Definition, { kind: "group" }>,
    readonly tag: T,
  ) {
    super(definition)
  }

  /** Replace this declaration, including every dependency on it, without acquiring its old wiring. */
  replace<const Target extends AnyNode | Layer.Any>(
    this: Node<A, E, T>,
    replacement: Target & CheckReplacement<A, E, T, Target>,
  ): Replacement {
    if (replacement instanceof NodeValue) {
      if (replacement.tag !== this.tag) throw new Error(`Cannot replace ${this.name} across tags`)
      return new ReplacementValue(this, replacement)
    }
    if (!Layer.isLayer(replacement)) throw new Error("A replacement must be a node or an Effect Layer")
    return new ReplacementValue(this, makeProvider({ name: this.name, layer: replacement, deps: [] }, this.tag))
  }
}

class ProviderNode<in out A, in out E, in out T extends Tag | undefined> extends NodeValue<A, E, T> {
  /** Decorate the implementation while preserving its dependency wiring and service contract. */
  mapLayer(this: Provider<A, E, T>, f: <R>(layer: Layer.Layer<A, E, R>) => Layer.Layer<A, E, R>): Provider<A, E, T> {
    const definition = this[GraphTypeId]
    if (definition.kind !== "layer") throw new Error(`Cannot map unbound layer node: ${this.name}`)
    return new ProviderNode(
      { ...definition, implementation: f(definition.implementation as Layer.Layer<A, E, unknown>) },
      this.tag,
    )
  }
}

class ReplacementValue {
  declare private readonly checked: void
  readonly [ReplacementTypeId]: { readonly source: AnyNode; readonly target: AnyNode }

  constructor(source: AnyNode, target: AnyNode) {
    this[ReplacementTypeId] = { source, target }
  }
}

type CheckErrors<Expected, Actual> = [Exclude<Actual, Expected>] extends [never]
  ? never
  : { readonly "New replacement errors": Exclude<Actual, Expected> }

type CheckReplacement<A, E, T, Target> = [ReplacementErrors<A, E, T, Target>] extends [never]
  ? unknown
  : ReplacementErrors<A, E, T, Target>

type ReplacementErrors<A, E, T, Target> = Target extends AnyNode
  ? [Exclude<A, Output<Target>>] extends [never]
    ? [GraphTag<Target>] extends [T]
      ? CheckErrors<E, Error<Target>>
      : { readonly "Invalid replacement tag": GraphTag<Target> }
    : { readonly "Missing replacement outputs": Exclude<A, Output<Target>> }
  : Target extends Layer.Layer<A, infer E2, never>
    ? CheckErrors<E, E2>
    : { readonly "Replacement must be a closed layer": Target }

type CheckDependencies<Implementation extends Layer.Any, Items extends GraphList> = [
  Exclude<Layer.Services<Implementation>, ListOutput<Items>>,
] extends [never]
  ? unknown
  : { readonly "Missing dependencies": Exclude<Layer.Services<Implementation>, ListOutput<Items>> }

type Identity =
  | { readonly service: Context.Service.Any; readonly name?: never }
  | { readonly name: string; readonly service?: never }
type CheckLayer<Implementation> = [Implementation] extends [RuntimeLayer]
  ? unknown
  : { readonly "Layer contract must be preserved": Implementation }
type TagInput<T> = { readonly tag: T } | ([T] extends [undefined] ? { readonly tag?: undefined } : never)
type MakeInput<Implementation extends Layer.Any, Items extends GraphList, T extends Tag | undefined> = Identity &
  TagInput<T> & {
    readonly layer: Implementation & CheckLayer<NoInfer<Implementation>>
    readonly deps: Items & CheckDependencies<Implementation, NoInfer<Items>>
  }
type DistributiveOmit<A, K extends PropertyKey> = A extends unknown ? Omit<A, K> : never

export type TagConfig = Readonly<Record<string, readonly string[]>>
type TagNames<Config extends TagConfig> = keyof Config & string
type CheckTags<Items extends GraphList, Names extends string> = [
  Exclude<GraphTag<Items[number]>, Tag<Names> | undefined>,
] extends [never]
  ? unknown
  : { readonly "Invalid tag dependencies": Exclude<GraphTag<Items[number]>, Tag<Names> | undefined> }

export interface Tags<Config extends TagConfig> {
  readonly values: { readonly [Name in TagNames<Config>]: Tag<Name> }
  readonly make: <Name extends TagNames<Config>>(
    name: Name,
  ) => <const Implementation extends Layer.Any, const Items extends GraphList>(
    input: DistributiveOmit<MakeInput<Implementation, Items, Tag<Name>>, "tag"> &
      CheckTags<Items, Name | Extract<Config[Name][number], string>>,
  ) => Provider<LayerOutput<Implementation>, Layer.Error<Implementation> | Error<Items[number]>, Tag<Name>>
}

export function tags<const Config extends { readonly [Name in keyof Config]: readonly (keyof Config & string)[] }>(
  config: Config,
): Tags<Config> {
  const names = Object.keys(config) as TagNames<Config>[]
  const values = Object.fromEntries(names.map((name) => [name, makeTag(name)])) as Tags<Config>["values"]
  return {
    values,
    make:
      <Name extends TagNames<Config>>(name: Name) =>
      <const Implementation extends Layer.Any, const Items extends GraphList>(
        input: DistributiveOmit<MakeInput<Implementation, Items, Tag<Name>>, "tag"> &
          CheckTags<Items, Name | Extract<Config[Name][number], string>>,
      ) =>
        makeProvider<Implementation, Items, Tag<Name>>(input, values[name]),
  }
}

export function make<
  const Implementation extends Layer.Any,
  const Items extends GraphList,
  const T extends Tag | undefined = undefined,
>(
  input: MakeInput<Implementation, Items, T>,
): Provider<LayerOutput<Implementation>, Layer.Error<Implementation> | Error<Items[number]>, T> {
  return makeProvider<Implementation, Items, T>(input, input.tag as T)
}

function makeProvider<Implementation extends Layer.Any, Items extends readonly AnyGraph[], T extends Tag | undefined>(
  input: Identity & { readonly layer: Implementation; readonly deps: Items },
  tag: T,
): Provider<LayerOutput<Implementation>, Layer.Error<Implementation> | Error<Items[number]>, T> {
  if (!Layer.isLayer(input.layer)) throw new Error("A layer node requires an Effect Layer")
  return new ProviderNode(
    {
      kind: "layer",
      name: input.service !== undefined ? input.service.key : input.name,
      implementation: input.layer,
      dependencies: [...input.deps],
    },
    tag,
  )
}

export function unbound<R, Shape, const T extends Tag>(service: Context.Key<R, Shape>, tag: T): Node<R, never, T> {
  return new NodeValue({ kind: "unbound", name: service.key }, tag)
}

/** Ordered, associative composition. Only these roots' outputs are exposed; their dependencies remain private. */
export function group<const Items extends readonly AnyGraph[]>(
  dependencies: Items,
): Graph<ListOutput<Items>, Error<Items[number]>, GraphTag<Items[number]>> {
  return new GraphValue({ kind: "group", name: "group", dependencies: [...dependencies] })
}

export interface CompileOptions {
  readonly replacements?: Replacements
  /** Share subgraphs rooted at this tag; give the remaining wiring a fresh map for each build. */
  readonly shared?: Tag
}

type Resolved = {
  readonly implementation: RuntimeLayer
  readonly dependencies: readonly Resolved[]
  readonly shared: boolean
}

/** Resolve the final overrides before validating or acquiring anything. Effect owns acquisition and finalization. */
export function compile<A, E>(root: Graph<A, E>, options: CompileOptions = {}): Layer.Layer<A, E> {
  const shared = options.shared
  const replacements = new Map<AnyGraph, AnyNode>(
    options.replacements?.map((item) => {
      const replacement = item[ReplacementTypeId]
      return [replacement.source, replacement.target] as const
    }),
  )
  const cache = {
    shared: new Map<AnyGraph, readonly Resolved[]>(),
    local: new Map<AnyGraph, readonly Resolved[]>(),
  }
  const stack: AnyGraph[] = []
  const definitions = { shared: new Map<RuntimeLayer, Resolved>(), local: new Map<RuntimeLayer, Resolved>() }

  const resolve = (graph: AnyGraph, inherited = false): readonly Resolved[] => {
    const definition = graph[GraphTypeId]
    const isShared = inherited || (shared !== undefined && graph instanceof NodeValue && graph.tag === shared)
    const resolved = isShared ? cache.shared : cache.local
    const cached = resolved.get(graph)
    if (cached) return cached
    const cycle = stack.indexOf(graph)
    if (cycle !== -1) {
      throw new Error(
        `Cycle detected in layer graph: ${[...stack.slice(cycle), graph].map((item) => item.name).join(" -> ")}`,
      )
    }
    stack.push(graph)
    const replacement = replacements.get(graph)
    const result = (() => {
      if (replacement && replacement !== graph) return resolve(replacement, isShared)
      if (definition.kind === "group")
        return definition.dependencies.flatMap((dependency) => resolve(dependency, isShared))
      if (definition.kind === "unbound") throw new Error(`Unbound layer node: ${definition.name}`)
      const node: Resolved = {
        implementation: definition.implementation,
        dependencies: definition.dependencies.flatMap((dependency) => resolve(dependency, isShared)),
        shared: isShared,
      }
      const registry = node.shared ? definitions.shared : definitions.local
      const existing = registry.get(node.implementation)
      if (existing) {
        if (
          existing.dependencies.length !== node.dependencies.length ||
          existing.dependencies.some((dependency, index) => dependency !== node.dependencies[index])
        ) {
          throw new Error(
            `Layer ${definition.name} is wired to different dependencies; use a distinct implementation Layer`,
          )
        }
        return [existing]
      }
      registry.set(node.implementation, node)
      return [node]
    })()
    stack.pop()
    resolved.set(graph, result)
    return result
  }

  const roots = resolve(root)
  return Layer.fromBuild((memoMap, scope) => {
    const local = shared === undefined ? memoMap : Layer.makeMemoMapUnsafe()
    const ambient = Layer.succeed(Layer.CurrentMemoMap, memoMap)
    const layers = new Map<Resolved, RuntimeLayer>()
    const build = (node: Resolved): RuntimeLayer => {
      const cached = layers.get(node)
      if (cached) return cached
      const dependencies = node.dependencies.map(build)
      // Acquisition uses the selected cache, while lazy LayerMaps inherit the enclosing shared cache.
      const implementation = Layer.suspend(() => node.implementation.pipe(Layer.provide([ambient, ...dependencies])))
      const layer = Layer.fromBuild((_, scope) => buildContext(implementation, node.shared ? memoMap : local, scope))
      layers.set(node, layer)
      return layer
    }
    return buildContext(
      roots.map(build).reduce<RuntimeLayer>((result, layer) => layer.pipe(Layer.provideMerge(result)), Layer.empty),
      memoMap,
      scope,
    )
  }) as Layer.Layer<A, E>
}

class BuildResult extends Context.Service<BuildResult, Context.Context<never>>()("@opencode/LayerNode/BuildResult") {}

function buildContext(layer: RuntimeLayer, memoMap: Layer.MemoMap, scope: Scope.Scope) {
  // Preserve the exact output context before Effect appends its own memo-map metadata.
  return Layer.buildWithMemoMap(
    layer.pipe(Layer.flatMap((context) => Layer.succeed(BuildResult, context))),
    memoMap,
    scope,
  ).pipe(Effect.map(Context.get(BuildResult)))
}

import { Layer, type Context, ManagedRuntime, type Effect } from "effect"
import { memoMap } from "./memo-map.js"
import { Observability } from "../observability.js"

export function makeRuntime<I, S, E>(service: Context.Service<I, S>, layer: Layer.Layer<I, E>) {
  let rt: ManagedRuntime.ManagedRuntime<I, E> | undefined
  const getRuntime = () =>
    (rt ??= ManagedRuntime.make(Layer.provideMerge(layer, Observability.layer()) as Layer.Layer<I, E>, {
      memoMap,
    }))

  return {
    runSync: <A, Err>(fn: (svc: S) => Effect.Effect<A, Err, I>) => getRuntime().runSync(service.use(fn)),
    runPromiseExit: <A, Err>(fn: (svc: S) => Effect.Effect<A, Err, I>, options?: Effect.RunOptions) =>
      getRuntime().runPromiseExit(service.use(fn), options),
    runPromise: <A, Err>(fn: (svc: S) => Effect.Effect<A, Err, I>, options?: Effect.RunOptions) =>
      getRuntime().runPromise(service.use(fn), options),
    runFork: <A, Err>(fn: (svc: S) => Effect.Effect<A, Err, I>) => getRuntime().runFork(service.use(fn)),
    runCallback: <A, Err>(fn: (svc: S) => Effect.Effect<A, Err, I>) => getRuntime().runCallback(service.use(fn)),
  }
}

import { Context, Effect } from "effect"

type EffectMethod = (...args: ReadonlyArray<never>) => Effect.Effect<unknown, unknown, unknown>

type ServiceUse<Identifier, Shape> = {
  readonly [Key in keyof Shape as Shape[Key] extends EffectMethod ? Key : never]: Shape[Key] extends (
    ...args: infer Args
  ) => infer Return
    ? Args extends ReadonlyArray<unknown>
      ? Return extends Effect.Effect<infer A, infer E, infer R>
        ? (...args: Args) => Effect.Effect<A, E, R | Identifier>
        : never
      : never
    : never
}

export const serviceUse = <Identifier, Shape>(tag: Context.Service<Identifier, Shape>) => {
  const cache = new Map<string, (...args: unknown[]) => Effect.Effect<unknown, unknown, unknown>>()
  // This is the only dynamic boundary: TypeScript knows the accessor shape,
  // but Proxy property names are runtime values.
  const access = new Proxy(
    {},
    {
      get: (_, key) => {
        if (typeof key !== "string") return undefined
        const cached = cache.get(key)
        if (cached) return cached
        const accessor = (...args: unknown[]) =>
          tag.use((service) => {
            // oxlint-disable-next-line typescript-eslint/no-unsafe-type-assertion -- Proxy keys are checked at runtime.
            const method = service[key as keyof Shape]
            if (typeof method !== "function") return Effect.die(new Error(`Service method not found: ${key}`))
            // oxlint-disable-next-line typescript-eslint/no-unsafe-type-assertion -- ServiceUse exposes only Effect-returning methods.
            return (method as (...args: unknown[]) => Effect.Effect<unknown, unknown, unknown>)(...args)
          })
        cache.set(key, accessor)
        return accessor
      },
    },
  )
  // oxlint-disable-next-line typescript-eslint/no-unsafe-type-assertion -- Proxy implements the mapped accessor surface lazily.
  return access as ServiceUse<Identifier, Shape>
}

import { describe, expect, test } from "bun:test"
import { base64Decode, base64Encode, checksum, sampledChecksum } from "./encode.js"

describe("frontend encoding", () => {
  test("uses unpadded URL-safe UTF-8 base64", () => {
    expect(base64Encode("hello")).toBe("aGVsbG8")
    expect(base64Encode("✓ à la mode")).toBe("4pyTIMOgIGxhIG1vZGU")
    expect(base64Decode("4pyTIMOgIGxhIG1vZGU")).toBe("✓ à la mode")
    expect(base64Decode("dXNlcjpwYXNz")).toBe("user:pass")
  })

  test("rejects invalid base64", () => {
    expect(() => base64Decode("%%%")).toThrow()
  })

  test("keeps stable FNV checksums", () => {
    expect(checksum("")).toBeUndefined()
    expect(checksum("hello")).toBe("m3bicr")
    expect(checksum("✓ à la mode")).toBe("jmczk0")
  })

  test("samples large values without changing the size boundary", () => {
    const value = "abcdef".repeat(100)
    expect(sampledChecksum(value, value.length)).toBe(checksum(value))
    expect(sampledChecksum(value, value.length - 1)).toBe("600:1isj1k5:1isj1k5:1isj1k5:1isj1k5:1isj1k5")
  })
})

export function base64Encode(value: string) {
  const bytes = new TextEncoder().encode(value)
  const binary = Array.from(bytes, (byte) => String.fromCharCode(byte)).join("")
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=/g, "")
}

export function base64Decode(value: string) {
  const binary = atob(value.replace(/-/g, "+").replace(/_/g, "/"))
  return new TextDecoder().decode(Uint8Array.from(binary, (character) => character.charCodeAt(0)))
}

export function checksum(content: string): string | undefined {
  if (!content) return
  let hash = 0x811c9dc5
  for (let index = 0; index < content.length; index++) {
    hash ^= content.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193)
  }
  return (hash >>> 0).toString(36)
}

export function sampledChecksum(content: string, limit = 500_000): string | undefined {
  if (!content) return
  if (content.length <= limit) return checksum(content)

  const size = 4096
  return `${content.length}:${[
    0,
    Math.floor(content.length * 0.25),
    Math.floor(content.length * 0.5),
    Math.floor(content.length * 0.75),
    content.length - size,
  ]
    .map((point) => {
      const start = Math.max(0, Math.min(content.length - size, point - Math.floor(size / 2)))
      return checksum(content.slice(start, start + size)) ?? ""
    })
    .join(":")}`
}

import path from "path"
import os from "os"
import { randomBytes, randomUUID } from "crypto"
import { mkdir, readFile, rm, stat, utimes, writeFile } from "fs/promises"
import { Hash } from "./hash.js"
import { Effect } from "effect"

export type FlockGlobal = {
  state: string
}

export namespace Flock {
  let global: FlockGlobal | undefined

  export function setGlobal(g: FlockGlobal) {
    global = g
  }

  const root = () => {
    if (!global) throw new Error("Flock global not set")
    return path.join(global.state, "locks")
  }

  // Defaults for callers that do not provide timing options.
  const defaultOpts = {
    staleMs: 60_000,
    timeoutMs: 5 * 60_000,
    baseDelayMs: 100,
    maxDelayMs: 2_000,
  }

  export interface WaitEvent {
    key: string
    attempt: number
    delay: number
    waited: number
  }

  export type Wait = (input: WaitEvent) => void | Promise<void>

  export interface Options {
    dir?: string
    signal?: AbortSignal
    staleMs?: number
    timeoutMs?: number
    baseDelayMs?: number
    maxDelayMs?: number
    onWait?: Wait
  }

  type Opts = {
    staleMs: number
    timeoutMs: number
    baseDelayMs: number
    maxDelayMs: number
  }

  type Owned = {
    acquired: true
    startHeartbeat: (intervalMs?: number) => void
    release: () => Promise<void>
  }

  export interface Lease {
    release: () => Promise<void>
    [Symbol.asyncDispose]: () => Promise<void>
  }

  function code(err: unknown) {
    if (typeof err !== "object" || err === null || !("code" in err)) return
    const value = err.code
    if (typeof value !== "string") return
    return value
  }

  function sleep(ms: number, signal?: AbortSignal) {
    return new Promise<void>((resolve, reject) => {
      if (signal?.aborted) {
        reject(signal.reason ?? new Error("Aborted"))
        return
      }

      let timer: NodeJS.Timeout | undefined

      const done = () => {
        signal?.removeEventListener("abort", abort)
        resolve()
      }

      const abort = () => {
        if (timer) {
          clearTimeout(timer)
        }
        signal?.removeEventListener("abort", abort)
        reject(signal?.reason ?? new Error("Aborted"))
      }

      signal?.addEventListener("abort", abort, { once: true })
      timer = setTimeout(done, ms)
    })
  }

  function jitter(ms: number) {
    const j = Math.floor(ms * 0.3)
    const d = Math.floor(Math.random() * (2 * j + 1)) - j
    return Math.max(0, ms + d)
  }

  function mono() {
    return performance.now()
  }

  function wall() {
    return performance.timeOrigin + mono()
  }

  async function stats(file: string) {
    try {
      return await stat(file)
    } catch (err) {
      const errCode = code(err)
      if (errCode === "ENOENT" || errCode === "ENOTDIR") return
      throw err
    }
  }

  async function stale(lockDir: string, heartbeatPath: string, metaPath: string, staleMs: number) {
    // Stale detection allows automatic recovery after crashed owners.
    const now = wall()
    const heartbeat = await stats(heartbeatPath)
    if (heartbeat) {
      return now - heartbeat.mtimeMs > staleMs
    }

    const meta = await stats(metaPath)
    if (meta) {
      return now - meta.mtimeMs > staleMs
    }

    const dir = await stats(lockDir)
    if (!dir) {
      return false
    }

    return now - dir.mtimeMs > staleMs
  }

  async function tryAcquireLockDir(lockDir: string, opts: Opts): Promise<Owned | { acquired: false }> {
    const token = randomUUID?.() ?? randomBytes(16).toString("hex")
    const metaPath = path.join(lockDir, "meta.json")
    const heartbeatPath = path.join(lockDir, "heartbeat")

    try {
      await mkdir(lockDir, { mode: 0o700 })
    } catch (err) {
      if (code(err) !== "EEXIST") {
        throw err
      }

      if (!(await stale(lockDir, heartbeatPath, metaPath, opts.staleMs))) {
        return { acquired: false }
      }

      const breakerPath = lockDir + ".breaker"
      try {
        await mkdir(breakerPath, { mode: 0o700 })
      } catch (claimErr) {
        const errCode = code(claimErr)
        if (errCode === "EEXIST") {
          const breaker = await stats(breakerPath)
          if (breaker && wall() - breaker.mtimeMs > opts.staleMs) {
            await rm(breakerPath, { recursive: true, force: true }).catch(() => undefined)
          }
          return { acquired: false }
        }

        if (errCode === "ENOENT" || errCode === "ENOTDIR") {
          return { acquired: false }
        }

        throw claimErr
      }

      try {
        // Breaker ownership ensures only one contender performs stale cleanup.
        if (!(await stale(lockDir, heartbeatPath, metaPath, opts.staleMs))) {
          return { acquired: false }
        }

        await rm(lockDir, { recursive: true, force: true })

        try {
          await mkdir(lockDir, { mode: 0o700 })
        } catch (retryErr) {
          const errCode = code(retryErr)
          if (errCode === "EEXIST" || errCode === "ENOTEMPTY") {
            return { acquired: false }
          }
          throw retryErr
        }
      } finally {
        await rm(breakerPath, { recursive: true, force: true }).catch(() => undefined)
      }
    }

    const meta = {
      token,
      pid: process.pid,
      hostname: os.hostname(),
      createdAt: new Date().toISOString(),
    }

    await writeFile(heartbeatPath, "", { flag: "wx" }).catch(async () => {
      await rm(lockDir, { recursive: true, force: true })
      throw new Error("Lock acquired but heartbeat already existed (possible compromise).")
    })

    await writeFile(metaPath, JSON.stringify(meta, null, 2), { flag: "wx" }).catch(async () => {
      await rm(lockDir, { recursive: true, force: true })
      throw new Error("Lock acquired but meta.json already existed (possible compromise).")
    })

    let timer: NodeJS.Timeout | undefined

    const startHeartbeat = (intervalMs = Math.max(100, Math.floor(opts.staleMs / 3))) => {
      if (timer) return
      // Heartbeat prevents long critical sections from being evicted as stale.
      timer = setInterval(() => {
        const t = new Date()
        void utimes(heartbeatPath, t, t).catch(() => undefined)
      }, intervalMs)
      timer.unref?.()
    }

    const release = async () => {
      if (timer) {
        clearInterval(timer)
        timer = undefined
      }

      const current = await readFile(metaPath, "utf8")
        .then((raw) => {
          const parsed = JSON.parse(raw)
          if (!parsed || typeof parsed !== "object") return {}
          return {
            token: "token" in parsed && typeof parsed.token === "string" ? parsed.token : undefined,
          }
        })
        .catch((err) => {
          const errCode = code(err)
          if (errCode === "ENOENT" || errCode === "ENOTDIR") {
            throw new Error("Refusing to release: lock is compromised (metadata missing).")
          }
          if (err instanceof SyntaxError) {
            throw new Error("Refusing to release: lock is compromised (metadata invalid).")
          }
          throw err
        })
      // Token check prevents deleting a lock that was re-acquired by another process.
      if (current.token !== token) {
        throw new Error("Refusing to release: lock token mismatch (not the owner).")
      }

      await rm(lockDir, { recursive: true, force: true })
    }

    return {
      acquired: true,
      startHeartbeat,
      release,
    }
  }

  async function acquireLockDir(
    lockDir: string,
    input: { key: string; onWait?: Wait; signal?: AbortSignal },
    opts: Opts,
  ) {
    const stop = mono() + opts.timeoutMs
    let attempt = 0
    let waited = 0
    let delay = opts.baseDelayMs

    while (true) {
      input.signal?.throwIfAborted()

      const res = await tryAcquireLockDir(lockDir, opts)
      if (res.acquired) {
        return res
      }

      if (mono() > stop) {
        throw new Error(`Timed out waiting for lock: ${input.key}`)
      }

      attempt += 1
      const ms = jitter(delay)
      await input.onWait?.({
        key: input.key,
        attempt,
        delay: ms,
        waited,
      })
      await sleep(ms, input.signal)
      waited += ms
      delay = Math.min(opts.maxDelayMs, Math.floor(delay * 1.7))
    }
  }

  export async function acquire(key: string, input: Options = {}): Promise<Lease> {
    input.signal?.throwIfAborted()
    const cfg: Opts = {
      staleMs: input.staleMs ?? defaultOpts.staleMs,
      timeoutMs: input.timeoutMs ?? defaultOpts.timeoutMs,
      baseDelayMs: input.baseDelayMs ?? defaultOpts.baseDelayMs,
      maxDelayMs: input.maxDelayMs ?? defaultOpts.maxDelayMs,
    }
    const dir = input.dir ?? root()

    await mkdir(dir, { recursive: true })
    const lockfile = path.join(dir, Hash.fast(key) + ".lock")
    const lock = await acquireLockDir(
      lockfile,
      {
        key,
        onWait: input.onWait,
        signal: input.signal,
      },
      cfg,
    )
    lock.startHeartbeat()

    const release = () => lock.release()
    return {
      release,
      [Symbol.asyncDispose]() {
        return release()
      },
    }
  }

  export async function withLock<T>(key: string, fn: () => Promise<T>, input: Options = {}) {
    await using _ = await acquire(key, input)
    input.signal?.throwIfAborted()
    return await fn()
  }

  export const effect = Effect.fn("Flock.effect")(function* (key: string, input: Options = {}) {
    return yield* Effect.acquireRelease(
      Effect.promise((signal) => Flock.acquire(key, { ...input, signal })).pipe(
        Effect.withSpan("Flock.acquire", {
          attributes: { key },
        }),
      ),
      (lock) => Effect.promise(() => lock.release()).pipe(Effect.withSpan("Flock.release")),
    ).pipe(Effect.asVoid)
  })
}

import path, { dirname, isAbsolute, join, relative, sep } from "path"
import { realpathSync } from "fs"
import { readdir } from "fs/promises"
import { lookup } from "mime-types"
import { Context, Effect, FileSystem, Layer, Schema } from "effect"
import type { PlatformError } from "effect/PlatformError"
import { Glob } from "./glob.js"
import { serviceUse } from "./effect/service-use.js"
import { makeGlobalNode } from "./effect/app-node.js"
import { filesystem } from "./effect/app-node-platform.js"
import { sameDirectory } from "./path.js"

export namespace FSUtil {
  export class FileSystemError extends Schema.TaggedError<FileSystemError>()("FileSystemError", {
    method: Schema.String,
    cause: Schema.optional(Schema.Defect()),
  }) {
    override get message() {
      const detail = this.cause instanceof Error ? this.cause.message : this.cause && String(this.cause)
      return `Filesystem operation failed: ${this.method}${detail ? `: ${detail}` : ""}`
    }
  }

  export type Error = PlatformError | FileSystemError

  export interface DirEntry {
    readonly name: string
    readonly type: "file" | "directory" | "symlink" | "other"
  }

  export interface UpOptions {
    readonly targets: string[]
    readonly start: string
    readonly stop?: string
    readonly mode?: "all" | "first"
    /** Only match regular files or directories (following symlinks). By default any existing path matches. */
    readonly type?: "file" | "directory"
  }

  export interface Interface extends FileSystem.FileSystem {
    readonly isDir: (path: string) => Effect.Effect<boolean>
    readonly isFile: (path: string) => Effect.Effect<boolean>
    readonly existsSafe: (path: string) => Effect.Effect<boolean>
    readonly readFileStringSafe: (path: string) => Effect.Effect<string | undefined, Error>
    readonly readJson: (path: string) => Effect.Effect<unknown, Error>
    readonly writeJson: (path: string, data: unknown, mode?: number) => Effect.Effect<void, Error>
    readonly ensureDir: (path: string) => Effect.Effect<void, Error>
    readonly writeWithDirs: (path: string, content: string | Uint8Array, mode?: number) => Effect.Effect<void, Error>
    readonly readDirectoryEntries: (path: string) => Effect.Effect<DirEntry[], Error>
    readonly resolve: (path: string) => Effect.Effect<string>
    readonly findUp: (target: string, start: string, stop?: string) => Effect.Effect<string[], Error>
    readonly up: (options: UpOptions) => Effect.Effect<string[], Error>
    readonly globUp: (pattern: string, start: string, stop?: string) => Effect.Effect<string[], Error>
    readonly scan: (pattern: string, options?: Glob.Options) => Effect.Effect<string[], Error>
    readonly globMatch: (pattern: string, filepath: string) => boolean
  }

  export class Service extends Context.Service<Service, Interface>()("@opencode/FSUtil") {}

  export const use = serviceUse(Service)

  // Exported so simulation can wrap this layer and override the methods that
  // bypass the injected FileSystem (readDirectoryEntries, scan, globUp).
  export const layer = Layer.effect(
    Service,
    Effect.gen(function* () {
      const fs = yield* FileSystem.FileSystem

      const existsSafe = Effect.fn("FileSystem.existsSafe")(function* (path: string) {
        return yield* fs.exists(path).pipe(Effect.orElseSucceed(() => false))
      })

      const readFileStringSafe = Effect.fn("FileSystem.readFileStringSafe")(function* (path: string) {
        return yield* fs.readFileString(path).pipe(
          Effect.catchReason("PlatformError", "NotFound", () => Effect.undefined),
          Effect.catchReason("PlatformError", "PermissionDenied", () => Effect.undefined),
        )
      })

      const isDir = Effect.fn("FileSystem.isDir")(function* (path: string) {
        const info = yield* fs.stat(path).pipe(Effect.catch(() => Effect.void))
        return info?.type === "Directory"
      })

      const isFile = Effect.fn("FileSystem.isFile")(function* (path: string) {
        const info = yield* fs.stat(path).pipe(Effect.catch(() => Effect.void))
        return info?.type === "File"
      })

      const readDirectoryEntries = Effect.fn("FileSystem.readDirectoryEntries")(function* (dirPath: string) {
        return yield* Effect.tryPromise({
          try: async () => {
            const entries = await readdir(dirPath, { withFileTypes: true })
            return entries.map(
              (e): DirEntry => ({
                name: e.name,
                type: e.isDirectory() ? "directory" : e.isSymbolicLink() ? "symlink" : e.isFile() ? "file" : "other",
              }),
            )
          },
          catch: (cause) => new FileSystemError({ method: "readDirectoryEntries", cause }),
        })
      })

      const resolve = Effect.fn("FileSystem.resolve")(function* (input: string) {
        const resolved = path.resolve(windowsPath(input))
        return yield* fs.realPath(resolved).pipe(
          Effect.catchReason("PlatformError", "NotFound", () => Effect.succeed(resolved)),
          Effect.orDie,
        )
      })

      const readJson = Effect.fn("FileSystem.readJson")(function* (path: string) {
        const text = yield* fs.readFileString(path)
        return yield* Effect.try({
          try: () => JSON.parse(text),
          catch: (cause) => new FileSystemError({ method: "readJson", cause }),
        })
      })

      const writeJson = Effect.fn("FileSystem.writeJson")(function* (path: string, data: unknown, mode?: number) {
        const content = JSON.stringify(data, null, 2)
        yield* fs.writeFileString(path, content)
        if (mode) yield* fs.chmod(path, mode)
      })

      const ensureDir = Effect.fn("FileSystem.ensureDir")(function* (path: string) {
        yield* fs.makeDirectory(path, { recursive: true }).pipe(
          // Bun on Windows can throw EEXIST here despite recursive mode.
          // https://github.com/oven-sh/bun/issues/21901
          Effect.catchIf(
            (error) => error.reason._tag === "AlreadyExists",
            (error) => isDir(path).pipe(Effect.flatMap((exists) => (exists ? Effect.void : Effect.fail(error)))),
          ),
        )
      })

      const writeWithDirs = Effect.fn("FileSystem.writeWithDirs")(function* (
        path: string,
        content: string | Uint8Array,
        mode?: number,
      ) {
        const write = typeof content === "string" ? fs.writeFileString(path, content) : fs.writeFile(path, content)

        yield* write.pipe(
          Effect.catchIf(
            (e) => e.reason._tag === "NotFound",
            () =>
              Effect.gen(function* () {
                yield* fs.makeDirectory(dirname(path), { recursive: true })
                yield* write
              }),
          ),
        )
        if (mode) yield* fs.chmod(path, mode)
      })

      const scan = Effect.fn("FileSystem.scan")(function* (pattern: string, options?: Glob.Options) {
        return yield* Effect.tryPromise({
          try: () => Glob.scan(pattern, options),
          catch: (cause) => new FileSystemError({ method: "glob", cause }),
        })
      })

      const up = Effect.fn("FileSystem.up")(function* (options: UpOptions) {
        const result: string[] = []
        let current = options.start
        while (true) {
          for (const target of options.targets) {
            const search = join(current, target)
            const found =
              options.type === "file"
                ? yield* isFile(search)
                : options.type === "directory"
                  ? yield* isDir(search)
                  : yield* fs.exists(search)
            if (found) {
              result.push(search)
              if (options.mode === "first") return result
            }
          }
          if (options.stop && sameDirectory(options.stop, current)) break
          const parent = dirname(current)
          if (parent === current) break
          current = parent
        }
        return result
      })

      const findUp = Effect.fn("FileSystem.findUp")((target: string, start: string, stop?: string) =>
        up({ targets: [target], start, stop }),
      )

      const globUp = Effect.fn("FileSystem.globUp")(function* (pattern: string, start: string, stop?: string) {
        const result: string[] = []
        let current = start
        while (true) {
          const matches = yield* scan(pattern, { cwd: current, absolute: true, include: "file", dot: true }).pipe(
            Effect.orElseSucceed(() => [] as string[]),
          )
          result.push(...matches)
          if (stop && sameDirectory(stop, current)) break
          const parent = dirname(current)
          if (parent === current) break
          current = parent
        }
        return result
      })

      return Service.of({
        ...fs,
        existsSafe,
        readFileStringSafe,
        isDir,
        isFile,
        readDirectoryEntries,
        resolve,
        readJson,
        writeJson,
        ensureDir,
        writeWithDirs,
        findUp,
        up,
        globUp,
        scan,
        globMatch: Glob.match,
      })
    }),
  )

  export const node = makeGlobalNode({ service: Service, layer: layer, deps: [filesystem] })

  // Pure helpers that don't need Effect (path manipulation, sync operations)
  export function mimeType(p: string): string {
    return lookup(p) || "application/octet-stream"
  }

  export function normalizePath(p: string): string {
    if (process.platform !== "win32") return p
    const resolved = path.resolve(windowsPath(p))
    try {
      return realpathSync.native(resolved)
    } catch {
      return resolved
    }
  }

  export function normalizePathPattern(p: string): string {
    if (process.platform !== "win32") return p
    if (p === "*") return p
    const match = p.match(/^(.*)[\\/]\*$/)
    if (!match) return normalizePath(p)
    const dir = /^[A-Za-z]:$/.test(match[1]) ? match[1] + "\\" : match[1]
    return join(normalizePath(dir), "*")
  }

  export function resolve(p: string): string {
    const resolved = path.resolve(windowsPath(p))
    try {
      return normalizePath(realpathSync(resolved))
    } catch (e: any) {
      if (e?.code === "ENOENT" || e?.code === "ENOTDIR") return normalizePath(resolved)
      throw e
    }
  }

  export function windowsPath(p: string): string {
    if (process.platform !== "win32") return p
    return p
      .replace(/^\/([a-zA-Z]):(?:[\\/]|$)/, (_, drive) => `${drive.toUpperCase()}:/`)
      .replace(/^\/([a-zA-Z])(?:\/|$)/, (_, drive) => `${drive.toUpperCase()}:/`)
      .replace(/^\/cygdrive\/([a-zA-Z])(?:\/|$)/, (_, drive) => `${drive.toUpperCase()}:/`)
      .replace(/^\/mnt\/([a-zA-Z])(?:\/|$)/, (_, drive) => `${drive.toUpperCase()}:/`)
  }

  export function overlaps(a: string, b: string) {
    return contains(a, b) || contains(b, a)
  }

  export function contains(parent: string, child: string) {
    const result = relative(parent, child)
    return result === "" || (!isAbsolute(result) && result !== ".." && !result.startsWith(`..${sep}`))
  }
}

import { glob, globSync, type GlobOptions } from "glob"
import { minimatch } from "minimatch"

export namespace Glob {
  export interface Options {
    cwd?: string
    absolute?: boolean
    include?: "file" | "all"
    dot?: boolean
    symlink?: boolean
  }

  function toGlobOptions(options: Options): GlobOptions {
    return {
      cwd: options.cwd,
      absolute: options.absolute,
      dot: options.dot,
      follow: options.symlink ?? false,
      nodir: options.include !== "all",
    }
  }

  export async function scan(pattern: string, options: Options = {}): Promise<string[]> {
    return glob(pattern, toGlobOptions(options)) as Promise<string[]>
  }

  export function scanSync(pattern: string, options: Options = {}): string[] {
    return globSync(pattern, toGlobOptions(options)) as string[]
  }

  export function match(pattern: string, filepath: string): boolean {
    return minimatch(filepath, pattern, { dot: true })
  }
}

import os from "os"
import path from "path"

const home = os.homedir()
const data = process.env.XDG_DATA_HOME || (home ? path.join(home, ".local", "share") : undefined)
const cache = process.env.XDG_CACHE_HOME || (home ? path.join(home, ".cache") : undefined)
const config = process.env.XDG_CONFIG_HOME || (home ? path.join(home, ".config") : undefined)
const state = process.env.XDG_STATE_HOME || (home ? path.join(home, ".local", "state") : undefined)

/** The XDG base directories that root opencode's global paths. */
export function roots(app: string) {
  return {
    data: path.join(data!, app),
    cache: path.join(cache!, app),
    config: path.join(config!, app),
    state: path.join(state!, app),
    tmp: path.join(os.tmpdir(), app),
  }
}

import os from "os"
import path from "path"

// workerd has no home directory or XDG base dirs and only tmp is writable, so
// every global path roots under one directory there. Nothing durable lives in
// these: on workerd the database is on Durable Object storage.
export function roots(app: string) {
  const root = path.join(os.tmpdir(), app)
  return {
    data: path.join(root, "data"),
    cache: path.join(root, "cache"),
    config: path.join(root, "config"),
    state: path.join(root, "state"),
    tmp: path.join(root, "tmp"),
  }
}

import path from "path"
import fs from "fs"
import os from "os"
import { Context, Effect, Layer } from "effect"
// XDG on runtimes with a home directory; one tmp-rooted directory on workerd.
// The variants resolve through the `workerd` bundle condition, like the
// native-module stubs, so no runtime sniffing happens here.
import { roots } from "#global-roots"
import { Flock } from "./flock.js"
import { makeGlobalNode } from "./effect/app-node.js"

const app = "opencode"
const { data, cache, config, state, tmp } = roots(app)

const paths = {
  get home() {
    return process.env.OPENCODE_TEST_HOME ?? os.homedir()
  },
  data,
  bin: path.join(cache, "bin"),
  log: path.join(data, "log"),
  repos: path.join(data, "repos"),
  cache,
  config,
  state,
  tmp,
}

export const Path = paths

Flock.setGlobal({ state })

export class Service extends Context.Service<Service, Interface>()("@opencode/Global") {}

export interface Interface {
  readonly home: string
  readonly data: string
  readonly cache: string
  readonly config: string
  readonly state: string
  readonly tmp: string
  readonly bin: string
  readonly log: string
  readonly repos: string
}

export function make(input: Partial<Interface> = {}): Interface {
  // The acquired service canonicalizes default tmp; use it instead of Path.tmp for path comparisons.
  return {
    home: Path.home,
    data: Path.data,
    cache: Path.cache,
    config: Path.config,
    state: Path.state,
    tmp: input.tmp ?? Path.tmp,
    bin: Path.bin,
    log: Path.log,
    repos: Path.repos,
    ...input,
  }
}

const acquire = (input: Partial<Interface>) =>
  Effect.gen(function* () {
    const service = Service.of(make(input))
    yield* Effect.promise(() =>
      Promise.all(
        [service.data, service.config, service.state, service.log, service.bin, service.repos, service.tmp].map(
          (directory) => fs.promises.mkdir(directory, { recursive: true }),
        ),
      ),
    )
    const canonicalTmp = yield* Effect.promise(() => fs.promises.realpath(service.tmp))
    return Service.of({ ...service, tmp: input.tmp ?? canonicalTmp })
  })

const layer = Layer.effect(
  Service,
  Effect.suspend(() => acquire({ config: process.env.OPENCODE_CONFIG_DIR ?? Path.config })),
)

export const node = makeGlobalNode({ service: Service, layer: layer, deps: [] })

export const layerWith = (input: Partial<Interface>) => Layer.effect(Service, acquire(input))

export * as Global from "./global.js"

import { createHash } from "crypto"

export namespace Hash {
  export function fast(input: string | Buffer): string {
    return createHash("sha1").update(input).digest("hex")
  }

  export function sha256(input: string | Buffer): string {
    return createHash("sha256").update(input).digest("hex")
  }
}

export * as NpmConfig from "./npm-config.js"

import { fileURLToPath } from "url"
import { Effect } from "effect"

export const load = (dir: string) =>
  Effect.tryPromise({
    try: async () => {
      // @ts-expect-error npm does not publish types for this internal config API.
      const { default: Config } = await import("@npmcli/config")
      // @ts-expect-error npm does not publish types for this internal config API.
      const { default: npmDefinitions } = await import("@npmcli/config/lib/definitions/index.js")
      const { definitions, flatten, nerfDarts, shorthands } = npmDefinitions
      const config = new Config({
        // Resolved per call: on workerd import.meta.url is undefined and building
        // this URL at module scope fails startup validation; npm config never runs there.
        npmPath: fileURLToPath(new URL("..", import.meta.url)),
        cwd: dir,
        env: { ...process.env },
        argv: [process.execPath, process.execPath, "--prefix", dir],
        execPath: process.execPath,
        platform: process.platform,
        definitions,
        flatten,
        nerfDarts,
        shorthands,
        warn: false,
      })
      await config.load()
      return config.flat as Record<string, unknown>
    },
    catch: (cause) => cause,
  }).pipe(Effect.orElseSucceed(() => ({}) as Record<string, unknown>))

export const registry = (dir: string) =>
  load(dir).pipe(
    Effect.map((config) => {
      const registry = typeof config.registry === "string" ? config.registry : "https://registry.npmjs.org"
      return registry.endsWith("/") ? registry.slice(0, -1) : registry
    }),
  )

export * as Npm from "./npm.js"

import path from "path"
import { createHash, randomUUID } from "node:crypto"
import { Clock, Effect, Schema, Context, Layer, Option, FileSystem } from "effect"
import { FSUtil } from "./fs-util.js"
import { Global } from "./global.js"
import { EffectFlock } from "./effect-flock.js"
import { makeGlobalNode } from "./effect/app-node.js"
import { filesystem } from "./effect/app-node-platform.js"
import { LayerNode } from "./effect/layer-node.js"
import { makeRuntime } from "./effect/runtime.js"
import { NpmConfig } from "./npm-config.js"

export class InstallFailedError extends Schema.TaggedError<InstallFailedError>()("NpmInstallFailedError", {
  add: Schema.Array(Schema.String).pipe(Schema.optional),
  dir: Schema.String,
  cause: Schema.optional(Schema.Defect()),
}) {}

export interface Package {
  readonly directory: string
  readonly name: string
  readonly version?: string
  readonly revision?: string
}

export interface Interface {
  readonly add: (pkg: string) => Effect.Effect<Package, InstallFailedError | EffectFlock.LockError>
  readonly resolve: (pkg: string) => Effect.Effect<Package>
  readonly check: (pkg: string) => Effect.Effect<boolean, InstallFailedError>
  readonly update: (pkg: string) => Effect.Effect<Package, InstallFailedError | EffectFlock.LockError>
  readonly which: (pkg: string, bin?: string) => Effect.Effect<string | undefined>
}

export class Service extends Context.Service<Service, Interface>()("@opencode/Npm") {}

const illegal = process.platform === "win32" ? new Set(["<", ">", ":", '"', "|", "?", "*"]) : undefined

export function sanitize(pkg: string) {
  if (!illegal) return pkg
  return Array.from(pkg, (char) => (illegal.has(char) || char.charCodeAt(0) < 32 ? "_" : char)).join("")
}

export async function isRegistryPackage(pkg: string) {
  return (await parse(pkg))?.type === "registry"
}

export async function isInstallablePackage(pkg: string) {
  return (await parse(pkg)) !== undefined
}

export async function cacheKey(pkg: string) {
  return key(pkg, await parse(pkg))
}

type Target =
  | { readonly type: "registry"; readonly name: string; readonly spec: string; readonly mutable: boolean }
  | { readonly type: "git"; readonly name?: string; readonly slug: string; readonly mutable: boolean }

async function parse(pkg: string): Promise<Target | undefined> {
  const { default: npa } = await import("npm-package-arg")
  try {
    const result = npa(pkg)
    if (result.type === "git") {
      return {
        type: "git",
        ...(result.name ? { name: result.name } : {}),
        slug: gitSlug(pkg),
        mutable: !isCommit(result.gitCommittish),
      }
    }
    if (!result.name || !["version", "range", "tag"].includes(result.type)) return
    return {
      type: "registry",
      name: result.name,
      spec: result.raw === result.name ? "latest" : result.rawSpec,
      mutable: result.type !== "version",
    }
  } catch {
    return
  }
}

function key(pkg: string, target: Target | undefined) {
  if (target?.type === "git")
    return `git-${target.slug}-${createHash("sha256").update(pkg).digest("hex").slice(0, 12)}`
  if (target?.type === "registry") return sanitize(`${target.name}@${target.spec}`)
  return sanitize(pkg)
}

function gitSlug(pkg: string) {
  const target = (() => {
    try {
      return decodeURIComponent(pkg.split("#")[0])
    } catch {
      return pkg.split("#")[0]
    }
  })()
  return (
    target
      .replace(/\.git$/i, "")
      .split(/[/:\\]/)
      .at(-1)
      ?.replace(/[^a-zA-Z0-9._-]+/g, "-")
      .replace(/^-+|-+$/g, "") || "repository"
  )
}

interface ArboristNode {
  name: string
  path: string
  realpath: string
  isLink: boolean
}

interface ArboristTree {
  edgesOut: Map<string, { to?: ArboristNode }>
  inventory: { values(): IterableIterator<ArboristNode> }
}

const PackageJson = Schema.Struct({
  dependencies: Schema.optional(Schema.Record(Schema.String, Schema.String)),
  version: Schema.optional(Schema.String),
})

const PackageLock = Schema.Struct({
  packages: Schema.optional(Schema.Record(Schema.String, Schema.Struct({ resolved: Schema.optional(Schema.String) }))),
})

const retention = 7 * 24 * 60 * 60 * 1_000
const stagingRetention = 60 * 60 * 1_000

const layer = Layer.effect(
  Service,
  Effect.gen(function* () {
    const afs = yield* FSUtil.Service
    const global = yield* Global.Service
    const fs = yield* FileSystem.FileSystem
    const flock = yield* EffectFlock.Service
    const directory = (pkg: string, target: Target | undefined) => path.join(global.cache, "npm", key(pkg, target))
    const generations = Effect.fnUntraced(function* (dir: string) {
      return yield* fs.readDirectory(dir).pipe(
        Effect.orElseSucceed(() => [] as string[]),
        Effect.map((entries) =>
          entries
            .filter((entry) => /^\d+$/.test(entry))
            .toSorted((a, b) => Number(a) - Number(b)),
        ),
      )
    })
    const current = Effect.fnUntraced(function* (dir: string) {
      const latest = (yield* generations(dir)).at(-1)
      return latest ? path.join(dir, latest) : undefined
    })
    const mkdir = (dir: string) =>
      fs.makeDirectory(dir, { recursive: true }).pipe(
        Effect.mapError((cause) => new InstallFailedError({ dir, cause })),
      )
    const remove = (target: string, dir: string) =>
      fs.remove(target, { recursive: true, force: true }).pipe(
        Effect.mapError((cause) => new InstallFailedError({ dir, cause })),
      )
    const rename = (from: string, to: string, dir: string) =>
      fs.rename(from, to).pipe(Effect.mapError((cause) => new InstallFailedError({ dir, cause })))
    const installedName = Effect.fnUntraced(function* (pkg: string, dir: string, target?: Target) {
      if (target?.name) return target.name
      const manifest = yield* afs
        .readJson(path.join(dir, "package.json"))
        .pipe(Effect.flatMap(Schema.decodeUnknownEffect(PackageJson)), Effect.option)
      if (Option.isSome(manifest)) {
        const name = Object.keys(manifest.value.dependencies ?? {})[0]
        if (name) return name
      }
      return pkg
    })
    const installedRevision = Effect.fnUntraced(function* (root: string, name: string, target: Target) {
      const dir = path.join(root, "node_modules", name)
      if (target.type === "registry") {
        const manifest = yield* afs
          .readJson(path.join(dir, "package.json"))
          .pipe(Effect.flatMap(Schema.decodeUnknownEffect(PackageJson)), Effect.option)
        return Option.isSome(manifest) ? manifest.value.version : undefined
      }
      for (const file of [path.join(root, "package-lock.json"), path.join(root, "node_modules", ".package-lock.json")]) {
        const lock = yield* afs
          .readJson(file)
          .pipe(Effect.flatMap(Schema.decodeUnknownEffect(PackageLock)), Effect.option)
        const revision = gitRevision(
          Option.isSome(lock) ? lock.value.packages?.[`node_modules/${name}`]?.resolved : undefined,
        )
        if (revision) return revision
      }
    })
    const metadata = Effect.fnUntraced(function* (root: string, name: string, dir: string, target: Target | undefined) {
      const manifest = yield* afs
        .readJson(path.join(dir, "package.json"))
        .pipe(Effect.flatMap(Schema.decodeUnknownEffect(PackageJson)), Effect.option)
      const manifestVersion = Option.isSome(manifest) ? manifest.value.version : undefined
      const revision = target ? (yield* installedRevision(root, name, target)) ?? manifestVersion : undefined
      const version = target?.type === "git" ? revision : manifestVersion
      return {
        directory: dir,
        name,
        ...(version ? { version } : {}),
        ...(revision ? { revision } : {}),
      }
    })
    const reify = (input: { dir: string; config?: string; add?: string[]; update?: boolean }) =>
      Effect.gen(function* () {
        const { Arborist } = yield* Effect.promise(() => import("@npmcli/arborist"))
        const add = input.add ?? []
        const options = {
          ...(yield* NpmConfig.load(input.config ?? input.dir)),
          ...(input.update ? { preferOnline: true, noGitRevCache: true } : {}),
          // Audit reports are unused here, but Arborist waits for them before completing an install.
          audit: false,
          windowsHide: true,
        }
        const arborist = new Arborist({
          ...options,
          path: input.dir,
          binLinks: true,
          progress: false,
          savePrefix: "",
          ignoreScripts: true,
        })
        return yield* Effect.tryPromise({
          try: () =>
            arborist.reify({
              ...options,
              add,
              update: input.update,
              save: true,
              saveType: "prod",
            }),
          catch: (cause) =>
            new InstallFailedError({
              cause,
              add,
              dir: input.dir,
            }),
        }) as Effect.Effect<ArboristTree, InstallFailedError>
      }).pipe(
        Effect.withSpan("Npm.reify", {
          attributes: input,
        }),
      )

    const install = Effect.fnUntraced(function* (
      pkg: string,
      target: Target | undefined,
      dir: string,
      update: boolean,
    ) {
      yield* flock.acquire(`npm-install:${dir}`)
      const active = yield* current(dir)
      const name = yield* installedName(pkg, active ?? dir, target)
      if (active && !update && (yield* afs.existsSafe(path.join(active, "node_modules", name)))) {
        return yield* metadata(active, name, path.join(active, "node_modules", name), target)
      }

      yield* mkdir(dir)
      const startedAt = yield* Clock.currentTimeMillis
      // Arborist keys lockfile entries relative to the root's real path. When the cache
      // directory is reached through a symlink (macOS `/var` → `/private/var`, a linked
      // XDG cache), the keys become `../../…` paths that installedRevision never finds,
      // so Git checks report "not installed" and updates go undetected. Stage under the
      // resolved directory so the root path and real path agree.
      const root = yield* fs.realPath(dir).pipe(Effect.mapError((cause) => new InstallFailedError({ dir, cause })))
      const staging = path.join(root, `.staging-${startedAt}-${randomUUID()}`)
      const staged = yield* Effect.gen(function* () {
        const tree = yield* reify({ dir: staging, config: dir, add: [pkg], update })
        const installed = tree.edgesOut.values().next().value?.to
        const installedNameValue = installed?.name ?? (yield* installedName(pkg, staging, target))
        const result = yield* metadata(
          staging,
          installedNameValue,
          installed?.path ?? path.join(staging, "node_modules", installedNameValue),
          target,
        )
        if (!installed && !(yield* afs.isDir(result.directory)))
          return yield* new InstallFailedError({ add: [pkg], dir: staging })
        const links =
          process.platform === "win32"
            ? Array.from(tree.inventory.values()).filter(
                (node) => node.isLink && FSUtil.contains(staging, node.path) && FSUtil.contains(staging, node.realpath),
              )
            : []
        return { result, links }
      }).pipe(Effect.onError(() => remove(staging, dir).pipe(Effect.ignore)))

      if (active) {
        const activeEntry = yield* metadata(active, name, path.join(active, "node_modules", name), target)
        if (activeEntry.revision && activeEntry.revision === staged.result.revision) {
          yield* remove(staging, dir)
          return activeEntry
        }
      }

      const completedAt = yield* Clock.currentTimeMillis
      const newest = Number((yield* generations(dir)).at(-1) ?? 0)
      const generation = path.join(dir, String(Math.max(completedAt, newest + 1)))
      // Windows junctions use absolute targets, so rebase internal links before publishing the generation.
      if (staged.links.length > 0) {
        const { unlink, symlink } = yield* Effect.promise(() => import("node:fs/promises"))
        yield* Effect.forEach(
          staged.links,
          (link) =>
            Effect.tryPromise({
              try: async () => {
                await unlink(link.path)
                await symlink(path.join(generation, path.relative(staging, link.realpath)), link.path, "junction")
              },
              catch: (cause) => new InstallFailedError({ dir, cause }),
            }),
          { discard: true },
        ).pipe(Effect.onError(() => remove(staging, dir).pipe(Effect.ignore)))
      }
      yield* rename(staging, generation, dir)
      return { ...staged.result, directory: path.join(generation, "node_modules", staged.result.name) }
    })

    const collect = Effect.fnUntraced(function* (dir: string) {
      const now = yield* Clock.currentTimeMillis
      const completed = yield* generations(dir)
      const keep = new Set(completed.slice(-2))
      const entries = yield* fs.readDirectory(dir).pipe(Effect.orElseSucceed(() => [] as string[]))
      yield* Effect.forEach(
        entries,
        (name) => {
          const timestamp = /^\d+$/.test(name)
            ? Number(name)
            : Number(name.match(/^\.staging-(\d+)-/)?.[1] ?? Number.NaN)
          const maximumAge = name.startsWith(".staging-") ? stagingRetention : retention
          if (!Number.isFinite(timestamp) || keep.has(name) || now - timestamp <= maximumAge) return Effect.void
          return remove(path.join(dir, name), dir).pipe(
            Effect.catchCause((cause) => Effect.logWarning("failed to remove stale npm generation", { dir, name, cause })),
          )
        },
        { concurrency: "unbounded", discard: true },
      )
    })

    const add = Effect.fn("Npm.add")(function* (pkg: string) {
      const target = yield* Effect.promise(() => parse(pkg))
      const dir = directory(pkg, target)
      return yield* install(pkg, target, dir, false)
    }, Effect.scoped)

    const resolve = Effect.fn("Npm.resolve")(function* (pkg: string) {
      const target = yield* Effect.promise(() => parse(pkg))
      const root = directory(pkg, target)
      const generation = yield* current(root)
      const name = yield* installedName(pkg, generation ?? root, target)
      const dir = path.join(generation ?? root, "node_modules", name)
      if (!(yield* afs.existsSafe(dir))) return { directory: dir, name }
      return yield* metadata(generation ?? root, name, dir, target)
    })

    const check = Effect.fn("Npm.check")(function* (pkg: string) {
      const target = yield* Effect.promise(() => parse(pkg))
      const root = directory(pkg, target)
      if (!target)
        return yield* new InstallFailedError({
          dir: root,
          cause: new Error("Package checks only support registry and Git package specs"),
        })
      if (!target.mutable) return false
      const generation = yield* current(root)
      const name = yield* installedName(pkg, generation ?? root, target)
      const installed = generation ? yield* installedRevision(generation, name, target) : undefined
      if (!installed)
        return yield* new InstallFailedError({ dir: root, cause: new Error(`Package is not installed: ${pkg}`) })
      const { manifest, resolve } = yield* Effect.promise(() => import("pacote"))
      const options = {
        ...(yield* NpmConfig.load(root)),
        preferOnline: true,
        noGitRevCache: true,
        ignoreScripts: true,
        // Pacote spawns Git directly rather than through AppProcess.
        windowsHide: true,
      }
      const available = yield* Effect.tryPromise({
        try: async () =>
          target.type === "git" ? gitRevision(await resolve(pkg, options)) : (await manifest(pkg, options)).version,
        catch: (cause) => new InstallFailedError({ dir: root, cause }),
      })
      if (!available)
        return yield* new InstallFailedError({ dir: root, cause: new Error(`Package revision not found: ${pkg}`) })
      return installed !== available
    })

    const update = Effect.fn("Npm.update")(function* (pkg: string) {
      const target = yield* Effect.promise(() => parse(pkg))
      const dir = directory(pkg, target)
      if (!target)
        return yield* new InstallFailedError({
          dir,
          cause: new Error("Package updates only support registry and Git package specs"),
        })
      if (!target.mutable) return yield* add(pkg)
      const installed = yield* install(pkg, target, dir, true)
      yield* collect(dir)
      return installed
    }, Effect.scoped)

    const which = Effect.fn("Npm.which")(function* (pkg: string, bin?: string) {
      const target = yield* Effect.promise(() => parse(pkg))
      const root = directory(pkg, target)

      const pick = Effect.fnUntraced(function* (dir: string) {
        const binDir = path.join(dir, "node_modules", ".bin")
        const files = yield* fs.readDirectory(binDir).pipe(Effect.orElseSucceed(() => [] as string[]))

        if (files.length === 0) return Option.none<string>()
        // Caller picked a specific bin (e.g. pyright exposes both `pyright` and
        // `pyright-langserver`); trust the hint if the package provides it.
        if (bin) return files.includes(bin) ? Option.some(path.join(binDir, bin)) : Option.none<string>()
        if (files.length === 1) return Option.some(path.join(binDir, files[0]))

        const packageName = target?.name ?? pkg
        const pkgJson = yield* afs.readJson(path.join(dir, "node_modules", packageName, "package.json")).pipe(Effect.option)

        if (Option.isSome(pkgJson)) {
          const parsed = pkgJson.value as { bin?: string | Record<string, string> }
          if (parsed?.bin) {
            const unscoped = packageName.startsWith("@") ? packageName.split("/")[1] : packageName
            const parsedBin = parsed.bin
            if (typeof parsedBin === "string") return Option.some(path.join(binDir, unscoped))
            const keys = Object.keys(parsedBin)
            const selected = parsedBin[unscoped] ? unscoped : keys[0]
            return selected ? Option.some(path.join(binDir, selected)) : Option.none<string>()
          }
        }

        return Option.some(path.join(binDir, files[0]))
      })

      return Option.getOrUndefined(
        yield* Effect.gen(function* () {
          const generation = yield* current(root)
          const selected = generation ? yield* pick(generation) : Option.none<string>()
          if (Option.isSome(selected)) return selected

          yield* add(pkg)

          const installed = yield* current(root)
          if (!installed) return Option.none<string>()
          return yield* pick(installed)
        }).pipe(
          Effect.scoped,
          Effect.orElseSucceed(() => Option.none<string>()),
        ),
      )
    })

    return Service.of({
      add,
      resolve,
      check,
      update,
      which,
    })
  }),
)

export const node = makeGlobalNode({
  service: Service,
  layer: layer,
  deps: [FSUtil.node, Global.node, filesystem, EffectFlock.node],
})

const { runPromise } = makeRuntime(Service, LayerNode.compile(node))

export async function add(...args: Parameters<Interface["add"]>) {
  return runPromise((svc) => svc.add(...args))
}

export async function resolve(...args: Parameters<Interface["resolve"]>) {
  return runPromise((svc) => svc.resolve(...args))
}

export async function check(...args: Parameters<Interface["check"]>) {
  return runPromise((svc) => svc.check(...args))
}

export async function update(...args: Parameters<Interface["update"]>) {
  return runPromise((svc) => svc.update(...args))
}

export async function which(...args: Parameters<Interface["which"]>) {
  return runPromise((svc) => svc.which(...args))
}

function gitRevision(resolved: string | undefined) {
  return resolved?.match(/#([a-f0-9]{40}|[a-f0-9]{64})(?=::|$)/i)?.[1]
}

function isCommit(value: string | null | undefined) {
  return /^(?:[a-f0-9]{40}|[a-f0-9]{64})$/i.test(value ?? "")
}

export * as Observability from "./observability.js"

import * as NodeFileSystem from "@effect/platform-node/NodeFileSystem"
import { LayerNode } from "./effect/layer-node.js"
import { Effect, Layer, Logger, References, Schema } from "effect"
import { FetchHttpClient } from "effect/http"
import { OtlpExporter, OtlpSerialization } from "effect/observability"
import { Logging } from "./observability/logging.js"
import { Otlp } from "./observability/otlp.js"

export const Options = Schema.Struct({
  endpoint: Schema.optional(Schema.String),
  headers: Schema.optional(Schema.String),
  client: Schema.optional(Schema.String),
  version: Schema.optional(Schema.String),
  channel: Schema.optional(Schema.String),
})
export type Options = typeof Options.Type

export function layer(
  options: Options = {
    endpoint: process.env.OTEL_EXPORTER_OTLP_ENDPOINT,
    headers: process.env.OTEL_EXPORTER_OTLP_HEADERS,
  },
) {
  const app = {
    client: options.client ?? "opencode",
    version: options.version ?? "unknown",
    channel: options.channel ?? "local",
  }
  const local = Logger.layer(Logging.loggers(app.channel === "local", app.channel), { mergeWithExisting: false }).pipe(
    Layer.provide(NodeFileSystem.layer),
    Layer.orDie,
    Layer.merge(Layer.succeed(References.MinimumLogLevel, Logging.minimumLogLevel())),
  )
  return Layer.unwrap(
    Effect.gen(function* () {
      const logs = Logger.layer(
        [...Logging.loggers(app.channel === "local", app.channel), ...Otlp.loggers(options, app)],
        { mergeWithExisting: false },
      ).pipe(
        Layer.provide(NodeFileSystem.layer),
        Layer.provide(OtlpSerialization.layerJson),
        Layer.provide(FetchHttpClient.layer),
        Layer.provide(OtlpExporter.layerFlusher),
        Layer.orDie,
        Layer.merge(Layer.succeed(References.MinimumLogLevel, Logging.minimumLogLevel())),
      )
      return Layer.merge(logs, yield* Otlp.tracingLayer(options, app))
    }),
  ).pipe(Layer.catchCause(() => local))
}

// Layer.suspend: constructing the loggers eagerly at module scope performs
