// Run with OPENCODE_DRIVE_DB=proof.sqlite. Only model output and fixture_hold are
// simulated. The debug endpoint closes the real graph without waiting an hour.
// Dynamic tools avoid the static adapter issue: anomalyco/opencode-drive#116.
export default OpenCodeDriver.use(
  {
    opencode: { dev: process.env.OPENCODE_DEV ?? process.cwd() },
    keepArtifacts: true,
    tui: { recording: true, viewport: { cols: 100, rows: 30 } },
    config: {
      autoupdate: false,
      username: "Demo",
      agents: { reviewer: { mode: "subagent", description: "Review the fixture" } },
    },
    tuiConfig: { theme: { name: "opencode", mode: "dark" }, animations: false, tabs: { mode: "off" } },
    project: { git: true, files: { "README.md": "# Parent fixture\n", "child/README.md": "# Child fixture\n" } },
  },
  ({ ui, llm, tui, opencode, artifacts, tools }) =>
    Effect.gen(function* () {
      const release = yield* Deferred.make<void>()
      const held = yield* Deferred.make<void>()
      yield* tools.attach({
        tools: [
          {
            name: "fixture_hold",
            description: "Wait for the fixture",
            inputSchema: { type: "object", properties: {} },
            options: { codemode: false },
          },
        ],
      })
      let parentRequests = 0
      let childRequests = 0
      yield* llm.serve((request) => {
        const body = JSON.stringify(request)
        if (body.includes("You are a subagent spawned")) {
          childRequests++
          if (childRequests === 1)
            return Stream.make(
              Llm.toolCall({ index: 0, id: "call_hold", name: "fixture_hold", input: {} }),
              Llm.finish("tool-calls"),
            )
          return Stream.fromEffect(
            Deferred.succeed(held, undefined).pipe(Effect.andThen(Deferred.await(release))),
          ).pipe(Stream.flatMap(() => Stream.make(Llm.text("CHILD_REVIEW_COMPLETE"))))
        }
        parentRequests++
        if (parentRequests === 1)
          return Stream.make(
            Llm.toolCall({
              index: 0,
              id: "call_review",
              name: "subagent",
              input: {
                agent: "reviewer",
                description: "Review fixture",
                prompt: "Review the child fixture",
                background: true,
              },
            }),
            Llm.finish("tool-calls"),
          )
        return Stream.make(
          Llm.text(
            parentRequests === 2 ? "Review is running in the background." : "Review received. All checks passed.",
          ),
        )
      })
      yield* ui.waitFor("Simulated Model", { timeout: 30000 })
      yield* ui.submit("Run the fixture review in the background.")
      yield* ui.waitFor("Review is running in the background.", { timeout: 30000 })
      const parent = (yield* opencode.session.list({ limit: 20 })).data.find((session) => !session.parentID)
      if (!parent) return yield* Effect.fail(new Error("Parent missing"))
      const child = (yield* opencode.session.list({ parentID: parent.id })).data[0]
      if (!child) return yield* Effect.fail(new Error("Child missing"))
      const hold = yield* tools.take("call_hold")
      yield* opencode.session.move({ sessionID: child.id, directory: AbsolutePath.make(`${artifacts}/files/child`) })
      yield* hold.finish({ structured: {}, content: [{ type: "text", text: "Fixture ready" }] })
      yield* Deferred.await(held).pipe(Effect.timeout("30 seconds"))
      const moved = yield* opencode.session.get({ sessionID: child.id })
      if (moved.location.directory !== `${artifacts}/files/child`)
        return yield* Effect.fail(new Error("Child did not move"))
      yield* opencode.session.wait({ sessionID: parent.id })
      if (evict) {
        yield* opencode.debug.location.evict({ location: { directory: parent.location.directory } })
        yield* opencode.location.get({ location: { directory: parent.location.directory } })
      }
      if (tui.recording)
        yield* tui.recording.mark(`${label}: parent idle${evict ? ", original location evicted" : " (control)"}`)
      yield* Deferred.succeed(release, undefined)
      yield* opencode.session.wait({ sessionID: child.id })
      const resumed = yield* ui.waitFor("Review received. All checks passed.", { timeout: 5000 }).pipe(
        Effect.as(true),
        Effect.catchTag("UiWaitTimeoutError", () => Effect.succeed(false)),
      )
      const messages = yield* opencode.message.list({ sessionID: parent.id })
      const childMessages = yield* opencode.message.list({ sessionID: child.id })
      const completed = childMessages.data.some(
        (message) =>
          message.type === "assistant" &&
          message.finish === "stop" &&
          message.content.some((part) => part.type === "text" && part.text === "CHILD_REVIEW_COMPLETE"),
      )
      const notifications = messages.data.filter(
        (message) => message.type === "synthetic" && message.metadata?.source === "subagent",
      ).length
      const marker = yield* Effect.acquireUseRelease(
        Effect.sync(() => new Database(`${artifacts}/logs/opencode/proof.sqlite`, { readonly: true })),
        (database) =>
          Effect.sync(() =>
            database
              .query<
                { status: string; output: string },
                [string]
              >("SELECT json_extract(value, '$.status') AS status, json_extract(value, '$.output') AS output FROM kv WHERE key LIKE 'job.background/%' AND json_extract(value, '$.recovery.childSessionID') = ?")
              .get(child.id),
          ),
        (database) => Effect.sync(() => database.close()),
      )
      const proof = { label, evict, resumed, completed, notifications, parentRequests, childRequests, marker }
      console.log(JSON.stringify(proof, null, 2))
      yield* Effect.promise(() => Bun.write(`${artifacts}/proof.json`, JSON.stringify(proof, null, 2)))
      if (
        !completed ||
        notifications !== (resumed ? 1 : 0) ||
        (resumed ? marker !== null : marker?.status !== "completed")
      )
        return yield* Effect.fail(new Error("Inconsistent completion evidence"))
      if (evict) {
        yield* opencode.debug.location.evict({ location: { directory: parent.location.directory } })
        yield* opencode.location.get({ location: { directory: parent.location.directory } })
        const rebuilt = yield* opencode.message.list({ sessionID: parent.id })
        if (rebuilt.data.filter((message) => message.type === "synthetic").length !== notifications)
          return yield* Effect.fail(new Error("Location rebuild duplicated notification"))
      }
      if (tui.recording)
        yield* tui.recording.mark(
          `${label}: ${resumed ? "completion resumes parent" : "child finished; parent never resumed"}`,
        )
      yield* Effect.sleep("2 seconds")
      console.log("screenshot", yield* ui.screenshot("completion"))
      if (tui.recording) console.log("video", yield* tui.recording.finish())
      if (resumed !== (label === "AFTER" || !evict))
        return yield* Effect.fail(new Error("Unexpected completion delivery"))
    }),
)

#!/usr/bin/env bun

const repo = "anomalyco/opencode"
const days = 60
const msg = `To stay organized issues are automatically closed after ${days} days of no activity. If the issue is still relevant please open a new one.`

const token = process.env.GITHUB_TOKEN
if (!token) {
  console.error("GITHUB_TOKEN environment variable is required")
  process.exit(1)
}

const cutoff = new Date(Date.now() - days * 24 * 60 * 60 * 1000)
const agentLogin = "opencode-agent[bot]"
const teamMembers = new Set(
  (await Bun.file(new URL("../../.github/TEAM_MEMBERS", import.meta.url)).text())
    .split("\n")
    .map((line) => line.trim().toLowerCase())
    .filter(Boolean),
)
const teamAssociations = new Set(["OWNER", "MEMBER"])

type Issue = {
  number: number
  updated_at: string
  author_association: string
  user: { login: string } | null
}

const headers = {
  Authorization: `Bearer ${token}`,
  "Content-Type": "application/json",
  Accept: "application/vnd.github+json",
  "X-GitHub-Api-Version": "2022-11-28",
}

function shouldSkip(i: Issue) {
  const login = i.user?.login.toLowerCase()
  return login === agentLogin || (login ? teamMembers.has(login) : false) || teamAssociations.has(i.author_association)
}

async function close(num: number) {
  const base = `https://api.github.com/repos/${repo}/issues/${num}`

  const comment = await fetch(`${base}/comments`, {
    method: "POST",
    headers,
    body: JSON.stringify({ body: msg }),
  })
  if (!comment.ok) throw new Error(`Failed to comment #${num}: ${comment.status} ${comment.statusText}`)

  const patch = await fetch(base, {
    method: "PATCH",
    headers,
    body: JSON.stringify({ state: "closed", state_reason: "not_planned" }),
  })
  if (!patch.ok) throw new Error(`Failed to close #${num}: ${patch.status} ${patch.statusText}`)

  console.log(`Closed https://github.com/${repo}/issues/${num}`)
}

async function main() {
  let page = 1
  let closed = 0

  while (true) {
    const res = await fetch(
      `https://api.github.com/repos/${repo}/issues?state=open&sort=updated&direction=asc&per_page=100&page=${page}`,
      { headers },
    )
    if (!res.ok) throw new Error(res.statusText)

    const all = (await res.json()) as Issue[]
    if (all.length === 0) break
    console.log(`Fetched page ${page} ${all.length} issues`)

    const stale: number[] = []
    for (const i of all) {
      const updated = new Date(i.updated_at)
      if (updated < cutoff) {
        if (shouldSkip(i)) {
          console.log(`Skipping stale issue #${i.number}; author ${i.user?.login ?? "unknown"} is exempt`)
          continue
        }
        stale.push(i.number)
      } else {
        console.log(`\nFound fresh issue #${i.number}, stopping`)
        if (stale.length > 0) {
          for (const num of stale) {
            await close(num)
            closed++
          }
        }
        console.log(`Closed ${closed} issues total`)
        return
      }
    }

    if (stale.length > 0) {
      for (const num of stale) {
        await close(num)
        closed++
      }
    }

    page++
  }

  console.log(`Closed ${closed} issues total`)
}

main().catch((err) => {
  console.error("Error:", err)
  process.exit(1)
})

#!/usr/bin/env bun

import { parseArgs } from "util"

const defaultRepo = "anomalyco/opencode"
const defaultAgeMonths = 1
const defaultThreshold = 2
const defaultSleepMs = 20_000
const defaultPrintLimit = 50
const positiveReactions = new Set(["THUMBS_UP", "HEART", "HOORAY", "ROCKET"])
const cleanupLabel = "automated-pr-cleanup"

const { values } = parseArgs({
  args: Bun.argv.slice(2),
  options: {
    execute: { type: "boolean", default: false },
    "dry-run": { type: "boolean", default: false },
    repo: { type: "string", default: defaultRepo },
    threshold: { type: "string", default: String(defaultThreshold) },
    "age-months": { type: "string", default: String(defaultAgeMonths) },
    "max-close": { type: "string" },
    "sleep-ms": { type: "string", default: String(defaultSleepMs) },
    "print-limit": { type: "string", default: String(defaultPrintLimit) },
    help: { type: "boolean", short: "h", default: false },
  },
})

if (values.help) {
  console.log(`
Usage: bun script/github/close-prs.ts [options]

Dry-run is the default. The script only comments and closes PRs when --execute is passed.

Criteria:
  - PRs created within the last month are untouched
  - PRs older than one month are closed when they have fewer than 2 positive reactions
  - Positive reactions are THUMBS_UP, HEART, HOORAY, and ROCKET reactions on the PR

Options:
  --execute              Comment and close matching PRs
  --dry-run              Explicitly run without changing anything
  --repo <owner/repo>    Repository to clean up (default: ${defaultRepo})
  --threshold <n>        Positive reaction threshold (default: ${defaultThreshold})
  --age-months <n>       Age cutoff in months (default: ${defaultAgeMonths})
  --max-close <n>        Maximum matching PRs to process
  --sleep-ms <n>         Delay between closing PRs (default: ${defaultSleepMs})
  --print-limit <n>      Number of matching PRs to print in dry-run (default: ${defaultPrintLimit})
  -h, --help             Show this help message

Examples:
  bun script/github/close-prs.ts
  bun script/github/close-prs.ts --threshold 2 --print-limit 100
  bun script/github/close-prs.ts --execute --threshold 2 --max-close 25
`)
  process.exit(0)
}

if (values.execute && values["dry-run"]) {
  console.error("Use either --execute or --dry-run, not both")
  process.exit(1)
}

const token = await requireToken()
const repo = requireRepo(values.repo)
const threshold = requirePositiveInteger("threshold", values.threshold)
const ageMonths = requirePositiveInteger("age-months", values["age-months"])
const maxClose =
  values["max-close"] === undefined ? undefined : requirePositiveInteger("max-close", values["max-close"])
const sleepMs = requireNonNegativeInteger("sleep-ms", values["sleep-ms"])
const printLimit = requireNonNegativeInteger("print-limit", values["print-limit"])
const cutoff = subtractMonths(new Date(), ageMonths)

const headers = {
  Authorization: `Bearer ${token}`,
  "Content-Type": "application/json",
  Accept: "application/vnd.github+json",
  "X-GitHub-Api-Version": "2022-11-28",
}

type PullRequest = {
  number: number
  title: string
  url: string
  createdAt: string
  reactionGroups: Array<{
    content: string
    users: {
      totalCount: number
    }
  }>
  labels: {
    nodes: Array<{
      name: string
    }>
  }
}

type GraphqlResponse = {
  data?: {
    rateLimit: {
      cost: number
      remaining: number
      resetAt: string
    }
    repository: {
      pullRequests: {
        pageInfo: {
          hasNextPage: boolean
          endCursor: string | null
        }
        nodes: PullRequest[]
      }
    }
  }
  errors?: Array<{
    message: string
  }>
}

type CleanupCandidate = PullRequest & {
  positiveReactions: number
}

const message = `Automated PR Cleanup

Thank you for contributing to opencode.

Due to the high volume of PRs from users and AI agents, we periodically close older PRs using automated criteria so maintainers can focus review time on the most active and community-supported contributions.

This PR was closed because it matched the following cleanup criteria:

- The PR was created more than ${ageMonths === 1 ? "1 month" : `${ageMonths} months`} ago
- The PR had fewer than ${threshold} positive reactions
- Positive reactions are counted as thumbs-up, heart, celebration, or rocket reactions on the PR

PRs created within the last ${ageMonths === 1 ? "month are" : `${ageMonths} months are`} not affected by this cleanup.

If you believe this PR was closed incorrectly, or if you are still actively working on it, please leave a comment explaining why it should be reopened. A maintainer can review and reopen it if appropriate.

Thanks again for taking the time to contribute.`

async function main() {
  console.log(`${values.execute ? "EXECUTE" : "DRY RUN"}: PR cleanup for ${repo.owner}/${repo.name}`)
  console.log(`Cutoff: ${cutoff.toISOString()}`)
  console.log(`Threshold: fewer than ${threshold} positive reactions`)

  const prs = await fetchOpenPullRequests()
  const recentCount = prs.filter((pr) => new Date(pr.createdAt) >= cutoff).length
  const matching = prs
    .map((pr) => ({ ...pr, positiveReactions: positiveReactionCount(pr) }))
    .filter((pr) => new Date(pr.createdAt) < cutoff && pr.positiveReactions < threshold)
  const candidates = matching.filter((pr) => !hasPriorCleanup(pr))
  const selected = maxClose === undefined ? candidates : candidates.slice(0, maxClose)

  console.log(`Fetched ${prs.length} open PRs`)
  console.log(`Matching cleanup criteria: ${matching.length}`)
  console.log(`Skipped previously cleaned PRs: ${matching.length - candidates.length}`)
  console.log(`Recent PRs untouched: ${recentCount}`)
  console.log(
    `Older PRs with at least ${threshold} positive reactions untouched: ${prs.length - matching.length - recentCount}`,
  )

  if (selected.length === 0) return

  if (!values.execute) {
    console.log(`\nDry-run only. Re-run with --execute to comment and close matching PRs.`)
    console.log(`Showing ${Math.min(printLimit, selected.length)} of ${selected.length} matching PRs:\n`)
    for (const pr of selected.slice(0, printLimit)) {
      console.log(`#${pr.number} ${pr.createdAt} positive=${pr.positiveReactions} ${pr.url}`)
    }
    if (selected.length > printLimit) console.log(`... ${selected.length - printLimit} more not shown`)
    return
  }

  await ensureCleanupLabel()

  console.log(`\nCommenting and closing ${selected.length} PRs...`)
  for (const pr of selected) {
    await closePullRequest(pr)
    if (sleepMs > 0) await sleep(sleepMs)
  }
  console.log(`Closed ${selected.length} PRs`)
}

async function fetchOpenPullRequests() {
  const prs: PullRequest[] = []
  let endCursor: string | null = null

  while (true) {
    const page = await graphql({
      query: `query($owner: String!, $name: String!, $endCursor: String) {
        rateLimit {
          cost
          remaining
          resetAt
        }
        repository(owner: $owner, name: $name) {
          pullRequests(first: 100, states: OPEN, orderBy: { field: CREATED_AT, direction: ASC }, after: $endCursor) {
            pageInfo {
              hasNextPage
              endCursor
            }
            nodes {
              number
              title
              url
              createdAt
              reactionGroups {
                content
                users {
                  totalCount
                }
              }
              labels(first: 100) {
                nodes {
                  name
                }
              }
            }
          }
        }
      }`,
      variables: {
        owner: repo.owner,
        name: repo.name,
        endCursor,
      },
    })

    prs.push(...page.repository.pullRequests.nodes)
    console.log(
      `Fetched ${prs.length} PRs, GraphQL rate limit remaining ${page.rateLimit.remaining} (cost ${page.rateLimit.cost})`,
    )

    if (page.rateLimit.remaining < 100) {
      const delay = Math.max(0, new Date(page.rateLimit.resetAt).getTime() - Date.now()) + 1_000
      console.warn(`GraphQL rate limit low; sleeping ${Math.ceil(delay / 1000)}s until reset`)
      await sleep(delay)
    }

    if (!page.repository.pullRequests.pageInfo.hasNextPage) return prs
    endCursor = page.repository.pullRequests.pageInfo.endCursor
  }
}

async function graphql(input: { query: string; variables: Record<string, string | null> }) {
  const response = await githubRequest("/graphql", {
    method: "POST",
    body: JSON.stringify(input),
  })
  const body = (await response.json()) as GraphqlResponse
  if (body.errors?.length)
    throw new Error(`GitHub GraphQL error: ${body.errors.map((error) => error.message).join(", ")}`)
  if (!body.data) throw new Error("GitHub GraphQL response did not include data")
  return body.data
}

async function closePullRequest(pr: CleanupCandidate) {
  await githubRequest(`/repos/${repo.owner}/${repo.name}/issues/${pr.number}/comments`, {
    method: "POST",
    body: JSON.stringify({ body: message }),
  })
  await githubRequest(`/repos/${repo.owner}/${repo.name}/pulls/${pr.number}`, {
    method: "PATCH",
    body: JSON.stringify({ state: "closed" }),
  })
  await githubRequest(`/repos/${repo.owner}/${repo.name}/issues/${pr.number}/labels`, {
    method: "POST",
    body: JSON.stringify({ labels: [cleanupLabel] }),
  })
  console.log(`Closed #${pr.number} positive=${pr.positiveReactions} ${pr.url}`)
}

async function ensureCleanupLabel() {
  const response = await fetch(
    `https://api.github.com/repos/${repo.owner}/${repo.name}/labels/${encodeURIComponent(cleanupLabel)}`,
    {
      headers,
    },
  )
  if (response.ok) return
  if (response.status !== 404)
    throw new Error(`Failed to check cleanup label: ${response.status} ${response.statusText}`)

  await githubRequest(`/repos/${repo.owner}/${repo.name}/labels`, {
    method: "POST",
    body: JSON.stringify({
      name: cleanupLabel,
      color: "ededed",
      description: "PR was closed by automated cleanup",
    }),
  })
}

async function githubRequest(path: string, init: RequestInit, attempt = 0): Promise<Response> {
  const response = await fetch(path.startsWith("https://") ? path : `https://api.github.com${path}`, {
    ...init,
    headers: {
      ...headers,
      ...init.headers,
    },
  })

  if (response.ok) return response

  const body = await response.text()
  const retryAfter = response.headers.get("retry-after")
  const reset = response.headers.get("x-ratelimit-reset")
  const retryMs = retryAfter
    ? Number(retryAfter) * 1000
    : response.headers.get("x-ratelimit-remaining") === "0" && reset
      ? Math.max(0, Number(reset) * 1000 - Date.now()) + 1_000
      : body.toLowerCase().includes("secondary rate limit")
        ? 300_000
        : response.status >= 500
          ? Math.min(300_000, 10_000 * 2 ** attempt)
          : 0

  if ((response.status === 403 || response.status === 429 || response.status >= 500) && retryMs > 0 && attempt < 10) {
    console.warn(`GitHub request failed; sleeping ${Math.ceil(retryMs / 1000)}s before retry ${attempt + 1}`)
    await sleep(retryMs)
    return githubRequest(path, init, attempt + 1)
  }

  throw new Error(`GitHub request failed: ${response.status} ${response.statusText}\n${body}`)
}

function positiveReactionCount(pr: PullRequest) {
  return pr.reactionGroups
    .filter((group) => positiveReactions.has(group.content))
    .reduce((total, group) => total + group.users.totalCount, 0)
}

function hasPriorCleanup(pr: PullRequest) {
  return pr.labels.nodes.some((label) => label.name === cleanupLabel)
}

function requireRepo(value: string | undefined) {
  if (!value) throw new Error("repo is required")
  const [owner, name] = value.split("/")
  if (!owner || !name) throw new Error(`Invalid repo ${value}; expected owner/name`)
  return { owner, name }
}

async function requireToken() {
  const envToken = process.env.GITHUB_TOKEN ?? process.env.GH_TOKEN
  if (envToken) return envToken

  const proc = Bun.spawn(["gh", "auth", "token"], {
    stdout: "pipe",
    stderr: "pipe",
  })
  const stdout = await new Response(proc.stdout).text()
  const stderr = await new Response(proc.stderr).text()
  const exitCode = await proc.exited
  if (exitCode === 0 && stdout.trim()) return stdout.trim()

  throw new Error(
    `GitHub authentication is required. Set GITHUB_TOKEN/GH_TOKEN or run gh auth login.\n${stderr.trim()}`,
  )
}

function requirePositiveInteger(name: string, value: string | undefined) {
  const parsed = Number(value)
  if (!Number.isInteger(parsed) || parsed <= 0) throw new Error(`${name} must be a positive integer`)
  return parsed
}

function requireNonNegativeInteger(name: string, value: string | undefined) {
  const parsed = Number(value)
  if (!Number.isInteger(parsed) || parsed < 0) throw new Error(`${name} must be a non-negative integer`)
  return parsed
}

function subtractMonths(date: Date, months: number) {
  const result = new Date(date)
  const day = result.getUTCDate()
  result.setUTCDate(1)
  result.setUTCMonth(result.getUTCMonth() - months)
  result.setUTCDate(
    Math.min(day, new Date(Date.UTC(result.getUTCFullYear(), result.getUTCMonth() + 1, 0)).getUTCDate()),
  )
  return result
}

function sleep(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

void main().catch((error) => {
  console.error("Error:", error)
  process.exit(1)
})

#!/usr/bin/env bun
// Fails when a GUI package file this branch adds or edits has any oxlint problem, including warn-level rules (anti-slop):
// a change that touches a file leaves the whole file clean. Untouched files and other packages are not checked.
// Usage: bun script/lint-changed.ts [base-ref]   (default: merge base with upstream/dev, origin/dev, or dev)
import { $ } from "bun"

type Diagnostic = {
  message: string
  code: string
  filename: string
  labels: { span: { line: number; column: number } }[]
}

const base = await resolveBase(process.argv[2] ?? process.env.LINT_BASE)
const tracked = (await $`git diff --name-only --diff-filter=ACMR ${base}`.text()).split("\n")
const untracked = (await $`git ls-files --others --exclude-standard`.text()).split("\n")
// The packages .oxlintrc.json applies the anti-slop rules to.
const packages = ["packages/app/", "packages/desktop/", "packages/gui-extensions/", "packages/ui/", "packages/session-ui/"]
const files = [...new Set([...tracked, ...untracked])].filter(
  (file) =>
    /\.(ts|tsx)$/.test(file) && packages.some((prefix) => file.startsWith(prefix)) && Bun.file(file).size > 0,
)

if (files.length === 0) {
  console.log(`lint:changed: no changed TypeScript files since ${base.slice(0, 10)}`)
  process.exit(0)
}

const report = JSON.parse(await $`bunx oxlint --format json ${files}`.nothrow().quiet().text()) as {
  diagnostics: Diagnostic[]
}

report.diagnostics.forEach((diagnostic) => {
  const span = diagnostic.labels[0]?.span
  console.log(`${diagnostic.filename}:${span?.line}:${span?.column}  ${diagnostic.code}  ${diagnostic.message}`)
})
