          includeComments: true,

          /**
           * Skip the trailing comments of the previous node.
           * This inserts a blank line after the last trailing comment.
           *
           * For example:
           *
           *     foo(); // trailing comment.
           *     // comment.
           *     bar();
           *
           * Get fixed to:
           *
           *     foo(); // trailing comment.
           *
           *     // comment.
           *     bar();
           * @param token The token to check.
           * @returns `true` if the token is not a trailing comment.
           * @private
           */
          filter(token) {
            if (isTokenOnSameLine(prevToken, token)) {
              prevToken = token
              return false
            }
            return true
          },
        })! || nextNode
      const insertText = isTokenOnSameLine(prevToken, nextToken)
        ? '\n\n'
        : '\n'

      return fixer.insertTextAfter(prevToken, insertText)
    },
  })
}

/**
 * Types of blank lines.
 * `any`, `never`, and `always` are defined.
 * Those have `verify` method to check and report statements.
 * @private
 */
const PaddingTypes = {
  any: { verify: verifyForAny },
  never: { verify: verifyForNever },
  always: { verify: verifyForAlways },
}

const MaybeMultilineStatementType: Record<string, NodeTestObject> = {
  'block-like': { test: isBlockLikeStatement },
  'expression': { test: isExpression },
  'return': newKeywordTester('ReturnStatement', 'return'),
  'export': newKeywordTester(
    [
      'ExportAllDeclaration',
      'ExportDefaultDeclaration',
      'ExportNamedDeclaration',
    ],
    'export',
  ),
  'var': newKeywordTester('VariableDeclaration', 'var'),
  'let': newKeywordTester('VariableDeclaration', 'let'),
  'const': newKeywordTester('VariableDeclaration', 'const'),
  'using': {
    test: node => node.type === 'VariableDeclaration'
      && (node.kind === 'using' || node.kind === 'await using'),
  },
  'type': newKeywordTester('TSTypeAliasDeclaration', 'type'),
}

/**
 * Types of statements.
 * Those have `test` method to check it matches to the given statement.
 * @private
 */
const StatementTypes: Record<string, NodeTestObject> = {
  '*': { test: (): boolean => true },
  'exports': { test: isCJSExport },
  'require': { test: isCJSRequire },
  'directive': { test: isDirectivePrologue },
  'iife': { test: isIIFEStatement },

  'block': newNodeTypeTester('BlockStatement'),
  'empty': newNodeTypeTester('EmptyStatement'),
  'function': newNodeTypeTester('FunctionDeclaration'),
  'ts-method': newNodeTypeTester('TSMethodSignature'),

  'break': newKeywordTester('BreakStatement', 'break'),
  'case': newKeywordTester('SwitchCase', 'case'),
  'class': newKeywordTester('ClassDeclaration', 'class'),
  'continue': newKeywordTester('ContinueStatement', 'continue'),
  'debugger': newKeywordTester('DebuggerStatement', 'debugger'),
  'default': newKeywordTester(
    ['SwitchCase', 'ExportDefaultDeclaration'],
    'default',
  ),
  'do': newKeywordTester('DoWhileStatement', 'do'),
  'for': newKeywordTester(
    [
      'ForStatement',
      'ForInStatement',
      'ForOfStatement',
    ],
    'for',
  ),
  'if': newKeywordTester('IfStatement', 'if'),
  'import': newKeywordTester('ImportDeclaration', 'import'),
  'switch': newKeywordTester('SwitchStatement', 'switch'),
  'throw': newKeywordTester('ThrowStatement', 'throw'),
  'try': newKeywordTester('TryStatement', 'try'),
  'while': newKeywordTester(
    ['WhileStatement', 'DoWhileStatement'],
    'while',
  ),
  'with': newKeywordTester('WithStatement', 'with'),

  'cjs-export': {
    test: (node, sourceCode) => node.type === 'ExpressionStatement'
      && node.expression.type === 'AssignmentExpression'
      && CJS_EXPORT.test(sourceCode.getText(node.expression.left)),
  },
  'cjs-import': {
    test: (node, sourceCode) => node.type === 'VariableDeclaration'
      && node.declarations.length > 0
      && node.declarations[0]?.init != null
      && CJS_IMPORT.test(sourceCode.getText(node.declarations[0].init)),
  },

  'enum': newKeywordTester(
    'TSEnumDeclaration',
    'enum',
  ),
  'interface': newKeywordTester(
    'TSInterfaceDeclaration',
    'interface',
  ),
  'function-overload': newNodeTypeTester('TSDeclareFunction'),
  ...Object.fromEntries(
    Object.entries(MaybeMultilineStatementType)
      .flatMap(([key, value]) => [
        [key, value],
        [
          `singleline-${key}`,
          {
            ...value,
            test: (node, sourceCode) => value.test(node, sourceCode) && isSingleLine(node),
          },
        ],
        [
          `multiline-${key}`,
          {
            ...value,
            test: (node, sourceCode) => value.test(node, sourceCode) && !isSingleLine(node),
          },
        ],
      ]),
  ),
}

/** Build the vendored padding rule with caller-owned, typed policy options. */
export default function createPaddingLineRule(options: RuleOptions): CreateRule {
return {
  meta: {
    type: 'layout',
    docs: {
      description: 'Require or disallow padding lines between statements',
    },
    fixable: 'whitespace',
    hasSuggestions: false,
    // This is intentionally an array schema as you can pass 0..n config objects
    schema: {
      $defs: {
        paddingType: {
          type: 'string',
          enum: Object.keys(PaddingTypes),
        },
        statementType: {
          type: 'string',
          enum: Object.keys(StatementTypes),
        },
        selectorOption: {
          type: 'object',
          properties: {
            selector: {
              type: 'string',
            },
            lineMode: {
              type: 'string',
              enum: ['any', 'singleline', 'multiline'],
            },
          },
          required: ['selector'],
          additionalProperties: false,
        },
        statementMatcher: {
          anyOf: [
            { $ref: '#/$defs/statementType' },
            { $ref: '#/$defs/selectorOption' },
          ],
        },
        statementOption: {
          anyOf: [
            { $ref: '#/$defs/statementMatcher' },
            {
              type: 'array',
              items: { $ref: '#/$defs/statementMatcher' },
              minItems: 1,
              uniqueItems: true,
              additionalItems: false,
            },
          ],
        },
      },
      type: 'array',
      additionalItems: false,
      items: {
        type: 'object',
        properties: {
          blankLine: { $ref: '#/$defs/paddingType' },
          prev: { $ref: '#/$defs/statementOption' },
          next: { $ref: '#/$defs/statementOption' },
        },
        additionalProperties: false,
        required: ['blankLine', 'prev', 'next'],
      },
    },
    messages: {
      unexpectedBlankLine: 'Unexpected blank line before this statement.',
      expectedBlankLine: 'Expected blank line before this statement.',
    },
  },
  create(context) {
    const sourceCode = context.sourceCode

    const selectorMatchedNodes = new Map<string, Set<ASTNode>>()
    const pendingPairs: { prevNode: ASTNode, nextNode: ASTNode }[] = []

    function collectSelectorOption(option: StatementOption): void {
      if (Array.isArray(option)) {
        for (const item of option)
          collectSelectorOption(item)
        return
      }

      if (!isSelectorOption(option))
        return

      selectorMatchedNodes.set(option.selector, new Set())
    }

    for (const configure of options) {
      collectSelectorOption(configure.prev)
      collectSelectorOption(configure.next)
    }

    type Scope = {
      upper: Scope
      prevNode: ASTNode | null
    } | null

    let scopeInfo: Scope = null

    /**
     * Processes to enter to new scope.
     * This manages the current previous statement.
     *
     * @private
     */
    function enterScope(): void {
      scopeInfo = {
        upper: scopeInfo,
        prevNode: null,
      }
    }

    /**
     * Processes to exit from the current scope.
     *
     * @private
     */
    function exitScope(): void {
      if (scopeInfo)
        scopeInfo = scopeInfo.upper
    }

    /**
     * Checks whether the given node matches the given type.
     * @param node The statement node to check.
     * @param type The statement type to check.
     * @returns `true` if the statement node matched the type.
     * @private
     */
    function match(node: ASTNode, type: StatementOption): boolean {
      let innerStatementNode = node

      while (innerStatementNode.type === 'LabeledStatement')
        innerStatementNode = innerStatementNode.body

      if (Array.isArray(type))
        return type.some(match.bind(null, innerStatementNode))

      if (isSelectorOption(type)) {
        const matchedNodes = selectorMatchedNodes.get(type.selector)
        if (!matchedNodes?.has(innerStatementNode))
          return false

        const lineMode = type.lineMode

        if (lineMode === 'singleline')
          return isSingleLine(innerStatementNode)
        else if (lineMode === 'multiline')
          return !isSingleLine(innerStatementNode)

        return true
      }
      else {
        const statementType = StatementTypes[type]
        if (statementType === undefined)
          throw new Error(`Padding rule invariant: unsupported statement type ${type}`)
        return statementType.test(innerStatementNode, sourceCode)
      }
    }

    /**
     * Finds the last matched configure from options.
     * @param prevNode The previous statement to match.
     * @param nextNode The current statement to match.
     * @returns The tester of the last matched configure.
     * @private
     */
    function getPaddingType(
      prevNode: ASTNode,
      nextNode: ASTNode,
    ): (typeof PaddingTypes)[keyof typeof PaddingTypes] {
      for (let i = options.length - 1; i >= 0; --i) {
        const configure = options[i]
        if (configure === undefined)
          throw new Error('Padding rule invariant: configuration entry is missing')
        if (
          match(prevNode, configure.prev)
          && match(nextNode, configure.next)
        ) {
          return PaddingTypes[configure.blankLine]
        }
      }
      return PaddingTypes.any
    }

    /**
     * Gets padding line sequences between the given 2 statements.
     * Comments are separators of the padding line sequences.
     * @param prevNode The previous statement to count.
     * @param nextNode The current statement to count.
     * @returns The array of token pairs.
     * @private
     */
    function getPaddingLineSequences(
      prevNode: ASTNode,
      nextNode: ASTNode,
    ): [Token, Token][] {
      const pairs: [Token, Token][] = []
      let prevToken: Token = getActualLastToken(prevNode, sourceCode)!

      if (nextNode.loc.start.line - prevToken.loc.end.line >= 2) {
        do {
          const token: Token = sourceCode.getTokenAfter(prevToken, {
            includeComments: true,
          })!

          if (token.loc.start.line - prevToken.loc.end.line >= 2)
            pairs.push([prevToken, token])

          prevToken = token
        } while (prevToken.range[0] < nextNode.range[0])
      }

      return pairs
    }

    /**
     * Verify padding lines between the given node and the previous node.
     * @param node The node to verify.
     *
     * @private
     */
    function verify(node: ASTNode): void {
      if (
        !node.parent
        || ![
          'BlockStatement',
          'Program',
          'StaticBlock',
          'SwitchCase',
          'SwitchStatement',
          'TSInterfaceBody',
          'TSModuleBlock',
          'TSTypeLiteral',
        ].includes(node.parent.type)
      ) {
        return
      }

      // Save this node as the current previous statement.
      const prevNode = scopeInfo!.prevNode

      // Verify.
      if (prevNode)
        pendingPairs.push({ prevNode, nextNode: node })

      scopeInfo!.prevNode = node
    }

    function verifyPendingPairs(): void {
      for (const { prevNode, nextNode } of pendingPairs) {
        const type = getPaddingType(prevNode, nextNode)
        const paddingLines = getPaddingLineSequences(prevNode, nextNode)

        type.verify(context, prevNode, nextNode, paddingLines)
      }
    }

    /**
     * Verify padding lines between the given node and the previous node.
     * Then process to enter to new scope.
     * @param node The node to verify.
     *
     * @private
     */
    function verifyThenEnterScope(node: ASTNode): void {
      verify(node)
      enterScope()
    }

    const selectorMatchListeners = Object.fromEntries(
      Array.from(selectorMatchedNodes.keys(), selector => [
        selector,
        (node: ASTNode): void => {
          selectorMatchedNodes.get(selector)?.add(node)
        },
      ]),
    )

    return {
      'Program': enterScope,
      'Program:exit': () => {
        verifyPendingPairs()
        exitScope()
      },
      'BlockStatement': enterScope,
      'BlockStatement:exit': exitScope,
      'SwitchStatement': enterScope,
      'SwitchStatement:exit': exitScope,
      'SwitchCase': verifyThenEnterScope,
      'SwitchCase:exit': exitScope,
      'StaticBlock': enterScope,
      'StaticBlock:exit': exitScope,

      'TSInterfaceBody': enterScope,
      'TSInterfaceBody:exit': exitScope,
      'TSModuleBlock': enterScope,
      'TSModuleBlock:exit': exitScope,
      'TSTypeLiteral': enterScope,
      'TSTypeLiteral:exit': exitScope,
      'TSDeclareFunction': verifyThenEnterScope,
      'TSDeclareFunction:exit': exitScope,
      'TSMethodSignature': verifyThenEnterScope,
      'TSMethodSignature:exit': exitScope,

      ':statement': verify,
      ...selectorMatchListeners,
    }
  },
}
}

#!/usr/bin/env bun

import path from "path"

const root = path.resolve(import.meta.dir, "..")
const proc = Bun.spawn(
  [
    "bun",
    "turbo",
    "typecheck",
    "--concurrency=1",
    "--force",
    "--continue=always",
    "--summarize",
    "--output-logs=errors-only",
  ],
  {
    cwd: root,
    stdout: "pipe",
    stderr: "pipe",
  },
)
const [stdout, stderr, exitCode] = await Promise.all([proc.stdout.text(), proc.stderr.text(), proc.exited])
const output = stdout + stderr
if (exitCode !== 0) {
  process.stdout.write(stdout)
  process.stderr.write(stderr)
  process.exit(exitCode)
}

const summary = output.match(/Summary:\s+(.+\.json)/)?.[1]?.trim()
if (!summary) {
  process.stdout.write(stdout)
  process.stderr.write(stderr)
  throw new Error("Turbo did not report a run summary")
}

const report = (await Bun.file(summary).json()) as {
  tasks: Array<{
    taskId: string
    execution: { startTime: number; endTime: number; exitCode: number } | null
  }>
}
const tasks = report.tasks
  .flatMap((task) =>
    task.execution
      ? [
          {
            task: task.taskId.replace(/#typecheck$/, ""),
            durationMs: task.execution.endTime - task.execution.startTime,
          },
        ]
      : [],
  )
  .sort((a, b) => b.durationMs - a.durationMs)
const total = tasks.reduce((duration, task) => duration + task.durationMs, 0)
const width = Math.max(...tasks.map((task) => task.task.length), "Package".length)

console.log(`Package${" ".repeat(width - "Package".length)}  Time    Share`)
tasks.forEach((task) => {
  const duration = `${(task.durationMs / 1000).toFixed(2)}s`.padStart(7)
  const share = `${((task.durationMs / total) * 100).toFixed(1)}%`.padStart(6)
  console.log(`${task.task.padEnd(width)}  ${duration}  ${share}`)
})
console.log(`\nTotal serial task time: ${(total / 1000).toFixed(2)}s`)
console.log(`Turbo summary: ${path.relative(root, summary)}`)

#!/usr/bin/env bun

import { mkdir } from "fs/promises"
import path from "path"

if (process.platform !== "darwin") throw new Error("System typecheck profiling currently supports macOS only")

const root = path.resolve(import.meta.dir, "..")
const startedAt = new Date()
const args = Bun.argv.slice(2)
const command = [
  "bun",
  "turbo",
  "typecheck",
  ...(args.some((arg) => arg.startsWith("--concurrency")) ? [] : ["--concurrency=3"]),
  ...args,
]
const before = systemSnapshot()
const proc = Bun.spawn(command, {
  cwd: root,
  stdin: "inherit",
  stdout: "inherit",
  stderr: "inherit",
})
const samples = [processTreeSnapshot(proc.pid, startedAt)]
const timer = setInterval(() => samples.push(processTreeSnapshot(proc.pid, startedAt)), 200)
const exitCode = await proc.exited
clearInterval(timer)
samples.push(processTreeSnapshot(proc.pid, startedAt))

const finishedAt = new Date()
const after = systemSnapshot()
const active = samples.filter((sample) => sample.processes > 0)
const report = {
  command,
  cwd: root,
  startedAt: startedAt.toISOString(),
  finishedAt: finishedAt.toISOString(),
  durationSeconds: (finishedAt.getTime() - startedAt.getTime()) / 1000,
  exitCode,
  summary: {
    peakCpuPercent: Math.max(0, ...active.map((sample) => sample.cpuPercent)),
    averageCpuPercent: average(active.map((sample) => sample.cpuPercent)),
    peakAggregateRssMB: Math.max(0, ...active.map((sample) => sample.aggregateRssMB)),
    peakProcesses: Math.max(0, ...active.map((sample) => sample.processes)),
    peakTsgoRelatedProcesses: Math.max(0, ...active.map((sample) => sample.tsgoRelatedProcesses)),
    swapDeltaMB: after.swapUsedMB - before.swapUsedMB,
    compressedMemoryDeltaMB: after.compressedMemoryMB - before.compressedMemoryMB,
    pageoutDelta: after.pageouts - before.pageouts,
  },
  system: { before, after },
  samples,
}

const directory = path.join(root, ".typecheck-profiles")
const file = path.join(directory, `${startedAt.toISOString().replaceAll(":", "-")}.json`)
await mkdir(directory, { recursive: true })
await Bun.write(file, JSON.stringify(report, null, 2) + "\n")

console.log(`
Typecheck profile
  Duration:       ${report.durationSeconds.toFixed(1)}s
  Average CPU:    ${report.summary.averageCpuPercent.toFixed(0)}%
  Peak CPU:       ${report.summary.peakCpuPercent.toFixed(0)}%
  Aggregate RSS:  ${report.summary.peakAggregateRssMB.toFixed(0)} MB
  Peak processes: ${report.summary.peakProcesses} (${report.summary.peakTsgoRelatedProcesses} tsgo-related)
  Swap delta:     ${signed(report.summary.swapDeltaMB)} MB
  Compressed:     ${signed(report.summary.compressedMemoryDeltaMB)} MB
  Pageouts:       ${signed(report.summary.pageoutDelta)}
  Report:         ${path.relative(root, file)}
`)

process.exit(exitCode)

function processTreeSnapshot(rootPID: number, startedAt: Date) {
  const processes = processList()
  const pids = new Set([rootPID])
  const pending = [rootPID]
  while (pending.length > 0) {
    const parent = pending.shift()
    processes
      .filter((process) => process.ppid === parent && !pids.has(process.pid))
      .forEach((process) => {
        pids.add(process.pid)
        pending.push(process.pid)
      })
  }
  const tree = processes.filter((process) => pids.has(process.pid))
  return {
    elapsedSeconds: (Date.now() - startedAt.getTime()) / 1000,
    processes: tree.length,
    tsgoRelatedProcesses: tree.filter((process) => /\btsgo\b/.test(process.command)).length,
    cpuPercent: sum(tree.map((process) => process.cpuPercent)),
    aggregateRssMB: sum(tree.map((process) => process.rssKB)) / 1024,
  }
}

function systemSnapshot() {
  const vm = text(["vm_stat"])
  const pageSize = Number(vm.match(/page size of (\d+) bytes/)?.[1] ?? 4096)
  const fields = Object.fromEntries(
    vm
      .split("\n")
      .map((line) => line.match(/^([^:]+):\s+(\d+)\.?$/))
      .filter((match): match is RegExpMatchArray => match !== null)
      .map((match) => [match[1], Number(match[2])]),
  )
  const swap = text(["sysctl", "-n", "vm.swapusage"])
  return {
    loadAverage: text(["sysctl", "-n", "vm.loadavg"]).trim(),
    thermalState: text(["pmset", "-g", "therm"]).trim(),
    swapUsedMB: Number(swap.match(/used = ([\d.]+)M/)?.[1] ?? 0),
    freeMemoryMB: ((fields["Pages free"] ?? 0) * pageSize) / 1024 / 1024,
    compressedMemoryMB: ((fields["Pages occupied by compressor"] ?? 0) * pageSize) / 1024 / 1024,
    pageouts: fields.Pageouts ?? 0,
    relevantProcesses: processList()
      .filter((process) =>
        /opencode|tsgo|tsserver|vtsls|eslintServer|tailwindcss-language-server/.test(process.command),
      )
      .sort((a, b) => b.rssKB - a.rssKB)
      .map(processSummary),
    topCpuProcesses: processList()
      .sort((a, b) => b.cpuPercent - a.cpuPercent)
      .slice(0, 15)
      .map(processSummary),
    topMemoryProcesses: processList()
      .sort((a, b) => b.rssKB - a.rssKB)
      .slice(0, 15)
      .map(processSummary),
  }
}

function processSummary(process: ReturnType<typeof processList>[number]) {
  return {
    pid: process.pid,
    ppid: process.ppid,
    rssMB: process.rssKB / 1024,
    cpuPercent: process.cpuPercent,
    command: process.command,
  }
}

function processList() {
  return text(["ps", "-axo", "pid=,ppid=,rss=,%cpu=,command="])
    .split("\n")
    .map((line) => line.trim().match(/^(\d+)\s+(\d+)\s+(\d+)\s+([\d.]+)\s+(.*)$/))
    .filter((match): match is RegExpMatchArray => match !== null)
    .map((match) => ({
      pid: Number(match[1]),
      ppid: Number(match[2]),
      rssKB: Number(match[3]),
      cpuPercent: Number(match[4]),
      command: match[5],
    }))
}

function text(command: string[]) {
  return Bun.spawnSync(command).stdout.toString()
}

function sum(values: number[]) {
  return values.reduce((total, value) => total + value, 0)
}

function average(values: number[]) {
  if (values.length === 0) return 0
  return sum(values) / values.length
}

function signed(value: number) {
  return `${value >= 0 ? "+" : ""}${value.toFixed(0)}`
}

#!/usr/bin/env bun

import { Script } from "@opencode/script"
import { mkdir, rm } from "node:fs/promises"
import path from "node:path"
import { fileURLToPath } from "node:url"

if (Script.channel !== "latest" || !/^\d+\.\d+\.\d+$/.test(Script.version)) {
  throw new Error("WinGet publishing requires a latest release version")
}

const root = fileURLToPath(new URL("..", import.meta.url))
const dryRun = process.argv.includes("--dry-run")
const token = process.env.WINGET_GITHUB_TOKEN
const cli = path.resolve(process.env.OPENCODE_CLI_DIST ?? path.join(root, "packages", "cli", "dist"))
const desktop = process.env.OPENCODE_DESKTOP_DIST
if (!desktop) throw new Error("OPENCODE_DESKTOP_DIST is required")
const outdir = path.join(cli, "winget")
const manifestVersion = "1.12.0"

const packages = [
  {
    identifier: "Anomaly.OpenCode",
    name: "OpenCode CLI",
    moniker: "opencode",
    description: "The open source AI coding agent for the terminal.",
    installer: [
      "InstallerType: zip",
      "NestedInstallerType: portable",
      "NestedInstallerFiles:",
      "- RelativeFilePath: opencode.exe",
      "  PortableCommandAlias: opencode",
      "Commands:",
      "- opencode",
    ],
    files: [
      { architecture: "x64", file: path.join(cli, "opencode-windows-x64-baseline.zip") },
      { architecture: "arm64", file: path.join(cli, "opencode-windows-arm64.zip") },
    ],
  },
  {
    identifier: "Anomaly.OpenCode.Desktop",
    // Matches the display name the installer registers with Windows, without its version suffix.
    name: "OpenCode",
    moniker: "opencode-desktop",
    description: "The open source AI coding agent as a desktop app.",
    installer: [
      "InstallerType: nullsoft",
      "Scope: user",
      "UpgradeBehavior: install",
      // electron-builder derives the NSIS uninstall key from the production app ID, ai.opencode.desktop.
      "ProductCode: d074f30d-5f88-5885-b075-be1348cc7676",
      "Protocols:",
      "- opencode",
    ],
    files: [
