    `PackageVersion: ${Script.version}`,
  ]
  const footer = (type: string) => [`ManifestType: ${type}`, `ManifestVersion: ${manifestVersion}`, ""]
  const installers = await Promise.all(
    input.files.map(async (item) => {
      const file = Bun.file(item.file)
      if (!(await file.exists()) || !file.size) throw new Error(`Missing WinGet installer: ${item.file}`)
      const sha256 = new Bun.CryptoHasher("sha256")
      for await (const chunk of file.stream()) sha256.update(chunk)
      return [
        `- Architecture: ${item.architecture}`,
        `  InstallerUrl: https://opencode.ai/files/bin/${encodeURIComponent(Script.version)}/${path.basename(item.file)}`,
        `  InstallerSha256: ${sha256.digest("hex").toUpperCase()}`,
      ]
    }),
  )
  const manifests = {
    [`${input.identifier}.yaml`]: [...header("version"), "DefaultLocale: en-US", ...footer("version")],
    [`${input.identifier}.installer.yaml`]: [
      ...header("installer"),
      ...input.installer,
      `ReleaseDate: ${new Date().toISOString().slice(0, 10)}`,
      "Installers:",
      ...installers.flat(),
      ...footer("installer"),
    ],
    [`${input.identifier}.locale.en-US.yaml`]: [
      ...header("defaultLocale"),
      "PackageLocale: en-US",
      // Matches the publisher the desktop installer registers with Windows.
      "Publisher: OpenCode",
      "PublisherUrl: https://anoma.ly/",
      "PublisherSupportUrl: https://github.com/anomalyco/opencode/issues",
      "PrivacyUrl: https://opencode.ai/legal/privacy-policy",
      `PackageName: ${input.name}`,
      "PackageUrl: https://opencode.ai/",
      "License: MIT",
      "LicenseUrl: https://github.com/anomalyco/opencode/blob/HEAD/LICENSE",
      `ShortDescription: ${input.description}`,
      `Moniker: ${input.moniker}`,
      "Tags:",
      "- ai",
      "- coding-agent",
      "- developer-tools",
      "Documentations:",
      "- DocumentLabel: Docs",
      "  DocumentUrl: https://opencode.ai/docs/",
      ...footer("defaultLocale"),
    ],
  }
  const files = Object.fromEntries(Object.entries(manifests).map(([name, lines]) => [name, lines.join("\n")]))
  await mkdir(directory, { recursive: true })
  await Promise.all(Object.entries(files).map(([name, content]) => Bun.write(path.join(directory, name), content)))
  return { identifier: input.identifier, directory, files }
}

// Opens the pull request from the token owner's fork, the only way to contribute to microsoft/winget-pkgs.
async function submit(input: Awaited<ReturnType<typeof prepare>>) {
  const upstream = "microsoft/winget-pkgs"
  const folder = ["manifests", "a", ...input.identifier.split("."), Script.version].join("/")
  const branch = `${input.identifier}-${Script.version}`
  if ((await github(`/repos/${upstream}/contents/${folder}`)).status === 200) {
    console.log(`${input.identifier} ${Script.version} is already in ${upstream}`)
    return
  }
  const fork: { owner: { login: string }; full_name: string } = await json(
    await github(`/repos/${upstream}/forks`, { method: "POST", body: { default_branch_only: true } }),
  )
  const pulls: unknown[] = await json(
    await github(`/repos/${upstream}/pulls?state=all&head=${encodeURIComponent(`${fork.owner.login}:${branch}`)}`),
  )
  if (pulls.length) {
    console.log(`${input.identifier} ${Script.version} already has a pull request`)
    return
  }
  // Forks share objects with their upstream, so the branch can start from upstream master without syncing the fork.
  const head: { object: { sha: string } } = await json(await github(`/repos/${upstream}/git/ref/heads/master`))
  const base: { tree: { sha: string } } = await json(await github(`/repos/${upstream}/git/commits/${head.object.sha}`))
  const tree: { sha: string } = await json(
    await github(`/repos/${fork.full_name}/git/trees`, {
      method: "POST",
      body: {
        base_tree: base.tree.sha,
        tree: Object.entries(input.files).map(([name, content]) => ({
          path: `${folder}/${name}`,
          mode: "100644",
          type: "blob",
          content,
        })),
      },
    }),
  )
  const title = `New version: ${input.identifier} version ${Script.version}`
  const commit: { sha: string } = await json(
    await github(`/repos/${fork.full_name}/git/commits`, {
      method: "POST",
      body: { message: title, tree: tree.sha, parents: [head.object.sha] },
    }),
  )
  const created = await github(`/repos/${fork.full_name}/git/refs`, {
    method: "POST",
    body: { ref: `refs/heads/${branch}`, sha: commit.sha },
  })
  // A retried release can find the branch from an attempt that failed before opening its pull request.
  await json(
    created.status === 422
      ? await github(`/repos/${fork.full_name}/git/refs/heads/${branch}`, {
          method: "PATCH",
          body: { sha: commit.sha, force: true },
        })
      : created,
  )
  const run = process.env.GITHUB_RUN_ID
    ? `${process.env.GITHUB_SERVER_URL}/${process.env.GITHUB_REPOSITORY}/actions/runs/${process.env.GITHUB_RUN_ID}`
    : undefined
  const pull: { html_url: string } = await json(
    await github(`/repos/${upstream}/pulls`, {
      method: "POST",
      body: {
        title,
        head: `${fork.owner.login}:${branch}`,
        base: "master",
        body: `Published by the [OpenCode](https://github.com/anomalyco/opencode) release workflow${run ? ` in ${run}` : ""}.`,
      },
    }),
  )
  console.log(`Opened ${pull.html_url}`)
}

function github(route: string, init?: { method?: string; body?: unknown }) {
  return fetch(`https://api.github.com${route}`, {
    method: init?.method ?? "GET",
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
    },
    body: init?.body === undefined ? undefined : JSON.stringify(init.body),
  })
}

async function json(response: Response) {
  if (!response.ok) throw new Error(`GitHub ${response.url} returned ${response.status}: ${await response.text()}`)
  return response.json()
}

#!/usr/bin/env bun

import { Script } from "@opencode/script"
import { $ } from "bun"
import { fileURLToPath } from "url"

console.log("=== publishing ===\n")

const dir = fileURLToPath(new URL("..", import.meta.url))
process.chdir(dir)
const tag = `v${Script.version}`

// Beta dogfoods the desktop app. The CLI and SDK packages ship from dev.
if (Script.channel === "beta") {
  console.log("\n=== desktop ===\n")
  await $`bun ./packages/desktop/scripts/publish.ts`
  process.exit(0)
}

const pkgjsons = await Array.fromAsync(
  new Bun.Glob("**/package.json").scan({
    absolute: true,
  }),
).then((arr) => arr.filter((x) => !x.includes("node_modules") && !x.includes("dist")))

async function prepareReleaseFiles() {
  for (const file of pkgjsons) {
    let pkg = await Bun.file(file).text()
    pkg = pkg.replaceAll(/"version": "[^"]+"/g, `"version": "${Script.version}"`)
    console.log("updated:", file)
    await Bun.file(file).write(pkg)
  }

  await $`bun install`
}

async function writeChangelog() {
  const notes = process.env["OPENCODE_RELEASE_NOTES"]?.trim()
  if (!notes) return
  const file = Bun.file("CHANGELOG.md")
  const text = await file.text()
  const lines = text.split("\n")
  if (lines.some((line) => line === `## ${tag}` || line.startsWith(`## ${tag} `))) return
  const index = lines.findIndex((line) => line.startsWith("## "))
  const head = (index === -1 ? lines : lines.slice(0, index)).join("\n").trimEnd()
  const rest = index === -1 ? "" : lines.slice(index).join("\n")
  const entry = `## ${tag} — ${new Date().toISOString().slice(0, 10)}\n\n${notes}\n`
  await file.write(`${head}\n\n${entry}${rest ? `\n${rest}` : ""}`)
}

if (Script.release && !Script.preview) {
  await $`git fetch origin --tags`
  await $`git switch --detach`
}

await prepareReleaseFiles()

if (Script.release) await $`bun ./packages/desktop/scripts/publish.ts --dry-run`

console.log("\n=== schema ===\n")
await $`bun ./packages/schema/script/publish.ts`

console.log("\n=== codemode ===\n")
await $`bun ./packages/codemode/script/publish.ts`

console.log("\n=== theme ===\n")
await $`bun ./packages/theme/script/publish.ts`

console.log("\n=== ai ===\n")
await $`bun ./packages/ai/script/publish.ts`

console.log("\n=== util ===\n")
await $`bun ./packages/util/script/publish.ts`

console.log("\n=== protocol ===\n")
await $`bun ./packages/protocol/script/publish.ts`

console.log("\n=== client ===\n")
await $`bun ./packages/client/script/publish.ts`

console.log("\n=== cli ===\n")
await $`bun ./packages/cli/script/publish.ts`

console.log("\n=== plugin ===\n")
await $`bun ./packages/plugin/script/publish.ts`

console.log("\n=== plugin-browser ===\n")
await $`bun ./packages/plugin-browser/script/publish.ts`

console.log("\n=== core ===\n")
await $`bun ./packages/core/script/publish.ts`

console.log("\n=== simulation ===\n")
await $`bun ./packages/simulation/script/publish.ts`

console.log("\n=== server ===\n")
await $`bun ./packages/server/script/publish.ts`

console.log("\n=== sdk ===\n")
await $`bun ./packages/sdk/script/publish.ts`

console.log("\n=== ui ===\n")
await $`bun ./packages/ui/script/publish.ts`

if (Script.release && !Script.preview) {
  if ((await $`git diff --quiet`.nothrow()).exitCode !== 0) await $`git commit -am "release: ${tag}"`
  await $`git tag -d ${tag}`.nothrow()
  await $`git tag ${tag}`
  await $`git push origin refs/tags/${tag} --force-with-lease --no-verify`
  await new Promise((resolve) => setTimeout(resolve, 5_000))
  await $`git fetch origin`
  await $`git checkout -B dev origin/dev`
  await prepareReleaseFiles()
  await writeChangelog()
  if ((await $`git diff --quiet`.nothrow()).exitCode !== 0) {
    // The release already published this code; a push-triggered dev publish of a version bump is wasted work.
    await $`git commit -am ${`sync release versions for ${tag} [skip ci]`}`
    await $`git push origin HEAD:dev --no-verify`
  }
}

if (Script.release) {
  console.log("\n=== desktop ===\n")
  await $`bun ./packages/desktop/scripts/publish.ts`
}

if (Script.release && Script.channel === "latest") {
  console.log("\n=== winget ===\n")
  // Everything else is published by now, and WinGet validation can reject a submission for reasons unrelated to the release.
  if ((await $`bun ./script/publish-winget.ts`.nothrow()).exitCode !== 0)
    console.log("::warning::WinGet submission failed; see the winget step output above")
}

#!/usr/bin/env bun

import { $ } from "bun"
import { parseArgs } from "util"

type Release = {
  tag_name: string
  draft: boolean
}

type Commit = {
  hash: string
  author: string | null
  message: string
  areas: Set<string>
}

type User = Map<string, Set<string>>
type Diff = {
  sha: string
  login: string | null
  message: string
}

const repo = process.env.GH_REPO ?? "anomalyco/opencode"
const bot = ["actions-user", "github-actions[bot]", "opencode", "opencode-agent[bot]"]
const team = [
  ...(await Bun.file(new URL("../.github/TEAM_MEMBERS", import.meta.url))
    .text()
    .then((x) => x.split(/\r?\n/).map((x) => x.trim()))
    .then((x) => x.filter((x) => x && !x.startsWith("#")))),
  ...bot,
]
const order = ["Core", "TUI", "Desktop", "SDK", "Extensions"] as const
const sections = {
  core: "Core",
  tui: "TUI",
  app: "Desktop",
  tauri: "Desktop",
  sdk: "SDK",
  plugin: "SDK",
  "extensions/vscode": "Extensions",
  github: "Extensions",
} as const

function ref(input: string) {
  if (input === "HEAD") return input
  if (input.startsWith("v")) return input
  if (input.match(/^\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/)) return `v${input}`
  return input
}

async function latest() {
  const data = await $`gh api "/repos/${repo}/releases?per_page=100"`.json()
  const release = (data as Release[]).find((item) => !item.draft)
  if (!release) throw new Error("No releases found")
  return release.tag_name.replace(/^v/, "")
}

async function diff(base: string, head: string) {
  const list: Diff[] = []
  for (let page = 1; ; page++) {
    const text =
      await $`gh api "/repos/${repo}/compare/${base}...${head}?per_page=100&page=${page}" --jq '.commits[] | {sha: .sha, login: .author.login, message: .commit.message}'`.text()
    const batch = text
      .split("\n")
      .filter(Boolean)
      .map((line) => JSON.parse(line) as Diff)
    if (batch.length === 0) break
    list.push(...batch)
    if (batch.length < 100) break
  }
  return list
}

function section(areas: Set<string>) {
  const priority = ["core", "tui", "app", "tauri", "sdk", "plugin", "extensions/vscode", "github"]
  for (const area of priority) {
    if (areas.has(area)) return sections[area as keyof typeof sections]
  }
  return "Core"
}

function type(message: string) {
  if (message.match(/fix/i)) return "Bugfixes"
  return "Improvements"
}

function reverted(commits: Commit[]) {
  const seen = new Map<string, Commit>()

  for (const commit of commits) {
    const match = commit.message.match(/^Revert "(.+)"$/)
    if (match) {
      const msg = match[1]!
      if (seen.has(msg)) seen.delete(msg)
      else seen.set(commit.message, commit)
      continue
    }

    const revert = `Revert "${commit.message}"`
    if (seen.has(revert)) {
      seen.delete(revert)
      continue
    }

    seen.set(commit.message, commit)
  }

  return [...seen.values()]
}

async function commits(from: string, to: string) {
  const base = ref(from)
  const head = ref(to)

  const data = new Map<string, { login: string | null; message: string }>()
  for (const item of await diff(base, head)) {
    data.set(item.sha, { login: item.login, message: item.message.split("\n")[0] ?? "" })
  }

  const log =
    await $`git log ${base}..${head} --format=%H -- packages/opencode packages/plugin packages/desktop packages/app sdks/vscode packages/extensions github`.text()

  const list: Commit[] = []
  for (const hash of log.split("\n").filter(Boolean)) {
    const item = data.get(hash)
    if (!item) continue
    if (item.message.match(/^(ignore:|test:|chore:|ci:|release:)/i)) continue

    const diff = await $`git diff-tree --no-commit-id --name-only -r ${hash}`.text()
    const areas = new Set<string>()

    for (const file of diff.split("\n").filter(Boolean)) {
      if (file.startsWith("packages/opencode/src/cli/cmd/")) areas.add("tui")
      else if (file.startsWith("packages/opencode/")) areas.add("core")
      else if (file.startsWith("packages/desktop/src-tauri/")) areas.add("tauri")
      else if (file.startsWith("packages/desktop/") || file.startsWith("packages/app/")) areas.add("app")
      else if (file.startsWith("packages/plugin/")) areas.add("sdk")
      else if (file.startsWith("sdks/vscode/") || file.startsWith("github/")) areas.add("extensions/vscode")
    }

    if (areas.size === 0) continue

    list.push({
      hash: hash.slice(0, 7),
      author: item.login,
      message: item.message,
      areas,
    })
  }

  return reverted(list)
}

async function contributors(from: string, to: string) {
  const base = ref(from)
  const head = ref(to)

  const users: User = new Map()
  for (const item of await diff(base, head)) {
    const title = item.message.split("\n")[0] ?? ""
    if (!item.login || team.includes(item.login)) continue
    if (title.match(/^(ignore:|test:|chore:|ci:|release:)/i)) continue
    if (!users.has(item.login)) users.set(item.login, new Set())
    users.get(item.login)!.add(title)
  }

  return users
}

async function published(to: string) {
  if (to === "HEAD") return
  const body = await $`gh release view ${ref(to)} --repo ${repo} --json body --jq .body`.text().catch(() => "")
  if (!body) return

  const lines = body.split(/\r?\n/)
  const start = lines.findIndex((line) => line.startsWith("**Thank you to "))
  if (start < 0) return
  return lines.slice(start).join("\n").trim()
}

async function thanks(from: string, to: string, reuse: boolean) {
  const release = reuse ? await published(to) : undefined
  if (release) return release.split(/\r?\n/)

  const users = await contributors(from, to)
  if (users.size === 0) return []

  const lines = [`**Thank you to ${users.size} community contributor${users.size > 1 ? "s" : ""}:**`]
  for (const [name, commits] of users) {
    lines.push(`- @${name}:`)
    for (const commit of commits) lines.push(`  - ${commit}`)
  }
  return lines
}

function format(from: string, to: string, list: Commit[], thanks: string[]) {
  const grouped = new Map<string, Map<string, string[]>>()
  for (const title of order) {
    grouped.set(
      title,
      new Map([
        ["Improvements", []],
        ["Bugfixes", []],
      ]),
    )
  }

  for (const commit of list) {
    const attr = commit.author && !team.includes(commit.author) ? ` (@${commit.author})` : ""
    grouped.get(section(commit.areas))!.get(type(commit.message))!.push(`- \`${commit.hash}\` ${commit.message}${attr}`)
  }

  const lines = [`Last release: ${ref(from)}`, `Target ref: ${to}`, ""]

  if (list.length === 0) {
    lines.push("No notable changes.")
  }

  for (const title of order) {
    const groups = grouped.get(title)
    if (!groups || [...groups.values()].every((entries) => entries.length === 0)) continue
    lines.push(`## ${title}`)
    const improvements = groups.get("Improvements")!
    const bugfixes = groups.get("Bugfixes")!
    if (bugfixes.length === 0) {
      lines.push(...improvements)
      lines.push("")
      continue
    }

    for (const [subtitle, entries] of groups) {
      if (entries.length === 0) continue
      lines.push(`### ${subtitle}`)
      lines.push(...entries)
      lines.push("")
    }
  }

  if (thanks.length > 0) {
    if (lines.at(-1) !== "") lines.push("")
    lines.push("## Community Contributors Input")
    lines.push("")
    lines.push(...thanks)
  }

  if (lines.at(-1) === "") lines.pop()
  return lines.join("\n")
}

if (import.meta.main) {
  const { values } = parseArgs({
    args: Bun.argv.slice(2),
    options: {
      from: { type: "string", short: "f" },
      to: { type: "string", short: "t", default: "HEAD" },
      help: { type: "boolean", short: "h", default: false },
    },
  })

  if (values.help) {
    console.log(`
Usage: bun script/raw-changelog.ts [options]

Options:
  -f, --from <version>   Starting version (default: latest non-draft GitHub release)
  -t, --to <ref>         Ending ref (default: HEAD)
  -h, --help             Show this help message

Examples:
  bun script/raw-changelog.ts
  bun script/raw-changelog.ts --from 1.0.200
  bun script/raw-changelog.ts -f 1.0.200 -t 1.0.205
`)
    process.exit(0)
  }

  const to = values.to!
  const from = values.from ?? (await latest())
  const list = await commits(from, to)
  console.log(format(from, to, list, await thanks(from, to, !values.from)))
}

#!/usr/bin/env bun

import { $ } from "bun"
import { OpenCode } from "@opencode/client"
import { Service } from "@opencode/client/service"
import { parse } from "@opencode/script/highlights"
import { rm } from "fs/promises"
import path from "path"
import { parseArgs } from "util"

const root = path.resolve(import.meta.dir, "..")
const review = path.join(root, "RELEASE_REVIEW.md")
const changelog = path.join(root, "UPCOMING_CHANGELOG.md")
const { values, positionals } = parseArgs({
  args: Bun.argv.slice(2),
  options: {
    from: { type: "string", short: "f" },
    to: { type: "string", short: "t", default: "HEAD" },
    print: { type: "boolean", default: false },
    help: { type: "boolean", short: "h", default: false },
  },
  allowPositionals: true,
})
const version = positionals[0] ?? "patch"

if (values.help) {
  console.log(`Usage: ./script/release.ts [major|minor|patch|version]
       ./script/release.ts --print [--from <tag>] [--to <ref>]

Generates release notes and a public API review, opens the result in your
editor, and asks for confirmation before triggering the release workflow.

The editor is selected from $VISUAL, then $EDITOR, and defaults to vim.

Options:
  -f, --from <tag>   Previous release tag (default: latest stable V2 tag)
  -t, --to <ref>     Ending ref (default: HEAD)
      --print        Print the generated review and exit without releasing`)
  process.exit(0)
}

const input = ["major", "minor", "patch"].includes(version)
  ? ["-f", `bump=${version}`]
  : /^\d+\.\d+\.\d+(?:[-.][0-9A-Za-z.-]+)?$/.test(version)
    ? ["-f", `version=${version}`]
    : undefined

if (!input || positionals.length > 1 || (!values.print && (values.from || values.to !== "HEAD"))) {
  console.error("Usage: ./script/release.ts [major|minor|patch|version]")
  console.error("       ./script/release.ts --print [--from <tag>] [--to <ref>]")
  process.exit(1)
}

process.chdir(root)

console.log("\n=== Generating changelog ===\n")
await rm(review, { force: true })
await $`git fetch origin "+refs/tags/v2.*:refs/tags/v2.*" "+refs/heads/v1:refs/remotes/origin/v1"`
const base =
  values.from ??
  (await $`git tag --list "v2.*" --sort=-version:refname`.text()).split("\n").find((tag) => /^v2\.\d+\.\d+$/.test(tag))
if (!base) throw new Error("No stable V2 release tag was found")
console.log(`Comparing ${commitRange(base, values.to)}`)
await generateReview(base, values.to)

if (!(await Bun.file(review).exists())) throw new Error("OpenCode did not create RELEASE_REVIEW.md")
if (values.print) {
  process.stdout.write(await Bun.file(review).text())
  process.exit(0)
}

const editor = Bun.spawn(["sh", "-c", 'exec ${VISUAL:-${EDITOR:-vim}} "$1"', "release", review], {
  cwd: root,
  env: process.env,
  stdin: "inherit",
  stdout: "inherit",
  stderr: "inherit",
})
if ((await editor.exited) !== 0) {
  console.error("Release cancelled because the editor exited with an error")
  process.exit(1)
}

const document = await Bun.file(review).text()
const notes = document.match(/<!-- changelog:start -->\s*([\s\S]*?)\s*<!-- changelog:end -->/)
if (!notes) throw new Error("Release review is missing its changelog markers")
const releaseNotes = notes[1].trim()
if (!releaseNotes) throw new Error("Release review has no changelog")
await Bun.write(changelog, `${releaseNotes}\n`)

const highlights = parse(releaseNotes)
highlights.problems.forEach((problem) => console.warn(`Warning: ${problem}`))
console.log(
  highlights.items.length
    ? `TUI highlights will show:\n${highlights.items.map((item) => `  - ${item.title}`).join("\n")}`
    : "TUI highlights will not show for this release",
)

const answer = prompt(`Trigger the ${version} release? [y/N]`)
if (answer?.trim().toLowerCase() !== "y" && answer?.trim().toLowerCase() !== "yes") {
  console.log("Release cancelled")
  process.exit(0)
}

await $`gh workflow run publish.yml --ref dev ${input} -f release_notes=${releaseNotes}`
console.log(`Triggered the ${version} release`)

async function generateReview(base: string, head: string) {
  const endpoint = await Service.ensure()
  const client = OpenCode.make({
    baseUrl: endpoint.url,
    headers: Service.headers(endpoint),
    fetch: ((request: RequestInfo | URL, init?: RequestInit) =>
      fetch(request, { ...init, timeout: false } as BunFetchRequestInit)) as typeof fetch,
  })
  const controller = new AbortController()
  const events = client.event.subscribe({ signal: controller.signal })[Symbol.asyncIterator]()
  const connected = await events.next()
  if (connected.done) throw new Error("OpenCode event stream disconnected")

  const session = await client.session.create({
    title: `Review ${version} release`,
    location: { directory: root },
    model: { providerID: "opencode", id: "gpt-5.6-sol", variant: "low" },
    permissions: [
      { action: "*", resource: "*", effect: "deny" },
      { action: "read", resource: "*", effect: "allow" },
      { action: "glob", resource: "*", effect: "allow" },
      { action: "grep", resource: "*", effect: "allow" },
      { action: "shell", resource: "git *", effect: "allow" },
      { action: "shell", resource: "gh *", effect: "allow" },
    ],
  })

  const completed = (async () => {
    while (true) {
      const next = await events.next()
      if (next.done) throw new Error("OpenCode event stream disconnected during release review")
      if (!("sessionID" in next.value.data) || next.value.data.sessionID !== session.id) continue
      if (next.value.type === "session.execution.succeeded") return
      if (next.value.type === "session.execution.failed") throw new Error(next.value.data.error.message)
      if (next.value.type === "session.execution.interrupted")
        throw new Error(`OpenCode release review was interrupted: ${next.value.data.reason}`)
    }
  })()

  try {
    await client.session.prompt({ sessionID: session.id, text: reviewPrompt(base, head) })
    await completed
    const messages = await client.message.list({ sessionID: session.id, limit: 100, order: "desc" })
    const response = messages.data.find((message) => message.type === "assistant")
    const text = response?.content.flatMap((part) => (part.type === "text" ? [part.text] : [])).join("\n")
    if (!text) throw new Error("OpenCode did not return a release review")
    await Bun.write(review, text)
  } finally {
    controller.abort()
    await events.return?.()
  }
}

// V1 history was merged into dev when V2 was promoted, so it must be excluded from the release range. Merges are skipped
// because dev only takes squash merges, and the promotion merge would otherwise show the whole V1 tree.
function commitRange(base: string, head: string) {
  return `--no-merges ${base}..${head} --not origin/v1`
}

function reviewPrompt(base: string, head: string) {
  return `Create a concise pre-release review for a maintainer.

The previous stable V2 release is ${base}. Inspect every relevant commit in \`git log ${commitRange(base, head)}\` and
read each commit's actual diff with \`git show\`. Do not use a whole-tree \`git diff\` between the endpoints, which
includes V1 history merged into dev. Do not compare against V1 release tags or commits outside that range. Do not rely
only on commit titles. Write a
user-facing changelog with sections for Core, TUI, Desktop, SDK, and Extensions, omitting empty sections and changes that
are entirely internal. Group bug fixes separately from improvements. Preserve community contributor attribution when it
is available from merged pull requests, but never thank authors listed in .github/TEAM_MEMBERS.

Start the changelog with a "### Highlights" section: the few changes worth telling people about, written for humans.
Pick 2 to 5 user-visible changes a user would notice, try, or share: new capabilities, clearly better workflows, or fixes
for problems many users hit. Merge related small changes into one highlight. Skip internal work, refactors, tests, CI,
dependency bumps, broad polish without one concrete outcome, and anything not usable in this release. When nothing
qualifies, omit the section instead of padding it. Order highlights by how much users will care.

Before writing a highlight, read its pull request with gh pr view and confirm the behavior in the diff. Name the exact
command, flag, setting, or place in the UI, and describe how to use it as the pull request does. Never invent, guess, or
embellish, and avoid vague claims like "better" or "more naturally". Write each highlight as one bullet with a few-word
Title Case title (lowercase short words like "and" or "to"), then one or two plain sentences in second person about what
you can now do and why it matters. Vary the sentence openings, and leave contributor thanks to the detailed
sections. For example:

- **Reopen Closed Tabs**: Right-click the new-session button in the tab bar to bring back a session you closed by
  mistake. ([#123](https://github.com/anomalyco/opencode/pull/123))

Every highlight must also appear in the detailed sections that follow. Use "###" for Highlights and each release section,
"####" for Improvements and Bug fixes, and never use "#" or "##" headings in the changelog, since each release is filed
under its own "##" heading.

Put the complete editable changelog between these markers, which must each appear exactly once outside code fences:

## Changelog

<!-- changelog:start -->
...changelog...
<!-- changelog:end -->

Then add a "## Public surface audit" with "### HTTP API", "### Plugin API", and "### Other risks". Report added,
removed, or changed public HTTP routes, schemas, generated client methods, plugin hooks, plugin methods, RPC and tool
contracts, plus any other compatibility risk. Name each affected route or symbol and explain its impact. Write
"None found." under groups without changes. This is an audit, not a second changelog.

Return only the complete Markdown review in your response. Do not modify any files.`
}

#!/usr/bin/env bun
// The GUI extension SDK is learned from editor hovers and the guide, so both are checked. Fails, naming each file and
// line, when in `packages/gui-extensions/src/sdk`:
// - an exported declaration, an interface member, a field of an object type (an option, a result, a union member), or
//   a member of an exported object such as `Store.global` has no doc comment;
// - a documented function or method leaves a parameter without `@param`, or names one it does not have.
// It also fails when a code block of the guide (`packages/gui-extensions/README.md`) marked `<!-- source: path -->` (a
// whole file of a shipping extension) or `<!-- source: path#name -->` (a top-level declaration or call named `name`,
// else the first nested match, with the comments directly above it) differs from that source, or when the
// guide or the package's AGENTS.md names a `ctx.<member>` no context declares.
// Usage: bun script/sdk-docs.ts
import path from "node:path"
import { Glob } from "bun"
import ts from "typescript"

const root = path.resolve(import.meta.dir, "..")
const pkg = path.join(root, "packages/gui-extensions")
const sdk = path.join(pkg, "src/sdk")

const problems: string[] = []
const counts = { declarations: 0, members: 0, parameters: 0, blocks: 0 }

const files = [...new Glob("**/*.{ts,tsx}").scanSync(sdk)]
  .filter((file) => !/\.(test|typecheck)\.tsx?$/.test(file))
  .toSorted()
  .map((file) => path.join(sdk, file))

const sources = await Promise.all(files.map(async (file) => parse(file, await Bun.file(file).text())))

sources.forEach((source) => source.statements.forEach((statement) => checkStatement(source, statement)))
await checkGuide()

problems.forEach((problem) => console.log(problem))
console.log(
  `sdk-docs: ${counts.declarations} declarations, ${counts.members} members and ${counts.parameters} parameters ` +
    `documented in ${files.length} files; ${counts.blocks} guide blocks match their source; ${problems.length} problem(s)`,
)
process.exit(problems.length > 0 ? 1 : 0)

function checkStatement(source: ts.SourceFile, statement: ts.Statement) {
  if (!exported(statement)) return

  const name = describe(statement)

  if (ts.isVariableStatement(statement)) {
    documented(source, statement, name, "declarations")
    statement.declarationList.declarations.forEach((declaration) => {
      if (declaration.type) checkTypes(source, declaration.type, name)

      if (declaration.initializer) checkInitializer(source, declaration.initializer, name)
    })

    return
  }

  if (name === undefined) return

  documented(source, statement, name, "declarations")

  if (ts.isFunctionDeclaration(statement)) return checkSignature(source, statement, name)

  if (ts.isInterfaceDeclaration(statement)) return checkMembers(source, statement.members, name)

  if (ts.isTypeAliasDeclaration(statement)) return checkTypes(source, statement.type, name)

  if (ts.isEnumDeclaration(statement))
    statement.members.forEach((member) =>
      documented(source, member, `${name}.${member.name.getText(source)}`, "members"),
    )
}

/** An exported const: the type arguments of its initializer, or each member of an object literal such as `Store`. */
function checkInitializer(source: ts.SourceFile, initializer: ts.Expression, owner: string) {
  if (!ts.isObjectLiteralExpression(initializer)) return checkTypes(source, initializer, owner)

  initializer.properties.forEach((property) => {
    const name = `${owner}.${property.name?.getText(source) ?? "…"}`

    documented(source, property, name, "members")

    const value = ts.isPropertyAssignment(property) ? property.initializer : property

    if (ts.isArrowFunction(value) || ts.isFunctionExpression(value) || ts.isMethodDeclaration(value))
      checkSignature(source, value, name, property)
  })
}

function checkMembers(source: ts.SourceFile, members: ts.NodeArray<ts.TypeElement>, owner: string) {
  members.forEach((member) => {
    if (ts.isIndexSignatureDeclaration(member)) return checkTypes(source, member.type, owner)

    const name = `${owner}.${member.name?.getText(source) ?? "(call)"}`

    documented(source, member, name, "members")

    if (ts.isMethodSignature(member) || ts.isCallSignatureDeclaration(member))
      return checkSignature(source, member, name)

    if (ts.isPropertySignature(member) && member.type) checkTypes(source, member.type, name)
  })
}

/** A function or method: a `@param` per parameter, and the object types of its parameters and result. */
function checkSignature(source: ts.SourceFile, signature: ts.SignatureDeclaration, name: string, host?: ts.Node) {
  checkParameters(source, signature, name, host)
  signature.parameters.forEach((parameter) => parameter.type && checkTypes(source, parameter.type, name))

  if (signature.type) checkTypes(source, signature.type, name)
}

/**
 * Every object type within a type: option objects, results and union members. A conditional type's `extends` clause is
 * a pattern, not a shape anyone writes, and a function's body is implementation.
 */
function checkTypes(source: ts.SourceFile, node: ts.Node, owner: string) {
  if (ts.isTypeLiteralNode(node)) return checkMembers(source, node.members, owner)

  if (ts.isConditionalTypeNode(node))
    return [node.checkType, node.trueType, node.falseType].forEach((type) => checkTypes(source, type, owner))

  if (ts.isArrowFunction(node) || ts.isFunctionExpression(node)) {
    node.parameters.forEach((parameter) => parameter.type && checkTypes(source, parameter.type, owner))

    if (node.type) checkTypes(source, node.type, owner)

    return
  }

  ts.forEachChild(node, (child) => checkTypes(source, child, owner))
}

/** Each parameter has a `@param`, and no `@param` names a parameter the signature lacks. */
function checkParameters(source: ts.SourceFile, signature: ts.SignatureDeclaration, name: string, host?: ts.Node) {
  const names = signature.parameters.map((parameter) => parameter.name.getText(source))
  const tags = docs(host ?? signature).flatMap((doc) => (doc.tags ?? []).filter(ts.isJSDocParameterTag))

  signature.parameters.forEach((parameter, index) => {
    if (tags.some((tag) => tag.name.getText(source) === names[index])) return void counts.parameters++

    report(source, parameter, `${name}: parameter \`${names[index]}\` has no @param`)
  })
  tags.forEach((tag) => {
    if (!names.includes(tag.name.getText(source)))
      report(source, tag, `${name}: @param \`${tag.name.getText(source)}\` names no parameter`)
  })
}

function documented(source: ts.SourceFile, node: ts.Node, name: string, kind: "declarations" | "members") {
  const described = docs(node).some((doc) => !!ts.getTextOfJSDocComment(doc.comment)?.trim())

  if (described) return void counts[kind]++

  report(source, node, `${name} has no doc comment`)
}

function docs(node: ts.Node) {
  return ts.getJSDocCommentsAndTags(node).filter(ts.isJSDoc)
}

function exported(statement: ts.Statement) {
  return (
    ts.canHaveModifiers(statement) &&
    !!ts.getModifiers(statement)?.some((modifier) => modifier.kind === ts.SyntaxKind.ExportKeyword)
  )
}

/** The declared name, or undefined for a statement that declares nothing, such as `export * from`. */
function describe(statement: ts.Statement) {
  if (ts.isVariableStatement(statement))
    return statement.declarationList.declarations.map((declaration) => declaration.name.getText()).join(", ")

  if (
    ts.isFunctionDeclaration(statement) ||
    ts.isClassDeclaration(statement) ||
    ts.isInterfaceDeclaration(statement) ||
    ts.isTypeAliasDeclaration(statement) ||
    ts.isEnumDeclaration(statement)
  )
    return statement.name?.getText() ?? "default"

  return undefined
}

function report(source: ts.SourceFile, node: ts.Node, message: string) {
  const position = source.getLineAndCharacterOfPosition(node.getStart(source))

  problems.push(`${relative(source.fileName)}:${position.line + 1}:${position.character + 1}  ${message}`)
}

function relative(file: string) {
  return path.relative(root, file).replaceAll(path.sep, "/")
}

/** The guide's marked code blocks match their source, and every `ctx.*` the guide and AGENTS.md name exists. */
async function checkGuide() {
  const guide = path.join(pkg, "README.md")
  const lines = (await read(guide)).split("\n")

  const blocks = lines.flatMap((line, index) => {
    const marker = /^<!-- source: ([^#\s]+)(?:#([\w$]+))? -->$/.exec(line.trim())

    if (!marker?.[1]) return []

    const fence = lines.findIndex((candidate, next) => next > index && candidate.startsWith("```"))
    const close = lines.findIndex((candidate, next) => next > fence && candidate.trim() === "```")
    const at = `${relative(guide)}:${index + 1}`

    if (fence === -1 || close === -1 || lines.slice(index + 1, fence).some((between) => between.trim() !== "")) {
      problems.push(`${at}  the source marker is not followed by a code block`)

      return []
    }

    return [{ at, file: path.join(pkg, marker[1]), name: marker[2], code: lines.slice(fence + 1, close) }]
  })

  await Promise.all(
    blocks.map(async (block) => {
      const label = `${relative(block.file)}${block.name ? `#${block.name}` : ""}`
      const text = await Bun.file(block.file)
        .text()
        .catch(() => undefined)

      if (text === undefined) return void problems.push(`${block.at}  ${label}: no such file`)

      const expected = excerpt(block.file, text.replaceAll("\r\n", "\n"), block.name)

      if (!expected) return void problems.push(`${block.at}  ${label}: nothing by that name`)

      const row = Array.from({ length: Math.max(expected.length, block.code.length) }, (_, row) => row).find(
        (row) => expected[row] !== block.code[row],
      )

      if (row === undefined) return void counts.blocks++

      problems.push(`${block.at}  the code block differs from ${label} at its line ${row + 1}`)
    }),
  )

  const members = contextMembers()

  await Promise.all(
    [guide, path.join(pkg, "AGENTS.md")].map(async (doc) =>
      (await read(doc)).split("\n").forEach((line, index) =>
        [...line.matchAll(/\bctx\.([A-Za-z]+)/g)].forEach((match) => {
          if (match[1] && !members.has(match[1]))
            problems.push(`${relative(doc)}:${index + 1}  \`ctx.${match[1]}\` is not a context member`)
        }),
      ),
    ),
  )
}

async function read(file: string) {
  return (await Bun.file(file).text()).replaceAll("\r\n", "\n")
}

/**
 * The file's lines, or, for a name, the lines of its top-level match (else the first nested match), with the comment
 * lines directly above it, dedented.
 */
function excerpt(file: string, text: string, name: string | undefined) {
  const lines = text.replace(/\n$/, "").split("\n")

  if (!name) return lines

  const source = parse(file, text)
  const node = named(source, name)

  if (!node) return undefined

  const first = source.getLineAndCharacterOfPosition(node.getStart(source)).line
  const last = source.getLineAndCharacterOfPosition(node.getEnd()).line
  const above = lines.slice(0, first).findLastIndex((line) => !/^\s*(\/\/|\/\*|\*)/.test(line)) + 1
  const picked = lines.slice(above, last + 1)
  const indent = Math.min(...picked.filter((line) => line.trim()).map((line) => /^\s*/.exec(line)?.[0].length ?? 0))

  return picked.map((line) => line.slice(indent))
}

/** Top-level matches win; otherwise find the first nested declaration, property or call in source order. */
function named(node: ts.Node, name: string): ts.Node | undefined {
  if (ts.isSourceFile(node)) {
    const top = node.statements.find((statement) => matches(statement, name))

    if (top) return top
  }

  if (matches(node, name)) return node

  return ts.forEachChild(node, (child) => named(child, name))
}

function matches(node: ts.Node, name: string) {
  if (ts.isVariableStatement(node)) {
    return node.declarationList.declarations.some((declaration) => declaration.name.getText() === name)
  }

  if (
    (ts.isFunctionDeclaration(node) ||
      ts.isClassDeclaration(node) ||
      ts.isInterfaceDeclaration(node) ||
      ts.isTypeAliasDeclaration(node) ||
      ts.isPropertyAssignment(node) ||
      ts.isMethodDeclaration(node)) &&
    node.name?.getText() === name
  )
    return true

  if (
    ts.isExpressionStatement(node) &&
    ts.isCallExpression(node.expression) &&
    node.expression.expression.getText() === name
  )
    return true

  return false
}

function parse(file: string, text: string) {
  return ts.createSourceFile(
    file,
    text,
    ts.ScriptTarget.Latest,
    true,
    file.endsWith(".tsx") ? ts.ScriptKind.TSX : ts.ScriptKind.TS,
  )
}

/** Every member a window or main context exposes: `BaseContext`, `Context`, `SetupContext` and `MainContext`. */
function contextMembers() {
  const names = new Set(["BaseContext", "Context", "SetupContext", "MainContext"])

  return new Set(
    sources.flatMap((source) =>
      source.statements.flatMap((statement) =>
        ts.isInterfaceDeclaration(statement) && names.has(statement.name.text)
          ? statement.members.flatMap((member) => (member.name ? [member.name.getText(source)] : []))
          : [],
      ),
    ),
  )
}

#!/usr/bin/env bun

async function sendToPostHog(event: string, properties: Record<string, any>) {
  const key = process.env["POSTHOG_KEY"]

  if (!key) {
    console.warn("POSTHOG_API_KEY not set, skipping PostHog event")
    return
  }

  const response = await fetch("https://us.i.posthog.com/i/v0/e/", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      distinct_id: "download",
      api_key: key,
      event,
      properties: {
        ...properties,
      },
    }),
  }).catch(() => null)

  if (response && !response.ok) {
    console.warn(`PostHog API error: ${response.status}`)
  }
}

interface Asset {
  name: string
  download_count: number
}

interface Release {
  tag_name: string
  name: string
  assets: Asset[]
}

interface NpmDownloadsRange {
  start: string
  end: string
  package: string
  downloads: Array<{
    downloads: number
    day: string
  }>
}

async function fetchNpmDownloads(packageName: string): Promise<number> {
  try {
    // Use a range from 2020 to current year + 5 years to ensure it works forever
    const currentYear = new Date().getFullYear()
    const endYear = currentYear + 5
    const response = await fetch(`https://api.npmjs.org/downloads/range/2020-01-01:${endYear}-12-31/${packageName}`)
    if (!response.ok) {
      console.warn(`Failed to fetch npm downloads for ${packageName}: ${response.status}`)
      return 0
    }
    const data: NpmDownloadsRange = await response.json()
    return data.downloads.reduce((total, day) => total + day.downloads, 0)
  } catch (error) {
    console.warn(`Error fetching npm downloads for ${packageName}:`, error)
    return 0
  }
}

async function fetchReleases(): Promise<Release[]> {
  const releases: Release[] = []
  let page = 1
  const per = 100

  while (true) {
    const url = `https://api.github.com/repos/anomalyco/opencode/releases?page=${page}&per_page=${per}`

    const response = await fetch(url)
    if (!response.ok) {
      throw new Error(`GitHub API error: ${response.status} ${response.statusText}`)
    }

    const batch: Release[] = await response.json()
    if (batch.length === 0) break

    releases.push(...batch)
    console.log(`Fetched page ${page} with ${batch.length} releases`)

    if (batch.length < per) break
    page++
    await new Promise((resolve) => setTimeout(resolve, 1000))
  }

  return releases
}

function calculate(releases: Release[]) {
  let total = 0
  const stats = []

  for (const release of releases) {
    let downloads = 0
    const assets = []

    for (const asset of release.assets) {
      downloads += asset.download_count
      assets.push({
        name: asset.name,
        downloads: asset.download_count,
      })
    }

    total += downloads
    stats.push({
      tag: release.tag_name,
      name: release.name,
      downloads,
      assets,
    })
  }

  return { total, stats }
}

async function save(githubTotal: number, npmDownloads: number) {
  const file = "STATS.md"
  const date = new Date().toISOString().split("T")[0]
  const total = githubTotal + npmDownloads

  let previousGithub = 0
  let previousNpm = 0
  let previousTotal = 0
  let content = ""

  try {
    content = await Bun.file(file).text()
    const lines = content.trim().split("\n")

    for (let i = lines.length - 1; i >= 0; i--) {
      const line = lines[i].trim()
      if (line.startsWith("|") && !line.includes("Date") && !line.includes("---")) {
        const match = line.match(
          /\|\s*[\d-]+\s*\|\s*([\d,]+)\s*(?:\([^)]*\))?\s*\|\s*([\d,]+)\s*(?:\([^)]*\))?\s*\|\s*([\d,]+)\s*(?:\([^)]*\))?\s*\|/,
        )
        if (match) {
          previousGithub = parseInt(match[1].replace(/,/g, ""))
          previousNpm = parseInt(match[2].replace(/,/g, ""))
          previousTotal = parseInt(match[3].replace(/,/g, ""))
          break
        }
      }
    }
  } catch {
    content =
      "# Download Stats\n\n| Date | GitHub Downloads | npm Downloads | Total |\n|------|------------------|---------------|-------|\n"
  }

  const githubChange = githubTotal - previousGithub
  const npmChange = npmDownloads - previousNpm
  const totalChange = total - previousTotal

  const githubChangeStr =
    githubChange > 0
      ? ` (+${githubChange.toLocaleString()})`
      : githubChange < 0
        ? ` (${githubChange.toLocaleString()})`
        : " (+0)"
  const npmChangeStr =
    npmChange > 0 ? ` (+${npmChange.toLocaleString()})` : npmChange < 0 ? ` (${npmChange.toLocaleString()})` : " (+0)"
  const totalChangeStr =
    totalChange > 0
      ? ` (+${totalChange.toLocaleString()})`
      : totalChange < 0
        ? ` (${totalChange.toLocaleString()})`
        : " (+0)"
  const line = `| ${date} | ${githubTotal.toLocaleString()}${githubChangeStr} | ${npmDownloads.toLocaleString()}${npmChangeStr} | ${total.toLocaleString()}${totalChangeStr} |\n`

  if (!content.includes("# Download Stats")) {
    content =
      "# Download Stats\n\n| Date | GitHub Downloads | npm Downloads | Total |\n|------|------------------|---------------|-------|\n"
  }

  await Bun.write(file, content + line)
  await Bun.spawn(["bunx", "prettier", "--write", file]).exited

  console.log(
    `\nAppended stats to ${file}: GitHub ${githubTotal.toLocaleString()}${githubChangeStr}, npm ${npmDownloads.toLocaleString()}${npmChangeStr}, Total ${total.toLocaleString()}${totalChangeStr}`,
  )
}

console.log("Fetching GitHub releases for anomalyco/opencode...\n")

const releases = await fetchReleases()
console.log(`\nFetched ${releases.length} releases total\n`)

const { total: githubTotal } = calculate(releases)

console.log("Fetching npm all-time downloads for opencode-ai...\n")
const npmDownloads = await fetchNpmDownloads("opencode-ai")
console.log(`Fetched npm all-time downloads: ${npmDownloads.toLocaleString()}\n`)

await save(githubTotal, npmDownloads)

await sendToPostHog("download", {
  count: githubTotal,
  source: "github",
})

await sendToPostHog("download", {
  count: npmDownloads,
  source: "npm",
})

const totalDownloads = githubTotal + npmDownloads

console.log("=".repeat(60))
console.log(`TOTAL DOWNLOADS: ${totalDownloads.toLocaleString()}`)
console.log(`  GitHub: ${githubTotal.toLocaleString()}`)
console.log(`  npm: ${npmDownloads.toLocaleString()}`)
console.log("=".repeat(60))

console.log("-".repeat(60))
console.log(`GitHub Total: ${githubTotal.toLocaleString()} downloads across ${releases.length} releases`)
console.log(`npm Total: ${npmDownloads.toLocaleString()} downloads`)
console.log(`Combined Total: ${totalDownloads.toLocaleString()} downloads`)

import { createHash } from "node:crypto"
import { createReadStream } from "node:fs"
import path from "node:path"

type Artifact = {
  channel: string
  name: string
  distribution: string
  version: string
  metadata: Record<string, unknown>
}

export namespace UpdateArtifact {
  export async function publish(artifact: Artifact) {
    if (process.env.GITHUB_ACTIONS !== "true") {
      console.log("skipped update artifact publication outside GitHub Actions")
      return
    }
    const requestURL = process.env.ACTIONS_ID_TOKEN_REQUEST_URL
    const requestToken = process.env.ACTIONS_ID_TOKEN_REQUEST_TOKEN
    if (!requestURL || !requestToken) throw new Error("GitHub Actions OIDC is unavailable")

    const url = new URL(requestURL)
    url.searchParams.set("audience", "https://update.opencode.ai")
    const tokenResponse = await fetch(url, { headers: { Authorization: `Bearer ${requestToken}` } })
    if (!tokenResponse.ok) throw new Error(`Failed to request GitHub OIDC token: ${tokenResponse.status}`)
    const token: unknown = await tokenResponse.json()
    if (!isRecord(token) || typeof token.value !== "string")
      throw new Error("GitHub OIDC response did not include a token")

    for (const attempt of [0, 1, 2]) {
      const response = await fetch("https://opencode.ai/update/api/publish", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token.value}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(artifact),
      })
      if (response.ok) return
      // D1 can commit the upsert and still time out. Replaying the same artifact is safe.
      if (response.status >= 500 && attempt < 2) {
        await response.arrayBuffer()
        console.warn(`Update artifact publication returned ${response.status}; retrying`)
        await Bun.sleep((attempt + 1) * 1_000)
        continue
      }
      throw new Error(`Failed to publish update artifact: ${response.status} ${await response.text()}`)
    }
  }

  export async function upload(input: { version: string; files: string[]; dryRun?: boolean }) {
    const { PutObjectCommand, S3Client } = await import("@aws-sdk/client-s3")
    const client = input.dryRun ? undefined : new S3Client(await credentials())
    const prefix = `bin/${input.version}/`
    const base = `https://opencode.ai/files/bin/${encodeURIComponent(input.version)}/`
    try {
      return Object.fromEntries(
        await Promise.all(
          input.files.map(async (filepath) => {
            const file = Bun.file(filepath)
            const name = path.basename(filepath)
            if (!file.size) throw new Error(`Empty release file: ${filepath}`)
            const hash = createHash("sha256")
            for await (const chunk of file.stream()) hash.update(chunk)
            const metadata = { url: `${base}${encodeURIComponent(name)}`, sha256: hash.digest("hex"), size: file.size }
            console.log(`${input.dryRun ? "dry-run upload" : "upload"}: ${prefix}${name}`)
            if (client) {
              await client.send(
                new PutObjectCommand({
                  Bucket: "opencode-production-files",
                  Key: `${prefix}${name}`,
                  Body: createReadStream(filepath),
                  ContentLength: file.size,
                  ContentType: name.endsWith(".tar.gz") ? "application/gzip" : file.type || "application/octet-stream",
                  ContentDisposition: `attachment; filename="${name}"`,
                  CacheControl: "public, max-age=31536000, immutable",
                }),
              )
            }
            return [name, metadata] as const
          }),
        ),
      )
    } finally {
      client?.destroy()
    }
  }
}

function isRecord(input: unknown): input is Record<string, unknown> {
  return typeof input === "object" && input !== null && !Array.isArray(input)
}

async function credentials() {
  const account = process.env.CLOUDFLARE_ACCOUNT_ID
  const token = process.env.CLOUDFLARE_API_TOKEN
  if (!account || !token) throw new Error("CLOUDFLARE_ACCOUNT_ID and CLOUDFLARE_API_TOKEN are required")
  // R2 uses the token ID as its access key and SHA-256(token) as its secret.
  for (const scope of [`accounts/${account}`, "user"]) {
    const response = await fetch(`https://api.cloudflare.com/client/v4/${scope}/tokens/verify`, {
      headers: { Authorization: `Bearer ${token}` },
    })
    if (!response.ok) continue
    const data: unknown = await response.json()
    if (!isRecord(data) || data.success !== true || !isRecord(data.result) || typeof data.result.id !== "string")
      continue
    return {
      region: "auto",
      endpoint: `https://${account}.r2.cloudflarestorage.com`,
      credentials: {
        accessKeyId: data.result.id,
        secretAccessKey: createHash("sha256").update(token).digest("hex"),
      },
    }
  }
  throw new Error("Cloudflare token verification failed")
}

#!/usr/bin/env bun

import path from "node:path"

const args = process.argv.slice(2)
const usage = "Usage: bun run script/upgrade-opentui.ts [--snapshot] <version>"

if (args.includes("--help") || args.includes("-h")) {
  console.log(usage)
  process.exit(0)
}

const snapshotArg = args.find((arg) => arg.startsWith("--snapshot="))
const snapshot = args.includes("--snapshot") || snapshotArg !== undefined
const unknown = args.find((arg) => arg.startsWith("-") && arg !== "--snapshot" && !arg.startsWith("--snapshot="))
if (unknown) {
  console.error(`Unknown option: ${unknown}`)
  console.error(usage)
  process.exit(1)
}

const positional = args.filter((arg) => arg !== "--snapshot" && !arg.startsWith("--snapshot="))
const raw = snapshotArg?.slice("--snapshot=".length) || positional[0]
if (!raw || positional.length > (snapshotArg ? 0 : 1)) {
  console.error(usage)
  process.exit(1)
}

if (snapshotArg === "--snapshot=") {
  console.error("Missing snapshot version")
  console.error(usage)
  process.exit(1)
}

const ver = raw.replace(/^v/, "")
const root = path.resolve(import.meta.dir, "..")
const lockfile = path.join(root, "bun.lock")
const skip = new Set([".git", ".opencode", ".turbo", "dist", "node_modules"])
const keys = ["@opentui/core", "@opentui/keymap", "@opentui/solid"] as const

const files = (await Array.fromAsync(new Bun.Glob("**/package.json").scan({ cwd: root }))).filter(
  (file) => !file.split("/").some((part) => skip.has(part)),
)

const setVersion = (cur: string, kind: "dep" | "peer") => {
  if (cur === "catalog:" || cur.startsWith("workspace:")) return cur
  if (snapshot) return ver
  if (kind === "peer") return `>=${ver}`
  if (cur.startsWith(">=")) return `>=${ver}`
  if (cur.startsWith("^")) return `^${ver}`
  if (cur.startsWith("~")) return `~${ver}`
  return ver
}

const editDeps = (obj: unknown, kind: "dep" | "peer") => {
  if (!obj || typeof obj !== "object") return false
  const map = obj as Record<string, unknown>
  return keys
    .map((key) => {
      const cur = map[key]
      if (typeof cur !== "string") return false
      const next = setVersion(cur, kind)
      if (next === cur) return false
      map[key] = next
      return true
    })
    .some(Boolean)
}

const editCatalog = (obj: unknown) => {
  if (!obj || typeof obj !== "object") return false
  const map = obj as Record<string, unknown>
  return keys
    .map((key) => {
      const cur = map[key]
      if (typeof cur !== "string" || cur === ver) return false
      map[key] = ver
      return true
    })
    .some(Boolean)
}

const editOverrides = (obj: unknown) => {
  if (!obj || typeof obj !== "object") return false
  const map = obj as Record<string, unknown>
  return keys
    .map((key) => {
      const cur = map[key]
      if (typeof cur !== "string") return false
      const next = snapshot ? ver : "catalog:"
      if (next === cur) return false
      map[key] = next
      return true
    })
    .some(Boolean)
}

const out = (
  await Promise.all(
    files.map(async (rel) => {
      const file = path.join(root, rel)
      const txt = await Bun.file(file).text()
      const json = JSON.parse(txt)
      const hit = [
        editCatalog(json.workspaces?.catalog),
        editOverrides(json.overrides),
        editDeps(json.dependencies, "dep"),
        editDeps(json.devDependencies, "dep"),
        editDeps(json.peerDependencies, "peer"),
      ].some(Boolean)
      if (!hit) return null
      await Bun.write(file, `${JSON.stringify(json, null, 2)}\n`)
      return rel
    }),
  )
).filter((item): item is string => item !== null)

if (out.length === 0) {
  console.log(`No opentui manifest updates needed for ${ver}`)
}

if (out.length > 0) {
  console.log(`Updated opentui${snapshot ? " snapshot" : ""} to ${ver} in:`)
  for (const file of out) {
    console.log(`- ${file}`)
  }
}

console.log("Running bun install to update bun.lock...")
const install = Bun.spawn([process.execPath, "install"], {
  cwd: root,
  stdout: "inherit",
  stderr: "inherit",
})
const installCode = await install.exited
if (installCode !== 0) process.exit(installCode)

const fixed = await fixKnownLockfileIssues()
if (fixed.length > 0) {
  console.log("Removed stale opentui-spinner peer lockfile entries:")
  for (const item of fixed) {
    console.log(`- ${item}`)
  }
}

const stale = await findStaleLockfileEntries()
if (stale.length > 0) {
  console.error(`bun.lock still contains stale opentui versions after upgrading to ${ver}:`)
  for (const item of stale) {
    console.error(`- ${item.entry}: ${item.pkg}@${item.version}`)
  }
  process.exit(1)
}

console.log("bun.lock opentui versions are consistent")

async function fixKnownLockfileIssues() {
  const txt = await Bun.file(lockfile).text()
  const stale = findStaleLockfileEntriesInText(txt)
  if (stale.length === 0) return []
  if (stale.some((item) => !item.entry.startsWith("opentui-spinner/@opentui/"))) return []

  const removed = txt
    .split("\n")
    .map((line) => line.match(/^    "(opentui-spinner\/@opentui\/[^\"]+)": /)?.[1])
    .filter((item): item is string => item !== undefined)

  if (removed.length === 0) return []

  await Bun.write(
    lockfile,
    txt
      .split("\n")
      .filter((line) => !line.match(/^    "opentui-spinner\/@opentui\//))
      .join("\n"),
  )
  return removed
}

async function findStaleLockfileEntries() {
  return findStaleLockfileEntriesInText(await Bun.file(lockfile).text())
}

function findStaleLockfileEntriesInText(txt: string) {
  return Array.from(txt.matchAll(/^    "([^"]+)": \["(@opentui\/(?:core(?:-[^@"]+)?|keymap|solid))@([^"]+)"/gm))
    .map((match) => ({
      entry: match[1]!,
      pkg: match[2]!,
      version: match[3]!,
    }))
    .filter((item) => item.version !== ver)
}

// This method is called when your extension is deactivated
export function deactivate() {}

import * as vscode from "vscode"

const TERMINAL_NAME = "opencode"

export function activate(context: vscode.ExtensionContext) {
  const openNewTerminalDisposable = vscode.commands.registerCommand("opencode.openNewTerminal", async () => {
    await openTerminal()
  })

  const openTerminalDisposable = vscode.commands.registerCommand("opencode.openTerminal", async () => {
    // An opencode terminal already exists => focus it
    const existingTerminal = vscode.window.terminals.find((t) => t.name === TERMINAL_NAME)
    if (existingTerminal) {
      existingTerminal.show()
      return
    }

    await openTerminal()
  })

  let addFilepathDisposable = vscode.commands.registerCommand("opencode.addFilepathToTerminal", async () => {
    const fileRef = getActiveFile()
    if (!fileRef) {
      return
    }

    const terminal = vscode.window.activeTerminal
    if (!terminal) {
      return
    }

    if (terminal.name === TERMINAL_NAME) {
      terminal.sendText(fileRef, false)
      terminal.show()
    }
  })

  context.subscriptions.push(openNewTerminalDisposable, openTerminalDisposable, addFilepathDisposable)

  async function openTerminal() {
    // Create a new terminal in split screen
    const terminal = vscode.window.createTerminal({
      name: TERMINAL_NAME,
      iconPath: {
        light: vscode.Uri.file(context.asAbsolutePath("images/button-dark.svg")),
        dark: vscode.Uri.file(context.asAbsolutePath("images/button-light.svg")),
      },
      location: {
        viewColumn: vscode.ViewColumn.Beside,
        preserveFocus: false,
      },
      env: {
        OPENCODE_CALLER: "vscode",
      },
    })

    terminal.show()
    terminal.sendText("opencode")
  }

  function getActiveFile() {
    const activeEditor = vscode.window.activeTextEditor
    if (!activeEditor) {
      return
    }

    const document = activeEditor.document
    const workspaceFolder = vscode.workspace.getWorkspaceFolder(document.uri)
    if (!workspaceFolder) {
      return
    }

    // Get the relative path from workspace root
    const relativePath = vscode.workspace.asRelativePath(document.uri)
    let filepathWithAt = `@${relativePath}`

    // Check if there's a selection and add line numbers
    const selection = activeEditor.selection
    if (!selection.isEmpty) {
      // Convert to 1-based line numbers
      const startLine = selection.start.line + 1
      const endLine = selection.end.line + 1

      if (startLine === endLine) {
        // Single line selection
        filepathWithAt += `#L${startLine}`
      } else {
        // Multi-line selection
        filepathWithAt += `#L${startLine}-${endLine}`
      }
    }

    return filepathWithAt
  }
}

