describe("loadSource", () => {
  const original = globalThis.fetch
  afterEach(() => {
    globalThis.fetch = original
  })

  function memoryCache() {
    const entries = new Map<string, Response>()
    return {
      entries,
      cache: {
        match: async (key: string) => entries.get(key)?.clone(),
        put: async (key: string, response: Response) => void entries.set(key, response),
      } as unknown as Cache,
    }
  }

  function stub(body: string | undefined) {
    const calls: string[] = []
    globalThis.fetch = (async (input: string) => {
      calls.push(input)
      return body === undefined ? new Response("", { status: 500 }) : new Response(body)
    }) as unknown as typeof fetch
    return calls
  }

  test("fetches dev's CHANGELOG.md and serves the cached copy while fresh", async () => {
    const calls = stub(changelog)
    const { cache } = memoryCache()
    const waits: Promise<unknown>[] = []
    const ctx = { waitUntil: (promise: Promise<unknown>) => void waits.push(promise) }
    expect(await loadSource(ctx, cache)).toBe(changelog)
    expect(await loadSource(ctx, cache)).toBe(changelog)
    expect(calls).toEqual(["https://raw.githubusercontent.com/anomalyco/opencode/dev/CHANGELOG.md"])
    expect(waits).toHaveLength(0)
  })

  test("serves a stale copy and keeps it when revalidation fails", async () => {
    const { cache, entries } = memoryCache()
    entries.set(
      "https://opencode.ai/changelog/source.md",
      new Response("stale", { headers: { "x-opencode-changelog-fetched-at": String(Date.now() - 301_000) } }),
    )
    const calls = stub(undefined)
    const waits: Promise<unknown>[] = []
    expect(await loadSource({ waitUntil: (promise) => void waits.push(promise) }, cache)).toBe("stale")
    await Promise.all(waits)
    expect(calls).toHaveLength(1)
    expect(await entries.get("https://opencode.ai/changelog/source.md")?.clone().text()).toBe("stale")
  })

  test("resolves undefined when GitHub fails and nothing is cached", async () => {
    stub(undefined)
    expect(await loadSource({ waitUntil: () => {} }, memoryCache().cache)).toBeUndefined()
  })
})

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url)
    const cors = {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, HEAD, OPTIONS",
      "Access-Control-Allow-Headers":
        "Range, If-Range, If-Match, If-None-Match, If-Modified-Since, If-Unmodified-Since",
      "Access-Control-Expose-Headers":
        "Accept-Ranges, Content-Length, Content-Range, Content-Disposition, ETag, Last-Modified",
    }

    if (!url.pathname.startsWith("/files/")) {
      return new Response(null, { status: 404, headers: cors })
    }
    if (request.method === "OPTIONS") {
      return new Response(null, {
        status: 204,
        headers: { ...cors, "Access-Control-Max-Age": "86400" },
      })
    }
    if (request.method !== "GET" && request.method !== "HEAD") {
      return new Response(null, {
        status: 405,
        headers: { ...cors, Allow: "GET, HEAD, OPTIONS" },
      })
    }

    let key: string
    try {
      key = decodeURIComponent(url.pathname.slice("/files/".length))
    } catch {
      return new Response(null, { status: 400, headers: cors })
    }
    if (!key) return new Response(null, { status: 404, headers: cors })

    // Public object responses never vary by cookies, authorization, or origin.
    const cacheKey = new Request(url.href, { method: "GET" })
    const cacheControl = request.headers.get("Cache-Control") ?? ""
    const noStore = /\bno-store\b/i.test(cacheControl)
    const bypass = noStore || /\bno-cache\b|\bmax-age=0\b/i.test(cacheControl)
    if (
      !bypass &&
      !request.headers.has("If-Match") &&
      !request.headers.has("If-Unmodified-Since") &&
      !request.headers.has("If-Range")
    ) {
      const headers = new Headers()
      for (const name of ["If-None-Match", "If-Modified-Since", "Range"]) {
        const value = request.headers.get(name)
        if (value !== null) headers.set(name, value)
      }
      if (headers.has("If-None-Match")) headers.delete("If-Modified-Since")
      if (request.method === "HEAD") headers.delete("Range")
      const cached = await caches.default.match(new Request(cacheKey, { headers }))
      if (cached && !(request.method === "GET" && request.headers.has("Range") && cached.status === 200)) {
        if (request.method !== "HEAD") return cached
        await cached.body?.cancel()
        return new Response(null, cached)
      }
      await cached?.body?.cancel()
    }

    const object = await env.FILES.head(key)
    if (!object) {
      return new Response(null, {
        status: 404,
        headers: { ...cors, "Cache-Control": "no-store" },
      })
    }

    const headers = new Headers(cors)
    object.writeHttpMetadata(headers)
    headers.set("ETag", object.httpEtag)
    headers.set("Last-Modified", object.uploaded.toUTCString())
    headers.set("Accept-Ranges", "bytes")
    if (!headers.has("Content-Type")) headers.set("Content-Type", "application/octet-stream")
    if (!headers.has("Cache-Control")) headers.set("Cache-Control", "public, max-age=3600")

    const modified = Math.floor(object.uploaded.getTime() / 1000) * 1000
    const ifMatch = request.headers.get("If-Match")
    const ifUnmodifiedSince = request.headers.get("If-Unmodified-Since")
    if (
      (ifMatch !== null && !matches(ifMatch, object.httpEtag, false)) ||
      (ifMatch === null && ifUnmodifiedSince !== null && modified > Date.parse(ifUnmodifiedSince))
    ) {
      return new Response(null, { status: 412, headers })
    }
    const ifNoneMatch = request.headers.get("If-None-Match")
    const ifModifiedSince = request.headers.get("If-Modified-Since")
    if (
      (ifNoneMatch !== null && matches(ifNoneMatch, object.httpEtag, true)) ||
      (ifNoneMatch === null && ifModifiedSince !== null && modified <= Date.parse(ifModifiedSince))
    ) {
      return new Response(null, { status: 304, headers })
    }

    headers.set("Content-Length", String(object.size))
    if (request.method === "HEAD") return new Response(null, { headers })

    let range: { offset: number; length: number } | undefined
    const ifRange = request.headers.get("If-Range")
    const rangeHeader = request.headers.get("Range")
    // Ignore unsupported/malformed and multipart ranges; a full 200 is valid.
    const bytes = rangeHeader?.match(/^bytes=(\d*)-(\d*)$/)
    if (
      bytes &&
      (bytes[1] || bytes[2]) &&
      (ifRange === null ||
        ifRange === object.httpEtag ||
        (!ifRange.startsWith('"') && !ifRange.startsWith("W/") && modified <= Date.parse(ifRange)))
    ) {
      const offset = bytes[1] ? Number(bytes[1]) : Math.max(0, object.size - Number(bytes[2]))
      const end = bytes[1] && bytes[2] ? Math.min(Number(bytes[2]), object.size - 1) : object.size - 1
      if (offset >= object.size || end < offset) {
        headers.set("Content-Range", `bytes */${object.size}`)
        headers.set("Content-Length", "0")
        return new Response(null, { status: 416, headers })
      }
      range = { offset, length: end - offset + 1 }
      headers.set("Content-Range", `bytes ${offset}-${end}/${object.size}`)
      headers.set("Content-Length", String(range.length))
    }

    const body = await env.FILES.get(key, {
      range,
      onlyIf: { etagMatches: object.etag },
    })
    // An overwrite/delete between head and get must not mix metadata and bytes.
    if (!body || !("body" in body)) {
      return new Response(null, {
        status: 503,
        headers: { ...cors, "Cache-Control": "no-store", "Retry-After": "1" },
      })
    }
    const response = new Response(body.body, {
      status: range ? 206 : 200,
      headers,
      encodeBody: "manual",
    })
    // Cache only complete responses. Larger objects still stream directly from R2.
    if (
      !range &&
      !noStore &&
      object.size <= 512 * 1024 * 1024 &&
      !/\b(private|no-store|no-cache)\b/i.test(headers.get("Cache-Control")!)
    ) {
      ctx.waitUntil(
        caches.default.put(cacheKey, response.clone()).catch((error) => {
          console.error("Failed to cache public file", error)
        }),
      )
    }
    return response
  },
} satisfies ExportedHandler<{ FILES: R2Bucket }>

function matches(value: string, etag: string, weak: boolean) {
  return value.split(",").some((part) => {
    const tag = part.trim()
    return tag === "*" || (weak ? tag.replace(/^W\//, "") : tag) === etag
  })
}

import { createRemoteJWKSet, jwtVerify, type JWTPayload } from "jose"
import type { Pipeline } from "cloudflare:pipelines"
import semver from "semver"
import { stringify } from "yaml"

interface Env {
  DB: D1Database
  EVENTS: Pipeline
}

type ArtifactRow = {
  channel: string
  name: string
  distribution: string
  version: string
  metadata: string
  active: number
  minimum: number
  time_created: number
  time_updated: number
}

type Artifact = Omit<ArtifactRow, "metadata" | "active" | "minimum"> & {
  metadata: unknown
  active: boolean
  minimum: boolean
}

type ArtifactInput = Pick<ArtifactRow, "channel" | "name" | "distribution" | "version"> & {
  metadata: unknown
}

const identifier = /^[a-zA-Z0-9._-]{1,64}$/
const version = /^[a-zA-Z0-9.+_-]{1,128}$/
const select =
  "SELECT channel, name, distribution, version, metadata, active, minimum, time_created, time_updated FROM artifact"
const audience = "https://update.opencode.ai"
const githubKeys = createRemoteJWKSet(new URL("https://token.actions.githubusercontent.com/.well-known/jwks"))
// Clients poll every lookup path, and querying D1 on each request overloaded it.
// Cache the caller-independent reads per isolate; caller-specific selection still runs per request.
const readTtl = 60_000
const reads = new Map<string, { expires: number; value: Promise<unknown> }>()

export default {
  async fetch(request: Request, env: Env, ctx: Pick<ExecutionContext, "waitUntil">): Promise<Response> {
    const url = new URL(request.url)
    // The legacy hostname only exposes /admin, covered by its existing Access policy.
    const prefix =
      url.hostname !== "update.opencode.ai" && (url.pathname === "/update" || url.pathname.startsWith("/update/"))
        ? "/update"
        : ""
    const pathname = url.pathname.slice(prefix.length) || "/"
    ctx.waitUntil(
      env.EVENTS.send([
        {
          source: "update",
          type: "request",
          timestamp: new Date().toISOString(),
          payload: {
            method: request.method,
            path: pathname,
            useragent: request.headers.get("user-agent"),
            ip: request.headers.get("cf-connecting-ip"),
            cf_country: request.cf?.country,
            cf_colo: request.cf?.colo,
          },
        },
      ]).catch(() => console.error("Failed to send update request event to the data lake")),
    )

    if (pathname === "/") return json({ service: "opencode-update" })
    if (pathname === "/admin" && request.method === "GET") return admin(request, env, prefix)
    if (pathname === "/admin/activate" && request.method === "POST") return markArtifact(request, env, "active", prefix)
    if (pathname === "/admin/minimum" && request.method === "POST") return markArtifact(request, env, "minimum", prefix)
    if (pathname === "/admin/rollout" && request.method === "POST") return configureRollout(request, env, prefix)
    if (pathname === "/api/publish" && request.method === "POST") return publishArtifact(request, env)
    if (request.method !== "GET") return new Response("Method not allowed", { status: 405 })

    const [root, ...path] = pathname.split("/").filter(Boolean)
    if (root !== "api" || path.length < 1 || path.length > 4 || !path.every(validIdentifier)) {
      return new Response("Not found", { status: 404 })
    }

    // D1 rejects queries while the database is overloaded. Return a retryable 503 instead of a 1101 exception page.
    return lookup(request, env, url, path).catch((error) => {
      console.error("Update lookup failed", error)
      return json({ error: "Update service temporarily unavailable" }, 503, { "Retry-After": "60" })
    })
  },
} satisfies ExportedHandler<Env>

async function lookup(request: Request, env: Env, url: URL, path: string[]) {
  const resolved = resolveChannel(path[0])
  const agent = request.headers.get("User-Agent")?.match(/^opencode\/(?:([^/]+)\/([^/]+)\/cli|(.*))$/)
  const current = url.searchParams.get("current") ?? agent?.[2] ?? agent?.[3]
  const source = agent?.[1] ?? current?.match(/^v?0\.0\.0-(.+)-\d+(?:\.\d+)?(?:\+.*)?$/)?.[1]
  const caller = source === undefined || resolveChannel(source) === resolved ? current : undefined
  const rollout = await cachedRead(`rollout:${resolved}`, () =>
    env.DB.prepare("SELECT duration_hours FROM channel_rollout WHERE channel = ?")
      .bind(resolved)
      .first<{ duration_hours: number }>(),
  )
  const duration = (rollout?.duration_hours ?? 0) * 3_600_000
  const ip = request.headers.get("CF-Connecting-IP")
  const hash =
    duration && ip
      ? new DataView(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(`${resolved}:${ip}`))).getUint32(0)
      : undefined
  // Missing IPs wait for full rollout. The same IP keeps its position across releases.
  const now = Date.now()
  const cutoff = now - duration * (hash === undefined ? 1 : (hash + 1) / 2 ** 32)
  if (path.length === 4) {
    return artifactDistribution(env.DB, resolved, path[1], path[2], caller, cutoff, duration, now, path[3])
  }
  if (path.length === 1) return channel(env.DB, resolved, caller, cutoff, duration, now)
  if (path.length === 2) return artifactName(env.DB, resolved, path[1], caller, cutoff, duration, now)
  return artifactDistribution(env.DB, resolved, path[1], path[2], caller, cutoff, duration, now)
}

async function channel(
  db: D1Database,
  channel: string,
  current: string | undefined,
  cutoff: number,
  duration: number,
  now: number,
) {
  const rows = await candidates(db, "channel = ?", [channel])
  const artifacts = await selectArtifacts(db, rows, current, cutoff, duration, now)
  if (!artifacts.length) return json({ error: "Channel not found" }, 404)
  return updateResponse({ channel, artifacts: artifacts.map(decodeArtifact) })
}

async function artifactName(
  db: D1Database,
  channel: string,
  name: string,
  current: string | undefined,
  cutoff: number,
  duration: number,
  now: number,
) {
  const rows = await candidates(db, "channel = ? AND name = ?", [channel, name])
  const artifacts = await selectArtifacts(db, rows, current, cutoff, duration, now)
  if (!artifacts.length) return json({ error: "Artifact not found" }, 404)
  return updateResponse({ channel, name, artifacts: artifacts.map(decodeArtifact) })
}

async function artifactDistribution(
  db: D1Database,
  channel: string,
  name: string,
  distribution: string,
  current: string | undefined,
  cutoff: number,
  duration: number,
  now: number,
  manifest?: string,
) {
  const rows = await candidates(db, "channel = ? AND name = ? AND distribution = ?", [channel, name, distribution])
  const artifact = (await selectArtifacts(db, rows, current, cutoff, duration, now))[0]
  if (!artifact) return json({ error: "Artifact not found" }, 404)
  if (manifest) {
    const metadata = decodeMetadata(artifact.metadata)
    if (name === "desktop" && /^latest(?:-mac|-linux(?:-arm64)?)?\.yml$/.test(manifest)) {
      const value = isRecord(metadata) && isRecord(metadata.manifests) ? metadata.manifests[manifest.replace(/^latest/, "desktop")] : undefined
      if (!isRecord(value)) return json({ error: "Manifest not found" }, 404)
      return new Response(stringify({ ...value, version: artifact.version }), {
        headers: { "Content-Type": "application/yaml; charset=utf-8", "Cache-Control": "no-store" },
      })
    }
    const file = isRecord(metadata) && isRecord(metadata.files) ? metadata.files[manifest] : undefined
    if (!isRecord(file) || typeof file.url !== "string") return json({ error: "File not found" }, 404)
    return new Response(null, { status: 302, headers: { Location: file.url, "Cache-Control": "no-store" } })
  }
  return updateResponse(decodeArtifact(artifact))
}

// `active = 1 OR minimum = 1` scanned every published build under the primary-key prefix.
// Reading each partial index separately keeps the read proportional to the selected artifacts.
function candidates(db: D1Database, filter: string, values: string[]) {
  return cachedRead(`artifacts:${values.join("/")}`, () =>
    db
      .prepare(
        `${select} INDEXED BY artifact_active WHERE ${filter} AND active = 1
         UNION ALL
         ${select} INDEXED BY artifact_minimum WHERE ${filter} AND minimum = 1 AND active = 0
         ORDER BY name, distribution`,
      )
      .bind(...values, ...values)
      .all<ArtifactRow>()
      .then((result) => result.results),
  )
}

async function selectArtifacts(
  db: D1Database,
  rows: ArtifactRow[],
  current: string | undefined,
  cutoff: number,
  duration: number,
  now: number,
) {
  const caller = current === undefined ? undefined : releaseVersion(current)
  const artifacts = await Promise.all(
    rows
      .filter((row) => row.active === 1)
      .map(async (active) => {
        const minimum = rows.find(
          (row) => row.minimum === 1 && row.name === active.name && row.distribution === active.distribution,
        )
        const floor = minimum && releaseVersion(minimum.version)
        if (current !== undefined && minimum && (!floor || !caller || semver.lt(caller, floor))) return minimum
        if (active.time_created <= cutoff) return active
        const start = now >= active.time_created ? active.time_created : Math.floor(now / readTtl) * readTtl
        const windowFloor = Math.min(active.time_created - 1, Math.floor(start - duration))
        const previous =
          (await rolloutCandidates(db, active, windowFloor)).find((row) => row.time_created <= cutoff) ?? null
        // A rollout must not send an identified client back below its compatibility floor.
        if (current !== undefined && minimum) {
          const version = previous && releaseVersion(previous.version)
          if (!version || !floor || semver.lt(version, floor)) return minimum
        }
        return previous
      }),
  )
  return artifacts.filter((artifact) => artifact !== null)
}

function rolloutCandidates(db: D1Database, active: ArtifactRow, floor: number) {
  return cachedRead(
    `history:${active.channel}/${active.name}/${active.distribution}/${active.time_created}/${floor}`,
    () =>
      db
        .prepare(
          `SELECT * FROM (
             ${select} INDEXED BY artifact_rollout
             WHERE channel = ? AND name = ? AND distribution = ? AND time_created < ? AND time_created > ?
             ORDER BY time_created DESC, version DESC
           )
           UNION ALL
           SELECT * FROM (
             ${select} INDEXED BY artifact_rollout
             WHERE channel = ? AND name = ? AND distribution = ? AND time_created <= ?
             ORDER BY time_created DESC, version DESC LIMIT 1
           )`,
        )
        .bind(
          active.channel,
          active.name,
          active.distribution,
          active.time_created,
          floor,
          active.channel,
          active.name,
          active.distribution,
          floor,
        )
        .all<ArtifactRow>()
        .then((result) => result.results),
  )
}

async function configureRollout(request: Request, env: Env, prefix: string) {
  const invalid = validMutation(request)
  if (invalid) return invalid
  const form = await request.formData()
  const channel = form.get("channel")
  const input = form.get("duration_hours")
  const duration = typeof input === "string" && input.trim() ? Number(input) : NaN
  if (
    !validIdentifier(channel) ||
    channel === "next" ||
    !Number.isFinite(duration) ||
    duration < 0 ||
    !Number.isFinite(duration * 3_600_000)
  ) {
    return json({ error: "Channel and a non-negative rollout duration in hours are required" }, 400)
  }
  await env.DB.prepare(
    "INSERT INTO channel_rollout (channel, duration_hours) VALUES (?, ?) ON CONFLICT (channel) DO UPDATE SET duration_hours = excluded.duration_hours",
  )
    .bind(channel, duration)
    .run()
  return Response.redirect(new URL(`${prefix}/admin`, request.url), 303)
}

function releaseVersion(input: string) {
  // Preview builds use a hyphen before the run number. Normalize it to a numeric
  // prerelease identifier, and compare historical next builds in the beta channel.
  return semver.valid(
    input.replace(
      /^(v?0\.0\.0)-(next|beta|dev)-(\d+)(?=\.|$)/,
      (_, core, channel, build) => `${core}-${resolveChannel(channel)}.${build}`,
    ),
  )
}

