async function publishArtifact(request: Request, env: Env) {
  const claims = await verifyGitHub(request)
  if (claims instanceof Response) return claims
  const input: unknown = await request.json().catch(() => undefined)
  const artifact = parseArtifact(isRecord(input) ? input : {})
  if (artifact instanceof Response) return artifact
  if (!channelsForRef(claims.ref).includes(artifact.channel)) return json({ error: "Channel is not allowed" }, 403)
  if (!isRecord(artifact.metadata)) return json({ error: "Metadata must be an object" }, 400)
  await activate(env.DB, [
    {
      ...artifact,
      metadata: {
        ...artifact.metadata,
        github: {
          sha: claims.sha,
          run_id: claims.run_id,
          run_attempt: claims.run_attempt,
          actor: claims.actor,
          ref: claims.ref,
        },
      },
    },
  ])
  return json({ published: true })
}

async function markArtifact(request: Request, env: Env, flag: "active" | "minimum", prefix: string) {
  const invalid = validMutation(request)
  if (invalid) return invalid
  const form = await request.formData()
  const key = parseKey({
    channel: form.get("channel"),
    name: form.get("name"),
    distribution: form.get("distribution"),
    version: form.get("version"),
  })
  if (key instanceof Response) return key
  const enabled = flag === "minimum" && form.get("enabled") === "0" ? 0 : 1
  if (flag === "minimum" && enabled && !releaseVersion(key.version)) {
    return json({ error: "Minimum must have a comparable release version" }, 400)
  }
  const exists = await env.DB.prepare(
    "SELECT 1 FROM artifact WHERE channel = ? AND name = ? AND distribution = ? AND version = ?",
  )
    .bind(key.channel, key.name, key.distribution, key.version)
    .first()
  if (!exists) return json({ error: "Artifact not found" }, 404)
  await env.DB.batch([
    ...(enabled
      ? [
          env.DB.prepare(
            `UPDATE artifact SET ${flag} = 0 WHERE channel = ? AND name = ? AND distribution = ? AND ${flag} = 1`,
          ).bind(key.channel, key.name, key.distribution),
        ]
      : []),
    env.DB.prepare(
      `UPDATE artifact SET ${flag} = ?, time_updated = ? WHERE channel = ? AND name = ? AND distribution = ? AND version = ?`,
    ).bind(enabled, Date.now(), key.channel, key.name, key.distribution, key.version),
  ])
  return Response.redirect(new URL(`${prefix}/admin`, request.url), 303)
}

function activate(db: D1Database, artifacts: ArtifactInput[]) {
  return db.batch(
    artifacts.flatMap((artifact) => {
      const time = Date.now()
      return [
        deactivateStatement(db, artifact),
        db
          .prepare(
            `INSERT INTO artifact (channel, name, distribution, version, metadata, active, time_created, time_updated)
             VALUES (?, ?, ?, ?, ?, 1, ?, ?)
             ON CONFLICT (channel, name, distribution, version) DO UPDATE SET
               metadata = excluded.metadata, active = 1, time_updated = excluded.time_updated`,
          )
          .bind(
            artifact.channel,
            artifact.name,
            artifact.distribution,
            artifact.version,
            JSON.stringify(artifact.metadata),
            time,
            time,
          ),
      ]
    }),
  )
}

function deactivateStatement(db: D1Database, artifact: Pick<ArtifactInput, "channel" | "name" | "distribution">) {
  return db
    .prepare("UPDATE artifact SET active = 0 WHERE channel = ? AND name = ? AND distribution = ? AND active = 1")
    .bind(artifact.channel, artifact.name, artifact.distribution)
}

function parseArtifact(input: Record<string, unknown>): ArtifactInput | Response {
  const key = parseKey(input)
  if (key instanceof Response) return key
  const metadata = typeof input.metadata === "string" ? parseMetadata(input.metadata) : input.metadata
  if (metadata === undefined) return json({ error: "Metadata must be valid JSON" }, 400)
  return { ...key, metadata }
}

function parseKey(input: Record<string, unknown>): Omit<ArtifactInput, "metadata"> | Response {
  if (
    !validIdentifier(input.channel) ||
    input.channel === "next" ||
    !validIdentifier(input.name) ||
    !validIdentifier(input.distribution) ||
    !validVersion(input.version)
  )
    return json({ error: "Invalid artifact" }, 400)
  return {
    channel: input.channel,
    name: input.name,
    distribution: input.distribution,
    version: input.version,
  }
}

function decodeArtifact(row: ArtifactRow): Artifact {
  return { ...row, metadata: decodeMetadata(row.metadata), active: row.active === 1, minimum: row.minimum === 1 }
}

function decodeMetadata(input: string) {
  return parseMetadata(input) ?? null
}

function parseMetadata(input: string): unknown | undefined {
  try {
    return JSON.parse(input)
  } catch {
    return
  }
}

async function verifyGitHub(request: Request) {
  const authorization = request.headers.get("Authorization")
  if (!authorization?.startsWith("Bearer ")) return json({ error: "Unauthorized" }, 401)
  const result = await jwtVerify(authorization.slice("Bearer ".length), githubKeys, {
    issuer: "https://token.actions.githubusercontent.com",
    audience,
  }).catch(() => undefined)
  if (!result || !validGitHubClaims(result.payload)) return json({ error: "Unauthorized" }, 401)
  return result.payload
}

type GitHubClaims = JWTPayload & {
  repository: string
  repository_id: string
  repository_owner_id: string
  workflow_ref: string
  ref: string
  sha: string
  run_id: string
  run_attempt: string
  actor: string
}

export function validGitHubClaims(claims: JWTPayload): claims is GitHubClaims {
  if (claims.repository !== "anomalyco/opencode") return false
  if (claims.repository_id !== "975734319") return false
  if (claims.repository_owner_id !== "66570915") return false
  if (typeof claims.workflow_ref !== "string" || typeof claims.ref !== "string") return false
  if (claims.workflow_ref !== `anomalyco/opencode/.github/workflows/publish.yml@${claims.ref}`) return false
  if (!channelsForRef(claims.ref).length) return false
  return [claims.sha, claims.run_id, claims.run_attempt, claims.actor].every((value) => typeof value === "string")
}

export function channelsForRef(ref: string) {
  if (ref === "refs/heads/dev") return ["dev", "latest"]
  if (ref === "refs/heads/beta") return ["beta"]
  return []
}

export function resolveChannel(channel: string) {
  return channel === "next" ? "beta" : channel
}

function cachedRead<T>(key: string, load: () => Promise<T>) {
  const now = Date.now()
  const hit = reads.get(key)
  if (hit) {
    reads.delete(key)
    if (hit.expires > now) {
      reads.set(key, hit)
      return hit.value as Promise<T>
    }
  }
  // Lookup paths are caller-controlled identifiers, so bound the number of retained entries.
  if (reads.size >= 1_000) {
    reads.forEach((entry, k) => {
      if (entry.expires <= now) reads.delete(k)
    })
    if (reads.size >= 1_000) {
      const oldest = reads.keys().next().value
      if (oldest !== undefined) reads.delete(oldest)
    }
  }
  // Concurrent callers share one in-flight read. Failed reads are dropped so the next request retries D1.
  const value = load()
  reads.set(key, { expires: now + readTtl, value })
  value.catch(() => {
    if (reads.get(key)?.value === value) reads.delete(key)
  })
  return value
}

function validMutation(request: Request) {
  const origin = request.headers.get("Origin")
  if (origin && origin !== new URL(request.url).origin) return json({ error: "Invalid origin" }, 403)
}

function validIdentifier(input: unknown): input is string {
  return typeof input === "string" && identifier.test(input)
}

function validVersion(input: unknown): input is string {
  return typeof input === "string" && version.test(input)
}

function isRecord(input: unknown): input is Record<string, unknown> {
  return typeof input === "object" && input !== null && !Array.isArray(input)
}

function updateResponse(value: unknown) {
  return json(value, 200, { "Cache-Control": "no-store" })
}

function json(value: unknown, status = 200, headers?: HeadersInit) {
  return Response.json(value, { status, headers: { "Cache-Control": "no-store", ...headers } })
}

function escape(value: string) {
  return value.replace(/[&<>"']/g, (character) => {
    if (character === "&") return "&amp;"
    if (character === "<") return "&lt;"
    if (character === ">") return "&gt;"
    if (character === '"') return "&quot;"
    return "&#39;"
  })
}

import { Database } from "bun:sqlite"
import { afterEach, expect, setSystemTime, test } from "bun:test"
import { readdirSync, readFileSync } from "node:fs"
import path from "node:path"
import worker, { channelsForRef, validGitHubClaims } from "../src/index"

type Env = Parameters<typeof worker.fetch>[1]

const migrations = path.join(import.meta.dir, "../migrations")

afterEach(() => setSystemTime())

// Runs the real schema and queries through bun:sqlite and records every statement sent to D1.
function database() {
  const sqlite = new Database(":memory:")
  readdirSync(migrations)
    .sort()
    .forEach((file) => sqlite.exec(readFileSync(path.join(migrations, file), "utf8")))
  const queries: string[] = []
  const DB = {
    prepare: (sql: string) => ({
      bind: (...values: unknown[]) => ({
        first: async () => {
          queries.push(sql)
          return sqlite.query(sql).get(...(values as never[])) ?? null
        },
        all: async () => {
          queries.push(sql)
          return { results: sqlite.query(sql).all(...(values as never[])) }
        },
      }),
    }),
  }
  const env = { DB, EVENTS: { send: () => Promise.resolve() } } as unknown as Env
  const insert = (input: { channel: string; version: string; time: number; active?: boolean; minimum?: boolean }) =>
    sqlite
      .query(
        "INSERT INTO artifact (channel, name, distribution, version, metadata, active, minimum, time_created, time_updated) VALUES (?, 'cli', 'opencode', ?, '{}', ?, ?, ?, ?)",
      )
      .run(input.channel, input.version, input.active ? 1 : 0, input.minimum ? 1 : 0, input.time, input.time)
  return { sqlite, env, queries, insert }
}

function lookup(env: Env, pathname: string, headers?: HeadersInit) {
  return worker.fetch(new Request(`https://opencode.ai/update/api/${pathname}`, { headers }), env, {
    waitUntil: () => {},
  })
}

async function version(response: Response) {
  expect(response.status).toBe(200)
  const body = (await response.json()) as { version: string }
  return body.version
}

test("returns a retryable 503 when D1 rejects a lookup", async () => {
  const overloaded = new Error("D1_ERROR: D1 DB is overloaded. Requests queued for too long.")
  const env = {
    DB: { prepare: () => ({ bind: () => ({ first: () => Promise.reject(overloaded) }) }) },
    EVENTS: { send: () => Promise.resolve() },
  } as unknown as Env
  const response = await worker.fetch(
    new Request("https://opencode.ai/update/api/latest/desktop/opencode/opencode-desktop-win-x64.exe"),
    env,
    { waitUntil: () => {} },
  )
  expect(response.status).toBe(503)
  expect(response.headers.get("Retry-After")).toBe("60")
  expect(response.headers.get("Cache-Control")).toBe("no-store")
  expect(await response.json()).toEqual({ error: "Update service temporarily unavailable" })
})

test("reuses D1 reads across lookups for 1 minute", async () => {
  const db = database()
  db.insert({ channel: "reuse", version: "1.0.0", time: 1, active: true })
  setSystemTime(new Date("2026-10-13T00:00:00Z"))

  expect(
    await Promise.all([lookup(db.env, "reuse/cli/opencode"), lookup(db.env, "reuse/cli/opencode")]).then((responses) =>
      Promise.all(responses.map(version)),
    ),
  ).toEqual(["1.0.0", "1.0.0"])
  expect(db.queries).toHaveLength(2)

  db.sqlite.query("UPDATE artifact SET active = 0").run()
  db.insert({ channel: "reuse", version: "1.0.1", time: 2, active: true })
  setSystemTime(new Date("2026-10-13T00:00:59Z"))
  expect(await version(await lookup(db.env, "reuse/cli/opencode"))).toBe("1.0.0")
  expect(db.queries).toHaveLength(2)

  setSystemTime(new Date("2026-10-13T00:01:01Z"))
  expect(await version(await lookup(db.env, "reuse/cli/opencode"))).toBe("1.0.1")
  expect(db.queries).toHaveLength(4)
})

test("evicts stale and cold entries without clearing hot reads", async () => {
  const db = database()
  db.insert({ channel: "hot", version: "1.0.0", time: 1, active: true })
  setSystemTime(new Date("2026-10-13T01:00:00Z"))

  expect(await version(await lookup(db.env, "hot/cli/opencode"))).toBe("1.0.0")
  expect(db.queries).toHaveLength(2)

  for (let i = 0; i < 600; i++) {
    expect((await lookup(db.env, `cold-${i}/cli/opencode`)).status).toBe(404)
    expect(await version(await lookup(db.env, "hot/cli/opencode"))).toBe("1.0.0")
  }
  expect(db.queries).toHaveLength(1202)
})

test("retries D1 on the next lookup after a failed read", async () => {
  const db = database()
  db.insert({ channel: "retry", version: "1.0.0", time: 1, active: true })
  const prepare = db.env.DB.prepare
  let fail = true
  db.env.DB.prepare = ((sql: string) =>
    fail
      ? { bind: () => ({ first: () => Promise.reject(new Error("overloaded")) }) }
      : prepare.call(db.env.DB, sql)) as typeof prepare

  expect((await lookup(db.env, "retry/cli/opencode")).status).toBe(503)
  fail = false
  expect(await version(await lookup(db.env, "retry/cli/opencode"))).toBe("1.0.0")
})

test("selects the minimum and active artifacts from the partial indexes", async () => {
  const db = database()
  db.insert({ channel: "minimum", version: "1.0.0", time: 1, minimum: true })
  db.insert({ channel: "minimum", version: "1.5.0", time: 2 })
  db.insert({ channel: "minimum", version: "2.0.0", time: 3, active: true })

  expect(await version(await lookup(db.env, "minimum/cli/opencode?current=0.9.0"))).toBe("1.0.0")
  expect(await version(await lookup(db.env, "minimum/cli/opencode?current=1.0.0"))).toBe("2.0.0")
  expect(await version(await lookup(db.env, "minimum/cli/opencode"))).toBe("2.0.0")

  // A release that is both active and minimum is listed once.
  db.insert({ channel: "both", version: "3.0.0", time: 1, active: true, minimum: true })
  const response = await lookup(db.env, "both")
  expect(response.status).toBe(200)
  const body = (await response.json()) as { artifacts: { version: string }[] }
  expect(body.artifacts.map((artifact) => artifact.version)).toEqual(["3.0.0"])
})

test("caches rollout fallback reads across caller IPs and overlapping releases", async () => {
  const db = database()
  const base = Date.parse("2026-10-13T00:00:00Z")
  db.sqlite.query("INSERT INTO channel_rollout (channel, duration_hours) VALUES ('rollout', 6)").run()
  db.insert({ channel: "rollout", version: "1.0.0", time: base })
  db.insert({ channel: "rollout", version: "1.1.0", time: base + 5 * 3_600_000 })
  db.insert({ channel: "rollout", version: "1.2.0", time: base + 7 * 3_600_000, active: true })
  setSystemTime(new Date(base + 7 * 3_600_000 + 1_000))

  // Missing IP waits for full 6h rollout -> cutoff is base + 1h + 1s, selects 1.0.0.
  expect(await version(await lookup(db.env, "rollout/cli/opencode"))).toBe("1.0.0")
  expect(db.queries).toHaveLength(3)

  // Different caller IPs evaluate different cutoffs against the cached rollout history without extra D1 reads.
  const versions = await Promise.all(
    Array.from({ length: 20 }, (_, i) =>
      lookup(db.env, "rollout/cli/opencode", { "CF-Connecting-IP": `203.0.113.${i + 1}` }).then(version),
    ),
  )
  expect(new Set(versions)).toEqual(new Set(["1.0.0", "1.1.0"]))
