import cloudflare from "@astrojs/cloudflare"
import mdx from "@astrojs/mdx"
import { unified } from "@astrojs/markdown-remark"
import { defineConfig } from "astro/config"
import remarkDocsLinks from "./src/docs/remark-links"

const base = "/v2/"

export default defineConfig({
  site: process.env.CLOUDFLARE_ENV === "production" ? "https://opencode.ai" : "https://dev.opencode.ai",
  base,
  output: "server",
  adapter: cloudflare({ imageService: "passthrough" }),
  integrations: [mdx()],
  markdown: {
    processor: unified({ remarkPlugins: [[remarkDocsLinks, { base }]] }),
    shikiConfig: {
      themes: {
        light: "github-light",
        dark: "github-dark",
      },
      transformers: [
        {
          name: "code-block-title",
          root(root) {
            const title = this.options.meta?.__raw?.match(/title="([^"]+)"/)?.[1]
            if (!title) return
            const pre = root.children[0]
            if (!pre || pre.type !== "element") return
            root.children = [
              {
                type: "element",
                tagName: "figure",
                properties: { className: ["astro-code-figure"] },
                children: [
                  {
                    type: "element",
                    tagName: "figcaption",
                    properties: { className: ["astro-code-title"] },
                    children: [{ type: "text", value: title }],
                  },
                  pre,
                ],
              },
            ]
          },
        },
      ],
    },
  },
  vite: {
    server: {
      allowedHosts: true,
    },
  },
})

import { fileURLToPath } from "url"

const source = fileURLToPath(new URL("../../../packages/protocol/openapi.json", import.meta.url))
const targets = ["../openapi.json", "../public/openapi.json"].map((path) =>
  fileURLToPath(new URL(path, import.meta.url)),
)
const document = await Bun.file(source).text()

if (process.argv.includes("--check")) {
  const stale = (await Promise.all(targets.map((path) => Bun.file(path).text()))).some((value) => value !== document)
  if (stale) {
    console.error("Generated OpenAPI documents are stale. Run `bun run generate` from services/www.")
    process.exit(1)
  }
  process.exit(0)
}

await Promise.all(targets.map((path) => Bun.write(path, document)))

import path from "node:path"

const root = path.resolve(import.meta.dir, "../dist/client")
const externalRoutes = new Set(["/docs"])
const files = await Array.fromAsync(new Bun.Glob("**/*.html").scan({ cwd: root, absolute: true }))
const failures = (
  await Promise.all(
    files.flatMap(async (file) => {
      const html = await Bun.file(file).text()
      const page = `https://opencode.local/${path.relative(root, file).replace(/index\.html$/, "")}`
      return Promise.all(
        Array.from(html.matchAll(/href="([^"]+)"/g), async (match) => {
          const url = new URL(match[1], page)
          if (url.origin !== "https://opencode.local") return
          if (externalRoutes.has(url.pathname)) return

          const targetPath = path.join(root, decodeURIComponent(url.pathname))
          const target = (
            await Promise.all(
              [targetPath, path.join(targetPath, "index.html"), `${targetPath}.html`].map(async (candidate) =>
                (await Bun.file(candidate).exists()) ? candidate : undefined,
              ),
            )
          ).find((candidate) => candidate !== undefined)
          if (!target) return `${path.relative(root, file)}: missing ${url.pathname}`
          if (!url.hash || !target.endsWith(".html")) return

          const id = decodeURIComponent(url.hash.slice(1))
          if ((await Bun.file(target).text()).includes(`id="${id}"`)) return
          return `${path.relative(root, file)}: missing ${url.pathname}${url.hash}`
        }),
      )
    }),
  )
)
  .flat(2)
  .filter((failure) => failure !== undefined)

if (failures.length === 0) process.exit(0)
console.error([...new Set(failures)].sort().join("\n"))
process.exit(1)

import { docsSections } from "./navigation"

export function renderLlmsTxt(site: URL) {
  const base = new URL(import.meta.env.BASE_URL, site)
  const sections = docsSections.flatMap((section) => [
    `## ${section.title}`,
    "",
    ...section.groups.flatMap((group) => [
      ...(group.title && group.title !== section.title ? [`### ${group.title}`, ""] : []),
      ...group.items.map((item) => {
        const path = item.slug === "index" ? "" : `${item.slug.replace(/\/index$/, "")}/`
        return `- [${item.title}](${new URL(`docs/${path}`, base)})`
      }),
      "",
    ]),
  ])

  return [
    "# OpenCode V2 Documentation",
    "",
    "> Official documentation for using, configuring, and building with OpenCode V2.",
    "",
    ...sections,
  ].join("\n")
}

